import { handleFreemiumLimitError } from "@/features/billing/store/upgradeWallStore";
import type { DataSourceGroupFilter, DemoSourcePreset } from "@/features/data-sources/types";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { BaseClient } from "@/shared/lib/BaseClient";
import { HttpService } from "@/shared/services/httpService";

export interface UploadFileResult {
  filePath: string;
  fileName: string;
  fileSize: number;
  /** True when the upload overwrote a file that already existed at that path. */
  replacedExisting: boolean;
  /** Connected data sources whose stored schema was re-inferred from the new file. */
  resyncedDataSources: string[];
}

/**
 * Client specifically for data operations, decoupled from Knowledge Graph
 */
export class DataClient extends BaseClient {
  /**
   * Load data sources for a workspace
   */
  async loadDataSources(ontologyScope: string = "user"): Promise<any> {
    try {
      const url = `/data/list?scope=${ontologyScope}`;

      const response = await HttpService.get(
        `${PROMETHEUX_CONFIG.BASE_URL}${url}`,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      return response;
    } catch (error) {
      throw error;
    }
  }

  /**
   * Delete specific data sources
   */
  async deleteDataSources(sourceIds: string[], ontologyScope: string = "user"): Promise<any> {
    try {
      const payload = {
        project: {
          scope: ontologyScope,
        },
        source_ids: sourceIds,
      };

      const response = await this.post(`/data/cleanup`, payload);

      return response;
    } catch (error) {
      throw error;
    }
  }

  /**
   * List sheet names for an Excel workbook.
   */
  async listSheets(databaseConfig: Record<string, unknown>): Promise<string[]> {
    const payload = { database: databaseConfig };
    const response = await this.post(`/data/list-sheets`, payload);
    return response?.data?.sheets ?? [];
  }

  /**
   * Connect to a data source
   */
  async connectDataSource(databaseConfig: any): Promise<any> {
    try {
      // Extract computeRowCount from databaseConfig and remove it
      const { computeRowCount, ...databaseConfigWithoutComputeRowCount } = databaseConfig;

      const payload = {
        database: databaseConfigWithoutComputeRowCount,
        computeRowCount: computeRowCount || false,
      };

      const response = await this.post(`/data/connect`, payload);

      return response;
    } catch (error) {
      // Freemium own-connection cap (402): open the upgrade wall from the single
      // connect choke point so every entry point surfaces it uniformly. Rethrow
      // so callers still see the failure.
      handleFreemiumLimitError(error);
      throw error;
    }
  }

  /**
   * List the Prometheux (px) datasources offered during onboarding, including
   * each preset's connection config used to pre-populate the connection form.
   */
  async loadDemoSources(): Promise<DemoSourcePreset[]> {
    const response = await this.get(`/data/demo-sources`);
    return response?.data ?? [];
  }

  /**
   * Refresh data sources by re-connecting each group and reconciling the list.
   * Databases are re-scanned for table changes; missing files are removed.
   */
  async refreshDataSources(ontologyScope: string = "user"): Promise<any> {
    try {
      const payload = { scope: ontologyScope };
      const response = await this.post(`/data/refresh`, payload);
      return response;
    } catch (error) {
      throw error;
    }
  }

  /**
   * Refresh a specific database connection group.
   * Only entries matching the filter are re-connected; other groups are
   * left untouched.
   */
  async refreshDataSourceGroup(
    groupFilter: DataSourceGroupFilter,
    ontologyScope: string = "user",
  ): Promise<any> {
    try {
      const payload = { scope: ontologyScope, group_filter: groupFilter };
      const response = await this.post(`/data/refresh`, payload);
      return response;
    } catch (error) {
      throw error;
    }
  }

  /**
   * Preview the first N records of a data source
   */
  async previewDataSource(
    bindAnnotation: string,
    scope: string = "user",
    limit: number = 10,
    compute?: any,
    page?: number,
    pageSize?: number,
    orderBy?: Array<{ position: number; direction: "asc" | "desc" }>,
    searchTerm?: string,
    columnFilters?: Array<{ position: number; value: string; operator?: string }>,
  ): Promise<any> {
    try {
      const payload: any = {
        bind_annotation: bindAnnotation,
        scope,
        limit,
      };
      if (page !== undefined) payload.page = page;
      if (pageSize !== undefined) payload.page_size = pageSize;
      if (compute) payload.compute = compute;
      if (orderBy?.length) payload.order_by = orderBy;
      if (searchTerm) payload.search_term = searchTerm;
      if (columnFilters?.length) payload.column_filters = columnFilters;

      const response = await this.post(`/data/preview`, payload);
      return response;
    } catch (error) {
      throw error;
    }
  }

  /**
   * Upload a file to the server's disk storage
   * @param file The file to upload
   * @param path Optional subdirectory path within disk/
   * @param onProgress Optional callback for upload progress (0-100)
   * @returns Object containing filePath, fileName, and fileSize
   */
  async uploadFile(
    file: File,
    path: string = "",
    onProgress?: (progress: number) => void,
  ): Promise<UploadFileResult> {
    const formData = new FormData();
    if (path) {
      formData.append("path", path);
    }
    return this.sendUpload(file, formData, onProgress);
  }

  /**
   * Upload a file attached to an AI assistant chat.
   * @param file The file to upload
   * @param chatSessionId The chat the file belongs to
   * @param onProgress Optional callback for upload progress (0-100)
   * @returns Object containing filePath, fileName, and fileSize
   */
  async uploadChatAttachment(
    file: File,
    chatSessionId: string,
    onProgress?: (progress: number) => void,
  ): Promise<UploadFileResult> {
    const formData = new FormData();
    formData.append("chat_session_id", chatSessionId);
    return this.sendUpload(file, formData, onProgress);
  }

  private async sendUpload(
    file: File,
    formData: FormData,
    onProgress?: (progress: number) => void,
  ): Promise<UploadFileResult> {
    try {
      formData.append("file", file);

      const response = await this.uploadMultipart("/data/files/upload", formData, onProgress);

      // Handle response format from backend
      if (response && response.status === "success" && response.data) {
        return {
          filePath: response.data.filePath,
          fileName: response.data.fileName,
          fileSize: response.data.fileSize,
          replacedExisting: response.data.replacedExisting ?? false,
          resyncedDataSources: response.data.resyncedDataSources ?? [],
        };
      } else if (response && response.filePath) {
        // Direct response format
        return {
          filePath: response.filePath,
          fileName: response.fileName,
          fileSize: response.fileSize,
          replacedExisting: response.replacedExisting ?? false,
          resyncedDataSources: response.resyncedDataSources ?? [],
        };
      } else {
        throw new Error(response?.message || "Upload failed: unexpected response format");
      }
    } catch (error) {
      // Freemium storage cap (402): open the upgrade wall from the single upload
      // choke point so every entry point (data browser, onboarding, chat
      // attachments) surfaces it uniformly. Rethrow so callers still see failure.
      handleFreemiumLimitError(error);
      throw error;
    }
  }
}
