import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpError, HttpService } from "@/shared/services/httpService";
import { NotificationError, type NotificationsPayload, type NotificationType } from "./types";

// Same auth shape as the teams/share endpoints: Prometheux bearer token +
// the Supabase JWT (so RLS scopes the underlying share/invite reads).
const SUPABASE_TOKEN_HEADER = "X-Supabase-Token";

const notificationsUrl = (suffix = ""): string =>
  `${PROMETHEUX_CONFIG.BASE_URL}/notifications${suffix ? `/${suffix}` : ""}`;

function authHeaders(supabaseToken: string | null): Record<string, string> | undefined {
  if (!supabaseToken) return undefined;
  return { [SUPABASE_TOKEN_HEADER]: supabaseToken };
}

interface ApiEnvelope<T> {
  status: string;
  message: string;
  data: T;
}

function isEnvelope<T>(value: unknown): value is ApiEnvelope<T> {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v.status === "string" && typeof v.message === "string";
}

function extractDetail(body: unknown): string | null {
  if (typeof body !== "object" || body === null) return null;
  const v = body as Record<string, unknown>;
  return typeof v.detail === "string" ? v.detail : null;
}

function unwrap<T>(response: unknown, action: string): T {
  if (!isEnvelope<T>(response)) {
    throw new NotificationError(`Unexpected response while ${action}.`, 500);
  }
  if (response.status === "success") return response.data;
  throw new NotificationError(response.message || `Failed to ${action}.`, 400);
}

async function call<T>(action: string, fn: () => Promise<unknown>): Promise<T> {
  try {
    return unwrap<T>(await fn(), action);
  } catch (err) {
    if (err instanceof NotificationError) throw err;
    if (err instanceof HttpError) {
      throw new NotificationError(
        extractDetail(err.body) ?? err.message ?? `Failed to ${action}.`,
        err.status,
      );
    }
    const message = err instanceof Error ? err.message : `Failed to ${action}.`;
    throw new NotificationError(message, 0);
  }
}

export function listNotifications(supabaseToken: string | null): Promise<NotificationsPayload> {
  return call<NotificationsPayload>("load notifications", () =>
    HttpService.get(notificationsUrl(), PROMETHEUX_CONFIG.AUTH_TOKEN, authHeaders(supabaseToken)),
  );
}

export function markAllNotificationsRead(
  supabaseToken: string | null,
): Promise<{ marked: number; unread_count: number }> {
  return call("mark notifications read", () =>
    HttpService.post(
      notificationsUrl("read-all"),
      {},
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

export function markNotificationRead(
  type: NotificationType,
  entityId: string,
  supabaseToken: string | null,
): Promise<{ id: string; read: boolean }> {
  return call("mark notification read", () =>
    HttpService.post(
      notificationsUrl(`${type}/${entityId}/read`),
      {},
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}
