import type { ChangeEvent, Dispatch, SetStateAction } from "react";
import { useCallback, useRef, useState } from "react";
import { toast } from "sonner";
import { OntologySchemaService } from "@/features/ontology-schema/api";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";
import { applyLayout } from "../graph.utils";
import type { GraphState } from "../types";

interface UseOwlImportParams {
  ontologyId: string;
  ontologyScope: string;
  setGraphState: Dispatch<SetStateAction<GraphState>>;
  refreshGraphFromBackend: () => Promise<void>;
}

/**
 * Owns OWL file import: importing an .owl into the graph for visualization, and
 * translating an .owl to Vadalog. Extracted from OntologySchemaEditor.
 */
export function useOwlImport({
  ontologyId,
  ontologyScope,
  setGraphState,
  refreshGraphFromBackend,
}: UseOwlImportParams) {
  const [isImporting, setIsImporting] = useState(false);
  const [isImportingVadalog, setIsImportingVadalog] = useState(false);
  const [isVadalogConfigDialogOpen, setIsVadalogConfigDialogOpen] = useState(false);
  const [includeImportedOntologies, setIncludeImportedOntologies] = useState(false);
  const [fileInputKey, setFileInputKey] = useState(Date.now()); // Force fresh file reads
  const fileInputRef = useRef<HTMLInputElement>(null);
  const fileInputVadalogRef = useRef<HTMLInputElement>(null);

  // OWL Import handler
  const handleOwlImport = useCallback(
    async (event: ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;

      if (!file.name.endsWith(".owl")) {
        toast.error("Please select an OWL file (.owl extension)");
        return;
      }

      setIsImporting(true);

      try {
        const fileContent = await file.text();

        // Call API to convert OWL to ontology JSON using HttpService
        const url = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/import-owl`;
        const payload = {
          owl_content: fileContent,
          // base_namespace is optional - will be auto-detected
        };

        const result = await HttpService.post(url, payload);

        if (result.status === "success" && result.data?.ontology_schema_data) {
          const { nodes, edges } = result.data.ontology_schema_data;

          // Apply layout to imported nodes
          const layoutedNodes = applyLayout(nodes, edges);

          const newGraphState = {
            nodes: layoutedNodes,
            edges: edges,
          };

          setGraphState(newGraphState);

          // Auto-save the imported ontology with the new state
          setTimeout(async () => {
            try {
              await OntologySchemaService.saveGraph(ontologyId, newGraphState, ontologyScope);
              await refreshGraphFromBackend();
            } catch (error) {
              console.error("Auto-save failed after import:", error);
            }
          }, 500);
        } else {
          throw new Error(result.message || "Invalid response format");
        }
      } catch (error) {
        console.error("Error importing OWL:", error);
        toast.error(
          `Failed to import OWL: ${error instanceof Error ? error.message : "Unknown error"}`,
        );
      } finally {
        setIsImporting(false);
        // Reset file input by changing key to force fresh reads
        setFileInputKey(Date.now());
      }
    },
    [ontologyId, ontologyScope, refreshGraphFromBackend, setGraphState],
  );

  // OWL to Vadalog Import handler - generates .vada file and CSVs to disk/owl
  const handleOwlToVadalogImport = useCallback(
    async (event: ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;

      if (!file.name.endsWith(".owl")) {
        toast.error("Please select an OWL file (.owl extension)");
        return;
      }

      setIsImportingVadalog(true);

      try {
        const fileContent = await file.text();

        // Auto-detect base namespace from OWL content
        // Look for xml:base or ontology IRI patterns
        let baseNamespace = "";
        const xmlBaseMatch = fileContent.match(/xml:base="([^"]+)"/);
        const ontologyIriMatch = fileContent.match(/rdf:about="([^"]+)"[^>]*>/);
        const owlOntologyMatch = fileContent.match(/<owl:Ontology[^>]*rdf:about="([^"]+)"/);

        if (owlOntologyMatch) {
          baseNamespace = owlOntologyMatch[1];
        } else if (xmlBaseMatch) {
          baseNamespace = xmlBaseMatch[1];
        } else if (ontologyIriMatch) {
          baseNamespace = ontologyIriMatch[1];
        }

        if (!baseNamespace) {
          toast.error(
            "Could not auto-detect base namespace from OWL file. Please ensure the file contains a valid ontology IRI.",
          );
          return;
        }

        // First, import for visualization
        try {
          const visualUrl = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/import-owl`;
          const visualPayload = {
            owl_content: fileContent,
          };

          const visualResult = await HttpService.post(visualUrl, visualPayload);

          if (visualResult.status === "success" && visualResult.data?.ontology_schema_data) {
            const { nodes, edges } = visualResult.data.ontology_schema_data;

            // Apply layout to imported nodes
            const layoutedNodes = applyLayout(nodes, edges);

            const newGraphState = {
              nodes: layoutedNodes,
              edges: edges,
            };

            setGraphState(newGraphState);

            // Auto-save the imported ontology with the new state
            setTimeout(async () => {
              try {
                await OntologySchemaService.saveGraph(ontologyId, newGraphState, ontologyScope);
                await refreshGraphFromBackend();
              } catch (error) {
                console.error("Auto-save failed after import:", error);
              }
            }, 500);
          }
        } catch (error) {
          console.error("Error importing OWL for visualization:", error);
          // Continue with Vadalog translation even if visualization fails
        }

        // Then, call API to convert OWL to Vadalog
        const url = `${PROMETHEUX_CONFIG.BASE_URL}/vadalingo/${ontologyId}/translate/owl-to-vadalog`;
        const payload = {
          owl_content: fileContent,
          base_namespace: baseNamespace,
          data_base_path: "owl",
          add_concepts: true,
          options: {
            include_imports: includeImportedOntologies, // Process imported ontologies based on user selection
            include_schema: false, // Don't include schema documentation
          },
        };

        const result = await HttpService.post(url, payload);

        if (result.status === "success" && result.data) {
          const message = `OWL translated to Vadalog successfully`;
          toast.success(message);
        } else {
          throw new Error(result.message || "Invalid response format");
        }
      } catch (error) {
        console.error("Error converting OWL to Vadalog:", error);
        toast.error(
          `Failed to convert OWL to Vadalog: ${error instanceof Error ? error.message : "Unknown error"}`,
        );
      } finally {
        setIsImportingVadalog(false);
        // Reset file input by changing key to force fresh reads
        setFileInputKey(Date.now());
      }
    },
    [ontologyId, includeImportedOntologies, ontologyScope, refreshGraphFromBackend, setGraphState],
  );

  const handleSelectOwlVadalogFile = () => {
    setIsVadalogConfigDialogOpen(false);
    fileInputVadalogRef.current?.click();
  };

  return {
    isImporting,
    isImportingVadalog,
    isVadalogConfigDialogOpen,
    setIsVadalogConfigDialogOpen,
    includeImportedOntologies,
    setIncludeImportedOntologies,
    fileInputKey,
    fileInputRef,
    fileInputVadalogRef,
    handleOwlImport,
    handleOwlToVadalogImport,
    handleSelectOwlVadalogFile,
  };
}
