import { create } from "zustand";

export type RunLimitKind = "timeout" | "rows";

interface RunLimitInfo {
  kind: RunLimitKind;
  limit: number | null;
  message: string;
}

interface RunLimitState {
  isOpen: boolean;
  info: RunLimitInfo | null;
  openRunLimitDialog: (info: RunLimitInfo) => void;
  closeRunLimitDialog: () => void;
}

/**
 * Shared open flag for the freemium per-run ceiling dialog. Store-driven (not
 * prop-driven) so the run handler can trigger it from the editor hook without
 * prop drilling — mirrors the agent-message limit dialog wiring.
 */
export const useRunLimitStore = create<RunLimitState>((set) => ({
  isOpen: false,
  info: null,
  openRunLimitDialog: (info) => set({ isOpen: true, info }),
  closeRunLimitDialog: () => set({ isOpen: false }),
}));
