import { useState } from "react";

import type { MessageAttachment } from "../attachments.types";
import { AttachmentLightbox } from "./AttachmentLightbox";
import { MessageAttachmentChip } from "./MessageAttachmentChip";

interface MessageAttachmentChipsProps {
  attachments: MessageAttachment[];
}

/**
 * Files that rode along with a sent user turn: images as thumbnails, anything
 * else as a compact named chip. Clicking opens an image full size, or downloads
 * any other file.
 */
export function MessageAttachmentChips({ attachments }: MessageAttachmentChipsProps) {
  const [openImage, setOpenImage] = useState<MessageAttachment | null>(null);

  if (attachments.length === 0) return null;

  const handleClose = () => setOpenImage(null);

  return (
    <>
      <ul className="flex flex-wrap justify-end gap-1.5">
        {attachments.map((attachment) => (
          <MessageAttachmentChip
            key={`${attachment.path ?? ""}-${attachment.name}`}
            attachment={attachment}
            onOpenImage={setOpenImage}
          />
        ))}
      </ul>
      <AttachmentLightbox attachment={openImage} onClose={handleClose} />
    </>
  );
}
