import { useQuery, useQueryClient } from "@tanstack/react-query";
import { ArrowLeft } from "lucide-react";
import { useCallback, useMemo, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { toast } from "sonner";
import { type OntologyData, OntologyService } from "@/features/ontologies/api";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import { Button } from "@/shared/components/ui/button";
import { DashboardClient } from "../../api/DashboardClient";
import { DashboardCanvas } from "../../components/DashboardCanvas";
import { AppEditor } from "../../components/editor/AppEditor";
import { NewAppSetup } from "../../components/editor/NewAppSetup";
import type { AppDefinition } from "../../schema/appDefinition.types";
import {
  createEmptyAppDefinition,
  isV2Authorable,
  migrateDefinition,
} from "../../schema/migrateDefinition";
import type { DashboardDefinition } from "../../types";

const client = new DashboardClient();

interface NewAppDraft {
  definition: AppDefinition;
  ontologyId: string;
}

export function DashboardEditContent() {
  const { ontologyId, id } = useParams<{ ontologyId?: string; id?: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const isNew = !ontologyId && !id;
  const [newApp, setNewApp] = useState<NewAppDraft | null>(null);

  const { data: projects = [] } = useQuery<OntologyData[]>({
    queryKey: ["dashboard-projects"],
    queryFn: () => OntologyService.listOntologies(["user", "organization"]),
  });

  const { data: dashboard = null } = useQuery<DashboardDefinition | null>({
    queryKey: ["dashboard", ontologyId, id],
    queryFn: () => client.getDashboard(ontologyId!, id!),
    enabled: !isNew && !!ontologyId && !!id,
  });

  // The v2 editor owns everything except documents carrying legacy machinery
  // (input concept, index-bound widgets) — those keep the v0 canvas. Memoized:
  // the editor initializes its draft from this object once per mount.
  const appDefinition = useMemo(() => {
    const migrated = dashboard ? migrateDefinition(dashboard) : null;
    return migrated && isV2Authorable(migrated) ? migrated : null;
  }, [dashboard]);

  const handleCreateNewApp = useCallback((name: string, homeOntologyId: string) => {
    setNewApp({
      definition: createEmptyAppDefinition(name, homeOntologyId),
      ontologyId: homeOntologyId,
    });
  }, []);

  const handleSave = useCallback(
    async (def: DashboardDefinition) => {
      try {
        await client.saveDashboard(def.ontologyId, def);
        queryClient.invalidateQueries({ queryKey: ["all-dashboards"] });
        queryClient.invalidateQueries({ queryKey: ["dashboard", def.ontologyId, def.id] });
        queryClient.invalidateQueries({ queryKey: ["dashboard-record", def.ontologyId, def.id] });
        navigate("/apps");
      } catch {
        toast.error("Failed to save the app");
      }
    },
    [navigate, queryClient],
  );

  const handleDelete = useCallback(
    async (defId: string) => {
      if (!ontologyId) return;
      try {
        await client.deleteDashboard(ontologyId, defId);
        queryClient.invalidateQueries({ queryKey: ["all-dashboards"] });
        queryClient.removeQueries({ queryKey: ["dashboard", ontologyId, defId] });
        navigate("/apps");
      } catch {
        toast.error("Failed to delete the app");
      }
    },
    [ontologyId, navigate, queryClient],
  );

  const title = isNew ? (newApp?.definition.name ?? "New app") : (dashboard?.name ?? "Edit app");

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <PageHeader
        left={
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => navigate("/apps")}
              className="gap-1.5 text-muted-foreground h-7 px-2"
            >
              <ArrowLeft className="h-3.5 w-3.5" />
              Apps
            </Button>
            <span className="text-muted-foreground/40 text-sm">/</span>
            <span className="text-sm font-medium">{title}</span>
          </div>
        }
      />

      <div className="flex-1 overflow-hidden flex flex-col">{renderEditor()}</div>
    </div>
  );

  function renderEditor() {
    if (isNew) {
      if (!newApp) return <NewAppSetup projects={projects} onCreate={handleCreateNewApp} />;
      return (
        <AppEditor
          key={newApp.definition.id}
          definition={newApp.definition}
          storageOntologyId={newApp.ontologyId}
        />
      );
    }
    if (appDefinition) {
      return <AppEditor key={id} definition={appDefinition} storageOntologyId={ontologyId ?? ""} />;
    }
    return (
      <DashboardCanvas
        key={id}
        dashboard={dashboard}
        projects={projects}
        onSave={handleSave}
        onDelete={handleDelete}
      />
    );
  }
}
