import { Info } from "lucide-react";

import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";

interface InfoHintProps {
  /** Accessible name for the icon button. */
  label?: string;
  /** Which side the tooltip opens on. */
  side?: "top" | "bottom" | "left" | "right";
  children: React.ReactNode;
}

/** Small ⓘ icon that explains the surrounding UI on hover. */
export function InfoHint({ label = "More information", side = "bottom", children }: InfoHintProps) {
  return (
    <Tooltip delayDuration={150}>
      <TooltipTrigger asChild>
        <button
          type="button"
          aria-label={label}
          className="inline-flex shrink-0 cursor-help text-muted-foreground/60 transition-colors hover:text-foreground"
        >
          <Info className="h-3.5 w-3.5" />
        </button>
      </TooltipTrigger>
      <TooltipContent
        side={side}
        className="max-w-xs space-y-1.5 font-sans text-xs font-normal normal-case tracking-normal leading-relaxed"
      >
        {children}
      </TooltipContent>
    </Tooltip>
  );
}
