import { useState } from "react";
import { cn } from "@/shared/lib/utils";
import type { FetchResult } from "../api/ConceptClient";
import type { DashboardDefinition } from "../types";
import type { DashboardTableHandlers } from "./outputs/table/tableOutput.types";
import { SectionView } from "./renderer/SectionView";

interface DashboardRendererProps {
  dashboard: DashboardDefinition;
  data: Record<string, FetchResult | null>;
  loadingConcepts: Record<string, boolean>;
  errorConcepts: Record<string, string>;
  hideHeader?: boolean;
  tableHandlers?: DashboardTableHandlers;
}

function countTotalWidgets(pages: DashboardDefinition["pages"]): number {
  return pages.reduce(
    (sum, page) => sum + page.sections.reduce((s, section) => s + section.widgets.length, 0),
    0,
  );
}

export function DashboardRenderer({
  dashboard,
  data,
  loadingConcepts,
  errorConcepts,
  hideHeader = false,
  tableHandlers,
}: DashboardRendererProps) {
  const [activePage, setActivePage] = useState(dashboard.pages[0]?.id ?? "");
  const currentPage = dashboard.pages.find((p) => p.id === activePage);
  const { pages } = dashboard;
  const header = dashboard.header ?? { title: dashboard.name };
  const isSingleWidget = countTotalWidgets(dashboard.pages) === 1;

  return (
    <div className="flex flex-col h-full overflow-hidden bg-background">
      {/* ── Header ── */}
      {!hideHeader && (
        <header className="bg-card border-b border-border px-8 h-14 flex items-center justify-between flex-shrink-0 sticky top-0 z-10">
          <div className="flex items-center gap-5 min-w-0">
            {header.logoUrl && (
              <>
                <img src={header.logoUrl} alt="Logo" className="h-[22px] w-auto flex-shrink-0" />
                <div className="w-px h-5 bg-border flex-shrink-0" />
              </>
            )}
            <div className="min-w-0 overflow-hidden">
              <div className="text-[13px] font-medium text-foreground/80 leading-tight truncate">
                {header.title || "App"}
              </div>
              {header.subtitle && (
                <div className="text-[11px] font-mono text-muted-foreground mt-px truncate">
                  {header.subtitle}
                </div>
              )}
            </div>
          </div>

          <div className="flex items-center gap-3 flex-shrink-0">
            {header.showStatus && (
              <div
                className="w-[7px] h-[7px] rounded-full bg-green-500"
                style={{ boxShadow: "0 0 0 2px rgb(240 253 244)" }}
              />
            )}
            {header.tags?.map((tag, i) => (
              <span
                key={i}
                className="text-[11px] font-mono text-muted-foreground bg-secondary border border-border px-2.5 py-[3px] rounded"
              >
                {tag}
              </span>
            ))}
          </div>
        </header>
      )}

      {/* ── Tab bar ── */}
      {pages.length > 1 && (
        <div className="bg-card border-b border-border px-8 flex flex-shrink-0">
          {pages.map((page) => (
            <button
              key={page.id}
              type="button"
              onClick={() => setActivePage(page.id)}
              className={cn(
                "px-[18px] py-3 text-[12px] font-medium border-b-2 -mb-px transition-all duration-150 whitespace-nowrap",
                page.id === activePage
                  ? "text-foreground border-foreground"
                  : "text-muted-foreground border-transparent hover:text-foreground/70",
              )}
            >
              {page.label}
            </button>
          ))}
        </div>
      )}

      {/* ── Page body ── */}
      <div
        className={
          isSingleWidget
            ? "flex-1 overflow-hidden flex flex-col min-h-0"
            : "flex-1 overflow-auto px-8 py-7 flex flex-col gap-5"
        }
      >
        {currentPage ? (
          currentPage.sections.map((section) => (
            <SectionView
              key={section.id}
              section={section}
              data={data}
              loading={loadingConcepts}
              errors={errorConcepts}
              tableHandlers={tableHandlers}
              fullscreen={isSingleWidget}
              ontologyId={dashboard.ontologyId}
            />
          ))
        ) : (
          <p className="text-sm text-muted-foreground">No pages configured.</p>
        )}
      </div>
    </div>
  );
}
