import { useState } from "react";
import { useAuthHandlers } from "@/features/auth/hooks/useAuthHandlers";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";

interface AuthFormProps {
  isSignUp: boolean;
  onToggleMode: () => void;
}

export const AuthForm = ({ isSignUp, onToggleMode }: AuthFormProps) => {
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");

  const {
    handleEmailLogin,
    handleGoogleLogin,
    handleMicrosoftLogin,
    handleMagicLinkLogin,
    handleResendConfirmation,
    isLoading,
    rateLimitTimer,
    resendRateLimitTimer,
    needsEmailConfirmation,
  } = useAuthHandlers(identifier, password, isSignUp);

  const handleMagicLinkClick = (e: React.MouseEvent) => {
    e.preventDefault();
    if (identifier?.includes("@")) {
      handleMagicLinkLogin(identifier);
    } else {
      alert("Please enter a valid email address");
    }
  };

  return (
    <div className="space-y-4">
      <form onSubmit={handleEmailLogin} className="space-y-4">
        <Input
          type="text"
          placeholder={isSignUp ? "Email address*" : "Username or email*"}
          value={identifier}
          onChange={(e) => setIdentifier(e.target.value)}
          className="bg-[#F5F7FB]"
          required
          disabled={isLoading || rateLimitTimer > 0}
        />
        <Input
          type="password"
          placeholder="Password*"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="bg-[#F5F7FB]"
          required
          disabled={isLoading || rateLimitTimer > 0}
        />
        {(rateLimitTimer > 0 || resendRateLimitTimer > 0) && (
          <div className="text-sm text-orange-500 text-center">
            {rateLimitTimer > 0 && `Please wait ${rateLimitTimer} seconds before trying again`}
            {resendRateLimitTimer > 0 &&
              `Please wait ${resendRateLimitTimer} seconds before requesting another confirmation email`}
          </div>
        )}

        <Button
          type="submit"
          className="w-full bg-[#29CC7A] hover:bg-[#25B86E]"
          disabled={isLoading || rateLimitTimer > 0}
        >
          {isLoading ? "Please wait..." : isSignUp ? "Sign Up" : "Continue"}
        </Button>
      </form>

      <div className="text-center space-y-2">
        <div className="text-sm">
          {isSignUp ? "Already have an account? " : "Don't have an account? "}
          <button
            onClick={onToggleMode}
            className="text-[#29CC7A] hover:underline"
            disabled={isLoading || rateLimitTimer > 0}
          >
            {isSignUp ? "Log In" : "Sign Up"}
          </button>
        </div>
        {!isSignUp && (
          <div className="text-sm space-y-1">
            <div className="flex justify-center gap-3">
              <a href="/reset-password" className="text-[#29CC7A] hover:underline">
                Forgot password?
              </a>
              <span className="text-gray-300">|</span>
              <button
                type="button"
                onClick={handleMagicLinkClick}
                disabled={isLoading}
                className="text-[#29CC7A] hover:underline disabled:opacity-50"
              >
                Send magic link
              </button>
            </div>
            {needsEmailConfirmation && identifier.includes("@") && (
              <div>
                <button
                  type="button"
                  onClick={handleResendConfirmation}
                  disabled={isLoading || resendRateLimitTimer > 0}
                  className="text-xs text-gray-500 hover:text-[#29CC7A] hover:underline disabled:opacity-50 transition-colors"
                >
                  Resend confirmation email
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};
