/**
 * Derive a short, human-readable detail for a tool-activity row from the tool's
 * streamed `input`. Generic on purpose: we surface identifier-like fields the
 * backend already sends (e.g. `skill_id` for `get_skill`) so a row can read
 * "get skill · design-ontology" instead of a bare "get skill".
 *
 * This never hardcodes skill names — it only echoes the id the backend streamed,
 * keeping `skills_loader` (jarvispy) the single source of truth.
 */
const DETAIL_KEYS = ["skill_id"] as const;

export function toolDetailFromInput(input: Record<string, unknown>): string | undefined {
  for (const key of DETAIL_KEYS) {
    const value = input[key];
    if (typeof value === "string" && value.trim() !== "") return value;
  }
  return undefined;
}
