import { Check, Pencil, RotateCcw, Trash2, X } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import type { MessageAttachment } from "../attachments.types";
import { formatMessageTime } from "../chatHistory.utils";
import { ConfirmDeleteDialog } from "./ConfirmDeleteDialog";
import { MessageAttachmentChips } from "./MessageAttachmentChips";

interface UserMessageBubbleProps {
  content: string;
  /** Files sent with this turn, shown as chips above the bubble. */
  attachments?: MessageAttachment[];
  /** ISO-8601 send time, revealed beside the bubble on hover. */
  createdAt?: string;
  /** Whether the edit/repeat affordances are available (live chat, not streaming). */
  canEdit: boolean;
  /**
   * Called with the text to (re-)run from this turn. Used for both saving an
   * edit (new text) and repeating (unchanged text) — the backend treats them
   * identically: truncate everything after this user turn and re-run.
   */
  onSubmitEdit: (newText: string) => void;
  /**
   * Discard this exchange — the message and the assistant's reply to it —
   * leaving the rest of the conversation alone.
   */
  onDelete: () => void;
  /** Bubble styling, so each chat keeps its own look. */
  bubbleClassName: string;
}

/**
 * A user chat bubble with an inline edit affordance. Hovering reveals a pencil
 * (when `canEdit`); editing swaps the bubble for a textarea with Save/Cancel.
 * Shared by both the docked assistant panel and the Home chat so the edit
 * behaviour lives in one place.
 */
export function UserMessageBubble({
  content,
  attachments,
  createdAt,
  canEdit,
  onSubmitEdit,
  onDelete,
  bubbleClassName,
}: UserMessageBubbleProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [draft, setDraft] = useState("");
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);

  const handleRequestDelete = () => setIsConfirmingDelete(true);

  const handleConfirmDelete = () => {
    setIsConfirmingDelete(false);
    onDelete();
  };

  const handleStartEdit = () => {
    setDraft(content);
    setIsEditing(true);
  };

  const handleRepeat = () => {
    if (!content) return;
    onSubmitEdit(content);
  };

  const handleCancel = () => {
    setIsEditing(false);
    setDraft("");
  };

  const handleSave = () => {
    const trimmed = draft.trim();
    if (!trimmed) return;
    setIsEditing(false);
    onSubmitEdit(trimmed);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSave();
    } else if (e.key === "Escape") {
      e.preventDefault();
      handleCancel();
    }
  };

  if (isEditing) {
    return (
      <div className="flex w-full max-w-[90%] flex-col gap-2">
        <textarea
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={handleKeyDown}
          rows={Math.min(8, Math.max(2, draft.split("\n").length))}
          className="w-full resize-none rounded-2xl border border-input bg-background px-4 py-2.5 text-sm leading-relaxed text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
        />
        <div className="flex justify-end gap-2">
          <Button type="button" size="sm" variant="ghost" onClick={handleCancel}>
            <X className="mr-1 h-3.5 w-3.5" />
            Cancel
          </Button>
          <Button type="button" size="sm" onClick={handleSave} disabled={!draft.trim()}>
            <Check className="mr-1 h-3.5 w-3.5" />
            Save &amp; send
          </Button>
        </div>
      </div>
    );
  }

  const editControls = canEdit ? (
    <div className="flex flex-shrink-0 items-center gap-0.5 opacity-0 transition-opacity group-hover:opacity-100">
      <button
        type="button"
        onClick={handleStartEdit}
        aria-label="Edit message"
        className="rounded-md p-1 text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
      >
        <Pencil className="h-3.5 w-3.5" />
      </button>
      <button
        type="button"
        onClick={handleRepeat}
        aria-label="Repeat message"
        className="rounded-md p-1 text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
      >
        <RotateCcw className="h-3.5 w-3.5" />
      </button>
      <button
        type="button"
        onClick={handleRequestDelete}
        aria-label="Delete message and its response"
        title="Delete this message and the reply to it"
        className="rounded-md p-1 text-muted-foreground transition-colors hover:bg-destructive/10 hover:text-destructive"
      >
        <Trash2 className="h-3.5 w-3.5" />
      </button>
    </div>
  ) : null;

  const sentAt = createdAt ? formatMessageTime(createdAt) : "";

  return (
    <div className="flex w-full flex-col items-end gap-1.5">
      {attachments && attachments.length > 0 && (
        <MessageAttachmentChips attachments={attachments} />
      )}
      {content && (
        <div className="group flex w-full items-center justify-end gap-1.5">
          {sentAt && (
            <time
              dateTime={createdAt}
              className="flex-shrink-0 text-[11px] text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100"
            >
              {sentAt}
            </time>
          )}
          {editControls}
          <div className={bubbleClassName}>{content}</div>
        </div>
      )}
      <ConfirmDeleteDialog
        open={isConfirmingDelete}
        onOpenChange={setIsConfirmingDelete}
        onConfirm={handleConfirmDelete}
        title="Delete the message"
        description="Are you sure you want to delete this message and the reply to it? It cannot be undone."
      />
    </div>
  );
}
