import type React from "react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { flushSync } from "react-dom";
import { toast } from "sonner";
import type { SaveCellHandler } from "@/features/concept-editor/components/query/types/editorTypes";
import type { ConceptCell } from "@/features/concept-editor/types";
import { APP_EVENTS } from "@/shared/constants/events";

/**
 * Sentinel group value used by the backend for cells with no group. A cell
 * with `group === UNGROUPED` is rendered at the root of the explorer tree.
 */
export const UNGROUPED = "group_id";

export type GroupDialogMode = "create" | "rename" | "assign";

interface GroupDialogState {
  open: boolean;
  mode: GroupDialogMode;
  editingGroupName: string | null;
}

const INITIAL_GROUP_DIALOG: GroupDialogState = {
  open: false,
  mode: "create",
  editingGroupName: null,
};

export interface UseEditorGroupsParams {
  cells: ConceptCell[];
  setCells: React.Dispatch<React.SetStateAction<ConceptCell[]>>;
  filteredCells: ConceptCell[];
  onSaveCell: SaveCellHandler;
}

export interface UseEditorGroupsReturn {
  groupNames: string[];
  groupedCells: Record<string, ConceptCell[]>;
  ungroupedCells: ConceptCell[];

  collapsedGroups: Record<string, boolean>;
  setCollapsedGroups: React.Dispatch<React.SetStateAction<Record<string, boolean>>>;
  handleToggleGroupCollapse: (groupName: string) => void;
  expandAllGroups: () => void;
  collapseAllGroups: () => void;

  showGroupDialog: boolean;
  groupDialogMode: GroupDialogMode;
  editingGroupName: string | null;
  closeGroupDialog: () => void;
  confirmGroupDialog: (groupName: string) => void;

  handleDeleteGroup: (groupName: string) => Promise<void>;
  handleAddCellToGroup: (cellId: string, groupName: string) => void;
  handleRemoveCellFromGroup: (cellId: string) => void;
  openRenameGroupDialog: (groupName: string) => void;
  startCreateGroupWithNewCell: (cellId: string) => void;
}

/**
 * All group-related concerns for the editor panel:
 * - tree derivations (groupNames / groupedCells / ungroupedCells)
 * - collapse state per group
 * - group dialog state (create / rename / assign)
 * - group mutations that fan out per-cell saves to the backend
 * - window event listeners for createGroupForCell
 */
export function useEditorGroups(params: UseEditorGroupsParams): UseEditorGroupsReturn {
  const { cells, setCells, filteredCells, onSaveCell } = params;

  const [collapsedGroups, setCollapsedGroups] = useState<Record<string, boolean>>({});
  const [groupDialog, setGroupDialog] = useState<GroupDialogState>(INITIAL_GROUP_DIALOG);
  const pendingGroupCellIdRef = useRef<string | null>(null);

  const groupNames = useMemo(() => {
    const names = new Set<string>();
    filteredCells.forEach((c) => {
      const g = c.group || UNGROUPED;
      if (g !== UNGROUPED) names.add(g);
    });
    return Array.from(names).sort();
  }, [filteredCells]);

  const groupedCells = useMemo(() => {
    const map: Record<string, ConceptCell[]> = {};
    groupNames.forEach((g) => {
      map[g] = [];
    });
    filteredCells.forEach((c) => {
      const g = c.group || UNGROUPED;
      if (g !== UNGROUPED && map[g]) map[g].push(c);
    });
    return map;
  }, [filteredCells, groupNames]);

  const ungroupedCells = useMemo(
    () => filteredCells.filter((c) => !c.group || c.group === UNGROUPED),
    [filteredCells],
  );

  const handleToggleGroupCollapse = useCallback((groupName: string) => {
    setCollapsedGroups((prev) => ({ ...prev, [groupName]: !(prev[groupName] ?? true) }));
  }, []);

  const expandAllGroups = useCallback(() => {
    setCollapsedGroups(() => {
      const next: Record<string, boolean> = {};
      for (const name of groupNames) next[name] = false;
      return next;
    });
  }, [groupNames]);

  const collapseAllGroups = useCallback(() => {
    setCollapsedGroups(() => {
      const next: Record<string, boolean> = {};
      for (const name of groupNames) next[name] = true;
      return next;
    });
  }, [groupNames]);

  const closeGroupDialog = useCallback(() => {
    setGroupDialog((prev) => ({ ...prev, open: false }));
  }, []);

  const persistGroupAssignment = useCallback(
    async (cellId: string, nextGroup: string) => {
      flushSync(() => {
        setCells((prev) =>
          prev.map((c) => (c.id === cellId ? { ...c, group: nextGroup, isModified: true } : c)),
        );
      });
      try {
        await onSaveCell(cellId, undefined, false);
        // Notify the Lineage view so its "Groups" legend refetches and reflects
        // the change without a page refresh.
        window.dispatchEvent(new CustomEvent(APP_EVENTS.CONCEPT_GROUPS_CHANGED));
      } catch (e) {
        console.error("Failed to persist group change:", e);
        toast.error("Group change saved locally; sync failed");
      }
    },
    [setCells, onSaveCell],
  );

  const handleCreateGroup = useCallback(
    (groupName: string) => {
      const cellId = pendingGroupCellIdRef.current;
      if (cellId) {
        pendingGroupCellIdRef.current = null;
        toast.success(`Cell added to new group "${groupName}"`);
        // Persist immediately (same path as adding to an existing group) so the
        // assignment reaches the backend and the Lineage "Groups" legend picks
        // it up — otherwise the new group only appears after a page refresh.
        void persistGroupAssignment(cellId, groupName);
      } else {
        toast.success(`Group "${groupName}" created`);
      }
      setGroupDialog((prev) => ({ ...prev, editingGroupName: groupName }));
      setCollapsedGroups((prev) => ({ ...prev, [groupName]: false }));
    },
    [persistGroupAssignment],
  );

  const persistGroupChangeForCells = useCallback(
    async (cellIds: string[], nextGroup: string, failureMessage: string) => {
      // flushSync so the cells ref in useConceptEditor sees the new group
      // before each save reads it. Without this, saves use the previous group.
      flushSync(() => {
        setCells((prev) =>
          prev.map((c) =>
            cellIds.includes(c.id) ? { ...c, group: nextGroup, isModified: true } : c,
          ),
        );
      });
      try {
        for (const cellId of cellIds) {
          await onSaveCell(cellId, undefined, false);
        }
        // Notify the Lineage view so its "Groups" legend refetches and reflects
        // the change without a page refresh.
        window.dispatchEvent(new CustomEvent(APP_EVENTS.CONCEPT_GROUPS_CHANGED));
      } catch (e) {
        console.error("Failed to persist group change:", e);
        toast.error(failureMessage);
      }
    },
    [setCells, onSaveCell],
  );

  const handleRenameGroup = useCallback(
    async (newGroupName: string) => {
      const oldName = groupDialog.editingGroupName;
      if (!oldName) return;
      // The group label lives on each cell row in the backend, so a rename
      // must persist every cell currently in the group — not just the one
      // the user happens to save next. Snapshot the affected IDs BEFORE the
      // state mutation so we still know who was in the old group.
      const affectedCellIds = cells.filter((c) => c.group === oldName).map((c) => c.id);
      setGroupDialog((prev) => ({ ...prev, editingGroupName: null }));
      if (affectedCellIds.length === 0) return;
      await persistGroupChangeForCells(
        affectedCellIds,
        newGroupName,
        `Group renamed locally; some cells failed to sync to "${newGroupName}"`,
      );
      toast.success(`Group renamed from "${oldName}" to "${newGroupName}"`);
    },
    [cells, groupDialog.editingGroupName, persistGroupChangeForCells],
  );

  const handleAssignToGroup = useCallback((_groupName: string) => {}, []);

  const handleDeleteGroup = useCallback(
    async (groupName: string) => {
      const affectedCellIds = cells.filter((c) => c.group === groupName).map((c) => c.id);
      if (affectedCellIds.length === 0) return;
      await persistGroupChangeForCells(
        affectedCellIds,
        UNGROUPED,
        `Group "${groupName}" deleted locally; some cells failed to sync`,
      );
      toast.success(`Group "${groupName}" deleted (cells ungrouped)`);
    },
    [cells, persistGroupChangeForCells],
  );

  const handleAddCellToGroup = useCallback(
    (cellId: string, groupName: string) => {
      toast.success(`Cell added to "${groupName}"`);
      void persistGroupAssignment(cellId, groupName);
    },
    [persistGroupAssignment],
  );

  const handleRemoveCellFromGroup = useCallback(
    (cellId: string) => {
      toast.success("Cell removed from group");
      void persistGroupAssignment(cellId, UNGROUPED);
    },
    [persistGroupAssignment],
  );

  const openRenameGroupDialog = useCallback((groupName: string) => {
    setGroupDialog({ open: true, mode: "rename", editingGroupName: groupName });
  }, []);

  const startCreateGroupWithNewCell = useCallback((cellId: string) => {
    pendingGroupCellIdRef.current = cellId;
    setGroupDialog({ open: true, mode: "create", editingGroupName: null });
  }, []);

  const confirmGroupDialog = useCallback(
    (groupName: string) => {
      if (groupDialog.mode === "create") return handleCreateGroup(groupName);
      if (groupDialog.mode === "rename") return handleRenameGroup(groupName);
      return handleAssignToGroup(groupName);
    },
    [groupDialog.mode, handleCreateGroup, handleRenameGroup, handleAssignToGroup],
  );

  // Listen for createGroupForCell events (from cell "Group > new" button)
  useEffect(() => {
    const handler = (event: CustomEvent) => {
      const { cellId, createMode } = event.detail;
      pendingGroupCellIdRef.current = cellId ?? null;
      setGroupDialog({
        open: true,
        mode: createMode ? "create" : "assign",
        editingGroupName: null,
      });
    };
    window.addEventListener("createGroupForCell", handler as EventListener);
    return () => window.removeEventListener("createGroupForCell", handler as EventListener);
  }, []);

  return {
    groupNames,
    groupedCells,
    ungroupedCells,
    collapsedGroups,
    setCollapsedGroups,
    handleToggleGroupCollapse,
    expandAllGroups,
    collapseAllGroups,
    showGroupDialog: groupDialog.open,
    groupDialogMode: groupDialog.mode,
    editingGroupName: groupDialog.editingGroupName,
    closeGroupDialog,
    confirmGroupDialog,
    handleDeleteGroup,
    handleAddCellToGroup,
    handleRemoveCellFromGroup,
    openRenameGroupDialog,
    startCreateGroupWithNewCell,
  };
}
