import { useQuery } from "@tanstack/react-query";

import { ConfigService } from "@/features/settings/api/configService";

const LLM_DEFAULTS_STALE_MS = 5 * 60 * 1000;

/**
 * Resolved non-secret LLM defaults — the provider/model/temperature an llm
 * concept runs with when its config declares no overrides.
 */
export function useLlmDefaults() {
  return useQuery({
    queryKey: ["llm-defaults"],
    queryFn: () => ConfigService.getLlmDefaults(),
    staleTime: LLM_DEFAULTS_STALE_MS,
  });
}
