import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { supabase } from "@/shared/integrations/supabase/client";
import { BaseClient } from "@/shared/lib/BaseClient";

/**
 * Response types
 */
export interface Machine {
  id: string;
  name: string;
  type: string;
  category: string | null;
  cores: number;
  memory_gb: number;
  cost_per_machine: number;
  ami?: string;
  created_at: string | null;
  updated_at: string | null;
}

export interface UserMachine {
  id: string;
  user_id: string;
  machine_id: string;
  node_group_id: string | null;
  status: "Requested" | "Enabled" | "Disabled";
  requested_at: string | null;
  enabled_at: string | null;
  disabled_at: string | null;
  created_at: string | null;
  is_default: boolean;
  is_active: boolean;
  for_compute: boolean; // Whether this machine is designated for compute workloads
  last_started_at: string | null; // Timestamp when machine was last started
  last_stopped_at: string | null; // Timestamp when machine was last stopped
  autotermination_minutes?: number | null;
  machines?: Machine;
}

interface UserMachinesResponse {
  status: "success" | "error";
  message: string;
  data?: {
    user_machines: UserMachine[];
  };
}

interface MachinesCombinedResponse {
  status: "success" | "error";
  message: string;
  data?: {
    machines: Machine[];
    user_machines_enabled: UserMachine[];
    user_machines_disabled: UserMachine[];
    total_machines: number;
    total_enabled: number;
    total_disabled: number;
  };
}

interface RequestMachineResponse {
  status: "success" | "error";
  message: string;
  data?: {
    user_machine: UserMachine | null;
    /** True when a previously disabled machine was re-enabled rather than added. */
    restored: boolean;
    /** Sent on the restore path only, carried over from the disabled record. */
    previous_usage_minutes?: number;
    free_minutes_remaining?: number | null;
  };
}

interface ToggleMachineActiveResponse {
  status: "success" | "error";
  message: string;
  data?: {
    user_machine: UserMachine;
  };
}

interface MachineStatusResponse {
  status: "success" | "error";
  message: string;
  data?: {
    user_machine_id: string;
    machine_status:
      | "started"
      | "stopped"
      | "stopping"
      | "pending"
      | "starting"
      | "crashed"
      | "restarting";
    is_active: boolean; // Current is_active status from Supabase (synced with pod status)
    pod_info: {
      name: string | null;
      phase: string | null;
      ready: string | null;
      restarts: number;
      ip: string | null;
      node: string | null;
    };
    metrics: {
      cpu_cores: number;
      memory_gb: number;
    };
    usage?: {
      free_minutes_remaining?: number;
      total_usage_minutes?: number;
      is_default?: boolean;
      current_session?: {
        id: string;
        started_at: string;
        stopped_at: string | null;
        duration_minutes: number | null;
        current_duration_minutes?: number;
      };
      current_session_cost_usd?: number;
    };
    error?: string;
    message?: string;
  };
}

export type MachineStatusValue =
  | "started"
  | "stopped"
  | "stopping"
  | "pending"
  | "starting"
  | "crashed"
  | "restarting";

export interface MachineStatusEvent {
  machine_status: MachineStatusValue;
  is_active: boolean;
  pod_info?: {
    name: string | null;
    phase: string | null;
    ready: string | null;
    restarts: number;
    ip: string | null;
    node: string | null;
  };
  timestamp?: string;
}

/**
 * Client for machine-related operations
 */
export class MachineClient extends BaseClient {
  /**
   * Get user's enabled machines (lightweight endpoint)
   * Used by UI components that only need to display user's current machines.
   * For full management (catalog + enabled + disabled), use getMachinesCombined().
   */
  async getUserMachines(): Promise<UserMachinesResponse> {
    try {
      // Get Supabase session for authentication header
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const additionalHeaders: Record<string, string> = {
        "X-Supabase-Token": session?.access_token || "null",
      };

      const response = await this.get(`/machines/user-machines`, undefined, additionalHeaders);
      return response;
    } catch (error) {
      console.error("Error fetching user machines:", error);
      throw error as Error;
    }
  }

  /**
   * Get all machines from catalog AND user's machines (enabled + disabled) in a single call
   *
   * Returns:
   * - machines: All catalog machines
   * - user_machines_enabled: User's enabled machines
   * - user_machines_disabled: User's disabled machines (preserving usage history)
   *
   * Frontend can use disabled machines in "Available" section with "Previously Used" badge
   */
  async getMachinesCombined(): Promise<MachinesCombinedResponse> {
    try {
      // Get Supabase session for authentication header
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const additionalHeaders: Record<string, string> = {
        "X-Supabase-Token": session?.access_token || "null",
      };

      const response = await this.get(`/machines/machines-combined`, undefined, additionalHeaders);
      return response;
    } catch (error) {
      console.error("Error fetching combined machines:", error);
      throw error as Error;
    }
  }

  /**
   * Request access to a machine or re-request a disabled machine
   * @param machineId - ID of the machine to request
   * @param machineName - Optional name of the machine for notifications
   */
  async useMachine(machineId: string, machineName?: string): Promise<RequestMachineResponse> {
    try {
      const payload = {
        machine_id: machineId,
        machine_name: machineName,
      };

      // Get Supabase session for authentication header
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const additionalHeaders: Record<string, string> = {
        "X-Supabase-Token": session?.access_token || "null",
      };

      const response = await this.post(
        "/machines/user-machines/use",
        payload,
        undefined,
        additionalHeaders,
      );
      return response;
    } catch (error) {
      console.error("Error using machine:", error);
      throw error as Error;
    }
  }

  /**
   * Start or stop a user's machine
   * @param userMachineId - ID of the user_machine record
   * @param isActive - true to start, false to stop
   * @param autoterminationMinutes - optional minutes of inactivity before auto-termination
   */
  async toggleMachineActive(
    userMachineId: string,
    isActive: boolean,
    autoterminationMinutes?: number,
  ): Promise<ToggleMachineActiveResponse> {
    try {
      const payload: Record<string, unknown> = {
        user_machine_id: userMachineId,
        is_active: isActive,
      };
      if (autoterminationMinutes !== undefined) {
        payload.autotermination_minutes = autoterminationMinutes;
      }

      // Get Supabase session for authentication header
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const additionalHeaders: Record<string, string> = {
        "X-Supabase-Token": session?.access_token || "null",
      };

      const response = await this.patch(
        "/machines/user-machines/toggle-active",
        payload,
        undefined,
        additionalHeaders,
      );
      return response;
    } catch (error) {
      console.error("Error toggling machine active status:", error);
      throw error as Error;
    }
  }

  /**
   * Get real-time status of a user's machine by checking the Kubernetes pod
   * @param userMachineId - ID of the user_machine record
   * @returns Machine status (started/stopped/pending/crashed/restarting) with pod metrics
   */
  async getMachineStatus(userMachineId: string): Promise<MachineStatusResponse> {
    try {
      // Get Supabase session for authentication header
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const additionalHeaders: Record<string, string> = {
        "X-Supabase-Token": session?.access_token || "null",
      };

      const response = await this.get(
        `/machines/user-machines/${userMachineId}/status`,
        undefined,
        additionalHeaders,
      );
      return response;
    } catch (error) {
      console.error("Error getting machine status:", error);
      throw error;
    }
  }

  async getMachineUsage(userMachineId: string) {
    try {
      // Get Supabase session for authentication header
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const additionalHeaders: Record<string, string> = {
        "X-Supabase-Token": session?.access_token || "null",
      };

      const response = await this.get(
        `/machines/user-machines/${userMachineId}/usage`,
        undefined,
        additionalHeaders,
      );
      return response;
    } catch (error) {
      console.error("Error getting machine status:", error);
      throw error as Error;
    }
  }

  async deleteUserMachine(userMachineId: string): Promise<{ status: string; message: string }> {
    try {
      // Get Supabase session for authentication header
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const additionalHeaders: Record<string, string> = {
        "X-Supabase-Token": session?.access_token || "null",
      };

      const response = await this.delete(
        `/machines/user-machines/${userMachineId}`,
        additionalHeaders,
      );
      return response;
    } catch (error) {
      console.error("Error deleting user machine:", error);
      throw error as Error;
    }
  }

  /**
   * Open a WebSocket connection for real-time machine status updates.
   * Auth is passed via query params since WebSocket doesn't support custom headers.
   * Returns the WebSocket instance so the caller can close it on cleanup.
   */
  async connectMachineStatusWs(
    userMachineId: string,
    onStatus: (data: MachineStatusEvent) => void,
    onDone: () => void,
    onError: (error: string) => void,
  ): Promise<WebSocket> {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    const token = PROMETHEUX_CONFIG.AUTH_TOKEN || "";
    const supabaseToken = session?.access_token || "";

    // Derive WebSocket URL from BASE_URL, handling both relative ("/api/v1")
    // and absolute ("http://localhost:8000/api/v1") configurations.
    let wsUrl: string;
    const baseUrl = PROMETHEUX_CONFIG.BASE_URL;
    if (baseUrl.startsWith("http://") || baseUrl.startsWith("https://")) {
      const parsed = new URL(baseUrl);
      const wsProtocol = parsed.protocol === "https:" ? "wss" : "ws";
      wsUrl = `${wsProtocol}://${parsed.host}${parsed.pathname}`;
    } else {
      const wsProtocol = window.location.protocol === "https:" ? "wss" : "ws";
      wsUrl = `${wsProtocol}://${window.location.host}${baseUrl}`;
    }

    const endpoint = `/machines/user-machines/${userMachineId}/status/ws`;
    const params = new URLSearchParams({
      token,
      x_supabase_token: supabaseToken,
    });

    const ws = new WebSocket(`${wsUrl}${endpoint}?${params.toString()}`);

    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        if (data.event === "status") {
          onStatus({
            machine_status: data.machine_status,
            is_active: data.is_active,
            pod_info: data.pod_info,
            timestamp: data.timestamp,
          });
        } else if (data.event === "done") {
          onDone();
        } else if (data.event === "error") {
          onError(data.error || "WebSocket stream error");
        }
      } catch {
        // Non-JSON message, ignore
      }
    };

    ws.onerror = () => {
      onError("WebSocket connection error");
    };

    ws.onclose = (event) => {
      if (event.code === 4001) {
        onError("WebSocket authentication failed");
      }
    };

    return ws;
  }
}
