import React from "react";
import QueryLanguageCell from "./QueryLanguageCell";
import type { QueryConceptCellProps } from "./types/editorTypes";

// Extended props for SQL cell - adds handlers for concept name changes
interface QuerySqlCellProps extends QueryConceptCellProps {
  onOutputPredicateChange?: (cellId: string, outputPredicate: string) => void;
}

// SQL cells share their entire shell with Cypher cells; the implementation lives
// in QueryLanguageCell, parametrized by `kind`.
const QuerySqlCell: React.FC<QuerySqlCellProps> = (props) => (
  <QueryLanguageCell {...props} kind="sql" />
);

export default React.memo(QuerySqlCell);
