import { useQuery } from "@tanstack/react-query";
import { AppWindow } from "lucide-react";
import type React from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { DashboardClient } from "@/features/dynamic-dashboard/api/DashboardClient";
import { guardSidebarNavClick } from "@/features/engine-status/engineStatus";
import { cn } from "@/shared/lib/utils";

const client = new DashboardClient();

interface SidebarOntologyDashboardsItemProps {
  ontologyId: string;
  collapsed: boolean;
}

export function SidebarOntologyDashboardsItem({
  ontologyId,
  collapsed,
}: SidebarOntologyDashboardsItemProps) {
  const location = useLocation();
  const navigate = useNavigate();

  const handleNavClick = (to: string) => (e: React.MouseEvent<HTMLAnchorElement>) => {
    void guardSidebarNavClick(e, () => navigate(to));
  };

  const { data: dashboards } = useQuery({
    queryKey: ["ontology-dashboards-sidebar", ontologyId],
    queryFn: () => client.listDashboards(ontologyId),
    enabled: !!ontologyId,
    staleTime: 30_000,
  });

  if (!dashboards?.length) return null;

  const currentPath = location.pathname;

  if (collapsed) {
    return (
      <div className="border-t pt-4">
        {dashboards.map((d) => {
          const dashboardHref = `/apps/${ontologyId}/${d.id}`;
          const isActive = currentPath === dashboardHref;
          return (
            <Link
              key={d.id}
              to={dashboardHref}
              onClick={handleNavClick(dashboardHref)}
              title={d.name}
              className={cn(
                "flex h-9 w-full items-center justify-center rounded-md text-sm font-medium text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
                isActive && "bg-primary/10 text-primary",
              )}
            >
              <AppWindow className="h-4 w-4 shrink-0" />
            </Link>
          );
        })}
      </div>
    );
  }

  return (
    <div className="border-t pt-4">
      <p className="mb-1 px-3 text-xs font-medium uppercase tracking-wider text-muted-foreground">
        Ontology Apps
      </p>
      {dashboards.map((d) => {
        const dashboardHref = `/apps/${ontologyId}/${d.id}`;
        const isActive = currentPath === dashboardHref;
        return (
          <Link
            key={d.id}
            to={dashboardHref}
            onClick={handleNavClick(dashboardHref)}
            className={cn(
              "flex h-9 w-full items-center gap-3 rounded-md px-2 text-sm font-medium text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
              isActive && "bg-primary/10 text-primary",
            )}
          >
            <AppWindow className="h-4 w-4 shrink-0" />
            <span className="truncate">{d.name}</span>
          </Link>
        );
      })}
    </div>
  );
}
