import { useState } from "react";
import { Link } from "react-router-dom";
import { toast } from "sonner";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/shared/components/ui/card";
import { Input } from "@/shared/components/ui/input";
import { useForceLightTheme } from "@/shared/hooks/useForceLightTheme";
import { supabase } from "@/shared/integrations/supabase/client";

const PasswordResetRequest = () => {
  useForceLightTheme();

  const [email, setEmail] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [rateLimitTimer, setRateLimitTimer] = useState(0);

  const startRateLimitCountdown = (seconds: number) => {
    setRateLimitTimer(seconds);

    const interval = setInterval(() => {
      setRateLimitTimer((prev) => {
        if (prev <= 1) {
          clearInterval(interval);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (rateLimitTimer > 0) {
      toast.error(`Please wait ${rateLimitTimer} seconds before trying again`);
      return;
    }

    if (!email.includes("@")) {
      toast.error("Please enter a valid email address");
      return;
    }

    setIsLoading(true);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: `${window.location.origin}/reset-password/confirm`,
      });

      if (error) {
        if (error.status === 429) {
          const waitSeconds = 300; // 5 minutes default
          startRateLimitCountdown(waitSeconds);
          throw new Error(
            `Please wait ${waitSeconds} seconds before requesting another reset email`,
          );
        }
        throw error;
      }

      setIsSuccess(true);
      toast.success("Password reset email sent! Please check your inbox.");
    } catch (error: any) {
      toast.error(error.message);
    } finally {
      setIsLoading(false);
    }
  };

  if (isSuccess) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <Card className="w-[400px] border-0 shadow-none">
          <CardHeader className="text-center space-y-6">
            <div className="flex justify-center">
              <img src="/prometheux-logo.png" alt="Prometheux" className="h-8" />
            </div>
            <CardTitle>Check your email</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4 text-center">
            <p className="text-sm text-muted-foreground">
              We've sent a password reset link to <strong>{email}</strong>
            </p>
            <p className="text-xs text-muted-foreground">
              If you don't see the email, check your spam folder or{" "}
              <button onClick={() => setIsSuccess(false)} className="text-primary hover:underline">
                try again
              </button>
            </p>
            <Link to="/login">
              <Button variant="outline" className="w-full">
                Back to Login
              </Button>
            </Link>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-white">
      <Card className="w-[400px] border-0 shadow-none">
        <CardHeader className="text-center space-y-6">
          <div className="flex justify-center">
            <img src="/prometheux-logo.png" alt="Prometheux" className="h-8" />
          </div>
          <CardTitle>Reset your password</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <p className="text-sm text-muted-foreground">
                Enter your email address and we'll send you a link to reset your password.
              </p>
              <Input
                type="email"
                placeholder="Email address*"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="bg-[#F5F7FB]"
                required
                disabled={isLoading || rateLimitTimer > 0}
              />
            </div>

            {rateLimitTimer > 0 && (
              <div className="text-sm text-orange-500 text-center">
                Please wait {rateLimitTimer} seconds before trying again
              </div>
            )}

            <Button
              type="submit"
              className="w-full bg-[#29CC7A] hover:bg-[#25B86E]"
              disabled={isLoading || rateLimitTimer > 0}
            >
              {isLoading ? "Sending..." : "Send Reset Email"}
            </Button>
          </form>

          <div className="text-center">
            <Link to="/login" className="text-sm text-[#29CC7A] hover:underline">
              Back to Login
            </Link>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default PasswordResetRequest;
