import { Clock, X } from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { Button } from "@/shared/components/ui/button";
import { ScrollArea } from "@/shared/components/ui/scroll-area";
import { splitStoredAttachments } from "../attachments.utils";
import { groupSessionsByRecency } from "../chatHistory.utils";
import type { ChatSessionMessage, ChatSessionMeta } from "../chatHistoryApi";
import { deleteSession, fetchSession, fetchSessions, renameSession } from "../chatHistoryApi";
import type { ChatMessage } from "../store";
import { useCodeAssistantStore } from "../store";
import { ChatHistoryRow } from "./ChatHistoryRow";
import { ConfirmDeleteDialog } from "./ConfirmDeleteDialog";

// Chat history is global per user — sessions are not scoped to a project, so
// this sidebar takes no project prop.
type ChatHistorySidebarProps = Record<string, never>;

const CONTEXT_BLOCK_RE = /^<retrieved_context>[\s\S]*?<\/retrieved_context>\s*/;

function stripInjectedContext(text: string): string {
  return text.replace(CONTEXT_BLOCK_RE, "");
}

interface ToolCall {
  function?: { name?: string };
  name?: string;
}

function extractToolName(tc: ToolCall): string {
  return tc.function?.name ?? tc.name ?? "tool";
}

function convertServerMessages(serverMsgs: ChatSessionMessage[]): ChatMessage[] {
  const result: ChatMessage[] = [];
  // Counts every stored user row, including the ones that render to nothing and
  // never become a bubble, so an edit truncates at the row the user pointed at.
  let userRow = 0;

  for (const m of serverMsgs) {
    if (m.role === "tool") continue;

    if (m.role === "user") {
      // Attachments were inlined into the stored text by the backend; show them
      // as chips rather than dumping the extracted file content in the bubble.
      const { text, attachments } = splitStoredAttachments(stripInjectedContext(m.content ?? ""));
      const turnIndex = userRow;
      userRow += 1;
      if (!text && attachments.length === 0) continue;
      result.push({
        id: crypto.randomUUID(),
        role: "user",
        content: text,
        attachments: attachments.length > 0 ? attachments : undefined,
        userTurnIndex: turnIndex,
        createdAt: m.created_at,
      });
      continue;
    }

    if (m.role !== "assistant") continue;

    const toolCalls = m.tool_calls as ToolCall[] | undefined;
    if (toolCalls?.length) {
      for (const tc of toolCalls) {
        const name = extractToolName(tc);
        result.push({
          id: crypto.randomUUID(),
          role: "tool",
          content: name,
          toolName: name,
          toolStatus: "done",
        });
      }
    }

    const text = m.content ?? "";
    if (text) {
      result.push({
        id: crypto.randomUUID(),
        role: "assistant",
        content: text,
        hasCodeBlock: text.includes("```"),
      });
    }
  }

  return result;
}

const ChatHistorySidebar: React.FC<ChatHistorySidebarProps> = () => {
  const { authToken, session } = useAuth();
  const {
    sessionId: activeSessionId,
    isHistoryOpen,
    toggleHistory,
    clearMessages,
    loadSession,
    isLoading,
    historyRevision,
  } = useCodeAssistantStore();

  const [sessions, setSessions] = useState<ChatSessionMeta[]>([]);
  const [isLoadingSessions, setIsLoadingSessions] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState("");
  const [sessionPendingDelete, setSessionPendingDelete] = useState<string | null>(null);
  const editInputRef = useRef<HTMLInputElement>(null);

  // Reactive, so the list loads as soon as signing in produces a token rather
  // than staying empty until something else re-renders the sidebar.
  const token = authToken ?? "";
  const supabaseToken = session?.access_token;

  const refresh = useCallback(async () => {
    if (!token) return;
    setIsLoadingSessions(true);
    try {
      const data = await fetchSessions(token, supabaseToken);
      setSessions(data);
    } catch {
      // silent — sidebar is non-critical
    } finally {
      setIsLoadingSessions(false);
    }
  }, [token, supabaseToken]);

  useEffect(() => {
    if (!isHistoryOpen) return;
    // historyRevision is intentionally in deps to trigger refresh after each turn
    void historyRevision;
    refresh();
  }, [isHistoryOpen, refresh, historyRevision]);

  const handleSelectSession = useCallback(
    async (sid: string) => {
      if (isLoading || sid === activeSessionId) return;
      try {
        const full = await fetchSession(sid, token, supabaseToken);
        const msgs = convertServerMessages(full.messages);
        loadSession(sid, msgs, full.title);
      } catch {
        // silent
      }
    },
    [activeSessionId, isLoading, loadSession, token, supabaseToken],
  );

  const handleConfirmDelete = useCallback(async () => {
    const sid = sessionPendingDelete;
    setSessionPendingDelete(null);
    if (!sid) return;
    try {
      await deleteSession(sid, token, supabaseToken);
      setSessions((prev) => prev.filter((s) => s.id !== sid));
      if (sid === activeSessionId) {
        clearMessages();
      }
    } catch {
      // silent
    }
  }, [activeSessionId, clearMessages, sessionPendingDelete, token, supabaseToken]);

  const handleStartRename = useCallback((sid: string, currentTitle: string) => {
    setEditingId(sid);
    setEditTitle(currentTitle);
    requestAnimationFrame(() => editInputRef.current?.focus());
  }, []);

  const handleFinishRename = useCallback(async () => {
    if (!editingId) return;
    const trimmed = editTitle.trim();
    if (!trimmed) {
      setEditingId(null);
      return;
    }
    try {
      await renameSession(editingId, trimmed, token, supabaseToken);
      setSessions((prev) => prev.map((s) => (s.id === editingId ? { ...s, title: trimmed } : s)));
    } catch {
      // silent
    }
    setEditingId(null);
  }, [editingId, editTitle, token, supabaseToken]);

  if (!isHistoryOpen) return null;

  const groups = groupSessionsByRecency(sessions);

  return (
    <div className="sticky top-0 flex h-screen max-h-screen w-[280px] max-w-[280px] flex-shrink-0 flex-col self-start overflow-hidden border-l border-border bg-card">
      {/* Header */}
      <div className="flex h-14 flex-shrink-0 items-center justify-between border-b border-border px-4">
        <span className="text-sm font-semibold text-foreground">Chat History</span>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-7 w-7 text-muted-foreground hover:text-foreground"
          onClick={toggleHistory}
        >
          <X className="h-4 w-4" />
        </Button>
      </div>

      {/* Session list */}
      <ScrollArea className="flex-1 overflow-hidden">
        {isLoadingSessions && sessions.length === 0 ? (
          <div className="flex items-center justify-center p-6">
            <span className="text-xs text-muted-foreground">Loading…</span>
          </div>
        ) : sessions.length === 0 ? (
          <div className="flex flex-col items-center justify-center gap-2 p-8 text-center">
            <Clock className="h-6 w-6 text-muted-foreground/40" />
            <span className="text-sm text-muted-foreground">No past chats yet</span>
          </div>
        ) : (
          <div className="flex flex-col gap-4 p-2">
            {groups.map((group) => (
              <section key={group.label} className="flex flex-col gap-0.5">
                <p className="px-2.5 pb-1 text-[11px] font-medium uppercase tracking-wide text-muted-foreground/80">
                  {group.label}
                </p>
                {group.sessions.map((s) => (
                  <ChatHistoryRow
                    key={s.id}
                    session={s}
                    isActive={s.id === activeSessionId}
                    isEditing={editingId === s.id}
                    editTitle={editTitle}
                    editInputRef={editInputRef}
                    onSelect={handleSelectSession}
                    onEditTitleChange={setEditTitle}
                    onFinishRename={handleFinishRename}
                    onCancelRename={() => setEditingId(null)}
                    onStartRename={handleStartRename}
                    onDelete={setSessionPendingDelete}
                  />
                ))}
              </section>
            ))}
          </div>
        )}
      </ScrollArea>
      <ConfirmDeleteDialog
        open={sessionPendingDelete !== null}
        onOpenChange={(open) => !open && setSessionPendingDelete(null)}
        onConfirm={handleConfirmDelete}
        title="Delete the chat"
        description="Are you sure you want to delete this conversation and everything in it? It cannot be undone."
      />
    </div>
  );
};

export default ChatHistorySidebar;
