import { Circle, Info, Link, Save, Trash2 } from "lucide-react";
import React, { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shared/components/ui/dialog";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Textarea } from "@/shared/components/ui/textarea";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";

// Types for custom fields
export interface CustomFieldData {
  value: string;
  type: "string" | "integer" | "double" | "date" | "boolean" | "set" | "list";
}

export interface NodeForm {
  label: string;
  description: string;
  color: string;
  customFields: Record<string, CustomFieldData>;
}

export interface EdgeForm {
  label: string;
  description: string;
  from: string;
  to: string;
  bidirectional?: boolean;
  customFields: Record<string, CustomFieldData>;
}

export interface NodeData {
  id: string;
  label: string;
  description: string;
  color: string;
  collapsed?: boolean;
  containedNodes?: {
    id: string;
    wasCollapsed: boolean;
    wasContaining: string[];
  }[];
  x?: number;
  y?: number;
  customFields?: Record<string, CustomFieldData>;
}

export type EntityType = "node" | "edge";
export type EntityForm = NodeForm | EdgeForm;

export interface EntityConfigProps {
  entityType: EntityType;
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  selectedEntity: any;
  entityForm: EntityForm;
  setEntityForm: React.Dispatch<React.SetStateAction<EntityForm>>;
  closeDialog: () => void;
  deleteEntity: () => void;
  saveEntity: () => void;
  validateFieldValue: (value: string, type: string) => string;
  FIELD_TYPE_OPTIONS: { value: string; label: string }[];
  // Node-specific props
  DEFAULT_NODE_COLORS?: string[];
  // Edge-specific props
  availableNodes?: { id: string; label: string }[];
  graphState?: { nodes: NodeData[] };
}

const EntityConfig: React.FC<EntityConfigProps> = ({
  entityType,
  isOpen,
  onOpenChange,
  selectedEntity,
  entityForm,
  setEntityForm,
  closeDialog,
  deleteEntity,
  saveEntity,
  validateFieldValue,
  FIELD_TYPE_OPTIONS,
  DEFAULT_NODE_COLORS = [],
  availableNodes = [],
  graphState = { nodes: [] },
}) => {
  const isNode = entityType === "node";
  const nodeForm = entityForm as NodeForm;
  const edgeForm = entityForm as EdgeForm;

  const getIcon = () => {
    return isNode ? (
      <Circle className="w-5 h-5 text-primary" />
    ) : (
      <Link className="w-5 h-5 text-primary" />
    );
  };

  const getTitle = () => {
    const entityName = isNode ? "Node" : "Edge";
    return selectedEntity ? `Edit ${entityName}` : `Add ${entityName}`;
  };

  const getCustomFields = () => {
    return isNode ? nodeForm.customFields : edgeForm.customFields;
  };

  const setCustomFields = (newFields: Record<string, CustomFieldData>) => {
    if (isNode) {
      setEntityForm((prev) => ({ ...prev, customFields: newFields }) as NodeForm);
    } else {
      setEntityForm((prev) => ({ ...prev, customFields: newFields }) as EdgeForm);
    }
  };

  const updateCustomField = (key: string, fieldData: CustomFieldData) => {
    const currentFields = getCustomFields();
    const newFields = { ...currentFields, [key]: fieldData };
    setCustomFields(newFields);
  };

  const removeCustomField = (key: string) => {
    const currentFields = getCustomFields();
    const newFields = { ...currentFields };
    delete newFields[key];
    setCustomFields(newFields);
  };

  const _renameCustomField = (oldKey: string, newKey: string) => {
    const currentFields = getCustomFields();
    const fieldData = currentFields[oldKey];
    const newFields = { ...currentFields };
    delete newFields[oldKey];
    newFields[newKey] = fieldData;
    setCustomFields(newFields);
  };

  const [customFieldInput, setCustomFieldInput] = useState("");
  const [isInputModified, setIsInputModified] = useState(false);

  // Initialize customFieldInput with current field names only when the dialog
  // opens.  Using entityForm as a dependency would reset the textarea on every
  // keystroke in the label/description fields, discarding un-applied input.
  const prevOpenRef = React.useRef(false);
  React.useEffect(() => {
    if (isOpen && !prevOpenRef.current) {
      const currentFields = getCustomFields();
      const fieldNames = Object.keys(currentFields);
      setCustomFieldInput(fieldNames.join(", "));
      setIsInputModified(false);
    }
    prevOpenRef.current = isOpen;
  }, [isOpen, getCustomFields]);

  const handleCustomFieldInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setCustomFieldInput(value);
    setIsInputModified(true);
  };

  const applyCustomFields = () => {
    if (customFieldInput.trim() === "") return;

    const names = customFieldInput
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    if (names.length > 0) {
      const currentFields = getCustomFields();
      const newFields: Record<string, CustomFieldData> = {};

      // Create new fields based on the input
      names.forEach((name) => {
        if (name) {
          // If field already exists, keep its current data
          if (name in currentFields) {
            newFields[name] = currentFields[name];
          } else {
            // Create new field
            newFields[name] = { value: "", type: "string" };
          }
        }
      });

      setCustomFields(newFields);
      setIsInputModified(false);
    }
  };

  const handleCustomFieldInputKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter") {
      e.preventDefault();
      applyCustomFields();
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] flex flex-col">
        <DialogHeader className="flex-shrink-0">
          <DialogTitle className="flex items-center gap-2">
            {getIcon()}
            {getTitle()}
          </DialogTitle>
        </DialogHeader>
        <div className="flex-1 overflow-y-auto px-1 min-h-0">
          <div className="space-y-4 py-4">
            {/* Label */}
            <div className="space-y-2">
              <Label htmlFor="entity-label" className="text-sm font-medium">
                Label
              </Label>
              <Input
                id="entity-label"
                value={isNode ? nodeForm.label : edgeForm.label}
                onChange={(e) => {
                  if (isNode) {
                    setEntityForm((prev) => ({ ...prev, label: e.target.value }) as NodeForm);
                  } else {
                    setEntityForm((prev) => ({ ...prev, label: e.target.value }) as EdgeForm);
                  }
                }}
                placeholder={`Enter ${entityType} label`}
                className="w-full"
              />
            </div>

            {/* Description */}
            <div className="space-y-2">
              <Label htmlFor="entity-description" className="text-sm font-medium">
                Description
              </Label>
              <Textarea
                id="entity-description"
                value={isNode ? nodeForm.description : edgeForm.description}
                onChange={(e) => {
                  if (isNode) {
                    setEntityForm((prev) => ({ ...prev, description: e.target.value }) as NodeForm);
                  } else {
                    setEntityForm((prev) => ({ ...prev, description: e.target.value }) as EdgeForm);
                  }
                }}
                placeholder={`Enter ${entityType} description`}
                rows={3}
                className="w-full resize-none"
              />
            </div>

            {/* Custom Fields */}
            <div className="space-y-2">
              <Label className="text-sm font-medium">Custom Fields</Label>
              {/* New custom field input */}
              <div className="flex gap-2 mb-2">
                <Textarea
                  placeholder="Type field names separated by commas (e.g. ID, Name, Company, etc.)"
                  value={customFieldInput}
                  onChange={handleCustomFieldInputChange}
                  onKeyDown={handleCustomFieldInputKeyDown}
                  className="flex-1 resize-none"
                  rows={1}
                />
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={applyCustomFields}
                  className={`px-4 transition-all ${
                    isInputModified && customFieldInput.trim() !== ""
                      ? "border-primary ring-2 ring-primary/20 bg-primary/5"
                      : ""
                  }`}
                >
                  Apply
                </Button>
              </div>
              <div className="space-y-2">
                {Object.entries(getCustomFields()).map(([key, fieldData], index) => (
                  <div
                    key={index}
                    className="flex gap-2 items-center border rounded-lg bg-muted/30 px-3 py-2"
                  >
                    <span
                      className="font-mono text-sm truncate overflow-ellipsis whitespace-nowrap"
                      style={{ maxWidth: "120px", minWidth: "120px", display: "inline-block" }}
                      title={key}
                    >
                      {key}
                    </span>
                    <Select
                      value={fieldData.type}
                      onValueChange={(newType: string) => {
                        const validatedValue = validateFieldValue(fieldData.value, newType);
                        updateCustomField(key, {
                          value: validatedValue,
                          type: newType as CustomFieldData["type"],
                        });
                      }}
                    >
                      <SelectTrigger className="w-32">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {FIELD_TYPE_OPTIONS.map((option) => (
                          <SelectItem key={option.value} value={option.value}>
                            {option.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <TooltipProvider>
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <span className="ml-1 cursor-pointer">
                            <Info className="w-4 h-4 text-muted-foreground" />
                          </span>
                        </TooltipTrigger>
                        <TooltipContent side="top" align="center" className="w-[250px]">
                          The value provides a constant, leave blank if you would like to keep it a
                          variable.
                        </TooltipContent>
                      </Tooltip>
                    </TooltipProvider>
                    <Input
                      placeholder={`Value`}
                      value={fieldData.value}
                      type={
                        fieldData.type === "integer" || fieldData.type === "double"
                          ? "number"
                          : fieldData.type === "date"
                            ? "datetime-local"
                            : "text"
                      }
                      onChange={(e) => {
                        const newValue = e.target.value;
                        updateCustomField(key, { ...fieldData, value: newValue });
                      }}
                      className="w-28 min-w-0"
                      style={{ width: "110px" }}
                    />
                    {fieldData.type === "boolean" && (
                      <div className="flex gap-1">
                        <Button
                          type="button"
                          variant={fieldData.value === "#T" ? "default" : "outline"}
                          size="sm"
                          onClick={() => updateCustomField(key, { ...fieldData, value: "#T" })}
                        >
                          #T
                        </Button>
                        <Button
                          type="button"
                          variant={fieldData.value === "#F" ? "default" : "outline"}
                          size="sm"
                          onClick={() => updateCustomField(key, { ...fieldData, value: "#F" })}
                        >
                          #F
                        </Button>
                      </div>
                    )}
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => removeCustomField(key)}
                      className="px-2"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                    {(fieldData.type === "set" || fieldData.type === "list") && (
                      <span className="text-xs text-muted-foreground ml-2 whitespace-nowrap">
                        {fieldData.type === "set" ? "{item1,item2,...}" : "[item1,item2,...]"}
                      </span>
                    )}
                  </div>
                ))}
              </div>
            </div>

            {/* Node-specific: Color Selection */}
            {isNode && (
              <div className="space-y-2">
                <Label className="text-sm font-medium">Color</Label>
                <div className="flex items-center gap-4">
                  <div className="flex items-center gap-2">
                    <input
                      id="node-color"
                      type="color"
                      value={nodeForm.color}
                      onChange={(e) =>
                        setEntityForm((prev) => ({ ...prev, color: e.target.value }) as NodeForm)
                      }
                      className="w-10 h-10 rounded-md border-2 border-border cursor-pointer bg-transparent"
                      title="Custom color"
                    />
                    <span className="text-xs text-muted-foreground">Custom</span>
                  </div>
                  <div className="flex-1">
                    <div className="flex gap-2 flex-wrap">
                      {DEFAULT_NODE_COLORS.map((color) => (
                        <button
                          key={color}
                          onClick={() => setEntityForm((prev) => ({ ...prev, color }) as NodeForm)}
                          className={`w-8 h-8 rounded-md border-2 transition-all hover:scale-110 ${
                            nodeForm.color === color
                              ? "border-primary ring-2 ring-primary/20"
                              : "border-border hover:border-primary/50"
                          }`}
                          style={{ backgroundColor: color }}
                          title={color}
                        />
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Edge-specific: Source and Target Node Selection */}
            {!isNode && !selectedEntity && (
              <>
                <div className="space-y-2">
                  <Label htmlFor="edge-from" className="text-sm font-medium">
                    Source Node
                  </Label>
                  <Select
                    value={edgeForm.from}
                    onValueChange={(value) =>
                      setEntityForm((prev) => ({ ...prev, from: value }) as EdgeForm)
                    }
                  >
                    <SelectTrigger className="w-full">
                      <SelectValue placeholder="Select source node" />
                    </SelectTrigger>
                    <SelectContent>
                      {availableNodes.map((node) => (
                        <SelectItem key={node.id} value={node.id}>
                          <div className="flex items-center gap-2">
                            <Circle
                              className="w-3 h-3"
                              style={{
                                color: graphState.nodes.find((n) => n.id === node.id)?.color,
                              }}
                            />
                            {node.label}
                          </div>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="edge-to" className="text-sm font-medium">
                    Target Node
                  </Label>
                  <Select
                    value={edgeForm.to}
                    onValueChange={(value) =>
                      setEntityForm((prev) => ({ ...prev, to: value }) as EdgeForm)
                    }
                  >
                    <SelectTrigger className="w-full">
                      <SelectValue placeholder="Select target node" />
                    </SelectTrigger>
                    <SelectContent>
                      {availableNodes.map((node) => (
                        <SelectItem key={node.id} value={node.id}>
                          <div className="flex items-center gap-2">
                            <Circle
                              className="w-3 h-3"
                              style={{
                                color: graphState.nodes.find((n) => n.id === node.id)?.color,
                              }}
                            />
                            {node.label}
                          </div>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </>
            )}

            {/* Edge-specific: Bidirectional Toggle */}
            {!isNode && (
              <div className="space-y-2">
                <div className="flex items-center space-x-2">
                  <input
                    id="edge-bidirectional"
                    type="checkbox"
                    checked={edgeForm.bidirectional || false}
                    onChange={(e) =>
                      setEntityForm(
                        (prev) => ({ ...prev, bidirectional: e.target.checked }) as EdgeForm,
                      )
                    }
                    className="rounded border-gray-300"
                  />
                  <Label htmlFor="edge-bidirectional" className="text-sm font-medium">
                    Bidirectional Edge
                  </Label>
                </div>
                <p className="text-xs text-muted-foreground">
                  Enable arrows on both ends of the edge
                </p>
              </div>
            )}
          </div>
        </div>

        {/* Footer Actions */}
        <div className="flex-shrink-0 flex items-center justify-between pt-4 border-t">
          <Button variant="outline" onClick={closeDialog} className="px-6">
            Cancel
          </Button>
          <div className="flex gap-2">
            {selectedEntity && (
              <Button onClick={deleteEntity} variant="destructive" className="px-6">
                <Trash2 className="w-4 h-4 mr-2" />
                Delete
              </Button>
            )}
            <Button onClick={saveEntity} className="px-6">
              <Save className="w-4 h-4 mr-2" />
              {selectedEntity
                ? "Update"
                : `Add ${entityType.charAt(0).toUpperCase() + entityType.slice(1)}`}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default EntityConfig;
