import { Circle, Code, Eye, FileCode, Link2, Save } from "lucide-react";
import type { ElementType } from "react";
import { ReadOnlyGate } from "@/features/ontologies/sharing/components/ReadOnlyGate";
import { useOntologyWideReadOnly } from "@/features/ontologies/sharing/hooks/useOntologyWideReadOnly";
import OntologySchemaSearchBar from "@/features/ontology-schema/components/OntologySchemaSearchBar";
import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";

interface OntologySchemaActionItemsProps {
  /** Collapses the overflow menu after an action is triggered. */
  close: () => void;
}

interface ViewModeButtonProps {
  active: boolean;
  icon: ElementType;
  label: string;
  onClick: () => void;
}

function ViewModeButton({ active, icon: Icon, label, onClick }: ViewModeButtonProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "flex h-full flex-1 items-center justify-center gap-1.5 rounded px-2.5 text-xs font-medium transition-colors",
        active
          ? "bg-background text-foreground shadow-sm"
          : "text-muted-foreground hover:text-foreground",
      )}
    >
      <Icon className="h-3.5 w-3.5" />
      {label}
    </button>
  );
}

/** Vertical, full-width form of the ontology toolbar, used inside the very-narrow overflow menu. */
export function OntologySchemaActionItems({ close }: OntologySchemaActionItemsProps) {
  const {
    viewMode,
    isSaving,
    isImporting,
    onViewModeChange,
    onAddNode,
    onOpenEdgeDialog,
    onSave,
    onTriggerOwlImport,
    onOpenOwlVadalogConfig,
    searchNodes,
    searchEdges,
    onNodeSearchSelect,
    onEdgeSearchSelect,
    onZoomToElement,
  } = useEditorActionsStore();
  const ontologyWideReadOnly = useOntologyWideReadOnly();

  const runAndClose = (action?: () => void) => {
    action?.();
    close();
  };

  const hasSearch = onNodeSearchSelect && onEdgeSearchSelect && onZoomToElement;

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center rounded-md border bg-muted p-0.5 h-9">
        <ViewModeButton
          active={viewMode === "visual"}
          icon={Eye}
          label="Visual"
          onClick={() => runAndClose(() => onViewModeChange?.("visual"))}
        />
        <ViewModeButton
          active={viewMode === "json"}
          icon={Code}
          label="JSON"
          onClick={() => runAndClose(() => onViewModeChange?.("json"))}
        />
      </div>

      <Button
        variant="outline"
        size="sm"
        className="w-full justify-start gap-2"
        onClick={() => runAndClose(onAddNode)}
      >
        <Circle className="h-3.5 w-3.5 text-muted-foreground" />
        Add Node
      </Button>
      <Button
        variant="outline"
        size="sm"
        className="w-full justify-start gap-2"
        onClick={() => runAndClose(onOpenEdgeDialog)}
      >
        <Link2 className="h-3.5 w-3.5 text-muted-foreground" />
        Add Edge
      </Button>

      <ReadOnlyGate readOnly={ontologyWideReadOnly}>
        <Button
          variant="outline"
          size="sm"
          className="w-full justify-start gap-2"
          onClick={() => runAndClose(onSave)}
          disabled={isSaving}
        >
          <Save className="h-3.5 w-3.5 text-muted-foreground" />
          Save graph
        </Button>
      </ReadOnlyGate>

      <Button
        variant="outline"
        size="sm"
        className="w-full justify-start gap-2"
        onClick={() => runAndClose(onTriggerOwlImport)}
        disabled={isImporting}
      >
        <Eye className="h-3.5 w-3.5 text-muted-foreground" />
        Visualize OWL
      </Button>
      <Button
        variant="outline"
        size="sm"
        className="w-full justify-start gap-2"
        onClick={() => runAndClose(onOpenOwlVadalogConfig)}
        disabled={isImporting}
      >
        <FileCode className="h-3.5 w-3.5 text-muted-foreground" />
        Translate OWL to Vadalog
      </Button>

      {hasSearch && (
        <OntologySchemaSearchBar
          nodes={searchNodes}
          edges={searchEdges}
          onNodeSelect={onNodeSearchSelect}
          onEdgeSelect={onEdgeSearchSelect}
          onZoomToElement={(id, type) => {
            onZoomToElement?.(id, type);
            close();
          }}
          inputWidthClass="w-full"
        />
      )}
    </div>
  );
}
