import { usePostHog } from "posthog-js/react";
import { useCallback } from "react";

export interface PostHogUser {
  username: string;
  organization: string;
  id: string;
  email?: string;
}

export class PostHogService {
  private static posthog: ReturnType<typeof usePostHog> | null = null;
  private static lastSetupUsername: string | null = null;

  // Expose debug method globally for browser console debugging
  static {
    if (typeof window !== "undefined") {
      (window as any).debugPostHog = () => PostHogService.debugPostHogState();
    }
  }

  /**
   * Initialize PostHog instance reference
   */
  static setPostHogInstance(posthogInstance: any) {
    PostHogService.posthog = posthogInstance;
  }

  /** True once an instance has been handed over, for callers outside the class. */
  static get hasInstance(): boolean {
    return PostHogService.posthog !== null;
  }

  /**
   * Identify user in PostHog.
   * Calls identify once with all properties — no redundant setPersonProperties or extra captures.
   */
  static identifyUser(user: PostHogUser) {
    if (!PostHogService.posthog) {
      return;
    }

    try {
      const personProperties: Record<string, string> = {
        username: user.username,
        organization: user.organization,
        user_id: user.id,
        display_name: `${user.username} (${user.organization})`,
        auth_method: "prometheux_auth",
        last_login: new Date().toISOString(),
      };
      // Email powers the PostHog->Attio join; only set it when present.
      if (user.email) {
        personProperties.email = user.email;
      }

      PostHogService.posthog.identify(user.username, personProperties);

      PostHogService.posthog.capture("user_identified", {
        method: "auth_provider",
      });
    } catch (_error) {
      // Error identifying user - silently ignore
    }
  }

  /**
   * Associate user with organization group in PostHog
   * Uses organization name as group key
   */
  static groupUser(user: PostHogUser) {
    if (!PostHogService.posthog) {
      return;
    }

    try {
      const groupData = {
        name: user.organization,
      };

      // Group users by organization
      PostHogService.posthog.group("organization", user.organization, groupData);
    } catch (_error) {}
  }

  /**
   * Complete user setup in PostHog (identify + group).
   * Idempotent: skips if called again for the same username.
   */
  static async setupUser(user: PostHogUser) {
    if (PostHogService.lastSetupUsername === user.username) {
      return;
    }
    PostHogService.lastSetupUsername = user.username;

    PostHogService.identifyUser(user);
    PostHogService.groupUser(user);

    const { WebVitalsService } = await import("./webVitalsService");
    WebVitalsService.initialize({
      username: user.username,
      organization: user.organization,
      user_id: user.id,
    });

    PostHogService.startSessionRecording();
  }

  /**
   * Debug method to check PostHog's current state
   */
  static debugPostHogState() {
    if (!PostHogService.posthog) {
      return;
    }
  }

  /**
   * Capture a custom event (for use by other services)
   */
  static captureEvent(eventName: string, properties: Record<string, unknown> = {}) {
    if (!PostHogService.posthog) {
      return;
    }

    try {
      PostHogService.posthog.capture(eventName, properties);
    } catch (_error) {}
  }

  /**
   * Session Recording Controls
   */
  static startSessionRecording() {
    if (!PostHogService.posthog) {
      return;
    }

    try {
      PostHogService.posthog.startSessionRecording();

      // Capture recording start event
      PostHogService.captureEvent("session_recording_started", {
        recording_method: "manual_start",
        timestamp: new Date().toISOString(),
      });
    } catch (_error) {}
  }

  static stopSessionRecording() {
    if (!PostHogService.posthog) {
      return;
    }

    try {
      PostHogService.posthog.stopSessionRecording();

      // Capture recording stop event
      PostHogService.captureEvent("session_recording_stopped", {
        recording_method: "manual_stop",
        timestamp: new Date().toISOString(),
      });
    } catch (_error) {}
  }

  static getSessionRecordingStatus() {
    if (!PostHogService.posthog) {
      return null;
    }

    try {
      const isRecording = PostHogService.posthog.sessionRecordingStarted?.() || false;
      const sessionId = PostHogService.posthog.get_session_id?.() || "Unknown";

      return {
        isRecording,
        sessionId,
      };
    } catch (_error) {
      return null;
    }
  }

  static setSessionProperties(properties: Record<string, unknown>) {
    if (!PostHogService.posthog) {
      return;
    }

    try {
      // register() sets super properties, sent with every subsequent event.
      // posthog-js has no setSessionProperties(), so calling it threw a
      // TypeError that the empty catch below swallowed — the properties never
      // reached PostHog. main.tsx registers its super properties the same way.
      PostHogService.posthog.register(properties);
    } catch (_error) {}
  }

  /**
   * Reset PostHog state when user logs out
   */
  static reset() {
    PostHogService.lastSetupUsername = null;

    if (!PostHogService.posthog) {
      return;
    }

    try {
      PostHogService.posthog.reset();
    } catch (_error) {}
  }
}

/**
 * React hook to use PostHog service within components.
 * All returned functions are stable (useCallback with []) so they are safe
 * to include in useEffect dependency arrays without causing repeated firing.
 */
export const usePostHogService = () => {
  const posthog = usePostHog();

  // Set the PostHog instance in the service when hook is used
  if (posthog && !PostHogService.hasInstance) {
    PostHogService.setPostHogInstance(posthog);
  }

  const identifyUser = useCallback((user: PostHogUser) => PostHogService.identifyUser(user), []);
  const groupUser = useCallback((user: PostHogUser) => PostHogService.groupUser(user), []);
  const setupUser = useCallback((user: PostHogUser) => PostHogService.setupUser(user), []);
  const reset = useCallback(() => PostHogService.reset(), []);
  const debugState = useCallback(() => PostHogService.debugPostHogState(), []);
  const startRecording = useCallback(() => PostHogService.startSessionRecording(), []);
  const stopRecording = useCallback(() => PostHogService.stopSessionRecording(), []);
  const getRecordingStatus = useCallback(() => PostHogService.getSessionRecordingStatus(), []);
  const setSessionProperties = useCallback(
    (properties: Record<string, unknown>) => PostHogService.setSessionProperties(properties),
    [],
  );

  return {
    identifyUser,
    groupUser,
    setupUser,
    reset,
    debugState,
    startRecording,
    stopRecording,
    getRecordingStatus,
    setSessionProperties,
  };
};
