import { UNGROUPED } from "@/features/concept-editor/hooks/useEditorGroups";

/**
 * Group colours and group-filtering helpers for the lineage canvas.
 *
 * Concept groups are arbitrary user-defined strings, so colours can't be
 * hard-coded per group. Instead each group name is hashed onto one of eight
 * palette slots defined as CSS variables in `base.css` (`--lineage-group-1..8`),
 * which keeps the colours theme-aware (light/dark) while staying stable for a
 * given group name. The `UNGROUPED` sentinel ("group_id") carries no colour.
 */

/** Number of palette slots defined in base.css (`--lineage-group-1..N`). */
export const GROUP_COLOR_COUNT = 8;

/** Filter key used for concepts that belong to no group. */
export const LINEAGE_UNGROUPED_KEY = "__ungrouped__";

const isUngrouped = (group?: string): boolean => !group || group === UNGROUPED;

/** Stable, order-independent hash of a group name onto a palette slot. */
const hashGroupName = (name: string): number => {
  let hash = 0;
  for (let i = 0; i < name.length; i++) {
    hash = (hash * 31 + name.charCodeAt(i)) >>> 0;
  }
  return hash % GROUP_COLOR_COUNT;
};

/** Map a concept's group to its filter key (ungrouped concepts share one key). */
export const groupFilterKey = (group?: string): string =>
  isUngrouped(group) ? LINEAGE_UNGROUPED_KEY : (group as string);

/** Resolve the CSS variable name for a group, or `null` when ungrouped. */
export const getGroupColorVar = (group?: string): string | null =>
  isUngrouped(group) ? null : `--lineage-group-${hashGroupName(group as string) + 1}`;

/** Full `hsl(var(--lineage-group-N))` colour string, or `null` when ungrouped. */
export const groupColor = (group?: string): string | null => {
  const cssVar = getGroupColorVar(group);
  return cssVar ? `hsl(var(${cssVar}))` : null;
};

/** Translucent variant of {@link groupColor}, e.g. for badge backgrounds. */
export const groupColorSoft = (group: string | undefined, alpha = 0.16): string | null => {
  const cssVar = getGroupColorVar(group);
  return cssVar ? `hsl(var(${cssVar}) / ${alpha})` : null;
};

export interface GroupLegendEntry {
  /** Filter key (group name, or {@link LINEAGE_UNGROUPED_KEY}). */
  key: string;
  /** Human-readable label shown in the legend. */
  label: string;
  /** `hsl(var(--lineage-group-N))` colour, or `null` for the ungrouped entry. */
  color: string | null;
  /** Number of concept nodes in this group. */
  count: number;
}

/**
 * Build the legend/filter entries from the concept nodes' group values.
 * Named groups are sorted alphabetically; the ungrouped bucket (if any) is
 * appended last so the legend always lists real groups first.
 */
export const buildGroupLegend = (conceptGroups: (string | undefined)[]): GroupLegendEntry[] => {
  const counts = new Map<string, number>();
  for (const group of conceptGroups) {
    const key = groupFilterKey(group);
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }

  const namedEntries: GroupLegendEntry[] = Array.from(counts.keys())
    .filter((key) => key !== LINEAGE_UNGROUPED_KEY)
    .sort((a, b) => a.localeCompare(b))
    .map((key) => ({ key, label: key, color: groupColor(key), count: counts.get(key) ?? 0 }));

  // No real groups → no legend at all (an "Ungrouped"-only legend is just noise).
  if (namedEntries.length === 0) return [];

  const ungroupedCount = counts.get(LINEAGE_UNGROUPED_KEY) ?? 0;
  if (ungroupedCount === 0) return namedEntries;

  return [
    ...namedEntries,
    { key: LINEAGE_UNGROUPED_KEY, label: "Ungrouped", color: null, count: ungroupedCount },
  ];
};
