// Order by item for column sorting
export interface OrderByItem {
  position: number;
  direction: "asc" | "desc";
}

export interface PaginationInfo {
  page: number;
  totalPages: number;
  hasNext: boolean;
  hasPrev: boolean;
  totalCount: number;
  pageSize?: number;
  orderBy?: OrderByItem[];
}

// Declared once in the feature's types module; re-exported here because callers
// have always imported them from this component.
export type { ColumnFilterValue, FilterOperator };

interface SearchState {
  searchTerm: string;
  columnPositions?: number[];
  columnFilters?: Record<number, ColumnFilterValue>;
}

interface QueryResultData {
  predicateName: string;
  columns: string[];
  rows: any[][];
}

interface CellClickParams {
  rowIndex: number;
  columnIndex: number;
  cellValue: any;
  rowData: any[];
  columnName: string;
}

interface QueryResultTableProps {
  data: QueryResultData;
  pagination?: PaginationInfo;
  onPageChange?: (page: number) => void;
  onPageSizeChange?: (pageSize: number) => void;
  isLoading?: boolean;
  // Search functionality
  // For global search: pass searchTerm, no columnFilters
  // For column filters: pass columnFilters (searchTerm can be undefined)
  onSearch?: (searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) => void;
  onClearSearch?: () => void;
  onClearColumnFilter?: (columnIndex: number) => void;
  searchState?: SearchState;
  // Sorting functionality
  onSort?: (orderBy: OrderByItem[]) => void;
  // IDs for graph building API
  ontologyId?: string;
  cellId?: string;
  // Cell click functionality
  onCellClick?: (params: CellClickParams) => void;
  selectedCell?: { rowIndex: number; columnIndex: number };
  // Execution times (milliseconds)
  runElapsedTime?: number; // Initial cell run time
  fetchElapsedTime?: number; // Fetch/pagination time
  // Row-level class name override based on row data
  getRowClassName?: (row: any[], columns: string[]) => string;
}

// Available page size options
const PAGE_SIZE_OPTIONS = [10, 25, 50, 100, 250, 500, 1000, 2500, 5000, 10000, 25000, 50000];

// Virtual scrolling configuration
const ROW_HEIGHT = 40; // Approximate height of each row
const VISIBLE_ROWS_BUFFER = 5; // Number of extra rows to render above/below visible area

// Memoized table row component to prevent unnecessary re-renders
const TableRowMemo = React.memo<{
  row: any[];
  rowIndex: number;
  predicateName: string;
  isNumericColumn: (index: number) => boolean;
  columns?: string[];
  onCellClick?: (params: CellClickParams) => void;
  selectedCell?: { rowIndex: number; columnIndex: number };
  getRowClassName?: (row: any[], columns: string[]) => string;
}>(
  ({
    row,
    rowIndex,
    predicateName,
    isNumericColumn,
    columns,
    onCellClick,
    selectedCell,
    getRowClassName,
  }) => {
    const extraClass = getRowClassName && columns ? getRowClassName(row, columns) : "";
    return (
      <TableRow
        className={cn(
          rowIndex % 2 === 0 ? "bg-transparent" : "bg-muted/15",
          "hover:bg-muted/30",
          "transition-colors",
          extraClass,
        )}
      >
        {Array.isArray(row) ? (
          row.map((cell, cellIdx) => {
            let cellContent: string | null = null;
            try {
              if (cell !== null && cell !== undefined) {
                if (Array.isArray(cell)) {
                  cellContent = JSON.stringify(cell);
                } else if (typeof cell === "object") {
                  cellContent = JSON.stringify(cell);
                } else {
                  cellContent = String(cell);
                }
              }
            } catch (_error) {
              cellContent = "[Error displaying value]";
            }

            const isSelected =
              selectedCell?.rowIndex === rowIndex && selectedCell?.columnIndex === cellIdx;

            return (
              <TableCell
                key={`${predicateName}-cell-${rowIndex}-${cellIdx}`}
                className={cn(
                  "py-1.5 px-4 border-r last:border-r-0",
                  "border-border/20",
                  "max-w-[400px] break-all",
                  isNumericColumn(cellIdx) ? "text-right font-mono" : "text-left font-normal",
                  onCellClick && "cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-950/30",
                  isSelected &&
                    "bg-blue-100 ring-2 ring-blue-400 ring-inset dark:bg-blue-900/40 dark:ring-blue-500",
                )}
                onClick={() => {
                  if (onCellClick && columns) {
                    onCellClick({
                      rowIndex,
                      columnIndex: cellIdx,
                      cellValue: cell,
                      rowData: row,
                      columnName: columns[cellIdx] || "",
                    });
                  }
                }}
              >
                {cellContent !== null ? (
                  cellContent
                ) : (
                  <span className="text-muted-foreground italic">null</span>
                )}
              </TableCell>
            );
          })
        ) : (
          <TableCell colSpan={100} className="text-center text-muted-foreground italic">
            Invalid row data
          </TableCell>
        )}
      </TableRow>
    );
  },
);

TableRowMemo.displayName = "TableRowMemo";

// Virtualized table body component
const VirtualizedTableBody = React.memo<{
  rows: any[][];
  predicateName: string;
  isNumericColumn: (index: number) => boolean;
  maxHeight?: number;
  columns?: string[];
  onCellClick?: (params: CellClickParams) => void;
  selectedCell?: { rowIndex: number; columnIndex: number };
  getRowClassName?: (row: any[], columns: string[]) => string;
}>(
  ({
    rows,
    predicateName,
    isNumericColumn,
    maxHeight = 400,
    columns,
    onCellClick,
    selectedCell,
    getRowClassName,
  }) => {
    const [scrollTop, setScrollTop] = useState(0);
    const containerRef = useRef<HTMLDivElement>(null);
    const scrollTimeoutRef = useRef<ReturnType<typeof setTimeout>>();

    const totalHeight = rows.length * ROW_HEIGHT;
    const visibleCount = Math.ceil(maxHeight / ROW_HEIGHT);
    const startIndex = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - VISIBLE_ROWS_BUFFER);
    const endIndex = Math.min(rows.length, startIndex + visibleCount + VISIBLE_ROWS_BUFFER * 2);

    const visibleRows = rows.slice(startIndex, endIndex);
    const offsetY = startIndex * ROW_HEIGHT;

    const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
      // Debounce scroll events to improve performance
      if (scrollTimeoutRef.current) {
        clearTimeout(scrollTimeoutRef.current);
      }

      scrollTimeoutRef.current = setTimeout(() => {
        setScrollTop(e.currentTarget.scrollTop);
      }, 16); // ~60fps
    }, []);

    // Cleanup timeout on unmount
    useEffect(() => {
      return () => {
        if (scrollTimeoutRef.current) {
          clearTimeout(scrollTimeoutRef.current);
        }
      };
    }, []);

    // Only use virtualization for tables with many rows
    // Note: Virtualization wraps TableBody in divs which can break table layout
    // Only enable for very large datasets where performance is critical
    const shouldVirtualize = rows.length > 500;

    if (!shouldVirtualize) {
      return (
        <TableBody>
          {rows.map((row, rowIdx) => (
            <TableRowMemo
              key={`${predicateName}-row-${rowIdx}`}
              row={row}
              rowIndex={rowIdx}
              predicateName={predicateName}
              isNumericColumn={isNumericColumn}
              columns={columns}
              onCellClick={onCellClick}
              selectedCell={selectedCell}
              getRowClassName={getRowClassName}
            />
          ))}
        </TableBody>
      );
    }

    return (
      <div
        ref={containerRef}
        style={{
          height: maxHeight,
          overflow: "auto",
          position: "relative",
        }}
        onScroll={handleScroll}
      >
        <div style={{ height: totalHeight, position: "relative" }}>
          <div style={{ transform: `translateY(${offsetY}px)` }}>
            <TableBody>
              {visibleRows.map((row, index) => (
                <TableRowMemo
                  key={`${predicateName}-row-${startIndex + index}`}
                  row={row}
                  rowIndex={startIndex + index}
                  predicateName={predicateName}
                  isNumericColumn={isNumericColumn}
                  columns={columns}
                  onCellClick={onCellClick}
                  selectedCell={selectedCell}
                  getRowClassName={getRowClassName}
                />
              ))}
            </TableBody>
          </div>
        </div>
      </div>
    );
  },
);

VirtualizedTableBody.displayName = "VirtualizedTableBody";

// Page input dialog component
const PageInputDialog = React.memo<{
  pagination: { totalPages: number };
  onPageChange: (page: number) => void;
  children: React.ReactNode;
}>(({ pagination, onPageChange, children }) => {
  const [inputValue, setInputValue] = useState("");
  const [isOpen, setIsOpen] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      const pageNumber = parseInt(inputValue.trim(), 10);

      if (Number.isNaN(pageNumber)) {
        setError("Please enter a valid page number");
        return;
      }

      if (pageNumber < 1 || pageNumber > pagination.totalPages) {
        setError(`Page number must be between 1 and ${pagination.totalPages}`);
        return;
      }

      setError("");
      setIsOpen(false);
      onPageChange(pageNumber);
      setInputValue("");
    },
    [inputValue, pagination.totalPages, onPageChange],
  );

  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setInputValue(e.target.value);
      if (error) setError("");
    },
    [error],
  );

  const handleOpenChange = useCallback((open: boolean) => {
    setIsOpen(open);
    if (!open) {
      setInputValue("");
      setError("");
    }
  }, []);

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogTrigger asChild>{children}</DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Select Page</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <label htmlFor="page-input" className="text-sm font-medium">
              Enter page number (1 - {pagination.totalPages})
            </label>
            <Input
              id="page-input"
              type="number"
              min="1"
              max={pagination.totalPages}
              value={inputValue}
              onChange={handleInputChange}
              placeholder={`1 - ${pagination.totalPages}`}
              className={error ? "border-red-500" : ""}
              autoFocus
            />
            {error && <p className="text-sm text-red-500">{error}</p>}
          </div>
          <div className="flex justify-end space-x-2">
            <Button type="button" variant="outline" onClick={() => setIsOpen(false)}>
              Cancel
            </Button>
            <Button type="submit">Go to Page</Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
});

PageInputDialog.displayName = "PageInputDialog";

// Column roles interface
const OPERATOR_LABELS: Record<FilterOperator, string> = {
  contains: "Contains",
  equals: "Equals",
  not_equals: "Not equals",
  greater_than: "Greater than",
  less_than: "Less than",
  greater_than_or_equal: "Greater or equal",
  less_than_or_equal: "Less or equal",
  starts_with: "Starts with",
  ends_with: "Ends with",
  is_null: "Is null",
  is_not_null: "Is not null",
};

const VALUELESS_OPERATORS: FilterOperator[] = ["is_null", "is_not_null"];

// Column filter popover component with role assignment and ordering
const ColumnFilterPopover = React.memo<{
  columnIndex: number;
  columnName: string;
  onFilter: (value: string, columnIndex: number, operator: FilterOperator) => void;
  onClearFilter?: (columnIndex: number) => void;
  isFiltered: boolean;
  currentFilterValue?: ColumnFilterValue;
  // Column role props
  // Ordering props
  currentSortDirection?: "asc" | "desc" | null;
  onSort?: (columnIndex: number, direction: "asc" | "desc" | null) => void;
}>(
  ({
    columnIndex,
    columnName,
    onFilter,
    onClearFilter,
    isFiltered,
    currentFilterValue,
    currentSortDirection,
    onSort,
  }) => {
    const [inputValue, setInputValue] = useState(currentFilterValue?.value || "");
    const [selectedOperator, setSelectedOperator] = useState<FilterOperator>(
      currentFilterValue?.operator || "contains",
    );
    const [isOpen, setIsOpen] = useState(false);
    const [activeSection, setActiveSection] = useState<"main" | "filter" | "order">("main");

    const needsValue = !VALUELESS_OPERATORS.includes(selectedOperator);

    // Determine current role for this column
    useEffect(() => {
      if (isOpen) {
        setInputValue(currentFilterValue?.value || "");
        setSelectedOperator(currentFilterValue?.operator || "contains");
        setActiveSection("main");
      }
    }, [isOpen, currentFilterValue]);

    const handleApply = useCallback(
      (e: React.FormEvent) => {
        e.preventDefault();
        if (!needsValue || inputValue.trim()) {
          onFilter(needsValue ? inputValue.trim() : "", columnIndex, selectedOperator);
          setIsOpen(false);
        }
      },
      [inputValue, columnIndex, onFilter, selectedOperator, needsValue],
    );

    const handleInputChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
      setInputValue(e.target.value);
    }, []);

    const handleClear = useCallback(() => {
      if (onClearFilter) {
        onClearFilter(columnIndex);
        setInputValue("");
        setSelectedOperator("contains");
        setIsOpen(false);
      }
    }, [onClearFilter, columnIndex]);

    const handleOpenChange = useCallback(
      (open: boolean) => {
        setIsOpen(open);
        if (!open) {
          setInputValue(currentFilterValue?.value || "");
          setSelectedOperator(currentFilterValue?.operator || "contains");
          setActiveSection("main");
        }
      },
      [currentFilterValue],
    );

    const handleSetSort = useCallback(
      (direction: "asc" | "desc" | null) => {
        if (onSort) {
          onSort(columnIndex, direction);
        }
        setIsOpen(false);
      },
      [onSort, columnIndex],
    );

    // Get indicators for the trigger button
    const hasActiveState = isFiltered || currentSortDirection;

    // Get sort indicator icon
    const sortIndicator = useMemo(() => {
      if (!currentSortDirection) return null;
      if (currentSortDirection === "asc") return <ArrowUp className="h-2.5 w-2.5 text-blue-600" />;
      if (currentSortDirection === "desc")
        return <ArrowDown className="h-2.5 w-2.5 text-blue-600" />;
      return null;
    }, [currentSortDirection]);

    return (
      <Popover open={isOpen} onOpenChange={handleOpenChange}>
        <PopoverTrigger asChild>
          <button
            className={cn(
              "ml-1 p-0.5 rounded hover:bg-muted transition-colors inline-flex items-center justify-center gap-0.5",
              hasActiveState && "text-blue-600 bg-blue-50 dark:bg-blue-900/30",
            )}
            title={`Options for ${columnName}`}
          >
            {isFiltered && <Filter className="h-2.5 w-2.5 text-blue-600" />}
            {sortIndicator}
            <MoreVertical className="h-3.5 w-3.5" />
          </button>
        </PopoverTrigger>
        <PopoverContent className="w-56 p-0" align="start">
          {/* Main Menu */}
          {activeSection === "main" && (
            <div className="py-1">
              {/* Filter Option */}
              <button
                type="button"
                onClick={() => setActiveSection("filter")}
                className={cn(
                  "w-full flex items-center gap-3 px-3 py-2 text-sm hover:bg-muted transition-colors",
                  isFiltered && "text-blue-600",
                )}
              >
                <Filter className="h-4 w-4" />
                <span className="flex-1 text-left">Filter</span>
                {isFiltered && <span className="text-xs text-blue-500">Active</span>}
                <ChevronRight className="h-4 w-4 text-muted-foreground" />
              </button>

              {/* Order Option */}
              {onSort && (
                <button
                  type="button"
                  onClick={() => setActiveSection("order")}
                  className={cn(
                    "w-full flex items-center gap-3 px-3 py-2 text-sm hover:bg-muted transition-colors",
                    currentSortDirection && "text-blue-600",
                  )}
                >
                  <ArrowUpDown className="h-4 w-4" />
                  <span className="flex-1 text-left">Order</span>
                  {currentSortDirection && (
                    <span className="text-xs text-blue-500">
                      {currentSortDirection === "asc" ? "Asc" : "Desc"}
                    </span>
                  )}
                  <ChevronRight className="h-4 w-4 text-muted-foreground" />
                </button>
              )}
            </div>
          )}

          {/* Filter Section */}
          {activeSection === "filter" && (
            <div className="p-3">
              <button
                type="button"
                onClick={() => setActiveSection("main")}
                className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground mb-2"
              >
                <ChevronLeft className="h-3 w-3" />
                Back
              </button>
              <form onSubmit={handleApply} className="space-y-2">
                {isFiltered && currentFilterValue && (
                  <div className="text-xs text-muted-foreground">
                    Currently: {OPERATOR_LABELS[currentFilterValue.operator]}
                    {currentFilterValue.value ? ` "${currentFilterValue.value}"` : ""}
                  </div>
                )}
                <select
                  value={selectedOperator}
                  onChange={(e) => setSelectedOperator(e.target.value as FilterOperator)}
                  className="w-full h-8 text-xs rounded-md border border-input bg-background px-2 focus:outline-none focus:ring-1 focus:ring-ring"
                >
                  {(Object.keys(OPERATOR_LABELS) as FilterOperator[]).map((op) => (
                    <option key={op} value={op}>
                      {OPERATOR_LABELS[op]}
                    </option>
                  ))}
                </select>
                {needsValue && (
                  <Input
                    type="text"
                    value={inputValue}
                    onChange={handleInputChange}
                    placeholder={`Value for ${columnName}...`}
                    className="h-8 text-sm"
                    autoFocus
                  />
                )}
                <div className="flex justify-between items-center gap-2">
                  {isFiltered && onClearFilter && (
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={handleClear}
                      className="h-7 px-2 text-xs text-muted-foreground hover:text-foreground"
                    >
                      <X className="h-3 w-3 mr-1" />
                      Clear
                    </Button>
                  )}
                  <Button
                    type="submit"
                    variant="outline"
                    size="sm"
                    disabled={needsValue && !inputValue.trim()}
                    className="h-7 px-2 text-xs ml-auto"
                  >
                    {isFiltered ? "Update" : "Apply"}
                  </Button>
                </div>
              </form>
            </div>
          )}

          {/* Order Section */}
          {activeSection === "order" && (
            <div className="py-1">
              <button
                type="button"
                onClick={() => setActiveSection("main")}
                className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground px-3 py-1.5 mb-1"
              >
                <ChevronLeft className="h-3 w-3" />
                Back
              </button>
              <button
                type="button"
                onClick={() => handleSetSort("asc")}
                className={cn(
                  "w-full flex items-center gap-3 px-3 py-2 text-sm hover:bg-muted transition-colors",
                  currentSortDirection === "asc" &&
                    "bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400",
                )}
              >
                <ArrowUp className="h-4 w-4" />
                <span className="flex-1 text-left">Ascending</span>
                {currentSortDirection === "asc" && <Check className="h-4 w-4" />}
              </button>
              <button
                type="button"
                onClick={() => handleSetSort("desc")}
                className={cn(
                  "w-full flex items-center gap-3 px-3 py-2 text-sm hover:bg-muted transition-colors",
                  currentSortDirection === "desc" &&
                    "bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400",
                )}
              >
                <ArrowDown className="h-4 w-4" />
                <span className="flex-1 text-left">Descending</span>
                {currentSortDirection === "desc" && <Check className="h-4 w-4" />}
              </button>
              {currentSortDirection && (
                <button
                  type="button"
                  onClick={() => handleSetSort(null)}
                  className="w-full flex items-center gap-3 px-3 py-2 text-sm hover:bg-muted transition-colors text-muted-foreground"
                >
                  <X className="h-4 w-4" />
                  <span className="flex-1 text-left">Clear</span>
                </button>
              )}
            </div>
          )}
        </PopoverContent>
      </Popover>
    );
  },
);

ColumnFilterPopover.displayName = "ColumnFilterPopover";

// Global search bar component
const GlobalSearchBar = React.memo<{
  onSearch: (searchTerm: string) => void;
  onClear: () => void;
  currentSearchTerm?: string;
  isSearchActive: boolean;
}>(({ onSearch, onClear, currentSearchTerm, isSearchActive }) => {
  const [inputValue, setInputValue] = useState(currentSearchTerm || "");
  const [isExpanded, setIsExpanded] = useState(isSearchActive);
  const inputRef = useRef<HTMLInputElement>(null);

  // Sync input with external search state
  useEffect(() => {
    setInputValue(currentSearchTerm || "");
    setIsExpanded(isSearchActive || !!currentSearchTerm);
  }, [currentSearchTerm, isSearchActive]);

  const handleSearch = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      if (inputValue.trim()) {
        onSearch(inputValue.trim());
      }
    },
    [inputValue, onSearch],
  );

  const handleClear = useCallback(() => {
    setInputValue("");
    onClear();
  }, [onClear]);

  const handleToggle = useCallback(() => {
    if (isExpanded && !isSearchActive) {
      // If expanded but no active search, close it
      setIsExpanded(false);
      setInputValue("");
    } else if (!isExpanded) {
      // If collapsed, expand it
      setIsExpanded(true);
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isExpanded, isSearchActive]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "Escape") {
        if (!isSearchActive) {
          setIsExpanded(false);
          setInputValue("");
        }
      }
    },
    [isSearchActive],
  );

  if (!isExpanded) {
    return (
      <button
        onClick={handleToggle}
        className="p-1 rounded hover:bg-blue-200/50 transition-colors"
        title="Search results"
      >
        <Search className="h-4 w-4 text-blue-700" />
      </button>
    );
  }

  return (
    <div className="flex items-center gap-1">
      <button
        type="button"
        onClick={handleToggle}
        className="p-1 rounded hover:bg-blue-200/50 transition-colors flex-shrink-0"
        title="Close search"
      >
        <Search className="h-4 w-4 text-blue-700" />
      </button>
      <form onSubmit={handleSearch} className="flex items-center gap-1">
        <div className="relative">
          {isSearchActive && (
            <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
          )}
          <Input
            ref={inputRef}
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Search all columns..."
            className={cn(
              "h-7 text-xs font-normal text-foreground bg-background/90 border-input focus:border-ring",
              isSearchActive ? "pl-7 pr-7" : "pl-2 pr-7",
              "w-40",
            )}
          />
          {(inputValue || isSearchActive) && (
            <button
              type="button"
              onClick={handleClear}
              className="absolute right-1.5 top-1/2 -translate-y-1/2 p-0.5 rounded hover:bg-muted transition-colors"
              title="Clear search"
            >
              <X className="h-3 w-3 text-muted-foreground" />
            </button>
          )}
        </div>
        <Button
          type="submit"
          size="sm"
          variant="secondary"
          disabled={!inputValue.trim()}
          className="h-7 px-2 text-xs bg-background hover:bg-muted text-blue-800 dark:text-blue-300 flex-shrink-0"
        >
          Search
        </Button>
      </form>
    </div>
  );
});

GlobalSearchBar.displayName = "GlobalSearchBar";

// Memoized pagination component
const PaginationControls = React.memo<{
  pagination: PaginationInfo;
  onPageChange: (page: number) => void;
  onPageSizeChange?: (pageSize: number) => void;
}>(({ pagination, onPageChange, onPageSizeChange }) => {
  const debounceTimeoutRef = useRef<ReturnType<typeof setTimeout>>();

  const handlePageChange = useCallback(
    (page: number) => {
      if (page >= 1 && page <= pagination.totalPages) {
        // Clear existing timeout to prevent rapid consecutive requests
        if (debounceTimeoutRef.current) {
          clearTimeout(debounceTimeoutRef.current);
        }

        // Debounce pagination requests to prevent rapid clicking
        debounceTimeoutRef.current = setTimeout(() => {
          onPageChange(page);
        }, 150); // 150ms debounce for pagination
      }
    },
    [onPageChange, pagination.totalPages],
  );

  const handlePageSizeChange = useCallback(
    (e: React.ChangeEvent<HTMLSelectElement>) => {
      const newSize = parseInt(e.target.value, 10);
      if (onPageSizeChange && newSize > 0) {
        onPageSizeChange(newSize);
      }
    },
    [onPageSizeChange],
  );

  // Cleanup timeout on unmount
  useEffect(() => {
    return () => {
      if (debounceTimeoutRef.current) {
        clearTimeout(debounceTimeoutRef.current);
      }
    };
  }, []);

  const currentPageSize = pagination.pageSize || 10;

  // Show options up to the first one that covers all records, but always keep
  // the active page size selectable — otherwise a size not in the trimmed set
  // (e.g. a 100 default over a 25-row result) leaves the <select> with no
  // matching option and the browser paints the first one (10), which no longer
  // reflects how many rows are actually shown.
  const totalCount = pagination.totalCount || 0;
  const firstCoveringOption = PAGE_SIZE_OPTIONS.find((size) => size >= totalCount);
  const pageSizeOptions = PAGE_SIZE_OPTIONS.filter((size) => {
    if (totalCount === 0) return true;
    if (size === currentPageSize) return true;
    return size <= totalCount || size === firstCoveringOption;
  });

  return (
    <div
      className={cn(
        "py-2 px-4 border-t sticky left-0 bg-background z-10 flex items-center justify-between",
        "border-border/70",
      )}
    >
      <Pagination className="mx-0 justify-start flex-1">
        <PaginationContent>
          <PaginationItem>
            <PaginationPrevious
              onClick={() => handlePageChange(pagination.page - 1)}
              className={cn(
                "h-8 px-2 text-xs",
                !pagination.hasPrev && "pointer-events-none opacity-50",
              )}
            />
          </PaginationItem>

          {/* First page */}
          {pagination.page > 2 && (
            <PaginationItem>
              <PaginationLink onClick={() => handlePageChange(1)} className="h-8 w-8 text-xs">
                1
              </PaginationLink>
            </PaginationItem>
          )}

          {/* Ellipsis for skipped pages */}
          {pagination.page > 3 && (
            <PaginationItem>
              <PageInputDialog pagination={pagination} onPageChange={handlePageChange}>
                <PaginationLink
                  className="h-8 w-8 text-xs cursor-pointer hover:bg-muted"
                  title="Select page"
                >
                  ...
                </PaginationLink>
              </PageInputDialog>
            </PaginationItem>
          )}

          {/* Previous page */}
          {pagination.page > 1 && (
            <PaginationItem>
              <PaginationLink
                onClick={() => handlePageChange(pagination.page - 1)}
                className="h-8 w-8 text-xs"
              >
                {pagination.page - 1}
              </PaginationLink>
            </PaginationItem>
          )}

          {/* Current page */}
          <PaginationItem>
            <PaginationLink isActive className="h-8 w-8 text-xs">
              {pagination.page}
            </PaginationLink>
          </PaginationItem>

          {/* Next page */}
          {pagination.page < pagination.totalPages && (
            <PaginationItem>
              <PaginationLink
                onClick={() => handlePageChange(pagination.page + 1)}
                className="h-8 w-8 text-xs"
              >
                {pagination.page + 1}
              </PaginationLink>
            </PaginationItem>
          )}

          {/* Ellipsis for skipped pages */}
          {pagination.page < pagination.totalPages - 2 && (
            <PaginationItem>
              <PageInputDialog pagination={pagination} onPageChange={handlePageChange}>
                <PaginationLink
                  className="h-8 w-8 text-xs cursor-pointer hover:bg-muted"
                  title="Select page"
                >
                  ...
                </PaginationLink>
              </PageInputDialog>
            </PaginationItem>
          )}

          {/* Last page */}
          {pagination.page < pagination.totalPages - 1 && (
            <PaginationItem>
              <PaginationLink
                onClick={() => handlePageChange(pagination.totalPages)}
                className="h-8 w-8 text-xs"
              >
                {pagination.totalPages}
              </PaginationLink>
            </PaginationItem>
          )}

          <PaginationItem>
            <PaginationNext
              onClick={() => handlePageChange(pagination.page + 1)}
              className={cn(
                "h-8 px-2 text-xs",
                !pagination.hasNext && "pointer-events-none opacity-50",
              )}
            />
          </PaginationItem>
        </PaginationContent>
      </Pagination>

      {/* Page size selector */}
      {onPageSizeChange && (
        <div className="flex items-center gap-2 ml-4 flex-shrink-0">
          <span className="text-xs text-muted-foreground">Rows:</span>
          <select
            value={currentPageSize}
            onChange={handlePageSizeChange}
            className="h-8 px-2 text-xs border border-input rounded bg-background text-foreground focus:outline-none focus:ring-1 focus:ring-ring"
          >
            {pageSizeOptions.map((size) => (
              <option key={size} value={size}>
                {size}
              </option>
            ))}
          </select>
        </div>
      )}
    </div>
  );
});

PaginationControls.displayName = "PaginationControls";

const QueryResultTable = React.memo<QueryResultTableProps>(
  ({
    data,
    pagination,
    onPageChange,
    onPageSizeChange,
    isLoading = false,
    onSearch,
    onClearSearch,
    onClearColumnFilter,
    searchState,
    onSort,
    ontologyId,
    cellId,
    onCellClick,
    selectedCell,
    getRowClassName,
  }) => {
    const { predicateName, columns, rows } = data;

    // Check if search is currently active
    const isSearchActive =
      !!searchState?.searchTerm ||
      !!(searchState?.columnFilters && Object.keys(searchState.columnFilters).length > 0);
    const activeColumnFilters = searchState?.columnFilters || {};
    const activeColumnIndices = Object.keys(activeColumnFilters).map(Number);

    // Current sorting state from pagination
    const currentOrderBy = pagination?.orderBy || [];

    const navigate = useNavigate();
    const canSeeGraphExplorer = usePermissionsStore((state) =>
      state.canSee("can_see_graph_explorer"),
    );

    // Hand off graph visualization to the Graph Explorer: deep-link with the
    // concept and its column list; role picking and rendering happen there.
    const handleOpenInGraphExplorer = useCallback(() => {
      const params = new URLSearchParams({
        concept: predicateName,
        columns: columns.join(","),
      });
      navigate(`/graph-explorer?${params.toString()}`);
    }, [columns, predicateName, navigate]);

    // Memoize the numeric column check to avoid recalculating on every render
    const isNumericColumn = useCallback(
      (columnIndex: number): boolean => {
        if (!rows || rows.length === 0) return false;

        try {
          // Check if all non-null values in this column are numbers
          return rows.every((row) => {
            if (!row || !Array.isArray(row)) return true; // Skip invalid rows

            const value = row[columnIndex];
            if (value === null || value === undefined) return true;

            // Handle array values - they're not numeric
            if (Array.isArray(value)) return false;

            // Handle object values - they're not numeric
            if (typeof value === "object") return false;

            return (
              (typeof value === "number" && !Number.isNaN(value)) ||
              (typeof value === "string" && !Number.isNaN(Number(value)) && value.trim() !== "")
            );
          });
        } catch (_error) {
          return false;
        }
      },
      [rows],
    );

    // Memoize the page change handler with scheduler to yield to main thread
    const handlePageChange = useCallback(
      (page: number) => {
        if (onPageChange && pagination && page >= 1 && page <= pagination.totalPages) {
          // Use scheduler API if available, otherwise fallback to setTimeout
          if ("scheduler" in window && "postTask" in (window as any).scheduler) {
            (window as any).scheduler.postTask(
              () => {
                onPageChange(page);
              },
              { priority: "user-blocking" },
            );
          } else {
            setTimeout(() => onPageChange(page), 0);
          }
        }
      },
      [onPageChange, pagination],
    );

    // Handle global search (clears column filters)
    const handleGlobalSearch = useCallback(
      (searchTerm: string) => {
        if (onSearch) {
          // Pass searchTerm only, no column filters
          onSearch(searchTerm, undefined);
        }
      },
      [onSearch],
    );

    // Handle column-specific filter - adds to existing filters
    const handleColumnFilter = useCallback(
      (value: string, columnIndex: number, operator: FilterOperator = "contains") => {
        if (onSearch) {
          const existingFilters = searchState?.columnFilters || {};
          const updatedFilters = { ...existingFilters, [columnIndex]: { value, operator } };
          onSearch(undefined, updatedFilters);
        }
      },
      [onSearch, searchState?.columnFilters],
    );

    // Handle clear all search
    const handleClearSearch = useCallback(() => {
      if (onClearSearch) {
        onClearSearch();
      }
    }, [onClearSearch]);

    // Handle clear individual column filter
    const handleClearColumnFilter = useCallback(
      (columnIndex: number) => {
        if (onClearColumnFilter) {
          onClearColumnFilter(columnIndex);
        } else if (onSearch) {
          // Fallback: remove this column from filters and re-search
          const existingFilters = searchState?.columnFilters || {};
          const updatedFilters = { ...existingFilters };
          delete updatedFilters[columnIndex];

          if (Object.keys(updatedFilters).length > 0) {
            // Still have other column filters
            onSearch(undefined, updatedFilters);
          } else {
            // No more column filters, clear all search
            if (onClearSearch) {
              onClearSearch();
            }
          }
        }
      },
      [onClearColumnFilter, onSearch, onClearSearch, searchState?.columnFilters],
    );

    // Handle column sorting - cycles through: none → asc → desc → none
    // Handle column sort from popover - accepts explicit direction (asc, desc, or null to clear)
    const handleColumnSort = useCallback(
      (columnIndex: number, direction: "asc" | "desc" | null) => {
        if (!onSort) return;

        let newOrderBy: OrderByItem[];

        if (direction === null) {
          // Clear sort for this column
          newOrderBy = currentOrderBy.filter((o) => o.position !== columnIndex);
        } else {
          const existingSort = currentOrderBy.find((o) => o.position === columnIndex);
          if (existingSort) {
            // Update existing sort direction
            newOrderBy = currentOrderBy.map((o) =>
              o.position === columnIndex ? { ...o, direction } : o,
            );
          } else {
            // Add new sort
            newOrderBy = [...currentOrderBy, { position: columnIndex, direction }];
          }
        }

        onSort(newOrderBy);
      },
      [onSort, currentOrderBy],
    );

    // Get sort direction for a column
    const getColumnSortDirection = useCallback(
      (columnIndex: number): "asc" | "desc" | null => {
        const sortItem = currentOrderBy.find((o) => o.position === columnIndex);
        return sortItem?.direction || null;
      },
      [currentOrderBy],
    );

    // Memoize the table header with column filters and sorting
    const tableHeader = useMemo(
      () => (
        <TableHeader>
          <TableRow className={cn("hover:bg-transparent", "bg-muted/20")}>
            {columns.map((column, idx) => {
              return (
                <TableHead
                  key={`${predicateName}-col-${idx}`}
                  className={cn(
                    "h-10 font-semibold px-4 py-2 border-b border-r last:border-r-0 whitespace-nowrap",
                    "text-foreground border-border/30",
                    isNumericColumn(idx) ? "text-right" : "text-left",
                  )}
                  style={{
                    whiteSpace: "nowrap",
                  }}
                >
                  <div className="flex items-center gap-0.5">
                    {/* Column name */}
                    <span className={isNumericColumn(idx) ? "flex-1 text-right" : ""}>
                      {column}
                    </span>
                    {/* Column options popover */}
                    <ColumnFilterPopover
                      columnIndex={idx}
                      columnName={column}
                      onFilter={handleColumnFilter}
                      onClearFilter={handleClearColumnFilter}
                      isFiltered={activeColumnIndices.includes(idx)}
                      currentFilterValue={activeColumnFilters[idx]}
                      currentSortDirection={getColumnSortDirection(idx)}
                      onSort={onSort ? handleColumnSort : undefined}
                    />
                  </div>
                </TableHead>
              );
            })}
          </TableRow>
        </TableHeader>
      ),
      [
        columns,
        predicateName,
        isNumericColumn,
        handleColumnFilter,
        handleClearColumnFilter,
        activeColumnIndices,
        activeColumnFilters,
        getColumnSortDirection,
        onSort,
        handleColumnSort,
        cellId,
        ontologyId,
      ],
    );

    // Helper function to check if rows data is properly structured
    const isRowsDataValid = (rows: any[]): boolean => {
      if (!rows || !Array.isArray(rows)) return false;

      // Empty array is valid if we have pagination info (query completed successfully)
      if (rows.length === 0) return true;

      // Check if all rows are arrays (properly structured)
      return rows.every((row) => Array.isArray(row));
    };

    // Show loading state if isLoading is true OR if we have no rows and no pagination info yet
    // OR if the rows data is not properly structured
    if (isLoading || ((!rows || rows.length === 0) && !pagination) || !isRowsDataValid(rows)) {
      return (
        <div className="overflow-visible w-auto max-w-full">
          <div
            className={cn(
              "rounded-md overflow-hidden inline-block min-w-[50%] bg-transparent border",
              "border-border",
            )}
          >
            {/* Table caption/header styled like Jupyter with softer colors */}
            <div
              className={cn(
                "py-2 px-4 font-semibold text-left flex justify-between items-center min-h-[44px]",
                "bg-blue-100 text-blue-800 dark:bg-blue-950/50 dark:text-blue-300",
              )}
            >
              <span>{predicateName}</span>
            </div>

            {/* Reserve space to prevent layout shift */}
            <div className="min-h-[200px] p-8 flex items-center justify-center">
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <PrometheuxSpinner size={16} />
                Loading results...
              </div>
            </div>

            {/* Reserve space for pagination to prevent layout shift */}
            <div className="h-12 bg-background border-t border-border/70 opacity-0">
              <div className="py-2 px-4">
                <div className="h-8 bg-muted rounded animate-pulse"></div>
              </div>
            </div>
          </div>
        </div>
      );
    }

    // Show empty results message if we have pagination info but no rows
    // (meaning the query completed successfully but returned no results)
    if (!rows || rows.length === 0) {
      return (
        <div className="overflow-visible w-auto max-w-full">
          <div
            className={cn(
              "rounded-md overflow-hidden inline-block min-w-[50%] bg-transparent border",
              "border-border",
            )}
          >
            {/* Table caption/header styled like Jupyter with softer colors */}
            <div
              className={cn(
                "py-2 px-4 font-semibold text-left min-h-[44px] flex items-center",
                "bg-blue-100 text-blue-800 dark:bg-blue-950/50 dark:text-blue-300",
              )}
            >
              <div className="flex items-center gap-3 w-full">
                <div className="flex items-center gap-2 flex-wrap">
                  <span>{predicateName}</span>
                  {onSearch && (
                    <GlobalSearchBar
                      onSearch={handleGlobalSearch}
                      onClear={handleClearSearch}
                      currentSearchTerm={
                        activeColumnIndices.length === 0 ? searchState?.searchTerm : undefined
                      }
                      isSearchActive={isSearchActive && activeColumnIndices.length === 0}
                    />
                  )}
                  {activeColumnIndices.length > 0 &&
                    activeColumnIndices.map((columnIdx) => {
                      const cf = activeColumnFilters[columnIdx];
                      const label =
                        typeof cf === "object" && cf
                          ? `${OPERATOR_LABELS[cf.operator]}${cf.value ? ` "${cf.value}"` : ""}`
                          : `"${cf}"`;
                      return (
                        <span
                          key={columnIdx}
                          className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-blue-200 text-blue-700 text-xs font-normal"
                        >
                          <Filter className="h-3 w-3" />
                          {columns[columnIdx]}: {label}
                          <button
                            onClick={() => handleClearColumnFilter(columnIdx)}
                            className="ml-0.5 p-0.5 rounded-full hover:bg-blue-300 transition-colors"
                            title={`Clear filter for ${columns[columnIdx]}`}
                          >
                            <X className="h-3 w-3" />
                          </button>
                        </span>
                      );
                    })}
                </div>
              </div>
            </div>

            <div className="p-8 flex flex-col items-center justify-center gap-3">
              <div className="text-sm text-muted-foreground">
                {isSearchActive
                  ? activeColumnIndices.length > 0
                    ? `No results found for filters on ${activeColumnIndices.map((idx) => columns[idx]).join(", ")}`
                    : `No results found for "${searchState?.searchTerm}"`
                  : "No results found"}
              </div>
              {isSearchActive && onClearSearch && (
                <Button variant="outline" size="sm" onClick={handleClearSearch} className="text-xs">
                  <X className="h-3 w-3 mr-1" />
                  Clear all filters
                </Button>
              )}
            </div>
          </div>
        </div>
      );
    }

    return (
      <div className="w-full overflow-x-auto" style={{ maxWidth: "100%", contain: "layout style" }}>
        <div
          className={cn(
            "rounded-md overflow-hidden bg-transparent border",
            "border-border",
            "inline-block",
          )}
          style={{ contain: "layout" }}
        >
          {/* Table caption/header styled like Jupyter with softer colors */}
          <div
            className={cn(
              "py-2 px-4 font-semibold text-left min-h-[44px] flex items-center",
              "bg-blue-100 text-blue-800 dark:bg-blue-950/50 dark:text-blue-300",
            )}
          >
            <div className="flex items-center justify-between gap-3 w-full">
              <div className="flex items-center gap-2 flex-wrap">
                <span>{predicateName}</span>
                {onSearch && (
                  <GlobalSearchBar
                    onSearch={handleGlobalSearch}
                    onClear={handleClearSearch}
                    currentSearchTerm={
                      activeColumnIndices.length === 0 ? searchState?.searchTerm : undefined
                    }
                    isSearchActive={isSearchActive && activeColumnIndices.length === 0}
                  />
                )}
                {activeColumnIndices.length > 0 &&
                  activeColumnIndices.map((columnIdx) => {
                    const cf = activeColumnFilters[columnIdx];
                    const label =
                      typeof cf === "object" && cf
                        ? `${OPERATOR_LABELS[cf.operator]}${cf.value ? ` "${cf.value}"` : ""}`
                        : `"${cf}"`;
                    return (
                      <span
                        key={columnIdx}
                        className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-blue-200 text-blue-700 text-xs font-normal"
                      >
                        <Filter className="h-3 w-3" />
                        {columns[columnIdx]}: {label}
                        <button
                          onClick={() => handleClearColumnFilter(columnIdx)}
                          className="ml-0.5 p-0.5 rounded-full hover:bg-blue-300 transition-colors"
                          title={`Clear filter for ${columns[columnIdx]}`}
                        >
                          <X className="h-3 w-3" />
                        </button>
                      </span>
                    );
                  })}
              </div>
              {/* Hand off to Graph Explorer (gated like the page itself) */}
              {canSeeGraphExplorer && ontologyId && cellId && (
                <button
                  type="button"
                  onClick={handleOpenInGraphExplorer}
                  className="flex items-center gap-1.5 px-3 py-1 text-xs rounded bg-background/50 text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300 whitespace-nowrap flex-shrink-0"
                >
                  <Waypoints className="h-3.5 w-3.5" />
                  Visualize in Graph Explorer
                </button>
              )}
            </div>
          </div>
          {/* Table View */}
          <div className="w-auto" style={{ willChange: isLoading ? "contents" : "auto" }}>
            <Table>
              {tableHeader}
              <VirtualizedTableBody
                rows={rows}
                predicateName={predicateName}
                isNumericColumn={isNumericColumn}
                maxHeight={400}
                columns={columns}
                onCellClick={onCellClick}
                selectedCell={selectedCell}
                getRowClassName={getRowClassName}
              />
            </Table>
          </div>
          {/* Pagination Controls - positioned on left and sticky during horizontal scroll */}
          {pagination && (
            <PaginationControls
              pagination={pagination}
              onPageChange={handlePageChange}
              onPageSizeChange={onPageSizeChange}
            />
          )}
          {/* Loading indicator */}
          {isLoading && (
            <div
              className={cn(
                "py-1 px-4 text-center text-xs text-muted-foreground border-t",
                "border-border/70 bg-muted/30",
              )}
            >
              Loading...
            </div>
          )}
        </div>
      </div>
    );
  },
);

QueryResultTable.displayName = "QueryResultTable";

export default QueryResultTable;
