import { Graph, type IElementEvent, type NodeData } from "@antv/g6";
import { useEffect, useMemo, useRef, useState } from "react";
import { useThemeStore } from "@/shared/store/themeStore";
import type { FetchResult } from "../../api/ConceptClient";
import type { GraphAnalyticsResult } from "../../api/GraphAnalyticsClient";
import { GraphAnalyticsPanel } from "./GraphAnalyticsPanel";
import {
  buildGraphData,
  buildLayout,
  EDGE_STROKE,
  LARGE_GRAPH_THRESHOLD,
  LAYOUTS,
  type LayoutType,
  NODE_FILL,
  NODE_LABEL_FILL,
  NODE_STROKE,
  PATH_PICK_LINE_WIDTH,
  PATH_SOURCE_STROKE,
  PATH_TARGET_STROKE,
  type PickMode,
  resolveGridStroke,
  truncateLabel,
} from "./graphWidget.utils";

interface GraphWidgetProps {
  data: FetchResult;
  xCol: number;
  yCol: number;
  fullscreen?: boolean;
  ontologyId?: string;
  predicateName?: string;
}

interface PathHighlightUpdate extends NodeData {
  id: string;
  style: { stroke: string; lineWidth: number };
}

function buildHighlightUpdate(
  id: string,
  graphData: { nodes: Array<{ id: string; _stroke?: string }> },
  pickedSource: string,
  pickedTarget: string,
): PathHighlightUpdate | null {
  const node = graphData.nodes.find((n) => n.id === id);
  if (!node) return null;
  if (id === pickedSource) {
    return { id, style: { stroke: PATH_SOURCE_STROKE, lineWidth: PATH_PICK_LINE_WIDTH } };
  }
  if (id === pickedTarget) {
    return { id, style: { stroke: PATH_TARGET_STROKE, lineWidth: PATH_PICK_LINE_WIDTH } };
  }
  return { id, style: { stroke: node._stroke ?? NODE_STROKE, lineWidth: 2 } };
}

interface UpdatableGraph {
  updateNodeData: (updates: PathHighlightUpdate[]) => void;
  draw?: () => void;
}

function applyPathHighlights(
  graph: UpdatableGraph,
  graphData: { nodes: Array<{ id: string; _stroke?: string }> },
  source: string,
  target: string,
  prev?: { source: string; target: string },
) {
  const ids = new Set<string>();
  if (prev?.source) ids.add(prev.source);
  if (prev?.target) ids.add(prev.target);
  if (source) ids.add(source);
  if (target) ids.add(target);
  if (ids.size === 0) return;
  const updates: PathHighlightUpdate[] = [];
  ids.forEach((id) => {
    const update = buildHighlightUpdate(id, graphData, source, target);
    if (update) updates.push(update);
  });
  if (updates.length === 0) return;
  graph.updateNodeData(updates);
  graph.draw?.();
}

export function GraphWidget({
  data,
  xCol,
  yCol,
  fullscreen = false,
  ontologyId,
  predicateName,
}: GraphWidgetProps) {
  const { theme } = useThemeStore();
  const containerRef = useRef<HTMLDivElement>(null);
  const graphRef = useRef<Graph | null>(null);
  const graphRenderedRef = useRef(false);

  const [analytics, setAnalytics] = useState<GraphAnalyticsResult | null>(null);
  const [pathSource, setPathSource] = useState<string>("");
  const [pathTarget, setPathTarget] = useState<string>("");
  const [pickMode, setPickMode] = useState<PickMode>(null);
  const graphData = useMemo(
    () => buildGraphData(data.rows, xCol, yCol, analytics),
    [data.rows, xCol, yCol, analytics],
  );

  const pickModeRef = useRef<PickMode>(pickMode);
  pickModeRef.current = pickMode;
  const pathSourceRef = useRef<string>(pathSource);
  pathSourceRef.current = pathSource;
  const pathTargetRef = useRef<string>(pathTarget);
  pathTargetRef.current = pathTarget;

  const isLargeGraph = graphData.nodes.length >= LARGE_GRAPH_THRESHOLD;

  const [layoutType, setLayoutType] = useState<LayoutType>(() =>
    graphData.nodes.length >= LARGE_GRAPH_THRESHOLD ? "force" : "dagre",
  );

  const layoutRef = useRef<LayoutType>(layoutType);
  layoutRef.current = layoutType;
  const isLargeGraphRef = useRef(isLargeGraph);
  isLargeGraphRef.current = isLargeGraph;
  const gridStrokeRef = useRef(resolveGridStroke(theme));
  gridStrokeRef.current = resolveGridStroke(theme);

  const prevIsLargeGraph = useRef(isLargeGraph);
  useEffect(() => {
    if (isLargeGraph === prevIsLargeGraph.current) return;
    prevIsLargeGraph.current = isLargeGraph;
    setLayoutType(isLargeGraph ? "force" : "dagre");
  }, [isLargeGraph]);

  useEffect(() => {
    if (!containerRef.current || graphData.nodes.length === 0) return;

    const large = isLargeGraphRef.current;

    const graph = new Graph({
      container: containerRef.current,
      autoResize: true,
      autoFit: "view",
      animation: large ? false : undefined,
      data: graphData,
      layout: buildLayout(layoutRef.current, large),
      node: {
        style: large
          ? {
              size: 8,
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              fill: (d: any) => d._fill ?? NODE_FILL,
              stroke: NODE_STROKE,
              lineWidth: 0.5,
            }
          : {
              size: 40,
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              fill: (d: any) => d._fill ?? NODE_FILL,
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              stroke: (d: any) => d._stroke ?? NODE_STROKE,
              lineWidth: 2,
              labelText: (d: { id: string }) => truncateLabel(String(d.id)),
              labelFill: NODE_LABEL_FILL,
              labelFontSize: 11,
              labelPlacement: "center",
            },
      },
      edge: {
        style: {
          stroke: EDGE_STROKE,
          lineWidth: large ? 0.5 : 1.5,
          endArrow: !large,
        },
      },
      behaviors: ["drag-canvas", "zoom-canvas", "drag-element"],
      plugins: [
        {
          type: "toolbar",
          position: "top-right",
          style: { marginTop: "8px", marginRight: "8px", borderRadius: "6px" },
          getItems: () => [
            { id: "zoom-in", value: "zoom-in" },
            { id: "zoom-out", value: "zoom-out" },
            { id: "auto-fit", value: "auto-fit" },
            { id: "reset", value: "reset" },
          ],
          onClick: (value: string) => {
            const current = graph.getZoom();
            switch (value) {
              case "zoom-in":
                graph.zoomTo(current * 1.2);
                break;
              case "zoom-out":
                graph.zoomTo(current * 0.8);
                break;
              case "auto-fit":
                graph.fitView();
                break;
              case "reset":
                graph.zoomTo(1).then(() => graph.fitCenter());
                break;
            }
          },
        },
        {
          key: "minimap",
          type: "minimap",
          size: [160, 100],
          position: "bottom-left",
        },
        {
          key: "grid-line",
          type: "grid-line",
          size: 20,
          stroke: gridStrokeRef.current,
          border: false,
          follow: true,
        },
      ],
    });

    graph.on<IElementEvent>("node:click", (evt) => {
      const id = String(evt?.target?.id ?? "");
      if (!id) return;
      const mode = pickModeRef.current;
      if (mode === "source") {
        setPathSource(id);
        setPickMode((m) => (m === "source" ? null : m));
      } else if (mode === "target") {
        setPathTarget(id);
        setPickMode((m) => (m === "target" ? null : m));
      }
    });

    graphRef.current = graph;
    graphRenderedRef.current = false;
    graph.render().then(() => {
      graphRenderedRef.current = true;
      applyPathHighlights(graph, graphData, pathSourceRef.current, pathTargetRef.current);
    });

    return () => {
      graphRenderedRef.current = false;
      graph.destroy();
      graphRef.current = null;
    };
  }, [graphData]); // eslint-disable-line react-hooks/exhaustive-deps

  const prevHighlightRef = useRef<{ source: string; target: string }>({
    source: "",
    target: "",
  });
  useEffect(() => {
    const graph = graphRef.current;
    if (!graph || !graphRenderedRef.current) return;
    const prev = prevHighlightRef.current;
    if (prev.source === pathSource && prev.target === pathTarget) return;
    applyPathHighlights(graph, graphData, pathSource, pathTarget, prev);
    prevHighlightRef.current = { source: pathSource, target: pathTarget };
  }, [pathSource, pathTarget, graphData]);

  useEffect(() => {
    const graph = graphRef.current;
    if (!graph || !graphRenderedRef.current) return;
    graph.layout(buildLayout(layoutType, isLargeGraphRef.current)).then(() => graph.fitView());
  }, [layoutType]);

  useEffect(() => {
    graphRef.current?.updatePlugin({ key: "grid-line", stroke: resolveGridStroke(theme) });
  }, [theme]);

  if (graphData.nodes.length === 0) {
    return <p className="text-xs text-muted-foreground py-4">No data</p>;
  }

  return (
    <div className="flex flex-col" style={{ height: fullscreen ? "100%" : 380, width: "100%" }}>
      <div className="flex items-center gap-2 pb-2 flex-shrink-0 flex-wrap">
        {ontologyId && predicateName && (
          <div className="w-full">
            <GraphAnalyticsPanel
              ontologyId={ontologyId}
              predicateName={predicateName}
              xCol={xCol}
              yCol={yCol}
              onResult={setAnalytics}
              pathSource={pathSource}
              pathTarget={pathTarget}
              pickMode={pickMode}
              onPathSourceChange={setPathSource}
              onPathTargetChange={setPathTarget}
              onPickModeChange={setPickMode}
            />
          </div>
        )}

        <span className="text-[11px] text-muted-foreground">Layout</span>
        <select
          value={layoutType}
          onChange={(e) => setLayoutType(e.target.value as LayoutType)}
          className="text-[11px] bg-background border border-border rounded px-2 py-0.5 text-foreground cursor-pointer focus:outline-none focus:ring-1 focus:ring-ring"
        >
          {LAYOUTS.map((l) => (
            <option key={l.value} value={l.value}>
              {l.label}
            </option>
          ))}
        </select>

        {isLargeGraph && (
          <span className="text-[10px] text-muted-foreground ml-1">
            {graphData.nodes.length.toLocaleString()} nodes · labels hidden
          </span>
        )}
      </div>

      <div
        ref={containerRef}
        className="flex-1 min-h-0"
        style={pickMode ? { cursor: "crosshair" } : undefined}
      />
    </div>
  );
}
