import { Maximize, ZoomIn, ZoomOut } from "lucide-react";

interface CanvasZoomControlsProps {
  onZoomIn: () => void;
  onZoomOut: () => void;
  onFitView: () => void;
}

/** Floating zoom in / zoom out / fit-view stack overlaid on the graph canvas. */
export function CanvasZoomControls({ onZoomIn, onZoomOut, onFitView }: CanvasZoomControlsProps) {
  return (
    <div className="absolute bottom-4 left-4 z-10 flex flex-col rounded-md border border-border bg-card shadow-sm overflow-hidden">
      <button
        type="button"
        title="Zoom in"
        onClick={onZoomIn}
        className="p-1.5 text-muted-foreground hover:bg-accent hover:text-accent-foreground transition-colors"
      >
        <ZoomIn className="h-3.5 w-3.5" />
      </button>
      <button
        type="button"
        title="Zoom out"
        onClick={onZoomOut}
        className="p-1.5 text-muted-foreground hover:bg-accent hover:text-accent-foreground transition-colors border-t border-border"
      >
        <ZoomOut className="h-3.5 w-3.5" />
      </button>
      <button
        type="button"
        title="Fit view"
        onClick={onFitView}
        className="p-1.5 text-muted-foreground hover:bg-accent hover:text-accent-foreground transition-colors border-t border-border"
      >
        <Maximize className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}
