import { AlertTriangle } from "lucide-react";

interface VisionWarningProps {
  /** Whether an image is attached to a model that cannot see one. */
  isVisible: boolean;
  model: string;
}

/**
 * Warns that the selected model cannot see an attached image. Advisory only —
 * the message still sends, and the agent is told in words what it was given.
 */
export function VisionWarning({ isVisible, model }: VisionWarningProps) {
  if (!isVisible) return null;
  return (
    <p className="flex items-center gap-1.5 text-amber-700 text-xs dark:text-amber-400">
      <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
      <span>{model} can't see images — pick a multimodal model to have it read this one.</span>
    </p>
  );
}
