import { Clock, Info, Loader2, Sparkles, Users2, X } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { useMyJoinRequests } from "@/features/teams/hooks/useMyJoinRequests";
import { useTeamSuggestion } from "@/features/teams/hooks/useTeamSuggestion";
import { TeamError } from "@/features/teams/types";
import { teamSuggestionDismissal } from "@/features/teams/utils/suggestionDismissal";
import { Button } from "@/shared/components/ui/button";
import CreateTeamDialog from "./CreateTeamDialog";

// Onboarding hint rendered on the Teams landing page. Pure polish — the
// core teams flow doesn't depend on it. Three shapes driven by
// `suggestion.action`:
//   * `none`                → render nothing.
//   * `create` /            → amber "start your team" tile with a primary CTA
//     `create_optional`       that opens CreateTeamDialog prefilled with
//                             `suggested_name`. `create_optional` softens the
//                             copy for the solo-user case.
//   * `join`                → domain-gated CTA. If the caller has no pending
//                             request for this team, show a real "Request to
//                             join" button. If a pending request already
//                             exists, swap to a passive "Request pending"
//                             state with a Cancel action.
//
// Dismissal is content-scoped: if the backend changes what it suggests
// (different team / different name / different action), the dismissal
// re-opens automatically.
const TeamSuggestionBanner: React.FC = () => {
  const { user } = useAuth();
  const userId = user?.id ?? "";
  const { suggestion } = useTeamSuggestion();
  const {
    requests: myJoinRequests,
    request: requestJoin,
    cancel: cancelJoin,
    isRequesting,
    requestingTeamId,
    isCancelling,
    cancellingRequestId,
  } = useMyJoinRequests();
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  // Bumping this forces a fresh read from localStorage so the banner hides
  // right after a click without needing an effect. When the suggestion itself
  // changes we re-render anyway (new `suggestion` object) and the
  // isDismissed check reads the new signature against the same storage slot.
  const [dismissTick, setDismissTick] = useState(0);

  if (!suggestion) return null;
  if (suggestion.action === "none") return null;
  // Referencing the tick keeps this dependent on the click, without an effect.
  void dismissTick;
  if (teamSuggestionDismissal.isDismissed(userId, suggestion)) return null;

  const handleDismiss = (): void => {
    teamSuggestionDismissal.dismiss(userId, suggestion);
    setDismissTick((t) => t + 1);
  };

  const handleCreateOpen = (): void => {
    setShowCreateDialog(true);
  };

  const handleCreateClose = (): void => {
    setShowCreateDialog(false);
  };

  const handleCreated = (): void => {
    // Once they've created a team the suggestion will refetch to `none`
    // via the mutation's invalidation. Clear the dismissal so future
    // suggestions can still show.
    teamSuggestionDismissal.clear(userId);
  };

  if (suggestion.action === "join") {
    return (
      <JoinSuggestionBanner
        teamId={suggestion.team?.id ?? null}
        teamName={suggestion.team?.name ?? "a team"}
        ownerEmail={suggestion.team?.owner_email ?? null}
        ownerUsername={suggestion.team?.owner_username ?? null}
        myRequests={myJoinRequests}
        onRequest={requestJoin}
        onCancel={cancelJoin}
        isRequesting={isRequesting}
        requestingTeamId={requestingTeamId}
        isCancelling={isCancelling}
        cancellingRequestId={cancellingRequestId}
        onDismiss={handleDismiss}
      />
    );
  }

  const isOptional = suggestion.action === "create_optional";
  const title = isOptional ? "Start a team when you're ready" : "Create your team";
  const description = isOptional
    ? "Teams let you share ontologies and manage members together. No pressure — you can do this anytime."
    : "Set up a team so your colleagues can join and collaborate on ontologies with you.";

  return (
    <>
      <BannerContainer>
        <BannerShell
          icon={<Sparkles className="h-4 w-4" />}
          title={title}
          description={description}
          onDismiss={handleDismiss}
          action={
            <Button type="button" size="sm" onClick={handleCreateOpen} className="gap-1.5">
              <Users2 className="h-3.5 w-3.5" />
              Create team
            </Button>
          }
        />
      </BannerContainer>
      <CreateTeamDialog
        isOpen={showCreateDialog}
        onClose={handleCreateClose}
        onCreated={handleCreated}
        prefillName={suggestion.suggested_name ?? undefined}
      />
    </>
  );
};

// -----------------------------------------------------------------------------
// Join-action variant — extracted so the parent stays focused on routing
// between actions. Owns the two sub-states (idle CTA vs. pending) and the
// error toasts for the 403/409 branches the backend surfaces on request.
// -----------------------------------------------------------------------------

interface JoinSuggestionBannerProps {
  teamId: string | null;
  teamName: string;
  ownerEmail: string | null;
  ownerUsername: string | null;
  myRequests: Array<{ id: string; team_id: string; status: string }>;
  onRequest: (teamId: string) => Promise<unknown>;
  onCancel: (input: { teamId: string; requestId: string }) => Promise<unknown>;
  isRequesting: boolean;
  requestingTeamId: string | null;
  isCancelling: boolean;
  cancellingRequestId: string | null;
  onDismiss: () => void;
}

const JoinSuggestionBanner: React.FC<JoinSuggestionBannerProps> = ({
  teamId,
  teamName,
  ownerEmail,
  ownerUsername,
  myRequests,
  onRequest,
  onCancel,
  isRequesting,
  requestingTeamId,
  isCancelling,
  cancellingRequestId,
  onDismiss,
}) => {
  const pendingRequest = teamId
    ? myRequests.find((r) => r.team_id === teamId && r.status === "pending")
    : undefined;
  const ownerLabel = ownerEmail ?? ownerUsername;
  const requestingThis = isRequesting && requestingTeamId === teamId;
  const cancellingThis = isCancelling && cancellingRequestId === pendingRequest?.id;

  const handleRequest = async (): Promise<void> => {
    if (!teamId) return;
    try {
      await onRequest(teamId);
      toast.success(`Requested to join ${teamName}. An admin will review it.`);
    } catch (err) {
      // Surface backend `detail` verbatim — spec calls out the 403 domain
      // mismatch and 409 already-member cases explicitly.
      const message =
        err instanceof TeamError
          ? err.message
          : "Could not send the join request. Please try again.";
      toast.error(message);
    }
  };

  const handleCancel = async (): Promise<void> => {
    if (!teamId || !pendingRequest) return;
    try {
      await onCancel({ teamId, requestId: pendingRequest.id });
      toast.success("Join request cancelled.");
    } catch (err) {
      const message =
        err instanceof TeamError ? err.message : "Could not cancel the request. Please try again.";
      toast.error(message);
    }
  };

  if (pendingRequest) {
    // Passive state — the request is in flight with the admins. Cancel is
    // the only outbound action; owner contact is still handy as a fallback
    // in case the admin didn't get the email.
    const description = ownerLabel
      ? `We've pinged the team owners. ${ownerLabel} will review — feel free to reach out if it's taking a while.`
      : "We've pinged the team owners. They'll review your request.";
    return (
      <BannerContainer>
        <BannerShell
          icon={<Clock className="h-4 w-4" />}
          title={`Request to join ${teamName} — pending`}
          description={description}
          onDismiss={onDismiss}
          action={
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleCancel}
              disabled={cancellingThis}
              className="gap-1.5"
            >
              {cancellingThis ? (
                <>
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  Cancelling…
                </>
              ) : (
                "Cancel request"
              )}
            </Button>
          }
        />
      </BannerContainer>
    );
  }

  const description = ownerLabel
    ? `Owned by ${ownerLabel}. Send a request and they'll review it.`
    : "Send a request and the team owners will review it.";
  return (
    <BannerContainer>
      <BannerShell
        icon={<Info className="h-4 w-4" />}
        title={`Join ${teamName}`}
        description={description}
        onDismiss={onDismiss}
        action={
          <Button
            type="button"
            size="sm"
            onClick={handleRequest}
            disabled={!teamId || requestingThis}
            className="gap-1.5"
          >
            {requestingThis ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                Sending…
              </>
            ) : (
              <>
                <Users2 className="h-3.5 w-3.5" />
                Request to join
              </>
            )}
          </Button>
        }
      />
    </BannerContainer>
  );
};

// Positioning wrapper — kept in the component so a `return null` above emits
// zero padding on the page. Matches the projects grid gutter.
const BannerContainer: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="px-8 pt-6">{children}</div>
);

interface BannerShellProps {
  icon: React.ReactNode;
  title: string;
  description: string;
  onDismiss: () => void;
  action?: React.ReactNode;
}

// Presentational wrapper — amber accents match the invitation card treatment
// so onboarding tiles read as a family. Uses semantic tokens for backgrounds
// so dark mode is automatic.
const BannerShell: React.FC<BannerShellProps> = ({
  icon,
  title,
  description,
  onDismiss,
  action,
}) => (
  <div className="relative flex flex-col gap-3 rounded-xl border border-amber-500/40 bg-amber-500/[0.05] p-4 sm:flex-row sm:items-center sm:gap-4 dark:border-amber-500/30 dark:bg-amber-500/[0.07]">
    <div className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-amber-500/15 text-amber-700 dark:text-amber-400">
      {icon}
    </div>
    <div className="min-w-0 flex-1">
      <p className="text-sm font-semibold text-foreground">{title}</p>
      <p className="mt-0.5 text-xs text-muted-foreground">{description}</p>
    </div>
    {action && <div className="flex-shrink-0">{action}</div>}
    <button
      type="button"
      onClick={onDismiss}
      className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-md text-muted-foreground/60 transition-colors hover:bg-secondary hover:text-foreground sm:relative sm:right-0 sm:top-0"
      aria-label="Dismiss"
    >
      <X className="h-3.5 w-3.5" />
    </button>
  </div>
);

export default TeamSuggestionBanner;
