import { useRef, useState } from "react";
import type { GraphTableQuery } from "@/features/concept-editor/api/ConceptEditorClient";
import { useConceptEditorClient } from "@/features/concept-editor/api/ConceptEditorClientContext";
import type {
  ColumnFilterValue,
  OrderByItem,
} from "@/features/concept-editor/components/query/components/QueryResultTable";
import type { ConceptData } from "@/features/concepts/api";
import { graphExplorerClient } from "../api/GraphExplorerClient";
import {
  type ConceptGraphData,
  collapseNodeNeighborhood,
  mergeConceptGraph,
  mergeTableSlice,
  parseConceptGraphPage,
  parseConceptGraphResponse,
} from "../conceptGraph.utils";
import type { GraphAnalyticsKey } from "../graphAnalytics";
import { DEFAULT_MAX_DEPTH, type GraphFunctionKey } from "../graphFunctions";
import { conceptGraphRoleIndices } from "../model.utils";
import type { ConceptGraphRoles } from "../types";

const GRAPH_PAGE_SIZE = 100;
/** Neighbors fetched per node expansion (the cap; "has more" surfaces a hint). */
const EXPAND_PAGE_SIZE = 100;
/** Cumulative node ceiling — block further expansion past this to stay responsive. */
const MAX_GRAPH_NODES = 2000;

export type ConceptGraphStatus = "idle" | "running" | "loading" | "ready" | "error";
export type ConceptGraphMode = "records" | GraphFunctionKey;

export interface GraphFunctionOptions {
  source: string;
  target: string;
  allPaths?: boolean;
  visited?: boolean;
  maxDepth?: number;
}

/** Server-side table query (sort / search / column filters / page size).
 * Records and traversal reshape the graph from the same fetch; analytics
 * applies it to the table only. */
export interface TableQueryState {
  orderBy: OrderByItem[];
  searchTerm: string;
  columnFilters: Record<number, ColumnFilterValue>;
  pageSize: number;
}

type GraphRoleIndices = { source: number; target: number; edge_value?: number };

/** Named options for a build-graph fetch (see the fetchGraph choke point). */
interface FetchGraphOptions {
  page: number;
  pageSize: number;
  mode: ConceptGraphMode;
  maxDepth?: number;
  sourceNode?: string;
  targetNode?: string;
  recompute?: boolean;
  allPaths?: boolean;
  visited?: boolean;
  /** Records-mode node expansion: fetch a single node's neighborhood. */
  nodeValue?: string;
}

interface ConceptGraphState {
  predicate: string | null;
  status: ConceptGraphStatus;
  error: string | null;
  data: ConceptGraphData | null;
  mode: ConceptGraphMode;
}

/** Records-mode node-expansion overlay state (grouped to keep the hook's
 * useState count low). All three are ephemeral and cleared on any re-seed.
 * Collapse is derived from live graph topology, so no provenance is tracked. */
interface ExpansionState {
  /** Nodes the user has expanded (their neighbors are merged into the graph). */
  expandedNodeIds: Set<string>;
  /** Nodes with an expansion fetch in flight (for spinners). */
  expandingNodeIds: Set<string>;
  /** Nodes whose last expansion hit the EXPAND_PAGE_SIZE cap ("showing first N"). */
  cappedNodeIds: Set<string>;
  /** Last neighbor page fetched per expanded node — drives "load more". */
  pageByNode: Record<string, number>;
}

const EMPTY_EXPANSION: ExpansionState = {
  expandedNodeIds: new Set(),
  expandingNodeIds: new Set(),
  cappedNodeIds: new Set(),
  pageByNode: {},
};

interface GraphRequest {
  concept: ConceptData;
  roles: ConceptGraphRoles;
  mode: ConceptGraphMode;
  sourceNode?: string;
  targetNode?: string;
  allPaths?: boolean;
  visited?: boolean;
  maxDepth?: number;
  /** Concept to run when results are missing — e.g. the parent concept of an
   * intermediate predicate (intermediates cannot be run directly). */
  runPredicate?: string;
}

interface UseConceptGraphReturn extends ConceptGraphState {
  isBusy: boolean;
  tableQuery: TableQueryState;
  expandedNodeIds: Set<string>;
  expandingNodeIds: Set<string>;
  cappedNodeIds: Set<string>;
  show: (concept: ConceptData, roles: ConceptGraphRoles, runPredicate?: string) => void;
  setMode: (mode: ConceptGraphMode) => void;
  loadFunction: (key: GraphFunctionKey, options: GraphFunctionOptions) => void;
  runAnalytics: (key: GraphAnalyticsKey, params: Record<string, unknown>) => void;
  clearAnalytics: () => void;
  goToPage: (page: number) => void;
  expandNode: (nodeId: string) => void;
  loadMoreNeighbors: (nodeId: string) => void;
  collapseNode: (nodeId: string) => void;
  setSort: (orderBy: OrderByItem[]) => void;
  setSearch: (searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) => void;
  clearSearch: () => void;
  clearColumnFilter: (columnIndex: number) => void;
  setPageSize: (pageSize: number) => void;
  close: () => void;
}

const IDLE_STATE: ConceptGraphState = {
  predicate: null,
  status: "idle",
  error: null,
  data: null,
  mode: "records",
};

const DEFAULT_TABLE_QUERY: TableQueryState = {
  orderBy: [],
  searchTerm: "",
  columnFilters: {},
  pageSize: GRAPH_PAGE_SIZE,
};

function conceptColumns(concept: ConceptData): string[] {
  return concept.column_names ?? Object.keys(concept.fields ?? {});
}

/** Convert the UI table-query state into the endpoint wire form. */
function toGraphTableQuery(query: TableQueryState): GraphTableQuery {
  const columnFilters = Object.entries(query.columnFilters).map(([position, filter]) => ({
    position: Number(position),
    value: filter.value,
    operator: filter.operator,
  }));
  const searchTerm = query.searchTerm.trim();
  return {
    order_by: query.orderBy.length > 0 ? query.orderBy : undefined,
    search_term: searchTerm.length > 0 ? searchTerm : undefined,
    column_filters: columnFilters.length > 0 ? columnFilters : undefined,
  };
}

/**
 * Orchestrates the concept-graph flow: run the concept if it has no results
 * yet (WebSocket stream), then fetch its results as a graph through the
 * build-graph endpoint — either as paginated edge records or as paths
 * between two nodes — and expose them as explorer node/edge records.
 */
export function useConceptGraph(ontologyId: string, scope: string): UseConceptGraphReturn {
  const clientFromContext = useConceptEditorClient();
  const clientRef = useRef(clientFromContext);
  const lastRequestRef = useRef<GraphRequest | null>(null);
  const activeAnalyticsRef = useRef<{
    key: GraphAnalyticsKey;
    params: Record<string, unknown>;
  } | null>(null);
  const populatedRef = useRef(new Set<string>());
  // The ref is the source of truth for in-flight fetches (updated synchronously);
  // the state mirrors it so the table can render active sort/search/filters.
  const tableQueryRef = useRef<TableQueryState>(DEFAULT_TABLE_QUERY);
  const [tableQuery, setTableQuery] = useState<TableQueryState>(DEFAULT_TABLE_QUERY);
  const [state, setState] = useState<ConceptGraphState>(IDLE_STATE);
  // Records-mode node-expansion overlay (which nodes are expanded / expanding /
  // capped). Collapse reads live graph topology, so no seed/provenance refs.
  const [expansion, setExpansion] = useState<ExpansionState>(EMPTY_EXPANSION);

  // Clear all expansion overlay state — called on every re-seed (full graph
  // replace) so expansions never leak across seeds.
  const resetExpansion = () => {
    setExpansion(EMPTY_EXPANSION);
  };

  const applyTableQuery = (next: TableQueryState) => {
    tableQueryRef.current = next;
    setTableQuery(next);
  };

  // Reset sort/search/filters (columns differ across concepts/modes) but keep
  // the chosen page size.
  const resetTableQuery = () => {
    applyTableQuery({ ...DEFAULT_TABLE_QUERY, pageSize: tableQueryRef.current.pageSize });
  };

  // Single choke point for the 15-arg positional build-graph call: every fetch
  // (seed load, records paging, node expansion) goes through here with named
  // options and always the current table query.
  const fetchGraph = (predicate: string, indices: GraphRoleIndices, opts: FetchGraphOptions) =>
    clientRef.current.buildGraphFromData(
      ontologyId,
      predicate,
      indices,
      scope,
      opts.page,
      opts.pageSize,
      opts.mode,
      opts.maxDepth ?? DEFAULT_MAX_DEPTH,
      opts.sourceNode,
      opts.targetNode,
      opts.recompute,
      opts.allPaths ?? true,
      opts.visited ?? true,
      toGraphTableQuery(tableQueryRef.current),
      opts.nodeValue,
    );

  const load = async (request: GraphRequest, page: number, recompute?: boolean) => {
    const { concept, roles, mode } = request;
    const predicate = concept.predicate_name;
    const indices = conceptGraphRoleIndices(roles, conceptColumns(concept));
    if (!indices) {
      setState({
        predicate,
        status: "error",
        error: "The assigned columns no longer exist on this concept.",
        data: null,
        mode,
      });
      return;
    }

    lastRequestRef.current = request;
    // A plain records/traversal load leaves any analytics overlay behind.
    activeAnalyticsRef.current = null;
    // A full graph replace re-seeds the canvas — drop any expansion overlay.
    resetExpansion();
    try {
      const runPredicate = request.runPredicate ?? predicate;
      const isPopulated = concept.is_populated || populatedRef.current.has(runPredicate);
      if (!isPopulated) {
        setState({ predicate, status: "running", error: null, data: null, mode });
        await clientRef.current.runConceptStream(runPredicate, () => {}, false);
        populatedRef.current.add(runPredicate);
      }
      setState((prev) => ({ ...prev, predicate, status: "loading", error: null, mode }));
      const response = await fetchGraph(predicate, indices, {
        page,
        pageSize: tableQueryRef.current.pageSize,
        mode,
        maxDepth: request.maxDepth,
        sourceNode: request.sourceNode || undefined,
        targetNode: request.targetNode || undefined,
        recompute,
        allPaths: request.allPaths,
        visited: request.visited,
      });
      const data = parseConceptGraphResponse(response);
      if (!data) throw new Error("Unexpected graph response from the server");
      setState({ predicate, status: "ready", error: null, data, mode });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Failed to build the graph";
      setState({ predicate, status: "error", error: message, data: null, mode });
    }
  };

  /**
   * Records-mode table paging, decoupled from the graph: fetch the page but
   * merge only the tabular slice (columns/rows/pagination), leaving the
   * persistent graph and its expansions intact.
   */
  const loadTableSlice = async (page: number) => {
    const last = lastRequestRef.current;
    if (!last) return;
    const { concept, roles } = last;
    const predicate = concept.predicate_name;
    const indices = conceptGraphRoleIndices(roles, conceptColumns(concept));
    if (!indices) return;
    setState((prev) => ({ ...prev, status: "loading", error: null }));
    try {
      const response = await fetchGraph(predicate, indices, {
        page,
        pageSize: tableQueryRef.current.pageSize,
        mode: "records",
      });
      const full = parseConceptGraphResponse(response);
      if (!full) throw new Error("Unexpected graph response from the server");
      setState((prev) =>
        prev.data
          ? {
              ...prev,
              status: "ready",
              error: null,
              data: mergeTableSlice(prev.data, {
                columns: full.columns,
                rows: full.rows,
                pagination: full.pagination,
              }),
            }
          : { ...prev, status: "ready", error: null, data: full },
      );
    } catch (error) {
      const message = error instanceof Error ? error.message : "Failed to load the page";
      setState((prev) => ({ ...prev, status: "error", error: message }));
    }
  };

  /**
   * Fetch one page of a node's cross-page neighbors (both directions) and
   * additively merge them into the persistent graph. Shared by the initial
   * expand (page 1) and "load more" (next page); concurrent runs compose via
   * functional setState. `has_next` on the neighbor query marks the node capped.
   */
  const runExpansion = async (nodeId: string, page: number) => {
    const last = lastRequestRef.current;
    if (!last || state.mode !== "records") return;
    const currentCount = state.data ? Object.keys(state.data.nodes).length : 0;
    if (currentCount >= MAX_GRAPH_NODES) {
      setState((prev) => ({
        ...prev,
        error: `Graph is at the ${MAX_GRAPH_NODES}-node limit — collapse a node before expanding more.`,
      }));
      return;
    }

    const { concept, roles } = last;
    const predicate = concept.predicate_name;
    const indices = conceptGraphRoleIndices(roles, conceptColumns(concept));
    if (!indices) return;

    setExpansion((prev) => ({
      ...prev,
      expandingNodeIds: new Set(prev.expandingNodeIds).add(nodeId),
    }));
    try {
      const response = await fetchGraph(predicate, indices, {
        page,
        pageSize: EXPAND_PAGE_SIZE,
        mode: "records",
        nodeValue: nodeId,
      });
      const addition = parseConceptGraphResponse(response);
      if (!addition) throw new Error("Unexpected graph response from the server");
      const wasCapped = addition.pagination?.has_next ?? false;
      setState((prev) =>
        prev.data ? { ...prev, data: mergeConceptGraph(prev.data, addition) } : prev,
      );
      setExpansion((prev) => {
        const expandingNodeIds = new Set(prev.expandingNodeIds);
        expandingNodeIds.delete(nodeId);
        const cappedNodeIds = new Set(prev.cappedNodeIds);
        if (wasCapped) cappedNodeIds.add(nodeId);
        else cappedNodeIds.delete(nodeId);
        return {
          expandedNodeIds: new Set(prev.expandedNodeIds).add(nodeId),
          expandingNodeIds,
          cappedNodeIds,
          pageByNode: { ...prev.pageByNode, [nodeId]: page },
        };
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Failed to expand the node";
      setExpansion((prev) => {
        const expandingNodeIds = new Set(prev.expandingNodeIds);
        expandingNodeIds.delete(nodeId);
        return { ...prev, expandingNodeIds };
      });
      setState((prev) => ({ ...prev, error: message }));
    }
  };

  const expandNode = (nodeId: string) => {
    if (state.mode !== "records") return;
    if (expansion.expandedNodeIds.has(nodeId) || expansion.expandingNodeIds.has(nodeId)) return;
    void runExpansion(nodeId, 1);
  };

  /**
   * Records-mode "load more": pull the next capped batch of an already-expanded
   * node's neighbors. No-op if the node isn't expanded or a fetch is in flight.
   */
  const loadMoreNeighbors = (nodeId: string) => {
    if (state.mode !== "records") return;
    if (!expansion.expandedNodeIds.has(nodeId) || expansion.expandingNodeIds.has(nodeId)) return;
    const nextPage = (expansion.pageByNode[nodeId] ?? 1) + 1;
    void runExpansion(nodeId, nextPage);
  };

  /**
   * Collapse a node's neighborhood: hide the neighbors wired to it *only*
   * (pendant leaves), whether they came from the seed sample or a prior
   * expansion — neighbors also connected elsewhere stay. Purely topological, so
   * it works even when the node's edges were already on the sampled page.
   * Reversible by expanding the node again.
   */
  const collapseNode = (nodeId: string) => {
    if (state.mode !== "records" || !state.data) return;
    const { data, removedNodeIds } = collapseNodeNeighborhood(state.data, nodeId);
    const removed = new Set(removedNodeIds);
    setExpansion((prev) => {
      const keep = (id: string) => id !== nodeId && !removed.has(id);
      return {
        expandedNodeIds: new Set([...prev.expandedNodeIds].filter(keep)),
        expandingNodeIds: new Set([...prev.expandingNodeIds].filter(keep)),
        cappedNodeIds: new Set([...prev.cappedNodeIds].filter(keep)),
        pageByNode: Object.fromEntries(Object.entries(prev.pageByNode).filter(([id]) => keep(id))),
      };
    });
    setState((prev) => (prev.data ? { ...prev, data } : prev));
  };

  const show = (concept: ConceptData, roles: ConceptGraphRoles, runPredicate?: string) => {
    resetTableQuery();
    void load({ concept, roles, mode: "records", runPredicate }, 1);
  };

  const setMode = (mode: ConceptGraphMode) => {
    if (mode === state.mode) return;
    const last = lastRequestRef.current;
    if (!last) return;
    resetTableQuery();
    if (mode === "records") {
      // Records mode has no extra inputs — reload immediately.
      void load({ ...last, mode, sourceNode: undefined, targetNode: undefined }, 1);
      return;
    }
    // Traversal modes wait for the user to press Load; just switch the toolbar.
    setState((prev) => ({ ...prev, mode }));
  };

  const loadFunction = (key: GraphFunctionKey, options: GraphFunctionOptions) => {
    const last = lastRequestRef.current;
    if (!last) return;
    resetTableQuery();
    void load(
      {
        ...last,
        mode: key,
        sourceNode: options.source,
        targetNode: options.target,
        allPaths: options.allPaths,
        visited: options.visited,
        maxDepth: options.maxDepth,
      },
      1,
      true,
    );
  };

  const loadAnalytics = async (
    key: GraphAnalyticsKey,
    params: Record<string, unknown>,
    page: number,
    recompute: boolean,
  ) => {
    const last = lastRequestRef.current;
    if (!last) return;
    const { concept, roles } = last;
    const predicate = concept.predicate_name;
    const indices = conceptGraphRoleIndices(roles, conceptColumns(concept));
    if (!indices) {
      setState({
        predicate,
        status: "error",
        error: "The assigned columns no longer exist on this concept.",
        data: null,
        mode: "records",
      });
      return;
    }

    activeAnalyticsRef.current = { key, params };
    // A recompute rebuilds the overlay graph — re-seed and drop expansions.
    if (recompute) resetExpansion();
    setState((prev) => ({ ...prev, predicate, status: "loading", error: null, mode: "records" }));
    try {
      const query = tableQueryRef.current;
      const tableQueryPayload = toGraphTableQuery(query);
      const response = await graphExplorerClient.runAnalytics(ontologyId, predicate, {
        column_roles: { source: indices.source, target: indices.target },
        function: key,
        function_params: params,
        project: { scope },
        page,
        page_size: query.pageSize,
        recompute,
        order_by: tableQueryPayload.order_by,
        search_term: tableQueryPayload.search_term,
        column_filters: tableQueryPayload.column_filters,
      });
      // Page changes / table-query changes (no recompute) return only the table
      // slice — keep the existing overlay graph and swap in the new rows.
      if (!recompute) {
        const slice = parseConceptGraphPage(response);
        if (!slice) throw new Error("Unexpected analytics response from the server");
        setState((prev) =>
          prev.data
            ? {
                ...prev,
                predicate,
                status: "ready",
                error: null,
                mode: "records",
                data: { ...prev.data, ...slice },
              }
            : {
                predicate,
                status: "error",
                error: "No graph to page.",
                data: null,
                mode: "records",
              },
        );
        return;
      }
      const data = parseConceptGraphResponse(response);
      if (!data) throw new Error("Unexpected analytics response from the server");
      setState({ predicate, status: "ready", error: null, data, mode: "records" });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Failed to run graph analytics";
      setState({ predicate, status: "error", error: message, data: null, mode: "records" });
    }
  };

  const runAnalytics = (key: GraphAnalyticsKey, params: Record<string, unknown>) => {
    resetTableQuery();
    void loadAnalytics(key, params, 1, true);
  };

  const clearAnalytics = () => {
    const last = lastRequestRef.current;
    if (!last) return;
    resetTableQuery();
    // Reloading the plain Records graph drops the analytics overlay (the
    // build-graph response carries no analytics_type/range) and clears the ref.
    void load({ ...last, mode: "records", sourceNode: undefined, targetNode: undefined }, 1);
  };

  const goToPage = (page: number) => {
    const analytics = activeAnalyticsRef.current;
    if (analytics) {
      // Page an active analytics overlay from its persisted parquet (no recompute).
      void loadAnalytics(analytics.key, analytics.params, page, false);
      return;
    }
    const last = lastRequestRef.current;
    if (!last) return;
    // Records mode: the graph is a persistent explore canvas, so paging updates
    // only the table slice and leaves the graph + expansions intact. Traversal
    // mode pages graph and table together (full replace).
    if (last.mode === "records") {
      void loadTableSlice(page);
      return;
    }
    void load(last, page);
  };

  // Re-run the current query at page 1 after a sort/search/filter change.
  // Analytics keeps its stable overlay (recompute=false); records/traversal
  // reshape the graph from the same fetch.
  const refetchFirstPage = () => {
    const analytics = activeAnalyticsRef.current;
    if (analytics) {
      void loadAnalytics(analytics.key, analytics.params, 1, false);
      return;
    }
    const last = lastRequestRef.current;
    if (last) void load(last, 1);
  };

  const setSort = (orderBy: OrderByItem[]) => {
    applyTableQuery({ ...tableQueryRef.current, orderBy });
    refetchFirstPage();
  };

  const setSearch = (searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) => {
    // A global search clears column filters; a column filter clears the term.
    const next =
      searchTerm !== undefined
        ? { ...tableQueryRef.current, searchTerm, columnFilters: {} }
        : { ...tableQueryRef.current, searchTerm: "", columnFilters: columnFilters ?? {} };
    applyTableQuery(next);
    refetchFirstPage();
  };

  const clearSearch = () => {
    applyTableQuery({ ...tableQueryRef.current, searchTerm: "", columnFilters: {} });
    refetchFirstPage();
  };

  const clearColumnFilter = (columnIndex: number) => {
    const columnFilters = { ...tableQueryRef.current.columnFilters };
    delete columnFilters[columnIndex];
    applyTableQuery({ ...tableQueryRef.current, columnFilters });
    refetchFirstPage();
  };

  const setPageSize = (pageSize: number) => {
    applyTableQuery({ ...tableQueryRef.current, pageSize });
    refetchFirstPage();
  };

  const close = () => {
    lastRequestRef.current = null;
    activeAnalyticsRef.current = null;
    applyTableQuery(DEFAULT_TABLE_QUERY);
    resetExpansion();
    setState(IDLE_STATE);
  };

  return {
    ...state,
    isBusy: state.status === "running" || state.status === "loading",
    tableQuery,
    expandedNodeIds: expansion.expandedNodeIds,
    expandingNodeIds: expansion.expandingNodeIds,
    cappedNodeIds: expansion.cappedNodeIds,
    show,
    setMode,
    loadFunction,
    runAnalytics,
    clearAnalytics,
    goToPage,
    expandNode,
    loadMoreNeighbors,
    collapseNode,
    setSort,
    setSearch,
    clearSearch,
    clearColumnFilter,
    setPageSize,
    close,
  };
}
