import {
  AlertCircle,
  AlignLeft,
  Check,
  CheckCircle,
  ChevronDown,
  FastForward,
  Link,
  Play,
  RotateCcw,
  Save,
  Settings2,
  Square,
  Trash,
  X,
  XCircle,
} from "lucide-react";
import React, { useCallback, useMemo, useState } from "react";
import * as Icons from "simple-icons";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { DatabricksService } from "@/features/compute/api/databricksService";
import { ReadOnlyGate } from "@/features/ontologies/sharing/components/ReadOnlyGate";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/shared/components/ui/alert-dialog";
import { Button } from "@/shared/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";
import type { CellToolbarProps as BaseCellToolbarProps } from "../types/editorTypes";

// Simple Icons wrapper component
const SimpleIcon: React.FC<{
  iconData: any;
  size: number;
  className?: string;
}> = ({ iconData, size, className }) => {
  if (!iconData) return null;

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      className={className}
      fill={`#${iconData.hex}`}
    >
      <path d={iconData.path} />
    </svg>
  );
};

interface CellToolbarProps extends BaseCellToolbarProps {
  onToggleSettings?: () => void;
  isSettingsActive?: boolean;
  onIndentCode?: (cellId: string) => void;
  useDatabricks?: boolean;
  onToggleDatabricks?: (cellId: string) => void;
  onToggleBindEditor?: () => void;
  isBindEditorActive?: boolean;
  onStopCell?: (cellId: string) => Promise<void>;
  readOnly?: boolean;
}

const CellToolbar: React.FC<CellToolbarProps> = ({
  cellId,
  code,
  isRunning,
  isCellSaving,
  hasResult,
  hasPersistedResults,
  isModified,
  onRunCell,
  onStopCell,
  onDeleteCell,
  onClearResults,
  onRestoreResults,
  onSaveCell,
  onToggleSettings,
  isSettingsActive = false,
  onIndentCode,
  useDatabricks = false,
  onToggleDatabricks,
  onToggleBindEditor,
  isBindEditorActive = false,
  readOnly = false,
}) => {
  const canEditOntologies = usePermissionsStore((state) => state.canEdit("can_edit_projects"));
  const readOnlyHint = readOnly ? "This concept is read-only on this shared ontology" : undefined;

  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [forceRerun, setForceRerun] = useState(true);
  const [isValidatingDatabricks, setIsValidatingDatabricks] = useState(false);
  const [validationModal, setValidationModal] = useState<{
    isOpen: boolean;
    type: "error" | "success";
    title: string;
    message: string;
    actionRequired?: string;
  }>({
    isOpen: false,
    type: "error",
    title: "",
    message: "",
    actionRequired: "",
  });

  const handleClearResults = useCallback(() => {
    if (onClearResults) {
      onClearResults(cellId);
    }
  }, [cellId, onClearResults]);

  const handleRestoreResults = useCallback(() => {
    if (onRestoreResults) {
      onRestoreResults(cellId);
    }
  }, [cellId, onRestoreResults]);

  // Add handler for saving the cell
  const handleSaveCell = useCallback(async () => {
    if (!onSaveCell) return;
    try {
      setIsSaving(true);
      await onSaveCell(cellId);
    } catch (error) {
      console.error("Error saving cell:", error);
    } finally {
      setIsSaving(false);
    }
  }, [cellId, onSaveCell]);

  // Add handler for stopping the cell
  const handleStopCell = useCallback(async () => {
    if (!onStopCell) return;
    try {
      await onStopCell(cellId);
    } catch (error) {
      console.error("Error stopping cell:", error);
    }
  }, [cellId, onStopCell]);

  // Add handler for deleting the cell
  const handleDeleteCell = useCallback(async () => {
    if (!onDeleteCell) return;
    try {
      setIsDeleting(true);
      await onDeleteCell(cellId);
      setDialogOpen(false);
    } catch (error) {
      console.error("Error deleting cell:", error);
    } finally {
      setIsDeleting(false);
    }
  }, [cellId, onDeleteCell]);

  // Safely check if code is valid and not empty
  const isCodeEmpty = useMemo(() => {
    return typeof code !== "string" || code.trim() === "";
  }, [code]);

  // Validate Databricks configuration
  const databricksValidation = useMemo(() => {
    return DatabricksService.validateDatabricksForExecution();
  }, []);

  // Get current Databricks configuration for display
  const databricksConfig = useMemo(() => {
    return DatabricksService.getCurrentDatabricksConfig();
  }, []);

  // Handle Databricks toggle with live validation
  const handleDatabricksToggle = useCallback(async () => {
    // If Databricks is currently enabled, just disable it without validation
    if (useDatabricks) {
      setValidationModal({
        isOpen: true,
        type: "success",
        title: "Databricks Disabled",
        message: "Cell will now execute using Prometheux resources",
        actionRequired: undefined,
      });

      if (onToggleDatabricks) {
        onToggleDatabricks(cellId);
      }
      return;
    }

    // If enabling Databricks, perform validation
    // First check static validation
    if (!databricksValidation.isValid) {
      setValidationModal({
        isOpen: true,
        type: "error",
        title: "Configuration Required",
        message: databricksValidation.errorMessage || "Databricks configuration is incomplete",
        actionRequired: databricksValidation.actionRequired,
      });
      return;
    }

    // If static validation passes, perform comprehensive validation
    setIsValidatingDatabricks(true);
    try {
      const resourceValidation = await DatabricksService.validateDatabricksWithResourceStatus();
      if (!resourceValidation.isValid) {
        setValidationModal({
          isOpen: true,
          type: "error",
          title: "Resource Validation Failed",
          message: resourceValidation.errorMessage || "Databricks resources are not ready",
          actionRequired: resourceValidation.actionRequired,
        });
        return;
      }

      // If comprehensive validation passes, show success and enable Databricks mode
      setValidationModal({
        isOpen: true,
        type: "success",
        title: "Databricks Ready!",
        message: "All resources are running and ready for execution",
        actionRequired: undefined,
      });

      if (onToggleDatabricks) {
        onToggleDatabricks(cellId);
      }
    } catch (error) {
      setValidationModal({
        isOpen: true,
        type: "error",
        title: "Validation Error",
        message:
          "Failed to validate Databricks resources. Please check your settings and try again.",
        actionRequired: "Go to Integration > Databricks and verify your configuration",
      });
    } finally {
      setIsValidatingDatabricks(false);
    }
  }, [databricksValidation, onToggleDatabricks, cellId, useDatabricks]);
  return (
    <div
      className={`rounded-md px-2 py-1 flex items-center justify-between pr-2 ${isModified ? "bg-amber-100 dark:bg-amber-900/30" : "bg-transparent"}`}
    >
      <div className="gap-1 flex flex-wrap items-center">
        {/* Bind Editor Toggle */}
        {onToggleBindEditor && canEditOntologies && (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                type="button"
                onClick={onToggleBindEditor}
                className={`h-6 w-6 ${isBindEditorActive ? "bg-muted" : ""}`}
              >
                <Link className="h-3.5 w-3.5" />
              </Button>
            </TooltipTrigger>
            <TooltipContent>Data bindings</TooltipContent>
          </Tooltip>
        )}
        {/* Settings Button */}
        {onToggleSettings && canEditOntologies && (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                type="button"
                onClick={onToggleSettings}
                className={`h-6 w-6 ${isSettingsActive ? "bg-muted" : ""}`}
              >
                <Settings2 className="h-3.5 w-3.5" />
              </Button>
            </TooltipTrigger>
            <TooltipContent>Settings</TooltipContent>
          </Tooltip>
        )}
        {isModified && (
          <div className="text-xs text-amber-600 dark:text-amber-400 font-medium">Modified</div>
        )}
        {/* Play / Stop Button with run-mode dropdown */}
        {isRunning && onStopCell ? (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button variant="ghost" size="icon" onClick={handleStopCell} className="h-6 w-6">
                <Square className="h-3.5 w-3.5" />
              </Button>
            </TooltipTrigger>
            <TooltipContent>Stop execution</TooltipContent>
          </Tooltip>
        ) : (
          <div className="flex items-center">
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => onRunCell(cellId, forceRerun)}
                  disabled={isCodeEmpty || isRunning}
                  className="h-6 w-6 rounded-r-none"
                >
                  {forceRerun ? <FastForward className="h-4 w-4" /> : <Play className="h-4 w-4" />}
                </Button>
              </TooltipTrigger>
              <TooltipContent>
                {forceRerun ? "Run workflow" : "Run cell"}{" "}
                <span className="ml-2 text-xs text-muted-foreground">⇧⏎</span>
              </TooltipContent>
            </Tooltip>
            <DropdownMenu>
              <Tooltip>
                <TooltipTrigger asChild>
                  <DropdownMenuTrigger asChild>
                    <Button
                      variant="ghost"
                      size="icon"
                      disabled={isCodeEmpty || isRunning}
                      className="h-7 w-4 px-0 rounded-l-none border-l border-border/40"
                    >
                      <ChevronDown className="h-3 w-3" />
                    </Button>
                  </DropdownMenuTrigger>
                </TooltipTrigger>
                <TooltipContent>Run options</TooltipContent>
              </Tooltip>
              <DropdownMenuContent align="start" className="w-56">
                <DropdownMenuItem
                  onClick={() => {
                    setForceRerun(false);
                    onRunCell(cellId, false);
                  }}
                >
                  <Play className="h-3.5 w-3.5 mr-2" />
                  <div className="flex flex-col">
                    <span className="flex items-center gap-2">
                      Run cell
                      {!forceRerun && <Check className="h-3 w-3 text-muted-foreground" />}
                    </span>
                    <span className="text-xs text-muted-foreground">Run current cell</span>
                  </div>
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  onClick={() => {
                    setForceRerun(true);
                    onRunCell(cellId, true);
                  }}
                >
                  <FastForward className="h-3.5 w-3.5 mr-2" />
                  <div className="flex flex-col">
                    <span className="flex items-center gap-2">
                      Run workflow
                      {forceRerun && <Check className="h-3 w-3 text-muted-foreground" />}
                    </span>
                    <span className="text-xs text-muted-foreground">Run workflow from input</span>
                  </div>
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        )}
        {/* Clear Results Button */}
        {hasResult && (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button variant="ghost" size="icon" onClick={handleClearResults} className="h-6 w-6">
                <X className="h-3.5 w-3.5" />
              </Button>
            </TooltipTrigger>
            <TooltipContent>Clear results</TooltipContent>
          </Tooltip>
        )}
        {/* Restore Results Button */}
        {!hasResult && hasPersistedResults && onRestoreResults && (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                onClick={handleRestoreResults}
                className="h-6 w-6"
              >
                <RotateCcw className="h-3.5 w-3.5" />
              </Button>
            </TooltipTrigger>
            <TooltipContent>Restore results</TooltipContent>
          </Tooltip>
        )}
        {/* Save Button */}
        {canEditOntologies && (
          <ReadOnlyGate readOnly={readOnly} tooltip={readOnlyHint}>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant={isModified ? "default" : "ghost"}
                  size="icon"
                  onClick={handleSaveCell}
                  disabled={isCodeEmpty || isSaving || isCellSaving || readOnly}
                  className="h-6 w-6"
                >
                  <Save className={`h-3.5 w-3.5 ${isModified ? "text-white" : ""}`} />
                  {isSaving && <span className="sr-only">Saving...</span>}
                </Button>
              </TooltipTrigger>
              <TooltipContent>
                Save cell <span className="ml-2 text-xs text-muted-foreground">⌘S / Ctrl+S</span>
              </TooltipContent>
            </Tooltip>
          </ReadOnlyGate>
        )}
        {/* Delete Button */}
        {canEditOntologies && (
          <ReadOnlyGate readOnly={readOnly} tooltip={readOnlyHint}>
            <AlertDialog open={dialogOpen} onOpenChange={setDialogOpen}>
              <Tooltip>
                <TooltipTrigger asChild>
                  <AlertDialogTrigger asChild>
                    <Button
                      variant="ghost"
                      size="icon"
                      disabled={readOnly}
                      className="h-6 w-6 text-destructive hover:text-destructive"
                    >
                      <Trash className="h-3.5 w-3.5" />
                    </Button>
                  </AlertDialogTrigger>
                </TooltipTrigger>
                <TooltipContent>Delete cell</TooltipContent>
              </Tooltip>
              <AlertDialogContent>
                <AlertDialogHeader>
                  <AlertDialogTitle>Delete Cell</AlertDialogTitle>
                  <AlertDialogDescription>
                    Are you sure you want to delete this cell? It cannot be undone.
                  </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                  <AlertDialogCancel>Cancel</AlertDialogCancel>
                  <AlertDialogAction
                    onClick={handleDeleteCell}
                    disabled={isDeleting}
                    className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                  >
                    {isDeleting ? "Deleting..." : "Delete"}
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          </ReadOnlyGate>
        )}
      </div>
      <div className="flex items-center space-x-1">
        {/* Cell management operations moved to CellSettings */}
      </div>

      {/* Beautiful Databricks Validation Modal */}
      <Dialog
        open={validationModal.isOpen}
        onOpenChange={(open) => setValidationModal((prev) => ({ ...prev, isOpen: open }))}
      >
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              {validationModal.type === "success" ? (
                <CheckCircle className="h-5 w-5 text-green-600" />
              ) : (
                <XCircle className="h-5 w-5 text-red-600" />
              )}
              {validationModal.title}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4">
            <div
              className={`p-4 rounded-lg ${
                validationModal.type === "success"
                  ? "bg-green-50 border border-green-200 dark:bg-green-900/20 dark:border-green-800"
                  : "bg-red-50 border border-red-200 dark:bg-red-900/20 dark:border-red-800"
              }`}
            >
              <div
                className={`flex items-start gap-3 ${
                  validationModal.type === "success"
                    ? "text-green-800 dark:text-green-200"
                    : "text-red-800 dark:text-red-200"
                }`}
              >
                {validationModal.type === "success" ? (
                  <CheckCircle className="h-5 w-5 mt-0.5 flex-shrink-0" />
                ) : (
                  <AlertCircle className="h-5 w-5 mt-0.5 flex-shrink-0" />
                )}
                <div className="space-y-2">
                  <p className="font-medium">{validationModal.message}</p>
                  {validationModal.actionRequired && (
                    <div className="text-sm opacity-90">
                      <p className="font-medium mb-1">Action Required:</p>
                      <p>{validationModal.actionRequired}</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button
              onClick={() => setValidationModal((prev) => ({ ...prev, isOpen: false }))}
              className={
                validationModal.type === "success" ? "bg-green-600 hover:bg-green-700" : ""
              }
            >
              {validationModal.type === "success" ? "Close" : "Got it"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};
export default React.memo(CellToolbar);
