import type { LucideIcon } from "lucide-react";
import SettingsNavCard from "./SettingsNavCard";

export interface SettingsNavItem {
  key: string;
  icon: LucideIcon;
  title: string;
  description: string;
  onClick: () => void;
}

interface SettingsNavListProps {
  items: SettingsNavItem[];
}

// Groups the settings entries into a single hairline-bordered container with row
// dividers. The grouped-list pattern reads as more considered than a stack of
// separate floating cards, and matches the density of a polished settings page.
export function SettingsNavList({ items }: SettingsNavListProps) {
  return (
    <div className="overflow-hidden rounded-xl border bg-card shadow-card">
      <div className="divide-y">
        {items.map((item) => (
          <SettingsNavCard
            key={item.key}
            icon={item.icon}
            title={item.title}
            description={item.description}
            onClick={item.onClick}
          />
        ))}
      </div>
    </div>
  );
}
