import { useOntologyConcepts } from "../../../hooks/useOntologyConcepts";
import type { RunGroupDef, RunTrigger } from "../../../schema/appDefinition.types";
import { patchRunGroup } from "../../../store/appEditorMutations";
import { useAppEditorStore } from "../../../store/appEditorStore";
import { EXECUTE_HELP, FACTS_HELP, PARAMS_HELP, TRIGGER_HELP } from "../editorHelp";
import { SelectField, TextField } from "./fields";
import { KeyValueEditor } from "./KeyValueEditor";
import { StaleSelection } from "./PageInspector";
import { TapListEditor } from "./TapListEditor";
import { TokenMultiSelectField } from "./TokenSelect";

interface RunGroupInspectorProps {
  pageId: string;
  groupId: string;
}

const TRIGGER_OPTIONS: Array<{ value: RunTrigger; label: string }> = [
  { value: "button", label: "Button (run_button widget)" },
  { value: "form", label: "Form submission" },
  { value: "auto", label: "Auto (when variables change)" },
  { value: "load", label: "Load (page open)" },
];

export function RunGroupInspector({ pageId, groupId }: RunGroupInspectorProps) {
  const draft = useAppEditorStore((state) => state.draft);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  const page = draft?.pages.find((candidate) => candidate.id === pageId);
  const { conceptNames, isLoading: conceptsLoading } = useOntologyConcepts(page?.project.id);

  const group = page?.runGroups.find((candidate) => candidate.id === groupId);
  if (!page || !group) return <StaleSelection />;

  const patch = (partial: Partial<RunGroupDef>) => {
    updateDraft((current) => patchRunGroup(current, pageId, groupId, partial));
  };

  const formOptions = page.inputs
    .filter((input) => input.type === "form")
    .map((input) => ({ value: input.id, label: input.label || input.id }));

  return (
    <div className="flex flex-col gap-2.5">
      <TextField label="Label" value={group.label} onChange={(value) => patch({ label: value })} />
      <SelectField
        label="Trigger"
        hint={TRIGGER_HELP}
        value={group.trigger}
        options={TRIGGER_OPTIONS}
        onChange={(value) => patch({ trigger: (value ?? "button") as RunTrigger })}
      />
      {group.trigger === "form" && (
        <SelectField
          label="Form"
          value={group.formId}
          options={formOptions}
          onChange={(value) => patch({ formId: value })}
        />
      )}
      <KeyValueEditor
        label="Params (@param → {{variable}} or literal)"
        hint={PARAMS_HELP}
        keyPlaceholder="input_entity"
        valuePlaceholder="{{entity}}"
        entries={group.params ?? {}}
        onChange={(entries) => patch({ params: entries })}
      />
      <KeyValueEditor
        label="Facts (input predicate → {{form.recordGroup}})"
        hint={FACTS_HELP}
        keyPlaceholder="scenario_assumption"
        valuePlaceholder="{{form.assumptions}}"
        entries={group.facts ?? {}}
        onChange={(entries) => patch({ facts: entries })}
      />
      <TokenMultiSelectField
        label="Execute (deepest concepts to run)"
        hint={EXECUTE_HELP}
        value={group.execute}
        onChange={(value) => patch({ execute: value })}
        options={conceptNames}
        loading={conceptsLoading}
        noun="concepts"
      />
      <TapListEditor
        taps={group.outputs ?? []}
        onChange={(outputs) => patch({ outputs })}
        conceptNames={conceptNames}
        conceptsLoading={conceptsLoading}
      />
    </div>
  );
}
