import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

export interface SuggestedConcept {
  predicate_name: string;
  signature: string;
  fields: Record<string, string>; // field_name -> field_type mapping
  type: "node" | "edge";
  source_node: string;
  target_node?: string; // only for edges
  edge_name?: string; // only for edges
  is_suggested: boolean;
}

export interface GraphData {
  nodes: Array<{
    id: string;
    label: string;
    description: string;
    color: string;
    x?: number;
    y?: number;
  }>;
  edges: Array<{
    id: string;
    from: string;
    to: string;
    label: string;
    description: string;
  }>;
}

export interface OntologySchemaData {
  ontology_schema_data: GraphData | null;
  suggested_concepts: SuggestedConcept[];
}

export interface SaveGraphRequest {
  project: {
    scope: string;
  };
  ontology_schema_data: GraphData;
}

export interface LoadGraphRequest {
  project: {
    scope: string;
  };
}

export interface GraphResponse {
  status: string;
  message?: string;
  data?: GraphData;
}

export class OntologySchemaService {
  /**
   * Regenerate the ontology schema graph from the project's concept lineage,
   * overwriting any existing graph (backs the Document view's refresh action).
   */
  static async generateFromLineage(
    ontologyId: string,
    ontologyScope: string = "user",
  ): Promise<GraphData | null> {
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/generate-ontology-schema-from-lineage?scope=${ontologyScope}`;

    const response = await HttpService.post(url, {});

    if (response.status === "success") {
      return response.data ?? null;
    }
    throw new Error(response.message || "Failed to regenerate ontology schema from lineage");
  }

  /**
   * Save graph data for a project
   */
  static async saveGraph(
    ontologyId: string,
    graphData: GraphData,
    ontologyScope: string = "user",
  ): Promise<GraphResponse> {
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/save-ontology-schema`;
    const payload: SaveGraphRequest = {
      project: {
        scope: ontologyScope,
      },
      ontology_schema_data: graphData,
    };

    const response = await HttpService.post(url, payload);

    if (response.status === "success") {
      return response;
    } else {
      throw new Error(response.message || "Failed to save graph");
    }
  }

  /**
   * Load graph data for a project
   */
  static async loadGraph(
    ontologyId: string,
    ontologyScope: string = "user",
  ): Promise<GraphData | null> {
    // Create query parameters for project scope
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/load-ontology-schema?scope=${ontologyScope}`;

    const response = await HttpService.get(url);

    if (response.status === "success" && response.data) {
      return response.data.ontology_schema_data;
    } else if (response.status === "success" && !response.data) {
      // No graph data found - this is normal for new projects
      return null;
    } else {
      throw new Error(response.message || "Failed to load ontology schema");
    }
  }

  /**
   * Load complete ontology schema data including suggested concepts for a project
   */
  static async loadOntologySchemaData(
    ontologyId: string,
    ontologyScope: string = "user",
  ): Promise<OntologySchemaData> {
    try {
      // Create query parameters for project scope
      const url = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/load-ontology-schema?scope=${ontologyScope}`;

      const response = await HttpService.get(url);

      if (response.status === "success" && response.data) {
        return {
          ontology_schema_data: response.data.ontology_schema_data || null,
          suggested_concepts: response.data.suggested_concepts || [],
        };
      } else {
        // No data found - return empty structure
        return {
          ontology_schema_data: null,
          suggested_concepts: [],
        };
      }
    } catch (_error) {
      // Return empty structure on error
      return {
        ontology_schema_data: null,
        suggested_concepts: [],
      };
    }
  }
}
