import { NotebookText } from "lucide-react";
import { useState } from "react";

import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/shared/components/ui/resizable";

import { useContextNotes } from "../hooks/useContextNotes";
import type { ContextNote } from "../types";
import { conceptNodeId } from "../types";
import { CollectionView } from "./components/CollectionView";
import { FormerlyPinnedNotice } from "./components/FormerlyPinnedNotice";
import { NewNotePane } from "./components/NewNotePane";
import { NoteEditorPane } from "./components/NoteEditorPane";
import { NoteInfoPanel } from "./components/NoteInfoPanel";
import { NotesSidebar } from "./components/NotesSidebar";
import { QuickSwitcher } from "./components/QuickSwitcher";
import { useNoteActions } from "./hooks/useNoteActions";
import { GLOBAL_VAULT, useNotesPageState } from "./hooks/useNotesPageState";
import { useNoteUrlSync } from "./hooks/useNoteUrlSync";
import { useOpenGraphNode } from "./hooks/useOpenGraphNode";
import {
  filterByShelf,
  groupDocumentChunks,
  linkDisplayTitle,
  normalizeFolderPath,
  notesUnderFolder,
  orderedChunksOf,
  representativeChunkOf,
  type VaultRef,
} from "./notesModel";
import { CONCEPT_WIKILINK_PREFIX } from "./wikilinks";

function NotesEmptyState() {
  return (
    <div className="flex h-full flex-col items-center justify-center gap-2 text-center">
      <NotebookText className="h-8 w-8 text-muted-foreground/50" />
      <p className="text-sm text-muted-foreground">Select a note, or create one.</p>
      <p className="text-xs text-muted-foreground">
        Press <kbd className="rounded border border-border bg-muted px-1">⌘K</kbd> to jump to any
        note · type <code className="rounded bg-muted px-1">[[</code> in the editor to link notes.
      </p>
    </div>
  );
}

interface ContextWorkspaceProps {
  /** Project vaults shown in the sidebar (in addition to the hardcoded Global vault). */
  projectVaults: VaultRef[];
  /** Vault the workspace opens on. Defaults to the Global vault. */
  initialVault?: VaultRef;
  /** Bind the selection to the /context/:noteId URL. Only the global Context
   *  page does this; the in-project tab (under /editor/:id) must not. */
  syncUrl?: boolean;
}

/**
 * The vault-parameterized notes workspace (sidebar + note/document editor +
 * collection grid + info panel + quick switcher). Rendered by the global
 * ContextPage (all vaults, Global default) and by the in-project Context tab
 * (single project vault, project default).
 */
export function ContextWorkspace({
  projectVaults,
  initialVault,
  syncUrl = false,
}: ContextWorkspaceProps) {
  const [switcherOpen, setSwitcherOpen] = useState(false);

  const pageState = useNotesPageState(initialVault);
  const { vault, vaultFilter, selection, selectNote, selectDocument, clearSelection } = pageState;
  const { openConcept } = useOpenGraphNode();

  const { data: globalNotes = [] } = useContextNotes({ scope: "global", scopeId: null });
  const { data: vaultNotes = [] } = useContextNotes(vaultFilter);
  const actions = useNoteActions(vaultFilter);

  // Wikilink targets resolve across the scope chain: global + active vault.
  const linkCandidates = vault.scope === "global" ? globalNotes : [...vaultNotes, ...globalNotes];

  const selectedNote =
    selection.type === "note"
      ? (vaultNotes.find((note) => note.id === selection.noteId) ?? null)
      : null;
  const selectedDocument =
    selection.type === "document"
      ? (groupDocumentChunks(vaultNotes).documents.find(
          (document) => document.documentId === selection.documentId,
        ) ?? null)
      : null;
  // Documents open in the SAME editor as notes: one merged text, edited as
  // a whole. Saving writes it back via saveDocumentText.
  const documentNote = selectedDocument
    ? {
        ...representativeChunkOf(selectedDocument),
        text: orderedChunksOf(selectedDocument)
          .map((chunk) => chunk.text)
          .join("\n\n"),
      }
    : null;
  const selectedCollection = selection.type === "collection" ? selection : null;
  const isDraftingNew = selection.type === "new";
  // What the right info panel describes: the note, or the document (as its
  // merged representative note).
  const infoNote = selectedNote ?? documentNote;

  // Card view respects the active shelf filter, mirroring the tree.
  const collectionGroups = selectedCollection
    ? groupDocumentChunks(filterByShelf(vaultNotes, pageState.shelf))
    : null;
  const collectionNotes = collectionGroups
    ? notesUnderFolder(collectionGroups.standalone, selectedCollection?.folderPath ?? "")
    : [];
  const collectionDocuments =
    collectionGroups && !selectedCollection?.folderPath ? collectionGroups.documents : [];

  const vaultOfNote = (note: ContextNote): VaultRef => {
    if (note.scope === "global") return GLOBAL_VAULT;
    const known = projectVaults.find((candidate) => candidate.scopeId === note.scope_id);
    return known ?? { scope: "ontology", scopeId: note.scope_id, name: "Ontology" };
  };

  const openNote = (note: ContextNote) => {
    if (note.kind === "document_chunk") {
      selectDocument(note.source_meta?.document_id ?? note.id, vaultOfNote(note));
      return;
    }
    selectNote(note.id, vaultOfNote(note), normalizeFolderPath(note.folder_path));
  };

  // /context/:noteId ←→ selection. Documents are addressed by their
  // representative chunk id (openNote routes it back to the document).
  const urlNoteId =
    selection.type === "note"
      ? selection.noteId
      : selectedDocument
        ? representativeChunkOf(selectedDocument).id
        : null;
  useNoteUrlSync({ urlNoteId, openNote, enabled: syncUrl });

  const handleOpenNoteByTitle = (title: string) => {
    const wanted = title.trim().toLowerCase();
    // [[concept:name]] resolves within the open vault's project and opens
    // the concept in the Explorer (decision 7).
    if (wanted.startsWith(CONCEPT_WIKILINK_PREFIX)) {
      const conceptName = title.trim().slice(CONCEPT_WIKILINK_PREFIX.length).trim();
      if (vault.scope === "ontology" && vault.scopeId && conceptName) {
        openConcept(conceptNodeId(vault.scopeId, conceptName));
      }
      return;
    }
    // linkDisplayTitle matches documents by filename, notes by title.
    const target = linkCandidates.find(
      (candidate) => linkDisplayTitle(candidate).toLowerCase() === wanted,
    );
    if (target) openNote(target);
  };

  const handleOpenNoteById = (noteId: string) => {
    const target = linkCandidates.find((candidate) => candidate.id === noteId);
    if (target) openNote(target);
  };

  const handleNoteCreated = (created: ContextNote) =>
    selectNote(created.id, vault, pageState.folderPath);

  return (
    <div className="flex h-full min-h-0 flex-1 flex-col">
      <FormerlyPinnedNotice notes={[...globalNotes, ...vaultNotes]} />
      <div className="min-h-0 flex-1">
        <ResizablePanelGroup direction="horizontal">
          <ResizablePanel defaultSize={22} minSize={15} maxSize={35}>
            <NotesSidebar
              pageState={pageState}
              ontologyVaults={projectVaults}
              onCreateNote={pageState.startNewNote}
              onSelectSearchResult={openNote}
            />
          </ResizablePanel>
          <ResizableHandle />
          <ResizablePanel defaultSize={infoNote ? 56 : 78} minSize={30}>
            {selectedNote && (
              <NoteEditorPane
                key={selectedNote.id}
                note={selectedNote}
                linkCandidates={linkCandidates}
                actions={actions}
                onOpenNoteByTitle={handleOpenNoteByTitle}
              />
            )}
            {selectedDocument && documentNote && (
              <NoteEditorPane
                key={selectedDocument.documentId}
                note={documentNote}
                linkCandidates={linkCandidates}
                actions={actions}
                onOpenNoteByTitle={handleOpenNoteByTitle}
                titleOverride={selectedDocument.filename}
                saveDraft={async (draft, edges) => {
                  await actions.saveDocumentText(selectedDocument, draft, linkCandidates, edges);
                }}
              />
            )}
            {selectedCollection && (
              <CollectionView
                vault={vault}
                folderPath={selectedCollection.folderPath}
                notes={collectionNotes}
                documents={collectionDocuments}
                lookupNotes={linkCandidates}
                onOpenNote={openNote}
                onOpenNoteId={handleOpenNoteById}
                onOpenDocument={(document) => selectDocument(document.documentId, vault)}
              />
            )}
            {isDraftingNew && (
              <NewNotePane
                vault={vault}
                folderPath={pageState.folderPath}
                linkCandidates={linkCandidates}
                actions={actions}
                onCreated={handleNoteCreated}
                onCancel={clearSelection}
              />
            )}
            {!selectedNote && !selectedDocument && !selectedCollection && !isDraftingNew && (
              <NotesEmptyState />
            )}
          </ResizablePanel>
          {infoNote && (
            <>
              <ResizableHandle />
              <ResizablePanel defaultSize={22} minSize={15} maxSize={35}>
                <NoteInfoPanel
                  key={selectedNote?.id ?? selectedDocument?.documentId}
                  note={infoNote}
                  linkCandidates={linkCandidates}
                  actions={actions}
                  onOpenNote={handleOpenNoteById}
                  onDeleted={clearSelection}
                  deleteOverride={
                    selectedDocument ? () => actions.deleteDocument(selectedDocument) : undefined
                  }
                  deleteLabel={selectedDocument ? "Delete document" : "Delete note"}
                />
              </ResizablePanel>
            </>
          )}
        </ResizablePanelGroup>
      </div>

      <QuickSwitcher
        open={switcherOpen}
        onOpenChange={setSwitcherOpen}
        activeVault={vault}
        onSelect={(note) => openNote(note)}
      />
    </div>
  );
}
