import { Save, X } from "lucide-react";
import { useState } from "react";

import { Button } from "@/shared/components/ui/button";

import { useOntologyConcepts } from "../../hooks/useOntologyConcepts";
import type { ContextNote } from "../../types";
import type { UseNoteActionsReturn } from "../hooks/useNoteActions";
import {
  buildConceptLinkTargets,
  buildLinkTargets,
  deriveTitleFromText,
  type VaultRef,
} from "../notesModel";
import { NoteMarkdownEditor } from "./NoteMarkdownEditor";
import { ShelfBadge } from "./ShelfBadge";

interface NewNotePaneProps {
  vault: VaultRef;
  /** "" = vault root. */
  folderPath: string;
  linkCandidates: ContextNote[];
  actions: UseNoteActionsReturn;
  onCreated: (note: ContextNote) => void;
  onCancel: () => void;
}

/** Draft editor for a not-yet-persisted note: empty, focused, and only
 *  saved when the user says so. Cancel discards it entirely. */
export function NewNotePane({
  vault,
  folderPath,
  linkCandidates,
  actions,
  onCreated,
  onCancel,
}: NewNotePaneProps) {
  const [draft, setDraft] = useState("");
  // [[concept:name]] autocomplete over the vault's own project.
  const { data: conceptNames } = useOntologyConcepts(
    vault.scope === "ontology" ? vault.scopeId : null,
  );

  const title = deriveTitleFromText(draft) || "New note";
  const canSave = draft.trim().length > 0 && !actions.isMutating;
  const destination = folderPath ? `${vault.name} / ${folderPath}` : vault.name;

  const handleSave = async () => {
    if (!canSave) return;
    const created = await actions.createNote({ text: draft, folderPath, linkCandidates });
    if (created) onCreated(created);
  };

  return (
    <div className="flex h-full flex-col">
      <header className="flex shrink-0 items-center justify-between gap-3 border-b border-border px-4 py-2.5">
        <div className="flex min-w-0 items-center gap-2">
          <h2 className="truncate text-base font-semibold text-foreground">{title}</h2>
          <ShelfBadge shelf="knowledge" />
        </div>
        <div className="flex shrink-0 items-center gap-1.5">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={onCancel}
            disabled={actions.isMutating}
            className="h-8"
          >
            <X className="mr-1.5 h-4 w-4" />
            Cancel
          </Button>
          <Button type="button" size="sm" onClick={handleSave} disabled={!canSave} className="h-8">
            <Save className="mr-1.5 h-4 w-4" />
            {actions.isMutating ? "Saving…" : "Save"}
          </Button>
        </div>
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto">
        <NoteMarkdownEditor
          value={draft}
          onChange={setDraft}
          getLinkCandidates={() => [
            ...buildLinkTargets(linkCandidates),
            ...buildConceptLinkTargets(conceptNames ?? []),
          ]}
          onSave={handleSave}
          autoFocus
        />
      </div>

      <footer className="shrink-0 border-t border-border px-4 py-2 text-xs text-muted-foreground">
        Saving to {destination} · nothing is stored until you save · type{" "}
        <code className="rounded bg-muted px-1">[[</code> to link another note
      </footer>
    </div>
  );
}
