import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { supabase } from "@/shared/integrations/supabase/client";

// Permissive: Stripe occasionally adds new states. We branch on the ones we
// care about and leave the rest as "no special UI".
export type SubscriberStatus =
  | "trialing"
  | "active"
  | "canceled"
  | "incomplete"
  | "incomplete_expired"
  | "past_due"
  | "paused"
  | "unpaid"
  | string;

export interface SubscriberRow {
  user_id: string;
  status: SubscriberStatus;
  current_period_end: string | null;
  stripe_subscription_id: string | null;
  stripe_customer_id: string | null;
}

const SUBSCRIBER_ROW_KEY = "billing-subscriber-row";

const isSubscriberRow = (value: unknown): value is SubscriberRow => {
  if (typeof value !== "object" || value === null) return false;
  if (!("user_id" in value) || typeof value.user_id !== "string") return false;
  if (!("status" in value) || typeof value.status !== "string") return false;
  return true;
};

const fetchSubscriberRow = async (userId: string): Promise<SubscriberRow | null> => {
  const { data, error } = await supabase
    .from("subscribers")
    .select("user_id, status, current_period_end, stripe_subscription_id, stripe_customer_id")
    .eq("user_id", userId)
    .maybeSingle();

  if (error) throw error;
  if (data === null) return null;
  if (!isSubscriberRow(data)) {
    throw new Error("subscribers row had unexpected shape");
  }
  return data;
};

export interface UseSubscriberRowResult {
  subscriber: SubscriberRow | null | undefined;
  isLoading: boolean;
  error: Error | null;
  refetch: () => void;
}

export const useSubscriberRow = (): UseSubscriberRowResult => {
  const { user } = useAuth();
  const userId = user?.id;

  const query = useQuery({
    queryKey: [SUBSCRIBER_ROW_KEY, userId],
    queryFn: () => {
      if (!userId) throw new Error("useSubscriberRow called without a userId");
      return fetchSubscriberRow(userId);
    },
    enabled: Boolean(userId),
  });

  return {
    subscriber: query.data,
    isLoading: query.isLoading,
    error: query.error,
    refetch: () => {
      query.refetch();
    },
  };
};

export const SUBSCRIBER_ROW_QUERY_KEY = SUBSCRIBER_ROW_KEY;
