import { ArrowLeft, ChevronLeft, ChevronRight, Share2, Table2 } from "lucide-react";
import { useMemo, useState } from "react";
import QueryResultTable, {
  type ColumnFilterValue,
  type OrderByItem,
  type PaginationInfo,
} from "@/features/concept-editor/components/query/components/QueryResultTable";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { cn } from "@/shared/lib/utils";
import type { ConceptGraphData } from "../../conceptGraph.utils";
import { type GraphAnalyticsKey, getGraphAnalytics } from "../../graphAnalytics";
import {
  DEFAULT_MAX_DEPTH,
  type GraphFunctionDef,
  type GraphFunctionKey,
  getGraphFunction,
} from "../../graphFunctions";
import type {
  ConceptGraphMode,
  ConceptGraphStatus,
  GraphFunctionOptions,
  TableQueryState,
} from "../../hooks/useConceptGraph";
import { ExplorerCanvas } from "../ExplorerCanvas";
import { ConceptGraphAnalyticsToolbar } from "./ConceptGraphAnalyticsToolbar";
import { ConceptGraphModeBar } from "./ConceptGraphModeBar";
import { ConceptGraphNodePanel } from "./ConceptGraphNodePanel";
import { ConceptGraphTraversalToolbar } from "./ConceptGraphTraversalToolbar";

type GraphViewKind = "graph" | "table";

interface ConceptGraphViewProps {
  predicate: string;
  status: ConceptGraphStatus;
  error: string | null;
  data: ConceptGraphData | null;
  mode: ConceptGraphMode;
  onModeChange: (mode: ConceptGraphMode) => void;
  onLoadFunction: (key: GraphFunctionKey, options: GraphFunctionOptions) => void;
  onRunAnalytics: (key: GraphAnalyticsKey, params: Record<string, unknown>) => void;
  onClearAnalytics: () => void;
  onPageChange: (page: number) => void;
  tableQuery: TableQueryState;
  onSort: (orderBy: OrderByItem[]) => void;
  onSearch: (searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) => void;
  onClearSearch: () => void;
  onClearColumnFilter: (columnIndex: number) => void;
  onPageSizeChange: (pageSize: number) => void;
  expandedNodeIds: Set<string>;
  expandingNodeIds: Set<string>;
  cappedNodeIds: Set<string>;
  onExpandNode: (nodeId: string) => void;
  onLoadMoreNeighbors: (nodeId: string) => void;
  onCollapseNode: (nodeId: string) => void;
  onClose: () => void;
}

/** Sample-size options for the records-mode seed graph. */
const SAMPLE_SIZES = [100, 250, 500, 1000] as const;

function statusMessage(status: ConceptGraphStatus, predicate: string): string {
  if (status === "running") return `Running ${predicate}…`;
  return "Building graph…";
}

function emptyStateMessage(activeFn: GraphFunctionDef | null, visited: boolean): string {
  if (!activeFn) return "This concept returned no graph records.";
  if (!visited) return `No ${activeFn.label} reachability edges found on this page.`;
  return `No ${activeFn.label} results found between those nodes on this page.`;
}

export function ConceptGraphView({
  predicate,
  status,
  error,
  data,
  mode,
  onModeChange,
  onLoadFunction,
  onRunAnalytics,
  onClearAnalytics,
  onPageChange,
  tableQuery,
  onSort,
  onSearch,
  onClearSearch,
  onClearColumnFilter,
  onPageSizeChange,
  expandedNodeIds,
  expandingNodeIds,
  cappedNodeIds,
  onExpandNode,
  onLoadMoreNeighbors,
  onCollapseNode,
  onClose,
}: ConceptGraphViewProps) {
  const [pathEndpoints, setPathEndpoints] = useState({ source: "", target: "" });
  const [options, setOptions] = useState<{
    allPaths: boolean;
    visited: boolean;
    maxDepth: number;
  }>({
    allPaths: true,
    visited: true,
    maxDepth: DEFAULT_MAX_DEPTH,
  });
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  // Bumped when a node is picked from the panel (a connection row) so the
  // canvas recenters on it; plain canvas clicks use setSelectedNodeId directly
  // and leave the camera put.
  const [focusToken, setFocusToken] = useState(0);
  const [analyticsKey, setAnalyticsKey] = useState<GraphAnalyticsKey | null>(null);
  const [view, setView] = useState<GraphViewKind>("graph");
  const pagination = data?.pagination ?? null;
  // The table view owns its own pagination (QueryResultTable). The header pager
  // is only for the traversal graph view (a result set); records mode is a
  // persistent explore canvas with no pager, and analytics overlays are stable.
  const isAnalyticsOverlay = Boolean(data?.analyticsType);
  const showPager =
    !!pagination &&
    pagination.total_pages > 1 &&
    view === "graph" &&
    mode !== "records" &&
    !isAnalyticsOverlay;
  // Node expansion is a records-mode affordance (raw adjacency), not available
  // for traversal path/pair results.
  const canExpand = mode === "records";
  const showSampleSize = canExpand && view === "graph";
  const isBusy = status === "running" || status === "loading";
  const selectedNode = selectedNodeId && data ? data.nodes[selectedNodeId] : undefined;
  const activeFn = mode === "records" ? null : getGraphFunction(mode);
  const activeAnalyticsFn = analyticsKey ? getGraphAnalytics(analyticsKey) : null;
  // Stable reference so typing in a toolbar field (or switching function/analytics)
  // doesn't change the ExplorerCanvas `analytics` prop and force a full G6 rebuild.
  const analyticsType = data?.analyticsType ?? null;
  const analyticsRange = data?.analyticsRange ?? null;
  const analyticsContext = useMemo(
    () => (data ? { type: analyticsType, range: analyticsRange } : undefined),
    // `data` presence toggles between an object and undefined; the overlay
    // content only depends on the type/range values.
    [data, analyticsType, analyticsRange],
  );

  const tableData = useMemo(
    () => (data ? { predicateName: predicate, columns: data.columns, rows: data.rows } : null),
    [data, predicate],
  );
  const paginationInfo = useMemo<PaginationInfo | undefined>(
    () =>
      pagination
        ? {
            page: pagination.page,
            totalPages: pagination.total_pages,
            hasNext: pagination.has_next,
            hasPrev: pagination.has_prev,
            totalCount: pagination.total_count,
            pageSize: pagination.page_size || tableQuery.pageSize,
            orderBy: tableQuery.orderBy,
          }
        : undefined,
    [pagination, tableQuery.pageSize, tableQuery.orderBy],
  );
  const searchState = useMemo(
    () => ({ searchTerm: tableQuery.searchTerm, columnFilters: tableQuery.columnFilters }),
    [tableQuery.searchTerm, tableQuery.columnFilters],
  );

  const handleLoad = () => {
    if (!activeFn) return;
    onLoadFunction(activeFn.key, {
      source: pathEndpoints.source,
      target: pathEndpoints.target,
      allPaths: options.allPaths,
      visited: options.visited,
      maxDepth: options.maxDepth,
    });
  };

  const setSource = (source: string) => setPathEndpoints((prev) => ({ ...prev, source }));
  const setTarget = (target: string) => setPathEndpoints((prev) => ({ ...prev, target }));

  const selectRecords = () => {
    setAnalyticsKey(null);
    if (mode !== "records") {
      onModeChange("records");
      return;
    }
    if (data?.analyticsType) onClearAnalytics();
  };

  const selectFunction = (key: GraphFunctionKey) => {
    setAnalyticsKey(null);
    onModeChange(key);
  };

  const selectAnalytics = (key: GraphAnalyticsKey) => {
    // Analytics overlays the Records graph — switch back to it if needed.
    if (mode !== "records") onModeChange("records");
    setAnalyticsKey(key);
  };

  const showGraph = () => setView("graph");
  const showTable = () => setView("table");

  // Panel-driven selection (header close or a connection row). Selecting a node
  // this way recenters the canvas on it; deselecting (null) doesn't.
  const handlePanelSelect = (id: string | null) => {
    setSelectedNodeId(id);
    if (id) setFocusToken((token) => token + 1);
  };

  const renderBody = () => {
    if (isBusy) {
      return (
        <div className="flex-1 flex flex-col items-center justify-center gap-3">
          <PrometheuxSpinner />
          <p className="text-xs text-muted-foreground">{statusMessage(status, predicate)}</p>
        </div>
      );
    }
    if (status === "error") {
      return (
        <div className="flex-1 flex items-center justify-center px-6">
          <p className="text-xs text-destructive text-center">{error}</p>
        </div>
      );
    }
    if (!data) return null;
    if (view === "table") {
      if (!tableData) return null;
      return (
        <div className="flex-1 min-h-0 overflow-auto p-3">
          <QueryResultTable
            data={tableData}
            pagination={paginationInfo}
            onPageChange={onPageChange}
            onPageSizeChange={onPageSizeChange}
            onSearch={onSearch}
            onClearSearch={onClearSearch}
            onClearColumnFilter={onClearColumnFilter}
            searchState={searchState}
            onSort={onSort}
          />
        </div>
      );
    }
    if (Object.keys(data.nodes).length === 0) {
      const message = emptyStateMessage(activeFn, options.visited);
      return (
        <div className="flex-1 flex items-center justify-center">
          <p className="text-xs text-muted-foreground">{message}</p>
        </div>
      );
    }
    return (
      <div className="flex-1 flex min-h-0">
        <ExplorerCanvas
          nodes={data.nodes}
          edges={data.edges}
          selectedNodeId={selectedNodeId}
          onSelectNode={setSelectedNodeId}
          onExpandNode={onExpandNode}
          canExpand={canExpand}
          expandedNodeIds={expandedNodeIds}
          expandingNodeIds={expandingNodeIds}
          focusToken={focusToken}
          analytics={analyticsContext}
        />
        {selectedNode && (
          <ConceptGraphNodePanel
            nodeId={selectedNode.id}
            data={data}
            onSelectNode={handlePanelSelect}
            canExpand={canExpand}
            isExpanded={expandedNodeIds.has(selectedNode.id)}
            isExpanding={expandingNodeIds.has(selectedNode.id)}
            isCapped={cappedNodeIds.has(selectedNode.id)}
            onExpand={onExpandNode}
            onLoadMore={onLoadMoreNeighbors}
            onCollapse={onCollapseNode}
          />
        )}
      </div>
    );
  };

  return (
    <div className="flex-1 flex flex-col min-h-0 min-w-0">
      <div className="h-10 flex items-center gap-2 px-3 border-b border-border flex-shrink-0">
        <Button variant="ghost" size="sm" className="h-6 gap-1 text-xs px-2" onClick={onClose}>
          <ArrowLeft className="h-3.5 w-3.5" />
          Model
        </Button>
        <Badge variant="secondary" className="text-[10px]">
          Concept graph
        </Badge>
        <span className="text-xs font-medium text-foreground truncate">{predicate}</span>

        <ConceptGraphModeBar
          mode={mode}
          analyticsKey={analyticsKey}
          isBusy={isBusy}
          onSelectRecords={selectRecords}
          onSelectFunction={selectFunction}
          onSelectAnalytics={selectAnalytics}
        />

        <div className="flex items-center bg-muted/50 rounded-md p-0.5 flex-shrink-0">
          <button
            type="button"
            onClick={showGraph}
            title="Graph view"
            className={cn(
              "flex items-center gap-1 rounded px-2 py-1 text-xs font-medium transition-colors",
              view === "graph"
                ? "bg-background text-foreground shadow-sm"
                : "text-muted-foreground hover:text-foreground",
            )}
          >
            <Share2 className="h-3 w-3" />
            Graph
          </button>
          <button
            type="button"
            onClick={showTable}
            title="Table view"
            className={cn(
              "flex items-center gap-1 rounded px-2 py-1 text-xs font-medium transition-colors",
              view === "table"
                ? "bg-background text-foreground shadow-sm"
                : "text-muted-foreground hover:text-foreground",
            )}
          >
            <Table2 className="h-3 w-3" />
            Table
          </button>
        </div>

        {showSampleSize && (
          <div className="ml-auto flex items-center gap-1.5">
            <label
              htmlFor="graph-sample-size"
              className="text-[11px] text-muted-foreground whitespace-nowrap"
            >
              Sample
            </label>
            <select
              id="graph-sample-size"
              value={tableQuery.pageSize}
              disabled={isBusy}
              onChange={(event) => onPageSizeChange(Number(event.target.value))}
              className="text-[11px] bg-background border border-border rounded px-1.5 py-0.5 text-foreground cursor-pointer focus:outline-none focus:ring-1 focus:ring-ring"
            >
              {SAMPLE_SIZES.map((size) => (
                <option key={size} value={size}>
                  {size}
                </option>
              ))}
            </select>
          </div>
        )}

        {showPager && pagination && (
          <div className={cn("flex items-center gap-1.5", showSampleSize ? "" : "ml-auto")}>
            <Button
              variant="outline"
              size="icon"
              className="h-6 w-6"
              disabled={!pagination.has_prev || status !== "ready"}
              onClick={() => onPageChange(pagination.page - 1)}
              title="Previous page"
            >
              <ChevronLeft className="h-3.5 w-3.5" />
            </Button>
            <span className="text-[11px] text-muted-foreground whitespace-nowrap">
              {pagination.page} / {pagination.total_pages}
            </span>
            <Button
              variant="outline"
              size="icon"
              className="h-6 w-6"
              disabled={!pagination.has_next || status !== "ready"}
              onClick={() => onPageChange(pagination.page + 1)}
              title="Next page"
            >
              <ChevronRight className="h-3.5 w-3.5" />
            </Button>
          </div>
        )}
      </div>

      {activeFn && (
        <ConceptGraphTraversalToolbar
          fn={activeFn}
          source={pathEndpoints.source}
          target={pathEndpoints.target}
          options={options}
          isBusy={isBusy}
          onSourceChange={setSource}
          onTargetChange={setTarget}
          onOptionsChange={setOptions}
          onLoad={handleLoad}
        />
      )}

      {mode === "records" && activeAnalyticsFn && (
        <ConceptGraphAnalyticsToolbar
          key={activeAnalyticsFn.key}
          fn={activeAnalyticsFn}
          isBusy={isBusy}
          activeType={data?.analyticsType ?? null}
          onRun={onRunAnalytics}
          onClear={onClearAnalytics}
        />
      )}

      {renderBody()}
    </div>
  );
}
