import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { supabase } from "@/shared/integrations/supabase/client";
import { HttpService } from "@/shared/services/httpService";
import { getComputePayload } from "./computePayload";
import type {
  AppHostSdk,
  ConceptResultPage,
  ConceptSummary,
  FetchOptions,
  OntologySummary,
  OrderBy,
  SearchOptions,
} from "./types";

// Shapes of the raw backend responses we read from (only the fields the SDK needs).
interface RawConcept {
  predicate_name: string;
  description?: string;
  fields?: Record<string, string>;
}

interface RawOntology {
  id?: string;
  name?: string;
  scope?: "user" | "organization";
}

function isSuccess(res: unknown): res is { status: string; message?: string; data?: unknown } {
  return typeof res === "object" && res !== null && "status" in res;
}

function ensureSuccess(res: unknown, fallback: string): asserts res is { data?: unknown } {
  if (!isSuccess(res) || res.status !== "success") {
    throw new Error((isSuccess(res) && res.message) || fallback);
  }
}

// Normalize a /fetch response into the SDK's ConceptResultPage shape (same fields
// the in-tree apps read: data.results.{columnNames,facts} + data.pagination.total_count).
function toResultPage(res: unknown): ConceptResultPage {
  const data = (res as { data?: Record<string, unknown> }).data;
  const results = (data?.results ?? {}) as { columnNames?: string[]; facts?: unknown[][] };
  const pagination = (data?.pagination ?? {}) as { total_count?: number };
  return {
    columns: results.columnNames ?? [],
    rows: results.facts ?? [],
    totalCount: pagination.total_count ?? 0,
  };
}

function orderByParam(orderBy?: OrderBy): string | null {
  if (!orderBy || orderBy.length === 0) return null;
  return orderBy.map((o) => `${o.position}:${o.direction}`).join(",");
}

// Mirror of the in-tree apps' getAuthHeaders(): in remote/prod auth the backend authenticates
// the Supabase session via this header. Empty in local dev (no session) where the static
// AUTH_TOKEN handles auth instead.
async function supabaseAuthHeaders(): Promise<Record<string, string>> {
  const {
    data: { session },
  } = await supabase.auth.getSession();
  return session?.access_token ? { "X-Supabase-Token": session.access_token } : {};
}

// Builds the host SDK an app uses to talk to the backend the same way the in-tree apps do:
// a generic authenticated HTTP escape hatch + concept list/run/fetch/search helpers that
// auto-inject the selected compute. Auth (static token + Supabase session) is handled here so
// apps never touch credentials.
export function createAppSdk(scope: "user" | "organization"): AppHostSdk {
  const base = PROMETHEUX_CONFIG.BASE_URL;
  const token = PROMETHEUX_CONFIG.AUTH_TOKEN;

  const toUrl = (path: string): string => (path.startsWith("http") ? path : `${base}${path}`);

  const httpGet = async (path: string): Promise<unknown> => {
    const headers = await supabaseAuthHeaders();
    return HttpService.get(toUrl(path), token, headers);
  };

  const httpPost = async (path: string, body: unknown): Promise<unknown> => {
    const headers = await supabaseAuthHeaders();
    return HttpService.post(toUrl(path), body, token, headers);
  };

  return {
    baseUrl: base,
    scope,
    http: { get: httpGet, post: httpPost },

    async listConcepts(ontologyId: string): Promise<ConceptSummary[]> {
      const res = await httpGet(`/concepts/${ontologyId}/list?scope=${scope}`);
      ensureSuccess(res, "Failed to list concepts");
      const concepts = (Array.isArray(res.data) ? res.data : []) as RawConcept[];
      return concepts.map((c) => ({
        predicateName: c.predicate_name,
        description: c.description,
        fields: c.fields,
      }));
    },

    async runConcept(ontologyId: string, conceptName: string): Promise<void> {
      const body: Record<string, unknown> = {
        params: {},
        scope,
        force_rerun: true,
        persist_outputs: true,
      };
      const compute = await getComputePayload();
      if (compute) body.compute = compute;
      const res = await httpPost(
        `/concepts/${ontologyId}/run/${encodeURIComponent(conceptName)}`,
        body,
      );
      ensureSuccess(res, `Failed to run ${conceptName}`);
    },

    async fetchResults(
      ontologyId: string,
      conceptName: string,
      options: FetchOptions = {},
    ): Promise<ConceptResultPage> {
      const { page = 1, pageSize = 50, scope: pageScope = scope, orderBy } = options;
      const qp = new URLSearchParams({
        output_predicate: conceptName,
        project_scope: pageScope,
      });
      const body: {
        page: number;
        page_size: number;
        order_by?: string;
        compute?: Record<string, unknown>;
      } = { page, page_size: pageSize };
      const ob = orderByParam(orderBy);
      if (ob) body.order_by = ob;
      const compute = await getComputePayload();
      if (compute) body.compute = compute;
      const res = await httpPost(`/concepts/${ontologyId}/fetch?${qp}`, body);
      ensureSuccess(res, "Failed to fetch results");
      return toResultPage(res);
    },

    async searchResults(
      ontologyId: string,
      conceptName: string,
      options: SearchOptions = {},
    ): Promise<ConceptResultPage> {
      const {
        page = 1,
        pageSize = 50,
        scope: pageScope = scope,
        orderBy,
        searchTerm,
        columnFilters,
      } = options;
      const qp = new URLSearchParams({
        output_predicate: conceptName,
        project_scope: pageScope,
      });

      const hasFilters = columnFilters && Object.keys(columnFilters).length > 0;
      const body: {
        page: number;
        page_size: number;
        order_by?: string;
        search_term?: string;
        column_filters?: Array<{ position: number; value: string; operator?: string }>;
        compute?: Record<string, unknown>;
      } = { page, page_size: pageSize };
      const ob = orderByParam(orderBy);
      if (ob) body.order_by = ob;
      if (searchTerm && !hasFilters) body.search_term = searchTerm;
      if (hasFilters) {
        body.column_filters = Object.entries(columnFilters).map(([position, cf]) => ({
          position: Number.parseInt(position, 10),
          value: cf.value,
          ...(cf.operator && cf.operator !== "contains" ? { operator: cf.operator } : {}),
        }));
      }
      const compute = await getComputePayload();
      if (compute) body.compute = compute;

      const res = await httpPost(`/concepts/${ontologyId}/fetch?${qp}`, body);
      ensureSuccess(res, "Failed to search results");
      return toResultPage(res);
    },

    // Multipart upload — mirrors DataClient.uploadFile. FormData sets its own
    // Content-Type boundary, so we must NOT spread the JSON headers here; only
    // the bearer token + Supabase session header are attached.
    async uploadFile(
      file: File,
      path = "",
    ): Promise<{ filePath: string; fileName: string; fileSize: number }> {
      const formData = new FormData();
      formData.append("file", file);
      if (path) formData.append("path", path);

      const sessionHeaders = await supabaseAuthHeaders();
      const res = await fetch(toUrl("/data/files/upload"), {
        method: "POST",
        headers: { Authorization: `Bearer ${token || ""}`, ...sessionHeaders },
        body: formData,
        mode: "cors",
      });
      if (!res.ok) throw new Error(`Upload failed: HTTP ${res.status} ${res.statusText}`);

      const json = (await res.json()) as {
        status?: string;
        message?: string;
        data?: { filePath: string; fileName: string; fileSize: number };
        filePath?: string;
        fileName?: string;
        fileSize?: number;
      };
      if (json.status === "success" && json.data) return json.data;
      if (json.filePath) {
        return {
          filePath: json.filePath,
          fileName: json.fileName ?? file.name,
          fileSize: json.fileSize ?? file.size,
        };
      }
      throw new Error(json.message || "Upload failed: unexpected response format");
    },

    async listOntologies(
      scopes: Array<"user" | "organization"> = ["user", "organization"],
    ): Promise<OntologySummary[]> {
      const res = await httpGet(`/ontologies/list?scopes=${scopes.join(",")}`);
      const data = isSuccess(res) ? (res as { data?: unknown }).data : null;
      if (!Array.isArray(data)) return [];
      return data
        .map((item): OntologySummary => {
          if (typeof item === "string") return { id: item, name: item, scope: "user" };
          const p = (item ?? {}) as RawOntology;
          return { id: p.id ?? "", name: p.name ?? p.id ?? "", scope: p.scope ?? "user" };
        })
        .filter((p) => p.id);
    },

    async wsUrl(path: string): Promise<string> {
      // WebSockets can't send custom auth headers, so the host appends the static token + the
      // Supabase session token as query params (mirrors the in-tree dompe api.ts).
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const auth = new URLSearchParams({
        token: token || "",
        x_supabase_token: session?.access_token || "",
      });
      const sep = path.includes("?") ? "&" : "?";
      const fullPath = `${base}${path}${sep}${auth.toString()}`;
      if (fullPath.startsWith("http://") || fullPath.startsWith("https://")) {
        const parsed = new URL(fullPath);
        parsed.protocol = parsed.protocol === "https:" ? "wss:" : "ws:";
        return parsed.toString();
      }
      const wsProtocol = window.location.protocol === "https:" ? "wss" : "ws";
      return `${wsProtocol}://${window.location.host}${fullPath}`;
    },

    async download(path: string): Promise<Blob> {
      const sessionHeaders = await supabaseAuthHeaders();
      const res = await fetch(toUrl(path), {
        headers: { Authorization: `Bearer ${token || ""}`, ...sessionHeaders },
        mode: "cors",
      });
      if (!res.ok) throw new Error(`Download failed: HTTP ${res.status} ${res.statusText}`);
      return res.blob();
    },
  };
}
