import { LogOut, MoreVertical, ShieldCheck } from "lucide-react";
import type React from "react";
import { useCallback } from "react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";

interface SharedOntologyKebabProps {
  // Optional: team shares hide the per-share leave action.
  onLeaveShare?: () => void | Promise<void>;
  // Optional: shown only to a recipient-team owner/admin of a team share.
  onManageTeamAccess?: () => void;
}

// Kebab dropdown rendered on the hover overlay of accepted shared project
// cards. Lives in its own file because ProjectCard is already at the file-size
// limit, and because keeping the dropdown isolated makes it easy to add more
// recipient-side actions later (e.g. "View share details") without bloating
// the card component.
//
// The trigger is rendered as a div role="button" because ProjectCard wraps the
// whole card in an <a> (react-router Link), and nesting <button> inside <a> is
// invalid HTML. preventDefault + stopPropagation on the trigger keeps the
// surrounding Link inert when the user clicks the kebab.
const SharedOntologyKebab: React.FC<SharedOntologyKebabProps> = ({
  onLeaveShare,
  onManageTeamAccess,
}) => {
  const handleTriggerClick = useCallback((e: React.MouseEvent | React.KeyboardEvent) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const handleContentClick = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
  }, []);

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        {/* biome-ignore lint/a11y/useSemanticElements: button cannot nest in anchor */}
        <div
          role="button"
          tabIndex={0}
          onClick={handleTriggerClick}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") handleTriggerClick(e);
          }}
          className="p-1.5 rounded-md text-muted-foreground/40 hover:text-foreground hover:bg-secondary transition-colors"
          title="Ontology settings"
        >
          <MoreVertical className="h-3.5 w-3.5" />
        </div>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" onClick={handleContentClick}>
        {onManageTeamAccess && (
          <DropdownMenuItem className="gap-2" onSelect={onManageTeamAccess}>
            <ShieldCheck className="h-3.5 w-3.5" />
            Manage team access
          </DropdownMenuItem>
        )}
        {onLeaveShare && (
          <DropdownMenuItem
            className="gap-2 text-destructive focus:text-destructive"
            onSelect={onLeaveShare}
          >
            <LogOut className="h-3.5 w-3.5" />
            Leave share
          </DropdownMenuItem>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

export default SharedOntologyKebab;
