import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { PAGE_SIZE_OPTIONS } from "./tableOutput.utils";

interface TableOutputPaginationProps {
  page: number;
  totalPages: number;
  totalCount: number;
  pageSize: number;
  hasNext: boolean;
  isBusy: boolean;
  onPageChange: (page: number) => void;
  onPageSizeChange: (pageSize: number) => void;
}

export function TableOutputPagination({
  page,
  totalPages,
  totalCount,
  pageSize,
  hasNext,
  isBusy,
  onPageChange,
  onPageSizeChange,
}: TableOutputPaginationProps) {
  return (
    <div className="flex items-center gap-2 text-xs text-muted-foreground">
      <Button
        type="button"
        variant="outline"
        size="sm"
        disabled={page === 1 || isBusy}
        onClick={() => onPageChange(page - 1)}
      >
        Prev
      </Button>
      {isBusy ? (
        <PrometheuxSpinner size={16} />
      ) : (
        <span>
          Page {page} of {totalPages} ({totalCount} rows)
        </span>
      )}
      <Button
        type="button"
        variant="outline"
        size="sm"
        disabled={!hasNext || isBusy}
        onClick={() => onPageChange(page + 1)}
      >
        Next
      </Button>

      <div className="ml-auto flex items-center gap-2">
        <span>Rows</span>
        <Select
          value={String(pageSize)}
          onValueChange={(v) => onPageSizeChange(Number(v))}
          disabled={isBusy}
        >
          <SelectTrigger className="h-8 w-[88px] text-xs">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {PAGE_SIZE_OPTIONS.map((size) => (
              <SelectItem key={size} value={String(size)} className="text-xs">
                {size}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
    </div>
  );
}
