import type { ResolvedStep } from "../gettingStarted.types";
import { GettingStartedStepItem } from "./GettingStartedStepItem";
import { ProgressRing } from "./ProgressRing";

interface GettingStartedPopoverProps {
  steps: ResolvedStep[];
  completedCount: number;
  total: number;
  onSelect: (step: ResolvedStep) => void;
  onSkip: () => void;
}

export function GettingStartedPopover({
  steps,
  completedCount,
  total,
  onSelect,
  onSkip,
}: GettingStartedPopoverProps) {
  return (
    <div className="flex flex-col">
      <div className="flex items-center gap-3 border-b p-4">
        <ProgressRing completed={completedCount} total={total} size={32} strokeWidth={3} />
        <div className="min-w-0">
          <p className="text-sm font-semibold text-foreground">Getting started</p>
          <p className="text-xs text-muted-foreground">
            {completedCount} of {total} tasks completed
          </p>
        </div>
      </div>

      <div className="flex flex-col gap-0.5 p-2">
        {steps.map((step) => (
          <GettingStartedStepItem key={step.id} step={step} onSelect={onSelect} />
        ))}
      </div>

      <div className="border-t p-2">
        <button
          type="button"
          onClick={onSkip}
          className="w-full rounded-md px-2 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
        >
          Skip getting started
        </button>
      </div>
    </div>
  );
}
