import { useState } from "react";
import { ExplorerSearchBar } from "@/features/concept-editor/components/ExplorerSearchBar";
import type { ConceptData } from "@/features/concepts/api";
import ConceptCard from "@/features/concepts/components/ConceptCard";
import { LibrarySidebarHeader } from "@/features/concepts/components/LibrarySidebarHeader";
import { conceptParams } from "@/features/concepts/utils/paramAnnotations";
import { useOntologyConcepts } from "../../hooks/useOntologyConcepts";
import { useAppEditorStore } from "../../store/appEditorStore";

function filterConcepts(concepts: ConceptData[], searchTerm: string): ConceptData[] {
  const trimmed = searchTerm.trim().toLowerCase();
  if (!trimmed) return concepts;
  return concepts.filter(
    (concept) =>
      concept.predicate_name.toLowerCase().includes(trimmed) ||
      (concept.fields &&
        Object.keys(concept.fields).some((field) => field.toLowerCase().includes(trimmed))),
  );
}

function emptyMessage(loading: boolean, searchTerm: string): string {
  if (loading) return "Loading concepts…";
  if (searchTerm.trim()) return "No concepts match your search";
  return "No concepts found in this app's ontology";
}

/**
 * Left-dock concepts browser — the project page's concept library
 * (LibrarySidebarHeader + ConceptCard) fed from the active page's own
 * project, so authors can see predicate names and fields while wiring
 * run groups and taps.
 */
export function EditorConceptsPanel() {
  const draft = useAppEditorStore((state) => state.draft);
  const activePageId = useAppEditorStore((state) => state.activePageId);

  const page = draft?.pages.find((candidate) => candidate.id === activePageId) ?? draft?.pages[0];
  const { concepts, isLoading, isRefetching, refetch } = useOntologyConcepts(page?.project.id);

  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [expandSignal, setExpandSignal] = useState({ open: false, nonce: 0 });

  const toggleSearch = () => {
    if (isSearchOpen) setSearchTerm("");
    setIsSearchOpen(!isSearchOpen);
  };

  const closeSearch = () => {
    setSearchTerm("");
    setIsSearchOpen(false);
  };

  const toggleExpandAll = () => {
    setExpandSignal((prev) => ({ open: !prev.open, nonce: prev.nonce + 1 }));
  };

  const filtered = filterConcepts(concepts, searchTerm);

  return (
    <div className="flex h-full flex-col">
      <LibrarySidebarHeader
        title="Concepts"
        isSearchOpen={isSearchOpen}
        isSearchActive={!!searchTerm.trim()}
        onToggleSearch={toggleSearch}
        allExpanded={expandSignal.open}
        onToggleExpandAll={toggleExpandAll}
        onRefresh={refetch}
        isRefreshing={isRefetching}
      />

      {isSearchOpen && (
        <ExplorerSearchBar
          value={searchTerm}
          onChange={setSearchTerm}
          onClose={closeSearch}
          placeholder="Search concepts..."
        />
      )}

      <div
        className="flex-1 min-h-0 overflow-y-auto px-2 pb-4 pt-2"
        style={{ scrollbarGutter: "stable" }}
      >
        <div className="space-y-2">
          {filtered.length === 0 && (
            <p className="p-4 text-center text-sm text-muted-foreground">
              {emptyMessage(isLoading, searchTerm)}
            </p>
          )}
          {filtered.map((concept) => (
            <ConceptCard
              key={concept.predicate_name}
              title={concept.predicate_name}
              description={
                concept.description || `Concept with ${concept.column_count || 0} fields`
              }
              fields={concept.fields || {}}
              params={conceptParams(concept)}
              expandSignal={expandSignal}
            />
          ))}
        </div>
      </div>
    </div>
  );
}
