import type { ReactNode } from "react";

interface GraphTooltipState {
  visible: boolean;
  x: number;
  y: number;
  content: ReactNode;
}

interface GraphTooltipProps {
  tooltip: GraphTooltipState;
}

/** Custom hover tooltip rendered above a node on the graph canvas. */
export function GraphTooltip({ tooltip }: GraphTooltipProps) {
  if (!tooltip.visible) return null;

  return (
    <div
      className="absolute z-50 pointer-events-none"
      style={{
        left: tooltip.x,
        top: tooltip.y,
        transform: "translate(-50%, -100%)",
      }}
    >
      <div className="bg-gray-900 text-white px-3 py-2 rounded-md shadow-lg text-sm whitespace-pre-line max-w-xs">
        {tooltip.content}
      </div>
      {/* Tooltip arrow */}
      <div
        className="absolute left-1/2 -translate-x-1/2 -bottom-1"
        style={{
          width: 0,
          height: 0,
          borderLeft: "6px solid transparent",
          borderRight: "6px solid transparent",
          borderTop: "6px solid rgb(17, 24, 39)",
        }}
      />
    </div>
  );
}
