import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { type OntologyData, type OntologyScope, OntologyService } from "@/features/ontologies/api";
import { useShareInbox } from "@/features/ontologies/sharing/hooks/useShareInbox";
import { mergeOwnedAndShared } from "@/features/ontologies/sharing/utils/sharing.utils";
import { useAuthToken } from "@/shared/auth/useAuthToken";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

const CACHE_DURATION = 30_000;

// Module-level shared state so every useProjects instance deduplicates requests
const sharedCache = {
  lastFetchTime: 0,
  data: null as OntologyData[] | null,
  inflight: null as Promise<OntologyData[]> | null,
};

type OntologiesListener = (data: OntologyData[]) => void;
const listeners = new Set<OntologiesListener>();

function notifyListeners(data: OntologyData[]) {
  for (const fn of listeners) fn(data);
}

interface UseOntologiesOptions {
  // When true (default), accepted shares from /projects/share/inbox are merged into the
  // returned list, marked with origin="shared". Disable only for call sites that strictly
  // need owned-only projects.
  includeShared?: boolean;
}

export const useOntologies = (
  scopes: OntologyScope[] = ["user", "organization"],
  options: UseOntologiesOptions = {},
) => {
  const includeShared = options.includeShared ?? true;
  const [projects, setOntologies] = useState<OntologyData[]>(sharedCache.data ?? []);
  const [isLoading, setIsLoading] = useState(sharedCache.data === null);
  const [isCopying, setIsCopying] = useState(false);
  const ontologiesRef = useRef<OntologyData[]>(projects);
  const authToken = useAuthToken();

  // Pull accepted shares from the React Query inbox so they appear alongside owned projects
  // in pickers and the projects list. The hook is always called (React's rules-of-hooks) but
  // its result is ignored when includeShared is false. RQ dedupes the underlying request, so
  // multiple useProjects instances cost one HTTP call.
  const inbox = useShareInbox();

  useEffect(() => {
    ontologiesRef.current = projects;
  }, [projects]);

  // Subscribe to cross-instance updates
  useEffect(() => {
    const handler: OntologiesListener = (data) => setOntologies(data);
    listeners.add(handler);
    return () => {
      listeners.delete(handler);
    };
  }, []);

  const scopesKey = scopes.join(",");

  const loadOntologies = useCallback(
    async (force: boolean = false) => {
      const now = Date.now();

      if (
        !force &&
        now - sharedCache.lastFetchTime < CACHE_DURATION &&
        sharedCache.data !== null &&
        sharedCache.data.length > 0
      ) {
        setOntologies(sharedCache.data);
        setIsLoading(false);
        return;
      }

      if (!PROMETHEUX_CONFIG.DEVELOPMENT_MODE && !authToken) {
        setIsLoading(false);
        return;
      }

      // If another instance already has a request in flight, piggyback on it
      if (sharedCache.inflight) {
        try {
          setIsLoading(true);
          const data = await sharedCache.inflight;
          setOntologies(data);
        } catch {
          // already logged by the original caller
        } finally {
          setIsLoading(false);
        }
        return;
      }

      try {
        setIsLoading(true);
        const request = OntologyService.listOntologies(scopesKey.split(",") as OntologyScope[]);
        sharedCache.inflight = request;

        const ontologiesData = await request;

        sharedCache.data = ontologiesData;
        sharedCache.lastFetchTime = Date.now();

        setOntologies(ontologiesData);
        notifyListeners(ontologiesData);
      } catch (error) {
        console.error("Error loading ontologies:", error);
      } finally {
        sharedCache.inflight = null;
        setIsLoading(false);
      }
    },
    [authToken, scopesKey],
  );

  // Update a project (name and description)
  const renameOntology = useCallback(
    async (id: string, newName: string, newDescription: string = ""): Promise<void> => {
      try {
        // Find the project to get its scope
        const project = projects.find((p) => p.id === id);
        if (!project) {
          throw new Error("Ontology not found");
        }

        // Update local state first for immediate UI feedback
        setOntologies((prev) =>
          prev.map((p) => (p.id === id ? { ...p, name: newName, description: newDescription } : p)),
        );

        // Call API to save the updates
        const success = await OntologyService.saveOntology(
          id,
          newName,
          newDescription,
          project.scope,
        );

        if (success) {
          // Dispatch custom event to notify other useProjects instances
          window.dispatchEvent(
            new CustomEvent("projectUpdated", {
              detail: { id, newName, newDescription, scope: project.scope },
            }),
          );
        } else {
          // Revert local state on API failure
          setOntologies((prev) =>
            prev.map((p) =>
              p.id === id ? { ...p, name: project.name, description: project.description } : p,
            ),
          );
        }
      } catch (error) {
        console.error("Error updating ontology:", error);

        // Revert local state on error
        const originalOntology = projects.find((p) => p.id === id);
        if (originalOntology) {
          setOntologies((prev) =>
            prev.map((p) =>
              p.id === id
                ? { ...p, name: originalOntology.name, description: originalOntology.description }
                : p,
            ),
          );
        }
        throw error;
      }
    },
    [projects],
  );

  // Copy a project
  const copyOntology = useCallback(
    async (
      ontologyId: string,
      newOntologyName: string,
      targetScope: OntologyScope = "user",
    ): Promise<void> => {
      try {
        setIsCopying(true);

        // Call API to copy the project
        const newOntologyId = await OntologyService.copyOntology(
          ontologyId,
          newOntologyName,
          targetScope,
        );

        if (newOntologyId) {
          // Automatically refresh the projects list to show the new project (force refresh)
          await loadOntologies(true);

          // Dispatch custom event to notify other useProjects instances
          window.dispatchEvent(
            new CustomEvent("projectCopied", {
              detail: { newOntologyId, newOntologyName },
            }),
          );
        }
      } catch (error) {
        console.error("Error copying ontology:", error);
        throw error;
      } finally {
        setIsCopying(false);
      }
    },
    [loadOntologies],
  );

  // Listen for project update events from other useProjects instances
  useEffect(() => {
    const handleOntologyUpdated = (event: CustomEvent) => {
      const { id, newName, newDescription } = event.detail;

      setOntologies((prev) =>
        prev.map((project) =>
          project.id === id ? { ...project, name: newName, description: newDescription } : project,
        ),
      );
    };

    const handleOntologyCopied = (event: CustomEvent) => {
      const { newOntologyId, newOntologyName } = event.detail;

      // Refresh projects list to get the new project data (force refresh)
      loadOntologies(true);
    };

    // Listen for both old and new event names for compatibility
    window.addEventListener("projectUpdated", handleOntologyUpdated as EventListener);
    window.addEventListener("projectRenamed", handleOntologyUpdated as EventListener);
    window.addEventListener("projectCopied", handleOntologyCopied as EventListener);

    return () => {
      window.removeEventListener("projectUpdated", handleOntologyUpdated as EventListener);
      window.removeEventListener("projectRenamed", handleOntologyUpdated as EventListener);
      window.removeEventListener("projectCopied", handleOntologyCopied as EventListener);
    };
  }, [loadOntologies]);

  // Initial load - only run once on mount
  useEffect(() => {
    loadOntologies();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadOntologies]);

  const prevBaseUrlRef = useRef(PROMETHEUX_CONFIG.BASE_URL);

  // Sign-in produces the token after this hook has already mounted and given
  // up once, so the load is retried when it lands.
  useEffect(() => {
    if (!authToken || ontologiesRef.current.length > 0) return;
    loadOntologies(true);
  }, [authToken, loadOntologies]);

  // Retry loading projects when BASE_URL changes (after session restoration or manual override)
  useEffect(() => {
    const urlChanged = prevBaseUrlRef.current !== PROMETHEUX_CONFIG.BASE_URL;
    prevBaseUrlRef.current = PROMETHEUX_CONFIG.BASE_URL;

    if (urlChanged && PROMETHEUX_CONFIG.AUTH_TOKEN) {
      loadOntologies(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadOntologies]);

  const mergedOntologies = useMemo<OntologyData[]>(() => {
    if (!includeShared) return projects;
    return mergeOwnedAndShared(projects, inbox.entries);
  }, [includeShared, projects, inbox.entries]);

  return {
    projects: mergedOntologies,
    isLoading,
    isCopying,
    loadOntologies,
    renameOntology,
    copyOntology,
  };
};
