import { Camera, Trash2, Upload, User } from "lucide-react";
import type React from "react";
import { useRef, useState } from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";
import { Avatar, AvatarFallback, AvatarImage } from "@/shared/components/ui/avatar";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Label } from "@/shared/components/ui/label";
import { cn } from "@/shared/lib/utils";

interface AvatarUploadProps {
  currentAvatarUrl?: string | null;
  onAvatarChange: (file: File) => void;
  onAvatarRemove: () => void;
  isUploading?: boolean;
  isDeleting?: boolean;
  userName?: string;
  disabled?: boolean;
}

export const AvatarUpload: React.FC<AvatarUploadProps> = ({
  currentAvatarUrl,
  onAvatarChange,
  onAvatarRemove,
  isUploading = false,
  isDeleting = false,
  userName = "User",
  disabled = false,
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);

  // Get initials for fallback avatar
  const _getInitials = (name: string) => {
    const parts = name.trim().split(" ");
    if (parts.length >= 2) {
      return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
    }
    return name.slice(0, 2).toUpperCase();
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Validate file type
    const validTypes = ["image/jpeg", "image/jpg", "image/png", "image/gif", "image/webp"];
    if (!validTypes.includes(file.type)) {
      alert("Invalid file type. Please upload a JPG, PNG, GIF, or WebP image.");
      return;
    }

    // Validate file size (max 5MB)
    const maxSize = 5 * 1024 * 1024;
    if (file.size > maxSize) {
      alert("File size too large. Maximum size is 5MB.");
      return;
    }

    // Create preview
    const reader = new FileReader();
    reader.onloadend = () => {
      setPreviewUrl(reader.result as string);
    };
    reader.readAsDataURL(file);

    // Trigger upload
    onAvatarChange(file);
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleRemoveClick = () => {
    setShowDeleteDialog(true);
  };

  const confirmRemove = () => {
    setPreviewUrl(null);
    onAvatarRemove();
    setShowDeleteDialog(false);

    // Reset file input
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const displayUrl = previewUrl || currentAvatarUrl;
  const hasAvatar = !!displayUrl;
  const isLoading = isUploading || isDeleting;

  return (
    <div className="space-y-4">
      <Label>Profile Picture</Label>

      <div className="flex items-center gap-6">
        {/* Avatar Display */}
        <div className="relative">
          <Avatar className="h-24 w-24 border-2 border-border">
            {displayUrl ? (
              <AvatarImage src={displayUrl} alt={userName} />
            ) : (
              <AvatarFallback className="text-2xl">
                <User className="h-12 w-12" />
              </AvatarFallback>
            )}
          </Avatar>

          {/* Camera overlay on hover */}
          {!disabled && !isLoading && (
            <button
              type="button"
              onClick={handleUploadClick}
              className={cn(
                "absolute inset-0 rounded-full bg-black/60 opacity-0 hover:opacity-100",
                "flex items-center justify-center transition-opacity cursor-pointer",
                "focus:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
              )}
              aria-label="Change avatar"
            >
              <Camera className="h-8 w-8 text-white" />
            </button>
          )}

          {/* Loading spinner */}
          {isLoading && (
            <div className="absolute inset-0 rounded-full bg-black/60 flex items-center justify-center">
              <PrometheuxSpinner size={36} />
            </div>
          )}
        </div>

        {/* Action Buttons */}
        <div className="flex flex-col gap-2">
          <input
            ref={fileInputRef}
            type="file"
            accept="image/jpeg,image/jpg,image/png,image/gif,image/webp"
            onChange={handleFileSelect}
            className="hidden"
            disabled={disabled || isLoading}
          />

          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handleUploadClick}
            disabled={disabled || isLoading}
            className="w-full"
          >
            <Upload className="h-4 w-4 mr-2" />
            {hasAvatar ? "Change Avatar" : "Upload Avatar"}
          </Button>

          {hasAvatar && (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleRemoveClick}
              disabled={disabled || isLoading}
              className="w-full text-destructive hover:text-destructive"
            >
              <Trash2 className="h-4 w-4 mr-2" />
              Remove Avatar
            </Button>
          )}
        </div>
      </div>

      {/* Helper text */}
      <p className="text-sm text-muted-foreground">
        Recommended: Square image, at least 200x200px. Max file size: 5MB.
        <br />
        Supported formats: JPG, PNG, GIF, WebP
      </p>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove Avatar</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to remove your profile picture? It cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmRemove}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};
