import { FileSpreadsheet } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";

interface SheetPickerDialogProps {
  open: boolean;
  sheets: string[];
  fileName: string;
  onSelect: (sheetName: string) => void;
  onCancel: () => void;
}

export function SheetPickerDialog({
  open,
  sheets,
  fileName,
  onSelect,
  onCancel,
}: SheetPickerDialogProps) {
  const [selected, setSelected] = useState<string | null>(null);

  const handleConfirm = () => {
    if (!selected) return;
    onSelect(selected);
  };

  return (
    <Dialog open={open} onOpenChange={(isOpen) => !isOpen && onCancel()}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileSpreadsheet className="h-5 w-5 text-primary" />
            Select a sheet
          </DialogTitle>
          <DialogDescription>
            <span className="font-medium">{fileName}</span> contains multiple sheets. Select which
            one to connect.
          </DialogDescription>
        </DialogHeader>

        <div className="max-h-60 overflow-y-auto rounded-md border border-border">
          {sheets.map((sheet) => (
            <button
              key={sheet}
              type="button"
              onClick={() => setSelected(sheet)}
              className={`w-full px-4 py-2.5 text-left text-sm transition-colors ${
                selected === sheet
                  ? "bg-primary/10 text-primary font-medium"
                  : "hover:bg-accent text-foreground"
              }`}
            >
              {sheet}
            </button>
          ))}
        </div>

        <DialogFooter>
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
          <Button type="button" disabled={!selected} onClick={handleConfirm}>
            Connect
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
