import { create } from "zustand";

interface ConfigStore {
  /**
   * Bumped whenever the user's LLM/embedding config is (re)loaded from the
   * backend or saved. The config itself lives in the mutable `PROMETHEUX_CONFIG`
   * global, which components can't subscribe to; consumers read this counter to
   * re-render (and re-read the global) once the real config lands — e.g. after
   * login, when the auth token arrives asynchronously after first mount.
   */
  configVersion: number;
  bumpConfigVersion: () => void;
}

export const useConfigStore = create<ConfigStore>((set) => ({
  configVersion: 0,
  bumpConfigVersion: () => set((state) => ({ configVersion: state.configVersion + 1 })),
}));
