import type React from "react";
import { CellApiButton } from "@/features/concept-editor/components/query/components/CellApiButton";
import { CellTypeSelect } from "@/features/concept-editor/components/query/components/CellTypeSelect";
import { GroupSelector } from "@/features/concept-editor/components/query/components/GroupSelector";
import type { ConceptCell, ConceptType } from "@/features/concept-editor/types";

/**
 * Marks the header's own controls so clicking them doesn't also toggle the cell.
 * Cheaper and more robust than stopping propagation on every wrapper.
 */
const CONTROL_SELECTOR = "[data-cell-header-control]";

interface CellHeaderRowProps {
  cell: ConceptCell;
  isOpen: boolean;
  /** Concept type to show when the cell has none yet. */
  defaultConceptType: ConceptType;
  onToggle: () => void;
  onCellTypeChange?: (cellId: string, conceptType: ConceptType) => void;
  buildCurlSnippet: (apiKey: string) => string;
  currentGroup?: string | null;
  groupNames?: string[];
  onAddCellToGroup?: (cellId: string, groupName: string) => void;
  onRemoveCellFromGroup?: (cellId: string) => void;
  /** Concept-name widget: a rename control, or a predicate picker for logic cells. */
  identity: React.ReactNode;
  /** Optional status chips (e.g. "non-deterministic", note count). */
  badges?: React.ReactNode;
  toolbar: React.ReactNode;
}

/**
 * The header strip of a concept cell: name widget, type selector, description
 * preview, API snippet button, group control, and the run/save toolbar. Clicking
 * anywhere outside those controls expands or collapses the cell.
 */
export function CellHeaderRow({
  cell,
  isOpen,
  defaultConceptType,
  onToggle,
  onCellTypeChange,
  buildCurlSnippet,
  currentGroup,
  groupNames,
  onAddCellToGroup,
  onRemoveCellFromGroup,
  identity,
  badges,
  toolbar,
}: CellHeaderRowProps) {
  const handleTypeChange = (conceptType: ConceptType) => {
    onCellTypeChange?.(cell.id, conceptType);
  };

  const isFromControl = (target: EventTarget) =>
    target instanceof Element && !!target.closest(CONTROL_SELECTOR);

  const handleClick = (event: React.MouseEvent) => {
    if (isFromControl(event.target)) return;
    onToggle();
  };

  // Keyboard activation for the header, which can't be a real <button> (see below).
  // The control check keeps Enter and Space typed in the name field from toggling.
  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (isFromControl(event.target)) return;
    if (event.key !== "Enter" && event.key !== " ") return;
    event.preventDefault();
    onToggle();
  };

  return (
    <div className="flex flex-wrap w-full items-center bg-muted/60 transition-colors duration-200">
      <div className="flex-1 min-w-0">
        {/* The header can't be a real <button> because it contains interactive
            controls (Selects, dropdowns), and a <button> inside a <button> is
            invalid HTML that breaks click handling. */}
        {/* biome-ignore lint/a11y/useSemanticElements: see comment above */}
        <div
          role="button"
          tabIndex={0}
          className="flex flex-1 min-w-0 items-center pl-4 pr-2.5 py-2 cursor-pointer text-left"
          onClick={handleClick}
          onKeyDown={handleKeyDown}
        >
          <div className="flex items-center flex-wrap gap-x-2 gap-y-1 w-full min-w-0">
            <div className="flex-shrink-0" data-cell-header-control>
              {identity}
            </div>

            <div className="flex-shrink-0" data-cell-header-control>
              <CellTypeSelect
                value={cell.conceptType || defaultConceptType}
                onChange={handleTypeChange}
              />
            </div>

            {badges}

            {!isOpen && cell.description && (
              <div className="flex-1 ml-2 text-left min-w-0">
                <span className="text-xs text-muted-foreground truncate block">
                  {cell.description}
                </span>
              </div>
            )}

            <div className="flex-shrink-0 ml-2" data-cell-header-control>
              <CellApiButton contextLabel={cell.outputPredicate} buildSnippet={buildCurlSnippet} />
            </div>

            <div className="flex-shrink-0 ml-2" data-cell-header-control>
              <GroupSelector
                cellId={cell.id}
                currentGroup={currentGroup ?? undefined}
                groupNames={groupNames}
                onAssign={onAddCellToGroup}
                onRemove={onRemoveCellFromGroup}
              />
            </div>
          </div>
        </div>
      </div>
      <div className="flex-shrink-0">{toolbar}</div>
    </div>
  );
}
