import { Handle, type NodeProps, Position } from "@xyflow/react";
import { ChevronDown, ChevronUp, Lock, MoreVertical, Pencil, Shield, Trash2 } from "lucide-react";
import type React from "react";
import { createContext, memo, useCallback, useContext, useEffect, useRef, useState } from "react";
import { getIconTypeForBinaryFile } from "@/features/data-sources/utils";
import type { ConceptCardCustomData } from "@/features/ontology-schema/types";
import DatabaseIcon, { getDatabaseIconColorClass } from "@/shared/components/icons/DatabaseIcon";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import { GroupBadge } from "./ConceptCardBadges";
import { ConceptCardBody } from "./ConceptCardBody";
import { StatusIndicator, statusBorderClass, statusTitle } from "./ConceptCardStatusIndicator";
import { groupColor, groupColorSoft } from "./lineage-view/groupColors";

// ---------------------------------------------------------------------------
// Context for card actions (provided by LineageView)
// ---------------------------------------------------------------------------

export interface LineageCardActions {
  onRename: (oldName: string, newName: string) => Promise<void>;
  onDelete: (conceptName: string) => Promise<void>;
  // Open the concept-permissions dialog. Only offered to the project owner, so
  // the menu item is hidden unless `canManagePermissions` is true.
  onManagePermissions?: (conceptName: string) => void;
  canManagePermissions?: boolean;
}

const noop = async () => {};
export const LineageCardActionsContext = createContext<LineageCardActions>({
  onRename: noop,
  onDelete: noop,
});

/** Minimum / maximum rendered card width (px). Names past the max still truncate. */
export const CONCEPT_CARD_MIN_WIDTH = 200;
export const CONCEPT_CARD_MAX_WIDTH = 480;

/** Fixed horizontal chrome around the name: padding + gaps + status circle + 2 action buttons. */
const CONCEPT_CARD_CHROME_WIDTH = 138;

/** Datasource chrome: full-height icon panel (64) + name padding (32). */
export const DATASOURCE_CARD_CHROME_WIDTH = 96;

/** Per-char name-width estimate at 25px; a slight over-estimate of real Inter
 * rendering so short names get room and only long names (hitting the max) trim. */
const CONCEPT_CARD_NAME_CHAR_WIDTH = 17;

/**
 * Estimate the rendered width of a card so the width tracks the name length
 * instead of cropping it. Clamped between a sensible min and max; the same
 * value is used for both dagre layout and rendering so they stay in sync.
 * Datasource nodes pass a smaller chrome since they have no action buttons.
 */
export const getConceptCardWidth = (
  label: string,
  chromeWidth: number = CONCEPT_CARD_CHROME_WIDTH,
): number => {
  const width = chromeWidth + label.length * CONCEPT_CARD_NAME_CHAR_WIDTH;
  return Math.min(CONCEPT_CARD_MAX_WIDTH, Math.max(CONCEPT_CARD_MIN_WIDTH, width));
};

/**
 * Header height (status bar + large name + actions), shown in every state.
 * Tall enough that the name stays legible when the whole chart is zoomed out.
 */
export const CONCEPT_CARD_HEADER_HEIGHT = 80;

/** Height per visible field row (expanded only) */
export const CONCEPT_CARD_FIELD_HEIGHT = 36;

/** Height of the always-on row-count footer (populated concepts only). */
export const CONCEPT_CARD_FOOTER_HEIGHT = 44;

/**
 * Calculate the pixel height of a concept card. Collapsed cards show only the
 * header; expanded cards add a row per field. Populated concepts always add the
 * row-count footer. The expand/collapse toggle lives inside the header, so it
 * costs no extra height.
 */
export const getConceptCardHeight = (
  fieldCount: number,
  isExpanded: boolean,
  hasFooter: boolean = false,
): number => {
  const footer = hasFooter ? CONCEPT_CARD_FOOTER_HEIGHT : 0;
  if (!isExpanded) {
    return CONCEPT_CARD_HEADER_HEIGHT + footer;
  }
  return CONCEPT_CARD_HEADER_HEIGHT + fieldCount * CONCEPT_CARD_FIELD_HEIGHT + footer;
};

const invisibleHandle: React.CSSProperties = {
  width: 1,
  height: 1,
  background: "transparent",
  border: "none",
  opacity: 0,
};

const ConceptCardNode: React.FC<NodeProps> = ({ data, selected }) => {
  const typedData = data as unknown as ConceptCardCustomData & {
    nodeType?: string;
    datasource_label?: string;
    bind_annotation?: string;
    hasContext?: boolean;
    isRestricted?: boolean;
  };
  const {
    label,
    fields = {},
    datasource_type,
    isExpanded: initialExpanded,
    nodeType,
    datasource_label,
    executionStatus,
    bind_annotation,
    concept_type,
    group,
    is_populated,
    row_count,
    execution_time_ms,
    hasContext,
  } = typedData;
  const [isExpanded, setIsExpanded] = useState(initialExpanded ?? false);

  // Inline rename state
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(label);
  const editInputRef = useRef<HTMLInputElement>(null);

  // Delete confirmation state
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);

  const { onRename, onDelete, onManagePermissions, canManagePermissions } =
    useContext(LineageCardActionsContext);

  const fieldEntries = Object.entries(fields);
  const fieldCount = fieldEntries.length;
  const hasExpandable = fieldCount > 0;

  const toggleExpand = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    setIsExpanded((prev) => !prev);
  }, []);

  // Sync with the "expand/collapse all" toggle: when the node's data.isExpanded
  // value changes (driven from LineageView), mirror it into local state. Local
  // per-card toggles don't touch data, so they survive unrelated re-renders.
  useEffect(() => {
    setIsExpanded(initialExpanded ?? false);
  }, [initialExpanded]);

  const handleStartEdit = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      setEditValue(label);
      setIsEditing(true);
    },
    [label],
  );

  useEffect(() => {
    if (isEditing && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [isEditing]);

  const handleConfirmRename = useCallback(() => {
    const trimmed = editValue.trim().toLowerCase();
    setIsEditing(false);
    if (trimmed && trimmed !== label) {
      onRename(label, trimmed);
    }
  }, [editValue, label, onRename]);

  const handleEditKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      e.stopPropagation();
      if (e.key === "Enter") {
        handleConfirmRename();
      } else if (e.key === "Escape") {
        setIsEditing(false);
        setEditValue(label);
      }
    },
    [handleConfirmRename, label],
  );

  const handleDeleteClick = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    setDeleteDialogOpen(true);
  }, []);

  const handleManagePermissionsClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onManagePermissions?.(label);
    },
    [onManagePermissions, label],
  );

  const handleConfirmDelete = useCallback(() => {
    setDeleteDialogOpen(false);
    onDelete(label);
  }, [label, onDelete]);

  // Group identity colour owns the left edge whenever the concept belongs to a
  // group, even mid-run — execution state is already conveyed by the status
  // circle (spinner / tick / cross), so the group colour stays readable. Only
  // ungrouped concepts fall back to the status-coloured left border.
  const groupAccent = groupColor(group);
  const groupBadgeBg = groupColorSoft(group);
  const statusBorder = groupAccent ? "" : statusBorderClass(executionStatus);
  const groupAccentStyle: React.CSSProperties = groupAccent
    ? { borderLeftWidth: 4, borderLeftColor: groupAccent }
    : {};

  // Concept hidden for this scoped session: it only appears because a visible
  // concept references its name. Render an anonymized, non-interactive
  // placeholder — no name, no actions, no navigation (blocked in LineageView).
  if (typedData.isRestricted) {
    return (
      <div
        className="relative flex min-h-[80px] cursor-default items-center gap-2.5 rounded-lg border border-dashed border-border bg-muted/40 px-4 shadow-sm"
        style={{ width: getConceptCardWidth("Restricted concept") }}
        title="Restricted concept — hidden by the ontology owner"
      >
        <Handle
          type="target"
          position={Position.Left}
          style={{ ...invisibleHandle, left: 0, top: "50%" }}
        />
        <Lock className="h-5 w-5 flex-shrink-0 text-muted-foreground" />
        <span className="truncate text-[22px] font-normal italic text-muted-foreground">
          Restricted concept
        </span>
        <Handle
          type="source"
          position={Position.Right}
          style={{ ...invisibleHandle, right: 0, top: "50%" }}
        />
      </div>
    );
  }

  if (nodeType === "datasource") {
    const displayName = datasource_label || datasource_type || "Data Source";
    const resolvedIconType =
      datasource_type?.toLowerCase() === "binaryfile" && bind_annotation
        ? getIconTypeForBinaryFile(bind_annotation)
        : datasource_type || "unknown";
    const iconColorClass = getDatabaseIconColorClass(resolvedIconType);
    return (
      <div
        className={`bg-card dark:bg-flow-node-bg rounded-lg shadow-md overflow-hidden relative cursor-default ${selected ? "ring-2 ring-blue-500 ring-offset-1 border-blue-500" : "border border-border"}`}
        style={{ width: getConceptCardWidth(displayName, DATASOURCE_CARD_CHROME_WIDTH) }}
      >
        <Handle
          type="target"
          position={Position.Left}
          style={{ ...invisibleHandle, left: 0, top: "50%" }}
        />
        <Handle
          type="source"
          position={Position.Right}
          style={{ ...invisibleHandle, right: 0, top: "50%" }}
        />
        <div className="flex items-stretch min-h-[80px]">
          {/* Full-height colored panel carrying the white icon */}
          <div
            className={`flex w-16 flex-shrink-0 items-center justify-center rounded-l-lg bg-current ${iconColorClass}`}
          >
            <DatabaseIcon type={resolvedIconType} className="h-8 w-8" colorClassName="text-white" />
          </div>
          <div className="flex flex-1 min-w-0 items-center px-4">
            <span
              className="text-[25px] font-normal truncate text-foreground min-w-0"
              title={displayName}
            >
              {displayName}
            </span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div
      className={`bg-card rounded-lg shadow-md overflow-hidden relative ${statusBorder} ${selected ? "ring-2 ring-blue-500 ring-offset-1 border-blue-500" : "border border-border"}`}
      style={{ width: getConceptCardWidth(label), ...groupAccentStyle }}
    >
      <Handle
        type="target"
        position={Position.Left}
        style={{ ...invisibleHandle, left: 0, top: "50%" }}
      />

      {/* Header — status bar + name + actions (and collapse chevron when expanded) */}
      <div
        className={`flex items-center gap-2.5 px-4 min-h-[80px] ${isExpanded ? "border-b border-border bg-muted/30" : ""}`}
      >
        <span className="flex shrink-0 items-center" title={statusTitle(executionStatus)}>
          <StatusIndicator status={executionStatus} />
        </span>

        {isEditing ? (
          <input
            ref={editInputRef}
            value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onKeyDown={handleEditKeyDown}
            onBlur={handleConfirmRename}
            onClick={(e) => e.stopPropagation()}
            className="text-[25px] font-normal text-foreground flex-1 min-w-0 bg-background border border-input rounded px-1.5 py-0.5 outline-none focus:ring-1 focus:ring-ring"
          />
        ) : (
          <span
            className="text-[25px] font-normal truncate text-foreground flex-1 min-w-0"
            title={label}
          >
            {label}
          </span>
        )}

        <GroupBadge
          group={group}
          accent={groupAccent}
          softBg={groupBadgeBg}
          visible={isExpanded && !isEditing}
        />

        {/* Expand/collapse toggle */}
        {hasExpandable && (
          <button
            type="button"
            onClick={toggleExpand}
            aria-label={isExpanded ? "Collapse" : "Expand"}
            className="flex-shrink-0 flex items-center justify-center h-7 w-7 rounded hover:bg-muted transition-colors text-muted-foreground hover:text-foreground"
          >
            {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
          </button>
        )}

        {/* Three-dot actions menu */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button
              type="button"
              onClick={(e) => e.stopPropagation()}
              className="flex-shrink-0 flex items-center justify-center h-7 w-7 rounded hover:bg-muted transition-colors text-muted-foreground hover:text-foreground"
            >
              <MoreVertical className="h-4 w-4" />
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="min-w-[140px]">
            {canManagePermissions && onManagePermissions && (
              <>
                <DropdownMenuItem
                  onClick={handleManagePermissionsClick}
                  className="gap-2 cursor-pointer"
                >
                  <Shield className="h-3.5 w-3.5" />
                  Permissions
                </DropdownMenuItem>
                <DropdownMenuSeparator />
              </>
            )}
            <DropdownMenuItem onClick={handleStartEdit} className="gap-2 cursor-pointer">
              <Pencil className="h-3.5 w-3.5" />
              Rename
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              onClick={handleDeleteClick}
              className="gap-2 cursor-pointer text-red-600 focus:text-red-600"
            >
              <Trash2 className="h-3.5 w-3.5" />
              Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      {/* Lower body — always-on row-count footer; column list when expanded */}
      <ConceptCardBody
        fields={fieldEntries}
        isExpanded={isExpanded}
        isPopulated={is_populated}
        rowCount={row_count}
        executionTimeMs={execution_time_ms}
        hasContext={hasContext}
        conceptType={concept_type}
      />

      <Handle
        type="source"
        position={Position.Right}
        style={{ ...invisibleHandle, right: 0, top: "50%" }}
      />

      {/* Delete confirmation dialog */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent onClick={(e) => e.stopPropagation()}>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Concept</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete &ldquo;{label}&rdquo;? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmDelete}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

export default memo(ConceptCardNode);
