import {
  ArrowDownToLine,
  Check,
  ChevronLeft,
  ChevronRight,
  RefreshCw,
  Search,
  Terminal,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { engineClient } from "../api/EngineClient";
import { useLogFile } from "../hooks/useLogFile";
import type { LogLevel } from "../types/engineMonitor.types";
import { LOG_LEVELS } from "../types/engineMonitor.types";
import {
  entryMatchesFilter,
  formatTimestamp,
  type ParsedLogEntry,
  parseLogContent,
  shortLogger,
} from "../utils/logParser";

interface EngineMonitorLogsProps {
  active: boolean;
}

const INHERIT_VALUE = "__INHERIT__";
const CONFIRMATION_MS = 2000;
const PAGE_SIZE = 200;

interface LevelControl {
  value: string;
  isApplying: boolean;
  error: string | null;
  appliedAt: number | null;
}

const INITIAL_LEVEL: LevelControl = {
  value: INHERIT_VALUE,
  isApplying: false,
  error: null,
  appliedAt: null,
};

function levelBadgeClass(level: LogLevel | null): string {
  switch (level) {
    case "ERROR":
      return "bg-red-500/15 text-red-600 dark:bg-red-500/20 dark:text-red-400 ring-1 ring-inset ring-red-500/30";
    case "WARN":
      return "bg-amber-500/15 text-amber-700 dark:bg-amber-500/20 dark:text-amber-400 ring-1 ring-inset ring-amber-500/30";
    case "INFO":
      return "bg-sky-500/10 text-sky-700 dark:bg-sky-500/15 dark:text-sky-400 ring-1 ring-inset ring-sky-500/25";
    case "DEBUG":
      return "bg-muted text-muted-foreground ring-1 ring-inset ring-border";
    case "TRACE":
      return "bg-muted text-muted-foreground/80 ring-1 ring-inset ring-border";
    default:
      return "bg-muted/60 text-muted-foreground/60 ring-1 ring-inset ring-border/60";
  }
}

function messageToneClass(level: LogLevel | null): string {
  switch (level) {
    case "ERROR":
      return "text-red-700 dark:text-red-300";
    case "WARN":
      return "text-amber-800 dark:text-amber-200";
    case "INFO":
      return "text-foreground";
    case "DEBUG":
    case "TRACE":
      return "text-muted-foreground";
    default:
      return "text-foreground/90";
  }
}

function formatSince(ts: number | null): string {
  if (!ts) return "never";
  const seconds = Math.max(0, Math.round((Date.now() - ts) / 1000));
  if (seconds < 60) return `${seconds}s ago`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes}m ago`;
}

interface LogRowProps {
  entry: ParsedLogEntry;
}

const LogRow: React.FC<LogRowProps> = ({ entry }) => {
  const time = formatTimestamp(entry.timestamp);
  const loggerShort = shortLogger(entry.logger);
  const hasContinuations = entry.continuations.length > 0;

  return (
    <div className="group grid grid-cols-[72px_64px_minmax(120px,180px)_minmax(80px,140px)_1fr] items-start gap-2 px-2 py-1 rounded hover:bg-muted/40 transition-colors">
      <div
        className="font-mono text-[10px] text-muted-foreground/60 tabular-nums truncate pt-0.5"
        title={entry.timestamp ?? ""}
      >
        {time || "—"}
      </div>
      <div className="flex items-center">
        <span
          className={`inline-flex h-4 min-w-[52px] items-center justify-center rounded px-1 text-[9px] font-semibold uppercase tracking-wider ${levelBadgeClass(entry.level)}`}
        >
          {entry.level ?? "log"}
        </span>
      </div>
      <div
        className="font-mono text-[10px] text-muted-foreground truncate pt-0.5"
        title={entry.logger ?? ""}
      >
        {loggerShort || "—"}
      </div>
      <div
        className="font-mono text-[10px] text-muted-foreground/70 truncate pt-0.5"
        title={entry.thread ?? ""}
      >
        {entry.thread ?? "—"}
      </div>
      <div
        className={`font-mono text-[11px] break-words whitespace-pre-wrap ${messageToneClass(entry.level)}`}
      >
        {entry.message}
        {hasContinuations ? (
          <pre className="mt-1 pl-3 border-l-2 border-border/60 text-[10px] text-muted-foreground whitespace-pre-wrap break-words">
            {entry.continuations.join("\n")}
          </pre>
        ) : null}
      </div>
    </div>
  );
};

const EngineMonitorLogs: React.FC<EngineMonitorLogsProps> = ({ active }) => {
  const { content, isLoading, lastUpdatedAt, error, refresh } = useLogFile({ enabled: active });
  const [filter, setFilter] = useState<string>("");
  const [autoScroll, setAutoScroll] = useState<boolean>(true);
  const [level, setLevel] = useState<LevelControl>(INITIAL_LEVEL);
  const [windowEnd, setWindowEnd] = useState<number | null>(null);
  const scrollerRef = useRef<HTMLDivElement | null>(null);
  const confirmTimerRef = useRef<number | null>(null);

  const entries = useMemo(() => (content ? parseLogContent(content) : []), [content]);

  const filteredEntries = useMemo(() => {
    if (!filter) return entries;
    return entries.filter((e) => entryMatchesFilter(e, filter));
  }, [entries, filter]);

  const totalFiltered = filteredEntries.length;
  const isTailing = windowEnd === null;
  const effectiveEnd = isTailing ? totalFiltered : Math.min(windowEnd, totalFiltered);
  const effectiveStart = Math.max(0, effectiveEnd - PAGE_SIZE);
  const visibleEntries = filteredEntries.slice(effectiveStart, effectiveEnd);

  const canGoOlder = effectiveStart > 0;
  const canGoNewer = !isTailing;
  const newerCount = isTailing ? 0 : totalFiltered - effectiveEnd;

  // biome-ignore lint/correctness/useExhaustiveDependencies: intentionally resets the pagination window whenever the filter changes
  useEffect(() => {
    setWindowEnd(null);
  }, [filter]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: visibleEntries is an intentional change-trigger so auto-scroll fires when new lines arrive
  useEffect(() => {
    if (!isTailing) return;
    if (!autoScroll) return;
    const el = scrollerRef.current;
    if (!el) return;
    el.scrollTop = el.scrollHeight;
  }, [visibleEntries, autoScroll, isTailing]);

  useEffect(() => {
    return () => {
      if (confirmTimerRef.current !== null) {
        window.clearTimeout(confirmTimerRef.current);
      }
    };
  }, []);

  const handleFilterChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setFilter(event.target.value);
  };

  const handleAutoScrollChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setAutoScroll(event.target.checked);
  };

  const handleOlder = () => {
    const nextEnd = Math.max(PAGE_SIZE, effectiveEnd - PAGE_SIZE);
    setWindowEnd(nextEnd);
  };

  const handleNewer = () => {
    const nextEnd = Math.min(totalFiltered, effectiveEnd + PAGE_SIZE);
    setWindowEnd(nextEnd >= totalFiltered ? null : nextEnd);
  };

  const handleJumpToLive = () => {
    setWindowEnd(null);
    const el = scrollerRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  };

  const handleLevelChange = async (value: string) => {
    const nextLevel: LogLevel | null = value === INHERIT_VALUE ? null : (value as LogLevel);
    setLevel((prev) => ({ ...prev, value, isApplying: true, error: null }));
    const ok = await engineClient.setLoggerLevel("ROOT", nextLevel);
    if (!ok) {
      setLevel((prev) => ({
        ...prev,
        isApplying: false,
        error: "Failed to update log level",
      }));
      return;
    }
    setLevel((prev) => ({ ...prev, isApplying: false, appliedAt: Date.now() }));
    if (confirmTimerRef.current !== null) {
      window.clearTimeout(confirmTimerRef.current);
    }
    confirmTimerRef.current = window.setTimeout(() => {
      setLevel((prev) => ({ ...prev, appliedAt: null }));
    }, CONFIRMATION_MS);
    void refresh();
  };

  const handleRefresh = () => {
    void refresh();
  };

  const isInitialLoading = content === null && isLoading;
  const isEmpty = !isInitialLoading && entries.length === 0;
  const rangeLabel =
    totalFiltered === 0 ? "0 of 0" : `${effectiveStart + 1}–${effectiveEnd} of ${totalFiltered}`;

  return (
    <div className="flex flex-col gap-2 p-3">
      <div className="flex items-center gap-2 flex-wrap">
        <div className="relative flex-1 min-w-[160px]">
          <Search className="absolute left-2 top-1/2 h-3 w-3 -translate-y-1/2 text-muted-foreground pointer-events-none" />
          <Input
            placeholder="Filter by message, logger, thread, level..."
            value={filter}
            onChange={handleFilterChange}
            className="h-7 text-xs pl-7"
          />
        </div>

        <div className="flex items-center gap-1.5 rounded-md border border-border bg-card px-2 py-0.5 text-xs text-muted-foreground">
          <span className="text-[10px] font-semibold uppercase tracking-wide">Level</span>
          <Select value={level.value} onValueChange={handleLevelChange} disabled={level.isApplying}>
            <SelectTrigger className="h-6 w-24 text-xs border-0 px-1 shadow-none focus:ring-0">
              <SelectValue placeholder="Select" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={INHERIT_VALUE}>Inherit</SelectItem>
              {LOG_LEVELS.map((l) => (
                <SelectItem key={l} value={l}>
                  {l}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {level.isApplying ? <PrometheuxSpinner size={16} /> : null}
          {level.appliedAt !== null ? (
            <span className="inline-flex items-center gap-0.5 text-[10px] text-emerald-600 dark:text-emerald-400">
              <Check className="h-3 w-3" />
              applied
            </span>
          ) : null}
        </div>

        <label className="inline-flex items-center gap-1.5 rounded-md border border-border bg-card px-2 py-1 text-xs text-muted-foreground cursor-pointer select-none hover:text-foreground transition-colors">
          <input
            type="checkbox"
            checked={autoScroll}
            onChange={handleAutoScrollChange}
            className="h-3 w-3 accent-primary"
          />
          Auto-scroll
        </label>

        <Button
          variant="outline"
          size="sm"
          onClick={handleRefresh}
          disabled={isLoading}
          className="h-7 text-xs gap-1.5"
        >
          {isLoading ? <PrometheuxSpinner size={16} /> : <RefreshCw className="h-3 w-3" />}
          Refresh
        </Button>
      </div>

      <div className="flex items-center gap-2 flex-wrap text-[10px] text-muted-foreground">
        <div className="inline-flex items-center rounded-md border border-border bg-card overflow-hidden">
          <button
            type="button"
            onClick={handleOlder}
            disabled={!canGoOlder}
            className="inline-flex items-center gap-1 px-2 py-1 hover:bg-muted disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            <ChevronLeft className="h-3 w-3" />
            Older
          </button>
          <span className="px-2 py-1 border-l border-r border-border tabular-nums text-foreground font-medium">
            {rangeLabel}
          </span>
          <button
            type="button"
            onClick={handleNewer}
            disabled={!canGoNewer}
            className="inline-flex items-center gap-1 px-2 py-1 hover:bg-muted disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            Newer
            <ChevronRight className="h-3 w-3" />
          </button>
        </div>

        {!isTailing ? (
          <Button
            variant="secondary"
            size="sm"
            onClick={handleJumpToLive}
            className="h-6 text-[10px] gap-1 px-2"
          >
            <ArrowDownToLine className="h-3 w-3" />
            Jump to live
            {newerCount > 0 ? (
              <span className="ml-0.5 inline-flex h-4 min-w-[16px] items-center justify-center rounded-full bg-primary/15 px-1 text-[9px] font-semibold text-primary">
                {newerCount}
              </span>
            ) : null}
          </Button>
        ) : (
          <span className="inline-flex items-center gap-1 text-emerald-600 dark:text-emerald-400">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
            Live tail
          </span>
        )}

        <span className="ml-auto inline-flex items-center gap-1">
          <span>updated {formatSince(lastUpdatedAt)}</span>
        </span>
      </div>

      {level.error ? (
        <div className="rounded-md border border-red-200 bg-red-50 p-2 text-xs text-red-700 dark:border-red-900/40 dark:bg-red-900/20 dark:text-red-400">
          {level.error}
        </div>
      ) : null}

      {error ? (
        <div className="rounded-md border border-red-200 bg-red-50 p-2 text-xs text-red-700 dark:border-red-900/40 dark:bg-red-900/20 dark:text-red-400">
          {error}
        </div>
      ) : null}

      <div className="relative rounded-lg border border-border bg-muted/40 overflow-hidden shadow-sm">
        <div className="flex items-center gap-1.5 px-3 py-1.5 border-b border-border bg-muted/60 text-[10px] uppercase tracking-widest text-muted-foreground font-semibold">
          <Terminal className="h-3 w-3" />
          <span>Prometheux engine log</span>
        </div>
        <div className="grid grid-cols-[72px_64px_minmax(120px,180px)_minmax(80px,140px)_1fr] gap-2 px-2 py-1.5 border-b border-border/60 bg-muted/30 text-[9px] uppercase tracking-wider text-muted-foreground/80 font-semibold">
          <div>Time</div>
          <div>Level</div>
          <div>Logger</div>
          <div>Thread</div>
          <div>Message</div>
        </div>
        <div
          ref={scrollerRef}
          className="overflow-auto custom-scrollbar bg-card divide-y divide-border/30"
          style={{ maxHeight: 420, minHeight: 220 }}
        >
          {isInitialLoading ? (
            <div className="flex items-center justify-center p-6 text-muted-foreground">
              <PrometheuxSpinner size={16} className="mr-2" /> Loading log file...
            </div>
          ) : isEmpty ? (
            <div className="flex flex-col items-center justify-center gap-1 p-8 text-muted-foreground">
              <Terminal className="h-8 w-8 opacity-30" />
              <div className="text-xs font-medium">Log file is empty</div>
              <div className="text-[10px] text-muted-foreground/70">
                No log entries have been written yet
              </div>
            </div>
          ) : visibleEntries.length === 0 ? (
            <div className="flex flex-col items-center justify-center gap-1 p-8 text-muted-foreground">
              <Search className="h-6 w-6 opacity-30" />
              <div className="text-xs">No entries match "{filter}"</div>
            </div>
          ) : (
            visibleEntries.map((entry) => <LogRow key={entry.id} entry={entry} />)
          )}
        </div>
      </div>
    </div>
  );
};

export default EngineMonitorLogs;
