import { Check, Loader2, Users2, X } from "lucide-react";
import type React from "react";
import { useCallback, useState } from "react";
import { toast } from "sonner";
import type { InvitationInboxEntry } from "@/features/teams/types";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";

interface InvitationCardProps {
  invitation: InvitationInboxEntry;
  onAccept: (token: string) => Promise<unknown>;
  onDecline: (token: string) => Promise<unknown>;
}

// Team-invitation card, visually distinct from a regular TeamCard so the
// invitee immediately understands it isn't yet a team they belong to. Amber
// border matches the PendingShareCard treatment on the Projects page.
const InvitationCard: React.FC<InvitationCardProps> = ({ invitation, onAccept, onDecline }) => {
  const [pendingAction, setPendingAction] = useState<"accept" | "decline" | null>(null);

  const handleAccept = useCallback(async (): Promise<void> => {
    setPendingAction("accept");
    try {
      await onAccept(invitation.token);
      toast.success(`Joined ${invitation.team_name}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to accept invitation";
      toast.error(message);
    } finally {
      setPendingAction(null);
    }
  }, [invitation.team_name, invitation.token, onAccept]);

  const handleDecline = useCallback(async (): Promise<void> => {
    setPendingAction("decline");
    try {
      await onDecline(invitation.token);
      toast.success("Invitation declined");
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to decline invitation";
      toast.error(message);
    } finally {
      setPendingAction(null);
    }
  }, [invitation.token, onDecline]);

  const isAccepting = pendingAction === "accept";
  const isDeclining = pendingAction === "decline";
  const anyPending = pendingAction !== null;

  return (
    <div className="relative flex flex-col gap-3 rounded-xl border border-amber-500/40 bg-amber-500/[0.04] p-5 transition-all duration-150 dark:border-amber-500/30 dark:bg-amber-500/[0.06]">
      <div className="absolute right-3 top-3">
        <Badge variant="outline" className="border-amber-500/60 text-amber-700 dark:text-amber-400">
          Invitation
        </Badge>
      </div>

      <div className="flex items-start gap-3">
        <div className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-secondary">
          <Users2 className="h-4 w-4 text-foreground/60" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="truncate pr-20 text-[14px] font-semibold leading-tight text-foreground">
            {invitation.team_name}
          </div>
          <div className="mt-1 text-[12px] text-muted-foreground">@{invitation.team_slug}</div>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2 border-t border-border/60 pt-3 text-[12px] text-muted-foreground">
        <Badge variant="outline" className="capitalize">
          {invitation.role}
        </Badge>
        <span className="truncate">Invited by {invitation.invited_by}</span>
      </div>

      <div className="flex items-center gap-2">
        <Button
          type="button"
          size="sm"
          className="flex-1 gap-1.5"
          onClick={handleAccept}
          disabled={anyPending}
        >
          {isAccepting ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <Check className="h-3.5 w-3.5" />
          )}
          Accept
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="flex-1 gap-1.5 text-muted-foreground"
          onClick={handleDecline}
          disabled={anyPending}
        >
          {isDeclining ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <X className="h-3.5 w-3.5" />
          )}
          Decline
        </Button>
      </div>
    </div>
  );
};

export default InvitationCard;
