import { useRunLimitStore } from "../store/runLimitStore";
import { ContactToUpgradeDialog } from "./ContactToUpgradeDialog";

const TITLE_BY_KIND = {
  timeout: "This run hit the free-plan time limit",
  rows: "This run hit the free-plan size limit",
} as const;

/**
 * Shown when a freemium account's run is stopped by the per-run ceiling (a
 * wall-clock timeout or an output-row cap). The descriptive copy comes straight
 * from the backend message (single source of truth); this just adds the contact
 * CTA. Longer runs / larger results are part of a paid subscription, so the CTA
 * contacts Prometheux rather than Stripe. Reads the shared open flag so the run
 * handler can trigger it.
 */
export const RunLimitDialog = () => {
  const isOpen = useRunLimitStore((s) => s.isOpen);
  const info = useRunLimitStore((s) => s.info);
  const closeDialog = useRunLimitStore((s) => s.closeRunLimitDialog);

  const title = info ? TITLE_BY_KIND[info.kind] : TITLE_BY_KIND.timeout;
  const base = info?.message ?? "This run exceeded a limit on the free plan.";
  const description = `${base} Longer runs and larger results are part of a paid subscription — contact Prometheux to upgrade.`;

  const handleOpenChange = (open: boolean) => {
    if (!open) closeDialog();
  };

  return (
    <ContactToUpgradeDialog
      open={isOpen}
      onOpenChange={handleOpenChange}
      title={title}
      description={description}
      contactSubject="Upgrade request — run limits"
    />
  );
};
