/**
 * Descriptor registry for the Graph Explorer's traversal functions.
 *
 * Each entry mirrors an engine traversal function exposed by the backend's
 * `build-graph` endpoint via `pagination_mode=<key>`. The Explorer renders its
 * mode toggle and per-mode toolbar controls from this list, so adding a new
 * traversal function (e.g. SSSP/ASP/TC) is a single entry here plus a matching
 * entry in the backend `TRAVERSAL_REGISTRY`.
 */

export type GraphFunctionKey = "paths" | "bfs" | "asp" | "sssp" | "tc";

/** Default traversal depth when a function supports (and the user hasn't set) one. */
export const DEFAULT_MAX_DEPTH = 10;

/** Sentinel depth meaning "no cap": the engine treats a non-positive/absent
 * max_depth as unlimited, so we send 0 to request an unbounded traversal. */
export const UNLIMITED_MAX_DEPTH = 0;

export interface GraphFunctionDef {
  key: GraphFunctionKey;
  label: string;
  /** Show the source/target node inputs. */
  supportsSourceTarget: boolean;
  /** Show the "all paths" enumeration toggle. */
  supportsAllPaths: boolean;
  /** Show the "provenance (visited)" toggle. */
  supportsVisited: boolean;
  /** Show the "max depth" input (traversal depth cap). #TC ignores it. */
  supportsMaxDepth: boolean;
  /** A source node is mandatory before the function can run (e.g. SSSP). */
  requiresSource: boolean;
  /** Short one-line hint shown under the toolbar. */
  hint: string;
}

export const GRAPH_FUNCTIONS: GraphFunctionDef[] = [
  {
    key: "paths",
    label: "Paths",
    supportsSourceTarget: true,
    supportsAllPaths: true,
    supportsVisited: true,
    supportsMaxDepth: true,
    requiresSource: false,
    hint: "Enumerate paths between nodes. Leave source/target empty to explore from all nodes.",
  },
  {
    key: "bfs",
    label: "BFS",
    supportsSourceTarget: true,
    supportsAllPaths: false,
    supportsVisited: true,
    supportsMaxDepth: true,
    requiresSource: false,
    hint: "Breadth-first levels from the source. Leave empty to start from all nodes.",
  },
  {
    key: "asp",
    label: "All Shortest Paths",
    supportsSourceTarget: true,
    supportsAllPaths: false,
    supportsVisited: true,
    supportsMaxDepth: true,
    requiresSource: false,
    hint: "Shortest-path distances between nodes. Leave source/target empty for all pairs.",
  },
  {
    key: "sssp",
    label: "Single-Source Shortest Path",
    supportsSourceTarget: true,
    supportsAllPaths: false,
    supportsVisited: true,
    supportsMaxDepth: true,
    requiresSource: true,
    hint: "Shortest-path distances from a single source. A source node is required.",
  },
  {
    // key stays "tc" (the engine #TC token); "Reachability" is the friendlier
    // user-facing label for the transitive closure.
    key: "tc",
    label: "Reachability",
    supportsSourceTarget: false,
    supportsAllPaths: false,
    supportsVisited: false,
    supportsMaxDepth: false,
    requiresSource: false,
    hint: "All reachable (source, target) pairs (transitive closure). No options apply.",
  },
];

const GRAPH_FUNCTION_KEYS = new Set<string>(GRAPH_FUNCTIONS.map((fn) => fn.key));

export function isGraphFunctionKey(value: string): value is GraphFunctionKey {
  return GRAPH_FUNCTION_KEYS.has(value);
}

export function getGraphFunction(key: GraphFunctionKey): GraphFunctionDef {
  const found = GRAPH_FUNCTIONS.find((fn) => fn.key === key);
  if (!found) throw new Error(`Unknown graph function: ${key}`);
  return found;
}
