import type { CurrentDashboard } from "./hooks/useCurrentDashboard";

export interface FocusedConcept {
  name: string;
  code: string;
}

/**
 * Structured reference to a dynamic-app widget, packaged by the app editor's
 * "Ask AI" affordance (ADR D7: select-widget-as-reference — users never have
 * to name components). Folded into the next outgoing message and cleared.
 */
export interface FocusedWidgetRef {
  dashboardId: string;
  dashboardName: string;
  /** The widget's page's project — where its concepts resolve. */
  ontologyId: string;
  pageId: string;
  pageLabel: string;
  sectionId: string;
  widgetId: string;
  widgetType: string;
  /** The widget's schema bindings (outputId + tapped concept, inputId, groupId…). */
  bindings: Record<string, string>;
}

/**
 * Client-side revision counters sent with every agent turn. The backend
 * compares them to the last-seen set and refreshes its cached project
 * context when any of them moved.
 */
export interface ContextRevisions {
  ontologySchema: number;
  projects: number;
  dashboards: number;
  datasources: number;
  contextNotes: number;
}

export interface AgentTurnContext {
  focusedConcept: FocusedConcept | null;
  focusedWidget: FocusedWidgetRef | null;
  contextRevisions: ContextRevisions;
}

interface TurnContextSource {
  focusedConcept: FocusedConcept | null;
  focusedWidget: FocusedWidgetRef | null;
  ontologySchemaRevision: number;
  ontologiesRevision: number;
  dashboardsRevision: number;
  datasourcesRevision: number;
  contextNotesRevision: number;
}

/**
 * Snapshot of the structured per-turn context sent with every chat request.
 * Replaces the old first-turn-only folding of context into the message text —
 * the agent now receives what the user is looking at on every turn.
 */
export function gatherTurnContext(state: TurnContextSource): AgentTurnContext {
  return {
    focusedConcept: state.focusedConcept,
    focusedWidget: state.focusedWidget,
    contextRevisions: {
      ontologySchema: state.ontologySchemaRevision,
      projects: state.ontologiesRevision,
      dashboards: state.dashboardsRevision,
      datasources: state.datasourcesRevision,
      contextNotes: state.contextNotesRevision,
    },
  };
}

export type { CurrentDashboard };
