import { AlertCircle } from "lucide-react";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { ContextSection } from "./ContextSection";
import { RenderedFile } from "./RenderedFile";
import { SummaryHeader } from "./SummaryHeader";
import type { OntologyDocument } from "./types";

function safeFilename(name: string): string {
  const trimmed = (name || "project").trim() || "project";
  return `${trimmed.replace(/[^a-z0-9_-]+/gi, "_")}.vada`;
}

interface DocumentOverviewProps {
  document: OntologyDocument | undefined;
  isLoading: boolean;
  error: Error | null;
  isRefreshing: boolean;
  onRefresh: () => void;
  onNoteSaved: () => void;
}

export function DocumentOverview({
  document,
  isLoading,
  error,
  isRefreshing,
  onRefresh,
  onNoteSaved,
}: DocumentOverviewProps) {
  if (isLoading && !document) {
    return (
      <div className="flex h-full items-center justify-center">
        <PrometheuxSpinner size={36} label="Composing ontology document…" />
      </div>
    );
  }

  if (error && !document) {
    return (
      <div className="flex h-full items-center justify-center gap-2 text-sm text-destructive">
        <AlertCircle className="h-4 w-4" />
        Failed to load project document: {error.message}
      </div>
    );
  }

  if (!document) {
    return null;
  }

  return (
    <div className="flex h-full flex-col overflow-y-auto bg-background pb-16">
      <SummaryHeader
        project={document.project}
        summary={document.summary}
        summarySource={document.summary_source}
        isRefreshing={isRefreshing}
        onRefresh={onRefresh}
      />
      <ContextSection notes={document.project_notes} onNoteSaved={onNoteSaved} />
      <RenderedFile
        filename={safeFilename(document.project.name)}
        content={document.rendered_text}
      />
    </div>
  );
}
