import type React from "react";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { useEngineStatusStore } from "./engineStatusStore";

// /livez is registered at the FastAPI app root (above the /api/v1 router), so we
// strip the suffix from the runtime-substituted BASE_URL to reach it. Read the
// config lazily so we always use the org/user URL set after login, not the
// placeholder baked in at module load.
const API_SUFFIX = "/api/v1";

function getLivenessUrl(): string {
  const base = PROMETHEUX_CONFIG.BASE_URL;
  const root = base.endsWith(API_SUFFIX) ? base.slice(0, -API_SUFFIX.length) : base;
  return `${root}/livez`;
}

let inflightProbe: Promise<boolean> | null = null;

async function probeLiveness(): Promise<boolean> {
  try {
    const response = await fetch(getLivenessUrl(), { method: "GET", mode: "cors" });
    return response.ok;
  } catch {
    return false;
  }
}

// Collapses concurrent probes (e.g. rapid sidebar clicks) into a single request.
function probeOnce(): Promise<boolean> {
  if (inflightProbe) return inflightProbe;
  inflightProbe = probeLiveness().finally(() => {
    inflightProbe = null;
  });
  return inflightProbe;
}

// Resolves true when the engine is reachable. Caches a positive result; never
// caches a negative one (so a later attempt re-probes and recovers once the
// engine finishes provisioning). When the engine is down it sets the status to
// "unavailable", which raises the full-screen provisioning overlay (see
// EngineProvisioningOverlay / useEngineProvisioning) instead of a dismissible
// toast — the app is unusable until the engine is up, so we block rather than
// nudge.
export async function ensureEngineReady(): Promise<boolean> {
  const store = useEngineStatusStore.getState();
  if (store.status === "ready") return true;

  const live = await probeOnce();
  if (live) {
    store.setStatus("ready");
    return true;
  }

  store.setStatus("unavailable");
  return false;
}

// Handles plain sidebar navigation. Always navigates — the app-global
// EngineProvisioningOverlay (rendered in App.tsx via useEngineProvisioning)
// is what actually blocks interaction while the engine is provisioning, so
// gating navigation here only produced dead clicks. We still kick off a probe
// so a down engine flips status to "unavailable" and raises that overlay.
// Modifier-clicks (open in new tab) are left untouched.
export function guardSidebarNavClick(
  e: React.MouseEvent<HTMLAnchorElement>,
  action: () => void,
): void {
  if (e.ctrlKey || e.metaKey || e.shiftKey || e.altKey) return;
  e.preventDefault();
  action();
  void ensureEngineReady();
}
