import { useEffect, useRef } from "react";
import { DatabricksConfigService } from "@/features/compute/api/databricksService";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

// Shape returned by the 3P static server's /api/app-context endpoint.
// See server.js in build-bundle-3p.sh for the source of truth.
//
// IMPORTANT (v1.0.3): the autofill no longer plants a bearer token in the
// Databricks config. It writes the workspace URL and the App SP's clientId
// into an OAuth2 (Service Principal) config; the user supplies the
// matching client secret by generating one for the App SP in the workspace
// admin UI. The OAuth2 (M2M) flow lets the Databricks SDK auto-refresh
// tokens, eliminating the 1-hour expiry that broke long-lived data
// connections in v1.0.2's App Service Principal mode.
interface AppContextResponse {
  mode: "databricks_3p";
  workspaceUrl: string;
  clientId: string;
  appName?: string;
  workspaceId?: string;
  // SCIM /Me lookup of the app's service principal:
  //   principalId          numeric workspace-internal SP id  (e.g. "75023684171364")
  //   principalUserName    e.g. "app-5ctusr"
  //   principalDisplayName e.g. "prometheux"
  principalId?: string | null;
  principalUserName?: string | null;
  principalDisplayName?: string | null;
  user?: {
    email: string | null;
    userId: string | null;
    username: string | null;
  };
}

// Read-only display data persisted for the App Service Principal info panel.
// We keep this purely informational in v1.0.3 (workspace URL, principal name,
// signed-in user). Authentication itself is configured by the user via the
// OAuth2 panel.
export interface AppPrincipalContext {
  workspaceUrl: string;
  clientId: string;
  workspaceId?: string;
  appName?: string;
  principalId?: string | null;
  principalUserName?: string | null;
  principalDisplayName?: string | null;
  user?: {
    email: string | null;
    userId: string | null;
    username: string | null;
  };
}

// Marker so we don't auto-fill on every reload after the user has manually
// configured something else.
export const APP_CONTEXT_MARKER_KEY = "databricks_3p_autofilled_at";
// Read-only display blob for the App Service Principal panel.
export const APP_CONTEXT_DATA_KEY = "databricks_3p_app_context";

// Refresh the display blob every 10 minutes so workspace URL / principal name
// stay current if they ever change.
const DISPLAY_REFRESH_MS = 10 * 60 * 1000;

async function fetchAppContext(): Promise<AppContextResponse | null> {
  try {
    const resp = await fetch("/api/app-context", {
      credentials: "same-origin",
      headers: { Accept: "application/json" },
    });
    if (!resp.ok) {
      console.warn("[3p-autofill] /api/app-context returned", resp.status);
      return null;
    }
    return (await resp.json()) as AppContextResponse;
  } catch (err) {
    console.warn("[3p-autofill] /api/app-context fetch failed:", err);
    return null;
  }
}

function persistAppContextDisplay(ctx: AppContextResponse) {
  const display: AppPrincipalContext = {
    workspaceUrl: ctx.workspaceUrl,
    clientId: ctx.clientId,
    workspaceId: ctx.workspaceId,
    appName: ctx.appName,
    principalId: ctx.principalId,
    principalUserName: ctx.principalUserName,
    principalDisplayName: ctx.principalDisplayName,
    user: ctx.user,
  };
  try {
    localStorage.setItem(APP_CONTEXT_DATA_KEY, JSON.stringify(display));
  } catch {
    // Ignore storage errors
  }
}

function applyOAuth2Autofill(ctx: AppContextResponse) {
  const current = DatabricksConfigService.getConfig();
  DatabricksConfigService.saveConfig({
    ...current,
    workspaceUrl: ctx.workspaceUrl,
    clientId: ctx.clientId,
    authMode: "oauth2",
    // Clear any stale bearer left over from the legacy App Service Principal
    // mode (v1.0.0–v1.0.2). The user enters the secret in the OAuth2 panel.
    token: "",
    isAppPrincipalToken: false,
    isOAuthToken: false,
  });
  DatabricksConfigService.clearConnectionStatus();
  persistAppContextDisplay(ctx);
  try {
    localStorage.setItem(APP_CONTEXT_MARKER_KEY, String(Date.now()));
  } catch {
    // Ignore storage errors
  }
  window.dispatchEvent(new CustomEvent("databricksConfigChanged"));
}

function migrateLegacyAppPrincipalConfig(ctx: AppContextResponse) {
  // Existing user on v1.0.0–v1.0.2 had:
  //   authMode: "token", isAppPrincipalToken: true, token: <OBO bearer>
  // The bearer is per-user, expires after ~1h with no auto-refresh, and is
  // what was breaking persistent data connections. We migrate them in place
  // to OAuth2, preserving their workspace URL and surfacing the App SP's
  // clientId; they then paste a fresh secret.
  const current = DatabricksConfigService.getConfig();
  DatabricksConfigService.saveConfig({
    ...current,
    workspaceUrl: current.workspaceUrl || ctx.workspaceUrl,
    clientId: ctx.clientId,
    authMode: "oauth2",
    token: "",
    isAppPrincipalToken: false,
    isOAuthToken: false,
  });
  DatabricksConfigService.clearConnectionStatus();
  persistAppContextDisplay(ctx);
  try {
    localStorage.setItem(APP_CONTEXT_MARKER_KEY, String(Date.now()));
  } catch {
    // Ignore storage errors
  }
  window.dispatchEvent(new CustomEvent("databricksConfigChanged"));
}

/**
 * Hook that, when running inside the Databricks 3P app, fetches the workspace
 * URL, app service principal client ID and identity headers from
 * /api/app-context and writes them into the Databricks config so the user
 * starts in OAuth2 (Service Principal) mode with workspace URL + clientId
 * already populated. The user only needs to paste a client secret generated
 * for that App SP in the workspace admin UI.
 *
 * Architecture rationale (v1.0.3 — supersedes v1.0.2):
 *   - the App SP's auto-injected client_secret cannot be surfaced to the
 *     browser (it's server-side only in DATABRICKS_CLIENT_SECRET), so the
 *     prior "App Service Principal" bearer auto-fill is deprecated;
 *   - the per-user OBO token returned by the Apps proxy
 *     (X-Forwarded-Access-Token, used by v1.0.2's /api/user-token) expires
 *     in ~1h with no refresh path inside jarvispy in `authMode: "token"`,
 *     which silently broke long-lived data connections;
 *   - OAuth2 (Service Principal) mode uses M2M client_credentials and the
 *     Databricks SDK auto-refreshes tokens, so there's no expiry to manage.
 *
 * It only writes credentials on first load (or when the user is migrating
 * from the legacy App Principal config). If the user has chosen PAT,
 * Databricks Login, or already has a working OAuth2 config, the periodic
 * refresh just updates the read-only display blob and never overwrites
 * their config.
 *
 * In all other modes (Snowflake, embedded Databricks, plain SaaS), this hook
 * is a no-op.
 */
export function useDatabricksAppContext(): void {
  const refreshTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) {
      return;
    }

    let cancelled = false;

    const hydrate = async () => {
      const ctx = await fetchAppContext();
      if (cancelled || !ctx) return;

      const current = DatabricksConfigService.getConfig();
      const isFirstAutofill = !localStorage.getItem(APP_CONTEXT_MARKER_KEY);
      const isLegacyAppPrincipalUser = current.isAppPrincipalToken === true;

      if (isLegacyAppPrincipalUser) {
        migrateLegacyAppPrincipalConfig(ctx);
      } else if (isFirstAutofill) {
        applyOAuth2Autofill(ctx);
      } else {
        // User already has a config they chose themselves — PAT, OAuth2 with
        // their own SP, Databricks Login, etc. Refresh display blob only.
        persistAppContextDisplay(ctx);
      }

      if (refreshTimerRef.current) {
        clearTimeout(refreshTimerRef.current);
      }
      refreshTimerRef.current = setTimeout(hydrate, DISPLAY_REFRESH_MS);
    };

    hydrate();

    return () => {
      cancelled = true;
      if (refreshTimerRef.current) {
        clearTimeout(refreshTimerRef.current);
        refreshTimerRef.current = null;
      }
    };
  }, []);
}
