import type React from "react";
import type { RestrictionLevel } from "../types";
import {
  accessLevelBadgeClass,
  accessLevelLabel,
  type EffectiveAccess,
} from "../utils/conceptAccess.utils";
import RosterRow from "./RosterRow";

// "Inherit" is not a dropdown option — clearing an explicit rule is done via the
// Reset button, and the inherited level is surfaced in the trigger placeholder.
const ROW_LEVEL_OPTIONS: { value: RestrictionLevel; label: string }[] = [
  { value: "read_write", label: "Editor" },
  { value: "read_only", label: "Viewer" },
  { value: "hidden", label: "Hidden" },
];

interface AccessRosterRowProps {
  label: string;
  hint?: string;
  effectiveLevel: EffectiveAccess;
  explicitLevel?: RestrictionLevel;
  editable: boolean;
  isBusy: boolean;
  onSetLevel: (level: RestrictionLevel) => void;
  onClearLevel: () => void;
}

// A single concept-access row: the subject's effective level as a badge plus an
// optional dropdown + Reset to change their concept-level permission.
const AccessRosterRow: React.FC<AccessRosterRowProps> = ({
  label,
  hint,
  effectiveLevel,
  explicitLevel,
  editable,
  isBusy,
  onSetLevel,
  onClearLevel,
}) => {
  const handleChange = (value: string): void => {
    if (value === "read_write" || value === "read_only" || value === "hidden") {
      onSetLevel(value);
    }
  };

  // When there's no explicit rule the row inherits its level; surface the
  // concrete inherited value in the trigger so the owner sees what "inherit"
  // resolves to for this team/ontology (e.g. "Editor (inherited)").
  const inheritedPlaceholder = `${accessLevelLabel(effectiveLevel)} (inherited)`;

  return (
    <RosterRow
      label={label}
      hint={hint}
      badgeText={accessLevelLabel(effectiveLevel)}
      badgeClass={accessLevelBadgeClass(effectiveLevel)}
      options={ROW_LEVEL_OPTIONS}
      value={explicitLevel}
      placeholder={inheritedPlaceholder}
      editable={editable}
      isBusy={isBusy}
      onChange={handleChange}
      onReset={onClearLevel}
      canReset={Boolean(explicitLevel)}
    />
  );
};

export default AccessRosterRow;
