import { patchPage } from "../../../store/appEditorMutations";
import { useAppEditorStore } from "../../../store/appEditorStore";
import { TextField } from "./fields";

interface PageInspectorProps {
  pageId: string;
}

/** One page = one lineage (ADR D9): label + the project the page binds to. */
export function PageInspector({ pageId }: PageInspectorProps) {
  const draft = useAppEditorStore((state) => state.draft);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  const page = draft?.pages.find((candidate) => candidate.id === pageId);
  if (!page) return <StaleSelection />;

  return (
    <div className="flex flex-col gap-2.5">
      <TextField
        label="Page label"
        value={page.label}
        onChange={(value) =>
          updateDraft((current) => patchPage(current, pageId, { label: value ?? "" }))
        }
      />
      <TextField
        label="Ontology id"
        value={page.project?.id}
        onChange={(value) =>
          updateDraft((current) => patchPage(current, pageId, { project: { id: value ?? "" } }))
        }
      />
      <p className="text-[10px] text-muted-foreground leading-relaxed">
        Every concept referenced on this page must resolve in this project — validated on save.
      </p>
    </div>
  );
}

export function StaleSelection() {
  return <p className="text-[11px] text-muted-foreground">This element no longer exists.</p>;
}
