// Store to manage schema suggestions for the CodeMirror editor
import { create } from "zustand";
import type { ConceptData } from "@/features/concepts/api";
import { groupConceptsByType } from "@/features/concepts/utils/conceptUtils";

interface BoundPredicateSig {
  label: string;
  apply: string;
  info: string;
}

interface SchemaState {
  schemaSuggestions: {
    label: string;
    type: string;
    info: string;
    apply: string;
    columns: string[];
  }[];
  boundPredicates: BoundPredicateSig[];
  setSchemaFromConcepts: (concepts: ConceptData[]) => void;
  setBoundPredicates: (sigs: BoundPredicateSig[]) => void;
  clearSchemaSuggestions: () => void;
}

export const useSchemaStore = create<SchemaState>((set, _get) => ({
  schemaSuggestions: [],
  boundPredicates: [],

  setBoundPredicates: (sigs) => {
    set({ boundPredicates: sigs });
  },

  setSchemaFromConcepts: (concepts) => {
    if (!concepts || !Array.isArray(concepts)) {
      return;
    }

    try {
      // Use the same logic as concept library to group concepts
      const { definedConcepts } = groupConceptsByType(concepts);

      const newSuggestions: {
        label: string;
        type: string;
        info: string;
        apply: string;
        columns: string[];
      }[] = [];

      // Only process defined concepts (same as "defined" tab in concept library)
      definedConcepts.forEach((concept) => {
        if (concept.predicate_name) {
          let columns: string[] = [];

          // Extract field names from the fields property
          if (concept.fields && typeof concept.fields === "object") {
            columns = Object.keys(concept.fields);
          } else if (concept.column_names && Array.isArray(concept.column_names)) {
            // Fallback to column_names if available
            columns = concept.column_names;
          } else if (concept.arity && typeof concept.arity === "number" && concept.arity > 0) {
            // Generate generic column names like X1, X2, X3...
            columns = Array.from({ length: concept.arity }, (_, i) => `X${i + 1}`);
          } else {
            // Default to single generic column if no field info is available
            columns = ["X"];
          }

          const columnDisplay = columns.join(", ");
          const apply = `${concept.predicate_name}(${columns.join(",")})`;

          // Create info string with field types if available
          let info: string;
          if (concept.fields && typeof concept.fields === "object") {
            const fieldsWithTypes = Object.entries(concept.fields)
              .map(([fieldName, fieldType]) => `${fieldName}:${fieldType}`)
              .join(", ");
            info = concept.description
              ? `${concept.predicate_name}(${fieldsWithTypes}) - ${concept.description}`
              : `${concept.predicate_name}(${fieldsWithTypes})`;
          } else {
            info = concept.description
              ? `${concept.predicate_name}(${columnDisplay}) - ${concept.description}`
              : `${concept.predicate_name}(${columnDisplay})`;
          }

          newSuggestions.push({
            label: concept.predicate_name,
            type: "concept",
            info: info,
            apply: apply,
            columns: columns,
          });
        }
      });

      set({ schemaSuggestions: newSuggestions });
    } catch (_error) {
      // Error processing concepts for schema suggestions
    }
  },

  clearSchemaSuggestions: () => {
    set({ schemaSuggestions: [], boundPredicates: [] });
  },
}));
