import { X } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/components/ui/tabs";
import { truncateText } from "@/shared/utils/textUtils";
import type { ShareType } from "../types";
import ManageSharesPanel from "./ManageSharesPanel";
import ShareModeSelector from "./ShareModeSelector";
import ShareOntologyForm from "./ShareOntologyForm";

interface ShareOntologyDialogProps {
  isOpen: boolean;
  onClose: () => void;
  ontologyId: string;
  ontologyName: string;
}

const DIALOG_TABS = {
  INVITE: "invite",
  MANAGE: "manage",
} as const;

const ShareOntologyDialog: React.FC<ShareOntologyDialogProps> = ({
  isOpen,
  onClose,
  ontologyId,
  ontologyName,
}) => {
  // The People/Team selector is shared across both tabs: it scopes both who you
  // invite AND which active shares are listed, so there's a single source of
  // truth rather than a per-tab toggle.
  const [mode, setMode] = useState<ShareType>("user");

  const handleOpenChange = (open: boolean): void => {
    if (!open) onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent className="p-0 sm:max-w-[520px] overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Share ontology</DialogTitle>

        {/* Yellow header bar — matches Edit/Copy dialogs in this domain */}
        <div
          style={{ background: "#FFDF4B", padding: "12px 20px" }}
          className="flex items-center justify-between border-b border-border"
        >
          <div className="min-w-0">
            <h2 className="text-base font-bold text-[#212020]">Share ontology</h2>
            <p className="text-xs text-[#212020]/80 truncate">{truncateText(ontologyName, 50)}</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="flex items-center justify-center h-6 w-6 rounded-full hover:bg-black/10 transition-colors"
            aria-label="Close"
          >
            <X className="h-4 w-4 text-[#212020]" />
          </button>
        </div>

        {/* Body */}
        <div className="bg-card p-6">
          <ShareModeSelector value={mode} onChange={setMode} />
          <Tabs defaultValue={DIALOG_TABS.INVITE} className="mt-4 w-full">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value={DIALOG_TABS.INVITE}>Invite</TabsTrigger>
              <TabsTrigger value={DIALOG_TABS.MANAGE}>Permissions</TabsTrigger>
            </TabsList>
            <TabsContent value={DIALOG_TABS.INVITE} className="mt-5" forceMount>
              <ShareOntologyForm
                ontologyId={ontologyId}
                ontologyName={ontologyName}
                mode={mode}
                onSubmitted={onClose}
              />
            </TabsContent>
            <TabsContent value={DIALOG_TABS.MANAGE} className="mt-5">
              <ManageSharesPanel ontologyId={ontologyId} mode={mode} />
            </TabsContent>
          </Tabs>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default ShareOntologyDialog;
