import { TableHead, TableHeader, TableRow } from "@/shared/components/ui/table";
import { ColumnFilterPopover } from "./ColumnFilterPopover";
import type { ColumnFilterValue, FilterOperator, OrderByItem } from "./tableOutput.types";
import { getColumnSortDirection } from "./tableOutput.utils";

interface TableOutputHeaderProps {
  columns: string[];
  orderBy?: OrderByItem[];
  columnFilters?: Record<number, ColumnFilterValue>;
  onApplyFilter: (columnIndex: number, value: string, operator: FilterOperator) => void;
  onClearFilter: (columnIndex: number) => void;
  onSort: (columnIndex: number, direction: "asc" | "desc" | null) => void;
}

export function TableOutputHeader({
  columns,
  orderBy,
  columnFilters,
  onApplyFilter,
  onClearFilter,
  onSort,
}: TableOutputHeaderProps) {
  return (
    <TableHeader>
      <TableRow>
        {columns.map((col, i) => (
          <TableHead key={i} className="whitespace-nowrap text-xs">
            <div className="inline-flex items-center">
              <span>{col}</span>
              <ColumnFilterPopover
                columnIndex={i}
                columnName={col}
                currentFilter={columnFilters?.[i]}
                currentSortDirection={getColumnSortDirection(orderBy, i)}
                onApplyFilter={onApplyFilter}
                onClearFilter={onClearFilter}
                onSort={onSort}
              />
            </div>
          </TableHead>
        ))}
      </TableRow>
    </TableHeader>
  );
}
