import { useMemo } from "react";
import { useContextTabRenderer } from "@/features/context-layer/hooks/useContextTabRenderer";
import { useAppTabRenderer } from "@/features/dashboards/hooks/useAppTabRenderer";
import { useLineageTabRenderer } from "@/features/ontology-schema/hooks/useLineageTabRenderer";
import type { TabComponent, TabRendererProps } from "./tabTypes";

export * from "./tabTypes";

export const useTabRenderer = (props: TabRendererProps): TabComponent | null => {
  const lineageTabContent = useLineageTabRenderer(props);
  const appTabContent = useAppTabRenderer(props);
  const contextTabContent = useContextTabRenderer(props);

  return useMemo(() => {
    switch (props.activeTab) {
      case "ontology":
      case "lineage":
      case "document":
        return lineageTabContent;
      case "context":
        return contextTabContent;
      case "app":
        return appTabContent;
      default:
        return null;
    }
  }, [props.activeTab, lineageTabContent, appTabContent, contextTabContent]);
};
