import { ChevronDown, ChevronUp, Info, Plus, Server, Zap } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/shared/components/ui/card";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import {
  type AvailabilityResult,
  getCategoryIcon,
  groupMachinesByCategory,
  MACHINES_PER_CATEGORY,
  type Machine,
  type UserMachine,
} from "../utils";
import { MachineCard } from "./MachineCard";
import { MachineSearchFilters } from "./MachineSearchFilters";

export interface PoolsTabContentProps {
  machines: Machine[];
  userMachines: UserMachine[];
  disabledUserMachines: UserMachine[];
  loadingMachines: boolean;
  machinesError: string | null;
  availabilityResults: Record<string, AvailabilityResult>;
  checkingAvailability: Record<string, boolean>;
  isRequesting: boolean;
  fetchAllMachines: () => Promise<void>;
  handleMachineRequest: (machineId: string, machineName: string) => Promise<any>;
  onToggleActive: (
    userMachineId: string,
    machineId: string,
    currentIsActive: boolean,
    autoterminationMinutes?: number,
  ) => Promise<void>;
  onRemoveMachine: (userMachineId: string, machineName: string) => Promise<void>;
  onCheckStatus: (machineId: string, userMachineId: string) => void;
  onFetchUsage: (userMachineId: string, machineName: string) => void;
  isPaidComputeEligible?: boolean;
  onPaidComputeRequired?: () => void;
}

export const PoolsTabContent: React.FC<PoolsTabContentProps> = ({
  machines,
  userMachines,
  disabledUserMachines,
  loadingMachines,
  machinesError,
  availabilityResults,
  checkingAvailability,
  isRequesting,
  fetchAllMachines,
  handleMachineRequest,
  onToggleActive,
  onRemoveMachine,
  onCheckStatus,
  onFetchUsage,
  isPaidComputeEligible,
  onPaidComputeRequired,
}) => {
  const [expandedCategories, setExpandedCategories] = useState<Record<string, boolean>>({});
  const [ondemandCategories, setOndemandCategories] = useState<Record<string, boolean>>({});
  const [searchFilters, setSearchFilters] = useState({
    minCores: "",
    maxCores: "",
    minMemory: "",
    maxMemory: "",
  });

  const filterMachines = (machinesToFilter: Machine[]) => {
    return machinesToFilter.filter((machine) => {
      if (searchFilters.minCores && machine.cores < parseInt(searchFilters.minCores, 10))
        return false;
      if (searchFilters.maxCores && machine.cores > parseInt(searchFilters.maxCores, 10))
        return false;
      if (searchFilters.minMemory && machine.memory_gb < parseInt(searchFilters.minMemory, 10))
        return false;
      if (searchFilters.maxMemory && machine.memory_gb > parseInt(searchFilters.maxMemory, 10))
        return false;
      return true;
    });
  };

  const clearFilters = () => {
    setSearchFilters({ minCores: "", maxCores: "", minMemory: "", maxMemory: "" });
  };

  const hasActiveFilters = () =>
    searchFilters.minCores !== "" ||
    searchFilters.maxCores !== "" ||
    searchFilters.minMemory !== "" ||
    searchFilters.maxMemory !== "";

  const getAvailableMachines = () => {
    const enabledMachineIds = userMachines.map((um) => um.machine_id);
    const disabledMachineIds = disabledUserMachines.map((um) => um.machine_id);

    const availableWithHistory = disabledUserMachines;
    const catalogMachinesNotUsed = machines.filter(
      (machine) =>
        !enabledMachineIds.includes(machine.id) && !disabledMachineIds.includes(machine.id),
    );

    const combined = [
      ...availableWithHistory,
      ...catalogMachinesNotUsed.map(
        (m) =>
          ({
            machines: m,
            machine_id: m.id,
            status: "Available" as const,
          }) as unknown as UserMachine,
      ),
    ];

    const machinesOnly = combined
      .map((item) => item.machines || (item as any))
      .filter(Boolean) as Machine[];

    const filtered = filterMachines(machinesOnly);

    return combined.filter((item) => {
      const machine = item.machines || (item as any);
      return filtered.some((m) => m.id === machine.id);
    });
  };

  const sortFreeFirst = (list: UserMachine[]) =>
    [...list].sort((a, b) => {
      const costA = a.machines?.cost_per_machine ?? Infinity;
      const costB = b.machines?.cost_per_machine ?? Infinity;
      return costA - costB;
    });

  // Treat real-time availability as the source of truth when present; fall back
  // to `is_active` when no recent status check has been recorded.
  const isUserMachineRunning = (um: UserMachine): boolean => {
    if (!um.machines) return false;
    const result = availabilityResults[um.machines.id];
    if (result?.machine_status) return result.machine_status !== "stopped";
    return um.is_active === true;
  };

  const partitionUserMachines = (running: boolean) => {
    const list = userMachines.filter(
      (um) => Boolean(um.machines) && isUserMachineRunning(um) === running,
    );
    const filteredIds = new Set(filterMachines(list.map((um) => um.machines!)).map((m) => m.id));
    return sortFreeFirst(list.filter((um) => filteredIds.has(um.machines!.id)));
  };

  const getActiveUserMachines = () => partitionUserMachines(true);
  const getInactiveUserMachines = () => partitionUserMachines(false);

  const toggleCategoryExpansion = (categoryKey: string) => {
    setExpandedCategories((prev) => ({ ...prev, [categoryKey]: !prev[categoryKey] }));
  };

  const isCategoryExpanded = (categoryKey: string) => expandedCategories[categoryKey] || false;

  const getDisplayedMachines = (machinelist: Machine[], categoryKey: string) =>
    isCategoryExpanded(categoryKey) ? machinelist : machinelist.slice(0, MACHINES_PER_CATEGORY);

  const shouldShowLoadMore = (machinelist: Machine[]) => machinelist.length > MACHINES_PER_CATEGORY;

  const machineCardProps = (userMachine: UserMachine) => {
    const machine = userMachine.machines!;
    return {
      availabilityResult: availabilityResults[machine.id],
      isCheckingAvailability: checkingAvailability[machine.id],
      isRequesting,
      onCheckStatus,
      onFetchUsage,
      onToggleActive,
      onRemoveMachine,
      isPaidComputeEligible,
      onPaidComputeRequired,
    };
  };

  return (
    <div className="space-y-6">
      <MachineSearchFilters
        searchFilters={searchFilters}
        onSearchFiltersChange={setSearchFilters}
        onClearFilters={clearFilters}
        hasActiveFilters={hasActiveFilters()}
      />

      {loadingMachines ? (
        <div className="flex items-center justify-center py-8">
          <PrometheuxSpinner size={36} />
          <span className="ml-2 text-muted-foreground">Loading machines...</span>
        </div>
      ) : machinesError ? (
        <div className="text-center py-8">
          <p className="text-red-600 dark:text-red-400 mb-4">{machinesError}</p>
          <Button onClick={() => fetchAllMachines()} variant="outline">
            <Plus className="w-4 h-4 mr-2" />
            Retry
          </Button>
        </div>
      ) : (
        <div className="space-y-8">
          {/* Active Machines */}
          {getActiveUserMachines().length > 0 && (
            <div>
              <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Zap className="w-5 h-5 text-green-600 dark:text-green-400" />
                Active Machines
              </h3>
              <div className="grid gap-4 @2xl:grid-cols-2 @5xl:grid-cols-3">
                {getActiveUserMachines().map((userMachine) => {
                  const machine = userMachine.machines;
                  if (!machine) return null;
                  return (
                    <MachineCard
                      key={`user-${machine.id}`}
                      machine={machine}
                      userMachine={userMachine}
                      {...machineCardProps(userMachine)}
                    />
                  );
                })}
              </div>
            </div>
          )}

          {/* Stopped Machines */}
          {getInactiveUserMachines().length > 0 && (
            <div>
              <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Server className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                Stopped Machines
              </h3>
              <div className="grid gap-4 @2xl:grid-cols-2 @5xl:grid-cols-3">
                {getInactiveUserMachines().map((userMachine) => {
                  const machine = userMachine.machines;
                  if (!machine) return null;
                  return (
                    <MachineCard
                      key={`inactive-${machine.id}`}
                      machine={machine}
                      userMachine={userMachine}
                      {...machineCardProps(userMachine)}
                    />
                  );
                })}
              </div>
            </div>
          )}

          {/* Available Machines by Category */}
          {getAvailableMachines().length > 0 && (
            <div>
              <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Plus className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                Available Machines
              </h3>
              {(() => {
                const availableItems = getAvailableMachines();
                const extractedMachines = availableItems
                  .map((item) => {
                    if ("machines" in item && item.machines) return item.machines;
                    return item as any as Machine;
                  })
                  .filter(Boolean) as Machine[];

                return groupMachinesByCategory(extractedMachines).map(
                  ({ category, displayName, machines: reservedMachines, ondemandMachines }) => {
                    const hasOndemand = ondemandMachines.length > 0;
                    const showOndemand = hasOndemand && (ondemandCategories[category] ?? false);
                    const catMachines = showOndemand ? ondemandMachines : reservedMachines;
                    if (catMachines.length === 0) return null;

                    const categoryKey = `available-${category}${showOndemand ? "-ondemand" : ""}`;
                    const displayedMachines = getDisplayedMachines(catMachines, categoryKey);
                    const isExpanded = isCategoryExpanded(categoryKey);
                    const showLoadMore = shouldShowLoadMore(catMachines);

                    return (
                      <div key={`available-${category}`} className="mb-6">
                        <div className="flex flex-col gap-1.5 mb-3">
                          <div className="flex items-center gap-2">
                            {getCategoryIcon(category)}
                            <h4 className="text-md font-medium text-muted-foreground">
                              {displayName}
                            </h4>
                            <Badge variant="outline" className="text-xs">
                              {catMachines.length}
                            </Badge>
                          </div>
                          {hasOndemand && (
                            <div className="flex items-center gap-1.5">
                              <div className="flex items-center rounded-md border bg-muted p-0.5">
                                <button
                                  type="button"
                                  onClick={() =>
                                    setOndemandCategories((prev) => ({
                                      ...prev,
                                      [category]: false,
                                    }))
                                  }
                                  className={`rounded px-2.5 py-1 text-xs font-medium transition-colors ${
                                    !showOndemand
                                      ? "bg-background text-foreground shadow-sm"
                                      : "text-muted-foreground hover:text-foreground"
                                  }`}
                                >
                                  Standard
                                </button>
                                <button
                                  type="button"
                                  onClick={() =>
                                    setOndemandCategories((prev) => ({ ...prev, [category]: true }))
                                  }
                                  className={`rounded px-2.5 py-1 text-xs font-medium transition-colors ${
                                    showOndemand
                                      ? "bg-background text-foreground shadow-sm"
                                      : "text-muted-foreground hover:text-foreground"
                                  }`}
                                >
                                  Dedicated
                                </button>
                              </div>
                              <TooltipProvider>
                                <Tooltip>
                                  <TooltipTrigger asChild>
                                    <Info className="w-3.5 h-3.5 text-muted-foreground cursor-help" />
                                  </TooltipTrigger>
                                  <TooltipContent side="right" className="max-w-xs">
                                    <p className="text-xs">
                                      Standard machines share resources across users for cost
                                      efficiency — full data isolation is ensured. Dedicated
                                      machines are exclusively yours for guaranteed performance.
                                    </p>
                                  </TooltipContent>
                                </Tooltip>
                              </TooltipProvider>
                            </div>
                          )}
                        </div>
                        <div className="grid gap-4 @2xl:grid-cols-2 @5xl:grid-cols-3">
                          {displayedMachines.map((machine) => {
                            const disabledRecord = availableItems.find(
                              (item) => "machines" in item && item.machines?.id === machine.id,
                            ) as UserMachine | undefined;

                            return (
                              <MachineCard
                                key={`available-${machine.id}`}
                                machine={machine}
                                userMachine={disabledRecord}
                                isAvailable={true}
                                isRequesting={isRequesting}
                                onRequest={() => handleMachineRequest(machine.id, machine.name)}
                              />
                            );
                          })}
                        </div>
                        {showLoadMore && (
                          <div className="flex justify-center mt-4">
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => toggleCategoryExpansion(categoryKey)}
                              className="flex items-center gap-2"
                            >
                              {isExpanded ? (
                                <>
                                  <ChevronUp className="w-4 h-4" /> Show Less
                                </>
                              ) : (
                                <>
                                  <ChevronDown className="w-4 h-4" /> Show{" "}
                                  {catMachines.length - MACHINES_PER_CATEGORY} More
                                </>
                              )}
                            </Button>
                          </div>
                        )}
                      </div>
                    );
                  },
                );
              })()}
            </div>
          )}

          {getAvailableMachines().length === 0 &&
            getActiveUserMachines().length === 0 &&
            getInactiveUserMachines().length === 0 && (
              <Card className="border-dashed">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium text-muted-foreground">
                    No Machines Available
                  </CardTitle>
                  <Server className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <p className="text-sm text-muted-foreground">
                    No compute machines are currently available
                  </p>
                </CardContent>
              </Card>
            )}
        </div>
      )}
    </div>
  );
};
