import { KeyRound, Loader2, ShieldCheck } from "lucide-react";
import { useState } from "react";
import { submitDatabricksCredentials } from "@/features/compute/api/databricksCredentials";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import { SecretInput } from "@/shared/components/ui/secret-input";
import { cn } from "@/shared/lib/utils";
import {
  buildCredentialSubmission,
  type CredentialAuthMode,
  type CredentialDraft,
  draftValue,
  EMPTY_CREDENTIAL_DRAFT,
  isDraftComplete,
  requestedFields,
  withDraftValue,
} from "../credentialRequest.utils";
import type { CredentialField, CredentialRequestData, CredentialRequestState } from "../store";

interface CredentialRequestCardProps {
  data: CredentialRequestData;
  state: CredentialRequestState;
  onSubmitted: () => void;
  onDismiss: () => void;
  onResolve: (state: CredentialRequestState) => void;
}

const LABELS: Record<CredentialField, string> = {
  host: "Workspace URL",
  auth_mode: "Credential",
  token: "Personal access token",
  client_id: "Client ID",
  client_secret: "Client secret",
};

const PLACEHOLDERS: Record<CredentialField, string> = {
  host: "https://dbc-xxxxxxxx.cloud.databricks.com",
  auth_mode: "",
  token: "dapi…",
  client_id: "The service principal's application ID",
  client_secret: "Workspace → service principal → secrets",
};

const MODE_OPTIONS: { value: CredentialAuthMode; label: string }[] = [
  { value: "token", label: "Personal access token" },
  { value: "oauth2", label: "Service principal" },
];

/**
 * The form the assistant opens when it needs a Databricks credential.
 *
 * The fields are masked, and what is typed here is sent to the backend on its
 * own request — so unlike an answer typed into the chat, it never becomes part
 * of the conversation, never reaches the model, and is not kept in the chat
 * history. Nothing is retained here once it has been sent.
 */
export function CredentialRequestCard({
  data,
  state,
  onSubmitted,
  onDismiss,
  onResolve,
}: CredentialRequestCardProps) {
  const [mode, setMode] = useState<CredentialAuthMode>(data.auth_mode || "");
  const [draft, setDraft] = useState<CredentialDraft>(EMPTY_CREDENTIAL_DRAFT);
  const [isSending, setIsSending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isPending = state === "pending";
  const fields = requestedFields(data, mode);
  const canSubmit = isPending && !isSending && isDraftComplete(fields, draft);
  const wasSubmitted = state === "submitted";
  const resolvedNote = wasSubmitted ? "Credentials sent securely" : "Not provided";
  const reopenLabel = wasSubmitted ? "Change credential" : "Enter them now";

  const handleModeChange = (next: CredentialAuthMode) => () => {
    setMode(next);
    setDraft((current) => ({ ...current, token: "", clientId: "", clientSecret: "" }));
  };

  const handleFieldChange = (field: CredentialField) => (value: string) => {
    setError(null);
    setDraft((current) => withDraftValue(current, field, value));
  };

  const handleSubmit = async () => {
    if (!canSubmit) return;
    setIsSending(true);
    setError(null);
    try {
      await submitDatabricksCredentials(buildCredentialSubmission(mode, draft));
      // Forget the values as soon as they are safely stored: the card stays on
      // screen and has no reason to keep holding them.
      setDraft(EMPTY_CREDENTIAL_DRAFT);
      onResolve("submitted");
      onSubmitted();
    } catch (e) {
      setError(e instanceof Error ? e.message : "The credentials could not be saved.");
    } finally {
      setIsSending(false);
    }
  };

  const handleDismiss = () => {
    setDraft(EMPTY_CREDENTIAL_DRAFT);
    onResolve("dismissed");
    onDismiss();
  };

  /**
   * A sent credential can be the wrong one — a service principal's secret typed
   * into the token field authenticates as nothing — and the card is where the
   * user looks to correct it. Reopening starts from an unanswered form rather
   * than the previous choice, since that choice is the likely mistake.
   */
  const handleReopen = () => {
    setMode(data.auth_mode || "");
    setDraft(EMPTY_CREDENTIAL_DRAFT);
    setError(null);
    onResolve("pending");
  };

  const renderField = (field: CredentialField) => {
    const value = draftValue(field, draft);
    return (
      <div key={field} className="space-y-1">
        <Label htmlFor={`credential-${field}`} className="text-xs text-muted-foreground">
          {LABELS[field]}
        </Label>
        {field === "host" ? (
          <Input
            id={`credential-${field}`}
            value={value}
            onChange={(e) => handleFieldChange(field)(e.target.value)}
            placeholder={PLACEHOLDERS[field]}
            disabled={isSending}
            className="font-mono text-sm"
          />
        ) : (
          <SecretInput
            id={`credential-${field}`}
            value={value}
            onChange={handleFieldChange(field)}
            placeholder={PLACEHOLDERS[field]}
            disabled={isSending}
            onEnter={handleSubmit}
          />
        )}
      </div>
    );
  };

  return (
    <div
      className={cn(
        "rounded-md border border-border bg-card p-3 text-sm",
        !isPending && "border-primary/40 bg-primary/5 opacity-80",
      )}
    >
      <header className="flex flex-wrap items-center gap-2 pb-1.5 text-xs text-muted-foreground">
        <KeyRound className="h-3.5 w-3.5 text-primary" />
        <span className="font-medium uppercase tracking-wide">Databricks credentials</span>
      </header>

      {data.context && <p className="pb-2 text-xs text-muted-foreground">{data.context}</p>}

      {data.host && (
        <p className="pb-2 text-xs text-muted-foreground">
          Workspace <span className="font-mono text-foreground">{data.host}</span>
        </p>
      )}

      {isPending && (
        <>
          {/* Always offered, even when a mode is already recorded: that mode may
              itself be the mistake — a service principal's secret sent as a token
              records "token" — and hiding the choice would reopen the same wrong
              form for good. Switching retires the credential it replaces. */}
          <div className="flex gap-1 pb-3">
            {MODE_OPTIONS.map((option) => (
              <button
                key={option.value}
                type="button"
                onClick={handleModeChange(option.value)}
                disabled={isSending}
                className={cn(
                  "rounded border px-2 py-1 text-xs transition-colors",
                  mode === option.value
                    ? "border-primary/60 bg-primary/10 text-foreground"
                    : "border-border bg-background text-muted-foreground hover:bg-accent",
                )}
              >
                {option.label}
              </button>
            ))}
          </div>

          <div className="space-y-2">{fields.map(renderField)}</div>

          {fields.length === 0 && (
            <p className="text-xs text-muted-foreground">Which kind of credential do you have?</p>
          )}

          <p className="flex items-start gap-1.5 pt-3 text-xs text-muted-foreground">
            <ShieldCheck className="mt-0.5 h-3.5 w-3.5 flex-shrink-0 text-primary" />
            <span>
              Sent straight to your session, not into the chat — the assistant never sees the value,
              and it is not saved to disk or to this conversation.
            </span>
          </p>

          {error && <p className="pt-2 text-xs text-destructive">{error}</p>}

          <footer className="mt-3 flex justify-end gap-2">
            <Button type="button" size="sm" variant="ghost" onClick={handleDismiss}>
              Not now
            </Button>
            <Button type="button" size="sm" onClick={handleSubmit} disabled={!canSubmit}>
              {isSending && <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />}
              Send securely
            </Button>
          </footer>
        </>
      )}

      {!isPending && (
        <div className="flex items-center justify-between gap-2">
          <p className="text-xs text-muted-foreground">{resolvedNote}</p>
          <Button type="button" size="sm" variant="ghost" onClick={handleReopen}>
            {reopenLabel}
          </Button>
        </div>
      )}
    </div>
  );
}
