import { useState } from "react";
import SettingsPanel from "@/features/settings/components/SettingsPanel";
import { ErrorBoundary } from "@/shared/components/ErrorBoundary";
import SidePanel from "@/shared/components/layout/SidePanel";
import { useNavigationState } from "@/shared/hooks/navigation/useNavigationState";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";
import { DashboardRunContent } from "./components/DashboardRunContent";

export default function DashboardRunPage() {
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const { activeTab, handleTabChange, handleBackFromSettings, previousTab } = useNavigationState();

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab={activeTab}
          onTabChange={handleTabChange}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onBackFromSettings={handleBackFromSettings}
          previousTab={previousTab}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}
      <div
        className={`flex-1 min-w-0 ${sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0"} transition-all duration-300 flex flex-col overflow-hidden`}
      >
        {activeTab === "settings" ? (
          <SettingsPanel
            settingsEnabled={true}
            onBack={handleBackFromSettings}
            previousTab={previousTab}
          />
        ) : (
          <ErrorBoundary>
            <DashboardRunContent />
          </ErrorBoundary>
        )}
      </div>
    </div>
  );
}
