import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { cancelJoinRequest, listMyJoinRequests, requestJoinTeam } from "../api";
import type { MyJoinRequest, TeamError } from "../types";

// The caller's own join-requests inbox. Powers the suggestion banner's
// "Request pending" / "Cancel request" states. Shared prefix so cross-hook
// invalidations (approve/reject from useTeamJoinRequests) can target it.
export const MY_JOIN_REQUESTS_KEY = ["teams", "my-join-requests"] as const;
const myJoinRequestsKey = (userId: string) => [...MY_JOIN_REQUESTS_KEY, userId] as const;

interface CancelInput {
  teamId: string;
  requestId: string;
}

interface UseMyJoinRequestsReturn {
  requests: MyJoinRequest[];
  isLoading: boolean;
  isFetching: boolean;
  error: TeamError | null;
  refresh: () => Promise<unknown>;

  request: (teamId: string) => Promise<{
    id: string;
    team_id: string;
    user_id: string;
    status: "pending";
    created_at: string;
  }>;
  isRequesting: boolean;
  requestingTeamId: string | null;

  cancel: (input: CancelInput) => Promise<{
    team_id: string;
    request_id: string;
    status: "cancelled";
  }>;
  isCancelling: boolean;
  cancellingRequestId: string | null;
}

// Read is scoped per user (query key includes userId); mutations invalidate
// both this key and — via prefix match — the admin-side team-join-requests
// key so dev/staging flows where the requester and admin share a tab stay
// consistent. TeamJoinRequestsSection also owns invalidations coming the
// other direction (approve/reject → invalidate this key).
export function useMyJoinRequests(): UseMyJoinRequestsReturn {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";

  const query = useQuery<MyJoinRequest[], TeamError>({
    queryKey: myJoinRequestsKey(userId),
    queryFn: () => listMyJoinRequests(supabaseToken),
    enabled: Boolean(userId && supabaseToken),
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const requestMutation = useMutation<
    { id: string; team_id: string; user_id: string; status: "pending"; created_at: string },
    TeamError,
    string
  >({
    mutationFn: (teamId) => requestJoinTeam(teamId, supabaseToken),
    onSuccess: () => {
      // Refresh both sides: the requester's own list (new pending row) AND
      // the admin outbox on this team (new pending row for them). We can't
      // pinpoint the admin's team from just the response, so we invalidate
      // by prefix.
      queryClient.invalidateQueries({ queryKey: MY_JOIN_REQUESTS_KEY });
      queryClient.invalidateQueries({ queryKey: ["teams", "team-join-requests"] });
    },
  });

  const cancelMutation = useMutation<
    { team_id: string; request_id: string; status: "cancelled" },
    TeamError,
    CancelInput
  >({
    mutationFn: ({ teamId, requestId }) => cancelJoinRequest(teamId, requestId, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: MY_JOIN_REQUESTS_KEY });
      queryClient.invalidateQueries({ queryKey: ["teams", "team-join-requests"] });
    },
  });

  return {
    requests: query.data ?? [],
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    refresh: query.refetch,

    request: requestMutation.mutateAsync,
    isRequesting: requestMutation.isPending,
    requestingTeamId: requestMutation.isPending ? (requestMutation.variables ?? null) : null,

    cancel: cancelMutation.mutateAsync,
    isCancelling: cancelMutation.isPending,
    cancellingRequestId: cancelMutation.isPending
      ? (cancelMutation.variables?.requestId ?? null)
      : null,
  };
}
