import { Eye, Pencil, Save, X } from "lucide-react";
import { useState } from "react";

import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

import { useContextEdges } from "../../hooks/useContextEdges";
import { useOntologyConcepts } from "../../hooks/useOntologyConcepts";
import type { ContextEdge, ContextNote } from "../../types";
import type { WikilinkCandidate } from "../editor/wikilinkCompletion";
import type { UseNoteActionsReturn } from "../hooks/useNoteActions";
import {
  buildConceptLinkTargets,
  buildLinkTargets,
  editorDisplayTitle,
  formatUsage,
} from "../notesModel";
import { type NoteEditorMode, notesPreferences } from "../notesPreferences";
import { NoteMarkdownEditor } from "./NoteMarkdownEditor";
import { NoteMarkdownPreview } from "./NoteMarkdownPreview";
import { NoteBadges } from "./ShelfBadge";

interface NoteEditorPaneProps {
  /** Remount with key={note.id} so the draft resets on selection change. */
  note: ContextNote;
  linkCandidates: ContextNote[];
  actions: UseNoteActionsReturn;
  onOpenNoteByTitle: (title: string) => void;
  /** Fixed title for documents (filename) instead of the draft-derived one. */
  titleOverride?: string;
  /** Custom save (documents write the merged text back to their chunks). */
  saveDraft?: (draft: string, edges: ContextEdge[]) => Promise<void>;
}

export function NoteEditorPane({
  note,
  linkCandidates,
  actions,
  onOpenNoteByTitle,
  titleOverride,
  saveDraft,
}: NoteEditorPaneProps) {
  const [draft, setDraft] = useState(note.text);
  // The pane remounts per note (key={note.id}); initializing from storage is
  // what carries the edit/preview choice across note navigation and sessions.
  const [mode, setMode] = useState<NoteEditorMode>(notesPreferences.getEditorMode);
  const { data: edges = [] } = useContextEdges("note", note.id);
  // [[concept:name]] autocomplete over the note's own project vault.
  const { data: conceptNames } = useOntologyConcepts(
    note.scope === "ontology" ? note.scope_id : null,
  );

  const isDirty = draft !== note.text;
  const title = titleOverride ?? editorDisplayTitle(note, draft);

  const getLinkCandidates = (): WikilinkCandidate[] => [
    ...buildLinkTargets(linkCandidates, note.id),
    ...buildConceptLinkTargets(conceptNames ?? []),
  ];

  const handleSave = async () => {
    if (!isDirty || actions.isMutating) return;
    if (saveDraft) {
      await saveDraft(draft, edges);
      return;
    }
    await actions.saveNoteText(note, draft, linkCandidates, edges);
  };

  const handleCancelEdits = () => setDraft(note.text);

  const switchMode = (next: NoteEditorMode) => {
    setMode(next);
    notesPreferences.setEditorMode(next);
  };
  const handleShowEdit = () => switchMode("edit");
  const handleShowPreview = () => switchMode("preview");

  return (
    <div className="flex h-full flex-col">
      <header className="flex shrink-0 items-center justify-between gap-3 border-b border-border px-4 py-2.5">
        <div className="flex min-w-0 items-center gap-2">
          <h2 className="truncate text-base font-semibold text-foreground">{title}</h2>
          {isDirty && (
            <span
              className="h-1.5 w-1.5 shrink-0 rounded-full bg-primary"
              title="Unsaved changes"
            />
          )}
          <NoteBadges note={note} />
        </div>
        <div className="flex shrink-0 items-center gap-1.5">
          <div className="flex items-center rounded-md border border-border p-0.5">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={handleShowEdit}
              className={cn("h-7 px-2.5", mode === "edit" && "bg-accent text-accent-foreground")}
              aria-label="Edit"
            >
              <Pencil className="h-4 w-4" />
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={handleShowPreview}
              className={cn("h-7 px-2.5", mode === "preview" && "bg-accent text-accent-foreground")}
              aria-label="Preview"
            >
              <Eye className="h-4 w-4" />
            </Button>
          </div>
          {isDirty && (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={handleCancelEdits}
              disabled={actions.isMutating}
              className="h-8"
            >
              <X className="mr-1.5 h-4 w-4" />
              Cancel
            </Button>
          )}
          <Button
            type="button"
            size="sm"
            onClick={handleSave}
            disabled={!isDirty || actions.isMutating}
            className="h-8"
          >
            <Save className="mr-1.5 h-4 w-4" />
            Save
          </Button>
        </div>
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto">
        {mode === "edit" ? (
          <NoteMarkdownEditor
            value={draft}
            onChange={setDraft}
            getLinkCandidates={getLinkCandidates}
            onSave={handleSave}
          />
        ) : (
          <NoteMarkdownPreview text={draft} onOpenWikilink={onOpenNoteByTitle} />
        )}
      </div>

      <footer className="shrink-0 border-t border-border px-4 py-2 text-xs text-muted-foreground">
        {formatUsage(note)} · type <code className="rounded bg-muted px-1">[[</code> to link another
        note
      </footer>
    </div>
  );
}
