import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";

interface OverwriteConfirmDialogProps {
  open: boolean;
  conceptName: string;
  onOpenChange: (open: boolean) => void;
  onConfirm: () => void;
}

/** Confirms overwriting an existing concept of the same name when saving. */
export function OverwriteConfirmDialog({
  open,
  conceptName,
  onOpenChange,
  onConfirm,
}: OverwriteConfirmDialogProps) {
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Overwrite Existing Concept</AlertDialogTitle>
          <AlertDialogDescription>
            A concept named &ldquo;{conceptName}&rdquo; already exists. Saving will overwrite its
            definition. Do you want to continue?
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction onClick={onConfirm}>Overwrite</AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}
