import type { FetchResult } from "../../../api/ConceptClient";
import { columnIndex } from "../../../runtime/useConceptRows";
import type { AppWidgetDef } from "../../../schema/appDefinition.types";

interface StatCardV2WidgetProps {
  widget: AppWidgetDef;
  data: FetchResult;
}

function formatStat(value: unknown): string {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return String(value ?? "—");
  if (Math.abs(numeric) >= 1_000_000) return `${(numeric / 1_000_000).toFixed(2)}M`;
  if (Math.abs(numeric) >= 10_000) return `${(numeric / 1_000).toFixed(1)}k`;
  if (Number.isInteger(numeric)) return numeric.toLocaleString();
  return numeric.toLocaleString(undefined, { maximumFractionDigits: 2 });
}

/** stat_card v2: reads the first row's value by column NAME (rename-safe). */
export function StatCardV2Widget({ widget, data }: StatCardV2WidgetProps) {
  const valueIndex = widget.valueCol ? columnIndex(data.columnNames, widget.valueCol) : -1;
  const labelIndex = widget.labelCol ? columnIndex(data.columnNames, widget.labelCol) : -1;
  const firstRow = data.rows[0];

  if (!firstRow || valueIndex < 0) {
    return <p className="text-xs text-muted-foreground py-4">No data</p>;
  }

  const label = labelIndex >= 0 ? String(firstRow[labelIndex] ?? "") : "";

  return (
    <div className="flex flex-col gap-1 py-2">
      <span className="text-3xl font-semibold tracking-tight tabular-nums">
        {formatStat(firstRow[valueIndex])}
      </span>
      {(widget.statSub || label) && (
        <span className="text-[11px] text-muted-foreground">
          {widget.statSub ?? ""}
          {widget.statSub && label ? " · " : ""}
          {label}
        </span>
      )}
    </div>
  );
}
