import { AlertTriangle } from "lucide-react";
import { useState } from "react";
import type { LlmConceptConfig } from "@/features/concept-editor/types";
import type { LlmConnectionSummary } from "@/features/settings/api/configService";
import { Button } from "@/shared/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { LlmConnectionEditor } from "./LlmConnectionEditor";

const CONNECTION_NONE = "none";
const CONNECTION_NEW = "__new__";

interface LlmConnectionSelectorProps {
  cellId: string;
  config: LlmConceptConfig;
  connections: LlmConnectionSummary[];
  /** The pinned connection names one this account does not have. */
  isMissing: boolean;
  disabled?: boolean;
  /** Concept name, used to suggest a name for a connection created here. */
  conceptName?: string;
  onChange: (patch: Partial<LlmConceptConfig>) => void;
}

/**
 * Picks the named connection an llm cell runs through, and repairs the case
 * where the definition names one this account does not have — a shared or
 * imported project, where the reference travels but the credentials do not.
 */
export function LlmConnectionSelector({
  cellId,
  config,
  connections,
  isMissing,
  disabled,
  conceptName,
  onChange,
}: LlmConnectionSelectorProps) {
  const [isCreating, setIsCreating] = useState(false);

  const handleConnectionChange = (value: string) => {
    if (value === CONNECTION_NEW) {
      setIsCreating(true);
      return;
    }
    // Switching the base invalidates provider/model overrides (they targeted
    // the previous base).
    const picked =
      value === CONNECTION_NONE ? undefined : connections.find((c) => c.name === value);
    onChange({
      connection: picked?.name,
      // The hint shadows the pinned connection so a reader without it knows
      // what to configure; it is meaningless without one.
      connection_hint: picked ? { provider: picked.provider, model: picked.model } : undefined,
      provider: undefined,
      model: undefined,
    });
  };

  const handleConnectionCreated = (created: {
    name: string;
    provider?: string;
    model?: string;
  }) => {
    setIsCreating(false);
    onChange({
      connection: created.name,
      connection_hint: { provider: created.provider, model: created.model },
      provider: undefined,
      model: undefined,
    });
  };

  const handleCancel = () => setIsCreating(false);

  const handleSetUpMissing = () => setIsCreating(true);

  // A connection created from this cell keeps the concept's name when it is
  // free, since that is what the reader will be looking for.
  const suggestedName = conceptName?.trim() || "llm_connection";
  const suggestedConnectionName = isMissing ? (config.connection ?? suggestedName) : suggestedName;

  const missingDescription = [config.connection_hint?.provider, config.connection_hint?.model]
    .filter(Boolean)
    .join(" / ");

  return (
    <>
      {/* `w-full` on the banner and the editor: both render inside the same
          flex-wrap row as the selects, where full width is what keeps them on
          their own line above the controls. */}
      {isMissing && (
        <div className="flex w-full flex-wrap items-center gap-2 rounded-md border border-amber-200 bg-amber-50 px-2 py-1.5 text-[11px] text-amber-800 dark:border-amber-900/40 dark:bg-amber-900/20 dark:text-amber-300">
          <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
          <span>
            This concept uses connection <span className="font-medium">{config.connection}</span>
            {missingDescription ? ` (${missingDescription})` : ""}, which is not in your settings.
          </span>
          <Button
            type="button"
            size="sm"
            variant="outline"
            className="h-6 px-2 text-[11px]"
            onClick={handleSetUpMissing}
            disabled={disabled}
          >
            Set up here
          </Button>
        </div>
      )}
      {isCreating && (
        <div className="w-full">
          <LlmConnectionEditor
            suggestedName={suggestedConnectionName}
            initialProvider={config.connection_hint?.provider ?? undefined}
            initialModel={config.connection_hint?.model ?? undefined}
            onSaved={handleConnectionCreated}
            onCancel={handleCancel}
          />
        </div>
      )}
      <div className="flex items-center gap-2">
        <label htmlFor={`llm-connection-${cellId}`} className="text-xs text-muted-foreground">
          Connection
        </label>
        <Select
          value={config.connection ?? CONNECTION_NONE}
          onValueChange={handleConnectionChange}
          disabled={disabled}
        >
          <SelectTrigger
            id={`llm-connection-${cellId}`}
            className="h-7 w-[170px] text-xs border-border"
          >
            <SelectValue placeholder={config.connection ?? "None (user settings)"} />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value={CONNECTION_NONE} className="text-xs">
              None (user settings)
            </SelectItem>
            {connections.map((c) => (
              <SelectItem key={c.name} value={c.name} className="text-xs">
                {c.name}
              </SelectItem>
            ))}
            <SelectItem value={CONNECTION_NEW} className="text-xs">
              New connection…
            </SelectItem>
          </SelectContent>
        </Select>
      </div>
    </>
  );
}
