import { useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { toast } from "sonner";
import { ConfigService, type LlmConnectionSettings } from "@/features/settings/api/configService";
import { LlmConnectionFields } from "@/features/settings/components/model/LlmConnectionFields";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";

interface LlmConnectionEditorProps {
  suggestedName: string;
  initialProvider?: string;
  initialModel?: string;
  onSaved: (created: { name: string; provider?: string; model?: string }) => void;
  onCancel: () => void;
}

/**
 * Define an LLM connection from inside an llm cell.
 *
 * What it writes is an ordinary named connection in the user's settings, not a
 * second kind of entity: the credential belongs to the account, because runs
 * execute on the caller's own pod under the caller's identity, and a definition
 * that carried a key would spend the author's account wherever it was shared.
 * The cell keeps the name.
 */
export function LlmConnectionEditor({
  suggestedName,
  initialProvider,
  initialModel,
  onSaved,
  onCancel,
}: LlmConnectionEditorProps) {
  const queryClient = useQueryClient();
  const [name, setName] = useState(suggestedName);
  const [settings, setSettings] = useState<LlmConnectionSettings>({
    llm_provider: initialProvider ?? "openai",
    llm_version: initialModel ?? "",
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => setName(e.target.value);

  const handleSave = async () => {
    const trimmed = name.trim();
    if (!trimmed) {
      toast.error("Give the connection a name");
      return;
    }
    setIsSaving(true);
    try {
      const summary = await ConfigService.upsertLlmConnection(trimmed, settings);
      queryClient.invalidateQueries({ queryKey: ["llm-defaults"] });
      toast.success(`Connection "${trimmed}" saved`);
      onSaved(summary);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to save the LLM connection");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex flex-col gap-3 rounded-md border border-border bg-muted/30 p-3">
      <div className="flex flex-col gap-1">
        <label htmlFor="llm-cell-conn-name" className="text-xs text-muted-foreground">
          Name
        </label>
        <Input
          id="llm-cell-conn-name"
          value={name}
          onChange={handleNameChange}
          className="h-8 w-full max-w-xs text-sm"
        />
      </div>
      <LlmConnectionFields settings={settings} idPrefix="llm-cell-conn" onChange={setSettings} />
      <p className="text-[11px] text-muted-foreground">
        Saved to your account settings, where you can rotate it later. Only this concept points at
        it until you pick it in another cell.
      </p>
      <div className="flex items-center gap-2">
        <Button type="button" size="sm" onClick={handleSave} disabled={isSaving}>
          {isSaving ? "Saving…" : "Save and use"}
        </Button>
        <Button type="button" size="sm" variant="ghost" onClick={onCancel} disabled={isSaving}>
          Cancel
        </Button>
      </div>
    </div>
  );
}
