// Derives the `compute` override the backend needs to route a run/fetch to the user's
// selected machine (Databricks workspace or a machine pool). This mirrors
// ConceptEditorClient.getComputePayload so federated apps get the same routing the in-tree
// apps do, without importing editor internals.
//
// TODO: dedupe with ConceptEditorClient.getComputePayload once the SDK is the single source.
export async function getComputePayload(): Promise<Record<string, unknown> | undefined> {
  const selectedCompute = localStorage.getItem("selectedCompute");

  // Snowflake: jarvispy already runs on the SPCS compute pool, no override needed.
  if (selectedCompute === "snowflake") return undefined;

  if (selectedCompute === "databricks") {
    const { DatabricksService } = await import("@/features/compute/api/databricksService");
    const cfg = DatabricksService.getDatabricksConfigForExecution();
    const val = DatabricksService.validateDatabricksForExecution();
    if (cfg.databricks_config && val.isValid) {
      return { databricks_configs: cfg.databricks_config };
    }
    return undefined;
  }

  if (selectedCompute === "pools") {
    const machineId = localStorage.getItem("selectedMachineId");
    if (machineId) return { machine_configs: { id: machineId } };
  }

  return undefined;
}
