import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import {
  DEFAULT_MAX_DEPTH,
  type GraphFunctionDef,
  UNLIMITED_MAX_DEPTH,
} from "../../graphFunctions";

interface TraversalOptions {
  allPaths: boolean;
  visited: boolean;
  maxDepth: number;
}

interface ConceptGraphTraversalToolbarProps {
  fn: GraphFunctionDef;
  source: string;
  target: string;
  options: TraversalOptions;
  isBusy: boolean;
  onSourceChange: (value: string) => void;
  onTargetChange: (value: string) => void;
  onOptionsChange: (options: TraversalOptions) => void;
  onLoad: () => void;
}

function helperText(fn: GraphFunctionDef, visited: boolean): string {
  if (fn.supportsVisited && !visited) {
    return "Renders direct source→target reachability edges (no intermediate hops).";
  }
  return fn.hint;
}

export function ConceptGraphTraversalToolbar({
  fn,
  source,
  target,
  options,
  isBusy,
  onSourceChange,
  onTargetChange,
  onOptionsChange,
  onLoad,
}: ConceptGraphTraversalToolbarProps) {
  const missingRequiredSource = fn.requiresSource && source.trim() === "";
  const loadDisabled = isBusy || missingRequiredSource;

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "Enter" && !loadDisabled) onLoad();
  };

  const handleAllPathsToggle = (checked: boolean) =>
    onOptionsChange({ ...options, allPaths: checked });

  const handleVisitedToggle = (checked: boolean) =>
    onOptionsChange({ ...options, visited: checked });

  const isUnlimited = options.maxDepth <= UNLIMITED_MAX_DEPTH;

  const handleMaxDepthChange = (value: string) => {
    const parsed = Number.parseInt(value, 10);
    const maxDepth = Number.isNaN(parsed) || parsed < 1 ? 1 : parsed;
    onOptionsChange({ ...options, maxDepth });
  };

  const handleUnlimitedToggle = (checked: boolean) =>
    onOptionsChange({ ...options, maxDepth: checked ? UNLIMITED_MAX_DEPTH : DEFAULT_MAX_DEPTH });

  return (
    <div className="flex items-center gap-2 px-3 py-1.5 border-b border-border flex-shrink-0 flex-wrap">
      {fn.supportsSourceTarget && (
        <>
          <Input
            value={source}
            onChange={(event) => onSourceChange(event.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={fn.requiresSource ? "Source node (required)" : "Source node"}
            disabled={isBusy}
            className="h-7 w-40 text-xs"
          />
          <Input
            value={target}
            onChange={(event) => onTargetChange(event.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Target node"
            disabled={isBusy}
            className="h-7 w-40 text-xs"
          />
        </>
      )}

      {fn.supportsMaxDepth && (
        <div className="flex items-center gap-1 text-[11px] text-muted-foreground">
          <label htmlFor="graph-max-depth">max depth</label>
          <Input
            id="graph-max-depth"
            type="number"
            min={1}
            value={isUnlimited ? "" : options.maxDepth}
            onChange={(event) => handleMaxDepthChange(event.target.value)}
            onKeyDown={handleKeyDown}
            disabled={isBusy || isUnlimited}
            placeholder={isUnlimited ? "∞" : undefined}
            className="h-7 w-16 text-xs"
          />
          <label className="flex items-center gap-1">
            <input
              type="checkbox"
              checked={isUnlimited}
              disabled={isBusy}
              onChange={(event) => handleUnlimitedToggle(event.target.checked)}
            />
            unlimited
          </label>
        </div>
      )}

      {fn.supportsVisited && (
        <label className="flex items-center gap-1 text-[11px] text-muted-foreground">
          <input
            type="checkbox"
            checked={options.visited}
            disabled={isBusy}
            onChange={(event) => handleVisitedToggle(event.target.checked)}
          />
          provenance
        </label>
      )}

      {fn.supportsAllPaths && (
        <label className="flex items-center gap-1 text-[11px] text-muted-foreground">
          <input
            type="checkbox"
            checked={options.allPaths}
            disabled={isBusy || !options.visited}
            onChange={(event) => handleAllPathsToggle(event.target.checked)}
          />
          all paths
        </label>
      )}

      <Button size="sm" className="h-7 text-xs" disabled={loadDisabled} onClick={onLoad}>
        {isBusy ? "Loading…" : "Load"}
      </Button>

      <p className="text-[10px] text-muted-foreground">{helperText(fn, options.visited)}</p>
    </div>
  );
}
