import { FolderKanban } from "lucide-react";
import { cn } from "@/shared/lib/utils";

export type ExplorerPanelId = "projects";

interface ExplorerRailProps {
  activePanel: ExplorerPanelId | null;
  onPanelChange: (panel: ExplorerPanelId | null) => void;
}

/**
 * Left-edge rail toggling the Projects panel — mirrors the lineage view's
 * rails so all explorers share the same docked-icon pattern. Clicking the
 * active entry closes the panel.
 */
export function ExplorerRail({ activePanel, onPanelChange }: ExplorerRailProps) {
  const isActive = activePanel === "projects";

  const handleClick = () => {
    onPanelChange(isActive ? null : "projects");
  };

  return (
    <div className="flex w-8 flex-shrink-0 flex-col border-r border-border bg-card">
      <button
        type="button"
        onClick={handleClick}
        title="Ontologies"
        aria-pressed={isActive}
        className={cn(
          "flex flex-col items-center gap-2 border-r-2 px-1 py-3 transition-colors",
          isActive
            ? "border-primary bg-accent text-accent-foreground"
            : "border-transparent text-muted-foreground hover:bg-accent hover:text-accent-foreground",
        )}
      >
        <FolderKanban className="h-4 w-4 flex-shrink-0" />
        <span
          className="text-[10px] font-medium uppercase tracking-wider"
          style={{ writingMode: "vertical-rl", transform: "rotate(180deg)" }}
        >
          Ontologies
        </span>
      </button>
    </div>
  );
}
