import { useCallback } from "react";
import type { ConceptClient, FetchResult } from "../api/ConceptClient";
import type {
  ColumnFilterValue,
  DashboardTableHandlers,
  OrderByItem,
  TableSearchState,
} from "../components/outputs/table/tableOutput.types";

interface UseTableActionsParams {
  client: ConceptClient;
  ontologyId: string | undefined;
  scope?: string;
  conceptData: Record<string, FetchResult | null>;
  setConceptData: React.Dispatch<React.SetStateAction<Record<string, FetchResult | null>>>;
  setLoadingConcepts: React.Dispatch<React.SetStateAction<Record<string, boolean>>>;
  setErrorConcepts: React.Dispatch<React.SetStateAction<Record<string, string>>>;
}

const DEFAULT_PAGE_SIZE = 10;

function hasActiveSearch(searchState: TableSearchState | undefined): boolean {
  if (!searchState) return false;
  if (searchState.searchTerm.trim()) return true;
  return !!searchState.columnFilters && Object.keys(searchState.columnFilters).length > 0;
}

export function useTableActions({
  client,
  ontologyId,
  scope = "user",
  conceptData,
  setConceptData,
  setLoadingConcepts,
  setErrorConcepts,
}: UseTableActionsParams): DashboardTableHandlers {
  const runFetch = useCallback(
    async (
      conceptName: string,
      page: number,
      pageSize: number,
      orderBy: OrderByItem[] | undefined,
      searchState: TableSearchState | undefined,
    ) => {
      if (!ontologyId) return;
      setLoadingConcepts((prev) => ({ ...prev, [conceptName]: true }));
      try {
        const data = hasActiveSearch(searchState)
          ? await client.searchConceptData(
              ontologyId,
              conceptName,
              scope,
              searchState!.searchTerm,
              searchState!.columnFilters,
              page,
              pageSize,
              orderBy,
            )
          : await client.fetchConceptData(ontologyId, conceptName, scope, page, pageSize, orderBy);
        setConceptData((prev) => ({ ...prev, [conceptName]: data }));
        setErrorConcepts((prev) => {
          if (!(conceptName in prev)) return prev;
          const next = { ...prev };
          delete next[conceptName];
          return next;
        });
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : "Failed to load data";
        setErrorConcepts((prev) => ({ ...prev, [conceptName]: message }));
      } finally {
        setLoadingConcepts((prev) => ({ ...prev, [conceptName]: false }));
      }
    },
    [client, ontologyId, scope, setConceptData, setErrorConcepts, setLoadingConcepts],
  );

  const onPageChange = useCallback(
    async (conceptName: string, page: number) => {
      const current = conceptData[conceptName];
      const pageSize = current?.pageSize ?? DEFAULT_PAGE_SIZE;
      await runFetch(conceptName, page, pageSize, current?.orderBy, current?.searchState);
    },
    [conceptData, runFetch],
  );

  const onPageSizeChange = useCallback(
    async (conceptName: string, pageSize: number) => {
      const current = conceptData[conceptName];
      await runFetch(conceptName, 1, pageSize, current?.orderBy, current?.searchState);
    },
    [conceptData, runFetch],
  );

  const onSort = useCallback(
    async (conceptName: string, orderBy: OrderByItem[]) => {
      const current = conceptData[conceptName];
      const pageSize = current?.pageSize ?? DEFAULT_PAGE_SIZE;
      const nextOrderBy = orderBy.length > 0 ? orderBy : undefined;
      await runFetch(conceptName, 1, pageSize, nextOrderBy, current?.searchState);
    },
    [conceptData, runFetch],
  );

  const onSearch = useCallback(
    async (
      conceptName: string,
      searchTerm?: string,
      columnFilters?: Record<number, ColumnFilterValue>,
    ) => {
      const current = conceptData[conceptName];
      const pageSize = current?.pageSize ?? DEFAULT_PAGE_SIZE;
      const nextSearch: TableSearchState = {
        searchTerm: searchTerm ?? "",
        columnFilters,
      };
      if (!hasActiveSearch(nextSearch)) {
        await runFetch(conceptName, 1, pageSize, current?.orderBy, undefined);
        return;
      }
      await runFetch(conceptName, 1, pageSize, current?.orderBy, nextSearch);
    },
    [conceptData, runFetch],
  );

  const onClearSearch = useCallback(
    async (conceptName: string) => {
      const current = conceptData[conceptName];
      const pageSize = current?.pageSize ?? DEFAULT_PAGE_SIZE;
      await runFetch(conceptName, 1, pageSize, current?.orderBy, undefined);
    },
    [conceptData, runFetch],
  );

  return { onPageChange, onPageSizeChange, onSort, onSearch, onClearSearch };
}
