import { Brain, ChevronDown, ChevronRight } from "lucide-react";
import { useState } from "react";

interface ThinkingMessageProps {
  /** The streamed reasoning text. */
  content: string;
  /** True while this reasoning run is still streaming (it is the live turn). */
  isActive: boolean;
}

/**
 * Collapsible block for the model's streamed extended-thinking. Auto-expanded
 * while it is the active (streaming) run so the user sees live progress instead
 * of a stalled "Thinking…" spinner; collapses to a compact pill once the answer
 * begins, and can be reopened to review the reasoning.
 */
export function ThinkingMessage({ content, isActive }: ThinkingMessageProps) {
  const [manuallyOpen, setManuallyOpen] = useState(false);
  const isOpen = isActive || manuallyOpen;

  const toggle = () => setManuallyOpen((prev) => !prev);

  return (
    <div className="w-full rounded-lg border border-border bg-card px-3 py-2 text-xs shadow-sm">
      <button
        type="button"
        onClick={toggle}
        className="flex w-full items-center gap-2 text-left text-muted-foreground hover:text-foreground"
      >
        <Brain className={isActive ? "h-3.5 w-3.5 animate-pulse" : "h-3.5 w-3.5"} />
        <span className="font-medium">{isActive ? "Thinking…" : "Thought process"}</span>
        {isOpen ? (
          <ChevronDown className="ml-auto h-3.5 w-3.5" />
        ) : (
          <ChevronRight className="ml-auto h-3.5 w-3.5" />
        )}
      </button>
      {isOpen && content && (
        <p className="mt-2 max-h-64 overflow-y-auto whitespace-pre-wrap break-words italic leading-relaxed text-muted-foreground">
          {content}
        </p>
      )}
    </div>
  );
}
