import { Plus, Trash2 } from "lucide-react";
import { Input } from "@/shared/components/ui/input";
import { InfoHint } from "../InfoHint";

interface KeyValueEditorProps {
  label: string;
  keyPlaceholder: string;
  valuePlaceholder: string;
  entries: Record<string, string>;
  onChange: (entries: Record<string, string> | undefined) => void;
  hint?: string;
}

/**
 * Ordered key→value rows for run-group bindings (params: @param → template,
 * facts: input predicate → record-group ref). Empty map clears the property.
 */
export function KeyValueEditor({
  label,
  keyPlaceholder,
  valuePlaceholder,
  entries,
  onChange,
  hint,
}: KeyValueEditorProps) {
  const rows = Object.entries(entries);

  const commit = (next: Array<[string, string]>) => {
    const filtered = next.filter(([key]) => key.trim() !== "");
    onChange(filtered.length > 0 ? Object.fromEntries(filtered) : undefined);
  };

  const updateRow = (index: number, key: string, value: string) => {
    const next: Array<[string, string]> = rows.map((row, i) => (i === index ? [key, value] : row));
    commit(next);
  };

  const removeRow = (index: number) => {
    commit(rows.filter((_, i) => i !== index));
  };

  const addRow = () => {
    onChange({ ...entries, "": "" });
  };

  return (
    <div className="flex flex-col gap-1">
      <span className="flex items-center gap-1 text-[10px] font-medium text-muted-foreground">
        {label}
        {hint && <InfoHint text={hint} />}
      </span>
      {rows.map(([key, value], index) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: rows are positional while being edited
        <div key={index} className="flex items-center gap-1">
          <Input
            value={key}
            placeholder={keyPlaceholder}
            onChange={(event) => updateRow(index, event.target.value, value)}
            className="h-6 text-[11px] font-mono flex-1 min-w-0"
          />
          <span className="text-muted-foreground/50 text-[10px] flex-shrink-0">→</span>
          <Input
            value={value}
            placeholder={valuePlaceholder}
            onChange={(event) => updateRow(index, key, event.target.value)}
            className="h-6 text-[11px] font-mono flex-1 min-w-0"
          />
          <button
            type="button"
            title="Remove binding"
            onClick={() => removeRow(index)}
            className="p-0.5 text-muted-foreground hover:text-destructive flex-shrink-0"
          >
            <Trash2 className="h-3 w-3" />
          </button>
        </div>
      ))}
      <button
        type="button"
        onClick={addRow}
        className="flex items-center gap-1 py-0.5 text-[10px] text-muted-foreground hover:text-foreground self-start"
      >
        <Plus className="h-2.5 w-2.5" />
        Add binding
      </button>
    </div>
  );
}
