import { useCallback, useEffect, useRef, useState } from "react";
import { useCodeAssistantStore } from "@/features/code-assistant/store";

const STORAGE_KEY = "ai_assistant_panel_width";
const DEFAULT_WIDTH = 320; // matches w-80
const MIN_WIDTH = 280;
const MAX_WIDTH = 800;

interface UsePanelResizeReturn {
  width: number;
  isResizing: boolean;
  handleResizeMouseDown: (e: React.MouseEvent) => void;
}

export function usePanelResize(): UsePanelResizeReturn {
  const [width, setWidth] = useState<number>(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = parseInt(stored, 10);
        if (!Number.isNaN(parsed) && parsed >= MIN_WIDTH && parsed <= MAX_WIDTH) return parsed;
      }
    } catch {
      // ignore — fall through to default
    }
    return DEFAULT_WIDTH;
  });

  const [isResizing, setIsResizing] = useState(false);
  const setPanelWidth = useCodeAssistantStore((state) => state.setPanelWidth);

  // Refs so the mouse-event closures always see the latest values.
  const startXRef = useRef(0);
  const startWidthRef = useRef(0);
  const latestWidthRef = useRef(width);

  useEffect(() => {
    latestWidthRef.current = width;
  }, [width]);

  // Mirror the width into the store so responsive consumers (e.g. the project
  // header) can treat the open panel as reserved horizontal space.
  useEffect(() => {
    setPanelWidth(width);
  }, [width, setPanelWidth]);

  const handleResizeMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
    startXRef.current = e.clientX;
    startWidthRef.current = latestWidthRef.current;

    document.body.style.cursor = "ew-resize";
    document.body.style.userSelect = "none";

    const onMove = (moveEvent: MouseEvent) => {
      // Panel is docked on the left (after the sidebar); its drag handle is on the
      // right edge, so dragging rightward widens it.
      const delta = moveEvent.clientX - startXRef.current;
      const next = Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, startWidthRef.current + delta));
      setWidth(next);
      latestWidthRef.current = next;
    };

    const onUp = () => {
      setIsResizing(false);
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
      try {
        localStorage.setItem(STORAGE_KEY, String(latestWidthRef.current));
      } catch {
        // ignore
      }
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup", onUp);
    };

    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseup", onUp);
  }, []);

  return { width, isResizing, handleResizeMouseDown };
}
