import { useCodeAssistantStore } from "../store";
import { useChatModels } from "./useChatModels";

interface UseVisionSupportReturn {
  /** True only when the active model is known to be unable to see images. */
  isTextOnly: boolean;
  /** The model the verdict refers to, for the warning copy. */
  model: string;
}

/**
 * Whether the model this chat will use can look at an attached image.
 *
 * The backend already degrades gracefully — a text-only model is told in words
 * what it was sent and asked to say it cannot see it — but the user only finds
 * out after spending a turn. This lets the composer say so up front.
 *
 * Deliberately conservative: a verdict is only returned when the model appears
 * in the fetched list and is absent from the vision subset. An unreachable
 * endpoint or an unrecognised model reports nothing rather than warning wrongly.
 */
export function useVisionSupport(): UseVisionSupportReturn {
  const { models, visionModels } = useChatModels();
  const selectedModel = useCodeAssistantStore((s) => s.selectedModel);
  const activeModel = useCodeAssistantStore((s) => s.activeModel);

  const model = selectedModel ?? activeModel ?? "";
  const isKnown = !!model && models.includes(model);

  return { isTextOnly: isKnown && !visionModels.includes(model), model };
}
