import { useMemo } from "react";
import { useOntologies } from "@/features/ontologies/hooks/useOntologies";
import { useOntologyId } from "@/features/ontologies/hooks/useOntologyId";
import type { ShareRole, ShareType, ShareUser } from "../types";

interface SharedOntologyContext {
  // True when the current project was injected from the recipient's inbox (origin="shared").
  isShared: boolean;
  // Convenience flag — viewer = read-only. Editor and owned projects map to false.
  isReadOnly: boolean;
  shareRole: ShareRole | null;
  sharedBy: ShareUser | null;
  // Id used by leaveShare() to drop the recipient's local token for this project.
  shareId: string | null;
  expiresAt: string | null;
  // "team" when this share was derived from a team share; the recipient team is
  // `teamId`. Together they let a recipient-team owner/admin co-manage the project.
  shareType: ShareType | null;
  teamId: string | null;
}

const EMPTY_CONTEXT: SharedOntologyContext = {
  isShared: false,
  isReadOnly: false,
  shareRole: null,
  sharedBy: null,
  shareId: null,
  expiresAt: null,
  shareType: null,
  teamId: null,
};

// Returns sharing-aware context for the project the user is currently viewing.
// Reads from the merged useProjects cache so it costs nothing extra beyond what the
// hook is already doing (the inbox query is deduped by React Query).
//
// Consumers:
//   - <SharedProjectBanner> renders the "Shared by X — role" pill from this hook.
//   - <ReadOnlyGate> reads isReadOnly to disable editor-mutation affordances.
//   - Future role-aware actions (e.g. hiding rename/delete in shared projects) consume
//     isShared / shareRole directly.
export function useSharedOntologyContext(): SharedOntologyContext {
  const ontologyId = useOntologyId();
  const { projects } = useOntologies();

  return useMemo(() => {
    if (!ontologyId) return EMPTY_CONTEXT;
    const project = projects.find((p) => p.id === ontologyId);
    if (!project || project.origin !== "shared") return EMPTY_CONTEXT;
    const role = project.shareRole ?? null;
    return {
      isShared: true,
      isReadOnly: role === "viewer",
      shareRole: role,
      sharedBy: project.sharedBy ?? null,
      shareId: project.shareId ?? null,
      expiresAt: project.expiresAt ?? null,
      shareType: project.shareType ?? "user",
      teamId: project.teamId ?? null,
    };
  }, [ontologyId, projects]);
}
