import {
  ArrowUpDown,
  Check,
  Download,
  Folder,
  FolderInput,
  Link,
  Pencil,
  Trash2,
  X,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import type { FileEntry } from "@/features/data-sources/api/fileSystemApi";
import { isConnectable } from "@/features/data-sources/hooks/useFileBrowser";
import { resolveFileIconOrGeneric } from "@/shared/components/icons/fileTypeIcons";
import { Button } from "@/shared/components/ui/button";
import { Checkbox } from "@/shared/components/ui/checkbox";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";

type SortKey = "name" | "size" | "modified";
type SortDir = "asc" | "desc";

interface FileListProps {
  entries: FileEntry[];
  selectedFiles: Set<string>;
  onToggleSelect: (name: string) => void;
  onToggleSelectAll: (selectAll: boolean) => void;
  onNavigateInto: (folderName: string) => void;
  onDelete: (names: string[]) => void;
  onConnect: (entry: FileEntry) => void;
  onRename: (oldName: string, newName: string) => void;
  onMove: (name: string, destinationDir: string) => void;
  onDownload: (name: string) => void;
  currentPath: string;
  connectingNames: Set<string>;
}

const FILE_ICON_SIZE = "h-4 w-4";

function getFileIcon(entry: FileEntry) {
  if (entry.type === "directory")
    return <Folder className={`${FILE_ICON_SIZE} text-blue-500 dark:text-blue-400`} />;
  return resolveFileIconOrGeneric(entry.extension, FILE_ICON_SIZE);
}

function formatSize(bytes: number | null): string {
  if (bytes == null) return "—";
  if (bytes === 0) return "0 B";
  const units = ["B", "KB", "MB", "GB"];
  const i = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
  const value = bytes / 1024 ** i;
  return `${value < 10 ? value.toFixed(1) : Math.round(value)} ${units[i]}`;
}

function formatDate(iso: string): string {
  const d = new Date(iso);
  return d.toLocaleDateString(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export function FileList({
  entries,
  selectedFiles,
  onToggleSelect,
  onToggleSelectAll,
  onNavigateInto,
  onDelete,
  onConnect,
  onRename,
  onMove,
  onDownload,
  currentPath,
  connectingNames,
}: FileListProps) {
  const [sortKey, setSortKey] = useState<SortKey>("name");
  const [sortDir, setSortDir] = useState<SortDir>("asc");
  const [renamingName, setRenamingName] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState("");
  const [movingName, setMovingName] = useState<string | null>(null);
  const [moveDestination, setMoveDestination] = useState("");
  const renameInputRef = useRef<HTMLInputElement>(null);
  const moveInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (renamingName && renameInputRef.current) {
      renameInputRef.current.focus();
      const dotIdx = renamingName.lastIndexOf(".");
      renameInputRef.current.setSelectionRange(0, dotIdx > 0 ? dotIdx : renamingName.length);
    }
  }, [renamingName]);

  useEffect(() => {
    if (movingName && moveInputRef.current) {
      moveInputRef.current.focus();
      moveInputRef.current.select();
    }
  }, [movingName]);

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortDir((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setSortKey(key);
      setSortDir("asc");
    }
  };

  const sorted = useMemo(() => {
    const copy = [...entries];
    const dir = sortDir === "asc" ? 1 : -1;
    copy.sort((a, b) => {
      if (a.type !== b.type) return a.type === "directory" ? -1 : 1;
      switch (sortKey) {
        case "name":
          return dir * a.name.localeCompare(b.name);
        case "size":
          return dir * ((a.size ?? 0) - (b.size ?? 0));
        case "modified":
          return dir * (new Date(a.modified).getTime() - new Date(b.modified).getTime());
        default:
          return 0;
      }
    });
    return copy;
  }, [entries, sortKey, sortDir]);

  const allSelected = entries.length > 0 && selectedFiles.size === entries.length;

  const startRename = (name: string) => {
    setRenamingName(name);
    setRenameValue(name);
  };

  const commitRename = () => {
    if (!renamingName) return;
    const trimmed = renameValue.trim();
    if (trimmed && trimmed !== renamingName) {
      onRename(renamingName, trimmed);
    }
    setRenamingName(null);
  };

  const cancelRename = () => {
    setRenamingName(null);
  };

  const startMove = (name: string) => {
    setMovingName(name);
    const parentPath = currentPath ? currentPath.split("/").slice(0, -1).join("/") : "";
    setMoveDestination(parentPath);
  };

  const commitMove = () => {
    if (!movingName) return;
    const trimmed = moveDestination.trim();
    onMove(movingName, trimmed);
    setMovingName(null);
  };

  const cancelMove = () => {
    setMovingName(null);
  };

  if (entries.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-muted-foreground">
        <Folder className="mb-3 h-10 w-10 opacity-40" />
        <p className="text-sm">This folder is empty</p>
      </div>
    );
  }

  const sortIndicator = (key: SortKey) => {
    if (sortKey !== key) return null;
    return <span className="ml-0.5 text-xs">{sortDir === "asc" ? "↑" : "↓"}</span>;
  };

  return (
    <div className="rounded-md border border-border">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-border bg-muted/50 text-left text-xs text-muted-foreground">
            <th className="w-10 px-3 py-2">
              <Checkbox
                checked={allSelected}
                onCheckedChange={(checked) => onToggleSelectAll(Boolean(checked))}
              />
            </th>
            <th className="px-3 py-2">
              <button
                type="button"
                className="flex items-center gap-1"
                onClick={() => toggleSort("name")}
              >
                Name <ArrowUpDown className="h-3 w-3" /> {sortIndicator("name")}
              </button>
            </th>
            <th className="hidden w-24 px-3 py-2 sm:table-cell">
              <button
                type="button"
                className="flex items-center gap-1"
                onClick={() => toggleSort("size")}
              >
                Size <ArrowUpDown className="h-3 w-3" /> {sortIndicator("size")}
              </button>
            </th>
            <th className="hidden w-44 px-3 py-2 md:table-cell">
              <button
                type="button"
                className="flex items-center gap-1"
                onClick={() => toggleSort("modified")}
              >
                Modified <ArrowUpDown className="h-3 w-3" /> {sortIndicator("modified")}
              </button>
            </th>
            <th className="w-40 px-3 py-2 text-right">Actions</th>
          </tr>
        </thead>
        <tbody>
          {sorted.map((entry) => {
            const selected = selectedFiles.has(entry.name);
            const connectable = isConnectable(entry);
            const isEntryConnecting = connectingNames.has(entry.name);
            const isRenaming = renamingName === entry.name;
            const isMoving = movingName === entry.name;

            return (
              <tr
                key={entry.name}
                className={`border-b border-border last:border-b-0 transition-colors ${
                  selected ? "bg-accent/60" : "hover:bg-accent/30"
                }`}
              >
                <td className="px-3 py-2">
                  <Checkbox checked={selected} onCheckedChange={() => onToggleSelect(entry.name)} />
                </td>
                <td className="px-3 py-2">
                  {isRenaming ? (
                    <div className="flex items-center gap-1.5">
                      {getFileIcon(entry)}
                      <input
                        ref={renameInputRef}
                        type="text"
                        value={renameValue}
                        onChange={(e) => setRenameValue(e.target.value)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter") commitRename();
                          if (e.key === "Escape") cancelRename();
                        }}
                        onBlur={commitRename}
                        className="h-6 flex-1 rounded border border-input bg-background px-1.5 text-sm text-foreground focus:outline-none focus:ring-1 focus:ring-ring"
                      />
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-6 w-6"
                        onClick={commitRename}
                      >
                        <Check className="h-3 w-3" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-6 w-6"
                        onMouseDown={cancelRename}
                      >
                        <X className="h-3 w-3" />
                      </Button>
                    </div>
                  ) : isMoving ? (
                    <div className="flex flex-col gap-1.5">
                      <span className="flex items-center gap-2 text-foreground">
                        {getFileIcon(entry)}
                        {entry.name}
                      </span>
                      <div className="ml-6 flex items-center gap-1.5">
                        <span className="shrink-0 text-xs text-muted-foreground">Move to:</span>
                        <span className="shrink-0 text-xs text-muted-foreground">disk /</span>
                        <input
                          ref={moveInputRef}
                          type="text"
                          value={moveDestination}
                          onChange={(e) => setMoveDestination(e.target.value)}
                          onKeyDown={(e) => {
                            if (e.key === "Enter") commitMove();
                            if (e.key === "Escape") cancelMove();
                          }}
                          placeholder="path/to/folder (empty = root)"
                          className="h-6 w-48 rounded border border-input bg-background px-1.5 text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring"
                        />
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6"
                          onClick={commitMove}
                        >
                          <Check className="h-3 w-3" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6"
                          onClick={cancelMove}
                        >
                          <X className="h-3 w-3" />
                        </Button>
                      </div>
                    </div>
                  ) : entry.type === "directory" ? (
                    <button
                      type="button"
                      onClick={() => onNavigateInto(entry.name)}
                      className="flex items-center gap-2 font-medium text-foreground hover:underline"
                    >
                      {getFileIcon(entry)}
                      {entry.name}
                    </button>
                  ) : (
                    <span className="flex items-center gap-2 text-foreground">
                      {getFileIcon(entry)}
                      {entry.name}
                    </span>
                  )}
                </td>
                <td className="hidden px-3 py-2 text-muted-foreground sm:table-cell">
                  {formatSize(entry.size)}
                </td>
                <td className="hidden px-3 py-2 text-muted-foreground md:table-cell">
                  {formatDate(entry.modified)}
                </td>
                <td className="px-3 py-2">
                  <div className="flex items-center justify-end gap-1">
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7"
                          onClick={() => startRename(entry.name)}
                        >
                          <Pencil className="h-3.5 w-3.5" />
                        </Button>
                      </TooltipTrigger>
                      <TooltipContent>Rename</TooltipContent>
                    </Tooltip>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7"
                          onClick={() => startMove(entry.name)}
                        >
                          <FolderInput className="h-3.5 w-3.5" />
                        </Button>
                      </TooltipTrigger>
                      <TooltipContent>Move to folder</TooltipContent>
                    </Tooltip>
                    {entry.type === "file" && (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7"
                            onClick={() => onDownload(entry.name)}
                          >
                            <Download className="h-3.5 w-3.5" />
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>Download</TooltipContent>
                      </Tooltip>
                    )}
                    {connectable && (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7"
                            onClick={() => onConnect(entry)}
                            disabled={isEntryConnecting}
                          >
                            {isEntryConnecting ? (
                              <PrometheuxSpinner size={16} />
                            ) : (
                              <Link className="h-3.5 w-3.5" />
                            )}
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>
                          {isEntryConnecting ? "Connecting…" : "Connect as data source"}
                        </TooltipContent>
                      </Tooltip>
                    )}
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 text-destructive hover:text-destructive"
                          onClick={() => onDelete([entry.name])}
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                        </Button>
                      </TooltipTrigger>
                      <TooltipContent>Delete</TooltipContent>
                    </Tooltip>
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
