import type { LlmConnectionSettings } from "../api/configService";

/** The providers a connection can target, as the backend resolver names them. */
export const LLM_PROVIDERS = [
  { value: "openai", label: "OpenAI" },
  { value: "anthropic", label: "Anthropic" },
  { value: "azure", label: "Azure" },
  { value: "databricks", label: "Databricks" },
  { value: "snowflake_cortex", label: "Snowflake Cortex" },
] as const;

/**
 * The fields of a connection that are credentials rather than configuration.
 * Mirrors SECRET_CONNECTION_FIELDS in the backend's llm_config, which is what
 * decides that an omitted one on save means unchanged.
 */
export const SECRET_FIELDS = ["llm_api_key", "databricks_client_secret"] as const;

type SecretField = (typeof SECRET_FIELDS)[number];

/** Which credentials a stored connection already holds, for placeholder copy. */
export function storedSecretsOf(settings: LlmConnectionSettings | undefined): SecretField[] {
  if (!settings) return [];
  return SECRET_FIELDS.filter((field) => Boolean(settings[field]));
}

/**
 * A copy of the settings with credentials dropped, for editing.
 *
 * The load-config response still carries stored keys, so an edit form would
 * otherwise put a live credential into an input. Blank plus "omitted means
 * unchanged" on save reaches the same result without holding the secret.
 */
export function withoutSecrets(settings: LlmConnectionSettings): LlmConnectionSettings {
  return SECRET_FIELDS.reduce<LlmConnectionSettings>(
    (acc, field) => {
      const { [field]: _dropped, ...rest } = acc;
      return rest;
    },
    { ...settings },
  );
}

/**
 * The fields model discovery needs: which account we are asking, not what it was
 * asked for. The model is excluded because it is the answer, and the provider
 * travels as its own request field.
 */
const NON_DISCOVERY_FIELDS: readonly string[] = ["llm_version", "llm_provider"];

/** The credentials and endpoints to list models against, blanks dropped. */
export function discoveryFieldsOf(settings: LlmConnectionSettings): Record<string, string> {
  return Object.entries(settings).reduce<Record<string, string>>((acc, [field, value]) => {
    if (NON_DISCOVERY_FIELDS.includes(field)) return acc;
    if (typeof value !== "string" || value === "") return acc;
    acc[field] = value;
    return acc;
  }, {});
}

/**
 * A short digest of a request body, for use in a cache key.
 *
 * The body carries credentials, and a cache key is visible wherever the query
 * cache is (devtools, a persister). A digest still changes when the credential
 * does — which is what makes the list refetch — without holding the value.
 * FNV-1a: not cryptographic, and it does not need to be.
 */
export function configFingerprint(value: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16);
}

/**
 * Apply an edit to a stored connection the way the backend will, so the list can
 * be updated without refetching: the edit is authoritative, except that a
 * credential it leaves out is one the user chose not to touch.
 */
export function applyConnectionEdit(
  stored: LlmConnectionSettings | undefined,
  edit: LlmConnectionSettings,
): LlmConnectionSettings {
  const kept = SECRET_FIELDS.reduce<LlmConnectionSettings>((acc, field) => {
    if (edit[field] === undefined && stored?.[field]) acc[field] = stored[field];
    return acc;
  }, {});
  return { ...edit, ...kept };
}
