import { FolderKanban } from "lucide-react";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { cn } from "@/shared/lib/utils";
import type { AppDefinition } from "../../schema/appDefinition.types";
import { pageRendersV2 } from "../../schema/appDefinition.types";
import { AppTabView } from "./AppTabView";

interface AppRendererProps {
  definition: AppDefinition;
  hideHeader?: boolean;
  /** The app's home project — rendered as a link on the header's right side. */
  project?: { id: string; name: string };
  /** Controlled active tab (editor preview). Uncontrolled when omitted. */
  activePageId?: string;
  onActivePageChange?: (pageId: string) => void;
}

/**
 * Schema v2 app viewer: header + tabs; every tab is self-contained
 * (own project, context and run groups — ADR D9). Each tab keeps its
 * state when switching because all tabs stay mounted (hidden via CSS).
 */
export function AppRenderer({
  definition,
  hideHeader = false,
  project,
  activePageId,
  onActivePageChange,
}: AppRendererProps) {
  const navigate = useNavigate();
  const [internalActivePage, setInternalActivePage] = useState(definition.pages[0]?.id ?? "");
  const activePage = activePageId ?? internalActivePage;
  const setActivePage = onActivePageChange ?? setInternalActivePage;
  // `header` can be absent on imported or hand-edited definitions — default
  // it so a missing header degrades to the app name instead of white-screening.
  const { pages } = definition;
  const header = definition.header ?? { title: definition.name };

  const handleOpenOntology = () => {
    if (project) navigate(`/editor/${project.id}`);
  };

  return (
    <div className="flex flex-col h-full overflow-hidden bg-background">
      {!hideHeader && (
        <header className="bg-card border-b border-border px-8 h-14 flex items-center justify-between flex-shrink-0 sticky top-0 z-10">
          <div className="flex items-center gap-5 min-w-0">
            {header.logoUrl && (
              <>
                <img src={header.logoUrl} alt="Logo" className="h-[22px] w-auto flex-shrink-0" />
                <div className="w-px h-5 bg-border flex-shrink-0" />
              </>
            )}
            <div className="min-w-0 overflow-hidden">
              <div className="text-[13px] font-medium text-foreground/80 leading-tight truncate">
                {header.title || "App"}
              </div>
              {header.subtitle && (
                <div className="text-[11px] font-mono text-muted-foreground mt-px truncate">
                  {header.subtitle}
                </div>
              )}
            </div>
          </div>
          {project && (
            <button
              type="button"
              onClick={handleOpenOntology}
              className="flex items-center gap-1.5 flex-shrink-0 text-[11px] font-mono text-muted-foreground hover:text-foreground bg-secondary border border-border px-2.5 py-[3px] rounded transition-colors"
              title="Open the ontology this app is built on"
            >
              <FolderKanban className="h-3 w-3" />
              {project.name}
            </button>
          )}
        </header>
      )}

      {pages.length > 1 && (
        <div className="bg-card border-b border-border px-8 flex flex-shrink-0 overflow-x-auto">
          {pages.map((page) => (
            <button
              key={page.id}
              type="button"
              onClick={() => setActivePage(page.id)}
              className={cn(
                "px-[18px] py-3 text-[12px] font-medium border-b-2 -mb-px transition-all duration-150 whitespace-nowrap flex-shrink-0",
                page.id === activePage
                  ? "text-foreground border-foreground"
                  : "text-muted-foreground border-transparent hover:text-foreground/70",
              )}
            >
              {page.label}
            </button>
          ))}
        </div>
      )}

      <div className="flex-1 overflow-auto px-8 py-6">
        {pages.map((page) => (
          <div key={page.id} className={page.id === activePage ? "block" : "hidden"}>
            {pageRendersV2(page) ? (
              <AppTabView page={page} />
            ) : (
              <p className="text-sm text-muted-foreground py-8">
                This tab uses the legacy app format — open it from the classic viewer.
              </p>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
