/**
 * Utility functions for masking API keys and sensitive data
 */

/**
 * Masks an API key by showing only the start and end characters
 * @param key - The API key to mask
 * @param visibleStart - Number of characters to show at the start (default: 8)
 * @param visibleEnd - Number of characters to show at the end (default: 8)
 * @returns Masked API key string
 */
export const maskApiKey = (key: string, visibleStart = 8, visibleEnd = 8): string => {
  if (!key) return "";

  // If the key is too short, return it as is
  if (key.length <= visibleStart + visibleEnd) {
    return key;
  }

  const start = key.substring(0, visibleStart);
  const end = key.substring(key.length - visibleEnd);
  const middle = "•".repeat(Math.min(12, key.length - visibleStart - visibleEnd));

  return `${start}${middle}${end}`;
};
