import { FileText, Table2 } from "lucide-react";
import type React from "react";
import type { ConceptCell } from "@/features/concept-editor/types";
import { runStatusDotClass } from "@/features/concept-editor/utils/runStatus";
import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

/** The two views that can occupy the bottom panel in split layout. */
type BottomView = "context" | "output";

/**
 * `TNonBottomView` is inferred from `editorView` alone (hence `NoInfer`
 * elsewhere), so a cell with a third non-bottom view — the logic cell's
 * "engine" — passes its union explicitly.
 */
interface CellSplitBottomTabsProps<TNonBottomView extends string> {
  cell: ConceptCell;
  currentView: NoInfer<TNonBottomView> | BottomView;
  /** The cell's authoring view — selecting an open tab collapses back to it. */
  editorView: TNonBottomView;
  /** Label for the left tab ("context" or "description"). */
  contextLabel?: string;
  /**
   * Cell-specific tabs rendered between context and output — currently only the
   * logic cell's "engine" tab. Build them with SplitBottomTabButton so they
   * match.
   */
  extraTabs?: React.ReactNode;
  onSelectView: (view: NoInfer<TNonBottomView> | BottomView) => void;
}

const TAB_BASE = "h-7 px-2 text-xs";
const TAB_ACTIVE = "bg-muted text-foreground";
const TAB_INACTIVE = "hover:bg-muted/50";

interface SplitBottomTabButtonProps {
  isOpen: boolean;
  icon: React.ReactNode;
  label: string;
  /** Status indicator shown after the label, e.g. a run-state dot. */
  indicator?: React.ReactNode;
  onClick: () => void;
}

/** A single tab in the bottom panel bar, for cells that add their own. */
export function SplitBottomTabButton({
  isOpen,
  icon,
  label,
  indicator,
  onClick,
}: SplitBottomTabButtonProps) {
  return (
    <Button
      variant="ghost"
      size="sm"
      onClick={onClick}
      className={cn(TAB_BASE, isOpen ? TAB_ACTIVE : TAB_INACTIVE)}
    >
      {icon}
      {label}
      {indicator}
    </Button>
  );
}

/**
 * Bottom panel switcher shown under the editor in Explorer (split) layout.
 *
 * Unlike the top tabs these toggle: clicking the open tab collapses the panel
 * by returning to the editor view, giving the editor the full height back.
 */
export function CellSplitBottomTabs<TNonBottomView extends string>({
  cell,
  currentView,
  editorView,
  contextLabel = "context",
  extraTabs,
  onSelectView,
}: CellSplitBottomTabsProps<TNonBottomView>) {
  const isContextOpen = currentView === "context";
  const isOutputOpen = currentView === "output";
  const showOutputDot = !!(cell.result || cell.error || cell.isRunning);

  const handleToggleContext = () => onSelectView(isContextOpen ? editorView : "context");
  const handleToggleOutput = () => onSelectView(isOutputOpen ? editorView : "output");

  const outputDot = showOutputDot ? (
    <span className={`ml-1 inline-block h-1.5 w-1.5 rounded-full ${runStatusDotClass(cell)}`} />
  ) : null;

  return (
    <div className="order-4 border-t border-border/50 bg-muted/30">
      <div className="flex items-center gap-1 px-4 py-2">
        <SplitBottomTabButton
          isOpen={isContextOpen}
          icon={<FileText className="h-3 w-3 mr-1" />}
          label={contextLabel}
          onClick={handleToggleContext}
        />
        {extraTabs}
        <SplitBottomTabButton
          isOpen={isOutputOpen}
          icon={<Table2 className="h-3 w-3 mr-1" />}
          label="output"
          indicator={outputDot}
          onClick={handleToggleOutput}
        />
      </div>
    </div>
  );
}
