import { Sparkles } from "lucide-react";
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { promptReferenceExtension } from "@/features/concept-editor/components/code-editor/promptReferences";
import { useCellCurlSnippet } from "@/features/concept-editor/hooks/useCellCurlSnippet";
import { useCellDragDrop } from "@/features/concept-editor/hooks/useCellDragDrop";
import {
  useCellRename,
  useConceptRenameCommit,
} from "@/features/concept-editor/hooks/useCellRename";
import { useCellSplitPanes } from "@/features/concept-editor/hooks/useCellSplitPanes";
import { useCellView } from "@/features/concept-editor/hooks/useCellView";
import { usePromptReferences } from "@/features/concept-editor/hooks/usePromptReferences";
import type { LlmConceptConfig } from "@/features/concept-editor/types";
import { AccordionContent } from "@/shared/components/ui/accordion";
import { cn } from "@/shared/lib/utils";
import { CellAccordionShell } from "./components/CellAccordionShell";
import { NonDeterministicBadge } from "./components/CellBadges";
import { CellContextTab } from "./components/CellContextTab";
import CellEditor from "./components/CellEditor";
import { CellHeaderRow } from "./components/CellHeaderRow";
import { CellRenameControl } from "./components/CellRenameControl";
import CellResults from "./components/CellResults";
import { CellSplitBottomTabs } from "./components/CellSplitBottomTabs";
import CellToolbar from "./components/CellToolbar";
import { type CellView, CellViewTabs } from "./components/CellViewTabs";
import { LlmCellConfigPanel } from "./components/LlmCellConfigPanel";
import { PromptInputsStrip } from "./components/PromptInputsStrip";
import { SplitDragHandle } from "./components/SplitDragHandle";
import type { QueryConceptCellProps } from "./types/editorTypes";

interface QueryLlmCellProps extends QueryConceptCellProps {
  onOutputPredicateChange?: (cellId: string, outputPredicate: string) => void;
}

const PROMPT_PLACEHOLDER =
  "Write the prompt for this concept. Reference upstream concepts with " +
  "{{concept_name}} — their output is substituted into the prompt on every run.";

/**
 * Editor cell for an llm concept: the cell body is the prompt template
 * ({{name}} placeholders reference upstream concepts and become input binds on
 * save), with declared output columns and model overrides in the config panel.
 * LLM concepts are non-deterministic — they re-run on every execution.
 */
const QueryLlmCell: React.FC<QueryLlmCellProps> = ({
  cell,
  onRunCell,
  onDeleteCell,
  onClearResults,
  onRestoreResults,
  onSaveCell,
  onStopCell,
  onCodeChange,
  setCells,
  changePage,
  isLoadingPage,
  searchPredicateData,
  clearSearch,
  groupNames,
  onAddCellToGroup,
  onRemoveCellFromGroup,
  onOutputPredicateChange,
  onCellTypeChange,
  onRenameConcept,
  defaultView,
  onViewChange,
  splitLayout,
  editorTheme,
}) => {
  const [open, setOpen] = useState<string>(cell.id);
  const [showSettings, setShowSettings] = useState(false);
  const initialView: CellView =
    defaultView === "context" || defaultView === "output" ? defaultView : "editor";
  const { currentView, setCurrentView } = useCellView<CellView>(cell, initialView);

  // In split layout, propagate currentView changes to the parent so it can
  // persist the bottom panel state. Skip the initial mount.
  const initialViewSyncRef = useRef(true);
  useEffect(() => {
    if (!splitLayout || !onViewChange) return;
    if (initialViewSyncRef.current) {
      initialViewSyncRef.current = false;
      return;
    }
    onViewChange(currentView);
  }, [currentView, splitLayout, onViewChange]);

  const {
    isBottomPanelOpen,
    editorPaneRef,
    bottomPaneRef,
    splitEditorStyle,
    splitBottomFlexStyle,
    editorRatio,
    handleSplitDragStart,
    adjustRatio,
  } = useCellSplitPanes({ splitLayout, currentView, editorView: "editor" });
  const { dropPosition, handleDragOver, handleDragLeave, handleDrop } = useCellDragDrop(cell.id);
  const buildCurlSnippet = useCellCurlSnippet(cell.outputPredicate);
  const rename = useCellRename({
    currentName: cell.outputPredicate,
    onCommit: useConceptRenameCommit({ cell, setCells, onRenameConcept, onOutputPredicateChange }),
  });

  const currentGroup = cell.group && cell.group !== "group_id" ? cell.group : null;

  React.useEffect(() => {
    if (cell.autoOpen) {
      setOpen(cell.id);
      setCells((prev) => prev.map((c) => (c.id === cell.id ? { ...c, autoOpen: false } : c)));
    }
  }, [cell.autoOpen, cell.id, setCells]);

  const handleToggleAccordion = useCallback(() => {
    setOpen((prev) => (prev === cell.id ? "" : cell.id));
  }, [cell.id]);

  const handlePromptChange = useCallback(
    (value: string) => {
      setCells((prev) =>
        prev.map((c) =>
          c.id === cell.id ? { ...c, code: value, isModified: true, needsSave: true } : c,
        ),
      );
      onCodeChange?.(value, cell.id);
    },
    [cell.id, setCells, onCodeChange],
  );

  // Deliberately not the host's `extensions`: those carry the Vadalog grammar,
  // which would syntax-colour ordinary English words. The only marking a prompt
  // wants is over its own references.
  const promptExtensions = useMemo(() => [promptReferenceExtension()], []);
  const { references } = usePromptReferences(cell.id, cell.code, cell.outputPredicate);

  const handleConfigChange = useCallback(
    (patch: Partial<LlmConceptConfig>) => {
      setCells((prev) =>
        prev.map((c) =>
          c.id === cell.id
            ? { ...c, llmConfig: { ...c.llmConfig, ...patch }, isModified: true, needsSave: true }
            : c,
        ),
      );
    },
    [cell.id, setCells],
  );

  const handleDescriptionChange = useCallback(
    (value: string) => {
      setCells((prev) =>
        prev.map((c) =>
          c.id === cell.id ? { ...c, description: value, isModified: true, needsSave: true } : c,
        ),
      );
    },
    [cell.id, setCells],
  );

  const handleToggleSettings = useCallback(() => {
    setShowSettings((prev) => !prev);
  }, []);

  const handleSaveCell = useCallback(
    async (cellId: string) => {
      return onSaveCell?.(cellId);
    },
    [onSaveCell],
  );

  const handleRunCell = useCallback(
    (cellId: string, forceRerun?: boolean) => {
      if (open !== cell.id) setOpen(cell.id);
      if (!cell.outputPredicate?.trim()) {
        toast.error("Please set a concept name before running");
        return;
      }
      if (!cell.code?.trim()) {
        toast.error("Please write a prompt before running");
        return;
      }
      onRunCell?.(cellId, undefined, forceRerun);
    },
    [open, cell.id, cell.outputPredicate, cell.code, onRunCell],
  );

  return (
    <CellAccordionShell
      cellId={cell.id}
      cellBackendId={cell.cellBackendId}
      open={open}
      onOpenChange={setOpen}
      dropPosition={dropPosition}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <CellHeaderRow
        cell={cell}
        isOpen={open === cell.id}
        defaultConceptType="llm"
        onToggle={handleToggleAccordion}
        onCellTypeChange={onCellTypeChange}
        buildCurlSnippet={buildCurlSnippet}
        currentGroup={currentGroup}
        groupNames={groupNames}
        onAddCellToGroup={onAddCellToGroup}
        onRemoveCellFromGroup={onRemoveCellFromGroup}
        identity={
          <CellRenameControl
            name={cell.outputPredicate || ""}
            isRenaming={rename.isRenaming}
            renameValue={rename.renameValue}
            inputRef={rename.inputRef}
            onRenameValueChange={rename.setRenameValue}
            onConfirm={rename.confirm}
            onCancel={rename.cancel}
            onStart={rename.start}
          />
        }
        badges={<NonDeterministicBadge />}
        toolbar={
          <CellToolbar
            cellId={cell.id}
            code={cell.code}
            isRunning={cell.isRunning}
            isCellSaving={cell.isSaving}
            hasResult={!!cell.result || !!cell.error}
            hasPersistedResults={cell.hasPersistedResults || false}
            isModified={cell.isModified}
            onRunCell={handleRunCell}
            onStopCell={onStopCell}
            onDeleteCell={onDeleteCell}
            onClearResults={onClearResults}
            onRestoreResults={onRestoreResults}
            onSaveCell={handleSaveCell}
            onToggleSettings={handleToggleSettings}
            isSettingsActive={showSettings}
            readOnly={cell.readOnly}
          />
        }
      />
      <AccordionContent style={{ overflow: "visible", minWidth: 0 }}>
        <div className="flex flex-col border-t border-border/50">
          {showSettings && (
            <div className="border-b border-border/50 bg-muted/50">
              <LlmCellConfigPanel
                cellId={cell.id}
                config={cell.llmConfig ?? {}}
                disabled={cell.readOnly}
                conceptName={cell.outputPredicate}
                onChange={handleConfigChange}
              />
            </div>
          )}
          <CellViewTabs
            cell={cell}
            currentView={currentView}
            editorLabel="prompt"
            editorIcon={<Sparkles className="h-3 w-3 mr-1" />}
            splitLayout={splitLayout}
            onSelectView={setCurrentView}
          />
          {currentView === "context" && (
            <div
              ref={isBottomPanelOpen ? bottomPaneRef : undefined}
              className={cn(
                "cell-view-pane flex flex-col px-4",
                splitLayout && "order-5 min-h-0 overflow-auto",
              )}
              style={splitBottomFlexStyle}
            >
              <CellContextTab
                description={cell.description || ""}
                onDescriptionChange={handleDescriptionChange}
                onSaveShortcut={() => handleSaveCell(cell.id)}
                cellBackendId={cell.cellBackendId}
                conceptName={cell.outputPredicate || ""}
                descriptionPlaceholder="Describe what this LLM concept extracts or generates..."
              />
            </div>
          )}
          {currentView === "output" && (
            <div
              ref={isBottomPanelOpen ? bottomPaneRef : undefined}
              className={cn(
                "cell-view-pane w-full overflow-x-auto",
                splitLayout && "order-5 min-h-0 overflow-auto",
              )}
              style={{ maxWidth: "100%", ...splitBottomFlexStyle }}
            >
              <CellResults
                cell={cell}
                setCells={setCells}
                changePage={changePage}
                isLoadingPage={isLoadingPage}
                searchPredicateData={searchPredicateData}
                clearSearch={clearSearch}
              />
            </div>
          )}
          {/* The prompt is this cell's body, so it fills the panel exactly like
              the code editor in the Vadalog/Python cells: the `cell-editor-pane`
              hook is what the host layouts in code-editor.css size to the
              remaining height. `flex-1 min-h-0` is repeated here because only
              the lineage host sets `flex: 1` in CSS, and the min-height keeps a
              usable box in an auto-height context. In split layout the pane
              stays mounted and `splitEditorStyle` sizes it against the bottom
              panel. */}
          <div
            ref={isBottomPanelOpen ? editorPaneRef : undefined}
            className={cn(
              "cell-editor-pane flex min-h-0 flex-1 flex-col",
              splitLayout && "order-2",
            )}
            style={splitEditorStyle}
          >
            <div className="min-h-0 flex-1">
              <CellEditor
                code={cell.code}
                cellId={cell.id}
                isRunning={cell.isRunning}
                extensions={promptExtensions}
                editorTheme={editorTheme}
                onCodeChange={handlePromptChange}
                onRunCell={handleRunCell}
                onSaveCell={handleSaveCell}
                placeholder={PROMPT_PLACEHOLDER}
                onToggleMinimize={handleToggleAccordion}
                fillHeight={splitLayout}
                readOnly={cell.readOnly || cell.isSaving}
                proseBody
              />
            </div>
            {/* Inside the editor pane, not beside it: as a sibling it would
                carry no `order` and jump above the editor in the split layout,
                where every pane is explicitly ordered. */}
            <PromptInputsStrip
              references={references}
              lastRunInputs={cell.llmInputs}
              lastRunTruncation={cell.llmTruncation}
            />
          </div>
          {isBottomPanelOpen && (
            <SplitDragHandle
              className="order-3"
              onMouseDown={handleSplitDragStart}
              onAdjust={adjustRatio}
              editorPercent={editorRatio * 100}
            />
          )}
          {splitLayout && (
            <CellSplitBottomTabs
              cell={cell}
              currentView={currentView}
              editorView="editor"
              onSelectView={setCurrentView}
            />
          )}
        </div>
      </AccordionContent>
    </CellAccordionShell>
  );
};

export default QueryLlmCell;
