import { BookOpen, ChevronDown, ChevronRight } from "lucide-react";
import { useState } from "react";

import { cn } from "@/shared/lib/utils";

import type { ContextLoadedData } from "../store";

interface ContextLoadedChipProps {
  data: ContextLoadedData;
}

export function ContextLoadedChip({ data }: ContextLoadedChipProps) {
  const [expanded, setExpanded] = useState(false);
  const toggle = () => setExpanded((prev) => !prev);
  const label = `Consulted ${data.count} note${data.count === 1 ? "" : "s"}`;

  return (
    <div className="rounded-lg border border-border bg-card px-3 py-2 text-xs shadow-sm">
      <button
        type="button"
        onClick={toggle}
        className="flex w-full items-center gap-2 text-left text-muted-foreground hover:text-foreground"
      >
        <BookOpen className="h-3.5 w-3.5" />
        <span className="font-medium">{label}</span>
        {expanded ? (
          <ChevronDown className="ml-auto h-3.5 w-3.5" />
        ) : (
          <ChevronRight className="ml-auto h-3.5 w-3.5" />
        )}
      </button>
      {expanded && data.notes.length > 0 && (
        <ul className="mt-2 space-y-1.5">
          {data.notes.map((note) => (
            <li key={note.id} className="flex items-start gap-1.5">
              <span
                className={cn(
                  "mt-0.5 inline-flex items-center rounded px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide",
                  note.scope === "global"
                    ? "bg-muted text-muted-foreground"
                    : "bg-primary/10 text-primary",
                )}
              >
                {note.kind}
              </span>
              <span className="flex-1 text-foreground/80">{note.preview}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
