import type React from "react";
import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import {
  DatabricksConfigService,
  DatabricksService,
} from "@/features/compute/api/databricksService";
import { MachineClient } from "@/features/compute/api/MachineClient";
import { useComputeMachines } from "@/features/compute/hooks/useComputeMachines";
import { useMachineStatus } from "@/features/compute/hooks/useMachineStatus";
import { useMachineStatusStream } from "@/features/compute/hooks/useMachineStatusStream";
import type { DatabricksCluster } from "@/features/compute/types";
import type { AvailabilityResult, Machine, UserMachine } from "@/features/compute/utils";

interface MachineStatusContextValue {
  // Data
  userMachines: UserMachine[];
  disabledUserMachines: UserMachine[];
  catalogMachines: Machine[];
  availabilityResults: Record<string, AvailabilityResult>; // keyed by machineId
  checkingAvailability: Record<string, boolean>; // keyed by machineId
  loadingMachines: boolean;
  hasMachinesLoaded: boolean;
  // Derived
  hasRunningMachine: boolean;
  stoppedMachines: UserMachine[];
  notRunningMachines: UserMachine[]; // stopped + starting/pending/restarting
  // The machine that we explicitly requested to start (null when none in progress)
  startingMachineId: string | null;
  // Databricks clusters
  databricksClusters: DatabricksCluster[];
  loadingDatabricksClusters: boolean;
  // Actions
  fetchAllMachines: () => Promise<void>;
  fetchDatabricksClusters: () => Promise<void>;
  autoSelectRunningCompute: () => void;
  checkMachineStatus: (
    machineId: string,
    userMachineId: string,
  ) => Promise<
    "started" | "stopped" | "stopping" | "pending" | "starting" | "crashed" | "restarting"
  >;
  startMachine: (userMachineId: string, machineId: string) => Promise<void>;
  addAndStartMachine: (catalogMachineId: string, catalogMachineName: string) => Promise<void>;
  startDatabricksCluster: (clusterId: string) => Promise<void>;
}

const MachineStatusContext = createContext<MachineStatusContextValue | null>(null);

export const MachineStatusProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const {
    userMachines,
    setUserMachines,
    disabledUserMachines,
    machines: catalogMachines,
    loadingMachines,
    fetchAllMachines,
    loadCount,
  } = useComputeMachines();
  const hasMachinesLoaded = loadCount > 0;

  const { availabilityResults, setAvailabilityResults, checkingAvailability, checkMachineStatus } =
    useMachineStatus(userMachines, setUserMachines, loadCount);

  const { startStream: startStatusStream } = useMachineStatusStream(
    setAvailabilityResults,
    setUserMachines,
    checkMachineStatus,
  );

  const machineClientRef = useRef(new MachineClient());
  const databricksClusterPollRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Tracks the machine we deliberately started so background polls can't overwrite its status
  const startingMachineIdRef = useRef<string | null>(null);
  const [startingMachineId, setStartingMachineId] = useState<string | null>(null);

  // Databricks config — kept in sync with localStorage so we can check cluster state
  const [databricksConfig, setDatabricksConfig] = useState(() =>
    DatabricksConfigService.getConfig(),
  );
  useEffect(() => {
    const handleStorage = () => setDatabricksConfig(DatabricksConfigService.getConfig());
    window.addEventListener("storage", handleStorage);
    window.addEventListener("databricksConfigChanged", handleStorage);
    return () => {
      window.removeEventListener("storage", handleStorage);
      window.removeEventListener("databricksConfigChanged", handleStorage);
    };
  }, []);

  // Databricks clusters list
  const [databricksClusters, setDatabricksClusters] = useState<DatabricksCluster[]>([]);
  const [loadingDatabricksClusters, setLoadingDatabricksClusters] = useState(false);
  // Prevent concurrent fetches
  const fetchingDatabricksClustersRef = useRef(false);

  // useCallback: reads config fresh each call, uses only refs + stable setters — no deps needed.
  const fetchDatabricksClusters = useCallback(async () => {
    const config = DatabricksConfigService.getConfig();
    if (!config.workspaceUrl || fetchingDatabricksClustersRef.current) return;
    fetchingDatabricksClustersRef.current = true;
    setLoadingDatabricksClusters(true);
    try {
      const service = new DatabricksService();
      const clusters = await service.listClusters(config.authMode);
      setDatabricksClusters(clusters || []);
    } catch {
      setDatabricksClusters([]);
    } finally {
      setLoadingDatabricksClusters(false);
      fetchingDatabricksClustersRef.current = false;
    }
  }, []);

  // Load clusters on mount and whenever the workspace URL changes.
  useEffect(() => {
    if (databricksConfig.workspaceUrl) {
      fetchDatabricksClusters();
    } else {
      setDatabricksClusters([]);
    }
  }, [databricksConfig.workspaceUrl, fetchDatabricksClusters]);

  // Re-sync when a machine is explicitly started/stopped on the Compute Management page.
  // Visibility-change auto-refresh is intentionally omitted — status checks are on-demand
  // (via the refresh button in the compute dropdown) to avoid N API calls on every tab switch.
  useEffect(() => {
    const refresh = () => {
      fetchAllMachines();
      fetchDatabricksClusters();
    };
    window.addEventListener("machineStateChanged", refresh);
    return () => {
      window.removeEventListener("machineStateChanged", refresh);
    };
  }, [fetchAllMachines, fetchDatabricksClusters]);

  // Clear the startingMachineId guard once the WebSocket stream confirms the machine is up.
  // Previously this effect also re-asserted "starting" when polls returned "stopped", but
  // that caused an infinite loop: setAvailabilityResults → availabilityResults changes →
  // effect re-runs. With streaming, the WebSocket is the authoritative status source and
  // no re-assertion is needed.
  useEffect(() => {
    const id = startingMachineIdRef.current;
    if (!id) return;
    if (availabilityResults[id]?.machine_status === "started") {
      startingMachineIdRef.current = null;
      setStartingMachineId(null);
    }
  }, [availabilityResults]);

  // is_active is the primary signal (set by the user's explicit toggle action on the Compute
  // Management page). Pod status check is secondary and can lag — e.g. a stopped pod may still
  // report 'started' for a few seconds while it winds down.
  const hasInternalRunningMachine = userMachines.some(
    (um) =>
      um.machines &&
      (um.is_active || availabilityResults[um.machines.id]?.machine_status === "started"),
  );
  // Prefer live cluster data from API; fall back to stored defaultCluster while clusters are still loading
  const hasDatabricksRunning =
    databricksClusters.some((c) => c.state === "RUNNING") ||
    (databricksClusters.length === 0 && databricksConfig.defaultCluster?.state === "RUNNING");
  const hasRunningMachine = hasInternalRunningMachine || hasDatabricksRunning;

  const stoppedMachines = userMachines.filter((um) => {
    if (!um.machines) return false;
    const result = availabilityResults[um.machines.id];
    if (result?.machine_status) return result.machine_status === "stopped";
    return !um.is_active;
  });

  // All machines that are not yet running — stopped + any transitional state
  const notRunningMachines = userMachines.filter((um) => {
    if (!um.machines) return false;
    const status = availabilityResults[um.machines.id]?.machine_status;
    return !status || status !== "started";
  });

  const startMachine = async (userMachineId: string, machineId: string) => {
    startingMachineIdRef.current = machineId;
    setStartingMachineId(machineId);

    setUserMachines((prev) =>
      prev.map((um) => (um.id === userMachineId ? { ...um, is_active: true } : um)),
    );
    setAvailabilityResults((prev) => ({
      ...prev,
      [machineId]: {
        status: "success",
        message: "Machine starting...",
        machine_status: "starting",
        is_available: false,
      },
    }));

    // Pre-select this machine so ComputeIndicator shows it immediately
    localStorage.setItem("selectedCompute", "pools");
    localStorage.setItem("selectedMachineId", machineId);
    window.dispatchEvent(new Event("storage"));

    await machineClientRef.current.toggleMachineActive(userMachineId, true);

    // Subscribe to real-time status updates via SSE
    startStatusStream(userMachineId, machineId);
  };

  const addAndStartMachine = async (catalogMachineId: string, catalogMachineName: string) => {
    const resp = await machineClientRef.current.useMachine(catalogMachineId, catalogMachineName);
    if (resp.status === "error" || !resp.data?.user_machine) {
      throw new Error(resp.message || "Failed to provision machine");
    }
    const um = resp.data.user_machine;
    setUserMachines((prev) => (prev.some((m) => m.id === um.id) ? prev : [...prev, um]));
    await startMachine(um.id, catalogMachineId);
  };

  const startDatabricksCluster = async (clusterId: string) => {
    if (databricksClusterPollRef.current) clearTimeout(databricksClusterPollRef.current);

    // Optimistically mark as PENDING so the modal shows it as starting
    setDatabricksClusters((prev) =>
      prev.map((c) => (c.cluster_id === clusterId ? { ...c, state: "PENDING" as const } : c)),
    );

    // Pre-select this cluster in ComputeIndicator
    const config = DatabricksConfigService.getConfig();
    const cluster = databricksClusters.find((c) => c.cluster_id === clusterId);
    if (cluster) {
      DatabricksConfigService.saveConfig({
        ...config,
        defaultClusterId: clusterId,
        defaultCluster: cluster,
      });
      setDatabricksConfig(DatabricksConfigService.getConfig());
      localStorage.setItem("selectedCompute", "databricks");
      window.dispatchEvent(new Event("storage"));
      window.dispatchEvent(new Event("databricksConfigChanged"));
    }

    const service = new DatabricksService();
    await service.startCluster(clusterId);

    // Poll until RUNNING or terminal error state (max ~10 min, every 10 s)
    let attempts = 0;
    const poll = async () => {
      try {
        const currentConfig = DatabricksConfigService.getConfig();
        const updated = await service.getCluster(clusterId, currentConfig.authMode);
        setDatabricksClusters((prev) =>
          prev.map((c) => (c.cluster_id === clusterId ? updated : c)),
        );
        // Sync defaultCluster in localStorage if this is the configured cluster
        if (currentConfig.defaultClusterId === clusterId) {
          DatabricksConfigService.saveConfig({ ...currentConfig, defaultCluster: updated });
          setDatabricksConfig(DatabricksConfigService.getConfig());
          window.dispatchEvent(new Event("storage"));
          window.dispatchEvent(new Event("databricksConfigChanged"));
        }
        attempts++;
        if (updated.state !== "RUNNING" && updated.state !== "ERROR" && attempts < 60) {
          databricksClusterPollRef.current = setTimeout(poll, 10000);
        }
      } catch {
        attempts++;
        if (attempts < 60) {
          databricksClusterPollRef.current = setTimeout(poll, 10000);
        }
      }
    };
    databricksClusterPollRef.current = setTimeout(poll, 10000);
  };

  // Picks the first available running machine/cluster and writes it to localStorage so
  // the execution backend knows which compute to target.
  const autoSelectRunningCompute = () => {
    // Internal pool machines take priority.
    // Use confirmed 'started' status first; fall back to is_active:true before the status poll runs.
    // is_active is the authoritative signal (reflects the user's explicit toggle action).
    // Pod status can lag — a recently stopped machine may still report 'started' briefly.
    const runningMachine = userMachines.find((um) => um.machines && um.is_active);
    if (runningMachine?.machines) {
      localStorage.setItem("selectedCompute", "pools");
      localStorage.setItem("selectedMachineId", runningMachine.machines.id);
      window.dispatchEvent(new Event("storage"));
      return;
    }

    // Then Databricks clusters from live data
    const runningCluster = databricksClusters.find((c) => c.state === "RUNNING");
    if (runningCluster) {
      const config = DatabricksConfigService.getConfig();
      DatabricksConfigService.saveConfig({
        ...config,
        defaultClusterId: runningCluster.cluster_id,
        defaultCluster: runningCluster,
      });
      setDatabricksConfig(DatabricksConfigService.getConfig());
      localStorage.setItem("selectedCompute", "databricks");
      window.dispatchEvent(new Event("storage"));
      window.dispatchEvent(new Event("databricksConfigChanged"));
    }
  };

  return (
    <MachineStatusContext.Provider
      value={{
        userMachines,
        disabledUserMachines,
        catalogMachines,
        availabilityResults,
        checkingAvailability,
        loadingMachines,
        hasMachinesLoaded,
        hasRunningMachine,
        stoppedMachines,
        notRunningMachines,
        startingMachineId,
        databricksClusters,
        loadingDatabricksClusters,
        fetchAllMachines,
        fetchDatabricksClusters,
        autoSelectRunningCompute,
        checkMachineStatus,
        startMachine,
        addAndStartMachine,
        startDatabricksCluster,
      }}
    >
      {children}
    </MachineStatusContext.Provider>
  );
};

export const useMachineStatusContext = (): MachineStatusContextValue => {
  const ctx = useContext(MachineStatusContext);
  if (!ctx) throw new Error("useMachineStatusContext must be used within MachineStatusProvider");
  return ctx;
};
