import { Search } from "lucide-react";
import { Fragment, type ReactNode, useMemo, useState } from "react";
import { Input } from "@/shared/components/ui/input";

export interface RosterSectionItem {
  key: string;
  // Pre-lowercased text used for client-side filtering (label + any hint).
  searchText: string;
  node: ReactNode;
}

interface RosterMemberSectionProps {
  title: string;
  items: RosterSectionItem[];
  // Rendered above the scrollable list and never filtered — e.g. the owner
  // "full access" row, which should always stay visible.
  leading?: ReactNode;
  // The search box appears once the list grows past this many items.
  searchThreshold?: number;
  // Empty-state copy when the roster has no rows at all (no leading either).
  emptyLabel?: string;
}

// Members can grow large, so the roster's people list gets a count, a search
// box (only once it's long enough to warrant one) and a bounded scroll area.
// Teams stay in their own always-visible section — this is people-only.
const RosterMemberSection: React.FC<RosterMemberSectionProps> = ({
  title,
  items,
  leading,
  searchThreshold = 6,
  emptyLabel,
}) => {
  const [query, setQuery] = useState("");

  const showSearch = items.length > searchThreshold;

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return items;
    return items.filter((item) => item.searchText.includes(q));
  }, [items, query]);

  const handleQueryChange = (event: React.ChangeEvent<HTMLInputElement>): void => {
    setQuery(event.target.value);
  };

  const isEmpty = !leading && items.length === 0;

  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex items-center justify-between px-0.5">
        <p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
          {title}
        </p>
        {items.length > 0 && (
          <span className="text-[11px] tabular-nums text-muted-foreground">{items.length}</span>
        )}
      </div>

      {showSearch && (
        <div className="relative">
          <Search className="pointer-events-none absolute left-2 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={query}
            onChange={handleQueryChange}
            placeholder="Search people…"
            className="h-8 pl-7 text-xs"
          />
        </div>
      )}

      {leading}

      {isEmpty ? (
        emptyLabel && <p className="px-1 py-2 text-xs text-muted-foreground">{emptyLabel}</p>
      ) : (
        <div className="flex max-h-64 flex-col gap-1 overflow-y-auto pr-0.5">
          {filtered.map((item) => (
            <Fragment key={item.key}>{item.node}</Fragment>
          ))}
          {showSearch && filtered.length === 0 && (
            <p className="px-1 py-2 text-xs text-muted-foreground">
              No people match “{query.trim()}”.
            </p>
          )}
        </div>
      )}
    </div>
  );
};

export default RosterMemberSection;
