import type { Edge, Node as FlowNode } from "@xyflow/react";
import {
  type Dispatch,
  type MutableRefObject,
  type SetStateAction,
  useCallback,
  useEffect,
  useMemo,
  useRef,
} from "react";
import type { ConceptCardCustomData } from "@/features/ontology-schema/types";
import { layoutElements } from "../components/lineage-view/lineage.utils";

type ConceptNode = FlowNode<ConceptCardCustomData>;

/** Minimal slice of the ReactFlow instance this hook needs. */
interface FlowFitView {
  fitView: (options?: { padding?: number; duration?: number }) => void;
}

interface UseExpandCollapseAllParams {
  nodes: ConceptNode[];
  setNodes: Dispatch<SetStateAction<ConceptNode[]>>;
  baseEdgesRef: MutableRefObject<Edge[]>;
  reactFlowInstance: MutableRefObject<FlowFitView | null>;
  skipAutoFitViewRef: MutableRefObject<boolean>;
}

interface UseExpandCollapseAllReturn {
  /** True when every concept card is expanded — drives the toggle icon. */
  allCardsExpanded: boolean;
  /** Expand or collapse all concept cards at once, then re-layout and re-fit. */
  toggleAllCards: () => void;
  /**
   * Labels of currently-expanded concept cards, mirrored from node data. Read
   * during a lineage refresh to re-apply expansion (a refresh rebuilds nodes
   * collapsed by default).
   */
  expandedLabelsRef: MutableRefObject<Set<string>>;
}

const isConcept = (n: ConceptNode): boolean => n.data.nodeType !== "datasource";

const everyConceptExpanded = (nodes: ConceptNode[]): boolean => {
  const concepts = nodes.filter(isConcept);
  return concepts.length > 0 && concepts.every((n) => !!n.data.isExpanded);
};

/**
 * Drives the "expand/collapse all cards" control on the lineage canvas. The
 * expanded flag lives on each node's data so the change reaches the (otherwise
 * locally-stateful) cards; flipping it changes card height, so we re-run the
 * dagre layout to avoid overlaps and re-fit the view.
 */
export function useExpandCollapseAll({
  nodes,
  setNodes,
  baseEdgesRef,
  reactFlowInstance,
  skipAutoFitViewRef,
}: UseExpandCollapseAllParams): UseExpandCollapseAllReturn {
  const allCardsExpanded = useMemo(() => everyConceptExpanded(nodes), [nodes]);

  // Mirror expanded labels so a refresh (which rebuilds nodes) can restore them.
  const expandedLabelsRef = useRef<Set<string>>(new Set());
  useEffect(() => {
    expandedLabelsRef.current = new Set(
      nodes.filter((n) => isConcept(n) && n.data.isExpanded).map((n) => n.data.label),
    );
  }, [nodes]);

  const toggleAllCards = useCallback(() => {
    setNodes((nds) => {
      const next = !everyConceptExpanded(nds);
      const updated = nds.map((n) =>
        isConcept(n) ? { ...n, data: { ...n.data, isExpanded: next } } : n,
      );
      const { nodes: laid } = layoutElements(updated, baseEdgesRef.current);
      return laid;
    });
    skipAutoFitViewRef.current = true;
    setTimeout(() => reactFlowInstance.current?.fitView({ padding: 0.15, duration: 300 }), 80);
  }, [setNodes, baseEdgesRef, reactFlowInstance, skipAutoFitViewRef]);

  return { allCardsExpanded, toggleAllCards, expandedLabelsRef };
}
