import { Navigate } from "react-router-dom";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";

interface RequirePermissionProps {
  permissionKey: string;
  children: React.ReactNode;
  redirectTo?: string;
}

export function RequirePermission({ permissionKey, children, redirectTo }: RequirePermissionProps) {
  const loaded = usePermissionsStore((state) => state.loaded);
  const canSee = usePermissionsStore((state) => state.canSee);
  const defaultRoute = usePermissionsStore((state) => state.defaultRoute);

  if (!loaded || canSee(permissionKey)) return <>{children}</>;
  // Redirect to the caller-provided fallback, otherwise the user's first
  // accessible page. Hard-coding "/" would loop when the home page itself
  // is permission-gated and the user lacks that permission.
  return <Navigate to={redirectTo ?? defaultRoute ?? "/"} replace />;
}
