import { Component, X } from "lucide-react";
import type { FocusedWidgetRef } from "../agentContext";

interface FocusedWidgetChipProps {
  widget: FocusedWidgetRef;
  onClear: () => void;
}

/**
 * Shows the widget reference queued for the next message (set by the app
 * editor's "Ask AI about this widget"). Sent once, then cleared.
 */
export function FocusedWidgetChip({ widget, onClear }: FocusedWidgetChipProps) {
  return (
    <div className="flex items-center gap-1.5 self-start rounded-md border border-border bg-secondary px-2 py-1">
      <Component className="h-3 w-3 text-muted-foreground flex-shrink-0" />
      <span className="text-[11px] truncate">
        {widget.widgetId}
        <span className="text-muted-foreground">
          {" "}
          · {widget.widgetType} · {widget.pageLabel}
        </span>
      </span>
      <button
        type="button"
        title="Remove widget reference"
        onClick={onClear}
        className="p-0.5 text-muted-foreground hover:text-foreground flex-shrink-0"
      >
        <X className="h-3 w-3" />
      </button>
    </div>
  );
}
