import { Inbox, RefreshCw } from "lucide-react";
import type React from "react";
import { useCallback, useMemo } from "react";
import OntologyList from "@/features/ontologies/components/OntologyList";
import { useShareInbox } from "@/features/ontologies/sharing/hooks/useShareInbox";
import { buildSharedTabList } from "@/features/ontologies/sharing/utils/sharing.utils";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

interface SharedOntologiesTabProps {
  onOpenOntology: (ontologyId: string, ontologyName: string) => void;
  openingOntologyId: string | null;
}

// Renders the "Shared with me" tab of the Projects page. Owns the inbox fetch
// and accept/leave wiring; ProjectList does the layout. Pending invitations and
// accepted shares come back through buildSharedTabList as ProjectData rows so
// the grid is uniform — ProjectList branches on shareStatus to swap in a
// PendingShareCard when needed.
const SharedOntologiesTab: React.FC<SharedOntologiesTabProps> = ({
  onOpenOntology,
  openingOntologyId,
}) => {
  const { entries, isLoading, isFetching, refresh, accept, leave, claim, error } = useShareInbox();

  const sharedOntologies = useMemo(() => buildSharedTabList(entries), [entries]);

  const handleAccept = useCallback(
    async (shareId: string): Promise<void> => {
      await accept(shareId);
    },
    [accept],
  );

  const handleLeave = useCallback(
    async (shareId: string): Promise<void> => {
      await leave(shareId);
    },
    [leave],
  );

  const handleClaim = useCallback(
    async (shareId: string): Promise<void> => {
      await claim(shareId);
    },
    [claim],
  );

  const handleRefresh = useCallback(() => {
    refresh();
  }, [refresh]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <PrometheuxSpinner size={36} label="Loading shared ontologies..." />
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center gap-3 py-12 text-center">
        <p className="text-sm text-destructive">{error.message}</p>
        <Button type="button" variant="outline" size="sm" onClick={handleRefresh}>
          <RefreshCw className="h-4 w-4 mr-2" />
          Try again
        </Button>
      </div>
    );
  }

  if (sharedOntologies.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center gap-3 py-16 text-center">
        <div className="flex h-12 w-12 items-center justify-center rounded-full bg-secondary">
          <Inbox className="h-5 w-5 text-muted-foreground" />
        </div>
        <div>
          <p className="text-sm font-medium text-foreground">No shared ontologies yet</p>
          <p className="mt-1 text-xs text-muted-foreground">
            When someone shares a project with you, it'll show up here.
          </p>
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleRefresh}
          disabled={isFetching}
        >
          <RefreshCw className={`h-4 w-4 mr-2 ${isFetching ? "animate-spin" : ""}`} />
          Refresh
        </Button>
      </div>
    );
  }

  return (
    <OntologyList
      projects={sharedOntologies}
      onOpenOntology={onOpenOntology}
      onAcceptShare={handleAccept}
      onLeaveShare={handleLeave}
      onClaimShare={handleClaim}
      openingOntologyId={openingOntologyId}
    />
  );
};

export default SharedOntologiesTab;
