import { FolderOpen, Play, Plus, X } from "lucide-react";
import type React from "react";
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { type OntologyData, OntologyService } from "@/features/ontologies/api";
import { setCurrentOntologyId, setCurrentOntologyScope } from "@/features/ontologies/utils";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";
import { generateEditorUrl } from "@/shared/utils/navigationUtils";

interface RunDataSourceModalProps {
  isOpen: boolean;
  onClose: () => void;
  bindAnnotation: string;
  tableName?: string;
  fields?: Record<string, string>;
}

function extractInputPredicate(bindAnnotation: string): string | null {
  const match = bindAnnotation.match(/@(?:bind|qbind)\("([^"]+)"/);
  return match ? match[1] : null;
}

const FILE_EXTENSIONS = new Set([
  "csv",
  "parquet",
  "json",
  "xlsx",
  "xls",
  "tsv",
  "txt",
  "orc",
  "avro",
  "ttl",
  "rdf",
  "owl",
  "yaml",
  "yml",
  "cobol",
  "cob",
  "cbl",
]);

function extractSavedConceptName(saveResponse: unknown, fallback: string): string {
  const normalizedFallback = fallback.trim().toLowerCase();
  if (typeof saveResponse !== "object" || saveResponse === null) return normalizedFallback;
  const data = (saveResponse as { data?: unknown }).data;
  if (typeof data !== "object" || data === null) return normalizedFallback;
  const id = (data as { id?: unknown }).id;
  return typeof id === "string" && id.length > 0 ? id : normalizedFallback;
}

function getConceptNameFromTableName(tableName: string): string {
  const parts = tableName.split(".");
  const last = parts[parts.length - 1];
  if (FILE_EXTENSIONS.has(last.toLowerCase()) && parts.length >= 2) {
    return parts[parts.length - 2].replace(/[^a-zA-Z0-9_]/g, "_");
  }
  return last.replace(/[^a-zA-Z0-9_]/g, "_");
}

function generateConceptCode(
  bindAnnotation: string,
  tableName: string | undefined,
  fields: Record<string, string> | undefined,
): { code: string; conceptName: string } | null {
  const inputPredicate = extractInputPredicate(bindAnnotation);
  if (!inputPredicate) return null;

  const rawOutput = tableName ? getConceptNameFromTableName(tableName) : `${inputPredicate}_view`;
  const outputPredicate = rawOutput === inputPredicate ? `${rawOutput}_view` : rawOutput;

  const fieldKeys = fields ? Object.keys(fields) : [];
  const columns = fieldKeys.join(",");

  const body =
    fieldKeys.length > 0
      ? `${outputPredicate}(${columns}) :-\n  ${inputPredicate}(${columns}).`
      : `${outputPredicate}() :-\n  ${inputPredicate}().`;

  const code = `@post("${outputPredicate}","orderby(1)").\n\n${body}`;
  return { code, conceptName: outputPredicate };
}

const RunDataSourceModal: React.FC<RunDataSourceModalProps> = ({
  isOpen,
  onClose,
  bindAnnotation,
  tableName,
  fields,
}) => {
  const { user } = useAuth();
  const navigate = useNavigate();

  const [projects, setOntologies] = useState<OntologyData[]>([]);
  const [isLoadingOntologies, setIsLoadingOntologies] = useState(false);
  const [selectedOntologyId, setSelectedOntologyId] = useState<string | null>(null);
  const [isCreatingNew, setIsCreatingNew] = useState(false);
  const [newOntologyName, setNewOntologyName] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!isOpen) return;
    setIsLoadingOntologies(true);
    setSelectedOntologyId(null);
    setIsCreatingNew(false);
    setNewOntologyName("");
    setError(null);
    OntologyService.listOntologies(["user"])
      .then(setOntologies)
      .catch(() => setOntologies([]))
      .finally(() => setIsLoadingOntologies(false));
  }, [isOpen]);

  const sourceDisplayName = tableName || extractInputPredicate(bindAnnotation) || "Data Source";
  const generated = generateConceptCode(bindAnnotation, tableName, fields);

  const handleConfirm = async () => {
    if (!generated) {
      setError("Unable to generate concept code from this data source.");
      return;
    }
    if (!isCreatingNew && !selectedOntologyId) {
      setError("Please select an ontology or create a new one.");
      return;
    }
    if (isCreatingNew && !newOntologyName.trim()) {
      setError("Please enter an ontology name.");
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      let ontologyId: string;
      if (isCreatingNew) {
        const ontologyData = await OntologyService.createOntology(newOntologyName.trim());
        ontologyId = ontologyData.id;
      } else {
        ontologyId = selectedOntologyId!;
      }

      setCurrentOntologyId(ontologyId);
      setCurrentOntologyScope("user");

      const inputPredicate = extractInputPredicate(bindAnnotation) || "";
      const bindAnnotationWithDot = bindAnnotation.trimEnd().endsWith(".")
        ? bindAnnotation
        : `${bindAnnotation}.`;

      const saveResponse = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/save`,
        {
          position: 0,
          definition: generated.code,
          binds: {
            input: [{ predicate: inputPredicate, annotation: bindAnnotationWithDot }],
            output: [],
          },
          output_predicate: generated.conceptName,
          concept_type: "logic",
          group: "group_id",
          scope: "user",
        },
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      if (saveResponse?.status === "error") {
        throw new Error(saveResponse.message || "Failed to save concept");
      }

      // Ask the lineage view to focus the concept we just created once it
      // mounts for this project. The backend lowercases predicate names on
      // save, so we use the canonical name it returns (LineageView matches the
      // node label and cell output predicate exactly, case-sensitively).
      const savedConceptName = extractSavedConceptName(saveResponse, generated.conceptName);
      useEditorActionsStore.getState().register({ pendingLineageFocus: savedConceptName });

      onClose();
      navigate(generateEditorUrl(user, ontologyId), { state: { activeTab: "lineage" } });
    } catch (err: any) {
      setError(err?.message || "Something went wrong. Please try again.");
      setIsSubmitting(false);
    }
  };

  const canConfirm = !isSubmitting && (!!selectedOntologyId || isCreatingNew);

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && !isSubmitting && onClose()}>
      <DialogContent className="p-0 sm:max-w-[460px] overflow-hidden [&>button:last-child]:hidden">
        <DialogTitle className="sr-only">Run Data Source</DialogTitle>
        {/* Green header */}
        <div
          style={{ background: "#00e382", padding: "12px 20px" }}
          className="flex items-center justify-between border-b border-border"
        >
          <div className="flex items-center gap-2">
            <Play className="h-4 w-4 text-[#212020]" />
            <h2 className="text-base font-bold text-[#212020]">Run Data Source</h2>
          </div>
          <button
            onClick={onClose}
            className="flex items-center justify-center h-6 w-6 rounded-full hover:bg-black/10 transition-colors"
            aria-label="Close"
            disabled={isSubmitting}
          >
            <X className="h-4 w-4 text-[#212020]" />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 bg-card">
          <p className="text-sm mb-1">
            <span className="font-mono font-medium">{sourceDisplayName}</span> will be added to the
            selected project as a concept ready to execute.
          </p>
          {generated && (
            <p className="text-xs text-muted-foreground mb-5">
              Concept:{" "}
              <span className="font-mono bg-muted px-1 rounded">{generated.conceptName}</span>
            </p>
          )}

          <p className="text-sm font-semibold mb-2">Select an ontology</p>

          {isLoadingOntologies ? (
            <div className="flex items-center justify-center py-8">
              <PrometheuxSpinner size={36} />
            </div>
          ) : (
            <div
              className="mb-3 border border-border rounded overflow-hidden"
              style={{ maxHeight: "180px", overflowY: "auto" }}
            >
              {projects.length === 0 ? (
                <p className="text-xs text-muted-foreground text-center py-4 px-3">
                  No projects yet — create one below.
                </p>
              ) : (
                projects.map((project) => (
                  <button
                    key={project.id}
                    onClick={() => {
                      setSelectedOntologyId(project.id);
                      setIsCreatingNew(false);
                    }}
                    className={`w-full text-left px-3 py-2 text-sm flex items-center gap-2 transition-colors border-b border-border last:border-b-0 ${
                      selectedOntologyId === project.id && !isCreatingNew
                        ? "bg-[#00e382] text-[#212020]"
                        : "hover:bg-accent"
                    }`}
                  >
                    <FolderOpen className="h-3.5 w-3.5 flex-shrink-0 text-muted-foreground" />
                    <span className="truncate">{project.name || project.id}</span>
                  </button>
                ))
              )}
            </div>
          )}

          {/* New project toggle */}
          <button
            onClick={() => {
              setIsCreatingNew(true);
              setSelectedOntologyId(null);
            }}
            className={`w-full text-left px-3 py-2 text-sm flex items-center gap-2 rounded transition-colors ${
              isCreatingNew
                ? "bg-[#00e382] text-[#212020] border border-[#212020]"
                : "border border-dashed border-border hover:border-foreground"
            }`}
          >
            <Plus className="h-3.5 w-3.5 flex-shrink-0" />
            <span>New ontology</span>
          </button>

          {isCreatingNew && (
            <input
              autoFocus
              type="text"
              placeholder="Ontology name"
              value={newOntologyName}
              onChange={(e) => setNewOntologyName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleConfirm()}
              className="mt-2 w-full px-3 py-2 text-sm rounded-md border border-border bg-background text-foreground outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
            />
          )}

          {error && <p className="mt-3 text-xs text-destructive">{error}</p>}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-2 px-6 pb-6 pt-4 bg-card border-t border-border">
          <Button variant="outline" size="sm" onClick={onClose} disabled={isSubmitting}>
            Cancel
          </Button>
          <Button
            size="sm"
            onClick={handleConfirm}
            disabled={!canConfirm}
            style={{
              background: "#00e382",
              color: "#212020",
              border: "1px solid #212020",
              boxShadow: canConfirm ? "2px 2px 0 0 #212020" : "none",
            }}
          >
            {isSubmitting ? (
              <>
                <PrometheuxSpinner size={16} className="mr-1" />
                Setting up…
              </>
            ) : (
              <>
                <Play className="h-3 w-3 mr-1" />
                Open in project
              </>
            )}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default RunDataSourceModal;
