import { useCallback, useRef } from "react";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

/**
 * Builds the cURL snippet the cell header's API button copies: a POST to the
 * concept's run endpoint. The returned callback is stable (inputs are mirrored
 * into refs) so it doesn't invalidate the cells' render memos.
 *
 * The key is supplied by `QuickApiKeyPopover` — either a freshly issued
 * short-lived JWT or the placeholder for the template variant. The session
 * bearer is never embedded.
 */
export function useCellCurlSnippet(conceptName: string | undefined) {
  const ontologyId = useOntologyId();
  const ontologyScope = useOntologyScope();

  const conceptNameRef = useRef(conceptName);
  conceptNameRef.current = conceptName;
  const ontologyIdRef = useRef(ontologyId);
  ontologyIdRef.current = ontologyId;
  const ontologyScopeRef = useRef(ontologyScope);
  ontologyScopeRef.current = ontologyScope;

  return useCallback((apiKey: string) => {
    const payload = {
      params: {},
      scope: ontologyScopeRef.current || "user",
      persist_outputs: false,
    };
    const name = encodeURIComponent(conceptNameRef.current || "");
    const endpoint = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyIdRef.current}/run/${name}`;

    return `curl -X POST '${endpoint}' \\
  -H 'Content-Type: application/json' \\
  -H 'Authorization: Bearer ${apiKey}' \\
  -d '${JSON.stringify(payload, null, 2).replace(/'/g, "'\\''")}'`;
  }, []);
}
