import { FolderInput, Plus, X } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/shared/components/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";

const CREATE_GROUP_EVENT = "createGroupForCell";

interface GroupSelectorProps {
  cellId: string;
  currentGroup?: string;
  groupNames?: string[];
  onAssign?: (cellId: string, groupName: string) => void;
  onRemove?: (cellId: string) => void;
}

export function GroupSelector({
  cellId,
  currentGroup,
  groupNames = [],
  onAssign,
  onRemove,
}: GroupSelectorProps) {
  const [open, setOpen] = useState(false);

  const handleAssign = (groupName: string) => {
    onAssign?.(cellId, groupName);
    setOpen(false);
  };

  const handleRemove = () => {
    onRemove?.(cellId);
  };

  const handleCreate = () => {
    setOpen(false);
    window.dispatchEvent(
      new CustomEvent(CREATE_GROUP_EVENT, {
        detail: { cellId, createMode: true },
      }),
    );
  };

  if (currentGroup) {
    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <div className="flex items-center gap-1 rounded border border-blue-200 bg-blue-50 px-2 py-0.5 text-xs font-medium text-blue-700 dark:border-blue-800 dark:bg-blue-900/20 dark:text-blue-400">
            <span className="max-w-[100px] truncate">{currentGroup}</span>
            <Button
              variant="ghost"
              size="sm"
              className="h-4 w-4 p-0 hover:bg-blue-100 dark:hover:bg-blue-900/40"
              onClick={handleRemove}
              aria-label={`Remove from group ${currentGroup}`}
            >
              <X className="h-3 w-3" />
            </Button>
          </div>
        </TooltipTrigger>
        <TooltipContent>Click X to remove from group</TooltipContent>
      </Tooltip>
    );
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="ghost" size="sm" className="h-7 px-2 text-xs">
          <FolderInput className="mr-1 h-3 w-3" />
          Group
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-72 p-0" align="end">
        <Command>
          <CommandInput placeholder="Search groups…" />
          <CommandList className="max-h-64">
            <CommandEmpty>No groups found.</CommandEmpty>
            <CommandGroup>
              {groupNames.map((groupName) => (
                <CommandItem
                  key={groupName}
                  value={groupName}
                  onSelect={() => handleAssign(groupName)}
                >
                  <span className="truncate">{groupName}</span>
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
          <div className="border-t border-border p-1">
            <Button
              type="button"
              variant="ghost"
              className="h-8 w-full justify-start px-2 text-sm"
              onClick={handleCreate}
            >
              <Plus className="mr-2 h-3 w-3" />
              New group
            </Button>
          </div>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
