import { Loader2, ShieldCheck, Trash2, X } from "lucide-react";
import type React from "react";
import { useCallback } from "react";
import { toast } from "sonner";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { truncateText } from "@/shared/utils/textUtils";
import { useOntologyRoleOverride } from "../hooks/useOntologyRoleOverride";
import { useTeamAdminShareActions } from "../hooks/useTeamAdminShareActions";
import type { PermissionCaller, ShareRole } from "../types";
import OntologyAccessRoster from "./OntologyAccessRoster";

interface TeamAdminPermissionsDialogProps {
  isOpen: boolean;
  onClose: () => void;
  ontologyId: string;
  ontologyName: string;
  teamId: string;
  teamName: string;
  // The project owner's id — shown as a static "full access" row in the roster.
  ownerSub?: string;
}

// Delegated project-permission panel for a recipient-team owner/admin who is NOT
// the project owner. Shows the same roster as the concept dialog (team + member
// rows) and routes mutations through team-admin/apply.
const TeamAdminPermissionsDialog: React.FC<TeamAdminPermissionsDialogProps> = ({
  isOpen,
  onClose,
  ontologyId,
  ontologyName,
  teamId,
  teamName,
  ownerSub,
}) => {
  const caller: PermissionCaller = { mode: "team_admin", teamId };

  const { updateTeamRole, revokeTeam, isUpdatingRole, isRevoking } = useTeamAdminShareActions({
    ontologyId,
    teamId,
  });
  const { setOntologyRole, clearOntologyRole, isSettingOntologyRole, isClearingOntologyRole } =
    useOntologyRoleOverride(caller);

  const isBusy = isUpdatingRole || isSettingOntologyRole || isClearingOntologyRole;

  const handleSetTeamRole = useCallback(
    async (_teamId: string, role: ShareRole) => {
      try {
        await updateTeamRole(role);
        toast.success(`Team base role set to ${role}`);
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Failed to update team role");
      }
    },
    [updateTeamRole],
  );

  const handleSetMemberRole = useCallback(
    async (recipientSub: string, role: ShareRole) => {
      try {
        await setOntologyRole({ ontologyId, recipientSub, role });
        toast.success(`Member set to ${role}`);
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Failed to update member role");
      }
    },
    [setOntologyRole, ontologyId],
  );

  const handleClearMemberRole = useCallback(
    async (recipientSub: string) => {
      try {
        await clearOntologyRole({ ontologyId, recipientSub });
        toast.success("Reverted to team base role");
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Failed to update member role");
      }
    },
    [clearOntologyRole, ontologyId],
  );

  const handleRevoke = async (): Promise<void> => {
    try {
      await revokeTeam();
      toast.success("Team access revoked");
      onClose();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to revoke team access");
    }
  };

  const handleOpenChange = (open: boolean): void => {
    if (!open) onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent className="p-0 sm:max-w-[480px] overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Manage team access</DialogTitle>

        <div className="flex items-center justify-between border-b border-border bg-card px-4 py-3">
          <div className="flex min-w-0 items-center gap-2">
            <ShieldCheck className="h-4 w-4 flex-shrink-0 text-primary" />
            <div className="min-w-0">
              <p className="truncate text-sm font-semibold text-foreground">
                Team access — {teamName}
              </p>
              <p className="truncate text-xs text-muted-foreground">
                {truncateText(ontologyName, 48)}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="h-6 w-6 inline-flex items-center justify-center rounded text-muted-foreground hover:bg-accent hover:text-foreground"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="flex flex-col gap-4 p-4">
          <OntologyAccessRoster
            ontologyId={ontologyId}
            caller={caller}
            ownerSub={ownerSub}
            onSetTeamRole={handleSetTeamRole}
            onSetMemberRole={handleSetMemberRole}
            onClearMemberRole={handleClearMemberRole}
            isBusy={isBusy}
          />

          <div className="flex justify-end border-t border-border pt-3">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="text-destructive hover:text-destructive"
              disabled={isRevoking}
              onClick={handleRevoke}
            >
              {isRevoking ? (
                <Loader2 className="mr-1 h-3.5 w-3.5 animate-spin" />
              ) : (
                <Trash2 className="mr-1 h-3.5 w-3.5" />
              )}
              Revoke team access
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default TeamAdminPermissionsDialog;
