import { useEffect } from "react";
import { useNavigate } from "react-router-dom";

import { useAuth } from "@/features/auth/components/AuthProvider";

import { useOnboardingStatus } from "../hooks/useOnboardingStatus";
import { companyOnboardingSkip } from "../utils/companyOnboardingSkip";

interface CompanyOnboardingGateProps {
  children: React.ReactNode;
}

export function CompanyOnboardingGate({ children }: CompanyOnboardingGateProps) {
  const navigate = useNavigate();
  const { user, loading } = useAuth();
  const userId = user?.id ?? "";
  const skipped = userId ? companyOnboardingSkip.isSkipped(userId) : true;

  // Wait for the auth provider to finish hydrating before probing the
  // backend. The provider only flips `loading` to false AFTER wiring
  // HttpService with the active token — so loading=false is the correct
  // proxy for "the backend call will go out authenticated." Using
  // `useAuth().authToken` directly does NOT work: some auth flows (e.g.
  // Supabase metadata SSO) update HttpService without updating the
  // React state, so that field stays null and the gate would never fire.
  const ready = !loading && Boolean(userId);
  const { status } = useOnboardingStatus(ready && !skipped);

  useEffect(() => {
    if (!ready) return;
    if (skipped) return;
    if (!status) return;
    if (!status.needs_company_onboarding) return;
    navigate("/setup/company", { replace: true });
  }, [navigate, status, ready, skipped]);

  return <>{children}</>;
}
