import { Key, Trash2 } from "lucide-react";
import type React from "react";
import { useState } from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/shared/components/ui/alert-dialog";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/shared/components/ui/table";
import type { TokenSummary } from "./apiKeys.types";
import {
  formatExpiry,
  formatRelativeSafe,
  getTokenStatus,
  type TokenStatus,
} from "./apiKeys.utils";

interface ApiKeyListProps {
  tokens: TokenSummary[];
  onRevokeToken: (jti: string) => Promise<void>;
  isRevoking: boolean;
}

interface StatusBadgeProps {
  status: TokenStatus;
}

const StatusBadge: React.FC<StatusBadgeProps> = ({ status }) => {
  if (status === "expired") {
    return (
      <Badge
        variant="outline"
        className="bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400 border-red-200 dark:border-red-900/40"
      >
        Expired
      </Badge>
    );
  }
  if (status === "never_expires") {
    return <Badge variant="secondary">No expiry</Badge>;
  }
  return (
    <Badge
      variant="outline"
      className="bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-400 border-green-200 dark:border-green-900/40"
    >
      Active
    </Badge>
  );
};

const EmptyState: React.FC = () => (
  <div className="text-center py-8">
    <Key className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
    <h3 className="text-lg font-medium mb-2">No API Keys</h3>
    <p className="text-muted-foreground mb-4">
      You haven't created any API keys yet. Create your first key to start using the API.
    </p>
  </div>
);

export const ApiKeyList: React.FC<ApiKeyListProps> = ({ tokens, onRevokeToken, isRevoking }) => {
  const [revokingJti, setRevokingJti] = useState<string | null>(null);

  if (tokens.length === 0) return <EmptyState />;

  const handleRevoke = async (jti: string) => {
    setRevokingJti(jti);
    try {
      await onRevokeToken(jti);
    } finally {
      setRevokingJti(null);
    }
  };

  const rows = tokens.map((token) => ({
    jti: token.jti,
    displayName: token.name ?? "Unnamed key",
    status: getTokenStatus(token.expires_at),
    issued: formatRelativeSafe(token.issued_at),
    expiry: formatExpiry(token.expires_at),
  }));

  return (
    <div className="border border-border rounded-lg">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Name</TableHead>
            <TableHead>Status</TableHead>
            <TableHead>Created</TableHead>
            <TableHead>Expires</TableHead>
            <TableHead className="w-[100px]">Actions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.jti}>
              <TableCell className="font-medium">{row.displayName}</TableCell>
              <TableCell>
                <StatusBadge status={row.status} />
              </TableCell>
              <TableCell className="text-muted-foreground">{row.issued}</TableCell>
              <TableCell className="text-muted-foreground">{row.expiry}</TableCell>
              <TableCell>
                <AlertDialog>
                  <AlertDialogTrigger asChild>
                    <Button
                      variant="ghost"
                      size="sm"
                      disabled={isRevoking || revokingJti === row.jti}
                      aria-label={`Revoke ${row.displayName}`}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </AlertDialogTrigger>
                  <AlertDialogContent>
                    <AlertDialogHeader>
                      <AlertDialogTitle>Revoke API Key</AlertDialogTitle>
                      <AlertDialogDescription>
                        Revoke the API key "{row.displayName}"? Any service using this key will
                        immediately stop working. This action cannot be undone.
                      </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                      <AlertDialogCancel>Cancel</AlertDialogCancel>
                      <AlertDialogAction
                        onClick={() => handleRevoke(row.jti)}
                        className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                      >
                        Revoke Key
                      </AlertDialogAction>
                    </AlertDialogFooter>
                  </AlertDialogContent>
                </AlertDialog>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
};
