import { Download, Trash2, X } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { toast } from "sonner";
import { type OntologyScope, OntologyService } from "@/features/ontologies/api";
import DeleteOntologyDialog from "@/features/ontologies/components/DeleteOntologyDialog";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import { Textarea } from "@/shared/components/ui/textarea";

interface EditOntologyDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onUpdateOntology: (id: string, newName: string, newDescription: string) => Promise<void>;
  onDeleteOntology?: (ontologyName: string) => void;
  currentName: string;
  currentDescription: string;
  ontologyId: string;
  ontologyScope?: OntologyScope;
}

const EditOntologyDialog: React.FC<EditOntologyDialogProps> = ({
  isOpen,
  onClose,
  onUpdateOntology,
  onDeleteOntology,
  currentName,
  currentDescription,
  ontologyId,
  ontologyScope = "user",
}) => {
  const [ontologyName, setOntologyName] = useState(currentName);
  const [ontologyDescription, setOntologyDescription] = useState(currentDescription);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!ontologyName.trim()) {
      toast.error("Ontology name cannot be empty");
      return;
    }

    setIsSubmitting(true);

    try {
      await onUpdateOntology(ontologyId, ontologyName.trim(), ontologyDescription.trim());
      onClose();
      toast.success("Ontology updated successfully");
    } catch (error) {
      toast.error("Failed to update ontology");
      console.error("Error updating ontology:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteSuccess = () => {
    if (onDeleteOntology) onDeleteOntology(currentName);
    onClose();
  };

  const handleExport = async () => {
    try {
      setIsExporting(true);
      const exportData = await OntologyService.exportOntology(ontologyId, ontologyScope);

      const blob = new Blob([JSON.stringify(exportData, null, 2)], {
        type: "application/json",
      });

      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `ontology-export-${ontologyId}-${new Date().toISOString().split("T")[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      toast.success("Ontology exported successfully");
    } catch (error) {
      console.error("Export error:", error);
      toast.error("Failed to export ontology");
    } finally {
      setIsExporting(false);
    }
  };

  const busy = isSubmitting || isExporting;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="p-0 sm:max-w-[550px] overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Edit Ontology</DialogTitle>
        {/* Yellow header bar */}
        <div
          style={{ background: "#FFDF4B", padding: "12px 20px" }}
          className="flex items-center justify-between border-b border-border"
        >
          <h2 className="text-base font-bold text-[#212020]">Edit Ontology</h2>
          <button
            onClick={onClose}
            className="flex items-center justify-center h-6 w-6 rounded-full hover:bg-black/10 transition-colors"
            aria-label="Close"
          >
            <X className="h-4 w-4 text-[#212020]" />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 bg-card">
          <form onSubmit={handleSubmit}>
            <div className="grid gap-4">
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="name" className="text-right text-sm font-medium">
                  Name
                </Label>
                <Input
                  id="name"
                  value={ontologyName}
                  onChange={(e) => setOntologyName(e.target.value)}
                  className="col-span-3"
                  placeholder="My Ontology"
                  autoFocus
                />
              </div>

              <div className="grid grid-cols-4 items-start gap-4">
                <Label htmlFor="description" className="text-right text-sm font-medium mt-2">
                  Description
                </Label>
                <Textarea
                  id="description"
                  value={ontologyDescription}
                  onChange={(e) => setOntologyDescription(e.target.value)}
                  className="col-span-3 resize-none"
                  placeholder="Optional ontology description..."
                  rows={3}
                />
              </div>
            </div>

            <div className="flex items-center justify-between mt-6">
              <div className="flex gap-2">
                {onDeleteOntology && (
                  <Button
                    type="button"
                    variant="destructive"
                    onClick={() => setShowDeleteConfirm(true)}
                    disabled={busy}
                    className="flex items-center gap-2"
                  >
                    <Trash2 className="h-4 w-4" />
                    Delete
                  </Button>
                )}
                <Button type="button" variant="outline" onClick={onClose} disabled={busy}>
                  Cancel
                </Button>
              </div>
              <div className="flex gap-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleExport}
                  disabled={busy}
                  className="flex items-center gap-2"
                >
                  {isExporting ? (
                    <>
                      <PrometheuxSpinner size={16} />
                      Exporting...
                    </>
                  ) : (
                    <>
                      <Download className="h-4 w-4" />
                      Export
                    </>
                  )}
                </Button>
                <Button
                  type="submit"
                  disabled={busy || !ontologyName.trim()}
                  isLoading={isSubmitting}
                  className="bg-[#FFDF4B] text-[#212020] hover:bg-[#FFDF4B]/90 border border-[#212020] shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px]"
                >
                  Save
                </Button>
              </div>
            </div>
          </form>
        </div>
      </DialogContent>

      {onDeleteOntology && (
        <DeleteOntologyDialog
          ontologyId={ontologyId}
          ontologyName={currentName}
          ontologyScope={ontologyScope}
          open={showDeleteConfirm}
          onOpenChange={setShowDeleteConfirm}
          onDeleteSuccess={handleDeleteSuccess}
        />
      )}
    </Dialog>
  );
};

export default EditOntologyDialog;
