import * as dagre from "dagre";
import type { CustomFieldData, EdgeData, NodeData } from "./types";

/**
 * Migrate persisted custom fields from older shapes (bare string, or
 * `{value, type}` with legacy type names) into the current CustomFieldData shape.
 */
export const migrateCustomFields = (
  fields: Record<string, unknown>,
): Record<string, CustomFieldData> => {
  const result: Record<string, CustomFieldData> = {};
  for (const [key, value] of Object.entries(fields)) {
    if (typeof value === "string") {
      // Old format — bare string, migrate to the new format.
      result[key] = { value, type: "string" };
    } else if (value && typeof value === "object" && "value" in value && "type" in value) {
      // Narrow the legacy stored object after the runtime guards above.
      const legacy = value as { value: string; type: string };
      const oldType = legacy.type;
      let newType: CustomFieldData["type"] = "string";

      // Map old types to new types
      if (oldType === "number") {
        newType = Number.isInteger(Number(legacy.value)) ? "integer" : "double";
      } else if (oldType === "email" || oldType === "url") {
        newType = "string";
      } else if (
        ["string", "integer", "double", "date", "boolean", "set", "list"].includes(oldType)
      ) {
        newType = oldType as CustomFieldData["type"];
      }

      // Validate boolean values
      let newValue = legacy.value;
      if (newType === "boolean" && !["#T", "#F"].includes(legacy.value)) {
        newValue = legacy.value === "true" ? "#T" : "#F";
      }

      result[key] = { value: newValue, type: newType };
    }
  }
  return result;
};

/** Coerce a raw field value to a valid representation for its declared type. */
export const validateFieldValue = (value: string, type: string): string => {
  switch (type) {
    case "integer":
      return Number.isInteger(Number(value)) ? value : "";
    case "double":
      return !Number.isNaN(Number(value)) ? value : "";
    case "boolean":
      return ["#T", "#F"].includes(value) ? value : "#F";
    case "date":
      // Accept both date-only and datetime formats
      return /^\d{4}-\d{2}-\d{2}(\s\d{2}:\d{2}:\d{2})?$/.test(value) ? value : "";
    case "set":
      // Validate set format: {item1,item2,...}
      return /^\{.*\}$/.test(value) ? value : "{}";
    case "list":
      // Validate list format: [item1,item2,...]
      return /^\[.*\]$/.test(value) ? value : "[]";
    default:
      return value;
  }
};

/** Resolve the current `--flow-bg` theme token to a usable CSS color. */
export function getFlowBgColor(): string {
  const val = getComputedStyle(document.documentElement).getPropertyValue("--flow-bg").trim();
  return val ? `hsl(${val})` : "#f5f6f9";
}

/** Lighten/darken a hex color by a percentage amount (negative = darker). */
export function adjustBrightness(color: string | undefined, amount: number): string {
  const num = parseInt((color || "#97c2fc").replace("#", ""), 16);
  const amt = Math.round(2.55 * amount);
  const R = (num >> 16) + amt;
  const G = ((num >> 8) & 0x00ff) + amt;
  const B = (num & 0x0000ff) + amt;
  return (
    "#" +
    (
      0x1000000 +
      (R < 255 ? (R < 1 ? 0 : R) : 255) * 0x10000 +
      (G < 255 ? (G < 1 ? 0 : G) : 255) * 0x100 +
      (B < 255 ? (B < 1 ? 0 : B) : 255)
    )
      .toString(16)
      .slice(1)
  );
}

/** Truncate a node label for display on the canvas. */
export function truncateLabel(label: string, maxLength: number = 8): string {
  if (label.length <= maxLength) return label;
  return `${label.substring(0, maxLength - 1)}…`;
}

export const generateNodeId = () => `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
export const generateEdgeId = () => `edge-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

/** Compute top-to-bottom dagre positions for the given nodes/edges. */
export function applyLayout(nodes: NodeData[], edges: EdgeData[]): NodeData[] {
  if (nodes.length === 0) return nodes;

  const g = new dagre.graphlib.Graph();
  g.setGraph({ rankdir: "TB", nodesep: 100, ranksep: 100 });
  g.setDefaultEdgeLabel(() => ({}));

  nodes.forEach((node) => {
    g.setNode(node.id, { width: 80, height: 80 });
  });

  edges.forEach((edge) => {
    g.setEdge(edge.from, edge.to);
  });

  dagre.layout(g);

  return nodes.map((node) => {
    const dagreNode = g.node(node.id);
    return {
      ...node,
      x: dagreNode?.x || 0,
      y: dagreNode?.y || 0,
    };
  });
}
