import { FolderOpen, Share2, User, Users } from "lucide-react";
import React, { useCallback, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { usePaidComputeEligibility } from "@/features/billing/hooks/usePaidComputeEligibility";
import type { ExecutionOverallStatus } from "@/features/lineage/executionStatus";
import type { OntologyOrigin, OntologyScope } from "@/features/ontologies/api";
import { useTeamAdminAccess } from "@/features/ontologies/sharing/hooks/useTeamAdminAccess";
import type { ShareRole, ShareType, ShareUser } from "@/features/ontologies/sharing/types";
import { setCurrentOntologyScope } from "@/features/ontologies/utils";
import { Badge } from "@/shared/components/ui/badge";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";
import { generateEditorUrl } from "@/shared/utils/navigationUtils";
import { handleSpaLinkClick } from "@/shared/utils/spaLink";
import { OntologyCardActions } from "./OntologyCardActions";
import { type OntologyCardDialog, OntologyCardDialogs } from "./OntologyCardDialogs";
import { OntologyStatusBadge } from "./OntologyStatusBadge";
import SharedOntologyKebab from "./SharedOntologyKebab";

interface OntologyCardProps {
  ontologyId: string;
  ontologyName?: string;
  ontologyDescription?: string;
  scope?: OntologyScope;
  author?: string;
  origin?: OntologyOrigin;
  sharedBy?: ShareUser;
  shareRole?: ShareRole;
  // Required when origin === "shared" so the kebab → Leave share can call the
  // backend with the right token id.
  shareId?: string;
  onOpenOntology: (ontologyId: string, ontologyName: string) => void;
  onDelete?: (ontologyName: string) => void;
  onRename?: (id: string, newName: string, newDescription: string) => Promise<void>;
  onCopy?: (
    ontologyId: string,
    newOntologyName: string,
    targetScope: OntologyScope,
  ) => Promise<void>;
  // Wired only by callers that render shared-accepted cards (e.g. the Shared tab).
  // Owned cards never need this.
  onLeaveShare?: (shareId: string) => Promise<void>;
  // "team" for team-derived shares. Per-share "Leave" is hidden for team shares —
  // access is governed by team membership, not an individual leave action.
  shareType?: ShareType;
  // Recipient team id of a team share — lets a team owner/admin co-manage
  // permissions via the delegated team-admin endpoint.
  teamId?: string;
  isOpening?: boolean;
  // Latest run state for this project (from the batch execution-status query).
  // Undefined when the project is idle / has never run.
  executionStatus?: ExecutionOverallStatus;
}

const OntologyCard: React.FC<OntologyCardProps> = ({
  ontologyId,
  ontologyName,
  ontologyDescription,
  scope = "user",
  author,
  origin,
  sharedBy,
  shareRole,
  shareId,
  onOpenOntology,
  onDelete,
  onRename,
  onCopy,
  onLeaveShare,
  shareType,
  teamId,
  isOpening = false,
  executionStatus,
}) => {
  const { user } = useAuth();
  const { isEligible } = usePaidComputeEligibility();
  const isFreemium = isEligible === false;
  const { canManage: canManageTeamAccess, teamName } = useTeamAdminAccess(teamId, shareType);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [dialog, setDialog] = useState<OntologyCardDialog>(null);

  const isSharedWithMe = origin === "shared";
  const displayName = ontologyName || ontologyId;
  const displayDescription = ontologyDescription || "";
  // Only user-scoped, owned projects are shareable. Q4 locks the scope rule; isSharedWithMe
  // disables Share for the recipient (only the owner can re-share — backend returns 403).
  const canShare = scope === "user" && !isSharedWithMe;
  // Owner-only mutations are hidden on shared rows. The viewer/editor distinction is enforced
  // at the route level by the backend (Q3) — we additionally hide the affordances on the
  // recipient's card so they don't appear actionable; mutation-route gating lives in step 7.
  const showOwnerActions = !isSharedWithMe;
  // Per-share leave applies to user shares only; team shares are governed by
  // team membership, so their kebab exposes team-admin management instead.
  const showLeaveAction = shareType !== "team" && Boolean(onLeaveShare && shareId);

  const ScopeIcon = useMemo(() => (scope === "user" ? User : Users), [scope]);

  const editorHref = generateEditorUrl(user, ontologyId);

  const handleClick = useCallback(
    (e: React.MouseEvent<HTMLAnchorElement>) => {
      handleSpaLinkClick(e, () => {
        if (isOpening) return;
        setCurrentOntologyScope(scope);
        onOpenOntology(ontologyId, ontologyName || ontologyId);
      });
    },
    [ontologyId, ontologyName, onOpenOntology, scope, isOpening],
  );

  const handleEditClick = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setShowEditDialog(true);
  }, []);

  const handleCopyClick = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDialog("copy");
  }, []);

  const handleShareClick = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      // Team sharing is a paid-only conversion trigger — freemium accounts get
      // the contact-to-upgrade wall instead of the share dialog.
      setDialog(isFreemium ? "shareUpgrade" : "share");
    },
    [isFreemium],
  );

  const handleManageTeamAccess = useCallback(() => {
    setDialog("teamAccess");
  }, []);

  const handleUpdateOntology = useCallback(
    async (id: string, newName: string, newDescription: string) => {
      if (onRename) await onRename(id, newName, newDescription);
      setShowEditDialog(false);
    },
    [onRename],
  );

  const handleDeleteOntology = useCallback(
    (name: string) => {
      if (onDelete) onDelete(name);
    },
    [onDelete],
  );

  const handleCopyOntology = useCallback(
    async (id: string, newOntologyName: string, targetScope: OntologyScope) => {
      if (onCopy) await onCopy(id, newOntologyName, targetScope);
      setDialog(null);
    },
    [onCopy],
  );

  const handleLeaveShare = useCallback(async (): Promise<void> => {
    if (!onLeaveShare || !shareId) return;
    try {
      await onLeaveShare(shareId);
      toast.success(`Left "${displayName}"`);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to leave share";
      toast.error(message);
    }
  }, [onLeaveShare, shareId, displayName]);

  return (
    <>
      <Link
        to={editorHref}
        onClick={handleClick}
        className={`group relative flex h-full flex-col gap-3 text-left bg-card border border-border rounded-lg p-4 shadow-card hover:border-foreground/20 hover:shadow-sm transition-all duration-150 no-underline ${
          isOpening ? "opacity-75 pointer-events-none" : ""
        }`}
      >
        {isOpening && (
          <div className="absolute inset-0 bg-background/80 backdrop-blur-sm flex items-center justify-center z-20 rounded-lg">
            <PrometheuxSpinner size={36} label="Opening ontology..." />
          </div>
        )}

        {/* Owner rows show Share/Copy/Settings on hover. Shared (accepted) rows
            show a single kebab menu whose only entry is "Leave share" —
            owner-only mutations are hidden because the backend rejects them. */}
        {showOwnerActions && (
          <OntologyCardActions
            canShare={canShare}
            canCopy={!!onCopy}
            canRename={!!onRename}
            onShare={handleShareClick}
            onCopy={handleCopyClick}
            onRename={handleEditClick}
          />
        )}

        {isSharedWithMe && (showLeaveAction || canManageTeamAccess) && (
          <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity">
            <SharedOntologyKebab
              onLeaveShare={showLeaveAction ? handleLeaveShare : undefined}
              onManageTeamAccess={canManageTeamAccess ? handleManageTeamAccess : undefined}
            />
          </div>
        )}

        <div className="flex items-start gap-3">
          <div className="w-9 h-9 rounded-md border bg-muted/60 flex items-center justify-center flex-shrink-0 transition-colors">
            <FolderOpen className="h-4 w-4 text-foreground/60" />
          </div>
          <div className="min-w-0 flex-1">
            <Tooltip>
              <TooltipTrigger asChild>
                <div className="font-semibold text-[14px] text-foreground leading-tight truncate pr-6">
                  {displayName}
                </div>
              </TooltipTrigger>
              <TooltipContent side="bottom" className="max-w-xs">
                <p className="break-words">{displayName}</p>
              </TooltipContent>
            </Tooltip>
            {displayDescription ? (
              <div className="text-[12px] text-muted-foreground mt-1 line-clamp-2">
                {displayDescription}
              </div>
            ) : (
              <div className="text-[12px] text-muted-foreground/50 italic mt-1">No description</div>
            )}
          </div>
        </div>

        <div className="mt-auto flex items-center gap-2 border-t border-border/60 pt-3">
          <span className="flex min-w-0 items-center gap-1.5 text-[12px] text-muted-foreground">
            {isSharedWithMe ? (
              <Share2 className="h-3 w-3 flex-shrink-0" />
            ) : (
              <ScopeIcon className="h-3 w-3 flex-shrink-0" />
            )}
            <span className="truncate">
              {isSharedWithMe && sharedBy
                ? `Shared by ${sharedBy.username}@${sharedBy.organization}`
                : author || "Unknown"}
            </span>
          </span>
          {isSharedWithMe && shareRole && (
            <Badge variant="outline" className="capitalize">
              {shareRole}
            </Badge>
          )}
          <span className="ml-auto">
            <OntologyStatusBadge status={executionStatus} />
          </span>
        </div>
      </Link>

      <OntologyCardDialogs
        ontologyId={ontologyId}
        displayName={displayName}
        displayDescription={displayDescription}
        scope={scope}
        teamId={teamId}
        teamName={teamName}
        ownerSub={sharedBy?.sub}
        showEditDialog={showEditDialog}
        onCloseEdit={() => setShowEditDialog(false)}
        onUpdate={handleUpdateOntology}
        onDelete={handleDeleteOntology}
        dialog={dialog}
        setDialog={setDialog}
        onCopy={handleCopyOntology}
      />
    </>
  );
};

export default React.memo(OntologyCard);
