import { useQueries } from "@tanstack/react-query";
import { useMemo } from "react";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { listTeamMembers } from "../api";
import type { MemberRow } from "../types";
import { TEAM_MEMBERS_KEY } from "./useTeamMembers";

interface UseTeamsMembersReturn {
  // Flat, de-duplicated roster across every requested team. Each row keeps its
  // originating teamId so callers can scope actions per team when needed.
  members: (MemberRow & { teamId: string })[];
  isLoading: boolean;
}

// Parallel roster fetch for an arbitrary set of teams (e.g. every team a
// project is shared with). Uses useQueries so the number of teams can vary
// between renders without violating the rules of hooks — the single
// useTeamMembers hook can only cover one team at a time.
export function useTeamsMembers(teamIds: string[]): UseTeamsMembersReturn {
  const { user, session } = useAuth();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";

  const uniqueIds = useMemo(() => Array.from(new Set(teamIds.filter(Boolean))), [teamIds]);

  const results = useQueries({
    queries: uniqueIds.map((teamId) => ({
      queryKey: [...TEAM_MEMBERS_KEY, teamId, userId],
      queryFn: () => listTeamMembers(teamId, supabaseToken),
      enabled: Boolean(userId && supabaseToken && teamId),
      staleTime: 0,
      refetchOnWindowFocus: false,
      retry: 1,
    })),
  });

  const members = useMemo(() => {
    const seen = new Set<string>();
    const flat: (MemberRow & { teamId: string })[] = [];
    results.forEach((result, index) => {
      const teamId = uniqueIds[index];
      for (const member of result.data ?? []) {
        if (seen.has(member.user_id)) continue;
        seen.add(member.user_id);
        flat.push({ ...member, teamId });
      }
    });
    return flat;
  }, [results, uniqueIds]);

  const isLoading = results.some((r) => r.isLoading);

  return { members, isLoading };
}
