/**
 * Generic sessionStorage cache factory.
 *
 * Per-tab, no TTL, no userId — sessionStorage already scopes to the tab
 * and clears when the tab closes. Use this for short-lived drafts the
 * user shouldn't lose to an accidental refresh (e.g. an interview answer
 * map). For cross-tab / cross-session persistence, use `createLocalCache`.
 *
 * The `validate` option filters malformed reads — return the typed
 * payload or throw, and bad cached data is treated as a miss.
 *
 * `flush()` is exposed separately from `set()` so callers can debounce
 * writes (typical pattern: a `useEffect` that schedules `set` on a
 * timeout and `flush`-es on cleanup). The cache itself does not
 * debounce; that decision lives at the call site.
 */

export interface SessionCache<T> {
  get: () => T | null;
  set: (data: T) => void;
  clear: () => void;
}

export interface SessionCacheOptions<T> {
  /**
   * Runtime validator. Receives the parsed JSON and must either return
   * `T` (possibly filtered / coerced) or throw — throws are caught and
   * treated as a cache miss.
   */
  validate?: (parsed: unknown) => T;
}

export function createSessionCache<T>(
  key: string,
  options: SessionCacheOptions<T> = {},
): SessionCache<T> {
  const { validate } = options;

  const get = (): T | null => {
    try {
      const raw = sessionStorage.getItem(key);
      if (!raw) return null;
      const parsed: unknown = JSON.parse(raw);
      if (validate) return validate(parsed);
      return parsed as T;
    } catch (error) {
      // Quiet read failure — malformed data, private mode, quota
      // exceeded on read are all "no cached value" from the caller's
      // point of view.
      return null;
    }
  };

  const set = (data: T): void => {
    try {
      sessionStorage.setItem(key, JSON.stringify(data));
    } catch (error) {
      // sessionStorage may be unavailable (private mode) or full —
      // surface to the console but don't break the caller's flow.
      console.error(`Error writing session cache "${key}":`, error);
    }
  };

  const clear = (): void => {
    try {
      sessionStorage.removeItem(key);
    } catch (error) {
      console.error(`Error clearing session cache "${key}":`, error);
    }
  };

  return { get, set, clear };
}
