import type { Suggestion } from "../types";

// The onboarding suggestion is polish, not a hard prompt. Users get one chance
// to dismiss it — but the dismissal is scoped to the *content* of the
// suggestion, not the user. If the backend changes what it recommends (e.g.
// "create" flips to "join" because someone else created a matching team, or
// the suggested name changes), we drop the dismissal so the new hint shows.
//
// Signature format: `<action>:<team.id|suggested_name|"">`.

const STORAGE_KEYS = {
  TEAM_SUGGESTION_DISMISSED: "prometheux.teams.suggestionDismissed",
} as const;

function suggestionSignature(suggestion: Suggestion): string {
  const identity = suggestion.team?.id ?? suggestion.suggested_name ?? "";
  return `${suggestion.action}:${identity}`;
}

function storageKey(userId: string): string {
  return `${STORAGE_KEYS.TEAM_SUGGESTION_DISMISSED}:${userId}`;
}

export const teamSuggestionDismissal = {
  isDismissed(userId: string, suggestion: Suggestion): boolean {
    if (!userId) return false;
    try {
      const stored = localStorage.getItem(storageKey(userId));
      return stored === suggestionSignature(suggestion);
    } catch {
      // localStorage may throw in private browsing / disabled cookies — treat
      // as "not dismissed" so the user still sees the hint at least once.
      return false;
    }
  },

  dismiss(userId: string, suggestion: Suggestion): void {
    if (!userId) return;
    try {
      localStorage.setItem(storageKey(userId), suggestionSignature(suggestion));
    } catch {
      // Same fallback — silently ignore. The user will see the banner again on
      // reload, which is a minor annoyance but not a bug.
    }
  },

  clear(userId: string): void {
    if (!userId) return;
    try {
      localStorage.removeItem(storageKey(userId));
    } catch {
      // Ignored — see above.
    }
  },
};
