import { ArrowDown, ArrowUp, ArrowUpDown, Filter } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { cn } from "@/shared/lib/utils";
import type { ColumnFilterValue, FilterOperator } from "./tableOutput.types";
import { OPERATOR_LABELS } from "./tableOutput.utils";

interface MainMenuProps {
  isFiltered: boolean;
  currentSortDirection: "asc" | "desc" | null;
  onPickFilter: () => void;
  onPickOrder: () => void;
}

export function MainMenu({
  isFiltered,
  currentSortDirection,
  onPickFilter,
  onPickOrder,
}: MainMenuProps) {
  return (
    <div className="py-1">
      <button
        type="button"
        onClick={onPickFilter}
        className={cn(
          "w-full flex items-center gap-3 px-3 py-2 text-sm hover:bg-muted transition-colors",
          isFiltered && "text-blue-600",
        )}
      >
        <Filter className="h-4 w-4" />
        <span className="flex-1 text-left">Filter</span>
        {isFiltered && <span className="text-xs text-blue-500">Active</span>}
      </button>
      <button
        type="button"
        onClick={onPickOrder}
        className={cn(
          "w-full flex items-center gap-3 px-3 py-2 text-sm hover:bg-muted transition-colors",
          currentSortDirection && "text-blue-600",
        )}
      >
        <ArrowUpDown className="h-4 w-4" />
        <span className="flex-1 text-left">Order</span>
        {currentSortDirection && (
          <span className="text-xs text-blue-500">
            {currentSortDirection === "asc" ? "Asc" : "Desc"}
          </span>
        )}
      </button>
    </div>
  );
}

interface FilterSectionProps {
  columnName: string;
  operator: FilterOperator;
  value: string;
  isFiltered: boolean;
  currentFilter?: ColumnFilterValue;
  needsValue: boolean;
  onBack: () => void;
  onChangeOperator: (op: FilterOperator) => void;
  onChangeValue: (v: string) => void;
  onSubmit: (e: React.FormEvent) => void;
  onClear: () => void;
}

export function FilterSection({
  columnName,
  operator,
  value,
  isFiltered,
  currentFilter,
  needsValue,
  onBack,
  onChangeOperator,
  onChangeValue,
  onSubmit,
  onClear,
}: FilterSectionProps) {
  const operatorOptions = Object.keys(OPERATOR_LABELS) as FilterOperator[];

  return (
    <div className="p-3">
      <button
        type="button"
        onClick={onBack}
        className="text-xs text-muted-foreground hover:text-foreground mb-2"
      >
        ← Back
      </button>
      <form onSubmit={onSubmit} className="space-y-2">
        {isFiltered && currentFilter && (
          <div className="text-xs text-muted-foreground">
            Currently: {OPERATOR_LABELS[currentFilter.operator]}
            {currentFilter.value ? ` "${currentFilter.value}"` : ""}
          </div>
        )}
        <select
          value={operator}
          onChange={(e) => onChangeOperator(e.target.value as FilterOperator)}
          className="w-full h-8 text-xs rounded-md border border-input bg-background px-2 focus:outline-none focus:ring-1 focus:ring-ring"
        >
          {operatorOptions.map((op) => (
            <option key={op} value={op}>
              {OPERATOR_LABELS[op]}
            </option>
          ))}
        </select>
        {needsValue && (
          <Input
            type="text"
            value={value}
            onChange={(e) => onChangeValue(e.target.value)}
            placeholder={`Value for ${columnName}…`}
            className="h-8 text-sm"
            autoFocus
          />
        )}
        <div className="flex justify-between items-center gap-2">
          {isFiltered && (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={onClear}
              className="h-7 px-2 text-xs text-muted-foreground hover:text-foreground"
            >
              Clear
            </Button>
          )}
          <Button
            type="submit"
            size="sm"
            disabled={needsValue && !value.trim()}
            className="h-7 px-3 text-xs ml-auto"
          >
            Apply
          </Button>
        </div>
      </form>
    </div>
  );
}

interface OrderSectionProps {
  currentSortDirection: "asc" | "desc" | null;
  onBack: () => void;
  onSort: (direction: "asc" | "desc" | null) => void;
}

export function OrderSection({ currentSortDirection, onBack, onSort }: OrderSectionProps) {
  return (
    <div className="p-3">
      <button
        type="button"
        onClick={onBack}
        className="text-xs text-muted-foreground hover:text-foreground mb-2"
      >
        ← Back
      </button>
      <div className="space-y-1">
        <button
          type="button"
          onClick={() => onSort("asc")}
          className={cn(
            "w-full flex items-center gap-2 px-2 py-1.5 text-sm rounded hover:bg-muted",
            currentSortDirection === "asc" && "text-blue-600 bg-blue-50 dark:bg-blue-900/30",
          )}
        >
          <ArrowUp className="h-4 w-4" /> Ascending
        </button>
        <button
          type="button"
          onClick={() => onSort("desc")}
          className={cn(
            "w-full flex items-center gap-2 px-2 py-1.5 text-sm rounded hover:bg-muted",
            currentSortDirection === "desc" && "text-blue-600 bg-blue-50 dark:bg-blue-900/30",
          )}
        >
          <ArrowDown className="h-4 w-4" /> Descending
        </button>
        {currentSortDirection && (
          <button
            type="button"
            onClick={() => onSort(null)}
            className="w-full text-left px-2 py-1.5 text-xs text-muted-foreground hover:text-foreground"
          >
            Clear sort
          </button>
        )}
      </div>
    </div>
  );
}
