import { useSyncExternalStore } from "react";
import { getAuthToken, subscribeToAuthToken } from "./authToken";

/**
 * The current access token, re-rendering when it changes.
 *
 * Null rather than an empty string when there is none, so `authToken ?? x` and
 * a plain truthiness check both read the way callers expect.
 */
export function useAuthToken(): string | null {
  const token = useSyncExternalStore(subscribeToAuthToken, getAuthToken);
  return token || null;
}
