import { ArrowDownLeft, ArrowUpRight, Loader2, Maximize2, Minimize2, Plus, X } from "lucide-react";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import {
  type ConceptGraphData,
  type ConceptNodeNeighbor,
  conceptNodeNeighbors,
} from "../../conceptGraph.utils";
import { nodeTypeColor } from "../../graphExplorer.utils";

interface ConceptGraphNodePanelProps {
  nodeId: string;
  data: ConceptGraphData;
  onSelectNode: (nodeId: string | null) => void;
  /** Whether node expansion is available (records mode only). */
  canExpand?: boolean;
  /** Whether this node has already been expanded. */
  isExpanded?: boolean;
  /** Whether an expansion fetch for this node is in flight. */
  isExpanding?: boolean;
  /** Whether this node's last expansion hit the fetch cap ("showing first N"). */
  isCapped?: boolean;
  onExpand?: (nodeId: string) => void;
  onLoadMore?: (nodeId: string) => void;
  onCollapse?: (nodeId: string) => void;
}

function NeighborRow({
  neighbor,
  onSelect,
}: {
  neighbor: ConceptNodeNeighbor;
  onSelect: () => void;
}) {
  const DirectionIcon = neighbor.direction === "out" ? ArrowUpRight : ArrowDownLeft;
  return (
    <button
      type="button"
      onClick={onSelect}
      className="w-full flex items-center gap-1.5 py-1 text-left hover:bg-accent/50 rounded px-1 transition-colors"
    >
      <DirectionIcon className="h-3 w-3 flex-shrink-0 text-muted-foreground" />
      <span className="text-xs text-foreground truncate flex-1" title={neighbor.otherId}>
        {neighbor.otherId}
      </span>
      {neighbor.edgeLabel && (
        <Badge variant="outline" className="text-[9px] flex-shrink-0">
          {neighbor.edgeLabel}
        </Badge>
      )}
    </button>
  );
}

export function ConceptGraphNodePanel({
  nodeId,
  data,
  onSelectNode,
  canExpand = false,
  isExpanded = false,
  isExpanding = false,
  isCapped = false,
  onExpand,
  onLoadMore,
  onCollapse,
}: ConceptGraphNodePanelProps) {
  const node = data.nodes[nodeId];
  if (!node) return null;

  const color = nodeTypeColor(node.node_type);
  const neighbors = conceptNodeNeighbors(data, nodeId);
  const analytics = node.analytics;
  const hasScore = typeof analytics?.score === "number";
  const hasComponent = analytics?.component !== undefined;

  const handleExpand = () => onExpand?.(nodeId);
  const handleLoadMore = () => onLoadMore?.(nodeId);
  const handleCollapse = () => onCollapse?.(nodeId);

  return (
    <div className="w-80 flex-shrink-0 border-l border-border bg-card flex flex-col min-h-0">
      <div className="flex items-start gap-2 px-3 py-2 border-b border-border">
        <span
          className="inline-block w-3 h-3 rounded-full border-2 flex-shrink-0 mt-0.5"
          style={{ backgroundColor: color.fill, borderColor: color.stroke }}
        />
        <div className="min-w-0">
          <p className="text-sm font-medium text-foreground break-all">{node.label}</p>
          <p className="text-[11px] text-muted-foreground">{node.node_type}</p>
        </div>
        <Button
          variant="ghost"
          size="icon"
          className="ml-auto h-6 w-6 flex-shrink-0"
          onClick={() => onSelectNode(null)}
        >
          <X className="h-3.5 w-3.5" />
        </Button>
      </div>

      {(hasScore || hasComponent) && (
        <div className="flex items-center gap-3 px-3 py-2 border-b border-border">
          {hasScore && (
            <div className="flex flex-col">
              <span className="text-[10px] text-muted-foreground uppercase">Score</span>
              <span className="text-xs font-medium text-foreground tabular-nums">
                {analytics?.score?.toFixed(4)}
              </span>
            </div>
          )}
          {hasComponent && (
            <div className="flex flex-col">
              <span className="text-[10px] text-muted-foreground uppercase">Component</span>
              <span className="text-xs font-medium text-foreground">{analytics?.component}</span>
            </div>
          )}
        </div>
      )}

      {canExpand && (
        <div className="px-3 py-2 border-b border-border">
          {!isExpanded ? (
            <Button
              variant="outline"
              size="sm"
              className="w-full h-7 text-xs"
              disabled={isExpanding}
              onClick={handleExpand}
            >
              {isExpanding ? (
                <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
              ) : (
                <Maximize2 className="h-3.5 w-3.5 mr-1.5" />
              )}
              {isExpanding ? "Expanding…" : "Expand neighbors"}
            </Button>
          ) : (
            <Button
              variant="outline"
              size="sm"
              className="w-full h-7 text-xs"
              disabled={isExpanding}
              onClick={handleCollapse}
            >
              <Minimize2 className="h-3.5 w-3.5 mr-1.5" />
              Collapse
            </Button>
          )}
          {isExpanded && isCapped && (
            <div className="mt-1.5">
              <Button
                variant="ghost"
                size="sm"
                className="w-full h-6 text-[11px]"
                disabled={isExpanding}
                onClick={handleLoadMore}
              >
                {isExpanding ? (
                  <Loader2 className="h-3 w-3 mr-1 animate-spin" />
                ) : (
                  <Plus className="h-3 w-3 mr-1" />
                )}
                Load more neighbors
              </Button>
              <p className="mt-1 text-[10px] text-muted-foreground">
                Showing a limited batch of neighbors — more available.
              </p>
            </div>
          )}
        </div>
      )}

      <div className="flex-1 overflow-y-auto px-3 py-2">
        <h3 className="text-[11px] font-medium text-muted-foreground uppercase mb-1.5">
          Connections ({neighbors.length})
        </h3>
        {neighbors.length === 0 && (
          <p className="text-xs text-muted-foreground">
            No edges touch this node in the loaded records.
          </p>
        )}
        {neighbors.map((neighbor) => (
          <NeighborRow
            key={`${neighbor.direction}-${neighbor.otherId}-${neighbor.edgeLabel}`}
            neighbor={neighbor}
            onSelect={() => onSelectNode(neighbor.otherId)}
          />
        ))}
      </div>
    </div>
  );
}
