import { useCallback, useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";

export const useNavigationState = () => {
  const location = useLocation();
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState("ontology");
  const [previousTab, setPreviousTab] = useState("ontology");
  const [isSettingsTransition, setIsSettingsTransition] = useState(false);

  const validTabs = useMemo(
    () => ["ontology", "lineage", "chat", "settings", "app", "projects", "data", "compute"],
    [],
  );

  // Apply activeTab from navigation state on route changes
  useEffect(() => {
    if (!location.state?.activeTab) return;
    const targetTab = location.state.activeTab;
    setActiveTab(targetTab);
    if (targetTab === "settings") {
      setIsSettingsTransition(true);
      setTimeout(() => setIsSettingsTransition(false), 1000);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.state]);

  // Listen for programmatic tab switches dispatched via CustomEvent
  useEffect(() => {
    const handleSwitchTab = (event: CustomEvent) => {
      const targetTab = event.detail;
      if (targetTab === "settings") {
        setIsSettingsTransition(true);
        setTimeout(() => setIsSettingsTransition(false), 1000);
      }
      if (validTabs.includes(targetTab) && activeTab !== targetTab) {
        setActiveTab(targetTab);
      }
    };
    window.addEventListener("switchTab", handleSwitchTab as EventListener);
    return () => window.removeEventListener("switchTab", handleSwitchTab as EventListener);
  }, [activeTab, validTabs]);

  // Migrate legacy virtual-kg tab to ontology
  useEffect(() => {
    if (activeTab === "virtual-kg") setActiveTab("ontology");
  }, [activeTab]);

  const handleTabChange = useCallback(
    (value: string) => {
      if (value === "virtual-kg") return;
      if (!validTabs.includes(value)) return;
      if (activeTab === value) return;

      if (value === "settings" && activeTab !== "settings") {
        if (location.pathname === "/") {
          setPreviousTab("projects");
        } else if (location.pathname === "/datasources") {
          setPreviousTab("datasources");
        } else {
          setPreviousTab(activeTab);
        }
        setIsSettingsTransition(true);
        setTimeout(() => setIsSettingsTransition(false), 1000);
      } else if (value === "ontology") {
        if (!globalThis.cachedOntologyCode && globalThis.tempOntologyCode) {
          globalThis.cachedOntologyCode = globalThis.tempOntologyCode;
        }
        if (globalThis.cachedOntologyCode) {
          window.dispatchEvent(
            new CustomEvent("autoCompileRequested", { bubbles: true, cancelable: true }),
          );
        }
      }

      setActiveTab(value);
    },
    [validTabs, activeTab, location.pathname],
  );

  const handleBackFromSettings = useCallback(() => {
    if (previousTab === "datasources") {
      navigate("/datasources");
      return;
    }

    const isGoingToHomePage =
      !location.pathname.startsWith("/editor/") || location.pathname === "/editor/new";

    if (globalThis.ontology_session && isGoingToHomePage) {
      globalThis.ontology_session = null;
    }

    const targetTab = validTabs.includes(previousTab) ? previousTab : "ontology";
    setActiveTab(targetTab);
    setPreviousTab("ontology");
  }, [previousTab, validTabs, location.pathname, navigate]);

  return {
    activeTab,
    handleTabChange,
    handleBackFromSettings,
    isSettingsTransition,
    previousTab,
  };
};
