import { useRef, useState } from "react";
import { useConceptEditorClient } from "@/features/concept-editor/api/ConceptEditorClientContext";
import type { ConceptGraphPagination } from "../types";

const PREVIEW_PAGE_SIZE = 50;

export type ConceptDataPreviewStatus = "idle" | "loading" | "ready" | "error";

interface ConceptDataPreviewState {
  predicate: string | null;
  status: ConceptDataPreviewStatus;
  error: string | null;
  columns: string[];
  rows: unknown[][];
  pagination: ConceptGraphPagination | null;
}

interface UseConceptDataPreviewReturn extends ConceptDataPreviewState {
  show: (predicate: string) => void;
  goToPage: (page: number) => void;
  close: () => void;
}

const IDLE_STATE: ConceptDataPreviewState = {
  predicate: null,
  status: "idle",
  error: null,
  columns: [],
  rows: [],
  pagination: null,
};

/**
 * Tabular preview of a concept's materialized results — the same fetch the
 * editor's "Restore results" action uses (no re-run). Shown while a concept
 * has no source/target roles assigned yet.
 */
export function useConceptDataPreview(
  ontologyId: string,
  scope: string,
): UseConceptDataPreviewReturn {
  const clientFromContext = useConceptEditorClient();
  const clientRef = useRef(clientFromContext);
  const [state, setState] = useState<ConceptDataPreviewState>(IDLE_STATE);

  const load = async (predicate: string, page: number) => {
    setState((prev) => ({ ...prev, predicate, status: "loading", error: null }));
    try {
      const response = await clientRef.current.fetchOutputFacts(
        ontologyId,
        predicate,
        page,
        scope,
        PREVIEW_PAGE_SIZE,
      );
      if (response.status !== "success" || !response.data) {
        throw new Error("Failed to fetch the concept's results");
      }
      setState({
        predicate,
        status: "ready",
        error: null,
        columns: response.data.results.columnNames ?? [],
        rows: response.data.results.facts ?? [],
        pagination: {
          page: response.data.pagination.page,
          total_pages: response.data.pagination.total_pages,
          has_next: response.data.pagination.has_next,
          has_prev: response.data.pagination.has_prev,
          total_count: response.data.pagination.total_count,
          page_size: PREVIEW_PAGE_SIZE,
        },
      });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Failed to fetch the concept's results";
      setState({ ...IDLE_STATE, predicate, status: "error", error: message });
    }
  };

  const show = (predicate: string) => {
    void load(predicate, 1);
  };

  const goToPage = (page: number) => {
    if (!state.predicate) return;
    void load(state.predicate, page);
  };

  const close = () => setState(IDLE_STATE);

  return { ...state, show, goToPage, close };
}
