/**
 * A turn the backend cut short on one of its per-turn budgets.
 *
 * Without this the model's wrap-up text is all the user sees, which reads like
 * it decided it was done. The copy below says the run was stopped and the panel
 * offers to continue it.
 */

export type HaltReason = "tool_iterations" | "time_budget";

export interface HaltData {
  reason: HaltReason;
  iterations: number;
  maxIterations: number;
  seconds: number;
  maxSeconds: number;
}

const HALT_REASONS: HaltReason[] = ["tool_iterations", "time_budget"];

function toNumber(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function toReason(value: unknown): HaltReason {
  const match = HALT_REASONS.find((reason) => reason === value);
  return match ?? "tool_iterations";
}

/** Read a `halted` stream event, tolerating anything unexpected in it. */
export function parseHalt(data: unknown): HaltData {
  const record: Record<string, unknown> =
    typeof data === "object" && data !== null ? (data as Record<string, unknown>) : {};
  return {
    reason: toReason(record.reason),
    iterations: toNumber(record.iterations),
    maxIterations: toNumber(record.max_iterations),
    seconds: toNumber(record.seconds),
    maxSeconds: toNumber(record.max_seconds),
  };
}

/** Sent when the user clicks Resume; the model still has the turn's history. */
export const RESUME_PROMPT =
  "Continue from where you stopped. Pick up the remaining work without repeating what is already done.";

export interface HaltCopy {
  title: string;
  detail: string;
}

export function describeHalt(data: HaltData): HaltCopy {
  if (data.reason === "time_budget") {
    const minutes = Math.max(1, Math.round(data.maxSeconds / 60));
    return {
      title: "Agent execution halted — time limit reached",
      detail: `This turn ran for its full ${minutes} minute limit, so the assistant had to stop and summarise. Resume to keep going.`,
    };
  }
  return {
    title: "Agent execution halted — tool call limit reached",
    detail: `This turn used all ${data.maxIterations} of its tool calls, so the assistant had to stop and summarise. Resume to keep going.`,
  };
}
