import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import {
  listOutbox,
  revokeShare,
  revokeTeamShare,
  updateShareRole,
  updateTeamShareRole,
} from "../api";
import type {
  OutboxEntry,
  RevokeInput,
  RevokeResult,
  ShareError,
  ShareRole,
  TeamRevokeInput,
  TeamUpdateRoleResult,
  UpdateRoleResult,
} from "../types";
import { SHARE_INBOX_KEY } from "./useShareInbox";

export const SHARE_OUTBOX_KEY = ["share", "outbox"] as const;
const outboxKey = (ontologyId: string | undefined, userId: string) =>
  [...SHARE_OUTBOX_KEY, ontologyId ?? "all", userId] as const;

interface UseShareOutboxOptions {
  // If provided, only that project's shares are loaded. Omit to load the full outbox
  // (e.g. for a settings page listing every share the user has created).
  ontologyId?: string;
  // Caller can defer the fetch (e.g. only run when the Manage Shares panel opens).
  // Defaults to true.
  enabled?: boolean;
}

interface UpdateRoleInput {
  shareId: string;
  shareRole: ShareRole;
}

interface UseShareOutboxReturn {
  entries: OutboxEntry[];
  isLoading: boolean;
  isFetching: boolean;
  error: ShareError | null;
  refresh: () => Promise<unknown>;
  revoke: (input: RevokeInput) => Promise<RevokeResult>;
  revokeTeam: (input: TeamRevokeInput) => Promise<RevokeResult>;
  isRevoking: boolean;
  updateRole: (input: UpdateRoleInput) => Promise<UpdateRoleResult>;
  updateTeamRole: (input: UpdateRoleInput) => Promise<TeamUpdateRoleResult>;
  isUpdatingRole: boolean;
  updatingShareId: string | null;
}

export function useShareOutbox({
  ontologyId,
  enabled = true,
}: UseShareOutboxOptions = {}): UseShareOutboxReturn {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";

  const query = useQuery<OutboxEntry[], ShareError>({
    queryKey: outboxKey(ontologyId, userId),
    queryFn: () => listOutbox(supabaseToken, ontologyId),
    enabled: enabled && Boolean(userId && supabaseToken),
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const revokeMutation = useMutation<RevokeResult, ShareError, RevokeInput>({
    mutationFn: (input) => revokeShare(input, supabaseToken),
    onSuccess: () => {
      // Invalidate by prefix so we hit every (ontologyId, userId) variant.
      queryClient.invalidateQueries({ queryKey: SHARE_OUTBOX_KEY });
    },
  });

  // Team-share revoke — separate endpoint (kills every member's token) but the
  // same cache-invalidation story as user revoke.
  const revokeTeamMutation = useMutation<RevokeResult, ShareError, TeamRevokeInput>({
    mutationFn: (input) => revokeTeamShare(input, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: SHARE_OUTBOX_KEY });
    },
  });

  // POST /share/update-role — changes the role on an existing share. The recipient's
  // view (driven by /share/inbox) also carries the role, so invalidate both query
  // trees to keep every consumer in sync (the inbox key is shared with useShareInbox /
  // useProjects / Shared tab). We don't gate on result.changed here — the toast layer
  // decides between "updated" and "unchanged"; invalidation is cheap and idempotent.
  const updateRoleMutation = useMutation<UpdateRoleResult, ShareError, UpdateRoleInput>({
    mutationFn: ({ shareId, shareRole }) => updateShareRole(shareId, shareRole, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: SHARE_OUTBOX_KEY });
      queryClient.invalidateQueries({ queryKey: SHARE_INBOX_KEY });
    },
  });

  // POST /share/team/update-role — the team equivalent. Members converge on the
  // new role at their next sync, so the immediate cache story is the same as the
  // user path: refresh both trees so the outbox row and any recipient views agree.
  const updateTeamRoleMutation = useMutation<TeamUpdateRoleResult, ShareError, UpdateRoleInput>({
    mutationFn: ({ shareId, shareRole }) => updateTeamShareRole(shareId, shareRole, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: SHARE_OUTBOX_KEY });
      queryClient.invalidateQueries({ queryKey: SHARE_INBOX_KEY });
    },
  });

  // A single row can only have one role edit in flight; surface whichever
  // mutation is pending so the row spinner + disabled state work for both paths.
  const roleUpdateVariables = updateRoleMutation.isPending
    ? updateRoleMutation.variables
    : updateTeamRoleMutation.isPending
      ? updateTeamRoleMutation.variables
      : null;

  return {
    entries: query.data ?? [],
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    refresh: query.refetch,
    revoke: revokeMutation.mutateAsync,
    revokeTeam: revokeTeamMutation.mutateAsync,
    isRevoking: revokeMutation.isPending || revokeTeamMutation.isPending,
    updateRole: updateRoleMutation.mutateAsync,
    updateTeamRole: updateTeamRoleMutation.mutateAsync,
    isUpdatingRole: updateRoleMutation.isPending || updateTeamRoleMutation.isPending,
    updatingShareId: roleUpdateVariables?.shareId ?? null,
  };
}
