import type { DatabricksCredentialSubmission } from "@/features/compute/api/databricksCredentials";
import type { CredentialField, CredentialRequestData } from "./store";

export type CredentialAuthMode = "token" | "oauth2" | "";

/** What the user has typed into the form so far. */
export interface CredentialDraft {
  host: string;
  token: string;
  clientId: string;
  clientSecret: string;
}

export const EMPTY_CREDENTIAL_DRAFT: CredentialDraft = {
  host: "",
  token: "",
  clientId: "",
  clientSecret: "",
};

const CREDENTIAL_FIELDS: CredentialField[] = [
  "host",
  "auth_mode",
  "token",
  "client_id",
  "client_secret",
];

const isCredentialField = (value: unknown): value is CredentialField =>
  typeof value === "string" && CREDENTIAL_FIELDS.includes(value as CredentialField);

const readAuthMode = (value: unknown): CredentialRequestData["auth_mode"] =>
  value === "token" || value === "oauth2" ? value : "";

const readString = (value: unknown): string => (typeof value === "string" ? value : "");

/**
 * Read a `credential_request` event off the wire.
 *
 * Unknown field names are dropped rather than trusted: the form renders an input
 * per name, and one we do not recognise would be a box nobody can act on.
 */
export function parseCredentialRequest(
  data: Record<string, unknown> | undefined,
): CredentialRequestData {
  const rawFields = Array.isArray(data?.fields) ? data.fields : [];
  return {
    provider: "databricks",
    auth_mode: readAuthMode(data?.auth_mode),
    fields: rawFields.filter(isCredentialField),
    host: readString(data?.host),
    context: readString(data?.context),
  };
}

/**
 * The inputs to show, given what the assistant asked for and which kind of
 * credential the user has settled on. Nothing credential-shaped is asked for
 * until that is known, because a token and a service principal are different
 * questions.
 */
export function requestedFields(
  data: CredentialRequestData,
  mode: CredentialAuthMode,
): CredentialField[] {
  const workspace: CredentialField[] = data.fields.includes("host") ? ["host"] : [];
  if (mode === "token") return [...workspace, "token"];
  if (mode === "oauth2") return [...workspace, "client_id", "client_secret"];
  return workspace;
}

/** Which part of the draft each requested field writes to. */
const DRAFT_KEY: Record<CredentialField, keyof CredentialDraft | null> = {
  host: "host",
  auth_mode: null,
  token: "token",
  client_id: "clientId",
  client_secret: "clientSecret",
};

export function draftValue(field: CredentialField, draft: CredentialDraft): string {
  const key = DRAFT_KEY[field];
  return key ? draft[key] : "";
}

export function withDraftValue(
  draft: CredentialDraft,
  field: CredentialField,
  value: string,
): CredentialDraft {
  const key = DRAFT_KEY[field];
  return key ? { ...draft, [key]: value } : draft;
}

/** Every field asked for has something in it. */
export function isDraftComplete(fields: CredentialField[], draft: CredentialDraft): boolean {
  if (fields.length === 0) return false;
  return fields.every((field) => draftValue(field, draft).trim().length > 0);
}

/** The submission body, carrying only the credential the chosen mode uses. */
export function buildCredentialSubmission(
  mode: CredentialAuthMode,
  draft: CredentialDraft,
): DatabricksCredentialSubmission {
  const host = draft.host.trim();
  const workspace = host ? { host } : {};
  if (mode === "token") {
    return { ...workspace, auth_mode: "token", token: draft.token.trim() };
  }
  return {
    ...workspace,
    auth_mode: "oauth2",
    client_id: draft.clientId.trim(),
    client_secret: draft.clientSecret.trim(),
  };
}
