import { AlertTriangle, Ban, PlugZap, X } from "lucide-react";
import { useMemo, useState } from "react";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";
import { lineageRunAck } from "@/shared/utils/lineageRunAck";
import {
  type ExecutionOverallStatus,
  type ExecutionStatusSnapshot,
  formatDuration,
} from "../executionStatus";

interface LastRunNoticeProps {
  snapshot: ExecutionStatusSnapshot | undefined;
}

type NoticeStatus = "error" | "cancelled" | "interrupted";

interface NoticePresentation {
  title: string;
  Icon: typeof AlertTriangle;
  /** Container background/border/text — paired light + dark variants. */
  containerClass: string;
  iconClass: string;
}

const NOTICE_STATUSES: ReadonlySet<string> = new Set<NoticeStatus>([
  "error",
  "cancelled",
  "interrupted",
]);

function isNoticeStatus(status: ExecutionOverallStatus): status is NoticeStatus {
  return NOTICE_STATUSES.has(status);
}

function resolvePresentation(status: NoticeStatus): NoticePresentation {
  switch (status) {
    case "error":
      return {
        title: "Last run failed",
        Icon: AlertTriangle,
        containerClass:
          "border-red-200 bg-red-50 text-red-800 dark:border-red-900/40 dark:bg-red-900/20 dark:text-red-200",
        iconClass: "text-red-600 dark:text-red-400",
      };
    case "cancelled":
      return {
        title: "Last run was cancelled",
        Icon: Ban,
        containerClass:
          "border-amber-200 bg-amber-50 text-amber-800 dark:border-amber-900/40 dark:bg-amber-900/20 dark:text-amber-200",
        iconClass: "text-amber-600 dark:text-amber-400",
      };
    case "interrupted":
      return {
        title: "Last run was interrupted",
        Icon: PlugZap,
        containerClass:
          "border-amber-200 bg-amber-50 text-amber-800 dark:border-amber-900/40 dark:bg-amber-900/20 dark:text-amber-200",
        iconClass: "text-amber-600 dark:text-amber-400",
      };
    default: {
      const _exhaustive: never = status;
      throw new Error(`Unhandled notice status: ${_exhaustive}`);
    }
  }
}

/**
 * Floating, acknowledgeable notice shown on the lineage canvas when the
 * project's most recent run ended in a non-success state. Surfaces the failure
 * reason so the user can mitigate and re-run, instead of being left guessing
 * why the lineage looks idle.
 *
 * Clicking the notice acknowledges it: the acknowledgement is persisted by
 * `execution_id` (see `lineageRunAck`), so the same failed run never nags again
 * across reloads or navigation. A later run mints a new id, so a fresh failure
 * re-surfaces.
 */
export function LastRunNotice({ snapshot }: LastRunNoticeProps) {
  // The run acknowledged in this session (clears the notice immediately on click).
  const [sessionAckedId, setSessionAckedId] = useState<string | null>(null);
  // When the editor panel is expanded full-screen it covers the lineage canvas,
  // so this floating notice would otherwise overlap the code editor (e.g. in
  // Explorer mode). Hide it while expanded; it re-surfaces once the panel closes.
  const isPanelExpanded = useEditorActionsStore((s) => s.isLineagePanelExpanded);
  const executionId = snapshot?.executionId ?? null;

  // Persisted lookup — covers a run acknowledged in a previous session that we
  // re-encounter on reload or navigation. Re-reads only when the run changes.
  const persistedAck = useMemo(() => lineageRunAck.isAcked(executionId), [executionId]);

  if (isPanelExpanded) return null;
  if (!snapshot || !executionId) return null;
  if (!isNoticeStatus(snapshot.status)) return null;
  if (persistedAck || executionId === sessionAckedId) return null;

  const { title, Icon, containerClass, iconClass } = resolvePresentation(snapshot.status);
  const duration = formatDuration(snapshot.durationMs);
  const target = snapshot.targetConcept;

  const handleAcknowledge = () => {
    lineageRunAck.ack(executionId);
    setSessionAckedId(executionId);
  };

  return (
    <div className="pointer-events-none absolute inset-x-0 top-3 z-20 flex justify-center px-4">
      <button
        type="button"
        onClick={handleAcknowledge}
        aria-label="Dismiss notice"
        className={`pointer-events-auto flex max-w-xl items-start gap-3 rounded-lg border px-4 py-3 text-left shadow-md transition-opacity hover:opacity-90 ${containerClass}`}
      >
        <Icon className={`mt-0.5 h-4 w-4 flex-shrink-0 ${iconClass}`} />
        <div className="min-w-0 flex-1">
          <p className="text-sm font-semibold">
            {title}
            {target ? <span className="font-normal"> · {target}</span> : null}
          </p>
          {snapshot.failureReason ? (
            <p className="mt-0.5 break-words text-xs opacity-90">{snapshot.failureReason}</p>
          ) : null}
          {duration ? <p className="mt-1 text-[11px] opacity-70">Ran for {duration}</p> : null}
          <p className="mt-1 text-[11px] opacity-60">Click to dismiss</p>
        </div>
        <X className={`mt-0.5 h-4 w-4 flex-shrink-0 opacity-70 ${iconClass}`} aria-hidden="true" />
      </button>
    </div>
  );
}
