import type { Extension } from "@codemirror/state";
import type React from "react";
import QueryConceptCell from "@/features/concept-editor/components/query/QueryConceptCell";
import QueryContextCell from "@/features/concept-editor/components/query/QueryContextCell";
import QueryCypherCell from "@/features/concept-editor/components/query/QueryCypherCell";
import QueryLlmCell from "@/features/concept-editor/components/query/QueryLlmCell";
import QueryPythonCell from "@/features/concept-editor/components/query/QueryPythonCell";
import QuerySqlCell from "@/features/concept-editor/components/query/QuerySqlCell";
import type { SaveCellHandler } from "@/features/concept-editor/components/query/types/editorTypes";
import type { ConceptCell, ConceptType } from "@/features/concept-editor/types";
import type { ExplorerBottomTab } from "@/shared/utils/explorerPreferences";

interface SelectedCellEditorProps {
  cell: ConceptCell;
  extensionsWithLinter: Extension[];
  extensionsWithoutLinter: Extension[];
  extensionsPython: Extension[];
  editorTheme: "light";
  setCells: React.Dispatch<React.SetStateAction<ConceptCell[]>>;
  onCodeChange: (value: string, cellId: string) => void;
  onRunCell: (cellId: string, freshCode?: string, forceRerun?: boolean) => void;
  onSaveCell: SaveCellHandler;
  onDeleteCell: (cellId: string) => Promise<void>;
  onStopCell: (cellId: string) => Promise<void>;
  onClearResults: (cellId: string) => void;
  onRestoreResults: (cellId: string) => void;
  onIndentCode: (cellId: string) => void;
  onOpenAssistant?: (cellId: string) => void;
  onCellTypeChange: (cellId: string, conceptType: ConceptType) => void;
  onOutputPredicateChange: (cellId: string, outputPredicate: string) => void;
  onRenameConcept?: (cellId: string, newName: string) => Promise<void>;
  groupNames: string[];
  onAddCellToGroup: (cellId: string, groupName: string) => void;
  onRemoveCellFromGroup: (cellId: string) => void;
  bottomTab: ExplorerBottomTab;
  onBottomTabChange: (view: ExplorerBottomTab) => void;
  /**
   * IDE split layout (editor on top, description/engine/output below). When
   * false the cell renders single-view with all tabs in one top row — used by
   * the collapsed lineage dock.
   */
  expanded: boolean;
}

const SelectedCellEditor: React.FC<SelectedCellEditorProps> = ({
  cell,
  extensionsWithLinter,
  extensionsWithoutLinter,
  extensionsPython,
  editorTheme,
  setCells,
  onCodeChange,
  onRunCell,
  onSaveCell,
  onDeleteCell,
  onStopCell,
  onClearResults,
  onRestoreResults,
  onIndentCode,
  onOpenAssistant,
  onCellTypeChange,
  onOutputPredicateChange,
  onRenameConcept,
  groupNames,
  onAddCellToGroup,
  onRemoveCellFromGroup,
  bottomTab,
  onBottomTabChange,
  expanded,
}) => {
  if (cell.conceptType === "context") {
    return (
      <QueryContextCell
        key={cell.id}
        cell={{ ...cell, autoOpen: true }}
        index={0}
        extensions={extensionsWithoutLinter}
        editorTheme={editorTheme}
        onCodeChange={onCodeChange}
        onRunCell={onRunCell}
        onSaveCell={onSaveCell}
        onDeleteCell={onDeleteCell}
        onClearResults={onClearResults}
        onRestoreResults={onRestoreResults}
        onStopCell={onStopCell}
        onIndentCode={onIndentCode}
        onOpenAssistant={onOpenAssistant}
        setCells={setCells}
        onOutputPredicateChange={onOutputPredicateChange}
        onCellTypeChange={onCellTypeChange}
        onRenameConcept={onRenameConcept}
        groupNames={groupNames}
        onAddCellToGroup={onAddCellToGroup}
        onRemoveCellFromGroup={onRemoveCellFromGroup}
        defaultView={bottomTab}
        onViewChange={onBottomTabChange}
        splitLayout={expanded}
      />
    );
  }

  if (cell.conceptType === "llm") {
    return (
      <QueryLlmCell
        key={cell.id}
        cell={{ ...cell, autoOpen: true }}
        index={0}
        extensions={extensionsWithoutLinter}
        editorTheme={editorTheme}
        onCodeChange={onCodeChange}
        onRunCell={onRunCell}
        onSaveCell={onSaveCell}
        onDeleteCell={onDeleteCell}
        onClearResults={onClearResults}
        onRestoreResults={onRestoreResults}
        onStopCell={onStopCell}
        onIndentCode={onIndentCode}
        onOpenAssistant={onOpenAssistant}
        setCells={setCells}
        onOutputPredicateChange={onOutputPredicateChange}
        onCellTypeChange={onCellTypeChange}
        onRenameConcept={onRenameConcept}
        groupNames={groupNames}
        onAddCellToGroup={onAddCellToGroup}
        onRemoveCellFromGroup={onRemoveCellFromGroup}
        defaultView={bottomTab}
        onViewChange={onBottomTabChange}
        splitLayout={expanded}
      />
    );
  }

  if (cell.conceptType === "python") {
    return (
      <QueryPythonCell
        key={cell.id}
        cell={{ ...cell, autoOpen: true }}
        index={0}
        extensions={extensionsPython}
        editorTheme={editorTheme}
        onCodeChange={onCodeChange}
        onRunCell={onRunCell}
        onSaveCell={onSaveCell}
        onDeleteCell={onDeleteCell}
        onClearResults={onClearResults}
        onRestoreResults={onRestoreResults}
        onStopCell={onStopCell}
        onIndentCode={onIndentCode}
        onOpenAssistant={onOpenAssistant}
        setCells={setCells}
        onOutputPredicateChange={onOutputPredicateChange}
        onCellTypeChange={onCellTypeChange}
        onRenameConcept={onRenameConcept}
        groupNames={groupNames}
        onAddCellToGroup={onAddCellToGroup}
        onRemoveCellFromGroup={onRemoveCellFromGroup}
        defaultView={bottomTab}
        onViewChange={onBottomTabChange}
        splitLayout={expanded}
      />
    );
  }

  if (cell.conceptType === "sql") {
    return (
      <QuerySqlCell
        key={cell.id}
        cell={{ ...cell, autoOpen: true }}
        index={0}
        extensions={extensionsWithoutLinter}
        editorTheme={editorTheme}
        onCodeChange={onCodeChange}
        onRunCell={onRunCell}
        onSaveCell={onSaveCell}
        onDeleteCell={onDeleteCell}
        onClearResults={onClearResults}
        onRestoreResults={onRestoreResults}
        onStopCell={onStopCell}
        onIndentCode={onIndentCode}
        onOpenAssistant={onOpenAssistant}
        setCells={setCells}
        onOutputPredicateChange={onOutputPredicateChange}
        onCellTypeChange={onCellTypeChange}
        onRenameConcept={onRenameConcept}
        groupNames={groupNames}
        onAddCellToGroup={onAddCellToGroup}
        onRemoveCellFromGroup={onRemoveCellFromGroup}
        defaultView={bottomTab}
        onViewChange={onBottomTabChange}
        splitLayout={expanded}
      />
    );
  }

  if (cell.conceptType === "cypher") {
    return (
      <QueryCypherCell
        key={cell.id}
        cell={{ ...cell, autoOpen: true }}
        index={0}
        extensions={extensionsWithoutLinter}
        editorTheme={editorTheme}
        onCodeChange={onCodeChange}
        onRunCell={onRunCell}
        onSaveCell={onSaveCell}
        onDeleteCell={onDeleteCell}
        onClearResults={onClearResults}
        onRestoreResults={onRestoreResults}
        onStopCell={onStopCell}
        onIndentCode={onIndentCode}
        onOpenAssistant={onOpenAssistant}
        setCells={setCells}
        onOutputPredicateChange={onOutputPredicateChange}
        onCellTypeChange={onCellTypeChange}
        onRenameConcept={onRenameConcept}
        groupNames={groupNames}
        onAddCellToGroup={onAddCellToGroup}
        onRemoveCellFromGroup={onRemoveCellFromGroup}
        defaultView={bottomTab}
        onViewChange={onBottomTabChange}
        splitLayout={expanded}
      />
    );
  }

  return (
    <QueryConceptCell
      key={cell.id}
      cell={{ ...cell, autoOpen: true }}
      index={0}
      extensions={extensionsWithLinter}
      editorTheme={editorTheme}
      onCodeChange={onCodeChange}
      onRunCell={onRunCell}
      onDeleteCell={onDeleteCell}
      onClearResults={onClearResults}
      onRestoreResults={onRestoreResults}
      onSaveCell={onSaveCell}
      onStopCell={onStopCell}
      onIndentCode={onIndentCode}
      onOpenAssistant={onOpenAssistant}
      setCells={setCells}
      onCellTypeChange={onCellTypeChange}
      onRenameConcept={onRenameConcept}
      groupNames={groupNames}
      onAddCellToGroup={onAddCellToGroup}
      onRemoveCellFromGroup={onRemoveCellFromGroup}
      defaultView={bottomTab}
      onViewChange={onBottomTabChange}
      splitLayout={expanded}
    />
  );
};

export type { SelectedCellEditorProps };
export default SelectedCellEditor;
