import { Loader2 } from "lucide-react";
import type React from "react";
import { useMemo } from "react";
import { useMyTeams } from "@/features/teams/hooks/useMyTeams";
import { useTeamsMembers } from "@/features/teams/hooks/useTeamsMembers";
import { useConceptRestrictions } from "../hooks/useConceptRestrictions";
import { useSharedOntologyContext } from "../hooks/useSharedOntologyContext";
import { useShareOutbox } from "../hooks/useShareOutbox";
import {
  OWNER_CALLER,
  type PermissionCaller,
  type RestrictionLevel,
  type ShareRole,
} from "../types";
import {
  type AccessRecipient,
  computeConceptAccess,
  type EffectiveAccess,
  normalizeLevel,
} from "../utils/conceptAccess.utils";
import AccessRosterRow from "./AccessRosterRow";
import RosterMemberSection, { type RosterSectionItem } from "./RosterMemberSection";

interface ConceptAccessRosterProps {
  ontologyId: string;
  predicateName: string;
  caller?: PermissionCaller;
  // Project owner id — shown as a dedicated "full access" row rather than a
  // resolved member row (they always have full access and can't be restricted).
  ownerSub?: string;
  // When provided, each restrictable member gets an inline dropdown to change
  // their concept-level permission. Omit for a read-only roster.
  onSetLevel?: (recipientSub: string, level: RestrictionLevel) => void | Promise<void>;
  onClearLevel?: (recipientSub: string) => void | Promise<void>;
  // Team-wide concept rule editing (the "Team" row above the user rows).
  onSetTeamLevel?: (teamId: string, level: RestrictionLevel) => void | Promise<void>;
  onClearTeamLevel?: (teamId: string) => void | Promise<void>;
  isBusy?: boolean;
}

const roleToLevel = (role: ShareRole): EffectiveAccess =>
  role === "editor" ? "read_write" : "read_only";

// Roster of who currently has access to a concept and at what effective level,
// computed client-side from the same endpoints the picker uses (backend
// resolution order — see conceptAccess.utils). When editing callbacks are
// supplied, each restrictable member row exposes a dropdown to change their
// concept-level permission directly.
const ConceptAccessRoster: React.FC<ConceptAccessRosterProps> = ({
  ontologyId,
  predicateName,
  caller = OWNER_CALLER,
  ownerSub,
  onSetLevel,
  onClearLevel,
  onSetTeamLevel,
  onClearTeamLevel,
  isBusy = false,
}) => {
  const { teams: myTeams } = useMyTeams();
  const { entries: outboxEntries } = useShareOutbox({ ontologyId });
  const { restrictions } = useConceptRestrictions({ ontologyId, caller });
  // A delegated team admin can't read the owner's outbox, so the team base role
  // isn't derivable from it — fall back to the recipient's own share row.
  // `sharedBy` identifies the project owner for the informational owner row.
  const { shareRole: contextShareRole, sharedBy } = useSharedOntologyContext();

  const sharedTeamIds = useMemo(() => {
    if (caller.mode === "team_admin") return [caller.teamId];
    return outboxEntries
      .filter((e) => e.share_type === "team")
      .map((e) => e.recipient_team_id ?? e.team_id)
      .filter((id): id is string => Boolean(id));
  }, [caller, outboxEntries]);

  const { members: teamMembers, isLoading } = useTeamsMembers(sharedTeamIds);

  const teamBaseFallback: ShareRole =
    caller.mode === "team_admin" ? (contextShareRole ?? "viewer") : "viewer";

  // The project owner is shown as a dedicated "full access" row (below), so it's
  // the only sub dropped from the resolved list to avoid a duplicate.
  const recipients = useMemo<AccessRecipient[]>(() => {
    const bySub = new Map<string, AccessRecipient>();

    const teamBaseByTeam = new Map<string, ShareRole>();
    for (const e of outboxEntries) {
      const teamId = e.recipient_team_id ?? e.team_id;
      if (e.share_type === "team" && teamId) teamBaseByTeam.set(teamId, e.share_role);
    }

    // Direct user shares (owner side only — a team admin's outbox is empty).
    for (const e of outboxEntries) {
      if (e.share_type === "team") continue;
      if (e.status !== "accepted" && e.status !== "pending") continue;
      if (e.recipient_sub === ownerSub) continue;
      bySub.set(e.recipient_sub, {
        sub: e.recipient_sub,
        label: `${e.recipient_username}@${e.recipient_organization}`,
        directRole: e.share_role,
      });
    }

    // Every member of the shared team(s) is shown — including the current user
    // and the team owner (this is an informational roster, not the restriction
    // picker). Members with no explicit rule resolve to the team base role.
    for (const m of teamMembers) {
      if (m.status !== "active" || m.user_id === ownerSub) continue;
      const teamBaseRole = teamBaseByTeam.get(m.teamId) ?? teamBaseFallback;
      const existing = bySub.get(m.user_id);
      if (existing) {
        existing.teamId = m.teamId;
        existing.teamBaseRole = teamBaseRole;
        continue;
      }
      bySub.set(m.user_id, {
        sub: m.user_id,
        label: `${m.username}@${m.organization}`,
        teamId: m.teamId,
        teamBaseRole,
      });
    }

    return [...bySub.values()];
  }, [outboxEntries, teamMembers, ownerSub, teamBaseFallback]);

  const rows = useMemo(
    () => computeConceptAccess(recipients, predicateName, restrictions),
    [recipients, predicateName, restrictions],
  );

  // A member with no direct share is only in the roster because they belong to
  // a shared team — surface that source ("via <team>") on their row instead of
  // listing them as if they were shared with individually.
  const viaTeamBySub = useMemo(() => {
    const teamNameById = new Map<string, string>();
    for (const e of outboxEntries) {
      const id = e.recipient_team_id ?? e.team_id;
      if (e.share_type === "team" && id) teamNameById.set(id, e.team_name ?? "Team");
    }
    if (caller.mode === "team_admin") {
      const t = myTeams.find((x) => x.id === caller.teamId);
      teamNameById.set(caller.teamId, t?.name ?? "Team");
    }
    const map = new Map<string, string>();
    for (const r of recipients) {
      if (r.directRole || !r.teamId) continue;
      map.set(r.sub, teamNameById.get(r.teamId) ?? "team");
    }
    return map;
  }, [recipients, outboxEntries, caller, myTeams]);

  // Explicit per-user concept rule for this predicate, keyed by sub. Drives the
  // dropdown's current value ("default" when the user inherits their level).
  const explicitBySub = useMemo(() => {
    const map = new Map<string, RestrictionLevel>();
    for (const r of restrictions) {
      if (r.scope !== "concept" || r.subject_type !== "user") continue;
      if (r.predicate_name !== predicateName) continue;
      map.set(r.recipient_sub ?? r.subject_id, normalizeLevel(r.level));
    }
    return map;
  }, [restrictions, predicateName]);

  // Team(s) the project is shared with, with their base role. Owner reads them
  // from the outbox team rows; a delegated admin manages their single team.
  const teamRows = useMemo(() => {
    const map = new Map<string, { id: string; name: string; baseRole: ShareRole }>();
    if (caller.mode === "team_admin") {
      const t = myTeams.find((x) => x.id === caller.teamId);
      map.set(caller.teamId, {
        id: caller.teamId,
        name: t?.name ?? "Team",
        baseRole: contextShareRole ?? "viewer",
      });
      return [...map.values()];
    }
    for (const e of outboxEntries) {
      if (e.share_type !== "team") continue;
      const id = e.recipient_team_id ?? e.team_id;
      if (!id) continue;
      map.set(id, { id, name: e.team_name ?? "Team", baseRole: e.share_role });
    }
    return [...map.values()];
  }, [caller, myTeams, contextShareRole, outboxEntries]);

  // Explicit team-wide concept rule for this predicate, keyed by team id.
  const teamExplicitById = useMemo(() => {
    const map = new Map<string, RestrictionLevel>();
    for (const r of restrictions) {
      if (r.scope !== "concept" || r.subject_type !== "team") continue;
      if (r.predicate_name !== predicateName) continue;
      map.set(r.subject_id, normalizeLevel(r.level));
    }
    return map;
  }, [restrictions, predicateName]);

  // Resolve a display label for the project owner (shown as "full access").
  const ownerLabel = useMemo(() => {
    if (!ownerSub) return null;
    if (sharedBy?.sub === ownerSub) return `${sharedBy.username}@${sharedBy.organization}`;
    const member = teamMembers.find((m) => m.user_id === ownerSub);
    if (member) return `${member.username}@${member.organization}`;
    const direct = outboxEntries.find((e) => e.recipient_sub === ownerSub);
    if (direct) return `${direct.recipient_username}@${direct.recipient_organization}`;
    return null;
  }, [ownerSub, sharedBy, teamMembers, outboxEntries]);

  if (isLoading) {
    return (
      <div className="flex items-center gap-2 px-1 py-2 text-xs text-muted-foreground">
        <Loader2 className="h-3 w-3 animate-spin" />
        Resolving access…
      </div>
    );
  }

  if (rows.length === 0 && teamRows.length === 0 && !ownerLabel) {
    return (
      <p className="px-1 py-2 text-xs text-muted-foreground">
        No users have access to this project yet.
      </p>
    );
  }

  const hasMembers = Boolean(ownerLabel) || rows.length > 0;

  const ownerNode = ownerLabel ? (
    <div className="flex items-center justify-between gap-2 rounded-md border border-border bg-card px-3 py-1.5">
      <span className="min-w-0 truncate text-xs text-foreground">{ownerLabel}</span>
      <span className="flex-shrink-0 rounded bg-green-100 px-1.5 py-0.5 text-[10px] font-medium text-green-700 dark:bg-green-900/20 dark:text-green-400">
        Owner · full access
      </span>
    </div>
  ) : null;

  const memberItems: RosterSectionItem[] = rows.map((row) => {
    const viaTeam = viaTeamBySub.get(row.sub);
    return {
      key: row.sub,
      searchText: `${row.label} ${viaTeam ?? ""}`.toLowerCase(),
      node: (
        <AccessRosterRow
          label={row.label}
          hint={viaTeam ? `via ${viaTeam}` : undefined}
          effectiveLevel={row.level}
          explicitLevel={explicitBySub.get(row.sub)}
          editable={Boolean(onSetLevel)}
          isBusy={isBusy}
          onSetLevel={(level) => onSetLevel?.(row.sub, level)}
          onClearLevel={() => onClearLevel?.(row.sub)}
        />
      ),
    };
  });

  return (
    <div className="flex flex-col gap-4">
      {teamRows.length > 0 && (
        <div className="flex flex-col gap-1">
          <p className="px-0.5 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
            Teams
          </p>
          {teamRows.map((team) => (
            <AccessRosterRow
              key={`team:${team.id}`}
              label={team.name}
              effectiveLevel={teamExplicitById.get(team.id) ?? roleToLevel(team.baseRole)}
              explicitLevel={teamExplicitById.get(team.id)}
              editable={Boolean(onSetTeamLevel)}
              isBusy={isBusy}
              onSetLevel={(level) => onSetTeamLevel?.(team.id, level)}
              onClearLevel={() => onClearTeamLevel?.(team.id)}
            />
          ))}
        </div>
      )}

      {hasMembers && (
        <RosterMemberSection title="Members" items={memberItems} leading={ownerNode} />
      )}
    </div>
  );
};

export default ConceptAccessRoster;
