import { Maximize2, Minimize2, X } from "lucide-react";
import { Button } from "@/shared/components/ui/button";

interface LineagePanelHeaderProps {
  /** Whether to show the unsaved/running counts (hidden for datasource panels). */
  showCounts: boolean;
  unsavedCount: number;
  runningCount: number;
  isExpanded: boolean;
  onToggleExpand: () => void;
  onClose: () => void;
}

/** Header bar of the lineage detail panel: status counts + expand/close. */
export function LineagePanelHeader({
  showCounts,
  unsavedCount,
  runningCount,
  isExpanded,
  onToggleExpand,
  onClose,
}: LineagePanelHeaderProps) {
  return (
    <div className="flex h-9 flex-shrink-0 items-center justify-between border-b border-border bg-muted pl-3 pr-1.5">
      <div className="flex items-center gap-3">
        {showCounts && (
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            {unsavedCount > 0 && (
              <span className="text-amber-600 dark:text-amber-400 font-medium">
                {unsavedCount} unsaved
              </span>
            )}
            {runningCount > 0 && (
              <span className="text-blue-600 dark:text-blue-400 font-medium flex items-center gap-1">
                <span className="inline-block h-1.5 w-1.5 rounded-full bg-blue-500 animate-pulse" />
                {runningCount} running
              </span>
            )}
          </div>
        )}
      </div>
      <div className="flex items-center gap-0.5">
        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={onToggleExpand}
          title={isExpanded ? "Collapse panel" : "Expand panel"}
        >
          {isExpanded ? (
            <Minimize2 className="h-3.5 w-3.5" />
          ) : (
            <Maximize2 className="h-3.5 w-3.5" />
          )}
        </Button>
        <Button variant="ghost" size="icon" className="h-6 w-6" onClick={onClose}>
          <X className="h-3.5 w-3.5" />
        </Button>
      </div>
    </div>
  );
}
