import React, { useCallback, useMemo, useState } from "react";

import ContentContainer from "./ContentContainer";
import ContentRenderer from "./ContentRenderer";
import { PageHeader, type PageHeaderProps } from "./PageHeader";

interface MainContentProps {
  activeTab: string;
  code: string;
  setCode: (code: string) => void;
  sidebarVisible: boolean;
  sidebarCollapsed?: boolean;
  onToggleSidebar: () => void;
  onBackFromSettings?: () => void;
  previousTab?: string;
  header?: PageHeaderProps;
}

const MainContent = React.memo(
  ({
    activeTab,
    code,
    setCode,
    sidebarVisible,
    sidebarCollapsed = false,
    onToggleSidebar,
    onBackFromSettings,
    previousTab,
    header,
  }: MainContentProps) => {
    const [aiSuggestionsEnabled, setAiSuggestionsEnabled] = useState(false);
    const [explainEnabled, setExplainEnabled] = useState(false);
    const [wordWrap, setWordWrap] = useState(false);

    const handleAiSuggestionsToggle = useCallback((enabled: boolean) => {
      setAiSuggestionsEnabled(enabled);
    }, []);

    const handleExplainToggle = useCallback((enabled: boolean) => {
      setExplainEnabled(enabled);
    }, []);

    const handleWordWrapChange = useCallback((enabled: boolean) => {
      setWordWrap(enabled);
    }, []);

    const mainContentClasses = useMemo(() => {
      if (!sidebarVisible) return "";
      return sidebarCollapsed ? "ml-14" : "ml-60";
    }, [sidebarVisible, sidebarCollapsed]);

    return (
      <div
        className={`flex-1 ${mainContentClasses} flex flex-col overflow-hidden transition-all duration-300`}
      >
        {activeTab !== "app" && <PageHeader {...(header ?? {})} />}
        <div className="flex-1 min-h-0">
          <ContentContainer
            isLineageView={
              activeTab === "ontology" || activeTab === "lineage" || activeTab === "document"
            }
            sidebarHidden={!sidebarVisible}
          >
            <ContentRenderer
              activeTab={activeTab}
              code={code}
              setCode={setCode}
              explainEnabled={explainEnabled}
              onAiSuggestionsToggle={handleAiSuggestionsToggle}
              aiSuggestionsEnabled={aiSuggestionsEnabled}
              onExplainToggle={handleExplainToggle}
              wordWrap={wordWrap}
              onWordWrapChange={handleWordWrapChange}
              onBackFromSettings={onBackFromSettings}
              previousTab={previousTab}
              onToggleSidebar={onToggleSidebar}
              sidebarVisible={sidebarVisible}
            />
          </ContentContainer>
        </div>
      </div>
    );
  },
);

MainContent.displayName = "MainContent";

export default MainContent;
