import { useCallback, useMemo, useState } from "react";
import { toast } from "sonner";

import { DataClient } from "@/features/data-sources/api/DataClient";

export interface PendingContextUpload {
  id: string;
  fileName: string;
  fileSize: number;
  /** Server path returned by /data/files/upload; null while the upload is in flight. */
  filePath: string | null;
  isUploading: boolean;
  error?: string;
}

interface UseContextUploadReturn {
  attachments: PendingContextUpload[];
  attach: (file: File) => Promise<void>;
  remove: (id: string) => void;
  clear: () => void;
  /** Paths to ingest as context notes. Only completed (non-error) uploads. */
  readyPaths: string[];
  isUploading: boolean;
}

const MAX_BYTES = 50 * 1024 * 1024;

export function useContextUpload(): UseContextUploadReturn {
  const [attachments, setAttachments] = useState<PendingContextUpload[]>([]);
  const dataClient = useMemo(() => new DataClient(), []);

  const attach = useCallback(
    async (file: File) => {
      if (file.size > MAX_BYTES) {
        const mb = (file.size / 1024 / 1024).toFixed(1);
        toast.error(`File too large: ${mb} MB (limit 50 MB)`);
        return;
      }
      const id = crypto.randomUUID();
      setAttachments((prev) => [
        ...prev,
        {
          id,
          fileName: file.name,
          fileSize: file.size,
          filePath: null,
          isUploading: true,
        },
      ]);
      try {
        const result = await dataClient.uploadFile(file);
        setAttachments((prev) =>
          prev.map((a) =>
            a.id === id
              ? {
                  ...a,
                  filePath: result.filePath,
                  isUploading: false,
                }
              : a,
          ),
        );
      } catch (err) {
        const message = err instanceof Error ? err.message : "Upload failed";
        setAttachments((prev) =>
          prev.map((a) => (a.id === id ? { ...a, isUploading: false, error: message } : a)),
        );
        toast.error(`Could not attach "${file.name}": ${message}`);
      }
    },
    [dataClient],
  );

  const remove = useCallback((id: string) => {
    setAttachments((prev) => prev.filter((a) => a.id !== id));
  }, []);

  const clear = useCallback(() => setAttachments([]), []);

  const readyPaths = useMemo(
    () =>
      attachments
        .filter((a) => a.filePath && !a.isUploading && !a.error)
        .map((a) => a.filePath as string),
    [attachments],
  );

  const isUploading = attachments.some((a) => a.isUploading);

  return { attachments, attach, remove, clear, readyPaths, isUploading };
}
