import { collectBindingRefs } from "../../../runtime/templateResolver";
import type { RunGroupDef } from "../../../schema/appDefinition.types";

interface VariableTriggersHintProps {
  runGroups: RunGroupDef[];
  variable?: string;
}

/** Run groups whose params/facts bindings read this variable (root or dotted). */
export function groupsReadingVariable(
  runGroups: RunGroupDef[],
  variable: string | undefined,
): RunGroupDef[] {
  if (!variable) return [];
  return runGroups.filter((group) =>
    collectBindingRefs([group.params, group.facts]).some(
      (ref) => ref === variable || ref.split(".")[0] === variable,
    ),
  );
}

function groupName(group: RunGroupDef): string {
  return group.label || group.id;
}

/**
 * Makes the selection→run wiring legible: under an input or a selectable
 * table, say which run groups its variable drives (auto groups re-run on
 * change; other triggers read it when they fire).
 */
export function VariableTriggersHint({ runGroups, variable }: VariableTriggersHintProps) {
  const consumers = groupsReadingVariable(runGroups, variable);
  if (consumers.length === 0) return null;

  const autoNames = consumers
    .filter((group) => group.trigger === "auto")
    .map(groupName)
    .join(", ");
  const passiveNames = consumers
    .filter((group) => group.trigger !== "auto")
    .map(groupName)
    .join(", ");

  return (
    <p className="text-[10px] text-muted-foreground leading-relaxed">
      {autoNames && (
        <>
          Selecting a value automatically runs: <span className="font-medium">{autoNames}</span>.{" "}
        </>
      )}
      {passiveNames && (
        <>
          Also read by: <span className="font-medium">{passiveNames}</span>.
        </>
      )}
    </p>
  );
}
