interface CompanyContextTextPanelProps {
  value: string;
  onChange: (next: string) => void;
  disabled: boolean;
  minChars: number;
}

const PLACEHOLDER = `Examples of what's useful here:

• What does your company do, in one paragraph?
• What's your role, and what kinds of questions do you usually answer with data?
• Any conventions worth remembering — fiscal year, default currency, what "active customer" means in your team?
• Any analyses you're starting with, or known data pitfalls the assistant should be aware of?

Paste a rough draft. You can edit, split, or add more notes later on the Context page.`;

export function CompanyContextTextPanel({
  value,
  onChange,
  disabled,
  minChars,
}: CompanyContextTextPanelProps) {
  const trimmedLength = value.trim().length;
  const tooShort = trimmedLength > 0 && trimmedLength < minChars;

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => onChange(e.target.value);

  return (
    <div className="space-y-2">
      <h3 className="text-sm font-medium text-foreground">Paste text</h3>
      <textarea
        value={value}
        onChange={handleChange}
        disabled={disabled}
        placeholder={PLACEHOLDER}
        className="min-h-[200px] w-full resize-y rounded-md border border-input bg-background p-3 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-primary disabled:opacity-60"
      />
      <div className="text-xs text-muted-foreground">
        {trimmedLength} character{trimmedLength === 1 ? "" : "s"}
        {tooShort && (
          <span className="ml-1.5 text-amber-600 dark:text-amber-400">
            (need at least {minChars} to save as text)
          </span>
        )}
      </div>
    </div>
  );
}
