import { useEffect, useMemo, useState } from "react";

import { CodeClient } from "@/features/concept-editor/api/CodeClient";
import {
  extractPromptReferences,
  setPromptReferenceState,
} from "@/features/concept-editor/components/code-editor/promptReferences";
import { cellEditorViews } from "@/features/concept-editor/components/query/components/CellEditor";
import { useDebouncedValue } from "@/shared/hooks/ui/useDebouncedValue";

const codeClient = new CodeClient();

/** Matches the debounce BindDataSelector uses for the same endpoint. */
const ANALYZE_SETTLE_MS = 500;

export interface PromptReference {
  name: string;
  resolved: boolean;
}

/**
 * The `{{name}}` references in a prompt, each marked resolved or not.
 *
 * The names are read locally so the list is instant while typing; whether each
 * one resolves is only knowable server-side, through the same helper the save
 * path uses to derive binds — so a reference shown as resolved here is one the
 * save will actually bind. Until the first answer arrives nothing is marked
 * broken, which is what stops chips flashing red mid-word.
 */
export function usePromptReferences(cellId: string, prompt: string, conceptName?: string) {
  const [unresolved, setUnresolved] = useState<string[]>([]);
  const [checked, setChecked] = useState(false);
  const settledPrompt = useDebouncedValue(prompt, ANALYZE_SETTLE_MS);

  const names = useMemo(() => extractPromptReferences(prompt), [prompt]);

  useEffect(() => {
    if (extractPromptReferences(settledPrompt).length === 0) {
      setUnresolved([]);
      setChecked(true);
      return;
    }
    let active = true;
    codeClient.analyzeCode(settledPrompt, "llm", conceptName).then((result) => {
      if (!active) return;
      setUnresolved(result.unresolvedReferences);
      setChecked(true);
    });
    return () => {
      active = false;
    };
  }, [settledPrompt, conceptName]);

  // Push the verdict into the open editor. CellEditor is memoized on a prop
  // list that excludes `extensions`, so a re-render would not repaint the
  // chips; a state effect reaches the live view regardless.
  useEffect(() => {
    cellEditorViews.get(cellId)?.dispatch({
      effects: setPromptReferenceState.of({ unresolved, checked }),
    });
  }, [cellId, unresolved, checked, names]);

  const references: PromptReference[] = useMemo(
    () => names.map((name) => ({ name, resolved: !checked || !unresolved.includes(name) })),
    [names, checked, unresolved],
  );

  return { references, checked };
}
