import { CreditCard } from "lucide-react";
import { useNavigate } from "react-router-dom";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";

export interface PaidComputeRequiredDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const BILLING_ROUTE = "/settings/billing";

export const PaidComputeRequiredDialog = ({
  open,
  onOpenChange,
}: PaidComputeRequiredDialogProps) => {
  const navigate = useNavigate();

  const handleSetUpBilling = () => {
    onOpenChange(false);
    navigate(BILLING_ROUTE);
  };

  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle className="flex items-center gap-2">
            <CreditCard className="h-5 w-5" />
            Set up billing to use paid compute
          </AlertDialogTitle>
          <AlertDialogDescription>
            Starting a paid machine requires an active subscription. Set up billing now to continue,
            or you can come back later.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Not now</AlertDialogCancel>
          <AlertDialogAction onClick={handleSetUpBilling}>Set up billing</AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
};
