import React from "react";
import QueryLanguageCell from "./QueryLanguageCell";
import type { QueryConceptCellProps } from "./types/editorTypes";

// Extended props for Cypher cell - adds handlers for concept name changes
interface QueryCypherCellProps extends QueryConceptCellProps {
  onOutputPredicateChange?: (cellId: string, outputPredicate: string) => void;
}

// Cypher cells share their entire shell with SQL cells; the implementation lives
// in QueryLanguageCell, parametrized by `kind`.
const QueryCypherCell: React.FC<QueryCypherCellProps> = (props) => (
  <QueryLanguageCell {...props} kind="cypher" />
);

export default React.memo(QueryCypherCell);
