import { useEffect, useState } from "react";
import { supabase } from "@/shared/integrations/supabase/client";

type AalLevel = "aal1" | "aal2";

export interface MfaAalState {
  currentLevel: AalLevel | null;
  nextLevel: AalLevel | null;
  isLoading: boolean;
}

/**
 * Subscribes to Supabase auth changes and keeps the Authenticator Assurance Level
 * in sync. Used by `RequireAuth` to decide whether to force the user through the
 * MFA challenge before granting dashboard access.
 *
 * Never check "does the user have a verified factor" manually — always rely on
 * `nextLevel === 'aal2'` while `currentLevel === 'aal1'` to decide that a
 * challenge is required. This matches how Supabase reasons about step-up auth.
 */
export function useMfaAal(): MfaAalState {
  const [state, setState] = useState<MfaAalState>({
    currentLevel: null,
    nextLevel: null,
    isLoading: true,
  });

  useEffect(() => {
    let isCancelled = false;

    const refresh = async () => {
      const { data } = await supabase.auth.mfa.getAuthenticatorAssuranceLevel();
      if (isCancelled) return;
      setState({
        currentLevel: (data?.currentLevel as AalLevel | null) ?? null,
        nextLevel: (data?.nextLevel as AalLevel | null) ?? null,
        isLoading: false,
      });
    };

    refresh();

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event) => {
      if (event === "SIGNED_IN" || event === "SIGNED_OUT" || event === "MFA_CHALLENGE_VERIFIED") {
        refresh();
      }
    });

    return () => {
      isCancelled = true;
      subscription.unsubscribe();
    };
  }, []);

  return state;
}

export function requiresMfaChallenge(state: MfaAalState): boolean {
  return state.nextLevel === "aal2" && state.currentLevel === "aal1";
}
