import type { OntologySnapshotMeta } from "@/features/ontologies/api";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";

interface SnapshotConfirmDialogsProps {
  confirmRestore: OntologySnapshotMeta | null;
  confirmDelete: OntologySnapshotMeta | null;
  safetySnapshot: boolean;
  isRestoring: boolean;
  isDeleting: boolean;
  onSafetySnapshotChange: (checked: boolean) => void;
  onCancelRestore: () => void;
  onConfirmRestore: () => void;
  onCancelDelete: () => void;
  onConfirmDelete: () => void;
}

export function SnapshotConfirmDialogs({
  confirmRestore,
  confirmDelete,
  safetySnapshot,
  isRestoring,
  isDeleting,
  onSafetySnapshotChange,
  onCancelRestore,
  onConfirmRestore,
  onCancelDelete,
  onConfirmDelete,
}: SnapshotConfirmDialogsProps) {
  return (
    <>
      <AlertDialog open={!!confirmRestore} onOpenChange={onCancelRestore}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Restore snapshot?</AlertDialogTitle>
            <AlertDialogDescription>
              This will overwrite the current project state with the selected snapshot.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <label className="flex items-center gap-2 px-1 text-sm text-foreground">
            <input
              type="checkbox"
              checked={safetySnapshot}
              onChange={(e) => onSafetySnapshotChange(e.target.checked)}
              className="h-4 w-4 rounded border-border"
            />
            Create a safety snapshot before restoring
          </label>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={onConfirmRestore} disabled={isRestoring}>
              {isRestoring ? "Restoring…" : "Restore"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={!!confirmDelete} onOpenChange={onCancelDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete snapshot?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. The snapshot will be permanently removed.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={onConfirmDelete} disabled={isDeleting}>
              {isDeleting ? "Deleting…" : "Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}
