import { Database, Parentheses, Share2, Sparkles, StickyNote } from "lucide-react";
import type React from "react";
import type { ConceptCell } from "@/features/concept-editor/types";
import PythonIcon from "@/shared/components/icons/PythonIcon";

type IconComponent = React.ComponentType<{ className?: string }>;
const UNGROUPED_SENTINEL = "group_id";

export function cellGroupOrNull(cell: ConceptCell): string | null {
  if (!cell.group || cell.group === UNGROUPED_SENTINEL) return null;
  return cell.group;
}

// Icon + accent color for a concept tree row, by concept type. Pure helpers kept
// out of the component so the row stays flat (no chained ternaries in render).
//
// The two non-executable kinds reuse the icons their own cell headers show, so a
// row and the cell it opens read as the same thing: a note for the window onto
// unstructured context, sparkles for the generative one.
export function conceptIcon(conceptType: ConceptCell["conceptType"]): IconComponent {
  if (conceptType === "python") return PythonIcon;
  if (conceptType === "sql") return Database;
  if (conceptType === "cypher") return Share2;
  if (conceptType === "context") return StickyNote;
  if (conceptType === "llm") return Sparkles;
  return Parentheses;
}

export function conceptIconColorClass(conceptType: ConceptCell["conceptType"]): string {
  if (conceptType === "python") return "text-python-icon";
  if (conceptType === "sql") return "text-green-600 dark:text-green-400";
  if (conceptType === "cypher") return "text-purple-600 dark:text-purple-400";
  if (conceptType === "context") return "text-amber-500 dark:text-amber-400";
  if (conceptType === "llm") return "text-blue-600 dark:text-blue-400";
  return "text-orange-600 dark:text-orange-400";
}
