import type { FilterOperator, OrderByItem } from "./tableOutput.types";

export const OPERATOR_LABELS: Record<FilterOperator, string> = {
  contains: "Contains",
  equals: "Equals",
  not_equals: "Not equals",
  greater_than: "Greater than",
  less_than: "Less than",
  greater_than_or_equal: "Greater or equal",
  less_than_or_equal: "Less or equal",
  starts_with: "Starts with",
  ends_with: "Ends with",
  is_null: "Is null",
  is_not_null: "Is not null",
};

export const VALUELESS_OPERATORS: FilterOperator[] = ["is_null", "is_not_null"];

export const PAGE_SIZE_OPTIONS = [10, 25, 50, 100, 250, 500, 1000, 2500, 5000];

export function operatorNeedsValue(operator: FilterOperator): boolean {
  return !VALUELESS_OPERATORS.includes(operator);
}

export function getColumnSortDirection(
  orderBy: OrderByItem[] | undefined,
  columnIndex: number,
): "asc" | "desc" | null {
  if (!orderBy) return null;
  const item = orderBy.find((o) => o.position === columnIndex);
  return item ? item.direction : null;
}

export function toggleColumnSort(
  orderBy: OrderByItem[] | undefined,
  columnIndex: number,
  direction: "asc" | "desc" | null,
): OrderByItem[] {
  const without = (orderBy ?? []).filter((o) => o.position !== columnIndex);
  if (!direction) return without;
  return [...without, { position: columnIndex, direction }];
}
