import { Paperclip, Send, Square } from "lucide-react";
import type React from "react";
import { useCallback, useRef } from "react";
import { Button } from "@/shared/components/ui/button";
import type { FocusedWidgetRef } from "../agentContext";
import type { PendingAttachment } from "../hooks/useChatAttachments";
import { useFileDropZone } from "../hooks/useFileDropZone";
import { useVisionSupport } from "../hooks/useVisionSupport";
import { ChatAttachmentChips } from "./ChatAttachmentChips";
import { ChatDropOverlay } from "./ChatDropOverlay";
import { FocusedWidgetChip } from "./FocusedWidgetChip";
import { VisionWarning } from "./VisionWarning";

interface ChatInputBoxProps {
  input: string;
  onInputChange: (e: React.ChangeEvent<HTMLTextAreaElement>) => void;
  onKeyDown: (e: React.KeyboardEvent<HTMLTextAreaElement>) => void;
  textareaRef: React.RefObject<HTMLTextAreaElement>;
  manualHeight: number | null;
  isLoading: boolean;
  attachments: PendingAttachment[];
  onRemoveAttachment: (id: string) => void;
  onAttachFile: (file: File) => void;
  focusedWidget: FocusedWidgetRef | null;
  onClearFocusedWidget: () => void;
  onSend: () => void;
  onAbort: () => void;
  sendDisabled: boolean;
  sendTitle: string;
  usageText: string | null;
  usageWarning: boolean;
}

// The assistant composer: one rounded card holding attachment/widget chips, a
// borderless auto-growing textarea, and a bottom toolbar (attach + send). Mirrors
// the Home chat input so both surfaces share a single polished pattern.
export function ChatInputBox({
  input,
  onInputChange,
  onKeyDown,
  textareaRef,
  manualHeight,
  isLoading,
  attachments,
  onRemoveAttachment,
  onAttachFile,
  focusedWidget,
  onClearFocusedWidget,
  onSend,
  onAbort,
  sendDisabled,
  sendTitle,
  usageText,
  usageWarning,
}: ChatInputBoxProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFiles = useCallback(
    (files: File[]) => {
      for (const file of files) onAttachFile(file);
    },
    [onAttachFile],
  );
  const { isDragging, dropZoneProps, handlePaste } = useFileDropZone(handleFiles, isLoading);
  const { isTextOnly, model } = useVisionSupport();
  const hasImage = attachments.some((a) => a.kind === "image" && !a.error);

  const handleAttachClick = () => fileInputRef.current?.click();
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    handleFiles(Array.from(e.target.files ?? []));
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  return (
    // Drop target for attachments; the paperclip button is the keyboard path.
    <div
      {...dropZoneProps}
      className="relative flex flex-col gap-2 rounded-2xl border border-input bg-card p-3 shadow-sm transition-shadow focus-within:ring-1 focus-within:ring-ring"
    >
      <ChatDropOverlay isVisible={isDragging} />
      {attachments.length > 0 && (
        <ChatAttachmentChips attachments={attachments} onRemove={onRemoveAttachment} />
      )}
      <VisionWarning isVisible={hasImage && isTextOnly} model={model} />
      {focusedWidget && <FocusedWidgetChip widget={focusedWidget} onClear={onClearFocusedWidget} />}

      <textarea
        ref={textareaRef}
        value={input}
        onChange={onInputChange}
        onKeyDown={onKeyDown}
        onPaste={handlePaste}
        placeholder="Ask anything… (Shift+Enter for new line)"
        disabled={isLoading}
        rows={3}
        style={manualHeight ? { height: manualHeight } : undefined}
        className="w-full resize-none border-0 bg-transparent px-1 text-sm leading-relaxed placeholder:text-muted-foreground focus:outline-none focus:ring-0 disabled:opacity-50 [-webkit-font-smoothing:antialiased] min-h-[64px] max-h-[300px]"
      />

      <input
        ref={fileInputRef}
        type="file"
        multiple
        className="hidden"
        onChange={handleFileChange}
      />

      <div className="flex items-center justify-between gap-2">
        {usageText ? (
          <span
            className={
              usageWarning
                ? "text-[11px] text-red-500 dark:text-red-400"
                : "text-[11px] text-muted-foreground"
            }
          >
            {usageText}
          </span>
        ) : (
          <span />
        )}
        <div className="flex items-center gap-1">
          <Button
            size="icon"
            variant="ghost"
            className="h-8 w-8 text-muted-foreground hover:text-foreground"
            onClick={handleAttachClick}
            disabled={isLoading}
            title="Attach a file"
          >
            <Paperclip className="h-4 w-4" />
          </Button>
          {isLoading ? (
            <Button
              size="icon"
              variant="destructive"
              className="h-8 w-8"
              onClick={onAbort}
              title="Stop"
            >
              <Square className="h-3.5 w-3.5 fill-current" />
            </Button>
          ) : (
            <Button
              size="icon"
              className="h-8 w-8"
              onClick={onSend}
              disabled={sendDisabled}
              title={sendTitle}
            >
              <Send className="h-4 w-4" />
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}
