import { Loader2, Ticket, Users2 } from "lucide-react";
import type React from "react";
import { useTeamMembers } from "@/features/teams/hooks/useTeamMembers";
import type { TeamMembershipRow } from "@/features/teams/types";
import { teamRoleCapabilities } from "@/features/teams/utils/teams.utils";
import TeamMemberRow from "./TeamMemberRow";

interface TeamMembersTabProps {
  team: TeamMembershipRow;
  callerUserId: string;
}

// Active roster + role / seat controls. Kept self-contained (calls its own
// useTeamMembers) so it can render as either a whole panel body (non-admin
// callers who never see the Invitations tab) or as one tab in the admin
// two-tab layout — the parent decides. RQ dedupes the query so multiple
// mounts of this hook cost nothing beyond the state overhead.
const TeamMembersTab: React.FC<TeamMembersTabProps> = ({ team, callerUserId }) => {
  const capabilities = teamRoleCapabilities(team.role);
  const {
    members,
    isLoading,
    changeRole,
    isChangingRole,
    updatingUserId,
    remove,
    isRemoving,
    removingUserId,
    grantSeat,
    releaseSeat,
    isUpdatingSeat,
    seatUpdatingUserId,
  } = useTeamMembers(team.id);

  // Plan seat capacity. `team.seats` / `team.seats_used` are only present for
  // owner/admin callers, but we compute a member-count fallback for the
  // "used" tally to keep the counter consistent while the cache is being
  // reconciled (e.g. right after a seat mutation). `canGrantMore` decides
  // whether the "Grant seat" button is enabled on rows without a seat.
  const planSeats = typeof team.seats === "number" ? team.seats : null;
  const seatsUsed =
    typeof team.seats_used === "number"
      ? team.seats_used
      : members.filter((m) => m.seat_granted).length;
  const canGrantMoreSeats = planSeats === null ? true : seatsUsed < planSeats;

  return (
    <section className="space-y-3">
      <div className="flex items-center justify-between gap-3">
        <div>
          <h3 className="text-sm font-semibold text-foreground">Members</h3>
          <p className="text-xs text-muted-foreground">
            {members.length === 0
              ? "No active members yet"
              : `${members.length} member${members.length !== 1 ? "s" : ""}`}
          </p>
        </div>
        {capabilities.canManageSeats && planSeats !== null && (
          <div
            className="flex items-center gap-1.5 rounded-md border border-border bg-muted/30 px-2.5 py-1 text-xs text-muted-foreground"
            title="Plan seats used across the team"
          >
            <Ticket className="h-3.5 w-3.5" />
            <span>
              <span className="font-medium text-foreground">{seatsUsed}</span> / {planSeats} seats
              used
            </span>
          </div>
        )}
      </div>

      {isLoading ? (
        <div className="flex items-center gap-2 py-6 text-xs text-muted-foreground">
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
          Loading members...
        </div>
      ) : members.length === 0 ? (
        <div className="flex flex-col items-center justify-center gap-2 rounded-md border border-dashed border-border bg-muted/30 px-3 py-8 text-center">
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-secondary">
            <Users2 className="h-4 w-4 text-muted-foreground" />
          </div>
          <p className="text-xs text-muted-foreground">Invite someone to get started.</p>
        </div>
      ) : (
        <div className="space-y-2">
          {members.map((member) => (
            <TeamMemberRow
              key={member.user_id}
              member={member}
              callerRole={team.role}
              callerUserId={callerUserId}
              onChangeRole={(userId, role) => changeRole({ userId, role })}
              onRemove={remove}
              onGrantSeat={grantSeat}
              onReleaseSeat={releaseSeat}
              isUpdatingRole={isChangingRole && updatingUserId === member.user_id}
              isRemoving={isRemoving && removingUserId === member.user_id}
              isUpdatingSeat={isUpdatingSeat && seatUpdatingUserId === member.user_id}
              canGrantMoreSeats={canGrantMoreSeats}
            />
          ))}
        </div>
      )}
    </section>
  );
};

export default TeamMembersTab;
