import { Activity, RefreshCw } from "lucide-react";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

interface EngineMonitorHeaderProps {
  isRunning: boolean;
  engineAlive: boolean;
  sparkActive: boolean;
  isLoading: boolean;
  runningTaskCount: number;
  executorCount: number;
  lastUpdatedAt: number | null;
  onRefresh: () => void;
}

type EngineVariant = "up" | "connecting" | "down";

interface LiveIndicatorProps {
  variant: EngineVariant;
}

function formatSince(ts: number | null): string {
  if (!ts) return "—";
  const seconds = Math.max(0, Math.round((Date.now() - ts) / 1000));
  if (seconds < 60) return `${seconds}s ago`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes}m ago`;
}

const EngineStatusIndicator: React.FC<LiveIndicatorProps> = ({ variant }) => {
  if (variant === "down") {
    return <span className="inline-block h-2 w-2 rounded-full bg-muted-foreground/40" />;
  }
  const colorClass = variant === "up" ? "bg-emerald-500" : "bg-amber-500";
  return (
    <span className="relative inline-flex h-2 w-2">
      <span
        className={`absolute inline-flex h-full w-full rounded-full opacity-60 animate-ping ${colorClass}`}
      />
      <span className={`relative inline-flex h-2 w-2 rounded-full ${colorClass}`} />
    </span>
  );
};

const SparkIdlePill: React.FC = () => (
  <span className="inline-flex items-center gap-1.5 rounded-full border border-border/60 bg-background/60 px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
    <span className="inline-block h-1.5 w-1.5 rounded-full bg-muted-foreground/40" />
    Spark idle
  </span>
);

const SparkActivePill: React.FC<{ runningTaskCount: number; executorCount: number }> = ({
  runningTaskCount,
  executorCount,
}) => (
  <span className="inline-flex items-center gap-1.5 rounded-full border border-emerald-500/30 bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold text-emerald-700 dark:text-emerald-400">
    <span className="relative inline-flex h-1.5 w-1.5">
      <span className="absolute inline-flex h-full w-full rounded-full bg-emerald-500 opacity-60 animate-ping" />
      <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-emerald-500" />
    </span>
    Spark active
    <span className="text-emerald-600/80 dark:text-emerald-400/80 font-normal">
      · {runningTaskCount} running · {executorCount} workers
    </span>
  </span>
);

const EngineMonitorHeader: React.FC<EngineMonitorHeaderProps> = ({
  isRunning,
  engineAlive,
  sparkActive,
  isLoading,
  runningTaskCount,
  executorCount,
  lastUpdatedAt,
  onRefresh,
}) => {
  const hasEverLoaded = lastUpdatedAt !== null;
  const variant: EngineVariant = engineAlive ? "up" : hasEverLoaded ? "down" : "connecting";
  const engineLabel = engineAlive
    ? "Engine online"
    : hasEverLoaded
      ? "Engine offline"
      : isRunning
        ? "Starting..."
        : "Connecting...";

  return (
    <div className="flex items-center gap-2 px-3 py-2 border-b border-border/40 bg-gradient-to-b from-muted/40 to-muted/20">
      <span className="flex h-6 w-6 items-center justify-center rounded-md bg-primary/10 text-primary ring-1 ring-primary/20">
        <Activity className="h-3.5 w-3.5" />
      </span>
      <div className="flex items-center gap-2 flex-1 min-w-0">
        <span className="text-sm font-semibold text-foreground tracking-tight">
          Engine activity
        </span>
        <EngineStatusIndicator variant={variant} />
        <span className="text-xs text-muted-foreground">{engineLabel}</span>
        {sparkActive ? (
          <SparkActivePill runningTaskCount={runningTaskCount} executorCount={executorCount} />
        ) : engineAlive ? (
          <SparkIdlePill />
        ) : null}
        {isLoading ? <PrometheuxSpinner size={16} className="ml-1" /> : null}
      </div>
      <span className="text-[11px] text-muted-foreground/70 tabular-nums">
        {formatSince(lastUpdatedAt)}
      </span>
      <button
        type="button"
        onClick={onRefresh}
        className="p-1.5 text-muted-foreground hover:text-foreground rounded-md hover:bg-accent transition-colors"
        title="Refresh now"
      >
        <RefreshCw className={`h-3.5 w-3.5 ${isLoading ? "animate-spin" : ""}`} />
      </button>
    </div>
  );
};

export default EngineMonitorHeader;
