import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import type { IssueTokenData } from "./apiKeys.types";
import { AuthApiUnauthorizedError, authApiClient } from "./authApiClient";
import { API_KEYS_QUERY_KEY } from "./useApiKeys";

interface CreateQuickKeyInput {
  name: string;
  expiresInMinutes: number;
}

export interface UseCreateQuickApiKeyReturn {
  isCreating: boolean;
  createKey: (input: CreateQuickKeyInput) => Promise<IssueTokenData | null>;
  revokeKey: (jti: string) => Promise<void>;
}

function errorMessage(error: unknown, fallback: string): string {
  return error instanceof Error ? error.message : fallback;
}

export function useCreateQuickApiKey(): UseCreateQuickApiKeyReturn {
  const queryClient = useQueryClient();
  const { signOut } = useAuth();
  const [isCreating, setIsCreating] = useState(false);

  const handleUnauthorized = useCallback(
    (error: unknown): boolean => {
      if (!(error instanceof AuthApiUnauthorizedError)) return false;
      toast.error("Your session has expired. Please sign in again.");
      void signOut();
      return true;
    },
    [signOut],
  );

  const createKey = useCallback(
    async (input: CreateQuickKeyInput): Promise<IssueTokenData | null> => {
      setIsCreating(true);
      try {
        const data = await authApiClient.issueToken({
          name: input.name,
          expiresInMinutes: input.expiresInMinutes,
        });
        queryClient.invalidateQueries({ queryKey: API_KEYS_QUERY_KEY });
        return data;
      } catch (error) {
        if (!handleUnauthorized(error)) {
          toast.error(errorMessage(error, "Failed to create API key"));
        }
        return null;
      } finally {
        setIsCreating(false);
      }
    },
    [queryClient, handleUnauthorized],
  );

  const revokeKey = useCallback(
    async (jti: string) => {
      try {
        await authApiClient.revokeToken(jti);
        queryClient.invalidateQueries({ queryKey: API_KEYS_QUERY_KEY });
        toast.success("API key revoked.");
      } catch (error) {
        if (handleUnauthorized(error)) return;
        toast.error(errorMessage(error, "Failed to revoke API key"));
      }
    },
    [queryClient, handleUnauthorized],
  );

  return { isCreating, createKey, revokeKey };
}
