import { Copy } from "lucide-react";
import { QuickApiKeyPopover } from "@/features/settings/components/api-keys/QuickApiKeyPopover";

interface CellApiButtonProps {
  /** Concept name — becomes part of the generated key's default name. */
  contextLabel: string | null | undefined;
  buildSnippet: (apiKey: string) => string;
}

/**
 * Cell-header "API" chip: opens a popover that mints a short-lived API key and
 * copies a ready-to-run cURL snippet. Never embeds the session bearer.
 */
export function CellApiButton({ contextLabel, buildSnippet }: CellApiButtonProps) {
  return (
    <QuickApiKeyPopover contextLabel={contextLabel} buildSnippet={buildSnippet}>
      <button
        type="button"
        className="flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium cursor-pointer hover:bg-primary/20 transition-colors bg-primary/10 text-primary border border-primary/30"
        aria-label="Copy API cURL with a fresh API key"
      >
        <Copy className="h-3 w-3" />
        <span>API</span>
      </button>
    </QuickApiKeyPopover>
  );
}
