import { Search, X } from "lucide-react";
import type React from "react";
import { useEffect, useRef } from "react";

interface ExplorerSearchBarProps {
  value: string;
  onChange: (value: string) => void;
  onClose: () => void;
  placeholder?: string;
}

/**
 * Search input rendered below the Explorer header. Auto-focuses on mount,
 * Escape closes (and clears), the inline X button clears without closing.
 * Wraps a controlled input — the actual `searchTerm` state lives upstream
 * (useEditorPanel) so the toolbar's search bar and this one stay in sync.
 */
export const ExplorerSearchBar: React.FC<ExplorerSearchBarProps> = ({
  value,
  onChange,
  onClose,
  placeholder = "Search...",
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    requestAnimationFrame(() => inputRef.current?.focus());
  }, []);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Escape") {
      e.preventDefault();
      onClose();
    }
  };

  const hasValue = !!value.trim();

  return (
    <div className="px-2 py-1.5 border-b border-border bg-muted/30">
      <div className="relative">
        <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-muted-foreground pointer-events-none" />
        <input
          ref={inputRef}
          type="text"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          className="w-full h-6 pl-6 pr-6 text-xs bg-card border border-border rounded-sm focus:outline-none focus:ring-1 focus:ring-primary/60"
        />
        {hasValue && (
          <button
            type="button"
            onClick={() => onChange("")}
            title="Clear search"
            className="absolute right-1 top-1/2 -translate-y-1/2 h-4 w-4 inline-flex items-center justify-center rounded hover:bg-accent text-muted-foreground"
          >
            <X className="h-3 w-3" />
          </button>
        )}
      </div>
    </div>
  );
};
