import { Trash2 } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import type { EditorSelection } from "../../../store/appEditor.types";
import { useAppEditorStore } from "../../../store/appEditorStore";
import { removeSelected } from "../../../store/selectionMutations";
import { KIND_HELP } from "../editorHelp";
import { InfoHint } from "../InfoHint";
import { AppInspector } from "./AppInspector";
import { FormFieldInspector } from "./FormFieldInspector";
import { InputInspector } from "./InputInspector";
import { PageInspector } from "./PageInspector";
import { RunGroupInspector } from "./RunGroupInspector";
import { SectionInspector } from "./SectionInspector";
import { WidgetInspector } from "./WidgetInspector";

interface EditorInspectorProps {
  storageOntologyId: string;
}

const KIND_LABELS: Record<EditorSelection["kind"], string> = {
  app: "App",
  page: "Page",
  section: "Section",
  widget: "Widget",
  input: "Input",
  formField: "Form field",
  runGroup: "Run group",
};

function selectionId(selection: EditorSelection): string | null {
  switch (selection.kind) {
    case "app":
      return null;
    case "page":
      return selection.pageId;
    case "section":
      return selection.sectionId;
    case "widget":
      return selection.widgetId;
    case "input":
      return selection.inputId;
    case "formField":
      return selection.fieldId;
    case "runGroup":
      return selection.groupId;
    default: {
      const _exhaustive: never = selection;
      throw new Error(`Unhandled selection: ${JSON.stringify(_exhaustive)}`);
    }
  }
}

/**
 * Right pane (ADR D7): the inspector for whatever is selected. Micro-edits
 * (labels, spans, bindings, column lists) are direct schema edits on the
 * draft — no assistant round-trip needed.
 */
export function EditorInspector({ storageOntologyId }: EditorInspectorProps) {
  const draft = useAppEditorStore((state) => state.draft);
  const selection = useAppEditorStore((state) => state.selection);
  const select = useAppEditorStore((state) => state.select);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  if (!draft) return null;
  const effective: EditorSelection = selection ?? { kind: "app" };
  const id = selectionId(effective);

  const handleDelete = () => {
    select(null);
    updateDraft((current) => removeSelected(current, effective));
  };

  return (
    <div className="flex flex-col gap-3 p-3">
      <div className="flex items-center justify-between gap-2">
        <div className="min-w-0">
          <h3 className="flex items-center gap-1.5 text-xs font-semibold">
            {KIND_LABELS[effective.kind]}
            <InfoHint text={KIND_HELP[effective.kind]} />
          </h3>
          {id && <p className="text-[10px] font-mono text-muted-foreground truncate">{id}</p>}
        </div>
        {effective.kind !== "app" && (
          <Button
            size="icon"
            variant="ghost"
            title={`Delete ${KIND_LABELS[effective.kind].toLowerCase()}`}
            onClick={handleDelete}
            className="h-6 w-6 text-muted-foreground hover:text-destructive flex-shrink-0"
          >
            <Trash2 className="h-3.5 w-3.5" />
          </Button>
        )}
      </div>

      <InspectorBody selection={effective} storageOntologyId={storageOntologyId} />
    </div>
  );
}

interface InspectorBodyProps {
  selection: EditorSelection;
  storageOntologyId: string;
}

function InspectorBody({ selection, storageOntologyId }: InspectorBodyProps) {
  switch (selection.kind) {
    case "app":
      return <AppInspector />;
    case "page":
      return <PageInspector pageId={selection.pageId} />;
    case "section":
      return <SectionInspector pageId={selection.pageId} sectionId={selection.sectionId} />;
    case "widget":
      return (
        <WidgetInspector
          pageId={selection.pageId}
          sectionId={selection.sectionId}
          widgetId={selection.widgetId}
          storageOntologyId={storageOntologyId}
        />
      );
    case "input":
      return <InputInspector pageId={selection.pageId} inputId={selection.inputId} />;
    case "formField":
      return (
        <FormFieldInspector
          pageId={selection.pageId}
          inputId={selection.inputId}
          sectionIndex={selection.sectionIndex}
          fieldId={selection.fieldId}
        />
      );
    case "runGroup":
      return <RunGroupInspector pageId={selection.pageId} groupId={selection.groupId} />;
    default: {
      const _exhaustive: never = selection;
      throw new Error(`Unhandled selection: ${JSON.stringify(_exhaustive)}`);
    }
  }
}
