import { useQuery } from "@tanstack/react-query";

import { ConceptService } from "@/features/concepts/api";

/** Concept (predicate) names of a project, for `[[concept:name]]`
 *  autocomplete and graph-node labels. null projectId disables the query. */
export function useOntologyConcepts(ontologyId: string | null) {
  return useQuery({
    queryKey: ["context-project-concepts", ontologyId ?? ""],
    queryFn: async () => {
      const concepts = await ConceptService.listConcepts(ontologyId ?? "", "user");
      return concepts
        .map((concept) => concept.predicate_name)
        .filter((name): name is string => Boolean(name));
    },
    enabled: Boolean(ontologyId),
    staleTime: 60 * 1000,
  });
}
