import { cn } from "@/shared/lib/utils";

import type { ContextNote, ContextShelf } from "../../types";
import { CONTEXT_SHELF_LABELS, shelfOf } from "../../types";

const SHELF_CLASSES: Record<ContextShelf, string> = {
  rules: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400",
  knowledge: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
  documents: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400",
};

interface ShelfBadgeProps {
  shelf: ContextShelf;
  className?: string;
}

export function ShelfBadge({ shelf, className }: ShelfBadgeProps) {
  return (
    <span
      className={cn(
        "rounded px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide",
        SHELF_CLASSES[shelf],
        className,
      )}
    >
      {CONTEXT_SHELF_LABELS[shelf]}
    </span>
  );
}

interface NoteBadgesProps {
  note: ContextNote;
}

/** Shelf badge plus the "auto-detected" tag for auto-seeded observations. */
export function NoteBadges({ note }: NoteBadgesProps) {
  return (
    <span className="inline-flex items-center gap-1.5">
      <ShelfBadge shelf={shelfOf(note)} />
      {note.kind === "observation" && (
        <span className="rounded bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
          Auto-detected
        </span>
      )}
    </span>
  );
}
