import { z } from "zod";

export type TokenType = "bootstrap" | "api_key";

export const LoginSessionSchema = z.object({
  ip: z.string(),
  city: z.string().nullable(),
  country: z.string().nullable(),
  country_code: z.string().nullable(),
  first_seen: z.string(),
  last_seen: z.string(),
  hit_count: z.number(),
  last_token_type: z.enum(["bootstrap", "api_key"]).nullable(),
  last_token_name: z.string().nullable(),
});
export type LoginSession = z.infer<typeof LoginSessionSchema>;

export const LoginActivityResponseSchema = z.object({
  status: z.literal("success"),
  message: z.string(),
  data: z.array(LoginSessionSchema),
});
