import { Sparkles } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { useOntologyConcepts } from "../../../hooks/useOntologyConcepts";
import type { AppPageDef, AppWidgetDef } from "../../../schema/appDefinition.types";
import { addInput, defaultInputFor, patchWidget } from "../../../store/appEditorMutations";
import { useAppEditorStore } from "../../../store/appEditorStore";
import { askAssistantAboutWidget } from "../askAssistant";
import {
  COLUMN_STACK_HELP,
  GROUP_BINDING_HELP,
  INPUT_BINDING_HELP,
  SPAN_HELP,
  TAP_BINDING_HELP,
  WIDGET_TYPE_HELP,
} from "../editorHelp";
import { InfoHint } from "../InfoHint";
import { NumberField, SelectField, type SelectOption, TextField } from "./fields";
import { StaleSelection } from "./PageInspector";
import { resolveTapColumns } from "./tapColumns";
import { type PatchWidgetFn, WidgetTypeFields } from "./WidgetTypeFields";

interface WidgetInspectorProps {
  pageId: string;
  sectionId: string;
  widgetId: string;
  storageOntologyId: string;
}

const TAP_WIDGET_TYPES = new Set([
  "rich_table",
  "text",
  "heatmap",
  "stat_card",
  "line_chart",
  "area_chart",
  "bar_chart",
  "pie_chart",
]);

function tapOptionsFor(page: AppPageDef): SelectOption[] {
  return page.runGroups.flatMap((group) =>
    (group.outputs ?? []).map((tap) => ({
      value: tap.id,
      label: `${tap.id} — ${tap.concept} (${group.id})`,
    })),
  );
}

export function WidgetInspector({ pageId, sectionId, widgetId }: WidgetInspectorProps) {
  const draft = useAppEditorStore((state) => state.draft);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  const page = draft?.pages.find((candidate) => candidate.id === pageId);
  const { concepts, isLoading: conceptsLoading } = useOntologyConcepts(page?.project.id);

  const section = page?.sections.find((candidate) => candidate.id === sectionId);
  const widget = section?.widgets.find(
    (candidate): candidate is AppWidgetDef => "type" in candidate && candidate.id === widgetId,
  );
  if (!draft || !page || !section || !widget) return <StaleSelection />;

  const columnOptions = resolveTapColumns(page, widget.outputId, concepts);

  const patch: PatchWidgetFn = (partial) => {
    updateDraft((current) => patchWidget(current, pageId, sectionId, widgetId, partial));
  };

  return (
    <div className="flex flex-col gap-2.5">
      <p className="flex items-center gap-1 text-[10px] font-mono text-muted-foreground">
        type: {widget.type}
        {WIDGET_TYPE_HELP[widget.type] && <InfoHint text={WIDGET_TYPE_HELP[widget.type]} />}
      </p>
      <TextField label="Label" value={widget.label} onChange={(value) => patch({ label: value })} />
      <NumberField
        label="Span (1–12)"
        hint={SPAN_HELP}
        value={widget.span}
        min={1}
        max={12}
        onChange={(value) => patch({ span: value })}
      />
      {section.layout === "columns" && (
        <NumberField
          label="Column stack (1-based)"
          hint={COLUMN_STACK_HELP}
          value={widget.column}
          min={1}
          max={4}
          onChange={(value) => patch({ column: value })}
        />
      )}

      <BindingFields page={page} widget={widget} patch={patch} />
      <WidgetTypeFields
        widget={widget}
        patch={patch}
        columnOptions={columnOptions}
        columnsLoading={conceptsLoading}
        runGroups={page.runGroups ?? []}
      />

      <Button
        size="sm"
        variant="outline"
        onClick={() => askAssistantAboutWidget(draft, page, sectionId, widget)}
        className="gap-2 h-7 mt-1"
      >
        <Sparkles className="h-3.5 w-3.5" />
        Ask AI about this widget
      </Button>
    </div>
  );
}

interface BindingFieldsProps {
  page: AppPageDef;
  widget: AppWidgetDef;
  patch: PatchWidgetFn;
}

function BindingFields({ page, widget, patch }: BindingFieldsProps) {
  const select = useAppEditorStore((state) => state.select);

  if (widget.type === "input_ref" || widget.type === "form_ref") {
    const wantForm = widget.type === "form_ref";
    const options = page.inputs
      .filter((input) => (input.type === "form") === wantForm)
      .map((input) => ({ value: input.id, label: input.label || input.id }));

    // Rescue path for unbound refs: create the backing input here and bind it,
    // instead of sending the user to the DATA panel and back.
    const handleCreateInput = () => {
      const { updateDraft } = useAppEditorStore.getState();
      updateDraft((draft) => addInput(draft, page.id, defaultInputFor(wantForm ? "form" : "text")));
      const created = useAppEditorStore
        .getState()
        .draft?.pages.find((candidate) => candidate.id === page.id)
        ?.inputs.at(-1);
      if (created) patch({ inputId: created.id });
    };

    return (
      <>
        <SelectField
          label={wantForm ? "Form" : "Input"}
          hint={INPUT_BINDING_HELP}
          value={widget.inputId}
          options={options}
          onChange={(value) => patch({ inputId: value })}
        />
        {widget.inputId && (
          <JumpLink
            label={`Edit ${wantForm ? "form" : "input"} definition`}
            onClick={() =>
              select({ kind: "input", pageId: page.id, inputId: widget.inputId ?? "" })
            }
          />
        )}
        <JumpLink
          label={wantForm ? "+ New form" : "+ New input"}
          onClick={handleCreateInput}
          isAction
        />
      </>
    );
  }

  if (
    widget.type === "run_button" ||
    (widget.type === "button" && widget.action?.type === "run_group")
  ) {
    const options = page.runGroups.map((group) => ({
      value: group.id,
      label: group.label || group.id,
    }));
    const groupId = widget.type === "run_button" ? widget.groupId : widget.action?.groupId;
    const onGroupChange = (value: string | undefined) => {
      if (widget.type === "run_button") return patch({ groupId: value });
      patch({ action: { ...widget.action, type: "run_group", groupId: value } });
    };
    return (
      <>
        <SelectField
          label="Run group"
          hint={GROUP_BINDING_HELP}
          value={groupId}
          options={options}
          onChange={onGroupChange}
        />
        {groupId && (
          <JumpLink
            label="Edit run group"
            onClick={() => select({ kind: "runGroup", pageId: page.id, groupId })}
          />
        )}
      </>
    );
  }

  if (TAP_WIDGET_TYPES.has(widget.type)) {
    return (
      <SelectField
        label="Output tap"
        hint={TAP_BINDING_HELP}
        value={widget.outputId}
        options={tapOptionsFor(page)}
        allowNone={widget.type === "text"}
        onChange={(value) => patch({ outputId: value })}
      />
    );
  }

  return null;
}

interface JumpLinkProps {
  label: string;
  onClick: () => void;
  /** Jump links navigate (arrow suffix); action links (e.g. "+ New form") don't. */
  isAction?: boolean;
}

function JumpLink({ label, onClick, isAction }: JumpLinkProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="text-[10px] text-primary hover:underline self-start"
    >
      {isAction ? label : `${label} →`}
    </button>
  );
}
