import { AlertTriangle, Check, Copy } from "lucide-react";
import React from "react";
import { Button } from "@/shared/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import type { GrantInfo } from "./useSnowflakeCompute";

interface GrantInstructionsDialogProps {
  grantInfo: GrantInfo | null;
  onDismiss: () => void;
}

const operationLabels: Record<string, string> = {
  create: "Create Compute Pool",
  resume: "Start (Resume) Compute Pool",
  suspend: "Stop (Suspend) Compute Pool",
  drop: "Drop Compute Pool",
};

export const GrantInstructionsDialog: React.FC<GrantInstructionsDialogProps> = ({
  grantInfo,
  onDismiss,
}) => {
  const [copied, setCopied] = React.useState(false);

  React.useEffect(() => {
    setCopied(false);
  }, []);

  if (!grantInfo) return null;

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(grantInfo.sql);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Fallback
      const textarea = document.createElement("textarea");
      textarea.value = grantInfo.sql;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <Dialog
      open={!!grantInfo}
      onOpenChange={(open) => {
        if (!open) onDismiss();
      }}
    >
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-amber-600 dark:text-amber-400">
            <AlertTriangle className="w-5 h-5" />
            Insufficient Privileges
          </DialogTitle>
          <DialogDescription>
            The application does not have the required privileges to{" "}
            <strong>{operationLabels[grantInfo.operation] || grantInfo.operation}</strong>
            {grantInfo.poolName && (
              <>
                {" "}
                for pool{" "}
                <code className="font-mono text-xs bg-muted px-1 py-0.5 rounded">
                  {grantInfo.poolName}
                </code>
              </>
            )}
            .
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-3">
          <p className="text-sm text-muted-foreground">
            Ask your Snowflake account administrator to run the following SQL:
          </p>

          <div className="relative">
            <pre className="bg-muted p-4 rounded-lg text-xs font-mono overflow-x-auto whitespace-pre-wrap border">
              {grantInfo.sql}
            </pre>
            <Button
              variant="outline"
              size="sm"
              className="absolute top-2 right-2 h-7 px-2 text-xs"
              onClick={handleCopy}
            >
              {copied ? (
                <>
                  <Check className="w-3 h-3 mr-1" />
                  Copied
                </>
              ) : (
                <>
                  <Copy className="w-3 h-3 mr-1" />
                  Copy
                </>
              )}
            </Button>
          </div>

          <p className="text-xs text-muted-foreground">
            After the grant is executed, click <strong>Refresh</strong> in the Compute Pools tab to
            see the updated state.
          </p>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onDismiss}>
            Close
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
