import type { LucideIcon } from "lucide-react";
import React, { useCallback } from "react";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

interface TemplateCardProps {
  id: string;
  title: string;
  description: string;
  icon: LucideIcon;
  onUse: (templateId: string) => void;
  isUsing?: boolean;
}

const TemplateCard: React.FC<TemplateCardProps> = ({
  id,
  title,
  description,
  icon: Icon,
  onUse,
  isUsing = false,
}) => {
  const handleClick = useCallback(() => {
    if (!isUsing) onUse(id);
  }, [id, onUse, isUsing]);

  return (
    <button
      type="button"
      onClick={handleClick}
      disabled={isUsing}
      className={`group relative text-left bg-card border border-border rounded-xl p-5 hover:border-foreground/30 hover:shadow-sm transition-all duration-150 flex flex-col gap-3 ${
        isUsing ? "opacity-75" : ""
      }`}
    >
      {isUsing && (
        <div className="absolute inset-0 bg-background/80 backdrop-blur-sm flex items-center justify-center z-20 rounded-xl">
          <PrometheuxSpinner size={36} label="Creating ontology..." />
        </div>
      )}

      <div className="flex items-start gap-3">
        <div className="w-9 h-9 rounded-lg bg-secondary flex items-center justify-center flex-shrink-0 group-hover:bg-secondary/70 transition-colors">
          <Icon className="h-4 w-4 text-foreground/60" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="font-semibold text-[14px] text-foreground leading-tight line-clamp-2">
            {title}
          </div>
          {description && (
            <div className="text-[12px] text-muted-foreground mt-1 line-clamp-2">{description}</div>
          )}
        </div>
      </div>

      <div className="flex items-center justify-between border-t border-border/60 pt-3">
        <span className="text-[12px] text-muted-foreground">Template</span>
        <span className="text-[12px] text-primary font-medium opacity-0 group-hover:opacity-100 transition-opacity">
          Use →
        </span>
      </div>
    </button>
  );
};

export default React.memo(TemplateCard);
