import { FolderKanban } from "lucide-react";
import { useCurrentOntologyName } from "@/features/ontologies/hooks/useOntologyId";
import { SharedOntologyBanner } from "@/features/ontologies/sharing/components/SharedOntologyBanner";
import { type OntologyTab, OntologyTabNav } from "./projectTabs";

interface EditorHeaderLeftProps {
  activeTab: string;
  onTabChange: (tab: OntologyTab) => void;
  /** Hidden on very narrow viewports, where the tabs move into the overflow menu. */
  showTabs: boolean;
}

export function EditorHeaderLeft({ activeTab, onTabChange, showTabs }: EditorHeaderLeftProps) {
  const { ontologyName } = useCurrentOntologyName();

  return (
    <div className="flex min-w-0 items-center gap-3">
      {ontologyName && (
        <>
          <div className="flex min-w-0 max-w-64 items-center gap-2">
            <FolderKanban className="h-4 w-4 shrink-0 text-muted-foreground" />
            <span className="truncate text-sm font-semibold" title={ontologyName}>
              {ontologyName}
            </span>
          </div>
          <SharedOntologyBanner />
          {showTabs && <span className="h-4 w-px shrink-0 bg-border" />}
        </>
      )}

      {showTabs && <OntologyTabNav activeTab={activeTab} onTabChange={onTabChange} variant="bar" />}
    </div>
  );
}
