import { memo, useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { usePaidComputeEligibility } from "@/features/billing/hooks/usePaidComputeEligibility";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { ConfigService, type CoveredModelInfo } from "@/features/settings/api/configService";
import { useConfigStore } from "@/features/settings/store/configStore";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Slider } from "@/shared/components/ui/slider";
import { Switch } from "@/shared/components/ui/switch";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import SettingsSection from "../SettingsSection";

interface ModelFormValues {
  llmProvider: string;
  modelVersion: string;
  temperature: number;
  maxTokens: string;
  llmApiKey: string;
  azureLlmEndpoint?: string;
  azureLlmApiVersion?: string;
  databricksWorkspaceUrl?: string;
  databricksClientId?: string;
  databricksClientSecret?: string;
  snowflakeAccountUrl?: string;
}

const FALLBACK_OPENAI_MODELS: string[] = ["gpt-5", "gpt-4o", "o1"];
const DEFAULT_MODEL: Record<string, string> = {
  openai: "gpt-4o",
  azure: "claude-sonnet-4-6",
  anthropic: "claude-sonnet-4-6",
  databricks: "databricks-claude-sonnet-4-6",
  snowflake_cortex: "claude-sonnet-4-6",
};

// Providers Prometheux serves managed (no user API key needed): the direct
// Anthropic API (the default) and the Azure AI Foundry pool (serves gpt-* and
// claude-*). Managed-tier users can switch freely between these two.
const MANAGED_PROVIDERS: string[] = ["anthropic", "azure"];
const MANAGED_DEFAULT_PROVIDER = "anthropic";
// Compute-backed providers are inherently bring-your-own (own workspace creds),
// so selecting them always implies the "use my own" path.
const COMPUTE_PROVIDERS = ["databricks", "snowflake_cortex"];

const CORTEX_SQL_SCRIPT = `USE ROLE ACCOUNTADMIN;

-- Grant the Cortex database role to the application
GRANT DATABASE ROLE SNOWFLAKE.CORTEX_USER TO APPLICATION prometheux;

-- Enable cross-region inference so all Cortex models are available
-- Use 'AWS_EU' to keep data within EU, or 'ANY_REGION' for full model access
ALTER ACCOUNT SET CORTEX_ENABLED_CROSS_REGION = 'ANY_REGION';`;

const CortexEnablementScript = memo(() => {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(() => {
    navigator.clipboard.writeText(CORTEX_SQL_SCRIPT).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }, []);

  return (
    <div className="rounded-md border border-amber-500/30 bg-amber-500/5 p-3">
      <p className="mb-2 text-sm font-medium text-amber-700 dark:text-amber-400">
        Enable Cortex access
      </p>
      <p className="mb-2 text-xs text-muted-foreground">
        Run this script once as <strong>ACCOUNTADMIN</strong> in a Snowflake worksheet to grant
        Cortex access to the application:
      </p>
      <div className="relative">
        <pre className="overflow-x-auto rounded bg-muted p-3 text-xs leading-relaxed">
          {CORTEX_SQL_SCRIPT}
        </pre>
        <button
          type="button"
          onClick={handleCopy}
          className="absolute right-2 top-2 rounded bg-background/80 px-2 py-1 text-xs text-muted-foreground transition-colors hover:bg-background hover:text-foreground"
        >
          {copied ? "Copied!" : "Copy"}
        </button>
      </div>
    </div>
  );
});

CortexEnablementScript.displayName = "CortexEnablementScript";

const ChatModelConfig = memo(() => {
  const [llmProvider, setLlmProvider] = useState(
    PROMETHEUX_CONFIG.CHAT.LLM_PROVIDER || MANAGED_DEFAULT_PROVIDER,
  );
  const [modelVersion, setModelVersion] = useState(PROMETHEUX_CONFIG.CHAT.MODEL_VERSION);
  const [temperature, setTemperature] = useState(PROMETHEUX_CONFIG.CHAT.TEMPERATURE);
  const [maxTokens, setMaxTokens] = useState(PROMETHEUX_CONFIG.CHAT.MAX_TOKENS.toString());
  const [llmApiKey, setLlmApiKey] = useState(PROMETHEUX_CONFIG.LLM_API_KEY);
  const [azureLlmEndpoint, setAzureLlmEndpoint] = useState(
    PROMETHEUX_CONFIG.CHAT.AZURE_LLM_ENDPOINT || "",
  );
  const [azureLlmApiVersion, setAzureLlmApiVersion] = useState(
    PROMETHEUX_CONFIG.CHAT.AZURE_LLM_API_VERSION || "",
  );
  const [databricksWorkspaceUrl, setDatabricksWorkspaceUrl] = useState(
    PROMETHEUX_CONFIG.CHAT.DATABRICKS_WORKSPACE_URL || "",
  );
  const [databricksClientId, setDatabricksClientId] = useState(
    PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_ID || "",
  );
  const [databricksClientSecret, setDatabricksClientSecret] = useState(
    PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_SECRET || "",
  );
  const [snowflakeAccountUrl, setSnowflakeAccountUrl] = useState(
    PROMETHEUX_CONFIG.CHAT.SNOWFLAKE_ACCOUNT_URL || "",
  );
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [availableModels, setAvailableModels] = useState<string[]>(FALLBACK_OPENAI_MODELS);
  const [coveredModels, setCoveredModels] = useState<Record<string, CoveredModelInfo>>({});
  const [isLoadingModels, setIsLoadingModels] = useState(false);
  // false = managed (Prometheux pool, no key); true = bring-your-own provider/key.
  const [useOwnProvider, setUseOwnProvider] = useState(false);

  // Freemium accounts are pinned to the managed key — they cannot bring their own.
  const { isEligible } = usePaidComputeEligibility();
  const isFreemium = isEligible === false;

  // Load config from backend on component mount
  useEffect(() => {
    const loadConfig = async () => {
      if (!PROMETHEUX_CONFIG.AUTH_TOKEN) {
        return;
      }

      setIsLoading(true);
      try {
        const config = await ConfigService.loadUserConfig();
        if (config?.llm) {
          // Update local state with loaded config
          if (config.llm.llm_provider !== undefined) setLlmProvider(config.llm.llm_provider);
          if (config.llm.llm_version !== undefined) setModelVersion(config.llm.llm_version);
          if (config.llm.llm_temperature !== undefined) setTemperature(config.llm.llm_temperature);
          if (config.llm.llm_max_tokens !== undefined)
            setMaxTokens(config.llm.llm_max_tokens.toString());
          if (config.llm.llm_api_key !== undefined) setLlmApiKey(config.llm.llm_api_key);
          if (config.llm.azure_llm_endpoint !== undefined)
            setAzureLlmEndpoint(config.llm.azure_llm_endpoint);
          if (config.llm.azure_llm_api_version !== undefined)
            setAzureLlmApiVersion(config.llm.azure_llm_api_version);
          if (config.llm.databricks_workspace_url !== undefined)
            setDatabricksWorkspaceUrl(config.llm.databricks_workspace_url);
          if (config.llm.databricks_client_id !== undefined)
            setDatabricksClientId(config.llm.databricks_client_id);
          if (config.llm.databricks_client_secret !== undefined)
            setDatabricksClientSecret(config.llm.databricks_client_secret);
          if (config.llm.snowflake_account_url !== undefined)
            setSnowflakeAccountUrl(config.llm.snowflake_account_url);

          // A saved API key or a compute-backed provider means the user is on
          // their own provider; otherwise they're on the managed pool.
          const savedProvider = config.llm.llm_provider ?? "";
          const hasOwnKey = !!config.llm.llm_api_key;
          setUseOwnProvider(hasOwnKey || COMPUTE_PROVIDERS.includes(savedProvider));

          // Apply to global config
          ConfigService.applyConfigToGlobal(config);
          useConfigStore.getState().bumpConfigVersion();
        }
      } catch (_error) {
        // Continue with default values if loading fails
      } finally {
        setIsLoading(false);
      }
    };

    loadConfig();
  }, []);

  useEffect(() => {
    if (!PROMETHEUX_CONFIG.AUTH_TOKEN) return;

    if (
      llmProvider === "databricks" &&
      (!databricksWorkspaceUrl || !databricksClientId || !databricksClientSecret)
    ) {
      const fallback = DEFAULT_MODEL.databricks;
      setAvailableModels([fallback]);
      return;
    }

    let cancelled = false;
    const timer = setTimeout(async () => {
      setIsLoadingModels(true);

      const extra: Record<string, string> = {};
      if (llmProvider === "databricks") {
        extra.databricks_workspace_url = databricksWorkspaceUrl;
        extra.databricks_client_id = databricksClientId;
        extra.databricks_client_secret = databricksClientSecret;
      } else if (llmProvider === "snowflake_cortex" && snowflakeAccountUrl) {
        extra.snowflake_account_url = snowflakeAccountUrl;
      }

      const result = await ConfigService.listModels(llmProvider, extra);
      if (cancelled) return;
      setCoveredModels(result.coveredModels);
      const models = result.models;
      if (models.length > 0) {
        setAvailableModels(models);
        if (!models.includes(modelVersion)) {
          setModelVersion(models[0]);
        }
      } else {
        const fallback = DEFAULT_MODEL[llmProvider] ?? "gpt-4o";
        setAvailableModels([fallback]);
        if (modelVersion !== fallback) {
          setModelVersion(fallback);
        }
      }
      setIsLoadingModels(false);
    }, 500);

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [
    llmProvider,
    databricksWorkspaceUrl,
    databricksClientId,
    databricksClientSecret,
    snowflakeAccountUrl,
  ]); // eslint-disable-line react-hooks/exhaustive-deps

  const handleProviderChange = useCallback((value: string) => {
    setLlmProvider(value);
    setModelVersion(DEFAULT_MODEL[value] ?? "gpt-4o");
  }, []);

  const handleModeChange = useCallback(
    (own: boolean) => {
      setUseOwnProvider(own);
      if (own) {
        // Entering BYO while on managed Azure means the Foundry pool, not a user
        // Azure resource — drop to a plain provider so the user isn't shown empty
        // Azure-OpenAI endpoint fields.
        if (llmProvider === "azure") {
          setLlmProvider("openai");
          setModelVersion(DEFAULT_MODEL.openai);
        }
        return;
      }
      // Managed: keep a managed-capable provider (default to direct Anthropic if
      // the current one isn't managed) and clear every BYO credential, so an empty
      // key is no longer a hidden "use managed" state.
      const managedProvider = MANAGED_PROVIDERS.includes(llmProvider)
        ? llmProvider
        : MANAGED_DEFAULT_PROVIDER;
      setLlmProvider(managedProvider);
      setModelVersion(DEFAULT_MODEL[managedProvider]);
      setLlmApiKey("");
      setAzureLlmEndpoint("");
      setAzureLlmApiVersion("");
      setDatabricksWorkspaceUrl("");
      setDatabricksClientId("");
      setDatabricksClientSecret("");
      setSnowflakeAccountUrl("");
    },
    [llmProvider],
  );

  const handleModelConfigSave = useCallback(async () => {
    if (!PROMETHEUX_CONFIG.AUTH_TOKEN) {
      toast.error("Authentication token is missing. Please set it first.");
      return;
    }

    setIsSaving(true);
    try {
      // Update global config first
      PROMETHEUX_CONFIG.CHAT.LLM_PROVIDER = llmProvider;
      PROMETHEUX_CONFIG.CHAT.MODEL_VERSION = modelVersion;
      PROMETHEUX_CONFIG.CHAT.TEMPERATURE = temperature;
      PROMETHEUX_CONFIG.CHAT.MAX_TOKENS = parseInt(maxTokens, 10);
      PROMETHEUX_CONFIG.LLM_API_KEY = isFreemium ? "" : llmApiKey;
      // Always set streaming to false
      PROMETHEUX_CONFIG.CHAT.STREAMING_ENABLED = false;

      if (llmProvider === "azure") {
        PROMETHEUX_CONFIG.CHAT.AZURE_LLM_ENDPOINT = azureLlmEndpoint;
        PROMETHEUX_CONFIG.CHAT.AZURE_LLM_API_VERSION = azureLlmApiVersion;
      }
      if (llmProvider === "databricks") {
        PROMETHEUX_CONFIG.CHAT.DATABRICKS_WORKSPACE_URL = databricksWorkspaceUrl;
        PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_ID = databricksClientId;
        PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_SECRET = databricksClientSecret;
      }
      if (llmProvider === "snowflake_cortex") {
        PROMETHEUX_CONFIG.CHAT.SNOWFLAKE_ACCOUNT_URL = snowflakeAccountUrl;
      }

      const configToSave = {
        llm: {
          llm_provider: llmProvider,
          llm_version: modelVersion,
          llm_temperature: temperature,
          llm_max_tokens: parseInt(maxTokens, 10),
          llm_api_key: isFreemium ? "" : llmApiKey,
          azure_llm_endpoint: azureLlmEndpoint,
          azure_llm_api_version: azureLlmApiVersion,
          databricks_workspace_url: databricksWorkspaceUrl,
          databricks_client_id: databricksClientId,
          databricks_client_secret: databricksClientSecret,
          snowflake_account_url: snowflakeAccountUrl,
        },
      };

      // Save to backend
      await ConfigService.saveUserConfig(configToSave);

      useCodeAssistantStore.getState().setActiveModel(modelVersion);
      useConfigStore.getState().bumpConfigVersion();
      toast.success("Model configuration saved successfully");
    } catch (error) {
      toast.error(
        `Failed to save configuration: ${error instanceof Error ? error.message : "Unknown error"}`,
      );
    } finally {
      setIsSaving(false);
    }
  }, [
    llmProvider,
    modelVersion,
    temperature,
    maxTokens,
    llmApiKey,
    azureLlmEndpoint,
    azureLlmApiVersion,
    databricksWorkspaceUrl,
    databricksClientId,
    databricksClientSecret,
    snowflakeAccountUrl,
    isFreemium,
  ]);

  const handleModelConfigReset = useCallback(() => {
    const defaultProvider = PROMETHEUX_CONFIG.SNOWFLAKE_MODE
      ? "snowflake_cortex"
      : MANAGED_DEFAULT_PROVIDER;
    const defaultModel = DEFAULT_MODEL[defaultProvider] ?? "gpt-4o";

    // Defaults are the managed pool (Snowflake mode aside, which is BYO compute).
    setUseOwnProvider(PROMETHEUX_CONFIG.SNOWFLAKE_MODE);
    setLlmProvider(defaultProvider);
    setModelVersion(defaultModel);
    setTemperature(0.5);
    setMaxTokens("8192");
    setLlmApiKey("");
    setAzureLlmEndpoint("");
    setAzureLlmApiVersion("");
    setDatabricksWorkspaceUrl("");
    setDatabricksClientId("");
    setDatabricksClientSecret("");
    setSnowflakeAccountUrl("");

    PROMETHEUX_CONFIG.CHAT.LLM_PROVIDER = defaultProvider;
    PROMETHEUX_CONFIG.CHAT.MODEL_VERSION = defaultModel;
    PROMETHEUX_CONFIG.CHAT.TEMPERATURE = 0.5;
    PROMETHEUX_CONFIG.CHAT.MAX_TOKENS = 8192;
    PROMETHEUX_CONFIG.LLM_API_KEY = "";
    PROMETHEUX_CONFIG.CHAT.STREAMING_ENABLED = false;
    PROMETHEUX_CONFIG.CHAT.AZURE_LLM_ENDPOINT = "";
    PROMETHEUX_CONFIG.CHAT.AZURE_LLM_API_VERSION = "";
    PROMETHEUX_CONFIG.CHAT.DATABRICKS_WORKSPACE_URL = "";
    PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_ID = "";
    PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_SECRET = "";
    PROMETHEUX_CONFIG.CHAT.SNOWFLAKE_ACCOUNT_URL = "";

    toast.success("Model configuration reset to defaults");
  }, []);

  const isComputeProvider = COMPUTE_PROVIDERS.includes(llmProvider);
  const showApiKeyField = useOwnProvider && !isComputeProvider;
  const showAzureFields = useOwnProvider && llmProvider === "azure";
  const showDatabricksFields = useOwnProvider && llmProvider === "databricks";
  const showSnowflakeFields = useOwnProvider && llmProvider === "snowflake_cortex";

  // Managed mode offers the two Prometheux-served providers; BYO mode offers the
  // full list (snowflake only when the app runs in Snowflake mode).
  const managedProviderOptions = [
    { value: "anthropic", label: "anthropic" },
    { value: "azure", label: "azure" },
  ];
  const byoProviderOptions = [
    { value: "openai", label: "openai" },
    { value: "azure", label: "azure" },
    { value: "anthropic", label: "anthropic" },
    { value: "databricks", label: "databricks" },
    ...(PROMETHEUX_CONFIG.SNOWFLAKE_MODE
      ? [{ value: "snowflake_cortex", label: "snowflake cortex" }]
      : []),
  ];
  const providerOptions = useOwnProvider ? byoProviderOptions : managedProviderOptions;
  const modelOptions = availableModels.map((model) => ({ model, covered: coveredModels[model] }));
  const selectedCovered = coveredModels[modelVersion];

  return (
    <SettingsSection
      title="Chat Model Configuration"
      description="Configure the LLM model settings for chat interactions"
    >
      <div className="space-y-4">
        <div className="flex items-center justify-between gap-4 rounded-md border border-border p-3">
          <div className="space-y-0.5">
            <Label htmlFor="use-own-provider">Use my own provider</Label>
            <p className="text-xs text-muted-foreground">
              {useOwnProvider
                ? "Bring your own API key or compute — you're billed directly by your provider."
                : "Running on Prometheux's managed models. No API key needed."}
            </p>
          </div>
          <Switch
            id="use-own-provider"
            checked={useOwnProvider}
            onCheckedChange={handleModeChange}
          />
        </div>

        <div>
          <Label htmlFor="llm-provider">LLM Provider</Label>
          <Select value={llmProvider} onValueChange={handleProviderChange}>
            <SelectTrigger>
              <SelectValue placeholder="Select LLM provider" />
            </SelectTrigger>
            <SelectContent>
              {providerOptions.map((opt) => (
                <SelectItem key={opt.value} value={opt.value}>
                  {opt.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {showApiKeyField && (
          <div>
            <Label htmlFor="llm-api-key">LLM API Key</Label>
            <Input
              id="llm-api-key"
              type="password"
              value={isFreemium ? "" : llmApiKey}
              onChange={(e) => setLlmApiKey(e.target.value)}
              placeholder={
                isFreemium
                  ? "Upgrade to a paid plan to use your own LLM API key"
                  : "Enter your own LLM API key"
              }
              disabled={isFreemium}
              className="flex-1"
            />
            {isFreemium && (
              <p className="mt-1 text-xs text-muted-foreground">
                Freemium accounts run on the managed model. Upgrade to use your own LLM API key.
              </p>
            )}
          </div>
        )}

        {showAzureFields && (
          <>
            <div>
              <Label htmlFor="azure-llm-endpoint">Azure LLM Endpoint</Label>
              <Input
                id="azure-llm-endpoint"
                type="text"
                value={azureLlmEndpoint}
                onChange={(e) => setAzureLlmEndpoint(e.target.value)}
                placeholder="Enter your Azure endpoint URL"
                className="flex-1"
              />
            </div>
            <div>
              <Label htmlFor="azure-llm-api-version">Azure LLM API Version</Label>
              <Input
                id="azure-llm-api-version"
                type="text"
                value={azureLlmApiVersion}
                onChange={(e) => setAzureLlmApiVersion(e.target.value)}
                placeholder="Enter Azure API version (e.g., 2023-05-15)"
                className="flex-1"
              />
            </div>
          </>
        )}

        {showDatabricksFields && (
          <>
            <div>
              <Label htmlFor="databricks-workspace-url">Databricks Workspace URL</Label>
              <Input
                id="databricks-workspace-url"
                type="text"
                value={databricksWorkspaceUrl}
                onChange={(e) => setDatabricksWorkspaceUrl(e.target.value)}
                placeholder="https://your-workspace.cloud.databricks.com"
                className="flex-1"
              />
            </div>
            <div>
              <Label htmlFor="databricks-client-id">Service Principal Client ID</Label>
              <Input
                id="databricks-client-id"
                type="text"
                value={databricksClientId}
                onChange={(e) => setDatabricksClientId(e.target.value)}
                placeholder="Service principal application ID"
                className="flex-1"
              />
            </div>
            <div>
              <Label htmlFor="databricks-client-secret">Service Principal Client Secret</Label>
              <Input
                id="databricks-client-secret"
                type="password"
                value={databricksClientSecret}
                onChange={(e) => setDatabricksClientSecret(e.target.value)}
                placeholder="OAuth secret for the service principal"
                className="flex-1"
              />
              <p className="mt-1 text-xs text-muted-foreground">
                Create a service principal in Databricks Settings &gt; Identity and access, then
                generate an OAuth secret.
              </p>
            </div>
          </>
        )}

        {showSnowflakeFields && (
          <div className="space-y-3">
            <div className="rounded-md bg-muted/50 p-3">
              <p className="text-sm text-muted-foreground">
                Snowflake Cortex uses the SPCS OAuth token for authentication. No API key or
                credentials are required &mdash; everything is managed automatically within the
                Snowflake security perimeter.
              </p>
            </div>
            <CortexEnablementScript />
          </div>
        )}

        <div>
          <Label htmlFor="model-version">Model Version</Label>
          <Select value={modelVersion} onValueChange={setModelVersion} disabled={isLoadingModels}>
            <SelectTrigger>
              <SelectValue
                placeholder={isLoadingModels ? "Loading models…" : "Select model version"}
              />
            </SelectTrigger>
            <SelectContent>
              {modelOptions.map(({ model, covered }) => (
                <SelectItem key={model} value={model}>
                  <span className="flex items-center gap-2">
                    {model}
                    {covered && (
                      <span className="rounded bg-amber-100 px-1.5 py-0.5 text-[10px] font-medium text-amber-700 dark:bg-amber-900/30 dark:text-amber-400">
                        30-day retention · no ZDR
                      </span>
                    )}
                  </span>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {selectedCovered && (
            <p className="mt-1 text-xs text-amber-700 dark:text-amber-400">
              {selectedCovered.note}
            </p>
          )}
        </div>

        <div className="space-y-2">
          <div className="flex justify-between">
            <Label htmlFor="temperature">Temperature</Label>
            <span className="text-sm text-muted-foreground">{temperature.toFixed(1)}</span>
          </div>
          <Slider
            id="temperature"
            min={0}
            max={1}
            step={0.1}
            value={[temperature]}
            onValueChange={(value) => setTemperature(value[0])}
            className="w-full"
          />
        </div>
        <div>
          <Label htmlFor="max-tokens">Max Tokens</Label>
          <Input
            id="max-tokens"
            type="number"
            min="1"
            value={maxTokens}
            onChange={(e) => setMaxTokens(e.target.value)}
            placeholder="Enter max tokens"
            className="flex-1"
          />
        </div>
        <div className="flex justify-end gap-4">
          <Button
            onClick={handleModelConfigSave}
            disabled={isSaving || isLoading}
            isLoading={isSaving}
          >
            {isSaving ? "Saving..." : "Save"}
          </Button>
          <Button
            onClick={handleModelConfigReset}
            variant="outline"
            disabled={isSaving || isLoading}
          >
            Reset
          </Button>
        </div>
      </div>
    </SettingsSection>
  );
});

ChatModelConfig.displayName = "ChatModelConfig";

export default ChatModelConfig;
