import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { supabase } from "@/shared/integrations/supabase/client";
import { BaseClient } from "@/shared/lib/BaseClient";
import { HttpService } from "@/shared/services/httpService";
import type {
  ActuatorHealth,
  ActuatorMeasurement,
  ActuatorMetric,
  HealthStatus,
  LogLevel,
  SparkApplication,
  SparkExecutor,
  SparkJob,
  SparkStage,
  SparkUIStatus,
} from "../types/engineMonitor.types";

const SPARK_UI_BASE = "/vadalog/spark-ui";
const ACTUATOR_BASE = "/vadalog/actuator";

const HEALTH_STATUSES: ReadonlySet<HealthStatus> = new Set<HealthStatus>([
  "UP",
  "DOWN",
  "OUT_OF_SERVICE",
  "UNKNOWN",
]);

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isEnvelope(value: unknown): value is { status?: unknown; data?: unknown } {
  return isObject(value) && ("data" in value || "status" in value);
}

function unwrapArray<T>(response: unknown): T[] {
  if (Array.isArray(response)) return response;
  if (isEnvelope(response) && Array.isArray(response.data)) return response.data;
  return [];
}

function unwrapObject<T>(response: unknown, isT: (v: unknown) => v is T): T | null {
  if (isT(response)) return response;
  if (isEnvelope(response) && isT(response.data)) return response.data;
  return null;
}

function isSparkUIStatus(value: unknown): value is SparkUIStatus {
  return isObject(value) && "running" in value && typeof value.running === "boolean";
}

function isSparkJob(value: unknown): value is SparkJob {
  return isObject(value) && "jobId" in value && typeof value.jobId === "number";
}

function isHealthStatus(value: unknown): value is HealthStatus {
  return typeof value === "string" && HEALTH_STATUSES.has(value as HealthStatus);
}

function isActuatorHealth(value: unknown): value is ActuatorHealth {
  return isObject(value) && "status" in value && isHealthStatus(value.status);
}

function isActuatorMeasurement(value: unknown): value is ActuatorMeasurement {
  return isObject(value) && typeof value.statistic === "string" && typeof value.value === "number";
}

function isActuatorMetric(value: unknown): value is ActuatorMetric {
  return (
    isObject(value) &&
    typeof value.name === "string" &&
    Array.isArray(value.measurements) &&
    value.measurements.every(isActuatorMeasurement)
  );
}

function unwrapLogfileBody(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed.startsWith("{") || !trimmed.endsWith("}")) return raw;
  try {
    const parsed: unknown = JSON.parse(trimmed);
    if (
      parsed !== null &&
      typeof parsed === "object" &&
      "data" in parsed &&
      typeof (parsed as { data: unknown }).data === "string"
    ) {
      return (parsed as { data: string }).data;
    }
    return raw;
  } catch {
    return raw;
  }
}

async function getJarvispyAuthHeaders(): Promise<Record<string, string>> {
  try {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    return { "X-Supabase-Token": session?.access_token || "null" };
  } catch {
    return { "X-Supabase-Token": "null" };
  }
}

export class EngineClient extends BaseClient {
  private async authedGet(endpoint: string): Promise<unknown> {
    const headers = await getJarvispyAuthHeaders();
    return this.get(endpoint, undefined, headers);
  }

  async getStatus(): Promise<SparkUIStatus | null> {
    try {
      const raw = await this.authedGet(`${SPARK_UI_BASE}/status`);
      return unwrapObject(raw, isSparkUIStatus);
    } catch {
      return null;
    }
  }

  async getJobs(): Promise<SparkJob[]> {
    try {
      const raw = await this.authedGet(`${SPARK_UI_BASE}/api/jobs`);
      return unwrapArray<SparkJob>(raw);
    } catch {
      return [];
    }
  }

  async getJob(jobId: number): Promise<SparkJob | null> {
    try {
      const raw = await this.authedGet(`${SPARK_UI_BASE}/api/jobs/${jobId}`);
      return unwrapObject(raw, isSparkJob);
    } catch {
      return null;
    }
  }

  async getStages(): Promise<SparkStage[]> {
    try {
      const raw = await this.authedGet(`${SPARK_UI_BASE}/api/stages`);
      return unwrapArray<SparkStage>(raw);
    } catch {
      return [];
    }
  }

  async getExecutors(): Promise<SparkExecutor[]> {
    try {
      const raw = await this.authedGet(`${SPARK_UI_BASE}/api/executors`);
      return unwrapArray<SparkExecutor>(raw);
    } catch {
      return [];
    }
  }

  async getApplications(): Promise<SparkApplication[]> {
    try {
      const raw = await this.authedGet(`${SPARK_UI_BASE}/api/applications`);
      return unwrapArray<SparkApplication>(raw);
    } catch {
      return [];
    }
  }

  async getHealth(): Promise<ActuatorHealth | null> {
    try {
      const raw = await this.authedGet(`${ACTUATOR_BASE}/health`);
      return unwrapObject(raw, isActuatorHealth);
    } catch {
      return null;
    }
  }

  async getCpuMetric(): Promise<ActuatorMetric | null> {
    try {
      const raw = await this.authedGet(`${ACTUATOR_BASE}/metrics/process.cpu.usage`);
      return unwrapObject(raw, isActuatorMetric);
    } catch {
      return null;
    }
  }

  async getCpuCountMetric(): Promise<ActuatorMetric | null> {
    try {
      const raw = await this.authedGet(`${ACTUATOR_BASE}/metrics/system.cpu.count`);
      return unwrapObject(raw, isActuatorMetric);
    } catch {
      return null;
    }
  }

  async getHeapUsedMetric(): Promise<ActuatorMetric | null> {
    try {
      const raw = await this.authedGet(`${ACTUATOR_BASE}/metrics/jvm.memory.used?tag=area:heap`);
      return unwrapObject(raw, isActuatorMetric);
    } catch {
      return null;
    }
  }

  async getHeapMaxMetric(): Promise<ActuatorMetric | null> {
    try {
      const raw = await this.authedGet(`${ACTUATOR_BASE}/metrics/jvm.memory.max?tag=area:heap`);
      return unwrapObject(raw, isActuatorMetric);
    } catch {
      return null;
    }
  }

  async triggerGc(): Promise<boolean> {
    return rawAuthedSend(`${ACTUATOR_BASE}/gc`, "POST");
  }

  async getLogfile(): Promise<string | null> {
    try {
      const url = `${PROMETHEUX_CONFIG.BASE_URL}${ACTUATOR_BASE}/logfile`;
      const jarvispyHeaders = await getJarvispyAuthHeaders();
      const response = await fetch(url, {
        method: "GET",
        headers: HttpService.getHeaders(undefined, {
          Accept: "text/plain, */*",
          ...jarvispyHeaders,
        }),
        mode: "cors",
      });
      if (!response.ok) return null;
      const raw = await response.text();
      return unwrapLogfileBody(raw);
    } catch {
      return null;
    }
  }

  async setLoggerLevel(loggerName: string, level: LogLevel | null): Promise<boolean> {
    const encoded = encodeURIComponent(loggerName);
    return rawAuthedSend(`${ACTUATOR_BASE}/loggers/${encoded}`, "POST", {
      configuredLevel: level,
    });
  }
}

async function rawAuthedSend(
  endpoint: string,
  method: "POST" | "PUT",
  body?: unknown,
): Promise<boolean> {
  try {
    const url = `${PROMETHEUX_CONFIG.BASE_URL}${endpoint}`;
    const jarvispyHeaders = await getJarvispyAuthHeaders();
    const response = await fetch(url, {
      method,
      headers: HttpService.getHeaders(undefined, jarvispyHeaders),
      body: body === undefined ? undefined : JSON.stringify(body),
      mode: "cors",
    });
    return response.ok;
  } catch {
    return false;
  }
}

export const engineClient = new EngineClient();
