import type { ReactNode } from "react";
import { TableBody, TableCell, TableRow } from "@/shared/components/ui/table";

interface TableOutputBodyProps {
  columns: string[];
  rows: unknown[][];
  renderCell?: (cell: unknown, rowIndex: number, columnIndex: number) => ReactNode;
  onRowClick?: (rowIndex: number) => void;
  rowClassName?: (rowIndex: number) => string | undefined;
}

function defaultRenderCell(cell: unknown): ReactNode {
  if (cell === null || cell === undefined) {
    return <span className="italic text-muted-foreground">null</span>;
  }
  return String(cell);
}

export function TableOutputBody({
  columns,
  rows,
  renderCell,
  onRowClick,
  rowClassName,
}: TableOutputBodyProps) {
  if (rows.length === 0) {
    return (
      <TableBody>
        <TableRow>
          <TableCell
            colSpan={columns.length || 1}
            className="text-center text-xs text-muted-foreground py-6"
          >
            No data
          </TableCell>
        </TableRow>
      </TableBody>
    );
  }

  return (
    <TableBody>
      {rows.map((row, ri) => (
        <TableRow
          key={ri}
          className={rowClassName?.(ri)}
          onClick={onRowClick ? () => onRowClick(ri) : undefined}
        >
          {row.map((cell, ci) => (
            <TableCell key={ci} className="text-xs">
              {renderCell ? renderCell(cell, ri, ci) : defaultRenderCell(cell)}
            </TableCell>
          ))}
        </TableRow>
      ))}
    </TableBody>
  );
}
