import type { Invoice } from "@/features/billing/types";
import { supabase } from "@/shared/integrations/supabase/client";
import { BaseClient } from "@/shared/lib/BaseClient";

interface InvoicesResponse {
  status: "success" | "error";
  message: string;
  data?: {
    invoices: Invoice[];
  };
}

/**
 * Client for invoice-related operations
 */
export class InvoiceClient extends BaseClient {
  /**
   * Get invoices for the authenticated user
   */
  async getMyInvoices(): Promise<InvoicesResponse> {
    try {
      // Get Supabase session for authentication header
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const additionalHeaders: Record<string, string> = {
        "X-Supabase-Token": session?.access_token || "null",
      };

      const response = await this.get("/invoices/me", undefined, additionalHeaders);
      return response;
    } catch (error) {
      console.error("Error fetching invoices:", error);
      throw error as Error;
    }
  }
}
