import type React from "react";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import { Switch } from "@/shared/components/ui/switch";
import type { ParsedParam } from "../../utils/paramParser";

export interface ParamFieldProps {
  param: ParsedParam;
  value: string | number | boolean;
  onChange: (val: string | number | boolean) => void;
}

export function ParamField({ param, value, onChange }: ParamFieldProps) {
  const id = `run-${param.name}`;
  const isDate = /^\d{4}-\d{2}-\d{2}/.test(String(param.defaultValue)) || /date/i.test(param.name);

  if (param.type === "bool") {
    return (
      <div className="flex items-center gap-2 mt-1">
        <Switch id={id} checked={Boolean(value)} onCheckedChange={onChange} />
        <Label htmlFor={id} className="text-xs text-muted-foreground cursor-pointer">
          {value ? "true" : "false"}
        </Label>
      </div>
    );
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (param.type === "int") {
      onChange(parseFloat(e.target.value) || 0);
      return;
    }
    if (param.type === "float") {
      onChange(parseFloat(e.target.value) || 0);
      return;
    }
    onChange(e.target.value);
  };

  return (
    <Input
      id={id}
      type={param.type === "int" || param.type === "float" ? "number" : isDate ? "date" : "text"}
      step="any"
      value={String(value)}
      onChange={handleChange}
      className="h-9 text-sm mt-1 min-w-[140px]"
    />
  );
}
