import { Info } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";

interface Shortcut {
  label: string;
  keys: string;
}

interface ShortcutGroup {
  title: string;
  items: Shortcut[];
}

// Platform-aware modifier labels. macOS uses the glyphs; everything else uses words.
const isMac = typeof navigator !== "undefined" && /Mac|iPhone|iPad|iPod/.test(navigator.platform);
const MOD = isMac ? "⌘" : "Ctrl";
const ALT = isMac ? "⌥" : "Alt";
const SHIFT = isMac ? "⇧" : "Shift";

const SHORTCUT_GROUPS: ShortcutGroup[] = [
  {
    title: "Multi-cursor & rename",
    items: [
      { label: "Select next occurrence", keys: `${MOD} D` },
      { label: "Select all occurrences", keys: `${MOD} ${SHIFT} L` },
      { label: "Add cursor above / below", keys: `${MOD} ${ALT} ↑ / ↓` },
      { label: "Column selection", keys: `${SHIFT} ${ALT} + drag` },
    ],
  },
  {
    title: "Lines",
    items: [
      { label: "Move line up / down", keys: `${ALT} ↑ / ↓` },
      { label: "Copy line up / down", keys: `${SHIFT} ${ALT} ↑ / ↓` },
      { label: "Toggle comment", keys: `${MOD} 7` },
      { label: "Indent code", keys: `${MOD} I` },
    ],
  },
  {
    title: "Search",
    items: [
      { label: "Find / Replace", keys: `${MOD} F` },
      { label: "Find next / previous", keys: `${MOD} G  /  ${MOD} ${SHIFT} G` },
      { label: "Go to line", keys: `${MOD} ${ALT} G` },
    ],
  },
  {
    title: "Run & save",
    items: [
      { label: "Run cell", keys: `${MOD} ${SHIFT} ↵` },
      { label: "Save", keys: `${MOD} S` },
      { label: "Toggle word wrap", keys: `${ALT} Z` },
    ],
  },
];

/**
 * Info icon in the editor toolbar that reveals the editor keyboard shortcuts
 * (multi-cursor, search, line ops) on hover. Reference-only, so a Tooltip is
 * enough — no interaction needed inside the panel.
 */
export function EditorShortcutsHelp() {
  return (
    <TooltipProvider delayDuration={150}>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7 text-muted-foreground"
            title="Editor keyboard shortcuts"
          >
            <Info className="h-4 w-4" />
          </Button>
        </TooltipTrigger>
        <TooltipContent side="bottom" align="end" className="w-72 p-3">
          <p className="mb-2 text-sm font-semibold text-popover-foreground">Editor shortcuts</p>
          <div className="space-y-2.5">
            {SHORTCUT_GROUPS.map((group) => (
              <div key={group.title}>
                <p className="mb-1 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
                  {group.title}
                </p>
                <ul className="space-y-1">
                  {group.items.map((item) => (
                    <li key={item.label} className="flex items-center justify-between gap-3">
                      <span className="text-xs text-popover-foreground">{item.label}</span>
                      <kbd className="shrink-0 rounded border border-border bg-muted px-1.5 py-0.5 font-mono text-[11px] text-muted-foreground">
                        {item.keys}
                      </kbd>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}
