const RECOVERY_CODE_COUNT = 10;
const RECOVERY_CODE_CHARS = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
const RECOVERY_CODE_GROUP_SIZE = 4;
const RECOVERY_CODE_GROUPS = 2;
const RECOVERY_CODE_SEPARATOR = "-";

/**
 * Generate a single recovery code with the shape `XXXX-XXXX`.
 * Uses `crypto.getRandomValues` for a cryptographically strong RNG.
 * Ambiguous characters (O/0, I/1) are excluded so users can re-type them reliably.
 */
function generateRecoveryCode(): string {
  const groups: string[] = [];
  for (let group = 0; group < RECOVERY_CODE_GROUPS; group += 1) {
    const bytes = new Uint32Array(RECOVERY_CODE_GROUP_SIZE);
    crypto.getRandomValues(bytes);
    let chunk = "";
    for (let i = 0; i < RECOVERY_CODE_GROUP_SIZE; i += 1) {
      chunk += RECOVERY_CODE_CHARS[bytes[i] % RECOVERY_CODE_CHARS.length];
    }
    groups.push(chunk);
  }
  return groups.join(RECOVERY_CODE_SEPARATOR);
}

export function generateRecoveryCodes(count: number = RECOVERY_CODE_COUNT): string[] {
  return Array.from({ length: count }, generateRecoveryCode);
}

/**
 * SHA-256 hash (hex) of the canonical form of a recovery code.
 * Canonicalization: uppercased + separators stripped. This lets the user enter
 * the code with or without dashes and in any case.
 */
export async function hashRecoveryCode(code: string): Promise<string> {
  const canonical = canonicalizeRecoveryCode(code);
  const bytes = new TextEncoder().encode(canonical);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return bufferToHex(digest);
}

export function canonicalizeRecoveryCode(code: string): string {
  return code.replace(/[\s-]/g, "").toUpperCase();
}

function bufferToHex(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let hex = "";
  for (const byte of bytes) {
    hex += byte.toString(16).padStart(2, "0");
  }
  return hex;
}
