import type { SuggestionState } from "../hooks/useMentionSuggestions";

interface MentionSuggestionDropdownProps {
  suggestions: SuggestionState;
  suggestionRefs: React.MutableRefObject<(HTMLDivElement | null)[]>;
  onSelect: (concept: string) => void;
  onHover: (index: number) => void;
}

/** The @-mention dropdown under a description textarea. */
export function MentionSuggestionDropdown({
  suggestions,
  suggestionRefs,
  onSelect,
  onHover,
}: MentionSuggestionDropdownProps) {
  if (!suggestions.show || suggestions.filtered.length === 0) return null;

  return (
    <div
      className="absolute w-full mt-1 bg-popover border rounded-md shadow-md max-h-48 overflow-y-auto"
      style={{ display: "block", zIndex: 9999 }}
    >
      {suggestions.filtered.map((concept, index) => (
        <div
          key={concept}
          ref={(el) => {
            suggestionRefs.current[index] = el;
          }}
          className={`px-3 py-2 text-sm cursor-pointer transition-colors ${
            index === suggestions.selectedIndex
              ? "bg-accent text-accent-foreground"
              : "hover:bg-accent/50"
          }`}
          onMouseDown={(e) => {
            e.preventDefault();
            onSelect(concept);
          }}
          onMouseEnter={() => onHover(index)}
        >
          @{concept}
        </div>
      ))}
    </div>
  );
}
