import type { OntologyData, OntologyScope } from "@/features/ontologies/api";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

interface OntologyListRow {
  id?: string;
  name?: string;
  description?: string;
  author?: string;
  scope?: OntologyScope;
}

/**
 * Server-side project search by name/description for global search.
 *
 * Deliberately kept out of the (oversized, grandfathered) `projects/api.ts`:
 * it hits the same `/ontologies/list` endpoint with the `q` filter param and
 * returns a lean projection. Only the user scope is searched — the org scope is
 * disabled backend-side.
 */
export async function searchOntologies(query: string): Promise<OntologyData[]> {
  const trimmed = query.trim();
  if (!trimmed) return [];

  const params = new URLSearchParams({ scopes: "user", q: trimmed });
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/list?${params.toString()}`;
  const response = await HttpService.get(url, PROMETHEUX_CONFIG.AUTH_TOKEN);

  if (response.status !== "success" || !Array.isArray(response.data)) return [];

  return (response.data as OntologyListRow[])
    .filter((row): row is OntologyListRow & { id: string } => Boolean(row?.id))
    .map((row) => ({
      id: row.id,
      name: row.name || row.id,
      description: row.description ?? "",
      author: row.author ?? "",
      scope: row.scope ?? "user",
    }));
}
