import { useCallback, useEffect, useRef, useState } from "react";
import { MachineClient } from "@/features/compute/api/MachineClient";
import type { AvailabilityResult, UserMachine } from "@/features/compute/utils";

export const useMachineStatus = (
  userMachines: UserMachine[],
  setUserMachines: React.Dispatch<React.SetStateAction<UserMachine[]>>,
  loadCount: number,
) => {
  const [checkingAvailability, setCheckingAvailability] = useState<Record<string, boolean>>({});
  const [availabilityResults, setAvailabilityResults] = useState<
    Record<string, AvailabilityResult>
  >({});
  const [refreshingMachines, setRefreshingMachines] = useState(false);
  // Machines whose status check has failed — skipped by checkAllMachinesStatus until
  // an explicit refresh or a successful call clears the entry.
  const failedMachinesRef = useRef<Set<string>>(new Set());
  const [usageDialogOpen, setUsageDialogOpen] = useState(false);
  const [selectedUsageMachine, setSelectedUsageMachine] = useState<{
    userMachineId: string;
    machineName: string;
  } | null>(null);
  const [usageData, setUsageData] = useState<any>(null);
  const [loadingUsage, setLoadingUsage] = useState(false);

  const clientRef = useRef(new MachineClient());

  const checkMachineStatus = useCallback(
    async (
      machineId: string,
      userMachineId: string,
    ): Promise<
      "started" | "stopped" | "stopping" | "pending" | "starting" | "crashed" | "restarting"
    > => {
      setCheckingAvailability((prev) => ({ ...prev, [machineId]: true }));

      try {
        const result = await clientRef.current.getMachineStatus(userMachineId);
        failedMachinesRef.current.delete(machineId);
        const machineStatus = (result.data?.machine_status || "stopped") as
          | "started"
          | "stopped"
          | "stopping"
          | "pending"
          | "starting"
          | "crashed"
          | "restarting";
        const machineInfo = result.data?.pod_info;
        const metrics = result.data?.metrics;
        const isActive = result.data?.is_active ?? false;
        const usage = result.data?.usage || {};

        const isAvailable = machineStatus === "started";

        let statusMessage = "";
        switch (machineStatus) {
          case "started":
            statusMessage = `Running (CPU: ${metrics?.cpu_cores || 0} cores, Memory: ${metrics?.memory_gb || 0} GB)`;
            break;
          case "stopped":
            statusMessage = "Stopped - Click Start to begin";
            break;
          case "stopping":
            statusMessage = "Stopping...";
            break;
          case "pending":
            statusMessage = "Starting up...";
            break;
          case "starting":
            statusMessage = "Container is being created...";
            break;
          case "crashed":
            statusMessage = `Crashed - Restarts: ${machineInfo?.restarts || 0}`;
            break;
          case "restarting":
            statusMessage = "Restarting...";
            break;
          default:
            statusMessage = "Unknown status";
        }

        setAvailabilityResults((prev) => ({
          ...prev,
          [machineId]: {
            status: result.status,
            message: statusMessage,
            is_available: isAvailable,
            machine_status: machineStatus,
            pod_info: machineInfo,
            metrics: metrics,
          },
        }));

        setUserMachines((prev) =>
          prev.map((um) => {
            if (um.id === userMachineId) {
              const updates: Partial<UserMachine> = { is_active: isActive };

              if (usage.free_minutes_remaining !== undefined) {
                updates.free_minutes_remaining = usage.free_minutes_remaining;
              }
              if (usage.total_usage_minutes !== undefined) {
                updates.total_usage_minutes = usage.total_usage_minutes;
              }
              if (usage.current_session !== undefined) {
                updates.current_session = usage.current_session;
              }
              if (usage.current_session_cost_usd !== undefined) {
                updates.current_session_cost_usd = usage.current_session_cost_usd;
              }

              return { ...um, ...updates };
            }
            return um;
          }),
        );

        return machineStatus;
      } catch (error) {
        console.error("Error checking machine status:", error);
        failedMachinesRef.current.add(machineId);
        setAvailabilityResults((prev) => ({
          ...prev,
          [machineId]: {
            status: "error",
            message: "Failed to check status",
            is_available: false,
          },
        }));
        return "stopped";
      } finally {
        setCheckingAvailability((prev) => ({ ...prev, [machineId]: false }));
      }
    },
    [],
  );

  const fetchUsageData = async (userMachineId: string, machineName: string) => {
    setLoadingUsage(true);
    setSelectedUsageMachine({ userMachineId, machineName });
    setUsageDialogOpen(true);

    try {
      const result = await clientRef.current.getMachineUsage(userMachineId);
      setUsageData(result.data);
    } catch (error) {
      console.error("Error fetching usage data:", error);
      setUsageData(null);
    } finally {
      setLoadingUsage(false);
    }
  };

  const checkAllMachinesStatus = async () => {
    if (userMachines.length === 0) return;

    const machinesWithInfo = userMachines.filter((um) => um.machines);
    if (machinesWithInfo.length === 0) return;

    for (const userMachine of machinesWithInfo) {
      if (userMachine.machines) {
        if (failedMachinesRef.current.has(userMachine.machines.id)) continue;
        try {
          await checkMachineStatus(userMachine.machines.id, userMachine.id);
        } catch (error) {
          console.error(`Failed to check status for machine ${userMachine.machines.id}:`, error);
        }
      }
    }
  };

  const handleRefreshMachines = async () => {
    setRefreshingMachines(true);
    failedMachinesRef.current.clear();
    try {
      await checkAllMachinesStatus();
    } finally {
      setRefreshingMachines(false);
    }
  };

  // Check status for all machines once after they finish loading.
  // checkAllMachinesStatus is intentionally excluded from the dep array —
  // it is not memoized and would cause an infinite loop if included.
  // Ongoing updates are handled by useMachineStatusStream (WebSocket).
  useEffect(() => {
    if (loadCount === 0) return;
    checkAllMachinesStatus();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadCount]);

  return {
    checkingAvailability,
    availabilityResults,
    setAvailabilityResults,
    refreshingMachines,
    usageDialogOpen,
    setUsageDialogOpen,
    selectedUsageMachine,
    usageData,
    loadingUsage,
    checkMachineStatus,
    fetchUsageData,
    handleRefreshMachines,
  };
};
