import { useCallback, useRef } from "react";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { useAgentMessageUsage } from "@/features/billing/hooks/useAgentMessageUsage";
import { DatabricksConfigService } from "@/features/compute/api/databricksService";
import { getAuthToken } from "@/shared/auth/authToken";
import { gatherTurnContext } from "../agentContext";
import { AgentMessageLimitError, sendAgentMessage } from "../api";
import type { AuthorizationDecision } from "../components/AuthorizationPrompt";
import { RESUME_PROMPT } from "../halt.utils";
import type { AuthorizationData } from "../store";
import { useCodeAssistantStore } from "../store";
import { useAuthorizationsStore } from "../store/authorizationsStore";
import { toolDetailFromInput } from "../toolActivity.utils";
import { resolveUserTurnIndex } from "../turnIndex.utils";
import type {
  AgentTurnInput,
  EditTurnInput,
  RunCoreInput,
  UseAgentTurnConfig,
} from "./agentTurn.types";

export type { AgentTurnInput, EditTurnInput, UseAgentTurnConfig } from "./agentTurn.types";

/**
 * Owns the full lifecycle of one agent chat turn: the user bubble, streamed
 * assistant text, tool/proposal/context/clarification chips, the plan card,
 * abort wiring, and error/cleanup.
 *
 * Both the in-project assistant panel and the Home chat consume this hook so
 * the streaming behaviour lives in exactly one place. In particular, the
 * chronological interleaving of chips and text — rotating the assistant bubble
 * anchor whenever a sibling chip is appended so later text renders *below* the
 * chip rather than merging into the bubble above — is implemented here once.
 */
export function useAgentTurn(config: UseAgentTurnConfig): {
  runTurn: (input: AgentTurnInput) => Promise<void>;
  editTurn: (input: EditTurnInput) => Promise<void>;
  resolveAuthorization: (
    messageId: string,
    decision: AuthorizationDecision,
    data: AuthorizationData,
  ) => Promise<void>;
  resumeAfterCredentials: (provided: boolean) => Promise<void>;
  resumeTurn: () => Promise<void>;
} {
  const { ontologyId, currentDashboard, onModel, onToolSideEffect } = config;
  const { session } = useAuth();
  const { refetch: refetchAgentUsage } = useAgentMessageUsage();

  const {
    sessionId,
    selectedModel,
    addUserMessage,
    appendToAssistantMessage,
    appendToThinkingMessage,
    addToolMessage,
    updateToolMessage,
    setToolProgress,
    addProposalMessage,
    addContextLoadedMessage,
    addWriterProposalMessage,
    addClarificationMessage,
    addAuthorizationMessage,
    setAuthorizationState,
    addCredentialRequestMessage,
    setPendingApprovedCalls,
    consumePendingApprovedCalls,
    upsertPlanMessage,
    setHaltNotice,
    setLoading,
    setSessionTitle,
    setActiveChatAbortController,
    bumpHistoryRevision,
    openAgentLimitDialog,
    truncateFromMessage,
  } = useCodeAssistantStore();

  // Anchor for the current assistant text run. Rotated whenever a sibling chip
  // (tool/proposal/context/clarification) is appended so text streamed after it
  // becomes a new bubble below the chip, preserving chronological order.
  const assistantIdRef = useRef<string>(crypto.randomUUID());
  const currentToolRef = useRef<string | null>(null);
  // Separate anchor for streamed extended-thinking. Each reasoning run becomes
  // its own collapsible block, closed (a fresh id minted) as soon as real text
  // or a chip follows it so the answer renders below rather than inside it.
  const thinkingIdRef = useRef<string>(crypto.randomUUID());
  const isThinkingRef = useRef(false);
  // Turns must never overlap on one session. An authorization resume starts
  // from an event handler while the previous turn's fetch is still draining
  // its tail (the stream stays open past `done` for history persistence and
  // session_meta), so each turn waits for the previous one to fully settle.
  const turnChainRef = useRef<Promise<void>>(Promise.resolve());

  // Shared streaming core for both new turns and edited re-runs. The caller has
  // already appended the user bubble; this drives the stream, chip/text
  // interleaving, abort wiring, and cleanup.
  const runCore = useCallback(
    async ({
      messageForAgent,
      attachmentPaths,
      editFromUserTurn,
      focusedWidget,
      continuation,
    }: RunCoreInput) => {
      const previousTurn = turnChainRef.current;
      let releaseTurn: () => void = () => {};
      turnChainRef.current = new Promise<void>((resolve) => {
        releaseTurn = resolve;
      });
      await previousTurn;

      setLoading(true);
      setHaltNotice(null);
      assistantIdRef.current = crypto.randomUUID();
      thinkingIdRef.current = crypto.randomUUID();
      isThinkingRef.current = false;

      // Close the current thinking block (if any) so subsequent text/chips land
      // below it and the next reasoning run starts a fresh, separate block.
      const endThinking = () => {
        if (!isThinkingRef.current) return;
        isThinkingRef.current = false;
        thinkingIdRef.current = crypto.randomUUID();
      };

      const controller = new AbortController();
      setActiveChatAbortController(controller);

      // Read at send time (not render time) so the values are always current.
      const turnContext = gatherTurnContext(useCodeAssistantStore.getState());
      // The focused concept belongs to a project editor; never leak a stale
      // one into the project-less Home chat.
      const focusedConcept = ontologyId === "_" ? undefined : turnContext.focusedConcept;

      // Consent policy for this turn: read the persisted mode + allow-list at
      // send time, and drain any one-shot approval queued by an "Allow once".
      const { mode, authorizedTools } = useAuthorizationsStore.getState();
      const approvedCalls = consumePendingApprovedCalls();

      try {
        await sendAgentMessage({
          ontologyId,
          message: messageForAgent,
          sessionId,
          authToken: getAuthToken(),
          supabaseToken: session?.access_token,
          attachmentPaths: attachmentPaths.length > 0 ? attachmentPaths : undefined,
          editFromUserTurn,
          continuation,
          focusedConcept,
          currentDashboard,
          focusedWidget,
          contextRevisions: turnContext.contextRevisions,
          model: selectedModel ?? undefined,
          mode,
          authorizedTools,
          approvedCalls,
          signal: controller.signal,
          onChunk: (chunk) => {
            endThinking();
            appendToAssistantMessage(assistantIdRef.current, chunk);
          },
          onThinking: (chunk) => {
            isThinkingRef.current = true;
            appendToThinkingMessage(thinkingIdRef.current, chunk);
          },
          onModel: onModel ?? (() => {}),
          onToolStart: (tool, input) => {
            endThinking();
            currentToolRef.current = addToolMessage(tool, toolDetailFromInput(input), input);
            assistantIdRef.current = crypto.randomUUID();
          },
          onToolProgress: (_tool, progress) => {
            if (currentToolRef.current) setToolProgress(currentToolRef.current, progress);
          },
          onToolResult: (tool, result) => {
            if (currentToolRef.current) {
              const ok = result?.success !== false;
              const errorMessage =
                !ok && typeof result?.error === "string" ? result.error : undefined;
              if (tool === "create_ontology" && ok) {
                const pid = (result.ontology_id ?? result.id) as string | undefined;
                updateToolMessage(
                  currentToolRef.current,
                  "done",
                  undefined,
                  pid,
                  undefined,
                  result,
                );
              } else {
                updateToolMessage(
                  currentToolRef.current,
                  ok ? "done" : "error",
                  undefined,
                  undefined,
                  errorMessage,
                  result,
                );
              }
              currentToolRef.current = null;
            }
            if (result?.success !== false) onToolSideEffect?.(tool, result);
          },
          onProposal: (data) => {
            endThinking();
            currentToolRef.current = addProposalMessage(data);
            assistantIdRef.current = crypto.randomUUID();
          },
          onContextLoaded: (data) => {
            if (data.count > 0) {
              endThinking();
              addContextLoadedMessage(data);
              assistantIdRef.current = crypto.randomUUID();
            }
          },
          onWriterProposal: (data) => {
            endThinking();
            addWriterProposalMessage(data);
            assistantIdRef.current = crypto.randomUUID();
          },
          onClarification: (data) => {
            endThinking();
            addClarificationMessage(data);
            assistantIdRef.current = crypto.randomUUID();
          },
          onAuthorizationRequest: (data) => {
            endThinking();
            addAuthorizationMessage(data);
            assistantIdRef.current = crypto.randomUUID();
          },
          onCredentialRequest: (data) => {
            endThinking();
            addCredentialRequestMessage(data);
            assistantIdRef.current = crypto.randomUUID();
          },
          onHalted: setHaltNotice,
          onPlan: (steps, planId) => {
            endThinking();
            upsertPlanMessage(steps, planId);
          },
          onSessionMeta: (data) => {
            if (data.title) setSessionTitle(data.title);
          },
        });
      } catch (err) {
        if (err instanceof AgentMessageLimitError) {
          openAgentLimitDialog();
        } else if (!controller.signal.aborted) {
          appendToAssistantMessage(assistantIdRef.current, `**Error:** ${(err as Error).message}`);
        }
      } finally {
        releaseTurn();
        // Don't clobber state a newer turn owns (an authorization resume
        // installs its own controller); null means the stop button cleared ours.
        const { activeChatAbortController } = useCodeAssistantStore.getState();
        if (activeChatAbortController === null || activeChatAbortController === controller) {
          setActiveChatAbortController(null);
          setLoading(false);
        }
        bumpHistoryRevision();
        refetchAgentUsage();
      }
    },
    [
      ontologyId,
      currentDashboard,
      onModel,
      onToolSideEffect,
      sessionId,
      selectedModel,
      session?.access_token,
      appendToAssistantMessage,
      appendToThinkingMessage,
      addToolMessage,
      updateToolMessage,
      setToolProgress,
      addProposalMessage,
      addContextLoadedMessage,
      addWriterProposalMessage,
      addClarificationMessage,
      addAuthorizationMessage,
      addCredentialRequestMessage,
      consumePendingApprovedCalls,
      upsertPlanMessage,
      setHaltNotice,
      setLoading,
      setSessionTitle,
      setActiveChatAbortController,
      bumpHistoryRevision,
      openAgentLimitDialog,
      refetchAgentUsage,
    ],
  );

  const runTurn = useCallback(
    async ({ userText, attachmentPaths, attachments }: AgentTurnInput) => {
      addUserMessage(userText, attachments);
      // A queued widget reference rides this one turn as a structured field,
      // then clears — the user's message text stays clean.
      const { focusedWidget, setFocusedWidget } = useCodeAssistantStore.getState();
      if (focusedWidget) setFocusedWidget(null);
      await runCore({
        messageForAgent: userText,
        attachmentPaths,
        focusedWidget,
      });
    },
    [addUserMessage, runCore],
  );

  // Resolve a pending authorization prompt. The backend halted the turn after
  // asking; whatever the user decides, we resume with a fresh turn (no user
  // bubble — the decision lives on the card) so the model re-issues (or drops)
  // the exact call. Allow-once queues the one-shot key; Always-allow also
  // persists the tool to the standing allow-list so it stops asking.
  const resolveAuthorization = useCallback(
    async (messageId: string, decision: AuthorizationDecision, data: AuthorizationData) => {
      if (decision === "deny") {
        setAuthorizationState(messageId, "denied");
        await runCore({
          messageForAgent:
            "I denied that action. Do not attempt it — continue with the rest without it.",
          attachmentPaths: [],
          continuation: true,
        });
        return;
      }

      if (decision === "always" && data.persistable) {
        useAuthorizationsStore.getState().authorizeTool(data.tool);
      }
      setAuthorizationState(messageId, decision === "always" ? "always_allowed" : "allowed_once");
      // The one-shot key clears the just-halted call regardless of the standing
      // allow-list (which only kicks in from the next turn onward).
      if (data.callKey) setPendingApprovedCalls([data.callKey]);
      await runCore({
        messageForAgent: "Approved — go ahead with that action.",
        attachmentPaths: [],
        continuation: true,
      });
    },
    [runCore, setAuthorizationState, setPendingApprovedCalls],
  );

  // Pick the turn back up after the credential form. The card has already sent
  // the credential to the backend on its own request, so all this carries is the
  // fact that it is there — the value itself never enters the conversation.
  //
  // Hydrating first keeps the browser's own copy in step: every turn re-posts
  // the compute block from localStorage, replacing what the backend holds, so a
  // stale local config would undo the credential that was just stored.
  const resumeAfterCredentials = useCallback(
    async (provided: boolean) => {
      if (!provided) {
        await runCore({
          messageForAgent:
            "I didn't provide the credentials. Don't ask again in the chat — carry on without Databricks.",
          attachmentPaths: [],
          continuation: true,
        });
        return;
      }
      await DatabricksConfigService.hydrateFromBackend();
      await runCore({
        messageForAgent:
          "I've entered the credentials in the secure form — they're stored now. Carry on.",
        attachmentPaths: [],
        continuation: true,
      });
    },
    [runCore],
  );

  // Continue a turn the backend cut short on its budget. Like an authorization
  // resume it carries no user bubble — the halt notice is the visible record.
  const resumeTurn = useCallback(
    () => runCore({ messageForAgent: RESUME_PROMPT, attachmentPaths: [], continuation: true }),
    [runCore],
  );

  // Edit a prior user message: discard it and everything after (locally +, via
  // editFromUserTurn, on the backend) then re-run from the new text. The index
  // identifies the backend's Nth persisted user row. Attachments are dropped.
  const editTurn = useCallback(
    async ({ messageId, userText }: EditTurnInput) => {
      const current = useCodeAssistantStore.getState().messages;
      const idx = current.findIndex((m) => m.id === messageId);
      if (idx < 0) return;
      const userTurnIndex = resolveUserTurnIndex(current, idx);
      truncateFromMessage(messageId);
      addUserMessage(userText);
      await runCore({
        messageForAgent: userText,
        attachmentPaths: [],
        editFromUserTurn: userTurnIndex,
      });
    },
    [truncateFromMessage, addUserMessage, runCore],
  );

  return { runTurn, editTurn, resolveAuthorization, resumeAfterCredentials, resumeTurn };
}
