import { useCallback, useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { useRequireCompute } from "@/features/compute/hooks/useRequireCompute";
import {
  type AppConcept,
  ConceptClient,
  type ConceptStatusEvent,
  type FetchResult,
} from "../api/ConceptClient";
import type { DashboardTableHandlers } from "../components/outputs/table/tableOutput.types";
import type { DashboardDefinition } from "../types";
import { type ParsedParam, parseParamAnnotations } from "../utils/paramParser";
import { useTableActions } from "./useTableActions";

const client = new ConceptClient();

export type ParamValues = Record<string, string | number | boolean>;

interface UseDashboardRunParams {
  dashboard: DashboardDefinition | null;
  allWidgetConcepts: string[];
  parsedParams: ParsedParam[];
  inputConcept: AppConcept | null;
  conceptsLoading: boolean;
}

interface UseDashboardRunReturn {
  paramValues: ParamValues;
  setParamValues: React.Dispatch<React.SetStateAction<ParamValues>>;
  isRunning: boolean;
  runStatus: string;
  conceptData: Record<string, FetchResult | null>;
  loadingConcepts: Record<string, boolean>;
  errorConcepts: Record<string, string>;
  handleRun: () => Promise<void>;
  tableHandlers: DashboardTableHandlers;
}

export function useDashboardRun({
  dashboard,
  allWidgetConcepts,
  parsedParams,
  inputConcept,
  conceptsLoading,
}: UseDashboardRunParams): UseDashboardRunReturn {
  const [paramValues, setParamValues] = useState<ParamValues>({});
  const [isRunning, setIsRunning] = useState(false);
  const [runStatus, setRunStatus] = useState("");
  const [conceptData, setConceptData] = useState<Record<string, FetchResult | null>>({});
  const [loadingConcepts, setLoadingConcepts] = useState<Record<string, boolean>>({});
  const [errorConcepts, setErrorConcepts] = useState<Record<string, string>>({});

  const { ensureCompute } = useRequireCompute();

  // Initialise param defaults when inputConcept changes
  useEffect(() => {
    const ann = inputConcept?.concept_details?.[0]?.param_annotations;
    if (!ann) return;
    const defaults: ParamValues = {};
    parseParamAnnotations(ann).forEach((p) => {
      defaults[p.name] = p.defaultValue;
    });
    setParamValues(defaults);
  }, [inputConcept]);

  const handleRun = useCallback(async () => {
    if (!dashboard) return;
    // No compute running → prompt the user to start a machine instead of failing silently.
    if (!ensureCompute()) return;

    setIsRunning(true);
    setConceptData({});
    setErrorConcepts({});

    const loadingMap: Record<string, boolean> = {};
    allWidgetConcepts.forEach((n) => {
      loadingMap[n] = true;
    });
    setLoadingConcepts(loadingMap);

    try {
      for (const conceptName of allWidgetConcepts) {
        try {
          setRunStatus(`Running: ${conceptName}`);
          const evalResults = await client.runConceptWithParams(
            dashboard.ontologyId,
            conceptName,
            paramValues,
            "user",
            true,
            (e: ConceptStatusEvent) => {
              if (e.concept && e.status) setRunStatus(`${e.concept}: ${e.status}`);
            },
          );
          let data: FetchResult;
          try {
            data = await client.fetchConceptData(dashboard.ontologyId, conceptName, "user");
          } catch {
            const fromStream = client.extractFromEvalResults(evalResults, conceptName);
            if (!fromStream) throw new Error("No data returned");
            data = fromStream;
          }
          setConceptData((prev) => ({ ...prev, [conceptName]: data }));
        } catch (err: unknown) {
          const message = err instanceof Error ? err.message : "Failed to load";
          console.error(`[DashboardRun] Failed to run concept "${conceptName}":`, err);
          toast.error(`Failed to run "${conceptName}": ${message}`);
          setErrorConcepts((prev) => ({ ...prev, [conceptName]: message }));
        } finally {
          setLoadingConcepts((prev) => ({ ...prev, [conceptName]: false }));
        }
      }
    } finally {
      setIsRunning(false);
      setRunStatus("");
    }
  }, [dashboard, allWidgetConcepts, paramValues, ensureCompute]);

  const tableHandlers = useTableActions({
    client,
    ontologyId: dashboard?.ontologyId,
    conceptData,
    setConceptData,
    setLoadingConcepts,
    setErrorConcepts,
  });

  // Auto-run once on mount, after concepts are loaded and param defaults are applied.
  // parsedParams.length > 0 means we must wait for paramValues to be populated first.
  const autoRunTriggered = useRef(false);
  useEffect(() => {
    if (!dashboard || conceptsLoading || autoRunTriggered.current) return;
    if (parsedParams.length > 0 && Object.keys(paramValues).length === 0) return;
    // If no compute is running, ensureCompute() opens the start-machine modal and
    // returns false. We deliberately don't mark autoRunTriggered yet — once the user
    // starts a machine, ensureCompute's identity changes, this effect re-runs and the
    // dashboard runs automatically.
    if (!ensureCompute()) return;
    autoRunTriggered.current = true;
    handleRun();
  }, [dashboard, conceptsLoading, parsedParams.length, paramValues, ensureCompute, handleRun]);

  return {
    paramValues,
    setParamValues,
    isRunning,
    runStatus,
    conceptData,
    loadingConcepts,
    errorConcepts,
    handleRun,
    tableHandlers,
  };
}
