import { ChevronDown, ChevronRight, Sparkles } from "lucide-react";
import { useState } from "react";

import { DemoDataPicker } from "@/features/data-sources/components/DemoDataPicker";
import type { DemoSourcePreset } from "@/features/data-sources/types";
import { cn } from "@/shared/lib/utils";

interface DemoDataSuggestionProps {
  onPickPreset: (preset: DemoSourcePreset) => void;
  defaultOpen?: boolean;
  className?: string;
}

export function DemoDataSuggestion({
  onPickPreset,
  defaultOpen = false,
  className,
}: DemoDataSuggestionProps) {
  const [open, setOpen] = useState(defaultOpen);
  const toggleOpen = () => setOpen((prev) => !prev);

  return (
    <div className={cn("rounded-xl border bg-card", className)}>
      <button
        type="button"
        onClick={toggleOpen}
        className="flex w-full items-center gap-2 px-4 py-3 text-left transition-colors hover:bg-muted/40"
      >
        <Sparkles className="h-4 w-4 shrink-0 text-primary" />
        <span className="flex-1 text-sm font-medium text-foreground">
          Available px-datasources — no setup needed
        </span>
        {open ? (
          <ChevronDown className="h-4 w-4 shrink-0 text-muted-foreground" />
        ) : (
          <ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground" />
        )}
      </button>
      {open && (
        <div className="border-t px-4 py-4">
          <p className="mb-3 text-xs text-muted-foreground">
            Pick a Prometheux read-only datasource to open the connection form pre-filled with its
            details — review them and connect to start exploring.
          </p>
          <DemoDataPicker onPickPreset={onPickPreset} />
        </div>
      )}
    </div>
  );
}

export default DemoDataSuggestion;
