/**
 * Pure helpers shared by QueryConceptCell and QuerySqlCell.
 */

/** Accordion title: the concept name, or a positional fallback (`prefix N`). */
export function getCellTitle(
  outputPredicate: string | undefined,
  index: number,
  prefix: string,
): string {
  if (outputPredicate) return outputPredicate;
  return `${prefix} ${index + 1}`;
}

/** A cell is "new" when it has no real name yet (id or positional fallback). */
export function isNewCellTitle(cellTitle: string, cellId: string, prefix: string): boolean {
  return cellTitle === cellId || cellTitle.startsWith(`${prefix} `);
}

/**
 * Extract unique predicate names from cell code. Supports both traditional
 * Vadalog rules (:- operator) and SQL-in-body rules (<- operator).
 */
export function getPredicateNames(code: string): string[] {
  const regex = /^\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\([^)]*\)\s*(<-|:-)/gm;
  const matches = Array.from(code.matchAll(regex));
  const names = matches.map((m) => m[1]);
  return Array.from(new Set(names));
}
