import { useEffect, useState } from "react";

import { AttachmentGoneError, loadAttachmentPreview } from "../attachmentPreview";
import type { MessageAttachment } from "../attachments.types";

type FailureState = "gone" | "failed" | null;

interface UseAttachmentPreviewReturn {
  /** Object URL to render, once one is available. */
  url?: string;
  isLoading: boolean;
  hasFailed: boolean;
  /** The file is gone rather than momentarily unreachable. */
  isGone: boolean;
}

/**
 * Resolves the thumbnail for one attachment chip.
 *
 * A freshly sent attachment already has an object URL from the file the user
 * picked. A restored one only has its server path, so the bytes are fetched
 * back — otherwise reopening a conversation turned every screenshot into a
 * generic file icon.
 */
export function useAttachmentPreview(attachment: MessageAttachment): UseAttachmentPreviewReturn {
  const { kind, previewUrl, path } = attachment;
  const [fetchedUrl, setFetchedUrl] = useState<string | undefined>(undefined);
  const [failure, setFailure] = useState<FailureState>(null);

  const shouldFetch = kind === "image" && !previewUrl && !!path;

  useEffect(() => {
    if (!shouldFetch || !path) return;
    let isActive = true;
    loadAttachmentPreview(path)
      .then((url) => {
        if (isActive) setFetchedUrl(url);
      })
      .catch((err: unknown) => {
        if (isActive) setFailure(err instanceof AttachmentGoneError ? "gone" : "failed");
      });
    return () => {
      isActive = false;
    };
  }, [shouldFetch, path]);

  return {
    url: previewUrl ?? fetchedUrl,
    isLoading: shouldFetch && !fetchedUrl && failure === null,
    hasFailed: failure !== null,
    isGone: failure === "gone",
  };
}
