import { useCallback, useEffect, useState } from "react";
import type {
  DashboardDefinition,
  DashboardHeader,
  DashboardPage,
  DashboardSection,
} from "../types";

interface UseCanvasDefinitionReturn {
  name: string;
  setName: (v: string) => void;
  ontologyId: string;
  setOntologyId: (v: string) => void;
  inputConceptName: string;
  setInputConceptName: (v: string) => void;
  header: DashboardHeader;
  setHeader: React.Dispatch<React.SetStateAction<DashboardHeader>>;
  pages: DashboardPage[];
  setPages: React.Dispatch<React.SetStateAction<DashboardPage[]>>;
  addPage: () => void;
  updatePage: (id: string, p: DashboardPage) => void;
  removePage: (id: string) => void;
}

export function useCanvasDefinition(
  dashboard: DashboardDefinition | null,
): UseCanvasDefinitionReturn {
  const [name, setName] = useState(dashboard?.name ?? "");
  const [ontologyId, setOntologyId] = useState(dashboard?.ontologyId ?? "");
  const [inputConceptName, setInputConceptName] = useState(dashboard?.inputConceptName ?? "");
  const [header, setHeader] = useState<DashboardHeader>(
    dashboard?.header ?? { title: "", showStatus: false },
  );
  const [pages, setPages] = useState<DashboardPage[]>(dashboard?.pages ?? []);

  // Sync all definition state when switching to a different dashboard
  useEffect(() => {
    setName(dashboard?.name ?? "");
    setOntologyId(dashboard?.ontologyId ?? "");
    setInputConceptName(dashboard?.inputConceptName ?? "");
    setHeader(dashboard?.header ?? { title: "", showStatus: false });
    setPages(dashboard?.pages ?? []);
  }, [
    dashboard?.ontologyId,
    dashboard?.inputConceptName,
    dashboard?.pages,
    dashboard?.name,
    dashboard?.header,
  ]);

  const addPage = useCallback(() => {
    setPages((prev) => [
      ...prev,
      {
        id: crypto.randomUUID(),
        label: `Page ${prev.length + 1}`,
        sections: [] as DashboardSection[],
      },
    ]);
  }, []);

  const updatePage = useCallback((id: string, p: DashboardPage) => {
    setPages((prev) => prev.map((pp) => (pp.id === id ? p : pp)));
  }, []);

  const removePage = useCallback((id: string) => {
    setPages((prev) => prev.filter((pp) => pp.id !== id));
  }, []);

  return {
    name,
    setName,
    ontologyId,
    setOntologyId,
    inputConceptName,
    setInputConceptName,
    header,
    setHeader,
    pages,
    setPages,
    addPage,
    updatePage,
    removePage,
  };
}
