import { Database, Table2 } from "lucide-react";
import type React from "react";

export type DatasourceDetailTabId = "details" | "preview";

interface DatasourceDetailTabsProps {
  activeTab: DatasourceDetailTabId;
  onTabChange: (tab: DatasourceDetailTabId) => void;
  /** Binary-file sources have no rows to show, so they get no Preview tab. */
  canPreview: boolean;
}

const TAB_CLASSES = "px-3 py-2 text-xs font-medium border-b-2 transition-colors";
const ACTIVE_TAB_CLASSES = "border-primary text-foreground";
const INACTIVE_TAB_CLASSES = "border-transparent text-muted-foreground hover:text-foreground";

const DatasourceDetailTabs: React.FC<DatasourceDetailTabsProps> = ({
  activeTab,
  onTabChange,
  canPreview,
}) => {
  const classesFor = (tab: DatasourceDetailTabId) =>
    `${TAB_CLASSES} ${activeTab === tab ? ACTIVE_TAB_CLASSES : INACTIVE_TAB_CLASSES}`;

  const handleDetailsClick = () => onTabChange("details");
  const handlePreviewClick = () => onTabChange("preview");

  return (
    <div className="flex-shrink-0 flex border-b px-4 mt-1">
      <button type="button" onClick={handleDetailsClick} className={classesFor("details")}>
        <span className="flex items-center gap-1.5">
          <Database className="h-3.5 w-3.5" />
          Details
        </span>
      </button>
      {canPreview && (
        <button type="button" onClick={handlePreviewClick} className={classesFor("preview")}>
          <span className="flex items-center gap-1.5">
            <Table2 className="h-3.5 w-3.5" />
            Preview
          </span>
        </button>
      )}
    </div>
  );
};

export default DatasourceDetailTabs;
