import { useCallback, useMemo } from "react";
import type { AppDefinition } from "../../schema/appDefinition.types";
import { useAppEditorStore } from "../../store/appEditorStore";
import { AppRenderer } from "../app/AppRenderer";
import { EditorSelectionProvider, type EditorSelectionValue } from "../app/editorSelection";

interface EditorPreviewProps {
  definition: AppDefinition;
}

/**
 * The center pane: the real AppRenderer running live against the draft — the
 * preview IS the canvas (ADR D7). In select mode clicks map widgets back to
 * their schema nodes; interact mode restores the app's own behavior.
 */
export function EditorPreview({ definition }: EditorPreviewProps) {
  const selection = useAppEditorStore((state) => state.selection);
  const select = useAppEditorStore((state) => state.select);
  const activePageId = useAppEditorStore((state) => state.activePageId);
  const setActivePage = useAppEditorStore((state) => state.setActivePage);
  const interactMode = useAppEditorStore((state) => state.interactMode);

  const onSelectWidget = useCallback(
    (sectionId: string, widgetId: string) => {
      const pageId = useAppEditorStore.getState().activePageId;
      select({ kind: "widget", pageId, sectionId, widgetId });
    },
    [select],
  );

  const selectionValue: EditorSelectionValue = useMemo(
    () => ({
      selectedWidgetId: selection?.kind === "widget" ? selection.widgetId : null,
      interactMode,
      onSelectWidget,
    }),
    [selection, interactMode, onSelectWidget],
  );

  return (
    <div className="flex-1 min-w-0 overflow-hidden">
      <EditorSelectionProvider value={selectionValue}>
        <AppRenderer
          definition={definition}
          activePageId={activePageId}
          onActivePageChange={setActivePage}
        />
      </EditorSelectionProvider>
    </div>
  );
}
