import type React from "react";
import { useEffect, useState } from "react";
import { Button } from "@/shared/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";

interface GroupDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (groupName: string) => void;
  initialName?: string;
  mode: "create" | "rename" | "assign";
  existingGroups?: string[];
}

const GroupDialog: React.FC<GroupDialogProps> = ({
  isOpen,
  onClose,
  onConfirm,
  initialName = "",
  mode,
  existingGroups = [],
}) => {
  const [groupName, setGroupName] = useState(initialName);
  const [useExisting, setUseExisting] = useState(mode === "assign" && existingGroups.length > 0);

  useEffect(() => {
    if (isOpen) {
      setGroupName(initialName);
      setUseExisting(mode === "assign" && existingGroups.length > 0);
    }
  }, [isOpen, initialName, mode, existingGroups.length]);

  const handleConfirm = () => {
    if (groupName.trim()) {
      onConfirm(groupName.trim());
      setGroupName("");
      onClose();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && groupName.trim()) {
      handleConfirm();
    }
  };

  const getTitle = () => {
    if (mode === "create") return "Create New Group";
    if (mode === "rename") return "Rename Group";
    return "Assign to Group";
  };

  const getDescription = () => {
    if (mode === "create") return "Enter a name for the new cell group.";
    if (mode === "rename") return "Enter a new name for this group.";
    return "Select an existing group or create a new one.";
  };

  const getButtonText = () => {
    if (mode === "create") return "Create";
    if (mode === "rename") return "Rename";
    return "Assign";
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>{getTitle()}</DialogTitle>
          <DialogDescription>{getDescription()}</DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          {mode === "assign" && existingGroups.length > 0 && (
            <div className="grid gap-2">
              <Label>Choose Option</Label>
              <div className="flex gap-4">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    checked={useExisting}
                    onChange={() => setUseExisting(true)}
                    className="cursor-pointer"
                  />
                  <span className="text-sm">Use existing group</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    checked={!useExisting}
                    onChange={() => setUseExisting(false)}
                    className="cursor-pointer"
                  />
                  <span className="text-sm">Create new group</span>
                </label>
              </div>
            </div>
          )}
          <div className="grid gap-2">
            <Label htmlFor="group-name">
              {mode === "assign" && useExisting && existingGroups.length > 0
                ? "Select Group"
                : "Group Name"}
            </Label>
            {mode === "assign" && useExisting && existingGroups.length > 0 ? (
              <select
                id="group-name"
                value={groupName}
                onChange={(e) => setGroupName(e.target.value)}
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <option value="">Select a group...</option>
                {existingGroups.map((group) => (
                  <option key={group} value={group}>
                    {group}
                  </option>
                ))}
              </select>
            ) : (
              <Input
                id="group-name"
                value={groupName}
                onChange={(e) => setGroupName(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="e.g., Data Processing, Analysis..."
                autoFocus
              />
            )}
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button onClick={handleConfirm} disabled={!groupName.trim()}>
            {getButtonText()}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default GroupDialog;
