import { useEffect, useState } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { getDefaultBaseUrl, PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import SettingsSection from "./SettingsSection";

const LOCAL_STORAGE_SERVICE_URL_KEY = "prometheux_service_url_override";

const ServiceUrlSettings = () => {
  const { user } = useAuth();
  const [serviceUrl, setServiceUrl] = useState(PROMETHEUX_CONFIG.BASE_URL);

  useEffect(() => {
    // Load from localStorage first, then fall back to config
    const savedUrl =
      localStorage.getItem(LOCAL_STORAGE_SERVICE_URL_KEY) || PROMETHEUX_CONFIG.BASE_URL;
    setServiceUrl(savedUrl);
  }, []);

  const handleServiceUrlSave = () => {
    if (serviceUrl.trim()) {
      PROMETHEUX_CONFIG.BASE_URL = serviceUrl.trim();
      // Save to localStorage for persistence and to mark as manually overridden
      localStorage.setItem(LOCAL_STORAGE_SERVICE_URL_KEY, serviceUrl.trim());
      toast.success("Service URL updated successfully. Reloading page...");

      // Reload the page after a short delay to apply changes
      setTimeout(() => {
        window.location.reload();
      }, 1000);
    } else {
      toast.error("Please enter a valid service URL");
    }
  };

  const handleReset = () => {
    const defaultUrl = getDefaultBaseUrl();
    setServiceUrl(defaultUrl);
    PROMETHEUX_CONFIG.BASE_URL = defaultUrl;
    localStorage.removeItem(LOCAL_STORAGE_SERVICE_URL_KEY);
    toast.success("Service URL reset to default. Reloading page...");

    setTimeout(() => {
      window.location.reload();
    }, 1000);
  };

  return (
    <SettingsSection
      title="Prometheux Service URL"
      description="Configure the URL for the Prometheux service"
    >
      <div className="flex gap-4">
        <Input
          id="service-url"
          value={serviceUrl}
          onChange={(e) => setServiceUrl(e.target.value)}
          placeholder="Enter service URL"
          className="flex-1"
        />
        <Button onClick={handleServiceUrlSave}>Save</Button>
        <Button variant="outline" onClick={handleReset}>
          Reset
        </Button>
      </div>
    </SettingsSection>
  );
};

export default ServiceUrlSettings;
