/**
 * Marks a concept whose output can change between runs (dynamic context, llm),
 * so it is never served from cache and its results are a snapshot, not a fact.
 */
export function NonDeterministicBadge() {
  return (
    <span
      className="flex-shrink-0 rounded bg-amber-100 px-1.5 py-0.5 text-[10px] font-medium text-amber-700 dark:bg-amber-900/30 dark:text-amber-400"
      title="Output can change between runs — never cached"
    >
      non-deterministic
    </span>
  );
}

interface NoteCountBadgeProps {
  count: number;
}

/** How many notes a static context concept pins. */
export function NoteCountBadge({ count }: NoteCountBadgeProps) {
  return (
    <span className="flex-shrink-0 text-xs text-muted-foreground">
      {count} note{count === 1 ? "" : "s"}
    </span>
  );
}
