export type ContextScope = "global" | "ontology";

export type ContextKind = "preference" | "fact" | "document_chunk" | "observation";

export type ContextSource = "user" | "agent_writer" | "import";

/** How a note reaches the model:
 *  - retrieved: semantic pool, injected only when relevant (default)
 *  - always:    a Rule — injected verbatim into the system prompt each turn
 *  - on_demand: title listed in the prompt, body fetched via tool
 */
export type ContextActivation = "retrieved" | "always" | "on_demand";

export interface ContextNoteSourceMeta {
  document_id?: string;
  filename?: string;
  chunk_index?: number;
  chunk_count?: number;
  [key: string]: unknown;
}

export interface ContextNote {
  id: string;
  scope: ContextScope;
  scope_id: string | null;
  kind: ContextKind;
  text: string;
  source: ContextSource;
  /** Legacy — pinning is retired. Kept only for the one-time "formerly pinned" notice. */
  pinned: boolean;
  created_at: string;
  last_used_at: string | null;
  use_count: number;
  superseded_by: string | null;
  source_meta: ContextNoteSourceMeta | null;
  activation: ContextActivation;
  title: string | null;
  folder_path: string | null;
}

export interface CreateContextNoteRequest {
  scope: ContextScope;
  scope_id?: string | null;
  kind: ContextKind;
  text: string;
  activation?: ContextActivation;
  title?: string | null;
  folder_path?: string | null;
  supersedes?: string[];
}

export interface UpdateContextNoteRequest {
  text?: string;
  kind?: ContextKind;
  activation?: ContextActivation;
  title?: string | null;
  folder_path?: string | null;
  scope?: ContextScope;
  scope_id?: string | null;
}

export interface CreateContextFromFileRequest {
  scope: ContextScope;
  scope_id?: string | null;
  file_path: string;
}

export interface ContextNoteFromFileResponse {
  document_id: string | null;
  filename: string;
  chunk_count: number;
  persisted: number;
  scope: ContextScope;
  scope_id: string | null;
}

export interface ContextNoteFilter {
  scope: ContextScope;
  scopeId?: string | null;
  kinds?: ContextKind[];
  activation?: ContextActivation;
}

// ── Knowledge-graph edges (context_edges) ──────────────────────────────────

export type ContextEdgeNodeType = "note" | "concept" | "ontology" | "datasource";

export type ContextEdgeRelation =
  | "relates_to"
  | "derived_from"
  | "defines"
  | "example_of"
  | "contradicts";

/**
 * Provenance, not annotation: a `derived_from` edge is a projection of what a
 * context concept was built from — its pin list for a static concept, its last
 * retrieval for a dynamic one — rewritten by the backend on every save or run.
 * Never hand-edit these; change the concept instead.
 */
export const PROVENANCE_RELATION: ContextEdgeRelation = "derived_from";

export interface ContextEdge {
  id: string;
  src_type: ContextEdgeNodeType;
  src_id: string;
  dst_type: ContextEdgeNodeType;
  dst_id: string;
  relation: ContextEdgeRelation;
  created_by: string;
  created_at: string | null;
}

export interface CreateContextEdgeRequest {
  src_type: ContextEdgeNodeType;
  src_id: string;
  dst_type: ContextEdgeNodeType;
  dst_id: string;
  relation?: ContextEdgeRelation;
  /** 'wikilink' edges track their text anchor; 'user' edges live independently. */
  created_by?: "user" | "wikilink";
}

// ── Concept / project edge endpoints (phase 4) ─────────────────────────────

/** Reference to a concept as a context-edge endpoint. */
export interface ConceptNodeRef {
  ontologyId: string;
  conceptName: string;
}

/**
 * A concept endpoint id is "<project_id>:<predicate_name>" — project ids
 * (UUIDs) and Vadalog predicate names cannot contain ':', so the split on
 * the first ':' is unambiguous. Mirrors the backend's
 * ContextNoteService.concept_node_id; both sides must build the same key.
 */
export function conceptNodeId(ontologyId: string, conceptName: string): string {
  return `${ontologyId}:${conceptName}`;
}

export function parseConceptNodeId(nodeId: string): ConceptNodeRef | null {
  const separator = nodeId.indexOf(":");
  if (separator <= 0 || separator === nodeId.length - 1) return null;
  return {
    ontologyId: nodeId.slice(0, separator),
    conceptName: nodeId.slice(separator + 1),
  };
}

export const CONTEXT_KIND_LABELS: Record<ContextKind, string> = {
  preference: "Preference",
  fact: "Fact",
  document_chunk: "Document chunk",
  observation: "Observation",
};

export const CONTEXT_ACTIVATION_LABELS: Record<ContextActivation, string> = {
  retrieved: "Retrieved when relevant",
  always: "Always applied (Rule)",
  on_demand: "On demand (title listed)",
};

export const CONTEXT_EDGE_RELATION_LABELS: Record<ContextEdgeRelation, string> = {
  relates_to: "Relates to",
  derived_from: "Derived from",
  defines: "Defines",
  example_of: "Example of",
  contradicts: "Contradicts",
};

/** The three shelves — badges/filters over orthogonal note dimensions, NOT folders.
 *  - rules:     activation != 'retrieved'
 *  - documents: kind = 'document_chunk' (grouped by source_meta.document_id)
 *  - knowledge: everything else the user should see
 */
export type ContextShelf = "rules" | "knowledge" | "documents";

export const CONTEXT_SHELF_LABELS: Record<ContextShelf, string> = {
  rules: "Rules",
  knowledge: "Knowledge",
  documents: "Documents",
};

export function shelfOf(note: Pick<ContextNote, "activation" | "kind">): ContextShelf {
  if (note.activation !== "retrieved") return "rules";
  if (note.kind === "document_chunk") return "documents";
  return "knowledge";
}
