import { Route } from "react-router-dom";
import { RequireAuth } from "@/features/auth/components/RequireAuth";
import { RequirePermission } from "@/features/auth/components/RequirePermission";
import TeamDetailPage from "./TeamDetailPage";
import TeamsPage from "./TeamsPage";

// Teams routes — a separate governance layer from `organization`. Gated by
// can_see_teams (the backend also enforces team membership on every endpoint).
// Exported as an array so <Routes> flattens them in place, keeping this
// feature's routing co-located with the feature rather than in AppRoutes.
export const teamsRoutes = [
  <Route
    key="teams"
    path="/teams"
    element={
      <RequireAuth>
        <RequirePermission permissionKey="can_see_teams">
          <TeamsPage />
        </RequirePermission>
      </RequireAuth>
    }
  />,
  <Route
    key="teams-detail"
    path="/teams/:teamId"
    element={
      <RequireAuth>
        <RequirePermission permissionKey="can_see_teams">
          <TeamDetailPage />
        </RequirePermission>
      </RequireAuth>
    }
  />,
];
