import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

import { useCodeAssistantStore } from "@/features/code-assistant/store";

import { ContextEdgeApi, ContextNoteApi } from "../api";
import { ATTACHED_NOTES_KEY_PREFIX } from "../hooks/useAttachedNotes";
import { deriveTitleFromText, isDerivedTitle } from "../notes/notesModel";
import { executeWikilinkEdgeSync } from "../notes/wikilinks";
import type { ContextEdge, ContextNote } from "../types";
import { conceptNodeId, PROVENANCE_RELATION } from "../types";

export interface UseConceptContextActionsReturn {
  /** Link an existing note to this concept. */
  attachNote: (noteId: string) => Promise<void>;
  /** Remove every note↔concept edge (the note itself survives). */
  detachNote: (noteId: string, conceptEdges: ContextEdge[]) => Promise<void>;
  /** Delete the note entirely — the backend cascades its edges. */
  deleteNote: (noteId: string) => Promise<void>;
  /** Create a project-scoped note and attach it in one gesture. */
  createAndAttach: (text: string, linkCandidates: ContextNote[]) => Promise<ContextNote | null>;
  /** Save edited text (+re-derived title), syncing wikilink-born edges. */
  saveNoteText: (
    note: ContextNote,
    newText: string,
    linkCandidates: ContextNote[],
    existingEdges: ContextEdge[],
  ) => Promise<ContextNote | null>;
}

/**
 * Note/edge writes from the concept Context tab. Every successful mutation
 * bumps the context-notes revision (the agent refreshes its cached context
 * next turn) and invalidates the attached-notes + edges queries.
 */
export function useConceptContextActions(
  ontologyId: string,
  conceptName: string,
): UseConceptContextActionsReturn {
  const queryClient = useQueryClient();
  const bumpContextNotesRevision = useCodeAssistantStore((state) => state.bumpContextNotesRevision);
  const conceptKey = conceptNodeId(ontologyId, conceptName);

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: [ATTACHED_NOTES_KEY_PREFIX] });
    queryClient.invalidateQueries({ queryKey: ["context-edges"] });
    queryClient.invalidateQueries({ queryKey: ["context-notes"] });
    bumpContextNotesRevision();
  };

  const attachNote = async (noteId: string): Promise<void> => {
    try {
      await ContextEdgeApi.create({
        src_type: "note",
        src_id: noteId,
        dst_type: "concept",
        dst_id: conceptKey,
        relation: "relates_to",
      });
      invalidate();
    } catch (error) {
      toast.error(
        `Could not attach note: ${error instanceof Error ? error.message : "unknown error"}`,
      );
    }
  };

  const detachNote = async (noteId: string, conceptEdges: ContextEdge[]): Promise<void> => {
    // Remove every annotation edge between the note and this concept (there can
    // be several — different relations or directions). Provenance edges are left
    // alone: they are a projection the backend rewrites, so deleting one here
    // would change nothing about what the concept returns and would come back on
    // the concept's next save or run.
    const touchesNote = (e: ContextEdge) =>
      (e.src_type === "note" && e.src_id === noteId) ||
      (e.dst_type === "note" && e.dst_id === noteId);
    const edges = conceptEdges.filter((e) => touchesNote(e) && e.relation !== PROVENANCE_RELATION);
    if (edges.length === 0) {
      const isProvenanceOnly = conceptEdges.some(
        (e) => touchesNote(e) && e.relation === PROVENANCE_RELATION,
      );
      if (isProvenanceOnly) {
        toast.info(
          "This note feeds the context concept's output — unpin it in the concept's cell to remove it.",
        );
      }
      return;
    }
    try {
      for (const edge of edges) {
        await ContextEdgeApi.remove(edge.id);
      }
      invalidate();
    } catch (error) {
      toast.error(
        `Could not detach note: ${error instanceof Error ? error.message : "unknown error"}`,
      );
    }
  };

  const deleteNote = async (noteId: string): Promise<void> => {
    try {
      await ContextNoteApi.remove(noteId);
      invalidate();
    } catch (error) {
      toast.error(
        `Could not delete note: ${error instanceof Error ? error.message : "unknown error"}`,
      );
    }
  };

  const syncWikilinks = async (
    note: ContextNote,
    text: string,
    linkCandidates: ContextNote[],
    existingEdges: ContextEdge[],
  ): Promise<void> => {
    // The executor never rejects — the note save already succeeded, so a
    // failed edge write must not fail the whole action. Surface failures
    // with a dedicated toast instead.
    const results = await executeWikilinkEdgeSync(
      note.id,
      text,
      linkCandidates,
      existingEdges,
      ontologyId,
      {
        createEdge: (edge) => ContextEdgeApi.create(edge),
        removeEdge: (edgeId) => ContextEdgeApi.remove(edgeId),
      },
    );
    const failedCount = results.filter((result) => result.status === "rejected").length;
    if (failedCount > 0) {
      toast.error(
        `Note saved, but ${failedCount} wikilink edge${failedCount === 1 ? "" : "s"} could not be updated`,
      );
    }
  };

  const createAndAttach = async (
    text: string,
    linkCandidates: ContextNote[],
  ): Promise<ContextNote | null> => {
    try {
      const note = await ContextNoteApi.create({
        scope: "ontology",
        scope_id: ontologyId,
        kind: "fact",
        text,
        title: deriveTitleFromText(text),
      });
      await ContextEdgeApi.create({
        src_type: "note",
        src_id: note.id,
        dst_type: "concept",
        dst_id: conceptKey,
        relation: "relates_to",
      });
      await syncWikilinks(note, text, linkCandidates, []);
      invalidate();
      return note;
    } catch (error) {
      toast.error(
        `Could not create note: ${error instanceof Error ? error.message : "unknown error"}`,
      );
      return null;
    }
  };

  const saveNoteText = async (
    note: ContextNote,
    newText: string,
    linkCandidates: ContextNote[],
    existingEdges: ContextEdge[],
  ): Promise<ContextNote | null> => {
    try {
      const updated = await ContextNoteApi.update(
        note.id,
        // Only an auto-derived title is refreshed from the new text; an
        // author-chosen one must survive body edits.
        isDerivedTitle(note)
          ? { text: newText, title: deriveTitleFromText(newText) }
          : { text: newText },
      );
      await syncWikilinks(note, newText, linkCandidates, existingEdges);
      invalidate();
      return updated;
    } catch (error) {
      toast.error(
        `Could not save note: ${error instanceof Error ? error.message : "unknown error"}`,
      );
      return null;
    }
  };

  return { attachNote, detachNote, deleteNote, createAndAttach, saveNoteText };
}
