import type React from "react";

interface PrometheuxSpinnerProps {
  size?: number;
  label?: string;
  className?: string;
}

export const PrometheuxSpinner: React.FC<PrometheuxSpinnerProps> = ({
  size = 48,
  label,
  className = "",
}) => {
  const outerDots = Array.from({ length: 8 }, (_, i) => {
    const rad = ((i * 45 - 90) * Math.PI) / 180;
    return { cx: 50 + 39 * Math.cos(rad), cy: 50 + 39 * Math.sin(rad) };
  });

  const innerDots = Array.from({ length: 4 }, (_, i) => {
    const rad = ((i * 90 - 67.5) * Math.PI) / 180;
    return { cx: 50 + 24 * Math.cos(rad), cy: 50 + 24 * Math.sin(rad) };
  });

  const svg = (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ flexShrink: 0 }}>
      <style>{`
        @keyframes pmx-spin-outer {
          to { transform: rotate(360deg); }
        }
        @keyframes pmx-spin-inner {
          to { transform: rotate(360deg); }
        }
        .pmx-outer {
          transform-origin: 50px 50px;
          animation: pmx-spin-outer 1.6s linear infinite;
        }
        .pmx-inner {
          transform-origin: 50px 50px;
          animation: pmx-spin-inner 4s linear infinite;
        }
      `}</style>
      <g className="pmx-outer">
        {outerDots.map((d, i) => (
          <circle key={i} cx={d.cx} cy={d.cy} r={7} fill="currentColor" />
        ))}
      </g>
      <g className="pmx-inner">
        {innerDots.map((d, i) => (
          <circle key={i} cx={d.cx} cy={d.cy} r={7} fill="currentColor" />
        ))}
      </g>
    </svg>
  );

  if (label) {
    return (
      <div className={`inline-flex items-center gap-3 ${className}`}>
        {svg}
        <span className="text-sm text-foreground">{label}</span>
      </div>
    );
  }

  return (
    <div style={{ width: size, height: size }} className={className}>
      {svg}
    </div>
  );
};

interface GeometricLoaderProps {
  size?: number;
  color?: string;
  className?: string;
}

// Animated Tetrahedron (4-sided pyramid)
export const TetrahedronLoader: React.FC<GeometricLoaderProps> = ({
  size = 48,
  color = "#29CC7A",
  className = "",
}) => {
  return (
    <div className={`relative ${className}`} style={{ width: size, height: size }}>
      <svg
        width={size}
        height={size}
        viewBox="0 0 100 100"
        className="animate-spin"
        style={{ animationDuration: "3s" }}
      >
        <defs>
          <style>
            {`
              .tetrahedron-face {
                fill: none;
                stroke: ${color};
                stroke-width: 2;
                stroke-linejoin: round;
                opacity: 0.8;
              }
              .tetrahedron-edge {
                stroke: ${color};
                stroke-width: 1.5;
                opacity: 0.6;
              }
            `}
          </style>
        </defs>

        {/* Tetrahedron faces */}
        <polygon points="50,15 25,70 75,70" className="tetrahedron-face" />
        <polygon points="50,15 75,70 62.5,45" className="tetrahedron-face" />
        <polygon points="50,15 25,70 37.5,45" className="tetrahedron-face" />
        <polygon points="25,70 75,70 50,85" className="tetrahedron-face" />

        {/* Internal edges for 3D effect */}
        <line x1="50" y1="15" x2="50" y2="85" className="tetrahedron-edge" />
        <line x1="37.5" y1="45" x2="62.5" y2="45" className="tetrahedron-edge" />
      </svg>
    </div>
  );
};

