// Combined loader with multiple shapes
export const GeometricLoader: React.FC<{
  variant?:
    | "tetrahedron"
    | "cube"
    | "octahedron"
    | "dodecahedron"
    | "combined"
    | "quad"
    | "vertical";
  size?: number;
  color?: string;
  className?: string;
}> = ({ variant = "combined", size = 48, color, className = "" }) => {
  if (variant === "tetrahedron") {
    return <TetrahedronLoader size={size} color={color || "#29CC7A"} className={className} />;
  }

  if (variant === "cube") {
    return <CubeLoader size={size} color={color || "#3B82F6"} className={className} />;
  }

  if (variant === "octahedron") {
    return <OctahedronLoader size={size} color={color || "#10B981"} className={className} />;
  }

  if (variant === "dodecahedron") {
    return <DodecahedronLoader size={size} color={color || "#8B5CF6"} className={className} />;
  }

  if (variant === "quad") {
    // Four shapes arranged in a larger formation
    const shapeSize = size * 0.4;
    const _spacing = size * 0.3;

    return (
      <div className={`relative ${className}`} style={{ width: size * 1.5, height: size * 1.5 }}>
        {/* Top Left - Tetrahedron */}
        <div
          className="absolute"
          style={{
            top: 0,
            left: 0,
            transform: "translate(0, 0)",
          }}
        >
          <TetrahedronLoader size={shapeSize} color="#29CC7A" />
        </div>

        {/* Top Right - Cube */}
        <div
          className="absolute"
          style={{
            top: 0,
            right: 0,
            transform: "translate(0, 0)",
          }}
        >
          <CubeLoader size={shapeSize} color="#3B82F6" />
        </div>

        {/* Bottom Left - Octahedron */}
        <div
          className="absolute"
          style={{
            bottom: 0,
            left: 0,
            transform: "translate(0, 0)",
          }}
        >
          <OctahedronLoader size={shapeSize} color="#10B981" />
        </div>

        {/* Bottom Right - Dodecahedron */}
        <div
          className="absolute"
          style={{
            bottom: 0,
            right: 0,
            transform: "translate(0, 0)",
          }}
        >
          <DodecahedronLoader size={shapeSize} color="#8B5CF6" />
        </div>
      </div>
    );
  }

  if (variant === "vertical") {
    // Return just the shapes for vertical layout - text will be inserted between them
    const shapeSize = size * 0.6; // Bigger individual shapes

    return {
      topShapes: (
        <div className="flex justify-center gap-8 mb-6">
          <TetrahedronLoader size={shapeSize} color="#29CC7A" />
          <CubeLoader size={shapeSize} color="#3B82F6" />
        </div>
      ),
      bottomShapes: (
        <div className="flex justify-center gap-8 mt-6">
          <OctahedronLoader size={shapeSize} color="#10B981" />
          <DodecahedronLoader size={shapeSize} color="#8B5CF6" />
        </div>
      ),
    } as any;
  }

  // Combined variant with all shapes overlapping (original behavior)
  return (
    <div className={`relative flex items-center justify-center ${className}`}>
      <div className="absolute">
        <TetrahedronLoader size={size * 0.7} color="#29CC7A" />
      </div>
      <div className="absolute" style={{ transform: "rotate(120deg)" }}>
        <CubeLoader size={size * 0.8} color="#3B82F6" />
      </div>
      <div className="absolute" style={{ transform: "rotate(240deg)" }}>
        <OctahedronLoader size={size * 0.6} color="#10B981" />
      </div>
      <div className="absolute" style={{ transform: "rotate(60deg)" }}>
        <DodecahedronLoader size={size * 0.5} color="#8B5CF6" />
      </div>
    </div>
  );
};

// Loading text component to pair with geometric loaders
export const LoadingText: React.FC<{
  primary: string;
  secondary?: string;
  className?: string;
}> = ({ primary, secondary, className = "" }) => {
  return (
    <div className={`text-center space-y-2 ${className}`}>
      <p className="text-base font-medium text-gray-800 animate-pulse">{primary}</p>
      {secondary && <p className="text-xs text-gray-500">{secondary}</p>}
    </div>
  );
};

// Animated logo component
