import { Plus, Trash2 } from "lucide-react";
import { Input } from "@/shared/components/ui/input";
import type { OutputTap } from "../../../schema/appDefinition.types";
import { TAPS_HELP } from "../editorHelp";
import { InfoHint } from "../InfoHint";
import { TokenCombobox } from "./TokenSelect";

interface TapListEditorProps {
  taps: OutputTap[];
  onChange: (taps: OutputTap[]) => void;
  conceptNames: string[];
  conceptsLoading: boolean;
}

/** Output taps: tap id → concept, the contract widgets bind against. */
export function TapListEditor({
  taps,
  onChange,
  conceptNames,
  conceptsLoading,
}: TapListEditorProps) {
  const updateTap = (index: number, patch: Partial<OutputTap>) => {
    onChange(taps.map((tap, i) => (i === index ? { ...tap, ...patch } : tap)));
  };

  const pickConcept = (index: number, concept: string) => {
    const tap = taps[index];
    // Default the widget-facing handle to the concept name until the author renames it.
    updateTap(index, { concept, id: tap.id || concept });
  };

  return (
    <div className="flex flex-col gap-1">
      <span className="flex items-center gap-1 text-[10px] font-medium text-muted-foreground">
        Output taps (tap id → concept)
        <InfoHint text={TAPS_HELP} />
      </span>
      {taps.map((tap, index) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: rows are positional while being edited
        <div key={index} className="flex items-center gap-1">
          <Input
            value={tap.id}
            placeholder="tap id"
            onChange={(event) => updateTap(index, { id: event.target.value })}
            className="h-6 text-[11px] font-mono flex-1 min-w-0"
          />
          <span className="text-muted-foreground/50 text-[10px] flex-shrink-0">→</span>
          <TokenCombobox
            value={tap.concept || undefined}
            onChange={(concept) => concept && pickConcept(index, concept)}
            options={conceptNames}
            loading={conceptsLoading}
            noun="concepts"
            placeholder="concept"
            className="flex-1 min-w-0"
          />
          <button
            type="button"
            title="Remove tap"
            onClick={() => onChange(taps.filter((_, i) => i !== index))}
            className="p-0.5 text-muted-foreground hover:text-destructive flex-shrink-0"
          >
            <Trash2 className="h-3 w-3" />
          </button>
        </div>
      ))}
      <button
        type="button"
        onClick={() => onChange([...taps, { id: "", concept: "" }])}
        className="flex items-center gap-1 py-0.5 text-[10px] text-muted-foreground hover:text-foreground self-start"
      >
        <Plus className="h-2.5 w-2.5" />
        Add tap
      </button>
    </div>
  );
}
