import { ChevronLeft, ChevronRight, X } from "lucide-react";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import type { ConceptDataPreviewStatus } from "../../hooks/useConceptDataPreview";
import type { ConceptGraphPagination } from "../../types";
import { GraphResultTable } from "./GraphResultTable";

interface ConceptDataTableViewProps {
  predicate: string;
  status: ConceptDataPreviewStatus;
  error: string | null;
  columns: string[];
  rows: unknown[][];
  pagination: ConceptGraphPagination | null;
  onPageChange: (page: number) => void;
  onClose: () => void;
}

export function ConceptDataTableView({
  predicate,
  status,
  error,
  columns,
  rows,
  pagination,
  onPageChange,
  onClose,
}: ConceptDataTableViewProps) {
  const renderBody = () => {
    if (status === "loading") {
      return (
        <div className="flex-1 flex items-center justify-center">
          <PrometheuxSpinner />
        </div>
      );
    }
    if (status === "error") {
      return (
        <div className="flex-1 flex items-center justify-center px-6">
          <p className="text-xs text-destructive text-center">{error}</p>
        </div>
      );
    }
    if (rows.length === 0) {
      return (
        <div className="flex-1 flex items-center justify-center">
          <p className="text-xs text-muted-foreground">This concept has no materialized results.</p>
        </div>
      );
    }
    return <GraphResultTable columns={columns} rows={rows} />;
  };

  return (
    <div className="flex-1 flex flex-col min-h-0 min-w-0">
      <div className="h-10 flex items-center gap-2 px-3 border-b border-border flex-shrink-0">
        <Badge variant="secondary" className="text-[10px]">
          Data preview
        </Badge>
        <span className="text-xs font-medium text-foreground truncate">{predicate}</span>
        <span className="text-[11px] text-muted-foreground truncate">
          Assign a source and a target column to see it as a graph
        </span>

        <div className="ml-auto flex items-center gap-1.5">
          {pagination && pagination.total_pages > 1 && (
            <>
              <Button
                variant="outline"
                size="icon"
                className="h-6 w-6"
                disabled={!pagination.has_prev || status !== "ready"}
                onClick={() => onPageChange(pagination.page - 1)}
                title="Previous page"
              >
                <ChevronLeft className="h-3.5 w-3.5" />
              </Button>
              <span className="text-[11px] text-muted-foreground whitespace-nowrap">
                {pagination.page} / {pagination.total_pages}
              </span>
              <Button
                variant="outline"
                size="icon"
                className="h-6 w-6"
                disabled={!pagination.has_next || status !== "ready"}
                onClick={() => onPageChange(pagination.page + 1)}
                title="Next page"
              >
                <ChevronRight className="h-3.5 w-3.5" />
              </Button>
            </>
          )}
          <Button variant="ghost" size="icon" className="h-6 w-6" onClick={onClose} title="Close">
            <X className="h-3.5 w-3.5" />
          </Button>
        </div>
      </div>
      {renderBody()}
    </div>
  );
}
