import type React from "react";
import { cn } from "@/shared/lib/utils";

const KEYBOARD_STEP = 0.05;

interface SplitDragHandleProps {
  onMouseDown: (event: React.MouseEvent<HTMLDivElement>) => void;
  /** Adjust the ratio by the given delta. Called from arrow-key handlers. */
  onAdjust: (deltaRatio: number) => void;
  /** Current editor share, expressed as a percentage 0-100. Reported via aria-valuenow. */
  editorPercent: number;
  className?: string;
}

/**
 * Horizontal drag bar used to resize the editor/bottom-panel split in
 * Explorer view. The visible row is 6px tall, with a hover/active accent so
 * the affordance is discoverable without dominating the layout. Focusable,
 * with arrow keys nudging the split by 5% and Home/End jumping to extremes.
 */
export function SplitDragHandle({
  onMouseDown,
  onAdjust,
  editorPercent,
  className,
}: SplitDragHandleProps) {
  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "ArrowUp") {
      event.preventDefault();
      onAdjust(-KEYBOARD_STEP);
      return;
    }
    if (event.key === "ArrowDown") {
      event.preventDefault();
      onAdjust(KEYBOARD_STEP);
      return;
    }
    if (event.key === "Home") {
      event.preventDefault();
      onAdjust(-1);
      return;
    }
    if (event.key === "End") {
      event.preventDefault();
      onAdjust(1);
    }
  };

  return (
    /* biome-ignore lint/a11y/useSemanticElements: <hr> can't host the onMouseDown/onKeyDown handlers a resize bar needs; div + role="separator" is the WAI-ARIA pattern for an interactive split bar. */
    <div
      role="separator"
      aria-orientation="horizontal"
      aria-valuenow={Math.round(editorPercent)}
      aria-valuemin={0}
      aria-valuemax={100}
      tabIndex={0}
      onMouseDown={onMouseDown}
      onKeyDown={handleKeyDown}
      className={cn(
        "group relative h-1.5 cursor-row-resize select-none outline-none",
        "before:absolute before:inset-x-0 before:top-1/2 before:h-px before:-translate-y-1/2",
        "before:bg-border before:transition-colors",
        "hover:before:bg-primary/40 active:before:bg-primary/60",
        "focus-visible:before:bg-primary/60",
        className,
      )}
    />
  );
}
