import { Label } from "@/shared/components/ui/label";
import { ScalarFieldControl } from "../../../forms/fields/ScalarFieldControl";
import { useTabContext } from "../../../runtime/tabContext";
import type { AppInputDef } from "../../../schema/appDefinition.types";

interface InputRefWidgetProps {
  input: AppInputDef;
  ontologyId: string;
}

/** A scalar input placed in the layout, bound straight to the tab context. */
export function InputRefWidget({ input, ontologyId }: InputRefWidgetProps) {
  const { values, setValue } = useTabContext();
  const { type } = input;

  if (type === "form") return null;

  return (
    <div className="flex flex-col gap-1.5">
      <Label className="text-[11px] font-medium text-foreground/70">
        {input.label ?? input.id}
        {input.required && <span className="text-destructive ml-0.5">*</span>}
      </Label>
      <ScalarFieldControl
        field={{ ...input, type }}
        value={values[input.id]}
        onChange={(value) => setValue(input.id, value)}
        ontologyId={ontologyId}
      />
    </div>
  );
}
