import { Database, FolderOpen, HardDrive, type LucideIcon, Network, Server } from "lucide-react";
import {
  siClickhouse,
  siDatabricks,
  siGooglecloud,
  siMariadb,
  siMongodb,
  siNeo4j,
  siPython,
  siRedis,
  siSnowflake,
  siSqlite,
} from "simple-icons";

/**
 * Single source of truth for database / storage / brand icons.
 *
 * Rendered by `DatabaseIcon` in the datasources Sources tab and the lineage graph.
 * File types are NOT here — those live in `fileTypeIconMap.ts`; `DatabaseIcon` tries
 * the file map first and only falls back to this one.
 *
 * These render three ways (brand SVG / image asset / Lucide glyph). Brand and Lucide
 * icons are monochromatic and theme-driven: they paint with `currentColor` set by the
 * `colorClass` below, so they adapt to light/dark. Image-asset logos keep their own
 * colors (an `<img>` can't be recolored via CSS) until they're replaced.
 *
 * Keys are lowercase; aliases (e.g. "postgres" → "postgresql") are listed explicitly.
 */

/** Minimal shape we use from a simple-icons icon object (recolored via currentColor). */
export interface BrandIconData {
  title: string;
  path: string;
}

export type DatabaseIconSpec =
  | { kind: "brand"; icon: BrandIconData; colorClass: string }
  | { kind: "image"; src: string; alt: string }
  | { kind: "mask"; src: string; alt: string; colorClass: string }
  | { kind: "lucide"; Icon: LucideIcon; colorClass: string };

// Theme-aware color for monochromatic icons. Adapts: near-black (light) / near-white (dark).
const THEME_ICON_COLOR = "text-foreground";

// Brand colors: a deeper shade for light mode, a brighter one for dark mode so the icon
// stays legible on the dark background. The many blue brands are kept on slightly distinct
// hues/shades (sky / blue / cyan / teal / indigo) so they don't all look identical.
const POSTGRES_BLUE = "text-sky-700 dark:text-sky-400";
const MYSQL_TEAL = "text-cyan-700 dark:text-cyan-400";
const ORACLE_RED = "text-red-600 dark:text-red-400";
const AWS_ORANGE = "text-orange-500 dark:text-orange-400";
const AZURE_BLUE = "text-blue-600 dark:text-blue-400";
const MONGODB_GREEN = "text-green-600 dark:text-green-400";
const MARIADB_TEAL = "text-teal-700 dark:text-teal-400";
const SQLITE_INDIGO = "text-indigo-600 dark:text-indigo-400";
const REDIS_RED = "text-red-600 dark:text-red-400";
const DATABRICKS_ORANGE = "text-orange-600 dark:text-orange-400";
const GOOGLE_BLUE = "text-blue-500 dark:text-blue-300";
const SNOWFLAKE_BLUE = "text-sky-500 dark:text-sky-300";
const PYTHON_BLUE = "text-blue-700 dark:text-blue-400";
const NEO4J_BLUE = "text-sky-600 dark:text-sky-400";
// ClickHouse's signature yellow — legible on both light and dark backgrounds
// (a deeper amber in light mode, the brand yellow in dark mode).
const CLICKHOUSE_YELLOW = "text-amber-500 dark:text-yellow-400";
// Colors for the Lucide-glyph entries (restoring their pre-consolidation accents).
const SQLSERVER_RED = "text-red-700 dark:text-red-400";
const SYBASE_RED = "text-red-500 dark:text-red-400";
const H2_INDIGO = "text-indigo-500 dark:text-indigo-400";
const PRESTO_EMERALD = "text-emerald-600 dark:text-emerald-400";
const HDFS_ORANGE = "text-orange-500 dark:text-orange-400";
const LOCAL_AMBER = "text-amber-500 dark:text-amber-400";
const API_BLUE = "text-blue-500 dark:text-blue-400";

const brand = (icon: BrandIconData, colorClass: string = THEME_ICON_COLOR): DatabaseIconSpec => ({
  kind: "brand",
  icon,
  colorClass,
});
// Full-color logo loaded as <img> — keeps its own colors (can't be recolored via CSS).
const image = (src: string, alt: string): DatabaseIconSpec => ({ kind: "image", src, alt });
// Single-color SVG painted with currentColor via a CSS mask. `colorClass` sets the
// light/dark color; defaults to the neutral theme color (B&W) when no brand color is given.
const mask = (
  src: string,
  alt: string,
  colorClass: string = THEME_ICON_COLOR,
): DatabaseIconSpec => ({
  kind: "mask",
  src,
  alt,
  colorClass,
});
const lucide = (Icon: LucideIcon, colorClass: string = THEME_ICON_COLOR): DatabaseIconSpec => ({
  kind: "lucide",
  Icon,
  colorClass,
});

/** Fallback for unknown database / storage / brand types (subtly de-emphasized). */
export const DEFAULT_DATABASE_ICON: DatabaseIconSpec = {
  kind: "lucide",
  Icon: Database,
  colorClass: "text-muted-foreground",
};

