import { Database, FolderOpen, List, Plus, RefreshCw } from "lucide-react";
import { useCallback, useRef, useState } from "react";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import ComputeIndicator from "@/features/compute/components/ComputeIndicator";
import DataTab, { type DataTabActions } from "@/features/data-sources/components/DataTab";
import { FileBrowserTab } from "@/features/data-sources/components/file-browser/FileBrowserTab";
import { GlobalSearchTrigger } from "@/features/global-search/components/GlobalSearchTrigger";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import SidePanel from "@/shared/components/layout/SidePanel";
import { Button } from "@/shared/components/ui/button";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";

type ActiveTab = "sources" | "files";

const TAB_ITEMS: Array<{ id: ActiveTab; label: string; icon: typeof List }> = [
  { id: "sources", label: "Sources", icon: List },
  { id: "files", label: "Files", icon: FolderOpen },
];

const DataSources = () => {
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [activeTab, setActiveTab] = useState<ActiveTab>("sources");

  const dataTabActionsRef = useRef<DataTabActions | null>(null);
  const [dataSourceCount, setDataSourceCount] = useState<number | null>(null);
  const canEditDatasources = usePermissionsStore((state) => state.canEdit("can_edit_datasources"));

  const marginClass = sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0";

  const handleSchemaInference = (vadalogProgram: string) => {
    sessionStorage.setItem("pendingInferredSchema", vadalogProgram);
  };

  const handleSourcesChanged = useCallback(() => {
    dataTabActionsRef.current?.refresh();
  }, []);

  const sourcesHeaderActions = (
    <>
      <ComputeIndicator interactive={true} />
      <Button
        variant="outline"
        size="icon"
        onClick={() => dataTabActionsRef.current?.refresh()}
        title="Refresh data sources"
      >
        <RefreshCw className="h-4 w-4" />
      </Button>
      {canEditDatasources && (
        <Button
          className="gap-2 text-xs font-semibold uppercase tracking-wide"
          onClick={() => dataTabActionsRef.current?.addDataSource()}
        >
          <Plus className="h-4 w-4" />
          Add Data Source
        </Button>
      )}
    </>
  );

  const filesHeaderActions = <ComputeIndicator interactive={true} />;

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="data"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-col flex-1 ${marginClass} overflow-hidden transition-all duration-200`}
      >
        <PageHeader
          title="Data"
          icon={Database}
          subtitle={
            activeTab === "sources" && dataSourceCount !== null
              ? `${dataSourceCount} data source${dataSourceCount !== 1 ? "s" : ""}`
              : undefined
          }
          actions={
            <>
              <GlobalSearchTrigger />
              {activeTab === "sources" ? sourcesHeaderActions : filesHeaderActions}
            </>
          }
        />

        {/* Tab bar */}
        <div className="flex border-b border-border px-6">
          {TAB_ITEMS.map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              type="button"
              onClick={() => setActiveTab(id)}
              className={`flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium transition-colors ${
                activeTab === id
                  ? "border-b-2 border-primary text-primary"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              <Icon className="h-4 w-4" />
              {label}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto min-h-0">
          {activeTab === "sources" ? (
            <DataTab
              onToggleSidebar={toggleSidebar}
              sidebarVisible={sidebarVisible}
              actionsRef={dataTabActionsRef}
              onCountChange={setDataSourceCount}
              onSchemaInference={handleSchemaInference}
            />
          ) : (
            <FileBrowserTab onSourcesChanged={handleSourcesChanged} />
          )}
        </div>
      </div>
    </div>
  );
};

export default DataSources;
