import { FileText, Network, NotebookText } from "lucide-react";
import type { ElementType } from "react";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { cn } from "@/shared/lib/utils";

// "ontology" is retained in the union for backward compatibility with older
// navigation state / links, but it is no longer a visible top-level tab: the
// former Lineage view is now surfaced as "Lineage", and the ontology-schema graph
// editor moved into the Document view. Any incoming "ontology" tab is coerced
// to "lineage" by the editor page.
export type OntologyTab = "ontology" | "lineage" | "document" | "context" | "app";

interface OntologyTabDef {
  id: OntologyTab;
  label: string;
  icon: ElementType;
  /** Permission required to show this tab; omitted = always visible. */
  permissionKey?: string;
}

export const PROJECT_TABS: OntologyTabDef[] = [
  { id: "lineage", label: "Lineage", icon: Network },
  { id: "document", label: "Document", icon: FileText },
  { id: "context", label: "Context", icon: NotebookText, permissionKey: "can_see_ai_agent" },
];

interface OntologyTabNavProps {
  activeTab: string;
  onTabChange: (tab: OntologyTab) => void;
  /** "bar" renders a horizontal switcher for the header; "menu" renders a full-width vertical list for the overflow popover. */
  variant: "bar" | "menu";
}

export function OntologyTabNav({ activeTab, onTabChange, variant }: OntologyTabNavProps) {
  const isMenu = variant === "menu";
  const containerClass = isMenu ? "flex flex-col gap-0.5" : "flex shrink-0 items-center gap-0.5";
  const canSee = usePermissionsStore((state) => state.canSee);
  const visibleTabs = PROJECT_TABS.filter((tab) => !tab.permissionKey || canSee(tab.permissionKey));

  return (
    <div className={containerClass}>
      {visibleTabs.map(({ id, label, icon: Icon }) => {
        const isActive = activeTab === id;
        return (
          <button
            key={id}
            type="button"
            onClick={() => onTabChange(id)}
            className={cn(
              "flex items-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition-colors",
              isMenu && "w-full",
              isActive
                ? "bg-primary/10 text-primary"
                : "text-muted-foreground hover:bg-accent hover:text-accent-foreground",
            )}
          >
            <Icon className="h-3.5 w-3.5" />
            {label}
          </button>
        );
      })}
    </div>
  );
}
