import type React from "react";
import { useState } from "react";
import { toast } from "sonner";
import { type OntologyScope, OntologyService } from "@/features/ontologies/api";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

interface DeleteOntologyDialogProps {
  ontologyId: string;
  ontologyName: string;
  ontologyScope?: OntologyScope;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDeleteSuccess: () => void;
}

const DeleteOntologyDialog: React.FC<DeleteOntologyDialogProps> = ({
  ontologyId,
  ontologyName,
  ontologyScope = "user",
  open,
  onOpenChange,
  onDeleteSuccess,
}) => {
  const [isDeleting, setIsDeleting] = useState(false);

  const handleDelete = async () => {
    try {
      setIsDeleting(true);
      const success = await OntologyService.deleteOntology(ontologyId, ontologyScope);

      if (success) {
        // Call the success callback to trigger refresh
        onDeleteSuccess();

        // toast.success(`Project "${projectName}" deleted successfully`);
      } else {
        console.error(`Failed to delete ontology ${ontologyName}`);
        toast.error(`Failed to delete ontology "${ontologyName}"`);
      }
    } catch (error) {
      console.error("Error deleting ontology:", error);
      toast.error("An unexpected error occurred while deleting the ontology");
    } finally {
      setIsDeleting(false);
      onOpenChange(false);
    }
  };

  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Delete the ontology</AlertDialogTitle>
          <AlertDialogDescription>
            Are you sure you want to delete the project? It cannot be undone.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
          <AlertDialogAction
            onClick={(e) => {
              e.preventDefault();
              handleDelete();
            }}
            disabled={isDeleting}
            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
          >
            {isDeleting ? (
              <>
                <PrometheuxSpinner size={16} className="mr-2" />
                Deleting...
              </>
            ) : (
              "Delete"
            )}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
};

export default DeleteOntologyDialog;
