import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { useChatModels } from "../hooks/useChatModels";
import { useCodeAssistantStore } from "../store";

/**
 * Compact in-chat model switcher for the assistant header. Lists models for the
 * user's configured provider and persists the pick via the store; the choice is
 * sent per-message so the backend can switch models mid-session.
 */
export function ChatModelSelect() {
  const { models, isLoading, coveredModels } = useChatModels();
  const selectedModel = useCodeAssistantStore((s) => s.selectedModel);
  const activeModel = useCodeAssistantStore((s) => s.activeModel);
  const setSelectedModel = useCodeAssistantStore((s) => s.setSelectedModel);

  // The dropdown reflects the explicit pick, falling back to whatever model the
  // backend reported for the last turn, then to the user's configured default
  // (so the trigger shows the real model even before the first turn). Any
  // current value not in the fetched list is still shown so it never renders
  // blank — leaving selectedModel null means the request omits `model` and the
  // backend uses the configured default, which is exactly what we display.
  const currentValue = selectedModel ?? activeModel ?? PROMETHEUX_CONFIG.CHAT.MODEL_VERSION ?? "";
  const modelIds = Array.from(new Set([...models, ...(currentValue ? [currentValue] : [])]));
  const options = modelIds.map((model) => ({ model, covered: coveredModels[model] }));

  if (options.length === 0) {
    return null;
  }

  const handleChange = (value: string) => setSelectedModel(value);

  return (
    <Select value={currentValue || undefined} onValueChange={handleChange} disabled={isLoading}>
      <SelectTrigger
        className="h-6 w-auto flex-shrink-0 gap-1 border-none bg-muted px-1.5 py-0.5 font-mono text-[10px] text-muted-foreground focus:ring-0 focus:ring-offset-0"
        title="Model — switch the model for this chat"
        aria-label="Select chat model"
      >
        <SelectValue placeholder="Model" />
      </SelectTrigger>
      <SelectContent>
        {options.map(({ model, covered }) => (
          <SelectItem key={model} value={model} className="font-mono text-xs">
            <span className="flex items-center gap-1.5">
              {model}
              {covered && (
                <span
                  title={covered.note}
                  className="rounded bg-amber-100 px-1 py-0.5 text-[9px] font-medium text-amber-700 dark:bg-amber-900/30 dark:text-amber-400"
                >
                  30d retention
                </span>
              )}
            </span>
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}
