import { ArrowRight, Circle, CirclePlus, Tag, X } from "lucide-react";
import { Badge } from "@/shared/components/ui/badge";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import type { ConceptGraphRole } from "../../types";

interface FieldRolePickerProps {
  role: ConceptGraphRole | null;
  onAssign: (role: ConceptGraphRole) => void;
  onClear: () => void;
}

const ROLE_BADGES: Record<ConceptGraphRole, { label: string; className: string }> = {
  source: {
    label: "source",
    className:
      "bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800",
  },
  target: {
    label: "target",
    className:
      "bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-800",
  },
  edge_label: {
    label: "label",
    className:
      "bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-800",
  },
};

export function FieldRolePicker({ role, onAssign, onClear }: FieldRolePickerProps) {
  const badge = role ? ROLE_BADGES[role] : null;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        {badge ? (
          <Badge
            variant="outline"
            className={`h-4 w-14 justify-center px-1 text-[9px] cursor-pointer flex-shrink-0 ${badge.className}`}
          >
            {badge.label}
          </Badge>
        ) : (
          <button
            type="button"
            title="Assign graph role"
            className="w-14 flex-shrink-0 flex items-center justify-center text-muted-foreground/50 hover:text-foreground transition-colors"
          >
            <CirclePlus className="h-3 w-3" />
          </button>
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-40">
        <DropdownMenuItem className="text-xs gap-2" onClick={() => onAssign("source")}>
          <Circle className="h-3 w-3" />
          Source node
        </DropdownMenuItem>
        <DropdownMenuItem className="text-xs gap-2" onClick={() => onAssign("target")}>
          <ArrowRight className="h-3 w-3" />
          Target node
        </DropdownMenuItem>
        <DropdownMenuItem className="text-xs gap-2" onClick={() => onAssign("edge_label")}>
          <Tag className="h-3 w-3" />
          Edge label
        </DropdownMenuItem>
        {role && (
          <DropdownMenuItem className="text-xs gap-2 text-destructive" onClick={onClear}>
            <X className="h-3 w-3" />
            Clear role
          </DropdownMenuItem>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
