import { useCallback, useMemo, useState } from "react";
import { toast } from "sonner";

import { DataClient } from "@/features/data-sources/api/DataClient";

import type { AttachmentKind, MessageAttachment } from "../attachments.types";
import { attachmentKind } from "../attachments.utils";
import { useCodeAssistantStore } from "../store";

export interface PendingAttachment {
  id: string;
  fileName: string;
  fileSize: number;
  kind: AttachmentKind;
  /** Object URL for an image preview; revoked when the chip is removed. */
  previewUrl?: string;
  /** Server path returned by /data/files/upload; null while the upload is in flight. */
  filePath: string | null;
  isUploading: boolean;
  error?: string;
}

interface UseChatAttachmentsReturn {
  attachments: PendingAttachment[];
  attach: (file: File) => Promise<void>;
  remove: (id: string) => void;
  clear: () => void;
  /** Paths to send to the agent. Only completed (non-error) uploads. */
  readyPaths: string[];
  /** Display metadata for the same uploads, to pin onto the sent message. */
  readyAttachments: MessageAttachment[];
  isUploading: boolean;
}

// 50 MB — larger than the 25 MB cap we had on the Documents tab, since
// the same upload pipeline is used for everything in disk/ today.
const MAX_BYTES = 50 * 1024 * 1024;

export function useChatAttachments(): UseChatAttachmentsReturn {
  const [attachments, setAttachments] = useState<PendingAttachment[]>([]);
  const sessionId = useCodeAssistantStore((s) => s.sessionId);
  const dataClient = useMemo(() => new DataClient(), []);

  const attach = useCallback(
    async (file: File) => {
      if (file.size > MAX_BYTES) {
        const mb = (file.size / 1024 / 1024).toFixed(1);
        toast.error(`File too large: ${mb} MB (limit 50 MB)`);
        return;
      }
      const id = crypto.randomUUID();
      const kind = attachmentKind(file.name, file.type);
      setAttachments((prev) => [
        ...prev,
        {
          id,
          fileName: file.name,
          fileSize: file.size,
          kind,
          previewUrl: kind === "image" ? URL.createObjectURL(file) : undefined,
          filePath: null,
          isUploading: true,
        },
      ]);
      try {
        // Sending the chat rather than a path leaves the storage layout to the
        // backend, which owns these files: it puts them in a directory per
        // conversation so deleting the chat deletes them, and expires the ones
        // nobody comes back to.
        const result = await dataClient.uploadChatAttachment(file, sessionId);
        setAttachments((prev) =>
          prev.map((a) =>
            a.id === id
              ? {
                  ...a,
                  filePath: result.filePath,
                  isUploading: false,
                }
              : a,
          ),
        );
      } catch (err) {
        const message = err instanceof Error ? err.message : "Upload failed";
        setAttachments((prev) =>
          prev.map((a) => (a.id === id ? { ...a, isUploading: false, error: message } : a)),
        );
        toast.error(`Could not attach "${file.name}": ${message}`);
      }
    },
    [dataClient, sessionId],
  );

  const remove = useCallback((id: string) => {
    setAttachments((prev) => {
      const dropped = prev.find((a) => a.id === id);
      if (dropped?.previewUrl) URL.revokeObjectURL(dropped.previewUrl);
      return prev.filter((a) => a.id !== id);
    });
  }, []);

  // Sent attachments keep their preview URL alive: the chip moves onto the
  // message bubble, which renders the thumbnail for the rest of the session.
  const clear = useCallback(() => setAttachments([]), []);

  const ready = useMemo(
    () => attachments.filter((a) => a.filePath && !a.isUploading && !a.error),
    [attachments],
  );

  const readyPaths = useMemo(() => ready.map((a) => a.filePath ?? ""), [ready]);

  const readyAttachments = useMemo(
    () =>
      ready.map(
        (a): MessageAttachment => ({
          name: a.fileName,
          kind: a.kind,
          previewUrl: a.previewUrl,
          path: a.filePath ?? undefined,
        }),
      ),
    [ready],
  );

  const isUploading = attachments.some((a) => a.isUploading);

  return { attachments, attach, remove, clear, readyPaths, readyAttachments, isUploading };
}
