import { useQuery } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import { type OntologyScope, OntologyService } from "@/features/ontologies/api";
import { extractUrlParams } from "@/shared/utils/navigationUtils";

/**
 * Hook to extract project ID from URL or sessionStorage
 * Updated to support new URL format with username and organization
 */
export const useOntologyId = () => {
  const location = useLocation();

  const [ontologyId, setOntologyId] = useState<string | null>(() => {
    // First try to extract from current URL
    const urlParams = extractUrlParams(location.pathname);
    if (urlParams.ontologyId) {
      return urlParams.ontologyId;
    }

    // Initialize with current value from sessionStorage
    const storedOntologyId = sessionStorage.getItem("currentOntologyId");
    if (storedOntologyId) {
      return storedOntologyId;
    }

    // The project ID should come from the URL or sessionStorage

    return null;
  });

  useEffect(() => {
    // Function to update project ID when URL or sessionStorage changes
    const updateOntologyId = () => {
      // First try to extract from URL
      const urlParams = extractUrlParams(location.pathname);
      if (urlParams.ontologyId) {
        setOntologyId(urlParams.ontologyId);
        return;
      }

      // Then try sessionStorage
      const storedOntologyId = sessionStorage.getItem("currentOntologyId");
      if (storedOntologyId) {
        setOntologyId(storedOntologyId);
        return;
      }

      // The project ID should come from the URL or sessionStorage

      setOntologyId(null);
    };

    // Update on URL changes
    updateOntologyId();

    // Listen for storage events (from other tabs/windows)
    window.addEventListener("storage", updateOntologyId);

    // Also listen for custom events when sessionStorage is updated in the same tab
    window.addEventListener("sessionStorageChanged", updateOntologyId);

    // Clean up event listeners
    return () => {
      window.removeEventListener("storage", updateOntologyId);
      window.removeEventListener("sessionStorageChanged", updateOntologyId);
    };
  }, [location.pathname]);

  return ontologyId;
};

/**
 * Hook to extract project scope from sessionStorage or global state
 */
export const useOntologyScope = () => {
  const [ontologyScope, setOntologyScope] = useState<string>(() => {
    if (globalThis.ontology_session?.scope) {
      return globalThis.ontology_session.scope;
    }

    return sessionStorage.getItem("currentOntologyScope") || "user";
  });

  useEffect(() => {
    const updateOntologyScope = () => {
      if (globalThis.ontology_session?.scope) {
        setOntologyScope(globalThis.ontology_session.scope);
        return;
      }

      // Fall back to sessionStorage
      const storedScope = sessionStorage.getItem("currentOntologyScope");
      setOntologyScope(storedScope || "user");
    };

    // Listen for storage events
    window.addEventListener("storage", updateOntologyScope);
    window.addEventListener("sessionStorageChanged", updateOntologyScope);

    return () => {
      window.removeEventListener("storage", updateOntologyScope);
      window.removeEventListener("sessionStorageChanged", updateOntologyScope);
    };
  }, []);

  return ontologyScope;
};

function toOntologyScope(scope: string): OntologyScope {
  return scope === "organization" ? "organization" : "user";
}

async function fetchOntologyName(ontologyId: string, scope: string): Promise<string> {
  try {
    const ontologyData = await OntologyService.loadOntology(ontologyId, toOntologyScope(scope));
    return ontologyData.name || ontologyId;
  } catch (error) {
    console.error("Error fetching ontology name:", error);
    // Fallback to the project ID if we can't fetch the name
    return ontologyId;
  }
}

/**
 * Hook to get the current ontology name.
 * Fetches the name using the current ontology ID, shared across callers via
 * React Query. Only fetches while the editor is open.
 */
export const useCurrentOntologyName = () => {
  const location = useLocation();
  const ontologyId = useOntologyId();
  const ontologyScope = useOntologyScope();

  const isOntologyPage = location.pathname.includes("/editor/");

  const { data, isLoading } = useQuery({
    queryKey: ["ontologyName", ontologyId, ontologyScope],
    queryFn: () => fetchOntologyName(ontologyId as string, ontologyScope),
    enabled: Boolean(ontologyId) && isOntologyPage,
  });

  return { ontologyName: data ?? null, isLoading };
};
