import type {
  ConceptGraphPagination,
  ExplorerEdge,
  ExplorerNode,
  ExplorerSubgraph,
  NodeAnalytics,
} from "./types";

export interface AnalyticsRange {
  min: number;
  max: number;
}

export interface ConceptGraphData {
  nodes: Record<string, ExplorerNode>;
  edges: Record<string, ExplorerEdge>;
  pagination: ConceptGraphPagination | null;
  /** Active analytics overlay key (e.g. "pagerank"), when the graph is scored. */
  analyticsType: string | null;
  /** Numeric score range across scored nodes, for node-size normalization. */
  analyticsRange: AnalyticsRange | null;
  /** Column names for the tabular view of the underlying result rows. */
  columns: string[];
  /** Underlying result rows backing this graph (same page as the graph). */
  rows: unknown[][];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function toAnalytics(raw: unknown): NodeAnalytics | undefined {
  if (!isRecord(raw)) return undefined;
  const analytics: NodeAnalytics = {};
  if (typeof raw.score === "number") analytics.score = raw.score;
  if (raw.component !== undefined) analytics.component = String(raw.component);
  return analytics.score === undefined && analytics.component === undefined ? undefined : analytics;
}

function toNode(raw: unknown): ExplorerNode | null {
  if (!isRecord(raw) || raw.id === undefined) return null;
  const id = String(raw.id);
  return {
    id,
    node_type: typeof raw.type === "string" ? raw.type : "concept",
    key: id,
    label: id,
    attributes: {},
    analytics: toAnalytics(raw.analytics),
  };
}

function toAnalyticsRange(raw: unknown): AnalyticsRange | null {
  if (!isRecord(raw)) return null;
  if (typeof raw.min !== "number" || typeof raw.max !== "number") return null;
  return { min: raw.min, max: raw.max };
}

function toEdge(raw: unknown): ExplorerEdge | null {
  if (!isRecord(raw) || raw.source === undefined || raw.target === undefined) return null;
  const source = String(raw.source);
  const target = String(raw.target);
  const id = raw.id !== undefined ? String(raw.id) : `${source}->${target}`;
  return {
    id,
    edge_type: typeof raw.type === "string" ? raw.type : "edge",
    label: typeof raw.label === "string" ? raw.label : "",
    source,
    target,
  };
}

function toPagination(raw: unknown): ConceptGraphPagination | null {
  if (!isRecord(raw)) return null;
  return {
    page: Number(raw.page ?? 1),
    total_pages: Number(raw.total_pages ?? 1),
    has_next: Boolean(raw.has_next),
    has_prev: Boolean(raw.has_prev),
    total_count: Number(raw.total_count ?? 0),
    page_size: Number(raw.page_size ?? 0),
  };
}

function extractColumnsRows(data: Record<string, unknown>): {
  columns: string[];
  rows: unknown[][];
} {
  const columns = Array.isArray(data.columns) ? data.columns.map((column) => String(column)) : [];
  const rows =
    Array.isArray(data.rows) && data.rows.every((row) => Array.isArray(row))
      ? (data.rows as unknown[][])
      : [];
  return { columns, rows };
}

/** The paginated table slice of an analytics response (no graph payload). */
export interface ConceptGraphPageSlice {
  columns: string[];
  rows: unknown[][];
  pagination: ConceptGraphPagination | null;
}

/**
 * Parse a lightweight analytics page-change response — it carries only the
 * table slice (`columns`, `rows`, `pagination`), not a fresh graph, so the
 * caller keeps the existing overlay graph and swaps in the new rows.
 */
export function parseConceptGraphPage(response: unknown): ConceptGraphPageSlice | null {
  if (!isRecord(response)) return null;
  const data = response.data;
  if (!isRecord(data)) return null;
  const { columns, rows } = extractColumnsRows(data);
  return { columns, rows, pagination: toPagination(data.pagination) };
}

/**
 * Stable, page-independent edge identity. Backend edge ids are page-local
 * (`{predicate}-{idx}`), so merging neighbors fetched across pages must dedup by
 * endpoints + label, not by id.
 */
export function edgeStableKey(edge: { source: string; target: string; label: string }): string {
  return `${edge.source}->${edge.target}->${edge.label}`;
}

/**
 * Additively merge an expansion subgraph (`addition`) into the current graph
 * (`base`): new nodes/edges are upserted, existing ones are kept as-is, and the
 * table slice (`pagination`/`columns`/`rows`) plus any analytics overlay stay
 * from `base` (an expansion is an overlay, not a page). Added edges are stored
 * under their stable key so cross-page duplicates collapse and G6 ids stay
 * unique.
 */
export function mergeConceptGraph(
  base: ConceptGraphData,
  addition: ConceptGraphData,
): ConceptGraphData {
  const nodes = { ...base.nodes };
  for (const [id, node] of Object.entries(addition.nodes)) {
    if (!nodes[id]) nodes[id] = node;
  }

  const edges = { ...base.edges };
  const existingKeys = new Set(Object.values(base.edges).map(edgeStableKey));
  for (const edge of Object.values(addition.edges)) {
    const key = edgeStableKey(edge);
    if (existingKeys.has(key)) continue;
    existingKeys.add(key);
    edges[key] = { ...edge, id: key };
  }

  return { ...base, nodes, edges };
}

/**
 * Swap only the tabular slice (`columns`/`rows`/`pagination`) into `base`,
 * leaving `nodes`/`edges` and any expansions untouched. Used when the table
 * pages independently of a persistent records-mode graph.
 */
export function mergeTableSlice(
  base: ConceptGraphData,
  slice: ConceptGraphPageSlice,
): ConceptGraphData {
  return { ...base, columns: slice.columns, rows: slice.rows, pagination: slice.pagination };
}

export interface ConceptGraphCollapseResult {
  data: ConceptGraphData;
  /** Neighbor node ids that were removed by the collapse. */
  removedNodeIds: string[];
}

/**
 * Collapse a node: the exact inverse of Expand. Remove every edge incident to
 * `nodeId`, then drop any neighbor left with no edges (it was only on the canvas
 * because of this node). The collapsed node itself stays (now isolated), so it
 * can be expanded again. Purely topological — no provenance/seed bookkeeping —
 * so it removes the node's whole neighborhood whether those edges came from the
 * sampled seed or a prior expansion.
 */
export function collapseNodeNeighborhood(
  data: ConceptGraphData,
  nodeId: string,
): ConceptGraphCollapseResult {
  const neighbors = new Set<string>();
  const edges: Record<string, ExplorerEdge> = {};
  for (const [key, edge] of Object.entries(data.edges)) {
    if (edge.source === nodeId || edge.target === nodeId) {
      const other = edge.source === nodeId ? edge.target : edge.source;
      if (other !== nodeId) neighbors.add(other);
      continue;
    }
    edges[key] = edge;
  }

  // A neighbor survives only if it still touches an edge once this node's edges
  // are gone.
  const stillConnected = new Set<string>();
  for (const edge of Object.values(edges)) {
    stillConnected.add(edge.source);
    stillConnected.add(edge.target);
  }

  const removedNodeIds: string[] = [];
  const nodes: Record<string, ExplorerNode> = {};
  for (const [id, node] of Object.entries(data.nodes)) {
    if (id !== nodeId && neighbors.has(id) && !stillConnected.has(id)) {
      removedNodeIds.push(id);
      continue;
    }
    nodes[id] = node;
  }
  return { data: { ...data, nodes, edges }, removedNodeIds };
}

export interface ConceptNodeNeighbor {
  direction: "out" | "in";
  otherId: string;
  edgeLabel: string;
}

/** Edges touching a node within the loaded subgraph, as neighbor entries. */
export function conceptNodeNeighbors(
  data: ConceptGraphData,
  nodeId: string,
): ConceptNodeNeighbor[] {
  return Object.values(data.edges)
    .filter((edge) => edge.source === nodeId || edge.target === nodeId)
    .map((edge) => ({
      direction: edge.source === nodeId ? "out" : "in",
      otherId: edge.source === nodeId ? edge.target : edge.source,
      edgeLabel: edge.label,
    }));
}

/**
 * Parse the build-graph endpoint response ({status, data:{nodes, edges,
 * pagination}}) into explorer records. Returns null when the shape is not
 * recognized so callers can surface a clear error.
 */
export function parseConceptGraphResponse(response: unknown): ConceptGraphData | null {
  if (!isRecord(response)) return null;
  const data = response.data;
  if (!isRecord(data)) return null;
  const rawNodes = Array.isArray(data.nodes) ? data.nodes : null;
  const rawEdges = Array.isArray(data.edges) ? data.edges : null;
  if (!rawNodes || !rawEdges) return null;

  const subgraph: ExplorerSubgraph = {
    nodes: rawNodes.map(toNode).filter((node): node is ExplorerNode => node !== null),
    edges: rawEdges.map(toEdge).filter((edge): edge is ExplorerEdge => edge !== null),
  };

  const { columns, rows } = extractColumnsRows(data);

  return {
    nodes: Object.fromEntries(subgraph.nodes.map((node) => [node.id, node])),
    edges: Object.fromEntries(subgraph.edges.map((edge) => [edge.id, edge])),
    pagination: toPagination(data.pagination),
    analyticsType: typeof data.analytics_type === "string" ? data.analytics_type : null,
    analyticsRange: toAnalyticsRange(data.analytics_range),
    columns,
    rows,
  };
}
