import { Loader2, Shield, X } from "lucide-react";
import type React from "react";
import { useCallback } from "react";
import { toast } from "sonner";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { useConceptRestrictions } from "../hooks/useConceptRestrictions";
import { OWNER_CALLER, type PermissionCaller, type RestrictionLevel } from "../types";
import ConceptAccessRoster from "./ConceptAccessRoster";

interface ConceptRestrictionsDialogProps {
  isOpen: boolean;
  onClose: () => void;
  ontologyId: string;
  predicateName: string;
  // Owner by default; a recipient-team admin routes mutations via team-admin/apply.
  caller?: PermissionCaller;
  // The project owner's id — passed to the roster so the owner is shown as a
  // static "full access" row and never gets an editable dropdown (can't be
  // restricted).
  ownerSub?: string;
}

// Thin shell around the access roster: the roster lists everyone with access to
// the concept (owner, shared team(s), then individual members) and — for a
// caller who may manage permissions — exposes an inline dropdown per row to set
// or reset that subject's concept-level permission.
const ConceptRestrictionsDialog: React.FC<ConceptRestrictionsDialogProps> = ({
  isOpen,
  onClose,
  ontologyId,
  predicateName,
  caller = OWNER_CALLER,
  ownerSub,
}) => {
  const {
    isLoading,
    setRestriction,
    isSettingRestriction,
    clearRestriction,
    isClearingRestriction,
  } = useConceptRestrictions({ ontologyId, enabled: isOpen, caller });

  const isBusy = isSettingRestriction || isClearingRestriction;

  const handleSetMemberLevel = useCallback(
    async (recipientSub: string, level: RestrictionLevel) => {
      try {
        await setRestriction({
          ontology_id: ontologyId,
          predicate_name: predicateName,
          level,
          recipient_sub: recipientSub,
        });
        toast.success("Permission updated");
      } catch {
        toast.error("Failed to update permission");
      }
    },
    [setRestriction, ontologyId, predicateName],
  );

  const handleClearMemberLevel = useCallback(
    async (recipientSub: string) => {
      try {
        await clearRestriction({
          ontology_id: ontologyId,
          predicate_name: predicateName,
          recipient_sub: recipientSub,
        });
        toast.success("Permission reset to default");
      } catch {
        toast.error("Failed to update permission");
      }
    },
    [clearRestriction, ontologyId, predicateName],
  );

  const handleSetTeamLevel = useCallback(
    async (teamId: string, level: RestrictionLevel) => {
      try {
        await setRestriction({
          ontology_id: ontologyId,
          predicate_name: predicateName,
          level,
          team_id: teamId,
        });
        toast.success("Team permission updated");
      } catch {
        toast.error("Failed to update team permission");
      }
    },
    [setRestriction, ontologyId, predicateName],
  );

  const handleClearTeamLevel = useCallback(
    async (teamId: string) => {
      try {
        await clearRestriction({
          ontology_id: ontologyId,
          predicate_name: predicateName,
          team_id: teamId,
        });
        toast.success("Team permission reset to default");
      } catch {
        toast.error("Failed to update team permission");
      }
    },
    [clearRestriction, ontologyId, predicateName],
  );

  const handleOpenChange = (open: boolean): void => {
    if (!open) onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent className="p-0 sm:max-w-[480px] overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Concept permissions</DialogTitle>

        <div className="flex items-center justify-between border-b border-border bg-card px-4 py-3">
          <div className="flex items-center gap-2">
            <Shield className="h-4 w-4 text-primary" />
            <span className="text-sm font-semibold text-foreground">
              Permissions — {predicateName}
            </span>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="h-6 w-6 inline-flex items-center justify-center rounded text-muted-foreground hover:bg-accent hover:text-foreground"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="flex flex-col gap-4 p-4">
          {isLoading ? (
            <div className="flex items-center justify-center py-6">
              <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
            </div>
          ) : (
            <div className="flex flex-col gap-1">
              <p className="text-xs font-medium text-muted-foreground mb-1">Current access</p>
              <ConceptAccessRoster
                ontologyId={ontologyId}
                predicateName={predicateName}
                caller={caller}
                ownerSub={ownerSub}
                onSetLevel={handleSetMemberLevel}
                onClearLevel={handleClearMemberLevel}
                onSetTeamLevel={handleSetTeamLevel}
                onClearTeamLevel={handleClearTeamLevel}
                isBusy={isBusy}
              />
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default ConceptRestrictionsDialog;
