import { SUPABASE_URL } from "@/shared/integrations/supabase/client";

/**
 * Tracks user login by calling the Supabase edge function
 */
export async function trackLogin(accessToken: string, loginMethod: string = "password") {
  try {
    const _response = await fetch(`${SUPABASE_URL}/functions/v1/track-login`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${accessToken}`,
      },
      body: JSON.stringify({ login_method: loginMethod }),
    });
  } catch (error) {
    console.error("[Login Tracking] ✗ Failed to track login:", error);
  }
}
