import { FolderTree } from "lucide-react";
import type React from "react";
import { cn } from "@/shared/lib/utils";

interface LineageTreeRailProps {
  isOpen: boolean;
  onToggle: () => void;
}

/**
 * Left-edge rail that toggles the Explorer tree — mirrors the right-side
 * LibraryRail (Concepts/Data) so the tree uses the same docked-icon pattern.
 * Lives at the workspace level so it stays visible even when the canvas is
 * collapsed (dock maximized).
 */
const LineageTreeRail: React.FC<LineageTreeRailProps> = ({ isOpen, onToggle }) => (
  <div className="flex w-8 flex-shrink-0 flex-col border-r border-border bg-card">
    <button
      type="button"
      onClick={onToggle}
      title="Explorer"
      aria-pressed={isOpen}
      className={cn(
        "flex flex-col items-center gap-2 border-r-2 px-1 py-3 transition-colors",
        isOpen
          ? "border-primary bg-accent text-accent-foreground"
          : "border-transparent text-muted-foreground hover:bg-accent hover:text-accent-foreground",
      )}
    >
      <FolderTree className="h-4 w-4 flex-shrink-0" />
      <span
        className="text-[10px] font-medium uppercase tracking-wider"
        style={{ writingMode: "vertical-rl", transform: "rotate(180deg)" }}
      >
        Explorer
      </span>
    </button>
  </div>
);

export default LineageTreeRail;
