import React from "react";
import { ErrorBoundary } from "@/shared/components/ErrorBoundary";
import { cn } from "@/shared/lib/utils";
import type { FetchResult } from "../../api/ConceptClient";
import type { DashboardSection } from "../../types";
import type { DashboardTableHandlers } from "../outputs/table/tableOutput.types";
import { WidgetCell } from "./WidgetCell";

interface SectionViewProps {
  section: DashboardSection;
  data: Record<string, FetchResult | null>;
  loading: Record<string, boolean>;
  errors: Record<string, string>;
  tableHandlers?: DashboardTableHandlers;
  fullscreen?: boolean;
  ontologyId?: string;
}

export function SectionView({
  section,
  data,
  loading,
  errors,
  tableHandlers,
  fullscreen = false,
  ontologyId,
}: SectionViewProps) {
  if (fullscreen) {
    return (
      <div className="flex-1 min-h-0 flex flex-col">
        {section.widgets[0] && (
          <ErrorBoundary inline>
            <WidgetCell
              widget={section.widgets[0]}
              data={data}
              loading={loading}
              errors={errors}
              tableHandlers={tableHandlers}
              fullscreen
              ontologyId={ontologyId}
            />
          </ErrorBoundary>
        )}
      </div>
    );
  }

  const gridClass =
    {
      single: "grid-cols-1",
      two_col: "grid-cols-1 md:grid-cols-2",
      four_col: "grid-cols-2 lg:grid-cols-4",
    }[section.layout] ?? "grid-cols-1";

  return (
    <div className="flex flex-col gap-3">
      {section.title && (
        <h3 className="text-[12px] font-semibold text-foreground uppercase tracking-wider">
          {section.title}
        </h3>
      )}
      <div className={cn("grid gap-3", gridClass)}>
        {section.widgets.map((widget) => (
          <ErrorBoundary key={widget.id} inline>
            <WidgetCell
              widget={widget}
              data={data}
              loading={loading}
              errors={errors}
              tableHandlers={tableHandlers}
              ontologyId={ontologyId}
            />
          </ErrorBoundary>
        ))}
      </div>
    </div>
  );
}
