import { LogOut } from "lucide-react";
import { useState } from "react";
import { useNavigate } from "react-router-dom";

import { useAuth } from "@/features/auth/components/AuthProvider";
import { CompanyContextStep } from "@/features/onboarding/components/CompanyContextStep";
import { CompanyDoneStep } from "@/features/onboarding/components/CompanyDoneStep";
import { CompanyOnboardingSkipScreen } from "@/features/onboarding/components/CompanyOnboardingSkipScreen";
import { DataConnectStep } from "@/features/onboarding/components/DataConnectStep";
import { InterviewStep } from "@/features/onboarding/components/InterviewStep";
import { PreferencesStep } from "@/features/onboarding/components/PreferencesStep";
import { WelcomeStep } from "@/features/onboarding/components/WelcomeStep";
import { companyOnboardingSkip } from "@/features/onboarding/utils/companyOnboardingSkip";
import { Button } from "@/shared/components/ui/button";
import { useWizardState, type WizardStepDef } from "@/shared/components/wizard/useWizardState";
import { Wizard } from "@/shared/components/wizard/Wizard";

const STEPS: WizardStepDef[] = [
  { id: "welcome", title: "Welcome", description: "What we'll do" },
  {
    id: "connect",
    title: "Connect data",
    description: "Add the sources the assistant should reason over",
    canSkip: true,
  },
  {
    id: "context",
    title: "Your context",
    description: "Tell the assistant about your work",
    canSkip: true,
  },
  {
    id: "interview",
    title: "Quick interview",
    description: "Five short prompts to round out your context",
    canSkip: true,
  },
  { id: "preferences", title: "Preferences", description: "Date format, locale, response style" },
  { id: "done", title: "Done", description: "You're all set" },
];

export function CompanyOnboardingWizard() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const userId = user?.id ?? "anonymous";
  const [isConfirmingSkip, setIsConfirmingSkip] = useState(false);

  const controls = useWizardState({
    id: "company-onboarding",
    steps: STEPS,
    userId,
  });

  const renderStep = () => {
    switch (controls.currentStep.id) {
      case "welcome":
        return <WelcomeStep controls={controls} />;
      case "connect":
        return <DataConnectStep controls={controls} />;
      case "context":
        return <CompanyContextStep controls={controls} />;
      case "interview":
        return <InterviewStep controls={controls} />;
      case "preferences":
        return <PreferencesStep controls={controls} />;
      case "done":
        return <CompanyDoneStep controls={controls} />;
      default: {
        const _exhaustive: never = controls.currentStep.id as never;
        throw new Error(`Unhandled step: ${_exhaustive}`);
      }
    }
  };

  // The "skip" flag is really a "this user has been through the wizard"
  // marker — without it set on completion, a user who skipped every
  // note-producing step finishes with an empty workspace, the home-page
  // CompanyOnboardingGate sees 0 projects + 0 notes and redirects back
  // here, and useWizardState's stale-completion guard resets the cache
  // (catching them on step 1). Setting the flag on completion breaks
  // that loop. Naming friction noted; renaming the util is a separate
  // pass since the existing call sites assume "skip" semantics.
  const markWizardDone = () => {
    if (userId && userId !== "anonymous") {
      companyOnboardingSkip.markSkipped(userId);
    }
  };

  const handleComplete = () => {
    // Onboarding done — drop the user on the home page. Anything they need
    // to revisit lives in Settings → Context Management.
    markWizardDone();
    navigate("/", { replace: true });
  };

  const handleSkipRequest = () => setIsConfirmingSkip(true);
  const handleSkipCancel = () => setIsConfirmingSkip(false);
  const handleSkipConfirm = () => {
    markWizardDone();
    navigate("/", { replace: true });
  };

  if (isConfirmingSkip) {
    return (
      <div className="flex h-full flex-col gap-3">
        <CompanyOnboardingSkipScreen onConfirm={handleSkipConfirm} onCancel={handleSkipCancel} />
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col gap-3">
      {!controls.isLastStep && (
        <div className="flex items-center justify-end">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={handleSkipRequest}
            className="gap-1.5 text-muted-foreground hover:text-foreground"
            title="Exit setup and go to your workspace — you can come back from Settings"
          >
            <LogOut className="h-3.5 w-3.5" />
            Skip onboarding
          </Button>
        </div>
      )}
      <Wizard steps={STEPS} controls={controls} onComplete={handleComplete}>
        {() => renderStep()}
      </Wizard>
    </div>
  );
}
