import { createContext, type ReactNode, useCallback, useContext, useMemo, useState } from "react";
import type { AppPageDef } from "../schema/appDefinition.types";

/**
 * The per-tab reactive context (ADR D2): inputs, form submissions and widget
 * row-selections all publish typed values here; run-group bindings read them.
 * Context is tab-scoped by design (D9) — each AppTabView mounts its own.
 */

export type TabValues = Record<string, unknown>;

interface TabContextValue {
  values: TabValues;
  setValue: (key: string, value: unknown) => void;
  setValues: (patch: TabValues) => void;
}

const TabContext = createContext<TabContextValue | null>(null);

function initialValuesFor(page: AppPageDef): TabValues {
  const seeded: TabValues = {};
  for (const input of page.inputs ?? []) {
    if (input.type !== "form" && input.default !== undefined) {
      seeded[input.id] = input.default;
    }
  }
  return seeded;
}

interface TabContextProviderProps {
  page: AppPageDef;
  children: ReactNode;
}

export function TabContextProvider({ page, children }: TabContextProviderProps) {
  const [values, setValuesState] = useState<TabValues>(() => initialValuesFor(page));

  const setValue = useCallback((key: string, value: unknown) => {
    setValuesState((prev) => ({ ...prev, [key]: value }));
  }, []);

  const setValues = useCallback((patch: TabValues) => {
    setValuesState((prev) => ({ ...prev, ...patch }));
  }, []);

  const contextValue = useMemo(
    () => ({ values, setValue, setValues }),
    [values, setValue, setValues],
  );

  return <TabContext.Provider value={contextValue}>{children}</TabContext.Provider>;
}

export function useTabContext(): TabContextValue {
  const context = useContext(TabContext);
  if (!context) throw new Error("useTabContext must be used inside a TabContextProvider");
  return context;
}
