import { FileText, Table2 } from "lucide-react";
import type React from "react";
import type { ConceptCell } from "@/features/concept-editor/types";
import { runStatusDotClass } from "@/features/concept-editor/utils/runStatus";
import PythonIcon from "@/shared/components/icons/PythonIcon";
import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

type PythonCellView = "context" | "python" | "output";

interface PythonCellViewTabsProps {
  cell: ConceptCell;
  currentView: PythonCellView;
  splitLayout: boolean;
  onSelectView: (view: PythonCellView) => void;
}

const TAB_BASE = "h-7 px-2 text-xs";
const TAB_ACTIVE = "bg-muted text-foreground";
const TAB_INACTIVE = "hover:bg-muted/50";

/**
 * Top view switcher for a Python cell (context / python / output). In split
 * layout only the "python" tab is shown here; the other tabs move to a panel
 * below. Extracted from QueryPythonCell to keep that component within its budget.
 */
const PythonCellViewTabs: React.FC<PythonCellViewTabsProps> = ({
  cell,
  currentView,
  splitLayout,
  onSelectView,
}) => {
  const pythonActive = currentView === "python" || splitLayout;
  const showOutputDot = !!(cell.result || cell.error || cell.isRunning);

  return (
    <div className={cn("border-t border-border/50 bg-muted/30", splitLayout && "order-1")}>
      <div className="flex items-center justify-between px-4 py-2">
        <div className="flex items-center gap-1">
          {!splitLayout && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => onSelectView("context")}
              className={cn(TAB_BASE, currentView === "context" ? TAB_ACTIVE : TAB_INACTIVE)}
            >
              <FileText className="h-3 w-3 mr-1" />
              context
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onSelectView("python")}
            className={cn(TAB_BASE, pythonActive ? TAB_ACTIVE : TAB_INACTIVE)}
          >
            <PythonIcon className="h-3 w-3 mr-1" />
            python
          </Button>
          {!splitLayout && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => onSelectView("output")}
              className={cn(TAB_BASE, currentView === "output" ? TAB_ACTIVE : TAB_INACTIVE)}
            >
              <Table2 className="h-3 w-3 mr-1" />
              output
              {showOutputDot && (
                <span
                  className={`ml-1 inline-block h-1.5 w-1.5 rounded-full ${runStatusDotClass(cell)}`}
                />
              )}
            </Button>
          )}
        </div>
      </div>
    </div>
  );
};

export default PythonCellViewTabs;
