import { useEffect } from "react";
import { Navigate, Route, Routes } from "react-router-dom";
import { AccessRestrictedScreen } from "@/features/auth/components/AccessRestrictedScreen";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { RequireAuth } from "@/features/auth/components/RequireAuth";
import { RequirePermission } from "@/features/auth/components/RequirePermission";
import DatabricksOAuthCallback from "@/features/auth/pages/DatabricksOAuthCallback";
import Login from "@/features/auth/pages/LoginPage";
import MfaChallengePage from "@/features/auth/pages/MfaChallengePage";
import PasswordResetConfirm from "@/features/auth/pages/PasswordResetConfirm";
import PasswordResetRequest from "@/features/auth/pages/PasswordResetRequest";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import Compute from "@/features/compute/ComputePage";
import ContextPage from "@/features/context-layer/notes/ContextPage";
import AppsDashboardPage from "@/features/dashboards/pages/AppsDashboardPage";
import AppsListPage from "@/features/dashboards/pages/AppsListPage";
import DataSources from "@/features/data-sources/DataSourcesPage";
import DashboardEditPage from "@/features/dynamic-dashboard/pages/DashboardEditPage";
import DashboardRunPage from "@/features/dynamic-dashboard/pages/DashboardRunPage";
import GraphExplorerPage from "@/features/graph-explorer/GraphExplorerPage";
import { CompanyOnboardingGate } from "@/features/onboarding/components/CompanyOnboardingGate";
import Onboarding from "@/features/onboarding/OnboardingPage";
import OntologiesList from "@/features/ontologies/OntologiesListPage";
import Ontologies from "@/features/ontologies/OntologiesPage";
import ProfilePage from "@/features/settings/ProfilePage";
import SettingsPage from "@/features/settings/SettingsPage";
import { teamsRoutes } from "@/features/teams/teamsRoutes";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import CompanySetupPage from "./pages/CompanySetupPage";
import { LegacyDashboardRedirect } from "./pages/LegacyDashboardRedirect";
import OntologyRoute from "./pages/OntologyRoute";

const AppRoutes = () => {
  const { user, hasPlatformAccess, signOut } = useAuth();
  const permissionsLoaded = usePermissionsStore((state) => state.loaded);
  const hasAnyAccess = usePermissionsStore((state) => state.hasAnyAccess);

  // Enhanced route change detection
  useEffect(() => {
    const handleRouteChange = () => {
      const pathParts = window.location.pathname.split("/").filter(Boolean);
      const isHomePage =
        window.location.pathname === "/" ||
        (pathParts.length === 2 && !pathParts[0].includes("editor"));

      if (isHomePage && globalThis.ontology_session) {
        globalThis.ontology_session = null;
      }
    };

    window.addEventListener("popstate", handleRouteChange);

    // Clean up
    return () => {
      window.removeEventListener("popstate", handleRouteChange);
    };
  }, []);

  if (user && hasPlatformAccess && !permissionsLoaded) {
    return (
      <div className="flex h-screen items-center justify-center bg-background">
        <PrometheuxSpinner size={36} />
      </div>
    );
  }

  if (user && hasPlatformAccess && permissionsLoaded && !hasAnyAccess) {
    return <AccessRestrictedScreen onSignOut={signOut} />;
  }

  return (
    <Routes>
      {/* Public auth routes */}
      <Route path="/login" element={<Login />} />
      <Route path="/reset-password" element={<PasswordResetRequest />} />
      <Route path="/reset-password/confirm" element={<PasswordResetConfirm />} />
      <Route path="/databricks-oauth-callback" element={<DatabricksOAuthCallback />} />
      <Route path="/mfa-challenge" element={<MfaChallengePage />} />

      {/* Onboarding route for users without platform access */}
      <Route
        path="/onboarding"
        element={
          <RequireAuth>
            <Onboarding />
          </RequireAuth>
        }
      />

      {/* Main routes - requires platform access */}
      <Route
        path="/"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_ai_agent">
              <CompanyOnboardingGate>
                <Ontologies />
              </CompanyOnboardingGate>
            </RequirePermission>
          </RequireAuth>
        }
      />

      <Route
        path="/:organization/:username"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_ai_agent">
              <CompanyOnboardingGate>
                <Ontologies />
              </CompanyOnboardingGate>
            </RequirePermission>
          </RequireAuth>
        }
      />

      <Route
        path="/settings"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_settings">
              <SettingsPage />
            </RequirePermission>
          </RequireAuth>
        }
      />

      {/* Stripe checkout / customer-portal redirects land at /settings/billing.
          Reuses SettingsPage; SettingsPanel deep-links to the billing section
          via location.pathname. */}
      <Route
        path="/settings/billing"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_settings">
              <SettingsPage />
            </RequirePermission>
          </RequireAuth>
        }
      />

      <Route
        path="/profile"
        element={
          <RequireAuth>
            <ProfilePage />
          </RequireAuth>
        }
      />

      {/* Updated editor routes with username and organization */}
      <Route
        path="/editor/:organization/:username/:id"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_projects">
              <OntologyRoute />
            </RequirePermission>
          </RequireAuth>
        }
      />

      <Route
        path="/datasources"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_datasources">
              <DataSources />
            </RequirePermission>
          </RequireAuth>
        }
      />

      <Route
        path="/graph-explorer"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_graph_explorer">
              <GraphExplorerPage />
            </RequirePermission>
          </RequireAuth>
        }
      />

      <Route
        path="/ontologies"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_projects">
              <OntologiesList />
            </RequirePermission>
          </RequireAuth>
        }
      />

      {/* Teams routes live with the feature (gated by can_see_teams). */}
      {teamsRoutes}

      {/* Context Management page (Obsidian shell) — replaces the old Settings
          section. Gated by can_see_ai_agent: context feeds the AI assistant. */}
      <Route
        path="/context/:noteId?"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_ai_agent">
              <ContextPage />
            </RequirePermission>
          </RequireAuth>
        }
      />

      <Route
        path="/compute"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_compute_page">
              <Compute />
            </RequirePermission>
          </RequireAuth>
        }
      />

      {/* ── Apps: one catalog (ADR D10). Dynamic apps live at /apps/:ontologyId/:id
          (two segments) and are edited in-platform; federated apps live at
          /apps/:dashboardId (one segment) and load as Module Federation remotes.
          /apps/new/edit must precede the parametric routes so React Router's
          static-segment scoring picks it for new apps. ── */}
      <Route
        path="/apps/new/edit"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_dynamic_dashboards">
              <DashboardEditPage />
            </RequirePermission>
          </RequireAuth>
        }
      />

      <Route
        path="/apps/:ontologyId/:id/edit"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_dynamic_dashboards">
              <DashboardEditPage />
            </RequirePermission>
          </RequireAuth>
        }
      />

      <Route
        path="/apps/:ontologyId/:id"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_dynamic_dashboards">
              <DashboardRunPage />
            </RequirePermission>
          </RequireAuth>
        }
      />

      {/* Legacy /dashboards URLs — permanent client-side redirects to /apps. */}
      <Route path="/dashboards" element={<Navigate to="/apps" replace />} />
      <Route path="/dashboards/new/edit" element={<Navigate to="/apps/new/edit" replace />} />
      <Route path="/dashboards/:ontologyId/:id/edit" element={<LegacyDashboardRedirect edit />} />
      <Route path="/dashboards/:ontologyId/:id" element={<LegacyDashboardRedirect />} />

      <Route
        path="/apps"
        element={
          <RequireAuth>
            <AppsListPage />
          </RequireAuth>
        }
      />

      <Route
        path="/apps/:dashboardId"
        element={
          <RequireAuth>
            <AppsDashboardPage />
          </RequireAuth>
        }
      />

      <Route
        path="/editor/:id"
        element={
          <RequireAuth>
            <RequirePermission permissionKey="can_see_projects">
              <OntologyRoute />
            </RequirePermission>
          </RequireAuth>
        }
      />

      {/* Knowledge Layer company setup (CompanyOnboardingWizard).
          Optional one-time bootstrap of global preferences, observation
          notes from connected data sources, etc. Trigger from
          Settings → Context Management. */}
      <Route
        path="/setup/company"
        element={
          <RequireAuth>
            <CompanySetupPage />
          </RequireAuth>
        }
      />

      {/* Catch-all route to redirect based on authentication and platform access */}
      <Route
        path="*"
        element={
          <Navigate to={!user ? "/login" : hasPlatformAccess ? "/" : "/onboarding"} replace />
        }
      />
    </Routes>
  );
};

export default AppRoutes;
