import type React from "react";
import { createContext, useContext, useRef } from "react";
import { ConceptEditorClient } from "./ConceptEditorClient";

const ConceptEditorClientContext = createContext<ConceptEditorClient | null>(null);

export const ConceptEditorClientProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const clientRef = useRef(new ConceptEditorClient());
  return (
    <ConceptEditorClientContext.Provider value={clientRef.current}>
      {children}
    </ConceptEditorClientContext.Provider>
  );
};

export function useConceptEditorClient(): ConceptEditorClient {
  const client = useContext(ConceptEditorClientContext);
  if (!client) {
    return new ConceptEditorClient();
  }
  return client;
}
