import {
  File,
  FileBraces,
  FileChartPie,
  FileCode,
  FileDigit,
  FileImage,
  FileSliders,
  FileSpreadsheet,
  FileText,
  type LucideIcon,
} from "lucide-react";

/**
 * Single source of truth for file-type icons (pure data — no JSX).
 *
 * Every surface that shows a file/data type — the Files tab (keyed by extension),
 * the Sources tab and the lineage graph (via `DatabaseIcon`, keyed by the token from
 * `getIconTypeForBinaryFile`) — resolves through THIS map, so the same type always
 * shows the same icon and color everywhere. `isFileType` is also the single authority
 * for "which extensions count as file types," so `getIconTypeForBinaryFile` no longer
 * keeps its own list that could drift from this one.
 *
 * Keys are lowercase. Multiple keys may share a spec; types that share an icon are
 * differentiated purely by color. Database / storage / brand types are intentionally
 * absent — `DatabaseIcon` handles those itself.
 */
export interface FileIconSpec {
  Icon: LucideIcon;
  colorClass: string;
}

const SPREADSHEET_GREEN: FileIconSpec = {
  Icon: FileSpreadsheet,
  colorClass: "text-green-600 dark:text-green-400",
};
const SPREADSHEET_TEAL: FileIconSpec = {
  Icon: FileSpreadsheet,
  colorClass: "text-teal-600 dark:text-teal-400",
};
const TEXT_NEUTRAL: FileIconSpec = { Icon: FileText, colorClass: "text-foreground" };
const TEXT_RED: FileIconSpec = { Icon: FileText, colorClass: "text-red-500 dark:text-red-400" };
const TEXT_SKY: FileIconSpec = { Icon: FileText, colorClass: "text-sky-600 dark:text-sky-400" };
const CODE_FUCHSIA: FileIconSpec = {
  Icon: FileCode,
  colorClass: "text-fuchsia-600 dark:text-fuchsia-400",
};
const CODE_YELLOW: FileIconSpec = {
  Icon: FileCode,
  colorClass: "text-yellow-600 dark:text-yellow-400",
};

/**
 * The shared fallback for unknown / unclassified files. Every surface uses this
 * (via `resolveFileIconOrGeneric`, and as the "binaryfile" map entry) so an
 * unrecognized file looks identical in the Files tab, Sources tab and lineage.
 */
export const GENERIC_FILE: FileIconSpec = { Icon: File, colorClass: "text-muted-foreground" };

export const FILE_ICON_BY_TYPE: Record<string, FileIconSpec> = {
  // Tabular / spreadsheet
  csv: SPREADSHEET_GREEN,
  tsv: SPREADSHEET_GREEN,
  xlsx: SPREADSHEET_GREEN,
  xls: SPREADSHEET_GREEN,
  excel: SPREADSHEET_GREEN,
  // Columnar data files
  parquet: SPREADSHEET_TEAL,
  orc: SPREADSHEET_TEAL,
  // Structured text
  json: { Icon: FileBraces, colorClass: "text-amber-500 dark:text-amber-400" },
  yaml: { Icon: FileSliders, colorClass: "text-indigo-500 dark:text-indigo-400" },
  yml: { Icon: FileSliders, colorClass: "text-indigo-500 dark:text-indigo-400" },
  // Documents
  pdf: TEXT_RED,
  doc: TEXT_SKY,
  docx: TEXT_SKY,
  txt: TEXT_NEUTRAL,
  text: TEXT_NEUTRAL,
  md: TEXT_NEUTRAL,
  log: TEXT_NEUTRAL,
  // Semantic web / RDF family
  ttl: CODE_FUCHSIA,
  rdf: CODE_FUCHSIA,
  owl: CODE_FUCHSIA,
  // COBOL
  cbl: CODE_YELLOW,
  cpy: CODE_YELLOW,
  cobol: CODE_YELLOW,
  cob: CODE_YELLOW,
  // Images — same icon, distinct colors per format
  jpg: { Icon: FileImage, colorClass: "text-purple-500 dark:text-purple-400" },
  jpeg: { Icon: FileImage, colorClass: "text-purple-500 dark:text-purple-400" },
  gif: { Icon: FileImage, colorClass: "text-orange-500 dark:text-orange-400" },
  png: { Icon: FileImage, colorClass: "text-blue-500 dark:text-blue-400" },
  tiff: { Icon: FileImage, colorClass: "text-pink-500 dark:text-pink-400" },
  bmp: { Icon: FileImage, colorClass: "text-emerald-500 dark:text-emerald-400" },
  webp: { Icon: FileImage, colorClass: "text-rose-500 dark:text-rose-400" },
  // svg is data-shaped, not a raster image — its own icon
  svg: { Icon: FileChartPie, colorClass: "text-cyan-500 dark:text-cyan-400" },
  // Actual .bin blobs get a distinct icon (per the agreed mapping)…
  bin: { Icon: FileDigit, colorClass: "text-slate-500 dark:text-slate-400" },
  // …while "binaryfile" is the generic/unknown bucket — the shared fallback below.
  binaryfile: GENERIC_FILE,
};

/**
 * Returns true when `token` (an extension or a format token) maps to a file icon.
 * This is the single authority used to decide whether something is a file type.
 */
export const isFileType = (token: string | undefined | null): boolean =>
  !!token && token.toLowerCase() in FILE_ICON_BY_TYPE;
