import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";
import type { VisualizationResponse } from "@/shared/types/prometheux";

export class VisualizationService {
  /**
   * Fetches concept-level lineage visualization.
   * Returns only concept nodes with enriched metadata (fields/types)
   * and transitive dependency edges between concepts.
   */
  static async visualizeConceptLineage(
    ontologyId: string,
    ontologyScope: string = "user",
    focusConcept?: string | null,
  ): Promise<VisualizationResponse> {
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/kgs/${ontologyId}/visualize-concept-lineage`;

    const payload = {
      project: {
        scope: ontologyScope,
      },
      // When set, the backend returns only this concept plus its transitive
      // upstream dependencies. Omitted entirely for the full-lineage view.
      ...(focusConcept ? { focus_concept: focusConcept } : {}),
    };

    const response = (await HttpService.post(
      url,
      payload,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
    )) as VisualizationResponse;

    return response;
  }
}
