import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { applyTeamAdminAction, clearOntologyRoleOverride, setOntologyRoleOverride } from "../api";
import {
  type ClearOntologyRoleInput,
  type OntologyRoleOverride,
  type OntologyRoleOverrideInput,
  OWNER_CALLER,
  type PermissionCaller,
  type ShareError,
} from "../types";
import { CONCEPT_RESTRICTIONS_KEY } from "./useConceptRestrictions";

interface UseOntologyRoleOverrideReturn {
  setOntologyRole: (input: OntologyRoleOverrideInput) => Promise<OntologyRoleOverride>;
  clearOntologyRole: (input: ClearOntologyRoleInput) => Promise<void>;
  isSettingOntologyRole: boolean;
  isClearingOntologyRole: boolean;
}

// Per-member ontology-level role override. Owner mode hits /ontology-role; a
// recipient-team admin routes through team-admin/apply. Both invalidate the
// concept-restrictions cache because GET /concept-restrictions surfaces ontology
// overrides as scope="ontology" rows, so the same list drives the UI.
export function useOntologyRoleOverride(
  caller: PermissionCaller = OWNER_CALLER,
): UseOntologyRoleOverrideReturn {
  const { session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;

  const setMutation = useMutation<OntologyRoleOverride, ShareError, OntologyRoleOverrideInput>({
    mutationFn: (input) => {
      if (caller.mode === "team_admin") {
        return applyTeamAdminAction<OntologyRoleOverride>(
          supabaseToken,
          input.ontologyId,
          caller.teamId,
          { action: "set_project_role", subject_id: input.recipientSub, role: input.role },
        );
      }
      return setOntologyRoleOverride(supabaseToken, input);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: CONCEPT_RESTRICTIONS_KEY });
    },
  });

  const clearMutation = useMutation<void, ShareError, ClearOntologyRoleInput>({
    mutationFn: async (input) => {
      if (caller.mode === "team_admin") {
        await applyTeamAdminAction<unknown>(supabaseToken, input.ontologyId, caller.teamId, {
          action: "clear_project_role",
          subject_id: input.recipientSub,
        });
        return;
      }
      await clearOntologyRoleOverride(supabaseToken, input);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: CONCEPT_RESTRICTIONS_KEY });
    },
  });

  return {
    setOntologyRole: setMutation.mutateAsync,
    clearOntologyRole: clearMutation.mutateAsync,
    isSettingOntologyRole: setMutation.isPending,
    isClearingOntologyRole: clearMutation.isPending,
  };
}
