import { Search, X } from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent } from "@/shared/components/ui/card";
import { Input } from "@/shared/components/ui/input";

interface SearchResult {
  id: string;
  type: "node" | "edge";
  label: string;
  description?: string;
}

interface OntologySchemaSearchBarProps {
  nodes: Array<{
    id: string;
    label: string;
    description?: string;
    x?: number;
    y?: number;
  }>;
  edges: Array<{
    id: string;
    from: string;
    to: string;
    label: string;
    description?: string;
  }>;
  onNodeSelect: (nodeId: string) => void;
  onEdgeSelect: (edgeId: string) => void;
  onZoomToElement: (elementId: string, type: "node" | "edge") => void;
  /** Width of the search input; defaults to a fixed header width, override with "w-full" inside menus. */
  inputWidthClass?: string;
}

export const OntologySchemaSearchBar: React.FC<OntologySchemaSearchBarProps> = ({
  nodes,
  edges,
  onNodeSelect,
  onEdgeSelect,
  onZoomToElement,
  inputWidthClass = "w-64",
}) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const inputRef = useRef<HTMLInputElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Perform search when search term changes
  const performSearch = useCallback(
    (term: string) => {
      if (!term.trim()) {
        setSearchResults([]);
        setIsOpen(false);
        setSelectedIndex(-1);
        return;
      }

      const lowerTerm = term.toLowerCase().trim();

      // Search nodes - be more precise with matching
      const matchingNodes = nodes
        .filter((node) => {
          const labelMatch = node.label.toLowerCase().includes(lowerTerm);
          const descriptionMatch = node.description?.toLowerCase().includes(lowerTerm) ?? false;
          const idMatch = node.id.toLowerCase() === lowerTerm; // Only exact ID match

          return labelMatch || descriptionMatch || idMatch;
        })
        .map((node) => ({
          id: node.id,
          type: "node" as const,
          label: node.label,
          description: node.description,
        }));

      // Search edges - be more precise with matching
      const matchingEdges = edges
        .filter((edge) => {
          const labelMatch = edge.label.toLowerCase().includes(lowerTerm);
          const descriptionMatch = edge.description?.toLowerCase().includes(lowerTerm) ?? false;
          const idMatch = edge.id.toLowerCase() === lowerTerm; // Only exact ID match

          // For edge connections, only match if the search term exactly matches a node ID
          const fromMatch = edge.from.toLowerCase() === lowerTerm;
          const toMatch = edge.to.toLowerCase() === lowerTerm;

          return labelMatch || descriptionMatch || idMatch || fromMatch || toMatch;
        })
        .map((edge) => ({
          id: edge.id,
          type: "edge" as const,
          label: edge.label,
          description: edge.description,
        }));

      const results = [...matchingNodes, ...matchingEdges];
      setSearchResults(results);
      setIsOpen(results.length > 0);
      setSelectedIndex(-1);
    },
    [nodes, edges],
  );

  // Update search when term changes with debounce
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      performSearch(searchTerm);
    }, 150); // 150ms debounce

    return () => clearTimeout(timeoutId);
  }, [searchTerm, performSearch]);

  // Handle input change
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  // Handle result selection
  const handleResultSelect = useCallback(
    (result: SearchResult) => {
      // Just zoom to the element without triggering selection
      onZoomToElement(result.id, result.type);

      // Show a brief toast notification
      toast.success(`Found ${result.type}: ${result.label}`, {
        duration: 1500,
      });

      setSearchTerm("");
      setIsOpen(false);
      setSelectedIndex(-1);
    },
    [onZoomToElement],
  );

  // Handle keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen || searchResults.length === 0) return;

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setSelectedIndex((prev) => (prev < searchResults.length - 1 ? prev + 1 : 0));
        break;
      case "ArrowUp":
        e.preventDefault();
        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : searchResults.length - 1));
        break;
      case "Enter":
        e.preventDefault();
        if (selectedIndex >= 0 && selectedIndex < searchResults.length) {
          handleResultSelect(searchResults[selectedIndex]);
        }
        break;
      case "Escape":
        setSearchTerm("");
        setIsOpen(false);
        setSelectedIndex(-1);
        inputRef.current?.blur();
        break;
    }
  };

  // Clear search
  const clearSearch = () => {
    setSearchTerm("");
    setIsOpen(false);
    setSelectedIndex(-1);
    inputRef.current?.focus();
  };

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
        setSelectedIndex(-1);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <div className="relative" ref={dropdownRef}>
      <div className="relative">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
        <Input
          ref={inputRef}
          type="text"
          placeholder="Search nodes and edges..."
          value={searchTerm}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          onFocus={() => searchResults.length > 0 && setIsOpen(true)}
          className={`pl-10 pr-10 ${inputWidthClass}`}
        />
        {searchTerm && (
          <Button
            variant="ghost"
            size="sm"
            onClick={clearSearch}
            className="absolute right-1 top-1/2 transform -translate-y-1/2 h-6 w-6 p-0"
          >
            <X className="h-3 w-3" />
          </Button>
        )}
      </div>

      {/* Search Results Dropdown */}
      {isOpen && searchResults.length > 0 && (
        <Card className="absolute top-full left-0 right-0 mt-1 z-50 max-h-64 overflow-y-auto">
          <CardContent className="p-0">
            {searchResults.map((result, index) => (
              <div
                key={`${result.type}-${result.id}`}
                className={`flex items-center gap-3 p-3 cursor-pointer hover:bg-muted/50 transition-colors ${
                  index === selectedIndex ? "bg-muted" : ""
                }`}
                onClick={() => handleResultSelect(result)}
              >
                <div
                  className={`w-2 h-2 rounded-full ${
                    result.type === "node" ? "bg-blue-500" : "bg-green-500"
                  }`}
                />
                <div className="flex-1 min-w-0">
                  <div className="font-medium text-sm truncate">{result.label}</div>
                  {result.description && (
                    <div className="text-xs text-muted-foreground truncate">
                      {result.description}
                    </div>
                  )}
                </div>
                <div className="text-xs text-muted-foreground capitalize">{result.type}</div>
              </div>
            ))}
          </CardContent>
        </Card>
      )}

      {/* No Results */}
      {isOpen && searchResults.length === 0 && searchTerm && (
        <Card className="absolute top-full left-0 right-0 mt-1 z-50">
          <CardContent className="p-3 text-center text-sm text-muted-foreground">
            No results found for "{searchTerm}"
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default OntologySchemaSearchBar;
