import { PostHogService } from "./posthogService";

/**
 * Semantic product-usage events.
 *
 * One module owns every custom event name so reports stay consistent and names
 * don't drift across the codebase. Call sites stay one line: `trackConceptRun({...})`.
 * All events flow through PostHogService.captureEvent, which no-ops when PostHog
 * is disabled at build time.
 *
 * These replace the old autocapture / user_click noise: instead of "clicked
 * button with text X" we record what the user actually did (ran a concept,
 * created an ontology, opened the assistant, opened an app, ...).
 */

/**
 * Collapse id-like path segments to ":id" so a route groups cleanly in reports
 * (e.g. /editor/prometheux/demo/213322beb48 -> /editor/:id/:id/:id). Bounds the
 * cardinality of the `route` property on pageviews.
 */
export function normalizeRoute(pathname: string): string {
  const collapsed = pathname
    .split("/")
    .map((seg) => {
      if (!seg) return seg;
      if (/^\d+$/.test(seg)) return ":id";
      if (/^[0-9a-f]{8,}$/i.test(seg)) return ":id";
      if (/^[0-9a-f-]{16,}$/i.test(seg)) return ":id";
      return seg;
    })
    .join("/");
  return collapsed || "/";
}

export function trackPageview(pathname: string): void {
  PostHogService.captureEvent("$pageview", {
    route: normalizeRoute(pathname),
    path: pathname,
  });
}

export interface ConceptRunProps {
  runMode: "cell" | "workflow";
  conceptType?: string;
  ontologyId?: string;
}
export function trackConceptRun(props: ConceptRunProps): void {
  PostHogService.captureEvent("concept_run", {
    run_mode: props.runMode,
    concept_type: props.conceptType,
    ontology_id: props.ontologyId,
  });
}

