import { Waypoints, X } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import type { ConceptOutput } from "../../hooks/useConceptOutputs";
import {
  assignConceptGraphRole,
  clearConceptGraphRole,
  conceptGraphReady,
  roleForColumn,
} from "../../model.utils";
import type { ConceptGraphRole, ConceptGraphRoles } from "../../types";
import { FieldRolePicker } from "./FieldRolePicker";

interface GraphActionRowProps {
  ready: boolean;
  hasAnyRole: boolean;
  isActiveGraph: boolean;
  isBusy: boolean;
  buttonLabel: string;
  onShowGraph: () => void;
  onClearRoles: () => void;
}

export function GraphActionRow({
  ready,
  hasAnyRole,
  isActiveGraph,
  isBusy,
  buttonLabel,
  onShowGraph,
  onClearRoles,
}: GraphActionRowProps) {
  return (
    <div className="space-y-1.5">
      {!ready && (
        <p className="text-[10px] text-muted-foreground">
          Assign a source and a target column to graph this output.
        </p>
      )}
      <div className="flex gap-1.5">
        <Button
          size="sm"
          variant={isActiveGraph ? "secondary" : "default"}
          className="flex-1 h-7 text-xs gap-1.5"
          disabled={!ready || isBusy}
          onClick={onShowGraph}
        >
          <Waypoints className="h-3 w-3" />
          {buttonLabel}
        </Button>
        {hasAnyRole && (
          <Button
            size="sm"
            variant="ghost"
            className="h-7 text-xs gap-1 px-2 text-muted-foreground hover:text-foreground"
            disabled={isBusy}
            onClick={onClearRoles}
            title="Clear column assignments"
          >
            <X className="h-3 w-3" />
            Clear
          </Button>
        )}
      </div>
    </div>
  );
}

export function hasAnyRoleAssigned(roles: ConceptGraphRoles): boolean {
  return Boolean(roles.source_column || roles.target_column || roles.edge_label_column);
}

interface ConceptOutputSectionProps {
  output: ConceptOutput;
  roles: ConceptGraphRoles;
  isActiveGraph: boolean;
  isBusy: boolean;
  buttonLabel: string;
  onRolesChange: (roles: ConceptGraphRoles) => void;
  onShowGraph: () => void;
}

/**
 * A concept's output table: the column list with role pickers, followed by
 * the graph actions. Rendered flat inside the card (no inner box). When the
 * shown output is a derived rule head (not the concept's own predicate), a
 * slim label names it.
 */
export function ConceptOutputSection({
  output,
  roles,
  isActiveGraph,
  isBusy,
  buttonLabel,
  onRolesChange,
  onShowGraph,
}: ConceptOutputSectionProps) {
  const columnNames = Object.keys(output.columns);

  const handleAssign = (column: string, role: ConceptGraphRole) =>
    onRolesChange(assignConceptGraphRole(roles, role, column));
  const handleClear = (column: string) => onRolesChange(clearConceptGraphRole(roles, column));

  return (
    <div>
      {!output.isPrimary && (
        <p className="px-3 pt-1.5 text-[10px] text-muted-foreground">
          Output: <span className="font-medium text-foreground/80">{output.predicate}</span>
        </p>
      )}
      <div className="divide-y divide-border/50">
        {columnNames.map((column) => (
          <div key={column} className="flex items-center gap-2 px-3 py-1 text-xs">
            <span className="flex-1 min-w-0 truncate text-foreground/80" title={column}>
              {column}
            </span>
            <span className="w-16 flex-shrink-0 text-right font-mono text-[10px] text-muted-foreground">
              {output.columns[column]}
            </span>
            <span className="w-14 flex-shrink-0 flex justify-end">
              <FieldRolePicker
                role={roleForColumn(roles, column)}
                onAssign={(role) => handleAssign(column, role)}
                onClear={() => handleClear(column)}
              />
            </span>
          </div>
        ))}
      </div>
      <div className="px-3 py-2 border-t border-border/50">
        <GraphActionRow
          ready={conceptGraphReady(roles)}
          hasAnyRole={hasAnyRoleAssigned(roles)}
          isActiveGraph={isActiveGraph}
          isBusy={isBusy}
          buttonLabel={buttonLabel}
          onShowGraph={onShowGraph}
          onClearRoles={() => onRolesChange({})}
        />
      </div>
    </div>
  );
}
