import type { AppDefinition } from "../schema/appDefinition.types";
import { isLegacyWidget } from "../schema/appDefinition.types";
import type { EditorSelection } from "./appEditor.types";
import { mapPage } from "./appEditorMutations";
import { removeFormField } from "./formFieldMutations";

/** Delete whatever the selection addresses; "app" and unknown ids are no-ops. */
export function removeSelected(
  definition: AppDefinition,
  selection: EditorSelection,
): AppDefinition {
  switch (selection.kind) {
    case "app":
      return definition;
    case "page":
      return {
        ...definition,
        pages: definition.pages.filter((page) => page.id !== selection.pageId),
      };
    case "section":
      return mapPage(definition, selection.pageId, (page) => ({
        ...page,
        sections: page.sections.filter((section) => section.id !== selection.sectionId),
      }));
    case "widget":
      return mapPage(definition, selection.pageId, (page) => ({
        ...page,
        sections: page.sections.map((section) =>
          section.id === selection.sectionId
            ? {
                ...section,
                widgets: section.widgets.filter(
                  (widget) => isLegacyWidget(widget) || widget.id !== selection.widgetId,
                ),
              }
            : section,
        ),
      }));
    case "input":
      return mapPage(definition, selection.pageId, (page) => ({
        ...page,
        inputs: page.inputs.filter((input) => input.id !== selection.inputId),
      }));
    case "formField":
      return removeFormField(
        definition,
        selection.pageId,
        selection.inputId,
        selection.sectionIndex,
        selection.fieldId,
      );
    case "runGroup":
      return mapPage(definition, selection.pageId, (page) => ({
        ...page,
        runGroups: page.runGroups.filter((group) => group.id !== selection.groupId),
      }));
    default: {
      const _exhaustive: never = selection;
      throw new Error(`Unhandled selection: ${JSON.stringify(_exhaustive)}`);
    }
  }
}
