import { useCallback, useEffect } from "react";
import { useMachineStatusContext } from "@/features/compute/context/MachineStatusContext";
import { useStartMachineStore } from "@/features/compute/store/startMachineStore";

interface UseRequireComputeReturn {
  /** True when a pool machine or Databricks cluster is currently running. */
  hasRunningMachine: boolean;
  /**
   * Call before any compute-dependent API request. Returns `true` when compute is
   * already running and the caller may proceed. When nothing is running it opens
   * the global start-machine modal (so the user can pick and start a machine) and
   * returns `false`, signalling the caller to abort the action.
   */
  ensureCompute: () => boolean;
}

/**
 * Reusable compute guard, shared by any page that triggers compute-dependent API
 * calls (lineage editor, dashboards, …). It mirrors the project-editor "Run" guard:
 * detect whether compute is running and, if not, prompt the user via the global
 * start-machine modal instead of letting the request fail silently.
 *
 * Must be used within `MachineStatusProvider` (mounted at the app root).
 */
export function useRequireCompute(): UseRequireComputeReturn {
  const {
    hasRunningMachine,
    notRunningMachines,
    databricksClusters,
    fetchAllMachines,
    fetchDatabricksClusters,
  } = useMachineStatusContext();
  const openStartMachineModal = useStartMachineStore((s) => s.openModal);

  // Re-sync machine data on mount so the guard reflects machines started/stopped on
  // the Compute Management page during this session (covers SPA navigation away and back).
  useEffect(() => {
    fetchAllMachines();
    fetchDatabricksClusters();
  }, [fetchAllMachines, fetchDatabricksClusters]);

  const ensureCompute = useCallback(() => {
    if (hasRunningMachine) return true;
    const notRunningDatabricksClusters = databricksClusters.filter((c) => c.state !== "RUNNING");
    const hasStartableCompute =
      notRunningMachines.length > 0 || notRunningDatabricksClusters.length > 0;
    // No compute is configured at all (e.g. local/dev where jarvispy runs without
    // managed machines or Databricks clusters). Compute selection isn't applicable
    // here, so allow the run to proceed instead of silently blocking it with no
    // modal to act on. Only block (and prompt) when there is something to start.
    if (!hasStartableCompute) return true;
    openStartMachineModal();
    return false;
  }, [hasRunningMachine, notRunningMachines, databricksClusters, openStartMachineModal]);

  return { hasRunningMachine, ensureCompute };
}
