import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { listTeamShareGrants } from "../api";
import type { ShareError, TeamShareGrant } from "../types";

export const TEAM_GRANTS_KEY = ["share", "team-grants"] as const;
const grantsKey = (shareId: string) => [...TEAM_GRANTS_KEY, shareId] as const;

interface UseTeamShareGrantsOptions {
  shareId: string;
  // Defer the fetch until the "who's in" roster is actually opened.
  enabled?: boolean;
}

interface UseTeamShareGrantsReturn {
  grants: TeamShareGrant[];
  isLoading: boolean;
  error: ShareError | null;
  refresh: () => Promise<unknown>;
}

// Owner-only roster of members who have claimed a given team share. Lazy by
// default (enabled === false) so it only fires when the roster is expanded.
export function useTeamShareGrants({
  shareId,
  enabled = true,
}: UseTeamShareGrantsOptions): UseTeamShareGrantsReturn {
  const { session } = useAuth();
  const supabaseToken = session?.access_token ?? null;

  const query = useQuery<TeamShareGrant[], ShareError>({
    queryKey: grantsKey(shareId),
    queryFn: () => listTeamShareGrants(supabaseToken, shareId),
    enabled: enabled && Boolean(shareId && supabaseToken),
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  return {
    grants: query.data ?? [],
    isLoading: query.isLoading,
    error: query.error,
    refresh: query.refetch,
  };
}
