import { type UseQueryResult, useQuery } from "@tanstack/react-query";
import type { DashboardAppConfig } from "@/features/dashboards/dashboardConfigRegistry";
import { loadRemoteExport } from "./remoteLoader";

interface RemoteConfigModule {
  default: DashboardAppConfig;
}

// Loads a federated app's exposed "./config" (the same DashboardAppConfig the app
// declares locally). The host reads this BEFORE mounting the app so it can seed project
// context and auto-start compute, exactly as the build-time registry did.
export function useRemoteAppConfig(
  dashboardId: string,
  remoteUrl: string,
): UseQueryResult<DashboardAppConfig> {
  return useQuery({
    queryKey: ["remote-app-config", dashboardId, remoteUrl],
    queryFn: async () => {
      const mod = await loadRemoteExport<RemoteConfigModule>(dashboardId, remoteUrl, "config");
      return mod.default;
    },
    staleTime: Number.POSITIVE_INFINITY,
    retry: 1,
  });
}
