import type { ContextEdge, ContextNote, CreateContextEdgeRequest } from "../types";
import { conceptNodeId } from "../types";
import { chunkIndexOf, linkDisplayTitle } from "./notesModel";

/** `[[Title]]` — wikilinks are an authoring gesture; storage is context_edges.
 *  `[[concept:name]]` targets a concept of the note's own project vault. */
const WIKILINK_PATTERN = /\[\[([^\][\n]+?)\]\]/g;

export const CONCEPT_WIKILINK_PREFIX = "concept:";

export function parseWikilinkTitles(text: string): string[] {
  const titles = new Set<string>();
  for (const match of (text ?? "").matchAll(WIKILINK_PATTERN)) {
    const title = match[1].trim();
    if (title && !title.toLowerCase().startsWith(CONCEPT_WIKILINK_PREFIX)) titles.add(title);
  }
  return [...titles];
}

/** Concept names referenced as `[[concept:name]]`. */
export function parseConceptWikilinks(text: string): string[] {
  const names = new Set<string>();
  for (const match of (text ?? "").matchAll(WIKILINK_PATTERN)) {
    const title = match[1].trim();
    if (!title.toLowerCase().startsWith(CONCEPT_WIKILINK_PREFIX)) continue;
    const name = title.slice(CONCEPT_WIKILINK_PREFIX.length).trim();
    if (name) names.add(name);
  }
  return [...names];
}

function buildTitleIndex(candidates: ContextNote[]): Map<string, ContextNote> {
  const index = new Map<string, ContextNote>();
  // Earlier entries win; callers pass newest-first lists, so ambiguous
  // titles resolve to the most recent note. Documents are indexed by
  // filename, and `[[filename]]` resolves to the document's first chunk.
  const standalone = candidates.filter((note) => note.kind !== "document_chunk");
  const chunksFirstToLast = candidates
    .filter((note) => note.kind === "document_chunk")
    .sort((a, b) => chunkIndexOf(a.source_meta) - chunkIndexOf(b.source_meta));
  for (const note of [...standalone, ...chunksFirstToLast]) {
    const key = linkDisplayTitle(note).toLowerCase();
    if (!index.has(key)) index.set(key, note);
  }
  return index;
}

export interface WikilinkSyncPlan {
  /** Note ids to create `relates_to` edges to (created_by='wikilink'). */
  createTargetIds: string[];
  /** Concept node ids ("<projectId>:<name>") to create edges to. */
  createConceptKeys: string[];
  /** Existing wikilink-born edge ids whose text anchor was removed. */
  deleteEdgeIds: string[];
}

/**
 * Sync rule: wikilink-born edges track their text anchor — removing the
 * `[[...]]` text removes the edge. Edges created from the graph UI or by
 * the agent (created_by != 'wikilink') are never touched here.
 *
 * `[[concept:name]]` resolves within the note's own project (`projectId`);
 * global-vault notes have no project, so concept wikilinks are inert there.
 * The concept doesn't need to exist yet — a dangling annotation surfaces
 * once a concept with that name is created.
 */
/** Edge write primitives the sync executor runs against — React Query
 *  mutations or direct API calls, whichever the caller has. */
export interface WikilinkEdgeWriter {
  createEdge: (edge: CreateContextEdgeRequest) => Promise<unknown>;
  removeEdge: (edgeId: string) => Promise<unknown>;
}

/**
 * Plan and execute the wikilink edge sync after a note's text was saved.
 *
 * Edge failures never reject: the note save itself already succeeded, so a
 * failed edge write must not fail the whole action. Callers that want to
 * surface failures can inspect the returned settled results.
 */
export async function executeWikilinkEdgeSync(
  noteId: string,
  newText: string,
  candidates: ContextNote[],
  existingEdges: ContextEdge[],
  ontologyId: string | null | undefined,
  writer: WikilinkEdgeWriter,
): Promise<PromiseSettledResult<unknown>[]> {
  const plan = planWikilinkEdgeSync(noteId, newText, candidates, existingEdges, ontologyId);
  const creates = plan.createTargetIds.map((dstId) =>
    writer.createEdge({
      src_type: "note",
      src_id: noteId,
      dst_type: "note",
      dst_id: dstId,
      relation: "relates_to",
      created_by: "wikilink",
    }),
  );
  const conceptCreates = plan.createConceptKeys.map((conceptKey) =>
    writer.createEdge({
      src_type: "note",
      src_id: noteId,
      dst_type: "concept",
      dst_id: conceptKey,
      relation: "relates_to",
      created_by: "wikilink",
    }),
  );
  const deletes = plan.deleteEdgeIds.map((edgeId) => writer.removeEdge(edgeId));
  return Promise.allSettled([...creates, ...conceptCreates, ...deletes]);
}

export function planWikilinkEdgeSync(
  noteId: string,
  newText: string,
  candidates: ContextNote[],
  existingEdges: ContextEdge[],
  ontologyId?: string | null,
): WikilinkSyncPlan {
  const titleIndex = buildTitleIndex(candidates);
  const linkedIds = new Set(
    parseWikilinkTitles(newText)
      .map((title) => titleIndex.get(title.toLowerCase())?.id)
      .filter((id): id is string => Boolean(id) && id !== noteId),
  );
  const linkedConceptKeys = new Set(
    ontologyId ? parseConceptWikilinks(newText).map((name) => conceptNodeId(ontologyId, name)) : [],
  );

  const ownWikilinkEdges = existingEdges.filter(
    (edge) =>
      edge.created_by === "wikilink" &&
      edge.src_type === "note" &&
      edge.src_id === noteId &&
      (edge.dst_type === "note" || edge.dst_type === "concept"),
  );
  const ownNoteEdges = ownWikilinkEdges.filter((edge) => edge.dst_type === "note");
  const ownConceptEdges = ownWikilinkEdges.filter((edge) => edge.dst_type === "concept");
  const alreadyLinkedIds = new Set(ownNoteEdges.map((edge) => edge.dst_id));
  const alreadyLinkedConcepts = new Set(ownConceptEdges.map((edge) => edge.dst_id));

  return {
    createTargetIds: [...linkedIds].filter((id) => !alreadyLinkedIds.has(id)),
    createConceptKeys: [...linkedConceptKeys].filter((key) => !alreadyLinkedConcepts.has(key)),
    deleteEdgeIds: [
      ...ownNoteEdges.filter((edge) => !linkedIds.has(edge.dst_id)),
      ...ownConceptEdges.filter((edge) => !linkedConceptKeys.has(edge.dst_id)),
    ].map((edge) => edge.id),
  };
}
