import { useQueryClient } from "@tanstack/react-query";
import { AppWindow, Plus } from "lucide-react";
import type React from "react";
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import {
  DashboardClient,
  type DashboardListItem,
} from "@/features/dynamic-dashboard/api/DashboardClient";
import { DashboardCard } from "@/features/dynamic-dashboard/pages/components/DashboardCard";
import {
  DeleteAppDialog,
  type DeleteAppTarget,
} from "@/features/dynamic-dashboard/pages/components/DeleteAppDialog";
import { Button } from "@/shared/components/ui/button";
import { useResolvedAppMeta } from "../../remotes/useResolvedAppMeta";
import { AppCard } from "./AppCard";

const client = new DashboardClient();

interface AppsCatalogProps {
  showDynamic: boolean;
  canEdit: boolean;
  dynamicApps: DashboardListItem[];
}

/**
 * One grid, two sources: dynamic apps first, federated apps after — same
 * card language, no visible distinction (ADR D10). Federated apps are not
 * converted or wrapped; they still load as Module Federation remotes.
 */
export function AppsCatalog({ showDynamic, canEdit, dynamicApps }: AppsCatalogProps) {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const visibleApps = usePermissionsStore((state) => state.visibleApps);
  const appMeta = useResolvedAppMeta(visibleApps);
  const dashboardsRevision = useCodeAssistantStore((s) => s.dashboardsRevision);
  const [deleteTarget, setDeleteTarget] = useState<DeleteAppTarget | null>(null);

  // Refresh the list whenever the AI assistant creates or deletes an app.
  useEffect(() => {
    if (dashboardsRevision === 0) return;
    queryClient.invalidateQueries({ queryKey: ["all-dashboards"] });
  }, [dashboardsRevision, queryClient]);

  const handleExport = async (e: React.MouseEvent, item: DashboardListItem) => {
    e.preventDefault();
    e.stopPropagation();
    try {
      const full = await client.getDashboard(item.ontologyId, item.id);
      if (!full) {
        toast.error("App not found");
        return;
      }
      // v2 definitions carry their project per page, not top-level — stamp the
      // storage project so the file is self-contained for import.
      const exported = { ...full, ontologyId: full.ontologyId || item.ontologyId };
      const blob = new Blob([JSON.stringify(exported, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${full.name.replace(/\s+/g, "_")}.json`;
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      toast.error("Failed to export the app");
    }
  };

  const handleDeleteClick = (e: React.MouseEvent, item: DashboardListItem) => {
    e.preventDefault();
    e.stopPropagation();
    setDeleteTarget({ ontologyId: item.ontologyId, id: item.id, name: item.name });
  };

  const handleDeleted = () => {
    queryClient.invalidateQueries({ queryKey: ["all-dashboards"] });
  };

  const isEmpty = (!showDynamic || dynamicApps.length === 0) && visibleApps.length === 0;

  if (isEmpty) {
    return (
      <div className="flex flex-col items-center justify-center h-full gap-4 text-muted-foreground">
        <div className="w-16 h-16 rounded-2xl bg-secondary flex items-center justify-center">
          <AppWindow className="h-8 w-8 opacity-40" />
        </div>
        <div className="text-center">
          <p className="text-sm font-medium">No apps yet</p>
          <p className="text-xs text-muted-foreground mt-1">
            {canEdit
              ? "Create your first app to get started."
              : "You don't have access to any apps yet."}
          </p>
        </div>
        {canEdit && (
          <Button
            variant="outline"
            size="sm"
            onClick={() => navigate("/apps/new/edit")}
            className="gap-1.5"
          >
            <Plus className="h-3.5 w-3.5" /> New App
          </Button>
        )}
      </div>
    );
  }

  return (
    <div className="px-8 py-6">
      <div className="grid grid-cols-3 gap-4">
        {showDynamic &&
          dynamicApps.map((d) => (
            <DashboardCard
              key={`${d.ontologyId}-${d.id}`}
              item={d}
              onEdit={
                canEdit
                  ? (e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      navigate(`/apps/${d.ontologyId}/${d.id}/edit`);
                    }
                  : undefined
              }
              onExport={(e) => handleExport(e, d)}
              onDelete={canEdit ? (e) => handleDeleteClick(e, d) : undefined}
            />
          ))}
        {visibleApps.map((app) => {
          const meta = appMeta[app.id];
          return (
            <AppCard
              key={app.id}
              id={app.id}
              name={meta?.name ?? app.name}
              description={meta?.description ?? ""}
            />
          );
        })}
      </div>
      <DeleteAppDialog
        target={deleteTarget}
        onOpenChange={(open) => {
          if (!open) setDeleteTarget(null);
        }}
        onDeleted={handleDeleted}
      />
    </div>
  );
}
