import { Filter, X } from "lucide-react";

interface LineageFocusBannerProps {
  conceptName: string;
  onClear: () => void;
}

/**
 * Pill shown while the lineage is isolated to a single concept's upstream
 * dependency slice. Clearing returns to the full lineage.
 */
export function LineageFocusBanner({ conceptName, onClear }: LineageFocusBannerProps) {
  return (
    <div className="glass-card flex items-center gap-2 rounded-md border border-border bg-card/90 py-1.5 pl-2.5 pr-1.5 shadow-md backdrop-blur">
      <Filter className="h-3.5 w-3.5 flex-shrink-0 text-primary" />
      <span className="text-xs text-muted-foreground">
        Focused view: <span className="font-medium text-foreground">{conceptName}</span>
      </span>
      <button
        type="button"
        onClick={onClear}
        className="ml-1 flex items-center gap-1 rounded px-1.5 py-0.5 text-xs font-medium text-primary transition-colors hover:bg-primary/10"
      >
        <X className="h-3 w-3" />
      </button>
    </div>
  );
}
