import { Settings } from "lucide-react";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import SettingsPanel from "@/features/settings/components/SettingsPanel";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import SidePanel from "@/shared/components/layout/SidePanel";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";

const SettingsPage = () => {
  const navigate = useNavigate();
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  const marginClass = sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0";

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="settings"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-col flex-1 ${marginClass} overflow-hidden transition-all duration-200`}
      >
        <PageHeader title="Settings" icon={Settings} />
        <div className="flex-1 overflow-y-auto min-h-0">
          <SettingsPanel settingsEnabled={true} onBack={() => navigate(-1)} />
        </div>
      </div>
    </div>
  );
};

export default SettingsPage;
