import { ChevronDown, ChevronRight, Plus, Trash2 } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import type { AppConcept } from "../../api/ConceptClient";
import type { DashboardPage, DashboardSection } from "../../types";
import { SectionEditor } from "./SectionEditor";

export interface PageEditorProps {
  page: DashboardPage;
  concepts: AppConcept[];
  knownColumnsMap: Record<string, string[]>;
  onChange: (p: DashboardPage) => void;
  onRemove: () => void;
}

export function PageEditor({
  page,
  concepts,
  knownColumnsMap,
  onChange,
  onRemove,
}: PageEditorProps) {
  const [expanded, setExpanded] = useState(true);

  const addSection = () => {
    onChange({
      ...page,
      sections: [...page.sections, { id: crypto.randomUUID(), layout: "single", widgets: [] }],
    });
  };

  const updateSection = (id: string, s: DashboardSection) => {
    onChange({ ...page, sections: page.sections.map((ss) => (ss.id === id ? s : ss)) });
  };

  const removeSection = (id: string) => {
    onChange({ ...page, sections: page.sections.filter((ss) => ss.id !== id) });
  };

  const sectionCount = page.sections.length;

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center gap-2 px-3 py-2 bg-secondary/50">
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          className="text-muted-foreground hover:text-foreground"
        >
          {expanded ? (
            <ChevronDown className="h-3.5 w-3.5" />
          ) : (
            <ChevronRight className="h-3.5 w-3.5" />
          )}
        </button>

        <Input
          value={page.label}
          onChange={(e) => onChange({ ...page, label: e.target.value })}
          placeholder="Page label"
          className="h-7 text-xs flex-1 font-medium"
        />

        <span className="text-[10px] text-muted-foreground font-mono whitespace-nowrap">
          {sectionCount} section{sectionCount !== 1 ? "s" : ""}
        </span>

        <Button
          variant="ghost"
          size="iconSm"
          onClick={onRemove}
          className="text-muted-foreground hover:text-destructive"
        >
          <Trash2 className="h-3.5 w-3.5" />
        </Button>
      </div>

      {expanded && (
        <div className="p-3 flex flex-col gap-2">
          {page.sections.map((section) => (
            <SectionEditor
              key={section.id}
              section={section}
              concepts={concepts}
              knownColumnsMap={knownColumnsMap}
              onChange={(s) => updateSection(section.id, s)}
              onRemove={() => removeSection(section.id)}
            />
          ))}
          {page.sections.length === 0 && (
            <p className="text-xs text-muted-foreground">No sections yet.</p>
          )}
          <Button
            variant="outline"
            size="sm"
            onClick={addSection}
            className="gap-1.5 h-7 text-xs self-start"
          >
            <Plus className="h-3 w-3" /> Add section
          </Button>
        </div>
      )}
    </div>
  );
}
