import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { supabase } from "@/shared/integrations/supabase/client";
import { BaseClient } from "@/shared/lib/BaseClient";
import { EngineBusyError, isEngineBusyPayload } from "@/shared/lib/engineBusy";
import type { ColumnFilterValue, OrderByItem } from "../components/outputs/table/tableOutput.types";
import { buildWsUrl, parseFetchResponse } from "./conceptClient.utils";

export interface AppConceptDetail {
  predicate_name: string;
  param_annotations?: string;
  fields?: Record<string, string>;
  definition?: string;
  is_populated?: boolean;
  row_count?: number;
  [key: string]: unknown;
}

export interface AppConcept {
  predicate_name: string;
  description?: string;
  concept_type?: string;
  is_populated?: boolean;
  row_count?: number;
  fields?: Record<string, string>;
  concept_details?: AppConceptDetail[];
  parsed?: { code?: string; binds?: { input: unknown[]; output: unknown[] } };
}

/** Normalised result set returned by both the stream path and the /fetch path. */
export interface FetchResult {
  columnNames: string[];
  rows: unknown[][];
  totalCount: number;
  page: number;
  pageSize: number;
  totalPages: number;
  hasNext: boolean;
  orderBy?: OrderByItem[];
  searchState?: {
    searchTerm: string;
    columnFilters?: Record<number, ColumnFilterValue>;
  };
}

export interface EvaluationResults {
  resultSet: Record<string, unknown[][]>;
  columnNames: Record<string, string[]>;
  types?: Record<string, string[]>;
  elapsedTime?: number;
  elapsedTimeMs?: number;
}

export interface RunOptions {
  /** Vadalog ground atoms prepended to the run (dynamic-app form records). */
  preambleFacts?: string;
}

export interface ConceptStatusEvent {
  type?: string;
  concept?: string;
  status?: "running" | "success" | "error" | "skipped";
  error?: string;
  order?: string[];
  total?: number;
}

export class ConceptClient extends BaseClient {
  async listConcepts(ontologyId: string, scope = "user"): Promise<AppConcept[]> {
    const response = await this.get(`/concepts/${ontologyId}/list?scope=${scope}`);
    if (response.status === "success" && Array.isArray(response.data)) {
      return response.data as AppConcept[];
    }
    throw new Error(response.message || "Failed to load concepts");
  }

  /**
   * Run a concept via WebSocket streaming.
   * Returns the full EvaluationResults so callers can check which predicates
   * were computed and extract each output's data directly.
   * Set persistOutputs=true when output concepts differ from the input (chain mode).
   */
  async runConceptWithParams(
    ontologyId: string,
    conceptName: string,
    params: Record<string, unknown>,
    scope = "user",
    persistOutputs = false,
    onEvent?: (event: ConceptStatusEvent) => void,
    options?: RunOptions,
  ): Promise<EvaluationResults> {
    const payload: Record<string, unknown> = {
      params,
      scope,
      force_rerun: true,
      persist_outputs: persistOutputs,
    };
    if (options?.preambleFacts) payload.preamble_facts = options.preambleFacts;

    const {
      data: { session },
    } = await supabase.auth.getSession();
    const token = PROMETHEUX_CONFIG.AUTH_TOKEN || "";
    const supabaseToken = session?.access_token || "";

    const qp = new URLSearchParams({ token, x_supabase_token: supabaseToken });
    const endpoint = `/concepts/${ontologyId}/run-stream/${encodeURIComponent(conceptName)}`;
    const wsUrl = buildWsUrl(`${endpoint}?${qp.toString()}`);

    return new Promise<EvaluationResults>((resolve, reject) => {
      const ws = new WebSocket(wsUrl);
      let finalResponse: Record<string, unknown> | null = null;
      let settled = false;

      const settle = (fn: () => void) => {
        if (!settled) {
          settled = true;
          fn();
        }
      };

      ws.onopen = () => {
        ws.send(JSON.stringify(payload));
      };

      ws.onmessage = (event) => {
        try {
          const msg = JSON.parse(event.data);
          if (msg.event === "ping") return;
          if (msg.event === "concept_status") {
            if (onEvent) onEvent(msg.data as ConceptStatusEvent);
          } else if (msg.event === "complete") {
            finalResponse = msg.data as Record<string, unknown>;
          } else if (msg.event === "error") {
            const errData = (msg.data || {}) as Record<string, unknown>;
            // Engine-busy becomes a typed error so the run-group runtime can
            // wait-and-retry instead of surfacing a red group error.
            const runError = isEngineBusyPayload(errData)
              ? new EngineBusyError((errData.message as string) || undefined)
              : new Error(
                  (errData.message as string) ||
                    (errData.data as Record<string, string>)?.errorMessage ||
                    "Execution error",
                );
            settle(() => reject(runError));
            ws.close();
          }
        } catch {
          // Non-JSON message, ignore
        }
      };

      ws.onclose = () => {
        if (finalResponse) {
          if (finalResponse.status === "error") {
            const d = finalResponse.data as Record<string, unknown> | undefined;
            settle(() =>
              reject(
                new Error(
                  (d?.errorMessage as string) ||
                    (finalResponse!.message as string) ||
                    "Execution failed",
                ),
              ),
            );
          } else {
            const data = finalResponse.data as Record<string, unknown> | undefined;
            settle(() =>
              resolve(
                (data?.evaluation_results ?? {
                  resultSet: {},
                  columnNames: {},
                }) as EvaluationResults,
              ),
            );
          }
        } else {
          settle(() => reject(new Error("WebSocket closed without a complete event")));
        }
      };

      ws.onerror = () => {
        settle(() => reject(new Error("WebSocket connection error")));
      };
    });
  }

  /** Extract one predicate's data from an EvaluationResults into a FetchResult. */
  extractFromEvalResults(evalResults: EvaluationResults, conceptName: string): FetchResult | null {
    const resultSet = evalResults.resultSet || {};
    const colNames = evalResults.columnNames || {};

    const key =
      Object.keys(resultSet).find((k) => k.toLowerCase() === conceptName.toLowerCase()) ?? null;

    if (!key) return null;

    const rows = resultSet[key] ?? [];
    return {
      columnNames: colNames[key] ?? [],
      rows,
      totalCount: rows.length,
      page: 1,
      pageSize: rows.length,
      totalPages: 1,
      hasNext: false,
    };
  }

  /** Fetch paginated results for an already-populated concept via /fetch. */
  async fetchConceptData(
    ontologyId: string,
    conceptName: string,
    scope = "user",
    page = 1,
    pageSize = 10,
    orderBy?: OrderByItem[],
  ): Promise<FetchResult> {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    const url = `/concepts/${ontologyId}/fetch?output_predicate=${encodeURIComponent(conceptName)}&project_scope=${scope}`;
    const body: { page: number; page_size: number; order_by?: string } = {
      page,
      page_size: pageSize,
    };
    if (orderBy && orderBy.length > 0) {
      body.order_by = orderBy.map((o) => `${o.position}:${o.direction}`).join(",");
    }
    const response = await this.post(url, body, undefined, {
      "X-Supabase-Token": session?.access_token || "null",
    });

    if (response.status !== "success") {
      throw new Error(response.message || response.error || "Failed to fetch concept data");
    }

    const d = response.data as Record<string, unknown>;
    return parseFetchResponse({ data: d, page, pageSize, orderBy });
  }

  /**
   * Search a populated concept via the unified /fetch endpoint. Supports either a
   * global searchTerm or column-specific filters with operators (and optional ordering).
   */
  async searchConceptData(
    ontologyId: string,
    conceptName: string,
    scope: string,
    searchTerm: string | undefined,
    columnFilters: Record<number, ColumnFilterValue> | undefined,
    page: number,
    pageSize: number,
    orderBy?: OrderByItem[],
  ): Promise<FetchResult> {
    const {
      data: { session },
    } = await supabase.auth.getSession();

    const hasColumnFilters = !!columnFilters && Object.keys(columnFilters).length > 0;
    const trimmedTerm = searchTerm?.trim() ?? "";
    const body: {
      page: number;
      page_size: number;
      order_by?: string;
      search_term?: string;
      column_filters?: Array<{ position: number; value: string; operator?: string }>;
    } = { page, page_size: pageSize };
    if (orderBy && orderBy.length > 0) {
      body.order_by = orderBy.map((o) => `${o.position}:${o.direction}`).join(",");
    }
    if (trimmedTerm && !hasColumnFilters) {
      body.search_term = trimmedTerm;
    }
    if (hasColumnFilters) {
      body.column_filters = Object.entries(columnFilters!).map(([position, cf]) => ({
        position: parseInt(position, 10),
        value: cf.value,
        ...(cf.operator !== "contains" ? { operator: cf.operator } : {}),
      }));
    }

    const url = `/concepts/${ontologyId}/fetch?output_predicate=${encodeURIComponent(conceptName)}&project_scope=${scope}`;
    const response = await this.post(url, body, undefined, {
      "X-Supabase-Token": session?.access_token || "null",
    });

    if (response.status !== "success") {
      throw new Error(response.message || response.error || "Failed to search concept data");
    }

    const d = response.data as Record<string, unknown>;
    return parseFetchResponse({
      data: d,
      page,
      pageSize,
      orderBy,
      searchState: {
        searchTerm: trimmedTerm,
        columnFilters: hasColumnFilters ? columnFilters : undefined,
      },
    });
  }
}
