const TEMPLATE_RE = /^\{\{\s*([A-Za-z0-9_.]+)\s*\}\}$/;

/** Returns the context key referenced by a "{{key}}" template, or null. */
export function templateRef(template: string): string | null {
  const match = TEMPLATE_RE.exec(template);
  return match ? match[1] : null;
}

/**
 * Resolve a context reference. Direct keys win ("formId.fieldId" is stored
 * flat); otherwise dotted refs traverse into record values — e.g.
 * "selectedOrder.orderid" reads the "orderid" column of a published
 * row-selection record.
 */
export function resolveRef(ref: string, values: Record<string, unknown>): unknown {
  if (ref in values) return values[ref];
  const [root, ...path] = ref.split(".");
  let current: unknown = values[root];
  for (const key of path) {
    if (current === null || typeof current !== "object") return undefined;
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}

/**
 * Resolve a binding template against the tab context: "{{key}}" → the context
 * value (with dotted-path traversal), anything else → the literal string.
 */
export function resolveTemplate(template: string, values: Record<string, unknown>): unknown {
  const ref = templateRef(template);
  return ref ? resolveRef(ref, values) : template;
}

/** All context keys referenced by a group's params/facts bindings. */
export function collectBindingRefs(bindings: Array<Record<string, string> | undefined>): string[] {
  return bindings
    .flatMap((binding) => Object.values(binding ?? {}))
    .map(templateRef)
    .filter((ref): ref is string => ref !== null);
}
