import { createLocalCache } from "@/shared/utils/createLocalCache";

const SKIP_KEY = "company-onboarding-skipped";
const ONE_YEAR_MS = 365 * 24 * 60 * 60 * 1000;
const SCHEMA_VERSION = 1;

interface SkipPayload {
  skippedAt: number;
}

const cache = createLocalCache<SkipPayload>(SKIP_KEY, ONE_YEAR_MS, SCHEMA_VERSION);

export const companyOnboardingSkip = {
  isSkipped(userId: string): boolean {
    return cache.get(userId) !== null;
  },
  markSkipped(userId: string): void {
    cache.set(userId, { skippedAt: Date.now() });
  },
  clear(): void {
    cache.clear();
  },
};
