import type { AuthMFAListFactorsResponse, Factor } from "@supabase/supabase-js";
import { useCallback, useEffect, useState } from "react";
import { generateRecoveryCodes, hashRecoveryCode } from "@/features/auth/utils/recoveryCodes";
import { supabase } from "@/shared/integrations/supabase/client";

export interface MfaEnrollment {
  factorId: string;
  qrCode: string;
  secret: string;
  uri: string;
}

export interface UseMfaReturn {
  factors: Factor[];
  verifiedFactor: Factor | null;
  isLoading: boolean;
  error: string | null;
  refreshFactors: () => Promise<void>;
  enrollTotp: (friendlyName?: string) => Promise<MfaEnrollment>;
  verifyEnrollment: (factorId: string, code: string) => Promise<void>;
  cancelEnrollment: (factorId: string) => Promise<void>;
  unenroll: (factorId: string) => Promise<void>;
  issueRecoveryCodes: () => Promise<string[]>;
  consumeRecoveryCode: (code: string) => Promise<boolean>;
}

function isFactorList(value: unknown): value is AuthMFAListFactorsResponse["data"] {
  return typeof value === "object" && value !== null && "all" in value;
}

export function useMfa(): UseMfaReturn {
  const [factors, setFactors] = useState<Factor[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refreshFactors = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const { data, error: listError } = await supabase.auth.mfa.listFactors();
      if (listError) throw listError;
      if (!isFactorList(data)) throw new Error("Unexpected MFA factors response");
      setFactors(data.all);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Failed to load MFA factors");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    refreshFactors();
  }, [refreshFactors]);

  const enrollTotp = useCallback(async (friendlyName?: string): Promise<MfaEnrollment> => {
    const { data, error: enrollError } = await supabase.auth.mfa.enroll({
      factorType: "totp",
      friendlyName: friendlyName ?? `Authenticator ${new Date().toISOString().slice(0, 10)}`,
    });
    if (enrollError) throw enrollError;
    if (!data) throw new Error("MFA enrollment returned no data");
    return {
      factorId: data.id,
      qrCode: data.totp.qr_code,
      secret: data.totp.secret,
      uri: data.totp.uri,
    };
  }, []);

  const verifyEnrollment = useCallback(
    async (factorId: string, code: string) => {
      const { data: challenge, error: challengeError } = await supabase.auth.mfa.challenge({
        factorId,
      });
      if (challengeError) throw challengeError;
      if (!challenge) throw new Error("MFA challenge returned no data");

      const { error: verifyError } = await supabase.auth.mfa.verify({
        factorId,
        challengeId: challenge.id,
        code,
      });
      if (verifyError) throw verifyError;
      await refreshFactors();
    },
    [refreshFactors],
  );

  const cancelEnrollment = useCallback(
    async (factorId: string) => {
      const { error: unenrollError } = await supabase.auth.mfa.unenroll({ factorId });
      if (unenrollError) throw unenrollError;
      await refreshFactors();
    },
    [refreshFactors],
  );

  const unenroll = useCallback(
    async (factorId: string) => {
      const { error: unenrollError } = await supabase.auth.mfa.unenroll({ factorId });
      if (unenrollError) throw unenrollError;
      await clearRecoveryCodesForCurrentUser();
      await refreshFactors();
    },
    [refreshFactors],
  );

  const issueRecoveryCodes = useCallback(async (): Promise<string[]> => {
    const { data: userData, error: userError } = await supabase.auth.getUser();
    if (userError) throw userError;
    const userId = userData?.user?.id;
    if (!userId) throw new Error("No authenticated user");

    await clearRecoveryCodesForUser(userId);

    const codes = generateRecoveryCodes();
    const hashes = await Promise.all(codes.map(hashRecoveryCode));
    const rows = hashes.map((code_hash) => ({ user_id: userId, code_hash }));

    const { error: insertError } = await supabase.from("mfa_recovery_codes").insert(rows);
    if (insertError) throw insertError;

    return codes;
  }, []);

  const consumeRecoveryCode = useCallback(async (code: string): Promise<boolean> => {
    const codeHash = await hashRecoveryCode(code);
    const { data, error: rpcError } = await supabase.rpc("consume_recovery_code", {
      p_code_hash: codeHash,
    });
    if (rpcError) throw rpcError;
    return data === true;
  }, []);

  const verifiedFactor = factors.find((factor) => factor.status === "verified") ?? null;

  return {
    factors,
    verifiedFactor,
    isLoading,
    error,
    refreshFactors,
    enrollTotp,
    verifyEnrollment,
    cancelEnrollment,
    unenroll,
    issueRecoveryCodes,
    consumeRecoveryCode,
  };
}

async function clearRecoveryCodesForCurrentUser(): Promise<void> {
  const { data } = await supabase.auth.getUser();
  const userId = data?.user?.id;
  if (!userId) return;
  await clearRecoveryCodesForUser(userId);
}

async function clearRecoveryCodesForUser(userId: string): Promise<void> {
  await supabase.from("mfa_recovery_codes").delete().eq("user_id", userId);
}
