import { ExternalLink } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { useTabContext } from "../../../runtime/tabContext";
import type { AppWidgetDef } from "../../../schema/appDefinition.types";

interface ButtonWidgetProps {
  widget: AppWidgetDef;
  onRunGroup: (groupId: string) => void;
}

const BUTTON_VARIANTS = {
  primary: "default",
  outline: "outline",
  ghost: "ghost",
} as const;

/**
 * Generic action button (layout-stress vocabulary): unlike run_button it is
 * not a run group's trigger — it opens a URL, publishes a context value, or
 * fires an existing run group. The app layer still never computes (ADR D1).
 */
export function ButtonWidget({ widget, onRunGroup }: ButtonWidgetProps) {
  const { setValue } = useTabContext();
  const action = widget.action;
  if (!action) {
    return (
      <Button
        variant={BUTTON_VARIANTS[widget.buttonStyle ?? "primary"]}
        size="sm"
        disabled
        title="Configure an action in the inspector to make this button work"
        className="gap-1.5 w-full"
      >
        {widget.label ?? "Button"}
      </Button>
    );
  }

  const handleClick = () => {
    if (action.type === "open_url" && action.url) {
      window.open(action.url, "_blank", "noopener,noreferrer");
      return;
    }
    if (action.type === "set_context" && action.key) {
      setValue(action.key, action.value);
      return;
    }
    if (action.type === "run_group" && action.groupId) {
      onRunGroup(action.groupId);
    }
  };

  return (
    <Button
      variant={BUTTON_VARIANTS[widget.buttonStyle ?? "primary"]}
      size="sm"
      onClick={handleClick}
      className="gap-1.5 w-full"
    >
      {widget.label ?? "Button"}
      {action.type === "open_url" && <ExternalLink className="h-3 w-3" />}
    </Button>
  );
}
