import { AlertTriangle, Loader2 } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useAuth } from "@/features/auth/components/AuthProvider";
import TeamDetailHeader from "@/features/teams/components/TeamDetailHeader";
import TeamRosterPanel from "@/features/teams/components/TeamRosterPanel";
import { useMyTeams } from "@/features/teams/hooks/useMyTeams";
import { useTeamMembers } from "@/features/teams/hooks/useTeamMembers";
import type { TeamError } from "@/features/teams/types";
import SidePanel from "@/shared/components/layout/SidePanel";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";

// Route: /teams/:teamId. Resolves the team from the caller's memberships list
// (single source of truth for role, seat status, and — for owner/admin — the
// team's plan-seat inventory). If the id isn't in the list, either the user
// isn't a member or they navigated to a stale link — we render an
// access-denied panel with a way back rather than trying to reach through
// the RBAC.
const TeamDetailPage: React.FC = () => {
  const { teamId = "" } = useParams<{ teamId: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const callerUserId = user?.id ?? "";

  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  const { teams, isLoading: isLoadingTeams } = useMyTeams();
  // Kick off the members query as soon as we have a teamId — it's independent
  // of resolving the caller's role, and starting early keeps the roster snappy.
  const membersState = useTeamMembers(teamId);

  const team = teams.find((t) => t.id === teamId);

  const renderBody = () => {
    if (isLoadingTeams) {
      return (
        <div className="flex h-64 items-center justify-center">
          <PrometheuxSpinner size={36} label="Loading team..." />
        </div>
      );
    }
    if (!team) {
      // Members might still be loading (independent query). Prefer a spinner
      // over the not-found panel until we know for sure — otherwise a fresh
      // navigation right after create can flash a false "not found" while the
      // list refetch is in flight.
      if (membersState.isLoading) {
        return (
          <div className="flex h-64 items-center justify-center">
            <PrometheuxSpinner size={36} label="Loading team..." />
          </div>
        );
      }
      const memberErr = membersState.error;
      const httpStatus = memberErr ? (memberErr as TeamError).httpStatus : null;
      const forbidden = httpStatus === 403;
      const notFound = httpStatus === 404;
      const title = forbidden
        ? "You're not a member of this team"
        : notFound
          ? "Team not found"
          : "Team unavailable";
      const description = forbidden
        ? "Ask an owner or admin of this team to invite you."
        : notFound
          ? "The team may have been deleted or the link is out of date."
          : (memberErr?.message ?? "Something went wrong loading this team. Try refreshing.");
      return (
        <div className="flex flex-col items-center justify-center gap-3 py-16 text-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-secondary">
            <AlertTriangle className="h-5 w-5 text-muted-foreground" />
          </div>
          <div>
            <p className="text-sm font-medium text-foreground">{title}</p>
            <p className="mt-1 text-xs text-muted-foreground">{description}</p>
            {/* Diagnostic footer — the team id we're looking up + the raw
                backend error. Small, monospaced, muted — invisible in the
                happy path, useful when a user needs to file a bug. */}
            <p className="mt-3 break-all font-mono text-[10px] text-muted-foreground/70">
              team_id: {teamId}
              {httpStatus !== null ? ` \u00b7 http ${httpStatus}` : ""}
              {memberErr?.message ? ` \u00b7 ${memberErr.message}` : ""}
            </p>
          </div>
          <Button type="button" size="sm" onClick={() => navigate("/teams")}>
            Back to Teams
          </Button>
        </div>
      );
    }
    return <TeamRosterPanel team={team} callerUserId={callerUserId} />;
  };

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="teams"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-1 flex-col overflow-hidden transition-all duration-200 ${sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0"}`}
      >
        {team ? (
          <TeamDetailHeader
            team={team}
            members={membersState.members}
            callerUserId={callerUserId}
          />
        ) : (
          <header className="relative z-20 flex h-[56px] shrink-0 items-center gap-3 border-b bg-card px-6">
            {(isLoadingTeams || membersState.isLoading) && (
              <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
            )}
            <h1 className="text-base font-bold">Team</h1>
          </header>
        )}

        <div className="min-h-0 flex-1 overflow-y-auto">{renderBody()}</div>
      </div>
    </div>
  );
};

export default TeamDetailPage;
