import { useCallback, useRef, useState } from "react";

/** Where a dragged cell would land relative to the cell being hovered. */
export type CellDropPosition = "top" | "bottom" | null;

/**
 * Fired at the window when a cell is dropped onto another cell. `useConceptEditor`
 * listens for it and performs the reorder; the drag source is the explorer tree
 * (see `useTreeDragDrop`).
 */
export const CELL_REORDER_EVENT = "cellReorder";

export interface CellReorderDetail {
  draggedCellId: string;
  targetCellId: string;
  position: CellDropPosition;
}

/**
 * Makes a cell a drop target for reordering: tracks which half of the cell the
 * pointer is over (so the caller can draw a drop indicator) and announces the
 * drop. Shared by every cell type.
 */
export function useCellDragDrop(cellId: string) {
  const [dropPosition, setDropPosition] = useState<CellDropPosition>(null);
  const cellIdRef = useRef(cellId);
  cellIdRef.current = cellId;

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
    const rect = e.currentTarget.getBoundingClientRect();
    setDropPosition(e.clientY < rect.top + rect.height / 2 ? "top" : "bottom");
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    // Only clear when leaving the cell entirely — moving over a child of the
    // cell fires dragleave too, which would make the indicator flicker.
    if (e.currentTarget.contains(e.relatedTarget as Node)) return;
    setDropPosition(null);
  }, []);

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      const position = dropPosition;
      setDropPosition(null);

      const dragData = e.dataTransfer.getData("text/plain");
      if (!dragData) return;

      let draggedCellId: unknown;
      try {
        draggedCellId = JSON.parse(dragData).cellId;
      } catch {
        return;
      }
      if (typeof draggedCellId !== "string" || draggedCellId === cellIdRef.current) return;

      const detail: CellReorderDetail = {
        draggedCellId,
        targetCellId: cellIdRef.current,
        position,
      };
      window.dispatchEvent(new CustomEvent(CELL_REORDER_EVENT, { detail }));
    },
    [dropPosition],
  );

  return { dropPosition, handleDragOver, handleDragLeave, handleDrop };
}
