import type React from "react";
import { useLlmDefaults } from "@/features/concept-editor/hooks/useLlmDefaults";
import type { LlmConceptConfig } from "@/features/concept-editor/types";
import { useLlmModels } from "@/features/settings/hooks/useLlmModels";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { LlmConnectionSelector } from "./LlmConnectionSelector";

const PROVIDER_DEFAULT = "default";
const MODEL_DEFAULT = "default";

const PROVIDERS = [
  { value: "azure", label: "Azure" },
  { value: "openai", label: "OpenAI" },
  { value: "anthropic", label: "Anthropic" },
  { value: "databricks", label: "Databricks" },
  { value: "snowflake_cortex", label: "Snowflake Cortex" },
];

interface LlmModelOverridesProps {
  cellId: string;
  config: LlmConceptConfig;
  disabled?: boolean;
  /** Concept name, used to suggest a name for a connection created here. */
  conceptName?: string;
  onChange: (patch: Partial<LlmConceptConfig>) => void;
}

function parseOptionalNumber(raw: string, parse: (value: string) => number): number | undefined {
  const parsed = parse(raw);
  return Number.isFinite(parsed) ? parsed : undefined;
}

/**
 * Provider/model/temperature/max-tokens overrides for an llm cell, showing the
 * resolved defaults (from /users/llm-defaults) so "Default" is never opaque,
 * with a model picker fed by the provider's live model list.
 */
export function LlmModelOverrides({
  cellId,
  config,
  disabled,
  conceptName,
  onChange,
}: LlmModelOverridesProps) {
  const { data: defaults } = useLlmDefaults();

  // A named connection replaces the user's default settings as the base; the
  // provider select is hidden then (the connection owns the provider).
  const connections = defaults?.connections ?? [];
  const connection = config.connection
    ? connections.find((c) => c.name === config.connection)
    : undefined;
  // The reference travels with the definition, so it can name a connection this
  // account never had — a shared or imported project. The hint recorded at save
  // time is what turns that into something the reader can fix.
  const isConnectionMissing = Boolean(config.connection) && !connection && Boolean(defaults);
  const baseProvider = connection?.provider ?? defaults?.provider;

  const effectiveProvider = config.provider ?? baseProvider ?? null;
  // Listed through the pinned connection, so the options are the ones its own
  // credentials can reach rather than the managed pool's.
  const { data: providerModels } = useLlmModels({
    provider: effectiveProvider,
    connection: connection?.name,
  });

  // The model a cleared override falls back to: the connection's model, the
  // user's default model, or the effective provider's platform default.
  const providerDefaultModel = effectiveProvider
    ? defaults?.defaultVersions[effectiveProvider]
    : undefined;
  const baseModel = connection ? (connection.model ?? providerDefaultModel) : undefined;
  const defaultModel =
    baseModel ?? (config.provider || connection ? providerDefaultModel : defaults?.model);

  const effectiveModel = config.model ?? defaultModel;
  const effectiveTemperature = config.temperature ?? defaults?.temperature;
  const effectiveMaxTokens = config.max_tokens ?? defaults?.conceptMaxTokens;

  const knownModels = providerModels ?? [];
  const modelOptions =
    config.model && !knownModels.includes(config.model)
      ? [config.model, ...knownModels]
      : knownModels;

  const handleProviderChange = (value: string) => {
    // A provider switch invalidates a pinned model (it belongs to the old provider).
    onChange({ provider: value === PROVIDER_DEFAULT ? undefined : value, model: undefined });
  };

  const handleModelSelect = (value: string) => {
    onChange({ model: value === MODEL_DEFAULT ? undefined : value });
  };

  const handleModelInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange({ model: e.target.value.trim() || undefined });
  };

  const handleTemperatureChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange({ temperature: parseOptionalNumber(e.target.value, Number.parseFloat) });
  };

  const handleMaxTokensChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange({ max_tokens: parseOptionalNumber(e.target.value, (v) => Number.parseInt(v, 10)) });
  };

  const handleRowLimitChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange({ row_limit: parseOptionalNumber(e.target.value, (v) => Number.parseInt(v, 10)) });
  };

  return (
    <div className="flex flex-col gap-2">
      {defaults && (
        <span className="text-[11px] text-muted-foreground">
          Runs with: <span className="font-medium">{effectiveProvider}</span> ·{" "}
          <span className="font-medium">{effectiveModel ?? "provider default"}</span> · temperature{" "}
          {effectiveTemperature} · max tokens {effectiveMaxTokens}
          {config.connection ? ` · connection "${config.connection}"` : ""}
        </span>
      )}
      <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
        <LlmConnectionSelector
          cellId={cellId}
          config={config}
          connections={connections}
          isMissing={isConnectionMissing}
          disabled={disabled}
          conceptName={conceptName}
          onChange={onChange}
        />
        {!config.connection && (
          <div className="flex items-center gap-2">
            <label htmlFor={`llm-provider-${cellId}`} className="text-xs text-muted-foreground">
              Provider
            </label>
            <Select
              value={config.provider ?? PROVIDER_DEFAULT}
              onValueChange={handleProviderChange}
              disabled={disabled}
            >
              <SelectTrigger
                id={`llm-provider-${cellId}`}
                className="h-7 w-[160px] text-xs border-border"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value={PROVIDER_DEFAULT} className="text-xs">
                  {defaults ? `Default (${defaults.provider})` : "Default"}
                </SelectItem>
                {PROVIDERS.map((p) => (
                  <SelectItem key={p.value} value={p.value} className="text-xs">
                    {p.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}
        <div className="flex items-center gap-2">
          <label htmlFor={`llm-model-${cellId}`} className="text-xs text-muted-foreground">
            Model
          </label>
          {modelOptions.length > 0 ? (
            <Select
              value={config.model ?? MODEL_DEFAULT}
              onValueChange={handleModelSelect}
              disabled={disabled}
            >
              <SelectTrigger
                id={`llm-model-${cellId}`}
                className="h-7 w-[220px] text-xs border-border"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value={MODEL_DEFAULT} className="text-xs">
                  {defaultModel ? `Default (${defaultModel})` : "Default"}
                </SelectItem>
                {modelOptions.map((model) => (
                  <SelectItem key={model} value={model} className="text-xs">
                    {model}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          ) : (
            <Input
              id={`llm-model-${cellId}`}
              value={config.model ?? ""}
              onChange={handleModelInput}
              placeholder={defaultModel ?? "default"}
              className="h-7 w-52 text-xs bg-muted/80"
              disabled={disabled}
            />
          )}
        </div>
        <div className="flex items-center gap-2">
          <label htmlFor={`llm-temp-${cellId}`} className="text-xs text-muted-foreground">
            Temperature
          </label>
          <Input
            id={`llm-temp-${cellId}`}
            type="number"
            min={0}
            max={2}
            step={0.1}
            value={config.temperature ?? ""}
            onChange={handleTemperatureChange}
            placeholder={defaults ? String(defaults.temperature) : "default"}
            className="h-7 w-24 text-xs bg-muted/80"
            disabled={disabled}
          />
        </div>
        <div className="flex items-center gap-2">
          <label htmlFor={`llm-maxtok-${cellId}`} className="text-xs text-muted-foreground">
            Max tokens
          </label>
          <Input
            id={`llm-maxtok-${cellId}`}
            type="number"
            min={1}
            value={config.max_tokens ?? ""}
            onChange={handleMaxTokensChange}
            placeholder={defaults ? String(defaults.conceptMaxTokens) : "default"}
            className="h-7 w-24 text-xs bg-muted/80"
            disabled={disabled}
          />
        </div>
        <div className="flex items-center gap-2">
          <label htmlFor={`llm-rowlimit-${cellId}`} className="text-xs text-muted-foreground">
            Rows per input
          </label>
          <Input
            id={`llm-rowlimit-${cellId}`}
            type="number"
            min={1}
            value={config.row_limit ?? ""}
            onChange={handleRowLimitChange}
            placeholder={defaults ? String(defaults.conceptRowLimit) : "default"}
            className="h-7 w-24 text-xs bg-muted/80"
            disabled={disabled}
            title="How many rows (or notes) of each referenced upstream the prompt carries. Anything beyond this is omitted from what the model sees."
          />
        </div>
      </div>
    </div>
  );
}
