import { type Diagnostic, linter } from "@codemirror/lint";
import { Facet } from "@codemirror/state";
import type { EditorView } from "@codemirror/view";

/**
 * Facet that allows injecting externally-known bound predicate names
 * (e.g. from the separate bind-annotation editor) into the linter.
 */
export const externalBoundPredicatesFacet = Facet.define<string[], string[]>({
  combine: (values) => values.flat(),
});

interface VadalogLinterOptions {
  strictMode?: boolean;
}

/**
 * Vadalog syntax linter that validates code based on Vadalog grammar rules
 * Provides IDE-like continuous syntax checking
 */
export function vadalogLinter(_options: VadalogLinterOptions = {}): any {
  return linter((view: EditorView): Diagnostic[] => {
    const diagnostics: Diagnostic[] = [];
    const state = view.state;
    const doc = state.doc;
    const text = doc.toString();
    const lines = text.split("\n");

    // Track predicates defined in @bind and @qbind annotations
    // These predicates are valid even if they don't have explicit definitions
    const boundPredicates = new Set<string>();
    const bindPattern = /@(?:bind|qbind)\s*\(\s*"([a-z_][a-zA-Z0-9_]*)"/g;
    let bindPredicateMatch: RegExpExecArray | null;
    while ((bindPredicateMatch = bindPattern.exec(text)) !== null) {
      boundPredicates.add(bindPredicateMatch[1]);
    }

    for (const name of state.facet(externalBoundPredicatesFacet)) {
      boundPredicates.add(name);
    }

    // Precompute ranges for qbind string arguments (excluding the first argument)
    // so we can ignore diagnostics that fall inside SQL/text payloads.
    const qbindStringRanges: { from: number; to: number }[] = [];
    const qbindPattern = /@qbind\s*\(/g;
    let qbindMatch: RegExpExecArray | null;

    while ((qbindMatch = qbindPattern.exec(text)) !== null) {
      let pos = qbindPattern.lastIndex;
      let depth = 1; // already consumed the opening '('
      let inString = false;
      let strChar: string | null = null;
      let escaped = false;
      let argIndex = 0;
      let currentStringStart: number | null = null;

      for (; pos < text.length; pos++) {
        const ch = text[pos];

        if (escaped) {
          escaped = false;
          continue;
        }

        if (ch === "\\") {
          escaped = true;
          continue;
        }

        if (inString) {
          if (ch === strChar) {
            inString = false;
            strChar = null;
            if (argIndex >= 1 && currentStringStart !== null) {
              qbindStringRanges.push({ from: currentStringStart, to: pos + 1 });
            }
            currentStringStart = null;
          }
          continue;
        }

        if (ch === '"' || ch === "'") {
          inString = true;
          strChar = ch;
          currentStringStart = pos;
          continue;
        }

        if (ch === "(") {
          depth++;
        } else if (ch === ")") {
          depth--;
          if (depth === 0) break;
        } else if (ch === "," && depth === 1) {
          argIndex++;
        }
      }
    }

    const isInQbindStringRange = (pos: number): boolean =>
      qbindStringRanges.some((range) => pos >= range.from && pos < range.to);

    // Helper function to check if a position is in a commented line
    const isInCommentedLine = (pos: number): boolean => {
      const line = doc.lineAt(pos);
      const lineText = line.text;
      const trimmedLine = lineText.trim();
      return trimmedLine.startsWith("%");
    };

    // Track state for multi-line constructs
    let inString = false;
    let stringChar: string | null = null;
    let escaped = false;
    let openParens = 0;
    let openBrackets = 0;
    let openBraces = 0;
    const parenPositions: { line: number; col: number; char: string }[] = [];

    // Validate each line
    lines.forEach((lineText, lineIndex) => {
      const lineNum = lineIndex + 1;
      const lineStart = doc.line(lineNum).from;

      // Skip empty lines and comments
      const trimmedLine = lineText.trim();
      if (trimmedLine === "" || trimmedLine.startsWith("%")) return;

      // Track string state and brackets
      for (let i = 0; i < lineText.length; i++) {
        const char = lineText[i];

        if (escaped) {
          escaped = false;
          continue;
        }

        if (char === "\\") {
          escaped = true;
          continue;
        }

        if (!inString && (char === '"' || char === "'")) {
          inString = true;
          stringChar = char;
        } else if (inString && char === stringChar) {
          inString = false;
          stringChar = null;
        }

        // Track brackets/parens (only when not in string or comment)
        if (!inString && !lineText.substring(0, i).trim().startsWith("%")) {
          if (char === "(") {
            openParens++;
            parenPositions.push({ line: lineNum, col: i, char: "(" });
          }
          if (char === ")") {
            openParens--;
            if (openParens < 0) {
              diagnostics.push({
                from: lineStart + i,
                to: lineStart + i + 1,
                severity: "error",
                message: "Unexpected closing parenthesis",
                markClass: "cm-error-highlight",
              });
            } else {
              parenPositions.pop();
            }
          }
          if (char === "[") {
            openBrackets++;
          }
          if (char === "]") {
            openBrackets--;
            if (openBrackets < 0) {
              diagnostics.push({
                from: lineStart + i,
                to: lineStart + i + 1,
                severity: "error",
                message: "Unexpected closing bracket",
                markClass: "cm-error-highlight",
              });
            }
          }
          if (char === "{") {
            openBraces++;
          }
          if (char === "}") {
            openBraces--;
            if (openBraces < 0) {
              diagnostics.push({
                from: lineStart + i,
                to: lineStart + i + 1,
                severity: "error",
                message: "Unexpected closing brace",
                markClass: "cm-error-highlight",
              });
            }
          }
        }
      }

      // Check for valid annotations
      const annotationPattern = /@([a-zA-Z_][a-zA-Z0-9_]*)/g;
      let annotationMatch;
      const validAnnotations = [
        "input",
        "output",
        "bind",
        "qbind",
        "mapping",
        "model",
        "post",
        "param",
        "explain",
        "chase",
      ];

      while ((annotationMatch = annotationPattern.exec(lineText)) !== null) {
        const annotation = annotationMatch[1];
        if (!validAnnotations.includes(annotation)) {
          diagnostics.push({
            from: lineStart + annotationMatch.index,
            to: lineStart + annotationMatch.index + annotationMatch[0].length,
            severity: "warning",
            message: `Unknown annotation: @${annotation}. Valid annotations are: ${validAnnotations.join(", ")}`,
          });
        }

        // Check if annotation has opening parenthesis
        const afterAnnotation = lineText.substring(
          annotationMatch.index + annotationMatch[0].length,
        );
        if (!afterAnnotation.trim().startsWith("(")) {
          diagnostics.push({
            from: lineStart + annotationMatch.index,
            to: lineStart + annotationMatch.index + annotationMatch[0].length,
            severity: "error",
            message: "Annotation must be followed by parentheses: @annotation(...)",
            markClass: "cm-error-highlight",
          });
        }
      }

      // Annotation period checking is now handled in the multi-line tracking section below

      // Check for valid predicate definitions
      // Predicates must begin with a letter and be lowercase
      const predicatePattern = /^\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/;
      const predicateMatch = lineText.match(predicatePattern);

      if (predicateMatch) {
        const predicateName = predicateMatch[1];
        const nameStart = lineText.indexOf(predicateName);

        // Check if predicate starts with a letter
        if (!/^[a-zA-Z]/.test(predicateName)) {
          diagnostics.push({
            from: lineStart + nameStart,
            to: lineStart + nameStart + predicateName.length,
            severity: "error",
            message: `Predicate name must begin with a letter: ${predicateName}`,
            markClass: "cm-error-highlight",
          });
        }
        // Check if predicate starts with lowercase
        else if (predicateName[0] !== predicateName[0].toLowerCase()) {
          diagnostics.push({
            from: lineStart + nameStart,
            to: lineStart + nameStart + predicateName.length,
            severity: "error",
            message: `Predicate names must start with a lowercase letter: ${predicateName}`,
            markClass: "cm-error-highlight",
          });
        }
      }

      // Also check predicates in rule bodies (after :- or <-)
      const ruleArrowIndex =
        lineText.indexOf(":-") !== -1 ? lineText.indexOf(":-") : lineText.indexOf("<-");
      if (ruleArrowIndex !== -1) {
        const bodyStart = ruleArrowIndex + 2;
        const body = lineText.substring(bodyStart);

        // Find all predicates in the body (predicate_name(...))
        const bodyPredicatePattern = /\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/g;
        let bodyPredMatch;

        // Graph analytics functions that start with #
        const graphFunctions = [
          "TC",
          "PATHS",
          "ASP",
          "SSSP",
          "BFS",
          "PR",
          "CC",
          "WCC",
          "TRI",
          "BC",
          "DC",
        ];

        while ((bodyPredMatch = bodyPredicatePattern.exec(body)) !== null) {
          const predName = bodyPredMatch[1];
          const predStart = bodyStart + bodyPredMatch.index;

          // Skip if it's a known annotation
          if (predName.startsWith("@") || validAnnotations.includes(predName)) {
            continue;
          }

          // Skip if it's a graph analytics function (these are uppercase and preceded by #)
          if (graphFunctions.includes(predName.toUpperCase())) {
            const beforePred = body.substring(
              Math.max(0, bodyPredMatch.index - 1),
              bodyPredMatch.index,
            );
            if (beforePred === "#") {
              continue;
            }
          }

          // Check if predicate starts with a letter
          if (!/^[a-zA-Z]/.test(predName)) {
            diagnostics.push({
              from: lineStart + predStart,
              to: lineStart + predStart + predName.length,
              severity: "error",
              message: `Predicate name must begin with a letter: ${predName}`,
              markClass: "cm-error-highlight",
            });
          }
          // Check if predicate starts with lowercase
          else if (predName[0] !== predName[0].toLowerCase()) {
            diagnostics.push({
              from: lineStart + predStart,
              to: lineStart + predStart + predName.length,
              severity: "error",
              message: `Predicate names must start with a lowercase letter: ${predName}`,
              markClass: "cm-error-highlight",
            });
          }
        }
      }

      // Check for rules that must end with period
      // Only check if the rule appears to be complete (not continuing on next line)
      if (
        (trimmedLine.includes(":-") || trimmedLine.includes("<-")) &&
        !trimmedLine.startsWith("@")
      ) {
        // Find the comment position (if any)
        const commentIndex = trimmedLine.indexOf("%");
        // Get the rule part (before comment, or entire line if no comment)
        const rulePart =
          commentIndex !== -1
            ? trimmedLine.substring(0, commentIndex).trimEnd()
            : trimmedLine.trimEnd();
        // If rule part ends with period, it's complete - don't flag
        if (!rulePart.endsWith(".")) {
          // If rule part ends with comma, it's continuing on next line - don't flag
          // If rule part ends with ':-' or '<-', body is on next line - don't flag
          if (!rulePart.endsWith(",") && !rulePart.endsWith(":-") && !rulePart.endsWith("<-")) {
            // Check if this is the last line or if next line doesn't continue the rule
            const isLastLine = lineIndex === lines.length - 1;
            const nextLine = !isLastLine ? lines[lineIndex + 1] : null;

            // Next line continues the rule if:
            // 1. It starts with whitespace (indented) OR
            // 2. It starts with a comma (continuation of body) OR
            // 3. It starts with a comment
            // If it starts at column 0 with a lowercase/@, it's a new rule/statement
            const nextLineContinues =
              nextLine &&
              (nextLine.match(/^\s+/) || // Starts with whitespace (indented)
                nextLine.trim().startsWith(",") || // Starts with comma
                nextLine.trim().startsWith("%")); // Starts with comment

            // Only flag if it's the last line OR next line doesn't continue
            if (isLastLine || !nextLineContinues) {
              diagnostics.push({
                from: lineStart + lineText.length - 1,
                to: lineStart + lineText.length,
                severity: "error",
                message: "Rules must end with a period (.)",
                markClass: "cm-error-highlight",
              });
            }
          }
        }
      }

      // Check for common syntax errors
      // Check for parameters in {..} without $ prefix
      // Pattern: {...} without $, e.g., {test} should be ${test}
      const paramWithoutDollarPattern = /(?<!\$)\{([a-z_][a-zA-Z0-9_]*)\}/g;
      let paramMatch;
      while ((paramMatch = paramWithoutDollarPattern.exec(lineText)) !== null) {
        const paramName = paramMatch[1];
        const braceIndex = paramMatch.index;

        // Skip if inside a string
        let inString = false;
        let strChar: string | null = null;
        let escaped = false;
        for (let i = 0; i < braceIndex; i++) {
          if (escaped) {
            escaped = false;
            continue;
          }
          if (lineText[i] === "\\") {
            escaped = true;
            continue;
          }
          if (!inString && (lineText[i] === '"' || lineText[i] === "'")) {
            inString = true;
            strChar = lineText[i];
          } else if (inString && lineText[i] === strChar) {
            inString = false;
            strChar = null;
          }
        }
        if (inString) continue;

        // Skip if this is part of a comment
        if (lineText.substring(0, braceIndex).includes("%")) continue;

        diagnostics.push({
          from: lineStart + braceIndex,
          to: lineStart + braceIndex + paramName.length + 2, // Include the {}
          severity: "error",
          message: `Parameter ${paramName} is missing $ prefix. Use \${${paramName}} instead of {${paramName}}`,
        });
      }

      // Check for variables (must start with uppercase)
      // Variables appear in predicate arguments, rule bodies, and condition expressions
      if (!trimmedLine.startsWith("@") && !trimmedLine.startsWith("%")) {
        let varMatch: RegExpExecArray | null = null; // Declare once for all patterns
        // Track which positions we've already flagged to avoid duplicates across patterns
        const flaggedPositions = new Set<string>();

        // First, identify ALL predicate names and library functions in this line
        // Predicates: lowercase identifier followed by opening paren
        // Library functions: library:function pattern (e.g., collections:split, math:abs)
        const predicateNames = new Set<string>();
        const predicatePattern = /\b([a-z_][a-zA-Z0-9_]*)\s*\(/g;
        let predMatch;
        while ((predMatch = predicatePattern.exec(lineText)) !== null) {
          const predName = predMatch[1];
          const predIndex = lineText.indexOf(
            predName,
            Math.max(0, predMatch.index - predName.length - 5),
          );
          // Store position + name to be more precise
          predicateNames.add(`${predIndex}:${predName}`);
        }

        // Also identify library functions (library:function pattern)
        // These are valid expressions and should not be flagged as variables
        const libraryFunctions = new Set<string>();
        const libraryPattern = /\b([a-z_][a-zA-Z0-9_]*):([a-z_][a-zA-Z0-9_]*)\s*\(/g;
        let libMatch;
        while ((libMatch = libraryPattern.exec(lineText)) !== null) {
          const libraryName = libMatch[1];
          const functionName = libMatch[2];
          // Store the function name part (e.g., "split" from "collections:split")
          const funcIndex = lineText.indexOf(functionName, libMatch.index + libraryName.length);
          libraryFunctions.add(`${funcIndex}:${functionName}`);
        }

        // Also identify predicates used as arguments to graph functions (e.g., #TC(edge))
        // Pattern: #FUNCTION_NAME(predicate_name)
        const graphFunctionPredicates = new Set<string>();
        const graphFunctionPattern =
          /#(?:TC|PATHS|ASP|SSSP|BFS|WCC|TRI|DC|BC|PR)\s*\(\s*([a-z_][a-zA-Z0-9_]*)/gi;
        let graphMatch;
        while ((graphMatch = graphFunctionPattern.exec(lineText)) !== null) {
          const predicateArg = graphMatch[1];
          const argIndex = graphMatch.index + graphMatch[0].indexOf(predicateArg);
          graphFunctionPredicates.add(`${argIndex}:${predicateArg}`);
        }

        // Helper to check if an identifier at a position is a predicate name or library function
        const isPredicateName = (pos: number, name: string): boolean => {
          // Check if it's in our predicateNames set
          if (
            predicateNames.has(`${pos}:${name}`) ||
            predicateNames.has(`${pos - 1}:${name}`) ||
            predicateNames.has(`${pos + 1}:${name}`)
          ) {
            return true;
          }

          // Check if it's a library function
          if (
            libraryFunctions.has(`${pos}:${name}`) ||
            libraryFunctions.has(`${pos - 1}:${name}`) ||
            libraryFunctions.has(`${pos + 1}:${name}`)
          ) {
            return true;
          }

          // Check if it's a predicate used as argument to a graph function
          if (
            graphFunctionPredicates.has(`${pos}:${name}`) ||
            graphFunctionPredicates.has(`${pos - 1}:${name}`) ||
            graphFunctionPredicates.has(`${pos + 1}:${name}`)
          ) {
            return true;
          }

          // Check if it's a bound predicate (from @bind or @qbind)
          if (boundPredicates.has(name)) {
            return true;
          }

          // Check if followed by (
          if (
            lineText
              .substring(pos + name.length)
              .trim()
              .startsWith("(")
          ) {
            return true;
          }

          // Check if preceded by : (part of library:function)
          const beforeName = lineText.substring(Math.max(0, pos - 20), pos);
          if (beforeName.trim().endsWith(":")) {
            return true;
          }

          // Check if preceded by # (graph function argument)
          if (
            beforeName.trim().endsWith("#TC(") ||
            beforeName.trim().endsWith("#PATHS(") ||
            beforeName.trim().endsWith("#ASP(") ||
            beforeName.trim().endsWith("#SSSP(") ||
            beforeName.trim().endsWith("#BFS(") ||
            beforeName.trim().endsWith("#WCC(") ||
            beforeName.trim().endsWith("#TRI(") ||
            beforeName.trim().endsWith("#DC(") ||
            beforeName.trim().endsWith("#BC(") ||
            beforeName.trim().endsWith("#PR(")
          ) {
            return true;
          }

          return false;
        };

        // Helper function to check if a position is inside a string
        const isInString = (pos: number): boolean => {
          let inStr = false;
          let strChar: string | null = null;
          let escaped = false;
          for (let i = 0; i < pos; i++) {
            if (escaped) {
              escaped = false;
              continue;
            }
            if (lineText[i] === "\\") {
              escaped = true;
              continue;
            }
            if (!inStr && (lineText[i] === '"' || lineText[i] === "'")) {
              inStr = true;
              strChar = lineText[i];
            } else if (inStr && lineText[i] === strChar) {
              inStr = false;
              strChar = null;
            }
          }
          return inStr;
        };

        // Helper function to check if a position is inside ${...} parameter syntax
        const isInParameter = (pos: number): boolean => {
          // Find the nearest ${ before this position
          let lastDollarBrace = -1;
          for (let i = pos - 1; i > 0; i--) {
            if (lineText[i - 1] === "$" && lineText[i] === "{") {
              lastDollarBrace = i - 1;
              break;
            }
          }

          if (lastDollarBrace === -1) return false;

          // Find the matching } after the ${ (not escaped)
          for (let i = lastDollarBrace + 2; i < lineText.length; i++) {
            // Check if this is an escaped }
            if (lineText[i] === "}" && (i === lastDollarBrace + 2 || lineText[i - 1] !== "\\")) {
              // Found matching }, check if pos is between ${ and }
              return pos > lastDollarBrace && pos < i;
            }
            // If we hit another ${ before finding }, this parameter is not closed yet
            // but we're still inside it if pos is after the ${
            if (i > 0 && lineText[i - 1] === "$" && lineText[i] === "{") {
              // Another ${ found, check if we're in the first one
              return pos > lastDollarBrace && pos < i;
            }
          }

          // If we reach here, the ${ is not closed, but if pos is after ${, we're in it
          return pos > lastDollarBrace;
        };

        // Pattern 1: Variables in predicate arguments - inside parentheses
        // Find all opening parentheses and check identifiers inside them
        const parenPattern = /\(/g;
        let parenMatch;

        while ((parenMatch = parenPattern.exec(lineText)) !== null) {
          const parenIndex = parenMatch.index;

          // Skip if inside a string
          if (isInString(parenIndex)) continue;

          // Find the matching closing parenthesis
          let parenDepth = 1;
          let closingParenIndex = -1;
          for (let i = parenIndex + 1; i < lineText.length; i++) {
            if (isInString(i)) continue;
            if (lineText[i] === "(") parenDepth++;
            if (lineText[i] === ")") {
              parenDepth--;
              if (parenDepth === 0) {
                closingParenIndex = i;
                break;
              }
            }
          }

          if (closingParenIndex === -1) continue; // Unclosed paren, will be caught by other checks

          // Extract content inside parentheses
          const insideParens = lineText.substring(parenIndex + 1, closingParenIndex);

          // Check if there's a predicate name before this opening paren
          const beforeParen = lineText.substring(Math.max(0, parenIndex - 50), parenIndex).trim();
          // If there's a lowercase identifier right before the paren, it's a predicate name, not a variable
          const hasPredicateBefore = /[a-z_][a-zA-Z0-9_]*\s*$/.test(beforeParen);

          // Only check for variables if this is an argument list (has predicate before)
          if (hasPredicateBefore) {
            // Find all lowercase identifiers inside the parentheses (these should be variables)
            const varPattern = /\b([a-z][a-zA-Z0-9_]*)\b/g;
            let varMatch;

            while ((varMatch = varPattern.exec(insideParens)) !== null) {
              const varName = varMatch[1];
              const varIndexInLine = parenIndex + 1 + varMatch.index;

              // Skip if inside a string
              if (isInString(varIndexInLine)) continue;

              // Skip if this is a predicate name
              if (isPredicateName(varIndexInLine, varName)) continue;

              // Skip if inside a parameter ${...}
              if (isInParameter(varIndexInLine)) continue;

              // Skip if it's a known annotation
              if (validAnnotations.includes(varName)) continue;

              // Skip if it's part of an annotation
              const beforeVar = lineText.substring(
                Math.max(0, varIndexInLine - 20),
                varIndexInLine,
              );
              if (beforeVar.includes("@")) continue;

              // Skip if it's a namespace prefix (followed by colon, e.g., "collections:")
              const afterVar = lineText.substring(
                varIndexInLine + varName.length,
                varIndexInLine + varName.length + 1,
              );
              if (afterVar === ":") continue;

              // This is a variable in argument position - must be uppercase
              const posKey = `${lineStart + varIndexInLine}-${varName}`;
              if (flaggedPositions.has(posKey)) continue; // Already flagged by another pattern
              flaggedPositions.add(posKey);

              const suggestedName = varName.charAt(0).toUpperCase() + varName.slice(1);
              diagnostics.push({
                from: lineStart + varIndexInLine,
                to: lineStart + varIndexInLine + varName.length,
                severity: "error",
                message: `Variables must start with an uppercase letter: ${varName}. Use ${suggestedName} instead.`,
                markClass: "cm-error-highlight",
              });
            }
          }
        }

        // Pattern 2: Variables after commas: predicate(A, b, C) -> b should be B
        const varAfterCommaPattern = /,\s*\b([a-z][a-zA-Z0-9_]*)\b/g;
        while ((varMatch = varAfterCommaPattern.exec(lineText)) !== null) {
          const varName = varMatch[1];
          const varIndex = varMatch.index + varMatch[0].indexOf(varName);

          // Skip if this is a predicate name
          if (isPredicateName(varIndex, varName)) continue;

          // Skip if inside a string
          if (isInString(varIndex)) continue;

          // Skip if inside a parameter ${...}
          if (isInParameter(varIndex)) continue;

          // Skip if it's a known annotation
          if (validAnnotations.includes(varName)) continue;

          // Skip if it's part of an annotation
          const beforeVar = lineText.substring(Math.max(0, varIndex - 20), varIndex);
          if (beforeVar.includes("@")) continue;

          // Skip if it's a namespace prefix (followed by colon, e.g., "collections:")
          const afterVar = lineText.substring(
            varIndex + varName.length,
            varIndex + varName.length + 1,
          );
          if (afterVar === ":") continue;

          // Check if we're inside parentheses (argument list)
          let parenDepth = 0;
          let insideParens = false;
          for (let i = 0; i < varIndex; i++) {
            if (lineText[i] === "(") {
              parenDepth++;
              insideParens = true;
            } else if (lineText[i] === ")") {
              parenDepth--;
            }
          }

          // Only flag if we're inside parentheses (argument position)
          if (insideParens && parenDepth > 0) {
            const posKey = `${lineStart + varIndex}-${varName}`;
            if (flaggedPositions.has(posKey)) continue; // Already flagged by another pattern
            flaggedPositions.add(posKey);

            const suggestedName = varName.charAt(0).toUpperCase() + varName.slice(1);
            diagnostics.push({
              from: lineStart + varIndex,
              to: lineStart + varIndex + varName.length,
              severity: "error",
              message: `Variables must start with an uppercase letter: ${varName}. Use ${suggestedName} instead.`,
              markClass: "cm-error-highlight",
            });
          }
        }

        // Pattern 3a: Variables AFTER operators in comparisons: X = y -> y should be Y
        // But NOT predicates after :- like "owns(X) :- person(X)"
        const varAfterOperatorPattern = /(?:[=!<>])\s*\b([a-z][a-zA-Z0-9_]*)\b/g;
        while ((varMatch = varAfterOperatorPattern.exec(lineText)) !== null) {
          const varName = varMatch[1];
          const varIndex = varMatch.index + varMatch[0].indexOf(varName);

          // Skip if this is a predicate name
          if (isPredicateName(varIndex, varName)) continue;

          // Skip if inside a string
          if (isInString(varIndex)) continue;

          // Skip if inside a parameter ${...}
          if (isInParameter(varIndex)) continue;

          // Skip if it's a known annotation
          if (validAnnotations.includes(varName)) continue;

          // Skip if it's part of an annotation
          const beforeVar = lineText.substring(Math.max(0, varIndex - 20), varIndex);
          if (beforeVar.includes("@")) continue;

          // Skip if it's a namespace prefix (followed by colon, e.g., "collections:")
          const afterVar = lineText.substring(
            varIndex + varName.length,
            varIndex + varName.length + 1,
          );
          if (afterVar === ":") continue;

          // This is a variable in an expression - must be uppercase
          const posKey = `${lineStart + varIndex}-${varName}`;
          if (flaggedPositions.has(posKey)) continue; // Already flagged by another pattern
          flaggedPositions.add(posKey);

          const suggestedName = varName.charAt(0).toUpperCase() + varName.slice(1);
          diagnostics.push({
            from: lineStart + varIndex,
            to: lineStart + varIndex + varName.length,
            severity: "error",
            message: `Variables must start with an uppercase letter: ${varName}. Use ${suggestedName} instead.`,
            markClass: "cm-error-highlight",
          });
        }

        // Pattern 3b: Variables BEFORE operators in comparisons: x = Y -> x should be X
        const varBeforeOperatorPattern = /\b([a-z][a-zA-Z0-9_]*)\s*[=!<>]/g;
        while ((varMatch = varBeforeOperatorPattern.exec(lineText)) !== null) {
          const varName = varMatch[1];
          const varIndex = varMatch.index;

          // Skip if this is a predicate name
          if (isPredicateName(varIndex, varName)) continue;

          // Skip if inside a string
          if (isInString(varIndex)) continue;

          // Skip if inside a parameter ${...}
          if (isInParameter(varIndex)) continue;

          // Skip if it's a known annotation
          if (validAnnotations.includes(varName)) continue;

          // Skip if it's part of an annotation
          const beforeVar = lineText.substring(Math.max(0, varIndex - 20), varIndex);
          if (beforeVar.includes("@")) continue;

          // Skip if preceded by ':-' or '<-' (it's a predicate in rule head)
          if (beforeVar.includes(":-") || beforeVar.includes("<-")) continue;

          // Skip if it's a namespace prefix (followed by colon, e.g., "collections:")
          const afterVar = lineText.substring(
            varIndex + varName.length,
            varIndex + varName.length + 1,
          );
          if (afterVar === ":") continue;

          // This is a variable before an operator - must be uppercase
          const posKey = `${lineStart + varIndex}-${varName}`;
          if (flaggedPositions.has(posKey)) continue; // Already flagged by another pattern
          flaggedPositions.add(posKey);

          const suggestedName = varName.charAt(0).toUpperCase() + varName.slice(1);
          diagnostics.push({
            from: lineStart + varIndex,
            to: lineStart + varIndex + varName.length,
            severity: "error",
            message: `Variables must start with an uppercase letter: ${varName}. Use ${suggestedName} instead.`,
            markClass: "cm-error-highlight",
          });
        }
      }
    });

    // Variable analysis for rules (head vs body, joins, aggregations)
    // Process each rule separately - handle multi-line rules

    // Helper function to find the actual end of a rule (period not inside a string)
    const findRuleEnd = (searchText: string, startPos: number): number | null => {
      let inString = false;
      let strChar: string | null = null;
      let escaped = false;

      for (let i = startPos; i < searchText.length; i++) {
        const char = searchText[i];

        if (escaped) {
          escaped = false;
          continue;
        }

        if (char === "\\") {
          escaped = true;
          continue;
        }

        if (!inString && (char === '"' || char === "'")) {
          inString = true;
          strChar = char;
        } else if (inString && char === strChar) {
          inString = false;
          strChar = null;
        }

        // Found a period that's not inside a string - this is the rule end
        if (!inString && char === ".") {
          return i;
        }
      }

      return null; // No period found
    };

    // Find all rules by looking for ":-" or "<-" pattern and then finding the actual rule end
    const rules: Array<{
      head: string;
      body: string;
      ruleStart: number;
      fullMatch: string;
      operator: string;
    }> = [];
    const headPattern = /([a-z_][a-zA-Z0-9_]*\s*\([^)]*\))\s*(:-|<-)\s*/g;
    let headMatch;

    while ((headMatch = headPattern.exec(text)) !== null) {
      const ruleStart = headMatch.index;
      const head = headMatch[1];
      const operator = headMatch[2];
      const bodyStartPos = headMatch.index + headMatch[0].length;

      // Skip if this rule is in a commented line
      if (isInCommentedLine(ruleStart)) continue;

      // Find the actual end of the rule (period not inside a string)
      const ruleEndPos = findRuleEnd(text, bodyStartPos);
      if (ruleEndPos === null) continue; // No period found, skip this rule

      const body = text.substring(bodyStartPos, ruleEndPos);
      const fullMatch = text.substring(ruleStart, ruleEndPos + 1);
      rules.push({
        head,
        body,
        ruleStart,
        fullMatch,
        operator,
      });
    }

    // Precompute ranges for Cypher-in-body rules so we can ignore diagnostics
    // that fall inside the Cypher payload. A body that starts with a Cypher
    // keyword (after the `<-` operator) is parsed as Cypher by the reasoner and
    // pushed down to Neo4j, so it must not be validated as Vadalog.
    const cypherBodyRanges: { from: number; to: number }[] = [];
    const cypherBodyStartPattern = /^(MATCH|OPTIONAL|UNWIND|CALL|CREATE|MERGE)\b/i;
    for (const rule of rules) {
      if (rule.operator !== "<-") continue;
      if (!cypherBodyStartPattern.test(rule.body.trim())) continue;
      const operatorPos = rule.fullMatch.indexOf(rule.operator);
      const bodyTextStart = rule.fullMatch.indexOf(rule.body, operatorPos + rule.operator.length);
      if (bodyTextStart === -1) continue;
      const from = rule.ruleStart + bodyTextStart;
      cypherBodyRanges.push({ from, to: from + rule.body.length });
    }

    const isInCypherBodyRange = (pos: number): boolean =>
      cypherBodyRanges.some((range) => pos >= range.from && pos < range.to);

    // Track predicate arities to detect inconsistencies
    const predicateArities = new Map<
      string,
      Map<number, Array<{ from: number; to: number; name: string }>>
    >();

    // Helper to extract predicate name and arity from a predicate call
    const extractPredicateInfo = (
      predicateText: string,
      startPos: number,
    ): { name: string; arity: number; from: number; to: number } | null => {
      // Match predicate name and arguments: e.g., "owns(X, Y)" or "person(X, Y, Z)"
      const predMatch = predicateText.match(/^([a-z_][a-zA-Z0-9_]*)\s*\(([^)]*)\)/);
      if (!predMatch) return null;

      const predName = predMatch[1];
      const argsText = predMatch[2].trim();

      // Count arguments (handle empty args, commas, and nested structures)
      let arity = 0;
      if (argsText.length > 0) {
        // Count commas, but be careful with nested parentheses and strings
        let depth = 0;
        let inString = false;
        let strChar: string | null = null;
        let escaped = false;

        for (let i = 0; i < argsText.length; i++) {
          const char = argsText[i];

          if (escaped) {
            escaped = false;
            continue;
          }

          if (char === "\\") {
            escaped = true;
            continue;
          }

          if (!inString && (char === '"' || char === "'")) {
            inString = true;
            strChar = char;
          } else if (inString && char === strChar) {
            inString = false;
            strChar = null;
          }

          if (!inString) {
            if (char === "(") depth++;
            else if (char === ")") depth--;
            else if (char === "," && depth === 0) arity++;
          }
        }
        arity++; // Number of commas + 1 = number of arguments
      }

      const fullMatchStart = predicateText.indexOf(predMatch[0]);
      const fullMatchEnd = fullMatchStart + predMatch[0].length;

      return {
        name: predName,
        arity: arity,
        from: startPos + fullMatchStart,
        to: startPos + fullMatchEnd,
      };
    };

    // Helper to extract variables from text, skipping strings and ${} parameters
    const extractVariables = (
      text: string,
      startPos: number = 0,
    ): Array<{ name: string; pos: number }> => {
      const vars: Array<{ name: string; pos: number }> = [];
      // Don't use lookbehind in the pattern - we'll check manually
      const varPattern = /([A-Z][a-zA-Z0-9_]*)/g;
      let match;

      while ((match = varPattern.exec(text)) !== null) {
        // Check if preceded by valid boundary
        if (match.index > 0) {
          const charBefore = text[match.index - 1];
          if (/[a-zA-Z0-9_]/.test(charBefore)) {
            continue; // Not a valid variable start
          }
        }

        // Check if followed by valid boundary
        const endPos = match.index + match[1].length;
        if (endPos < text.length) {
          const charAfter = text[endPos];
          if (/[a-zA-Z0-9_]/.test(charAfter)) {
            continue; // Not a valid variable end
          }
        }

        const varPos = startPos + match.index;

        // Skip if inside a string
        let inString = false;
        let strChar: string | null = null;
        let escaped = false;
        for (let i = 0; i < match.index; i++) {
          if (escaped) {
            escaped = false;
            continue;
          }
          if (text[i] === "\\") {
            escaped = true;
            continue;
          }
          if (!inString && (text[i] === '"' || text[i] === "'")) {
            inString = true;
            strChar = text[i];
          } else if (inString && text[i] === strChar) {
            inString = false;
            strChar = null;
          }
        }
        if (inString) continue;

        // Skip if inside ${...}
        let inParam = false;
        for (let i = match.index - 1; i >= 0; i--) {
          if (i > 0 && text[i - 1] === "$" && text[i] === "{") {
            // Find matching }
            for (let j = i + 1; j < text.length; j++) {
              if (text[j] === "}" && (j === i + 1 || text[j - 1] !== "\\")) {
                if (match.index > i && match.index < j) {
                  inParam = true;
                }
                break;
              }
            }
            break;
          }
        }
        if (inParam) continue;

        vars.push({ name: match[1], pos: varPos });
      }

      return vars;
    };

    // Also track standalone facts (predicates without bodies)
    // Match facts that are on lines without ':-' (not rule heads)
    const factPattern = /([a-z_][a-zA-Z0-9_]*\s*\([^)]*\))\s*\./g;
    let factMatch;
    while ((factMatch = factPattern.exec(text)) !== null) {
      // Skip if in commented line
      if (isInCommentedLine(factMatch.index)) continue;

      // Check if this fact is on a line that contains ':-' (then it's a rule head, skip)
      const factLineStart = text.lastIndexOf("\n", factMatch.index) + 1;
      const factLineEnd = text.indexOf("\n", factMatch.index);
      const factLine =
        factLineEnd === -1
          ? text.substring(factLineStart)
          : text.substring(factLineStart, factLineEnd);

      if (factLine.includes(":-") || factLine.includes("<-")) continue; // Rule head, already handled

      const factText = factMatch[1];
      const factInfo = extractPredicateInfo(factText, factMatch.index);
      if (factInfo) {
        if (!predicateArities.has(factInfo.name)) {
          predicateArities.set(factInfo.name, new Map());
        }
        const arityMap = predicateArities.get(factInfo.name)!;
        if (!arityMap.has(factInfo.arity)) {
          arityMap.set(factInfo.arity, []);
        }
        arityMap.get(factInfo.arity)!.push({
          from: factInfo.from,
          to: factInfo.to,
          name: factInfo.name,
        });
      }
    }

    // Track predicates defined via SQL-style rules: pred(...) <- select ... from ...
    // SQL-style heads with empty parens (arity 0) are valid — the actual arity
    // is determined by the SELECT clause, so we exempt them from arity checks.
    const sqlStyleZeroArityHeads = new Set<string>();
    const sqlRulePattern = /([a-z_][a-zA-Z0-9_]*\s*\([^)]*\))\s*<-\s*/g;
    let sqlMatch;
    while ((sqlMatch = sqlRulePattern.exec(text)) !== null) {
      if (isInCommentedLine(sqlMatch.index)) continue;
      const sqlHeadInfo = extractPredicateInfo(sqlMatch[1], sqlMatch.index);
      if (sqlHeadInfo) {
        if (sqlHeadInfo.arity === 0) {
          sqlStyleZeroArityHeads.add(sqlHeadInfo.name);
        }
        if (!predicateArities.has(sqlHeadInfo.name)) {
          predicateArities.set(sqlHeadInfo.name, new Map());
        }
        const arityMap = predicateArities.get(sqlHeadInfo.name)!;
        if (!arityMap.has(sqlHeadInfo.arity)) {
          arityMap.set(sqlHeadInfo.arity, []);
        }
        arityMap.get(sqlHeadInfo.arity)!.push({
          from: sqlHeadInfo.from,
          to: sqlHeadInfo.to,
          name: sqlHeadInfo.name,
        });
      }
    }

    // Check for multi-line rules without periods using stateful tracking
    // Helper to extract rule part before comment
    const getRulePart = (lineText: string): string => {
      const trimmed = lineText.trim();
      const commentIndex = trimmed.indexOf("%");
      return commentIndex !== -1 ? trimmed.substring(0, commentIndex).trimEnd() : trimmed;
    };

    let inRule = false;
    let _ruleStartLine = -1;
    let lastNonEmptyLine = -1;
    let lastNonEmptyContent = "";
    let lastNonEmptyLineContent = "";

    // Track annotation state for multi-line annotations
    let inAnnotation = false;
    let _annotationStartLine = -1;
    let lastAnnotationLine = -1;
    let lastAnnotationContent = "";
    let lastAnnotationLineContent = "";

    // Helper to check if a line ends an annotation (has closing paren followed by period)
    const annotationEnds = (lineText: string): boolean => {
      const part = getRulePart(lineText);
      // Check if line has closing parenthesis followed by period
      const parenIndex = part.lastIndexOf(")");
      if (parenIndex !== -1) {
        const afterParen = part.substring(parenIndex + 1).trim();
        return afterParen === "." || afterParen.startsWith(".");
      }
      return false;
    };

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const trimmed = line.trim();

      // Skip empty lines and comments
      if (trimmed === "" || trimmed.startsWith("%")) {
        // If we're in a rule and hit blank line, the rule should have ended
        if (inRule && trimmed === "") {
          // Check if the last non-empty line ended with period (before any comment)
          const lastRulePart = getRulePart(lastNonEmptyContent);
          if (!lastRulePart.endsWith(".")) {
            const lineStart = doc.line(lastNonEmptyLine + 1).from;
            // Find the last non-whitespace character in the actual line
            const trimmedLine = lastNonEmptyLineContent.trimEnd();
            const lastCharPos = lineStart + trimmedLine.length;
            // Skip if in commented line (shouldn't happen since we skip comments, but safety check)
            if (!isInCommentedLine(lastCharPos)) {
              diagnostics.push({
                from: lastCharPos,
                to: lastCharPos + 1,
                severity: "error",
                message: "Rules must end with a period (.)",
                markClass: "cm-error-highlight",
              });
            }
          }
          inRule = false;
        }
        // If we're in an annotation and hit blank line, the annotation should have ended
        if (inAnnotation && trimmed === "") {
          const _lastAnnotationPart = getRulePart(lastAnnotationContent);
          if (!annotationEnds(lastAnnotationContent)) {
            const lineStart = doc.line(lastAnnotationLine + 1).from;
            const trimmedLine = lastAnnotationLineContent.trimEnd();
            const lastCharPos = lineStart + trimmedLine.length;
            if (!isInCommentedLine(lastCharPos)) {
              diagnostics.push({
                from: lastCharPos,
                to: lastCharPos + 1,
                severity: "error",
                message: "Annotations must end with a period (.)",
                markClass: "cm-error-highlight",
              });
            }
          }
          inAnnotation = false;
        }
        continue;
      }

      // Check if this line starts a new rule
      if ((trimmed.includes(":-") || trimmed.includes("<-")) && !trimmed.startsWith("@")) {
        // If we were in a rule before, it should have ended with period
        if (inRule) {
          const lastRulePart = getRulePart(lastNonEmptyContent);
          if (!lastRulePart.endsWith(".")) {
            const lineStart = doc.line(lastNonEmptyLine + 1).from;
            // Find the last non-whitespace character in the actual line
            const trimmedLine = lastNonEmptyLineContent.trimEnd();
            const lastCharPos = lineStart + trimmedLine.length;
            // Skip if in commented line (shouldn't happen since we skip comments, but safety check)
            if (!isInCommentedLine(lastCharPos)) {
              diagnostics.push({
                from: lastCharPos,
                to: lastCharPos + 1,
                severity: "error",
                message: "Rules must end with a period (.)",
                markClass: "cm-error-highlight",
              });
            }
          }
        }
        // If we were in an annotation, it should have ended with period
        if (inAnnotation) {
          const _lastAnnotationPart = getRulePart(lastAnnotationContent);
          if (!annotationEnds(lastAnnotationContent)) {
            const lineStart = doc.line(lastAnnotationLine + 1).from;
            const trimmedLine = lastAnnotationLineContent.trimEnd();
            const lastCharPos = lineStart + trimmedLine.length;
            if (!isInCommentedLine(lastCharPos)) {
              diagnostics.push({
                from: lastCharPos,
                to: lastCharPos + 1,
                severity: "error",
                message: "Annotations must end with a period (.)",
                markClass: "cm-error-highlight",
              });
            }
          }
          inAnnotation = false;
        }
        inRule = true;
        _ruleStartLine = i;
      }

      // Check if this line starts a new annotation or fact
      if (trimmed.startsWith("@")) {
        // If we were in a rule, it should have ended with period
        if (inRule) {
          const lastRulePart = getRulePart(lastNonEmptyContent);
          if (!lastRulePart.endsWith(".")) {
            const lineStart = doc.line(lastNonEmptyLine + 1).from;
            // Find the last non-whitespace character in the actual line
            const trimmedLine = lastNonEmptyLineContent.trimEnd();
            const lastCharPos = lineStart + trimmedLine.length;
            // Skip if in commented line (shouldn't happen since we skip comments, but safety check)
            if (!isInCommentedLine(lastCharPos)) {
              diagnostics.push({
                from: lastCharPos,
                to: lastCharPos + 1,
                severity: "error",
                message: "Rules must end with a period (.)",
                markClass: "cm-error-highlight",
              });
            }
          }
        }
        // If we were in an annotation, it should have ended with period
        if (inAnnotation) {
          const _lastAnnotationPart = getRulePart(lastAnnotationContent);
          if (!annotationEnds(lastAnnotationContent)) {
            const lineStart = doc.line(lastAnnotationLine + 1).from;
            const trimmedLine = lastAnnotationLineContent.trimEnd();
            const lastCharPos = lineStart + trimmedLine.length;
            if (!isInCommentedLine(lastCharPos)) {
              diagnostics.push({
                from: lastCharPos,
                to: lastCharPos + 1,
                severity: "error",
                message: "Annotations must end with a period (.)",
                markClass: "cm-error-highlight",
              });
            }
          }
        }
        inRule = false;
        inAnnotation = true;
        _annotationStartLine = i;
      }

      // If line ends with period (before any comment), rule is complete
      const rulePart = getRulePart(trimmed);
      if (rulePart.endsWith(".")) {
        inRule = false;
      }

      // If annotation line ends with closing paren and period, annotation is complete
      if (inAnnotation && annotationEnds(trimmed)) {
        inAnnotation = false;
      }

      // Update tracking variables
      if (inRule) {
        lastNonEmptyLine = i;
        lastNonEmptyContent = trimmed;
        lastNonEmptyLineContent = line;
      }
      if (inAnnotation) {
        lastAnnotationLine = i;
        lastAnnotationContent = trimmed;
        lastAnnotationLineContent = line;
      }
      if (!inRule && !inAnnotation) {
        lastNonEmptyLine = i;
        lastNonEmptyContent = trimmed;
        lastNonEmptyLineContent = line;
      }
    }

    // Check if we ended while still in a rule
    if (inRule) {
      const lastRulePart = getRulePart(lastNonEmptyContent);
      if (!lastRulePart.endsWith(".")) {
        const lineStart = doc.line(lastNonEmptyLine + 1).from;
        // Find the last non-whitespace character in the actual line
        const trimmedLine = lastNonEmptyLineContent.trimEnd();
        const lastCharPos = lineStart + trimmedLine.length;
        // Skip if in commented line (shouldn't happen since we skip comments, but safety check)
        if (!isInCommentedLine(lastCharPos)) {
          diagnostics.push({
            from: lastCharPos,
            to: lastCharPos + 1,
            severity: "error",
            message: "Rules must end with a period (.)",
            markClass: "cm-error-highlight",
          });
        }
      }
    }

    // Check if we ended while still in an annotation
    if (inAnnotation) {
      const _lastAnnotationPart = getRulePart(lastAnnotationContent);
      if (!annotationEnds(lastAnnotationContent)) {
        const lineStart = doc.line(lastAnnotationLine + 1).from;
        const trimmedLine = lastAnnotationLineContent.trimEnd();
        const lastCharPos = lineStart + trimmedLine.length;
        if (!isInCommentedLine(lastCharPos)) {
          diagnostics.push({
            from: lastCharPos,
            to: lastCharPos + 1,
            severity: "error",
            message: "Annotations must end with a period (.)",
            markClass: "cm-error-highlight",
          });
        }
      }
    }

    for (const rule of rules) {
      const { head, body, ruleStart, fullMatch, operator } = rule;

      // Extract variables from head
      const headVarMatches = extractVariables(head, ruleStart);
      const _headVars = new Set(headVarMatches.map((v) => v.name));

      // Extract variables from body
      const operatorPos = fullMatch.indexOf(operator);
      // After the operator there's usually a space, so we need to account for the actual start of body text
      const bodyTextStart = fullMatch.indexOf(body, operatorPos + operator.length);
      const bodyStart = ruleStart + bodyTextStart;
      const bodyVarMatches = extractVariables(body, bodyStart);
      const bodyVars = new Set(bodyVarMatches.map((v) => v.name));

      // Also check for variables on the left-hand side of assignments (e.g., "CODE = ...")
      // These are also considered "used" in the body, even if extractVariables didn't find them
      // (this handles cases where the variable appears as "CODE = if(...)" which should be recognized as usage)
      const assignmentPattern = /\b([A-Z][a-zA-Z0-9_]*)\s*=/g;
      let assignMatch;
      while ((assignMatch = assignmentPattern.exec(body)) !== null) {
        const varName = assignMatch[1];
        // Skip if inside a string (shouldn't happen with our pattern, but safety check)
        let inString = false;
        let strChar: string | null = null;
        let escaped = false;
        for (let i = 0; i < assignMatch.index; i++) {
          if (escaped) {
            escaped = false;
            continue;
          }
          if (body[i] === "\\") {
            escaped = true;
            continue;
          }
          if (!inString && (body[i] === '"' || body[i] === "'")) {
            inString = true;
            strChar = body[i];
          } else if (inString && body[i] === strChar) {
            inString = false;
            strChar = null;
          }
        }
        if (!inString) {
          // Variable on left-hand side of assignment is considered used
          bodyVars.add(varName);
        }
      }

      // Track predicate arities: extract from head
      const headPredInfo = extractPredicateInfo(head, ruleStart);
      if (headPredInfo) {
        if (!predicateArities.has(headPredInfo.name)) {
          predicateArities.set(headPredInfo.name, new Map());
        }
        const arityMap = predicateArities.get(headPredInfo.name)!;
        if (!arityMap.has(headPredInfo.arity)) {
          arityMap.set(headPredInfo.arity, []);
        }
        arityMap.get(headPredInfo.arity)!.push({
          from: headPredInfo.from,
          to: headPredInfo.to,
          name: headPredInfo.name,
        });
      }

      // Track predicate arities: extract all predicates from body
      // Match all predicate calls in the body (e.g., "owns(X, Y), person(X)")
      const bodyPredicatePattern = /([a-z_][a-zA-Z0-9_]*\s*\([^)]*\))/g;
      let bodyPredMatch;
      while ((bodyPredMatch = bodyPredicatePattern.exec(body)) !== null) {
        const predText = bodyPredMatch[1];
        const predStartInBody = bodyPredMatch.index;
        const predInfo = extractPredicateInfo(predText, bodyStart + predStartInBody);
        if (predInfo) {
          // Skip aggregation functions and built-in functions (they're not predicates)
          const aggFunctions = [
            "SUM",
            "COUNT",
            "AVG",
            "MIN",
            "MAX",
            "GROUP_CONCAT",
            "COUNT_DISTINCT",
            "MCOUNT",
            "MSUM",
            "MPROD",
            "MAVG",
            "MUNION",
            "MMAX",
            "MMIN",
          ];
          if (aggFunctions.includes(predInfo.name.toUpperCase())) continue;

          // Skip graph analytics functions (they start with # but we're checking the name part)
          const graphFunctions = [
            "TC",
            "PATHS",
            "ASP",
            "SSSP",
            "BFS",
            "PR",
            "CC",
            "WCC",
            "TRI",
            "BC",
            "DC",
          ];
          if (graphFunctions.includes(predInfo.name.toUpperCase())) continue;

          // Skip string functions
          const stringFunctions = [
            "SUBSTRING",
            "CONTAINS",
            "CONTAINS_ANY",
            "STARTS_WITH",
            "ENDS_WITH",
            "CONCAT",
            "CONCAT_WS",
            "REPLACE",
            "JOIN",
            "INDEX_OF",
            "STRING_LENGTH",
            "TO_LOWER",
            "TO_UPPER",
            "SPLIT",
            "IS_EMPTY",
          ];
          if (stringFunctions.includes(predInfo.name.toUpperCase())) continue;

          // Skip type casting functions
          const typeCastFunctions = [
            "AS_STRING",
            "AS_INT",
            "AS_LONG",
            "AS_DOUBLE",
            "AS_FLOAT",
            "AS_BOOLEAN",
            "AS_DATE",
            "AS_TIMESTAMP",
            "AS_JSON",
            "AS_LIST",
            "AS_SET",
            "AS_MAP",
          ];
          if (typeCastFunctions.includes(predInfo.name.toUpperCase())) continue;

          // Skip interval operators
          const intervalOperators = ["BETWEEN", "_BETWEEN", "BETWEEN_", "_BETWEEN_"];
          if (intervalOperators.includes(predInfo.name.toUpperCase())) continue;

          // Skip logical operators (expressions, not predicates)
          const logicalOperators = [
            "AND",
            "OR",
            "NOT",
            "XOR",
            "NAND",
            "NOR",
            "XNOR",
            "IMPLIES",
            "IFF",
            "IF",
          ];
          if (logicalOperators.includes(predInfo.name.toUpperCase())) continue;

          // Skip null operators (expressions, not predicates)
          const nullOperators = ["IS_NULL", "IS_NOT_NULL"];
          if (nullOperators.includes(predInfo.name.toUpperCase())) continue;

          // Skip utility functions
          const utilityFunctions = [
            "STRUCT",
            "UUID",
            "MONOTONICALLY_INCREASING_ID",
            "TRANSFORM",
            "FILTER",
            "MASK",
          ];
          if (utilityFunctions.includes(predInfo.name.toUpperCase())) continue;

          // Skip if it's a namespace-prefixed function (collections:, math:, hash:, date:, utils:, anonymization:, kalmanFilter:, embeddings:, llm:)
          // Check the text before the predicate to see if there's a namespace prefix
          const textBeforePred = text.substring(Math.max(0, predInfo.from - 50), predInfo.from);
          const namespacePatterns = [
            /collections:\s*$/i,
            /math:\s*$/i,
            /hash:\s*$/i,
            /date:\s*$/i,
            /utils:\s*$/i,
            /anonymization:\s*$/i,
            /kalmanFilter:\s*$/i,
            /embeddings:\s*$/i,
            /llm:\s*$/i,
          ];
          const isNamespaceFunction = namespacePatterns.some((pattern) =>
            pattern.test(textBeforePred),
          );
          if (isNamespaceFunction) continue;

          // Also check for namespace functions by name (in case they're used without explicit namespace in some contexts)
          const namespaceFunctionNames = [
            // collections: functions
            "SIZE",
            "IS_EMPTY",
            "CONTAINS",
            "CONTAINS_ALL",
            "ADD",
            "REMOVE",
            "GET",
            "UNION",
            "DIFFERENCE",
            "INTERSECTION",
            "SORT",
            "DISTINCT",
            "REMOVE_NULLS",
            "SHUFFLE",
            "EXPLODE",
            "SLICE",
            "SUB_ARRAY",
            "TRANSFORM",
            "FILTER",
            "MAP",
            // math: functions
            "MOD",
            "SQRT",
            "ABS",
            "ROUND",
            "BROUND",
            "LOG",
            "LOG10",
            "POW",
            "EXP",
            "CEIL",
            "FLOOR",
            "SIN",
            "COS",
            "TAN",
            "UNIFORM",
            "RAND",
            "PI",
            "E",
            // hash: functions
            "HASH",
            "SHA1",
            "MD5",
            "SHA2",
            // date: functions
            "CURRENT_DATE",
            "CURRENT_TIMESTAMP",
            "NEXT_DAY",
            "PREV_DAY",
            "ADD",
            "SUB",
            "DIFF",
            "SPEC_DAY",
            "TO_TIMESTAMP",
            "FORMAT",
            // utils: functions
            "PHONE_NUMBER",
            // anonymization: functions
            "RISK",
            "MSU",
            // kalmanFilter: functions
            "FAULT",
            "EXTRACTOR",
            // embeddings: functions
            "VECTORIZE",
            "COSINE_SIM_UDF",
            "COSINE_SIM",
            // llm: functions
            "GENERATE",
          ];
          if (namespaceFunctionNames.includes(predInfo.name.toUpperCase())) continue;

          if (!predicateArities.has(predInfo.name)) {
            predicateArities.set(predInfo.name, new Map());
          }
          const arityMap = predicateArities.get(predInfo.name)!;
          if (!arityMap.has(predInfo.arity)) {
            arityMap.set(predInfo.arity, []);
          }
          arityMap.get(predInfo.arity)!.push({
            from: predInfo.from,
            to: predInfo.to,
            name: predInfo.name,
          });
        }
      }

      // Find variables in head but not in body
      const headOnlyVars = headVarMatches.filter((v) => !bodyVars.has(v.name));
      const headOnlyVarNames = new Set(headOnlyVars.map((v) => v.name));

      for (const varMatch of headOnlyVars) {
        // Only warn once per variable name
        if (headOnlyVarNames.has(varMatch.name)) {
          headOnlyVarNames.delete(varMatch.name); // Remove so we don't warn again
          // Skip if in commented line
          if (isInCommentedLine(varMatch.pos)) continue;
          diagnostics.push({
            from: varMatch.pos,
            to: varMatch.pos + varMatch.name.length,
            severity: "warning",
            message: `${varMatch.name} declared in head but not used in body`,
            markClass: "cm-header-only-variable",
          });
        }
      }

      // Find join variables (variables that appear in multiple body predicates)
      // Split body by commas but keep track of original positions
      const bodyPredicates: Array<{ text: string; startInBody: number }> = [];
      let currentPos = 0;
      const parts = body.split(",");

      for (let i = 0; i < parts.length; i++) {
        const part = parts[i];
        const trimmed = part.trim();
        if (trimmed && !trimmed.startsWith("%")) {
          // Find where the trimmed part actually starts in the original body
          const trimStart = part.indexOf(trimmed);
          bodyPredicates.push({
            text: trimmed,
            startInBody: currentPos + trimStart,
          });
        }
        currentPos += part.length + 1; // +1 for the comma
      }

      const varOccurrences = new Map<string, number>();
      const varInPredicates = new Map<string, Set<number>>(); // Track which predicates contain each variable

      for (let predIndex = 0; predIndex < bodyPredicates.length; predIndex++) {
        const pred = bodyPredicates[predIndex];
        const predVars = extractVariables(pred.text, bodyStart + pred.startInBody);

        for (const v of predVars) {
          const count = varOccurrences.get(v.name) || 0;
          varOccurrences.set(v.name, count + 1);

          if (!varInPredicates.has(v.name)) {
            varInPredicates.set(v.name, new Set());
          }
          varInPredicates.get(v.name)!.add(predIndex);
        }
      }

      // Track which diagnostics we've already added to avoid duplicates
      const highlightedPositions = new Set<string>();

      // First, mark aggregation variables (higher priority)
      const aggregationVars = new Set<string>();
      const aggregationPattern =
        /\b(SUM|COUNT|AVG|MIN|MAX|GROUP_CONCAT|COUNT_DISTINCT|MCOUNT|MSUM|MPROD|MAVG|MUNION|MMAX|MMIN)\s*\(\s*([A-Z][a-zA-Z0-9_]*)\s*\)/gi;
      let aggMatch;
      while ((aggMatch = aggregationPattern.exec(body)) !== null) {
        aggregationVars.add(aggMatch[2]);
      }

      // Highlight join variables (appear in 2+ predicates) - but not aggregation vars
      const joinVars = new Map<string, number>();
      for (const [varName, count] of varOccurrences.entries()) {
        if (
          count >= 2 &&
          varInPredicates.get(varName)!.size >= 2 &&
          !aggregationVars.has(varName)
        ) {
          joinVars.set(varName, varInPredicates.get(varName)!.size);
        }
      }

      // Highlight each occurrence of join variables (without duplicates)
      for (const varMatch of bodyVarMatches) {
        if (joinVars.has(varMatch.name)) {
          const posKey = `${varMatch.pos}-${varMatch.name}`;
          if (!highlightedPositions.has(posKey)) {
            highlightedPositions.add(posKey);
            // Skip if in commented line
            if (isInCommentedLine(varMatch.pos)) continue;

            diagnostics.push({
              from: varMatch.pos,
              to: varMatch.pos + varMatch.name.length,
              severity: "info",
              message: `Join variable appears in ${joinVars.get(varMatch.name)} predicates`,
              markClass: "cm-join-variable-highlight",
            });
          }
        }
      }

      // Aggregation variable highlighting removed per user request
    }

    // Check for predicate arity inconsistencies
    // Define all built-in functions that should be excluded from arity checks
    const aggFunctions = [
      "SUM",
      "COUNT",
      "AVG",
      "MIN",
      "MAX",
      "GROUP_CONCAT",
      "COUNT_DISTINCT",
      "MCOUNT",
      "MSUM",
      "MPROD",
      "MAVG",
      "MUNION",
      "MMAX",
      "MMIN",
    ];
    const graphFunctions = [
      "TC",
      "PATHS",
      "ASP",
      "SSSP",
      "BFS",
      "PR",
      "CC",
      "WCC",
      "TRI",
      "BC",
      "DC",
    ];
    const stringFunctions = [
      "SUBSTRING",
      "CONTAINS",
      "CONTAINS_ANY",
      "STARTS_WITH",
      "ENDS_WITH",
      "CONCAT",
      "CONCAT_WS",
      "REPLACE",
      "JOIN",
      "INDEX_OF",
      "STRING_LENGTH",
      "TO_LOWER",
      "TO_UPPER",
      "SPLIT",
      "IS_EMPTY",
    ];
    const typeCastFunctions = [
      "AS_STRING",
      "AS_INT",
      "AS_LONG",
      "AS_DOUBLE",
      "AS_FLOAT",
      "AS_BOOLEAN",
      "AS_DATE",
      "AS_TIMESTAMP",
      "AS_JSON",
      "AS_LIST",
      "AS_SET",
      "AS_MAP",
    ];
    const intervalOperators = ["BETWEEN", "_BETWEEN", "BETWEEN_", "_BETWEEN_"];
    const logicalOperators = [
      "AND",
      "OR",
      "NOT",
      "XOR",
      "NAND",
      "NOR",
      "XNOR",
      "IMPLIES",
      "IFF",
      "IF",
    ];
    const nullOperators = ["IS_NULL", "IS_NOT_NULL"];
    const utilityFunctions = [
      "STRUCT",
      "UUID",
      "MONOTONICALLY_INCREASING_ID",
      "TRANSFORM",
      "FILTER",
      "MASK",
    ];
    const namespaceFunctionNames = [
      // collections: functions
      "SIZE",
      "IS_EMPTY",
      "CONTAINS",
      "CONTAINS_ALL",
      "ADD",
      "REMOVE",
      "GET",
      "UNION",
      "DIFFERENCE",
      "INTERSECTION",
      "SORT",
      "DISTINCT",
      "REMOVE_NULLS",
      "SHUFFLE",
      "EXPLODE",
      "SLICE",
      "SUB_ARRAY",
      "TRANSFORM",
      "FILTER",
      "MAP",
      // math: functions
      "MOD",
      "SQRT",
      "ABS",
      "ROUND",
      "BROUND",
      "LOG",
      "LOG10",
      "POW",
      "EXP",
      "CEIL",
      "FLOOR",
      "SIN",
      "COS",
      "TAN",
      "UNIFORM",
      "RAND",
      "PI",
      "E",
      // hash: functions
      "HASH",
      "SHA1",
      "MD5",
      "SHA2",
      // date: functions (note: ADD conflicts with collections:add, but both are functions)
      "CURRENT_DATE",
      "CURRENT_TIMESTAMP",
      "NEXT_DAY",
      "PREV_DAY",
      "SUB",
      "DIFF",
      "SPEC_DAY",
      "TO_TIMESTAMP",
      "FORMAT",
      // utils: functions
      "PHONE_NUMBER",
      // anonymization: functions
      "RISK",
      "MSU",
      // kalmanFilter: functions
      "FAULT",
      "EXTRACTOR",
      // embeddings: functions
      "VECTORIZE",
      "COSINE_SIM_UDF",
      "COSINE_SIM",
      // llm: functions
      "GENERATE",
    ];
    const allBuiltInFunctions = [
      ...aggFunctions,
      ...graphFunctions,
      ...stringFunctions,
      ...typeCastFunctions,
      ...intervalOperators,
      ...logicalOperators,
      ...nullOperators,
      ...utilityFunctions,
      ...namespaceFunctionNames,
    ];

    for (const [predName, arityMap] of predicateArities.entries()) {
      // Skip all built-in functions - they can have variable arity
      if (allBuiltInFunctions.includes(predName.toUpperCase())) continue;

      // Exclude arity 0 from consistency checks when it comes from a SQL-style (<-) head,
      // since the actual arity is determined by the SELECT clause, not the head parens.
      const arities = sqlStyleZeroArityHeads.has(predName)
        ? Array.from(arityMap.keys()).filter((a) => a !== 0)
        : Array.from(arityMap.keys());
      if (arities.length > 1) {
        const _arityList = arities.sort((a, b) => a - b).join(", ");
        for (const [arity, occurrences] of arityMap.entries()) {
          if (sqlStyleZeroArityHeads.has(predName) && arity === 0) continue;
          for (const occ of occurrences) {
            // Skip if in commented line
            if (isInCommentedLine(occ.from)) continue;
            diagnostics.push({
              from: occ.from,
              to: occ.to,
              severity: "error",
              message: `Predicate ${predName} is used with arity ${arity}, but also with arity ${arities.filter((a) => a !== arity).join(", ")}`,
              markClass: "cm-error-highlight",
            });
          }
        }
      }
    }

    // Check if annotation first arguments reference existing predicates
    // Only check for: bind, qbind, output, mapping, model, post (not param or others)
    const definedPredicates = new Set(predicateArities.keys());
    const annotationsToCheck = ["bind", "qbind", "output", "mapping", "model", "post"];
    const annotationPattern = /@([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/g;
    let annotationMatch;

    while ((annotationMatch = annotationPattern.exec(text)) !== null) {
      const annotationStart = annotationMatch.index;
      const annotationName = annotationMatch[1];

      // Skip if in commented line
      if (isInCommentedLine(annotationStart)) continue;

      // Skip if this annotation is not one we need to check
      if (!annotationsToCheck.includes(annotationName)) {
        continue;
      }

      const afterParen = text.substring(annotationStart + annotationMatch[0].length);

      // Extract the first argument (up to comma or closing paren at top level)
      let firstArg = "";
      let depth = 0;
      let inString = false;
      let strChar: string | null = null;
      let escaped = false;

      for (let i = 0; i < afterParen.length; i++) {
        const char = afterParen[i];

        if (escaped) {
          escaped = false;
          firstArg += char;
          continue;
        }

        if (char === "\\") {
          escaped = true;
          firstArg += "\\";
          continue;
        }

        if (!inString && (char === '"' || char === "'")) {
          inString = true;
          strChar = char;
          firstArg += char;
        } else if (inString && char === strChar) {
          inString = false;
          strChar = null;
          firstArg += char;
        } else if (!inString) {
          if (char === "(") {
            depth++;
            firstArg += char;
          } else if (char === ")") {
            if (depth === 0) {
              // End of annotation arguments
              break;
            }
            depth--;
            firstArg += char;
          } else if (char === "," && depth === 0) {
            // End of first argument
            break;
          } else {
            firstArg += char;
          }
        } else {
          // Inside string
          firstArg += char;
        }
      }

      // Clean up the first argument (trim whitespace)
      const trimmedArg = firstArg.trim();

      // The first argument should always be a string literal
      // Extract the string value (remove quotes)
      let referencedPredicate: string | null = null;
      let predicateStartPos = 0;
      let predicateEndPos = 0;

      // Calculate where firstArg starts in the original text
      const firstArgStartInText = annotationStart + annotationMatch[0].length;

      if (trimmedArg.startsWith('"') && trimmedArg.endsWith('"')) {
        // Double-quoted string
        referencedPredicate = trimmedArg.slice(1, -1);
        // Find the position of the string content (after opening quote) within firstArg
        const quoteIndex = firstArg.indexOf('"');
        predicateStartPos = firstArgStartInText + quoteIndex + 1;
        predicateEndPos = predicateStartPos + referencedPredicate.length;
      } else if (trimmedArg.startsWith("'") && trimmedArg.endsWith("'")) {
        // Single-quoted string
        referencedPredicate = trimmedArg.slice(1, -1);
        // Find the position of the string content (after opening quote) within firstArg
        const quoteIndex = firstArg.indexOf("'");
        predicateStartPos = firstArgStartInText + quoteIndex + 1;
        predicateEndPos = predicateStartPos + referencedPredicate.length;
      } else {
        // Not a string literal - skip (shouldn't happen, but handle gracefully)
        continue;
      }

      // Check if the extracted string is a valid predicate name and if it exists
      if (referencedPredicate && /^[a-z_][a-zA-Z0-9_]*$/.test(referencedPredicate)) {
        // Allow bound predicates (from @bind/@qbind) and defined predicates
        if (
          !definedPredicates.has(referencedPredicate) &&
          !boundPredicates.has(referencedPredicate)
        ) {
          // Skip if in commented line
          if (isInCommentedLine(predicateStartPos)) continue;
          diagnostics.push({
            from: predicateStartPos,
            to: predicateEndPos,
            severity: "error",
            message: `Annotation @${annotationName} references predicate '${referencedPredicate}' which does not exist`,
            markClass: "cm-error-highlight",
          });
        }
      }
    }

    // Check @param annotations: verify predicate exists only if there's no ${paramName} usage
    // First, collect all parameter usages ${XXXXX}
    const paramUsages = new Set<string>();
    const paramUsagePattern = /\$\{([a-z_][a-zA-Z0-9_]*)\}/g;
    let paramUsageMatch;
    while ((paramUsageMatch = paramUsagePattern.exec(text)) !== null) {
      paramUsages.add(paramUsageMatch[1]);
    }

    // Now check @param annotations
    const paramAnnotationPattern = /@param\s*\(/g;
    let paramAnnotationMatch;

    while ((paramAnnotationMatch = paramAnnotationPattern.exec(text)) !== null) {
      const annotationStart = paramAnnotationMatch.index;

      // Skip if in commented line
      if (isInCommentedLine(annotationStart)) continue;

      const afterParen = text.substring(annotationStart + paramAnnotationMatch[0].length);

      // Extract the first argument (up to comma or closing paren at top level)
      let firstArg = "";
      let depth = 0;
      let inString = false;
      let strChar: string | null = null;
      let escaped = false;

      for (let i = 0; i < afterParen.length; i++) {
        const char = afterParen[i];

        if (escaped) {
          escaped = false;
          firstArg += char;
          continue;
        }

        if (char === "\\") {
          escaped = true;
          firstArg += "\\";
          continue;
        }

        if (!inString && (char === '"' || char === "'")) {
          inString = true;
          strChar = char;
          firstArg += char;
        } else if (inString && char === strChar) {
          inString = false;
          strChar = null;
          firstArg += char;
        } else if (!inString) {
          if (char === "(") {
            depth++;
            firstArg += char;
          } else if (char === ")") {
            if (depth === 0) {
              break;
            }
            depth--;
            firstArg += char;
          } else if (char === "," && depth === 0) {
            break;
          } else {
            firstArg += char;
          }
        } else {
          firstArg += char;
        }
      }

      // Clean up the first argument (trim whitespace)
      const trimmedArg = firstArg.trim();

      // Extract predicate name from string literal
      let referencedPredicate: string | null = null;
      let predicateStartPos = 0;
      let predicateEndPos = 0;

      const firstArgStartInText = annotationStart + paramAnnotationMatch[0].length;

      if (trimmedArg.startsWith('"') && trimmedArg.endsWith('"')) {
        referencedPredicate = trimmedArg.slice(1, -1);
        const quoteIndex = firstArg.indexOf('"');
        predicateStartPos = firstArgStartInText + quoteIndex + 1;
        predicateEndPos = predicateStartPos + referencedPredicate.length;
      } else if (trimmedArg.startsWith("'") && trimmedArg.endsWith("'")) {
        referencedPredicate = trimmedArg.slice(1, -1);
        const quoteIndex = firstArg.indexOf("'");
        predicateStartPos = firstArgStartInText + quoteIndex + 1;
        predicateEndPos = predicateStartPos + referencedPredicate.length;
      } else {
        continue;
      }

      // Check if the extracted string is a valid predicate name
      if (referencedPredicate && /^[a-z_][a-zA-Z0-9_]*$/.test(referencedPredicate)) {
        // Only check if predicate exists if there's NO ${predicate_name} usage
        if (!paramUsages.has(referencedPredicate)) {
          // Check if predicate exists (allow bound predicates and defined predicates)
          if (
            !definedPredicates.has(referencedPredicate) &&
            !boundPredicates.has(referencedPredicate)
          ) {
            // Skip if in commented line
            if (isInCommentedLine(predicateStartPos)) continue;
            diagnostics.push({
              from: predicateStartPos,
              to: predicateEndPos,
              severity: "error",
              message: `Annotation @param references predicate '${referencedPredicate}' which does not exist`,
              markClass: "cm-error-highlight",
            });
          }
        }
      }
    }

    // Final document-level checks
    if (openParens > 0 && parenPositions.length > 0) {
      const lastOpen = parenPositions[parenPositions.length - 1];
      const lineStart = doc.line(lastOpen.line).from;
      diagnostics.push({
        from: lineStart + lastOpen.col,
        to: lineStart + lastOpen.col + 1,
        severity: "error",
        message: `${openParens} unclosed parenthesis(es)`,
        markClass: "cm-error-highlight",
      });
    }

    if (openBrackets > 0) {
      diagnostics.push({
        from: doc.length - 1,
        to: doc.length,
        severity: "error",
        message: `${openBrackets} unclosed bracket(s)`,
        markClass: "cm-error-highlight",
      });
    }

    if (openBraces > 0) {
      diagnostics.push({
        from: doc.length - 1,
        to: doc.length,
        severity: "error",
        message: `${openBraces} unclosed brace(s)`,
        markClass: "cm-error-highlight",
      });
    }

    // If a string was never closed, report once at the last quote position (best effort)
    if (inString) {
      const lastQuotePos = text.lastIndexOf(stringChar ?? '"');
      const from = lastQuotePos >= 0 ? lastQuotePos : Math.max(0, text.length - 1);
      diagnostics.push({
        from,
        to: Math.min(from + 1, text.length),
        severity: "error",
        message: `Unclosed string (started with ${stringChar ?? '"'})`,
        markClass: "cm-error-highlight",
      });
    }

    // Drop diagnostics that fall inside qbind payload strings (except first
    // argument) or inside Cypher-in-body rule payloads.
    const filteredDiagnostics = diagnostics.filter(
      (d) => !isInQbindStringRange(d.from) && !isInCypherBodyRange(d.from),
    );
    return filteredDiagnostics;
  });
}
