import { useEffect, useRef } from "react";
import type { ConceptData } from "@/features/concepts/api";
import ConceptCard from "@/features/concepts/components/ConceptCard";
import { conceptParams } from "@/features/concepts/utils/paramAnnotations";
import { primaryOutput } from "../../hooks/useConceptOutputs";
import { findConceptGraph } from "../../model.utils";
import type { ConceptGraphRoles, GraphViewModel } from "../../types";
import { ConceptOutputSection } from "./ConceptOutputSection";

interface OntologyConceptCardProps {
  concept: ConceptData;
  model: GraphViewModel | null;
  activeGraphPredicate: string | null;
  isGraphBusy: boolean;
  /** Scrolls the card into view and expands it (deep-link role-picking flow). */
  isFocused?: boolean;
  onRolesChange: (predicate: string, roles: ConceptGraphRoles) => void;
  onShowGraph: (concept: ConceptData, runPredicate?: string) => void;
}

function graphButtonLabel(isBusy: boolean, isPopulated: boolean | undefined): string {
  if (isBusy) return "Loading…";
  if (isPopulated) return "Show graph";
  return "Run & show graph";
}

export function OntologyConceptCard({
  concept,
  model,
  activeGraphPredicate,
  isGraphBusy,
  isFocused,
  onRolesChange,
  onShowGraph,
}: OntologyConceptCardProps) {
  // A concept is identified by its name: the card always graphs the concept's
  // own predicate with its stored, run-refreshed schema. Intermediate rule
  // heads are never the card's output.
  const output = primaryOutput(concept);

  const cardRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!isFocused) return;
    cardRef.current?.scrollIntoView({ block: "center", behavior: "smooth" });
  }, [isFocused]);

  const roles: ConceptGraphRoles = findConceptGraph(model, concept.predicate_name)?.roles ?? {};
  const isBusy = isGraphBusy && concept.predicate_name === activeGraphPredicate;

  const footer = (
    <ConceptOutputSection
      output={output}
      roles={roles}
      isActiveGraph={concept.predicate_name === activeGraphPredicate}
      isBusy={isBusy}
      buttonLabel={graphButtonLabel(isBusy, concept.is_populated)}
      onRolesChange={(nextRoles) => onRolesChange(concept.predicate_name, nextRoles)}
      onShowGraph={() => onShowGraph(concept)}
    />
  );

  return (
    <div ref={cardRef}>
      <ConceptCard
        title={concept.predicate_name}
        description={concept.description}
        fields={{}}
        params={conceptParams(concept)}
        footer={footer}
        expandSignal={isFocused ? { open: true, nonce: 1 } : undefined}
      />
    </div>
  );
}
