import type React from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import QueryResultTable, {
  type ColumnFilterValue,
  type OrderByItem,
} from "@/features/concept-editor/components/query/components/QueryResultTable";
import { isPreviewableDataSource } from "@/features/data-sources/bind.utils";
import { useDataSources } from "@/features/data-sources/hooks/useDataSources";
import { getIconTypeForBinaryFile } from "@/features/data-sources/utils";
import DatabaseIcon from "@/shared/components/icons/DatabaseIcon";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import DatasourceDetailTabs, { type DatasourceDetailTabId } from "./DatasourceDetailTabs";
import type { DatasourcePanelInfo } from "./lineage-view/types";

interface DatasourceDetailPanelProps {
  datasource: DatasourcePanelInfo;
}

type TabId = DatasourceDetailTabId;

const LINEAGE_PREVIEW_PAGE_SIZE = 10;

const DatasourceDetailPanel: React.FC<DatasourceDetailPanelProps> = ({ datasource }) => {
  const [activeTab, setActiveTab] = useState<TabId>("details");
  const [previewData, setPreviewData] = useState<any>(null);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const [isLoadingPreview, setIsLoadingPreview] = useState(false);
  const [isFetching, setIsFetching] = useState(false);

  const orderByRef = useRef<OrderByItem[]>([]);
  const searchTermRef = useRef<string | undefined>(undefined);
  const columnFiltersRef = useRef<
    Array<{ position: number; value: string; operator?: string }> | undefined
  >(undefined);
  const pageSizeRef = useRef(LINEAGE_PREVIEW_PAGE_SIZE);

  const [searchState, setSearchState] = useState<{
    searchTerm: string;
    columnFilters?: Record<number, ColumnFilterValue>;
  }>({ searchTerm: "" });

  const { previewDataSourcePaginated, dataSources } = useDataSources();

  const matchedSource = dataSources.find((ds) => ds.bindAnnotation === datasource.bindAnnotation);
  const host = matchedSource?.host;

  const fieldEntries = Object.entries(datasource.fields);
  const canPreview = isPreviewableDataSource(datasource.bindAnnotation ?? "");

  const fetchPage = useCallback(
    async (page: number) => {
      if (!datasource.bindAnnotation) {
        setPreviewError("No bind annotation available for this data source");
        return;
      }
      const ob = orderByRef.current.length
        ? orderByRef.current.map((o) => ({ position: o.position, direction: o.direction }))
        : undefined;
      try {
        const result = await previewDataSourcePaginated(
          datasource.bindAnnotation,
          page,
          pageSizeRef.current,
          ob,
          searchTermRef.current,
          columnFiltersRef.current,
        );
        if (result) {
          setPreviewData(result);
        } else {
          setPreviewError("Failed to load preview data");
        }
      } catch {
        setPreviewError("An error occurred while loading the preview");
      }
    },
    [datasource.bindAnnotation, previewDataSourcePaginated],
  );

  const loadPreview = useCallback(async () => {
    if (previewData || isLoadingPreview) return;
    setIsLoadingPreview(true);
    setPreviewError(null);
    try {
      await fetchPage(1);
    } finally {
      setIsLoadingPreview(false);
    }
  }, [previewData, isLoadingPreview, fetchPage]);

  useEffect(() => {
    if (activeTab === "preview" && !previewData && !previewError) {
      loadPreview();
    }
  }, [activeTab, previewData, previewError, loadPreview]);

  const handlePageChange = useCallback(
    async (page: number) => {
      setIsFetching(true);
      setPreviewError(null);
      try {
        await fetchPage(page);
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage],
  );

  const handlePageSizeChange = useCallback(
    async (pageSize: number) => {
      pageSizeRef.current = pageSize;
      setIsFetching(true);
      try {
        await fetchPage(1);
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage],
  );

  const handleSort = useCallback(
    async (orderBy: OrderByItem[]) => {
      orderByRef.current = orderBy;
      setIsFetching(true);
      try {
        await fetchPage(1);
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage],
  );

  const handleSearch = useCallback(
    async (searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) => {
      searchTermRef.current = searchTerm || undefined;
      const cfArray = columnFilters
        ? Object.entries(columnFilters)
            .filter(([, v]) =>
              typeof v === "object"
                ? v.value || ["is_null", "is_not_null"].includes(v.operator)
                : !!v,
            )
            .map(([k, v]) =>
              typeof v === "object"
                ? {
                    position: Number(k),
                    value: v.value,
                    ...(v.operator !== "contains" ? { operator: v.operator } : {}),
                  }
                : { position: Number(k), value: String(v) },
            )
        : undefined;
      columnFiltersRef.current = cfArray?.length ? cfArray : undefined;
      setSearchState({ searchTerm: searchTerm || "", columnFilters });
      setIsFetching(true);
      try {
        await fetchPage(1);
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage],
  );

  const handleClearSearch = useCallback(async () => {
    searchTermRef.current = undefined;
    columnFiltersRef.current = undefined;
    setSearchState({ searchTerm: "" });
    setIsFetching(true);
    try {
      await fetchPage(1);
    } finally {
      setIsFetching(false);
    }
  }, [fetchPage]);

  const handleClearColumnFilter = useCallback(
    async (columnIndex: number) => {
      const existing = columnFiltersRef.current?.filter((cf) => cf.position !== columnIndex);
      columnFiltersRef.current = existing?.length ? existing : undefined;
      const newFilters = { ...searchState.columnFilters };
      delete newFilters[columnIndex];
      setSearchState((prev) => ({
        ...prev,
        columnFilters: Object.keys(newFilters).length ? newFilters : undefined,
      }));
      setIsFetching(true);
      try {
        await fetchPage(1);
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage, searchState.columnFilters],
  );

  const columnNames: string[] = previewData?.results?.columnNames || [];
  const facts: any[][] = previewData?.results?.facts || [];

  const paginationInfo = previewData?.pagination
    ? {
        page: previewData.pagination.page,
        totalPages: previewData.pagination.total_pages,
        hasNext: previewData.pagination.has_next,
        hasPrev: previewData.pagination.has_prev,
        totalCount: previewData.pagination.total_count,
        pageSize: previewData.pagination.page_size,
        orderBy: orderByRef.current.length ? orderByRef.current : undefined,
      }
    : undefined;

  const resolvedIconType =
    datasource.datasourceType?.toLowerCase() === "binaryfile" && datasource.bindAnnotation
      ? getIconTypeForBinaryFile(datasource.bindAnnotation)
      : datasource.datasourceType || "unknown";

  return (
    <div className="flex flex-col flex-1 min-h-0">
      {/* Datasource info bar + tabs */}
      <div className="flex-shrink-0 flex items-center gap-3 px-4 pt-2 pb-0">
        <DatabaseIcon type={resolvedIconType} className="h-5 w-5 flex-shrink-0" />
        <span className="text-sm font-semibold text-foreground truncate">{datasource.label}</span>
        <span className="text-xs text-muted-foreground bg-muted px-2 py-0.5 rounded font-medium">
          {datasource.datasourceType}
        </span>
      </div>

      <DatasourceDetailTabs
        activeTab={activeTab}
        onTabChange={setActiveTab}
        canPreview={canPreview}
      />

      {/* Tab content */}
      <div className="flex-1 overflow-auto">
        {activeTab === "details" && (
          <div className="p-4 space-y-4">
            <div className="space-y-2">
              <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                Connection
              </h4>
              <div className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1.5 text-sm">
                <span className="text-muted-foreground">Type</span>
                <span className="font-medium">{datasource.datasourceType}</span>
                {host && (
                  <>
                    <span className="text-muted-foreground">Host</span>
                    <span className="font-mono text-xs">{host}</span>
                  </>
                )}
                {datasource.database && (
                  <>
                    <span className="text-muted-foreground">Database</span>
                    <span className="font-mono text-xs">{datasource.database}</span>
                  </>
                )}
                <span className="text-muted-foreground">Table</span>
                <span className="font-mono text-xs">{datasource.label}</span>
              </div>
            </div>

            {fieldEntries.length > 0 && (
              <div className="space-y-2">
                <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                  Schema ({fieldEntries.length} column{fieldEntries.length !== 1 ? "s" : ""})
                </h4>
                <div className="border rounded-md overflow-hidden">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="bg-muted border-b">
                        <th className="text-left text-xs font-semibold text-muted-foreground px-3 py-1.5">
                          Column
                        </th>
                        <th className="text-left text-xs font-semibold text-muted-foreground px-3 py-1.5">
                          Type
                        </th>
                      </tr>
                    </thead>
                    <tbody>
                      {fieldEntries.map(([name, type]) => (
                        <tr key={name} className="border-b last:border-b-0">
                          <td className="px-3 py-1.5 text-xs font-medium">{name}</td>
                          <td className="px-3 py-1.5 text-xs font-mono text-muted-foreground">
                            {type}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {fieldEntries.length === 0 && (
              <p className="text-xs text-muted-foreground italic">
                No schema information available.
              </p>
            )}
          </div>
        )}

        {activeTab === "preview" && (
          <div className="p-4">
            {isLoadingPreview ? (
              <div className="flex items-center justify-center h-32">
                <PrometheuxSpinner size={36} label="Fetching records..." />
              </div>
            ) : previewError ? (
              <div className="flex items-center justify-center h-24">
                <p className="text-xs text-destructive">{previewError}</p>
              </div>
            ) : (
              <QueryResultTable
                data={{
                  predicateName: datasource.label,
                  columns: columnNames,
                  rows: facts,
                }}
                pagination={paginationInfo}
                onPageChange={handlePageChange}
                onPageSizeChange={handlePageSizeChange}
                isLoading={isFetching}
                onSearch={handleSearch}
                onClearSearch={handleClearSearch}
                onClearColumnFilter={handleClearColumnFilter}
                searchState={searchState}
                onSort={handleSort}
              />
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default DatasourceDetailPanel;
