import { StickyNote } from "lucide-react";
import React, { useCallback, useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { useCellCurlSnippet } from "@/features/concept-editor/hooks/useCellCurlSnippet";
import { useCellDragDrop } from "@/features/concept-editor/hooks/useCellDragDrop";
import {
  useCellRename,
  useConceptRenameCommit,
} from "@/features/concept-editor/hooks/useCellRename";
import { useCellSplitPanes } from "@/features/concept-editor/hooks/useCellSplitPanes";
import { useCellView } from "@/features/concept-editor/hooks/useCellView";
import type { ContextMode } from "@/features/concept-editor/types";
import { useOntologyId } from "@/features/ontologies/hooks/useOntologyId";
import { AccordionContent } from "@/shared/components/ui/accordion";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Textarea } from "@/shared/components/ui/textarea";
import { cn } from "@/shared/lib/utils";
import { CellAccordionShell } from "./components/CellAccordionShell";
import { NonDeterministicBadge, NoteCountBadge } from "./components/CellBadges";
import { CellDescriptionSection } from "./components/CellDescriptionSection";
import { CellHeaderRow } from "./components/CellHeaderRow";
import { CellRenameControl } from "./components/CellRenameControl";
import CellResults from "./components/CellResults";
import { CellSplitBottomTabs } from "./components/CellSplitBottomTabs";
import CellToolbar from "./components/CellToolbar";
import { type CellView, CellViewTabs } from "./components/CellViewTabs";
import { ContextNotePicker } from "./components/ContextNotePicker";
import { SplitDragHandle } from "./components/SplitDragHandle";
import type { QueryConceptCellProps } from "./types/editorTypes";

interface QueryContextCellProps extends QueryConceptCellProps {
  onOutputPredicateChange?: (cellId: string, outputPredicate: string) => void;
}

const QueryContextCell: React.FC<QueryContextCellProps> = ({
  cell,
  onRunCell,
  onDeleteCell,
  onClearResults,
  onRestoreResults,
  onSaveCell,
  onStopCell,
  setCells,
  changePage,
  isLoadingPage,
  searchPredicateData,
  clearSearch,
  groupNames,
  onAddCellToGroup,
  onRemoveCellFromGroup,
  onOutputPredicateChange,
  onCellTypeChange,
  onRenameConcept,
  defaultView,
  onViewChange,
  splitLayout,
}) => {
  const projectId = useOntologyId();
  const [open, setOpen] = useState<string>(cell.id);
  const initialView: CellView =
    defaultView === "context" || defaultView === "output" ? defaultView : "editor";
  const { currentView, setCurrentView } = useCellView<CellView>(cell, initialView);

  // In split layout, propagate currentView changes to the parent so it can
  // persist the bottom panel state. Skip the initial mount.
  const initialViewSyncRef = useRef(true);
  useEffect(() => {
    if (!splitLayout || !onViewChange) return;
    if (initialViewSyncRef.current) {
      initialViewSyncRef.current = false;
      return;
    }
    onViewChange(currentView);
  }, [currentView, splitLayout, onViewChange]);

  const {
    isBottomPanelOpen,
    editorPaneRef,
    bottomPaneRef,
    splitEditorStyle,
    splitBottomFlexStyle,
    editorRatio,
    handleSplitDragStart,
    adjustRatio,
  } = useCellSplitPanes({ splitLayout, currentView, editorView: "editor" });
  const { dropPosition, handleDragOver, handleDragLeave, handleDrop } = useCellDragDrop(cell.id);
  const buildCurlSnippet = useCellCurlSnippet(cell.outputPredicate);
  const rename = useCellRename({
    currentName: cell.outputPredicate,
    onCommit: useConceptRenameCommit({ cell, setCells, onRenameConcept, onOutputPredicateChange }),
  });

  const currentGroup = cell.group && cell.group !== "group_id" ? cell.group : null;

  React.useEffect(() => {
    if (cell.autoOpen) {
      setOpen(cell.id);
      setCells((prev) => prev.map((c) => (c.id === cell.id ? { ...c, autoOpen: false } : c)));
    }
  }, [cell.autoOpen, cell.id, setCells]);

  const handleToggleAccordion = useCallback(() => {
    setOpen((prev) => (prev === cell.id ? "" : cell.id));
  }, [cell.id]);

  const handleNoteIdsChange = useCallback(
    (noteIds: string[]) => {
      setCells((prev) =>
        prev.map((c) =>
          c.id === cell.id ? { ...c, noteIds, isModified: true, needsSave: true } : c,
        ),
      );
    },
    [cell.id, setCells],
  );

  const handleModeChange = useCallback(
    (value: ContextMode) => {
      setCells((prev) =>
        prev.map((c) =>
          c.id === cell.id ? { ...c, contextMode: value, isModified: true, needsSave: true } : c,
        ),
      );
    },
    [cell.id, setCells],
  );

  const handleQueryChange = useCallback(
    (query: string) => {
      setCells((prev) =>
        prev.map((c) =>
          c.id === cell.id ? { ...c, contextQuery: query, isModified: true, needsSave: true } : c,
        ),
      );
    },
    [cell.id, setCells],
  );

  const handleTopKChange = useCallback(
    (raw: string) => {
      const parsed = Number.parseInt(raw, 10);
      const topK = Number.isFinite(parsed) && parsed > 0 ? parsed : undefined;
      setCells((prev) =>
        prev.map((c) =>
          c.id === cell.id ? { ...c, contextTopK: topK, isModified: true, needsSave: true } : c,
        ),
      );
    },
    [cell.id, setCells],
  );

  const handleDescriptionChange = useCallback(
    (value: string) => {
      setCells((prev) =>
        prev.map((c) =>
          c.id === cell.id ? { ...c, description: value, isModified: true, needsSave: true } : c,
        ),
      );
    },
    [cell.id, setCells],
  );

  const handleSaveCell = useCallback(
    async (cellId: string) => {
      return onSaveCell?.(cellId);
    },
    [onSaveCell],
  );

  const handleRunCell = useCallback(
    (cellId: string, forceRerun?: boolean) => {
      if (open !== cell.id) setOpen(cell.id);
      if (!cell.outputPredicate?.trim()) {
        toast.error("Please set a concept name before running");
        return;
      }
      onRunCell?.(cellId, undefined, forceRerun);
    },
    [open, cell.id, cell.outputPredicate, onRunCell],
  );

  // CellToolbar disables Run/Save while `code` is empty; a context cell has no
  // code, so gate those actions on the concept name instead by passing a
  // non-empty sentinel only once a name is set.
  const toolbarCode = cell.outputPredicate?.trim() ? "context" : "";
  const noteCount = cell.noteIds?.length ?? 0;
  const contextMode: ContextMode = cell.contextMode ?? "static";
  const isDynamic = contextMode === "dynamic";

  return (
    <CellAccordionShell
      cellId={cell.id}
      cellBackendId={cell.cellBackendId}
      open={open}
      onOpenChange={setOpen}
      dropPosition={dropPosition}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <CellHeaderRow
        cell={cell}
        isOpen={open === cell.id}
        defaultConceptType="context"
        onToggle={handleToggleAccordion}
        onCellTypeChange={onCellTypeChange}
        buildCurlSnippet={buildCurlSnippet}
        currentGroup={currentGroup}
        groupNames={groupNames}
        onAddCellToGroup={onAddCellToGroup}
        onRemoveCellFromGroup={onRemoveCellFromGroup}
        identity={
          <CellRenameControl
            name={cell.outputPredicate || ""}
            isRenaming={rename.isRenaming}
            renameValue={rename.renameValue}
            inputRef={rename.inputRef}
            onRenameValueChange={rename.setRenameValue}
            onConfirm={rename.confirm}
            onCancel={rename.cancel}
            onStart={rename.start}
          />
        }
        badges={isDynamic ? <NonDeterministicBadge /> : <NoteCountBadge count={noteCount} />}
        toolbar={
          <CellToolbar
            cellId={cell.id}
            code={toolbarCode}
            isRunning={cell.isRunning}
            isCellSaving={cell.isSaving}
            hasResult={!!cell.result || !!cell.error}
            hasPersistedResults={cell.hasPersistedResults || false}
            isModified={cell.isModified}
            onRunCell={handleRunCell}
            onStopCell={onStopCell}
            onDeleteCell={onDeleteCell}
            onClearResults={onClearResults}
            onRestoreResults={onRestoreResults}
            onSaveCell={handleSaveCell}
            readOnly={cell.readOnly}
          />
        }
      />
      <AccordionContent style={{ overflow: "visible", minWidth: 0 }}>
        <div className="flex flex-col border-t border-border/50">
          <CellViewTabs
            cell={cell}
            currentView={currentView}
            editorLabel="notes"
            editorIcon={<StickyNote className="h-3 w-3 mr-1" />}
            contextLabel="description"
            splitLayout={splitLayout}
            onSelectView={setCurrentView}
          />
          {/* The context cell's "description" view deliberately has NO
                attached-notes panel (unlike other cells' context tab): its
                notes ARE its content, edited in the notes view. */}
          {currentView === "context" && (
            <div
              ref={isBottomPanelOpen ? bottomPaneRef : undefined}
              className={cn(
                "cell-view-pane px-4 py-2",
                splitLayout && "order-5 min-h-0 overflow-auto",
              )}
              style={splitBottomFlexStyle}
            >
              <CellDescriptionSection
                description={cell.description || ""}
                onDescriptionChange={handleDescriptionChange}
                onSaveShortcut={() => handleSaveCell(cell.id)}
                cellBackendId={cell.cellBackendId}
                placeholder="Describe what knowledge this context concept exposes..."
              />
            </div>
          )}
          {currentView === "output" && (
            <div
              ref={isBottomPanelOpen ? bottomPaneRef : undefined}
              className={cn(
                "cell-view-pane w-full overflow-x-auto",
                splitLayout && "order-5 min-h-0 overflow-auto",
              )}
              style={{ maxWidth: "100%", ...splitBottomFlexStyle }}
            >
              <CellResults
                cell={cell}
                setCells={setCells}
                changePage={changePage}
                isLoadingPage={isLoadingPage}
                searchPredicateData={searchPredicateData}
                clearSearch={clearSearch}
              />
            </div>
          )}
          {/* The note selection is this cell's body, so it plays the role the
              code editor plays elsewhere: `cell-editor-pane` lets the host
              layouts size it, and it stays mounted in split layout. */}
          <div
            ref={isBottomPanelOpen ? editorPaneRef : undefined}
            className={cn(
              "cell-editor-pane flex min-h-0 flex-1 flex-col",
              splitLayout && "order-2",
            )}
            style={splitEditorStyle}
          >
            <div className="flex flex-shrink-0 flex-wrap items-center gap-2 border-b border-border/50 px-3 py-2">
              <span className="text-xs text-muted-foreground">Mode</span>
              <Select value={contextMode} onValueChange={handleModeChange} disabled={cell.readOnly}>
                <SelectTrigger className="h-7 w-[110px] text-xs border-border">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="static" className="text-xs">
                    Static
                  </SelectItem>
                  <SelectItem value="dynamic" className="text-xs">
                    Dynamic
                  </SelectItem>
                </SelectContent>
              </Select>
              <span className="text-[11px] text-muted-foreground">
                {isDynamic
                  ? "Retrieve notes by semantic query on every run"
                  : "Pin a fixed set of notes"}
              </span>
            </div>
            {isDynamic ? (
              <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto p-3">
                <div className="flex flex-col gap-1">
                  <label
                    htmlFor={`ctx-query-${cell.id}`}
                    className="text-xs font-medium text-foreground"
                  >
                    Query
                  </label>
                  <Textarea
                    id={`ctx-query-${cell.id}`}
                    value={cell.contextQuery ?? ""}
                    onChange={(e) => handleQueryChange(e.target.value)}
                    placeholder="e.g. refund, cancellation and chargeback policy and past resolutions"
                    className="min-h-[64px] text-sm"
                    disabled={cell.readOnly}
                  />
                </div>
                <div className="flex items-center gap-2">
                  <label htmlFor={`ctx-topk-${cell.id}`} className="text-xs text-muted-foreground">
                    Top-k
                  </label>
                  <Input
                    id={`ctx-topk-${cell.id}`}
                    type="number"
                    min={1}
                    value={cell.contextTopK ?? ""}
                    onChange={(e) => handleTopKChange(e.target.value)}
                    placeholder="default"
                    className="h-7 w-24 text-xs bg-muted/80"
                    disabled={cell.readOnly}
                  />
                </div>
              </div>
            ) : (
              <ContextNotePicker
                projectId={projectId}
                selectedNoteIds={cell.noteIds ?? []}
                onChange={handleNoteIdsChange}
                disabled={cell.readOnly}
                fillHeight
              />
            )}
          </div>
          {isBottomPanelOpen && (
            <SplitDragHandle
              className="order-3"
              onMouseDown={handleSplitDragStart}
              onAdjust={adjustRatio}
              editorPercent={editorRatio * 100}
            />
          )}
          {splitLayout && (
            <CellSplitBottomTabs
              cell={cell}
              currentView={currentView}
              editorView="editor"
              contextLabel="description"
              onSelectView={setCurrentView}
            />
          )}
        </div>
      </AccordionContent>
    </CellAccordionShell>
  );
};

export default QueryContextCell;
