// Pure helpers — no hooks, no JSX. Single place that recognises a freemium
// "upgrade wall" 402 from the backend and maps it to the copy shown in the
// shared ContactToUpgradeDialog. Adding a new wall = one code + one switch arm.

import { HttpError } from "@/shared/services/httpService";
import { formatResetDate } from "./billing.utils";

export const FREEMIUM_LIMIT_CODES = {
  STORAGE: "STORAGE_LIMIT_REACHED",
  ONTOLOGY: "ONTOLOGY_LIMIT_REACHED",
  DATASOURCE: "DATASOURCE_LIMIT_REACHED",
  VERSIONING: "VERSIONING_REQUIRES_SUBSCRIPTION",
  EMBEDDING: "EMBEDDING_LIMIT_REACHED",
} as const;

export type FreemiumLimitCode = (typeof FREEMIUM_LIMIT_CODES)[keyof typeof FREEMIUM_LIMIT_CODES];

const KNOWN_CODES = new Set<string>(Object.values(FREEMIUM_LIMIT_CODES));

// Codes the backend sent before ontologies were called ontologies. Kept until
// jarvispy emits the current spelling; remove both sides together.
const SUPERSEDED_CODES: Record<string, FreemiumLimitCode> = {
  PROJECT_LIMIT_REACHED: FREEMIUM_LIMIT_CODES.ONTOLOGY,
};

const isKnownCode = (value: string): value is FreemiumLimitCode => KNOWN_CODES.has(value);

export interface FreemiumLimitInfo {
  code: FreemiumLimitCode;
  used: number | null;
  limit: number | null;
  usedMb: number | null;
  limitMb: number | null;
  // ISO timestamp for monthly-quota walls (e.g. embeddings). Null for the
  // capacity/binary walls that don't reset on a schedule.
  resetsAt: string | null;
}

export interface UpgradeWallContent {
  title: string;
  description: string;
  contactSubject: string;
}

const numberField = (body: Record<string, unknown>, key: string): number | null =>
  typeof body[key] === "number" ? (body[key] as number) : null;

/**
 * The backend refuses freemium-gated actions with HTTP 402 and a body of
 * { code: "<KNOWN_CODE>", ... }. Returns the parsed info when it matches one of
 * the upgrade-wall codes, or null otherwise (so callers can ignore other errors).
 */
export const parseFreemiumLimit = (err: unknown): FreemiumLimitInfo | null => {
  if (!(err instanceof HttpError)) return null;
  if (err.status !== 402) return null;
  const body = err.body;
  if (typeof body !== "object" || body === null) return null;
  const record = body as Record<string, unknown>;
  if (typeof record.code !== "string") return null;
  const code = SUPERSEDED_CODES[record.code] ?? record.code;
  if (!isKnownCode(code)) return null;

  return {
    code,
    used: numberField(record, "used"),
    limit: numberField(record, "limit"),
    usedMb: numberField(record, "used_mb"),
    limitMb: numberField(record, "limit_mb"),
    resetsAt: typeof record.resets_at === "string" ? record.resets_at : null,
  };
};

/** Map a freemium limit to the dialog copy. Exhaustive over every known code. */
export const buildUpgradeContent = (info: FreemiumLimitInfo): UpgradeWallContent => {
  switch (info.code) {
    case FREEMIUM_LIMIT_CODES.STORAGE: {
      const limitMb = info.limitMb ?? 100;
      return {
        title: "You've reached your storage limit",
        description:
          `Freemium accounts can store up to ${limitMb} MB of files. ` +
          "You've reached that limit — delete some files to free up space, or move " +
          "up to a paid subscription for more storage. Contact Prometheux to upgrade.",
        contactSubject: "Upgrade request — file storage",
      };
    }
    case FREEMIUM_LIMIT_CODES.ONTOLOGY: {
      const limit = info.limit ?? 2;
      return {
        title: "You've reached your ontology limit",
        description:
          `Freemium accounts can have up to ${limit} ontologies. ` +
          "You've reached that limit — delete an ontology to free up a slot, or move " +
          "up to a paid subscription for more ontologies. Contact Prometheux to upgrade.",
        contactSubject: "Upgrade request — ontologies",
      };
    }
    case FREEMIUM_LIMIT_CODES.DATASOURCE: {
      const limit = info.limit ?? 2;
      return {
        title: "You've reached your data source limit",
        description:
          `Freemium accounts can connect up to ${limit} of their own data sources ` +
          "(Prometheux's own databases don't count). You've reached that limit — remove " +
          "a connection to free up a slot, or move up to a paid subscription for more " +
          "connections. Contact Prometheux to upgrade.",
        contactSubject: "Upgrade request — data source connections",
      };
    }
    case FREEMIUM_LIMIT_CODES.VERSIONING:
      return {
        title: "Ontology versioning is a paid feature",
        description:
          "Saving and restoring ontology snapshots is part of a paid subscription. " +
          "You can still view your existing versions on freemium — move up to a paid " +
          "plan to create and restore them. Contact Prometheux to upgrade.",
        contactSubject: "Upgrade request — ontology versioning",
      };
    case FREEMIUM_LIMIT_CODES.EMBEDDING: {
      const limitClause =
        info.limit !== null
          ? `Freemium accounts include ${info.limit} document embeddings per month. `
          : "";
      const resetDate = formatResetDate(info.resetsAt);
      const resetClause = resetDate ? `Your quota resets on ${resetDate}. ` : "";
      return {
        title: "You've reached your monthly embedding limit",
        description:
          `${limitClause}${resetClause}Embedding more documents is part of a paid ` +
          "subscription — contact Prometheux to upgrade.",
        contactSubject: "Upgrade request — document embeddings",
      };
    }
    default: {
      const _exhaustive: never = info.code;
      throw new Error(`Unhandled freemium limit code: ${_exhaustive}`);
    }
  }
};
