import { differenceInCalendarDays, format, formatDistanceToNow, isToday, parseISO } from "date-fns";
import type { ChatSessionMeta } from "./chatHistoryApi";

export interface ChatSessionGroup {
  label: string;
  sessions: ChatSessionMeta[];
}

export function formatRelativeTime(iso: string): string {
  try {
    return formatDistanceToNow(parseISO(iso), { addSuffix: true });
  } catch {
    return "";
  }
}

/**
 * When a chat message was sent, for the label revealed beside its bubble.
 *
 * Today's messages show the time alone — the date would be noise in a
 * conversation you are still having. Older ones carry the date with it.
 * Empty string for anything unparseable, so the caller can skip the label.
 */
export function formatMessageTime(iso: string): string {
  try {
    const sentAt = parseISO(iso);
    return format(sentAt, isToday(sentAt) ? "p" : "PPp");
  } catch {
    return "";
  }
}

// Recency buckets, newest first. Rendered as section headers so a long history
// is scannable instead of an undifferentiated wall of rows.
const BUCKET_ORDER = [
  "Today",
  "Yesterday",
  "Previous 7 days",
  "Previous 30 days",
  "Older",
] as const;

function bucketFor(iso: string): (typeof BUCKET_ORDER)[number] {
  try {
    const days = differenceInCalendarDays(new Date(), parseISO(iso));
    if (days <= 0) return "Today";
    if (days === 1) return "Yesterday";
    if (days <= 7) return "Previous 7 days";
    if (days <= 30) return "Previous 30 days";
    return "Older";
  } catch {
    return "Older";
  }
}

// Groups sessions (assumed already sorted newest-first by the API) into recency
// buckets, dropping any bucket that ended up empty.
export function groupSessionsByRecency(sessions: ChatSessionMeta[]): ChatSessionGroup[] {
  const buckets = new Map<string, ChatSessionMeta[]>();
  for (const session of sessions) {
    const key = bucketFor(session.updated_at);
    const existing = buckets.get(key) ?? [];
    existing.push(session);
    buckets.set(key, existing);
  }
  return BUCKET_ORDER.filter((label) => buckets.has(label)).map((label) => ({
    label,
    sessions: buckets.get(label) ?? [],
  }));
}
