import { Trash2 } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import type { AppConcept } from "../../api/ConceptClient";
import type { DashboardWidget, WidgetType } from "../../types";

export const WIDGET_TYPES: { value: WidgetType; label: string }[] = [
  { value: "stat_card", label: "Stat card" },
  { value: "table", label: "Table" },
  { value: "bar_list", label: "Bar list" },
  { value: "channel_grid", label: "Channel grid" },
  { value: "badge_table", label: "Badge table" },
  { value: "line_chart", label: "Line chart" },
  { value: "pie_chart", label: "Pie chart" },
  { value: "progress_bar", label: "Progress bar" },
  { value: "graph", label: "Graph" },
];

interface ColSelectProps {
  col: number;
  setCol: (v: number) => void;
  label: string;
  colOptions: { index: number; name: string }[];
}

function ColSelect({ col, setCol, label, colOptions }: ColSelectProps) {
  return (
    <div className="flex flex-col gap-1 min-w-[100px]">
      <Label className="text-xs text-muted-foreground">{label}</Label>
      {colOptions.length > 0 ? (
        <Select value={String(col)} onValueChange={(v) => setCol(Number(v))}>
          <SelectTrigger className="h-7 text-xs w-full">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {colOptions.map((c) => (
              <SelectItem key={c.index} value={String(c.index)} className="text-xs">
                {c.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      ) : (
        <Input
          type="number"
          min={0}
          value={col}
          onChange={(e) => setCol(Number(e.target.value) || 0)}
          className="h-7 text-xs w-16"
        />
      )}
    </div>
  );
}

export interface WidgetConfigRowProps {
  widget: DashboardWidget;
  concepts: AppConcept[];
  knownColumns?: string[];
  onChange: (w: DashboardWidget) => void;
  onRemove: () => void;
}

function resolveXColLabel(type: WidgetType): string {
  if (type === "line_chart") return "X axis";
  if (type === "graph") return "Source";
  return "Label col";
}

function resolveYColLabel(type: WidgetType): string {
  if (type === "line_chart") return "Y axis";
  if (type === "graph") return "Target";
  return "Value col";
}

function buildColOptions(
  knownColumns: string[] | undefined,
  concept: AppConcept | undefined,
): { index: number; name: string }[] {
  if (knownColumns?.length) return knownColumns.map((name, index) => ({ index, name }));
  if (concept?.fields) return Object.keys(concept.fields).map((name, index) => ({ index, name }));
  const detailFields = concept?.concept_details?.[0]?.fields;
  if (detailFields) return Object.keys(detailFields).map((name, index) => ({ index, name }));
  return [];
}

export function WidgetConfigRow({
  widget,
  concepts,
  knownColumns,
  onChange,
  onRemove,
}: WidgetConfigRowProps) {
  const concept = concepts.find((c) => c.predicate_name === widget.conceptName);
  const colOptions = buildColOptions(knownColumns, concept);

  const needsCols = widget.type !== "table";

  return (
    <div className="bg-card border border-border rounded-md p-2.5 flex flex-col gap-2">
      {/* Row 1: concept + type + label + delete */}
      <div className="flex items-end gap-2 flex-wrap">
        <div className="flex flex-col gap-1 min-w-[140px] flex-1">
          <Label className="text-xs text-muted-foreground">Concept</Label>
          <Select
            value={widget.conceptName}
            onValueChange={(v) => onChange({ ...widget, conceptName: v })}
          >
            <SelectTrigger className="h-7 text-xs">
              <SelectValue placeholder="Select concept" />
            </SelectTrigger>
            <SelectContent>
              {concepts.map((c) => (
                <SelectItem key={c.predicate_name} value={c.predicate_name} className="text-xs">
                  {c.predicate_name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="flex flex-col gap-1 w-28">
          <Label className="text-xs text-muted-foreground">Type</Label>
          <Select
            value={widget.type}
            onValueChange={(v) => onChange({ ...widget, type: v as WidgetType })}
          >
            <SelectTrigger className="h-7 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {WIDGET_TYPES.map((t) => (
                <SelectItem key={t.value} value={t.value} className="text-xs">
                  {t.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="flex flex-col gap-1 w-28">
          <Label className="text-xs text-muted-foreground">Label</Label>
          <Input
            value={widget.label ?? ""}
            onChange={(e) => onChange({ ...widget, label: e.target.value })}
            placeholder="Optional"
            className="h-7 text-xs"
          />
        </div>

        <Button
          variant="ghost"
          size="iconSm"
          onClick={onRemove}
          className="text-muted-foreground hover:text-destructive self-end mb-0.5"
        >
          <Trash2 className="h-3.5 w-3.5" />
        </Button>
      </div>

      {/* Row 2: column mapping + stat sub-label */}
      {needsCols && (
        <div className="flex items-end gap-2 flex-wrap">
          <ColSelect
            col={widget.xCol}
            setCol={(v) => onChange({ ...widget, xCol: v })}
            label={resolveXColLabel(widget.type)}
            colOptions={colOptions}
          />
          <ColSelect
            col={widget.yCol}
            setCol={(v) => onChange({ ...widget, yCol: v })}
            label={resolveYColLabel(widget.type)}
            colOptions={colOptions}
          />
          {widget.type === "stat_card" && (
            <div className="flex flex-col gap-1 flex-1 min-w-[100px]">
              <Label className="text-xs text-muted-foreground">Sub-label</Label>
              <Input
                value={widget.statSub ?? ""}
                onChange={(e) => onChange({ ...widget, statSub: e.target.value })}
                placeholder="e.g. vs last quarter"
                className="h-7 text-xs"
              />
            </div>
          )}
        </div>
      )}
    </div>
  );
}
