import { format } from "date-fns";
import DOMPurify from "dompurify";
import { useMemo } from "react";
import type { Invoice } from "@/features/billing/types";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shared/components/ui/dialog";
import { ScrollArea } from "@/shared/components/ui/scroll-area";

interface InvoicePreviewDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  invoice: Invoice | null;
}

// DOMPurify config locked down for the invoice preview: allow only a small
// presentational subset, no scripts/styles/forms/event handlers.
// Resolves F7 from the 2026-06-12 security review for this sink.
const INVOICE_PURIFY_CONFIG = {
  ALLOWED_TAGS: ["div", "h1", "h2", "h3", "p", "span", "table", "thead", "tbody", "tr", "th", "td"],
  ALLOWED_ATTR: ["style", "colspan", "rowspan"],
  ALLOW_DATA_ATTR: false,
  FORBID_TAGS: ["script", "style", "iframe", "object", "embed", "form", "input"],
  FORBID_ATTR: ["onerror", "onload", "onclick", "onmouseover"],
};

export function InvoicePreviewDialog({ open, onOpenChange, invoice }: InvoicePreviewDialogProps) {
  const html = useMemo(() => {
    if (!invoice) return "";
    const raw = generateInvoiceHtml(invoice);
    return DOMPurify.sanitize(raw, INVOICE_PURIFY_CONFIG);
  }, [invoice]);

  if (!invoice) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl max-h-[90vh] p-0">
        <DialogHeader className="px-6 pt-6 pb-0">
          <DialogTitle>Invoice {invoice.invoice_number}</DialogTitle>
        </DialogHeader>
        <ScrollArea className="max-h-[calc(90vh-80px)]">
          <div className="p-6" dangerouslySetInnerHTML={{ __html: html }} />
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}

function generateInvoiceHtml(inv: Invoice): string {
  const invoiceDate = format(new Date(inv.sent_at), "MMMM d, yyyy");
  const dueDate = format(
    new Date(new Date(inv.sent_at).getTime() + 30 * 24 * 60 * 60 * 1000),
    "MMMM d, yyyy",
  );
  const periodFrom = format(new Date(inv.period_from), "MMMM dd, yyyy");
  const periodTo = format(new Date(inv.period_to), "MMMM dd, yyyy");
  const total = inv.total_amount.toFixed(2);
  const userName = inv.recipient_name || inv.recipient_email;

  const lineItemsHtml = (inv.line_items || [])
    .map((item) => {
      const unit = item.category === "license" ? "days" : "hrs";
      const rateLabel = item.category === "license" ? "day" : "hr";
      const amount = Number(item.amount);
      const rate = Number(item.rate);
      const hours = Number(item.hours);

      // Add category suffix if not already present
      const categorySuffix = item.category === "license" ? " - License" : " - Compute";
      const description =
        item.description.includes(" - Compute") || item.description.includes(" - License")
          ? item.description
          : item.description + categorySuffix;

      return `<tr>
      <td style="padding:12px 0;border-bottom:1px solid #e5e7eb">${description} (${hours} ${unit} @ $${rate.toFixed(2)}/${rateLabel})</td>
      <td style="padding:12px 16px;border-bottom:1px solid #e5e7eb;text-align:center">1</td>
      <td style="padding:12px 16px;border-bottom:1px solid #e5e7eb;text-align:right">$${amount.toFixed(2)}</td>
      <td style="padding:12px 0;border-bottom:1px solid #e5e7eb;text-align:right;font-weight:500">$${amount.toFixed(2)}</td>
    </tr>`;
    })
    .join("");

  return `
<div style="font-family:inherit;padding:24px 0">
  <h1 style="font-size:36px;font-weight:600;margin:0 0 24px">Invoice</h1>
  <div style="display:flex;gap:80px;flex-wrap:wrap;margin-bottom:32px">
    <div><p style="color:#6b7280;font-size:12px;text-transform:uppercase;margin:0 0 4px">Invoice number</p><p style="font-size:14px;margin:0;font-weight:500">${inv.invoice_number.replace("INV-", "")}</p></div>
    <div><p style="color:#6b7280;font-size:12px;text-transform:uppercase;margin:0 0 4px">Date of issue</p><p style="font-size:14px;margin:0">${invoiceDate}</p></div>
    <div><p style="color:#6b7280;font-size:12px;text-transform:uppercase;margin:0 0 4px">Date due</p><p style="font-size:14px;margin:0">${dueDate}</p></div>
  </div>
  <div style="margin-bottom:32px;padding-bottom:24px;border-bottom:1px solid #e5e7eb">
    <p style="margin:0;font-weight:600">Prometheux Limited</p>
    <p style="color:#6b7280;margin:4px 0 0">14 Welbeck Street, London, W1G 9XU, UK</p>
  </div>
  <div style="background:#f3f4f6;border-radius:8px;padding:16px 20px;margin-bottom:32px">
    <p style="margin:0;font-weight:600">$${total} USD due ${dueDate}</p>
  </div>
  <div style="margin-bottom:24px">
    <p style="color:#6b7280;font-size:12px;text-transform:uppercase;margin:0 0 8px">Bill to</p>
    <p style="margin:0;font-weight:500">${userName}</p>
    <p style="margin:4px 0 0;color:#6b7280">${inv.recipient_email}</p>
    ${inv.organization ? `<p style="margin:4px 0 0;color:#6b7280">${inv.organization}</p>` : ""}
  </div>
  <div style="margin-bottom:24px">
    <p style="color:#6b7280;font-size:12px;text-transform:uppercase;margin:0 0 8px">Billing period</p>
    <p style="margin:0">${periodFrom} - ${periodTo}</p>
  </div>
  <table style="width:100%;border-collapse:collapse;margin-bottom:24px">
    <thead><tr style="border-bottom:2px solid #e5e7eb">
      <th style="padding:12px 0;text-align:left;font-weight:600">Description</th>
      <th style="padding:12px 16px;text-align:center;font-weight:600">Qty</th>
      <th style="padding:12px 16px;text-align:right;font-weight:600">Unit price</th>
      <th style="padding:12px 0;text-align:right;font-weight:600">Amount</th>
    </tr></thead>
    <tbody>${lineItemsHtml || '<tr><td colspan="4" style="padding:24px;text-align:center;color:#6b7280">No line items</td></tr>'}</tbody>
  </table>
  <div style="border-top:1px solid #e5e7eb;padding-top:16px">
    <div style="display:flex;justify-content:flex-end;margin-bottom:8px"><span style="color:#6b7280;width:100px">Subtotal</span><span style="width:100px;text-align:right">$${total}</span></div>
    <div style="display:flex;justify-content:flex-end;margin-bottom:8px"><span style="font-weight:600;width:100px">Total</span><span style="font-weight:600;width:100px;text-align:right">$${total}</span></div>
    <div style="display:flex;justify-content:flex-end;padding-top:12px;border-top:2px solid #111827;margin-top:12px"><span style="font-size:16px;font-weight:700;width:120px">Amount due</span><span style="font-size:16px;font-weight:700;width:120px;text-align:right">$${total} USD</span></div>
  </div>
  <div style="margin-top:48px;padding-top:24px;border-top:1px solid #e5e7eb"><p style="color:#6b7280;font-size:12px;margin:0;text-align:center">Thank you for using Prometheux Services.</p></div>
</div>`;
}
