/**
 * The Prometheux access token, in one place.
 *
 * It used to live in three: a field on `PROMETHEUX_CONFIG`, a static inside
 * `HttpService`, and React state in `AuthProvider`. Each was written
 * separately, and signing in wrote only two of them — so whether a request went
 * out authenticated depended on which copy its caller happened to read, and
 * every raw-`fetch` call site carried a fallback to paper over the difference.
 *
 * Those three are now views onto this value. Read it as late as possible:
 * a token that arrives after a component rendered is still the one its next
 * request should carry.
 */

type Listener = () => void;

let token = "";
const listeners = new Set<Listener>();

export function getAuthToken(): string {
  return token;
}

export function setAuthToken(next: string | null): void {
  const value = next ?? "";
  if (value === token) return;
  token = value;
  for (const listener of listeners) listener();
}

export function clearAuthToken(): void {
  setAuthToken("");
}

/**
 * Watch the token, in the shape `useSyncExternalStore` expects.
 *
 * Sign-in happens outside React — it is an async callback, not a render — so
 * anything that wants to re-render when the token lands has to subscribe.
 */
export function subscribeToAuthToken(listener: Listener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}
