import type React from "react";
import { useCallback, useRef, useState } from "react";
import {
  EDITOR_RATIO_MAX,
  EDITOR_RATIO_MIN,
  explorerPreferences,
} from "@/shared/utils/explorerPreferences";

const DEFAULT_EDITOR_RATIO = 0.5;

interface UseExplorerSplitResizeReturn {
  editorRatio: number;
  editorPaneRef: React.RefObject<HTMLDivElement>;
  bottomPaneRef: React.RefObject<HTMLDivElement>;
  handleDragStart: (event: React.MouseEvent<HTMLDivElement>) => void;
  adjustRatio: (deltaRatio: number) => void;
}

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

/**
 * Drives the vertical split between the editor and the bottom panel in
 * Explorer view. The hook owns the ratio state, persists it to localStorage
 * on drag end, and exposes refs the caller attaches to the two flex panes so
 * the drag handler can measure their starting heights.
 */
export function useExplorerSplitResize(): UseExplorerSplitResizeReturn {
  const [editorRatio, setEditorRatio] = useState<number>(
    () => explorerPreferences.getEditorRatio() ?? DEFAULT_EDITOR_RATIO,
  );
  const editorPaneRef = useRef<HTMLDivElement>(null);
  const bottomPaneRef = useRef<HTMLDivElement>(null);

  const handleDragStart = useCallback((event: React.MouseEvent<HTMLDivElement>) => {
    event.preventDefault();
    const editor = editorPaneRef.current;
    const bottom = bottomPaneRef.current;
    if (!editor || !bottom) return;

    const startY = event.clientY;
    const startEditorH = editor.getBoundingClientRect().height;
    const startBottomH = bottom.getBoundingClientRect().height;
    const total = startEditorH + startBottomH;
    if (total <= 0) return;

    // Block text selection while dragging so the cursor doesn't flicker into
    // I-beam and the editor text doesn't get highlighted.
    const previousUserSelect = document.body.style.userSelect;
    document.body.style.userSelect = "none";

    let latestRatio = startEditorH / total;

    const onMouseMove = (e: MouseEvent) => {
      const delta = e.clientY - startY;
      const nextEditorH = clamp(
        startEditorH + delta,
        EDITOR_RATIO_MIN * total,
        EDITOR_RATIO_MAX * total,
      );
      latestRatio = nextEditorH / total;
      setEditorRatio(latestRatio);
    };

    const onMouseUp = () => {
      document.removeEventListener("mousemove", onMouseMove);
      document.removeEventListener("mouseup", onMouseUp);
      document.body.style.userSelect = previousUserSelect;
      explorerPreferences.setEditorRatio(latestRatio);
    };

    document.addEventListener("mousemove", onMouseMove);
    document.addEventListener("mouseup", onMouseUp);
  }, []);

  const adjustRatio = useCallback((deltaRatio: number) => {
    setEditorRatio((current) => {
      const next = clamp(current + deltaRatio, EDITOR_RATIO_MIN, EDITOR_RATIO_MAX);
      explorerPreferences.setEditorRatio(next);
      return next;
    });
  }, []);

  return { editorRatio, editorPaneRef, bottomPaneRef, handleDragStart, adjustRatio };
}
