import { loadRemote, registerRemotes } from "@module-federation/runtime";

// Module Federation remote names become global identifiers, so they cannot contain
// hyphens (a dashboardId like "sella-wealth" must register as "app_sella_wealth").
// The customer-apps repo builds each app with this exact name, so host registration
// and the remote's federation `name` stay in sync. Keep this in lockstep with the
// `remoteNameFor` helper in prometheux-customer-apps/vite.config.ts.
export function remoteNameFor(dashboardId: string): string {
  return `app_${dashboardId.replace(/[^a-zA-Z0-9_]/g, "_")}`;
}

// Remotes can only be registered once per name; re-registering warns at runtime.
const registered = new Set<string>();

function ensureRegistered(dashboardId: string, entryUrl: string): string {
  const name = remoteNameFor(dashboardId);
  if (!registered.has(name)) {
    // @module-federation/vite emits an ESM remoteEntry that assigns the container to a
    // global named after the remote (`app_<id>`). Dynamic loading goes through the runtime
    // (not the plugin's build-time import() transform), so it must be told the entry is a
    // module — otherwise the default "var" loader script-injects an ESM file and fails with
    // RUNTIME-001. `type` and `entryGlobalName` are accepted by the runtime (the plugin
    // registers its own remotes the same way) even though the SDK's RemoteWithEntry type
    // only names { name, entry }.
    registerRemotes([{ name, entry: entryUrl, type: "module", entryGlobalName: name }]);
    registered.add(name);
  }
  return name;
}

// Load a named export module ("App" or "config") from a federated client app.
// `exposed` is the expose key without the leading "./" (matches the remote's `exposes`).
export async function loadRemoteExport<T>(
  dashboardId: string,
  entryUrl: string,
  exposed: string,
): Promise<T> {
  const name = ensureRegistered(dashboardId, entryUrl);
  const mod = await loadRemote<T>(`${name}/${exposed}`);
  if (!mod) {
    throw new Error(
      `Federated app "${dashboardId}" at ${entryUrl} exposed no module "${exposed}".`,
    );
  }
  return mod;
}
