import type { ElementType } from "react";
import { cn } from "@/shared/lib/utils";

type IconChipSize = "sm" | "md" | "lg";

interface IconChipProps {
  icon: ElementType;
  size?: IconChipSize;
  className?: string;
}

const chipSize: Record<IconChipSize, string> = {
  sm: "h-7 w-7 rounded-md",
  md: "h-9 w-9 rounded-md",
  lg: "h-11 w-11 rounded-lg",
};

const glyphSize: Record<IconChipSize, string> = {
  sm: "h-3.5 w-3.5",
  md: "h-4 w-4",
  lg: "h-5 w-5",
};

/**
 * Small rounded-square container that frames an icon on a faint muted surface —
 * the "icon chip" pattern that gives list rows, cards, and headers a designed,
 * premium feel instead of a bare glyph. Purely presentational.
 */
export function IconChip({ icon: Icon, size = "md", className }: IconChipProps) {
  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center justify-center border bg-muted/60",
        chipSize[size],
        className,
      )}
    >
      <Icon className={cn("text-foreground/80", glyphSize[size])} />
    </span>
  );
}
