import {
  Ban,
  CheckCircle,
  Cpu,
  DollarSign,
  FileText,
  MemoryStick,
  Plus,
  RefreshCw,
  Timer,
  Trash2,
} from "lucide-react";
import type React from "react";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "@/shared/components/ui/card";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import type { AvailabilityResult, Machine, UserMachine } from "../utils";
import { getCategoryDisplayName } from "../utils";
import { MachineToggleButton } from "./MachineToggleButton";

export interface MachineCardProps {
  machine: Machine;
  userMachine?: UserMachine;
  isAvailable?: boolean;
  onSelect?: () => void;
  onRequest?: () => void;
  availabilityResult?: AvailabilityResult;
  isCheckingAvailability?: boolean;
  isRequesting?: boolean;
  onCheckStatus?: (machineId: string, userMachineId: string) => void;
  onFetchUsage?: (userMachineId: string, machineName: string) => void;
  onToggleActive?: (
    userMachineId: string,
    machineId: string,
    currentIsActive: boolean,
    autoterminationMinutes?: number,
  ) => Promise<void>;
  onRemoveMachine?: (userMachineId: string, machineName: string) => Promise<void>;
  // `undefined` = eligibility not yet known; the toggle button does not lock
  // during loading. The backend remains authoritative (returns 402 if needed).
  isPaidComputeEligible?: boolean;
  // Called when the user clicks Start on a paid machine while ineligible.
  onPaidComputeRequired?: () => void;
}

export const MachineCard: React.FC<MachineCardProps> = ({
  machine,
  userMachine,
  isAvailable = false,
  onSelect,
  onRequest,
  availabilityResult,
  isCheckingAvailability = false,
  isRequesting = false,
  onCheckStatus,
  onFetchUsage,
  onToggleActive,
  onRemoveMachine,
  isPaidComputeEligible,
  onPaidComputeRequired,
}) => {
  const _status = userMachine?.status;
  const isUnavailable = availabilityResult && availabilityResult.status === "error";

  const machineStatus = availabilityResult?.machine_status;
  const isRunning = machineStatus === "started";
  const currentSessionDuration = userMachine?.current_session?.current_duration_minutes || 0;

  const displayFreeMinutes =
    userMachine?.free_minutes_remaining !== undefined
      ? isRunning && currentSessionDuration > 0
        ? Math.max(0, userMachine.free_minutes_remaining - currentSessionDuration)
        : userMachine.free_minutes_remaining
      : undefined;

  const isFree = machine.cost_per_machine === 0;

  return (
    <Card
      className={`@container transition-all hover:shadow-md ${
        isUnavailable
          ? "opacity-50 border-red-200 dark:border-red-800 cursor-not-allowed"
          : isFree
            ? "border-green-300 dark:border-green-700 ring-1 ring-green-200 dark:ring-green-800/50"
            : ""
      }`}
    >
      <CardHeader className="flex flex-row flex-wrap items-center justify-between gap-2 space-y-0 pb-2">
        <CardTitle className="text-sm font-medium flex min-w-0 flex-wrap items-center gap-2">
          <span className="truncate">{machine.name}</span>
          {isFree && (
            <Badge className="text-xs bg-green-600 hover:bg-green-600 text-white border-0">
              FREE
            </Badge>
          )}
          {userMachine?.status === "Disabled" && (
            <Badge
              variant="outline"
              className="text-xs border-purple-500 text-purple-700 dark:text-purple-400"
            >
              Previously Used
            </Badge>
          )}
          {/* Free minutes badge */}
          {displayFreeMinutes !== undefined && displayFreeMinutes > 0 && (
            <Badge
              variant="secondary"
              className="text-xs bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400"
            >
              {displayFreeMinutes.toFixed(0)} free mins
            </Badge>
          )}
        </CardTitle>
        <div className="flex items-center gap-2">
          {userMachine && (
            <MachineToggleButton
              userMachine={userMachine}
              machine={machine}
              availabilityResult={availabilityResult}
              onToggleActive={onToggleActive}
              isPaidComputeEligible={isPaidComputeEligible}
              onPaidComputeRequired={onPaidComputeRequired}
            />
          )}

          {/* Status check button for ENABLED machines only */}
          {userMachine && userMachine.status === "Enabled" && (
            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-6 px-2 text-xs"
                    onClick={(e) => {
                      e.stopPropagation();
                      onCheckStatus?.(machine.id, userMachine.id);
                    }}
                    disabled={isCheckingAvailability}
                  >
                    <RefreshCw
                      className={`w-3 h-3 ${isCheckingAvailability ? "animate-spin" : ""}`}
                    />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>
                  <p>{availabilityResult?.message || "Check real-time machine status"}</p>
                </TooltipContent>
              </Tooltip>
            </TooltipProvider>
          )}

          {/* Request/Use button for available machines (includes disabled machines) */}
          {isAvailable && onRequest && (
            <Button
              variant="outline"
              size="sm"
              className="h-6 px-2 text-xs"
              onClick={(e) => {
                e.stopPropagation();
                onRequest();
              }}
              disabled={isRequesting}
            >
              {isRequesting ? (
                <>
                  <PrometheuxSpinner size={16} className="mr-1" />
                  Requesting...
                </>
              ) : (
                <>
                  <Plus className="w-2 h-2 mr-1" />
                  Use
                </>
              )}
            </Button>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-3">
          {machine.category && (
            <div className="text-xs text-muted-foreground">
              {getCategoryDisplayName(machine.category)}
            </div>
          )}
          <div className="grid grid-cols-1 gap-3 @xs:grid-cols-3 @xs:gap-4">
            <div className="flex items-center gap-2">
              <div className="flex items-center justify-center w-6 h-6 rounded-full bg-blue-100 dark:bg-blue-900/30">
                <Cpu className="w-3 h-3 text-blue-600 dark:text-blue-400" />
              </div>
              <div>
                <div className="text-xs text-muted-foreground">Cores</div>
                <div className="text-sm font-semibold">{machine.cores}</div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <div className="flex items-center justify-center w-6 h-6 rounded-full bg-purple-100 dark:bg-purple-900/30">
                <MemoryStick className="w-3 h-3 text-purple-600 dark:text-purple-400" />
              </div>
              <div>
                <div className="text-xs text-muted-foreground">Memory</div>
                <div className="text-sm font-semibold">{machine.memory_gb} GB</div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <div className="flex items-center justify-center w-6 h-6 rounded-full bg-green-100 dark:bg-green-900/30">
                <DollarSign className="w-3 h-3 text-green-600 dark:text-green-400" />
              </div>
              <div>
                <div className="text-xs text-muted-foreground">Cost</div>
                <div
                  className={`text-sm font-semibold ${isFree ? "text-green-600 dark:text-green-400" : ""}`}
                >
                  {isFree ? "Free" : `$${machine.cost_per_machine}/hr`}
                </div>
              </div>
            </div>
          </div>
        </div>
      </CardContent>

      {/* CardFooter - Status badges and action buttons (only for ENABLED machines) */}
      {userMachine && userMachine.status === "Enabled" && (
        <CardFooter className="flex flex-wrap items-center justify-between gap-2 pt-2 border-t">
          {/* Status badge + auto-termination indicator (left side) */}
          <div className="flex flex-wrap items-center gap-2">
            {availabilityResult?.machine_status && (
              <>
                {availabilityResult.machine_status === "started" && (
                  <Badge
                    variant="outline"
                    className="text-xs text-green-600 dark:text-green-400 border-green-600"
                  >
                    <CheckCircle className="w-2 h-2 mr-1" />
                    Running
                  </Badge>
                )}
                {["pending", "starting", "restarting", "crashed"].includes(
                  availabilityResult.machine_status,
                ) && (
                  <Badge
                    variant="outline"
                    className="text-xs text-blue-600 dark:text-blue-400 border-blue-600"
                  >
                    <PrometheuxSpinner size={16} className="mr-1" />
                    Starting
                  </Badge>
                )}
                {availabilityResult.machine_status === "stopping" && (
                  <Badge
                    variant="outline"
                    className="text-xs text-orange-600 dark:text-orange-400 border-orange-600"
                  >
                    <PrometheuxSpinner size={16} className="mr-1" />
                    Stopping
                  </Badge>
                )}
                {availabilityResult.machine_status === "stopped" && (
                  <Badge
                    variant="outline"
                    className="text-xs text-gray-600 dark:text-gray-400 border-gray-600"
                  >
                    <Ban className="w-2 h-2 mr-1" />
                    Stopped
                  </Badge>
                )}
              </>
            )}
            {userMachine.autotermination_minutes != null && (
              <Badge
                variant="outline"
                className="text-xs text-orange-600 dark:text-orange-400 border-orange-600"
              >
                <Timer className="w-2 h-2 mr-1" />
                {userMachine.autotermination_minutes}m idle stop
              </Badge>
            )}
          </div>

          {/* Right side buttons */}
          <div className="flex items-center gap-2">
            {/* Details button (for enabled machines) */}
            <Button
              variant="outline"
              size="sm"
              className="h-7 px-3 text-xs"
              onClick={(e) => {
                e.stopPropagation();
                onFetchUsage?.(userMachine.id, machine.name);
              }}
            >
              <FileText className="w-3 h-3 mr-1" />
              Details
            </Button>

            {/* Remove button (only for stopped enabled machines) */}
            {!userMachine.is_active && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-7 px-2 text-xs text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-950"
                      onClick={async (e) => {
                        e.stopPropagation();
                        onRemoveMachine?.(userMachine.id, machine.name);
                      }}
                    >
                      <Trash2 className="w-3 h-3 mr-1" />
                      Remove
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>
                    <p>Remove this machine from your list</p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}
          </div>
        </CardFooter>
      )}
    </Card>
  );
};
