import type { Change } from "diff";
import { cn } from "@/shared/lib/utils";
import { type DiffLine, toDiffLines } from "./snapshotDiff.utils";

const LINE_STYLES: Record<DiffLine["type"], string> = {
  add: "bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-400",
  remove: "bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400",
  context: "text-muted-foreground",
};

const LINE_PREFIX: Record<DiffLine["type"], string> = {
  add: "+",
  remove: "-",
  context: " ",
};

interface ConceptLineDiffProps {
  changes: Change[];
}

export function ConceptLineDiff({ changes }: ConceptLineDiffProps) {
  const lines = toDiffLines(changes);

  return (
    <div className="overflow-x-auto rounded-md border border-border bg-card font-mono text-xs">
      {lines.map((line) => (
        <div
          key={line.id}
          className={cn("flex whitespace-pre px-2 py-0.5", LINE_STYLES[line.type])}
        >
          <span className="mr-2 select-none opacity-60">{LINE_PREFIX[line.type]}</span>
          <span>{line.text || " "}</span>
        </div>
      ))}
    </div>
  );
}
