// Reserved top-level route segments. A two-segment path that starts with one of
// these is a real page (e.g. /context/:id, /apps/:id, /settings/billing) — NOT
// the remote-mode "/:organization/:username" home landing. Keep in sync with the
// top-level routes in AppRoutes.tsx.
const NON_HOME_ROOTS = new Set([
  "editor",
  "settings",
  "profile",
  "datasources",
  "graph-explorer",
  "ontologies",
  "context",
  "compute",
  "apps",
  "dashboards",
  "teams",
  "onboarding",
  "setup",
  "login",
  "reset-password",
  "databricks-oauth-callback",
  "mfa-challenge",
]);

/**
 * True on the home landing — the root ("/") or the remote-mode
 * "/:organization/:username" page. Both embed the AI chat inline, so callers use
 * this to hide the sidebar launcher, force-close the docked panel, and warm the
 * engine there. Every other route (including two-segment ones like /context/:id)
 * is a normal page.
 */
export function isHomePath(pathname: string): boolean {
  const parts = pathname.split("/").filter(Boolean);
  if (parts.length === 0) return true;
  return parts.length === 2 && !NON_HOME_ROOTS.has(parts[0]);
}
