import type { AppSectionDef } from "../../../schema/appDefinition.types";
import { patchSection } from "../../../store/appEditorMutations";
import { useAppEditorStore } from "../../../store/appEditorStore";
import { CsvField, SelectField, TextField } from "./fields";
import { StaleSelection } from "./PageInspector";

interface SectionInspectorProps {
  pageId: string;
  sectionId: string;
}

const LAYOUT_OPTIONS = [
  { value: "grid", label: "Grid (12-column row flow)" },
  { value: "columns", label: "Columns (side-by-side card stacks)" },
];

export function SectionInspector({ pageId, sectionId }: SectionInspectorProps) {
  const draft = useAppEditorStore((state) => state.draft);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  const section = draft?.pages
    .find((page) => page.id === pageId)
    ?.sections.find((candidate) => candidate.id === sectionId);
  if (!section) return <StaleSelection />;

  const patch = (partial: Partial<AppSectionDef>) => {
    updateDraft((current) => patchSection(current, pageId, sectionId, partial));
  };

  const weightsAsStrings = section.weights?.map((weight) => String(weight));

  const handleWeightsChange = (items: string[] | undefined) => {
    if (!items) return patch({ weights: undefined });
    const numbers = items.map(Number).filter((n) => Number.isFinite(n) && n > 0);
    patch({ weights: numbers.length > 0 ? numbers : undefined });
  };

  return (
    <div className="flex flex-col gap-2.5">
      <TextField
        label="Title"
        value={section.title}
        onChange={(value) => patch({ title: value })}
      />
      <SelectField
        label="Layout"
        value={section.layout === "columns" ? "columns" : "grid"}
        options={LAYOUT_OPTIONS}
        onChange={(value) => patch({ layout: value === "columns" ? "columns" : "grid" })}
      />
      {section.layout === "columns" && (
        <CsvField
          label="Stack weights (e.g. 8, 4)"
          value={weightsAsStrings}
          onChange={handleWeightsChange}
          placeholder="equal widths"
        />
      )}
    </div>
  );
}
