// Apply persisted theme before React renders to avoid flash of unstyled content.
// Zustand persist stores state as: { state: { theme: "light"|"dark" }, version: 0 }
try {
  const raw = localStorage.getItem("theme-preference");
  const theme = raw ? JSON.parse(raw)?.state?.theme : "light";
  if (theme === "dark") document.documentElement.classList.add("dark");
} catch {
  // Ignore — defaults to light
}

// One-time cleanup: the editor's default cell view is now enforced by the
// `defaultCellView` preference, so the old persisted bottom-tab key is orphaned.
// Remove it so it doesn't linger in returning users' localStorage.
try {
  localStorage.removeItem("prometheux:explorer:bottomTab");
} catch {
  // Ignore — best-effort cleanup
}

import "@fontsource-variable/inter/index.css";
import "@fontsource-variable/fira-code/index.css";
import { type ComponentType, type ReactNode, StrictMode } from "react";
import { createRoot } from "react-dom/client";
import "./index.css";
import "./shared/styles/vadalog-linter.css";
import App from "./App.jsx";

// PostHog is only loaded when VITE_PUBLIC_POSTHOG_KEY is set at build time.
// Builds without the key (e.g. the Databricks 3P marketplace bundle)
// never reach the dynamic `import("posthog-js/react")` below, so Vite/Rollup
// tree-shake the entire SDK out — no telemetry code ships to customers and
// no third-party host is contacted.
const POSTHOG_KEY = import.meta.env.VITE_PUBLIC_POSTHOG_KEY;

// Dev-only: `bun run dev:apps` / `dev:apps:remote` set VITE_APP_RELOAD_URL so the host
// full-reloads when a federated customer app changes (Fast Refresh can't cross the Module
// Federation boundary). Unset in `dev`/`dev:remote` and prod, so this import is tree-shaken.
const APP_RELOAD_URL = import.meta.env.VITE_APP_RELOAD_URL;
if (import.meta.env.DEV && APP_RELOAD_URL) {
  import("./shared/dev/appReloadClient").then(({ connectAppReload }) => {
    connectAppReload(APP_RELOAD_URL);
  });
}

type ProviderProps = { children: ReactNode } & Record<string, unknown>;
const PassthroughProvider: ComponentType<ProviderProps> = ({ children }) => <>{children}</>;

async function loadProvider(): Promise<{
  Provider: ComponentType<ProviderProps>;
  providerProps: Record<string, unknown>;
}> {
  if (!POSTHOG_KEY) {
    return { Provider: PassthroughProvider, providerProps: {} };
  }

  const { PostHogProvider } = await import("posthog-js/react");
  const options = {
    api_host: import.meta.env.VITE_PUBLIC_POSTHOG_HOST,
    person_profiles: "identified_only" as const,
    debug: import.meta.env.DEV,
    capture_pageview: true,
    disable_person_processing: false,
    bootstrap: {
      distinctID: undefined,
    },
    disable_session_recording: false,
    session_recording: {
      recordCrossOriginIframes: true,
      maskAllInputs: true,
      maskInputOptions: {
        password: true,
        email: false,
        text: false,
      },
      recordConsoleLog: import.meta.env.DEV,
      recordNetworkRequests: true,
      sampleRate: 1.0,
      minimumDuration: 1000,
      recordCanvas: true,
    },
    // Autocapture is OFF: it produced high-volume, low-signal events
    // ("clicked button with text X", "clicked div") that said little about
    // actual platform use. Product usage is now tracked with explicit semantic
    // events (see shared/services/analyticsEvents.ts).
    autocapture: false,
    loaded: (posthog: any) => {
      // Register super properties (sent with every event).
      // Prefer register() over setSessionProperties() — it has existed since v1
      // and avoids the "not a function" error on older cached builds in staging.
      posthog.register({
        app_name: "Prometheux RAG",
        app_version: "1.0.3",
        environment: import.meta.env.DEV ? "development" : "production",
      });
    },
  };

  return {
    Provider: PostHogProvider as ComponentType<ProviderProps>,
    providerProps: { apiKey: POSTHOG_KEY, options },
  };
}

(async () => {
  const { Provider, providerProps } = await loadProvider();
  createRoot(document.getElementById("root")).render(
    <StrictMode>
      <Provider {...providerProps}>
        <App />
      </Provider>
    </StrictMode>,
  );
})();
