import { FileText } from "lucide-react";
import React, { useCallback } from "react";
import { toast } from "sonner";
import type { TemplateData } from "@/features/ontologies/api";
import TemplateCard from "./TemplateCard";

interface TemplateListProps {
  templates: TemplateData[];
  onUseTemplate?: (templateId: string, templateName: string) => void;
  usingTemplateId?: string | null;
}

const TemplateList: React.FC<TemplateListProps> = ({
  templates,
  onUseTemplate,
  usingTemplateId,
}) => {
  const handleUseTemplate = useCallback(
    (templateId: string) => {
      const template = templates.find((t) => t.id === templateId);
      if (template && onUseTemplate) {
        onUseTemplate(template.id, template.name);
      } else {
        toast.info("TODO for using ontology template");
      }
    },
    [templates, onUseTemplate],
  );

  if (templates.length === 0) {
    return null;
  }

  return (
    <div>
      <div className="grid grid-cols-3 gap-4">
        {templates.map((template) => (
          <TemplateCard
            key={template.id}
            id={template.id}
            title={template.name}
            description={template.description}
            icon={FileText}
            onUse={handleUseTemplate}
            isUsing={usingTemplateId === template.id}
          />
        ))}
      </div>
    </div>
  );
};

export default React.memo(TemplateList);
