import type { Edge, Node as FlowNode } from "@xyflow/react";
import { MarkerType } from "@xyflow/react";

import { linkDisplayTitle } from "../notes/notesModel";
import type { ContextEdge, ContextNote, ContextShelf } from "../types";
import { PROVENANCE_RELATION, shelfOf } from "../types";

export const CONTEXT_NOTE_CARD_WIDTH = 260;
const NOTE_CARD_HEIGHT = 104;
const CONCEPT_CARD_HEIGHT = 56;
// Horizontal gap between a note column and the concept; vertical gap
// between stacked notes; alternating x-stagger for an organic look.
const COLUMN_GAP = 170;
const ROW_GAP = 36;
const STAGGER = 44;

// Mirrors the lineage flow's DEFAULT_EDGE_STYLE / DEFAULT_EDGE_MARKER
// (lineage-view/constants.ts) so both canvases read as one system.
const EDGE_STYLE = { stroke: "#aaa", strokeWidth: 2 };
const EDGE_MARKER = { type: MarkerType.ArrowClosed, width: 18, height: 18, color: "#aaa" };
// Provenance pins (derived_from — a context concept's note set) draw dashed
// and labeled, so "this note feeds the output" reads differently from a
// plain annotation ("this note is about the concept").
const PROVENANCE_EDGE_STYLE = { ...EDGE_STYLE, strokeDasharray: "6 4" };
const EDGE_LABEL_STYLE = {
  fontSize: 10,
  fill: "hsl(var(--muted-foreground))",
  fontFamily: "monospace",
};

export interface ContextConceptNodeData {
  label: string;
  [key: string]: unknown;
}

export interface ContextNoteNodeData {
  title: string;
  snippet: string;
  shelf: ContextShelf;
  [key: string]: unknown;
}

export function conceptCardWidth(label: string): number {
  return Math.min(Math.max(label.length * 11 + 96, 180), 340);
}

function noteSnippet(note: ContextNote): string {
  const body = (note.text || "").replace(/\s+/g, " ").trim();
  return body.length > 160 ? `${body.slice(0, 157)}…` : body;
}

/** Vertically centered, x-staggered positions for one side column. */
function sideColumnPositions(count: number, baseX: number, direction: 1 | -1) {
  const totalHeight = count * NOTE_CARD_HEIGHT + (count - 1) * ROW_GAP;
  const startY = -totalHeight / 2;
  return Array.from({ length: count }, (_, i) => ({
    x: baseX + direction * (i % 2) * STAGGER,
    y: startY + i * (NOTE_CARD_HEIGHT + ROW_GAP),
  }));
}

/**
 * Local context graph for the Context tab, in the lineage flow's visual
 * language: the concept card in the middle with its attached-note cards
 * distributed on BOTH sides (making horizontal use of the panel), all
 * pointing at the concept; note↔note links among the attached set are
 * drawn too. Per-side handles keep every arrow entering the concept from
 * the side the note sits on.
 */
export function buildContextFlow(
  conceptKey: string,
  conceptName: string,
  attachedNotes: ContextNote[],
  allEdges: ContextEdge[],
): { nodes: FlowNode[]; edges: Edge[] } {
  const noteIds = new Set(attachedNotes.map((note) => note.id));
  const conceptWidth = conceptCardWidth(conceptName);

  // Alternate sides so the split stays balanced (ceil on the left).
  const leftNotes = attachedNotes.filter((_, i) => i % 2 === 0);
  const rightNotes = attachedNotes.filter((_, i) => i % 2 === 1);
  const sideOf = new Map<string, "left" | "right">([
    ...leftNotes.map((n) => [n.id, "left"] as const),
    ...rightNotes.map((n) => [n.id, "right"] as const),
  ]);

  const leftPositions = sideColumnPositions(
    leftNotes.length,
    -(COLUMN_GAP + CONTEXT_NOTE_CARD_WIDTH),
    -1,
  );
  const rightPositions = sideColumnPositions(rightNotes.length, conceptWidth + COLUMN_GAP, 1);

  const toNoteNode = (note: ContextNote, position: { x: number; y: number }): FlowNode => ({
    id: note.id,
    type: "contextNote",
    data: {
      title: linkDisplayTitle(note),
      snippet: noteSnippet(note),
      shelf: shelfOf(note),
    } satisfies ContextNoteNodeData,
    position,
  });

  const nodes: FlowNode[] = [
    ...leftNotes.map((note, i) => toNoteNode(note, leftPositions[i])),
    ...rightNotes.map((note, i) => toNoteNode(note, rightPositions[i])),
    {
      id: conceptKey,
      type: "contextConcept",
      data: { label: conceptName } satisfies ContextConceptNodeData,
      position: { x: 0, y: -CONCEPT_CARD_HEIGHT / 2 },
    },
  ];

  // Attached notes always point AT the concept, whatever the stored
  // direction; the handles face each other based on the note's side.
  const conceptEdges: Edge[] = allEdges
    .filter(
      (edge) =>
        (edge.src_type === "concept" && edge.src_id === conceptKey && noteIds.has(edge.dst_id)) ||
        (edge.dst_type === "concept" && edge.dst_id === conceptKey && noteIds.has(edge.src_id)),
    )
    .map((edge) => {
      const noteId = edge.src_type === "note" ? edge.src_id : edge.dst_id;
      const fromLeft = sideOf.get(noteId) === "left";
      const isProvenance = edge.relation === PROVENANCE_RELATION;
      return {
        id: edge.id,
        source: noteId,
        sourceHandle: fromLeft ? "source-right" : "source-left",
        target: conceptKey,
        targetHandle: fromLeft ? "target-left" : "target-right",
        type: "default",
        style: isProvenance ? PROVENANCE_EDGE_STYLE : EDGE_STYLE,
        markerEnd: EDGE_MARKER,
        ...(isProvenance ? { label: "derived from", labelStyle: EDGE_LABEL_STYLE } : {}),
      };
    });

  const noteEdges: Edge[] = allEdges
    .filter(
      (edge) =>
        edge.src_type === "note" &&
        edge.dst_type === "note" &&
        noteIds.has(edge.src_id) &&
        noteIds.has(edge.dst_id),
    )
    .map((edge) => {
      // Leave toward the target's side so same-side links stay tight and
      // cross-side links arc around the concept.
      const crossing = sideOf.get(edge.src_id) !== sideOf.get(edge.dst_id);
      const targetOnRight = sideOf.get(edge.dst_id) === "right";
      const exitRight = crossing ? targetOnRight : sideOf.get(edge.src_id) === "left";
      return {
        id: edge.id,
        source: edge.src_id,
        sourceHandle: exitRight ? "source-right" : "source-left",
        target: edge.dst_id,
        targetHandle: exitRight ? "target-left" : "target-right",
        type: "default",
        style: EDGE_STYLE,
        markerEnd: EDGE_MARKER,
      };
    });

  return { nodes, edges: [...conceptEdges, ...noteEdges] };
}
