import type { SchemaInferenceInitialValues } from "@/features/concept-editor/components/code-editor/editor/SchemaInferenceForm";
import type { DemoDatabaseConfig } from "@/features/data-sources/types";

const S3_HOST_PREFIX = "s3a://";

export interface DemoPrefill {
  initialValues: SchemaInferenceInitialValues;
  initialStorageType: string;
}

/**
 * Map a px-datasource connection config to the connection form's prefill shape.
 * File presets stored as an `s3a://` host pre-select the AWS storage type so the
 * form shows the access key / secret key fields.
 */
export function buildDemoPrefill(database: DemoDatabaseConfig): DemoPrefill {
  const isS3 = database.host?.startsWith(S3_HOST_PREFIX) ?? false;
  const hasPort = database.port != null && database.port > 0;

  return {
    initialValues: {
      databaseType: database.databaseType ?? "",
      username: database.username ?? "",
      password: database.password ?? "",
      host: database.host ?? "",
      port: hasPort ? String(database.port) : "",
      databaseName: database.databaseName ?? "",
      options: "",
    },
    initialStorageType: isS3 ? "aws" : "local",
  };
}
