import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

export interface OnboardingStatus {
  needs_company_onboarding: boolean;
  project_count: number;
  global_note_count: number;
  supported: boolean;
}

interface ApiEnvelope<T> {
  status: "success" | "error";
  data?: T;
  message?: string;
}

export async function fetchOnboardingStatus(): Promise<OnboardingStatus> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/knowledge/onboarding-status`;
  const response: ApiEnvelope<OnboardingStatus> = await HttpService.get(url);
  if (response.status !== "success" || !response.data) {
    throw new Error(response.message ?? "Failed to load onboarding status");
  }
  return response.data;
}
