import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import type { AvailabilityResult, Machine, UserMachine } from "../utils";
import { SnowflakeComputeClient } from "./SnowflakeComputeClient";
import { SNOWFLAKE_MACHINES, type SnowflakeComputePool } from "./snowflakeMachines";

export interface GrantInfo {
  operation: string;
  poolName: string;
  sql: string;
}

function mapPoolStateToMachineStatus(state: string): AvailabilityResult["machine_status"] {
  switch (state) {
    case "ACTIVE":
    case "IDLE":
      return "started";
    case "STARTING":
      return "starting";
    case "STOPPING":
      return "pending";
    case "SUSPENDED":
      return "stopped";
    default:
      return "stopped";
  }
}

function poolToUserMachine(pool: SnowflakeComputePool): UserMachine {
  const machine = SNOWFLAKE_MACHINES.find((m) => m.id === pool.instance_family);
  const isActive = ["ACTIVE", "IDLE", "STARTING"].includes(pool.state);

  return {
    id: pool.name,
    user_id: "snowflake",
    machine_id: pool.instance_family,
    node_group_id: null,
    status: "Enabled",
    requested_at: null,
    enabled_at: null,
    disabled_at: null,
    created_at: null,
    is_default: pool.is_current,
    is_active: isActive,
    for_compute: true,
    last_started_at: null,
    last_stopped_at: null,
    machines: machine || {
      id: pool.instance_family,
      name: pool.instance_family,
      type: "unknown",
      category: null,
      cores: 0,
      memory_gb: 0,
      cost_per_machine: 0,
      created_at: null,
      updated_at: null,
    },
  };
}

export const useSnowflakeCompute = () => {
  const [pools, setPools] = useState<SnowflakeComputePool[]>([]);
  const [currentPool, setCurrentPool] = useState<string>("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isRequesting, setIsRequesting] = useState(false);
  const [checkingStatus, setCheckingStatus] = useState<Record<string, boolean>>({});
  const [availabilityResults, setAvailabilityResults] = useState<
    Record<string, AvailabilityResult>
  >({});
  const [isSwitching, setIsSwitching] = useState(false);
  const [grantInfo, setGrantInfo] = useState<GrantInfo | null>(null);

  const clientRef = useRef<SnowflakeComputeClient | null>(null);
  const getClient = useCallback(() => {
    if (!clientRef.current) clientRef.current = new SnowflakeComputeClient();
    return clientRef.current;
  }, []);

  const handleGrantRequired = useCallback((data: any, fallbackOperation: string) => {
    setGrantInfo({
      operation: data.operation || fallbackOperation,
      poolName: data.pool_name || "",
      sql: data.grant_sql || "",
    });
  }, []);

  const fetchPools = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await getClient().listPools();
      if (response.status === "success" && response.data) {
        setPools(response.data.pools);
        setCurrentPool(response.data.current_pool);

        const results: Record<string, AvailabilityResult> = {};
        for (const pool of response.data.pools) {
          // Key by pool name (unique) to avoid collisions when multiple pools share instance_family
          results[pool.name] = {
            status: "success",
            message: `Pool ${pool.name}: ${pool.state}`,
            machine_status: mapPoolStateToMachineStatus(pool.state),
          };
        }
        setAvailabilityResults(results);
      } else {
        setError(response.message || "Failed to load compute pools");
      }
    } catch (err) {
      console.error("Error fetching Snowflake compute pools:", err);
      setError(err instanceof Error ? err.message : "Failed to load compute pools");
    } finally {
      setLoading(false);
    }
  }, [getClient]);

  useEffect(() => {
    if (!PROMETHEUX_CONFIG.SNOWFLAKE_MODE) return;
    fetchPools();
  }, [fetchPools]);

  const handleUsePool = useCallback(
    async (instanceFamily: string) => {
      setIsRequesting(true);
      try {
        const response = await getClient().createPool(instanceFamily);

        if (response.status === "success") {
          toast.success(`Compute pool created with ${instanceFamily}`);
          await fetchPools();
          return { success: true };
        }

        if (response.data?.grant_required) {
          handleGrantRequired(response.data, "create");
          return { success: false };
        }

        toast.error(response.message || "Failed to create compute pool");
        return { success: false };
      } catch (err) {
        const message = err instanceof Error ? err.message : "Failed to create compute pool";
        toast.error(message);
        return { success: false };
      } finally {
        setIsRequesting(false);
      }
    },
    [fetchPools, handleGrantRequired, getClient],
  );

  const handleStartPool = useCallback(
    async (poolName: string) => {
      setAvailabilityResults((prev) => ({
        ...prev,
        [poolName]: { status: "success", message: "Starting...", machine_status: "starting" },
      }));

      try {
        const response = await getClient().resumePool(poolName);
        if (response.data?.grant_required) {
          handleGrantRequired(response.data, "resume");
        } else if (response.status === "success") {
          toast.success(`Compute pool ${poolName} is starting`);
        } else {
          toast.error(response.message || "Failed to start compute pool");
        }
        await fetchPools();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Failed to start compute pool");
        await fetchPools();
      }
    },
    [fetchPools, handleGrantRequired, getClient],
  );

  const handleStopPool = useCallback(
    async (poolName: string) => {
      setAvailabilityResults((prev) => ({
        ...prev,
        [poolName]: { status: "success", message: "Stopping...", machine_status: "pending" },
      }));

      try {
        const response = await getClient().suspendPool(poolName);
        if (response.data?.grant_required) {
          handleGrantRequired(response.data, "suspend");
        } else if (response.status === "success") {
          toast.success(`Compute pool ${poolName} is stopping`);
        } else {
          toast.error(response.message || "Failed to stop compute pool");
        }
        await fetchPools();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Failed to stop compute pool");
        await fetchPools();
      }
    },
    [fetchPools, handleGrantRequired, getClient],
  );

  const handleToggleActive = useCallback(
    async (poolName: string, _instanceFamily: string, currentIsActive: boolean) => {
      if (currentIsActive) {
        await handleStopPool(poolName);
      } else {
        await handleStartPool(poolName);
      }
    },
    [handleStartPool, handleStopPool],
  );

  const handleRemovePool = useCallback(
    async (poolName: string) => {
      if (
        !window.confirm(
          `Drop compute pool ${poolName}?\n\nThis will permanently remove the compute pool.`,
        )
      ) {
        return;
      }
      try {
        const response = await getClient().dropPool(poolName);
        if (response.data?.grant_required) {
          handleGrantRequired(response.data, "drop");
        } else if (response.status === "success") {
          toast.success(`Compute pool ${poolName} dropped`);
        } else {
          toast.error(response.message || "Failed to drop compute pool");
        }
        await fetchPools();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Failed to drop compute pool");
      }
    },
    [fetchPools, handleGrantRequired, getClient],
  );

  const handleCheckStatus = useCallback(
    async (poolName: string) => {
      setCheckingStatus((prev) => ({ ...prev, [poolName]: true }));
      try {
        const response = await getClient().getPoolStatus(poolName);
        if (response.status === "success" && response.data) {
          setAvailabilityResults((prev) => ({
            ...prev,
            [poolName]: {
              status: "success",
              message: `Pool ${response.data!.pool_name}: ${response.data!.state}`,
              machine_status: mapPoolStateToMachineStatus(response.data!.state),
            },
          }));
        }
      } catch (err) {
        console.error("Error checking pool status:", err);
      } finally {
        setCheckingStatus((prev) => ({ ...prev, [poolName]: false }));
      }
    },
    [getClient],
  );

  const handleSwitchCompute = useCallback(
    async (poolName: string): Promise<boolean> => {
      setIsSwitching(true);
      try {
        const response = await getClient().switchCompute(poolName);
        if (response.status === "success") {
          toast.success("Switching compute pool... The platform will restart.");
          return true;
        }
        toast.error(response.message || "Failed to switch compute pool");
        setIsSwitching(false);
        return false;
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Failed to switch compute pool");
        setIsSwitching(false);
        return false;
      }
    },
    [getClient],
  );

  const stopSwitching = useCallback(() => {
    setIsSwitching(false);
  }, []);

  const dismissGrantInfo = useCallback(() => {
    setGrantInfo(null);
  }, []);

  const userMachines: UserMachine[] = useMemo(() => pools.map(poolToUserMachine), [pools]);

  const availableMachines: Machine[] = useMemo(() => {
    const usedInstanceFamilies = pools.map((p) => p.instance_family);
    return SNOWFLAKE_MACHINES.filter((m) => !usedInstanceFamilies.includes(m.id));
  }, [pools]);

  return {
    machines: SNOWFLAKE_MACHINES,
    availableMachines,
    userMachines,
    currentPool,
    loading,
    error,
    isRequesting,
    checkingStatus,
    availabilityResults,
    isSwitching,
    grantInfo,
    fetchPools,
    handleUsePool,
    handleToggleActive,
    handleRemovePool,
    handleCheckStatus,
    handleSwitchCompute,
    stopSwitching,
    dismissGrantInfo,
  };
};
