import type { CSSProperties } from "react";
import { ErrorBoundary } from "@/shared/components/ErrorBoundary";
import { cn } from "@/shared/lib/utils";
import type { AppSectionDef, AppWidgetDef } from "../../schema/appDefinition.types";
import { isLegacyWidget } from "../../schema/appDefinition.types";
import { AppWidgetRenderer, type TabRuntime } from "./AppWidgetRenderer";
import { EditorSelectOverlay, useEditorSelection } from "./editorSelection";

interface AppSectionViewProps {
  section: AppSectionDef;
  runtime: TabRuntime;
}

const SPAN_CLASSES: Record<number, string> = {
  1: "lg:col-span-1",
  2: "lg:col-span-2",
  3: "lg:col-span-3",
  4: "lg:col-span-4",
  5: "lg:col-span-5",
  6: "lg:col-span-6",
  7: "lg:col-span-7",
  8: "lg:col-span-8",
  9: "lg:col-span-9",
  10: "lg:col-span-10",
  11: "lg:col-span-11",
  12: "lg:col-span-12",
};

const BARE_WIDGET_TYPES = new Set(["input_ref", "form_ref", "run_button", "button"]);

const COLUMN_COUNT_CLASSES: Record<number, string> = {
  1: "lg:grid-cols-1",
  2: "lg:grid-cols-2",
  3: "lg:grid-cols-3",
  4: "lg:grid-cols-4",
};

interface ColumnStacksProps {
  sectionId: string;
  widgets: AppWidgetDef[];
  weights?: number[];
  runtime: TabRuntime;
}

function stackTemplate(weights: number[] | undefined, stackCount: number): string | undefined {
  if (!weights || weights.length === 0) return undefined;
  const positive = weights.filter((weight) => Number.isFinite(weight) && weight > 0);
  if (positive.length === 0) return undefined;
  return Array.from({ length: stackCount }, (_, i) => `${positive[i] ?? 1}fr`).join(" ");
}

/**
 * "columns" layout: side-by-side card stacks — each widget joins the stack
 * named by its `column` and each stack renders as ONE card (the hand-coded
 * apps' two-card pattern: title, description, controls and content together).
 */
function ColumnStacks({ sectionId, widgets, weights, runtime }: ColumnStacksProps) {
  const columnCount = Math.max(1, ...widgets.map((widget) => widget.column ?? 1));
  const stacks = Array.from({ length: Math.min(columnCount, 4) }, (_, index) =>
    widgets.filter((widget) => (widget.column ?? 1) === index + 1),
  );
  const template = stackTemplate(weights, stacks.length);

  return (
    <div
      className={cn(
        "grid grid-cols-1 gap-4",
        template
          ? "lg:[grid-template-columns:var(--stack-template)]"
          : COLUMN_COUNT_CLASSES[stacks.length],
      )}
      style={template ? ({ "--stack-template": template } as CSSProperties) : undefined}
    >
      {stacks.map((stack, index) => (
        <div
          key={index}
          className="bg-card border border-border rounded-lg p-4 flex flex-col gap-4"
        >
          {stack.map((widget) => (
            <div key={widget.id} className="relative flex flex-col gap-2">
              {widget.label && (
                <h4 className="text-xs font-medium text-muted-foreground">{widget.label}</h4>
              )}
              <ErrorBoundary>
                <AppWidgetRenderer widget={widget} runtime={runtime} />
              </ErrorBoundary>
              <EditorSelectOverlay sectionId={sectionId} widgetId={widget.id} />
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

/** 12-column grid section (ADR D4): each widget spans 1-12 columns. */
export function AppSectionView({ section, runtime }: AppSectionViewProps) {
  const editor = useEditorSelection();
  const widgets = section.widgets.filter(
    (widget): widget is AppWidgetDef => !isLegacyWidget(widget),
  );

  if (widgets.length === 0 && editor) {
    return (
      <section className="rounded-lg border border-dashed border-border px-4 py-8 text-center">
        <p className="text-xs text-muted-foreground">
          Empty section — add widgets from the Structure panel, or ask the AI assistant.
        </p>
      </section>
    );
  }

  return (
    <section className="flex flex-col gap-3">
      {section.title && (
        <h3 className="text-[13px] font-semibold text-foreground/80">{section.title}</h3>
      )}
      {section.layout === "columns" ? (
        <ColumnStacks
          sectionId={section.id}
          widgets={widgets}
          weights={section.weights}
          runtime={runtime}
        />
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
          {widgets.map((widget) => {
            const span = SPAN_CLASSES[widget.span ?? 12] ?? SPAN_CLASSES[12];
            const isBare = BARE_WIDGET_TYPES.has(widget.type);
            return (
              <div
                key={widget.id}
                className={cn(
                  span,
                  "relative",
                  !isBare && "bg-card border border-border rounded-lg p-4 flex flex-col gap-2",
                )}
              >
                {!isBare && widget.label && (
                  <h4 className="text-xs font-medium text-muted-foreground">{widget.label}</h4>
                )}
                <ErrorBoundary>
                  <AppWidgetRenderer widget={widget} runtime={runtime} />
                </ErrorBoundary>
                <EditorSelectOverlay sectionId={section.id} widgetId={widget.id} />
              </div>
            );
          })}
        </div>
      )}
    </section>
  );
}
