import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import {
  DashboardClient,
  type DashboardStatus,
  type DashboardVersion,
} from "../api/DashboardClient";
import type { AppDefinition } from "../schema/appDefinition.types";

const client = new DashboardClient();

export function formatVersionTimestamp(iso: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export function resolvePublishHint(
  isPublished: boolean,
  isUpToDate: boolean,
  publishedVersion: number | null,
): string {
  if (!isPublished) return "Viewers see the live draft until you publish a snapshot.";
  if (isUpToDate) return "Viewers see the latest version.";
  return `Viewers see v${publishedVersion}; the draft has newer changes.`;
}

interface UseAppVersionsReturn {
  versions: DashboardVersion[];
  isLoading: boolean;
  status: DashboardStatus;
  publishedVersion: number | null;
  latestVersion: number | null;
  /** True when the draft has moved past the published snapshot. */
  hasUnpublishedChanges: boolean;
  publish: () => void;
  unpublish: () => void;
  isPublishing: boolean;
  restore: (versionId: string) => void;
  isRestoring: boolean;
  toggleBookmark: (version: DashboardVersion) => void;
}

/**
 * Version checkpoints + publish state for one dashboard/app.
 *
 * Everything derives from the cheap versions-list endpoint: the published
 * flag on a version is the publish state, so no separate status query.
 */
export function useAppVersions(
  ontologyId: string,
  dashboardId: string,
  onDraftReplaced: (definition: AppDefinition) => void,
): UseAppVersionsReturn {
  const queryClient = useQueryClient();
  const versionsKey = ["dashboard-versions", ontologyId, dashboardId];

  const { data: versions = [], isLoading } = useQuery<DashboardVersion[]>({
    queryKey: versionsKey,
    queryFn: () => client.listVersions(ontologyId, dashboardId),
    enabled: !!ontologyId && !!dashboardId,
  });

  const invalidateAll = () => {
    queryClient.invalidateQueries({ queryKey: versionsKey });
    queryClient.invalidateQueries({ queryKey: ["dashboard", ontologyId, dashboardId] });
    queryClient.invalidateQueries({ queryKey: ["dashboard-record", ontologyId, dashboardId] });
    queryClient.invalidateQueries({ queryKey: ["all-dashboards"] });
  };

  const publishMutation = useMutation({
    mutationFn: () => client.publishDashboard(ontologyId, dashboardId),
    onSuccess: (version) => {
      invalidateAll();
      toast.success(`Published${version ? ` v${version}` : ""} — viewers now see this snapshot`);
    },
    onError: (err: Error) => toast.error(err.message),
  });

  const unpublishMutation = useMutation({
    mutationFn: () => client.unpublishDashboard(ontologyId, dashboardId),
    onSuccess: () => {
      invalidateAll();
      toast.success("Unpublished — the app is draft-only again");
    },
    onError: (err: Error) => toast.error(err.message),
  });

  const restoreMutation = useMutation({
    mutationFn: async (versionId: string) => {
      await client.restoreVersion(ontologyId, dashboardId, versionId);
      return client.getDashboardRecord(ontologyId, dashboardId, "draft");
    },
    onSuccess: (record) => {
      invalidateAll();
      if (record) onDraftReplaced(record.definition as AppDefinition);
      toast.success("Version restored as the new draft");
    },
    onError: (err: Error) => toast.error(err.message),
  });

  const bookmarkMutation = useMutation({
    mutationFn: (version: DashboardVersion) =>
      client.bookmarkVersion(ontologyId, dashboardId, version.id, !version.bookmarked),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: versionsKey }),
    onError: (err: Error) => toast.error(err.message),
  });

  const publishedEntry = versions.find((version) => version.published) ?? null;
  const latestVersion = versions[0]?.version ?? null;
  const publishedVersion = publishedEntry?.version ?? null;

  return {
    versions,
    isLoading,
    status: publishedEntry ? "published" : "draft",
    publishedVersion,
    latestVersion,
    hasUnpublishedChanges:
      publishedVersion !== null && latestVersion !== null && latestVersion > publishedVersion,
    publish: () => publishMutation.mutate(),
    unpublish: () => unpublishMutation.mutate(),
    isPublishing: publishMutation.isPending || unpublishMutation.isPending,
    restore: (versionId: string) => restoreMutation.mutate(versionId),
    isRestoring: restoreMutation.isPending,
    toggleBookmark: (version: DashboardVersion) => bookmarkMutation.mutate(version),
  };
}
