export type ShareRole = "viewer" | "editor";

export type ShareStatus =
  | "pending"
  | "accepted"
  | "revoked"
  | "superseded"
  | "left"
  // Team shares are listed with a single live status ("active") since there's no
  // per-recipient pending/accepted lifecycle on the team row itself.
  | "active";

// A share is either targeted at a single user ("user") or at an entire team
// ("team"). Team shares grant access to every active member; each member claims
// a per-member scoped token on first open. Direct shares default to "user".
export type ShareType = "user" | "team";

export type ShareApiStatus = "success" | "error" | "conflict";

export interface ShareUser {
  sub: string;
  username: string;
  organization: string;
}

// Recipient identification — exactly one of these three shapes must be provided.
// Exclusivity is enforced at the form layer (zod) and by the backend; modelling it
// as a plain union lets the wire payload pass through untouched.
export type ShareRecipientInput =
  | { sub: string }
  | { email: string }
  | { username: string; organization: string };

export interface ShareInput {
  ontologyId: string;
  recipient: ShareRecipientInput;
  shareRole: ShareRole;
  // null = never expires
  expiresInMinutes: number | null;
}

// Owner-side input for sharing a project with an entire team (POST /share/team).
// No expiry — team shares live as long as the share row and each member's token
// (24h, auto-refreshed while the member stays in the team).
export interface ShareTeamInput {
  ontologyId: string;
  recipientTeamId: string;
  shareRole: ShareRole;
}

export type RevokeInput = { shareId: string } | { ontologyId: string; recipientSub: string };

// Owner-side revoke for a team share (POST /share/team/revoke). Kills every
// member's token. Idempotent.
export type TeamRevokeInput = { shareId: string } | { ontologyId: string; recipientTeamId: string };

// Wire shape from POST /projects/share — snake_case mirrors the backend payload exactly.
export interface ShareSummary {
  share_id: string;
  jti: string;
  ontology_id: string;
  ontology_name: string;
  recipient: ShareUser;
  share_role: ShareRole;
  status: ShareStatus;
  expires_at: string | null;
}

// Terminal states (revoked, superseded, left) are filtered out server-side for the inbox.
export type InboxStatus = "pending" | "accepted";

export interface InboxEntry {
  share_id: string;
  owner: ShareUser;
  ontology_id: string;
  ontology_name: string;
  share_role: ShareRole;
  status: InboxStatus;
  expires_at: string | null;
  created_at: string;
  accepted_at: string | null;
  // true iff the recipient's current pod still holds the JWT locally.
  // If status === "accepted" && has_local_token === false → claimed on another device.
  has_local_token: boolean;
  // Phase 2 — team-scoped shares. Absent (or "user") for direct shares.
  share_type?: ShareType;
  // Team-share only fields. `team_id` is the team the share targets;
  // `needs_claim` is true until the member claims (mints + vaults a scoped
  // token). On team rows expires_at / accepted_at are null.
  team_id?: string;
  needs_claim?: boolean;
}

// Wire shape from POST /share/team. No token is minted up front (members claim
// on first open), so this carries only the share row, not a jti/recipient user.
export interface TeamShareSummary {
  share_id: string;
  ontology_id: string;
  ontology_name: string;
  recipient_team_id: string;
  share_role: ShareRole;
  status: ShareStatus;
}

// Wire shape from POST /share/team/claim. Idempotent — rotates the member's
// scoped token. Mirrors AcceptedShare so the recipient UI can treat a claimed
// team share exactly like an accepted direct share.
export interface ClaimResult {
  share_id: string;
  ontology_id: string;
  ontology_name: string;
  share_role: ShareRole;
  status: ShareStatus;
}

export interface OutboxEntry {
  share_id: string;
  ontology_id: string;
  recipient_sub: string;
  recipient_username: string;
  recipient_organization: string;
  share_role: ShareRole;
  jti: string;
  status: ShareStatus;
  expires_at: string | null;
  created_at: string;
  updated_at: string;
  // Phase 2 — present when the backend surfaces team shares in the outbox
  // (GET /share/list). Absent (or "user") for direct shares; when "team", the
  // recipient_* user fields and jti/expires_at/accepted_at are null, the team
  // identity lives in team_id / recipient_team_id / team_name, and status is
  // "active".
  share_type?: ShareType;
  team_id?: string;
  recipient_team_id?: string;
  team_name?: string;
  // Team rows only — how many members have claimed the share so far. Drives the
  // "N joined" hint in the Manage Shares panel.
  claimed_count?: number;
}

export interface AcceptedShare {
  share_id: string;
  status: "accepted";
  ontology_id: string;
  ontology_name: string;
  share_role: ShareRole;
  owner: ShareUser;
}

export interface RevokeResult {
  share_id: string;
  status: "revoked";
}

// POST /projects/share/update-role response. `changed=false` is the backend's
// idempotency signal — the request was valid but the row already had that role,
// so the UI should surface a no-op toast instead of a success one.
export interface UpdateRoleResult extends ShareSummary {
  changed: boolean;
}

// POST /projects/share/team/update-role response. Same `changed` idempotency
// signal as UpdateRoleResult, but the team row has no recipient user — members
// converge on the new role at their next sync (≤24h).
export interface TeamUpdateRoleResult {
  share_id: string;
  ontology_id: string;
  recipient_team_id: string;
  share_role: ShareRole;
  status: ShareStatus;
  changed: boolean;
}

// One claimed member from GET /projects/share/team/grants (owner-only roster).
export interface TeamShareGrant {
  recipient_sub: string;
  claimed_at: string;
  last_seen_at: string | null;
}

// POST /projects/share/sync. `updated` counts share rows whose role was refreshed
// during reconciliation (added when role-edit landed alongside the existing
// prune/keep accounting).
export interface SyncResult {
  pruned: number;
  kept: number;
  updated: number;
}

// Backend response envelope: { status, message, data } for every share endpoint.
export interface ShareApiResponse<T> {
  status: ShareApiStatus;
  message: string;
  data: T;
}

// ── Concept-level restrictions ──────────────────────────────────────────────

// "read_write" (backend alias "writeable") elevates a concept above the share's
// base role — a concept can be editable even under a viewer share.
export type RestrictionLevel = "hidden" | "read_only" | "read_write";
export type RestrictionSubjectType = "user" | "team";

// A rule row is either a single-concept rule ("concept") or an ontology-level base
// override ("ontology", carried on GET /concept-restrictions with predicate_name "*").
export type RestrictionScope = "concept" | "ontology";

export interface ConceptRestriction {
  ontology_id: string;
  // "*" for ontology-level override rows (scope === "ontology").
  predicate_name: string;
  subject_type: RestrictionSubjectType;
  subject_id: string;
  recipient_sub: string | null;
  level: RestrictionLevel;
  scope: RestrictionScope;
  created_at: string;
  updated_at: string;
}

export interface SetRestrictionInput {
  ontology_id: string;
  predicate_name: string;
  level: RestrictionLevel;
  recipient_sub?: string;
  team_id?: string;
}

export interface ClearRestrictionInput {
  ontology_id: string;
  predicate_name: string;
  recipient_sub?: string;
  team_id?: string;
}

// ── Per-member project-level role override ──────────────────────────────────
// POST /ontologies/share/ontology-role gives one member a base role different from
// the team's (cascades to all concepts). User subject only. Once set, team rules
// stop applying to that member; only a user+concept rule can then change a single
// concept for them. DELETE reverts to the team base role.

export interface OntologyRoleOverrideInput {
  ontologyId: string;
  recipientSub: string;
  role: ShareRole;
}

export interface ClearOntologyRoleInput {
  ontologyId: string;
  recipientSub: string;
}

export interface OntologyRoleOverride {
  ontology_id: string;
  recipient_sub: string;
  role: ShareRole;
}

// ── Team-admin delegation ───────────────────────────────────────────────────
// Every permission mutation is issued either by the project owner (owner-only
// endpoints: /concept-restrictions, /ontology-role, /team/*) or delegated to an
// owner/admin of the recipient team via POST /projects/share/team-admin/apply.
// The reusable permission UI takes a PermissionCaller and routes accordingly.

export type PermissionCaller = { mode: "owner" } | { mode: "team_admin"; teamId: string };

export const OWNER_CALLER: PermissionCaller = { mode: "owner" };

// Discriminated action for POST /projects/share/team-admin/apply. The envelope
// also carries { ontology_id, team_id }; these are the action-specific fields.
// `subject_id` is a team member id for user-targeted rules, omitted for team-wide.
export type TeamAdminAction =
  | {
      // Delegated read — the owner-only GET /concept-restrictions asserts project
      // ownership (404 for a team admin), so team admins list via this action.
      action: "list_concept_restrictions";
      subject_type?: RestrictionSubjectType;
      subject_id?: string;
    }
  | {
      action: "set_concept_restriction";
      predicate_name: string;
      level: RestrictionLevel;
      subject_type: RestrictionSubjectType;
      subject_id?: string;
    }
  | {
      action: "clear_concept_restriction";
      predicate_name: string;
      subject_type: RestrictionSubjectType;
      subject_id?: string;
    }
  | { action: "set_project_role"; subject_id: string; role: ShareRole }
  | { action: "clear_project_role"; subject_id: string }
  | { action: "update_team_role"; share_role: ShareRole }
  | { action: "revoke_team" }
  | { action: "reenable_team"; share_role: ShareRole };

export type TeamAdminActionName = TeamAdminAction["action"];

// Typed error thrown by ShareService. Carries the API status (success/error/conflict) so
// the UI can distinguish 409-style conflicts (e.g. "already claimed on another device")
// from generic errors without parsing message strings.
export class ShareError extends Error {
  readonly apiStatus: Exclude<ShareApiStatus, "success">;
  readonly httpStatus: number;

  constructor(message: string, apiStatus: Exclude<ShareApiStatus, "success">, httpStatus = 0) {
    super(message);
    this.name = "ShareError";
    this.apiStatus = apiStatus;
    this.httpStatus = httpStatus;
  }
}
