import { OctagonPause, Play } from "lucide-react";

import { Button } from "@/shared/components/ui/button";

import { describeHalt, type HaltData } from "../halt.utils";

interface HaltNoticeProps {
  data: HaltData;
  /** Disabled while a turn is in flight, so Resume can't stack turns. */
  disabled?: boolean;
  onResume: () => void;
}

export function HaltNotice({ data, disabled, onResume }: HaltNoticeProps) {
  const { title, detail } = describeHalt(data);

  return (
    <div className="rounded-md border border-amber-500/40 bg-amber-50/60 p-3 text-sm dark:bg-amber-900/10">
      <header className="flex flex-wrap items-center gap-2 pb-1.5 text-xs text-muted-foreground">
        <OctagonPause className="h-3.5 w-3.5 text-amber-600 dark:text-amber-400" />
        <span className="font-medium uppercase tracking-wide">Halted</span>
      </header>

      <p className="text-foreground">{title}</p>
      <p className="pt-1 text-xs text-muted-foreground">{detail}</p>

      <footer className="mt-3 flex justify-end">
        <Button type="button" size="sm" disabled={disabled} onClick={onResume}>
          <Play className="mr-1 h-3.5 w-3.5" />
          Resume
        </Button>
      </footer>
    </div>
  );
}
