import { Share2, ShieldCheck } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { ContactToUpgradeDialog } from "@/features/billing/components/ContactToUpgradeDialog";
import { usePaidComputeEligibility } from "@/features/billing/hooks/usePaidComputeEligibility";
import {
  useCurrentOntologyName,
  useOntologyId,
  useOntologyScope,
} from "@/features/ontologies/hooks/useOntologyId";
import ShareOntologyDialog from "@/features/ontologies/sharing/components/ShareOntologyDialog";
import TeamAdminPermissionsDialog from "@/features/ontologies/sharing/components/TeamAdminPermissionsDialog";
import { useOntologyPermissionAccess } from "@/features/ontologies/sharing/hooks/useOntologyPermissionAccess";
import { Button } from "@/shared/components/ui/button";

// Header entry point for sharing / managing permissions of the open project.
//   - Project owner (user-scoped) → the full share dialog (invite + permissions).
//     Freemium accounts hit the upgrade wall instead.
//   - Owner/admin of the recipient team of a team share → the delegated
//     team-admin panel, routed through team-admin/apply.
//   - Everyone else → nothing.
export const OntologyShareButton: React.FC = () => {
  const ontologyId = useOntologyId();
  const ontologyScope = useOntologyScope();
  const { ontologyName } = useCurrentOntologyName();
  const { isEligible } = usePaidComputeEligibility();
  const access = useOntologyPermissionAccess();
  const [dialog, setDialog] = useState<null | "share" | "upgrade" | "teamAccess">(null);

  const isFreemium = isEligible === false;
  const isOwner = access.caller.mode === "owner";
  const isDelegatedAdmin = access.canManage && access.caller.mode === "team_admin";
  // Owners can only share user-scoped projects (org projects aren't shareable).
  const ownerCanShare = isOwner && access.canManage && ontologyScope === "user";

  if (!ontologyId || (!ownerCanShare && !isDelegatedAdmin)) return null;

  const handleClick = (): void => {
    if (isDelegatedAdmin) {
      setDialog("teamAccess");
      return;
    }
    setDialog(isFreemium ? "upgrade" : "share");
  };

  const title = isDelegatedAdmin ? "Manage team permissions" : "Share ontology";
  const Icon = isDelegatedAdmin ? ShieldCheck : Share2;

  return (
    <>
      <Button type="button" variant="outline" size="iconSm" onClick={handleClick} title={title}>
        <Icon className="h-3.5 w-3.5" />
      </Button>

      {dialog === "share" && (
        <ShareOntologyDialog
          isOpen
          onClose={() => setDialog(null)}
          ontologyId={ontologyId}
          ontologyName={ontologyName || ontologyId}
        />
      )}

      {dialog === "teamAccess" && access.teamId && (
        <TeamAdminPermissionsDialog
          isOpen
          onClose={() => setDialog(null)}
          ontologyId={ontologyId}
          ontologyName={ontologyName || ontologyId}
          teamId={access.teamId}
          teamName={access.teamName ?? "team"}
          ownerSub={access.ownerSub}
        />
      )}

      <ContactToUpgradeDialog
        open={dialog === "upgrade"}
        onOpenChange={(open) => setDialog(open ? "upgrade" : null)}
        title="Sharing is part of a paid subscription"
        description="Sharing ontologies with your team is available on a paid subscription. Contact Prometheux to upgrade and start collaborating."
        contactSubject="Upgrade request — team sharing"
      />
    </>
  );
};
