import { InfoHint as SharedInfoHint } from "@/shared/components/InfoHint";

interface InfoHintProps {
  text: string;
}

/** Small ⓘ affordance used across the editor to explain schema concepts.
 *  Thin adapter over the shared InfoHint: editor tooltips open to the left
 *  because the inspector sits against the right edge of the screen. */
export function InfoHint({ text }: InfoHintProps) {
  return <SharedInfoHint side="left">{text}</SharedInfoHint>;
}
