import type React from "react";
import { useCallback, useState } from "react";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import ExplorerTree from "@/features/concept-editor/components/ExplorerTree";
import type { UseEditorGroupsReturn } from "@/features/concept-editor/hooks/useEditorGroups";
import type { ConceptCell } from "@/features/concept-editor/types";
import { useOntologyId } from "@/features/ontologies/hooks/useOntologyId";
import ConceptRestrictionsDialog from "@/features/ontologies/sharing/components/ConceptRestrictionsDialog";
import { useOntologyPermissionAccess } from "@/features/ontologies/sharing/hooks/useOntologyPermissionAccess";
import { ErrorBoundary } from "@/shared/components/ErrorBoundary";

interface LineageExplorerPanelProps {
  groups: UseEditorGroupsReturn;
  cells: ConceptCell[];
  selectedCellId: string | null;
  onSelectCell: (cellId: string) => void;
  canEditOntologies: boolean;
  /** Create a new (blank) concept cell and return it. */
  onAddCell: () => ConceptCell;
  onRenameConcept?: (cellId: string, newName: string) => Promise<void>;
  onDeleteCell: (cellId: string) => Promise<void>;
  /** Isolate a concept's upstream dependency slice in the lineage graph. */
  onIsolateConcept?: (conceptName: string) => void;
  onOutputPredicateChange: (cellId: string, outputPredicate: string) => void;
  searchTerm: string;
  onSearchTermChange: (value: string) => void;
  onRefresh: () => void;
  isRefreshing: boolean;
  onSaveAll: () => void;
  isSavingAll: boolean;
  hasUnsavedChanges: boolean;
}

/**
 * The lineage view's left file-tree panel. A thin wrapper around ExplorerTree
 * that wires "add cell / add group" to also select the new cell so it opens in
 * the editor dock, and routes renames through the backend when the cell exists.
 */
const LineageExplorerPanel: React.FC<LineageExplorerPanelProps> = ({
  groups,
  cells,
  selectedCellId,
  onSelectCell,
  canEditOntologies,
  onAddCell,
  onRenameConcept,
  onDeleteCell,
  onIsolateConcept,
  onOutputPredicateChange,
  searchTerm,
  onSearchTermChange,
  onRefresh,
  isRefreshing,
  onSaveAll,
  isSavingAll,
  hasUnsavedChanges,
}) => {
  const ontologyId = useOntologyId();
  const permissionAccess = useOntologyPermissionAccess();
  const canSeeTeams = usePermissionsStore((s) => s.canSee("can_see_teams"));
  // Concept permissions are a teams-governance feature — gate behind can_see_teams.
  const canManagePermissions = permissionAccess.canManage && canSeeTeams;

  const [permissionsTarget, setPermissionsTarget] = useState<string | null>(null);

  const handleManagePermissions = useCallback((predicateName: string) => {
    setPermissionsTarget(predicateName);
  }, []);

  const handleAddCell = () => {
    const newCell = onAddCell();
    onSelectCell(newCell.id);
  };

  const handleAddGroup = () => {
    const newCell = onAddCell();
    onSelectCell(newCell.id);
    groups.startCreateGroupWithNewCell(newCell.id);
  };

  const handleAddCellInGroup = (groupName: string | null) => {
    const newCell = onAddCell();
    if (groupName) groups.handleAddCellToGroup(newCell.id, groupName);
    onSelectCell(newCell.id);
  };

  const handleRenameCell = async (cellId: string, newName: string) => {
    const cell = cells.find((c) => c.id === cellId);
    if (cell?.cellBackendId && onRenameConcept) {
      await onRenameConcept(cellId, newName);
      return;
    }
    onOutputPredicateChange(cellId, newName);
  };

  return (
    <>
      <ExplorerTree
        groupNames={groups.groupNames}
        groupedCells={groups.groupedCells}
        ungroupedCells={groups.ungroupedCells}
        collapsedGroups={groups.collapsedGroups}
        selectedCellId={selectedCellId}
        onSelectCell={onSelectCell}
        onToggleGroupCollapse={groups.handleToggleGroupCollapse}
        canEditOntologies={canEditOntologies}
        onAddCell={canEditOntologies ? handleAddCell : undefined}
        onAddGroup={canEditOntologies ? handleAddGroup : undefined}
        onAddCellToGroup={groups.handleAddCellToGroup}
        onRemoveCellFromGroup={groups.handleRemoveCellFromGroup}
        onAddCellInGroup={canEditOntologies ? handleAddCellInGroup : undefined}
        onRenameCell={canEditOntologies ? handleRenameCell : undefined}
        onDeleteCell={canEditOntologies ? onDeleteCell : undefined}
        onIsolateConcept={onIsolateConcept}
        onRenameGroup={canEditOntologies ? groups.openRenameGroupDialog : undefined}
        onDeleteGroup={canEditOntologies ? groups.handleDeleteGroup : undefined}
        onExpandAllGroups={groups.expandAllGroups}
        onCollapseAllGroups={groups.collapseAllGroups}
        searchTerm={searchTerm}
        onSearchTermChange={onSearchTermChange}
        onRefresh={onRefresh}
        isRefreshing={isRefreshing}
        onSaveAll={onSaveAll}
        isSavingAll={isSavingAll}
        hasUnsavedChanges={hasUnsavedChanges}
        onManagePermissions={canManagePermissions ? handleManagePermissions : undefined}
        isOntologyOwner={permissionAccess.canManage}
      />
      {permissionsTarget && ontologyId && (
        <ErrorBoundary inline>
          <ConceptRestrictionsDialog
            isOpen
            onClose={() => setPermissionsTarget(null)}
            ontologyId={ontologyId}
            predicateName={permissionsTarget}
            caller={permissionAccess.caller}
            ownerSub={permissionAccess.ownerSub}
          />
        </ErrorBoundary>
      )}
    </>
  );
};

export default LineageExplorerPanel;
