import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

export interface DatabricksCredentialSubmission {
  auth_mode: "token" | "oauth2";
  token?: string;
  client_id?: string;
  client_secret?: string;
  /** Only when the workspace is not configured yet. */
  host?: string;
}

/**
 * Hand a credential the user typed into the assistant's secure form to the
 * backend, over its own request.
 *
 * This is why the value never appears in the conversation: it goes from the form
 * to the in-memory credential store directly, so it is not a chat message, is
 * not in the model's context, and is not written to the chat history. The
 * endpoint accepts credential fields only, so a submission cannot repoint the
 * cluster or the JAR location.
 *
 * Throws on failure — unlike the settings page's best-effort sync, the user is
 * waiting on this one and has to be told if it did not land.
 */
export async function submitDatabricksCredentials(
  submission: DatabricksCredentialSubmission,
): Promise<void> {
  const response = await fetch(
    `${PROMETHEUX_CONFIG.BASE_URL}/compute/databricks/session/credentials`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${PROMETHEUX_CONFIG.AUTH_TOKEN}`,
      },
      body: JSON.stringify(submission),
    },
  );

  if (!response.ok) {
    throw new Error(await readErrorMessage(response));
  }
}

async function readErrorMessage(response: Response): Promise<string> {
  try {
    const body: unknown = await response.json();
    if (typeof body === "object" && body !== null && "message" in body) {
      const { message } = body as { message?: unknown };
      if (typeof message === "string" && message) return message;
    }
  } catch {
    // A response that is not JSON tells us nothing more than its status did.
  }
  return `The credentials could not be saved (${response.status}).`;
}
