import { AppWindow } from "lucide-react";
import { useState } from "react";
import type { OntologyData } from "@/features/ontologies/api";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";

interface NewAppSetupProps {
  projects: OntologyData[];
  onCreate: (name: string, ontologyId: string) => void;
}

/**
 * First step of the new-app flow: pick the home project (where the app is
 * stored and where its first page's concepts resolve — ADR D9) and name it.
 * Creating scaffolds an empty v2 definition straight into the app editor;
 * nothing is persisted until the first save.
 */
export function NewAppSetup({ projects, onCreate }: NewAppSetupProps) {
  const [name, setName] = useState("");
  const [ontologyId, setOntologyId] = useState("");

  const canCreate = name.trim().length > 0 && ontologyId.length > 0;

  const handleCreate = () => {
    if (canCreate) onCreate(name.trim(), ontologyId);
  };

  return (
    <div className="flex flex-1 items-center justify-center p-6">
      <div className="w-full max-w-md rounded-lg border border-border bg-card p-6 flex flex-col gap-4">
        <div className="flex items-center gap-2.5">
          <AppWindow className="h-4.5 w-4.5 text-muted-foreground" />
          <h2 className="text-sm font-semibold">New app</h2>
        </div>

        <label className="flex flex-col gap-1.5">
          <span className="text-[11px] font-medium text-muted-foreground">App name</span>
          <Input
            value={name}
            autoFocus
            placeholder="e.g. Portfolio Operations"
            onChange={(event) => setName(event.target.value)}
            onKeyDown={(event) => event.key === "Enter" && handleCreate()}
          />
        </label>

        <div className="flex flex-col gap-1.5">
          <span className="text-[11px] font-medium text-muted-foreground">Ontology</span>
          <Select value={ontologyId} onValueChange={setOntologyId}>
            <SelectTrigger>
              <SelectValue placeholder="Select the ontology the app is built on" />
            </SelectTrigger>
            <SelectContent>
              {projects.map((project) => (
                <SelectItem key={project.id} value={project.id} className="text-sm">
                  {project.name || project.id}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-[11px] text-muted-foreground leading-relaxed">
            The app lives in this project and its first page runs against this project's lineage.
            Pages added later can reference other projects.
          </p>
        </div>

        <Button onClick={handleCreate} disabled={!canCreate} className="self-end">
          Create app
        </Button>
      </div>
    </div>
  );
}
