import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { DashboardClient, DashboardValidationError } from "../../api/DashboardClient";
import { PUBLISHING_UI_ENABLED } from "../../publishing";
import type { AppDefinition } from "../../schema/appDefinition.types";
import { useAppEditorStore } from "../../store/appEditorStore";

const client = new DashboardClient();

interface UseAppEditorSaveReturn {
  save: (definition: AppDefinition) => Promise<boolean>;
  isSaving: boolean;
  errors: string[];
  clearErrors: () => void;
}

/**
 * Save-with-validation for the editor draft. Every save is hard-validated
 * server-side against the lineage (ADR D3/D6); validation failures surface as
 * the error list, anything else as a toast. A successful save marks the draft
 * clean and refreshes the dashboard queries.
 */
export function useAppEditorSave(storageOntologyId: string): UseAppEditorSaveReturn {
  const queryClient = useQueryClient();
  const markSaved = useAppEditorStore((state) => state.markSaved);
  const navigate = useNavigate();
  const location = useLocation();
  const [isSaving, setIsSaving] = useState(false);
  const [errors, setErrors] = useState<string[]>([]);

  const save = useCallback(
    async (definition: AppDefinition): Promise<boolean> => {
      setIsSaving(true);
      setErrors([]);
      try {
        const savedId = await client.saveDashboard(storageOntologyId, definition);
        markSaved();
        // Publishing is hidden until governance lands — every save publishes
        // its checkpoint so viewers always see the latest state.
        if (!PUBLISHING_UI_ENABLED) {
          try {
            await client.publishDashboard(storageOntologyId, savedId);
          } catch {
            toast.error("Saved, but publishing the new version failed");
          }
        }
        queryClient.invalidateQueries({ queryKey: ["all-dashboards"] });
        queryClient.invalidateQueries({ queryKey: ["dashboard", storageOntologyId, savedId] });
        queryClient.invalidateQueries({
          queryKey: ["dashboard-record", storageOntologyId, savedId],
        });
        queryClient.invalidateQueries({
          queryKey: ["dashboard-versions", storageOntologyId, savedId],
        });
        toast.success("App saved — definition validated against the lineage");
        // First save of a new app: swap /apps/new/edit for the canonical edit
        // route so refresh and deep links keep the session instead of
        // restarting the New App flow.
        if (location.pathname === "/apps/new/edit") {
          navigate(`/apps/${storageOntologyId}/${savedId}/edit`, { replace: true });
        }
        return true;
      } catch (err: unknown) {
        if (err instanceof DashboardValidationError) {
          setErrors(err.errors);
          return false;
        }
        setErrors([err instanceof Error ? err.message : "Failed to save the app"]);
        return false;
      } finally {
        setIsSaving(false);
      }
    },
    [storageOntologyId, markSaved, queryClient, navigate, location.pathname],
  );

  const clearErrors = useCallback(() => setErrors([]), []);

  return { save, isSaving, errors, clearErrors };
}
