import type { FocusedWidgetRef } from "@/features/code-assistant/agentContext";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import type { AppDefinition, AppPageDef, AppWidgetDef } from "../../schema/appDefinition.types";

function widgetBindings(page: AppPageDef, widget: AppWidgetDef): Record<string, string> {
  const bindings: Record<string, string> = {};
  if (widget.outputId) {
    bindings.outputId = widget.outputId;
    const concept = page.runGroups
      .flatMap((group) => group.outputs ?? [])
      .find((tap) => tap.id === widget.outputId)?.concept;
    if (concept) bindings.concept = concept;
  }
  if (widget.inputId) bindings.inputId = widget.inputId;
  if (widget.groupId) bindings.groupId = widget.groupId;
  if (widget.action?.type === "run_group" && widget.action.groupId) {
    bindings.groupId = widget.action.groupId;
  }
  return bindings;
}

/**
 * Select-widget-as-reference (ADR D7 / NEXT item 3): packages the selected
 * widget as a structured reference into the assistant session and opens the
 * panel — the user asks in their own words, never naming components.
 */
export function askAssistantAboutWidget(
  definition: AppDefinition,
  page: AppPageDef,
  sectionId: string,
  widget: AppWidgetDef,
): void {
  const reference: FocusedWidgetRef = {
    dashboardId: definition.id,
    dashboardName: definition.name,
    ontologyId: page.project.id,
    pageId: page.id,
    pageLabel: page.label,
    sectionId,
    widgetId: widget.id,
    widgetType: widget.type,
    bindings: widgetBindings(page, widget),
  };
  const { setFocusedWidget, openPanel } = useCodeAssistantStore.getState();
  setFocusedWidget(reference);
  openPanel();
}

/**
 * One-click fix-it (adopted market lesson): hand the save-time validation
 * errors to the assistant with no prompt-writing. Seeds a ready-to-send
 * message naming the app and its errors, and opens the panel; the user
 * reviews and sends (a turn may call save_dashboard).
 */
export function askAssistantToFix(
  definition: AppDefinition,
  storageOntologyId: string,
  errors: string[],
): void {
  const errorList = errors.map((e) => `- ${e}`).join("\n");
  const prompt = [
    `The app "${definition.name}" (dashboard id ${definition.id}, ontology ${storageOntologyId}) `,
    "failed to save with these validation errors:",
    errorList,
    "",
    "Load it with get_app, fix the definition so it passes validation, and save it with save_app.",
  ].join("\n");
  const { setSeededPrompt, openPanel } = useCodeAssistantStore.getState();
  setSeededPrompt(prompt);
  openPanel();
}
