import { Inbox } from "lucide-react";
import type { SparkJob } from "../types/engineMonitor.types";
import { jobStatusBadgeClass } from "../utils/engineMonitor.utils";

interface EngineMonitorJobsProps {
  jobs: SparkJob[];
}

interface MetricCellProps {
  value: number;
  accent?: "danger" | "muted";
}

const MetricCell: React.FC<MetricCellProps> = ({ value, accent }) => {
  if (value === 0 && accent === "muted") {
    return <span className="text-muted-foreground/60 tabular-nums">0</span>;
  }
  if (value > 0 && accent === "danger") {
    return (
      <span className="tabular-nums font-semibold text-red-600 dark:text-red-400">{value}</span>
    );
  }
  return <span className="tabular-nums text-foreground">{value}</span>;
};

const StatusBadge: React.FC<{ status: string }> = ({ status }) => (
  <span
    className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide ${jobStatusBadgeClass(
      status,
    )}`}
  >
    <span className="inline-block h-1 w-1 rounded-full bg-current" />
    {status}
  </span>
);

const EngineMonitorJobs: React.FC<EngineMonitorJobsProps> = ({ jobs }) => {
  if (jobs.length === 0) {
    return (
      <div className="p-3">
        <div className="flex flex-col items-center justify-center gap-2 rounded-lg border border-dashed border-border bg-muted/30 p-8 text-center">
          <Inbox className="h-8 w-8 text-muted-foreground/50" />
          <div className="text-sm font-medium text-foreground">No jobs yet</div>
          <div className="text-xs text-muted-foreground">
            Jobs will appear here once Spark begins executing stages.
          </div>
        </div>
      </div>
    );
  }

  const sortedJobs = [...jobs].sort((a, b) => b.jobId - a.jobId);

  return (
    <div className="p-3">
      <div className="rounded-lg border border-border bg-card overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-xs">
            <thead>
              <tr className="border-b border-border bg-muted/40">
                <th className="w-16 text-left px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  ID
                </th>
                <th className="text-left px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Name
                </th>
                <th className="w-28 text-left px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Status
                </th>
                <th className="w-16 text-right px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Tasks
                </th>
                <th className="w-16 text-right px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Active
                </th>
                <th className="w-20 text-right px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Done
                </th>
                <th className="w-16 text-right px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Failed
                </th>
              </tr>
            </thead>
            <tbody>
              {sortedJobs.map((job, idx) => {
                const rowBg = idx % 2 === 0 ? "bg-transparent" : "bg-muted/20";
                return (
                  <tr
                    key={job.jobId}
                    className={`${rowBg} border-b border-border/50 last:border-0 hover:bg-muted/50 transition-colors`}
                  >
                    <td className="px-3 py-2">
                      <span className="inline-block rounded bg-muted px-1.5 py-0.5 font-mono text-[11px] text-foreground">
                        {job.jobId}
                      </span>
                    </td>
                    <td
                      className="px-3 py-2 max-w-[320px] truncate text-foreground"
                      title={job.name}
                    >
                      {job.name}
                    </td>
                    <td className="px-3 py-2">
                      <StatusBadge status={job.status} />
                    </td>
                    <td className="px-3 py-2 text-right">
                      <MetricCell value={job.numTasks ?? 0} />
                    </td>
                    <td className="px-3 py-2 text-right">
                      <MetricCell value={job.numActiveTasks ?? 0} accent="muted" />
                    </td>
                    <td className="px-3 py-2 text-right">
                      <MetricCell value={job.numCompletedTasks ?? 0} />
                    </td>
                    <td className="px-3 py-2 text-right">
                      <MetricCell value={job.numFailedTasks ?? 0} accent="danger" />
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default EngineMonitorJobs;
