import { useMemo } from "react";
import {
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import type { FetchResult } from "../../api/ConceptClient";

const LINE_COLOR = "#6366f1";

interface LineChartOutputProps {
  data: FetchResult;
  xCol: number;
  yCol: number;
  fullscreen?: boolean;
}

export function LineChartOutput({ data, xCol, yCol, fullscreen = false }: LineChartOutputProps) {
  const xLabel = data.columnNames[xCol] ?? `col_${xCol}`;
  const yLabel = data.columnNames[yCol] ?? `col_${yCol}`;

  const chartData = useMemo(
    () =>
      data.rows.map((row) => ({
        [xLabel]: row[xCol] !== null && row[xCol] !== undefined ? String(row[xCol]) : "",
        [yLabel]: Number(row[yCol]) || 0,
      })),
    [data.rows, xCol, yCol, xLabel, yLabel],
  );

  if (chartData.length === 0) {
    return <p className="text-xs text-muted-foreground py-4">No data</p>;
  }

  return (
    <ResponsiveContainer width="100%" height={fullscreen ? "100%" : 280}>
      <LineChart data={chartData} margin={{ top: 8, right: 16, bottom: 20, left: 8 }}>
        <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
        <XAxis
          dataKey={xLabel}
          tick={{ fontSize: 11 }}
          tickLine={false}
          axisLine={false}
          interval="preserveStartEnd"
        />
        <YAxis tick={{ fontSize: 11 }} tickLine={false} axisLine={false} width={48} />
        <Tooltip
          contentStyle={{ fontSize: 12, borderRadius: 6 }}
          labelStyle={{ fontWeight: 600 }}
        />
        <Legend wrapperStyle={{ fontSize: 12 }} />
        <Line
          type="monotone"
          dataKey={yLabel}
          stroke={LINE_COLOR}
          strokeWidth={2}
          dot={{ r: 3 }}
          activeDot={{ r: 5 }}
        />
      </LineChart>
    </ResponsiveContainer>
  );
}
