import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Loader2 } from "lucide-react";
import { useMemo, useState } from "react";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";

import { ContextNoteApi } from "../api";
import { AttachedNoteEditor } from "../concept-context/AttachedNoteEditor";
import { useAllContextEdges } from "../hooks/useContextEdges";
import { useContextNotes } from "../hooks/useContextNotes";
import { useNoteActions } from "../notes/hooks/useNoteActions";
import { noteDisplayTitle } from "../notes/notesModel";

interface NoteDockPanelProps {
  /** null = draft mode: a new project-scoped note, persisted on Save. */
  noteId: string | null;
  ontologyId: string;
  onClose: () => void;
  /** Draft saved — switch the dock to the persisted note. */
  onCreated: (noteId: string) => void;
}

/**
 * The Explorer dock showing a standalone context note (one not attached to
 * any concept) — same full-featured markdown editor the concept context
 * tab uses, just without a concept graph around it. Also hosts the
 * "new project note" draft from the Context rail's plus button.
 */
export function NoteDockPanel({ noteId, ontologyId, onClose, onCreated }: NoteDockPanelProps) {
  const queryClient = useQueryClient();
  const [isSaving, setIsSaving] = useState(false);
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const isDraft = noteId === null;

  const { data: note, isLoading } = useQuery({
    queryKey: ["context-note", noteId ?? ""],
    queryFn: () => ContextNoteApi.get(noteId ?? ""),
    enabled: !isDraft,
  });
  const { data: globalNotes } = useContextNotes({ scope: "global" });
  const { data: ontologyNotes } = useContextNotes({ scope: "ontology", scopeId: ontologyId });
  const { data: allEdges } = useAllContextEdges();
  const actions = useNoteActions({ scope: "ontology", scopeId: ontologyId });

  const linkCandidates = useMemo(
    () => [...(globalNotes ?? []), ...(ontologyNotes ?? [])],
    [globalNotes, ontologyNotes],
  );

  const handleSave = async (text: string) => {
    setIsSaving(true);
    try {
      if (isDraft) {
        const created = await actions.createNote({ text, folderPath: "", linkCandidates });
        if (created) {
          queryClient.setQueryData(["context-note", created.id], created);
          onCreated(created.id);
        }
        return;
      }
      if (!note) return;
      const noteEdges = (allEdges ?? []).filter(
        (edge) => edge.src_id === note.id || edge.dst_id === note.id,
      );
      const saved = await actions.saveNoteText(note, text, linkCandidates, noteEdges);
      if (saved) {
        queryClient.setQueryData(["context-note", noteId ?? ""], saved);
      }
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = () => {
    setConfirmingDelete(false);
    if (!noteId) return;
    actions.deleteNote(noteId);
    onClose();
  };

  if (isDraft) {
    return (
      <div className="min-h-0 flex-1 p-3">
        <AttachedNoteEditor
          key="draft"
          note={null}
          linkCandidates={linkCandidates}
          onSave={handleSave}
          onClose={onClose}
          isSaving={isSaving}
        />
      </div>
    );
  }

  if (isLoading || !note) {
    return (
      <div className="flex flex-1 items-center justify-center gap-2 text-sm text-muted-foreground">
        <Loader2 className="h-4 w-4 animate-spin" />
        Loading note…
      </div>
    );
  }

  return (
    <div className="min-h-0 flex-1 p-3">
      <AttachedNoteEditor
        key={note.id}
        note={note}
        linkCandidates={linkCandidates}
        onSave={handleSave}
        onDelete={() => setConfirmingDelete(true)}
        onClose={onClose}
        isSaving={isSaving}
      />
      <AlertDialog open={confirmingDelete} onOpenChange={(next) => setConfirmingDelete(next)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete "{noteDisplayTitle(note)}"?</AlertDialogTitle>
            <AlertDialogDescription>
              The note and all of its links are removed permanently. The assistant will no longer
              retrieve it.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete note
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
