import { patchApp } from "../../../store/appEditorMutations";
import { useAppEditorStore } from "../../../store/appEditorStore";
import { TextField } from "./fields";

/** Default inspector (nothing selected): the app shell — name and header. */
export function AppInspector() {
  const draft = useAppEditorStore((state) => state.draft);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);
  if (!draft) return null;

  const patchHeader = (patch: Partial<typeof draft.header>) => {
    updateDraft((current) => patchApp(current, { header: { ...current.header, ...patch } }));
  };

  return (
    <div className="flex flex-col gap-2.5">
      <TextField
        label="App name"
        value={draft.name}
        onChange={(value) => updateDraft((current) => patchApp(current, { name: value ?? "" }))}
      />
      <TextField
        label="Header title"
        value={draft.header?.title}
        onChange={(value) => patchHeader({ title: value ?? "" })}
      />
      <TextField
        label="Header subtitle"
        value={draft.header?.subtitle}
        onChange={(value) => patchHeader({ subtitle: value })}
      />
      <TextField
        label="Logo URL"
        value={draft.header?.logoUrl}
        onChange={(value) => patchHeader({ logoUrl: value })}
      />
      <p className="text-[10px] text-muted-foreground leading-relaxed">
        Select a widget in the preview, or a node in the Structure / Data panels, to edit it here.
      </p>
    </div>
  );
}
