import { Copy, Plus } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { toast } from "sonner";
import { getDataSourcePath } from "@/features/data-sources/utils";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/shared/components/ui/accordion";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";

interface DataSourceCardProps {
  tableName: string;
  datasourceType: string;
  predicatePlaceholder?: string;
  fields?: Record<string, string>;
  columnCount?: number;
  rowCount?: number;
  onCreateConcept?: () => Promise<void>;
  flat?: boolean;
  databaseName?: string;
}

const DataSourceCard: React.FC<DataSourceCardProps> = ({
  tableName,
  datasourceType,
  predicatePlaceholder,
  fields = {},
  columnCount = 0,
  rowCount,
  onCreateConcept,
  flat = false,
  databaseName,
}) => {
  const [_isExpanded, setIsExpanded] = useState(false);
  const [isCreating, setIsCreating] = useState(false);
  const fieldNames = Object.keys(fields);
  const filePath = getDataSourcePath({ databaseName, tableName });

  const handleCreateConcept = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!onCreateConcept || isCreating) return;
    setIsCreating(true);
    try {
      await onCreateConcept();
    } finally {
      setIsCreating(false);
    }
  };

  const handleCopy = () => {
    const placeholder = predicatePlaceholder || tableName;
    const signature =
      fieldNames.length > 0 ? `${placeholder}(${fieldNames.join(",")})` : placeholder;
    navigator.clipboard.writeText(signature);
    toast.success(`Copied to clipboard`);
  };

  const typeLabel = datasourceType || "unknown";

  const actionButtons = (
    <>
      {onCreateConcept && (
        <Button
          variant="ghost"
          size="sm"
          onClick={handleCreateConcept}
          disabled={isCreating}
          className="h-7 w-7 p-0 hover:bg-muted flex-shrink-0 opacity-0 group-hover:opacity-100 transition-opacity duration-200"
          title="Create concept from this data source"
        >
          {isCreating ? <PrometheuxSpinner size={16} /> : <Plus className="h-3.5 w-3.5" />}
        </Button>
      )}
      <Button
        variant="ghost"
        size="sm"
        onClick={(e) => {
          e.stopPropagation();
          handleCopy();
        }}
        className="h-7 w-7 p-0 hover:bg-muted flex-shrink-0 opacity-0 group-hover:opacity-100 transition-opacity duration-200"
        title="Copy predicate signature"
      >
        <Copy className="h-3.5 w-3.5" />
      </Button>
    </>
  );

  if (flat) {
    return (
      <Accordion type="single" collapsible onValueChange={(value) => setIsExpanded(!!value)}>
        <AccordionItem value="item-1" className="border-0 relative group">
          <AccordionTrigger className="px-0 py-2.5 hover:no-underline w-full hover:bg-muted/30 transition-colors duration-200 rounded">
            <div className="flex items-center w-full px-2 max-w-[calc(100%-1rem)]">
              <div className="flex-1 min-w-0 text-left">
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="text-xs leading-tight font-medium truncate block">
                        {tableName}
                        <span className="font-normal text-muted-foreground ml-1">
                          ({columnCount || fieldNames.length} columns)
                        </span>
                      </span>
                    </TooltipTrigger>
                    <TooltipContent>
                      <p>{tableName}</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
                {filePath && (
                  <TooltipProvider>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <span className="text-[10px] text-muted-foreground truncate block">
                          {filePath}
                        </span>
                      </TooltipTrigger>
                      <TooltipContent side="bottom" className="max-w-sm break-all">
                        <p>{filePath}</p>
                      </TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                )}
              </div>
              <div className="flex items-center gap-0.5 flex-shrink-0">{actionButtons}</div>
            </div>
          </AccordionTrigger>
          <AccordionContent className="px-2 pb-2 pt-1">
            {fieldNames.length > 0 ? (
              <table className="w-full text-xs">
                <thead>
                  <tr className="border-b border-border/40">
                    <th className="text-left font-medium text-muted-foreground py-1 pr-4">Name</th>
                    <th className="text-left font-medium text-muted-foreground py-1">Type</th>
                  </tr>
                </thead>
                <tbody>
                  {fieldNames.map((fieldName) => (
                    <tr key={fieldName} className="border-b border-border/20 last:border-b-0">
                      <td className="py-1 pr-4 font-mono text-foreground">{fieldName}</td>
                      <td className="py-1 text-muted-foreground">{fields[fieldName]}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <p className="text-xs text-muted-foreground">No schema information available</p>
            )}
          </AccordionContent>
        </AccordionItem>
      </Accordion>
    );
  }

  return (
    <Accordion
      type="single"
      collapsible
      className="mb-4 rounded-lg overflow-hidden bg-card"
      onValueChange={(value) => setIsExpanded(!!value)}
    >
      <AccordionItem value="item-1" className="border rounded-lg relative group">
        <AccordionTrigger className="px-3 py-1 hover:no-underline w-full hover:bg-muted/50 transition-colors duration-200">
          <div className="flex flex-col w-full max-w-[calc(100%-1rem)]">
            <div className="flex items-center w-full">
              <div className="flex-1 min-w-0 text-left">
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="text-sm leading-tight font-medium truncate block">
                        {tableName}
                      </span>
                    </TooltipTrigger>
                    <TooltipContent>
                      <p>{tableName}</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </div>
              <div className="flex items-center gap-0.5 flex-shrink-0">{actionButtons}</div>
            </div>
            <div className="flex items-center gap-1 text-xs text-muted-foreground w-full">
              <Badge variant="outline" className="text-xs px-1.5 py-0 h-4">
                {typeLabel}
              </Badge>
              <span>{columnCount || fieldNames.length} columns</span>
              {rowCount != null && rowCount > 0 && <span>· {rowCount.toLocaleString()} rows</span>}
            </div>
            {filePath && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span className="text-[10px] text-muted-foreground truncate block mb-2 w-full text-left">
                      {filePath}
                    </span>
                  </TooltipTrigger>
                  <TooltipContent side="bottom" className="max-w-sm break-all">
                    <p>{filePath}</p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}
            {!filePath && <div className="mb-1" />}
          </div>
        </AccordionTrigger>
        <AccordionContent className="px-3 pb-3 pt-2">
          {fieldNames.length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {fieldNames.map((fieldName) => (
                <div
                  key={fieldName}
                  className="flex flex-wrap items-center gap-1 text-xs bg-muted/80 rounded px-2 py-1"
                >
                  <span className="font-medium text-foreground">{fieldName}</span>
                  <Badge variant="outline" className="text-xs px-1 py-0 h-4 bg-card">
                    {fields[fieldName]}
                  </Badge>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-xs text-muted-foreground">No schema information available</p>
          )}
        </AccordionContent>
      </AccordionItem>
    </Accordion>
  );
};

export default DataSourceCard;
