// Typed error for the freemium per-run ceiling. The backend rejects a run that
// exceeds the wall-clock timeout or the output-row cap with a structured body
// carrying a stable `code` (mirrors the AgentMessageLimitError pattern). Match
// on `code` — never on the message string.

export const RUN_TIMEOUT_CODE = "RUN_TIMEOUT_EXCEEDED";
export const RUN_ROW_LIMIT_CODE = "RUN_ROW_LIMIT_EXCEEDED";

export type RunLimitKind = "timeout" | "rows";

interface RunLimitErrorParams {
  code: string;
  kind: RunLimitKind;
  message: string;
  limit: number | null;
}

export class RunLimitExceededError extends Error {
  readonly code: string;
  readonly kind: RunLimitKind;
  readonly limit: number | null;

  constructor({ code, kind, message, limit }: RunLimitErrorParams) {
    super(message);
    this.name = "RunLimitExceededError";
    this.code = code;
    this.kind = kind;
    this.limit = limit;
  }
}

interface RunLimitBody {
  code: string;
  message?: string;
  limit?: number | null;
  limit_seconds?: number | null;
  limit_rows?: number | null;
}

const isRunLimitBody = (value: unknown): value is RunLimitBody => {
  if (typeof value !== "object" || value === null) return false;
  const body = value as Record<string, unknown>;
  return body.code === RUN_TIMEOUT_CODE || body.code === RUN_ROW_LIMIT_CODE;
};

const pickLimit = (body: RunLimitBody): number | null => {
  if (typeof body.limit_seconds === "number") return body.limit_seconds;
  if (typeof body.limit_rows === "number") return body.limit_rows;
  if (typeof body.limit === "number") return body.limit;
  return null;
};

/**
 * Returns a typed RunLimitExceededError when `data` is a freemium run-ceiling
 * body, otherwise null so the caller can fall back to a generic error.
 */
export const parseRunLimitError = (data: unknown): RunLimitExceededError | null => {
  if (!isRunLimitBody(data)) return null;
  const kind: RunLimitKind = data.code === RUN_TIMEOUT_CODE ? "timeout" : "rows";
  return new RunLimitExceededError({
    code: data.code,
    kind,
    message: data.message || "This run hit a limit on the free plan.",
    limit: pickLimit(data),
  });
};
