import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { listTeamInvitations, revokeTeamInvitation } from "../api";
import type { TeamError, TeamPendingInvitation } from "../types";

// Shared prefix so cross-hook invalidations (invite from useTeamMembers,
// accept/decline from useTeamInvitations) can target every pending list
// without knowing the specific teamId — RQ matches on prefix.
export const TEAM_PENDING_INVITATIONS_KEY = ["teams", "pending-invitations"] as const;
const pendingInvitationsKey = (teamId: string, userId: string) =>
  [...TEAM_PENDING_INVITATIONS_KEY, teamId, userId] as const;

interface UseTeamPendingInvitationsOptions {
  enabled?: boolean;
}

interface UseTeamPendingInvitationsReturn {
  invitations: TeamPendingInvitation[];
  isLoading: boolean;
  isFetching: boolean;
  error: TeamError | null;
  refresh: () => Promise<unknown>;

  revoke: (invitationId: string) => Promise<{
    team_id: string;
    invitation_id: string;
    status: "revoked";
  }>;
  isRevoking: boolean;
  revokingInvitationId: string | null;
}

// Team-side outbox of pending invitations for a single team + the revoke
// mutation. Owner/admin only — for non-admin callers the backend returns an
// empty list, and the UI is expected to gate the whole section behind the
// caller's role before mounting this hook.
//
// Deliberately separate from useTeamInvitations (which is the invitee's own
// inbox) so the two never accidentally share a cache slot.
export function useTeamPendingInvitations(
  teamId: string | null | undefined,
  { enabled = true }: UseTeamPendingInvitationsOptions = {},
): UseTeamPendingInvitationsReturn {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";
  const safeTeamId = teamId ?? "";

  const query = useQuery<TeamPendingInvitation[], TeamError>({
    queryKey: pendingInvitationsKey(safeTeamId, userId),
    queryFn: () => listTeamInvitations(safeTeamId, supabaseToken),
    enabled: enabled && Boolean(userId && supabaseToken && safeTeamId),
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const revokeMutation = useMutation<
    { team_id: string; invitation_id: string; status: "revoked" },
    TeamError,
    string
  >({
    mutationFn: (invitationId) => revokeTeamInvitation(safeTeamId, invitationId, supabaseToken),
    onSuccess: () => {
      // Refresh this team's pending list. No need to touch member/roster
      // queries — a revoked invite never became a membership.
      queryClient.invalidateQueries({
        queryKey: [...TEAM_PENDING_INVITATIONS_KEY, safeTeamId],
      });
    },
  });

  return {
    invitations: query.data ?? [],
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    refresh: query.refetch,

    revoke: revokeMutation.mutateAsync,
    isRevoking: revokeMutation.isPending,
    revokingInvitationId: revokeMutation.isPending ? (revokeMutation.variables ?? null) : null,
  };
}
