import type React from "react";
import { cn } from "@/shared/lib/utils";

interface ExplorerHeaderIconButtonProps {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  /** Visually highlights the button and sets aria-pressed=true. */
  active?: boolean;
}

/** Small icon button used for actions in Explorer-style panel headers. */
export const ExplorerHeaderIconButton: React.FC<ExplorerHeaderIconButtonProps> = ({
  icon,
  label,
  onClick,
  active,
}) => (
  <button
    type="button"
    onClick={onClick}
    title={label}
    aria-pressed={active}
    className={cn(
      "h-6 w-6 inline-flex items-center justify-center rounded text-muted-foreground hover:bg-accent hover:text-accent-foreground",
      active && "bg-accent text-accent-foreground",
    )}
  >
    {icon}
  </button>
);
