import { ChevronRight, type LucideIcon } from "lucide-react";
import { IconChip } from "@/shared/components/ui/IconChip";

interface SettingsNavCardProps {
  icon: LucideIcon;
  title: string;
  description: string;
  onClick: () => void;
}

// A single settings entry, rendered as a row inside SettingsNavList's grouped
// container: an icon chip, a title + muted description, and a chevron affordance.
const SettingsNavCard = ({ icon, title, description, onClick }: SettingsNavCardProps) => (
  <button
    type="button"
    onClick={onClick}
    className="group flex w-full items-center gap-4 px-4 py-4 text-left transition-colors hover:bg-accent/50"
  >
    <IconChip icon={icon} size="md" />
    <div className="min-w-0 flex-1">
      <p className="text-sm font-medium leading-none text-foreground">{title}</p>
      <p className="mt-1.5 text-sm leading-snug text-muted-foreground">{description}</p>
    </div>
    <ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground/60 transition-colors group-hover:text-foreground" />
  </button>
);

export default SettingsNavCard;
