// SVG-only "light" build: no direct eval, no web worker, no extra renderers.
// Renders plain Lottie JSON (e.g. /hero-animation.json) — replaces the much
// heavier @dotlottie/player-component custom element.
import lottie from "lottie-web/build/player/lottie_light";
import type { CSSProperties } from "react";
import { useEffect, useRef } from "react";

interface LottiePlayerProps {
  /** Path or URL to a Lottie JSON file. */
  src: string;
  loop?: boolean;
  autoplay?: boolean;
  /** Playback speed multiplier (1 = normal). */
  speed?: number;
  className?: string;
  style?: CSSProperties;
}

export const LottiePlayer = ({
  src,
  loop = false,
  autoplay = true,
  speed = 1,
  className,
  style,
}: LottiePlayerProps) => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const animation = lottie.loadAnimation({
      container,
      renderer: "svg",
      loop,
      autoplay,
      path: src,
    });
    animation.setSpeed(speed);

    return () => animation.destroy();
  }, [src, loop, autoplay, speed]);

  return <div ref={containerRef} className={className} style={style} />;
};
