import { Loader2, Pin } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { ContextNoteApi } from "@/features/context-layer/api";
import type { CreateContextNoteRequest } from "@/features/context-layer/types";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import type { WizardControls } from "@/shared/components/wizard/useWizardState";
import { WizardStep } from "@/shared/components/wizard/WizardStep";

interface PreferencesStepProps {
  controls: WizardControls;
}

interface PreferencesState {
  dateFormat: "ISO" | "EU" | "US";
  locale: "en-GB" | "en-US" | "de-DE" | "es-ES" | "fr-FR" | "it-IT" | "pt-BR";
  responseStyle: "terse" | "balanced" | "verbose";
}

const DEFAULTS: PreferencesState = {
  dateFormat: "ISO",
  locale: "en-GB",
  responseStyle: "balanced",
};

const DATE_FORMAT_LABELS: Record<PreferencesState["dateFormat"], string> = {
  ISO: "ISO-8601 (2026-05-13)",
  EU: "DD/MM/YYYY (13/05/2026)",
  US: "MM/DD/YYYY (05/13/2026)",
};

const RESPONSE_STYLE_LABELS: Record<PreferencesState["responseStyle"], string> = {
  terse: "Terse — short replies, no summaries",
  balanced: "Balanced — default",
  verbose: "Verbose — full context every turn",
};

function notesFromPreferences(prefs: PreferencesState): CreateContextNoteRequest[] {
  return [
    {
      scope: "global",
      kind: "preference",
      text: `Date format: ${DATE_FORMAT_LABELS[prefs.dateFormat]}.`,
    },
    {
      scope: "global",
      kind: "preference",
      text: `Locale: ${prefs.locale}.`,
    },
    {
      scope: "global",
      kind: "preference",
      text: `Response style: ${RESPONSE_STYLE_LABELS[prefs.responseStyle]}.`,
    },
  ];
}

export function PreferencesStep({ controls }: PreferencesStepProps) {
  const [prefs, setPrefs] = useState<PreferencesState>(DEFAULTS);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleDateFormatChange = (value: string) =>
    setPrefs((prev) => ({ ...prev, dateFormat: value as PreferencesState["dateFormat"] }));
  const handleLocaleChange = (value: string) =>
    setPrefs((prev) => ({ ...prev, locale: value as PreferencesState["locale"] }));
  const handleResponseStyleChange = (value: string) =>
    setPrefs((prev) => ({ ...prev, responseStyle: value as PreferencesState["responseStyle"] }));

  const handleSaveAll = async () => {
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      const requests = notesFromPreferences(prefs);
      await Promise.all(requests.map((r) => ContextNoteApi.create(r)));
      toast.success(`Saved ${requests.length} preferences to your Context Layer`);
      controls.goNext();
    } catch (err) {
      const message = err instanceof Error ? err.message : "Unknown error";
      toast.error(`Could not save preferences: ${message}`);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <WizardStep
      controls={controls}
      title="Set your preferences"
      description="These three notes are saved at the global scope and retrieved whenever they're relevant to what you're asking. Change them anytime on the Context page."
      primaryAction={{
        label: isSubmitting ? "Saving…" : "Save all and continue",
        onClick: handleSaveAll,
        disabled: isSubmitting,
      }}
    >
      <div className="grid gap-4 sm:max-w-md">
        <div className="space-y-1.5">
          <Label htmlFor="pref-date-format">Date format</Label>
          <Select value={prefs.dateFormat} onValueChange={handleDateFormatChange}>
            <SelectTrigger id="pref-date-format">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {(Object.keys(DATE_FORMAT_LABELS) as PreferencesState["dateFormat"][]).map((k) => (
                <SelectItem key={k} value={k}>
                  {DATE_FORMAT_LABELS[k]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-1.5">
          <Label htmlFor="pref-locale">Locale</Label>
          <Select value={prefs.locale} onValueChange={handleLocaleChange}>
            <SelectTrigger id="pref-locale">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="en-GB">English (UK)</SelectItem>
              <SelectItem value="en-US">English (US)</SelectItem>
              <SelectItem value="de-DE">German</SelectItem>
              <SelectItem value="es-ES">Spanish</SelectItem>
              <SelectItem value="fr-FR">French</SelectItem>
              <SelectItem value="it-IT">Italian</SelectItem>
              <SelectItem value="pt-BR">Portuguese (BR)</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-1.5">
          <Label htmlFor="pref-response-style">Response style</Label>
          <Select value={prefs.responseStyle} onValueChange={handleResponseStyleChange}>
            <SelectTrigger id="pref-response-style">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {(Object.keys(RESPONSE_STYLE_LABELS) as PreferencesState["responseStyle"][]).map(
                (k) => (
                  <SelectItem key={k} value={k}>
                    {RESPONSE_STYLE_LABELS[k]}
                  </SelectItem>
                ),
              )}
            </SelectContent>
          </Select>
        </div>

        <div className="flex items-start gap-2 rounded-md border border-border bg-card/60 p-3 text-xs text-muted-foreground">
          <Pin className="mt-0.5 h-3.5 w-3.5 text-primary" />
          <p>
            Pinned notes are always retrieved, no matter what you're asking about. Use them
            sparingly for things you genuinely want applied to every turn.
          </p>
        </div>

        {isSubmitting && (
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
            Saving…
          </div>
        )}
      </div>
    </WizardStep>
  );
}
