import { Eye, Pencil } from "lucide-react";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { type AssistantMode, useAuthorizationsStore } from "../store/authorizationsStore";

/**
 * Compact agent/ask (read-only) mode switcher, sat next to the model picker.
 * In "ask" mode the assistant can read and answer but cannot change anything —
 * enforced server-side, this control just sets the persisted preference.
 */
export function ChatModeSelect() {
  const mode = useAuthorizationsStore((s) => s.mode);
  const setMode = useAuthorizationsStore((s) => s.setMode);

  const handleChange = (value: string) => {
    const next: AssistantMode = value === "ask" ? "ask" : "agent";
    setMode(next);
  };

  return (
    <Select value={mode} onValueChange={handleChange}>
      <SelectTrigger
        className="h-6 w-auto flex-shrink-0 gap-1 border-none bg-muted px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground focus:ring-0 focus:ring-offset-0"
        title="Mode — Agent can make changes (with your authorization); Ask is read-only"
        aria-label="Select assistant mode"
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value="agent" className="text-xs">
          <span className="flex items-center gap-1.5">
            <Pencil className="h-3 w-3" />
            Agent
          </span>
        </SelectItem>
        <SelectItem value="ask" className="text-xs">
          <span className="flex items-center gap-1.5">
            <Eye className="h-3 w-3" />
            Ask
          </span>
        </SelectItem>
      </SelectContent>
    </Select>
  );
}
