import { Checkbox } from "@/shared/components/ui/checkbox";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Input } from "@/shared/components/ui/input";
import { RadioGroup, RadioGroupItem } from "@/shared/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Textarea } from "@/shared/components/ui/textarea";
import { rowsToOptions, type SelectOption, useConceptRows } from "../../runtime/useConceptRows";
import type { FormFieldDef } from "../../schema/appDefinition.types";

interface ScalarFieldControlProps {
  field: Pick<
    FormFieldDef,
    "id" | "type" | "options" | "optionsSource" | "placeholder" | "min" | "max" | "label"
  >;
  value: unknown;
  onChange: (value: unknown) => void;
  ontologyId: string;
}

/**
 * Renders one scalar input control by declared type. Controlled component:
 * used both by the form engine (via RHF Controller) and by standalone
 * `input_ref` widgets bound straight to the tab context.
 */
export function ScalarFieldControl({
  field,
  value,
  onChange,
  ontologyId,
}: ScalarFieldControlProps) {
  const { data: optionRows, isLoading: optionsLoading } = useConceptRows(
    field.optionsSource ? ontologyId : undefined,
    field.optionsSource?.concept,
  );

  const options: SelectOption[] = field.optionsSource
    ? rowsToOptions(optionRows, field.optionsSource.valueCol, field.optionsSource.labelCol)
    : (field.options ?? []).map((option) => ({ value: option, label: option }));

  if (field.type === "select" || field.type === "combobox") {
    if (optionsLoading) {
      return (
        <div className="h-9 flex items-center gap-2 rounded-md border border-input bg-background px-3 text-sm text-muted-foreground">
          <PrometheuxSpinner size={13} />
          Loading options…
        </div>
      );
    }
    return (
      <Select value={value ? String(value) : ""} onValueChange={onChange}>
        <SelectTrigger className="h-9 text-sm">
          <SelectValue placeholder={field.placeholder ?? `Select ${field.label ?? field.id}`} />
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  }

  if (field.type === "radio") {
    if (optionsLoading) {
      return (
        <div className="flex items-center gap-2 py-2 text-xs text-muted-foreground">
          <PrometheuxSpinner size={13} />
          Loading options…
        </div>
      );
    }
    return (
      <RadioGroup
        value={value ? String(value) : ""}
        onValueChange={onChange}
        className="flex flex-wrap gap-3 py-1"
      >
        {options.map((option) => {
          const radioId = `${field.id}-${option.value}`;
          return (
            <span key={option.value} className="flex items-center gap-1.5 text-xs text-foreground">
              <RadioGroupItem id={radioId} value={option.value} />
              <label htmlFor={radioId}>{option.label}</label>
            </span>
          );
        })}
      </RadioGroup>
    );
  }

  if (field.type === "multi_select") {
    if (optionsLoading) {
      return (
        <div className="flex items-center gap-2 py-2 text-xs text-muted-foreground">
          <PrometheuxSpinner size={13} />
          Loading options…
        </div>
      );
    }
    const selected = Array.isArray(value) ? (value as string[]) : [];
    const toggle = (optionValue: string, checked: boolean) => {
      if (checked) {
        onChange([...selected, optionValue]);
        return;
      }
      onChange(selected.filter((entry) => entry !== optionValue));
    };
    return (
      <div className="flex flex-wrap gap-3 py-1">
        {options.map((option) => {
          const checkboxId = `${field.id}-${option.value}`;
          return (
            <span key={option.value} className="flex items-center gap-1.5 text-xs text-foreground">
              <Checkbox
                id={checkboxId}
                checked={selected.includes(option.value)}
                onCheckedChange={(checked) => toggle(option.value, checked === true)}
              />
              <label htmlFor={checkboxId}>{option.label}</label>
            </span>
          );
        })}
      </div>
    );
  }

  if (field.type === "checkbox") {
    return (
      <div className="h-9 flex items-center">
        <Checkbox
          id={`check-${field.id}`}
          checked={value === true}
          onCheckedChange={(checked) => onChange(checked === true)}
        />
        {field.placeholder && (
          <label htmlFor={`check-${field.id}`} className="ml-2 text-xs text-foreground">
            {field.placeholder}
          </label>
        )}
      </div>
    );
  }

  if (field.type === "textarea") {
    return (
      <Textarea
        className="text-sm min-h-[72px]"
        value={value === undefined || value === null ? "" : String(value)}
        placeholder={field.placeholder}
        onChange={(event) => onChange(event.target.value)}
      />
    );
  }

  if (field.type === "password") {
    return (
      <Input
        type="password"
        className="h-9 text-sm"
        value={value === undefined || value === null ? "" : String(value)}
        placeholder={field.placeholder}
        onChange={(event) => onChange(event.target.value)}
      />
    );
  }

  if (field.type === "number") {
    return (
      <Input
        type="number"
        className="h-9 text-sm"
        value={value === undefined || value === null ? "" : String(value)}
        min={field.min}
        max={field.max}
        placeholder={field.placeholder}
        onChange={(event) => onChange(event.target.value)}
      />
    );
  }

  return (
    <Input
      type={field.type === "date" ? "date" : "text"}
      className="h-9 text-sm"
      value={value === undefined || value === null ? "" : String(value)}
      placeholder={field.placeholder}
      onChange={(event) => onChange(event.target.value)}
    />
  );
}
