import { ChevronRight, Loader2 } from "lucide-react";

import { useDemoSources } from "@/features/data-sources/hooks/useDemoSources";
import type { DemoSourcePreset } from "@/features/data-sources/types";
import DatabaseIcon from "@/shared/components/icons/DatabaseIcon";
import { cn } from "@/shared/lib/utils";

interface DemoDataPickerProps {
  onPickPreset: (preset: DemoSourcePreset) => void;
  className?: string;
}

// The only file-based px preset is S3, so render the recognizable storage icon
// for the "files" category rather than the underlying file type (csv).
const CATEGORY_ICON_FALLBACK: Record<string, string> = {
  files: "s3",
};

const resolveIconType = (preset: DemoSourcePreset): string =>
  CATEGORY_ICON_FALLBACK[preset.category] ?? preset.databaseType ?? "";

interface DemoSourceRowProps {
  preset: DemoSourcePreset;
  onPick: (preset: DemoSourcePreset) => void;
}

function DemoSourceRow({ preset, onPick }: DemoSourceRowProps) {
  const handleClick = () => onPick(preset);

  return (
    <button
      type="button"
      onClick={handleClick}
      className="flex w-full items-center gap-3 rounded-md border border-border bg-card p-3 text-left transition-colors hover:border-primary/40 hover:bg-muted/40"
    >
      <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-muted/60 ring-1 ring-border/50">
        <DatabaseIcon type={resolveIconType(preset)} className="h-4 w-4" />
      </div>
      <span className="min-w-0 flex-1">
        <span className="block text-sm font-medium text-foreground">{preset.label}</span>
        <span className="block truncate text-xs text-muted-foreground">{preset.description}</span>
      </span>
      <ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground" />
    </button>
  );
}

export function DemoDataPicker({ onPickPreset, className }: DemoDataPickerProps) {
  const { presets, isLoadingPresets, presetsError } = useDemoSources();

  if (isLoadingPresets) {
    return (
      <div className={cn("flex items-center gap-2 text-sm text-muted-foreground", className)}>
        <Loader2 className="h-4 w-4 animate-spin" />
        <span>Loading px-datasources…</span>
      </div>
    );
  }

  if (presetsError) {
    return (
      <div className={cn("text-sm text-destructive", className)}>
        Could not load px-datasources.
      </div>
    );
  }

  if (presets.length === 0) return null;

  return (
    <ul className={cn("space-y-2", className)}>
      {presets.map((preset) => (
        <li key={preset.id}>
          <DemoSourceRow preset={preset} onPick={onPickPreset} />
        </li>
      ))}
    </ul>
  );
}

export default DemoDataPicker;
