import { useQuery } from "@tanstack/react-query";

import { useDebouncedValue } from "@/shared/hooks/ui/useDebouncedValue";

import { ContextNoteApi } from "../../api";
import type { ContextNote, ContextNoteFilter } from "../../types";

const SEARCH_DEBOUNCE_MS = 300;

export interface UseNotesSearchReturn {
  /** Exact-word matches via the Postgres full-text index. */
  exactMatches: ContextNote[];
  /** Conceptually related notes via embedding search. */
  relatedMatches: ContextNote[];
  isLoading: boolean;
}

/**
 * The search pane runs both search modes side by side — full-text for
 * exact recall, semantic for "find notes related to…" (the differentiator
 * Obsidian doesn't have). Results are deduplicated in favor of exact.
 */
export function useNotesSearch(query: string, filter: ContextNoteFilter): UseNotesSearchReturn {
  const debouncedQuery = useDebouncedValue(query.trim(), SEARCH_DEBOUNCE_MS);
  const enabled = debouncedQuery.length > 0;
  const scopeKey = [filter.scope, filter.scopeId ?? "global", debouncedQuery] as const;

  const ftsQuery = useQuery({
    queryKey: ["context-notes-fts", ...scopeKey],
    queryFn: () => ContextNoteApi.searchFulltext(debouncedQuery, filter),
    enabled,
  });

  const semanticQuery = useQuery({
    queryKey: ["context-notes-semantic", ...scopeKey],
    queryFn: () => ContextNoteApi.search(debouncedQuery, { ...filter }),
    enabled,
  });

  const exactMatches = ftsQuery.data ?? [];
  const exactIds = new Set(exactMatches.map((note) => note.id));
  const relatedMatches = (semanticQuery.data ?? []).filter((note) => !exactIds.has(note.id));

  return {
    exactMatches,
    relatedMatches,
    isLoading: enabled && (ftsQuery.isLoading || semanticQuery.isLoading),
  };
}
