import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { approveJoinRequest, listTeamJoinRequests, rejectJoinRequest } from "../api";
import type { Membership, TeamError, TeamJoinRequest } from "../types";
import { MY_JOIN_REQUESTS_KEY } from "./useMyJoinRequests";
import { TEAM_MEMBERS_KEY } from "./useTeamMembers";

// Admin-side pending join requests for a single team + approve/reject
// mutations. Shared prefix so cross-hook invalidations from useMyJoinRequests
// (request/cancel from the requester side) can target it without knowing the
// specific teamId — RQ matches on prefix.
export const TEAM_JOIN_REQUESTS_KEY = ["teams", "team-join-requests"] as const;
const teamJoinRequestsKey = (teamId: string, userId: string) =>
  [...TEAM_JOIN_REQUESTS_KEY, teamId, userId] as const;

interface UseTeamJoinRequestsOptions {
  enabled?: boolean;
}

interface UseTeamJoinRequestsReturn {
  requests: TeamJoinRequest[];
  isLoading: boolean;
  isFetching: boolean;
  error: TeamError | null;
  refresh: () => Promise<unknown>;

  approve: (requestId: string) => Promise<{
    team_id: string;
    request_id: string;
    membership: Membership;
  }>;
  isApproving: boolean;
  approvingRequestId: string | null;

  reject: (requestId: string) => Promise<{
    team_id: string;
    request_id: string;
    status: "rejected";
  }>;
  isRejecting: boolean;
  rejectingRequestId: string | null;
}

// Owner/admin only. Non-admin callers get an empty list from the backend, but
// TeamRosterPanel gates this behind capabilities.canManageMembers to avoid
// mounting the hook / rendering an empty section for regular members.
export function useTeamJoinRequests(
  teamId: string | null | undefined,
  { enabled = true }: UseTeamJoinRequestsOptions = {},
): UseTeamJoinRequestsReturn {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";
  const safeTeamId = teamId ?? "";

  const query = useQuery<TeamJoinRequest[], TeamError>({
    queryKey: teamJoinRequestsKey(safeTeamId, userId),
    queryFn: () => listTeamJoinRequests(safeTeamId, supabaseToken),
    enabled: enabled && Boolean(userId && supabaseToken && safeTeamId),
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const approveMutation = useMutation<
    { team_id: string; request_id: string; membership: Membership },
    TeamError,
    string
  >({
    mutationFn: (requestId) => approveJoinRequest(safeTeamId, requestId, supabaseToken),
    onSuccess: () => {
      // Approve promotes the requester into an active member: the pending
      // request row drops out AND the roster gains a row. Both queries live
      // under prefixes we can target.
      queryClient.invalidateQueries({
        queryKey: [...TEAM_JOIN_REQUESTS_KEY, safeTeamId],
      });
      queryClient.invalidateQueries({ queryKey: [...TEAM_MEMBERS_KEY, safeTeamId] });
      // If the requester happens to be signed in on the same client (dev
      // flows), their own inbox needs to flip pending → approved.
      queryClient.invalidateQueries({ queryKey: MY_JOIN_REQUESTS_KEY });
    },
  });

  const rejectMutation = useMutation<
    { team_id: string; request_id: string; status: "rejected" },
    TeamError,
    string
  >({
    mutationFn: (requestId) => rejectJoinRequest(safeTeamId, requestId, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: [...TEAM_JOIN_REQUESTS_KEY, safeTeamId],
      });
      queryClient.invalidateQueries({ queryKey: MY_JOIN_REQUESTS_KEY });
    },
  });

  return {
    requests: query.data ?? [],
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    refresh: query.refetch,

    approve: approveMutation.mutateAsync,
    isApproving: approveMutation.isPending,
    approvingRequestId: approveMutation.isPending ? (approveMutation.variables ?? null) : null,

    reject: rejectMutation.mutateAsync,
    isRejecting: rejectMutation.isPending,
    rejectingRequestId: rejectMutation.isPending ? (rejectMutation.variables ?? null) : null,
  };
}
