import type { EdgeData, NodeData } from "@antv/g6";
import type { AnalyticsRange } from "./conceptGraph.utils";
import { getGraphAnalytics, isGraphAnalyticsKey } from "./graphAnalytics";
import type { ExplorerEdge, ExplorerNode } from "./types";

export interface CanvasNode extends NodeData {
  id: string;
  _label: string;
  _fill: string;
  _stroke: string;
  /** Node radius override, set when an analytics score overlay is active. */
  _size?: number;
  /** Seed position for a newly-added node, so an incremental draw places it
   * without a relayout. Existing nodes omit this and keep their position. */
  style?: { x: number; y: number };
}

/** Context for rendering a node-scoring analytics overlay on the canvas. */
export interface CanvasAnalytics {
  type: string | null;
  range: AnalyticsRange | null;
}

const ANALYTICS_MIN_SIZE = 18;
const ANALYTICS_MAX_SIZE = 54;

/** Map a node score to a radius within the analytics size band. */
export function scoreToSize(score: number, range: AnalyticsRange): number {
  const span = range.max - range.min;
  if (span <= 0) return (ANALYTICS_MIN_SIZE + ANALYTICS_MAX_SIZE) / 2;
  const ratio = (score - range.min) / span;
  const clamped = Math.min(1, Math.max(0, ratio));
  return ANALYTICS_MIN_SIZE + clamped * (ANALYTICS_MAX_SIZE - ANALYTICS_MIN_SIZE);
}

export interface CanvasEdge extends EdgeData {
  id: string;
  source: string;
  target: string;
  _label: string;
  /** Edge/arrow color: the source node's color darkened, so clusters share a hue. */
  _stroke?: string;
  /** Highlight color when the edge touches the selected node (full node color). */
  _strokeActive?: string;
}

export interface CanvasData {
  nodes: CanvasNode[];
  edges: CanvasEdge[];
}

/**
 * Curated node palette — saturated fills that read on light and dark
 * canvases. Ordered so the concept graphs' common node types ("source" →
 * index 3, "target" → index 5) land on the indigo/amber pair.
 */
const NODE_PALETTE: Array<{ fill: string; stroke: string }> = [
  { fill: "#14B8A6", stroke: "#0D9488" }, // teal
  { fill: "#F26B8A", stroke: "#D44E6E" }, // rose
  { fill: "#3FA0F5", stroke: "#2A7FD0" }, // sky
  { fill: "#6C5CE7", stroke: "#5346C8" }, // indigo
  { fill: "#A855F7", stroke: "#8A3BDB" }, // orchid
  { fill: "#F2A93B", stroke: "#D28A1D" }, // amber
];

/** Stable palette entry per node type so every type gets a distinct, consistent color. */
export function nodeTypeColor(nodeTypeId: string): { fill: string; stroke: string } {
  let hash = 0;
  for (let i = 0; i < nodeTypeId.length; i++) {
    hash = (hash * 31 + nodeTypeId.charCodeAt(i)) >>> 0;
  }
  return NODE_PALETTE[hash % NODE_PALETTE.length];
}

export function truncateLabel(label: string, max = 18): string {
  return label.length > max ? `${label.slice(0, max - 1)}…` : label;
}

/** Darken a #rrggbb color by the given fraction (0.25 = 25% darker). */
export function darkenColor(hex: string, amount = 0.25): string {
  const value = Number.parseInt(hex.slice(1), 16);
  const r = Math.round(((value >> 16) & 0xff) * (1 - amount));
  const g = Math.round(((value >> 8) & 0xff) * (1 - amount));
  const b = Math.round((value & 0xff) * (1 - amount));
  return `#${((r << 16) | (g << 8) | b).toString(16).padStart(6, "0")}`;
}

/** Whether the active analytics overlay groups nodes (e.g. connected components). */
function isNodeGroupAnalytics(type: string | null): boolean {
  return (
    type !== null &&
    isGraphAnalyticsKey(type) &&
    getGraphAnalytics(type).resultType === "node_group"
  );
}

/** One-line legend describing how the active analytics overlay is encoded. */
export function analyticsLegend(analytics: CanvasAnalytics | undefined): string | null {
  const type = analytics?.type ?? null;
  if (type === null || !isGraphAnalyticsKey(type)) return null;
  const def = getGraphAnalytics(type);
  if (def.resultType === "node_group") return `${def.label} · node color`;
  const range = analytics?.range;
  if (!range) return `${def.label} · node size`;
  return `${def.label} · node size (${range.min.toFixed(2)}–${range.max.toFixed(2)})`;
}

/** Resolve a node's canvas color, coloring by component id when grouping. */
function resolveNodeColor(node: ExplorerNode, isGroup: boolean): { fill: string; stroke: string } {
  if (isGroup && node.analytics?.component !== undefined) {
    return nodeTypeColor(`component:${node.analytics.component}`);
  }
  return nodeTypeColor(node.node_type);
}

export function buildCanvasData(
  nodes: Record<string, ExplorerNode>,
  edges: Record<string, ExplorerEdge>,
  analytics?: CanvasAnalytics,
): CanvasData {
  const isGroup = isNodeGroupAnalytics(analytics?.type ?? null);
  const range = analytics?.range ?? null;
  const nodeColors = new Map<string, { fill: string; stroke: string }>();

  return {
    nodes: Object.values(nodes).map((node) => {
      const color = resolveNodeColor(node, isGroup);
      nodeColors.set(node.id, color);
      const score = node.analytics?.score;
      const size = range && typeof score === "number" ? scoreToSize(score, range) : undefined;
      return {
        id: node.id,
        _label: node.label,
        _fill: color.fill,
        _stroke: color.stroke,
        _size: size,
      };
    }),
    edges: Object.values(edges).map((edge) => {
      const sourceFill = nodeColors.get(edge.source)?.fill;
      return {
        id: edge.id,
        source: edge.source,
        target: edge.target,
        _label: edge.label,
        _stroke: sourceFill ? darkenColor(sourceFill) : undefined,
        _strokeActive: sourceFill,
      };
    }),
  };
}
