import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/shared/components/ui/table";

interface GraphResultTableProps {
  columns: string[];
  rows: unknown[][];
}

export function cellText(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}

export function GraphResultTable({ columns, rows }: GraphResultTableProps) {
  return (
    <div className="flex-1 min-h-0 overflow-auto">
      <Table>
        <TableHeader className="sticky top-0 bg-background z-10">
          <TableRow>
            {columns.map((column) => (
              <TableHead key={column} className="text-xs font-medium whitespace-nowrap">
                {column}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row, rowIndex) => (
            // biome-ignore lint/suspicious/noArrayIndexKey: rows are positional page data with no stable id
            <TableRow key={rowIndex}>
              {columns.map((column, columnIndex) => (
                <TableCell
                  key={column}
                  className="text-xs py-1.5 max-w-[320px] truncate"
                  title={cellText(row[columnIndex])}
                >
                  {cellText(row[columnIndex])}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}
