import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { shareOntologyWithTeam } from "../api";
import type { ShareError, ShareTeamInput, TeamShareSummary } from "../types";
import { SHARE_OUTBOX_KEY } from "./useShareOutbox";

interface UseShareTeamReturn {
  shareWithTeam: (input: ShareTeamInput) => Promise<TeamShareSummary>;
  isSharing: boolean;
  error: ShareError | null;
  reset: () => void;
}

// Mutation hook for the sender-side "Share with team" flow. Mirrors
// useShareProject but hits POST /share/team; invalidates the outbox so the
// Manage Shares panel reflects the new team share.
export function useShareTeam(): UseShareTeamReturn {
  const { session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;

  const mutation = useMutation<TeamShareSummary, ShareError, ShareTeamInput>({
    mutationFn: (input) => shareOntologyWithTeam(input, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: SHARE_OUTBOX_KEY });
    },
  });

  return {
    shareWithTeam: mutation.mutateAsync,
    isSharing: mutation.isPending,
    error: mutation.error,
    reset: mutation.reset,
  };
}
