import type React from "react";
import { useCallback, useEffect, useMemo } from "react";
import type { ConceptCell } from "@/features/concept-editor/types";

interface UseTreeKeyboardNavParams {
  /** Group names in display order. Used together with `collapsedGroups` and `groupedCells` to compute the visible list. */
  groupNames: string[];
  groupedCells: Record<string, ConceptCell[]>;
  ungroupedCells: ConceptCell[];
  collapsedGroups: Record<string, boolean>;
  selectedCellId: string | null;
  onSelectCell: (cellId: string) => void;
  /** Container element used to (a) scope the scroll-into-view query and (b) host the onKeyDown handler. */
  containerRef: React.RefObject<HTMLDivElement>;
  onStartRename?: (cellId: string) => void;
  onDeleteCell?: (cellId: string) => void | Promise<void>;
}

interface UseTreeKeyboardNavReturn {
  handleKeyDown: (event: React.KeyboardEvent<HTMLDivElement>) => void;
}

/**
 * Keyboard navigation for the Explorer tree:
 *   - ArrowUp / ArrowDown — move selection through visible cells
 *   - Home / End — jump to first / last visible cell
 *   - F2 — start inline rename on the selected cell
 *   - Delete — delete the selected cell
 *
 * Folder headers aren't traversable by arrow keys; cells inside a collapsed
 * group are skipped (the caller provides the already-filtered list).
 *
 * Also scrolls the selected row into view when selection changes — looks up
 * the row via `[data-tree-cell-id="..."]` inside the container ref.
 */
export function useTreeKeyboardNav(params: UseTreeKeyboardNavParams): UseTreeKeyboardNavReturn {
  const {
    groupNames,
    groupedCells,
    ungroupedCells,
    collapsedGroups,
    selectedCellId,
    onSelectCell,
    containerRef,
    onStartRename,
    onDeleteCell,
  } = params;

  const visibleCells = useMemo(() => {
    const list: ConceptCell[] = [];
    for (const groupName of groupNames) {
      const isExpanded = !(collapsedGroups[groupName] ?? true);
      if (isExpanded) list.push(...(groupedCells[groupName] || []));
    }
    list.push(...ungroupedCells);
    return list;
  }, [groupNames, groupedCells, ungroupedCells, collapsedGroups]);

  useEffect(() => {
    if (!selectedCellId || !containerRef.current) return;
    const el = containerRef.current.querySelector<HTMLElement>(
      `[data-tree-cell-id="${CSS.escape(selectedCellId)}"]`,
    );
    el?.scrollIntoView({ block: "nearest" });
  }, [selectedCellId, containerRef]);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      // Don't intercept keys typed into the search input or the inline-rename
      // input. Both are inside the tree, so their events bubble up here.
      const target = event.target as HTMLElement;
      if (target.tagName === "INPUT" || target.tagName === "TEXTAREA") return;
      if (visibleCells.length === 0) return;

      const currentIdx = selectedCellId
        ? visibleCells.findIndex((c) => c.id === selectedCellId)
        : -1;

      if (event.key === "ArrowDown") {
        event.preventDefault();
        const nextIdx = currentIdx < 0 ? 0 : Math.min(currentIdx + 1, visibleCells.length - 1);
        onSelectCell(visibleCells[nextIdx].id);
        return;
      }
      if (event.key === "ArrowUp") {
        event.preventDefault();
        const nextIdx = currentIdx < 0 ? visibleCells.length - 1 : Math.max(currentIdx - 1, 0);
        onSelectCell(visibleCells[nextIdx].id);
        return;
      }
      if (event.key === "Home") {
        event.preventDefault();
        onSelectCell(visibleCells[0].id);
        return;
      }
      if (event.key === "End") {
        event.preventDefault();
        onSelectCell(visibleCells[visibleCells.length - 1].id);
        return;
      }
      if (event.key === "F2") {
        event.preventDefault();
        if (selectedCellId && onStartRename) onStartRename(selectedCellId);
        return;
      }
      if (event.key === "Delete") {
        event.preventDefault();
        if (selectedCellId && onDeleteCell) void onDeleteCell(selectedCellId);
      }
    },
    [visibleCells, selectedCellId, onSelectCell, onStartRename, onDeleteCell],
  );

  return { handleKeyDown };
}
