import { useQuery } from "@tanstack/react-query";

import { useDebouncedValue } from "@/shared/hooks/ui/useDebouncedValue";
import { ConfigService } from "../api/configService";
import { configFingerprint } from "../utils/llmConnection.utils";

const MODELS_STALE_MS = 5 * 60 * 1000;
/** Long enough that discovery is not attempted against a half-typed key. */
const CREDENTIAL_SETTLE_MS = 400;

export interface LlmModelSource {
  /** Provider to list for; a null one leaves the query idle. */
  provider: string | null;
  /**
   * Saved connection to list through. Its credentials stay on the pod, so the
   * server resolves the name and discovers on our behalf.
   */
  connection?: string;
  /**
   * Credentials being typed. They overlay the connection's stored ones, so a
   * form lists what it is about to save rather than what is saved now.
   */
  credentials?: Record<string, string>;
}

/**
 * The model names a provider offers to a given set of credentials.
 *
 * Which models exist is an account-level fact, not a provider-level one: an
 * OpenAI org sees the models it is entitled to, and an Azure resource sees the
 * deployments someone named. So the listing request carries whatever identifies
 * the account — a saved connection's name, credentials mid-edit, or neither,
 * which lists the managed pool.
 *
 * Empty means discovery had nothing to say (unreachable, or no credentials yet);
 * callers should stay usable in that case rather than block on the list.
 */
export function useLlmModels({ provider, connection, credentials }: LlmModelSource) {
  const extra: Record<string, string> = {
    ...(connection ? { connection } : {}),
    ...(credentials ?? {}),
  };
  // The fingerprint is what gets debounced, and it is a string: debouncing the
  // object itself would restart the timer on every render, since it is rebuilt
  // each time. A digest also keeps the credential out of the cache key while
  // still changing when the credential does, which is what refetches the list.
  const settled = useDebouncedValue(configFingerprint(JSON.stringify(extra)), CREDENTIAL_SETTLE_MS);

  return useQuery({
    queryKey: ["llm-models", provider ?? "", settled],
    queryFn: async () => {
      const result = await ConfigService.listModels(provider ?? "", extra);
      return result.models;
    },
    enabled: Boolean(provider),
    staleTime: MODELS_STALE_MS,
  });
}
