import { MoreHorizontal } from "lucide-react";
import { type ReactNode, useState } from "react";
import ComputeIndicator from "@/features/compute/components/ComputeIndicator";
import { Button } from "@/shared/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";
import { type OntologyTab, OntologyTabNav } from "./projectTabs";

interface OntologyHeaderOverflowProps {
  activeTab: string;
  onTabChange: (tab: OntologyTab) => void;
  /** Render the machine dropdown inside the menu (omitted on views that have no compute). */
  showCompute?: boolean;
  /** Tab-specific items (e.g. lineage Run / New Concept / Search). `close` collapses the menu. */
  renderItems?: (close: () => void) => ReactNode;
}

const Divider = () => <span className="h-px w-full bg-border" />;

export function OntologyHeaderOverflow({
  activeTab,
  onTabChange,
  showCompute = false,
  renderItems,
}: OntologyHeaderOverflowProps) {
  const [open, setOpen] = useState(false);

  const close = () => setOpen(false);

  const handleTabChange = (tab: OntologyTab) => {
    onTabChange(tab);
    close();
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="outline" size="iconSm" title="More" aria-label="More">
          <MoreHorizontal className="h-4 w-4" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-64 p-2">
        <div className="flex flex-col gap-2">
          <OntologyTabNav activeTab={activeTab} onTabChange={handleTabChange} variant="menu" />
          {showCompute && (
            <>
              <Divider />
              <ComputeIndicator interactive={true} />
            </>
          )}
          {renderItems && (
            <>
              <Divider />
              {renderItems(close)}
            </>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}
