import { useState } from "react";
import { toast } from "sonner";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { DashboardClient } from "../../api/DashboardClient";

const client = new DashboardClient();

export interface DeleteAppTarget {
  ontologyId: string;
  id: string;
  name: string;
}

interface DeleteAppDialogProps {
  /** The app to delete; null keeps the dialog closed. */
  target: DeleteAppTarget | null;
  onOpenChange: (open: boolean) => void;
  onDeleted: () => void;
}

/** Confirm-and-delete for a dynamic app — same alert pattern as project deletion. */
export function DeleteAppDialog({ target, onOpenChange, onDeleted }: DeleteAppDialogProps) {
  const [isDeleting, setIsDeleting] = useState(false);

  const handleDelete = async () => {
    if (!target) return;
    try {
      setIsDeleting(true);
      await client.deleteDashboard(target.ontologyId, target.id);
      onDeleted();
      toast.success(`App "${target.name}" deleted`);
    } catch (error) {
      console.error("Error deleting app:", error);
      toast.error(`Failed to delete app "${target.name}"`);
    } finally {
      setIsDeleting(false);
      onOpenChange(false);
    }
  };

  return (
    <AlertDialog open={!!target} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Delete the app</AlertDialogTitle>
          <AlertDialogDescription>
            Are you sure you want to delete “{target?.name}”? Its definition and version history
            will be removed. It cannot be undone.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
          <AlertDialogAction
            onClick={(e) => {
              e.preventDefault();
              handleDelete();
            }}
            disabled={isDeleting}
            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
          >
            {isDeleting ? (
              <>
                <PrometheuxSpinner size={16} className="mr-2" />
                Deleting...
              </>
            ) : (
              "Delete"
            )}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}
