import { zodResolver } from "@hookform/resolvers/zod";
import { Loader2, X } from "lucide-react";
import type React from "react";
import { useEffect } from "react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import { z } from "zod";
import { useMyTeams } from "@/features/teams/hooks/useMyTeams";
import type { Team, TeamError } from "@/features/teams/types";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";

interface CreateTeamDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onCreated?: (team: Team) => void;
  // Optional pre-fills, used by the onboarding suggestion banner. The user can
  // still edit them before submitting.
  prefillName?: string;
  prefillLinkedDomain?: string;
}

// The backend accepts optional slug + linked_domain. Slug is auto-generated
// from name if omitted; we allow the user to override it. Validation is
// permissive on the FE (backend is authoritative for uniqueness / format).
const formSchema = z.object({
  name: z.string().min(1, "Team name is required").max(120, "Name is too long"),
  slug: z
    .string()
    .max(80, "Slug is too long")
    .regex(/^[a-z0-9-]*$/i, "Slug can only contain letters, numbers and dashes")
    .optional(),
  linked_domain: z
    .string()
    .max(180, "Domain is too long")
    .regex(/^([a-z0-9-]+\.)+[a-z]{2,}$/i, "Enter a valid domain like acme.com")
    .or(z.literal(""))
    .optional(),
});

type CreateTeamFormData = z.infer<typeof formSchema>;

const DEFAULT_VALUES: CreateTeamFormData = { name: "", slug: "", linked_domain: "" };

const CreateTeamDialog: React.FC<CreateTeamDialogProps> = ({
  isOpen,
  onClose,
  onCreated,
  prefillName,
  prefillLinkedDomain,
}) => {
  const { create, isCreating } = useMyTeams();

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<CreateTeamFormData>({
    resolver: zodResolver(formSchema),
    defaultValues: DEFAULT_VALUES,
  });

  // Reset the form each time the dialog opens. If the caller passed prefills
  // (onboarding banner), seed them; otherwise start blank.
  useEffect(() => {
    if (!isOpen) return;
    reset({
      name: prefillName ?? "",
      slug: "",
      linked_domain: prefillLinkedDomain ?? "",
    });
  }, [isOpen, reset, prefillName, prefillLinkedDomain]);

  const handleOpenChange = (open: boolean): void => {
    if (!open) onClose();
  };

  const onSubmit = handleSubmit(async (values) => {
    // Empty strings for optional fields are omitted so the backend's slug
    // auto-generation kicks in and linked_domain stays null.
    const payload = {
      name: values.name.trim(),
      slug: values.slug?.trim() || undefined,
      linked_domain: values.linked_domain?.trim() || undefined,
    };
    try {
      const team = await create(payload);
      toast.success(`Team "${team.name}" created`);
      onCreated?.(team);
      onClose();
    } catch (err) {
      // 409 = caller already owns a team (max 1 per user).
      const teamErr = err as TeamError;
      if (teamErr.httpStatus === 409) {
        toast.error(teamErr.message || "You already own a team", {
          description: "Only one team per user can be created. Try transferring ownership instead.",
        });
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to create team";
      toast.error(message);
    }
  });

  const pending = isCreating || isSubmitting;

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent className="p-0 sm:max-w-[520px] overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Create team</DialogTitle>

        <div
          style={{ background: "#FFDF4B", padding: "12px 20px" }}
          className="flex items-center justify-between border-b border-border"
        >
          <div className="min-w-0">
            <h2 className="text-base font-bold text-[#212020]">Create team</h2>
            <p className="text-xs text-[#212020]/80">
              A team is a governance / collaboration group. Different from your organization.
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="flex h-6 w-6 items-center justify-center rounded-full transition-colors hover:bg-black/10"
            aria-label="Close"
          >
            <X className="h-4 w-4 text-[#212020]" />
          </button>
        </div>

        <form onSubmit={onSubmit} className="space-y-4 bg-card p-6">
          <div className="space-y-1.5">
            <Label htmlFor="team-name">Name</Label>
            <Input
              id="team-name"
              placeholder="Acme"
              autoFocus
              disabled={pending}
              {...register("name")}
            />
            {errors.name && <p className="text-xs text-destructive">{errors.name.message}</p>}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="team-slug">
              Slug <span className="text-xs text-muted-foreground">(optional)</span>
            </Label>
            <Input id="team-slug" placeholder="acme" disabled={pending} {...register("slug")} />
            <p className="text-xs text-muted-foreground">
              Auto-generated from the name if left blank. Letters, numbers and dashes only.
            </p>
            {errors.slug && <p className="text-xs text-destructive">{errors.slug.message}</p>}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="team-domain">
              Linked domain <span className="text-xs text-muted-foreground">(optional)</span>
            </Label>
            <Input
              id="team-domain"
              placeholder="acme.com"
              disabled={pending}
              {...register("linked_domain")}
            />
            <p className="text-xs text-muted-foreground">
              Used to suggest joining this team to users signing in with matching emails.
            </p>
            {errors.linked_domain && (
              <p className="text-xs text-destructive">{errors.linked_domain.message}</p>
            )}
          </div>

          <div className="flex items-center justify-end gap-2 pt-2">
            <Button type="button" variant="ghost" onClick={onClose} disabled={pending}>
              Cancel
            </Button>
            <Button type="submit" disabled={pending} className="gap-1.5">
              {pending && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
              Create team
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default CreateTeamDialog;
