import { ChevronDown, ChevronUp, RefreshCw, Search, Trash2 } from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import SchemaInferenceForm from "@/features/concept-editor/components/code-editor/editor/SchemaInferenceForm";
import DataSourceListItem from "@/features/data-sources/components/DataSourceListItem";
import { DemoDataSuggestion } from "@/features/data-sources/components/DemoDataSuggestion";
import FailedDatasourcesDialog from "@/features/data-sources/components/FailedDatasourcesDialog";
import { buildDemoPrefill, type DemoPrefill } from "@/features/data-sources/demoPrefill";
import { useDataSources } from "@/features/data-sources/hooks/useDataSources";
import type { DataSource, DemoSourcePreset } from "@/features/data-sources/types";
import {
  getGroupIconType,
  getStorageIconType,
  groupDataSourcesByLocationAndType,
} from "@/features/data-sources/utils";
import { useAuthToken } from "@/shared/auth/useAuthToken";
import DatabaseIcon from "@/shared/components/icons/DatabaseIcon";
import { Button } from "@/shared/components/ui/button";
import { Checkbox } from "@/shared/components/ui/checkbox";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { cn } from "@/shared/lib/utils";
import { DeleteAllSourcesDialog } from "./DeleteAllSourcesDialog";

export interface DataTabActions {
  refresh: () => void;
  addDataSource: () => void;
}

interface DataTabProps {
  onToggleSidebar?: () => void;
  sidebarVisible?: boolean;
  onSchemaInference?: (vadalogProgram: string) => void;
  actionsRef?: React.MutableRefObject<DataTabActions | null>;
  onCountChange?: (count: number) => void;
}

interface SchemaFormState {
  open: boolean;
  prefill: DemoPrefill | null;
}

const CLOSED_SCHEMA_FORM: SchemaFormState = { open: false, prefill: null };

const DataTab: React.FC<DataTabProps> = ({ onSchemaInference, actionsRef, onCountChange }) => {
  const [schemaForm, setSchemaForm] = useState<SchemaFormState>(CLOSED_SCHEMA_FORM);
  const [showDeleteAllDialog, setShowDeleteAllDialog] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [connectionInProgress, setConnectionInProgress] = useState(false);
  const [selectedDataSources, setSelectedDataSources] = useState<string[]>([]);
  const [connectingDataSource, setConnectingDataSource] = useState<{
    type: string;
    name: string;
  } | null>(null);
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
  const initialLoadComplete = useRef(false);
  const authToken = useAuthToken();
  const canEditDatasources = usePermissionsStore((state) => state.canEdit("can_edit_datasources"));

  const {
    dataSources,
    isLoading,
    isConnectingSource,
    isDeletingSource,
    isDeletingAllSources,
    refreshingGroupKey,
    failedDatasources,
    clearFailedDatasources,
    loadDataSources,
    refreshDataSources,
    refreshDataSourceGroup,
    deleteDataSources,
    deleteAllDataSources,
    connectDataSource,
    previewDataSource,
    previewDataSourcePaginated,
  } = useDataSources();

  const groupedByLocation = groupDataSourcesByLocationAndType(dataSources);

  const handleAddDataset = useCallback(() => setSchemaForm({ open: true, prefill: null }), []);

  const handlePickDemoPreset = useCallback((preset: DemoSourcePreset) => {
    setSchemaForm({ open: true, prefill: buildDemoPrefill(preset.database) });
  }, []);

  const closeSchemaForm = useCallback(() => setSchemaForm(CLOSED_SCHEMA_FORM), []);

  // Wire up imperative actions for the page header buttons

  useEffect(() => {
    if (actionsRef) {
      actionsRef.current = {
        refresh: () => refreshDataSources(),
        addDataSource: handleAddDataset,
      };
    }
  }, [actionsRef, refreshDataSources, handleAddDataset]);

  // Report count to page header subtitle
  useEffect(() => {
    onCountChange?.(dataSources.length);
  }, [dataSources.length, onCountChange]);

  // Initial load. Without a token there is nothing to load with, and marking
  // the load done would mean never trying again — this effect re-runs when the
  // token lands, because loadDataSources changes with it.
  useEffect(() => {
    if (!authToken) return;
    if (
      !initialLoadComplete.current &&
      !isLoading &&
      !isConnectingSource &&
      !connectionInProgress
    ) {
      initialLoadComplete.current = true;
      loadDataSources();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authToken, connectionInProgress, isConnectingSource, isLoading, loadDataSources]);

  // Remove stale selections when data sources are deleted
  useEffect(() => {
    if (selectedDataSources.length === 0) return;
    const existing = dataSources.map((ds) => ds.id).filter(Boolean) as string[];
    const valid = selectedDataSources.filter((id) => existing.includes(id));
    if (valid.length !== selectedDataSources.length) setSelectedDataSources(valid);
  }, [dataSources, selectedDataSources]);

  const handleDataSourceSelection = (id: string, isSelected: boolean) => {
    setSelectedDataSources((prev) =>
      isSelected ? [...prev, id] : prev.filter((sourceId) => sourceId !== id),
    );
  };

  const getGroupSourceIds = (location: string, groupName: string) => {
    const lg = groupedByLocation.find((g) => g.location === location);
    const sg = lg?.subGroups.find((s) => s.name === groupName);
    return (sg?.dataSources.map((ds) => ds.id).filter(Boolean) as string[]) ?? [];
  };

  const handleSelectAllInGroup = (location: string, groupName: string, isSelected: boolean) => {
    const ids = getGroupSourceIds(location, groupName);
    setSelectedDataSources((prev) =>
      isSelected
        ? [...prev, ...ids.filter((id) => !prev.includes(id))]
        : prev.filter((id) => !ids.includes(id)),
    );
  };

  const isGroupFullySelected = (location: string, groupName: string) => {
    const ids = getGroupSourceIds(location, groupName);
    return ids.length > 0 && ids.every((id) => selectedDataSources.includes(id));
  };

  const isGroupPartiallySelected = (location: string, groupName: string) => {
    const ids = getGroupSourceIds(location, groupName);
    const selected = ids.filter((id) => selectedDataSources.includes(id));
    return selected.length > 0 && selected.length < ids.length;
  };

  const getTypeGroupSourceIds = (sources: DataSource[]) =>
    sources.map((ds) => ds.id).filter(Boolean) as string[];

  const handleSelectAllInTypeGroup = (sources: DataSource[], isSelected: boolean) => {
    const ids = getTypeGroupSourceIds(sources);
    setSelectedDataSources((prev) =>
      isSelected
        ? [...prev, ...ids.filter((id) => !prev.includes(id))]
        : prev.filter((id) => !ids.includes(id)),
    );
  };

  const isTypeGroupFullySelected = (sources: DataSource[]) => {
    const ids = getTypeGroupSourceIds(sources);
    return ids.length > 0 && ids.every((id) => selectedDataSources.includes(id));
  };

  const isTypeGroupPartiallySelected = (sources: DataSource[]) => {
    const ids = getTypeGroupSourceIds(sources);
    const selected = ids.filter((id) => selectedDataSources.includes(id));
    return selected.length > 0 && selected.length < ids.length;
  };

  const handleConfirmDelete = async () => {
    if (selectedDataSources.length > 0) {
      try {
        await deleteDataSources(selectedDataSources);
        setSelectedDataSources([]);
        toast.success(
          `Data source${selectedDataSources.length === 1 ? "" : "s"} deleted successfully`,
        );
      } catch {
        toast.error("Failed to delete selected data sources");
      }
    } else {
      await deleteAllDataSources();
    }
    setShowDeleteAllDialog(false);
  };

  const handleDataBindingComplete = useCallback(
    async (vadalogProgram: string, bindAnnotations?: string[], modelAnnotations?: string[]) => {
      try {
        setSchemaForm(CLOSED_SCHEMA_FORM);
        setConnectionInProgress(true);
        setConnectingDataSource({ type: "Database", name: "Connecting..." });

        if (!vadalogProgram || vadalogProgram.trim() === "") {
          const success = await loadDataSources(true);
          if (success) {
            window.dispatchEvent(
              new CustomEvent("dataSourceConnected", {
                detail: {
                  ontologyScope: sessionStorage.getItem("currentOntologyScope") || "user",
                },
              }),
            );
          }
        } else {
          const success = await connectDataSource(
            vadalogProgram,
            bindAnnotations,
            modelAnnotations,
          );
          if (success) {
            window.dispatchEvent(
              new CustomEvent("dataSourceConnected", {
                detail: {
                  ontologyScope: sessionStorage.getItem("currentOntologyScope") || "user",
                },
              }),
            );
            onSchemaInference?.(vadalogProgram);
          } else {
            toast.error("Failed to connect data source");
          }
        }
      } catch (error) {
        const msg =
          error instanceof Error
            ? error.message
            : "There was a problem connecting your data source";
        toast.error(msg, { duration: 8000 });
      } finally {
        setConnectionInProgress(false);
        setConnectingDataSource(null);
      }
    },
    [connectDataSource, loadDataSources, onSchemaInference],
  );

  const toggleGroup = (groupId: string) => {
    setExpandedGroups((prev) => {
      const next = new Set(prev);
      if (next.has(groupId)) next.delete(groupId);
      else next.add(groupId);
      return next;
    });
  };

  const isBusy =
    isLoading ||
    isConnectingSource ||
    isDeletingSource ||
    isDeletingAllSources ||
    connectionInProgress;

  const filteredGroups = groupedByLocation.filter(
    (lg) =>
      !searchTerm ||
      lg.subGroups.some((sg) =>
        sg.dataSources.some(
          (ds) =>
            (ds.tableName || ds.bindAnnotation || "")
              .toLowerCase()
              .includes(searchTerm.toLowerCase()) ||
            sg.name.toLowerCase().includes(searchTerm.toLowerCase()),
        ),
      ),
  );

  return (
    <div className="p-6 space-y-4">
      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <input
          type="text"
          placeholder="Search data sources…"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="h-9 w-full rounded-md border bg-card pl-9 pr-3 text-sm outline-none focus:ring-2 focus:ring-primary/30 placeholder:text-muted-foreground"
        />
      </div>

      {/* Bulk delete toolbar */}
      {selectedDataSources.length > 0 && (
        <div className="flex items-center justify-between rounded-lg border bg-muted/40 px-4 py-2">
          <span className="text-sm text-muted-foreground">
            {selectedDataSources.length} selected
          </span>
          <Button
            onClick={() => setShowDeleteAllDialog(true)}
            variant="destructive"
            size="sm"
            disabled={isDeletingSource || isDeletingAllSources}
            className="gap-2 h-7 text-xs"
          >
            <Trash2 className="h-3 w-3" />
            Delete selected
          </Button>
        </div>
      )}

      {/* Loading */}
      {isBusy && (
        <div className="flex items-center justify-center py-16">
          <PrometheuxSpinner
            size={36}
            label={
              isConnectingSource || connectionInProgress
                ? "Connecting data source…"
                : isDeletingSource || isDeletingAllSources
                  ? "Deleting data sources…"
                  : "Loading data sources…"
            }
          />
        </div>
      )}

      {/* Cards */}
      {!isBusy && (
        <div className="space-y-3">
          {/* Public demo datasources — always available, expanded when empty */}
          {!searchTerm && (
            <DemoDataSuggestion
              onPickPreset={handlePickDemoPreset}
              defaultOpen={dataSources.length === 0}
            />
          )}

          {/* Connecting placeholder card */}
          {connectingDataSource && (
            <div className="overflow-hidden rounded-xl border bg-card shadow-sm">
              <div className="flex items-center gap-3 px-4 py-3.5">
                <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-muted/60 ring-1 ring-border/50">
                  <PrometheuxSpinner size={16} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-semibold text-sm">{connectingDataSource.type}</p>
                  <p className="text-xs text-muted-foreground">Connecting…</p>
                </div>
              </div>
            </div>
          )}

          {filteredGroups.map((locationGroup) =>
            locationGroup.subGroups.map((subGroup) => {
              const groupId = `${locationGroup.location}_${subGroup.name}`;
              const isExpanded = expandedGroups.has(groupId);
              const fullySelected = isGroupFullySelected(locationGroup.location, subGroup.name);
              const partiallySelected = isGroupPartiallySelected(
                locationGroup.location,
                subGroup.name,
              );

              return (
                <div
                  key={groupId}
                  className={cn(
                    "overflow-hidden rounded-xl border bg-card shadow-sm transition-shadow",
                    isExpanded && "shadow-md",
                  )}
                >
                  {/* Card header */}
                  <div className="flex w-full items-center gap-3 px-4 py-3.5">
                    {/* Group checkbox */}
                    <div
                      className="shrink-0"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleSelectAllInGroup(
                          locationGroup.location,
                          subGroup.name,
                          !fullySelected,
                        );
                      }}
                    >
                      <Checkbox
                        checked={fullySelected}
                        ref={(el) => {
                          const input = el?.querySelector?.(
                            'input[type="checkbox"]',
                          ) as HTMLInputElement | null;
                          if (input) input.indeterminate = partiallySelected;
                        }}
                        onCheckedChange={() => {}}
                        className="pointer-events-none"
                      />
                    </div>

                    {/* Clickable expand area */}
                    <button
                      onClick={() => toggleGroup(groupId)}
                      className="flex flex-1 min-w-0 items-center gap-3 text-left hover:opacity-80 transition-opacity"
                    >
                      <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-muted/60 ring-1 ring-border/50">
                        <DatabaseIcon
                          type={getGroupIconType(subGroup.name, subGroup.type)}
                          className="h-4 w-4"
                        />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="font-semibold text-sm">
                          {subGroup.name.charAt(0).toUpperCase() + subGroup.name.slice(1)}
                        </p>
                        {locationGroup.location !== "Unknown" && (
                          <p className="text-xs text-muted-foreground truncate">
                            {locationGroup.location}
                          </p>
                        )}
                      </div>
                      <span className="shrink-0 text-xs text-muted-foreground">
                        {subGroup.dataSources.length}{" "}
                        {subGroup.dataSources.length === 1 ? "source" : "sources"}
                      </span>
                    </button>

                    {/* Refresh group button */}
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-7 w-7 shrink-0 p-0"
                      title="Reconnect these data sources"
                      disabled={refreshingGroupKey === groupId || isLoading || isConnectingSource}
                      onClick={(e) => {
                        e.stopPropagation();
                        const rep = subGroup.dataSources[0];
                        if (rep) {
                          refreshDataSourceGroup(
                            {
                              datasource_type: rep.datasourceType,
                              host: rep.host || "",
                              port: rep.port || "",
                              database_name: rep.databaseName || "",
                            },
                            groupId,
                          );
                        }
                      }}
                    >
                      <RefreshCw
                        className={cn(
                          "h-3.5 w-3.5",
                          refreshingGroupKey === groupId && "animate-spin",
                        )}
                      />
                    </Button>

                    <button
                      onClick={() => toggleGroup(groupId)}
                      className="shrink-0 text-muted-foreground"
                    >
                      {isExpanded ? (
                        <ChevronUp className="h-4 w-4" />
                      ) : (
                        <ChevronDown className="h-4 w-4" />
                      )}
                    </button>
                  </div>

                  {/* Expanded rows */}
                  {isExpanded && (
                    <div className="border-t bg-muted/30">
                      {subGroup.typeGroups.length > 1 &&
                      getStorageIconType(subGroup.name) !== null ? (
                        <div className="divide-y">
                          {subGroup.typeGroups.map((typeGroup) => {
                            const typeGroupId = `${groupId}_type_${typeGroup.type}`;
                            const isTypeExpanded = expandedGroups.has(typeGroupId);
                            const typeFullySelected = isTypeGroupFullySelected(
                              typeGroup.dataSources,
                            );
                            const typePartiallySelected = isTypeGroupPartiallySelected(
                              typeGroup.dataSources,
                            );

                            return (
                              <div key={typeGroupId}>
                                <div className="flex items-center gap-3 px-4 py-2.5 hover:bg-muted/40 transition-colors">
                                  <div
                                    className="shrink-0"
                                    role="checkbox"
                                    aria-checked={typeFullySelected}
                                    tabIndex={0}
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      handleSelectAllInTypeGroup(
                                        typeGroup.dataSources,
                                        !typeFullySelected,
                                      );
                                    }}
                                    onKeyDown={(e) => {
                                      if (e.key === " " || e.key === "Enter") {
                                        e.preventDefault();
                                        handleSelectAllInTypeGroup(
                                          typeGroup.dataSources,
                                          !typeFullySelected,
                                        );
                                      }
                                    }}
                                  >
                                    <Checkbox
                                      checked={typeFullySelected}
                                      ref={(el) => {
                                        const input = el?.querySelector?.(
                                          'input[type="checkbox"]',
                                        ) as HTMLInputElement | null;
                                        if (input) input.indeterminate = typePartiallySelected;
                                      }}
                                      onCheckedChange={() => {}}
                                      className="pointer-events-none"
                                    />
                                  </div>

                                  <button
                                    type="button"
                                    onClick={() => toggleGroup(typeGroupId)}
                                    className="flex flex-1 min-w-0 items-center gap-2.5 text-left hover:opacity-80 transition-opacity"
                                  >
                                    <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-muted/60 ring-1 ring-border/50">
                                      <DatabaseIcon type={typeGroup.type} className="h-3.5 w-3.5" />
                                    </div>
                                    <span className="font-medium text-sm">
                                      {typeGroup.type.charAt(0).toUpperCase() +
                                        typeGroup.type.slice(1)}
                                    </span>
                                    <span className="text-xs text-muted-foreground">
                                      {typeGroup.dataSources.length}{" "}
                                      {typeGroup.dataSources.length === 1 ? "source" : "sources"}
                                    </span>
                                  </button>

                                  <button
                                    type="button"
                                    onClick={() => toggleGroup(typeGroupId)}
                                    className="shrink-0 text-muted-foreground"
                                  >
                                    {isTypeExpanded ? (
                                      <ChevronUp className="h-3.5 w-3.5" />
                                    ) : (
                                      <ChevronDown className="h-3.5 w-3.5" />
                                    )}
                                  </button>
                                </div>

                                {isTypeExpanded && (
                                  <div className="divide-y border-t bg-background/50">
                                    {typeGroup.dataSources.map((dataSource, index) => (
                                      <DataSourceListItem
                                        key={dataSource.id ?? `${typeGroupId}-${index}`}
                                        id={dataSource.id}
                                        bindAnnotation={dataSource.bindAnnotation}
                                        tableName={dataSource.tableName}
                                        fields={dataSource.fields}
                                        index={index}
                                        rowCount={dataSource.rowCount}
                                        columnCount={dataSource.columnCount}
                                        author={dataSource.author}
                                        timestamp={dataSource.timestamp}
                                        databaseName={dataSource.databaseName}
                                        onSelect={handleDataSourceSelection}
                                        selected={selectedDataSources.includes(dataSource.id ?? "")}
                                        onPreview={previewDataSource}
                                        onPreviewPaginated={previewDataSourcePaginated}
                                        onDisconnect={
                                          canEditDatasources
                                            ? (id) => {
                                                setSelectedDataSources([id]);
                                                setShowDeleteAllDialog(true);
                                              }
                                            : undefined
                                        }
                                      />
                                    ))}
                                  </div>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      ) : (
                        <div className="divide-y">
                          {subGroup.dataSources.map((dataSource, index) => (
                            <DataSourceListItem
                              key={dataSource.id ?? `${groupId}-${index}`}
                              id={dataSource.id}
                              bindAnnotation={dataSource.bindAnnotation}
                              tableName={dataSource.tableName}
                              fields={dataSource.fields}
                              index={index}
                              rowCount={dataSource.rowCount}
                              columnCount={dataSource.columnCount}
                              author={dataSource.author}
                              timestamp={dataSource.timestamp}
                              databaseName={dataSource.databaseName}
                              onSelect={handleDataSourceSelection}
                              selected={selectedDataSources.includes(dataSource.id ?? "")}
                              onPreview={previewDataSource}
                              onPreviewPaginated={previewDataSourcePaginated}
                              onDisconnect={
                                canEditDatasources
                                  ? (id) => {
                                      setSelectedDataSources([id]);
                                      setShowDeleteAllDialog(true);
                                    }
                                  : undefined
                              }
                            />
                          ))}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            }),
          )}

          {/* Empty state */}
          {filteredGroups.length === 0 && !connectingDataSource && (
            <div className="rounded-xl border bg-card p-12 text-center text-sm text-muted-foreground">
              {searchTerm
                ? `No data sources match "${searchTerm}".`
                : "No data sources connected yet. Click + Add Data Source to get started."}
            </div>
          )}
        </div>
      )}

      {/* Connect Data Sources modal */}
      {schemaForm.open && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="w-full max-w-2xl max-h-[95vh] overflow-y-auto rounded">
            <SchemaInferenceForm
              key={schemaForm.prefill?.initialValues.databaseType ?? "manual"}
              onClose={closeSchemaForm}
              onInferenceComplete={handleDataBindingComplete}
              initialValues={schemaForm.prefill?.initialValues}
              initialStorageType={schemaForm.prefill?.initialStorageType}
            />
          </div>
        </div>
      )}

      <DeleteAllSourcesDialog
        open={showDeleteAllDialog}
        onOpenChange={setShowDeleteAllDialog}
        onConfirm={handleConfirmDelete}
        isDeleting={isDeletingAllSources}
        selectedCount={selectedDataSources.length}
      />

      <FailedDatasourcesDialog
        failedDatasources={failedDatasources}
        onClose={clearFailedDatasources}
      />
    </div>
  );
};

export default DataTab;
