/**
 * Pure helpers for rendering an authorization prompt. No hooks, no JSX.
 */

/** "create_csv_datasource" → "Create csv datasource". */
export function prettifyToolName(tool: string): string {
  if (!tool) return "this action";
  const words = tool.replace(/_/g, " ").trim();
  return words.charAt(0).toUpperCase() + words.slice(1);
}

// The most descriptive argument for each tool, shown as the action subject.
const SUBJECT_KEYS = [
  "concept_name",
  "predicate_name",
  "name",
  "app_id",
  "machine_id",
  "snapshot_id",
  "policy_id",
  "data_source",
] as const;

// save_app sends the whole definition under `app`, so its name is nested
// rather than top-level like every other tool's subject.
const NESTED_SUBJECT_ARG = "app";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function trimmedString(value: unknown): string {
  if (typeof value !== "string") return "";
  return value.trim();
}

function nestedSubject(input: Record<string, unknown>): string {
  const nested = input[NESTED_SUBJECT_ARG];
  if (!isRecord(nested)) return "";
  return trimmedString(nested.name);
}

/**
 * A short, human subject for the action, e.g. the concept/app/datasource name.
 * Returns an empty string when nothing descriptive is present.
 */
export function summarizeAuthorizationInput(input: Record<string, unknown> | undefined): string {
  if (!input) return "";
  for (const key of SUBJECT_KEYS) {
    const value = trimmedString(input[key]);
    if (value) return value;
  }
  return nestedSubject(input);
}
