import type React from "react";
import { siSnowflake } from "simple-icons";

interface SnowflakeIconProps {
  className?: string;
  size?: number;
}

/**
 * Snowflake brand icon from simple-icons.
 * Drop-in replacement for the lucide Snowflake icon wherever the real brand logo is needed.
 */
const SnowflakeIcon: React.FC<SnowflakeIconProps> = ({ className = "", size }) => {
  const resolvedSize = size ?? sizeFromClassName(className) ?? 16;

  return (
    <svg
      role="img"
      viewBox="0 0 24 24"
      width={resolvedSize}
      height={resolvedSize}
      className={className}
      fill={`#${siSnowflake.hex}`}
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d={siSnowflake.path} />
    </svg>
  );
};

function sizeFromClassName(cls: string): number | undefined {
  if (cls.includes("w-3 ") || cls.includes('w-3"') || /\bw-3\b/.test(cls)) return 12;
  if (/\bw-3\.5\b/.test(cls)) return 14;
  if (/\bw-4\b/.test(cls)) return 16;
  if (/\bw-5\b/.test(cls)) return 20;
  if (/\bw-6\b/.test(cls)) return 24;
  return undefined;
}

export default SnowflakeIcon;
