import { ContactToUpgradeDialog } from "@/features/billing/components/ContactToUpgradeDialog";
import type { OntologyScope } from "@/features/ontologies/api";
import ShareOntologyDialog from "@/features/ontologies/sharing/components/ShareOntologyDialog";
import TeamAdminPermissionsDialog from "@/features/ontologies/sharing/components/TeamAdminPermissionsDialog";
import CopyOntologyDialog from "./CopyOntologyDialog";
import EditOntologyDialog from "./EditOntologyDialog";

export type OntologyCardDialog = "copy" | "share" | "shareUpgrade" | "teamAccess" | null;

interface OntologyCardDialogsProps {
  ontologyId: string;
  displayName: string;
  displayDescription: string;
  scope: OntologyScope;
  teamId?: string;
  teamName?: string;
  ownerSub?: string;
  showEditDialog: boolean;
  onCloseEdit: () => void;
  onUpdate: (id: string, newName: string, newDescription: string) => Promise<void>;
  onDelete: (name: string) => void;
  dialog: OntologyCardDialog;
  setDialog: (dialog: OntologyCardDialog) => void;
  onCopy: (id: string, newName: string, targetScope: OntologyScope) => Promise<void>;
}

// The modal cluster an OntologyCard can open (edit / copy / share / team-access /
// upgrade wall). Extracted from OntologyCard to keep that component under the
// size limit; state stays in the card and is passed in.
export function OntologyCardDialogs({
  ontologyId,
  displayName,
  displayDescription,
  scope,
  teamId,
  teamName,
  ownerSub,
  showEditDialog,
  onCloseEdit,
  onUpdate,
  onDelete,
  dialog,
  setDialog,
  onCopy,
}: OntologyCardDialogsProps) {
  return (
    <>
      {showEditDialog && (
        <EditOntologyDialog
          isOpen={showEditDialog}
          onClose={onCloseEdit}
          onUpdateOntology={onUpdate}
          onDeleteOntology={onDelete}
          currentName={displayName}
          currentDescription={displayDescription}
          ontologyId={ontologyId}
          ontologyScope={scope}
        />
      )}

      {dialog === "copy" && (
        <CopyOntologyDialog
          isOpen
          onClose={() => setDialog(null)}
          onCopyOntology={onCopy}
          sourceOntologyName={displayName}
          ontologyId={ontologyId}
          ontologyScope={scope}
        />
      )}

      {dialog === "share" && (
        <ShareOntologyDialog
          isOpen
          onClose={() => setDialog(null)}
          ontologyId={ontologyId}
          ontologyName={displayName}
        />
      )}

      {dialog === "teamAccess" && teamId && (
        <TeamAdminPermissionsDialog
          isOpen
          onClose={() => setDialog(null)}
          ontologyId={ontologyId}
          ontologyName={displayName}
          teamId={teamId}
          teamName={teamName}
          ownerSub={ownerSub}
        />
      )}

      <ContactToUpgradeDialog
        open={dialog === "shareUpgrade"}
        onOpenChange={(open) => setDialog(open ? "shareUpgrade" : null)}
        title="Sharing is part of a paid subscription"
        description="Sharing ontologies with your team is available on a paid subscription. Contact Prometheux to upgrade and start collaborating."
        contactSubject="Upgrade request — team sharing"
      />
    </>
  );
}
