import type { ConceptType } from "@/features/concept-editor/types";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";

const CONCEPT_TYPE_OPTIONS: { value: ConceptType; label: string }[] = [
  { value: "logic", label: "Logic" },
  { value: "sql", label: "SQL" },
  { value: "cypher", label: "Cypher" },
  { value: "python", label: "Python" },
  { value: "context", label: "Context" },
  { value: "llm", label: "LLM" },
];

function isConceptType(value: string): value is ConceptType {
  return CONCEPT_TYPE_OPTIONS.some((option) => option.value === value);
}

interface CellTypeSelectProps {
  value: ConceptType;
  onChange: (value: ConceptType) => void;
}

/**
 * The concept-type dropdown in a cell header. Single source of truth for the
 * option list — a new concept type is added here once instead of in every cell.
 */
export function CellTypeSelect({ value, onChange }: CellTypeSelectProps) {
  const handleChange = (next: string) => {
    if (isConceptType(next)) onChange(next);
  };

  return (
    <Select value={value} onValueChange={handleChange}>
      <SelectTrigger className="h-7 w-[90px] text-xs border-border">
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {CONCEPT_TYPE_OPTIONS.map((option) => (
          <SelectItem key={option.value} value={option.value} className="text-xs">
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}
