import { Database, NotebookText, Waypoints } from "lucide-react";
import { useLocation } from "react-router-dom";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { SidebarAppsItem } from "@/shared/components/layout/SidebarAppsItem";
import { SidebarNavLink } from "@/shared/components/layout/SidebarNavLink";

interface SidebarWorkspaceLinksProps {
  collapsed: boolean;
  iconClassName: string;
}

/** The permission-gated static links of the Workspace nav section
 *  (Data / Notes / Apps). Home and Projects stay in SidePanel — they
 *  need its navigation handlers. */
export function SidebarWorkspaceLinks({ collapsed, iconClassName }: SidebarWorkspaceLinksProps) {
  const location = useLocation();
  const canSeeAiAgent = usePermissionsStore((state) => state.canSee("can_see_ai_agent"));
  const canSeeDatasources = usePermissionsStore((state) => state.canSee("can_see_datasources"));
  const canSeeGraphExplorer = usePermissionsStore((state) =>
    state.canSee("can_see_graph_explorer"),
  );

  return (
    <>
      {canSeeDatasources && (
        <SidebarNavLink
          icon={<Database className={iconClassName} />}
          label="Data"
          to="/datasources"
          isActive={location.pathname === "/datasources"}
          collapsed={collapsed}
        />
      )}
      {canSeeGraphExplorer && (
        <SidebarNavLink
          icon={<Waypoints className={iconClassName} />}
          label="Graph Explorer"
          to="/graph-explorer"
          isActive={location.pathname.startsWith("/graph-explorer")}
          collapsed={collapsed}
        />
      )}
      {canSeeAiAgent && (
        <SidebarNavLink
          icon={<NotebookText className={iconClassName} />}
          label="Context"
          to="/context"
          isActive={location.pathname.startsWith("/context")}
          collapsed={collapsed}
        />
      )}
      <SidebarAppsItem collapsed={collapsed} />
    </>
  );
}
