import { useCallback, useMemo, useState } from "react";

export interface UseLineageGroupFilterReturn {
  /** Group filter keys the user has toggled off (hidden from the canvas). */
  hiddenGroups: Set<string>;
  /** Whether a given group key is currently visible. */
  isGroupVisible: (key: string) => boolean;
  /** Show/hide a single group. */
  toggleGroup: (key: string) => void;
}

/**
 * Owns the lineage canvas group-visibility filter: a set of hidden group keys.
 * Kept deliberately small (one piece of state) so it can be reused by both the
 * legend control and the node/edge filtering in `LineageView`.
 */
export function useLineageGroupFilter(): UseLineageGroupFilterReturn {
  const [hiddenGroups, setHiddenGroups] = useState<Set<string>>(new Set());

  const toggleGroup = useCallback((key: string) => {
    setHiddenGroups((prev) => {
      const next = new Set(prev);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  }, []);

  const isGroupVisible = useCallback((key: string) => !hiddenGroups.has(key), [hiddenGroups]);

  return useMemo(
    () => ({ hiddenGroups, isGroupVisible, toggleGroup }),
    [hiddenGroups, isGroupVisible, toggleGroup],
  );
}
