import React, { useMemo } from "react";
import type {
  ExecutionOverallStatus,
  ExecutionStatusSnapshot,
} from "@/features/lineage/executionStatus";
import type { OntologyData, OntologyScope } from "@/features/ontologies/api";
import { useOntologiesExecutionStatus } from "@/features/ontologies/hooks/useOntologiesExecutionStatus";
import { lineageRunAck } from "@/shared/utils/lineageRunAck";
import OntologyCard from "./OntologyCard";
import PendingShareCard from "./PendingShareCard";

/**
 * The status to badge for a project. A live run always shows; a terminal
 * failure the user has already acknowledged (in the lineage notice, keyed by
 * execution_id) is suppressed so it doesn't keep nagging from the list too.
 */
function visibleStatus(
  snapshot: ExecutionStatusSnapshot | undefined,
): ExecutionOverallStatus | undefined {
  if (!snapshot) return undefined;
  if (snapshot.status === "running") return "running";
  if (lineageRunAck.isAcked(snapshot.executionId)) return undefined;
  return snapshot.status;
}

interface OntologyListProps {
  projects: OntologyData[] | string[];
  onOpenOntology: (ontologyId: string, ontologyName: string) => void;
  onDeleteOntology?: (ontologyName: string) => void;
  onRenameOntology?: (id: string, newName: string, newDescription: string) => Promise<void>;
  onCopyOntology?: (
    ontologyId: string,
    newOntologyName: string,
    targetScope: OntologyScope,
  ) => Promise<void>;
  // Recipient-side callbacks. Wired only when the list is rendered in the
  // Shared with me tab; ignored elsewhere. Pending invitations need both
  // (Accept and Decline); accepted shares only need leave. Team shares awaiting
  // a claim need onClaimShare.
  onAcceptShare?: (shareId: string) => Promise<void>;
  onLeaveShare?: (shareId: string) => Promise<void>;
  onClaimShare?: (shareId: string) => Promise<void>;
  onRefreshOntologies?: () => Promise<void>;
  onOntologyImported?: () => Promise<void>;
  openingOntologyId?: string | null;
}

const OntologyList: React.FC<OntologyListProps> = ({
  projects,
  onOpenOntology,
  onDeleteOntology,
  onRenameOntology,
  onCopyOntology,
  onAcceptShare,
  onLeaveShare,
  onClaimShare,
  openingOntologyId,
}) => {
  // Scopes present in this list — drives the single batch execution-status query.
  const scopes = useMemo(() => {
    const set = new Set<string>();
    for (const project of projects) {
      set.add(typeof project === "string" ? "user" : project.scope);
    }
    return Array.from(set);
  }, [projects]);

  const { statuses } = useOntologiesExecutionStatus(scopes);

  return (
    <div>
      <div className="grid grid-cols-3 gap-4">
        {projects.map((project) => {
          // Handle both string[] (legacy callers passing project ids only) and
          // ProjectData[] (everything else).
          if (typeof project === "string") {
            return (
              <OntologyCard
                key={project}
                ontologyId={project}
                scope="user"
                onOpenOntology={onOpenOntology}
                onDelete={onDeleteOntology}
                onRename={onRenameOntology}
                onCopy={onCopyOntology}
                isOpening={openingOntologyId === project}
                executionStatus={visibleStatus(statuses[project])}
              />
            );
          }

          // Team share awaiting a claim → single "Join" card (no decline).
          const isTeamNeedsClaim =
            project.origin === "shared" &&
            project.shareType === "team" &&
            project.needsClaim === true &&
            !!project.shareId;

          if (
            isTeamNeedsClaim &&
            onClaimShare &&
            onAcceptShare &&
            onLeaveShare &&
            project.shareId
          ) {
            return (
              <PendingShareCard
                key={project.id}
                ontologyId={project.id}
                ontologyName={project.name}
                ontologyDescription={project.description}
                sharedBy={project.sharedBy}
                shareRole={project.shareRole}
                shareId={project.shareId}
                shareType="team"
                onClaim={onClaimShare}
                onAccept={onAcceptShare}
                onDecline={onLeaveShare}
              />
            );
          }

          const isPendingShare =
            project.origin === "shared" && project.shareStatus === "pending" && !!project.shareId;

          if (isPendingShare && onAcceptShare && onLeaveShare && project.shareId) {
            return (
              <PendingShareCard
                key={project.id}
                ontologyId={project.id}
                ontologyName={project.name}
                ontologyDescription={project.description}
                sharedBy={project.sharedBy}
                shareRole={project.shareRole}
                shareId={project.shareId}
                onAccept={onAcceptShare}
                onDecline={onLeaveShare}
              />
            );
          }

          return (
            <OntologyCard
              key={project.id}
              ontologyId={project.id}
              ontologyName={project.name}
              ontologyDescription={project.description}
              scope={project.scope}
              author={project.author}
              origin={project.origin}
              sharedBy={project.sharedBy}
              shareRole={project.shareRole}
              shareId={project.shareId}
              shareType={project.shareType}
              teamId={project.teamId}
              onOpenOntology={onOpenOntology}
              onDelete={onDeleteOntology}
              onRename={onRenameOntology}
              onCopy={onCopyOntology}
              onLeaveShare={onLeaveShare}
              isOpening={openingOntologyId === project.id}
              executionStatus={visibleStatus(statuses[project.id])}
            />
          );
        })}
      </div>
    </div>
  );
};

export default React.memo(OntologyList);
