import type { AppWidgetDef, AppWidgetType } from "../schema/appDefinition.types";

export interface WidgetTypeOption {
  type: AppWidgetType;
  label: string;
}

/** The add-widget menu, grouped roughly by role (inputs, actions, outputs). */
export const WIDGET_TYPE_OPTIONS: WidgetTypeOption[] = [
  { type: "input_ref", label: "Input" },
  { type: "form_ref", label: "Form" },
  { type: "run_button", label: "Run button" },
  { type: "button", label: "Button" },
  { type: "rich_table", label: "Table" },
  { type: "text", label: "Text" },
  { type: "stat_card", label: "Stat card" },
  { type: "line_chart", label: "Line chart" },
  { type: "area_chart", label: "Area chart" },
  { type: "bar_chart", label: "Bar chart" },
  { type: "pie_chart", label: "Pie chart" },
  { type: "heatmap", label: "Heatmap" },
];

const DEFAULT_SPANS: Partial<Record<AppWidgetType, number>> = {
  input_ref: 3,
  run_button: 2,
  button: 2,
  stat_card: 3,
  line_chart: 6,
  area_chart: 6,
  bar_chart: 6,
  pie_chart: 4,
  heatmap: 6,
};

/** A freshly added widget: sensible span, empty bindings for the inspector to fill. */
export function defaultWidgetFor(type: AppWidgetType): Omit<AppWidgetDef, "id"> {
  const base: Omit<AppWidgetDef, "id"> = { type, span: DEFAULT_SPANS[type] ?? 12 };
  if (type === "text") return { ...base, content: "New text block" };
  if (type === "button") return { ...base, label: "Button", action: { type: "open_url", url: "" } };
  return base;
}
