// Pure billing helpers — no hooks, no JSX. Lives separately per the
// code-style rule so it can be unit-tested without React.

import { HttpError } from "@/shared/services/httpService";

export const GRACE_PERIOD_DAYS = 5;
const MS_PER_DAY = 1000 * 60 * 60 * 24;

/**
 * The Python backend refuses billable actions with HTTP 402 and a body of
 * { code: "PAYMENT_REQUIRED", error: "billing_required" }. Match on the code
 * field (stable contract) — never on the message string.
 */
export const isPaymentRequiredError = (err: unknown): boolean => {
  if (!(err instanceof HttpError)) return false;
  if (err.status !== 402) return false;
  const body = err.body;
  if (typeof body !== "object" || body === null) return false;
  if (!("code" in body)) return false;
  return body.code === "PAYMENT_REQUIRED";
};

/**
 * Returns `true` when an unpaid invoice's `sent_at` is older than the 5-day
 * grace period, matching the server-side rule used by `can_use_paid_compute`.
 */
export const isInvoiceOverdue = (sentAtIso: string, now: Date = new Date()): boolean => {
  const sentAt = new Date(sentAtIso);
  if (Number.isNaN(sentAt.getTime())) return false;
  const ageDays = (now.getTime() - sentAt.getTime()) / MS_PER_DAY;
  return ageDays >= GRACE_PERIOD_DAYS;
};

/**
 * Formats an ISO timestamp as a short human date (e.g. "Jul 1, 2026") for quota
 * reset copy. Returns null when the input is missing or unparseable.
 */
export const formatResetDate = (isoDate: string | null): string | null => {
  if (!isoDate) return null;
  const date = new Date(isoDate);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
};

/**
 * Returns the number of full days remaining until `endsAt` (or null if the
 * timestamp is missing/invalid). Negative values are clamped to 0.
 */
export const trialDaysRemaining = (
  endsAtIso: string | null,
  now: Date = new Date(),
): number | null => {
  if (!endsAtIso) return null;
  const ends = new Date(endsAtIso);
  if (Number.isNaN(ends.getTime())) return null;
  const diffDays = (ends.getTime() - now.getTime()) / MS_PER_DAY;
  return Math.max(0, Math.ceil(diffDays));
};
