import { useCallback, useRef, useState } from "react";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { MachineClient } from "@/features/compute/api/MachineClient";
import { useToast } from "@/shared/hooks/ui/use-toast";

interface RequestMachineResult {
  success: boolean;
  data?: unknown;
  error?: string;
}

export const useRequestMachine = () => {
  const [isRequesting, setIsRequesting] = useState(false);
  const { user } = useAuth();
  const { toast } = useToast();
  const clientRef = useRef(new MachineClient());

  const requestMachine = useCallback(
    async (machineId: string, machineName?: string): Promise<RequestMachineResult> => {
      if (!user?.id) {
        const error = "User not authenticated";
        toast({
          title: "Authentication Error",
          description: error,
          variant: "destructive",
        });
        return { success: false, error };
      }

      setIsRequesting(true);

      try {
        const response = await clientRef.current.useMachine(machineId, machineName);

        if (response.status === "error") {
          // Handle already enabled error
          if (response.message.includes("already using")) {
            toast({
              title: "Already in Use",
              description: response.message,
              variant: "destructive",
            });
            return { success: false, error: response.message };
          }

          throw new Error(response.message);
        }

        // Show success toast
        const isRestored = response.data?.restored || false;
        const previousUsage = response.data?.previous_usage_minutes || 0;
        const freeMinutesRemaining = response.data?.free_minutes_remaining;

        let description = "";
        if (isRestored) {
          description = `Restored with ${previousUsage.toFixed(0)} minutes of usage history.`;
          if (freeMinutesRemaining !== null && freeMinutesRemaining !== undefined) {
            description += ` ${freeMinutesRemaining.toFixed(0)} free minutes remaining.`;
          }
        } else {
          description = `${machineName || "Machine"} is now in your list. Click 'Start' to activate it.`;
        }

        toast({
          title: isRestored ? "Machine Re-enabled!" : "Machine Added",
          description: description,
          variant: "default",
        });

        return { success: true, data: response.data?.user_machine };
      } catch (error) {
        console.error("Error using machine:", error);
        const errorMessage = error instanceof Error ? error.message : "Failed to use machine";

        toast({
          title: "Failed to Use Machine",
          description: errorMessage,
          variant: "destructive",
        });

        return { success: false, error: errorMessage };
      } finally {
        setIsRequesting(false);
      }
    },
    [user?.id, toast],
  );

  return {
    requestMachine,
    isRequesting,
  };
};
