import React, { useCallback, useMemo } from "react";
import QueryResultTable, {
  type ColumnFilterValue,
  type OrderByItem,
} from "@/features/concept-editor/components/query/components/QueryResultTable";
import { usePaginatedResults } from "@/features/concept-editor/hooks/usePaginatedResults";
import { isStoppedByUser } from "@/features/concept-editor/utils/runStatus";
import { useOntologyId } from "@/features/ontologies/hooks/useOntologyId";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { ScrollArea } from "@/shared/components/ui/scroll-area";
import type { CellResultsProps } from "../types/editorTypes";

const CellResults: React.FC<CellResultsProps> = ({
  cell,
  setCells,
  changePage: externalChangePage,
  isLoadingPage: externalIsLoadingPage,
  searchPredicateData: externalSearchPredicateData,
  clearSearch: externalClearSearch,
}) => {
  const ontologyId = useOntologyId();

  const paginationHook = usePaginatedResults([cell], setCells);

  // Use external pagination props if provided, otherwise use local hooks
  const changePage = externalChangePage || paginationHook.changePage;
  const changePageSize = paginationHook.changePageSize;
  const changeOrderBy = paginationHook.changeOrderBy;
  const isLoadingPage =
    externalIsLoadingPage !== undefined ? externalIsLoadingPage : paginationHook.isLoadingPage;
  const searchPredicateData = externalSearchPredicateData || paginationHook.searchPredicateData;
  const clearSearch = externalClearSearch || paginationHook.clearSearch;

  /* ---------------------------------------------------------- */
  /* memoised helpers                                           */
  /* ---------------------------------------------------------- */
  const loadingState = useMemo(
    () =>
      cell.isWaitingForEngine ? (
        <div className="bg-amber-50 dark:bg-amber-950/30 p-3 text-sm text-amber-700 dark:text-amber-400 border-t border-amber-200 dark:border-amber-800/50 flex items-center gap-2">
          <PrometheuxSpinner size={16} />
          Waiting for the engine to free up… it will run automatically.
        </div>
      ) : (
        <div className="bg-muted p-3 text-sm flex items-center gap-2">
          <PrometheuxSpinner size={16} />
          Running query...
        </div>
      ),
    [cell.isWaitingForEngine],
  );

  const errorState = useMemo(() => {
    if (isStoppedByUser(cell.error)) {
      return (
        <div className="bg-yellow-50 dark:bg-yellow-950/30 p-3 text-sm text-yellow-700 dark:text-yellow-400 border-t border-yellow-200 dark:border-yellow-800/50">
          <div className="font-medium mb-1">Stopped:</div>
          <div className="whitespace-pre-wrap break-words">{cell.error}</div>
        </div>
      );
    }
    return (
      <div className="bg-red-50 dark:bg-red-950/30 p-3 text-sm text-red-600 dark:text-red-400 border-t border-red-200 dark:border-red-800/50">
        <div className="font-medium mb-1">Error:</div>
        <div className="whitespace-pre-wrap break-words">{cell.error}</div>
      </div>
    );
  }, [cell.error]);

  const isPredicateLoading = useCallback(
    (predicate: string) => cell.loadingPredicates?.includes(predicate) || false,
    [cell.loadingPredicates],
  );

  const handlePageChange = useCallback(
    (predicate: string, newPage: number) => {
      if (changePage) {
        changePage(cell.id, predicate, newPage);
      }
    },
    [changePage, cell.id],
  );

  const handlePageSizeChange = useCallback(
    (predicate: string, newPageSize: number) => {
      if (changePageSize) {
        changePageSize(cell.id, predicate, newPageSize);
      }
    },
    [changePageSize, cell.id],
  );

  // Handle search for a specific predicate
  // For global search: pass searchTerm, no columnFilters
  // For column filters: pass columnFilters, searchTerm can be empty
  const handleSearch = useCallback(
    (predicate: string, searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) => {
      if (searchPredicateData) {
        searchPredicateData(cell.id, predicate, searchTerm, columnFilters);
      }
    },
    [searchPredicateData, cell.id],
  );

  // Handle clear search for a specific predicate
  const handleClearSearch = useCallback(
    (predicate: string) => {
      if (clearSearch) {
        clearSearch(cell.id, predicate);
      }
    },
    [clearSearch, cell.id],
  );

  // Handle clear individual column filter
  const handleClearColumnFilter = useCallback(
    (predicate: string, columnIndex: number) => {
      // Get current search state
      const resultData = cell.result?.data;
      if (!resultData || !resultData[predicate]?.searchState?.columnFilters) {
        return;
      }

      const currentFilters = resultData[predicate].searchState.columnFilters || {};
      const updatedFilters = { ...currentFilters };
      delete updatedFilters[columnIndex];

      if (Object.keys(updatedFilters).length > 0) {
        // Still have other filters
        handleSearch(predicate, undefined, updatedFilters);
      } else {
        // No more column filters, clear all search
        handleClearSearch(predicate);
      }
    },
    [cell.result?.data, handleSearch, handleClearSearch],
  );

  // Handle sorting for a specific predicate
  const handleSort = useCallback(
    (predicate: string, orderBy: OrderByItem[]) => {
      if (changeOrderBy) {
        changeOrderBy(cell.id, predicate, orderBy);
      }
    },
    [changeOrderBy, cell.id],
  );

  /* ---------------------------------------------------------- */
  /* render results                                             */
  /* ---------------------------------------------------------- */
  const resultContent = useMemo(() => {
    // If no result, don't show anything
    if (!cell.result) {
      return null;
    }

    const resultData = cell.result.data;
    const predicates = Object.keys(resultData);

    // If no predicates, show a no results message instead of null
    if (predicates.length === 0) {
      // Show different message for Databricks cells
      const isDatabricksCell = cell.useDatabricks;
      const message = isDatabricksCell
        ? "Prometheux job terminated. Loading results..."
        : "No predicates found";

      return (
        <div className="w-full overflow-x-auto custom-scrollbar">
          <div className="p-2 flex flex-col items-start">
            <div className="p-8 flex items-center justify-center text-sm text-muted-foreground">
              {message}
            </div>
          </div>
        </div>
      );
    }

    return (
      <div className="w-full overflow-x-auto custom-scrollbar">
        <div className="p-2 flex flex-col items-start">
          {predicates.map((pred) => {
            const runTime = cell.result?.runElapsedTime;
            const fetchTime = resultData[pred].fetchElapsedTime;

            return (
              <QueryResultTable
                key={`${cell.id}-${pred}`}
                data={{
                  predicateName: pred,
                  columns: resultData[pred].columns,
                  rows: resultData[pred].rows,
                }}
                pagination={resultData[pred].pagination}
                onPageChange={(page) => handlePageChange(pred, page)}
                onPageSizeChange={(pageSize) => handlePageSizeChange(pred, pageSize)}
                isLoading={isPredicateLoading(pred)}
                onSearch={(searchTerm, columnFilters) =>
                  handleSearch(pred, searchTerm, columnFilters)
                }
                onClearSearch={() => handleClearSearch(pred)}
                onClearColumnFilter={(columnIndex) => handleClearColumnFilter(pred, columnIndex)}
                searchState={resultData[pred].searchState}
                onSort={(orderBy) => handleSort(pred, orderBy)}
                ontologyId={ontologyId || undefined}
                cellId={cell.cellBackendId || cell.id}
                runElapsedTime={runTime}
                fetchElapsedTime={fetchTime}
              />
            );
          })}
        </div>
      </div>
    );
  }, [
    cell.result?.data,
    cell.id,
    cell.cellBackendId,
    handlePageChange,
    handlePageSizeChange,
    isPredicateLoading,
    handleSearch,
    handleClearSearch,
    handleClearColumnFilter,
    handleSort,
    ontologyId,
  ]);

  const cellIdInfo = useMemo(() => {
    return cell.cellBackendId ? (
      <div className="text-xs text-muted-foreground/60 mt-1">Cell ID: {cell.cellBackendId}</div>
    ) : null;
  }, [cell.cellBackendId]);

  // Calculate total results count across all predicates
  const totalResultsCount = useMemo(() => {
    if (!cell.result?.data) return null;

    const resultData = cell.result.data;
    const predicates = Object.keys(resultData);

    let total = 0;
    let hasSearch = false;

    predicates.forEach((pred) => {
      const pagination = resultData[pred].pagination;
      const searchState = resultData[pred].searchState;

      if (pagination && pagination.totalCount !== undefined) {
        total += pagination.totalCount;
      }

      if (searchState?.searchTerm) {
        hasSearch = true;
      }
    });

    return { total, hasSearch };
  }, [cell.result?.data]);

  /* ---------------------------------------------------------- */
  /* return markup                                              */
  /* ---------------------------------------------------------- */
  // Check if we should show loading state (including when pagination is loading)
  const hasLoadingPredicates = cell.loadingPredicates && cell.loadingPredicates.length > 0;
  const isInitialPaginationLoading =
    cell.result &&
    cell.result.data &&
    Object.keys(cell.result.data).some((predicate) => !cell.result?.data[predicate].pagination) &&
    hasLoadingPredicates;

  if (cell.isRunning || isInitialPaginationLoading) return loadingState;
  if (cell.error && !cell.isRunning) return errorState;

  if (cell.result && !cell.isRunning) {
    // If resultContent is null (because we're still loading), show loading state
    if (resultContent === null) {
      return loadingState;
    }

    return (
      <div className="bg-muted/50 p-2 border-t border-border/30">
        <div className="text-xs text-muted-foreground mb-2 pl-4 flex items-center gap-3">
          <span>
            {totalResultsCount !== null && totalResultsCount.total >= 0
              ? `${totalResultsCount.total} results`
              : "results"}
          </span>
          {cell.result.runElapsedTime !== undefined && (
            <span className="text-muted-foreground/70">
              • executed in {(cell.result.runElapsedTime / 1000).toFixed(2)}s
            </span>
          )}
          {/* {cellIdInfo} */}
        </div>
        <div className="bg-transparent rounded-md overflow-hidden">{resultContent}</div>
      </div>
    );
  }

  return null;
};

export default React.memo(CellResults);
