import { RefreshCw } from "lucide-react";
import { Fragment } from "react";
import { Button } from "@/shared/components/ui/button";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";
import type { OntologyDocument, SummarySource } from "./types";

interface SummaryHeaderProps {
  project: OntologyDocument["project"];
  summary: string;
  summarySource: SummarySource;
  isRefreshing: boolean;
  onRefresh: () => void;
}

function focusOnLineage(predicateName: string) {
  // Ask LineageView to focus this concept once it mounts (or immediately if
  // it's already mounted with its nodes ready), then switch to the Ontology
  // tab (still backed by the lineage id/plumbing).
  useEditorActionsStore.getState().register({ pendingLineageFocus: predicateName });
  window.dispatchEvent(new CustomEvent("switchTab", { detail: "lineage" }));
}

function renderSummaryWithPredicateHighlights(summary: string) {
  // Backend wraps predicate / concept names in single backticks; we render the
  // odd-indexed segments (the content between matching backticks) as clickable
  // monospace tokens that jump to the Lineage view with that concept focused.
  const parts = summary.split("`");
  return parts.map((part, index) => {
    if (index % 2 === 1 && part.length > 0) {
      return (
        <button
          // biome-ignore lint/suspicious/noArrayIndexKey: split index is stable per render
          key={index}
          type="button"
          onClick={() => focusOnLineage(part)}
          title={`Show ${part} in Ontology`}
          className="rounded bg-primary/10 px-1 py-0.5 font-mono text-[0.85em] font-medium text-primary transition-colors hover:bg-primary/20 hover:underline focus:outline-none focus:ring-2 focus:ring-primary/40"
        >
          {part}
        </button>
      );
    }
    return (
      // biome-ignore lint/suspicious/noArrayIndexKey: split index is stable per render
      <Fragment key={index}>{part}</Fragment>
    );
  });
}

export function SummaryHeader({
  project,
  summary,
  summarySource,
  isRefreshing,
  onRefresh,
}: SummaryHeaderProps) {
  const trimmedSummary = summary.trim();
  const isEmptyOntology = summarySource === "empty_project";

  return (
    <section className="border-b border-border bg-card px-8 py-6">
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0 flex-1">
          <h1 className="truncate text-2xl font-semibold text-foreground">
            {project.name || "Untitled ontology"}
          </h1>
          {project.description && (
            <p className="mt-1 text-sm text-muted-foreground">{project.description}</p>
          )}
        </div>
        <Button
          variant="outline"
          size="sm"
          className="gap-1.5"
          onClick={onRefresh}
          disabled={isRefreshing}
          type="button"
        >
          <RefreshCw className={isRefreshing ? "h-3.5 w-3.5 animate-spin" : "h-3.5 w-3.5"} />
          Refresh
        </Button>
      </div>
      {trimmedSummary && (
        <p
          className={
            isEmptyOntology
              ? "mt-4 text-sm italic leading-relaxed text-muted-foreground"
              : "mt-4 text-sm leading-relaxed text-foreground"
          }
        >
          {renderSummaryWithPredicateHighlights(trimmedSummary)}
        </p>
      )}
    </section>
  );
}
