import { Info, RotateCcw, Trash2 } from "lucide-react";
import { Button } from "@/shared/components/ui/button";

interface EdgeActionButtonsProps {
  /** DOM-space position of the selected edge's midpoint. */
  position: { x: number; y: number };
  onDetails: () => void;
  onCycleCurve: () => void;
  onDelete: () => void;
}

const BUTTON_CLASS = "h-8 w-8 p-0 rounded-full transition-colors hover:[background-color:#d1d5db]";

/** Floating actions shown over a selected edge on the canvas. */
export function EdgeActionButtons({
  position,
  onDetails,
  onCycleCurve,
  onDelete,
}: EdgeActionButtonsProps) {
  return (
    <div
      className="absolute z-20 bg-background/95 backdrop-blur-sm border rounded-full shadow-lg p-1 flex gap-0.5"
      style={{ left: position.x, top: position.y, transform: "translate(-50%, -50%)" }}
    >
      <Button
        onClick={onDetails}
        variant="ghost"
        size="sm"
        title="Edge Details"
        className={BUTTON_CLASS}
      >
        <Info className="w-4 h-4" />
      </Button>
      <Button
        onClick={onCycleCurve}
        variant="ghost"
        size="sm"
        title="Change Curve Shape"
        className={BUTTON_CLASS}
      >
        <RotateCcw className="w-4 h-4" />
      </Button>
      <Button
        onClick={onDelete}
        variant="ghost"
        size="sm"
        title="Delete Edge"
        className={BUTTON_CLASS}
      >
        <Trash2 className="w-4 h-4" />
      </Button>
    </div>
  );
}
