import { FolderKanban, Info } from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { useConceptEditorClient } from "@/features/concept-editor/api/ConceptEditorClientContext";
import { useSchemaStore } from "@/features/concept-editor/store";
import { ConceptService } from "@/features/concepts/api";
import type { FailedDatasource } from "@/features/data-sources/components/FailedDatasourcesDialog";
import FailedDatasourcesDialog from "@/features/data-sources/components/FailedDatasourcesDialog";
import { type OntologyScope, OntologyService } from "@/features/ontologies/api";
import CreateOntologyDialog from "@/features/ontologies/components/CreateOntologyDialog";
import EditOntologyDialog from "@/features/ontologies/components/EditOntologyDialog";
import { OntologiesListHeaderActions } from "@/features/ontologies/components/OntologiesListHeaderActions";
import OntologyCreationLoader from "@/features/ontologies/components/OntologyCreationLoader";
import OntologyList from "@/features/ontologies/components/OntologyList";
import TemplateList from "@/features/ontologies/components/TemplateList";
import { useOntologies } from "@/features/ontologies/hooks/useOntologies";
import { useTemplates } from "@/features/ontologies/hooks/useTemplates";
import SharedOntologiesTab from "@/features/ontologies/sharing/components/SharedOntologiesTab";
import { useShareInbox } from "@/features/ontologies/sharing/hooks/useShareInbox";
import { setCurrentOntologyId, setCurrentOntologyScope } from "@/features/ontologies/utils";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import SidePanel from "@/shared/components/layout/SidePanel";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";
import { generateEditorUrl } from "@/shared/utils/navigationUtils";

const baseLoadingSteps = [
  "Processing context",
  "Generating ontology",
  "Defining concepts",
  "Setting up ontology",
];

const OntologiesListPage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { user } = useAuth();

  // This component is rendered at both "/" (home) and "/projects".
  // Only show the page header on the projects listing route.
  const isOntologiesRoute = location.pathname === "/ontologies";
  const conceptClient = useConceptEditorClient();

  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  const scopes = useMemo<OntologyScope[]>(() => ["user", "organization"], []);
  // includeShared:false so the merged shared rows stay out of the "My Ontologies"
  // tab — they belong in the new Shared tab below. The picker used in the
  // editor still gets the merged list via its own useProjects() instance.
  const {
    projects,
    isLoading: isOntologiesLoading,
    isCopying,
    loadOntologies: refetchOntologies,
    renameOntology,
    copyOntology,
  } = useOntologies(scopes, { includeShared: false });
  // Drive the Shared tab visibility + count from the inbox. The fetch is
  // deduped by React Query (SharedProjectsTab calls the same hook), so this
  // adds no extra request.
  const { entries: shareInboxEntries } = useShareInbox();
  const sharedCount = shareInboxEntries.length;
  const {
    templates,
    isLoading: isTemplatesLoading,
    loadTemplates: refetchTemplates,
  } = useTemplates();

  const [activeContentTab, setActiveContentTab] = useState("projects");
  const [openingOntologyId, setOpeningOntologyId] = useState<string | null>(null);
  const [usingTemplateId, setUsingTemplateId] = useState<string | null>(null);
  const [_isCreatingOntology, setIsCreatingOntology] = useState(false);
  const [isDeletingOntology, setIsDeletingOntology] = useState(false);
  const [isUpdatingOntology, setIsUpdatingOntology] = useState(false);
  const [isImportingOntology, setIsImportingOntology] = useState(false);
  const [isCreatingFromContext, setIsCreatingFromContext] = useState(false);
  const [loadingStep, setLoadingStep] = useState(0);

  const loadingSteps = baseLoadingSteps;

  const [failedDatasources, setFailedDatasources] = useState<FailedDatasource[]>([]);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [editingOntology, setEditingOntology] = useState<{
    id: string;
    name: string;
    description: string;
    scope: OntologyScope;
  } | null>(null);

  const canEditOntologies = usePermissionsStore((state) => state.canEdit("can_edit_projects"));
  const canSeeTemplates = usePermissionsStore((state) => state.canSee("can_see_templates"));

  const isLoading =
    isOntologiesLoading ||
    isTemplatesLoading ||
    isDeletingOntology ||
    isCopying ||
    isUpdatingOntology ||
    isImportingOntology;

  const handleRefreshOntologies = () => {
    refetchOntologies(true);
    refetchTemplates(true);
  };

  const headerActions = isOntologiesRoute ? (
    <OntologiesListHeaderActions
      isLoading={isLoading}
      canEditOntologies={canEditOntologies}
      onRefresh={handleRefreshOntologies}
      onNewOntology={() => setShowCreateDialog(true)}
    />
  ) : undefined;

  // Pick a sensible default tab once data has loaded: owned projects first,
  // then shared (so recipients with no own projects don't land on Templates),
  // then templates as the last fallback.
  useEffect(() => {
    if (isOntologiesLoading) return;
    if (projects.length > 0) {
      setActiveContentTab("projects");
      return;
    }
    if (sharedCount > 0) {
      setActiveContentTab("shared");
      return;
    }
    setActiveContentTab(canSeeTemplates ? "templates" : "projects");
  }, [projects.length, sharedCount, isOntologiesLoading, canSeeTemplates]);

  // Reload when the AI assistant creates a project
  const ontologiesRevision = useCodeAssistantStore((s) => s.ontologiesRevision);
  useEffect(() => {
    if (ontologiesRevision > 0) refetchOntologies(true);
  }, [ontologiesRevision, refetchOntologies]);

  // Loading steps for template/context creation
  useEffect(() => {
    if (!isCreatingFromContext) {
      setLoadingStep(0);
      return;
    }
    setLoadingStep(0);
    const stepDelays = [3000, 4000, 5000];
    const timers: ReturnType<typeof setTimeout>[] = [];
    stepDelays.forEach((delay, i) => {
      timers.push(setTimeout(() => setLoadingStep(i + 1), delay));
    });
    return () => timers.forEach((t) => clearTimeout(t));
  }, [isCreatingFromContext]);

  const handleOpenOntology = useCallback(
    async (ontologyId: string, _ontologyName: string) => {
      try {
        setOpeningOntologyId(ontologyId);
        const storedScope = sessionStorage.getItem("currentOntologyScope");
        const ontologyScope =
          storedScope === "user" || storedScope === "organization"
            ? (storedScope as OntologyScope)
            : "user";

        const [ontologyData, conceptCells, concepts] = await Promise.all([
          OntologyService.loadOntology(ontologyId, ontologyScope),
          conceptClient.loadConcepts().catch(() => ({ status: "error", data: [] })),
          ConceptService.listConcepts(ontologyId, ontologyScope).catch(() => []),
        ]);

        setCurrentOntologyId(ontologyId);
        setCurrentOntologyScope(ontologyScope);

        if (conceptCells && conceptCells.status === "success" && Array.isArray(conceptCells.data)) {
          sessionStorage.setItem("ontologyConceptCells", JSON.stringify(conceptCells.data));
        } else {
          sessionStorage.removeItem("ontologyConceptCells");
        }

        if (concepts && concepts.length > 0) {
          useSchemaStore.getState().setSchemaFromConcepts(concepts);
        } else {
          useSchemaStore.getState().clearSchemaSuggestions();
        }

        const editorUrl = generateEditorUrl(user, ontologyId);
        navigate(editorUrl, {
          state: {
            ontologyData,
            conceptCells,
            concepts,
            activeTab: "lineage",
          },
        });
      } catch (error) {
        console.error("Error opening ontology:", error);
      } finally {
        setOpeningOntologyId(null);
      }
    },
    [navigate, user, conceptClient],
  );

  const handleDeleteOntology = useCallback(
    async (_ontologyName: string) => {
      try {
        setIsDeletingOntology(true);
        await refetchOntologies(true);
      } catch (error) {
        console.error("Error refreshing ontology list:", error);
      } finally {
        setIsDeletingOntology(false);
      }
    },
    [refetchOntologies],
  );

  const handleUpdateOntology = useCallback(
    async (id: string, newName: string, newDescription: string) => {
      try {
        setIsUpdatingOntology(true);
        await renameOntology(id, newName, newDescription);
        await refetchOntologies(true);
        setShowEditDialog(false);
        setEditingOntology(null);
      } catch (error) {
        console.error("Error updating ontology:", error);
      } finally {
        setIsUpdatingOntology(false);
      }
    },
    [renameOntology, refetchOntologies],
  );

  const handleCopyOntology = useCallback(
    async (ontologyId: string, newOntologyName: string, targetScope: OntologyScope) => {
      try {
        await copyOntology(ontologyId, newOntologyName, targetScope);
      } catch (error) {
        console.error("Error copying ontology:", error);
      }
    },
    [copyOntology],
  );

  const handleOntologyImported = useCallback(async () => {
    try {
      setIsImportingOntology(true);
      await refetchOntologies(true);
    } catch (error) {
      console.error("Error refreshing after import:", error);
      throw error;
    } finally {
      setIsImportingOntology(false);
    }
  }, [refetchOntologies]);

  const handleCreateOntology = useCallback(
    async (name: string, description: string, scope: OntologyScope) => {
      try {
        setIsCreatingOntology(true);
        globalThis.cachedOntologyCode = "";
        sessionStorage.removeItem("ontologyConceptCells");
        useSchemaStore.getState().clearSchemaSuggestions();
        sessionStorage.setItem("newOntologyScope", scope);

        const ontologyData = await OntologyService.createOntology(name, description, scope);
        if (!ontologyData?.id) throw new Error("Ontology creation failed: No ontology ID returned");

        setCurrentOntologyId(ontologyData.id);
        setCurrentOntologyScope(scope);
        await new Promise((resolve) => setTimeout(resolve, 50));
        await refetchOntologies(true);

        navigate(`/editor/${ontologyData.id}`, { state: { activeTab: "lineage" } });
        return ontologyData.id;
      } catch (error) {
        console.error("Error creating ontology:", error);
        throw error;
      } finally {
        setIsCreatingOntology(false);
      }
    },
    [navigate, refetchOntologies],
  );

  const handleUseTemplate = useCallback(
    async (templateId: string, templateName: string) => {
      setIsCreatingFromContext(true);
      setLoadingStep(0);
      try {
        setUsingTemplateId(templateId);
        const newOntology = await OntologyService.createFromTemplate(templateId, templateName);
        if (!newOntology?.id) throw new Error("Failed to create ontology from template");

        if (newOntology.failed_datasources?.length) {
          setFailedDatasources(newOntology.failed_datasources);
        }

        await refetchOntologies(true);
      } catch (error) {
        console.error("Error using template:", error);
      } finally {
        setUsingTemplateId(null);
        setIsCreatingFromContext(false);
        setLoadingStep(0);
      }
    },
    [refetchOntologies],
  );

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="projects"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-col flex-1 ${sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0"} overflow-hidden transition-all duration-200`}
      >
        {isOntologiesRoute && (
          <PageHeader
            title="Ontologies"
            subtitle={`${projects.length} ${projects.length === 1 ? "ontology" : "ontologies"}`}
            icon={FolderKanban}
            actions={headerActions}
          />
        )}

        {/* Tab bar */}
        <div className="flex border-b border-border px-6">
          {projects.length > 0 && (
            <button
              type="button"
              onClick={() => setActiveContentTab("projects")}
              className={`flex items-center px-4 py-2.5 text-sm font-medium transition-colors ${
                activeContentTab === "projects"
                  ? "border-b-2 border-primary text-primary"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              My Ontologies
            </button>
          )}

          {sharedCount > 0 && (
            <button
              type="button"
              onClick={() => setActiveContentTab("shared")}
              className={`flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium transition-colors ${
                activeContentTab === "shared"
                  ? "border-b-2 border-primary text-primary"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              Shared with me
              <span className="rounded-full bg-secondary px-1.5 py-0.5 text-[10px] font-semibold text-muted-foreground">
                {sharedCount}
              </span>
            </button>
          )}

          {canSeeTemplates &&
            (PROMETHEUX_CONFIG.SNOWFLAKE_MODE ? (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      onClick={() => setActiveContentTab("templates")}
                      className={`flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium transition-colors ${
                        activeContentTab === "templates"
                          ? "border-b-2 border-primary text-primary"
                          : "text-muted-foreground hover:text-foreground"
                      }`}
                    >
                      Templates <Info className="h-3.5 w-3.5" />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent className="max-w-sm p-3">
                    <p className="font-medium">External Access Required</p>
                    <p className="text-sm mt-1">
                      Template projects require external access integration.
                    </p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            ) : (
              <button
                type="button"
                onClick={() => setActiveContentTab("templates")}
                className={`flex items-center px-4 py-2.5 text-sm font-medium transition-colors ${
                  activeContentTab === "templates"
                    ? "border-b-2 border-primary text-primary"
                    : "text-muted-foreground hover:text-foreground"
                }`}
              >
                Templates
              </button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto min-h-0">
          <div className="px-8 py-6">
            {/* My Projects content */}
            {activeContentTab === "projects" &&
              projects.length > 0 &&
              (isLoading ? (
                <div className="flex items-center justify-center h-64">
                  <PrometheuxSpinner size={36} label="Loading ontologies..." />
                </div>
              ) : (
                <OntologyList
                  projects={projects}
                  onOpenOntology={handleOpenOntology}
                  onDeleteOntology={handleDeleteOntology}
                  onRenameOntology={canEditOntologies ? handleUpdateOntology : undefined}
                  onCopyOntology={canEditOntologies ? handleCopyOntology : undefined}
                  onRefreshOntologies={refetchOntologies}
                  onOntologyImported={handleOntologyImported}
                  openingOntologyId={openingOntologyId}
                />
              ))}

            {/* Shared with me content */}
            {activeContentTab === "shared" && (
              <SharedOntologiesTab
                onOpenOntology={handleOpenOntology}
                openingOntologyId={openingOntologyId}
              />
            )}

            {/* Templates content */}
            {canSeeTemplates &&
              activeContentTab === "templates" &&
              (isTemplatesLoading ? (
                <div className="flex items-center justify-center h-64">
                  <PrometheuxSpinner size={36} label="Loading templates..." />
                </div>
              ) : (
                <div className="space-y-6">
                  {projects.length === 0 && (
                    <div className="flex flex-col items-center pt-4 pb-2 text-center space-y-1">
                      <p className="text-lg font-semibold">
                        It looks like you don't have any projects yet.
                      </p>
                      <p className="text-sm text-muted-foreground">
                        Why not get started with one of our templates?
                      </p>
                    </div>
                  )}
                  <TemplateList
                    templates={templates}
                    onUseTemplate={handleUseTemplate}
                    usingTemplateId={usingTemplateId}
                  />
                </div>
              ))}
          </div>
        </div>
      </div>

      <CreateOntologyDialog
        isOpen={showCreateDialog}
        onClose={() => setShowCreateDialog(false)}
        onCreateOntology={handleCreateOntology}
        onOntologyImported={handleOntologyImported}
        existingOntologies={projects}
      />

      {editingOntology && (
        <EditOntologyDialog
          isOpen={showEditDialog}
          onClose={() => {
            setShowEditDialog(false);
            setEditingOntology(null);
          }}
          onUpdateOntology={handleUpdateOntology}
          onDeleteOntology={handleDeleteOntology}
          currentName={editingOntology.name}
          currentDescription={editingOntology.description}
          ontologyId={editingOntology.id}
          ontologyScope={editingOntology.scope}
        />
      )}

      {isCreatingFromContext && (
        <OntologyCreationLoader
          title="Creating Ontology"
          steps={loadingSteps}
          currentStep={loadingStep}
        />
      )}

      <FailedDatasourcesDialog
        failedDatasources={failedDatasources}
        onClose={() => setFailedDatasources([])}
      />
    </div>
  );
};

export default OntologiesListPage;
