import { create } from "zustand";
import { persist } from "zustand/middleware";

/**
 * User-level UI preferences, persisted locally (localStorage) via the persist
 * middleware, mirroring `themeStore`. Consumers only ever read/write through
 * this store — persistence is an internal detail. A future backend mirror can
 * be added without touching consumers: add a `hydrateFromServer` action and a
 * debounced push inside the setters.
 */

export type DefaultCellView = "code" | "description";

interface PreferencesState {
  /** Which view a concept cell opens on. Enforced on every cell mount. */
  defaultCellView: DefaultCellView;
  /** Whether code editors wrap long lines by default. */
  wrapCodeByDefault: boolean;
  /**
   * Explicit expand/collapse choices for context sidebar vaults, keyed by
   * `vaultKey`. Only vaults the user has actually toggled appear here, so each
   * vault keeps its own default until then.
   */
  vaultExpanded: Record<string, boolean>;
  setDefaultCellView: (view: DefaultCellView) => void;
  setWrapCodeByDefault: (enabled: boolean) => void;
  setVaultExpanded: (key: string, expanded: boolean) => void;
}

const STORAGE_KEY = "prometheux:preferences";

export const usePreferencesStore = create<PreferencesState>()(
  persist(
    (set) => ({
      defaultCellView: "code",
      wrapCodeByDefault: false,
      vaultExpanded: {},
      setDefaultCellView: (view) => set({ defaultCellView: view }),
      setWrapCodeByDefault: (enabled) => set({ wrapCodeByDefault: enabled }),
      setVaultExpanded: (key, expanded) =>
        set((state) => ({ vaultExpanded: { ...state.vaultExpanded, [key]: expanded } })),
    }),
    { name: STORAGE_KEY },
  ),
);
