import { type FormEvent, useState } from "react";
import type { MfaEnrollment } from "@/features/auth/hooks/useMfa";
import { RecoveryCodesDisplay } from "@/features/settings/components/users/profile/security/RecoveryCodesDisplay";
import type { UseMfaEnrollmentReturn } from "@/features/settings/components/users/profile/security/useMfaEnrollment";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";

interface MfaEnrollmentWizardProps {
  enrollment: UseMfaEnrollmentReturn;
}

export const MfaEnrollmentWizard = ({ enrollment }: MfaEnrollmentWizardProps) => {
  const {
    step,
    enrollment: factor,
    recoveryCodes,
    isBusy,
    errorMessage,
    verifyCode,
    cancel,
    finishRecoveryStep,
  } = enrollment;

  if (step === "idle") return null;

  if (step === "recovery") {
    return <RecoveryCodesDisplay codes={recoveryCodes} onDone={finishRecoveryStep} />;
  }

  if (!factor) return null;

  return (
    <div className="space-y-6">
      <EnrollmentScanStep factor={factor} />
      <EnrollmentVerifyStep
        isBusy={isBusy}
        errorMessage={errorMessage}
        onVerify={verifyCode}
        onCancel={cancel}
      />
    </div>
  );
};

interface EnrollmentScanStepProps {
  factor: MfaEnrollment;
}

const EnrollmentScanStep = ({ factor }: EnrollmentScanStepProps) => {
  const [showSecret, setShowSecret] = useState(false);

  return (
    <div className="space-y-4">
      <div>
        <h4 className="text-sm font-medium mb-1">1. Scan this QR code</h4>
        <p className="text-sm text-muted-foreground">
          Use Google Authenticator, 1Password, Authy, or any TOTP-compatible app.
        </p>
      </div>

      <div className="flex justify-center">
        <div className="bg-white p-4 rounded-lg border border-border">
          <img
            src={factor.qrCode}
            alt="Scan this QR code with your authenticator app"
            className="w-48 h-48"
          />
        </div>
      </div>

      <div className="text-center">
        <button
          type="button"
          onClick={() => setShowSecret((prev) => !prev)}
          className="text-sm text-primary hover:underline"
        >
          {showSecret ? "Hide" : "Can't scan? Enter the code manually"}
        </button>
        {showSecret && (
          <p className="mt-2 font-mono text-sm break-all bg-muted px-3 py-2 rounded select-all">
            {factor.secret}
          </p>
        )}
      </div>
    </div>
  );
};

interface EnrollmentVerifyStepProps {
  isBusy: boolean;
  errorMessage: string | null;
  onVerify: (code: string) => Promise<void>;
  onCancel: () => Promise<void>;
}

const VERIFY_CODE_LENGTH = 6;

const EnrollmentVerifyStep = ({
  isBusy,
  errorMessage,
  onVerify,
  onCancel,
}: EnrollmentVerifyStepProps) => {
  const [code, setCode] = useState("");

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault();
    if (code.length !== VERIFY_CODE_LENGTH) return;
    await onVerify(code);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-3">
      <div>
        <h4 className="text-sm font-medium mb-1">2. Enter the 6-digit code</h4>
        <p className="text-sm text-muted-foreground">
          Paste the code currently shown in your authenticator app.
        </p>
      </div>

      <Input
        autoFocus
        inputMode="numeric"
        autoComplete="one-time-code"
        placeholder="123456"
        value={code}
        onChange={(event) => setCode(event.target.value.replace(/\D/g, ""))}
        maxLength={VERIFY_CODE_LENGTH}
        disabled={isBusy}
        className="text-center tracking-widest text-lg"
      />

      {errorMessage && <p className="text-sm text-destructive">{errorMessage}</p>}

      <div className="flex gap-2">
        <Button
          type="submit"
          disabled={isBusy || code.length !== VERIFY_CODE_LENGTH}
          className="flex-1"
        >
          {isBusy ? "Verifying…" : "Verify and enable"}
        </Button>
        <Button type="button" variant="outline" onClick={onCancel} disabled={isBusy}>
          Cancel
        </Button>
      </div>
    </form>
  );
};
