import { ServerCog } from "lucide-react";
import type { SparkExecutor } from "../types/engineMonitor.types";
import { formatBytes } from "../utils/engineMonitor.utils";

interface EngineMonitorExecutorsProps {
  executors: SparkExecutor[];
}

const EngineMonitorExecutors: React.FC<EngineMonitorExecutorsProps> = ({ executors }) => {
  if (executors.length === 0) {
    return (
      <div className="p-3">
        <div className="flex flex-col items-center justify-center gap-2 rounded-lg border border-dashed border-border bg-muted/30 p-8 text-center">
          <ServerCog className="h-8 w-8 text-muted-foreground/50" />
          <div className="text-sm font-medium text-foreground">No executors registered</div>
          <div className="text-xs text-muted-foreground">
            Workers will appear here when the cluster allocates them.
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-3">
      <div className="rounded-lg border border-border bg-card overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-xs">
            <thead>
              <tr className="border-b border-border bg-muted/40">
                <th className="w-20 text-left px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  ID
                </th>
                <th className="text-left px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Host:Port
                </th>
                <th className="w-20 text-right px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  RDD
                </th>
                <th className="w-28 text-right px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Memory
                </th>
                <th className="w-28 text-right px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Disk
                </th>
                <th className="w-16 text-right px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Cores
                </th>
                <th className="w-20 text-right px-3 py-2 font-medium text-muted-foreground uppercase tracking-wide text-[10px]">
                  Active
                </th>
              </tr>
            </thead>
            <tbody>
              {executors.map((exec, idx) => {
                const rowBg = idx % 2 === 0 ? "bg-transparent" : "bg-muted/20";
                const isActive = (exec.activeTasks ?? 0) > 0;
                return (
                  <tr
                    key={exec.id}
                    className={`${rowBg} border-b border-border/50 last:border-0 hover:bg-muted/50 transition-colors`}
                  >
                    <td className="px-3 py-2">
                      <span className="inline-flex items-center gap-1.5">
                        <span
                          className={`inline-block h-1.5 w-1.5 rounded-full ${
                            isActive ? "bg-amber-500" : "bg-muted-foreground/40"
                          }`}
                        />
                        <span className="inline-block rounded bg-muted px-1.5 py-0.5 font-mono text-[11px] text-foreground">
                          {exec.id}
                        </span>
                      </span>
                    </td>
                    <td
                      className="px-3 py-2 font-mono text-[11px] text-foreground truncate"
                      title={exec.hostPort ?? ""}
                    >
                      {exec.hostPort ?? "—"}
                    </td>
                    <td className="px-3 py-2 text-right tabular-nums text-foreground">
                      {exec.rddBlocks ?? 0}
                    </td>
                    <td className="px-3 py-2 text-right tabular-nums text-foreground">
                      {formatBytes(exec.memoryUsed)}
                    </td>
                    <td className="px-3 py-2 text-right tabular-nums text-foreground">
                      {formatBytes(exec.diskUsed)}
                    </td>
                    <td className="px-3 py-2 text-right tabular-nums text-foreground">
                      {exec.totalCores ?? 0}
                    </td>
                    <td className="px-3 py-2 text-right">
                      <span
                        className={`tabular-nums ${
                          isActive
                            ? "font-semibold text-amber-600 dark:text-amber-400"
                            : "text-muted-foreground/70"
                        }`}
                      >
                        {exec.activeTasks ?? 0}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default EngineMonitorExecutors;
