import { useEffect } from "react";
import { useEngineMonitorStore } from "../store/engineMonitorStore";
import type { EngineMonitorSnapshot } from "../types/engineMonitor.types";

interface UseEngineMonitorReturn extends EngineMonitorSnapshot {
  refreshNow: () => Promise<void>;
  triggerGc: () => Promise<boolean>;
}

export function useEngineMonitor(): UseEngineMonitorReturn {
  const status = useEngineMonitorStore((s) => s.status);
  const jobs = useEngineMonitorStore((s) => s.jobs);
  const executors = useEngineMonitorStore((s) => s.executors);
  const applications = useEngineMonitorStore((s) => s.applications);
  const health = useEngineMonitorStore((s) => s.health);
  const cpu = useEngineMonitorStore((s) => s.cpu);
  const cpuCount = useEngineMonitorStore((s) => s.cpuCount);
  const memoryUsed = useEngineMonitorStore((s) => s.memoryUsed);
  const memoryMax = useEngineMonitorStore((s) => s.memoryMax);
  const samples = useEngineMonitorStore((s) => s.samples);
  const isTriggeringGc = useEngineMonitorStore((s) => s.isTriggeringGc);
  const gcLastTriggeredAt = useEngineMonitorStore((s) => s.gcLastTriggeredAt);
  const isLoading = useEngineMonitorStore((s) => s.isLoading);
  const lastUpdatedAt = useEngineMonitorStore((s) => s.lastUpdatedAt);
  const error = useEngineMonitorStore((s) => s.error);
  const subscribe = useEngineMonitorStore((s) => s.subscribe);
  const unsubscribe = useEngineMonitorStore((s) => s.unsubscribe);
  const refreshNow = useEngineMonitorStore((s) => s.refreshNow);
  const triggerGc = useEngineMonitorStore((s) => s.triggerGc);

  useEffect(() => {
    subscribe();
    return () => {
      unsubscribe();
    };
  }, [subscribe, unsubscribe]);

  return {
    status,
    jobs,
    executors,
    applications,
    runtime: {
      health,
      cpu,
      cpuCount,
      memoryUsed,
      memoryMax,
      samples,
      isTriggeringGc,
      gcLastTriggeredAt,
    },
    isLoading,
    lastUpdatedAt,
    error,
    refreshNow,
    triggerGc,
  };
}
