import {
  Background,
  Controls,
  type Node as FlowNode,
  ReactFlow,
  ReactFlowProvider,
  useEdgesState,
  useNodesState,
  useReactFlow,
} from "@xyflow/react";
import { useCallback, useEffect, useMemo } from "react";
import "@xyflow/react/dist/style.css";

import type { ContextEdge, ContextNote } from "../types";
import { ContextConceptNode, ContextNoteNode } from "./ContextFlowNodes";
import { buildContextFlow } from "./flowGraph";

const nodeTypes = {
  contextConcept: ContextConceptNode,
  contextNote: ContextNoteNode,
};

// Same canvas surface as the lineage view (LineageView's Background config).
const canvasStyle = { backgroundColor: "hsl(var(--flow-bg, var(--background)))" };

interface ConceptContextCanvasProps {
  conceptKey: string;
  conceptName: string;
  attachedNotes: ContextNote[];
  allEdges: ContextEdge[];
  onOpenNote: (noteId: string) => void;
  /** Bump to re-fit the view — e.g. when the note editor opens/closes and
   *  the canvas gets a different width. */
  refitKey?: string | number;
}

function ConceptContextCanvasInner({
  conceptKey,
  conceptName,
  attachedNotes,
  allEdges,
  onOpenNote,
  refitKey,
}: ConceptContextCanvasProps) {
  const flow = useMemo(
    () => buildContextFlow(conceptKey, conceptName, attachedNotes, allEdges),
    [conceptKey, conceptName, attachedNotes, allEdges],
  );

  const [nodes, setNodes, onNodesChange] = useNodesState<FlowNode>([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState(flow.edges);
  const { fitView } = useReactFlow();

  useEffect(() => {
    setNodes(flow.nodes);
    setEdges(flow.edges);
  }, [flow, setNodes, setEdges]);

  // Re-fit after the container resizes (editor pane opening/closing) or the
  // graph changes. The delay lets the CSS width settle first.
  useEffect(() => {
    const timer = setTimeout(() => {
      fitView({ padding: 0.25, maxZoom: 1, duration: 300 });
    }, 120);
    return () => clearTimeout(timer);
  }, [refitKey, flow, fitView]);

  const handleNodeClick = useCallback(
    (_event: React.MouseEvent, node: FlowNode) => {
      if (node.type === "contextNote") onOpenNote(node.id);
    },
    [onOpenNote],
  );

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      nodeTypes={nodeTypes}
      onNodesChange={onNodesChange}
      onEdgesChange={onEdgesChange}
      onNodeClick={handleNodeClick}
      nodesConnectable={false}
      deleteKeyCode={null}
      fitView
      fitViewOptions={{ padding: 0.25, maxZoom: 1 }}
      minZoom={0.3}
      proOptions={{ hideAttribution: true }}
      style={canvasStyle}
    >
      <Background color="hsl(var(--border))" gap={28} size={0.8} />
      <Controls showInteractive={false} position="bottom-right" />
    </ReactFlow>
  );
}

/** Local context graph for one concept, drawn in the lineage canvas style:
 *  white rounded cards, curved arrow edges, dotted background. */
export function ConceptContextCanvas(props: ConceptContextCanvasProps) {
  if (props.attachedNotes.length === 0) {
    return (
      <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
        No context attached to this concept yet — attach a note or create one.
      </div>
    );
  }

  return (
    <div className="h-full w-full overflow-hidden rounded-md border border-border">
      <ReactFlowProvider>
        <ConceptContextCanvasInner {...props} />
      </ReactFlowProvider>
    </div>
  );
}
