/**
 * Persisted UI state for the Notes page. Keys are typed constants per the
 * project storage rules (state-management.md).
 */

const STORAGE_KEYS = {
  FORMERLY_PINNED_NOTICE_DISMISSED: "prometheux:notes:formerlyPinnedNoticeDismissed",
  EDITOR_MODE: "prometheux:notes:editorMode",
} as const;

export type NoteEditorMode = "edit" | "preview";

export const notesPreferences = {
  /** Last edit/preview choice — carried across note navigation and sessions. */
  getEditorMode(): NoteEditorMode {
    try {
      const raw = localStorage.getItem(STORAGE_KEYS.EDITOR_MODE);
      return raw === "preview" ? "preview" : "edit";
    } catch (error) {
      console.error("Failed to read editor mode from storage:", error);
      return "edit";
    }
  },
  setEditorMode(mode: NoteEditorMode): void {
    try {
      localStorage.setItem(STORAGE_KEYS.EDITOR_MODE, mode);
    } catch (error) {
      console.error("Failed to persist editor mode:", error);
    }
  },
  isPinnedNoticeDismissed(): boolean {
    try {
      return localStorage.getItem(STORAGE_KEYS.FORMERLY_PINNED_NOTICE_DISMISSED) === "true";
    } catch (error) {
      console.error("Failed to read pinned-notice flag from storage:", error);
      return true;
    }
  },
  dismissPinnedNotice(): void {
    try {
      localStorage.setItem(STORAGE_KEYS.FORMERLY_PINNED_NOTICE_DISMISSED, "true");
    } catch (error) {
      console.error("Failed to persist pinned-notice flag:", error);
    }
  },
};
