import { useQuery } from "@tanstack/react-query";
import { OntologyDocumentApi } from "./api";
import type { OntologyDocument } from "./types";

interface UseOntologyDocumentReturn {
  document: OntologyDocument | undefined;
  isLoading: boolean;
  error: Error | null;
  refetch: () => void;
}

export function useOntologyDocument(
  ontologyId: string | null,
  scope: string = "user",
  generateOntologySchema: boolean = false,
): UseOntologyDocumentReturn {
  const query = useQuery({
    queryKey: ["ontology-document", ontologyId, scope],
    queryFn: () => OntologyDocumentApi.get(ontologyId as string, scope, { generateOntologySchema }),
    enabled: Boolean(ontologyId),
    staleTime: 30_000,
  });

  return {
    document: query.data,
    isLoading: query.isLoading,
    error: (query.error as Error | null) ?? null,
    refetch: query.refetch,
  };
}
