import { useEffect, useRef } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import { toast } from "sonner";

import { ContextNoteApi } from "../../api";
import type { ContextNote } from "../../types";

interface UseNoteUrlSyncArgs {
  /** The note id the current selection should show in the URL (documents
   *  use their representative chunk id); null when nothing is open. */
  urlNoteId: string | null;
  /** Opens a note (documents route to the document view internally). */
  openNote: (note: ContextNote) => void;
  /** When false, the hook is inert — no deep-link fetch and no URL rewriting.
   *  The in-project Context tab lives under /editor/:id and must not touch the
   *  /context route. Defaults to true (the global Context page). */
  enabled?: boolean;
}

/**
 * Two-way binding between the selection and /context/:noteId.
 *
 * On load with a :noteId param, the note is fetched by id (it can live in
 * any vault) and opened. Afterwards every selection change is reflected
 * in the URL (history replace — Back leaves the page, not each note).
 */
export function useNoteUrlSync({ urlNoteId, openNote, enabled = true }: UseNoteUrlSyncArgs): void {
  const { noteId: paramNoteId } = useParams<{ noteId: string }>();
  const navigate = useNavigate();
  const location = useLocation();

  // The initial deep link is consumed exactly once; until then the
  // URL-sync direction stays off so it can't wipe the param.
  const pendingDeepLinkRef = useRef<string | null>(enabled ? (paramNoteId ?? null) : null);
  const openNoteRef = useRef(openNote);
  openNoteRef.current = openNote;

  useEffect(() => {
    if (!enabled) return;
    const pending = pendingDeepLinkRef.current;
    if (!pending) return;
    let cancelled = false;

    ContextNoteApi.get(pending)
      .then((note) => {
        if (!cancelled) openNoteRef.current(note);
      })
      .catch(() => {
        if (!cancelled) toast.error("That note no longer exists.");
      })
      .finally(() => {
        if (!cancelled) pendingDeepLinkRef.current = null;
      });

    return () => {
      cancelled = true;
    };
  }, [enabled]);

  useEffect(() => {
    if (!enabled) return;
    if (pendingDeepLinkRef.current) return;
    const target = urlNoteId ? `/context/${urlNoteId}` : "/context";
    if (location.pathname !== target) navigate(target, { replace: true });
  }, [enabled, urlNoteId, location.pathname, navigate]);
}
