import { useCallback, useMemo, useRef, useState } from "react";

import type { ConceptCell } from "@/features/concept-editor/types";

interface UseCellRenameOptions {
  /** The name currently persisted on the cell. */
  currentName: string | undefined;
  /** Called with the normalized name, only when it actually differs. */
  onCommit: (name: string) => void;
}

/**
 * Rename-in-place state for a cell header: the draft value, whether the widget
 * is in edit mode, and the input ref to focus. Naming policy lives here — a name
 * is trimmed and lowercased, and an empty or unchanged one is discarded.
 *
 * Pair with `CellRenameControl` (or `CellPredicatePicker`) for the presentation.
 */
export function useCellRename({ currentName, onCommit }: UseCellRenameOptions) {
  const [isRenaming, setIsRenaming] = useState(false);
  const [renameValue, setRenameValue] = useState(currentName || "");
  const inputRef = useRef<HTMLInputElement>(null);

  const start = useCallback(() => {
    setRenameValue(currentName || "");
    setIsRenaming(true);
    // The input replaces the label in this same commit, so focus on the next tick.
    setTimeout(() => inputRef.current?.focus(), 0);
  }, [currentName]);

  const cancel = useCallback(() => {
    setIsRenaming(false);
    setRenameValue(currentName || "");
  }, [currentName]);

  const confirm = useCallback(() => {
    const trimmed = renameValue.trim().toLowerCase();
    setIsRenaming(false);
    if (trimmed && trimmed !== currentName) onCommit(trimmed);
  }, [renameValue, currentName, onCommit]);

  // Memoized so callers can pass the whole thing as one dependency.
  return useMemo(
    () => ({ isRenaming, renameValue, setRenameValue, inputRef, start, cancel, confirm }),
    [isRenaming, renameValue, start, cancel, confirm],
  );
}

interface UseConceptRenameCommitOptions {
  cell: ConceptCell;
  setCells: React.Dispatch<React.SetStateAction<ConceptCell[]>>;
  onRenameConcept?: (cellId: string, newName: string) => void;
  onOutputPredicateChange?: (cellId: string, outputPredicate: string) => void;
}

/**
 * The standard commit policy for `useCellRename`: a cell that exists in the
 * backend goes through the rename endpoint (which has to move the stored
 * concept), while one that was never saved is just relabelled locally.
 */
export function useConceptRenameCommit({
  cell,
  setCells,
  onRenameConcept,
  onOutputPredicateChange,
}: UseConceptRenameCommitOptions) {
  const { id, cellBackendId } = cell;

  return useCallback(
    (name: string) => {
      if (cellBackendId && onRenameConcept) {
        onRenameConcept(id, name);
        return;
      }
      setCells((prev) =>
        prev.map((c) => (c.id === id ? { ...c, outputPredicate: name, isModified: true } : c)),
      );
      onOutputPredicateChange?.(id, name);
    },
    [id, cellBackendId, setCells, onRenameConcept, onOutputPredicateChange],
  );
}
