import { ArrowLeft, type LucideIcon } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { IconChip } from "@/shared/components/ui/IconChip";

interface SettingsSectionHeaderProps {
  icon: LucideIcon;
  title: string;
  description: string;
  onBack: () => void;
}

// Header for an individual settings section: a subtle back link, an icon chip
// paired with a right-sized title, and a muted one-line description underneath —
// a clear title/subtitle hierarchy rather than an oversized icon + heading.
export function SettingsSectionHeader({
  icon,
  title,
  description,
  onBack,
}: SettingsSectionHeaderProps) {
  return (
    <header className="mx-6 mb-8 mt-6">
      <Button
        variant="ghost"
        size="sm"
        onClick={onBack}
        className="mb-5 h-auto p-0 font-normal text-muted-foreground hover:bg-transparent hover:text-foreground"
      >
        <ArrowLeft className="mr-2 h-4 w-4" />
        Back to Settings
      </Button>
      <div className="flex items-center gap-3">
        <IconChip icon={icon} size="lg" />
        <h1 className="text-2xl font-semibold tracking-tight">{title}</h1>
      </div>
      <p className="mt-2 max-w-2xl text-sm text-muted-foreground">{description}</p>
    </header>
  );
}
