import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import {
  type CreateTeamInput,
  createTeam,
  deleteTeam,
  leaveTeam,
  listMyTeams,
  transferOwnership,
} from "../api";
import type { Team, TeamError, TeamMembershipRow } from "../types";

// Shared key so mutations in other hooks (invite accept, role change) can
// invalidate my teams list too — anything that could change a caller's team
// membership should hit this.
export const MY_TEAMS_KEY = ["teams", "mine"] as const;
const myTeamsKey = (userId: string) => [...MY_TEAMS_KEY, userId] as const;

interface TransferInput {
  teamId: string;
  newOwnerUserId: string;
}

interface UseMyTeamsReturn {
  teams: TeamMembershipRow[];
  isLoading: boolean;
  isFetching: boolean;
  error: TeamError | null;
  refresh: () => Promise<unknown>;

  create: (input: CreateTeamInput) => Promise<Team>;
  isCreating: boolean;

  leave: (teamId: string) => Promise<{ team_id: string; status: "left" }>;
  isLeaving: boolean;

  deleteTeam: (teamId: string) => Promise<{ team_id: string; status: "deleted" }>;
  isDeletingTeam: boolean;
  deletingTeamId: string | null;

  transfer: (input: TransferInput) => Promise<{ team_id: string; new_owner_user_id: string }>;
  isTransferring: boolean;
}

// GET /teams + all mutations that only affect the caller's team list.
// Invitations-side mutations live on useTeamInvitations, member-side mutations
// live on useTeamMembers — but every one of those also invalidates
// MY_TEAMS_KEY to keep this in sync.
export function useMyTeams(): UseMyTeamsReturn {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";

  const query = useQuery<TeamMembershipRow[], TeamError>({
    queryKey: myTeamsKey(userId),
    queryFn: () => listMyTeams(supabaseToken),
    enabled: Boolean(userId && supabaseToken),
    // Same manual-refresh model as sharing: refetch on mount + after own
    // mutations, no polling, no window-focus refetch.
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const createMutation = useMutation<Team, TeamError, CreateTeamInput>({
    mutationFn: (input) => createTeam(input, supabaseToken),
    onSuccess: (newTeam) => {
      // Optimistically push the new team into the my-teams cache so a user
      // clicking the just-created card lands on a resolvable detail page
      // BEFORE the invalidate → refetch cycle completes. Without this, there's
      // a race where the card renders (from a stale non-empty cache) but the
      // detail page's teams.find() returns undefined and shows "not found".
      // The caller of create() is by definition the owner of the new team.
      // Under the owner-funded plan the owner is auto-seated on creation, so
      // seat_granted starts as true and seats_used at 1 (matching a minimal
      // 1-seat plan). The refetch corrects both once the backend responds.
      queryClient.setQueryData<TeamMembershipRow[]>(myTeamsKey(userId), (prev) => {
        const base = prev ?? [];
        if (base.some((t) => t.id === newTeam.id)) return base;
        const optimistic: TeamMembershipRow = {
          ...newTeam,
          role: "owner",
          seat_granted: true,
          seats_used: 1,
        };
        return [...base, optimistic];
      });
      queryClient.invalidateQueries({ queryKey: MY_TEAMS_KEY });
      // The onboarding suggestion depends on whether the caller has any team,
      // so a create flips its state — invalidate that query key too.
      queryClient.invalidateQueries({ queryKey: ["teams", "suggestion"] });
    },
  });

  const leaveMutation = useMutation<{ team_id: string; status: "left" }, TeamError, string>({
    mutationFn: (teamId) => leaveTeam(teamId, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: MY_TEAMS_KEY });
      queryClient.invalidateQueries({ queryKey: ["teams", "suggestion"] });
    },
  });

  const deleteMutation = useMutation<{ team_id: string; status: "deleted" }, TeamError, string>({
    mutationFn: (teamId) => deleteTeam(teamId, supabaseToken),
    onSuccess: (_result, teamId) => {
      // Same optimistic-cache trick as create, in reverse: strip the deleted
      // team from the my-teams cache immediately so the caller navigates back
      // to a consistent list without waiting on the refetch. Also drop the
      // roster cache for that team — nobody's coming back to it.
      queryClient.setQueryData<TeamMembershipRow[]>(myTeamsKey(userId), (prev) =>
        (prev ?? []).filter((t) => t.id !== teamId),
      );
      queryClient.invalidateQueries({ queryKey: MY_TEAMS_KEY });
      queryClient.invalidateQueries({ queryKey: ["teams", "suggestion"] });
      queryClient.removeQueries({ queryKey: ["teams", "members", teamId] });
    },
  });

  const transferMutation = useMutation<
    { team_id: string; new_owner_user_id: string },
    TeamError,
    TransferInput
  >({
    mutationFn: ({ teamId, newOwnerUserId }) =>
      transferOwnership(teamId, newOwnerUserId, supabaseToken),
    onSuccess: (_result, variables) => {
      // Both the caller's teams list (role flips owner → admin) and the roster
      // for that team need refetching.
      queryClient.invalidateQueries({ queryKey: MY_TEAMS_KEY });
      queryClient.invalidateQueries({ queryKey: ["teams", "members", variables.teamId] });
    },
  });

  return {
    teams: query.data ?? [],
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    refresh: query.refetch,

    create: createMutation.mutateAsync,
    isCreating: createMutation.isPending,

    leave: leaveMutation.mutateAsync,
    isLeaving: leaveMutation.isPending,

    deleteTeam: deleteMutation.mutateAsync,
    isDeletingTeam: deleteMutation.isPending,
    deletingTeamId: deleteMutation.isPending ? (deleteMutation.variables ?? null) : null,

    transfer: transferMutation.mutateAsync,
    isTransferring: transferMutation.isPending,
  };
}
