import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { shareOntology } from "../api";
import type { ShareError, ShareInput, ShareSummary } from "../types";
import { SHARE_OUTBOX_KEY } from "./useShareOutbox";

interface UseShareOntologyReturn {
  share: (input: ShareInput) => Promise<ShareSummary>;
  isSharing: boolean;
  error: ShareError | null;
  reset: () => void;
}

// Mutation hook for the sender-side "Share project" form. Pairs with useShareOutbox,
// whose `entries` list is invalidated on success so the Manage Shares panel updates.
export function useShareOntology(): UseShareOntologyReturn {
  const { session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;

  const mutation = useMutation<ShareSummary, ShareError, ShareInput>({
    mutationFn: (input) => shareOntology(input, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: SHARE_OUTBOX_KEY });
    },
  });

  return {
    share: mutation.mutateAsync,
    isSharing: mutation.isPending,
    error: mutation.error,
    reset: mutation.reset,
  };
}
