import { z } from "zod";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

/**
 * Client + runtime validation for the project execution-status endpoint.
 *
 * Lets a client returning to the lineage tab recover the live progress of an
 * in-flight run, or learn why the last run failed / was cancelled / was
 * interrupted. The backend persists an append-only run history; this reads the
 * latest run for the project.
 */

export type ExecutionOverallStatus =
  | "idle"
  | "running"
  | "success"
  | "error"
  | "cancelled"
  | "interrupted";

export type ExecutionConceptState = "running" | "success" | "error" | "skipped";

const conceptStatusSchema = z.object({
  status: z.enum(["running", "success", "error", "skipped"]).catch("running"),
  error: z.string().optional(),
  reason: z.string().optional(),
});

const snapshotSchema = z.object({
  status: z.enum(["idle", "running", "success", "error", "cancelled", "interrupted"]).catch("idle"),
  execution_id: z.string().optional().nullable(),
  target_concept: z.string().optional().nullable(),
  order: z.array(z.string()).catch([]),
  total: z.number().optional().nullable(),
  statuses: z.record(z.string(), conceptStatusSchema).catch({}),
  failure_reason: z.string().optional().nullable(),
  started_at: z.string().optional().nullable(),
  updated_at: z.string().optional().nullable(),
  finished_at: z.string().optional().nullable(),
  duration_ms: z.number().optional().nullable(),
});

const envelopeSchema = z.object({ data: snapshotSchema });

type RawSnapshot = z.infer<typeof snapshotSchema>;

// Batch endpoint: latest run per project, keyed by project_id. Only non-idle
// projects are present (an absent project is idle), so the payload stays small.
const batchEnvelopeSchema = z.object({ data: z.record(z.string(), snapshotSchema) });

export interface ExecutionStatusSnapshot {
  status: ExecutionOverallStatus;
  executionId: string | null;
  targetConcept: string | null;
  order: string[];
  total: number | null;
  statuses: Record<string, z.infer<typeof conceptStatusSchema>>;
  failureReason: string | null;
  startedAt: string | null;
  updatedAt: string | null;
  finishedAt: string | null;
  durationMs: number | null;
}

const TERMINAL_STATES: ReadonlySet<ExecutionOverallStatus> = new Set([
  "success",
  "error",
  "cancelled",
  "interrupted",
]);

export function isTerminalStatus(status: ExecutionOverallStatus): boolean {
  return TERMINAL_STATES.has(status);
}

/** Format a run duration (ms) as a short human string, e.g. "1m 23s" or "850ms". */
export function formatDuration(ms: number | null): string | null {
  if (ms === null || !Number.isFinite(ms) || ms < 0) return null;
  if (ms < 1000) return `${ms}ms`;
  const totalSeconds = Math.round(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  if (minutes === 0) return `${seconds}s`;
  return `${minutes}m ${seconds}s`;
}

function toSnapshot(data: RawSnapshot): ExecutionStatusSnapshot {
  return {
    status: data.status,
    executionId: data.execution_id ?? null,
    targetConcept: data.target_concept ?? null,
    order: data.order,
    total: data.total ?? null,
    statuses: data.statuses,
    failureReason: data.failure_reason ?? null,
    startedAt: data.started_at ?? null,
    updatedAt: data.updated_at ?? null,
    finishedAt: data.finished_at ?? null,
    durationMs: data.duration_ms ?? null,
  };
}

export async function fetchOntologyExecutionStatus(
  ontologyId: string,
  ontologyScope: string = "user",
): Promise<ExecutionStatusSnapshot> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/execution-status?scope=${ontologyScope}`;
  const raw = await HttpService.get(url, PROMETHEUX_CONFIG.AUTH_TOKEN);
  const { data } = envelopeSchema.parse(raw);
  return toSnapshot(data);
}

/**
 * Latest run per project across the given scopes, in a single request — so the
 * projects-list page can badge every card without fanning out one request per
 * project. Returns a map keyed by project_id; only non-idle projects are
 * present (callers treat an absent project as idle).
 */
export async function fetchOntologiesExecutionStatus(
  scopes: string[],
): Promise<Record<string, ExecutionStatusSnapshot>> {
  const scopeParam = (scopes.length > 0 ? scopes : ["user"]).join(",");
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/execution-statuses?scopes=${scopeParam}`;
  const raw = await HttpService.get(url, PROMETHEUX_CONFIG.AUTH_TOKEN);
  const { data } = batchEnvelopeSchema.parse(raw);
  const out: Record<string, ExecutionStatusSnapshot> = {};
  for (const [ontologyId, snapshot] of Object.entries(data)) {
    out[ontologyId] = toSnapshot(snapshot);
  }
  return out;
}
