import { type Change, diffLines } from "diff";
import type { SnapshotConcept } from "@/features/ontologies/api";

export type ConceptDiffStatus = "added" | "removed" | "changed";

export interface ConceptFieldDiff {
  field: keyof SnapshotConcept;
  label: string;
  changes: Change[];
}

export interface ChangedConcept {
  predicateName: string;
  before: SnapshotConcept;
  after: SnapshotConcept;
  fieldDiffs: ConceptFieldDiff[];
}

export interface ConceptSetDiff {
  added: SnapshotConcept[];
  removed: SnapshotConcept[];
  changed: ChangedConcept[];
}

export type DiffLineType = "add" | "remove" | "context";

export interface DiffLine {
  id: string;
  type: DiffLineType;
  text: string;
}

// The concept fields worth diffing, in display order, with human labels.
// predicate_name is the identity key and ordering metadata is intentionally omitted.
const DIFF_FIELDS: { field: keyof SnapshotConcept; label: string }[] = [
  { field: "definition", label: "Definition" },
  { field: "fields", label: "Fields" },
  { field: "bind_annotations", label: "Bind annotations" },
  { field: "model_annotation", label: "Model annotation" },
  { field: "post_annotations", label: "Post annotations" },
  { field: "mapping_annotations", label: "Mapping annotations" },
  { field: "param_annotations", label: "Param annotations" },
  { field: "ontology_schema_type", label: "Schema type" },
  { field: "concept_type", label: "Concept type" },
  { field: "description", label: "Description" },
];

const EMPTY_CONCEPT: SnapshotConcept = {
  predicate_name: "",
  fields: null,
  bind_annotations: null,
  model_annotation: null,
  definition: null,
  post_annotations: null,
  mapping_annotations: null,
  param_annotations: null,
  ontology_schema_type: null,
  concept_type: null,
  description: null,
  position: null,
  concept_group: null,
};

function normalizeFieldValue(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return String(value);
  }
}

export function diffConceptFields(
  before: SnapshotConcept,
  after: SnapshotConcept,
): ConceptFieldDiff[] {
  return DIFF_FIELDS.flatMap(({ field, label }) => {
    const beforeText = normalizeFieldValue(before[field]);
    const afterText = normalizeFieldValue(after[field]);
    if (beforeText === afterText) return [];
    return [{ field, label, changes: diffLines(beforeText, afterText) }];
  });
}

export function diffConceptSets(
  base: SnapshotConcept[],
  target: SnapshotConcept[],
): ConceptSetDiff {
  const baseMap = new Map(base.map((concept) => [concept.predicate_name, concept]));
  const targetMap = new Map(target.map((concept) => [concept.predicate_name, concept]));

  const added = target.filter((concept) => !baseMap.has(concept.predicate_name));
  const removed = base.filter((concept) => !targetMap.has(concept.predicate_name));

  const changed = target.flatMap<ChangedConcept>((after) => {
    const before = baseMap.get(after.predicate_name);
    if (!before) return [];
    const fieldDiffs = diffConceptFields(before, after);
    if (fieldDiffs.length === 0) return [];
    return [{ predicateName: after.predicate_name, before, after, fieldDiffs }];
  });

  return { added, removed, changed };
}

// For an added/removed concept there is no counterpart, so we diff against an
// empty concept to render every populated field as fully added/removed.
export function singleConceptFieldDiffs(
  concept: SnapshotConcept,
  status: "added" | "removed",
): ConceptFieldDiff[] {
  if (status === "added") return diffConceptFields(EMPTY_CONCEPT, concept);
  return diffConceptFields(concept, EMPTY_CONCEPT);
}

function lineType(change: Change): DiffLineType {
  if (change.added) return "add";
  if (change.removed) return "remove";
  return "context";
}

export function toDiffLines(changes: Change[]): DiffLine[] {
  let counter = 0;
  return changes.flatMap((change) => {
    const type = lineType(change);
    const lines = change.value.split("\n");
    // diffLines keeps a trailing newline, which yields a spurious empty final line.
    if (lines.length > 1 && lines[lines.length - 1] === "") lines.pop();
    return lines.map((text) => {
      counter += 1;
      return { id: `${type}-${counter}`, type, text };
    });
  });
}
