import type { ComponentPropsWithoutRef } from "react";
import ReactMarkdown, { type Components } from "react-markdown";
import remarkGfm from "remark-gfm";

const WIKILINK_HREF_PREFIX = "#wikilink=";

interface NoteMarkdownPreviewProps {
  text: string;
  onOpenWikilink: (title: string) => void;
}

/** Rewrite `[[Title]]` into markdown links the renderer can intercept. */
function rewriteWikilinks(text: string): string {
  return (text ?? "").replace(
    /\[\[([^\][\n]+?)\]\]/g,
    (_, title: string) => `[${title}](${WIKILINK_HREF_PREFIX}${encodeURIComponent(title.trim())})`,
  );
}

export function NoteMarkdownPreview({ text, onOpenWikilink }: NoteMarkdownPreviewProps) {
  const handleLinkClick = (
    event: React.MouseEvent<HTMLAnchorElement>,
    href: string | undefined,
  ) => {
    if (!href?.startsWith(WIKILINK_HREF_PREFIX)) return;
    event.preventDefault();
    onOpenWikilink(decodeURIComponent(href.slice(WIKILINK_HREF_PREFIX.length)));
  };

  const renderLink = ({ href, children, ...props }: ComponentPropsWithoutRef<"a">) => {
    const isWikilink = href?.startsWith(WIKILINK_HREF_PREFIX);
    return (
      <a
        href={href}
        onClick={(event) => handleLinkClick(event, href)}
        target={isWikilink ? undefined : "_blank"}
        rel={isWikilink ? undefined : "noreferrer"}
        className="cursor-pointer text-primary underline underline-offset-2 hover:text-primary/80"
        {...props}
      >
        {children}
      </a>
    );
  };

  const components: Components = {
    a: renderLink,
    h1: (props) => <h1 className="pb-1 text-xl font-bold text-foreground" {...props} />,
    h2: (props) => <h2 className="pb-1 text-lg font-semibold text-foreground" {...props} />,
    h3: (props) => <h3 className="pb-1 text-base font-semibold text-foreground" {...props} />,
    p: (props) => <p className="text-sm leading-relaxed text-foreground" {...props} />,
    ul: (props) => <ul className="list-disc space-y-1 pl-5 text-sm text-foreground" {...props} />,
    ol: (props) => (
      <ol className="list-decimal space-y-1 pl-5 text-sm text-foreground" {...props} />
    ),
    blockquote: (props) => (
      <blockquote
        className="border-l-2 border-border pl-3 text-sm italic text-muted-foreground"
        {...props}
      />
    ),
    code: (props) => (
      <code className="rounded bg-muted px-1 py-0.5 font-mono text-xs text-foreground" {...props} />
    ),
    pre: (props) => (
      <pre className="overflow-x-auto rounded-md bg-muted p-3 font-mono text-xs" {...props} />
    ),
  };

  return (
    <div className="space-y-3 p-4">
      <ReactMarkdown remarkPlugins={[remarkGfm]} components={components}>
        {rewriteWikilinks(text)}
      </ReactMarkdown>
    </div>
  );
}
