import { Loader2, RefreshCw } from "lucide-react";
import type React from "react";
import { useMemo, useState } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { useTeamsMembers } from "@/features/teams/hooks/useTeamsMembers";
import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";
import { useConceptRestrictions } from "../hooks/useConceptRestrictions";
import { useShareOutbox } from "../hooks/useShareOutbox";
import { type OutboxEntry, ShareError, type ShareRole, type ShareType } from "../types";
import { normalizeLevel } from "../utils/conceptAccess.utils";
import { partitionByLiveness } from "../utils/sharing.utils";
import RosterMemberSection, { type RosterSectionItem } from "./RosterMemberSection";
import ShareRow from "./ShareRow";
import TeamMemberShareRow from "./TeamMemberShareRow";

interface ManageSharesPanelProps {
  ontologyId: string;
  // Person/Team scope, owned by the parent dialog's shared selector.
  mode: ShareType;
}

const teamIdOf = (entry: OutboxEntry): string | null =>
  entry.recipient_team_id ?? entry.team_id ?? null;

const ManageSharesPanel: React.FC<ManageSharesPanelProps> = ({ ontologyId, mode }) => {
  const {
    entries,
    isLoading,
    isFetching,
    error,
    refresh,
    revoke,
    revokeTeam,
    isRevoking,
    updateRole,
    updateTeamRole,
    updatingShareId,
  } = useShareOutbox({ ontologyId });
  const [showHistory, setShowHistory] = useState(false);
  const [pendingRevokeShareId, setPendingRevokeShareId] = useState<string | null>(null);

  // The owner manages their own shares here, so the current user IS the owner —
  // they're excluded from the People list (they always have full access).
  const { user } = useAuth();
  const ownerSub = user?.id ?? "";
  const { restrictions } = useConceptRestrictions({ ontologyId });

  const { live, historical } = useMemo(() => partitionByLiveness(entries), [entries]);

  const teamShareIds = useMemo(
    () =>
      live
        .filter((e) => e.share_type === "team")
        .map(teamIdOf)
        .filter((id): id is string => Boolean(id)),
    [live],
  );
  const { members: teamMembers } = useTeamsMembers(teamShareIds);

  const personLive = live.filter((e) => e.share_type !== "team");
  const teamLive = live.filter((e) => e.share_type === "team");

  // Per-member ontology-level override (read_write → editor). A member with an
  // override keeps it regardless of the team's base role — this is why a member
  // bumped to editor must not fall back to the team's "viewer" base.
  const overrideBySub = useMemo(() => {
    const map = new Map<string, ShareRole>();
    for (const r of restrictions) {
      if (r.scope !== "ontology" || r.subject_type !== "user") continue;
      const sub = r.recipient_sub ?? r.subject_id;
      map.set(sub, normalizeLevel(r.level) === "read_write" ? "editor" : "viewer");
    }
    return map;
  }, [restrictions]);

  // People who only have access because they belong to a shared team — surfaced
  // in the People view with the team in parentheses, deduped against anyone who
  // also has a direct share (the direct row wins, since it's manageable) and the
  // owner (always full access). The role reflects the effective level: a
  // per-member override wins over the team's base role.
  const teamPeople = useMemo(() => {
    const teamMeta = new Map<string, { name: string; role: ShareRole }>();
    for (const e of teamLive) {
      const id = teamIdOf(e);
      if (id) teamMeta.set(id, { name: e.team_name ?? "Team", role: e.share_role });
    }
    const directSubs = new Set(personLive.map((e) => e.recipient_sub));
    return teamMembers
      .filter((m) => m.status === "active" && m.user_id !== ownerSub && !directSubs.has(m.user_id))
      .map((m) => {
        const teamBaseRole = teamMeta.get(m.teamId)?.role ?? "viewer";
        return {
          id: m.user_id,
          label: `${m.username}@${m.organization}`,
          teamName: teamMeta.get(m.teamId)?.name ?? "team",
          role: overrideBySub.get(m.user_id) ?? teamBaseRole,
        };
      });
  }, [teamLive, personLive, teamMembers, overrideBySub, ownerSub]);

  const handleRevoke = async (entry: OutboxEntry): Promise<void> => {
    setPendingRevokeShareId(entry.share_id);
    try {
      if (entry.share_type === "team") {
        await revokeTeam({ shareId: entry.share_id });
      } else {
        await revoke({ shareId: entry.share_id });
      }
      toast.success("Share revoked");
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to revoke share";
      toast.error(message);
    } finally {
      setPendingRevokeShareId(null);
    }
  };

  const handleRoleChange = async (entry: OutboxEntry, role: ShareRole): Promise<void> => {
    try {
      const input = { shareId: entry.share_id, shareRole: role };
      const result =
        entry.share_type === "team" ? await updateTeamRole(input) : await updateRole(input);
      if (result.changed) {
        toast.success(`Role updated to ${role}`);
      } else {
        toast(`Role already ${role}`, { description: "No changes applied." });
      }
    } catch (err) {
      if (err instanceof ShareError && err.apiStatus === "conflict") {
        toast.error("This share can't be updated — create a new share instead.", {
          description: err.message,
        });
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to update role";
      toast.error(message);
    }
  };

  const handleRefresh = (): void => {
    void refresh();
  };

  const handleToggleHistory = (): void => {
    setShowHistory((prev) => !prev);
  };

  const renderShareRow = (entry: OutboxEntry, greyed: boolean): React.ReactElement => (
    <ShareRow
      key={entry.share_id}
      entry={entry}
      greyed={greyed}
      isRevoking={isRevoking}
      pendingRevokeShareId={pendingRevokeShareId}
      onRevoke={handleRevoke}
      onRoleChange={handleRoleChange}
      updatingShareId={updatingShareId}
    />
  );

  const personItems: RosterSectionItem[] = [
    ...personLive.map((entry) => ({
      key: entry.share_id,
      searchText: `${entry.recipient_username}@${entry.recipient_organization}`.toLowerCase(),
      node: renderShareRow(entry, false),
    })),
    ...teamPeople.map((p) => ({
      key: `tm:${p.id}`,
      searchText: `${p.label} ${p.teamName}`.toLowerCase(),
      node: <TeamMemberShareRow label={p.label} teamName={p.teamName} role={p.role} />,
    })),
  ];

  const historyForView =
    mode === "team"
      ? historical.filter((e) => e.share_type === "team")
      : historical.filter((e) => e.share_type !== "team");
  const activeCount = mode === "team" ? teamLive.length : personItems.length;

  const isInitialLoading = isLoading && entries.length === 0;

  const renderActiveList = (): React.ReactElement => {
    if (isInitialLoading) {
      return (
        <div className="flex items-center gap-2 py-6 text-xs text-muted-foreground">
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
          Loading shares...
        </div>
      );
    }
    if (mode === "team") {
      if (teamLive.length === 0) {
        return (
          <p className="rounded-md border border-dashed border-border bg-muted/30 px-3 py-6 text-center text-xs text-muted-foreground">
            No teams have access to this ontology yet.
          </p>
        );
      }
      return (
        <div className="space-y-2">{teamLive.map((entry) => renderShareRow(entry, false))}</div>
      );
    }
    if (personItems.length === 0) {
      return (
        <p className="rounded-md border border-dashed border-border bg-muted/30 px-3 py-6 text-center text-xs text-muted-foreground">
          You haven't shared this ontology with anyone yet.
        </p>
      );
    }
    return <RosterMemberSection title="People" items={personItems} />;
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-sm font-semibold text-foreground">Active shares</h3>
          <p className="text-xs text-muted-foreground">
            {activeCount === 0 ? "No active shares" : `${activeCount} active`}
          </p>
        </div>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={handleRefresh}
          disabled={isFetching}
          className="h-8"
        >
          <RefreshCw className={cn("h-3.5 w-3.5", isFetching && "animate-spin")} />
          <span className="ml-1">Refresh</span>
        </Button>
      </div>

      {error && (
        <p className="rounded-md border border-destructive/40 bg-destructive/5 px-3 py-2 text-xs text-destructive">
          {error.message}
        </p>
      )}

      {renderActiveList()}

      {historyForView.length > 0 && (
        <div className="pt-2">
          <button
            type="button"
            onClick={handleToggleHistory}
            className="text-xs font-medium text-muted-foreground underline-offset-2 hover:underline"
          >
            {showHistory ? "Hide history" : `Show history (${historyForView.length})`}
          </button>
          {showHistory && (
            <div className="mt-2 space-y-2">
              {historyForView.map((entry) => renderShareRow(entry, true))}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ManageSharesPanel;
