import { Plus, Trash2 } from "lucide-react";
import { useEffect, useMemo, useRef } from "react";
import { type Control, Controller, type FieldValues, useFieldArray } from "react-hook-form";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { useConceptRows } from "../../runtime/useConceptRows";
import type { FormFieldDef } from "../../schema/appDefinition.types";
import { ScalarFieldControl } from "./ScalarFieldControl";

interface RecordGroupFieldProps {
  field: FormFieldDef;
  control: Control<FieldValues>;
  ontologyId: string;
}

function seedRows(
  columnNames: string[],
  rows: unknown[][],
  field: FormFieldDef,
): Record<string, unknown>[] {
  const columnToField = field.seedFrom?.columnToField ?? {};
  const fieldIds = (field.fields ?? []).map((rowField) => rowField.id);
  return rows.map((row) => {
    const record: Record<string, unknown> = Object.fromEntries(
      (field.fields ?? []).map((rowField) => [rowField.id, rowField.default ?? ""]),
    );
    columnNames.forEach((column, index) => {
      const lower = column.toLowerCase();
      const mapped = Object.entries(columnToField).find(([key]) => key.toLowerCase() === lower);
      const direct = fieldIds.find((fieldId) => fieldId.toLowerCase() === lower);
      const target = mapped?.[1] ?? direct ?? null;
      if (target) record[target] = row[index];
    });
    return record;
  });
}

/**
 * Repeatable row editor (ADR D5 tier 3): each row is a set of typed fields;
 * optionally seeded from a concept's current output so users edit instead of
 * starting blank. Produces the record arrays that facts bindings serialize.
 */
export function RecordGroupField({ field, control, ontologyId }: RecordGroupFieldProps) {
  const { fields: rows, append, remove, replace } = useFieldArray({ control, name: field.id });
  const maxRows = field.maxRows ?? 200;

  const { data: seedData, isLoading: seedLoading } = useConceptRows(
    field.seedFrom ? ontologyId : undefined,
    field.seedFrom?.concept,
    Math.min(maxRows, 200),
  );
  const isSeeding = seedLoading && rows.length === 0;

  const hasSeeded = useRef(false);
  useEffect(() => {
    if (!seedData || hasSeeded.current || rows.length > 0) return;
    hasSeeded.current = true;
    const seeded = seedRows(seedData.columnNames, seedData.rows, field).slice(0, maxRows);
    if (seeded.length > 0) replace(seeded);
  }, [seedData, rows.length, field, maxRows, replace]);

  const emptyRecord = useMemo(
    () =>
      Object.fromEntries(
        (field.fields ?? []).map((rowField) => [rowField.id, rowField.default ?? ""]),
      ),
    [field],
  );

  const rowFields = field.fields ?? [];

  if (isSeeding) {
    return (
      <div className="flex items-center gap-2 py-4 text-xs text-muted-foreground border border-dashed border-border rounded-md px-3">
        <PrometheuxSpinner size={14} />
        Loading rows from “{field.seedFrom?.concept}”…
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-2">
      <div
        className="grid gap-2 text-[11px] font-medium text-muted-foreground"
        style={{ gridTemplateColumns: `repeat(${rowFields.length}, 1fr) 2rem` }}
      >
        {rowFields.map((rowField) => (
          <span key={rowField.id}>{rowField.label ?? rowField.id}</span>
        ))}
        <span />
      </div>

      <div className="flex flex-col gap-1.5 max-h-[320px] overflow-y-auto pr-1">
        {rows.map((row, rowIndex) => (
          <div
            key={row.id}
            className="grid gap-2 items-center"
            style={{ gridTemplateColumns: `repeat(${rowFields.length}, 1fr) 2rem` }}
          >
            {rowFields.map((rowField) => (
              <Controller
                key={rowField.id}
                control={control}
                name={`${field.id}.${rowIndex}.${rowField.id}`}
                render={({ field: rhf }) => (
                  <ScalarFieldControl
                    field={rowField}
                    value={rhf.value}
                    onChange={rhf.onChange}
                    ontologyId={ontologyId}
                  />
                )}
              />
            ))}
            <Button
              type="button"
              variant="ghost"
              size="iconSm"
              className="text-muted-foreground hover:text-destructive"
              disabled={rows.length <= (field.minRows ?? 0)}
              onClick={() => remove(rowIndex)}
            >
              <Trash2 className="h-3.5 w-3.5" />
            </Button>
          </div>
        ))}
      </div>

      <Button
        type="button"
        variant="outline"
        size="sm"
        className="self-start gap-1.5"
        disabled={rows.length >= maxRows}
        onClick={() => append(emptyRecord)}
      >
        <Plus className="h-3.5 w-3.5" />
        Add row
      </Button>
    </div>
  );
}
