import { useCodeAssistantStore } from "@/features/code-assistant/store";

/**
 * Horizontal space (px) the docked AI assistant chat currently reserves —
 * its width when open, 0 when closed. The panel is fixed-positioned to the right
 * of the rail and the content wrapper pads left by this amount, so responsive
 * breakpoints should subtract it.
 */
export function useChatReservedWidth(): number {
  const isOpen = useCodeAssistantStore((state) => state.isPanelOpen);
  const width = useCodeAssistantStore((state) => state.panelWidth);
  return isOpen ? width : 0;
}
