import { useQuery } from "@tanstack/react-query";
import { useMemo } from "react";

import { ContextNoteApi } from "@/features/context-layer/api";
import type { ContextNote, ContextNoteFilter } from "@/features/context-layer/types";
import type { DashboardListItem } from "@/features/dynamic-dashboard/api/DashboardClient";
import { DashboardClient } from "@/features/dynamic-dashboard/api/DashboardClient";
import type { OntologyData } from "@/features/ontologies/api";
import { useDebouncedValue } from "@/shared/hooks/ui/useDebouncedValue";

import { searchOntologies } from "../api";

const SEARCH_DEBOUNCE_MS = 300;
const MIN_QUERY_LENGTH = 3;
const MAX_PER_GROUP = 6;

const dashboardClient = new DashboardClient();

export interface GlobalSearchState {
  projects: OntologyData[];
  apps: DashboardListItem[];
  context: ContextNote[];
  isLoading: boolean;
  /** True once the query is long enough for searching to be enabled. */
  isActive: boolean;
}

/** First-seen-wins dedupe across the note lists. */
function mergeContextNotes(lists: (ContextNote[] | undefined)[]): ContextNote[] {
  const flat = lists.flatMap((list) => list ?? []);
  const byId = new Map(flat.map((note) => [note.id, note]));
  return Array.from(byId.values());
}

/**
 * Powers the header global search. Fires in parallel:
 *  - projects (server-side `q` filter on name/description)
 *  - dynamic apps (server-side `q` filter on name; federated apps excluded)
 *  - context notes via full-text (exact-word) search, for the global scope plus
 *    the active project when there is one.
 *
 * Semantic/embedding search is intentionally NOT used here: it returns the
 * top-K nearest notes by vector distance regardless of whether they contain the
 * query words, which reads as arbitrary results in a jump-to search. Exact
 * matching keeps this group predictable, matching the projects/apps behaviour.
 */
export function useGlobalSearch(
  rawQuery: string,
  activeOntologyId: string | null,
): GlobalSearchState {
  const query = useDebouncedValue(rawQuery.trim(), SEARCH_DEBOUNCE_MS);
  const enabled = query.length >= MIN_QUERY_LENGTH;

  const ontologiesQuery = useQuery({
    queryKey: ["global-search", "projects", query],
    queryFn: () => searchOntologies(query),
    enabled,
  });

  const appsQuery = useQuery({
    queryKey: ["global-search", "apps", query],
    queryFn: () => dashboardClient.listAllDashboards("user", query),
    enabled,
  });

  const globalFilter: ContextNoteFilter = { scope: "global" };
  const globalFts = useQuery({
    queryKey: ["global-search", "ctx-fts", "global", query],
    queryFn: () => ContextNoteApi.searchFulltext(query, globalFilter),
    enabled,
  });

  const ontologyEnabled = enabled && Boolean(activeOntologyId);
  const ontologyFilter: ContextNoteFilter = { scope: "ontology", scopeId: activeOntologyId };
  const ontologyFts = useQuery({
    queryKey: ["global-search", "ctx-fts", "ontology", activeOntologyId, query],
    queryFn: () => ContextNoteApi.searchFulltext(query, ontologyFilter),
    enabled: ontologyEnabled,
  });

  const context = useMemo(
    () => mergeContextNotes([globalFts.data, ontologyFts.data]).slice(0, MAX_PER_GROUP),
    [globalFts.data, ontologyFts.data],
  );

  const projects = (ontologiesQuery.data ?? []).slice(0, MAX_PER_GROUP);
  const apps = (appsQuery.data ?? []).slice(0, MAX_PER_GROUP);

  const isLoading =
    enabled &&
    (ontologiesQuery.isLoading ||
      appsQuery.isLoading ||
      globalFts.isLoading ||
      (ontologyEnabled && ontologyFts.isLoading));

  return { projects, apps, context, isLoading, isActive: enabled };
}
