import { create } from "zustand";

/**
 * Persistent, per-user assistant consent preferences:
 *  - `mode`: "agent" (can make changes, gated by authorization) or "ask"
 *    (read-only — the assistant cannot change anything);
 *  - `authorizedTools`: the standing "always allow" list, so the assistant
 *    stops asking before running those tools.
 *
 * Both are persisted to localStorage (best-effort) so the choices survive
 * reloads. Destructive/irreversible tools are never persisted here — the
 * backend enforces that regardless, and the UI only ever offers "Allow once"
 * for them.
 */
export type AssistantMode = "agent" | "ask";

const STORAGE_KEYS = {
  MODE: "ai_assistant_mode",
  AUTHORIZED_TOOLS: "ai_assistant_authorized_tools",
} as const;

function readMode(): AssistantMode {
  try {
    return localStorage.getItem(STORAGE_KEYS.MODE) === "ask" ? "ask" : "agent";
  } catch {
    return "agent";
  }
}

function writeMode(mode: AssistantMode): void {
  try {
    localStorage.setItem(STORAGE_KEYS.MODE, mode);
  } catch {
    // best-effort persistence
  }
}

function readAuthorizedTools(): string[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.AUTHORIZED_TOOLS);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((t): t is string => typeof t === "string");
  } catch {
    return [];
  }
}

function writeAuthorizedTools(tools: string[]): void {
  try {
    localStorage.setItem(STORAGE_KEYS.AUTHORIZED_TOOLS, JSON.stringify(tools));
  } catch {
    // best-effort persistence
  }
}

interface AuthorizationsState {
  mode: AssistantMode;
  setMode: (mode: AssistantMode) => void;
  authorizedTools: string[];
  authorizeTool: (tool: string) => void;
  revokeTool: (tool: string) => void;
  clearAuthorizedTools: () => void;
}

export const useAuthorizationsStore = create<AuthorizationsState>((set) => ({
  mode: readMode(),
  setMode: (mode) => {
    writeMode(mode);
    set({ mode });
  },
  authorizedTools: readAuthorizedTools(),
  authorizeTool: (tool) =>
    set((state) => {
      if (state.authorizedTools.includes(tool)) return state;
      const next = [...state.authorizedTools, tool];
      writeAuthorizedTools(next);
      return { authorizedTools: next };
    }),
  revokeTool: (tool) =>
    set((state) => {
      const next = state.authorizedTools.filter((t) => t !== tool);
      writeAuthorizedTools(next);
      return { authorizedTools: next };
    }),
  clearAuthorizedTools: () => {
    writeAuthorizedTools([]);
    set({ authorizedTools: [] });
  },
}));
