import { useQueryClient } from "@tanstack/react-query";
import { useMemo } from "react";
import { useLocation } from "react-router-dom";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";

export interface CurrentDashboard {
  id: string;
  name: string | null;
}

// Dynamic app run/edit: /apps/:ontologyId/:id[/edit] — two path segments.
// Excludes /apps/new/edit, which has no app yet.
function parseDynamicDashboard(pathname: string): { ontologyId: string; id: string } | null {
  const match = pathname.match(/^\/apps\/([^/]+)\/([^/]+)/);
  if (!match || match[1] === "new") return null;
  return { ontologyId: match[1], id: match[2] };
}

// Federated app: /apps/:dashboardId — a single path segment.
function parseAppId(pathname: string): string | null {
  const match = pathname.match(/^\/apps\/([^/]+)$/);
  return match ? match[1] : null;
}

/**
 * Resolves the app the user is currently viewing, so the chat can tell the
 * agent what it's looking at. Returns null on any non-app page.
 *
 * The name is best-effort: dynamic apps read it from the React Query cache
 * (already populated by the app page), federated apps from the permissions
 * store. When the name isn't available the id alone still anchors the agent,
 * which can resolve the rest via its `get_dashboard` tool.
 */
export function useCurrentDashboard(): CurrentDashboard | null {
  const { pathname } = useLocation();
  const queryClient = useQueryClient();
  const visibleApps = usePermissionsStore((state) => state.visibleApps);

  const dynamic = parseDynamicDashboard(pathname);
  const appId = dynamic ? null : parseAppId(pathname);

  const id = dynamic?.id ?? appId;
  const dynamicName = dynamic
    ? (queryClient.getQueryData<{ name?: string }>(["dashboard", dynamic.ontologyId, dynamic.id])
        ?.name ?? null)
    : null;
  const appName = appId ? (visibleApps.find((app) => app.id === appId)?.name ?? null) : null;
  const name = dynamicName ?? appName;

  return useMemo(() => (id ? { id, name } : null), [id, name]);
}
