import { MoreHorizontal, Pencil, Trash2 } from "lucide-react";
import type React from "react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import { cn } from "@/shared/lib/utils";
import { formatRelativeTime } from "../chatHistory.utils";
import type { ChatSessionMeta } from "../chatHistoryApi";

interface ChatHistoryRowProps {
  session: ChatSessionMeta;
  isActive: boolean;
  isEditing: boolean;
  editTitle: string;
  editInputRef: React.RefObject<HTMLInputElement>;
  onSelect: (id: string) => void;
  onEditTitleChange: (value: string) => void;
  onFinishRename: () => void;
  onCancelRename: () => void;
  onStartRename: (id: string, title: string) => void;
  onDelete: (id: string) => void;
}

// A single chat-history entry: the title + relative timestamp, plus a rename/
// delete menu that stays hidden until the row is hovered (or its menu is open).
export function ChatHistoryRow({
  session,
  isActive,
  isEditing,
  editTitle,
  editInputRef,
  onSelect,
  onEditTitleChange,
  onFinishRename,
  onCancelRename,
  onStartRename,
  onDelete,
}: ChatHistoryRowProps) {
  return (
    <div
      className={cn(
        "group relative flex w-full items-center gap-1 rounded-lg px-2.5 py-2 transition-colors",
        isActive ? "bg-accent" : "hover:bg-accent/60",
      )}
    >
      {isEditing ? (
        <input
          ref={editInputRef}
          className="min-w-0 flex-1 rounded-md border border-input bg-background px-1.5 py-1 text-sm text-foreground outline-none focus:ring-1 focus:ring-ring"
          value={editTitle}
          onChange={(e) => onEditTitleChange(e.target.value)}
          onBlur={onFinishRename}
          onKeyDown={(e) => {
            if (e.key === "Enter") onFinishRename();
            if (e.key === "Escape") onCancelRename();
          }}
        />
      ) : (
        <button
          type="button"
          className="w-0 flex-grow cursor-pointer overflow-hidden text-left"
          onClick={() => onSelect(session.id)}
        >
          <p
            className={cn(
              "truncate text-sm text-foreground",
              isActive ? "font-semibold" : "font-medium",
            )}
          >
            {session.title}
          </p>
          <p className="truncate text-[11px] text-muted-foreground">
            {formatRelativeTime(session.updated_at)}
          </p>
        </button>
      )}

      {!isEditing && (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button
              type="button"
              className="flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-md text-muted-foreground opacity-0 transition-opacity hover:bg-background hover:text-foreground focus:opacity-100 group-hover:opacity-100 data-[state=open]:opacity-100"
            >
              <MoreHorizontal className="h-3.5 w-3.5" />
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" side="right" className="w-32">
            <DropdownMenuItem onSelect={() => onStartRename(session.id, session.title)}>
              <Pencil className="mr-2 h-3.5 w-3.5" />
              Rename
            </DropdownMenuItem>
            <DropdownMenuItem
              className="text-destructive focus:text-destructive"
              onSelect={() => onDelete(session.id)}
            >
              <Trash2 className="mr-2 h-3.5 w-3.5" />
              Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </div>
  );
}
