import { AlertCircle, Loader2, Paperclip, X } from "lucide-react";

import { cn } from "@/shared/lib/utils";

import type { PendingAttachment } from "../hooks/useChatAttachments";

interface ChatAttachmentChipsProps {
  attachments: PendingAttachment[];
  onRemove: (id: string) => void;
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

export function ChatAttachmentChips({ attachments, onRemove }: ChatAttachmentChipsProps) {
  if (attachments.length === 0) return null;
  return (
    <ul className="flex flex-wrap gap-1.5">
      {attachments.map((attachment) => {
        const Icon = attachment.error ? AlertCircle : attachment.isUploading ? Loader2 : Paperclip;
        const showThumbnail = !attachment.error && !attachment.isUploading && attachment.previewUrl;
        const handleRemove = () => onRemove(attachment.id);
        return (
          <li
            key={attachment.id}
            className={cn(
              "inline-flex max-w-xs items-center gap-1.5 rounded-md border border-border bg-card px-2 py-1 text-xs",
              attachment.error && "border-destructive/40 bg-destructive/5",
            )}
            title={attachment.error ?? attachment.fileName}
          >
            {showThumbnail ? (
              <img
                src={attachment.previewUrl}
                alt=""
                className="h-5 w-5 shrink-0 rounded-sm border border-border object-cover"
              />
            ) : (
              <Icon
                className={cn(
                  "h-3 w-3 shrink-0",
                  attachment.error
                    ? "text-destructive"
                    : attachment.isUploading
                      ? "animate-spin text-muted-foreground"
                      : "text-muted-foreground",
                )}
              />
            )}
            <span className="truncate text-foreground">{attachment.fileName}</span>
            <span className="shrink-0 text-muted-foreground">
              {formatSize(attachment.fileSize)}
            </span>
            <button
              type="button"
              onClick={handleRemove}
              className="ml-0.5 shrink-0 text-muted-foreground hover:text-foreground"
              aria-label={`Remove ${attachment.fileName}`}
            >
              <X className="h-3 w-3" />
            </button>
          </li>
        );
      })}
    </ul>
  );
}
