import type { ConceptRestriction, RestrictionLevel, ShareRole } from "../types";

// Effective access to a single concept, on one normalized scale:
//   hidden      → the concept is invisible / all concept calls rejected
//   read_only   → visible, not editable (base role "viewer")
//   read_write  → editable (base role "editor")
export type EffectiveAccess = RestrictionLevel;

// Where the effective level came from — used to explain the row in the UI.
export type AccessSource = "concept" | "ontology" | "share" | "team-concept" | "team";

export interface AccessRecipient {
  sub: string;
  label: string;
  // Base role from a direct user share, if this user was shared with directly.
  directRole?: ShareRole;
  // The recipient team this user belongs to (a team the project is shared with).
  teamId?: string;
  // That team's base share role.
  teamBaseRole?: ShareRole;
}

export interface AccessRow {
  sub: string;
  label: string;
  level: EffectiveAccess;
  source: AccessSource;
}

const roleToLevel = (role: ShareRole): EffectiveAccess =>
  role === "editor" ? "read_write" : "read_only";

const subjectSub = (r: ConceptRestriction): string => r.recipient_sub ?? r.subject_id;

// The backend uses "writeable" as an alias for "read_write" (and may vary in
// casing). Normalize any level string coming off the wire to the FE enum so the
// render path never trips over an unexpected value — a bad level must never
// crash the permissions panel.
export function normalizeLevel(level: string | null | undefined): EffectiveAccess {
  switch ((level ?? "").toLowerCase()) {
    case "read_write":
    case "writeable":
    case "writable":
      return "read_write";
    case "hidden":
      return "hidden";
    default:
      return "read_only";
  }
}

// Resolve one recipient's effective access to a concept, applying the backend's
// precedence (most specific wins, user rules beat team rules):
//   user+concept > user+project > direct user share > team+concept > team base
export function resolveConceptAccess(
  recipient: AccessRecipient,
  predicateName: string,
  restrictions: ConceptRestriction[],
): AccessRow {
  const base = { sub: recipient.sub, label: recipient.label };

  const userConcept = restrictions.find(
    (r) =>
      r.scope === "concept" &&
      r.subject_type === "user" &&
      r.predicate_name === predicateName &&
      subjectSub(r) === recipient.sub,
  );
  if (userConcept) return { ...base, level: normalizeLevel(userConcept.level), source: "concept" };

  const userOntology = restrictions.find(
    (r) => r.scope === "ontology" && r.subject_type === "user" && subjectSub(r) === recipient.sub,
  );
  if (userOntology)
    return { ...base, level: normalizeLevel(userOntology.level), source: "ontology" };

  if (recipient.directRole) {
    return { ...base, level: roleToLevel(recipient.directRole), source: "share" };
  }

  if (recipient.teamId) {
    const teamConcept = restrictions.find(
      (r) =>
        r.scope === "concept" &&
        r.subject_type === "team" &&
        r.predicate_name === predicateName &&
        r.subject_id === recipient.teamId,
    );
    if (teamConcept)
      return { ...base, level: normalizeLevel(teamConcept.level), source: "team-concept" };
  }

  const teamRole = recipient.teamBaseRole ?? "viewer";
  return { ...base, level: roleToLevel(teamRole), source: "team" };
}

// Build the full effective-access roster for a concept, sorted with the most
// restricted first (hidden → read-only → writeable), then by label.
const LEVEL_ORDER: Record<EffectiveAccess, number> = {
  hidden: 0,
  read_only: 1,
  read_write: 2,
};

export function computeConceptAccess(
  recipients: AccessRecipient[],
  predicateName: string,
  restrictions: ConceptRestriction[],
): AccessRow[] {
  return recipients
    .map((recipient) => resolveConceptAccess(recipient, predicateName, restrictions))
    .sort((a, b) => LEVEL_ORDER[a.level] - LEVEL_ORDER[b.level] || a.label.localeCompare(b.label));
}

// ── Presentation helpers (shared by the dialog + the access roster) ─────────

// Accepts a raw level string (may be a backend alias) so the render path can
// never throw on an unexpected value.
export function accessLevelLabel(level: string): string {
  const normalized = normalizeLevel(level);
  switch (normalized) {
    case "read_write":
      return "Editor";
    case "read_only":
      return "Viewer";
    case "hidden":
      return "Hidden";
    default: {
      const _exhaustive: never = normalized;
      throw new Error(`Unhandled level: ${_exhaustive}`);
    }
  }
}

export function accessLevelBadgeClass(level: string): string {
  const normalized = normalizeLevel(level);
  switch (normalized) {
    case "read_write":
      return "bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-400";
    case "hidden":
      return "bg-red-100 text-red-700 dark:bg-red-900/20 dark:text-red-400";
    case "read_only":
      return "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-400";
    default: {
      const _exhaustive: never = normalized;
      throw new Error(`Unhandled level: ${_exhaustive}`);
    }
  }
}
