import { zodResolver } from "@hookform/resolvers/zod";
import { Users } from "lucide-react";
import type React from "react";
import { useEffect } from "react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import { z } from "zod";
import { useMyTeams } from "@/features/teams/hooks/useMyTeams";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { cn } from "@/shared/lib/utils";
import { useShareOntology } from "../hooks/useShareOntology";
import { useShareOutbox } from "../hooks/useShareOutbox";
import { useShareTeam } from "../hooks/useShareTeam";
import type { ShareRecipientInput, ShareRole, ShareType } from "../types";
import {
  dateToExpiresInMinutes,
  type ExpiryPreset,
  findPendingMatch,
  isEmail,
  maxExpiryDateIso,
  minExpiryDateIso,
  presetToMinutes,
  roleMeta,
} from "../utils/sharing.utils";

const SHARE_ROLES: readonly ShareRole[] = ["viewer", "editor"];
const EXPIRY_PRESETS: readonly { value: ExpiryPreset; label: string }[] = [
  { value: "never", label: "Never" },
  { value: "1d", label: "1 day" },
  { value: "7d", label: "7 days" },
  { value: "30d", label: "30 days" },
  { value: "custom", label: "Pick date" },
];

const formSchema = z
  .object({
    mode: z.enum(["user", "team"]),
    recipient: z.string().optional(),
    organization: z.string().optional(),
    teamId: z.string().optional(),
    shareRole: z.enum(["viewer", "editor"]),
    expiryPreset: z.enum(["never", "1d", "7d", "30d", "custom"]),
    expiryDate: z.string().optional(),
  })
  .superRefine((data, ctx) => {
    if (data.mode === "team") {
      if (!data.teamId) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          path: ["teamId"],
          message: "Select a team",
        });
      }
      return;
    }
    if (!data.recipient?.trim()) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ["recipient"],
        message: "Recipient is required",
      });
    } else if (!isEmail(data.recipient) && !data.organization?.trim()) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ["organization"],
        message: "Organization is required when sharing by username",
      });
    }
    if (data.expiryPreset === "custom" && !data.expiryDate) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ["expiryDate"],
        message: "Pick an expiry date",
      });
    }
  });

type ShareFormData = z.infer<typeof formSchema>;

interface ShareOntologyFormProps {
  ontologyId: string;
  ontologyName: string;
  // Person/Team scope, owned by the parent dialog's shared selector.
  mode: ShareType;
  onSubmitted: () => void;
}

const DEFAULT_VALUES: ShareFormData = {
  mode: "user",
  recipient: "",
  organization: "",
  teamId: "",
  shareRole: "viewer",
  expiryPreset: "never",
  expiryDate: "",
};

function resolveExpiresInMinutes(data: ShareFormData): number | null {
  if (data.expiryPreset === "custom" && data.expiryDate) {
    return dateToExpiresInMinutes(new Date(data.expiryDate));
  }
  if (data.expiryPreset === "custom") return null;
  return presetToMinutes(data.expiryPreset);
}

function buildRecipient(data: ShareFormData): ShareRecipientInput {
  const recipient = (data.recipient ?? "").trim();
  if (isEmail(recipient)) return { email: recipient };
  return { username: recipient, organization: (data.organization ?? "").trim() };
}

const ShareOntologyForm: React.FC<ShareOntologyFormProps> = ({
  ontologyId,
  ontologyName,
  mode,
  onSubmitted,
}) => {
  const { share, isSharing } = useShareOntology();
  const { shareWithTeam, isSharing: isSharingTeam } = useShareTeam();
  const { entries: outboxEntries } = useShareOutbox({ ontologyId });
  const { teams, isLoading: isLoadingTeams } = useMyTeams();
  const {
    register,
    handleSubmit,
    watch,
    setValue,
    formState: { errors },
  } = useForm<ShareFormData>({
    resolver: zodResolver(formSchema),
    defaultValues: DEFAULT_VALUES,
  });

  // Mirror the parent's selector value into form state for validation/submit.
  useEffect(() => {
    setValue("mode", mode, { shouldValidate: false });
  }, [mode, setValue]);
  const recipientValue = watch("recipient") ?? "";
  const organizationValue = watch("organization") ?? "";
  const teamIdValue = watch("teamId") ?? "";
  const shareRoleValue = watch("shareRole");
  const expiryPresetValue = watch("expiryPreset");

  const isTeamMode = mode === "team";
  const looksLikeEmail = isEmail(recipientValue);
  const existingPending =
    isTeamMode || looksLikeEmail
      ? undefined
      : findPendingMatch(outboxEntries, recipientValue, organizationValue);

  const busy = isSharing || isSharingTeam;
  const submitLabel = isTeamMode
    ? "Share with team"
    : existingPending
      ? "Resend invitation"
      : "Send invitation";

  const onValidSubmit = async (data: ShareFormData) => {
    try {
      if (data.mode === "team" && data.teamId) {
        await shareWithTeam({
          ontologyId,
          recipientTeamId: data.teamId,
          shareRole: data.shareRole,
        });
        toast.success(`"${ontologyName}" shared with the team`);
        onSubmitted();
        return;
      }
      await share({
        ontologyId,
        recipient: buildRecipient(data),
        shareRole: data.shareRole,
        expiresInMinutes: resolveExpiresInMinutes(data),
      });
      toast.success(`Invitation sent for "${ontologyName}"`);
      onSubmitted();
    } catch (error) {
      const message = error instanceof Error ? error.message : "Failed to share ontology";
      toast.error(message);
    }
  };

  const handleExpiryPresetChange = (preset: ExpiryPreset): void => {
    setValue("expiryPreset", preset, { shouldValidate: true });
    if (preset !== "custom") setValue("expiryDate", "");
  };

  return (
    <form onSubmit={handleSubmit(onValidSubmit)} className="space-y-5">
      {isTeamMode ? (
        <div className="space-y-1.5">
          <Label className="text-sm font-medium">Team</Label>
          <Select value={teamIdValue} onValueChange={(value) => setValue("teamId", value)}>
            <SelectTrigger>
              <SelectValue placeholder={isLoadingTeams ? "Loading teams…" : "Select a team"} />
            </SelectTrigger>
            <SelectContent>
              {teams.map((team) => (
                <SelectItem key={team.id} value={team.id}>
                  <span className="inline-flex items-center gap-2">
                    <Users className="h-3.5 w-3.5 text-muted-foreground" />
                    {team.name}
                  </span>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {errors.teamId && <p className="text-xs text-destructive">{errors.teamId.message}</p>}
          {!isLoadingTeams && teams.length === 0 && (
            <p className="text-xs text-muted-foreground">
              You aren't a member of any team yet. Create a team to share with everyone in it at
              once.
            </p>
          )}
          <p className="text-xs text-muted-foreground">
            Every active member gets access. New members are included automatically; removing a
            member revokes their access.
          </p>
        </div>
      ) : (
        <>
          <div className="space-y-1.5">
            <Label htmlFor="recipient" className="text-sm font-medium">
              Email or username
            </Label>
            <Input
              id="recipient"
              autoFocus
              placeholder="bob@example.com or bob"
              {...register("recipient")}
            />
            {errors.recipient && (
              <p className="text-xs text-destructive">{errors.recipient.message}</p>
            )}
            {existingPending && (
              <p className="text-xs text-muted-foreground">
                A pending invitation already exists for this user. Sending again will replace it
                with a new link.
              </p>
            )}
          </div>

          {!looksLikeEmail && recipientValue.length > 0 && (
            <div className="space-y-1.5">
              <Label htmlFor="organization" className="text-sm font-medium">
                Organization
              </Label>
              <Input id="organization" placeholder="acme" {...register("organization")} />
              {errors.organization && (
                <p className="text-xs text-destructive">{errors.organization.message}</p>
              )}
            </div>
          )}
        </>
      )}

      <div className="space-y-1.5">
        <Label className="text-sm font-medium">Role</Label>
        <Select
          value={shareRoleValue}
          onValueChange={(value) => setValue("shareRole", value as ShareRole)}
        >
          <SelectTrigger>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {SHARE_ROLES.map((role) => {
              const meta = roleMeta(role);
              return (
                <SelectItem key={role} value={role}>
                  <span className="font-medium">{meta.title}</span>
                  <span className="ml-2 text-xs text-muted-foreground">{meta.description}</span>
                </SelectItem>
              );
            })}
          </SelectContent>
        </Select>
      </div>

      {!isTeamMode && (
        <div className="space-y-2">
          <Label className="text-sm font-medium">Expires</Label>
          <div className="flex flex-wrap gap-2">
            {EXPIRY_PRESETS.map((preset) => {
              const isActive = expiryPresetValue === preset.value;
              return (
                <button
                  key={preset.value}
                  type="button"
                  onClick={() => handleExpiryPresetChange(preset.value)}
                  className={cn(
                    "rounded-full border px-3 py-1 text-xs font-medium transition-colors",
                    isActive
                      ? "border-foreground bg-foreground text-background"
                      : "border-border bg-card text-muted-foreground hover:text-foreground",
                  )}
                >
                  {preset.label}
                </button>
              );
            })}
          </div>
          {expiryPresetValue === "custom" && (
            <div className="space-y-1.5">
              <Input
                type="date"
                min={minExpiryDateIso()}
                max={maxExpiryDateIso()}
                {...register("expiryDate")}
              />
              {errors.expiryDate && (
                <p className="text-xs text-destructive">{errors.expiryDate.message}</p>
              )}
            </div>
          )}
        </div>
      )}

      <div className="flex justify-end pt-2">
        <Button
          type="submit"
          disabled={busy}
          isLoading={busy}
          className="bg-[#FFDF4B] text-[#212020] hover:bg-[#FFDF4B]/90 border border-[#212020] shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px]"
        >
          {submitLabel}
        </Button>
      </div>
    </form>
  );
};

export default ShareOntologyForm;
