import { Ticket, Users2 } from "lucide-react";
import type React from "react";
import { useCallback } from "react";
import { Link, useNavigate } from "react-router-dom";
import type { TeamMembershipRow } from "@/features/teams/types";
import { teamRoleMeta } from "@/features/teams/utils/teams.utils";
import { Badge } from "@/shared/components/ui/badge";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";
import { handleSpaLinkClick } from "@/shared/utils/spaLink";

interface TeamCardProps {
  team: TeamMembershipRow;
}

// Grid tile for the "My Teams" tab. Mirrors the visual language of
// ProjectCard so the workspace pages feel consistent — folder icon area, name,
// description, footer with metadata. Click anywhere on the card to open the
// detail page (Users icon is decorative; the anchor is the clickable target).
const TeamCard: React.FC<TeamCardProps> = ({ team }) => {
  const navigate = useNavigate();
  const roleTitle = teamRoleMeta(team.role).title;

  const handleClick = useCallback(
    (e: React.MouseEvent<HTMLAnchorElement>): void => {
      handleSpaLinkClick(e, () => navigate(`/teams/${team.id}`));
    },
    [navigate, team.id],
  );

  const description = team.linked_domain ? `Linked to ${team.linked_domain}` : "No linked domain";

  return (
    <Link
      to={`/teams/${team.id}`}
      onClick={handleClick}
      className="group relative flex flex-col gap-3 rounded-xl border border-border bg-card p-5 no-underline transition-all duration-150 hover:border-foreground/30 hover:shadow-sm"
    >
      <div className="flex items-start gap-3">
        <div className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg bg-secondary transition-colors group-hover:bg-secondary/70">
          <Users2 className="h-4 w-4 text-foreground/60" />
        </div>
        <div className="min-w-0 flex-1">
          <Tooltip>
            <TooltipTrigger asChild>
              <div className="truncate pr-6 text-[14px] font-semibold leading-tight text-foreground">
                {team.name}
              </div>
            </TooltipTrigger>
            <TooltipContent side="bottom" className="max-w-xs">
              <p className="break-words">{team.name}</p>
            </TooltipContent>
          </Tooltip>
          <div className="mt-1 line-clamp-2 text-[12px] text-muted-foreground">{description}</div>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2 border-t border-border/60 pt-3 text-[12px] text-muted-foreground">
        <span className="truncate">@{team.slug}</span>
        <Badge variant="outline" className="capitalize">
          {roleTitle}
        </Badge>
        {team.seat_granted && (
          <Badge
            className="gap-1 bg-amber-500/15 text-amber-700 hover:bg-amber-500/20 dark:text-amber-400"
            title="You hold a seat on this team — the team plan applies to you here"
          >
            <Ticket className="h-3 w-3" />
            Seated
          </Badge>
        )}
      </div>
    </Link>
  );
};

export default TeamCard;
