import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { supabase } from "@/shared/integrations/supabase/client";

const PAID_COMPUTE_ELIGIBILITY_KEY = "paid-compute-eligibility";

export interface UsePaidComputeEligibilityResult {
  isEligible: boolean | undefined;
  isLoading: boolean;
  isError: boolean;
  error: Error | null;
  refetch: () => void;
}

// Calls the zero-arg overload of can_use_paid_compute(), which resolves
// auth.uid() server-side. The (p_user_id uuid) overload is reserved for the
// Python backend's hard-enforcement path. See paid-compute handoff.
const fetchPaidComputeEligibility = async (): Promise<boolean> => {
  const { data, error } = await supabase.rpc("can_use_paid_compute");
  if (error) throw error;
  if (typeof data !== "boolean") {
    throw new Error(`can_use_paid_compute returned a non-boolean value: ${JSON.stringify(data)}`);
  }
  return data;
};

// In local dev we treat every account as paid, mirroring the backend's
// RUN_MODE == "development" bypass in entitlements_service.is_freemium. Vite sets
// import.meta.env.DEV only under `npm run dev`, so this never leaks to production.
const DEV_ELIGIBILITY: UsePaidComputeEligibilityResult = {
  isEligible: true,
  isLoading: false,
  isError: false,
  error: null,
  refetch: () => {},
};

export const usePaidComputeEligibility = (): UsePaidComputeEligibilityResult => {
  const { user } = useAuth();
  const userId = user?.id;

  const query = useQuery({
    queryKey: [PAID_COMPUTE_ELIGIBILITY_KEY, userId],
    queryFn: fetchPaidComputeEligibility,
    enabled: Boolean(userId) && !import.meta.env.DEV,
  });

  if (import.meta.env.DEV) {
    return DEV_ELIGIBILITY;
  }

  return {
    isEligible: query.data,
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
    refetch: () => {
      query.refetch();
    },
  };
};

export const PAID_COMPUTE_ELIGIBILITY_QUERY_KEY = PAID_COMPUTE_ELIGIBILITY_KEY;
