import { Pencil } from "lucide-react";
import type React from "react";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";

interface CellPredicatePickerProps {
  /** Currently selected output predicate. */
  outputPredicate?: string;
  /** Predicates the cell's program derives — the selectable outputs. */
  predicateOptions: string[];
  onPredicateChange: (predicate: string) => void;
  /** Renaming is only possible once the concept exists in the backend. */
  canRename: boolean;
  isRenaming: boolean;
  renameValue: string;
  inputRef: React.Ref<HTMLInputElement>;
  onRenameValueChange: (value: string) => void;
  onConfirm: () => void;
  onCancel: () => void;
  onStart: () => void;
}

/**
 * Identity widget for a logic cell: picks which of the program's derived
 * predicates this cell exposes, with an optional rename affordance.
 */
export function CellPredicatePicker({
  outputPredicate,
  predicateOptions,
  onPredicateChange,
  canRename,
  isRenaming,
  renameValue,
  inputRef,
  onRenameValueChange,
  onConfirm,
  onCancel,
  onStart,
}: CellPredicatePickerProps) {
  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") onConfirm();
    if (event.key === "Escape") onCancel();
  };

  if (isRenaming) {
    return (
      <Input
        ref={inputRef}
        value={renameValue}
        onChange={(e) => onRenameValueChange(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={onConfirm}
        placeholder="new_name"
        className="h-7 text-sm w-40 bg-muted/80"
        autoFocus
      />
    );
  }

  const hasOptions = predicateOptions.length > 0;

  return (
    <div className="flex items-center gap-1">
      <Select
        value={outputPredicate || (hasOptions ? "" : undefined)}
        onValueChange={onPredicateChange}
      >
        <SelectTrigger
          className="h-7 text-sm border-border [&>svg]:w-3 [&>svg]:h-3"
          style={{ width: "auto", minWidth: "120px", maxWidth: "950px" }}
        >
          <SelectValue placeholder="Select output predicate" className="truncate">
            {outputPredicate ? (
              <span className="truncate pr-2 block">{outputPredicate}</span>
            ) : (
              "Select output predicate"
            )}
          </SelectValue>
        </SelectTrigger>
        <SelectContent>
          {hasOptions ? (
            predicateOptions.map((option) => (
              <SelectItem key={option} value={option}>
                {option}
              </SelectItem>
            ))
          ) : (
            <div className="px-2 py-1 text-xs text-muted-foreground">No predicates</div>
          )}
        </SelectContent>
      </Select>
      {canRename && (
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              type="button"
              className="p-1 rounded hover:bg-muted/80 text-muted-foreground hover:text-foreground transition-colors"
              onClick={onStart}
            >
              <Pencil className="h-3 w-3" />
            </button>
          </TooltipTrigger>
          <TooltipContent side="bottom">Rename concept</TooltipContent>
        </Tooltip>
      )}
    </div>
  );
}
