import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRequireCompute } from "@/features/compute/hooks/useRequireCompute";
import { EngineWaitCancelledError, runWithEngineWait } from "@/shared/lib/engineBusy";
import { ConceptClient, type EvaluationResults, type FetchResult } from "../api/ConceptClient";
import type {
  BoundTableHandlers,
  ColumnFilterValue,
  OrderByItem,
  TableSearchState,
} from "../components/outputs/table/tableOutput.types";
import type { AppPageDef } from "../schema/appDefinition.types";
import { type GroupBindings, recordGroupFieldOrders, resolveGroupBindings } from "./groupBindings";
import { useTabContext } from "./tabContext";
import { collectBindingRefs, resolveRef } from "./templateResolver";

export type GroupRunState = "idle" | "running" | "waiting" | "done" | "error";

/** A group is "busy" while actively running OR parked waiting for the engine. */
export function isGroupBusy(state?: GroupRunState): boolean {
  return state === "running" || state === "waiting";
}

const AUTO_RUN_DEBOUNCE_MS = 400;
const DEFAULT_PAGE_SIZE = 10;

const client = new ConceptClient();

// The engine rejects concurrent executions globally, not per tab, so every
// group run — load, auto, button or form — from EVERY mounted hook instance
// goes through this one module-level queue. A per-instance queue is not
// enough: tabs stay mounted once visited, and switching tabs while another
// tab's load groups are still draining would collide with ENGINE_BUSY.
const sharedRunQueue: { current: Promise<unknown> } = { current: Promise.resolve() };

interface UseRunGroupsReturn {
  tapData: Record<string, FetchResult | null>;
  tapLoading: Record<string, boolean>;
  tapErrors: Record<string, string>;
  groupState: Record<string, GroupRunState>;
  groupErrors: Record<string, string>;
  runGroup: (groupId: string, extraValues?: Record<string, unknown>) => Promise<void>;
  cancelGroup: (groupId: string) => void;
  handlersForTap: (tapId: string) => BoundTableHandlers;
}

function hasActiveSearch(searchState: TableSearchState | undefined): boolean {
  if (!searchState) return false;
  if (searchState.searchTerm.trim()) return true;
  return !!searchState.columnFilters && Object.keys(searchState.columnFilters).length > 0;
}

/**
 * The run-group engine for one tab (ADR D2): resolves param/facts bindings
 * from the tab context, executes the group's concepts sequentially with
 * intermediate materialization, then fetches every output tap.
 */
export function useRunGroups(page: AppPageDef, ontologyId: string): UseRunGroupsReturn {
  const { values } = useTabContext();
  const { ensureCompute } = useRequireCompute();

  const [tapData, setTapData] = useState<Record<string, FetchResult | null>>({});
  const [tapLoading, setTapLoading] = useState<Record<string, boolean>>({});
  const [tapErrors, setTapErrors] = useState<Record<string, string>>({});
  const [groupState, setGroupState] = useState<Record<string, GroupRunState>>({});
  const [groupErrors, setGroupErrors] = useState<Record<string, string>>({});

  const valuesRef = useRef(values);
  valuesRef.current = values;
  const tapDataRef = useRef(tapData);
  tapDataRef.current = tapData;

  // Abort handles for in-flight group runs, so Cancel can stop a run that is
  // parked waiting for the engine to free up.
  const runControllers = useRef<Map<string, AbortController>>(new Map());

  const fieldOrders = useMemo(() => recordGroupFieldOrders(page), [page]);
  const groups = useMemo(() => page.runGroups ?? [], [page]);
  const tapConcepts = useMemo(() => {
    const map: Record<string, string> = {};
    for (const group of groups) {
      for (const tap of group.outputs ?? []) map[tap.id] = tap.concept;
    }
    return map;
  }, [groups]);

  const executeGroup = useCallback(
    async (groupId: string, extraValues?: Record<string, unknown>) => {
      const group = groups.find((candidate) => candidate.id === groupId);
      if (!group || !ensureCompute()) return;

      let bindings: GroupBindings;
      try {
        bindings = resolveGroupBindings(
          group,
          { ...valuesRef.current, ...extraValues },
          fieldOrders,
        );
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : "Unresolved bindings";
        setGroupState((prev) => ({ ...prev, [groupId]: "error" }));
        setGroupErrors((prev) => ({ ...prev, [groupId]: message }));
        return;
      }

      const taps = group.outputs ?? [];
      setGroupState((prev) => ({ ...prev, [groupId]: "running" }));
      setGroupErrors((prev) => ({ ...prev, [groupId]: "" }));
      setTapLoading((prev) => ({
        ...prev,
        ...Object.fromEntries(taps.map((tap) => [tap.id, true])),
      }));

      const controller = new AbortController();
      runControllers.current.set(groupId, controller);
      try {
        let lastEval: EvaluationResults | null = null;
        for (const concept of group.execute) {
          // Wait-and-retry on ENGINE_BUSY: the engine runs one execution at a
          // time globally, so contention with another surface parks the run in
          // a "waiting" state until it frees, instead of failing red.
          // The engine accepted the run once it emits its first status event:
          // flip "waiting" → "running" then, not when the run finishes.
          const onStarted = () =>
            setGroupState((prev) =>
              prev[groupId] === "waiting" ? { ...prev, [groupId]: "running" } : prev,
            );
          lastEval = await runWithEngineWait(
            () =>
              client.runConceptWithParams(
                ontologyId,
                concept,
                bindings.params,
                "user",
                true,
                onStarted,
                {
                  preambleFacts: bindings.preambleFacts,
                },
              ),
            {
              signal: controller.signal,
              onWaiting: () => setGroupState((prev) => ({ ...prev, [groupId]: "waiting" })),
              onResume: () => setGroupState((prev) => ({ ...prev, [groupId]: "running" })),
            },
          );
        }
        for (const tap of taps) {
          try {
            const data = await client.fetchConceptData(
              ontologyId,
              tap.concept,
              "user",
              1,
              DEFAULT_PAGE_SIZE,
            );
            setTapData((prev) => ({ ...prev, [tap.id]: data }));
            setTapErrors((prev) => ({ ...prev, [tap.id]: "" }));
          } catch {
            const fallback = lastEval ? client.extractFromEvalResults(lastEval, tap.concept) : null;
            setTapData((prev) => ({ ...prev, [tap.id]: fallback }));
          }
        }
        setGroupState((prev) => ({ ...prev, [groupId]: "done" }));
      } catch (err: unknown) {
        if (err instanceof EngineWaitCancelledError) {
          // User cancelled the wait — return to idle, not an error.
          setGroupState((prev) => ({ ...prev, [groupId]: "idle" }));
          setGroupErrors((prev) => ({ ...prev, [groupId]: "" }));
        } else {
          const message = err instanceof Error ? err.message : "Execution failed";
          setGroupState((prev) => ({ ...prev, [groupId]: "error" }));
          setGroupErrors((prev) => ({ ...prev, [groupId]: message }));
        }
      } finally {
        runControllers.current.delete(groupId);
        setTapLoading((prev) => ({
          ...prev,
          ...Object.fromEntries(taps.map((tap) => [tap.id, false])),
        }));
      }
    },
    [groups, ontologyId, ensureCompute, fieldOrders],
  );

  const runGroup = useCallback(
    (groupId: string, extraValues?: Record<string, unknown>) => {
      const run = sharedRunQueue.current.then(() => executeGroup(groupId, extraValues));
      sharedRunQueue.current = run.catch(() => undefined);
      return run;
    },
    [executeGroup],
  );

  // Cancel a group's in-flight run (used while it is parked waiting for the
  // engine). Aborting rejects runWithEngineWait, which executeGroup maps to idle.
  const cancelGroup = useCallback((groupId: string) => {
    runControllers.current.get(groupId)?.abort();
  }, []);

  // ── Load-triggered groups: run once when the tab first mounts, sequentially
  // (the engine rejects concurrent executions) ──────────────────────────────
  const hasRunLoadGroups = useRef(false);
  useEffect(() => {
    if (hasRunLoadGroups.current) return;
    const loadGroups = groups.filter((group) => group.trigger === "load");
    if (loadGroups.length === 0) return;
    hasRunLoadGroups.current = true;
    void (async () => {
      for (const group of loadGroups) {
        await runGroup(group.id);
      }
    })();
  }, [groups, runGroup]);

  // ── Auto-triggered groups (drill-downs): run when all bound context values
  // are present and any of them changed ────────────────────────────────────
  const autoSignatures = useRef<Record<string, string>>({});
  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];
    for (const group of groups) {
      if (group.trigger !== "auto") continue;
      const refs = collectBindingRefs([group.params, group.facts]);
      if (refs.length === 0 || refs.some((ref) => resolveRef(ref, values) === undefined)) continue;
      const signature = JSON.stringify(refs.map((ref) => resolveRef(ref, values)));
      if (autoSignatures.current[group.id] === signature) continue;
      // Record the signature only when the timer fires: the cleanup cancels
      // pending timers on every effect re-run (mount churn, other groups
      // finishing), and marking early would silently swallow the run.
      timers.push(
        setTimeout(() => {
          autoSignatures.current[group.id] = signature;
          void runGroup(group.id);
        }, AUTO_RUN_DEBOUNCE_MS),
      );
    }
    return () => timers.forEach(clearTimeout);
  }, [values, groups, runGroup]);

  // ── Table handlers (server-side pagination/sort/search per tap) ──────────
  const refetchTap = useCallback(
    async (
      tapId: string,
      page_: number,
      pageSize: number,
      orderBy: OrderByItem[] | undefined,
      searchState: TableSearchState | undefined,
    ) => {
      const concept = tapConcepts[tapId];
      if (!concept) return;
      setTapLoading((prev) => ({ ...prev, [tapId]: true }));
      try {
        const data = hasActiveSearch(searchState)
          ? await client.searchConceptData(
              ontologyId,
              concept,
              "user",
              searchState!.searchTerm,
              searchState!.columnFilters,
              page_,
              pageSize,
              orderBy,
            )
          : await client.fetchConceptData(ontologyId, concept, "user", page_, pageSize, orderBy);
        setTapData((prev) => ({ ...prev, [tapId]: data }));
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : "Failed to load data";
        setTapErrors((prev) => ({ ...prev, [tapId]: message }));
      } finally {
        setTapLoading((prev) => ({ ...prev, [tapId]: false }));
      }
    },
    [ontologyId, tapConcepts],
  );

  const handlersForTap = useCallback(
    (tapId: string): BoundTableHandlers => {
      const current = () => tapDataRef.current[tapId];
      return {
        onPageChange: (page_: number) =>
          refetchTap(
            tapId,
            page_,
            current()?.pageSize ?? DEFAULT_PAGE_SIZE,
            current()?.orderBy,
            current()?.searchState,
          ),
        onPageSizeChange: (pageSize: number) =>
          refetchTap(tapId, 1, pageSize, current()?.orderBy, current()?.searchState),
        onSort: (orderBy: OrderByItem[]) =>
          refetchTap(
            tapId,
            1,
            current()?.pageSize ?? DEFAULT_PAGE_SIZE,
            orderBy.length > 0 ? orderBy : undefined,
            current()?.searchState,
          ),
        onSearch: (searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) =>
          refetchTap(tapId, 1, current()?.pageSize ?? DEFAULT_PAGE_SIZE, current()?.orderBy, {
            searchTerm: searchTerm ?? "",
            columnFilters,
          }),
        onClearSearch: () =>
          refetchTap(
            tapId,
            1,
            current()?.pageSize ?? DEFAULT_PAGE_SIZE,
            current()?.orderBy,
            undefined,
          ),
      };
    },
    [refetchTap],
  );

  return {
    tapData,
    tapLoading,
    tapErrors,
    groupState,
    groupErrors,
    runGroup,
    cancelGroup,
    handlersForTap,
  };
}
