import { Search, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { useActiveOntologyId } from "../hooks/useActiveOntologyId";
import { GlobalSearchResults } from "./GlobalSearchResults";

/**
 * Header search: a Search icon that expands inline into a text field. Results
 * appear in a dropdown below, grouped by Projects / Context / Apps. Closes on
 * Escape, on click outside, or via the clear button. Rendered once inside
 * PageHeader so it shows on every page.
 */
export function GlobalSearchTrigger() {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const activeOntologyId = useActiveOntologyId();

  const close = () => {
    setOpen(false);
    setQuery("");
  };

  useEffect(() => {
    if (!open) return;
    inputRef.current?.focus();

    const handleMouseDown = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) close();
    };
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") close();
    };

    document.addEventListener("mousedown", handleMouseDown);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("mousedown", handleMouseDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [open]);

  if (!open) {
    return (
      <button
        type="button"
        aria-label="Search"
        onClick={() => setOpen(true)}
        className="flex h-9 w-9 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
      >
        <Search className="h-4 w-4" />
      </button>
    );
  }

  const showDropdown = query.trim().length > 0;

  return (
    <div ref={containerRef} className="relative">
      <div className="flex items-center gap-2 rounded-md border border-input bg-background px-2">
        <Search className="h-4 w-4 shrink-0 text-muted-foreground" />
        <input
          ref={inputRef}
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="Search ontologies, context, apps…"
          className="h-9 w-56 bg-transparent text-sm text-foreground outline-none placeholder:text-muted-foreground md:w-72"
        />
        <button
          type="button"
          aria-label="Close search"
          onClick={close}
          className="text-muted-foreground transition-colors hover:text-foreground"
        >
          <X className="h-4 w-4" />
        </button>
      </div>
      {showDropdown && (
        <div className="absolute right-0 top-full z-30 mt-1 max-h-[70vh] w-[22rem] overflow-y-auto rounded-md border border-border bg-popover p-1 text-popover-foreground shadow-md md:w-[26rem]">
          <GlobalSearchResults query={query} activeOntologyId={activeOntologyId} onClose={close} />
        </div>
      )}
    </div>
  );
}
