import { ChevronDown, Clock, Settings2 } from "lucide-react";
import type React from "react";
import { useMemo, useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";

type IntervalUnit = "minutes" | "hours" | "days" | "weeks";

const UNIT_OPTIONS: { value: IntervalUnit; label: string; min: number; max: number }[] = [
  { value: "minutes", label: "minutes", min: 1, max: 59 },
  { value: "hours", label: "hours", min: 1, max: 23 },
  { value: "days", label: "days", min: 1, max: 30 },
  { value: "weeks", label: "weeks", min: 1, max: 4 },
];

interface CronPolicyFormProps {
  onSubmit: (cronExpression: string, timezone: string) => Promise<void>;
  onCancel: () => void;
}

const CronPolicyForm: React.FC<CronPolicyFormProps> = ({ onSubmit, onCancel }) => {
  const [intervalValue, setIntervalValue] = useState(6);
  const [intervalUnit, setIntervalUnit] = useState<IntervalUnit>("hours");
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [rawCron, setRawCron] = useState("");
  const [timezone, setTimezone] = useState("UTC");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const cronExpression = useMemo(() => {
    if (showAdvanced) return rawCron.trim();
    return intervalToCron(intervalValue, intervalUnit);
  }, [showAdvanced, rawCron, intervalValue, intervalUnit]);

  const isValid = useMemo(() => {
    if (!cronExpression) return false;
    return cronExpression.trim().split(/\s+/).length === 5;
  }, [cronExpression]);

  const description = useMemo(() => {
    if (showAdvanced) return cronExpression ? `Cron: ${cronExpression}` : "";
    const unitLabel = intervalValue === 1 ? intervalUnit.slice(0, -1) : intervalUnit;
    return `Runs every ${intervalValue} ${unitLabel}`;
  }, [showAdvanced, cronExpression, intervalValue, intervalUnit]);

  const handleSubmit = async () => {
    if (!isValid) return;
    setIsSubmitting(true);
    try {
      await onSubmit(cronExpression, timezone);
    } finally {
      setIsSubmitting(false);
    }
  };

  const currentUnitConfig = UNIT_OPTIONS.find((u) => u.value === intervalUnit)!;

  const clampedValue = Math.max(
    currentUnitConfig.min,
    Math.min(currentUnitConfig.max, intervalValue),
  );
  if (clampedValue !== intervalValue) {
    setIntervalValue(clampedValue);
  }

  return (
    <div className="flex flex-col gap-3 p-3 border border-border/50 rounded-md bg-background">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
          <Clock className="h-3 w-3" />
          New scheduled policy
        </div>
        <Button
          variant="ghost"
          size="sm"
          className="h-6 px-1.5 text-[10px] text-muted-foreground"
          onClick={() => {
            if (!showAdvanced) setRawCron(cronExpression);
            setShowAdvanced((prev) => !prev);
          }}
        >
          <Settings2 className="h-3 w-3 mr-1" />
          {showAdvanced ? "Simple" : "Advanced"}
        </Button>
      </div>

      {showAdvanced ? (
        <div className="flex items-center gap-2">
          <Input
            placeholder="Cron expression (e.g. 0 */6 * * *)"
            value={rawCron}
            onChange={(e) => setRawCron(e.target.value)}
            className="h-7 text-xs flex-1 font-mono"
          />
          <Input
            placeholder="Timezone"
            value={timezone}
            onChange={(e) => setTimezone(e.target.value)}
            className="h-7 text-xs w-24"
          />
        </div>
      ) : (
        <div className="flex items-center gap-2">
          <span className="text-xs text-muted-foreground whitespace-nowrap">Run every</span>
          <Input
            type="number"
            min={currentUnitConfig.min}
            max={currentUnitConfig.max}
            value={intervalValue}
            onChange={(e) => setIntervalValue(parseInt(e.target.value, 10) || 1)}
            className="h-7 text-xs w-16 text-center"
          />
          <div className="relative">
            <select
              value={intervalUnit}
              onChange={(e) => setIntervalUnit(e.target.value as IntervalUnit)}
              className="h-7 text-xs appearance-none bg-background border border-input rounded-md pl-2 pr-6 focus:outline-none focus:ring-1 focus:ring-ring cursor-pointer"
            >
              {UNIT_OPTIONS.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
            <ChevronDown className="h-3 w-3 absolute right-1.5 top-1/2 -translate-y-1/2 pointer-events-none text-muted-foreground" />
          </div>
        </div>
      )}

      {description && <div className="text-[10px] text-muted-foreground/70">{description}</div>}

      <div className="flex justify-end gap-2">
        <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onCancel}>
          Cancel
        </Button>
        <Button
          size="sm"
          className="h-7 text-xs"
          disabled={!isValid || isSubmitting}
          onClick={handleSubmit}
        >
          {isSubmitting ? "Creating..." : "Create"}
        </Button>
      </div>
    </div>
  );
};

function intervalToCron(value: number, unit: IntervalUnit): string {
  switch (unit) {
    case "minutes":
      return `*/${value} * * * *`;
    case "hours":
      return `0 */${value} * * *`;
    case "days":
      return value === 1 ? "0 0 * * *" : `0 0 */${value} * *`;
    case "weeks":
      return value === 1 ? "0 0 * * 1" : `0 0 */${value * 7} * *`;
  }
}

export function describeCron(expr: string): string {
  const parts = expr.trim().split(/\s+/);
  if (parts.length !== 5) return expr;

  const [min, hour, dom, _mon, dow] = parts;

  if (min.startsWith("*/") && hour === "*") {
    const n = parseInt(min.slice(2), 10);
    return n === 1 ? "Every minute" : `Every ${n} minutes`;
  }
  if (min === "0" && hour.startsWith("*/")) {
    const n = parseInt(hour.slice(2), 10);
    return n === 1 ? "Every hour" : `Every ${n} hours`;
  }
  if (min === "0" && hour === "0" && dom.startsWith("*/")) {
    const n = parseInt(dom.slice(2), 10);
    return `Every ${n} days`;
  }
  if (min === "0" && hour === "0" && dom === "*" && dow === "*") return "Daily at midnight";
  if (min === "0" && hour === "0" && dom === "*" && dow === "1") return "Weekly (Monday)";
  if (min === "0" && hour === "*") return "Every hour";

  return expr;
}

export default CronPolicyForm;
