import { memo, useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { ConfigService } from "@/features/settings/api/configService";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Switch } from "@/shared/components/ui/switch";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import SettingsSection from "../SettingsSection";

// Prometheux's managed embeddings run on the Azure embedding deployment (the
// server's default EMBEDDING_PROVIDER), with no user API key required.
const MANAGED_EMBEDDING_PROVIDER = "azure";

const EmbeddingConfig = memo(() => {
  const [embeddingProvider, setEmbeddingProvider] = useState(
    PROMETHEUX_CONFIG.EMBEDDING.EMBEDDING_PROVIDER || "openai",
  );
  const [embeddingModel, setEmbeddingModel] = useState(PROMETHEUX_CONFIG.EMBEDDING.MODEL_VERSION);
  const [embeddingDimensions, setEmbeddingDimensions] = useState(
    PROMETHEUX_CONFIG.EMBEDDING.DIMENSIONS.toString(),
  );
  const [embeddingApiKey, setEmbeddingApiKey] = useState(PROMETHEUX_CONFIG.EMBEDDING_API_KEY);
  const [azureEmbeddingEndpoint, setAzureEmbeddingEndpoint] = useState(
    PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_ENDPOINT || "",
  );
  const [azureEmbeddingApiVersion, setAzureEmbeddingApiVersion] = useState(
    PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_API_VERSION || "",
  );
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  // false = managed (Prometheux key, no API key); true = bring-your-own.
  const [useOwnProvider, setUseOwnProvider] = useState(false);

  // Load config from backend on component mount
  useEffect(() => {
    const loadConfig = async () => {
      if (!PROMETHEUX_CONFIG.AUTH_TOKEN) {
        return;
      }

      setIsLoading(true);
      try {
        const config = await ConfigService.loadUserConfig();
        if (config?.embedding) {
          // Update local state with loaded config
          if (config.embedding.embedding_provider !== undefined)
            setEmbeddingProvider(config.embedding.embedding_provider);
          if (config.embedding.embedding_version !== undefined)
            setEmbeddingModel(config.embedding.embedding_version);
          if (config.embedding.embedding_dimensions !== undefined)
            setEmbeddingDimensions(config.embedding.embedding_dimensions.toString());
          if (config.embedding.embedding_api_key !== undefined)
            setEmbeddingApiKey(config.embedding.embedding_api_key);
          if (config.embedding.azure_embedding_endpoint !== undefined)
            setAzureEmbeddingEndpoint(config.embedding.azure_embedding_endpoint);
          if (config.embedding.azure_embedding_api_version !== undefined)
            setAzureEmbeddingApiVersion(config.embedding.azure_embedding_api_version);

          // A saved API key means the user is on their own provider; otherwise
          // they're on Prometheux's managed embeddings.
          setUseOwnProvider(!!config.embedding.embedding_api_key);

          // Apply to global config
          ConfigService.applyConfigToGlobal(config);
        }
      } catch (_error) {
        // Continue with default values if loading fails
      } finally {
        setIsLoading(false);
      }
    };

    loadConfig();
  }, []);

  useEffect(() => {
    if (embeddingModel === "text-embedding-ada-002") {
      setEmbeddingDimensions("1536");
    } else if (
      embeddingModel === "text-embedding-3-small" &&
      parseInt(embeddingDimensions, 10) > 1536
    ) {
      setEmbeddingDimensions("1536");
    } else if (
      embeddingModel === "text-embedding-3-large" &&
      parseInt(embeddingDimensions, 10) > 3072
    ) {
      setEmbeddingDimensions("3072");
    }
  }, [embeddingModel, embeddingDimensions]);

  const handleModeChange = useCallback(
    (own: boolean) => {
      setUseOwnProvider(own);
      if (own) {
        // Entering BYO from the managed default: openai needs only a key, so it's
        // the friendlier starting point than azure (which also needs an endpoint).
        if (embeddingProvider === MANAGED_EMBEDDING_PROVIDER) {
          setEmbeddingProvider("openai");
        }
        return;
      }
      // Managed: pin to the server's default embedding provider and clear the
      // user's key/endpoint so an empty key is no longer a hidden state.
      setEmbeddingProvider(MANAGED_EMBEDDING_PROVIDER);
      setEmbeddingApiKey("");
      setAzureEmbeddingEndpoint("");
      setAzureEmbeddingApiVersion("");
    },
    [embeddingProvider],
  );

  const handleEmbeddingConfigSave = useCallback(async () => {
    if (!PROMETHEUX_CONFIG.AUTH_TOKEN) {
      toast.error("Authentication token is missing. Please set it first.");
      return;
    }

    setIsSaving(true);
    try {
      // Update global config first
      PROMETHEUX_CONFIG.EMBEDDING.EMBEDDING_PROVIDER = embeddingProvider;
      PROMETHEUX_CONFIG.EMBEDDING.MODEL_VERSION = embeddingModel;
      PROMETHEUX_CONFIG.EMBEDDING.DIMENSIONS = parseInt(embeddingDimensions, 10);
      PROMETHEUX_CONFIG.EMBEDDING_API_KEY = embeddingApiKey;

      // Save Azure-specific settings if provider is Azure
      if (embeddingProvider === "azure") {
        PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_ENDPOINT = azureEmbeddingEndpoint;
        PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_API_VERSION = azureEmbeddingApiVersion;
      }

      // Prepare config for backend
      const configToSave = {
        embedding: {
          embedding_provider: embeddingProvider,
          embedding_version: embeddingModel,
          embedding_dimensions: parseInt(embeddingDimensions, 10),
          embedding_api_key: embeddingApiKey,
          azure_embedding_endpoint: azureEmbeddingEndpoint,
          azure_embedding_api_version: azureEmbeddingApiVersion,
        },
      };

      // Save to backend
      await ConfigService.saveUserConfig(configToSave);

      toast.success("Embedding configuration saved successfully");
    } catch (error) {
      toast.error(
        `Failed to save configuration: ${error instanceof Error ? error.message : "Unknown error"}`,
      );
    } finally {
      setIsSaving(false);
    }
  }, [
    embeddingProvider,
    embeddingModel,
    embeddingDimensions,
    embeddingApiKey,
    azureEmbeddingEndpoint,
    azureEmbeddingApiVersion,
  ]);

  const handleEmbeddingConfigReset = useCallback(() => {
    // Defaults are Prometheux's managed embeddings (Azure deployment, no key).
    setUseOwnProvider(false);
    setEmbeddingProvider(MANAGED_EMBEDDING_PROVIDER);
    setEmbeddingModel("text-embedding-3-large");
    setEmbeddingDimensions("2048");
    setEmbeddingApiKey("");
    setAzureEmbeddingEndpoint("");
    setAzureEmbeddingApiVersion("");

    PROMETHEUX_CONFIG.EMBEDDING.EMBEDDING_PROVIDER = MANAGED_EMBEDDING_PROVIDER;
    PROMETHEUX_CONFIG.EMBEDDING.MODEL_VERSION = "text-embedding-3-large";
    PROMETHEUX_CONFIG.EMBEDDING.DIMENSIONS = 2048;
    PROMETHEUX_CONFIG.EMBEDDING_API_KEY = "";
    PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_ENDPOINT = "";
    PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_API_VERSION = "";

    toast.success("Embedding configuration reset to defaults");
  }, []);

  const handleEmbeddingDimensionsChange = useCallback(
    (value: string) => {
      let newValue = parseInt(value, 10);
      if (embeddingModel === "text-embedding-ada-002") {
        newValue = 1536;
      } else if (embeddingModel === "text-embedding-3-small") {
        newValue = Math.min(Math.max(1, newValue), 1536);
      } else if (embeddingModel === "text-embedding-3-large") {
        newValue = Math.min(Math.max(1, newValue), 3072);
      }
      setEmbeddingDimensions(newValue.toString());
    },
    [embeddingModel],
  );

  const showAzureFields = useOwnProvider && embeddingProvider === "azure";

  return (
    <SettingsSection
      title="Embedding Configuration"
      description="Configure the embedding model settings"
    >
      <div className="space-y-4">
        <div className="flex items-center justify-between gap-4 rounded-md border border-border p-3">
          <div className="space-y-0.5">
            <Label htmlFor="use-own-embedding-provider">Use my own provider</Label>
            <p className="text-xs text-muted-foreground">
              {useOwnProvider
                ? "Bring your own embedding API key — you're billed directly by your provider."
                : "Running on Prometheux's managed embeddings. No API key needed."}
            </p>
          </div>
          <Switch
            id="use-own-embedding-provider"
            checked={useOwnProvider}
            onCheckedChange={handleModeChange}
          />
        </div>

        {useOwnProvider && (
          <div>
            <Label htmlFor="embedding-provider">Embedding Provider</Label>
            <Select value={embeddingProvider} onValueChange={setEmbeddingProvider}>
              <SelectTrigger>
                <SelectValue placeholder="Select embedding provider" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="openai">openai</SelectItem>
                <SelectItem value="azure">azure</SelectItem>
              </SelectContent>
            </Select>
          </div>
        )}

        {useOwnProvider && (
          <div>
            <Label htmlFor="embedding-api-key">Embedding API Key</Label>
            <Input
              id="embedding-api-key"
              type="password"
              value={embeddingApiKey}
              onChange={(e) => setEmbeddingApiKey(e.target.value)}
              placeholder="Enter your own embedding API key"
              className="flex-1"
            />
          </div>
        )}

        {showAzureFields && (
          <>
            <div>
              <Label htmlFor="azure-embedding-endpoint">Azure Embedding Endpoint</Label>
              <Input
                id="azure-embedding-endpoint"
                type="text"
                value={azureEmbeddingEndpoint}
                onChange={(e) => setAzureEmbeddingEndpoint(e.target.value)}
                placeholder="Enter your Azure embedding endpoint URL"
                className="flex-1"
              />
            </div>
            <div>
              <Label htmlFor="azure-embedding-api-version">Azure Embedding API Version</Label>
              <Input
                id="azure-embedding-api-version"
                type="text"
                value={azureEmbeddingApiVersion}
                onChange={(e) => setAzureEmbeddingApiVersion(e.target.value)}
                placeholder="Enter Azure embedding API version (e.g., 2023-05-15)"
                className="flex-1"
              />
            </div>
          </>
        )}

        <div>
          <Label htmlFor="embedding-model">Embedding Model</Label>
          <Select value={embeddingModel} onValueChange={setEmbeddingModel}>
            <SelectTrigger>
              <SelectValue placeholder="Select embedding model" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="text-embedding-3-large">text-embedding-3-large</SelectItem>
              <SelectItem value="text-embedding-3-small">text-embedding-3-small</SelectItem>
              <SelectItem value="text-embedding-ada-002">text-embedding-ada-002</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div>
          <Label htmlFor="embedding-dimensions">
            Embedding Dimensions
            {embeddingModel === "text-embedding-ada-002" && (
              <span className="text-sm text-muted-foreground ml-2">(Fixed at 1536)</span>
            )}
          </Label>
          <Input
            id="embedding-dimensions"
            type="number"
            min="1"
            max={
              embeddingModel === "text-embedding-3-small"
                ? 1536
                : embeddingModel === "text-embedding-3-large"
                  ? 3072
                  : 1536
            }
            value={embeddingDimensions}
            onChange={(e) => handleEmbeddingDimensionsChange(e.target.value)}
            placeholder="Enter embedding dimensions"
            className="flex-1"
            disabled={embeddingModel === "text-embedding-ada-002"}
          />
        </div>

        <div className="flex justify-end gap-4">
          <Button
            onClick={handleEmbeddingConfigSave}
            disabled={isSaving || isLoading}
            isLoading={isSaving}
          >
            {isSaving ? "Saving..." : "Save"}
          </Button>
          <Button
            onClick={handleEmbeddingConfigReset}
            variant="outline"
            disabled={isSaving || isLoading}
          >
            Reset
          </Button>
        </div>
      </div>
    </SettingsSection>
  );
});

EmbeddingConfig.displayName = "EmbeddingConfig";

export default EmbeddingConfig;
