import { groupDocumentChunks, linkDisplayTitle, representativeChunkOf } from "../notes/notesModel";
import type { ContextEdge, ContextNote, ContextShelf } from "../types";
import { parseConceptNodeId, shelfOf } from "../types";

export interface PanelNoteConnection {
  kind: "concept" | "ontology" | "note";
  label: string;
  /** Set on same-project concept chips — enables focus-in-lineage. */
  conceptName?: string;
  /** Set on note chips — deep-links to the Context page. */
  noteId?: string;
}

export interface PanelNoteEntry {
  /** Representative note (first chunk for documents) — deep-link target. */
  note: ContextNote;
  title: string;
  snippet: string;
  shelf: ContextShelf;
  /** First-level connections only — deeper hops are not traversed. */
  connections: PanelNoteConnection[];
}

function snippetOf(note: ContextNote): string {
  const body = (note.text || "").replace(/\s+/g, " ").trim();
  return body.length > 180 ? `${body.slice(0, 177)}…` : body;
}

function edgeEndpoints(edge: ContextEdge): Array<{ type: string; id: string }> {
  return [
    { type: edge.src_type, id: edge.src_id },
    { type: edge.dst_type, id: edge.dst_id },
  ];
}

/**
 * Everything the Context rail panel lists for a project: project-scoped
 * notes plus any note edge-attached to the project or to one of its
 * concepts. Document chunks collapse into one entry per document.
 */
export function buildContextPanelEntries(
  ontologyId: string,
  ontologyName: string,
  ontologyNotes: ContextNote[],
  globalNotes: ContextNote[],
  allEdges: ContextEdge[],
): PanelNoteEntry[] {
  const allNotes = [...ontologyNotes, ...globalNotes];
  const byId = new Map(allNotes.map((note) => [note.id, note]));

  // note id → edges touching it (either direction).
  const edgesByNoteId = new Map<string, ContextEdge[]>();
  for (const edge of allEdges) {
    for (const endpoint of edgeEndpoints(edge)) {
      if (endpoint.type !== "note") continue;
      const list = edgesByNoteId.get(endpoint.id) ?? [];
      list.push(edge);
      edgesByNoteId.set(endpoint.id, list);
    }
  }

  const connectionsFor = (noteIds: string[]): PanelNoteConnection[] => {
    const seen = new Set<string>();
    const connections: PanelNoteConnection[] = [];
    const push = (connection: PanelNoteConnection) => {
      const key = `${connection.kind}:${connection.label}`;
      if (seen.has(key)) return;
      seen.add(key);
      connections.push(connection);
    };

    const ownIds = new Set(noteIds);
    for (const noteId of noteIds) {
      for (const edge of edgesByNoteId.get(noteId) ?? []) {
        for (const endpoint of edgeEndpoints(edge)) {
          if (endpoint.type === "note") {
            if (ownIds.has(endpoint.id)) continue;
            const other = byId.get(endpoint.id);
            if (other) push({ kind: "note", label: linkDisplayTitle(other), noteId: other.id });
            continue;
          }
          if (endpoint.type === "concept") {
            const ref = parseConceptNodeId(endpoint.id);
            if (ref?.ontologyId === ontologyId) {
              push({ kind: "concept", label: ref.conceptName, conceptName: ref.conceptName });
            }
            continue;
          }
          if (endpoint.type === "ontology" && endpoint.id === ontologyId) {
            push({ kind: "ontology", label: ontologyName });
          }
        }
      }
    }
    return connections;
  };

  const isRelevant = (noteIds: string[], scopeId: string | null): boolean => {
    if (scopeId === ontologyId) return true;
    return noteIds.some((noteId) =>
      (edgesByNoteId.get(noteId) ?? []).some((edge) =>
        edgeEndpoints(edge).some(
          (endpoint) =>
            (endpoint.type === "ontology" && endpoint.id === ontologyId) ||
            (endpoint.type === "concept" &&
              parseConceptNodeId(endpoint.id)?.ontologyId === ontologyId),
        ),
      ),
    );
  };

  const { documents, standalone } = groupDocumentChunks(allNotes);

  const entries: PanelNoteEntry[] = [];
  for (const note of standalone) {
    if (!isRelevant([note.id], note.scope_id)) continue;
    entries.push({
      note,
      title: linkDisplayTitle(note),
      snippet: snippetOf(note),
      shelf: shelfOf(note),
      connections: connectionsFor([note.id]),
    });
  }
  for (const group of documents) {
    const representative = representativeChunkOf(group);
    const chunkIds = group.notes.map((chunk) => chunk.id);
    if (!isRelevant(chunkIds, representative.scope_id)) continue;
    entries.push({
      note: representative,
      title: group.filename,
      snippet: snippetOf(representative),
      shelf: "documents",
      connections: connectionsFor(chunkIds),
    });
  }
  return entries;
}

export function filterPanelEntries(entries: PanelNoteEntry[], term: string): PanelNoteEntry[] {
  const wanted = term.trim().toLowerCase();
  if (!wanted) return entries;
  return entries.filter(
    (entry) =>
      entry.title.toLowerCase().includes(wanted) ||
      entry.note.text.toLowerCase().includes(wanted) ||
      entry.connections.some((c) => c.label.toLowerCase().includes(wanted)),
  );
}
