import { FileText, Folder, Globe } from "lucide-react";

import type { ContextNote } from "../../types";
import type { DocumentGroup, VaultRef } from "../notesModel";
import {
  formatRelativeTime,
  formatUsage,
  normalizeFolderPath,
  noteDisplayTitle,
} from "../notesModel";
import { NoteBadges } from "./ShelfBadge";

const SNIPPET_MAX_CHARS = 220;

interface NoteCardGridProps {
  vault: VaultRef;
  /** "" = the whole vault. */
  folderPath: string;
  notes: ContextNote[];
  /** Shown only for the vault root ("" ) — documents live at root. */
  documents: DocumentGroup[];
  onOpenNote: (note: ContextNote) => void;
  onOpenDocument: (document: DocumentGroup) => void;
}

function snippetOf(note: ContextNote): string {
  const body = note.text
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("#"))
    .join(" ");
  return body.length > SNIPPET_MAX_CHARS ? `${body.slice(0, SNIPPET_MAX_CHARS)}…` : body;
}

interface NoteCardProps {
  note: ContextNote;
  showFolder: boolean;
  onOpen: () => void;
}

function NoteCard({ note, showFolder, onOpen }: NoteCardProps) {
  const folder = normalizeFolderPath(note.folder_path);
  return (
    <button
      type="button"
      onClick={onOpen}
      className="flex flex-col gap-2 rounded-lg border border-border bg-card p-4 text-left transition-colors hover:border-primary/40 hover:bg-accent/30"
    >
      <div className="flex w-full items-start justify-between gap-2">
        <h3 className="min-w-0 flex-1 truncate text-sm font-semibold text-foreground">
          {noteDisplayTitle(note)}
        </h3>
        <NoteBadges note={note} />
      </div>
      <p className="line-clamp-3 w-full text-sm leading-relaxed text-muted-foreground">
        {snippetOf(note)}
      </p>
      <div className="mt-auto flex w-full items-center gap-2 text-xs text-muted-foreground">
        <span>{formatUsage(note)}</span>
        {showFolder && folder && (
          <>
            <span aria-hidden>·</span>
            <span className="inline-flex min-w-0 items-center gap-1 truncate">
              <Folder className="h-3.5 w-3.5 shrink-0" />
              {folder}
            </span>
          </>
        )}
      </div>
    </button>
  );
}

interface DocumentCardProps {
  document: DocumentGroup;
  onOpen: () => void;
}

function DocumentCard({ document, onOpen }: DocumentCardProps) {
  const usage = document.useCount > 0 ? `Used ${document.useCount}×` : "Never used";
  const lastUsed = formatRelativeTime(document.lastUsedAt);
  return (
    <button
      type="button"
      onClick={onOpen}
      className="flex flex-col gap-2 rounded-lg border border-border bg-card p-4 text-left transition-colors hover:border-primary/40 hover:bg-accent/30"
    >
      <div className="flex w-full items-center gap-2">
        <FileText className="h-4 w-4 shrink-0 text-muted-foreground" />
        <h3 className="min-w-0 flex-1 truncate text-sm font-semibold text-foreground">
          {document.filename}
        </h3>
      </div>
      <p className="text-xs text-muted-foreground">
        Document · searched when relevant · {usage}
        {lastUsed ? ` · last used ${lastUsed}` : ""}
      </p>
    </button>
  );
}

/** Card list body of the collection view (header + tabs live in CollectionView). */
export function NoteCardGrid({
  vault,
  folderPath,
  notes,
  documents,
  onOpenNote,
  onOpenDocument,
}: NoteCardGridProps) {
  const EmptyIcon = folderPath ? Folder : Globe;
  const heading = folderPath || vault.name;
  const count = notes.length + documents.length;

  if (count === 0) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-2 text-center">
        <EmptyIcon className="h-8 w-8 text-muted-foreground/50" />
        <p className="text-sm text-muted-foreground">Nothing in {heading} yet.</p>
      </div>
    );
  }

  return (
    <div className="h-full overflow-y-auto">
      <div className="grid grid-cols-1 gap-3 p-6 lg:grid-cols-2 2xl:grid-cols-3">
        {notes.map((note) => (
          <NoteCard
            key={note.id}
            note={note}
            showFolder={!folderPath}
            onOpen={() => onOpenNote(note)}
          />
        ))}
        {documents.map((document) => (
          <DocumentCard
            key={document.documentId}
            document={document}
            onOpen={() => onOpenDocument(document)}
          />
        ))}
      </div>
    </div>
  );
}
