import { useCallback, useEffect, useRef, useState } from "react";

export interface SuggestionState {
  show: boolean;
  filtered: string[];
  selectedIndex: number;
}

const CLOSED: SuggestionState = { show: false, filtered: [], selectedIndex: 0 };

export interface UseMentionSuggestionsReturn {
  suggestions: SuggestionState;
  suggestionRefs: React.MutableRefObject<(HTMLDivElement | null)[]>;
  /** Recompute the dropdown from the text + cursor position. */
  checkSuggestions: (value: string, cursorPosition: number) => void;
  closeSuggestions: () => void;
  moveSelection: (delta: 1 | -1) => void;
  setSelectedIndex: (index: number) => void;
}

/**
 * @-mention autocomplete state for description textareas. Concept names
 * arrive via the batched "conceptsUpdated" window event (fetched once by
 * the parent list, not per cell).
 */
export function useMentionSuggestions(): UseMentionSuggestionsReturn {
  const [conceptNames, setConceptNames] = useState<string[]>([]);
  const [suggestions, setSuggestions] = useState<SuggestionState>(CLOSED);
  const suggestionRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    const handleConceptsUpdated = (event: Event) => {
      const detail = (event as CustomEvent).detail as
        | { concepts?: Array<{ predicate_name?: string }> }
        | undefined;
      const concepts = detail?.concepts;
      if (!Array.isArray(concepts) || concepts.length === 0) return;
      setConceptNames(
        concepts.map((c) => c.predicate_name).filter((name): name is string => Boolean(name)),
      );
    };
    window.addEventListener("conceptsUpdated", handleConceptsUpdated);
    return () => window.removeEventListener("conceptsUpdated", handleConceptsUpdated);
  }, []);

  useEffect(() => {
    suggestionRefs.current = [];
  }, [suggestions.filtered]);

  useEffect(() => {
    if (suggestions.show && suggestionRefs.current[suggestions.selectedIndex]) {
      suggestionRefs.current[suggestions.selectedIndex]?.scrollIntoView({
        behavior: "smooth",
        block: "nearest",
      });
    }
  }, [suggestions.selectedIndex, suggestions.show]);

  const checkSuggestions = useCallback(
    (value: string, cursorPosition: number) => {
      if (conceptNames.length === 0) {
        setSuggestions(CLOSED);
        return;
      }
      const textBeforeCursor = value.substring(0, cursorPosition);
      const lastAtIndex = textBeforeCursor.lastIndexOf("@");
      if (lastAtIndex === -1) {
        setSuggestions(CLOSED);
        return;
      }
      const textAfterAt = textBeforeCursor.substring(lastAtIndex + 1);
      if (textAfterAt.includes(" ") || textAfterAt.length === 0) {
        setSuggestions(CLOSED);
        return;
      }
      const filtered = conceptNames.filter((concept) =>
        concept.toLowerCase().includes(textAfterAt.toLowerCase()),
      );
      setSuggestions({ show: filtered.length > 0, filtered, selectedIndex: 0 });
    },
    [conceptNames],
  );

  const closeSuggestions = useCallback(() => setSuggestions(CLOSED), []);

  const moveSelection = useCallback((delta: 1 | -1) => {
    setSuggestions((prev) => ({
      ...prev,
      selectedIndex: Math.min(
        Math.max(prev.selectedIndex + delta, 0),
        Math.max(prev.filtered.length - 1, 0),
      ),
    }));
  }, []);

  const setSelectedIndex = useCallback((index: number) => {
    setSuggestions((prev) => ({ ...prev, selectedIndex: index }));
  }, []);

  return {
    suggestions,
    suggestionRefs,
    checkSuggestions,
    closeSuggestions,
    moveSelection,
    setSelectedIndex,
  };
}
