import { cn } from "@/shared/lib/utils";
import { ConceptLineDiff } from "./ConceptLineDiff";
import type { ConceptDiffStatus, ConceptFieldDiff } from "./snapshotDiff.utils";

const STATUS_BADGE: Record<ConceptDiffStatus, string> = {
  added: "bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-400",
  removed: "bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400",
  changed: "bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400",
};

const STATUS_LABEL: Record<ConceptDiffStatus, string> = {
  added: "Added",
  removed: "Removed",
  changed: "Changed",
};

interface ConceptDiffCardProps {
  status: ConceptDiffStatus;
  predicateName: string;
  fieldDiffs: ConceptFieldDiff[];
}

export function ConceptDiffCard({ status, predicateName, fieldDiffs }: ConceptDiffCardProps) {
  return (
    <div className="rounded-md border border-border bg-card">
      <div className="flex items-center gap-2 border-b border-border px-3 py-2">
        <span
          className={cn(
            "rounded px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide",
            STATUS_BADGE[status],
          )}
        >
          {STATUS_LABEL[status]}
        </span>
        <span className="truncate font-mono text-sm text-foreground" title={predicateName}>
          {predicateName}
        </span>
      </div>

      <div className="space-y-3 p-3">
        {fieldDiffs.length === 0 && (
          <p className="text-xs text-muted-foreground">No field-level changes.</p>
        )}
        {fieldDiffs.map((fieldDiff) => (
          <div key={fieldDiff.field} className="space-y-1">
            <p className="text-xs font-medium text-muted-foreground">{fieldDiff.label}</p>
            <ConceptLineDiff changes={fieldDiff.changes} />
          </div>
        ))}
      </div>
    </div>
  );
}
