import { AlertTriangle, Check, Copy, Eye, EyeOff } from "lucide-react";
import type React from "react";
import { useCallback, useState } from "react";
import { Alert, AlertDescription } from "@/shared/components/ui/alert";
import { Button } from "@/shared/components/ui/button";
import { Checkbox } from "@/shared/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import { Input } from "@/shared/components/ui/input";
import { maskApiKey } from "@/shared/utils/keyMasking";

interface ApiKeySuccessDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  apiKey: string;
  keyName: string;
}

export const ApiKeySuccessDialog: React.FC<ApiKeySuccessDialogProps> = ({
  open,
  onOpenChange,
  apiKey,
  keyName,
}) => {
  const [showKey, setShowKey] = useState(false);
  const [copied, setCopied] = useState(false);
  const [confirmed, setConfirmed] = useState(false);

  const displayKey = showKey ? apiKey : maskApiKey(apiKey);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(apiKey);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      console.error("Failed to copy API key:", error);
    }
  }, [apiKey]);

  const handleClose = useCallback(() => {
    if (confirmed) {
      onOpenChange(false);
      // Reset state for next time
      setShowKey(false);
      setCopied(false);
      setConfirmed(false);
    }
  }, [confirmed, onOpenChange]);

  const handleToggleVisibility = useCallback(() => {
    setShowKey((prev) => !prev);
  }, []);

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl" onPointerDownOutside={(e) => e.preventDefault()}>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Check className="h-5 w-5 text-green-600" />
            API Key Created Successfully
          </DialogTitle>
          <DialogDescription>
            Your API key "{keyName}" has been created. Please copy it now as it won't be shown
            again.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* Security Warning */}
          <Alert>
            <AlertTriangle className="h-4 w-4" />
            <AlertDescription>
              <strong>Important:</strong> This is the only time you'll see this key. Store it
              securely and don't share it. If you lose this key, you'll need to create a new one.
            </AlertDescription>
          </Alert>

          {/* API Key Display */}
          <div className="space-y-2">
            <label className="text-sm font-medium">API Key</label>
            <div className="flex gap-2">
              <Input
                value={displayKey}
                readOnly
                className="font-mono text-sm"
                type={showKey ? "text" : "password"}
              />
              <Button
                variant="outline"
                size="icon"
                onClick={handleToggleVisibility}
                className="flex-shrink-0"
              >
                {showKey ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </Button>
              <Button variant="outline" size="icon" onClick={handleCopy} className="flex-shrink-0">
                {copied ? (
                  <Check className="h-4 w-4 text-green-600" />
                ) : (
                  <Copy className="h-4 w-4" />
                )}
              </Button>
            </div>
          </div>

          {/* Usage Instructions */}
          <div className="bg-muted p-4 rounded-lg">
            <h4 className="font-medium mb-2">How to use this API key:</h4>
            <div className="text-sm text-muted-foreground space-y-1">
              <p>Include it in your API requests as a Bearer token:</p>
              <code className="block bg-background p-2 rounded text-xs mt-2">
                Authorization: Bearer {maskApiKey(apiKey, 12, 4)}
              </code>
            </div>
          </div>

          {/* Confirmation Checkbox */}
          <div className="flex items-center space-x-2">
            <Checkbox
              id="confirm-saved"
              checked={confirmed}
              onCheckedChange={(checked) => setConfirmed(checked === true)}
            />
            <label
              htmlFor="confirm-saved"
              className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
            >
              I have copied and securely stored this API key
            </label>
          </div>
        </div>

        <DialogFooter>
          <Button onClick={handleClose} disabled={!confirmed} className="w-full">
            {confirmed ? "Close" : "Please confirm you have saved the key"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
