import { AlertCircle, Mail, RotateCw } from "lucide-react";

import { Button } from "@/shared/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/shared/components/ui/card";

interface ConflictProps {
  registeredOrganization?: string;
}

/**
 * Shown in 3P (Databricks Marketplace) mode when the user's email is already
 * associated with a Prometheux account that was registered from a different
 * Databricks workspace (or via the regular web sign-up). Strict one-email
 * policy: we don't try to merge or migrate silently.
 */
export const DatabricksEmailConflictScreen = ({ registeredOrganization }: ConflictProps) => (
  <div className="flex min-h-screen items-center justify-center bg-background p-6">
    <Card className="w-full max-w-lg">
      <CardHeader className="space-y-3">
        <div className="flex h-12 w-12 items-center justify-center rounded-full bg-amber-100 dark:bg-amber-900/30">
          <AlertCircle className="h-6 w-6 text-amber-600 dark:text-amber-400" />
        </div>
        <CardTitle>Email already registered</CardTitle>
        <CardDescription>
          {registeredOrganization ? (
            <>
              The email address associated with your Databricks workspace is already linked to a
              Prometheux account on a different organization (
              <span className="font-medium">{registeredOrganization}</span>).
            </>
          ) : (
            <>
              The email address associated with your Databricks workspace is already linked to an
              existing Prometheux account.
            </>
          )}
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <p className="text-sm text-muted-foreground">
          For security reasons, each email can only be linked to a single Prometheux account. If you
          need to migrate this account to your new Databricks workspace, please contact our support
          team.
        </p>
        <Button asChild className="w-full">
          <a href="mailto:support@prometheux.ai?subject=Databricks%20account%20migration">
            <Mail className="mr-2 h-4 w-4" />
            Contact support@prometheux.ai
          </a>
        </Button>
      </CardContent>
    </Card>
  </div>
);

interface FatalProps {
  message?: string;
  onRetry?: () => void;
}

/**
 * Shown in 3P mode when the SSO bridge (server.js → Edge Function) fails for
 * any reason other than 409 conflict. Examples: SP token rejected, Supabase
 * temporarily unavailable, network glitch.
 */
export const DatabricksSsoErrorScreen = ({ message, onRetry }: FatalProps) => (
  <div className="flex min-h-screen items-center justify-center bg-background p-6">
    <Card className="w-full max-w-lg">
      <CardHeader className="space-y-3">
        <div className="flex h-12 w-12 items-center justify-center rounded-full bg-red-100 dark:bg-red-900/30">
          <AlertCircle className="h-6 w-6 text-red-600 dark:text-red-400" />
        </div>
        <CardTitle>We couldn't sign you in</CardTitle>
        <CardDescription>
          Something went wrong while connecting your Databricks identity to Prometheux. This is
          usually temporary.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {message ? (
          <pre className="overflow-auto rounded-md bg-muted p-3 text-xs text-muted-foreground">
            {message}
          </pre>
        ) : null}
        <div className="flex flex-col gap-2 sm:flex-row">
          <Button className="flex-1" onClick={onRetry ?? (() => window.location.reload())}>
            <RotateCw className="mr-2 h-4 w-4" />
            Try again
          </Button>
          <Button asChild variant="outline" className="flex-1">
            <a href="mailto:support@prometheux.ai?subject=Databricks%20sign-in%20issue">
              <Mail className="mr-2 h-4 w-4" />
              Contact support
            </a>
          </Button>
        </div>
      </CardContent>
    </Card>
  </div>
);
