import { Loader2, Pencil } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { ContextNoteApi } from "@/features/context-layer/api";
import { Button } from "@/shared/components/ui/button";
import type { ContextNoteKind, DocumentContextNote } from "./types";

interface EditableNoteCardProps {
  note: DocumentContextNote;
  onSaved: () => void;
}

function kindBadgeClass(kind: ContextNoteKind): string {
  switch (kind) {
    case "preference":
      return "bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400";
    case "fact":
      return "bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400";
    case "document_chunk":
      return "bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400";
    case "observation":
      return "bg-purple-50 text-purple-700 dark:bg-purple-900/20 dark:text-purple-400";
    default: {
      const _exhaustive: never = kind;
      return _exhaustive;
    }
  }
}

export function EditableNoteCard({ note, onSaved }: EditableNoteCardProps) {
  const [isEditing, setIsEditing] = useState(false);
  // Optimistic local copy of the note text. The save returns before the
  // parent's React Query refetch lands, so without this we'd flash the old
  // text after switching back to view mode. The effect below resyncs as soon
  // as the fresh prop arrives.
  const [displayText, setDisplayText] = useState(note.text);
  const [draft, setDraft] = useState(note.text);
  const [isSaving, setIsSaving] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  useEffect(() => {
    setDisplayText(note.text);
  }, [note.text]);

  useEffect(() => {
    if (isEditing) {
      textareaRef.current?.focus();
      // Place cursor at the end of the current text.
      const len = textareaRef.current?.value.length ?? 0;
      textareaRef.current?.setSelectionRange(len, len);
    }
  }, [isEditing]);

  const startEdit = () => {
    setDraft(displayText);
    setIsEditing(true);
  };

  const cancelEdit = () => {
    setDraft(displayText);
    setIsEditing(false);
  };

  const saveEdit = async () => {
    const trimmed = draft.trim();
    if (!trimmed) {
      toast.error("Note text cannot be empty");
      return;
    }
    if (trimmed === displayText.trim()) {
      setIsEditing(false);
      return;
    }
    setIsSaving(true);
    try {
      await ContextNoteApi.update(note.id, { text: trimmed });
      setDisplayText(trimmed);
      setIsEditing(false);
      onSaved();
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to update note";
      toast.error(message);
    } finally {
      setIsSaving(false);
    }
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      cancelEdit();
      return;
    }
    if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
      event.preventDefault();
      saveEdit();
    }
  };

  if (isEditing) {
    return (
      <li className="rounded-lg border border-border bg-card px-4 py-3 text-sm">
        <div className="flex items-center gap-2">
          <span
            className={`rounded px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide ${kindBadgeClass(note.kind)}`}
          >
            {note.kind.replace("_", " ")}
          </span>
        </div>
        <textarea
          ref={textareaRef}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={handleKeyDown}
          rows={Math.max(3, Math.min(10, draft.split("\n").length + 1))}
          disabled={isSaving}
          className="mt-2 w-full resize-y rounded-md border border-input bg-background px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50"
        />
        <div className="mt-2 flex items-center justify-end gap-2">
          <span className="mr-auto text-[11px] text-muted-foreground">
            ⌘/Ctrl + Enter to save · Esc to cancel
          </span>
          <Button variant="ghost" size="sm" onClick={cancelEdit} disabled={isSaving} type="button">
            Cancel
          </Button>
          <Button
            size="sm"
            onClick={saveEdit}
            disabled={isSaving}
            className="gap-1.5"
            type="button"
          >
            {isSaving ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                Saving…
              </>
            ) : (
              "Save"
            )}
          </Button>
        </div>
      </li>
    );
  }

  return (
    <li className="group relative rounded-lg border border-border bg-card px-4 py-3 text-sm">
      <div className="flex items-center gap-2">
        <span
          className={`rounded px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide ${kindBadgeClass(note.kind)}`}
        >
          {note.kind.replace("_", " ")}
        </span>
        <button
          type="button"
          onClick={startEdit}
          title="Edit note"
          className="ml-auto rounded p-1 text-muted-foreground opacity-0 transition-opacity hover:bg-muted hover:text-foreground focus:opacity-100 focus:outline-none focus:ring-2 focus:ring-primary group-hover:opacity-100"
        >
          <Pencil className="h-3.5 w-3.5" />
        </button>
      </div>
      <p className="mt-2 whitespace-pre-wrap text-foreground">{displayText}</p>
    </li>
  );
}
