import { MessageSquareText } from "lucide-react";
import { useLocation } from "react-router-dom";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { MessageSquareIcon } from "@/shared/components/icons/MessageSquareIcon";
import { cn } from "@/shared/lib/utils";
import { trackAssistantOpened } from "@/shared/services/analyticsEvents";
// The home page embeds the chat inline, so the launcher is hidden there.
import { isHomePath } from "@/shared/utils/isHomePath";

interface SidebarAssistantItemProps {
  collapsed: boolean;
}

/**
 * Bottom-dock launcher for the AI assistant. Rendered as a full-width, always-lit
 * nav row using the same muted-gray surface as the docked chat panel, so the
 * launcher reads as an extension of that surface and stands apart from the
 * transparent nav rows around it. The icon still conveys state: an outline glyph when no
 * conversation exists, the filled variant once one is in progress (pulsing while
 * the agent streams). Owns its own bordered section so the gating below keeps the
 * surrounding layout clean when the launcher is hidden.
 */
export function SidebarAssistantItem({ collapsed }: SidebarAssistantItemProps) {
  const { pathname } = useLocation();
  const canSeeAiAgent = usePermissionsStore((state) => state.canSee("can_see_ai_agent"));
  const isPanelOpen = useCodeAssistantStore((state) => state.isPanelOpen);
  const openPanel = useCodeAssistantStore((state) => state.openPanel);
  const closePanel = useCodeAssistantStore((state) => state.closePanel);
  const hasConversation = useCodeAssistantStore((state) => state.messages.length > 0);
  const isStreaming = useCodeAssistantStore((state) => state.isLoading);

  if (!canSeeAiAgent || isHomePath(pathname)) return null;

  const Icon = hasConversation ? MessageSquareText : MessageSquareIcon;
  // Toggle visibility using the open/close actions so closing also marks the
  // panel user-closed — otherwise the App auto-open effect re-opens it.
  const handleToggle = () => {
    if (isPanelOpen) {
      closePanel();
      return;
    }
    trackAssistantOpened("sidebar");
    openPanel();
  };

  return (
    <div className="border-b">
      <button
        onClick={handleToggle}
        title={collapsed ? "AI Assistant" : undefined}
        aria-label="Toggle AI Assistant"
        aria-pressed={isPanelOpen}
        className={cn(
          "flex h-9 w-full items-center gap-3 border-l-2 border-primary px-3 text-sm font-medium",
          "bg-muted text-foreground transition-colors hover:bg-border",
          collapsed && "justify-center border-l-0 px-0",
        )}
      >
        <Icon className={cn("h-4 w-4 shrink-0", isStreaming && "animate-pulse")} />
        {!collapsed && <span className="truncate">AI Assistant</span>}
      </button>
    </div>
  );
}
