import { getComputePayload } from "@/features/concept-editor/api/computePayload";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import type {
  ContextRevisions,
  CurrentDashboard,
  FocusedConcept,
  FocusedWidgetRef,
} from "./agentContext";
import { parseCredentialRequest } from "./credentialRequest.utils";
import { type HaltData, parseHalt } from "./halt.utils";
import type {
  AuthorizationData,
  ClarificationData,
  ContextLoadedData,
  CredentialRequestData,
  PlanStep,
  ProposalData,
  ToolProgressData,
  WriterProposalData,
} from "./store";

/**
 * Stable contract with the Python backend: when a freemium account has used its
 * monthly agent-message quota, the chat endpoint refuses with HTTP 402 and a body
 * of { code: "AGENT_MESSAGE_LIMIT_REACHED", used, limit, resets_at }.
 */
export const AGENT_MESSAGE_LIMIT_CODE = "AGENT_MESSAGE_LIMIT_REACHED";

export class AgentMessageLimitError extends Error {
  readonly used: number;
  readonly limit: number;
  readonly resetsAt: string | null;

  constructor(used: number, limit: number, resetsAt: string | null) {
    super(`Monthly agent message limit reached (${used}/${limit})`);
    this.name = "AgentMessageLimitError";
    this.used = used;
    this.limit = limit;
    this.resetsAt = resetsAt;
  }
}

interface AgentLimitBody {
  code: string;
  used?: number;
  limit?: number;
  resets_at?: string;
}

const isAgentLimitBody = (value: unknown): value is AgentLimitBody => {
  if (typeof value !== "object" || value === null) return false;
  const body = value as Record<string, unknown>;
  return body.code === AGENT_MESSAGE_LIMIT_CODE;
};

const parseAgentLimitError = (rawBody: string): AgentMessageLimitError | null => {
  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    return null;
  }
  if (!isAgentLimitBody(parsed)) return null;
  return new AgentMessageLimitError(
    typeof parsed.used === "number" ? parsed.used : 0,
    typeof parsed.limit === "number" ? parsed.limit : 0,
    typeof parsed.resets_at === "string" ? parsed.resets_at : null,
  );
};

interface SendAgentMessageParams {
  ontologyId: string;
  message: string;
  sessionId: string;
  authToken: string;
  supabaseToken?: string;
  /** Per-message model override (e.g. "gpt-4o", "claude-sonnet-4-6"). */
  model?: string;
  /**
   * Server-side paths (as returned by /data/files/upload, e.g.
   * "disk/<filename>") for files the user attached to this turn. The
   * backend extracts text from each and prepends labeled blocks to the
   * user message before passing it to the LLM.
   */
  attachmentPaths?: string[];
  /**
   * 0-based index of the user message being edited. When set, the backend
   * truncates the conversation (in-memory + persisted) at that user turn and
   * re-runs from `message`. Omitted for normal turns.
   */
  editFromUserTurn?: number;
  /**
   * Marks a message this app composed rather than the user typing it (an
   * authorization decision, a resume after a halt), so the backend does not
   * put it through the scope pre-check as a standalone request.
   */
  continuation?: boolean;
  /** Concept open in the editor — sent every turn so "fix this" stays accurate. */
  focusedConcept?: FocusedConcept | null;
  /** Dashboard currently being viewed — sent every turn. */
  currentDashboard?: CurrentDashboard | null;
  /** App widget the user selected in the editor ("Ask AI about this widget") —
   * a one-shot structured reference for this turn. */
  focusedWidget?: FocusedWidgetRef | null;
  /** Revision counters; the backend refreshes project context when they move. */
  contextRevisions?: ContextRevisions;
  /**
   * Consent policy for this turn. `mode` "ask" makes the assistant read-only;
   * `authorizedTools` is the standing allow-list; `approvedCalls` are one-shot
   * action approvals (keyed on tool+args). Sending `mode` at all is what turns
   * interactive authorization on server-side, so it's always included.
   */
  mode?: string;
  authorizedTools?: string[];
  approvedCalls?: string[];
  signal?: AbortSignal;
  onChunk: (chunk: string) => void;
  /** Streamed extended-thinking/reasoning deltas (Anthropic), shown separately from the answer. */
  onThinking?: (chunk: string) => void;
  onModel?: (model: string) => void;
  onToolStart?: (tool: string, input: Record<string, unknown>) => void;
  onToolResult?: (tool: string, result: Record<string, unknown>) => void;
  onToolProgress?: (tool: string, progress: ToolProgressData) => void;
  onProposal?: (data: ProposalData) => void;
  onContextLoaded?: (data: ContextLoadedData) => void;
  onWriterProposal?: (data: WriterProposalData) => void;
  onClarification?: (data: ClarificationData) => void;
  onAuthorizationRequest?: (data: AuthorizationData) => void;
  onCredentialRequest?: (data: CredentialRequestData) => void;
  onHalted?: (data: HaltData) => void;
  onPlan?: (steps: PlanStep[], planId?: string) => void;
  onSessionMeta?: (data: { session_id: string; title: string }) => void;
  onDone?: () => void;
}

const isPlanStep = (value: unknown): value is PlanStep => {
  if (typeof value !== "object" || value === null) return false;
  const step = value as Record<string, unknown>;
  return typeof step.content === "string" && typeof step.status === "string";
};

/**
 * Calls POST /agent/{projectId}/chat and streams the NDJSON response.
 * Handles metadata, content, tool_start, tool_result, proposal, done, and error events.
 */
export async function sendAgentMessage({
  ontologyId,
  message,
  sessionId,
  authToken,
  supabaseToken,
  attachmentPaths,
  editFromUserTurn,
  continuation,
  focusedConcept,
  currentDashboard,
  focusedWidget,
  contextRevisions,
  model,
  mode,
  authorizedTools,
  approvedCalls,
  signal,
  onChunk,
  onThinking,
  onModel,
  onToolStart,
  onToolResult,
  onToolProgress,
  onProposal,
  onContextLoaded,
  onWriterProposal,
  onClarification,
  onAuthorizationRequest,
  onCredentialRequest,
  onHalted,
  onPlan,
  onSessionMeta,
  onDone,
}: SendAgentMessageParams): Promise<void> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/agent/${ontologyId}/chat`;

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${authToken}`,
  };
  if (supabaseToken) {
    headers["X-Supabase-Token"] = supabaseToken;
  }

  const body: Record<string, unknown> = { message, session_id: sessionId };
  if (attachmentPaths && attachmentPaths.length > 0) {
    body.attachment_paths = attachmentPaths;
  }
  if (model) {
    body.model = model;
  }
  if (typeof editFromUserTurn === "number") {
    body.edit_from_user_turn = editFromUserTurn;
  }
  if (continuation) {
    body.continuation = true;
  }
  if (focusedConcept) {
    body.focused_concept = focusedConcept;
  }
  if (currentDashboard) {
    body.current_dashboard = currentDashboard;
  }
  if (focusedWidget) {
    body.focused_widget = focusedWidget;
  }
  if (contextRevisions) {
    body.context_revisions = contextRevisions;
  }
  // Always send the mode: its presence is the backend's signal that this client
  // understands interactive authorization (an older client omits it and keeps
  // the previous permissive behavior).
  body.mode = mode ?? "agent";
  if (authorizedTools && authorizedTools.length > 0) {
    body.authorized_tools = authorizedTools;
  }
  if (approvedCalls && approvedCalls.length > 0) {
    body.approved_calls = approvedCalls;
  }
  // The assistant runs server-side and cannot see the compute selection held in
  // localStorage, and the backend's copy is in-memory only — so it is gone after
  // a restart. Sending it with every message makes that invisible: the user's
  // Databricks cluster keeps being used without them having to re-enter
  // anything. Only databricks_configs is read on this endpoint.
  const compute = await getComputePayload();
  if (compute?.databricks_configs) {
    body.compute = compute;
  }

  const response = await fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
    mode: "cors",
    signal,
  });

  if (!response.ok) {
    const text = await response.text();
    if (response.status === 402) {
      const limitError = parseAgentLimitError(text);
      if (limitError) throw limitError;
    }
    throw new Error(`Request failed (${response.status}): ${text}`);
  }

  if (!response.body) {
    throw new Error("Streaming not supported by this browser");
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });

      // NDJSON: split on newlines, keep incomplete last line in buffer
      const lines = buffer.split("\n");
      buffer = lines.pop() ?? "";

      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed) continue;
        try {
          const parsed = JSON.parse(trimmed);
          const { type, data } = parsed;

          if (type === "metadata" && data?.model && onModel) {
            onModel(data.model);
          } else if (type === "content" && data?.chunk) {
            onChunk(data.chunk);
          } else if (type === "thinking" && data?.chunk && onThinking) {
            onThinking(data.chunk);
          } else if (type === "tool_start" && onToolStart) {
            onToolStart(data?.tool ?? "", data?.input ?? {});
          } else if (type === "tool_result" && onToolResult) {
            onToolResult(data?.tool ?? "", data?.result ?? {});
          } else if (type === "tool_progress" && onToolProgress && data) {
            // Backend yields zero-based `index` per chunk; convert to 1-based
            // `current` for display ("chunk 3 of 10" rather than "chunk 2").
            // Skip dispatch entirely when `data` is null/undefined — an
            // empty progress event just clutters the chat without info.
            const idx = typeof data.index === "number" ? data.index : undefined;
            const total = typeof data.total === "number" ? data.total : undefined;
            onToolProgress(data.tool ?? "", {
              event: data.event ?? "",
              current: idx !== undefined ? idx + 1 : undefined,
              total,
              label: typeof data.label === "string" ? data.label : undefined,
              filename: typeof data.filename === "string" ? data.filename : undefined,
              document_id: typeof data.document_id === "string" ? data.document_id : undefined,
            });
          } else if (type === "proposal" && onProposal) {
            onProposal(data as ProposalData);
          } else if (type === "context_loaded" && onContextLoaded) {
            onContextLoaded(data as ContextLoadedData);
          } else if (type === "writer_proposal" && onWriterProposal) {
            onWriterProposal(data as WriterProposalData);
          } else if (type === "clarification" && onClarification) {
            onClarification(data as ClarificationData);
          } else if (type === "authorization_request" && onAuthorizationRequest) {
            onAuthorizationRequest({
              tool: typeof data?.tool === "string" ? data.tool : "",
              callKey: typeof data?.call_key === "string" ? data.call_key : "",
              persistable: data?.persistable !== false,
              input:
                data?.input && typeof data.input === "object"
                  ? (data.input as Record<string, unknown>)
                  : {},
            });
          } else if (type === "credential_request" && onCredentialRequest) {
            onCredentialRequest(parseCredentialRequest(data));
          } else if (type === "halted" && onHalted) {
            onHalted(parseHalt(data));
          } else if (type === "plan" && onPlan) {
            const steps = Array.isArray(data?.steps) ? data.steps.filter(isPlanStep) : [];
            const planId = typeof data?.plan_id === "string" ? data.plan_id : undefined;
            onPlan(steps, planId);
          } else if (type === "session_meta" && onSessionMeta && data) {
            onSessionMeta(data as { session_id: string; title: string });
          } else if (type === "done" && onDone) {
            onDone();
          } else if (type === "error") {
            throw new Error(data?.error ?? "Unknown error from server");
          }
        } catch (e) {
          if (e instanceof SyntaxError) continue; // malformed line, skip
          throw e;
        }
      }
    }
  } finally {
    reader.releaseLock();
  }
}
