import type { FetchResult } from "../../api/ConceptClient";
import type { DashboardWidget } from "../../types";

interface ChannelGridWidgetProps {
  data: FetchResult;
  widget: DashboardWidget;
}

export function ChannelGridWidget({ data, widget }: ChannelGridWidgetProps) {
  const items = data.rows.map((row) => ({
    name: row[widget.xCol] != null ? String(row[widget.xCol]) : "—",
    value: row[widget.yCol] != null ? String(row[widget.yCol]) : "—",
  }));

  if (items.length === 0) {
    return <p className="text-xs text-muted-foreground py-4">No data</p>;
  }

  return (
    <div className="grid grid-cols-2 gap-2">
      {items.map((item, i) => (
        <div key={i} className="bg-secondary/50 border border-border rounded-md p-3">
          <div className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground mb-1">
            {item.name}
          </div>
          <div className="text-2xl font-semibold tracking-tight text-foreground leading-none">
            {item.value}
          </div>
        </div>
      ))}
    </div>
  );
}
