import type React from "react";
import type { AppHostSdk } from "@/shared/app-sdk/types";

export interface AppTabProps {
  onToggleSidebar?: () => void;
  sidebarVisible?: boolean;
  name?: string;
  description?: string;
  // Provided to federated (remote) client apps so they can talk to the backend the same
  // way in-tree apps do. Optional because local apps import host modules directly instead.
  ontologyId?: string;
  sdk?: AppHostSdk;
}

export interface DashboardEntry {
  id: string;
  name: string;
  description?: string;
  // Local apps (build-time bundled) carry a component; remote client apps (federated,
  // loaded at runtime) carry a remoteUrl instead. Exactly one is set.
  component?: React.ComponentType<AppTabProps>;
  componentName?: string;
  remoteUrl?: string;
}

// Eagerly import all app components. The filename (without extension) is the
// canonical component name — it must match the "component" field in permissions.
const appModules = import.meta.glob("./components/**/*App*.tsx", { eager: true });

export const COMPONENT_MAP: Record<string, React.ComponentType<AppTabProps>> = {};

for (const [path, module] of Object.entries(appModules)) {
  const filename = path.split("/").pop()!.replace(".tsx", "");
  const mod = module as { default?: React.ComponentType<AppTabProps> };
  if (mod.default) {
    COMPONENT_MAP[filename] = mod.default;
  }
}
