import { zodResolver } from "@hookform/resolvers/zod";
import { ArrowRight } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { useForm } from "react-hook-form";
import { z } from "zod";
import { useOnboardingSubmit } from "@/features/onboarding/hooks/useOnboardingSubmit";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import { type OrganizationType, OrganizationTypeSelector } from "./OrganizationTypeSelector";

const onboardingSchema = z.object({
  firstName: z.string().min(1, "First name is required"),
  lastName: z.string().min(1, "Last name is required"),
  username: z
    .string()
    .min(3, "Username must be at least 3 characters")
    .max(30, "Username must be at most 30 characters")
    .regex(
      /^[a-zA-Z0-9_-]+$/,
      "Username can only contain letters, numbers, underscores, and hyphens",
    ),
});

type OnboardingFormData = z.infer<typeof onboardingSchema>;

interface OnboardingFormProps {
  onSuccess: () => void;
  userEmail?: string;
}

export const OnboardingForm: React.FC<OnboardingFormProps> = ({ onSuccess, userEmail }) => {
  const [organizationType, setOrganizationType] = useState<OrganizationType | null>(null);
  const [organizationName, setOrganizationName] = useState("");
  const [orgError, setOrgError] = useState<string | undefined>();

  const { submitOnboarding, isSubmitting } = useOnboardingSubmit();

  const form = useForm<OnboardingFormData>({
    resolver: zodResolver(onboardingSchema),
    defaultValues: {
      firstName: "",
      lastName: "",
      username: "",
    },
  });

  const validateOrganization = (): boolean => {
    if (!organizationType) {
      setOrgError("Please select how you will use Prometheux");
      return false;
    }
    if (organizationType === "organization" && !organizationName.trim()) {
      setOrgError("Please enter your organization name");
      return false;
    }
    setOrgError(undefined);
    return true;
  };

  const onSubmit = async (data: OnboardingFormData) => {
    if (!validateOrganization()) {
      return;
    }

    const success = await submitOnboarding({
      firstName: data.firstName,
      lastName: data.lastName,
      username: data.username,
      organizationType: organizationType!,
      organizationName: organizationType === "organization" ? organizationName : undefined,
    });

    if (success) {
      onSuccess();
    }
  };

  const handleOrganizationTypeChange = (type: OrganizationType) => {
    setOrganizationType(type);
    setOrgError(undefined);
    if (type === "solo") {
      setOrganizationName("");
    }
  };

  return (
    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
      {/* Welcome Header */}
      <div className="text-center space-y-2 pb-2">
        <h2 className="text-2xl font-semibold text-foreground">Complete your profile</h2>
        <p className="text-sm text-muted-foreground">Tell us a bit about yourself to get started</p>
        {userEmail && (
          <p className="text-xs text-muted-foreground">
            Signed in as <span className="font-medium">{userEmail}</span>
          </p>
        )}
      </div>

      {/* Name Fields - Side by Side */}
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="firstName" className="text-sm font-medium">
            First Name
          </Label>
          <Input
            id="firstName"
            type="text"
            placeholder="John"
            {...form.register("firstName")}
            className={form.formState.errors.firstName ? "border-destructive" : ""}
          />
          {form.formState.errors.firstName && (
            <p className="text-sm text-destructive">{form.formState.errors.firstName.message}</p>
          )}
        </div>

        <div className="space-y-2">
          <Label htmlFor="lastName" className="text-sm font-medium">
            Last Name
          </Label>
          <Input
            id="lastName"
            type="text"
            placeholder="Doe"
            {...form.register("lastName")}
            className={form.formState.errors.lastName ? "border-destructive" : ""}
          />
          {form.formState.errors.lastName && (
            <p className="text-sm text-destructive">{form.formState.errors.lastName.message}</p>
          )}
        </div>
      </div>

      {/* Username Field */}
      <div className="space-y-2">
        <Label htmlFor="username" className="text-sm font-medium">
          Username
        </Label>
        <Input
          id="username"
          type="text"
          placeholder="johndoe"
          {...form.register("username")}
          className={form.formState.errors.username ? "border-destructive" : ""}
        />
        <p className="text-xs text-muted-foreground">
          This will be your unique identifier and cannot be changed later
        </p>
        {form.formState.errors.username && (
          <p className="text-sm text-destructive">{form.formState.errors.username.message}</p>
        )}
      </div>

      {/* Organization Type Selector */}
      <OrganizationTypeSelector
        selectedType={organizationType}
        onTypeChange={handleOrganizationTypeChange}
        organizationName={organizationName}
        onOrganizationNameChange={setOrganizationName}
        error={orgError}
      />

      {/* Submit Button */}
      <Button type="submit" disabled={isSubmitting} className="w-full h-11 text-base font-medium">
        {isSubmitting ? (
          <>
            <PrometheuxSpinner size={16} className="mr-2" />
            Setting up your account...
          </>
        ) : (
          <>
            Continue
            <ArrowRight className="ml-2 h-4 w-4" />
          </>
        )}
      </Button>
    </form>
  );
};
