import type React from "react";
import { ExplorerSearchBar } from "@/features/concept-editor/components/ExplorerSearchBar";
import type { ConceptCell } from "@/features/concept-editor/types";
import { ContextNotesPanel } from "@/features/context-layer/explorer-panel/ContextNotesPanel";
import { getGroupIconType, getStorageIconType } from "@/features/data-sources/utils";
import { useOntologyId } from "@/features/ontologies/hooks/useOntologyId";
import DatabaseIcon from "@/shared/components/icons/DatabaseIcon";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/shared/components/ui/accordion";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import { useLibrarySidebar } from "../hooks/useLibrarySidebar";
import { conceptParams } from "../utils/paramAnnotations";
import ConceptCard from "./ConceptCard";
import DataSourceCard from "./DataSourceCard";
import { LibrarySidebarHeader } from "./LibrarySidebarHeader";

export type LibraryPanel = "concepts" | "data" | "context";

interface ConceptLibrarySidebarProps {
  panel: LibraryPanel;
  cells: ConceptCell[];
  onRefreshCells?: () => Promise<void>;
  /** Opens a context note in the Explorer's bottom dock (Context panel). */
  onOpenContextNote?: (noteId: string, conceptName?: string) => void;
  /** Starts a new project-note draft in the dock (Context panel's plus). */
  onCreateContextNote?: () => void;
}

const ConceptLibrarySidebar: React.FC<ConceptLibrarySidebarProps> = ({
  panel,
  cells,
  onRefreshCells,
  onOpenContextNote,
  onCreateContextNote,
}) => {
  const lib = useLibrarySidebar({ panel, onRefreshCells });
  const ontologyId = useOntologyId();

  const renderPanel = () => {
    if (panel === "concepts") return renderConcepts();
    if (panel === "context") {
      return (
        <ContextNotesPanel
          ontologyId={ontologyId ?? ""}
          searchTerm={lib.searchTerm}
          onOpenNote={(noteId, conceptName) => onOpenContextNote?.(noteId, conceptName)}
        />
      );
    }
    return renderData();
  };

  const renderConcepts = () => {
    if (lib.conceptsLoading) {
      return <p className="p-4 text-center text-muted-foreground">Loading concepts...</p>;
    }
    if (lib.filteredConcepts.length === 0) {
      return (
        <div className="p-4 text-center text-muted-foreground">
          <p>{lib.searchTerm ? "No concepts match your search" : "No concepts found"}</p>
          <p className="text-sm mt-2">
            {lib.searchTerm
              ? "Try a different search term"
              : "Create concepts in cells or ontology nodes to see them here"}
          </p>
        </div>
      );
    }
    return lib.filteredConcepts.map((concept) => {
      const cell = cells.find((c) => c.outputPredicate === concept.predicate_name);
      const description =
        cell?.description ||
        concept.description ||
        `Concept with ${concept.column_count || 0} fields`;
      return (
        <ConceptCard
          key={concept.predicate_name}
          title={concept.predicate_name}
          description={description}
          fields={concept.fields || {}}
          params={conceptParams(concept)}
          onNavigateToCell={() => lib.handleNavigateToCell(concept.predicate_name)}
          expandSignal={lib.expandSignal}
        />
      );
    });
  };

  const renderData = () => {
    if (lib.dataLoading) {
      return <p className="p-4 text-center text-muted-foreground">Loading datasources...</p>;
    }
    if (lib.groupedDataSources.length === 0) {
      return (
        <div className="p-4 text-center text-muted-foreground">
          <p>{lib.searchTerm ? "No datasources match your search" : "No datasources found"}</p>
          <p className="text-sm mt-2">
            {lib.searchTerm
              ? "Try a different search term"
              : "Connect datasources from the Data page to see them here"}
          </p>
        </div>
      );
    }
    return (
      <Accordion
        type="multiple"
        className="space-y-2"
        value={lib.dataGroupValue}
        onValueChange={lib.setDataGroupValue}
      >
        {lib.groupedDataSources.map((locationGroup) =>
          locationGroup.subGroups.map((subGroup) => {
            const id = lib.groupId(locationGroup.location, subGroup.name);
            const showLocation =
              locationGroup.location !== "Unknown" && locationGroup.location !== subGroup.name;
            return (
              <AccordionItem key={id} value={id} className="border rounded-lg bg-card">
                <AccordionTrigger className="px-3 py-2.5 hover:no-underline">
                  <div className="flex items-center gap-2 flex-1 min-w-0">
                    <DatabaseIcon
                      type={getGroupIconType(subGroup.name, subGroup.type)}
                      className="h-4 w-4 flex-shrink-0"
                    />
                    <div className="flex flex-col items-start flex-1 min-w-0">
                      <span className="font-medium text-sm truncate max-w-full">
                        {subGroup.name.charAt(0).toUpperCase() + subGroup.name.slice(1)}
                      </span>
                      {showLocation && (
                        <TooltipProvider>
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <span className="text-xs text-muted-foreground truncate max-w-full block">
                                {locationGroup.location}
                              </span>
                            </TooltipTrigger>
                            <TooltipContent side="bottom" className="max-w-sm break-all">
                              <p>{locationGroup.location}</p>
                            </TooltipContent>
                          </Tooltip>
                        </TooltipProvider>
                      )}
                    </div>
                    <span className="text-xs text-muted-foreground mr-1 flex-shrink-0">
                      {subGroup.dataSources.length}{" "}
                      {subGroup.dataSources.length === 1 ? "source" : "sources"}
                    </span>
                  </div>
                </AccordionTrigger>
                <AccordionContent className="px-2 pb-1 pt-0">
                  {subGroup.typeGroups.length > 1 && getStorageIconType(subGroup.name) !== null ? (
                    <Accordion type="multiple" className="w-full">
                      {subGroup.typeGroups.map((typeGroup) => (
                        <AccordionItem
                          key={typeGroup.type}
                          value={`${id}_${typeGroup.type}`}
                          className="border-b last:border-b-0"
                        >
                          <AccordionTrigger className="px-2 py-2 hover:no-underline">
                            <div className="flex items-center gap-2 flex-1 min-w-0">
                              <DatabaseIcon
                                type={typeGroup.type}
                                className="h-3.5 w-3.5 flex-shrink-0"
                              />
                              <span className="font-medium text-xs truncate">{typeGroup.type}</span>
                              <span className="text-xs text-muted-foreground">
                                {typeGroup.dataSources.length}
                              </span>
                            </div>
                          </AccordionTrigger>
                          <AccordionContent className="px-0 pb-0">
                            <div className="divide-y divide-border/40">
                              {typeGroup.dataSources.map((ds) => (
                                <DataSourceCard
                                  key={ds.id}
                                  tableName={ds.tableName}
                                  datasourceType={ds.datasourceType}
                                  predicatePlaceholder={ds.predicatePlaceholder}
                                  fields={ds.fields}
                                  columnCount={ds.columnCount}
                                  rowCount={ds.rowCount}
                                  databaseName={ds.databaseName}
                                  onCreateConcept={() => lib.handleCreateConcept(ds)}
                                  flat
                                />
                              ))}
                            </div>
                          </AccordionContent>
                        </AccordionItem>
                      ))}
                    </Accordion>
                  ) : (
                    <div className="divide-y divide-border/40">
                      {subGroup.dataSources.map((ds) => (
                        <DataSourceCard
                          key={ds.id}
                          tableName={ds.tableName}
                          datasourceType={ds.datasourceType}
                          predicatePlaceholder={ds.predicatePlaceholder}
                          fields={ds.fields}
                          columnCount={ds.columnCount}
                          rowCount={ds.rowCount}
                          databaseName={ds.databaseName}
                          onCreateConcept={() => lib.handleCreateConcept(ds)}
                          flat
                        />
                      ))}
                    </div>
                  )}
                </AccordionContent>
              </AccordionItem>
            );
          }),
        )}
      </Accordion>
    );
  };

  return (
    <div
      className="h-full bg-background border-l border-border flex flex-col flex-shrink-0"
      style={{ width: "330px", maxWidth: "330px" }}
    >
      <LibrarySidebarHeader
        title={lib.panelTitle}
        isSearchOpen={lib.isSearchOpen}
        isSearchActive={!!lib.searchTerm.trim()}
        onToggleSearch={lib.toggleSearch}
        allExpanded={lib.allExpanded}
        onToggleExpandAll={lib.toggleExpandAll}
        onRefresh={lib.handleRefresh}
        isRefreshing={lib.isRefreshing}
        onCreate={panel === "context" ? onCreateContextNote : undefined}
        createLabel="New ontology note"
      />

      {lib.isSearchOpen && (
        <ExplorerSearchBar
          value={lib.searchTerm}
          onChange={lib.setSearchTerm}
          onClose={lib.closeSearch}
          placeholder={lib.searchPlaceholder}
        />
      )}

      <div
        className="flex-1 min-h-0 overflow-y-auto pl-2 pr-2 pb-4 pt-2"
        style={{ scrollbarGutter: "stable" }}
      >
        <div className="space-y-2">{renderPanel()}</div>
      </div>
    </div>
  );
};

export default ConceptLibrarySidebar;
