import { useEffect, useRef } from "react";
import { useSearchParams } from "react-router-dom";
import { toast } from "sonner";
import { type ConceptData, ConceptService } from "@/features/concepts/api";
import { conceptGraphReady, findConceptGraph } from "../model.utils";
import type { ConceptGraphRoles, GraphViewModel } from "../types";
import { resolveDerivedOutput } from "./useConceptOutputs";

interface UseConceptGraphDeepLinkParams {
  ontologyId: string;
  scope: string;
  /** Deep-link handling waits for the model so saving roles cannot clobber it. */
  isModelLoading: boolean;
  model: GraphViewModel | null;
  /** Predicate of the concept graph currently shown (null in model mode). */
  predicate: string | null;
  saveRoles: (predicate: string, roles: ConceptGraphRoles) => void;
  showGraph: (concept: ConceptData, roles: ConceptGraphRoles, runPredicate?: string) => void;
  /** Called when the concept has no usable roles yet — the page should let
   * the user pick them. `cardPredicate` is the concept card holding the
   * output (the parent concept when the predicate is a derived rule head). */
  onNeedsRoles: (concept: ConceptData, cardPredicate: string) => void;
  /** Called when a deep link resolves — the page should surface the selection (open the panel). */
  onOpened: (concept: ConceptData, cardPredicate: string) => void;
}

function rolesFromParams(params: URLSearchParams): ConceptGraphRoles {
  return {
    source_column: params.get("source") ?? undefined,
    target_column: params.get("target") ?? undefined,
    edge_label_column: params.get("label") ?? undefined,
  };
}

/**
 * Two-way sync between the URL and the concept graph, so the current view is
 * shareable and survives refresh.
 *
 * Inbound — /graph-explorer?concept=X[&columns=A,B][&source=&target=&label=]:
 * roles come from the URL (output-table hand-off) or the saved model; with
 * neither, the page is asked to open the role picker. The transient role
 * params are cleared after being persisted; `concept` and `columns` stay.
 *
 * Outbound — showing a concept graph writes ?concept=X (history replaced);
 * returning to model mode removes it.
 */
export function useConceptGraphDeepLink({
  ontologyId,
  scope,
  isModelLoading,
  model,
  predicate,
  saveRoles,
  showGraph,
  onNeedsRoles,
  onOpened,
}: UseConceptGraphDeepLinkParams): void {
  const [searchParams, setSearchParams] = useSearchParams();
  const processedRef = useRef<string | null>(null);
  const lastShownRef = useRef<string | null>(null);

  const callbacksRef = useRef({ saveRoles, showGraph, onNeedsRoles, onOpened });
  callbacksRef.current = { saveRoles, showGraph, onNeedsRoles, onOpened };
  const modelRef = useRef(model);
  modelRef.current = model;

  const conceptParam = searchParams.get("concept");

  // Inbound: open the concept graph described by the URL.
  useEffect(() => {
    if (!conceptParam || isModelLoading) return;
    if (processedRef.current === conceptParam) return;
    processedRef.current = conceptParam;

    const urlRoles = rolesFromParams(searchParams);

    // Fallback schema for predicates that are not saved concepts (e.g.
    // intermediate rules): the output table passes its column list along.
    const columnsParam = searchParams.get("columns");
    const fallbackConcept: ConceptData | null = columnsParam
      ? {
          predicate_name: conceptParam,
          column_names: columnsParam.split(","),
          is_populated: true,
        }
      : null;

    const clearParams = (keys: string[]) => {
      setSearchParams(
        (previous) => {
          const next = new URLSearchParams(previous);
          for (const key of keys) next.delete(key);
          return next;
        },
        { replace: true },
      );
    };

    const open = async () => {
      try {
        const concepts = await ConceptService.listConcepts(ontologyId, scope);
        let runPredicate: string | undefined;
        let concept = concepts.find((candidate) => candidate.predicate_name === conceptParam);
        if (!concept) {
          // Not a saved concept — maybe a derived output (intermediate rule
          // head) of one; resolve its schema and parent via rule analysis.
          const derived = await resolveDerivedOutput(concepts, conceptParam);
          if (derived) {
            concept = derived.concept;
            runPredicate = derived.parentPredicate;
          }
        }
        concept = concept ?? fallbackConcept ?? undefined;
        if (!concept) {
          toast.error(`Concept "${conceptParam}" was not found in this ontology`);
          clearParams(["concept", "columns", "source", "target", "label"]);
          return;
        }
        const cardPredicate = runPredicate ?? concept.predicate_name;
        callbacksRef.current.onOpened(concept, cardPredicate);
        const savedRoles = findConceptGraph(modelRef.current, conceptParam)?.roles ?? {};
        const roles = conceptGraphReady(urlRoles) ? urlRoles : savedRoles;
        if (!conceptGraphReady(roles)) {
          callbacksRef.current.onNeedsRoles(concept, cardPredicate);
          clearParams(["source", "target", "label"]);
          return;
        }
        if (conceptGraphReady(urlRoles)) {
          callbacksRef.current.saveRoles(conceptParam, roles);
        }
        callbacksRef.current.showGraph(concept, roles, runPredicate);
        clearParams(["source", "target", "label"]);
      } catch {
        toast.error("Failed to open the concept graph");
        clearParams(["concept", "columns", "source", "target", "label"]);
      }
    };
    void open();
  }, [conceptParam, isModelLoading, ontologyId, scope, searchParams, setSearchParams]);

  // Outbound: keep ?concept= in sync with the graph being viewed.
  useEffect(() => {
    const current = searchParams.get("concept");
    if (predicate) {
      lastShownRef.current = predicate;
      processedRef.current = predicate;
      if (current !== predicate) {
        setSearchParams(
          (previous) => {
            const next = new URLSearchParams(previous);
            next.set("concept", predicate);
            // Params describing a previously linked concept no longer apply.
            for (const key of ["columns", "source", "target", "label"]) next.delete(key);
            return next;
          },
          { replace: true },
        );
      }
      return;
    }
    if (lastShownRef.current && current === lastShownRef.current) {
      lastShownRef.current = null;
      processedRef.current = null;
      setSearchParams(
        (previous) => {
          const next = new URLSearchParams(previous);
          next.delete("concept");
          next.delete("columns");
          return next;
        },
        { replace: true },
      );
    }
  }, [predicate, searchParams, setSearchParams]);
}
