import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

import { ContextEdgeApi } from "../api";
import type { ContextEdgeNodeType, CreateContextEdgeRequest } from "../types";
import { ATTACHED_NOTES_KEY_PREFIX } from "./useAttachedNotes";

const edgeListKey = (nodeType: ContextEdgeNodeType, nodeId: string) =>
  ["context-edges", nodeType, nodeId] as const;

export function useContextEdges(nodeType: ContextEdgeNodeType, nodeId: string | null) {
  return useQuery({
    queryKey: edgeListKey(nodeType, nodeId ?? ""),
    queryFn: () => ContextEdgeApi.listForNode(nodeType, nodeId ?? ""),
    enabled: Boolean(nodeId),
  });
}

/** Every edge in the workspace — feeds the graph view. */
export function useAllContextEdges(options?: { enabled?: boolean }) {
  return useQuery({
    queryKey: ["context-edges", "all"],
    queryFn: () => ContextEdgeApi.listAll(),
    enabled: options?.enabled ?? true,
  });
}

export function useCreateContextEdge() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateContextEdgeRequest) => ContextEdgeApi.create(body),
    onSuccess: () => {
      // Prefix invalidation covers per-node lists and the graph's all-edges query.
      queryClient.invalidateQueries({ queryKey: ["context-edges"] });
      queryClient.invalidateQueries({ queryKey: [ATTACHED_NOTES_KEY_PREFIX] });
    },
    onError: (error: Error) => {
      toast.error(`Could not link notes: ${error.message}`);
    },
  });
}

export function useDeleteContextEdge() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => ContextEdgeApi.remove(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["context-edges"] });
      queryClient.invalidateQueries({ queryKey: [ATTACHED_NOTES_KEY_PREFIX] });
    },
    onError: (error: Error) => {
      toast.error(`Could not remove link: ${error.message}`);
    },
  });
}
