import { useQuery } from "@tanstack/react-query";

import { ContextNoteApi } from "../api";
import type { ContextEdgeNodeType } from "../types";

export const ATTACHED_NOTES_KEY_PREFIX = "context-attached";

/** Notes attached to a concept/project node via context_edges (phase 4).
 *  Edge and note mutations invalidate the ATTACHED_NOTES_KEY_PREFIX. */
export function useAttachedNotes(nodeType: ContextEdgeNodeType, nodeId: string | null) {
  return useQuery({
    queryKey: [ATTACHED_NOTES_KEY_PREFIX, nodeType, nodeId ?? ""],
    queryFn: () => ContextNoteApi.listAttached(nodeType, nodeId ?? ""),
    enabled: Boolean(nodeId),
  });
}
