import { useCallback, useMemo, useState } from "react";

export const useSidebarState = () => {
  const [sidebarVisible, setSidebarVisible] = useState(() => {
    try {
      const storedState = localStorage.getItem("prometheuxSidebarVisible");
      return storedState !== null ? storedState === "true" : true;
    } catch (_error) {
      return true;
    }
  });

  const toggleSidebar = useCallback(() => {
    setSidebarVisible((prevState) => {
      const newState = !prevState;
      try {
        localStorage.setItem("prometheuxSidebarVisible", newState.toString());
      } catch (_error) {
        // ignore
      }
      return newState;
    });
  }, []);

  return useMemo(() => ({ sidebarVisible, toggleSidebar }), [sidebarVisible, toggleSidebar]);
};
