import { syntaxHighlighting } from "@codemirror/language";
import { EditorView } from "@codemirror/view";
import CodeMirror from "@uiw/react-codemirror";
import { ArrowLeft, ArrowRight, ChevronDown, ChevronUp, Copy, Plus, Search, X } from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { CodeClient } from "@/features/concept-editor/api/CodeClient";
import { customLanguage } from "@/features/concept-editor/components/code-editor/language/customProlog";
import { customHighlightStyle } from "@/features/concept-editor/components/code-editor/styles/editorHighlightStyle";
import type { CellBinds } from "@/features/concept-editor/types";
import { useDataSources } from "@/features/data-sources/hooks/useDataSources";
import { getDatasourceDisplayName } from "@/features/data-sources/predicateExtraction.utils";
import type { DataSource } from "@/features/data-sources/types";
import DatabaseIcon from "@/shared/components/icons/DatabaseIcon";
import { Badge } from "@/shared/components/ui/badge";
import { Input } from "@/shared/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/components/ui/tabs";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";

interface BindDataSelectorProps {
  cellId: string;
  code: string;
  outputPredicate?: string;
  binds: CellBinds;
  onBindsChange: (binds: CellBinds) => void;
  conceptType?: "logic" | "sql" | "cypher" | "python" | "context" | "llm";
  onBoundPredicatesChange?: (signatures: { label: string; apply: string; info: string }[]) => void;
}

interface InputBindingLocal {
  id: string;
  predicate: string;
  datasourceId: string;
  fullBindAnnotation: string;
}

interface OutputBindingLocal {
  id: string;
  predicateName: string;
  databaseKey?: string;
  datasourceName: string;
  fullBindAnnotation: string;
}

const codeClient = new CodeClient();
let bindingCounter = 0;
const nextId = () => `ib-${++bindingCounter}`;

function buildPredicateSignature(predicate: string, ds: DataSource | undefined): string {
  if (!ds?.fields) return `${predicate}()`;
  const args = Object.keys(ds.fields)
    .map((f) => f.charAt(0).toUpperCase() + f.slice(1))
    .join(",");
  return `${predicate}(${args})`;
}

function maskPasswordInAnnotation(annotation: string): string {
  return annotation
    .replace(/password='[^']*'/gi, "password='****'")
    .replace(/password=[^,)'"]+/gi, "password=****")
    .replace(/s3aSecretKey='[^']*'/gi, "s3aSecretKey='****'")
    .replace(/s3aSecretKey=[^,)'"]+/gi, "s3aSecretKey=****");
}

function bindsToRawText(binds: CellBinds): string {
  const lines: string[] = [];
  for (const b of binds.input) {
    if (b.annotation) lines.push(maskPasswordInAnnotation(b.annotation));
  }
  for (const b of binds.output) {
    if (b.annotation) lines.push(maskPasswordInAnnotation(b.annotation));
  }
  return lines.join("\n");
}

function restoreMaskedPasswords(parsed: CellBinds, original: CellBinds): CellBinds {
  const restore = (
    entries: Array<{ predicate: string; annotation: string; [k: string]: any }>,
    origEntries: Array<{ predicate: string; annotation: string; [k: string]: any }>,
  ) =>
    entries.map((b) => {
      if (!b.annotation.includes("****")) return b;
      const orig = origEntries.find((o) => o.predicate === b.predicate);
      return orig ? { ...b, annotation: orig.annotation } : b;
    });

  return {
    input: restore(parsed.input, original.input),
    output: restore(parsed.output, original.output),
  };
}

const BindDataSelector: React.FC<BindDataSelectorProps> = ({
  cellId,
  code,
  outputPredicate,
  binds,
  onBindsChange,
  conceptType = "logic",
  onBoundPredicatesChange,
}) => {
  const { dataSources, isLoading, loadDataSources } = useDataSources();

  const [activeTab, setActiveTab] = useState<"visual" | "raw">("visual");
  const [rawText, setRawText] = useState(() => bindsToRawText(binds));
  const isParsing = useRef(false);
  const rawParseTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const bindsRef = useRef(binds);
  bindsRef.current = binds;
  const localCommitRef = useRef(false);

  const [detectedPredicates, setDetectedPredicates] = useState<string[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const [inputBindings, setInputBindings] = useState<InputBindingLocal[]>([]);
  const [outputBindings, setOutputBindings] = useState<OutputBindingLocal[]>([]);

  const [isAdding, setIsAdding] = useState(false);
  const [newPredicate, setNewPredicate] = useState("");
  const [newDatasourceId, setNewDatasourceId] = useState<string | null>(null);
  const [predicateFocused, setPredicateFocused] = useState(false);
  const [datasourcePickerOpen, setDatasourcePickerOpen] = useState(false);
  const [datasourceSearch, setDatasourceSearch] = useState("");

  const [outputSearchTerm, setOutputSearchTerm] = useState("");
  const [expandedOutputTypes, setExpandedOutputTypes] = useState<Set<string>>(new Set());
  const [outputPickerOpen, setOutputPickerOpen] = useState(false);

  useEffect(() => {
    loadDataSources();
  }, [loadDataSources]);
  useEffect(
    () => () => {
      if (rawParseTimer.current) clearTimeout(rawParseTimer.current);
    },
    [],
  );

  // Analyze code via backend
  useEffect(() => {
    if (!code.trim()) {
      setDetectedPredicates([]);
      return;
    }
    const timer = setTimeout(async () => {
      setIsAnalyzing(true);
      try {
        const result = await codeClient.analyzeCode(code, conceptType, outputPredicate);
        setDetectedPredicates(result.inputPredicates);
      } catch {
        setDetectedPredicates([]);
      } finally {
        setIsAnalyzing(false);
      }
    }, 500);
    return () => clearTimeout(timer);
  }, [code, conceptType, outputPredicate]);

  // Initialize local state from CellBinds prop (skip when the change came from our own visual UI)
  useEffect(() => {
    if (localCommitRef.current) {
      localCommitRef.current = false;
      if (activeTab !== "raw") {
        setRawText(bindsToRawText(binds));
      }
      return;
    }
    if (dataSources.length === 0) return;

    const inputs: InputBindingLocal[] = binds.input.map((entry) => {
      let ds = dataSources.find((d) => d.bindAnnotation === entry.annotation);
      if (!ds && entry.table_name) {
        ds = dataSources.find((d) => d.tableName === entry.table_name);
      }
      return {
        id: nextId(),
        predicate: entry.predicate,
        datasourceId: ds?.id || "",
        fullBindAnnotation: entry.annotation,
      };
    });

    const outputs: OutputBindingLocal[] = binds.output.map((entry, i) => ({
      id: `out-${i}`,
      predicateName: entry.predicate,
      datasourceName: entry.table_name || entry.path || "",
      fullBindAnnotation: entry.annotation,
    }));

    setInputBindings(inputs);
    setOutputBindings(outputs);
    if (activeTab !== "raw") {
      setRawText(bindsToRawText(binds));
    }
  }, [dataSources, binds, activeTab]);

  // Emit bound predicate signatures whenever input bindings change
  useEffect(() => {
    if (!onBoundPredicatesChange) return;
    const sigs = inputBindings.map((b) => {
      const ds = dataSources.find((d) => d.id === b.datasourceId);
      const sig = buildPredicateSignature(b.predicate, ds);
      const info = ds?.fields
        ? `${b.predicate}(${Object.entries(ds.fields)
            .map(([n, t]) => `${n}:${t}`)
            .join(", ")})`
        : b.predicate;
      return { label: b.predicate, apply: sig, info };
    });
    onBoundPredicatesChange(sigs);
  }, [inputBindings, dataSources, onBoundPredicatesChange]);

  // Store raw text and debounce server-side parsing
  const handleRawChange = useCallback(
    (value: string) => {
      setRawText(value);
      if (rawParseTimer.current) clearTimeout(rawParseTimer.current);
      rawParseTimer.current = setTimeout(async () => {
        const currentRaw = bindsToRawText(bindsRef.current);
        if (value.trim() === currentRaw.trim()) return;
        if (!value.trim()) {
          onBindsChange({ input: [], output: [] });
          return;
        }
        try {
          const result = await codeClient.parseBinds(value, outputPredicate || "");
          const restored = restoreMaskedPasswords(result.binds as CellBinds, bindsRef.current);
          onBindsChange(restored);
        } catch {
          // keep existing binds on parse error
        }
      }, 600);
    },
    [outputPredicate, onBindsChange],
  );

  // Commit local state -> CellBinds
  const commitBindings = useCallback(
    (newInputs: InputBindingLocal[], newOutputs: OutputBindingLocal[]) => {
      localCommitRef.current = true;
      const updated: CellBinds = {
        input: newInputs.map((b) => ({ predicate: b.predicate, annotation: b.fullBindAnnotation })),
        output: newOutputs.map((o) => ({
          predicate: o.predicateName,
          annotation: o.fullBindAnnotation,
          table_name: o.datasourceName,
        })),
      };
      onBindsChange(updated);
    },
    [onBindsChange],
  );

  // Tab switch logic — only re-parse and propagate if raw text was actually edited
  const handleTabChange = async (tab: string) => {
    if (tab === "visual" && activeTab === "raw") {
      const currentRaw = bindsToRawText(binds);
      if (rawText.trim() !== currentRaw.trim()) {
        if (rawText.trim()) {
          isParsing.current = true;
          try {
            const result = await codeClient.parseBinds(rawText, outputPredicate || "");
            const parsed: CellBinds = result.binds;
            const restored = restoreMaskedPasswords(parsed, binds);
            onBindsChange(restored);
          } catch {
            // keep existing binds on error
          } finally {
            isParsing.current = false;
          }
        } else {
          onBindsChange({ input: [], output: [] });
        }
      }
    } else if (tab === "raw" && activeTab === "visual") {
      setRawText(bindsToRawText(binds));
    }
    setActiveTab(tab as "visual" | "raw");
  };

  // Input binding actions
  const handleAddBinding = async () => {
    if (!newPredicate.trim() || !newDatasourceId) return;
    const ds = dataSources.find((d) => d.id === newDatasourceId);
    if (!ds) return;

    const annotation = await codeClient.buildBindAnnotation(
      ds.bindAnnotation,
      newPredicate.trim(),
      false,
    );
    if (!annotation) return;

    const binding: InputBindingLocal = {
      id: nextId(),
      predicate: newPredicate.trim(),
      datasourceId: newDatasourceId,
      fullBindAnnotation: annotation,
    };
    const updated = [...inputBindings, binding];
    setInputBindings(updated);
    commitBindings(updated, outputBindings);
    setNewPredicate("");
    setNewDatasourceId(null);
    setIsAdding(false);
  };

  const handleRemoveBinding = (id: string) => {
    const updated = inputBindings.filter((b) => b.id !== id);
    setInputBindings(updated);
    commitBindings(updated, outputBindings);
  };

  const handleCancelAdd = () => {
    setIsAdding(false);
    setNewPredicate("");
    setNewDatasourceId(null);
    setPredicateFocused(false);
    setDatasourcePickerOpen(false);
    setDatasourceSearch("");
  };

  const filteredPredicates = useMemo(() => {
    if (!newPredicate.trim()) return detectedPredicates;
    const lower = newPredicate.toLowerCase();
    return detectedPredicates.filter((p) => p.toLowerCase().includes(lower));
  }, [detectedPredicates, newPredicate]);

  const filteredDataSources = useMemo(() => {
    if (!datasourceSearch.trim()) return dataSources;
    const lower = datasourceSearch.toLowerCase();
    return dataSources.filter((ds) => {
      const name = getDatasourceDisplayName(ds);
      return (
        name.toLowerCase().includes(lower) ||
        ds.datasourceType?.toLowerCase().includes(lower) ||
        ds.databaseName?.toLowerCase().includes(lower)
      );
    });
  }, [dataSources, datasourceSearch]);

  const groupedFilteredDS = useMemo(() => {
    const groups: Record<string, typeof dataSources> = {};
    filteredDataSources.forEach((ds) => {
      const type = ds.datasourceType || "unknown";
      if (!groups[type]) groups[type] = [];
      groups[type].push(ds);
    });
    Object.keys(groups).forEach((type) => {
      groups[type].sort((a, b) =>
        getDatasourceDisplayName(a).localeCompare(getDatasourceDisplayName(b)),
      );
    });
    return Object.keys(groups)
      .sort()
      .map((type) => ({ type, dataSources: groups[type] }));
  }, [filteredDataSources]);

  // Output connection grouping — unique connections (type + location), not individual files/tables
  const groupedDatabases = useMemo(() => {
    const connections = new Map<
      string,
      { name: string; type: string; sampleDatasource: (typeof dataSources)[0] }
    >();
    dataSources.forEach((ds) => {
      const key = `${ds.datasourceType}-${ds.location || ""}-${ds.groupBy || ""}`;
      if (!connections.has(key)) {
        const name = ds.databaseName
          ? `${ds.databaseName} @ ${ds.host || "localhost"}${ds.port ? `:${ds.port}` : ""}`
          : ds.location || ds.datasourceType;
        connections.set(key, { name, type: ds.datasourceType, sampleDatasource: ds });
      }
    });
    return Array.from(connections.entries()).map(([key, value]) => ({ key, ...value }));
  }, [dataSources]);

  const filteredOutputDatabases = useMemo(() => {
    if (!outputSearchTerm.trim()) return groupedDatabases;
    const lower = outputSearchTerm.toLowerCase();
    return groupedDatabases.filter(
      (db) => db.name.toLowerCase().includes(lower) || db.type.toLowerCase().includes(lower),
    );
  }, [groupedDatabases, outputSearchTerm]);

  const groupedOutputDatabases = useMemo(() => {
    const groups: Record<string, typeof groupedDatabases> = {};
    filteredOutputDatabases.forEach((db) => {
      const type = db.type || "unknown";
      if (!groups[type]) groups[type] = [];
      groups[type].push(db);
    });
    Object.keys(groups).forEach((type) => {
      groups[type].sort((a, b) => a.name.localeCompare(b.name));
    });
    return Object.keys(groups)
      .sort()
      .map((type) => ({ type, databases: groups[type] }));
  }, [filteredOutputDatabases]);

  const toggleOutputType = (type: string) => {
    setExpandedOutputTypes((prev) => {
      const s = new Set(prev);
      if (s.has(type)) s.delete(type);
      else s.add(type);
      return s;
    });
  };

  useEffect(() => {
    if (outputSearchTerm.trim()) {
      setExpandedOutputTypes(new Set(groupedOutputDatabases.map((g) => g.type)));
    } else if (groupedOutputDatabases.length > 0 && expandedOutputTypes.size === 0) {
      setExpandedOutputTypes(new Set(groupedOutputDatabases.map((g) => g.type)));
    }
  }, [outputSearchTerm, groupedOutputDatabases, expandedOutputTypes.size]);

  const handleAddOutputBinding = async (databaseKey: string) => {
    if (!outputPredicate) return;
    const database = groupedDatabases.find((db) => db.key === databaseKey);
    if (!database) return;
    const fullAnnotation = await codeClient.buildBindAnnotation(
      database.sampleDatasource.bindAnnotation,
      outputPredicate,
      true,
    );
    if (!fullAnnotation) return;
    const newBinding: OutputBindingLocal = {
      id: `out-${databaseKey}-${Math.random().toString(36).substr(2, 9)}`,
      predicateName: outputPredicate,
      databaseKey,
      datasourceName: database.name,
      fullBindAnnotation: fullAnnotation,
    };
    const updated = [...outputBindings, newBinding];
    setOutputBindings(updated);
    commitBindings(inputBindings, updated);
    setOutputSearchTerm("");
  };

  const handleRemoveOutputBinding = (bindingId: string) => {
    const updated = outputBindings.filter((b) => b.id !== bindingId);
    setOutputBindings(updated);
    commitBindings(inputBindings, updated);
  };

  const rawEditorTheme = useMemo(
    () =>
      EditorView.theme({
        ".cm-editor": {
          background: "hsl(var(--card)) !important",
        },
        ".cm-gutters": {
          background: "hsl(var(--card) / 0.2) !important",
          borderRight: "none !important",
        },
        ".cm-scroller": {
          background: "hsl(var(--card)) !important",
        },
        ".cm-content": {
          // Transparent (NOT card) on purpose. With drawSelection:true CodeMirror
          // paints its selection in a .cm-selectionLayer BEHIND the content; an
          // opaque content background would hide that highlight. The .cm-scroller
          // above already paints the card background, so transparent looks
          // identical while letting the drawn selection show through.
          background: "transparent !important",
        },
        ".cm-line": {
          background: "transparent !important",
        },
        // Selection color is handled globally in code-editor.css
        // (.cm-selectionBackground, with light/dark variants) — no local override
        // needed now that the content layer no longer hides it.
      }),
    [],
  );

  const rawEditorExtensions = useMemo(
    () => [customLanguage, syntaxHighlighting(customHighlightStyle), rawEditorTheme],
    [rawEditorTheme],
  );

  const newDs = newDatasourceId ? dataSources.find((d) => d.id === newDatasourceId) : null;

  return (
    <Tabs value={activeTab} onValueChange={handleTabChange} className="w-full">
      <TabsList className="h-7 p-0.5 bg-muted/60 rounded-md inline-flex w-auto gap-0.5">
        <TabsTrigger
          value="visual"
          className="text-[11px] h-6 px-3 rounded-sm data-[state=active]:bg-background data-[state=active]:shadow-sm"
        >
          Visual
        </TabsTrigger>
        <TabsTrigger
          value="raw"
          className="text-[11px] h-6 px-3 rounded-sm data-[state=active]:bg-background data-[state=active]:shadow-sm"
        >
          Raw
        </TabsTrigger>
      </TabsList>

      <TabsContent value="visual" className="mt-2 space-y-3">
        {/* ── Input Bindings ── */}
        <div>
          <div className="flex items-center justify-between mb-1.5">
            <span className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/70">
              Input
            </span>
            {isAnalyzing && (
              <span className="text-[10px] italic text-muted-foreground/50">analyzing...</span>
            )}
          </div>

          {inputBindings.length > 0 && (
            <div className="flex flex-col gap-1 mb-1.5">
              {inputBindings.map((binding) => {
                const ds = dataSources.find((d) => d.id === binding.datasourceId);
                const sig = buildPredicateSignature(binding.predicate, ds);
                return (
                  <div key={binding.id} className="flex items-center gap-1.5">
                    <div className="flex-1 min-w-0 flex items-center gap-1.5 px-2 py-1 border border-border rounded-md bg-card">
                      <code className="font-mono text-xs font-medium truncate">
                        {binding.predicate}
                      </code>
                      <ArrowLeft className="h-2.5 w-2.5 flex-shrink-0 text-muted-foreground/50" />
                      {ds && (
                        <>
                          <DatabaseIcon
                            type={ds.datasourceType}
                            className="h-3 w-3 flex-shrink-0 text-muted-foreground"
                          />
                          <span className="text-xs text-muted-foreground truncate">
                            {getDatasourceDisplayName(ds)}
                          </span>
                        </>
                      )}
                    </div>
                    <button
                      onClick={() => {
                        navigator.clipboard.writeText(sig);
                        toast.success(`Copied to clipboard`);
                      }}
                      className="flex-shrink-0 h-5 w-5 flex items-center justify-center rounded-sm hover:bg-muted text-muted-foreground/60 hover:text-muted-foreground transition-colors"
                      title="Copy predicate signature"
                    >
                      <Copy className="h-3 w-3" />
                    </button>
                    <button
                      onClick={() => handleRemoveBinding(binding.id)}
                      className="flex-shrink-0 h-5 w-5 flex items-center justify-center rounded-sm hover:bg-destructive/10 text-muted-foreground/60 hover:text-destructive transition-colors"
                    >
                      <X className="h-3 w-3" />
                    </button>
                  </div>
                );
              })}
            </div>
          )}

          {isAdding ? (
            <div className="flex items-start gap-1.5">
              {/* Predicate combo box (free-text + suggestions) */}
              <div className="flex-1 min-w-0 relative">
                <Input
                  type="text"
                  placeholder="Predicate name..."
                  value={newPredicate}
                  onChange={(e) => setNewPredicate(e.target.value)}
                  onFocus={() => {
                    setPredicateFocused(true);
                    setDatasourcePickerOpen(false);
                  }}
                  onBlur={() => setTimeout(() => setPredicateFocused(false), 150)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && newPredicate.trim() && newDatasourceId) {
                      e.preventDefault();
                      handleAddBinding();
                    } else if (e.key === "Escape") {
                      setPredicateFocused(false);
                    }
                  }}
                  className="h-7 text-xs font-mono"
                  autoFocus
                />
                {predicateFocused && filteredPredicates.length > 0 && (
                  <div className="absolute z-50 top-full left-0 right-0 mt-1 border border-border rounded-md bg-popover shadow-md max-h-48 overflow-y-auto">
                    {isAnalyzing && (
                      <div className="px-2.5 py-1 text-[10px] text-muted-foreground/50 border-b border-border">
                        detecting...
                      </div>
                    )}
                    {filteredPredicates.map((pred) => (
                      <button
                        key={pred}
                        className="w-full text-left px-2.5 py-1 text-xs hover:bg-muted/50 transition-colors"
                        onMouseDown={(e) => {
                          e.preventDefault();
                          setNewPredicate(pred);
                          setPredicateFocused(false);
                        }}
                      >
                        <code className="font-mono">{pred}</code>
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <ArrowLeft className="h-3 w-3 flex-shrink-0 text-muted-foreground/40 mt-1.5" />

              {/* Datasource picker */}
              <div className="flex-1 min-w-0 relative">
                <button
                  onClick={() => {
                    setDatasourcePickerOpen(!datasourcePickerOpen);
                    setPredicateFocused(false);
                  }}
                  className={`w-full text-left px-2 py-1 border rounded-md text-xs transition-colors flex items-center justify-between gap-1 ${
                    newDs
                      ? "border-border bg-card"
                      : "border-dashed border-border text-muted-foreground hover:bg-muted/30"
                  }`}
                >
                  {newDs ? (
                    <span className="flex items-center gap-1 truncate">
                      <DatabaseIcon type={newDs.datasourceType} className="h-3 w-3 flex-shrink-0" />
                      <span className="truncate">{getDatasourceDisplayName(newDs)}</span>
                    </span>
                  ) : (
                    <span className="truncate">Datasource...</span>
                  )}
                  <ChevronDown className="h-3 w-3 flex-shrink-0 text-muted-foreground/60" />
                </button>
                {datasourcePickerOpen && (
                  <div className="absolute z-50 top-full left-0 right-0 mt-1 border border-border rounded-md bg-popover shadow-md">
                    <div className="p-1.5 border-b border-border">
                      <div className="relative">
                        <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-muted-foreground" />
                        <Input
                          type="text"
                          placeholder="Search..."
                          value={datasourceSearch}
                          onChange={(e) => setDatasourceSearch(e.target.value)}
                          className="h-6 text-xs pl-6"
                          autoFocus
                        />
                      </div>
                    </div>
                    <div className="max-h-64 overflow-y-auto">
                      {isLoading ? (
                        <div className="px-2.5 py-1.5 text-[11px] text-muted-foreground">
                          Loading...
                        </div>
                      ) : groupedFilteredDS.length === 0 ? (
                        <div className="px-2.5 py-1.5 text-[11px] text-muted-foreground">
                          No datasources
                        </div>
                      ) : (
                        groupedFilteredDS.map(({ type, dataSources: groupDS }) => (
                          <div key={type}>
                            <div className="px-2.5 py-1 bg-muted/40 text-[10px] font-semibold uppercase tracking-wider flex items-center gap-1">
                              <DatabaseIcon type={type} className="h-3 w-3" />
                              {type}
                              <Badge variant="secondary" className="text-[9px] h-3.5 px-1 ml-auto">
                                {groupDS.length}
                              </Badge>
                            </div>
                            {groupDS.map((ds) => (
                              <button
                                key={ds.id}
                                className="w-full text-left pl-6 pr-2.5 py-1 text-xs hover:bg-muted/50 transition-colors flex items-center gap-1.5"
                                onClick={() => {
                                  setNewDatasourceId(ds.id);
                                  setDatasourcePickerOpen(false);
                                  setDatasourceSearch("");
                                }}
                              >
                                <DatabaseIcon
                                  type={ds.datasourceType}
                                  className="h-3 w-3 flex-shrink-0 text-muted-foreground"
                                />
                                <span className="truncate">{getDatasourceDisplayName(ds)}</span>
                              </button>
                            ))}
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>

              {/* Confirm / cancel */}
              <div className="flex items-center gap-0.5 flex-shrink-0">
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <button
                        onClick={handleAddBinding}
                        disabled={!newPredicate.trim() || !newDatasourceId}
                        className="h-6 w-6 flex items-center justify-center rounded-md bg-primary text-primary-foreground disabled:opacity-30 hover:bg-primary/90 transition-colors"
                      >
                        <Plus className="h-3 w-3" />
                      </button>
                    </TooltipTrigger>
                    <TooltipContent>
                      <p>Confirm</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
                <button
                  onClick={handleCancelAdd}
                  className="h-6 w-6 flex items-center justify-center rounded-md text-muted-foreground hover:bg-muted/50 transition-colors"
                >
                  <X className="h-3 w-3" />
                </button>
              </div>
            </div>
          ) : (
            <button
              onClick={() => setIsAdding(true)}
              disabled={isLoading}
              className="w-full flex items-center justify-center gap-1 text-[11px] text-muted-foreground hover:text-foreground py-1 border border-dashed border-border/60 rounded-md hover:border-border hover:bg-muted/20 transition-colors disabled:opacity-40"
            >
              <Plus className="h-3 w-3" />
              <span>Add input binding</span>
            </button>
          )}
        </div>

        {/* ── Separator ── */}
        {/* Python concepts auto-manage their parquet output bind, so output
            binding editing is hidden — only input bindings are user-editable. */}
        {conceptType !== "python" && <div className="border-t border-border/40" />}

        {/* ── Output Bindings ── */}
        {conceptType !== "python" && (
          <div>
            <span className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/70 block mb-1.5">
              Output
            </span>

            {outputBindings.length > 0 && (
              <div className="border border-border rounded-md overflow-hidden divide-y divide-border mb-1.5">
                {outputBindings.map((binding) => (
                  <div
                    key={binding.id}
                    className="flex items-center gap-1.5 px-2 py-1 bg-card hover:bg-muted/30 transition-colors group"
                  >
                    <code className="font-mono text-xs font-medium truncate">
                      {binding.predicateName}
                    </code>
                    <ArrowRight className="h-2.5 w-2.5 flex-shrink-0 text-muted-foreground/50" />
                    <span className="text-xs text-muted-foreground truncate flex-1">
                      {binding.datasourceName}
                    </span>
                    <button
                      onClick={() => handleRemoveOutputBinding(binding.id)}
                      className="opacity-0 group-hover:opacity-100 h-4 w-4 flex items-center justify-center rounded-sm hover:bg-destructive/10 hover:text-destructive text-muted-foreground transition-opacity"
                    >
                      <X className="h-2.5 w-2.5" />
                    </button>
                  </div>
                ))}
              </div>
            )}

            {/* Inline output picker */}
            <div>
              <button
                onClick={() => setOutputPickerOpen(!outputPickerOpen)}
                disabled={!outputPredicate || groupedDatabases.length === 0}
                className="w-full flex items-center justify-center gap-1 text-[11px] text-muted-foreground hover:text-foreground py-1 border border-dashed border-border/60 rounded-md hover:border-border hover:bg-muted/20 transition-colors disabled:opacity-40"
              >
                <Plus className="h-3 w-3" />
                <span>Add output binding</span>
              </button>
              {outputPickerOpen && (
                <div className="mt-1.5 border border-border rounded-md bg-popover">
                  <div className="p-1.5 border-b border-border">
                    <div className="relative">
                      <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-muted-foreground" />
                      <Input
                        type="text"
                        placeholder="Search databases..."
                        value={outputSearchTerm}
                        onChange={(e) => setOutputSearchTerm(e.target.value)}
                        className="h-6 text-xs pl-6"
                        autoFocus
                      />
                    </div>
                  </div>
                  <div className="max-h-48 overflow-y-auto">
                    {filteredOutputDatabases.length === 0 ? (
                      <div className="px-2.5 py-1.5 text-[11px] text-muted-foreground">
                        No databases found
                      </div>
                    ) : (
                      groupedOutputDatabases.map(({ type, databases }) => {
                        const isTypeExpanded = expandedOutputTypes.has(type);
                        return (
                          <div key={type}>
                            <button
                              onClick={() => toggleOutputType(type)}
                              className="w-full px-2.5 py-1.5 bg-muted/30 text-[10px] font-semibold uppercase tracking-wider flex items-center gap-1 hover:bg-muted/50 transition-colors"
                            >
                              <DatabaseIcon type={type} className="h-3 w-3" />
                              <span className="flex-1 text-left">{type}</span>
                              <Badge variant="secondary" className="text-[9px] h-3.5 px-1">
                                {databases.length}
                              </Badge>
                              {isTypeExpanded ? (
                                <ChevronUp className="h-3 w-3" />
                              ) : (
                                <ChevronDown className="h-3 w-3" />
                              )}
                            </button>
                            {isTypeExpanded &&
                              databases.map((db) => (
                                <button
                                  key={db.key}
                                  onClick={() => {
                                    handleAddOutputBinding(db.key);
                                    setOutputPickerOpen(false);
                                  }}
                                  className="w-full text-left pl-6 pr-2.5 py-1.5 text-xs hover:bg-muted/50 transition-colors flex items-center gap-1.5"
                                >
                                  <DatabaseIcon
                                    type={db.type}
                                    className="h-3 w-3 flex-shrink-0 text-muted-foreground"
                                  />
                                  <span className="font-mono text-xs truncate">{db.name}</span>
                                </button>
                              ))}
                          </div>
                        );
                      })
                    )}
                  </div>
                </div>
              )}
            </div>

            {outputBindings.length === 0 && !outputPickerOpen && (
              <p className="text-[11px] text-muted-foreground/60 mt-1 text-center">
                {!outputPredicate
                  ? "Set an output predicate for this cell first."
                  : groupedDatabases.length === 0
                    ? "No databases connected."
                    : "By default, output is not materialized."}
              </p>
            )}
          </div>
        )}
      </TabsContent>

      <TabsContent value="raw" className="mt-2">
        <div className="border border-border rounded-md overflow-hidden">
          <CodeMirror
            value={rawText}
            onChange={handleRawChange}
            height="140px"
            theme="light"
            extensions={rawEditorExtensions}
            basicSetup={{
              lineNumbers: true,
              foldGutter: true,
              highlightActiveLine: true,
              syntaxHighlighting: true,
              // drawSelection:true draws CM's own selection/multi-cursor layer.
              // Stays visible because .cm-content above is transparent.
              drawSelection: true,
            }}
            className="text-xs"
          />
        </div>
        <p className="text-[11px] text-muted-foreground/60 mt-1">
          Edit @bind / @qbind annotations directly. Parsed on switch to Visual.
        </p>
      </TabsContent>
    </Tabs>
  );
};

export default BindDataSelector;
