import { Plus } from "lucide-react";
import { cn } from "@/shared/lib/utils";
import type { AppInputDef, RunGroupDef } from "../../schema/appDefinition.types";
import { selectionEquals } from "../../store/appEditor.types";
import * as mutations from "../../store/appEditorMutations";
import { useAppEditorStore } from "../../store/appEditorStore";
import { DATA_INPUTS_HELP, DATA_RUN_GROUPS_HELP } from "./editorHelp";
import { InfoHint } from "./InfoHint";

/**
 * Data tab of the left pane (ADR D7): the active page's inputs and run
 * groups as a visible wiring table — what feeds what, at a glance. Rows
 * select into the same inspector the preview uses.
 */
export function EditorDataPanel() {
  const draft = useAppEditorStore((state) => state.draft);
  const activePageId = useAppEditorStore((state) => state.activePageId);

  const page = draft?.pages.find((candidate) => candidate.id === activePageId);
  if (!draft || !page) {
    return <p className="p-3 text-[11px] text-muted-foreground">No page selected.</p>;
  }

  return (
    <div className="flex flex-col gap-4 p-2">
      <div className="flex flex-col gap-1">
        <PanelHeading hint={DATA_INPUTS_HELP}>Inputs</PanelHeading>
        {page.inputs.length === 0 && <EmptyHint>No inputs on this page.</EmptyHint>}
        {page.inputs.map((input) => (
          <InputRow key={input.id} pageId={page.id} input={input} />
        ))}
        <div className="flex gap-3 pl-2">
          <AddButton label="Add field" onAdd={() => addInputToPage(page.id, "text")} />
          <AddButton label="Add form" onAdd={() => addInputToPage(page.id, "form")} />
        </div>
      </div>

      <div className="flex flex-col gap-1">
        <PanelHeading hint={DATA_RUN_GROUPS_HELP}>Run groups</PanelHeading>
        {page.runGroups.length === 0 && <EmptyHint>No run groups on this page.</EmptyHint>}
        {page.runGroups.map((group) => (
          <RunGroupRow key={group.id} pageId={page.id} group={group} />
        ))}
        <div className="pl-2">
          <AddButton
            label="Add run group"
            onAdd={() => {
              const { updateDraft } = useAppEditorStore.getState();
              updateDraft((draftState) => mutations.addRunGroup(draftState, page.id));
            }}
          />
        </div>
      </div>
    </div>
  );
}

function addInputToPage(pageId: string, type: "text" | "form") {
  const { updateDraft, select } = useAppEditorStore.getState();
  updateDraft((draft) => mutations.addInput(draft, pageId, mutations.defaultInputFor(type)));
  const added = useAppEditorStore
    .getState()
    .draft?.pages.find((page) => page.id === pageId)
    ?.inputs.at(-1);
  if (added) select({ kind: "input", pageId, inputId: added.id });
}

interface InputRowProps {
  pageId: string;
  input: AppInputDef;
}

function InputRow({ pageId, input }: InputRowProps) {
  const selection = useAppEditorStore((state) => state.selection);
  const select = useAppEditorStore((state) => state.select);
  const isSelected = selectionEquals(selection, { kind: "input", pageId, inputId: input.id });

  const fieldCount =
    input.type === "form"
      ? (input.sections ?? []).reduce((total, section) => total + section.fields.length, 0)
      : null;

  return (
    <SelectableCard
      isSelected={isSelected}
      onSelect={() => select({ kind: "input", pageId, inputId: input.id })}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="text-[11px] truncate">{input.label || input.id}</span>
        <span className="text-[9px] font-mono text-muted-foreground flex-shrink-0">
          {input.type}
        </span>
      </div>
      {fieldCount !== null && (
        <span className="text-[10px] text-muted-foreground">
          {fieldCount} field{fieldCount === 1 ? "" : "s"}
        </span>
      )}
    </SelectableCard>
  );
}

interface RunGroupRowProps {
  pageId: string;
  group: RunGroupDef;
}

function RunGroupRow({ pageId, group }: RunGroupRowProps) {
  const selection = useAppEditorStore((state) => state.selection);
  const select = useAppEditorStore((state) => state.select);
  const isSelected = selectionEquals(selection, { kind: "runGroup", pageId, groupId: group.id });

  const paramBindings = Object.entries(group.params ?? {});
  const factBindings = Object.entries(group.facts ?? {});

  return (
    <SelectableCard
      isSelected={isSelected}
      onSelect={() => select({ kind: "runGroup", pageId, groupId: group.id })}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="text-[11px] font-medium truncate">{group.label || group.id}</span>
        <span className="text-[9px] font-mono text-muted-foreground flex-shrink-0">
          {group.trigger}
          {group.trigger === "form" && group.formId ? `:${group.formId}` : ""}
        </span>
      </div>
      {paramBindings.map(([name, template]) => (
        <WiringLine key={name} left={name} right={template} />
      ))}
      {factBindings.map(([predicate, template]) => (
        <WiringLine key={predicate} left={`${predicate} (facts)`} right={template} />
      ))}
      <WiringLine left="execute" right={group.execute.join(", ") || "—"} />
      <WiringLine
        left="taps"
        right={(group.outputs ?? []).map((tap) => tap.id).join(", ") || "—"}
      />
    </SelectableCard>
  );
}

function WiringLine({ left, right }: { left: string; right: string }) {
  return (
    <div className="flex items-baseline gap-1.5 text-[10px] font-mono min-w-0">
      <span className="text-muted-foreground flex-shrink-0">{left}</span>
      <span className="text-muted-foreground/50 flex-shrink-0">→</span>
      <span className="truncate">{right}</span>
    </div>
  );
}

interface SelectableCardProps {
  isSelected: boolean;
  onSelect: () => void;
  children: React.ReactNode;
}

function SelectableCard({ isSelected, onSelect, children }: SelectableCardProps) {
  return (
    <button
      type="button"
      onClick={onSelect}
      className={cn(
        "flex flex-col gap-0.5 rounded border px-2 py-1.5 text-left",
        isSelected ? "border-primary bg-accent" : "border-border hover:bg-accent/50",
      )}
    >
      {children}
    </button>
  );
}

function PanelHeading({ children, hint }: { children: React.ReactNode; hint?: string }) {
  return (
    <h4 className="flex items-center gap-1 px-2 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
      {children}
      {hint && <InfoHint text={hint} />}
    </h4>
  );
}

function EmptyHint({ children }: { children: React.ReactNode }) {
  return <p className="px-2 text-[10px] text-muted-foreground">{children}</p>;
}

interface AddButtonProps {
  label: string;
  onAdd: () => void;
}

function AddButton({ label, onAdd }: AddButtonProps) {
  return (
    <button
      type="button"
      onClick={onAdd}
      className="flex items-center gap-1 py-0.5 text-[10px] text-muted-foreground hover:text-foreground"
    >
      <Plus className="h-2.5 w-2.5" />
      {label}
    </button>
  );
}
