import { BaseClient } from "@/shared/lib/BaseClient";

export interface AnalyticsNode {
  id: string;
  analytics?: { score?: number; component?: string };
}

export interface AnalyticsEdge {
  source: string;
  target: string;
}

export interface GraphAnalyticsResult {
  nodes: AnalyticsNode[];
  edges: AnalyticsEdge[];
  analytics_type: string;
  analytics_range?: { min: number; max: number };
}

export interface RunAnalyticsRequest {
  column_roles: { source: number; target: number };
  function: string;
  function_params?: Record<string, unknown>;
  project?: { scope: string };
}

class GraphAnalyticsClient extends BaseClient {
  async runAnalytics(
    ontologyId: string,
    predicate: string,
    request: RunAnalyticsRequest,
  ): Promise<GraphAnalyticsResult> {
    const response = await this.post(
      `/kgs/${encodeURIComponent(ontologyId)}/graph-analytics/${encodeURIComponent(predicate)}`,
      request,
    );
    if (response.status !== "ok" && response.status !== "success") {
      throw new Error(response.message || "Graph analytics failed");
    }
    return response.data as GraphAnalyticsResult;
  }
}

export const graphAnalyticsClient = new GraphAnalyticsClient();
