import { RefreshCw } from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { toast } from "sonner";

import { useConceptEditorClient } from "@/features/concept-editor/api/ConceptEditorClientContext";
import { Button } from "@/shared/components/ui/button";
import { Textarea } from "@/shared/components/ui/textarea";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";
import { formatDescriptionWithMentions } from "@/shared/utils/sanitize";

import { useMentionSuggestions } from "../hooks/useMentionSuggestions";
import { MentionSuggestionDropdown } from "./MentionSuggestionDropdown";

interface CellDescriptionSectionProps {
  description: string;
  onDescriptionChange: (value: string) => void;
  /** Invoked on Cmd/Ctrl+S inside the textarea. */
  onSaveShortcut: () => void;
  /** Backend concept id — enables "generate description from code". */
  cellBackendId?: string;
  placeholder?: string;
}

/**
 * The concept description block: read view with @-mention highlighting,
 * click-to-edit textarea with @-concept autocomplete, and LLM regeneration.
 * Extracted from the query cells — rendered at the top of the Context tab.
 */
export function CellDescriptionSection({
  description,
  onDescriptionChange,
  onSaveShortcut,
  cellBackendId,
  placeholder = "Add a description to explain what this cell does... (use @ to tag concepts)",
}: CellDescriptionSectionProps) {
  const conceptEditorClient = useConceptEditorClient();
  const [isEditing, setIsEditing] = useState(false);
  const [editingText, setEditingText] = useState(description || "");
  const [isRegenerating, setIsRegenerating] = useState(false);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const {
    suggestions,
    suggestionRefs,
    checkSuggestions,
    closeSuggestions,
    moveSelection,
    setSelectedIndex,
  } = useMentionSuggestions();

  useEffect(() => {
    if (!isEditing && description && description !== editingText) {
      setEditingText(description);
    }
  }, [description]);

  const checkAtCursor = useCallback(
    (value: string, cursorPos?: number) => {
      const cursorPosition = cursorPos ?? inputRef.current?.selectionStart ?? value.length;
      checkSuggestions(value, cursorPosition);
    },
    [checkSuggestions],
  );

  const handleStartEdit = useCallback(() => {
    setIsEditing(true);
    setEditingText(description || "");
    closeSuggestions();
  }, [description, closeSuggestions]);

  const handleChange = useCallback(
    (value: string) => {
      setEditingText(value);
      onDescriptionChange(value);
      checkAtCursor(value);
    },
    [checkAtCursor, onDescriptionChange],
  );

  const handleInputClick = useCallback(() => {
    setTimeout(() => {
      const currentValue = inputRef.current?.value || "";
      const cursorPos = inputRef.current?.selectionStart ?? currentValue.length;
      checkAtCursor(currentValue, cursorPos);
    }, 10);
  }, [checkAtCursor]);

  const handleSelectSuggestion = useCallback(
    (concept: string) => {
      const cursorPosition = inputRef.current?.selectionStart || editingText.length;
      const textBeforeCursor = editingText.substring(0, cursorPosition);
      const textAfterCursor = editingText.substring(cursorPosition);
      const lastAtIndex = textBeforeCursor.lastIndexOf("@");
      if (lastAtIndex === -1) return;
      const newText = `${editingText.substring(0, lastAtIndex)}@${concept} ${textAfterCursor}`;
      setEditingText(newText);
      onDescriptionChange(newText);
      closeSuggestions();
      setTimeout(() => {
        if (inputRef.current) {
          const newPosition = lastAtIndex + concept.length + 2;
          inputRef.current.setSelectionRange(newPosition, newPosition);
          inputRef.current.focus();
        }
      }, 0);
    },
    [editingText, onDescriptionChange, closeSuggestions],
  );

  const handleRegenerate = useCallback(async () => {
    if (!cellBackendId) {
      toast.error("Please save the cell first");
      return;
    }
    setIsRegenerating(true);
    try {
      const response = await conceptEditorClient.generateDescription(cellBackendId);
      if (response.status === "success" && response.data?.description) {
        setEditingText(response.data.description);
        onDescriptionChange(response.data.description);
        toast.success("Description generated successfully");
      } else {
        toast.error(response.message || "Failed to generate description");
      }
    } catch (error) {
      console.error("Error regenerating description:", error);
      toast.error(error instanceof Error ? error.message : "Failed to generate description");
    } finally {
      setIsRegenerating(false);
    }
  }, [cellBackendId, conceptEditorClient, onDescriptionChange]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if ((e.metaKey || e.ctrlKey) && e.key === "s") {
      e.preventDefault();
      onSaveShortcut();
      return;
    }
    if (!suggestions.show) {
      if (e.key === "Escape") {
        setEditingText(description || "");
        setIsEditing(false);
        closeSuggestions();
      }
      return;
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      moveSelection(1);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      moveSelection(-1);
    } else if (e.key === "Enter" && suggestions.filtered.length > 0) {
      e.preventDefault();
      handleSelectSuggestion(suggestions.filtered[suggestions.selectedIndex]);
    } else if (e.key === "Escape") {
      e.preventDefault();
      closeSuggestions();
    }
  };

  if (isEditing) {
    return (
      <div className="py-2 relative" style={{ zIndex: 1, overflow: "visible" }}>
        <Textarea
          ref={inputRef}
          value={editingText}
          onChange={(e) => handleChange(e.target.value)}
          onClick={handleInputClick}
          onKeyUp={(e) => {
            if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(e.key)) {
              handleInputClick();
            }
          }}
          placeholder={placeholder}
          className="text-sm min-h-[80px] resize-none"
          autoFocus
          onKeyDown={handleKeyDown}
          onBlur={() => {
            setTimeout(() => {
              closeSuggestions();
              setIsEditing(false);
            }, 200);
          }}
        />
        <MentionSuggestionDropdown
          suggestions={suggestions}
          suggestionRefs={suggestionRefs}
          onSelect={handleSelectSuggestion}
          onHover={setSelectedIndex}
        />
      </div>
    );
  }

  return (
    <div className="flex items-start gap-2">
      <div
        className="flex-1 text-sm text-muted-foreground min-h-[20px] cursor-pointer hover:bg-muted/30 rounded-md p-2 transition-colors"
        onClick={handleStartEdit}
      >
        {description ? (
          <span dangerouslySetInnerHTML={{ __html: formatDescriptionWithMentions(description) }} />
        ) : (
          "Click to add a description..."
        )}
      </div>
      <div className="flex items-center gap-0.5 flex-shrink-0">
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="sm"
              onClick={handleRegenerate}
              disabled={isRegenerating || !cellBackendId}
              className="h-8 px-2"
            >
              <RefreshCw className={`h-4 w-4 ${isRegenerating ? "animate-spin" : ""}`} />
            </Button>
          </TooltipTrigger>
          <TooltipContent>
            {isRegenerating ? "Generating..." : "Generate description from code"}
          </TooltipContent>
        </Tooltip>
      </div>
    </div>
  );
}
