import type React from "react";
import { useRef, useState } from "react";
import { toast } from "sonner";
import type { FailedDatasource } from "@/features/data-sources/components/FailedDatasourcesDialog";
import { type OntologyData, type OntologyScope, OntologyService } from "@/features/ontologies/api";

export interface ImportConflict {
  importData: Record<string, unknown>;
  existingOntology: OntologyData;
}

interface UseOntologyImportOptions {
  scope: OntologyScope;
  existingOntologies: OntologyData[];
  onImported?: () => Promise<void> | void;
  onClose: () => void;
}

interface UseOntologyImportReturn {
  isImporting: boolean;
  selectedFile: File | null;
  fileInputRef: React.RefObject<HTMLInputElement | null>;
  failedDatasources: FailedDatasource[];
  dismissFailedDatasources: () => void;
  importConflict: ImportConflict | null;
  conflictOntologyName: string;
  handleFileSelect: (event: React.ChangeEvent<HTMLInputElement>) => void;
  handleImport: () => Promise<void>;
  handleConflictOverwrite: () => Promise<void>;
  handleConflictCopy: () => Promise<void>;
  handleConflictCancel: () => void;
  clearFileSelection: () => void;
}

// Export files are user-held and outlive a deploy, so one written before the
// project→ontology rename still spells this key project_id.
function readOntologyId(importData: Record<string, unknown>): string | null {
  const id = importData.ontology_id ?? importData.project_id;
  return typeof id === "string" && id.length > 0 ? id : null;
}

function readFileAsText(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result !== "string") {
        reject(new Error("Ontology file could not be read as text"));
        return;
      }
      resolve(reader.result);
    };
    reader.onerror = () => reject(reader.error ?? new Error("Ontology file could not be read"));
    reader.readAsText(file);
  });
}

// Owns the whole "import an ontology from a JSON export" flow: file selection,
// the overwrite-or-copy conflict prompt, the upload itself and the post-import
// datasource report. Extracted from CreateOntologyDialog, which is a form shell
// and should not also be an upload state machine.
export function useOntologyImport({
  scope,
  existingOntologies,
  onImported,
  onClose,
}: UseOntologyImportOptions): UseOntologyImportReturn {
  const [isImporting, setIsImporting] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [failedDatasources, setFailedDatasources] = useState<FailedDatasource[]>([]);
  const [importConflict, setImportConflict] = useState<ImportConflict | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const clearFileSelection = () => {
    setSelectedFile(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    if (file.type !== "application/json" && !file.name.endsWith(".json")) {
      toast.error("Please select a valid JSON file");
      event.target.value = "";
      return;
    }
    setSelectedFile(file);
  };

  const performImport = async (importData: Record<string, unknown>, forceNewId = false) => {
    try {
      setIsImporting(true);

      const response = await OntologyService.importOntology(importData, scope, forceNewId);

      if (!response?.new_ontology_id) {
        toast.error("Ontology import failed");
        return;
      }

      await onImported?.();

      clearFileSelection();
      onClose();

      toast.success("Ontology imported successfully");

      // The backend re-keys an import whose id is already claimed by an
      // ontology shared with this user: requests are routed by id alone, so
      // reusing it would leave one of the two unreachable. Say so, otherwise
      // the ontology appears under an id the user has never seen.
      const requestedOntologyId = readOntologyId(importData);
      if (!forceNewId && requestedOntologyId && requestedOntologyId !== response.new_ontology_id) {
        toast.info(
          `Its original ID was already taken by an ontology shared with you, ` +
            `so this copy was imported as ${response.new_ontology_id}.`,
        );
      }

      if (response.failed_datasources && response.failed_datasources.length > 0) {
        setFailedDatasources(response.failed_datasources);
      }
    } catch (error) {
      console.error("Import error:", error);
      toast.error("Failed to import ontology");
    } finally {
      setIsImporting(false);
    }
  };

  const handleImport = async () => {
    if (!selectedFile) {
      toast.error("Please select an ontology file to import");
      return;
    }

    try {
      setIsImporting(true);
      const fileContent = await readFileAsText(selectedFile);

      let importData: Record<string, unknown>;
      try {
        importData = JSON.parse(fileContent);
      } catch (_parseError) {
        toast.error("Invalid JSON file format");
        return;
      }

      const ontologyId = readOntologyId(importData);
      const existingOntology = ontologyId
        ? existingOntologies.find((o) => o.id === ontologyId)
        : undefined;

      if (existingOntology) {
        setImportConflict({ importData, existingOntology });
        return;
      }

      await performImport(importData);
    } catch (error) {
      console.error("Import error:", error);
      toast.error("Failed to import ontology");
    } finally {
      setIsImporting(false);
    }
  };

  const handleConflictOverwrite = async () => {
    if (!importConflict) return;
    setImportConflict(null);
    await performImport(importConflict.importData);
  };

  const handleConflictCopy = async () => {
    if (!importConflict) return;
    setImportConflict(null);
    await performImport(importConflict.importData, true);
  };

  const handleConflictCancel = () => {
    setImportConflict(null);
  };

  const conflictOntologyName =
    importConflict?.existingOntology.name || importConflict?.existingOntology.id || "";

  return {
    isImporting,
    selectedFile,
    fileInputRef,
    failedDatasources,
    dismissFailedDatasources: () => setFailedDatasources([]),
    importConflict,
    conflictOntologyName,
    handleFileSelect,
    handleImport,
    handleConflictOverwrite,
    handleConflictCopy,
    handleConflictCancel,
    clearFileSelection,
  };
}
