import type { ReactNode } from "react";
import type { FetchResult } from "../../api/ConceptClient";
import type { BadgeColor, DashboardWidget } from "../../types";
import { TableOutput } from "../outputs/TableOutput";
import type { BoundTableHandlers } from "../outputs/table/tableOutput.types";

const BADGE_CLASSES: Record<BadgeColor, string> = {
  green: "bg-green-50 text-green-700 border-green-200 dark:bg-green-900/20 dark:text-green-400",
  orange:
    "bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-400",
  purple:
    "bg-purple-50 text-purple-700 border-purple-200 dark:bg-purple-900/20 dark:text-purple-400",
  amber: "bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400",
  red: "bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-400",
  blue: "bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400",
  neutral: "bg-secondary text-muted-foreground border-border",
};

interface BadgeTableWidgetProps {
  data: FetchResult;
  widget: DashboardWidget;
  handlers?: BoundTableHandlers;
}

function resolveBadgeColor(
  value: string,
  colorMap: Record<string, BadgeColor> | undefined,
): BadgeColor {
  return colorMap?.[value] ?? "neutral";
}

export function BadgeTableWidget({ data, widget, handlers }: BadgeTableWidgetProps) {
  const { badgeColorMap } = widget;
  // Fall back to yCol (the "value col") when badgeCol isn't explicitly set —
  // the editor exposes Label col (xCol) and Value col (yCol), and the value
  // column is what should be badged (status / state).
  const badgeCol = widget.badgeCol ?? widget.yCol;

  const renderCell = (cell: unknown, _ri: number, ci: number): ReactNode => {
    const display = cell != null ? String(cell) : "—";
    if (ci !== badgeCol) {
      return <span className="text-foreground">{display}</span>;
    }
    const color = resolveBadgeColor(display, badgeColorMap);
    return (
      <span
        className={`inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium font-mono border ${BADGE_CLASSES[color]}`}
      >
        {display}
      </span>
    );
  };

  return <TableOutput data={data} handlers={handlers} renderCell={renderCell} />;
}
