import { Check, Copy, Download, Info } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";
import { Alert, AlertDescription, AlertTitle } from "@/shared/components/ui/alert";
import { Button } from "@/shared/components/ui/button";

interface RecoveryCodesDisplayProps {
  codes: string[];
  onDone: () => void;
}

export const RecoveryCodesDisplay = ({ codes, onDone }: RecoveryCodesDisplayProps) => {
  const [hasCopied, setHasCopied] = useState(false);
  const [hasAcknowledged, setHasAcknowledged] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(codes.join("\n"));
      setHasCopied(true);
      toast.success("Recovery codes copied to clipboard");
      setTimeout(() => setHasCopied(false), 2000);
    } catch {
      toast.error("Unable to copy to clipboard");
    }
  };

  const handleDownload = () => {
    const blob = new Blob([buildDownloadContents(codes)], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "prometheux-recovery-codes.txt";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-4">
      <Alert>
        <Info className="h-4 w-4" />
        <AlertTitle>Save these codes somewhere safe</AlertTitle>
        <AlertDescription>
          Each recovery code can only be used once and grants access if you lose your authenticator.
          They will not be shown again.
        </AlertDescription>
      </Alert>

      <div className="rounded-lg border border-border bg-muted/40 p-4 font-mono text-sm grid grid-cols-2 gap-2">
        {codes.map((code) => (
          <span key={code} className="select-all">
            {code}
          </span>
        ))}
      </div>

      <div className="flex flex-wrap gap-2">
        <Button variant="outline" onClick={handleCopy}>
          {hasCopied ? <Check className="h-4 w-4 mr-2" /> : <Copy className="h-4 w-4 mr-2" />}
          {hasCopied ? "Copied" : "Copy all"}
        </Button>
        <Button variant="outline" onClick={handleDownload}>
          <Download className="h-4 w-4 mr-2" />
          Download .txt
        </Button>
      </div>

      <label className="flex items-start gap-2 text-sm text-muted-foreground">
        <input
          type="checkbox"
          checked={hasAcknowledged}
          onChange={(event) => setHasAcknowledged(event.target.checked)}
          className="mt-1"
        />
        <span>I have saved my recovery codes in a secure location.</span>
      </label>

      <Button className="w-full" disabled={!hasAcknowledged} onClick={onDone}>
        Done
      </Button>
    </div>
  );
};

function buildDownloadContents(codes: string[]): string {
  const header = [
    "Prometheux — MFA recovery codes",
    `Generated: ${new Date().toISOString()}`,
    "Each code can be used only once. Store them somewhere safe.",
    "",
  ];
  return [...header, ...codes].join("\n");
}
