import type { DashboardDefinition } from "../types";
import type { AppDefinition, AppPageDef } from "./appDefinition.types";
import { isLegacyWidget, pageUsesV2Runtime } from "./appDefinition.types";

export const SCHEMA_VERSION = 2;

/**
 * Client-side mirror of the backend migrate-on-read (dashboard_schema.py):
 * v0 documents are wrapped into schema v2 — every page gains its owning
 * project reference and empty inputs/runGroups. Idempotent.
 */
export function migrateDefinition(definition: DashboardDefinition | AppDefinition): AppDefinition {
  const asApp = definition as AppDefinition;
  if ((asApp.schemaVersion ?? 0) >= SCHEMA_VERSION) return asApp;

  const legacy = definition as DashboardDefinition;
  return {
    ...legacy,
    schemaVersion: SCHEMA_VERSION,
    pages: legacy.pages.map((page) => ({
      project: { id: legacy.ontologyId ?? "" },
      inputs: [],
      runGroups: [],
      ...page,
    })) as AppPageDef[],
  };
}

/** True when at least one page needs the v2 runtime (inputs / run groups). */
export function usesV2Runtime(definition: AppDefinition): boolean {
  return definition.pages.some(pageUsesV2Runtime);
}

/**
 * Which editor owns a (migrated) definition. Anything on the v2 runtime is
 * v2; documents carrying legacy machinery (an input concept, index-bound
 * widgets) belong to the v0 canvas; empty documents — including apps freshly
 * scaffolded by the new-app flow — are v2-authorable.
 */
export function isV2Authorable(definition: AppDefinition): boolean {
  if (usesV2Runtime(definition)) return true;
  if (definition.inputConceptName) return false;
  const hasLegacyWidgets = definition.pages.some((page) =>
    page.sections?.some((section) => section.widgets?.some(isLegacyWidget)),
  );
  return !hasLegacyWidgets;
}

/** Fresh v2 definition for the new-app flow: one page, one empty section. */
export function createEmptyAppDefinition(name: string, ontologyId: string): AppDefinition {
  return {
    schemaVersion: SCHEMA_VERSION,
    id: crypto.randomUUID(),
    name,
    header: { title: name },
    pages: [
      {
        id: "page_1",
        label: "Page 1",
        project: { id: ontologyId },
        inputs: [],
        runGroups: [],
        sections: [{ id: "section_1", layout: "grid", widgets: [] }],
      },
    ],
  };
}
