import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { trackLogin } from "@/features/auth/utils/loginTracking";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { supabase } from "@/shared/integrations/supabase/client";
import { HttpService } from "@/shared/services/httpService";

export const useAuthHandlers = (identifier: string, password: string, isSignUp: boolean) => {
  const navigate = useNavigate();
  const { setIsLoginInProgress, setLoading } = useAuth();
  const [isLoading, setIsLoading] = useState(false);
  const [rateLimitTimer, setRateLimitTimer] = useState(0);
  const [resendRateLimitTimer, setResendRateLimitTimer] = useState(0);
  const [needsEmailConfirmation, setNeedsEmailConfirmation] = useState(false);

  const startRateLimitCountdown = (seconds: number, isResend: boolean = false) => {
    const timerSetter = isResend ? setResendRateLimitTimer : setRateLimitTimer;
    timerSetter(seconds);

    const interval = setInterval(() => {
      timerSetter((prev) => {
        if (prev <= 1) {
          clearInterval(interval);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  const checkPlatformAccessAndNavigate = async (userId: string) => {
    try {
      // Add timeout to prevent hanging (3 seconds for better UX)
      const timeoutPromise = new Promise<{ hasAccess: boolean; metadata?: any }>((_, reject) =>
        setTimeout(() => reject(new Error("Platform access check timeout")), 3000),
      );

      const platformAccessPromise = supabase
        .from("user_applications")
        .select(`
          status,
          metadata,
          applications!inner(name)
        `)
        .eq("user_id", userId)
        .eq("applications.name", "Platform")
        .single();

      const { data: userApp, error: userAppError } = (await Promise.race([
        platformAccessPromise,
        timeoutPromise,
      ])) as any;

      if (userAppError && userAppError.code !== "PGRST116") {
        // PGRST116 means no rows found
        throw userAppError;
      }

      const hasAccess = userApp?.status?.toLowerCase() === "enabled";

      if (hasAccess) {
        // Extract JWT token and metadata for enabled users
        let extractedToken = null;
        let extractedUsername = identifier.includes("@") ? identifier.split("@")[0] : identifier;
        let extractedOrganization;
        let apiUrl = null;

        if (userApp?.metadata) {
          try {
            const metadata = userApp.metadata;

            // Extract from metadata fields directly
            extractedUsername = metadata.username || extractedUsername;
            extractedOrganization = metadata.organization;
            extractedToken = metadata.jwt;
            apiUrl = metadata.url;
          } catch (error) {
            console.error("❌ Error extracting metadata:", error);
          }
        }

        // Set JWT token (always extract if available)
        if (extractedToken) {
          PROMETHEUX_CONFIG.AUTH_TOKEN = extractedToken;
          HttpService.setAuthToken(extractedToken);
        }

        // Update BASE_URL from metadata
        if (extractedUsername && extractedOrganization && apiUrl) {
          // Use the complete API URL from metadata
          PROMETHEUX_CONFIG.BASE_URL = apiUrl;
        }

        setIsLoginInProgress(false);
        setLoading(false);

        // Fetch permissions now so we can navigate directly to the first available page.
        try {
          const { data: permData } = await supabase.rpc("get_user_effective_permissions");
          usePermissionsStore.getState().setPermissions(permData ?? []);
        } catch {
          // AuthProvider will retry on session change — fall back to root.
        }

        const { defaultRoute } = usePermissionsStore.getState();
        navigate(defaultRoute ?? "/", { replace: true });
      } else {
        setIsLoginInProgress(false);
        setLoading(false);
        navigate("/onboarding");
      }
    } catch (error: any) {
      console.error("💥 Error in checkPlatformAccessAndNavigate:", error);
      // In production, if it's a timeout, allow access to prevent blocking the user
      if (import.meta.env.PROD && error.message.includes("timeout")) {
        setIsLoginInProgress(false);
        setLoading(false);
        const { defaultRoute } = usePermissionsStore.getState();
        navigate(defaultRoute ?? "/", { replace: true });
      } else {
        // In development or other errors, deny access for security
        toast.error("Failed to verify platform access. Please try again.");
        setIsLoginInProgress(false);
        setLoading(false);
      }
    }
  };

  const handleResendConfirmation = async () => {
    if (resendRateLimitTimer > 0) {
      return;
    }

    try {
      const { error: resendError } = await supabase.auth.resend({
        type: "signup",
        email: identifier,
      });

      if (resendError) {
        if (resendError.status === 429) {
          const waitSeconds = parseInt(resendError.message.match(/\d+/)?.[0] || "60", 10);
          startRateLimitCountdown(waitSeconds, true);
          throw new Error(
            `Please wait ${waitSeconds} seconds before requesting another confirmation email`,
          );
        }
        throw resendError;
      }
    } catch (error: any) {
      toast.error(error.message || "Failed to resend confirmation email");
    }
  };

  const handleEmailLogin = async (e: React.FormEvent) => {
    e.preventDefault();

    if (rateLimitTimer > 0) {
      return;
    }

    setIsLoading(true);
    setIsLoginInProgress(true);
    try {
      // For signup, we always require an email
      if (isSignUp) {
        if (!identifier.includes("@")) {
          throw new Error("Please provide a valid email address for signup");
        }

        const { data, error } = await supabase.auth.signUp({
          email: identifier,
          password,
          options: {
            emailRedirectTo: `${window.location.origin}/onboarding`,
            data: {
              email: identifier,
            },
          },
        });

        // Detect "email already registered" in two cases:
        //   1. The signup-user edge function (wired as a Before User Created
        //      auth hook on the backend) returns HTTP 409. The SDK surfaces
        //      this as an AuthApiError with status === 409.
        //   2. Supabase's email-enumeration protection: when enabled, signUp
        //      for an existing email returns a fake-success with no error and
        //      data.user.identities === []. Without this check we would show
        //      the success toast even though no user was created and no email
        //      was sent.
        const isAlreadyRegistered =
          error?.status === 409 ||
          (error?.message !== undefined && /already.*registered/i.test(error.message)) ||
          (!error && data.user !== null && (data.user.identities?.length ?? 0) === 0);

        if (isAlreadyRegistered) {
          toast.error("This email is already registered. Try logging in instead.");
          return;
        }

        if (error) throw error;

        toast.success(
          "Account created successfully! Please check your email to confirm your account.",
        );
      } else {
        // For login, check if the identifier is an email or username
        const isEmail = identifier.includes("@");
        let loginOptions;

        if (isEmail) {
          loginOptions = {
            email: identifier,
            password,
          };
        } else {
          // Use our new secure function to get email by username
          const { data: email, error: lookupError } = await supabase.rpc("get_email_by_username", {
            lookup_username: identifier,
          });

          if (lookupError) {
            throw new Error("Error looking up username");
          }

          if (!email) {
            throw new Error("Username not found");
          }

          loginOptions = {
            email,
            password,
          };
        }

        const { data, error } = await supabase.auth.signInWithPassword(loginOptions);

        if (error) {
          if (error.status === 429) {
            const waitSeconds = parseInt(error.message.match(/\d+/)?.[0] || "60", 10);
            startRateLimitCountdown(waitSeconds);
            throw new Error(`Please wait ${waitSeconds} seconds before trying again`);
          }

          // Let "Email not confirmed" fall through to the catch block, which
          // surfaces a toast and resets the loading state (an early return here
          // failed silently and left the form spinning).
          throw error;
        }

        if (data.session) {
          // Track the login
          await trackLogin(data.session.access_token, "password");

          // If the user has a verified MFA factor, Supabase reports
          // nextLevel === 'aal2' while the session is still aal1 — route them
          // through the challenge page before we check platform access.
          const { data: aal } = await supabase.auth.mfa.getAuthenticatorAssuranceLevel();
          if (aal?.nextLevel === "aal2" && aal?.currentLevel === "aal1") {
            setIsLoginInProgress(false);
            setLoading(false);
            navigate("/mfa-challenge");
            return;
          }

          // Check platform access before navigation
          await checkPlatformAccessAndNavigate(data.session.user.id);
        } else {
          throw new Error("No session returned from login");
        }
      }
    } catch (error: any) {
      setIsLoginInProgress(false);
      setLoading(false);

      const tooManyMessage = isSignUp
        ? "Too many signup attempts. Please wait a moment before trying again."
        : "Too many login attempts. Please wait a moment before trying again.";
      const genericMessage = isSignUp
        ? "Signup failed. Please try again."
        : "Login failed. Please try again.";

      // Show appropriate error message based on error type
      if (error.message?.includes("Invalid login credentials")) {
        toast.error("Invalid email or password. Please try again.");
      } else if (error.message?.includes("Email not confirmed")) {
        setNeedsEmailConfirmation(true);
        toast.error("Please check your email and click the confirmation link before signing in.");
      } else if (error.message?.includes("Too many requests")) {
        toast.error(tooManyMessage);
      } else {
        toast.error(error.message || genericMessage);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: "google",
        options: {
          redirectTo: `${window.location.origin}/`,
          queryParams: {
            access_type: "offline",
            prompt: "consent",
          },
        },
      });

      if (error) {
        throw error;
      }
    } catch (error: any) {
      console.error("Google login error:", error);
      toast.error("Google sign-in failed. Please try again.");
    }
  };

  const handleMicrosoftLogin = async () => {
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: "azure",
        options: {
          redirectTo: `${window.location.origin}/onboarding`,
          queryParams: {
            access_type: "offline",
            prompt: "consent",
          },
        },
      });

      if (error) throw error;
    } catch (_error: any) {
      toast.error("Microsoft sign-in failed. Please try again.");
    }
  };

  const handleMagicLinkLogin = async (email: string) => {
    try {
      setIsLoading(true);

      const { error } = await supabase.auth.signInWithOtp({
        email: email,
        options: {
          emailRedirectTo: `${window.location.origin}/`,
        },
      });

      if (error) {
        throw error;
      }

      toast.success("Magic link sent! Check your email (including spam/junk folder) to sign in.", {
        duration: 6000,
      });
    } catch (error: any) {
      console.error("Magic link error:", error);
      toast.error(error.message || "Failed to send magic link. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  return {
    handleEmailLogin,
    handleGoogleLogin,
    handleMicrosoftLogin,
    handleMagicLinkLogin,
    handleResendConfirmation,
    isLoading,
    rateLimitTimer,
    resendRateLimitTimer,
    needsEmailConfirmation,
  };
};
