import { Waypoints } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import ComputeIndicator from "@/features/compute/components/ComputeIndicator";
import type { ConceptData } from "@/features/concepts/api";
import { GlobalSearchTrigger } from "@/features/global-search/components/GlobalSearchTrigger";
import type { OntologyData } from "@/features/ontologies/api";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";
import { setCurrentOntologyId, setCurrentOntologyScope } from "@/features/ontologies/utils";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import SidePanel from "@/shared/components/layout/SidePanel";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";
import { ConceptDataTableView } from "./components/concept-graph/ConceptDataTableView";
import { ConceptGraphView } from "./components/concept-graph/ConceptGraphView";
import { type ExplorerPanelId, ExplorerRail } from "./components/ExplorerRail";
import { GraphExplorerEmptyState } from "./components/GraphExplorerEmptyState";
import { OntologiesPanel } from "./components/ontologies-panel/OntologiesPanel";
import { useConceptDataPreview } from "./hooks/useConceptDataPreview";
import { useConceptGraph } from "./hooks/useConceptGraph";
import { useConceptGraphDeepLink } from "./hooks/useConceptGraphDeepLink";
import { useGraphModel } from "./hooks/useGraphModel";
import { useModelBuilder } from "./hooks/useModelBuilder";
import { findConceptGraph } from "./model.utils";

const WORKSPACE_FALLBACK_ID = "workspace";

const GraphExplorerPage = () => {
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [activePanel, setActivePanel] = useState<ExplorerPanelId | null>("projects");
  const [focusPredicate, setFocusPredicate] = useState<string | null>(null);

  const ontologyId = useOntologyId() ?? WORKSPACE_FALLBACK_ID;
  const scope = useOntologyScope();

  const { model, isLoading, save } = useGraphModel(ontologyId, scope);
  const builder = useModelBuilder(model, scope, save);
  const conceptGraph = useConceptGraph(ontologyId, scope);
  const dataPreview = useConceptDataPreview(ontologyId, scope);

  const handleNeedsRoles = (concept: ConceptData, cardPredicate: string) => {
    setActivePanel("projects");
    setFocusPredicate(cardPredicate);
    // Show the concept's materialized data while the user picks roles —
    // fetched, not re-run (same call as the editor's "Restore results").
    dataPreview.show(concept.predicate_name);
    toast.info(
      `Assign a source and a target column on "${concept.predicate_name}" to visualize it`,
    );
  };

  const handleConceptDeepLinkOpened = (_concept: ConceptData, cardPredicate: string) => {
    setActivePanel("projects");
    setFocusPredicate(cardPredicate);
  };

  const handleDeepLinkShowGraph = (
    concept: ConceptData,
    roles: Parameters<typeof conceptGraph.show>[1],
    runPredicate?: string,
  ) => {
    dataPreview.close();
    conceptGraph.show(concept, roles, runPredicate);
  };

  useConceptGraphDeepLink({
    ontologyId,
    scope,
    isModelLoading: isLoading,
    model: model ?? null,
    predicate: conceptGraph.predicate,
    saveRoles: builder.saveConceptGraphRoles,
    showGraph: handleDeepLinkShowGraph,
    onNeedsRoles: handleNeedsRoles,
    onOpened: handleConceptDeepLinkOpened,
  });

  // Reset the concept graph when the Projects panel switches project.
  // Runs every render with a guard (the callback it invokes is not
  // referentially stable, so a dependency array would not help).
  const prevOntologyRef = useRef(ontologyId);
  const conceptGraphClose = conceptGraph.close;
  const dataPreviewClose = dataPreview.close;
  useEffect(() => {
    if (prevOntologyRef.current === ontologyId) return;
    prevOntologyRef.current = ontologyId;
    conceptGraphClose();
    dataPreviewClose();
  });

  const marginClass = sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0";

  const handleSelectOntology = (project: OntologyData | null) => {
    if (!project || project.id === ontologyId) return;
    setCurrentOntologyId(project.id);
    setCurrentOntologyScope(project.scope);
  };

  const handleShowConceptGraph = (concept: ConceptData, runPredicate?: string) => {
    const roles = findConceptGraph(model, concept.predicate_name)?.roles ?? {};
    dataPreview.close();
    conceptGraph.show(concept, roles, runPredicate);
  };

  const renderCenter = () => {
    if (conceptGraph.status !== "idle" && conceptGraph.predicate) {
      return (
        <ConceptGraphView
          predicate={conceptGraph.predicate}
          status={conceptGraph.status}
          error={conceptGraph.error}
          data={conceptGraph.data}
          mode={conceptGraph.mode}
          onModeChange={conceptGraph.setMode}
          onLoadFunction={conceptGraph.loadFunction}
          onRunAnalytics={conceptGraph.runAnalytics}
          onClearAnalytics={conceptGraph.clearAnalytics}
          onPageChange={conceptGraph.goToPage}
          tableQuery={conceptGraph.tableQuery}
          onSort={conceptGraph.setSort}
          onSearch={conceptGraph.setSearch}
          onClearSearch={conceptGraph.clearSearch}
          onClearColumnFilter={conceptGraph.clearColumnFilter}
          onPageSizeChange={conceptGraph.setPageSize}
          expandedNodeIds={conceptGraph.expandedNodeIds}
          expandingNodeIds={conceptGraph.expandingNodeIds}
          cappedNodeIds={conceptGraph.cappedNodeIds}
          onExpandNode={conceptGraph.expandNode}
          onLoadMoreNeighbors={conceptGraph.loadMoreNeighbors}
          onCollapseNode={conceptGraph.collapseNode}
          onClose={conceptGraph.close}
        />
      );
    }
    if (dataPreview.status !== "idle" && dataPreview.predicate) {
      return (
        <ConceptDataTableView
          predicate={dataPreview.predicate}
          status={dataPreview.status}
          error={dataPreview.error}
          columns={dataPreview.columns}
          rows={dataPreview.rows}
          pagination={dataPreview.pagination}
          onPageChange={dataPreview.goToPage}
          onClose={dataPreview.close}
        />
      );
    }
    if (isLoading) {
      return (
        <div className="flex-1 flex items-center justify-center">
          <PrometheuxSpinner />
        </div>
      );
    }
    return <GraphExplorerEmptyState />;
  };

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="graph-explorer"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-col flex-1 ${marginClass} overflow-hidden transition-all duration-200`}
      >
        <PageHeader
          title="Graph Explorer"
          icon={Waypoints}
          actions={
            <>
              <GlobalSearchTrigger />
              <ComputeIndicator interactive={true} />
            </>
          }
        />
        <div className="flex-1 flex min-h-0">
          <ExplorerRail activePanel={activePanel} onPanelChange={setActivePanel} />
          {activePanel === "projects" && (
            <OntologiesPanel
              activeOntologyId={ontologyId === WORKSPACE_FALLBACK_ID ? null : ontologyId}
              scope={scope}
              model={model ?? null}
              activeGraphPredicate={conceptGraph.predicate}
              isGraphBusy={conceptGraph.isBusy}
              focusPredicate={focusPredicate}
              onSelectOntology={handleSelectOntology}
              onRolesChange={builder.saveConceptGraphRoles}
              onShowGraph={handleShowConceptGraph}
            />
          )}
          <div className="flex-1 flex flex-col min-w-0">{renderCenter()}</div>
        </div>
      </div>
    </div>
  );
};

export default GraphExplorerPage;
