import type { LucideIcon } from "lucide-react";
import {
  AlertTriangle,
  CheckCircle2,
  Clock,
  Fingerprint,
  Layers,
  ListTodo,
  PlayCircle,
  Server,
  Timer,
  UserCircle2,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import type { SparkApplication, SparkExecutor, SparkJob } from "../types/engineMonitor.types";
import {
  computeTaskTotals,
  formatAbsoluteTime,
  formatUptime,
  getPrimaryAttempt,
  parseSparkTime,
} from "../utils/engineMonitor.utils";

interface EngineMonitorOverviewProps {
  jobs: SparkJob[];
  executors: SparkExecutor[];
  applications: SparkApplication[];
}

interface InfoCardProps {
  label: string;
  value: string;
  icon: LucideIcon;
}

const InfoCard: React.FC<InfoCardProps> = ({ label, value, icon: Icon }) => (
  <div className="rounded-lg border border-border bg-card px-3 py-2.5 hover:border-border/80 transition-colors">
    <div className="flex items-center gap-2 mb-1">
      <Icon className="h-3.5 w-3.5 text-muted-foreground" />
      <div className="text-[11px] font-medium text-muted-foreground uppercase tracking-wide">
        {label}
      </div>
    </div>
    <div className="text-sm font-semibold text-foreground truncate tabular-nums" title={value}>
      {value}
    </div>
  </div>
);

interface StatCardProps {
  label: string;
  value: number;
  icon: LucideIcon;
  accent: {
    bg: string;
    ring: string;
    text: string;
    iconBg: string;
  };
}

const StatCard: React.FC<StatCardProps> = ({ label, value, icon: Icon, accent }) => (
  <div
    className={`group relative overflow-hidden rounded-lg border ${accent.ring} ${accent.bg} p-3 transition-all hover:shadow-sm`}
  >
    <div className="flex items-start justify-between">
      <div className={`flex h-7 w-7 items-center justify-center rounded-md ${accent.iconBg}`}>
        <Icon className={`h-3.5 w-3.5 ${accent.text}`} />
      </div>
      <div className={`text-2xl font-bold leading-none tabular-nums ${accent.text}`}>{value}</div>
    </div>
    <div
      className={`text-[11px] font-medium mt-2 uppercase tracking-wide ${accent.text} opacity-90`}
    >
      {label}
    </div>
  </div>
);

const TASK_ACCENTS = {
  completed: {
    bg: "bg-emerald-50 dark:bg-emerald-950/30",
    ring: "border-emerald-200 dark:border-emerald-900/40",
    text: "text-emerald-700 dark:text-emerald-400",
    iconBg: "bg-emerald-100 dark:bg-emerald-900/40",
  },
  running: {
    bg: "bg-amber-50 dark:bg-amber-950/30",
    ring: "border-amber-200 dark:border-amber-900/40",
    text: "text-amber-700 dark:text-amber-400",
    iconBg: "bg-amber-100 dark:bg-amber-900/40",
  },
  failed: {
    bg: "bg-red-50 dark:bg-red-950/30",
    ring: "border-red-200 dark:border-red-900/40",
    text: "text-red-700 dark:text-red-400",
    iconBg: "bg-red-100 dark:bg-red-900/40",
  },
  total: {
    bg: "bg-sky-50 dark:bg-sky-950/30",
    ring: "border-sky-200 dark:border-sky-900/40",
    text: "text-sky-700 dark:text-sky-400",
    iconBg: "bg-sky-100 dark:bg-sky-900/40",
  },
} as const;

const SectionLabel: React.FC<{ icon: LucideIcon; label: string }> = ({ icon: Icon, label }) => (
  <div className="flex items-center gap-1.5 mb-2 px-0.5">
    <Icon className="h-3 w-3 text-muted-foreground" />
    <div className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">
      {label}
    </div>
  </div>
);

const EngineMonitorOverview: React.FC<EngineMonitorOverviewProps> = ({
  jobs,
  executors,
  applications,
}) => {
  const [now, setNow] = useState<Date>(() => new Date());

  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  const primaryApp = applications[0];
  const primaryAttempt = getPrimaryAttempt(primaryApp);
  const startedAt = parseSparkTime(primaryAttempt?.startTime);
  const sparkUser = primaryAttempt?.sparkUser ?? "—";
  const sessionId = primaryApp?.id ?? "—";
  const workerCount = executors.length;

  const taskTotals = useMemo(() => computeTaskTotals(jobs), [jobs]);
  const startedAtLabel = formatAbsoluteTime(startedAt);
  const uptimeLabel = formatUptime(startedAt, now);

  const completionRatio =
    taskTotals.total > 0
      ? Math.min(100, Math.round((taskTotals.completed / taskTotals.total) * 100))
      : 0;

  return (
    <div className="flex flex-col gap-4 p-3">
      <div>
        <SectionLabel icon={Timer} label="Session" />
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
          <InfoCard icon={Clock} label="Started At" value={startedAtLabel} />
          <InfoCard icon={Timer} label="Total Uptime" value={uptimeLabel} />
          <InfoCard icon={UserCircle2} label="User" value={sparkUser} />
        </div>
      </div>

      <div>
        <div className="flex items-center justify-between mb-2 px-0.5">
          <div className="flex items-center gap-1.5">
            <ListTodo className="h-3 w-3 text-muted-foreground" />
            <div className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">
              Tasks
            </div>
          </div>
          {taskTotals.total > 0 ? (
            <div className="flex items-center gap-2 text-[10px] text-muted-foreground">
              <span className="tabular-nums font-medium">{completionRatio}%</span>
              <span>complete</span>
            </div>
          ) : null}
        </div>

        {taskTotals.total > 0 ? (
          <div className="mb-2 h-1 w-full overflow-hidden rounded-full bg-muted">
            <div
              className="h-full rounded-full bg-gradient-to-r from-emerald-500 to-emerald-400 transition-all duration-500"
              style={{ width: `${completionRatio}%` }}
            />
          </div>
        ) : null}

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
          <StatCard
            label="Completed"
            value={taskTotals.completed}
            icon={CheckCircle2}
            accent={TASK_ACCENTS.completed}
          />
          <StatCard
            label="Running"
            value={taskTotals.running}
            icon={PlayCircle}
            accent={TASK_ACCENTS.running}
          />
          <StatCard
            label="Failed"
            value={taskTotals.failed}
            icon={AlertTriangle}
            accent={TASK_ACCENTS.failed}
          />
          <StatCard
            label="Total"
            value={taskTotals.total}
            icon={Layers}
            accent={TASK_ACCENTS.total}
          />
        </div>
      </div>

      <div>
        <SectionLabel icon={Server} label="Engine Configuration" />
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
          <InfoCard icon={Fingerprint} label="Session ID" value={sessionId} />
          <InfoCard icon={Server} label="Worker Nodes" value={String(workerCount)} />
        </div>
      </div>
    </div>
  );
};

export default EngineMonitorOverview;
