import { AlertCircle, CheckCircle2, CreditCard, ExternalLink, Loader2 } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/shared/components/ui/alert";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/shared/components/ui/card";
import { useBillingActions } from "../hooks/useBillingActions";
import { usePaidComputeEligibility } from "../hooks/usePaidComputeEligibility";
import { usePostCheckoutConfirmation } from "../hooks/usePostCheckoutConfirmation";
import { useSubscriberRow } from "../hooks/useSubscriberRow";
import { type UnpaidInvoice, useUnpaidInvoices } from "../hooks/useUnpaidInvoices";
import { GRACE_PERIOD_DAYS, isInvoiceOverdue, trialDaysRemaining } from "../utils/billing.utils";
import { UserInvoiceHistory } from "./UserInvoiceHistory";

interface StatusBadgeProps {
  isEligible: boolean | undefined;
  isLoading: boolean;
}

const StatusBadge = ({ isEligible, isLoading }: StatusBadgeProps) => {
  if (isLoading || isEligible === undefined) {
    return <Badge variant="outline">Checking…</Badge>;
  }
  if (isEligible) {
    return (
      <Badge className="border-green-200 bg-green-100 text-green-800 dark:border-green-800 dark:bg-green-900/40 dark:text-green-300">
        <CheckCircle2 className="mr-1 h-3 w-3" />
        Billing active
      </Badge>
    );
  }
  return (
    <Badge
      variant="outline"
      className="border-amber-300 text-amber-700 dark:border-amber-800 dark:text-amber-400"
    >
      Billing required
    </Badge>
  );
};

interface TrialNoticeProps {
  daysRemaining: number;
  endsAtIso: string;
}

const TrialNotice = ({ daysRemaining, endsAtIso }: TrialNoticeProps) => {
  const formattedDate = new Date(endsAtIso).toLocaleDateString();
  const dayLabel = daysRemaining === 1 ? "day" : "days";
  return (
    <Alert className="border-blue-200 bg-blue-50 dark:border-blue-800 dark:bg-blue-950/30">
      <AlertTitle className="text-blue-900 dark:text-blue-100">
        Trial — {daysRemaining} {dayLabel} remaining
      </AlertTitle>
      <AlertDescription className="text-blue-800 dark:text-blue-200">
        Your trial ends on {formattedDate}. Add a payment method to keep paid compute available
        afterwards.
      </AlertDescription>
    </Alert>
  );
};

interface OverdueNoticeProps {
  invoice: UnpaidInvoice;
}

const OverdueNotice = ({ invoice }: OverdueNoticeProps) => (
  <Alert variant="destructive">
    <AlertCircle className="h-4 w-4" />
    <AlertTitle>Payment overdue</AlertTitle>
    <AlertDescription>
      An invoice has been unpaid for more than {GRACE_PERIOD_DAYS} days. Update your payment method
      to keep paid compute running.
      {invoice.stripe_invoice_url && (
        <a
          href={invoice.stripe_invoice_url}
          target="_blank"
          rel="noopener noreferrer"
          className="ml-2 underline"
        >
          View invoice
        </a>
      )}
    </AlertDescription>
  </Alert>
);

const ConfirmingNotice = () => (
  <Alert className="border-blue-200 bg-blue-50 dark:border-blue-800 dark:bg-blue-950/30">
    <Loader2 className="h-4 w-4 animate-spin text-blue-600 dark:text-blue-400" />
    <AlertTitle className="text-blue-900 dark:text-blue-100">
      Confirming your subscription
    </AlertTitle>
    <AlertDescription className="text-blue-800 dark:text-blue-200">
      We're verifying your payment with Stripe. This usually takes a few seconds.
    </AlertDescription>
  </Alert>
);

export const BillingSettings = () => {
  const { isEligible, isLoading: isEligibilityLoading } = usePaidComputeEligibility();
  const { subscriber } = useSubscriberRow();
  const { invoices: unpaidInvoices } = useUnpaidInvoices();
  const { startCheckout, openCustomerPortal, isLaunchingCheckout, isOpeningPortal } =
    useBillingActions();
  const { isConfirming } = usePostCheckoutConfirmation(isEligible);

  const isTrialing = subscriber?.status === "trialing";
  const trialEndIso = subscriber?.current_period_end ?? null;
  const trialDays = isTrialing ? trialDaysRemaining(trialEndIso) : null;
  const oldestOverdue = unpaidInvoices.find((inv) => isInvoiceOverdue(inv.sent_at)) ?? null;
  const hasSubscription = Boolean(subscriber?.stripe_customer_id);
  const showSubscribe = !isEligibilityLoading && isEligible === false && !hasSubscription;
  const showManage = hasSubscription;

  return (
    <div className="space-y-6">
      {isConfirming && <ConfirmingNotice />}
      {isTrialing && trialDays !== null && trialEndIso && (
        <TrialNotice daysRemaining={trialDays} endsAtIso={trialEndIso} />
      )}
      {oldestOverdue && <OverdueNotice invoice={oldestOverdue} />}

      <Card>
        <CardHeader>
          <div className="flex items-start justify-between gap-4">
            <div className="space-y-1">
              <CardTitle className="flex items-center gap-2">
                <CreditCard className="h-5 w-5" />
                Subscription
              </CardTitle>
              <CardDescription>
                Paid compute requires an active subscription. Manage yours below.
              </CardDescription>
            </div>
            <StatusBadge isEligible={isEligible} isLoading={isEligibilityLoading} />
          </div>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-3">
            {showSubscribe && (
              <Button type="button" onClick={startCheckout} disabled={isLaunchingCheckout}>
                {isLaunchingCheckout ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                Set up billing
              </Button>
            )}
            {showManage && (
              <Button
                type="button"
                variant="outline"
                onClick={openCustomerPortal}
                disabled={isOpeningPortal}
              >
                {isOpeningPortal ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <ExternalLink className="mr-2 h-4 w-4" />
                )}
                Manage subscription
              </Button>
            )}
            {!showSubscribe && !showManage && !isEligibilityLoading && (
              <p className="text-sm text-muted-foreground">No action required.</p>
            )}
          </div>
        </CardContent>
      </Card>

      <div>
        <h3 className="mb-4 text-lg font-semibold text-foreground">Invoice history</h3>
        <UserInvoiceHistory />
      </div>
    </div>
  );
};
