import { useMutation, useQuery } from "@tanstack/react-query";

import {
  fetchInterviewTemplate,
  type InterviewSubmitRequest,
  type InterviewSubmitResult,
  type InterviewTemplate,
  submitInterview,
} from "../api/interviewApi";

export function useInterviewTemplate(scope: "global" | "ontology" = "global") {
  return useQuery<InterviewTemplate>({
    queryKey: ["interview-template", scope],
    queryFn: () => fetchInterviewTemplate(scope),
    staleTime: 60 * 60 * 1000,
    retry: 1,
  });
}

interface UseSubmitInterviewReturn {
  submit: (body: InterviewSubmitRequest) => Promise<InterviewSubmitResult>;
  isPending: boolean;
  errorMessage: string | null;
  reset: () => void;
}

/**
 * Wrap the submit mutation so consumers can read a single
 * `errorMessage: string | null` instead of digging into
 * `mutation.error?.message`. Keeps the React-Query type out of
 * components that just want a string to surface to the user.
 */
export function useSubmitInterview(): UseSubmitInterviewReturn {
  const mutation = useMutation<InterviewSubmitResult, Error, InterviewSubmitRequest>({
    mutationFn: submitInterview,
    // Mutations should not auto-retry — a duplicate POST would race
    // the idempotency check on the backend. The endpoint *is*
    // idempotent, but explicit retries should come from the user.
    retry: 0,
  });
  return {
    submit: mutation.mutateAsync,
    isPending: mutation.isPending,
    errorMessage: mutation.error?.message ?? null,
    reset: mutation.reset,
  };
}
