import { ChevronLeft, LogOut, MoreVertical, Repeat, Ticket, Trash2, Users2 } from "lucide-react";
import type React from "react";
import { useCallback, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useMyTeams } from "@/features/teams/hooks/useMyTeams";
import type { MemberRow, TeamError, TeamMembershipRow } from "@/features/teams/types";
import { teamRoleCapabilities, teamRoleMeta } from "@/features/teams/utils/teams.utils";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import TransferOwnershipDialog from "./TransferOwnershipDialog";

interface TeamDetailHeaderProps {
  team: TeamMembershipRow;
  members: MemberRow[];
  callerUserId: string;
}

// The "left" slot rendered inside PageHeader on the team detail page. Owns the
// header actions (kebab: transfer / leave / delete) and shows caller-scoped
// badges — role, seat status, and (for owner/admin) plan-seat utilization.
const TeamDetailHeader: React.FC<TeamDetailHeaderProps> = ({ team, members, callerUserId }) => {
  const navigate = useNavigate();
  const capabilities = teamRoleCapabilities(team.role);
  const roleTitle = teamRoleMeta(team.role).title;

  const { leave, isLeaving, transfer, isTransferring, deleteTeam, isDeletingTeam } = useMyTeams();

  const [showTransfer, setShowTransfer] = useState(false);

  const handleLeave = useCallback(async (): Promise<void> => {
    const confirmed = window.confirm(`Leave ${team.name}? You'll lose access to the team.`);
    if (!confirmed) return;
    try {
      await leave(team.id);
      toast.success(`Left ${team.name}`);
      navigate("/teams");
    } catch (err) {
      const teamErr = err as TeamError;
      // The backend refuses when an owner tries to leave with other members
      // still present — surface the transfer-ownership hint.
      if (teamErr.httpStatus === 409 || teamErr.httpStatus === 400) {
        toast.error(teamErr.message || "Transfer ownership before you can leave.", {
          description: "Only the owner can transfer ownership; do that first.",
        });
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to leave team";
      toast.error(message);
    }
  }, [leave, navigate, team.id, team.name]);

  const handleTransfer = useCallback(
    async (newOwnerUserId: string): Promise<void> => {
      await transfer({ teamId: team.id, newOwnerUserId });
    },
    [transfer, team.id],
  );

  const handleDelete = useCallback(async (): Promise<void> => {
    const confirmed = window.confirm(
      `Delete ${team.name}? This is permanent — the team, all memberships and pending invites will be removed.`,
    );
    if (!confirmed) return;
    try {
      await deleteTeam(team.id);
      toast.success(`Deleted ${team.name}`);
      navigate("/teams");
    } catch (err) {
      const teamErr = err as TeamError;
      // 403 = not the owner (shouldn't happen — the menu item is gated, but
      // network state can drift). 409 = backend refuses because other active
      // members still exist (implementation-defined; surface backend's detail).
      if (teamErr.httpStatus === 403) {
        toast.error(teamErr.message || "Only the team owner can delete this team.");
        return;
      }
      if (teamErr.httpStatus === 409) {
        toast.error(teamErr.message || "Team has other members.", {
          description: "Remove other members first, or transfer ownership.",
        });
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to delete team";
      toast.error(message);
    }
  }, [deleteTeam, navigate, team.id, team.name]);

  // Seat inventory (`seats_used` / `seats`) is only present for owner/admin
  // in the membership row. Falls back to a member-count for the used tally
  // in case an optimistic cache write hasn't been reconciled yet.
  const canSeeSeatCounter =
    capabilities.canManageSeats && typeof team.seats === "number" && team.seats > 0;
  const seatsUsed =
    typeof team.seats_used === "number"
      ? team.seats_used
      : members.filter((m) => m.seat_granted).length;

  const left = (
    <div className="flex min-w-0 flex-1 items-center gap-3">
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="h-8 w-8 shrink-0"
        onClick={() => navigate("/teams")}
        title="Back to Teams"
      >
        <ChevronLeft className="h-4 w-4" />
      </Button>
      <Users2 className="h-5 w-5 shrink-0 text-muted-foreground" />
      <div className="min-w-0">
        <div className="flex flex-wrap items-center gap-2">
          <h1 className="truncate font-bold leading-tight">{team.name}</h1>
          <Badge variant="outline" className="capitalize">
            {roleTitle}
          </Badge>
          {team.seat_granted && (
            <Badge className="gap-1 bg-amber-500/15 text-amber-700 hover:bg-amber-500/20 dark:text-amber-400">
              <Ticket className="h-3 w-3" />
              Seated
            </Badge>
          )}
          {canSeeSeatCounter && (
            <Badge variant="outline" className="gap-1" title="Plan seats used across the team">
              <Ticket className="h-3 w-3" />
              {seatsUsed} / {team.seats} seats
            </Badge>
          )}
        </div>
        <p className="truncate text-xs text-muted-foreground">
          @{team.slug}
          {team.linked_domain ? ` \u00b7 ${team.linked_domain}` : ""}
        </p>
      </div>
    </div>
  );

  const actions = (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button type="button" variant="outline" size="icon" title="Team settings">
            <MoreVertical className="h-4 w-4" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          {capabilities.canTransferOwnership && (
            <DropdownMenuItem
              className="gap-2"
              onSelect={() => setShowTransfer(true)}
              disabled={isTransferring}
            >
              <Repeat className="h-3.5 w-3.5" />
              Transfer ownership
            </DropdownMenuItem>
          )}
          {capabilities.canTransferOwnership && <DropdownMenuSeparator />}
          <DropdownMenuItem className="gap-2" onSelect={handleLeave} disabled={isLeaving}>
            <LogOut className="h-3.5 w-3.5" />
            Leave team
          </DropdownMenuItem>
          {capabilities.canDeleteTeam && (
            <DropdownMenuItem
              className="gap-2 text-destructive focus:text-destructive"
              onSelect={handleDelete}
              disabled={isDeletingTeam}
            >
              <Trash2 className="h-3.5 w-3.5" />
              Delete team
            </DropdownMenuItem>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    </>
  );

  return (
    <>
      <PageHeader left={left} actions={actions} />
      <TransferOwnershipDialog
        isOpen={showTransfer}
        onClose={() => setShowTransfer(false)}
        teamName={team.name}
        members={members}
        callerUserId={callerUserId}
        onTransfer={handleTransfer}
        isTransferring={isTransferring}
      />
    </>
  );
};

export default TeamDetailHeader;
