import { useQuery } from "@tanstack/react-query";
import { LayoutDashboard, Play, Trash2 } from "lucide-react";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import type { OntologyData } from "@/features/ontologies/api";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/shared/components/ui/alert-dialog";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import { Separator } from "@/shared/components/ui/separator";
import { type AppConcept, ConceptClient } from "../api/ConceptClient";
import { useCanvasDefinition } from "../hooks/useCanvasDefinition";
import { useCanvasRun } from "../hooks/useCanvasRun";
import type { DashboardDefinition } from "../types";
import { parseParamAnnotations } from "../utils/paramParser";
import { CanvasConfigPanel } from "./canvas/CanvasConfigPanel";
import { CanvasParamField } from "./canvas/CanvasParamField";
import { DashboardRenderer } from "./DashboardRenderer";

const client = new ConceptClient();

interface DashboardCanvasProps {
  dashboard: DashboardDefinition | null;
  projects: OntologyData[];
  onSave: (def: DashboardDefinition) => void;
  onDelete?: (id: string) => void;
}

export function DashboardCanvas({ dashboard, projects, onSave, onDelete }: DashboardCanvasProps) {
  const {
    name,
    setName,
    ontologyId,
    setOntologyId,
    inputConceptName,
    setInputConceptName,
    header,
    setHeader,
    pages,
    setPages,
    addPage,
    updatePage,
    removePage,
  } = useCanvasDefinition(dashboard);

  const [paramValues, setParamValues] = useState<Record<string, string | number | boolean>>({});

  const { data: concepts = [], isLoading: conceptsLoading } = useQuery<AppConcept[]>({
    queryKey: ["dashboard-concepts", ontologyId],
    queryFn: () => client.listConcepts(ontologyId),
    enabled: !!ontologyId,
  });

  const inputConcept = useMemo(
    () => concepts.find((c) => c.predicate_name === inputConceptName) ?? null,
    [concepts, inputConceptName],
  );

  const parsedParams = useMemo(() => {
    const ann = inputConcept?.concept_details?.[0]?.param_annotations;
    return ann ? parseParamAnnotations(ann) : [];
  }, [inputConcept]);

  const allWidgetConcepts = useMemo(() => {
    const names = new Set<string>();
    pages.forEach((p) =>
      p.sections.forEach((s) =>
        s.widgets.forEach((w) => {
          if (w.conceptName) names.add(w.conceptName);
        }),
      ),
    );
    return Array.from(names);
  }, [pages]);

  const {
    isRunning,
    runStatus,
    conceptData,
    loadingConcepts,
    errorConcepts,
    knownColumnsMap,
    handleRun,
    resetRunState,
    tableHandlers,
  } = useCanvasRun({ ontologyId, allWidgetConcepts, paramValues });

  // Reset param values and run state when switching dashboards
  useEffect(() => {
    setParamValues({});
    resetRunState();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dashboard?.id]);

  // Initialise param defaults when the input concept changes
  useEffect(() => {
    const ann = inputConcept?.concept_details?.[0]?.param_annotations;
    if (ann) {
      const defaults: Record<string, string | number | boolean> = {};
      parseParamAnnotations(ann).forEach((p) => {
        defaults[p.name] = p.defaultValue;
      });
      setParamValues(defaults);
    } else {
      setParamValues({});
    }
  }, [inputConceptName, inputConcept]);

  const handleSave = useCallback(() => {
    if (!name.trim() || !ontologyId) return;
    onSave({
      id: dashboard?.id ?? crypto.randomUUID(),
      name: name.trim(),
      ontologyId,
      inputConceptName,
      header,
      pages,
      createdAt: dashboard?.createdAt ?? new Date().toISOString(),
    });
  }, [name, ontologyId, inputConceptName, header, pages, dashboard, onSave]);

  const handleOntologyChange = (v: string) => {
    setOntologyId(v);
    setInputConceptName("");
    setPages([]);
  };

  const canSave = !!name.trim() && !!ontologyId;
  const canRun = !!ontologyId && allWidgetConcepts.length > 0;
  const hasData = Object.keys(conceptData).length > 0 || Object.keys(loadingConcepts).length > 0;

  const previewDef: DashboardDefinition = {
    id: dashboard?.id ?? "",
    name,
    ontologyId,
    inputConceptName,
    header,
    pages,
    createdAt: dashboard?.createdAt ?? "",
  };

  return (
    <div className="flex flex-col gap-6 h-full overflow-auto p-6">
      {/* ── Top bar ── */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <LayoutDashboard className="h-5 w-5 text-muted-foreground flex-shrink-0" />
          <Input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="App name…"
            className="h-8 text-base font-semibold w-64"
          />
        </div>
        {dashboard && onDelete && (
          <AlertDialog>
            <AlertDialogTrigger asChild>
              <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive">
                <Trash2 className="h-3.5 w-3.5" />
              </Button>
            </AlertDialogTrigger>
            <AlertDialogContent>
              <AlertDialogHeader>
                <AlertDialogTitle>Delete app?</AlertDialogTitle>
                <AlertDialogDescription>
                  <strong>{name || "This app"}</strong> will be permanently deleted. This action
                  cannot be undone.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel>Cancel</AlertDialogCancel>
                <AlertDialogAction
                  onClick={() => onDelete(dashboard.id)}
                  className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                >
                  Delete
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        )}
      </div>

      {/* ── Config panel ── */}
      <CanvasConfigPanel
        projects={projects}
        ontologyId={ontologyId}
        onOntologyChange={handleOntologyChange}
        inputConceptName={inputConceptName}
        setInputConceptName={setInputConceptName}
        concepts={concepts}
        conceptsLoading={conceptsLoading}
        header={header}
        setHeader={setHeader}
        pages={pages}
        addPage={addPage}
        updatePage={updatePage}
        removePage={removePage}
        knownColumnsMap={knownColumnsMap}
        canSave={canSave}
        onSave={handleSave}
      />

      {/* ── Parameters + run ── */}
      {inputConceptName && (
        <>
          <Separator />
          <div className="flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-medium">
                Parameters
                {parsedParams.length === 0 && (
                  <span className="text-muted-foreground font-normal ml-1.5">(none defined)</span>
                )}
              </h3>
              {inputConcept?.description && (
                <span className="text-xs text-muted-foreground max-w-sm text-right truncate">
                  {inputConcept.description}
                </span>
              )}
            </div>

            {parsedParams.length > 0 && (
              <div className="flex flex-wrap gap-4">
                {parsedParams.map((param) => (
                  <div key={param.name} className="flex flex-col gap-1 min-w-[160px]">
                    <Label htmlFor={`dp-${param.name}`} className="text-sm font-medium">
                      {param.name}
                    </Label>
                    <CanvasParamField
                      param={param}
                      value={paramValues[param.name] ?? param.defaultValue}
                      onChange={(val) => setParamValues((prev) => ({ ...prev, [param.name]: val }))}
                    />
                    <span className="text-xs text-muted-foreground">{param.type}</span>
                  </div>
                ))}
              </div>
            )}

            <div className="flex items-center gap-3">
              <Button
                onClick={handleRun}
                disabled={isRunning || !canRun}
                size="sm"
                className="gap-2"
              >
                {isRunning ? <PrometheuxSpinner size={16} /> : <Play className="h-3.5 w-3.5" />}
                {isRunning ? "Running…" : "Run"}
              </Button>
              {runStatus && <span className="text-xs text-muted-foreground">{runStatus}</span>}
            </div>
          </div>
        </>
      )}

      {/* ── Dashboard preview ── */}
      {hasData && (
        <>
          <Separator />
          <div
            className="border border-border rounded-lg overflow-hidden flex-shrink-0"
            style={{ height: "max(500px, calc(100vh - 380px))" }}
          >
            <DashboardRenderer
              dashboard={previewDef}
              data={conceptData}
              loadingConcepts={loadingConcepts}
              errorConcepts={errorConcepts}
              tableHandlers={tableHandlers}
            />
          </div>
        </>
      )}
    </div>
  );
}
