import type React from "react";
import { cn } from "@/shared/lib/utils";

export interface EditorRailItem<T extends string> {
  id: T;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
}

interface EditorRailProps<T extends string> {
  side: "left" | "right";
  items: Array<EditorRailItem<T>>;
  activePanel: T | null;
  onPanelChange: (panel: T | null) => void;
}

/**
 * Edge rail of vertical-label toggle buttons — the same docked-panel pattern
 * as the lineage view's LineageTreeRail / LibraryRail, so the app editor
 * collapses exactly like the rest of the product. Clicking the active item
 * closes its panel and gives the width back to the preview.
 */
export function EditorRail<T extends string>({
  side,
  items,
  activePanel,
  onPanelChange,
}: EditorRailProps<T>) {
  const handleClick = (id: T) => {
    onPanelChange(activePanel === id ? null : id);
  };

  return (
    <div
      className={cn(
        "w-8 flex-shrink-0 bg-card flex flex-col",
        side === "left" ? "border-r border-border" : "border-l border-border",
      )}
    >
      {items.map(({ id, label, icon: Icon }) => {
        const isActive = activePanel === id;
        return (
          <button
            key={id}
            type="button"
            onClick={() => handleClick(id)}
            title={label}
            aria-pressed={isActive}
            className={cn(
              "flex flex-col items-center gap-2 py-3 px-1 transition-colors",
              side === "left" ? "border-r-2" : "border-l-2",
              isActive
                ? "bg-accent text-accent-foreground border-primary"
                : "text-muted-foreground hover:bg-accent hover:text-accent-foreground border-transparent",
            )}
          >
            <Icon className="h-4 w-4 flex-shrink-0" />
            <span
              className="text-[10px] font-medium uppercase tracking-wider"
              style={{ writingMode: "vertical-rl", transform: "rotate(180deg)" }}
            >
              {label}
            </span>
          </button>
        );
      })}
    </div>
  );
}
