import { Navigate, useParams } from "react-router-dom";

/** Old /dashboards/:ontologyId/:id[/edit] links → the /apps equivalent. */
export function LegacyDashboardRedirect({ edit = false }: { edit?: boolean }) {
  const { ontologyId, id } = useParams<{ ontologyId: string; id: string }>();
  return <Navigate to={`/apps/${ontologyId}/${id}${edit ? "/edit" : ""}`} replace />;
}
