import { Link2, Plus } from "lucide-react";
import { useMemo, useState } from "react";

import { Button } from "@/shared/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/shared/components/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";

import { linkDisplayTitle } from "../notes/notesModel";
import type { ContextNote } from "../types";

interface AttachNoteControlsProps {
  /** Notes available to attach (workspace-wide, minus already attached). */
  candidates: ContextNote[];
  attachedIds: Set<string>;
  onAttach: (noteId: string) => void;
  onStartNewNote: () => void;
}

interface AttachCandidate {
  id: string;
  title: string;
}

function buildCandidates(notes: ContextNote[], attachedIds: Set<string>): AttachCandidate[] {
  return notes
    .filter((note) => !attachedIds.has(note.id))
    .map((note) => ({ id: note.id, title: linkDisplayTitle(note) }));
}

export function AttachNoteControls({
  candidates,
  attachedIds,
  onAttach,
  onStartNewNote,
}: AttachNoteControlsProps) {
  const [open, setOpen] = useState(false);
  const attachable = useMemo(
    () => buildCandidates(candidates, attachedIds),
    [candidates, attachedIds],
  );

  const handleSelect = (noteId: string) => {
    setOpen(false);
    onAttach(noteId);
  };

  return (
    <div className="flex items-center gap-1.5">
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button variant="outline" size="sm" className="h-7 gap-1.5 text-xs">
            <Link2 className="h-3.5 w-3.5" />
            Attach note
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-80 p-0" align="end">
          <Command>
            <CommandInput placeholder="Search notes…" />
            <CommandList>
              <CommandEmpty>No unattached notes found.</CommandEmpty>
              <CommandGroup>
                {attachable.map((candidate) => (
                  <CommandItem
                    key={candidate.id}
                    value={candidate.title}
                    onSelect={() => handleSelect(candidate.id)}
                  >
                    {candidate.title}
                  </CommandItem>
                ))}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
      <Button variant="outline" size="sm" className="h-7 gap-1.5 text-xs" onClick={onStartNewNote}>
        <Plus className="h-3.5 w-3.5" />
        New note
      </Button>
    </div>
  );
}
