import type { DashboardHeader, DashboardWidget } from "../types";

/**
 * Schema v2 — "dynamic apps" (ADR: adr-dynamic-apps-dashboards-v2).
 *
 * An app is a published viewport onto existing lineages: pages are tabs,
 * each bound to exactly one project, carrying its own inputs (typed values
 * and structured forms), run groups (params + facts bindings, execute list,
 * output taps) and a 12-column grid layout whose widgets project tap results.
 */

export type ScalarInputType =
  | "text"
  | "number"
  | "select"
  | "combobox"
  | "date"
  | "multi_select"
  | "checkbox"
  | "radio"
  | "password"
  | "textarea";

export interface OptionsSource {
  concept: string;
  valueCol?: string;
  labelCol?: string;
}

export interface VisibleWhen {
  field: string;
  equals: unknown;
}

export interface SeedFrom {
  concept: string;
  /** Maps concept column name → record field id when they differ. */
  columnToField?: Record<string, string>;
}

export interface FormFieldDef {
  id: string;
  type: ScalarInputType | "record_group";
  /** form layout "grid": columns (of 12) this field spans; defaults to 12 */
  span?: number;
  label?: string;
  required?: boolean;
  min?: number;
  max?: number;
  pattern?: string;
  placeholder?: string;
  options?: string[];
  optionsSource?: OptionsSource;
  default?: unknown;
  visibleWhen?: VisibleWhen;
  // record_group only
  fields?: FormFieldDef[];
  minRows?: number;
  maxRows?: number;
  seedFrom?: SeedFrom;
}

export interface FormSectionDef {
  title?: string;
  fields: FormFieldDef[];
}

export interface AppInputDef {
  id: string;
  type: ScalarInputType | "form";
  label?: string;
  required?: boolean;
  options?: string[];
  optionsSource?: OptionsSource;
  default?: unknown;
  placeholder?: string;
  /** form only */
  sections?: FormSectionDef[];
  submitLabel?: string;
  /**
   * "flow" (default): fields flow as a responsive filter bar.
   * "grid": 12-column grid; each field takes its `span` (default 12 = stacked
   * full width) — the record-editor / signup-card layout.
   */
  layout?: "flow" | "grid";
  /** "top" (default) or "left" — labels beside the controls (record editors) */
  labelPosition?: "top" | "left";
}

export type RunTrigger = "button" | "form" | "auto" | "load";

export interface OutputTap {
  id: string;
  concept: string;
}

export interface RunGroupDef {
  id: string;
  label?: string;
  trigger: RunTrigger;
  /** trigger === "form": the form input whose submission fires this group */
  formId?: string;
  /** @param name → "{{contextKey}}" or literal */
  params?: Record<string, string>;
  /** input predicate → "{{formId.recordGroupId}}" */
  facts?: Record<string, string>;
  execute: string[];
  outputs: OutputTap[];
}

export type FormatOperator = "less_than" | "greater_than" | "equals" | "not_equals";
export type FormatColor = "red" | "green" | "amber" | "blue" | "neutral";

export interface FormatRule {
  column: string;
  operator: FormatOperator;
  value: string | number;
  color: FormatColor;
  /** "text" (default): colored text. "badge": soft pill chip. */
  display?: "text" | "badge";
}

export type ColumnFormat = "number" | "percent" | "signed_percent";

export interface ButtonAction {
  type: "open_url" | "set_context" | "run_group";
  /** open_url */
  url?: string;
  /** set_context */
  key?: string;
  value?: unknown;
  /** run_group */
  groupId?: string;
}

export type AppWidgetType =
  | "input_ref"
  | "form_ref"
  | "run_button"
  | "button"
  | "rich_table"
  | "text"
  | "heatmap"
  | "stat_card"
  | "line_chart"
  | "area_chart"
  | "bar_chart"
  | "pie_chart";

export interface AppWidgetDef {
  id: string;
  type: AppWidgetType;
  span?: number;
  /** sections with layout "columns": which column stack this widget joins (1-based) */
  column?: number;
  label?: string;
  /** text widgets: static markdown (alternative to an outputId tap) */
  content?: string;
  /** input_ref / form_ref */
  inputId?: string;
  /** run_button */
  groupId?: string;
  /** tap widgets — the output tap this widget projects */
  outputId?: string;
  /** charts: x column name and one or more y series column names */
  x?: string;
  y?: string[];
  /**
   * charts: pivot long-format rows into one series per distinct value of this
   * column (e.g. rows of (entity, date, value) → one line per entity). When
   * set, `y` must name exactly one value column.
   */
  seriesCol?: string;
  /** stat_card */
  valueCol?: string;
  labelCol?: string;
  statSub?: string;
  /** heatmap */
  rowCol?: string;
  colCol?: string;
  /** rich_table: subset + order of columns to show (names) */
  columns?: string[];
  formatRules?: FormatRule[];
  /** rich_table: value formatting per column name */
  columnFormats?: Record<string, ColumnFormat>;
  /**
   * rich_table chrome. "full" (default): search + sort/filter + CSV +
   * pagination. "compact": sort + pagination only. "plain": just the table —
   * key-value detail panels.
   */
  variant?: "full" | "compact" | "plain";
  /** rich_table: publish the clicked row into the tab context under this key */
  onRowSelect?: { set: string };
  /** button */
  action?: ButtonAction;
  /** button visual style */
  buttonStyle?: "primary" | "outline" | "ghost";
}

export interface AppSectionDef {
  id: string;
  /**
   * "grid": 12-column row flow with per-widget span. "columns": side-by-side
   * card stacks — each widget joins the stack named by its `column`, and each
   * stack renders as one card (the customer-app two-card pattern).
   */
  layout?: "grid" | "columns" | "single" | "two_col" | "four_col";
  /** layout "columns": relative stack widths, e.g. [8, 4]; defaults to equal */
  weights?: number[];
  title?: string;
  widgets: Array<AppWidgetDef | DashboardWidget>;
}

export interface AppPageDef {
  id: string;
  label: string;
  project: { id: string };
  inputs: AppInputDef[];
  runGroups: RunGroupDef[];
  sections: AppSectionDef[];
}

export interface AppDefinition {
  schemaVersion: number;
  id: string;
  name: string;
  header: DashboardHeader;
  pages: AppPageDef[];
  /** legacy compatibility (v0 documents migrated on read) */
  ontologyId?: string;
  inputConceptName?: string;
  createdAt?: string;
}

/** A legacy widget binds a concept by name with numeric column indices. */
export function isLegacyWidget(widget: AppWidgetDef | DashboardWidget): widget is DashboardWidget {
  return "conceptName" in widget && typeof (widget as DashboardWidget).xCol === "number";
}

/** A page uses the v2 runtime when it declares inputs or run groups. */
export function pageUsesV2Runtime(page: AppPageDef): boolean {
  return (page.inputs?.length ?? 0) > 0 || (page.runGroups?.length ?? 0) > 0;
}

/**
 * A page renders through the v2 tab view unless it actually contains
 * index-bound legacy widgets. Empty pages and pages with only static v2
 * widgets (e.g. text) are v2 — "no run groups" does not mean "legacy".
 */
export function pageRendersV2(page: AppPageDef): boolean {
  return !page.sections?.some((section) => section.widgets?.some(isLegacyWidget));
}
