// Deployed builds are built from this file: the workflow copies it over
// prometheux.ts before `npm run build`. Anything that changes there has to
// change here too, or it simply does not exist in production.
import { getAuthToken, setAuthToken } from "@/shared/auth/authToken";

// Helper functions for cleaner configuration
const isSnowflakeMode = () => import.meta.env.VITE_SNOWFLAKE_MODE === "true";
// Databricks "embedded app" mode: skips auth, uses relative /api/v1, derives a mock
// user from the hostname. Use this when the SPA is served from inside a Databricks App.
const isDatabricksMode = () => import.meta.env.VITE_DATABRICKS_MODE === "true";
// Databricks "third-party" mode: keeps production auth, BASE_URL, and the real
// Supabase user, but renders the same Databricks-only UI as the embedded mode
// (Compute tab, manual engine-install instructions, etc.).
const isDatabricks3PMode = () => import.meta.env.VITE_DATABRICKS_3P_MODE === "true";
// True for either Databricks deployment style — used to gate Databricks-specific UI.
const isAnyDatabricksMode = () => isDatabricksMode() || isDatabricks3PMode();
const isDevelopmentMode = () => import.meta.env.DEV;
const shouldSkipAuth = () => isSnowflakeMode() || isDatabricksMode() || isDevelopmentMode();

export function getDefaultBaseUrl(): string {
  if (isDatabricksMode()) return "/api/v1";
  if (isSnowflakeMode()) return "/api/v1";
  if (isDevelopmentMode()) return "http://localhost:8000/api/v1";
  return "https://api.prometheux.ai/jarvispy/organization/username/api/v1";
}

// Deployments whose backend does not authenticate them: the SPA served from
// inside a Snowflake or Databricks app. Everywhere else the token arrives with
// the session.
function defaultAuthToken(): string {
  if (isSnowflakeMode()) return "snowflake-dev-token";
  if (isDatabricksMode()) return "platform-dev-token";
  return "";
}

setAuthToken(defaultAuthToken());

export const PROMETHEUX_CONFIG = {
  BASE_URL: getDefaultBaseUrl(),

  // A view onto the shared token (see shared/auth/authToken.ts). As a plain
  // field it was a second copy that sign-in no longer wrote, so every
  // `if (!AUTH_TOKEN) skip` guard stayed true and no data was ever fetched.
  get AUTH_TOKEN(): string {
    return getAuthToken();
  },
  set AUTH_TOKEN(value: string) {
    setAuthToken(value);
  },
  LLM_API_KEY: "",
  EMBEDDING_API_KEY: "",

  EMBEDDING: {
    MODEL_VERSION: "text-embedding-3-large",
    DIMENSIONS: 2048,
    EMBEDDING_PROVIDER: "openai",
    AZURE_EMBEDDING_ENDPOINT: "",
    AZURE_EMBEDDING_API_VERSION: "",
  },

  CHAT: {
    MODEL_VERSION: "claude-sonnet-4-6",
    TEMPERATURE: 0.5,
    MAX_TOKENS: 8192,
    STREAMING_ENABLED: false,
    LLM_PROVIDER: isSnowflakeMode() ? "snowflake_cortex" : "anthropic",
    AZURE_LLM_ENDPOINT: "",
    AZURE_LLM_API_VERSION: "",
    DATABRICKS_WORKSPACE_URL: "",
    DATABRICKS_CLIENT_ID: "",
    DATABRICKS_CLIENT_SECRET: "",
    SNOWFLAKE_ACCOUNT_URL: "",
  },

  SNOWFLAKE_MODE: isSnowflakeMode(),
  DATABRICKS_MODE: isDatabricksMode(),
  DATABRICKS_3P_MODE: isDatabricks3PMode(),
  // True for either Databricks deployment style — gate Databricks-specific UI on this,
  // not on DATABRICKS_MODE, unless the branch also affects auth/BASE_URL/mock user.
  DATABRICKS_UI_MODE: isAnyDatabricksMode(),
  DEVELOPMENT_MODE: isSnowflakeMode() || isDatabricksMode(),
  SKIP_AUTH: shouldSkipAuth(),
};
