import { useQueryClient } from "@tanstack/react-query";
import { useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { type HttpErrorInfo, HttpService } from "@/shared/services/httpService";
import { generateHomeUrl } from "@/shared/utils/navigationUtils";
import { resolveCurrentOntologyId } from "../../utils";
import { syncShares } from "../api";
import { handleSharedOntologyAuthError, setSelfHealContext } from "../selfHeal";
import { isInboxEntryOpenable } from "../utils/sharing.utils";
import { SHARE_INBOX_KEY, useShareInbox } from "./useShareInbox";

// One unattributed reconcile per window. A screen that fires several requests
// against an orphaned share id would otherwise sync once per failure.
const RECONCILE_THROTTLE_MS = 10_000;
const ORPHANED_SHARE_TOAST_ID = "orphaned-share-reconcile";

// Boot-time hook mounted at AppContent. Installs the HttpService error hook and
// keeps the self-heal controller in sync with the recipient's inbox snapshot.
//
// Lives at the app shell because it needs React Query, react-router and auth in
// scope — everything below this mount point benefits from automatic recovery
// when a share is revoked while the recipient is mid-session.
export function useSharedOntologiesSelfHeal(): void {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const navigate = useNavigate();
  const { entries } = useShareInbox();

  // Refs keep the controller's callbacks pointing at fresh state without forcing
  // a re-install on every inbox tick.
  const acceptedIdsRef = useRef<string[]>([]);
  const supabaseTokenRef = useRef<string | null>(null);
  const userRef = useRef(user);
  const lastReconcileAtRef = useRef(0);

  useEffect(() => {
    // Openable shares — accepted direct shares plus claimed team shares — are the
    // set the self-heal controller may evict. isInboxEntryOpenable folds both.
    acceptedIdsRef.current = entries.filter(isInboxEntryOpenable).map((e) => e.ontology_id);
  }, [entries]);

  useEffect(() => {
    supabaseTokenRef.current = session?.access_token ?? null;
  }, [session]);

  useEffect(() => {
    userRef.current = user;
  }, [user]);

  // Per-code fallback copy. The BE message is preferred when provided; these are
  // the safety net for empty / missing strings.
  const HEAL_FALLBACK: Record<
    "share_revoked" | "share_expired" | "team_membership_revoked",
    string
  > = {
    share_revoked: "Access to this shared ontology was revoked.",
    share_expired: "Access to this shared ontology has expired.",
    team_membership_revoked: "Your team's access to this shared ontology was revoked.",
  };

  // Single-shot heal performed on a confirmed share_revoked / share_expired /
  // team_membership_revoked for an accepted shared project. Order matches the BE
  // dev's contract: sync → invalidate inbox → toast → optional navigate home.
  const triggerHeal = async (
    failedOntologyId: string,
    code: "share_revoked" | "share_expired" | "team_membership_revoked",
    backendMessage: string,
  ): Promise<void> => {
    try {
      await syncShares(supabaseTokenRef.current);
    } catch {
      // sync is best-effort; the inbox invalidation below will reflect the
      // authoritative state from Supabase.
    }

    await queryClient.invalidateQueries({ queryKey: SHARE_INBOX_KEY });

    toast.error(backendMessage || HEAL_FALLBACK[code]);

    // Only navigate when the user is actually viewing the failed project — a
    // background 401 (e.g. lineage poll for a project they've already left) must
    // not yank them out of whatever screen they're on now.
    const currentOntologyId = sessionStorage.getItem("currentOntologyId");
    if (currentOntologyId === failedOntologyId) {
      navigate(generateHomeUrl(userRef.current));
    }
  };

  // Distinct from triggerHeal: the share is valid, the user just hit an
  // editor-only route as a viewer. Use a stable sonner id so a workflow firing
  // many parallel mutations only surfaces one toast.
  const notifyRoleMismatch = (failedOntologyId: string, backendMessage: string): void => {
    toast.error(backendMessage || "Editor access is required for this action.", {
      id: `role-mismatch:${failedOntologyId}`,
      description: backendMessage
        ? undefined
        : "Ask the ontology owner to grant you editor access.",
    });
  };

  // FE-bug-shaped failures: non-allowlisted route, stale ontology_id in URL, or
  // missing ontology_id in payload. Surface a generic toast so the user knows
  // something went wrong, and console.error the diagnostic data for triage.
  // No share eviction — the share itself is fine.
  const notifyShareBug = (
    code: "share_route_forbidden" | "share_project_mismatch" | "share_missing_project_id",
    data: Record<string, unknown> | null,
    backendMessage: string,
  ): void => {
    console.error("[Share auth contract violation]", code, { data, message: backendMessage });
    toast.error("Something went wrong with this shared ontology request.", {
      id: `share-bug:${code}`,
    });
  };

  const notifyConceptHidden = (conceptName: string, ontologyId: string): void => {
    queryClient.invalidateQueries({ queryKey: ["concepts", ontologyId] });
    toast.error(`Concept "${conceptName}" is hidden on this shared ontology.`, {
      id: `concept-hidden:${ontologyId}:${conceptName}`,
    });
  };

  const notifyConceptReadOnly = (conceptName: string, ontologyId: string): void => {
    toast.error(`Concept "${conceptName}" is read-only on this shared ontology.`, {
      id: `concept-read-only:${ontologyId}:${conceptName}`,
    });
  };

  // Fallback for a revoked/expired failure that matches nothing in the inbox
  // snapshot — typically an orphaned vault row, where the owner has revoked (so
  // the share is gone from the inbox) but the recipient's pod still routes that
  // ontology id to the owner. Syncing prunes the row; refetching then resolves
  // the id locally, which is what unblocks an imported copy sharing the id.
  // Throttled rather than deduped: there is no ontology id to key on.
  const reconcileOrphanedShares = async (
    code: "share_revoked" | "share_expired",
    backendMessage: string,
  ): Promise<void> => {
    const now = Date.now();
    if (now - lastReconcileAtRef.current < RECONCILE_THROTTLE_MS) return;
    lastReconcileAtRef.current = now;

    try {
      await syncShares(supabaseTokenRef.current);
    } catch {
      // Best-effort, exactly as in triggerHeal.
    }

    await queryClient.invalidateQueries({ queryKey: SHARE_INBOX_KEY });
    toast.error(backendMessage || HEAL_FALLBACK[code], { id: ORPHANED_SHARE_TOAST_ID });

    const ontologyId = resolveCurrentOntologyId();
    if (!ontologyId) return;
    await queryClient.invalidateQueries({
      predicate: (query) => query.queryKey.includes(ontologyId),
    });
  };

  useEffect(() => {
    setSelfHealContext({
      getAcceptedOntologyIds: () => acceptedIdsRef.current,
      triggerHeal,
      notifyRoleMismatch,
      notifyShareBug,
      notifyConceptHidden,
      notifyConceptReadOnly,
      reconcileOrphanedShares,
    });

    const handler = (info: HttpErrorInfo): void => {
      handleSharedOntologyAuthError(info);
    };
    const unregister = HttpService.setErrorHook(handler);

    return () => {
      unregister();
      setSelfHealContext(null);
    };
  }, [queryClient, navigate]);
}
