import type React from "react";
import { useExplorerSplitResize } from "./useExplorerSplitResize";

interface UseCellSplitPanesOptions<TView extends string> {
  /** Explorer (maximized) layout: editor on top, other views in a bottom panel. */
  splitLayout: boolean | undefined;
  currentView: TView;
  /** The cell's authoring view — the one that lives in the editor pane. */
  editorView: TView;
}

interface UseCellSplitPanesReturn {
  /** Editor pane is sharing the height with a bottom panel right now. */
  isBottomPanelOpen: boolean;
  editorPaneRef: React.RefObject<HTMLDivElement>;
  bottomPaneRef: React.RefObject<HTMLDivElement>;
  /** For the editor pane: hidden outside split layout, flex-sized when shared. */
  splitEditorStyle: React.CSSProperties | undefined;
  /** For whichever bottom view is showing — the complement of the editor's flex. */
  splitBottomFlexStyle: React.CSSProperties | undefined;
  editorRatio: number;
  handleSplitDragStart: (event: React.MouseEvent<HTMLDivElement>) => void;
  adjustRatio: (deltaRatio: number) => void;
}

/**
 * The editor/bottom-panel split every concept cell shares in Explorer view.
 *
 * Outside split layout the editor pane is hidden unless its own view is
 * selected (the cell shows one view at a time); inside it, the editor is always
 * mounted and the two panes divide the height in the persisted ratio. Cells
 * differ only in what their authoring view is called ("logic", "python",
 * "editor"), which is why this takes `editorView` rather than assuming a name.
 */
export function useCellSplitPanes<TView extends string>({
  splitLayout,
  currentView,
  editorView,
}: UseCellSplitPanesOptions<TView>): UseCellSplitPanesReturn {
  const { editorRatio, editorPaneRef, bottomPaneRef, handleDragStart, adjustRatio } =
    useExplorerSplitResize();

  const isEditorView = currentView === editorView;
  const isBottomPanelOpen = splitLayout && !isEditorView;

  const splitEditorStyle: React.CSSProperties | undefined = (() => {
    if (!splitLayout && !isEditorView) return { display: "none" };
    if (isBottomPanelOpen) return { flex: `${editorRatio} 1 0%` };
    return undefined;
  })();

  const splitBottomFlexStyle: React.CSSProperties | undefined = isBottomPanelOpen
    ? { flex: `${1 - editorRatio} 1 0%` }
    : undefined;

  return {
    isBottomPanelOpen,
    editorPaneRef,
    bottomPaneRef,
    splitEditorStyle,
    splitBottomFlexStyle,
    editorRatio,
    handleSplitDragStart: handleDragStart,
    adjustRatio,
  };
}
