import type React from "react";
import { useTeamMembers } from "@/features/teams/hooks/useTeamMembers";
import type { TeamMembershipRow } from "@/features/teams/types";
import InviteMemberForm from "./InviteMemberForm";
import TeamJoinRequestsSection from "./TeamJoinRequestsSection";
import TeamPendingInvitationsSection from "./TeamPendingInvitationsSection";

interface TeamInvitationsTabProps {
  team: TeamMembershipRow;
}

// Owner/admin-only tab that groups every "movement into membership" flow:
//   1. Invite a member — outbound admin action (creates a pending invitation)
//   2. Pending invitations — outbound queue awaiting the invitee's response
//   3. Join requests — inbound queue from domain-matching users awaiting an
//      approve/reject decision
//
// Order matches the funnel: create → awaiting response → inbound queue. The
// parent (TeamRosterPanel) gates this tab behind capabilities.canInvite so
// the tab bar never even shows it to regular members.
const TeamInvitationsTab: React.FC<TeamInvitationsTabProps> = ({ team }) => {
  // Only the invite form's mutation state lives here — the two list sections
  // own their own React Query hooks. Pulling `invite` from useTeamMembers
  // keeps the invalidation chain (invite → pending list) as it was, without
  // duplicating a hook here.
  const { invite, isInviting } = useTeamMembers(team.id);

  return (
    <div className="space-y-6">
      <section className="space-y-4 rounded-lg border border-border bg-card p-4">
        <div>
          <h3 className="text-sm font-semibold text-foreground">Invite a member</h3>
          <p className="text-xs text-muted-foreground">
            We'll send them an email with a link to join. They accept in-app — no CTA link needed.
          </p>
        </div>
        <InviteMemberForm onInvite={invite} isSubmitting={isInviting} />
      </section>

      <TeamPendingInvitationsSection teamId={team.id} />
      <TeamJoinRequestsSection teamId={team.id} />
    </div>
  );
};

export default TeamInvitationsTab;
