import type { LucideIcon } from "lucide-react";
import { Button } from "@/shared/components/ui/button";

export interface NodeActionButton {
  icon: LucideIcon;
  handler: () => void;
  title: string;
}

interface NodeActionButtonsProps {
  /** Canvas-space center (the selected node) the buttons circle around. */
  center: { x: number; y: number };
  buttons: NodeActionButton[];
  /** Convert a canvas-space point to DOM coordinates (network.canvasToDOM). */
  toDOM: (canvasPos: { x: number; y: number }) => { x: number; y: number };
}

// Radius is in canvas units (node visual radius is ~30 units) so it scales
// correctly at any zoom level — converted to DOM coordinates at render time.
const CANVAS_RADIUS = 60;

/** Floating actions arranged in a circle around a selected node. */
export function NodeActionButtons({ center, buttons, toDOM }: NodeActionButtonsProps) {
  const angleStep = (2 * Math.PI) / buttons.length;
  const positioned = buttons.map((button, index) => {
    const angle = index * angleStep - Math.PI / 2; // Start from top
    const canvasPos = {
      x: center.x + Math.cos(angle) * CANVAS_RADIUS,
      y: center.y + Math.sin(angle) * CANVAS_RADIUS,
    };
    const dom = toDOM(canvasPos);
    return { ...button, x: dom.x, y: dom.y };
  });

  return (
    <>
      {positioned.map(({ icon: Icon, handler, title, x, y }) => (
        <div
          key={title}
          className="absolute z-20 bg-background/95 backdrop-blur-sm border rounded-full shadow-lg"
          style={{ left: x, top: y, transform: "translate(-50%, -50%)" }}
        >
          <Button
            onClick={handler}
            variant="ghost"
            size="sm"
            title={title}
            className="h-8 w-8 p-0 rounded-full text-foreground transition-colors hover:[background-color:#d1d5db]"
          >
            <Icon className="w-4 h-4" />
          </Button>
        </div>
      ))}
    </>
  );
}
