import type React from "react";
import { FILE_ICON_BY_TYPE, GENERIC_FILE } from "./fileTypeIconMap";

export { FILE_ICON_BY_TYPE, type FileIconSpec, GENERIC_FILE, isFileType } from "./fileTypeIconMap";

/**
 * Resolves a file-type token (extension or format token) to its icon element, or
 * null when the token is not a known file type (so callers can fall back — e.g. to
 * a database icon). `sizeClassName` supplies the size (e.g. "h-4 w-4"); the color
 * comes from the shared map in `fileTypeIconMap.ts`.
 */
export const resolveFileIcon = (
  token: string | undefined | null,
  sizeClassName: string,
  colorClassName?: string,
): React.ReactElement | null => {
  if (!token) return null;
  const spec = FILE_ICON_BY_TYPE[token.toLowerCase()];
  if (!spec) return null;
  const { Icon, colorClass } = spec;
  return <Icon className={`${sizeClassName} ${colorClassName ?? colorClass}`} />;
};

/**
 * Like `resolveFileIcon` but never returns null — unknown tokens fall back to the
 * shared generic-file icon. Use this where the thing IS known to be a file (e.g. the
 * Files browser), so the unknown-file icon matches every other surface.
 */
export const resolveFileIconOrGeneric = (
  token: string | undefined | null,
  sizeClassName: string,
): React.ReactElement => {
  const spec = (token && FILE_ICON_BY_TYPE[token.toLowerCase()]) || GENERIC_FILE;
  const { Icon, colorClass } = spec;
  return <Icon className={`${sizeClassName} ${colorClass}`} />;
};
