import { History, MessageSquare, PanelLeftClose, Plus } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { ChatModelSelect } from "./ChatModelSelect";
import { ChatModeSelect } from "./ChatModeSelect";

interface ChatPanelHeaderProps {
  sessionTitle: string | null;
  activeCellName: string;
  isLoading: boolean;
  onNewChat: () => void;
  onToggleHistory: () => void;
  onClose: () => void;
}

export function ChatPanelHeader({
  sessionTitle,
  activeCellName,
  isLoading,
  onNewChat,
  onToggleHistory,
  onClose,
}: ChatPanelHeaderProps) {
  return (
    <div className="flex h-14 shrink-0 items-center gap-2 border-b bg-card px-3">
      <div className="flex items-center gap-1 flex-shrink-0">
        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={onClose}
          title="Dock to left"
          aria-label="Dock to left"
        >
          <PanelLeftClose className="h-3.5 w-3.5" />
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={onNewChat}
          title="New chat"
          disabled={isLoading}
        >
          <Plus className="h-3.5 w-3.5" />
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={onToggleHistory}
          title="Chat history"
        >
          <History className="h-3.5 w-3.5" />
        </Button>
      </div>
      <MessageSquare className="h-4 w-4 flex-shrink-0 text-blue-600 dark:text-blue-400" />
      <span className="truncate min-w-0 text-sm font-semibold text-foreground">
        {sessionTitle ?? "AI Assistant"}
      </span>
      {activeCellName && !sessionTitle && (
        <span className="text-xs text-muted-foreground truncate max-w-24" title={activeCellName}>
          · {activeCellName}
        </span>
      )}
      <div className="ml-auto flex flex-shrink-0 items-center gap-1.5">
        <ChatModeSelect />
        <ChatModelSelect />
      </div>
    </div>
  );
}
