import { useEffect, useState } from "react";
import { ConfigService, type CoveredModelInfo } from "@/features/settings/api/configService";
import { useConfigStore } from "@/features/settings/store/configStore";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

interface UseChatModelsReturn {
  /** Models available for the user's currently configured LLM provider. */
  models: string[];
  /** Per-model data-privacy metadata for any Covered Models in the list. */
  coveredModels: Record<string, CoveredModelInfo>;
  /** The subset of `models` that can be shown images. */
  visionModels: string[];
  isLoading: boolean;
  /** The provider the list was resolved for (e.g. "openai", "azure"). */
  provider: string;
}

function buildProviderCredentials(provider: string): Record<string, string> {
  if (provider === "databricks") {
    return {
      databricks_workspace_url: PROMETHEUX_CONFIG.CHAT.DATABRICKS_WORKSPACE_URL || "",
      databricks_client_id: PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_ID || "",
      databricks_client_secret: PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_SECRET || "",
    };
  }
  if (provider === "snowflake_cortex" && PROMETHEUX_CONFIG.CHAT.SNOWFLAKE_ACCOUNT_URL) {
    return { snowflake_account_url: PROMETHEUX_CONFIG.CHAT.SNOWFLAKE_ACCOUNT_URL };
  }
  return {};
}

/**
 * Lists the chat models available for the user's configured provider, mirroring
 * the Settings model picker. The backend's per-message model override reuses the
 * user's provider credentials, so the in-chat switcher must only offer models
 * valid for that same provider.
 */
export function useChatModels(): UseChatModelsReturn {
  // Re-read the global provider/model whenever the user's config is (re)loaded.
  // The config lives in the mutable PROMETHEUX_CONFIG global, so without this
  // signal the list would stay on the build-time default provider after login.
  const configVersion = useConfigStore((s) => s.configVersion);
  const provider = PROMETHEUX_CONFIG.CHAT.LLM_PROVIDER || "openai";
  const [models, setModels] = useState<string[]>([]);
  const [coveredModels, setCoveredModels] = useState<Record<string, CoveredModelInfo>>({});
  const [visionModels, setVisionModels] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (!PROMETHEUX_CONFIG.AUTH_TOKEN) return;

    let cancelled = false;
    setIsLoading(true);
    const configuredModel = PROMETHEUX_CONFIG.CHAT.MODEL_VERSION;

    ConfigService.listModels(provider, buildProviderCredentials(provider))
      .then((fetched) => {
        if (cancelled) return;
        const fallback = configuredModel ? [configuredModel] : [];
        setModels(fetched.models.length > 0 ? fetched.models : fallback);
        setCoveredModels(fetched.coveredModels);
        setVisionModels(fetched.visionModels);
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [provider, configVersion]);

  return { models, coveredModels, visionModels, isLoading, provider };
}
