import { ListChevronsDownUp, ListChevronsUpDown, Plus, RefreshCw, Search } from "lucide-react";
import type React from "react";
import { ExplorerHeaderIconButton } from "@/features/concept-editor/components/ExplorerHeaderIconButton";
import { cn } from "@/shared/lib/utils";

interface LibrarySidebarHeaderProps {
  title: string;
  isSearchOpen: boolean;
  isSearchActive: boolean;
  onToggleSearch: () => void;
  allExpanded: boolean;
  onToggleExpandAll: () => void;
  onRefresh: () => void;
  isRefreshing: boolean;
  /** Panel-specific create action (e.g. new project note) — panels that
   *  omit it show no plus button. */
  onCreate?: () => void;
  createLabel?: string;
}

/**
 * Header for the Concepts / Data sidebar — matches the Explorer tree header:
 * title on the left, icon buttons (search toggle, expand/collapse all, refresh)
 * on the right.
 */
export const LibrarySidebarHeader: React.FC<LibrarySidebarHeaderProps> = ({
  title,
  isSearchOpen,
  isSearchActive,
  onToggleSearch,
  allExpanded,
  onToggleExpandAll,
  onRefresh,
  isRefreshing,
  onCreate,
  createLabel = "New",
}) => (
  <div className="flex h-9 items-center justify-between border-b border-border bg-muted pl-3 pr-1.5">
    <span className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
      {title}
    </span>
    <div className="flex items-center gap-0.5">
      {onCreate && (
        <ExplorerHeaderIconButton
          icon={<Plus className="h-3.5 w-3.5" />}
          label={createLabel}
          onClick={onCreate}
        />
      )}
      <ExplorerHeaderIconButton
        icon={<Search className="h-3.5 w-3.5" />}
        label={isSearchOpen ? "Close search" : "Search"}
        active={isSearchOpen || isSearchActive}
        onClick={onToggleSearch}
      />
      <ExplorerHeaderIconButton
        icon={
          allExpanded ? (
            <ListChevronsDownUp className="h-3.5 w-3.5" />
          ) : (
            <ListChevronsUpDown className="h-3.5 w-3.5" />
          )
        }
        label={allExpanded ? "Collapse all" : "Expand all"}
        onClick={onToggleExpandAll}
      />
      <ExplorerHeaderIconButton
        icon={<RefreshCw className={cn("h-3.5 w-3.5", isRefreshing && "animate-spin")} />}
        label="Refresh"
        onClick={onRefresh}
      />
    </div>
  </div>
);
