import { create } from "zustand";
import type { FocusedWidgetRef } from "./agentContext";
import type { MessageAttachment } from "./attachments.types";
import type { HaltData } from "./halt.utils";
import {
  readStoredPanelWidth,
  readStoredSelectedModel,
  writeStoredSelectedModel,
} from "./storePersistence";
import { removeTurnAt } from "./turnIndex.utils";

export type MessageRole =
  | "user"
  | "assistant"
  | "thinking"
  | "tool"
  | "proposal"
  | "context_loaded"
  | "writer_proposal"
  | "clarification"
  | "authorization"
  | "credential_request"
  | "plan";
export type AssistAction = "suggest" | "fix" | "explain" | "implement";

/**
 * Lifecycle of a tool message in the chat panel.
 * Single source of truth so adding a new state (e.g. "cancelled")
 * doesn't require chasing the union across three files.
 */
export type ToolStatus = "running" | "done" | "error";

export interface ProposalColumn {
  name: string;
  type: string;
}

export interface ProposalData {
  tool: string;
  // concept proposals
  concept_name?: string;
  definition?: string;
  description?: string;
  // dashboard proposals
  dashboard_name?: string;
  dashboard_id?: string;
  page_count?: number;
  widget_count?: number;
  ontology_id?: string;
  // create_csv_datasource proposals
  predicate_name?: string;
  row_count?: number;
  columns?: ProposalColumn[];
  // save_ontology_schema proposals
  node_count?: number;
  edge_count?: number;
}

export interface ContextNotePreview {
  id: string;
  kind: string;
  scope: "global" | "ontology";
  pinned: boolean;
  preview: string;
}

export interface ContextLoadedData {
  count: number;
  notes: ContextNotePreview[];
}

export interface SupersedeCandidate {
  id: string;
  kind: string;
  scope: "global" | "ontology";
  text: string;
}

export interface WriterProposalData {
  scope: "global" | "ontology";
  kind: string;
  /** Empty when the writer pass omitted it; the backend then derives one. */
  title?: string;
  text: string;
  ontology_id?: string | null;
  supersedes?: SupersedeCandidate[];
}

export type WriterProposalState = "pending" | "saved" | "dismissed";

export interface ClarificationOption {
  label: string;
  value: string;
  description?: string;
}

export interface ClarificationData {
  question: string;
  options: ClarificationOption[];
  scope_picker: boolean;
  allow_custom: boolean;
  context?: string;
  ontology_id?: string | null;
}

export type ClarificationState = "pending" | "answered";

export interface AuthorizationData {
  /** Tool the assistant wants to run (e.g. "create_csv_datasource"). */
  tool: string;
  /** Stable hash of (tool, args); echoed back as a one-shot approval. */
  callKey: string;
  /** False for destructive/irreversible tools — only "Allow once" is offered. */
  persistable: boolean;
  /** Redacted argument summary for the prompt (large fields stripped upstream). */
  input?: Record<string, unknown>;
}

export type AuthorizationState = "pending" | "allowed_once" | "always_allowed" | "denied";

/** Which Databricks credential fields the assistant's secure form should ask for. */
export type CredentialField = "host" | "auth_mode" | "token" | "client_id" | "client_secret";

export interface CredentialRequestData {
  provider: "databricks";
  /** Empty when the user has not said which kind of credential they have. */
  auth_mode?: "token" | "oauth2" | "";
  fields: CredentialField[];
  /** Workspace already configured, shown as context rather than asked for again. */
  host?: string;
  context?: string;
}

export type CredentialRequestState = "pending" | "submitted" | "dismissed";

export type PlanStepStatus = "pending" | "in_progress" | "completed";

export interface PlanStep {
  content: string;
  status: PlanStepStatus;
}

export interface ToolProgressData {
  event: string;
  current?: number;
  total?: number;
  /** A ready-made line to show, for tools whose progress is not a count. */
  label?: string;
  filename?: string;
  document_id?: string;
}

export interface ChatMessage {
  id: string;
  role: MessageRole;
  content: string;
  action?: AssistAction;
  hasCodeBlock?: boolean;
  /** ISO-8601 send time, shown on hover. Set for user turns, live and restored. */
  createdAt?: string;
  /** Files sent with a user turn — rendered as chips beside the bubble. */
  attachments?: MessageAttachment[];
  /**
   * For a user bubble restored from history: which persisted user row it is,
   * 0-based. Counting rendered bubbles is not equivalent, because a stored
   * message can render to nothing and be dropped. Edit-and-rerun truncates the
   * conversation at this index, so an undercount would discard the wrong turn.
   */
  userTurnIndex?: number;
  // tool activity fields
  toolName?: string;
  toolDetail?: string;
  toolStatus?: ToolStatus;
  toolProgress?: ToolProgressData;
  // Raw tool call request/response, surfaced when a tool chip is expanded.
  toolInput?: Record<string, unknown>;
  toolResult?: Record<string, unknown>;
  // proposal fields
  proposalData?: ProposalData;
  // set when a create_ontology tool succeeds; used for navigation
  createdOntologyId?: string;
  // set when a tool fails — surfaced in the relevant proposal/tool card
  errorMessage?: string;
  // Knowledge Layer message fields
  contextLoaded?: ContextLoadedData;
  writerProposal?: WriterProposalData;
  writerProposalState?: WriterProposalState;
  clarification?: ClarificationData;
  clarificationState?: ClarificationState;
  // authorization request (role === "authorization")
  authorization?: AuthorizationData;
  authorizationState?: AuthorizationState;
  // secure credential form (role === "credential_request"). What the user types
  // into it goes straight to the backend, never through the chat.
  credentialRequest?: CredentialRequestData;
  credentialRequestState?: CredentialRequestState;
  // live task plan (role === "plan"); updated in place across the turn
  planSteps?: PlanStep[];
  // stable id of this plan (from the backend). One card per planId, so a new
  // multi-step task gets its own card while a continuing plan reuses this one.
  planId?: string;
}

interface CodeAssistantState {
  // ── Active editor state (synced from EditorPanel) ─────────────
  activeCode: string;
  activeCellId: string | null;
  activeCellName: string;
  setActiveCode: (code: string, cellId: string, cellName?: string) => void;

  // ── Session ───────────────────────────────────────────────────
  sessionId: string;
  sessionTitle: string | null;
  setSessionTitle: (title: string) => void;

  // ── Chat history sidebar ──────────────────────────────────────
  isHistoryOpen: boolean;
  toggleHistory: () => void;
  historyRevision: number;
  bumpHistoryRevision: () => void;

  // ── Chat state ────────────────────────────────────────────────
  messages: ChatMessage[];
  isLoading: boolean;
  isPanelOpen: boolean;
  userClosedPanel: boolean;
  /** Current docked-panel width in px, mirrored from usePanelResize. */
  panelWidth: number;
  setPanelWidth: (width: number) => void;
  activeModel: string | null;
  setActiveModel: (model: string) => void;
  /** User-selected chat model (persisted). Null → use saved LLM config default. */
  selectedModel: string | null;
  setSelectedModel: (model: string | null) => void;

  // ── Focused concept (set when opened via Ask AI button) ───────
  // When set, the first message of the session injects this concept's
  // name and code as context so the agent focuses on it exclusively.
  focusedConcept: { name: string; code: string } | null;
  setFocusedConcept: (concept: { name: string; code: string } | null) => void;

  // ── Focused widget (set by the app editor's "Ask AI" button) ──
  // Folded into the next outgoing message as a structured reference
  // block, then cleared — one-shot, like an attachment.
  focusedWidget: FocusedWidgetRef | null;
  setFocusedWidget: (widget: FocusedWidgetRef | null) => void;

  // Prompt text pre-filled into the composer (e.g. the editor's one-click
  // "Fix with AI"); the panel consumes it into its input, then clears it.
  // Not auto-sent — the user reviews and presses send.
  seededPrompt: string | null;
  setSeededPrompt: (prompt: string | null) => void;

  // ── Ontology schema sync ──────────────────────────────────────
  // Incremented whenever the agent saves an ontology schema;
  // OntologySchemaEditor watches this to know when to reload.
  ontologySchemaRevision: number;
  bumpOntologySchemaRevision: () => void;

  // ── Projects sync ─────────────────────────────────────────────
  // Incremented whenever the agent creates a project; ProjectsListPage
  // watches this to know when to reload.
  ontologiesRevision: number;
  bumpOntologiesRevision: () => void;

  // ── Dashboards sync ───────────────────────────────────────────
  // Incremented whenever the agent saves or deletes a dashboard;
  // the apps catalog watches this to invalidate the list query.
  dashboardsRevision: number;
  bumpDashboardsRevision: () => void;

  // ── Data sources sync ─────────────────────────────────────────
  // Incremented whenever the agent creates a CSV datasource;
  // datasource and concept-schema consumers watch this to refresh.
  datasourcesRevision: number;
  bumpDatasourcesRevision: () => void;

  // ── Context notes sync ────────────────────────────────────────
  // Incremented whenever the user edits a context note or rule on the
  // Notes page; sent per turn so the agent reloads <user_rules> and
  // its cached context mid-session instead of waiting for a reload.
  contextNotesRevision: number;
  bumpContextNotesRevision: () => void;

  // ── Active chat abort (shared by HomeChat and CodeAssistantPanel) ─
  activeChatAbortController: AbortController | null;
  setActiveChatAbortController: (controller: AbortController | null) => void;
  abortActiveChat: () => void;

  // ── Freemium agent-message limit dialog (shared by both send sites) ─
  isAgentLimitDialogOpen: boolean;
  openAgentLimitDialog: () => void;
  closeAgentLimitDialog: () => void;

  addUserMessage: (content: string, attachments?: MessageAttachment[]) => string;
  setAssistantMessage: (id: string, content: string) => void;
  appendToAssistantMessage: (id: string, chunk: string) => void;
  /** Append streamed reasoning to a "thinking" message, creating it on first chunk. */
  appendToThinkingMessage: (id: string, chunk: string) => void;
  addToolMessage: (tool: string, detail?: string, input?: Record<string, unknown>) => string;
  updateToolMessage: (
    id: string,
    status: Extract<ToolStatus, "done" | "error">,
    summary?: string,
    createdOntologyId?: string,
    errorMessage?: string,
    result?: Record<string, unknown>,
  ) => void;
  setToolProgress: (id: string, progress: ToolProgressData) => void;
  addProposalMessage: (data: ProposalData) => string;
  addContextLoadedMessage: (data: ContextLoadedData) => string;
  addWriterProposalMessage: (data: WriterProposalData) => string;
  setWriterProposalState: (id: string, state: WriterProposalState) => void;
  addClarificationMessage: (data: ClarificationData) => string;
  setClarificationState: (id: string, state: ClarificationState) => void;
  addAuthorizationMessage: (data: AuthorizationData) => string;
  setAuthorizationState: (id: string, state: AuthorizationState) => void;
  addCredentialRequestMessage: (data: CredentialRequestData) => string;
  setCredentialRequestState: (id: string, state: CredentialRequestState) => void;
  /**
   * One-shot tool-call approval keys to attach to the NEXT request only. Set
   * when the user clicks "Allow once"; consumed (read + cleared) by the turn
   * that resumes the pending action so it doesn't leak into unrelated turns.
   */
  pendingApprovedCalls: string[];
  setPendingApprovedCalls: (keys: string[]) => void;
  consumePendingApprovedCalls: () => string[];
  /**
   * Create or update (in place) a live plan card. Keyed on `planId`: the same
   * plan (re-emitted across turns/gates) reuses its card, a different plan gets
   * a new one — so multiple plans in one conversation each get their own card.
   */
  upsertPlanMessage: (steps: PlanStep[], planId?: string) => void;
  /**
   * Set when the backend cut a turn short on a budget. Not a message: a halt is
   * always the tail of a turn, so it renders under the transcript and clears
   * when the next one starts.
   */
  haltNotice: HaltData | null;
  setHaltNotice: (notice: HaltData | null) => void;
  setLoading: (loading: boolean) => void;
  /**
   * Drop the message with the given id and everything after it. Used by the
   * edit-and-rerun flow to discard the edited turn and all later messages
   * before the re-run streams fresh ones.
   */
  truncateFromMessage: (id: string) => void;
  /**
   * Drop one exchange — the user message with the given id and the assistant's
   * reply to it — keeping everything after it.
   */
  removeTurn: (id: string) => void;
  openPanel: () => void;
  togglePanel: () => void;
  closePanel: () => void;
  clearMessages: () => void;
  loadSession: (sessionId: string, messages: ChatMessage[], title: string | null) => void;
}

export const useCodeAssistantStore = create<CodeAssistantState>((set) => ({
  // ── Active editor state ───────────────────────────────────────
  activeCode: "",
  activeCellId: null,
  activeCellName: "",

  setActiveCode: (code, cellId, cellName) => {
    set({ activeCode: code, activeCellId: cellId, activeCellName: cellName ?? cellId });
  },

  // ── Session ───────────────────────────────────────────────────
  sessionId: crypto.randomUUID(),
  sessionTitle: null,
  setSessionTitle: (title) => set({ sessionTitle: title }),

  // ── Chat history sidebar ──────────────────────────────────────
  isHistoryOpen: false,
  toggleHistory: () => set((state) => ({ isHistoryOpen: !state.isHistoryOpen })),
  historyRevision: 0,
  bumpHistoryRevision: () => set((state) => ({ historyRevision: state.historyRevision + 1 })),

  // ── Chat state ────────────────────────────────────────────────
  messages: [],
  isLoading: false,
  isPanelOpen: false,
  userClosedPanel: false,
  panelWidth: readStoredPanelWidth(),
  setPanelWidth: (width) => set({ panelWidth: width }),
  activeModel: null,
  setActiveModel: (model) => set({ activeModel: model }),
  selectedModel: readStoredSelectedModel(),
  setSelectedModel: (model) => {
    writeStoredSelectedModel(model);
    set({ selectedModel: model });
  },
  focusedConcept: null,
  setFocusedConcept: (concept) => set({ focusedConcept: concept }),
  focusedWidget: null,
  setFocusedWidget: (widget) => set({ focusedWidget: widget }),
  seededPrompt: null,
  setSeededPrompt: (prompt) => set({ seededPrompt: prompt }),

  activeChatAbortController: null,
  setActiveChatAbortController: (controller) => set({ activeChatAbortController: controller }),
  abortActiveChat: () => {
    const { activeChatAbortController } = useCodeAssistantStore.getState();
    activeChatAbortController?.abort();
    // Drop the spinner here — the aborted fetch only rejects a microtask later.
    set({ activeChatAbortController: null, isLoading: false });
  },

  isAgentLimitDialogOpen: false,
  openAgentLimitDialog: () => set({ isAgentLimitDialogOpen: true }),
  closeAgentLimitDialog: () => set({ isAgentLimitDialogOpen: false }),

  addUserMessage: (content, attachments) => {
    const id = crypto.randomUUID();
    set((state) => ({
      messages: [
        ...state.messages,
        { id, role: "user", content, attachments, createdAt: new Date().toISOString() },
      ],
      // Plan cards are keyed by their backend planId (see upsertPlanMessage), so
      // a new turn needs no bookkeeping here: a continuing plan reuses its card
      // and a different plan gets its own — one card per plan, across turns.
    }));
    return id;
  },

  setAssistantMessage: (id, content) => {
    const hasCodeBlock = content.includes("```");
    set((state) => ({
      messages: state.messages.map((m) => (m.id === id ? { ...m, content, hasCodeBlock } : m)),
    }));
  },

  appendToAssistantMessage: (id, chunk) => {
    set((state) => {
      const existing = state.messages.find((m) => m.id === id);
      if (!existing) {
        return {
          messages: [
            ...state.messages,
            { id, role: "assistant" as MessageRole, content: chunk, hasCodeBlock: false },
          ],
        };
      }
      const newContent = existing.content + chunk;
      return {
        messages: state.messages.map((m) =>
          m.id === id ? { ...m, content: newContent, hasCodeBlock: newContent.includes("```") } : m,
        ),
      };
    });
  },

  appendToThinkingMessage: (id, chunk) => {
    set((state) => {
      const existing = state.messages.find((m) => m.id === id);
      if (!existing) {
        return {
          messages: [...state.messages, { id, role: "thinking" as MessageRole, content: chunk }],
        };
      }
      return {
        messages: state.messages.map((m) =>
          m.id === id ? { ...m, content: m.content + chunk } : m,
        ),
      };
    });
  },

  addToolMessage: (tool, detail, input) => {
    const id = crypto.randomUUID();
    set((state) => ({
      messages: [
        ...state.messages,
        {
          id,
          role: "tool" as MessageRole,
          content: tool,
          toolName: tool,
          toolDetail: detail,
          toolStatus: "running" as const,
          toolInput: input,
        },
      ],
    }));
    return id;
  },

  updateToolMessage: (id, status, summary, createdOntologyId, errorMessage, result) => {
    set((state) => ({
      messages: state.messages.map((m) =>
        m.id === id
          ? {
              ...m,
              toolStatus: status,
              content: summary ?? m.content,
              // Keep toolProgress in place: for fast tools (single-chunk
              // ingest, etc.) the in-flight counter would only flash for
              // ~100ms before being cleared. Persisting the final count
              // alongside the ✓ gives the user proof of what landed.
              ...(createdOntologyId ? { createdOntologyId } : {}),
              ...(errorMessage ? { errorMessage } : {}),
              ...(result ? { toolResult: result } : {}),
            }
          : m,
      ),
    }));
  },

  setToolProgress: (id, progress) => {
    set((state) => ({
      messages: state.messages.map((m) => (m.id === id ? { ...m, toolProgress: progress } : m)),
    }));
  },

  addProposalMessage: (data) => {
    const id = crypto.randomUUID();
    set((state) => ({
      messages: [
        ...state.messages,
        {
          id,
          role: "proposal" as MessageRole,
          content: data.concept_name ?? data.predicate_name ?? data.tool,
          proposalData: data,
          toolStatus: "running" as const,
        },
      ],
    }));
    return id;
  },

  addContextLoadedMessage: (data) => {
    const id = crypto.randomUUID();
    set((state) => ({
      messages: [
        ...state.messages,
        {
          id,
          role: "context_loaded" as MessageRole,
          content: `${data.count} note${data.count === 1 ? "" : "s"}`,
          contextLoaded: data,
        },
      ],
    }));
    return id;
  },

  addWriterProposalMessage: (data) => {
    const id = crypto.randomUUID();
    set((state) => ({
      messages: [
        ...state.messages,
        {
          id,
          role: "writer_proposal" as MessageRole,
          content: data.text,
          writerProposal: data,
          writerProposalState: "pending" as const,
        },
      ],
    }));
    return id;
  },

  setWriterProposalState: (id, state) => {
    set((current) => ({
      messages: current.messages.map((m) =>
        m.id === id ? { ...m, writerProposalState: state } : m,
      ),
    }));
  },

  addClarificationMessage: (data) => {
    const id = crypto.randomUUID();
    set((state) => ({
      messages: [
        ...state.messages,
        {
          id,
          role: "clarification" as MessageRole,
          content: data.question,
          clarification: data,
          clarificationState: "pending" as ClarificationState,
        },
      ],
    }));
    return id;
  },

  setClarificationState: (id, state) => {
    set((current) => ({
      messages: current.messages.map((m) =>
        m.id === id ? { ...m, clarificationState: state } : m,
      ),
    }));
  },

  addAuthorizationMessage: (data) => {
    const id = crypto.randomUUID();
    set((state) => ({
      messages: [
        ...state.messages,
        {
          id,
          role: "authorization" as MessageRole,
          content: data.tool,
          authorization: data,
          authorizationState: "pending" as AuthorizationState,
        },
      ],
    }));
    return id;
  },

  setAuthorizationState: (id, state) => {
    set((current) => ({
      messages: current.messages.map((m) =>
        m.id === id ? { ...m, authorizationState: state } : m,
      ),
    }));
  },

  addCredentialRequestMessage: (data) => {
    const id = crypto.randomUUID();
    set((state) => ({
      messages: [
        ...state.messages,
        {
          id,
          role: "credential_request" as MessageRole,
          content: data.context || "",
          credentialRequest: data,
          credentialRequestState: "pending" as CredentialRequestState,
        },
      ],
    }));
    return id;
  },

  setCredentialRequestState: (id, state) => {
    set((current) => ({
      messages: current.messages.map((m) =>
        m.id === id ? { ...m, credentialRequestState: state } : m,
      ),
    }));
  },

  pendingApprovedCalls: [],
  setPendingApprovedCalls: (keys) => set({ pendingApprovedCalls: keys }),
  consumePendingApprovedCalls: () => {
    const { pendingApprovedCalls } = useCodeAssistantStore.getState();
    if (pendingApprovedCalls.length > 0) set({ pendingApprovedCalls: [] });
    return pendingApprovedCalls;
  },

  upsertPlanMessage: (steps, planId) => {
    // The backend tags every plan with a stable id; without one (or with no
    // steps) there is nothing to key a card on, so ignore the event.
    if (!planId || steps.length === 0) return;
    set((state) => {
      const existing = state.messages.find((m) => m.role === "plan" && m.planId === planId);
      // Same plan → update in place (same message id → no remount, the spinner
      // keeps its state) and pin it to the bottom so the live plan sits at the
      // end of the transcript instead of drifting up-chat as content streams in.
      if (existing) {
        const others = state.messages.filter((m) => m.id !== existing.id);
        return { messages: [...others, { ...existing, planSteps: steps }] };
      }
      // A new plan (new id) → its own card, so distinct plans in one
      // conversation coexist instead of overwriting each other.
      const id = crypto.randomUUID();
      return {
        messages: [
          ...state.messages,
          { id, role: "plan" as MessageRole, content: "Plan", planSteps: steps, planId },
        ],
      };
    });
  },

  haltNotice: null,
  setHaltNotice: (notice) => set({ haltNotice: notice }),

  setLoading: (loading) => set({ isLoading: loading }),

  truncateFromMessage: (id) => {
    set((state) => {
      const idx = state.messages.findIndex((m) => m.id === id);
      if (idx < 0) return {};
      return { messages: state.messages.slice(0, idx) };
    });
  },

  removeTurn: (id) => {
    set((state) => {
      const idx = state.messages.findIndex((m) => m.id === id);
      if (idx < 0) return {};
      return { messages: removeTurnAt(state.messages, idx) };
    });
  },

  openPanel: () => set({ isPanelOpen: true, userClosedPanel: false }),

  // Opened by the user (FAB or programmatically) — clears the "user closed" flag
  togglePanel: () =>
    set((state) => ({
      isPanelOpen: !state.isPanelOpen,
      userClosedPanel: state.isPanelOpen ? state.userClosedPanel : false,
    })),

  // Closed by the user via the X button — suppresses future auto-opens
  closePanel: () => set({ isPanelOpen: false, userClosedPanel: true }),

  clearMessages: () =>
    set({
      messages: [],
      sessionId: crypto.randomUUID(),
      sessionTitle: null,
      userClosedPanel: false,
      focusedConcept: null,
      focusedWidget: null,
      seededPrompt: null,
      activeModel: null,
      haltNotice: null,
    }),

  loadSession: (sessionId, messages, title) =>
    set({
      sessionId,
      sessionTitle: title,
      messages,
      focusedConcept: null,
      focusedWidget: null,
      activeModel: null,
      userClosedPanel: false,
      haltNotice: null,
    }),

  ontologySchemaRevision: 0,
  bumpOntologySchemaRevision: () =>
    set((state) => ({ ontologySchemaRevision: state.ontologySchemaRevision + 1 })),

  ontologiesRevision: 0,
  bumpOntologiesRevision: () =>
    set((state) => ({ ontologiesRevision: state.ontologiesRevision + 1 })),

  dashboardsRevision: 0,
  bumpDashboardsRevision: () =>
    set((state) => ({ dashboardsRevision: state.dashboardsRevision + 1 })),

  datasourcesRevision: 0,
  bumpDatasourcesRevision: () =>
    set((state) => ({ datasourcesRevision: state.datasourcesRevision + 1 })),

  contextNotesRevision: 0,
  bumpContextNotesRevision: () =>
    set((state) => ({ contextNotesRevision: state.contextNotesRevision + 1 })),
}));
