import { useQuery } from "@tanstack/react-query";
import { MapPin, Shield, User } from "lucide-react";
import { useState } from "react";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { LoginActivity } from "@/features/settings/components/login-activity/LoginActivity";
import { PasswordChangeForm } from "@/features/settings/components/users/profile/PasswordChangeForm";
import MfaSettings from "@/features/settings/components/users/profile/security/MfaSettings";
import { UserProfileForm } from "@/features/settings/components/users/profile/UserProfileForm";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import SidePanel from "@/shared/components/layout/SidePanel";
import { Separator } from "@/shared/components/ui/separator";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";
import { supabase } from "@/shared/integrations/supabase/client";

type ActiveTab = "profile" | "security" | "login-activity";

const TAB_ITEMS: Array<{ id: ActiveTab; label: string; icon: typeof User }> = [
  { id: "profile", label: "Profile", icon: User },
  { id: "security", label: "Security", icon: Shield },
  { id: "login-activity", label: "Login Activity", icon: MapPin },
];

const noop = () => {};

const ProfilePage = () => {
  const { user } = useAuth();
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [activeTab, setActiveTab] = useState<ActiveTab>("profile");

  const { data: currentUser } = useQuery({
    queryKey: ["profile", user?.id],
    queryFn: async () => {
      const {
        data: { user: authUser },
      } = await supabase.auth.getUser();
      if (!authUser) throw new Error("No user found");
      const { data: profile, error } = await supabase
        .from("profiles")
        .select("*")
        .eq("id", authUser.id)
        .single();
      if (error) throw error;
      return profile;
    },
    enabled: !!user,
  });

  const marginClass = sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0";

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="profile"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-col flex-1 ${marginClass} overflow-hidden transition-all duration-200`}
      >
        <PageHeader title="User Info" icon={User} />

        {/* Tab bar */}
        <div className="flex border-b border-border px-6">
          {TAB_ITEMS.map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              type="button"
              onClick={() => setActiveTab(id)}
              className={`flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium transition-colors ${
                activeTab === id
                  ? "border-b-2 border-primary text-primary"
                  : "text-muted-foreground hover:text-primary"
              }`}
            >
              <Icon className="h-4 w-4" />
              {label}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto min-h-0">
          <div className="px-8 py-6">
            {activeTab === "profile" && (
              <UserProfileForm currentUser={currentUser} onSuccess={noop} />
            )}
            {activeTab === "security" && (
              <div className="space-y-6">
                <PasswordChangeForm onSuccess={noop} />
                <Separator />
                <MfaSettings />
              </div>
            )}
            {activeTab === "login-activity" && <LoginActivity />}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProfilePage;
