import { useCallback, useRef, useState } from "react";
import { toast } from "sonner";
import type { FailedDatasource } from "@/features/data-sources/components/FailedDatasourcesDialog";
import { useBackendClient } from "@/features/data-sources/hooks/useBackendClient";
import type {
  ApiDataSource,
  DataSource,
  DataSourceGroupFilter,
} from "@/features/data-sources/types";
import { useAuthToken } from "@/shared/auth/useAuthToken";

export type { ApiDataSource, DataSource };

export const useDataSources = () => {
  const [dataSources, setDataSources] = useState<DataSource[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isConnectingSource, setIsConnectingSource] = useState(false);
  const [isDeletingSource, setIsDeletingSource] = useState(false);
  const [isDeletingAllSources, setIsDeletingAllSources] = useState(false);
  const [refreshingGroupKey, setRefreshingGroupKey] = useState<string | null>(null);
  const [failedDatasources, setFailedDatasources] = useState<FailedDatasource[]>([]);

  // Destructure stable callbacks so useCallback deps don't churn on every render
  // (useBackendClient returns a new object literal each render, but the individual
  // callbacks inside are useCallback-wrapped and referentially stable).
  const {
    loadKgSources,
    refreshKgSources,
    refreshKgSourceGroup,
    cleanupKgSource,
    cleanupKgSources,
    connectDataSource: connectDataSourceApi,
    previewDataSource: previewDataSourceApi,
  } = useBackendClient();

  const loadInProgress = useRef(false);
  // Subscribed rather than read once, so that a load skipped before sign-in
  // produced a token gives callers a new identity to re-run on when it does.
  const authToken = useAuthToken();

  const loadDataSources = useCallback(
    async (isAfterConnection = false) => {
      if (loadInProgress.current) {
        return false;
      }

      if (!authToken) {
        console.warn("loadDataSources: auth token not yet available, skipping");
        return false;
      }

      try {
        loadInProgress.current = true;
        setIsLoading(true);
        const currentOntologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
        const response = await loadKgSources(currentOntologyScope);
        if (response.status === "success" && Array.isArray(response.data)) {
          const sources: ApiDataSource[] = response.data;
          const formattedSources: DataSource[] = sources.map((source) => ({
            id: source.datasource_id,
            datasourceType: source.datasource_type,
            tableName: source.table_name,
            bindAnnotation: source.bind_annotation,
            predicatePlaceholder: source.predicate_placeholder,
            fields: source.fields,
            rowCount: source.row_count,
            columnCount: source.column_count,
            author: source.author,
            timestamp: source.timestamp,
            databaseName: source.database_name,
            host: source.host,
            port: source.port,
            location: source.location,
            groupBy: source.group_by,
          }));
          setDataSources(formattedSources);

          if (isAfterConnection) {
            window.dispatchEvent(new CustomEvent("dataSourceConnected"));
          }

          return true;
        } else {
          toast.warning("No data sources found or invalid response format");
          return false;
        }
      } catch (error) {
        console.error("Error loading data sources:", error);
        toast.error("Failed to load data sources");
        return false;
      } finally {
        setIsLoading(false);
        loadInProgress.current = false;
      }
    },
    [authToken, loadKgSources],
  );

  const refreshDataSources = useCallback(async () => {
    if (loadInProgress.current) {
      return false;
    }

    try {
      loadInProgress.current = true;
      setIsLoading(true);
      const currentOntologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
      const response = await refreshKgSources(currentOntologyScope);
      if (response.status === "success" && Array.isArray(response.data)) {
        const sources: ApiDataSource[] = response.data;
        const formattedSources: DataSource[] = sources.map((source) => ({
          id: source.datasource_id,
          datasourceType: source.datasource_type,
          tableName: source.table_name,
          bindAnnotation: source.bind_annotation,
          predicatePlaceholder: source.predicate_placeholder,
          fields: source.fields,
          rowCount: source.row_count,
          columnCount: source.column_count,
          author: source.author,
          timestamp: source.timestamp,
          databaseName: source.database_name,
          host: source.host,
          port: source.port,
          location: source.location,
          groupBy: source.group_by,
        }));
        setDataSources(formattedSources);
        window.dispatchEvent(new CustomEvent("dataSourceConnected"));

        const failed: FailedDatasource[] = response.failed_datasources ?? [];
        if (failed.length > 0) {
          setFailedDatasources(failed);
        } else {
          toast.success("Data sources refreshed successfully");
        }

        return true;
      } else {
        toast.warning("Failed to refresh data sources");
        return false;
      }
    } catch (error) {
      console.error("Error refreshing data sources:", error);
      toast.error("Failed to refresh data sources");
      return false;
    } finally {
      setIsLoading(false);
      loadInProgress.current = false;
    }
  }, [refreshKgSources]);

  const deleteDataSource = useCallback(
    async (sourceId: string) => {
      try {
        setIsDeletingSource(true);
        const currentOntologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
        const success = await cleanupKgSource(currentOntologyScope, sourceId);
        if (success) {
          setDataSources((prevSources) => prevSources.filter((source) => source.id !== sourceId));
          window.dispatchEvent(new CustomEvent("dataSourceDeleted"));
        } else {
          toast.error("Failed to delete the data source");
        }
      } catch (error) {
        console.error("Error deleting data source:", error);
        toast.error("An error occurred while deleting the data source");
      } finally {
        setIsDeletingSource(false);
      }
    },
    [cleanupKgSource],
  );

  const deleteDataSources = useCallback(
    async (sourceIds: string[]) => {
      if (!sourceIds || sourceIds.length === 0) {
        toast.error("No data sources selected for deletion");
        return false;
      }
      try {
        setIsDeletingSource(true);
        const currentOntologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
        const success = await cleanupKgSources(sourceIds, currentOntologyScope);
        if (success) {
          setDataSources((prevSources) =>
            prevSources.filter((source) => !sourceIds.includes(source.id || "")),
          );
          window.dispatchEvent(new CustomEvent("dataSourceDeleted"));
          return success;
        } else {
          toast.error("Failed to delete the selected data sources");
          return false;
        }
      } catch (error) {
        console.error("Error deleting data sources:", error);
        toast.error("An error occurred while deleting the data sources");
        return false;
      } finally {
        setIsDeletingSource(false);
      }
    },
    [cleanupKgSources],
  );

  const deleteAllDataSources = useCallback(async () => {
    // Delete every current source by passing its explicit id. The backend has
    // no "delete all" mode (an empty id list is rejected), so we enumerate the
    // ids from state rather than sending an empty payload.
    const allIds = dataSources.map((source) => source.id || "").filter(Boolean);
    if (allIds.length === 0) {
      return;
    }
    try {
      setIsDeletingAllSources(true);
      const currentOntologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
      const response = await cleanupKgSources(allIds, currentOntologyScope);
      if (response && response.status === "success") {
        setDataSources([]);
        window.dispatchEvent(new CustomEvent("dataSourceDeleted"));
        toast.success("All data sources deleted successfully");
      } else {
        toast.error("Failed to delete all data sources");
      }
    } catch (error) {
      console.error("Error deleting all data sources:", error);
      toast.error("An error occurred while deleting all data sources");
    } finally {
      setIsDeletingAllSources(false);
    }
  }, [cleanupKgSources, dataSources]);

  const connectDataSource = useCallback(
    async (vadalogProgram: string, bindAnnotations?: string[], modelAnnotations?: string[]) => {
      try {
        setIsConnectingSource(true);
        const currentOntologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
        const databaseConfig = {
          vadalogProgram,
          bindAnnotations,
          modelAnnotations,
          scope: currentOntologyScope,
        };
        const response = await connectDataSourceApi(databaseConfig);
        if (response && response.status === "success") {
          await loadDataSources(true);
          return true;
        } else {
          toast.error("Failed to connect data source");
          return false;
        }
      } catch (error) {
        console.error("Error connecting data source:", error);
        toast.error("An error occurred while connecting the data source");
        return false;
      } finally {
        setIsConnectingSource(false);
      }
    },
    [connectDataSourceApi, loadDataSources],
  );

  const refreshDataSourceGroup = useCallback(
    async (groupFilter: DataSourceGroupFilter, groupKey: string) => {
      try {
        setRefreshingGroupKey(groupKey);
        const currentOntologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
        const response = await refreshKgSourceGroup(groupFilter, currentOntologyScope);
        if (response.status === "success" && Array.isArray(response.data)) {
          const sources: ApiDataSource[] = response.data;
          const formattedSources: DataSource[] = sources.map((source) => ({
            id: source.datasource_id,
            datasourceType: source.datasource_type,
            tableName: source.table_name,
            bindAnnotation: source.bind_annotation,
            predicatePlaceholder: source.predicate_placeholder,
            fields: source.fields,
            rowCount: source.row_count,
            columnCount: source.column_count,
            author: source.author,
            timestamp: source.timestamp,
            databaseName: source.database_name,
            host: source.host,
            port: source.port,
            location: source.location,
            groupBy: source.group_by,
          }));
          setDataSources(formattedSources);
          window.dispatchEvent(new CustomEvent("dataSourceConnected"));

          const failed: FailedDatasource[] = response.failed_datasources ?? [];
          if (failed.length > 0) {
            setFailedDatasources(failed);
          } else {
            toast.success("Connection refreshed successfully");
          }

          return true;
        } else {
          toast.warning("Failed to refresh connection");
          return false;
        }
      } catch (error) {
        console.error("Error refreshing data source group:", error);
        toast.error("Failed to refresh connection");
        return false;
      } finally {
        setRefreshingGroupKey(null);
      }
    },
    [refreshKgSourceGroup],
  );

  const getComputePayload = useCallback(async () => {
    const selectedCompute = localStorage.getItem("selectedCompute");
    if (selectedCompute === "databricks") {
      const { DatabricksService } = await import("@/features/compute/api/databricksService");
      const databricksConfig = DatabricksService.getDatabricksConfigForExecution();
      if (databricksConfig.databricks_config) {
        return { databricks_configs: databricksConfig.databricks_config };
      }
    } else if (selectedCompute === "pools") {
      const selectedMachineId = localStorage.getItem("selectedMachineId");
      if (selectedMachineId) {
        return { machine_configs: { id: selectedMachineId, machine_url: "" } };
      }
    }
    return undefined;
  }, []);

  const previewDataSource = useCallback(
    async (bindAnnotation: string, limit: number = 10) => {
      try {
        const currentOntologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
        const compute = await getComputePayload();

        const response = await previewDataSourceApi(
          bindAnnotation,
          currentOntologyScope,
          limit,
          compute,
        );

        if (response && response.status === "success" && response.data) {
          return response.data;
        }
        return null;
      } catch (error) {
        console.error("Error previewing data source:", error);
        return null;
      }
    },
    [previewDataSourceApi, getComputePayload],
  );

  const previewDataSourcePaginated = useCallback(
    async (
      bindAnnotation: string,
      page: number = 1,
      pageSize: number = 10,
      orderBy?: Array<{ position: number; direction: "asc" | "desc" }>,
      searchTerm?: string,
      columnFilters?: Array<{ position: number; value: string; operator?: string }>,
    ) => {
      try {
        const currentOntologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
        const compute = await getComputePayload();

        const response = await previewDataSourceApi(
          bindAnnotation,
          currentOntologyScope,
          10,
          compute,
          page,
          pageSize,
          orderBy,
          searchTerm,
          columnFilters,
        );

        if (response && response.status === "success" && response.data) {
          return response.data;
        }
        return null;
      } catch (error) {
        console.error("Error previewing data source (paginated):", error);
        return null;
      }
    },
    [previewDataSourceApi, getComputePayload],
  );

  const clearFailedDatasources = useCallback(() => setFailedDatasources([]), []);

  return {
    dataSources,
    isLoading,
    isConnectingSource,
    isDeletingSource,
    isDeletingAllSources,
    refreshingGroupKey,
    failedDatasources,
    clearFailedDatasources,
    loadDataSources,
    refreshDataSources,
    refreshDataSourceGroup,
    deleteDataSource,
    deleteDataSources,
    deleteAllDataSources,
    connectDataSource,
    previewDataSource,
    previewDataSourcePaginated,
  };
};
