import { useEffect } from "react";

import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/shared/components/ui/command";

import { useContextNotes } from "../../hooks/useContextNotes";
import type { ContextNote } from "../../types";
import type { VaultRef } from "../notesModel";
import { groupDocumentChunks, noteDisplayTitle, representativeChunkOf } from "../notesModel";
import { NoteBadges } from "./ShelfBadge";

interface QuickSwitcherProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  activeVault: VaultRef;
  onSelect: (note: ContextNote, vault: VaultRef) => void;
}

const GLOBAL_VAULT: VaultRef = { scope: "global", scopeId: null, name: "Global" };

/** Cmd+K fuzzy switcher over note titles (global + active vault). */
export function QuickSwitcher({ open, onOpenChange, activeVault, onSelect }: QuickSwitcherProps) {
  const { data: globalNotes = [] } = useContextNotes(
    { scope: "global", scopeId: null },
    { enabled: open },
  );
  const { data: vaultNotes = [] } = useContextNotes(
    { scope: activeVault.scope, scopeId: activeVault.scopeId },
    { enabled: open && activeVault.scope === "ontology" },
  );

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key === "k") {
        event.preventDefault();
        onOpenChange(!open);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [open, onOpenChange]);

  const buildGroup = (vault: VaultRef, notes: ContextNote[]) => {
    // Documents appear once, by filename; selecting one opens the document.
    const { documents, standalone } = groupDocumentChunks(notes);
    return [
      ...standalone.map((note) => ({ note, vault, title: noteDisplayTitle(note) })),
      ...documents.map((group) => ({
        note: representativeChunkOf(group),
        vault,
        title: group.filename,
      })),
    ];
  };

  const groups = [
    { heading: "Global", entries: buildGroup(GLOBAL_VAULT, globalNotes) },
    ...(activeVault.scope === "ontology"
      ? [{ heading: activeVault.name, entries: buildGroup(activeVault, vaultNotes) }]
      : []),
  ];

  const handleSelect = (note: ContextNote, vault: VaultRef) => {
    onOpenChange(false);
    onSelect(note, vault);
  };

  return (
    <CommandDialog open={open} onOpenChange={onOpenChange} title="Jump to a note">
      <CommandInput placeholder="Jump to a note…" />
      <CommandList>
        <CommandEmpty>No notes found.</CommandEmpty>
        {groups.map((group) => (
          <CommandGroup key={group.heading} heading={group.heading}>
            {group.entries.map((entry) => (
              <CommandItem
                key={entry.note.id}
                value={`${entry.title} ${entry.note.id}`}
                onSelect={() => handleSelect(entry.note, entry.vault)}
              >
                <span className="min-w-0 flex-1 truncate">{entry.title}</span>
                <NoteBadges note={entry.note} />
              </CommandItem>
            ))}
          </CommandGroup>
        ))}
      </CommandList>
    </CommandDialog>
  );
}
