import { Handle, type NodeProps, Position } from "@xyflow/react";
import { NotebookText } from "lucide-react";
import type React from "react";
import { memo } from "react";

import type { ContextShelf } from "../types";
import {
  CONTEXT_NOTE_CARD_WIDTH,
  type ContextConceptNodeData,
  type ContextNoteNodeData,
  conceptCardWidth,
} from "./flowGraph";

const invisibleHandle: React.CSSProperties = {
  width: 1,
  height: 1,
  background: "transparent",
  border: "none",
  opacity: 0,
};

/** Invisible connection points on both sides — the layout picks the pair
 *  facing the other endpoint so arrows always take the short way. */
function SideHandles() {
  return (
    <>
      <Handle
        id="target-left"
        type="target"
        position={Position.Left}
        style={{ ...invisibleHandle, left: 0, top: "50%" }}
      />
      <Handle
        id="target-right"
        type="target"
        position={Position.Right}
        style={{ ...invisibleHandle, right: 0, top: "50%" }}
      />
      <Handle
        id="source-left"
        type="source"
        position={Position.Left}
        style={{ ...invisibleHandle, left: 0, top: "50%" }}
      />
      <Handle
        id="source-right"
        type="source"
        position={Position.Right}
        style={{ ...invisibleHandle, right: 0, top: "50%" }}
      />
    </>
  );
}

const SHELF_DOTS: Record<ContextShelf, string> = {
  rules: "bg-amber-500 dark:bg-amber-400",
  knowledge: "bg-blue-500 dark:bg-blue-400",
  documents: "bg-emerald-500 dark:bg-emerald-400",
};

const SHELF_LABELS: Record<ContextShelf, string> = {
  rules: "Rule",
  knowledge: "Note",
  documents: "Document",
};

/** The concept card — same chrome as the lineage concept card, with a
 *  violet accent marking it as the context anchor. */
function ContextConceptNodeInner({ data }: NodeProps) {
  const { label } = data as unknown as ContextConceptNodeData;
  return (
    <div
      className="bg-card rounded-lg shadow-md border border-border relative flex items-center gap-2.5 px-4"
      style={{
        width: conceptCardWidth(label),
        height: 56,
        borderLeftWidth: 4,
        borderLeftColor: "#8b5cf6",
      }}
    >
      <SideHandles />
      <span className="h-2.5 w-2.5 shrink-0 rounded-full bg-violet-500 dark:bg-violet-400" />
      <span className="truncate text-lg font-normal text-foreground" title={label}>
        {label}
      </span>
    </div>
  );
}

/** An attached-note card: shelf-typed header + text snippet, like the
 *  ontology-snippet cards in the reference design. */
function ContextNoteNodeInner({ data }: NodeProps) {
  const { title, snippet, shelf } = data as unknown as ContextNoteNodeData;
  return (
    <div
      className="bg-card rounded-lg shadow-md border border-border relative cursor-pointer px-3.5 py-2.5 transition-colors hover:border-violet-400 dark:hover:border-violet-500"
      style={{ width: CONTEXT_NOTE_CARD_WIDTH, minHeight: 104 }}
    >
      <SideHandles />
      <div className="flex items-center gap-1.5">
        <span className={`h-2 w-2 shrink-0 rounded-full ${SHELF_DOTS[shelf]}`} />
        <NotebookText className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
        <span className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
          {SHELF_LABELS[shelf]}
        </span>
      </div>
      <p className="mt-1 truncate text-sm font-medium text-foreground" title={title}>
        {title}
      </p>
      <p className="mt-0.5 line-clamp-2 text-xs leading-snug text-muted-foreground">{snippet}</p>
    </div>
  );
}

export const ContextConceptNode = memo(ContextConceptNodeInner);
export const ContextNoteNode = memo(ContextNoteNodeInner);
