import { useCallback, useState } from "react";
import { useRequireCompute } from "@/features/compute/hooks/useRequireCompute";
import { ConceptClient, type ConceptStatusEvent, type FetchResult } from "../api/ConceptClient";
import type { DashboardTableHandlers } from "../components/outputs/table/tableOutput.types";
import { useTableActions } from "./useTableActions";

const client = new ConceptClient();

type ParamValues = Record<string, string | number | boolean>;

interface UseCanvasRunParams {
  ontologyId: string;
  allWidgetConcepts: string[];
  paramValues: ParamValues;
}

interface UseCanvasRunReturn {
  isRunning: boolean;
  runStatus: string;
  conceptData: Record<string, FetchResult | null>;
  loadingConcepts: Record<string, boolean>;
  errorConcepts: Record<string, string>;
  knownColumnsMap: Record<string, string[]>;
  handleRun: () => Promise<void>;
  resetRunState: () => void;
  tableHandlers: DashboardTableHandlers;
}

export function useCanvasRun({
  ontologyId,
  allWidgetConcepts,
  paramValues,
}: UseCanvasRunParams): UseCanvasRunReturn {
  const [isRunning, setIsRunning] = useState(false);
  const [runStatus, setRunStatus] = useState("");
  const [conceptData, setConceptData] = useState<Record<string, FetchResult | null>>({});
  const [loadingConcepts, setLoadingConcepts] = useState<Record<string, boolean>>({});
  const [errorConcepts, setErrorConcepts] = useState<Record<string, string>>({});
  const [knownColumnsMap, setKnownColumnsMap] = useState<Record<string, string[]>>({});

  const { ensureCompute } = useRequireCompute();

  const resetRunState = useCallback(() => {
    setConceptData({});
    setLoadingConcepts({});
    setErrorConcepts({});
    setKnownColumnsMap({});
    setRunStatus("");
  }, []);

  const handleRun = useCallback(async () => {
    if (!ontologyId) return;
    // No compute running → prompt the user to start a machine instead of failing silently.
    if (!ensureCompute()) return;

    setIsRunning(true);
    setConceptData({});
    setErrorConcepts({});

    const loadingMap: Record<string, boolean> = {};
    allWidgetConcepts.forEach((n) => {
      loadingMap[n] = true;
    });
    setLoadingConcepts(loadingMap);

    try {
      await Promise.all(
        allWidgetConcepts.map(async (conceptName) => {
          try {
            const evalResults = await client.runConceptWithParams(
              ontologyId,
              conceptName,
              paramValues,
              "user",
              true,
              (e: ConceptStatusEvent) => {
                if (e.concept && e.status) setRunStatus(`${e.concept}: ${e.status}`);
              },
            );
            let data: FetchResult;
            try {
              data = await client.fetchConceptData(ontologyId, conceptName, "user");
            } catch {
              const fromStream = client.extractFromEvalResults(evalResults, conceptName);
              if (!fromStream) throw new Error("No data returned");
              data = fromStream;
            }
            setConceptData((prev) => ({ ...prev, [conceptName]: data }));
            if (data.columnNames?.length) {
              setKnownColumnsMap((prev) => ({ ...prev, [conceptName]: data.columnNames }));
            }
          } catch (err: unknown) {
            const message = err instanceof Error ? err.message : "Failed to load data";
            setErrorConcepts((prev) => ({ ...prev, [conceptName]: message }));
          } finally {
            setLoadingConcepts((prev) => ({ ...prev, [conceptName]: false }));
          }
        }),
      );
    } finally {
      setIsRunning(false);
      setRunStatus("");
    }
  }, [ontologyId, allWidgetConcepts, paramValues, ensureCompute]);

  const tableHandlers = useTableActions({
    client,
    ontologyId,
    conceptData,
    setConceptData,
    setLoadingConcepts,
    setErrorConcepts,
  });

  return {
    isRunning,
    runStatus,
    conceptData,
    loadingConcepts,
    errorConcepts,
    knownColumnsMap,
    handleRun,
    resetRunState,
    tableHandlers,
  };
}
