import { ShieldCheck } from "lucide-react";
import { type FormEvent, useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { useMfa } from "@/features/auth/hooks/useMfa";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/shared/components/ui/card";
import { Input } from "@/shared/components/ui/input";
import { supabase } from "@/shared/integrations/supabase/client";

interface MfaChallengeLocationState {
  from?: { pathname: string };
}

const TOTP_CODE_LENGTH = 6;

const MfaChallengePage = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, signOut } = useAuth();
  const { verifiedFactor, isLoading: isLoadingFactors, consumeRecoveryCode } = useMfa();

  const [mode, setMode] = useState<"totp" | "recovery">("totp");
  const [code, setCode] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const redirectTo = useMemo(() => {
    const state = location.state;
    if (state && typeof state === "object" && "from" in state) {
      const locationState = state as MfaChallengeLocationState;
      return locationState.from?.pathname ?? "/";
    }
    return "/";
  }, [location.state]);

  useEffect(() => {
    if (!user) {
      navigate("/login", { replace: true });
    }
  }, [user, navigate]);

  useEffect(() => {
    let isCancelled = false;
    const checkAal = async () => {
      const { data } = await supabase.auth.mfa.getAuthenticatorAssuranceLevel();
      if (isCancelled) return;
      if (data?.currentLevel === "aal2") {
        navigate(redirectTo, { replace: true });
      }
    };
    checkAal();
    return () => {
      isCancelled = true;
    };
  }, [navigate, redirectTo]);

  const handleTotpSubmit = async (event: FormEvent) => {
    event.preventDefault();
    if (!verifiedFactor) {
      setErrorMessage("No MFA factor is enrolled for this account.");
      return;
    }
    if (code.length !== TOTP_CODE_LENGTH) {
      setErrorMessage(`Please enter the ${TOTP_CODE_LENGTH}-digit code from your authenticator.`);
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);
    try {
      const { data: challenge, error: challengeError } = await supabase.auth.mfa.challenge({
        factorId: verifiedFactor.id,
      });
      if (challengeError) throw challengeError;
      if (!challenge) throw new Error("Failed to start MFA challenge");

      const { error: verifyError } = await supabase.auth.mfa.verify({
        factorId: verifiedFactor.id,
        challengeId: challenge.id,
        code,
      });
      if (verifyError) throw verifyError;

      navigate(redirectTo, { replace: true });
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : "Invalid code. Please try again.";
      setErrorMessage(message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRecoverySubmit = async (event: FormEvent) => {
    event.preventDefault();
    if (code.trim().length === 0) {
      setErrorMessage("Please enter a recovery code.");
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);
    try {
      const consumed = await consumeRecoveryCode(code);
      if (!consumed) {
        setErrorMessage("This recovery code is invalid or has already been used.");
        return;
      }

      toast.success(
        "Recovery code accepted. Please reconfigure MFA from your profile's Security tab.",
      );
      navigate(redirectTo, { replace: true });
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : "Failed to validate recovery code.";
      setErrorMessage(message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleToggleMode = () => {
    setErrorMessage(null);
    setCode("");
    setMode((current) => (current === "totp" ? "recovery" : "totp"));
  };

  const handleCancel = async () => {
    await signOut();
    navigate("/login", { replace: true });
  };

  if (isLoadingFactors) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <p className="text-muted-foreground">Loading…</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="space-y-3">
          <div className="flex justify-center">
            <div className="p-3 rounded-full bg-primary/10">
              <ShieldCheck className="h-8 w-8 text-primary" />
            </div>
          </div>
          <CardTitle className="text-center">Two-factor authentication</CardTitle>
          <p className="text-sm text-muted-foreground text-center">
            {mode === "totp"
              ? "Enter the 6-digit code from your authenticator app."
              : "Enter one of your one-time recovery codes."}
          </p>
        </CardHeader>

        <CardContent className="space-y-4">
          <form
            onSubmit={mode === "totp" ? handleTotpSubmit : handleRecoverySubmit}
            className="space-y-4"
          >
            <Input
              autoFocus
              inputMode={mode === "totp" ? "numeric" : "text"}
              autoComplete={mode === "totp" ? "one-time-code" : "off"}
              placeholder={mode === "totp" ? "123456" : "XXXX-XXXX"}
              value={code}
              onChange={(event) => setCode(event.target.value)}
              disabled={isSubmitting}
              className="text-center tracking-widest text-lg"
            />

            {errorMessage && <p className="text-sm text-destructive text-center">{errorMessage}</p>}

            <Button type="submit" className="w-full" disabled={isSubmitting}>
              {isSubmitting ? "Verifying…" : "Verify"}
            </Button>
          </form>

          <div className="flex flex-col gap-2 text-center">
            <button
              type="button"
              onClick={handleToggleMode}
              className="text-sm text-primary hover:underline"
              disabled={isSubmitting}
            >
              {mode === "totp"
                ? "Use a recovery code instead"
                : "Use your authenticator app instead"}
            </button>
            <button
              type="button"
              onClick={handleCancel}
              className="text-xs text-muted-foreground hover:underline"
              disabled={isSubmitting}
            >
              Sign out
            </button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default MfaChallengePage;
