import { Bell } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { acceptShare } from "@/features/ontologies/sharing/api";
import { generateEditorUrl } from "@/shared/utils/navigationUtils";
import { useNotifications } from "../hooks/useNotifications";
import type { NotificationItem } from "../types";
import { AcceptInvitationDialog } from "./AcceptInvitationDialog";
import { NotificationPanel } from "./NotificationPanel";

// Header notification bell: red dot + count of unread items, a floating panel,
// and click-through routing by type. Opening the panel acknowledges everything
// (clears the count); items stay as greyed history until resolved (ADR 0003).
export function NotificationBell() {
  const [open, setOpen] = useState(false);
  const [inviteItem, setInviteItem] = useState<NotificationItem | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const { user, session } = useAuth();
  const supabaseToken = session?.access_token ?? null;
  const canSeeNotifications = usePermissionsStore((state) => state.canSee("can_see_notifications"));
  const { items, unreadCount, isLoading, markAllRead, markRead } = useNotifications();

  useEffect(() => {
    if (!open) return;
    const onMouseDown = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setOpen(false);
      }
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onMouseDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onMouseDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  const handleToggle = () => {
    const next = !open;
    setOpen(next);
    if (next && unreadCount > 0) markAllRead();
  };

  const handleItemClick = async (item: NotificationItem) => {
    if (!item.read) markRead({ type: item.type, entityId: item.entity_id });
    setOpen(false);

    if (item.type === "project_share") {
      const ontologyId = item.action.ontology_id;
      if (!ontologyId) {
        navigate("/ontologies");
        return;
      }
      // The notification is for a *pending* share, so claim it first (vaults the
      // scoped token) — otherwise the editor can't route to the owner's ontology.
      // On failure, fall back to the shared-ontologies list.
      try {
        await acceptShare(item.entity_id, supabaseToken);
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Couldn't open the shared ontology");
        navigate("/ontologies");
        return;
      }
      navigate(generateEditorUrl(user, ontologyId), { state: { activeTab: "lineage" } });
      return;
    }

    // Team invite: confirm + accept in place. The user may lack can_see_teams,
    // so we must NOT route them to /teams.
    setInviteItem(item);
  };

  // Gated behind can_see_notifications. Hooks above always run (React rules);
  // the render is what's suppressed for users without the permission.
  if (!canSeeNotifications) return null;

  return (
    <div ref={containerRef} className="relative">
      <button
        type="button"
        aria-label="Notifications"
        onClick={handleToggle}
        className="relative flex h-9 w-9 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
      >
        <Bell className="h-4 w-4" />
        {unreadCount > 0 && (
          <span className="absolute -right-0.5 -top-0.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-destructive px-1 text-[10px] font-semibold leading-none text-destructive-foreground">
            {unreadCount > 9 ? "9+" : unreadCount}
          </span>
        )}
      </button>

      {open && (
        <div className="absolute right-0 top-full z-30 mt-1 max-h-[70vh] w-[22rem] overflow-y-auto rounded-md border border-border bg-popover text-popover-foreground shadow-md">
          <div className="border-b border-border px-3 py-2 text-sm font-semibold">
            Notifications
          </div>
          <NotificationPanel items={items} isLoading={isLoading} onItemClick={handleItemClick} />
        </div>
      )}

      <AcceptInvitationDialog item={inviteItem} onClose={() => setInviteItem(null)} />
    </div>
  );
}
