import { useCallback, useMemo } from "react";
import { DataClient } from "@/features/data-sources/api/DataClient";
import type { DataSourceGroupFilter } from "@/features/data-sources/types";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";

/**
 * Hook for accessing client instances to make backend API calls
 */
export function useBackendClient() {
  // Create singleton instances of the clients using useMemo
  const dataClient = useMemo(() => new DataClient(), []);

  // Get current project ID and scope
  const ontologyScope = useOntologyScope();

  // Expose the methods we need from the clients
  return {
    // Load data sources for workspace (no longer project-specific)
    loadKgSources: useCallback(
      async (providedOntologyScope?: string) => {
        try {
          const finalOntologyScope = providedOntologyScope || ontologyScope;

          return await dataClient.loadDataSources(finalOntologyScope);
        } catch (error) {
          console.error("Error loading data sources:", error);
          throw error;
        }
      },
      [dataClient, ontologyScope],
    ),

    // Delete data source from workspace (no longer project-specific)
    cleanupKgSource: useCallback(
      async (providedOntologyScope?: string, sourceId?: string) => {
        try {
          const finalOntologyScope = providedOntologyScope || ontologyScope;

          if (!sourceId) {
            throw new Error("No source ID provided");
          }

          const response = await dataClient.deleteDataSources([sourceId], finalOntologyScope);
          return response && response.status === "success";
        } catch (error) {
          console.error("Error cleaning up data source:", error);
          return false;
        }
      },
      [dataClient, ontologyScope],
    ),

    // Bulk cleanup for multiple data sources from workspace (no longer project-specific)
    cleanupKgSources: useCallback(
      async (sourceIds?: string[], ontologyScope?: string) => {
        try {
          return await dataClient.deleteDataSources(sourceIds, ontologyScope);
        } catch (error) {
          throw error;
        }
      },
      [dataClient],
    ),

    // List sheet names for an Excel workbook
    listSheets: useCallback(
      async (databaseConfig: Record<string, unknown>) => {
        try {
          return await dataClient.listSheets(databaseConfig);
        } catch (error) {
          console.error("Error listing sheets:", error);
          throw error;
        }
      },
      [dataClient],
    ),

    // Connect data source to workspace (no longer project-specific)
    connectDataSource: useCallback(
      async (databaseConfig: any) => {
        try {
          return await dataClient.connectDataSource(databaseConfig);
        } catch (error) {
          console.error("Error connecting data source:", error);
          throw error;
        }
      },
      [dataClient],
    ),

    // Preview data source records
    previewDataSource: useCallback(
      async (
        bindAnnotation: string,
        providedOntologyScope?: string,
        limit: number = 10,
        compute?: any,
        page?: number,
        pageSize?: number,
        orderBy?: Array<{ position: number; direction: "asc" | "desc" }>,
        searchTerm?: string,
        columnFilters?: Array<{ position: number; value: string; operator?: string }>,
      ) => {
        try {
          const finalOntologyScope = providedOntologyScope || ontologyScope;
          return await dataClient.previewDataSource(
            bindAnnotation,
            finalOntologyScope,
            limit,
            compute,
            page,
            pageSize,
            orderBy,
            searchTerm,
            columnFilters,
          );
        } catch (error) {
          console.error("Error previewing data source:", error);
          throw error;
        }
      },
      [dataClient, ontologyScope],
    ),

    // Refresh data sources (re-connect and reconcile)
    refreshKgSources: useCallback(
      async (providedOntologyScope?: string) => {
        try {
          const finalOntologyScope = providedOntologyScope || ontologyScope;
          return await dataClient.refreshDataSources(finalOntologyScope);
        } catch (error) {
          console.error("Error refreshing data sources:", error);
          throw error;
        }
      },
      [dataClient, ontologyScope],
    ),

    // Refresh a specific database connection group
    refreshKgSourceGroup: useCallback(
      async (groupFilter: DataSourceGroupFilter, providedOntologyScope?: string) => {
        try {
          const finalOntologyScope = providedOntologyScope || ontologyScope;
          return await dataClient.refreshDataSourceGroup(groupFilter, finalOntologyScope);
        } catch (error) {
          console.error("Error refreshing data source group:", error);
          throw error;
        }
      },
      [dataClient, ontologyScope],
    ),

    // Upload file to server's disk storage
    uploadFile: useCallback(
      async (file: File, path: string = "", onProgress?: (progress: number) => void) => {
        try {
          return await dataClient.uploadFile(file, path, onProgress);
        } catch (error) {
          console.error("Error uploading file:", error);
          throw error;
        }
      },
      [dataClient],
    ),
  };
}
