import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { DataClient } from "@/features/data-sources/api/DataClient";
import { DashboardClient } from "@/features/dynamic-dashboard/api/DashboardClient";
import { useOntologies } from "@/features/ontologies/hooks/useOntologies";
import { useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";
import { GETTING_STARTED_STEPS } from "../gettingStarted.steps";
import type { GettingStartedState, ResolvedStep, StepId } from "../gettingStarted.types";
import { gettingStartedStorage } from "../gettingStartedStorage";

const SIGNAL_STALE_MS = 60_000;
const DATA_SOURCES_QUERY_KEY = "getting-started-data-sources";

// The Getting Started feature went live at this moment. Accounts created before
// it are existing users who already onboarded the manual way — the checklist
// would otherwise sit stuck at a partial count for them (the `assistant` signal
// is session-scoped and the `mcp` step is manual, so it never auto-dismisses).
// Suppress it entirely for them; only genuinely new signups see it.
const FEATURE_LAUNCH_MS = Date.parse("2026-06-15T12:32:25Z");

function isExistingUser(createdAt: string | undefined): boolean {
  if (!createdAt) return false; // mock/dev users have no created_at — treat as new
  const created = Date.parse(createdAt);
  return !Number.isNaN(created) && created < FEATURE_LAUNCH_MS;
}

function resolveSteps(signals: Record<StepId, boolean>, manualDone: StepId[]): ResolvedStep[] {
  return GETTING_STARTED_STEPS.map((step) => {
    const completed = step.manual ? manualDone.includes(step.id) : (signals[step.id] ?? false);
    return { ...step, completed };
  });
}

interface UseGettingStartedReturn {
  steps: ResolvedStep[];
  completedCount: number;
  total: number;
  isVisible: boolean;
  /**
   * True when the checklist should auto-open: signals have settled, nothing is
   * done yet, and it has never auto-opened before (persisted, so it survives
   * sidebar remounts on navigation).
   */
  shouldAutoOpen: boolean;
  markAutoOpened: () => void;
  markDone: (stepId: StepId) => void;
  dismiss: () => void;
}

export function useGettingStarted(): UseGettingStartedReturn {
  const { user, session } = useAuth();
  const userId = user?.id ?? "";
  const ontologyScope = useOntologyScope();
  const queryClient = useQueryClient();

  // The checklist only makes sense for users who can reach every step it covers.
  // Power users (JupyterLab access) are excluded entirely. When ineligible we never
  // render and never fetch — the onboarding is treated as skipped.
  const canSeeOntologies = usePermissionsStore((s) => s.canSee("can_see_projects"));
  const canSeeDatasources = usePermissionsStore((s) => s.canSee("can_see_datasources"));
  const canSeeDashboards = usePermissionsStore((s) => s.canSee("can_see_dynamic_dashboards"));
  const canSeeAiAgent = usePermissionsStore((s) => s.canSee("can_see_ai_agent"));
  const canSeeJupyterLab = usePermissionsStore((s) => s.canSee("can_see_jupyter_lab"));
  const isEligible =
    canSeeOntologies &&
    canSeeDatasources &&
    canSeeDashboards &&
    canSeeAiAgent &&
    !canSeeJupyterLab &&
    !isExistingUser(session?.user.created_at);

  const [state, setState] = useState<GettingStartedState>(() => gettingStartedStorage.read(userId));

  const enabled = isEligible && !!userId && !state.dismissed;

  const { projects, isLoading: ontologiesLoading } = useOntologies(["user", "organization"]);
  const hasUserMessage = useCodeAssistantStore((s) => s.messages.some((m) => m.role === "user"));

  const { data: dashboards, isLoading: dashboardsLoading } = useQuery({
    queryKey: ["all-dashboards"],
    queryFn: () => new DashboardClient().listAllDashboards(),
    enabled,
    staleTime: SIGNAL_STALE_MS,
  });

  const { data: dataSources, isLoading: dataSourcesLoading } = useQuery({
    queryKey: [DATA_SOURCES_QUERY_KEY, ontologyScope],
    queryFn: async () => {
      const response = await new DataClient().loadDataSources(ontologyScope);
      return response.status === "success" && Array.isArray(response.data) ? response.data : [];
    },
    enabled,
    staleTime: SIGNAL_STALE_MS,
  });

  const isReady = enabled && !ontologiesLoading && !dashboardsLoading && !dataSourcesLoading;

  // The widget lives in the always-mounted sidebar, so it never refetches on
  // navigation. Connecting a data source dispatches "dataSourceConnected"
  // (see useDataSources / DataTab) — refresh the count when that fires.
  useEffect(() => {
    if (!enabled) return;
    const handleDataSourceConnected = () => {
      queryClient.invalidateQueries({ queryKey: [DATA_SOURCES_QUERY_KEY] });
    };
    window.addEventListener("dataSourceConnected", handleDataSourceConnected);
    return () => window.removeEventListener("dataSourceConnected", handleDataSourceConnected);
  }, [enabled, queryClient]);

  const steps = useMemo(() => {
    const signals: Record<StepId, boolean> = {
      project: projects.length > 0,
      data: (dataSources?.length ?? 0) > 0,
      dashboard: (dashboards?.length ?? 0) > 0,
      assistant: hasUserMessage,
      mcp: false,
    };
    return resolveSteps(signals, state.manualDone);
  }, [projects.length, dataSources, dashboards, hasUserMessage, state.manualDone]);

  const completedCount = useMemo(() => steps.filter((s) => s.completed).length, [steps]);
  const total = steps.length;

  // Auto-dismiss permanently once every step is complete.
  useEffect(() => {
    if (!isEligible || !userId || state.dismissed) return;
    if (completedCount < total) return;
    gettingStartedStorage.dismiss(userId);
    setState((prev) => ({ ...prev, dismissed: true }));
  }, [isEligible, userId, state.dismissed, completedCount, total]);

  const shouldAutoOpen = isReady && completedCount === 0 && !state.autoOpened;

  const markAutoOpened = useCallback(() => {
    if (!userId) return;
    gettingStartedStorage.markAutoOpened(userId);
    setState((prev) => (prev.autoOpened ? prev : { ...prev, autoOpened: true }));
  }, [userId]);

  const dismiss = useCallback(() => {
    if (!userId) return;
    gettingStartedStorage.dismiss(userId);
    setState((prev) => ({ ...prev, dismissed: true }));
  }, [userId]);

  const markDone = useCallback(
    (stepId: StepId) => {
      if (!userId) return;
      gettingStartedStorage.markDone(userId, stepId);
      setState((prev) =>
        prev.manualDone.includes(stepId)
          ? prev
          : { ...prev, manualDone: [...prev.manualDone, stepId] },
      );
    },
    [userId],
  );

  return {
    steps,
    completedCount,
    total,
    isVisible: isEligible && !!userId && !state.dismissed,
    shouldAutoOpen,
    markAutoOpened,
    markDone,
    dismiss,
  };
}
