import { Database, Plus } from "lucide-react";
import { useCallback, useState } from "react";
import SchemaInferenceForm from "@/features/concept-editor/components/code-editor/editor/SchemaInferenceForm";
import { DemoDataPicker } from "@/features/data-sources/components/DemoDataPicker";
import { buildDemoPrefill, type DemoPrefill } from "@/features/data-sources/demoPrefill";
import type { DemoSourcePreset } from "@/features/data-sources/types";
import { Button } from "@/shared/components/ui/button";
import type { WizardControls } from "@/shared/components/wizard/useWizardState";
import { WizardStep } from "@/shared/components/wizard/WizardStep";

interface DataConnectStepProps {
  controls: WizardControls;
}

interface SchemaFormState {
  open: boolean;
  prefill: DemoPrefill | null;
}

const CLOSED_FORM: SchemaFormState = { open: false, prefill: null };

export function DataConnectStep({ controls }: DataConnectStepProps) {
  const [schemaForm, setSchemaForm] = useState<SchemaFormState>(CLOSED_FORM);
  const [connectedCount, setConnectedCount] = useState(0);

  const handleAddManual = () => setSchemaForm({ open: true, prefill: null });

  const handlePickPreset = useCallback((preset: DemoSourcePreset) => {
    setSchemaForm({ open: true, prefill: buildDemoPrefill(preset.database) });
  }, []);

  const handleClose = useCallback(() => setSchemaForm(CLOSED_FORM), []);

  const handleInferenceComplete = useCallback(() => {
    setConnectedCount((n) => n + 1);
    setSchemaForm(CLOSED_FORM);
  }, []);

  const formKey = schemaForm.prefill?.initialValues.databaseType ?? "manual";

  return (
    <WizardStep
      controls={controls}
      title="Connect your data"
      description="Add the data sources you want the assistant to reason over. You can skip this and connect later — auto-seed picks up new connections in the background."
    >
      <div className="space-y-4">
        <Button type="button" variant="default" onClick={handleAddManual}>
          <Plus className="mr-2 h-4 w-4" />
          Add data source
        </Button>

        <div className="flex items-center gap-3">
          <div className="h-px flex-1 bg-border" />
          <span className="text-xs uppercase tracking-wide text-muted-foreground">
            or use our px-datasources for now
          </span>
          <div className="h-px flex-1 bg-border" />
        </div>

        <p className="text-xs text-muted-foreground">
          Pick one to open the connection form pre-filled with its details — review them and connect
          to see what connecting a datasource looks like.
        </p>

        <DemoDataPicker onPickPreset={handlePickPreset} />

        <div className="rounded-md border border-border bg-card p-4 text-sm">
          {connectedCount === 0 ? (
            <div className="space-y-1">
              <div className="flex items-center gap-2 text-foreground">
                <Database className="h-4 w-4 text-muted-foreground" />
                <span>No data sources connected in this session yet.</span>
              </div>
              <p className="text-xs text-muted-foreground">
                Auto-seed runs asynchronously after each connect — the resulting observation notes
                show up later on the Context page.
              </p>
            </div>
          ) : (
            <div className="space-y-1">
              <p className="text-foreground">
                <span className="font-medium">{connectedCount}</span> data source
                {connectedCount === 1 ? "" : "s"} connected this session. Add more, or continue.
              </p>
              <p className="text-xs text-muted-foreground">
                Observation notes are generated in the background; they'll appear on the Context
                page when ready.
              </p>
            </div>
          )}
        </div>
      </div>

      {schemaForm.open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="max-h-[95vh] w-full max-w-2xl overflow-y-auto rounded">
            <SchemaInferenceForm
              key={formKey}
              onClose={handleClose}
              onInferenceComplete={handleInferenceComplete}
              initialValues={schemaForm.prefill?.initialValues}
              initialStorageType={schemaForm.prefill?.initialStorageType}
            />
          </div>
        </div>
      )}
    </WizardStep>
  );
}
