import { Plus, X } from "lucide-react";
import type { LlmConceptConfig, LlmOutputColumn } from "@/features/concept-editor/types";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { LlmModelOverrides } from "./LlmModelOverrides";

const COLUMN_TYPES = ["string", "int", "double", "boolean"] as const;

interface LlmCellConfigPanelProps {
  cellId: string;
  config: LlmConceptConfig;
  disabled?: boolean;
  /** Concept name, used to suggest a name for a connection created from here. */
  conceptName?: string;
  onChange: (patch: Partial<LlmConceptConfig>) => void;
}

/**
 * Declared output columns + model overrides for an llm cell. With no declared
 * columns the concept outputs a single `response` string column; declaring
 * columns holds the model to a JSON contract with exactly those fields.
 */
export function LlmCellConfigPanel({
  cellId,
  config,
  disabled,
  conceptName,
  onChange,
}: LlmCellConfigPanelProps) {
  const columns = config.output_columns ?? [];

  const setColumns = (next: LlmOutputColumn[]) => {
    onChange({ output_columns: next.length > 0 ? next : undefined });
  };

  const handleAddColumn = () => {
    setColumns([...columns, { name: "", type: "string" }]);
  };

  const handleRemoveColumn = (index: number) => {
    setColumns(columns.filter((_, i) => i !== index));
  };

  const handleColumnChange = (index: number, patch: Partial<LlmOutputColumn>) => {
    setColumns(columns.map((col, i) => (i === index ? { ...col, ...patch } : col)));
  };

  return (
    <div className="flex flex-col gap-3 px-3 py-2">
      <div className="flex flex-col gap-1.5">
        <div className="flex items-center gap-2">
          <span className="text-xs font-medium text-foreground">Output columns</span>
          <span className="text-[11px] text-muted-foreground">
            {columns.length === 0
              ? "None declared — the output is a single `response` column"
              : "The model must return a JSON array with exactly these fields"}
          </span>
        </div>
        {columns.map((col, index) => (
          <div
            // biome-ignore lint/suspicious/noArrayIndexKey: columns are positional and editable in place
            key={`${cellId}-col-${index}`}
            className="flex items-center gap-2"
          >
            <Input
              value={col.name}
              onChange={(e) => handleColumnChange(index, { name: e.target.value })}
              placeholder="column_name"
              className="h-7 w-48 text-xs bg-muted/80"
              disabled={disabled}
            />
            <Select
              value={col.type}
              onValueChange={(value) => handleColumnChange(index, { type: value })}
              disabled={disabled}
            >
              <SelectTrigger className="h-7 w-[100px] text-xs border-border">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {COLUMN_TYPES.map((t) => (
                  <SelectItem key={t} value={t} className="text-xs">
                    {t}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              onClick={() => handleRemoveColumn(index)}
              disabled={disabled}
              aria-label="Remove column"
            >
              <X className="h-3.5 w-3.5" />
            </Button>
          </div>
        ))}
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="h-7 w-fit gap-1 text-xs"
          onClick={handleAddColumn}
          disabled={disabled}
        >
          <Plus className="h-3.5 w-3.5" />
          Add column
        </Button>
      </div>

      <LlmModelOverrides
        cellId={cellId}
        config={config}
        disabled={disabled}
        conceptName={conceptName}
        onChange={onChange}
      />
    </div>
  );
}
