// Simple Icons wrapper component
const _SimpleIcon: React.FC<{
  iconData: any;
  size: number;
  className?: string;
}> = ({ iconData, size, className }) => {
  if (!iconData) return null;

  return (
    <svg
      role="img"
      viewBox="0 0 24 24"
      width={size}
      height={size}
      className={className}
      fill={`#${iconData.hex}`}
      xmlns="http://www.w3.org/2000/svg"
    >
      <title>{iconData.title}</title>
      <path d={iconData.path} />
    </svg>
  );
};

