// Minimum shape of a Databricks Spark version entry the UI consumes. The full
// payload from `listSparkVersions` carries more metadata, but only `key` (the
// value sent back to Databricks) and `name` (the human-readable label) are
// needed for rendering and recommendation logic.
interface SparkVersionOption {
  key: string;
  name: string;
}

// True when the version is the team's recommended runtime for new clusters.
// Today that means 17.3 LTS Photon (non-ML). Kept as a pure module-level
// helper so the same rule drives both the "Recommended" badge and the sort
// order in the picker — if the recommendation changes, only this function
// needs to be updated.
const isRecommendedSparkVersion = (name: string | undefined): boolean => {
  if (!name) return false;
  return (
    name.includes("17.3") && name.includes("LTS") && name.includes("Photon") && !name.includes("ML")
  );
};

