                                  const schemaKey = `${catalog.name}.${schema.name}`;
                                  const isSchemaExpanded = expandedSchemas.has(schemaKey);
                                  const volumes = schemaVolumes[schemaKey] || [];
                                  const isLoadingVolumes = loadingSchemaVolumes[schemaKey];

