import type { User as AuthUser } from "@/features/auth/types";

/**
 * Generate home page URL with username and organization
 * @param user - User object containing username and organization
 * @returns Formatted URL path for home page
 */
export const generateHomeUrl = (user: AuthUser | null): string => {
  if (!user?.username || !user.organization) {
    return "/";
  }

  const homeUrl = `/${user.organization}/${user.username}`;

  return homeUrl;
};

/**
 * Generate editor URL with username and organization
 * @param user - User object containing username and organization
 * @param projectId - Project ID
 * @returns Formatted URL path
 */
export const generateEditorUrl = (user: AuthUser | null, ontologyId: string): string => {
  if (!user?.username || !user.organization) {
    return `/editor/${ontologyId}`;
  }

  return `/editor/${user.organization}/${user.username}/${ontologyId}`;
};

/**
 * Extract URL parameters from the current path
 * @param pathname - Current URL pathname
 * @returns Object containing organization, username, and projectId
 */
export const extractUrlParams = (
  pathname: string,
): {
  organization?: string;
  username?: string;
  ontologyId?: string;
  isNewFormat?: boolean;
  isHomePage?: boolean;
} => {
  const pathParts = pathname.split("/").filter(Boolean);

  const WORKSPACE_ROUTE_PREFIXES = [
    "apps",
    "compute",
    "context",
    "dashboards",
    "datasources",
    "editor",
    "onboarding",
    "projects",
    "reset-password",
    "settings",
    "setup",
    "teams",
  ];
  if (
    pathParts.length === 2 &&
    pathParts[0] &&
    pathParts[1] &&
    !WORKSPACE_ROUTE_PREFIXES.includes(pathParts[0])
  ) {
    const [organization, username] = pathParts;
    return { organization, username, isNewFormat: true, isHomePage: true };
  }

  if (pathParts.length >= 4 && pathParts[0] === "editor" && pathParts.length > 3) {
    const [, organization, username, ontologyId] = pathParts;
    return { organization, username, ontologyId, isNewFormat: true, isHomePage: false };
  }

  if (pathParts.length >= 2 && pathParts[0] === "editor") {
    const [, ontologyId] = pathParts;
    return { ontologyId, isNewFormat: false, isHomePage: false };
  }

  if (pathParts.length === 0) {
    return { isNewFormat: false, isHomePage: true };
  }

  return {};
};
