import { Label } from "@/shared/components/ui/label";

interface UnboundWidgetPlaceholderProps {
  kind: "input" | "form";
  label?: string;
}

/**
 * Shown while an input_ref / form_ref widget has no binding yet, so the
 * widget is visible on the canvas from the moment it is added instead of
 * collapsing to an invisible sliver.
 */
export function UnboundWidgetPlaceholder({ kind, label }: UnboundWidgetPlaceholderProps) {
  if (kind === "form") {
    return (
      <div className="flex min-h-24 flex-col items-center justify-center gap-1 rounded-md border border-dashed border-border bg-muted/20 p-4">
        <p className="text-xs font-medium text-muted-foreground">{label ?? "Form"}</p>
        <p className="text-[11px] text-muted-foreground/70">
          Bind a form in the inspector to render it here
        </p>
      </div>
    );
  }
  return (
    <div className="flex flex-col gap-1.5">
      <Label className="text-[11px] font-medium text-foreground/70">{label ?? "Input"}</Label>
      <div className="flex h-9 items-center rounded-md border border-dashed border-border bg-muted/20 px-3 text-[11px] text-muted-foreground/70">
        Bind an input in the inspector
      </div>
    </div>
  );
}
