/**
 * Cleans up verbose backend error messages for display in toasts and inline errors.
 * Strips Java class names and redundant prefixes while preserving the actual message.
 */
export function simplifyFetchError(rawMessage: string): string {
  if (!rawMessage) return "An unknown error occurred";

  let cleaned = rawMessage
    // Strip "Error fetching data for predicate 'X': " prefix
    .replace(/^Error fetching data for predicate '[^']*':\s*/i, "")
    // Strip "Spark Connect execution failed: " prefix
    .replace(/^Spark Connect execution failed:\s*/i, "")
    // Strip Java/Scala exception class names (e.g. org.sparkproject.connect.grpc.StatusRuntimeException: )
    .replace(/[\w]+\.[\w.]+Exception:\s*/g, "")
    .replace(/[\w]+\.[\w.]+Error:\s*/g, "")
    // Collapse repeated status codes (e.g. "PERMISSION_DENIED: PERMISSION_DENIED:")
    .replace(/(\b[A-Z_]+):\s*\1:\s*/g, "$1: ")
    .replace(/\s+/g, " ")
    .trim();

  if (cleaned.length > 300) {
    cleaned = `${cleaned.substring(0, 297)}...`;
  }

  return cleaned || rawMessage;
}
