import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

export interface FileEntry {
  name: string;
  type: "file" | "directory";
  size: number | null;
  modified: string;
  extension?: string;
}

interface DeleteResult {
  deleted: string[];
  errors: Array<{ path: string; error: string }>;
}

const baseUrl = () => PROMETHEUX_CONFIG.BASE_URL;
const token = () => PROMETHEUX_CONFIG.AUTH_TOKEN;

export async function listFiles(path = ""): Promise<FileEntry[]> {
  const url = `${baseUrl()}/data/files/list?path=${encodeURIComponent(path)}`;
  const response = await HttpService.get(url, token());
  if (response.status === "success") return response.data;
  throw new Error(response.message ?? "Failed to list files");
}

export async function createDirectory(path: string): Promise<string> {
  const url = `${baseUrl()}/data/files/mkdir`;
  const response = await HttpService.post(url, { path }, token());
  if (response.status === "success") return response.data.path;
  throw new Error(response.message ?? "Failed to create directory");
}

export async function deleteFiles(paths: string[], recursive = false): Promise<DeleteResult> {
  const url = `${baseUrl()}/data/files/delete`;
  const response = await HttpService.post(url, { paths, recursive }, token());
  if (response.status === "success") return response.data;
  throw new Error(response.message ?? "Failed to delete files");
}

export async function moveFile(
  source: string,
  destination: string,
): Promise<{ source: string; destination: string }> {
  const url = `${baseUrl()}/data/files/move`;
  const response = await HttpService.post(url, { source, destination }, token());
  if (response.status === "success") return response.data;
  throw new Error(response.message ?? "Failed to move file");
}
