import type { ConceptData } from "@/features/concepts/api";

export interface ConceptGroup {
  inputConcepts: ConceptData[];
  definedConcepts: ConceptData[];
}

/**
 * Groups concepts into Input Concepts and Defined Concepts.
 * Since datasources are now managed separately, all concepts here are "defined".
 */
export const groupConceptsByType = (concepts: ConceptData[]): ConceptGroup => {
  return {
    inputConcepts: [],
    definedConcepts: [...concepts],
  };
};

/**
 * Formats concept data for clipboard copying with predicate name and fields
 */
export const formatConceptForClipboard = (
  concept: ConceptData | { predicate_name: string; fields?: Record<string, string> },
): string => {
  const predicateName = concept.predicate_name;

  // Get fields from the concept data
  let fields: Record<string, string> = {};
  if (concept.fields && typeof concept.fields === "object") {
    fields = concept.fields;
  }

  // If we have fields, format as predicate(field1,field2,...)
  if (Object.keys(fields).length > 0) {
    const fieldNames = Object.keys(fields);
    return `${predicateName}(${fieldNames.join(",")})`;
  }

  // Fallback to just predicate name if no fields available
  return predicateName;
};
