import { Check, ChevronLeft } from "lucide-react";
import type React from "react";
import { LottiePlayer } from "@/shared/components/LottiePlayer";

interface OntologyCreationLoaderProps {
  title?: string;
  steps: string[];
  currentStep: number;
  onBack?: () => void;
}

const OntologyCreationLoader: React.FC<OntologyCreationLoaderProps> = ({
  title = "Creating Ontology",
  steps,
  currentStep,
  onBack,
}) => {
  return (
    <div className="fixed inset-0 bg-background z-50 flex">
      {/* Left Sidebar - Progress */}
      <div className="w-[400px] bg-card border-r border-border p-8 flex flex-col">
        {onBack && (
          <button
            onClick={onBack}
            className="mb-6 p-2 hover:bg-secondary rounded-md transition-colors w-fit"
            aria-label="Go back"
          >
            <ChevronLeft className="w-5 h-5 text-foreground" />
          </button>
        )}

        <div className="mb-8">
          <div className="w-12 h-12 bg-card rounded-full flex items-center justify-center border border-border shadow-sm">
            <img src="/prometheux-icon.png" alt="Prometheux" className="w-8 h-8 object-contain" />
          </div>
        </div>

        <h2 className="text-3xl font-bold text-foreground mb-8">{title}</h2>

        <div className="flex-1">
          <div className="relative">
            {steps.map((step, index) => {
              const isCompleted = index < currentStep;
              const isActive = index === currentStep;

              return (
                <div key={index} className="relative flex items-start mb-6">
                  {index < steps.length - 1 && (
                    <div
                      className="absolute left-5 top-10 w-0.5 bg-border"
                      style={{ height: "calc(100% + 1.5rem)" }}
                    />
                  )}
                  <div className="relative z-10 flex items-center">
                    <div
                      className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${
                        isCompleted
                          ? "bg-muted border-2 border-border"
                          : isActive
                            ? "bg-background border-0"
                            : "bg-background border-2 border-border"
                      }`}
                    >
                      {isCompleted ? (
                        <Check className="w-5 h-5 text-muted-foreground" />
                      ) : isActive ? (
                        <div className="flex gap-1.5 items-center">
                          <div className="w-2 h-2 bg-orange-500 rounded-full animate-pulse" />
                          <div className="w-2 h-2 bg-yellow-500 rounded-full animate-pulse [animation-delay:150ms]" />
                          <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse [animation-delay:300ms]" />
                        </div>
                      ) : (
                        <div className="w-2 h-2 bg-border rounded-full" />
                      )}
                    </div>
                  </div>
                  <div className="ml-4 flex-1 pt-2">
                    <p
                      className={`text-lg transition-colors ${
                        isActive
                          ? "font-semibold text-foreground"
                          : isCompleted
                            ? "text-muted-foreground"
                            : "text-muted-foreground/60"
                      }`}
                    >
                      {step}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Right Content Area - Hero Animation */}
      <div className="flex-1 bg-background relative overflow-hidden flex items-center justify-center">
        <LottiePlayer
          src="/hero-animation.json"
          style={{ width: "700px", height: "100%" }}
          loop
          autoplay
        />
      </div>
    </div>
  );
};

export default OntologyCreationLoader;
