import { Eye, Pencil, ShieldCheck, Trash2 } from "lucide-react";

import { prettifyToolName } from "@/features/code-assistant/authorization.utils";
import {
  type AssistantMode,
  useAuthorizationsStore,
} from "@/features/code-assistant/store/authorizationsStore";
import { Button } from "@/shared/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/shared/components/ui/card";

const MODE_OPTIONS: { value: AssistantMode; label: string; hint: string; icon: React.ReactNode }[] =
  [
    {
      value: "agent",
      label: "Agent",
      hint: "Can make changes, asking for your authorization first.",
      icon: <Pencil className="h-4 w-4" />,
    },
    {
      value: "ask",
      label: "Ask",
      hint: "Can read and answer, but never changes anything.",
      icon: <Eye className="h-4 w-4" />,
    },
  ];

const AssistantSettings = () => {
  const mode = useAuthorizationsStore((s) => s.mode);
  const setMode = useAuthorizationsStore((s) => s.setMode);
  const authorizedTools = useAuthorizationsStore((s) => s.authorizedTools);
  const revokeTool = useAuthorizationsStore((s) => s.revokeTool);
  const clearAuthorizedTools = useAuthorizationsStore((s) => s.clearAuthorizedTools);

  const hasAuthorizations = authorizedTools.length > 0;

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Default mode</CardTitle>
          <CardDescription>
            How the assistant starts each new chat. You can switch this per-chat from the picker
            next to the model selector.
          </CardDescription>
        </CardHeader>
        <CardContent className="grid gap-3 sm:grid-cols-2">
          {MODE_OPTIONS.map((option) => {
            const active = mode === option.value;
            return (
              <button
                key={option.value}
                type="button"
                onClick={() => setMode(option.value)}
                className={`flex flex-col gap-1 rounded-md border p-3 text-left transition-colors ${
                  active
                    ? "border-primary bg-primary/10"
                    : "border-border hover:bg-accent hover:text-accent-foreground"
                }`}
              >
                <span className="flex items-center gap-2 text-sm font-medium">
                  {option.icon}
                  {option.label}
                </span>
                <span className="text-xs text-muted-foreground">{option.hint}</span>
              </button>
            );
          })}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-lg">
            <ShieldCheck className="h-5 w-5" />
            Always-allowed actions
          </CardTitle>
          <CardDescription>
            Actions you chose "Always allow" for. The assistant runs these without asking again.
            Destructive actions (like deletes) can never be added here — they always ask.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {!hasAuthorizations ? (
            <p className="text-sm text-muted-foreground">
              No actions are always-allowed yet. When the assistant asks for authorization, choose
              "Always allow" to add it here.
            </p>
          ) : (
            <div className="space-y-4">
              <ul className="divide-y divide-border rounded-md border">
                {authorizedTools.map((tool) => (
                  <li key={tool} className="flex items-center justify-between px-3 py-2">
                    <span className="text-sm">{prettifyToolName(tool)}</span>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="text-muted-foreground hover:text-destructive"
                      onClick={() => revokeTool(tool)}
                    >
                      <Trash2 className="mr-1 h-3.5 w-3.5" />
                      Revoke
                    </Button>
                  </li>
                ))}
              </ul>
              <Button type="button" variant="outline" size="sm" onClick={clearAuthorizedTools}>
                Revoke all
              </Button>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default AssistantSettings;
