import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/shared/components/ui/card";
import { Label } from "@/shared/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/shared/components/ui/radio-group";
import { Switch } from "@/shared/components/ui/switch";
import { type DefaultCellView, usePreferencesStore } from "@/shared/store/preferencesStore";
import { type Theme, useThemeStore } from "@/shared/store/themeStore";

function isTheme(value: string): value is Theme {
  return value === "light" || value === "dark";
}

function isDefaultCellView(value: string): value is DefaultCellView {
  return value === "code" || value === "description";
}

const PreferencesSettings = () => {
  const theme = useThemeStore((state) => state.theme);
  const setTheme = useThemeStore((state) => state.setTheme);
  const defaultCellView = usePreferencesStore((state) => state.defaultCellView);
  const setDefaultCellView = usePreferencesStore((state) => state.setDefaultCellView);
  const wrapCodeByDefault = usePreferencesStore((state) => state.wrapCodeByDefault);
  const setWrapCodeByDefault = usePreferencesStore((state) => state.setWrapCodeByDefault);

  const handleThemeChange = (value: string) => {
    if (isTheme(value)) setTheme(value);
  };

  const handleDefaultCellViewChange = (value: string) => {
    if (isDefaultCellView(value)) setDefaultCellView(value);
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Appearance</CardTitle>
          <CardDescription>Control how Prometheux looks.</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            <Label className="text-sm font-medium text-foreground">Theme</Label>
            <p className="text-xs text-muted-foreground">Choose between light and dark mode.</p>
            <RadioGroup value={theme} onValueChange={handleThemeChange} className="pt-2">
              <div className="flex items-center gap-2">
                <RadioGroupItem value="light" id="theme-light" />
                <Label htmlFor="theme-light" className="font-normal">
                  Light
                </Label>
              </div>
              <div className="flex items-center gap-2">
                <RadioGroupItem value="dark" id="theme-dark" />
                <Label htmlFor="theme-dark" className="font-normal">
                  Dark
                </Label>
              </div>
            </RadioGroup>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Editor</CardTitle>
          <CardDescription>Defaults applied when opening concept cells.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-2">
            <Label className="text-sm font-medium text-foreground">Default cell view</Label>
            <p className="text-xs text-muted-foreground">
              Which view a cell opens on. You can still switch views per cell.
            </p>
            <RadioGroup
              value={defaultCellView}
              onValueChange={handleDefaultCellViewChange}
              className="pt-2"
            >
              <div className="flex items-center gap-2">
                <RadioGroupItem value="code" id="cell-view-code" />
                <Label htmlFor="cell-view-code" className="font-normal">
                  Code
                </Label>
              </div>
              <div className="flex items-center gap-2">
                <RadioGroupItem value="description" id="cell-view-description" />
                <Label htmlFor="cell-view-description" className="font-normal">
                  Description
                </Label>
              </div>
            </RadioGroup>
          </div>

          <div className="flex items-center justify-between gap-4">
            <div className="space-y-1">
              <Label htmlFor="wrap-code" className="text-sm font-medium text-foreground">
                Wrap code by default
              </Label>
              <p className="text-xs text-muted-foreground">
                Wrap long lines in code editors instead of scrolling horizontally.
              </p>
            </div>
            <Switch
              id="wrap-code"
              checked={wrapCodeByDefault}
              onCheckedChange={setWrapCodeByDefault}
            />
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default PreferencesSettings;
