import type React from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";

interface DeleteAllSourcesDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirm: () => void;
  isDeleting?: boolean;
  selectedCount?: number;
}

export const DeleteAllSourcesDialog: React.FC<DeleteAllSourcesDialogProps> = ({
  open,
  onOpenChange,
  onConfirm,
  isDeleting,
  selectedCount = 0,
}) => {
  const isDeleteSelected = selectedCount > 0;
  const title = isDeleteSelected
    ? `Delete selected data source${selectedCount === 1 ? "" : "s"}`
    : "Delete all data sources";

  const description = isDeleteSelected
    ? `Are you sure you want to delete the data source${selectedCount === 1 ? "" : "s"}? It cannot be undone.`
    : "Are you sure you want to delete all data sources? It cannot be undone.";

  const actionText = isDeleteSelected
    ? `Delete ${selectedCount === 1 ? "Source" : "Sources"}`
    : "Delete All";

  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
          <AlertDialogAction
            onClick={onConfirm}
            disabled={isDeleting}
            className="bg-destructive hover:bg-destructive/90"
          >
            {isDeleting ? "Deleting..." : actionText}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
};
