import { useQuery } from "@tanstack/react-query";
import { AppWindow, ArrowLeft, Play } from "lucide-react";
import React, { useEffect, useMemo, useRef } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { type OntologyData, OntologyService } from "@/features/ontologies/api";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Label } from "@/shared/components/ui/label";
import { trackAppOpened } from "@/shared/services/analyticsEvents";
import { type AppConcept, ConceptClient } from "../../api/ConceptClient";
import { DashboardClient } from "../../api/DashboardClient";
import { AppRenderer } from "../../components/app/AppRenderer";
import { DashboardRenderer } from "../../components/DashboardRenderer";
import { useDashboardRun } from "../../hooks/useDashboardRun";
import { PUBLISHING_UI_ENABLED } from "../../publishing";
import { isV2Authorable, migrateDefinition } from "../../schema/migrateDefinition";
import { type ParsedParam, parseParamAnnotations } from "../../utils/paramParser";
import { ParamField } from "./ParamField";

const apiClient = new ConceptClient();
const dashboardClient = new DashboardClient();

export function DashboardRunContent() {
  const { ontologyId, id } = useParams<{ ontologyId: string; id: string }>();
  const navigate = useNavigate();

  // Viewers get the published snapshot; unpublished apps fall back to the
  // live draft (flagged with a Draft chip below).
  const { data: record = null, isLoading: isRecordLoading } = useQuery({
    queryKey: ["dashboard-record", ontologyId, id, "published"],
    queryFn: () => dashboardClient.getDashboardRecord(ontologyId!, id!, "published"),
    enabled: !!ontologyId && !!id,
  });
  const dashboard = record?.definition ?? null;
  const isServingDraft = record !== null && record.served === "draft";

  const { data: concepts = [], isLoading: conceptsLoading } = useQuery<AppConcept[]>({
    queryKey: ["dashboard-run-concepts", dashboard?.ontologyId],
    queryFn: () => apiClient.listConcepts(dashboard!.ontologyId),
    enabled: !!dashboard?.ontologyId,
  });

  const { data: projects = [] } = useQuery<OntologyData[]>({
    queryKey: ["dashboard-projects"],
    queryFn: () => OntologyService.listOntologies(["user", "organization"]),
  });

  // Record that an end user opened this app, once per app id.
  const openedRef = useRef<string | null>(null);
  useEffect(() => {
    if (!dashboard || !id) return;
    if (openedRef.current === id) return;
    openedRef.current = id;
    trackAppOpened({
      appId: id,
      appName: dashboard.name,
      appType: "dynamic",
      ontologyId: dashboard.ontologyId ?? ontologyId,
    });
  }, [dashboard, id, ontologyId]);

  const inputConcept = useMemo(
    () => concepts.find((c) => c.predicate_name === dashboard?.inputConceptName) ?? null,
    [concepts, dashboard?.inputConceptName],
  );

  const parsedParams = useMemo<ParsedParam[]>(() => {
    const ann = inputConcept?.concept_details?.[0]?.param_annotations;
    return ann ? parseParamAnnotations(ann) : [];
  }, [inputConcept]);

  const allWidgetConcepts = useMemo(() => {
    if (!dashboard) return [];
    const names = new Set<string>();
    dashboard.pages.forEach((p) =>
      p.sections.forEach((s) =>
        s.widgets.forEach((w) => {
          if (w.conceptName) names.add(w.conceptName);
        }),
      ),
    );
    return Array.from(names);
  }, [dashboard]);

  const {
    paramValues,
    setParamValues,
    isRunning,
    runStatus,
    conceptData,
    loadingConcepts,
    errorConcepts,
    handleRun,
    tableHandlers,
  } = useDashboardRun({
    dashboard,
    allWidgetConcepts,
    parsedParams,
    inputConcept,
    conceptsLoading,
  });

  if (isRecordLoading) {
    return (
      <div className="flex flex-col items-center justify-center h-full gap-4 text-muted-foreground">
        <PrometheuxSpinner size={32} />
        <p className="text-sm">Loading app…</p>
      </div>
    );
  }

  if (!dashboard) {
    return (
      <div className="flex flex-col items-center justify-center h-full gap-4 text-muted-foreground">
        <AppWindow className="h-12 w-12 opacity-20" />
        <p className="text-sm">App not found.</p>
        <Button variant="outline" size="sm" onClick={() => navigate("/apps")}>
          Back to Apps
        </Button>
      </div>
    );
  }

  // Schema v2 apps carry their own inputs, run buttons and forms per tab —
  // no broadcast param strip or global RUN button.
  const appDefinition = migrateDefinition(dashboard);
  const homeOntology = ontologyId
    ? {
        id: ontologyId,
        name: projects.find((candidate) => candidate.id === ontologyId)?.name ?? ontologyId,
      }
    : undefined;
  if (isV2Authorable(appDefinition)) {
    return (
      <div className="flex flex-col h-full overflow-hidden">
        <div className="flex items-center gap-3 px-6 h-14 border-b border-border flex-shrink-0 bg-background">
          <Button
            variant="ghost"
            size="iconSm"
            onClick={() => navigate("/apps")}
            className="text-muted-foreground flex-shrink-0"
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <AppWindow className="h-5 w-5 text-foreground/50 flex-shrink-0" />
          <h1 className="text-[17px] font-semibold tracking-tight truncate">{dashboard.name}</h1>
          {PUBLISHING_UI_ENABLED && isServingDraft && (
            <span className="text-[10px] px-2 py-0.5 rounded-full bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400 flex-shrink-0">
              Draft — not published
            </span>
          )}
        </div>
        <div className="flex-1 overflow-hidden">
          <AppRenderer definition={appDefinition} project={homeOntology} />
        </div>
      </div>
    );
  }

  const hasData =
    Object.keys(conceptData).length > 0 ||
    Object.keys(loadingConcepts).some((k) => loadingConcepts[k]) ||
    Object.keys(errorConcepts).length > 0;

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* ── Top bar ── */}
      <div className="flex items-center justify-between px-6 h-14 border-b border-border flex-shrink-0 bg-background">
        <div className="flex items-center gap-3 min-w-0 overflow-hidden">
          <Button
            variant="ghost"
            size="iconSm"
            onClick={() => navigate("/apps")}
            className="text-muted-foreground flex-shrink-0"
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <AppWindow className="h-5 w-5 text-foreground/50 flex-shrink-0" />
          <h1 className="text-[17px] font-semibold tracking-tight truncate">{dashboard.name}</h1>
        </div>
        <Button
          onClick={handleRun}
          disabled={isRunning || allWidgetConcepts.length === 0}
          className="gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 flex-shrink-0"
        >
          {isRunning ? <PrometheuxSpinner size={16} /> : <Play className="h-4 w-4 fill-white" />}
          {isRunning ? "Running…" : "RUN"}
        </Button>
      </div>

      {/* ── Dashboard header (logo, title, subtitle, tags) ── */}
      <div className="bg-card border-b border-border px-8 h-14 flex items-center justify-between flex-shrink-0">
        <div className="flex items-center gap-5 min-w-0 overflow-hidden">
          {dashboard.header.logoUrl ? (
            <>
              <img
                src={dashboard.header.logoUrl}
                alt="Logo"
                className="h-[22px] w-auto flex-shrink-0"
              />
              <div className="w-px h-5 bg-border flex-shrink-0" />
            </>
          ) : null}
          <div className="min-w-0">
            <div className="text-[13px] font-medium text-foreground/80 leading-tight truncate">
              {dashboard.header.title || "App"}
            </div>
            {dashboard.header.subtitle && (
              <div className="text-[11px] font-mono text-muted-foreground mt-px truncate">
                {dashboard.header.subtitle}
              </div>
            )}
          </div>
        </div>
        <div className="flex items-center gap-3 flex-shrink-0">
          {dashboard.header.showStatus && (
            <div
              className="w-[7px] h-[7px] rounded-full bg-green-500"
              style={{ boxShadow: "0 0 0 2px rgb(240 253 244)" }}
            />
          )}
          {dashboard.header.tags?.map((tag, i) => (
            <span
              key={i}
              className="text-[11px] font-mono text-muted-foreground bg-secondary border border-border px-2.5 py-[3px] rounded"
            >
              {tag}
            </span>
          ))}
        </div>
      </div>

      {/* ── Filters strip — only shown when there are params (or still loading) ── */}
      {(conceptsLoading || parsedParams.length > 0 || runStatus) && (
        <div className="border-b border-border flex-shrink-0 bg-card">
          <div className="flex items-end gap-5 px-8 py-3 flex-wrap">
            {conceptsLoading && (
              <div className="flex items-center gap-2 text-xs text-muted-foreground py-1">
                <PrometheuxSpinner size={16} />
                Loading parameters…
              </div>
            )}
            {!conceptsLoading &&
              parsedParams.map((param) => (
                <div key={param.name} className="flex flex-col gap-1">
                  <Label
                    htmlFor={`run-${param.name}`}
                    className="text-[11px] font-medium text-foreground/70"
                  >
                    {param.name}
                  </Label>
                  <ParamField
                    param={param}
                    value={paramValues[param.name] ?? param.defaultValue}
                    onChange={(val) => setParamValues((prev) => ({ ...prev, [param.name]: val }))}
                  />
                </div>
              ))}
            {runStatus && (
              <span className="ml-auto self-center text-[11px] text-muted-foreground font-mono">
                {runStatus}
              </span>
            )}
          </div>
        </div>
      )}

      {/* ── Dashboard content ── */}
      <div className={`flex-1 overflow-hidden ${!hasData ? "opacity-60" : ""}`}>
        <DashboardRenderer
          dashboard={dashboard}
          data={hasData ? conceptData : {}}
          loadingConcepts={hasData ? loadingConcepts : {}}
          errorConcepts={hasData ? errorConcepts : {}}
          hideHeader
          tableHandlers={tableHandlers}
        />
      </div>
    </div>
  );
}
