import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";
import {
  type IssueTokenData,
  type IssueTokenRequest,
  IssueTokenResponseSchema,
  ListTokensResponseSchema,
  RevokeAllResponseSchema,
  type RevokeTokenResponse,
  RevokeTokenResponseSchema,
  type TokenSummary,
} from "./apiKeys.types";

const AUTH_BASE = "/auth";

export class AuthApiUnauthorizedError extends Error {
  constructor() {
    super("Authentication token is invalid or expired");
    this.name = "AuthApiUnauthorizedError";
  }
}

export class AuthApiError extends Error {
  constructor(
    public readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = "AuthApiError";
  }
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function extractErrorMessage(raw: string, fallback: string): string {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (isObject(parsed)) {
      if (typeof parsed.message === "string") return parsed.message;
      if (typeof parsed.detail === "string") return parsed.detail;
    }
  } catch {
    /* fall through to fallback */
  }
  return fallback;
}

async function authedFetch(path: string, init: RequestInit): Promise<Response> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}${AUTH_BASE}${path}`;
  const headers = HttpService.getHeaders(
    undefined,
    init.headers as Record<string, string> | undefined,
  );
  return fetch(url, { ...init, headers, mode: "cors" });
}

async function parseJsonOrThrow(response: Response): Promise<unknown> {
  const text = await response.text();

  if (response.status === 401) throw new AuthApiUnauthorizedError();

  if (!response.ok) {
    throw new AuthApiError(response.status, extractErrorMessage(text, response.statusText));
  }

  try {
    return JSON.parse(text);
  } catch {
    throw new AuthApiError(response.status, "Invalid JSON response from /auth endpoint");
  }
}

async function issueToken(request: IssueTokenRequest): Promise<IssueTokenData> {
  const body: Record<string, unknown> = {};
  if (request.name) body.name = request.name;
  if (request.expiresInMinutes && request.expiresInMinutes > 0) {
    body.expires_in_minutes = request.expiresInMinutes;
  }

  const response = await authedFetch("/issue-token", {
    method: "POST",
    body: JSON.stringify(body),
  });
  const raw = await parseJsonOrThrow(response);
  return IssueTokenResponseSchema.parse(raw).data;
}

async function listTokens(): Promise<TokenSummary[]> {
  const response = await authedFetch("/tokens", { method: "GET" });
  const raw = await parseJsonOrThrow(response);
  return ListTokensResponseSchema.parse(raw).data.tokens;
}

async function revokeToken(jti: string): Promise<RevokeTokenResponse["data"]> {
  const response = await authedFetch(`/revoke/${encodeURIComponent(jti)}`, {
    method: "POST",
  });
  const raw = await parseJsonOrThrow(response);
  return RevokeTokenResponseSchema.parse(raw).data;
}

async function revokeCurrentSession(): Promise<void> {
  const response = await authedFetch("/revoke", { method: "POST" });
  await parseJsonOrThrow(response);
}

async function revokeAll(): Promise<void> {
  const response = await authedFetch("/revoke-all", { method: "POST" });
  const raw = await parseJsonOrThrow(response);
  RevokeAllResponseSchema.parse(raw);
}

export const authApiClient = {
  issueToken,
  listTokens,
  revokeToken,
  revokeCurrentSession,
  revokeAll,
};
