import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { useCellCurlSnippet } from "@/features/concept-editor/hooks/useCellCurlSnippet";
import { useCellDragDrop } from "@/features/concept-editor/hooks/useCellDragDrop";
import {
  useCellRename,
  useConceptRenameCommit,
} from "@/features/concept-editor/hooks/useCellRename";
import { useCellSplitPanes } from "@/features/concept-editor/hooks/useCellSplitPanes";
import { useCellView } from "@/features/concept-editor/hooks/useCellView";
import type { CellBinds } from "@/features/concept-editor/types";
import { AccordionContent } from "@/shared/components/ui/accordion";
import { cn } from "@/shared/lib/utils";
import { getCellTitle, isNewCellTitle } from "./cell.utils";
import { CellAccordionShell } from "./components/CellAccordionShell";
import { CellContextTab } from "./components/CellContextTab";
import CellEditor from "./components/CellEditor";
import { CellHeaderRow } from "./components/CellHeaderRow";
import { CellRenameControl } from "./components/CellRenameControl";
import CellResults from "./components/CellResults";
import CellSettings from "./components/CellSettings";
import { CellSplitBottomTabs } from "./components/CellSplitBottomTabs";
import CellToolbar from "./components/CellToolbar";
import PythonCellViewTabs from "./components/PythonCellViewTabs";
import PolicySection from "./components/policies/PolicySection";
import { SplitDragHandle } from "./components/SplitDragHandle";
import type { QueryConceptCellProps } from "./types/editorTypes";

const PYTHON_PLACEHOLDER = `# Define main() returning the concept's rows as a list of dicts.
# The dict keys become the output columns.
#
# Declare dependencies in-code (each returns a pandas DataFrame):
#   use_px_concept("other_concept")  -> read another concept's output
#   use_px_data("my_datasource")     -> read a connected datasource

def main():
    # df = use_px_concept("other_concept")
    # rows = use_px_data("my_datasource")
    return [
        {"id": 1, "name": "alpha"},
        {"id": 2, "name": "beta"},
    ]`;

// Extended props for Python cell - adds handler for concept name changes
interface QueryPythonCellProps extends QueryConceptCellProps {
  onOutputPredicateChange?: (cellId: string, outputPredicate: string) => void;
}

const QueryPythonCell: React.FC<QueryPythonCellProps> = ({
  cell,
  index,
  extensions,
  editorTheme,
  onCodeChange,
  onRunCell,
  onDeleteCell,
  onClearResults,
  onRestoreResults,
  onSaveCell,
  onStopCell,
  setCells,
  changePage,
  isLoadingPage,
  searchPredicateData,
  clearSearch,
  groupNames,
  onAddCellToGroup,
  onRemoveCellFromGroup,
  onOutputPredicateChange,
  onCellTypeChange,
  onRenameConcept,
  defaultView,
  onViewChange,
  splitLayout,
}) => {
  const cellTitle = getCellTitle(cell.outputPredicate, index, "Python Cell");
  const isNewCell = isNewCellTitle(cellTitle, cell.id, "Python Cell");
  const [open, setOpen] = useState<string | null>(isNewCell ? cell.id : null);
  const isOpen = open === cell.id;
  const initialView: "context" | "python" | "output" =
    defaultView === "python" || defaultView === "output" ? defaultView : "context";
  const { currentView, setCurrentView } = useCellView<"context" | "python">(cell, initialView);

  // In split layout, propagate currentView changes to the parent so it can
  // persist the bottom panel state. Skip the initial mount.
  const initialViewSyncRef = useRef(true);
  useEffect(() => {
    if (!splitLayout || !onViewChange) return;
    if (initialViewSyncRef.current) {
      initialViewSyncRef.current = false;
      return;
    }
    onViewChange(currentView);
  }, [currentView, splitLayout, onViewChange]);

  const {
    isBottomPanelOpen,
    editorPaneRef,
    bottomPaneRef,
    splitEditorStyle,
    splitBottomFlexStyle,
    editorRatio,
    handleSplitDragStart,
    adjustRatio,
  } = useCellSplitPanes({ splitLayout, currentView, editorView: "python" });
  const [showSettings, setShowSettings] = useState(false);
  const [showBindEditor, setShowBindEditor] = useState(false);

  const handleToggleSettings = useCallback(() => {
    setShowSettings((prev) => {
      if (!prev) setShowBindEditor(false);
      return !prev;
    });
  }, []);

  const handleToggleBindEditor = useCallback(() => {
    if (!isOpen) setOpen(cell.id);
    setShowBindEditor((prev) => {
      if (!prev) setShowSettings(false);
      return !prev;
    });
  }, [cell.id, isOpen]);

  const handleBindsChange = useCallback(
    (newBinds: CellBinds) => {
      setCells((prevCells) => {
        const idx = prevCells.findIndex((c) => c.id === cell.id);
        if (idx === -1) return prevCells;
        const updated = [...prevCells];
        updated[idx] = { ...updated[idx], binds: newBinds, isModified: true };
        return updated;
      });
    },
    [setCells, cell.id],
  );
  const { dropPosition, handleDragOver, handleDragLeave, handleDrop } = useCellDragDrop(cell.id);
  const buildCurlSnippet = useCellCurlSnippet(cell.outputPredicate);
  const rename = useCellRename({
    currentName: cell.outputPredicate,
    onCommit: useConceptRenameCommit({ cell, setCells, onRenameConcept, onOutputPredicateChange }),
  });

  const currentGroup = cell.group && cell.group !== "group_id" ? cell.group : null;

  // Store ref to get current code directly from CodeMirror
  const getCurrentCodeRef = useRef<(() => string) | null>(null);

  React.useEffect(() => {
    if (cell.autoOpen) {
      setOpen(cell.id);
      setCells((prevCells) =>
        prevCells.map((c) => (c.id === cell.id ? { ...c, autoOpen: false } : c)),
      );
    }
  }, [cell.autoOpen, cell.id, setCells]);

  // Refs for stable callback dependencies
  const cellIdRef = useRef(cell.id);
  cellIdRef.current = cell.id;
  const handleSaveCell = useCallback(
    async (cellId: string, _unusedFreshCode?: string, showToast?: boolean) => {
      if (onSaveCell) {
        let freshCode = cell.code;
        if (getCurrentCodeRef.current) {
          freshCode = getCurrentCodeRef.current();
          if (freshCode !== cell.code) {
            onCodeChange(freshCode, cellId);
          }
        }
        return onSaveCell(cellId, freshCode, showToast);
      }
    },
    [onSaveCell, cell.code, onCodeChange],
  );

  const handleDescriptionChange = useCallback(
    (value: string) => {
      setCells((prevCells) => {
        const cellIndex = prevCells.findIndex((c) => c.id === cellIdRef.current);
        if (cellIndex === -1) return prevCells;

        const updatedCells = [...prevCells];
        updatedCells[cellIndex] = {
          ...prevCells[cellIndex],
          description: value,
          isModified: true,
          needsSave: true,
        };

        return updatedCells;
      });
    },
    [setCells],
  );

  const handleToggleAccordion = useCallback(() => {
    setOpen((prevOpen) => (prevOpen === cell.id ? "" : cell.id));
  }, [cell.id]);

  const handleAccordionChange = (value: string) => {
    setOpen(value);
  };

  const ensureAccordionOpen = () => {
    if (!isOpen) setOpen(cell.id);
  };

  const handleEditorReady = useCallback((getCode: () => string) => {
    getCurrentCodeRef.current = getCode;
  }, []);

  const handleRunCell = async (cellId: string, forceRerun?: boolean) => {
    ensureAccordionOpen();

    if (!cell.outputPredicate || !cell.outputPredicate.trim()) {
      toast.error("Please set a concept name before running");
      return;
    }

    let freshCode = cell.code;
    if (getCurrentCodeRef.current) {
      freshCode = getCurrentCodeRef.current();
      if (freshCode !== cell.code) {
        onCodeChange(freshCode, cellId);
      }
    }

    if (onRunCell) {
      onRunCell(cellId, freshCode, forceRerun);
    }
  };

  const memoizedCell = useMemo(
    () => (
      <CellAccordionShell
        cellId={cell.id}
        cellBackendId={cell.cellBackendId}
        open={open}
        onOpenChange={handleAccordionChange}
        dropPosition={dropPosition}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        <CellHeaderRow
          cell={cell}
          isOpen={isOpen}
          defaultConceptType="python"
          onToggle={handleToggleAccordion}
          onCellTypeChange={onCellTypeChange}
          buildCurlSnippet={buildCurlSnippet}
          currentGroup={currentGroup}
          groupNames={groupNames}
          onAddCellToGroup={onAddCellToGroup}
          onRemoveCellFromGroup={onRemoveCellFromGroup}
          identity={
            <CellRenameControl
              name={cell.outputPredicate || ""}
              isRenaming={rename.isRenaming}
              renameValue={rename.renameValue}
              inputRef={rename.inputRef}
              onRenameValueChange={rename.setRenameValue}
              onConfirm={rename.confirm}
              onCancel={rename.cancel}
              onStart={rename.start}
            />
          }
          toolbar={
            <CellToolbar
              cellId={cell.id}
              code={cell.code}
              isRunning={cell.isRunning}
              isCellSaving={cell.isSaving}
              hasResult={!!cell.result || !!cell.error}
              hasPersistedResults={cell.hasPersistedResults || false}
              isModified={cell.isModified}
              onRunCell={handleRunCell}
              onStopCell={onStopCell}
              onDeleteCell={onDeleteCell}
              onClearResults={onClearResults}
              onRestoreResults={onRestoreResults}
              onSaveCell={handleSaveCell}
              onToggleSettings={handleToggleSettings}
              isSettingsActive={showSettings}
              onToggleBindEditor={handleToggleBindEditor}
              isBindEditorActive={showBindEditor}
              readOnly={cell.readOnly}
            />
          }
        />
        <AccordionContent style={{ overflow: "visible", minWidth: 0 }}>
          <div className="flex flex-col" style={{ minWidth: 0, overflow: "visible" }}>
            {showSettings && (
              <div className="cell-settings-pane w-full p-2 bg-muted/50 border-t border-border/50 flex flex-col gap-2">
                <PolicySection conceptName={cell.outputPredicate} />
              </div>
            )}
            {showBindEditor && (
              <CellSettings
                cellId={cell.id}
                showDataEditor={showBindEditor}
                onToggleDataEditor={handleToggleBindEditor}
                isRunning={cell.isRunning}
                extensions={extensions}
                editorTheme={editorTheme}
                code={cell.code}
                outputPredicate={cell.outputPredicate}
                showBindEditor={showBindEditor}
                binds={cell.binds || { input: [], output: [] }}
                onBindsChange={handleBindsChange}
                conceptType="python"
                fillHeight={splitLayout}
              />
            )}
            <PythonCellViewTabs
              cell={cell}
              currentView={currentView}
              splitLayout={splitLayout}
              onSelectView={setCurrentView}
            />

            {currentView === "context" && (
              <div
                ref={isBottomPanelOpen ? bottomPaneRef : undefined}
                className={cn(
                  "cell-view-pane flex flex-col px-4",
                  splitLayout && "order-5 min-h-0 overflow-auto",
                )}
                style={{
                  position: "relative",
                  zIndex: 1,
                  ...splitBottomFlexStyle,
                }}
              >
                <CellContextTab
                  description={cell.description || ""}
                  onDescriptionChange={handleDescriptionChange}
                  onSaveShortcut={() => handleSaveCell(cell.id)}
                  cellBackendId={cell.cellBackendId}
                  conceptName={cell.outputPredicate || ""}
                  descriptionPlaceholder="Add a description to explain what this Python concept does..."
                />
              </div>
            )}
            {currentView === "output" && (
              <div
                ref={isBottomPanelOpen ? bottomPaneRef : undefined}
                className={cn(
                  "cell-view-pane w-full overflow-x-auto",
                  splitLayout && "order-5 min-h-0 overflow-auto",
                )}
                style={{ maxWidth: "100%", ...splitBottomFlexStyle }}
              >
                <CellResults
                  cell={cell}
                  setCells={setCells}
                  changePage={changePage}
                  isLoadingPage={isLoadingPage}
                  searchPredicateData={searchPredicateData}
                  clearSearch={clearSearch}
                />
              </div>
            )}
            <div
              ref={isBottomPanelOpen ? editorPaneRef : undefined}
              className={cn(
                "cell-editor-pane border-t border-border/50",
                splitLayout && (isBottomPanelOpen ? "order-2 min-h-0" : "order-2 flex-1 min-h-0"),
              )}
              style={splitEditorStyle}
            >
              <CellEditor
                code={cell.code}
                cellId={cell.id}
                isRunning={cell.isRunning}
                extensions={extensions}
                editorTheme={editorTheme}
                onCodeChange={onCodeChange}
                onRunCell={handleRunCell}
                onSaveCell={handleSaveCell}
                placeholder={PYTHON_PLACEHOLDER}
                onToggleMinimize={handleToggleAccordion}
                onEditorReady={handleEditorReady}
                fillHeight={splitLayout}
                readOnly={cell.isSaving}
              />
            </div>
            {isBottomPanelOpen && (
              <SplitDragHandle
                className="order-3"
                onMouseDown={handleSplitDragStart}
                onAdjust={adjustRatio}
                editorPercent={editorRatio * 100}
              />
            )}
            {splitLayout && (
              <CellSplitBottomTabs
                cell={cell}
                currentView={currentView}
                editorView="python"
                onSelectView={setCurrentView}
              />
            )}
          </div>
        </AccordionContent>
      </CellAccordionShell>
    ),
    [
      cell.id,
      cell.code,
      cell.outputPredicate,
      cell.conceptType,
      cell.description,
      cell.isRunning,
      cell.result,
      cell.error,
      cell.hasPersistedResults,
      cell.isModified,
      cell.isSaving,
      cell.cellBackendId,
      cell.binds,
      // Local UI state
      open,
      isOpen,
      currentView,
      splitLayout,
      isBottomPanelOpen,
      editorRatio,
      rename,
      dropPosition,
      showSettings,
      handleToggleSettings,
      showBindEditor,
      handleToggleBindEditor,
      handleBindsChange,
      currentGroup,
      groupNames,
      // Metadata
      index,
      // Stable callbacks
      handleSaveCell,
      handleDescriptionChange,
      handleToggleAccordion,
      handleRunCell,
      handleEditorReady,
      handleDragOver,
      handleDragLeave,
      handleDrop,
      buildCurlSnippet,
      handleSplitDragStart,
      adjustRatio,
      // Config
      extensions,
      editorTheme,
      // Parent handlers
      onCodeChange,
      onDeleteCell,
      onClearResults,
      onRestoreResults,
      onStopCell,
      onCellTypeChange,
      onAddCellToGroup,
      onRemoveCellFromGroup,
      changePage,
      isLoadingPage,
      searchPredicateData,
      clearSearch,
      setCells,
    ],
  );

  return memoizedCell;
};

export default React.memo(QueryPythonCell);
