import { useQueryClient } from "@tanstack/react-query";
import { Loader2 } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { acceptTeamInvitation, declineTeamInvitation } from "@/features/teams/api";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { NOTIFICATIONS_KEY } from "../hooks/useNotifications";
import type { NotificationItem } from "../types";

interface AcceptInvitationDialogProps {
  // The team-invitation notification to act on; null keeps the dialog closed.
  item: NotificationItem | null;
  onClose: () => void;
}

// Accept/decline a team invitation from the notification itself. Kept out of the
// Teams page on purpose: an invited user may not have can_see_teams, so /teams
// would redirect them away before they could act.
export function AcceptInvitationDialog({ item, onClose }: AcceptInvitationDialogProps) {
  const { session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const [pending, setPending] = useState<null | "accept" | "decline">(null);

  const token = item?.action.token ?? null;

  const refresh = (): void => {
    queryClient.invalidateQueries({ queryKey: NOTIFICATIONS_KEY });
    queryClient.invalidateQueries({ queryKey: ["teams"] });
  };

  const resolve = async (mode: "accept" | "decline"): Promise<void> => {
    if (!token) return;
    setPending(mode);
    try {
      if (mode === "accept") await acceptTeamInvitation(token, supabaseToken);
      else await declineTeamInvitation(token, supabaseToken);
      toast.success(mode === "accept" ? "Invitation accepted" : "Invitation declined");
      refresh();
      onClose();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : `Failed to ${mode} invitation`);
    } finally {
      setPending(null);
    }
  };

  return (
    <Dialog open={item !== null} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[440px]">
        <DialogTitle>Team invitation</DialogTitle>
        <p className="text-sm text-foreground">{item?.title ?? "You've been invited to a team."}</p>
        <p className="text-sm text-muted-foreground">
          {item?.actor ? `Invited by ${item.actor}. ` : ""}
          Accepting adds you to the team — you can leave at any time.
        </p>
        <div className="flex items-center justify-end gap-2 pt-2">
          <Button
            type="button"
            variant="ghost"
            onClick={() => resolve("decline")}
            disabled={pending !== null}
            className="gap-1.5"
          >
            {pending === "decline" && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
            Decline
          </Button>
          <Button
            type="button"
            onClick={() => resolve("accept")}
            disabled={pending !== null}
            className="gap-1.5"
          >
            {pending === "accept" && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
            Accept
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}
