import { useQuery } from "@tanstack/react-query";
import { type ConceptData, ConceptService } from "@/features/concepts/api";

interface UseOntologyConceptsReturn {
  concepts: ConceptData[];
  isLoading: boolean;
  error: Error | null;
}

/**
 * Concepts for an arbitrary project (unlike useConcepts, which is hard-wired
 * to the currently-open project). Fetches lazily: pass enabled=false while
 * the project's group is collapsed.
 */
export function useOntologyConcepts(
  ontologyId: string | null,
  scope: string,
  enabled: boolean,
): UseOntologyConceptsReturn {
  const query = useQuery({
    queryKey: ["gx-project-concepts", ontologyId, scope],
    queryFn: () => ConceptService.listConcepts(ontologyId ?? "", scope),
    enabled: enabled && Boolean(ontologyId),
    staleTime: 30_000,
  });

  return {
    concepts: query.data ?? [],
    isLoading: query.isLoading,
    error: query.error,
  };
}
