import { LogOut, MoreVertical, Share2 } from "lucide-react";
import type React from "react";
import { useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import { generateHomeUrl } from "@/shared/utils/navigationUtils";
import { useSharedOntologyContext } from "../hooks/useSharedOntologyContext";
import { useShareInbox } from "../hooks/useShareInbox";

// Small visual indicator + menu shown next to the project name in the editor header
// when the current project was shared with the user. Renders nothing for owned projects,
// so it's safe to drop into any header layout unconditionally.
//
// Actions:
//   - Leave share: drops the local token and navigates the user back to their home.
//     The inbox React Query cache invalidation rolls through useProjects automatically,
//     so the project disappears from pickers without a manual refresh.
export const SharedOntologyBanner: React.FC = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { isShared, sharedBy, shareRole, shareId } = useSharedOntologyContext();
  const { leave, isLeaving } = useShareInbox();

  const handleLeave = useCallback(async (): Promise<void> => {
    if (!shareId) return;
    try {
      await leave(shareId);
      toast.success("Left shared ontology");
      // After leaving, any further request to this ontology_id would 401/403 — route the
      // user home immediately rather than letting the editor try and fail.
      navigate(generateHomeUrl(user));
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to leave share";
      toast.error(message);
    }
  }, [leave, shareId, navigate, user]);

  if (!isShared || !sharedBy || !shareRole) return null;

  const ownerLabel = `${sharedBy.username}@${sharedBy.organization}`;

  return (
    <div className="flex shrink-0 items-center gap-1.5 rounded-md border border-border bg-muted/30 px-2 py-1">
      <Share2 className="h-3 w-3 text-muted-foreground" />
      <span className="text-xs text-muted-foreground">
        Shared by <span className="font-medium text-foreground">{ownerLabel}</span>
      </span>
      <Badge variant="outline" className="capitalize">
        {shareRole}
      </Badge>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            type="button"
            variant="ghost"
            size="iconSm"
            className="h-6 w-6"
            title="Share options"
          >
            <MoreVertical className="h-3 w-3" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem
            className="gap-2 text-destructive focus:text-destructive"
            onClick={handleLeave}
            disabled={isLeaving}
          >
            <LogOut className="h-3.5 w-3.5" />
            Leave share
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
};

export default SharedOntologyBanner;
