import { ReasoningService } from "@/features/concept-editor/api/reasoningService";
import { BaseClient } from "@/shared/lib/BaseClient";

/**
 * Client for code-related operations (compilation, reasoning, visualization)
 */
export class CodeClient extends BaseClient {
  async compile(ontology: string): Promise<boolean> {
    return ReasoningService.compile(ontology);
  }

  async reason(
    vadalogProgram: string,
    toExplain: boolean = false,
    toEmbed: boolean = false,
  ): Promise<any> {
    return ReasoningService.reason(vadalogProgram, toExplain, toEmbed);
  }

  async generateCode(prompt: string, code: string): Promise<any> {
    return await this.post("/generate_code", {
      prompt,
      code,
    });
  }

  async buildBindAnnotation(
    bindAnnotation: string,
    predicateName: string,
    isOutput: boolean = false,
  ): Promise<string> {
    try {
      const response = await this.post("/vadalog/build-bind", {
        bindAnnotation,
        predicateName,
        isOutput,
      });
      if (response.status === "success" && response.data?.annotation) {
        return response.data.annotation;
      }
      return "";
    } catch {
      return "";
    }
  }

  async analyzeCode(
    program: string,
    conceptType?: string,
    conceptName?: string,
  ): Promise<{
    inputPredicates: string[];
    /** For llm concepts: the `{{name}}` references that match no project concept. */
    unresolvedReferences: string[];
    headPredicates: string[];
    headPredicateTerms: Record<string, string[]>;
  }> {
    const empty = {
      inputPredicates: [],
      unresolvedReferences: [],
      headPredicates: [],
      headPredicateTerms: {},
    };
    try {
      const payload: any = { program };
      if (conceptType && conceptType !== "logic") {
        payload.conceptType = conceptType;
        payload.conceptName = conceptName || "";
        payload.ontologyId = sessionStorage.getItem("currentOntologyId") || "";
        payload.ontologyScope = sessionStorage.getItem("currentOntologyScope") || "user";
      }
      const response = await this.post("/vadalog/analyze", payload);
      if (response.status === "success" && response.data) {
        return {
          inputPredicates: response.data.inputPredicates || [],
          unresolvedReferences: response.data.unresolvedReferences || [],
          headPredicates: response.data.headPredicates || [],
          headPredicateTerms: response.data.headPredicateTerms || {},
        };
      }
      return empty;
    } catch {
      return empty;
    }
  }

  async parseBinds(
    program: string,
    outputPredicate: string,
  ): Promise<{
    code: string;
    binds: {
      input: {
        predicate: string;
        annotation: string;
        path?: string;
        table_name?: string;
        datasource_type?: string;
      }[];
      output: {
        predicate: string;
        annotation: string;
        path?: string;
        table_name?: string;
        datasource_type?: string;
      }[];
    };
  }> {
    try {
      const response = await this.post("/vadalog/parse-binds", {
        program,
        outputPredicate,
      });
      if (response.status === "success" && response.data) {
        return {
          code: response.data.code ?? "",
          binds: response.data.binds ?? { input: [], output: [] },
        };
      }
      return { code: "", binds: { input: [], output: [] } };
    } catch {
      return { code: "", binds: { input: [], output: [] } };
    }
  }
}
