import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

// Full-screen, interaction-blocking overlay shown while the backend engine is
// still provisioning (typically right after a brand-new account is created, the
// user can authenticate but their environment isn't ready yet). It replaces the
// old toast: a toast is dismissible and lets the user click into an app that
// can't work yet, whereas this blocks the whole UI and auto-dismisses once the
// engine reports ready (see useEngineProvisioning) — no manual refresh needed.
export const EngineProvisioningOverlay = () => {
  return (
    <div
      role="status"
      aria-live="polite"
      className="fixed inset-0 z-[100] flex flex-col items-center justify-center gap-6 bg-background/95 px-6 text-center backdrop-blur-sm"
    >
      <PrometheuxSpinner size={64} className="text-primary" />
      <div className="max-w-md space-y-3">
        <h2 className="text-xl font-semibold text-foreground">Setting up your environment</h2>
        <p className="text-sm leading-relaxed text-muted-foreground">
          We're provisioning your workspace — a one-time setup that takes a moment. As soon as it's
          ready you'll be able to start working.
        </p>
        <p className="text-xs text-muted-foreground">
          No need to refresh; this screen updates automatically when your environment is ready.
        </p>
      </div>
    </div>
  );
};
