import { useEffect } from "react";
import { ensureEngineReady } from "../engineStatus";
import { useEngineStatusStore } from "../engineStatusStore";

const POLL_INTERVAL_MS = 4000;

// Drives the provisioning overlay. While the engine is "unavailable" (and the
// user is authenticated) it re-probes /livez on an interval; ensureEngineReady
// flips the store to "ready" on the first successful probe, which clears the
// overlay and tears down the interval automatically. Returns whether the
// blocking overlay should currently be shown.
export function useEngineProvisioning(active: boolean): boolean {
  const status = useEngineStatusStore((state) => state.status);
  const isProvisioning = active && status === "unavailable";

  useEffect(() => {
    if (!isProvisioning) return;

    let cancelled = false;
    const probe = () => {
      if (!cancelled) void ensureEngineReady();
    };
    const intervalId = window.setInterval(probe, POLL_INTERVAL_MS);

    return () => {
      cancelled = true;
      window.clearInterval(intervalId);
    };
  }, [isProvisioning]);

  return isProvisioning;
}
