export type NotificationType = "project_share" | "team_invitation";

// Routing hints the backend attaches so the FE knows where to send the user.
export interface NotificationAction {
  kind: NotificationType;
  ontology_id?: string;
  share_role?: string;
  team_id?: string;
  token?: string;
  role?: string;
}

export interface NotificationItem {
  id: string; // `${type}:${entity_id}` — stable across polls
  type: NotificationType;
  entity_id: string;
  title: string;
  actor: string | null;
  created_at: string | null;
  read: boolean;
  action: NotificationAction;
}

export interface NotificationsPayload {
  items: NotificationItem[];
  unread_count: number;
}

// Single error class for the feature (mirrors TeamError / ShareError).
export class NotificationError extends Error {
  httpStatus: number;
  constructor(message: string, httpStatus: number) {
    super(message);
    this.name = "NotificationError";
    this.httpStatus = httpStatus;
  }
}
