import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

const AGENT_MESSAGE_USAGE_KEY = "agent-message-usage";

export interface AgentMessageUsage {
  isFreemium: boolean;
  used: number;
  limit: number;
  remaining: number | null;
  resetsAt: string;
  unlimited: boolean;
}

export interface UseAgentMessageUsageResult {
  usage: AgentMessageUsage | undefined;
  isLoading: boolean;
  isError: boolean;
  error: Error | null;
  refetch: () => void;
}

interface RawAgentMessageUsage {
  is_freemium: boolean;
  used: number;
  limit: number;
  remaining: number | null;
  resets_at: string;
  unlimited: boolean;
}

const isRawUsage = (value: unknown): value is RawAgentMessageUsage => {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.is_freemium === "boolean" &&
    typeof v.used === "number" &&
    typeof v.limit === "number" &&
    typeof v.resets_at === "string" &&
    typeof v.unlimited === "boolean"
  );
};

const fetchAgentMessageUsage = async (authToken: string): Promise<AgentMessageUsage> => {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/agent/message-usage`;
  const data = await HttpService.get(url, authToken);
  if (!isRawUsage(data)) {
    throw new Error("Unexpected response shape from /agent/message-usage");
  }
  return {
    isFreemium: data.is_freemium,
    used: data.used,
    limit: data.limit,
    remaining: typeof data.remaining === "number" ? data.remaining : null,
    resetsAt: data.resets_at,
    unlimited: data.unlimited,
  };
};

export const useAgentMessageUsage = (): UseAgentMessageUsageResult => {
  const { authToken, user } = useAuth();
  const userId = user?.id;
  // Reactive, so the query starts as soon as signing in produces a token.
  const token = authToken ?? "";

  const query = useQuery({
    queryKey: [AGENT_MESSAGE_USAGE_KEY, userId],
    queryFn: () => fetchAgentMessageUsage(token),
    enabled: Boolean(token),
    staleTime: 30_000,
  });

  return {
    usage: query.data,
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
    refetch: () => {
      query.refetch();
    },
  };
};

export const AGENT_MESSAGE_USAGE_QUERY_KEY = AGENT_MESSAGE_USAGE_KEY;
