import { useCallback } from "react";
import { useNavigate } from "react-router-dom";

import { useAuth } from "@/features/auth/components/AuthProvider";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";
import { generateEditorUrl } from "@/shared/utils/navigationUtils";

import { parseConceptNodeId } from "../../types";

export interface UseOpenGraphNodeReturn {
  /** Navigate to the concept's project and open it in the Explorer. */
  openConcept: (conceptNodeId: string) => void;
  /** Navigate to the project. */
  openOntology: (ontologyId: string) => void;
}

/**
 * Click-through for concept/project endpoints on the Context page
 * (decision 7): a concept link opens its owning project with the concept
 * focused in the Explorer; a project link opens the project.
 */
export function useOpenGraphNode(): UseOpenGraphNodeReturn {
  const navigate = useNavigate();
  const { user } = useAuth();

  const openConcept = useCallback(
    (nodeId: string) => {
      const ref = parseConceptNodeId(nodeId);
      if (!ref) return;
      // The editor consumes pendingLineageFocus once mounted and opens the
      // concept's cell in the dock — same flow the library sidebar uses.
      useEditorActionsStore.getState().register({ pendingLineageFocus: ref.conceptName });
      navigate(generateEditorUrl(user, ref.ontologyId), { state: { activeTab: "lineage" } });
    },
    [navigate, user],
  );

  const openOntology = useCallback(
    (ontologyId: string) => {
      navigate(generateEditorUrl(user, ontologyId), { state: { activeTab: "lineage" } });
    },
    [navigate, user],
  );

  return { openConcept, openOntology };
}
