import type { ContextNote, ContextScope, ContextShelf } from "../types";
import { shelfOf } from "../types";

/** A sidebar root — Global or one project ("vault" in the Obsidian sense). */
export interface VaultRef {
  scope: ContextScope;
  scopeId: string | null;
  name: string;
}

/** Stable identity for a vault, for keying per-vault UI state. */
export function vaultKey(vault: VaultRef): string {
  return `${vault.scope}:${vault.scopeId ?? ""}`;
}

export interface FolderNode {
  /** Normalized path, e.g. "research/interviews". */
  path: string;
  /** Last path segment, e.g. "interviews". */
  name: string;
  children: FolderNode[];
}

/** Document chunks presented as one item — users see documents, never chunks. */
export interface DocumentGroup {
  documentId: string;
  filename: string;
  chunkCount: number;
  useCount: number;
  lastUsedAt: string | null;
  notes: ContextNote[];
}

export type NotesSelection =
  | { type: "none" }
  | { type: "note"; noteId: string }
  | { type: "document"; documentId: string }
  /** A vault or folder title was clicked — center shows its notes as cards.
   *  folderPath "" = the whole vault. */
  | { type: "collection"; folderPath: string }
  /** Draft note being written — nothing is persisted until Save. */
  | { type: "new" };

const TITLE_MAX_CHARS = 120;

/** Titles come from prose — drop emphasis/code markers and unwrap
 *  `[[target]]` / `[[target|label]]` wikilinks to their display text. */
function stripInlineMarkdown(line: string): string {
  return line
    .replace(/\[\[([^\][|\n]+)(?:\|([^\][\n]+))?\]\]/g, (_, target, label) => label ?? target)
    .replace(/[*_`]{1,3}/g, "")
    .trim();
}

/** Mirrors the backend's derive_title: first non-empty line, markdown stripped. */
export function deriveTitleFromText(text: string): string {
  const lines = (text ?? "").split("\n");
  for (const line of lines) {
    const candidate = stripInlineMarkdown(line.trim().replace(/^#+/, "").trim());
    if (candidate) return candidate.slice(0, TITLE_MAX_CHARS);
  }
  return (text ?? "").trim().slice(0, TITLE_MAX_CHARS);
}

export function noteDisplayTitle(note: Pick<ContextNote, "title" | "text">): string {
  return note.title?.trim() || deriveTitleFromText(note.text) || "Untitled";
}

/** A stored title equal to the body's first line was auto-derived at write time
 *  rather than chosen by an author, so it may keep tracking the body. */
export function isDerivedTitle(note: Pick<ContextNote, "title" | "text">): boolean {
  const stored = note.title?.trim();
  return !stored || stored === deriveTitleFromText(note.text);
}

/** Title for an open note: an author-chosen title stays put, while an
 *  auto-derived one follows the draft's first line as it is edited. */
export function editorDisplayTitle(
  note: Pick<ContextNote, "title" | "text">,
  draft: string,
): string {
  if (!isDerivedTitle(note)) return note.title?.trim() ?? "";
  return deriveTitleFromText(draft) || "Untitled";
}

export function normalizeFolderPath(raw: string | null | undefined): string {
  if (!raw) return "";
  return raw
    .split("/")
    .map((segment) => segment.trim())
    .filter(Boolean)
    .join("/");
}

/** Build a nested tree from folder paths (notes' folder_path + locally created folders). */
export function buildFolderTree(folderPaths: Array<string | null | undefined>): FolderNode[] {
  const roots: FolderNode[] = [];
  const byPath = new Map<string, FolderNode>();

  const ensureNode = (path: string): FolderNode => {
    const existing = byPath.get(path);
    if (existing) return existing;
    const segments = path.split("/");
    const node: FolderNode = { path, name: segments[segments.length - 1], children: [] };
    byPath.set(path, node);
    if (segments.length === 1) {
      roots.push(node);
      return node;
    }
    const parent = ensureNode(segments.slice(0, -1).join("/"));
    parent.children.push(node);
    return node;
  };

  const uniquePaths = new Set(folderPaths.map(normalizeFolderPath).filter(Boolean));
  [...uniquePaths].sort().forEach(ensureNode);
  return roots;
}

/** Notes sitting directly in a folder ("" = vault root). */
export function notesInFolder(notes: ContextNote[], folderPath: string): ContextNote[] {
  return notes.filter((note) => normalizeFolderPath(note.folder_path) === folderPath);
}

/** Every folder path used by the notes, ancestors included, sorted. */
export function collectFolderPaths(notes: ContextNote[]): string[] {
  const paths = new Set<string>();
  for (const note of notes) {
    const path = normalizeFolderPath(note.folder_path);
    if (!path) continue;
    const segments = path.split("/");
    for (let depth = 1; depth <= segments.length; depth++) {
      paths.add(segments.slice(0, depth).join("/"));
    }
  }
  return [...paths].sort();
}

/** Notes in a folder and all its subfolders ("" = every note in the vault). */
export function notesUnderFolder(notes: ContextNote[], folderPath: string): ContextNote[] {
  if (!folderPath) return notes;
  const prefix = `${folderPath}/`;
  return notes.filter((note) => {
    const path = normalizeFolderPath(note.folder_path);
    return path === folderPath || path.startsWith(prefix);
  });
}

interface GroupedNotes {
  documents: DocumentGroup[];
  standalone: ContextNote[];
}

/** Split document_chunk notes into per-document groups; everything else passes through. */
export function groupDocumentChunks(notes: ContextNote[]): GroupedNotes {
  const documents = new Map<string, DocumentGroup>();
  const standalone: ContextNote[] = [];

  for (const note of notes) {
    if (note.kind !== "document_chunk") {
      standalone.push(note);
      continue;
    }
    const documentId = note.source_meta?.document_id ?? note.id;
    const group = documents.get(documentId) ?? {
      documentId,
      filename: note.source_meta?.filename ?? noteDisplayTitle(note),
      chunkCount: 0,
      useCount: 0,
      lastUsedAt: null,
      notes: [],
    };
    group.chunkCount += 1;
    group.useCount += note.use_count;
    group.notes.push(note);
    if (note.last_used_at && (!group.lastUsedAt || note.last_used_at > group.lastUsedAt)) {
      group.lastUsedAt = note.last_used_at;
    }
    documents.set(documentId, group);
  }

  return { documents: [...documents.values()], standalone };
}

/** Display name of the virtual folder that collects auto-generated notes. */
export const AUTO_GENERATED_FOLDER_LABEL = "Auto-generated";

/** Auto-generated source observations written by the backend when a data
 *  source is connected. They carry a "[Source ID: <hash>]" text prefix. We
 *  group them out of the vault root so they don't bury hand-written notes.
 *  Detection is client-side only — nothing about the note is mutated. */
export function isAutoGeneratedNote(note: Pick<ContextNote, "text">): boolean {
  return (note.text ?? "").trimStart().startsWith("[Source ID:");
}

export function filterByShelf(notes: ContextNote[], shelf: ContextShelf | null): ContextNote[] {
  if (!shelf) return notes;
  return notes.filter((note) => shelfOf(note) === shelf);
}

export function chunkIndexOf(sourceMeta: { chunk_index?: number } | null): number {
  return typeof sourceMeta?.chunk_index === "number" ? sourceMeta.chunk_index : Number.MAX_VALUE;
}

export function orderedChunksOf(group: DocumentGroup): ContextNote[] {
  return [...group.notes].sort((a, b) => chunkIndexOf(a.source_meta) - chunkIndexOf(b.source_meta));
}

/** The chunk that stands in for a whole document (link target, graph node). */
export function representativeChunkOf(group: DocumentGroup): ContextNote {
  return orderedChunksOf(group)[0];
}

/** How a note is named when linking or graphing: documents go by filename. */
export function linkDisplayTitle(note: ContextNote): string {
  if (note.kind === "document_chunk") {
    return note.source_meta?.filename ?? noteDisplayTitle(note);
  }
  return noteDisplayTitle(note);
}

export interface LinkTarget {
  id: string;
  title: string;
}

/** `[[concept:name]]` targets for a project vault's concepts (phase 4). */
export function buildConceptLinkTargets(conceptNames: string[]): LinkTarget[] {
  return conceptNames.map((name) => ({
    id: `concept:${name}`,
    title: `concept:${name}`,
  }));
}

/** What `[[` offers: standalone notes by title, documents once by filename. */
export function buildLinkTargets(notes: ContextNote[], excludeId?: string): LinkTarget[] {
  const { documents, standalone } = groupDocumentChunks(notes);
  return [
    ...standalone.map((note) => ({ id: note.id, title: noteDisplayTitle(note) })),
    ...documents.map((group) => ({
      id: representativeChunkOf(group).id,
      title: group.filename,
    })),
  ].filter((target) => target.id !== excludeId);
}

export function formatRelativeTime(iso: string | null): string {
  if (!iso) return "";
  const then = new Date(iso).getTime();
  if (Number.isNaN(then)) return "";
  const days = Math.floor((Date.now() - then) / (24 * 60 * 60 * 1000));
  if (days <= 0) return "today";
  if (days === 1) return "yesterday";
  if (days < 30) return `${days} days ago`;
  return new Date(iso).toLocaleDateString(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

/** Per-item usage line: the shelf's one-line promise made concrete. */
export function formatUsage(
  note: Pick<ContextNote, "activation" | "use_count" | "last_used_at">,
): string {
  if (note.activation === "always") return "Applied to every request";
  if (note.activation === "on_demand") return "Listed every request · fetched on demand";
  if (note.use_count <= 0) return "Never used";
  const lastUsed = formatRelativeTime(note.last_used_at);
  return lastUsed ? `Used ${note.use_count}× · last used ${lastUsed}` : `Used ${note.use_count}×`;
}

/** Rough token estimate (~4 chars/token) shown as the cost of an always-rule. */
export function estimateTokens(text: string): number {
  return Math.ceil((text ?? "").length / 4);
}
