import { Lightbulb } from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";

import { parseFreemiumLimit } from "@/features/billing/utils/freemiumLimit";
import { ContextNoteApi } from "@/features/context-layer/api";
import { CompanyContextTextPanel } from "@/features/onboarding/components/CompanyContextTextPanel";
import { CompanyContextUploadPanel } from "@/features/onboarding/components/CompanyContextUploadPanel";
import { useContextUpload } from "@/features/onboarding/hooks/useContextUpload";
import type { WizardControls } from "@/shared/components/wizard/useWizardState";
import { WizardStep } from "@/shared/components/wizard/WizardStep";

interface CompanyContextStepProps {
  controls: WizardControls;
}

const MIN_CHARS = 20;

export function CompanyContextStep({ controls }: CompanyContextStepProps) {
  const [text, setText] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const { attachments, attach, remove, readyPaths, isUploading } = useContextUpload();

  const trimmed = text.trim();
  const hasValidText = trimmed.length >= MIN_CHARS;
  const hasReadyFiles = readyPaths.length > 0;
  const canSave = !isSaving && !isUploading && (hasValidText || hasReadyFiles);

  const saveOps = useMemo(() => {
    const ops: Array<{ label: string; run: () => Promise<unknown> }> = [];
    if (hasValidText) {
      ops.push({
        label: "context note",
        run: () =>
          ContextNoteApi.create({
            scope: "global",
            scope_id: null,
            kind: "fact",
            text: trimmed,
          }),
      });
    }
    for (const path of readyPaths) {
      ops.push({
        label: path,
        run: () =>
          ContextNoteApi.createFromFile({
            scope: "global",
            scope_id: null,
            file_path: path,
          }),
      });
    }
    return ops;
  }, [hasValidText, trimmed, readyPaths]);

  const handleSave = async () => {
    if (!canSave || saveOps.length === 0) return;
    setIsSaving(true);
    const results = await Promise.allSettled(saveOps.map((op) => op.run()));
    const rejected = results.filter((r): r is PromiseRejectedResult => r.status === "rejected");

    // A freemium embedding-cap 402 already opened the shared upgrade wall (from
    // the ContextNoteApi layer). Stop here without a redundant error toast.
    const hitFreemiumLimit = rejected.some((r) => parseFreemiumLimit(r.reason) !== null);
    if (hitFreemiumLimit) {
      setIsSaving(false);
      return;
    }

    if (rejected.length === 0) {
      toast.success("Saved to your global context");
      controls.goNext();
    } else if (rejected.length === results.length) {
      toast.error("Nothing could be saved — please try again");
    } else {
      const noun = rejected.length === 1 ? "item" : "items";
      toast.warning(`Saved with ${rejected.length} ${noun} that failed — continuing`);
      controls.goNext();
    }
    setIsSaving(false);
  };

  const primaryLabel = isSaving ? "Saving…" : "Save and continue";
  const inputsDisabled = isSaving;

  return (
    <WizardStep
      controls={controls}
      title="Tell us about your work"
      description="A short paragraph or two about your company, your role, and the kinds of questions you'll want help with — and/or upload any documents we should remember. We'll keep this in mind on every future turn."
      primaryAction={{
        label: primaryLabel,
        onClick: handleSave,
        disabled: !canSave,
      }}
    >
      <div className="space-y-4">
        <div className="flex items-start gap-2 rounded-md border border-primary/30 bg-primary/5 p-3 text-xs text-muted-foreground">
          <Lightbulb className="mt-0.5 h-3.5 w-3.5 shrink-0 text-primary" />
          <p>
            Think of it like briefing a new teammate.{" "}
            <span className="font-medium text-foreground">Good to type:</span> team conventions
            (fiscal year, default currency, what "active customer" means), domain jargon, and known
            gotchas. <span className="font-medium text-foreground">Good to upload:</span>{" "}
            glossaries, data dictionaries, internal handbooks, style guides, or policy docs —
            anything narrative the assistant should learn from.
          </p>
        </div>

        <CompanyContextTextPanel
          value={text}
          onChange={setText}
          disabled={inputsDisabled}
          minChars={MIN_CHARS}
        />

        <CompanyContextUploadPanel
          attachments={attachments}
          onPick={attach}
          onRemove={remove}
          disabled={inputsDisabled}
        />
      </div>
    </WizardStep>
  );
}
