/**
 * Shared helpers for classifying a cell's run outcome.
 *
 * A user-initiated stop is reported by the backend (both Vadalog and Python
 * concepts) with this exact message. The UI treats it as a non-fatal warning
 * rather than a hard error.
 */
export const EXECUTION_STOPPED_MESSAGE = "Execution stopped by user.";

export function isStoppedByUser(error?: string | null): boolean {
  return error?.trim() === EXECUTION_STOPPED_MESSAGE;
}

interface RunStatusDotInput {
  isRunning?: boolean;
  isWaitingForEngine?: boolean;
  error?: string | null;
}

/** Tailwind color class for the small per-cell run-status indicator dot. */
export function runStatusDotClass({
  isRunning,
  isWaitingForEngine,
  error,
}: RunStatusDotInput): string {
  if (isWaitingForEngine) return "bg-amber-500 animate-pulse";
  if (isRunning) return "bg-blue-500 animate-pulse";
  if (isStoppedByUser(error)) return "bg-yellow-500";
  if (error) return "bg-red-500";
  return "bg-green-500";
}
