// Concept cell types. "logic" = Vadalog, "sql" = SQL, "cypher" = Cypher,
// "python" = a Python script whose main() returns the concept's tabular output,
// "context" = a non-executable concept that pins notes and, when run, exposes
// them as a uniform note table + a context window,
// "llm" = a generative concept whose body is a prompt template ({{name}}
// placeholders reference upstream concepts) materializing an LLM response
// as a typed table.
export type ConceptType = "logic" | "sql" | "cypher" | "python" | "context" | "llm";

// Every type whose concept name is authored, not derived from a Vadalog rule
// head. Save and run must agree on this set: a run saves the cell first, and a
// save that treats a named concept as Vadalog sends the wrong payload (for
// context and llm, one that drops their concept_config).
const NAMED_CONCEPT_TYPES: readonly ConceptType[] = ["sql", "cypher", "python", "context", "llm"];

export function requiresConceptName(conceptType: ConceptType | undefined): boolean {
  return !!conceptType && NAMED_CONCEPT_TYPES.includes(conceptType);
}

// Order by item for column sorting
export interface OrderByItem {
  position: number;
  direction: "asc" | "desc";
}

export type FilterOperator =
  | "contains"
  | "equals"
  | "not_equals"
  | "greater_than"
  | "less_than"
  | "greater_than_or_equal"
  | "less_than_or_equal"
  | "starts_with"
  | "ends_with"
  | "is_null"
  | "is_not_null";

export interface ColumnFilterValue {
  value: string;
  operator: FilterOperator;
}

export interface BindEntry {
  predicate: string;
  annotation: string;
  predicate_name?: string;
  datasource_type?: string;
  path?: string;
  table_name?: string;
}

export interface CellBinds {
  input: BindEntry[];
  output: BindEntry[];
}

// A context concept is either "static" (a pinned note set) or "dynamic" (a saved
// semantic query re-evaluated every run).
export type ContextMode = "static" | "dynamic";

// Config bag for a context concept, sent to the backend as `concept_config` on
// save and restored from the concepts-list read path. Static uses `note_ids`;
// dynamic uses `query` (+ optional `top_k`/`kinds`).
export interface ContextConceptConfig {
  mode: ContextMode;
  note_ids?: string[];
  query?: string;
  top_k?: number | null;
  kinds?: string[] | null;
}

// One declared output column of an llm concept.
export interface LlmOutputColumn {
  name: string;
  type: string;
}

// Config bag for an llm concept, sent to the backend as `concept_config` on
// save and restored from the concepts-list read path. When `output_columns`
// is set the model is held to a JSON-array contract and the output table has
// exactly those columns; otherwise the output is a single `response` column.
// The remaining fields are optional per-concept overrides of the user's LLM
// settings.
/**
 * Non-secret description of the pinned connection, stored on the concept so a
 * reader who does not have that connection — a share recipient, an import — can
 * be told what to configure. Advisory: nothing resolves from it, and it goes
 * stale if the connection is later edited.
 */
export interface LlmConnectionHint {
  provider?: string | null;
  model?: string | null;
}

/**
 * What one referenced upstream contributed to the last run. The prompt's own
 * omission marker is read by the model; this is how the author finds out that
 * an answer was reasoned over a capped view of the data.
 */
export interface LlmInputSummary {
  ref: string;
  concept_type: string;
  /** "rows" for a tabular upstream, "notes" for a context one. */
  unit: string;
  sent: number;
  total: number;
  truncated: boolean;
}

/**
 * What the model did not see, and what it did not finish saying.
 *
 * Both ends of a run can be cut without any error being raised: the assembled
 * prompt can overflow the model's context window, and the answer can stop at the
 * `max_tokens` ceiling mid-sentence. Neither is visible in the output itself --
 * a truncated answer looks exactly like a complete one.
 */
export interface LlmRunTruncation {
  /** Set when part of the prompt was dropped to fit the context window. */
  prompt?: {
    sent_tokens: number;
    total_tokens: number;
    dropped_tokens: number;
    context_window: number;
  } | null;
  /** True when the answer was cut short by the token ceiling. */
  output: boolean;
  /** The ceiling that cut it, so the message can name the number to raise. */
  maxTokens?: number | null;
}

export interface LlmConceptConfig {
  output_columns?: LlmOutputColumn[] | null;
  provider?: string | null;
  model?: string | null;
  /** Name of a saved LLM connection (Settings) used as this concept's base. */
  connection?: string | null;
  connection_hint?: LlmConnectionHint | null;
  temperature?: number | null;
  max_tokens?: number | null;
  row_limit?: number | null;
}

export interface ConceptCell {
  id: string;
  code: string;
  result: null | {
    type: "query-result";
    data: Record<
      string,
      {
        columns: string[];
        rows: any[][];
        pagination?: {
          page: number;
          totalPages: number;
          hasNext: boolean;
          hasPrev: boolean;
          totalCount: number;
          pageSize?: number;
          orderBy?: OrderByItem[];
        };
        searchState?: {
          searchTerm: string;
          columnPositions?: number[];
          columnFilters?: Record<number, ColumnFilterValue>;
        };
        fetchElapsedTime?: number;
      }
    >;
    runElapsedTime?: number;
  };
  isRunning: boolean;
  // True while a run is parked waiting for the (globally single-threaded) engine
  // to free up. It auto-retries until the engine is available, the run proceeds,
  // or the user cancels. Distinct from isRunning so the UI shows a neutral
  // "waiting" state rather than a spinner labelled "Running".
  isWaitingForEngine?: boolean;
  error?: string;
  cellBackendId?: string;
  isModified?: boolean;
  needsSave?: boolean;
  lastSavedContent?: string;
  loadingPredicates?: string[];
  hasPersistedResults?: boolean;
  outputPredicate?: string;
  // True once the user has explicitly chosen the output predicate from the
  // dropdown (or a saved value was loaded). While false, the default keeps
  // tracking the last parsed predicate as the user writes the code.
  outputPredicateUserSet?: boolean;
  description?: string;
  autoOpen?: boolean;
  dataCode?: string;
  useDatabricks?: boolean;
  databricksJobInfo?: Record<string, any> | null;
  group?: string;
  conceptType?: ConceptType;
  executionTime?: number;
  binds?: CellBinds;
  isSaving?: boolean;
  readOnly?: boolean;
  // Context concepts (conceptType === "context"). Static mode pins a set of notes
  // (noteIds); dynamic mode stores a semantic query (contextQuery) re-evaluated
  // every run. These round-trip through concept_config on save/load.
  contextMode?: ContextMode;
  noteIds?: string[];
  contextQuery?: string;
  contextTopK?: number;
  contextKinds?: string[];
  // LLM concepts (conceptType === "llm"). The prompt template lives in `code`;
  // this bag carries the declared output columns and model overrides. It
  // round-trips through concept_config on save/load.
  llmConfig?: LlmConceptConfig;
  // How much of each referenced upstream the last run actually sent. Run
  // metadata, not saved state: an upstream can outgrow the row budget without
  // the concept changing, so this is only ever as current as the last run.
  llmInputs?: LlmInputSummary[];
  // Whether the last run lost either end of the exchange. Run metadata for the
  // same reason as llmInputs: it describes one run, not the saved concept.
  llmTruncation?: LlmRunTruncation;
}

// ── Evaluation policies ──────────────────────────────────────────────

export interface CronTriggerConfig {
  cron_expression: string;
  timezone: string;
}

export interface DataChangeTriggerConfig {
  check_interval_minutes: number;
}

export type TriggerType = "cron" | "data_change";

export interface EvaluationPolicy {
  policy_id: string;
  ontology_id: string;
  concept_name: string;
  trigger_type: TriggerType;
  trigger_config: CronTriggerConfig | DataChangeTriggerConfig;
  scope: string;
  enabled: boolean;
  created_by: string;
  created_at: string;
  updated_at: string;
  last_run_at: string | null;
  last_run_status: "success" | "error" | null;
  last_run_error: string | null;
}

export interface PolicyRun {
  run_id: string;
  policy_id: string;
  ontology_id: string;
  concept_name: string;
  trigger_type: string;
  started_at: string;
  finished_at: string | null;
  status: "running" | "success" | "error";
  error_message: string | null;
  result_summary: Record<string, unknown> | null;
}
