import { matchPath } from "react-router-dom";

/** Prefix shown on every browser tab / history entry. */
export const APP_TITLE = "Prometheux";

/**
 * Static route patterns mapped to the label appended after `${APP_TITLE}: `.
 * Order matters — the first pattern that matches the pathname wins, so more
 * specific patterns must precede the catch-all `/:organization/:username` home
 * variant (which would otherwise match any two-segment path).
 */
const STATIC_TITLES: ReadonlyArray<{ pattern: string; label: string }> = [
  { pattern: "/login", label: "Login" },
  { pattern: "/reset-password", label: "Reset Password" },
  { pattern: "/reset-password/confirm", label: "Reset Password" },
  { pattern: "/mfa-challenge", label: "Multi-Factor Authentication" },
  { pattern: "/onboarding", label: "Onboarding" },
  { pattern: "/setup/company", label: "Company Setup" },
  { pattern: "/settings", label: "Settings" },
  { pattern: "/profile", label: "Profile" },
  { pattern: "/datasources", label: "Data Sources" },
  { pattern: "/ontologies", label: "Ontologies" },
  { pattern: "/compute", label: "Compute" },
  { pattern: "/apps", label: "Apps" },
  { pattern: "/", label: "Home" },
  { pattern: "/:organization/:username", label: "Home" },
];

/** Turn a URL slug like "sella-wealth" into a readable label like "Sella Wealth". */
function titleizeSlug(slug: string): string {
  return slug
    .split("-")
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

/** `${APP_TITLE}: Label (Name)`, or `${APP_TITLE}: Label` when the name is unknown. */
function withName(label: string, name?: string | null): string {
  if (!name) return `${APP_TITLE}: ${label}`;
  return `${APP_TITLE}: ${label} (${name})`;
}

function resolveStaticLabel(pathname: string): string | null {
  for (const { pattern, label } of STATIC_TITLES) {
    if (matchPath(pattern, pathname)) return label;
  }
  return null;
}

/** Resolved entity names for routes whose title includes a record's name. */
interface TitleEntities {
  ontologyName?: string | null;
  dashboardName?: string | null;
}

/**
 * Build the document title for a given route so each browser-history entry is
 * distinguishable (e.g. "Prometheux: Ontologies" instead of a repeated
 * "Prometheux"). The project editor and apps include the open record's
 * name, e.g. "Prometheux: App (Sales Overview)".
 */
export function buildDocumentTitle(pathname: string, entities: TitleEntities = {}): string {
  const isEditor =
    matchPath("/editor/:organization/:username/:id", pathname) !== null ||
    matchPath("/editor/:id", pathname) !== null;
  if (isEditor) return withName("Ontologies", entities.ontologyName);

  // The "new app" route must precede the parametric app matches, which would
  // otherwise capture it as ontologyId="new", id="edit".
  if (matchPath("/apps/new/edit", pathname)) return `${APP_TITLE}: New App`;
  // Dynamic apps: /apps/:ontologyId/:id — two segments.
  if (matchPath("/apps/:ontologyId/:id/edit", pathname)) {
    return withName("Edit App", entities.dashboardName);
  }
  if (matchPath("/apps/:ontologyId/:id", pathname)) {
    return withName("App", entities.dashboardName);
  }

  // Federated apps: /apps/:dashboardId — one segment.
  const appMatch = matchPath("/apps/:dashboardId", pathname);
  const dashboardId = appMatch?.params.dashboardId;
  if (dashboardId) return `${APP_TITLE}: ${titleizeSlug(dashboardId)}`;

  const label = resolveStaticLabel(pathname);
  if (!label) return APP_TITLE;
  return `${APP_TITLE}: ${label}`;
}
