import { ChevronDown } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import { cn } from "@/shared/lib/utils";
import { GRAPH_ANALYTICS, type GraphAnalyticsKey, getGraphAnalytics } from "../../graphAnalytics";
import { GRAPH_FUNCTIONS, type GraphFunctionKey, getGraphFunction } from "../../graphFunctions";
import type { ConceptGraphMode } from "../../hooks/useConceptGraph";

interface ConceptGraphModeBarProps {
  mode: ConceptGraphMode;
  analyticsKey: GraphAnalyticsKey | null;
  isBusy: boolean;
  onSelectRecords: () => void;
  onSelectFunction: (key: GraphFunctionKey) => void;
  onSelectAnalytics: (key: GraphAnalyticsKey) => void;
}

const PILL_BASE =
  "flex items-center gap-1 px-2.5 py-0.5 text-[11px] rounded transition-colors whitespace-nowrap";

function pillClass(active: boolean, isBusy: boolean): string {
  return cn(
    PILL_BASE,
    active
      ? "bg-background shadow-sm text-foreground"
      : "text-muted-foreground hover:text-foreground",
    isBusy && "opacity-50",
  );
}

export function ConceptGraphModeBar({
  mode,
  analyticsKey,
  isBusy,
  onSelectRecords,
  onSelectFunction,
  onSelectAnalytics,
}: ConceptGraphModeBarProps) {
  const isRecordsPlain = mode === "records" && analyticsKey === null;
  const activeFunction = mode === "records" ? null : getGraphFunction(mode);
  const activeAnalytics = analyticsKey ? getGraphAnalytics(analyticsKey) : null;

  return (
    <div className="flex items-center bg-muted/50 rounded-md p-0.5 flex-shrink-0">
      <button
        type="button"
        disabled={isBusy}
        onClick={onSelectRecords}
        className={pillClass(isRecordsPlain, isBusy)}
      >
        Records
      </button>

      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button
            type="button"
            disabled={isBusy}
            className={pillClass(activeFunction !== null, isBusy)}
          >
            {activeFunction ? activeFunction.label : "Graph functions"}
            <ChevronDown className="h-3 w-3" />
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start">
          {GRAPH_FUNCTIONS.map((fn) => (
            <DropdownMenuItem key={fn.key} onSelect={() => onSelectFunction(fn.key)}>
              {fn.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>

      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button
            type="button"
            disabled={isBusy}
            className={pillClass(activeAnalytics !== null, isBusy)}
          >
            {activeAnalytics ? activeAnalytics.label : "Analytics"}
            <ChevronDown className="h-3 w-3" />
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start">
          {GRAPH_ANALYTICS.map((fn) => (
            <DropdownMenuItem key={fn.key} onSelect={() => onSelectAnalytics(fn.key)}>
              {fn.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}
