import { Search, X } from "lucide-react";
import { useEffect, useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import type { ColumnFilterValue, TableSearchState } from "./tableOutput.types";
import { OPERATOR_LABELS } from "./tableOutput.utils";

interface TableOutputSearchProps {
  columns: string[];
  searchState?: TableSearchState;
  onSearch: (searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) => void;
  onClearSearch: () => void;
  onClearColumnFilter: (columnIndex: number) => void;
}

export function TableOutputSearch({
  columns,
  searchState,
  onSearch,
  onClearSearch,
  onClearColumnFilter,
}: TableOutputSearchProps) {
  const [draft, setDraft] = useState(searchState?.searchTerm ?? "");

  useEffect(() => {
    setDraft(searchState?.searchTerm ?? "");
  }, [searchState?.searchTerm]);

  const columnFilters = searchState?.columnFilters;
  const filterEntries = columnFilters ? Object.entries(columnFilters) : [];
  const hasGlobalSearch = !!searchState?.searchTerm;
  const hasColumnFilters = filterEntries.length > 0;
  const hasAnyActive = hasGlobalSearch || hasColumnFilters;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!draft.trim()) {
      if (hasGlobalSearch) onClearSearch();
      return;
    }
    onSearch(draft.trim(), undefined);
  };

  const handleClearAll = () => {
    setDraft("");
    onClearSearch();
  };

  return (
    <div className="flex flex-col gap-2">
      <form onSubmit={handleSubmit} className="flex items-center gap-2">
        <div className="relative flex-1 max-w-xs">
          <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
          <Input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Search…"
            className="h-8 pl-7 text-xs"
            disabled={hasColumnFilters}
          />
        </div>
        <Button
          type="submit"
          size="sm"
          variant="outline"
          className="h-8 text-xs"
          disabled={hasColumnFilters || !draft.trim()}
        >
          Search
        </Button>
        {hasAnyActive && (
          <Button
            type="button"
            size="sm"
            variant="ghost"
            className="h-8 text-xs text-muted-foreground hover:text-foreground"
            onClick={handleClearAll}
          >
            Clear all
          </Button>
        )}
      </form>

      {hasColumnFilters && (
        <div className="flex flex-wrap items-center gap-1.5">
          {filterEntries.map(([positionStr, filter]) => {
            const position = Number(positionStr);
            const columnName = columns[position] ?? `col_${position + 1}`;
            return (
              <FilterChip
                key={position}
                columnName={columnName}
                filter={filter}
                onRemove={() => onClearColumnFilter(position)}
              />
            );
          })}
        </div>
      )}
    </div>
  );
}

interface FilterChipProps {
  columnName: string;
  filter: ColumnFilterValue;
  onRemove: () => void;
}

function FilterChip({ columnName, filter, onRemove }: FilterChipProps) {
  const valuePart = filter.value ? ` "${filter.value}"` : "";
  return (
    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[11px] bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400 border border-blue-200 dark:border-blue-800">
      <span className="font-medium">{columnName}</span>
      <span className="text-muted-foreground">
        {OPERATOR_LABELS[filter.operator]}
        {valuePart}
      </span>
      <button
        type="button"
        onClick={onRemove}
        className="hover:text-blue-900 dark:hover:text-blue-200"
        aria-label={`Remove filter for ${columnName}`}
      >
        <X className="h-3 w-3" />
      </button>
    </span>
  );
}
