import { AlertCircle, AlertTriangle, Check } from "lucide-react";

import type { PromptReference } from "@/features/concept-editor/hooks/usePromptReferences";
import type { LlmInputSummary, LlmRunTruncation } from "@/features/concept-editor/types";
import { cn } from "@/shared/lib/utils";

interface PromptInputsStripProps {
  references: PromptReference[];
  /** Per-reference delivery facts from the last run, when there has been one. */
  lastRunInputs?: LlmInputSummary[];
  /** Set when the last run lost part of the prompt or part of the answer. */
  lastRunTruncation?: LlmRunTruncation;
}

interface InputRow {
  name: string;
  resolved: boolean;
  detail: string | null;
  truncated: boolean;
}

function detailFor(summary: LlmInputSummary | undefined): string | null {
  if (!summary) return null;
  if (!summary.truncated) return `${summary.total} ${summary.unit} sent`;
  return `${summary.sent} of ${summary.total} ${summary.unit} sent`;
}

function buildRows(
  references: PromptReference[],
  lastRunInputs: LlmInputSummary[] | undefined,
): InputRow[] {
  const byRef = new Map((lastRunInputs ?? []).map((item) => [item.ref, item]));
  return references.map((reference) => {
    const summary = byRef.get(reference.name);
    return {
      name: reference.name,
      resolved: reference.resolved,
      detail: detailFor(summary),
      truncated: Boolean(summary?.truncated),
    };
  });
}

function truncationWarnings(truncation: LlmRunTruncation | undefined): string[] {
  if (!truncation) return [];

  const warnings: string[] = [];
  const prompt = truncation.prompt;
  if (prompt) {
    warnings.push(
      `Prompt too long for the model: ${prompt.dropped_tokens.toLocaleString()} of ` +
        `${prompt.total_tokens.toLocaleString()} tokens were dropped before sending.`,
    );
  }
  if (truncation.output) {
    const ceiling = truncation.maxTokens ? ` (max tokens: ${truncation.maxTokens})` : "";
    warnings.push(`Answer cut short by the token limit${ceiling} -- raise it to get the rest.`);
  }
  return warnings;
}

/**
 * The prompt's dependencies and what the last run lost, stated once.
 *
 * Everything here is invisible in the output otherwise: whether a
 * `{{reference}}` resolves (an unresolved one reaches the model as literal
 * braces), how much of each upstream was actually sent (the row budget caps
 * silently), and whether either end of the exchange was cut -- a prompt too big
 * for the context window, or an answer stopped at the token ceiling. A truncated
 * answer reads exactly like a complete one, which is the whole problem.
 */
export function PromptInputsStrip({
  references,
  lastRunInputs,
  lastRunTruncation,
}: PromptInputsStripProps) {
  const warnings = truncationWarnings(lastRunTruncation);
  if (references.length === 0 && warnings.length === 0) return null;

  const rows = buildRows(references, lastRunInputs);

  return (
    <div className="flex flex-col gap-1 border-t border-border/50 px-3 py-1.5">
      {warnings.map((warning) => (
        <span
          key={warning}
          className="flex items-center gap-1 text-xs text-amber-600 dark:text-amber-400"
        >
          <AlertTriangle className="h-3 w-3 flex-shrink-0" />
          {warning}
        </span>
      ))}
      {rows.length > 0 && (
        <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
          <span className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
            Inputs
          </span>
          {rows.map((row) => (
            <span key={row.name} className="flex items-center gap-1 text-xs">
              {row.resolved ? (
                <Check className="h-3 w-3 text-muted-foreground" />
              ) : (
                <AlertCircle className="h-3 w-3 text-destructive" />
              )}
              <code
                className={cn("font-mono", row.resolved ? "text-foreground" : "text-destructive")}
              >
                {row.name}
              </code>
              {!row.resolved && <span className="text-destructive">unresolved</span>}
              {row.detail && (
                <span
                  className={cn(
                    "text-muted-foreground",
                    row.truncated && "text-amber-600 dark:text-amber-400",
                  )}
                >
                  {row.detail}
                </span>
              )}
            </span>
          ))}
        </div>
      )}
    </div>
  );
}
