import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

export interface WorkspaceExportResponse {
  status: "success" | "error";
  message: string;
  // `data` is the export artifact itself: workspace-level tables alongside one
  // export per ontology, keyed by ontology id.
  data?: {
    summary: {
      total_tables: number;
      total_rows: number;
      ontologies_found: number;
    };
    tables: Record<string, unknown>;
    ontologies: Record<string, unknown>;
  };
}

export interface WorkspaceImportResponse {
  status: "success" | "error";
  message: string;
}

export class WorkspaceService {
  /**
   * Export workspace tables
   */
  static async exportWorkspace(
    scope: "user" | "organization" = "user",
  ): Promise<WorkspaceExportResponse> {
    try {
      const url = `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/export-workspace`;

      const payload = {
        scope,
      };

      const response = (await HttpService.post(
        url,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      )) as WorkspaceExportResponse;

      return response;
    } catch (error) {
      console.error("Error exporting workspace:", error);
      throw error;
    }
  }

  /**
   * Import workspace tables
   */
  static async importWorkspace(
    exportData: unknown,
    scope: "user" | "organization" = "user",
  ): Promise<WorkspaceImportResponse> {
    try {
      const url = `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/import-workspace`;

      const payload = {
        export_data: exportData,
        scope,
      };

      const response = (await HttpService.post(
        url,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      )) as WorkspaceImportResponse;

      return response;
    } catch (error) {
      console.error("Error importing workspace:", error);
      throw error;
    }
  }
}
