import {
  ChevronDown,
  ChevronRight,
  EllipsisVertical,
  FilePlus,
  Folder,
  FolderOpen,
  FolderPlus,
  Lock,
  Pencil,
  Trash2,
} from "lucide-react";
import type React from "react";
import {
  conceptIcon,
  conceptIconColorClass,
} from "@/features/concept-editor/components/explorerTreeItem.utils";
import {
  TreeFileContextMenuContent,
  TreeFileDropdownMenu,
  type TreeFileMenuActions,
} from "@/features/concept-editor/components/TreeFileMenus";
import { TreeRenameInput } from "@/features/concept-editor/components/TreeRenameInput";
import type { ConceptCell } from "@/features/concept-editor/types";
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "@/shared/components/ui/context-menu";
import { cn } from "@/shared/lib/utils";

export interface TreeFolderProps {
  groupName: string;
  isExpanded: boolean;
  cellCount: number;
  isDropTarget: boolean;
  canEditOntologies: boolean;
  onToggle: () => void;
  onDragOver: (e: React.DragEvent) => void;
  onDragLeave: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent) => void;
  onAddCellInGroup?: (groupName: string | null) => void;
  onAddGroup?: () => void;
  onRenameGroup?: (groupName: string) => void;
  onDeleteGroup?: (groupName: string) => void;
  children?: React.ReactNode;
}

export const TreeFolder: React.FC<TreeFolderProps> = ({
  groupName,
  isExpanded,
  cellCount,
  isDropTarget,
  canEditOntologies,
  onToggle,
  onDragOver,
  onDragLeave,
  onDrop,
  onAddCellInGroup,
  onAddGroup,
  onRenameGroup,
  onDeleteGroup,
  children,
}) => {
  const hasContextActions =
    canEditOntologies && (onRenameGroup || onDeleteGroup || onAddCellInGroup || onAddGroup);

  const folderHeader = (
    <button
      type="button"
      onClick={onToggle}
      className="w-full flex items-center gap-1 px-2 py-1 hover:bg-accent text-xs"
    >
      {isExpanded ? (
        <ChevronDown className="h-3.5 w-3.5 text-muted-foreground" />
      ) : (
        <ChevronRight className="h-3.5 w-3.5 text-muted-foreground" />
      )}
      {isExpanded ? (
        <FolderOpen className="h-3.5 w-3.5 text-blue-500 dark:text-blue-400" />
      ) : (
        <Folder className="h-3.5 w-3.5 text-blue-500 dark:text-blue-400" />
      )}
      <span className="flex-1 text-left truncate font-medium">{groupName}</span>
      <span className="text-muted-foreground tabular-nums">{cellCount}</span>
    </button>
  );

  return (
    // biome-ignore lint/a11y/noStaticElementInteractions: drop zone is pointer-only; DnD has no keyboard equivalent
    <div
      onDragOver={onDragOver}
      onDragLeave={onDragLeave}
      onDrop={onDrop}
      className={cn(isDropTarget && "bg-accent/50 ring-1 ring-inset ring-primary/40 rounded-sm")}
    >
      {hasContextActions ? (
        <ContextMenu>
          <ContextMenuTrigger asChild>{folderHeader}</ContextMenuTrigger>
          <ContextMenuContent>
            {onAddCellInGroup && (
              <ContextMenuItem onSelect={() => onAddCellInGroup(groupName)}>
                <FilePlus className="h-3.5 w-3.5" />
                New cell in {groupName}
              </ContextMenuItem>
            )}
            {onAddGroup && (
              <ContextMenuItem onSelect={onAddGroup}>
                <FolderPlus className="h-3.5 w-3.5" />
                New group
              </ContextMenuItem>
            )}
            {(onRenameGroup || onDeleteGroup) && <ContextMenuSeparator />}
            {onRenameGroup && (
              <ContextMenuItem onSelect={() => onRenameGroup(groupName)}>
                <Pencil className="h-3.5 w-3.5" />
                Rename group
              </ContextMenuItem>
            )}
            {onDeleteGroup && (
              <ContextMenuItem
                onSelect={() => onDeleteGroup(groupName)}
                className="text-destructive focus:text-destructive"
              >
                <Trash2 className="h-3.5 w-3.5" />
                Delete group
              </ContextMenuItem>
            )}
          </ContextMenuContent>
        </ContextMenu>
      ) : (
        folderHeader
      )}
      {children}
    </div>
  );
};

export interface TreeFileProps {
  cell: ConceptCell;
  isSelected: boolean;
  isNested: boolean;
  canDrag: boolean;
  canEditOntologies: boolean;
  isEditing: boolean;
  onSelect: () => void;
  onDragStart: (e: React.DragEvent) => void;
  onDragEnd: () => void;
  onDragOver: (e: React.DragEvent) => void;
  onDragLeave: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent) => void;
  dropPosition: "top" | "bottom" | null;
  onStartRename: () => void;
  onCancelRename: () => void;
  onCommitRename: (cellId: string, value: string) => void;
  onDeleteCell?: (cellId: string) => void | Promise<void>;
  onAddCellInGroup?: (groupName: string | null) => void;
  onAddGroup?: () => void;
  onIsolateConcept?: (conceptName: string) => void;
  onManagePermissions?: (predicateName: string) => void;
  isOntologyOwner?: boolean;
}

export const TreeFile: React.FC<TreeFileProps> = ({
  cell,
  isSelected,
  isNested,
  canDrag,
  canEditOntologies,
  isEditing,
  onSelect,
  onDragStart,
  onDragEnd,
  onDragOver,
  onDragLeave,
  onDrop,
  dropPosition,
  onStartRename,
  onCancelRename,
  onCommitRename,
  onDeleteCell,
  onAddCellInGroup,
  onAddGroup,
  onIsolateConcept,
  onManagePermissions,
  isOntologyOwner = false,
}) => {
  const Icon = conceptIcon(cell.conceptType);
  const name = cell.outputPredicate || cell.id;
  const canIsolate = !!onIsolateConcept && !!cell.outputPredicate;
  const canManagePermissions = isOntologyOwner && !!onManagePermissions && !!cell.outputPredicate;
  const hasEditActions =
    canEditOntologies && Boolean(onDeleteCell || onAddCellInGroup || onAddGroup);
  const hasContextActions = hasEditActions || canIsolate || canManagePermissions;
  const iconClassName = cn("h-3.5 w-3.5", conceptIconColorClass(cell.conceptType));

  if (isEditing) {
    return (
      <TreeRenameInput
        initialValue={name}
        isNested={isNested}
        Icon={Icon}
        iconClassName={iconClassName}
        onCommit={(value) => onCommitRename(cell.id, value)}
        onCancel={onCancelRename}
      />
    );
  }

  const menuActions: TreeFileMenuActions = {
    canIsolate,
    canManagePermissions,
    canEditOntologies,
    hasEditActions,
    name,
    cell,
    onIsolateConcept,
    onManagePermissions,
    onStartRename,
    onAddCellInGroup,
    onAddGroup,
    onDeleteCell,
  };

  const fileRow = (
    // biome-ignore lint/a11y/noStaticElementInteractions: HTML drag-and-drop target
    <div
      onDragOver={onDragOver}
      onDragLeave={onDragLeave}
      onDrop={onDrop}
      className={cn(
        "group/tree-file relative w-full flex items-center text-xs hover:bg-accent",
        isNested ? "pl-7 pr-1" : "pl-2 pr-1",
        isSelected && "bg-accent text-accent-foreground font-medium",
        dropPosition === "top" &&
          "before:absolute before:inset-x-1 before:top-0 before:z-10 before:h-0.5 before:bg-primary",
        dropPosition === "bottom" &&
          "after:absolute after:inset-x-1 after:bottom-0 after:z-10 after:h-0.5 after:bg-primary",
      )}
    >
      <button
        type="button"
        draggable={canDrag}
        onDragStart={onDragStart}
        onDragEnd={onDragEnd}
        onClick={onSelect}
        onDoubleClick={canEditOntologies ? onStartRename : undefined}
        data-tree-cell-id={cell.id}
        className={cn(
          "flex-1 min-w-0 flex items-center gap-1.5 py-1",
          canDrag && "cursor-grab active:cursor-grabbing",
        )}
      >
        <Icon className={iconClassName} />
        <span
          className={cn(
            "flex-1 text-left truncate",
            cell.isModified && "text-green-600 dark:text-green-400",
          )}
        >
          {name}
        </span>
        {cell.readOnly && (
          <Lock
            className="h-3 w-3 text-muted-foreground flex-shrink-0"
            aria-label="Read-only concept"
          />
        )}
        {cell.isModified && (
          <span
            title="Unsaved changes"
            className="h-1.5 w-1.5 rounded-full bg-green-600 dark:bg-green-400 flex-shrink-0"
          />
        )}
      </button>
      {hasContextActions && (
        <TreeFileDropdownMenu {...menuActions}>
          <button
            type="button"
            className="h-5 w-5 flex-shrink-0 inline-flex items-center justify-center rounded text-muted-foreground opacity-0 group-hover/tree-file:opacity-100 hover:bg-accent-foreground/10 focus:opacity-100 data-[state=open]:opacity-100"
            aria-label="Actions"
          >
            <EllipsisVertical className="h-3.5 w-3.5" />
          </button>
        </TreeFileDropdownMenu>
      )}
    </div>
  );

  if (!hasContextActions) return fileRow;

  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>{fileRow}</ContextMenuTrigger>
      <TreeFileContextMenuContent {...menuActions} />
    </ContextMenu>
  );
};
