import { Check, FolderOpen, Loader2, Share2, Users, X } from "lucide-react";
import type React from "react";
import { useCallback, useState } from "react";
import { toast } from "sonner";
import type { ShareRole, ShareType, ShareUser } from "@/features/ontologies/sharing/types";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";

interface PendingShareCardProps {
  ontologyId: string;
  ontologyName?: string;
  ontologyDescription?: string;
  sharedBy?: ShareUser;
  shareRole?: ShareRole;
  shareId: string;
  onAccept: (shareId: string) => Promise<void>;
  onDecline: (shareId: string) => Promise<void>;
  // Team shares surface a single "Join" action (claim) instead of Accept/Decline —
  // there's no per-member decline; membership is managed via the team itself.
  shareType?: ShareType;
  onClaim?: (shareId: string) => Promise<void>;
}

// Card variant used for invitations the recipient hasn't accepted yet. Same
// visual shape as ProjectCard so the Shared tab is a uniform grid, but the
// click target is replaced with Accept / Decline buttons — there's no editor to
// open until the share is accepted (the recipient has no local token yet, so
// any proxy request would 401).
const PendingShareCard: React.FC<PendingShareCardProps> = ({
  ontologyId,
  ontologyName,
  ontologyDescription,
  sharedBy,
  shareRole,
  shareId,
  onAccept,
  onDecline,
  shareType = "user",
  onClaim,
}) => {
  const [pendingAction, setPendingAction] = useState<"accept" | "decline" | "join" | null>(null);

  const isTeam = shareType === "team";
  const displayName = ontologyName || ontologyId;
  const displayDescription = ontologyDescription || "";

  const handleAccept = useCallback(async (): Promise<void> => {
    setPendingAction("accept");
    try {
      await onAccept(shareId);
      toast.success(`Joined "${displayName}"`);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to accept invitation";
      toast.error(message);
    } finally {
      setPendingAction(null);
    }
  }, [onAccept, shareId, displayName]);

  const handleDecline = useCallback(async (): Promise<void> => {
    setPendingAction("decline");
    try {
      await onDecline(shareId);
      toast.success("Invitation declined");
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to decline invitation";
      toast.error(message);
    } finally {
      setPendingAction(null);
    }
  }, [onDecline, shareId]);

  const handleJoin = useCallback(async (): Promise<void> => {
    if (!onClaim) return;
    setPendingAction("join");
    try {
      await onClaim(shareId);
      toast.success(`Joined "${displayName}"`);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to join shared ontology";
      toast.error(message);
    } finally {
      setPendingAction(null);
    }
  }, [onClaim, shareId, displayName]);

  const isAccepting = pendingAction === "accept";
  const isDeclining = pendingAction === "decline";
  const isJoining = pendingAction === "join";
  const anyPending = pendingAction !== null;

  return (
    <div className="relative flex h-full flex-col gap-3 rounded-lg border border-amber-500/40 bg-amber-500/[0.04] p-4 transition-all duration-150 dark:border-amber-500/30 dark:bg-amber-500/[0.06]">
      <div className="absolute right-3 top-3">
        <Badge variant="outline" className="border-amber-500/60 text-amber-700 dark:text-amber-400">
          {isTeam ? "Team invitation" : "Invitation"}
        </Badge>
      </div>

      <div className="flex items-start gap-3">
        <div className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md border bg-muted/60">
          <FolderOpen className="h-4 w-4 text-foreground/60" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="truncate pr-20 text-[14px] font-semibold leading-tight text-foreground">
            {displayName}
          </div>
          {displayDescription ? (
            <div className="mt-1 line-clamp-2 text-[12px] text-muted-foreground">
              {displayDescription}
            </div>
          ) : (
            <div className="mt-1 text-[12px] italic text-muted-foreground/50">No description</div>
          )}
        </div>
      </div>

      <div className="flex items-center gap-2 border-t border-border/60 pt-3">
        <span className="flex min-w-0 items-center gap-1.5 text-[12px] text-muted-foreground">
          {isTeam ? (
            <Users className="h-3 w-3 flex-shrink-0" />
          ) : (
            <Share2 className="h-3 w-3 flex-shrink-0" />
          )}
          <span className="truncate">
            {sharedBy
              ? `Shared by ${sharedBy.username}@${sharedBy.organization}`
              : "Shared with you"}
          </span>
        </span>
        {shareRole && (
          <Badge variant="outline" className="capitalize">
            {shareRole}
          </Badge>
        )}
      </div>

      {isTeam ? (
        <div className="flex items-center gap-2">
          <Button
            type="button"
            size="sm"
            className="flex-1 gap-1.5"
            onClick={handleJoin}
            disabled={anyPending}
          >
            {isJoining ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Users className="h-3.5 w-3.5" />
            )}
            Join
          </Button>
        </div>
      ) : (
        <div className="flex items-center gap-2">
          <Button
            type="button"
            size="sm"
            className="flex-1 gap-1.5"
            onClick={handleAccept}
            disabled={anyPending}
          >
            {isAccepting ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Check className="h-3.5 w-3.5" />
            )}
            Accept
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="flex-1 gap-1.5 text-muted-foreground"
            onClick={handleDecline}
            disabled={anyPending}
          >
            {isDeclining ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <X className="h-3.5 w-3.5" />
            )}
            Decline
          </Button>
        </div>
      )}
    </div>
  );
};

export default PendingShareCard;
