import { useState } from "react";

interface CompareState {
  isComparing: boolean;
  selected: string[];
  diffOpen: boolean;
}

interface UseSnapshotCompareReturn {
  isComparing: boolean;
  selected: string[];
  diffOpen: boolean;
  canCompare: boolean;
  toggleComparing: () => void;
  toggleSelected: (source: string) => void;
  openDiff: () => void;
  setDiffOpen: (open: boolean) => void;
}

const INITIAL: CompareState = { isComparing: false, selected: [], diffOpen: false };

export function useSnapshotCompare(): UseSnapshotCompareReturn {
  const [state, setState] = useState<CompareState>(INITIAL);

  const toggleComparing = () =>
    setState((prev) =>
      prev.isComparing ? INITIAL : { isComparing: true, selected: [], diffOpen: false },
    );

  const toggleSelected = (source: string) =>
    setState((prev) => {
      if (prev.selected.includes(source)) {
        return { ...prev, selected: prev.selected.filter((s) => s !== source) };
      }
      // Keep at most two selected; adding a third drops the earliest selection.
      const selected =
        prev.selected.length >= 2 ? [prev.selected[1], source] : [...prev.selected, source];
      return { ...prev, selected };
    });

  const openDiff = () => setState((prev) => ({ ...prev, diffOpen: true }));
  const setDiffOpen = (open: boolean) => setState((prev) => ({ ...prev, diffOpen: open }));

  return {
    isComparing: state.isComparing,
    selected: state.selected,
    diffOpen: state.diffOpen,
    canCompare: state.selected.length === 2,
    toggleComparing,
    toggleSelected,
    openDiff,
    setDiffOpen,
  };
}
