import { FilePlus, Filter, FolderPlus, Pencil, Shield, Trash2 } from "lucide-react";
import type React from "react";
import { cellGroupOrNull } from "@/features/concept-editor/components/explorerTreeItem.utils";
import type { ConceptCell } from "@/features/concept-editor/types";
import {
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
} from "@/shared/components/ui/context-menu";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";

export interface TreeFileMenuActions {
  canIsolate: boolean;
  canManagePermissions: boolean;
  canEditOntologies: boolean;
  hasEditActions: boolean;
  name: string;
  cell: ConceptCell;
  onIsolateConcept?: (conceptName: string) => void;
  onManagePermissions?: (predicateName: string) => void;
  onStartRename: () => void;
  onAddCellInGroup?: (groupName: string | null) => void;
  onAddGroup?: () => void;
  onDeleteCell?: (cellId: string) => void | Promise<void>;
}

export const TreeFileContextMenuContent: React.FC<TreeFileMenuActions> = ({
  canIsolate,
  canManagePermissions,
  canEditOntologies,
  hasEditActions,
  name,
  cell,
  onIsolateConcept,
  onManagePermissions,
  onStartRename,
  onAddCellInGroup,
  onAddGroup,
  onDeleteCell,
}) => (
  <ContextMenuContent>
    {canIsolate && (
      <ContextMenuItem className="gap-[5px]" onSelect={() => onIsolateConcept?.(name)}>
        <Filter className="h-3.5 w-3.5" />
        Focused view
      </ContextMenuItem>
    )}
    {canManagePermissions && (
      <ContextMenuItem className="gap-[5px]" onSelect={() => onManagePermissions?.(name)}>
        <Shield className="h-3.5 w-3.5" />
        Permissions
      </ContextMenuItem>
    )}
    {(canIsolate || canManagePermissions) && hasEditActions && <ContextMenuSeparator />}
    {/* Rename mutates this concept — gate on its per-concept read_only flag, not
        the global share role (a concept can be writeable under a viewer share). */}
    {canEditOntologies && !cell.readOnly && (
      <ContextMenuItem className="gap-[5px]" onSelect={onStartRename}>
        <Pencil className="h-3.5 w-3.5" />
        Rename
      </ContextMenuItem>
    )}
    {onAddCellInGroup && (
      <ContextMenuItem
        className="gap-[5px]"
        onSelect={() => onAddCellInGroup(cellGroupOrNull(cell))}
      >
        <FilePlus className="h-3.5 w-3.5" />
        New cell here
      </ContextMenuItem>
    )}
    {onAddGroup && (
      <ContextMenuItem className="gap-[5px]" onSelect={onAddGroup}>
        <FolderPlus className="h-3.5 w-3.5" />
        New group
      </ContextMenuItem>
    )}
    {onDeleteCell && !cell.readOnly && (
      <>
        <ContextMenuSeparator />
        <ContextMenuItem
          onSelect={() => onDeleteCell(cell.id)}
          className="gap-[5px] text-destructive focus:text-destructive"
        >
          <Trash2 className="h-3.5 w-3.5" />
          Delete
        </ContextMenuItem>
      </>
    )}
  </ContextMenuContent>
);

export const TreeFileDropdownMenu: React.FC<
  TreeFileMenuActions & { children: React.ReactNode }
> = ({
  canIsolate,
  canManagePermissions,
  canEditOntologies,
  hasEditActions,
  name,
  cell,
  onIsolateConcept,
  onManagePermissions,
  onStartRename,
  onAddCellInGroup,
  onAddGroup,
  onDeleteCell,
  children,
}) => (
  <DropdownMenu>
    <DropdownMenuTrigger asChild>{children}</DropdownMenuTrigger>
    <DropdownMenuContent align="end" className="min-w-[160px]">
      {canIsolate && (
        <DropdownMenuItem className="gap-[5px]" onSelect={() => onIsolateConcept?.(name)}>
          <Filter className="h-3.5 w-3.5" />
          Focused view
        </DropdownMenuItem>
      )}
      {canManagePermissions && (
        <DropdownMenuItem className="gap-[5px]" onSelect={() => onManagePermissions?.(name)}>
          <Shield className="h-3.5 w-3.5" />
          Permissions
        </DropdownMenuItem>
      )}
      {(canIsolate || canManagePermissions) && hasEditActions && <DropdownMenuSeparator />}
      {/* Rename mutates this concept — gate on its per-concept read_only flag, not
          the global share role (a concept can be writeable under a viewer share). */}
      {canEditOntologies && !cell.readOnly && (
        <DropdownMenuItem className="gap-[5px]" onSelect={onStartRename}>
          <Pencil className="h-3.5 w-3.5" />
          Rename
        </DropdownMenuItem>
      )}
      {onAddCellInGroup && (
        <DropdownMenuItem
          className="gap-[5px]"
          onSelect={() => onAddCellInGroup(cellGroupOrNull(cell))}
        >
          <FilePlus className="h-3.5 w-3.5" />
          New cell here
        </DropdownMenuItem>
      )}
      {onAddGroup && (
        <DropdownMenuItem className="gap-[5px]" onSelect={onAddGroup}>
          <FolderPlus className="h-3.5 w-3.5" />
          New group
        </DropdownMenuItem>
      )}
      {onDeleteCell && !cell.readOnly && (
        <>
          <DropdownMenuSeparator />
          <DropdownMenuItem
            onSelect={() => onDeleteCell(cell.id)}
            className="gap-[5px] text-destructive focus:text-destructive"
          >
            <Trash2 className="h-3.5 w-3.5" />
            Delete
          </DropdownMenuItem>
        </>
      )}
    </DropdownMenuContent>
  </DropdownMenu>
);
