/**
 * Selection model for the v2 app editor (ADR D7). Everything the inspector
 * can edit is addressed by one of these — clicking in the preview, the
 * structure outline or the data panel all produce the same selection values.
 */
export type EditorSelection =
  | { kind: "app" }
  | { kind: "page"; pageId: string }
  | { kind: "section"; pageId: string; sectionId: string }
  | { kind: "widget"; pageId: string; sectionId: string; widgetId: string }
  | { kind: "input"; pageId: string; inputId: string }
  | {
      kind: "formField";
      pageId: string;
      inputId: string;
      /** Form sections are positional (no ids) — address by index. */
      sectionIndex: number;
      fieldId: string;
    }
  | { kind: "runGroup"; pageId: string; groupId: string };

export type EditorView = "visual" | "json";

export function selectionEquals(a: EditorSelection | null, b: EditorSelection | null): boolean {
  if (a === null || b === null) return a === b;
  return JSON.stringify(a) === JSON.stringify(b);
}
