import { Lock, X } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { toast } from "sonner";
import type { OntologyScope } from "@/features/ontologies/api";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";

interface CopyOntologyDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onCopyOntology: (
    ontologyId: string,
    newOntologyName: string,
    targetScope: OntologyScope,
  ) => Promise<void>;
  sourceOntologyName: string;
  ontologyId: string;
  ontologyScope?: OntologyScope;
}

const CopyOntologyDialog: React.FC<CopyOntologyDialogProps> = ({
  isOpen,
  onClose,
  onCopyOntology,
  sourceOntologyName,
  ontologyId,
  ontologyScope = "user",
}) => {
  const [newOntologyName, setNewOntologyName] = useState(`${sourceOntologyName} (Copy)`);
  const [targetScope, setTargetScope] = useState<OntologyScope>("user");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!newOntologyName.trim()) {
      toast.error("Ontology name cannot be empty");
      return;
    }

    setIsSubmitting(true);

    try {
      await onCopyOntology(ontologyId, newOntologyName.trim(), targetScope);
      onClose();
    } catch (error) {
      toast.error("Failed to copy ontology");
      console.error("Error copying ontology:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    if (!isSubmitting) {
      setNewOntologyName(`${sourceOntologyName} (Copy)`);
      setTargetScope("user");
      onClose();
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && handleClose()}>
      <DialogContent className="p-0 sm:max-w-[425px] overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Copy Ontology</DialogTitle>
        {/* Yellow header bar */}
        <div
          style={{ background: "#FFDF4B", padding: "12px 20px" }}
          className="flex items-center justify-between border-b border-border"
        >
          <h2 className="text-base font-bold text-[#212020]">Copy Ontology</h2>
          <button
            onClick={handleClose}
            className="flex items-center justify-center h-6 w-6 rounded-full hover:bg-black/10 transition-colors"
            aria-label="Close"
          >
            <X className="h-4 w-4 text-[#212020]" />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 bg-card">
          <form onSubmit={handleSubmit}>
            <div className="grid gap-4">
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="newName" className="text-right text-sm font-medium">
                  New Name
                </Label>
                <Input
                  id="newName"
                  value={newOntologyName}
                  onChange={(e) => setNewOntologyName(e.target.value)}
                  className="col-span-3"
                  placeholder="My Ontology (Copy)"
                  autoFocus
                />
              </div>

              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="scope" className="text-right text-sm font-medium">
                  Scope
                </Label>
                <Select
                  value={targetScope}
                  onValueChange={(value: OntologyScope) => {
                    if (value === "organization") return;
                    setTargetScope(value);
                  }}
                >
                  <SelectTrigger className="col-span-3">
                    <SelectValue placeholder="Select scope" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="user">Personal</SelectItem>
                    <SelectItem value="organization" disabled>
                      <div className="flex items-center opacity-50">
                        <span>Organizational</span>
                        <Lock className="ml-2 h-3 w-3" />
                        <span className="ml-1 text-xs text-muted-foreground">(Coming Soon)</span>
                      </div>
                    </SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="flex justify-end gap-2 mt-6">
              <Button type="button" variant="outline" onClick={handleClose} disabled={isSubmitting}>
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={isSubmitting || !newOntologyName.trim()}
                isLoading={isSubmitting}
                className="bg-[#FFDF4B] text-[#212020] hover:bg-[#FFDF4B]/90 border border-[#212020] shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px]"
              >
                Copy
              </Button>
            </div>
          </form>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default CopyOntologyDialog;
