/**
 * Persisted acknowledgements for the lineage "last run failed / cancelled /
 * interrupted" notice.
 *
 * Once a user acknowledges a failed run (by clicking its notice), we remember
 * its `execution_id` so the same notice does not reappear every time they
 * reopen the project. A *new* run mints a new `execution_id`, so a subsequent
 * failure re-surfaces. The acked list is bounded (FIFO) so it can't grow
 * without limit.
 *
 * Keys are typed constants and all access is defensive, per the project rules
 * (see state-management.md).
 */

const STORAGE_KEYS = {
  ACKED_RUNS: "prometheux:lineage:ackedRuns",
} as const;

// Keep at most this many acked execution ids; oldest are dropped first.
const MAX_ACKED = 200;

function readAll(): string[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.ACKED_RUNS);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((v): v is string => typeof v === "string");
  } catch (error) {
    console.error("Failed to read acked lineage runs from storage:", error);
    return [];
  }
}

export const lineageRunAck = {
  isAcked(executionId: string | null | undefined): boolean {
    if (!executionId) return false;
    return readAll().includes(executionId);
  },
  ack(executionId: string): void {
    if (!executionId) return;
    try {
      const next = readAll().filter((id) => id !== executionId);
      next.push(executionId);
      const bounded = next.slice(-MAX_ACKED);
      localStorage.setItem(STORAGE_KEYS.ACKED_RUNS, JSON.stringify(bounded));
    } catch (error) {
      console.error("Failed to persist acked lineage run:", error);
    }
  },
  clear(): void {
    try {
      localStorage.removeItem(STORAGE_KEYS.ACKED_RUNS);
    } catch (error) {
      console.error("Failed to clear acked lineage runs:", error);
    }
  },
};
