import { StreamLanguage } from "@codemirror/language";

interface CustomPrologState {
  inString?: boolean;
  stringChar?: string;
  escaped?: boolean;
}

/**
 * Vadalog Language Mode for CodeMirror
 *
 * Token types mapped to colors (via editorHighlightStyle.ts):
 * - "comment"     → Grey italic (comments starting with %)
 * - "meta"        → Green bold (annotations like @input, @output, @bind)
 * - "variable"    → Orange (uppercase identifiers like X, Y, Z)
 * - "keyword"     → Green (lowercase atoms/predicates like rule, fact)
 * - "string"      → Blue (quoted strings)
 * - "number"      → Blue (numeric literals)
 * - "operator"    → Purple (operators like :-, ->, <-, <=, >=, !=)
 * - "punctuation" → Theme foreground (parentheses, commas, periods)
 * - "propertyName"→ Cyan (Skolem functions #FUNC, built-in functions)
 */
export const customLanguage = StreamLanguage.define({
  name: "customProlog",
  startState: (): CustomPrologState => ({}),
  token: (stream, state: CustomPrologState) => {
    // If we're already in a string, continue parsing it
    if (state.inString) {
      let escaped = state.escaped || false;
      while (!stream.eol()) {
        const ch = stream.next();
        if (escaped) {
          escaped = false;
        } else if (ch === "\\") {
          escaped = true;
        } else if (ch === state.stringChar) {
          // Found closing quote
          state.inString = false;
          state.stringChar = undefined;
          state.escaped = false;
          return "string";
        }
      }
      // Still in string, continue on next line
      state.escaped = escaped;
      return "string";
    }

    // Comments (% ...)
    if (stream.match(/^%.*$/)) {
      return "comment";
    }

    // Annotations (@input, @output, @bind, etc.)
    if (stream.match(/@(input|output|bind|qbind|mapping|model|post|param|explain|chase)\b/)) {
      return "meta";
    }

    // Handle double-quoted strings
    if (stream.match(/"/)) {
      state.inString = true;
      state.stringChar = '"';
      state.escaped = false;
      let escaped = false;
      while (!stream.eol()) {
        const ch = stream.next();
        if (escaped) {
          escaped = false;
        } else if (ch === "\\") {
          escaped = true;
        } else if (ch === '"') {
          // Found closing quote
          state.inString = false;
          state.stringChar = undefined;
          state.escaped = false;
          return "string";
        }
      }
      // String continues on next line
      state.escaped = escaped;
      return "string";
    }

    // Handle single-quoted strings
    if (stream.match(/'/)) {
      state.inString = true;
      state.stringChar = "'";
      state.escaped = false;
      let escaped = false;
      while (!stream.eol()) {
        const ch = stream.next();
        if (escaped) {
          escaped = false;
        } else if (ch === "\\") {
          escaped = true;
        } else if (ch === "'") {
          // Found closing quote
          state.inString = false;
          state.stringChar = undefined;
          state.escaped = false;
          return "string";
        }
      }
      // String continues on next line
      state.escaped = escaped;
      return "string";
    }

    // Skolem functions (#FUNC, #PERSON)
    if (stream.match(/#[A-Z][a-zA-Z0-9_]*/)) {
      return "propertyName";
    }

    // Multi-character operators (must check before single-char).
    // Grouping these into a single token keeps Fira Code ligatures intact
    // (e.g. `<-` → `←`, `>=` → `≥`) — CSS ligatures don't apply across spans.
    if (stream.match(/<=>|<->|:-|->|<-|<=|>=|=>|!=|&&|\|\||==|=</)) {
      return "operator";
    }

    // Single-character operators
    if (stream.match(/[<>=!+\-*/\\|&]/)) {
      return "operator";
    }

    // Keyword operators (not, in) - must be followed by space or end
    if (stream.match(/\b(not|in)\b/)) {
      return "operator";
    }

    // Numbers - doubles with decimal point
    if (stream.match(/-?[0-9]+\.[0-9]+/)) {
      return "number";
    }

    // Numbers - integers
    if (stream.match(/-?[0-9]+/)) {
      return "number";
    }

    // Cypher clause keywords (for Cypher-in-body rules pushed down to Neo4j).
    // Matched before the uppercase-variable rule so inline Cypher reads as
    // keywords rather than variables.
    if (
      stream.match(
        /\b(MATCH|OPTIONAL|UNWIND|CALL|CREATE|MERGE|RETURN|WHERE|WITH|ORDER\s+BY|SKIP|LIMIT|DELETE|DETACH|SET|REMOVE|FOREACH|YIELD)\b/,
      )
    ) {
      return "keyword";
    }

    // Variables (uppercase identifiers like X, Y, PersonName)
    if (stream.match(/[A-Z][a-zA-Z0-9_]*/)) {
      return "variable";
    }

    // Built-in/external functions with namespace (collections:add, nullManagement:isnull)
    if (stream.match(/[a-z][a-zA-Z0-9_]*:[a-z][a-zA-Z0-9_]*/)) {
      return "propertyName";
    }

    // Atoms/Predicates (lowercase identifiers like rule, fact, purchaseCount)
    if (stream.match(/[a-z][a-zA-Z0-9_]*/)) {
      return "keyword";
    }

    // Punctuation (parentheses, commas, periods)
    if (stream.match(/[(),.[\]{}]/)) {
      return "punctuation";
    }

    // Skip whitespace
    if (stream.eatSpace()) return null;

    // Consume any other character
    stream.next();
    return null;
  },
});
