import { create } from "zustand";

interface GettingStartedUiState {
  open: boolean;
  setOpen: (open: boolean) => void;
}

// Popover open state lives in a module-level store rather than local useState
// because SidePanel — and therefore this widget — is mounted per page and
// remounts on every route change (and twice under StrictMode in dev). Local
// state would reset on each remount, blinking the auto-opened popover shut.
// The store keeps it stable across remounts; the once-ever auto-open trigger is
// gated separately by the persisted `autoOpened` flag in gettingStartedStorage.
export const useGettingStartedUiStore = create<GettingStartedUiState>((set) => ({
  open: false,
  setOpen: (open) => set({ open }),
}));
