import { Plus } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import type { AppInputDef, FormFieldDef } from "../../schema/appDefinition.types";
import { selectionEquals } from "../../store/appEditor.types";
import { useAppEditorStore } from "../../store/appEditorStore";
import { addFormField, moveFormField } from "../../store/formFieldMutations";
import { removeSelected } from "../../store/selectionMutations";
import { OutlineRow } from "./OutlineRow";

export interface FieldTypeOption {
  type: FormFieldDef["type"];
  label: string;
}

const FIELD_TYPE_OPTIONS: FieldTypeOption[] = [
  { type: "text", label: "Text" },
  { type: "number", label: "Number" },
  { type: "select", label: "Select" },
  { type: "combobox", label: "Combobox" },
  { type: "date", label: "Date" },
  { type: "multi_select", label: "Multi-select" },
  { type: "checkbox", label: "Checkbox" },
  { type: "radio", label: "Radio buttons" },
  { type: "password", label: "Password" },
  { type: "textarea", label: "Textarea" },
  { type: "record_group", label: "Record group" },
];

interface EditorOutlineFormFieldsProps {
  pageId: string;
  form: AppInputDef;
}

/**
 * The fields of a form input, nested in the structure tree under its
 * form_ref widget — fields are schema nodes like any widget, with the same
 * select / reorder / delete / add affordances (form sections are positional;
 * a header row appears only when a form has more than one).
 */
export function EditorOutlineFormFields({ pageId, form }: EditorOutlineFormFieldsProps) {
  const sections = form.sections ?? [];
  const showSectionHeaders = sections.length > 1;

  return (
    <>
      {sections.map((section, sectionIndex) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: form sections are positional by design
        <div key={sectionIndex} className="flex flex-col gap-0.5">
          {showSectionHeaders && (
            <p className="pl-11 py-0.5 text-[9px] font-medium uppercase tracking-wide text-muted-foreground">
              {section.title || `Section ${sectionIndex + 1}`}
            </p>
          )}
          {section.fields.map((field) => (
            <FieldRow
              key={field.id}
              pageId={pageId}
              inputId={form.id}
              sectionIndex={sectionIndex}
              field={field}
            />
          ))}
          <AddFieldMenu pageId={pageId} inputId={form.id} sectionIndex={sectionIndex} />
        </div>
      ))}
      {sections.length === 0 && <AddFieldMenu pageId={pageId} inputId={form.id} sectionIndex={0} />}
    </>
  );
}

interface FieldRowProps {
  pageId: string;
  inputId: string;
  sectionIndex: number;
  field: FormFieldDef;
}

function FieldRow({ pageId, inputId, sectionIndex, field }: FieldRowProps) {
  const selection = useAppEditorStore((state) => state.selection);
  const select = useAppEditorStore((state) => state.select);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  const fieldSelection = {
    kind: "formField",
    pageId,
    inputId,
    sectionIndex,
    fieldId: field.id,
  } as const;

  return (
    <OutlineRow
      label={field.label || field.id}
      hint={field.type}
      depth={3}
      isSelected={selectionEquals(selection, fieldSelection)}
      onSelect={() => select(fieldSelection)}
      onMoveUp={() =>
        updateDraft((draft) => moveFormField(draft, pageId, inputId, sectionIndex, field.id, -1))
      }
      onMoveDown={() =>
        updateDraft((draft) => moveFormField(draft, pageId, inputId, sectionIndex, field.id, 1))
      }
      onDelete={() => {
        select(null);
        updateDraft((draft) => removeSelected(draft, fieldSelection));
      }}
    />
  );
}

interface AddFieldMenuProps {
  pageId: string;
  inputId: string;
  sectionIndex: number;
}

function AddFieldMenu({ pageId, inputId, sectionIndex }: AddFieldMenuProps) {
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  const handleAdd = (type: FormFieldDef["type"]) => {
    const field: Omit<FormFieldDef, "id"> =
      type === "record_group"
        ? { type, label: "New group", fields: [] }
        : { type, label: "New field" };
    updateDraft((draft) => addFormField(draft, pageId, inputId, sectionIndex, field));
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          type="button"
          className="flex items-center gap-1 pl-11 py-0.5 text-[10px] text-muted-foreground hover:text-foreground"
        >
          <Plus className="h-2.5 w-2.5" />
          Add field
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="max-h-72 overflow-y-auto">
        {FIELD_TYPE_OPTIONS.map((option) => (
          <DropdownMenuItem
            key={option.type}
            className="text-xs"
            onSelect={() => handleAdd(option.type)}
          >
            {option.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
