import { X } from "lucide-react";
import { useEffect, useState } from "react";
import { Toaster as Sonner } from "sonner";

type ToasterProps = React.ComponentProps<typeof Sonner>;

function useHtmlTheme(): "light" | "dark" {
  const getTheme = () => (document.documentElement.classList.contains("dark") ? "dark" : "light");

  const [theme, setTheme] = useState<"light" | "dark">(getTheme);

  useEffect(() => {
    const observer = new MutationObserver(() => setTheme(getTheme()));
    observer.observe(document.documentElement, { attributeFilter: ["class"] });
    return () => observer.disconnect();
  }, [getTheme]);

  return theme;
}

const Toaster = ({ ...props }: ToasterProps) => {
  const theme = useHtmlTheme();

  return (
    <Sonner
      theme={theme as ToasterProps["theme"]}
      className="toaster group"
      style={
        {
          "--toast-close-button-start": "unset",
          "--toast-close-button-end": "8px",
          "--toast-close-button-transform": "none",
        } as React.CSSProperties
      }
      toastOptions={{
        closeButton: true,
        classNames: {
          toast:
            "group toast group-[.toaster]:bg-background group-[.toaster]:text-foreground group-[.toaster]:border-border group-[.toaster]:shadow-lg relative",
          description: "group-[.toast]:text-muted-foreground",
          actionButton: "group-[.toast]:bg-primary group-[.toast]:text-primary-foreground",
          cancelButton: "group-[.toast]:bg-muted group-[.toast]:text-muted-foreground",
          closeButton:
            "!absolute !right-2 !top-2 !z-50 !flex !items-center !justify-center !w-8 !h-8 !text-foreground !hover:bg-secondary/20 !transition-colors !cursor-pointer !text-lg !font-bold !min-w-[32px] !min-h-[32px] !leading-none !rounded-md",
        },
      }}
      icons={{
        close: <X className="w-4 h-4" />,
      }}
      {...props}
    />
  );
};

export { Toaster };
