import { Building2, User } from "lucide-react";
import type React from "react";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import { cn } from "@/shared/lib/utils";

export type OrganizationType = "solo" | "organization";

interface OrganizationTypeSelectorProps {
  selectedType: OrganizationType | null;
  onTypeChange: (type: OrganizationType) => void;
  organizationName: string;
  onOrganizationNameChange: (name: string) => void;
  error?: string;
}

export const OrganizationTypeSelector: React.FC<OrganizationTypeSelectorProps> = ({
  selectedType,
  onTypeChange,
  organizationName,
  onOrganizationNameChange,
  error,
}) => {
  return (
    <div className="space-y-4">
      <Label className="text-sm font-medium text-foreground">How will you use Prometheux?</Label>

      <div className="grid grid-cols-2 gap-4">
        {/* Solo Option */}
        <button
          type="button"
          onClick={() => onTypeChange("solo")}
          className={cn(
            "relative flex flex-col items-center justify-center p-6 rounded-xl border-2 transition-all duration-200",
            "hover:border-primary/50 hover:bg-accent/50",
            "focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2",
            selectedType === "solo"
              ? "border-primary bg-primary/5 shadow-sm"
              : "border-border bg-background",
          )}
        >
          <div
            className={cn(
              "p-4 rounded-full mb-3 transition-colors duration-200",
              selectedType === "solo"
                ? "bg-primary/10 text-primary"
                : "bg-muted text-muted-foreground",
            )}
          >
            <User className="h-8 w-8" />
          </div>
          <span
            className={cn(
              "font-medium text-base",
              selectedType === "solo" ? "text-primary" : "text-foreground",
            )}
          >
            Solo
          </span>
          <span className="text-xs text-muted-foreground mt-1 text-center">Personal use</span>
          {selectedType === "solo" && (
            <div className="absolute top-2 right-2 w-2 h-2 rounded-full bg-primary" />
          )}
        </button>

        {/* Organization Option */}
        <button
          type="button"
          onClick={() => onTypeChange("organization")}
          className={cn(
            "relative flex flex-col items-center justify-center p-6 rounded-xl border-2 transition-all duration-200",
            "hover:border-primary/50 hover:bg-accent/50",
            "focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2",
            selectedType === "organization"
              ? "border-primary bg-primary/5 shadow-sm"
              : "border-border bg-background",
          )}
        >
          <div
            className={cn(
              "p-4 rounded-full mb-3 transition-colors duration-200",
              selectedType === "organization"
                ? "bg-primary/10 text-primary"
                : "bg-muted text-muted-foreground",
            )}
          >
            <Building2 className="h-8 w-8" />
          </div>
          <span
            className={cn(
              "font-medium text-base",
              selectedType === "organization" ? "text-primary" : "text-foreground",
            )}
          >
            Organization
          </span>
          <span className="text-xs text-muted-foreground mt-1 text-center">Team or company</span>
          {selectedType === "organization" && (
            <div className="absolute top-2 right-2 w-2 h-2 rounded-full bg-primary" />
          )}
        </button>
      </div>

      {/* Organization Name Input - only shown when Organization is selected */}
      {selectedType === "organization" && (
        <div className="space-y-2 animate-in fade-in slide-in-from-top-2 duration-200">
          <Label htmlFor="organization-name" className="text-sm font-medium">
            Organization Name
          </Label>
          <Input
            id="organization-name"
            type="text"
            placeholder="Enter your organization name"
            value={organizationName}
            onChange={(e) => onOrganizationNameChange(e.target.value)}
            className={cn(
              "transition-all duration-200",
              error ? "border-destructive focus:ring-destructive" : "",
            )}
          />
          {error && <p className="text-sm text-destructive">{error}</p>}
        </div>
      )}
    </div>
  );
};
