import type { AppWidgetDef, RunGroupDef } from "../../../schema/appDefinition.types";
import {
  BUTTON_ACTION_HELP,
  BUTTON_ACTION_PLACEHOLDER,
  CHART_X_HELP,
  CHART_Y_HELP,
  CHROME_HELP,
  COLUMN_FORMATS_HELP,
  COLUMN_FORMATS_PLACEHOLDER,
  FORMAT_RULES_HELP,
  FORMAT_RULES_PLACEHOLDER,
  HEATMAP_HELP,
  ROW_SELECT_HELP,
  SERIES_COL_HELP,
  STAT_LABEL_HELP,
  STAT_VALUE_HELP,
} from "../editorHelp";
import { BoolField, JsonField, SelectField, TextAreaField, TextField } from "./fields";
import { TokenComboboxField, TokenMultiSelectField } from "./TokenSelect";
import { VariableTriggersHint } from "./VariableTriggersHint";

export type PatchWidgetFn = (partial: Partial<AppWidgetDef>) => void;

interface WidgetTypeFieldsProps {
  widget: AppWidgetDef;
  patch: PatchWidgetFn;
  /** Columns of the widget's bound tap (its concept's fields). */
  columnOptions: string[];
  columnsLoading: boolean;
  /** The page's run groups — used to show what a selection variable triggers. */
  runGroups: RunGroupDef[];
}

const CHART_TYPES = new Set(["line_chart", "area_chart", "bar_chart", "pie_chart"]);

const VARIANT_OPTIONS = [
  { value: "full", label: "Full (search, CSV, pagination)" },
  { value: "compact", label: "Compact (sort + pagination)" },
  { value: "plain", label: "Plain (just the table)" },
];

const BUTTON_STYLE_OPTIONS = [
  { value: "primary", label: "Primary" },
  { value: "outline", label: "Outline" },
  { value: "ghost", label: "Ghost" },
];

/** Variable a newly-selectable table publishes its clicked row under. */
function defaultRowVariable(widgetId: string): string {
  return `selected_${widgetId}`.replace(/[^A-Za-z0-9_]/g, "_");
}

/** Per-type inspector fields: the widget vocabulary's knobs, one group per type. */
export function WidgetTypeFields({
  widget,
  patch,
  columnOptions,
  columnsLoading,
  runGroups,
}: WidgetTypeFieldsProps) {
  const columnPicker = { options: columnOptions, loading: columnsLoading, noun: "columns" };
  if (widget.type === "text" && !widget.outputId) {
    return (
      <TextAreaField
        label="Content (markdown)"
        value={widget.content}
        onChange={(value) => patch({ content: value })}
      />
    );
  }

  if (widget.type === "button") {
    return (
      <>
        <SelectField
          label="Style"
          value={widget.buttonStyle}
          options={BUTTON_STYLE_OPTIONS}
          allowNone
          onChange={(value) =>
            patch({ buttonStyle: value as AppWidgetDef["buttonStyle"] | undefined })
          }
        />
        <JsonField
          label="Action (open_url | set_context | run_group)"
          hint={BUTTON_ACTION_HELP}
          placeholder={BUTTON_ACTION_PLACEHOLDER}
          value={widget.action}
          onChange={(value) => patch({ action: value as AppWidgetDef["action"] })}
        />
      </>
    );
  }

  if (widget.type === "rich_table") {
    return (
      <>
        <TokenMultiSelectField
          label="Columns (subset + order)"
          value={widget.columns ?? []}
          onChange={(value) => patch({ columns: value.length > 0 ? value : undefined })}
          placeholder="All columns"
          {...columnPicker}
        />
        <SelectField
          label="Chrome"
          hint={CHROME_HELP}
          value={widget.variant}
          options={VARIANT_OPTIONS}
          allowNone
          onChange={(value) => patch({ variant: value as AppWidgetDef["variant"] | undefined })}
        />
        <BoolField
          label="Selectable rows"
          value={!!widget.onRowSelect}
          onChange={(enabled) =>
            patch({ onRowSelect: enabled ? { set: defaultRowVariable(widget.id) } : undefined })
          }
        />
        {widget.onRowSelect && (
          <>
            <TextField
              label="Selected row → variable"
              hint={ROW_SELECT_HELP}
              placeholder="e.g. selectedOrder"
              value={widget.onRowSelect.set}
              onChange={(value) => patch({ onRowSelect: value ? { set: value } : undefined })}
            />
            <VariableTriggersHint runGroups={runGroups} variable={widget.onRowSelect.set} />
          </>
        )}
        <JsonField
          label="Format rules"
          hint={FORMAT_RULES_HELP}
          placeholder={FORMAT_RULES_PLACEHOLDER}
          value={widget.formatRules}
          onChange={(value) => patch({ formatRules: value as AppWidgetDef["formatRules"] })}
        />
        <JsonField
          label="Column formats"
          hint={COLUMN_FORMATS_HELP}
          placeholder={COLUMN_FORMATS_PLACEHOLDER}
          value={widget.columnFormats}
          onChange={(value) => patch({ columnFormats: value as AppWidgetDef["columnFormats"] })}
          rows={3}
        />
      </>
    );
  }

  if (CHART_TYPES.has(widget.type)) {
    return (
      <>
        <TokenComboboxField
          label="X column"
          hint={CHART_X_HELP}
          value={widget.x}
          onChange={(value) => patch({ x: value })}
          allowNone
          {...columnPicker}
        />
        <TokenMultiSelectField
          label="Y column(s)"
          hint={CHART_Y_HELP}
          value={widget.y ?? []}
          onChange={(value) => patch({ y: value.length > 0 ? value : undefined })}
          {...columnPicker}
        />
        <TokenComboboxField
          label="Series column (long-format pivot)"
          hint={SERIES_COL_HELP}
          value={widget.seriesCol}
          onChange={(value) => patch({ seriesCol: value })}
          allowNone
          {...columnPicker}
        />
      </>
    );
  }

  if (widget.type === "stat_card") {
    return (
      <>
        <TokenComboboxField
          label="Value column"
          hint={STAT_VALUE_HELP}
          value={widget.valueCol}
          onChange={(value) => patch({ valueCol: value })}
          allowNone
          {...columnPicker}
        />
        <TokenComboboxField
          label="Label column"
          hint={STAT_LABEL_HELP}
          value={widget.labelCol}
          onChange={(value) => patch({ labelCol: value })}
          allowNone
          {...columnPicker}
        />
        <TextField
          label="Sub-text"
          value={widget.statSub}
          onChange={(value) => patch({ statSub: value })}
        />
      </>
    );
  }

  if (widget.type === "heatmap") {
    return (
      <>
        <TokenComboboxField
          label="Row column"
          hint={HEATMAP_HELP}
          value={widget.rowCol}
          onChange={(value) => patch({ rowCol: value })}
          allowNone
          {...columnPicker}
        />
        <TokenComboboxField
          label="Column column"
          value={widget.colCol}
          onChange={(value) => patch({ colCol: value })}
          allowNone
          {...columnPicker}
        />
        <TokenComboboxField
          label="Value column"
          value={widget.valueCol}
          onChange={(value) => patch({ valueCol: value })}
          allowNone
          {...columnPicker}
        />
      </>
    );
  }

  return null;
}
