import { useMemo } from "react";
import type { TabComponent, TabRendererProps } from "@/shared/hooks/tabs/tabTypes";
import { OntologyContextTab } from "../notes/OntologyContextTab";

export function useContextTabRenderer(props: TabRendererProps): TabComponent | null {
  return useMemo(() => {
    if (props.activeTab !== "context") return null;
    return {
      component: OntologyContextTab,
      props: {},
    };
  }, [props.activeTab]);
}
