import { useAuth } from "@/features/auth/components/AuthProvider";
import { useTeamAdminAccess } from "@/features/ontologies/sharing/hooks/useTeamAdminAccess";
import { OWNER_CALLER, type PermissionCaller, type ShareRole } from "../types";
import { useSharedOntologyContext } from "./useSharedOntologyContext";

export interface OntologyPermissionAccess {
  // Whether the current user may open the permissions panel for the open project.
  canManage: boolean;
  // How mutations route: owner-only endpoints, or team-admin/apply (delegated).
  caller: PermissionCaller;
  // Project owner id — excluded from subject pickers (can't be restricted).
  ownerSub?: string;
  // Recipient team context (delegated mode only).
  teamId?: string;
  teamName?: string;
  teamBaseRole?: ShareRole;
}

const NO_ACCESS: OntologyPermissionAccess = { canManage: false, caller: OWNER_CALLER };

// Resolves who may manage permissions of the currently-open project:
//   - Project owner (project not shared to them) → owner-only endpoints.
//   - Owner/admin of the recipient team of a team share → delegated via
//     team-admin/apply. Only while the project is actually shared with that team.
//   - Everyone else → no management panel.
export function useOntologyPermissionAccess(): OntologyPermissionAccess {
  const { user } = useAuth();
  const { isShared, shareType, teamId, sharedBy, shareRole } = useSharedOntologyContext();
  const teamAdmin = useTeamAdminAccess(teamId ?? undefined, shareType ?? undefined);

  // Owned project (never arrived via a share) → the current user is the owner.
  if (!isShared) {
    return { canManage: true, caller: OWNER_CALLER, ownerSub: user?.id };
  }

  // Team share where the current user is an owner/admin of the recipient team.
  if (shareType === "team" && teamId && teamAdmin.canManage) {
    return {
      canManage: true,
      caller: { mode: "team_admin", teamId },
      ownerSub: sharedBy?.sub,
      teamId,
      teamName: teamAdmin.teamName,
      teamBaseRole: shareRole ?? "viewer",
    };
  }

  return NO_ACCESS;
}
