import type { AppInputDef, ScalarInputType } from "../../../schema/appDefinition.types";
import { patchInput } from "../../../store/appEditorMutations";
import { useAppEditorStore } from "../../../store/appEditorStore";
import { INPUT_TYPE_HELP, OPTIONS_SOURCE_HELP, OPTIONS_SOURCE_PLACEHOLDER } from "../editorHelp";
import { BoolField, CsvField, JsonField, SelectField, TextField } from "./fields";
import { StaleSelection } from "./PageInspector";
import { VariableTriggersHint } from "./VariableTriggersHint";

interface InputInspectorProps {
  pageId: string;
  inputId: string;
}

const SCALAR_TYPE_OPTIONS: Array<{ value: ScalarInputType; label: string }> = [
  { value: "text", label: "Text" },
  { value: "number", label: "Number" },
  { value: "select", label: "Select" },
  { value: "combobox", label: "Combobox" },
  { value: "date", label: "Date" },
  { value: "multi_select", label: "Multi-select" },
  { value: "checkbox", label: "Checkbox" },
  { value: "radio", label: "Radio buttons" },
  { value: "password", label: "Password" },
  { value: "textarea", label: "Textarea" },
];

const FORM_LAYOUT_OPTIONS = [
  { value: "flow", label: "Flow (filter bar)" },
  { value: "grid", label: "Grid (per-field span)" },
];

const LABEL_POSITION_OPTIONS = [
  { value: "top", label: "Labels on top" },
  { value: "left", label: "Labels on the left" },
];

export function InputInspector({ pageId, inputId }: InputInspectorProps) {
  const draft = useAppEditorStore((state) => state.draft);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  const page = draft?.pages.find((candidate) => candidate.id === pageId);
  const input = page?.inputs.find((candidate) => candidate.id === inputId);
  if (!page || !input) return <StaleSelection />;

  const patch = (partial: Partial<AppInputDef>) => {
    updateDraft((current) => patchInput(current, pageId, inputId, partial));
  };

  const common = (
    <>
      <TextField label="Label" value={input.label} onChange={(value) => patch({ label: value })} />
      <BoolField
        label="Required"
        value={input.required}
        onChange={(value) => patch({ required: value })}
      />
    </>
  );

  if (input.type === "form") {
    return (
      <div className="flex flex-col gap-2.5">
        {common}
        <TextField
          label="Submit label"
          value={input.submitLabel}
          onChange={(value) => patch({ submitLabel: value })}
        />
        <SelectField
          label="Field layout"
          value={input.layout ?? "flow"}
          options={FORM_LAYOUT_OPTIONS}
          onChange={(value) => patch({ layout: value as AppInputDef["layout"] })}
        />
        <SelectField
          label="Label position"
          value={input.labelPosition ?? "top"}
          options={LABEL_POSITION_OPTIONS}
          onChange={(value) => patch({ labelPosition: value as AppInputDef["labelPosition"] })}
        />
        <JsonField
          label="Sections & fields (raw)"
          value={input.sections}
          onChange={(value) => patch({ sections: value as AppInputDef["sections"] })}
          rows={14}
        />
        <p className="text-[10px] text-muted-foreground leading-relaxed">
          Fields are also in the Structure tree under this form's widget — select one there to edit
          it, or add fields with its + menu. This raw view is the escape hatch.
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-2.5">
      <SelectField
        label="Type"
        hint={INPUT_TYPE_HELP[input.type]}
        value={input.type}
        options={SCALAR_TYPE_OPTIONS}
        onChange={(value) => patch({ type: (value ?? "text") as ScalarInputType })}
      />
      {common}
      <TextField
        label="Placeholder"
        value={input.placeholder}
        onChange={(value) => patch({ placeholder: value })}
      />
      <TextField
        label="Default value"
        value={input.default === undefined ? undefined : String(input.default)}
        onChange={(value) => patch({ default: value })}
      />
      <CsvField
        label="Static options"
        value={input.options}
        onChange={(value) => patch({ options: value })}
      />
      <JsonField
        label="Options from concept"
        hint={OPTIONS_SOURCE_HELP}
        placeholder={OPTIONS_SOURCE_PLACEHOLDER}
        value={input.optionsSource}
        onChange={(value) => patch({ optionsSource: value as AppInputDef["optionsSource"] })}
        rows={4}
      />
      <VariableTriggersHint runGroups={page.runGroups ?? []} variable={input.id} />
    </div>
  );
}
