import { AlertCircle, Bug } from "lucide-react";
import type { SparkUIStatus } from "../types/engineMonitor.types";

interface EngineMonitorStatusProps {
  status: SparkUIStatus | null;
  jobsCount: number;
  executorsCount: number;
  applicationsCount: number;
  lastUpdatedAt: number | null;
  error: string | null;
}

interface StatusRowProps {
  label: string;
  value: string;
  mono?: boolean;
  accent?: "connected" | "idle" | "unreachable";
}

function connectionAccent(status: SparkUIStatus | null): "connected" | "idle" | "unreachable" {
  if (status === null) return "unreachable";
  return status.running === true ? "connected" : "idle";
}

function connectionLabel(accent: "connected" | "idle" | "unreachable"): string {
  switch (accent) {
    case "connected":
      return "running";
    case "idle":
      return "idle";
    case "unreachable":
      return "unreachable";
  }
}

function connectionDotClass(accent: "connected" | "idle" | "unreachable"): string {
  switch (accent) {
    case "connected":
      return "bg-emerald-500";
    case "idle":
      return "bg-muted-foreground/50";
    case "unreachable":
      return "bg-red-500";
  }
}

const StatusRow: React.FC<StatusRowProps> = ({ label, value, mono, accent }) => (
  <div className="grid grid-cols-[140px_1fr] items-center gap-2 py-1.5 px-2 rounded hover:bg-muted/30 transition-colors">
    <div className="text-[11px] uppercase tracking-wide text-muted-foreground font-medium">
      {label}
    </div>
    <div
      className={`text-foreground break-all flex items-center gap-1.5 ${mono ? "font-mono text-xs" : "text-sm"}`}
    >
      {accent ? (
        <span className={`inline-block h-1.5 w-1.5 rounded-full ${connectionDotClass(accent)}`} />
      ) : null}
      {value}
    </div>
  </div>
);

function formatTimestamp(ts: number | null): string {
  if (!ts) return "never";
  return new Date(ts).toLocaleTimeString();
}

const EngineMonitorStatus: React.FC<EngineMonitorStatusProps> = ({
  status,
  jobsCount,
  executorsCount,
  applicationsCount,
  lastUpdatedAt,
  error,
}) => {
  const accent = connectionAccent(status);

  return (
    <div className="p-3 flex flex-col gap-3">
      <div className="flex items-center gap-2 text-xs text-muted-foreground">
        <Bug className="h-3 w-3" />
        <span className="uppercase tracking-widest font-semibold">Debug</span>
      </div>

      <div className="rounded-lg border border-border bg-card divide-y divide-border/60 overflow-hidden">
        <StatusRow label="Connection" value={connectionLabel(accent)} accent={accent} />
        <StatusRow label="Spark URL" value={status?.spark_url ?? "—"} mono />
        <StatusRow label="Proxy URL" value={status?.proxy_url ?? "—"} mono />
        <StatusRow label="Message" value={status?.message ?? "—"} />
        <StatusRow label="Jobs" value={String(jobsCount)} />
        <StatusRow label="Executors" value={String(executorsCount)} />
        <StatusRow label="Applications" value={String(applicationsCount)} />
        <StatusRow label="Last update" value={formatTimestamp(lastUpdatedAt)} />
      </div>

      {error ? (
        <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-xs text-red-700 dark:border-red-900/40 dark:bg-red-900/20 dark:text-red-400">
          <div className="flex items-center gap-1.5 font-semibold mb-1">
            <AlertCircle className="h-3.5 w-3.5" />
            Error
          </div>
          <div className="whitespace-pre-wrap break-words font-mono text-[11px]">{error}</div>
        </div>
      ) : null}
    </div>
  );
};

export default EngineMonitorStatus;
