import type React from "react";
import { cn } from "@/shared/lib/utils";

interface NavButtonProps {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  isActive?: boolean;
  collapsed: boolean;
}

export function SidebarNavButton({
  icon,
  label,
  onClick,
  isActive = false,
  collapsed,
}: NavButtonProps) {
  return (
    <button
      onClick={onClick}
      title={collapsed ? label : undefined}
      className={cn(
        "flex h-9 w-full items-center gap-3 rounded-md px-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground",
        isActive && "bg-primary/10 text-primary",
        collapsed && "justify-center px-0 mx-0",
      )}
    >
      {icon}
      {!collapsed && <span className="truncate">{label}</span>}
    </button>
  );
}
