import { autocompletion } from "@codemirror/autocomplete";
import { search } from "@codemirror/search";
import { EditorView, keymap } from "@codemirror/view";
import CodeMirror from "@uiw/react-codemirror";
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { customCompletions } from "@/features/concept-editor/components/code-editor/completions/customCompletions";
import { useSchemaStore } from "@/features/concept-editor/store";
import { usePreferencesStore } from "@/shared/store/preferencesStore";
import type { CellEditorProps as BaseCellEditorProps } from "../types/editorTypes";

export const cellEditorViews = new Map<string, EditorView>();

interface CellEditorProps extends BaseCellEditorProps {
  className?: string;
  placeholder?: string;
  onWordWrapToggle?: (enabled: boolean) => void;
  wordWrap?: boolean;
  onToggleMinimize?: () => void;
  onEditorReady?: (getCode: () => string) => void; // Expose function to get current code
  /**
   * When true the editor fills 100% of its parent height (instead of growing
   * to fit content). Used by the Explorer split layout where the parent has
   * flex-allocated height and the editor must clip + scroll internally.
   */
  fillHeight?: boolean;
  /**
   * The body is prose rather than code (an llm concept's prompt), so the
   * affordances that only make sense for code are dropped: line numbers and a
   * fold gutter down the side of an English paragraph read as noise, and
   * wrapping is what a paragraph wants by default.
   */
  proseBody?: boolean;
}

const CellEditor: React.FC<CellEditorProps> = ({
  code,
  cellId,
  isRunning,
  extensions,
  editorTheme,
  onCodeChange,
  onRunCell,
  onSaveCell,
  onIndentCode,
  className,
  placeholder,
  onWordWrapToggle,
  wordWrap: externalWordWrap,
  onToggleMinimize,
  onEditorReady,
  fillHeight,
  readOnly,
  proseBody,
}) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const editorViewRef = useRef<EditorView | null>(null);
  const _schemaSuggestions = useSchemaStore((state) => state.schemaSuggestions);
  const [internalWordWrap, setInternalWordWrap] = useState(
    () => usePreferencesStore.getState().wrapCodeByDefault,
  );
  const wordWrap =
    externalWordWrap !== undefined ? externalWordWrap : proseBody || internalWordWrap;

  // Selection highlight colors live in code-editor.css (.cm-selectionBackground,
  // with !important to beat CodeMirror's high-specificity focused selector, and
  // a proper .dark variant). Kept in CSS rather than an EditorView.theme here
  // because EditorView.theme scopes selectors under the editor element, so a
  // `.dark` ancestor (which lives on <html>) would never match.

  // Store onToggleMinimize in ref to avoid recreating extension
  const onToggleMinimizeRef = useRef(onToggleMinimize);
  onToggleMinimizeRef.current = onToggleMinimize;

  // Gutter click handler to minimize/expand cell (optimized)
  const gutterClickExtension = useMemo(() => {
    if (!onToggleMinimizeRef.current) return [];

    const gutterTheme = EditorView.theme({
      ".cm-gutters": {
        cursor: "pointer !important",
        userSelect: "none !important",
      },
      ".cm-gutterElement": {
        cursor: "pointer !important",
        userSelect: "none !important",
      },
      ".cm-lineNumbers .cm-gutterElement": {
        cursor: "pointer !important",
        userSelect: "none !important",
      },
    });

    const eventHandlers = EditorView.domEventHandlers({
      mousedown: (event, _view) => {
        const target = event.target as HTMLElement;
        const isGutterClick = !!target.closest(".cm-gutters");
        // Check if the click is on the gutter (line numbers area)
        if (isGutterClick && onToggleMinimizeRef.current) {
          onToggleMinimizeRef.current();
          event.preventDefault();
          event.stopPropagation();
          return true;
        }
        return false;
      },
      click: (event, _view) => {
        const target = event.target as HTMLElement;
        const isGutterClick = !!target.closest(".cm-gutters");
        // Check if the click is on the gutter (line numbers area)
        if (isGutterClick && onToggleMinimizeRef.current) {
          onToggleMinimizeRef.current();
          event.preventDefault();
          event.stopPropagation();
          return true;
        }
        return false;
      },
    });

    return [gutterTheme, eventHandlers];
  }, []); // No dependencies - uses ref

  // Ensure code is a string
  const safeCode = useMemo(() => {
    return typeof code === "string" ? code : "";
  }, [code]);

  // Handle code changes directly - let parent handle debouncing
  const handleChange = useCallback(
    (value: string) => {
      onCodeChange(value, cellId);
    },
    [onCodeChange, cellId],
  );

  const handleShiftEnter = useCallback(() => {
    if (!isRunning && safeCode.trim()) {
      onRunCell(cellId);
      return true;
    }
    return false;
  }, [cellId, isRunning, safeCode, onRunCell]);

  // Handle Mod+S or Ctrl+S key combination to save the cell
  const handleSaveCell = useCallback(() => {
    if (!isRunning && !readOnly && onSaveCell && safeCode.trim()) {
      onSaveCell(cellId);
      return true;
    }
    return false;
  }, [cellId, isRunning, readOnly, safeCode, onSaveCell]);

  // Handle Mod+I or Ctrl+I key combination to indent the cell
  const handleIndentCell = useCallback(() => {
    if (!isRunning && onIndentCode && safeCode.trim()) {
      onIndentCode(cellId);
      return true;
    }
    return false;
  }, [cellId, isRunning, safeCode, onIndentCode]);

  // Handle toggling % comments at the start of selected lines
  const handleCommentLines = useCallback((view: EditorView) => {
    const { state } = view;
    const { selection } = state;

    const changes: any[] = [];
    let allLinesCommented = true;
    let _totalLines = 0;

    // First pass: check if all selected lines are already commented
    selection.ranges.forEach((range) => {
      const from = range.from;
      const to = range.to;

      // Get line numbers for the selection
      const fromLine = state.doc.lineAt(from);
      const toLine = state.doc.lineAt(to);

      for (let lineNum = fromLine.number; lineNum <= toLine.number; lineNum++) {
        const line = state.doc.line(lineNum);
        const lineText = state.doc.sliceString(line.from, line.to);
        _totalLines++;

        // Check if line starts with % (considering whitespace)
        if (!lineText.trimStart().startsWith("%")) {
          allLinesCommented = false;
        }
      }
    });

    // Second pass: apply comment or uncomment based on current state
    selection.ranges.forEach((range) => {
      const from = range.from;
      const to = range.to;

      // Get line numbers for the selection
      const fromLine = state.doc.lineAt(from);
      const toLine = state.doc.lineAt(to);

      for (let lineNum = fromLine.number; lineNum <= toLine.number; lineNum++) {
        const line = state.doc.line(lineNum);
        const lineText = state.doc.sliceString(line.from, line.to);

        if (allLinesCommented) {
          // Uncomment: remove first % character
          const trimmedText = lineText.trimStart();
          if (trimmedText.startsWith("%")) {
            const leadingWhitespace = lineText.substring(0, lineText.length - trimmedText.length);
            const percentIndex = line.from + leadingWhitespace.length;
            changes.push({
              from: percentIndex,
              to: percentIndex + 1,
              insert: "",
            });
          }
        } else {
          // Comment: add % at the start of the line (after leading whitespace)
          const trimmedText = lineText.trimStart();
          const leadingWhitespace = lineText.substring(0, lineText.length - trimmedText.length);
          const insertPos = line.from + leadingWhitespace.length;
          changes.push({
            from: insertPos,
            to: insertPos,
            insert: "%",
          });
        }
      }
    });

    if (changes.length > 0) {
      // Calculate selection adjustment
      const isUncommenting = allLinesCommented;
      const selectionOffset = isUncommenting ? -changes.length : changes.length;

      view.dispatch({
        changes,
        selection: {
          anchor:
            selection.main.anchor +
            (selection.main.anchor >= selection.main.head ? selectionOffset : 0),
          head: selection.main.head + selectionOffset,
        },
      });
      return true;
    }

    return false;
  }, []);

  // Toggle word wrap
  const handleWordWrapToggle = useCallback(
    (enabled: boolean) => {
      if (onWordWrapToggle) {
        onWordWrapToggle(enabled);
      } else {
        setInternalWordWrap(enabled);
      }
    },
    [onWordWrapToggle],
  );

  // Use refs to avoid recreating keymap extension
  const handlersRef = useRef({
    handleShiftEnter,
    handleCommentLines,
    handleSaveCell,
    handleIndentCell,
    handleWordWrapToggle,
  });
  handlersRef.current = {
    handleShiftEnter,
    handleCommentLines,
    handleSaveCell,
    handleIndentCell,
    handleWordWrapToggle,
  };

  const wordWrapRef = useRef(wordWrap);
  wordWrapRef.current = wordWrap;

  // Add keymap extension for Shift+Enter, comment shortcut, and save (optimized)
  const keymapExtension = useMemo(() => {
    return keymap.of([
      {
        key: "Mod-Shift-Enter",
        run: () => handlersRef.current.handleShiftEnter(),
      },
      {
        key: "Ctrl-Shift-Enter",
        run: () => handlersRef.current.handleShiftEnter(),
      },
      {
        key: "Mod-7",
        run: (view) => handlersRef.current.handleCommentLines(view),
      },
      {
        key: "Ctrl-7",
        run: (view) => handlersRef.current.handleCommentLines(view),
      },
      {
        key: "Mod-s",
        run: () => handlersRef.current.handleSaveCell(),
      },
      {
        key: "Ctrl-s",
        run: () => handlersRef.current.handleSaveCell(),
      },
      {
        key: "Mod-i",
        run: () => handlersRef.current.handleIndentCell(),
      },
      {
        key: "Ctrl-i",
        run: () => handlersRef.current.handleIndentCell(),
      },
      // Option+Z (Mac) or Alt+Z (Windows) for word wrap toggle
      {
        key: "Alt-z",
        run: () => {
          handlersRef.current.handleWordWrapToggle(!wordWrapRef.current);
          return true;
        },
      },
      {
        key: "Mod-Alt-z", // Option+Z on Mac (Mod is Cmd)
        run: () => {
          handlersRef.current.handleWordWrapToggle(!wordWrapRef.current);
          return true;
        },
      },
    ]);
  }, []); // No dependencies - uses refs

  // Add autocomplete extension with schema suggestions
  const autocompleteExtension = useMemo(() => {
    return autocompletion({
      override: [customCompletions],
      activateOnTyping: true,
      defaultKeymap: true,
      closeOnBlur: false,
      maxRenderedOptions: 10,
      icons: true,
    });
  }, []);

  const cellIdRef = useRef(cellId);
  cellIdRef.current = cellId;

  // Create updateListener extension once to prevent memory leak
  const updateListenerExtension = useMemo(
    () =>
      EditorView.updateListener.of((update) => {
        if (update.view) {
          editorViewRef.current = update.view;
          cellEditorViews.set(cellIdRef.current, update.view);
        }
      }),
    [],
  ); // No dependencies - directly updates ref

  useEffect(() => {
    return () => {
      cellEditorViews.delete(cellId);
    };
  }, [cellId]);

  // Expose function to get current code directly from editor (bypasses React state)
  useEffect(() => {
    if (onEditorReady && editorViewRef.current) {
      const getCode = () => {
        if (editorViewRef.current) {
          return editorViewRef.current.state.doc.toString();
        }
        return code; // Fallback to prop if view not available
      };
      onEditorReady(getCode);
    }
  }, [onEditorReady, code]); // Re-expose when editor view changes or code prop updates

  // Add direct DOM event listener as fallback for gutter clicks
  useEffect(() => {
    if (!onToggleMinimize || !editorRef.current) return;

    const handleGutterClick = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      const isGutterClick = target.closest(".cm-gutters") !== null;

      if (isGutterClick && onToggleMinimizeRef.current) {
        onToggleMinimizeRef.current();
        event.preventDefault();
        event.stopPropagation();
      }
    };

    const editorElement = editorRef.current;
    editorElement.addEventListener("click", handleGutterClick, true); // Use capture phase

    return () => {
      editorElement.removeEventListener("click", handleGutterClick, true);
    };
  }, [onToggleMinimize]); // No dependencies - uses ref

  // CodeMirror theme to make editor background white and match theme (memoized to prevent recreation)
  const customEditorTheme = useMemo(
    () =>
      EditorView.theme({
        ".cm-editor": {
          background: "hsl(var(--card)) !important",
          border: "1px solid hsl(var(--border)) !important",
          borderRadius: "0.5rem !important",
          transition: "border-color 0.2s ease-in-out !important",
          outline: "none !important",
        },
        ".cm-gutters": {
          background: "hsl(var(--card) / 0.2) !important",
          borderRight: "none !important",
          backdropFilter: "blur(6px)",
        },
        ".cm-scroller": {
          background: "hsl(var(--card)) !important",
        },
        ".cm-content": {
          // Transparent (NOT card) on purpose. With drawSelection:true CodeMirror
          // paints its selection in a .cm-selectionLayer BEHIND the content; an
          // opaque content background would hide that highlight entirely (the
          // exact bug that made selections invisible). The .cm-scroller above
          // already paints the card background, so transparent here looks
          // identical while letting the drawn selection show through.
          background: "transparent !important",
        },
        ".cm-line": {
          background: "transparent !important",
        },
      }),
    [],
  ); // Create once

  // Combine all extensions including our autocomplete extension and word wrap
  // Optimized to prevent memory leaks from recreating extensions
  const allExtensions = useMemo(() => {
    // Ensure extensions is an array before spreading
    const baseExtensions = Array.isArray(extensions) ? extensions : [];
    const gutterExtensions = Array.isArray(gutterClickExtension) ? gutterClickExtension : [];
    const combinedExtensions = [
      ...baseExtensions,
      // Dock the Find/Replace panel at the top of the editor. Without an explicit
      // search() config, openSearchPanel self-installs it at the bottom, where it
      // overlaps the panel/tabs below the editor and sits in the sticky panels
      // container (so manual positioning fights it). Top docking is in-flow and
      // predictable.
      search({ top: true }),
      keymapExtension,
      autocompleteExtension,
      updateListenerExtension, // Use memoized listener instead of creating new one
      customEditorTheme,
      ...gutterExtensions,
    ];

    // Add word wrap extension if enabled
    if (wordWrap) {
      combinedExtensions.push(EditorView.lineWrapping);
    }

    return combinedExtensions;
  }, [
    extensions,
    keymapExtension,
    autocompleteExtension,
    wordWrap,
    updateListenerExtension,
    customEditorTheme,
    gutterClickExtension,
  ]);

  // Memoize CodeMirror props to prevent unnecessary re-renders
  const codeMirrorProps = useMemo(
    () => ({
      value: safeCode,
      height: fillHeight ? ("100%" as const) : ("auto" as const),
      theme: editorTheme,
      onChange: handleChange,
      extensions: allExtensions,
      placeholder: placeholder || "Enter your query here...",
      readOnly: !!readOnly,
      editable: !readOnly,
      style: fillHeight ? { minHeight: 0, height: "100%" } : { minHeight: 0, height: "auto" },
      basicSetup: {
        lineNumbers: !proseBody,
        foldGutter: !proseBody,
        dropCursor: true,
        allowMultipleSelections: true,
        autocompletion: false,
        bracketMatching: true,
        closeBrackets: true,
        syntaxHighlighting: true,
        highlightActiveLine: true,
        highlightActiveLineGutter: true,
        highlightSpecialChars: false,
        // drawSelection renders multiple cursors/selections — required for the
        // multi-cursor commands (Cmd-D selectNextOccurrence, Cmd-Alt-Up/Down
        // addCursorAbove/Below) to be visible. defaultKeymap (on by default in
        // @uiw basicSetup) already binds those + move/copy line.
        // It also suppresses the native browser selection and draws its own
        // highlight (.cm-selectionBackground, styled in code-editor.css). This
        // only stays visible because .cm-content above is transparent — an
        // opaque content background would paint over the drawn selection layer.
        drawSelection: true,
        highlightSelectionMatches: true,
        rectangularSelection: true,
        crosshairCursor: true,
        indentOnInput: true,
        // Enables Find/Replace (Cmd-F), selectNextOccurrence (Cmd-D),
        // selectSelectionMatches (Cmd-Shift-L) and gotoLine (Cmd-Alt-G).
        searchKeymap: true,
      },
    }),
    [
      safeCode,
      editorTheme,
      handleChange,
      allExtensions,
      placeholder,
      fillHeight,
      readOnly,
      proseBody,
    ],
  );

  return (
    <div
      ref={editorRef}
      className={`relative concept-cell-container cell-editor-wrapper ${wordWrap ? "word-wrap-enabled" : ""} ${className || ""} focus-ring-wrapper`}
      data-cell-id={cellId}
      style={{ minHeight: 0, height: fillHeight ? "100%" : "auto" }}
    >
      <CodeMirror {...codeMirrorProps} />
    </div>
  );
};

// Custom comparison function to prevent unnecessary re-renders
const arePropsEqual = (prevProps: CellEditorProps, nextProps: CellEditorProps) => {
  return (
    prevProps.code === nextProps.code &&
    prevProps.cellId === nextProps.cellId &&
    prevProps.isRunning === nextProps.isRunning &&
    prevProps.editorTheme === nextProps.editorTheme &&
    prevProps.placeholder === nextProps.placeholder &&
    prevProps.wordWrap === nextProps.wordWrap &&
    prevProps.className === nextProps.className &&
    prevProps.readOnly === nextProps.readOnly
  );
};

export default React.memo(CellEditor, arePropsEqual);
