import { ConceptContextPanel } from "@/features/context-layer/concept-context/ConceptContextPanel";
import { useOntologyId } from "@/features/ontologies/hooks/useOntologyId";

import { CellDescriptionSection } from "./CellDescriptionSection";

interface CellContextTabProps {
  description: string;
  onDescriptionChange: (value: string) => void;
  onSaveShortcut: () => void;
  cellBackendId?: string;
  /** The concept (predicate) name — attaches context by project + name. */
  conceptName: string;
  descriptionPlaceholder?: string;
}

/**
 * Content of the Explorer bottom panel's Context tab (replaces the old
 * Description tab): the concept description on top, the local context
 * graph with attach/edit affordances below.
 */
export function CellContextTab({
  description,
  onDescriptionChange,
  onSaveShortcut,
  cellBackendId,
  conceptName,
  descriptionPlaceholder,
}: CellContextTabProps) {
  const ontologyId = useOntologyId();
  const canAttach = Boolean(ontologyId && conceptName);

  return (
    <div className="flex h-full min-h-0 flex-col gap-3 py-2">
      <CellDescriptionSection
        description={description}
        onDescriptionChange={onDescriptionChange}
        onSaveShortcut={onSaveShortcut}
        cellBackendId={cellBackendId}
        placeholder={descriptionPlaceholder}
      />
      {canAttach ? (
        <ConceptContextPanel ontologyId={ontologyId} conceptName={conceptName} />
      ) : (
        <div className="py-4 text-center text-sm text-muted-foreground">
          Save the concept to attach context notes to it.
        </div>
      )}
    </div>
  );
}
