import { useCallback, useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { useConceptEditorClient } from "@/features/concept-editor/api/ConceptEditorClientContext";
import { useSchemaStore } from "@/features/concept-editor/store";
import { ConceptService } from "@/features/concepts/api";
import type { FailedDatasource } from "@/features/data-sources/components/FailedDatasourcesDialog";
import FailedDatasourcesDialog from "@/features/data-sources/components/FailedDatasourcesDialog";
import { type OntologyScope, OntologyService } from "@/features/ontologies/api";
import CreateOntologyDialog from "@/features/ontologies/components/CreateOntologyDialog";
import EditOntologyDialog from "@/features/ontologies/components/EditOntologyDialog";
import OntologiesContent from "@/features/ontologies/components/OntologiesContent";
import OntologyCreationLoader from "@/features/ontologies/components/OntologyCreationLoader";
import { useOntologies } from "@/features/ontologies/hooks/useOntologies";
import { useOntologiesPageState } from "@/features/ontologies/hooks/useOntologiesPageState";
import { useTemplates } from "@/features/ontologies/hooks/useTemplates";
import { setCurrentOntologyId, setCurrentOntologyScope } from "@/features/ontologies/utils";
import SidePanel from "@/shared/components/layout/SidePanel";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";
import { generateEditorUrl } from "@/shared/utils/navigationUtils";

const Ontologies = () => {
  const conceptClient = useConceptEditorClient();

  // Sidebar and navigation state
  const { sidebarVisible, toggleSidebar } = useSidebarState();

  // All local state
  const state = useOntologiesPageState("");
  const {
    hasFetchedOnMount,
    showCreateDialog,
    setShowCreateDialog,
    setIsCreatingOntology,
    showEditDialog,
    setShowEditDialog,
    editingOntology,
    setEditingOntology,
    openingOntologyId,
    setOpeningOntologyId,
    usingTemplateId,
    setUsingTemplateId,
    isDeletingOntology,
    setIsDeletingOntology,
    isUpdatingOntology,
    setIsUpdatingOntology,
    isImportingOntology,
    setIsImportingOntology,
    isCreatingFromContext,
    setIsCreatingFromContext,
    loadingStep,
    setLoadingStep,
    sidebarCollapsed,
    setSidebarCollapsed,
    prevActiveTab,
    setPrevActiveTab,
  } = state;

  const [failedDatasources, setFailedDatasources] = useState<FailedDatasource[]>([]);

  const navigate = useNavigate();
  const location = useLocation();
  const { user } = useAuth();

  // Define scopes to fetch - could be made configurable in settings later
  const scopes = useMemo<OntologyScope[]>(() => ["user", "organization"], []);

  // Loading steps for context project creation
  const loadingSteps = [
    "Processing context",
    "Generating ontology",
    "Defining concepts",
    "Setting up ontology",
  ];

  // Progress through loading steps sequentially
  useEffect(() => {
    if (!isCreatingFromContext) {
      setLoadingStep(0);
      return;
    }

    // Step 1: Start immediately
    setLoadingStep(0);

    // Step 2: After 5 seconds
    const step2Timer = setTimeout(() => {
      setLoadingStep(1);
    }, 5000);

    // Step 3: After 10 seconds
    const step3Timer = setTimeout(() => {
      setLoadingStep(2);
    }, 10000);

    // Step 4: After 15 seconds
    const step4Timer = setTimeout(() => {
      setLoadingStep(3);
    }, 15000);

    return () => {
      clearTimeout(step2Timer);
      clearTimeout(step3Timer);
      clearTimeout(step4Timer);
    };
  }, [
    isCreatingFromContext, // Step 1: Start immediately
    setLoadingStep,
  ]);

  // Detect navigation back to home page for automatic refresh
  const shouldRefreshOnMount = useMemo(() => {
    if (location.state?.skipRefetch) return false;
    return location.state?.refreshOntologies === true;
  }, [location.state?.skipRefetch, location.state?.refreshOntologies]);

  // Use the hooks for projects and templates
  const {
    projects,
    isLoading: isOntologiesLoading,
    isCopying,
    loadOntologies: refetchOntologies,
    renameOntology,
    copyOntology,
  } = useOntologies(scopes);
  const {
    templates,
    isLoading: isTemplatesLoading,
    loadTemplates: refetchTemplates,
  } = useTemplates();

  // Combined loading state for both projects and templates
  const isLoading =
    isOntologiesLoading ||
    isTemplatesLoading ||
    isDeletingOntology ||
    isCopying ||
    isUpdatingOntology ||
    isImportingOntology;
  const _isFetching = isLoading; // Keep for compatibility

  // Show skeleton loading only for initial load
  const _isInitialLoading = isLoading && projects.length === 0 && templates.length === 0;

  // Consolidated effect to handle all refetch scenarios
  useEffect(() => {
    if (location.state?.skipRefetch) return;

    if (shouldRefreshOnMount) {
      Promise.all([refetchOntologies(true), refetchTemplates(true)]).catch((error) => {
        console.error("Error refreshing ontologies and templates on navigation:", error);
      });
      hasFetchedOnMount.current = true;
      window.history.replaceState(
        { ...window.history.state, refreshOntologies: false },
        document.title,
      );
      return;
    }

    if (!hasFetchedOnMount.current) {
      Promise.all([refetchOntologies(true), refetchTemplates(true)]).catch((error) => {
        console.error("Error refreshing ontologies and templates on mount:", error);
      });
      hasFetchedOnMount.current = true;
    }
  }, [
    shouldRefreshOnMount,
    refetchOntologies,
    refetchTemplates,
    hasFetchedOnMount,
    location.state?.skipRefetch,
  ]);

  const handleCreateOntology = useCallback(
    async (name: string, description: string, scope: OntologyScope) => {
      try {
        setIsCreatingOntology(true);

        // Clear any existing cached data
        globalThis.cachedOntologyCode = "";

        // Clear sessionStorage to prevent stale data from previous projects
        sessionStorage.removeItem("ontologyConceptCells");

        // Clear schema suggestions to prevent stale autocomplete from previous projects
        const schemaStore = useSchemaStore.getState();
        schemaStore.clearSchemaSuggestions();

        // Store the selected scope in sessionStorage
        sessionStorage.setItem("newOntologyScope", scope);

        // Call the API to create a new project
        const ontologyData = await OntologyService.createOntology(name, description, scope);

        if (!ontologyData?.id) {
          throw new Error("Ontology creation failed: No ontology ID returned");
        }

        const ontologyId = ontologyData.id;

        // Store the project ID and scope for use in the editor
        setCurrentOntologyId(ontologyId);
        setCurrentOntologyScope(scope);

        // Add a small delay to ensure sessionStorage is updated
        await new Promise((resolve) => setTimeout(resolve, 50));

        // Refresh projects list (force refresh to show new project)
        await refetchOntologies(true);

        // Navigate to the editor with the new project ID and set data tab as active
        navigate(`/editor/${ontologyId}`, {
          state: {
            activeTab: "lineage", // Land on the Ontology (graph) tab for new projects
          },
        });

        return ontologyId;
      } catch (error) {
        console.error("Error creating ontology:", error);
        throw error;
      } finally {
        setIsCreatingOntology(false);
      }
    },
    [navigate, refetchOntologies, setIsCreatingOntology],
  );

  const _handleOpenOntology = useCallback(
    async (ontologyId: string, _ontologyName: string) => {
      try {
        // Set loading state for this specific project
        setOpeningOntologyId(ontologyId);

        // Get scope from sessionStorage if available
        const storedScope = sessionStorage.getItem("currentOntologyScope");
        const ontologyScope =
          storedScope === "user" || storedScope === "organization"
            ? (storedScope as OntologyScope)
            : "user";

        const [ontologyData, conceptCells, concepts] = await Promise.all([
          OntologyService.loadOntology(ontologyId, ontologyScope),
          conceptClient.loadConcepts().catch(() => {
            return { status: "error", data: [] };
          }),
          ConceptService.listConcepts(ontologyId, ontologyScope).catch(() => {
            return [];
          }),
        ]);

        // Store the IDs in sessionStorage for use in the editor
        setCurrentOntologyId(ontologyId);
        setCurrentOntologyScope(ontologyScope);

        // Store concept cells data in sessionStorage if available
        if (conceptCells && conceptCells.status === "success" && Array.isArray(conceptCells.data)) {
          sessionStorage.setItem("ontologyConceptCells", JSON.stringify(conceptCells.data));
        } else {
          sessionStorage.removeItem("ontologyConceptCells");
        }

        // Set concepts as CodeMirror suggestions
        if (concepts && concepts.length > 0) {
          const schemaStore = useSchemaStore.getState();
          schemaStore.setSchemaFromConcepts(concepts);
        } else {
          // Clear suggestions if no concepts found
          const schemaStore = useSchemaStore.getState();
          schemaStore.clearSchemaSuggestions();
        }

        // toast.success(`Loading project: ${projectName}`);

        // Remove the blocking state right before navigation
        // setIsBlocking(false); // This line was removed as per the edit hint

        // Navigate to the editor using the new URL format with username and organization
        const editorUrl = generateEditorUrl(user, ontologyId);
        navigate(editorUrl, {
          state: {
            ontologyData: ontologyData,
            conceptCells: conceptCells,
            concepts: concepts,
            activeTab: "lineage",
          },
        });
      } catch (error) {
        console.error("Error opening ontology:", error);
      } finally {
        // Clear loading state
        setOpeningOntologyId(null);
      }
    },
    [
      navigate,
      user,
      conceptClient.loadConcepts, // Clear loading state
      setOpeningOntologyId,
    ],
  );

  const handleDeleteOntology = useCallback(
    async (_ontologyName: string) => {
      try {
        // Set loading state to hide stale project list
        setIsDeletingOntology(true);

        // Refetch the project list (force refresh to bypass cache)
        await refetchOntologies(true);
      } catch (error) {
        console.error("Error refreshing ontology list:", error);
      } finally {
        setIsDeletingOntology(false);
      }
    },
    [refetchOntologies, setIsDeletingOntology],
  );

  const _handleEditOntology = useCallback(
    (
      ontologyId: string,
      ontologyName: string,
      ontologyDescription: string,
      scope: OntologyScope,
    ) => {
      setEditingOntology({
        id: ontologyId,
        name: ontologyName,
        description: ontologyDescription,
        scope,
      });
      setShowEditDialog(true);
    },
    [setShowEditDialog, setEditingOntology],
  );

  const handleUpdateOntology = useCallback(
    async (id: string, newName: string, newDescription: string) => {
      try {
        setIsUpdatingOntology(true);
        await renameOntology(id, newName, newDescription);
        await refetchOntologies(true);
        setShowEditDialog(false);
        setEditingOntology(null);
      } catch (error) {
        console.error("Error updating ontology:", error);
      } finally {
        setIsUpdatingOntology(false);
      }
    },
    [
      renameOntology,
      refetchOntologies,
      setShowEditDialog,
      setIsUpdatingOntology,
      setEditingOntology,
    ],
  );

  const _handleCopyOntology = useCallback(
    async (ontologyId: string, newOntologyName: string, targetScope: OntologyScope) => {
      try {
        await copyOntology(ontologyId, newOntologyName, targetScope);
      } catch (error) {
        console.error("Error copying ontology:", error);
        // Error toast is already shown in the hook
      }
    },
    [copyOntology],
  );

  const handleOntologyImported = useCallback(async () => {
    try {
      setIsImportingOntology(true);
      // Force refresh the project list to show the imported project
      await refetchOntologies(true);
    } catch (error) {
      console.error("Error refreshing ontology list after import:", error);
      throw error; // Re-throw so the dialog can handle it
    } finally {
      setIsImportingOntology(false);
    }
  }, [refetchOntologies, setIsImportingOntology]);

  const _handleUseTemplate = useCallback(
    async (templateId: string, templateName: string) => {
      setIsCreatingFromContext(true);
      setLoadingStep(0);
      try {
        // Set loading state for this specific template
        setUsingTemplateId(templateId);

        const newOntology = await OntologyService.createFromTemplate(templateId, templateName);

        if (!newOntology?.id) {
          throw new Error("Failed to create ontology from template: No ontology ID returned");
        }

        if (newOntology.failed_datasources?.length) {
          setFailedDatasources(newOntology.failed_datasources);
        }

        await refetchOntologies(true);
      } catch (error) {
        console.error("Error importing template:", error);
      } finally {
        setUsingTemplateId(null);
        setIsCreatingFromContext(false);
        setLoadingStep(0);
      }
    },
    [refetchOntologies, setUsingTemplateId, setLoadingStep, setIsCreatingFromContext],
  );

  const marginClass = sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0";

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="projects"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-col flex-1 ${marginClass} overflow-hidden transition-all duration-200`}
      >
        <div className="flex-1 overflow-y-auto min-h-0">
          <OntologiesContent sidebarVisible={sidebarVisible} toggleSidebar={toggleSidebar} />
        </div>
      </div>

      {/* Create Project Dialog */}
      <CreateOntologyDialog
        isOpen={showCreateDialog}
        onClose={() => setShowCreateDialog(false)}
        onCreateOntology={handleCreateOntology}
        onOntologyImported={handleOntologyImported}
        existingOntologies={projects}
      />

      {/* Edit Project Dialog */}
      {editingOntology && (
        <EditOntologyDialog
          isOpen={showEditDialog}
          onClose={() => {
            setShowEditDialog(false);
            setEditingOntology(null);
          }}
          onUpdateOntology={handleUpdateOntology}
          onDeleteOntology={handleDeleteOntology}
          currentName={editingOntology.name}
          currentDescription={editingOntology.description}
          ontologyId={editingOntology.id}
          ontologyScope={editingOntology.scope}
        />
      )}

      {/* Loading Overlay for Context Project Creation */}
      {isCreatingFromContext && (
        <OntologyCreationLoader
          title="Creating Ontology"
          steps={loadingSteps}
          currentStep={loadingStep}
        />
      )}

      <FailedDatasourcesDialog
        failedDatasources={failedDatasources}
        onClose={() => setFailedDatasources([])}
      />
    </div>
  );
};

export default Ontologies;
