import { BookMarked, History, ListTree, SlidersHorizontal, Sparkles, Workflow } from "lucide-react";
import { useEffect, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import type { AppDefinition } from "../../schema/appDefinition.types";
import {
  type EditorLeftPanel,
  type EditorRightPanel,
  useAppEditorStore,
} from "../../store/appEditorStore";
import { AppVersionsPanel } from "../app/AppVersionsPanel";
import { askAssistantToFix } from "./askAssistant";
import { EditorConceptsPanel } from "./EditorConceptsPanel";
import { EditorDataPanel } from "./EditorDataPanel";
import { EditorJsonPane } from "./EditorJsonPane";
import { EditorOutline } from "./EditorOutline";
import { EditorPreview } from "./EditorPreview";
import { EditorRail, type EditorRailItem } from "./EditorRail";
import { EditorToolbar } from "./EditorToolbar";
import { EditorInspector } from "./inspector/EditorInspector";
import { useAppEditorSave } from "./useAppEditorSave";

interface AppEditorProps {
  definition: AppDefinition;
  /** Home project — the per-project table this app is stored in (route param). */
  storageOntologyId: string;
}

const LEFT_RAIL_ITEMS: Array<EditorRailItem<EditorLeftPanel>> = [
  { id: "structure", label: "Structure", icon: ListTree },
  { id: "data", label: "Data", icon: Workflow },
  { id: "concepts", label: "Concepts", icon: BookMarked },
];

function renderLeftPanel(panel: EditorLeftPanel) {
  if (panel === "structure") return <EditorOutline />;
  if (panel === "data") return <EditorDataPanel />;
  return <EditorConceptsPanel />;
}

/** The concepts library keeps the project page's 330px card width; the
 *  outline/data panels stay compact. It also scrolls internally so its
 *  header stays pinned. */
function leftAsideClass(panel: EditorLeftPanel) {
  if (panel === "concepts") return "w-[330px] overflow-hidden";
  return "w-64 overflow-y-auto";
}

const RIGHT_RAIL_ITEMS: Array<EditorRailItem<EditorRightPanel>> = [
  { id: "inspector", label: "Inspector", icon: SlidersHorizontal },
  { id: "versions", label: "Versions", icon: History },
];

/**
 * The v2 app editor (ADR D7): the live preview is the canvas, flanked by
 * dockable side panels behind edge rails — the same collapse pattern as the
 * lineage view (LineageTreeRail / LibraryRail), so the preview can take the
 * full width on demand. Left: structure outline / data wiring. Right:
 * inspector (micro-edits are direct schema edits) / version history.
 */
export function AppEditor({ definition, storageOntologyId }: AppEditorProps) {
  const navigate = useNavigate();
  const draft = useAppEditorStore((state) => state.draft);
  const savedSnapshot = useAppEditorStore((state) => state.savedSnapshot);
  const view = useAppEditorStore((state) => state.view);
  const jsonParseError = useAppEditorStore((state) => state.jsonParseError);
  const leftPanel = useAppEditorStore((state) => state.leftPanel);
  const rightPanel = useAppEditorStore((state) => state.rightPanel);
  const setLeftPanel = useAppEditorStore((state) => state.setLeftPanel);
  const setRightPanel = useAppEditorStore((state) => state.setRightPanel);
  const initDraft = useAppEditorStore((state) => state.initDraft);
  const replaceDraft = useAppEditorStore((state) => state.replaceDraft);
  const reset = useAppEditorStore((state) => state.reset);

  const { save, isSaving, errors } = useAppEditorSave(storageOntologyId);

  // Init when the store has no draft for THIS app (first mount, StrictMode
  // remount after the cleanup reset, or navigation to another app). Later
  // refetches of the same app must not clobber in-progress edits.
  useEffect(() => {
    const current = useAppEditorStore.getState().draft;
    if (!current || current.id !== definition.id) initDraft(definition);
  }, [definition, initDraft]);

  useEffect(() => () => reset(), [reset]);

  const isDirty = useMemo(
    () => draft !== null && JSON.stringify(draft) !== savedSnapshot,
    [draft, savedSnapshot],
  );

  if (!draft) return null;

  const handleSave = () => {
    // The JSON pane holds unparseable text: the draft is stale, and saving it
    // would silently persist something other than what the user is looking at.
    if (view === "json" && jsonParseError) {
      toast.error("Fix the JSON before saving — the text in the editor has not been applied");
      return;
    }
    void save(draft);
  };

  const handleOpenApp = () => {
    navigate(`/apps/${storageOntologyId}/${draft.id}`);
  };

  const handleCancel = () => {
    navigate("/apps");
  };

  const handleDraftReplaced = (restored: AppDefinition) => {
    replaceDraft(restored);
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <EditorToolbar
        isDirty={isDirty}
        isSaving={isSaving}
        onSave={handleSave}
        onCancel={handleCancel}
        onOpenApp={handleOpenApp}
      />

      {errors.length > 0 && (
        <div className="mx-6 mt-3 flex-shrink-0 rounded-md border border-destructive/40 bg-destructive/5 px-4 py-3">
          <div className="flex items-start justify-between gap-3 mb-1.5">
            <p className="text-xs font-semibold text-destructive">
              Validation failed — nothing was saved
            </p>
            <button
              type="button"
              onClick={() => askAssistantToFix(draft, storageOntologyId, errors)}
              className="flex-shrink-0 flex items-center gap-1 rounded px-2 py-0.5 text-[11px] font-medium text-primary hover:bg-primary/10 transition-colors"
            >
              <Sparkles className="h-3 w-3" />
              Fix with AI
            </button>
          </div>
          <ul className="flex flex-col gap-1 max-h-32 overflow-y-auto">
            {errors.map((error) => (
              <li key={error} className="text-[11px] text-destructive/90 font-mono">
                • {error}
              </li>
            ))}
          </ul>
        </div>
      )}

      <div className="flex flex-1 min-h-0">
        <EditorRail
          side="left"
          items={LEFT_RAIL_ITEMS}
          activePanel={leftPanel}
          onPanelChange={setLeftPanel}
        />
        {leftPanel && (
          <aside
            className={`${leftAsideClass(leftPanel)} flex-shrink-0 bg-card min-h-0 border-r border-border`}
          >
            {renderLeftPanel(leftPanel)}
          </aside>
        )}

        {view === "json" ? (
          <div className="flex flex-col flex-1 min-w-0 pt-4">
            <EditorJsonPane />
          </div>
        ) : (
          <EditorPreview definition={draft} />
        )}

        {rightPanel === "inspector" && (
          <aside className="w-80 flex-shrink-0 overflow-y-auto bg-card min-h-0 border-l border-border">
            <EditorInspector storageOntologyId={storageOntologyId} />
          </aside>
        )}
        {rightPanel === "versions" && (
          <AppVersionsPanel
            ontologyId={storageOntologyId}
            dashboardId={draft.id}
            onDraftReplaced={handleDraftReplaced}
          />
        )}
        <EditorRail
          side="right"
          items={RIGHT_RAIL_ITEMS}
          activePanel={rightPanel}
          onPanelChange={setRightPanel}
        />
      </div>
    </div>
  );
}
