import type { LucideIcon } from "lucide-react";
import { Activity, Cpu, HardDrive, Recycle, ShieldCheck } from "lucide-react";
import { useMemo } from "react";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import type { HealthStatus, RuntimeState } from "../types/engineMonitor.types";
import { formatBytes, formatCpuPercent, healthBadgeClass } from "../utils/engineMonitor.utils";
import RuntimeSparkline from "./RuntimeSparkline";

interface EngineMonitorRuntimeProps {
  runtime: RuntimeState;
  onTriggerGc: () => void;
}

const CPU_COLOR = "#f97316";
const MEMORY_COLOR = "#6366f1";

function formatGcLastTriggered(ts: number | null): string {
  if (!ts) return "never";
  const seconds = Math.max(0, Math.round((Date.now() - ts) / 1000));
  if (seconds < 60) return `${seconds}s ago`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes}m ago`;
}

interface MetricCardProps {
  icon: LucideIcon;
  iconBgClass: string;
  iconColorClass: string;
  title: string;
  value: string;
  secondary?: string;
  progressPercent: number;
  progressColor: string;
  sparkline: React.ReactNode;
}

const MetricCard: React.FC<MetricCardProps> = ({
  icon: Icon,
  iconBgClass,
  iconColorClass,
  title,
  value,
  secondary,
  progressPercent,
  progressColor,
  sparkline,
}) => (
  <div className="relative overflow-hidden rounded-lg border border-border bg-card shadow-sm">
    <div className="flex items-start justify-between p-3 pb-2">
      <div className="flex items-center gap-2">
        <div className={`flex h-7 w-7 items-center justify-center rounded-md ${iconBgClass}`}>
          <Icon className={`h-3.5 w-3.5 ${iconColorClass}`} />
        </div>
        <div>
          <div className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
            {title}
          </div>
          {secondary ? (
            <div className="text-[10px] text-muted-foreground/80 mt-0.5">{secondary}</div>
          ) : null}
        </div>
      </div>
      <div className="text-2xl font-bold tabular-nums text-foreground leading-none">{value}</div>
    </div>
    <div className="px-3">
      <div className="h-1 w-full rounded-full bg-muted overflow-hidden">
        <div
          className="h-full rounded-full transition-all duration-500"
          style={{ width: `${progressPercent}%`, backgroundColor: progressColor }}
        />
      </div>
    </div>
    <div className="px-3 pt-2 pb-3">{sparkline}</div>
  </div>
);

interface HealthBadgeProps {
  status: HealthStatus;
}

const HealthBadge: React.FC<HealthBadgeProps> = ({ status }) => {
  const isUp = status === "UP";
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-[11px] font-semibold ${healthBadgeClass(status)}`}
    >
      {isUp ? (
        <span className="relative inline-flex h-1.5 w-1.5">
          <span className="absolute inline-flex h-full w-full rounded-full bg-emerald-500 opacity-60 animate-ping" />
          <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-emerald-500" />
        </span>
      ) : (
        <span className="inline-block h-1.5 w-1.5 rounded-full bg-current opacity-80" />
      )}
      {status}
    </span>
  );
};

const EngineMonitorRuntime: React.FC<EngineMonitorRuntimeProps> = ({ runtime, onTriggerGc }) => {
  const {
    health,
    cpu,
    cpuCount,
    memoryUsed,
    memoryMax,
    samples,
    isTriggeringGc,
    gcLastTriggeredAt,
  } = runtime;

  const memoryPeak = useMemo(() => {
    const values = samples
      .map((s) => s.memoryUsed)
      .filter((v): v is number => typeof v === "number");
    if (values.length === 0) return null;
    return Math.max(...values);
  }, [samples]);

  const cpuBarWidth = cpu !== null ? Math.min(100, Math.max(0, cpu * 100)) : 0;
  const memoryDenominator = memoryMax ?? memoryPeak;
  const memoryBarWidth =
    memoryUsed !== null && memoryDenominator !== null && memoryDenominator > 0
      ? Math.min(100, (memoryUsed / memoryDenominator) * 100)
      : 0;

  const cpuCoresLabel = (() => {
    if (cpuCount === null || cpuCount <= 0) return undefined;
    const cores = Math.round(cpuCount);
    return `on ${cores} ${cores === 1 ? "core" : "cores"}`;
  })();
  const memoryMaxLabel =
    memoryMax !== null
      ? `of ${formatBytes(memoryMax)} max`
      : memoryPeak !== null
        ? `Peak ${formatBytes(memoryPeak)}`
        : undefined;

  const healthStatus: HealthStatus = health?.status ?? "UNKNOWN";

  return (
    <div className="flex flex-col gap-3 p-3">
      <div className="flex items-center justify-between gap-2 flex-wrap rounded-lg border border-border bg-card px-3 py-2">
        <div className="flex items-center gap-2">
          <div className="flex h-7 w-7 items-center justify-center rounded-md bg-primary/10 text-primary ring-1 ring-primary/20">
            <ShieldCheck className="h-3.5 w-3.5" />
          </div>
          <div>
            <div className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
              Engine health
            </div>
            <HealthBadge status={healthStatus} />
          </div>
        </div>
        <div className="flex items-center gap-3 text-[11px] text-muted-foreground">
          <div className="flex items-center gap-1.5">
            <Activity className="h-3 w-3" />
            <span>GC last: {formatGcLastTriggered(gcLastTriggeredAt)}</span>
          </div>
          <Button
            variant="default"
            size="sm"
            onClick={onTriggerGc}
            disabled={isTriggeringGc}
            className="h-7 text-xs gap-1.5"
          >
            {isTriggeringGc ? <PrometheuxSpinner size={16} /> : <Recycle className="h-3 w-3" />}
            Perform GC
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
        <MetricCard
          icon={Cpu}
          iconBgClass="bg-orange-100 dark:bg-orange-900/30"
          iconColorClass="text-orange-600 dark:text-orange-400"
          title="CPU usage"
          value={formatCpuPercent(cpu)}
          secondary={cpuCoresLabel}
          progressPercent={cpuBarWidth}
          progressColor={CPU_COLOR}
          sparkline={
            <RuntimeSparkline
              samples={samples}
              dataKey="cpu"
              color={CPU_COLOR}
              height={80}
              yMax={1}
              formatValue={(value) => (value === null ? "—" : `${(value * 100).toFixed(1)}%`)}
            />
          }
        />

        <MetricCard
          icon={HardDrive}
          iconBgClass="bg-indigo-100 dark:bg-indigo-900/30"
          iconColorClass="text-indigo-600 dark:text-indigo-400"
          title="Heap memory"
          value={formatBytes(memoryUsed)}
          secondary={memoryMaxLabel}
          progressPercent={memoryBarWidth}
          progressColor={MEMORY_COLOR}
          sparkline={
            <RuntimeSparkline
              samples={samples}
              dataKey="memoryUsed"
              color={MEMORY_COLOR}
              height={80}
              yMax={memoryMax ?? undefined}
              formatValue={(value) => (value === null ? "—" : formatBytes(value))}
            />
          }
        />
      </div>

      <div className="text-[10px] text-muted-foreground px-1 flex items-center justify-between">
        <span>Samples collected every 5 seconds</span>
        <span className="tabular-nums">{samples.length} data points</span>
      </div>
    </div>
  );
};

export default EngineMonitorRuntime;
