import { zodResolver } from "@hookform/resolvers/zod";
import { Loader2, UserPlus } from "lucide-react";
import type React from "react";
import { Controller, useForm } from "react-hook-form";
import { toast } from "sonner";
import { z } from "zod";
import type { AssignableTeamRole, InviteRecipient, TeamError } from "@/features/teams/types";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";

interface InviteMemberFormProps {
  onInvite: (input: { role: AssignableTeamRole; recipient: InviteRecipient }) => Promise<unknown>;
  isSubmitting: boolean;
}

// The backend accepts email OR sub OR username+organization. Email is the
// common case (works even for users who haven't signed up yet — the invite
// email tells them to). Sub/username invites can be added as an "advanced"
// mode later if users ask for it.
const formSchema = z.object({
  email: z.string().email("Enter a valid email"),
  role: z.enum(["admin", "member"]),
});

type FormData = z.infer<typeof formSchema>;

const DEFAULT_VALUES: FormData = { email: "", role: "member" };

const InviteMemberForm: React.FC<InviteMemberFormProps> = ({ onInvite, isSubmitting }) => {
  const {
    register,
    handleSubmit,
    control,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: zodResolver(formSchema),
    defaultValues: DEFAULT_VALUES,
  });

  const onSubmit = handleSubmit(async (values) => {
    try {
      await onInvite({ role: values.role, recipient: { email: values.email.trim() } });
      toast.success(`Invitation sent to ${values.email}`);
      reset(DEFAULT_VALUES);
    } catch (err) {
      const teamErr = err as TeamError;
      // 403 = caller isn't owner/admin (shouldn't happen — the form is gated,
      // but log a specific message just in case).
      // 404 = resolving by sub/username failed (n/a here — we send email only).
      // 409 = already invited or already a member.
      if (teamErr.httpStatus === 409) {
        toast.error(teamErr.message || "This user already has a pending invitation.");
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to send invitation";
      toast.error(message);
    }
  });

  return (
    <form onSubmit={onSubmit} className="space-y-4">
      {/* Inputs group: email + role sit in a row and align by their own tops —
          no cross-element height juggling needed. */}
      <div className="flex flex-col gap-3 sm:flex-row">
        <div className="flex-1 space-y-1.5">
          <Label htmlFor="invite-email">Email</Label>
          <Input
            id="invite-email"
            type="email"
            placeholder="teammate@acme.com"
            disabled={isSubmitting}
            {...register("email")}
          />
          {errors.email && <p className="text-xs text-destructive">{errors.email.message}</p>}
        </div>

        <div className="space-y-1.5 sm:w-[160px]">
          <Label htmlFor="invite-role">Role</Label>
          <Controller
            control={control}
            name="role"
            render={({ field }) => (
              <Select value={field.value} onValueChange={field.onChange} disabled={isSubmitting}>
                <SelectTrigger id="invite-role" className="capitalize">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="member">Member</SelectItem>
                  <SelectItem value="admin">Admin</SelectItem>
                </SelectContent>
              </Select>
            )}
          />
        </div>
      </div>

      {/* Action group: the submit button owns its own row, right-aligned. */}
      <div className="flex justify-end">
        <Button type="submit" disabled={isSubmitting} className="gap-1.5">
          {isSubmitting ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <UserPlus className="h-3.5 w-3.5" />
          )}
          Invite
        </Button>
      </div>
    </form>
  );
};

export default InviteMemberForm;
