import {
  AlertCircle,
  CheckCircle,
  ChevronDown,
  Database,
  Pencil,
  RefreshCw,
  Server,
  Zap,
} from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import {
  DatabricksConfigService,
  DatabricksService,
} from "@/features/compute/api/databricksService";
import { useMachineStatusContext } from "@/features/compute/context/MachineStatusContext";
import { SnowflakeComputeClient } from "@/features/compute/snowflake/SnowflakeComputeClient";
import type { DatabricksCatalog, DatabricksCluster } from "@/features/compute/types";
import { useConceptEditorClient } from "@/features/concept-editor/api/ConceptEditorClientContext";
import SnowflakeIcon from "@/shared/components/icons/SnowflakeIcon";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

interface Machine {
  id: string;
  name: string;
  type: string;
  category: string | null;
  cores: number;
  memory_gb: number;
  cost_per_machine: number;
  ami?: string;
  created_at: string | null;
  updated_at: string | null;
}

interface UserMachine {
  id: string;
  user_id: string;
  machine_id: string;
  node_group_id: string | null;
  status: "Requested" | "Enabled" | "Disabled";
  requested_at: string | null;
  enabled_at: string | null;
  disabled_at: string | null;
  created_at: string | null;
  is_default: boolean;
  is_active: boolean;
  for_compute: boolean;
  autotermination_minutes?: number | null;
  machines?: Machine;
}

interface ComputeIndicatorProps {
  className?: string;
  showIcon?: boolean;
  variant?: "default" | "outline" | "secondary";
  interactive?: boolean; // New prop to enable dropdown functionality
}

const ComputeIndicator: React.FC<ComputeIndicatorProps> = ({
  className = "",
  showIcon = true,
  variant = "outline",
  interactive = false,
}) => {
  const { user } = useAuth();
  const isSnowflake = PROMETHEUX_CONFIG.SNOWFLAKE_MODE;
  const isDatabricksUI = PROMETHEUX_CONFIG.DATABRICKS_UI_MODE;

  const [selectedCompute, setSelectedCompute] = useState<
    "pools" | "databricks" | "snowflake" | null
  >(() => {
    const saved = localStorage.getItem("selectedCompute");
    if (saved === "pools" || saved === "databricks" || saved === "snowflake") return saved;
    return null;
  });
  const [selectedMachine, setSelectedMachine] = useState<Machine | null>(null);

  // Machine data from global context
  const {
    userMachines,
    availabilityResults: machineAvailabilityResults,
    checkingAvailability: machineCheckingAvailability,
    startingMachineId,
    checkMachineStatus,
    fetchAllMachines,
  } = useMachineStatusContext();
  const [databricksConfig, setDatabricksConfig] = useState(() =>
    DatabricksConfigService.getConfig(),
  );

  // Databricks clusters state
  const [databricksClusters, setDatabricksClusters] = useState<DatabricksCluster[]>([]);
  const [loadingClusters, setLoadingClusters] = useState(false);
  const [clusterCacheTimestamp, setClusterCacheTimestamp] = useState(0);

  // Catalog selection modal state
  const [showCatalogModal, setShowCatalogModal] = useState(false);
  const [pendingClusterSelection, setPendingClusterSelection] = useState<DatabricksCluster | null>(
    null,
  );
  const [catalogsForSelection, setCatalogsForSelection] = useState<DatabricksCatalog[]>([]);
  const [loadingCatalogs, setLoadingCatalogs] = useState(false);
  const [selectedCatalogForCluster, setSelectedCatalogForCluster] = useState<string>("");
  const [isEditingCatalog, setIsEditingCatalog] = useState(false); // Track if editing existing catalog

  // Databricks-only availability checking state (machine availability comes from context)
  const [checkingAvailability, setCheckingAvailability] = useState<Record<string, boolean>>({});
  const [availabilityResults, setAvailabilityResults] = useState<
    Record<
      string,
      {
        status: "success" | "error";
        message: string;
        is_available?: boolean;
        machine_status?:
          | "started"
          | "stopped"
          | "stopping"
          | "pending"
          | "starting"
          | "crashed"
          | "restarting";
      }
    >
  >({});

  // Snowflake compute state
  const [snowflakeCurrentPool, setSnowflakeCurrentPool] = useState<string>("");
  const [snowflakePoolState, setSnowflakePoolState] = useState<string>("");
  const kgClient = useConceptEditorClient();

  // Get user's first enabled and running machine for auto-selection
  const getFirstRunningMachine = () => {
    return userMachines.find((um) => {
      if (!um.machines || um.status !== "Enabled") return false;
      return machineAvailabilityResults[um.machines.id]?.machine_status === "started";
    });
  };

  // Load Databricks clusters
  const loadDatabricksClusters = async (): Promise<DatabricksCluster[]> => {
    // Check cache (60 second TTL)
    const now = Date.now();
    if (clusterCacheTimestamp && now - clusterCacheTimestamp < 60000) {
      return databricksClusters; // Return cached data
    }

    setLoadingClusters(true);
    try {
      const databricksService = new DatabricksService();
      const clusters = await databricksService.listClusters(databricksConfig.authMode);
      setDatabricksClusters(clusters || []);
      setClusterCacheTimestamp(now);
      return clusters || [];
    } catch (error) {
      console.error("Error loading Databricks clusters:", error);
      setDatabricksClusters([]);
      return [];
    } finally {
      setLoadingClusters(false);
    }
  };

  // Check Databricks availability for a specific cluster
  const checkDatabricksClusterAvailability = async (cluster: DatabricksCluster) => {
    const key = `databricks-${cluster.cluster_id}`;
    setCheckingAvailability((prev) => ({ ...prev, [key]: true }));

    try {
      // Temporarily set this cluster as the default to check its availability
      const currentConfig = DatabricksConfigService.getConfig();

      // Save temporarily to check this specific cluster
      DatabricksConfigService.saveConfig({
        ...currentConfig,
        defaultClusterId: cluster.cluster_id,
        defaultCluster: cluster,
      });

      const result = await kgClient.checkDatabricksAvailability();
      const databricks = result.data?.compute?.databricks;

      console.log("[ComputeIndicator] Availability check result for", cluster.cluster_name, {
        is_available: databricks?.is_available,
        prometheux: databricks?.prometheux,
        message: result.message,
      });

      // Restore original config
      DatabricksConfigService.saveConfig(currentConfig);

      // Build detailed message including Prometheux status
      let detailedMessage = result.message || "Status check completed";
      if (databricks?.prometheux) {
        if (databricks.prometheux.is_installed) {
          detailedMessage = `Ready for execution`;
          if (databricks.prometheux.library_path) {
            detailedMessage += `\nPrometheux: ${databricks.prometheux.library_path}`;
          }
        } else {
          detailedMessage = `Prometheux is not installed on this cluster`;
        }
      } else if (databricks?.cluster && !databricks.cluster.is_running) {
        detailedMessage = `Cluster is ${databricks.cluster.state}`;
      } else if (!databricks?.is_available) {
        // If not available but no specific reason, provide fallback
        detailedMessage =
          result.message ||
          "Cluster is not available for execution. Check Prometheux installation.";
      }

      setAvailabilityResults((prev) => ({
        ...prev,
        [key]: {
          status: result.status,
          message: detailedMessage,
          is_available: databricks?.is_available || false,
        },
      }));
    } catch (error) {
      console.error(`Error checking Databricks availability for ${cluster.cluster_name}:`, error);

      // Restore original config on error
      const currentConfig = DatabricksConfigService.getConfig();
      DatabricksConfigService.saveConfig(currentConfig);

      setAvailabilityResults((prev) => ({
        ...prev,
        [key]: {
          status: "error",
          message: error instanceof Error ? error.message : "Failed to check availability",
          is_available: false,
        },
      }));
    } finally {
      setCheckingAvailability((prev) => ({ ...prev, [key]: false }));
    }
  };

  // Check Databricks availability (for currently configured cluster)
  const checkDatabricksAvailability = async () => {
    if (!databricksConfig.defaultClusterId) {
      return;
    }

    const key = `databricks-${databricksConfig.defaultClusterId}`;
    setCheckingAvailability((prev) => ({ ...prev, [key]: true }));

    try {
      const result = await kgClient.checkDatabricksAvailability();
      const databricks = result.data?.compute?.databricks;

      // Build detailed message including Prometheux status
      let detailedMessage = result.message || "Status check completed";
      if (databricks?.prometheux) {
        if (databricks.prometheux.is_installed) {
          detailedMessage = `Ready for execution`;
          if (databricks.prometheux.library_path) {
            detailedMessage += `\nPrometheux: ${databricks.prometheux.library_path}`;
          }
        } else {
          detailedMessage = `Prometheux is not installed on this cluster`;
        }
      } else if (databricks?.cluster && !databricks.cluster.is_running) {
        detailedMessage = `Cluster is ${databricks.cluster.state}`;
      } else if (!databricks?.is_available) {
        // If not available but no specific reason, provide fallback
        detailedMessage =
          result.message ||
          "Cluster is not available for execution. Check Prometheux installation.";
      }

      setAvailabilityResults((prev) => ({
        ...prev,
        [key]: {
          status: result.status,
          message: detailedMessage,
          is_available: databricks?.is_available || false,
        },
      }));
    } catch (error) {
      console.error("Error checking Databricks availability:", error);
      setAvailabilityResults((prev) => ({
        ...prev,
        [key]: {
          status: "error",
          message: error instanceof Error ? error.message : "Failed to check availability",
          is_available: false,
        },
      }));
    } finally {
      setCheckingAvailability((prev) => ({ ...prev, [key]: false }));
    }
  };

  // Load catalogs for selection modal
  const loadCatalogsForSelection = async () => {
    setLoadingCatalogs(true);
    try {
      const databricksService = new DatabricksService();
      const catalogs = await databricksService.listCatalogs();
      setCatalogsForSelection(catalogs || []);
    } catch (error) {
      console.error("Error loading catalogs:", error);
      toast.error("Failed to load catalogs");
      setCatalogsForSelection([]);
    } finally {
      setLoadingCatalogs(false);
    }
  };

  // Complete cluster selection after catalog is chosen
  const completeClusterSelection = async (cluster: DatabricksCluster) => {
    const currentConfig = DatabricksConfigService.getConfig();
    DatabricksConfigService.saveConfig({
      ...currentConfig,
      defaultClusterId: cluster.cluster_id,
      defaultCluster: cluster,
    });

    localStorage.setItem("selectedCompute", "databricks");
    setSelectedCompute("databricks");
    setDatabricksConfig(DatabricksConfigService.getConfig());

    // Trigger storage events for other components
    window.dispatchEvent(new Event("storage"));
    window.dispatchEvent(new Event("databricksConfigChanged"));

    // The AI assistant can't read localStorage — hand it the cluster too.
    void DatabricksService.syncSessionConfig();

    // Check availability if not already checked
    const key = `databricks-${cluster.cluster_id}`;
    const availabilityResult = availabilityResults[key];
    if (!availabilityResult) {
      await checkDatabricksClusterAvailability(cluster);
    }
  };

  // Handle catalog selection and complete cluster selection
  const handleCatalogSelection = async () => {
    if (!selectedCatalogForCluster || !pendingClusterSelection) {
      toast.error("Please select a catalog");
      return;
    }

    // Save catalog to config
    const currentConfig = DatabricksConfigService.getConfig();
    DatabricksConfigService.saveConfig({
      ...currentConfig,
      defaultCatalog: selectedCatalogForCluster,
    });

    setDatabricksConfig(DatabricksConfigService.getConfig());

    // Close modal
    setShowCatalogModal(false);

    if (isEditingCatalog) {
      // Just editing catalog for already-selected cluster
      // Trigger config change event for other components
      window.dispatchEvent(new Event("databricksConfigChanged"));
      toast.success("Catalog updated successfully");
    } else {
      // Complete new cluster selection
      await completeClusterSelection(pendingClusterSelection);
    }

    // Reset modal state
    setPendingClusterSelection(null);
    setSelectedCatalogForCluster("");
    setCatalogsForSelection([]);
    setIsEditingCatalog(false);
  };

  // Handle edit catalog (pencil icon click)
  const handleEditCatalog = async (e: React.MouseEvent, cluster: DatabricksCluster) => {
    e.stopPropagation(); // Prevent cluster selection

    // Set pending cluster and mark as editing mode
    setPendingClusterSelection(cluster);
    setIsEditingCatalog(true);

    // Load catalogs and show modal
    await loadCatalogsForSelection();

    // Pre-select current catalog if available
    const currentConfig = DatabricksConfigService.getConfig();
    if (currentConfig.defaultCatalog) {
      setSelectedCatalogForCluster(currentConfig.defaultCatalog);
    }

    setShowCatalogModal(true);
  };

  // Handle compute selection
  const handleComputeSelection = async (
    type: "pools" | "databricks",
    machineId?: string,
    cluster?: DatabricksCluster,
  ) => {
    if (type === "pools" && machineId) {
      const availabilityResult = machineAvailabilityResults[machineId];
      if (availabilityResult && !availabilityResult.is_available) {
        return;
      }

      localStorage.setItem("selectedCompute", type);
      setSelectedCompute(type);
      localStorage.setItem("selectedMachineId", machineId);

      // Switching to a pool machine: stop the assistant running on Databricks.
      void DatabricksService.clearSessionConfig();

      const userMachine = userMachines.find((um) => um.machines?.id === machineId);

      if (userMachine?.machines) {
        setSelectedMachine(userMachine.machines);
      }

      // Trigger storage event for other components
      window.dispatchEvent(new Event("storage"));

      // Check status after selection if not already checked (context handles it, but force a refresh if missing)
      if (!availabilityResult && userMachine) {
        await checkMachineStatus(machineId, userMachine.id);
      }
    } else if (type === "databricks" && cluster) {
      const key = `databricks-${cluster.cluster_id}`;
      const availabilityResult = availabilityResults[key];

      // Only allow selection if:
      // 1. Cluster is RUNNING, AND
      // 2. Availability check passed (is_available = true)
      if (cluster.state !== "RUNNING") {
        return;
      }

      if (availabilityResult && !availabilityResult.is_available) {
        return;
      }

      // Check if catalog is configured
      const currentConfig = DatabricksConfigService.getConfig();
      if (!currentConfig.defaultCatalog) {
        // Need to select catalog first - show modal
        setPendingClusterSelection(cluster);
        await loadCatalogsForSelection();
        setShowCatalogModal(true);
        return;
      }

      // Complete cluster selection (catalog already configured)
      await completeClusterSelection(cluster);
    }
  };

  // Check if any compute is available for execution
  const _hasAvailableCompute = () => {
    const hasAvailableMachines = userMachines.some((um) => {
      if (um.status !== "Enabled" || !um.machines) return false;
      return machineAvailabilityResults[um.machines.id]?.machine_status === "started";
    });

    // Check if any Databricks cluster is available
    const hasDatabricksAvailable =
      databricksConfig.defaultClusterId &&
      (() => {
        const key = `databricks-${databricksConfig.defaultClusterId}`;
        const result = availabilityResults[key];
        // Databricks is available only if availability check passed
        return result?.is_available || false;
      })();

    return hasAvailableMachines || hasDatabricksAvailable;
  };

  // Clear compute selection if currently selected compute becomes unavailable or stopped
  useEffect(() => {
    const currentCompute = localStorage.getItem("selectedCompute");

    // Snowflake compute is always available (the platform runs on it)
    if (currentCompute === "snowflake") return;

    if (currentCompute === "pools") {
      const currentMachineId = localStorage.getItem("selectedMachineId");
      if (currentMachineId) {
        const result = machineAvailabilityResults[currentMachineId];
        // Only clear when definitively stopped, and never for the machine we're intentionally starting
        const isDefinitelyStopped =
          result?.machine_status === "stopped" || result?.machine_status === "crashed";
        if (isDefinitelyStopped && currentMachineId !== startingMachineId) {
          localStorage.removeItem("selectedCompute");
          localStorage.removeItem("selectedMachineId");
          setSelectedCompute(null);
          setSelectedMachine(null);
          window.dispatchEvent(new Event("storage"));
        }
      }
    } else if (currentCompute === "databricks" && databricksConfig.defaultClusterId) {
      const key = `databricks-${databricksConfig.defaultClusterId}`;
      const result = availabilityResults[key];
      if (result && !result.is_available) {
        localStorage.removeItem("selectedCompute");
        setSelectedCompute(null);
        window.dispatchEvent(new Event("storage"));
      }
    }
  }, [
    machineAvailabilityResults,
    availabilityResults,
    startingMachineId,
    databricksConfig.defaultClusterId,
  ]);

  // Proactively check Databricks availability when configuration changes
  useEffect(() => {
    const checkDatabricksIfConfigured = async () => {
      // Check availability if workspace and cluster are configured
      if (databricksConfig.workspaceUrl && databricksConfig.defaultClusterId) {
        const key = `databricks-${databricksConfig.defaultClusterId}`;
        if (!availabilityResults[key] && !checkingAvailability[key]) {
          await checkDatabricksAvailability();
        }
      }
    };

    checkDatabricksIfConfigured();
  }, [databricksConfig, availabilityResults, checkingAvailability, checkDatabricksAvailability]);

  // Stable: uses only imported class + stable state setters — no deps needed.
  const loadSnowflakePoolInfo = useCallback(async () => {
    try {
      const client = new SnowflakeComputeClient();
      const response = await client.listPools();
      if (response.data?.pools) {
        const currentPool = response.data.pools.find((p: { is_current?: boolean }) => p.is_current);
        if (currentPool) {
          setSnowflakeCurrentPool(currentPool.name);
          setSnowflakePoolState(currentPool.state);
        }
      }
    } catch (error) {
      console.error("[ComputeIndicator] Error loading Snowflake pool info:", error);
    }
  }, []);

  // Snowflake mode: auto-select snowflake compute and load pool info (runs once)
  useEffect(() => {
    if (!isSnowflake) return;
    const savedCompute = localStorage.getItem("selectedCompute");
    if (savedCompute === "databricks") {
      setSelectedCompute("databricks");
    } else if (savedCompute !== "snowflake") {
      localStorage.setItem("selectedCompute", "snowflake");
      setSelectedCompute("snowflake");
      window.dispatchEvent(new Event("storage"));
    } else {
      setSelectedCompute("snowflake");
    }
    loadSnowflakePoolInfo();
  }, [user?.id, loadSnowflakePoolInfo]);

  // Databricks UI mode: force "databricks" as the selected compute. Pool machines are
  // hidden from the dropdown in this mode, so any saved "pools" selection is invalid.
  useEffect(() => {
    if (!isDatabricksUI) return;
    const savedCompute = localStorage.getItem("selectedCompute");
    if (savedCompute !== "databricks") {
      localStorage.setItem("selectedCompute", "databricks");
      window.dispatchEvent(new Event("storage"));
    }
    setSelectedCompute("databricks");
  }, [isDatabricksUI]);

  // Non-Snowflake mode: restore selection from localStorage or auto-select active machine
  useEffect(() => {
    if (isSnowflake || isDatabricksUI) return;
    const savedCompute = localStorage.getItem("selectedCompute");
    if (savedCompute === "pools" || savedCompute === "databricks") {
      setSelectedCompute(savedCompute);
    }

    if (!savedCompute && user?.id) {
      const activeMachine = userMachines.find(
        (um) => um.is_active && um.for_compute && um.status === "Enabled" && um.machines,
      );
      if (activeMachine?.machines) {
        setSelectedCompute("pools");
        setSelectedMachine(activeMachine.machines);
        localStorage.setItem("selectedCompute", "pools");
        localStorage.setItem("selectedMachineId", activeMachine.machines.id);
        window.dispatchEvent(new Event("storage"));
      }
    }
  }, [user?.id, userMachines]);

  // Update selected machine when userMachines changes or when no compute is selected
  useEffect(() => {
    // In Snowflake or Databricks UI mode, pool machine auto-selection is irrelevant
    if (isSnowflake || isDatabricksUI) return;

    if (userMachines.length > 0) {
      const firstRunningMachine = getFirstRunningMachine();

      // If no compute is selected and we have a running machine, auto-select it
      if (!selectedCompute && firstRunningMachine?.machines) {
        setSelectedCompute("pools");
        setSelectedMachine(firstRunningMachine.machines);

        // Store in localStorage
        localStorage.setItem("selectedCompute", "pools");
        localStorage.setItem("selectedMachineId", firstRunningMachine.machines.id);

        // Trigger storage event for other components
        window.dispatchEvent(new Event("storage"));
      }
      // Handle existing pools selection logic
      else if (selectedCompute === "pools") {
        const savedMachineId = localStorage.getItem("selectedMachineId");

        const activeMachine = userMachines.find(
          (um) => um.is_active && um.for_compute && um.status === "Enabled" && um.machines,
        );

        // Respect explicit user selection: if the saved machine is still running,
        // don't override it with the is_active machine (multiple machines can run).
        const savedIsRunning =
          savedMachineId &&
          machineAvailabilityResults[savedMachineId]?.machine_status === "started";

        if (activeMachine?.machines && !savedIsRunning) {
          if (activeMachine.machines.id !== savedMachineId) {
            localStorage.setItem("selectedMachineId", activeMachine.machines.id);
            window.dispatchEvent(new Event("storage"));
          }
          setSelectedMachine(activeMachine.machines);
        } else if (savedMachineId && !selectedMachine) {
          // No is_active machine yet (data still loading or none active) — fall back to saved
          const savedUserMachine = userMachines.find(
            (um) => um.machines?.id === savedMachineId && um.status === "Enabled",
          );
          if (savedUserMachine?.machines) {
            setSelectedMachine(savedUserMachine.machines);
          }
        } else if (!savedMachineId && !selectedMachine && firstRunningMachine?.machines) {
          // No saved machine, auto-select first running machine
          setSelectedMachine(firstRunningMachine.machines);
          localStorage.setItem("selectedMachineId", firstRunningMachine.machines.id);
        }
      }
    }
  }, [
    userMachines,
    selectedCompute,
    selectedMachine,
    getFirstRunningMachine,
    machineAvailabilityResults,
  ]);

  // Listen for changes to localStorage and Databricks config
  useEffect(() => {
    const handleStorageChange = () => {
      const savedCompute = localStorage.getItem("selectedCompute");
      if (
        savedCompute === "pools" ||
        savedCompute === "databricks" ||
        savedCompute === "snowflake"
      ) {
        setSelectedCompute(savedCompute);
      }

      const newConfig = DatabricksConfigService.getConfig();
      setDatabricksConfig((prev) => {
        if (
          prev.workspaceUrl === newConfig.workspaceUrl &&
          prev.defaultClusterId === newConfig.defaultClusterId
        ) {
          return prev;
        }
        return newConfig;
      });
    };

    window.addEventListener("storage", handleStorageChange);
    window.addEventListener("databricksConfigChanged", handleStorageChange);

    return () => {
      window.removeEventListener("storage", handleStorageChange);
      window.removeEventListener("databricksConfigChanged", handleStorageChange);
    };
  }, []);

  // Get compute display text
  const getComputeText = () => {
    if (selectedCompute === "snowflake") {
      return snowflakeCurrentPool || "Snowflake Compute";
    } else if (selectedCompute === "pools") {
      if (selectedMachine) return selectedMachine.name;
      // Show machine name from context even before selectedMachine is resolved
      const savedId = localStorage.getItem("selectedMachineId");
      if (savedId) {
        const machine = userMachines.find((um) => um.machines?.id === savedId)?.machines;
        if (machine) return machine.name;
      }
      return "No Compute Selected";
    } else if (selectedCompute === "databricks") {
      if (databricksConfig.defaultCluster?.cluster_name) {
        return `${databricksConfig.defaultCluster.cluster_name} (Databricks)`;
      } else {
        return "Databricks (Not Configured)";
      }
    }
    return "No Compute Selected";
  };

  // Get appropriate icon
  const getIcon = () => {
    if (selectedCompute === "snowflake") {
      return <SnowflakeIcon className="w-3 h-3" />;
    }
    return <Zap className="w-3 h-3" />;
  };

  // Get availability status for current selection
  const getCurrentAvailabilityStatus = () => {
    if (selectedCompute === "snowflake") {
      return { status: "success" as const, message: "Snowflake compute pool", is_available: true };
    } else if (selectedCompute === "pools") {
      const machineId = selectedMachine?.id || localStorage.getItem("selectedMachineId");
      if (machineId) {
        const result = machineAvailabilityResults[machineId];
        // is_active is authoritative. If the machine is active but pod status hasn't caught up
        // yet (or still says stopped after a recent start), treat it as 'starting' so the
        // trigger shows a spinner instead of a red alert.
        const selectedUm = userMachines.find((um) => um.machines?.id === machineId);
        if (
          selectedUm?.is_active &&
          (!result || result.machine_status === "stopped" || result.machine_status === "crashed")
        ) {
          return {
            status: "success" as const,
            message: "Machine starting...",
            machine_status: "starting" as const,
            is_available: false,
          };
        }
        return result || null;
      }
    } else if (selectedCompute === "databricks" && databricksConfig.defaultClusterId) {
      const key = `databricks-${databricksConfig.defaultClusterId}`;
      return availabilityResults[key];
    }
    return null;
  };

  const currentStatus = getCurrentAvailabilityStatus();

  if (!interactive) {
    // Original badge behavior
    return (
      <Badge variant={variant} className={`flex items-center gap-1.5 ${className}`}>
        {showIcon && getIcon()}
        <span className="text-xs">{getComputeText()}</span>
      </Badge>
    );
  }

  const handleDropdownOpen = async () => {
    try {
      if (isSnowflake) {
        await loadSnowflakePoolInfo();
      }

      // Load Databricks clusters if workspace is configured (lightweight list call)
      if (databricksConfig.workspaceUrl) {
        const clusters = await loadDatabricksClusters();
        const runningClusters = clusters.filter((c) => c.state === "RUNNING");
        for (const cluster of runningClusters) {
          const key = `databricks-${cluster.cluster_id}`;
          if (!checkingAvailability[key]) {
            await checkDatabricksClusterAvailability(cluster);
          }
        }
      }
    } catch (error) {
      console.error("Error in handleDropdownOpen:", error);
    }
  };

  const handleRefreshAllStatuses = () => {
    for (const um of userMachines) {
      if (um.machines && um.status === "Enabled") {
        checkMachineStatus(um.machines.id, um.id);
      }
    }
  };

  const handleRefreshSingleMachine = (machineId: string, userMachineId: string) => {
    checkMachineStatus(machineId, userMachineId);
  };

  const handleRefreshDatabricksClusters = async () => {
    if (!databricksConfig.workspaceUrl) return;
    setClusterCacheTimestamp(0);
    const clusters = await loadDatabricksClusters();
    const runningClusters = clusters.filter((c) => c.state === "RUNNING");
    for (const cluster of runningClusters) {
      await checkDatabricksClusterAvailability(cluster);
    }
  };

  // Interactive dropdown behavior
  return (
    <TooltipProvider>
      <DropdownMenu
        onOpenChange={(open) => {
          if (open) handleDropdownOpen();
        }}
      >
        <DropdownMenuTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            className={`flex items-center gap-2 text-xs ${className}`}
          >
            {showIcon && getIcon()}
            <span>{getComputeText()}</span>
            {(() => {
              const selectedMachineId =
                selectedMachine?.id || localStorage.getItem("selectedMachineId");
              const isCheckingSelected =
                selectedCompute === "pools" && selectedMachineId
                  ? machineCheckingAvailability[selectedMachineId]
                  : false;
              const hasResult =
                selectedCompute === "pools" && selectedMachineId
                  ? machineAvailabilityResults[selectedMachineId] !== undefined
                  : true;
              const machineStatus = currentStatus?.machine_status;
              if (
                isCheckingSelected ||
                !hasResult ||
                (machineStatus &&
                  ["starting", "stopping", "pending", "restarting"].includes(machineStatus))
              ) {
                return <PrometheuxSpinner size={16} />;
              }
              if (currentStatus) {
                return currentStatus.is_available ? (
                  <CheckCircle className="w-3 h-3 text-green-600" />
                ) : (
                  <AlertCircle className="w-3 h-3 text-red-600" />
                );
              }
              return null;
            })()}
            <ChevronDown className="w-3 h-3" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="start"
          className="w-80 max-w-[90vw] max-h-[70vh] overflow-y-auto"
        >
          {/* Snowflake Compute (read-only), Compute Pool Machines, or nothing in Databricks UI mode */}
          {isDatabricksUI ? null : isSnowflake ? (
            <>
              <DropdownMenuLabel className="flex items-center justify-between">
                <span className="flex items-center gap-1.5">
                  <SnowflakeIcon className="w-3.5 h-3.5" />
                  Snowflake Compute
                </span>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      className="p-0.5 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                      onClick={(e) => {
                        e.stopPropagation();
                        loadSnowflakePoolInfo();
                      }}
                    >
                      <RefreshCw className="w-3 h-3" />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>Refresh pool info</TooltipContent>
                </Tooltip>
              </DropdownMenuLabel>
              <DropdownMenuItem
                className="flex items-center justify-between cursor-default"
                onSelect={(e) => e.preventDefault()}
              >
                <div className="flex items-center gap-2">
                  <SnowflakeIcon className="w-3 h-3" />
                  <div className="flex flex-col">
                    <span className="text-xs font-medium">
                      {snowflakeCurrentPool || "Loading..."}
                    </span>
                    {snowflakePoolState && (
                      <span className="text-[10px] text-muted-foreground">
                        {snowflakePoolState}
                      </span>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-1">
                  <Badge variant="outline" className="text-[10px] px-1 py-0">
                    Current
                  </Badge>
                  <CheckCircle className="w-3 h-3 text-green-600" />
                </div>
              </DropdownMenuItem>
              <DropdownMenuItem disabled className="py-1">
                <span className="text-[10px] text-muted-foreground italic">
                  Manage pools in Compute Management page
                </span>
              </DropdownMenuItem>
              <DropdownMenuSeparator />
            </>
          ) : userMachines.length > 0 ? (
            <>
              <DropdownMenuLabel className="flex items-center justify-between">
                <span>Compute Pool Machines</span>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      className="p-0.5 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleRefreshAllStatuses();
                      }}
                    >
                      <RefreshCw
                        className={`w-3 h-3 ${Object.values(machineCheckingAvailability).some(Boolean) ? "animate-spin" : ""}`}
                      />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>Refresh all machine statuses</TooltipContent>
                </Tooltip>
              </DropdownMenuLabel>
              {userMachines
                .filter((um) => um.for_compute === true && um.status === "Enabled")
                .map((userMachine) => {
                  if (!userMachine.machines) return null;
                  const machine = userMachine.machines;
                  const isSelected =
                    selectedCompute === "pools" && selectedMachine?.id === machine.id;
                  const isChecking = machineCheckingAvailability[machine.id];
                  const statusResult = machineAvailabilityResults[machine.id];
                  const hasResult = statusResult !== undefined;
                  const rawMachineStatus = statusResult?.machine_status;
                  // is_active is the authoritative signal. If is_active:true but pod status says
                  // stopped/crashed/unknown, the pod hasn't caught up yet — treat as 'starting'.
                  const machineStatus =
                    rawMachineStatus === "started"
                      ? "started"
                      : userMachine.is_active &&
                          (!rawMachineStatus ||
                            rawMachineStatus === "stopped" ||
                            rawMachineStatus === "crashed")
                        ? "starting"
                        : rawMachineStatus || "stopped";
                  const isRunning = machineStatus === "started";
                  const isPending = ["pending", "starting", "stopping", "restarting"].includes(
                    machineStatus,
                  );

                  return (
                    <DropdownMenuItem
                      key={machine.id}
                      onClick={(e) => {
                        if (!isRunning) {
                          e.preventDefault();
                          return;
                        }
                        handleComputeSelection("pools", machine.id);
                      }}
                      className={`flex items-center justify-between ${!isRunning ? "opacity-60" : "cursor-pointer"}`}
                    >
                      <div className="flex items-center gap-2">
                        <Server className="w-3 h-3" />
                        <span className="text-xs">
                          {machine.name}
                          {isSelected && " (Current)"}
                        </span>
                      </div>
                      <div className="flex items-center gap-1">
                        {!isChecking && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <button
                                type="button"
                                className="p-0.5 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  e.preventDefault();
                                  handleRefreshSingleMachine(machine.id, userMachine.id);
                                }}
                              >
                                <RefreshCw className="w-2.5 h-2.5" />
                              </button>
                            </TooltipTrigger>
                            <TooltipContent>Refresh status</TooltipContent>
                          </Tooltip>
                        )}
                        {isChecking || !hasResult ? (
                          <PrometheuxSpinner size={16} />
                        ) : isRunning ? (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <div>
                                <CheckCircle className="w-3 h-3 text-green-600" />
                              </div>
                            </TooltipTrigger>
                            <TooltipContent>
                              <p>Machine is running</p>
                            </TooltipContent>
                          </Tooltip>
                        ) : isPending ? (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <div>
                                <PrometheuxSpinner size={16} />
                              </div>
                            </TooltipTrigger>
                            <TooltipContent>
                              <p>Machine is starting ({machineStatus})</p>
                            </TooltipContent>
                          </Tooltip>
                        ) : (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <div>
                                <AlertCircle className="w-3 h-3 text-red-600" />
                              </div>
                            </TooltipTrigger>
                            <TooltipContent>
                              <p>
                                Machine is {machineStatus}. Start it in the Compute Management page.
                              </p>
                            </TooltipContent>
                          </Tooltip>
                        )}
                      </div>
                    </DropdownMenuItem>
                  );
                })}
              <DropdownMenuSeparator />
            </>
          ) : (
            <>
              <DropdownMenuLabel>Compute Pool Machines</DropdownMenuLabel>
              <DropdownMenuItem disabled>
                <span className="text-xs text-muted-foreground">No machines available</span>
              </DropdownMenuItem>
              <DropdownMenuSeparator />
            </>
          )}

          {/* Databricks Clusters - Show if workspace configured */}
          {databricksConfig.workspaceUrl ? (
            <>
              <DropdownMenuLabel className="flex items-center justify-between">
                <span>Databricks Clusters</span>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      className="p-0.5 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleRefreshDatabricksClusters();
                      }}
                    >
                      <RefreshCw className={`w-3 h-3 ${loadingClusters ? "animate-spin" : ""}`} />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>Refresh clusters</TooltipContent>
                </Tooltip>
              </DropdownMenuLabel>
              {loadingClusters ? (
                <DropdownMenuItem disabled>
                  <PrometheuxSpinner size={16} className="mr-2" />
                  <span className="text-xs">Loading clusters...</span>
                </DropdownMenuItem>
              ) : databricksClusters.length > 0 ? (
                databricksClusters.map((cluster) => {
                  const isSelected =
                    selectedCompute === "databricks" &&
                    databricksConfig.defaultClusterId === cluster.cluster_id;
                  const isRunning = cluster.state === "RUNNING";
                  const key = `databricks-${cluster.cluster_id}`;
                  const isChecking = checkingAvailability[key];
                  const statusResult = availabilityResults[key];
                  const isAvailable = statusResult?.is_available || false;

                  const isDisabled = !isRunning || (statusResult && !isAvailable);

                  return (
                    <DropdownMenuItem
                      key={cluster.cluster_id}
                      onClick={(e) => {
                        if (isDisabled) {
                          e.preventDefault();
                          return;
                        }
                        handleComputeSelection("databricks", undefined, cluster);
                      }}
                      className={`flex items-center justify-between gap-2 ${isDisabled ? "opacity-60" : "cursor-pointer"}`}
                    >
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <div className="flex items-center gap-2 min-w-0 flex-1">
                            <Zap className="w-3 h-3 shrink-0" />
                            <span className="text-xs truncate">
                              {cluster.cluster_name}
                              {isSelected && " (Current)"}
                            </span>
                          </div>
                        </TooltipTrigger>
                        <TooltipContent side="right" className="max-w-xs break-all">
                          <p>{cluster.cluster_name}</p>
                        </TooltipContent>
                      </Tooltip>
                      <div className="flex items-center gap-1 shrink-0">
                        {isRunning && !isChecking && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <button
                                type="button"
                                className="p-0.5 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  e.preventDefault();
                                  checkDatabricksClusterAvailability(cluster);
                                }}
                              >
                                <RefreshCw className="w-2.5 h-2.5" />
                              </button>
                            </TooltipTrigger>
                            <TooltipContent>Refresh status</TooltipContent>
                          </Tooltip>
                        )}
                        {!isRunning ? (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <div>
                                <Badge variant="outline" className="text-xs h-4 px-1">
                                  {cluster.state}
                                </Badge>
                              </div>
                            </TooltipTrigger>
                            <TooltipContent>
                              <p>
                                Cluster must be RUNNING. Go to Compute &gt; Databricks to start it.
                              </p>
                            </TooltipContent>
                          </Tooltip>
                        ) : isChecking ? (
                          <PrometheuxSpinner size={16} />
                        ) : isAvailable ? (
                          <>
                            <Tooltip>
                              <TooltipTrigger asChild>
                                <div>
                                  <CheckCircle className="w-3 h-3 text-green-600" />
                                </div>
                              </TooltipTrigger>
                              <TooltipContent>
                                <p className="max-w-xs whitespace-pre-line">
                                  {statusResult.message || "Ready for execution"}
                                </p>
                              </TooltipContent>
                            </Tooltip>
                            <Tooltip>
                              <TooltipTrigger asChild>
                                <button
                                  onClick={(e) => handleEditCatalog(e, cluster)}
                                  className="p-0.5 hover:bg-accent rounded transition-colors"
                                >
                                  <Pencil className="w-3 h-3 text-muted-foreground hover:text-foreground" />
                                </button>
                              </TooltipTrigger>
                              <TooltipContent>
                                <p>Change catalog</p>
                              </TooltipContent>
                            </Tooltip>
                          </>
                        ) : statusResult ? (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <div>
                                <AlertCircle className="w-3 h-3 text-yellow-600" />
                              </div>
                            </TooltipTrigger>
                            <TooltipContent>
                              <p className="max-w-xs whitespace-pre-line">
                                {statusResult.message || "Cluster is not available for execution"}
                              </p>
                            </TooltipContent>
                          </Tooltip>
                        ) : null}
                      </div>
                    </DropdownMenuItem>
                  );
                })
              ) : (
                <DropdownMenuItem disabled>
                  <span className="text-xs text-muted-foreground">No clusters found</span>
                </DropdownMenuItem>
              )}
            </>
          ) : null}

          {/* Fallback message if nothing is available. In Databricks UI mode, only the
              workspace configuration matters since pool machines are hidden from the dropdown. */}
          {(isDatabricksUI
            ? !databricksConfig.workspaceUrl
            : userMachines.length === 0 && !databricksConfig.workspaceUrl) && (
            <DropdownMenuItem disabled>
              <span className="text-xs text-muted-foreground">
                No compute resources available. Configure in Settings.
              </span>
            </DropdownMenuItem>
          )}
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Catalog Selection Modal */}
      <Dialog
        open={showCatalogModal}
        onOpenChange={(open) => {
          setShowCatalogModal(open);
          if (!open) {
            // Reset state when modal closes
            setPendingClusterSelection(null);
            setSelectedCatalogForCluster("");
            setCatalogsForSelection([]);
            setIsEditingCatalog(false);
          }
        }}
      >
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Database className="w-5 h-5" />
              {isEditingCatalog ? "Change Unity Catalog" : "Select Unity Catalog"}
            </DialogTitle>
            <DialogDescription>
              {isEditingCatalog ? (
                <>
                  Change the catalog for cluster{" "}
                  <span className="font-medium">{pendingClusterSelection?.cluster_name}</span>. This
                  will be used for all queries on this cluster.
                </>
              ) : (
                <>
                  A catalog is required for executing queries on Databricks. Please select a catalog
                  to use with cluster{" "}
                  <span className="font-medium">{pendingClusterSelection?.cluster_name}</span>.
                </>
              )}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="catalog-select">Catalog</Label>
              <Select
                value={selectedCatalogForCluster}
                onValueChange={setSelectedCatalogForCluster}
                disabled={loadingCatalogs}
              >
                <SelectTrigger id="catalog-select">
                  <SelectValue
                    placeholder={loadingCatalogs ? "Loading catalogs..." : "Select a catalog"}
                  />
                </SelectTrigger>
                <SelectContent>
                  {catalogsForSelection.length > 0 ? (
                    catalogsForSelection.map((catalog) => (
                      <SelectItem key={catalog.name} value={catalog.name}>
                        {catalog.name}
                      </SelectItem>
                    ))
                  ) : (
                    <SelectItem value="no-catalogs" disabled>
                      No catalogs available
                    </SelectItem>
                  )}
                </SelectContent>
              </Select>
              <p className="text-xs text-muted-foreground">
                This will be saved and used for all queries on this cluster.
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowCatalogModal(false);
                setPendingClusterSelection(null);
                setSelectedCatalogForCluster("");
                setCatalogsForSelection([]);
                setIsEditingCatalog(false);
              }}
            >
              Cancel
            </Button>
            <Button
              onClick={handleCatalogSelection}
              disabled={!selectedCatalogForCluster || loadingCatalogs}
            >
              {loadingCatalogs ? (
                <>
                  <PrometheuxSpinner size={16} className="mr-2" />
                  Loading...
                </>
              ) : (
                "Confirm Selection"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </TooltipProvider>
  );
};

export default ComputeIndicator;
