import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { acceptShare, claimTeamShare, leaveShare, listInbox } from "../api";
import type { AcceptedShare, ClaimResult, InboxEntry, ShareError } from "../types";

// Keep the prefix as a value so other share hooks can invalidate these queries
// without duplicating the literal.
export const SHARE_INBOX_KEY = ["share", "inbox"] as const;
const inboxKey = (userId: string) => [...SHARE_INBOX_KEY, userId] as const;

interface UseShareInboxReturn {
  entries: InboxEntry[];
  isLoading: boolean;
  isFetching: boolean;
  error: ShareError | null;
  refresh: () => Promise<unknown>;
  accept: (shareId: string) => Promise<AcceptedShare>;
  leave: (shareId: string) => Promise<void>;
  // Claims a team share — mints + vaults the member's scoped token. After this
  // the entry flips to openable (needs_claim === false) on the next inbox refetch.
  claim: (shareId: string) => Promise<ClaimResult>;
  isAccepting: boolean;
  isLeaving: boolean;
  isClaiming: boolean;
}

export function useShareInbox(): UseShareInboxReturn {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";

  const query = useQuery<InboxEntry[], ShareError>({
    queryKey: inboxKey(userId),
    queryFn: () => listInbox(supabaseToken),
    enabled: Boolean(userId && supabaseToken),
    // Brief specifies a manual-refresh model: no polling, no window-focus refetch.
    // Refetch on mount + after own mutations keeps the panel consistent.
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const acceptMutation = useMutation<AcceptedShare, ShareError, string>({
    mutationFn: (shareId) => acceptShare(shareId, supabaseToken),
    onSuccess: () => {
      // useProjects re-merges via the inbox React Query cache (useMemo over
      // inbox.entries), so a single invalidation refreshes the picker too.
      queryClient.invalidateQueries({ queryKey: SHARE_INBOX_KEY });
    },
  });

  const leaveMutation = useMutation<void, ShareError, string>({
    mutationFn: (shareId) => leaveShare(shareId, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: SHARE_INBOX_KEY });
    },
  });

  const claimMutation = useMutation<ClaimResult, ShareError, string>({
    mutationFn: (shareId) => claimTeamShare(shareId, supabaseToken),
    onSuccess: () => {
      // Same as accept: the inbox re-merges into useProjects via React Query, so
      // one invalidation flips the row to openable and updates every picker.
      queryClient.invalidateQueries({ queryKey: SHARE_INBOX_KEY });
    },
  });

  return {
    entries: query.data ?? [],
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    refresh: query.refetch,
    accept: acceptMutation.mutateAsync,
    leave: leaveMutation.mutateAsync,
    claim: claimMutation.mutateAsync,
    isAccepting: acceptMutation.isPending,
    isLeaving: leaveMutation.isPending,
    isClaiming: claimMutation.isPending,
  };
}
