// Defensive recovery call — used by the 401/403 self-healing flow when a request to a
// shared project's data routes fails because the share was revoked or expired.
export async function syncShares(supabaseToken: string | null): Promise<SyncResult> {
  return call<SyncResult>("sync shares", () =>
    HttpService.post(
      shareUrl("sync"),
      {},
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

// ── Team-scoped sharing (Phase 2) ───────────────────────────────────────────

// POST /ontologies/share/team — shares a project with an entire team. Caller must
// be an active member of the team (403 otherwise). Paid feature (same gate as
// direct sharing). No token minted up front; members claim on first open.
export async function shareOntologyWithTeam(
  input: ShareTeamInput,
  supabaseToken: string | null,
): Promise<TeamShareSummary> {
  const payload = {
    ontology_id: input.ontologyId,
    recipient_team_id: input.recipientTeamId,
    share_role: input.shareRole,
  };
  return call<TeamShareSummary>("share ontology with team", () =>
    HttpService.post(
      shareUrl("team"),
      payload,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

// POST /ontologies/share/team/revoke — kills every member's token for a team
// share. Accepts either the share_id or the (ontology_id, recipient_team_id)
// pair. Idempotent.
export async function revokeTeamShare(
  input: TeamRevokeInput,
  supabaseToken: string | null,
): Promise<RevokeResult> {
  const payload =
    "shareId" in input
      ? { share_id: input.shareId }
      : { ontology_id: input.ontologyId, recipient_team_id: input.recipientTeamId };
  return call<RevokeResult>("revoke team share", () =>
    HttpService.post(
      shareUrl("team/revoke"),
      payload,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

// POST /ontologies/share/team/claim — member claims a team share, minting and
// vaulting a per-member scoped token (24h). Idempotent (rotates the token).
// Errors: 403 (not a member), 409 (share not active), 400 (you own it).
export async function claimTeamShare(
  shareId: string,
  supabaseToken: string | null,
): Promise<ClaimResult> {
  return call<ClaimResult>("claim team share", () =>
    HttpService.post(
      shareUrl("team/claim"),
      { share_id: shareId },
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

// POST /ontologies/share/team/update-role — changes a team share's role. Members
// converge on the new role at their next sync (≤24h). Idempotent, paid-gated.
export async function updateTeamShareRole(
  shareId: string,
  shareRole: ShareRole,
  supabaseToken: string | null,
): Promise<TeamUpdateRoleResult> {
  return call<TeamUpdateRoleResult>("update team share role", () =>
    HttpService.post(
      shareUrl("team/update-role"),
      { share_id: shareId, share_role: shareRole },
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

// GET /ontologies/share/team/grants — owner-only roster of members who have
// claimed a team share.
export async function listTeamShareGrants(
  supabaseToken: string | null,
  shareId: string,
): Promise<TeamShareGrant[]> {
  const qs = `?share_id=${encodeURIComponent(shareId)}`;
  return call<TeamShareGrant[]>("load team share grants", () =>
    HttpService.get(
      shareUrl(`team/grants${qs}`),
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

// ── Concept-level restrictions ──────────────────────────────────────────────

const restrictionUrl = (): string => shareUrl("concept-restrictions");

export async function setConceptRestriction(
  supabaseToken: string | null,
  input: SetRestrictionInput,
): Promise<ConceptRestriction> {
  return call<ConceptRestriction>("set concept restriction", () =>
    HttpService.post(
      restrictionUrl(),
      input,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

export async function clearConceptRestriction(
  supabaseToken: string | null,
  input: ClearRestrictionInput,
): Promise<void> {
  await call<unknown>("clear concept restriction", () =>
    HttpService.delete(
      restrictionUrl(),
      input,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

export interface ListRestrictionsFilter {
  recipient_sub?: string;
  team_id?: string;
}

export async function listConceptRestrictions(
  supabaseToken: string | null,
  ontologyId: string,
  filter?: ListRestrictionsFilter,
): Promise<ConceptRestriction[]> {
  const params = new URLSearchParams({ ontology_id: ontologyId });
  if (filter?.recipient_sub) params.set("recipient_sub", filter.recipient_sub);
  if (filter?.team_id) params.set("team_id", filter.team_id);
  return call<ConceptRestriction[]>("list concept restrictions", () =>
    HttpService.get(
      `${restrictionUrl()}?${params.toString()}`,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

// ── Per-member project-level role override ──────────────────────────────────

const ontologyRoleUrl = (): string => shareUrl("ontology-role");

// POST /ontologies/share/ontology-role — gives one member a base role different
// from the team's (cascades to all concepts). User subject only.
export async function setOntologyRoleOverride(
  supabaseToken: string | null,
  input: OntologyRoleOverrideInput,
): Promise<OntologyRoleOverride> {
  return call<OntologyRoleOverride>("set ontology role override", () =>
    HttpService.post(
      ontologyRoleUrl(),
      { ontology_id: input.ontologyId, recipient_sub: input.recipientSub, role: input.role },
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

// DELETE /ontologies/share/ontology-role — reverts the member to the team base role.
export async function clearOntologyRoleOverride(
  supabaseToken: string | null,
  input: ClearOntologyRoleInput,
): Promise<void> {
  await call<unknown>("clear ontology role override", () =>
    HttpService.delete(
      ontologyRoleUrl(),
      { ontology_id: input.ontologyId, recipient_sub: input.recipientSub },
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

// ── Team-admin delegation ───────────────────────────────────────────────────

// POST /ontologies/share/team-admin/apply — an owner/admin of the recipient team
// (who is not the project owner) co-manages permissions of a project shared with
// their team. `data` matches the corresponding owner-only endpoint's shape, so
// the caller specifies the expected result type per action.
export async function applyTeamAdminAction<T>(
  supabaseToken: string | null,
  ontologyId: string,
  teamId: string,
  action: TeamAdminAction,
): Promise<T> {
  return call<T>(`apply team-admin ${action.action}`, () =>
    HttpService.post(
      shareUrl("team-admin/apply"),
      { ontology_id: ontologyId, team_id: teamId, ...action },
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}
