import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useMemo, useState } from "react";
import { toast } from "sonner";
import { type ConceptData, ConceptService } from "@/features/concepts/api";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";

export const useConcepts = () => {
  const [isDeletingConcept, setIsDeletingConcept] = useState(false);

  const ontologyId = useOntologyId();
  const ontologyScope = useOntologyScope();
  const queryClient = useQueryClient();

  // Fetch concepts from API
  const {
    data: concepts,
    isLoading,
    isError,
    error,
    refetch,
  } = useQuery<ConceptData[], Error>({
    queryKey: ["concepts", ontologyId, ontologyScope],
    queryFn: () => {
      if (!ontologyId) {
        throw new Error("No ontology ID available");
      }
      return ConceptService.listConcepts(ontologyId, ontologyScope);
    },
    enabled: !!ontologyId,
    staleTime: 60000, // 60 seconds
    // refetchOnWindowFocus: true, // Commented out to reduce API calls
    retry: 2,
  });

  const loadConcepts = useCallback(
    async (force: boolean = false) => {
      try {
        if (force) {
          await queryClient.invalidateQueries({
            queryKey: ["concepts", ontologyId, ontologyScope],
          });
        }
        await refetch();
      } catch (error) {
        console.error("Error loading concepts:", error);
        throw error;
      }
    },
    [refetch, queryClient, ontologyId, ontologyScope],
  );

  const deleteConcept = useCallback(
    async (conceptName: string) => {
      if (!ontologyId) {
        toast.error("No ontology ID available");
        return false;
      }

      setIsDeletingConcept(true);
      try {
        await ConceptService.deleteConcepts(ontologyId, [conceptName], ontologyScope);

        // Invalidate and refetch concepts
        await queryClient.invalidateQueries({ queryKey: ["concepts", ontologyId, ontologyScope] });
        await refetch();

        toast.success(`Concept "${conceptName}" deleted successfully`);
        return true;
      } catch (error) {
        console.error("Error deleting concept:", error);
        toast.error(error instanceof Error ? error.message : "Failed to delete concept");
        return false;
      } finally {
        setIsDeletingConcept(false);
      }
    },
    [ontologyId, ontologyScope, queryClient, refetch],
  );

  const deleteConcepts = useCallback(
    async (conceptNames: string[]) => {
      if (!ontologyId) {
        toast.error("No ontology ID available");
        return false;
      }

      if (!conceptNames || conceptNames.length === 0) {
        toast.error("No concepts selected for deletion");
        return false;
      }

      setIsDeletingConcept(true);
      try {
        await ConceptService.deleteConcepts(ontologyId, conceptNames, ontologyScope);

        // Invalidate and refetch concepts
        await queryClient.invalidateQueries({ queryKey: ["concepts", ontologyId, ontologyScope] });
        await refetch();

        return true;
      } catch (error) {
        console.error("Error deleting concepts:", error);
        toast.error(error instanceof Error ? error.message : "Failed to delete concepts");
        return false;
      } finally {
        setIsDeletingConcept(false);
      }
    },
    [ontologyId, ontologyScope, queryClient, refetch],
  );

  // Memoize the concepts array to prevent unnecessary re-renders
  const memoizedConcepts = useMemo(() => concepts || [], [concepts]);

  return {
    concepts: memoizedConcepts,
    isLoading,
    isError,
    error,
    isDeletingConcept,
    loadConcepts,
    deleteConcept,
    deleteConcepts,
    refetch,
  };
};
