import { type RefObject, useCallback, useRef, useState } from "react";
import type { ImperativePanelHandle } from "react-resizable-panels";
import { type DefaultCellView, usePreferencesStore } from "@/shared/store/preferencesStore";
import type { ExplorerBottomTab } from "@/shared/utils/explorerPreferences";

// Map the user's enforced default cell view preference onto the dock's bottom
// tab. "code" -> the logic editor, "description" -> the context tab. Any other
// value is unreachable for the preference type but defaults to the editor.
function preferenceToTab(view: DefaultCellView): ExplorerBottomTab {
  return view === "description" ? "context" : "logic";
}

// Default dock height as a percentage of the vertical panel group.
export const DOCK_DEFAULT_PCT = 40;

interface UseLineageEditorDockReturn {
  /** Imperative handle for the canvas panel — collapsing it lets the dock fill the view. */
  canvasPanelRef: RefObject<ImperativePanelHandle>;
  /** Whether the dock is maximized (canvas collapsed, dock fills the whole view). */
  isMaximized: boolean;
  /** Toggle between maximized (canvas collapsed) and the default split. */
  toggleMaximize: () => void;
  /** Restore the default split (canvas visible again). */
  restore: () => void;
  /** Keep `isMaximized` in sync when the canvas collapses/expands by any means. */
  onCanvasCollapse: () => void;
  onCanvasExpand: () => void;
  /** Current bottom tab (description / logic / engine / output) for the editor. */
  bottomTab: ExplorerBottomTab;
  setBottomTab: (view: ExplorerBottomTab) => void;
}

/**
 * Owns the single lineage editor dock's UI state: maximize (by collapsing the
 * canvas panel so the dock takes the full view height) and the bottom-tab
 * selection. There is no separate full-screen mode — the dock is one panel that
 * resizes, and "maximize" simply collapses the canvas above it.
 *
 * The initial bottom tab is enforced by the user's `defaultCellView`
 * preference. In-session switching updates local state only and does not
 * override the preference on the next open.
 */
export function useLineageEditorDock(): UseLineageEditorDockReturn {
  const canvasPanelRef = useRef<ImperativePanelHandle>(null);
  const [isMaximized, setIsMaximized] = useState(false);
  const [bottomTab, setBottomTabState] = useState<ExplorerBottomTab>(() =>
    preferenceToTab(usePreferencesStore.getState().defaultCellView),
  );

  const setBottomTab = useCallback((view: ExplorerBottomTab) => {
    setBottomTabState(view);
  }, []);

  const toggleMaximize = useCallback(() => {
    const panel = canvasPanelRef.current;
    if (!panel) return;
    if (panel.isCollapsed()) panel.expand();
    else panel.collapse();
  }, []);

  const restore = useCallback(() => canvasPanelRef.current?.expand(), []);

  const onCanvasCollapse = useCallback(() => setIsMaximized(true), []);
  const onCanvasExpand = useCallback(() => setIsMaximized(false), []);

  return {
    canvasPanelRef,
    isMaximized,
    toggleMaximize,
    restore,
    onCanvasCollapse,
    onCanvasExpand,
    bottomTab,
    setBottomTab,
  };
}
