import type {
  AppDefinition,
  AppInputDef,
  AppPageDef,
  AppSectionDef,
  AppWidgetDef,
  RunGroupDef,
} from "../schema/appDefinition.types";
import { isLegacyWidget } from "../schema/appDefinition.types";

/**
 * Pure, immutable mutation helpers for the editor draft. Every function
 * returns a new definition; unknown ids return the input unchanged so the
 * store never has to guard against stale selections.
 */

export function nextId(prefix: string, existing: string[]): string {
  const taken = new Set(existing);
  let counter = 1;
  while (taken.has(`${prefix}_${counter}`)) counter += 1;
  return `${prefix}_${counter}`;
}

export function mapPage(
  definition: AppDefinition,
  pageId: string,
  update: (page: AppPageDef) => AppPageDef,
): AppDefinition {
  return {
    ...definition,
    pages: definition.pages.map((page) => (page.id === pageId ? update(page) : page)),
  };
}

/** Map every input of a page — form-field mutations build on this. */
export function patchPageInputs(
  definition: AppDefinition,
  pageId: string,
  update: (input: AppInputDef) => AppInputDef,
): AppDefinition {
  return mapPage(definition, pageId, (page) => ({ ...page, inputs: page.inputs.map(update) }));
}

export function patchApp(definition: AppDefinition, patch: Partial<AppDefinition>): AppDefinition {
  return { ...definition, ...patch };
}

export function patchPage(
  definition: AppDefinition,
  pageId: string,
  patch: Partial<AppPageDef>,
): AppDefinition {
  return mapPage(definition, pageId, (page) => ({ ...page, ...patch }));
}

export function patchSection(
  definition: AppDefinition,
  pageId: string,
  sectionId: string,
  patch: Partial<AppSectionDef>,
): AppDefinition {
  return mapPage(definition, pageId, (page) => ({
    ...page,
    sections: page.sections.map((section) =>
      section.id === sectionId ? { ...section, ...patch } : section,
    ),
  }));
}

export function patchWidget(
  definition: AppDefinition,
  pageId: string,
  sectionId: string,
  widgetId: string,
  patch: Partial<AppWidgetDef>,
): AppDefinition {
  return mapPage(definition, pageId, (page) => ({
    ...page,
    sections: page.sections.map((section) => {
      if (section.id !== sectionId) return section;
      return {
        ...section,
        widgets: section.widgets.map((widget) =>
          !isLegacyWidget(widget) && widget.id === widgetId ? { ...widget, ...patch } : widget,
        ),
      };
    }),
  }));
}

export function patchInput(
  definition: AppDefinition,
  pageId: string,
  inputId: string,
  patch: Partial<AppInputDef>,
): AppDefinition {
  return mapPage(definition, pageId, (page) => ({
    ...page,
    inputs: page.inputs.map((input) => (input.id === inputId ? { ...input, ...patch } : input)),
  }));
}

export function patchRunGroup(
  definition: AppDefinition,
  pageId: string,
  groupId: string,
  patch: Partial<RunGroupDef>,
): AppDefinition {
  return mapPage(definition, pageId, (page) => ({
    ...page,
    runGroups: page.runGroups.map((group) =>
      group.id === groupId ? { ...group, ...patch } : group,
    ),
  }));
}

// ── Add ────────────────────────────────────────────────────────────────────

export function addPage(definition: AppDefinition, ontologyId: string): AppDefinition {
  const id = nextId(
    "page",
    definition.pages.map((page) => page.id),
  );
  const page: AppPageDef = {
    id,
    label: "New page",
    project: { id: ontologyId },
    inputs: [],
    runGroups: [],
    sections: [],
  };
  return { ...definition, pages: [...definition.pages, page] };
}

export function addSection(definition: AppDefinition, pageId: string): AppDefinition {
  return mapPage(definition, pageId, (page) => {
    const id = nextId(
      "section",
      page.sections.map((section) => section.id),
    );
    return { ...page, sections: [...page.sections, { id, layout: "grid", widgets: [] }] };
  });
}

export function addWidget(
  definition: AppDefinition,
  pageId: string,
  sectionId: string,
  widget: Omit<AppWidgetDef, "id">,
): AppDefinition {
  return mapPage(definition, pageId, (page) => {
    const existingIds = page.sections.flatMap((section) =>
      section.widgets.filter((w): w is AppWidgetDef => !isLegacyWidget(w)).map((w) => w.id),
    );
    const id = nextId(widget.type, existingIds);
    return {
      ...page,
      sections: page.sections.map((section) =>
        section.id === sectionId
          ? { ...section, widgets: [...section.widgets, { ...widget, id }] }
          : section,
      ),
    };
  });
}

export function addInput(
  definition: AppDefinition,
  pageId: string,
  input: Omit<AppInputDef, "id">,
): AppDefinition {
  return mapPage(definition, pageId, (page) => {
    const id = nextId(
      input.type === "form" ? "form" : "input",
      page.inputs.map((candidate) => candidate.id),
    );
    return { ...page, inputs: [...page.inputs, { ...input, id }] };
  });
}

/** Fresh input definition shared by every "create an input" entry point. */
export function defaultInputFor(type: "text" | "form"): Omit<AppInputDef, "id"> {
  if (type === "form") return { type: "form", label: "New form", sections: [{ fields: [] }] };
  return { type: "text", label: "New input" };
}

/**
 * One-step form placement: create the backing form input and a form_ref
 * widget bound to it, so its fields are immediately editable in the outline.
 */
export function addFormWidget(
  definition: AppDefinition,
  pageId: string,
  sectionId: string,
): AppDefinition {
  const withInput = addInput(definition, pageId, defaultInputFor("form"));
  const inputId = withInput.pages.find((page) => page.id === pageId)?.inputs.at(-1)?.id;
  if (!inputId) return definition;
  return addWidget(withInput, pageId, sectionId, { type: "form_ref", span: 12, inputId });
}

export function addRunGroup(definition: AppDefinition, pageId: string): AppDefinition {
  return mapPage(definition, pageId, (page) => {
    const id = nextId(
      "group",
      page.runGroups.map((group) => group.id),
    );
    const group: RunGroupDef = { id, trigger: "button", execute: [], outputs: [] };
    return { ...page, runGroups: [...page.runGroups, group] };
  });
}

// ── Reorder ────────────────────────────────────────────────────────────────

export function moveItem<T>(items: T[], index: number, direction: -1 | 1): T[] {
  const target = index + direction;
  if (index < 0 || target < 0 || target >= items.length) return items;
  const next = [...items];
  [next[index], next[target]] = [next[target], next[index]];
  return next;
}

export function moveSection(
  definition: AppDefinition,
  pageId: string,
  sectionId: string,
  direction: -1 | 1,
): AppDefinition {
  return mapPage(definition, pageId, (page) => ({
    ...page,
    sections: moveItem(
      page.sections,
      page.sections.findIndex((section) => section.id === sectionId),
      direction,
    ),
  }));
}

export function moveWidget(
  definition: AppDefinition,
  pageId: string,
  sectionId: string,
  widgetId: string,
  direction: -1 | 1,
): AppDefinition {
  return mapPage(definition, pageId, (page) => ({
    ...page,
    sections: page.sections.map((section) => {
      if (section.id !== sectionId) return section;
      const index = section.widgets.findIndex(
        (widget) => !isLegacyWidget(widget) && widget.id === widgetId,
      );
      return { ...section, widgets: moveItem(section.widgets, index, direction) };
    }),
  }));
}

export function movePage(
  definition: AppDefinition,
  pageId: string,
  direction: -1 | 1,
): AppDefinition {
  return {
    ...definition,
    pages: moveItem(
      definition.pages,
      definition.pages.findIndex((page) => page.id === pageId),
      direction,
    ),
  };
}
