import { AlertCircle } from "lucide-react";
import { Alert, AlertDescription } from "@/shared/components/ui/alert";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import type { FetchResult } from "../../api/ConceptClient";
import { type FormValues, FormWidget } from "../../forms/FormWidget";
import { type GroupRunState, isGroupBusy } from "../../runtime/useRunGroups";
import type { AppPageDef, AppWidgetDef } from "../../schema/appDefinition.types";
import type { BoundTableHandlers } from "../outputs/table/tableOutput.types";
import { ButtonWidget } from "./widgets/ButtonWidget";
import { ChartV2Widget } from "./widgets/ChartV2Widget";
import { HeatmapWidget } from "./widgets/HeatmapWidget";
import { InputRefWidget } from "./widgets/InputRefWidget";
import { RichTableWidget } from "./widgets/RichTableWidget";
import { RunButtonWidget } from "./widgets/RunButtonWidget";
import { StatCardV2Widget } from "./widgets/StatCardV2Widget";
import { TextWidget } from "./widgets/TextWidget";
import { UnboundWidgetPlaceholder } from "./widgets/UnboundWidgetPlaceholder";

export interface TabRuntime {
  page: AppPageDef;
  ontologyId: string;
  tapData: Record<string, FetchResult | null>;
  tapLoading: Record<string, boolean>;
  tapErrors: Record<string, string>;
  groupState: Record<string, GroupRunState>;
  groupErrors: Record<string, string>;
  runGroup: (groupId: string, extraValues?: Record<string, unknown>) => Promise<void>;
  cancelGroup: (groupId: string) => void;
  handlersForTap: (tapId: string) => BoundTableHandlers;
  onSubmitForm: (formId: string, values: FormValues) => void;
}

interface AppWidgetRendererProps {
  widget: AppWidgetDef;
  runtime: TabRuntime;
}

function TapPlaceholder({
  loading,
  waiting,
  error,
}: {
  loading: boolean;
  waiting?: boolean;
  error?: string;
}) {
  if (waiting) {
    return (
      <div className="flex items-center gap-2 py-6 text-amber-700 dark:text-amber-400 text-sm">
        <PrometheuxSpinner size={16} />
        Waiting for the engine to free up… it will run automatically.
      </div>
    );
  }
  if (loading) {
    return (
      <div className="flex items-center gap-2 py-6 text-muted-foreground text-sm">
        <PrometheuxSpinner size={16} />
        Loading…
      </div>
    );
  }
  if (error) {
    return (
      <Alert variant="destructive">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>{error}</AlertDescription>
      </Alert>
    );
  }
  return <p className="text-xs text-muted-foreground py-4">–</p>;
}

export function AppWidgetRenderer({ widget, runtime }: AppWidgetRendererProps) {
  const { page, ontologyId } = runtime;

  if (widget.type === "input_ref" || widget.type === "form_ref") {
    const input = page.inputs.find((candidate) => candidate.id === widget.inputId);
    if (!input) {
      return (
        <UnboundWidgetPlaceholder
          kind={widget.type === "form_ref" ? "form" : "input"}
          label={widget.label}
        />
      );
    }
    if (input.type === "form") {
      const boundGroup = page.runGroups.find(
        (group) => group.trigger === "form" && group.formId === input.id,
      );
      return (
        <FormWidget
          input={input}
          ontologyId={ontologyId}
          isRunning={boundGroup ? isGroupBusy(runtime.groupState[boundGroup.id]) : false}
          runError={boundGroup ? runtime.groupErrors[boundGroup.id] : undefined}
          onSubmitForm={runtime.onSubmitForm}
        />
      );
    }
    return <InputRefWidget input={input} ontologyId={ontologyId} />;
  }

  if (widget.type === "text" && widget.content && !widget.outputId) {
    return <TextWidget content={widget.content} />;
  }

  if (widget.type === "button") {
    return (
      <ButtonWidget widget={widget} onRunGroup={(groupId) => void runtime.runGroup(groupId)} />
    );
  }

  if (widget.type === "run_button") {
    const group = page.runGroups.find((candidate) => candidate.id === widget.groupId);
    const handleRun = () => {
      if (group) void runtime.runGroup(group.id);
    };
    return (
      <RunButtonWidget
        label={widget.label ?? group?.label ?? "Run"}
        unbound={!group}
        state={group ? (runtime.groupState[group.id] ?? "idle") : "idle"}
        error={group ? runtime.groupErrors[group.id] : undefined}
        onRun={handleRun}
        onCancel={group ? () => runtime.cancelGroup(group.id) : undefined}
      />
    );
  }

  const tapId = widget.outputId ?? "";
  const data = runtime.tapData[tapId];
  if (!data) {
    // A tap has no data of its own until its group runs. Surface the owning
    // group's running/error state so an auto/load group that failed (e.g. its
    // concept was deleted) shows the reason instead of the empty placeholder.
    const owningGroup = page.runGroups.find((group) =>
      (group.outputs ?? []).some((tap) => tap.id === tapId),
    );
    const owningState = owningGroup ? runtime.groupState[owningGroup.id] : undefined;
    const groupError = owningGroup ? runtime.groupErrors[owningGroup.id] : undefined;
    return (
      <TapPlaceholder
        loading={(runtime.tapLoading[tapId] ?? false) || owningState === "running"}
        waiting={owningState === "waiting"}
        error={runtime.tapErrors[tapId] || groupError}
      />
    );
  }

  switch (widget.type) {
    case "rich_table":
      return (
        <RichTableWidget widget={widget} data={data} handlers={runtime.handlersForTap(tapId)} />
      );
    case "text":
      return <TextWidget data={data} />;
    case "heatmap":
      return <HeatmapWidget widget={widget} data={data} />;
    case "stat_card":
      return <StatCardV2Widget widget={widget} data={data} />;
    case "line_chart":
    case "area_chart":
    case "bar_chart":
    case "pie_chart":
      return <ChartV2Widget widget={widget} data={data} />;
    default:
      return <p className="text-xs text-muted-foreground">Unknown widget type: {widget.type}</p>;
  }
}
