import {
  type Dispatch,
  type SetStateAction,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { toast } from "sonner";
import {
  APP_CONTEXT_DATA_KEY,
  type AppPrincipalContext,
} from "@/features/auth/hooks/useDatabricksAppContext";
import {
  DatabricksConfigService,
  DatabricksService,
} from "@/features/compute/api/databricksService";
import type { DatabricksCatalog, DatabricksCluster } from "@/features/compute/types";
import { normalizeDatabricksTables } from "@/features/data-sources/databricks.utils";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

/**
 * Minimal shape of a Unity Catalog schema as returned by the Databricks API.
 * The UI only consumes `name`; other fields are intentionally not modelled
 * here to avoid drift with the backend payload.
 */
export interface DatabricksSchema {
  name: string;
  [extra: string]: unknown;
}

/**
 * Minimal shape of a Unity Catalog table as returned by the Databricks API.
 * The UI only consumes `name`; other metadata fields (table_type, comment,
 * etc.) are passed through as `unknown` so the type doesn't drift.
 */
export interface DatabricksTable {
  name: string;
  [extra: string]: unknown;
}

interface DatabricksLoginConfig {
  mainConfig: ReturnType<typeof DatabricksConfigService.getConfig>;
  hasToken: boolean;
  isExpired: boolean;
  isOAuth: boolean;
}

export interface UseDatabricksConnectionArgs {
  /** True when the surrounding form is currently configuring a Databricks data source. */
  isActive: boolean;
  /** Currently-selected catalog name from the form (drives schema auto-load). */
  selectedCatalog: string;
  /** Currently-selected schema name from the form (drives table auto-load). */
  selectedSchema: string;
}

export interface UseDatabricksConnectionResult {
  // ---- Auth + connection state ----
  authMethod: string;
  setAuthMethod: Dispatch<SetStateAction<string>>;
  connectionMode: "jdbc" | "in-cluster";
  setConnectionMode: Dispatch<SetStateAction<"jdbc" | "in-cluster">>;
  /** True for auth methods that pull credentials from the central DatabricksConfigService. */
  authUsesMainConfig: boolean;
  appPrincipalCtx: AppPrincipalContext | null;

  // ---- Per-form credential state (only used when authUsesMainConfig is false) ----
  workspaceUrl: string;
  setWorkspaceUrl: Dispatch<SetStateAction<string>>;
  pat: string;
  setPat: Dispatch<SetStateAction<string>>;
  oauthClientId: string;
  setOauthClientId: Dispatch<SetStateAction<string>>;
  oauthSecret: string;
  setOauthSecret: Dispatch<SetStateAction<string>>;

  // ---- Loaded data + loading flags ----
  clusters: DatabricksCluster[];
  setClusters: Dispatch<SetStateAction<DatabricksCluster[]>>;
  catalogs: DatabricksCatalog[];
  setCatalogs: Dispatch<SetStateAction<DatabricksCatalog[]>>;
  schemas: DatabricksSchema[];
  setSchemas: Dispatch<SetStateAction<DatabricksSchema[]>>;
  tables: DatabricksTable[];
  setTables: Dispatch<SetStateAction<DatabricksTable[]>>;
  loadingClusters: boolean;
  loadingCatalogs: boolean;
  loadingSchemas: boolean;
  loadingTables: boolean;

  // ---- Helpers ----
  getLoginConfig: () => DatabricksLoginConfig;
  withTempConfig: <T>(fn: () => Promise<T>) => Promise<T>;
  loadClusters: () => Promise<void>;
  loadCatalogs: () => Promise<void>;
  loadSchemas: (catalogName: string) => Promise<void>;
  loadTables: (catalogName: string, schemaName: string) => Promise<void>;
}

/**
 * Holds all Databricks-specific state and side-effects for the data-source
 * connection forms. Extracted from `SchemaInferenceForm` to keep that file
 * focused on its primary job (composing the form for every database type).
 *
 * The hook owns:
 *   - Auth method, connection mode (`jdbc` | `in-cluster`), and per-form
 *     credential state.
 *   - The lists of clusters / catalogs / schemas plus their loading flags.
 *   - Two auto-load effects keyed on `isActive` and `selectedCatalog`.
 *   - A monotonically incremented request id so a stale `listSchemas`
 *     response can't overwrite a fresher one when the user rapidly switches
 *     catalogs.
 */
export function useDatabricksConnection({
  isActive,
  selectedCatalog,
  selectedSchema,
}: UseDatabricksConnectionArgs): UseDatabricksConnectionResult {
  // -------------------------- Auth + connection state --------------------------
  const [authMethod, setAuthMethod] = useState<string>(() => {
    // In the 3P app, if the user has already configured OAuth2 (Service
    // Principal) credentials on the Compute page, default this form to
    // OAuth2 too so the workspace URL and client ID flow through. The
    // legacy "app_principal" default (bearer minted by useDatabricksAppContext)
    // was removed in v1.0.3 — its OBO token expired in 1h with no auto-refresh.
    if (PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) {
      const cfg = DatabricksConfigService.getConfig();
      if (cfg.authMode === "oauth2" && cfg.clientId) return "oauth2";
    }
    return "personal_access_token";
  });
  const [connectionMode, setConnectionMode] = useState<"jdbc" | "in-cluster">("jdbc");

  const authUsesMainConfig = authMethod === "databricks_login";

  // Read-only display data for the App Service Principal panel. Persisted by
  // useDatabricksAppContext. Re-reads when authMethod changes so the autofill
  // shown in a separate tab is reflected on the current form.
  // biome-ignore lint/correctness/useExhaustiveDependencies: authMethod is the intentional re-read trigger; the memo body has no other reactive inputs.
  const appPrincipalCtx = useMemo<AppPrincipalContext | null>(() => {
    if (!PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) return null;
    try {
      const raw = localStorage.getItem(APP_CONTEXT_DATA_KEY);
      return raw ? (JSON.parse(raw) as AppPrincipalContext) : null;
    } catch {
      return null;
    }
  }, [authMethod]);

  // -------------------------- Credential state --------------------------
  // In 3P + OAuth2 mode, pre-fill from the central config (which itself was
  // autofilled by useDatabricksAppContext with the App SP's workspaceUrl +
  // clientId, plus the secret the user pasted on the Compute page). Users
  // can still override any field per-form.
  const [workspaceUrl, setWorkspaceUrl] = useState<string>(() => {
    if (PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) {
      const cfg = DatabricksConfigService.getConfig();
      if (cfg.authMode === "oauth2" && cfg.workspaceUrl) return cfg.workspaceUrl;
    }
    return "";
  });
  const [pat, setPat] = useState("");
  const [oauthClientId, setOauthClientId] = useState<string>(() => {
    if (PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) {
      const cfg = DatabricksConfigService.getConfig();
      if (cfg.authMode === "oauth2" && cfg.clientId) return cfg.clientId;
    }
    return "";
  });
  const [oauthSecret, setOauthSecret] = useState<string>(() => {
    if (PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) {
      const cfg = DatabricksConfigService.getConfig();
      if (cfg.authMode === "oauth2" && cfg.clientSecret) return cfg.clientSecret;
    }
    return "";
  });

  // Track the last values we pulled from the central config so we can
  // detect, on a subsequent `databricksConfigChanged` event, whether the
  // local field was edited by the user (diverged from the last sync) or
  // is still in lockstep with the central config and safe to overwrite.
  // This gives us "soft" two-way sync: edits on the Compute page propagate
  // here automatically, but a user's in-progress local edits are never
  // clobbered.
  const lastSyncedFromCentralRef = useRef<{
    workspaceUrl: string;
    clientId: string;
    clientSecret: string;
  }>({
    workspaceUrl,
    clientId: oauthClientId,
    clientSecret: oauthSecret,
  });

  // -------------------------- Loaded data + loading flags --------------------------
  const [clusters, setClusters] = useState<DatabricksCluster[]>([]);
  const [catalogs, setCatalogs] = useState<DatabricksCatalog[]>([]);
  const [schemas, setSchemas] = useState<DatabricksSchema[]>([]);
  const [tables, setTables] = useState<DatabricksTable[]>([]);
  const [loadingClusters, setLoadingClusters] = useState(false);
  const [loadingCatalogs, setLoadingCatalogs] = useState(false);
  const [loadingSchemas, setLoadingSchemas] = useState(false);
  const [loadingTables, setLoadingTables] = useState(false);

  // -------------------------- Helpers --------------------------
  // Reads only from the DatabricksConfigService module (no React state),
  // so memoized with empty deps to provide a stable reference for effects
  // and callbacks that depend on it.
  const getLoginConfig = useCallback((): DatabricksLoginConfig => {
    const mainConfig = DatabricksConfigService.getConfig();
    const hasToken = mainConfig.token && mainConfig.workspaceUrl;
    const isExpired = mainConfig.oauthExpiresAt
      ? mainConfig.oauthExpiresAt - Date.now() < 5 * 60 * 1000
      : false;
    return { mainConfig, hasToken: !!hasToken, isExpired, isOAuth: !!mainConfig.isOAuthToken };
  }, []);

  // Soft sync of OAuth2 credentials from the central DatabricksConfigService.
  // Fires when the Compute page (or useDatabricksAppContext) updates the
  // config. For each field, we only overwrite the local state if the user
  // hasn't typed a different value since the last sync; this lets edits
  // propagate across pages while protecting in-progress input.
  // Only active in 3P + OAuth2 mode — the original non-3P UX (per-form
  // independent credentials) is preserved.
  // biome-ignore lint/correctness/useExhaustiveDependencies: ref reads are intentionally not reactive; state setters are stable.
  useEffect(() => {
    if (!PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) return;
    if (authMethod !== "oauth2") return;

    const sync = () => {
      const cfg = DatabricksConfigService.getConfig();
      if (cfg.authMode !== "oauth2") return;
      const last = lastSyncedFromCentralRef.current;
      const nextWs = cfg.workspaceUrl || "";
      const nextId = cfg.clientId || "";
      const nextSecret = cfg.clientSecret || "";

      setWorkspaceUrl((cur) => (cur === last.workspaceUrl ? nextWs : cur));
      setOauthClientId((cur) => (cur === last.clientId ? nextId : cur));
      setOauthSecret((cur) => (cur === last.clientSecret ? nextSecret : cur));

      lastSyncedFromCentralRef.current = {
        workspaceUrl: nextWs,
        clientId: nextId,
        clientSecret: nextSecret,
      };
    };

    // Also run once on mount / auth-method switch so that flipping the
    // dropdown from PAT → OAuth2 immediately pulls the latest creds.
    sync();
    window.addEventListener("databricksConfigChanged", sync);
    return () => window.removeEventListener("databricksConfigChanged", sync);
  }, [authMethod]);

  // Execute a function with temporary Databricks config, then restore original.
  // For 'databricks_login' / 'app_principal' the main config is already correct
  // and no swap is needed. Memoized so callers that depend on this keep a
  // stable reference across renders — otherwise effects keyed on those callers
  // re-fire on every render and trigger overlapping API requests that race.
  const withTempConfig = useCallback(
    async <T>(fn: () => Promise<T>): Promise<T> => {
      if (authUsesMainConfig) {
        return await fn();
      }

      const originalConfig = DatabricksConfigService.getConfig();
      try {
        const tempAuthMode = authMethod === "personal_access_token" ? "token" : "oauth2";
        const tempConfig = {
          ...originalConfig,
          workspaceUrl,
          authMode: tempAuthMode as "token" | "oauth2",
          token: tempAuthMode === "token" ? pat : undefined,
          clientId: tempAuthMode === "oauth2" ? oauthClientId : undefined,
          clientSecret: tempAuthMode === "oauth2" ? oauthSecret : undefined,
        };
        DatabricksConfigService.saveConfig(tempConfig);

        return await fn();
      } finally {
        DatabricksConfigService.saveConfig(originalConfig);
      }
    },
    [authUsesMainConfig, authMethod, workspaceUrl, pat, oauthClientId, oauthSecret],
  );

  // -------------------------- Loaders --------------------------
  const loadClusters = useCallback(async () => {
    if (authUsesMainConfig) {
      const { hasToken, isExpired } = getLoginConfig();
      if (!hasToken || isExpired) {
        toast.error(
          "No active Databricks session. Go to Compute → Databricks → Authentication and click Login with Databricks.",
        );
        return;
      }
    } else {
      if (!workspaceUrl) {
        toast.error("Please enter Workspace URL first");
        return;
      }
      const authMode = authMethod === "personal_access_token" ? "token" : "oauth2";
      if (authMode === "token" && !pat) {
        toast.error("Please enter Personal Access Token first");
        return;
      }
      if (authMode === "oauth2" && (!oauthClientId || !oauthSecret)) {
        toast.error("Please enter OAuth2 Client ID and Secret first");
        return;
      }
    }

    const effectiveAuthMode = authUsesMainConfig
      ? "token"
      : authMethod === "personal_access_token"
        ? "token"
        : "oauth2";

    setLoadingClusters(true);
    try {
      const fetched = await withTempConfig(async () => {
        const databricksService = new DatabricksService();
        return await databricksService.listClusters(effectiveAuthMode);
      });

      setClusters(fetched || []);
      if (!fetched || fetched.length === 0) {
        toast.info("No clusters found");
      }
    } catch (error) {
      console.error("Error loading clusters:", error);
      toast.error("Failed to load clusters. Check your credentials.");
      setClusters([]);
    } finally {
      setLoadingClusters(false);
    }
  }, [
    authUsesMainConfig,
    authMethod,
    workspaceUrl,
    pat,
    oauthClientId,
    oauthSecret,
    withTempConfig,
    getLoginConfig,
  ]);

  const loadCatalogs = useCallback(async () => {
    // Mirror `loadClusters`: surface a toast when the user is missing the
    // prerequisite credentials. This used to be silent because the loader
    // was driven by an auto-effect; it's now button-triggered, so the user
    // expects feedback.
    if (authUsesMainConfig) {
      const { hasToken, isExpired } = getLoginConfig();
      if (!hasToken || isExpired) {
        toast.error(
          "No active Databricks session. Go to Compute → Databricks → Authentication and click Login with Databricks.",
        );
        return;
      }
    } else {
      if (!workspaceUrl) {
        toast.error("Please enter Workspace URL first");
        return;
      }
      const authMode = authMethod === "personal_access_token" ? "token" : "oauth2";
      if (authMode === "token" && !pat) {
        toast.error("Please enter Personal Access Token first");
        return;
      }
      if (authMode === "oauth2" && (!oauthClientId || !oauthSecret)) {
        toast.error("Please enter OAuth2 Client ID and Secret first");
        return;
      }
    }

    setLoadingCatalogs(true);
    try {
      const fetched = await withTempConfig(async () => {
        const databricksService = new DatabricksService();
        return await databricksService.listCatalogs();
      });

      setCatalogs(fetched || []);
      if (!fetched || fetched.length === 0) {
        toast.info("No catalogs found");
      }
    } catch (error) {
      console.error("Error loading catalogs:", error);
      toast.error("Failed to load catalogs");
      setCatalogs([]);
    } finally {
      setLoadingCatalogs(false);
    }
  }, [
    authUsesMainConfig,
    authMethod,
    workspaceUrl,
    pat,
    oauthClientId,
    oauthSecret,
    withTempConfig,
    getLoginConfig,
  ]);

  // Monotonically incremented per schemas request — used to discard stale
  // responses so a slow reply from a previous catalog can't overwrite the
  // freshly loaded schemas for the catalog the user just selected.
  const schemasRequestIdRef = useRef(0);

  const loadSchemas = useCallback(
    async (catalogName: string) => {
      if (!catalogName) {
        setSchemas([]);
        return;
      }

      const requestId = ++schemasRequestIdRef.current;
      setLoadingSchemas(true);
      try {
        const fetched = await withTempConfig(async () => {
          const databricksService = new DatabricksService();
          return (await databricksService.listSchemas(catalogName)) as DatabricksSchema[];
        });

        if (requestId !== schemasRequestIdRef.current) return;
        setSchemas(fetched || []);
      } catch (error) {
        if (requestId !== schemasRequestIdRef.current) return;
        console.error("Error loading schemas:", error);
        toast.error("Failed to load schemas");
        setSchemas([]);
      } finally {
        if (requestId === schemasRequestIdRef.current) {
          setLoadingSchemas(false);
        }
      }
    },
    [withTempConfig],
  );

  // Same stale-request guard pattern as schemas — switching catalog or schema
  // rapidly could otherwise let an older `listTables` response overwrite a
  // newer one.
  const tablesRequestIdRef = useRef(0);

  const loadTables = useCallback(
    async (catalogName: string, schemaName: string) => {
      if (!catalogName || !schemaName) {
        setTables([]);
        return;
      }

      // Mirror `loadCatalogs`: surface a toast when the user is missing the
      // prerequisite credentials. The loader is button-triggered, so the user
      // expects explicit feedback rather than a silent no-op.
      if (authUsesMainConfig) {
        const { hasToken, isExpired } = getLoginConfig();
        if (!hasToken || isExpired) {
          toast.error(
            "No active Databricks session. Go to Compute → Databricks → Authentication and click Login with Databricks.",
          );
          return;
        }
      } else {
        if (!workspaceUrl) {
          toast.error("Please enter Workspace URL first");
          return;
        }
        const authMode = authMethod === "personal_access_token" ? "token" : "oauth2";
        if (authMode === "token" && !pat) {
          toast.error("Please enter Personal Access Token first");
          return;
        }
        if (authMode === "oauth2" && (!oauthClientId || !oauthSecret)) {
          toast.error("Please enter OAuth2 Client ID and Secret first");
          return;
        }
      }

      const requestId = ++tablesRequestIdRef.current;
      setLoadingTables(true);
      try {
        const fetched = await withTempConfig(async () => {
          const databricksService = new DatabricksService();
          return await databricksService.listTables(catalogName, schemaName);
        });

        if (requestId !== tablesRequestIdRef.current) return;

        // Backend has been observed returning either a bare array of names
        // (`["orders", ...]`) or an array of objects (`[{ name: "orders" }]`).
        // `normalizeDatabricksTables` coerces both into the picker's expected
        // shape so the UI never has to handle response drift.
        const normalized = normalizeDatabricksTables(fetched);
        setTables(normalized);
        if (normalized.length === 0) {
          toast.info("No tables found in this schema");
        }
      } catch (error) {
        if (requestId !== tablesRequestIdRef.current) return;
        // We previously fell back silently because the call was driven by an
        // auto-effect, but it is now button-triggered so the user deserves an
        // explicit message. `setTables([])` keeps the free-text input as a
        // safety net for backends that don't expose the discovery endpoint.
        console.error("Could not load Databricks tables.", error);
        toast.error("Failed to load tables. You can still enter table names manually below.");
        setTables([]);
      } finally {
        if (requestId === tablesRequestIdRef.current) {
          setLoadingTables(false);
        }
      }
    },
    [
      authUsesMainConfig,
      authMethod,
      getLoginConfig,
      oauthClientId,
      oauthSecret,
      pat,
      withTempConfig,
      workspaceUrl,
    ],
  );

  // -------------------------- Auto-load effects --------------------------
  // NOTE: catalog and table discovery are intentionally button-driven
  // (mirroring the Compute → Databricks Unity Catalog tab). The user clicks
  // "Load Catalogs" / "Load Tables" in the form — we don't fire requests on
  // render because the form may not yet have credentials in either local
  // state (PAT/OAuth) or in the central config (Databricks Login). Schemas
  // remain auto-loaded once a catalog is picked because the catalog already
  // implies a credentialed call has succeeded.

  // Auto-load schemas when the catalog selection changes. `loadSchemas` is
  // memoized so this effect only re-fires when its real inputs change — not
  // on every render — which previously caused overlapping requests that
  // raced and could wipe the schemas state.
  useEffect(() => {
    if (!isActive || !selectedCatalog) return;
    loadSchemas(selectedCatalog);
  }, [isActive, selectedCatalog, loadSchemas]);

  // Tables are intentionally button-driven (parallel to catalogs). We do not
  // auto-load when catalog/schema change — instead we clear the previously
  // discovered list so the form doesn't show stale tables from a different
  // scope. The user re-triggers discovery by clicking "Load Tables".
  // biome-ignore lint/correctness/useExhaustiveDependencies: selectedCatalog and selectedSchema are intentional change-triggers so the stale tables list is wiped whenever the scope changes, even though the body doesn't read them.
  useEffect(() => {
    if (!isActive) return;
    setTables([]);
  }, [isActive, selectedCatalog, selectedSchema]);

  return {
    authMethod,
    setAuthMethod,
    connectionMode,
    setConnectionMode,
    authUsesMainConfig,
    appPrincipalCtx,

    workspaceUrl,
    setWorkspaceUrl,
    pat,
    setPat,
    oauthClientId,
    setOauthClientId,
    oauthSecret,
    setOauthSecret,

    clusters,
    setClusters,
    catalogs,
    setCatalogs,
    schemas,
    setSchemas,
    tables,
    setTables,
    loadingClusters,
    loadingCatalogs,
    loadingSchemas,
    loadingTables,

    getLoginConfig,
    withTempConfig,
    loadClusters,
    loadCatalogs,
    loadSchemas,
    loadTables,
  };
}
