import { formatDistanceToNow, parseISO } from "date-fns";
import { Lock, RotateCcw, Trash2 } from "lucide-react";
import type { OntologySnapshotMeta } from "@/features/ontologies/api";
import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

interface SnapshotItemProps {
  snapshot: OntologySnapshotMeta;
  onRestore: () => void;
  onDelete: () => void;
  disabled: boolean;
  restoreLocked: boolean;
  isComparing: boolean;
  isSelected: boolean;
  onToggleSelect: () => void;
}

export function SnapshotItem({
  snapshot,
  onRestore,
  onDelete,
  disabled,
  restoreLocked,
  isComparing,
  isSelected,
  onToggleSelect,
}: SnapshotItemProps) {
  const isAuto = snapshot.description?.startsWith("Auto:");
  const timeAgo = formatRelativeTime(snapshot.created_at);
  const label = snapshot.description || "No description";
  const restoreTitle = restoreLocked
    ? "Restoring is a paid feature — upgrade to restore"
    : "Restore this snapshot";

  const containerClass = cn(
    "group flex items-start gap-3 rounded-md border bg-card p-3 transition-colors",
    isComparing && isSelected ? "border-primary bg-primary/10" : "border-border hover:bg-muted/50",
    isComparing && "cursor-pointer",
  );

  if (isComparing) {
    return (
      <button
        type="button"
        onClick={onToggleSelect}
        className={cn(containerClass, "w-full text-left")}
      >
        <input
          type="checkbox"
          checked={isSelected}
          readOnly
          className="mt-0.5 h-4 w-4 rounded border-border"
        />
        <div className="min-w-0 flex-1">
          <p
            className={cn(
              "truncate text-sm",
              isAuto ? "italic text-muted-foreground" : "font-medium text-foreground",
            )}
            title={label}
          >
            {label}
          </p>
          <p className="mt-0.5 text-xs text-muted-foreground">{timeAgo}</p>
        </div>
      </button>
    );
  }

  return (
    <div className={containerClass}>
      <div className="min-w-0 flex-1">
        <p
          className={cn(
            "truncate text-sm",
            isAuto ? "italic text-muted-foreground" : "font-medium text-foreground",
          )}
          title={label}
        >
          {label}
        </p>
        <p className="mt-0.5 text-xs text-muted-foreground">{timeAgo}</p>
      </div>
      <div className="flex shrink-0 items-center gap-1 opacity-0 transition-opacity group-hover:opacity-100">
        <Button
          type="button"
          variant="ghost"
          size="iconSm"
          onClick={onRestore}
          disabled={disabled}
          title={restoreTitle}
        >
          {restoreLocked ? <Lock className="h-3.5 w-3.5" /> : <RotateCcw className="h-3.5 w-3.5" />}
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="iconSm"
          onClick={onDelete}
          disabled={disabled}
          title="Delete this snapshot"
          className="text-destructive hover:text-destructive"
        >
          <Trash2 className="h-3.5 w-3.5" />
        </Button>
      </div>
    </div>
  );
}

function formatRelativeTime(iso: string): string {
  try {
    return formatDistanceToNow(parseISO(iso), { addSuffix: true });
  } catch {
    return "unknown";
  }
}
