import { useCallback, useEffect, useRef, useState } from "react";
import { engineClient } from "../api/EngineClient";

const LOGFILE_POLL_INTERVAL_MS = 10_000;

interface UseLogFileOptions {
  enabled: boolean;
}

interface UseLogFileReturn {
  content: string | null;
  isLoading: boolean;
  lastUpdatedAt: number | null;
  error: string | null;
  refresh: () => Promise<void>;
}

export function useLogFile({ enabled }: UseLogFileOptions): UseLogFileReturn {
  const [content, setContent] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [lastUpdatedAt, setLastUpdatedAt] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const refresh = useCallback(async () => {
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;

    setIsLoading(true);
    try {
      const text = await engineClient.getLogfile();
      if (controller.signal.aborted) return;
      if (text === null) {
        setError("Unable to load log file");
      } else {
        setContent(text);
        setLastUpdatedAt(Date.now());
        setError(null);
      }
    } catch (err: unknown) {
      if (controller.signal.aborted) return;
      const message = err instanceof Error ? err.message : "Failed to load log file";
      setError(message);
    } finally {
      if (!controller.signal.aborted) setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!enabled) return;
    void refresh();
    const id = setInterval(() => {
      void refresh();
    }, LOGFILE_POLL_INTERVAL_MS);
    return () => {
      clearInterval(id);
      abortRef.current?.abort();
    };
  }, [enabled, refresh]);

  return { content, isLoading, lastUpdatedAt, error, refresh };
}
