import type { CanvasEdge, CanvasNode } from "../graphExplorer.utils";

/** G6 style callbacks receive loosely-typed datums; narrow to our shapes. */
export function asCanvasNode(datum: unknown): Partial<CanvasNode> {
  return (datum ?? {}) as Partial<CanvasNode>;
}

export function asCanvasEdge(datum: unknown): Partial<CanvasEdge> {
  return (datum ?? {}) as Partial<CanvasEdge>;
}

export const LARGE_GRAPH_THRESHOLD = 200;
export const SELECTED_LINE_WIDTH = 4;

/**
 * Place newly-added (expansion) nodes on a ring around the already-placed
 * neighbor they attach to, so a batch of new neighbors fans out instead of
 * piling on one point. Existing nodes are left untouched (no `style` returned),
 * so a `draw()` keeps their positions. `getPosition` returns a live node
 * position, or null when it isn't placed yet.
 */
export function seedNewNodePositions(
  newNodes: CanvasNode[],
  newEdges: CanvasEdge[],
  existingNodeIds: Set<string>,
  getPosition: (id: string) => [number, number] | null,
): CanvasNode[] {
  const anchorOf = new Map<string, string>();
  for (const node of newNodes) {
    const edge = newEdges.find(
      (e) =>
        (e.source === node.id && existingNodeIds.has(e.target)) ||
        (e.target === node.id && existingNodeIds.has(e.source)),
    );
    if (edge) anchorOf.set(node.id, existingNodeIds.has(edge.source) ? edge.source : edge.target);
  }

  const idsByAnchor = new Map<string, string[]>();
  for (const node of newNodes) {
    const anchor = anchorOf.get(node.id);
    if (!anchor) continue;
    const group = idsByAnchor.get(anchor) ?? [];
    group.push(node.id);
    idsByAnchor.set(anchor, group);
  }

  const positions = new Map<string, { x: number; y: number }>();
  for (const [anchor, ids] of idsByAnchor) {
    const base = getPosition(anchor);
    if (!base) continue;
    const radius = 70 + ids.length * 6;
    ids.forEach((id, index) => {
      const angle = (index / ids.length) * Math.PI * 2;
      positions.set(id, {
        x: base[0] + radius * Math.cos(angle),
        y: base[1] + radius * Math.sin(angle),
      });
    });
  }

  return newNodes.map((node) => {
    const position = positions.get(node.id);
    return position ? { ...node, style: position } : node;
  });
}

export type LayoutType = "force" | "dagre" | "circular";

export const LAYOUTS: Array<{ value: LayoutType; label: string }> = [
  { value: "force", label: "Force" },
  { value: "dagre", label: "Hierarchical" },
  { value: "circular", label: "Circular" },
];

export function buildLayout(type: LayoutType, large: boolean) {
  if (type === "dagre") return { type: "dagre", rankdir: "TB", nodesep: 60, ranksep: 60 };
  if (type === "circular") return { type: "circular" };
  return {
    type: "force",
    preventOverlap: !large,
    nodeStrength: large ? -20 : -50,
    edgeStrength: 0.1,
    iterations: large ? 100 : 300,
  };
}

interface GrayedPalette {
  nodeFill: string;
  nodeStroke: string;
  edge: string;
  label: string;
}

/** Solid low-contrast grays for unrelated elements while a node is selected. */
export function resolveGrayedPalette(theme: string): GrayedPalette {
  if (theme === "dark") {
    return { nodeFill: "#2b3547", nodeStroke: "#3d4a5f", edge: "#33405a", label: "#5b677d" };
  }
  return { nodeFill: "#cbd5e1", nodeStroke: "#94a3b8", edge: "#d3dae4", label: "#94a3b8" };
}

export function resolveGridStroke(theme: string): string {
  // Barely-there grid: just enough texture to signal a canvas.
  return theme === "dark" ? "#0d1526" : "#f8fafc";
}

export function resolveNodeLabelFill(theme: string): string {
  return theme === "dark" ? "#e2e8f0" : "#1e293b";
}

export function resolveEdgeLabelFill(theme: string): string {
  return theme === "dark" ? "#a99ee0" : "#7c6fd1";
}

export function resolveEdgeStroke(theme: string): string {
  // Soft lavender, translucent so crossings stay readable.
  return theme === "dark" ? "#8b7ce8" : "#b7a8ef";
}

export function resolveLabelBackground(theme: string): string {
  return theme === "dark" ? "#0b1121" : "#ffffff";
}
