import { AlertTriangle, Loader2, X } from "lucide-react";
import type React from "react";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import type { MemberRow, TeamError } from "@/features/teams/types";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";

interface TransferOwnershipDialogProps {
  isOpen: boolean;
  onClose: () => void;
  teamName: string;
  members: MemberRow[];
  callerUserId: string;
  onTransfer: (newOwnerUserId: string) => Promise<unknown>;
  isTransferring: boolean;
}

// Confirmation dialog for POST /teams/{team_id}/transfer-ownership. Eligible
// targets are all active members other than the caller — the backend rejects
// transfer-to-self as a no-op and rejects transfers to non-members.
const TransferOwnershipDialog: React.FC<TransferOwnershipDialogProps> = ({
  isOpen,
  onClose,
  teamName,
  members,
  callerUserId,
  onTransfer,
  isTransferring,
}) => {
  const eligibleMembers = useMemo(
    () => members.filter((m) => m.status === "active" && m.user_id !== callerUserId),
    [members, callerUserId],
  );

  const [selected, setSelected] = useState<string>("");

  // Reset selection each time the dialog opens; if there's exactly one
  // eligible target, preselect it so the user just has to confirm.
  useEffect(() => {
    if (!isOpen) return;
    setSelected(eligibleMembers.length === 1 ? eligibleMembers[0].user_id : "");
  }, [isOpen, eligibleMembers]);

  const handleOpenChange = (open: boolean): void => {
    if (!open && !isTransferring) onClose();
  };

  const handleTransfer = async (): Promise<void> => {
    if (!selected) return;
    const target = eligibleMembers.find((m) => m.user_id === selected);
    if (!target) return;
    try {
      await onTransfer(selected);
      toast.success(`${target.username} is now the owner`, {
        description: "You've been demoted to admin.",
      });
      onClose();
    } catch (err) {
      const teamErr = err as TeamError;
      if (teamErr.httpStatus === 403) {
        toast.error(teamErr.message || "Only the owner can transfer ownership.");
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to transfer ownership";
      toast.error(message);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent className="p-0 sm:max-w-[480px] overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Transfer ownership</DialogTitle>

        <div
          style={{ background: "#FFDF4B", padding: "12px 20px" }}
          className="flex items-center justify-between border-b border-border"
        >
          <div className="min-w-0">
            <h2 className="text-base font-bold text-[#212020]">Transfer ownership</h2>
            <p className="truncate text-xs text-[#212020]/80">{teamName}</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            disabled={isTransferring}
            className="flex h-6 w-6 items-center justify-center rounded-full transition-colors hover:bg-black/10 disabled:opacity-50"
            aria-label="Close"
          >
            <X className="h-4 w-4 text-[#212020]" />
          </button>
        </div>

        <div className="space-y-4 bg-card p-6">
          <div className="flex items-start gap-2 rounded-md border border-amber-500/40 bg-amber-500/[0.06] p-3 text-xs text-foreground dark:bg-amber-500/[0.08]">
            <AlertTriangle className="mt-0.5 h-4 w-4 flex-shrink-0 text-amber-600 dark:text-amber-400" />
            <div>
              <p className="font-medium">You'll be demoted to admin.</p>
              <p className="mt-0.5 text-muted-foreground">
                The new owner will have full control of the team, including the ability to remove
                you. This can't be undone from your side.
              </p>
            </div>
          </div>

          {eligibleMembers.length === 0 ? (
            <p className="rounded-md border border-dashed border-border bg-muted/30 px-3 py-6 text-center text-xs text-muted-foreground">
              No eligible members to transfer to. Invite someone first.
            </p>
          ) : (
            <div className="space-y-1.5">
              <Label htmlFor="new-owner">New owner</Label>
              <Select value={selected} onValueChange={setSelected} disabled={isTransferring}>
                <SelectTrigger id="new-owner">
                  <SelectValue placeholder="Choose a member" />
                </SelectTrigger>
                <SelectContent>
                  {eligibleMembers.map((m) => (
                    <SelectItem key={m.user_id} value={m.user_id}>
                      {m.username}
                      <span className="ml-2 text-muted-foreground">{m.email}</span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          <div className="flex items-center justify-end gap-2 pt-2">
            <Button type="button" variant="ghost" onClick={onClose} disabled={isTransferring}>
              Cancel
            </Button>
            <Button
              type="button"
              onClick={handleTransfer}
              disabled={!selected || isTransferring}
              className="gap-1.5"
            >
              {isTransferring && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
              Transfer ownership
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default TransferOwnershipDialog;
