import { useEffect, useRef } from "react";
import { useLocation } from "react-router-dom";
import { trackPageview } from "@/shared/services/analyticsEvents";

/**
 * Fire a PostHog `$pageview` on every SPA route change.
 *
 * The initial hard load is already captured by posthog-js (`capture_pageview`),
 * so the first render is skipped to avoid double-counting — this hook only adds
 * the client-side navigations that a plain SPA would otherwise miss.
 */
export function usePageviewTracking(): void {
  const location = useLocation();
  const isFirstRender = useRef(true);

  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    trackPageview(location.pathname);
  }, [location.pathname]);
}
