import React from "react";
import { type TabRendererProps, useTabRenderer } from "@/shared/hooks/tabs/useTabRenderer";

interface ContentRendererProps {
  activeTab: string;
  code: string;
  setCode: (code: string) => void;
  aiSuggestionsEnabled: boolean;
  explainEnabled: boolean;
  wordWrap: boolean;
  onAiSuggestionsToggle: (enabled: boolean) => void;
  onExplainToggle: (enabled: boolean) => void;
  onWordWrapChange: (enabled: boolean) => void;
  onBackFromSettings?: () => void;
  previousTab?: string;
  onToggleSidebar?: () => void;
  sidebarVisible?: boolean;
}

const ContentRenderer = ({
  activeTab,
  code,
  setCode,
  aiSuggestionsEnabled,
  explainEnabled,
  wordWrap,
  onAiSuggestionsToggle,
  onExplainToggle,
  onWordWrapChange,
  onBackFromSettings,
  previousTab,
  onToggleSidebar,
  sidebarVisible = false,
}: ContentRendererProps) => {
  const tabRendererProps: TabRendererProps = {
    activeTab,
    code,
    setCode,
    aiSuggestionsEnabled,
    explainEnabled,
    wordWrap,
    onAiSuggestionsToggle,
    onExplainToggle,
    onWordWrapChange,
    onBackFromSettings,
    previousTab,
    onToggleSidebar,
    sidebarVisible,
  };

  const tabContent = useTabRenderer(tabRendererProps);

  if (!tabContent) return null;

  const { component: TabComponent, props } = tabContent;

  return <TabComponent {...props} />;
};

export default React.memo(ContentRenderer);
