import { Copy, Settings, Share2 } from "lucide-react";
import type React from "react";

interface OntologyCardActionsProps {
  canShare: boolean;
  canCopy: boolean;
  canRename: boolean;
  onShare: (e: React.MouseEvent) => void;
  onCopy: (e: React.MouseEvent) => void;
  onRename: (e: React.MouseEvent) => void;
}

/**
 * Hover action overlay (Share / Copy / Settings) for an owned project card.
 *
 * These live on top of the card-wide <Link>; nesting a <button> inside an <a>
 * is invalid HTML, so each action is a role="button" div with a keyboard
 * handler. Extracted from ProjectCard to keep that file within the size limit.
 */
export function OntologyCardActions({
  canShare,
  canCopy,
  canRename,
  onShare,
  onCopy,
  onRename,
}: OntologyCardActionsProps) {
  return (
    <div className="absolute top-3 right-3 flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
      {canShare && (
        // biome-ignore lint/a11y/useSemanticElements: button cannot nest in anchor
        <div
          role="button"
          tabIndex={0}
          onClick={onShare}
          onKeyDown={(e) => {
            if (e.key === "Enter") onShare(e as unknown as React.MouseEvent);
          }}
          className="p-1.5 rounded-md text-muted-foreground/40 hover:text-foreground hover:bg-secondary transition-colors"
          title="Share ontology"
        >
          <Share2 className="h-3.5 w-3.5" />
        </div>
      )}
      {canCopy && (
        // biome-ignore lint/a11y/useSemanticElements: button cannot nest in anchor
        <div
          role="button"
          tabIndex={0}
          onClick={onCopy}
          onKeyDown={(e) => {
            if (e.key === "Enter") onCopy(e as unknown as React.MouseEvent);
          }}
          className="p-1.5 rounded-md text-muted-foreground/40 hover:text-foreground hover:bg-secondary transition-colors"
          title="Copy ontology"
        >
          <Copy className="h-3.5 w-3.5" />
        </div>
      )}
      {canRename && (
        // biome-ignore lint/a11y/useSemanticElements: button cannot nest in anchor
        <div
          role="button"
          tabIndex={0}
          onClick={onRename}
          onKeyDown={(e) => {
            if (e.key === "Enter") onRename(e as unknown as React.MouseEvent);
          }}
          className="p-1.5 rounded-md text-muted-foreground/40 hover:text-foreground hover:bg-secondary transition-colors"
          title="Ontology settings"
        >
          <Settings className="h-3.5 w-3.5" />
        </div>
      )}
    </div>
  );
}
