import type { OntologyData } from "@/features/ontologies/api";
import type { InboxEntry, OutboxEntry, ShareRole, ShareStatus } from "../types";

// Backend caps share expiry at 5 years (MAX_SHARE_EXPIRES_IN_MINUTES). Clamping on
// the FE avoids a round-trip 400; if the backend cap ever shrinks, the backend will
// still enforce it and we'll surface the message via ShareError.
export const FIVE_YEARS_MINUTES = 60 * 24 * 365 * 5;

const ONE_DAY_MINUTES = 24 * 60;
const SEVEN_DAYS_MINUTES = 7 * ONE_DAY_MINUTES;
const THIRTY_DAYS_MINUTES = 30 * ONE_DAY_MINUTES;

const EXPIRY_PRESETS = {
  never: null,
  "1d": ONE_DAY_MINUTES,
  "7d": SEVEN_DAYS_MINUTES,
  "30d": THIRTY_DAYS_MINUTES,
} as const;

export type ExpiryPreset = keyof typeof EXPIRY_PRESETS | "custom";

interface AssignableMember {
  user_id: string;
  role: string;
}

interface AssignableMemberOptions {
  // The signed-in user — never a valid restriction subject (you can't restrict
  // yourself; owner-set rules on the owner are inert anyway).
  currentUserId: string;
  // The project owner's id. Total access; the backend rejects targeting them
  // (403 in the delegated flow), so they're dropped from the picker.
  ownerSub?: string;
  // In the team-admin delegated UI the team owner also can't be targeted (403).
  excludeTeamOwner: boolean;
}

// Whether a team member may be offered as a per-concept / ontology-role subject.
// Filters out the current user, the project owner, and (when delegated) the
// team owner — all of whom the backend refuses to restrict.
export function isAssignableSubjectMember(
  member: AssignableMember,
  { currentUserId, ownerSub, excludeTeamOwner }: AssignableMemberOptions,
): boolean {
  if (member.user_id === currentUserId) return false;
  if (ownerSub && member.user_id === ownerSub) return false;
  if (excludeTeamOwner && member.role === "owner") return false;
  return true;
}

export function presetToMinutes(preset: Exclude<ExpiryPreset, "custom">): number | null {
  return EXPIRY_PRESETS[preset];
}

export function isEmail(input: string): boolean {
  return input.includes("@");
}

// Converts a target Date to "minutes from now", clamped between 1 minute and the
// backend's 5-year cap. Anything earlier than 1 minute would be useless; anything
// past 5 years would trip the backend cap.
export function dateToExpiresInMinutes(target: Date, now: Date = new Date()): number {
  const diff = Math.round((target.getTime() - now.getTime()) / 60_000);
  if (diff < 1) return 1;
  if (diff > FIVE_YEARS_MINUTES) return FIVE_YEARS_MINUTES;
  return diff;
}

// Formats a Date as `YYYY-MM-DD` in the *local* timezone, suitable for a native
// <input type="date">. We deliberately avoid `toISOString().split("T")[0]` because
// it returns UTC, which is off-by-one for users east of GMT after evening.
export function toLocalIsoDate(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function minExpiryDateIso(now: Date = new Date()): string {
  const tomorrow = new Date(now.getTime() + ONE_DAY_MINUTES * 60_000);
  return toLocalIsoDate(tomorrow);
}

export function maxExpiryDateIso(now: Date = new Date()): string {
  const max = new Date(now.getTime() + FIVE_YEARS_MINUTES * 60_000);
  return toLocalIsoDate(max);
}

// Matches a (username, organization) pair against existing pending outbox rows so the
// submit button can read "Resend invitation" instead of "Send invitation". Email-mode
// submits can't be pre-matched (the client doesn't know the recipient's sub), so the
// caller is expected to skip the check entirely in that case.
export function findPendingMatch(
  entries: OutboxEntry[],
  username: string,
  organization: string,
): OutboxEntry | undefined {
  const u = username.trim().toLowerCase();
  const o = organization.trim().toLowerCase();
  if (!u || !o) return undefined;
  return entries.find(
    (e) =>
      e.status === "pending" &&
      e.recipient_username.toLowerCase() === u &&
      e.recipient_organization.toLowerCase() === o,
  );
}

const LIVE_STATUSES = new Set<ShareStatus>(["pending", "accepted", "active"]);

export interface OutboxPartition {
  live: OutboxEntry[];
  historical: OutboxEntry[];
}

export function partitionByLiveness(entries: OutboxEntry[]): OutboxPartition {
  const live: OutboxEntry[] = [];
  const historical: OutboxEntry[] = [];
  for (const entry of entries) {
    if (LIVE_STATUSES.has(entry.status)) {
      live.push(entry);
    } else {
      historical.push(entry);
    }
  }
  return { live, historical };
}

export function formatExpiresAt(iso: string | null): string {
  if (!iso) return "Never expires";
  const date = new Date(iso);
  return `Expires ${date.toLocaleDateString(undefined, { dateStyle: "medium" })}`;
}

interface RoleMeta {
  title: string;
  description: string;
}

const ROLE_LABELS: Record<ShareRole, RoleMeta> = {
  viewer: { title: "Viewer", description: "Read-only access" },
  editor: { title: "Editor", description: "Can make changes" },
};

export function roleMeta(role: ShareRole): RoleMeta {
  return ROLE_LABELS[role];
}

const STATUS_LABELS: Record<ShareStatus, string> = {
  pending: "Pending",
  accepted: "Accepted",
  revoked: "Revoked",
  superseded: "Superseded",
  left: "Left",
  active: "Active",
};

export function statusLabel(status: ShareStatus): string {
  return STATUS_LABELS[status];
}

// Whether an inbox entry can be opened in the editor. Direct shares are openable
// once accepted; team shares are openable once claimed (needs_claim === false).
export function isInboxEntryOpenable(entry: InboxEntry): boolean {
  if (entry.share_type === "team") return entry.needs_claim === false;
  return entry.status === "accepted";
}

// Whether an inbox entry is awaiting a recipient action before it can be opened.
// Direct shares: pending (accept). Team shares: needs_claim (join/claim).
export function isInboxEntryPendingAction(entry: InboxEntry): boolean {
  if (entry.share_type === "team") return entry.needs_claim === true;
  return entry.status === "pending";
}

// Maps an inbox entry into a ProjectData row so it can be rendered through the same
// components (ProjectCard, ProjectList) as the user's own projects. Per Q2: shared
// projects always carry scope="user" because the dispatcher forwards reads to the
// owner's pod where the project lives under their user scope. `shareStatus` lets
// downstream components branch on pending vs accepted (Accept/Decline buttons vs
// open-in-editor); for team shares it's derived from needs_claim so a not-yet-
// claimed team share renders as a "Join" invitation.
export function inboxEntryToOntologyData(entry: InboxEntry): OntologyData {
  const isTeam = entry.share_type === "team";
  const shareStatus: InboxEntry["status"] = isInboxEntryOpenable(entry) ? "accepted" : "pending";
  return {
    id: entry.ontology_id,
    name: entry.ontology_name,
    description: "",
    author: `${entry.owner.username}@${entry.owner.organization}`,
    scope: "user",
    origin: "shared",
    sharedBy: entry.owner,
    shareRole: entry.share_role,
    shareId: entry.share_id,
    expiresAt: entry.expires_at,
    shareStatus,
    shareType: entry.share_type ?? "user",
    needsClaim: isTeam ? entry.needs_claim === true : undefined,
    teamId: entry.team_id,
  };
}

// Merges the user's own projects with their openable shares (accepted direct
// shares + claimed team shares), marking owned rows explicitly and filtering out
// any shared rows whose ontology_id is already present as an owned project
// (defensive — a user cannot, in practice, both own and be a recipient of the same project).
// Used by the editor's project picker and any caller that wants a single combined list.
export function mergeOwnedAndShared(owned: OntologyData[], inbox: InboxEntry[]): OntologyData[] {
  const ownedIds = new Set(owned.map((p) => p.id));
  const sharedRows = inbox
    .filter(isInboxEntryOpenable)
    .map(inboxEntryToOntologyData)
    .filter((p) => !ownedIds.has(p.id));
  const ownedTagged = owned.map<OntologyData>((p) => (p.origin ? p : { ...p, origin: "owned" }));
  return [...ownedTagged, ...sharedRows];
}

// Returns the recipient's shared projects (awaiting-action first, then openable)
// as ProjectData rows, so pending invitations / unclaimed team shares are
// visually prioritised in the "Shared with me" tab.
export function buildSharedTabList(inbox: InboxEntry[]): OntologyData[] {
  const pending = inbox.filter(isInboxEntryPendingAction).map(inboxEntryToOntologyData);
  const openable = inbox.filter(isInboxEntryOpenable).map(inboxEntryToOntologyData);
  return [...pending, ...openable];
}
