import type { FormFieldDef, ScalarInputType } from "../../../schema/appDefinition.types";
import { useAppEditorStore } from "../../../store/appEditorStore";
import { patchFormField } from "../../../store/formFieldMutations";
import {
  INPUT_TYPE_HELP,
  OPTIONS_SOURCE_HELP,
  OPTIONS_SOURCE_PLACEHOLDER,
  SEED_FROM_HELP,
  SEED_FROM_PLACEHOLDER,
  VISIBLE_WHEN_PLACEHOLDER,
} from "../editorHelp";
import { BoolField, CsvField, JsonField, NumberField, SelectField, TextField } from "./fields";
import { StaleSelection } from "./PageInspector";

interface FormFieldInspectorProps {
  pageId: string;
  inputId: string;
  sectionIndex: number;
  fieldId: string;
}

const FIELD_TYPE_OPTIONS: Array<{ value: FormFieldDef["type"]; label: string }> = [
  { value: "text", label: "Text" },
  { value: "number", label: "Number" },
  { value: "select", label: "Select" },
  { value: "combobox", label: "Combobox" },
  { value: "date", label: "Date" },
  { value: "multi_select", label: "Multi-select" },
  { value: "checkbox", label: "Checkbox" },
  { value: "radio", label: "Radio buttons" },
  { value: "password", label: "Password" },
  { value: "textarea", label: "Textarea" },
  { value: "record_group", label: "Record group" },
];

const OPTION_FIELD_TYPES = new Set(["select", "combobox", "multi_select", "radio"]);

export function FormFieldInspector({
  pageId,
  inputId,
  sectionIndex,
  fieldId,
}: FormFieldInspectorProps) {
  const draft = useAppEditorStore((state) => state.draft);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  const field = draft?.pages
    .find((page) => page.id === pageId)
    ?.inputs.find((input) => input.id === inputId)
    ?.sections?.[sectionIndex]?.fields.find((candidate) => candidate.id === fieldId);
  if (!field) return <StaleSelection />;

  const patch = (partial: Partial<FormFieldDef>) => {
    updateDraft((current) =>
      patchFormField(current, pageId, inputId, sectionIndex, fieldId, partial),
    );
  };

  return (
    <div className="flex flex-col gap-2.5">
      <SelectField
        label="Type"
        hint={INPUT_TYPE_HELP[field.type]}
        value={field.type}
        options={FIELD_TYPE_OPTIONS}
        onChange={(value) => patch({ type: (value ?? "text") as FormFieldDef["type"] })}
      />
      <TextField label="Label" value={field.label} onChange={(value) => patch({ label: value })} />
      <BoolField
        label="Required"
        value={field.required}
        onChange={(value) => patch({ required: value })}
      />
      <NumberField
        label="Span (grid layout, 1–12)"
        value={field.span}
        min={1}
        max={12}
        onChange={(value) => patch({ span: value })}
      />
      {field.type !== "record_group" && <ScalarFieldKnobs field={field} patch={patch} />}
      {field.type === "record_group" && <RecordGroupKnobs field={field} patch={patch} />}
      <JsonField
        label="Visible when ({field, equals})"
        hint="Show this field only while another field of the same form has the given value."
        placeholder={VISIBLE_WHEN_PLACEHOLDER}
        value={field.visibleWhen}
        onChange={(value) => patch({ visibleWhen: value as FormFieldDef["visibleWhen"] })}
        rows={3}
      />
    </div>
  );
}

interface KnobsProps {
  field: FormFieldDef;
  patch: (partial: Partial<FormFieldDef>) => void;
}

function ScalarFieldKnobs({ field, patch }: KnobsProps) {
  return (
    <>
      <TextField
        label="Placeholder"
        value={field.placeholder}
        onChange={(value) => patch({ placeholder: value })}
      />
      <TextField
        label="Default value"
        value={field.default === undefined ? undefined : String(field.default)}
        onChange={(value) => patch({ default: value })}
      />
      {field.type === "number" && (
        <>
          <NumberField label="Min" value={field.min} onChange={(value) => patch({ min: value })} />
          <NumberField label="Max" value={field.max} onChange={(value) => patch({ max: value })} />
        </>
      )}
      {field.type === "text" && (
        <TextField
          label="Pattern (regex)"
          value={field.pattern}
          onChange={(value) => patch({ pattern: value })}
        />
      )}
      {OPTION_FIELD_TYPES.has(field.type as ScalarInputType) && (
        <>
          <CsvField
            label="Static options"
            value={field.options}
            onChange={(value) => patch({ options: value })}
          />
          <JsonField
            label="Options from concept"
            hint={OPTIONS_SOURCE_HELP}
            placeholder={OPTIONS_SOURCE_PLACEHOLDER}
            value={field.optionsSource}
            onChange={(value) => patch({ optionsSource: value as FormFieldDef["optionsSource"] })}
            rows={4}
          />
        </>
      )}
    </>
  );
}

function RecordGroupKnobs({ field, patch }: KnobsProps) {
  return (
    <>
      <NumberField
        label="Min rows"
        value={field.minRows}
        min={0}
        onChange={(value) => patch({ minRows: value })}
      />
      <NumberField
        label="Max rows"
        value={field.maxRows}
        min={1}
        onChange={(value) => patch({ maxRows: value })}
      />
      <JsonField
        label="Seed from ({concept, columnToField})"
        hint={SEED_FROM_HELP}
        placeholder={SEED_FROM_PLACEHOLDER}
        value={field.seedFrom}
        onChange={(value) => patch({ seedFrom: value as FormFieldDef["seedFrom"] })}
        rows={4}
      />
      <JsonField
        label="Row fields"
        value={field.fields}
        onChange={(value) => patch({ fields: value as FormFieldDef["fields"] })}
        rows={10}
      />
      <p className="text-[10px] text-muted-foreground leading-relaxed">
        Row field ids must match the input predicate's @model columns — validated on save.
      </p>
    </>
  );
}
