import { type Node as FlowNode, Position } from "@xyflow/react";
import type {
  ConceptCardCustomData,
  ExecutionStatus,
  LineageNodeData,
} from "@/features/ontology-schema/types";

/** Map API lineage nodes to ReactFlow concept-card nodes. */
export const transformNodes = (apiNodes: LineageNodeData[]): FlowNode<ConceptCardCustomData>[] =>
  apiNodes.map((n) => ({
    id: n.id,
    type: "conceptCard",
    data: {
      label: n.id,
      nodeType: n.type,
      is_input: n.is_input,
      fields: n.fields ?? {},
      datasource_type: n.datasource_type,
      datasource_label: n.datasource_label,
      database: n.database ?? "",
      bind_annotation: n.bind_annotation ?? "",
      isExpanded: false,
      definition: n.definition ?? "",
      description: n.description ?? "",
      bind_annotations: n.bind_annotations ?? "",
      concept_type: n.concept_type ?? "logic",
      content: n.content ?? "",
      concept_id: n.concept_id ?? "",
      group: n.group ?? "group_id",
      is_populated: n.is_populated ?? false,
      row_count: n.row_count ?? 0,
      execution_time_ms: n.execution_time_ms ?? 0,
    } as ConceptCardCustomData & { nodeType?: string; datasource_label?: string },
    position: { x: 0, y: 0 },
    sourcePosition: Position.Right,
    targetPosition: Position.Left,
  }));

/**
 * Mark concepts that have context notes attached (context_edges) so their
 * card shows the violet notebook indicator. Datasource nodes never carry it.
 */
export const stampAnnotatedNodes = (
  nodes: FlowNode<ConceptCardCustomData>[],
  annotatedConcepts: Set<string>,
): FlowNode<ConceptCardCustomData>[] =>
  nodes.map((n) => {
    const isAnnotated =
      n.data.nodeType !== "datasource" && annotatedConcepts.has(String(n.data.label));
    if (!isAnnotated) return n;
    return { ...n, data: { ...n.data, hasContext: true } };
  });

/**
 * Reconcile the lineage against the accessible concept set. Concept nodes whose
 * label is NOT in the accessible set are hidden for this scoped session — they
 * only appear because a visible concept references them — so they're flagged
 * `isRestricted` to render as an anonymized, non-interactive placeholder.
 *
 * Datasource nodes are never concepts and are left untouched. When the
 * accessible set is empty (concepts not loaded yet) nothing is marked, so the
 * graph never flashes every node as restricted during load.
 */
export const markRestrictedNodes = (
  nodes: FlowNode<ConceptCardCustomData>[],
  accessibleConcepts: Set<string>,
): FlowNode<ConceptCardCustomData>[] => {
  if (accessibleConcepts.size === 0) return nodes;
  return nodes.map((n) => {
    const isConcept = n.data.nodeType !== "datasource";
    const isRestricted = isConcept && !accessibleConcepts.has(String(n.data.label));
    if (!isRestricted) return n;
    return { ...n, data: { ...n.data, isRestricted: true } };
  });
};

/**
 * Re-apply execution status and card expansion onto freshly transformed nodes
 * so a lineage refresh keeps run colours and doesn't collapse expanded cards.
 */
export const restorePreservedNodeState = (
  nodes: FlowNode<ConceptCardCustomData>[],
  statuses: Record<string, ExecutionStatus>,
  expandedLabels: Set<string>,
): FlowNode<ConceptCardCustomData>[] =>
  nodes.map((n) => {
    const label = n.data.label;
    const st = statuses[label];
    const isExpanded = expandedLabels.has(label);
    if (!st && !isExpanded) return n;
    return {
      ...n,
      data: {
        ...n.data,
        ...(st ? { executionStatus: st } : {}),
        ...(isExpanded ? { isExpanded: true } : {}),
      },
    };
  });
