import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

import { ContextNoteApi } from "../api";
import type {
  ContextNote,
  ContextNoteFilter,
  CreateContextNoteRequest,
  UpdateContextNoteRequest,
} from "../types";

const STALE_TIME_MS = 30 * 1000;

const noteListKey = (filter: ContextNoteFilter) =>
  ["context-notes", filter.scope, filter.scopeId ?? "global", filter.kinds ?? []] as const;

const showMutationError = (verb: string) => (error: Error) => {
  toast.error(`Could not ${verb} note: ${error.message}`);
};

export function useContextNotes(filter: ContextNoteFilter, options?: { enabled?: boolean }) {
  return useQuery({
    queryKey: noteListKey(filter),
    queryFn: () => ContextNoteApi.list(filter),
    staleTime: STALE_TIME_MS,
    enabled: options?.enabled ?? true,
  });
}

export function useCreateContextNote(filter: ContextNoteFilter) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateContextNoteRequest) => ContextNoteApi.create(body),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: noteListKey(filter) });
    },
    onError: showMutationError("create"),
  });
}

interface UpdateContextNoteVars {
  id: string;
  body: UpdateContextNoteRequest;
}

export function useUpdateContextNote(filter: ContextNoteFilter) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: UpdateContextNoteVars) => ContextNoteApi.update(id, body),
    onSuccess: (updated: ContextNote) => {
      queryClient.setQueryData<ContextNote[] | undefined>(noteListKey(filter), (current) =>
        current?.map((note) => (note.id === updated.id ? updated : note)),
      );
    },
    onError: showMutationError("update"),
  });
}

export function useDeleteContextNote(filter: ContextNoteFilter) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => ContextNoteApi.remove(id),
    onSuccess: (_void, id) => {
      queryClient.setQueryData<ContextNote[] | undefined>(noteListKey(filter), (current) =>
        current?.filter((note) => note.id !== id),
      );
    },
    onError: showMutationError("delete"),
  });
}
