import type { Node as FlowNode } from "@xyflow/react";
import { type MutableRefObject, useEffect, useRef } from "react";
import type { ConceptCell } from "@/features/concept-editor/types";
import type { ConceptCardCustomData } from "@/features/ontology-schema/types";
import type { PanelState } from "../components/lineage-view/types";

interface UseLineageConceptFocusParams {
  /** Concept name another view requested be focused (consumed once handled). */
  focusConceptName?: string | null;
  onFocusConsumed?: () => void;
  nodes: FlowNode<ConceptCardCustomData>[];
  findCellForConcept: (conceptName: string) => ConceptCell | undefined;
  loadCells: () => void;
  reactFlowInstance: MutableRefObject<{ fitView: (opts: unknown) => void } | null>;
  skipAutoFitViewRef: MutableRefObject<boolean>;
  setPanelState: (state: PanelState | null) => void;
}

/**
 * Brings a concept requested by another view (`focusConceptName`) into the
 * lineage editor: fit the canvas to its node and open its cell in the dock.
 */
export function useLineageConceptFocus({
  focusConceptName,
  onFocusConsumed,
  nodes,
  findCellForConcept,
  loadCells,
  reactFlowInstance,
  skipAutoFitViewRef,
  setPanelState,
}: UseLineageConceptFocusParams): void {
  const pendingFocusRef = useRef<string | null>(null);

  useEffect(() => {
    if (!focusConceptName) return;
    pendingFocusRef.current = focusConceptName;
    loadCells();
    onFocusConsumed?.();
  }, [focusConceptName, onFocusConsumed, loadCells]);

  useEffect(() => {
    const name = pendingFocusRef.current;
    if (!name || nodes.length === 0) return;

    const node = nodes.find((n) => n.data.label === name);
    if (node && reactFlowInstance.current) {
      skipAutoFitViewRef.current = true;
      reactFlowInstance.current.fitView({
        nodes: [node],
        duration: 500,
        padding: 0.5,
        maxZoom: 1.2,
      });
    }

    const cell = findCellForConcept(name);
    if (!cell) return;
    pendingFocusRef.current = null;
    setPanelState({
      conceptName: name,
      cellId: cell.id,
      isNew: false,
      panelKey: `focus-${name}-${Date.now()}`,
    });
  }, [nodes, findCellForConcept, reactFlowInstance, skipAutoFitViewRef, setPanelState]);
}
