import { Check, Circle, ListTodo } from "lucide-react";

import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

import type { PlanStep } from "../store";

interface PlanMessageProps {
  steps: PlanStep[];
}

function PlanStepRow({ step }: { step: PlanStep }) {
  const isCompleted = step.status === "completed";
  const isInProgress = step.status === "in_progress";
  const textClass = isCompleted
    ? "text-muted-foreground line-through"
    : isInProgress
      ? "text-foreground font-medium"
      : "text-muted-foreground";
  return (
    <li className="flex items-start gap-2 text-xs">
      <span className="mt-0.5 flex-shrink-0">
        {isCompleted ? (
          <Check className="h-3.5 w-3.5 text-green-500 dark:text-green-400" />
        ) : isInProgress ? (
          <PrometheuxSpinner size={14} />
        ) : (
          <Circle className="h-3.5 w-3.5 text-muted-foreground/50" />
        )}
      </span>
      <span className={textClass}>{step.content}</span>
    </li>
  );
}

export function PlanMessage({ steps }: PlanMessageProps) {
  if (steps.length === 0) return null;
  const completed = steps.filter((s) => s.status === "completed").length;
  return (
    <div className="rounded-lg border border-border bg-card p-3 shadow-sm">
      <div className="mb-2 flex items-center gap-1.5 text-xs font-semibold text-foreground">
        <ListTodo className="h-3.5 w-3.5 text-primary" />
        <span>Plan</span>
        <span className="ml-auto font-mono text-[10px] font-normal text-muted-foreground">
          {completed}/{steps.length}
        </span>
      </div>
      <ul className="space-y-1.5">
        {steps.map((step) => (
          <PlanStepRow key={step.content} step={step} />
        ))}
      </ul>
    </div>
  );
}
