import { ChevronDown, ChevronRight, FolderOpen, Globe } from "lucide-react";
import { cn } from "@/shared/lib/utils";
import { usePreferencesStore } from "@/shared/store/preferencesStore";

import { useContextNotes } from "../../hooks/useContextNotes";
import type { ContextNote, ContextShelf } from "../../types";
import type { DocumentGroup, NotesSelection, VaultRef } from "../notesModel";
import {
  buildFolderTree,
  filterByShelf,
  groupDocumentChunks,
  isAutoGeneratedNote,
  normalizeFolderPath,
  vaultKey,
} from "../notesModel";
import { FolderTreeView } from "./FolderTreeView";

interface VaultSectionProps {
  vault: VaultRef;
  isActive: boolean;
  shelf: ContextShelf | null;
  /** UI-created folders with no notes yet (active vault only). */
  localFolders: string[];
  selection: NotesSelection;
  defaultExpanded?: boolean;
  onActivate: (vault: VaultRef) => void;
  onSelectNote: (note: ContextNote, vault: VaultRef, folderPath: string) => void;
  onSelectDocument: (document: DocumentGroup, vault: VaultRef) => void;
  /** Vault or folder title clicked — show the group's notes as cards. */
  onSelectCollection: (vault: VaultRef, folderPath: string) => void;
}

export function VaultSection({
  vault,
  isActive,
  shelf,
  localFolders,
  selection,
  defaultExpanded = false,
  onActivate,
  onSelectNote,
  onSelectDocument,
  onSelectCollection,
}: VaultSectionProps) {
  // Expansion is a remembered preference rather than local state: it used to
  // reset to `defaultExpanded` on every remount, so the Global vault reappeared
  // open however often you collapsed it.
  const key = vaultKey(vault);
  const storedExpanded = usePreferencesStore((state) => state.vaultExpanded[key]);
  const setVaultExpanded = usePreferencesStore((state) => state.setVaultExpanded);
  const isExpanded = storedExpanded ?? defaultExpanded;

  const { data: notes = [], isLoading } = useContextNotes(
    { scope: vault.scope, scopeId: vault.scopeId },
    { enabled: isExpanded },
  );

  const shelfNotes = filterByShelf(notes, shelf);
  const { documents, standalone } = groupDocumentChunks(shelfNotes);
  // Pull unfiled auto-generated notes into their own virtual folder. Notes the
  // user has already filed into a real folder keep their placement.
  const autoGenerated = standalone.filter(
    (note) => isAutoGeneratedNote(note) && normalizeFolderPath(note.folder_path) === "",
  );
  const organized = standalone.filter((note) => !autoGenerated.includes(note));
  const folders = buildFolderTree([
    ...organized.map((note) => note.folder_path),
    ...(isActive ? localFolders : []),
  ]);
  const itemCount = organized.length + autoGenerated.length + documents.length;

  const handleToggle = () => {
    setVaultExpanded(key, !isExpanded);
    onActivate(vault);
  };

  const handleTitleClick = () => {
    setVaultExpanded(key, true);
    onSelectCollection(vault, "");
  };

  const ChevronIcon = isExpanded ? ChevronDown : ChevronRight;
  const VaultIcon = vault.scope === "global" ? Globe : FolderOpen;
  const isVaultSelected =
    isActive && selection.type === "collection" && selection.folderPath === "";

  return (
    <section className="pb-1">
      <div
        className={cn(
          "flex w-full items-center gap-1 rounded-md pr-1.5 text-sm font-semibold transition-colors",
          isVaultSelected ? "bg-accent text-accent-foreground" : "hover:bg-accent/50",
          isActive ? "text-foreground" : "text-muted-foreground",
        )}
      >
        <button
          type="button"
          onClick={handleToggle}
          className="shrink-0 rounded-md p-1.5 text-muted-foreground hover:text-foreground"
          aria-label={isExpanded ? "Collapse vault" : "Expand vault"}
        >
          <ChevronIcon className="h-4 w-4" />
        </button>
        <button
          type="button"
          onClick={handleTitleClick}
          className="flex min-w-0 flex-1 items-center gap-1.5 py-1.5 text-left"
        >
          <VaultIcon className="h-4 w-4 shrink-0" />
          <span className="min-w-0 flex-1 truncate">{vault.name}</span>
        </button>
        {isExpanded && !isLoading && (
          <span className="shrink-0 text-xs font-normal text-muted-foreground">{itemCount}</span>
        )}
      </div>

      {isExpanded && isLoading && (
        <p className="px-5 py-1 text-sm text-muted-foreground">Loading…</p>
      )}
      {isExpanded && !isLoading && itemCount + folders.length === 0 && (
        <p className="px-5 py-1 text-sm italic text-muted-foreground/70">Empty</p>
      )}
      {isExpanded && (
        <div className="ml-3 border-l border-border/70 pl-1.5">
          <FolderTreeView
            folders={folders}
            standaloneNotes={organized}
            autoGeneratedNotes={autoGenerated}
            documents={documents}
            selection={isActive ? selection : { type: "none" }}
            onSelectNote={(note, folderPath) => onSelectNote(note, vault, folderPath)}
            onSelectDocument={(document) => onSelectDocument(document, vault)}
            onSelectFolder={(folderPath) => onSelectCollection(vault, folderPath)}
          />
        </div>
      )}
    </section>
  );
}
