import { useMemo } from "react";
import type { FetchResult } from "../../../api/ConceptClient";
import { columnIndex } from "../../../runtime/useConceptRows";
import type { AppWidgetDef } from "../../../schema/appDefinition.types";

interface HeatmapWidgetProps {
  widget: AppWidgetDef;
  data: FetchResult;
}

interface HeatmapModel {
  rowKeys: string[];
  colKeys: string[];
  cells: Map<string, number>;
  max: number;
}

function buildModel(data: FetchResult, widget: AppWidgetDef): HeatmapModel | null {
  const rowIndex = widget.rowCol ? columnIndex(data.columnNames, widget.rowCol) : 0;
  const colIndex = widget.colCol ? columnIndex(data.columnNames, widget.colCol) : 1;
  const valueIndex = widget.valueCol ? columnIndex(data.columnNames, widget.valueCol) : 2;
  if (rowIndex < 0 || colIndex < 0 || valueIndex < 0) return null;

  const rowKeys: string[] = [];
  const colKeys: string[] = [];
  const cells = new Map<string, number>();
  let max = 0;

  for (const row of data.rows) {
    const rowKey = String(row[rowIndex] ?? "");
    const colKey = String(row[colIndex] ?? "");
    const value = Number(row[valueIndex]) || 0;
    if (!rowKeys.includes(rowKey)) rowKeys.push(rowKey);
    if (!colKeys.includes(colKey)) colKeys.push(colKey);
    cells.set(`${rowKey}�${colKey}`, value);
    if (value > max) max = value;
  }
  return { rowKeys: rowKeys.sort(), colKeys: colKeys.sort(), cells, max };
}

function formatValue(value: number): string {
  if (Math.abs(value) >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`;
  if (Math.abs(value) >= 1_000) return `${(value / 1_000).toFixed(0)}k`;
  return value.toLocaleString();
}

/**
 * heatmap / pivot widget (ADR D4): row column × column column × value
 * column with a color scale. Cell intensity uses the theme's chart color
 * via a CSS variable, so it adapts to light/dark automatically.
 */
export function HeatmapWidget({ widget, data }: HeatmapWidgetProps) {
  const model = useMemo(() => buildModel(data, widget), [data, widget]);

  if (!model || model.rowKeys.length === 0) {
    return <p className="text-xs text-muted-foreground py-4">No data</p>;
  }

  const cellValue = (rowKey: string, colKey: string) => model.cells.get(`${rowKey}�${colKey}`) ?? 0;

  return (
    <div className="overflow-auto">
      <table className="text-xs border-separate border-spacing-0.5 w-full">
        <thead>
          <tr>
            <th className="text-left text-muted-foreground font-medium px-2 py-1" />
            {model.colKeys.map((colKey) => (
              <th key={colKey} className="text-muted-foreground font-medium px-2 py-1 text-center">
                {colKey}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {model.rowKeys.map((rowKey) => (
            <tr key={rowKey}>
              <td className="text-muted-foreground font-medium px-2 py-1 whitespace-nowrap">
                {rowKey}
              </td>
              {model.colKeys.map((colKey) => {
                const value = cellValue(rowKey, colKey);
                const alpha = model.max > 0 ? 0.08 + 0.72 * (value / model.max) : 0;
                return (
                  <td
                    key={colKey}
                    className="text-center px-2 py-1.5 rounded text-foreground tabular-nums"
                    style={{ backgroundColor: `hsl(var(--chart-line) / ${alpha.toFixed(2)})` }}
                    title={`${rowKey} × ${colKey}: ${value.toLocaleString()}`}
                  >
                    {formatValue(value)}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
