import { Copy } from "lucide-react";
import type React from "react";
import { useEffect, useState } from "react";
import { toast } from "sonner";
import { formatConceptForClipboard } from "@/features/concepts/utils/conceptUtils";
import type { ConceptParam } from "@/features/concepts/utils/paramAnnotations";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/shared/components/ui/accordion";
import { Button } from "@/shared/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";

interface ConceptCardProps {
  title: string;
  description?: string;
  fields?: Record<string, string>;
  /** `@param` inputs of the concept — when present, the body groups into
   *  "Input" (params) and "Output" (fields) sections. */
  params?: ConceptParam[];
  onNavigateToCell?: () => void;
  /** Broadcast from "expand/collapse all" — applies `open` whenever `nonce` changes. */
  expandSignal?: { open: boolean; nonce: number };
  /** Optional action rendered at the right of each field row (e.g. a role picker). */
  fieldAction?: (fieldName: string) => React.ReactNode;
  /** Optional content rendered below the field list (e.g. card-level actions). */
  footer?: React.ReactNode;
}

/** Muted uppercase divider between the Input (params) and Output (fields) groups. */
const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <p className="px-3 pb-1 pt-2 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
    {children}
  </p>
);

const ConceptCard: React.FC<ConceptCardProps> = ({
  title,
  description,
  fields = {},
  params = [],
  onNavigateToCell,
  expandSignal,
  fieldAction,
  footer,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);

  // biome-ignore lint/correctness/useExhaustiveDependencies: respond only to nonce changes
  useEffect(() => {
    if (expandSignal) setIsExpanded(expandSignal.open);
  }, [expandSignal?.nonce]);

  const fieldOrder = Object.keys(fields);
  const hasParams = params.length > 0;

  const handleCopy = () => {
    navigator.clipboard.writeText(formatConceptForClipboard({ predicate_name: title, fields }));
    toast.success("Copied to clipboard");
  };

  const handleTitleClick = (e: React.MouseEvent) => {
    if (!onNavigateToCell) return;
    e.stopPropagation();
    onNavigateToCell();
  };

  return (
    <Accordion
      type="single"
      collapsible
      className="rounded-lg overflow-hidden bg-card"
      value={isExpanded ? "item-1" : ""}
      onValueChange={(value) => setIsExpanded(!!value)}
    >
      <AccordionItem value="item-1" className="border rounded-lg group">
        {/* Header row is its own positioning context so the copy button stays
            pinned to the title bar — anchoring to the item would drop it into
            the vertical middle of the fields once expanded. */}
        <div className="relative">
          <AccordionTrigger className="px-3 py-2 hover:no-underline hover:bg-muted/50 transition-colors duration-200">
            <div className="flex w-full min-w-0 items-center gap-2 pr-7">
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span
                      className={`flex-1 min-w-0 truncate text-left text-sm font-medium ${
                        onNavigateToCell ? "cursor-pointer hover:text-primary" : ""
                      }`}
                      onClick={handleTitleClick}
                    >
                      {title}
                    </span>
                  </TooltipTrigger>
                  <TooltipContent>
                    <p>
                      {title}
                      {onNavigateToCell ? " (Click to navigate to cell)" : ""}
                    </p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            </div>
          </AccordionTrigger>
          {/* Sibling of the trigger, not a child: Radix's AccordionTrigger is a
              <button>, and a <button> may not contain another <button>. Overlaid
              just left of the chevron. */}
          <Button
            variant="ghost"
            size="icon"
            onClick={(e) => {
              e.stopPropagation();
              handleCopy();
            }}
            title="Copy concept"
            className="absolute right-8 top-1/2 z-10 h-6 w-6 -translate-y-1/2 opacity-0 transition-opacity duration-200 hover:bg-muted group-hover:opacity-100"
          >
            <Copy className="h-3.5 w-3.5" />
          </Button>
        </div>
        <AccordionContent className="pt-0 pb-0">
          {description && (
            <p className="px-3 pb-2 text-xs leading-relaxed text-muted-foreground">{description}</p>
          )}
          {hasParams && (
            <div className="border-t border-border/50">
              <SectionLabel>Input</SectionLabel>
              <div className="divide-y divide-border/50 border-t border-border/50">
                {params.map((param) => (
                  <div key={param.name} className="flex items-center gap-2 px-3 py-1 text-xs">
                    <span className="flex-1 min-w-0 truncate text-foreground/80" title={param.name}>
                      @{param.name}
                    </span>
                    <span
                      className="max-w-[45%] flex-shrink-0 truncate text-right font-mono text-[10px] text-muted-foreground"
                      title={param.defaultValue ? `default: ${param.defaultValue}` : undefined}
                    >
                      {param.defaultValue ?? ""}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
          {hasParams && fieldOrder.length > 0 && <SectionLabel>Output</SectionLabel>}
          {fieldOrder.length > 0 && (
            <div className="divide-y divide-border/50 border-t border-border/50">
              {fieldOrder.map((fieldName) => (
                <div key={fieldName} className="flex items-center gap-2 px-3 py-1 text-xs">
                  <span className="flex-1 min-w-0 truncate text-foreground/80" title={fieldName}>
                    {fieldName}
                  </span>
                  <span className="w-16 flex-shrink-0 text-right font-mono text-[10px] text-muted-foreground">
                    {fields[fieldName]}
                  </span>
                  {fieldAction && (
                    <span className="w-14 flex-shrink-0 flex justify-end">
                      {fieldAction(fieldName)}
                    </span>
                  )}
                </div>
              ))}
            </div>
          )}
          {footer && <div className="border-t border-border/50">{footer}</div>}
        </AccordionContent>
      </AccordionItem>
    </Accordion>
  );
};

export default ConceptCard;
