import { useEffect, useRef, useState } from "react";
import { Navigate, useParams } from "react-router-dom";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { ComputeStartingOverlay } from "@/features/compute/components/ComputeStartingOverlay";
import { useAutoStartCompute } from "@/features/compute/hooks/useAutoStartCompute";
import { DASHBOARD_CONFIG_MAP } from "@/features/dashboards/dashboardConfigRegistry";
import { RemoteAppHost } from "@/features/dashboards/remotes/RemoteAppHost";
import { setCurrentOntologyId, setCurrentOntologyScope } from "@/features/ontologies/utils";
import SidePanel from "@/shared/components/layout/SidePanel";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";
import { trackAppOpened } from "@/shared/services/analyticsEvents";

export default function AppsDashboardPage() {
  const { dashboardId } = useParams<{ dashboardId: string }>();
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const seededRef = useRef<string | null>(null);

  const loaded = usePermissionsStore((state) => state.loaded);
  const visibleApps = usePermissionsStore((state) => state.visibleApps);

  // Resolve config early — hooks must be called unconditionally before any early returns
  const config = dashboardId ? DASHBOARD_CONFIG_MAP[dashboardId] : undefined;
  const {
    phase: computePhase,
    statusMessage,
    machineName,
    liveMessage,
  } = useAutoStartCompute(config?.computeRequirements);

  const entry = visibleApps.find((d) => d.id === dashboardId);

  // Record that an end user opened this federated app, once per app id.
  const openedRef = useRef<string | null>(null);
  useEffect(() => {
    if (!entry) return;
    if (openedRef.current === entry.id) return;
    openedRef.current = entry.id;
    trackAppOpened({
      appId: entry.id,
      appName: entry.name,
      appType: "federated",
      ontologyId: config?.ontologyId,
    });
  }, [entry, config]);

  // Seed project context before the Dashboard child renders so useProjectId() /
  // useProjectScope() lazy initialisers get the correct values without needing the
  // project editor page to have been visited first.
  // The ref guard ensures the event is only dispatched when the active dashboard changes.
  if (dashboardId && seededRef.current !== dashboardId) {
    if (config) {
      if (!config.ontologyId) {
        throw new Error(
          `[AppsDashboardPage] config for "${dashboardId}" has an empty projectId. ` +
            `Fill it in at the corresponding *.config.ts file before using this app.`,
        );
      }
      seededRef.current = dashboardId;
      setCurrentOntologyId(config.ontologyId);
      setCurrentOntologyScope(config.scope);
    }
  }

  const marginClass = sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0";

  if (loaded && !entry) {
    const firstApp = visibleApps[0];
    return <Navigate to={firstApp ? `/apps/${firstApp.id}` : "/"} replace />;
  }

  if (!entry) {
    return (
      <div className="flex h-screen overflow-hidden">
        {sidebarVisible && (
          <SidePanel
            activeTab=""
            onTabChange={() => {}}
            visible={sidebarVisible}
            onToggle={toggleSidebar}
            onCollapsedChange={setSidebarCollapsed}
          />
        )}
        <div
          className={`flex flex-1 items-center justify-center ${marginClass} transition-all duration-200`}
        >
          <p className="text-sm text-muted-foreground">App not found.</p>
        </div>
      </div>
    );
  }

  // Remote (federated) client app: RemoteAppHost owns config load, context seeding and
  // compute auto-start. Local apps keep the build-time component + page-level compute path.
  const renderAppContent = () => {
    if (entry.remoteUrl) {
      return (
        // key on the app id forces a full unmount+remount when switching between
        // two federated apps (same /apps/:dashboardId route, changing param).
        // Without it React reuses the RemoteAppHost instance and the remote view
        // gets stuck on the previous app.
        <RemoteAppHost
          key={entry.id}
          dashboardId={entry.id}
          remoteUrl={entry.remoteUrl}
          name={entry.name}
          onToggleSidebar={toggleSidebar}
          sidebarVisible={sidebarVisible}
        />
      );
    }
    if (!entry.component) {
      return <p className="text-sm text-muted-foreground">App is not available.</p>;
    }
    if (computePhase !== "ready") {
      return (
        <ComputeStartingOverlay
          phase={computePhase}
          statusMessage={statusMessage}
          machineName={machineName}
          liveMessage={liveMessage}
        />
      );
    }
    const Dashboard = entry.component;
    return (
      <Dashboard
        onToggleSidebar={toggleSidebar}
        sidebarVisible={sidebarVisible}
        name={entry.name}
        description={config?.description}
      />
    );
  };

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab=""
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}
      <div className={`flex-1 ${marginClass} overflow-hidden transition-all duration-200`}>
        {renderAppContent()}
      </div>
    </div>
  );
}
