import { Users } from "lucide-react";
import type React from "react";
import { Badge } from "@/shared/components/ui/badge";
import type { ShareRole } from "../types";

interface TeamMemberShareRowProps {
  label: string;
  teamName: string;
  role: ShareRole;
}

// Read-only person row for someone who has access through a shared team (not a
// direct share). Access is governed by the team, so there are no per-row
// controls here — the team name is shown in parentheses to explain the source.
const TeamMemberShareRow: React.FC<TeamMemberShareRowProps> = ({ label, teamName, role }) => (
  <div className="flex items-center justify-between gap-3 rounded-md border border-border bg-card px-3 py-2.5">
    <div className="flex min-w-0 items-center gap-1.5">
      <span className="truncate text-sm font-medium text-foreground">{label}</span>
      <span className="inline-flex flex-shrink-0 items-center gap-1 text-xs text-muted-foreground">
        <Users className="h-3 w-3" />({teamName})
      </span>
    </div>
    <Badge variant="outline" className="flex-shrink-0 capitalize">
      {role}
    </Badge>
  </div>
);

export default TeamMemberShareRow;
