import { Cpu, MemoryStick, Server, Zap } from "lucide-react";
import type React from "react";
import { useEffect, useState } from "react";
import type { DatabricksCluster } from "@/features/compute/types";
import type { AvailabilityResult, UserMachine } from "@/features/compute/utils";
import { Button } from "@/shared/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

type SelectedItem =
  | { type: "pool"; userMachineId: string }
  | { type: "databricks"; clusterId: string }
  | null;

interface StartMachineModalProps {
  open: boolean;
  onClose: () => void;
  stoppedMachines: UserMachine[];
  availabilityResults: Record<string, AvailabilityResult>;
  checkingAvailability: Record<string, boolean>;
  onStartMachine: (userMachineId: string, machineId: string) => Promise<void>;
  databricksClusters?: DatabricksCluster[];
  loadingDatabricksClusters?: boolean;
  onStartDatabricksCluster?: (clusterId: string) => Promise<void>;
  onFetchDatabricksClusters?: () => void;
}

export const StartMachineModal: React.FC<StartMachineModalProps> = ({
  open,
  onClose,
  stoppedMachines,
  availabilityResults,
  checkingAvailability,
  onStartMachine,
  databricksClusters = [],
  loadingDatabricksClusters = false,
  onStartDatabricksCluster,
  onFetchDatabricksClusters,
}) => {
  const [selectedItem, setSelectedItem] = useState<SelectedItem>(null);
  const [isStarting, setIsStarting] = useState(false);
  // Snapshot of the pool machine that was started — kept so the row stays visible
  // even after the machine moves out of the stoppedMachines list.
  const [startedMachineSnapshot, setStartedMachineSnapshot] = useState<UserMachine | null>(null);
  // Cluster that was started — track it so we can show live state updates
  const [startingClusterId, setStartingClusterId] = useState<string | null>(null);

  const notRunningDatabricksClusters = databricksClusters.filter((c) => c.state !== "RUNNING");

  // Fetch clusters and auto-select first available option when modal opens
  useEffect(() => {
    if (open) {
      // Trigger a fresh cluster fetch so we always have up-to-date data
      onFetchDatabricksClusters?.();

      if (stoppedMachines.length > 0) {
        setSelectedItem({ type: "pool", userMachineId: stoppedMachines[0].id });
      } else if (notRunningDatabricksClusters.length > 0) {
        setSelectedItem({
          type: "databricks",
          clusterId: notRunningDatabricksClusters[0].cluster_id,
        });
      }
    }
    // Intentionally only runs when the modal opens — auto-selects from whatever
    // data is available at that moment. Index-based deps removed: they crash when
    // either array is empty and re-running mid-session adds no value.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, onFetchDatabricksClusters]);

  useEffect(() => {
    if (!open) {
      setIsStarting(false);
      setSelectedItem(null);
      setStartedMachineSnapshot(null);
      setStartingClusterId(null);
    }
  }, [open]);

  const handleStart = async () => {
    if (!selectedItem) return;

    if (selectedItem.type === "pool") {
      const selected = stoppedMachines.find((um) => um.id === selectedItem.userMachineId);
      if (!selected?.machines) return;
      setStartedMachineSnapshot(selected);
      setIsStarting(true);
      try {
        await onStartMachine(selected.id, selected.machines.id);
      } catch {
        setIsStarting(false);
        setStartedMachineSnapshot(null);
      }
    } else if (selectedItem.type === "databricks" && onStartDatabricksCluster) {
      setStartingClusterId(selectedItem.clusterId);
      setIsStarting(true);
      try {
        await onStartDatabricksCluster(selectedItem.clusterId);
      } catch {
        setIsStarting(false);
        setStartingClusterId(null);
      }
    }
  };

  const ALREADY_STARTING_STATUSES = ["starting", "stopping", "pending", "restarting"];

  // While starting a pool machine via this modal's Start button, show the snapshot.
  const displayPoolMachines =
    isStarting && startedMachineSnapshot ? [startedMachineSnapshot] : stoppedMachines;

  const startedMachineStatus = startedMachineSnapshot?.machines
    ? availabilityResults[startedMachineSnapshot.machines.id]?.machine_status
    : undefined;
  const isPoolMachineRunning =
    isStarting && startedMachineSnapshot && startedMachineStatus === "started";

  // Live state of the Databricks cluster being started
  const startingCluster = startingClusterId
    ? databricksClusters.find((c) => c.cluster_id === startingClusterId)
    : null;
  const isDatabricksRunning = isStarting && startingCluster?.state === "RUNNING";

  const isRunning = isPoolMachineRunning || isDatabricksRunning;

  // Disable Start if any pool machine is loading/starting
  const anyMachineLoadingOrStarting =
    !isStarting &&
    stoppedMachines.some((um) => {
      if (!um.machines) return false;
      const machineId = um.machines.id;
      const isChecking = checkingAvailability[machineId];
      const hasResult = availabilityResults[machineId] !== undefined;
      const status = availabilityResults[machineId]?.machine_status;
      return (
        isChecking || !hasResult || (status ? ALREADY_STARTING_STATUSES.includes(status) : false)
      );
    });

  const canStart = selectedItem !== null && !isStarting && !anyMachineLoadingOrStarting;
  const showPoolSection = displayPoolMachines.length > 0;
  // Show Databricks section while loading (so the section appears immediately) or when there are non-running clusters
  const hasDatabricksCallback = !!onFetchDatabricksClusters;
  const showDatabricksSection =
    !isStarting &&
    hasDatabricksCallback &&
    (loadingDatabricksClusters || notRunningDatabricksClusters.length > 0);

  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        if (!o) onClose();
      }}
    >
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Server className="h-5 w-5" />
            Start a Compute Machine
          </DialogTitle>
          <DialogDescription>
            To run this concept, you need a compute machine running. Select one to start.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Compute Pool Machines */}
          {showPoolSection && (
            <div className="space-y-2">
              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
                Compute Pool Machines
              </p>
              {displayPoolMachines.map((userMachine) => {
                const machine = userMachine.machines;
                if (!machine) return null;
                const isSelected =
                  selectedItem?.type === "pool" && selectedItem.userMachineId === userMachine.id;
                const isChecking = checkingAvailability[machine.id];
                const hasResult = availabilityResults[machine.id] !== undefined;
                const machineStatus = availabilityResults[machine.id]?.machine_status;

                const isLoadingStatus = !isStarting && (isChecking || !hasResult);
                const alreadyStarting =
                  !isStarting && !isLoadingStatus && machineStatus
                    ? ALREADY_STARTING_STATUSES.includes(machineStatus)
                    : false;

                const thisIsRunning = isStarting && isSelected && machineStatus === "started";
                const thisIsStarting = isStarting && isSelected && machineStatus !== "started";
                const nonSelectable = isStarting || alreadyStarting || isLoadingStatus;

                return (
                  <div
                    key={userMachine.id}
                    onClick={() => {
                      if (!nonSelectable)
                        setSelectedItem({ type: "pool", userMachineId: userMachine.id });
                    }}
                    className={`rounded-lg border p-3 transition-colors ${
                      nonSelectable ? "cursor-default opacity-80" : "cursor-pointer"
                    } ${
                      isSelected && !alreadyStarting && !isLoadingStatus
                        ? "border-primary bg-primary/5"
                        : alreadyStarting || isLoadingStatus
                          ? "border-blue-300 bg-blue-50/50"
                          : "border-border hover:border-primary/50 hover:bg-muted/50"
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <div>
                        <div className="flex items-center gap-1.5">
                          <Server className="h-3.5 w-3.5 text-muted-foreground" />
                          <span className="font-medium text-sm">{machine.name}</span>
                        </div>
                        <div className="flex items-center gap-3 mt-1 text-xs text-muted-foreground">
                          <span className="flex items-center gap-1">
                            <Cpu className="h-3 w-3" />
                            {machine.cores} cores
                          </span>
                          <span className="flex items-center gap-1">
                            <MemoryStick className="h-3 w-3" />
                            {machine.memory_gb} GB
                          </span>
                        </div>
                      </div>

                      <div className="flex items-center gap-1.5">
                        {thisIsRunning && (
                          <>
                            <span className="text-xs text-green-600">running</span>
                            <div className="h-2.5 w-2.5 rounded-full bg-green-500" />
                          </>
                        )}
                        {(thisIsStarting || alreadyStarting || isLoadingStatus) && (
                          <>
                            <span className="text-xs text-blue-600">
                              {isLoadingStatus ? "loading..." : "starting"}
                            </span>
                            <PrometheuxSpinner size={16} />
                          </>
                        )}
                        {!nonSelectable && isSelected && (
                          <div className="h-2.5 w-2.5 rounded-full bg-primary" />
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {/* Databricks Clusters */}
          {showDatabricksSection && (
            <div className="space-y-2">
              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
                Databricks Clusters
              </p>
              {loadingDatabricksClusters ? (
                <div className="flex items-center gap-2 rounded-lg border border-border p-3 text-xs text-muted-foreground">
                  <PrometheuxSpinner size={16} />
                  Loading clusters...
                </div>
              ) : (
                <div className="max-h-72 space-y-2 overflow-y-auto pr-1">
                  {notRunningDatabricksClusters.map((cluster) => {
                    const isSelected =
                      selectedItem?.type === "databricks" &&
                      selectedItem.clusterId === cluster.cluster_id;
                    const isThisStarting = isStarting && startingClusterId === cluster.cluster_id;
                    const isThisRunning = isThisStarting && cluster.state === "RUNNING";
                    const isTransitional = ["PENDING", "RESTARTING", "RESIZING"].includes(
                      cluster.state,
                    );
                    // Only TERMINATED clusters can be started; others are in-progress or errored
                    const canBeStarted = cluster.state === "TERMINATED";
                    const nonSelectable = isStarting || !canBeStarted;

                    return (
                      <div
                        key={cluster.cluster_id}
                        onClick={() => {
                          if (!nonSelectable)
                            setSelectedItem({ type: "databricks", clusterId: cluster.cluster_id });
                        }}
                        className={`rounded-lg border p-3 transition-colors ${
                          nonSelectable ? "cursor-default opacity-80" : "cursor-pointer"
                        } ${
                          isSelected && canBeStarted
                            ? "border-primary bg-primary/5"
                            : isTransitional || isThisStarting
                              ? "border-blue-300 bg-blue-50/50"
                              : "border-border hover:border-primary/50 hover:bg-muted/50"
                        }`}
                      >
                        <div className="flex items-center justify-between gap-2">
                          <div className="flex min-w-0 flex-1 items-center gap-1.5">
                            <Zap className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                            <span
                              className="truncate font-medium text-sm"
                              title={cluster.cluster_name}
                            >
                              {cluster.cluster_name}
                            </span>
                          </div>

                          <div className="flex items-center gap-1.5 shrink-0">
                            {isThisRunning && (
                              <>
                                <span className="text-xs text-green-600">running</span>
                                <div className="h-2.5 w-2.5 rounded-full bg-green-500" />
                              </>
                            )}
                            {isThisStarting && !isThisRunning && (
                              <>
                                <span className="text-xs text-blue-600">starting</span>
                                <PrometheuxSpinner size={16} />
                              </>
                            )}
                            {!isThisStarting && isTransitional && (
                              <>
                                <span className="text-xs text-blue-600">
                                  {cluster.state.toLowerCase()}
                                </span>
                                <PrometheuxSpinner size={16} />
                              </>
                            )}
                            {!isThisStarting && !isTransitional && cluster.state === "ERROR" && (
                              <span className="text-xs text-red-500">{cluster.state}</span>
                            )}
                            {!isThisStarting &&
                              !isTransitional &&
                              cluster.state === "TERMINATED" &&
                              !isSelected && (
                                <span className="text-xs text-muted-foreground">
                                  {cluster.state}
                                </span>
                              )}
                            {!nonSelectable && isSelected && (
                              <div className="h-2.5 w-2.5 rounded-full bg-primary" />
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {isStarting && !isRunning && (
            <p className="text-xs text-muted-foreground pt-1">
              This may take a few minutes. You can close this dialog and try running again once the
              machine is ready.
            </p>
          )}
          {isRunning && (
            <p className="text-xs text-green-600 pt-1">
              Machine is ready. You can now close this dialog and run your concept.
            </p>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            {isStarting ? "Close" : "Cancel"}
          </Button>
          <Button onClick={handleStart} disabled={!canStart}>
            Start
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
