import type { AppPageDef, RunGroupDef } from "../schema/appDefinition.types";
import { type FactRecord, serializeFacts } from "./factsSerializer";
import { resolveTemplate, templateRef } from "./templateResolver";

export interface GroupBindings {
  params: Record<string, unknown>;
  preambleFacts: string;
}

/** "formId.groupId" → ordered field ids of that record group. */
export function recordGroupFieldOrders(page: AppPageDef): Record<string, string[]> {
  const orders: Record<string, string[]> = {};
  for (const input of page.inputs ?? []) {
    if (input.type !== "form") continue;
    for (const section of input.sections ?? []) {
      for (const field of section.fields) {
        if (field.type !== "record_group") continue;
        orders[`${input.id}.${field.id}`] = (field.fields ?? []).map((rowField) => rowField.id);
      }
    }
  }
  return orders;
}

/**
 * Resolve a run group's `params` templates and serialize its `facts` record
 * groups into preamble-fact programs, against the given context values.
 * Throws when a facts binding has no rows to send.
 */
export function resolveGroupBindings(
  group: RunGroupDef,
  contextValues: Record<string, unknown>,
  fieldOrders: Record<string, string[]>,
): GroupBindings {
  const params: Record<string, unknown> = {};
  for (const [name, template] of Object.entries(group.params ?? {})) {
    const resolved = resolveTemplate(template, contextValues);
    if (resolved !== undefined && resolved !== null && resolved !== "") {
      params[name] = resolved;
    }
  }
  const factsPrograms: string[] = [];
  for (const [predicate, template] of Object.entries(group.facts ?? {})) {
    const ref = templateRef(template);
    const resolved = ref ? contextValues[ref] : undefined;
    if (!Array.isArray(resolved) || resolved.length === 0) {
      throw new Error(`No records for '${predicate}' — submit the form first`);
    }
    const order = ref ? (fieldOrders[ref] ?? []) : [];
    factsPrograms.push(serializeFacts(predicate, resolved as FactRecord[], order));
  }
  return { params, preambleFacts: factsPrograms.join("\n") };
}
