import type React from "react";
import { useEffect, useRef, useState } from "react";
import { cn } from "@/shared/lib/utils";

interface TreeRenameInputProps {
  initialValue: string;
  isNested: boolean;
  Icon: React.ComponentType<{ className?: string }>;
  iconClassName: string;
  onCommit: (value: string) => void;
  onCancel: () => void;
}

/**
 * Inline-rename input used by TreeFile when a cell is in edit mode. Auto-focuses
 * and selects on mount. Enter commits, Escape cancels, blur commits.
 */
export const TreeRenameInput: React.FC<TreeRenameInputProps> = ({
  initialValue,
  isNested,
  Icon,
  iconClassName,
  onCommit,
  onCancel,
}) => {
  const [value, setValue] = useState(initialValue);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
    inputRef.current?.select();
  }, []);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      e.preventDefault();
      onCommit(value);
    } else if (e.key === "Escape") {
      e.preventDefault();
      onCancel();
    }
  };

  return (
    <div
      className={cn(
        "w-full flex items-center gap-1.5 py-0.5 text-xs",
        isNested ? "pl-7 pr-2" : "px-2",
      )}
    >
      <Icon className={iconClassName} />
      <input
        ref={inputRef}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => onCommit(value)}
        className="flex-1 min-w-0 h-5 px-1 text-xs bg-background border border-primary/60 rounded-sm focus:outline-none focus:ring-1 focus:ring-primary/60"
      />
    </div>
  );
};
