import { useCallback, useEffect, useRef, useState } from "react";
import { OntologyService, type TemplateData } from "@/features/ontologies/api";
import { useAuthToken } from "@/shared/auth/useAuthToken";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

export const useTemplates = () => {
  const [templates, setTemplates] = useState<TemplateData[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [_lastFetchTime, setLastFetchTime] = useState<number>(0);
  const templatesRef = useRef<TemplateData[]>([]);
  const authToken = useAuthToken();

  // Update ref when templates change
  useEffect(() => {
    templatesRef.current = templates;
  }, [templates]);

  // Cache duration: 60 seconds (templates change less frequently)
  const CACHE_DURATION = 60 * 1000;

  // Use a ref to track last fetch time to avoid dependency issues
  const lastFetchTimeRef = useRef<number>(0);

  // Load templates from API with caching
  const loadTemplates = useCallback(
    async (force: boolean = false) => {
      const now = Date.now();

      // Use cache if not forcing and cache is still valid
      if (
        !force &&
        now - lastFetchTimeRef.current < CACHE_DURATION &&
        templatesRef.current.length > 0
      ) {
        setIsLoading(false);
        return;
      }

      // In production mode, wait for JWT token to be available
      if (!PROMETHEUX_CONFIG.DEVELOPMENT_MODE && !authToken) {
        setIsLoading(false);
        return;
      }

      try {
        setIsLoading(true);
        const templatesData = await OntologyService.listTemplates();
        setTemplates(templatesData);
        lastFetchTimeRef.current = now;
        setLastFetchTime(now);
      } catch (error) {
        console.error("Error loading templates:", error);
      } finally {
        setIsLoading(false);
      }
    },
    [authToken],
  );

  // Initial load - only run once on mount
  useEffect(() => {
    loadTemplates();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadTemplates]);

  const prevBaseUrlRef = useRef(PROMETHEUX_CONFIG.BASE_URL);

  // Sign-in produces the token after this hook has already mounted and given
  // up once, so the load is retried when it lands.
  useEffect(() => {
    if (!authToken || templates.length > 0) return;
    loadTemplates(true);
  }, [authToken, loadTemplates, templates.length]);

  // Retry loading templates when BASE_URL changes (after session restoration)
  useEffect(() => {
    const urlChanged = prevBaseUrlRef.current !== PROMETHEUX_CONFIG.BASE_URL;
    prevBaseUrlRef.current = PROMETHEUX_CONFIG.BASE_URL;

    if (urlChanged && PROMETHEUX_CONFIG.AUTH_TOKEN && templates.length === 0) {
      loadTemplates(true); // Force refresh
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [templates.length, loadTemplates]);

  return {
    templates,
    isLoading,
    loadTemplates,
  };
};
