/**
 * Utility functions for managing sessionStorage with event notifications
 * This ensures that hooks can react to sessionStorage changes
 */

import { extractUrlParams } from "@/shared/utils/navigationUtils";

/**
 * Sets a sessionStorage item and dispatches a custom event to notify listeners
 */
const setSessionStorageItem = (key: string, value: string) => {
  sessionStorage.setItem(key, value);
  // Dispatch custom event to notify components in the same tab
  window.dispatchEvent(
    new CustomEvent("sessionStorageChanged", {
      detail: { key, value },
    }),
  );
};

/**
 * Sets the current project ID in sessionStorage and notifies listeners
 */
export const setCurrentOntologyId = (ontologyId: string) => {
  setSessionStorageItem("currentOntologyId", ontologyId);
};

/**
 * Sets the current project scope in sessionStorage and notifies listeners
 */
export const setCurrentOntologyScope = (ontologyScope: string) => {
  setSessionStorageItem("currentOntologyScope", ontologyScope);
};

/**
 * Resolves the current project id, treating the URL as the source of truth on
 * editor routes and falling back to sessionStorage for routes that don't carry
 * the project id (e.g. federated apps).
 */
export const resolveCurrentOntologyId = (): string | null =>
  extractUrlParams(window.location.pathname).ontologyId ??
  sessionStorage.getItem("currentOntologyId");

/**
 * Aligns the sessionStorage project session with the project in the URL.
 * Direct URL opens (new tab, pasted link) bypass the navigation handlers that
 * normally write these keys, leaving API clients that resolve the project from
 * sessionStorage without a context. The scope is intentionally left untouched:
 * it is not derivable from the URL, and every reader already defaults to "user".
 *
 * Writes without dispatching sessionStorageChanged: this runs during the
 * project route's initial render as a bootstrap, before any consumer could
 * have read the missing value — and dispatching mid-render would trigger
 * setState-in-render on listeners still mounted from the previous route.
 */
export const hydrateOntologySessionFromUrl = (pathname: string) => {
  const { ontologyId } = extractUrlParams(pathname);
  if (!ontologyId) return;
  if (sessionStorage.getItem("currentOntologyId") === ontologyId) return;
  sessionStorage.setItem("currentOntologyId", ontologyId);
};
