import type React from "react";
import { useEffect, useRef, useState } from "react";
import { DeleteCellDialog } from "@/features/concept-editor/components/DeleteCellDialog";
import { ExplorerSearchBar } from "@/features/concept-editor/components/ExplorerSearchBar";
import { ExplorerTreeHeader } from "@/features/concept-editor/components/ExplorerTreeHeader";
import { TreeFile, TreeFolder } from "@/features/concept-editor/components/ExplorerTreeItems";
import { useDeleteCellRequest } from "@/features/concept-editor/hooks/useDeleteCellRequest";
import { ROOT_TARGET, useTreeDragDrop } from "@/features/concept-editor/hooks/useTreeDragDrop";
import { useTreeKeyboardNav } from "@/features/concept-editor/hooks/useTreeKeyboardNav";
import type { ConceptCell } from "@/features/concept-editor/types";
import { cn } from "@/shared/lib/utils";

interface ExplorerTreeProps {
  groupNames: string[];
  groupedCells: Record<string, ConceptCell[]>;
  ungroupedCells: ConceptCell[];
  collapsedGroups: Record<string, boolean>;
  selectedCellId: string | null;
  onSelectCell: (cellId: string) => void;
  onToggleGroupCollapse: (groupName: string) => void;
  canEditOntologies: boolean;
  onAddCell?: () => void;
  onAddGroup?: () => void;
  onAddCellToGroup: (cellId: string, groupName: string) => void;
  onRemoveCellFromGroup: (cellId: string) => void;
  onAddCellInGroup?: (groupName: string | null) => void;
  /** Rename a cell to a new display name. Parent decides whether to hit the backend. */
  onRenameCell?: (cellId: string, newName: string) => void | Promise<void>;
  onDeleteCell?: (cellId: string) => void | Promise<void>;
  /** Isolate a concept's upstream dependency slice (lineage view only). */
  onIsolateConcept?: (conceptName: string) => void;
  onRenameGroup?: (groupName: string) => void;
  onDeleteGroup?: (groupName: string) => void;
  onExpandAllGroups?: () => void;
  onCollapseAllGroups?: () => void;
  /** Shared search term used by the Explorer and toolbar. */
  searchTerm?: string;
  onSearchTermChange?: (value: string) => void;
  /** Editor actions rendered in the header (Refresh / Save All). */
  onRefresh?: () => void;
  isRefreshing?: boolean;
  onSaveAll?: () => void;
  isSavingAll?: boolean;
  hasUnsavedChanges?: boolean;
  /** Open the concept restrictions dialog (owner-only). */
  onManagePermissions?: (predicateName: string) => void;
  isOntologyOwner?: boolean;
}

const ExplorerTree: React.FC<ExplorerTreeProps> = ({
  groupNames,
  groupedCells,
  ungroupedCells,
  collapsedGroups,
  selectedCellId,
  onSelectCell,
  onToggleGroupCollapse,
  canEditOntologies,
  onAddCell,
  onAddGroup,
  onAddCellToGroup,
  onRemoveCellFromGroup,
  onAddCellInGroup,
  onRenameCell,
  onDeleteCell,
  onIsolateConcept,
  onRenameGroup,
  onDeleteGroup,
  onExpandAllGroups,
  onCollapseAllGroups,
  searchTerm,
  onSearchTermChange,
  onRefresh,
  isRefreshing,
  onSaveAll,
  isSavingAll,
  hasUnsavedChanges,
  onManagePermissions,
  isOntologyOwner = false,
}) => {
  const isEmpty = groupNames.length === 0 && ungroupedCells.length === 0;
  const showHeaderActions = canEditOntologies && (onAddCell || onAddGroup);
  const supportsSearch = onSearchTermChange !== undefined;
  const hasActiveSearch = !!searchTerm?.trim();
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [editingCellId, setEditingCellId] = useState<string | null>(null);

  // If the search term gets set externally (e.g. via the toolbar) while the
  // panel is closed, open it so the active filter is visible in this surface.
  useEffect(() => {
    if (hasActiveSearch && !isSearchOpen) setIsSearchOpen(true);
  }, [hasActiveSearch, isSearchOpen]);

  const toggleSearch = () => {
    const next = !isSearchOpen;
    setIsSearchOpen(next);
    if (!next) onSearchTermChange?.("");
  };

  const closeSearch = () => {
    setIsSearchOpen(false);
    onSearchTermChange?.("");
  };

  const {
    dropTarget,
    cellDropTarget,
    handleDragStartCell,
    handleDragEndCell,
    handleDragOverCell,
    handleDragLeaveCell,
    handleDropOnCell,
    handleDragOverFolder,
    handleDragLeaveFolder,
    handleDropOnFolder,
    handleDragOverRoot,
    handleDragLeaveRoot,
    handleDropOnRoot,
  } = useTreeDragDrop({ canEditOntologies, onAddCellToGroup, onRemoveCellFromGroup });

  const startInlineRename = (cellId: string) => setEditingCellId(cellId);
  const cancelInlineRename = () => setEditingCellId(null);
  const commitInlineRename = (cellId: string, value: string) => {
    const trimmed = value.trim();
    setEditingCellId(null);
    if (!trimmed || !onRenameCell) return;
    void onRenameCell(cellId, trimmed);
  };

  // Delete actions (keyboard Delete + context menu Delete) stage through a
  // confirmation dialog rather than firing the destructive action directly.
  const { cellPendingDelete, requestDeleteCell, confirmDelete, cancelDelete } =
    useDeleteCellRequest({
      groupedCells,
      ungroupedCells,
      onDelete: canEditOntologies ? onDeleteCell : undefined,
    });

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const { handleKeyDown } = useTreeKeyboardNav({
    groupNames,
    groupedCells,
    ungroupedCells,
    collapsedGroups,
    selectedCellId,
    onSelectCell,
    containerRef: scrollContainerRef,
    onStartRename: canEditOntologies && onRenameCell ? startInlineRename : undefined,
    onDeleteCell: requestDeleteCell,
  });

  // Single button that flips between "expand all" and "collapse all". A
  // group counts as expanded only if collapsedGroups explicitly has it set
  // to false (undefined defaults to collapsed).
  const allGroupsExpanded =
    groupNames.length > 0 && groupNames.every((name) => collapsedGroups[name] === false);
  const toggleAllGroups =
    onExpandAllGroups || onCollapseAllGroups
      ? () => {
          if (allGroupsExpanded) onCollapseAllGroups?.();
          else onExpandAllGroups?.();
        }
      : undefined;

  return (
    <div className="w-[260px] flex-shrink-0 border-r border-border bg-card flex flex-col h-full">
      <ExplorerTreeHeader
        hasGroups={groupNames.length > 0}
        supportsSearch={supportsSearch}
        isSearchOpen={isSearchOpen}
        isSearchActive={hasActiveSearch}
        onToggleSearch={toggleSearch}
        allGroupsExpanded={allGroupsExpanded}
        onToggleAllGroups={toggleAllGroups}
        onAddCell={showHeaderActions ? onAddCell : undefined}
        onAddGroup={showHeaderActions ? onAddGroup : undefined}
        onRefresh={onRefresh}
        isRefreshing={isRefreshing}
        onSaveAll={onSaveAll}
        isSavingAll={isSavingAll}
        hasUnsavedChanges={hasUnsavedChanges}
      />
      {isSearchOpen && supportsSearch && (
        <ExplorerSearchBar
          value={searchTerm ?? ""}
          onChange={onSearchTermChange}
          onClose={closeSearch}
        />
      )}
      {/* biome-ignore lint/a11y/noStaticElementInteractions: drop zone is pointer-only; DnD has no keyboard equivalent */}
      <div
        ref={scrollContainerRef}
        tabIndex={-1}
        onKeyDown={handleKeyDown}
        className={cn(
          "flex-1 overflow-y-auto py-1 transition-colors outline-none",
          dropTarget === ROOT_TARGET && "bg-accent/30",
        )}
        onDragOver={handleDragOverRoot}
        onDragLeave={handleDragLeaveRoot}
        onDrop={handleDropOnRoot}
      >
        {groupNames.map((groupName) => {
          const cellsInGroup = groupedCells[groupName] || [];
          if (cellsInGroup.length === 0) return null;
          const isExpanded = !(collapsedGroups[groupName] ?? true);
          return (
            <TreeFolder
              key={groupName}
              groupName={groupName}
              isExpanded={isExpanded}
              cellCount={cellsInGroup.length}
              isDropTarget={dropTarget === groupName}
              canEditOntologies={canEditOntologies}
              onToggle={() => onToggleGroupCollapse(groupName)}
              onDragOver={(e) => handleDragOverFolder(e, groupName)}
              onDragLeave={handleDragLeaveFolder}
              onDrop={(e) => handleDropOnFolder(e, groupName)}
              onAddCellInGroup={onAddCellInGroup}
              onAddGroup={onAddGroup}
              onRenameGroup={onRenameGroup}
              onDeleteGroup={onDeleteGroup}
            >
              {isExpanded &&
                cellsInGroup.map((cell) => (
                  <TreeFile
                    key={cell.id}
                    cell={cell}
                    isSelected={cell.id === selectedCellId}
                    isNested
                    canDrag={canEditOntologies}
                    canEditOntologies={canEditOntologies}
                    isEditing={editingCellId === cell.id}
                    onSelect={() => onSelectCell(cell.id)}
                    onDragStart={(e) => handleDragStartCell(e, cell)}
                    onDragEnd={handleDragEndCell}
                    onDragOver={(e) => handleDragOverCell(e, cell)}
                    onDragLeave={(e) => handleDragLeaveCell(e, cell.id)}
                    onDrop={(e) => handleDropOnCell(e, cell)}
                    dropPosition={
                      cellDropTarget?.cellId === cell.id ? cellDropTarget.position : null
                    }
                    onStartRename={() => startInlineRename(cell.id)}
                    onCancelRename={cancelInlineRename}
                    onCommitRename={commitInlineRename}
                    onDeleteCell={requestDeleteCell}
                    onAddCellInGroup={onAddCellInGroup}
                    onAddGroup={onAddGroup}
                    onIsolateConcept={onIsolateConcept}
                    onManagePermissions={onManagePermissions}
                    isOntologyOwner={isOntologyOwner}
                  />
                ))}
            </TreeFolder>
          );
        })}
        {ungroupedCells.map((cell) => (
          <TreeFile
            key={cell.id}
            cell={cell}
            isSelected={cell.id === selectedCellId}
            isNested={false}
            canDrag={canEditOntologies}
            canEditOntologies={canEditOntologies}
            isEditing={editingCellId === cell.id}
            onSelect={() => onSelectCell(cell.id)}
            onDragStart={(e) => handleDragStartCell(e, cell)}
            onDragEnd={handleDragEndCell}
            onDragOver={(e) => handleDragOverCell(e, cell)}
            onDragLeave={(e) => handleDragLeaveCell(e, cell.id)}
            onDrop={(e) => handleDropOnCell(e, cell)}
            dropPosition={cellDropTarget?.cellId === cell.id ? cellDropTarget.position : null}
            onStartRename={() => startInlineRename(cell.id)}
            onCancelRename={cancelInlineRename}
            onCommitRename={commitInlineRename}
            onDeleteCell={requestDeleteCell}
            onAddCellInGroup={onAddCellInGroup}
            onAddGroup={onAddGroup}
            onIsolateConcept={onIsolateConcept}
            onManagePermissions={onManagePermissions}
            isOntologyOwner={isOntologyOwner}
          />
        ))}
        {isEmpty && (
          <div className="px-3 py-2 text-xs text-muted-foreground">
            {hasActiveSearch ? "No cells match this filter" : "No concepts yet"}
          </div>
        )}
      </div>
      <DeleteCellDialog
        cell={cellPendingDelete}
        onConfirm={confirmDelete}
        onCancel={cancelDelete}
      />
    </div>
  );
};

export default ExplorerTree;
