import { useEffect, useRef, useState } from "react";
import { useMachineStatusContext } from "@/features/compute/context/MachineStatusContext";
import type { Machine, UserMachine } from "@/features/compute/utils";
import type { ComputeRequirements } from "@/features/dashboards/dashboardConfigRegistry";
import { useToast } from "@/shared/hooks/ui/use-toast";

export type AutoStartPhase = "checking" | "starting" | "ready" | "error";

export interface AutoStartState {
  phase: AutoStartPhase;
  statusMessage: string;
  machineName?: string;
  liveMessage?: string;
}

type MachineAction =
  | { kind: "start"; userMachineId: string; machineId: string; machineName: string }
  | { kind: "provision"; machineId: string; machineName: string };

interface SelectResult {
  action?: MachineAction;
  largestAvailable?: { name: string; cores: number; memoryGb: number };
}

// Score a machine by how closely it matches the requirements.
// Lower = better fit. Uses sum of per-dimension excess ratios so that a machine with
// 3.5x the required memory (but exact cores) ranks worse than one with 1.33x cores
// and exact memory, even though the former has fewer cores in absolute terms.
function fitScore(cores: number, memGb: number, minCores: number, minMemGb: number): number {
  return cores / Math.max(minCores, 1) + memGb / Math.max(minMemGb, 1);
}

// Plain size comparator used only for the "largest available" error report.
const byLargest = (
  a: { cores: number; memory_gb: number },
  b: { cores: number; memory_gb: number },
) => b.cores - a.cores || b.memory_gb - a.memory_gb;

function selectBestMachine(
  enabled: UserMachine[],
  disabled: UserMachine[],
  catalog: Machine[],
  req: ComputeRequirements,
): SelectResult {
  const { minCores = 0, minMemoryGb = 0 } = req;
  const fits = (cores: number, mem: number) => cores >= minCores && mem >= minMemoryGb;
  const byFit = (
    a: { cores: number; memory_gb: number },
    b: { cores: number; memory_gb: number },
  ) =>
    fitScore(a.cores, a.memory_gb, minCores, minMemoryGb) -
    fitScore(b.cores, b.memory_gb, minCores, minMemoryGb);

  // Priority 1: already-enabled machines
  const enabledMatch = enabled
    .filter((um) => um.status === "Enabled" && um.for_compute && um.machines)
    .filter((um) => fits(um.machines!.cores, um.machines!.memory_gb))
    .sort((a, b) => byFit(a.machines!, b.machines!))[0];
  if (enabledMatch?.machines) {
    return {
      action: {
        kind: "start",
        userMachineId: enabledMatch.id,
        machineId: enabledMatch.machines.id,
        machineName: enabledMatch.machines.name,
      },
    };
  }

  // Priority 2: previously-used disabled machines
  const disabledMatch = disabled
    .filter((um) => um.machines)
    .filter((um) => fits(um.machines!.cores, um.machines!.memory_gb))
    .sort((a, b) => byFit(a.machines!, b.machines!))[0];
  if (disabledMatch?.machines) {
    return {
      action: {
        kind: "provision",
        machineId: disabledMatch.machines.id,
        machineName: disabledMatch.machines.name,
      },
    };
  }

  // Priority 3: catalog machines not yet added by this user
  const usedMachineIds = new Set([...enabled, ...disabled].map((um) => um.machine_id));
  const catalogMatch = catalog
    .filter((m) => !usedMachineIds.has(m.id))
    .filter((m) => fits(m.cores, m.memory_gb))
    .sort(byFit)[0];
  if (catalogMatch) {
    return {
      action: { kind: "provision", machineId: catalogMatch.id, machineName: catalogMatch.name },
    };
  }

  // Nothing meets requirements — report the largest option across all pools for the error message
  const allSpecs = [
    ...enabled
      .filter((um) => um.machines)
      .map((um) => ({
        name: um.machines!.name,
        cores: um.machines!.cores,
        memory_gb: um.machines!.memory_gb,
      })),
    ...disabled
      .filter((um) => um.machines)
      .map((um) => ({
        name: um.machines!.name,
        cores: um.machines!.cores,
        memory_gb: um.machines!.memory_gb,
      })),
    ...catalog
      .filter((m) => !usedMachineIds.has(m.id))
      .map((m) => ({ name: m.name, cores: m.cores, memory_gb: m.memory_gb })),
  ];
  const largest = [...allSpecs].sort(byLargest)[0];
  return largest
    ? {
        largestAvailable: { name: largest.name, cores: largest.cores, memoryGb: largest.memory_gb },
      }
    : {};
}

export function useAutoStartCompute(requirements: ComputeRequirements | undefined): AutoStartState {
  const { toast } = useToast();
  const {
    hasRunningMachine,
    userMachines,
    disabledUserMachines,
    catalogMachines,
    loadingMachines,
    hasMachinesLoaded,
    availabilityResults,
    startMachine,
    addAndStartMachine,
  } = useMachineStatusContext();

  const [state, setState] = useState<AutoStartState>({
    phase: requirements ? "checking" : "ready",
    statusMessage: requirements ? "Checking compute availability…" : "",
  });

  const startedMachineIdRef = useRef<string | null>(null);
  const didTriggerStartRef = useRef(false);
  // Once we've reached "ready", lock the phase — background refetches (e.g. tab focus
  // refresh) must not flip loadingMachines true→false and downgrade us back to "checking",
  // which would unmount the dashboard and lose all its state.
  const hasReachedReadyRef = useRef(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startMachineRef = useRef(startMachine);
  const addAndStartMachineRef = useRef(addAndStartMachine);
  startMachineRef.current = startMachine;
  addAndStartMachineRef.current = addAndStartMachine;

  // Decide whether to auto-start a machine
  useEffect(() => {
    if (!requirements) return;
    if (didTriggerStartRef.current) return;
    if (hasReachedReadyRef.current) return;

    if (!hasMachinesLoaded || loadingMachines) {
      setState({ phase: "checking", statusMessage: "Checking compute availability…" });
      return;
    }

    if (hasRunningMachine) {
      hasReachedReadyRef.current = true;
      setState({ phase: "ready", statusMessage: "" });
      return;
    }

    const { action, largestAvailable } = selectBestMachine(
      userMachines,
      disabledUserMachines,
      catalogMachines,
      requirements,
    );

    if (!action) {
      const { minCores = 0, minMemoryGb = 0 } = requirements;
      const detail = largestAvailable
        ? ` Your largest available machine is ${largestAvailable.name} (${largestAvailable.cores} cores, ${largestAvailable.memoryGb} GB).`
        : "";
      setState({
        phase: "error",
        statusMessage:
          `This app requires at least ${minCores} cores and ${minMemoryGb} GB of memory.${detail} ` +
          `Please contact your administrator to provision a suitable machine.`,
      });
      return;
    }

    didTriggerStartRef.current = true;
    startedMachineIdRef.current = action.machineId;

    timeoutRef.current = setTimeout(
      () => {
        setState({
          phase: "error",
          statusMessage:
            "Compute machine is taking too long to start. Please try again or contact your administrator.",
        });
      },
      10 * 60 * 1000,
    );

    setState({
      phase: "starting",
      statusMessage: `Starting compute machine "${action.machineName}"…`,
      machineName: action.machineName,
    });

    const onError = (err: unknown) => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      const raw = err instanceof Error ? err.message : "Unknown error";
      const statusMessage =
        action.kind === "provision"
          ? `Could not provision machine "${action.machineName}". Please add it manually from the Compute page and try again.`
          : `Could not start machine "${action.machineName}". Please try again or contact your administrator.`;
      console.error("[useAutoStartCompute]", raw);
      toast({
        title: "Failed to start compute",
        description: raw,
        variant: "destructive",
      });
      setState({ phase: "error", statusMessage });
    };

    if (action.kind === "start") {
      startMachineRef.current(action.userMachineId, action.machineId).catch(onError);
    } else {
      addAndStartMachineRef.current(action.machineId, action.machineName).catch(onError);
    }
  }, [
    requirements,
    hasMachinesLoaded,
    loadingMachines,
    hasRunningMachine,
    userMachines,
    disabledUserMachines,
    catalogMachines,
  ]);

  // Watch for start completion or failure via WebSocket-driven availability results
  useEffect(() => {
    const machineId = startedMachineIdRef.current;
    if (!machineId) return;

    const machineStatus = availabilityResults[machineId]?.machine_status;
    if (machineStatus === "started") {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      hasReachedReadyRef.current = true;
      setState({ phase: "ready", statusMessage: "" });
    } else if (machineStatus === "crashed") {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      setState({
        phase: "error",
        statusMessage: "The compute machine failed to start. Please contact your administrator.",
      });
    }
  }, [availabilityResults]);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const liveMessage =
    startedMachineIdRef.current && state.phase === "starting"
      ? availabilityResults[startedMachineIdRef.current]?.message
      : undefined;

  return { ...state, liveMessage };
}
