import { useCallback, useEffect, useRef, useState } from "react";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { MachineClient } from "@/features/compute/api/MachineClient";
import { useRequestMachine } from "@/features/compute/hooks/useRequestMachine";
import type { Machine, UserMachine } from "@/features/compute/utils";

export const useComputeMachines = () => {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [userMachines, setUserMachines] = useState<UserMachine[]>([]);
  const [disabledUserMachines, setDisabledUserMachines] = useState<UserMachine[]>([]);
  const [loadingMachines, setLoadingMachines] = useState(false);
  const [machinesError, setMachinesError] = useState<string | null>(null);
  const [loadCount, setLoadCount] = useState(0);

  const { user } = useAuth();
  const { requestMachine, isRequesting } = useRequestMachine();
  const clientRef = useRef(new MachineClient());

  const fetchAllMachines = useCallback(async () => {
    if (!user?.id) return;

    setLoadingMachines(true);
    setMachinesError(null);

    try {
      const response = await clientRef.current.getMachinesCombined();

      if (response.status === "error") {
        throw new Error(response.message);
      }

      setMachines(response.data?.machines || []);
      setUserMachines(response.data?.user_machines_enabled || []);
      setDisabledUserMachines(response.data?.user_machines_disabled || []);
      // Increment on every successful fetch so useMachineStatus re-runs status checks.
      // This covers both the initial load and subsequent refreshes (SPA navigation,
      // machineStateChanged events, etc.).
      setLoadCount((prev) => prev + 1);
    } catch (error) {
      console.error("Error fetching machines:", error);
      setMachinesError(error instanceof Error ? error.message : "Failed to load machines");
      // Do not clear existing machine data on a failed refresh — keep whatever was loaded before
      // so the UI doesn't suddenly show empty state due to a transient network error.
    } finally {
      setLoadingMachines(false);
    }
  }, [user?.id]);

  const handleMachineRequest = useCallback(
    async (machineId: string, machineName: string) => {
      const result = await requestMachine(machineId, machineName);
      if (result.success) {
        await fetchAllMachines();
      }
      return result;
    },
    [requestMachine, fetchAllMachines],
  );

  // Load all machines on mount and when user changes
  useEffect(() => {
    fetchAllMachines();
  }, [fetchAllMachines]);

  return {
    machines,
    userMachines,
    setUserMachines,
    disabledUserMachines,
    loadingMachines,
    machinesError,
    fetchAllMachines,
    handleMachineRequest,
    isRequesting,
    loadCount,
  };
};
