import { useState } from "react";

import { useCodeAssistantStore } from "@/features/code-assistant/store";

import { useCreateContextEdge, useDeleteContextEdge } from "../../hooks/useContextEdges";
import {
  useCreateContextNote,
  useDeleteContextNote,
  useUpdateContextNote,
} from "../../hooks/useContextNotes";
import type { ContextActivation, ContextEdge, ContextNote, ContextNoteFilter } from "../../types";
import {
  type DocumentGroup,
  deriveTitleFromText,
  isDerivedTitle,
  normalizeFolderPath,
  representativeChunkOf,
} from "../notesModel";
import { executeWikilinkEdgeSync } from "../wikilinks";

interface CreateNoteArgs {
  text: string;
  folderPath: string;
  activation?: ContextActivation;
  /** When provided, `[[wikilinks]]` in the new text create edges on save. */
  linkCandidates?: ContextNote[];
}

export interface UseNoteActionsReturn {
  createNote: (args: CreateNoteArgs) => Promise<ContextNote | null>;
  /** Saves text (+re-derived title), then syncs wikilink-born edges. */
  saveNoteText: (
    note: ContextNote,
    newText: string,
    linkCandidates: ContextNote[],
    existingEdges: ContextEdge[],
  ) => Promise<ContextNote | null>;
  /** Saves a whole document's text onto its first chunk and removes the
   *  others — documents are edited as one piece, like any other note. */
  saveDocumentText: (
    group: DocumentGroup,
    newText: string,
    linkCandidates: ContextNote[],
    existingEdges: ContextEdge[],
  ) => Promise<ContextNote | null>;
  /** Deletes every chunk of a document. */
  deleteDocument: (group: DocumentGroup) => void;
  setActivation: (note: ContextNote, activation: ContextActivation) => Promise<ContextNote | null>;
  moveToFolder: (note: ContextNote, folderPath: string) => void;
  deleteNote: (id: string) => void;
  /** Write-time screening rejection reason from the last create/update, if any. */
  screeningError: string | null;
  clearScreeningError: () => void;
  isMutating: boolean;
}

function toScreeningError(error: unknown): string | null {
  if (!(error instanceof Error)) return null;
  return error.message.toLowerCase().includes("screening") ? error.message : null;
}

/**
 * All note writes from the Notes page go through here so every successful
 * mutation bumps the context-notes revision — the agent then reloads its
 * cached context (including <user_rules>) on the next turn instead of
 * waiting for a new session.
 */
export function useNoteActions(filter: ContextNoteFilter): UseNoteActionsReturn {
  const bumpContextNotesRevision = useCodeAssistantStore((state) => state.bumpContextNotesRevision);
  const createMutation = useCreateContextNote(filter);
  const updateMutation = useUpdateContextNote(filter);
  const deleteMutation = useDeleteContextNote(filter);
  const createEdgeMutation = useCreateContextEdge();
  const deleteEdgeMutation = useDeleteContextEdge();
  const [screeningError, setScreeningError] = useState<string | null>(null);

  const createNote = async (args: CreateNoteArgs): Promise<ContextNote | null> => {
    setScreeningError(null);
    try {
      const note = await createMutation.mutateAsync({
        scope: filter.scope,
        scope_id: filter.scopeId ?? null,
        kind: "fact",
        text: args.text,
        title: deriveTitleFromText(args.text),
        folder_path: normalizeFolderPath(args.folderPath) || null,
        activation: args.activation ?? "retrieved",
      });
      if (args.linkCandidates?.length) {
        await syncWikilinkEdges(note.id, args.text, args.linkCandidates, []);
      }
      bumpContextNotesRevision();
      return note;
    } catch (error) {
      setScreeningError(toScreeningError(error));
      return null;
    }
  };

  const syncWikilinkEdges = async (
    noteId: string,
    newText: string,
    linkCandidates: ContextNote[],
    existingEdges: ContextEdge[],
  ): Promise<void> => {
    // [[concept:name]] resolves within the note's own project vault.
    // Edge failures surface as toasts from the edge hooks; the executor
    // never rejects, so the note save is never failed retroactively.
    await executeWikilinkEdgeSync(noteId, newText, linkCandidates, existingEdges, filter.scopeId, {
      createEdge: (edge) => createEdgeMutation.mutateAsync(edge),
      removeEdge: (edgeId) => deleteEdgeMutation.mutateAsync(edgeId),
    });
  };

  const saveNoteText = async (
    note: ContextNote,
    newText: string,
    linkCandidates: ContextNote[],
    existingEdges: ContextEdge[],
  ): Promise<ContextNote | null> => {
    setScreeningError(null);
    try {
      // Only an auto-derived title is refreshed from the new text; an
      // author-chosen one must survive body edits.
      const updated = await updateMutation.mutateAsync({
        id: note.id,
        body: isDerivedTitle(note)
          ? { text: newText, title: deriveTitleFromText(newText) }
          : { text: newText },
      });
      await syncWikilinkEdges(note.id, newText, linkCandidates, existingEdges);
      bumpContextNotesRevision();
      return updated;
    } catch (error) {
      setScreeningError(toScreeningError(error));
      return null;
    }
  };

  const saveDocumentText = async (
    group: DocumentGroup,
    newText: string,
    linkCandidates: ContextNote[],
    existingEdges: ContextEdge[],
  ): Promise<ContextNote | null> => {
    const representative = representativeChunkOf(group);
    const saved = await saveNoteText(representative, newText, linkCandidates, existingEdges);
    if (!saved) return null;
    // The merged text now lives on the first chunk; drop the rest.
    for (const chunk of group.notes) {
      if (chunk.id !== representative.id) deleteMutation.mutate(chunk.id);
    }
    return saved;
  };

  const deleteDocument = (group: DocumentGroup) => {
    group.notes.forEach((chunk) => {
      deleteMutation.mutate(chunk.id);
    });
    bumpContextNotesRevision();
  };

  const setActivation = async (
    note: ContextNote,
    activation: ContextActivation,
  ): Promise<ContextNote | null> => {
    setScreeningError(null);
    try {
      const updated = await updateMutation.mutateAsync({ id: note.id, body: { activation } });
      bumpContextNotesRevision();
      return updated;
    } catch (error) {
      setScreeningError(toScreeningError(error));
      return null;
    }
  };

  const moveToFolder = (note: ContextNote, folderPath: string) => {
    updateMutation.mutate(
      { id: note.id, body: { folder_path: normalizeFolderPath(folderPath) || null } },
      { onSuccess: bumpContextNotesRevision },
    );
  };

  const deleteNote = (id: string) => {
    deleteMutation.mutate(id, { onSuccess: bumpContextNotesRevision });
  };

  return {
    createNote,
    saveNoteText,
    saveDocumentText,
    deleteDocument,
    setActivation,
    moveToFolder,
    deleteNote,
    screeningError,
    clearScreeningError: () => setScreeningError(null),
    isMutating: createMutation.isPending || updateMutation.isPending || deleteMutation.isPending,
  };
}
