import { FolderPlus, Plus, Search, X } from "lucide-react";
import { useState } from "react";
import { InfoHint } from "@/shared/components/InfoHint";
import { Button } from "@/shared/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import { Input } from "@/shared/components/ui/input";
import { cn } from "@/shared/lib/utils";
import type { ContextNote, ContextShelf } from "../../types";
import { CONTEXT_SHELF_LABELS } from "../../types";
import type { UseNotesPageStateReturn } from "../hooks/useNotesPageState";
import type { DocumentGroup, VaultRef } from "../notesModel";
import { SearchResults } from "./SearchResults";
import { VaultSection } from "./VaultSection";

const SHELF_FILTERS: Array<ContextShelf | null> = [null, "rules", "knowledge", "documents"];

interface NotesSidebarProps {
  pageState: UseNotesPageStateReturn;
  ontologyVaults: VaultRef[];
  onCreateNote: () => void;
  onSelectSearchResult: (note: ContextNote) => void;
}

export function NotesSidebar({
  pageState,
  ontologyVaults,
  onCreateNote,
  onSelectSearchResult,
}: NotesSidebarProps) {
  const [folderDialog, setFolderDialog] = useState({ open: false, name: "" });
  const {
    vault,
    shelf,
    searchQuery,
    selection,
    localFolders,
    vaultFilter,
    selectVault,
    selectNote,
    selectDocument,
    selectCollection,
    setShelf,
    setSearchQuery,
    addLocalFolder,
  } = pageState;

  const isSearching = searchQuery.trim().length > 0;

  const handleSelectNote = (note: ContextNote, noteVault: VaultRef, folderPath: string) =>
    selectNote(note.id, noteVault, folderPath);

  const handleSelectDocument = (document: DocumentGroup, documentVault: VaultRef) =>
    selectDocument(document.documentId, documentVault);

  const handleCreateFolder = () => {
    addLocalFolder(folderDialog.name);
    setFolderDialog({ open: false, name: "" });
  };

  const shelfLabel = (value: ContextShelf | null) => (value ? CONTEXT_SHELF_LABELS[value] : "All");

  return (
    <div className="flex h-full flex-col">
      <div className="shrink-0 space-y-2.5 border-b border-border p-3">
        <div className="relative">
          <Search className="absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder={`Search ${vault.name}…`}
            className="h-9 pl-8 pr-8 text-sm"
          />
          {isSearching && (
            <button
              type="button"
              onClick={() => setSearchQuery("")}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              aria-label="Clear search"
            >
              <X className="h-4 w-4" />
            </button>
          )}
        </div>

        <div className="flex flex-wrap items-center gap-1.5">
          {SHELF_FILTERS.map((value) => (
            <button
              key={value ?? "all"}
              type="button"
              onClick={() => setShelf(value)}
              className={cn(
                "rounded-full border px-2.5 py-0.5 text-xs font-medium transition-colors",
                shelf === value
                  ? "border-primary bg-primary/10 text-primary"
                  : "border-border text-muted-foreground hover:text-foreground",
              )}
            >
              {shelfLabel(value)}
            </button>
          ))}
          <InfoHint label="What the note types mean">
            <p>Every note is one of three types — the colored dot shows which:</p>
            <p>
              <span className="font-medium">Rules</span> (amber) reach the assistant on every single
              request: "always" rules are injected verbatim, "on demand" rules are listed by title
              and fetched when needed.
            </p>
            <p>
              <span className="font-medium">Knowledge</span> (blue) — facts, preferences, and
              auto-detected observations — is retrieved only when relevant to what you ask.
            </p>
            <p>
              <span className="font-medium">Documents</span> (green) are files you imported,
              searched when relevant.
            </p>
          </InfoHint>
        </div>

        <div className="flex gap-1.5">
          <Button type="button" size="sm" onClick={onCreateNote} className="h-8 flex-1 text-sm">
            <Plus className="mr-1.5 h-4 w-4" />
            New note
          </Button>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => setFolderDialog({ open: true, name: "" })}
            className="h-8"
            aria-label="New folder"
          >
            <FolderPlus className="h-4 w-4" />
          </Button>
        </div>
      </div>

      <div className="min-h-0 flex-1 overflow-y-auto p-2">
        {isSearching ? (
          <SearchResults query={searchQuery} filter={vaultFilter} onSelect={onSelectSearchResult} />
        ) : (
          <>
            <VaultSection
              vault={{ scope: "global", scopeId: null, name: "Global" }}
              isActive={vault.scope === "global"}
              shelf={shelf}
              localFolders={localFolders}
              selection={selection}
              defaultExpanded
              onActivate={selectVault}
              onSelectNote={handleSelectNote}
              onSelectDocument={handleSelectDocument}
              onSelectCollection={selectCollection}
            />
            {ontologyVaults.map((ontologyVault) => (
              <VaultSection
                key={ontologyVault.scopeId}
                vault={ontologyVault}
                isActive={vault.scopeId === ontologyVault.scopeId}
                shelf={shelf}
                localFolders={localFolders}
                selection={selection}
                onActivate={selectVault}
                onSelectNote={handleSelectNote}
                onSelectDocument={handleSelectDocument}
                onSelectCollection={selectCollection}
              />
            ))}
          </>
        )}
      </div>

      <Dialog
        open={folderDialog.open}
        onOpenChange={(open) => setFolderDialog((prev) => ({ ...prev, open }))}
      >
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>New folder in {vault.name}</DialogTitle>
          </DialogHeader>
          <Input
            value={folderDialog.name}
            onChange={(e) => setFolderDialog((prev) => ({ ...prev, name: e.target.value }))}
            placeholder="e.g. research/interviews"
            autoFocus
          />
          <DialogFooter>
            <Button
              type="button"
              variant="ghost"
              onClick={() => setFolderDialog({ open: false, name: "" })}
            >
              Cancel
            </Button>
            <Button type="button" onClick={handleCreateFolder} disabled={!folderDialog.name.trim()}>
              Create
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
