export type ParamType = "int" | "float" | "bool" | "str";

export interface ParsedParam {
  name: string;
  defaultValue: string | number | boolean;
  type: ParamType;
}

function parseRawValue(rawValue: string): {
  type: ParamType;
  defaultValue: string | number | boolean;
} {
  if (rawValue === "true" || rawValue === "false") {
    return { type: "bool", defaultValue: rawValue === "true" };
  }
  if (rawValue.startsWith('"')) {
    return { type: "str", defaultValue: rawValue.slice(1, -1) };
  }
  if (rawValue.includes(".")) {
    return { type: "float", defaultValue: parseFloat(rawValue) };
  }
  return { type: "int", defaultValue: parseInt(rawValue, 10) };
}

/**
 * Parses @param("name", value). annotations from a concept's param_annotations string.
 * Supports: int, float, bool (true/false), and str ("quoted") types.
 */
export function parseParamAnnotations(paramAnnotations: string): ParsedParam[] {
  if (!paramAnnotations?.trim()) return [];

  const params: ParsedParam[] = [];
  // Matches: @param("name", true|false|"str"|float|int).
  const regex = /@param\(\s*"([^"]+)"\s*,\s*(true|false|"[^"]*"|-?\d+\.\d+|-?\d+)\s*\)\s*\./g;

  let match;
  while ((match = regex.exec(paramAnnotations)) !== null) {
    const [, name, rawValue] = match;
    const { type, defaultValue } = parseRawValue(rawValue);
    params.push({ name, defaultValue, type });
  }

  return params;
}
