import { AlertCircle } from "lucide-react";
import type React from "react";
import { Alert, AlertDescription } from "@/shared/components/ui/alert";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/shared/components/ui/card";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { LoginActivityList } from "./LoginActivityList";
import { useLoginActivity } from "./useLoginActivity";

export const LoginActivity: React.FC = () => {
  const { sessions, isLoading, error } = useLoginActivity();

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <PrometheuxSpinner size={36} />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="destructive">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>Failed to load login activity: {error.message}</AlertDescription>
      </Alert>
    );
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Recent Sessions</CardTitle>
          <CardDescription>
            Locations and IPs that have accessed your account, sorted by most recent activity.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <LoginActivityList sessions={sessions} />
        </CardContent>
      </Card>
    </div>
  );
};
