import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";
import type { OntologyDocument } from "./types";

interface ApiEnvelope<T> {
  status: "success" | "error";
  data?: T;
  message?: string;
}

interface GetOptions {
  refresh?: boolean;
  /**
   * Ask the backend to also bootstrap the project's ontology graph from its
   * lineage when none exists yet. Idempotent server-side.
   */
  generateOntologySchema?: boolean;
}

export const OntologyDocumentApi = {
  async get(
    ontologyId: string,
    scope: string = "user",
    options: GetOptions = {},
  ): Promise<OntologyDocument> {
    const params = new URLSearchParams({ scope });
    if (options.refresh) params.set("refresh", "true");
    if (options.generateOntologySchema) params.set("generate_ontology_schema", "true");
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/knowledge/ontology/${ontologyId}/text?${params.toString()}`;
    const response: ApiEnvelope<OntologyDocument> = await HttpService.get(url);
    if (response.status === "success" && response.data !== undefined) {
      return response.data;
    }
    throw new Error(response.message ?? "Failed to load ontology document");
  },
};
