import { Loader2 } from "lucide-react";
import { type ComponentType, lazy, Suspense, useMemo, useRef } from "react";
import { ComputeStartingOverlay } from "@/features/compute/components/ComputeStartingOverlay";
import { useAutoStartCompute } from "@/features/compute/hooks/useAutoStartCompute";
import type { AppTabProps } from "@/features/dashboards/dashboardRegistry";
import { setCurrentOntologyId, setCurrentOntologyScope } from "@/features/ontologies/utils";
import { createAppSdk } from "@/shared/app-sdk/createAppSdk";
import { ErrorBoundary } from "@/shared/components/ErrorBoundary";
import { loadRemoteExport } from "./remoteLoader";
import { useRemoteAppConfig } from "./useRemoteAppConfig";

interface RemoteAppHostProps {
  dashboardId: string;
  remoteUrl: string;
  name: string;
  onToggleSidebar?: () => void;
  sidebarVisible?: boolean;
}

interface RemoteAppModule {
  default: ComponentType<AppTabProps>;
}

function CenteredLoader({ message }: { message: string }) {
  return (
    <div className="flex h-full flex-col items-center justify-center gap-3 text-muted-foreground">
      <Loader2 className="h-5 w-5 animate-spin" />
      <span className="text-sm">{message}</span>
    </div>
  );
}

// Renders a federated client app: load its exposed config → seed ontology context +
// auto-start compute → lazily mount its exposed "./App". The two-stage load (config
// before App) mirrors what the build-time registry + AppsDashboardPage did locally.
export function RemoteAppHost({
  dashboardId,
  remoteUrl,
  name,
  onToggleSidebar,
  sidebarVisible,
}: RemoteAppHostProps) {
  const { data: config, isLoading, error } = useRemoteAppConfig(dashboardId, remoteUrl);

  // Seed ontology context synchronously once config arrives, before the lazy App resolves,
  // so the app's useProjectId()/useProjectScope() lazy initialisers see the right values.
  const seededRef = useRef<string | null>(null);
  if (config?.ontologyId && seededRef.current !== dashboardId) {
    seededRef.current = dashboardId;
    setCurrentOntologyId(config.ontologyId);
    setCurrentOntologyScope(config.scope);
  }

  // undefined requirements → phase "ready" immediately (no compute needed).
  const { phase, statusMessage, machineName, liveMessage } = useAutoStartCompute(
    config?.computeRequirements,
  );

  const RemoteApp = useMemo(
    () => lazy(() => loadRemoteExport<RemoteAppModule>(dashboardId, remoteUrl, "App")),
    [dashboardId, remoteUrl],
  );

  // The host-injected SDK the app uses to talk to the backend (seed of @prometheux/app-sdk).
  const sdk = useMemo(() => createAppSdk(config?.scope ?? "user"), [config?.scope]);

  if (error) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-2 p-10 text-center text-muted-foreground">
        <p className="text-sm font-semibold text-foreground">Couldn't load “{name}”</p>
        <p className="max-w-md break-words font-mono text-xs">{error.message}</p>
        <p className="text-xs">Remote: {remoteUrl}</p>
      </div>
    );
  }

  if (isLoading || !config) return <CenteredLoader message={`Loading ${name}…`} />;

  if (phase !== "ready") {
    return (
      <ComputeStartingOverlay
        phase={phase}
        statusMessage={statusMessage}
        machineName={machineName}
        liveMessage={liveMessage}
      />
    );
  }

  return (
    <ErrorBoundary>
      <Suspense fallback={<CenteredLoader message={`Loading ${name}…`} />}>
        <RemoteApp
          onToggleSidebar={onToggleSidebar}
          sidebarVisible={sidebarVisible}
          name={name}
          description={config.description}
          ontologyId={config.ontologyId}
          sdk={sdk}
        />
      </Suspense>
    </ErrorBoundary>
  );
}
