import { Activity, AlignLeft, FileText, Parentheses, Sparkles, Table2 } from "lucide-react";
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { EditorShortcutsHelp } from "@/features/concept-editor/components/EditorShortcutsHelp";
import { useCellCurlSnippet } from "@/features/concept-editor/hooks/useCellCurlSnippet";
import { useCellDragDrop } from "@/features/concept-editor/hooks/useCellDragDrop";
import { useCellRename } from "@/features/concept-editor/hooks/useCellRename";
import { useCellSplitPanes } from "@/features/concept-editor/hooks/useCellSplitPanes";
import { useCellView } from "@/features/concept-editor/hooks/useCellView";
import { useSchemaStore } from "@/features/concept-editor/store";
import type { CellBinds } from "@/features/concept-editor/types";
import { runStatusDotClass } from "@/features/concept-editor/utils/runStatus";
import EngineMonitorPanel from "@/features/engine-monitor/components/EngineMonitorPanel";
import { AccordionContent } from "@/shared/components/ui/accordion";
import { Button } from "@/shared/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";
import { cn } from "@/shared/lib/utils";
import { usePreferencesStore } from "@/shared/store/preferencesStore";
import { getCellTitle, getPredicateNames, isNewCellTitle } from "./cell.utils";
import { CellAccordionShell } from "./components/CellAccordionShell";
import { CellContextTab } from "./components/CellContextTab";
import CellEditor from "./components/CellEditor";
import { CellHeaderRow } from "./components/CellHeaderRow";
import { CellPredicatePicker } from "./components/CellPredicatePicker";
import CellResults from "./components/CellResults";
import CellSettings from "./components/CellSettings";
import { CellSplitBottomTabs, SplitBottomTabButton } from "./components/CellSplitBottomTabs";
import CellToolbar from "./components/CellToolbar";
import { SplitDragHandle } from "./components/SplitDragHandle";
import type { QueryConceptCellProps } from "./types/editorTypes";

const QueryConceptCell: React.FC<QueryConceptCellProps> = ({
  cell,
  index,
  extensions,
  editorTheme,
  onCodeChange,
  onRunCell,
  onDeleteCell,
  onClearResults,
  onRestoreResults,
  onSaveCell,
  onStopCell,
  onIndentCode,
  onOpenAssistant,
  setCells,
  changePage,
  isLoadingPage,
  searchPredicateData,
  clearSearch,
  groupNames,
  onAddCellToGroup,
  onRemoveCellFromGroup,
  onCellTypeChange,
  onRenameConcept,
  defaultView,
  onViewChange,
  splitLayout,
}) => {
  const predicateOptions = useMemo(() => getPredicateNames(cell.code), [cell.code]);

  // Accordion title + "new cell" detection
  const cellTitle = getCellTitle(cell.outputPredicate, index, "Cell");
  const isNewCell = isNewCellTitle(cellTitle, cell.id, "Cell");
  const [open, setOpen] = useState<string | null>(isNewCell ? cell.id : null);
  const isOpen = open === cell.id;
  const [showDataEditor, setShowDataEditor] = useState(false);
  const [showBindEditor, setShowBindEditor] = useState(false);
  const initialView: "context" | "logic" | "engine" | "output" =
    defaultView === "logic" || defaultView === "engine" || defaultView === "output"
      ? defaultView
      : "context";
  const { currentView, setCurrentView } = useCellView<"context" | "logic" | "engine">(
    cell,
    initialView,
  );

  // In split layout, notify the parent on every currentView change so it can
  // persist the bottom panel state. Skip the initial mount fire (we'd be
  // pushing the value the parent just handed us).
  const initialViewSyncRef = useRef(true);
  useEffect(() => {
    if (!onViewChange) return;
    if (initialViewSyncRef.current) {
      initialViewSyncRef.current = false;
      return;
    }
    onViewChange(currentView);
  }, [currentView, onViewChange]);

  const {
    isBottomPanelOpen,
    editorPaneRef,
    bottomPaneRef,
    splitEditorStyle,
    splitBottomFlexStyle,
    editorRatio,
    handleSplitDragStart,
    adjustRatio,
  } = useCellSplitPanes({ splitLayout, currentView, editorView: "logic" });

  const [wordWrap, setWordWrap] = useState(() => usePreferencesStore.getState().wrapCodeByDefault);
  const { dropPosition, handleDragOver, handleDragLeave, handleDrop } = useCellDragDrop(cell.id);

  // A logic cell's name is always backed by a stored concept, so a rename always
  // goes through the rename endpoint — no local-relabel fallback.
  const commitRename = useCallback(
    (name: string) => onRenameConcept?.(cell.id, name),
    [cell.id, onRenameConcept],
  );
  const rename = useCellRename({ currentName: cell.outputPredicate, onCommit: commitRename });

  // Group management helpers
  const currentGroup = cell.group && cell.group !== "group_id" ? cell.group : null;

  // Open accordion if cell.autoOpen is true, then clear the flag
  React.useEffect(() => {
    if (cell.autoOpen) {
      setOpen(cell.id);
      setCells((prevCells) =>
        prevCells.map((c) => (c.id === cell.id ? { ...c, autoOpen: false } : c)),
      );
    }
  }, [cell.autoOpen, cell.id, setCells]);

  // Note: conceptsUpdated event handler moved to parent (ConceptList) to prevent
  // cascading re-renders across all cells. The parent now handles concept updates
  // in a single batched setState operation. CellDescriptionSection (inside the
  // Context tab) listens to that event for its @-mention suggestions.

  // Keep the default output predicate in sync with the code.
  //
  // We default to the LAST parsed predicate (typically the final output head of
  // the program). As long as the user has NOT explicitly picked a predicate, the
  // default keeps tracking the last parsed one — so while writing a program
  // function by function, the default follows the most recently added head.
  //
  // Once the user picks a predicate from the dropdown (outputPredicateUserSet),
  // their choice is preserved and we only step in if it disappears from the code.
  React.useEffect(() => {
    if (predicateOptions.length === 0) return;
    const lastPredicate = predicateOptions[predicateOptions.length - 1];

    // User-chosen predicate: keep it, unless it no longer exists in the code.
    // When it disappears, the explicit choice is gone — fall back to the last
    // predicate AND unlock, so the default resumes tracking the latest head as
    // the user keeps writing (until they pick a new one).
    if (cell.outputPredicateUserSet) {
      if (cell.outputPredicate && !predicateOptions.includes(cell.outputPredicate)) {
        setCells((prevCells) =>
          prevCells.map((c) =>
            c.id === cell.id
              ? {
                  ...c,
                  outputPredicate: lastPredicate,
                  outputPredicateUserSet: false,
                  isModified: true,
                }
              : c,
          ),
        );
      }
      return;
    }

    // No explicit choice yet: keep the default tracking the last parsed predicate.
    if (cell.outputPredicate !== lastPredicate) {
      setCells((prevCells) =>
        prevCells.map((c) =>
          c.id === cell.id ? { ...c, outputPredicate: lastPredicate, isModified: true } : c,
        ),
      );
    }
  }, [
    cell.code,
    cell.outputPredicate,
    cell.outputPredicateUserSet,
    predicateOptions,
    setCells,
    cell.id,
  ]);

  // Handler for predicate change: update state and mark as modified (optimized)
  const handlePredicateChange = useCallback(
    (value: string) => {
      // Update the cell with the selected output predicate and lock it in as a
      // user choice so the auto-tracking effect stops following the last head.
      setCells((prevCells) =>
        prevCells.map((c) =>
          c.id === cellIdRef.current
            ? { ...c, outputPredicate: value, outputPredicateUserSet: true, isModified: true }
            : c,
        ),
      );
    },
    [setCells],
  );

  // Handler for save: get fresh code and pass it to onSaveCell
  // Signature matches CellToolbarProps/CellEditorProps but ignores freshCode param
  // (we always get fresh code from CodeMirror instead)
  const handleSaveCell = useCallback(
    async (cellId: string, _unusedFreshCode?: string, showToast?: boolean) => {
      if (onSaveCell) {
        let freshCode = cell.code;
        if (getCurrentCodeRef.current) {
          freshCode = getCurrentCodeRef.current();
          if (freshCode !== cell.code) {
            onCodeChange(freshCode, cellId);
          }
        }
        return onSaveCell(cellId, freshCode, showToast);
      }
    },
    [onSaveCell, cell.code, cell.outputPredicate, onCodeChange],
  );

  // Refs for stable callback dependencies
  const cellIdRef = useRef(cell.id);
  cellIdRef.current = cell.id;

  const handledescriptionChange = useCallback(
    (value: string) => {
      setCells((prevCells) => {
        const cellIndex = prevCells.findIndex((c) => c.id === cellIdRef.current);
        if (cellIndex === -1) return prevCells;

        const updatedCells = [...prevCells];
        updatedCells[cellIndex] = {
          ...prevCells[cellIndex],
          description: value,
          isModified: true,
          needsSave: true, // Mark cell as needing save when description changes
        };

        return updatedCells;
      });
    },
    [setCells],
  );

  // Handler for word wrap toggle
  const handleWordWrapToggle = useCallback((enabled: boolean) => {
    setWordWrap(enabled);
  }, []);

  // Handler to toggle accordion (minimize/expand cell)
  const handleToggleAccordion = useCallback(() => {
    setOpen((prevOpen) => (prevOpen === cell.id ? "" : cell.id));
  }, [cell.id]);

  // Keyboard activation for the (non-button) header toggle. The header can't be a
  // real <button> because it contains interactive controls (Selects, dropdowns),
  // and a <button> inside a <button> is invalid HTML that breaks click handling.
  // Handler for Accordion open/close. The Accordion is not `collapsible`, so a
  // header/toolbar click can't close the open cell (the dock cell stays open).
  const handleAccordionChange = (value: string) => {
    setOpen(value);
  };

  // Only open if closed, never close
  const ensureAccordionOpen = () => {
    if (!isOpen) setOpen(cell.id);
  };

  // Store ref to get current code directly from CodeMirror (solves stale state issue)
  const getCurrentCodeRef = useRef<(() => string) | null>(null);

  const handleEditorReady = useCallback((getCode: () => string) => {
    getCurrentCodeRef.current = getCode;
  }, []);

  const handleRunCell = async (cellId: string, forceRerun?: boolean) => {
    ensureAccordionOpen();

    let freshCode = cell.code;
    if (getCurrentCodeRef.current) {
      freshCode = getCurrentCodeRef.current();
      if (freshCode !== cell.code) {
        onCodeChange(freshCode, cellId);
      }
    }

    if (onRunCell) {
      onRunCell(cellId, freshCode, forceRerun);
    }
  };

  const handleToggleSettings = () => {
    ensureAccordionOpen();
    setShowDataEditor((prev) => {
      if (!prev) setShowBindEditor(false);
      return !prev;
    });
  };

  const handleToggleBindEditor = () => {
    ensureAccordionOpen();
    setShowBindEditor((prev) => {
      if (!prev) setShowDataEditor(false);
      return !prev;
    });
  };

  const handleBindsChange = useCallback(
    (newBinds: CellBinds) => {
      setCells((prevCells) => {
        const idx = prevCells.findIndex((c) => c.id === cellIdRef.current);
        if (idx === -1) return prevCells;
        const updated = [...prevCells];
        updated[idx] = { ...updated[idx], binds: newBinds, isModified: true };
        return updated;
      });
    },
    [setCells],
  );

  const setBoundPredicates = useSchemaStore((state) => state.setBoundPredicates);
  const handleBoundPredicatesChange = useCallback(
    (sigs: { label: string; apply: string; info: string }[]) => {
      setBoundPredicates(sigs);
    },
    [setBoundPredicates],
  );

  const buildCurlSnippet = useCellCurlSnippet(cell.outputPredicate);

  // Memoize the cell component to prevent unnecessary re-renders
  // Only depend on actual cell data and essential local state
  const memoizedCell = useMemo(
    () => (
      <CellAccordionShell
        cellId={cell.id}
        cellBackendId={cell.cellBackendId}
        open={open}
        onOpenChange={handleAccordionChange}
        dropPosition={dropPosition}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        <CellHeaderRow
          cell={cell}
          isOpen={isOpen}
          defaultConceptType="logic"
          onToggle={handleToggleAccordion}
          onCellTypeChange={onCellTypeChange}
          buildCurlSnippet={buildCurlSnippet}
          currentGroup={currentGroup}
          groupNames={groupNames}
          onAddCellToGroup={onAddCellToGroup}
          onRemoveCellFromGroup={onRemoveCellFromGroup}
          identity={
            <CellPredicatePicker
              outputPredicate={cell.outputPredicate}
              predicateOptions={predicateOptions}
              onPredicateChange={handlePredicateChange}
              canRename={!!cell.cellBackendId && !!onRenameConcept}
              isRenaming={rename.isRenaming}
              renameValue={rename.renameValue}
              inputRef={rename.inputRef}
              onRenameValueChange={rename.setRenameValue}
              onConfirm={rename.confirm}
              onCancel={rename.cancel}
              onStart={rename.start}
            />
          }
          toolbar={
            <CellToolbar
              cellId={cell.id}
              code={cell.code}
              isRunning={cell.isRunning}
              isCellSaving={cell.isSaving}
              hasResult={!!cell.result || !!cell.error}
              hasPersistedResults={cell.hasPersistedResults || false}
              isModified={cell.isModified}
              onRunCell={handleRunCell}
              onStopCell={onStopCell}
              onDeleteCell={onDeleteCell}
              onClearResults={onClearResults}
              onRestoreResults={onRestoreResults}
              onSaveCell={handleSaveCell}
              onIndentCode={onIndentCode}
              onToggleSettings={handleToggleSettings}
              isSettingsActive={showDataEditor}
              onToggleBindEditor={handleToggleBindEditor}
              isBindEditorActive={showBindEditor}
              readOnly={cell.readOnly}
            />
          }
        />
        <AccordionContent style={{ overflow: "visible", minWidth: 0 }}>
          <div className="flex flex-col" style={{ minWidth: 0, overflow: "visible" }}>
            {/* Main Cell Editor and Settings */}
            <CellSettings
              cellId={cell.id}
              showDataEditor={showDataEditor || showBindEditor}
              onToggleDataEditor={handleToggleSettings}
              isRunning={cell.isRunning}
              extensions={extensions}
              editorTheme={editorTheme}
              onCodeChange={onCodeChange}
              onRunCell={onRunCell}
              onSaveCell={onSaveCell}
              code={cell.code}
              outputPredicate={cell.outputPredicate}
              showBindEditor={showBindEditor}
              binds={cell.binds || { input: [], output: [] }}
              onBindsChange={handleBindsChange}
              onBoundPredicatesChange={handleBoundPredicatesChange}
              conceptName={cell.cellBackendId}
              fillHeight={splitLayout}
            />

            {/* View Switcher (top). In splitLayout the editor sits below this
                    bar and the description/engine/output tabs move to a panel below
                    the editor — so we hide them here and keep only the logic label
                    plus the action buttons (Indent/Wrap/AskAI). */}
            <div className={cn("border-t border-border/50 bg-muted/30", splitLayout && "order-1")}>
              <div className="flex items-center justify-between px-4 py-2">
                <div className="flex items-center gap-1">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setCurrentView("logic")}
                    className={`h-7 px-2 text-xs ${
                      currentView === "logic" || splitLayout
                        ? "bg-muted text-foreground"
                        : "hover:bg-muted/50"
                    }`}
                  >
                    <Parentheses className="h-3 w-3 mr-1" />
                    logic
                  </Button>
                  {!splitLayout && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setCurrentView("context")}
                      className={`h-7 px-2 text-xs ${
                        currentView === "context" ? "bg-muted text-foreground" : "hover:bg-muted/50"
                      }`}
                    >
                      <FileText className="h-3 w-3 mr-1" />
                      context
                    </Button>
                  )}
                  {!splitLayout && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setCurrentView("engine")}
                      className={`h-7 px-2 text-xs ${
                        currentView === "engine" ? "bg-muted text-foreground" : "hover:bg-muted/50"
                      }`}
                    >
                      <Activity className="h-3 w-3 mr-1" />
                      engine
                      {cell.isRunning ? (
                        <span className="ml-1 inline-block h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
                      ) : null}
                    </Button>
                  )}
                  {!splitLayout && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setCurrentView("output")}
                      className={`h-7 px-2 text-xs ${
                        currentView === "output" ? "bg-muted text-foreground" : "hover:bg-muted/50"
                      }`}
                    >
                      <Table2 className="h-3 w-3 mr-1" />
                      output
                      {(cell.result || cell.error || cell.isRunning) && (
                        <span
                          className={`ml-1 inline-block h-1.5 w-1.5 rounded-full ${runStatusDotClass(cell)}`}
                        />
                      )}
                    </Button>
                  )}
                </div>

                {/* Logic-mode action buttons. Always visible in splitLayout
                        since the editor is always shown. */}
                {(currentView === "logic" || splitLayout) && (
                  <div className="flex items-center gap-1">
                    <EditorShortcutsHelp />
                    {/* Indent Button */}
                    {onIndentCode && (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => onIndentCode(cell.id)}
                            disabled={!cell.code || cell.code.trim() === ""}
                            className="h-7 px-2 text-xs"
                          >
                            <AlignLeft className="h-3 w-3 mr-1" />
                            Indent
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>
                          Auto indent code{" "}
                          <span className="ml-2 text-xs text-muted-foreground">⌘I / Ctrl+I</span>
                        </TooltipContent>
                      </Tooltip>
                    )}
                    {/* Word Wrap Button */}
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleWordWrapToggle(!wordWrap)}
                          className={`h-7 px-2 text-xs ${wordWrap ? "bg-muted text-foreground" : ""}`}
                        >
                          <FileText className="h-3 w-3 mr-1" />
                          Wrap
                        </Button>
                      </TooltipTrigger>
                      <TooltipContent>Toggle word wrap</TooltipContent>
                    </Tooltip>
                    {/* Ask AI Button — only for saved concepts */}
                    {onOpenAssistant && cell.cellBackendId && (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => onOpenAssistant(cell.id)}
                            className="h-7 px-2 text-xs"
                          >
                            <Sparkles className="h-3 w-3 mr-1" />
                            Ask AI
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>Open AI assistant for this concept</TooltipContent>
                      </Tooltip>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* Content based on current view. In splitLayout these sit at
                    order-5 (below the resize handle at order-3 and the bottom
                    tab bar at order-4). The flex value comes from useCellSplitPanes
                    and is the complement of the editor's flex value, so editor
                    + bottom share the available height in the saved ratio. */}
            {currentView === "context" && (
              <div
                ref={isBottomPanelOpen ? bottomPaneRef : undefined}
                className={cn(
                  "cell-view-pane flex flex-col px-4",
                  splitLayout && "order-5 min-h-0 overflow-auto",
                )}
                style={{
                  position: "relative",
                  zIndex: 1,
                  ...splitBottomFlexStyle,
                }}
              >
                <CellContextTab
                  description={cell.description || ""}
                  onDescriptionChange={handledescriptionChange}
                  onSaveShortcut={() => handleSaveCell(cell.id)}
                  cellBackendId={cell.cellBackendId}
                  conceptName={cell.outputPredicate || ""}
                />
              </div>
            )}
            {currentView === "engine" && (
              <div
                ref={isBottomPanelOpen ? bottomPaneRef : undefined}
                className={cn(
                  "cell-view-pane w-full px-4 py-3",
                  splitLayout && "order-5 min-h-0 overflow-auto",
                )}
                style={splitBottomFlexStyle}
              >
                <EngineMonitorPanel isRunning={cell.isRunning} />
              </div>
            )}
            {currentView === "output" && (
              <div
                ref={isBottomPanelOpen ? bottomPaneRef : undefined}
                className={cn(
                  "cell-view-pane w-full overflow-x-auto",
                  splitLayout && "order-5 min-h-0 overflow-auto",
                )}
                style={{ maxWidth: "100%", ...splitBottomFlexStyle }}
              >
                <CellResults
                  cell={cell}
                  setCells={setCells}
                  changePage={changePage}
                  isLoadingPage={isLoadingPage}
                  searchPredicateData={searchPredicateData}
                  clearSearch={clearSearch}
                />
              </div>
            )}
            <div
              ref={isBottomPanelOpen ? editorPaneRef : undefined}
              className={cn(
                "cell-editor-pane border-t border-border/50",
                splitLayout && (isBottomPanelOpen ? "order-2 min-h-0" : "order-2 flex-1 min-h-0"),
              )}
              style={splitEditorStyle}
            >
              <CellEditor
                code={cell.code}
                cellId={cell.id}
                isRunning={cell.isRunning}
                extensions={extensions}
                editorTheme={editorTheme}
                onCodeChange={onCodeChange}
                onRunCell={handleRunCell}
                onSaveCell={handleSaveCell}
                onIndentCode={onIndentCode}
                placeholder="Type logic here..."
                wordWrap={wordWrap}
                onWordWrapToggle={handleWordWrapToggle}
                onToggleMinimize={handleToggleAccordion}
                onEditorReady={handleEditorReady}
                fillHeight={splitLayout}
                readOnly={cell.isSaving}
              />
            </div>
            {/* Vertical resize handle between editor and bottom panel.
                    Only rendered when the bottom panel is open; collapsing
                    the panel hides it (re-opening restores the saved ratio). */}
            {isBottomPanelOpen && (
              <SplitDragHandle
                className="order-3"
                onMouseDown={handleSplitDragStart}
                onAdjust={adjustRatio}
                editorPercent={editorRatio * 100}
              />
            )}
            {splitLayout && (
              <CellSplitBottomTabs<"logic" | "engine">
                cell={cell}
                currentView={currentView}
                editorView="logic"
                onSelectView={setCurrentView}
                extraTabs={
                  <SplitBottomTabButton
                    isOpen={currentView === "engine"}
                    icon={<Activity className="h-3 w-3 mr-1" />}
                    label="engine"
                    indicator={
                      cell.isRunning ? (
                        <span className="ml-1 inline-block h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
                      ) : null
                    }
                    onClick={() => setCurrentView(currentView === "engine" ? "logic" : "engine")}
                  />
                }
              />
            )}
          </div>
        </AccordionContent>
      </CellAccordionShell>
    ),
    [
      // Core cell data - use individual properties to avoid re-render on unrelated changes
      cell.id,
      cell.code,
      cell.outputPredicate,
      cell.description,
      cell.isRunning,
      cell.result,
      cell.error,
      cell.hasPersistedResults,
      cell.isModified,
      cell.cellBackendId,
      predicateOptions,
      // Local UI state
      open,
      isOpen,
      showDataEditor,
      currentView,
      splitLayout,
      wordWrap,
      dropPosition,
      rename,
      currentGroup,
      groupNames,
      // Metadata
      index,
      // Stable callbacks - these should rarely change now
      handlePredicateChange,
      handleSaveCell,
      handleToggleSettings,
      handledescriptionChange,
      handleWordWrapToggle,
      handleToggleAccordion,
      handleBoundPredicatesChange,
      handleRunCell,
      handleEditorReady,
      handleDragOver,
      handleDragLeave,
      handleDrop,
      buildCurlSnippet,
      // Config (stable)
      extensions,
      editorTheme,
      // Parent handlers (should be memoized by parent)
      onCodeChange,
      onDeleteCell,
      onClearResults,
      onRestoreResults,
      onIndentCode,
      onCellTypeChange,
      onRenameConcept,
      onAddCellToGroup,
      onRemoveCellFromGroup,
      changePage,
      isLoadingPage,
    ],
  );

  return memoizedCell;
};

export default React.memo(QueryConceptCell);
