import { FolderPlus, Link, RefreshCw, Trash2, Upload } from "lucide-react";
import { useCallback, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { DataClient } from "@/features/data-sources/api/DataClient";
import type { FileEntry } from "@/features/data-sources/api/fileSystemApi";
import { FileBreadcrumb } from "@/features/data-sources/components/file-browser/FileBreadcrumb";
import { FileList } from "@/features/data-sources/components/file-browser/FileList";
import { SheetPickerDialog } from "@/features/data-sources/components/SheetPickerDialog";
import { isConnectable, useFileBrowser } from "@/features/data-sources/hooks/useFileBrowser";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

const EXCEL_EXTENSIONS = new Set(["xlsx", "xls"]);

interface FileBrowserTabProps {
  onSourcesChanged?: () => void;
}

interface SheetPickerState {
  open: boolean;
  sheets: string[];
  fileName: string;
  pendingConfig: Record<string, unknown> | null;
}

const INITIAL_SHEET_PICKER: SheetPickerState = {
  open: false,
  sheets: [],
  fileName: "",
  pendingConfig: null,
};

export function FileBrowserTab({ onSourcesChanged }: FileBrowserTabProps) {
  const browser = useFileBrowser();
  const [connectingNames, setConnectingNames] = useState<Set<string>>(new Set());
  const [mkdirOpen, setMkdirOpen] = useState(false);
  const [folderName, setFolderName] = useState("");
  const [sheetPicker, setSheetPicker] = useState<SheetPickerState>(INITIAL_SHEET_PICKER);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dataClient = useMemo(() => new DataClient(), []);

  const isConnecting = connectingNames.size > 0;

  const markConnecting = (name: string) => setConnectingNames((prev) => new Set(prev).add(name));

  const unmarkConnecting = (name: string) =>
    setConnectingNames((prev) => {
      const next = new Set(prev);
      next.delete(name);
      return next;
    });

  const connectWithConfig = useCallback(
    async (config: Record<string, unknown>, fileName: string) => {
      const result = await dataClient.connectDataSource(config);
      if (result?.status === "success" || result?.data?.connectionStatus) {
        toast.success(`"${fileName}" connected as data source`);
        onSourcesChanged?.();
      } else {
        toast.error(result?.message ?? "Connection failed");
      }
    },
    [dataClient, onSourcesChanged],
  );

  const handleConnect = useCallback(
    async (entry: FileEntry) => {
      markConnecting(entry.name);
      try {
        const config = browser.buildConnectConfig(entry);
        const ext = entry.extension ?? "";

        if (!EXCEL_EXTENSIONS.has(ext)) {
          await connectWithConfig(config, entry.name);
          return;
        }

        const sheets = await dataClient.listSheets(config);
        if (sheets.length <= 1) {
          await connectWithConfig(config, entry.name);
          return;
        }

        setSheetPicker({
          open: true,
          sheets,
          fileName: entry.name,
          pendingConfig: config,
        });
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Connection failed");
      } finally {
        unmarkConnecting(entry.name);
      }
    },
    [browser, dataClient, connectWithConfig, markConnecting, unmarkConnecting],
  );

  const handleSheetSelect = useCallback(
    async (sheetName: string) => {
      if (!sheetPicker.pendingConfig) return;
      setSheetPicker(INITIAL_SHEET_PICKER);

      const fileName = sheetPicker.fileName;
      markConnecting(fileName);
      try {
        const config = {
          ...sheetPicker.pendingConfig,
          options: {
            ...(sheetPicker.pendingConfig.options as Record<string, unknown> | undefined),
            dataAddress: `'${sheetName}'!A1`,
          },
        };
        await connectWithConfig(config, fileName);
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Connection failed");
      } finally {
        unmarkConnecting(fileName);
      }
    },
    [sheetPicker, connectWithConfig, markConnecting, unmarkConnecting],
  );

  const handleSheetCancel = useCallback(() => setSheetPicker(INITIAL_SHEET_PICKER), []);

  const handleBulkConnect = useCallback(async () => {
    const selected = browser.entries.filter(
      (e) => browser.selectedFiles.has(e.name) && isConnectable(e),
    );
    if (selected.length === 0) {
      toast.info("No connectable files selected");
      return;
    }
    for (const entry of selected) {
      markConnecting(entry.name);
    }
    let successCount = 0;
    for (const entry of selected) {
      try {
        const config = browser.buildConnectConfig(entry);
        const ext = entry.extension ?? "";

        if (EXCEL_EXTENSIONS.has(ext)) {
          const sheets = await dataClient.listSheets(config);
          if (sheets.length > 1) {
            toast.info(`"${entry.name}" has multiple sheets — connect it individually`);
            unmarkConnecting(entry.name);
            continue;
          }
        }

        const result = await dataClient.connectDataSource(config);
        if (result?.status === "success" || result?.data?.connectionStatus) {
          successCount++;
        }
      } catch {
        toast.error(`Failed to connect "${entry.name}"`);
      } finally {
        unmarkConnecting(entry.name);
      }
    }
    if (successCount > 0) {
      toast.success(`Connected ${successCount} file(s) as data sources`);
      onSourcesChanged?.();
    }
  }, [browser, dataClient, onSourcesChanged, markConnecting, unmarkConnecting]);

  const handleDeleteSelected = useCallback(() => {
    const names = [...browser.selectedFiles];
    if (names.length === 0) return;
    browser.deleteSelected(names, true);
  }, [browser]);

  const handleUploadClick = () => fileInputRef.current?.click();

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    for (const file of Array.from(files)) {
      await browser.uploadFile(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleMkdir = () => {
    const trimmed = folderName.trim();
    if (!trimmed) return;
    browser.mkdir(trimmed);
    setFolderName("");
    setMkdirOpen(false);
  };

  const connectableSelectedCount = browser.entries.filter(
    (e) => browser.selectedFiles.has(e.name) && isConnectable(e),
  ).length;

  return (
    <div className="relative flex flex-col gap-4 p-6">
      {/* Connection overlay */}
      {isConnecting && (
        <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-background/80 backdrop-blur-sm">
          <PrometheuxSpinner
            size={36}
            label={`Connecting data source${connectingNames.size > 1 ? "s" : ""}…`}
          />
          <p className="mt-1 text-xs text-muted-foreground">{[...connectingNames].join(", ")}</p>
        </div>
      )}

      {/* Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <FileBreadcrumb currentPath={browser.currentPath} onNavigate={browser.navigate} />

        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={browser.refresh} disabled={isConnecting}>
            <RefreshCw className="mr-1.5 h-3.5 w-3.5" />
            Refresh
          </Button>

          <Button
            variant="outline"
            size="sm"
            onClick={() => setMkdirOpen(true)}
            disabled={isConnecting}
          >
            <FolderPlus className="mr-1.5 h-3.5 w-3.5" />
            New Folder
          </Button>

          <Button variant="outline" size="sm" onClick={handleUploadClick} disabled={isConnecting}>
            <Upload className="mr-1.5 h-3.5 w-3.5" />
            Upload
          </Button>

          {browser.selectedFiles.size > 0 && (
            <>
              <Button
                variant="outline"
                size="sm"
                className="text-destructive"
                onClick={handleDeleteSelected}
                disabled={isConnecting}
              >
                <Trash2 className="mr-1.5 h-3.5 w-3.5" />
                Delete ({browser.selectedFiles.size})
              </Button>

              {connectableSelectedCount > 0 && (
                <Button size="sm" onClick={handleBulkConnect} disabled={isConnecting}>
                  {isConnecting ? (
                    <PrometheuxSpinner size={16} className="mr-1.5" />
                  ) : (
                    <Link className="mr-1.5 h-3.5 w-3.5" />
                  )}
                  Connect ({connectableSelectedCount})
                </Button>
              )}
            </>
          )}
        </div>
      </div>

      {/* Inline mkdir input */}
      {mkdirOpen && (
        <div className="flex items-center gap-2">
          <input
            type="text"
            placeholder="Folder name"
            value={folderName}
            onChange={(e) => setFolderName(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") handleMkdir();
              if (e.key === "Escape") setMkdirOpen(false);
            }}
            className="h-8 w-56 rounded-md border border-input bg-background px-2 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring"
          />
          <Button size="sm" onClick={handleMkdir}>
            Create
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setMkdirOpen(false);
              setFolderName("");
            }}
          >
            Cancel
          </Button>
        </div>
      )}

      {/* File listing */}
      {browser.isLoading ? (
        <div className="flex items-center justify-center py-16">
          <PrometheuxSpinner size={36} label="Loading files…" />
        </div>
      ) : (
        <FileList
          entries={browser.entries}
          selectedFiles={browser.selectedFiles}
          onToggleSelect={browser.toggleSelect}
          onToggleSelectAll={browser.toggleSelectAll}
          onNavigateInto={browser.navigateInto}
          onDelete={(names) => browser.deleteSelected(names, true)}
          onConnect={handleConnect}
          onRename={browser.rename}
          onMove={browser.move}
          onDownload={browser.download}
          currentPath={browser.currentPath}
          connectingNames={connectingNames}
        />
      )}

      <input
        ref={fileInputRef}
        type="file"
        className="hidden"
        multiple
        onChange={handleFileChange}
      />

      <SheetPickerDialog
        open={sheetPicker.open}
        sheets={sheetPicker.sheets}
        fileName={sheetPicker.fileName}
        onSelect={handleSheetSelect}
        onCancel={handleSheetCancel}
      />
    </div>
  );
}
