import type React from "react";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import {
  API_KEY_PLACEHOLDER,
  buildDefaultQuickKeyName,
  QUICK_EXPIRY_PRESET_OPTIONS,
  type QuickExpiryPreset,
  quickPresetToMinutes,
} from "./apiKeys.utils";
import { useCreateQuickApiKey } from "./useCreateQuickApiKey";

interface QuickApiKeyPopoverProps {
  /** Short label describing what this key is for — becomes part of the default name. */
  contextLabel: string | null | undefined;
  /** Builds the cURL (or any snippet) to copy, given either the real JWT or the placeholder. */
  buildSnippet: (apiKey: string) => string;
  /** The trigger element (button) wrapped by the popover. */
  children: React.ReactNode;
  /** Optional className forwarded to the popover content. */
  contentClassName?: string;
}

interface FormState {
  name: string;
  expiry: QuickExpiryPreset;
  error: string | null;
}

function buildInitialFormState(contextLabel: string | null | undefined): FormState {
  return {
    name: buildDefaultQuickKeyName(contextLabel),
    expiry: "1h",
    error: null,
  };
}

async function writeClipboard(value: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(value);
    return true;
  } catch (error) {
    console.error("Clipboard write failed:", error);
    return false;
  }
}

export const QuickApiKeyPopover: React.FC<QuickApiKeyPopoverProps> = ({
  contextLabel,
  buildSnippet,
  children,
  contentClassName,
}) => {
  const { isCreating, createKey, revokeKey } = useCreateQuickApiKey();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState<FormState>(() => buildInitialFormState(contextLabel));

  // Reset the form when the popover closes so the next open starts fresh
  // (new timestamp, default expiry). Not while open — that would wipe the user's input.
  useEffect(() => {
    if (open) return;
    setForm(buildInitialFormState(contextLabel));
  }, [open, contextLabel]);

  const handleOpenChange = useCallback(
    (nextOpen: boolean) => {
      if (isCreating) return;
      setOpen(nextOpen);
    },
    [isCreating],
  );

  const handleNameChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    setForm((prev) => ({ ...prev, name: value, error: null }));
  }, []);

  const handleExpiryChange = useCallback((value: string) => {
    setForm((prev) => ({ ...prev, expiry: value as QuickExpiryPreset }));
  }, []);

  const handleCreate = useCallback(async () => {
    const trimmedName = form.name.trim();
    if (!trimmedName) {
      setForm((prev) => ({ ...prev, error: "Give this key a name so you can find it later." }));
      return;
    }
    if (trimmedName.length > 120) {
      setForm((prev) => ({ ...prev, error: "Name must be 120 characters or fewer." }));
      return;
    }

    const data = await createKey({
      name: trimmedName,
      expiresInMinutes: quickPresetToMinutes(form.expiry),
    });
    if (!data) return;

    const snippet = buildSnippet(data.token);
    const copied = await writeClipboard(snippet);
    const jti = data.jti;

    toast.success(copied ? "Copied to clipboard" : "API key created", {
      description: copied
        ? "A fresh API key was embedded in the snippet on your clipboard."
        : "Clipboard write failed — the key is now visible in Settings → API Keys.",
      action: {
        label: "Revoke now",
        onClick: () => {
          void revokeKey(jti);
        },
      },
    });
    setOpen(false);
  }, [form.name, form.expiry, createKey, buildSnippet, revokeKey]);

  const handleCopyTemplate = useCallback(async () => {
    const snippet = buildSnippet(API_KEY_PLACEHOLDER);
    const copied = await writeClipboard(snippet);
    if (copied) {
      toast.success("Template copied", {
        description: `Replace ${API_KEY_PLACEHOLDER} with your own API key before running.`,
      });
    } else {
      toast.error("Failed to copy template to clipboard.");
    }
    setOpen(false);
  }, [buildSnippet]);

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger asChild>{children}</PopoverTrigger>
      <PopoverContent
        align="end"
        className={`w-80 ${contentClassName ?? ""}`}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="space-y-3">
          <div>
            <h4 className="text-sm font-semibold">Copy with a fresh API key</h4>
            <p className="text-xs text-muted-foreground mt-1">
              Creates a short-lived API key and embeds it in the snippet you copy.
            </p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="quick-key-name" className="text-xs">
              Name
            </Label>
            <Input
              id="quick-key-name"
              value={form.name}
              onChange={handleNameChange}
              disabled={isCreating}
              maxLength={120}
              className="h-8 text-xs"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="quick-key-expiry" className="text-xs">
              Expires in
            </Label>
            <Select value={form.expiry} onValueChange={handleExpiryChange} disabled={isCreating}>
              <SelectTrigger id="quick-key-expiry" className="h-8 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {QUICK_EXPIRY_PRESET_OPTIONS.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {form.error && <p className="text-xs text-destructive">{form.error}</p>}

          <Button
            type="button"
            size="sm"
            className="w-full"
            onClick={handleCreate}
            disabled={isCreating || !form.name.trim()}
          >
            {isCreating ? (
              <>
                <PrometheuxSpinner size={16} className="mr-2" />
                Creating...
              </>
            ) : (
              "Create key and copy"
            )}
          </Button>

          <div className="pt-1 border-t border-border">
            <button
              type="button"
              onClick={handleCopyTemplate}
              disabled={isCreating}
              className="text-xs text-muted-foreground hover:text-foreground underline underline-offset-2 disabled:opacity-50"
            >
              Copy as template instead ({API_KEY_PLACEHOLDER})
            </button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
};
