import { handleFreemiumLimitError } from "@/features/billing/store/upgradeWallStore";
import type { FailedDatasource } from "@/features/data-sources/components/FailedDatasourcesDialog";
import type {
  InboxStatus,
  ShareRole,
  ShareType,
  ShareUser,
} from "@/features/ontologies/sharing/types";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

export type FailedDatasourceEntry = FailedDatasource;

// Define types for projects
export type OntologyScope = "user" | "organization";

// Projects in the FE come from two sources: the user's own /ontologies/list (origin="owned"
// or undefined) and accepted shares from /ontologies/share/inbox (origin="shared"). Shared
// projects are presented alongside owned ones in pickers; consumers can use `origin` to
// gate owner-only affordances (rename/delete/share/copy) and display "Shared by X" badges.
export type OntologyOrigin = "owned" | "shared";

export interface OntologyData {
  id: string;
  scope: OntologyScope;
  name?: string;
  description?: string;
  author?: string;
  to_persist?: boolean;
  created_at?: string;
  updated_at?: string;
  // Sharing-aware fields. Undefined / "owned" → the current user owns this project.
  // "shared" → this row was injected from the recipient's inbox; loading it transparently
  // proxies to the owner's pod via the dispatcher.
  origin?: OntologyOrigin;
  sharedBy?: ShareUser;
  shareRole?: ShareRole;
  shareId?: string;
  expiresAt?: string | null;
  // Recipient-side lifecycle stage. "accepted" rows can be opened in the editor;
  // "pending" rows surface as invitations the user must accept first. Undefined
  // for owned rows.
  shareStatus?: InboxStatus;
  // "team" when this shared row was derived from a team share. `needsClaim` is
  // true until the member claims a scoped token; a needs-claim team row renders
  // as a "Join" invitation rather than an openable project. `teamId` identifies
  // the recipient team so a team owner/admin can co-manage permissions.
  shareType?: ShareType;
  needsClaim?: boolean;
  teamId?: string;
}

// Define type for templates
export interface TemplateData {
  id: string;
  name: string;
  description: string;
  author?: string;
  scope?: OntologyScope;
  to_persist?: boolean;
  created_at?: string;
  updated_at?: string;
}

export interface ConceptEditorData {
  id: string;
  name: string;
  cells?: Array<{
    id: string;
    content: string;
    position: number;
    timestamp?: string;
    author?: string;
  }>;
  timestamp?: string;
  author?: string;
}

export interface OntologySnapshotMeta {
  id: string;
  ontology_id: string;
  description: string | null;
  created_at: string;
}

// A concept definition as captured in a snapshot (or the live project). Only the
// fields relevant to a diff are returned by the backend — no materialized data.
export interface SnapshotConcept {
  predicate_name: string;
  fields: unknown;
  bind_annotations: string | null;
  model_annotation: string | null;
  definition: string | null;
  post_annotations: string | null;
  mapping_annotations: string | null;
  param_annotations: string | null;
  ontology_schema_type: string | null;
  concept_type: string | null;
  description: string | null;
  position: number | null;
  concept_group: string | null;
}

// A diff source is either a stored snapshot id or the live working state.
export const CURRENT_SNAPSHOT_SOURCE = "current" as const;
export type SnapshotDiffSource = string;

export class OntologyService {
  static async listOntologies(
    scopes: OntologyScope[] = ["user", "organization"],
  ): Promise<OntologyData[]> {
    try {
      // Create query parameters for scopes
      const scopesParam = scopes.join(",");
      const url = `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/list?scopes=${scopesParam}`;

      const response = await HttpService.get(url, PROMETHEUX_CONFIG.AUTH_TOKEN);

      if (response.status === "success" && Array.isArray(response.data)) {
        return response.data.map((item) => {
          if (typeof item === "string") {
            return { id: item, scope: "user" as OntologyScope };
          } else if (typeof item === "object" && item.id) {
            return {
              id: item.id,
              name: item.name || item.id,
              description: item.description || "",
              author: item.author || "",
              scope: item.scope || ("user" as OntologyScope),
            };
          }
          // Fallback
          return {
            id: String(item),
            name: String(item),
            description: "",
            author: "",
            scope: "user" as OntologyScope,
          };
        });
      }

      return [];
    } catch (_error) {
      throw new Error("Failed to fetch ontologies");
    }
  }

  static async createOntology(
    name: string,
    description: string = "",
    scope: OntologyScope = "user",
    toPersist: boolean = true,
  ): Promise<OntologyData> {
    try {
      // Create payload according to the specified format
      const payload = {
        project: {
          name: name,
          description: description,
          scope: scope,
          to_persist: toPersist,
        },
      };

      const response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/save`,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      if (response.status === "success" && response.data) {
        // The save endpoint returns the id under ontology_id, not id.
        const ontologyData = response.data;
        if (ontologyData.ontology_id && !ontologyData.id) {
          return {
            ...ontologyData,
            id: ontologyData.ontology_id,
          } as OntologyData;
        }
        return response.data as OntologyData;
      }

      throw new Error("Failed to create ontology: Invalid response format");
    } catch (error) {
      handleFreemiumLimitError(error);
      throw new Error("Failed to create ontology");
    }
  }

  static async saveOntology(
    ontologyId: string,
    name: string,
    description: string = "",
    scope: OntologyScope = "user",
    toPersist: boolean = true,
  ): Promise<boolean> {
    try {
      // Create payload according to the specified format
      const payload = {
        project: {
          id: ontologyId,
          name: name,
          description: description,
          scope: scope,
          to_persist: toPersist,
        },
      };

      const response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/save`,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      // Check for successful save response
      return response.status === "success";
    } catch (_error) {
      throw new Error("Failed to save ontology");
    }
  }

  static async deleteOntology(ontologyId: string, scope: OntologyScope = "user"): Promise<boolean> {
    try {
      // Updated payload structure to match API requirements
      const payload = {
        project: {
          id: ontologyId,
          scope: scope,
        },
      };

      // Updated endpoint to include workspace ID
      const response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/cleanup`,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      // Check for successful deletion response
      return response.status === "success";
    } catch (_error) {
      throw new Error("Failed to delete ontology");
    }
  }

  static async loadOntology(
    ontologyId: string,
    scope: OntologyScope = "user",
  ): Promise<OntologyData> {
    try {
      // Create query parameters for project ID and scope
      const url = `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/load?ontology_id=${ontologyId}&scope=${scope}`;

      const response = await HttpService.get(url, PROMETHEUX_CONFIG.AUTH_TOKEN);

      if (response.status === "success" && response.data) {
        return response.data as OntologyData;
      }

      throw new Error("Failed to load ontology: Invalid response format");
    } catch (_error) {
      throw new Error("Failed to load ontology");
    }
  }

  static async listTemplates(): Promise<TemplateData[]> {
    try {
      const response = await HttpService.get(
        `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/list-templates`,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      if (response.status === "success" && Array.isArray(response.data)) {
        return response.data.map((item) => {
          if (typeof item === "object" && item.id && item.name) {
            return {
              id: item.id,
              name: item.name,
              description: item.description || "",
              author: item.author || "",
              scope: item.scope || ("organization" as OntologyScope),
              to_persist: item.to_persist || true,
              created_at: item.created_at || "",
              updated_at: item.updated_at || "",
            };
          }
          // Fallback for unexpected format
          return {
            id: String(item.id || item),
            name: String(item.name || item),
            description: String(item.description || ""),
            author: String(item.author || ""),
            scope: "organization" as OntologyScope,
            to_persist: true,
            created_at: "",
            updated_at: "",
          };
        });
      }

      return [];
    } catch (_error) {
      throw new Error("Failed to fetch templates");
    }
  }

  static async createFromTemplate(
    templateId: string,
    ontologyName: string,
    _ontologyDescription: string = "",
    scope: OntologyScope = "user",
  ): Promise<OntologyData & { failed_datasources?: FailedDatasourceEntry[] }> {
    try {
      const payload = {
        template_id: templateId,
        new_ontology_name: ontologyName,
        project_scope: scope,
      };

      const response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/import-template`,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      if (response.status === "success" && response.data) {
        return response.data;
      }

      throw new Error("Failed to create ontology from template: Invalid response format");
    } catch (error) {
      handleFreemiumLimitError(error);
      throw new Error("Failed to create ontology from template");
    }
  }

  static async copyOntology(
    ontologyId: string,
    newOntologyName: string,
    targetScope: OntologyScope = "user",
  ): Promise<string> {
    try {
      // Create payload according to the API schema
      const payload = {
        ontology_id: ontologyId,
        new_ontology_name: newOntologyName,
        target_scope: targetScope,
      };

      const response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/copy`,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      if (response.status === "success" && response.data && response.data.new_ontology_id) {
        return response.data.new_ontology_id;
      }

      throw new Error("Failed to copy ontology: Invalid response format");
    } catch (error) {
      handleFreemiumLimitError(error);
      throw new Error("Failed to copy ontology");
    }
  }

  static async exportOntology(ontologyId: string, scope: OntologyScope = "user"): Promise<any> {
    try {
      const payload = {
        ontology_id: ontologyId,
        scope: scope,
      };

      const response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/export-ontology`,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      if (response.status === "success" && response.data) {
        return response.data;
      }

      throw new Error("Failed to export ontology: Invalid response format");
    } catch (error) {
      console.error("Error exporting ontology:", error);
      throw error;
    }
  }

  static async importOntology(
    exportData: any,
    scope: OntologyScope = "user",
    forceNewId = false,
  ): Promise<{
    new_ontology_id: string;
    failed_datasources?: FailedDatasourceEntry[];
  }> {
    try {
      const payload = {
        export_data: exportData,
        scope: scope,
        force_new_id: forceNewId,
      };

      const response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/import-ontology`,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );

      if (response.status === "success" && response.data) {
        return response.data;
      }

      throw new Error("Failed to import ontology: Invalid response format");
    } catch (error) {
      handleFreemiumLimitError(error);
      console.error("Error importing ontology:", error);
      throw error;
    }
  }

  // ─── Snapshots (Versioning) ──────────────────────────────────────────────────

  static async createSnapshot(
    ontologyId: string,
    scope: OntologyScope = "user",
    description?: string,
  ): Promise<OntologySnapshotMeta> {
    const payload: Record<string, unknown> = { ontology_id: ontologyId, scope };
    if (description) payload.description = description;

    const response = await HttpService.post(
      `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/snapshots/create`,
      payload,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
    );

    if (response.status === "success" && response.data) {
      return response.data as OntologySnapshotMeta;
    }

    throw new Error("Failed to create snapshot");
  }

  static async listSnapshots(
    ontologyId: string,
    scope: OntologyScope = "user",
  ): Promise<OntologySnapshotMeta[]> {
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/snapshots/list?ontology_id=${ontologyId}&scope=${scope}`;
    const response = await HttpService.get(url, PROMETHEUX_CONFIG.AUTH_TOKEN);

    if (response.status === "success" && Array.isArray(response.data)) {
      return response.data as OntologySnapshotMeta[];
    }

    return [];
  }

  static async restoreSnapshot(
    snapshotId: string,
    ontologyId: string,
    scope: OntologyScope = "user",
    createSafetySnapshot = true,
  ): Promise<void> {
    const payload = {
      snapshot_id: snapshotId,
      ontology_id: ontologyId,
      scope,
      create_safety_snapshot: createSafetySnapshot,
    };

    const response = await HttpService.post(
      `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/snapshots/restore`,
      payload,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
    );

    if (response.status !== "success") {
      throw new Error("Failed to restore snapshot");
    }
  }

  static async deleteSnapshot(
    snapshotId: string,
    ontologyId: string,
    scope: OntologyScope = "user",
  ): Promise<void> {
    const payload = { snapshot_id: snapshotId, ontology_id: ontologyId, scope };

    const response = await HttpService.post(
      `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/snapshots/delete`,
      payload,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
    );

    if (response.status !== "success") {
      throw new Error("Failed to delete snapshot");
    }
  }

  static async getSnapshotConcepts(
    ontologyId: string,
    source: SnapshotDiffSource,
    scope: OntologyScope = "user",
  ): Promise<SnapshotConcept[]> {
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/ontologies/snapshots/concepts?ontology_id=${encodeURIComponent(
      ontologyId,
    )}&source=${encodeURIComponent(source)}&scope=${scope}`;
    const response = await HttpService.get(url, PROMETHEUX_CONFIG.AUTH_TOKEN);

    if (response.status === "success" && Array.isArray(response.data)) {
      return response.data as SnapshotConcept[];
    }

    return [];
  }
}
