import { useQuery } from "@tanstack/react-query";
import { ConceptClient, type FetchResult } from "../api/ConceptClient";

const client = new ConceptClient();

interface UseConceptRowsReturn {
  data: FetchResult | null;
  isLoading: boolean;
  error: Error | null;
}

/** Read rows of an already-populated concept (options sources, record-group seeds). */
export function useConceptRows(
  ontologyId: string | undefined,
  conceptName: string | undefined,
  pageSize = 200,
): UseConceptRowsReturn {
  const { data, isLoading, error } = useQuery({
    queryKey: ["app-concept-rows", ontologyId, conceptName, pageSize],
    queryFn: () => client.fetchConceptData(ontologyId!, conceptName!, "user", 1, pageSize),
    enabled: !!ontologyId && !!conceptName,
    staleTime: 60_000,
  });
  return { data: data ?? null, isLoading, error: error instanceof Error ? error : null };
}

export interface SelectOption {
  value: string;
  label: string;
}

/**
 * Case-insensitive column lookup. Column-name references in definitions are
 * validated case-insensitively by the backend, and fetch results can differ
 * in casing from the declared model — resolution must tolerate both.
 */
export function columnIndex(columnNames: string[], name: string | undefined | null): number {
  if (!name) return -1;
  const lower = name.toLowerCase();
  return columnNames.findIndex((column) => column.toLowerCase() === lower);
}

/** Map a concept's rows to select/combobox options via valueCol/labelCol names. */
export function rowsToOptions(
  result: FetchResult | null,
  valueCol?: string,
  labelCol?: string,
): SelectOption[] {
  if (!result) return [];
  const valueIndex = valueCol ? columnIndex(result.columnNames, valueCol) : 0;
  const labelIndex = labelCol ? columnIndex(result.columnNames, labelCol) : valueIndex;
  if (valueIndex < 0) return [];
  const seen = new Set<string>();
  return result.rows
    .map((row) => ({
      value: String(row[valueIndex] ?? ""),
      label: String(row[labelIndex >= 0 ? labelIndex : valueIndex] ?? ""),
    }))
    .filter((option) => {
      if (!option.value || seen.has(option.value)) return false;
      seen.add(option.value);
      return true;
    });
}
