import { Folder, Globe, HelpCircle, SendHorizonal } from "lucide-react";
import { useRef, useState } from "react";

import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

import type { ClarificationData, ClarificationState } from "../store";

interface ClarificationPromptProps {
  data: ClarificationData;
  state: ClarificationState;
  onAnswer: (answer: string) => void;
  onResolve: (state: ClarificationState) => void;
}

type Scope = "global" | "ontology";

function buildAnswerText(
  selectedValue: string,
  scope: Scope | null,
  customText: string,
  options: ClarificationData["options"],
): string {
  const trimmedCustom = customText.trim();
  if (selectedValue === "__custom__" && trimmedCustom) {
    if (scope) return `[${scope}] ${trimmedCustom}`;
    return trimmedCustom;
  }
  const option = options.find((o) => o.value === selectedValue);
  const labelPart = option ? option.label : selectedValue;
  if (scope) return `[${scope}] ${labelPart}`;
  return labelPart;
}

export function ClarificationPrompt({
  data,
  state,
  onAnswer,
  onResolve,
}: ClarificationPromptProps) {
  const ontologyAvailable = Boolean(data.ontology_id);
  const initialScope: Scope | null = data.scope_picker
    ? ontologyAvailable
      ? "ontology"
      : "global"
    : null;
  const [scope, setScope] = useState<Scope | null>(initialScope);
  const [selectedValue, setSelectedValue] = useState<string | null>(null);
  const [customText, setCustomText] = useState("");
  const customInputRef = useRef<HTMLInputElement>(null);

  const isPending = state === "pending";
  const isCustomSelected = selectedValue === "__custom__";

  const handleSelectOption = (value: string) => () => {
    setSelectedValue(value);
    setCustomText("");
  };

  const handleCustomTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setCustomText(e.target.value);
    if (selectedValue !== "__custom__") setSelectedValue("__custom__");
  };

  const handleCustomKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key !== "Enter") return;
    e.preventDefault();
    handleSubmit();
  };

  const handleScopeOntology = () => setScope("ontology");
  const handleScopeGlobal = () => setScope("global");

  const canSubmit =
    isPending &&
    selectedValue !== null &&
    (selectedValue !== "__custom__" || customText.trim().length > 0);

  const handleSubmit = () => {
    if (!canSubmit || selectedValue === null) return;
    const answer = buildAnswerText(selectedValue, scope, customText, data.options);
    onResolve("answered");
    onAnswer(answer);
  };

  return (
    <div
      className={cn(
        "rounded-md border border-border bg-card p-3 text-sm",
        state === "answered" && "border-primary/40 bg-primary/5 opacity-80",
      )}
    >
      <header className="flex flex-wrap items-center gap-2 pb-1.5 text-xs text-muted-foreground">
        <HelpCircle className="h-3.5 w-3.5 text-primary" />
        <span className="font-medium uppercase tracking-wide">Clarification</span>
        {data.scope_picker && isPending && (
          <>
            <span aria-hidden>·</span>
            <div className="inline-flex items-center gap-0.5 rounded border border-border bg-background/60 p-0.5">
              <button
                type="button"
                onClick={handleScopeOntology}
                disabled={!ontologyAvailable}
                className={cn(
                  "inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide transition-colors",
                  scope === "ontology"
                    ? "bg-primary text-primary-foreground"
                    : "text-muted-foreground hover:text-foreground",
                  !ontologyAvailable && "opacity-50",
                )}
              >
                <Folder className="h-3 w-3" />
                project
              </button>
              <button
                type="button"
                onClick={handleScopeGlobal}
                className={cn(
                  "inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide transition-colors",
                  scope === "global"
                    ? "bg-primary text-primary-foreground"
                    : "text-muted-foreground hover:text-foreground",
                )}
              >
                <Globe className="h-3 w-3" />
                global
              </button>
            </div>
          </>
        )}
      </header>

      {data.context && <p className="pb-2 text-xs text-muted-foreground">{data.context}</p>}

      <p className="whitespace-pre-wrap font-medium text-foreground">{data.question}</p>

      <ul className="mt-2 space-y-1">
        {data.options.map((option) => {
          const isActive = selectedValue === option.value;
          return (
            <li key={option.value}>
              <button
                type="button"
                onClick={handleSelectOption(option.value)}
                disabled={!isPending}
                className={cn(
                  "w-full rounded border border-border p-2 text-left text-xs transition-colors",
                  isActive ? "border-primary/60 bg-primary/10" : "bg-background hover:bg-accent",
                  !isPending && "cursor-default",
                )}
              >
                <div className="font-medium text-foreground">{option.label}</div>
                {option.description && (
                  <div className="pt-0.5 text-muted-foreground">{option.description}</div>
                )}
              </button>
            </li>
          );
        })}
      </ul>

      {data.allow_custom && isPending && (
        <div
          className={cn(
            "mt-2 flex items-center gap-1.5 rounded border p-1.5 transition-colors",
            isCustomSelected ? "border-primary/60 bg-primary/5" : "border-border bg-background",
          )}
        >
          <input
            ref={customInputRef}
            type="text"
            value={customText}
            onChange={handleCustomTextChange}
            onKeyDown={handleCustomKeyDown}
            placeholder="Other — type your own answer"
            disabled={!isPending}
            className="min-w-0 flex-1 bg-transparent px-1.5 py-1 text-xs text-foreground placeholder:text-muted-foreground focus:outline-none"
          />
          {isCustomSelected && customText.trim().length > 0 && (
            <button
              type="button"
              onClick={handleSubmit}
              className="flex-shrink-0 rounded p-1 text-primary hover:bg-primary/10 transition-colors"
            >
              <SendHorizonal className="h-3.5 w-3.5" />
            </button>
          )}
        </div>
      )}

      {isPending && selectedValue !== null && !isCustomSelected && (
        <footer className="mt-3 flex justify-end gap-2">
          <Button type="button" size="sm" onClick={handleSubmit} disabled={!canSubmit}>
            Answer
          </Button>
        </footer>
      )}
      {state === "answered" && (
        <footer className="mt-2 text-xs text-muted-foreground">Answer sent</footer>
      )}
    </div>
  );
}
