import type React from "react";
import { useState } from "react";
import { useMyTeams } from "@/features/teams/hooks/useMyTeams";
import { useTeamJoinRequests } from "@/features/teams/hooks/useTeamJoinRequests";
import { useTeamPendingInvitations } from "@/features/teams/hooks/useTeamPendingInvitations";
import type { TeamMembershipRow } from "@/features/teams/types";
import { teamRoleCapabilities } from "@/features/teams/utils/teams.utils";
import TeamInvitationsTab from "./TeamInvitationsTab";
import TeamMembersTab from "./TeamMembersTab";

interface TeamRosterPanelProps {
  team: TeamMembershipRow;
  callerUserId: string;
}

type TabId = "members" | "invitations";

// Composition shell for the team detail body. Two tabs, mirroring the
// TabButton pattern used on TeamsPage so both pages read as a family:
//   * Members — active roster + role / seat controls (visible to everyone).
//   * Invitations — invite form + pending invitations + join requests
//                   (owner/admin only — every action inside requires the
//                   admin role).
//
// For regular members the whole tab bar is skipped: they'd have nothing to
// switch between, so we render the members tab body directly to keep the
// layout unchanged for them.
const TeamRosterPanel: React.FC<TeamRosterPanelProps> = ({ team, callerUserId }) => {
  const capabilities = teamRoleCapabilities(team.role);
  const [activeTab, setActiveTab] = useState<TabId>("members");

  // useMyTeams is also called by the header — RQ dedupes so this doesn't fire
  // a second request, but referencing the hook makes the invalidation chain
  // (invite → inbox → my teams) explicit.
  useMyTeams();

  // Tab counts for the admin view. Only mounted (`enabled`) for owner/admin
  // so we don't fire pointless requests for regular members whose tabs are
  // hidden. The child sub-components (mounted on the Invitations tab) call
  // the same hooks — RQ dedupes them into a single request per key.
  const { invitations: pendingInvitations } = useTeamPendingInvitations(team.id, {
    enabled: capabilities.canInvite,
  });
  const { requests: joinRequests } = useTeamJoinRequests(team.id, {
    enabled: capabilities.canInvite,
  });
  const invitationsCount = pendingInvitations.length + joinRequests.length;

  if (!capabilities.canInvite) {
    return (
      <div className="px-8 py-6">
        <TeamMembersTab team={team} callerUserId={callerUserId} />
      </div>
    );
  }

  return (
    <div>
      {/* Tab bar + body match the shared page pattern (Projects / Data / Teams
          list): px-6 tab bar with a full-width underline, px-8 py-6 body. */}
      <div className="flex border-b border-border px-6">
        <TabButton
          active={activeTab === "members"}
          onClick={() => setActiveTab("members")}
          label="Members"
        />
        <TabButton
          active={activeTab === "invitations"}
          onClick={() => setActiveTab("invitations")}
          label="Invitations"
          count={invitationsCount}
        />
      </div>

      <div className="px-8 py-6">
        {activeTab === "members" && <TeamMembersTab team={team} callerUserId={callerUserId} />}
        {activeTab === "invitations" && <TeamInvitationsTab team={team} />}
      </div>
    </div>
  );
};

interface TabButtonProps {
  active: boolean;
  onClick: () => void;
  label: string;
  count?: number;
}

// Matches TabButton on TeamsPage so both pages share the same visual token
// for tab selection. Kept co-located here to avoid an extra shared file for
// a pattern that lives in exactly two places today — if a third page needs
// the same treatment, lift it to shared/.
const TabButton: React.FC<TabButtonProps> = ({ active, onClick, label, count }) => (
  <button
    type="button"
    onClick={onClick}
    className={`flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium transition-colors ${
      active
        ? "border-b-2 border-primary text-primary"
        : "text-muted-foreground hover:text-foreground"
    }`}
  >
    {label}
    {typeof count === "number" && count > 0 && (
      <span className="rounded-full bg-secondary px-1.5 py-0.5 text-[10px] font-semibold text-muted-foreground">
        {count}
      </span>
    )}
  </button>
);

export default TeamRosterPanel;
