import { Loader2 } from "lucide-react";
import { useNavigate } from "react-router-dom";

import { noteDisplayTitle } from "@/features/context-layer/notes/notesModel";

import { useGlobalSearch } from "../hooks/useGlobalSearch";

interface GlobalSearchResultsProps {
  query: string;
  activeOntologyId: string | null;
  onClose: () => void;
}

interface ResultItem {
  id: string;
  title: string;
  subtitle: string;
  path: string;
}

interface ResultGroup {
  heading: string;
  items: ResultItem[];
}

interface ResultGroupSectionProps {
  group: ResultGroup;
  onSelect: (path: string) => void;
}

function ResultGroupSection({ group, onSelect }: ResultGroupSectionProps) {
  if (group.items.length === 0) return null;
  return (
    <section className="pb-2">
      <p className="px-2 pb-1 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        {group.heading}
      </p>
      <ul className="space-y-px">
        {group.items.map((item) => (
          <li key={item.id}>
            <button
              type="button"
              onClick={() => onSelect(item.path)}
              className="w-full space-y-0.5 rounded-md px-2 py-1.5 text-left transition-colors hover:bg-accent/50"
            >
              <span className="block truncate text-sm font-medium text-foreground">
                {item.title}
              </span>
              {item.subtitle && (
                <span className="block truncate text-xs text-muted-foreground">
                  {item.subtitle}
                </span>
              )}
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

export function GlobalSearchResults({
  query,
  activeOntologyId,
  onClose,
}: GlobalSearchResultsProps) {
  const navigate = useNavigate();
  const { projects, apps, context, isLoading, isActive } = useGlobalSearch(query, activeOntologyId);

  const handleSelect = (path: string) => {
    onClose();
    navigate(path);
  };

  if (!isActive) {
    return (
      <p className="p-3 text-xs italic text-muted-foreground">
        Type at least 3 characters to search.
      </p>
    );
  }

  const groups: ResultGroup[] = [
    {
      heading: "Ontologies",
      items: projects.map((project) => ({
        id: project.id,
        title: project.name || project.id,
        subtitle: project.description ?? "",
        path: `/editor/${project.id}`,
      })),
    },
    {
      heading: "Apps",
      items: apps.map((app) => ({
        id: app.id,
        title: app.name,
        subtitle: app.ontologyName,
        path: `/apps/${app.ontologyId}/${app.id}`,
      })),
    },
    {
      heading: "Context",
      items: context.map((note) => ({
        id: note.id,
        title: noteDisplayTitle(note),
        subtitle: note.text,
        path: `/context/${note.id}`,
      })),
    },
  ];

  const hasResults = groups.some((group) => group.items.length > 0);

  if (isLoading && !hasResults) {
    return (
      <div className="flex items-center gap-2 p-3 text-xs text-muted-foreground">
        <Loader2 className="h-3.5 w-3.5 animate-spin" />
        Searching…
      </div>
    );
  }

  if (!hasResults) {
    return <p className="p-3 text-xs italic text-muted-foreground">No matching results.</p>;
  }

  return (
    <div>
      {groups.map((group) => (
        <ResultGroupSection key={group.heading} group={group} onSelect={handleSelect} />
      ))}
    </div>
  );
}
