import { useCallback, useMemo, useState } from "react";
import type { ConceptCell } from "@/features/concept-editor/types";

interface UseDeleteCellRequestParams {
  groupedCells: Record<string, ConceptCell[]>;
  ungroupedCells: ConceptCell[];
  onDelete?: (cellId: string) => void | Promise<void>;
}

interface UseDeleteCellRequestReturn {
  cellPendingDelete: ConceptCell | null;
  /**
   * Stages a delete for confirmation. Looks the cell up across grouped +
   * ungrouped sources by id. Returns undefined when `onDelete` is missing so
   * callers can leave the affordance off.
   */
  requestDeleteCell: ((cellId: string) => void) | undefined;
  confirmDelete: () => Promise<void>;
  cancelDelete: () => void;
}

/**
 * Owns the "user has requested to delete a cell, awaiting confirmation"
 * state used by ExplorerTree's keyboard Delete key and the context-menu
 * Delete item. Both surfaces stage through the same dialog rather than
 * deleting immediately.
 */
export function useDeleteCellRequest({
  groupedCells,
  ungroupedCells,
  onDelete,
}: UseDeleteCellRequestParams): UseDeleteCellRequestReturn {
  const [cellPendingDelete, setCellPendingDelete] = useState<ConceptCell | null>(null);

  const requestDeleteCell = useMemo(() => {
    if (!onDelete) return undefined;
    return (cellId: string) => {
      for (const arr of Object.values(groupedCells)) {
        const cell = arr.find((c) => c.id === cellId);
        if (cell) {
          setCellPendingDelete(cell);
          return;
        }
      }
      const ungrouped = ungroupedCells.find((c) => c.id === cellId);
      if (ungrouped) setCellPendingDelete(ungrouped);
    };
  }, [groupedCells, ungroupedCells, onDelete]);

  const confirmDelete = useCallback(async () => {
    if (cellPendingDelete && onDelete) await onDelete(cellPendingDelete.id);
    setCellPendingDelete(null);
  }, [cellPendingDelete, onDelete]);

  const cancelDelete = useCallback(() => setCellPendingDelete(null), []);

  return { cellPendingDelete, requestDeleteCell, confirmDelete, cancelDelete };
}
