import { useRef, useState } from "react";
import type { OntologyScope } from "@/features/ontologies/api";

export function useOntologiesPageState(initialActiveTab: string) {
  const hasFetchedOnMount = useRef(false);

  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [isCreatingOntology, setIsCreatingOntology] = useState(false);

  const [showEditDialog, setShowEditDialog] = useState(false);
  const [editingOntology, setEditingOntology] = useState<{
    id: string;
    name: string;
    description: string;
    scope: OntologyScope;
  } | null>(null);

  const [openingOntologyId, setOpeningOntologyId] = useState<string | null>(null);
  const [usingTemplateId, setUsingTemplateId] = useState<string | null>(null);

  const [isDeletingOntology, setIsDeletingOntology] = useState(false);
  const [isUpdatingOntology, setIsUpdatingOntology] = useState(false);
  const [isImportingOntology, setIsImportingOntology] = useState(false);

  const [searchQuery, setSearchQuery] = useState("");
  const [isCreatingFromContext, setIsCreatingFromContext] = useState(false);
  const [loadingStep, setLoadingStep] = useState(0);
  const [selectedTemplateCategory, setSelectedTemplateCategory] = useState<string>("all");

  const [activeContentTab, setActiveContentTab] = useState("projects");

  const [attachedFiles, setAttachedFiles] = useState<File[]>([]);
  const [isProcessingFiles, setIsProcessingFiles] = useState(false);

  const [selectedConcepts, setSelectedConcepts] = useState<string[]>([]);
  const [showConceptSelector, setShowConceptSelector] = useState(false);

  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [prevActiveTab, setPrevActiveTab] = useState(initialActiveTab);

  return {
    hasFetchedOnMount,
    showCreateDialog,
    setShowCreateDialog,
    isCreatingOntology,
    setIsCreatingOntology,
    showEditDialog,
    setShowEditDialog,
    editingOntology,
    setEditingOntology,
    openingOntologyId,
    setOpeningOntologyId,
    usingTemplateId,
    setUsingTemplateId,
    isDeletingOntology,
    setIsDeletingOntology,
    isUpdatingOntology,
    setIsUpdatingOntology,
    isImportingOntology,
    setIsImportingOntology,
    searchQuery,
    setSearchQuery,
    isCreatingFromContext,
    setIsCreatingFromContext,
    loadingStep,
    setLoadingStep,
    selectedTemplateCategory,
    setSelectedTemplateCategory,
    activeContentTab,
    setActiveContentTab,
    attachedFiles,
    setAttachedFiles,
    isProcessingFiles,
    setIsProcessingFiles,
    selectedConcepts,
    setSelectedConcepts,
    showConceptSelector,
    setShowConceptSelector,
    sidebarCollapsed,
    setSidebarCollapsed,
    prevActiveTab,
    setPrevActiveTab,
  };
}
