import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import {
  applyTeamAdminAction,
  clearConceptRestriction,
  type ListRestrictionsFilter,
  listConceptRestrictions,
  setConceptRestriction,
} from "../api";
import {
  type ClearRestrictionInput,
  type ConceptRestriction,
  OWNER_CALLER,
  type PermissionCaller,
  type SetRestrictionInput,
  type ShareError,
} from "../types";

export const CONCEPT_RESTRICTIONS_KEY = ["concept-restrictions"] as const;

const restrictionsKey = (ontologyId: string) => [...CONCEPT_RESTRICTIONS_KEY, ontologyId] as const;

// The owner-only GET returns a bare array; the delegated team-admin/apply route
// may return the same rows under a wrapper key. Coerce either shape to an array
// so the consumers' `.filter`/`.find` calls can never crash the render tree.
function coerceRestrictions(data: unknown): ConceptRestriction[] {
  if (Array.isArray(data)) return data;
  if (data && typeof data === "object") {
    const rec = data as Record<string, unknown>;
    for (const key of ["restrictions", "items", "results", "rows", "data"]) {
      if (Array.isArray(rec[key])) return rec[key] as ConceptRestriction[];
    }
  }
  return [];
}

interface UseConceptRestrictionsOptions {
  ontologyId: string;
  filter?: ListRestrictionsFilter;
  enabled?: boolean;
  // When the caller is a recipient-team admin (not the project owner), set/clear
  // mutations route through team-admin/apply instead of the owner-only endpoints.
  caller?: PermissionCaller;
}

export function useConceptRestrictions({
  ontologyId,
  filter,
  enabled = true,
  caller = OWNER_CALLER,
}: UseConceptRestrictionsOptions) {
  const { session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;

  const query = useQuery<ConceptRestriction[], ShareError>({
    queryKey: [...restrictionsKey(ontologyId), caller.mode, filter],
    queryFn: () => {
      // Team admins can't hit the owner-only GET (it asserts ownership → 404),
      // so they read the same rows through the delegation endpoint.
      if (caller.mode === "team_admin") {
        return applyTeamAdminAction<ConceptRestriction[]>(
          supabaseToken,
          ontologyId,
          caller.teamId,
          {
            action: "list_concept_restrictions",
            subject_type: filter?.recipient_sub ? "user" : filter?.team_id ? "team" : undefined,
            subject_id: filter?.recipient_sub ?? filter?.team_id,
          },
        );
      }
      return listConceptRestrictions(supabaseToken, ontologyId, filter);
    },
    enabled: enabled && Boolean(ontologyId && supabaseToken),
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const setMutation = useMutation<ConceptRestriction, ShareError, SetRestrictionInput>({
    mutationFn: (input) => {
      if (caller.mode === "team_admin") {
        return applyTeamAdminAction<ConceptRestriction>(
          supabaseToken,
          input.ontology_id,
          caller.teamId,
          {
            action: "set_concept_restriction",
            predicate_name: input.predicate_name,
            level: input.level,
            subject_type: input.recipient_sub ? "user" : "team",
            subject_id: input.recipient_sub,
          },
        );
      }
      return setConceptRestriction(supabaseToken, input);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: CONCEPT_RESTRICTIONS_KEY });
    },
  });

  const clearMutation = useMutation<void, ShareError, ClearRestrictionInput>({
    mutationFn: async (input) => {
      if (caller.mode === "team_admin") {
        await applyTeamAdminAction<unknown>(supabaseToken, input.ontology_id, caller.teamId, {
          action: "clear_concept_restriction",
          predicate_name: input.predicate_name,
          subject_type: input.recipient_sub ? "user" : "team",
          subject_id: input.recipient_sub,
        });
        return;
      }
      await clearConceptRestriction(supabaseToken, input);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: CONCEPT_RESTRICTIONS_KEY });
    },
  });

  return {
    restrictions: coerceRestrictions(query.data),
    isLoading: query.isLoading,
    error: query.error,
    refresh: query.refetch,
    setRestriction: setMutation.mutateAsync,
    isSettingRestriction: setMutation.isPending,
    clearRestriction: clearMutation.mutateAsync,
    isClearingRestriction: clearMutation.isPending,
  };
}
