import { create } from "zustand";
import { engineClient } from "../api/EngineClient";
import type {
  ActuatorHealth,
  RuntimeSample,
  SparkApplication,
  SparkExecutor,
  SparkJob,
  SparkUIStatus,
} from "../types/engineMonitor.types";
import { extractMetricValue } from "../utils/engineMonitor.utils";

const POLL_INTERVAL_MS = 5000;
const MAX_SAMPLES = 60;

interface EngineMonitorState {
  status: SparkUIStatus | null;
  jobs: SparkJob[];
  executors: SparkExecutor[];
  applications: SparkApplication[];

  health: ActuatorHealth | null;
  cpu: number | null;
  cpuCount: number | null;
  memoryUsed: number | null;
  memoryMax: number | null;
  samples: RuntimeSample[];
  isTriggeringGc: boolean;
  gcLastTriggeredAt: number | null;

  isLoading: boolean;
  lastUpdatedAt: number | null;
  error: string | null;
  subscriberCount: number;

  subscribe: () => void;
  unsubscribe: () => void;
  refreshNow: () => Promise<void>;
  triggerGc: () => Promise<boolean>;
}

interface SparkSnapshot {
  status: SparkUIStatus | null;
  jobs: SparkJob[];
  executors: SparkExecutor[];
  applications: SparkApplication[];
}

interface RuntimeSnapshot {
  health: ActuatorHealth | null;
  cpu: number | null;
  cpuCount: number | null;
  memoryUsed: number | null;
  memoryMax: number | null;
}

let pollHandle: ReturnType<typeof setInterval> | null = null;
let inflight: Promise<void> | null = null;

function startPolling(refresh: () => Promise<void>) {
  if (pollHandle !== null) return;
  void refresh();
  pollHandle = setInterval(() => {
    void refresh();
  }, POLL_INTERVAL_MS);
}

function stopPolling() {
  if (pollHandle === null) return;
  clearInterval(pollHandle);
  pollHandle = null;
}

async function fetchSparkSnapshot(): Promise<SparkSnapshot> {
  const status = await engineClient.getStatus();
  if (!status || status.running !== true) {
    return { status, jobs: [], executors: [], applications: [] };
  }

  const [jobs, executors, applications] = await Promise.all([
    engineClient.getJobs(),
    engineClient.getExecutors(),
    engineClient.getApplications(),
  ]);

  return { status, jobs, executors, applications };
}

async function fetchRuntimeSnapshot(): Promise<RuntimeSnapshot> {
  const [health, cpuMetric, cpuCountMetric, heapUsedMetric, heapMaxMetric] = await Promise.all([
    engineClient.getHealth(),
    engineClient.getCpuMetric(),
    engineClient.getCpuCountMetric(),
    engineClient.getHeapUsedMetric(),
    engineClient.getHeapMaxMetric(),
  ]);

  return {
    health,
    cpu: extractMetricValue(cpuMetric),
    cpuCount: extractMetricValue(cpuCountMetric),
    memoryUsed: extractMetricValue(heapUsedMetric),
    memoryMax: extractMetricValue(heapMaxMetric),
  };
}

function appendSample(
  existing: RuntimeSample[],
  runtime: RuntimeSnapshot,
  ts: number,
): RuntimeSample[] {
  const next = existing.concat({
    ts,
    cpu: runtime.cpu,
    memoryUsed: runtime.memoryUsed,
  });
  if (next.length <= MAX_SAMPLES) return next;
  return next.slice(next.length - MAX_SAMPLES);
}

export const useEngineMonitorStore = create<EngineMonitorState>((set, get) => {
  const refreshNow = async () => {
    if (inflight) return inflight;

    set({ isLoading: true });
    inflight = (async () => {
      try {
        const [spark, runtime] = await Promise.all([fetchSparkSnapshot(), fetchRuntimeSnapshot()]);

        const ts = Date.now();
        const previousSamples = get().samples;

        set({
          status: spark.status,
          jobs: spark.jobs,
          executors: spark.executors,
          applications: spark.applications,
          health: runtime.health,
          cpu: runtime.cpu,
          cpuCount: runtime.cpuCount,
          memoryUsed: runtime.memoryUsed,
          memoryMax: runtime.memoryMax,
          samples: appendSample(previousSamples, runtime, ts),
          lastUpdatedAt: ts,
          error: null,
          isLoading: false,
        });
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : "Failed to load engine data";
        set({ error: message, isLoading: false });
      } finally {
        inflight = null;
      }
    })();

    return inflight;
  };

  const triggerGc = async () => {
    if (get().isTriggeringGc) return false;
    set({ isTriggeringGc: true });
    try {
      const ok = await engineClient.triggerGc();
      set({
        isTriggeringGc: false,
        gcLastTriggeredAt: ok ? Date.now() : get().gcLastTriggeredAt,
      });
      if (ok) {
        void refreshNow();
      }
      return ok;
    } catch {
      set({ isTriggeringGc: false });
      return false;
    }
  };

  return {
    status: null,
    jobs: [],
    executors: [],
    applications: [],
    health: null,
    cpu: null,
    cpuCount: null,
    memoryUsed: null,
    memoryMax: null,
    samples: [],
    isTriggeringGc: false,
    gcLastTriggeredAt: null,
    isLoading: false,
    lastUpdatedAt: null,
    error: null,
    subscriberCount: 0,

    subscribe: () => {
      const next = get().subscriberCount + 1;
      set({ subscriberCount: next });
      if (next === 1) startPolling(refreshNow);
    },

    unsubscribe: () => {
      const next = Math.max(0, get().subscriberCount - 1);
      set({ subscriberCount: next });
      if (next === 0) stopPolling();
    },

    refreshNow,
    triggerGc,
  };
});
