import { useMemo } from "react";
import Lineage from "@/features/lineage/components/Lineage";
import { DocumentView } from "@/features/ontology-schema/components/DocumentView/DocumentView";
import type { TabComponent, TabRendererProps } from "@/shared/hooks/tabs/tabTypes";

export function useLineageTabRenderer(props: TabRendererProps): TabComponent | null {
  const { onToggleSidebar, sidebarVisible } = props;

  return useMemo(() => {
    if (props.activeTab === "document") {
      return {
        component: DocumentView,
        props: {},
      };
    }

    // "ontology" is a legacy alias for the graph view, now labelled "Ontology"
    // but still backed by the lineage id/plumbing. The ontology *schema* editor
    // lives inside the Document view now, not here.
    if (props.activeTab !== "ontology" && props.activeTab !== "lineage") {
      return null;
    }

    return {
      component: Lineage,
      props: {
        onToggleSidebar,
        sidebarVisible,
      },
    };
  }, [props.activeTab, onToggleSidebar, sidebarVisible]);
}
