/**
 * Utility functions for text formatting and wrapping
 */

/**
 * Formats text to wrap at a specified character limit per line
 * @param text - The text to format
 * @param charLimit - The maximum number of characters per line (default: 100)
 * @returns Formatted text with line breaks
 */
export const formatTextWithCharLimit = (text: string | null, charLimit: number = 100): string => {
  if (text === null || text === undefined) {
    return "";
  }

  const textStr = String(text);

  // If text is shorter than or equal to the limit, return as is
  if (textStr.length <= charLimit) {
    return textStr;
  }

  const lines: string[] = [];
  let currentIndex = 0;

  while (currentIndex < textStr.length) {
    // Extract a chunk of text up to the character limit
    let endIndex = currentIndex + charLimit;

    // If we're not at the end of the string, try to break at a space
    if (endIndex < textStr.length) {
      // Look backwards from the end position to find a space
      const lastSpaceIndex = textStr.lastIndexOf(" ", endIndex);

      // If we found a space within reasonable distance (at least 70% of the limit),
      // break there instead of mid-word
      if (lastSpaceIndex > currentIndex && lastSpaceIndex > currentIndex + charLimit * 0.7) {
        endIndex = lastSpaceIndex;
      }
    }

    // Add the line
    lines.push(textStr.substring(currentIndex, endIndex).trim());

    // Move to the next position
    currentIndex = endIndex;

    // Skip any leading spaces at the start of the next line
    while (currentIndex < textStr.length && textStr[currentIndex] === " ") {
      currentIndex++;
    }
  }

  return lines.join("\n");
};

/**
 * Truncates text to a specified length and adds ellipsis if needed
 * @param text - The text to truncate
 * @param maxLength - Maximum length before truncation
 * @returns The truncated text with ellipsis if needed
 */
export const truncateText = (text: string, maxLength: number): string => {
  if (!text || text.length <= maxLength) {
    return text;
  }
  return `${text.substring(0, maxLength)}...`;
};
