import { useQuery, useQueryClient } from "@tanstack/react-query";
import { AppWindow, Plus, Upload } from "lucide-react";
import { useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import ComputeIndicator from "@/features/compute/components/ComputeIndicator";
import {
  DashboardClient,
  DashboardValidationError,
} from "@/features/dynamic-dashboard/api/DashboardClient";
import type { DashboardDefinition } from "@/features/dynamic-dashboard/types";
import { GlobalSearchTrigger } from "@/features/global-search/components/GlobalSearchTrigger";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import SidePanel from "@/shared/components/layout/SidePanel";
import { Button } from "@/shared/components/ui/button";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";
import { AppsCatalog } from "./components/AppsCatalog";

const client = new DashboardClient();

/**
 * Storage project of an exported app file: v0 definitions keep it top-level
 * (`projectId`), v2 definitions carry it per page (`pages[].project.id`).
 */
function resolveStorageOntologyId(parsed: DashboardDefinition): string | undefined {
  if (parsed.ontologyId) return parsed.ontologyId;
  const page: unknown = parsed.pages?.[0];
  if (typeof page !== "object" || page === null || !("project" in page)) return undefined;
  const project = page.project;
  if (typeof project !== "object" || project === null || !("id" in project)) return undefined;
  return typeof project.id === "string" ? project.id : undefined;
}

/**
 * The one Apps catalog (ADR D10): dynamic apps (built in-platform, listed
 * for users with can_see/can_edit_dynamic_dashboards) and federated apps
 * (loaded at runtime per can_see_<id>_app) side by side, indistinguishable
 * to viewers. Editing affordances exist only for can_edit_dynamic_dashboards.
 */
export default function AppsListPage() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const importInputRef = useRef<HTMLInputElement>(null);

  const canSeeDynamicApps = usePermissionsStore((state) =>
    state.canSee("can_see_dynamic_dashboards"),
  );
  const canEditDynamicApps = usePermissionsStore((state) =>
    state.canEdit("can_edit_dynamic_dashboards"),
  );
  const visibleApps = usePermissionsStore((state) => state.visibleApps);
  const showDynamic = canSeeDynamicApps || canEditDynamicApps;

  const { data: dynamicApps = [] } = useQuery({
    queryKey: ["all-dashboards"],
    queryFn: () => client.listAllDashboards(),
    enabled: showDynamic,
  });

  const totalCount = (showDynamic ? dynamicApps.length : 0) + visibleApps.length;

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const parsed = JSON.parse(ev.target?.result as string) as DashboardDefinition;
        const storageOntologyId = resolveStorageOntologyId(parsed);
        if (!parsed.name || !Array.isArray(parsed.pages) || !storageOntologyId) {
          toast.error("Invalid app file — missing name, pages or ontology");
          return;
        }
        const withNewId: DashboardDefinition = {
          ...parsed,
          id: crypto.randomUUID(),
          ontologyId: storageOntologyId,
          createdAt: new Date().toISOString(),
        };
        client
          .saveDashboard(storageOntologyId, withNewId)
          .then(() => {
            queryClient.invalidateQueries({ queryKey: ["all-dashboards"] });
            toast.success(`App "${parsed.name}" imported`);
          })
          .catch((err: unknown) => {
            // Surface the validation reason (e.g. a concept that doesn't exist
            // in the target project) instead of a generic failure.
            const detail =
              err instanceof DashboardValidationError
                ? err.errors[0]
                : err instanceof Error
                  ? err.message
                  : undefined;
            toast.error(detail ? `Import failed — ${detail}` : "Failed to import the app");
          });
      } catch {
        toast.error("Failed to parse the app file");
      } finally {
        e.target.value = "";
      }
    };
    reader.readAsText(file);
  };

  const marginClass = sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0";

  const headerActions = (
    <>
      <ComputeIndicator interactive={true} />
      {canEditDynamicApps && (
        <>
          <input
            ref={importInputRef}
            type="file"
            accept=".json"
            className="hidden"
            onChange={handleImportFile}
          />
          <Button
            variant="outline"
            size="sm"
            className="gap-1.5 text-xs"
            onClick={() => importInputRef.current?.click()}
          >
            <Upload className="h-3.5 w-3.5" />
            Import
          </Button>
          <Button
            size="sm"
            className="gap-1.5 text-xs font-semibold uppercase tracking-wide"
            onClick={() => navigate("/apps/new/edit")}
          >
            <Plus className="h-3.5 w-3.5" />
            New App
          </Button>
        </>
      )}
    </>
  );

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab=""
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-col flex-1 min-w-0 ${marginClass} overflow-hidden transition-all duration-200`}
      >
        <PageHeader
          title="Apps"
          icon={AppWindow}
          subtitle={`${totalCount} app${totalCount !== 1 ? "s" : ""}`}
          actions={
            <>
              <GlobalSearchTrigger />
              {headerActions}
            </>
          }
        />
        <div className="flex-1 overflow-y-auto min-h-0">
          <AppsCatalog
            showDynamic={showDynamic}
            canEdit={canEditDynamicApps}
            dynamicApps={dynamicApps}
          />
        </div>
      </div>
    </div>
  );
}
