import { NotebookText } from "lucide-react";
import { useState } from "react";

import { GlobalSearchTrigger } from "@/features/global-search/components/GlobalSearchTrigger";
import { useOntologies } from "@/features/ontologies/hooks/useOntologies";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import SidePanel from "@/shared/components/layout/SidePanel";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";

import { ContextWorkspace } from "./ContextWorkspace";
import type { VaultRef } from "./notesModel";

export default function ContextPage() {
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  const { projects } = useOntologies();
  const ontologyVaults: VaultRef[] = projects.map((project) => ({
    scope: "ontology",
    scopeId: project.id,
    name: project.name,
  }));

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="context"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-1 flex-col ${sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0"} overflow-hidden transition-all duration-200`}
      >
        <PageHeader
          title="Context Management"
          subtitle="What your assistant knows — rules, knowledge, and documents"
          icon={NotebookText}
          actions={<GlobalSearchTrigger />}
        />

        <ContextWorkspace projectVaults={ontologyVaults} syncUrl />
      </div>
    </div>
  );
}
