import { format } from "date-fns";
import { ExternalLink, FileText, Receipt } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { InvoiceClient } from "@/features/billing/api/InvoiceClient";
import type { Invoice } from "@/features/billing/types";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Skeleton } from "@/shared/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/shared/components/ui/table";
import { InvoicePreviewDialog } from "./InvoicePreviewDialog";

export function UserInvoiceHistory() {
  const [searchQuery, setSearchQuery] = useState("");
  const [previewInvoice, setPreviewInvoice] = useState<Invoice | null>(null);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const client = new InvoiceClient();

  useEffect(() => {
    const fetchInvoices = async () => {
      try {
        setIsLoading(true);
        setError(null);
        const response = await client.getMyInvoices();

        if (response.status === "success") {
          setInvoices(response.data?.invoices || []);
        } else {
          setError(response.message || "Failed to load invoices");
        }
      } catch (err) {
        console.error("Error fetching invoices:", err);
        setError(err instanceof Error ? err.message : "Failed to load invoices");
      } finally {
        setIsLoading(false);
      }
    };

    fetchInvoices();
  }, [client.getMyInvoices]);

  const filteredInvoices = useMemo(() => {
    if (!invoices) return [];
    if (!searchQuery.trim()) return invoices;
    const query = searchQuery.toLowerCase();
    return invoices.filter(
      (inv) =>
        inv.invoice_number.toLowerCase().includes(query) ||
        inv.status.toLowerCase().includes(query) ||
        inv.total_amount.toString().includes(query),
    );
  }, [invoices, searchQuery]);

  const getStatusBadge = (status: string, paidAt: string | null) => {
    if (paidAt || status === "paid") {
      return <Badge className="bg-green-500/10 text-green-600">Paid</Badge>;
    }
    switch (status) {
      case "void":
      case "voided":
        return <Badge variant="secondary">Void</Badge>;
      case "sent":
        return <Badge variant="outline">Sent</Badge>;
      case "overdue":
      case "payment_failed":
        return (
          <Badge variant="destructive">{status === "overdue" ? "Overdue" : "Payment Failed"}</Badge>
        );
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  const totalAmount =
    invoices?.reduce(
      (sum, inv) => (inv.status !== "void" ? sum + Number(inv.total_amount) : sum),
      0,
    ) || 0;

  if (isLoading) {
    return (
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <Receipt className="h-5 w-5" />
          <h2 className="text-lg font-semibold">Invoice History</h2>
        </div>
        <Skeleton className="h-10 w-full" />
        <Skeleton className="h-10 w-full" />
        <Skeleton className="h-10 w-full" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <Receipt className="h-5 w-5" />
          <h2 className="text-lg font-semibold">Invoice History</h2>
        </div>
        <div className="flex flex-col items-center py-8">
          <FileText className="h-12 w-12 text-muted-foreground/50 mb-4" />
          <p className="text-muted-foreground">{error}</p>
        </div>
      </div>
    );
  }

  if (!invoices?.length) {
    return (
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <Receipt className="h-5 w-5" />
          <h2 className="text-lg font-semibold">Invoice History</h2>
        </div>
        <div className="flex flex-col items-center py-8">
          <FileText className="h-12 w-12 text-muted-foreground/50 mb-4" />
          <p className="text-muted-foreground">No invoices yet</p>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Receipt className="h-5 w-5" />
            <h2 className="text-lg font-semibold">Invoice History</h2>
            <Badge variant="secondary">{invoices.length}</Badge>
          </div>
          <span className="text-sm text-muted-foreground">
            Total: <span className="font-medium">${totalAmount.toFixed(2)}</span>
          </span>
        </div>

        <Input
          placeholder="Search invoices..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="max-w-sm"
        />

        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Invoice #</TableHead>
              <TableHead>Period</TableHead>
              <TableHead>Amount</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Sent</TableHead>
              <TableHead className="text-right">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredInvoices.map((invoice) => (
              <TableRow
                key={invoice.id}
                className={`cursor-pointer ${invoice.status === "void" ? "opacity-60" : ""}`}
                onClick={() => setPreviewInvoice(invoice)}
              >
                <TableCell className="font-medium">{invoice.invoice_number}</TableCell>
                <TableCell>
                  {format(new Date(invoice.period_from), "MMM d")} -{" "}
                  {format(new Date(invoice.period_to), "MMM d, yyyy")}
                </TableCell>
                <TableCell>${Number(invoice.total_amount).toFixed(2)}</TableCell>
                <TableCell>{getStatusBadge(invoice.status, invoice.paid_at)}</TableCell>
                <TableCell>{format(new Date(invoice.sent_at), "MMM d, yyyy")}</TableCell>
                <TableCell className="text-right">
                  <div onClick={(e) => e.stopPropagation()}>
                    {invoice.stripe_invoice_url && invoice.status !== "void" && (
                      <Button variant="ghost" size="sm" asChild>
                        <a
                          href={invoice.stripe_invoice_url}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          <ExternalLink className="h-4 w-4 mr-1" />
                          View
                        </a>
                      </Button>
                    )}
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      <InvoicePreviewDialog
        open={!!previewInvoice}
        onOpenChange={(open) => !open && setPreviewInvoice(null)}
        invoice={previewInvoice}
      />
    </>
  );
}
