import type { Extension } from "@codemirror/state";
import React from "react";
import type { SaveCellHandler } from "@/features/concept-editor/components/query/types/editorTypes";
import type { CellBinds } from "@/features/concept-editor/types";
import BindDataSelector from "./BindDataSelector";
import PolicySection from "./policies/PolicySection";

interface CellSettingsProps {
  cellId: string;
  showDataEditor: boolean;
  onToggleDataEditor: () => void;
  isRunning: boolean;
  extensions: Extension[];
  editorTheme: "light";
  onCodeChange?: (value: string, cellId?: string) => void;
  onRunCell?: (cellId: string) => void;
  onSaveCell?: SaveCellHandler;
  code?: string;
  outputPredicate?: string;
  showBindEditor?: boolean;
  binds?: CellBinds;
  onBindsChange?: (binds: CellBinds) => void;
  conceptType?: "logic" | "sql" | "cypher" | "python" | "context" | "llm";
  onBoundPredicatesChange?: (signatures: { label: string; apply: string; info: string }[]) => void;
  conceptName?: string;
  fillHeight?: boolean;
}

const CellSettings: React.FC<CellSettingsProps> = ({
  cellId,
  showDataEditor,
  code,
  outputPredicate,
  showBindEditor = false,
  binds,
  onBindsChange,
  conceptType = "logic",
  onBoundPredicatesChange,
  conceptName,
  fillHeight = false,
}) => {
  if (!showDataEditor) return null;

  return (
    <div
      className={`cell-settings-pane w-full p-2 bg-muted/50 border-t border-border/50 flex flex-col gap-2 ${
        fillHeight ? "min-h-0 overflow-y-auto" : ""
      }`}
    >
      <div className="flex flex-col flex-1">
        {/* Bind Data Selector */}
        {showBindEditor && onBindsChange && binds && (
          <div className="mb-4 px-4 pt-2">
            <BindDataSelector
              cellId={cellId}
              code={code || ""}
              outputPredicate={outputPredicate}
              binds={binds}
              onBindsChange={onBindsChange}
              conceptType={conceptType}
              onBoundPredicatesChange={onBoundPredicatesChange}
            />
          </div>
        )}

        {/* Evaluation Policies Section — only in settings view, not bind editor */}
        {!showBindEditor && conceptName && <PolicySection conceptName={conceptName} />}
      </div>
    </div>
  );
};

// Custom comparison function to prevent unnecessary re-renders
const arePropsEqual = (prevProps: CellSettingsProps, nextProps: CellSettingsProps) => {
  return (
    prevProps.cellId === nextProps.cellId &&
    prevProps.showDataEditor === nextProps.showDataEditor &&
    prevProps.isRunning === nextProps.isRunning &&
    prevProps.editorTheme === nextProps.editorTheme &&
    prevProps.showBindEditor === nextProps.showBindEditor &&
    prevProps.conceptType === nextProps.conceptType &&
    prevProps.binds === nextProps.binds &&
    prevProps.code === nextProps.code &&
    prevProps.outputPredicate === nextProps.outputPredicate &&
    prevProps.onBoundPredicatesChange === nextProps.onBoundPredicatesChange &&
    prevProps.conceptName === nextProps.conceptName &&
    prevProps.fillHeight === nextProps.fillHeight
  );
};

export default React.memo(CellSettings, arePropsEqual);
