import { Trash2, Unlink, X } from "lucide-react";
import { useMemo, useState } from "react";

import { Button } from "@/shared/components/ui/button";

import { NoteMarkdownEditor } from "../notes/components/NoteMarkdownEditor";
import { buildLinkTargets, editorDisplayTitle } from "../notes/notesModel";
import type { ContextNote } from "../types";

interface AttachedNoteEditorProps {
  /** null = drafting a brand-new note for this concept. */
  note: ContextNote | null;
  /** Wikilink autocomplete candidates (workspace notes). */
  linkCandidates: ContextNote[];
  onSave: (text: string) => Promise<void>;
  onDetach?: () => void;
  /** Delete the note entirely (callers confirm first). */
  onDelete?: () => void;
  onClose: () => void;
  isSaving: boolean;
}

/** In-place editor for an attached note (or a new-note draft) inside the
 *  concept Context tab. Markdown + `[[` wikilinks, same as the notes page. */
export function AttachedNoteEditor({
  note,
  linkCandidates,
  onSave,
  onDetach,
  onDelete,
  onClose,
  isSaving,
}: AttachedNoteEditorProps) {
  const [text, setText] = useState(note?.text ?? "");
  const isDirty = text !== (note?.text ?? "");
  const canSave = isDirty && text.trim().length > 0 && !isSaving;

  const linkTargets = useMemo(
    () => buildLinkTargets(linkCandidates, note?.id),
    [linkCandidates, note?.id],
  );

  const handleSave = async () => {
    if (!canSave) return;
    await onSave(text);
  };

  const title = note ? editorDisplayTitle(note, text) : "New note";

  return (
    <div className="flex h-full min-h-0 flex-col rounded-md border border-border bg-card">
      <div className="flex items-center justify-between gap-2 border-b border-border px-3 py-1.5">
        <span className="truncate text-sm font-medium text-foreground">{title}</span>
        <div className="flex items-center gap-1">
          {note && onDetach && (
            <Button
              variant="ghost"
              size="sm"
              className="h-7 gap-1 text-xs text-muted-foreground"
              onClick={onDetach}
              title="Remove the link to this concept (the note itself is kept)"
            >
              <Unlink className="h-3.5 w-3.5" />
              Detach
            </Button>
          )}
          {note && onDelete && (
            <Button
              variant="ghost"
              size="sm"
              className="h-7 gap-1 text-xs text-muted-foreground hover:text-destructive"
              onClick={onDelete}
              title="Delete this note"
            >
              <Trash2 className="h-3.5 w-3.5" />
              Delete
            </Button>
          )}
          <Button variant="ghost" size="sm" className="h-7 w-7 p-0" onClick={onClose}>
            <X className="h-3.5 w-3.5" />
          </Button>
        </div>
      </div>
      <div className="min-h-0 flex-1 overflow-auto">
        <NoteMarkdownEditor
          value={text}
          onChange={setText}
          getLinkCandidates={() => linkTargets}
          onSave={handleSave}
          autoFocus
        />
      </div>
      <div className="flex items-center justify-end gap-2 border-t border-border px-3 py-1.5">
        <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onClose}>
          Cancel
        </Button>
        <Button size="sm" className="h-7 text-xs" onClick={handleSave} disabled={!canSave}>
          {isSaving ? "Saving…" : "Save"}
        </Button>
      </div>
    </div>
  );
}
