import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { useConceptEditorClient } from "@/features/concept-editor/api/ConceptEditorClientContext";
import type {
  CronTriggerConfig,
  DataChangeTriggerConfig,
  EvaluationPolicy,
  TriggerType,
} from "@/features/concept-editor/types";

type TriggerConfig = CronTriggerConfig | DataChangeTriggerConfig;

interface UseConceptPoliciesReturn {
  policies: EvaluationPolicy[];
  isLoading: boolean;
  error: Error | null;
  createPolicy: (triggerType: TriggerType, config: TriggerConfig) => Promise<void>;
  updatePolicy: (
    policyId: string,
    patch: { trigger_config?: TriggerConfig; enabled?: boolean },
  ) => Promise<void>;
  deletePolicy: (policyId: string) => Promise<void>;
  triggerPolicy: (policyId: string) => Promise<void>;
  refresh: () => Promise<void>;
}

export function useConceptPolicies(conceptName: string | undefined): UseConceptPoliciesReturn {
  const [policies, setPolicies] = useState<EvaluationPolicy[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const client = useConceptEditorClient();

  const refresh = useCallback(async () => {
    if (!conceptName) return;
    setIsLoading(true);
    setError(null);
    try {
      const data = await client.listPolicies(conceptName);
      setPolicies(data);
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
    } finally {
      setIsLoading(false);
    }
  }, [conceptName, client]);

  useEffect(() => {
    refresh();
    const interval = setInterval(refresh, 30_000);
    return () => clearInterval(interval);
  }, [refresh]);

  const createPolicy = useCallback(
    async (triggerType: TriggerType, config: TriggerConfig) => {
      if (!conceptName) return;
      try {
        await client.createPolicy(conceptName, triggerType, config);
        toast.success("Policy created");
        await refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        toast.error(`Failed to create policy: ${msg}`);
        throw err;
      }
    },
    [conceptName, client, refresh],
  );

  const updatePolicy = useCallback(
    async (policyId: string, patch: { trigger_config?: TriggerConfig; enabled?: boolean }) => {
      try {
        await client.updatePolicy(policyId, patch);
        toast.success("Policy updated");
        await refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        toast.error(`Failed to update policy: ${msg}`);
        throw err;
      }
    },
    [client, refresh],
  );

  const deletePolicy = useCallback(
    async (policyId: string) => {
      try {
        await client.deletePolicy(policyId);
        toast.success("Policy deleted");
        await refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        toast.error(`Failed to delete policy: ${msg}`);
        throw err;
      }
    },
    [client, refresh],
  );

  const triggerPolicy = useCallback(
    async (policyId: string) => {
      try {
        await client.triggerPolicy(policyId);
        toast.success("Policy triggered");
        setTimeout(refresh, 2_000);
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        toast.error(`Failed to trigger policy: ${msg}`);
        throw err;
      }
    },
    [client, refresh],
  );

  return {
    policies,
    isLoading,
    error,
    createPolicy,
    updatePolicy,
    deletePolicy,
    triggerPolicy,
    refresh,
  };
}
