import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { useConcepts } from "@/features/concepts/hooks/useConcepts";
import { VisualizationService } from "@/features/lineage/api";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";
import { APP_EVENTS } from "@/shared/constants/events";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";
import { useReconnectExecutionStatus } from "../hooks/useReconnectExecutionStatus";
import { LastRunNotice } from "./LastRunNotice";
import LineageView from "./LineageView";

interface LineageProps {
  onToggleSidebar?: () => void;
  sidebarVisible?: boolean;
  topLeftControls?: React.ReactNode;
}

const Lineage: React.FC<LineageProps> = ({ onToggleSidebar, sidebarVisible, topLeftControls }) => {
  const [visualizationData, setVisualizationData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [focusConceptName, setFocusConceptName] = useState<string | null>(null);

  // Isolated upstream-slice mode: when set, every fetch (including incidental
  // refreshes) returns only this concept + its upstream dependencies. Kept in a
  // ref too so the event-driven refetches below preserve the slice.
  const [isolatedConcept, setIsolatedConcept] = useState<string | null>(null);
  const isolatedConceptRef = useRef<string | null>(null);

  const isManualRefreshRef = React.useRef(false);

  const ontologyId = useOntologyId();
  const ontologyScope = useOntologyScope();

  const { concepts, loadConcepts } = useConcepts();

  // Accessible concept set for the current scoped session. Hidden concepts are
  // absent here, so any lineage node not in this set is reconciled into a
  // "Restricted concept" placeholder (see LineageView / markRestrictedNodes).
  const accessibleConcepts = useMemo(
    () => new Set(concepts.map((c) => c.predicate_name)),
    [concepts],
  );

  // Recover the latest run's progress/outcome when returning to this tab. The
  // hook publishes in-flight per-concept statuses to the lineage run-status
  // store (consumed by the graph view); here we use the snapshot for the notice.
  const { snapshot: lastRunSnapshot } = useReconnectExecutionStatus(ontologyId, ontologyScope);

  const ontologySchemaRevision = useCodeAssistantStore((s) => s.ontologySchemaRevision);
  const prevOntologySchemaRevisionRef = useRef(ontologySchemaRevision);

  const fetchConceptLineage = useCallback(
    async (silent = false) => {
      if (!ontologyId) return;

      if (!silent) setIsLoading(true);
      try {
        const response = await VisualizationService.visualizeConceptLineage(
          ontologyId,
          ontologyScope,
          isolatedConceptRef.current,
        );
        if (response && response.status === "success") {
          setVisualizationData(response);
        }
      } catch (error) {
        console.error("Failed to fetch concept lineage:", error);
      } finally {
        if (!silent) setIsLoading(false);
      }
    },
    [ontologyId, ontologyScope],
  );

  // Fetch on mount and when the project changes.
  // visualizationData intentionally excluded: it changes after every fetch,
  // which would create an infinite request loop.
  useEffect(() => {
    if (ontologyId) fetchConceptLineage();
  }, [ontologyId, fetchConceptLineage]);

  // Refetch when the AI assistant creates or updates a concept.
  useEffect(() => {
    if (prevOntologySchemaRevisionRef.current === ontologySchemaRevision) return;
    prevOntologySchemaRevisionRef.current = ontologySchemaRevision;
    if (ontologyId) fetchConceptLineage(true);
  }, [ontologySchemaRevision, ontologyId, fetchConceptLineage]);

  useEffect(() => {
    const handleLineageTabActivated = async () => {
      if (ontologyId) await fetchConceptLineage();
    };
    window.addEventListener("lineageTabActivated", handleLineageTabActivated);
    return () => window.removeEventListener("lineageTabActivated", handleLineageTabActivated);
  }, [ontologyId, fetchConceptLineage]);

  // Refetch when a concept's group is created/renamed/removed in the Explorer,
  // so the "Groups" legend stays in sync without a page refresh. Silent so the
  // canvas doesn't flash the loading spinner.
  useEffect(() => {
    const handleGroupsChanged = () => {
      if (ontologyId) void fetchConceptLineage(true);
    };
    window.addEventListener(APP_EVENTS.CONCEPT_GROUPS_CHANGED, handleGroupsChanged);
    return () => window.removeEventListener(APP_EVENTS.CONCEPT_GROUPS_CHANGED, handleGroupsChanged);
  }, [ontologyId, fetchConceptLineage]);

  useEffect(() => {
    const handleFocusConcept = async (e: Event) => {
      const name = (e as CustomEvent).detail?.conceptName;
      if (ontologyId) {
        await fetchConceptLineage();
        if (name) setFocusConceptName(name);
      }
    };
    window.addEventListener("lineageFocusConcept", handleFocusConcept);
    return () => window.removeEventListener("lineageFocusConcept", handleFocusConcept);
  }, [ontologyId, fetchConceptLineage]);

  // Cross-view focus from the Document tab: clicking a predicate chip there
  // sets `pendingLineageFocus` on the editor-actions store and dispatches
  // switchTab to "lineage". By the time this wrapper mounts (or re-renders
  // for a project change), we consume the value, route it through the same
  // focusConceptName path the lineageFocusConcept window event uses, and
  // clear it so it can't refire.
  const pendingLineageFocus = useEditorActionsStore((s) => s.pendingLineageFocus);
  useEffect(() => {
    if (!pendingLineageFocus || !ontologyId) return;
    setFocusConceptName(pendingLineageFocus);
    useEditorActionsStore.getState().register({ pendingLineageFocus: null });
  }, [pendingLineageFocus, ontologyId]);

  // Isolate a concept's upstream dependency slice (re-fetches + re-renders).
  const handleIsolateConcept = useCallback(
    (conceptName: string) => {
      if (!conceptName) return;
      setIsolatedConcept(conceptName);
      isolatedConceptRef.current = conceptName;
      void fetchConceptLineage(true);
    },
    [fetchConceptLineage],
  );

  // Clear isolation and return to the full lineage.
  const handleClearIsolation = useCallback(() => {
    setIsolatedConcept(null);
    isolatedConceptRef.current = null;
    void fetchConceptLineage(true);
  }, [fetchConceptLineage]);

  const handleFullRefresh = useCallback(async () => {
    if (!ontologyId) return;

    try {
      isManualRefreshRef.current = true;
      await loadConcepts(true);
      await fetchConceptLineage(true);
    } catch (error) {
      console.error("Error during full refresh:", error);
      toast.error("Failed to refresh lineage");
    } finally {
      isManualRefreshRef.current = false;
    }
  }, [ontologyId, loadConcepts, fetchConceptLineage]);

  return (
    <div className="relative h-full overflow-hidden">
      <LastRunNotice snapshot={lastRunSnapshot} />
      <LineageView
        data={visualizationData}
        accessibleConcepts={accessibleConcepts}
        isLineageLoading={isLoading}
        onToggleSidebar={onToggleSidebar}
        sidebarVisible={sidebarVisible}
        topLeftControls={topLeftControls}
        onRefreshLineage={handleFullRefresh}
        focusConceptName={focusConceptName}
        onFocusConsumed={() => setFocusConceptName(null)}
        isolatedConcept={isolatedConcept}
        onIsolateConcept={handleIsolateConcept}
        onClearIsolation={handleClearIsolation}
      />
    </div>
  );
};

export default React.memo(Lineage);
