import { useEffect, useState } from "react";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Switch } from "@/shared/components/ui/switch";
import { Textarea } from "@/shared/components/ui/textarea";
import { InfoHint } from "../InfoHint";

/**
 * Small labeled controls for the inspector. Every control is fully
 * controlled from the draft; "empty" consistently maps to undefined so
 * micro-edits never litter the definition with empty strings.
 */

interface FieldRowProps {
  label: string;
  /** Optional ⓘ tooltip beside the label. */
  hint?: string;
  children: React.ReactNode;
}

export function FieldRow({ label, hint, children }: FieldRowProps) {
  return (
    <div className="flex flex-col gap-1">
      <span className="flex items-center gap-1 text-[10px] font-medium text-muted-foreground">
        {label}
        {hint && <InfoHint text={hint} />}
      </span>
      {children}
    </div>
  );
}

interface TextFieldProps {
  label: string;
  value: string | undefined;
  onChange: (value: string | undefined) => void;
  placeholder?: string;
  hint?: string;
}

export function TextField({ label, value, onChange, placeholder, hint }: TextFieldProps) {
  return (
    <FieldRow label={label} hint={hint}>
      <Input
        value={value ?? ""}
        placeholder={placeholder}
        onChange={(event) => onChange(event.target.value || undefined)}
        className="h-7 text-xs"
      />
    </FieldRow>
  );
}

interface TextAreaFieldProps {
  label: string;
  value: string | undefined;
  onChange: (value: string | undefined) => void;
  rows?: number;
}

export function TextAreaField({ label, value, onChange, rows = 4 }: TextAreaFieldProps) {
  return (
    <FieldRow label={label}>
      <Textarea
        value={value ?? ""}
        rows={rows}
        onChange={(event) => onChange(event.target.value || undefined)}
        className="text-xs font-mono"
      />
    </FieldRow>
  );
}

interface NumberFieldProps {
  label: string;
  value: number | undefined;
  onChange: (value: number | undefined) => void;
  min?: number;
  max?: number;
  hint?: string;
}

export function NumberField({ label, value, onChange, min, max, hint }: NumberFieldProps) {
  const handleChange = (raw: string) => {
    if (raw === "") return onChange(undefined);
    const parsed = Number(raw);
    if (!Number.isNaN(parsed)) onChange(parsed);
  };
  return (
    <FieldRow label={label} hint={hint}>
      <Input
        type="number"
        value={value ?? ""}
        min={min}
        max={max}
        onChange={(event) => handleChange(event.target.value)}
        className="h-7 text-xs"
      />
    </FieldRow>
  );
}

export interface SelectOption {
  value: string;
  label: string;
}

interface SelectFieldProps {
  label: string;
  value: string | undefined;
  onChange: (value: string | undefined) => void;
  options: SelectOption[];
  /** Adds a "none" entry mapping to undefined. */
  allowNone?: boolean;
  hint?: string;
}

const NONE_VALUE = "__none__";

export function SelectField({
  label,
  value,
  onChange,
  options,
  allowNone,
  hint,
}: SelectFieldProps) {
  return (
    <FieldRow label={label} hint={hint}>
      <Select
        value={value ?? (allowNone ? NONE_VALUE : "")}
        onValueChange={(next) => onChange(next === NONE_VALUE ? undefined : next)}
      >
        <SelectTrigger className="h-7 text-xs">
          <SelectValue placeholder="—" />
        </SelectTrigger>
        <SelectContent>
          {allowNone && (
            <SelectItem value={NONE_VALUE} className="text-xs text-muted-foreground">
              — none —
            </SelectItem>
          )}
          {options.map((option) => (
            <SelectItem key={option.value} value={option.value} className="text-xs">
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </FieldRow>
  );
}

interface CsvFieldProps {
  label: string;
  value: string[] | undefined;
  onChange: (value: string[] | undefined) => void;
  placeholder?: string;
  hint?: string;
}

/** Comma-separated list ↔ string[]; empty clears the property. */
export function CsvField({ label, value, onChange, placeholder, hint }: CsvFieldProps) {
  const [text, setText] = useState((value ?? []).join(", "));

  useEffect(() => {
    setText((value ?? []).join(", "));
  }, [value]);

  const commit = () => {
    const items = text
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
    onChange(items.length > 0 ? items : undefined);
  };

  return (
    <FieldRow label={label} hint={hint}>
      <Input
        value={text}
        placeholder={placeholder}
        onChange={(event) => setText(event.target.value)}
        onBlur={commit}
        className="h-7 text-xs font-mono"
      />
    </FieldRow>
  );
}

interface BoolFieldProps {
  label: string;
  value: boolean | undefined;
  onChange: (value: boolean | undefined) => void;
}

export function BoolField({ label, value, onChange }: BoolFieldProps) {
  return (
    <div className="flex items-center justify-between gap-2">
      <span className="text-[10px] font-medium text-muted-foreground">{label}</span>
      <Switch
        checked={value ?? false}
        onCheckedChange={(checked) => onChange(checked || undefined)}
      />
    </div>
  );
}

interface JsonFieldProps {
  label: string;
  value: unknown;
  onChange: (value: unknown) => void;
  rows?: number;
  hint?: string;
  /** Example shown while the field is empty. */
  placeholder?: string;
}

/**
 * Escape hatch for nested structures (formatRules, form sections, actions):
 * raw JSON, parsed and applied on blur. Server-side validation still owns
 * structural correctness at save time.
 */
export function JsonField({ label, value, onChange, rows = 5, hint, placeholder }: JsonFieldProps) {
  const serialize = (input: unknown) => (input === undefined ? "" : JSON.stringify(input, null, 2));
  const [text, setText] = useState(() => serialize(value));
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setText(serialize(value));
    setError(null);
  }, [value]);

  const commit = () => {
    if (text.trim() === "") {
      setError(null);
      onChange(undefined);
      return;
    }
    try {
      onChange(JSON.parse(text));
      setError(null);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Invalid JSON");
    }
  };

  return (
    <FieldRow label={label} hint={hint}>
      <Textarea
        value={text}
        rows={rows}
        spellCheck={false}
        placeholder={placeholder}
        onChange={(event) => setText(event.target.value)}
        onBlur={commit}
        className="text-[11px] font-mono leading-relaxed placeholder:text-muted-foreground/50"
      />
      {error && <span className="text-[10px] text-destructive">Invalid JSON: {error}</span>}
    </FieldRow>
  );
}
