import { zodResolver } from "@hookform/resolvers/zod";
import { useQueryClient } from "@tanstack/react-query";
import { Lock } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import { z } from "zod";
import { useAvatarManagement } from "@/features/settings/hooks/useAvatarManagement";
import { useAvatarSrc } from "@/features/settings/hooks/useAvatarSrc";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import { supabase } from "@/shared/integrations/supabase/client";
import { AvatarUpload } from "./AvatarUpload";

const profileFormSchema = z.object({
  email: z.string().email(),
  username: z.string().min(1, "Username is required").optional(),
  first_name: z.string().optional(),
  last_name: z.string().optional(),
  organization: z.string().optional(),
});

type ProfileFormData = z.infer<typeof profileFormSchema>;

interface UserProfileFormProps {
  currentUser?: any;
  onSuccess: () => void;
}

export const UserProfileForm: React.FC<UserProfileFormProps> = ({ currentUser, onSuccess }) => {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [pendingAvatarFile, setPendingAvatarFile] = useState<File | null>(null);
  const queryClient = useQueryClient();

  const { changeAvatar, removeAvatar, isUploading, isDeleting } = useAvatarManagement();
  const avatarSrc = useAvatarSrc(currentUser?.avatar_url);

  const form = useForm<ProfileFormData>({
    resolver: zodResolver(profileFormSchema),
    defaultValues: {
      email: currentUser?.email || "",
      username: currentUser?.username || "",
      first_name: currentUser?.first_name || "",
      last_name: currentUser?.last_name || "",
      organization: currentUser?.organization || "",
    },
  });

  const onSubmit = async (data: ProfileFormData) => {
    setIsSubmitting(true);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) throw new Error("No user found");

      // Handle avatar upload if there's a pending file
      let newAvatarUrl: string | null = null;
      if (pendingAvatarFile) {
        newAvatarUrl = await changeAvatar(pendingAvatarFile, user.id, currentUser?.avatar_url);

        if (!newAvatarUrl) {
          // Avatar upload failed, but we can continue with other updates
          toast.error("Avatar upload failed, but other changes will be saved");
        }
      }

      // Only update fields that are allowed to be changed
      const updateData: any = {};

      // Always allow first_name and last_name
      if (data.first_name !== undefined) updateData.first_name = data.first_name;
      if (data.last_name !== undefined) updateData.last_name = data.last_name;

      // Only allow username and organization if they're currently null/empty
      if (!currentUser?.username && data.username) {
        updateData.username = data.username;
      }
      if (!currentUser?.organization && data.organization) {
        updateData.organization = data.organization;
      }

      // Update profiles table
      const { error: profileError } = await supabase
        .from("profiles")
        .update(updateData)
        .eq("id", user.id);

      if (profileError) throw profileError;

      // Also update auth user metadata for first_name and last_name
      if (data.first_name !== undefined || data.last_name !== undefined) {
        const metadataUpdate: any = {};
        if (data.first_name !== undefined) metadataUpdate.first_name = data.first_name;
        if (data.last_name !== undefined) metadataUpdate.last_name = data.last_name;

        const { error: metadataError } = await supabase.auth.updateUser({
          data: metadataUpdate,
        });

        if (metadataError) {
          // Don't throw error - profile update succeeded
        }
      }

      // Invalidate the profile query to refresh the data
      await queryClient.invalidateQueries({ queryKey: ["profile", user.id] });

      // Clear pending avatar file
      setPendingAvatarFile(null);

      toast.success("Profile updated successfully");
      onSuccess();
    } catch (error: any) {
      console.error("Error updating profile:", error);
      toast.error(`Failed to update profile: ${error.message}`);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleAvatarChange = (file: File) => {
    setPendingAvatarFile(file);
  };

  const handleAvatarRemove = async () => {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) throw new Error("No user found");

      if (currentUser?.avatar_url) {
        const success = await removeAvatar(user.id, currentUser.avatar_url);
        if (success) {
          // Invalidate queries to refresh the UI
          await queryClient.invalidateQueries({ queryKey: ["profile", user.id] });
        }
      }

      // Clear any pending avatar file
      setPendingAvatarFile(null);
    } catch (error: any) {
      console.error("Error removing avatar:", error);
      toast.error("Failed to remove avatar");
    }
  };

  const isUsernameLocked = !!currentUser?.username;
  const isOrganizationLocked = !!currentUser?.organization;

  // Get user's display name for avatar
  const displayName =
    currentUser?.first_name && currentUser?.last_name
      ? `${currentUser.first_name} ${currentUser.last_name}`
      : currentUser?.username || currentUser?.email || "User";

  return (
    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
      <div className="space-y-4">
        {/* Avatar Upload Section */}
        <AvatarUpload
          currentAvatarUrl={avatarSrc}
          onAvatarChange={handleAvatarChange}
          onAvatarRemove={handleAvatarRemove}
          isUploading={isUploading}
          isDeleting={isDeleting}
          userName={displayName}
          disabled={isSubmitting}
        />

        {/* Email field - read-only */}
        <div className="space-y-2">
          <Label htmlFor="email">Email</Label>
          <Input
            id="email"
            type="email"
            value={form.watch("email")}
            disabled
            className="bg-muted"
          />
          <p className="text-sm text-muted-foreground">Email cannot be changed</p>
        </div>

        {/* Username field */}
        <div className="space-y-2">
          <Label htmlFor="username" className="flex items-center gap-2">
            Username
            {isUsernameLocked && <Lock className="h-3 w-3 text-muted-foreground" />}
          </Label>
          <Input
            id="username"
            {...form.register("username")}
            disabled={isUsernameLocked}
            className={isUsernameLocked ? "bg-muted" : ""}
          />
          {isUsernameLocked ? (
            <p className="text-sm text-muted-foreground">Username cannot be changed once set</p>
          ) : (
            <p className="text-sm text-muted-foreground">
              Choose a unique username (cannot be changed later)
            </p>
          )}
          {form.formState.errors.username && (
            <p className="text-sm text-destructive">{form.formState.errors.username.message}</p>
          )}
        </div>

        {/* First Name field */}
        <div className="space-y-2">
          <Label htmlFor="first_name">First Name</Label>
          <Input id="first_name" {...form.register("first_name")} />
          {form.formState.errors.first_name && (
            <p className="text-sm text-destructive">{form.formState.errors.first_name.message}</p>
          )}
        </div>

        {/* Last Name field */}
        <div className="space-y-2">
          <Label htmlFor="last_name">Last Name</Label>
          <Input id="last_name" {...form.register("last_name")} />
          {form.formState.errors.last_name && (
            <p className="text-sm text-destructive">{form.formState.errors.last_name.message}</p>
          )}
        </div>

        {/* Organization field */}
        <div className="space-y-2">
          <Label htmlFor="organization" className="flex items-center gap-2">
            Organization
            {isOrganizationLocked && <Lock className="h-3 w-3 text-muted-foreground" />}
          </Label>
          <Input
            id="organization"
            {...form.register("organization")}
            disabled={isOrganizationLocked}
            className={isOrganizationLocked ? "bg-muted" : ""}
          />
          {isOrganizationLocked ? (
            <p className="text-sm text-muted-foreground">Organization cannot be changed once set</p>
          ) : (
            <p className="text-sm text-muted-foreground">
              Your organization (cannot be changed later)
            </p>
          )}
          {form.formState.errors.organization && (
            <p className="text-sm text-destructive">{form.formState.errors.organization.message}</p>
          )}
        </div>
      </div>

      <div className="flex justify-end space-x-2">
        <Button type="submit" disabled={isSubmitting || isUploading || isDeleting}>
          {isSubmitting ? "Saving..." : "Save Changes"}
        </Button>
      </div>
    </form>
  );
};
