import { Loader2 } from "lucide-react";
import type React from "react";
import { useMemo } from "react";
import { useMyTeams } from "@/features/teams/hooks/useMyTeams";
import { useTeamsMembers } from "@/features/teams/hooks/useTeamsMembers";
import { useConceptRestrictions } from "../hooks/useConceptRestrictions";
import { useSharedOntologyContext } from "../hooks/useSharedOntologyContext";
import { useShareOutbox } from "../hooks/useShareOutbox";
import { OWNER_CALLER, type PermissionCaller, type ShareRole } from "../types";
import { normalizeLevel } from "../utils/conceptAccess.utils";
import { MemberRoleRow, TeamRoleRow } from "./OntologyRoleRows";
import RosterMemberSection, { type RosterSectionItem } from "./RosterMemberSection";

interface OntologyAccessRosterProps {
  ontologyId: string;
  caller?: PermissionCaller;
  // Project owner id — shown as a static "full access" row, never editable.
  ownerSub?: string;
  // When provided, member/team rows expose a dropdown to change the base role.
  onSetMemberRole?: (recipientSub: string, role: ShareRole) => void | Promise<void>;
  onClearMemberRole?: (recipientSub: string) => void | Promise<void>;
  onSetTeamRole?: (teamId: string, role: ShareRole) => void | Promise<void>;
  isBusy?: boolean;
}

interface OntologyRecipient {
  sub: string;
  label: string;
  directRole?: ShareRole;
  // The recipient team this user belongs to (a team the ontology is shared
  // with), used to annotate their row with "via <team>".
  teamId?: string;
  teamBaseRole?: ShareRole;
}

// Project-level access roster: the shared team(s) and every member with their
// effective base role, mirroring the concept roster's layout. Setting a level
// writes a project-scope override (member) or the team base role (team).
const OntologyAccessRoster: React.FC<OntologyAccessRosterProps> = ({
  ontologyId,
  caller = OWNER_CALLER,
  ownerSub,
  onSetMemberRole,
  onClearMemberRole,
  onSetTeamRole,
  isBusy = false,
}) => {
  const { teams: myTeams } = useMyTeams();
  const { entries: outboxEntries } = useShareOutbox({ ontologyId });
  const { restrictions } = useConceptRestrictions({ ontologyId, caller });
  const { shareRole: contextShareRole, sharedBy } = useSharedOntologyContext();

  const teamBaseFallback: ShareRole =
    caller.mode === "team_admin" ? (contextShareRole ?? "viewer") : "viewer";

  const sharedTeamIds = useMemo(() => {
    if (caller.mode === "team_admin") return [caller.teamId];
    return outboxEntries
      .filter((e) => e.share_type === "team")
      .map((e) => e.recipient_team_id ?? e.team_id)
      .filter((id): id is string => Boolean(id));
  }, [caller, outboxEntries]);

  const { members: teamMembers, isLoading } = useTeamsMembers(sharedTeamIds);

  const teamRows = useMemo(() => {
    const map = new Map<string, { id: string; name: string; baseRole: ShareRole }>();
    if (caller.mode === "team_admin") {
      const t = myTeams.find((x) => x.id === caller.teamId);
      map.set(caller.teamId, {
        id: caller.teamId,
        name: t?.name ?? "Team",
        baseRole: contextShareRole ?? "viewer",
      });
      return [...map.values()];
    }
    for (const e of outboxEntries) {
      if (e.share_type !== "team") continue;
      const id = e.recipient_team_id ?? e.team_id;
      if (!id) continue;
      map.set(id, { id, name: e.team_name ?? "Team", baseRole: e.share_role });
    }
    return [...map.values()];
  }, [caller, myTeams, contextShareRole, outboxEntries]);

  const recipients = useMemo<OntologyRecipient[]>(() => {
    const bySub = new Map<string, OntologyRecipient>();

    const teamBaseByTeam = new Map<string, ShareRole>();
    for (const e of outboxEntries) {
      const teamId = e.recipient_team_id ?? e.team_id;
      if (e.share_type === "team" && teamId) teamBaseByTeam.set(teamId, e.share_role);
    }

    for (const e of outboxEntries) {
      if (e.share_type === "team") continue;
      if (e.status !== "accepted" && e.status !== "pending") continue;
      if (e.recipient_sub === ownerSub) continue;
      bySub.set(e.recipient_sub, {
        sub: e.recipient_sub,
        label: `${e.recipient_username}@${e.recipient_organization}`,
        directRole: e.share_role,
      });
    }

    for (const m of teamMembers) {
      if (m.status !== "active" || m.user_id === ownerSub) continue;
      const teamBaseRole = teamBaseByTeam.get(m.teamId) ?? teamBaseFallback;
      const existing = bySub.get(m.user_id);
      if (existing) {
        existing.teamId = m.teamId;
        existing.teamBaseRole = teamBaseRole;
        continue;
      }
      bySub.set(m.user_id, {
        sub: m.user_id,
        label: `${m.username}@${m.organization}`,
        teamId: m.teamId,
        teamBaseRole,
      });
    }

    return [...bySub.values()];
  }, [outboxEntries, teamMembers, ownerSub, teamBaseFallback]);

  // Explicit per-member project override, keyed by sub (read_write→editor).
  const overrideBySub = useMemo(() => {
    const map = new Map<string, ShareRole>();
    for (const r of restrictions) {
      if (r.scope !== "ontology" || r.subject_type !== "user") continue;
      map.set(
        r.recipient_sub ?? r.subject_id,
        normalizeLevel(r.level) === "read_write" ? "editor" : "viewer",
      );
    }
    return map;
  }, [restrictions]);

  // A member with no direct share is only listed because they belong to a
  // shared team — annotate their row with "via <team>" rather than presenting
  // them as an individual share.
  const teamNameById = useMemo(() => {
    const map = new Map<string, string>();
    for (const t of teamRows) map.set(t.id, t.name);
    return map;
  }, [teamRows]);

  const memberRows = useMemo(() => {
    return recipients
      .map((rec) => {
        const override = overrideBySub.get(rec.sub);
        const effective = override ?? rec.directRole ?? rec.teamBaseRole ?? "viewer";
        const viaTeam =
          !rec.directRole && rec.teamId ? (teamNameById.get(rec.teamId) ?? "team") : undefined;
        return { sub: rec.sub, label: rec.label, override, effective, viaTeam };
      })
      .sort((a, b) => a.label.localeCompare(b.label));
  }, [recipients, overrideBySub, teamNameById]);

  const ownerLabel = useMemo(() => {
    if (!ownerSub) return null;
    if (sharedBy?.sub === ownerSub) return `${sharedBy.username}@${sharedBy.organization}`;
    const member = teamMembers.find((m) => m.user_id === ownerSub);
    if (member) return `${member.username}@${member.organization}`;
    const direct = outboxEntries.find((e) => e.recipient_sub === ownerSub);
    if (direct) return `${direct.recipient_username}@${direct.recipient_organization}`;
    return null;
  }, [ownerSub, sharedBy, teamMembers, outboxEntries]);

  if (isLoading) {
    return (
      <div className="flex items-center gap-2 px-1 py-2 text-xs text-muted-foreground">
        <Loader2 className="h-3 w-3 animate-spin" />
        Resolving access…
      </div>
    );
  }

  const hasMembers = Boolean(ownerLabel) || memberRows.length > 0;

  if (teamRows.length === 0 && !hasMembers) {
    return (
      <p className="px-1 py-2 text-xs text-muted-foreground">
        No users have access to this project yet.
      </p>
    );
  }

  const ownerNode = ownerLabel ? (
    <div className="flex items-center justify-between gap-2 rounded-md border border-border bg-card px-3 py-1.5">
      <span className="min-w-0 truncate text-xs text-foreground">{ownerLabel}</span>
      <span className="flex-shrink-0 rounded bg-green-100 px-1.5 py-0.5 text-[10px] font-medium text-green-700 dark:bg-green-900/20 dark:text-green-400">
        Owner · full access
      </span>
    </div>
  ) : null;

  const memberItems: RosterSectionItem[] = memberRows.map((row) => ({
    key: row.sub,
    searchText: `${row.label} ${row.viaTeam ?? ""}`.toLowerCase(),
    node: (
      <MemberRoleRow
        label={row.label}
        hint={row.viaTeam ? `via ${row.viaTeam}` : undefined}
        effective={row.effective}
        override={row.override}
        editable={Boolean(onSetMemberRole)}
        isBusy={isBusy}
        onSet={(role) => onSetMemberRole?.(row.sub, role)}
        onClear={() => onClearMemberRole?.(row.sub)}
      />
    ),
  }));

  return (
    <div className="flex flex-col gap-4">
      {teamRows.length > 0 && (
        <div className="flex flex-col gap-1">
          <p className="px-0.5 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
            Teams
          </p>
          {teamRows.map((team) => (
            <TeamRoleRow
              key={`team:${team.id}`}
              name={team.name}
              baseRole={team.baseRole}
              editable={Boolean(onSetTeamRole)}
              isBusy={isBusy}
              onSet={(role) => onSetTeamRole?.(team.id, role)}
            />
          ))}
        </div>
      )}

      {hasMembers && (
        <RosterMemberSection title="Members" items={memberItems} leading={ownerNode} />
      )}
    </div>
  );
};

export default OntologyAccessRoster;
