import { useMemo } from "react";
import type { FetchResult } from "../../api/ConceptClient";

const BAR_COLORS = [
  "#6366f1",
  "#8b5cf6",
  "#06b6d4",
  "#10b981",
  "#f59e0b",
  "#ef4444",
  "#ec4899",
  "#14b8a6",
];

interface ProgressBarOutputProps {
  data: FetchResult;
  xCol: number; // label column
  yCol: number; // value column
}

export function ProgressBarOutput({ data, xCol, yCol }: ProgressBarOutputProps) {
  const items = useMemo(
    () =>
      data.rows.map((row) => ({
        label: row[xCol] !== null && row[xCol] !== undefined ? String(row[xCol]) : "—",
        value: Number(row[yCol]) || 0,
      })),
    [data.rows, xCol, yCol],
  );

  if (items.length === 0) {
    return <p className="text-xs text-muted-foreground py-4">No data</p>;
  }

  const max = Math.max(...items.map((i) => i.value), 1);

  return (
    <div className="flex flex-col gap-3">
      {items.map((item, i) => {
        const pct = Math.round((item.value / max) * 100);
        const color = BAR_COLORS[i % BAR_COLORS.length];
        return (
          <div key={i} className="flex flex-col gap-1">
            <div className="flex items-center justify-between text-xs">
              <span className="font-medium truncate max-w-[60%]">{item.label}</span>
              <span className="text-muted-foreground tabular-nums">{item.value}</span>
            </div>
            <div className="h-2 w-full rounded-full bg-secondary overflow-hidden">
              <div
                className="h-full rounded-full transition-all duration-500"
                style={{ width: `${pct}%`, backgroundColor: color }}
              />
            </div>
          </div>
        );
      })}
    </div>
  );
}
