import { Pencil, Plus, Trash2 } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import type { LlmConnectionSettings } from "../../api/configService";
import { useLlmConnections } from "../../hooks/useLlmConnections";
import SettingsSection from "../SettingsSection";
import { LlmConnectionForm } from "./LlmConnectionForm";

interface EditorState {
  mode: "closed" | "create" | "edit";
  name: string;
}

const CLOSED: EditorState = { mode: "closed", name: "" };

/**
 * Settings section for named LLM connections: self-contained
 * provider/model/credential targets that llm concepts can pin per concept via
 * their cell config, instead of the account-wide chat model settings.
 */
const LlmConnectionsConfig = () => {
  const { connections, isLoading, isSaving, upsertConnection, removeConnection } =
    useLlmConnections();
  const [editor, setEditor] = useState<EditorState>(CLOSED);

  const entries = Object.entries(connections);
  const initialDraft =
    editor.mode === "edit" && connections[editor.name]
      ? { name: editor.name, settings: connections[editor.name] }
      : null;

  const handleAdd = () => setEditor({ mode: "create", name: "" });
  const handleClose = () => setEditor(CLOSED);

  const handleSubmit = (name: string, settings: LlmConnectionSettings) =>
    upsertConnection(name, settings);

  return (
    <SettingsSection
      title="LLM Connections"
      description="Named provider/model/key targets that individual LLM concepts can use instead of the account default"
    >
      <div className="flex flex-col gap-3">
        {isLoading && <p className="text-sm text-muted-foreground">Loading connections…</p>}
        {!isLoading && entries.length === 0 && editor.mode === "closed" && (
          <p className="text-sm text-muted-foreground">
            No connections yet. Add one to pin an LLM concept to its own provider and API key.
          </p>
        )}
        {entries.map(([name, settings]) => (
          <div
            key={name}
            className="flex items-center justify-between rounded-md border border-border px-3 py-2"
          >
            <div className="flex min-w-0 flex-col">
              <span className="truncate text-sm font-medium text-foreground">{name}</span>
              <span className="truncate text-xs text-muted-foreground">
                {settings.llm_provider ?? "provider default"} ·{" "}
                {settings.llm_version ?? "provider default model"}
                {settings.llm_api_key ? " · own key" : " · managed key"}
              </span>
            </div>
            <div className="flex flex-shrink-0 items-center gap-1">
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={() => setEditor({ mode: "edit", name })}
                aria-label={`Edit connection ${name}`}
              >
                <Pencil className="h-3.5 w-3.5" />
              </Button>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7 text-destructive"
                onClick={() => removeConnection(name)}
                disabled={isSaving}
                aria-label={`Remove connection ${name}`}
              >
                <Trash2 className="h-3.5 w-3.5" />
              </Button>
            </div>
          </div>
        ))}
        {editor.mode !== "closed" ? (
          <LlmConnectionForm
            key={`${editor.mode}-${editor.name}`}
            initial={initialDraft}
            isSaving={isSaving}
            onSubmit={handleSubmit}
            onCancel={handleClose}
          />
        ) : (
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="w-fit gap-1"
            onClick={handleAdd}
            disabled={isLoading}
          >
            <Plus className="h-3.5 w-3.5" />
            Add connection
          </Button>
        )}
      </div>
    </SettingsSection>
  );
};

export default LlmConnectionsConfig;
