import { AlertCircle } from "lucide-react";
import type { AutoStartPhase } from "@/features/compute/hooks/useAutoStartCompute";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

interface ComputeStartingOverlayProps {
  phase: Exclude<AutoStartPhase, "ready">;
  statusMessage: string;
  machineName?: string;
  liveMessage?: string;
}

export function ComputeStartingOverlay({
  phase,
  statusMessage,
  machineName,
  liveMessage,
}: ComputeStartingOverlayProps) {
  const isError = phase === "error";

  return (
    <div
      className="flex h-full w-full flex-col items-center justify-center gap-4"
      role="status"
      aria-live="polite"
    >
      {isError ? (
        <AlertCircle className="h-8 w-8 text-destructive" aria-hidden="true" />
      ) : (
        <PrometheuxSpinner size={32} />
      )}

      <div className="flex max-w-sm flex-col items-center gap-1.5 text-center">
        <p className={`text-sm font-medium ${isError ? "text-destructive" : "text-foreground"}`}>
          {statusMessage}
        </p>
        {machineName && !isError && (
          <p className="text-xs text-muted-foreground">Machine: {machineName}</p>
        )}
        {liveMessage && !isError && <p className="text-xs text-muted-foreground">{liveMessage}</p>}
        {phase === "starting" && (
          <p className="mt-1 text-xs text-muted-foreground">
            This may take a few minutes while we provision the compute resources this app requires.
          </p>
        )}
      </div>
    </div>
  );
}
