import { useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { useOntologyId } from "@/features/ontologies/hooks/useOntologyId";
import { OntologyDocumentApi } from "./api";
import { DocumentOntologySchemaGraph } from "./DocumentOntologySchemaGraph";
import { DocumentOverview } from "./DocumentOverview";
import { type DocumentSubTab, DocumentTabBar } from "./DocumentTabBar";
import { useOntologyDocument } from "./useOntologyDocument";

const SCOPE = "user";

export function DocumentView() {
  const ontologyId = useOntologyId();
  const queryClient = useQueryClient();
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [subTab, setSubTab] = useState<DocumentSubTab>("overview");
  // generateOntologySchema=true bootstraps the schema graph from lineage when the
  // project has none yet, so the "Schema" sub-tab opens populated.
  const { document, isLoading, error } = useOntologyDocument(ontologyId, SCOPE, true);

  const handleRefresh = async () => {
    if (!ontologyId) return;
    setIsRefreshing(true);
    try {
      const fresh = await OntologyDocumentApi.get(ontologyId, SCOPE, { refresh: true });
      queryClient.setQueryData(["ontology-document", ontologyId, SCOPE], fresh);
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleNoteSaved = () => {
    if (!ontologyId) return;
    // Note text changed — re-fetch the document so the Context section,
    // hash, and (eventually, on next view) the LLM summary all stay in sync.
    queryClient.invalidateQueries({
      queryKey: ["ontology-document", ontologyId, SCOPE],
    });
  };

  if (!ontologyId) {
    return (
      <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
        Open a project to see its Document view.
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col overflow-hidden bg-background">
      <DocumentTabBar activeTab={subTab} onTabChange={setSubTab} />
      <div className="min-h-0 flex-1">
        {subTab === "schema" ? (
          <DocumentOntologySchemaGraph />
        ) : (
          <DocumentOverview
            document={document}
            isLoading={isLoading}
            error={error}
            isRefreshing={isRefreshing || isLoading}
            onRefresh={handleRefresh}
            onNoteSaved={handleNoteSaved}
          />
        )}
      </div>
    </div>
  );
}
