/**
 * Descriptor registry for the Graph Explorer's node-scoring analytics.
 *
 * Unlike the traversal functions in `graphFunctions.ts` (which define graph
 * structure), these functions produce one value per node and are rendered as
 * an OVERLAY on the loaded Records graph: node size/color by score, or group
 * color by connected component. Each entry mirrors an engine function exposed
 * by the backend `graph-analytics` endpoint via `function=<key>`.
 *
 * Adding a new analytics function is a single entry here (plus a matching entry
 * in the backend `FUNCTION_REGISTRY`).
 */

export type GraphAnalyticsKey = "pagerank" | "dc" | "bc" | "cc";

/** How the result is applied to nodes: a numeric score, or a group id. */
export type GraphAnalyticsResultType = "node_score" | "node_group";

/** A single tunable parameter, rendered as one control in the toolbar. */
export type GraphAnalyticsParam =
  | {
      name: string;
      kind: "number";
      label: string;
      default: number;
      min?: number;
      max?: number;
      step?: number;
    }
  | {
      name: string;
      kind: "enum";
      label: string;
      default: string;
      options: Array<{ value: string; label: string }>;
    }
  | {
      name: string;
      kind: "int";
      label: string;
      placeholder?: string;
      min?: number;
      max?: number;
    };

export interface GraphAnalyticsDef {
  key: GraphAnalyticsKey;
  label: string;
  description: string;
  resultType: GraphAnalyticsResultType;
  params: GraphAnalyticsParam[];
}

export const GRAPH_ANALYTICS: GraphAnalyticsDef[] = [
  {
    key: "pagerank",
    label: "PageRank",
    description: "Link-based importance. Larger nodes are more important.",
    resultType: "node_score",
    params: [
      {
        name: "damping",
        kind: "number",
        label: "damping",
        default: 0.85,
        min: 0,
        max: 1,
        step: 0.05,
      },
    ],
  },
  {
    key: "dc",
    label: "Degree Centrality",
    description: "Score by number of connections. Larger nodes are more connected.",
    resultType: "node_score",
    params: [
      {
        name: "direction",
        kind: "enum",
        label: "direction",
        default: "total",
        options: [
          { value: "total", label: "Total" },
          { value: "in", label: "In-degree" },
          { value: "out", label: "Out-degree" },
        ],
      },
    ],
  },
  {
    key: "bc",
    label: "Betweenness Centrality",
    description: "How often a node lies on shortest paths. Highlights bridge nodes.",
    resultType: "node_score",
    params: [
      {
        name: "sample",
        kind: "int",
        label: "sample",
        placeholder: "all",
        min: 1,
        max: 10000,
      },
    ],
  },
  {
    key: "cc",
    label: "Connected Components",
    description: "Group nodes into connected components. Same color = reachable.",
    resultType: "node_group",
    params: [],
  },
];

const GRAPH_ANALYTICS_KEYS = new Set<string>(GRAPH_ANALYTICS.map((fn) => fn.key));

export function isGraphAnalyticsKey(value: string): value is GraphAnalyticsKey {
  return GRAPH_ANALYTICS_KEYS.has(value);
}

export function getGraphAnalytics(key: GraphAnalyticsKey): GraphAnalyticsDef {
  const found = GRAPH_ANALYTICS.find((fn) => fn.key === key);
  if (!found) throw new Error(`Unknown graph analytics function: ${key}`);
  return found;
}
