import { Sparkles } from "lucide-react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";

/**
 * Shared "you hit a freemium limit" dialog for the non-machine limits
 * (AI agent messages, per-run ceiling, document embeddings).
 *
 * Unlike paid machines — which have a per-machine Stripe cost and a self-serve
 * checkout at /settings/billing — these limits are lifted as part of a paid
 * subscription handled by the team. So the only CTA here is "Contact Prometheux"
 * (a mailto), never a Stripe checkout. The machine flow keeps its own dialog.
 */
const SUPPORT_EMAIL = "support@prometheux.co.uk";

export interface ContactToUpgradeDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description: string;
  /** Optional mailto subject so we can tell the limits apart in the inbox. */
  contactSubject?: string;
}

export const ContactToUpgradeDialog = ({
  open,
  onOpenChange,
  title,
  description,
  contactSubject,
}: ContactToUpgradeDialogProps) => {
  const subjectQuery = contactSubject ? `?subject=${encodeURIComponent(contactSubject)}` : "";
  const mailtoHref = `mailto:${SUPPORT_EMAIL}${subjectQuery}`;

  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5" />
            {title}
          </AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <p className="text-sm text-muted-foreground">
          Reach us at{" "}
          <a href={mailtoHref} className="select-all font-medium text-foreground underline">
            {SUPPORT_EMAIL}
          </a>
          .
        </p>
        <AlertDialogFooter>
          <AlertDialogCancel>Not now</AlertDialogCancel>
          <AlertDialogAction asChild>
            <a href={mailtoHref}>Contact Prometheux</a>
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
};
