import { create } from "zustand";

export type EngineStatus = "unknown" | "ready" | "unavailable";

interface EngineStatusStore {
  status: EngineStatus;
  setStatus: (status: EngineStatus) => void;
}

// Tracks whether the Jarvispy engine is reachable. A "ready" result is cached so
// navigation stays instant once the engine is warm; "unavailable" is transient
// and gets re-checked on the next attempt so the user recovers automatically.
export const useEngineStatusStore = create<EngineStatusStore>((set) => ({
  status: "unknown",
  setStatus: (status) => set((state) => (state.status === status ? state : { status })),
}));
