import { ArrowDown, ArrowUp, Trash2 } from "lucide-react";
import { cn } from "@/shared/lib/utils";

interface OutlineRowProps {
  label: string;
  /** Small right-aligned type/kind hint. */
  hint?: string;
  depth: 0 | 1 | 2 | 3;
  isSelected: boolean;
  onSelect: () => void;
  onMoveUp?: () => void;
  onMoveDown?: () => void;
  onDelete?: () => void;
}

const DEPTH_PADDING: Record<number, string> = {
  0: "pl-2",
  1: "pl-5",
  2: "pl-8",
  3: "pl-11",
};

/** One row of the structure outline: click selects, hover reveals actions. */
export function OutlineRow({
  label,
  hint,
  depth,
  isSelected,
  onSelect,
  onMoveUp,
  onMoveDown,
  onDelete,
}: OutlineRowProps) {
  return (
    <div
      className={cn(
        "group flex items-center gap-1 pr-1 py-0.5 rounded",
        DEPTH_PADDING[depth],
        isSelected ? "bg-accent text-accent-foreground" : "hover:bg-accent/50",
      )}
    >
      <button
        type="button"
        onClick={onSelect}
        className="flex-1 min-w-0 flex items-center gap-2 text-left"
      >
        <span className="text-[11px] truncate">{label}</span>
        {hint && (
          <span className="text-[9px] font-mono text-muted-foreground flex-shrink-0">{hint}</span>
        )}
      </button>
      <div className="hidden group-hover:flex items-center flex-shrink-0">
        {onMoveUp && <RowAction title="Move up" onClick={onMoveUp} icon={ArrowUp} />}
        {onMoveDown && <RowAction title="Move down" onClick={onMoveDown} icon={ArrowDown} />}
        {onDelete && <RowAction title="Delete" onClick={onDelete} icon={Trash2} destructive />}
      </div>
    </div>
  );
}

interface RowActionProps {
  title: string;
  onClick: () => void;
  icon: typeof ArrowUp;
  destructive?: boolean;
}

function RowAction({ title, onClick, icon: Icon, destructive = false }: RowActionProps) {
  return (
    <button
      type="button"
      title={title}
      onClick={onClick}
      className={cn(
        "p-0.5 rounded text-muted-foreground",
        destructive ? "hover:text-destructive" : "hover:text-foreground",
      )}
    >
      <Icon className="h-3 w-3" />
    </button>
  );
}
