// The concept service handles API calls related to concepts and virtual KG building

import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

export interface ConceptData {
  predicate_name: string;
  type?: string; // Database type provided by backend
  /** Concept language: "logic" (Vadalog, default), "sql", "cypher", or "python".
   * Python bodies are raw code (`def main(...)`) and must never be sent to the
   * Vadalog parser. "context" pins notes and is non-executable. */
  concept_type?: string;
  /** False for non-deterministic concepts (never served from cache). */
  is_deterministic?: boolean;
  /** Opaque per-type config bag (e.g. a static context concept's note_ids).
   * Postgres JSON may arrive as an object or a raw string. */
  concept_config?: Record<string, unknown> | string | null;
  description?: string;
  arity?: number;
  column_names?: string[];
  fields?: Record<string, string>; // Field names mapped to their types
  bind_annotations?: string;
  model_annotation?: string;
  definition?: string;
  /** Per-output-predicate details; `definition` lives here in the list response. */
  concept_details?: Array<{
    predicate_name?: string;
    definition?: string;
    /** Raw `@param("name","default").` annotations of this concept's source. */
    param_annotations?: string;
  }>;
  read_only?: boolean;
  is_populated?: boolean;
  timestamp?: string;
  author?: string;
  row_count?: number;
  execution_time_ms?: number;
  column_count?: number;
}

export class ConceptService {
  /**
   * Lists concepts for a given project
   */
  static async listConcepts(ontologyId: string, scope: string = "user"): Promise<ConceptData[]> {
    // Create query parameters for project scope
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/list?scope=${scope}`;

    const response = await HttpService.get(url);

    if (response.status === "success" && Array.isArray(response.data)) {
      return response.data;
    } else {
      throw new Error("Failed to load concepts");
    }
  }

  /**
   * Delete specific concepts
   */
  static async deleteConcepts(
    ontologyId: string,
    conceptNames: string[],
    ontologyScope: string = "user",
  ): Promise<any> {
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/cleanup`;
    const payload = {
      project: {
        scope: ontologyScope,
      },
      concept_names: conceptNames,
    };

    const response = await HttpService.post(url, payload);

    if (response.status === "success") {
      return response;
    } else {
      throw new Error(response.message || "Failed to delete concepts");
    }
  }
}
