import { useMemo } from "react";
import { Area, AreaChart, ResponsiveContainer, Tooltip, YAxis } from "recharts";
import type { RuntimeSample } from "../types/engineMonitor.types";

interface RuntimeSparklineProps {
  samples: RuntimeSample[];
  dataKey: "cpu" | "memoryUsed";
  color: string;
  height?: number;
  formatValue: (value: number | null) => string;
  yMax?: number;
}

interface ChartDatum {
  ts: number;
  value: number | null;
}

const RuntimeSparkline: React.FC<RuntimeSparklineProps> = ({
  samples,
  dataKey,
  color,
  height = 60,
  formatValue,
  yMax,
}) => {
  const chartData = useMemo<ChartDatum[]>(
    () => samples.map((sample) => ({ ts: sample.ts, value: sample[dataKey] })),
    [samples, dataKey],
  );

  const hasData = chartData.some((d) => typeof d.value === "number");

  if (!hasData) {
    return (
      <div
        className="flex items-center justify-center rounded-md border border-dashed border-border text-xs text-muted-foreground"
        style={{ height }}
      >
        Waiting for samples...
      </div>
    );
  }

  const gradientId = `sparkline-gradient-${dataKey}`;

  return (
    <ResponsiveContainer width="100%" height={height}>
      <AreaChart data={chartData} margin={{ top: 4, right: 4, bottom: 0, left: 0 }}>
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity={0.35} />
            <stop offset="100%" stopColor={color} stopOpacity={0} />
          </linearGradient>
        </defs>
        <YAxis hide domain={yMax !== undefined ? [0, yMax] : ["auto", "auto"]} allowDataOverflow />
        <Tooltip
          cursor={{ stroke: color, strokeOpacity: 0.3 }}
          contentStyle={{
            background: "hsl(var(--card))",
            border: "1px solid hsl(var(--border))",
            borderRadius: 6,
            fontSize: 11,
            padding: "4px 8px",
          }}
          labelFormatter={(label) => new Date(Number(label)).toLocaleTimeString()}
          formatter={(value: number | string) =>
            [formatValue(typeof value === "number" ? value : Number(value)), ""] as [string, string]
          }
        />
        <Area
          type="monotone"
          dataKey="value"
          stroke={color}
          strokeWidth={2}
          fill={`url(#${gradientId})`}
          dot={false}
          activeDot={{ r: 3, strokeWidth: 0, fill: color }}
          isAnimationActive={false}
          connectNulls
        />
      </AreaChart>
    </ResponsiveContainer>
  );
};

export default RuntimeSparkline;
