import type { FetchResult } from "../../api/ConceptClient";
import type { DashboardWidget } from "../../types";

function formatValue(v: any): string {
  if (v === null || v === undefined) return "—";
  const n = Number(v);
  if (!Number.isNaN(n)) {
    if (Math.abs(n) >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
    if (Math.abs(n) >= 1_000) return n % 1000 === 0 ? `${n / 1000}K` : n.toLocaleString();
    return n.toLocaleString();
  }
  return String(v);
}

interface StatCardWidgetProps {
  data: FetchResult;
  widget: DashboardWidget;
}

export function StatCardWidget({ data, widget }: StatCardWidgetProps) {
  const firstRow = data.rows[0];
  const value = firstRow != null ? firstRow[widget.yCol] : null;
  const label = widget.label || data.columnNames?.[widget.yCol] || `col_${widget.yCol}`;

  return (
    <div className="bg-card border border-border rounded-lg p-4">
      <div className="text-[11px] font-medium text-muted-foreground uppercase tracking-widest mb-1.5">
        {label}
      </div>
      <div className="text-[28px] font-bold tracking-tight leading-none text-foreground">
        {formatValue(value)}
      </div>
      {widget.statSub && (
        <div className="text-[11px] text-muted-foreground mt-1.5">{widget.statSub}</div>
      )}
    </div>
  );
}
