import { Loader2 } from "lucide-react";
import type React from "react";
import { useTeamShareGrants } from "../hooks/useTeamShareGrants";
import type { TeamShareGrant } from "../types";

interface TeamShareGrantsProps {
  shareId: string;
}

function formatTimestamp(iso: string | null): string {
  if (!iso) return "—";
  return new Date(iso).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
}

// Members are keyed by their opaque auth subject; show a short prefix so the
// list is scannable without leaking the full identifier.
function shortSub(sub: string): string {
  return sub.length > 12 ? `${sub.slice(0, 12)}…` : sub;
}

interface GrantRowProps {
  grant: TeamShareGrant;
}

const GrantRow: React.FC<GrantRowProps> = ({ grant }) => (
  <div className="flex items-center justify-between gap-2 px-3 py-1.5 text-xs">
    <span className="truncate font-mono text-foreground">{shortSub(grant.recipient_sub)}</span>
    <span className="flex-shrink-0 text-muted-foreground">
      Joined {formatTimestamp(grant.claimed_at)}
    </span>
  </div>
);

const TeamShareGrants: React.FC<TeamShareGrantsProps> = ({ shareId }) => {
  const { grants, isLoading, error } = useTeamShareGrants({ shareId });

  if (isLoading) {
    return (
      <div className="flex items-center gap-2 px-3 py-2 text-xs text-muted-foreground">
        <Loader2 className="h-3 w-3 animate-spin" />
        Loading members…
      </div>
    );
  }

  if (error) {
    return <p className="px-3 py-2 text-xs text-destructive">{error.message}</p>;
  }

  if (grants.length === 0) {
    return <p className="px-3 py-2 text-xs text-muted-foreground">No members have joined yet.</p>;
  }

  return (
    <div className="divide-y divide-border/60 rounded-md border border-border bg-muted/20">
      {grants.map((grant) => (
        <GrantRow key={grant.recipient_sub} grant={grant} />
      ))}
    </div>
  );
};

export default TeamShareGrants;
