import { useQuery } from "@tanstack/react-query";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  type LineageConceptStatusMap,
  useLineageRunStatusStore,
} from "@/features/lineage/store/lineageRunStatusStore";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";
import { type ExecutionStatusSnapshot, fetchOntologyExecutionStatus } from "../executionStatus";

const POLL_INTERVAL_MS = 1500;

interface UseReconnectExecutionStatusReturn {
  snapshot: ExecutionStatusSnapshot | undefined;
}

/**
 * On returning to the lineage tab, recover the state of the project's latest
 * run from the backend. While a run is still in progress, poll and expose its
 * per-concept progress so the graph can repaint. The returned snapshot also
 * drives the "last run failed / cancelled / interrupted" notice.
 *
 * Statuses are delivered as state (not transient window events) so they survive
 * the mount race between the lineage data load and the graph view, and node
 * rebuilds re-apply them. Suppressed while the user is the active local runner —
 * the live WebSocket run owns the graph then.
 */
export function useReconnectExecutionStatus(
  ontologyId: string | undefined,
  ontologyScope: string,
): UseReconnectExecutionStatusReturn {
  const isLocalRunning = useEditorActionsStore((s) => s.isRunningConcept);
  const [shownExecutionId, setShownExecutionId] = useState<string | null>(null);
  const prevLocalRunningRef = useRef(isLocalRunning);

  const query = useQuery({
    queryKey: ["execution-status", ontologyId, ontologyScope],
    queryFn: () => fetchOntologyExecutionStatus(ontologyId as string, ontologyScope),
    enabled: !!ontologyId,
    staleTime: 0,
    refetchInterval: (q) => (q.state.data?.status === "running" ? POLL_INTERVAL_MS : false),
  });

  const { data: snapshot, refetch } = query;

  // A local run just ended — refresh once so the notice reflects its outcome.
  useEffect(() => {
    const ended = prevLocalRunningRef.current && !isLocalRunning;
    prevLocalRunningRef.current = isLocalRunning;
    if (ended) refetch();
  }, [isLocalRunning, refetch]);

  // Remember a run we've seen in flight, so its final per-concept statuses keep
  // showing after it transitions to a terminal state.
  useEffect(() => {
    if (
      snapshot?.status === "running" &&
      snapshot.executionId &&
      snapshot.executionId !== shownExecutionId
    ) {
      setShownExecutionId(snapshot.executionId);
    }
  }, [snapshot, shownExecutionId]);

  const reconnectStatuses = useMemo<LineageConceptStatusMap | null>(() => {
    if (!snapshot?.executionId) return null;
    const running = snapshot.status === "running";
    const showing = snapshot.executionId === shownExecutionId;
    // A terminal run we never saw in flight stays off the canvas — the notice
    // surfaces its outcome instead of repainting a stale chain.
    if (!running && !showing) return null;
    const out: LineageConceptStatusMap = {};
    for (const [concept, st] of Object.entries(snapshot.statuses)) {
      out[concept] = { status: st.status, error: st.error };
    }
    return out;
  }, [snapshot, shownExecutionId]);

  // Publish to the shared store so the deep graph view (useConceptExecutionStatus)
  // can pick it up regardless of mount timing. Clear on unmount.
  const setReconnectStatuses = useLineageRunStatusStore((s) => s.setReconnectStatuses);
  useEffect(() => {
    setReconnectStatuses(reconnectStatuses);
  }, [reconnectStatuses, setReconnectStatuses]);
  useEffect(() => () => setReconnectStatuses(null), [setReconnectStatuses]);

  return { snapshot };
}
