import type { AssignableTeamRole, TeamMembershipRow, TeamRole } from "../types";

interface RoleMeta {
  title: string;
  description: string;
}

const ROLE_LABELS: Record<TeamRole, RoleMeta> = {
  owner: { title: "Owner", description: "Full control — can transfer or delete the team" },
  admin: { title: "Admin", description: "Can invite / remove members and change roles" },
  member: { title: "Member", description: "Can view the roster" },
};

export function teamRoleMeta(role: TeamRole): RoleMeta {
  return ROLE_LABELS[role];
}

// Actions the caller can perform on a given team, driven purely by their role
// in that team. Matches the FE gating cheat-sheet in the backend contract:
//
//   Action                            owner  admin  member
//   Invite / remove / change roles      Y      Y      N
//   Transfer ownership                  Y      N      N
//   Delete team                         Y      N      N
//   Leave team                          Y*     Y      Y   (* owner: must transfer first)
//   View roster                         Y      Y      Y
//   Grant / release seats               Y      Y      N   (owner-funded plan)
//
// The backend also enforces this (returns 403), so optimistic gating in the UI
// is safe.
export interface TeamRoleCapabilities {
  canManageMembers: boolean;
  canInvite: boolean;
  canTransferOwnership: boolean;
  canDeleteTeam: boolean;
  canLeave: boolean;
  canManageSeats: boolean;
}

export function teamRoleCapabilities(role: TeamRole): TeamRoleCapabilities {
  const isOwnerOrAdmin = role === "owner" || role === "admin";
  return {
    canManageMembers: isOwnerOrAdmin,
    canInvite: isOwnerOrAdmin,
    canTransferOwnership: role === "owner",
    canDeleteTeam: role === "owner",
    canLeave: true,
    canManageSeats: isOwnerOrAdmin,
  };
}

// Roles the caller can assign to another member via PATCH /members/{id}. The
// backend rejects any attempt to set `owner` (transfer-ownership is the only
// path) and any attempt to demote the current owner — we filter at both the
// role list and the row-eligibility layer to keep the UI honest.
export function assignableRolesFor(callerRole: TeamRole): readonly AssignableTeamRole[] {
  if (callerRole === "owner" || callerRole === "admin") return ["admin", "member"];
  return [];
}

// Helper for callers rendering a list of teams that want to highlight "the
// team I own". Returns null if none — the backend enforces max 1 owned team
// per user, so at most one row matches.
export function findOwnedTeam(teams: TeamMembershipRow[]): TeamMembershipRow | null {
  return teams.find((t) => t.role === "owner") ?? null;
}
