export interface SnowflakeComputePool {
  name: string;
  instance_family: string;
  state: "ACTIVE" | "IDLE" | "SUSPENDED" | "STARTING" | "STOPPING" | "UNKNOWN";
  min_nodes: number;
  max_nodes: number;
  is_current: boolean;
}

export interface SnowflakeComputeConfig {
  current_pool: string;
  pools: SnowflakeComputePool[];
}
