import type React from "react";
import { useMemo } from "react";
import { useLocation } from "react-router-dom";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import type { TabComponent, TabRendererProps } from "@/shared/hooks/tabs/tabTypes";

export const useAppTabRenderer = (props: TabRendererProps): TabComponent | null => {
  const location = useLocation();
  const visibleApps = usePermissionsStore((state) => state.visibleApps);

  return useMemo(() => {
    if (!location.pathname.includes("/editor/")) return null;
    if (visibleApps.length === 0) return null;

    const app = visibleApps[0];
    return {
      component: app.component as React.FC<any>,
      props: {
        onToggleSidebar: props.onToggleSidebar,
        sidebarVisible: props.sidebarVisible,
      },
    };
  }, [props.onToggleSidebar, props.sidebarVisible, location.pathname, visibleApps]);
};
