import type { NotificationItem } from "./types";

// Secondary line under a notification title.
export function notificationSubtitle(item: NotificationItem): string {
  if (item.type === "project_share") {
    return item.actor ? `Shared by ${item.actor}` : "Shared with you";
  }
  return item.actor ? `Invited by ${item.actor}` : "Team invitation";
}
