import { Label } from "@/shared/components/ui/label";

import type { ContextNote } from "../../types";
import { NotesGraphView } from "./NotesGraphView";

interface NoteLocalGraphProps {
  note: ContextNote;
  /** Title/label lookup for the note's 1-hop neighbors. */
  lookupNotes: ContextNote[];
  onOpenNote: (noteId: string) => void;
}

/** Obsidian-style local graph in the info panel: the open note and its
 *  1-hop neighborhood (notes, concepts, projects). */
export function NoteLocalGraph({ note, lookupNotes, onOpenNote }: NoteLocalGraphProps) {
  return (
    <section className="space-y-1.5">
      <Label>Local graph</Label>
      <div className="h-44 overflow-hidden rounded-md border border-border bg-card">
        <NotesGraphView
          collectionNotes={[note]}
          documents={[]}
          lookupNotes={lookupNotes}
          onOpenNoteId={onOpenNote}
          showLegend={false}
        />
      </div>
    </section>
  );
}
