import { useQuery, useQueryClient } from "@tanstack/react-query";
import { LogOut } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { OnboardingForm } from "@/features/onboarding/components/OnboardingForm";
import { OnboardingPendingStatus } from "@/features/onboarding/components/OnboardingPendingStatus";
import { HeroLoadingScreen } from "@/shared/components/HeroLoadingScreen";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent } from "@/shared/components/ui/card";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { supabase } from "@/shared/integrations/supabase/client";

type OnboardingState = "profile_incomplete" | "requested" | "loading";

// Cache clearing utilities
const clearPlatformAccessCache = () => {
  try {
    localStorage.removeItem("platform_access_cache");
  } catch (error) {
    console.error("Error clearing platform access cache:", error);
  }
};

const clearJupyterLabAccessCache = () => {
  try {
    localStorage.removeItem("jupyterlab_access_cache");
  } catch (error) {
    console.error("Error clearing JupyterLab cache:", error);
  }
};

const clearUserOrganizationCache = () => {
  try {
    localStorage.removeItem("user_organization_cache");
  } catch (error) {
    console.error("Error clearing user organization cache:", error);
  }
};

const Onboarding = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, refreshPlatformAccess, signOut } = useAuth();
  const _queryClient = useQueryClient();

  const [onboardingState, setOnboardingState] = useState<OnboardingState>("loading");

  // Handle back to login - clears all caches and signs out.
  // In 3P (Databricks Marketplace) mode, signOut() already redirects the
  // browser back to the user's Databricks workspace via window.location, so
  // we skip the local navigate("/login") to avoid racing the navigation
  // and to ensure the user lands back on Databricks (not on a /login page
  // they'd never use anyway).
  const handleBackToLogin = async () => {
    try {
      clearPlatformAccessCache();
      clearJupyterLabAccessCache();
      clearUserOrganizationCache();

      await signOut();

      if (!PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) {
        navigate("/login");
      }
    } catch (error) {
      console.error("Error returning to login:", error);
      if (!PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) {
        navigate("/login");
      }
    }
  };

  // Query to fetch current user profile
  const { data: currentUserProfile, refetch: refetchProfile } = useQuery({
    queryKey: ["profile", user?.id],
    queryFn: async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) throw new Error("No user found");

      const { data: profile, error } = await supabase
        .from("profiles")
        .select("*")
        .eq("id", user.id)
        .single();

      if (error) throw error;
      return profile;
    },
    enabled: !!user,
  });

  // Check if user profile is complete
  const isProfileComplete = useCallback(() => {
    if (!currentUserProfile) return false;

    const hasUsername = currentUserProfile.username && currentUserProfile.username.trim() !== "";
    const hasOrganization =
      currentUserProfile.organization && currentUserProfile.organization.trim() !== "";
    const hasFirstName =
      currentUserProfile.first_name && currentUserProfile.first_name.trim() !== "";
    const hasLastName = currentUserProfile.last_name && currentUserProfile.last_name.trim() !== "";

    return hasUsername && hasOrganization && hasFirstName && hasLastName;
  }, [currentUserProfile]);

  // Check current platform access status
  const checkPlatformAccessStatus = useCallback(async () => {
    if (!user?.id) {
      setOnboardingState("profile_incomplete");
      return;
    }

    try {
      const { data: userApp, error } = await supabase
        .from("user_applications")
        .select(`
          status,
          user_id,
          application_id,
          applications!inner(id, name)
        `)
        .eq("user_id", user.id)
        .eq("applications.name", "Platform")
        .single();

      if (error && error.code !== "PGRST116") {
        // If profile is complete but no access request, set to profile_incomplete to trigger re-check
        setOnboardingState(isProfileComplete() ? "requested" : "profile_incomplete");
        return;
      }

      if (userApp) {
        const status = userApp.status?.toLowerCase();
        if (status === "enabled") {
          // User has access - clear caches and refresh auth state
          clearPlatformAccessCache();
          clearJupyterLabAccessCache();

          // Refresh platform access to update all auth state
          await refreshPlatformAccess();

          // Restore the page they were trying to reach (passed via RequireAuth state), or go home
          const from = (location.state as any)?.from?.pathname;
          navigate(from || "/");
          return;
        } else if (status === "requested") {
          setOnboardingState("requested");
          return;
        }
      }

      // No request found - check if profile is complete
      if (isProfileComplete()) {
        // Profile is complete but no request - something went wrong
        // Show the form again or handle this edge case
        setOnboardingState("profile_incomplete");
      } else {
        setOnboardingState("profile_incomplete");
      }
    } catch (error) {
      console.error("Error checking platform access status:", error);
      setOnboardingState("profile_incomplete");
    }
  }, [user?.id, navigate, isProfileComplete, location.state, refreshPlatformAccess]);

  // Check status on component mount and when profile changes
  useEffect(() => {
    if (currentUserProfile !== undefined) {
      checkPlatformAccessStatus();
    }
  }, [currentUserProfile, checkPlatformAccessStatus]);

  // Handle successful form submission
  const handleOnboardingSuccess = () => {
    setOnboardingState("requested");
    refetchProfile();
  };

  // Handle refresh status
  const handleRefreshStatus = async () => {
    setOnboardingState("loading");
    await checkPlatformAccessStatus();
  };

  // Render loading state
  if (onboardingState === "loading") {
    return <HeroLoadingScreen />;
  }

  // Render pending status
  if (onboardingState === "requested") {
    return (
      <OnboardingPendingStatus
        onRefreshStatus={handleRefreshStatus}
        onBackToLogin={handleBackToLogin}
      />
    );
  }

  // Render onboarding form (profile_incomplete state)
  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-4">
      <div className="w-full max-w-md">
        {/* Logo */}
        <div className="flex justify-center mb-8">
          <img src="/prometheux-logo.png" alt="Prometheux" className="h-8" />
        </div>

        {/* Onboarding Form Card */}
        <Card className="border-0 shadow-lg">
          <CardContent className="pt-6">
            <OnboardingForm onSuccess={handleOnboardingSuccess} userEmail={user?.email} />
          </CardContent>
        </Card>

        {/* Back to Login Button — labeled "Back to Databricks" in 3P mode */}
        <div className="mt-4 text-center">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleBackToLogin}
            className="text-muted-foreground hover:text-foreground"
          >
            <LogOut className="h-4 w-4 mr-2" />
            {PROMETHEUX_CONFIG.DATABRICKS_3P_MODE ? "Back to Databricks" : "Back to Login"}
          </Button>
        </div>
      </div>
    </div>
  );
};

export default Onboarding;
