import { RefreshCw } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { OntologySchemaActions } from "@/features/ontologies/components/header/OntologySchemaActions";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";
import { OntologySchemaService } from "@/features/ontology-schema/api";
import OntologySchemaEditor from "@/features/ontology-schema/components/OntologySchemaEditor";
import { Button } from "@/shared/components/ui/button";

/**
 * Document view "Schema" sub-tab: just the schema graph, no title or summary.
 * The refresh button regenerates the schema from the current concept lineage
 * (as if the graph were absent) and reloads the canvas.
 */
export function DocumentOntologySchemaGraph() {
  const ontologyId = useOntologyId();
  const ontologyScope = useOntologyScope();
  const bumpOntologySchemaRevision = useCodeAssistantStore((s) => s.bumpOntologySchemaRevision);
  const [isRegenerating, setIsRegenerating] = useState(false);

  const handleRegenerate = async () => {
    if (!ontologyId) return;
    setIsRegenerating(true);
    try {
      await OntologySchemaService.generateFromLineage(ontologyId, ontologyScope);
      bumpOntologySchemaRevision();
      toast.success("Schema regenerated from lineage");
    } catch {
      toast.error("Failed to regenerate schema from lineage");
    } finally {
      setIsRegenerating(false);
    }
  };

  return (
    <div className="flex h-full flex-col overflow-hidden bg-background">
      <div className="flex shrink-0 items-center justify-end gap-2 border-b border-border bg-card px-4 py-2">
        <Button
          variant="outline"
          size="sm"
          className="gap-1.5"
          onClick={handleRegenerate}
          disabled={isRegenerating}
          type="button"
        >
          <RefreshCw className={isRegenerating ? "h-3.5 w-3.5 animate-spin" : "h-3.5 w-3.5"} />
          Regenerate
        </Button>
        <OntologySchemaActions showCompute={false} />
      </div>
      <div className="min-h-0 flex-1">
        <OntologySchemaEditor defaultSubTab="schema" schemaOnly />
      </div>
    </div>
  );
}
