import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import type { ColumnFilterValue, OrderByItem } from "../components/outputs/table/tableOutput.types";
import type { FetchResult } from "./ConceptClient";

/** Derive the ws(s):// endpoint for a run-stream path from the configured BASE_URL. */
export function buildWsUrl(path: string): string {
  const baseUrl = PROMETHEUX_CONFIG.BASE_URL;
  if (baseUrl.startsWith("http://") || baseUrl.startsWith("https://")) {
    const parsed = new URL(baseUrl);
    const wsProtocol = parsed.protocol === "https:" ? "wss" : "ws";
    return `${wsProtocol}://${parsed.host}${parsed.pathname}${path}`;
  }
  const wsProtocol = window.location.protocol === "https:" ? "wss" : "ws";
  return `${wsProtocol}://${window.location.host}${baseUrl}${path}`;
}

interface ParseFetchArgs {
  data: Record<string, unknown>;
  page: number;
  pageSize: number;
  orderBy?: OrderByItem[];
  searchState?: { searchTerm: string; columnFilters?: Record<number, ColumnFilterValue> };
}

/** Normalise a /fetch response body into a FetchResult. */
export function parseFetchResponse({
  data,
  page,
  pageSize,
  orderBy,
  searchState,
}: ParseFetchArgs): FetchResult {
  const results = data.results as Record<string, unknown> | undefined;
  const pagination = data.pagination as Record<string, unknown> | undefined;
  return {
    columnNames: (results?.columnNames as string[]) ?? [],
    rows: (results?.facts as unknown[][]) ?? [],
    totalCount: (pagination?.total_count as number) ?? 0,
    page: (pagination?.page as number) ?? page,
    pageSize: (pagination?.page_size as number) ?? pageSize,
    totalPages: (pagination?.total_pages as number) ?? 1,
    hasNext: (pagination?.has_next as boolean) ?? false,
    orderBy,
    ...(searchState ? { searchState } : {}),
  };
}
