import { AlertCircle } from "lucide-react";
import React from "react";
import { Alert, AlertDescription } from "@/shared/components/ui/alert";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import type { FetchResult } from "../../api/ConceptClient";
import type { DashboardWidget } from "../../types";
import { LineChartOutput } from "../outputs/LineChartOutput";
import { PieChartOutput } from "../outputs/PieChartOutput";
import { ProgressBarOutput } from "../outputs/ProgressBarOutput";
import { TableOutput } from "../outputs/TableOutput";
import type { BoundTableHandlers } from "../outputs/table/tableOutput.types";
import { BadgeTableWidget } from "./BadgeTableWidget";
import { BarListWidget } from "./BarListWidget";
import { ChannelGridWidget } from "./ChannelGridWidget";
import { GraphWidget } from "./GraphWidget";
import { StatCardWidget } from "./StatCardWidget";

interface WidgetRendererProps {
  widget: DashboardWidget;
  data?: FetchResult | null;
  isLoading?: boolean;
  error?: string;
  tableHandlers?: BoundTableHandlers;
  fullscreen?: boolean;
  ontologyId?: string;
}

export function WidgetRenderer({
  widget,
  data,
  isLoading,
  error,
  tableHandlers,
  fullscreen = false,
  ontologyId,
}: WidgetRendererProps) {
  if (isLoading) {
    return (
      <div className="flex items-center gap-2 py-6 text-muted-foreground text-sm">
        <PrometheuxSpinner size={16} />
        Loading…
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="destructive">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>{error}</AlertDescription>
      </Alert>
    );
  }

  if (!data) return null;

  switch (widget.type) {
    case "table":
      return <TableOutput data={data} handlers={tableHandlers} />;

    case "line_chart":
      return (
        <LineChartOutput
          data={data}
          xCol={widget.xCol}
          yCol={widget.yCol}
          fullscreen={fullscreen}
        />
      );

    case "pie_chart":
      return (
        <PieChartOutput data={data} xCol={widget.xCol} yCol={widget.yCol} fullscreen={fullscreen} />
      );

    case "progress_bar":
      return <ProgressBarOutput data={data} xCol={widget.xCol} yCol={widget.yCol} />;

    case "stat_card":
      return <StatCardWidget data={data} widget={widget} />;

    case "bar_list":
      return <BarListWidget data={data} widget={widget} />;

    case "channel_grid":
      return <ChannelGridWidget data={data} widget={widget} />;

    case "badge_table":
      return <BadgeTableWidget data={data} widget={widget} handlers={tableHandlers} />;

    case "graph":
      return (
        <GraphWidget
          data={data}
          xCol={widget.xCol}
          yCol={widget.yCol}
          fullscreen={fullscreen}
          ontologyId={ontologyId}
          predicateName={widget.conceptName}
        />
      );

    default:
      return <p className="text-xs text-muted-foreground">Unknown widget type</p>;
  }
}
