import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect } from "react";
import { toast } from "sonner";
import { useSchemaStore } from "@/features/concept-editor/store";
import { ConceptService } from "@/features/concepts/api";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";

/**
 * Custom hook for automatically refreshing concepts after data operations
 * This ensures both the concepts page and CodeMirror suggestions stay updated
 */
export const useConceptRefresh = () => {
  const queryClient = useQueryClient();
  const ontologyId = useOntologyId();
  const ontologyScope = useOntologyScope();
  const { setSchemaFromConcepts, clearSchemaSuggestions } = useSchemaStore();

  const refreshConcepts = useCallback(
    async (
      showToast: boolean = true,
      retryCount: number = 0,
      eventOntologyId?: string,
      eventOntologyScope?: string,
    ): Promise<boolean> => {
      // Use project ID from event if provided, otherwise fall back to hooks
      const targetOntologyId = eventOntologyId || ontologyId;
      const targetOntologyScope = eventOntologyScope || ontologyScope;

      if (!targetOntologyId) {
        return false;
      }

      try {
        // Get the current concept count before refresh
        const currentConcepts = useSchemaStore.getState().schemaSuggestions;
        const previousConceptCount = currentConcepts.length;

        // Invalidate and refetch concepts query cache
        await queryClient.invalidateQueries({
          queryKey: ["concepts", targetOntologyId, targetOntologyScope],
        });

        // Fetch fresh concepts data using the same project ID and scope as the datasource connection
        const concepts = await ConceptService.listConcepts(targetOntologyId, targetOntologyScope);

        // Update CodeMirror suggestions
        if (concepts && concepts.length > 0) {
          setSchemaFromConcepts(concepts);

          // Dispatch conceptsUpdated event to update cell descriptions
          window.dispatchEvent(
            new CustomEvent("conceptsUpdated", {
              detail: { concepts },
              bubbles: true,
              cancelable: true,
            }),
          );

          // Check if we got new concepts
          if (concepts.length > previousConceptCount && retryCount > 0) {
            if (showToast) {
              toast.success(
                `${concepts.length} concepts loaded (${concepts.length - previousConceptCount} new)`,
              );
            }
            return true;
          } else if (retryCount === 0) {
            // First attempt, always show success
            if (showToast) {
              toast.success(`${concepts.length} concepts refreshed`);
            }
            return true;
          } else if (concepts.length === previousConceptCount && retryCount < 3) {
            // No new concepts yet, retry after a short delay
            setTimeout(() => {
              refreshConcepts(showToast, retryCount + 1, eventOntologyId, eventOntologyScope);
            }, 2000);
            return false;
          }
        } else {
          clearSchemaSuggestions();

          if (showToast) {
            toast.success("No concepts found, suggestions cleared");
          }
        }

        return true;
      } catch (error) {
        console.error("❌ Error refreshing concepts:", error);

        // Retry logic for failed requests
        if (retryCount < 2) {
          setTimeout(() => {
            refreshConcepts(showToast, retryCount + 1, eventOntologyId, eventOntologyScope);
          }, 3000);
          return false;
        }

        if (showToast) {
          toast.error("Failed to refresh concepts after multiple attempts");
        }

        return false;
      }
    },
    [ontologyId, ontologyScope, queryClient, setSchemaFromConcepts, clearSchemaSuggestions],
  );

  // Listen for custom events that should trigger concept refresh
  useEffect(() => {
    const handleDataSourceConnected = (event: CustomEvent) => {
      const { ontologyId: eventOntologyId, ontologyScope: eventOntologyScope } = event.detail || {};
      refreshConcepts(false, 0, eventOntologyId, eventOntologyScope); // Don't show toast for automatic refresh
    };

    const handleCellExecuted = () => {
      refreshConcepts(false); // Don't show toast for automatic refresh
    };

    const handleDataSourceDeleted = () => {
      refreshConcepts(false); // Don't show toast for automatic refresh
    };

    // Add event listeners
    window.addEventListener("dataSourceConnected", handleDataSourceConnected as EventListener);
    window.addEventListener("cellExecuted", handleCellExecuted);
    window.addEventListener("dataSourceDeleted", handleDataSourceDeleted);

    // Cleanup event listeners
    return () => {
      window.removeEventListener("dataSourceConnected", handleDataSourceConnected as EventListener);
      window.removeEventListener("cellExecuted", handleCellExecuted);
      window.removeEventListener("dataSourceDeleted", handleDataSourceDeleted);
    };
  }, [refreshConcepts]);

  return {
    refreshConcepts,
  };
};
