import { useMemo } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Legend,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import type { FetchResult } from "../../../api/ConceptClient";
import { columnIndex } from "../../../runtime/useConceptRows";
import type { AppWidgetDef } from "../../../schema/appDefinition.types";

interface ChartV2WidgetProps {
  widget: AppWidgetDef;
  data: FetchResult;
}

const SERIES_COLORS = [
  "hsl(var(--chart-line))",
  "hsl(199 89% 68%)",
  "hsl(262 60% 60%)",
  "hsl(160 60% 45%)",
  "hsl(30 90% 55%)",
];

const CHART_HEIGHT = 280;
// seriesCol pivots are bounded: beyond this the chart is unreadable and the
// legend floods the layout (each extra distinct value = one more series).
const MAX_PIVOT_SERIES = 12;

interface ChartModel {
  rows: Array<Record<string, unknown>>;
  seriesNames: string[];
}

function buildChartData(
  data: FetchResult,
  xName: string | undefined,
  yNames: string[],
): ChartModel {
  const xIndex = xName ? columnIndex(data.columnNames, xName) : 0;
  const yIndexes = yNames
    .map((name) => [name, columnIndex(data.columnNames, name)] as const)
    .filter(([, index]) => index >= 0);
  if (xIndex < 0 || yIndexes.length === 0) return { rows: [], seriesNames: [] };
  return {
    rows: data.rows.map((row) => ({
      x: String(row[xIndex] ?? ""),
      ...Object.fromEntries(yIndexes.map(([name, index]) => [name, Number(row[index]) || 0])),
    })),
    seriesNames: yIndexes.map(([name]) => name),
  };
}

/**
 * Pivot long-format rows (x, series, value) into one point per x with one
 * numeric key per distinct series value — e.g. (date, entity, aum) rows
 * become one line per entity.
 */
function pivotBySeries(
  data: FetchResult,
  xName: string | undefined,
  seriesName: string,
  valueName: string | undefined,
): ChartModel {
  const xIndex = xName ? columnIndex(data.columnNames, xName) : 0;
  const seriesIndex = columnIndex(data.columnNames, seriesName);
  const valueIndex = valueName ? columnIndex(data.columnNames, valueName) : -1;
  if (xIndex < 0 || seriesIndex < 0 || valueIndex < 0) return { rows: [], seriesNames: [] };

  const seriesNames: string[] = [];
  const byX = new Map<string, Record<string, unknown>>();
  for (const row of data.rows) {
    const series = String(row[seriesIndex] ?? "");
    if (!seriesNames.includes(series)) {
      if (seriesNames.length >= MAX_PIVOT_SERIES) continue;
      seriesNames.push(series);
    }
    const xValue = String(row[xIndex] ?? "");
    const point = byX.get(xValue) ?? { x: xValue };
    point[series] = Number(row[valueIndex]) || 0;
    byX.set(xValue, point);
  }
  const rows = [...byX.values()].sort((a, b) => String(a.x).localeCompare(String(b.x)));
  return { rows, seriesNames };
}

/**
 * v2 charts (ADR D4): line / area / bar / pie bound by column NAMES with
 * multi-series support (`y` is a list of column names, or `seriesCol` pivots
 * long-format rows into one series per distinct value).
 */
export function ChartV2Widget({ widget, data }: ChartV2WidgetProps) {
  const model = useMemo(
    () =>
      widget.seriesCol
        ? pivotBySeries(data, widget.x, widget.seriesCol, widget.y?.[0])
        : buildChartData(data, widget.x, widget.y ?? []),
    [data, widget.x, widget.y, widget.seriesCol],
  );
  const { rows: chartData, seriesNames: yNames } = model;

  if (chartData.length === 0) {
    return <p className="text-xs text-muted-foreground py-4">No data</p>;
  }

  const axisProps = {
    tick: { fontSize: 11 },
    tickLine: false,
    axisLine: false,
  } as const;
  const commonChildren = (
    <>
      <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
      <XAxis dataKey="x" {...axisProps} interval="preserveStartEnd" />
      <YAxis {...axisProps} width={52} />
      <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6 }} labelStyle={{ fontWeight: 600 }} />
      {yNames.length > 1 && <Legend wrapperStyle={{ fontSize: 12 }} />}
    </>
  );

  if (widget.type === "pie_chart") {
    const valueKey = yNames[0];
    return (
      <ResponsiveContainer width="100%" height={CHART_HEIGHT}>
        <PieChart>
          <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6 }} />
          <Legend wrapperStyle={{ fontSize: 12 }} />
          <Pie
            data={chartData}
            dataKey={valueKey}
            nameKey="x"
            innerRadius={55}
            outerRadius={90}
            paddingAngle={2}
          >
            {chartData.map((entry, index) => (
              <Cell key={String(entry.x)} fill={SERIES_COLORS[index % SERIES_COLORS.length]} />
            ))}
          </Pie>
        </PieChart>
      </ResponsiveContainer>
    );
  }

  if (widget.type === "bar_chart") {
    return (
      <ResponsiveContainer width="100%" height={CHART_HEIGHT}>
        <BarChart data={chartData} margin={{ top: 8, right: 16, bottom: 8, left: 8 }}>
          {commonChildren}
          {yNames.map((name, index) => (
            <Bar
              key={name}
              dataKey={name}
              fill={SERIES_COLORS[index % SERIES_COLORS.length]}
              radius={[3, 3, 0, 0]}
            />
          ))}
        </BarChart>
      </ResponsiveContainer>
    );
  }

  if (widget.type === "area_chart") {
    return (
      <ResponsiveContainer width="100%" height={CHART_HEIGHT}>
        <AreaChart data={chartData} margin={{ top: 8, right: 16, bottom: 8, left: 8 }}>
          {commonChildren}
          {yNames.map((name, index) => (
            <Area
              key={name}
              type="monotone"
              dataKey={name}
              stroke={SERIES_COLORS[index % SERIES_COLORS.length]}
              fill={SERIES_COLORS[index % SERIES_COLORS.length]}
              fillOpacity={0.15}
              strokeWidth={2}
            />
          ))}
        </AreaChart>
      </ResponsiveContainer>
    );
  }

  return (
    <ResponsiveContainer width="100%" height={CHART_HEIGHT}>
      <LineChart data={chartData} margin={{ top: 8, right: 16, bottom: 8, left: 8 }}>
        {commonChildren}
        {yNames.map((name, index) => (
          <Line
            key={name}
            type="monotone"
            dataKey={name}
            stroke={SERIES_COLORS[index % SERIES_COLORS.length]}
            strokeWidth={2}
            dot={{ r: 2.5 }}
            activeDot={{ r: 4.5 }}
          />
        ))}
      </LineChart>
    </ResponsiveContainer>
  );
}
