import { useEffect, useRef, useState } from "react";
import type { AppDefinition } from "../../schema/appDefinition.types";
import { useAppEditorStore } from "../../store/appEditorStore";

const PARSE_DEBOUNCE_MS = 500;

function parseDefinition(text: string): AppDefinition {
  const parsed: unknown = JSON.parse(text);
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new Error("The definition must be a JSON object");
  }
  return parsed as AppDefinition;
}

/**
 * The raw-JSON escape hatch (ADR D6: the schema is the primary product
 * surface). The textarea is the source of truth while this pane is visible;
 * valid JSON is applied to the shared draft after a short debounce so the
 * visual panes stay in sync, and structural mistakes are still caught by the
 * server-side validation on save.
 */
export function EditorJsonPane() {
  const draft = useAppEditorStore((state) => state.draft);
  const replaceDraft = useAppEditorStore((state) => state.replaceDraft);
  const parseError = useAppEditorStore((state) => state.jsonParseError);
  const setParseError = useAppEditorStore((state) => state.setJsonParseError);
  const [text, setText] = useState(() => JSON.stringify(draft, null, 2));
  // Distinguishes draft changes that echo our own apply (skip re-serialize,
  // it would fight the caret) from external ones (version restore).
  const lastAppliedRef = useRef<AppDefinition | null>(null);

  useEffect(() => {
    if (!draft || draft === lastAppliedRef.current) return;
    setText(JSON.stringify(draft, null, 2));
    setParseError(null);
  }, [draft]);

  useEffect(() => {
    const timer = setTimeout(() => {
      try {
        const parsed = parseDefinition(text);
        setParseError(null);
        lastAppliedRef.current = parsed;
        replaceDraft(parsed);
      } catch (err: unknown) {
        setParseError(err instanceof Error ? err.message : "Invalid JSON");
      }
    }, PARSE_DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [text, replaceDraft, setParseError]);

  // Leaving the pane discards unapplied text — the draft becomes the source
  // of truth again, so a lingering parse error must not keep blocking saves.
  useEffect(() => () => setParseError(null), [setParseError]);

  return (
    <div className="flex flex-col flex-1 min-h-0 px-6 pb-6 gap-2">
      {parseError && (
        <p className="text-[11px] text-destructive font-mono flex-shrink-0">
          Invalid JSON — changes not applied: {parseError}
        </p>
      )}
      <textarea
        value={text}
        onChange={(event) => setText(event.target.value)}
        spellCheck={false}
        className="w-full flex-1 resize-none rounded-md border border-input bg-background p-4 font-mono text-xs leading-relaxed text-foreground focus:outline-none focus:ring-1 focus:ring-ring"
      />
    </div>
  );
}
