import { Plus, Save } from "lucide-react";
import type React from "react";
import type { OntologyData } from "@/features/ontologies/api";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Separator } from "@/shared/components/ui/separator";
import { Switch } from "@/shared/components/ui/switch";
import type { AppConcept } from "../../api/ConceptClient";
import type { DashboardHeader, DashboardPage } from "../../types";
import { PageEditor } from "./PageEditor";

export interface CanvasConfigPanelProps {
  projects: OntologyData[];
  ontologyId: string;
  onOntologyChange: (v: string) => void;
  inputConceptName: string;
  setInputConceptName: (v: string) => void;
  concepts: AppConcept[];
  conceptsLoading: boolean;
  header: DashboardHeader;
  setHeader: React.Dispatch<React.SetStateAction<DashboardHeader>>;
  pages: DashboardPage[];
  addPage: () => void;
  updatePage: (id: string, p: DashboardPage) => void;
  removePage: (id: string) => void;
  knownColumnsMap: Record<string, string[]>;
  canSave: boolean;
  onSave: () => void;
}

export function CanvasConfigPanel({
  projects,
  ontologyId,
  onOntologyChange,
  inputConceptName,
  setInputConceptName,
  concepts,
  conceptsLoading,
  header,
  setHeader,
  pages,
  addPage,
  updatePage,
  removePage,
  knownColumnsMap,
  canSave,
  onSave,
}: CanvasConfigPanelProps) {
  return (
    <div className="bg-card border border-border rounded-lg p-4 flex flex-col gap-5">
      {/* Project + input concept */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="flex flex-col gap-1.5">
          <Label className="text-xs text-muted-foreground uppercase tracking-wide">Ontology</Label>
          <Select value={ontologyId} onValueChange={onOntologyChange}>
            <SelectTrigger className="h-8 text-sm">
              <SelectValue placeholder="Select ontology" />
            </SelectTrigger>
            <SelectContent>
              {projects.map((p) => (
                <SelectItem key={p.id} value={p.id}>
                  {p.name || p.id}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="flex flex-col gap-1.5">
          <Label className="text-xs text-muted-foreground uppercase tracking-wide">
            Input concept <span className="normal-case text-muted-foreground/60">(drives run)</span>
          </Label>
          <Select
            value={inputConceptName}
            onValueChange={setInputConceptName}
            disabled={!ontologyId || conceptsLoading}
          >
            <SelectTrigger className="h-8 text-sm">
              <SelectValue placeholder={conceptsLoading ? "Loading…" : "Select concept"} />
            </SelectTrigger>
            <SelectContent>
              {concepts.map((c) => (
                <SelectItem key={c.predicate_name} value={c.predicate_name}>
                  <div className="flex items-center gap-1.5">
                    <span>{c.predicate_name}</span>
                    {c.concept_type && (
                      <Badge variant="secondary" className="text-xs py-0">
                        {c.concept_type}
                      </Badge>
                    )}
                  </div>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <Separator />

      {/* Header config */}
      <div className="flex flex-col gap-3">
        <Label className="text-xs text-muted-foreground uppercase tracking-wide">App Header</Label>
        <div className="grid grid-cols-2 gap-3">
          <div className="flex flex-col gap-1.5">
            <Label className="text-xs text-muted-foreground">Title</Label>
            <Input
              value={header.title}
              onChange={(e) => setHeader((h) => ({ ...h, title: e.target.value }))}
              placeholder="e.g. Acme Corp · Sales Intelligence"
              className="h-8 text-sm"
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <Label className="text-xs text-muted-foreground">Subtitle</Label>
            <Input
              value={header.subtitle ?? ""}
              onChange={(e) => setHeader((h) => ({ ...h, subtitle: e.target.value }))}
              placeholder="Mono sub-label below title"
              className="h-8 text-sm"
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <Label className="text-xs text-muted-foreground">Logo URL (optional)</Label>
            <Input
              value={header.logoUrl ?? ""}
              onChange={(e) => setHeader((h) => ({ ...h, logoUrl: e.target.value }))}
              placeholder="https://…/logo.png"
              className="h-8 text-sm"
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <Label className="text-xs text-muted-foreground">
              Header tags <span className="font-normal">(comma-separated)</span>
            </Label>
            <Input
              value={header.tags?.join(", ") ?? ""}
              onChange={(e) =>
                setHeader((h) => ({
                  ...h,
                  tags: e.target.value
                    .split(",")
                    .map((t) => t.trim())
                    .filter(Boolean),
                }))
              }
              placeholder="1,200 records, project_id: abc"
              className="h-8 text-sm"
            />
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Switch
            checked={header.showStatus ?? false}
            onCheckedChange={(v) => setHeader((h) => ({ ...h, showStatus: v }))}
          />
          <Label className="text-xs text-muted-foreground cursor-pointer">
            Show status dot (green)
          </Label>
        </div>
      </div>

      <Separator />

      {/* Pages / tabs */}
      <div className="flex flex-col gap-3">
        <div className="flex items-center justify-between">
          <Label className="text-xs text-muted-foreground uppercase tracking-wide">
            Pages / Tabs
          </Label>
          <Button
            variant="outline"
            size="sm"
            onClick={addPage}
            disabled={!ontologyId}
            className="gap-1.5 h-7 text-xs"
          >
            <Plus className="h-3 w-3" /> Add page
          </Button>
        </div>

        {pages.length === 0 && (
          <p className="text-xs text-muted-foreground">
            No pages yet — each page becomes a tab in the app.
          </p>
        )}

        <div className="flex flex-col gap-3">
          {pages.map((page) => (
            <PageEditor
              key={page.id}
              page={page}
              concepts={concepts}
              knownColumnsMap={knownColumnsMap}
              onChange={(p) => updatePage(page.id, p)}
              onRemove={() => removePage(page.id)}
            />
          ))}
        </div>
      </div>

      <div className="flex justify-end">
        <Button size="sm" onClick={onSave} disabled={!canSave} className="gap-1.5">
          <Save className="h-3.5 w-3.5" /> Save App
        </Button>
      </div>
    </div>
  );
}
