import { useEffect } from "react";
import { useLocation } from "react-router-dom";
import { useCurrentDashboardName } from "@/features/dynamic-dashboard/hooks/useCurrentDashboardName";
import { useCurrentOntologyName } from "@/features/ontologies/hooks/useOntologyId";
import { buildDocumentTitle } from "@/shared/utils/pageTitle";

/**
 * Keeps `document.title` in sync with the current route so each browser-history
 * entry is distinguishable (e.g. "Prometheux: Ontologies"). The project editor and
 * dashboards append the open record's name. Mount once near the app root.
 */
export function useDocumentTitle(): void {
  const location = useLocation();
  const { ontologyName } = useCurrentOntologyName();
  const { dashboardName } = useCurrentDashboardName();

  useEffect(() => {
    document.title = buildDocumentTitle(location.pathname, { ontologyName, dashboardName });
  }, [location.pathname, ontologyName, dashboardName]);
}
