import { useSchemaStore } from "@/features/concept-editor/store";
import type { OntologyScope } from "@/features/ontologies/api";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

export class ReasoningService {
  static async compile(ontology: string): Promise<boolean> {
    try {
      const _response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/compile`,
        { ontology },
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );
      return true;
    } catch (_error) {
      return false;
    }
  }

  static async cleanup(existingKgId?: string, scope: OntologyScope = "user"): Promise<boolean> {
    try {
      // Skip cleanup if no KG ID is provided (new KG case)
      if (existingKgId === undefined) {
        return true;
      }

      // Create a properly structured payload as expected by the backend
      const payload = {
        virtual_kg: {
          id: existingKgId,
          scope: scope,
        },
      };

      const _response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/cleanup`,
        payload,
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );
      return true;
    } catch (_error) {
      return false;
    }
  }

  static async reason(
    vadalogProgram: string,
    toExplain: boolean = false,
    toEmbed: boolean = false,
    scope: OntologyScope = "user",
  ): Promise<any> {
    // Clear existing schema suggestions before making the request
    const schemaStore = useSchemaStore.getState();
    schemaStore.clearSchemaSuggestions();

    // Create embedding config object with all embedding-related parameters
    const embeddingConfig = {
      embedding_provider: PROMETHEUX_CONFIG.EMBEDDING.EMBEDDING_PROVIDER,
      embedding_api_key: PROMETHEUX_CONFIG.EMBEDDING_API_KEY,
      embedding_version: PROMETHEUX_CONFIG.EMBEDDING.MODEL_VERSION,
      embedding_dimensions: PROMETHEUX_CONFIG.EMBEDDING.DIMENSIONS,
      azure_embedding_endpoint: PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_ENDPOINT,
      azure_embedding_api_version: PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_API_VERSION,
    };

    const payload = {
      vadalog_programs: [
        [
          {
            content: vadalogProgram,
          },
        ],
      ],
      vadalog_params: {
        filter: 1,
      },
      to_explain: toExplain,
      to_persist: true,
      to_embed: toEmbed,
      embedding_config: embeddingConfig,
      scope: scope, // Use the provided scope parameter
    };

    const reasoningResult = await HttpService.post(
      `${PROMETHEUX_CONFIG.BASE_URL}/reason`,
      payload,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
    );

    if (reasoningResult.data) {
      globalThis.ontology_session = reasoningResult.data;
    }

    return reasoningResult;
  }

  static async deleteKnowledgeGraph(
    graphId: string,
    scope: OntologyScope = "user",
  ): Promise<boolean> {
    try {
      // Update to explicitly pass both id and scope to the cleanup method
      const cleanupSuccess = await ReasoningService.cleanup(graphId, scope);

      return cleanupSuccess;
    } catch (_error) {
      return false;
    }
  }
}
