import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

interface ChatSessionMeta {
  id: string;
  ontology_id: string | null;
  title: string;
  created_at: string;
  updated_at: string;
}

interface ChatSessionMessage {
  role: string;
  content?: string;
  tool_calls?: unknown[];
  tool_call_id?: string;
  /** ISO-8601, when the message was stored — a user turn is stored on send. */
  created_at?: string;
}

interface ChatSessionFull extends ChatSessionMeta {
  messages: ChatSessionMessage[];
}

interface ApiResponse<T> {
  status: string;
  message: string;
  data: T;
}

function authHeaders(authToken: string, supabaseToken?: string): Record<string, string> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${authToken}`,
  };
  if (supabaseToken) {
    headers["X-Supabase-Token"] = supabaseToken;
  }
  return headers;
}

export async function fetchSessions(
  authToken: string,
  supabaseToken?: string,
): Promise<ChatSessionMeta[]> {
  // Chat history is global per user — a single chat can span multiple projects,
  // so sessions are not filtered by project.
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/chat-history/sessions`;
  const res = await fetch(url, {
    headers: authHeaders(authToken, supabaseToken),
  });

  if (!res.ok) throw new Error(`Failed to list sessions (${res.status})`);

  const json: ApiResponse<ChatSessionMeta[]> = await res.json();
  return json.data;
}

export async function fetchSession(
  sessionId: string,
  authToken: string,
  supabaseToken?: string,
): Promise<ChatSessionFull> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/chat-history/sessions/${sessionId}`;
  const res = await fetch(url, {
    headers: authHeaders(authToken, supabaseToken),
  });

  if (!res.ok) throw new Error(`Failed to load session (${res.status})`);

  const json: ApiResponse<ChatSessionFull> = await res.json();
  return json.data;
}

export async function deleteSession(
  sessionId: string,
  authToken: string,
  supabaseToken?: string,
): Promise<void> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/chat-history/sessions/${sessionId}`;
  const res = await fetch(url, {
    method: "DELETE",
    headers: authHeaders(authToken, supabaseToken),
  });

  if (!res.ok) throw new Error(`Failed to delete session (${res.status})`);
}

/**
 * Delete one exchange — the given user turn and the assistant's reply to it —
 * leaving the rest of the conversation in place. `turnIndex` is the 0-based
 * position of the user message in the stored transcript, not its position among
 * the bubbles on screen; see `resolveUserTurnIndex`.
 */
export async function deleteTurn(
  sessionId: string,
  turnIndex: number,
  authToken: string,
  supabaseToken?: string,
): Promise<void> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/chat-history/sessions/${sessionId}/turns/${turnIndex}`;
  const res = await fetch(url, {
    method: "DELETE",
    headers: authHeaders(authToken, supabaseToken),
  });

  if (!res.ok) throw new Error(`Failed to delete message (${res.status})`);
}

export async function renameSession(
  sessionId: string,
  title: string,
  authToken: string,
  supabaseToken?: string,
): Promise<void> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/chat-history/sessions/${sessionId}`;
  const res = await fetch(url, {
    method: "PATCH",
    headers: authHeaders(authToken, supabaseToken),
    body: JSON.stringify({ title }),
  });

  if (!res.ok) throw new Error(`Failed to rename session (${res.status})`);
}

export type { ChatSessionFull, ChatSessionMessage, ChatSessionMeta };
