import { ChevronRight, HardDrive } from "lucide-react";

interface FileBreadcrumbProps {
  currentPath: string;
  onNavigate: (path: string) => void;
}

export function FileBreadcrumb({ currentPath, onNavigate }: FileBreadcrumbProps) {
  const segments = currentPath ? currentPath.split("/").filter(Boolean) : [];

  const crumbs = segments.map((seg, i) => ({
    label: seg,
    path: segments.slice(0, i + 1).join("/"),
  }));

  return (
    <nav className="flex items-center gap-1 text-sm" aria-label="File path">
      <button
        type="button"
        onClick={() => onNavigate("")}
        className="flex items-center gap-1 rounded px-1.5 py-0.5 font-medium text-foreground hover:bg-accent"
      >
        <HardDrive className="h-3.5 w-3.5" />
        disk
      </button>

      {crumbs.map((crumb) => (
        <span key={crumb.path} className="flex items-center gap-1">
          <ChevronRight className="h-3.5 w-3.5 text-muted-foreground" />
          <button
            type="button"
            onClick={() => onNavigate(crumb.path)}
            className="rounded px-1.5 py-0.5 text-foreground hover:bg-accent"
          >
            {crumb.label}
          </button>
        </span>
      ))}
    </nav>
  );
}
