import { Eye, EyeOff } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { cn } from "@/shared/lib/utils";

interface SecretInputProps {
  id?: string;
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  onEnter?: () => void;
}

/**
 * A text field for something the user would not want on their screen — a token,
 * a client secret, a password. Masked until they ask to see it, so it can be
 * checked for a typo without being readable to whoever is watching.
 *
 * Browser autofill and password managers are kept out: these are credentials for
 * a third-party service being passed through, not this app's own login.
 */
export function SecretInput({
  id,
  value,
  onChange,
  placeholder,
  disabled,
  className,
  onEnter,
}: SecretInputProps) {
  const [isRevealed, setIsRevealed] = useState(false);

  const handleToggleReveal = () => setIsRevealed((revealed) => !revealed);

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key !== "Enter" || !onEnter) return;
    event.preventDefault();
    onEnter();
  };

  return (
    <div className="relative">
      <Input
        id={id}
        type={isRevealed ? "text" : "password"}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        disabled={disabled}
        autoComplete="off"
        autoCorrect="off"
        autoCapitalize="off"
        spellCheck={false}
        data-1p-ignore
        data-lpignore="true"
        className={cn("pr-10 font-mono text-sm", className)}
      />
      <Button
        type="button"
        variant="ghost"
        size="sm"
        className="absolute right-0 top-0 h-full px-3"
        onClick={handleToggleReveal}
        disabled={disabled}
        aria-label={isRevealed ? "Hide" : "Show"}
      >
        {isRevealed ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
      </Button>
    </div>
  );
}
