export interface ComputeRequirements {
  minCores?: number;
  minMemoryGb?: number;
}

export interface DashboardAppConfig {
  dashboardId: string;
  name: string;
  description: string;
  ontologyId: string;
  scope: "user" | "organization";
  computeRequirements?: ComputeRequirements;
}

const configModules = import.meta.glob("./components/**/*.config.ts", { eager: true });

export const DASHBOARD_CONFIG_MAP: Record<string, DashboardAppConfig> = {};

// Maps dashboardId → component filename (derived from the config file's own basename).
// Used as a fallback when a permission's value.metadata.component is absent (org-level policies).
export const DASHBOARD_ID_TO_COMPONENT_NAME: Record<string, string> = {};

for (const [path, mod] of Object.entries(configModules)) {
  const config = (mod as { default?: DashboardAppConfig }).default;
  if (config?.dashboardId) {
    DASHBOARD_CONFIG_MAP[config.dashboardId] = config;
    const componentName = path.split("/").pop()!.replace(".config.ts", "");
    DASHBOARD_ID_TO_COMPONENT_NAME[config.dashboardId] = componentName;
  }
}
