import { Check, ChevronDown, ChevronUp, FileSpreadsheet, X } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import type { ProposalData } from "../store";

type CsvCardStatus = "running" | "done" | "error";

interface CsvDatasourceProposalCardProps {
  data: ProposalData;
  toolStatus?: CsvCardStatus;
  errorMessage?: string;
}

function resolveStatus(toolStatus: CsvDatasourceProposalCardProps["toolStatus"]): CsvCardStatus {
  if (toolStatus === "done") return "done";
  if (toolStatus === "error") return "error";
  return "running";
}

function resolveStatusColor(status: CsvCardStatus) {
  if (status === "done") return "border-green-500/40 bg-green-500/5";
  if (status === "error") return "border-destructive/40 bg-destructive/5";
  return "border-primary/60 bg-primary/10 shadow-sm shadow-primary/10";
}

function resolveTitle(status: CsvCardStatus) {
  if (status === "done") return "Created mock CSV";
  if (status === "error") return "Failed to create CSV";
  return "Creating mock CSV";
}

function resolveStatusText(status: CsvCardStatus, errorMessage?: string) {
  if (status === "done") return "Saved to disk and registered as a datasource.";
  if (status === "error") {
    return errorMessage ?? "Registration failed — see chat for details.";
  }
  return "Writing file and registering datasource…";
}

function resolveTitleColor(status: CsvCardStatus) {
  if (status === "done") return "text-green-600 dark:text-green-400";
  if (status === "error") return "text-destructive";
  return "text-primary";
}

const CsvDatasourceProposalCard: React.FC<CsvDatasourceProposalCardProps> = ({
  data,
  toolStatus,
  errorMessage,
}) => {
  const [expanded, setExpanded] = useState(false);

  const status = resolveStatus(toolStatus);
  const isRunning = status === "running";
  const isError = status === "error";

  const columns = data.columns ?? [];
  const hasColumns = columns.length > 0;
  const rowCount = data.row_count ?? 0;
  const colCount = columns.length;

  return (
    <div className={`rounded-lg border text-xs overflow-hidden ${resolveStatusColor(status)}`}>
      <div className="px-3 py-2 flex items-center justify-between gap-2">
        <div className="flex items-center gap-2 min-w-0">
          {isRunning && <PrometheuxSpinner size={20} className="flex-shrink-0" />}
          {status === "done" && (
            <Check className="h-4 w-4 text-green-500 flex-shrink-0" strokeWidth={3} />
          )}
          {status === "error" && (
            <X className="h-4 w-4 text-destructive flex-shrink-0" strokeWidth={3} />
          )}
          <FileSpreadsheet className="h-3.5 w-3.5 opacity-60 flex-shrink-0" />
          <span className={`font-medium flex-shrink-0 ${resolveTitleColor(status)}`}>
            {resolveTitle(status)}
          </span>
          {data.predicate_name && (
            <span className="font-mono text-[11px] text-muted-foreground truncate">
              {data.predicate_name}.csv
            </span>
          )}
        </div>
        <div className="flex items-center gap-2 flex-shrink-0 text-[11px] text-muted-foreground">
          <span>
            {rowCount} row{rowCount === 1 ? "" : "s"} · {colCount} col{colCount === 1 ? "" : "s"}
          </span>
          {hasColumns && (
            <button
              type="button"
              onClick={() => setExpanded((v) => !v)}
              className="text-muted-foreground hover:text-foreground transition-colors"
              title={expanded ? "Hide columns" : "Show columns"}
            >
              {expanded ? (
                <ChevronUp className="h-3.5 w-3.5" />
              ) : (
                <ChevronDown className="h-3.5 w-3.5" />
              )}
            </button>
          )}
        </div>
      </div>

      <div
        className={`px-3 pb-2 text-[11px] flex items-start gap-2 ${
          isRunning
            ? "text-primary/80 animate-pulse"
            : isError
              ? "text-destructive"
              : "text-muted-foreground"
        }`}
      >
        {isRunning && (
          <span className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-primary flex-shrink-0" />
        )}
        <span className="break-words">{resolveStatusText(status, errorMessage)}</span>
      </div>

      {expanded && hasColumns && (
        <div className="border-t border-border/50 bg-muted/40 px-3 py-2 font-mono text-[11px] leading-relaxed max-h-48 overflow-y-auto">
          {columns.map((col) => (
            <div key={col.name} className="flex justify-between gap-4">
              <span className="text-foreground">{col.name}</span>
              <span className="text-muted-foreground">{col.type}</span>
            </div>
          ))}
        </div>
      )}

      {data.description && (
        <div className="px-3 pb-2 text-muted-foreground text-[11px]">{data.description}</div>
      )}
    </div>
  );
};

export default CsvDatasourceProposalCard;
