// localStorage-backed persistence for the code-assistant store (panel width,
// selected chat model). Best-effort: storage failures fall back to defaults.

const AI_PANEL_WIDTH_KEY = "ai_assistant_panel_width";
const AI_PANEL_DEFAULT_WIDTH = 320;

export function readStoredPanelWidth(): number {
  try {
    const stored = localStorage.getItem(AI_PANEL_WIDTH_KEY);
    if (stored) {
      const parsed = parseInt(stored, 10);
      if (!Number.isNaN(parsed)) return parsed;
    }
  } catch {
    // ignore — fall through to default
  }
  return AI_PANEL_DEFAULT_WIDTH;
}

// User's chosen chat model, persisted so the pick survives reloads. Null means
// "use the model from the user's saved LLM config" (the request omits `model`).
const AI_SELECTED_MODEL_KEY = "ai_assistant_selected_model";

export function readStoredSelectedModel(): string | null {
  try {
    return localStorage.getItem(AI_SELECTED_MODEL_KEY) || null;
  } catch {
    return null;
  }
}

export function writeStoredSelectedModel(model: string | null): void {
  try {
    if (model) {
      localStorage.setItem(AI_SELECTED_MODEL_KEY, model);
    } else {
      localStorage.removeItem(AI_SELECTED_MODEL_KEY);
    }
  } catch {
    // ignore — persistence is best-effort
  }
}
