import { create } from "zustand";
import { persist } from "zustand/middleware";

interface SidebarState {
  collapsed: boolean;
  toggle: () => void;
  setCollapsed: (collapsed: boolean) => void;
  ontologiesExpanded: boolean;
  setOntologiesExpanded: (expanded: boolean) => void;
  appsExpanded: boolean;
  setAppsExpanded: (expanded: boolean) => void;
}

export const useSidebarStore = create<SidebarState>()(
  persist(
    (set) => ({
      collapsed: false,
      toggle: () => set((s) => ({ collapsed: !s.collapsed })),
      setCollapsed: (collapsed) => set({ collapsed }),
      ontologiesExpanded: false,
      setOntologiesExpanded: (expanded) => set({ ontologiesExpanded: expanded }),
      appsExpanded: false,
      setAppsExpanded: (expanded) => set({ appsExpanded: expanded }),
    }),
    { name: "sidebar-state" },
  ),
);
