import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { ConfigService, type LlmConnectionSettings } from "../api/configService";
import { applyConnectionEdit } from "../utils/llmConnection.utils";

interface LlmConnectionsState {
  connections: Record<string, LlmConnectionSettings>;
  isLoading: boolean;
  isSaving: boolean;
}

/**
 * Named LLM connections from the user config (`llm_connections`): loading,
 * upsert, and delete.
 *
 * Writes go one connection at a time through /users/llm-connection, which reads
 * and merges server-side. Sending the whole map from the copy loaded here would
 * silently drop anything saved from another tab or from an llm cell in between.
 * Each write invalidates the llm-defaults query so cell pickers refresh.
 */
export function useLlmConnections() {
  const queryClient = useQueryClient();
  const [state, setState] = useState<LlmConnectionsState>({
    connections: {},
    isLoading: true,
    isSaving: false,
  });

  useEffect(() => {
    let cancelled = false;
    ConfigService.loadUserConfig().then((config) => {
      if (cancelled) return;
      setState((prev) => ({
        ...prev,
        connections: config?.llm_connections ?? {},
        isLoading: false,
      }));
    });
    return () => {
      cancelled = true;
    };
  }, []);

  const upsertConnection = useCallback(
    async (name: string, settings: LlmConnectionSettings): Promise<boolean> => {
      setState((prev) => ({ ...prev, isSaving: true }));
      try {
        await ConfigService.upsertLlmConnection(name, settings);
        setState((prev) => ({
          ...prev,
          connections: {
            ...prev.connections,
            [name]: applyConnectionEdit(prev.connections[name], settings),
          },
          isSaving: false,
        }));
        queryClient.invalidateQueries({ queryKey: ["llm-defaults"] });
        toast.success(`Connection "${name}" saved`);
        return true;
      } catch (error) {
        setState((prev) => ({ ...prev, isSaving: false }));
        toast.error(error instanceof Error ? error.message : "Failed to save the LLM connection");
        return false;
      }
    },
    [queryClient],
  );

  const removeConnection = useCallback(
    async (name: string): Promise<boolean> => {
      setState((prev) => ({ ...prev, isSaving: true }));
      try {
        await ConfigService.deleteLlmConnection(name);
        setState((prev) => {
          const { [name]: _removed, ...rest } = prev.connections;
          return { ...prev, connections: rest, isSaving: false };
        });
        queryClient.invalidateQueries({ queryKey: ["llm-defaults"] });
        toast.success(`Connection "${name}" removed`);
        return true;
      } catch (error) {
        setState((prev) => ({ ...prev, isSaving: false }));
        toast.error(error instanceof Error ? error.message : "Failed to remove the LLM connection");
        return false;
      }
    },
    [queryClient],
  );

  return { ...state, upsertConnection, removeConnection };
}
