import type { Session } from "@supabase/supabase-js";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useNavigate } from "react-router-dom";
import {
  DatabricksEmailConflictScreen,
  DatabricksSsoErrorScreen,
} from "@/features/auth/components/Databricks3PErrorScreens";
import {
  APP_CONTEXT_DATA_KEY,
  type AppPrincipalContext,
  useDatabricksAppContext,
} from "@/features/auth/hooks/useDatabricksAppContext";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import type { User } from "@/features/auth/types";
import { trackLogin } from "@/features/auth/utils/loginTracking";
import { captureOAuthTokens, markTokensAsProcessed } from "@/features/auth/utils/oauthTokenCapture";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { DatabricksConfigService } from "@/features/compute/api/databricksService";
import { clearAuthToken, getAuthToken, setAuthToken } from "@/shared/auth/authToken";
import { useAuthToken } from "@/shared/auth/useAuthToken";
import { getDefaultBaseUrl, PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { supabase } from "@/shared/integrations/supabase/client";
import { usePostHogService } from "@/shared/services/posthogService";
import { createLocalCache } from "@/shared/utils/createLocalCache";

// Storage keys for manual overrides
const LOCAL_STORAGE_SERVICE_URL_KEY = "prometheux_service_url_override";
const LOCAL_STORAGE_AUTH_TOKEN_KEY = "prometheux_auth_token";

// Public auth-flow paths the user should be redirected away from once a session
// is established. Refreshing on a deep link (e.g. /editor/...) must NOT navigate.
const PUBLIC_AUTH_PATHS = [
  "/login",
  "/reset-password",
  "/mfa-challenge",
  "/databricks-oauth-callback",
] as const;

const isOnPublicAuthPath = (): boolean => {
  const path = window.location.pathname;
  return PUBLIC_AUTH_PATHS.some((p) => path === p || path.startsWith(`${p}/`));
};

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  signOut: () => Promise<void>;
  hasPlatformAccess: boolean;
  authToken: string | null;
  jupyterLabUrl: string | null;
  setIsLoginInProgress: (value: boolean) => void;
  setLoading: (value: boolean) => void;
  refreshPlatformAccess: () => Promise<boolean>;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  session: null,
  loading: true,
  signOut: async () => {},
  hasPlatformAccess: false,
  authToken: null,
  jupyterLabUrl: null,
  setIsLoginInProgress: () => {},
  setLoading: () => {},
  refreshPlatformAccess: async () => false,
});

export const useAuth = () => {
  return useContext(AuthContext);
};

interface PlatformAccessPayload {
  hasAccess: boolean;
  metadata: any;
}

interface JupyterLabAccessPayload {
  url: string | null;
}

interface UserOrganizationPayload {
  username: string;
  organization: string;
}

const TWELVE_HOURS_MS = 12 * 60 * 60 * 1000;
const TWENTY_FOUR_HOURS_MS = 24 * 60 * 60 * 1000;

const platformAccessCache = createLocalCache<PlatformAccessPayload>(
  "platform_access_cache",
  TWELVE_HOURS_MS,
  2,
);

const jupyterLabAccessCache = createLocalCache<JupyterLabAccessPayload>(
  "jupyterlab_access_cache",
  TWELVE_HOURS_MS,
);

const userOrganizationCache = createLocalCache<UserOrganizationPayload>(
  "user_organization_cache",
  TWENTY_FOUR_HOURS_MS,
);

export const AuthProvider = ({ children }: { children: React.ReactNode }) => {
  // 3P (SaaS Edition) autofill: hydrate the Databricks config from the app's
  // service-principal context endpoint. No-op in every other deployment mode.
  // Must be called unconditionally to satisfy the rules of hooks.
  useDatabricksAppContext();

  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [hasPlatformAccess, setHasPlatformAccess] = useState(false);
  // Read from the shared token rather than held here, so what this exposes is
  // always what requests actually carry.
  const authToken = useAuthToken();
  const [jupyterLabUrl, setJupyterLabUrl] = useState<string | null>(null);
  const [isLoginInProgress, setIsLoginInProgress] = useState(false);
  const [ssoError, setSsoError] = useState<{
    kind: "409" | "fatal";
    registeredOrganization?: string;
    message?: string;
  } | null>(null);
  const navigate = useNavigate();
  const { setupUser: setupPostHogUser } = usePostHogService();

  // Zero-click SSO for 3P (Databricks Marketplace) mode.
  // On AuthProvider mount, if no Supabase session is active yet, we ask
  // server.js to bridge the user's Databricks identity to a Supabase session
  // by calling the `databricks-sso` Edge Function. The returned token pair is
  // then handed to supabase.auth.setSession(), which triggers the normal
  // SIGNED_IN event and lets the existing flow take over (RequireAuth →
  // /onboarding pending until an admin approves the Platform application).
  useEffect(() => {
    if (!PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) return;

    let cancelled = false;
    (async () => {
      // Validate the cached session against the Supabase server (not just
      // against localStorage). getSession() reads localStorage and would
      // happily report a session whose user has been deleted backend-side
      // (e.g. during testing or after an admin-initiated removal). getUser()
      // hits the server and returns null in that case, letting the SSO
      // bridge transparently re-create the session. This makes the whole
      // flow self-healing: no need to clear browser cache after deleting a
      // test user.
      const {
        data: { user: validUser },
      } = await supabase.auth.getUser();
      if (validUser || cancelled) return;

      try {
        const r = await fetch("/api/prometheux-sso", {
          method: "POST",
          credentials: "same-origin",
        });
        const body = await r.json().catch(() => ({}));
        if (cancelled) return;

        if (r.status === 409) {
          setSsoError({
            kind: "409",
            registeredOrganization: body?.registered_organization,
          });
          setLoading(false);
          return;
        }
        if (!r.ok) {
          throw new Error(body?.error || body?.message || `sso_${r.status}`);
        }
        if (!body?.access_token || !body?.refresh_token) {
          throw new Error("sso_missing_tokens");
        }

        await supabase.auth.setSession({
          access_token: body.access_token,
          refresh_token: body.refresh_token,
        });
      } catch (err) {
        if (cancelled) return;
        console.error("[3p-sso] failed:", err);
        setSsoError({ kind: "fatal", message: String(err) });
        setLoading(false);
      }
    })();

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Skip authentication in Snowflake mode or development mode
  if (PROMETHEUX_CONFIG.SNOWFLAKE_MODE || PROMETHEUX_CONFIG.SKIP_AUTH) {
    let mockUser;

    if (PROMETHEUX_CONFIG.DATABRICKS_MODE) {
      // Extract username from Databricks domain pattern
      const extractDatabricksUsername = () => {
        const hostname = window.location.hostname;

        // Pattern: prometheux-7474655666244350.aws.databricksapps.com
        // We want to extract "7474655666244350" from this pattern
        const parts = hostname.split("-");
        if (parts.length >= 2) {
          // Get the second part (after app name, before domain)
          const workspaceId = parts[1].split(".")[0];
          return workspaceId;
        }

        return null;
      };

      const databricksUsername = extractDatabricksUsername();

      mockUser = {
        id: databricksUsername || "databricks-user",
        email: `${databricksUsername || "user"}@databricks.com`,
        username: databricksUsername || "databricks-user",
        organization: "databricks",
      };
    } else if (PROMETHEUX_CONFIG.SNOWFLAKE_MODE) {
      // Extract username from Snowflake domain pattern
      const extractSnowflakeUsername = () => {
        const hostname = window.location.hostname;

        // Pattern: mann5b-a7788582654371-iv35831.snowflakecomputing.app
        // We want to extract "iv35831" from this pattern
        const parts = hostname.split("-");
        if (parts.length >= 3) {
          // Get the last part before ".snowflakecomputing.app"
          const lastPart = parts[parts.length - 1].split(".")[0];
          return lastPart;
        }

        return null;
      };

      const snowflakeUsername = extractSnowflakeUsername();

      mockUser = {
        id: snowflakeUsername || "snowflake-user",
        email: `${snowflakeUsername || "user"}@snowflake.com`,
        username: snowflakeUsername || "snowflake-user",
        organization: "snowflake",
      };
    } else {
      // Development mode - use static mock user
      mockUser = {
        id: "dev-user",
        email: "dev@prometheux.com",
        username: "dev-user",
        organization: "prometheux",
      };
    }

    // Initialize PostHog with mock user — run once on mount only.
    // mockUser is a static object (derived from compile-time config / hostname),
    // so it never changes after the initial render. setupPostHogUser is stable
    // via useCallback and is idempotent for the same username.
    const mockUsername = mockUser.username;
    const mockId = mockUser.id;
    const mockOrganization = mockUser.organization;
    useEffect(() => {
      if (mockUsername) {
        setupPostHogUser({
          id: mockId,
          username: mockUsername,
          organization: mockOrganization || "unknown",
        });
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
      <AuthContext.Provider
        value={{
          user: mockUser,
          session: null,
          loading: false,
          signOut: async () => {},
          hasPlatformAccess: true,
          // The platform token this deployment ships with, not null: an embedded
          // app authenticates its requests with it like anywhere else.
          authToken: getAuthToken() || null,
          jupyterLabUrl: null,
          setIsLoginInProgress: () => {},
          setLoading: () => {},
          refreshPlatformAccess: async () => true,
        }}
      >
        {children}
      </AuthContext.Provider>
    );
  }

  const checkPlatformAccess = useCallback(
    async (
      userId: string,
      timeoutMs: number = 3000,
    ): Promise<{ hasAccess: boolean; metadata?: any }> => {
      try {
        // Check cache first
        const cachedResult = platformAccessCache.get(userId);
        if (cachedResult) {
          return { hasAccess: cachedResult.hasAccess, metadata: cachedResult.metadata };
        }

        // Add timeout to prevent hanging
        const timeoutPromise = new Promise<{ hasAccess: boolean; metadata?: any }>((_, reject) =>
          setTimeout(() => reject(new Error("Platform access check timeout")), timeoutMs),
        );

        const checkPromise = async (): Promise<{ hasAccess: boolean; metadata?: any }> => {
          // Use a single JOIN query to get both application and user access info including metadata
          const { data: userApp, error: userAppError } = await supabase
            .from("user_applications")
            .select(`
            status,
            user_id,
            application_id,
            metadata,
            applications!inner(id, name)
          `)
            .eq("user_id", userId)
            .eq("applications.name", "Platform")
            .single();

          if (userAppError) {
            return { hasAccess: false };
          }

          const hasAccess = userApp?.status?.toLowerCase() === "enabled";
          return { hasAccess, metadata: userApp?.metadata };
        };

        const result = (await Promise.race([checkPromise(), timeoutPromise])) as {
          hasAccess: boolean;
          metadata?: any;
        };

        // Cache the successful result
        platformAccessCache.set(userId, {
          hasAccess: result.hasAccess,
          metadata: result.metadata,
        });

        return result;
      } catch (error) {
        console.error("Error in checkPlatformAccess:", error);

        // Try to use cached result on error
        const cachedResult = platformAccessCache.get(userId);
        if (cachedResult) {
          return { hasAccess: cachedResult.hasAccess, metadata: cachedResult.metadata };
        }

        // In production, if there's a timeout and no cache, deny access for security
        if (import.meta.env.PROD && error.message.includes("timeout")) {
          return { hasAccess: false, metadata: null };
        }

        // In development or other errors with no cache, deny access for security
        return { hasAccess: false };
      }
    },
    [],
  );

  const checkJupyterLabAccess = useCallback(async (userId: string): Promise<string | null> => {
    try {
      // Check cache first
      const cachedResult = jupyterLabAccessCache.get(userId);
      if (cachedResult) {
        return cachedResult.url;
      }

      // Add timeout to prevent hanging (2 seconds for better UX)
      const timeoutPromise = new Promise<string | null>((_, reject) =>
        setTimeout(() => reject(new Error("JupyterLab access check timeout")), 2000),
      );

      const checkPromise = async (): Promise<string | null> => {
        // Query for JupyterLab application access
        const { data: userApp, error: userAppError } = await supabase
          .from("user_applications")
          .select(`
            status,
            metadata,
            applications!inner(id, name)
          `)
          .eq("user_id", userId)
          .eq("applications.name", "JupyterLab")
          .single();

        if (userAppError || !userApp) {
          return null;
        }

        const hasAccess = userApp?.status?.toLowerCase() === "enabled";
        if (!hasAccess) {
          return null;
        }

        // Extract URL from metadata
        const metadata = userApp.metadata as any;
        if (metadata?.url) {
          return metadata.url;
        }

        return null;
      };

      const result = (await Promise.race([checkPromise(), timeoutPromise])) as string | null;

      // Cache the result
      jupyterLabAccessCache.set(userId, { url: result });

      return result;
    } catch (error) {
      console.error("Error checking JupyterLab access:", error);

      // Try to use cached result on error
      const cachedResult = jupyterLabAccessCache.get(userId);
      if (cachedResult) {
        return cachedResult.url;
      }

      return null;
    }
  }, []);

  const refreshPlatformAccess = async (): Promise<boolean> => {
    if (!user?.id) {
      return false;
    }

    try {
      // Clear all caches to force fresh checks
      platformAccessCache.clear();
      jupyterLabAccessCache.clear();

      // Re-check platform access
      const { hasAccess, metadata } = await checkPlatformAccess(user.id);
      setHasPlatformAccess(hasAccess);

      // Re-check JupyterLab access
      const newJupyterLabUrl = await checkJupyterLabAccess(user.id);
      setJupyterLabUrl(newJupyterLabUrl);

      // If user has access, update configs based on metadata
      if (hasAccess && metadata) {
        try {
          const extractedUsername = metadata.username;
          const extractedOrganization = metadata.organization;
          const extractedToken = metadata.jwt;
          const apiUrl = metadata.url;

          // Check for manual overrides in localStorage
          const hasManualTokenOverride = localStorage.getItem(LOCAL_STORAGE_AUTH_TOKEN_KEY);
          const hasManualUrlOverride = localStorage.getItem(LOCAL_STORAGE_SERVICE_URL_KEY);

          // Set JWT token if available and not manually overridden
          if (extractedToken && !hasManualTokenOverride) {
            setAuthToken(extractedToken);
          }

          // Update BASE_URL from metadata if not manually overridden and not in local API mode
          if (
            extractedUsername &&
            extractedOrganization &&
            apiUrl &&
            !hasManualUrlOverride &&
            import.meta.env.VITE_LOCAL_API !== "true"
          ) {
            PROMETHEUX_CONFIG.BASE_URL = apiUrl;
          }
        } catch (error) {
          console.error("Error extracting metadata:", error);
        }
      }

      return hasAccess;
    } catch (error) {
      console.error("Error refreshing platform access:", error);
      return false;
    }
  };

  const signOut = async () => {
    // 3P (Databricks Marketplace) mode: capture the workspace URL BEFORE any
    // localStorage clearing so we can redirect the user back to their
    // Databricks workspace at the end. From the user's POV this looks like a
    // clean "exit back to Databricks" instead of dumping them on /login,
    // and it prevents the SSO bridge from immediately re-signing them in.
    let databricks3pRedirectUrl: string | null = null;
    if (PROMETHEUX_CONFIG.DATABRICKS_3P_MODE) {
      try {
        const raw = localStorage.getItem(APP_CONTEXT_DATA_KEY);
        if (raw) {
          const ctx = JSON.parse(raw) as AppPrincipalContext;
          if (ctx?.workspaceUrl) {
            databricks3pRedirectUrl = ctx.workspaceUrl;
          }
        }
      } catch {
        // ignore — we'll fall back to a default redirect below
      }
    }

    try {
      // Add timeout to prevent hanging
      const timeoutPromise = new Promise((_, reject) =>
        setTimeout(() => reject(new Error("SignOut timeout")), 3000),
      );

      const signOutPromise = supabase.auth.signOut();
      const { error } = (await Promise.race([signOutPromise, timeoutPromise])) as any;

      if (error) throw error;

      // Clear local state
      setUser(null);
      setSession(null);
      setHasPlatformAccess(false);
      clearAuthToken();
      setJupyterLabUrl(null);
      isProcessingSessionRef.current = false;
      permissionsFetchedForUserRef.current = null;
      usePermissionsStore.getState().clearPermissions();

      // Reset AI assistant session so the next login starts fresh
      useCodeAssistantStore.getState().closePanel();
      useCodeAssistantStore.getState().clearMessages();

      // Clear platform access cache
      platformAccessCache.clear();

      // Clear JupyterLab access cache
      jupyterLabAccessCache.clear();

      // Clear user organization cache
      userOrganizationCache.clear();

      // Clear manual overrides from settings
      localStorage.removeItem(LOCAL_STORAGE_AUTH_TOKEN_KEY);
      localStorage.removeItem(LOCAL_STORAGE_SERVICE_URL_KEY);

      // Clear Databricks configuration
      DatabricksConfigService.clearConfig();

      // Clear selected compute resources
      localStorage.removeItem("selectedMachineId");
      localStorage.removeItem("selectedCompute");

      // Reset BASE_URL to default
      PROMETHEUX_CONFIG.BASE_URL = getDefaultBaseUrl();

      // Clear Supabase storage manually as fallback
      localStorage.removeItem(
        `sb-${import.meta.env.VITE_SUPABASE_URL?.split("//")[1]?.split(".")[0]}-auth-token`,
      );
    } catch (error: any) {
      // Even if Supabase signOut fails, clear local state
      setUser(null);
      setSession(null);
      setHasPlatformAccess(false);
      clearAuthToken();
      isProcessingSessionRef.current = false;
      permissionsFetchedForUserRef.current = null;
      usePermissionsStore.getState().clearPermissions();

      // Reset AI assistant session so the next login starts fresh
      useCodeAssistantStore.getState().closePanel();
      useCodeAssistantStore.getState().clearMessages();

      // Clear manual overrides from settings
      localStorage.removeItem(LOCAL_STORAGE_AUTH_TOKEN_KEY);
      localStorage.removeItem(LOCAL_STORAGE_SERVICE_URL_KEY);

      // Clear Databricks configuration
      DatabricksConfigService.clearConfig();

      // Clear selected compute resources
      localStorage.removeItem("selectedMachineId");
      localStorage.removeItem("selectedCompute");

      // Reset BASE_URL to default
      PROMETHEUX_CONFIG.BASE_URL = getDefaultBaseUrl();

      // Clear Supabase storage manually as fallback
      localStorage.removeItem(
        `sb-${import.meta.env.VITE_SUPABASE_URL?.split("//")[1]?.split(".")[0]}-auth-token`,
      );

      // Only show error if it's not a timeout
      if (!error.message.includes("timeout")) {
      } else {
      }
    }

    // 3P (Databricks Marketplace) mode: bounce the user back to their
    // Databricks workspace. Without this they'd remain on this origin and
    // the SSO bridge would silently sign them right back in. window.location
    // navigation also discards any in-memory React state, which is what we
    // want after a logout.
    if (databricks3pRedirectUrl) {
      window.location.replace(databricks3pRedirectUrl);
    }
  };

  const isProcessingSessionRef = useRef(false);
  const permissionsFetchedForUserRef = useRef<string | null>(null);

  useEffect(() => {
    // Handle session changes (both initial and auth state changes)
    const handleSessionChange = async (session: Session) => {
      // Prevent duplicate processing
      if (isProcessingSessionRef.current) {
        return;
      }

      isProcessingSessionRef.current = true;

      try {
        setSession(session);

        // Check for cached user organization first
        const cachedUserOrg = userOrganizationCache.get(session.user.id);

        // Use basic user data from auth (no profiles table dependency)
        const userData = {
          id: session.user.id,
          email: session.user.email || "",
          username:
            cachedUserOrg?.username ||
            session.user.user_metadata?.username ||
            session.user.email?.split("@")[0],
          first_name: session.user.user_metadata?.first_name,
          last_name: session.user.user_metadata?.last_name,
          organization: cachedUserOrg?.organization, // Use cached organization if available
        };

        // Parallelize all database queries for faster performance
        let [platformAccessResult, jupyterLabUrl] = await Promise.all([
          checkPlatformAccess(session.user.id),
          checkJupyterLabAccess(session.user.id),
        ]);

        // Safety-net retry: if metadata is still missing after the first attempt (e.g. OAuth
        // flow where the session was just established), wait and retry with a generous timeout.
        if (!cachedUserOrg && !platformAccessResult.metadata?.organization) {
          platformAccessCache.clear();
          await new Promise((resolve) => setTimeout(resolve, 2000));
          const retryResult = await checkPlatformAccess(session.user.id, 10000);
          if (retryResult.metadata) {
            platformAccessResult = retryResult;
          }
        }

        // Extract JWT token and metadata from platform access result
        if (platformAccessResult.metadata) {
          try {
            const metadata = platformAccessResult.metadata;
            const extractedToken = metadata.jwt;
            const extractedUsername = metadata.username;
            const extractedOrganization = metadata.organization;
            const apiUrl = metadata.url;

            // Check for manual overrides in localStorage
            const hasManualTokenOverride = localStorage.getItem(LOCAL_STORAGE_AUTH_TOKEN_KEY);
            const hasManualUrlOverride = localStorage.getItem(LOCAL_STORAGE_SERVICE_URL_KEY);

            // Apply auth token from metadata only if not manually overridden
            if (extractedToken && !hasManualTokenOverride) {
              setAuthToken(extractedToken);
            } else if (hasManualTokenOverride) {
              // Apply the manual override
              setAuthToken(hasManualTokenOverride);
            }

            // Update BASE_URL and user data from metadata
            if (extractedUsername && extractedOrganization && apiUrl) {
              // Update user data with extracted values
              userData.username = extractedUsername;
              userData.organization = extractedOrganization;

              // Cache the user organization for future use
              userOrganizationCache.set(session.user.id, {
                username: extractedUsername,
                organization: extractedOrganization,
              });

              // Apply BASE_URL from metadata only if not manually overridden and not in local API mode
              if (hasManualUrlOverride) {
                PROMETHEUX_CONFIG.BASE_URL = hasManualUrlOverride;
              } else if (import.meta.env.VITE_LOCAL_API !== "true") {
                PROMETHEUX_CONFIG.BASE_URL = apiUrl;
              }
            }
          } catch (error) {
            console.error("Error extracting metadata:", error);
          }
        }

        // Guard: if SIGNED_OUT fired while we were awaiting (it resets the ref to false),
        // don't override the sign-out by re-setting user state.
        if (!isProcessingSessionRef.current) {
          return;
        }

        setUser(userData);

        // Fetch effective permissions once per user session.
        // If the login flow already fetched and set them (via useAuthHandlers),
        // skip the RPC and just navigate — avoids a redundant round-trip.
        if (permissionsFetchedForUserRef.current !== userData.id) {
          permissionsFetchedForUserRef.current = userData.id;

          const { loaded } = usePermissionsStore.getState();
          if (loaded) {
            if (isOnPublicAuthPath()) {
              const { defaultRoute } = usePermissionsStore.getState();
              if (defaultRoute) navigate(defaultRoute, { replace: true });
            }
          } else {
            supabase.rpc("get_user_effective_permissions").then(({ data, error }) => {
              if (error) {
                console.error("[permissions] error:", error);
                return;
              }
              usePermissionsStore.getState().setPermissions(data ?? []);
              if (isOnPublicAuthPath()) {
                const { defaultRoute } = usePermissionsStore.getState();
                if (defaultRoute) {
                  navigate(defaultRoute, { replace: true });
                }
              }
            });
          }
        }

        setHasPlatformAccess(platformAccessResult.hasAccess);
        setJupyterLabUrl(jupyterLabUrl);

        if (userData.username && userData.organization) {
          setupPostHogUser({
            id: userData.id,
            username: userData.username,
            organization: userData.organization,
            email: userData.email,
          });
        }

        // Keep loading true during login to prevent dashboard flash
        // Loading will be set to false by the login form after navigation
        if (!isLoginInProgress) {
          setLoading(false);
        }
      } finally {
        isProcessingSessionRef.current = false;
      }
    };

    // Set up listener FIRST, then check for existing session
    // Capture OAuth tokens immediately before they get cleared
    const capturedTokens = captureOAuthTokens();

    // 1. Set up auth state listener
    // IMPORTANT: Database queries (supabase.from()) must NOT run inside onAuthStateChange
    // callbacks. The Supabase client's internal auth state may not be fully settled when the
    // callback fires, causing queries to hang/timeout. We defer heavy work (handleSessionChange)
    // to the next event-loop tick so the client finishes its internal processing first.
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === "TOKEN_REFRESHED") {
        if (session) setSession(session);
        return;
      }
      if (event === "SIGNED_IN") {
        if (session) {
          setTimeout(async () => {
            const provider = session.user?.app_metadata?.provider;
            if (provider && provider !== "email") {
              await trackLogin(session.access_token, provider);
            }
            await handleSessionChange(session);
          }, 0);
        }
      } else if (event === "SIGNED_OUT") {
        // Clear state on sign out (lightweight state updates, no DB queries — safe inline)
        setUser(null);
        setSession(null);
        setHasPlatformAccess(false);
        clearAuthToken();
        setJupyterLabUrl(null);
        setLoading(false);
        isProcessingSessionRef.current = false;
        permissionsFetchedForUserRef.current = null;
        usePermissionsStore.getState().clearPermissions();
      } else if (event === "INITIAL_SESSION") {
        if (session) {
          // Defer to avoid same deadlock issue
          setTimeout(() => handleSessionChange(session), 0);
        } else {
          setLoading(false);
        }
      }
    });

    // 2. Process captured OAuth tokens if available
    if (capturedTokens) {
      supabase.auth
        .setSession({
          access_token: capturedTokens.access_token,
          refresh_token: capturedTokens.refresh_token,
        })
        .then(({ data, error }) => {
          if (error) {
            setLoading(false);
          } else {
            markTokensAsProcessed();
            // The onAuthStateChange listener will handle the rest
          }
        });
    } else {
      // 3. Check for existing session (only if no captured tokens)
      supabase.auth.getSession().then(({ data: { session }, error }) => {
        if (error) {
          setLoading(false);
          return;
        }

        if (session) {
          handleSessionChange(session);
        } else {
          setLoading(false);
        }
      });
    }

    return () => {
      subscription.unsubscribe();
    };
  }, [setupPostHogUser, isLoginInProgress, checkPlatformAccess, checkJupyterLabAccess]);

  // Create memoized context value to prevent unnecessary re-renders
  const contextValue = useMemo(
    () => ({
      user,
      session,
      loading,
      signOut,
      hasPlatformAccess,
      authToken,
      jupyterLabUrl,
      setIsLoginInProgress,
      setLoading,
      refreshPlatformAccess,
    }),
    [
      user,
      session,
      loading,
      signOut,
      hasPlatformAccess,
      authToken,
      jupyterLabUrl,
      refreshPlatformAccess,
    ],
  );

  if (ssoError?.kind === "409") {
    return (
      <DatabricksEmailConflictScreen registeredOrganization={ssoError.registeredOrganization} />
    );
  }
  if (ssoError?.kind === "fatal") {
    return <DatabricksSsoErrorScreen message={ssoError.message} />;
  }

  return <AuthContext.Provider value={contextValue}>{children}</AuthContext.Provider>;
};
