import { z } from "zod";

import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

// ── Schemas ─────────────────────────────────────────────────────────────
// Runtime validation at the boundary so the rest of the app sees a
// guaranteed shape. If the backend ever drifts (renamed field, dropped
// optional, etc.) we crash here with a clear message rather than silently
// reading undefined elsewhere.

const ScopeSchema = z.enum(["global", "ontology"]);

const InterviewQuestionSchema = z.object({
  id: z.string(),
  prompt: z.string(),
  placeholder: z.string(),
  helper: z.string().nullable(),
});

const InterviewTemplateSchema = z.object({
  scope: ScopeSchema,
  total: z.number().int().nonnegative(),
  questions: z.array(InterviewQuestionSchema),
});

const InterviewSubmitResultSchema = z.object({
  saved: z.array(z.string()),
  saved_count: z.number().int().nonnegative(),
  // `reused` covers the idempotency path: a re-submit of the same
  // (scope, scope_id, text) returns the existing note id rather than
  // creating a duplicate. The fields are optional for back-compat with
  // older backends that don't emit them.
  reused: z.array(z.string()).optional().default([]),
  reused_count: z.number().int().nonnegative().optional().default(0),
  skipped: z.array(z.string()),
  scope: ScopeSchema,
  scope_id: z.string().nullable(),
});

export type InterviewQuestion = z.infer<typeof InterviewQuestionSchema>;
export type InterviewTemplate = z.infer<typeof InterviewTemplateSchema>;
export type InterviewSubmitResult = z.infer<typeof InterviewSubmitResultSchema>;

export interface InterviewSubmitRequest {
  scope: "global" | "ontology";
  scope_id: string | null;
  answers: Record<string, string>;
}

// ── Envelope unwrap ─────────────────────────────────────────────────────

interface ApiEnvelope<T> {
  status: "success" | "error";
  data?: T;
  message?: string;
}

function unwrap<T>(response: ApiEnvelope<unknown>, schema: z.ZodType<T>, fallback: string): T {
  if (response.status !== "success" || response.data === undefined) {
    throw new Error(response.message ?? fallback);
  }
  const result = schema.safeParse(response.data);
  if (!result.success) {
    throw new Error(`${fallback}: response shape did not match schema (${result.error.message})`);
  }
  return result.data;
}

// ── Calls ───────────────────────────────────────────────────────────────

export async function fetchInterviewTemplate(
  scope: "global" | "ontology" = "global",
): Promise<InterviewTemplate> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/knowledge/interview/template?scope=${scope}`;
  const response: ApiEnvelope<unknown> = await HttpService.get(url);
  return unwrap(response, InterviewTemplateSchema, "Failed to load interview template");
}

export async function submitInterview(
  body: InterviewSubmitRequest,
): Promise<InterviewSubmitResult> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}/knowledge/interview`;
  const response: ApiEnvelope<unknown> = await HttpService.post(url, body);
  return unwrap(response, InterviewSubmitResultSchema, "Failed to save interview answers");
}
