export interface SparkUIStatus {
  running: boolean;
  message?: string;
  error?: string;
  spark_url?: string;
  proxy_url?: string;
}

export interface SparkJob {
  jobId: number;
  name: string;
  status: string;
  submissionTime?: string | number;
  completionTime?: string | number;
  numTasks?: number;
  numActiveTasks?: number;
  numCompletedTasks?: number;
  numFailedTasks?: number;
  numSkippedTasks?: number;
  numStages?: number;
  numCompletedStages?: number;
  numActiveStages?: number;
  numFailedStages?: number;
  numSkippedStages?: number;
  stageIds?: number[];
}

export interface SparkStage {
  stageId: number;
  attemptId?: number;
  status: string;
  name: string;
  numTasks?: number;
  numActiveTasks?: number;
  numCompleteTasks?: number;
  numFailedTasks?: number;
  submissionTime?: string | number;
  completionTime?: string | number;
}

export interface SparkExecutor {
  id: string;
  hostPort?: string;
  isActive?: boolean;
  rddBlocks?: number;
  memoryUsed?: number;
  diskUsed?: number;
  totalCores?: number;
  activeTasks?: number;
  failedTasks?: number;
  completedTasks?: number;
  totalTasks?: number;
  maxMemory?: number;
  addTime?: string | number;
  removeTime?: string | number;
}

export interface SparkApplication {
  id: string;
  name?: string;
  attempts?: Array<{
    startTime?: string | number;
    endTime?: string | number;
    lastUpdated?: string | number;
    duration?: number;
    sparkUser?: string;
    completed?: boolean;
    appSparkVersion?: string;
  }>;
}

export type SparkUIApiError = {
  status: "error";
  message: string;
  data?: { error_code?: string };
};

export interface TaskTotals {
  total: number;
  running: number;
  completed: number;
  failed: number;
}

export interface ActuatorMeasurement {
  statistic: string;
  value: number;
}

export interface ActuatorMetric {
  name: string;
  description?: string;
  baseUnit?: string | null;
  measurements: ActuatorMeasurement[];
}

export type HealthStatus = "UP" | "DOWN" | "OUT_OF_SERVICE" | "UNKNOWN";

export interface ActuatorHealth {
  status: HealthStatus;
  components?: Record<string, { status: HealthStatus }>;
}

export interface RuntimeSample {
  ts: number;
  cpu: number | null;
  memoryUsed: number | null;
}

export interface RuntimeState {
  health: ActuatorHealth | null;
  cpu: number | null;
  cpuCount: number | null;
  memoryUsed: number | null;
  memoryMax: number | null;
  samples: RuntimeSample[];
  isTriggeringGc: boolean;
  gcLastTriggeredAt: number | null;
}

export const LOG_LEVELS = ["OFF", "ERROR", "WARN", "INFO", "DEBUG", "TRACE"] as const;
export type LogLevel = (typeof LOG_LEVELS)[number];

export interface EngineMonitorSnapshot {
  status: SparkUIStatus | null;
  jobs: SparkJob[];
  executors: SparkExecutor[];
  applications: SparkApplication[];
  runtime: RuntimeState;
  isLoading: boolean;
  lastUpdatedAt: number | null;
  error: string | null;
}
