import { create } from "zustand";
import type { AppDefinition } from "../schema/appDefinition.types";
import type { EditorSelection, EditorView } from "./appEditor.types";

export type EditorLeftPanel = "structure" | "data" | "concepts";
export type EditorRightPanel = "inspector" | "versions";

/**
 * Draft state for the v2 app editor (ADR D7). The draft is the single source
 * of truth for all three panes; mutations go through pure helpers in
 * appEditorMutations.ts via `updateDraft`. Saving is the caller's job
 * (useAppEditorSave) — the store only tracks the last-saved snapshot so the
 * toolbar can show dirtiness.
 */
interface AppEditorState {
  draft: AppDefinition | null;
  /** JSON of the last saved (or freshly loaded) definition, for dirty checks. */
  savedSnapshot: string;
  selection: EditorSelection | null;
  activePageId: string;
  view: EditorView;
  /** Preview interaction mode: false = click selects, true = widgets behave live. */
  interactMode: boolean;
  /** Docked side panels (lineage-rail pattern); null = collapsed to the rail. */
  leftPanel: EditorLeftPanel | null;
  rightPanel: EditorRightPanel | null;
  /** Set while the JSON pane holds unparseable text — the draft is stale, so
   * saving must be refused until the JSON parses again. */
  jsonParseError: string | null;

  initDraft: (definition: AppDefinition) => void;
  updateDraft: (update: (draft: AppDefinition) => AppDefinition) => void;
  /** Replace the whole draft (JSON pane apply, version restore). */
  replaceDraft: (definition: AppDefinition) => void;
  markSaved: () => void;
  select: (selection: EditorSelection | null) => void;
  setActivePage: (pageId: string) => void;
  setView: (view: EditorView) => void;
  setInteractMode: (interact: boolean) => void;
  setLeftPanel: (panel: EditorLeftPanel | null) => void;
  setRightPanel: (panel: EditorRightPanel | null) => void;
  setJsonParseError: (error: string | null) => void;
  reset: () => void;
}

export const useAppEditorStore = create<AppEditorState>((set) => ({
  draft: null,
  savedSnapshot: "",
  selection: null,
  activePageId: "",
  view: "visual",
  interactMode: false,
  leftPanel: "structure",
  rightPanel: "inspector",
  jsonParseError: null,

  initDraft: (definition) =>
    set({
      draft: definition,
      savedSnapshot: JSON.stringify(definition),
      selection: null,
      activePageId: definition.pages[0]?.id ?? "",
      view: "visual",
      interactMode: false,
      leftPanel: "structure",
      rightPanel: "inspector",
      jsonParseError: null,
    }),

  updateDraft: (update) => set((state) => (state.draft ? { draft: update(state.draft) } : {})),

  replaceDraft: (definition) =>
    set((state) => ({
      draft: definition,
      selection: null,
      activePageId: definition.pages.some((page) => page.id === state.activePageId)
        ? state.activePageId
        : (definition.pages[0]?.id ?? ""),
    })),

  markSaved: () =>
    set((state) => (state.draft ? { savedSnapshot: JSON.stringify(state.draft) } : {})),

  select: (selection) =>
    set((state) => ({
      selection,
      // Selecting something on another page follows it in the preview.
      activePageId:
        selection && selection.kind !== "app" && selection.pageId !== state.activePageId
          ? selection.pageId
          : state.activePageId,
      // Selecting a node means the user wants to edit it — surface the
      // inspector even if the right dock was collapsed or showing versions.
      rightPanel: selection ? "inspector" : state.rightPanel,
    })),

  setActivePage: (pageId) => set({ activePageId: pageId }),

  setJsonParseError: (error) => set({ jsonParseError: error }),
  setView: (view) => set({ view }),
  setInteractMode: (interact) => set({ interactMode: interact }),
  setLeftPanel: (panel) => set({ leftPanel: panel }),
  setRightPanel: (panel) => set({ rightPanel: panel }),

  reset: () =>
    set({
      draft: null,
      savedSnapshot: "",
      selection: null,
      activePageId: "",
      view: "visual",
      interactMode: false,
      leftPanel: "structure",
      rightPanel: "inspector",
      jsonParseError: null,
    }),
}));
