import type { ElementType, ReactNode } from "react";
import { NotificationBell } from "@/features/notifications/components/NotificationBell";

export interface PageHeaderProps {
  title?: string;
  subtitle?: string;
  icon?: ElementType;
  actions?: ReactNode;
  /** Replaces the icon+title section with fully custom content */
  left?: ReactNode;
}

export function PageHeader({ title, subtitle, icon: Icon, actions, left }: PageHeaderProps) {
  if (!title && !left) return null;

  return (
    <header className="relative z-20 flex h-[56px] max-h-[56px] min-h-[56px] shrink-0 flex-nowrap items-center justify-between gap-3 border-b bg-card px-6">
      <div className="flex min-w-0 flex-1 items-center gap-3 overflow-hidden">
        {left ?? (
          <>
            {Icon && <Icon className="h-5 w-5 text-muted-foreground" />}
            <div>
              <h1 className="font-bold leading-tight">{title}</h1>
              {subtitle && <p className="text-xs text-muted-foreground">{subtitle}</p>}
            </div>
          </>
        )}
      </div>
      {/* Right region: page-specific actions + the global notification bell
          (rendered here so it appears on every page that has a header). */}
      <div className="flex min-w-0 shrink-0 flex-nowrap items-center gap-2">
        {actions}
        <NotificationBell />
      </div>
    </header>
  );
}
