import { useQuery } from "@tanstack/react-query";
import { AppWindow, ChevronRight } from "lucide-react";
import type React from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { useResolvedAppMeta } from "@/features/dashboards/remotes/useResolvedAppMeta";
import { DashboardClient } from "@/features/dynamic-dashboard/api/DashboardClient";
import { guardSidebarNavClick } from "@/features/engine-status/engineStatus";
import { cn } from "@/shared/lib/utils";
import { useSidebarStore } from "@/shared/store/sidebarStore";

const dashboardClient = new DashboardClient();

interface SidebarAppsItemProps {
  collapsed: boolean;
}

/**
 * The single Apps nav entry (ADR D10): one catalog for dynamic apps (built
 * in-platform) and federated apps (runtime remotes) — the expanded sublist
 * mixes both without distinction. Visible for can_see/can_edit_dynamic_dashboards
 * or any can_see_<id>_app permission.
 */
export function SidebarAppsItem({ collapsed }: SidebarAppsItemProps) {
  const location = useLocation();
  const navigate = useNavigate();
  const { appsExpanded, setAppsExpanded } = useSidebarStore();
  const visibleApps = usePermissionsStore((state) => state.visibleApps);
  const canSeeDynamicApps = usePermissionsStore(
    (state) =>
      state.canSee("can_see_dynamic_dashboards") || state.canEdit("can_edit_dynamic_dashboards"),
  );
  const appMeta = useResolvedAppMeta(visibleApps);

  const { data: dynamicApps = [] } = useQuery({
    queryKey: ["all-dashboards"],
    queryFn: () => dashboardClient.listAllDashboards(),
    enabled: canSeeDynamicApps,
    staleTime: 30_000,
  });

  const isAppsPage = location.pathname.startsWith("/apps");

  const handleNavClick = (to: string) => (e: React.MouseEvent<HTMLAnchorElement>) => {
    void guardSidebarNavClick(e, () => navigate(to));
  };

  if (visibleApps.length === 0 && !canSeeDynamicApps) return null;

  if (collapsed) {
    return (
      <Link
        to="/apps"
        onClick={handleNavClick("/apps")}
        title="Apps"
        className={cn(
          "flex h-9 w-full items-center justify-center rounded-md text-sm font-medium text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
          isAppsPage && "bg-primary/10 text-primary",
        )}
      >
        <AppWindow className="h-4 w-4 shrink-0" />
      </Link>
    );
  }

  const sublinks = [
    ...dynamicApps.map((app) => ({
      key: `${app.ontologyId}-${app.id}`,
      href: `/apps/${app.ontologyId}/${app.id}`,
      name: app.name,
    })),
    ...visibleApps.map((app) => ({
      key: app.id,
      href: `/apps/${app.id}`,
      name: appMeta[app.id]?.name ?? app.name,
    })),
  ];

  return (
    <>
      <div className="flex h-9 items-center">
        <Link
          to="/apps"
          onClick={handleNavClick("/apps")}
          className={cn(
            "flex flex-1 items-center gap-3 rounded-md px-2 h-full text-sm font-medium text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
            isAppsPage && "bg-primary/10 text-primary",
          )}
        >
          <AppWindow className="h-4 w-4 shrink-0" />
          <span className="truncate">Apps</span>
        </Link>
        {sublinks.length > 0 && (
          <button
            type="button"
            onClick={() => setAppsExpanded(!appsExpanded)}
            title={appsExpanded ? "Collapse apps" : "Expand apps"}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
          >
            <ChevronRight
              className={cn(
                "h-3.5 w-3.5 transition-transform duration-150",
                appsExpanded && "rotate-90",
              )}
            />
          </button>
        )}
      </div>

      {appsExpanded && sublinks.length > 0 && (
        <div className="ml-5 mr-1 mt-0.5 space-y-0.5">
          {sublinks.map((app) => (
            <Link
              key={app.key}
              to={app.href}
              onClick={handleNavClick(app.href)}
              className={cn(
                "flex h-8 w-full items-center gap-2 rounded-md px-2 text-sm text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
                location.pathname === app.href && "bg-primary/10 text-primary",
              )}
            >
              <AppWindow className="h-3.5 w-3.5 shrink-0 opacity-60" />
              <span className="truncate">{app.name}</span>
            </Link>
          ))}
        </div>
      )}
    </>
  );
}
