import type { LlmRunTruncation } from "@/features/concept-editor/types";

/**
 * Just the run-payload keys this reads, so the util does not have to depend on
 * the whole response type.
 */
interface TruncationKeys {
  llm_prompt_truncation?: LlmRunTruncation["prompt"];
  llm_output_truncated?: boolean;
  llm_max_tokens?: number | null;
}

/**
 * Fold the run payload's three `llm_*` truncation keys into one object, or
 * `undefined` when nothing was cut.
 *
 * Returning `undefined` rather than a zeroed object matters: the strip renders
 * on presence, so an object that merely says "nothing was truncated" would put a
 * permanent empty warning slot under every prompt.
 */
export function buildLlmTruncation(data: TruncationKeys | undefined): LlmRunTruncation | undefined {
  const prompt = data?.llm_prompt_truncation ?? null;
  const output = Boolean(data?.llm_output_truncated);
  if (!prompt && !output) return undefined;

  return { prompt, output, maxTokens: data?.llm_max_tokens ?? null };
}
