import type {
  ConceptGraphRole,
  ConceptGraphRoles,
  ConceptGraphSpec,
  GraphViewModel,
} from "./types";

export function emptyModel(scope: string): GraphViewModel {
  return { version: 1, scope, node_types: [], edge_types: [] };
}

export function findConceptGraph(
  model: GraphViewModel | null | undefined,
  predicate: string,
): ConceptGraphSpec | undefined {
  return model?.concept_graphs?.find((spec) => spec.predicate === predicate);
}

export function upsertConceptGraph(model: GraphViewModel, spec: ConceptGraphSpec): GraphViewModel {
  const existing = model.concept_graphs ?? [];
  const exists = existing.some((entry) => entry.predicate === spec.predicate);
  const conceptGraphs = exists
    ? existing.map((entry) => (entry.predicate === spec.predicate ? spec : entry))
    : [...existing, spec];
  return { ...model, concept_graphs: conceptGraphs };
}

/**
 * Assign a role to a column. A role can only belong to one column, and a
 * column can only hold one role — both previous holders are cleared.
 */
export function assignConceptGraphRole(
  roles: ConceptGraphRoles,
  role: ConceptGraphRole,
  column: string,
): ConceptGraphRoles {
  const cleared: ConceptGraphRoles = {
    source_column: roles.source_column === column ? undefined : roles.source_column,
    target_column: roles.target_column === column ? undefined : roles.target_column,
    edge_label_column: roles.edge_label_column === column ? undefined : roles.edge_label_column,
  };
  if (role === "source") return { ...cleared, source_column: column };
  if (role === "target") return { ...cleared, target_column: column };
  return { ...cleared, edge_label_column: column };
}

export function clearConceptGraphRole(roles: ConceptGraphRoles, column: string): ConceptGraphRoles {
  return {
    source_column: roles.source_column === column ? undefined : roles.source_column,
    target_column: roles.target_column === column ? undefined : roles.target_column,
    edge_label_column: roles.edge_label_column === column ? undefined : roles.edge_label_column,
  };
}

export function roleForColumn(roles: ConceptGraphRoles, column: string): ConceptGraphRole | null {
  if (roles.source_column === column) return "source";
  if (roles.target_column === column) return "target";
  if (roles.edge_label_column === column) return "edge_label";
  return null;
}

export function conceptGraphReady(roles: ConceptGraphRoles): boolean {
  return Boolean(roles.source_column && roles.target_column);
}

/**
 * Resolve role column names to the positional indices the build-graph
 * endpoint expects. Returns null when a required column is missing from
 * the concept's current column list (e.g. after a schema change).
 */
export function conceptGraphRoleIndices(
  roles: ConceptGraphRoles,
  columns: string[],
): { source: number; target: number; edge_value?: number } | null {
  if (!roles.source_column || !roles.target_column) return null;
  const source = columns.indexOf(roles.source_column);
  const target = columns.indexOf(roles.target_column);
  if (source < 0 || target < 0) return null;
  const edgeValue = roles.edge_label_column ? columns.indexOf(roles.edge_label_column) : -1;
  if (edgeValue >= 0) return { source, target, edge_value: edgeValue };
  return { source, target };
}
