import { type ReactNode, useState } from "react";
import { Table } from "@/shared/components/ui/table";
import type { FetchResult } from "../../api/ConceptClient";
import { TableOutputBody } from "./table/TableOutputBody";
import { TableOutputHeader } from "./table/TableOutputHeader";
import { TableOutputPagination } from "./table/TableOutputPagination";
import { TableOutputSearch } from "./table/TableOutputSearch";
import type {
  BoundTableHandlers,
  ColumnFilterValue,
  FilterOperator,
} from "./table/tableOutput.types";
import { toggleColumnSort } from "./table/tableOutput.utils";

interface TableOutputProps {
  data: FetchResult;
  handlers?: BoundTableHandlers;
  /**
   * "full" (default): search + sortable/filterable header + pagination.
   * "compact": sortable header + pagination, no search bar.
   * "plain": bare table — detail/kv panels.
   */
  chrome?: "full" | "compact" | "plain";
  renderCell?: (cell: unknown, rowIndex: number, columnIndex: number) => ReactNode;
  onRowClick?: (rowIndex: number) => void;
  rowClassName?: (rowIndex: number) => string | undefined;
}

function deriveColumns(data: FetchResult): string[] {
  if (data.columnNames.length > 0) return data.columnNames;
  const firstRow = data.rows[0];
  if (!firstRow) return [];
  return firstRow.map((_, i) => `col_${i + 1}`);
}

export function TableOutput({
  data,
  handlers,
  chrome = "full",
  renderCell,
  onRowClick,
  rowClassName,
}: TableOutputProps) {
  const [busy, setBusy] = useState(false);
  const columns = deriveColumns(data);
  const supportsControls = !!handlers && chrome !== "plain";
  const showSearch = supportsControls && chrome === "full";

  const runHandler = async (work: () => Promise<void>) => {
    setBusy(true);
    try {
      await work();
    } finally {
      setBusy(false);
    }
  };

  const handlePageChange = (page: number) => {
    if (!handlers) return;
    runHandler(() => handlers.onPageChange(page));
  };

  const handlePageSizeChange = (pageSize: number) => {
    if (!handlers) return;
    runHandler(() => handlers.onPageSizeChange(pageSize));
  };

  const handleSort = (columnIndex: number, direction: "asc" | "desc" | null) => {
    if (!handlers) return;
    const next = toggleColumnSort(data.orderBy, columnIndex, direction);
    runHandler(() => handlers.onSort(next));
  };

  const handleApplyFilter = (columnIndex: number, value: string, operator: FilterOperator) => {
    if (!handlers) return;
    const existing = data.searchState?.columnFilters ?? {};
    const nextFilters: Record<number, ColumnFilterValue> = {
      ...existing,
      [columnIndex]: { value, operator },
    };
    runHandler(() => handlers.onSearch(undefined, nextFilters));
  };

  const handleClearColumnFilter = (columnIndex: number) => {
    if (!handlers) return;
    const existing = data.searchState?.columnFilters ?? {};
    const next: Record<number, ColumnFilterValue> = { ...existing };
    delete next[columnIndex];
    if (Object.keys(next).length === 0) {
      runHandler(() => handlers.onClearSearch());
      return;
    }
    runHandler(() => handlers.onSearch(undefined, next));
  };

  const handleSearch = (searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) => {
    if (!handlers) return;
    runHandler(() => handlers.onSearch(searchTerm, columnFilters));
  };

  const handleClearSearch = () => {
    if (!handlers) return;
    runHandler(() => handlers.onClearSearch());
  };

  return (
    <div className="flex flex-col gap-2">
      {showSearch && (
        <TableOutputSearch
          columns={columns}
          searchState={data.searchState}
          onSearch={handleSearch}
          onClearSearch={handleClearSearch}
          onClearColumnFilter={handleClearColumnFilter}
        />
      )}

      <div className="border border-border rounded-lg overflow-auto max-h-[420px]">
        <Table>
          {supportsControls ? (
            <TableOutputHeader
              columns={columns}
              orderBy={data.orderBy}
              columnFilters={data.searchState?.columnFilters}
              onApplyFilter={handleApplyFilter}
              onClearFilter={handleClearColumnFilter}
              onSort={handleSort}
            />
          ) : (
            <PlainHeader columns={columns} />
          )}
          <TableOutputBody
            columns={columns}
            rows={data.rows}
            renderCell={renderCell}
            onRowClick={onRowClick}
            rowClassName={rowClassName}
          />
        </Table>
      </div>

      {supportsControls && (
        <TableOutputPagination
          page={data.page}
          totalPages={data.totalPages}
          totalCount={data.totalCount}
          pageSize={data.pageSize}
          hasNext={data.hasNext}
          isBusy={busy}
          onPageChange={handlePageChange}
          onPageSizeChange={handlePageSizeChange}
        />
      )}
    </div>
  );
}

function PlainHeader({ columns }: { columns: string[] }) {
  return (
    <thead>
      <tr>
        {columns.map((col, i) => (
          <th
            key={i}
            className="h-9 px-3 text-left align-middle font-medium text-muted-foreground whitespace-nowrap text-xs"
          >
            {col}
          </th>
        ))}
      </tr>
    </thead>
  );
}
