import { Braces, ExternalLink, LayoutPanelLeft, Save, X } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { cn } from "@/shared/lib/utils";
import { useAppEditorStore } from "../../store/appEditorStore";

interface EditorToolbarProps {
  isDirty: boolean;
  isSaving: boolean;
  onSave: () => void;
  onCancel: () => void;
  onOpenApp: () => void;
}

/**
 * Top bar of the app editor. Save + Cancel sit top-right (the product's
 * edit-surface convention). Definition file round-trips live on the apps
 * catalog: export on the card, import in the page header.
 */
export function EditorToolbar({
  isDirty,
  isSaving,
  onSave,
  onCancel,
  onOpenApp,
}: EditorToolbarProps) {
  const view = useAppEditorStore((state) => state.view);
  const setView = useAppEditorStore((state) => state.setView);
  const interactMode = useAppEditorStore((state) => state.interactMode);
  const setInteractMode = useAppEditorStore((state) => state.setInteractMode);

  return (
    <div className="flex items-center gap-2 px-6 py-2.5 border-b border-border flex-shrink-0 bg-card">
      <Button size="sm" variant="outline" onClick={onOpenApp} className="gap-2 h-7">
        <ExternalLink className="h-3.5 w-3.5" />
        Open app
      </Button>
      {isDirty && (
        <span className="text-[11px] text-amber-600 dark:text-amber-400">Unsaved changes</span>
      )}

      <div className="ml-auto flex items-center gap-2">
        {view === "visual" && (
          <div className="flex rounded-md border border-border overflow-hidden">
            <ModeButton active={!interactMode} onClick={() => setInteractMode(false)}>
              Select
            </ModeButton>
            <ModeButton active={interactMode} onClick={() => setInteractMode(true)}>
              Interact
            </ModeButton>
          </div>
        )}
        <div className="flex rounded-md border border-border overflow-hidden">
          <ModeButton active={view === "visual"} onClick={() => setView("visual")}>
            <LayoutPanelLeft className="h-3 w-3" />
            Visual
          </ModeButton>
          <ModeButton active={view === "json"} onClick={() => setView("json")}>
            <Braces className="h-3 w-3" />
            JSON
          </ModeButton>
        </div>
        <Button
          size="sm"
          variant="ghost"
          onClick={onCancel}
          className="gap-1.5 h-7 text-muted-foreground"
        >
          <X className="h-3.5 w-3.5" />
          Cancel
        </Button>
        <Button size="sm" onClick={onSave} disabled={isSaving} className="gap-2 h-7">
          {isSaving ? <PrometheuxSpinner size={13} /> : <Save className="h-3.5 w-3.5" />}
          {isSaving ? "Validating…" : "Save app"}
        </Button>
      </div>
    </div>
  );
}

interface ModeButtonProps {
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}

function ModeButton({ active, onClick, children }: ModeButtonProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "flex items-center gap-1.5 px-2.5 py-1 text-[11px] font-medium transition-colors",
        active
          ? "bg-secondary text-foreground"
          : "bg-transparent text-muted-foreground hover:text-foreground",
      )}
    >
      {children}
    </button>
  );
}
