import {
  AlertCircle,
  AlertTriangle,
  Copy,
  FileText,
  Lock,
  RefreshCw,
  Upload,
  User,
  Users,
  X,
} from "lucide-react";
import type React from "react";
import { useMemo, useState } from "react";
import { toast } from "sonner";
import { ContextNoteApi } from "@/features/context-layer/api";
import FailedDatasourcesDialog from "@/features/data-sources/components/FailedDatasourcesDialog";
import type { OntologyData, OntologyScope } from "@/features/ontologies/api";
import { useOntologyImport } from "@/features/ontologies/hooks/useOntologyImport";
import { Alert, AlertDescription } from "@/shared/components/ui/alert";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/components/ui/tabs";
import { Textarea } from "@/shared/components/ui/textarea";

interface CreateOntologyDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onCreateOntology: (
    name: string,
    description: string,
    scope: OntologyScope,
  ) => Promise<string | undefined> | string | undefined | void;
  onOntologyImported?: () => void;
  defaultScope?: OntologyScope;
  existingOntologies?: OntologyData[];
}

const CreateOntologyDialog: React.FC<CreateOntologyDialogProps> = ({
  isOpen,
  onClose,
  onCreateOntology,
  onOntologyImported,
  defaultScope = "user",
  existingOntologies = [],
}) => {
  const [ontologyName, setOntologyName] = useState("");
  const [ontologyDescription, setOntologyDescription] = useState("");
  const [ontologyContext, setOntologyContext] = useState("");
  const [scope, setScope] = useState<OntologyScope>(defaultScope);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<"create" | "import">("create");

  const {
    isImporting,
    selectedFile,
    fileInputRef,
    failedDatasources,
    dismissFailedDatasources,
    importConflict,
    conflictOntologyName,
    handleFileSelect,
    handleImport,
    handleConflictOverwrite,
    handleConflictCopy,
    handleConflictCancel,
    clearFileSelection,
  } = useOntologyImport({ scope, existingOntologies, onImported: onOntologyImported, onClose });

  const isSnowflakeDomain = useMemo(() => {
    const hostname = window.location.hostname;
    return hostname.includes("snowflakecomputing.app");
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!ontologyName.trim()) {
      toast.error("Ontology name cannot be empty");
      return;
    }

    if (ontologyDescription.trim().length > 1000) {
      toast.error("Ontology description cannot exceed 1000 characters");
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      const description = ontologyDescription.trim() || "";
      const context = ontologyContext.trim();
      const createdOntologyId = await onCreateOntology(ontologyName.trim(), description, scope);

      // Project-scoped context can only be saved AFTER the project exists
      // (the note's scope_id is the new project's id). If the parent
      // handler returned an id and the user provided context, persist it.
      // A failure here doesn't roll back the project — surface it as a
      // soft error so the user knows to retry from Settings.
      if (createdOntologyId && context) {
        try {
          await ContextNoteApi.create({
            scope: "ontology",
            scope_id: createdOntologyId,
            kind: "fact",
            text: context,
          });
        } catch (contextError) {
          const message = contextError instanceof Error ? contextError.message : "Unknown error";
          toast.error(
            `Ontology created, but saving the initial context failed: ${message}. ` +
              `Add it from the Context page.`,
          );
        }
      }

      setOntologyName("");
      setOntologyDescription("");
      setOntologyContext("");
      onClose();
      toast.success(`Ontology "${ontologyName}" created successfully`);
    } catch (error) {
      setError(error instanceof Error ? error.message : "Failed to create ontology");
      toast.error("Failed to create ontology");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleScopeChange = (value: OntologyScope) => {
    if (value === "organization") return;
    setScope(value);
  };

  return (
    <>
      {/* Import conflict dialog */}
      <Dialog
        open={importConflict !== null}
        onOpenChange={(open) => {
          if (!open) handleConflictCancel();
        }}
      >
        <DialogContent className="p-0 max-w-[480px] overflow-hidden [&>button]:hidden">
          <div className="min-w-0 flex items-center justify-between border-b border-border bg-amber-100 px-5 py-3 dark:bg-amber-900/30">
            <div className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-amber-600 dark:text-amber-400" />
              <h2 className="text-base font-bold text-foreground">Ontology Already Exists</h2>
            </div>
            <button
              type="button"
              onClick={handleConflictCancel}
              className="flex items-center justify-center h-6 w-6 rounded-full hover:bg-black/10 transition-colors"
              aria-label="Close"
            >
              <X className="h-4 w-4 text-foreground" />
            </button>
          </div>
          <div className="min-w-0 p-6 bg-card space-y-4">
            <p className="text-sm">
              A project named <strong>{conflictOntologyName}</strong> already exists. How would you
              like to proceed?
            </p>
            <div className="space-y-2">
              <Button
                onClick={handleConflictOverwrite}
                disabled={isImporting}
                isLoading={isImporting}
                variant="outline"
                className="w-full justify-start gap-3 h-auto py-3 px-4"
              >
                <RefreshCw className="h-4 w-4 shrink-0" />
                <div className="min-w-0 text-left">
                  <div className="font-medium">Overwrite existing ontology</div>
                  <div className="text-xs text-muted-foreground whitespace-normal">
                    All existing concepts, ontology schema, and apps will be replaced with the
                    imported file. This cannot be undone.
                  </div>
                </div>
              </Button>
              <Button
                onClick={handleConflictCopy}
                disabled={isImporting}
                isLoading={isImporting}
                variant="outline"
                className="w-full justify-start gap-3 h-auto py-3 px-4"
              >
                <Copy className="h-4 w-4 shrink-0" />
                <div className="min-w-0 text-left">
                  <div className="font-medium">Import as a new ontology</div>
                  <div className="text-xs text-muted-foreground whitespace-normal">
                    Create a copy with a new ID, keeping the original untouched
                  </div>
                </div>
              </Button>
            </div>
            <div className="flex justify-end pt-2">
              <Button variant="outline" onClick={handleConflictCancel} disabled={isImporting}>
                Cancel
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      <FailedDatasourcesDialog
        failedDatasources={failedDatasources}
        onClose={dismissFailedDatasources}
      />

      <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
        <DialogContent className="p-0 sm:max-w-[520px] overflow-hidden [&>button]:hidden">
          <DialogTitle className="sr-only">New Ontology</DialogTitle>
          {/* Yellow header bar */}
          <div
            style={{ background: "#FFDF4B", padding: "12px 20px" }}
            className="flex items-center justify-between border-b border-border"
          >
            <h2 className="text-base font-bold text-[#212020]">New Ontology</h2>
            <button
              type="button"
              onClick={onClose}
              className="flex items-center justify-center h-6 w-6 rounded-full hover:bg-black/10 transition-colors"
              aria-label="Close"
            >
              <X className="h-4 w-4 text-[#212020]" />
            </button>
          </div>

          {/* Body */}
          <div className="p-6 bg-card">
            <Tabs
              value={activeTab}
              onValueChange={(v) => setActiveTab(v as "create" | "import")}
              className="w-full"
            >
              <TabsList className="grid w-full grid-cols-2 mb-4">
                <TabsTrigger value="create">Create</TabsTrigger>
                <TabsTrigger value="import">Import</TabsTrigger>
              </TabsList>

              <TabsContent value="create" className="mt-0">
                <form onSubmit={handleSubmit}>
                  <div className="grid gap-4">
                    <div className="grid grid-cols-4 items-center gap-4">
                      <Label htmlFor="name" className="text-right text-sm font-medium">
                        Name
                      </Label>
                      <Input
                        id="name"
                        value={ontologyName}
                        onChange={(e) => setOntologyName(e.target.value)}
                        className="col-span-3"
                        placeholder="My Ontology"
                        autoFocus={activeTab === "create"}
                      />
                    </div>

                    <div className="grid grid-cols-4 items-start gap-4">
                      <Label htmlFor="description" className="text-right text-sm font-medium mt-2">
                        Description
                      </Label>
                      <Textarea
                        id="description"
                        value={ontologyDescription}
                        onChange={(e) => setOntologyDescription(e.target.value)}
                        className="col-span-3 resize-none"
                        placeholder="Optional ontology description..."
                        rows={3}
                      />
                    </div>

                    <div className="grid grid-cols-4 items-start gap-4">
                      <Label htmlFor="context" className="text-right text-sm font-medium mt-2">
                        Context
                      </Label>
                      <div className="col-span-3 space-y-1">
                        <Textarea
                          id="context"
                          value={ontologyContext}
                          onChange={(e) => setOntologyContext(e.target.value)}
                          className="resize-y"
                          placeholder="What's this ontology for? Key questions, definitions, or domain notes the assistant should keep in mind."
                          rows={4}
                        />
                        <p className="text-xs text-muted-foreground">
                          Optional. Saved as a project-scoped note the assistant reads on every
                          turn. Edit later on the Context page.
                        </p>
                      </div>
                    </div>

                    <div className="grid grid-cols-4 items-center gap-4">
                      <Label htmlFor="scope" className="text-right text-sm font-medium">
                        Scope
                      </Label>
                      <Select value={scope} onValueChange={handleScopeChange}>
                        <SelectTrigger className="col-span-3">
                          <SelectValue placeholder="Select scope" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="user">
                            <div className="flex items-center">
                              <User className="mr-2 h-4 w-4" />
                              <span>User Scope</span>
                            </div>
                          </SelectItem>
                          {!isSnowflakeDomain && (
                            <SelectItem value="organization" disabled>
                              <div className="flex items-center opacity-50">
                                <Users className="mr-2 h-4 w-4" />
                                <span>Organization Scope</span>
                                <Lock className="ml-2 h-3 w-3" />
                                <span className="ml-1 text-xs text-muted-foreground">
                                  (Coming Soon)
                                </span>
                              </div>
                            </SelectItem>
                          )}
                        </SelectContent>
                      </Select>
                    </div>

                    {error && <div className="text-destructive text-sm col-span-4">{error}</div>}
                  </div>

                  <div className="flex justify-end gap-2 mt-6">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={onClose}
                      disabled={isSubmitting}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      disabled={isSubmitting || !ontologyName.trim()}
                      isLoading={isSubmitting}
                      className="bg-[#FFDF4B] text-[#212020] hover:bg-[#FFDF4B]/90 border border-[#212020] shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px]"
                    >
                      Create
                    </Button>
                  </div>
                </form>
              </TabsContent>

              <TabsContent value="import" className="mt-0">
                <div className="space-y-4">
                  <Alert>
                    <AlertCircle className="h-4 w-4" />
                    <AlertDescription>Import an ontology from a JSON export file.</AlertDescription>
                  </Alert>

                  <div className="grid grid-cols-4 items-center gap-4">
                    <Label htmlFor="import-scope" className="text-right text-sm font-medium">
                      Scope
                    </Label>
                    <Select value={scope} onValueChange={handleScopeChange}>
                      <SelectTrigger className="col-span-3">
                        <SelectValue placeholder="Select scope" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="user">
                          <div className="flex items-center">
                            <User className="mr-2 h-4 w-4" />
                            <span>User Scope</span>
                          </div>
                        </SelectItem>
                        {!isSnowflakeDomain && (
                          <SelectItem value="organization" disabled>
                            <div className="flex items-center opacity-50">
                              <Users className="mr-2 h-4 w-4" />
                              <span>Organization Scope</span>
                              <Lock className="ml-2 h-3 w-3" />
                              <span className="ml-1 text-xs text-muted-foreground">
                                (Coming Soon)
                              </span>
                            </div>
                          </SelectItem>
                        )}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="project-file" className="text-sm font-medium">
                      Project File
                    </Label>
                    <Input
                      id="project-file"
                      type="file"
                      accept=".json,application/json"
                      onChange={handleFileSelect}
                      ref={fileInputRef}
                    />
                    {selectedFile && (
                      <div className="flex items-center justify-between p-2 bg-muted/50 border border-border rounded">
                        <div className="flex items-center gap-2">
                          <FileText className="h-4 w-4" />
                          <span className="text-sm">{selectedFile.name}</span>
                          <span className="text-xs text-muted-foreground">
                            ({(selectedFile.size / 1024).toFixed(1)} KB)
                          </span>
                        </div>
                        <Button variant="ghost" size="sm" onClick={clearFileSelection}>
                          Remove
                        </Button>
                      </div>
                    )}
                  </div>

                  <div className="flex justify-end gap-2">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={onClose}
                      disabled={isImporting}
                    >
                      Cancel
                    </Button>
                    <Button
                      onClick={handleImport}
                      disabled={isImporting || !selectedFile}
                      isLoading={isImporting}
                      className="bg-[#FFDF4B] text-[#212020] hover:bg-[#FFDF4B]/90 border border-[#212020] shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px]"
                    >
                      <Upload className="h-4 w-4 mr-2" />
                      Import
                    </Button>
                  </div>
                </div>
              </TabsContent>
            </Tabs>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
};

export default CreateOntologyDialog;
