import type { Completion, CompletionContext } from "@codemirror/autocomplete";
import type { EditorView } from "@codemirror/view";
import { useSchemaStore } from "@/features/concept-editor/store";

// Helper to get the current word or token at cursor position
const getCurrentToken = (
  context: CompletionContext,
): { from: number; to: number; text: string } => {
  // Get document and cursor position
  const { state, pos } = context;
  const line = state.doc.lineAt(pos);
  const lineText = line.text;

  // For handling space trigger
  if (pos > 0 && lineText[pos - line.from - 1] === " ") {
    return {
      from: pos,
      to: pos,
      text: "", // Empty text for space trigger
    };
  }

  // For handling ( or () triggers
  if (
    pos > 0 &&
    (lineText[pos - line.from - 1] === "(" ||
      (pos > 1 && lineText.substring(pos - line.from - 2, pos - line.from) === "()"))
  ) {
    return {
      from: pos - (lineText[pos - line.from - 1] === ")" ? 2 : 1),
      to: pos,
      text: "(",
    };
  }

  // Find word boundaries around cursor position
  let start = pos;
  let end = pos;

  // Look backward for start of word
  while (start > line.from && /[\w]/.test(lineText[start - line.from - 1])) {
    start--;
  }

  // Look forward for end of word
  while (end < line.to && /[\w]/.test(lineText[end - line.from])) {
    end++;
  }

  return {
    from: start,
    to: end,
    text: lineText.slice(start - line.from, end - line.from),
  };
};

/**
 * `{{` completes over concept names — the authoring gesture for an llm
 * concept's dependencies, the way `[[` completes note titles in the notes
 * editor. Handled here rather than as a second `autocompletion()` extension
 * because CellEditor registers this function as its only completion source, and
 * two overrides would compete.
 */
const promptReferenceCompletions = (context: CompletionContext) => {
  const opening = context.matchBefore(/\{\{([^}\n]*)$/);
  if (!opening) return null;

  const { schemaSuggestions } = useSchemaStore.getState();
  if (!schemaSuggestions || schemaSuggestions.length === 0) return null;

  const typed = opening.text.slice(2).toLowerCase();
  const options = schemaSuggestions
    .filter((suggestion) => suggestion.label.toLowerCase().includes(typed))
    .map((suggestion) => ({
      label: suggestion.label,
      type: "concept",
      info: suggestion.info,
      // Not `suggestion.apply` — that is the Vadalog atom form `name(cols)`,
      // which is not what a placeholder holds.
      apply: applyReference(suggestion.label),
    }));

  if (options.length === 0) return null;
  return { from: opening.from + 2, options, validFor: /^[^}\n]*$/ };
};

/** Insert `name}}`, absorbing the `}}` that bracket-closing already put after
 *  the cursor so the result is not `{{name}}}}`. */
function applyReference(name: string) {
  return (view: EditorView, _completion: Completion, from: number, to: number) => {
    const doc = view.state.doc;
    let end = to;
    while (end < doc.length && end - to < 2 && doc.sliceString(end, end + 1) === "}") {
      end += 1;
    }
    const insert = `${name}}}`;
    view.dispatch({
      changes: { from, to: end, insert },
      selection: { anchor: from + insert.length },
      userEvent: "input.complete",
    });
  };
}

// Check if the character before cursor is a period
const isPeriodBeforeCursor = (context: CompletionContext): boolean => {
  const { state, pos } = context;
  if (pos <= 0) return false;

  const line = state.doc.lineAt(pos);
  return pos > 0 && line.text[pos - line.from - 1] === ".";
};

// The actual custom completion function
export const customCompletions = async (context: CompletionContext) => {
  try {
    // Inside `{{`, the only meaningful completion is a concept name, and the
    // token rules below (which stop on `(` and periods) do not apply.
    const promptReference = promptReferenceCompletions(context);
    if (promptReference) return promptReference;

    // Check if there's a period before the cursor - if so, don't show suggestions
    if (isPeriodBeforeCursor(context)) {
      return null;
    }

    // For space triggering, we need to manually check
    // This creates the effect of activateOnSpace without using the property
    const { state, pos } = context;
    const line = state.doc.lineAt(pos);

    // Force trigger completions on space
    const spaceJustTyped = pos > 0 && line.text[pos - line.from - 1] === " ";

    // Get schema suggestions and bound predicates from the store
    const { schemaSuggestions, boundPredicates } = useSchemaStore.getState();

    const hasSchemaSuggestions = schemaSuggestions && schemaSuggestions.length > 0;
    const hasBoundPredicates = boundPredicates && boundPredicates.length > 0;

    if (!hasSchemaSuggestions && !hasBoundPredicates) {
      return null;
    }

    // Get current token at cursor
    const { from, to, text: currentToken } = getCurrentToken(context);

    // Only show suggestions if there's at least one letter typed
    // Don't show on space, whitespace, or empty triggers
    if (!currentToken || currentToken === "" || currentToken === "(" || spaceJustTyped) {
      return null;
    }

    // Filter suggestions based on the current token
    if (currentToken && currentToken.length > 0) {
      const lower = currentToken.toLowerCase();
      const options: {
        label: string;
        type: string;
        apply: string;
        info: string;
        boost?: number;
      }[] = [];
      const seen = new Set<string>();

      // Bound predicates first (higher priority via boost)
      if (hasBoundPredicates) {
        for (const bp of boundPredicates) {
          if (bp.label.toLowerCase().includes(lower) && !seen.has(bp.label)) {
            seen.add(bp.label);
            options.push({
              label: bp.label,
              type: "predicate",
              apply: bp.apply,
              info: bp.info,
              boost: 10,
            });
          }
        }
      }

      if (hasSchemaSuggestions) {
        for (const s of schemaSuggestions) {
          if (s.label.toLowerCase().includes(lower) && !seen.has(s.label)) {
            seen.add(s.label);
            options.push({ label: s.label, type: "predicate", apply: s.apply, info: s.info });
          }
        }
      }

      if (options.length > 0) {
        return { from, to, options };
      }
    }

    return null;
  } catch (error) {
    console.error("Error in customCompletions:", error);
    return null;
  }
};
