// Shared-project self-healing — module-level controller.
//
// The hook layer (useSharedProjectsSelfHeal) installs a single error hook on
// HttpService that calls handleSharedProjectAuthError() for every non-ok HTTP
// response. We branch on the backend's structured `error_code` field rather
// than pattern-matching on free-text message strings. See BE dev's
// 2026-05-25 contract message for the six codes.
//
// Branches:
//   - share_revoked / share_expired         → heal (sync, invalidate, toast, navigate),
//                                             falling back to an unattributed
//                                             sync when the inbox has no match
//   - share_role_insufficient               → role-mismatch toast only; share is fine
//   - share_route_forbidden                 → FE-bug toast; do not evict
//   - share_project_mismatch                → FE-bug toast; do not evict
//   - share_missing_project_id              → FE-bug toast; do not evict
//
// Non-share auth failures (regular pmtx_token revocation, supabase auth, etc.)
// still return the legacy `{detail: "..."}` shape with no `error_code` and are
// passed through to existing call-site handling.

import { HttpError, type HttpErrorInfo } from "@/shared/services/httpService";

export type ShareAuthErrorCode =
  | "share_revoked"
  | "share_expired"
  | "share_role_insufficient"
  | "share_route_forbidden"
  | "share_project_mismatch"
  | "share_missing_project_id"
  | "concept_hidden"
  | "concept_read_only"
  | "team_membership_revoked";

const KNOWN_CODES: ReadonlySet<ShareAuthErrorCode> = new Set([
  "share_revoked",
  "share_expired",
  "share_role_insufficient",
  "share_route_forbidden",
  "share_project_mismatch",
  "share_missing_project_id",
  "concept_hidden",
  "concept_read_only",
  "team_membership_revoked",
]);

interface ShareAuthErrorEnvelope {
  status: "error";
  message: string;
  data: Record<string, unknown> | null;
  error_code: ShareAuthErrorCode;
}

export interface SelfHealContext {
  // Snapshot of accepted shared project ids. Updated whenever the inbox changes.
  getAcceptedOntologyIds: () => string[];
  // Runs the recovery flow for the project whose share token was revoked or
  // expired. Implemented by the React hook so it has access to React Query /
  // router / toast / auth. `code` lets the toast distinguish revoked vs expired.
  triggerHeal: (
    failedOntologyId: string,
    code: "share_revoked" | "share_expired" | "team_membership_revoked",
    backendMessage: string,
  ) => Promise<void>;
  // Surfaces a focused "you need editor access" toast when a viewer hits a route
  // that requires editor. Distinct from triggerHeal because the share is still
  // valid; the user just lacks the role for this specific action. Prefer the
  // backend's message — it already names the required role.
  notifyRoleMismatch: (failedOntologyId: string, backendMessage: string) => void;
  // Surfaces a generic error toast + console.error for FE-bug-shaped failures
  // (calling a non-allowlisted route, stale ontology_id, missing ontology_id in
  // payload). Logs the diagnostic data for triage. No share eviction.
  notifyShareBug: (
    code: "share_route_forbidden" | "share_project_mismatch" | "share_missing_project_id",
    data: Record<string, unknown> | null,
    backendMessage: string,
  ) => void;
  // Concept was hidden by the owner — refresh the concept list and surface a toast.
  notifyConceptHidden: (conceptName: string, ontologyId: string) => void;
  // Concept is read-only for this recipient — surface a toast.
  notifyConceptReadOnly: (conceptName: string, ontologyId: string) => void;
  // Last resort for a revoked/expired failure that matches no share in the inbox
  // snapshot. Syncs the vault without assuming which ontology is at fault.
  reconcileOrphanedShares: (
    code: "share_revoked" | "share_expired",
    backendMessage: string,
  ) => Promise<void>;
}

let context: SelfHealContext | null = null;
const inflightHeals = new Set<string>();

export function setSelfHealContext(ctx: SelfHealContext | null): void {
  context = ctx;
}

// Narrows an arbitrary response body to the share-auth-error envelope shape.
// Returns null for anything else, including FastAPI's legacy `{detail: "..."}`
// shape used by non-share auth failures.
function parseShareAuthError(body: unknown): ShareAuthErrorEnvelope | null {
  if (typeof body !== "object" || body === null) return null;
  const b = body as Record<string, unknown>;
  if (b.status !== "error") return null;
  const code = b.error_code;
  if (typeof code !== "string" || !KNOWN_CODES.has(code as ShareAuthErrorCode)) return null;
  const message = typeof b.message === "string" ? b.message : "";
  const data =
    typeof b.data === "object" && b.data !== null ? (b.data as Record<string, unknown>) : null;
  return {
    status: "error",
    message,
    data,
    error_code: code as ShareAuthErrorCode,
  };
}

// Public helper for call sites that want to soft-handle the role-insufficient
// case rather than letting it abort their flow. Example: the editor's
// Run-before-Save sequence — Run is allowed for viewers even though Save is
// editor-only, so the FE swallows the save error and proceeds with the cached
// backend id.
export function isRoleInsufficientError(err: unknown): boolean {
  if (!(err instanceof HttpError)) return false;
  const envelope = parseShareAuthError(err.body);
  return envelope?.error_code === "share_role_insufficient";
}

export function isConceptReadOnlyError(err: unknown): boolean {
  if (!(err instanceof HttpError)) return false;
  const envelope = parseShareAuthError(err.body);
  return envelope?.error_code === "concept_read_only";
}

function dataConceptName(data: Record<string, unknown> | null): string {
  if (!data) return "unknown";
  const name = data.concept_name;
  return typeof name === "string" && name.length > 0 ? name : "unknown";
}

function dataOntologyId(data: Record<string, unknown> | null): string | null {
  if (!data) return null;
  const id = data.ontology_id;
  return typeof id === "string" && id.length > 0 ? id : null;
}

// Fires the heal at most once per ontology at a time. The guard matters because
// a single screen can have several queries in flight against the same ontology,
// each of which would otherwise kick off its own sync.
function runHealOnce(
  ontologyId: string,
  code: "share_revoked" | "share_expired" | "team_membership_revoked",
  backendMessage: string,
): void {
  if (!context || inflightHeals.has(ontologyId)) return;
  inflightHeals.add(ontologyId);

  context
    .triggerHeal(ontologyId, code, backendMessage)
    .catch((err) => {
      console.warn("Self-heal flow threw for ontology", ontologyId, err);
    })
    .finally(() => {
      inflightHeals.delete(ontologyId);
    });
}

function matchAcceptedOntologyId(info: HttpErrorInfo, accepted: string[]): string | null {
  // Primary match: ontology_id appears in the URL (path or query).
  const fromUrl = accepted.find((id) => id.length > 0 && info.url.includes(id));
  if (fromUrl) return fromUrl;
  // Fallback for body-extractor routes (POST /ontologies/save, /cleanup,
  // /export-ontology, /copy) whose URLs don't carry the ontology_id — the backend
  // reads it from the request body. Per BE dev's confirmation these always act
  // on the project the user is currently inside, so currentOntologyId is a safe
  // proxy.
  const current = sessionStorage.getItem("currentOntologyId");
  if (current && accepted.includes(current)) return current;
  return null;
}

// Returns true iff the response was identified as a share auth failure and the
// appropriate side-effect was fired. Non-share errors return false so existing
// per-call-site handling continues.
export function handleSharedOntologyAuthError(info: HttpErrorInfo): boolean {
  if (!context) return false;
  // Loop guard: skip the share endpoints themselves so a failing /sync or
  // /inbox doesn't recursively trigger another sync.
  if (info.url.includes("/ontologies/share")) return false;

  const envelope = parseShareAuthError(info.body);
  if (!envelope) return false;

  switch (envelope.error_code) {
    case "share_revoked":
    case "share_expired": {
      // data is null for these — resolve ontology_id via URL/sessionStorage.
      const accepted = context.getAcceptedOntologyIds();
      const matched = accepted.length > 0 ? matchAcceptedOntologyId(info, accepted) : null;
      if (matched) {
        runHealOnce(matched, envelope.error_code, envelope.message);
        return true;
      }

      // No match is not a reason to stop: once the owner revokes, the share
      // leaves the inbox while the recipient's vaulted token lives on and keeps
      // routing that ontology id to the owner's pod. That orphaned row is
      // precisely what needs pruning, and only a sync can do it — bailing here
      // left the user staring at an unexplained 401 with no way out.
      context.reconcileOrphanedShares(envelope.error_code, envelope.message).catch((err) => {
        console.warn("Orphaned-share reconcile threw", err);
      });
      return true;
    }
    case "share_role_insufficient": {
      // Backend includes ontology_id in data, so we don't need URL matching.
      const pid = dataOntologyId(envelope.data) ?? "unknown";
      context.notifyRoleMismatch(pid, envelope.message);
      return true;
    }
    case "share_route_forbidden":
    case "share_project_mismatch":
    case "share_missing_project_id":
      context.notifyShareBug(envelope.error_code, envelope.data, envelope.message);
      return true;
    case "concept_hidden": {
      const conceptName = dataConceptName(envelope.data);
      const pid = dataOntologyId(envelope.data) ?? "unknown";
      context.notifyConceptHidden(conceptName, pid);
      return true;
    }
    case "concept_read_only": {
      const conceptName = dataConceptName(envelope.data);
      const pid = dataOntologyId(envelope.data) ?? "unknown";
      context.notifyConceptReadOnly(conceptName, pid);
      return true;
    }
    case "team_membership_revoked": {
      // Member was removed from the team (or the team share was revoked). Treat
      // exactly like share_revoked: evict + sync + refresh. Unlike the revoked/
      // expired codes, the backend includes ontology_id in data, so resolve from
      // there first and only fall back to URL/sessionStorage matching.
      const matched =
        dataOntologyId(envelope.data) ??
        matchAcceptedOntologyId(info, context.getAcceptedOntologyIds());
      if (!matched) return true;

      runHealOnce(matched, "team_membership_revoked", envelope.message);
      return true;
    }
    default: {
      const _exhaustive: never = envelope.error_code;
      throw new Error(`Unhandled share error code: ${_exhaustive}`);
    }
  }
}
