import { Download } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import SidebarToggleButton from "@/shared/components/ui/SidebarToggleButton";
import { Textarea } from "@/shared/components/ui/textarea";

interface JsonEditorPanelProps {
  jsonContent: string;
  onJsonChange: (value: string) => void;
  onExport: () => void;
  onToggleSidebar?: () => void;
  sidebarVisible: boolean;
}

/** Full-screen JSON view of the graph, with a toolbar (sidebar toggle + export). */
export function JsonEditorPanel({
  jsonContent,
  onJsonChange,
  onExport,
  onToggleSidebar,
  sidebarVisible,
}: JsonEditorPanelProps) {
  return (
    <div className="h-full relative">
      {/* JSON mode toolbar — sidebar toggle + export only; other actions in page header */}
      <div className="absolute top-4 left-4 right-4 flex justify-between items-center z-10">
        <div className="flex items-center gap-3">
          {onToggleSidebar && (
            <SidebarToggleButton
              onToggleSidebar={onToggleSidebar}
              sidebarVisible={sidebarVisible}
            />
          )}
        </div>
        <div className="flex items-center gap-1 bg-background/95 backdrop-blur-sm border rounded-lg p-1 shadow-lg">
          <Button onClick={onExport} variant="ghost" size="sm" title="Export JSON" className="h-8">
            <Download className="w-4 h-4" />
          </Button>
        </div>
      </div>

      <div className="h-full p-4">
        <div className="h-full pt-16">
          <Textarea
            value={jsonContent}
            onChange={(e) => onJsonChange(e.target.value)}
            placeholder="Enter your graph JSON here..."
            className="h-full resize-none font-mono text-sm border-0 focus-visible:ring-0 bg-muted/30"
          />
        </div>
      </div>
    </div>
  );
}
