import { z } from "zod";
import type { AppInputDef, FormFieldDef } from "../schema/appDefinition.types";

/**
 * Compile a form definition's declarative validation (required/min/max/
 * pattern, record-group row bounds) into a Zod schema for React Hook Form.
 * Kept flat and boring on purpose — the schema is agent-authored (ADR D6).
 */

function scalarSchema(field: FormFieldDef): z.ZodType {
  if (field.type === "checkbox") {
    const schema = z.boolean();
    if (field.required) {
      return schema.refine((checked) => checked === true, {
        message: `${field.label ?? field.id} must be checked`,
      });
    }
    return schema;
  }
  if (field.type === "number") {
    let schema = z.coerce.number({ message: `${field.label ?? field.id} must be a number` });
    if (field.min !== undefined) schema = schema.min(field.min);
    if (field.max !== undefined) schema = schema.max(field.max);
    return field.required ? schema : schema.optional();
  }
  if (field.type === "multi_select") {
    const schema = z.array(z.string());
    return field.required ? schema.min(1, `${field.label ?? field.id} is required`) : schema;
  }
  let schema = z.string();
  if (field.pattern) schema = schema.regex(new RegExp(field.pattern));
  if (field.required) return schema.min(1, `${field.label ?? field.id} is required`);
  return schema.optional().or(z.literal(""));
}

function fieldSchema(field: FormFieldDef): z.ZodType {
  if (field.type !== "record_group") return scalarSchema(field);

  const rowShape = Object.fromEntries(
    (field.fields ?? []).map((rowField) => [rowField.id, scalarSchema(rowField)]),
  );
  let rows = z.array(z.object(rowShape));
  if (field.minRows !== undefined) {
    rows = rows.min(field.minRows, `${field.label ?? field.id}: at least ${field.minRows} row(s)`);
  }
  if (field.maxRows !== undefined) rows = rows.max(field.maxRows);
  return rows;
}

export function collectFormFields(input: AppInputDef): FormFieldDef[] {
  return (input.sections ?? []).flatMap((section) => section.fields);
}

export function buildFormSchema(input: AppInputDef): z.ZodType {
  const shape = Object.fromEntries(
    collectFormFields(input).map((field) => [field.id, fieldSchema(field)]),
  );
  return z.object(shape);
}

function fieldDefault(field: FormFieldDef): unknown {
  if (field.default !== undefined) return field.default;
  if (field.type === "record_group") return [];
  if (field.type === "multi_select") return [];
  if (field.type === "checkbox") return false;
  if (field.type === "number") return "";
  return "";
}

export function buildFormDefaults(input: AppInputDef): Record<string, unknown> {
  return Object.fromEntries(
    collectFormFields(input).map((field) => [field.id, fieldDefault(field)]),
  );
}

/** Evaluate a field's conditional visibility against current form values. */
export function isFieldVisible(field: FormFieldDef, values: Record<string, unknown>): boolean {
  if (!field.visibleWhen) return true;
  return values[field.visibleWhen.field] === field.visibleWhen.equals;
}
