import { AlertCircle, Check, Loader2, StickyNote } from "lucide-react";
import { useMemo, useState } from "react";
import { useContextNotes } from "@/features/context-layer/hooks/useContextNotes";
import type { ContextNote } from "@/features/context-layer/types";
import { Input } from "@/shared/components/ui/input";
import { cn } from "@/shared/lib/utils";

interface ContextNotePickerProps {
  projectId: string | null;
  selectedNoteIds: string[];
  onChange: (noteIds: string[]) => void;
  disabled?: boolean;
  /**
   * Grow the note list to the height the parent gives it instead of capping it.
   * Used where the picker is the cell's editor pane (Explorer / Lineage), the
   * same role `fillHeight` plays for CellEditor.
   */
  fillHeight?: boolean;
}

function noteLabel(note: ContextNote): string {
  const title = note.title?.trim();
  if (title) return title;
  const firstLine = note.text.split("\n")[0]?.trim();
  return firstLine || "Untitled note";
}

function matchesQuery(note: ContextNote, query: string): boolean {
  if (!query) return true;
  const q = query.toLowerCase();
  return noteLabel(note).toLowerCase().includes(q) || note.text.toLowerCase().includes(q);
}

/**
 * Multi-select list of the project's context notes. The chosen ids drive a
 * static context concept's `concept_config.note_ids`.
 */
export function ContextNotePicker({
  projectId,
  selectedNoteIds,
  onChange,
  disabled = false,
  fillHeight = false,
}: ContextNotePickerProps) {
  const [query, setQuery] = useState("");
  const {
    data: notes,
    isLoading,
    error,
  } = useContextNotes(
    { scope: "ontology", scopeId: projectId ?? "" },
    { enabled: Boolean(projectId) },
  );

  const selected = useMemo(() => new Set(selectedNoteIds), [selectedNoteIds]);

  const filtered = useMemo(() => {
    const list = notes ?? [];
    const q = query.trim().toLowerCase();
    return list.filter((note) => matchesQuery(note, q));
  }, [notes, query]);

  const toggle = (noteId: string) => {
    const next = new Set(selected);
    if (next.has(noteId)) {
      next.delete(noteId);
    } else {
      next.add(noteId);
    }
    onChange(Array.from(next));
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => setQuery(e.target.value);

  if (isLoading) {
    return (
      <div className="flex items-center gap-2 px-4 py-6 text-sm text-muted-foreground">
        <Loader2 className="h-4 w-4 animate-spin" />
        <span>Loading notes…</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center gap-2 px-4 py-6 text-sm text-destructive">
        <AlertCircle className="h-4 w-4" />
        <span>Could not load notes.</span>
      </div>
    );
  }

  if ((notes ?? []).length === 0) {
    return (
      <div className="flex flex-col items-center gap-1 px-4 py-8 text-center text-sm text-muted-foreground">
        <StickyNote className="h-5 w-5 opacity-60" />
        <span>No notes in this ontology yet.</span>
        <span className="text-xs">Create notes in the Context page, then pin them here.</span>
      </div>
    );
  }

  return (
    <div className={cn("flex flex-col gap-2 px-4 py-3", fillHeight && "min-h-0 flex-1")}>
      <div className="flex items-center justify-between gap-2">
        <Input
          value={query}
          onChange={handleSearchChange}
          placeholder="Search notes…"
          className="h-8 text-sm"
          disabled={disabled}
        />
        <span className="flex-shrink-0 text-xs text-muted-foreground">
          {selected.size} selected
        </span>
      </div>
      <div
        className={cn(
          "flex flex-col gap-1 overflow-y-auto",
          fillHeight ? "min-h-0 flex-1" : "max-h-72",
        )}
      >
        {filtered.map((note) => {
          const isSelected = selected.has(note.id);
          return (
            <button
              type="button"
              key={note.id}
              onClick={() => toggle(note.id)}
              disabled={disabled}
              className={cn(
                "flex items-start gap-2 rounded-md border px-2 py-1.5 text-left text-sm transition-colors",
                isSelected ? "border-primary/40 bg-primary/10" : "border-border hover:bg-accent",
                disabled && "opacity-50",
              )}
            >
              <span
                className={cn(
                  "mt-0.5 flex h-4 w-4 flex-shrink-0 items-center justify-center rounded border",
                  isSelected
                    ? "border-primary bg-primary text-primary-foreground"
                    : "border-border",
                )}
              >
                {isSelected && <Check className="h-3 w-3" />}
              </span>
              <span className="min-w-0">
                <span className="block truncate font-medium text-foreground">
                  {noteLabel(note)}
                </span>
                <span className="block truncate text-xs text-muted-foreground">{note.text}</span>
              </span>
            </button>
          );
        })}
        {filtered.length === 0 && (
          <div className="px-2 py-4 text-center text-xs text-muted-foreground">
            No notes match “{query}”.
          </div>
        )}
      </div>
    </div>
  );
}

export default ContextNotePicker;
