import { Check, X } from "lucide-react";
import type React from "react";
import type { ExecutionStatus } from "@/features/ontology-schema/types";

/**
 * Circular status indicator to the left of the concept name. A gray outlined
 * circle by default; a spinning amber dot while running; a green check on
 * success; a red cross on error. Sized to sit alongside the large name.
 */
export const StatusIndicator: React.FC<{ status?: ExecutionStatus }> = ({ status }) => {
  const base = "h-5 w-5 flex-shrink-0";
  switch (status?.status) {
    case "running":
      return (
        <span className={`${base} relative inline-flex items-center justify-center`}>
          <span
            className="absolute inset-0 rounded-full border-2 border-amber-600/25 border-t-amber-600 animate-spin"
            style={{ animationDuration: "0.8s" }}
          />
          <span className="h-2.5 w-2.5 rounded-full bg-amber-600" />
        </span>
      );
    case "success":
      return (
        <span
          className={`${base} rounded-full bg-green-600 inline-flex items-center justify-center`}
        >
          <Check className="h-3 w-3 text-white" strokeWidth={3} />
        </span>
      );
    case "error":
      return (
        <span className={`${base} rounded-full bg-red-600 inline-flex items-center justify-center`}>
          <X className="h-3 w-3 text-white" strokeWidth={3} />
        </span>
      );
    case "skipped":
      return <span className={`${base} inline-block rounded-full bg-muted-foreground/50`} />;
    default:
      return (
        <span className={`${base} inline-block rounded-full border-2 border-muted-foreground/30`} />
      );
  }
};

/** Human-readable tooltip text for an execution status. */
export const statusTitle = (s?: ExecutionStatus): string => {
  if (!s) return "";
  if (s.status === "error" && s.error) return `Error: ${s.error}`;
  return s.status.charAt(0).toUpperCase() + s.status.slice(1);
};

/**
 * Colored left accent border reflecting execution status. Empty for the idle
 * (no status) and skipped states so only meaningful runs get the accent.
 */
export const statusBorderClass = (s?: ExecutionStatus): string => {
  switch (s?.status) {
    case "running":
      return "border-l-4 border-l-amber-600";
    case "success":
      return "border-l-4 border-l-green-600";
    case "error":
      return "border-l-4 border-l-red-600";
    default:
      return "";
  }
};
