import type { Edge, Node as FlowNode } from "@xyflow/react";
import type { Dispatch, MutableRefObject, SetStateAction } from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import type { ConceptStatusEvent } from "@/features/concept-editor/api/ConceptEditorClient";
import type { ConceptData } from "@/features/concepts/api";
import { useLineageRunStatusStore } from "@/features/lineage/store/lineageRunStatusStore";
import type { ConceptCardCustomData } from "@/features/ontology-schema/types";
import {
  DEFAULT_EDGE_MARKER,
  DEFAULT_EDGE_STYLE,
  FLOW_RUNNING_MARKER,
  FLOW_RUNNING_STYLE,
  FLOW_SUCCESS_MARKER,
  FLOW_SUCCESS_STYLE,
} from "../constants";
import {
  applySelectionHighlight,
  collectUpstreamEdgeIds,
  resolveEdgeStatus,
} from "../lineage.utils";

type ConceptStatus = { status: "running" | "success" | "error" | "skipped"; error?: string };

interface UseConceptExecutionStatusParams {
  setNodes: Dispatch<SetStateAction<FlowNode<ConceptCardCustomData>[]>>;
  setEdges: Dispatch<SetStateAction<Edge[]>>;
  selectedNodeIdRef: MutableRefObject<string | null>;
  baseEdgesRef: MutableRefObject<Edge[]>;
}

/**
 * Tracks per-concept execution status from live run events (window events) and,
 * on reconnect, from a backend snapshot published to the lineage run-status
 * store. The two sources are merged into a single derived map that drives the
 * graph (node `executionStatus` + edge color/animation), so painting is a pure
 * function of the inputs and can't be dropped by mount timing or node rebuilds.
 * `conceptStatusesRef` mirrors the merged map so the data-transform effect can
 * read the latest statuses without depending on them.
 */
export function useConceptExecutionStatus({
  setNodes,
  setEdges,
  selectedNodeIdRef,
  baseEdgesRef,
}: UseConceptExecutionStatusParams) {
  const externalStatuses = useLineageRunStatusStore((s) => s.reconnectStatuses);
  const [liveStatuses, setLiveStatuses] = useState<Record<string, ConceptStatus>>({});

  // Live run events (active local run) take precedence over the reconnect
  // snapshot; the snapshot fills in everything when we weren't the runner.
  const conceptStatuses = useMemo<Record<string, ConceptStatus>>(
    () => ({ ...(externalStatuses ?? {}), ...liveStatuses }),
    [externalStatuses, liveStatuses],
  );
  const conceptStatusesRef = useRef(conceptStatuses);
  conceptStatusesRef.current = conceptStatuses;

  useEffect(() => {
    const handleStart = () => setLiveStatuses({});
    const handleStatus = (e: Event) => {
      const evt = (e as CustomEvent<ConceptStatusEvent>).detail;
      if (evt.type === "execution_plan") return;
      if (evt.concept && evt.status) {
        setLiveStatuses((prev) => ({
          ...prev,
          [evt.concept!]: { status: evt.status!, error: evt.error },
        }));
        // The backend streams the concept's row count and elapsed time with its
        // success event, so update the footer the moment this card finishes
        // instead of waiting for the whole run to end (conceptsUpdated still
        // reconciles at the end).
        const typedEvt = evt as { row_count?: number; execution_time_ms?: number };
        const rowCount = typedEvt.row_count;
        if (evt.status === "success" && typeof rowCount === "number") {
          const concept = evt.concept;
          setNodes((prev) =>
            prev.map((n) => {
              if (n.data.label !== concept) return n;
              const execMs =
                typeof typedEvt.execution_time_ms === "number"
                  ? typedEvt.execution_time_ms
                  : n.data.execution_time_ms;
              if (
                n.data.row_count === rowCount &&
                n.data.is_populated &&
                n.data.execution_time_ms === execMs
              ) {
                return n;
              }
              return {
                ...n,
                data: {
                  ...n.data,
                  row_count: rowCount,
                  is_populated: true,
                  execution_time_ms: execMs,
                },
              };
            }),
          );
        }
      }
    };
    window.addEventListener("conceptExecutionStart", handleStart);
    window.addEventListener("conceptExecutionStatus", handleStatus);
    return () => {
      window.removeEventListener("conceptExecutionStart", handleStart);
      window.removeEventListener("conceptExecutionStatus", handleStatus);
    };
  }, [setNodes]);

  // Inject executionStatus into node data when statuses change
  useEffect(() => {
    if (Object.keys(conceptStatuses).length === 0) {
      setNodes((prev) =>
        prev.map((n) => {
          if (n.data.executionStatus) {
            return { ...n, data: { ...n.data, executionStatus: undefined } };
          }
          return n;
        }),
      );
      return;
    }
    setNodes((prev) =>
      prev.map((n) => {
        const label = n.data.label;
        const st = conceptStatuses[label];
        const cur = n.data.executionStatus;
        if (st && (cur?.status !== st.status || cur?.error !== st.error)) {
          return { ...n, data: { ...n.data, executionStatus: st } };
        }
        if (!st && cur) {
          return { ...n, data: { ...n.data, executionStatus: undefined } };
        }
        return n;
      }),
    );
  }, [conceptStatuses, setNodes]);

  // Optimistically refresh record counts as soon as a run finishes. On
  // `cellExecuted`, useConceptRefresh re-fetches the concept list (which carries
  // the freshly-stored `row_count`/`is_populated`) and re-broadcasts it via
  // `conceptsUpdated`. We merge those counts straight into the nodes so the
  // badges update immediately, instead of waiting for the next lineage re-fetch.
  useEffect(() => {
    const handleConceptsUpdated = (e: Event) => {
      const concepts = (e as CustomEvent<{ concepts?: ConceptData[] }>).detail?.concepts;
      if (!concepts?.length) return;
      const byName = new Map(concepts.map((c) => [c.predicate_name, c]));
      setNodes((prev) =>
        prev.map((n) => {
          const c = byName.get(n.data.label);
          if (!c || c.row_count === undefined) return n;
          const isPopulated = c.is_populated ?? n.data.is_populated;
          const execMs = c.execution_time_ms ?? n.data.execution_time_ms;
          if (
            n.data.row_count === c.row_count &&
            n.data.is_populated === isPopulated &&
            n.data.execution_time_ms === execMs
          ) {
            return n;
          }
          return {
            ...n,
            data: {
              ...n.data,
              row_count: c.row_count,
              is_populated: isPopulated,
              execution_time_ms: execMs,
            },
          };
        }),
      );
    };
    window.addEventListener("conceptsUpdated", handleConceptsUpdated);
    return () => window.removeEventListener("conceptsUpdated", handleConceptsUpdated);
  }, [setNodes]);

  // Highlight edges flowing into running/completed concepts, then layer
  // selection highlighting on top when a node is selected.
  // Uses baseEdgesRef directly (not a functional updater) to avoid a race
  // where the deferred updater overwrites the ref after the data-loading
  // effect has already populated it.
  useEffect(() => {
    const current = baseEdgesRef.current;
    if (current.length === 0) return;

    let base: Edge[];

    if (Object.keys(conceptStatuses).length === 0) {
      const needsReset = current.some(
        (e) => e.animated || (e.style as Record<string, unknown>)?.stroke !== "#aaa",
      );
      base = needsReset
        ? current.map((e) => ({
            ...e,
            animated: false,
            style: DEFAULT_EDGE_STYLE,
            markerEnd: DEFAULT_EDGE_MARKER,
          }))
        : current;
    } else {
      base = current.map((e) => {
        const edgeStatus = resolveEdgeStatus(e, conceptStatuses);
        if (edgeStatus === "running") {
          return {
            ...e,
            animated: true,
            style: FLOW_RUNNING_STYLE,
            markerEnd: FLOW_RUNNING_MARKER,
          };
        }
        if (edgeStatus === "success") {
          return {
            ...e,
            animated: false,
            style: FLOW_SUCCESS_STYLE,
            markerEnd: FLOW_SUCCESS_MARKER,
          };
        }
        return { ...e, animated: false, style: DEFAULT_EDGE_STYLE, markerEnd: DEFAULT_EDGE_MARKER };
      });
    }

    baseEdgesRef.current = base;

    if (!selectedNodeIdRef.current) {
      setEdges(base);
      return;
    }
    const highlighted = collectUpstreamEdgeIds(selectedNodeIdRef.current, base);
    setEdges(applySelectionHighlight(base, highlighted, conceptStatuses));
  }, [conceptStatuses, setEdges, selectedNodeIdRef, baseEdgesRef]);

  return { conceptStatuses, conceptStatusesRef };
}
