import { useEffect } from "react";
import { VerticalGeometricLoader } from "@/shared/components/ui/geometric-loaders";

/**
 * Databricks OAuth Callback Page
 * This page is opened in a popup window during Databricks OAuth login.
 * It receives the authorization code from Databricks and sends it back to the parent window.
 */
const DatabricksOAuthCallback = () => {
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get("code");
    const state = params.get("state");
    const error = params.get("error");
    const errorDescription = params.get("error_description");

    // If we're in a popup (opened by parent window)
    if (window.opener && !window.opener.closed) {
      if (error) {
        // Send error to parent window
        window.opener.postMessage(
          {
            type: "databricks-oauth-error",
            error,
            errorDescription,
          },
          window.location.origin,
        );
      } else if (code && state) {
        // Send success with code to parent window
        window.opener.postMessage(
          {
            type: "databricks-oauth-success",
            code,
            state,
          },
          window.location.origin,
        );
      } else {
        // Missing required parameters
        window.opener.postMessage(
          {
            type: "databricks-oauth-error",
            error: "invalid_response",
            errorDescription: "Missing code or state parameter",
          },
          window.location.origin,
        );
      }

      // Close popup after sending message
      setTimeout(() => {
        window.close();
      }, 500);
    } else {
      // Not in a popup
    }
  }, []);

  return (
    <div className="flex items-center justify-center min-h-screen bg-background">
      <div className="text-center space-y-4">
        <VerticalGeometricLoader />
        <p className="text-sm text-muted-foreground">Completing Databricks authentication...</p>
        <p className="text-xs text-muted-foreground">This window will close automatically.</p>
      </div>
    </div>
  );
};

export default DatabricksOAuthCallback;
