import type React from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import ReactMarkdown from "react-markdown";
import rehypeHighlight from "rehype-highlight";
import remarkGfm from "remark-gfm";
import { useCurrentDashboard } from "../hooks/useCurrentDashboard";
import { useCurrentOntologyId } from "../hooks/useCurrentOntologyId";
import "highlight.js/styles/tokyo-night-dark.css";
import { AgentMessageLimitDialog } from "@/features/billing/components/AgentMessageLimitDialog";
import { useAgentMessageUsage } from "@/features/billing/hooks/useAgentMessageUsage";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { trackAssistantMessageSent } from "@/shared/services/analyticsEvents";
import { useSidebarLayoutStore } from "@/shared/store/sidebarLayoutStore";
import { useAgentTurn } from "../hooks/useAgentTurn";
import { useChatAttachments } from "../hooks/useChatAttachments";
import { useDeleteTurn } from "../hooks/useDeleteTurn";
import { usePanelResize } from "../hooks/usePanelResize";
import { isAppWriteTool } from "../proposal.utils";
import { useCodeAssistantStore } from "../store";
import { AuthorizationPrompt } from "./AuthorizationPrompt";
import { ChatEmptyState } from "./ChatEmptyState";
import ChatHistorySidebar from "./ChatHistorySidebar";
import { ChatInputBox } from "./ChatInputBox";
import { ChatPanelHeader } from "./ChatPanelHeader";
import { ClarificationPrompt } from "./ClarificationPrompt";
import { ContextLoadedChip } from "./ContextLoadedChip";
import { CredentialRequestCard } from "./CredentialRequestCard";
import CsvDatasourceProposalCard from "./CsvDatasourceProposalCard";
import { chatMarkdownComponents } from "./chatMarkdown";
import { HaltNotice } from "./HaltNotice";
import { PlanMessage } from "./PlanMessage";
import {
  ConceptProposalCard,
  DashboardProposalCard,
  OntologyProposalCard,
  OntologySchemaProposalCard,
} from "./ProposalCards";
import { ThinkingMessage } from "./ThinkingMessage";
import { ToolMessage } from "./ToolMessage";
import { UserMessageBubble } from "./UserMessageBubble";
import { WriterProposalCard } from "./WriterProposalCard";

// Tool activity card moved to ./ToolMessage.tsx as part of #1 streaming.
// Proposal cards moved to ./ProposalCards.tsx as part of v0.1 close.

// ── Main panel ────────────────────────────────────────────────────────────────

const CodeAssistantPanel: React.FC = () => {
  const ontologyId = useCurrentOntologyId(); // null when not inside a project
  const dashboard = useCurrentDashboard(); // non-null while viewing a dashboard

  const {
    activeCellName,
    messages,
    haltNotice,
    isLoading,
    isPanelOpen,
    focusedWidget,
    setFocusedWidget,
    seededPrompt,
    setSeededPrompt,
    sessionId,
    sessionTitle,
    toggleHistory,
    closePanel,
    clearMessages,
    setWriterProposalState,
    setClarificationState,
    setCredentialRequestState,
    setActiveModel,
    bumpOntologySchemaRevision,
    bumpOntologiesRevision,
    bumpDashboardsRevision,
    bumpDatasourcesRevision,
    abortActiveChat,
    openAgentLimitDialog,
  } = useCodeAssistantStore();

  const { usage: agentUsage } = useAgentMessageUsage();
  const agentLimitReached =
    !!agentUsage?.isFreemium && agentUsage.remaining !== null && agentUsage.remaining <= 0;

  const { width: panelWidth, isResizing, handleResizeMouseDown } = usePanelResize();
  const railWidth = useSidebarLayoutStore((state) => state.railWidth);
  const [input, setInput] = useState("");
  const [manualHeight, setManualHeight] = useState<number | null>(null);
  const inputDragRef = useRef<{ startY: number; startH: number } | null>(null);
  const messagesScrollRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const {
    attachments,
    attach: attachFile,
    remove: removeAttachment,
    clear: clearAttachments,
    readyPaths: attachmentPaths,
    readyAttachments,
    isUploading: attachmentsUploading,
  } = useChatAttachments();

  // Jump to the newest messages when the panel (re)opens or a chat is loaded
  // from history. Markdown/code blocks finish laying out over several frames
  // (syntax highlighting expands their height), so a single scroll lands too
  // high. Re-pin to the bottom each frame until the content height stops
  // growing (or a frame cap is hit), and bail out if the user scrolls up.
  useEffect(() => {
    const MAX_FRAMES = 40;
    const STABLE_FRAMES = 4;
    const SCROLL_UP_THRESHOLD = 40;
    if (!isPanelOpen) return;
    let cancelled = false;
    let raf = 0;
    let lastHeight = -1;
    let stableCount = 0;
    let frames = 0;

    const step = () => {
      if (cancelled) return;
      const el = messagesScrollRef.current;
      if (!el) return;
      const distanceFromBottom = el.scrollHeight - el.scrollTop - el.clientHeight;
      if (
        frames > 0 &&
        distanceFromBottom > SCROLL_UP_THRESHOLD &&
        el.scrollHeight === lastHeight
      ) {
        return; // user scrolled up while content was stable — stop fighting them
      }
      el.scrollTop = el.scrollHeight;
      stableCount = el.scrollHeight === lastHeight ? stableCount + 1 : 0;
      lastHeight = el.scrollHeight;
      frames += 1;
      if (stableCount < STABLE_FRAMES && frames < MAX_FRAMES) {
        raf = requestAnimationFrame(step);
      }
    };

    raf = requestAnimationFrame(step);
    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
    };
  }, [sessionId, isPanelOpen]);

  // A seeded prompt (e.g. the editor's one-click "Fix with AI") pre-fills the
  // composer and focuses it, then clears from the store. Not auto-sent — the
  // user reviews and presses send, since a turn may call save_dashboard.
  useEffect(() => {
    if (!seededPrompt) return;
    setInput(seededPrompt);
    setSeededPrompt(null);
    const el = textareaRef.current;
    if (el) {
      el.focus();
      el.style.height = "auto";
      el.style.height = `${Math.min(Math.max(el.scrollHeight, 72), 300)}px`;
    }
  }, [seededPrompt, setSeededPrompt]);

  // Project-panel-specific reactions to a successful tool result: refresh the
  // relevant caches / views the tool just mutated.
  const handleToolSideEffect = useCallback(
    (tool: string) => {
      if (
        tool === "save_ontology_schema" ||
        tool === "update_concept" ||
        tool === "create_concept"
      ) {
        bumpOntologySchemaRevision();
        window.dispatchEvent(new CustomEvent("conceptCreated"));
      }
      if (tool === "create_ontology") {
        bumpOntologiesRevision();
      }
      if (isAppWriteTool(tool)) {
        bumpDashboardsRevision();
      }
      if (tool === "create_csv_datasource" || tool === "connect_file_as_datasource") {
        bumpDatasourcesRevision();
        // Reuses the existing data-source refresh event picked up by
        // useConceptRefresh so concept autocomplete + datasource list update.
        window.dispatchEvent(
          new CustomEvent("dataSourceConnected", {
            detail: { ontologyId, ontologyScope: "user" },
          }),
        );
      }
    },
    [
      bumpOntologySchemaRevision,
      bumpOntologiesRevision,
      bumpDashboardsRevision,
      bumpDatasourcesRevision,
      ontologyId,
    ],
  );

  const { runTurn, editTurn, resolveAuthorization, resumeAfterCredentials, resumeTurn } =
    useAgentTurn({
      ontologyId: ontologyId ?? "_",
      currentDashboard: dashboard,
      onModel: setActiveModel,
      onToolSideEffect: handleToolSideEffect,
    });

  // Editing rewrites the conversation from that turn on, which cannot be done
  // sensibly while a reply is still streaming into it.
  const canEditMessages = !isLoading;

  const handleSubmitEdit = useCallback(
    (messageId: string, newText: string) => {
      if (agentLimitReached) {
        openAgentLimitDialog();
        return;
      }
      void editTurn({ messageId, userText: newText });
    },
    [agentLimitReached, openAgentLimitDialog, editTurn],
  );

  const { deleteTurn } = useDeleteTurn();

  const handleDeleteTurn = useCallback(
    (messageId: string) => {
      void deleteTurn(messageId);
    },
    [deleteTurn],
  );

  const handleSend = useCallback(
    async (overrideMessage?: string) => {
      const userMessage = (overrideMessage ?? input).trim();
      // Allow sending if there's either text or at least one ready
      // attachment — pure-attachment messages are valid ("here, look at
      // this file"). Block while uploads are still in flight or a turn
      // is already running.
      const pathsToSend = overrideMessage ? [] : attachmentPaths;
      const attachmentsToShow = overrideMessage ? [] : readyAttachments;
      const canSend = !isLoading && (userMessage.length > 0 || pathsToSend.length > 0);
      if (!canSend) return;
      if (agentLimitReached) {
        openAgentLimitDialog();
        return;
      }

      trackAssistantMessageSent({
        messageLength: userMessage.length,
        attachmentCount: pathsToSend.length,
      });

      if (!overrideMessage) {
        setInput("");
        clearAttachments();
        setManualHeight(null);
        if (textareaRef.current) textareaRef.current.style.height = "72px";
      }

      await runTurn({
        userText: userMessage,
        attachmentPaths: pathsToSend,
        attachments: attachmentsToShow,
      });
    },
    [
      input,
      attachmentPaths,
      readyAttachments,
      clearAttachments,
      isLoading,
      agentLimitReached,
      openAgentLimitDialog,
      runTurn,
    ],
  );

  const INPUT_MIN_HEIGHT = 72;
  const INPUT_MAX_HEIGHT = 300;

  const autoResizeTextarea = useCallback(() => {
    const el = textareaRef.current;
    if (!el || manualHeight !== null) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(Math.max(el.scrollHeight, INPUT_MIN_HEIGHT), INPUT_MAX_HEIGHT)}px`;
  }, [manualHeight]);

  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setInput(e.target.value);
      setManualHeight(null);
      autoResizeTextarea();
    },
    [autoResizeTextarea],
  );

  const handleInputResizeMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    const el = textareaRef.current;
    if (!el) return;
    const startY = e.clientY;
    const startH = el.offsetHeight;
    inputDragRef.current = { startY, startH };

    const onMouseMove = (ev: MouseEvent) => {
      if (!inputDragRef.current) return;
      const delta = inputDragRef.current.startY - ev.clientY;
      const next = Math.min(
        Math.max(inputDragRef.current.startH + delta, INPUT_MIN_HEIGHT),
        INPUT_MAX_HEIGHT,
      );
      setManualHeight(next);
      el.style.height = `${next}px`;
    };

    const onMouseUp = () => {
      inputDragRef.current = null;
      document.removeEventListener("mousemove", onMouseMove);
      document.removeEventListener("mouseup", onMouseUp);
    };

    document.addEventListener("mousemove", onMouseMove);
    document.addEventListener("mouseup", onMouseUp);
  }, []);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleAbort = useCallback(() => {
    abortActiveChat();
  }, [abortActiveChat]);

  if (!isPanelOpen) return null;

  return (
    <div
      className="fixed top-0 z-30 flex h-screen flex-row overflow-hidden border-r bg-muted transition-[left] duration-200"
      style={{ left: railWidth, width: panelWidth }}
    >
      {/* Resize handle — right edge (panel is docked on the left) */}
      <div
        onMouseDown={handleResizeMouseDown}
        className="absolute right-0 top-0 bottom-0 z-10 w-1 cursor-ew-resize group"
      >
        <div
          className={`absolute inset-y-0 right-0 w-px bg-border transition-all duration-100 group-hover:w-[3px]${isResizing ? " !w-[3px]" : ""}`}
        />
      </div>

      {/* Main chat column */}
      <div className="flex flex-1 flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <ChatPanelHeader
          sessionTitle={sessionTitle}
          activeCellName={activeCellName}
          isLoading={isLoading}
          onNewChat={clearMessages}
          onToggleHistory={toggleHistory}
          onClose={closePanel}
        />

        {/* Messages */}
        <div ref={messagesScrollRef} className="flex-1 overflow-y-auto px-4 py-4 space-y-4 min-h-0">
          {messages.length === 0 && <ChatEmptyState onSelectPrompt={handleSend} />}

          {messages.map((msg) => {
            if (msg.role === "thinking") {
              return (
                <ThinkingMessage
                  key={msg.id}
                  content={msg.content}
                  isActive={isLoading && msg.id === messages[messages.length - 1]?.id}
                />
              );
            }

            if (msg.role === "tool") {
              return (
                <ToolMessage
                  key={msg.id}
                  toolName={msg.toolName ?? msg.content}
                  toolDetail={msg.toolDetail}
                  status={msg.toolStatus ?? "running"}
                  progress={msg.toolProgress}
                  toolInput={msg.toolInput}
                  toolResult={msg.toolResult}
                />
              );
            }

            if (msg.role === "context_loaded" && msg.contextLoaded) {
              return <ContextLoadedChip key={msg.id} data={msg.contextLoaded} />;
            }

            if (msg.role === "plan" && msg.planSteps) {
              return <PlanMessage key={msg.id} steps={msg.planSteps} />;
            }

            if (msg.role === "writer_proposal" && msg.writerProposal) {
              return (
                <WriterProposalCard
                  key={msg.id}
                  proposal={msg.writerProposal}
                  state={msg.writerProposalState ?? "pending"}
                  onResolve={(next) => setWriterProposalState(msg.id, next)}
                />
              );
            }

            if (msg.role === "clarification" && msg.clarification) {
              return (
                <ClarificationPrompt
                  key={msg.id}
                  data={msg.clarification}
                  state={msg.clarificationState ?? "pending"}
                  onResolve={(next) => setClarificationState(msg.id, next)}
                  onAnswer={(answer) => handleSend(answer)}
                />
              );
            }

            if (msg.role === "authorization" && msg.authorization) {
              return (
                <AuthorizationPrompt
                  key={msg.id}
                  data={msg.authorization}
                  state={msg.authorizationState ?? "pending"}
                  onDecide={(decision) =>
                    resolveAuthorization(msg.id, decision, msg.authorization!)
                  }
                />
              );
            }

            if (msg.role === "credential_request" && msg.credentialRequest) {
              return (
                <CredentialRequestCard
                  key={msg.id}
                  data={msg.credentialRequest}
                  state={msg.credentialRequestState ?? "pending"}
                  onResolve={(next) => setCredentialRequestState(msg.id, next)}
                  onSubmitted={() => resumeAfterCredentials(true)}
                  onDismiss={() => resumeAfterCredentials(false)}
                />
              );
            }

            if (msg.role === "proposal" && msg.proposalData) {
              if (msg.proposalData.tool === "create_ontology") {
                return (
                  <OntologyProposalCard
                    key={msg.id}
                    data={msg.proposalData}
                    toolStatus={msg.toolStatus}
                    createdOntologyId={msg.createdOntologyId}
                  />
                );
              }
              if (isAppWriteTool(msg.proposalData.tool)) {
                return (
                  <DashboardProposalCard
                    key={msg.id}
                    data={msg.proposalData}
                    toolStatus={msg.toolStatus}
                  />
                );
              }
              if (msg.proposalData.tool === "save_ontology_schema") {
                return (
                  <OntologySchemaProposalCard
                    key={msg.id}
                    data={msg.proposalData}
                    toolStatus={msg.toolStatus}
                  />
                );
              }
              if (msg.proposalData.tool === "create_csv_datasource") {
                return (
                  <CsvDatasourceProposalCard
                    key={msg.id}
                    data={msg.proposalData}
                    toolStatus={msg.toolStatus}
                    errorMessage={msg.errorMessage}
                  />
                );
              }
              return (
                <ConceptProposalCard
                  key={msg.id}
                  data={msg.proposalData}
                  toolStatus={msg.toolStatus}
                />
              );
            }

            return (
              <div
                key={msg.id}
                className={`flex flex-col gap-1 ${msg.role === "user" ? "items-end" : "items-start"}`}
              >
                {msg.role === "user" ? (
                  <UserMessageBubble
                    content={msg.content}
                    attachments={msg.attachments}
                    createdAt={msg.createdAt}
                    canEdit={canEditMessages}
                    onSubmitEdit={(newText) => handleSubmitEdit(msg.id, newText)}
                    onDelete={() => handleDeleteTurn(msg.id)}
                    bubbleClassName="max-w-[90%] bg-blue-500 text-white rounded-2xl rounded-br-md px-4 py-2.5 text-sm leading-relaxed whitespace-pre-wrap [-webkit-font-smoothing:antialiased] [overflow-wrap:break-word]"
                  />
                ) : (
                  <div className="code-assist-message max-w-full [-webkit-font-smoothing:antialiased] [overflow-wrap:break-word]">
                    <ReactMarkdown
                      remarkPlugins={[remarkGfm]}
                      rehypePlugins={[rehypeHighlight]}
                      components={chatMarkdownComponents}
                    >
                      {msg.content || "▍"}
                    </ReactMarkdown>
                  </div>
                )}
              </div>
            );
          })}

          {haltNotice && (
            <HaltNotice data={haltNotice} disabled={isLoading} onResume={resumeTurn} />
          )}

          {(() => {
            if (!isLoading) return null;
            const last = messages[messages.length - 1];
            // Already showing a spinner: running tool card, running proposal card,
            // streaming text, or the live thinking block.
            if (last?.role === "assistant" || last?.role === "thinking") return null;
            if (
              (last?.role === "tool" || last?.role === "proposal") &&
              last.toolStatus === "running"
            )
              return null;
            const label = !last || last.role === "user" ? "Thinking…" : "Working…";
            return (
              <div className="flex items-center gap-2 text-muted-foreground">
                <PrometheuxSpinner size={16} />
                <span className="text-sm">{label}</span>
              </div>
            );
          })()}
        </div>

        {/* Input resize handle — top edge */}
        <div
          onMouseDown={handleInputResizeMouseDown}
          className="flex-shrink-0 h-1 cursor-ns-resize relative border-t border-border"
        />

        {/* Input */}
        <div className="flex-shrink-0 px-3 pb-3 pt-1.5">
          <ChatInputBox
            input={input}
            onInputChange={handleInputChange}
            onKeyDown={handleKeyDown}
            textareaRef={textareaRef}
            manualHeight={manualHeight}
            isLoading={isLoading}
            attachments={attachments}
            onRemoveAttachment={removeAttachment}
            onAttachFile={attachFile}
            focusedWidget={focusedWidget}
            onClearFocusedWidget={() => setFocusedWidget(null)}
            onSend={() => handleSend()}
            onAbort={handleAbort}
            sendDisabled={attachmentsUploading || (!input.trim() && attachmentPaths.length === 0)}
            sendTitle={attachmentsUploading ? "Waiting for uploads…" : "Send (Enter)"}
            usageText={
              agentUsage?.isFreemium && agentUsage.remaining !== null
                ? `${agentUsage.remaining} of ${agentUsage.limit} agent messages left this month`
                : null
            }
            usageWarning={agentLimitReached}
          />
        </div>
      </div>
      {/* end main chat column */}

      {/* History sidebar — right side */}
      <ChatHistorySidebar />

      <AgentMessageLimitDialog />
    </div>
  );
};

export default CodeAssistantPanel;
