/**
 * HTML Sanitization Utilities
 *
 * This module provides functions to safely render user-controllable content
 * and prevent Cross-Site Scripting (XSS) attacks.
 *
 * IMPORTANT: Always use these utilities when rendering user input as HTML.
 */

/**
 * Escapes HTML entities to prevent XSS when displaying user input as text.
 * Use this when you want to display user input without any HTML interpretation.
 *
 * @param text - The raw text to escape
 * @returns The escaped text safe for insertion into HTML
 *
 * @example
 * const userInput = '<script>alert("xss")</script>';
 * const safe = escapeHtml(userInput);
 * // Returns: '&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;'
 */
const escapeHtml = (text: string): string => {
  if (!text) return "";

  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
};

/**
 * Formats a description with highlighted @mentions while preventing XSS.
 *
 * This function:
 * 1. First escapes all HTML in the input to prevent XSS
 * 2. Then applies safe transformations to highlight @mentions
 *
 * @param description - The raw description text (may contain @mentions)
 * @returns Safe HTML string with highlighted mentions
 *
 * @example
 * const desc = 'Uses @customer data <script>alert(1)</script>';
 * const safe = formatDescriptionWithMentions(desc);
 * // Returns: 'Uses <span class="...">customer</span> data &lt;script&gt;alert(1)&lt;/script&gt;'
 */
export const formatDescriptionWithMentions = (description: string): string => {
  if (!description) return "";

  // Step 1: Escape all HTML entities first to neutralize any malicious content
  const escaped = escapeHtml(description);

  // Step 2: Now safely apply the @mention highlighting
  // Since the input is already escaped, we can safely create our styled spans
  const withHighlightedMentions = escaped.replace(
    /@(\w+)/g,
    '<span class="inline-block bg-blue-100 text-blue-800 text-xs font-medium px-2 py-1 rounded-full mr-1 mb-1">$1</span>',
  );

  return withHighlightedMentions;
};
