import { Eye, EyeOff, Layers } from "lucide-react";
import { useState } from "react";
import type { GroupLegendEntry } from "./lineage-view/groupColors";

interface LineageGroupLegendProps {
  entries: GroupLegendEntry[];
  isGroupVisible: (key: string) => boolean;
  onToggleGroup: (key: string) => void;
}

interface GroupSwatchProps {
  color: string | null;
  dimmed: boolean;
}

function GroupSwatch({ color, dimmed }: GroupSwatchProps) {
  const swatchStyle = color
    ? { backgroundColor: color }
    : { backgroundColor: "hsl(var(--muted-foreground))" };
  return (
    <span
      className={`h-3 w-3 flex-shrink-0 rounded-sm ${dimmed ? "opacity-30" : ""}`}
      style={swatchStyle}
    />
  );
}

/**
 * Floating colour legend + group visibility filter for the lineage canvas.
 * Each row shows the group's colour swatch and concept count; clicking it
 * toggles that group's nodes on the graph. Collapses to a single icon button
 * so it never crowds the canvas.
 */
export function LineageGroupLegend({
  entries,
  isGroupVisible,
  onToggleGroup,
}: LineageGroupLegendProps) {
  const [open, setOpen] = useState(true);

  if (entries.length === 0) return null;

  if (!open) {
    return (
      <button
        type="button"
        onClick={() => setOpen(true)}
        title="Show group filter"
        aria-label="Show group filter"
        className="glass-card flex h-9 w-9 items-center justify-center rounded-md border border-border bg-card/90 text-muted-foreground shadow-md backdrop-blur transition-colors hover:text-foreground"
      >
        <Layers className="h-4 w-4" />
      </button>
    );
  }

  return (
    <div className="glass-card w-56 rounded-md border border-border bg-card/90 shadow-md backdrop-blur">
      <div className="flex items-center justify-between border-b border-border px-3 py-2">
        <div className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
          <Layers className="h-3.5 w-3.5 text-muted-foreground" />
          Groups
        </div>
        <button
          type="button"
          onClick={() => setOpen(false)}
          title="Hide group filter"
          aria-label="Hide group filter"
          className="text-muted-foreground transition-colors hover:text-foreground"
        >
          <EyeOff className="h-3.5 w-3.5" />
        </button>
      </div>

      <div className="max-h-64 overflow-y-auto py-1">
        {entries.map((entry) => {
          const visible = isGroupVisible(entry.key);
          return (
            <button
              key={entry.key}
              type="button"
              onClick={() => onToggleGroup(entry.key)}
              title={visible ? `Hide ${entry.label}` : `Show ${entry.label}`}
              className="flex w-full items-center gap-2 px-3 py-1.5 text-left text-xs transition-colors hover:bg-muted"
            >
              <GroupSwatch color={entry.color} dimmed={!visible} />
              <span
                className={`flex-1 truncate ${visible ? "text-foreground" : "text-muted-foreground line-through"}`}
              >
                {entry.label}
              </span>
              <span className="flex-shrink-0 text-[10px] font-mono text-muted-foreground">
                {entry.count}
              </span>
              {visible ? (
                <Eye className="h-3.5 w-3.5 flex-shrink-0 text-muted-foreground" />
              ) : (
                <EyeOff className="h-3.5 w-3.5 flex-shrink-0 text-muted-foreground" />
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}
