import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import {
  changeMemberRole,
  grantSeat,
  inviteToTeam,
  listTeamMembers,
  releaseSeat,
  removeMember,
} from "../api";
import type {
  AssignableTeamRole,
  Invitation,
  InviteRecipient,
  MemberRow,
  Membership,
  TeamError,
} from "../types";
import { MY_TEAMS_KEY } from "./useMyTeams";
import { TEAM_INVITATIONS_KEY } from "./useTeamInvitations";
import { TEAM_PENDING_INVITATIONS_KEY } from "./useTeamPendingInvitations";

// Keyed by team so switching between team detail pages doesn't fight over one
// cache slot. Includes the caller's userId so a sign-in flip re-fetches.
export const TEAM_MEMBERS_KEY = ["teams", "members"] as const;
const membersKey = (teamId: string, userId: string) =>
  [...TEAM_MEMBERS_KEY, teamId, userId] as const;

interface ChangeRoleInput {
  userId: string;
  role: AssignableTeamRole;
}

interface InviteInputVars {
  role: AssignableTeamRole;
  recipient: InviteRecipient;
}

interface UseTeamMembersOptions {
  enabled?: boolean;
}

interface UseTeamMembersReturn {
  members: MemberRow[];
  isLoading: boolean;
  isFetching: boolean;
  error: TeamError | null;
  refresh: () => Promise<unknown>;

  invite: (input: InviteInputVars) => Promise<Invitation>;
  isInviting: boolean;

  changeRole: (input: ChangeRoleInput) => Promise<Membership>;
  isChangingRole: boolean;
  updatingUserId: string | null;

  remove: (userId: string) => Promise<{ team_id: string; user_id: string; status: "removed" }>;
  isRemoving: boolean;
  removingUserId: string | null;

  grantSeat: (userId: string) => Promise<{ team_id: string; user_id: string; seat_granted: true }>;
  releaseSeat: (
    userId: string,
  ) => Promise<{ team_id: string; user_id: string; seat_granted: false }>;
  isUpdatingSeat: boolean;
  seatUpdatingUserId: string | null;
}

// Roster + invite/role/remove mutations for a single team. Bundled together
// because they all target the same team_id and every one invalidates this
// same query — grouping avoids ceremony at the call site (TeamRosterPanel
// pulls one hook).
export function useTeamMembers(
  teamId: string | null | undefined,
  { enabled = true }: UseTeamMembersOptions = {},
): UseTeamMembersReturn {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";
  const safeTeamId = teamId ?? "";

  const query = useQuery<MemberRow[], TeamError>({
    queryKey: membersKey(safeTeamId, userId),
    queryFn: () => listTeamMembers(safeTeamId, supabaseToken),
    enabled: enabled && Boolean(userId && supabaseToken && safeTeamId),
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const inviteMutation = useMutation<Invitation, TeamError, InviteInputVars>({
    mutationFn: ({ role, recipient }) =>
      inviteToTeam({ team_id: safeTeamId, role, recipient }, supabaseToken),
    onSuccess: () => {
      // The roster itself doesn't change on invite (member added on accept),
      // but two adjacent queries do:
      //   * TEAM_INVITATIONS_KEY — the *invitee's* inbox. If they happen to be
      //     signed in on the same client (dev flows, shared devices), this
      //     keeps their card up to date.
      //   * TEAM_PENDING_INVITATIONS_KEY — the team-side outbox of pending
      //     invitations. The row we just created must appear immediately in
      //     the "Pending invitations" section for the sender.
      queryClient.invalidateQueries({ queryKey: TEAM_INVITATIONS_KEY });
      queryClient.invalidateQueries({
        queryKey: [...TEAM_PENDING_INVITATIONS_KEY, safeTeamId],
      });
    },
  });

  const changeRoleMutation = useMutation<Membership, TeamError, ChangeRoleInput>({
    mutationFn: ({ userId: memberId, role }) =>
      changeMemberRole(safeTeamId, memberId, role, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [...TEAM_MEMBERS_KEY, safeTeamId] });
    },
  });

  const removeMutation = useMutation<
    { team_id: string; user_id: string; status: "removed" },
    TeamError,
    string
  >({
    mutationFn: (memberId) => removeMember(safeTeamId, memberId, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [...TEAM_MEMBERS_KEY, safeTeamId] });
    },
  });

  // Seat mutations invalidate both the roster (per-member seat_granted flips)
  // AND the caller's team list (seats_used and — for the target if they're
  // signed in on the same client — seat_granted flips). Failures bubble as
  // TeamError so the UI can branch on httpStatus 409 (out of seats / owner
  // seat is protected) and surface the backend `detail`.
  const grantSeatMutation = useMutation<
    { team_id: string; user_id: string; seat_granted: true },
    TeamError,
    string
  >({
    mutationFn: (memberId) => grantSeat(safeTeamId, memberId, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [...TEAM_MEMBERS_KEY, safeTeamId] });
      queryClient.invalidateQueries({ queryKey: MY_TEAMS_KEY });
    },
  });

  const releaseSeatMutation = useMutation<
    { team_id: string; user_id: string; seat_granted: false },
    TeamError,
    string
  >({
    mutationFn: (memberId) => releaseSeat(safeTeamId, memberId, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [...TEAM_MEMBERS_KEY, safeTeamId] });
      queryClient.invalidateQueries({ queryKey: MY_TEAMS_KEY });
    },
  });

  const isUpdatingSeat = grantSeatMutation.isPending || releaseSeatMutation.isPending;
  const seatUpdatingUserId = grantSeatMutation.isPending
    ? (grantSeatMutation.variables ?? null)
    : releaseSeatMutation.isPending
      ? (releaseSeatMutation.variables ?? null)
      : null;

  return {
    members: query.data ?? [],
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    refresh: query.refetch,

    invite: inviteMutation.mutateAsync,
    isInviting: inviteMutation.isPending,

    changeRole: changeRoleMutation.mutateAsync,
    isChangingRole: changeRoleMutation.isPending,
    updatingUserId: changeRoleMutation.isPending
      ? (changeRoleMutation.variables?.userId ?? null)
      : null,

    remove: removeMutation.mutateAsync,
    isRemoving: removeMutation.isPending,
    removingUserId: removeMutation.isPending ? (removeMutation.variables ?? null) : null,

    grantSeat: grantSeatMutation.mutateAsync,
    releaseSeat: releaseSeatMutation.mutateAsync,
    isUpdatingSeat,
    seatUpdatingUserId,
  };
}
