/**
 * Tool-name predicates for routing a streamed proposal to the right card.
 *
 * Listing them here is what stops an app proposal from falling through to the
 * generic concept card and reading "Creating concept".
 */
const APP_WRITE_TOOLS = ["save_app", "delete_app"] as const;

export function isAppWriteTool(tool: string): boolean {
  return APP_WRITE_TOOLS.some((name) => name === tool);
}
