import { Graph, type IElementEvent } from "@antv/g6";
import { Search, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { useThemeStore } from "@/shared/store/themeStore";
import {
  analyticsLegend,
  buildCanvasData,
  type CanvasAnalytics,
  truncateLabel,
} from "../graphExplorer.utils";
import type { ExplorerEdge, ExplorerNode } from "../types";
import { CanvasZoomControls } from "./CanvasZoomControls";

import {
  asCanvasEdge,
  asCanvasNode,
  buildLayout,
  LARGE_GRAPH_THRESHOLD,
  LAYOUTS,
  type LayoutType,
  resolveEdgeLabelFill,
  resolveEdgeStroke,
  resolveGrayedPalette,
  resolveGridStroke,
  resolveLabelBackground,
  resolveNodeLabelFill,
  SELECTED_LINE_WIDTH,
  seedNewNodePositions,
} from "./explorerCanvas.utils";

/** Zoom level applied when focusing a searched node (skipped if already closer). */
const SEARCH_FOCUS_ZOOM = 2;

interface ExplorerCanvasProps {
  nodes: Record<string, ExplorerNode>;
  edges: Record<string, ExplorerEdge>;
  selectedNodeId: string | null;
  onSelectNode: (nodeId: string | null) => void;
  onExpandNode: (nodeId: string) => void;
  /** Whether node expansion is available (records mode only). Gates the
   * double-click handler and the on-canvas hint. */
  canExpand?: boolean;
  /** Records-mode: nodes the user has expanded (drawn with an accent ring). */
  expandedNodeIds?: Set<string>;
  /** Records-mode: nodes with an expansion fetch in flight (dimmed). */
  expandingNodeIds?: Set<string>;
  /** Bumped by the parent to request the camera zoom/center the selected node
   * (e.g. clicking a connection in the node panel). Plain canvas clicks don't
   * change it, so they select without moving the camera. */
  focusToken?: number;
  analytics?: CanvasAnalytics;
}

export function ExplorerCanvas({
  nodes,
  edges,
  selectedNodeId,
  onSelectNode,
  onExpandNode,
  canExpand = false,
  expandedNodeIds,
  expandingNodeIds,
  focusToken,
  analytics,
}: ExplorerCanvasProps) {
  const { theme } = useThemeStore();
  const containerRef = useRef<HTMLDivElement>(null);
  const graphRef = useRef<Graph | null>(null);
  const renderedRef = useRef(false);

  const [layoutType, setLayoutType] = useState<LayoutType>("force");
  // True while a layout run (initial render, full rebuild, or layout switch) is
  // computing. The force simulation can take a moment on larger graphs, so we
  // veil the canvas until the settled positions are drawn instead of showing
  // nodes mid-arrangement.
  const [isLayouting, setIsLayouting] = useState(false);
  // Canvas-native "find a node" query — matched client-side against the loaded
  // nodes; picking a match focuses the camera and selects it.
  const [nodeQuery, setNodeQuery] = useState("");

  const canvasData = useMemo(
    () => buildCanvasData(nodes, edges, analytics),
    [nodes, edges, analytics],
  );
  const isLargeGraph = canvasData.nodes.length >= LARGE_GRAPH_THRESHOLD;
  const analyticsLegendText = analyticsLegend(analytics);
  const hasNodes = canvasData.nodes.length > 0;

  const nodeMatches = useMemo(() => {
    const query = nodeQuery.trim().toLowerCase();
    if (!query) return [];
    const matches: Array<{ id: string; label: string }> = [];
    for (const node of canvasData.nodes) {
      if (node._label.toLowerCase().includes(query) || node.id.toLowerCase().includes(query)) {
        matches.push({ id: node.id, label: node._label });
        if (matches.length >= 8) break;
      }
    }
    return matches;
  }, [nodeQuery, canvasData.nodes]);

  const layoutRef = useRef<LayoutType>(layoutType);
  layoutRef.current = layoutType;
  // Latest canvas data, so the create-effect (which only re-runs on theme /
  // presence) always seeds the graph with the current nodes/edges.
  const canvasDataRef = useRef(canvasData);
  canvasDataRef.current = canvasData;
  const selectHandlerRef = useRef(onSelectNode);
  selectHandlerRef.current = onSelectNode;
  const expandHandlerRef = useRef(onExpandNode);
  expandHandlerRef.current = onExpandNode;
  const canExpandRef = useRef(canExpand);
  canExpandRef.current = canExpand;
  const gridStrokeRef = useRef(resolveGridStroke(theme));
  gridStrokeRef.current = resolveGridStroke(theme);
  // Latest selected id, so the focus-token effect can center it without
  // re-firing whenever the selection itself changes (canvas clicks must not
  // move the camera).
  const selectedNodeIdRef = useRef(selectedNodeId);
  selectedNodeIdRef.current = selectedNodeId;

  useEffect(() => {
    if (!containerRef.current || !hasNodes) return;

    const data = canvasDataRef.current;
    const large = data.nodes.length >= LARGE_GRAPH_THRESHOLD;
    const graph = new Graph({
      container: containerRef.current,
      autoResize: true,
      autoFit: "view",
      padding: 64,
      // Disable animation entirely: with it on, the force layout renders every
      // simulation tick, so nodes visibly drift for a few seconds before they
      // settle. Off, G6 runs the simulation to completion and commits the final
      // positions in a single draw — the graph appears already-arranged.
      animation: false,
      data,
      layout: buildLayout(layoutRef.current, large),
      node: {
        style: {
          size: (d: unknown) => asCanvasNode(d)._size ?? (large ? 16 : 30),
          fill: (d: unknown) => asCanvasNode(d)._fill ?? "#6C5CE7",
          stroke: (d: unknown) => asCanvasNode(d)._stroke ?? "#5346C8",
          lineWidth: 1.5,
          labelText: large
            ? undefined
            : (d: unknown) => {
                const node = asCanvasNode(d);
                return truncateLabel(String(node._label ?? node.id ?? ""));
              },
          labelFontSize: 11,
          labelPlacement: "bottom",
          labelFill: resolveNodeLabelFill(theme),
          labelBackground: true,
          labelBackgroundFill: resolveLabelBackground(theme),
          labelBackgroundOpacity: 0.85,
          labelBackgroundRadius: 4,
          labelBackgroundPadding: [1, 4, 1, 4],
        },
        state: {
          selected: {
            lineWidth: SELECTED_LINE_WIDTH,
            stroke: theme === "dark" ? "#f8fafc" : "#0f172a",
          },
          // Custom state name: G6's built-in "inactive" adds transparency.
          muted: {
            fill: resolveGrayedPalette(theme).nodeFill,
            stroke: resolveGrayedPalette(theme).nodeStroke,
            labelFill: resolveGrayedPalette(theme).label,
            opacity: 1,
            fillOpacity: 1,
            strokeOpacity: 1,
          },
          // Expanded: an accent ring so the user can see what they've grown.
          expanded: {
            lineWidth: 3,
            stroke: theme === "dark" ? "#2dd4bf" : "#0d9488",
          },
          // Expanding: dim the node while its neighbors are being fetched.
          expanding: {
            fillOpacity: 0.45,
            strokeOpacity: 0.45,
          },
        },
      },
      edge: {
        style: {
          stroke: (d: unknown) => asCanvasEdge(d)._stroke ?? resolveEdgeStroke(theme),
          strokeOpacity: large ? 0.35 : 0.55,
          lineWidth: large ? 0.5 : 1.5,
          endArrow: !large,
          endArrowSize: 8,
          labelText: large
            ? undefined
            : (d: unknown) => truncateLabel(String(asCanvasEdge(d)._label ?? ""), 14),
          labelFontSize: 9,
          labelFill: resolveEdgeLabelFill(theme),
          labelBackground: true,
          labelBackgroundFill: resolveLabelBackground(theme),
          labelBackgroundOpacity: 0.85,
          labelBackgroundRadius: 3,
          labelBackgroundPadding: [1, 3, 1, 3],
        },
        state: {
          highlight: {
            stroke: (d: unknown) => {
              const edge = asCanvasEdge(d);
              return edge._strokeActive ?? edge._stroke ?? resolveEdgeStroke(theme);
            },
            strokeOpacity: 0.95,
            lineWidth: 2.5,
          },
          muted: {
            stroke: resolveGrayedPalette(theme).edge,
            strokeOpacity: 1, // solid gray, no transparency
            opacity: 1,
            labelFill: resolveGrayedPalette(theme).label,
          },
        },
      },
      behaviors: ["drag-canvas", "zoom-canvas", "drag-element"],
      plugins: [
        {
          key: "grid-line",
          type: "grid-line",
          size: 20,
          stroke: gridStrokeRef.current,
          border: false,
          follow: true,
        },
      ],
    });

    graph.on<IElementEvent>("node:click", (evt) => {
      const id = String(evt?.target?.id ?? "");
      if (id) selectHandlerRef.current(id);
    });
    graph.on<IElementEvent>("node:dblclick", (evt) => {
      if (!canExpandRef.current) return;
      const id = String(evt?.target?.id ?? "");
      if (id) expandHandlerRef.current(id);
    });
    graph.on("canvas:click", () => selectHandlerRef.current(null));

    graphRef.current = graph;
    renderedRef.current = false;
    setIsLayouting(true);
    graph
      .render()
      .then(() => {
        renderedRef.current = true;
      })
      .catch((error: unknown) => {
        // render() rejects when the graph is destroyed mid-render (e.g. the
        // StrictMode dev double-mount). Only surface errors for live graphs.
        if (!graph.destroyed) console.error("Graph render failed:", error);
      })
      .finally(() => {
        // Guard against the StrictMode double-mount clearing the flag for the
        // graph that replaced this one.
        if (graphRef.current === graph) setIsLayouting(false);
      });

    return () => {
      renderedRef.current = false;
      graph.destroy();
      graphRef.current = null;
    };
    // The graph is recreated only when the theme changes (option mappers close
    // over it) or when nodes first appear / fully disappear. Ongoing data
    // changes are handled incrementally by the sync effect below.
  }, [theme, hasNodes]); // eslint-disable-line react-hooks/exhaustive-deps

  // Data sync: reconcile the live graph with canvasData while keeping every
  // surviving node exactly where it is. We pin each still-present node to its
  // current position and place only the genuinely-new nodes (on a ring around
  // the neighbor they attach to), then push the *whole* graph with a single
  // setData + draw. setData reconciles adds, removes, re-adds and restyles from
  // the full data; draw() paints without running a layout (only setLayout /
  // render do), so nothing already on the canvas moves. A full relayout happens
  // only when the graph is fresh — no node in common (new concept / analytics
  // recompute). Rebuilding from the complete data every time (rather than an
  // incremental add/remove diff) is what lets a collapsed node be expanded again
  // reliably: the removed neighbors simply reappear in the data.
  useEffect(() => {
    const graph = graphRef.current;
    if (!graph || !renderedRef.current) return;

    const rebuild = () => {
      const large = canvasData.nodes.length >= LARGE_GRAPH_THRESHOLD;
      graph.setData(canvasData);
      graph.setLayout(buildLayout(layoutRef.current, large));
      setIsLayouting(true);
      void graph
        .draw()
        .then(() => graph.fitView())
        .catch(() => {})
        .finally(() => {
          if (graphRef.current === graph) setIsLayouting(false);
        });
    };

    try {
      const livePositions = new Map<string, [number, number]>();
      for (const node of graph.getNodeData()) {
        const id = String(node.id);
        const position = graph.getElementPosition(id);
        if (position && Number.isFinite(position[0]) && Number.isFinite(position[1])) {
          livePositions.set(id, [position[0], position[1]]);
        }
      }

      const existingNodeIds = new Set(livePositions.keys());
      const sharesNodes = canvasData.nodes.some((node) => existingNodeIds.has(node.id));

      // Fresh graph (nothing placed yet, or a wholly new node set) → lay it out.
      if (existingNodeIds.size === 0 || !sharesNodes) {
        rebuild();
        return;
      }

      const newNodes = canvasData.nodes.filter((node) => !existingNodeIds.has(node.id));
      const seededNew = seedNewNodePositions(
        newNodes,
        canvasData.edges,
        existingNodeIds,
        (id) => livePositions.get(id) ?? null,
      );
      const newStyleById = new Map<string, { x: number; y: number }>();
      for (const node of seededNew) {
        if (node.style) newStyleById.set(node.id, node.style);
      }

      const positioned = canvasData.nodes.map((node) => {
        const live = livePositions.get(node.id);
        if (live) return { ...node, style: { x: live[0], y: live[1] } };
        const seededStyle = newStyleById.get(node.id);
        return seededStyle ? { ...node, style: seededStyle } : node;
      });

      graph.setData({ nodes: positioned, edges: canvasData.edges });
      void graph.draw().catch(() => {});
    } catch (error) {
      console.error("Graph data sync failed, rebuilding:", error);
      rebuild();
    }
  }, [canvasData]);

  // Selection highlight, lineage-style: the selected node gets a bright ring,
  // its edges light up in the full node color, direct neighbors keep their
  // colors, and everything unrelated is grayed out — solid, no transparency —
  // mirroring the connections listed in the panel. Uses element states so the
  // styles override the option mappers.
  useEffect(() => {
    const graph = graphRef.current;
    if (!graph || !renderedRef.current) return;

    const connectedEdgeIds = new Set<string>();
    const neighborIds = new Set<string>();
    if (selectedNodeId) {
      for (const edge of canvasData.edges) {
        if (edge.source !== selectedNodeId && edge.target !== selectedNodeId) continue;
        connectedEdgeIds.add(edge.id);
        neighborIds.add(edge.source === selectedNodeId ? edge.target : edge.source);
      }
    }

    const selectionStateFor = (nodeId: string): string[] => {
      if (!selectedNodeId) return [];
      if (nodeId === selectedNodeId) return ["selected"];
      if (neighborIds.has(nodeId)) return [];
      return ["muted"];
    };
    // Expansion affordances layer on top of selection so an expanded node keeps
    // its accent ring even when another node is selected.
    const expansionStateFor = (nodeId: string): string[] => {
      if (expandingNodeIds?.has(nodeId)) return ["expanding"];
      if (expandedNodeIds?.has(nodeId)) return ["expanded"];
      return [];
    };
    const edgeStateFor = (edgeId: string): string[] => {
      if (!selectedNodeId) return [];
      return connectedEdgeIds.has(edgeId) ? ["highlight"] : ["muted"];
    };

    const states: Record<string, string[]> = {};
    for (const node of canvasData.nodes) {
      states[node.id] = [...selectionStateFor(node.id), ...expansionStateFor(node.id)];
    }
    for (const edge of canvasData.edges) states[edge.id] = edgeStateFor(edge.id);
    void graph.setElementState(states);
  }, [selectedNodeId, canvasData, expandedNodeIds, expandingNodeIds]);

  useEffect(() => {
    const graph = graphRef.current;
    if (!graph || !renderedRef.current) return;
    setIsLayouting(true);
    graph
      .layout(buildLayout(layoutType, isLargeGraph))
      .then(() => graph.fitView())
      .catch(() => {})
      .finally(() => {
        if (graphRef.current === graph) setIsLayouting(false);
      });
  }, [layoutType, isLargeGraph]);

  useEffect(() => {
    graphRef.current?.updatePlugin({ key: "grid-line", stroke: resolveGridStroke(theme) });
  }, [theme]);

  // G6's autoResize only tracks window resizes; when the inspector panel
  // mounts/unmounts the flex container changes size without one, so the
  // canvas would keep its old width and push the panel off-screen. Re-fit
  // after resizing so the graph re-centers into the remaining space.
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const observer = new ResizeObserver(() => {
      const graph = graphRef.current;
      if (!graph || !renderedRef.current) return;
      graph.resize(container.clientWidth, container.clientHeight);
      void graph.fitView();
    });
    observer.observe(container);
    return () => observer.disconnect();
  }, []);

  const handleZoomIn = () => {
    void graphRef.current?.zoomBy(1.25);
  };
  const handleZoomOut = () => {
    void graphRef.current?.zoomBy(0.8);
  };
  const handleFitView = () => {
    void graphRef.current?.fitView();
  };

  // Zoom in to a comfortable level (never zooming back out if the user is
  // already closer) and center the node.
  const focusCamera = useCallback(async (id: string) => {
    const graph = graphRef.current;
    if (!graph) return;
    try {
      if (graph.getZoom() < SEARCH_FOCUS_ZOOM) await graph.zoomTo(SEARCH_FOCUS_ZOOM);
      await graph.focusElement(id);
    } catch {
      // focusElement/zoomTo can reject on a destroyed graph; selection still applies.
    }
  }, []);

  // Search pick: select the node (reusing the standard highlight), focus the
  // camera, and close the dropdown.
  const focusNode = (id: string) => {
    onSelectNode(id);
    setNodeQuery("");
    void focusCamera(id);
  };

  // Parent-requested focus (e.g. a connection clicked in the node panel): zoom
  // to and center the currently-selected node. Skips the initial mount (token
  // 0/undefined); only re-fires when the token changes, so plain canvas
  // selection never moves the camera.
  useEffect(() => {
    if (!focusToken) return;
    const id = selectedNodeIdRef.current;
    if (id) void focusCamera(id);
  }, [focusToken, focusCamera]);

  const handleNodeQueryChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setNodeQuery(event.target.value);
  };

  const clearNodeQuery = () => setNodeQuery("");

  if (canvasData.nodes.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center text-sm text-muted-foreground">
        Search your data to place nodes on the canvas
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col min-h-0 min-w-0">
      <div className="flex items-center gap-2 px-3 py-1.5 border-b border-border flex-shrink-0">
        <span className="text-[11px] text-muted-foreground">Layout</span>
        <select
          value={layoutType}
          onChange={(e) => setLayoutType(e.target.value as LayoutType)}
          className="text-[11px] bg-background border border-border rounded px-2 py-0.5 text-foreground cursor-pointer focus:outline-none focus:ring-1 focus:ring-ring"
        >
          {LAYOUTS.map((layout) => (
            <option key={layout.value} value={layout.value}>
              {layout.label}
            </option>
          ))}
        </select>

        <div className="relative">
          <div className="flex items-center gap-1 rounded border border-border bg-background px-1.5">
            <Search className="h-3 w-3 flex-shrink-0 text-muted-foreground" />
            <input
              type="text"
              value={nodeQuery}
              onChange={handleNodeQueryChange}
              placeholder="Find node…"
              className="w-32 bg-transparent py-0.5 text-[11px] text-foreground placeholder:text-muted-foreground focus:outline-none"
            />
            {nodeQuery && (
              <button
                type="button"
                onClick={clearNodeQuery}
                title="Clear"
                className="flex-shrink-0 text-muted-foreground hover:text-foreground"
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>
          {nodeMatches.length > 0 && (
            <ul className="absolute left-0 top-full z-20 mt-1 max-h-56 w-56 overflow-y-auto rounded-md border border-border bg-card py-1 shadow-md">
              {nodeMatches.map((match) => (
                <li key={match.id}>
                  <button
                    type="button"
                    onClick={() => void focusNode(match.id)}
                    title={match.label}
                    className="block w-full truncate px-2 py-1 text-left text-[11px] text-foreground hover:bg-accent"
                  >
                    {match.label}
                  </button>
                </li>
              ))}
            </ul>
          )}
          {nodeQuery.trim() && nodeMatches.length === 0 && (
            <div className="absolute left-0 top-full z-20 mt-1 w-56 rounded-md border border-border bg-card px-2 py-1.5 text-[11px] text-muted-foreground shadow-md">
              No matching nodes on the canvas.
            </div>
          )}
        </div>

        {analyticsLegendText && (
          <span className="text-[11px] text-muted-foreground border border-border rounded px-1.5 py-0.5">
            {analyticsLegendText}
          </span>
        )}
        <span className="text-[11px] text-muted-foreground ml-auto">
          {canvasData.nodes.length} nodes · {canvasData.edges.length} edges
          {canExpand ? " · double-click to expand" : ""}
        </span>
      </div>
      <div className="relative flex-1 min-h-0 min-w-0">
        {/* G6 overwrites the container's position with an inline `position:
            relative`, which disables `absolute inset-0` sizing and freezes the
            height at mount time — size it explicitly instead. */}
        <div ref={containerRef} className="h-full w-full overflow-hidden" />
        {isLayouting && (
          <div className="absolute inset-0 z-10 flex flex-col items-center justify-center gap-3 bg-background/70 backdrop-blur-sm">
            <PrometheuxSpinner size={40} />
            <p className="text-xs text-muted-foreground">Arranging graph…</p>
          </div>
        )}
        <CanvasZoomControls
          onZoomIn={handleZoomIn}
          onZoomOut={handleZoomOut}
          onFitView={handleFitView}
        />
      </div>
    </div>
  );
}
