import { useState } from "react";
import { toast } from "sonner";
import { supabase } from "@/shared/integrations/supabase/client";

const BILLING_RETURN_PATH = "/settings/billing";
const STRIPE_SESSION_PLACEHOLDER = "{CHECKOUT_SESSION_ID}";

interface UrlResponse {
  url: string;
}

const isUrlResponse = (value: unknown): value is UrlResponse => {
  if (typeof value !== "object" || value === null) return false;
  if (!("url" in value) || typeof value.url !== "string") return false;
  return true;
};

// supabase-js raises a FunctionsHttpError whose `context` is the underlying
// fetch Response. We read status without forcing a cast so we can branch on
// the 404 that create-customer-portal returns when no Stripe customer exists.
const getFunctionsErrorStatus = (err: unknown): number | undefined => {
  if (typeof err !== "object" || err === null) return undefined;
  if (!("context" in err)) return undefined;
  const ctx = err.context;
  if (!(ctx instanceof Response)) return undefined;
  return ctx.status;
};

export interface UseBillingActionsResult {
  startCheckout: () => Promise<void>;
  openCustomerPortal: () => Promise<void>;
  isLaunchingCheckout: boolean;
  isOpeningPortal: boolean;
}

export const useBillingActions = (): UseBillingActionsResult => {
  const [isLaunchingCheckout, setIsLaunchingCheckout] = useState(false);
  const [isOpeningPortal, setIsOpeningPortal] = useState(false);

  const startCheckout = async (): Promise<void> => {
    setIsLaunchingCheckout(true);
    try {
      const origin = window.location.origin;
      // {CHECKOUT_SESSION_ID} is a literal placeholder Stripe substitutes on
      // redirect — do NOT URL-encode it or pre-fill it. The edge function
      // forwards it verbatim.
      const success_url = `${origin}${BILLING_RETURN_PATH}?session_id=${STRIPE_SESSION_PLACEHOLDER}`;
      const cancel_url = `${origin}${BILLING_RETURN_PATH}`;
      const { data, error } = await supabase.functions.invoke("create-checkout", {
        body: { success_url, cancel_url },
      });
      if (error) throw error;
      if (!isUrlResponse(data)) {
        throw new Error("create-checkout response missing 'url'");
      }
      window.location.href = data.url;
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to open checkout";
      toast.error(message);
      setIsLaunchingCheckout(false);
    }
  };

  const openCustomerPortal = async (): Promise<void> => {
    setIsOpeningPortal(true);
    try {
      const return_url = `${window.location.origin}${BILLING_RETURN_PATH}`;
      const { data, error } = await supabase.functions.invoke("create-customer-portal", {
        body: { return_url },
      });
      if (error) {
        if (getFunctionsErrorStatus(error) === 404) {
          toast.error("No active subscription found. Set up billing first.");
          setIsOpeningPortal(false);
          return;
        }
        throw error;
      }
      if (!isUrlResponse(data)) {
        throw new Error("create-customer-portal response missing 'url'");
      }
      window.location.href = data.url;
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to open customer portal";
      toast.error(message);
      setIsOpeningPortal(false);
    }
  };

  return { startCheckout, openCustomerPortal, isLaunchingCheckout, isOpeningPortal };
};
