import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpError, HttpService } from "@/shared/services/httpService";

const extractMessage = (body: unknown): string | null => {
  if (
    typeof body === "object" &&
    body !== null &&
    "message" in body &&
    typeof body.message === "string"
  ) {
    return body.message;
  }
  return null;
};

/**
 * Base client providing shared functionality for Prometheux API access
 */
export class BaseClient {
  protected async post(
    endpoint: string,
    data: any,
    authToken?: string,
    additionalHeaders?: Record<string, string>,
  ) {
    return HttpService.post(
      `${PROMETHEUX_CONFIG.BASE_URL}${endpoint}`,
      data,
      authToken,
      additionalHeaders,
    );
  }

  protected async get(
    endpoint: string,
    authToken?: string,
    additionalHeaders?: Record<string, string>,
  ) {
    return HttpService.get(
      `${PROMETHEUX_CONFIG.BASE_URL}${endpoint}`,
      authToken,
      additionalHeaders,
    );
  }

  protected async patch(
    endpoint: string,
    data: any,
    authToken?: string,
    additionalHeaders?: Record<string, string>,
  ) {
    return HttpService.patch(
      `${PROMETHEUX_CONFIG.BASE_URL}${endpoint}`,
      data,
      authToken,
      additionalHeaders,
    );
  }

  protected async delete(endpoint: string, additionalHeaders?: Record<string, string>) {
    return HttpService.delete(
      `${PROMETHEUX_CONFIG.BASE_URL}${endpoint}`,
      undefined,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      additionalHeaders,
    );
  }

  /**
   * Upload a file using multipart/form-data with progress tracking
   * Uses XMLHttpRequest to support upload progress events
   */
  protected async uploadMultipart(
    endpoint: string,
    formData: FormData,
    onProgress?: (progress: number) => void,
  ): Promise<any> {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      const url = `${PROMETHEUX_CONFIG.BASE_URL}${endpoint}`;

      // Track upload progress
      if (onProgress) {
        xhr.upload.addEventListener("progress", (e) => {
          if (e.lengthComputable) {
            const percentComplete = (e.loaded / e.total) * 100;
            onProgress(percentComplete);
          }
        });
      }

      // Handle completion
      xhr.addEventListener("load", () => {
        if (xhr.status >= 200 && xhr.status < 300) {
          try {
            const response = JSON.parse(xhr.responseText);
            resolve(response);
          } catch {
            resolve(xhr.responseText);
          }
        } else {
          const fallback = `Upload failed with status ${xhr.status}`;
          let parsedBody: unknown;
          try {
            parsedBody = JSON.parse(xhr.responseText);
          } catch {
            parsedBody = undefined;
          }
          // Reject with HttpError (carrying status + parsed body) so callers can
          // tell apart structured failures like the freemium storage cap (402).
          reject(new HttpError(extractMessage(parsedBody) ?? fallback, xhr.status, parsedBody));
        }
      });

      // Handle errors
      xhr.addEventListener("error", () => {
        reject(new Error("Network error during upload"));
      });

      xhr.addEventListener("abort", () => {
        reject(new Error("Upload was aborted"));
      });

      // Open and send request
      xhr.open("POST", url);

      // Set authorization header
      const authToken = PROMETHEUX_CONFIG.AUTH_TOKEN;
      if (authToken) {
        xhr.setRequestHeader("Authorization", `Bearer ${authToken}`);
      }

      // Don't set Content-Type - let browser set it with boundary for multipart
      xhr.send(formData);
    });
  }
}
