import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

/**
 * Fetching an attachment back from `disk/` so a restored conversation can show
 * it. Object URLs are memoised per path: the same screenshot is referenced by
 * every chip for that turn, and re-fetching on each render would both hammer
 * the endpoint and leak a new URL every time.
 */
const previewCache = new Map<string, Promise<string>>();

function buildDownloadUrl(path: string): string {
  return `${PROMETHEUX_CONFIG.BASE_URL}/data/files/download?path=${encodeURIComponent(path)}`;
}

/**
 * The file is gone for good — deleted, or swept by attachment retention once
 * the conversation went cold. Distinct from a transient failure, because there
 * is no point offering a retry and the chip should say so.
 */
export class AttachmentGoneError extends Error {
  constructor(path: string) {
    super(`Attachment no longer available: ${path}`);
    this.name = "AttachmentGoneError";
  }
}

const HTTP_NOT_FOUND = 404;

async function fetchObjectUrl(path: string): Promise<string> {
  const response = await fetch(buildDownloadUrl(path), {
    headers: { Authorization: `Bearer ${PROMETHEUX_CONFIG.AUTH_TOKEN || ""}` },
    mode: "cors",
  });
  if (response.status === HTTP_NOT_FOUND) throw new AttachmentGoneError(path);
  if (!response.ok) throw new Error(`Could not load attachment (${response.status})`);
  return URL.createObjectURL(await response.blob());
}

/** Object URL for a stored attachment, fetched once per path per session. */
export function loadAttachmentPreview(path: string): Promise<string> {
  const cached = previewCache.get(path);
  if (cached) return cached;

  // A failed fetch is evicted so a retry is possible — a cached rejection would
  // make one network blip permanent for the rest of the session.
  const pending = fetchObjectUrl(path).catch((err: unknown) => {
    previewCache.delete(path);
    throw err;
  });
  previewCache.set(path, pending);
  return pending;
}

/** Trigger a browser download for a stored attachment. */
export async function downloadAttachment(path: string, fileName: string): Promise<void> {
  const objectUrl = await loadAttachmentPreview(path);
  const link = document.createElement("a");
  link.href = objectUrl;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
}
