import { create } from "zustand";
import {
  DASHBOARD_CONFIG_MAP,
  DASHBOARD_ID_TO_COMPONENT_NAME,
} from "@/features/dashboards/dashboardConfigRegistry";
import { COMPONENT_MAP, type DashboardEntry } from "@/features/dashboards/dashboardRegistry";
import { remoteEntryUrlFor } from "@/features/dashboards/remotes/appsBaseUrl";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

interface PermissionValue {
  enabled: boolean;
  metadata?: Record<string, string>;
}

export interface Permission {
  permission_id: string;
  key: string;
  permission_type: string;
  description: string | null;
  value: PermissionValue;
  source: string;
}

interface PermissionsStore {
  permissions: Permission[];
  loaded: boolean;
  visibleApps: DashboardEntry[];
  defaultRoute: string | null;
  singlePageRoute: string | null;
  hasAnyAccess: boolean;
  setPermissions: (permissions: Permission[]) => void;
  clearPermissions: () => void;
  canSee: (key: string) => boolean;
  canEdit: (key: string) => boolean;
  // Rollout-friendly variant: returns true if the key is enabled OR if the key is
  // not yet present in the user's permissions at all (e.g. a freshly-introduced
  // feature whose backend seed hasn't landed yet). Use sparingly — only when the
  // backend doesn't enforce the permission and you want graceful UI rollout.
  canSeeOrUnknown: (key: string) => boolean;
}

// Ordered list of navigable pages — order determines defaultRoute priority and must
// mirror the visual order of items in the sidebar (see SidePanel.tsx).
// The { kind: "apps" } marker represents the Apps group; it expands to one route per
// visible app at the position where Apps sits in the sidebar (between Dashboards and
// Compute). Without this marker, app routes would be appended after Settings and a
// user with only Settings + app permissions would land on Settings.
// can_see_ai_agent maps to "/" (the AI assistant home, same content as /:org/:username).
type SectionEntry = { kind: "permission"; key: string; route: string } | { kind: "apps" };

const SECTION_ROUTES: SectionEntry[] = [
  { kind: "permission", key: "can_see_ai_agent", route: "/" },
  { kind: "permission", key: "can_see_projects", route: "/ontologies" },
  { kind: "permission", key: "can_see_datasources", route: "/datasources" },
  { kind: "permission", key: "can_see_graph_explorer", route: "/graph-explorer" },
  { kind: "permission", key: "can_see_dynamic_dashboards", route: "/apps" },
  { kind: "apps" },
  { kind: "permission", key: "can_see_compute_page", route: "/compute" },
  { kind: "permission", key: "can_see_settings", route: "/settings" },
];

// In dev/Snowflake/Databricks modes auth is bypassed and permissions are never fetched.
// Treat as fully loaded with full access so section nav items behave normally.
const DEV_MODE = PROMETHEUX_CONFIG.SKIP_AUTH;

// Derive a URL-safe route id from the permission key.
// "can_see_sella_wealth_app" → "sella-wealth"
function deriveAppId(permissionKey: string): string {
  return permissionKey
    .replace(/^can_see_/, "")
    .replace(/_app$/, "")
    .replace(/_/g, "-");
}

// Resolve one `can_see_<id>_app` permission to a visible app entry.
//
// An app is LOCAL if a build-time component is bundled for its id (the in-tree dashboards);
// otherwise it is a FEDERATED REMOTE whose remoteEntry URL is derived from the single
// configured apps base URL + the stable per-app path. This is self-maintaining: deleting an
// app from the frontend (or adding a brand-new federated app) flips it to the remote path
// automatically, with no per-app URL or marker stored anywhere.
function resolveAppEntry(permission: Permission): DashboardEntry[] {
  const appId = deriveAppId(permission.key);
  const meta = permission.value.metadata;

  const componentName = meta?.component ?? DASHBOARD_ID_TO_COMPONENT_NAME[appId];
  const component = componentName ? COMPONENT_MAP[componentName] : undefined;
  if (component) {
    const appName = meta?.app_name ?? DASHBOARD_CONFIG_MAP[appId]?.name ?? appId;
    return [{ id: appId, name: appName, component, componentName }];
  }

  const remoteUrl = remoteEntryUrlFor(appId);
  if (!remoteUrl) return [];
  return [{ id: appId, name: meta?.app_name ?? appId, description: meta?.description, remoteUrl }];
}

function computeVisibleApps(permissions: Permission[]): DashboardEntry[] {
  return permissions
    .filter((p) => p.key.endsWith("_app") && p.value.enabled)
    .flatMap(resolveAppEntry);
}

function computeNavigableRoutes(
  permissions: Permission[],
  visibleApps: DashboardEntry[],
): string[] {
  return SECTION_ROUTES.flatMap((entry) => {
    if (entry.kind === "apps") {
      return visibleApps.map((app) => `/apps/${app.id}`);
    }
    const enabled = permissions.some((p) => p.key === entry.key && p.value.enabled);
    return enabled ? [entry.route] : [];
  });
}

export const usePermissionsStore = create<PermissionsStore>((set, get) => ({
  permissions: [],
  loaded: DEV_MODE,
  // Apps are discovered purely from permissions (see computeVisibleApps), so there is nothing
  // to seed before they load. In SKIP_AUTH dev no permissions are fetched, so no apps show.
  visibleApps: [],
  defaultRoute: null,
  singlePageRoute: null,
  hasAnyAccess: DEV_MODE,

  setPermissions: (permissions) => {
    const visibleApps = computeVisibleApps(permissions);
    const routes = computeNavigableRoutes(permissions, visibleApps);

    // When exactly one route is accessible, the sidebar is hidden and the user lands
    // directly on that page — even if it's a specific app or sub-item.
    // When multiple routes are accessible, group items (Apps) should land on their
    // group page (/apps) rather than a specific sub-item so the user can navigate.
    const toGroupRoute = (route: string): string => {
      if (route.startsWith("/apps/")) return "/apps";
      return route;
    };

    const firstRoute = routes[0] ?? null;
    const isSingleRoute = routes.length === 1;

    set({
      permissions,
      loaded: true,
      visibleApps,
      defaultRoute: firstRoute && !isSingleRoute ? toGroupRoute(firstRoute) : firstRoute,
      singlePageRoute: isSingleRoute ? firstRoute : null,
      hasAnyAccess: routes.length > 0,
    });
  },

  clearPermissions: () =>
    set({
      permissions: [],
      loaded: DEV_MODE,
      visibleApps: [],
      defaultRoute: null,
      singlePageRoute: null,
      hasAnyAccess: DEV_MODE,
    }),

  canSee: (key) => {
    const { permissions, loaded } = get();
    if (!loaded) return false;
    if (DEV_MODE) return true;
    return permissions.some((p) => p.key === key && p.value.enabled);
  },

  canEdit: (key) => {
    const { permissions, loaded } = get();
    if (!loaded) return false;
    if (DEV_MODE) return true;
    return permissions.some((p) => p.key === key && p.value.enabled);
  },

  canSeeOrUnknown: (key) => {
    const { permissions, loaded } = get();
    if (!loaded) return false;
    if (DEV_MODE) return true;
    const entry = permissions.find((p) => p.key === key);
    if (!entry) return true;
    return entry.value.enabled;
  },
}));
