import { Crosshair, Play, X } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import {
  type GraphAnalyticsResult,
  graphAnalyticsClient,
  type RunAnalyticsRequest,
} from "../../api/GraphAnalyticsClient";
import type { PickMode } from "./graphWidget.utils";

interface GraphAnalyticsPanelProps {
  ontologyId: string;
  predicateName: string;
  xCol: number;
  yCol: number;
  onResult: (result: GraphAnalyticsResult | null) => void;
  pathSource: string;
  pathTarget: string;
  pickMode: PickMode;
  onPathSourceChange: (value: string) => void;
  onPathTargetChange: (value: string) => void;
  onPickModeChange: (mode: PickMode) => void;
}

type FnKey = "pagerank" | "dc" | "bc" | "cc" | "paths";

const FN_OPTIONS: Array<{ value: FnKey; label: string }> = [
  { value: "pagerank", label: "PageRank" },
  { value: "dc", label: "Degree Centrality" },
  { value: "bc", label: "Betweenness Centrality" },
  { value: "cc", label: "Connected Components" },
  { value: "paths", label: "All Paths" },
];

interface FnParams {
  damping: string;
  direction: string;
  sample: string;
  maxDepth: string;
}

const DEFAULT_PARAMS: FnParams = {
  damping: "0.85",
  direction: "total",
  sample: "",
  maxDepth: "10",
};

const INPUT_CLS =
  "text-[11px] bg-background border border-border rounded px-1.5 py-0.5 text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring";

function buildFunctionParams(
  fn: FnKey,
  p: FnParams,
  pathSource: string,
  pathTarget: string,
): Record<string, unknown> {
  switch (fn) {
    case "pagerank":
      return { damping: parseFloat(p.damping) || 0.85 };
    case "dc":
      return { direction: p.direction };
    case "bc":
      return p.sample ? { sample: parseInt(p.sample) } : {};
    case "cc":
      return {};
    case "paths": {
      const params: Record<string, unknown> = { max_depth: parseInt(p.maxDepth) || 10 };
      if (pathSource) params.source = pathSource;
      if (pathTarget) params.target = pathTarget;
      return params;
    }
  }
}

export function GraphAnalyticsPanel({
  ontologyId,
  predicateName,
  xCol,
  yCol,
  onResult,
  pathSource,
  pathTarget,
  pickMode,
  onPathSourceChange,
  onPathTargetChange,
  onPickModeChange,
}: GraphAnalyticsPanelProps) {
  const [selectedFn, setSelectedFn] = useState<FnKey | "">("");
  const [isRunning, setIsRunning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [params, setParams] = useState<FnParams>(DEFAULT_PARAMS);

  const setParam = (key: keyof FnParams, value: string) =>
    setParams((prev) => ({ ...prev, [key]: value }));

  const handleFnChange = (fn: FnKey | "") => {
    setSelectedFn(fn);
    setError(null);
    if (fn !== "paths") onPickModeChange(null);
    if (!fn) onResult(null);
  };

  const togglePick = (slot: "source" | "target") => {
    onPickModeChange(pickMode === slot ? null : slot);
  };

  const handleRun = async () => {
    if (!selectedFn) return;
    setIsRunning(true);
    setError(null);
    try {
      const request: RunAnalyticsRequest = {
        column_roles: { source: xCol, target: yCol },
        function: selectedFn,
        function_params: buildFunctionParams(selectedFn, params, pathSource, pathTarget),
        project: { scope: "user" },
      };
      const result = await graphAnalyticsClient.runAnalytics(ontologyId, predicateName, request);
      onResult(result);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Analytics failed");
      onResult(null);
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <div className="flex flex-col gap-1.5 pb-2 border-b border-border mb-2">
      <div className="flex items-center gap-2 flex-wrap">
        <span className="text-[11px] font-medium text-muted-foreground">Analytics</span>

        <select
          value={selectedFn}
          onChange={(e) => handleFnChange(e.target.value as FnKey | "")}
          className={INPUT_CLS}
        >
          <option value="">None</option>
          {FN_OPTIONS.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>

        {selectedFn === "pagerank" && (
          <label className="flex items-center gap-1 text-[11px] text-muted-foreground">
            damping
            <input
              type="number"
              min="0"
              max="1"
              step="0.05"
              value={params.damping}
              onChange={(e) => setParam("damping", e.target.value)}
              className={`${INPUT_CLS} w-14`}
            />
          </label>
        )}

        {selectedFn === "dc" && (
          <select
            value={params.direction}
            onChange={(e) => setParam("direction", e.target.value)}
            className={INPUT_CLS}
          >
            <option value="total">Total</option>
            <option value="in">In-degree</option>
            <option value="out">Out-degree</option>
          </select>
        )}

        {selectedFn === "bc" && (
          <label className="flex items-center gap-1 text-[11px] text-muted-foreground">
            sample
            <input
              type="number"
              min="1"
              max="10000"
              placeholder="all"
              value={params.sample}
              onChange={(e) => setParam("sample", e.target.value)}
              className={`${INPUT_CLS} w-16`}
            />
          </label>
        )}

        {selectedFn === "paths" && (
          <>
            <NodePicker
              slot="source"
              value={pathSource}
              isPicking={pickMode === "source"}
              onTypedChange={onPathSourceChange}
              onTogglePick={() => togglePick("source")}
              onClear={() => onPathSourceChange("")}
            />
            <NodePicker
              slot="target"
              value={pathTarget}
              isPicking={pickMode === "target"}
              onTypedChange={onPathTargetChange}
              onTogglePick={() => togglePick("target")}
              onClear={() => onPathTargetChange("")}
            />
            <label className="flex items-center gap-1 text-[11px] text-muted-foreground">
              depth
              <input
                type="number"
                min="1"
                max="50"
                value={params.maxDepth}
                onChange={(e) => setParam("maxDepth", e.target.value)}
                className={`${INPUT_CLS} w-10`}
              />
            </label>
          </>
        )}

        {selectedFn && (
          <Button
            type="button"
            size="sm"
            onClick={handleRun}
            disabled={isRunning}
            className="h-5 px-2 text-[11px]"
          >
            <Play className="h-2.5 w-2.5 mr-1" />
            {isRunning ? "Running…" : "Run"}
          </Button>
        )}
      </div>

      {pickMode && selectedFn === "paths" && (
        <p className="text-[11px] text-muted-foreground">
          Click a node on the chart to set the {pickMode}.
        </p>
      )}
      {error && <p className="text-[11px] text-destructive">{error}</p>}
    </div>
  );
}

interface NodePickerProps {
  slot: "source" | "target";
  value: string;
  isPicking: boolean;
  onTypedChange: (value: string) => void;
  onTogglePick: () => void;
  onClear: () => void;
}

function resolvePickerRingClass(isPicking: boolean, slot: "source" | "target"): string {
  if (!isPicking) return "";
  if (slot === "source") return "ring-1 ring-emerald-500";
  return "ring-1 ring-red-500";
}

function NodePicker({
  slot,
  value,
  isPicking,
  onTypedChange,
  onTogglePick,
  onClear,
}: NodePickerProps) {
  const ringClass = resolvePickerRingClass(isPicking, slot);
  return (
    <div className={`flex items-center gap-0.5 rounded ${ringClass}`}>
      <input
        type="text"
        placeholder={`${slot} node`}
        value={value}
        onChange={(e) => onTypedChange(e.target.value)}
        className={`${INPUT_CLS} w-24`}
      />
      <button
        type="button"
        onClick={onTogglePick}
        title={`Pick ${slot} node from chart`}
        className={`h-5 w-5 flex items-center justify-center rounded border border-border text-foreground hover:bg-accent ${
          isPicking ? "bg-accent" : "bg-background"
        }`}
      >
        <Crosshair className="h-3 w-3" />
      </button>
      {value && (
        <button
          type="button"
          onClick={onClear}
          title={`Clear ${slot}`}
          className="h-5 w-5 flex items-center justify-center rounded border border-border bg-background text-muted-foreground hover:bg-accent"
        >
          <X className="h-3 w-3" />
        </button>
      )}
    </div>
  );
}
