import {
  FilePlus,
  FolderPlus,
  ListChevronsDownUp,
  ListChevronsUpDown,
  RefreshCw,
  Save,
  Search,
} from "lucide-react";
import type React from "react";
import { ExplorerHeaderIconButton } from "@/features/concept-editor/components/ExplorerHeaderIconButton";
import { cn } from "@/shared/lib/utils";

interface ExplorerTreeHeaderProps {
  hasGroups: boolean;
  /** Search controls — present only when search is supported by the parent. */
  supportsSearch: boolean;
  isSearchOpen: boolean;
  isSearchActive: boolean;
  onToggleSearch: () => void;
  /**
   * Single toggle that flips between "expand all" and "collapse all"
   * depending on whether any groups are currently collapsed.
   * Hidden when there are no groups.
   */
  allGroupsExpanded: boolean;
  onToggleAllGroups?: () => void;
  /** Add controls — present only with edit permission. */
  onAddCell?: () => void;
  onAddGroup?: () => void;
  /** Editor actions — present only when the parent wires them up. */
  onRefresh?: () => void;
  isRefreshing?: boolean;
  onSaveAll?: () => void;
  isSavingAll?: boolean;
  hasUnsavedChanges?: boolean;
}

/** Top row of the Explorer tree: title + action buttons (search, expand/collapse toggle, new cell, new group). */
export const ExplorerTreeHeader: React.FC<ExplorerTreeHeaderProps> = ({
  hasGroups,
  supportsSearch,
  isSearchOpen,
  isSearchActive,
  onToggleSearch,
  allGroupsExpanded,
  onToggleAllGroups,
  onAddCell,
  onAddGroup,
  onRefresh,
  isRefreshing,
  onSaveAll,
  isSavingAll,
  hasUnsavedChanges,
}) => (
  <div className="flex items-center justify-between gap-2 pl-3 pr-1.5 py-1 border-b border-border bg-muted h-9">
    <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
      Explorer
    </span>
    <div className="flex items-center gap-0.5">
      {onRefresh && (
        <ExplorerHeaderIconButton
          icon={<RefreshCw className={cn("h-3.5 w-3.5", isRefreshing && "animate-spin")} />}
          label="Refresh concepts"
          onClick={onRefresh}
        />
      )}
      {onSaveAll && (
        <ExplorerHeaderIconButton
          icon={<Save className={cn("h-3.5 w-3.5", isSavingAll && "animate-pulse")} />}
          label="Save all"
          active={hasUnsavedChanges}
          onClick={onSaveAll}
        />
      )}
      {supportsSearch && (
        <ExplorerHeaderIconButton
          icon={<Search className="h-3.5 w-3.5" />}
          label={isSearchOpen ? "Close search" : "Search cells"}
          active={isSearchOpen || isSearchActive}
          onClick={onToggleSearch}
        />
      )}
      {hasGroups && onToggleAllGroups && (
        <ExplorerHeaderIconButton
          icon={
            allGroupsExpanded ? (
              <ListChevronsDownUp className="h-3.5 w-3.5" />
            ) : (
              <ListChevronsUpDown className="h-3.5 w-3.5" />
            )
          }
          label={allGroupsExpanded ? "Collapse all groups" : "Expand all groups"}
          onClick={onToggleAllGroups}
        />
      )}
      {onAddCell && (
        <ExplorerHeaderIconButton
          icon={<FilePlus className="h-3.5 w-3.5" />}
          label="New cell"
          onClick={onAddCell}
        />
      )}
      {onAddGroup && (
        <ExplorerHeaderIconButton
          icon={<FolderPlus className="h-3.5 w-3.5" />}
          label="New group"
          onClick={onAddGroup}
        />
      )}
    </div>
  </div>
);
