import { ChevronDown, ChevronRight, FileText, Sparkles } from "lucide-react";
import { useState } from "react";

import { cn } from "@/shared/lib/utils";

import type { ContextNote, ContextShelf } from "../../types";
import { shelfOf } from "../../types";
import type { DocumentGroup, FolderNode, NotesSelection } from "../notesModel";
import { AUTO_GENERATED_FOLDER_LABEL, noteDisplayTitle, notesInFolder } from "../notesModel";

/** Reserved key for the synthetic auto-generated folder. The leading control
 *  character can never collide with a normalized (real) folder_path. */
const AUTO_GENERATED_FOLDER_KEY = "\u0000auto-generated";

const SHELF_DOT_CLASSES: Record<ContextShelf, string> = {
  rules: "bg-amber-500 dark:bg-amber-400",
  knowledge: "bg-blue-500 dark:bg-blue-400",
  documents: "bg-emerald-500 dark:bg-emerald-400",
};

/** Obsidian-style indent: each nested level is a ul with a guide line. */
const NESTED_LIST_CLASSES = "ml-3 border-l border-border/70 pl-1.5";

interface FolderTreeViewProps {
  folders: FolderNode[];
  /** Non-document notes of the vault (already shelf-filtered). */
  standaloneNotes: ContextNote[];
  /** Auto-generated notes, collected under a collapsed virtual folder. */
  autoGeneratedNotes?: ContextNote[];
  /** Document groups — always listed at the vault root. */
  documents: DocumentGroup[];
  selection: NotesSelection;
  onSelectNote: (note: ContextNote, folderPath: string) => void;
  onSelectDocument: (document: DocumentGroup) => void;
  /** Folder title clicked — show the folder's notes as cards. */
  onSelectFolder: (folderPath: string) => void;
}

interface NoteRowProps {
  note: ContextNote;
  isSelected: boolean;
  onSelect: () => void;
}

function NoteRow({ note, isSelected, onSelect }: NoteRowProps) {
  return (
    <button
      type="button"
      onClick={onSelect}
      className={cn(
        "flex w-full items-center gap-2 rounded-md px-2 py-1 text-left text-sm transition-colors",
        isSelected ? "bg-accent text-accent-foreground" : "text-foreground/90 hover:bg-accent/50",
      )}
    >
      <span className="min-w-0 flex-1 truncate">{noteDisplayTitle(note)}</span>
      <span className={cn("h-2 w-2 shrink-0 rounded-full", SHELF_DOT_CLASSES[shelfOf(note)])} />
    </button>
  );
}

interface DocumentRowProps {
  document: DocumentGroup;
  isSelected: boolean;
  onSelect: () => void;
}

function DocumentRow({ document, isSelected, onSelect }: DocumentRowProps) {
  return (
    <button
      type="button"
      onClick={onSelect}
      className={cn(
        "flex w-full items-center gap-2 rounded-md px-2 py-1 text-left text-sm transition-colors",
        isSelected ? "bg-accent text-accent-foreground" : "text-foreground/90 hover:bg-accent/50",
      )}
    >
      <FileText className="h-4 w-4 shrink-0 text-muted-foreground" />
      <span className="min-w-0 flex-1 truncate">{document.filename}</span>
      <span className={cn("h-2 w-2 shrink-0 rounded-full", SHELF_DOT_CLASSES.documents)} />
    </button>
  );
}

export function FolderTreeView({
  folders,
  standaloneNotes,
  autoGeneratedNotes = [],
  documents,
  selection,
  onSelectNote,
  onSelectDocument,
  onSelectFolder,
}: FolderTreeViewProps) {
  const [expandedFolders, setExpandedFolders] = useState<Set<string>>(new Set());

  const toggleFolder = (path: string) => {
    setExpandedFolders((prev) => {
      const next = new Set(prev);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  };

  const isNoteSelected = (note: ContextNote) =>
    selection.type === "note" && selection.noteId === note.id;

  const renderFolder = (folder: FolderNode): React.ReactNode => {
    const isExpanded = expandedFolders.has(folder.path);
    const folderNotes = notesInFolder(standaloneNotes, folder.path);
    const ChevronIcon = isExpanded ? ChevronDown : ChevronRight;
    const isFolderSelected =
      selection.type === "collection" && selection.folderPath === folder.path;

    return (
      <li key={folder.path}>
        <div
          className={cn(
            "flex w-full items-center rounded-md transition-colors",
            isFolderSelected ? "bg-accent text-accent-foreground" : "hover:bg-accent/50",
          )}
        >
          <button
            type="button"
            onClick={() => toggleFolder(folder.path)}
            className="shrink-0 rounded-md p-1 text-muted-foreground hover:text-foreground"
            aria-label={isExpanded ? "Collapse folder" : "Expand folder"}
          >
            <ChevronIcon className="h-4 w-4" />
          </button>
          <button
            type="button"
            onClick={() => onSelectFolder(folder.path)}
            className="min-w-0 flex-1 truncate py-1 pr-1.5 text-left text-sm font-medium text-foreground"
          >
            {folder.name}
          </button>
        </div>
        {isExpanded && (
          <ul className={NESTED_LIST_CLASSES}>
            {folder.children.map((child) => renderFolder(child))}
            {folderNotes.map((note) => (
              <li key={note.id}>
                <NoteRow
                  note={note}
                  isSelected={isNoteSelected(note)}
                  onSelect={() => onSelectNote(note, folder.path)}
                />
              </li>
            ))}
          </ul>
        )}
      </li>
    );
  };

  const rootNotes = notesInFolder(standaloneNotes, "");
  const isAutoExpanded = expandedFolders.has(AUTO_GENERATED_FOLDER_KEY);
  const AutoChevron = isAutoExpanded ? ChevronDown : ChevronRight;

  const renderAutoGeneratedFolder = (): React.ReactNode => (
    <li key={AUTO_GENERATED_FOLDER_KEY}>
      <div className="flex w-full items-center rounded-md transition-colors hover:bg-accent/50">
        <button
          type="button"
          onClick={() => toggleFolder(AUTO_GENERATED_FOLDER_KEY)}
          className="shrink-0 rounded-md p-1 text-muted-foreground hover:text-foreground"
          aria-label={isAutoExpanded ? "Collapse auto-generated" : "Expand auto-generated"}
        >
          <AutoChevron className="h-4 w-4" />
        </button>
        <button
          type="button"
          onClick={() => toggleFolder(AUTO_GENERATED_FOLDER_KEY)}
          className="flex min-w-0 flex-1 items-center gap-1.5 py-1 pr-1.5 text-left text-sm font-medium text-foreground"
        >
          <Sparkles className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
          <span className="min-w-0 flex-1 truncate">{AUTO_GENERATED_FOLDER_LABEL}</span>
          <span className="shrink-0 text-xs font-normal text-muted-foreground">
            {autoGeneratedNotes.length}
          </span>
        </button>
      </div>
      {isAutoExpanded && (
        <ul className={NESTED_LIST_CLASSES}>
          {autoGeneratedNotes.map((note) => (
            <li key={note.id}>
              <NoteRow
                note={note}
                isSelected={isNoteSelected(note)}
                onSelect={() => onSelectNote(note, "")}
              />
            </li>
          ))}
        </ul>
      )}
    </li>
  );

  return (
    <ul className="space-y-px">
      {folders.map((folder) => renderFolder(folder))}
      {autoGeneratedNotes.length > 0 && renderAutoGeneratedFolder()}
      {rootNotes.map((note) => (
        <li key={note.id}>
          <NoteRow
            note={note}
            isSelected={isNoteSelected(note)}
            onSelect={() => onSelectNote(note, "")}
          />
        </li>
      ))}
      {documents.map((document) => (
        <li key={document.documentId}>
          <DocumentRow
            document={document}
            isSelected={
              selection.type === "document" && selection.documentId === document.documentId
            }
            onSelect={() => onSelectDocument(document)}
          />
        </li>
      ))}
    </ul>
  );
}
