import { FileText, Network } from "lucide-react";
import type { ElementType } from "react";
import { cn } from "@/shared/lib/utils";

export type DocumentSubTab = "overview" | "schema";

interface DocumentSubTabDef {
  id: DocumentSubTab;
  label: string;
  icon: ElementType;
}

const DOCUMENT_SUB_TABS: DocumentSubTabDef[] = [
  { id: "overview", label: "Overview", icon: FileText },
  { id: "schema", label: "Schema", icon: Network },
];

interface DocumentTabBarProps {
  activeTab: DocumentSubTab;
  onTabChange: (tab: DocumentSubTab) => void;
}

export function DocumentTabBar({ activeTab, onTabChange }: DocumentTabBarProps) {
  return (
    <div className="flex shrink-0 items-center gap-0.5 border-b border-border bg-card px-4 py-2">
      {DOCUMENT_SUB_TABS.map(({ id, label, icon: Icon }) => {
        const isActive = activeTab === id;
        return (
          <button
            key={id}
            type="button"
            onClick={() => onTabChange(id)}
            className={cn(
              "flex items-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition-colors",
              isActive
                ? "bg-primary/10 text-primary"
                : "text-muted-foreground hover:bg-accent hover:text-accent-foreground",
            )}
          >
            <Icon className="h-3.5 w-3.5" />
            {label}
          </button>
        );
      })}
    </div>
  );
}
