import { useEffect } from "react";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

// Constants for localStorage keys
const LOCAL_STORAGE_AUTH_TOKEN_KEY = "prometheux_auth_token";
const LOCAL_STORAGE_SERVICE_URL_KEY = "prometheux_service_url_override";

export const useApiToken = () => {
  useEffect(() => {
    // Load auth token override
    const savedToken = localStorage.getItem(LOCAL_STORAGE_AUTH_TOKEN_KEY);

    if (savedToken) {
      PROMETHEUX_CONFIG.AUTH_TOKEN = savedToken;
      HttpService.setAuthToken(savedToken);
    } else if (PROMETHEUX_CONFIG.AUTH_TOKEN) {
      HttpService.setAuthToken(PROMETHEUX_CONFIG.AUTH_TOKEN);
    }

    // Load service URL override
    const savedUrl = localStorage.getItem(LOCAL_STORAGE_SERVICE_URL_KEY);

    if (savedUrl) {
      PROMETHEUX_CONFIG.BASE_URL = savedUrl;
    }
  }, []);
};
