import { useCallback, useState } from "react";
import { toast } from "sonner";
import { clearAuthToken, setAuthToken } from "@/shared/auth/authToken";
import { useAuthToken } from "@/shared/auth/useAuthToken";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import SettingsSection from "./SettingsSection";

const LOCAL_STORAGE_AUTH_TOKEN_KEY = "prometheux_auth_token";

const AuthSettings = () => {
  const activeToken = useAuthToken();
  // What the user has typed, if anything. Until they do, the field shows the
  // token requests are actually carrying — which arrives after sign-in resolves,
  // so reading it once on mount showed an empty box to a signed-in user.
  const [draftToken, setDraftToken] = useState<string | null>(() =>
    localStorage.getItem(LOCAL_STORAGE_AUTH_TOKEN_KEY),
  );
  const [isSaving, setIsSaving] = useState(false);

  const authToken = draftToken ?? activeToken ?? "";

  const handleAuthTokenSave = useCallback(() => {
    setIsSaving(true);

    try {
      setAuthToken(authToken);

      // Save to localStorage for persistence
      localStorage.setItem(LOCAL_STORAGE_AUTH_TOKEN_KEY, authToken);
      toast.success("Authentication token updated successfully. Reloading page...");

      // Reload the page after a short delay to apply changes
      setTimeout(() => {
        window.location.reload();
      }, 1000);
    } catch (error) {
      console.error("Error saving auth token:", error);
      toast.error("Failed to save authentication token");
      setIsSaving(false);
    }
  }, [authToken]);

  const handleTokenReset = useCallback(() => {
    setIsSaving(true);

    try {
      setDraftToken(null);
      clearAuthToken();

      // Clear from localStorage as well
      localStorage.removeItem(LOCAL_STORAGE_AUTH_TOKEN_KEY);
      toast.success("Authentication token reset successfully. Reloading page...");

      // Reload the page after a short delay to apply changes
      setTimeout(() => {
        window.location.reload();
      }, 1000);
    } catch (error) {
      console.error("Error resetting auth token:", error);
      toast.error("Failed to reset authentication token");
      setIsSaving(false);
    }
  }, []);

  return (
    <SettingsSection
      title="Authentication Token"
      description="Configure the authentication token for the Prometheux service"
    >
      <div className="flex gap-4">
        <Input
          id="auth-token"
          value={authToken}
          onChange={(e) => setDraftToken(e.target.value)}
          type="password"
          placeholder="Enter your API key from the platform"
          className="flex-1"
          // Allow editing even in development mode
          disabled={isSaving}
        />
        <Button onClick={handleAuthTokenSave} disabled={isSaving} variant="default">
          Save
        </Button>
        <Button variant="outline" onClick={handleTokenReset} disabled={isSaving}>
          Reset
        </Button>
      </div>
      {!authToken && (
        <p className="text-sm text-destructive mt-2">
          Authentication token is required for API requests. Please set it above.
        </p>
      )}
    </SettingsSection>
  );
};

export default AuthSettings;
