import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import type { CreateTokenInput, IssueTokenData, TokenSummary } from "./apiKeys.types";
import { AuthApiError, AuthApiUnauthorizedError, authApiClient } from "./authApiClient";

export const API_KEYS_QUERY_KEY = ["api-keys", "jarvispy"] as const;

export interface UseApiKeysReturn {
  tokens: TokenSummary[];
  isLoading: boolean;
  error: Error | null;
  isCreating: boolean;
  isRevoking: boolean;
  isRevokingAll: boolean;
  createToken: (input: CreateTokenInput) => Promise<IssueTokenData>;
  revokeToken: (jti: string) => Promise<void>;
  revokeAllTokens: () => Promise<void>;
}

function errorMessage(error: unknown, fallback: string): string {
  return error instanceof Error ? error.message : fallback;
}

export function useApiKeys(): UseApiKeysReturn {
  const queryClient = useQueryClient();
  const { signOut } = useAuth();

  const handleUnauthorized = useCallback(
    (error: unknown): boolean => {
      if (!(error instanceof AuthApiUnauthorizedError)) return false;
      toast.error("Your session has expired. Please sign in again.");
      void signOut();
      return true;
    },
    [signOut],
  );

  const tokensQuery = useQuery<TokenSummary[], Error>({
    queryKey: API_KEYS_QUERY_KEY,
    queryFn: () => authApiClient.listTokens(),
    retry: (_failureCount, error) => !(error instanceof AuthApiUnauthorizedError),
  });

  useEffect(() => {
    if (tokensQuery.error) handleUnauthorized(tokensQuery.error);
  }, [tokensQuery.error, handleUnauthorized]);

  const createMutation = useMutation<IssueTokenData, Error, CreateTokenInput>({
    mutationFn: (input) =>
      authApiClient.issueToken({ name: input.name, expiresInMinutes: input.expiresInMinutes }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: API_KEYS_QUERY_KEY });
    },
    onError: (error) => {
      if (handleUnauthorized(error)) return;
      toast.error(errorMessage(error, "Failed to create API key"));
    },
  });

  const revokeMutation = useMutation({
    mutationFn: (jti: string) => authApiClient.revokeToken(jti),
    onMutate: async (jti) => {
      await queryClient.cancelQueries({ queryKey: API_KEYS_QUERY_KEY });
      const previous = queryClient.getQueryData<TokenSummary[]>(API_KEYS_QUERY_KEY);
      queryClient.setQueryData<TokenSummary[]>(
        API_KEYS_QUERY_KEY,
        (old) => old?.filter((token) => token.jti !== jti) ?? [],
      );
      return { previous };
    },
    onError: (error, _jti, context) => {
      if (context?.previous) {
        queryClient.setQueryData(API_KEYS_QUERY_KEY, context.previous);
      }
      if (handleUnauthorized(error)) return;
      if (error instanceof AuthApiError && error.status === 403) {
        toast.error("This key no longer belongs to you — refreshing list.");
        queryClient.invalidateQueries({ queryKey: API_KEYS_QUERY_KEY });
        return;
      }
      if (error instanceof AuthApiError && error.status === 409) {
        toast.error("This key is protected and cannot be revoked.");
        return;
      }
      toast.error(errorMessage(error, "Failed to revoke API key"));
    },
    onSuccess: (result) => {
      if (result.status === "not_found") {
        toast.info("Key was already revoked.");
      } else {
        toast.success("API key revoked.");
      }
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: API_KEYS_QUERY_KEY });
    },
  });

  const revokeAllMutation = useMutation({
    mutationFn: () => authApiClient.revokeAll(),
    onError: (error) => {
      if (handleUnauthorized(error)) return;
      toast.error(errorMessage(error, "Failed to revoke all keys"));
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: API_KEYS_QUERY_KEY });
      toast.success("All API keys revoked.");
    },
  });

  const createToken = useCallback(
    (input: CreateTokenInput) => createMutation.mutateAsync(input),
    [createMutation],
  );

  const revokeToken = useCallback(
    async (jti: string) => {
      await revokeMutation.mutateAsync(jti);
    },
    [revokeMutation],
  );

  const revokeAllTokens = useCallback(async () => {
    await revokeAllMutation.mutateAsync();
  }, [revokeAllMutation]);

  return {
    tokens: tokensQuery.data ?? [],
    isLoading: tokensQuery.isLoading,
    error:
      tokensQuery.error instanceof AuthApiUnauthorizedError ? null : (tokensQuery.error ?? null),
    isCreating: createMutation.isPending,
    isRevoking: revokeMutation.isPending,
    isRevokingAll: revokeAllMutation.isPending,
    createToken,
    revokeToken,
    revokeAllTokens,
  };
}
