import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/shared/integrations/supabase/client";

const SIGNED_URL_TTL_SECONDS = 60 * 60;

function isAbsoluteUrl(value: string): boolean {
  return /^(https?:|data:|blob:)/.test(value);
}

// Returns the storage key inside the avatars bucket if `value` references it,
// otherwise null. External URLs (e.g. OAuth provider CDNs) return null and
// should be rendered as-is.
export function extractStoragePath(value: string): string | null {
  if (!isAbsoluteUrl(value)) return value;
  if (value.includes("/avatars/")) {
    return value.split("/avatars/").pop() ?? null;
  }
  return null;
}

// Resolves a stored avatar reference to a renderable URL.
// - Storage paths in the avatars bucket → short-lived signed URL (bucket is private)
// - External absolute URLs (OAuth provider pictures, data:, blob:) → passed through
export function useAvatarSrc(value: string | null | undefined): string | undefined {
  const path = value ? extractStoragePath(value) : null;

  const { data } = useQuery({
    queryKey: ["avatar-signed-url", path],
    queryFn: async () => {
      if (!path) return undefined;
      const { data: signed, error } = await supabase.storage
        .from("avatars")
        .createSignedUrl(path, SIGNED_URL_TTL_SECONDS);
      if (error) throw error;
      return signed.signedUrl;
    },
    enabled: !!path,
    // Refresh slightly before the signed URL expires
    staleTime: SIGNED_URL_TTL_SECONDS * 1000 * 0.9,
  });

  if (!value) return undefined;
  if (path === null) return value;
  return data;
}
