import type React from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import * as Icons from "simple-icons";
import { PaidComputeRequiredDialog } from "@/features/billing/components/PaidComputeRequiredDialog";
import { usePaidComputeEligibility } from "@/features/billing/hooks/usePaidComputeEligibility";
import { isPaymentRequiredError } from "@/features/billing/utils/billing.utils";
import { DatabricksConfigService } from "@/features/compute/api/databricksService";
import { MachineClient } from "@/features/compute/api/MachineClient";
import { MachineUsageDialog } from "@/features/compute/components/MachineUsageDialog";
import { PoolsTabContent } from "@/features/compute/components/PoolsTabContent";
import { useComputeMachines } from "@/features/compute/hooks/useComputeMachines";
import { useMachineStatus } from "@/features/compute/hooks/useMachineStatus";
import { useMachineStatusStream } from "@/features/compute/hooks/useMachineStatusStream";
import { ComputeSwitchOverlay } from "@/features/compute/snowflake/ComputeSwitchOverlay";
import { GrantInstructionsDialog } from "@/features/compute/snowflake/GrantInstructionsDialog";
import { SnowflakePoolsTabContent } from "@/features/compute/snowflake/SnowflakePoolsTabContent";
import { useSnowflakeCompute } from "@/features/compute/snowflake/useSnowflakeCompute";
import { SimpleIcon } from "@/features/compute/utils";
import DatabricksSettings from "@/features/settings/components/DatabricksSettings";
import { Badge } from "@/shared/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/shared/components/ui/card";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

export type ComputeActiveTab = "pools" | "databricks";

interface ComputeTabProps {
  onRefreshReady?: (fn: () => Promise<void>) => void;
  activeTab: ComputeActiveTab;
}

const ComputeTab: React.FC<ComputeTabProps> = ({ onRefreshReady, activeTab }) => {
  const [databricksConfig, setDatabricksConfig] = useState(() =>
    DatabricksConfigService.getConfig(),
  );
  const [switchTarget, setSwitchTarget] = useState<string>("");
  const [paidComputeDialogOpen, setPaidComputeDialogOpen] = useState(false);

  const { isEligible: isPaidComputeEligible } = usePaidComputeEligibility();

  const isSnowflake = PROMETHEUX_CONFIG.SNOWFLAKE_MODE;

  const {
    machines,
    userMachines,
    setUserMachines,
    disabledUserMachines,
    loadingMachines,
    machinesError,
    fetchAllMachines,
    handleMachineRequest,
    isRequesting,
    loadCount,
  } = useComputeMachines();

  const {
    checkingAvailability,
    availabilityResults,
    setAvailabilityResults,
    refreshingMachines,
    usageDialogOpen,
    setUsageDialogOpen,
    selectedUsageMachine,
    usageData,
    loadingUsage,
    checkMachineStatus,
    fetchUsageData,
    handleRefreshMachines,
  } = useMachineStatus(userMachines, setUserMachines, loadCount);

  const { startStream: startStatusStream } = useMachineStatusStream(
    setAvailabilityResults,
    setUserMachines,
    checkMachineStatus,
  );

  const snowflake = useSnowflakeCompute();

  const clientRef = useRef(new MachineClient());

  const handleToggleActive = async (
    userMachineId: string,
    machineId: string,
    currentIsActive: boolean,
    autoterminationMinutes?: number,
  ) => {
    const newIsActive = !currentIsActive;
    const prevAutoTerm = userMachines.find(
      (um) => um.id === userMachineId,
    )?.autotermination_minutes;

    setUserMachines((prev) =>
      prev.map((um) =>
        um.id === userMachineId
          ? {
              ...um,
              is_active: newIsActive,
              autotermination_minutes: newIsActive
                ? (autoterminationMinutes ?? null)
                : um.autotermination_minutes,
            }
          : um,
      ),
    );

    setAvailabilityResults((prev) => ({
      ...prev,
      [machineId]: {
        status: "success",
        message: newIsActive ? "Machine starting..." : "Machine stopping...",
        machine_status: newIsActive ? "starting" : "stopping",
      },
    }));

    try {
      const response = await clientRef.current.toggleMachineActive(
        userMachineId,
        newIsActive,
        autoterminationMinutes,
      );
      if (response.data?.user_machine) {
        const confirmed = response.data.user_machine;
        setUserMachines((prev) =>
          prev.map((um) =>
            um.id === userMachineId
              ? { ...um, autotermination_minutes: confirmed.autotermination_minutes ?? null }
              : um,
          ),
        );
      }
      window.dispatchEvent(new CustomEvent("machineStateChanged"));
      // Subscribe to real-time status updates for the transition
      startStatusStream(userMachineId, machineId);
    } catch (error) {
      console.error("Error toggling machine:", error);
      setUserMachines((prev) =>
        prev.map((um) =>
          um.id === userMachineId
            ? { ...um, is_active: !newIsActive, autotermination_minutes: prevAutoTerm }
            : um,
        ),
      );
      // Backend refuses billable activation with HTTP 402 + the agreed
      // { code: "PAYMENT_REQUIRED", error: "billing_required" } body. We branch
      // on the stable `code` field — never on the message — and prompt the
      // user to set up billing instead of surfacing a generic error.
      if (isPaymentRequiredError(error)) {
        setPaidComputeDialogOpen(true);
      }
    }
  };

  const handlePaidComputeRequired = useCallback(() => {
    setPaidComputeDialogOpen(true);
  }, []);

  const handleRemoveMachine = async (userMachineId: string, machineName: string) => {
    if (
      window.confirm(
        `Remove ${machineName} from your active machines?\n\nYour usage history will be preserved. You can request this machine again later to restore access with all your data.`,
      )
    ) {
      try {
        await clientRef.current.deleteUserMachine(userMachineId);
        await fetchAllMachines();
      } catch (error) {
        console.error("Error removing machine:", error);
        alert("Failed to remove machine. Please try again.");
      }
    }
  };

  const handleSnowflakeSwitchCompute = async (poolName: string) => {
    setSwitchTarget(poolName);
    const success = await snowflake.handleSwitchCompute(poolName);
    if (!success) {
      setSwitchTarget("");
    }
    return success;
  };

  const refreshAll = useCallback(async () => {
    await fetchAllMachines();
    await handleRefreshMachines();
  }, [fetchAllMachines, handleRefreshMachines]);

  const onRefreshReadyRef = useRef(onRefreshReady);
  onRefreshReadyRef.current = onRefreshReady;

  useEffect(() => {
    onRefreshReadyRef.current?.(refreshAll);
  }, [refreshAll]);

  useEffect(() => {
    const handleStorageChange = () => {
      setDatabricksConfig(DatabricksConfigService.getConfig());
    };

    window.addEventListener("storage", handleStorageChange);
    window.addEventListener("databricksConfigChanged", handleStorageChange);

    return () => {
      window.removeEventListener("storage", handleStorageChange);
      window.removeEventListener("databricksConfigChanged", handleStorageChange);
    };
  }, []);

  return (
    <div className="p-4 @2xl:p-8 space-y-6">
      {PROMETHEUX_CONFIG.DATABRICKS_UI_MODE ? (
        <div className="space-y-6">
          <Card className="transition-all hover:shadow-md mb-6">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                <SimpleIcon iconData={Icons.siDatabricks} size={16} />
                Databricks Workspace
              </CardTitle>
              <div className="flex items-center gap-2">
                <Badge variant="outline">Connected</Badge>
              </div>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-muted-foreground">Workspace</span>
                  <span className="text-sm font-medium">
                    {databricksConfig.workspaceUrl || "Not configured"}
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-muted-foreground">Auth Mode</span>
                  <span className="text-sm font-medium capitalize">
                    {databricksConfig.authMode || "token"}
                  </span>
                </div>
                {databricksConfig.defaultCluster && (
                  <>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-muted-foreground">Cluster Name</span>
                      <span className="text-sm font-medium">
                        {databricksConfig.defaultCluster.cluster_name}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-muted-foreground">Cluster ID</span>
                      <span className="text-sm font-medium font-mono text-xs">
                        {databricksConfig.defaultCluster.cluster_id}
                      </span>
                    </div>
                  </>
                )}
              </div>
            </CardContent>
          </Card>
          <DatabricksSettings />
        </div>
      ) : (
        <div className="space-y-6">
          {/* Pools content */}
          {activeTab === "pools" && (
            <div className="space-y-6">
              {isSnowflake ? (
                <SnowflakePoolsTabContent
                  availableMachines={snowflake.availableMachines}
                  userMachines={snowflake.userMachines}
                  currentPool={snowflake.currentPool}
                  loading={snowflake.loading}
                  error={snowflake.error}
                  isRequesting={snowflake.isRequesting}
                  checkingStatus={snowflake.checkingStatus}
                  availabilityResults={snowflake.availabilityResults}
                  onRefresh={snowflake.fetchPools}
                  onUsePool={snowflake.handleUsePool}
                  onToggleActive={snowflake.handleToggleActive}
                  onRemovePool={snowflake.handleRemovePool}
                  onCheckStatus={snowflake.handleCheckStatus}
                  onSwitchCompute={handleSnowflakeSwitchCompute}
                />
              ) : (
                <PoolsTabContent
                  machines={machines}
                  userMachines={userMachines}
                  disabledUserMachines={disabledUserMachines}
                  loadingMachines={loadingMachines}
                  machinesError={machinesError}
                  availabilityResults={availabilityResults}
                  checkingAvailability={checkingAvailability}
                  isRequesting={isRequesting}
                  fetchAllMachines={fetchAllMachines}
                  handleMachineRequest={handleMachineRequest}
                  onToggleActive={handleToggleActive}
                  onRemoveMachine={handleRemoveMachine}
                  onCheckStatus={checkMachineStatus}
                  onFetchUsage={fetchUsageData}
                  isPaidComputeEligible={isPaidComputeEligible}
                  onPaidComputeRequired={handlePaidComputeRequired}
                />
              )}
            </div>
          )}

          {/* Databricks content */}
          {activeTab === "databricks" && (
            <div className="space-y-6">
              <Card className="transition-all hover:shadow-md mb-6">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium flex items-center gap-2">
                    <SimpleIcon iconData={Icons.siDatabricks} size={16} />
                    Databricks Workspace
                  </CardTitle>
                  <div className="flex items-center gap-2">
                    <Badge variant="outline">Connected</Badge>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-muted-foreground">Workspace</span>
                      <span className="text-sm font-medium">
                        {databricksConfig.workspaceUrl || "Not configured"}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-muted-foreground">Auth Mode</span>
                      <span className="text-sm font-medium capitalize">
                        {databricksConfig.authMode || "token"}
                      </span>
                    </div>
                    {databricksConfig.defaultCluster && (
                      <>
                        <div className="flex items-center justify-between">
                          <span className="text-sm text-muted-foreground">Cluster Name</span>
                          <span className="text-sm font-medium">
                            {databricksConfig.defaultCluster.cluster_name}
                          </span>
                        </div>
                        <div className="flex items-center justify-between">
                          <span className="text-sm text-muted-foreground">Cluster ID</span>
                          <span className="text-sm font-medium font-mono text-xs">
                            {databricksConfig.defaultCluster.cluster_id}
                          </span>
                        </div>
                      </>
                    )}
                  </div>
                </CardContent>
              </Card>
              <DatabricksSettings />
            </div>
          )}
        </div>
      )}

      <MachineUsageDialog
        open={usageDialogOpen}
        onOpenChange={setUsageDialogOpen}
        machineName={selectedUsageMachine?.machineName}
        loadingUsage={loadingUsage}
        usageData={usageData}
      />

      <PaidComputeRequiredDialog
        open={paidComputeDialogOpen}
        onOpenChange={setPaidComputeDialogOpen}
      />

      {isSnowflake && (
        <>
          <ComputeSwitchOverlay
            isVisible={snowflake.isSwitching}
            poolName={switchTarget}
            onDismiss={() => {
              snowflake.stopSwitching();
              setSwitchTarget("");
            }}
          />
          <GrantInstructionsDialog
            grantInfo={snowflake.grantInfo}
            onDismiss={snowflake.dismissGrantInfo}
          />
        </>
      )}
    </div>
  );
};

export default ComputeTab;
