import { supabase } from "@/shared/integrations/supabase/client";

export interface SlackNotificationData {
  type: "new_request" | "request_approved" | "request_denied";
  userName: string;
  userEmail: string;
  firstName?: string;
  lastName?: string;
  organization?: string;
  applicationName: string;
  applicationId: string;
  requestedAt?: string;
  processedBy?: string;
  additionalInfo?: string;
}

/**
 * Send Slack notification via Supabase Edge Function
 * @param data - Notification data to send
 * @returns Promise<boolean> - Success status
 */
export const sendSlackNotification = async (data: SlackNotificationData): Promise<boolean> => {
  try {
    const { data: response, error } = await supabase.functions.invoke("send-slack-notification", {
      body: data,
    });

    if (error) {
      return false;
    }

    return true;
  } catch (error) {
    console.error("❌ Failed to send Slack notification:", error);
    return false;
  }
};
