import { MoreHorizontal, Play, Plus, Search, X } from "lucide-react";
import { useState } from "react";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { useChatReservedWidth } from "@/features/code-assistant/hooks/useChatReservedWidth";
import ComputeIndicator from "@/features/compute/components/ComputeIndicator";
import { ReadOnlyGate } from "@/features/ontologies/sharing/components/ReadOnlyGate";
import { useOntologyWideReadOnly } from "@/features/ontologies/sharing/hooks/useOntologyWideReadOnly";
import { Button } from "@/shared/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";
import { NARROW_VIEWPORT_PX, useIsNarrowViewport } from "@/shared/hooks/ui/useIsNarrowViewport";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";

interface LineageSearchNode {
  id: string;
  label: string;
  nodeType?: string;
}

function filterSearchNodes(
  nodes: LineageSearchNode[],
  query: string,
  limit: number,
): LineageSearchNode[] {
  if (!query) return [];
  const lower = query.toLowerCase();
  return nodes.filter((node) => node.label.toLowerCase().includes(lower)).slice(0, limit);
}

interface RunButtonProps {
  isRunningConcept: boolean;
  onRunConcept: (() => void) | null;
  className?: string;
}

function RunButton({ isRunningConcept, onRunConcept, className }: RunButtonProps) {
  return (
    <Button
      size="sm"
      onClick={() => onRunConcept?.()}
      disabled={isRunningConcept}
      className={`gap-1.5 text-xs bg-green-600 hover:bg-green-700 text-white ${className ?? ""}`}
    >
      <Play className="h-3.5 w-3.5" />
      Run
    </Button>
  );
}

interface NewConceptButtonProps {
  onNewConcept: (() => void) | null;
  className?: string;
}

function NewConceptButton({ onNewConcept, className }: NewConceptButtonProps) {
  return (
    <Button
      size="sm"
      className={`gap-1.5 text-xs font-semibold uppercase tracking-wide ${className ?? ""}`}
      onClick={() => onNewConcept?.()}
    >
      <Plus className="h-3.5 w-3.5" />
      New Concept
    </Button>
  );
}

interface SearchInputProps {
  value: string;
  onChange: (v: string) => void;
  onFocus?: () => void;
  onBlur?: () => void;
  widthClass: string;
}

function SearchInput({ value, onChange, onFocus, onBlur, widthClass }: SearchInputProps) {
  return (
    <div className="relative">
      <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
      <input
        placeholder="Search concepts..."
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onFocus={onFocus}
        onBlur={onBlur}
        className={`h-9 ${widthClass} rounded-md border bg-card pl-8 pr-8 text-sm focus:outline-none focus:ring-2 focus:ring-primary`}
      />
      {value && (
        <button
          type="button"
          className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
          onClick={() => onChange("")}
        >
          <X className="h-3.5 w-3.5" />
        </button>
      )}
    </div>
  );
}

interface SearchResultsProps {
  results: LineageSearchNode[];
  onSelect: (label: string) => void;
  className?: string;
}

function SearchResults({ results, onSelect, className }: SearchResultsProps) {
  if (results.length === 0) return null;
  return (
    <div className={className}>
      {results.map((node) => (
        <button
          key={node.id}
          type="button"
          onMouseDown={() => onSelect(node.label)}
          className="flex w-full items-center px-3 py-1.5 text-sm hover:bg-muted text-left truncate"
        >
          {node.label}
        </button>
      ))}
    </div>
  );
}

function FullLineageActions() {
  const {
    onNewConcept,
    lineageSearchValue,
    setLineageSearchValue,
    lineageSearchNodes,
    onLineageSearchSelect,
    canRunConcept,
    isRunningConcept,
    onRunConcept,
  } = useEditorActionsStore();

  const canEditOntologies = usePermissionsStore((state) => state.canEdit("can_edit_projects"));
  // New Concept is ontology-wide: allowed under a viewer share only when at
  // least one concept is elevated to writeable (backend enforces per concept).
  const ontologyWideReadOnly = useOntologyWideReadOnly();
  const [searchOpen, setSearchOpen] = useState(false);

  const visibleResults = filterSearchNodes(lineageSearchNodes, lineageSearchValue, 8);
  const showResultsPanel = searchOpen && lineageSearchValue && visibleResults.length > 0;

  return (
    <>
      {canRunConcept && (
        <RunButton isRunningConcept={isRunningConcept} onRunConcept={onRunConcept} />
      )}
      {canEditOntologies && (
        <ReadOnlyGate readOnly={ontologyWideReadOnly}>
          <NewConceptButton onNewConcept={onNewConcept} />
        </ReadOnlyGate>
      )}

      <div className="relative">
        <SearchInput
          value={lineageSearchValue}
          onChange={(v) => setLineageSearchValue?.(v)}
          onFocus={() => setSearchOpen(true)}
          onBlur={() => setTimeout(() => setSearchOpen(false), 150)}
          widthClass="w-44"
        />
        {showResultsPanel && (
          <SearchResults
            results={visibleResults}
            onSelect={(label) => onLineageSearchSelect?.(label)}
            className="absolute top-full mt-1 right-0 z-50 min-w-full w-max max-w-[28rem] rounded-md border bg-card shadow-md py-1"
          />
        )}
      </div>
    </>
  );
}

interface LineageActionItemsProps {
  /** Collapses the surrounding menu after an action is triggered. */
  close: () => void;
}

/** Stacked Run / New Concept / Search column, shared by the lineage kebab and the very-narrow overflow menu. */
export function LineageActionItems({ close }: LineageActionItemsProps) {
  const {
    onNewConcept,
    lineageSearchValue,
    setLineageSearchValue,
    lineageSearchNodes,
    onLineageSearchSelect,
    canRunConcept,
    isRunningConcept,
    onRunConcept,
  } = useEditorActionsStore();

  const canEditOntologies = usePermissionsStore((state) => state.canEdit("can_edit_projects"));
  const ontologyWideReadOnly = useOntologyWideReadOnly();

  const visibleResults = filterSearchNodes(lineageSearchNodes, lineageSearchValue, 6);

  const handleRun = () => {
    onRunConcept?.();
    close();
  };

  const handleNewConcept = () => {
    onNewConcept?.();
    close();
  };

  const handleSelectResult = (label: string) => {
    onLineageSearchSelect?.(label);
    close();
  };

  return (
    <div className="flex flex-col gap-2">
      {canRunConcept && (
        <RunButton
          isRunningConcept={isRunningConcept}
          onRunConcept={handleRun}
          className="w-full justify-center"
        />
      )}
      {canEditOntologies && (
        <ReadOnlyGate readOnly={ontologyWideReadOnly}>
          <NewConceptButton onNewConcept={handleNewConcept} className="w-full justify-center" />
        </ReadOnlyGate>
      )}
      <SearchInput
        value={lineageSearchValue}
        onChange={(v) => setLineageSearchValue?.(v)}
        widthClass="w-full"
      />
      <SearchResults
        results={visibleResults}
        onSelect={handleSelectResult}
        className="max-h-56 overflow-y-auto rounded-md border bg-card py-1"
      />
    </div>
  );
}

function CompactLineageActions() {
  const [open, setOpen] = useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="outline" size="iconSm" title="More actions" aria-label="More actions">
          <MoreHorizontal className="h-4 w-4" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-64 p-2">
        <LineageActionItems close={() => setOpen(false)} />
      </PopoverContent>
    </Popover>
  );
}

export function LineageHeaderActions() {
  const reservedWidth = useChatReservedWidth();
  const isNarrow = useIsNarrowViewport(NARROW_VIEWPORT_PX, reservedWidth);

  return (
    <>
      <ComputeIndicator interactive={true} />
      {isNarrow ? <CompactLineageActions /> : <FullLineageActions />}
    </>
  );
}
