import { BaseClient } from "@/shared/lib/BaseClient";
import type { AppDefinition } from "../schema/appDefinition.types";
import type { DashboardDefinition } from "../types";

/** Raised when the server rejects a schema-v2 definition with actionable errors. */
export class DashboardValidationError extends Error {
  readonly errors: string[];
  readonly warnings: string[];

  constructor(errors: string[], warnings: string[] = []) {
    super(errors.join("; "));
    this.name = "DashboardValidationError";
    this.errors = errors;
    this.warnings = warnings;
  }
}

export type DashboardStatus = "draft" | "published";

export interface DashboardListItem {
  id: string;
  name: string;
  ontologyId: string;
  ontologyName: string;
  logoUrl: string;
  createdAt: string;
  updatedAt: string;
  author: string;
  status: DashboardStatus;
}

/** A saved checkpoint (metadata only — definitions load via restore). */
export interface DashboardVersion {
  id: string;
  version: number;
  author: string;
  createdAt: string;
  bookmarked: boolean;
  label: string | null;
  published: boolean;
  publishedAt: string | null;
}

/** A dashboard with publish metadata; `served` says which variant `definition` is. */
export interface DashboardRecord {
  definition: DashboardDefinition;
  status: DashboardStatus;
  served: DashboardStatus;
  publishedVersion: number | null;
}

interface DashboardListRow {
  id: string;
  name: string;
  ontology_id?: string;
  ontology_name?: string;
  logo_url?: string;
  created_at: string;
  updated_at: string;
  author: string;
  status?: string;
}

interface DashboardGetRow {
  id: string;
  name: string;
  definition: DashboardDefinition;
  created_at: string;
  updated_at: string;
  author: string;
  status?: string;
  served?: string;
  published_version?: number | null;
}

interface DashboardVersionRow {
  id: string;
  version: number;
  author: string | null;
  created_at: string;
  bookmarked: boolean;
  label: string | null;
  published: boolean;
  published_at: string | null;
}

function toStatus(raw: string | undefined): DashboardStatus {
  return raw === "published" ? "published" : "draft";
}

export class DashboardClient extends BaseClient {
  async listAllDashboards(scope = "user", query?: string): Promise<DashboardListItem[]> {
    const params = new URLSearchParams({ scope });
    if (query && query.trim()) params.set("q", query.trim());
    const response = await this.get(`/apps/list?${params.toString()}`);
    if (response.status === "success" && Array.isArray(response.data)) {
      return (response.data as DashboardListRow[]).map((row) => ({
        id: row.id,
        name: row.name,
        ontologyId: row.ontology_id ?? "",
        ontologyName: row.ontology_name ?? row.ontology_id ?? "",
        logoUrl: row.logo_url ?? "",
        createdAt: row.created_at,
        updatedAt: row.updated_at,
        author: row.author ?? "",
        status: toStatus(row.status),
      }));
    }
    return [];
  }

  async listDashboards(ontologyId: string, scope = "user"): Promise<DashboardListItem[]> {
    const response = await this.get(`/apps/${ontologyId}/list?scope=${scope}`);
    if (response.status === "success" && Array.isArray(response.data)) {
      return (response.data as DashboardListRow[]).map((row) => ({
        id: row.id,
        name: row.name,
        ontologyId,
        ontologyName: ontologyId,
        logoUrl: row.logo_url ?? "",
        createdAt: row.created_at,
        updatedAt: row.updated_at,
        author: row.author ?? "",
        status: toStatus(row.status),
      }));
    }
    return [];
  }

  async getDashboard(
    ontologyId: string,
    id: string,
    scope = "user",
  ): Promise<DashboardDefinition | null> {
    const response = await this.get(`/apps/${ontologyId}/${id}?scope=${scope}`);
    if (response.status === "success" && response.data) {
      return (response.data as DashboardGetRow).definition;
    }
    return null;
  }

  async saveDashboard(
    ontologyId: string,
    dashboard: DashboardDefinition | AppDefinition,
    scope = "user",
  ): Promise<string> {
    const response = await this.post(`/apps/${ontologyId}/save`, { app: dashboard, scope });
    if (response.status === "success" && response.data?.id) {
      return response.data.id as string;
    }
    const data = response.data as { errors?: string[]; warnings?: string[] } | undefined;
    if (Array.isArray(data?.errors) && data.errors.length > 0) {
      throw new DashboardValidationError(data.errors, data.warnings ?? []);
    }
    throw new Error(response.message ?? "Failed to save app");
  }

  async deleteDashboard(ontologyId: string, id: string, scope = "user"): Promise<void> {
    const response = await this.delete(`/apps/${ontologyId}/${id}?scope=${scope}`);
    if (response.status !== "success") {
      throw new Error(response.message ?? "Failed to delete app");
    }
  }

  /**
   * Load a dashboard with publish metadata. `variant: "published"` serves the
   * published snapshot when one exists (`served` reports the fallback).
   */
  async getDashboardRecord(
    ontologyId: string,
    id: string,
    variant: DashboardStatus = "draft",
    scope = "user",
  ): Promise<DashboardRecord | null> {
    const response = await this.get(`/apps/${ontologyId}/${id}?scope=${scope}&variant=${variant}`);
    if (response.status !== "success" || !response.data) return null;
    const row = response.data as DashboardGetRow;
    return {
      definition: row.definition,
      status: toStatus(row.status),
      served: toStatus(row.served),
      publishedVersion: row.published_version ?? null,
    };
  }

  async listVersions(ontologyId: string, id: string, scope = "user"): Promise<DashboardVersion[]> {
    const response = await this.get(`/apps/${ontologyId}/${id}/versions?scope=${scope}`);
    if (response.status !== "success" || !Array.isArray(response.data)) return [];
    return (response.data as DashboardVersionRow[]).map((row) => ({
      id: row.id,
      version: row.version,
      author: row.author ?? "",
      createdAt: row.created_at,
      bookmarked: row.bookmarked,
      label: row.label,
      published: row.published,
      publishedAt: row.published_at,
    }));
  }

  async restoreVersion(ontologyId: string, id: string, versionId: string): Promise<void> {
    const response = await this.post(`/apps/${ontologyId}/${id}/versions/${versionId}/restore`, {});
    if (response.status !== "success") {
      throw new Error(response.message ?? "Failed to restore version");
    }
  }

  async bookmarkVersion(
    ontologyId: string,
    id: string,
    versionId: string,
    bookmarked: boolean,
    label?: string,
  ): Promise<void> {
    const response = await this.patch(`/apps/${ontologyId}/${id}/versions/${versionId}/bookmark`, {
      bookmarked,
      label,
    });
    if (response.status !== "success") {
      throw new Error(response.message ?? "Failed to update bookmark");
    }
  }

  async publishDashboard(ontologyId: string, id: string): Promise<number | null> {
    const response = await this.post(`/apps/${ontologyId}/${id}/publish`, {});
    if (response.status !== "success") {
      throw new Error(response.message ?? "Failed to publish app");
    }
    const data = response.data as { version?: number } | undefined;
    return data?.version ?? null;
  }

  async unpublishDashboard(ontologyId: string, id: string): Promise<void> {
    const response = await this.post(`/apps/${ontologyId}/${id}/unpublish`, {});
    if (response.status !== "success") {
      throw new Error(response.message ?? "Failed to unpublish app");
    }
  }
}
