import { create } from "zustand";
import {
  buildUpgradeContent,
  type FreemiumLimitCode,
  parseFreemiumLimit,
  type UpgradeWallContent,
} from "../utils/freemiumLimit";

interface UpgradeWallState {
  isOpen: boolean;
  content: UpgradeWallContent | null;
  openUpgradeWall: (content: UpgradeWallContent) => void;
  closeUpgradeWall: () => void;
}

/**
 * Single store + dialog for every freemium "contact Prometheux to upgrade" wall
 * (storage, projects, data sources, versioning). Store-driven so any API client
 * or component can trigger it without prop drilling. The two helpers below are
 * the only entry points callers need.
 */
export const useUpgradeWallStore = create<UpgradeWallState>((set) => ({
  isOpen: false,
  content: null,
  openUpgradeWall: (content) => set({ isOpen: true, content }),
  closeUpgradeWall: () => set({ isOpen: false }),
}));

/**
 * Reactive entry point: if `error` is a recognised freemium 402, open the wall
 * with the matching copy. Returns true when handled so callers can branch.
 */
export const handleFreemiumLimitError = (error: unknown): boolean => {
  const info = parseFreemiumLimit(error);
  if (!info) return false;
  useUpgradeWallStore.getState().openUpgradeWall(buildUpgradeContent(info));
  return true;
};

/**
 * Proactive entry point: open the wall for a known code up front (e.g. a binary
 * feature the UI knows is gated before any request is made).
 */
export const openUpgradeWallForCode = (code: FreemiumLimitCode): void => {
  useUpgradeWallStore.getState().openUpgradeWall(
    buildUpgradeContent({
      code,
      used: null,
      limit: null,
      usedMb: null,
      limitMb: null,
      resetsAt: null,
    }),
  );
};
