import { ChevronDown, ChevronRight } from "lucide-react";
import { useState } from "react";
import { EditableNoteCard } from "./EditableNoteCard";
import type { DocumentContextNote } from "./types";

interface ContextSectionProps {
  notes?: DocumentContextNote[];
  onNoteSaved: () => void;
}

export function ContextSection({ notes = [], onNoteSaved }: ContextSectionProps) {
  const [isCollapsed, setIsCollapsed] = useState(false);

  if (notes.length === 0) return null;

  const toggle = () => setIsCollapsed((prev) => !prev);

  return (
    <section className="px-8 py-6">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground">
          Context
          <span className="ml-2 font-normal text-muted-foreground/60">({notes.length})</span>
        </h2>
        <button
          type="button"
          onClick={toggle}
          aria-expanded={!isCollapsed}
          aria-label={isCollapsed ? "Expand context section" : "Collapse context section"}
          title={isCollapsed ? "Expand context" : "Collapse context"}
          className="rounded p-1 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus:outline-none focus:ring-2 focus:ring-primary"
        >
          {isCollapsed ? <ChevronRight className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
        </button>
      </div>
      {!isCollapsed && (
        <ul className="mt-3 space-y-2">
          {notes.map((note) => (
            <EditableNoteCard key={note.id} note={note} onSaved={onNoteSaved} />
          ))}
        </ul>
      )}
    </section>
  );
}
