import { useCallback, useRef, useState } from "react";
import { toast } from "sonner";
import { useConceptEditorClient } from "@/features/concept-editor/api/ConceptEditorClientContext";
import type { ColumnFilterValue } from "@/features/concept-editor/components/query/components/QueryResultTable";
import type { ConceptCell, OrderByItem } from "@/features/concept-editor/types";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";
import { simplifyFetchError } from "@/shared/utils/errorUtils";

// Type for tracking active search state per predicate
interface PredicateSearchState {
  searchTerm: string;
  columnPositions?: number[];
  columnFilters?: Record<number, ColumnFilterValue>;
}

// Default page size
const DEFAULT_PAGE_SIZE = 10;

export const usePaginatedResults = (
  cells: ConceptCell[],
  setCells: React.Dispatch<React.SetStateAction<ConceptCell[]>>,
) => {
  const [isLoadingPage, setIsLoadingPage] = useState(false);
  const ontologyId = useOntologyId();
  const ontologyScope = useOntologyScope();
  const client = useConceptEditorClient();

  // Track active search state per cell and predicate
  // Key format: `${cellId}:${predicate}`
  const searchStateRef = useRef<Map<string, PredicateSearchState>>(new Map());

  // Track page size per cell and predicate
  const pageSizeRef = useRef<Map<string, number>>(new Map());

  // Track ordering per cell and predicate
  const orderByRef = useRef<Map<string, OrderByItem[]>>(new Map());

  // Helper to get search state key
  const getSearchKey = (cellId: string, predicate: string) => `${cellId}:${predicate}`;

  // Helper to update cell loading state
  const setPredicateLoading = useCallback(
    (cellId: string, predicate: string, loading: boolean) => {
      setCells((prevCells) => {
        const cellIndex = prevCells.findIndex((c) => c.id === cellId);
        if (cellIndex === -1) return prevCells;

        const cell = prevCells[cellIndex];
        const loadingPredicates = cell.loadingPredicates || [];

        if (loading) {
          if (loadingPredicates.includes(predicate)) return prevCells;
          const updatedCell = {
            ...cell,
            loadingPredicates: [...loadingPredicates, predicate],
          };
          const next = [...prevCells];
          next[cellIndex] = updatedCell;
          return next;
        } else {
          const updatedCell = {
            ...cell,
            loadingPredicates: loadingPredicates.filter((p) => p !== predicate),
          };
          const next = [...prevCells];
          next[cellIndex] = updatedCell;
          return next;
        }
      });
    },
    [setCells],
  );

  // Helper to get page size for a predicate
  const getPageSize = useCallback((cellId: string, predicate: string): number => {
    const key = getSearchKey(cellId, predicate);
    return pageSizeRef.current.get(key) || DEFAULT_PAGE_SIZE;
  }, []);

  // Helper to get orderBy for a predicate
  const getOrderBy = useCallback((cellId: string, predicate: string): OrderByItem[] | undefined => {
    const key = getSearchKey(cellId, predicate);
    return orderByRef.current.get(key);
  }, []);

  // Helper to update predicate data in cells
  const updatePredicateData = useCallback(
    (
      cellId: string,
      predicate: string,
      data: { columnNames: string[]; facts: any[][] },
      pagination: {
        page: number;
        total_pages: number;
        has_next: boolean;
        has_prev: boolean;
        total_count: number;
        order_by?: OrderByItem[];
      },
      searchState?: PredicateSearchState,
      pageSize?: number,
      orderBy?: OrderByItem[],
      elapsedTime?: number,
    ) => {
      setCells((prevCells) => {
        const cellIndex = prevCells.findIndex((c) => c.id === cellId);
        if (
          cellIndex === -1 ||
          !prevCells[cellIndex].result ||
          prevCells[cellIndex].result.type !== "query-result"
        ) {
          return prevCells;
        }

        const cell = prevCells[cellIndex];
        const updatedData = { ...cell.result.data };

        updatedData[predicate] = {
          columns: data.columnNames || [],
          rows: data.facts || [],
          pagination: {
            page: pagination.page,
            totalPages: pagination.total_pages,
            hasNext: pagination.has_next,
            hasPrev: pagination.has_prev,
            totalCount: pagination.total_count,
            pageSize: pageSize || DEFAULT_PAGE_SIZE,
            orderBy: orderBy || pagination.order_by,
          },
          // Store search state in the predicate data for UI to access
          searchState: searchState
            ? {
                searchTerm: searchState.searchTerm,
                columnPositions: searchState.columnPositions,
                columnFilters: searchState.columnFilters,
              }
            : undefined,
          fetchElapsedTime: elapsedTime, // Store fetch/pagination time for this predicate
        };

        const loadingPredicates = (cell.loadingPredicates || []).filter((p) => p !== predicate);

        const updatedCell = {
          ...cell,
          result: { ...cell.result, data: updatedData },
          loadingPredicates,
        };

        const next = [...prevCells];
        next[cellIndex] = updatedCell;
        return next;
      });
    },
    [setCells],
  );

  // Helper to set error state for predicate
  const setPredicateError = useCallback(
    (cellId: string, predicate: string) => {
      setCells((prevCells) => {
        const cellIndex = prevCells.findIndex((c) => c.id === cellId);
        if (
          cellIndex === -1 ||
          !prevCells[cellIndex].result ||
          prevCells[cellIndex].result.type !== "query-result"
        ) {
          return prevCells;
        }

        const cell = prevCells[cellIndex];
        const updatedData = { ...cell.result.data };

        updatedData[predicate] = {
          columns: [],
          rows: [],
          pagination: {
            page: 1,
            totalPages: 1,
            hasNext: false,
            hasPrev: false,
            totalCount: 0,
          },
        };

        const loadingPredicates = (cell.loadingPredicates || []).filter((p) => p !== predicate);

        const updatedCell = {
          ...cell,
          result: { ...cell.result, data: updatedData },
          loadingPredicates,
        };

        const next = [...prevCells];
        next[cellIndex] = updatedCell;
        return next;
      });
    },
    [setCells],
  );

  const fetchPredicateData = useCallback(
    async (
      cellId: string,
      predicate: string,
      page: number = 1,
      pageSize?: number,
      orderBy?: OrderByItem[],
    ) => {
      if (!ontologyId) return;

      const cell = cells.find((c) => c.id === cellId);
      if (!cell?.cellBackendId) {
        return;
      }

      const effectivePageSize = pageSize ?? getPageSize(cellId, predicate);
      const effectiveOrderBy = orderBy ?? getOrderBy(cellId, predicate);

      try {
        setIsLoadingPage(true);
        setPredicateLoading(cellId, predicate, true);

        const selectedMachineId = localStorage.getItem("selectedMachineId");
        let compute;
        if (selectedMachineId) {
          compute = {
            machine_configs: {
              id: selectedMachineId,
              machine_url: "",
            },
          };
        }

        const response = await client.fetchOutputFacts(
          ontologyId,
          predicate,
          page,
          ontologyScope,
          effectivePageSize,
          effectiveOrderBy,
          compute,
        );

        if (response.status === "success" && response.data) {
          // Clear search state when fetching normal data
          const searchKey = getSearchKey(cellId, predicate);
          searchStateRef.current.delete(searchKey);

          updatePredicateData(
            cellId,
            predicate,
            response.data.results,
            response.data.pagination,
            undefined,
            effectivePageSize,
            effectiveOrderBy,
            response.data.elapsedTime,
          );
        } else {
          throw new Error(response.error || "Failed to fetch predicate data");
        }
      } catch (error) {
        console.error("Error fetching paginated data:", error);
        const errorMsg = simplifyFetchError(error instanceof Error ? error.message : String(error));
        toast.error(errorMsg, { duration: 8000 });
        setPredicateError(cellId, predicate);
      } finally {
        setIsLoadingPage(false);
      }
    },
    [
      cells,
      ontologyId,
      ontologyScope,
      client,
      setPredicateLoading,
      updatePredicateData,
      setPredicateError,
      getPageSize,
      getOrderBy,
    ],
  );

  const searchPredicateData = useCallback(
    async (
      cellId: string,
      predicate: string,
      searchTerm?: string,
      columnFilters?: Record<number, ColumnFilterValue>,
      page: number = 1,
      pageSize?: number,
      orderBy?: OrderByItem[],
    ) => {
      if (!ontologyId) return;

      const cell = cells.find((c) => c.id === cellId);
      if (!cell?.cellBackendId) {
        return;
      }

      const hasGlobalSearch = searchTerm && searchTerm.trim();
      const hasColumnFilters = columnFilters && Object.keys(columnFilters).length > 0;

      if (!hasGlobalSearch && !hasColumnFilters) {
        toast.error("Please enter a search term");
        return;
      }

      // Use provided pageSize or get stored one
      const effectivePageSize = pageSize ?? getPageSize(cellId, predicate);
      // Use provided orderBy or get stored one
      const effectiveOrderBy = orderBy ?? getOrderBy(cellId, predicate);

      try {
        setIsLoadingPage(true);
        setPredicateLoading(cellId, predicate, true);

        // Get selected compute from localStorage
        const selectedMachineId = localStorage.getItem("selectedMachineId");
        let compute;
        if (selectedMachineId) {
          compute = {
            machine_configs: {
              id: selectedMachineId,
              machine_url: "",
            },
          };
        }

        const response = await client.searchOutputFacts(
          ontologyId,
          predicate,
          hasGlobalSearch ? searchTerm!.trim() : undefined,
          hasColumnFilters ? columnFilters : undefined,
          page,
          effectivePageSize,
          ontologyScope,
          effectiveOrderBy,
          compute,
        );

        if (response.status === "success" && response.data) {
          // Store search state for pagination within search results
          const searchKey = getSearchKey(cellId, predicate);
          const columnPositions = hasColumnFilters
            ? Object.keys(columnFilters!).map(Number)
            : undefined;
          const searchState: PredicateSearchState = {
            searchTerm: hasGlobalSearch ? searchTerm!.trim() : "",
            columnPositions,
            columnFilters,
          };
          searchStateRef.current.set(searchKey, searchState);

          updatePredicateData(
            cellId,
            predicate,
            response.data.results,
            response.data.pagination,
            searchState,
            effectivePageSize,
            effectiveOrderBy,
            response.data.elapsedTime,
          );
        } else {
          throw new Error(response.error || "Failed to search predicate data");
        }
      } catch (error) {
        console.error("Error searching predicate data:", error);
        const errorMsg = simplifyFetchError(error instanceof Error ? error.message : String(error));
        toast.error(errorMsg, { duration: 8000 });
        setPredicateError(cellId, predicate);
      } finally {
        setIsLoadingPage(false);
      }
    },
    [
      cells,
      ontologyId,
      ontologyScope,
      client,
      setPredicateLoading,
      updatePredicateData,
      setPredicateError,
      getPageSize,
      getOrderBy,
    ],
  );

  // Clear search and return to normal pagination
  const clearSearch = useCallback(
    (cellId: string, predicate: string) => {
      const searchKey = getSearchKey(cellId, predicate);
      searchStateRef.current.delete(searchKey);

      // Explicitly get the current orderBy and pageSize to preserve them
      const currentPageSize = getPageSize(cellId, predicate);
      const currentOrderBy = getOrderBy(cellId, predicate);

      // Fetch first page of normal data with preserved settings
      fetchPredicateData(cellId, predicate, 1, currentPageSize, currentOrderBy);
    },
    [fetchPredicateData, getPageSize, getOrderBy],
  );

  // Change page - handles both normal pagination and search pagination
  const changePage = useCallback(
    (cellId: string, predicate: string, newPage: number) => {
      const searchKey = getSearchKey(cellId, predicate);
      const searchState = searchStateRef.current.get(searchKey);
      const pageSize = getPageSize(cellId, predicate);
      const orderBy = getOrderBy(cellId, predicate);

      if (searchState) {
        // If in search mode, paginate within search results
        // Pass searchTerm for global search, or columnFilters for column-specific
        const hasColumnFilters =
          searchState.columnFilters && Object.keys(searchState.columnFilters).length > 0;
        searchPredicateData(
          cellId,
          predicate,
          hasColumnFilters ? undefined : searchState.searchTerm,
          hasColumnFilters ? searchState.columnFilters : undefined,
          newPage,
          pageSize,
          orderBy,
        );
      } else {
        // Normal pagination
        fetchPredicateData(cellId, predicate, newPage, pageSize, orderBy);
      }
    },
    [fetchPredicateData, searchPredicateData, getPageSize, getOrderBy],
  );

  // Change page size - updates stored page size and refetches from page 1
  const changePageSize = useCallback(
    (cellId: string, predicate: string, newPageSize: number) => {
      const key = getSearchKey(cellId, predicate);
      pageSizeRef.current.set(key, newPageSize);

      const searchState = searchStateRef.current.get(key);
      const orderBy = getOrderBy(cellId, predicate);

      if (searchState) {
        // If in search mode, re-search with new page size
        const hasColumnFilters =
          searchState.columnFilters && Object.keys(searchState.columnFilters).length > 0;
        searchPredicateData(
          cellId,
          predicate,
          hasColumnFilters ? undefined : searchState.searchTerm,
          hasColumnFilters ? searchState.columnFilters : undefined,
          1, // Reset to page 1
          newPageSize,
          orderBy,
        );
      } else {
        // Normal pagination - refetch from page 1 with new size
        fetchPredicateData(cellId, predicate, 1, newPageSize, orderBy);
      }
    },
    [fetchPredicateData, searchPredicateData, getOrderBy],
  );

  // Change ordering - updates stored orderBy and refetches from page 1
  const changeOrderBy = useCallback(
    (cellId: string, predicate: string, newOrderBy: OrderByItem[]) => {
      const key = getSearchKey(cellId, predicate);

      // Store or remove orderBy
      if (newOrderBy.length > 0) {
        orderByRef.current.set(key, newOrderBy);
      } else {
        orderByRef.current.delete(key);
      }

      const searchState = searchStateRef.current.get(key);
      const pageSize = getPageSize(cellId, predicate);

      if (searchState) {
        // If in search mode, re-search with new ordering
        const hasColumnFilters =
          searchState.columnFilters && Object.keys(searchState.columnFilters).length > 0;
        searchPredicateData(
          cellId,
          predicate,
          hasColumnFilters ? undefined : searchState.searchTerm,
          hasColumnFilters ? searchState.columnFilters : undefined,
          1, // Reset to page 1
          pageSize,
          newOrderBy.length > 0 ? newOrderBy : undefined,
        );
      } else {
        // Normal pagination - refetch from page 1 with new ordering
        fetchPredicateData(
          cellId,
          predicate,
          1,
          pageSize,
          newOrderBy.length > 0 ? newOrderBy : undefined,
        );
      }
    },
    [fetchPredicateData, searchPredicateData, getPageSize],
  );

  // Get current search state for a predicate
  const getSearchState = useCallback((cellId: string, predicate: string) => {
    const searchKey = getSearchKey(cellId, predicate);
    return searchStateRef.current.get(searchKey);
  }, []);

  return {
    fetchPredicateData,
    changePage,
    changePageSize,
    changeOrderBy,
    isLoadingPage,
    searchPredicateData,
    clearSearch,
    getSearchState,
  };
};
