import { useQuery } from "@tanstack/react-query";
import { matchPath, useLocation } from "react-router-dom";
import { DashboardClient } from "../api/DashboardClient";

const dashboardClient = new DashboardClient();

/** Route slug used for creating a brand-new dashboard, which has no id to load. */
const NEW_DASHBOARD_SLUG = "new";

/**
 * Resolves the name of the dashboard for the current route, reusing the same
 * React Query cache (`["dashboard", projectId, id]`) as the run/edit pages so
 * no extra fetch is issued. Returns null when not on a dashboard route or for
 * the "new dashboard" route.
 */
export function useCurrentDashboardName(): { dashboardName: string | null } {
  const location = useLocation();
  const match =
    matchPath("/apps/:ontologyId/:id/edit", location.pathname) ??
    matchPath("/apps/:ontologyId/:id", location.pathname);

  const ontologyId = match?.params.ontologyId;
  const id = match?.params.id;
  const isNew = ontologyId === NEW_DASHBOARD_SLUG;

  const { data } = useQuery({
    queryKey: ["dashboard", ontologyId, id],
    queryFn: () => dashboardClient.getDashboard(ontologyId as string, id as string),
    enabled: Boolean(ontologyId) && Boolean(id) && !isNew,
  });

  return { dashboardName: data?.name ?? null };
}
