import { useCallback, useEffect, useRef, useState } from "react";
import type { MachineStatusEvent, MachineStatusValue } from "@/features/compute/api/MachineClient";
import { MachineClient } from "@/features/compute/api/MachineClient";
import type { AvailabilityResult, UserMachine } from "@/features/compute/utils";

function buildStatusMessage(
  status: MachineStatusValue,
  podInfo?: MachineStatusEvent["pod_info"],
): string {
  switch (status) {
    case "started":
      return "Running";
    case "stopped":
      return "Stopped - Click Start to begin";
    case "stopping":
      return "Stopping...";
    case "pending":
      return "Starting up...";
    case "starting":
      return "Container is being created...";
    case "crashed":
      return `Crashed - Restarts: ${podInfo?.restarts || 0}`;
    case "restarting":
      return "Restarting...";
    default:
      return "Unknown status";
  }
}

interface UseMachineStatusStreamReturn {
  startStream: (userMachineId: string, machineId: string) => void;
  stopStream: () => void;
  isStreaming: boolean;
}

/**
 * Hook that subscribes to a WebSocket stream for real-time machine status updates
 * and feeds them into the same availabilityResults / userMachines state that
 * the one-shot checkMachineStatus writes to.
 */
export const useMachineStatusStream = (
  setAvailabilityResults: React.Dispatch<React.SetStateAction<Record<string, AvailabilityResult>>>,
  setUserMachines: React.Dispatch<React.SetStateAction<UserMachine[]>>,
  checkMachineStatus: (machineId: string, userMachineId: string) => Promise<MachineStatusValue>,
): UseMachineStatusStreamReturn => {
  const wsRef = useRef<WebSocket | null>(null);
  const [isStreaming, setIsStreaming] = useState(false);
  const client = useRef(new MachineClient()).current;

  const stopStream = useCallback(() => {
    if (wsRef.current && wsRef.current.readyState !== WebSocket.CLOSED) {
      wsRef.current.close();
    }
    wsRef.current = null;
    setIsStreaming(false);
  }, []);

  // Clean up on unmount so we never leave a dangling connection
  useEffect(() => stopStream, [stopStream]);

  const startStream = useCallback(
    (userMachineId: string, machineId: string) => {
      // Tear down any existing connection first
      if (wsRef.current && wsRef.current.readyState !== WebSocket.CLOSED) {
        wsRef.current.close();
      }

      setIsStreaming(true);

      const STABLE_STATES: MachineStatusValue[] = ["started", "stopped", "crashed"];
      let finalized = false;

      const finalizeStream = async () => {
        if (finalized) return;
        finalized = true;

        if (wsRef.current && wsRef.current.readyState !== WebSocket.CLOSED) {
          wsRef.current.close();
        }
        wsRef.current = null;
        setIsStreaming(false);
        try {
          await checkMachineStatus(machineId, userMachineId);
        } catch {
          // Non-critical — the stream already set the terminal state
        }
      };

      const onStatus = (event: MachineStatusEvent) => {
        if (finalized) return;

        const statusMessage = buildStatusMessage(event.machine_status, event.pod_info);

        setAvailabilityResults((prev) => ({
          ...prev,
          [machineId]: {
            status: "success",
            message: statusMessage,
            is_available: event.machine_status === "started",
            machine_status: event.machine_status,
            pod_info: event.pod_info,
          },
        }));

        setUserMachines((prev) =>
          prev.map((um) => (um.id === userMachineId ? { ...um, is_active: event.is_active } : um)),
        );

        if (STABLE_STATES.includes(event.machine_status)) {
          finalizeStream();
        }
      };

      const onDone = () => {
        finalizeStream();
      };

      const onError = (error: string) => {
        console.error("Machine status stream error:", error);
      };

      client
        .connectMachineStatusWs(userMachineId, onStatus, onDone, onError)
        .then((ws) => {
          if (finalized) {
            ws.close();
            return;
          }
          wsRef.current = ws;
        })
        .catch((err) => {
          console.error("Failed to open machine status WebSocket:", err);
          setIsStreaming(false);
        });
    },
    [client, setAvailabilityResults, setUserMachines, checkMachineStatus],
  );

  return { startStream, stopStream, isStreaming };
};
