import { ChevronDown, Database } from "lucide-react";
import type React from "react";
import { useMemo, useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";

type IntervalUnit = "minutes" | "hours" | "days" | "weeks";

const UNIT_OPTIONS: { value: IntervalUnit; label: string; min: number; max: number }[] = [
  { value: "minutes", label: "minutes", min: 1, max: 59 },
  { value: "hours", label: "hours", min: 1, max: 23 },
  { value: "days", label: "days", min: 1, max: 30 },
  { value: "weeks", label: "weeks", min: 1, max: 4 },
];

interface DataChangePolicyFormProps {
  onSubmit: (checkIntervalMinutes: number) => Promise<void>;
  onCancel: () => void;
}

function unitToMinutes(value: number, unit: IntervalUnit): number {
  switch (unit) {
    case "hours":
      return value * 60;
    case "days":
      return value * 1440;
    case "weeks":
      return value * 10080;
    default:
      return value;
  }
}

export function describeDataChangeInterval(minutes: number): string {
  if (minutes >= 10080 && minutes % 10080 === 0) {
    const w = minutes / 10080;
    return w === 1 ? "Check every week" : `Check every ${w} weeks`;
  }
  if (minutes >= 1440 && minutes % 1440 === 0) {
    const d = minutes / 1440;
    return d === 1 ? "Check every day" : `Check every ${d} days`;
  }
  if (minutes >= 60 && minutes % 60 === 0) {
    const h = minutes / 60;
    return h === 1 ? "Check every hour" : `Check every ${h} hours`;
  }
  return minutes === 1 ? "Check every minute" : `Check every ${minutes} minutes`;
}

const DataChangePolicyForm: React.FC<DataChangePolicyFormProps> = ({ onSubmit, onCancel }) => {
  const [intervalValue, setIntervalValue] = useState(5);
  const [intervalUnit, setIntervalUnit] = useState<IntervalUnit>("minutes");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const currentUnitConfig = UNIT_OPTIONS.find((u) => u.value === intervalUnit)!;

  const clampedValue = Math.max(
    currentUnitConfig.min,
    Math.min(currentUnitConfig.max, intervalValue),
  );
  if (clampedValue !== intervalValue) {
    setIntervalValue(clampedValue);
  }

  const checkIntervalMinutes = useMemo(
    () => unitToMinutes(intervalValue, intervalUnit),
    [intervalValue, intervalUnit],
  );

  const description = useMemo(() => {
    const unitLabel = intervalValue === 1 ? intervalUnit.slice(0, -1) : intervalUnit;
    return `Checks upstream datasources every ${intervalValue} ${unitLabel} — runs concept only when data changes`;
  }, [intervalValue, intervalUnit]);

  const handleSubmit = async () => {
    setIsSubmitting(true);
    try {
      await onSubmit(checkIntervalMinutes);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="flex flex-col gap-3 p-3 border border-border/50 rounded-md bg-background">
      <div className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
        <Database className="h-3 w-3" />
        New data-change policy
      </div>

      <div className="flex items-center gap-2">
        <span className="text-xs text-muted-foreground whitespace-nowrap">Check every</span>
        <Input
          type="number"
          min={currentUnitConfig.min}
          max={currentUnitConfig.max}
          value={intervalValue}
          onChange={(e) => setIntervalValue(Number.parseInt(e.target.value, 10) || 1)}
          className="h-7 text-xs w-16 text-center"
        />
        <div className="relative">
          <select
            value={intervalUnit}
            onChange={(e) => setIntervalUnit(e.target.value as IntervalUnit)}
            className="h-7 text-xs appearance-none bg-background border border-input rounded-md pl-2 pr-6 focus:outline-none focus:ring-1 focus:ring-ring cursor-pointer"
          >
            {UNIT_OPTIONS.map((opt) => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
          <ChevronDown className="h-3 w-3 absolute right-1.5 top-1/2 -translate-y-1/2 pointer-events-none text-muted-foreground" />
        </div>
      </div>

      <div className="text-[10px] text-muted-foreground/70">{description}</div>

      <div className="flex justify-end gap-2">
        <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onCancel}>
          Cancel
        </Button>
        <Button size="sm" className="h-7 text-xs" disabled={isSubmitting} onClick={handleSubmit}>
          {isSubmitting ? "Creating..." : "Create"}
        </Button>
      </div>
    </div>
  );
};

export default DataChangePolicyForm;
