// Backend wire types (snake_case) for the Teams feature. Kept 1:1 with the
// backend contract so the api layer doesn't need to translate on every call —
// components that need camelCase can compute local view models.
//
// Teams are a purely logical governance object; they are NOT the same axis as
// the existing infra `organization` (email-domain → Kubernetes namespace). Do
// not conflate team roles with the org-level admin flag.

// ---------------------------------------------------------------------------
// Roles and status
// ---------------------------------------------------------------------------

export type TeamRole = "owner" | "admin" | "member";

// Roles you can invite / assign directly (owner is only set via create or
// transfer-ownership).
export type AssignableTeamRole = Exclude<TeamRole, "owner">;

export type MemberStatus = "active" | "removed" | "left";

export type InvitationStatus = "pending" | "accepted" | "declined" | "expired";

// ---------------------------------------------------------------------------
// Team objects
// ---------------------------------------------------------------------------

// Shape returned by POST /teams (fresh create).
export interface Team {
  id: string;
  slug: string;
  name: string;
  created_by: string;
  linked_domain: string | null;
  billing_plan: string | null;
  seats: number | null;
  created_at: string;
  updated_at: string;
}

// Row returned by GET /teams — Team + caller-context fields.
//
// Seat model (owner-funded): the team owner buys a plan with N seats. The
// owner always occupies one seat automatically, so N-1 remain for others.
// Any owner/admin can grant/release seats on specific members via
// POST/DELETE /teams/{team_id}/members/{user_id}/seat. A seated member
// inherits the team's plan; unseated members fall back to their personal
// plan. There is no member-driven "billing team" concept anymore.
export interface TeamMembershipRow extends Team {
  role: TeamRole;
  // Does the caller hold a seat on this team?
  seat_granted: boolean;
  // Visible only to owner/admin — the backend hides plan capacity from
  // regular members. `seats` is inherited from Team but the caller-scoped
  // `seats_used` is only meaningful here.
  seats_used?: number | null;
}

// ---------------------------------------------------------------------------
// Onboarding suggestion
// ---------------------------------------------------------------------------

export type SuggestionAction = "none" | "join" | "create" | "create_optional";

// For `action: "join"` the payload carries enough contact info to point the
// user at the right admin to ask for an invite (`owner_email` is canonical;
// username/organization are for display / secondary reference). Fields are
// only populated on the "join" branch — everything is nullable so a caller
// can render defensively.
export interface SuggestionTeam {
  id: string;
  name: string;
  owner_username?: string | null;
  owner_organization?: string | null;
  owner_email?: string | null;
}

export interface Suggestion {
  action: SuggestionAction;
  team?: SuggestionTeam | null;
  suggested_name?: string | null;
}

// ---------------------------------------------------------------------------
// Invitations
// ---------------------------------------------------------------------------

// Recipient identifier — exactly one shape must be provided at the top level
// or nested under `recipient`. The backend accepts both; we normalise to the
// top-level form on the way out.
export type InviteRecipient =
  | { email: string }
  | { sub: string }
  | { username: string; organization: string };

export interface InviteInput {
  team_id: string;
  role: AssignableTeamRole;
  recipient: InviteRecipient;
}

// Full invitation object returned by POST /teams/invite.
export interface Invitation {
  id: string;
  team_id: string;
  email: string;
  role: AssignableTeamRole;
  token: string;
  status: InvitationStatus;
  invited_by: string;
  expires_at: string | null;
  created_at: string;
}

// Row returned by GET /teams/invitations — the invitee's inbox. Carries
// enough team context (team_name, team_slug) to render a card without a
// second request.
export interface InvitationInboxEntry {
  id: string;
  team_id: string;
  team_name: string;
  team_slug: string;
  role: AssignableTeamRole;
  token: string;
  status: InvitationStatus;
  invited_by: string;
  expires_at: string | null;
  created_at: string;
}

// Row returned by GET /teams/{team_id}/invitations — the *team*-side view of
// pending invitations that owner/admin can revoke. Deliberately does NOT
// include the invitation token (that's a recipient-only secret used to
// accept) so team admins can't impersonate the invitee.
export interface TeamPendingInvitation {
  id: string;
  team_id: string;
  email: string;
  role: AssignableTeamRole;
  status: InvitationStatus;
  invited_by: string;
  expires_at: string | null;
  created_at: string;
}

// ---------------------------------------------------------------------------
// Join requests (domain-gated self-service join)
// ---------------------------------------------------------------------------

// Lifecycle: pending → approved | rejected | cancelled. `approved` returns a
// membership; `rejected` / `cancelled` terminates the row.
export type JoinRequestStatus = "pending" | "approved" | "rejected" | "cancelled";

// Row returned by GET /teams/join-requests — the caller's own requests across
// all teams, any status. Minimal shape: enough to show "Request pending" state
// and offer a Cancel action, keyed by team_id so the banner can cross-check
// with a specific suggestion.
export interface MyJoinRequest {
  id: string;
  team_id: string;
  status: JoinRequestStatus;
  created_at: string;
}

// Row returned by GET /teams/{team_id}/join-requests — the *team*-side view
// for owner/admin. Carries the requester's identity so admins can decide.
export interface TeamJoinRequest {
  id: string;
  user_id: string;
  username: string;
  organization: string;
  email: string;
  status: JoinRequestStatus;
  created_at: string;
}

// ---------------------------------------------------------------------------
// Membership
// ---------------------------------------------------------------------------

export interface MemberRow {
  user_id: string;
  username: string;
  organization: string;
  email: string;
  role: TeamRole;
  status: MemberStatus;
  joined_at: string;
  // Whether this member currently holds one of the team's plan seats. A
  // seated member inherits the team plan (owner-funded model). Owner/admin
  // callers can toggle this via grantSeat / releaseSeat.
  seat_granted: boolean;
}

export interface Membership {
  team_id: string;
  user_id: string;
  role: TeamRole;
  status: MemberStatus;
  joined_at: string;
}

// ---------------------------------------------------------------------------
// Response envelopes
// ---------------------------------------------------------------------------

// Success and validation errors come through this standard envelope. Business
// / RPC errors (403/404/409/502) bypass this and land as `{ detail: "..." }`
// bodies with the appropriate HTTP status — handled by the api layer.
export interface TeamApiResponse<T> {
  status: "success" | "error";
  message: string;
  data: T;
}

// ---------------------------------------------------------------------------
// Typed error
//
// Callers branch on `httpStatus`:
//   400 — bad input (envelope status:"error" also lands here)
//   403 — not allowed (caller isn't owner/admin, invite email mismatch)
//   404 — not found (unknown team, sub/username resolution failed)
//   409 — conflict (already owned a team, invite not pending, etc.)
//   502 — teams service unreachable (safe to retry)
//   0   — network / non-HTTP failure
// ---------------------------------------------------------------------------

export class TeamError extends Error {
  readonly httpStatus: number;

  constructor(message: string, httpStatus: number) {
    super(message);
    this.name = "TeamError";
    this.httpStatus = httpStatus;
  }
}
