import type React from "react";
import { useCallback, useRef, useState } from "react";

interface DropZoneHandlers {
  onDragEnter: (e: React.DragEvent<HTMLElement>) => void;
  onDragOver: (e: React.DragEvent<HTMLElement>) => void;
  onDragLeave: (e: React.DragEvent<HTMLElement>) => void;
  onDrop: (e: React.DragEvent<HTMLElement>) => void;
}

interface UseFileDropZoneReturn {
  /** True while a file drag hovers the zone — render the drop affordance. */
  isDragging: boolean;
  /** Spread onto the element that should accept drops. */
  dropZoneProps: DropZoneHandlers;
  /** Attach to the composer textarea to accept pasted screenshots. */
  handlePaste: (e: React.ClipboardEvent<HTMLElement>) => void;
}

const carriesFiles = (transfer: DataTransfer | null): boolean =>
  Array.from(transfer?.types ?? []).includes("Files");

// A screenshot pasted from the clipboard arrives as "image.png" for everyone,
// which collides in disk/ across users and turns. Give it a unique, readable
// name so the chip and the agent both have something to refer to.
const GENERIC_PASTE_NAMES = new Set(["", "image.png", "image.jpeg", "blob"]);

function withReadableName(file: File): File {
  if (!GENERIC_PASTE_NAMES.has(file.name)) return file;
  const extension = file.type.split("/")[1] || "png";
  const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-");
  return new File([file], `pasted-image-${stamp}.${extension}`, { type: file.type });
}

/**
 * Drag-and-drop plus clipboard-paste file intake for a chat composer. Both the
 * assistant panel and the Home chat share it through ChatInputBox, so files,
 * screenshots and images dragged from another app all land the same way.
 */
export function useFileDropZone(
  onFiles: (files: File[]) => void,
  disabled = false,
): UseFileDropZoneReturn {
  const [isDragging, setIsDragging] = useState(false);
  // dragenter/dragleave also fire for children; count depth so moving over the
  // textarea inside the zone doesn't flicker the affordance off.
  const depthRef = useRef(0);

  const handleDragEnter = useCallback(
    (e: React.DragEvent<HTMLElement>) => {
      if (disabled || !carriesFiles(e.dataTransfer)) return;
      e.preventDefault();
      depthRef.current += 1;
      setIsDragging(true);
    },
    [disabled],
  );

  const handleDragOver = useCallback(
    (e: React.DragEvent<HTMLElement>) => {
      if (disabled || !carriesFiles(e.dataTransfer)) return;
      // Without this the browser navigates to the dropped file.
      e.preventDefault();
      e.dataTransfer.dropEffect = "copy";
    },
    [disabled],
  );

  const handleDragLeave = useCallback((e: React.DragEvent<HTMLElement>) => {
    if (!carriesFiles(e.dataTransfer)) return;
    depthRef.current = Math.max(0, depthRef.current - 1);
    if (depthRef.current === 0) setIsDragging(false);
  }, []);

  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLElement>) => {
      if (disabled) return;
      e.preventDefault();
      depthRef.current = 0;
      setIsDragging(false);
      const files = Array.from(e.dataTransfer.files);
      if (files.length > 0) onFiles(files.map(withReadableName));
    },
    [disabled, onFiles],
  );

  const handlePaste = useCallback(
    (e: React.ClipboardEvent<HTMLElement>) => {
      if (disabled) return;
      const files = Array.from(e.clipboardData.files);
      if (files.length === 0) return;
      // Copied text that merely carries a file flavour keeps its default paste.
      e.preventDefault();
      onFiles(files.map(withReadableName));
    },
    [disabled, onFiles],
  );

  return {
    isDragging,
    dropZoneProps: {
      onDragEnter: handleDragEnter,
      onDragOver: handleDragOver,
      onDragLeave: handleDragLeave,
      onDrop: handleDrop,
    },
    handlePaste,
  };
}
