import { useQuery } from "@tanstack/react-query";

import { useAuth } from "@/features/auth/components/AuthProvider";

import { fetchOnboardingStatus, type OnboardingStatus } from "../api/onboardingStatusApi";

interface UseOnboardingStatusReturn {
  status: OnboardingStatus | null;
  isLoading: boolean;
  isError: boolean;
}

const STALE_MS = 60 * 1000;

export function useOnboardingStatus(enabled: boolean = true): UseOnboardingStatusReturn {
  const { user } = useAuth();
  const userId = user?.id ?? "";
  const query = useQuery({
    // Key by userId so a logout / different-user login doesn't reuse the
    // previous workspace's status while the staleTime is still warm.
    queryKey: ["onboarding-status", userId],
    queryFn: fetchOnboardingStatus,
    enabled: enabled && Boolean(userId),
    staleTime: STALE_MS,
    // Retry handles the small window where the auth provider has flipped
    // loading=false but HttpService is still settling. By the second
    // attempt (a few hundred ms later) the token is reliably attached.
    retry: 2,
    retryDelay: (attempt) => Math.min(300 * 2 ** attempt, 1500),
  });
  return {
    status: query.data ?? null,
    isLoading: query.isLoading,
    isError: query.isError,
  };
}
