import { FolderKanban, RefreshCw } from "lucide-react";
import { useState } from "react";
import type { ConceptData } from "@/features/concepts/api";
import type { OntologyData } from "@/features/ontologies/api";
import { useOntologies } from "@/features/ontologies/hooks/useOntologies";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/shared/components/ui/accordion";
import { Button } from "@/shared/components/ui/button";
import { IconChip } from "@/shared/components/ui/IconChip";
import { useOntologyConcepts } from "../../hooks/useOntologyConcepts";
import type { ConceptGraphRoles, GraphViewModel } from "../../types";
import { OntologyConceptCard } from "./OntologyConceptCard";

interface OntologiesPanelProps {
  activeOntologyId: string | null;
  scope: string;
  model: GraphViewModel | null;
  activeGraphPredicate: string | null;
  isGraphBusy: boolean;
  /** Predicate to scroll into view and expand (deep-link "pick your roles" flow). */
  focusPredicate?: string | null;
  onSelectOntology: (project: OntologyData | null) => void;
  onRolesChange: (predicate: string, roles: ConceptGraphRoles) => void;
  onShowGraph: (concept: ConceptData, runPredicate?: string) => void;
}

export function OntologiesPanel({
  activeOntologyId,
  scope,
  model,
  activeGraphPredicate,
  isGraphBusy,
  focusPredicate,
  onSelectOntology,
  onRolesChange,
  onShowGraph,
}: OntologiesPanelProps) {
  const { projects, isLoading: isLoadingOntologies, loadOntologies } = useOntologies();
  const [openOntologyId, setOpenOntologyId] = useState<string | null>(activeOntologyId);
  const openableOntologies = projects.filter((project) => project.shareStatus !== "pending");

  const { concepts, isLoading: isLoadingConcepts } = useOntologyConcepts(
    openOntologyId,
    scope,
    Boolean(openOntologyId),
  );

  const handleAccordionChange = (value: string) => {
    setOpenOntologyId(value || null);
    if (!value) return;
    const project = openableOntologies.find((candidate) => candidate.id === value);
    if (project) onSelectOntology(project);
  };

  const handleRefresh = () => {
    void loadOntologies(true);
  };

  const renderConcepts = () => {
    if (isLoadingConcepts) {
      return <p className="px-3 py-2 text-xs text-muted-foreground">Loading concepts…</p>;
    }
    if (concepts.length === 0) {
      return (
        <p className="px-3 py-2 text-xs text-muted-foreground">No concepts in this ontology.</p>
      );
    }
    return (
      <div className="space-y-1.5 border-t border-border bg-muted/40 px-2 py-2">
        {concepts.map((concept) => (
          <OntologyConceptCard
            key={concept.predicate_name}
            concept={concept}
            model={model}
            activeGraphPredicate={activeGraphPredicate}
            isGraphBusy={isGraphBusy}
            isFocused={concept.predicate_name === focusPredicate}
            onRolesChange={onRolesChange}
            onShowGraph={onShowGraph}
          />
        ))}
      </div>
    );
  };

  const renderBody = () => {
    if (isLoadingOntologies && openableOntologies.length === 0) {
      return <p className="p-4 text-center text-xs text-muted-foreground">Loading ontologies…</p>;
    }
    if (openableOntologies.length === 0) {
      return (
        <p className="p-4 text-center text-xs text-muted-foreground">
          No ontologies yet. Create one from the Ontologies page.
        </p>
      );
    }
    return (
      <Accordion
        type="single"
        collapsible
        className="space-y-2"
        value={openOntologyId ?? ""}
        onValueChange={handleAccordionChange}
      >
        {openableOntologies.map((project) => (
          <AccordionItem
            key={project.id}
            value={project.id}
            className="overflow-hidden rounded-lg border border-border bg-card shadow-card transition-colors hover:border-foreground/20 data-[state=open]:border-foreground/15"
          >
            <AccordionTrigger className="px-3 py-2.5 hover:bg-accent/40 hover:no-underline data-[state=open]:bg-accent/30">
              <div className="flex items-center gap-2.5 flex-1 min-w-0">
                <IconChip icon={FolderKanban} size="sm" />
                <div className="flex flex-col items-start flex-1 min-w-0">
                  <span className="font-medium text-sm truncate max-w-full">
                    {project.name ?? project.id}
                  </span>
                  <span className="text-[11px] capitalize text-muted-foreground">
                    {project.scope}
                  </span>
                </div>
              </div>
            </AccordionTrigger>
            <AccordionContent className="px-0 pb-1 pt-0">
              {project.id === openOntologyId && renderConcepts()}
            </AccordionContent>
          </AccordionItem>
        ))}
      </Accordion>
    );
  };

  return (
    <div
      className="h-full bg-background border-r border-border flex flex-col flex-shrink-0"
      style={{ width: "330px", maxWidth: "330px" }}
    >
      <div className="h-10 flex items-center gap-2 px-3 border-b border-border flex-shrink-0">
        <h2 className="text-sm font-medium text-foreground flex-1">Ontologies</h2>
        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={handleRefresh}
          disabled={isLoadingOntologies}
          title="Refresh ontologies"
        >
          <RefreshCw className={`h-3.5 w-3.5 ${isLoadingOntologies ? "animate-spin" : ""}`} />
        </Button>
      </div>

      <div
        className="flex-1 min-h-0 overflow-y-auto pl-2 pr-2 pb-4 pt-2"
        style={{ scrollbarGutter: "stable" }}
      >
        {renderBody()}
      </div>
    </div>
  );
}
