import { useParams } from "react-router-dom";

/**
 * The ontology id implied by the current route, or null.
 *  - /editor/:id and /editor/:organization/:username/:id → params.id
 *  - /apps/:ontologyId/:id                                → params.ontologyId
 * Anywhere else (projects list, context page, settings, …) there is no active
 * ontology, so global search falls back to global-scope context only.
 */
export function useActiveOntologyId(): string | null {
  const params = useParams();
  return params.ontologyId ?? params.id ?? null;
}
