import { useMemo } from "react";
import { Cell, Legend, Pie, PieChart, ResponsiveContainer, Tooltip } from "recharts";
import type { FetchResult } from "../../api/ConceptClient";

const COLORS = [
  "#6366f1",
  "#8b5cf6",
  "#06b6d4",
  "#10b981",
  "#f59e0b",
  "#ef4444",
  "#ec4899",
  "#14b8a6",
];

interface PieChartOutputProps {
  data: FetchResult;
  xCol: number; // label column
  yCol: number; // value column
  fullscreen?: boolean;
}

export function PieChartOutput({ data, xCol, yCol, fullscreen = false }: PieChartOutputProps) {
  const chartData = useMemo(
    () =>
      data.rows
        .map((row) => ({
          name: row[xCol] !== null && row[xCol] !== undefined ? String(row[xCol]) : "—",
          value: Number(row[yCol]) || 0,
        }))
        .filter((d) => d.value > 0),
    [data.rows, xCol, yCol],
  );

  if (chartData.length === 0) {
    return <p className="text-xs text-muted-foreground py-4">No data</p>;
  }

  const total = chartData.reduce((s, d) => s + d.value, 0);

  const renderLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
    if (percent < 0.04) return null;
    const RADIAN = Math.PI / 180;
    const r = innerRadius + (outerRadius - innerRadius) * 0.5;
    const x = cx + r * Math.cos(-midAngle * RADIAN);
    const y = cy + r * Math.sin(-midAngle * RADIAN);
    return (
      <text x={x} y={y} fill="white" textAnchor="middle" dominantBaseline="central" fontSize={11}>
        {`${(percent * 100).toFixed(0)}%`}
      </text>
    );
  };

  return (
    <ResponsiveContainer width="100%" height={fullscreen ? "100%" : 280}>
      <PieChart>
        <Pie
          data={chartData}
          cx="50%"
          cy="50%"
          outerRadius={110}
          dataKey="value"
          labelLine={false}
          label={renderLabel}
        >
          {chartData.map((_, i) => (
            <Cell key={i} fill={COLORS[i % COLORS.length]} />
          ))}
        </Pie>
        <Tooltip
          formatter={(value: number) => [`${value} (${((value / total) * 100).toFixed(1)}%)`, ""]}
          contentStyle={{ fontSize: 12, borderRadius: 6 }}
        />
        <Legend wrapperStyle={{ fontSize: 12 }} />
      </PieChart>
    </ResponsiveContainer>
  );
}
