import { useCallback, useRef, useState } from "react";
import { toast } from "sonner";
import type { MfaEnrollment, UseMfaReturn } from "@/features/auth/hooks/useMfa";

type EnrollmentStep = "idle" | "scan" | "verify" | "recovery";

interface EnrollmentState {
  step: EnrollmentStep;
  enrollment: MfaEnrollment | null;
  recoveryCodes: string[];
  isBusy: boolean;
  errorMessage: string | null;
}

const INITIAL_STATE: EnrollmentState = {
  step: "idle",
  enrollment: null,
  recoveryCodes: [],
  isBusy: false,
  errorMessage: null,
};

export interface UseMfaEnrollmentReturn extends EnrollmentState {
  hasVerifiedFactor: boolean;
  startEnrollment: () => Promise<void>;
  verifyCode: (code: string) => Promise<void>;
  cancel: () => Promise<void>;
  disableMfa: () => Promise<void>;
  finishRecoveryStep: () => void;
}

export function useMfaEnrollment(mfa: UseMfaReturn): UseMfaEnrollmentReturn {
  const {
    verifiedFactor,
    enrollTotp,
    verifyEnrollment,
    cancelEnrollment,
    unenroll,
    issueRecoveryCodes,
  } = mfa;

  const [state, setState] = useState<EnrollmentState>(INITIAL_STATE);
  const pendingFactorIdRef = useRef<string | null>(null);

  const patchState = useCallback((patch: Partial<EnrollmentState>) => {
    setState((prev) => ({ ...prev, ...patch }));
  }, []);

  const startEnrollment = useCallback(async () => {
    patchState({ isBusy: true, errorMessage: null });
    try {
      const enrollment = await enrollTotp();
      pendingFactorIdRef.current = enrollment.factorId;
      patchState({ step: "scan", enrollment, isBusy: false });
    } catch (err: unknown) {
      patchState({
        isBusy: false,
        errorMessage: err instanceof Error ? err.message : "Failed to start enrollment",
      });
    }
  }, [enrollTotp, patchState]);

  const verifyCode = useCallback(
    async (code: string) => {
      if (!pendingFactorIdRef.current) {
        patchState({ errorMessage: "No enrollment in progress" });
        return;
      }
      patchState({ isBusy: true, errorMessage: null });
      try {
        await verifyEnrollment(pendingFactorIdRef.current, code);
        const codes = await issueRecoveryCodes();
        patchState({ step: "recovery", recoveryCodes: codes, isBusy: false });
        toast.success("Two-factor authentication enabled");
      } catch (err: unknown) {
        patchState({
          isBusy: false,
          errorMessage: err instanceof Error ? err.message : "Invalid code. Please try again.",
        });
      }
    },
    [issueRecoveryCodes, verifyEnrollment, patchState],
  );

  const cancel = useCallback(async () => {
    const factorId = pendingFactorIdRef.current;
    pendingFactorIdRef.current = null;
    if (factorId) {
      try {
        await cancelEnrollment(factorId);
      } catch {
        // Best-effort cleanup — the factor will stay unverified if this fails
        // but Supabase won't treat it as a verified MFA method.
      }
    }
    setState(INITIAL_STATE);
  }, [cancelEnrollment]);

  const disableMfa = useCallback(async () => {
    if (!verifiedFactor) return;
    patchState({ isBusy: true, errorMessage: null });
    try {
      await unenroll(verifiedFactor.id);
      toast.success("Two-factor authentication disabled");
      setState(INITIAL_STATE);
    } catch (err: unknown) {
      patchState({
        isBusy: false,
        errorMessage: err instanceof Error ? err.message : "Failed to disable MFA",
      });
    }
  }, [unenroll, verifiedFactor, patchState]);

  const finishRecoveryStep = useCallback(() => {
    pendingFactorIdRef.current = null;
    setState(INITIAL_STATE);
  }, []);

  return {
    ...state,
    hasVerifiedFactor: Boolean(verifiedFactor),
    startEnrollment,
    verifyCode,
    cancel,
    disableMfa,
    finishRecoveryStep,
  };
}
