import type React from "react";
import { Link, useNavigate } from "react-router-dom";
import { guardSidebarNavClick } from "@/features/engine-status/engineStatus";
import { cn } from "@/shared/lib/utils";

interface SidebarNavLinkProps {
  icon: React.ReactNode;
  label: string;
  to: string;
  onClick?: () => void;
  isActive?: boolean;
  collapsed: boolean;
}

export function SidebarNavLink({
  icon,
  label,
  to,
  onClick,
  isActive = false,
  collapsed,
}: SidebarNavLinkProps) {
  const navigate = useNavigate();

  const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    void guardSidebarNavClick(e, onClick ?? (() => navigate(to)));
  };

  return (
    <Link
      to={to}
      onClick={handleClick}
      title={collapsed ? label : undefined}
      className={cn(
        "flex h-9 w-full items-center gap-3 rounded-md px-2 text-sm font-medium text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
        isActive && "bg-primary/10 text-primary",
        collapsed && "justify-center px-0 mx-0",
      )}
    >
      {icon}
      {!collapsed && <span className="truncate">{label}</span>}
    </Link>
  );
}
