import type { FetchResult } from "../../api/ConceptClient";
import type { DashboardWidget } from "../../types";

const BAR_COLORS = [
  "#2563eb",
  "#ea580c",
  "#0891b2",
  "#7c3aed",
  "#16a34a",
  "#d97706",
  "#dc2626",
  "#ec4899",
];

interface BarListWidgetProps {
  data: FetchResult;
  widget: DashboardWidget;
}

export function BarListWidget({ data, widget }: BarListWidgetProps) {
  const items = data.rows.map((row) => ({
    name: row[widget.xCol] != null ? String(row[widget.xCol]) : "—",
    value: Number(row[widget.yCol]) || 0,
  }));

  if (items.length === 0) {
    return <p className="text-xs text-muted-foreground py-4">No data</p>;
  }

  const max = Math.max(...items.map((i) => i.value), 1);

  return (
    <div className="flex flex-col gap-3">
      {items.map((item, i) => {
        const pct = Math.round((item.value / max) * 100);
        const color = BAR_COLORS[i % BAR_COLORS.length];
        return (
          <div key={i} className="flex flex-col gap-1.5">
            <div className="flex items-center justify-between text-[12px]">
              <span className="font-semibold text-foreground truncate max-w-[60%]">
                {item.name}
              </span>
              <span className="text-muted-foreground font-mono tabular-nums">
                {item.value.toLocaleString()}
              </span>
            </div>
            <div className="h-[5px] w-full rounded-full bg-secondary overflow-hidden border border-border/40">
              <div
                className="h-full rounded-full transition-all duration-700"
                style={{ width: `${pct}%`, backgroundColor: color }}
              />
            </div>
          </div>
        );
      })}
    </div>
  );
}
