import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

/**
 * A named LLM connection: a self-contained provider/model/credential target an
 * llm concept can pin via `concept_config.connection`. Field names match the
 * `llm` block so the backend resolver can use one as a drop-in base.
 */
export interface LlmConnectionSettings {
  llm_provider?: string;
  llm_version?: string;
  llm_api_key?: string;
  azure_llm_endpoint?: string;
  azure_llm_api_version?: string;
  databricks_workspace_url?: string;
  databricks_client_id?: string;
  databricks_client_secret?: string;
  snowflake_account_url?: string;
}

export interface UserConfig {
  llm?: {
    llm_provider?: string;
    llm_version?: string;
    llm_temperature?: number;
    llm_max_tokens?: number;
    llm_api_key?: string;
    azure_llm_endpoint?: string;
    azure_llm_api_version?: string;
    databricks_workspace_url?: string;
    databricks_client_id?: string;
    databricks_client_secret?: string;
    snowflake_account_url?: string;
  };
  llm_connections?: Record<string, LlmConnectionSettings>;
  embedding?: {
    embedding_provider?: string;
    embedding_version?: string;
    embedding_dimensions?: number;
    embedding_api_key?: string;
    azure_embedding_endpoint?: string;
    azure_embedding_api_version?: string;
  };
}

export interface ConfigResponse {
  status: string;
  message: string;
  data?: UserConfig;
}

/** Data-privacy terms for an Anthropic "Covered Model" (30-day retention, no ZDR). */
export interface CoveredModelInfo {
  retention_days: number;
  zdr_available: boolean;
  note: string;
}

/** Result of listing models: the option ids plus per-model covered-model metadata. */
export interface ModelsResult {
  models: string[];
  coveredModels: Record<string, CoveredModelInfo>;
  /** Which of `models` accept images, so the UI can warn before a turn is spent. */
  visionModels: string[];
}

/**
 * Resolved non-secret LLM defaults from /users/llm-defaults: what an LLM call
 * runs with when nothing is overridden (user settings merged over app
 * defaults; no keys or endpoints).
 */
export interface LlmDefaults {
  provider: string;
  model: string;
  temperature: number;
  /** Max-tokens default applied to llm concepts specifically. */
  conceptMaxTokens: number;
  /** Rows of each upstream a prompt carries before truncating. */
  conceptRowLimit: number;
  /** Default model per provider — what a provider override falls back to. */
  defaultVersions: Record<string, string>;
  /** Non-secret summaries of the user's saved LLM connections. */
  connections: LlmConnectionSummary[];
}

/** Non-secret summary of a saved LLM connection, as listed by /users/llm-defaults. */
export interface LlmConnectionSummary {
  name: string;
  provider?: string;
  model?: string;
}

interface LlmDefaultsPayload {
  llm_provider?: string;
  llm_version?: string;
  llm_temperature?: number;
  llm_concept_max_tokens?: number;
  llm_concept_row_limit?: number;
  default_versions?: Record<string, string>;
  connections?: unknown;
}

function parseConnectionSummaries(raw: unknown): LlmConnectionSummary[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .filter(
      (entry): entry is { name: string; provider?: string; model?: string } =>
        typeof entry === "object" &&
        entry !== null &&
        typeof (entry as { name?: unknown }).name === "string",
    )
    .map((entry) => ({ name: entry.name, provider: entry.provider, model: entry.model }));
}

function isCoveredModelInfo(value: unknown): value is CoveredModelInfo {
  return (
    typeof value === "object" &&
    value !== null &&
    "retention_days" in value &&
    "zdr_available" in value &&
    "note" in value
  );
}

function parseVisionModels(raw: unknown): string[] {
  if (!Array.isArray(raw)) return [];
  return raw.filter((entry): entry is string => typeof entry === "string");
}

function parseCoveredModels(raw: unknown): Record<string, CoveredModelInfo> {
  if (typeof raw !== "object" || raw === null) return {};
  return Object.entries(raw).reduce<Record<string, CoveredModelInfo>>((acc, [key, value]) => {
    if (isCoveredModelInfo(value)) acc[key] = value;
    return acc;
  }, {});
}

export class ConfigService {
  /**
   * Save user configuration to backend
   */
  static async saveUserConfig(config: UserConfig, scope: string = "user"): Promise<void> {
    const payload = {
      config_data: config,
      scope: scope,
    };

    const response = (await HttpService.post(
      `${PROMETHEUX_CONFIG.BASE_URL}/users/save-config`,
      payload,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
    )) as ConfigResponse;

    if (response.status !== "success") {
      throw new Error(response.message || "Failed to save configuration");
    }
  }

  /**
   * Create or update one named LLM connection.
   *
   * Not `saveUserConfig({ llm_connections })`: that replaces the whole map, so a
   * map built from an earlier read drops connections saved since. The backend
   * reads and merges immediately before writing. Secret fields left out keep
   * their stored value, which is how an edit form saves without ever being told
   * the current key.
   */
  static async upsertLlmConnection(
    name: string,
    settings: LlmConnectionSettings,
    scope: string = "user",
  ): Promise<LlmConnectionSummary> {
    const response = (await HttpService.post(
      `${PROMETHEUX_CONFIG.BASE_URL}/users/llm-connection`,
      { name, settings, scope },
      PROMETHEUX_CONFIG.AUTH_TOKEN,
    )) as { status: string; message?: string; data?: unknown };

    if (response.status !== "success") {
      throw new Error(response.message || "Failed to save the LLM connection");
    }
    const [summary] = parseConnectionSummaries([response.data]);
    return summary ?? { name };
  }

  /** Remove one named LLM connection, leaving the others alone. */
  static async deleteLlmConnection(name: string, scope: string = "user"): Promise<void> {
    const url = `${PROMETHEUX_CONFIG.BASE_URL}/users/llm-connection/${encodeURIComponent(name)}?scope=${scope}`;
    const response = (await HttpService.delete(url, undefined, PROMETHEUX_CONFIG.AUTH_TOKEN)) as {
      status: string;
      message?: string;
    };

    if (response.status !== "success") {
      throw new Error(response.message || "Failed to remove the LLM connection");
    }
  }

  /**
   * Load user configuration from backend
   */
  static async loadUserConfig(scope: string = "user"): Promise<UserConfig | null> {
    try {
      // Create query parameters for scope
      const url = `${PROMETHEUX_CONFIG.BASE_URL}/users/load-config?scope=${scope}`;

      const response = (await HttpService.get(url, PROMETHEUX_CONFIG.AUTH_TOKEN)) as ConfigResponse;

      if (response.status === "success" && response.data) {
        return response.data;
      }

      return null;
    } catch (_error) {
      // Don't throw error for loading - just return null to use defaults
      return null;
    }
  }

  /**
   * Apply loaded config to PROMETHEUX_CONFIG
   */
  static applyConfigToGlobal(config: UserConfig): void {
    // Apply LLM config
    if (config.llm) {
      if (config.llm.llm_provider !== undefined) {
        PROMETHEUX_CONFIG.CHAT.LLM_PROVIDER = config.llm.llm_provider;
      }
      if (config.llm.llm_version !== undefined) {
        PROMETHEUX_CONFIG.CHAT.MODEL_VERSION = config.llm.llm_version;
      }
      if (config.llm.llm_temperature !== undefined) {
        PROMETHEUX_CONFIG.CHAT.TEMPERATURE = config.llm.llm_temperature;
      }
      if (config.llm.llm_max_tokens !== undefined) {
        PROMETHEUX_CONFIG.CHAT.MAX_TOKENS = config.llm.llm_max_tokens;
      }
      if (config.llm.llm_api_key !== undefined) {
        PROMETHEUX_CONFIG.LLM_API_KEY = config.llm.llm_api_key;
      }
      if (config.llm.azure_llm_endpoint !== undefined) {
        PROMETHEUX_CONFIG.CHAT.AZURE_LLM_ENDPOINT = config.llm.azure_llm_endpoint;
      }
      if (config.llm.azure_llm_api_version !== undefined) {
        PROMETHEUX_CONFIG.CHAT.AZURE_LLM_API_VERSION = config.llm.azure_llm_api_version;
      }
      if (config.llm.databricks_workspace_url !== undefined) {
        PROMETHEUX_CONFIG.CHAT.DATABRICKS_WORKSPACE_URL = config.llm.databricks_workspace_url;
      }
      if (config.llm.databricks_client_id !== undefined) {
        PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_ID = config.llm.databricks_client_id;
      }
      if (config.llm.databricks_client_secret !== undefined) {
        PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_SECRET = config.llm.databricks_client_secret;
      }
      if (config.llm.snowflake_account_url !== undefined) {
        PROMETHEUX_CONFIG.CHAT.SNOWFLAKE_ACCOUNT_URL = config.llm.snowflake_account_url;
      }
    }

    // Apply embedding config
    if (config.embedding) {
      if (config.embedding.embedding_provider !== undefined) {
        PROMETHEUX_CONFIG.EMBEDDING.EMBEDDING_PROVIDER = config.embedding.embedding_provider;
      }
      if (config.embedding.embedding_version !== undefined) {
        PROMETHEUX_CONFIG.EMBEDDING.MODEL_VERSION = config.embedding.embedding_version;
      }
      if (config.embedding.embedding_dimensions !== undefined) {
        PROMETHEUX_CONFIG.EMBEDDING.DIMENSIONS = config.embedding.embedding_dimensions;
      }
      if (config.embedding.embedding_api_key !== undefined) {
        PROMETHEUX_CONFIG.EMBEDDING_API_KEY = config.embedding.embedding_api_key;
      }
      if (config.embedding.azure_embedding_endpoint !== undefined) {
        PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_ENDPOINT =
          config.embedding.azure_embedding_endpoint;
      }
      if (config.embedding.azure_embedding_api_version !== undefined) {
        PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_API_VERSION =
          config.embedding.azure_embedding_api_version;
      }
    }
  }

  /**
   * Fetch available models for a given LLM provider.
   * Pass provider-specific credentials so the backend can reach the remote API.
   */
  static async listModels(
    provider: string,
    extraConfig?: Record<string, string>,
  ): Promise<ModelsResult> {
    const empty: ModelsResult = { models: [], coveredModels: {}, visionModels: [] };
    try {
      const url = `${PROMETHEUX_CONFIG.BASE_URL}/users/llm-models`;
      const body: Record<string, string> = { provider, ...extraConfig };
      const response = (await HttpService.post(url, body, PROMETHEUX_CONFIG.AUTH_TOKEN)) as {
        status: string;
        data?: { models?: string[]; covered_models?: unknown; vision_models?: unknown };
      };
      if (response.status === "success" && response.data?.models) {
        return {
          models: response.data.models,
          coveredModels: parseCoveredModels(response.data.covered_models),
          visionModels: parseVisionModels(response.data.vision_models),
        };
      }
      return empty;
    } catch (_error) {
      return empty;
    }
  }

  /**
   * Fetch the resolved non-secret LLM defaults (effective provider, model,
   * temperature, and the llm-concept max-tokens default).
   */
  static async getLlmDefaults(): Promise<LlmDefaults | null> {
    try {
      const url = `${PROMETHEUX_CONFIG.BASE_URL}/users/llm-defaults`;
      const response = (await HttpService.get(url, PROMETHEUX_CONFIG.AUTH_TOKEN)) as {
        status: string;
        data?: LlmDefaultsPayload;
      };
      if (response.status !== "success" || !response.data) return null;
      const payload = response.data;
      if (!payload.llm_provider || !payload.llm_version) return null;
      return {
        provider: payload.llm_provider,
        model: payload.llm_version,
        temperature: payload.llm_temperature ?? 0.3,
        conceptMaxTokens: payload.llm_concept_max_tokens ?? 4096,
        conceptRowLimit: payload.llm_concept_row_limit ?? 100,
        defaultVersions: payload.default_versions ?? {},
        connections: parseConnectionSummaries(payload.connections),
      };
    } catch (_error) {
      return null;
    }
  }

  /**
   * Get current config from PROMETHEUX_CONFIG
   */
  static getCurrentConfig(): UserConfig {
    return {
      llm: {
        llm_provider: PROMETHEUX_CONFIG.CHAT.LLM_PROVIDER,
        llm_version: PROMETHEUX_CONFIG.CHAT.MODEL_VERSION,
        llm_temperature: PROMETHEUX_CONFIG.CHAT.TEMPERATURE,
        llm_max_tokens: PROMETHEUX_CONFIG.CHAT.MAX_TOKENS,
        llm_api_key: PROMETHEUX_CONFIG.LLM_API_KEY,
        azure_llm_endpoint: PROMETHEUX_CONFIG.CHAT.AZURE_LLM_ENDPOINT,
        azure_llm_api_version: PROMETHEUX_CONFIG.CHAT.AZURE_LLM_API_VERSION,
        databricks_workspace_url: PROMETHEUX_CONFIG.CHAT.DATABRICKS_WORKSPACE_URL,
        databricks_client_id: PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_ID,
        databricks_client_secret: PROMETHEUX_CONFIG.CHAT.DATABRICKS_CLIENT_SECRET,
        snowflake_account_url: PROMETHEUX_CONFIG.CHAT.SNOWFLAKE_ACCOUNT_URL,
      },
      embedding: {
        embedding_provider: PROMETHEUX_CONFIG.EMBEDDING.EMBEDDING_PROVIDER,
        embedding_version: PROMETHEUX_CONFIG.EMBEDDING.MODEL_VERSION,
        embedding_dimensions: PROMETHEUX_CONFIG.EMBEDDING.DIMENSIONS,
        embedding_api_key: PROMETHEUX_CONFIG.EMBEDDING_API_KEY,
        azure_embedding_endpoint: PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_ENDPOINT,
        azure_embedding_api_version: PROMETHEUX_CONFIG.EMBEDDING.AZURE_EMBEDDING_API_VERSION,
      },
    };
  }
}
