import { useCallback, useEffect, useRef, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";

export interface UnsavedChangesWarningOptions {
  hasUnsavedChanges: boolean;
  onSaveChanges: () => Promise<boolean>;
  onShowSaveDialog: () => void;
}

/**
 * Enhanced hook to warn users about unsaved changes when navigating away
 * Handles both browser navigation (refresh, close) and React Router navigation
 */
export function useUnsavedChangesWarning({
  hasUnsavedChanges,
  onSaveChanges,
  onShowSaveDialog,
}: UnsavedChangesWarningOptions) {
  const navigate = useNavigate();
  const location = useLocation();
  const [pendingNavigation, setPendingNavigation] = useState<string | null>(null);
  const [isNavigationBlocked, setIsNavigationBlocked] = useState(false);
  const previousLocationRef = useRef(location.pathname);
  const isNavigatingRef = useRef(false);

  // Handle browser close/refresh with beforeunload event
  useEffect(() => {
    const handleBeforeUnload = (event: BeforeUnloadEvent) => {
      if (hasUnsavedChanges && !isNavigatingRef.current) {
        // Modern browsers require preventDefault and returnValue
        event.preventDefault();
        const message = "You have unsaved changes. Are you sure you want to leave?";
        event.returnValue = message;
        return message;
      }
    };

    if (hasUnsavedChanges) {
      window.addEventListener("beforeunload", handleBeforeUnload, { capture: true });
      return () =>
        window.removeEventListener("beforeunload", handleBeforeUnload, { capture: true });
    }
  }, [hasUnsavedChanges]);

  // Enhanced navigation interception using popstate for back/forward buttons
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
      if (hasUnsavedChanges && !isNavigatingRef.current) {
        // Prevent navigation by pushing the current state back
        event.preventDefault();
        window.history.pushState(null, "", previousLocationRef.current);

        // Show save dialog
        setPendingNavigation(location.pathname);
        setIsNavigationBlocked(true);
        onShowSaveDialog();
      }
    };

    if (hasUnsavedChanges) {
      // Push current state to enable interception
      window.history.pushState(null, "", location.pathname);
      window.addEventListener("popstate", handlePopState);

      return () => {
        window.removeEventListener("popstate", handlePopState);
      };
    }
  }, [hasUnsavedChanges, location.pathname, onShowSaveDialog]);

  // Track location changes to update previous location reference
  useEffect(() => {
    if (!isNavigatingRef.current) {
      previousLocationRef.current = location.pathname;
    }
  }, [location.pathname]);

  // Custom navigate function that checks for unsaved changes
  const navigateWithCheck = useCallback(
    (to: string) => {
      if (hasUnsavedChanges && !isNavigatingRef.current) {
        setPendingNavigation(to);
        setIsNavigationBlocked(true);
        onShowSaveDialog();
        return false;
      } else {
        isNavigatingRef.current = true;
        navigate(to);
        // Reset flag after navigation
        setTimeout(() => {
          isNavigatingRef.current = false;
        }, 100);
        return true;
      }
    },
    [hasUnsavedChanges, navigate, onShowSaveDialog],
  );

  // Helper function to continue navigation after handling unsaved changes
  const confirmNavigation = useCallback(() => {
    if (pendingNavigation) {
      const target = pendingNavigation;
      setPendingNavigation(null);
      setIsNavigationBlocked(false);
      isNavigatingRef.current = true;

      // Navigate to the target location
      navigate(target);

      // Reset navigation flag after a short delay
      setTimeout(() => {
        isNavigatingRef.current = false;
      }, 100);
    }
  }, [navigate, pendingNavigation]);

  // Helper function to cancel navigation and reset state
  const cancelNavigation = useCallback(() => {
    setPendingNavigation(null);
    setIsNavigationBlocked(false);
  }, []);

  // Force navigation without checks (for use after saving)
  const forceNavigate = useCallback(
    (to: string) => {
      isNavigatingRef.current = true;
      navigate(to);
      setTimeout(() => {
        isNavigatingRef.current = false;
      }, 100);
    },
    [navigate],
  );

  return {
    showPrompt: isNavigationBlocked,
    confirmNavigation,
    cancelNavigation,
    navigateWithCheck,
    forceNavigate,
    pendingNavigation,
  };
}

/**
 * Global registry for unsaved changes checkers
 * This allows any component to register itself as having unsaved changes
 */
interface UnsavedChangesChecker {
  id: string;
  hasUnsavedChanges: () => boolean;
  saveChanges: () => Promise<boolean>;
  showSaveDialog: () => void;
}

const unsavedChangesRegistry: Map<string, UnsavedChangesChecker> = new Map();

export const registerUnsavedChangesChecker = (checker: UnsavedChangesChecker) => {
  unsavedChangesRegistry.set(checker.id, checker);

  return () => {
    unsavedChangesRegistry.delete(checker.id);
  };
};

export const checkForUnsavedChanges = (): Promise<boolean> => {
  return new Promise((resolve) => {
    const checkers = Array.from(unsavedChangesRegistry.values());
    const checkersWithUnsavedChanges = checkers.filter((checker) => checker.hasUnsavedChanges());

    if (checkersWithUnsavedChanges.length === 0) {
      resolve(true); // No unsaved changes, proceed
      return;
    }

    // For now, just trigger the first checker's save dialog
    // In a more complex app, you might want to show a list of all components with unsaved changes
    const firstChecker = checkersWithUnsavedChanges[0];
    firstChecker.showSaveDialog();

    // Return false to indicate navigation should be blocked
    resolve(false);
  });
};

/**
 * Custom hook that wraps navigate to check for unsaved changes globally
 */
export const useSafeNavigate = () => {
  const navigate = useNavigate();

  const safeNavigate = useCallback(
    async (to: string, options?: object) => {
      const canProceed = await checkForUnsavedChanges();
      if (canProceed) {
        navigate(to, options);
      }
      return canProceed;
    },
    [navigate],
  );

  return safeNavigate;
};
