/**
 * Generic, per-user localStorage cache factory.
 *
 * Replaces hand-rolled cache blocks that duplicate TTL + userId + version
 * validation. Stored envelope is opaque to the caller; `get()` returns the
 * typed payload (or null) and `set()`/`clear()` mutate atomically.
 *
 * Version is optional. When provided, entries whose stored `version` does not
 * match are treated as misses — use this to invalidate cached data after the
 * payload shape changes.
 */

interface CacheEnvelope<T> {
  data: T;
  userId: string;
  timestamp: number;
  version?: number;
}

export interface LocalCache<T> {
  get: (userId: string) => T | null;
  set: (userId: string, data: T) => void;
  clear: () => void;
}

export function createLocalCache<T>(key: string, ttlMs: number, version?: number): LocalCache<T> {
  const isExpired = (timestamp: number): boolean => Date.now() - timestamp > ttlMs;

  const get = (userId: string): T | null => {
    try {
      const raw = localStorage.getItem(key);
      if (!raw) return null;

      const envelope = JSON.parse(raw) as CacheEnvelope<T>;
      if (envelope.userId !== userId) return null;
      if (isExpired(envelope.timestamp)) return null;
      if (version !== undefined && envelope.version !== version) return null;

      return envelope.data;
    } catch (error) {
      console.error(`Error reading cache "${key}":`, error);
      return null;
    }
  };

  const set = (userId: string, data: T): void => {
    try {
      const envelope: CacheEnvelope<T> = {
        data,
        userId,
        timestamp: Date.now(),
        ...(version !== undefined ? { version } : {}),
      };
      localStorage.setItem(key, JSON.stringify(envelope));
    } catch (error) {
      console.error(`Error writing cache "${key}":`, error);
    }
  };

  const clear = (): void => {
    try {
      localStorage.removeItem(key);
    } catch (error) {
      console.error(`Error clearing cache "${key}":`, error);
    }
  };

  return { get, set, clear };
}
