import { GitCompare, History, Loader2, Lock, RefreshCw, X } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";
import { usePaidComputeEligibility } from "@/features/billing/hooks/usePaidComputeEligibility";
import { openUpgradeWallForCode } from "@/features/billing/store/upgradeWallStore";
import { FREEMIUM_LIMIT_CODES } from "@/features/billing/utils/freemiumLimit";
import {
  CURRENT_SNAPSHOT_SOURCE,
  type OntologyScope,
  type OntologySnapshotMeta,
} from "@/features/ontologies/api";
import { SnapshotConfirmDialogs } from "@/features/ontologies/snapshots/SnapshotConfirmDialogs";
import { SnapshotDiffDialog } from "@/features/ontologies/snapshots/SnapshotDiffDialog";
import { SnapshotItem } from "@/features/ontologies/snapshots/SnapshotItem";
import {
  CURRENT_SOURCE_LABEL,
  orderDiffPair,
  sourceLabel,
} from "@/features/ontologies/snapshots/snapshotCompare.utils";
import { useOntologySnapshots } from "@/features/ontologies/snapshots/useOntologySnapshots";
import { useSnapshotCompare } from "@/features/ontologies/snapshots/useSnapshotCompare";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/shared/components/ui/sheet";
import { cn } from "@/shared/lib/utils";

interface SnapshotsSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  ontologyId: string | null;
  scope: OntologyScope;
  onRestored: () => void;
}

export function SnapshotsSheet({
  open,
  onOpenChange,
  ontologyId,
  scope,
  onRestored,
}: SnapshotsSheetProps) {
  const {
    snapshots,
    isLoading,
    isFetching,
    isCreating,
    isRestoring,
    isDeleting,
    create,
    restore,
    remove,
    refresh,
  } = useOntologySnapshots(ontologyId, scope);

  const compare = useSnapshotCompare();

  const [description, setDescription] = useState("");
  const [confirmRestore, setConfirmRestore] = useState<OntologySnapshotMeta | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<OntologySnapshotMeta | null>(null);
  const [safetySnapshot, setSafetySnapshot] = useState(true);

  // Creating/restoring snapshots is a paid-only feature. Freemium accounts can
  // still view and delete existing snapshots, but the two mutating actions route
  // to the upgrade dialog. (The backend also enforces this with a 402 safety net.)
  const { isEligible } = usePaidComputeEligibility();
  const isFreemium = isEligible === false;

  const diffPair = orderDiffPair(compare.selected, snapshots);
  const baseLabel = diffPair ? sourceLabel(diffPair.baseSource, snapshots) : "";
  const targetLabel = diffPair ? sourceLabel(diffPair.targetSource, snapshots) : "";
  const isCurrentSelected = compare.selected.includes(CURRENT_SNAPSHOT_SOURCE);

  const handleCreate = async () => {
    if (isFreemium) {
      openUpgradeWallForCode(FREEMIUM_LIMIT_CODES.VERSIONING);
      return;
    }
    try {
      await create(description.trim() || undefined);
      setDescription("");
      toast.success("Snapshot created");
    } catch {
      toast.error("Failed to create snapshot");
    }
  };

  const handleRequestRestore = (snapshot: OntologySnapshotMeta) => {
    if (isFreemium) {
      openUpgradeWallForCode(FREEMIUM_LIMIT_CODES.VERSIONING);
      return;
    }
    setConfirmRestore(snapshot);
  };

  const handleRestore = async () => {
    if (!confirmRestore) return;
    try {
      await restore(confirmRestore.id, safetySnapshot);
      setConfirmRestore(null);
      toast.success("Ontology restored from snapshot");
      onRestored();
    } catch {
      toast.error("Failed to restore snapshot");
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete) return;
    try {
      await remove(confirmDelete.id);
      setConfirmDelete(null);
      toast.success("Snapshot deleted");
    } catch {
      toast.error("Failed to delete snapshot");
    }
  };

  const handleSelectCurrent = () => compare.toggleSelected(CURRENT_SNAPSHOT_SOURCE);

  const renderSaveButtonContent = () => {
    if (isCreating) return <Loader2 className="h-3.5 w-3.5 animate-spin" />;
    if (isFreemium) return <Lock className="h-3.5 w-3.5" />;
    return "Save";
  };

  return (
    <>
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent
          side="right"
          className="flex w-[380px] flex-col sm:max-w-[380px] [&>button.absolute]:hidden"
        >
          <SheetHeader>
            <div className="flex items-center justify-between">
              <SheetTitle className="flex items-center gap-2">
                <History className="h-4 w-4" />
                Project Versions
              </SheetTitle>
              <div className="flex items-center gap-1">
                <Button
                  type="button"
                  variant={compare.isComparing ? "secondary" : "ghost"}
                  size="iconSm"
                  onClick={compare.toggleComparing}
                  title="Compare versions"
                >
                  <GitCompare className="h-3.5 w-3.5" />
                </Button>
                <Button
                  type="button"
                  variant="ghost"
                  size="iconSm"
                  onClick={refresh}
                  disabled={isFetching}
                  title="Refresh snapshots"
                >
                  <RefreshCw className={cn("h-3.5 w-3.5", isFetching && "animate-spin")} />
                </Button>
                <SheetClose asChild>
                  <Button type="button" variant="ghost" size="iconSm" title="Close">
                    <X className="h-3.5 w-3.5" />
                  </Button>
                </SheetClose>
              </div>
            </div>
            <SheetDescription>
              {compare.isComparing
                ? "Select two versions to see how their concepts differ."
                : "Create and restore point-in-time snapshots of your ontology."}
            </SheetDescription>
          </SheetHeader>

          {!compare.isComparing && (
            <div className="mt-4 flex gap-2">
              <Input
                placeholder="Description (optional)"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") handleCreate();
                }}
                disabled={isCreating}
                className="flex-1"
              />
              <Button
                type="button"
                size="sm"
                onClick={handleCreate}
                disabled={isCreating || !ontologyId}
                title={
                  isFreemium
                    ? "Ontology versioning is a paid feature — upgrade to save snapshots"
                    : undefined
                }
              >
                {renderSaveButtonContent()}
              </Button>
            </div>
          )}

          <div className="mt-4 flex-1 overflow-y-auto">
            {isLoading && (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
              </div>
            )}

            {!isLoading && snapshots.length === 0 && (
              <p className="py-8 text-center text-sm text-muted-foreground">
                No snapshots yet. Create one to save the current state.
              </p>
            )}

            {!isLoading && (
              <div className="space-y-2">
                {compare.isComparing && (
                  <button
                    type="button"
                    onClick={handleSelectCurrent}
                    className={cn(
                      "flex w-full items-center gap-3 rounded-md border p-3 text-left transition-colors",
                      isCurrentSelected
                        ? "border-primary bg-primary/10"
                        : "border-border bg-card hover:bg-muted/50",
                    )}
                  >
                    <input
                      type="checkbox"
                      checked={isCurrentSelected}
                      readOnly
                      className="h-4 w-4 rounded border-border"
                    />
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-sm font-medium text-foreground">
                        {CURRENT_SOURCE_LABEL}
                      </p>
                      <p className="mt-0.5 text-xs text-muted-foreground">Working copy (live)</p>
                    </div>
                  </button>
                )}

                {snapshots.map((snapshot) => (
                  <SnapshotItem
                    key={snapshot.id}
                    snapshot={snapshot}
                    onRestore={() => handleRequestRestore(snapshot)}
                    onDelete={() => setConfirmDelete(snapshot)}
                    disabled={isRestoring || isDeleting}
                    restoreLocked={isFreemium}
                    isComparing={compare.isComparing}
                    isSelected={compare.selected.includes(snapshot.id)}
                    onToggleSelect={() => compare.toggleSelected(snapshot.id)}
                  />
                ))}
              </div>
            )}
          </div>

          {compare.isComparing && (
            <div className="mt-3 border-t border-border pt-3">
              <Button
                type="button"
                className="w-full"
                size="sm"
                onClick={compare.openDiff}
                disabled={!compare.canCompare}
              >
                {compare.canCompare ? "Compare selected" : "Select two versions"}
              </Button>
            </div>
          )}
        </SheetContent>
      </Sheet>

      <SnapshotDiffDialog
        open={compare.diffOpen && diffPair !== null}
        onOpenChange={compare.setDiffOpen}
        ontologyId={ontologyId}
        scope={scope}
        baseSource={diffPair?.baseSource ?? null}
        targetSource={diffPair?.targetSource ?? null}
        baseLabel={baseLabel}
        targetLabel={targetLabel}
      />

      <SnapshotConfirmDialogs
        confirmRestore={confirmRestore}
        confirmDelete={confirmDelete}
        safetySnapshot={safetySnapshot}
        isRestoring={isRestoring}
        isDeleting={isDeleting}
        onSafetySnapshotChange={setSafetySnapshot}
        onCancelRestore={() => setConfirmRestore(null)}
        onConfirmRestore={handleRestore}
        onCancelDelete={() => setConfirmDelete(null)}
        onConfirmDelete={handleDelete}
      />
    </>
  );
}
