import { HighlightStyle } from "@codemirror/language";
import { tags } from "@lezer/highlight";

/**
 * Vadalog Syntax Highlighting Color Palette
 *
 * Colors are driven by CSS variables defined in `shared/styles/base.css` under
 * `:root` (light) and `.dark` (dark), so the palette adapts automatically to the
 * active theme. Light mode keeps the original JupyterLab-style colors; dark mode
 * uses a VS Code / Cursor "Dark+" palette tuned for contrast on the dark editor
 * background. See the `--syntax-*` variables in base.css to adjust either theme.
 *
 * - Comments: italic (muted)
 * - Annotations (@input, @output, @bind): bold
 * - Variables (X, Y, Z)
 * - Atoms/Predicates (rule, fact)
 * - Strings / Numbers
 * - Punctuation: follows the active theme's foreground color
 */
export const customHighlightStyle = HighlightStyle.define([
  // Atoms/Predicates (lowercase identifiers)
  { tag: tags.keyword, color: "hsl(var(--syntax-keyword))" },

  // Variables (uppercase identifiers)
  { tag: tags.variableName, color: "hsl(var(--syntax-variable))" },

  // Punctuation - parentheses, commas, periods, brackets. Uses the theme's
  // foreground variable so it stays visible in both light and dark mode.
  { tag: tags.punctuation, color: "hsl(var(--foreground))" },

  // Comments - italic
  { tag: tags.comment, color: "hsl(var(--syntax-comment))", fontStyle: "italic" },

  // Strings
  { tag: tags.string, color: "hsl(var(--syntax-string))" },

  // Numbers (integers and doubles)
  { tag: tags.number, color: "hsl(var(--syntax-number))" },

  // Operators (:-, ->, <=, >=, !=, &&, ||, not, in) - bold
  { tag: tags.operator, color: "hsl(var(--syntax-operator))", fontWeight: "bold" },

  // Annotations (@input, @output, @bind) - bold
  { tag: tags.meta, color: "hsl(var(--syntax-annotation))", fontWeight: "bold" },

  // Skolem functions (#FUNC, #CC, #TC) and built-in/external functions
  { tag: tags.propertyName, color: "hsl(var(--syntax-function))" },
]);
