import { Loader2, Mail, X } from "lucide-react";
import type React from "react";
import { useCallback } from "react";
import { toast } from "sonner";
import { useTeamPendingInvitations } from "@/features/teams/hooks/useTeamPendingInvitations";
import type { TeamError, TeamPendingInvitation } from "@/features/teams/types";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";

interface TeamPendingInvitationsSectionProps {
  teamId: string;
}

// Team-side "Pending invitations" panel — the sender's outbox. Gated at the
// caller level (TeamRosterPanel only mounts this when the current user has
// capabilities.canInvite). Consumes the dedicated useTeamPendingInvitations
// hook so this component doesn't know about React Query or the API.
const TeamPendingInvitationsSection: React.FC<TeamPendingInvitationsSectionProps> = ({
  teamId,
}) => {
  const { invitations, isLoading, error, revoke, isRevoking, revokingInvitationId } =
    useTeamPendingInvitations(teamId);

  return (
    <section className="space-y-3">
      <div>
        <h3 className="text-sm font-semibold text-foreground">Pending invitations</h3>
        <p className="text-xs text-muted-foreground">
          {invitations.length === 0
            ? "No pending invitations"
            : `${invitations.length} awaiting response`}
        </p>
      </div>

      {isLoading ? (
        <div className="flex items-center gap-2 py-4 text-xs text-muted-foreground">
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
          Loading pending invitations...
        </div>
      ) : error ? (
        <div className="rounded-md border border-destructive/40 bg-destructive/[0.04] px-3 py-2 text-xs text-destructive">
          {error.message}
        </div>
      ) : invitations.length === 0 ? (
        <div className="flex flex-col items-center justify-center gap-2 rounded-md border border-dashed border-border bg-muted/30 px-3 py-6 text-center">
          <div className="flex h-9 w-9 items-center justify-center rounded-full bg-secondary">
            <Mail className="h-4 w-4 text-muted-foreground" />
          </div>
          <p className="text-xs text-muted-foreground">
            Invitations you send will appear here until they're accepted or declined.
          </p>
        </div>
      ) : (
        <div className="space-y-2">
          {invitations.map((invitation) => (
            <PendingInvitationRow
              key={invitation.id}
              invitation={invitation}
              onRevoke={revoke}
              isRevoking={isRevoking && revokingInvitationId === invitation.id}
            />
          ))}
        </div>
      )}
    </section>
  );
};

interface PendingInvitationRowProps {
  invitation: TeamPendingInvitation;
  onRevoke: (invitationId: string) => Promise<unknown>;
  isRevoking: boolean;
}

// Single pending invitation row. Layout mirrors TeamMemberRow so the two
// sections read as a family.
const PendingInvitationRow: React.FC<PendingInvitationRowProps> = ({
  invitation,
  onRevoke,
  isRevoking,
}) => {
  const handleRevoke = useCallback(async (): Promise<void> => {
    const confirmed = window.confirm(
      `Revoke the invitation for ${invitation.email}? They won't be able to accept it anymore.`,
    );
    if (!confirmed) return;
    try {
      await onRevoke(invitation.id);
      toast.success(`Revoked invitation for ${invitation.email}`);
    } catch (err) {
      const teamErr = err as TeamError;
      // 409 — already accepted/declined. The row should disappear on the next
      // refetch anyway (it's no longer pending) — point the admin at the right
      // tool for the actual state.
      if (teamErr.httpStatus === 409) {
        toast.error(teamErr.message || "This invitation is no longer pending.", {
          description: "If they already joined, remove them from the members list instead.",
        });
        return;
      }
      if (teamErr.httpStatus === 404) {
        toast.error("That invitation no longer exists.");
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to revoke invitation";
      toast.error(message);
    }
  }, [invitation.email, invitation.id, onRevoke]);

  return (
    <div className="flex items-start justify-between gap-3 rounded-md border border-border bg-card px-3 py-2.5">
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <Mail className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
          <span className="truncate text-sm font-medium text-foreground">{invitation.email}</span>
        </div>
        <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
          <Badge variant="outline" className="capitalize">
            {invitation.role}
          </Badge>
          <span>Invited by {invitation.invited_by}</span>
        </div>
      </div>
      <Button
        type="button"
        variant="ghost"
        size="sm"
        className="h-8 text-destructive hover:text-destructive"
        onClick={handleRevoke}
        disabled={isRevoking}
      >
        {isRevoking ? (
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
        ) : (
          <X className="h-3.5 w-3.5" />
        )}
        <span className="ml-1">Revoke</span>
      </Button>
    </div>
  );
};

export default TeamPendingInvitationsSection;
