import { useCurrentOntologyName, useOntologyId } from "@/features/ontologies/hooks/useOntologyId";

import { ContextWorkspace } from "./ContextWorkspace";
import type { VaultRef } from "./notesModel";

/**
 * In-project Context tab: the notes workspace scoped to the current project's
 * vault. Reuses ContextWorkspace (the same body the global Context page renders)
 * with only this project's vault, opened by default.
 */
export function OntologyContextTab() {
  const projectId = useOntologyId();
  const { ontologyName } = useCurrentOntologyName();

  if (!projectId) {
    return (
      <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
        Open a project to manage its context.
      </div>
    );
  }

  const projectVault: VaultRef = {
    scope: "ontology",
    scopeId: projectId,
    name: ontologyName ?? "Ontology",
  };

  return <ContextWorkspace projectVaults={[projectVault]} initialVault={projectVault} />;
}
