import { AlertTriangle, Trash2 } from "lucide-react";
import { useState } from "react";
import { InfoHint } from "@/shared/components/InfoHint";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import type { ContextActivation, ContextNote } from "../../types";
import { CONTEXT_ACTIVATION_LABELS } from "../../types";
import type { UseNoteActionsReturn } from "../hooks/useNoteActions";
import {
  collectFolderPaths,
  estimateTokens,
  formatRelativeTime,
  formatUsage,
  linkDisplayTitle,
  normalizeFolderPath,
} from "../notesModel";
import { NoteLinksSection } from "./NoteLinksSection";
import { NoteLocalGraph } from "./NoteLocalGraph";

/** Select sentinels — real folder paths are normalized and can't collide. */
const FOLDER_ROOT = "__root__";
const FOLDER_NEW = "__new__";

const ACTIVATION_OPTIONS: ContextActivation[] = ["retrieved", "always", "on_demand"];

const ACTIVATION_HELP: Record<ContextActivation, string> = {
  retrieved: "Looked up when relevant to your request.",
  always: "Injected into every request — this note becomes a Rule.",
  on_demand: "Its title is listed every request; the assistant fetches the body when needed.",
};

interface NoteInfoPanelProps {
  /** Remount with key={note.id} so the folder input resets on selection change. */
  note: ContextNote;
  linkCandidates: ContextNote[];
  actions: UseNoteActionsReturn;
  onOpenNote: (noteId: string) => void;
  onDeleted: () => void;
  /** Documents delete all their chunks instead of the single note. */
  deleteOverride?: () => void;
  deleteLabel?: string;
}

export function NoteInfoPanel({
  note,
  linkCandidates,
  actions,
  onOpenNote,
  onDeleted,
  deleteOverride,
  deleteLabel = "Delete note",
}: NoteInfoPanelProps) {
  const [folderInput, setFolderInput] = useState("");
  const [isAddingFolder, setIsAddingFolder] = useState(false);
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);

  const isRule = note.activation !== "retrieved";
  const currentFolder = normalizeFolderPath(note.folder_path);
  // Move destinations come from the note's own vault.
  const vaultFolders = collectFolderPaths(
    linkCandidates.filter(
      (candidate) => candidate.scope === note.scope && candidate.scope_id === note.scope_id,
    ),
  );

  const handleActivationChange = (value: string) => {
    actions.setActivation(note, value as ContextActivation);
  };

  const handleFolderSelect = (value: string) => {
    if (value === FOLDER_NEW) {
      setFolderInput("");
      setIsAddingFolder(true);
      return;
    }
    setIsAddingFolder(false);
    const destination = value === FOLDER_ROOT ? "" : value;
    if (destination !== currentFolder) actions.moveToFolder(note, destination);
  };

  const handleNewFolderCommit = () => {
    const destination = normalizeFolderPath(folderInput);
    setIsAddingFolder(false);
    if (destination && destination !== currentFolder) actions.moveToFolder(note, destination);
  };

  const handleConfirmDelete = () => {
    if (deleteOverride) deleteOverride();
    else actions.deleteNote(note.id);
    setIsConfirmingDelete(false);
    onDeleted();
  };

  return (
    <div className="flex h-full flex-col gap-4 overflow-y-auto p-4 text-sm">
      <section className="space-y-1.5">
        <div className="flex items-center gap-1.5">
          <Label htmlFor="note-activation">How it reaches the assistant</Label>
          <InfoHint label="How the retrieval modes work">
            <p>
              <span className="font-medium">Retrieved when relevant</span> — the note lives in the
              semantic pool; the assistant looks it up only when your request is related. This is
              the default and costs nothing when unused.
            </p>
            <p>
              <span className="font-medium">Always applied (Rule)</span> — injected verbatim into
              the assistant's instructions on every request. Strongest guarantee, but it costs
              tokens on every message.
            </p>
            <p>
              <span className="font-medium">On demand</span> — only the title is listed on every
              request; the assistant fetches the full text when it decides it's needed. Good for
              long playbooks.
            </p>
          </InfoHint>
        </div>
        <Select value={note.activation} onValueChange={handleActivationChange}>
          <SelectTrigger id="note-activation" className="w-full">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {ACTIVATION_OPTIONS.map((option) => (
              <SelectItem key={option} value={option}>
                {CONTEXT_ACTIVATION_LABELS[option]}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <p className="text-xs text-muted-foreground">{ACTIVATION_HELP[note.activation]}</p>
        {note.activation === "always" && (
          <p className="text-xs text-muted-foreground">
            Cost: ~{estimateTokens(note.text)} tokens added to every request.
          </p>
        )}
        {actions.screeningError && (
          <div className="flex items-start gap-2 rounded-md border border-destructive/40 bg-destructive/10 p-2 text-xs text-destructive">
            <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
            <span>{actions.screeningError}</span>
          </div>
        )}
        {isRule && !actions.screeningError && (
          <p className="text-xs text-muted-foreground">
            Rules are screened when created or edited — hostile or off-policy text is rejected.
          </p>
        )}
      </section>

      <section className="space-y-1.5">
        <Label htmlFor="note-folder">Folder</Label>
        <Select
          value={isAddingFolder ? FOLDER_NEW : currentFolder || FOLDER_ROOT}
          onValueChange={handleFolderSelect}
        >
          <SelectTrigger id="note-folder" className="w-full">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value={FOLDER_ROOT}>Vault root</SelectItem>
            {vaultFolders.map((folder) => (
              <SelectItem key={folder} value={folder}>
                {folder}
              </SelectItem>
            ))}
            <SelectItem value={FOLDER_NEW}>New folder…</SelectItem>
          </SelectContent>
        </Select>
        {isAddingFolder && (
          <Input
            value={folderInput}
            onChange={(e) => setFolderInput(e.target.value)}
            onBlur={handleNewFolderCommit}
            onKeyDown={(e) => {
              if (e.key === "Enter") handleNewFolderCommit();
            }}
            placeholder="e.g. research/interviews"
            autoFocus
          />
        )}
        <p className="text-xs text-muted-foreground">
          Purely organizational — folders never affect retrieval.
        </p>
      </section>

      <NoteLinksSection note={note} linkCandidates={linkCandidates} onOpenNote={onOpenNote} />

      <NoteLocalGraph note={note} lookupNotes={linkCandidates} onOpenNote={onOpenNote} />

      <section className="space-y-1 border-t border-border pt-3 text-xs text-muted-foreground">
        <div className="flex items-center justify-between gap-1.5">
          <p>{formatUsage(note)}</p>
          <InfoHint label="What these details mean">
            <p>
              <span className="font-medium">Used</span> — how many times the assistant actually
              pulled this note into a conversation, and when it last did. "Never used" is a hint a
              note may be dead weight.
            </p>
            <p>
              <span className="font-medium">Created</span> — when the note was added.
            </p>
            <p>
              <span className="font-medium">Source</span> — who wrote it: you ("user"), the
              assistant while chatting ("agent_writer"), or a file import ("import").
            </p>
            <p>
              <span className="font-medium">Scope</span> — Global notes are available in every
              project; Project notes only apply inside their project.
            </p>
          </InfoHint>
        </div>
        <p>Created {formatRelativeTime(note.created_at)}</p>
        <p>Source: {note.source}</p>
        <p>Scope: {note.scope === "global" ? "Global" : "Ontology"}</p>
      </section>

      <div className="mt-auto border-t border-border pt-3">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={() => setIsConfirmingDelete(true)}
          disabled={actions.isMutating}
          className="w-full text-destructive hover:text-destructive"
        >
          <Trash2 className="mr-1.5 h-3.5 w-3.5" />
          {deleteLabel}
        </Button>
      </div>

      <AlertDialog open={isConfirmingDelete} onOpenChange={setIsConfirmingDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{deleteLabel}</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete “{linkDisplayTitle(note)}”? Links to and from it are
              removed too. This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={actions.isMutating}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmDelete}
              disabled={actions.isMutating}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
