import { useCallback } from "react";
import { emptyModel, upsertConceptGraph } from "../model.utils";
import type { ConceptGraphRoles, GraphViewModel } from "../types";

interface UseModelBuilderReturn {
  saveConceptGraphRoles: (predicate: string, roles: ConceptGraphRoles) => void;
}

/**
 * Persists concept-graph role assignments into the project's graph model
 * (creating an empty model when none exists yet) through the save mutation
 * from useGraphModel.
 */
export function useModelBuilder(
  model: GraphViewModel | null | undefined,
  scope: string,
  save: (model: GraphViewModel) => void,
): UseModelBuilderReturn {
  const baseModel = model ?? emptyModel(scope);

  const saveConceptGraphRoles = useCallback(
    (predicate: string, roles: ConceptGraphRoles) =>
      save(upsertConceptGraph(baseModel, { predicate, roles })),
    [baseModel, save],
  );

  return { saveConceptGraphRoles };
}
