import { AlertCircle, Download, FileText, Upload } from "lucide-react";
import type React from "react";
import { useRef, useState } from "react";
import { toast } from "sonner";
import { WorkspaceService } from "@/features/settings/api/workspaceService";
import { Alert, AlertDescription } from "@/shared/components/ui/alert";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";

const WorkspaceSettings: React.FC = () => {
  const [isExporting, setIsExporting] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleExport = async () => {
    try {
      setIsExporting(true);
      const response = await WorkspaceService.exportWorkspace("user");

      if (response.status === "success" && response.data) {
        // Create a downloadable JSON file with just the export data
        const exportData = response.data;

        const blob = new Blob([JSON.stringify(exportData, null, 2)], {
          type: "application/json",
        });

        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `workspace-export-user-${new Date().toISOString().split("T")[0]}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);

        toast.success("Workspace exported successfully");
      } else {
        toast.error("Workspace export failed");
      }
    } catch (error) {
      console.error("Export error:", error);
      toast.error("Workspace export failed");
    } finally {
      setIsExporting(false);
    }
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.type === "application/json" || file.name.endsWith(".json")) {
        setSelectedFile(file);
      } else {
        toast.error("Please select a valid JSON file");
        event.target.value = "";
      }
    }
  };

  const handleImport = async () => {
    if (!selectedFile) {
      toast.error("Please select a file to import");
      return;
    }

    try {
      setIsImporting(true);

      // Read the file content
      const fileContent = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => resolve(e.target?.result as string);
        reader.onerror = (e) => reject(e);
        reader.readAsText(selectedFile);
      });

      // Parse the JSON content
      let importData;
      try {
        importData = JSON.parse(fileContent);
      } catch (_parseError) {
        toast.error("Invalid JSON file format");
        return;
      }

      const response = await WorkspaceService.importWorkspace(importData, "user");

      if (response.status === "success") {
        toast.success("Workspace imported successfully");
        setSelectedFile(null);
        if (fileInputRef.current) {
          fileInputRef.current.value = "";
        }
      } else {
        toast.error("Workspace import failed");
      }
    } catch (error) {
      console.error("Import error:", error);
      toast.error("Workspace import failed");
    } finally {
      setIsImporting(false);
    }
  };

  const clearFileSelection = () => {
    setSelectedFile(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  return (
    <div className="space-y-6">
      {/* Export Section */}
      <div className="space-y-4">
        <div>
          <h4 className="text-sm font-medium mb-2">Export</h4>
          <p className="text-sm text-muted-foreground mb-4">
            Export all tables and data from your workspace.
          </p>
          <Button onClick={handleExport} disabled={isExporting} className="w-full">
            {isExporting ? (
              <>
                <PrometheuxSpinner size={16} className="mr-2" />
                Exporting...
              </>
            ) : (
              <>
                <Download className="h-4 w-4 mr-2" />
                Export Workspace
              </>
            )}
          </Button>
        </div>
      </div>

      {/* Import Section */}
      <div className="space-y-4">
        <div>
          <h4 className="text-sm font-medium mb-2">Import</h4>
          <p className="text-sm text-muted-foreground mb-4">
            Import exported workspace data into the current workspace.
          </p>

          <Alert className="mb-4">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <strong>Warning:</strong> Importing will merge data with existing workspace. This
              cannot be undone.
            </AlertDescription>
          </Alert>

          <div className="space-y-2">
            <Label htmlFor="workspace-file">Select Workspace Export File</Label>
            <Input
              id="workspace-file"
              type="file"
              accept=".json,application/json"
              onChange={handleFileSelect}
              ref={fileInputRef}
            />
            {selectedFile && (
              <div className="flex items-center justify-between p-2 bg-muted rounded-md">
                <div className="flex items-center gap-2">
                  <FileText className="h-4 w-4" />
                  <span className="text-sm">{selectedFile.name}</span>
                  <span className="text-xs text-muted-foreground">
                    ({(selectedFile.size / 1024).toFixed(1)} KB)
                  </span>
                </div>
                <Button variant="ghost" size="sm" onClick={clearFileSelection}>
                  Remove
                </Button>
              </div>
            )}
          </div>

          <Button
            onClick={handleImport}
            disabled={isImporting || !selectedFile}
            className="w-full mt-4"
            variant={selectedFile ? "default" : "secondary"}
          >
            {isImporting ? (
              <>
                <PrometheuxSpinner size={16} className="mr-2" />
                Importing...
              </>
            ) : (
              <>
                <Upload className="h-4 w-4 mr-2" />
                Import Workspace
              </>
            )}
          </Button>
        </div>
      </div>
    </div>
  );
};

export default WorkspaceSettings;
