import { create } from "zustand";

/**
 * Live width (px) of the fixed left rail as currently rendered — the expanded
 * width, the collapsed width, or 0 when the rail is hidden. Published by
 * SidePanel and read by the docked AI chat so it can anchor immediately to the
 * right of the rail without overlapping it. Not persisted: it is derived state
 * that SidePanel re-publishes on every mount.
 */
interface SidebarLayoutState {
  railWidth: number;
  setRailWidth: (width: number) => void;
}

export const useSidebarLayoutStore = create<SidebarLayoutState>((set) => ({
  railWidth: 0,
  setRailWidth: (railWidth) => set({ railWidth }),
}));
