import { useQuery } from "@tanstack/react-query";
import {
  type ExecutionStatusSnapshot,
  fetchOntologiesExecutionStatus,
} from "@/features/lineage/executionStatus";

// Poll fast while a run is live, slow otherwise so a run started elsewhere
// (e.g. another tab) is still picked up without hammering the backend. The
// engine is globally serialized, so "running" means at most one project.
const RUNNING_POLL_MS = 1500;
const IDLE_POLL_MS = 15000;

export interface UseOntologiesExecutionStatusReturn {
  /** Latest run per project, keyed by project_id. Absent project = idle. */
  statuses: Record<string, ExecutionStatusSnapshot>;
  isLoading: boolean;
}

/**
 * Execution state for every project on the list page in a single request.
 *
 * One batch call (not one per card) returns the latest run per project; idle /
 * succeeded projects are omitted, so the payload stays small even with dozens
 * of projects. Polls only while something is running, with a slow idle
 * heartbeat to catch runs started outside this page.
 */
export function useOntologiesExecutionStatus(scopes: string[]): UseOntologiesExecutionStatusReturn {
  // Stable key regardless of scope order/dupes.
  const scopeKey = Array.from(new Set(scopes)).sort().join(",");

  const { data, isLoading } = useQuery({
    queryKey: ["ontologies-execution-status", scopeKey],
    queryFn: () => fetchOntologiesExecutionStatus(scopeKey.split(",").filter(Boolean)),
    enabled: scopeKey.length > 0,
    staleTime: 0,
    refetchInterval: (q) => {
      const current = q.state.data;
      const anyRunning = !!current && Object.values(current).some((s) => s.status === "running");
      return anyRunning ? RUNNING_POLL_MS : IDLE_POLL_MS;
    },
  });

  return { statuses: data ?? {}, isLoading };
}
