import { handleFreemiumLimitError } from "@/features/billing/store/upgradeWallStore";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";

import type {
  ContextEdge,
  ContextEdgeNodeType,
  ContextNote,
  ContextNoteFilter,
  ContextNoteFromFileResponse,
  CreateContextEdgeRequest,
  CreateContextFromFileRequest,
  CreateContextNoteRequest,
  UpdateContextNoteRequest,
} from "./types";

interface ApiEnvelope<T> {
  status: "success" | "error";
  data?: T;
  message?: string;
}

const BASE_PATH = "/knowledge/context";

function buildUrl(path = ""): string {
  return `${PROMETHEUX_CONFIG.BASE_URL}${BASE_PATH}${path}`;
}

function unwrap<T>(response: ApiEnvelope<T>, fallbackMessage: string): T {
  if (response.status === "success" && response.data !== undefined) {
    return response.data;
  }
  throw new Error(response.message ?? fallbackMessage);
}

function buildQueryString(filter: ContextNoteFilter): string {
  const params = new URLSearchParams();
  params.set("scope", filter.scope);
  if (filter.scopeId) params.set("scope_id", filter.scopeId);
  if (filter.kinds?.length) params.set("kinds", filter.kinds.join(","));
  if (filter.activation) params.set("activation", filter.activation);
  return params.toString();
}

export const ContextNoteApi = {
  async list(filter: ContextNoteFilter): Promise<ContextNote[]> {
    const url = `${buildUrl()}?${buildQueryString(filter)}`;
    const response: ApiEnvelope<ContextNote[]> = await HttpService.get(url);
    return unwrap(response, "Failed to load context notes");
  },

  /** Single note by id — resolves deep links to notes in any vault. */
  async get(id: string): Promise<ContextNote> {
    const response: ApiEnvelope<ContextNote> = await HttpService.get(buildUrl(`/${id}`));
    return unwrap(response, "Failed to load context note");
  },

  async create(body: CreateContextNoteRequest): Promise<ContextNote> {
    try {
      const response: ApiEnvelope<ContextNote> = await HttpService.post(buildUrl(), body);
      return unwrap(response, "Failed to create context note");
    } catch (error) {
      // Surfaces the freemium embedding-cap 402 as the shared upgrade wall.
      handleFreemiumLimitError(error);
      throw error;
    }
  },

  async createFromFile(body: CreateContextFromFileRequest): Promise<ContextNoteFromFileResponse> {
    try {
      const response: ApiEnvelope<ContextNoteFromFileResponse> = await HttpService.post(
        buildUrl("/from-file"),
        body,
      );
      return unwrap(response, "Failed to ingest file as context");
    } catch (error) {
      // Surfaces the freemium embedding-cap 402 as the shared upgrade wall.
      handleFreemiumLimitError(error);
      throw error;
    }
  },

  async update(id: string, body: UpdateContextNoteRequest): Promise<ContextNote> {
    const response: ApiEnvelope<ContextNote> = await HttpService.patch(buildUrl(`/${id}`), body);
    return unwrap(response, "Failed to update context note");
  },

  async remove(id: string): Promise<void> {
    const response: ApiEnvelope<void> = await HttpService.delete(buildUrl(`/${id}`));
    if (response.status !== "success") {
      throw new Error(response.message ?? "Failed to delete context note");
    }
  },

  async search(query: string, filter: ContextNoteFilter): Promise<ContextNote[]> {
    const response: ApiEnvelope<ContextNote[]> = await HttpService.post(
      `${buildUrl("/search")}?${buildQueryString(filter)}`,
      { query },
    );
    return unwrap(response, "Failed to search context notes");
  },

  /** Active notes attached to a concept/project/datasource node via
   *  context_edges, either direction. Concepts use conceptNodeId(). */
  async listAttached(nodeType: ContextEdgeNodeType, nodeId: string): Promise<ContextNote[]> {
    const params = new URLSearchParams({ node_type: nodeType, node_id: nodeId });
    const response: ApiEnvelope<ContextNote[]> = await HttpService.get(
      `${buildUrl("/attached")}?${params.toString()}`,
    );
    return unwrap(response, "Failed to load attached notes");
  },

  /** Full-text (exact word) search over titles + text, ranked by ts_rank.
   *  Complements the semantic `search` — use both in the search pane. */
  async searchFulltext(query: string, filter: ContextNoteFilter): Promise<ContextNote[]> {
    const params = new URLSearchParams(buildQueryString(filter));
    params.set("q", query);
    const response: ApiEnvelope<ContextNote[]> = await HttpService.get(
      `${buildUrl("/fts")}?${params.toString()}`,
    );
    return unwrap(response, "Failed to search context notes (full-text)");
  },
};

export const ContextEdgeApi = {
  /** Every edge touching the node, both directions (backlinks included). */
  async listForNode(nodeType: ContextEdgeNodeType, nodeId: string): Promise<ContextEdge[]> {
    const params = new URLSearchParams({ node_type: nodeType, node_id: nodeId });
    const response: ApiEnvelope<ContextEdge[]> = await HttpService.get(
      `${buildUrl("/edges")}?${params.toString()}`,
    );
    return unwrap(response, "Failed to load context edges");
  },

  /** Every edge in the workspace — feeds the graph view. */
  async listAll(): Promise<ContextEdge[]> {
    const response: ApiEnvelope<ContextEdge[]> = await HttpService.get(buildUrl("/edges"));
    return unwrap(response, "Failed to load context edges");
  },

  /** Duplicate triples return the existing edge rather than erroring. */
  async create(body: CreateContextEdgeRequest): Promise<ContextEdge> {
    const response: ApiEnvelope<ContextEdge> = await HttpService.post(buildUrl("/edges"), body);
    return unwrap(response, "Failed to create context edge");
  },

  async remove(id: string): Promise<void> {
    const response: ApiEnvelope<void> = await HttpService.delete(buildUrl(`/edges/${id}`));
    if (response.status !== "success") {
      throw new Error(response.message ?? "Failed to delete context edge");
    }
  },
};
