import type { Dispatch, SetStateAction } from "react";
import { useCallback, useState } from "react";
import { toast } from "sonner";
import { type GraphData, OntologySchemaService } from "@/features/ontology-schema/api";
import { DEFAULT_NODE_COLORS } from "../constants";
import { applyLayout, generateEdgeId, migrateCustomFields } from "../graph.utils";
import type { EdgeData, GraphState, NodeData, ViewMode } from "../types";

/** Loosely-typed shapes for nodes/edges parsed from user-edited JSON. */
interface ParsedGraphNode {
  id?: string;
  label?: string;
  description?: string;
  color?: string;
  collapsed?: boolean;
  customFields?: Record<string, unknown>;
  containedNodes?: NodeData["containedNodes"];
  x?: number;
  y?: number;
}

interface ParsedGraphEdge {
  id?: string;
  from?: string;
  to?: string;
  label?: string;
  description?: string;
  bidirectional?: boolean;
  smooth?: EdgeData["smooth"];
  selfReference?: EdgeData["selfReference"];
  customFields?: Record<string, unknown>;
}

interface UseGraphPersistenceParams {
  ontologyId: string;
  ontologyScope: string;
  graphState: GraphState;
  viewMode: ViewMode;
  jsonContent: string;
  setGraphState: Dispatch<SetStateAction<GraphState>>;
}

/**
 * Owns graph persistence: load from backend, save (visual or JSON mode),
 * debounced auto-save, and silent refresh. Extracted from OntologySchemaEditor.
 */
export function useGraphPersistence({
  ontologyId,
  ontologyScope,
  graphState,
  viewMode,
  jsonContent,
  setGraphState,
}: UseGraphPersistenceParams) {
  const [isSaving, setIsSaving] = useState(false);
  const [, setIsLoading] = useState(false);

  // Reload from backend, preserving any locally-known node positions.
  const refreshGraphFromBackend = useCallback(async () => {
    if (!ontologyId) return;
    try {
      const graphData = await OntologySchemaService.loadGraph(ontologyId, ontologyScope);
      if (graphData) {
        const seenKeys = new Set<string>();
        const dedupedEdges = graphData.edges.filter((e) => {
          const key = `${e.from}|${e.to}|${(e.label || "").toLowerCase()}`;
          if (seenKeys.has(key)) return false;
          seenKeys.add(key);
          return true;
        });
        setGraphState((prev) => {
          const posById = new Map(prev.nodes.map((n) => [n.id, { x: n.x, y: n.y }]));
          const posByLabel = new Map(
            prev.nodes.map((n) => [n.label?.toLowerCase(), { x: n.x, y: n.y }]),
          );
          const nodes = graphData.nodes.map((n) => {
            const saved = posById.get(n.id) ?? posByLabel.get(n.label?.toLowerCase());
            return saved ? { ...n, x: saved.x ?? n.x, y: saved.y ?? n.y } : n;
          });
          return { nodes, edges: dedupedEdges };
        });
      }
    } catch (error) {
      console.error("Silent graph refresh failed:", error);
    }
  }, [ontologyId, ontologyScope, setGraphState]);

  const autoSaveGraph = useCallback(
    (updatedGraphState: GraphState) => {
      if (!ontologyId) return;

      setTimeout(() => {
        (async () => {
          try {
            await OntologySchemaService.saveGraph(ontologyId, updatedGraphState, ontologyScope);
            await refreshGraphFromBackend();
          } catch (error) {
            console.error("Auto-save failed:", error);
          }
        })();
      }, 100);
    },
    [ontologyId, ontologyScope, refreshGraphFromBackend],
  );

  // Save graph to backend
  const saveGraph = useCallback(async () => {
    if (!ontologyId) {
      toast.error("No ontology selected");
      return;
    }

    setIsSaving(true);
    try {
      let graphData: GraphData;

      if (viewMode === "json") {
        // If in JSON mode, parse the current JSON content
        try {
          const parsedData = JSON.parse(jsonContent);

          // Validate the JSON structure
          if (
            !parsedData.nodes ||
            !parsedData.edges ||
            !Array.isArray(parsedData.nodes) ||
            !Array.isArray(parsedData.edges)
          ) {
            throw new Error('Invalid graph data structure. Expected "nodes" and "edges" arrays.');
          }

          // Validate and process nodes
          const validatedNodes = parsedData.nodes.map((node: ParsedGraphNode, index: number) => {
            if (!node.id) {
              throw new Error(`Node at index ${index} is missing an "id" field`);
            }
            return {
              id: node.id,
              label: node.label || `Node ${index + 1}`,
              description: node.description || "",
              color: node.color || DEFAULT_NODE_COLORS[index % DEFAULT_NODE_COLORS.length],
              collapsed: node.collapsed || false,
              customFields: migrateCustomFields(node.customFields || {}),
              containedNodes: node.containedNodes || [],
              x: node.x,
              y: node.y,
            };
          });

          // Validate and process edges
          const validatedEdges = parsedData.edges.map((edge: ParsedGraphEdge, index: number) => {
            if (!edge.from || !edge.to) {
              throw new Error(`Edge at index ${index} is missing "from" or "to" field`);
            }
            // Check if referenced nodes exist
            if (!validatedNodes.find((n: NodeData) => n.id === edge.from)) {
              throw new Error(
                `Edge at index ${index} references non-existent source node: ${edge.from}`,
              );
            }
            if (!validatedNodes.find((n: NodeData) => n.id === edge.to)) {
              throw new Error(
                `Edge at index ${index} references non-existent target node: ${edge.to}`,
              );
            }
            return {
              id: edge.id || generateEdgeId(),
              from: edge.from,
              to: edge.to,
              label: edge.label || "",
              description: edge.description || "",
              bidirectional: edge.bidirectional || false,
              smooth: edge.smooth || {
                enabled: true,
                type: "continuous",
                roundness: 0.5,
              },
              ...(edge.selfReference && {
                selfReference: edge.selfReference,
              }),
              customFields: migrateCustomFields(edge.customFields || {}),
            };
          });

          graphData = {
            nodes: validatedNodes,
            edges: validatedEdges,
          };
        } catch (parseError) {
          toast.error(
            `Cannot save: Invalid JSON format. ${parseError instanceof Error ? parseError.message : "Please fix the JSON and try again."}`,
          );
          return;
        }
      } else {
        // If in visual mode, use the current graph state
        graphData = {
          nodes: graphState.nodes,
          edges: graphState.edges,
        };
      }

      await OntologySchemaService.saveGraph(ontologyId, graphData, ontologyScope);
      await refreshGraphFromBackend();
      window.dispatchEvent(new Event("lineageTabActivated"));
      toast.success("Graph saved successfully");
    } catch (error) {
      console.error("Error saving graph:", error);
      toast.error("Failed to save graph");
    } finally {
      setIsSaving(false);
    }
  }, [ontologyId, ontologyScope, graphState, viewMode, jsonContent, refreshGraphFromBackend]);

  // Load graph from backend
  const loadGraph = useCallback(async () => {
    if (!ontologyId) {
      toast.error("No ontology selected");
      return;
    }

    setIsLoading(true);
    try {
      const graphData = await OntologySchemaService.loadGraph(ontologyId, ontologyScope);

      if (graphData) {
        const seenKeys = new Set<string>();
        const dedupedEdges = graphData.edges.filter((e) => {
          const key = `${e.from}|${e.to}|${(e.label || "").toLowerCase()}`;
          if (seenKeys.has(key)) return false;
          seenKeys.add(key);
          return true;
        });

        const allHavePositions = graphData.nodes.every(
          (node) => node.x !== undefined && node.y !== undefined,
        );
        const noneHavePositions = !graphData.nodes.some(
          (node) => node.x !== undefined && node.y !== undefined,
        );

        if (noneHavePositions && graphData.nodes.length > 0) {
          const layoutedNodes = applyLayout(graphData.nodes, dedupedEdges);
          setGraphState({
            nodes: layoutedNodes,
            edges: dedupedEdges,
          });
        } else if (!allHavePositions && graphData.nodes.length > 0) {
          const layouted = applyLayout(graphData.nodes, dedupedEdges);
          const layoutMap = new Map(layouted.map((n) => [n.id, { x: n.x, y: n.y }]));
          const merged = graphData.nodes.map((n) => {
            if (n.x !== undefined && n.y !== undefined) return n;
            const fallback = layoutMap.get(n.id);
            return { ...n, x: fallback?.x ?? 0, y: fallback?.y ?? 0 };
          });
          setGraphState({ nodes: merged, edges: dedupedEdges });
        } else {
          setGraphState({
            nodes: graphData.nodes,
            edges: dedupedEdges,
          });
        }
      } else {
        // No graph data found - start with empty graph
        setGraphState({ nodes: [], edges: [] });
      }
    } catch (error) {
      console.error("Error loading ontology:", error);
    } finally {
      setIsLoading(false);
    }
  }, [ontologyId, ontologyScope, setGraphState]);

  return { isSaving, refreshGraphFromBackend, autoSaveGraph, saveGraph, loadGraph };
}
