import { Check, ShieldAlert, ShieldCheck, X } from "lucide-react";

import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

import { prettifyToolName, summarizeAuthorizationInput } from "../authorization.utils";
import type { AuthorizationData, AuthorizationState } from "../store";

export type AuthorizationDecision = "once" | "always" | "deny";

interface AuthorizationPromptProps {
  data: AuthorizationData;
  state: AuthorizationState;
  onDecide: (decision: AuthorizationDecision) => void;
}

function resolvedLabel(state: AuthorizationState): string {
  if (state === "allowed_once") return "Allowed once";
  if (state === "always_allowed") return "Always allowed";
  if (state === "denied") return "Denied";
  return "";
}

export function AuthorizationPrompt({ data, state, onDecide }: AuthorizationPromptProps) {
  const isPending = state === "pending";
  const toolLabel = prettifyToolName(data.tool);
  const subject = summarizeAuthorizationInput(data.input);
  const destructive = !data.persistable;

  const handleOnce = () => onDecide("once");
  const handleAlways = () => onDecide("always");
  const handleDeny = () => onDecide("deny");

  return (
    <div
      className={cn(
        "rounded-md border p-3 text-sm",
        destructive ? "border-red-500/40 bg-red-50/60 dark:bg-red-900/10" : "border-border bg-card",
        !isPending && "opacity-80",
      )}
    >
      <header className="flex flex-wrap items-center gap-2 pb-1.5 text-xs text-muted-foreground">
        {destructive ? (
          <ShieldAlert className="h-3.5 w-3.5 text-red-600 dark:text-red-400" />
        ) : (
          <ShieldCheck className="h-3.5 w-3.5 text-primary" />
        )}
        <span className="font-medium uppercase tracking-wide">
          {destructive ? "Confirm action" : "Authorization"}
        </span>
      </header>

      <p className="text-foreground">
        Allow the assistant to <span className="font-medium">{toolLabel.toLowerCase()}</span>
        {subject && (
          <>
            {" "}
            <code className="rounded bg-muted px-1 py-0.5 text-xs">{subject}</code>
          </>
        )}
        ?
      </p>
      {destructive && isPending && (
        <p className="pt-1 text-xs text-red-600 dark:text-red-400">
          This is destructive and can't be permanently allowed — approve it only for this action.
        </p>
      )}

      {isPending ? (
        <footer className="mt-3 flex flex-wrap justify-end gap-2">
          <Button type="button" size="sm" variant="ghost" onClick={handleDeny}>
            <X className="mr-1 h-3.5 w-3.5" />
            Deny
          </Button>
          <Button type="button" size="sm" variant="outline" onClick={handleOnce}>
            Allow once
          </Button>
          {data.persistable && (
            <Button type="button" size="sm" onClick={handleAlways}>
              <Check className="mr-1 h-3.5 w-3.5" />
              Always allow
            </Button>
          )}
        </footer>
      ) : (
        <footer className="mt-2 text-xs text-muted-foreground">{resolvedLabel(state)}</footer>
      )}
    </div>
  );
}
