import { ChevronDown, ChevronRight, Loader2, Trash2, Users } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { cn } from "@/shared/lib/utils";
import type { OutboxEntry, ShareRole } from "../types";
import { formatExpiresAt, statusLabel } from "../utils/sharing.utils";
import TeamMemberOverrides from "./TeamMemberOverrides";
import TeamShareGrants from "./TeamShareGrants";

interface ShareRowProps {
  entry: OutboxEntry;
  greyed: boolean;
  isRevoking: boolean;
  pendingRevokeShareId: string | null;
  onRevoke: (entry: OutboxEntry) => void;
  onRoleChange: (entry: OutboxEntry, role: ShareRole) => void;
  updatingShareId: string | null;
}

const LIVE_STATUSES = new Set<OutboxEntry["status"]>(["pending", "accepted", "active"]);

function statusVariant(status: OutboxEntry["status"]): "secondary" | "default" | "outline" {
  if (status === "pending") return "secondary";
  if (status === "accepted" || status === "active") return "default";
  return "outline";
}

function isShareRole(value: string): value is ShareRole {
  return value === "viewer" || value === "editor";
}

const ShareRow: React.FC<ShareRowProps> = ({
  entry,
  greyed,
  isRevoking,
  pendingRevokeShareId,
  onRevoke,
  onRoleChange,
  updatingShareId,
}) => {
  const [showGrants, setShowGrants] = useState(false);
  const [showOverrides, setShowOverrides] = useState(false);

  const isThisRowRevoking = isRevoking && pendingRevokeShareId === entry.share_id;
  const isTeam = entry.share_type === "team";
  const teamName = entry.team_name ?? "Team";
  const teamId = entry.recipient_team_id ?? entry.team_id ?? "";
  const claimedCount = entry.claimed_count ?? 0;
  const isLive = LIVE_STATUSES.has(entry.status);
  const canRevoke = isLive;
  // Both user and team shares are editable while live (M6 added team update-role).
  // Historical rows keep a static badge so the audit trail reflects the role at
  // the time of the terminal transition.
  const canEditRole = isLive;
  const isThisRowUpdatingRole = updatingShareId === entry.share_id;

  const handleRoleSelect = (value: string): void => {
    if (!isShareRole(value)) return;
    // No client-side identity guard: the backend is authoritative and returns
    // `data.changed=false` for no-ops (handled at the toast layer).
    onRoleChange(entry, value);
  };

  const handleToggleGrants = (): void => {
    setShowGrants((prev) => !prev);
  };

  const handleToggleOverrides = (): void => {
    setShowOverrides((prev) => !prev);
  };

  return (
    <div className={cn("rounded-md border border-border bg-card", greyed && "opacity-60")}>
      <div className="flex items-start justify-between gap-3 px-3 py-2.5">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            {isTeam ? (
              <>
                <Users className="h-3.5 w-3.5 flex-shrink-0 text-muted-foreground" />
                <span className="truncate text-sm font-medium text-foreground">{teamName}</span>
                <span className="text-xs text-muted-foreground">Team</span>
              </>
            ) : (
              <>
                <span className="truncate text-sm font-medium text-foreground">
                  {entry.recipient_username}
                </span>
                <span className="text-xs text-muted-foreground">
                  @{entry.recipient_organization}
                </span>
              </>
            )}
          </div>
          <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
            {canEditRole ? (
              <div className="flex items-center gap-1.5">
                <Select
                  value={entry.share_role}
                  onValueChange={handleRoleSelect}
                  disabled={isThisRowUpdatingRole}
                >
                  <SelectTrigger className="h-7 w-[100px] px-2 py-0 text-xs capitalize">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="viewer">Viewer</SelectItem>
                    <SelectItem value="editor">Editor</SelectItem>
                  </SelectContent>
                </Select>
                {isThisRowUpdatingRole && (
                  <Loader2 className="h-3 w-3 animate-spin text-muted-foreground" />
                )}
              </div>
            ) : (
              <Badge variant="outline" className="capitalize">
                {entry.share_role}
              </Badge>
            )}
            <Badge variant={statusVariant(entry.status)} className="capitalize">
              {statusLabel(entry.status)}
            </Badge>
            {isTeam ? (
              <>
                <button
                  type="button"
                  onClick={handleToggleGrants}
                  className="inline-flex items-center gap-1 rounded px-1 py-0.5 font-medium text-muted-foreground hover:text-foreground"
                >
                  {showGrants ? (
                    <ChevronDown className="h-3 w-3" />
                  ) : (
                    <ChevronRight className="h-3 w-3" />
                  )}
                  {claimedCount} joined
                </button>
                <button
                  type="button"
                  onClick={handleToggleOverrides}
                  className="inline-flex items-center gap-1 rounded px-1 py-0.5 font-medium text-muted-foreground hover:text-foreground"
                >
                  {showOverrides ? (
                    <ChevronDown className="h-3 w-3" />
                  ) : (
                    <ChevronRight className="h-3 w-3" />
                  )}
                  Member roles
                </button>
              </>
            ) : (
              <span>{formatExpiresAt(entry.expires_at)}</span>
            )}
          </div>
        </div>
        {canRevoke && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-8 text-destructive hover:text-destructive"
            disabled={isThisRowRevoking}
            onClick={() => onRevoke(entry)}
          >
            {isThisRowRevoking ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Trash2 className="h-3.5 w-3.5" />
            )}
            <span className="ml-1">Revoke</span>
          </Button>
        )}
      </div>
      {isTeam && showGrants && (
        <div className="border-t border-border p-2">
          <TeamShareGrants shareId={entry.share_id} />
        </div>
      )}
      {isTeam && showOverrides && teamId && (
        <div className="border-t border-border p-2">
          <TeamMemberOverrides
            ontologyId={entry.ontology_id}
            teamId={teamId}
            teamBaseRole={entry.share_role}
          />
        </div>
      )}
    </div>
  );
};

export default ShareRow;
