import type React from "react";
import { Button } from "@/shared/components/ui/button";

const getFileIcon = (fileName: string) => {
  const extension = fileName.split(".").pop()?.toLowerCase();
  switch (extension) {
    case "pdf":
      return "📄";
    case "csv":
      return "📊";
    case "txt":
      return "📝";
    case "doc":
    case "docx":
      return "📄";
    case "png":
    case "jpg":
    case "jpeg":
    case "gif":
    case "bmp":
    case "webp":
    case "svg":
      return "🖼️";
    default:
      return "📎";
  }
};

const getFileTypeColor = (fileName: string) => {
  const extension = fileName.split(".").pop()?.toLowerCase();
  switch (extension) {
    case "pdf":
      return "bg-red-500";
    case "csv":
      return "bg-green-500";
    case "txt":
      return "bg-blue-500";
    case "doc":
    case "docx":
      return "bg-blue-600";
    case "png":
    case "jpg":
    case "jpeg":
    case "gif":
    case "bmp":
    case "webp":
    case "svg":
      return "bg-purple-500";
    default:
      return "bg-gray-500";
  }
};

interface AttachedFilesPreviewProps {
  attachedFiles: File[];
  onFileRemove: (index: number) => void;
}

const AttachedFilesPreview: React.FC<AttachedFilesPreviewProps> = ({
  attachedFiles,
  onFileRemove,
}) => {
  if (attachedFiles.length === 0) return null;

  return (
    <div className="mt-3 space-y-2">
      {attachedFiles.map((file, index) => (
        <div
          key={index}
          className="relative bg-gray-100 rounded-xl px-4 py-3 shadow-sm border border-gray-200"
        >
          <div className="flex items-center gap-3">
            <div
              className={`w-8 h-8 rounded-lg ${getFileTypeColor(file.name)} flex items-center justify-center text-white text-sm font-medium`}
            >
              {getFileIcon(file.name)}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-sm font-medium text-gray-900 truncate">{file.name}</div>
              <div className="text-xs text-gray-500 uppercase">{file.name.split(".").pop()}</div>
            </div>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => onFileRemove(index)}
              className="h-6 w-6 p-0 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-full"
            >
              ×
            </Button>
          </div>
        </div>
      ))}
    </div>
  );
};

export default AttachedFilesPreview;
