import { Check, ChevronDown, Plus } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Checkbox } from "@/shared/components/ui/checkbox";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/shared/components/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";
import { cn } from "@/shared/lib/utils";
import { FieldRow } from "./fields";

/**
 * Typeahead pickers over a known token vocabulary (concept names, column
 * names) — the author searches instead of memorizing identifiers. A
 * free-text escape stays available for tokens the list does not know
 * (e.g. a concept not yet saved), so the pickers never gate what the
 * schema allows.
 */

const NONE_VALUE = "__none__";

interface TokenCommandListProps {
  options: string[];
  loading: boolean;
  noun: string;
  search: string;
  onSearchChange: (value: string) => void;
  isSelected: (token: string) => boolean;
  onPick: (token: string) => void;
  multi?: boolean;
  /** Renders a "— none —" entry mapping to undefined (single-select only). */
  onClear?: () => void;
}

function TokenCommandList({
  options,
  loading,
  noun,
  search,
  onSearchChange,
  isSelected,
  onPick,
  multi,
  onClear,
}: TokenCommandListProps) {
  const trimmed = search.trim();
  const showCustom = trimmed.length > 0 && !options.includes(trimmed);
  const emptyText = loading ? `Loading ${noun}…` : `No ${noun} match.`;
  // Filter manually (shouldFilter={false}) so real tokens keep their order
  // and always rank above the free-text escape item.
  const visible = options.filter((token) => token.toLowerCase().includes(trimmed.toLowerCase()));

  return (
    <Command shouldFilter={false}>
      <CommandInput
        value={search}
        onValueChange={onSearchChange}
        placeholder={`Search ${noun}…`}
        className="h-8 text-xs"
      />
      <CommandList>
        <CommandEmpty className="py-3 text-center text-xs text-muted-foreground">
          {emptyText}
        </CommandEmpty>
        <CommandGroup>
          {onClear && !trimmed && (
            <CommandItem
              value={NONE_VALUE}
              onSelect={onClear}
              className="text-xs cursor-pointer text-muted-foreground"
            >
              <Check className="mr-2 h-3 w-3 opacity-0" />— none —
            </CommandItem>
          )}
          {visible.map((token) => (
            <CommandItem
              key={token}
              value={token}
              onSelect={() => onPick(token)}
              className="text-xs font-mono cursor-pointer"
              title={token}
            >
              {multi ? (
                <Checkbox
                  checked={isSelected(token)}
                  className="mr-2 pointer-events-none"
                  tabIndex={-1}
                  aria-hidden="true"
                />
              ) : (
                <Check className={cn("mr-2 h-3 w-3", !isSelected(token) && "opacity-0")} />
              )}
              <span className="truncate">{token}</span>
            </CommandItem>
          ))}
          {showCustom && (
            <CommandItem
              value={trimmed}
              onSelect={() => onPick(trimmed)}
              className="text-xs cursor-pointer"
            >
              <Plus className="mr-2 h-3 w-3" />
              Use “{trimmed}”
            </CommandItem>
          )}
        </CommandGroup>
      </CommandList>
    </Command>
  );
}

function summarizeSelection(selected: string[], noun: string, placeholder?: string): string {
  if (selected.length === 0) return placeholder ?? `Select ${noun}…`;
  if (selected.length <= 2) return selected.join(", ");
  return `${selected.length} ${noun} selected`;
}

interface TokenMultiSelectFieldProps {
  label: string;
  hint?: string;
  value: string[];
  onChange: (value: string[]) => void;
  options: string[];
  loading?: boolean;
  noun?: string;
  /** Trigger text while nothing is selected (e.g. "All columns"). */
  placeholder?: string;
}

/** Labeled multi-select; selection order is preserved (click order). */
export function TokenMultiSelectField({
  label,
  hint,
  value,
  onChange,
  options,
  loading = false,
  noun = "items",
  placeholder,
}: TokenMultiSelectFieldProps) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");

  const handleOpenChange = (next: boolean) => {
    setOpen(next);
    if (!next) setSearch("");
  };

  const toggle = (token: string) => {
    if (value.includes(token)) return onChange(value.filter((item) => item !== token));
    onChange([...value, token]);
  };

  return (
    <FieldRow label={label} hint={hint}>
      <Popover open={open} onOpenChange={handleOpenChange}>
        <PopoverTrigger asChild>
          <Button
            type="button"
            variant="outline"
            role="combobox"
            aria-expanded={open}
            className="h-7 w-full justify-between px-2 text-xs font-normal"
          >
            <span
              className={cn(
                "truncate font-mono",
                value.length === 0 && "font-sans text-muted-foreground",
              )}
            >
              {summarizeSelection(value, noun, placeholder)}
            </span>
            <ChevronDown className="ml-1 h-3 w-3 shrink-0 opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent
          className="w-[--radix-popover-trigger-width] min-w-[14rem] p-0"
          align="start"
        >
          <TokenCommandList
            options={options}
            loading={loading}
            noun={noun}
            search={search}
            onSearchChange={setSearch}
            isSelected={(token) => value.includes(token)}
            onPick={toggle}
            multi
          />
        </PopoverContent>
      </Popover>
    </FieldRow>
  );
}

interface TokenComboboxProps {
  value: string | undefined;
  onChange: (value: string | undefined) => void;
  options: string[];
  loading?: boolean;
  noun?: string;
  placeholder?: string;
  className?: string;
  /** Offers a "— none —" entry that clears the value. */
  allowNone?: boolean;
}

/** Compact single-select over a token vocabulary. */
export function TokenCombobox({
  value,
  onChange,
  options,
  loading = false,
  noun = "items",
  placeholder,
  className,
  allowNone,
}: TokenComboboxProps) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");

  const handleOpenChange = (next: boolean) => {
    setOpen(next);
    if (!next) setSearch("");
  };

  const pick = (token: string | undefined) => {
    onChange(token);
    handleOpenChange(false);
  };

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className={cn("h-6 justify-between px-2 text-[11px] font-mono font-normal", className)}
        >
          <span className={cn("truncate", !value && "font-sans text-muted-foreground")}>
            {value ?? placeholder ?? `Select ${noun}…`}
          </span>
          <ChevronDown className="ml-1 h-3 w-3 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[--radix-popover-trigger-width] min-w-[14rem] p-0" align="start">
        <TokenCommandList
          options={options}
          loading={loading}
          noun={noun}
          search={search}
          onSearchChange={setSearch}
          isSelected={(token) => token === value}
          onPick={pick}
          onClear={allowNone ? () => pick(undefined) : undefined}
        />
      </PopoverContent>
    </Popover>
  );
}

interface TokenComboboxFieldProps extends TokenComboboxProps {
  label: string;
  hint?: string;
}

/** Labeled single-select styled like the other inspector fields. */
export function TokenComboboxField({ label, hint, ...combobox }: TokenComboboxFieldProps) {
  return (
    <FieldRow label={label} hint={hint}>
      <TokenCombobox {...combobox} className={cn("h-7 w-full text-xs", combobox.className)} />
    </FieldRow>
  );
}
