import type { EdgeData, NodeData } from "@antv/g6";
import type { GraphAnalyticsResult } from "../../api/GraphAnalyticsClient";

export const LARGE_GRAPH_THRESHOLD = 200;

export const NODE_FILL = "#DBEAFE";
export const NODE_STROKE = "#93C5FD";
export const NODE_LABEL_FILL = "#1E3A5F";
export const EDGE_STROKE = "#94A3B8";

export const PATH_SOURCE_STROKE = "#10b981";
export const PATH_TARGET_STROKE = "#ef4444";
export const PATH_PICK_LINE_WIDTH = 4;

export const LAYOUTS = [
  { value: "dagre", label: "Hierarchical" },
  { value: "force", label: "Force" },
  { value: "grid", label: "Grid" },
  { value: "circular", label: "Circular" },
  { value: "radial", label: "Radial" },
] as const;

export type LayoutType = (typeof LAYOUTS)[number]["value"];

export type PickMode = "source" | "target" | null;

export function resolveGridStroke(theme: string): string {
  return theme === "dark" ? "#1e293b" : "#f0f4f8";
}

export function buildLayout(type: LayoutType, large = false) {
  switch (type) {
    case "dagre":
      return { type: "dagre", rankdir: "TB", nodesep: 60, ranksep: 60 };
    case "force":
      return {
        type: "force",
        preventOverlap: !large,
        nodeStrength: large ? -20 : -50,
        edgeStrength: 0.1,
        iterations: large ? 100 : 300,
      };
    case "grid":
      return { type: "grid" };
    case "circular":
      return { type: "circular" };
    case "radial":
      return { type: "radial", unitRadius: 100 };
  }
}

export function truncateLabel(label: string): string {
  return label.length > 20 ? `${label.slice(0, 17)}…` : label;
}

export interface GraphNode extends NodeData {
  id: string;
  _fill?: string;
  _stroke?: string;
}

export interface GraphEdge extends EdgeData {
  id: string;
  source: string;
  target: string;
}

export interface GraphData {
  nodes: GraphNode[];
  edges: GraphEdge[];
}

const SCORE_FROM = [219, 234, 254] as const;
const SCORE_TO = [30, 64, 175] as const;

// Derive a stable, unique color from a component identifier string.
// Uses a simple string hash → hue so each distinct component ID always
// maps to the same hue, and no two different IDs accidentally share one
// (unlike a fixed palette that wraps after 10 entries).
function componentIdToColor(id: string): string {
  let hash = 0;
  for (let i = 0; i < id.length; i++) {
    hash = (hash * 31 + id.charCodeAt(i)) >>> 0;
  }
  const hue = hash % 360;
  return `hsl(${hue}, 70%, 55%)`;
}

function scoreToColor(normalized: number): string {
  const r = Math.round(SCORE_FROM[0] + normalized * (SCORE_TO[0] - SCORE_FROM[0]));
  const g = Math.round(SCORE_FROM[1] + normalized * (SCORE_TO[1] - SCORE_FROM[1]));
  const b = Math.round(SCORE_FROM[2] + normalized * (SCORE_TO[2] - SCORE_FROM[2]));
  return `rgb(${r},${g},${b})`;
}

export function buildGraphData(
  rows: unknown[][],
  xCol: number,
  yCol: number,
  analytics: GraphAnalyticsResult | null,
): GraphData {
  if (analytics) {
    const range = analytics.analytics_range;

    return {
      nodes: analytics.nodes.map((n) => {
        const a = n.analytics;
        let fill = NODE_FILL;
        let stroke = NODE_STROKE;

        if (a?.score !== undefined && range) {
          const span = range.max - range.min || 1;
          const normalized = Math.max(0, Math.min(1, (a.score - range.min) / span));
          fill = scoreToColor(normalized);
          stroke = scoreToColor(Math.min(1, normalized + 0.15));
        } else if (a?.component !== undefined) {
          fill = componentIdToColor(a.component);
          stroke = fill;
        }

        return { id: n.id, _fill: fill, _stroke: stroke };
      }),
      edges: analytics.edges.map((e, i) => ({
        id: `e${i}`,
        source: e.source,
        target: e.target,
      })),
    };
  }

  const nodeIds = new Set<string>();
  const edges: GraphEdge[] = [];
  rows.forEach((row, idx) => {
    const source = String(row[xCol] ?? "");
    const target = String(row[yCol] ?? "");
    if (!source || !target) return;
    nodeIds.add(source);
    nodeIds.add(target);
    edges.push({ id: `e${idx}`, source, target });
  });

  return {
    nodes: Array.from(nodeIds).map((id) => ({ id })),
    edges,
  };
}
