import type React from "react";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";
import { useSharedOntologyContext } from "../hooks/useSharedOntologyContext";

interface ReadOnlyGateProps {
  children: React.ReactNode;
  // Optional tooltip override. Defaults to the standard "read-only" message that names
  // the owner when known.
  tooltip?: string;
  // Per-concept (or computed) read-only override. When provided, it takes
  // precedence over the global share role — this is how per-concept elevation
  // and restriction work:
  //   - false → editable even under a viewer share (a concept elevated to
  //     writeable, or an ontology-wide surface where at least one concept is
  //     writeable)
  //   - true  → blocked even under an editor share (a concept restricted to
  //     read-only)
  // When undefined, falls back to the global share-role gate (legacy behavior
  // for surfaces that have no concept context).
  readOnly?: boolean;
}

// Wraps an editor-mutation affordance so it becomes non-interactive when the current
// user cannot edit the concept/surface it guards. Defense in depth — the backend already
// returns 403 on the corresponding routes (concept_read_only / share_revoked), but the FE
// shouldn't invite the failure.
//
// Gating precedence: an explicit `readOnly` prop always wins (per-concept flag from the
// concept list); otherwise we fall back to the global viewer share role. Deciding purely
// off the share role is wrong — a concept can be writeable under a viewer share (elevation)
// or read-only under an editor share (restriction) — so concept-scoped callers must pass
// the per-concept flag.
//
// Implementation notes:
//   - The outer wrapper captures hover for the Tooltip (so the user sees *why* the
//     button is disabled).
//   - The inner div sets `pointer-events: none` to block clicks on the children without
//     mutating their props (works regardless of whether children are Button, native
//     <button>, or arbitrary JSX).
//   - When not in read-only mode, children render unchanged with no wrapper overhead.
export function ReadOnlyGate({ children, tooltip, readOnly }: ReadOnlyGateProps) {
  const { isReadOnly: globalReadOnly, sharedBy } = useSharedOntologyContext();
  const blocked = readOnly ?? globalReadOnly;

  if (!blocked) return <>{children}</>;

  const ownerLabel = sharedBy ? `${sharedBy.username}@${sharedBy.organization}` : "the owner";
  const message = tooltip ?? `Read-only — ask ${ownerLabel} for editor access`;

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span className="inline-flex items-center" aria-disabled="true">
          <span className="pointer-events-none opacity-50">{children}</span>
        </span>
      </TooltipTrigger>
      <TooltipContent>{message}</TooltipContent>
    </Tooltip>
  );
}
