import { AlertTriangle, ChevronDown, ChevronUp, Database, X } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/shared/components/ui/dialog";

export interface FailedDatasource {
  datasource_type: string;
  host: string;
  port: string;
  database_name: string;
  schema_name: string;
  table_name: string;
  error?: string;
}

interface FailedDatasourcesDialogProps {
  failedDatasources: FailedDatasource[];
  onClose: () => void;
}

const FILE_TYPES = new Set([
  "csv",
  "excel",
  "json",
  "parquet",
  "pdf",
  "image",
  "text",
  "docx",
  "binaryfile",
]);

function formatDatasourceDetail(ds: FailedDatasource) {
  const isFile = FILE_TYPES.has(ds.datasource_type?.toLowerCase());
  if (isFile) {
    return {
      type: ds.datasource_type,
      location: ds.database_name || ds.host || "—",
      table: ds.table_name || "—",
    };
  }
  const hostPort = [ds.host, ds.port].filter(Boolean).join(":");
  const dbPath = [ds.database_name, ds.schema_name].filter(Boolean).join("/");
  return {
    type: ds.datasource_type,
    location: [hostPort, dbPath].filter(Boolean).join(" / ") || "—",
    table: ds.table_name || "—",
  };
}

const FailedDatasourcesDialog: React.FC<FailedDatasourcesDialogProps> = ({
  failedDatasources,
  onClose,
}) => {
  const [expandedIndex, setExpandedIndex] = useState<number | null>(null);

  const handleToggle = (index: number) => {
    setExpandedIndex((prev) => (prev === index ? null : index));
  };

  const handleClose = () => {
    setExpandedIndex(null);
    onClose();
  };

  return (
    <Dialog open={failedDatasources.length > 0} onOpenChange={(open) => !open && handleClose()}>
      <DialogContent className="p-0 max-w-[560px] overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Data Sources Not Connected</DialogTitle>
        <div className="min-w-0 flex items-center justify-between border-b border-border bg-amber-100 px-5 py-3 dark:bg-amber-900/30">
          <div className="flex items-center gap-2">
            <AlertTriangle className="h-5 w-5 text-amber-600 dark:text-amber-400" />
            <h2 className="text-base font-bold text-foreground">Data Sources Not Connected</h2>
          </div>
          <button
            type="button"
            onClick={handleClose}
            className="flex items-center justify-center h-6 w-6 rounded-full hover:bg-black/10 transition-colors"
            aria-label="Close"
          >
            <X className="h-4 w-4 text-foreground" />
          </button>
        </div>
        <div className="min-w-0 p-6 bg-card space-y-4">
          <p className="text-sm">
            The following data sources could not be reconnected. You can set them up again from the{" "}
            <strong>Data Sources</strong> tab.
          </p>
          <div className="space-y-2 max-h-[300px] overflow-y-auto">
            {failedDatasources.map((ds, i) => {
              const detail = formatDatasourceDetail(ds);
              const hasError = Boolean(ds.error);
              const isExpanded = expandedIndex === i;

              return (
                <div
                  key={`${detail.type}-${detail.table}-${i}`}
                  className="bg-muted/50 border border-border rounded overflow-hidden"
                >
                  <div className="flex items-start gap-3 p-3">
                    <Database className="h-4 w-4 mt-0.5 text-muted-foreground shrink-0" />
                    <div className="min-w-0 flex-1 text-sm space-y-0.5">
                      <div className="flex items-center gap-2">
                        <span className="font-medium uppercase text-xs px-1.5 py-0.5 bg-muted rounded">
                          {detail.type || "unknown"}
                        </span>
                        <span className="font-medium truncate">{detail.table}</span>
                      </div>
                      <p className="text-muted-foreground truncate">{detail.location}</p>
                    </div>
                    {hasError && (
                      <button
                        type="button"
                        onClick={() => handleToggle(i)}
                        className="shrink-0 mt-0.5 text-muted-foreground hover:text-foreground transition-colors"
                        aria-label={isExpanded ? "Hide error details" : "Show error details"}
                      >
                        {isExpanded ? (
                          <ChevronUp className="h-4 w-4" />
                        ) : (
                          <ChevronDown className="h-4 w-4" />
                        )}
                      </button>
                    )}
                  </div>
                  {hasError && isExpanded && (
                    <div className="border-t border-border bg-red-50 dark:bg-red-900/20 px-3 py-2">
                      <p className="text-xs text-red-700 dark:text-red-400 font-mono whitespace-pre-wrap break-all">
                        {ds.error}
                      </p>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          <div className="flex justify-end pt-2">
            <Button
              type="button"
              onClick={handleClose}
              className="bg-[#FFDF4B] text-[#212020] hover:bg-[#FFDF4B]/90 border border-[#212020] shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px]"
            >
              OK
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default FailedDatasourcesDialog;
