import { useCallback, useEffect } from "react";

export const useTabSwitchEffect = (handleTabChange: (value: string) => void) => {
  // Use useCallback to memoize the event handler
  const handleSwitchTab = useCallback(
    (event: CustomEvent) => {
      // If we have unsaved ontology code in memory, save it to global cache before switching tabs
      const currentTab = document
        .querySelector('.tab-item[data-state="active"]')
        ?.getAttribute("data-value");
      if (currentTab === "setup" && typeof globalThis.tempOntologyCode === "string") {
        globalThis.cachedOntologyCode = globalThis.tempOntologyCode;
        // Clear the temporary variable after saving
        globalThis.tempOntologyCode = undefined;
      }

      handleTabChange(event.detail);
    },
    [handleTabChange],
  );

  useEffect(() => {
    // Add event listener for tab switching
    window.addEventListener("switchTab", handleSwitchTab as EventListener);

    // Clean up
    return () => {
      window.removeEventListener("switchTab", handleSwitchTab as EventListener);
    };
  }, [handleSwitchTab]);
};
