import { useState } from "react";

import type { ContextNoteFilter, ContextShelf } from "../../types";
import { type NotesSelection, normalizeFolderPath, type VaultRef } from "../notesModel";

export const GLOBAL_VAULT: VaultRef = { scope: "global", scopeId: null, name: "Global" };

interface NotesPageState {
  vault: VaultRef;
  /** Folder the next created note lands in ("" = vault root). */
  folderPath: string;
  selection: NotesSelection;
  shelf: ContextShelf | null;
  searchQuery: string;
  /** Folders created in the UI that have no notes yet (folders are implicit in folder_path). */
  localFolders: string[];
}

const INITIAL_STATE: NotesPageState = {
  vault: GLOBAL_VAULT,
  folderPath: "",
  selection: { type: "none" },
  shelf: null,
  searchQuery: "",
  localFolders: [],
};

export interface UseNotesPageStateReturn extends NotesPageState {
  vaultFilter: ContextNoteFilter;
  selectVault: (vault: VaultRef) => void;
  selectNote: (noteId: string, vault: VaultRef, folderPath: string) => void;
  selectDocument: (documentId: string, vault: VaultRef) => void;
  /** Vault/folder title clicked — center shows the group's notes as cards. */
  selectCollection: (vault: VaultRef, folderPath: string) => void;
  /** Open an empty draft in the editor; nothing persists until Save. */
  startNewNote: () => void;
  clearSelection: () => void;
  setShelf: (shelf: ContextShelf | null) => void;
  setSearchQuery: (query: string) => void;
  addLocalFolder: (path: string) => void;
  setFolderPath: (path: string) => void;
}

export function useNotesPageState(initialVault?: VaultRef): UseNotesPageStateReturn {
  const [state, setState] = useState<NotesPageState>(() => ({
    ...INITIAL_STATE,
    vault: initialVault ?? GLOBAL_VAULT,
  }));

  const selectVault = (vault: VaultRef) =>
    setState((prev) => ({
      ...prev,
      vault,
      folderPath: "",
      selection: { type: "none" },
      localFolders: [],
    }));

  const selectNote = (noteId: string, vault: VaultRef, folderPath: string) =>
    setState((prev) => ({
      ...prev,
      vault,
      folderPath,
      selection: { type: "note", noteId },
    }));

  const selectDocument = (documentId: string, vault: VaultRef) =>
    setState((prev) => ({ ...prev, vault, selection: { type: "document", documentId } }));

  const selectCollection = (vault: VaultRef, folderPath: string) =>
    setState((prev) => ({
      ...prev,
      vault,
      folderPath: normalizeFolderPath(folderPath),
      selection: { type: "collection", folderPath: normalizeFolderPath(folderPath) },
      localFolders: prev.vault.scopeId === vault.scopeId ? prev.localFolders : [],
    }));

  const clearSelection = () => setState((prev) => ({ ...prev, selection: { type: "none" } }));

  const startNewNote = () => setState((prev) => ({ ...prev, selection: { type: "new" } }));

  const setShelf = (shelf: ContextShelf | null) => setState((prev) => ({ ...prev, shelf }));

  const setSearchQuery = (searchQuery: string) => setState((prev) => ({ ...prev, searchQuery }));

  const addLocalFolder = (path: string) => {
    const normalized = normalizeFolderPath(path);
    if (!normalized) return;
    setState((prev) => ({
      ...prev,
      folderPath: normalized,
      localFolders: prev.localFolders.includes(normalized)
        ? prev.localFolders
        : [...prev.localFolders, normalized],
    }));
  };

  const setFolderPath = (path: string) =>
    setState((prev) => ({ ...prev, folderPath: normalizeFolderPath(path) }));

  return {
    ...state,
    vaultFilter: { scope: state.vault.scope, scopeId: state.vault.scopeId },
    selectVault,
    selectNote,
    selectDocument,
    selectCollection,
    startNewNote,
    clearSelection,
    setShelf,
    setSearchQuery,
    addLocalFolder,
    setFolderPath,
  };
}
