import { useUpgradeWallStore } from "../store/upgradeWallStore";
import { ContactToUpgradeDialog } from "./ContactToUpgradeDialog";

/**
 * The single, globally-mounted freemium upgrade wall. Content is supplied by
 * whichever limit triggered it (see upgradeWallStore helpers). Mounted once in
 * App; never rendered per-feature.
 */
export const UpgradeWallDialog = () => {
  const isOpen = useUpgradeWallStore((s) => s.isOpen);
  const content = useUpgradeWallStore((s) => s.content);
  const closeWall = useUpgradeWallStore((s) => s.closeUpgradeWall);

  const handleOpenChange = (open: boolean) => {
    if (!open) closeWall();
  };

  return (
    <ContactToUpgradeDialog
      open={isOpen}
      onOpenChange={handleOpenChange}
      title={content?.title ?? ""}
      description={content?.description ?? ""}
      contactSubject={content?.contactSubject ?? ""}
    />
  );
};
