import { Lock, Power, Timer } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import type { AvailabilityResult, Machine, UserMachine } from "../utils";

export interface MachineToggleButtonProps {
  userMachine: UserMachine;
  machine: Machine;
  availabilityResult?: AvailabilityResult;
  onToggleActive?: (
    userMachineId: string,
    machineId: string,
    currentIsActive: boolean,
    autoterminationMinutes?: number,
  ) => Promise<void>;
  // `undefined` = eligibility not yet known; don't lock the UI while loading.
  // The backend remains the authority and will 402 if the user is ineligible.
  isPaidComputeEligible?: boolean;
  onPaidComputeRequired?: () => void;
}

const TRANSITIONAL_STATES = ["starting", "stopping", "pending", "restarting"] as const;

const STARTING_STATES = ["starting", "pending", "restarting"] as const;

const isTransitional = (status: string | undefined): boolean =>
  status !== undefined && (TRANSITIONAL_STATES as readonly string[]).includes(status);

const isStarting = (status: string | undefined): boolean =>
  status !== undefined && (STARTING_STATES as readonly string[]).includes(status);

const renderStartTooltip = (machineStatus: string | undefined): string => {
  if (machineStatus === "stopping") return "Cannot start - machine is still stopping";
  if (isStarting(machineStatus)) return "Cannot start - another instance is still starting";
  return "Click to start this machine";
};

export const MachineToggleButton: React.FC<MachineToggleButtonProps> = ({
  userMachine,
  machine,
  availabilityResult,
  onToggleActive,
  isPaidComputeEligible,
  onPaidComputeRequired,
}) => {
  const [startPopoverOpen, setStartPopoverOpen] = useState(false);
  const [autoTermMinutes, setAutoTermMinutes] = useState(
    userMachine.autotermination_minutes != null ? String(userMachine.autotermination_minutes) : "",
  );

  if (userMachine.status !== "Enabled") return null;

  const machineStatus = availabilityResult?.machine_status;
  const isFree = machine.cost_per_machine === 0;
  // Lock the Start button when we know the user is ineligible AND the machine
  // is not free. We never lock free machines; we never lock during loading
  // (isPaidComputeEligible === undefined) — let the backend be the authority.
  const isLocked = !isFree && isPaidComputeEligible === false;

  const handleStopClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onToggleActive?.(userMachine.id, machine.id, userMachine.is_active);
  };

  const handleStartMachine = () => {
    setStartPopoverOpen(false);
    const minutes = autoTermMinutes ? parseInt(autoTermMinutes, 10) : undefined;
    onToggleActive?.(userMachine.id, machine.id, userMachine.is_active, minutes);
  };

  const handleLockedClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onPaidComputeRequired?.();
  };

  const handlePopoverOpenChange = (open: boolean) => {
    setStartPopoverOpen(open);
    if (open) {
      setAutoTermMinutes(
        userMachine.autotermination_minutes != null
          ? String(userMachine.autotermination_minutes)
          : "",
      );
    }
  };

  if (userMachine.is_active) {
    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              type="button"
              variant="default"
              size="sm"
              className="h-6 px-2 text-xs"
              disabled={machineStatus === "stopping"}
              onClick={handleStopClick}
            >
              <Power className="w-2 h-2 mr-1" />
              {machineStatus === "stopping" ? "Stopping..." : "Stop"}
            </Button>
          </TooltipTrigger>
          <TooltipContent>
            <p>
              {machineStatus === "stopping"
                ? "Machine is shutting down..."
                : "Click to stop this machine and clean up resources"}
            </p>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  if (isLocked) {
    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="h-6 px-2 text-xs"
              onClick={handleLockedClick}
            >
              <Lock className="w-2 h-2 mr-1" />
              Start
            </Button>
          </TooltipTrigger>
          <TooltipContent>
            <p>Subscription required to start paid compute. Click to set up billing.</p>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  if (isFree) {
    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="h-6 px-2 text-xs"
              disabled={isTransitional(machineStatus)}
              onClick={(e) => {
                e.stopPropagation();
                onToggleActive?.(userMachine.id, machine.id, userMachine.is_active);
              }}
            >
              <Power className="w-2 h-2 mr-1" />
              Start
            </Button>
          </TooltipTrigger>
          <TooltipContent>
            <p>{renderStartTooltip(machineStatus)}</p>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  return (
    <Popover open={startPopoverOpen} onOpenChange={handlePopoverOpenChange}>
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>
            <PopoverTrigger asChild>
              <Button
                type="button"
                variant="outline"
                size="sm"
                className="h-6 px-2 text-xs"
                disabled={isTransitional(machineStatus)}
                onClick={(e) => e.stopPropagation()}
              >
                <Power className="w-2 h-2 mr-1" />
                Start
              </Button>
            </PopoverTrigger>
          </TooltipTrigger>
          <TooltipContent>
            <p>{renderStartTooltip(machineStatus)}</p>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
      <PopoverContent className="w-64 p-3" align="end" onClick={(e) => e.stopPropagation()}>
        <div className="space-y-3">
          <div className="flex items-center gap-2 text-xs font-medium">
            <Timer className="w-3 h-3 text-muted-foreground" />
            Auto-terminate after inactivity
          </div>
          <div className="flex items-center gap-2">
            <Input
              type="number"
              min={1}
              placeholder="disabled"
              className="h-7 text-xs w-20"
              value={autoTermMinutes}
              onChange={(e) => setAutoTermMinutes(e.target.value)}
            />
            <span className="text-xs text-muted-foreground">min</span>
          </div>
          <div className="flex gap-1">
            {[30, 60, 120].map((m) => (
              <Button
                key={m}
                type="button"
                variant={autoTermMinutes === String(m) ? "secondary" : "ghost"}
                size="sm"
                className="h-5 px-2 text-[10px]"
                onClick={() => setAutoTermMinutes(autoTermMinutes === String(m) ? "" : String(m))}
              >
                {m}m
              </Button>
            ))}
          </div>
          <Button
            type="button"
            size="sm"
            className="w-full h-7 text-xs"
            onClick={handleStartMachine}
          >
            <Power className="w-3 h-3 mr-1" />
            Start Machine
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
};
