import { useQuery } from "@tanstack/react-query";
import type { LoginSession } from "./loginActivity.types";
import { loginActivityApi } from "./loginActivityApi";

const LOGIN_ACTIVITY_QUERY_KEY = ["login-activity"] as const;

interface UseLoginActivityReturn {
  sessions: LoginSession[];
  isLoading: boolean;
  error: Error | null;
}

export function useLoginActivity(): UseLoginActivityReturn {
  const query = useQuery<LoginSession[], Error>({
    queryKey: LOGIN_ACTIVITY_QUERY_KEY,
    queryFn: () => loginActivityApi.fetchLoginActivity(),
    staleTime: 60_000,
  });

  return {
    sessions: query.data ?? [],
    isLoading: query.isLoading,
    error: query.error ?? null,
  };
}
