import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { useEffect } from "react";
import { BrowserRouter, useLocation } from "react-router-dom";
import { AuthProvider, useAuth } from "@/features/auth/components/AuthProvider";
import { useApiToken } from "@/features/auth/hooks/useApiToken";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { captureOAuthTokens } from "@/features/auth/utils/oauthTokenCapture";
import { UpgradeWallDialog } from "@/features/billing/components/UpgradeWallDialog";
import CodeAssistantPanel from "@/features/code-assistant/components/CodeAssistantPanel";
import { useChatReservedWidth } from "@/features/code-assistant/hooks/useChatReservedWidth";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { GlobalStartMachineModal } from "@/features/compute/components/GlobalStartMachineModal";
import { MachineStatusProvider } from "@/features/compute/context/MachineStatusContext";
import { ConceptEditorClientProvider } from "@/features/concept-editor/api/ConceptEditorClientContext";
import { useConceptRefresh } from "@/features/concepts/hooks/useConceptRefresh";
import { EngineProvisioningOverlay } from "@/features/engine-status/components/EngineProvisioningOverlay";
import { ensureEngineReady } from "@/features/engine-status/engineStatus";
import { useEngineProvisioning } from "@/features/engine-status/hooks/useEngineProvisioning";
import { useSharedOntologiesSelfHeal } from "@/features/ontologies/sharing/hooks/useSharedOntologiesSelfHeal";
import { useConfigLoader } from "@/features/settings/hooks/useConfigLoader";
import { Toaster as Sonner } from "@/shared/components/ui/sonner";
import { Toaster } from "@/shared/components/ui/toaster";
import { TooltipProvider } from "@/shared/components/ui/tooltip";
import { useDocumentTitle } from "@/shared/hooks/useDocumentTitle";
import { usePageviewTracking } from "@/shared/hooks/usePageviewTracking";
import { isHomePath } from "@/shared/utils/isHomePath";
import AppRoutes from "./AppRoutes";

// Configure the query client with appropriate default options
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: true,
      staleTime: 30000,
      retry: 1,
    },
  },
});

const AppContent = () => {
  const location = useLocation();
  const { user } = useAuth();
  const canSeeAiAgent = usePermissionsStore((state) => state.canSee("can_see_ai_agent"));
  const showAiAssistant = Boolean(user && canSeeAiAgent);
  const { messages, userClosedPanel, isPanelOpen, togglePanel } = useCodeAssistantStore();
  const chatReservedWidth = useChatReservedWidth();
  const isProvisioning = useEngineProvisioning(Boolean(user));

  // Auto-open the panel on navigation when a conversation is in progress,
  // unless the user explicitly closed it. Force-close on the home page since
  // the chat is already embedded there.
  useEffect(() => {
    if (!showAiAssistant) return;
    if (isHomePath(location.pathname)) {
      if (isPanelOpen) togglePanel();
      return;
    }
    if (messages.length > 0 && !userClosedPanel && !isPanelOpen) {
      togglePanel();
    }
  }, [
    location.pathname,
    showAiAssistant,
    isPanelOpen,
    messages.length,
    togglePanel,
    userClosedPanel,
  ]); // eslint-disable-line react-hooks/exhaustive-deps

  // CRITICAL: Capture OAuth tokens immediately on app load
  useEffect(() => {
    captureOAuthTokens();
  }, []);

  // On the home page, proactively check the engine is up so we can show a
  // friendly "stopped or provisioning" message (instead of a raw "Failed to
  // fetch") when the backend is still being created. Scoped to home so we never
  // interfere with execution buttons elsewhere.
  useEffect(() => {
    if (!user) return;
    if (isHomePath(location.pathname)) void ensureEngineReady();
  }, [location.pathname, user]);

  usePageviewTracking(); // Emit a $pageview on each SPA route change
  useDocumentTitle(); // Keep the browser tab / history title in sync with the route
  useApiToken(); // Initialize API token management
  useConceptRefresh(); // Initialize concept refresh functionality
  useConfigLoader(); // Load user configuration from backend
  useSharedOntologiesSelfHeal(); // Auto-recover when a shared share is revoked mid-session

  return (
    <>
      <div className="flex h-screen overflow-hidden">
        <div className="flex-1 min-w-0 overflow-hidden" style={{ paddingLeft: chatReservedWidth }}>
          <AppRoutes />
        </div>
        {showAiAssistant && <CodeAssistantPanel />}
      </div>
      {isProvisioning && <EngineProvisioningOverlay />}
      <UpgradeWallDialog />
    </>
  );
};

const App = () => {
  // Get the base path from environment variable, default to '/'
  const basePath = import.meta.env.VITE_BASE_PATH || "/";

  return (
    <BrowserRouter basename={basePath}>
      <QueryClientProvider client={queryClient}>
        <TooltipProvider>
          <Toaster />
          <Sonner />
          <AuthProvider>
            <ConceptEditorClientProvider>
              <MachineStatusProvider>
                <GlobalStartMachineModal />
                <AppContent />
              </MachineStatusProvider>
            </ConceptEditorClientProvider>
          </AuthProvider>
        </TooltipProvider>
      </QueryClientProvider>
    </BrowserRouter>
  );
};

export default App;
