import { RecordCountFooter } from "./ConceptCardBadges";

interface ConceptCardBodyProps {
  fields: [string, string][];
  isExpanded: boolean;
  isPopulated?: boolean;
  rowCount?: number;
  executionTimeMs?: number;
  hasContext?: boolean;
  conceptType?: "logic" | "sql" | "cypher" | "python" | "context" | "llm";
}

/**
 * The card's lower body: the row-count footer (shown on every populated card,
 * collapsed or expanded) preceded by the column list (name + type) that appears
 * only while the card is expanded. Renders nothing when there is neither a field
 * list to show nor a count to report.
 */
export function ConceptCardBody({
  fields,
  isExpanded,
  isPopulated,
  rowCount,
  executionTimeMs,
  hasContext,
  conceptType,
}: ConceptCardBodyProps) {
  const hasRowCount = Boolean(isPopulated && rowCount && rowCount > 0);
  const showFields = isExpanded && fields.length > 0;
  if (!showFields && !hasRowCount && !hasContext && !conceptType) return null;
  return (
    <div className="dark:bg-flow-node-bg rounded-b-lg overflow-hidden">
      {showFields && (
        <div className="divide-y divide-border/50">
          {fields.map(([fieldName, fieldType]) => (
            <div
              key={fieldName}
              className="flex items-center justify-between px-3 py-1.5 text-base"
            >
              <span className="text-foreground/80 truncate mr-2" title={fieldName}>
                {fieldName}
              </span>
              <span className="text-muted-foreground font-mono text-sm bg-muted/50 px-1.5 py-0.5 rounded flex-shrink-0">
                {fieldType}
              </span>
            </div>
          ))}
        </div>
      )}
      <RecordCountFooter
        isPopulated={isPopulated}
        count={rowCount}
        executionTimeMs={executionTimeMs}
        hasContext={hasContext}
        conceptType={conceptType}
      />
    </div>
  );
}
