import {
  Bot,
  Brain,
  Database,
  Key,
  type LucideIcon,
  Receipt,
  Server,
  SlidersHorizontal,
  Users2,
} from "lucide-react";
import { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { BillingSettings } from "@/features/billing/components/BillingSettings";
import { Separator } from "@/shared/components/ui/separator";
import AssistantSettings from "./AssistantSettings";
import AuthSettings from "./AuthSettings";
import { ApiKeys } from "./api-keys/ApiKeys";
import ModelSettings from "./ModelSettings";
import PreferencesSettings from "./PreferencesSettings";
import ServiceUrlSettings from "./ServiceUrlSettings";
import { SettingsNavList } from "./SettingsNavList";
import { SettingsSectionHeader } from "./SettingsSectionHeader";
import WorkspaceSettings from "./WorkspaceSettings";

interface SettingsPanelProps {
  settingsEnabled: boolean;
  onBack?: () => void;
  previousTab?: string;
}

type SettingsSection =
  | "main"
  | "api"
  | "llm"
  | "assistant"
  | "workspace"
  | "api-keys"
  | "billing"
  | "preferences";

const SettingsPanel = ({
  settingsEnabled,
  onBack,
  previousTab = "overview",
}: SettingsPanelProps) => {
  const location = useLocation();
  const navigate = useNavigate();
  const canSeeApiConfiguration = usePermissionsStore((state) =>
    state.canSee("can_see_api_configuration"),
  );
  const canSeeTeams = usePermissionsStore((state) => state.canSee("can_see_teams"));
  const [currentSection, setCurrentSection] = useState<SettingsSection>("main");

  // Effect to handle initial navigation state
  useEffect(() => {
    const state = location.state as any;
    if (state?.settingsSection) {
      setCurrentSection(state.settingsSection as SettingsSection);
    }
  }, [location.state]);

  // Deep-link support for /settings/billing — the Stripe checkout/portal
  // redirects land here, so the panel must open the billing section when the
  // URL matches even if there's no router state.
  useEffect(() => {
    if (location.pathname.startsWith("/settings/billing")) {
      setCurrentSection("billing");
    }
  }, [location.pathname]);

  const renderMainSettings = () => {
    // Teams navigates to the standalone Teams page (list + detail at /teams and
    // /teams/:teamId; entry point moved here from the sidebar). Teams and API
    // Configuration are permission-gated; the rest are always shown.
    const cards = [
      {
        key: "preferences",
        icon: SlidersHorizontal,
        title: "Preferences",
        description:
          "Personalize appearance and editor defaults like theme, default cell view, and code wrapping",
        onClick: () => setCurrentSection("preferences"),
        visible: true,
      },
      {
        key: "api",
        icon: Server,
        title: "API Configuration",
        description: "Configure service URLs and authentication tokens for API connections",
        onClick: () => setCurrentSection("api"),
        visible: canSeeApiConfiguration,
      },
      {
        key: "llm",
        icon: Brain,
        title: "LLM Configuration",
        description: "Configure language models and embedding settings for AI features.",
        onClick: () => setCurrentSection("llm"),
        visible: true,
      },
      {
        key: "assistant",
        icon: Bot,
        title: "AI Assistant",
        description:
          "Set the default mode (agent or read-only ask) and manage which actions the assistant may run without asking",
        onClick: () => setCurrentSection("assistant"),
        visible: true,
      },
      {
        key: "api-keys",
        icon: Key,
        title: "API Keys",
        description: "Create and manage API keys for programmatic access to Prometheux",
        onClick: () => setCurrentSection("api-keys"),
        visible: true,
      },
      {
        key: "billing",
        icon: Receipt,
        title: "Billing",
        description: "Manage your subscription, payment method, and view invoice history",
        onClick: () => setCurrentSection("billing"),
        visible: true,
      },
      {
        key: "teams",
        icon: Users2,
        title: "Teams",
        description: "Create teams, manage members, and respond to invitations",
        onClick: () => navigate("/teams"),
        visible: canSeeTeams,
      },
      {
        key: "workspace",
        icon: Database,
        title: "Workspace Management",
        description: "Export and import workspace data including ontologies and tables",
        onClick: () => setCurrentSection("workspace"),
        visible: true,
      },
    ];

    return (
      <div className="mx-6 mb-6 mt-6 space-y-5">
        <p className="text-sm text-muted-foreground">
          Manage your account, workspace, and platform configuration.
        </p>
        <SettingsNavList items={cards.filter((card) => card.visible)} />
      </div>
    );
  };

  const sectionHeader = (icon: LucideIcon, title: string, description: string) => (
    <SettingsSectionHeader
      icon={icon}
      title={title}
      description={description}
      onBack={() => setCurrentSection("main")}
    />
  );

  const renderPreferences = () => (
    <>
      {sectionHeader(
        SlidersHorizontal,
        "Preferences",
        "Personalize appearance and editor defaults",
      )}
      <div className="mx-6 mb-6">
        <PreferencesSettings />
      </div>
    </>
  );

  const renderApiSettings = () => (
    <>
      {sectionHeader(
        Server,
        "API Configuration",
        "Configure service URLs and authentication tokens for API connections",
      )}
      <div className="space-y-6 mx-6 mb-6">
        <ServiceUrlSettings />
        <Separator />
        <AuthSettings />
      </div>
    </>
  );

  const renderLlmSettings = () => (
    <>
      {sectionHeader(
        Brain,
        "LLM Configuration",
        "Configure language models and embedding settings for AI features",
      )}
      <div className="mx-6 mb-6">
        <ModelSettings />
      </div>
    </>
  );

  const renderAssistantSettings = () => (
    <>
      {sectionHeader(Bot, "AI Assistant", "Set the default mode and manage always-allowed actions")}
      <div className="mx-6 mb-6">
        <AssistantSettings />
      </div>
    </>
  );

  const renderApiKeysSettings = () => (
    <>
      {sectionHeader(
        Key,
        "API Keys",
        "Create and manage API keys for programmatic access to Prometheux",
      )}
      <div className="mx-6 mb-6">
        <ApiKeys />
      </div>
    </>
  );

  const renderBillingSettings = () => (
    <>
      {sectionHeader(
        Receipt,
        "Billing",
        "Manage your subscription, payment method, and view invoice history",
      )}
      <div className="mx-6 mb-6">
        <BillingSettings />
      </div>
    </>
  );

  const renderWorkspaceSettings = () => (
    <>
      {sectionHeader(
        Database,
        "Workspace Management",
        "Export and import workspace data including ontologies and tables",
      )}
      <div className="mx-6 mb-6">
        <WorkspaceSettings />
      </div>
    </>
  );

  switch (currentSection) {
    case "preferences":
      return renderPreferences();
    case "api":
      return canSeeApiConfiguration ? renderApiSettings() : renderMainSettings();
    case "llm":
      return renderLlmSettings();
    case "assistant":
      return renderAssistantSettings();
    case "api-keys":
      return renderApiKeysSettings();
    case "billing":
      return renderBillingSettings();
    case "workspace":
      return renderWorkspaceSettings();
    default:
      return renderMainSettings();
  }
};

export default SettingsPanel;
