import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { OntologySnapshotMeta } from "@/features/ontologies/api";
import { type OntologyScope, OntologyService } from "@/features/ontologies/api";

const SNAPSHOTS_KEY = ["ontology", "snapshots"] as const;
const snapshotsKey = (ontologyId: string) => [...SNAPSHOTS_KEY, ontologyId] as const;

interface UseOntologySnapshotsReturn {
  snapshots: OntologySnapshotMeta[];
  isLoading: boolean;
  isFetching: boolean;
  error: Error | null;
  create: (description?: string) => Promise<OntologySnapshotMeta>;
  restore: (snapshotId: string, createSafetySnapshot?: boolean) => Promise<void>;
  remove: (snapshotId: string) => Promise<void>;
  refresh: () => void;
  isCreating: boolean;
  isRestoring: boolean;
  isDeleting: boolean;
}

export function useOntologySnapshots(
  ontologyId: string | null,
  scope: OntologyScope = "user",
): UseOntologySnapshotsReturn {
  const queryClient = useQueryClient();

  const query = useQuery<OntologySnapshotMeta[], Error>({
    queryKey: snapshotsKey(ontologyId ?? ""),
    queryFn: () => OntologyService.listSnapshots(ontologyId!, scope),
    enabled: Boolean(ontologyId),
    staleTime: 30_000,
    refetchOnWindowFocus: false,
  });

  const createMutation = useMutation<OntologySnapshotMeta, Error, string | undefined>({
    mutationFn: (description) => OntologyService.createSnapshot(ontologyId!, scope, description),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: snapshotsKey(ontologyId ?? "") });
    },
  });

  const restoreMutation = useMutation<
    void,
    Error,
    { snapshotId: string; createSafetySnapshot: boolean }
  >({
    mutationFn: ({ snapshotId, createSafetySnapshot }) =>
      OntologyService.restoreSnapshot(snapshotId, ontologyId!, scope, createSafetySnapshot),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: snapshotsKey(ontologyId ?? "") });
    },
  });

  const deleteMutation = useMutation<void, Error, string>({
    mutationFn: (snapshotId) => OntologyService.deleteSnapshot(snapshotId, ontologyId!, scope),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: snapshotsKey(ontologyId ?? "") });
    },
  });

  return {
    snapshots: query.data ?? [],
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    create: (description) => createMutation.mutateAsync(description),
    restore: (snapshotId, createSafetySnapshot = true) =>
      restoreMutation.mutateAsync({ snapshotId, createSafetySnapshot }),
    remove: (snapshotId) => deleteMutation.mutateAsync(snapshotId),
    refresh: () => queryClient.invalidateQueries({ queryKey: snapshotsKey(ontologyId ?? "") }),
    isCreating: createMutation.isPending,
    isRestoring: restoreMutation.isPending,
    isDeleting: deleteMutation.isPending,
  };
}
