import { Download } from "lucide-react";
import { useCallback, useMemo } from "react";
import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";
import { trackAppInteraction } from "@/shared/services/analyticsEvents";
import type { FetchResult } from "../../../api/ConceptClient";
import { useTabContext } from "../../../runtime/tabContext";
import { columnIndex } from "../../../runtime/useConceptRows";
import type { AppWidgetDef, FormatRule } from "../../../schema/appDefinition.types";
import { downloadCsv } from "../../../utils/csvExport";
import { TableOutput } from "../../outputs/TableOutput";
import type { BoundTableHandlers } from "../../outputs/table/tableOutput.types";
import { buildProjection, formatCell, ontologyData, ontologyHandlers } from "./richTable.utils";

interface RichTableWidgetProps {
  widget: AppWidgetDef;
  data: FetchResult;
  handlers?: BoundTableHandlers;
}

const TEXT_FORMAT_CLASSES: Record<string, string> = {
  red: "text-red-600 dark:text-red-400 font-medium",
  green: "text-green-600 dark:text-green-400 font-medium",
  amber: "text-amber-600 dark:text-amber-400 font-medium",
  blue: "text-blue-600 dark:text-blue-400 font-medium",
  neutral: "text-muted-foreground",
};

const BADGE_FORMAT_CLASSES: Record<string, string> = {
  red: "bg-red-50 text-red-700 dark:bg-red-900/20 dark:text-red-400",
  green: "bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-400",
  amber: "bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
  blue: "bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
  neutral: "bg-secondary text-muted-foreground",
};

function ruleMatches(rule: FormatRule, cell: unknown): boolean {
  const numeric = Number(cell);
  const target = Number(rule.value);
  if (rule.operator === "less_than") return numeric < target;
  if (rule.operator === "greater_than") return numeric > target;
  if (rule.operator === "equals") return String(cell) === String(rule.value);
  return String(cell) !== String(rule.value);
}

/**
 * rich_table (ADR D4): server-side pagination/filter/sort via the tap
 * handlers, CSV export, `columns` subset/order, per-column value formats,
 * conditional formatting (colored text or badge pills) and row-select →
 * tab context (the drill-down mechanism). `variant` scales the chrome down
 * for detail panels.
 */
export function RichTableWidget({ widget, data, handlers }: RichTableWidgetProps) {
  const { values, setValue } = useTabContext();
  const variant = widget.variant ?? "full";
  const selectedRecord = widget.onRowSelect ? values[widget.onRowSelect.set] : undefined;

  const projection = useMemo(
    () => buildProjection(data.columnNames, widget.columns),
    [data.columnNames, widget.columns],
  );
  const view = useMemo(
    () => (projection ? ontologyData(data, projection) : data),
    [data, projection],
  );
  const viewHandlers = useMemo(() => {
    if (!handlers) return undefined;
    return projection ? ontologyHandlers(handlers, projection) : handlers;
  }, [handlers, projection]);

  const ruleColumns = useMemo(() => {
    const map = new Map<number, FormatRule[]>();
    for (const rule of widget.formatRules ?? []) {
      const index = columnIndex(view.columnNames, rule.column);
      if (index >= 0) map.set(index, [...(map.get(index) ?? []), rule]);
    }
    return map;
  }, [widget.formatRules, view.columnNames]);

  const formatColumns = useMemo(() => {
    const map = new Map<number, "number" | "percent" | "signed_percent">();
    for (const [column, format] of Object.entries(widget.columnFormats ?? {})) {
      const index = columnIndex(view.columnNames, column);
      if (index >= 0) map.set(index, format);
    }
    return map;
  }, [widget.columnFormats, view.columnNames]);

  const renderCell = useCallback(
    (cell: unknown, _rowIndex: number, colIndex: number) => {
      if (cell === null || cell === undefined) {
        return <span className="italic text-muted-foreground">null</span>;
      }
      const text = formatCell(cell, formatColumns.get(colIndex));
      const matched = (ruleColumns.get(colIndex) ?? []).find((rule) => ruleMatches(rule, cell));
      if (!matched) return text;
      if (matched.display === "badge") {
        return (
          <span
            className={cn(
              "inline-block px-2 py-px rounded-full text-[11px] font-medium",
              BADGE_FORMAT_CLASSES[matched.color],
            )}
          >
            {text}
          </span>
        );
      }
      return <span className={TEXT_FORMAT_CLASSES[matched.color]}>{text}</span>;
    },
    [ruleColumns, formatColumns],
  );

  const handleRowClick = useCallback(
    (rowIndex: number) => {
      if (!widget.onRowSelect) return;
      // Publish the FULL row (all fetched columns), not just the displayed subset.
      const record = Object.fromEntries(
        data.columnNames.map((column, index) => [column, data.rows[rowIndex]?.[index]]),
      );
      setValue(widget.onRowSelect.set, record);
      trackAppInteraction({ type: "row_select" });
    },
    [widget.onRowSelect, data, setValue],
  );

  // The selected row is whichever row matches the record published under the
  // widget's variable — identity by cell values, so it survives re-fetches
  // and clears naturally when the row falls off the current page.
  const isRowSelected = useCallback(
    (rowIndex: number) => {
      if (!selectedRecord || typeof selectedRecord !== "object") return false;
      const record = selectedRecord as Record<string, unknown>;
      return data.columnNames.every(
        (column, index) => record[column] === data.rows[rowIndex]?.[index],
      );
    },
    [selectedRecord, data],
  );

  const selectableRowClassName = useCallback(
    (rowIndex: number) =>
      cn("cursor-pointer hover:bg-accent/60", isRowSelected(rowIndex) && "bg-accent"),
    [isRowSelected],
  );

  const handleExport = () => {
    downloadCsv(view.columnNames, view.rows, widget.label ?? widget.id);
  };

  const hasDecorations = ruleColumns.size > 0 || formatColumns.size > 0;

  return (
    <div className="flex flex-col gap-2">
      {variant === "full" && (
        <div className="flex justify-end">
          <Button variant="ghost" size="sm" className="gap-1.5 text-xs" onClick={handleExport}>
            <Download className="h-3.5 w-3.5" />
            CSV
          </Button>
        </div>
      )}
      <TableOutput
        data={view}
        handlers={viewHandlers}
        chrome={variant}
        renderCell={hasDecorations ? renderCell : undefined}
        onRowClick={widget.onRowSelect ? handleRowClick : undefined}
        rowClassName={widget.onRowSelect ? selectableRowClassName : undefined}
      />
    </div>
  );
}
