import { useCallback, useMemo } from "react";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { trackAppInteraction } from "@/shared/services/analyticsEvents";
import type { FormValues } from "../../forms/FormWidget";
import { TabContextProvider, useTabContext } from "../../runtime/tabContext";
import { isGroupBusy, useRunGroups } from "../../runtime/useRunGroups";
import type { AppPageDef } from "../../schema/appDefinition.types";
import { AppSectionView } from "./AppSectionView";
import type { TabRuntime } from "./AppWidgetRenderer";

interface AppTabViewProps {
  page: AppPageDef;
}

/**
 * One app tab (ADR D9): mounts its own context and run-group engine, both
 * scoped to this page's single project. Form submissions publish their values
 * into the context under "formId.fieldId" keys and fire the bound run group
 * in the same tick (values passed as overrides — state has not flushed yet).
 */
function AppTabBody({ page }: AppTabViewProps) {
  const ontologyId = page.project.id;
  const { setValues } = useTabContext();
  const runGroups = useRunGroups(page, ontologyId);

  // Check if any run group is currently executing or waiting for the engine
  const isAnyGroupRunning = useMemo(
    () => Object.values(runGroups.groupState).some(isGroupBusy),
    [runGroups.groupState],
  );

  const onSubmitForm = useCallback(
    (formId: string, values: FormValues) => {
      const flattened = Object.fromEntries(
        Object.entries(values).map(([fieldId, value]) => [`${formId}.${fieldId}`, value]),
      );
      setValues(flattened);
      trackAppInteraction({ type: "form_submit", tabId: page.id, ontologyId });
      const boundGroup = page.runGroups.find(
        (group) => group.trigger === "form" && group.formId === formId,
      );
      if (boundGroup) void runGroups.runGroup(boundGroup.id, flattened);
    },
    [page.runGroups, runGroups, setValues],
  );

  const runtime: TabRuntime = { page, ontologyId, onSubmitForm, ...runGroups };

  return (
    <div className="relative flex flex-col gap-5">
      {/* Global loading indicator */}
      {isAnyGroupRunning && (
        <div className="fixed right-4 top-4 flex items-center gap-2 text-sm text-foreground/70">
          <PrometheuxSpinner size={16} />
          <span>Loading...</span>
        </div>
      )}
      {page.sections.map((section) => (
        <AppSectionView key={section.id} section={section} runtime={runtime} />
      ))}
    </div>
  );
}

export function AppTabView({ page }: AppTabViewProps) {
  return (
    <TabContextProvider page={page}>
      <AppTabBody page={page} />
    </TabContextProvider>
  );
}
