import { ArrowUp, Database, Paperclip } from "lucide-react";
import { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { AuthForm } from "@/features/auth/components/AuthForm";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { LoginIntroOverlay } from "@/features/auth/components/LoginIntroOverlay";
import { useAuthHandlers } from "@/features/auth/hooks/useAuthHandlers";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { hasCapturedTokens } from "@/features/auth/utils/oauthTokenCapture";
import AttachedFilesPreview from "@/features/ontologies/components/AttachedFilesPreview";
import { HeroLoadingScreen } from "@/shared/components/HeroLoadingScreen";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { useForceLightTheme } from "@/shared/hooks/useForceLightTheme";

// Lovable-style outlined social button
const AuthModalSocialButton = ({
  onClick,
  label,
  children,
}: {
  onClick: () => void;
  label: string;
  children: React.ReactNode;
}) => (
  <button
    onClick={onClick}
    className="w-full flex items-center justify-between px-5 py-3 bg-white border border-gray-200 hover:border-gray-400 transition-colors text-sm font-medium text-[#212020]"
    style={{ borderRadius: "10px" }}
  >
    <span className="w-5">{children}</span>
    <span className="flex-1 text-center">{label}</span>
    <span className="w-5" />
  </button>
);

// Email section that expands the full AuthForm
const AuthEmailSection = ({
  isSignUp,
  onToggleMode,
}: {
  isSignUp: boolean;
  onToggleMode: () => void;
}) => {
  const [expanded, setExpanded] = useState(false);
  if (!expanded) {
    return (
      <button
        onClick={() => setExpanded(true)}
        className="w-full py-3 bg-[#1828FF] text-white text-sm font-semibold uppercase tracking-wider shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px] transition-all"
        style={{ borderRadius: "10px" }}
      >
        Continue with username or email
      </button>
    );
  }
  return <AuthForm isSignUp={isSignUp} onToggleMode={onToggleMode} />;
};

const PLACEHOLDERS = [
  "I want to understand the root cause of...",
  "Where in the patient journey are we losing patients before treatment?",
  "Where are the biggest single points of failure in our supply chain?",
  "What is the root cause of this service outage?",
  "Show me the network behind this suspicious transaction.",
  "Which customers are most at risk of churning this quarter?",
];

const INTRO_DURATION = 2000;
const FADE_DURATION = 800;

const Login = () => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [isProcessingOAuth, setIsProcessingOAuth] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [query, setQuery] = useState("");
  const [attachedFiles, setAttachedFiles] = useState<File[]>([]);
  const [placeholderIndex, setPlaceholderIndex] = useState(0);
  const [displayedPlaceholder, setDisplayedPlaceholder] = useState("");

  // Intro animation state
  const [introVisible, setIntroVisible] = useState(true);
  const [introFading, setIntroFading] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();
  const { loading: authLoading, hasPlatformAccess, user } = useAuth();
  const { handleGoogleLogin, handleMicrosoftLogin } = useAuthHandlers("", "", isSignUp);

  useForceLightTheme();

  // Intro: play once then fade out
  useEffect(() => {
    const fadeTimer = setTimeout(() => setIntroFading(true), INTRO_DURATION);
    const hideTimer = setTimeout(() => setIntroVisible(false), INTRO_DURATION + FADE_DURATION);
    return () => {
      clearTimeout(fadeTimer);
      clearTimeout(hideTimer);
    };
  }, []);

  // Typewriter effect
  useEffect(() => {
    if (introVisible) return; // don't start typewriter until intro done
    const full = PLACEHOLDERS[placeholderIndex];
    let i = 0;
    setDisplayedPlaceholder("");
    const typeInterval = setInterval(() => {
      i++;
      setDisplayedPlaceholder(full.slice(0, i));
      if (i >= full.length) {
        clearInterval(typeInterval);
        setTimeout(() => {
          setPlaceholderIndex((prev) => (prev + 1) % PLACEHOLDERS.length);
        }, 2500);
      }
    }, 38);
    return () => clearInterval(typeInterval);
  }, [placeholderIndex, introVisible]);

  useEffect(() => {
    const hasTokens = hasCapturedTokens();
    if (hasTokens) setIsProcessingOAuth(true);
    if (user && !authLoading) {
      if (!hasPlatformAccess) {
        navigate("/onboarding", { replace: true });
        return;
      }
      // Prefer the page the user was trying to reach (preserved as `from`),
      // then defaultRoute (first available page based on permissions), then root.
      const { defaultRoute } = usePermissionsStore.getState();
      const from = (location.state as any)?.from?.pathname;
      navigate(from ?? defaultRoute ?? "/", { replace: true });
    }
  }, [user, authLoading, hasPlatformAccess, navigate, location.state]);

  const handleSend = () => {
    if (query.trim()) {
      setIsSignUp(true);
      setShowAuthModal(true);
    }
  };

  // OAuth loading state
  if ((authLoading && user) || isProcessingOAuth) {
    const loadingMessage = isProcessingOAuth
      ? "Please wait while we securely sign you in…"
      : "Checking your permissions…";
    return <HeroLoadingScreen size={280} showLogo message={loadingMessage} />;
  }

  return (
    <div className="min-h-screen relative overflow-hidden" style={{ background: "#f2f2f2" }}>
      {/* Always-visible logo — top left, above all layers */}
      <img src="/prometheux-logo.png" alt="Prometheux" className="fixed top-5 left-8 h-8 z-[60]" />

      {/* ── Intro animation overlay ── */}
      <LoginIntroOverlay
        visible={introVisible}
        fading={introFading}
        fadeDurationMs={FADE_DURATION}
      />

      {/* ── Login page (fades in as intro fades out) ── */}
      <div
        className="min-h-screen flex flex-col relative"
        style={{
          opacity: introFading ? 1 : 0,
          transition: `opacity ${FADE_DURATION}ms ease-in-out`,
        }}
      >
        {/* Decorative hero cubes */}
        <img
          src="/platform-hero-img-left.svg"
          aria-hidden="true"
          className="hidden lg:block absolute pointer-events-none select-none"
          style={{ width: 220, top: 80, left: 80, opacity: 0.85 }}
        />
        <img
          src="/platform-hero-img-right.svg"
          aria-hidden="true"
          className="hidden lg:block absolute pointer-events-none select-none"
          style={{ width: 240, top: 80, right: 80, opacity: 0.85 }}
        />

        {/* Top nav — hidden in 3P (Databricks Marketplace) mode where the
            user is auto-signed-in via the SSO bridge and has no business
            seeing email/password entry points. */}
        {!PROMETHEUX_CONFIG.DATABRICKS_3P_MODE && (
          <header className="relative z-10 flex items-center justify-end px-4 sm:px-8 py-5">
            <div className="flex items-center gap-3">
              <button
                onClick={() => {
                  setIsSignUp(false);
                  setShowAuthModal(true);
                }}
                className="text-sm font-medium bg-white text-[#212020] px-4 py-2 uppercase tracking-wider border border-[#212020] shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px] transition-all"
              >
                Log in
              </button>
              <button
                onClick={() => {
                  setIsSignUp(true);
                  setShowAuthModal(true);
                }}
                className="text-sm font-medium bg-[#1828FF] text-white px-4 py-2 uppercase tracking-wider shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px] transition-all"
              >
                Sign up
              </button>
            </div>
          </header>
        )}

        {/* Main content */}
        <main className="relative z-10 flex flex-col items-center justify-center flex-1 px-4 pb-8 sm:pb-16">
          <style>{`
            @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
            @font-face {
              font-family: 'Roobert';
              src: url('/RoobertTRIALVF.woff2') format('woff2'),
                   url('/RoobertTRIALVF.woff') format('woff');
              font-weight: 100 900;
            }
            .greeting-title { font-family: 'Roobert', sans-serif; }
          `}</style>

          {/* Cloud + sun icon */}
          <div className="relative mb-6" style={{ width: 110, height: 95 }}>
            <img
              src="/sun-icon.svg"
              alt=""
              aria-hidden="true"
              style={{
                width: 48,
                height: 48,
                position: "absolute",
                top: 0,
                right: 0,
                zIndex: 0,
                animation: "spin 12s linear infinite",
              }}
            />
            <img
              src="/3dcloud-icon.svg"
              alt=""
              aria-hidden="true"
              style={{ width: 90, height: 90, position: "absolute", bottom: 0, left: 0, zIndex: 1 }}
            />
          </div>

          <h1 className="greeting-title text-4xl md:text-5xl font-bold text-[#212020] text-center mb-3">
            Build your first ontology
          </h1>
          <p className="text-base text-gray-500 text-center mb-10 max-w-md">
            Describe what you want to understand and Prometheux will build it for you.
          </p>

          {/* Chat box */}
          <div className="w-full max-w-2xl bg-white border border-[#212020] shadow-[4px_4px_0_0_#212020]">
            <div className="flex flex-col p-4">
              <textarea
                placeholder={displayedPlaceholder}
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    handleSend();
                  }
                }}
                className="w-full pl-1 pr-1 pt-1 pb-1 text-base border-0 focus:ring-0 resize-none overflow-y-auto outline-none bg-transparent"
                style={{ minHeight: "4.5rem", maxHeight: "12rem" }}
                onInput={(e) => {
                  const t = e.target as HTMLTextAreaElement;
                  t.style.height = "auto";
                  t.style.height = `${Math.min(t.scrollHeight, 192)}px`;
                }}
              />
              <div className="flex items-center justify-end gap-1 pt-2">
                <div className="flex items-center gap-1">
                  <TooltipProvider>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <button
                          onClick={() => {
                            setIsSignUp(true);
                            setShowAuthModal(true);
                          }}
                          className="h-8 w-8 flex items-center justify-center text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded transition-colors"
                        >
                          <Database className="h-4 w-4" />
                        </button>
                      </TooltipTrigger>
                      <TooltipContent>Connect Database</TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                  <input
                    type="file"
                    multiple
                    accept=".pdf,.csv,.txt,.doc,.docx,.png,.jpg,.jpeg,.gif,.bmp,.webp,.svg"
                    onChange={(e) => {
                      if (e.target.files) {
                        setAttachedFiles((prev) => [...prev, ...Array.from(e.target.files!)]);
                      }
                    }}
                    className="hidden"
                    id="login-file-input"
                  />
                  <button
                    onClick={() => document.getElementById("login-file-input")?.click()}
                    className="h-8 w-8 flex items-center justify-center text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded transition-colors"
                  >
                    <Paperclip className="h-4 w-4" />
                  </button>
                </div>
                <button
                  onClick={handleSend}
                  className="h-8 w-8 flex items-center justify-center bg-[#1828FF] text-white rounded-lg hover:bg-[#1828FF]/90 transition-colors"
                >
                  <ArrowUp className="h-4 w-4" />
                </button>
              </div>
              <AttachedFilesPreview
                attachedFiles={attachedFiles}
                onFileRemove={(i) => setAttachedFiles((prev) => prev.filter((_, idx) => idx !== i))}
              />
            </div>
          </div>

          {!PROMETHEUX_CONFIG.DATABRICKS_3P_MODE && (
            <p className="text-xs text-gray-400 mt-4 text-center">
              Already have an account?{" "}
              <button
                onClick={() => {
                  setIsSignUp(false);
                  setShowAuthModal(true);
                }}
                className="text-[#1828FF] hover:underline"
              >
                Log in
              </button>
            </p>
          )}
        </main>
      </div>

      {/* Auth modal — never shown in 3P mode (auth handled by SSO bridge) */}
      {showAuthModal && !PROMETHEUX_CONFIG.DATABRICKS_3P_MODE && (
        <div
          className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4"
          onClick={() => setShowAuthModal(false)}
        >
          <div
            className="bg-[#fafaf8] w-full max-w-[480px] relative p-6 sm:p-10 sm:pb-8"
            style={{ borderRadius: "20px" }}
            onClick={(e) => e.stopPropagation()}
          >
            {/* Close */}
            <button
              onClick={() => setShowAuthModal(false)}
              className="absolute top-5 right-5 text-gray-400 hover:text-gray-700 transition-colors"
              aria-label="Close"
            >
              <svg
                width="20"
                height="20"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
              >
                <path d="M18 6 6 18M6 6l12 12" />
              </svg>
            </button>

            {/* Icon */}
            <img src="/prometheux-icon.png" alt="Prometheux" className="w-12 h-12 mb-6" />

            {/* Heading */}
            <h2 className="greeting-title text-[1.6rem] sm:text-[2rem] font-bold text-[#212020] leading-tight mb-1">
              {isSignUp ? "Start Building." : "Welcome back."}
            </h2>
            <p className="text-[1.3rem] sm:text-[1.75rem] font-semibold text-gray-400 leading-tight mb-5 sm:mb-7">
              {isSignUp ? "Create free account" : "Log in to continue"}
            </p>

            {/* Social buttons */}
            <div className="space-y-3 mb-5">
              <AuthModalSocialButton onClick={handleGoogleLogin} label="Continue with Google">
                <svg
                  viewBox="0 0 48 48"
                  className="h-5 w-5"
                  xmlns="http://www.w3.org/2000/svg"
                  aria-hidden="true"
                >
                  <path
                    fill="#FFC107"
                    d="M43.611 20.083H42V20H24v8h11.303c-1.649 4.657-6.08 8-11.303 8-6.627 0-12-5.373-12-12s5.373-12 12-12c3.059 0 5.842 1.154 7.961 3.039l5.657-5.657C34.046 6.053 29.268 4 24 4 12.955 4 4 12.955 4 24s8.955 20 20 20 20-8.955 20-20c0-1.341-.138-2.65-.389-3.917z"
                  />
                  <path
                    fill="#FF3D00"
                    d="M6.306 14.691l6.571 4.819C14.655 15.108 18.961 12 24 12c3.059 0 5.842 1.154 7.961 3.039l5.657-5.657C34.046 6.053 29.268 4 24 4 16.318 4 9.656 8.337 6.306 14.691z"
                  />
                  <path
                    fill="#4CAF50"
                    d="M24 44c5.166 0 9.86-1.977 13.409-5.192l-6.19-5.238C29.211 35.091 26.715 36 24 36c-5.202 0-9.619-3.317-11.283-7.946l-6.522 5.025C9.505 39.556 16.227 44 24 44z"
                  />
                  <path
                    fill="#1976D2"
                    d="M43.611 20.083H42V20H24v8h11.303c-.792 2.237-2.231 4.166-4.087 5.571l6.19 5.238C36.971 39.205 44 34 44 24c0-1.341-.138-2.65-.389-3.917z"
                  />
                </svg>
              </AuthModalSocialButton>
              <AuthModalSocialButton onClick={handleMicrosoftLogin} label="Continue with Microsoft">
                <svg viewBox="0 0 24 24" className="h-5 w-5" xmlns="http://www.w3.org/2000/svg">
                  <path fill="#f25022" d="M0 0h11.5v11.5H0z" />
                  <path fill="#00a4ef" d="M0 12.5h11.5V24H0z" />
                  <path fill="#7fba00" d="M12.5 0H24v11.5H12.5z" />
                  <path fill="#ffb900" d="M12.5 12.5H24V24H12.5z" />
                </svg>
              </AuthModalSocialButton>
            </div>

            {/* OR divider */}
            <div className="flex items-center gap-3 mb-5">
              <div className="flex-1 h-px bg-gray-200" />
              <span className="text-xs font-medium text-gray-400 tracking-widest">OR</span>
              <div className="flex-1 h-px bg-gray-200" />
            </div>

            {/* Email form (collapsed into just the continue button + inline expand) */}
            <AuthEmailSection isSignUp={isSignUp} onToggleMode={() => setIsSignUp(!isSignUp)} />

            {/* Footer */}
            <p className="text-xs text-gray-400 mt-6 leading-relaxed">
              By continuing, you agree to the{" "}
              <a
                href="https://prometheux.ai/terms-and-conditions"
                target="_blank"
                rel="noopener noreferrer"
                className="underline hover:text-gray-600"
              >
                Terms of Service
              </a>{" "}
              and{" "}
              <a
                href="https://prometheux.ai/privacy-policy"
                target="_blank"
                rel="noopener noreferrer"
                className="underline hover:text-gray-600"
              >
                Privacy Policy
              </a>
              .
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Login;
