import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { HttpService } from "@/shared/services/httpService";
import { LoginActivityResponseSchema, type LoginSession } from "./loginActivity.types";

const USERS_BASE = "/users";

async function authedFetch(path: string, init: RequestInit): Promise<Response> {
  const url = `${PROMETHEUX_CONFIG.BASE_URL}${USERS_BASE}${path}`;
  const headers = HttpService.getHeaders(
    undefined,
    init.headers as Record<string, string> | undefined,
  );
  return fetch(url, { ...init, headers, mode: "cors" });
}

async function parseJsonOrThrow(response: Response): Promise<unknown> {
  const text = await response.text();

  if (response.status === 401) {
    throw new Error("Authentication token is invalid or expired");
  }

  if (!response.ok) {
    throw new Error(text || response.statusText);
  }

  try {
    return JSON.parse(text);
  } catch {
    throw new Error("Invalid JSON response from /users endpoint");
  }
}

async function fetchLoginActivity(): Promise<LoginSession[]> {
  const response = await authedFetch("/login-activity", { method: "GET" });
  const raw = await parseJsonOrThrow(response);
  return LoginActivityResponseSchema.parse(raw).data;
}

export const loginActivityApi = {
  fetchLoginActivity,
};
