/**
 * Serialize form record-group rows into Vadalog ground atoms (preamble facts).
 *
 * Rows travel per-run via the run endpoint's `preamble_facts` field; the
 * engine prepends them to the program and skips their predicate during
 * dependency resolution. Nothing is persisted (ADR D8).
 */

export type FactRecord = Record<string, unknown>;

function serializeValue(value: unknown): string {
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  if (typeof value === "boolean") return value ? "#T" : "#F";
  const text = String(value ?? "");
  const escaped = text.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  return `"${escaped}"`;
}

function coerce(value: unknown): unknown {
  if (typeof value !== "string") return value;
  const trimmed = value.trim();
  if (trimmed !== "" && !Number.isNaN(Number(trimmed))) return Number(trimmed);
  return value;
}

/**
 * Build `predicate("a", 1.5).` lines from records, emitting arguments in
 * `fieldOrder` (the record_group's declared field order — which must match
 * the input predicate's @model column order).
 */
export function serializeFacts(
  predicate: string,
  records: FactRecord[],
  fieldOrder: string[],
): string {
  return records
    .map((record) => {
      const args = fieldOrder.map((field) => serializeValue(coerce(record[field])));
      return `${predicate}(${args.join(", ")}).`;
    })
    .join("\n");
}
