import { create } from "zustand";

/**
 * Bridge store between deep editor components (OntologySchemaEditor, LineageView)
 * and the page-level header actions rendered in Index.tsx.
 *
 * Components populate this store via useEffect; the header reads from it.
 */

interface EditorActionsState {
  // ── Ontology ───────────────────────────────────────────────────────────────
  viewMode: "visual" | "json";
  isSaving: boolean;
  isImporting: boolean;

  /** Handlers registered by OntologySchemaEditor */
  onViewModeChange: ((mode: string) => void) | null;
  onAddNode: (() => void) | null;
  onOpenEdgeDialog: (() => void) | null;
  onSave: (() => void) | null;
  onTriggerOwlImport: (() => void) | null;
  onOpenOwlVadalogConfig: (() => void) | null;

  /** Graph data + search handlers for OntologySchemaSearchBar */
  searchNodes: Array<{ id: string; label: string; description?: string }>;
  searchEdges: Array<{ id: string; from: string; to: string; label: string; description?: string }>;
  onNodeSearchSelect: ((nodeId: string) => void) | null;
  onEdgeSearchSelect: ((edgeId: string) => void) | null;
  onZoomToElement: ((id: string, type: "node" | "edge") => void) | null;

  // ── Lineage ────────────────────────────────────────────────────────────────
  onNewConcept: (() => void) | null;
  /** Run button — only shown when a non-new concept cell is selected */
  canRunConcept: boolean;
  isRunningConcept: boolean;
  onRunConcept: (() => void) | null;

  /** True when the lineage detail panel is in full-screen (expanded) mode */
  isLineagePanelExpanded: boolean;

  /** Lineage search — stored here so the header input drives the canvas */
  lineageSearchValue: string;
  setLineageSearchValue: ((v: string) => void) | null;
  lineageSearchNodes: Array<{ id: string; label: string; nodeType?: string }>;
  onLineageSearchSelect: ((label: string) => void) | null;

  /**
   * Concept name another view (e.g. the Document view's predicate chips)
   * has requested be focused on the lineage canvas. LineageView consumes
   * and clears this once its nodes are ready.
   */
  pendingLineageFocus: string | null;

  /**
   * Context note the Explorer's Context rail asked to open inside a
   * concept's context tab. ConceptContextPanel consumes and clears it
   * once the concept's attached notes are loaded.
   */
  pendingContextNoteId: string | null;

  /**
   * Request from a concept's context panel to create a new static context
   * cell pre-filled with these note ids (the "make this knowledge
   * computable" bridge). LineageView consumes and clears it.
   */
  pendingContextCellSeed: { noteIds: string[]; sourceConcept: string } | null;

  // ── Store actions ──────────────────────────────────────────────────────────
  register: (updates: Partial<Omit<EditorActionsState, "register" | "clear">>) => void;
  clear: () => void;
}

const EMPTY: Omit<EditorActionsState, "register" | "clear"> = {
  viewMode: "visual",
  isSaving: false,
  isImporting: false,
  onViewModeChange: null,
  onAddNode: null,
  onOpenEdgeDialog: null,
  onSave: null,
  onTriggerOwlImport: null,
  onOpenOwlVadalogConfig: null,
  searchNodes: [],
  searchEdges: [],
  onNodeSearchSelect: null,
  onEdgeSearchSelect: null,
  onZoomToElement: null,
  onNewConcept: null,
  canRunConcept: false,
  isRunningConcept: false,
  onRunConcept: null,
  isLineagePanelExpanded: false,
  lineageSearchValue: "",
  setLineageSearchValue: null,
  lineageSearchNodes: [],
  onLineageSearchSelect: null,
  pendingLineageFocus: null,
  pendingContextNoteId: null,
  pendingContextCellSeed: null,
};

export const useEditorActionsStore = create<EditorActionsState>((set) => ({
  ...EMPTY,
  register: (updates) => set((s) => ({ ...s, ...updates })),
  clear: () => set((s) => ({ ...s, ...EMPTY })),
}));
