import { Folder, Globe, LayoutGrid, Waypoints } from "lucide-react";
import { useState } from "react";

import { cn } from "@/shared/lib/utils";

import type { ContextNote } from "../../types";
import type { DocumentGroup, VaultRef } from "../notesModel";
import { NoteCardGrid } from "./NoteCardGrid";
import { NotesGraphView } from "./NotesGraphView";

type CollectionTab = "cards" | "graph";

interface CollectionViewProps {
  vault: VaultRef;
  /** "" = the whole vault. */
  folderPath: string;
  notes: ContextNote[];
  documents: DocumentGroup[];
  /** Title lookup for graph neighbors outside the collection. */
  lookupNotes: ContextNote[];
  onOpenNote: (note: ContextNote) => void;
  onOpenNoteId: (noteId: string) => void;
  onOpenDocument: (document: DocumentGroup) => void;
}

interface TabButtonProps {
  isActive: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}

function TabButton({ isActive, icon, label, onClick }: TabButtonProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "inline-flex items-center gap-1.5 rounded-md px-2.5 py-1 text-sm transition-colors",
        isActive
          ? "bg-accent font-medium text-accent-foreground"
          : "text-muted-foreground hover:text-foreground",
      )}
    >
      {icon}
      {label}
    </button>
  );
}

/** Center view for a selected vault/folder: Cards | Graph tabs. */
export function CollectionView({
  vault,
  folderPath,
  notes,
  documents,
  lookupNotes,
  onOpenNote,
  onOpenNoteId,
  onOpenDocument,
}: CollectionViewProps) {
  const [tab, setTab] = useState<CollectionTab>("cards");

  const HeaderIcon = folderPath ? Folder : Globe;
  const heading = folderPath || vault.name;
  const count = notes.length + documents.length;

  return (
    <div className="flex h-full flex-col">
      <header className="flex shrink-0 items-center gap-2 border-b border-border px-6 py-2.5">
        <HeaderIcon className="h-4 w-4 text-muted-foreground" />
        <h2 className="text-base font-semibold text-foreground">{heading}</h2>
        <span className="text-xs text-muted-foreground">
          {count} item{count === 1 ? "" : "s"}
        </span>
        <div className="ml-auto flex items-center gap-1 rounded-lg border border-border p-0.5">
          <TabButton
            isActive={tab === "cards"}
            icon={<LayoutGrid className="h-4 w-4" />}
            label="Cards"
            onClick={() => setTab("cards")}
          />
          <TabButton
            isActive={tab === "graph"}
            icon={<Waypoints className="h-4 w-4" />}
            label="Graph"
            onClick={() => setTab("graph")}
          />
        </div>
      </header>

      <div className="min-h-0 flex-1">
        {tab === "cards" ? (
          <NoteCardGrid
            vault={vault}
            folderPath={folderPath}
            notes={notes}
            documents={documents}
            onOpenNote={onOpenNote}
            onOpenDocument={onOpenDocument}
          />
        ) : (
          <NotesGraphView
            collectionNotes={notes}
            documents={documents}
            lookupNotes={lookupNotes}
            onOpenNoteId={onOpenNoteId}
          />
        )}
      </div>
    </div>
  );
}
