import { Loader2 } from "lucide-react";

import type { ContextNote, ContextNoteFilter } from "../../types";
import { useNotesSearch } from "../hooks/useNotesSearch";
import { noteDisplayTitle } from "../notesModel";
import { NoteBadges } from "./ShelfBadge";

interface SearchResultsProps {
  query: string;
  filter: ContextNoteFilter;
  onSelect: (note: ContextNote) => void;
}

interface ResultGroupProps {
  heading: string;
  notes: ContextNote[];
  onSelect: (note: ContextNote) => void;
}

function ResultGroup({ heading, notes, onSelect }: ResultGroupProps) {
  if (notes.length === 0) return null;
  return (
    <section className="pb-2">
      <p className="px-2 pb-1 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        {heading}
      </p>
      <ul className="space-y-px">
        {notes.map((note) => (
          <li key={note.id}>
            <button
              type="button"
              onClick={() => onSelect(note)}
              className="w-full space-y-0.5 rounded-md px-2 py-1.5 text-left transition-colors hover:bg-accent/50"
            >
              <span className="flex items-center gap-1.5">
                <span className="min-w-0 flex-1 truncate text-sm font-medium text-foreground">
                  {noteDisplayTitle(note)}
                </span>
                <NoteBadges note={note} />
              </span>
              <span className="block truncate text-xs text-muted-foreground">{note.text}</span>
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

export function SearchResults({ query, filter, onSelect }: SearchResultsProps) {
  const { exactMatches, relatedMatches, isLoading } = useNotesSearch(query, filter);

  if (isLoading) {
    return (
      <div className="flex items-center gap-2 p-3 text-xs text-muted-foreground">
        <Loader2 className="h-3.5 w-3.5 animate-spin" />
        Searching…
      </div>
    );
  }

  if (exactMatches.length === 0 && relatedMatches.length === 0) {
    return <p className="p-3 text-xs italic text-muted-foreground">No matching notes.</p>;
  }

  return (
    <div>
      <ResultGroup heading="Exact matches" notes={exactMatches} onSelect={onSelect} />
      <ResultGroup heading="Related" notes={relatedMatches} onSelect={onSelect} />
    </div>
  );
}
