import { useCallback, useState } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { sendSlackNotification } from "@/features/onboarding/utils";
import { supabase } from "@/shared/integrations/supabase/client";

export interface OnboardingData {
  firstName: string;
  lastName: string;
  username: string;
  organizationType: "solo" | "organization";
  organizationName?: string;
}

export interface UseOnboardingSubmitResult {
  submitOnboarding: (data: OnboardingData) => Promise<boolean>;
  isSubmitting: boolean;
  error: string | null;
}

export const useOnboardingSubmit = (): UseOnboardingSubmitResult => {
  const { user } = useAuth();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const submitOnboarding = useCallback(
    async (data: OnboardingData): Promise<boolean> => {
      if (!user?.id) {
        setError("User not authenticated");
        return false;
      }

      setIsSubmitting(true);
      setError(null);

      try {
        // Determine organization value
        const organization =
          data.organizationType === "solo" ? "solo" : data.organizationName?.trim() || "";

        // 1. Save profile data to Supabase profiles table
        const { error: profileError } = await supabase
          .from("profiles")
          .update({
            first_name: data.firstName,
            last_name: data.lastName,
            username: data.username,
            organization: organization,
          })
          .eq("id", user.id);

        if (profileError) {
          throw new Error(`Failed to save profile: ${profileError.message}`);
        }

        // Also update auth user metadata
        const { error: metadataError } = await supabase.auth.updateUser({
          data: {
            first_name: data.firstName,
            last_name: data.lastName,
            username: data.username,
          },
        });

        if (metadataError) {
          // Don't throw - profile update succeeded
        }

        // 2. Get the Platform application ID
        const { data: platformApp, error: appError } = await supabase
          .from("applications")
          .select("id")
          .eq("name", "Platform")
          .single();

        if (appError || !platformApp) {
          throw new Error("Platform application not found");
        }

        // 3. Check if request already exists
        const { data: existingRequest, error: checkError } = await supabase
          .from("user_applications")
          .select("id, status")
          .eq("user_id", user.id)
          .eq("application_id", platformApp.id)
          .single();

        if (checkError && checkError.code !== "PGRST116") {
          throw checkError;
        }

        // If already requested or enabled, don't create duplicate
        if (existingRequest) {
          if (existingRequest.status?.toLowerCase() === "requested") {
            toast.success("Access request already submitted");
            return true;
          } else if (existingRequest.status?.toLowerCase() === "enabled") {
            return true;
          }
        }

        // 4. Create access request in user_applications
        const { error: upsertError } = await supabase.from("user_applications").upsert(
          {
            user_id: user.id,
            application_id: platformApp.id,
            node_group: null,
            status: "Requested",
            metadata: {
              request_message: `New user onboarding: ${data.firstName} ${data.lastName} (${data.username}) from ${organization}`,
              requested_at: new Date().toISOString(),
            },
          },
          {
            onConflict: "user_id,application_id,node_group",
          },
        );

        if (upsertError) {
          throw new Error(`Failed to create access request: ${upsertError.message}`);
        }

        // 5. Send email notification via Edge Function
        try {
          const { error: emailError } = await supabase.functions.invoke(
            "send-platform-access-request",
            {
              body: {
                userName: data.username,
                userEmail: user.email,
                firstName: data.firstName,
                lastName: data.lastName,
                organization: organization,
                applicationName: "Platform",
                applicationId: platformApp.id,
                requestedAt: new Date().toISOString(),
              },
            },
          );
        } catch (emailError) {
          console.error("Error sending access request email:", emailError);
        }

        // 6. Send Slack notification
        try {
          await sendSlackNotification({
            type: "new_request",
            userName: data.username,
            userEmail: user.email,
            firstName: data.firstName,
            lastName: data.lastName,
            organization: organization,
            applicationName: "Platform",
            applicationId: platformApp.id,
            requestedAt: new Date().toISOString(),
          });
        } catch (_slackError) {
          // Slack notification is non-critical
        }

        toast.success("Access request submitted successfully");
        return true;
      } catch (err: any) {
        console.error("Error in onboarding submission:", err);
        setError(err.message || "An error occurred during onboarding");
        toast.error(err.message || "Failed to complete onboarding");
        return false;
      } finally {
        setIsSubmitting(false);
      }
    },
    [user?.id, user?.email],
  );

  return {
    submitOnboarding,
    isSubmitting,
    error,
  };
};
