import type { AppDefinition, FormFieldDef } from "../schema/appDefinition.types";
import { moveItem, nextId, patchPageInputs } from "./appEditorMutations";

/**
 * Pure mutations for form fields — schema nodes nested inside a form input's
 * positional sections (ADR D5). Same contract as appEditorMutations: every
 * function returns a new definition; unknown ids are a no-op.
 */

/** Update one form section's fields immutably; missing input/section = no-op. */
function mapFormFields(
  definition: AppDefinition,
  pageId: string,
  inputId: string,
  sectionIndex: number,
  update: (fields: FormFieldDef[]) => FormFieldDef[],
): AppDefinition {
  return patchPageInputs(definition, pageId, (input) => {
    if (input.id !== inputId || input.type !== "form") return input;
    const sections = input.sections ?? [];
    if (!sections[sectionIndex]) return input;
    return {
      ...input,
      sections: sections.map((section, index) =>
        index === sectionIndex ? { ...section, fields: update(section.fields) } : section,
      ),
    };
  });
}

export function patchFormField(
  definition: AppDefinition,
  pageId: string,
  inputId: string,
  sectionIndex: number,
  fieldId: string,
  patch: Partial<FormFieldDef>,
): AppDefinition {
  return mapFormFields(definition, pageId, inputId, sectionIndex, (fields) =>
    fields.map((field) => (field.id === fieldId ? { ...field, ...patch } : field)),
  );
}

export function addFormField(
  definition: AppDefinition,
  pageId: string,
  inputId: string,
  sectionIndex: number,
  field: Omit<FormFieldDef, "id">,
): AppDefinition {
  return patchPageInputs(definition, pageId, (input) => {
    if (input.id !== inputId || input.type !== "form") return input;
    // A form saved without sections gets its first one on demand.
    const sections = (input.sections ?? []).length > 0 ? input.sections! : [{ fields: [] }];
    const allFieldIds = sections.flatMap((section) => section.fields.map((f) => f.id));
    const id = nextId("field", allFieldIds);
    return {
      ...input,
      sections: sections.map((section, index) =>
        index === sectionIndex
          ? { ...section, fields: [...section.fields, { ...field, id }] }
          : section,
      ),
    };
  });
}

export function removeFormField(
  definition: AppDefinition,
  pageId: string,
  inputId: string,
  sectionIndex: number,
  fieldId: string,
): AppDefinition {
  return mapFormFields(definition, pageId, inputId, sectionIndex, (fields) =>
    fields.filter((field) => field.id !== fieldId),
  );
}

export function moveFormField(
  definition: AppDefinition,
  pageId: string,
  inputId: string,
  sectionIndex: number,
  fieldId: string,
  direction: -1 | 1,
): AppDefinition {
  return mapFormFields(definition, pageId, inputId, sectionIndex, (fields) =>
    moveItem(
      fields,
      fields.findIndex((field) => field.id === fieldId),
      direction,
    ),
  );
}
