import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { listNotifications, markAllNotificationsRead, markNotificationRead } from "../api";
import type {
  NotificationError,
  NotificationItem,
  NotificationsPayload,
  NotificationType,
} from "../types";

// Polling cadence for the bell. Matches the "slow poll" convention used
// elsewhere (e.g. useProjectsExecutionStatus idle interval).
const NOTIFICATIONS_POLL_MS = 45_000;

export const NOTIFICATIONS_KEY = ["notifications"] as const;
const notificationsKey = (userId: string) => [...NOTIFICATIONS_KEY, userId] as const;

interface UseNotificationsReturn {
  items: NotificationItem[];
  unreadCount: number;
  isLoading: boolean;
  markAllRead: () => Promise<unknown>;
  markRead: (input: { type: NotificationType; entityId: string }) => Promise<unknown>;
}

// GET /notifications on a poll + read mutations. Read state is server-owned, so
// both mutations invalidate the feed to re-derive read flags / unread count.
export function useNotifications(): UseNotificationsReturn {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";
  const canSeeNotifications = usePermissionsStore((state) => state.canSee("can_see_notifications"));

  // Local dev has no Supabase session token, but the backend bypasses JWT there,
  // so enable the poll anyway. Stays off in Snowflake/Databricks modes (no
  // Supabase backend for this feature), matching the teams/shares hooks.
  const isLocalDev =
    PROMETHEUX_CONFIG.SKIP_AUTH &&
    !PROMETHEUX_CONFIG.SNOWFLAKE_MODE &&
    !PROMETHEUX_CONFIG.DATABRICKS_MODE;

  const query = useQuery<NotificationsPayload, NotificationError>({
    queryKey: notificationsKey(userId),
    queryFn: () => listNotifications(supabaseToken),
    enabled: canSeeNotifications && (isLocalDev || Boolean(userId && supabaseToken)),
    staleTime: 0,
    refetchInterval: NOTIFICATIONS_POLL_MS,
    retry: 1,
  });

  const markAllMutation = useMutation<unknown, NotificationError, void>({
    mutationFn: () => markAllNotificationsRead(supabaseToken),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: NOTIFICATIONS_KEY }),
  });

  const markReadMutation = useMutation<
    unknown,
    NotificationError,
    { type: NotificationType; entityId: string }
  >({
    mutationFn: ({ type, entityId }) => markNotificationRead(type, entityId, supabaseToken),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: NOTIFICATIONS_KEY }),
  });

  return {
    items: query.data?.items ?? [],
    unreadCount: query.data?.unread_count ?? 0,
    isLoading: query.isLoading,
    markAllRead: markAllMutation.mutateAsync,
    markRead: markReadMutation.mutateAsync,
  };
}
