import { create } from "zustand";

interface StartMachineStore {
  open: boolean;
  openModal: () => void;
  closeModal: () => void;
}

export const useStartMachineStore = create<StartMachineStore>((set) => ({
  open: false,
  openModal: () => set({ open: true }),
  closeModal: () => set({ open: false }),
}));
