import { extractDatabaseInfo } from "@/features/data-sources/utils";

const BINARY_FILE_DATASOURCE_TYPE = "binaryfile";

/**
 * Binary files (PDF, DOCX, images) hold no rows until a bind annotation declares
 * how to read them, and the engine only turns one into a dataset by sending its
 * bytes to Azure Document Intelligence — a metered call, plus an LLM call in the
 * default `layout` mode. Neither belongs behind a preview click, so these sources
 * do not offer one.
 */
export const isPreviewableDataSource = (bindAnnotation: string): boolean =>
  extractDatabaseInfo(bindAnnotation).type.toLowerCase() !== BINARY_FILE_DATASOURCE_TYPE;

/**
 * Replaces credential values in a bind annotation with asterisks, so copying one
 * to the clipboard never carries a secret out of the app.
 */
export const maskBindSecrets = (bindAnnotation: string): string =>
  bindAnnotation
    .replace(/password='[^']*'/gi, "password='****'")
    .replace(/password=[^,)'"]+/gi, "password=****")
    .replace(/s3aSecretKey='[^']*'/gi, "s3aSecretKey='****'")
    .replace(/s3aSecretKey=[^,)'"]+/gi, "s3aSecretKey=****");
