import { clearAuthToken, getAuthToken, setAuthToken } from "@/shared/auth/authToken";

// ---------------------------------------------------------------------------
// Request deduplication — collapses concurrent identical requests into one
// ---------------------------------------------------------------------------

const inflightGets = new Map<string, Promise<any>>();
const inflightPosts = new Map<string, Promise<any>>();

// POST endpoints that are read-only queries (safe to deduplicate)
const DEDUP_POST_PATTERNS = ["/visualize-concept-lineage"];

// ---------------------------------------------------------------------------
// Typed HTTP error + global error hook
//
// Carries `status` so cross-cutting handlers (e.g. shared-project self-healing
// on 401/403) can react without parsing message strings. `body` is the parsed
// JSON body when available (for cases like FastAPI's `{"detail": "..."}`).
// ---------------------------------------------------------------------------

export class HttpError extends Error {
  readonly status: number;
  readonly body: unknown;

  constructor(message: string, status: number, body?: unknown) {
    super(message);
    this.name = "HttpError";
    this.status = status;
    this.body = body;
  }
}

export interface HttpErrorInfo {
  url: string;
  status: number;
  body: unknown;
}

type HttpErrorHook = (info: HttpErrorInfo) => void;

let errorHook: HttpErrorHook | null = null;

function notifyError(info: HttpErrorInfo): void {
  if (!errorHook) return;
  try {
    errorHook(info);
  } catch (err) {
    // Hooks must never break the request path.
    console.warn("HttpService error hook threw", err);
  }
}

async function readErrorBody(response: Response): Promise<{ text: string; parsed: unknown }> {
  const text = await response.text();
  try {
    return { text, parsed: JSON.parse(text) };
  } catch {
    return { text, parsed: undefined };
  }
}

// Best human-readable message for a failed response: prefer the backend's own
// `message`, then FastAPI's `detail`, then the bare status line. Mirrors
// BaseClient.extractMessage so structured backend errors keep their text after
// they are rethrown as HttpError.
function errorMessageFrom(parsed: unknown, status: number, statusText: string): string {
  if (typeof parsed === "object" && parsed !== null) {
    const v = parsed as Record<string, unknown>;
    if (typeof v.message === "string" && v.message.length > 0) return v.message;
    if (typeof v.detail === "string" && v.detail.length > 0) return v.detail;
  }
  return `HTTP ${status}: ${statusText}`;
}

// Single non-ok exit for every verb. Always throws a typed HttpError carrying
// the HTTP status + parsed body, so callers can branch on `error_code` / `code`
// / envelope `status` without the response ever being mistaken for success.
//
// Previously a 4xx/5xx body that merely had a `message` field was RETURNED as
// if it were data. That silently hid engine-busy (409), freemium limits (402)
// and parse errors from the UI, and defeated `instanceof HttpError` checks
// (e.g. self-heal's isRoleInsufficientError, the freemium upgrade walls). The
// parsed body is always attached, so `error_code`-driven handlers still work.
async function raiseForStatus(url: string, response: Response): Promise<never> {
  const { parsed } = await readErrorBody(response);
  notifyError({ url, status: response.status, body: parsed });
  throw new HttpError(
    errorMessageFrom(parsed, response.status, response.statusText),
    response.status,
    parsed,
  );
}

export class HttpService {
  // Register a single global hook invoked on every non-ok HTTP response (before
  // throw / envelope return). Returns an unregister fn so React effects can
  // detach on unmount.
  static setErrorHook(hook: HttpErrorHook | null): () => void {
    errorHook = hook;
    return () => {
      if (errorHook === hook) errorHook = null;
    };
  }

  static getHeaders(authToken?: string, additionalHeaders?: Record<string, string>): HeadersInit {
    const token = authToken || getAuthToken();

    return {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
      ...additionalHeaders,
    };
  }

  static setAuthToken(token: string) {
    setAuthToken(token);
  }

  static clearAuthToken() {
    clearAuthToken();
  }

  private static sanitizeForLog(obj: any): any {
    if (!obj) return obj;
    if (typeof obj !== "object") return obj;

    if (Array.isArray(obj)) {
      return obj.map((item) => HttpService.sanitizeForLog(item));
    }

    const sanitized = { ...obj };
    const sensitiveKeys = [
      "Authorization",
      "authorization",
      "api_key",
      "apiKey",
      "api_token",
      "apiToken",
      "llm_api_key",
      "llmApiKey",
      "embedding_api_key",
      "embeddingApiKey",
      "AUTH_TOKEN",
      "authToken",
      "password",
      "secret",
    ];

    for (const key in sanitized) {
      if (typeof sanitized[key] === "object" && sanitized[key] !== null) {
        sanitized[key] = HttpService.sanitizeForLog(sanitized[key]);
      } else if (
        sensitiveKeys.some((sensitiveKey) => key.toLowerCase().includes(sensitiveKey.toLowerCase()))
      ) {
        sanitized[key] = "[REDACTED]";
      }
    }

    return sanitized;
  }

  static async get(
    url: string,
    authToken?: string,
    additionalHeaders?: Record<string, string>,
  ): Promise<any> {
    // Deduplicate concurrent GET requests to the same URL
    const dedupeKey = url;
    const existing = inflightGets.get(dedupeKey);
    if (existing) return existing;

    const request = HttpService.executeGet(url, authToken, additionalHeaders);
    inflightGets.set(dedupeKey, request);

    try {
      return await request;
    } finally {
      inflightGets.delete(dedupeKey);
    }
  }

  private static async executeGet(
    url: string,
    authToken?: string,
    additionalHeaders?: Record<string, string>,
  ): Promise<any> {
    const headers = HttpService.getHeaders(authToken, additionalHeaders);

    const response = await fetch(url, {
      method: "GET",
      headers,
      mode: "cors",
    });

    if (!response.ok) {
      await raiseForStatus(url, response);
    }

    const contentType = response.headers.get("content-type");
    if (contentType?.includes("text/html")) {
      throw new Error(
        "Received HTML response instead of JSON. API endpoint may not exist or server configuration issue.",
      );
    }

    try {
      return await response.json();
    } catch (_error) {
      const text = await response.text();
      console.error("Failed to parse JSON response", {
        url,
        responseText: text.substring(0, 200),
      });
      throw new Error("Invalid JSON response from server");
    }
  }

  static async post(
    url: string,
    body: unknown,
    authToken?: string,
    additionalHeaders?: Record<string, string>,
  ): Promise<any> {
    const canDedup = DEDUP_POST_PATTERNS.some((p) => url.includes(p));
    if (canDedup) {
      const bodyStr = JSON.stringify(body);
      const dedupeKey = `${url}::${bodyStr}`;
      const existing = inflightPosts.get(dedupeKey);
      if (existing) return existing;

      const request = HttpService.executePost(url, body, authToken, additionalHeaders);
      inflightPosts.set(dedupeKey, request);
      try {
        return await request;
      } finally {
        inflightPosts.delete(dedupeKey);
      }
    }

    return HttpService.executePost(url, body, authToken, additionalHeaders);
  }

  private static async executePost(
    url: string,
    body: unknown,
    authToken?: string,
    additionalHeaders?: Record<string, string>,
  ): Promise<any> {
    const headers = HttpService.getHeaders(authToken, additionalHeaders);
    const response = await fetch(url, {
      method: "POST",
      headers,
      body: JSON.stringify(body),
      mode: "cors",
    });

    if (!response.ok) {
      await raiseForStatus(url, response);
    }

    return await response.json();
  }

  static async delete(
    url: string,
    body?: unknown,
    authToken?: string,
    additionalHeaders?: Record<string, string>,
  ): Promise<any> {
    const headers = HttpService.getHeaders(authToken, additionalHeaders);

    const requestOptions: RequestInit = {
      method: "DELETE",
      headers,
      mode: "cors",
    };

    if (body) {
      requestOptions.body = JSON.stringify(body);
    }

    const response = await fetch(url, requestOptions);

    if (!response.ok) {
      await raiseForStatus(url, response);
    }

    return response.json();
  }

  static async patch(
    url: string,
    body: unknown,
    authToken?: string,
    additionalHeaders?: Record<string, string>,
  ): Promise<any> {
    const headers = HttpService.getHeaders(authToken, additionalHeaders);
    const response = await fetch(url, {
      method: "PATCH",
      headers,
      body: JSON.stringify(body),
      mode: "cors",
    });

    if (!response.ok) {
      await raiseForStatus(url, response);
    }

    const jsonResponse = await response.json();

    return jsonResponse;
  }

  static async postStream(
    url: string,
    body: unknown,
    authToken: string,
    onChunk: (chunk: string) => void,
    additionalHeaders?: Record<string, string>,
  ): Promise<string> {
    const headers = HttpService.getHeaders(authToken, additionalHeaders);

    const response = await fetch(url, {
      method: "POST",
      headers,
      body: JSON.stringify(body),
      mode: "cors",
    });

    if (!response.ok) {
      await raiseForStatus(url, response);
    }

    if (!response.body) {
      throw new Error("ReadableStream not supported");
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let fullResponse = "";

    try {
      while (true) {
        const { done, value } = await reader.read();

        if (done) {
          break;
        }

        const text = decoder.decode(value, { stream: true });
        const lines = text.split("\n");

        for (const line of lines) {
          if (line.startsWith("data: ")) {
            const data = line.slice(6);
            if (data === "[DONE]") {
              return fullResponse;
            }
            fullResponse += data;
            onChunk(data);
          }
        }
      }
    } finally {
      reader.releaseLock();
    }

    return fullResponse;
  }
}
