import { Moon, Sun } from "lucide-react";
import { cn } from "@/shared/lib/utils";
import { type Theme, useThemeStore } from "@/shared/store/themeStore";

const next: Record<Theme, Theme> = { light: "dark", dark: "light" };
const icons: Record<Theme, React.ElementType> = { light: Sun, dark: Moon };
const labels: Record<Theme, string> = { light: "Light", dark: "Dark" };

interface ThemeToggleProps {
  collapsed?: boolean;
}

export function ThemeToggle({ collapsed = false }: ThemeToggleProps) {
  const { theme, setTheme } = useThemeStore();
  const Icon = icons[theme];

  return (
    <button
      onClick={() => setTheme(next[theme])}
      title={collapsed ? labels[theme] : undefined}
      aria-label={`Switch to ${next[theme]} mode`}
      className={cn(
        "flex h-9 w-full items-center gap-3 rounded-md px-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground",
        collapsed && "justify-center px-0",
      )}
    >
      <Icon className="h-4 w-4 shrink-0" />
      {!collapsed && <span className="truncate">{labels[theme]}</span>}
    </button>
  );
}
