import { CalendarClock, ChevronDown, ChevronRight, Clock, Database, Plus } from "lucide-react";
import type React from "react";
import { useCallback, useState } from "react";
import { ContactToUpgradeDialog } from "@/features/billing/components/ContactToUpgradeDialog";
import { usePaidComputeEligibility } from "@/features/billing/hooks/usePaidComputeEligibility";
import { useConceptPolicies } from "@/features/concept-editor/hooks/useConceptPolicies";
import type {
  CronTriggerConfig,
  DataChangeTriggerConfig,
  TriggerType,
} from "@/features/concept-editor/types";
import { Button } from "@/shared/components/ui/button";
import CronPolicyForm from "./CronPolicyForm";
import DataChangePolicyForm from "./DataChangePolicyForm";
import PolicyCard from "./PolicyCard";

type FormState = { visible: false } | { visible: true; type: TriggerType | null };

interface PolicySectionProps {
  conceptName: string | undefined;
}

const PolicySection: React.FC<PolicySectionProps> = ({ conceptName }) => {
  const { policies, isLoading, createPolicy, updatePolicy, deletePolicy, triggerPolicy } =
    useConceptPolicies(conceptName);
  const { isEligible } = usePaidComputeEligibility();
  const isFreemium = isEligible === false;

  const [formState, setFormState] = useState<FormState>({ visible: false });
  const [expanded, setExpanded] = useState(true);
  const [showUpgrade, setShowUpgrade] = useState(false);

  const handleCreateCron = useCallback(
    async (cronExpression: string, timezone: string) => {
      const config: CronTriggerConfig = { cron_expression: cronExpression, timezone };
      await createPolicy("cron", config);
      setFormState({ visible: false });
    },
    [createPolicy],
  );

  const handleCreateDataChange = useCallback(
    async (checkIntervalMinutes: number) => {
      const config: DataChangeTriggerConfig = { check_interval_minutes: checkIntervalMinutes };
      await createPolicy("data_change", config);
      setFormState({ visible: false });
    },
    [createPolicy],
  );

  const handleCancel = useCallback(() => setFormState({ visible: false }), []);

  // Scheduling is a paid-only "productionising" feature. Freemium accounts get
  // the contact-to-upgrade wall instead of the create/enable/trigger actions.
  const handleAddClick = useCallback(() => {
    if (isFreemium) {
      setShowUpgrade(true);
      return;
    }
    setFormState({ visible: true, type: null });
  }, [isFreemium]);

  const handleToggle = useCallback(
    async (policyId: string, enabled: boolean) => {
      if (isFreemium && enabled) {
        setShowUpgrade(true);
        return;
      }
      await updatePolicy(policyId, { enabled });
    },
    [updatePolicy, isFreemium],
  );

  const handleTrigger = useCallback(
    async (policyId: string) => {
      if (isFreemium) {
        setShowUpgrade(true);
        return;
      }
      await triggerPolicy(policyId);
    },
    [triggerPolicy, isFreemium],
  );

  if (!conceptName) return null;

  const hasPolicies = policies.length > 0;
  const showTypePicker = formState.visible && formState.type === null;
  const showCronForm = formState.visible && formState.type === "cron";
  const showDataChangeForm = formState.visible && formState.type === "data_change";
  const showAnyForm = formState.visible;

  return (
    <div className="flex flex-col gap-2 mt-2">
      <div className="flex items-center gap-2">
        <div
          className="flex items-center gap-1.5 cursor-pointer flex-1"
          onClick={() => setExpanded((prev) => !prev)}
        >
          <div className="h-4 w-4 flex items-center justify-center">
            {expanded ? <ChevronDown className="h-3 w-3" /> : <ChevronRight className="h-3 w-3" />}
          </div>
          <CalendarClock className="h-3.5 w-3.5 text-muted-foreground" />
          <span className="text-xs text-muted-foreground">
            Policies{hasPolicies ? ` (${policies.length})` : ""}
          </span>
        </div>
        {expanded && (
          <Button variant="ghost" size="sm" className="h-7 px-2" onClick={handleAddClick}>
            <Plus className="h-3 w-3 mr-1" />
            <span className="text-xs">Add</span>
          </Button>
        )}
      </div>

      {expanded && (
        <div className="flex flex-col gap-2 ml-4">
          {isLoading && <div className="text-xs text-muted-foreground py-1">Loading...</div>}

          {!isLoading && !hasPolicies && !showAnyForm && (
            <div className="text-xs text-muted-foreground py-1">No evaluation policies yet.</div>
          )}

          {policies.map((policy) => (
            <PolicyCard
              key={policy.policy_id}
              policy={policy}
              onToggle={handleToggle}
              onDelete={deletePolicy}
              onTrigger={handleTrigger}
            />
          ))}

          {showTypePicker && (
            <div className="flex flex-col gap-2 p-3 border border-border/50 rounded-md bg-background">
              <div className="text-xs font-medium text-muted-foreground">Choose policy type</div>
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  className="flex-1 h-8 text-xs gap-1.5"
                  onClick={() => setFormState({ visible: true, type: "cron" })}
                >
                  <Clock className="h-3 w-3" />
                  Scheduled
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="flex-1 h-8 text-xs gap-1.5"
                  onClick={() => setFormState({ visible: true, type: "data_change" })}
                >
                  <Database className="h-3 w-3" />
                  Data change
                </Button>
              </div>
              <Button
                variant="ghost"
                size="sm"
                className="h-7 text-xs self-end"
                onClick={handleCancel}
              >
                Cancel
              </Button>
            </div>
          )}

          {showCronForm && <CronPolicyForm onSubmit={handleCreateCron} onCancel={handleCancel} />}

          {showDataChangeForm && (
            <DataChangePolicyForm onSubmit={handleCreateDataChange} onCancel={handleCancel} />
          )}
        </div>
      )}

      <ContactToUpgradeDialog
        open={showUpgrade}
        onOpenChange={setShowUpgrade}
        title="Scheduling is part of a paid subscription"
        description="Scheduled runs, data-change triggers, alerts and webhooks let you productionise your work — they're available on a paid subscription. Contact Prometheux to upgrade."
        contactSubject="Upgrade request — scheduling & alerts"
      />
    </div>
  );
};

export default PolicySection;
