// still has other active members (implementation-defined — surface the raw
// `detail` message so the user knows what to do next).
export async function deleteTeam(
  teamId: string,
  supabaseToken: string | null,
): Promise<{ team_id: string; status: "deleted" }> {
  assertTeamId(teamId, "delete team");
  return call<{ team_id: string; status: "deleted" }>("delete team", () =>
    HttpService.delete(
      teamsUrl(encodeURIComponent(teamId)),
      undefined,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

