// ---------------------------------------------------------------------------
// Seat management (owner-funded plan)
//
// The team owner buys a plan with a fixed number of seats. owner/admin
// assign / release specific seats — no consent step, and the assignment is
// automatically applied (a seated member inherits the team's plan). The
// owner always occupies one seat and can't be un-seated. Errors:
//   * 403 — caller isn't owner/admin (also enforced by the FE via
//           capabilities.canManageSeats).
//   * 409 — out of free seats on grant, or trying to revoke the owner's own
//           seat on release. Surface `detail` verbatim.
// Both endpoints are idempotent, so double-clicks are safe.
// ---------------------------------------------------------------------------

function assertUserId(userId: unknown, action: string): asserts userId is string {
  if (typeof userId !== "string" || userId.length === 0) {
    throw new TeamError(`Cannot ${action}: missing user id.`, 400);
  }
}

export async function grantSeat(
  teamId: string,
  userId: string,
  supabaseToken: string | null,
): Promise<{ team_id: string; user_id: string; seat_granted: true }> {
  assertTeamId(teamId, "grant seat");
  assertUserId(userId, "grant seat");
  return call<{ team_id: string; user_id: string; seat_granted: true }>("grant seat", () =>
    HttpService.post(
      teamsUrl(`${encodeURIComponent(teamId)}/members/${encodeURIComponent(userId)}/seat`),
      undefined,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}

export async function releaseSeat(
  teamId: string,
  userId: string,
  supabaseToken: string | null,
): Promise<{ team_id: string; user_id: string; seat_granted: false }> {
  assertTeamId(teamId, "release seat");
  assertUserId(userId, "release seat");
  return call<{ team_id: string; user_id: string; seat_granted: false }>("release seat", () =>
    HttpService.delete(
      teamsUrl(`${encodeURIComponent(teamId)}/members/${encodeURIComponent(userId)}/seat`),
      undefined,
      PROMETHEUX_CONFIG.AUTH_TOKEN,
      authHeaders(supabaseToken),
    ),
  );
}
