import type React from "react";
import { useState } from "react";
import type { ConceptCell } from "@/features/concept-editor/types";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";

interface DeleteCellDialogProps {
  /** Non-null opens the dialog. Null/undefined keeps it closed. */
  cell: ConceptCell | null;
  onConfirm: () => Promise<void> | void;
  onCancel: () => void;
}

/**
 * Confirmation modal shown when the user deletes a cell from the Explorer
 * tree (context menu or Delete key). Copy matches the trash-can dialog in
 * CellToolbar so the two surfaces share the same UX.
 */
export const DeleteCellDialog: React.FC<DeleteCellDialogProps> = ({
  cell,
  onConfirm,
  onCancel,
}) => {
  const [isDeleting, setIsDeleting] = useState(false);

  const handleConfirm = async () => {
    try {
      setIsDeleting(true);
      await onConfirm();
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <AlertDialog open={cell !== null} onOpenChange={(open) => !open && onCancel()}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Delete Cell</AlertDialogTitle>
          <AlertDialogDescription>
            Are you sure you want to delete this cell? It cannot be undone.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction
            onClick={handleConfirm}
            disabled={isDeleting}
            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
          >
            {isDeleting ? "Deleting..." : "Delete"}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
};
