import type { AttachmentKind, MessageAttachment } from "./attachments.types";

const IMAGE_EXTENSIONS = [
  ".png",
  ".jpg",
  ".jpeg",
  ".gif",
  ".webp",
  ".bmp",
  ".tif",
  ".tiff",
  ".svg",
] as const;

export function isImageFileName(name: string): boolean {
  const lower = name.toLowerCase();
  return IMAGE_EXTENSIONS.some((ext) => lower.endsWith(ext));
}

export function attachmentKind(name: string, mimeType?: string): AttachmentKind {
  if (mimeType?.startsWith("image/")) return "image";
  return isImageFileName(name) ? "image" : "file";
}

// The backend inlines each attachment into the stored user message as an
// <attachment filename="…" path="…">…extracted text…</attachment> block (or a
// self-closing one when extraction failed). Restored transcripts show the file
// as a chip, so the block is pulled back out of the text here.
// Self-closing form first: sharing one alternation would let the greedy tag
// scan run past a `/>` and swallow the next block along with it.
const ATTACHMENT_BLOCK_RE =
  /<attachment\b[^>]*\/>\s*|<attachment\b[^>]*>[\s\S]*?<\/attachment>\s*/g;
const FILENAME_ATTR_RE = /filename="([^"]*)"/;
const PATH_ATTR_RE = /path="([^"]*)"/;

export interface StoredMessageParts {
  text: string;
  attachments: MessageAttachment[];
}

/** Split a persisted user message into the text the user typed and the
 *  attachments the backend folded into it. */
export function splitStoredAttachments(content: string): StoredMessageParts {
  const blocks = content.match(ATTACHMENT_BLOCK_RE) ?? [];
  const parsed = blocks.map((block): MessageAttachment => {
    const path = block.match(PATH_ATTR_RE)?.[1];
    const name = block.match(FILENAME_ATTR_RE)?.[1] ?? path?.split("/").pop() ?? "attachment";
    return { name, kind: attachmentKind(name), path };
  });
  // One file can write more than one block — a scanned PDF contributes its
  // extracted text and a second block naming the pages sent as images — and
  // both describe the same chip.
  const byFile = new Map(parsed.map((a) => [a.path ?? a.name, a]));
  return {
    text: content.replace(ATTACHMENT_BLOCK_RE, "").trim(),
    attachments: [...byFile.values()],
  };
}
