import { BaseClient } from "@/shared/lib/BaseClient";
import type { SnowflakeComputePool } from "./snowflakeMachines";

export interface SnowflakePoolsResponse {
  status: "success" | "error";
  message: string;
  data?: {
    current_pool: string;
    pools: SnowflakeComputePool[];
  };
}

export interface SnowflakePoolActionResponse {
  status: "success" | "error";
  message: string;
  data?: {
    pool_name: string;
    state: string;
    grant_required?: boolean;
    grant_sql?: string;
  };
}

export interface SnowflakePoolStatusResponse {
  status: "success" | "error";
  message: string;
  data?: {
    pool_name: string;
    state: "ACTIVE" | "IDLE" | "SUSPENDED" | "STARTING" | "STOPPING" | "UNKNOWN";
    instance_family: string;
    min_nodes: number;
    max_nodes: number;
    num_services: number;
    num_jobs: number;
    is_current: boolean;
  };
}

export interface SnowflakeSwitchComputeResponse {
  status: "success" | "error";
  message: string;
  data?: {
    pool_name: string;
    restarting: boolean;
  };
}

/**
 * Client for Snowflake compute pool operations.
 * Communicates with jarvispy backend which executes Snowflake SQL commands.
 */
export class SnowflakeComputeClient extends BaseClient {
  /**
   * List all compute pools available to the app + the current active pool
   */
  async listPools(): Promise<SnowflakePoolsResponse> {
    try {
      return await this.get("/snowflake/compute/pools");
    } catch (error) {
      console.error("Error listing Snowflake compute pools:", error);
      throw error;
    }
  }

  /**
   * Create a compute pool with a given instance family and grant it to the app.
   * Backend runs: CREATE COMPUTE POOL + GRANT USAGE
   */
  async createPool(instanceFamily: string): Promise<SnowflakePoolActionResponse> {
    try {
      return await this.post("/snowflake/compute/pools", {
        instance_family: instanceFamily,
      });
    } catch (error) {
      console.error("Error creating Snowflake compute pool:", error);
      throw error;
    }
  }

  /**
   * Resume (start) a suspended compute pool.
   * Backend runs: ALTER COMPUTE POOL ... RESUME
   */
  async resumePool(poolName: string): Promise<SnowflakePoolActionResponse> {
    try {
      return await this.post("/snowflake/compute/pools/resume", {
        pool_name: poolName,
      });
    } catch (error) {
      console.error("Error resuming Snowflake compute pool:", error);
      throw error;
    }
  }

  /**
   * Suspend (stop) a compute pool.
   * Backend runs: ALTER COMPUTE POOL ... SUSPEND
   */
  async suspendPool(poolName: string): Promise<SnowflakePoolActionResponse> {
    try {
      return await this.post("/snowflake/compute/pools/suspend", {
        pool_name: poolName,
      });
    } catch (error) {
      console.error("Error suspending Snowflake compute pool:", error);
      throw error;
    }
  }

  /**
   * Drop (remove) a compute pool.
   * Backend runs: DROP COMPUTE POOL
   */
  async dropPool(poolName: string): Promise<SnowflakePoolActionResponse> {
    try {
      return await this.delete(`/snowflake/compute/pools/${encodeURIComponent(poolName)}`);
    } catch (error) {
      console.error("Error dropping Snowflake compute pool:", error);
      throw error;
    }
  }

  /**
   * Get status of a specific compute pool.
   * Backend runs: DESCRIBE COMPUTE POOL
   */
  async getPoolStatus(poolName: string): Promise<SnowflakePoolStatusResponse> {
    try {
      return await this.get(`/snowflake/compute/pools/${encodeURIComponent(poolName)}/status`);
    } catch (error) {
      console.error("Error getting Snowflake compute pool status:", error);
      throw error;
    }
  }

  /**
   * Switch platform to a different compute pool.
   * Backend runs: set_compute_pool() + init()
   * This restarts all SPCS services and the app URL changes.
   */
  async switchCompute(poolName: string): Promise<SnowflakeSwitchComputeResponse> {
    try {
      return await this.post("/snowflake/compute/switch", {
        pool_name: poolName,
      });
    } catch (error) {
      console.error("Error switching Snowflake compute pool:", error);
      throw error;
    }
  }
}
