import { Bookmark, History, RotateCcw, Upload } from "lucide-react";
import { useState } from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import type { DashboardVersion } from "../../api/DashboardClient";
import {
  formatVersionTimestamp,
  resolvePublishHint,
  useAppVersions,
} from "../../hooks/useAppVersions";
import { PUBLISHING_UI_ENABLED } from "../../publishing";
import type { AppDefinition } from "../../schema/appDefinition.types";

interface AppVersionsPanelProps {
  ontologyId: string;
  dashboardId: string;
  /** Called with the fresh draft definition after a restore succeeds. */
  onDraftReplaced: (definition: AppDefinition) => void;
}

interface VersionRowProps {
  version: DashboardVersion;
  isLatest: boolean;
  isRestoring: boolean;
  onRestore: (version: DashboardVersion) => void;
  onToggleBookmark: (version: DashboardVersion) => void;
}

function VersionRow({
  version,
  isLatest,
  isRestoring,
  onRestore,
  onToggleBookmark,
}: VersionRowProps) {
  return (
    <li className="group flex items-center gap-2 px-3 py-2 rounded-md hover:bg-secondary/60 transition-colors">
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-1.5">
          <span className="text-xs font-semibold text-foreground">v{version.version}</span>
          {PUBLISHING_UI_ENABLED && version.published && (
            <span className="text-[10px] px-1.5 py-px rounded bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-400">
              Live
            </span>
          )}
          {PUBLISHING_UI_ENABLED && isLatest && !version.published && (
            <span className="text-[10px] px-1.5 py-px rounded bg-secondary text-muted-foreground">
              Draft
            </span>
          )}
          {!PUBLISHING_UI_ENABLED && isLatest && (
            <span className="text-[10px] px-1.5 py-px rounded bg-secondary text-muted-foreground">
              Current
            </span>
          )}
          {version.label && (
            <span className="text-[10px] text-muted-foreground truncate">{version.label}</span>
          )}
        </div>
        <div className="text-[10px] text-muted-foreground mt-0.5 truncate">
          {formatVersionTimestamp(version.createdAt)}
          {version.author ? ` · ${version.author}` : ""}
        </div>
      </div>

      <button
        type="button"
        onClick={() => onToggleBookmark(version)}
        title={version.bookmarked ? "Remove bookmark" : "Bookmark this version"}
        className={
          version.bookmarked
            ? "p-1 rounded text-amber-500 dark:text-amber-400"
            : "p-1 rounded text-muted-foreground/30 hover:text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity"
        }
      >
        <Bookmark className="h-3.5 w-3.5" fill={version.bookmarked ? "currentColor" : "none"} />
      </button>

      {!isLatest && (
        <button
          type="button"
          onClick={() => onRestore(version)}
          disabled={isRestoring}
          title="Restore this version as the new draft"
          className="p-1 rounded text-muted-foreground/30 hover:text-foreground opacity-0 group-hover:opacity-100 transition-opacity disabled:opacity-30"
        >
          <RotateCcw className="h-3.5 w-3.5" />
        </button>
      )}
    </li>
  );
}

/**
 * Publish controls + checkpoint history for a dynamic app.
 *
 * Every save is a checkpoint; publishing freezes the latest checkpoint as the
 * snapshot viewers see. Restore never rewrites history — it re-saves the old
 * definition as a new checkpoint.
 */
export function AppVersionsPanel({
  ontologyId,
  dashboardId,
  onDraftReplaced,
}: AppVersionsPanelProps) {
  const {
    versions,
    isLoading,
    status,
    publishedVersion,
    hasUnpublishedChanges,
    publish,
    unpublish,
    isPublishing,
    restore,
    isRestoring,
    toggleBookmark,
  } = useAppVersions(ontologyId, dashboardId, onDraftReplaced);

  const [pendingRestore, setPendingRestore] = useState<DashboardVersion | null>(null);

  const isPublished = status === "published";
  const isUpToDate = isPublished && !hasUnpublishedChanges;
  const publishLabel = hasUnpublishedChanges ? "Republish" : "Publish";
  const latestVersionNumber = versions[0]?.version ?? null;

  const handleConfirmRestore = () => {
    if (pendingRestore) restore(pendingRestore.id);
    setPendingRestore(null);
  };

  return (
    <aside className="w-[264px] flex-shrink-0 border-l border-border flex flex-col overflow-hidden bg-card">
      {PUBLISHING_UI_ENABLED && (
        <div className="px-4 py-3 border-b border-border flex-shrink-0">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs font-semibold text-foreground">Publishing</span>
            {isPublished ? (
              <span className="text-[10px] px-2 py-0.5 rounded-full bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-400">
                Published · v{publishedVersion}
              </span>
            ) : (
              <span className="text-[10px] px-2 py-0.5 rounded-full bg-secondary text-muted-foreground">
                Draft
              </span>
            )}
          </div>
          <p className="text-[11px] text-muted-foreground leading-snug mb-3">
            {resolvePublishHint(isPublished, isUpToDate, publishedVersion)}
          </p>
          <div className="flex items-center gap-2">
            <Button
              size="sm"
              onClick={publish}
              disabled={isPublishing || isUpToDate}
              className="gap-1.5 h-7 text-xs"
            >
              {isPublishing ? <PrometheuxSpinner size={12} /> : <Upload className="h-3 w-3" />}
              {isUpToDate ? "Up to date" : publishLabel}
            </Button>
            {isPublished && (
              <Button
                size="sm"
                variant="ghost"
                onClick={unpublish}
                disabled={isPublishing}
                className="h-7 text-xs text-muted-foreground"
              >
                Unpublish
              </Button>
            )}
          </div>
        </div>
      )}

      <div className="flex items-center gap-1.5 px-4 pt-3 pb-1 flex-shrink-0">
        <History className="h-3.5 w-3.5 text-muted-foreground" />
        <span className="text-xs font-semibold text-foreground">Version history</span>
      </div>

      {isLoading && (
        <div className="flex items-center gap-2 px-4 py-3 text-xs text-muted-foreground">
          <PrometheuxSpinner size={14} />
          Loading versions…
        </div>
      )}

      {!isLoading && versions.length === 0 && (
        <p className="px-4 py-3 text-[11px] text-muted-foreground">
          No checkpoints yet — every save creates one.
        </p>
      )}

      <ul className="flex-1 overflow-y-auto px-1.5 pb-2">
        {versions.map((version) => (
          <VersionRow
            key={version.id}
            version={version}
            isLatest={version.version === latestVersionNumber}
            isRestoring={isRestoring}
            onRestore={setPendingRestore}
            onToggleBookmark={toggleBookmark}
          />
        ))}
      </ul>

      <AlertDialog
        open={!!pendingRestore}
        onOpenChange={(open) => {
          if (!open) setPendingRestore(null);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Restore version {pendingRestore?.version}?</AlertDialogTitle>
            <AlertDialogDescription>
              The app will be reverted to v{pendingRestore?.version}. Any unsaved editor changes
              will be replaced. Nothing is deleted — the current state stays in the version history,
              and the restore is recorded as a new checkpoint.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmRestore}>Restore</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </aside>
  );
}
