import { zodResolver } from "@hookform/resolvers/zod";
import { Play } from "lucide-react";
import { type ReactNode, useEffect } from "react";
import { type Control, Controller, type FieldValues, useForm, useWatch } from "react-hook-form";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Label } from "@/shared/components/ui/label";
import { cn } from "@/shared/lib/utils";
import { useTabContext } from "../runtime/tabContext";
import type { AppInputDef, FormFieldDef } from "../schema/appDefinition.types";
import { RecordGroupField } from "./fields/RecordGroupField";
import { ScalarFieldControl } from "./fields/ScalarFieldControl";
import { buildFormDefaults, buildFormSchema, isFieldVisible } from "./formSchema";

/**
 * Field ids come from the app definition at runtime, so the value map cannot be
 * described more precisely than react-hook-form's own FieldValues. Using their
 * alias is what lets useFieldArray resolve a dynamic name (see RecordGroupField).
 */
export type FormValues = FieldValues;

const FIELD_SPAN_CLASSES: Record<number, string> = {
  1: "md:col-span-1",
  2: "md:col-span-2",
  3: "md:col-span-3",
  4: "md:col-span-4",
  5: "md:col-span-5",
  6: "md:col-span-6",
  7: "md:col-span-7",
  8: "md:col-span-8",
  9: "md:col-span-9",
  10: "md:col-span-10",
  11: "md:col-span-11",
  12: "md:col-span-12",
};

interface FieldRowProps {
  field: FormFieldDef;
  control: Control<FormValues>;
  ontologyId: string;
  labelLeft: boolean;
  error?: string;
}

function FieldRow({ field, control, ontologyId, labelLeft, error }: FieldRowProps) {
  const label = (
    <Label className="text-[11px] font-medium text-foreground/70">
      {field.label ?? field.id}
      {field.required && <span className="text-destructive ml-0.5">*</span>}
    </Label>
  );
  const controlNode: ReactNode =
    field.type === "record_group" ? (
      <RecordGroupField field={field} control={control} ontologyId={ontologyId} />
    ) : (
      <Controller
        control={control}
        name={field.id}
        render={({ field: rhf }) => (
          <ScalarFieldControl
            field={field}
            value={rhf.value}
            onChange={rhf.onChange}
            ontologyId={ontologyId}
          />
        )}
      />
    );
  const errorNode = error ? <p className="text-[11px] text-destructive">{error}</p> : null;

  if (labelLeft && field.type !== "record_group") {
    return (
      <div className="grid grid-cols-[140px_1fr] items-center gap-x-3">
        {label}
        <div className="flex flex-col gap-1">
          {controlNode}
          {errorNode}
        </div>
      </div>
    );
  }
  return (
    <div className="flex flex-col gap-1.5">
      {label}
      {controlNode}
      {errorNode}
    </div>
  );
}

/**
 * Structured form container (ADR D5 tier 2-3): schema-declared validation
 * compiled to RHF + Zod, conditional visibility, record groups. Its submit
 * button is the trigger of the run group bound to this form.
 *
 * Layouts: "flow" (default) — scalar fields as a responsive filter bar;
 * "grid" — a 12-column grid honoring each field's `span` (record editors,
 * signup cards). `labelPosition: "left"` puts labels beside the controls.
 */
export function FormWidget({
  input,
  ontologyId,
  isRunning = false,
  runError,
  onSubmitForm,
}: FormWidgetProps) {
  const { setValues } = useTabContext();
  const form = useForm<FormValues>({
    resolver: zodResolver(buildFormSchema(input)),
    defaultValues: buildFormDefaults(input),
  });
  const watched = useWatch({ control: form.control });

  // Publish form field changes to TabContext in real-time for auto-trigger run groups
  useEffect(() => {
    const flattened = Object.fromEntries(
      Object.entries(watched).map(([fieldId, value]) => [`${input.id}.${fieldId}`, value]),
    );
    setValues(flattened);
  }, [watched, input.id, setValues]);

  const handleSubmit = form.handleSubmit((values) => onSubmitForm(input.id, values));
  const isGrid = input.layout === "grid";
  const labelLeft = input.labelPosition === "left";

  const fieldError = (field: FormFieldDef) => {
    const error = form.formState.errors[field.id];
    return error ? String(error.message ?? "Invalid value") : undefined;
  };

  const renderGridSection = (fields: FormFieldDef[]) => (
    <div className="grid grid-cols-12 gap-x-3 gap-y-4">
      {fields.map((field) => (
        <div
          key={field.id}
          className={cn(
            "col-span-12",
            field.type !== "record_group" && FIELD_SPAN_CLASSES[field.span ?? 12],
          )}
        >
          <FieldRow
            field={field}
            control={form.control}
            ontologyId={ontologyId}
            labelLeft={labelLeft}
            error={fieldError(field)}
          />
        </div>
      ))}
    </div>
  );

  const renderFlowSection = (fields: FormFieldDef[]) => {
    // Scalar fields lay out as a filter bar; record groups take full width.
    const scalarFields = fields.filter((field) => field.type !== "record_group");
    const recordGroups = fields.filter((field) => field.type === "record_group");
    return (
      <>
        {scalarFields.length > 0 && (
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-5">
            {scalarFields.map((field) => (
              <FieldRow
                key={field.id}
                field={field}
                control={form.control}
                ontologyId={ontologyId}
                labelLeft={false}
                error={fieldError(field)}
              />
            ))}
          </div>
        )}
        {recordGroups.map((field) => (
          <FieldRow
            key={field.id}
            field={field}
            control={form.control}
            ontologyId={ontologyId}
            labelLeft={false}
            error={fieldError(field)}
          />
        ))}
      </>
    );
  };

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-4">
      {(input.sections ?? []).map((section) => {
        const visibleFields = section.fields.filter((field) => isFieldVisible(field, watched));
        return (
          <div
            key={section.title ?? section.fields[0]?.id ?? "section"}
            className="flex flex-col gap-3"
          >
            {section.title && (
              <h4 className="text-xs font-semibold text-foreground/80">{section.title}</h4>
            )}
            {isGrid ? renderGridSection(visibleFields) : renderFlowSection(visibleFields)}
          </div>
        );
      })}
      <Button type="submit" disabled={isRunning} className="self-start gap-2">
        {isRunning ? <PrometheuxSpinner size={14} /> : <Play className="h-3.5 w-3.5" />}
        {input.submitLabel ?? "Run"}
      </Button>
      {runError && <p className="text-[11px] text-destructive">{runError}</p>}
    </form>
  );
}

interface FormWidgetProps {
  input: AppInputDef;
  ontologyId: string;
  isRunning?: boolean;
  runError?: string;
  onSubmitForm: (formId: string, values: FormValues) => void;
}
