import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { useConcepts } from "@/features/concepts/hooks/useConcepts";
import { useDataSources } from "@/features/data-sources/hooks/useDataSources";
import type { DataSource } from "@/features/data-sources/types";
import { groupDataSourcesByLocationAndType } from "@/features/data-sources/utils";
import { useOntologyId } from "@/features/ontologies/hooks/useOntologyId";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { trackConceptCreated } from "@/shared/services/analyticsEvents";
import { HttpService } from "@/shared/services/httpService";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";
import type { LibraryPanel } from "../components/ConceptLibrarySidebar";
import {
  extractSavedConceptName,
  getConceptNameFromTableName,
} from "../conceptFromDataSource.utils";

export interface ExpandSignal {
  open: boolean;
  nonce: number;
}

interface UseLibrarySidebarParams {
  panel: LibraryPanel;
  onRefreshCells?: () => Promise<void>;
}

/** Stable id for a top-level data group (location + sub-group name). */
const groupId = (location: string, name: string) => `${location}_${name}`;

const PANEL_TITLES: Record<LibraryPanel, string> = {
  concepts: "Concepts",
  data: "Data",
  context: "Context",
};

const SEARCH_PLACEHOLDERS: Record<LibraryPanel, string> = {
  concepts: "Search by concept or field name...",
  data: "Search by datasource or column name...",
  context: "Search notes or connections...",
};

export function useLibrarySidebar({ panel, onRefreshCells }: UseLibrarySidebarParams) {
  const ontologyId = useOntologyId();
  const queryClient = useQueryClient();
  const { concepts, isLoading: conceptsLoading, loadConcepts } = useConcepts();
  const { dataSources, isLoading: dataLoading, loadDataSources } = useDataSources();
  const isLineagePanelExpanded = useEditorActionsStore((s) => s.isLineagePanelExpanded);

  const [search, setSearch] = useState({ term: "", open: false });
  const [expand, setExpand] = useState({ all: false, nonce: 0 });
  const [dataGroupValue, setDataGroupValue] = useState<string[]>([]);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const searchTerm = search.term;

  useEffect(() => {
    if (panel === "data" && dataSources.length === 0 && !dataLoading) {
      loadDataSources();
    }
  }, [panel, loadDataSources, dataSources.length, dataLoading]);

  const filteredConcepts = useMemo(() => {
    if (!searchTerm.trim()) return concepts;
    const lower = searchTerm.toLowerCase();
    return concepts.filter(
      (c) =>
        c.predicate_name.toLowerCase().includes(lower) ||
        (c.fields && Object.keys(c.fields).some((f) => f.toLowerCase().includes(lower))),
    );
  }, [concepts, searchTerm]);

  const filteredDataSources = useMemo(() => {
    if (!searchTerm.trim()) return dataSources;
    const lower = searchTerm.toLowerCase();
    return dataSources.filter(
      (ds) =>
        ds.tableName.toLowerCase().includes(lower) ||
        ds.datasourceType?.toLowerCase().includes(lower) ||
        (ds.fields && Object.keys(ds.fields).some((f) => f.toLowerCase().includes(lower))),
    );
  }, [dataSources, searchTerm]);

  const groupedDataSources = useMemo(
    () => groupDataSourcesByLocationAndType(filteredDataSources),
    [filteredDataSources],
  );

  const allGroupIds = useMemo(
    () =>
      groupedDataSources.flatMap((loc) =>
        loc.subGroups.map((sub) => groupId(loc.location, sub.name)),
      ),
    [groupedDataSources],
  );

  const setSearchTerm = useCallback((term: string) => setSearch((s) => ({ ...s, term })), []);
  const toggleSearch = useCallback(() => setSearch((s) => ({ ...s, open: !s.open })), []);
  const closeSearch = useCallback(() => setSearch({ term: "", open: false }), []);

  const toggleExpandAll = useCallback(() => {
    setExpand((e) => ({ all: !e.all, nonce: e.nonce + 1 }));
    setDataGroupValue(expand.all ? [] : allGroupIds);
  }, [expand.all, allGroupIds]);

  const handleRefresh = useCallback(async () => {
    setIsRefreshing(true);
    try {
      if (panel === "concepts") {
        await loadConcepts(true);
      } else if (panel === "context") {
        await Promise.all([
          queryClient.invalidateQueries({ queryKey: ["context-notes"] }),
          queryClient.invalidateQueries({ queryKey: ["context-edges"] }),
        ]);
      } else {
        await loadDataSources();
      }
      toast.success(`${PANEL_TITLES[panel]} refreshed`);
    } catch {
      toast.error("Failed to refresh");
    } finally {
      setIsRefreshing(false);
    }
  }, [panel, loadConcepts, loadDataSources, queryClient]);

  const handleNavigateToCell = useCallback((conceptName: string) => {
    // Reuse the same cross-view focus path as the Document tab (see
    // SummaryHeader.focusOnLineage): register the concept for LineageView to
    // focus once mounted, then switch to the Lineage tab. This fits the canvas
    // to the node and opens its cell in the dock, without relying on the cell's
    // DOM element already being rendered.
    useEditorActionsStore.getState().register({ pendingLineageFocus: conceptName });
    window.dispatchEvent(new CustomEvent("switchTab", { detail: "lineage" }));
  }, []);

  const handleCreateConcept = useCallback(
    async (ds: DataSource) => {
      if (!ontologyId) {
        toast.error("No ontology selected");
        return;
      }
      const inputPredicate = ds.bindAnnotation.match(/@(?:bind|qbind)\("([^"]+)"/)?.[1];
      if (!inputPredicate) {
        toast.error("Could not parse data source annotation");
        return;
      }
      const rawOutput = ds.tableName
        ? getConceptNameFromTableName(ds.tableName)
        : `${inputPredicate}_view`;
      const outputPredicate = rawOutput === inputPredicate ? `${rawOutput}_view` : rawOutput;
      const fieldKeys = ds.fields ? Object.keys(ds.fields) : [];
      const columns = fieldKeys.join(",");
      const body =
        fieldKeys.length > 0
          ? `${outputPredicate}(${columns}) :-\n  ${inputPredicate}(${columns}).`
          : `${outputPredicate}() :-\n  ${inputPredicate}().`;
      const definition = `@post("${outputPredicate}","orderby(1)").\n\n${body}`;
      const bindAnnotationWithDot = ds.bindAnnotation.trimEnd().endsWith(".")
        ? ds.bindAnnotation
        : `${ds.bindAnnotation}.`;

      const response = await HttpService.post(
        `${PROMETHEUX_CONFIG.BASE_URL}/concepts/${ontologyId}/save`,
        {
          position: 0,
          definition,
          binds: {
            input: [{ predicate: inputPredicate, annotation: bindAnnotationWithDot }],
            output: [],
          },
          output_predicate: outputPredicate,
          concept_type: "logic",
          group: "group_id",
          scope: "user",
        },
        PROMETHEUX_CONFIG.AUTH_TOKEN,
      );
      if (response?.status === "error") {
        toast.error(response.message || "Failed to create concept");
        throw new Error(response.message);
      }
      const savedConceptName = extractSavedConceptName(response, outputPredicate);
      toast.success(`Concept "${savedConceptName}" created`);
      trackConceptCreated({ via: "datasource", conceptType: "logic", ontologyId });
      await Promise.all([loadConcepts(true), onRefreshCells?.()]);
      window.dispatchEvent(
        new CustomEvent("conceptCreated", { detail: { conceptName: savedConceptName } }),
      );
      if (!isLineagePanelExpanded) {
        window.dispatchEvent(
          new CustomEvent("lineageFocusConcept", { detail: { conceptName: savedConceptName } }),
        );
      }
    },
    [ontologyId, loadConcepts, onRefreshCells, isLineagePanelExpanded],
  );

  const searchPlaceholder = SEARCH_PLACEHOLDERS[panel];

  return {
    panelTitle: PANEL_TITLES[panel],
    conceptsLoading,
    dataLoading,
    filteredConcepts,
    groupedDataSources,
    searchTerm,
    setSearchTerm,
    isSearchOpen: search.open,
    toggleSearch,
    closeSearch,
    searchPlaceholder,
    allExpanded: expand.all,
    toggleExpandAll,
    expandSignal: { open: expand.all, nonce: expand.nonce } satisfies ExpandSignal,
    dataGroupValue,
    setDataGroupValue,
    isRefreshing,
    handleRefresh,
    handleCreateConcept,
    handleNavigateToCell,
    groupId,
  };
}
