import { useCallback, useEffect, useRef, useState } from "react";
import { flushSync } from "react-dom";
import { toast } from "sonner";
import { useRunLimitStore } from "@/features/billing/store/runLimitStore";
import type { ConceptStatusEvent } from "@/features/concept-editor/api/ConceptEditorClient";
import { ConceptConflictError } from "@/features/concept-editor/api/ConceptEditorClient";
import { useConceptEditorClient } from "@/features/concept-editor/api/ConceptEditorClientContext";
import { RunLimitExceededError } from "@/features/concept-editor/api/runLimitError";
import type { CellReorderDetail } from "@/features/concept-editor/hooks/useCellDragDrop";
import { CELL_REORDER_EVENT } from "@/features/concept-editor/hooks/useCellDragDrop";
import type {
  ConceptCell,
  ConceptType,
  ContextConceptConfig,
  LlmConceptConfig,
} from "@/features/concept-editor/types";
import { requiresConceptName } from "@/features/concept-editor/types";
import {
  contextCellFieldsFromConfig,
  createConceptCell,
  llmCellFieldsFromConfig,
  PYTHON_DEFAULT_CODE,
} from "@/features/concept-editor/utils/createCell";
import { buildLlmTruncation } from "@/features/concept-editor/utils/llmRunFacts";
import { EXECUTION_STOPPED_MESSAGE } from "@/features/concept-editor/utils/runStatus";
import { ConceptService } from "@/features/concepts/api";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";
import {
  isConceptReadOnlyError,
  isRoleInsufficientError,
} from "@/features/ontologies/sharing/selfHeal";
import { EngineWaitCancelledError, runWithEngineWait } from "@/shared/lib/engineBusy";
import { trackConceptCreated, trackConceptRun } from "@/shared/services/analyticsEvents";
import { simplifyFetchError } from "@/shared/utils/errorUtils";

export interface ConflictDialogState {
  open: boolean;
  conceptName: string;
  cellId: string;
  freshCode?: string;
}

export function useConceptEditor({ ensureEmptyCell = true }: { ensureEmptyCell?: boolean } = {}) {
  const [cells, setCells] = useState<ConceptCell[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [conflictDialog, setConflictDialog] = useState<ConflictDialogState>({
    open: false,
    conceptName: "",
    cellId: "",
  });
  const apiClient = useConceptEditorClient();
  const ontologyScope = useOntologyScope();
  const currentOntologyId = useOntologyId();

  // Mirror cells in a ref so callbacks can read the latest value without re-memoization.
  // Required for save-after-update flows (e.g. drag-to-group auto-save), where the save
  // must see the just-written group/code even if React hasn't re-rendered the consumer yet.
  const cellsRef = useRef<ConceptCell[]>(cells);
  cellsRef.current = cells;

  // Synchronous guard: prevents overlapping saves for the same cell even before
  // React flushes the isSaving state update to cellsRef.
  const savingGuardRef = useRef<Set<string>>(new Set());

  // ---------------------------------------------------------------------------
  // Load cells from backend
  // ---------------------------------------------------------------------------
  const loadCells = useCallback(async () => {
    const ontologyIdToUse = currentOntologyId || sessionStorage.getItem("currentOntologyId");
    if (!ontologyIdToUse) {
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    try {
      const response = await apiClient.loadConcepts();

      if (response.status === "success" && Array.isArray(response.data)) {
        const populatedConcepts = new Set<string>();
        for (const cellData of response.data) {
          const details = (cellData as any).concept_details;
          if (Array.isArray(details)) {
            for (const d of details) {
              if (d.is_populated) populatedConcepts.add(d.predicate_name);
            }
          }
        }
        const MAX_POSITION = 999999;
        const sortedCells = [...response.data].sort((a, b) => {
          let groupA = (a as any).group || "group_id";
          let groupB = (b as any).group || "group_id";
          if (typeof groupA === "string") groupA = groupA.replace(/^['"](.*)['"]$/, "$1");
          if (typeof groupB === "string") groupB = groupB.replace(/^['"](.*)['"]$/, "$1");
          if (groupA !== groupB) return groupA.localeCompare(groupB);
          const posA = a.position ?? MAX_POSITION;
          const posB = b.position ?? MAX_POSITION;
          return posA - posB;
        });

        // Preserve client-side cell IDs across reloads by matching on
        // cellBackendId. Regenerating IDs every time invalidates anything
        // holding a reference to the cell (ExplorerView's selectedCellId,
        // panelState.cellId in lineage, CellEditor view registry, etc.) and
        // forces those consumers to fall back to first-cell heuristics.
        // Read via the ref so this useCallback doesn't depend on `cells`
        // (the on-mount effect at line ~198 depends on loadCells — adding
        // `cells` to deps would loop).
        const existingIdByBackendId = new Map<string, string>();
        for (const existing of cellsRef.current) {
          if (existing.cellBackendId) {
            existingIdByBackendId.set(existing.cellBackendId, existing.id);
          }
        }

        const loaded: ConceptCell[] = sortedCells.map((cellData) => {
          const backendId = cellData.id;
          const cellId =
            (backendId && existingIdByBackendId.get(backendId)) ??
            `cell-${Date.now()}-${Math.random()}`;
          const conceptType = (cellData as any).concept_type || "logic";
          const parsed = (cellData as any).parsed;
          const mainCode = parsed?.code ?? "";
          const outputPredicate = (cellData as any).concept || "";
          const cellBinds = parsed?.binds ?? { input: [], output: [] };

          let groupValue = (cellData as any).group || "group_id";
          if (typeof groupValue === "string") {
            groupValue = groupValue.replace(/^['"](.*)['"]$/, "$1");
          }

          const baseCell: ConceptCell = {
            id: cellId,
            code: mainCode,
            result: null,
            isRunning: false,
            cellBackendId: cellData.id,
            isModified: false,
            lastSavedContent: mainCode,
            outputPredicate,
            // A persisted predicate is treated as an explicit choice so editing
            // the code later doesn't silently re-point the default to the last head.
            outputPredicateUserSet: !!outputPredicate,
            conceptType: conceptType as ConceptType,
            description: (cellData as any).description || undefined,
            group: groupValue,
            binds: cellBinds,
            readOnly: (cellData as unknown as { read_only?: boolean }).read_only === true,
            ...(conceptType === "context"
              ? contextCellFieldsFromConfig(
                  (cellData as { concept_config?: unknown }).concept_config,
                )
              : {}),
            ...(conceptType === "llm"
              ? llmCellFieldsFromConfig((cellData as { concept_config?: unknown }).concept_config)
              : {}),
          };

          const conceptNameForCell = baseCell.outputPredicate;
          if (conceptNameForCell && populatedConcepts.has(conceptNameForCell)) {
            baseCell.hasPersistedResults = true;
          }

          return baseCell;
        });

        if (ensureEmptyCell && loaded.length === 0) {
          loaded.push({
            id: `cell-${Date.now()}`,
            code: "",
            result: null,
            isRunning: false,
            isModified: false,
            lastSavedContent: "",
            group: "group_id",
          });
        }

        setCells(loaded);
      }
    } catch (error) {
      console.error("useConceptEditor: Error loading cells:", error);
    } finally {
      setIsLoading(false);
    }
  }, [currentOntologyId, apiClient, ensureEmptyCell]);

  const refreshCellContents = useCallback(
    async (excludeCellId?: string) => {
      const ontologyIdToUse = currentOntologyId || sessionStorage.getItem("currentOntologyId");
      if (!ontologyIdToUse) return;
      try {
        const response = await apiClient.loadConcepts();
        if (response.status !== "success" || !Array.isArray(response.data)) return;

        const backendMap = new Map<string, any>();
        for (const d of response.data) {
          if (d.id) backendMap.set(d.id, d);
        }

        setCells((prev) =>
          prev.map((c) => {
            if (c.id === excludeCellId) return c;
            const bd = c.cellBackendId ? backendMap.get(c.cellBackendId) : undefined;
            if (!bd) return c;
            const parsed = bd.parsed;
            const newCode = parsed?.code ?? "";
            const newBinds = parsed?.binds ?? c.binds;
            const newConcept = bd.concept || "";

            let groupValue = bd.group || "group_id";
            if (typeof groupValue === "string") {
              groupValue = groupValue.replace(/^['"](.*)['"]$/, "$1");
            }

            const nextConceptType = (bd.concept_type || c.conceptType) as ConceptType;
            const updated: any = {
              ...c,
              code: newCode,
              lastSavedContent: newCode,
              binds: newBinds,
              isModified: false,
              outputPredicate: newConcept || c.outputPredicate,
              description: bd.description || c.description,
              group: groupValue,
              conceptType: nextConceptType,
              readOnly: bd.read_only === true,
              ...(nextConceptType === "context"
                ? contextCellFieldsFromConfig(bd.concept_config)
                : {}),
              ...(nextConceptType === "llm" ? llmCellFieldsFromConfig(bd.concept_config) : {}),
            };

            return updated;
          }),
        );
      } catch (err) {
        console.error("refreshCellContents failed:", err);
      }
    },
    [currentOntologyId, apiClient],
  );

  // Load on mount and when project changes
  useEffect(() => {
    const timer = setTimeout(() => {
      loadCells();
    }, 100);
    return () => clearTimeout(timer);
  }, [loadCells]);

  // ---------------------------------------------------------------------------
  // Listen for drag-and-drop cell reorder events
  // ---------------------------------------------------------------------------
  useEffect(() => {
    const handleCellReorder = (event: CustomEvent<CellReorderDetail>) => {
      const { draggedCellId, targetCellId, position } = event.detail;

      setCells((prev) => {
        const draggedIndex = prev.findIndex((c) => c.id === draggedCellId);
        const targetIndex = prev.findIndex((c) => c.id === targetCellId);
        if (draggedIndex === -1 || targetIndex === -1) return prev;

        const draggedCell = prev[draggedIndex];
        const targetCell = prev[targetIndex];
        const cellGroup = draggedCell.group || "group_id";
        const targetGroup = targetCell.group || "group_id";
        if (cellGroup !== targetGroup) return prev;

        const next = [...prev];
        const dragged = next.splice(draggedIndex, 1)[0];

        let insertAt = next.findIndex((c) => c.id === targetCellId);
        if (position === "bottom") insertAt += 1;

        next.splice(insertAt, 0, dragged);

        const idsInGroup = next
          .filter((c) => (c.group || "group_id") === cellGroup && c.cellBackendId)
          .map((c) => c.cellBackendId!);

        if (idsInGroup.length > 0) {
          apiClient.reorderConcepts(idsInGroup, cellGroup).catch((err) => {
            console.error("Error reordering cells:", err);
            toast.error("Failed to persist cell order");
          });
        }

        return next;
      });
    };

    window.addEventListener(CELL_REORDER_EVENT, handleCellReorder as EventListener);
    return () => window.removeEventListener(CELL_REORDER_EVENT, handleCellReorder as EventListener);
  }, [apiClient]);

  // ---------------------------------------------------------------------------
  // Code change (flushSync for CodeMirror)
  // ---------------------------------------------------------------------------
  const handleCodeChange = useCallback((value: string, cellId: string) => {
    flushSync(() => {
      setCells((prev) => {
        const idx = prev.findIndex((c) => c.id === cellId || cellId === `${c.id}-data`);
        if (idx === -1) return prev;
        const cell = prev[idx];
        const isDataCode = cellId.endsWith("-data");
        const updated = {
          ...cell,
          [isDataCode ? "dataCode" : "code"]: value,
          isModified: value !== (cell.lastSavedContent ?? ""),
        };
        const arr = [...prev];
        arr[idx] = updated;
        return arr;
      });
    });
  }, []);

  // ---------------------------------------------------------------------------
  // Helper: build full cell content (code + binds + @output)
  // ---------------------------------------------------------------------------
  const _buildCellContent = useCallback((cell: ConceptCell): string => {
    let content = cell.code;
    if (cell.binds) {
      const lines: string[] = [];
      for (const b of cell.binds.input) {
        if (b.annotation) lines.push(b.annotation);
      }
      for (const b of cell.binds.output) {
        if (b.annotation) lines.push(b.annotation);
      }
      if (lines.length > 0) content = `${content.trim()}\n\n${lines.join("\n")}`;
    }
    if (cell.outputPredicate?.trim() && !content.includes("@output(")) {
      content = `${content.trim()}\n\n@output("${cell.outputPredicate.trim()}").`;
    }
    return content;
  }, []);

  // ---------------------------------------------------------------------------
  // Helper: check if concept is populated
  // ---------------------------------------------------------------------------
  const checkConceptPopulated = useCallback(
    async (conceptName: string): Promise<boolean> => {
      try {
        const pid = currentOntologyId || sessionStorage.getItem("currentOntologyId");
        if (!pid) return false;
        const concepts = await ConceptService.listConcepts(pid, ontologyScope);
        return concepts.find((c) => c.predicate_name === conceptName)?.is_populated === true;
      } catch {
        return false;
      }
    },
    [currentOntologyId, ontologyScope],
  );

  // After a run, intermediate dependency concepts also become populated on the
  // backend, but only the executed cell gets its flag flipped locally. Re-read the
  // populated set once and stamp every cell so the "restore results" button shows
  // up for the dependencies that ran alongside the target.
  const refreshPopulatedFlags = useCallback(async () => {
    try {
      const pid = currentOntologyId || sessionStorage.getItem("currentOntologyId");
      if (!pid) return;
      const concepts = await ConceptService.listConcepts(pid, ontologyScope);
      const populated = new Set(
        concepts.filter((c) => c.is_populated === true).map((c) => c.predicate_name),
      );
      setCells((prev) =>
        prev.map((c) => {
          const pred = c.outputPredicate;
          if (!pred) return c;
          const isPopulated = populated.has(pred);
          if ((c.hasPersistedResults || false) === isPopulated) return c;
          return { ...c, hasPersistedResults: isPopulated };
        }),
      );
    } catch {
      // Best-effort: button state will refresh on the next full reload.
    }
  }, [currentOntologyId, ontologyScope]);

  // ---------------------------------------------------------------------------
  // Save logic cell
  // ---------------------------------------------------------------------------
  const handleSaveCell = useCallback(
    async (
      cellId: string,
      freshCode?: string,
      showToast = true,
      forceOverwrite = false,
    ): Promise<string | undefined> => {
      if (savingGuardRef.current.has(cellId)) return undefined;
      savingGuardRef.current.add(cellId);
      setCells((prev) => prev.map((c) => (c.id === cellId ? { ...c, isSaving: true } : c)));
      try {
        const cellIndex = cellsRef.current.findIndex((c) => c.id === cellId);
        let cell = cellIndex >= 0 ? cellsRef.current[cellIndex] : undefined;
        if (!cell) throw new Error("Cell not found");

        const isSql = cell.conceptType === "sql";
        const isCypher = cell.conceptType === "cypher";
        const isPython = cell.conceptType === "python";
        const isContext = cell.conceptType === "context";
        const isLlm = cell.conceptType === "llm";
        const requiresName = requiresConceptName(cell.conceptType);
        if (requiresName && !cell.outputPredicate?.trim()) {
          const typeLabels: Partial<Record<ConceptType, string>> = {
            context: "Context",
            llm: "LLM",
            python: "Python",
            cypher: "Cypher",
            sql: "SQL",
          };
          const typeLabel = typeLabels[cell.conceptType ?? "sql"] ?? "SQL";
          throw new Error(`Please set a concept name before saving the ${typeLabel} cell`);
        }

        const isDynamicContext = isContext && cell.contextMode === "dynamic";
        if (isDynamicContext && !cell.contextQuery?.trim()) {
          throw new Error("Please enter a query before saving the dynamic Context cell");
        }
        if (isLlm && !(freshCode ?? cell.code)?.trim()) {
          throw new Error("Please write a prompt before saving the LLM cell");
        }

        if (freshCode !== undefined) {
          cell = { ...cell, code: freshCode };
          setCells((prev) => prev.map((c) => (c.id === cellId ? { ...c, code: freshCode } : c)));
        }

        const pid = currentOntologyId || sessionStorage.getItem("currentOntologyId");
        if (!pid) throw new Error("No ontology ID available");

        const codeForApi = cell.code;

        let conceptConfig: ContextConceptConfig | LlmConceptConfig | undefined;
        if (isDynamicContext) {
          conceptConfig = {
            mode: "dynamic",
            query: cell.contextQuery?.trim() ?? "",
            top_k: cell.contextTopK ?? null,
            kinds: cell.contextKinds ?? null,
          };
        } else if (isContext) {
          conceptConfig = { mode: "static", note_ids: cell.noteIds ?? [] };
        } else if (isLlm) {
          conceptConfig = cell.llmConfig ?? {};
        }

        const response = await apiClient.saveConcept(
          codeForApi,
          cellIndex,
          cell.cellBackendId,
          cell.description,
          cell.group || "group_id",
          cell.conceptType || "logic",
          cell.binds,
          cell.outputPredicate,
          requiresName ? cell.outputPredicate : undefined,
          forceOverwrite,
          conceptConfig,
        );

        if (response.status !== "success") throw new Error(response.message || "Failed to save");

        const unresolvedReferences = response.data?.unresolved_references;
        if (unresolvedReferences?.length) {
          toast.warning(
            `Saved, but ${unresolvedReferences.map((ref) => `{{${ref}}}`).join(", ")} ` +
              "matches no concept in this project — the prompt will show the model " +
              "the braces, not the data.",
          );
        }

        const backendId = response.data?.id;
        const isNewConcept = !cell.cellBackendId && backendId;
        if (backendId) {
          const serverDescription = response.data?.description;
          const serverConcept = response.data?.concept;
          const injectedBinds = response.data?.injected_binds;
          const savedCode = freshCode ?? cell.code;
          setCells((prev) => {
            const updated = prev.map((c) => {
              if (c.id !== cellId) return c;
              const patch: ConceptCell = {
                ...c,
                cellBackendId: backendId,
                isModified: false,
                code: savedCode,
                lastSavedContent: savedCode,
                error: undefined,
                ...(requiresName
                  ? { outputPredicate: cell!.outputPredicate }
                  : serverConcept !== undefined
                    ? { outputPredicate: serverConcept }
                    : {}),
                ...(serverDescription && !c.description ? { description: serverDescription } : {}),
              };
              if (injectedBinds?.length) {
                const existingBinds = c.binds || { input: [], output: [] };
                const existingPreds = new Set(existingBinds.input.map((b) => b.predicate));
                const newEntries = injectedBinds
                  .filter((ib) => !existingPreds.has(ib.predicate))
                  .map((ib) => ({ predicate: ib.predicate, annotation: ib.annotation }));
                if (newEntries.length > 0) {
                  patch.binds = {
                    ...existingBinds,
                    input: [...existingBinds.input, ...newEntries],
                  };
                }
              }
              return patch;
            });

            if (isNewConcept) {
              const savedCell = updated.find((c) => c.id === cellId);
              const group = savedCell?.group || "group_id";
              const idsInGroup = updated
                .filter((c) => (c.group || "group_id") === group && c.cellBackendId)
                .map((c) => c.cellBackendId!);
              if (idsInGroup.length > 0) {
                apiClient.reorderConcepts(idsInGroup, group).catch((err) => {
                  console.error("Error syncing positions after new concept save:", err);
                });
              }
            }

            return updated;
          });
        }

        window.dispatchEvent(new CustomEvent("cellExecuted"));
        return backendId;
      } catch (error) {
        if (error instanceof ConceptConflictError) {
          const cell = cellsRef.current.find((c) => c.id === cellId);
          setConflictDialog({
            open: true,
            conceptName: cell?.outputPredicate || "",
            cellId,
            freshCode,
          });
          return undefined;
        }
        console.error("Error saving cell:", error);
        const msg = error instanceof Error ? error.message : "Failed to save";
        setCells((prev) => prev.map((c) => (c.id === cellId ? { ...c, error: msg } : c)));
        if (showToast) toast.error(`Failed to save: ${msg}`);
        throw error;
      } finally {
        savingGuardRef.current.delete(cellId);
        setCells((prev) => prev.map((c) => (c.id === cellId ? { ...c, isSaving: false } : c)));
      }
    },
    [currentOntologyId, apiClient],
  );

  const handleConfirmOverwrite = useCallback(async () => {
    const { cellId, freshCode } = conflictDialog;
    setConflictDialog((prev) => ({ ...prev, open: false }));
    if (cellId) {
      await handleSaveCell(cellId, freshCode, true, true);
      await loadCells();
    }
  }, [conflictDialog, handleSaveCell, loadCells]);

  const handleCancelOverwrite = useCallback(() => {
    setConflictDialog({ open: false, conceptName: "", cellId: "" });
  }, []);

  // Per-cell abort handles for the "waiting for the engine" retry loop, so a
  // Stop press can cancel a parked run that has no active WebSocket to close.
  const engineWaitControllers = useRef<Map<string, AbortController>>(new Map());

  // ---------------------------------------------------------------------------
  // Run cell (logic or SQL)
  // ---------------------------------------------------------------------------
  const handleRunCell = useCallback(
    async (cellId: string, freshCode?: string, forceRerun?: boolean) => {
      const cellIndex = cells.findIndex((c) => c.id === cellId);
      let cell = cellIndex >= 0 ? cells[cellIndex] : undefined;
      if (!cell) {
        toast.error("Cell not found");
        return;
      }

      const isSql = cell.conceptType === "sql";
      const isCypher = cell.conceptType === "cypher";
      const isPython = cell.conceptType === "python";
      const requiresName = requiresConceptName(cell.conceptType);

      if (requiresName && !cell.outputPredicate?.trim()) {
        toast.error("Please set a concept name before running");
        return;
      }

      if (freshCode !== undefined) {
        cell = { ...cell, code: freshCode };
        if (!requiresName) {
          const regex = /^\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\([^)]*\)\s*(<-|:-)/gm;
          const matches = Array.from(freshCode.matchAll(regex));
          const preds = matches.map((m) => m[1]);
          if (preds.length > 0) {
            const cur = cell.outputPredicate;
            if (!cur || !preds.includes(cur)) cell = { ...cell, outputPredicate: preds[0] };
          }
        }
      }

      setCells((prev) =>
        prev.map((c) =>
          c.id === cellId
            ? { ...c, isRunning: true, error: undefined, code: freshCode ?? c.code }
            : c,
        ),
      );

      try {
        const pid = currentOntologyId || sessionStorage.getItem("currentOntologyId");
        if (!pid) throw new Error("No ontology ID available");

        let backendId: string | undefined;
        let updatedBinds = cell.binds;

        // Run is two steps: save first, then execute. Save is editor-only on the
        // backend; Run is allowed for viewers of shared projects. So if the save
        // step is denied with the role-insufficient 403, we swallow it and
        // continue with whatever backendId the cell already has. Any other error
        // (validation, network, parse) still aborts as before.
        try {
          if (requiresName) {
            const savedBackendId = await handleSaveCell(cellId, cell.code, false);
            backendId = (savedBackendId as string) || cell.cellBackendId;
          } else {
            const codeForRunSave = cell.code;

            const saveResp = await apiClient.saveConcept(
              codeForRunSave,
              cellIndex,
              cell.cellBackendId,
              cell.description,
              cell.group || "group_id",
              cell.conceptType || "logic",
              cell.binds,
              cell.outputPredicate,
            );
            if (saveResp.status !== "success")
              throw new Error(saveResp.message || "Failed to save before running");

            backendId = saveResp.data?.id || cell.cellBackendId;
            const saveDescription = saveResp.data?.description;
            const saveConcept = saveResp.data?.concept;
            const injectedBinds = saveResp.data?.injected_binds;

            if (saveConcept !== undefined) {
              cell = { ...cell, outputPredicate: saveConcept };
            }

            if (injectedBinds?.length) {
              const existingBinds = cell.binds || { input: [], output: [] };
              const existingPreds = new Set(existingBinds.input.map((b) => b.predicate));
              const newEntries = injectedBinds
                .filter((ib) => !existingPreds.has(ib.predicate))
                .map((ib) => ({ predicate: ib.predicate, annotation: ib.annotation }));
              if (newEntries.length > 0) {
                updatedBinds = {
                  ...existingBinds,
                  input: [...existingBinds.input, ...newEntries],
                };
              }
            }

            const isNewRunConcept = !cell.cellBackendId && backendId;
            setCells((prev) => {
              const updated = prev.map((c) => {
                if (c.id !== cellId) return c;
                const patch: ConceptCell = {
                  ...c,
                  cellBackendId: backendId,
                  isModified: false,
                  lastSavedContent: cell!.code,
                  ...(saveConcept !== undefined ? { outputPredicate: saveConcept } : {}),
                  ...(saveDescription && !c.description ? { description: saveDescription } : {}),
                };
                if (updatedBinds !== cell!.binds) {
                  patch.binds = updatedBinds;
                }
                return patch;
              });

              if (isNewRunConcept) {
                const group = cell.group || "group_id";
                const idsInGroup = updated
                  .filter((c) => (c.group || "group_id") === group && c.cellBackendId)
                  .map((c) => c.cellBackendId!);
                if (idsInGroup.length > 0) {
                  apiClient.reorderConcepts(idsInGroup, group).catch((err) => {
                    console.error("Error syncing positions after new concept run:", err);
                  });
                }
              }

              return updated;
            });
          }
        } catch (saveErr) {
          if (!isRoleInsufficientError(saveErr) && !isConceptReadOnlyError(saveErr)) throw saveErr;
          // Viewer on a shared project: save denied, Run still allowed. The
          // self-heal hook has already surfaced the "editor access required"
          // toast at the HTTP layer; here we just continue with the cell's
          // existing backend id so the run can proceed against the
          // last-saved version on the owner's pod.
          backendId = cell.cellBackendId;
          if (!backendId) {
            throw new Error("This concept must be saved first, which requires editor access.");
          }
        }

        window.dispatchEvent(new CustomEvent("conceptExecutionStart"));

        const onStatusEvent = (event: ConceptStatusEvent) => {
          window.dispatchEvent(new CustomEvent("conceptExecutionStatus", { detail: event }));
          // The engine accepted the run: the first status event means execution
          // has begun, so drop the "waiting for the engine" state right away —
          // not when the run finishes.
          setCells((prev) =>
            prev.map((c) =>
              c.id === cellId && c.isWaitingForEngine ? { ...c, isWaitingForEngine: false } : c,
            ),
          );
          if (event.concept && event.status === "error" && event.error) {
            setCells((prev) =>
              prev.map((c) => {
                const pred = c.outputPredicate;
                return pred === event.concept ? { ...c, error: event.error } : c;
              }),
            );
          } else if (event.concept && event.status === "success") {
            setCells((prev) =>
              prev.map((c) => {
                const pred = c.outputPredicate;
                return pred === event.concept && c.error ? { ...c, error: undefined } : c;
              }),
            );
          }
        };

        const runConceptName = requiresName
          ? cell.outputPredicate!
          : backendId || cell.outputPredicate!;
        trackConceptRun({
          runMode: (forceRerun ?? true) ? "workflow" : "cell",
          conceptType: cell.conceptType,
          ontologyId: currentOntologyId,
        });
        const engineWaitController = new AbortController();
        engineWaitControllers.current.set(cellId, engineWaitController);
        const response = await runWithEngineWait(
          () => apiClient.runConceptStream(runConceptName, onStatusEvent, forceRerun ?? true),
          {
            signal: engineWaitController.signal,
            onWaiting: () =>
              setCells((prev) =>
                prev.map((c) =>
                  c.id === cellId ? { ...c, isWaitingForEngine: true, error: undefined } : c,
                ),
              ),
            onResume: () =>
              setCells((prev) =>
                prev.map((c) => (c.id === cellId ? { ...c, isWaitingForEngine: false } : c)),
              ),
          },
        );

        if (isSql || isCypher || isPython) {
          if (response.status !== "success") {
            throw new Error(response.message || "Failed to run concept");
          }

          const evalResults = (response.data as any)?.evaluation_results;
          const elapsedTime = evalResults?.elapsedTime;

          const resultData: Record<string, any> = {};
          if (evalResults?.resultSet) {
            const colNames = evalResults.columnNames || {};
            Object.entries(evalResults.resultSet).forEach(([name, rows]) => {
              if (Array.isArray(rows)) {
                resultData[name] = {
                  columns:
                    colNames[name] ||
                    (rows.length > 0 ? rows[0].map((_: any, i: number) => `col_${i}`) : []),
                  rows,
                  pagination: {
                    page: 1,
                    totalPages: Math.ceil(rows.length / 10),
                    hasNext: rows.length > 10,
                    hasPrev: false,
                    totalCount: rows.length,
                  },
                };
              }
            });
          }
          const hasImmediate = Object.keys(resultData).length > 0;

          setCells((prev) =>
            prev.map((c) =>
              c.id === cellId
                ? {
                    ...c,
                    isRunning: !hasImmediate,
                    cellBackendId: backendId,
                    outputPredicate: cell!.outputPredicate,
                    result: hasImmediate
                      ? {
                          type: "query-result" as const,
                          data: resultData,
                          runElapsedTime: elapsedTime,
                        }
                      : null,
                    executionTime: elapsedTime,
                    error: undefined,
                    hasPersistedResults: true,
                    isModified: false,
                  }
                : c,
            ),
          );
        } else if (response?.data) {
          const results = response.data?.evaluation_results;
          // Only llm concepts report this: how much of each referenced upstream
          // the run actually sent, which the row budget can silently cap.
          const llmInputs = response.data?.llm_inputs;
          // Same, for the two silent cuts around the call itself: an overflowing
          // prompt and an answer stopped at the token ceiling.
          const llmTruncation = buildLlmTruncation(response.data);

          if (!results || Object.keys(results).length === 0 || !results.columnNames) {
            setCells((prev) =>
              prev.map((c) =>
                c.id === cellId
                  ? {
                      ...c,
                      isRunning: false,
                      cellBackendId: backendId,
                      isModified: false,
                      lastSavedContent: cell!.code,
                      llmInputs,
                      llmTruncation,
                    }
                  : c,
              ),
            );
            window.dispatchEvent(new CustomEvent("cellExecuted"));
            void refreshPopulatedFlags();
            return;
          }

          if (results?.columnNames) {
            const formattedData: Record<string, { columns: string[]; rows: any[][] }> = {};
            Object.keys(results.columnNames).forEach((tableName) => {
              if (tableName !== "prometheux_databricks_job_info") {
                formattedData[tableName] = {
                  columns: results.columnNames[tableName] || [],
                  rows: results.resultSet?.[tableName] || [],
                };
              }
            });

            setCells((prev) =>
              prev.map((c) =>
                c.id === cellId
                  ? {
                      ...c,
                      isRunning: false,
                      result: {
                        type: "query-result" as const,
                        data: formattedData,
                        runElapsedTime: results.elapsedTime,
                      },
                      cellBackendId: backendId,
                      isModified: false,
                      lastSavedContent: cell!.code,
                      hasPersistedResults: true,
                      llmInputs,
                      llmTruncation,
                    }
                  : c,
              ),
            );
          }
        }

        window.dispatchEvent(new CustomEvent("cellExecuted"));
        void refreshPopulatedFlags();

        // Fetch paginated output facts
        const pred = cell.outputPredicate?.trim();
        if (pred) {
          try {
            const factsResp = await apiClient.fetchOutputFacts(pid, pred, 1, ontologyScope);
            if (factsResp.status === "success" && factsResp.data) {
              setCells((prev) =>
                prev.map((c) => {
                  if (c.id === cellId) {
                    const data = c.result?.data ? { ...c.result.data } : {};
                    data[pred] = {
                      columns: factsResp.data.results.columnNames || [],
                      rows: factsResp.data.results.facts || [],
                      pagination: {
                        page: factsResp.data.pagination.page,
                        totalPages: factsResp.data.pagination.total_pages,
                        hasNext: factsResp.data.pagination.has_next,
                        hasPrev: factsResp.data.pagination.has_prev,
                        totalCount: factsResp.data.pagination.total_count,
                      },
                      fetchElapsedTime: factsResp.data.elapsedTime,
                    };
                    return {
                      ...c,
                      isRunning: false,
                      outputPredicate: pred,
                      result: c.result
                        ? { ...c.result, data }
                        : { type: "query-result" as const, data, runElapsedTime: c.executionTime },
                      hasPersistedResults: true,
                    };
                  }
                  return c;
                }),
              );
            }
          } catch (e) {
            console.error("Error fetching output facts:", e);
            const errorMsg = simplifyFetchError(e instanceof Error ? e.message : String(e));
            toast.error(errorMsg, { duration: 8000 });
            setCells((prev) => prev.map((c) => (c.id === cellId ? { ...c, error: errorMsg } : c)));
          }
        }
      } catch (error) {
        // Cancelling the engine-wait is a user stop, not a failure — render the
        // neutral "stopped" state rather than a red error.
        if (error instanceof EngineWaitCancelledError) {
          setCells((prev) =>
            prev.map((c) =>
              c.id === cellId
                ? {
                    ...c,
                    isRunning: false,
                    isWaitingForEngine: false,
                    error: EXECUTION_STOPPED_MESSAGE,
                  }
                : c,
            ),
          );
          return;
        }
        console.error("Error running cell:", error);
        if (error instanceof RunLimitExceededError) {
          useRunLimitStore.getState().openRunLimitDialog({
            kind: error.kind,
            limit: error.limit,
            message: error.message,
          });
        }
        const msg = error instanceof Error ? error.message : "Error running cell";
        setCells((prev) =>
          prev.map((c) =>
            c.id === cellId ? { ...c, isRunning: false, isWaitingForEngine: false, error: msg } : c,
          ),
        );
      } finally {
        engineWaitControllers.current.delete(cellId);
      }
    },
    [cells, currentOntologyId, ontologyScope, apiClient, handleSaveCell, refreshPopulatedFlags],
  );

  // ---------------------------------------------------------------------------
  // Delete cell
  // ---------------------------------------------------------------------------
  const handleDeleteCell = useCallback(
    async (cellId: string): Promise<void> => {
      const cell = cells.find((c) => c.id === cellId);
      const conceptName = cell?.cellBackendId;

      if (conceptName) {
        try {
          await apiClient.deleteConcepts([conceptName]);
          toast.success("Cell deleted");
        } catch (error) {
          console.error("Error deleting cell:", error);
          toast.error("Failed to delete cell");
          return;
        }
      }

      setCells((prev) => {
        const updated = prev.filter((c) => c.id !== cellId);
        if (updated.length === 0) {
          return [
            {
              id: `cell-${Date.now()}`,
              code: "",
              result: null,
              isRunning: false,
              isModified: false,
              lastSavedContent: "",
              group: "group_id",
            },
          ];
        }
        return updated;
      });
    },
    [cells, apiClient],
  );

  // ---------------------------------------------------------------------------
  // Stop cell
  // ---------------------------------------------------------------------------
  const handleStopCell = useCallback(
    async (_cellId: string) => {
      // Abort any parked engine-wait retries first — those runs have no live
      // WebSocket for stopEvaluation to reach.
      for (const controller of engineWaitControllers.current.values()) controller.abort();
      try {
        await apiClient.stopEvaluation();
      } catch (e) {
        console.error("Error stopping cell:", e);
      } finally {
        setCells((prev) =>
          prev.map((c) =>
            c.isRunning ? { ...c, isRunning: false, isWaitingForEngine: false } : c,
          ),
        );
      }
    },
    [apiClient],
  );

  // ---------------------------------------------------------------------------
  // Clear / Restore results
  // ---------------------------------------------------------------------------
  const handleClearResults = useCallback(
    async (cellId: string) => {
      const cell = cells.find((c) => c.id === cellId);
      const conceptName = cell?.outputPredicate;
      let isPopulated = false;
      if (conceptName) isPopulated = await checkConceptPopulated(conceptName);

      setCells((prev) =>
        prev.map((c) =>
          c.id === cellId
            ? { ...c, result: null, error: undefined, hasPersistedResults: isPopulated }
            : c,
        ),
      );
    },
    [cells, checkConceptPopulated],
  );

  const handleRestoreResults = useCallback(
    async (cellId: string) => {
      const cell = cells.find((c) => c.id === cellId);
      if (!cell?.cellBackendId) {
        toast.error("Cannot restore results: cell not found");
        return;
      }

      const conceptName = cell.outputPredicate;
      if (!conceptName) {
        toast.error("No concept name found for this cell");
        return;
      }

      toast.info("Restoring results...");
      try {
        const pid = currentOntologyId || sessionStorage.getItem("currentOntologyId");
        if (!pid) throw new Error("No ontology ID");

        const isPopulated = await checkConceptPopulated(conceptName);
        if (!isPopulated) {
          toast.error("This concept has no data to restore");
          setCells((prev) =>
            prev.map((c) => (c.id === cellId ? { ...c, hasPersistedResults: false } : c)),
          );
          return;
        }

        const factsResp = await apiClient.fetchOutputFacts(pid, conceptName, 1, ontologyScope);
        if (factsResp.status === "success" && factsResp.data) {
          const restoredData: Record<string, any> = {};
          restoredData[conceptName] = {
            columns: factsResp.data.results.columnNames || [],
            rows: factsResp.data.results.facts || [],
            pagination: {
              page: factsResp.data.pagination.page,
              totalPages: factsResp.data.pagination.total_pages,
              hasNext: factsResp.data.pagination.has_next,
              hasPrev: factsResp.data.pagination.has_prev,
              totalCount: factsResp.data.pagination.total_count,
            },
          };
          setCells((prev) =>
            prev.map((c) =>
              c.id === cellId
                ? {
                    ...c,
                    result: { type: "query-result" as const, data: restoredData },
                    error: undefined,
                    autoOpen: true,
                  }
                : c,
            ),
          );
        } else {
          throw new Error("Failed to fetch concept data");
        }
      } catch (error) {
        console.error("Error restoring results:", error);
        toast.error(
          `Failed to restore results: ${error instanceof Error ? error.message : "Unknown error"}`,
        );
      }
    },
    [cells, currentOntologyId, ontologyScope, apiClient, checkConceptPopulated],
  );

  // ---------------------------------------------------------------------------
  // Add cells
  // ---------------------------------------------------------------------------
  const handleAddCell = useCallback((group: string = "group_id") => {
    const newCell = createConceptCell({ conceptType: "logic", group, autoOpen: true });
    setCells((prev) => [...prev, newCell]);
    trackConceptCreated({ via: "editor_cell", conceptType: "logic" });
    return newCell;
  }, []);

  const handleAddCellAfter = useCallback(
    (afterCellId: string, conceptType: ConceptType = "logic") => {
      setCells((prev) => {
        // Resolve the anchor against the full cells array. The divider lives in a
        // filtered/grouped view, so a positional index from that view would not line
        // up here — find the anchor by id and insert immediately after it instead.
        const anchorIndex = prev.findIndex((c) => c.id === afterCellId);
        const newCell = createConceptCell({
          conceptType,
          group: prev[anchorIndex]?.group,
          autoOpen: conceptType === "sql" || conceptType === "cypher" || conceptType === "python",
        });
        if (anchorIndex === -1) return [...prev, newCell];
        const arr = [...prev];
        arr.splice(anchorIndex + 1, 0, newCell);
        return arr;
      });
      trackConceptCreated({ via: "editor_cell", conceptType });
    },
    [],
  );

  const handleAddSqlCell = useCallback((group: string = "group_id") => {
    const newCell = createConceptCell({ conceptType: "sql", group, autoOpen: true });
    setCells((prev) => [...prev, newCell]);
    trackConceptCreated({ via: "editor_cell", conceptType: "sql" });
    return newCell;
  }, []);

  const handleAddCypherCell = useCallback((group: string = "group_id") => {
    const newCell = createConceptCell({ conceptType: "cypher", group, autoOpen: true });
    setCells((prev) => [...prev, newCell]);
    trackConceptCreated({ via: "editor_cell", conceptType: "cypher" });
    return newCell;
  }, []);

  const handleAddPythonCell = useCallback((group: string = "group_id") => {
    const newCell = createConceptCell({ conceptType: "python", group, autoOpen: true });
    setCells((prev) => [...prev, newCell]);
    trackConceptCreated({ via: "editor_cell", conceptType: "python" });
    return newCell;
  }, []);

  /** New static context cell, optionally pre-pinned with note ids (the
   *  "create context concept from attached notes" bridge). */
  const handleAddContextCell = useCallback(
    (contextNoteIds: string[] = [], group: string = "group_id") => {
      const newCell = createConceptCell({
        conceptType: "context",
        group,
        autoOpen: true,
        contextNoteIds,
      });
      setCells((prev) => [...prev, newCell]);
      trackConceptCreated({ via: "editor_cell", conceptType: "context" });
      return newCell;
    },
    [],
  );

  // ---------------------------------------------------------------------------
  // Move cell within its group
  // ---------------------------------------------------------------------------
  const handleMoveCell = useCallback(
    (cellId: string, direction: "up" | "down") => {
      setCells((prev) => {
        const cellIndex = prev.findIndex((c) => c.id === cellId);
        if (cellIndex === -1) return prev;

        const cell = prev[cellIndex];
        const cellGroup = cell.group || "group_id";
        const sameGroup = prev.filter((c) => (c.group || "group_id") === cellGroup);
        const groupIndex = sameGroup.findIndex((c) => c.id === cellId);

        const canMove =
          (direction === "up" && groupIndex > 0) ||
          (direction === "down" && groupIndex < sameGroup.length - 1);
        if (!canMove) return prev;

        const targetCell = sameGroup[direction === "up" ? groupIndex - 1 : groupIndex + 1];
        const targetIndex = prev.findIndex((c) => c.id === targetCell.id);

        const next = [...prev];
        [next[cellIndex], next[targetIndex]] = [next[targetIndex], next[cellIndex]];

        const conceptNamesInGroup = next
          .filter((c) => (c.group || "group_id") === cellGroup && c.cellBackendId)
          .map((c) => c.cellBackendId!);

        if (conceptNamesInGroup.length > 0) {
          apiClient.reorderConcepts(conceptNamesInGroup, cellGroup).catch((err) => {
            console.error("Error reordering cells:", err);
            toast.error("Failed to persist cell order");
          });
        }

        return next;
      });
    },
    [apiClient],
  );

  // ---------------------------------------------------------------------------
  // Cell type / concept name change
  // ---------------------------------------------------------------------------
  const handleCellTypeChange = useCallback((cellId: string, newCellType: ConceptType) => {
    setCells((prev) =>
      prev.map((c) => {
        if (c.id !== cellId) return c;
        // Seed the Python starter body when switching an empty cell to Python,
        // never clobbering code the user already wrote.
        const code = newCellType === "python" && !c.code.trim() ? PYTHON_DEFAULT_CODE : c.code;
        // Context concepts hold a note selection / query instead of code; default
        // to static mode and init the selection empty.
        const noteIds = newCellType === "context" ? (c.noteIds ?? []) : c.noteIds;
        const contextMode = newCellType === "context" ? (c.contextMode ?? "static") : c.contextMode;
        // LLM concepts keep the code (it becomes the prompt template) and start
        // with an empty config (single response column, user-level LLM settings).
        const llmConfig = newCellType === "llm" ? (c.llmConfig ?? {}) : c.llmConfig;
        return {
          ...c,
          conceptType: newCellType,
          code,
          noteIds,
          contextMode,
          llmConfig,
          isModified: true,
        };
      }),
    );
  }, []);

  const handleOutputPredicateChange = useCallback((cellId: string, outputPredicate: string) => {
    setCells((prev) =>
      prev.map((c) =>
        c.id === cellId
          ? {
              ...c,
              outputPredicate: outputPredicate,
              outputPredicateUserSet: true,
              isModified: true,
            }
          : c,
      ),
    );
  }, []);

  // ---------------------------------------------------------------------------
  // Rename concept (used by lineage card inline edit and cell rename button)
  // ---------------------------------------------------------------------------
  const handleRenameConcept = useCallback(
    async (cellId: string, newName: string): Promise<void> => {
      const trimmedName = newName.trim().toLowerCase();
      if (!trimmedName) {
        toast.error("Concept name cannot be empty");
        return;
      }

      const cell = cells.find((c) => c.id === cellId);
      if (!cell) {
        toast.error("Cell not found");
        return;
      }

      const oldName = cell.outputPredicate || cell.cellBackendId;
      if (!oldName || oldName === trimmedName) return;

      if (!cell.cellBackendId) {
        toast.error("Save the cell before renaming");
        return;
      }

      try {
        const response = await apiClient.renameConcept(oldName, trimmedName);

        if (response.status !== "success") throw new Error(response.message || "Failed to rename");

        await loadCells();

        toast.success(`Concept renamed to "${trimmedName}"`);
      } catch (error) {
        const msg = error instanceof Error ? error.message : "Failed to rename";
        toast.error(`Failed to rename: ${msg}`);
      }
    },
    [cells, apiClient, loadCells],
  );

  // ---------------------------------------------------------------------------
  // Public API
  // ---------------------------------------------------------------------------
  return {
    cells,
    setCells,
    isLoading,
    loadCells,
    handleCodeChange,
    handleSaveCell,
    handleRunCell,
    handleDeleteCell,
    handleStopCell,
    handleClearResults,
    handleRestoreResults,
    handleAddCell,
    handleAddCellAfter,
    conflictDialog,
    handleConfirmOverwrite,
    handleCancelOverwrite,
    handleAddSqlCell,
    handleAddCypherCell,
    handleAddPythonCell,
    handleAddContextCell,
    handleMoveCell,
    handleCellTypeChange,
    handleOutputPredicateChange,
    handleRenameConcept,
  };
}
