import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { applyTeamAdminAction } from "../api";
import type { ShareError, ShareRole } from "../types";
import { CONCEPT_RESTRICTIONS_KEY } from "./useConceptRestrictions";
import { SHARE_INBOX_KEY } from "./useShareInbox";

interface UseTeamAdminShareActionsOptions {
  ontologyId: string;
  teamId: string;
}

interface UseTeamAdminShareActionsReturn {
  updateTeamRole: (role: ShareRole) => Promise<unknown>;
  revokeTeam: () => Promise<unknown>;
  reenableTeam: (role: ShareRole) => Promise<unknown>;
  isUpdatingRole: boolean;
  isRevoking: boolean;
  isReenabling: boolean;
}

// Team-wide delegated actions (update_team_role / revoke_team / reenable_team)
// for a recipient-team admin. Invalidates the inbox (the team admin sees the
// share there, carrying the base role) and the restrictions cache.
export function useTeamAdminShareActions({
  ontologyId,
  teamId,
}: UseTeamAdminShareActionsOptions): UseTeamAdminShareActionsReturn {
  const { session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;

  const invalidate = (): void => {
    queryClient.invalidateQueries({ queryKey: SHARE_INBOX_KEY });
    queryClient.invalidateQueries({ queryKey: CONCEPT_RESTRICTIONS_KEY });
  };

  const updateRoleMutation = useMutation<unknown, ShareError, ShareRole>({
    mutationFn: (role) =>
      applyTeamAdminAction(supabaseToken, ontologyId, teamId, {
        action: "update_team_role",
        share_role: role,
      }),
    onSuccess: invalidate,
  });

  const revokeMutation = useMutation<unknown, ShareError, void>({
    mutationFn: () =>
      applyTeamAdminAction(supabaseToken, ontologyId, teamId, { action: "revoke_team" }),
    onSuccess: invalidate,
  });

  const reenableMutation = useMutation<unknown, ShareError, ShareRole>({
    mutationFn: (role) =>
      applyTeamAdminAction(supabaseToken, ontologyId, teamId, {
        action: "reenable_team",
        share_role: role,
      }),
    onSuccess: invalidate,
  });

  return {
    updateTeamRole: updateRoleMutation.mutateAsync,
    revokeTeam: revokeMutation.mutateAsync,
    reenableTeam: reenableMutation.mutateAsync,
    isUpdatingRole: updateRoleMutation.isPending,
    isRevoking: revokeMutation.isPending,
    isReenabling: reenableMutation.isPending,
  };
}
