import { useQuery } from "@tanstack/react-query";
import { ChevronLeft, ChevronRight, Home, Server } from "lucide-react";
import React, { useCallback, useEffect } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { setCurrentOntologyId, setCurrentOntologyScope } from "@/features/ontologies/utils";
import { useAvatarSrc } from "@/features/settings/hooks/useAvatarSrc";
import { SidebarBottom } from "@/shared/components/layout/SidebarBottom";
import { SidebarNavButton } from "@/shared/components/layout/SidebarNavButton";
import { SidebarNavLink } from "@/shared/components/layout/SidebarNavLink";
import { SidebarOntologiesItem } from "@/shared/components/layout/SidebarOntologiesItem";
import { SidebarOntologyDashboardsItem } from "@/shared/components/layout/SidebarOntologyDashboardsItem";
import { SidebarWorkspaceLinks } from "@/shared/components/layout/SidebarWorkspaceLinks";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { useSafeNavigate } from "@/shared/hooks/editor/useUnsavedChangesWarning";
import { supabase } from "@/shared/integrations/supabase/client";
import { cn } from "@/shared/lib/utils";
import { useSidebarLayoutStore } from "@/shared/store/sidebarLayoutStore";
import { useSidebarStore } from "@/shared/store/sidebarStore";
import {
  extractUrlParams,
  generateEditorUrl,
  generateHomeUrl,
} from "@/shared/utils/navigationUtils";

// ─── Helpers ──────────────────────────────────────────────────────────────────

const RAIL_WIDTH_COLLAPSED = 56; // w-14
const RAIL_WIDTH_EXPANDED = 240; // w-60

function SectionLabel({ label }: { label: string }) {
  return (
    <p className="mb-1 px-3 text-xs font-medium uppercase tracking-wider text-muted-foreground">
      {label}
    </p>
  );
}

// ─── Types ────────────────────────────────────────────────────────────────────

interface SidePanelProps {
  activeTab: string;
  onTabChange: (value: string) => void;
  visible: boolean;
  onToggle: () => void;
  onBackFromSettings?: () => void;
  previousTab?: string;
  onCollapsedChange?: (isCollapsed: boolean) => void;
}

// ─── Component ────────────────────────────────────────────────────────────────

const SidePanel = React.memo(
  ({
    activeTab,
    onTabChange,
    visible,
    onBackFromSettings: _onBackFromSettings,
    previousTab: _previousTab = "overview",
    onCollapsedChange,
  }: SidePanelProps) => {
    const { collapsed, toggle } = useSidebarStore();
    const setRailWidth = useSidebarLayoutStore((state) => state.setRailWidth);
    const navigate = useNavigate();
    const safeNavigate = useSafeNavigate();
    const location = useLocation();
    const { user, signOut, jupyterLabUrl } = useAuth();

    // ── Page context ──────────────────────────────────────────────────────────

    const urlParams = extractUrlParams(location.pathname);
    const isDataSourcesPage = location.pathname === "/datasources";
    const isComputePage = location.pathname === "/compute";
    const isOntologiesPage = location.pathname === "/ontologies";
    const isAppsPage = location.pathname.startsWith("/apps");
    const isHomePage = location.pathname === "/" || urlParams.isHomePage;
    const isOnboardingPage = location.pathname === "/onboarding";
    const isProfilePage = location.pathname === "/profile";
    const isSettingsTab = activeTab === "settings";
    const isWorkspacePage =
      isHomePage || isDataSourcesPage || isComputePage || isOntologiesPage || isAppsPage;
    const currentOntologyId = urlParams.ontologyId || null;

    const defaultRoute = usePermissionsStore((state) => state.defaultRoute);
    const canSeeOntologies = usePermissionsStore((state) => state.canSee("can_see_projects"));
    const canSeeAiAgent = usePermissionsStore((state) => state.canSee("can_see_ai_agent"));
    const canSeeDynamicDashboards = usePermissionsStore((state) =>
      state.canSee("can_see_dynamic_dashboards"),
    );
    const canSeeComputePage = usePermissionsStore((state) => state.canSee("can_see_compute_page"));
    const canSeeJupyterLab = usePermissionsStore((state) => state.canSee("can_see_jupyter_lab"));
    const canSeeSettings = usePermissionsStore((state) => state.canSee("can_see_settings"));

    // Notify parent when collapsed state changes
    useEffect(() => {
      if (onCollapsedChange) onCollapsedChange(collapsed);
    }, [collapsed, onCollapsedChange]);

    // Publish the rail's rendered width so the docked AI chat can anchor to its
    // right edge. 0 when hidden, w-14 (56px) collapsed, w-60 (240px) expanded.
    useEffect(() => {
      setRailWidth(visible ? (collapsed ? RAIL_WIDTH_COLLAPSED : RAIL_WIDTH_EXPANDED) : 0);
      return () => setRailWidth(0);
    }, [visible, collapsed, setRailWidth]);

    // ── User profile ──────────────────────────────────────────────────────────

    const { data: currentUser } = useQuery({
      queryKey: ["profile", user?.id],
      queryFn: async () => {
        const {
          data: { user: authUser },
        } = await supabase.auth.getUser();
        if (!authUser) throw new Error("No user found");
        const { data: profile, error } = await supabase
          .from("profiles")
          .select("*")
          .eq("id", authUser.id)
          .single();
        if (error) throw error;
        return profile;
      },
      enabled: !!user,
    });

    const userDisplayName =
      currentUser?.first_name && currentUser?.last_name
        ? `${currentUser.first_name} ${currentUser.last_name}`
        : currentUser?.username || currentUser?.email || "Profile";

    const avatarSrc = useAvatarSrc(currentUser?.avatar_url);

    // ── Handlers ──────────────────────────────────────────────────────────────

    const handleHomeClick = useCallback(() => {
      const homeUrl = generateHomeUrl(user);
      const isAlreadyHome = location.pathname === homeUrl || location.pathname === "/";
      if (isAlreadyHome) {
        window.dispatchEvent(
          new CustomEvent("refreshProjects", { detail: { timestamp: Date.now() } }),
        );
      }
      navigate(homeUrl, {
        state: { refreshOntologies: true, activeTab: "projects", timestamp: Date.now() },
        replace: isAlreadyHome,
      });
    }, [user, location.pathname, navigate]);

    const handleNavigateToOntology = useCallback(
      (ontologyId: string, scope: string) => {
        if (location.pathname.includes("/editor/") && ontologyId === currentOntologyId) {
          safeNavigate(generateEditorUrl(user, ontologyId), {
            state: { activeTab: "lineage" },
            replace: false,
          });
          onTabChange("lineage");
          window.dispatchEvent(new CustomEvent("switchTab", { detail: "lineage" }));
          return;
        }

        // Set project context in sessionStorage so useProjectScope() returns the
        // correct value — without this, useConcepts() fetches with a stale scope
        // from the previous project, causing a data mismatch vs the canvas.
        setCurrentOntologyId(ontologyId);
        setCurrentOntologyScope(scope);
        // Clear stale concept cells so the editor loads fresh data for this project
        sessionStorage.removeItem("ontologyConceptCells");
        navigate(generateEditorUrl(user, ontologyId), {
          state: { activeTab: "lineage" },
        });
      },
      [user, navigate, location.pathname, currentOntologyId, safeNavigate, onTabChange],
    );

    const handleTabClick = useCallback(
      (tabValue: string) => {
        const params = extractUrlParams(location.pathname);
        const ontologyId = params.ontologyId;

        if (tabValue === "ontology") {
          if (!globalThis.cachedOntologyCode && globalThis.tempOntologyCode) {
            globalThis.cachedOntologyCode = globalThis.tempOntologyCode;
          }
          if (globalThis.cachedOntologyCode) {
            window.dispatchEvent(
              new CustomEvent("autoCompileRequested", { bubbles: true, cancelable: true }),
            );
          }
        }

        if (location.pathname.includes("/editor/") && ontologyId) {
          safeNavigate(generateEditorUrl(user, ontologyId), {
            state: { activeTab: tabValue },
            replace: false,
          });
          onTabChange(tabValue);
          window.dispatchEvent(new CustomEvent("switchTab", { detail: tabValue }));
          return;
        }

        onTabChange(tabValue);
        window.dispatchEvent(new CustomEvent("switchTab", { detail: tabValue }));
      },
      [onTabChange, location.pathname, user, safeNavigate],
    );

    const handleSignOut = useCallback(async () => {
      try {
        await signOut();
        navigate("/login");
      } catch (error) {
        console.error("Error in handleSignOut:", error);
      }
    }, [signOut, navigate]);

    const handleJupyterLabClick = useCallback(() => {
      if (jupyterLabUrl) {
        window.open(jupyterLabUrl, "_blank", "noopener,noreferrer");
      } else {
        toast.error("JupyterLab is not available for your account");
      }
    }, [jupyterLabUrl]);

    if (!visible) return null;

    const iconCls = "h-4 w-4 shrink-0";

    // ── Render ────────────────────────────────────────────────────────────────

    return (
      <aside
        className={cn(
          "fixed left-0 top-0 z-40 flex h-screen flex-col border-r bg-card transition-all duration-200",
          collapsed ? "w-14" : "w-60",
        )}
      >
        {/* Header */}
        <div className="flex h-14 shrink-0 items-center border-b px-3 mb-3">
          {collapsed ? (
            <button
              onClick={toggle}
              title="Expand sidebar"
              className="mx-auto flex flex-col items-center justify-center gap-0.5 text-muted-foreground transition-colors hover:text-foreground"
            >
              <img
                src="/prometheux-icon.png"
                alt="Prometheux"
                className="h-6 w-6 object-contain dark:invert"
                onClick={(e) => {
                  e.stopPropagation();
                  const homeUrl = defaultRoute ?? "/";
                  if (e.ctrlKey || e.metaKey || e.shiftKey) {
                    window.open(homeUrl, "_blank", "noopener,noreferrer");
                    return;
                  }
                  navigate(homeUrl);
                }}
              />
              <ChevronRight className="h-3 w-3" />
            </button>
          ) : (
            <>
              <Link
                to={defaultRoute ?? "/"}
                title="Go to homepage"
                className="h-7 flex-1 object-contain object-left"
              >
                <img
                  src="/prometheux-logo.png"
                  alt="Prometheux"
                  className="h-7 cursor-pointer object-contain object-left dark:invert"
                />
              </Link>
              <button
                onClick={toggle}
                title="Collapse sidebar"
                className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
              >
                <ChevronLeft className="h-4 w-4" />
              </button>
            </>
          )}
        </div>

        {/* Nav */}
        <nav className="flex-1 overflow-y-auto overflow-x-hidden px-2 pb-4">
          {!isOnboardingPage && (
            <>
              {/* Workspace */}
              <div className="mb-4">
                {!collapsed && <SectionLabel label="Workspace" />}
                {canSeeAiAgent && (
                  <SidebarNavLink
                    icon={<Home className={iconCls} />}
                    label="Home"
                    to={generateHomeUrl(user)}
                    onClick={handleHomeClick}
                    isActive={isHomePage}
                    collapsed={collapsed}
                  />
                )}
                {canSeeOntologies && (
                  <SidebarOntologiesItem
                    collapsed={collapsed}
                    isActive={isOntologiesPage}
                    currentOntologyId={currentOntologyId}
                    onNavigateToOntologies={() => navigate("/ontologies")}
                    onNavigateToOntology={handleNavigateToOntology}
                  />
                )}
                <SidebarWorkspaceLinks collapsed={collapsed} iconClassName={iconCls} />
              </div>

              {canSeeDynamicDashboards && currentOntologyId && (
                <SidebarOntologyDashboardsItem
                  ontologyId={currentOntologyId}
                  collapsed={collapsed}
                />
              )}

              {/* Manage */}
              {canSeeComputePage && (
                <div className="border-t pt-4">
                  {!collapsed && <SectionLabel label="Manage" />}
                  <SidebarNavLink
                    icon={<Server className={iconCls} />}
                    label="Compute"
                    to="/compute"
                    isActive={isComputePage || activeTab === "compute"}
                    collapsed={collapsed}
                  />
                </div>
              )}

              {/* Dev Tools */}
              {!PROMETHEUX_CONFIG.DEVELOPMENT_MODE &&
                !PROMETHEUX_CONFIG.SNOWFLAKE_MODE &&
                canSeeJupyterLab &&
                jupyterLabUrl && (
                  <div className="border-t pt-4">
                    {!collapsed && <SectionLabel label="Dev Tools" />}
                    <SidebarNavButton
                      icon={<img src="/jupyterlab.svg" alt="JupyterLab" className={iconCls} />}
                      label="JupyterLab"
                      onClick={handleJupyterLabClick}
                      collapsed={collapsed}
                    />
                  </div>
                )}
            </>
          )}
        </nav>

        <SidebarBottom
          collapsed={collapsed}
          userDisplayName={userDisplayName}
          avatarSrc={avatarSrc}
          isProfilePage={isProfilePage}
          isOnboardingPage={isOnboardingPage}
          isSettingsTab={isSettingsTab}
          canSeeSettings={canSeeSettings}
          onSignOut={handleSignOut}
        />
      </aside>
    );
  },
  (prevProps, nextProps) =>
    prevProps.activeTab === nextProps.activeTab &&
    prevProps.visible === nextProps.visible &&
    prevProps.previousTab === nextProps.previousTab,
);

SidePanel.displayName = "SidePanel";
export default SidePanel;
