import { CodeClient } from "@/features/concept-editor/api/CodeClient";
import type { ConceptData } from "@/features/concepts/api";

/** One output table of a concept (a rule-head predicate). */
export interface ConceptOutput {
  predicate: string;
  /** Column name -> type; type is "" when only derivable from the rule head. */
  columns: Record<string, string>;
  /** True for the concept's own predicate (has a stored, run-refreshed schema). */
  isPrimary: boolean;
}

const codeClient = new CodeClient();

/**
 * The concept's default output table: its own predicate, with the stored
 * schema (rule-head-derived at save time, refreshed with the engine's real
 * result columns after every run). This is what the cards display.
 */
export function primaryOutput(concept: ConceptData): ConceptOutput {
  return {
    predicate: concept.predicate_name,
    columns: concept.fields ?? {},
    isPrimary: true,
  };
}

/** The engine lowercases head variable names in materialized schemas. */
function columnsFromTerms(terms: string[]): Record<string, string> {
  return Object.fromEntries(terms.map((term) => [term.toLowerCase(), ""]));
}

function conceptDefinition(concept: ConceptData): string | undefined {
  if (concept.definition) return concept.definition;
  const detail =
    concept.concept_details?.find((d) => d.predicate_name === concept.predicate_name) ??
    concept.concept_details?.[0];
  return detail?.definition;
}

/**
 * Python concepts store their raw `def main(...)` body in `definition`; that is not
 * Vadalog and the analyze endpoint would 500 trying to compile it. They also
 * expose no rule-head predicates to derive columns from — the concept's own
 * `fields` are the authoritative schema — so analysis is skipped entirely.
 */
function isPythonConcept(concept: ConceptData): boolean {
  return concept.concept_type === "python";
}

/**
 * Find a derived output (intermediate rule head) by name across a project's
 * concepts — used by deep links like ?concept=air_edges_routes where the
 * predicate has no concept row of its own. Cheap prefilter on the definition text,
 * then confirmation via the parser. Returns the derived schema plus the
 * parent predicate (which is what must be run to materialize it).
 */
export async function resolveDerivedOutput(
  concepts: ConceptData[],
  predicate: string,
): Promise<{ concept: ConceptData; parentPredicate: string } | null> {
  const candidates = concepts.filter(
    (concept) => !isPythonConcept(concept) && conceptDefinition(concept)?.includes(predicate),
  );
  for (const parent of candidates) {
    const definition = conceptDefinition(parent);
    if (!definition) continue;
    const analysis = await codeClient.analyzeCode(definition);
    const terms = analysis.headPredicateTerms[predicate];
    if (!terms || terms.length === 0) continue;
    return {
      concept: {
        predicate_name: predicate,
        fields: columnsFromTerms(terms),
        column_names: Object.keys(columnsFromTerms(terms)),
        is_populated: parent.is_populated,
      },
      parentPredicate: parent.predicate_name,
    };
  }
  return null;
}
