import { Check, Copy } from "lucide-react";
import React from "react";
import type { Components } from "react-markdown";

// rehype-highlight transforms code children into <span> elements for coloring,
// so we can't just cast to string — we need to recurse through the React node tree.
function extractText(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(extractText).join("");
  if (React.isValidElement(node))
    return extractText((node.props as { children?: React.ReactNode }).children);
  return "";
}

type PreProps = React.HTMLAttributes<HTMLPreElement> & { children?: React.ReactNode };

/** Fenced code block with mac-style chrome and a copy button. */
function ChatCodeBlock({ children, ...props }: PreProps) {
  const codeEl = React.Children.toArray(children).find(
    (c): c is React.ReactElement => React.isValidElement(c) && c.type === "code",
  );
  const rawCode = codeEl ? extractText(codeEl).replace(/\n$/, "") : "";
  const [copied, setCopied] = React.useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(rawCode).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  return (
    <div className="my-3 rounded-xl overflow-hidden border border-white/[0.06] bg-[#1a1b26]">
      {/* Top bar */}
      <div className="flex items-center justify-between px-4 py-2 bg-white/[0.04] border-b border-white/[0.06]">
        <div className="flex gap-1.5">
          <span className="w-3 h-3 rounded-full bg-[#ff5f57]" />
          <span className="w-3 h-3 rounded-full bg-[#febc2e]" />
          <span className="w-3 h-3 rounded-full bg-[#28c840]" />
        </div>
        {rawCode && (
          <button
            type="button"
            onClick={handleCopy}
            className="flex items-center gap-1.5 text-[11px] text-white/40 hover:text-white/70 transition-colors"
          >
            {copied ? <Check className="h-3 w-3" /> : <Copy className="h-3 w-3" />}
            {copied ? "Copied!" : "Copy"}
          </button>
        )}
      </div>
      {/* Code */}
      <pre
        {...props}
        className="!m-0 !rounded-none !bg-transparent overflow-x-auto px-4 py-3 text-[13px] leading-[1.7] font-mono [-webkit-font-smoothing:antialiased] text-[#a9b1d6]"
      >
        {children}
      </pre>
    </div>
  );
}

/** Markdown renderers shared by the assistant panel's message list. */
export const chatMarkdownComponents: Components = {
  pre: ChatCodeBlock,
};
