import { CURRENT_SNAPSHOT_SOURCE, type OntologySnapshotMeta } from "@/features/ontologies/api";

export const CURRENT_SOURCE_LABEL = "Current state";

export function sourceLabel(source: string, snapshots: OntologySnapshotMeta[]): string {
  if (source === CURRENT_SNAPSHOT_SOURCE) return CURRENT_SOURCE_LABEL;
  const snapshot = snapshots.find((s) => s.id === source);
  return snapshot?.description?.trim() || "Snapshot";
}

function sourceTime(source: string, snapshots: OntologySnapshotMeta[]): number {
  if (source === CURRENT_SNAPSHOT_SOURCE) return Date.now();
  const snapshot = snapshots.find((s) => s.id === source);
  if (!snapshot) return 0;
  const time = new Date(snapshot.created_at).getTime();
  return Number.isNaN(time) ? 0 : time;
}

export interface OrderedDiffPair {
  baseSource: string;
  targetSource: string;
}

// Orders a selected pair so the diff always reads oldest -> newest.
export function orderDiffPair(
  selected: string[],
  snapshots: OntologySnapshotMeta[],
): OrderedDiffPair | null {
  if (selected.length !== 2) return null;
  const [first, second] = selected;
  const olderFirst = sourceTime(first, snapshots) <= sourceTime(second, snapshots);
  return {
    baseSource: olderFirst ? first : second,
    targetSource: olderFirst ? second : first,
  };
}
