import { Clock, Database, Play, Trash } from "lucide-react";
import type React from "react";
import { useCallback, useMemo, useState } from "react";
import type {
  CronTriggerConfig,
  DataChangeTriggerConfig,
  EvaluationPolicy,
} from "@/features/concept-editor/types";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { Switch } from "@/shared/components/ui/switch";
import { describeCron } from "./CronPolicyForm";
import { describeDataChangeInterval } from "./DataChangePolicyForm";

interface PolicyCardProps {
  policy: EvaluationPolicy;
  onToggle: (policyId: string, enabled: boolean) => Promise<void>;
  onDelete: (policyId: string) => Promise<void>;
  onTrigger: (policyId: string) => Promise<void>;
}

const PolicyCard: React.FC<PolicyCardProps> = ({ policy, onToggle, onDelete, onTrigger }) => {
  const [busy, setBusy] = useState(false);

  const handleToggle = useCallback(
    async (checked: boolean) => {
      setBusy(true);
      try {
        await onToggle(policy.policy_id, checked);
      } finally {
        setBusy(false);
      }
    },
    [policy.policy_id, onToggle],
  );

  const handleDelete = useCallback(async () => {
    setBusy(true);
    try {
      await onDelete(policy.policy_id);
    } finally {
      setBusy(false);
    }
  }, [policy.policy_id, onDelete]);

  const handleTrigger = useCallback(async () => {
    setBusy(true);
    try {
      await onTrigger(policy.policy_id);
    } finally {
      setBusy(false);
    }
  }, [policy.policy_id, onTrigger]);

  const isDataChange = policy.trigger_type === "data_change";

  const { humanLabel, subtitle, Icon } = useMemo(() => {
    if (isDataChange) {
      const cfg = policy.trigger_config as DataChangeTriggerConfig;
      return {
        humanLabel: "On data change",
        subtitle: describeDataChangeInterval(cfg.check_interval_minutes),
        Icon: Database,
      };
    }
    const cfg = policy.trigger_config as CronTriggerConfig;
    return {
      humanLabel: describeCron(cfg.cron_expression),
      subtitle: cfg.timezone ?? "UTC",
      Icon: Clock,
    };
  }, [policy, isDataChange]);

  const statusBadge = buildStatusBadge(policy);

  return (
    <div className="flex items-center gap-2 p-2 border border-border/50 rounded-md bg-background">
      <Switch
        checked={policy.enabled}
        onCheckedChange={handleToggle}
        disabled={busy}
        className="scale-75"
      />

      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-1.5">
          <Icon className="h-3 w-3 shrink-0 text-muted-foreground" />
          <span className="text-xs truncate">{humanLabel}</span>
          <span className="text-[10px] text-muted-foreground">({subtitle})</span>
        </div>
        {policy.last_run_at && (
          <div className="text-[10px] text-muted-foreground mt-0.5 truncate">
            Last run: {formatRelativeTime(policy.last_run_at)}
            {statusBadge}
          </div>
        )}
      </div>

      <div className="flex items-center gap-0.5 shrink-0">
        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6 p-0"
          onClick={handleTrigger}
          disabled={busy}
          title="Trigger now"
        >
          <Play className="h-3 w-3" />
        </Button>
        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6 p-0 hover:text-red-500"
          onClick={handleDelete}
          disabled={busy}
          title="Delete policy"
        >
          <Trash className="h-3 w-3" />
        </Button>
      </div>
    </div>
  );
};

function buildStatusBadge(policy: EvaluationPolicy) {
  if (!policy.last_run_status) return null;
  const variant = policy.last_run_status === "success" ? "secondary" : "destructive";
  return (
    <Badge variant={variant} className="ml-1.5 text-[9px] px-1.5 py-0 h-3.5 leading-none">
      {policy.last_run_status}
    </Badge>
  );
}

function formatRelativeTime(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  const minutes = Math.floor(diff / 60_000);
  if (minutes < 1) return "just now";
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

export default PolicyCard;
