import {
  BarChart3,
  ChevronDown,
  ChevronUp,
  Clock,
  Copy,
  Play,
  Search,
  Table2,
  Unplug,
  User,
} from "lucide-react";
import type React from "react";
import { useCallback, useRef, useState } from "react";
import { toast } from "sonner";
import QueryResultTable, {
  type ColumnFilterValue,
  type OrderByItem,
} from "@/features/concept-editor/components/query/components/QueryResultTable";
import { isPreviewableDataSource, maskBindSecrets } from "@/features/data-sources/bind.utils";
import RunDataSourceModal from "@/features/data-sources/components/RunDataSourceModal";
import { getDataSourcePath, getIconTypeForBinaryFile } from "@/features/data-sources/utils";
import DatabaseIcon from "@/shared/components/icons/DatabaseIcon";
import { Button } from "@/shared/components/ui/button";
import { Checkbox } from "@/shared/components/ui/checkbox";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

interface DataSourceListItemProps {
  id?: string;
  bindAnnotation: string;
  tableName?: string;
  fields?: Record<string, string>;
  index: number;
  rowCount?: number;
  columnCount?: number;
  author?: string;
  timestamp?: string;
  selected?: boolean;
  onSelect?: (id: string, isSelected: boolean) => void;
  onPreview?: (bindAnnotation: string) => Promise<any>;
  onPreviewPaginated?: (
    bindAnnotation: string,
    page: number,
    pageSize: number,
    orderBy?: Array<{ position: number; direction: "asc" | "desc" }>,
    searchTerm?: string,
    columnFilters?: Array<{ position: number; value: string; operator?: string }>,
  ) => Promise<any>;
  onDisconnect?: (id: string) => void;
  databaseName?: string;
}

const DATA_PAGE_SIZE = 10;

const DataSourceListItem: React.FC<DataSourceListItemProps> = ({
  id,
  bindAnnotation,
  tableName,
  fields,
  index,
  rowCount = 0,
  columnCount = 0,
  author,
  timestamp,
  selected = false,
  onSelect,
  onPreview,
  onPreviewPaginated,
  onDisconnect,
  databaseName,
}) => {
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewData, setPreviewData] = useState<any>(null);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const [isLoadingPreview, setIsLoadingPreview] = useState(false);
  const [isFetching, setIsFetching] = useState(false);
  const [fieldsExpanded, setFieldsExpanded] = useState(false);
  const [showRunModal, setShowRunModal] = useState(false);

  const orderByRef = useRef<OrderByItem[]>([]);
  const searchTermRef = useRef<string | undefined>(undefined);
  const columnFiltersRef = useRef<
    Array<{ position: number; value: string; operator?: string }> | undefined
  >(undefined);
  const pageSizeRef = useRef(DATA_PAGE_SIZE);

  const [searchState, setSearchState] = useState<{
    searchTerm: string;
    columnFilters?: Record<number, ColumnFilterValue>;
  }>({ searchTerm: "" });

  const getDataSourceName = () => {
    if (tableName) return tableName;
    const bindMatch = bindAnnotation.match(/@bind\("([^"]+)"/);
    const qbindMatch = bindAnnotation.match(/@qbind\("([^"]+)"/);
    const match = bindMatch || qbindMatch;
    return match ? match[1] : `Data Source ${index + 1}`;
  };

  const iconType = getIconTypeForBinaryFile(bindAnnotation);
  const filePath = getDataSourcePath({ databaseName, tableName });
  const canPreview =
    (!!onPreview || !!onPreviewPaginated) && isPreviewableDataSource(bindAnnotation);

  const formatTimestamp = (ts?: string) => {
    if (!ts) return "";
    try {
      const date = new Date(ts);
      return (
        date.toLocaleDateString() +
        " " +
        date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
      );
    } catch {
      return ts;
    }
  };

  const handleCopyBind = () => {
    navigator.clipboard.writeText(maskBindSecrets(bindAnnotation));
    toast.success("Copied to clipboard");
  };

  const fetchPage = useCallback(
    async (page: number) => {
      if (!onPreviewPaginated) {
        if (onPreview) {
          const result = await onPreview(bindAnnotation);
          if (result) {
            setPreviewData(result);
            return true;
          }
        }
        return false;
      }

      const ob = orderByRef.current.length
        ? orderByRef.current.map((o) => ({ position: o.position, direction: o.direction }))
        : undefined;
      const result = await onPreviewPaginated(
        bindAnnotation,
        page,
        pageSizeRef.current,
        ob,
        searchTermRef.current,
        columnFiltersRef.current,
      );
      if (result) {
        setPreviewData(result);
        return true;
      }
      return false;
    },
    [bindAnnotation, onPreview, onPreviewPaginated],
  );

  const handlePreviewToggle = async () => {
    if (previewOpen) {
      setPreviewOpen(false);
      return;
    }
    if (!canPreview) return;

    if (previewData) {
      setPreviewOpen(true);
      return;
    }

    setPreviewError(null);
    setPreviewOpen(true);
    setIsLoadingPreview(true);
    try {
      const ok = await fetchPage(1);
      if (!ok) setPreviewError("Failed to load preview data");
    } catch {
      setPreviewError("An error occurred while loading the preview");
    } finally {
      setIsLoadingPreview(false);
    }
  };

  const handlePageChange = useCallback(
    async (page: number) => {
      setIsFetching(true);
      try {
        await fetchPage(page);
      } catch {
        /* error state handled inside */
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage],
  );

  const handlePageSizeChange = useCallback(
    async (pageSize: number) => {
      pageSizeRef.current = pageSize;
      setIsFetching(true);
      try {
        await fetchPage(1);
      } catch {
        /* */
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage],
  );

  const handleSort = useCallback(
    async (orderBy: OrderByItem[]) => {
      orderByRef.current = orderBy;
      setIsFetching(true);
      try {
        await fetchPage(1);
      } catch {
        /* */
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage],
  );

  const handleSearch = useCallback(
    async (searchTerm?: string, columnFilters?: Record<number, ColumnFilterValue>) => {
      searchTermRef.current = searchTerm || undefined;
      const cfArray = columnFilters
        ? Object.entries(columnFilters)
            .filter(([, v]) =>
              typeof v === "object"
                ? v.value || ["is_null", "is_not_null"].includes(v.operator)
                : !!v,
            )
            .map(([k, v]) =>
              typeof v === "object"
                ? {
                    position: Number(k),
                    value: v.value,
                    ...(v.operator !== "contains" ? { operator: v.operator } : {}),
                  }
                : { position: Number(k), value: String(v) },
            )
        : undefined;
      columnFiltersRef.current = cfArray?.length ? cfArray : undefined;
      setSearchState({ searchTerm: searchTerm || "", columnFilters });
      setIsFetching(true);
      try {
        await fetchPage(1);
      } catch {
        /* */
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage],
  );

  const handleClearSearch = useCallback(async () => {
    searchTermRef.current = undefined;
    columnFiltersRef.current = undefined;
    setSearchState({ searchTerm: "" });
    setIsFetching(true);
    try {
      await fetchPage(1);
    } catch {
      /* */
    } finally {
      setIsFetching(false);
    }
  }, [fetchPage]);

  const handleClearColumnFilter = useCallback(
    async (columnIndex: number) => {
      const existing = columnFiltersRef.current?.filter((cf) => cf.position !== columnIndex);
      columnFiltersRef.current = existing?.length ? existing : undefined;
      const newFilters = { ...searchState.columnFilters };
      delete newFilters[columnIndex];
      setSearchState((prev) => ({
        ...prev,
        columnFilters: Object.keys(newFilters).length ? newFilters : undefined,
      }));
      setIsFetching(true);
      try {
        await fetchPage(1);
      } catch {
        /* */
      } finally {
        setIsFetching(false);
      }
    },
    [fetchPage, searchState.columnFilters],
  );

  const columnNames: string[] = previewData?.results?.columnNames || [];
  const facts: any[][] = previewData?.results?.facts || [];
  const fieldEntries = fields ? Object.entries(fields) : [];

  const paginationInfo = previewData?.pagination
    ? {
        page: previewData.pagination.page,
        totalPages: previewData.pagination.total_pages,
        hasNext: previewData.pagination.has_next,
        hasPrev: previewData.pagination.has_prev,
        totalCount: previewData.pagination.total_count,
        pageSize: previewData.pagination.page_size,
        orderBy: orderByRef.current.length ? orderByRef.current : undefined,
      }
    : undefined;

  return (
    <div
      className={`border-b border-border/50 ${selected ? "bg-primary/5 border-primary/20" : ""}`}
    >
      {/* Main row */}
      <div className="flex items-center justify-between py-3 px-4 hover:bg-muted/30 transition-colors">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-6">
            <div className="flex-shrink-0" onClick={(e) => e.stopPropagation()}>
              <div
                onClick={(e) => {
                  e.stopPropagation();
                  e.preventDefault();
                  if (id && onSelect) onSelect(id, !selected);
                }}
                className="cursor-pointer"
              >
                <Checkbox
                  checked={selected}
                  onCheckedChange={() => {}}
                  className="pointer-events-none"
                />
              </div>
            </div>

            <div className="flex items-center gap-2 min-w-0 flex-shrink-0">
              <DatabaseIcon type={iconType} className="h-4 w-4" />
              <div className="min-w-0">
                <div className="font-medium text-sm truncate">{getDataSourceName()}</div>
                {filePath && (
                  <div className="text-xs text-muted-foreground truncate" title={filePath}>
                    {filePath}
                  </div>
                )}
              </div>
            </div>

            {rowCount > 0 && (
              <div className="flex items-center gap-1 text-xs text-muted-foreground flex-shrink-0">
                <Table2 className="h-3 w-3" />
                <span>{rowCount} records</span>
              </div>
            )}

            <div className="flex items-center gap-1 text-xs text-muted-foreground flex-shrink-0">
              <BarChart3 className="h-3 w-3" />
              <span>{fieldEntries.length || columnCount} features</span>
              {fieldEntries.length > 0 && (
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setFieldsExpanded(!fieldsExpanded);
                  }}
                  className="ml-1 hover:text-foreground transition-colors"
                >
                  {fieldsExpanded ? (
                    <ChevronUp className="h-3 w-3" />
                  ) : (
                    <ChevronDown className="h-3 w-3" />
                  )}
                </button>
              )}
            </div>

            {author && (
              <div className="flex items-center gap-1 text-xs text-muted-foreground flex-shrink-0">
                <User className="h-3 w-3" />
                <span>{author}</span>
              </div>
            )}

            {timestamp && (
              <div className="flex items-center gap-1 text-xs text-muted-foreground flex-shrink-0">
                <Clock className="h-3 w-3" />
                <span>{formatTimestamp(timestamp)}</span>
              </div>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2" onClick={(e) => e.stopPropagation()}>
          <Button
            variant="ghost"
            size="sm"
            className="flex items-center gap-1 h-8 px-2 text-muted-foreground hover:text-[#212020]"
            onClick={() => setShowRunModal(true)}
            title="Run data source in an ontology"
          >
            <Play className="h-3 w-3" />
          </Button>
          {canPreview && (
            <Button
              variant={previewOpen ? "secondary" : "ghost"}
              size="sm"
              className="flex items-center gap-1 h-8 px-2"
              onClick={handlePreviewToggle}
              disabled={isLoadingPreview}
              title={previewOpen ? "Close preview" : "Preview first records"}
            >
              {isLoadingPreview ? (
                <PrometheuxSpinner size={16} />
              ) : previewOpen ? (
                <ChevronUp className="h-3 w-3" />
              ) : (
                <Search className="h-3 w-3" />
              )}
              {previewOpen && facts.length > 0 && (
                <span className="text-xs tabular-nums text-muted-foreground">{facts.length}</span>
              )}
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            className="flex items-center gap-1 h-8 px-2"
            onClick={handleCopyBind}
            title="Copy bind annotation"
          >
            <Copy className="h-3 w-3" />
          </Button>
          {onDisconnect && id && (
            <Button
              variant="ghost"
              size="sm"
              className="flex items-center gap-1 h-8 px-2 text-muted-foreground hover:text-red-500"
              onClick={() => onDisconnect(id)}
              title="Disconnect"
            >
              <Unplug className="h-3 w-3" />
            </Button>
          )}
        </div>
      </div>

      {fieldsExpanded && fieldEntries.length > 0 && (
        <div className="px-4 pb-3 pl-14 animate-in slide-in-from-top-1 duration-150">
          <div className="border rounded-md p-2 bg-muted/20">
            <div className="grid grid-cols-2 gap-x-4 gap-y-1">
              {fieldEntries.map(([name, type]) => (
                <div key={name} className="flex items-center justify-between text-xs">
                  <span className="font-mono text-foreground truncate">{name}</span>
                  <span className="text-muted-foreground ml-2">{type}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      <RunDataSourceModal
        isOpen={showRunModal}
        onClose={() => setShowRunModal(false)}
        bindAnnotation={bindAnnotation}
        tableName={tableName}
        fields={fields}
      />

      {previewOpen && (
        <div className="px-4 pb-3 pl-14 animate-in slide-in-from-top-1 duration-150 grid">
          {isLoadingPreview ? (
            <div className="border rounded-md flex items-center justify-center h-32">
              <PrometheuxSpinner size={16} label="Fetching records..." />
            </div>
          ) : previewError ? (
            <div className="border rounded-md flex items-center justify-center h-24">
              <p className="text-xs text-destructive">{previewError}</p>
            </div>
          ) : (
            <QueryResultTable
              data={{
                predicateName: previewData?.predicate || getDataSourceName(),
                columns: columnNames,
                rows: facts,
              }}
              pagination={paginationInfo}
              onPageChange={handlePageChange}
              onPageSizeChange={handlePageSizeChange}
              isLoading={isFetching}
              onSearch={handleSearch}
              onClearSearch={handleClearSearch}
              onClearColumnFilter={handleClearColumnFilter}
              searchState={searchState}
              onSort={handleSort}
            />
          )}
        </div>
      )}
    </div>
  );
};

export default DataSourceListItem;
