import { BarChart3, Clock, NotebookText } from "lucide-react";
import type React from "react";

type ConceptLanguage = "logic" | "sql" | "cypher" | "python" | "context" | "llm";

interface RecordCountFooterProps {
  isPopulated?: boolean;
  count?: number;
  executionTimeMs?: number;
  /** Context notes are attached — show the violet notebook marker. */
  hasContext?: boolean;
  /** Language the concept is defined in — shown as a pill on the left. */
  conceptType?: ConceptLanguage;
}

/**
 * Card footer bar. Keeps the header free for the full-width concept name by
 * hosting secondary metadata here instead: the definition-language pill on the
 * left, and the last-run stats (row count, elapsed time) plus the attached-
 * context marker on the right. Row/time values are cached from the lineage
 * response, reflecting the most recent run.
 */
export function RecordCountFooter({
  isPopulated,
  count,
  executionTimeMs,
  hasContext,
  conceptType,
}: RecordCountFooterProps) {
  const hasRows = Boolean(isPopulated && count && count > 0);
  if (!hasRows && !hasContext && !conceptType) return null;
  const seconds = executionTimeMs && executionTimeMs > 0 ? executionTimeMs / 1000 : null;
  return (
    <div className="flex items-center justify-between gap-3 border-t border-border/60 px-4 py-2.5 text-sm">
      <LanguageBadge conceptType={conceptType} />
      <div className="flex items-center gap-3">
        {hasRows && (
          <span className="flex items-center gap-1.5">
            <BarChart3 className="h-4 w-4 flex-shrink-0 text-blue-500 dark:text-blue-400" />
            <span className="font-semibold text-foreground">{(count ?? 0).toLocaleString()}</span>
            <span className="text-muted-foreground">rows</span>
          </span>
        )}
        {hasRows && seconds !== null && (
          <span className="flex items-center gap-1.5">
            <Clock className="h-4 w-4 flex-shrink-0 text-blue-500 dark:text-blue-400" />
            <span className="font-semibold text-foreground">{seconds.toFixed(2)}</span>
            <span className="text-muted-foreground">s</span>
          </span>
        )}
        {hasContext && (
          <span
            className="flex items-center text-violet-500 dark:text-violet-400"
            title="Context notes attached — open the concept's context tab to view"
          >
            <NotebookText className="h-4 w-4 flex-shrink-0" />
          </span>
        )}
      </div>
    </div>
  );
}

interface GroupBadgeProps {
  group?: string;
  accent: string | null;
  softBg: string | null;
  visible: boolean;
}

/**
 * Inline group-name pill shown in the card header when a concept belongs to a
 * group and the card is expanded. Collapsed cards rely on the left-edge colour
 * accent alone, so this stays hidden then.
 */
export function GroupBadge({ group, accent, softBg, visible }: GroupBadgeProps) {
  if (!accent || !visible) return null;
  const style: React.CSSProperties = { backgroundColor: softBg ?? undefined, color: accent };
  return (
    <span
      className="flex-shrink-0 max-w-[110px] truncate rounded px-1.5 py-0.5 text-xs font-medium"
      style={style}
      title={`Group: ${group}`}
    >
      {group}
    </span>
  );
}

/**
 * Display labels for each concept definition language. Note the backend uses
 * "logic" to represent Vadalog — there is no literal "vadalog" value. The pill
 * is deliberately neutral (muted tokens) so it reads as metadata, not status.
 */
const LANGUAGE_LABELS: Record<ConceptLanguage, string> = {
  logic: "Vadalog",
  sql: "SQL",
  cypher: "Cypher",
  python: "Python",
  context: "Context",
  llm: "LLM",
};

interface LanguageBadgeProps {
  conceptType?: ConceptLanguage;
}

/**
 * Inline pill in the card header naming the language the concept is defined in
 * (Vadalog / SQL / Cypher / Python). Mirrors how datasource cards surface their
 * source type, giving an at-a-glance read of the concept's definition kind.
 */
export function LanguageBadge({ conceptType }: LanguageBadgeProps) {
  if (!conceptType) return null;
  const label = LANGUAGE_LABELS[conceptType];
  if (!label) return null;
  return (
    <span
      className="flex-shrink-0 rounded bg-muted px-1.5 py-0.5 text-xs font-medium text-muted-foreground"
      title={`Defined in ${label}`}
    >
      {label}
    </span>
  );
}
