import { Play } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Label } from "@/shared/components/ui/label";
import { type GroupRunState, isGroupBusy } from "../../../runtime/useRunGroups";

interface RunButtonWidgetProps {
  label: string;
  state: GroupRunState;
  error?: string;
  onRun: () => void;
  /** Cancel a run parked waiting for the engine. */
  onCancel?: () => void;
  /** No run group bound yet — the button shows but cannot fire. */
  unbound?: boolean;
}

function buttonText(state: GroupRunState, label: string): string {
  if (state === "waiting") return "Waiting for engine…";
  if (isGroupBusy(state)) return "Running…";
  return label;
}

/**
 * A run group's trigger placed in the layout (ADR D4). Mirrors the anatomy of
 * a labeled input (invisible label spacer + h-9 control) so a button sharing
 * a grid row with input_ref widgets aligns with their controls, not their
 * labels.
 */
export function RunButtonWidget({
  label,
  state,
  error,
  onRun,
  onCancel,
  unbound,
}: RunButtonWidgetProps) {
  const busy = isGroupBusy(state);
  const isWaiting = state === "waiting";
  return (
    <div className="flex flex-col gap-1.5">
      <Label aria-hidden="true" className="text-[11px] font-medium invisible select-none">
        &nbsp;
      </Label>
      <div className="flex items-center gap-2">
        <Button
          onClick={onRun}
          disabled={busy || unbound}
          title={unbound ? "Assign a run group to make this button work" : undefined}
          className="gap-2 h-9 self-start px-6"
        >
          {busy ? <PrometheuxSpinner size={14} /> : <Play className="h-3.5 w-3.5" />}
          {buttonText(state, label)}
        </Button>
        {isWaiting && onCancel ? (
          <Button variant="ghost" size="sm" onClick={onCancel} className="h-9">
            Cancel
          </Button>
        ) : null}
      </div>
      {isWaiting ? (
        <p className="text-[11px] text-amber-700 dark:text-amber-400">
          Engine busy — this will run automatically when it frees up.
        </p>
      ) : null}
      {state === "error" && error ? <p className="text-[11px] text-destructive">{error}</p> : null}
    </div>
  );
}
