import { useState } from "react";
import { toast } from "sonner";
import { extractStoragePath } from "@/features/settings/hooks/useAvatarSrc";
import { supabase } from "@/shared/integrations/supabase/client";

export interface AvatarUploadResult {
  avatarPath: string;
  filePath: string;
}

export const useAvatarManagement = () => {
  const [isUploading, setIsUploading] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const uploadAvatar = async (file: File, userId: string): Promise<AvatarUploadResult | null> => {
    setIsUploading(true);
    try {
      const validTypes = ["image/jpeg", "image/jpg", "image/png", "image/gif", "image/webp"];
      if (!validTypes.includes(file.type)) {
        toast.error("Invalid file type. Please upload a JPG, PNG, GIF, or WebP image.");
        return null;
      }

      const maxSize = 5 * 1024 * 1024;
      if (file.size > maxSize) {
        toast.error("File size too large. Maximum size is 5MB.");
        return null;
      }

      // The userId folder prefix is required by the avatars bucket RLS policy:
      // (storage.foldername(name))[1] = auth.uid()::text
      const fileExt = file.name.split(".").pop();
      const randomNum = Math.random().toString(36).substring(2, 15);
      const filePath = `${userId}/${randomNum}.${fileExt}`;

      const { error: uploadError } = await supabase.storage.from("avatars").upload(filePath, file, {
        cacheControl: "3600",
        upsert: false,
      });

      if (uploadError) throw uploadError;

      toast.success("Avatar uploaded successfully");

      // Store the storage path, not a URL. The bucket is private; consumers
      // resolve the path to a signed URL via useAvatarSrc at render time.
      return {
        avatarPath: filePath,
        filePath,
      };
    } catch (error: any) {
      console.error("Error uploading avatar:", error);
      toast.error(`Failed to upload avatar: ${error.message || "Unknown error"}`);
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  /**
   * Delete an avatar from Supabase storage
   * @param filePath - The file path in storage (extracted from avatar_url)
   */
  const deleteAvatar = async (filePath: string): Promise<boolean> => {
    setIsDeleting(true);
    try {
      // Extract just the filename from the path if it's a full URL
      let fileName = filePath;
      if (filePath.includes("/avatars/")) {
        fileName = filePath.split("/avatars/").pop() || filePath;
      }

      const { error } = await supabase.storage.from("avatars").remove([fileName]);

      if (error) {
        throw error;
      }

      toast.success("Avatar deleted successfully");
      return true;
    } catch (error: any) {
      console.error("Error deleting avatar:", error);
      toast.error(`Failed to delete avatar: ${error.message || "Unknown error"}`);
      return false;
    } finally {
      setIsDeleting(false);
    }
  };

  /**
   * Update the avatar_url in the profiles table
   * @param userId - The user ID
   * @param avatarUrl - The new avatar URL (or null to remove)
   */
  const updateProfileAvatar = async (
    userId: string,
    avatarUrl: string | null,
  ): Promise<boolean> => {
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ avatar_url: avatarUrl })
        .eq("id", userId);

      if (error) {
        throw error;
      }

      return true;
    } catch (error: any) {
      console.error("Error updating profile avatar:", error);
      toast.error(`Failed to update profile: ${error.message || "Unknown error"}`);
      return false;
    }
  };

  /**
   * Complete avatar change process: upload new, delete old, update profile
   * @param file - The new avatar file
   * @param userId - The user ID
   * @param currentAvatarUrl - The current avatar URL (to delete old one)
   */
  const changeAvatar = async (
    file: File,
    userId: string,
    currentAvatarUrl?: string | null,
  ): Promise<string | null> => {
    try {
      const uploadResult = await uploadAvatar(file, userId);
      if (!uploadResult) return null;

      const updateSuccess = await updateProfileAvatar(userId, uploadResult.avatarPath);
      if (!updateSuccess) {
        await deleteAvatar(uploadResult.filePath);
        return null;
      }

      // Delete old avatar if it lived in our bucket (skip external OAuth URLs)
      if (currentAvatarUrl) {
        const oldPath = extractStoragePath(currentAvatarUrl);
        if (oldPath) await deleteAvatar(oldPath);
      }

      return uploadResult.avatarPath;
    } catch (error: any) {
      console.error("Error changing avatar:", error);
      toast.error("Failed to change avatar");
      return null;
    }
  };

  /**
   * Remove avatar completely: delete from storage and update profile
   * @param userId - The user ID
   * @param currentAvatarUrl - The current avatar URL
   */
  const removeAvatar = async (userId: string, currentAvatarUrl: string): Promise<boolean> => {
    try {
      // Only attempt storage delete if the avatar lives in our bucket
      const path = extractStoragePath(currentAvatarUrl);
      if (path) {
        const deleteSuccess = await deleteAvatar(path);
        if (!deleteSuccess) return false;
      }

      const updateSuccess = await updateProfileAvatar(userId, null);
      return updateSuccess;
    } catch (error: any) {
      console.error("Error removing avatar:", error);
      return false;
    }
  };

  return {
    uploadAvatar,
    deleteAvatar,
    updateProfileAvatar,
    changeAvatar,
    removeAvatar,
    isUploading,
    isDeleting,
  };
};
