import { BookMarked, Database, NotebookText } from "lucide-react";
import type React from "react";
import { cn } from "@/shared/lib/utils";

export type LibraryPanelId = "concepts" | "data" | "context";

interface LibraryRailItem {
  id: LibraryPanelId;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
}

const RAIL_ITEMS: LibraryRailItem[] = [
  { id: "concepts", label: "Concepts", icon: BookMarked },
  { id: "data", label: "Data", icon: Database },
  { id: "context", label: "Context", icon: NotebookText },
];

interface LibraryRailProps {
  activePanel: LibraryPanelId | null;
  onPanelChange: (panel: LibraryPanelId | null) => void;
}

const LibraryRail: React.FC<LibraryRailProps> = ({ activePanel, onPanelChange }) => {
  const handleClick = (id: LibraryPanelId) => {
    onPanelChange(activePanel === id ? null : id);
  };

  return (
    <div className="w-8 flex-shrink-0 border-l border-border bg-card flex flex-col">
      {RAIL_ITEMS.map(({ id, label, icon: Icon }) => {
        const isActive = activePanel === id;
        return (
          <button
            key={id}
            type="button"
            onClick={() => handleClick(id)}
            title={label}
            aria-pressed={isActive}
            className={cn(
              "flex flex-col items-center gap-2 py-3 px-1 transition-colors border-l-2",
              isActive
                ? "bg-accent text-accent-foreground border-primary"
                : "text-muted-foreground hover:bg-accent hover:text-accent-foreground border-transparent",
            )}
          >
            <Icon className="h-4 w-4 flex-shrink-0" />
            <span
              className="text-[10px] font-medium uppercase tracking-wider"
              style={{ writingMode: "vertical-rl", transform: "rotate(180deg)" }}
            >
              {label}
            </span>
          </button>
        );
      })}
    </div>
  );
};

export default LibraryRail;
