import type { Node as FlowNode } from "@xyflow/react";
import { useCallback } from "react";

import type { ConceptCardCustomData } from "@/features/ontology-schema/types";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";

interface UseOpenContextNoteParams {
  nodes: FlowNode<ConceptCardCustomData>[];
  setBottomTab: (tab: "context") => void;
  openNodePanel: (node: FlowNode) => void;
  setPanelState: (state: null) => void;
  setDatasourcePanelInfo: (info: null) => void;
  setNotePanelId: (noteId: string | null) => void;
}

/**
 * Context rail → dock: an attached note opens inside its concept's
 * context tab (same flow as clicking the concept, with the note
 * pre-opened via pendingContextNoteId); a standalone note opens as a
 * bare note editor in the dock.
 */
export function useOpenContextNote({
  nodes,
  setBottomTab,
  openNodePanel,
  setPanelState,
  setDatasourcePanelInfo,
  setNotePanelId,
}: UseOpenContextNoteParams) {
  return useCallback(
    (noteId: string, conceptName?: string) => {
      const conceptNode = conceptName
        ? nodes.find((n) => n.data.nodeType !== "datasource" && n.data.label === conceptName)
        : undefined;
      if (conceptNode) {
        useEditorActionsStore.getState().register({ pendingContextNoteId: noteId });
        setBottomTab("context");
        setNotePanelId(null);
        openNodePanel(conceptNode);
        return;
      }
      setPanelState(null);
      setDatasourcePanelInfo(null);
      setNotePanelId(noteId);
    },
    [nodes, setBottomTab, openNodePanel, setPanelState, setDatasourcePanelInfo, setNotePanelId],
  );
}
