import { markdown, markdownLanguage } from "@codemirror/lang-markdown";
import type { Extension } from "@codemirror/state";
import { EditorView, keymap } from "@codemirror/view";
import CodeMirror from "@uiw/react-codemirror";
import { useMemo, useRef } from "react";

import { useThemeStore } from "@/shared/store/themeStore";

import { type WikilinkCandidate, wikilinkCompletion } from "../editor/wikilinkCompletion";

interface NoteMarkdownEditorProps {
  value: string;
  onChange: (value: string) => void;
  /** Titles offered by the `[[` autocomplete. */
  getLinkCandidates: () => WikilinkCandidate[];
  /** Invoked on Mod-S. */
  onSave: () => void;
  autoFocus?: boolean;
}

const editorChrome = EditorView.theme({
  "&": { backgroundColor: "transparent", fontSize: "15px", height: "100%" },
  ".cm-content": { padding: "20px 24px", lineHeight: "1.7" },
  ".cm-scroller": { fontFamily: "inherit" },
  "&.cm-focused": { outline: "none" },
});

export function NoteMarkdownEditor({
  value,
  onChange,
  getLinkCandidates,
  onSave,
  autoFocus = false,
}: NoteMarkdownEditorProps) {
  const theme = useThemeStore((state) => state.theme);

  // Refs keep the extension array stable across renders — rebuilding
  // CodeMirror extensions on every keystroke resets editor state.
  const candidatesRef = useRef(getLinkCandidates);
  candidatesRef.current = getLinkCandidates;
  const saveRef = useRef(onSave);
  saveRef.current = onSave;

  const extensions = useMemo<Extension[]>(
    () => [
      markdown({ base: markdownLanguage }),
      EditorView.lineWrapping,
      wikilinkCompletion(() => candidatesRef.current()),
      keymap.of([
        {
          key: "Mod-s",
          run: () => {
            saveRef.current();
            return true;
          },
        },
      ]),
      editorChrome,
    ],
    [],
  );

  return (
    <CodeMirror
      value={value}
      onChange={onChange}
      extensions={extensions}
      theme={theme}
      height="100%"
      autoFocus={autoFocus}
      basicSetup={{
        lineNumbers: false,
        foldGutter: false,
        highlightActiveLine: false,
        highlightActiveLineGutter: false,
        autocompletion: false,
      }}
      className="h-full"
    />
  );
}
