import { ShieldCheck, ShieldOff } from "lucide-react";
import { useState } from "react";
import { useMfa } from "@/features/auth/hooks/useMfa";
import SettingsSection from "@/features/settings/components/SettingsSection";
import { MfaEnrollmentWizard } from "@/features/settings/components/users/profile/security/MfaEnrollmentWizard";
import { useMfaEnrollment } from "@/features/settings/components/users/profile/security/useMfaEnrollment";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";
import { Button } from "@/shared/components/ui/button";

const MfaSettings = () => {
  const mfa = useMfa();
  const { verifiedFactor, isLoading, error } = mfa;
  const enrollment = useMfaEnrollment(mfa);
  const [isDisableDialogOpen, setIsDisableDialogOpen] = useState(false);

  const handleStart = () => {
    enrollment.startEnrollment();
  };

  const handleConfirmDisable = async () => {
    await enrollment.disableMfa();
    setIsDisableDialogOpen(false);
  };

  const isEnrollmentActive = enrollment.step !== "idle";

  return (
    <SettingsSection
      title="Two-factor authentication"
      description="Protect your account with a time-based one-time password (TOTP) from your authenticator app."
    >
      {isLoading && <p className="text-sm text-muted-foreground">Loading MFA status…</p>}
      {error && <p className="text-sm text-destructive">{error}</p>}

      {!isLoading && !isEnrollmentActive && (
        <MfaStatusRow
          isEnabled={Boolean(verifiedFactor)}
          factorName={verifiedFactor?.friendly_name}
          onEnable={handleStart}
          onRequestDisable={() => setIsDisableDialogOpen(true)}
        />
      )}

      {isEnrollmentActive && <MfaEnrollmentWizard enrollment={enrollment} />}

      <AlertDialog open={isDisableDialogOpen} onOpenChange={setIsDisableDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Disable two-factor authentication?</AlertDialogTitle>
            <AlertDialogDescription>
              Your recovery codes will be invalidated and your account will no longer require a
              second factor at sign-in. You can re-enable it at any time.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={enrollment.isBusy}>Keep it on</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmDisable}
              disabled={enrollment.isBusy}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {enrollment.isBusy ? "Disabling…" : "Disable MFA"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </SettingsSection>
  );
};

interface MfaStatusRowProps {
  isEnabled: boolean;
  factorName?: string;
  onEnable: () => void;
  onRequestDisable: () => void;
}

const MfaStatusRow = ({ isEnabled, factorName, onEnable, onRequestDisable }: MfaStatusRowProps) => {
  if (isEnabled) {
    return (
      <div className="flex items-center justify-between gap-4 rounded-lg border border-border bg-muted/40 p-4">
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-full bg-primary/10">
            <ShieldCheck className="h-5 w-5 text-primary" />
          </div>
          <div>
            <p className="text-sm font-medium">MFA is enabled</p>
            <p className="text-xs text-muted-foreground">
              {factorName ? `Factor: ${factorName}` : "Authenticator app configured"}
            </p>
          </div>
        </div>
        <Button variant="outline" onClick={onRequestDisable}>
          Disable
        </Button>
      </div>
    );
  }

  return (
    <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-4">
      <div className="flex items-center gap-3">
        <div className="p-2 rounded-full bg-muted">
          <ShieldOff className="h-5 w-5 text-muted-foreground" />
        </div>
        <div>
          <p className="text-sm font-medium">MFA is not enabled</p>
          <p className="text-xs text-muted-foreground">
            Add a second step to sign-in using an authenticator app.
          </p>
        </div>
      </div>
      <Button onClick={onEnable}>Enable MFA</Button>
    </div>
  );
};

export default MfaSettings;
