import { Plus } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import type { AppPageDef, AppSectionDef, AppWidgetDef } from "../../schema/appDefinition.types";
import { isLegacyWidget } from "../../schema/appDefinition.types";
import { selectionEquals } from "../../store/appEditor.types";
import * as mutations from "../../store/appEditorMutations";
import { useAppEditorStore } from "../../store/appEditorStore";
import { removeSelected } from "../../store/selectionMutations";
import { defaultWidgetFor, WIDGET_TYPE_OPTIONS } from "../../store/widgetDefaults";
import { EditorOutlineFormFields } from "./EditorOutlineFormFields";
import { OutlineRow } from "./OutlineRow";

/**
 * Structure tab of the left pane: pages → sections → widgets. Clicking any
 * row selects it (same selection the preview and inspector share); hover
 * actions reorder and delete; the + menus add nodes with sensible defaults.
 */
export function EditorOutline() {
  const draft = useAppEditorStore((state) => state.draft);
  if (!draft) return null;

  return (
    <div className="flex flex-col gap-3 p-2">
      {draft.pages.map((page) => (
        <PageBlock key={page.id} page={page} />
      ))}
      <AddRow label="Add page" onAdd={() => addPageToDraft()} />
    </div>
  );
}

function addPageToDraft() {
  const { draft, updateDraft, select } = useAppEditorStore.getState();
  const ontologyId = draft?.pages[0]?.project.id ?? draft?.ontologyId ?? "";
  updateDraft((current) => mutations.addPage(current, ontologyId));
  const added = useAppEditorStore.getState().draft?.pages.at(-1);
  if (added) select({ kind: "page", pageId: added.id });
}

interface PageBlockProps {
  page: AppPageDef;
}

function PageBlock({ page }: PageBlockProps) {
  const selection = useAppEditorStore((state) => state.selection);
  const select = useAppEditorStore((state) => state.select);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  return (
    <div className="flex flex-col gap-0.5">
      <OutlineRow
        label={page.label || page.id}
        hint="page"
        depth={0}
        isSelected={selectionEquals(selection, { kind: "page", pageId: page.id })}
        onSelect={() => select({ kind: "page", pageId: page.id })}
        onMoveUp={() => updateDraft((draft) => mutations.movePage(draft, page.id, -1))}
        onMoveDown={() => updateDraft((draft) => mutations.movePage(draft, page.id, 1))}
        onDelete={() => {
          select(null);
          updateDraft((draft) => removeSelected(draft, { kind: "page", pageId: page.id }));
        }}
      />
      {page.sections.map((section) => (
        <SectionBlock key={section.id} page={page} section={section} />
      ))}
      <AddRow
        label="Add section"
        depth={1}
        onAdd={() => updateDraft((draft) => mutations.addSection(draft, page.id))}
      />
    </div>
  );
}

interface SectionBlockProps {
  page: AppPageDef;
  section: AppSectionDef;
}

function SectionBlock({ page, section }: SectionBlockProps) {
  const selection = useAppEditorStore((state) => state.selection);
  const select = useAppEditorStore((state) => state.select);
  const updateDraft = useAppEditorStore((state) => state.updateDraft);

  const widgets = section.widgets.filter(
    (widget): widget is AppWidgetDef => !isLegacyWidget(widget),
  );
  const sectionSelection = { kind: "section", pageId: page.id, sectionId: section.id } as const;

  const handleAddWidget = (type: AppWidgetDef["type"]) => {
    // Forms are one-step: create the backing form input and bind it, so the
    // fields tree (with "Add field") appears immediately under the widget.
    if (type === "form_ref") {
      updateDraft((draft) => mutations.addFormWidget(draft, page.id, section.id));
      return;
    }
    updateDraft((draft) => mutations.addWidget(draft, page.id, section.id, defaultWidgetFor(type)));
  };

  return (
    <div className="flex flex-col gap-0.5">
      <OutlineRow
        label={section.title || section.id}
        hint={section.layout ?? "grid"}
        depth={1}
        isSelected={selectionEquals(selection, sectionSelection)}
        onSelect={() => select(sectionSelection)}
        onMoveUp={() =>
          updateDraft((draft) => mutations.moveSection(draft, page.id, section.id, -1))
        }
        onMoveDown={() =>
          updateDraft((draft) => mutations.moveSection(draft, page.id, section.id, 1))
        }
        onDelete={() => {
          select(null);
          updateDraft((draft) => removeSelected(draft, sectionSelection));
        }}
      />
      {widgets.map((widget) => {
        // Forms expand in place: their fields are schema nodes like widgets.
        const form =
          widget.type === "form_ref" || widget.type === "input_ref"
            ? page.inputs.find((input) => input.id === widget.inputId && input.type === "form")
            : undefined;
        return (
          <div key={widget.id} className="flex flex-col gap-0.5">
            <OutlineRow
              label={widget.label || widget.id}
              hint={widget.type}
              depth={2}
              isSelected={selectionEquals(selection, {
                kind: "widget",
                pageId: page.id,
                sectionId: section.id,
                widgetId: widget.id,
              })}
              onSelect={() =>
                select({
                  kind: "widget",
                  pageId: page.id,
                  sectionId: section.id,
                  widgetId: widget.id,
                })
              }
              onMoveUp={() =>
                updateDraft((draft) =>
                  mutations.moveWidget(draft, page.id, section.id, widget.id, -1),
                )
              }
              onMoveDown={() =>
                updateDraft((draft) =>
                  mutations.moveWidget(draft, page.id, section.id, widget.id, 1),
                )
              }
              onDelete={() => {
                select(null);
                updateDraft((draft) =>
                  removeSelected(draft, {
                    kind: "widget",
                    pageId: page.id,
                    sectionId: section.id,
                    widgetId: widget.id,
                  }),
                );
              }}
            />
            {form && <EditorOutlineFormFields pageId={page.id} form={form} />}
          </div>
        );
      })}
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button
            type="button"
            className="flex items-center gap-1 pl-8 py-0.5 text-[10px] text-muted-foreground hover:text-foreground"
          >
            <Plus className="h-2.5 w-2.5" />
            Add widget
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" className="max-h-72 overflow-y-auto">
          {WIDGET_TYPE_OPTIONS.map((option) => (
            <DropdownMenuItem
              key={option.type}
              className="text-xs"
              onSelect={() => handleAddWidget(option.type)}
            >
              {option.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

interface AddRowProps {
  label: string;
  depth?: 0 | 1;
  onAdd: () => void;
}

function AddRow({ label, depth = 0, onAdd }: AddRowProps) {
  return (
    <button
      type="button"
      onClick={onAdd}
      className={`flex items-center gap-1 py-0.5 text-[10px] text-muted-foreground hover:text-foreground ${depth === 1 ? "pl-5" : "pl-2"}`}
    >
      <Plus className="h-2.5 w-2.5" />
      {label}
    </button>
  );
}
