import { useMemo } from "react";

import type { ContextEdge } from "../types";
import { parseConceptNodeId } from "../types";
import { useAllContextEdges } from "./useContextEdges";

function conceptEndpointOf(edge: ContextEdge): string | null {
  if (edge.src_type === "concept") return edge.src_id;
  if (edge.dst_type === "concept") return edge.dst_id;
  return null;
}

/**
 * Concept (predicate) names of a project that have context notes attached
 * via context_edges — drives the "has attached context" indicator on the
 * lineage cards. Edge mutations invalidate the underlying query.
 */
export function useAnnotatedConcepts(ontologyId: string | null): Set<string> {
  const { data: allEdges } = useAllContextEdges({ enabled: Boolean(ontologyId) });

  return useMemo(() => {
    const names = new Set<string>();
    if (!ontologyId || !allEdges) return names;
    for (const edge of allEdges) {
      const conceptId = conceptEndpointOf(edge);
      if (!conceptId) continue;
      const ref = parseConceptNodeId(conceptId);
      if (ref?.ontologyId === ontologyId) names.add(ref.conceptName);
    }
    return names;
  }, [allEdges, ontologyId]);
}
