import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { graphExplorerClient } from "../api/GraphExplorerClient";
import type { GraphViewModel } from "../types";

interface UseGraphModelReturn {
  model: GraphViewModel | null | undefined;
  isLoading: boolean;
  error: Error | null;
  isSaving: boolean;
  save: (model: GraphViewModel) => void;
}

export function useGraphModel(ontologyId: string, scope: string): UseGraphModelReturn {
  const queryClient = useQueryClient();
  const modelKey = ["graph-explorer-model", ontologyId, scope];

  const modelQuery = useQuery({
    queryKey: modelKey,
    queryFn: () => graphExplorerClient.getModel(ontologyId, scope),
    enabled: Boolean(ontologyId),
  });

  const saveMutation = useMutation({
    mutationFn: (model: GraphViewModel) => graphExplorerClient.saveModel(ontologyId, scope, model),
    onSuccess: (saved) => {
      queryClient.setQueryData(modelKey, saved);
    },
  });

  return {
    model: modelQuery.data,
    isLoading: modelQuery.isLoading,
    error: modelQuery.error,
    isSaving: saveMutation.isPending,
    save: (model: GraphViewModel) => saveMutation.mutate(model),
  };
}
