import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import type { LlmConnectionSettings } from "../../api/configService";
import { useLlmModels } from "../../hooks/useLlmModels";
import { discoveryFieldsOf, LLM_PROVIDERS } from "../../utils/llmConnection.utils";

/** Radix Select has no empty value, so "no model pinned" needs a sentinel. */
const MODEL_PROVIDER_DEFAULT = "__provider_default__";

interface LlmConnectionFieldsProps {
  settings: LlmConnectionSettings;
  /**
   * Names of credentials already stored for this connection. Their inputs start
   * blank rather than prefilled, so an untouched blank means "keep what is
   * stored"; the backend treats an omitted credential as unchanged.
   */
  storedSecrets?: readonly string[];
  /**
   * Name of the connection being edited, when it is already saved. Its stored
   * credentials are what its models should be listed against, and they are not
   * here to send — the server resolves the name instead.
   */
  connectionName?: string;
  /** Prefix for input ids, so two of these can coexist on one page. */
  idPrefix?: string;
  onChange: (settings: LlmConnectionSettings) => void;
}

function secretPlaceholder(field: string, storedSecrets: readonly string[]): string {
  if (storedSecrets.includes(field)) return "stored — leave blank to keep";
  return "managed key when empty";
}

/**
 * The provider-shaped half of a connection form: provider, model, credentials
 * and whatever endpoints that provider needs. Shared by the Settings form and
 * the llm cell, so one place knows what a provider requires.
 */
export function LlmConnectionFields({
  settings,
  storedSecrets = [],
  connectionName,
  idPrefix = "llm-conn",
  onChange,
}: LlmConnectionFieldsProps) {
  const provider = settings.llm_provider ?? "openai";

  const { data: discoveredModels } = useLlmModels({
    provider,
    connection: connectionName,
    credentials: discoveryFieldsOf(settings),
  });

  // A saved model this account can no longer discover still has to be shown, or
  // opening the form would silently repoint the connection at something else.
  const known = discoveredModels ?? [];
  const model = settings.llm_version ?? "";
  const modelOptions = model && !known.includes(model) ? [model, ...known] : known;

  const setField =
    (field: keyof LlmConnectionSettings) => (e: React.ChangeEvent<HTMLInputElement>) => {
      // Empty stays as "" rather than undefined: for a credential that is the
      // difference between clearing it and leaving the stored one in place.
      onChange({ ...settings, [field]: e.target.value });
    };

  const handleProviderChange = (value: string) => {
    // Provider-specific fields from the old provider make no sense on the new
    // one; the credential carries over since it is usually the same account.
    onChange({ llm_provider: value, llm_api_key: settings.llm_api_key });
  };

  const handleModelSelect = (value: string) => {
    onChange({ ...settings, llm_version: value === MODEL_PROVIDER_DEFAULT ? "" : value });
  };

  return (
    <div className="grid grid-cols-2 gap-3">
      <div className="flex flex-col gap-1">
        <label htmlFor={`${idPrefix}-provider`} className="text-xs text-muted-foreground">
          Provider
        </label>
        <Select value={provider} onValueChange={handleProviderChange}>
          <SelectTrigger id={`${idPrefix}-provider`} className="h-8 text-sm border-border">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {LLM_PROVIDERS.map((p) => (
              <SelectItem key={p.value} value={p.value} className="text-sm">
                {p.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="flex flex-col gap-1">
        <label htmlFor={`${idPrefix}-model`} className="text-xs text-muted-foreground">
          Model
        </label>
        {modelOptions.length > 0 ? (
          <Select value={model || MODEL_PROVIDER_DEFAULT} onValueChange={handleModelSelect}>
            <SelectTrigger id={`${idPrefix}-model`} className="h-8 text-sm border-border">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={MODEL_PROVIDER_DEFAULT} className="text-sm">
                Provider default
              </SelectItem>
              {modelOptions.map((option) => (
                <SelectItem key={option} value={option} className="text-sm">
                  {option}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        ) : (
          // Discovery came back empty: unreachable, or a provider that needs
          // credentials we do not have yet. Typing a name must still work.
          <Input
            id={`${idPrefix}-model`}
            value={model}
            onChange={setField("llm_version")}
            placeholder="provider default"
            className="h-8 text-sm"
          />
        )}
      </div>
      <div className="flex flex-col gap-1">
        <label htmlFor={`${idPrefix}-key`} className="text-xs text-muted-foreground">
          API key
        </label>
        <Input
          id={`${idPrefix}-key`}
          type="password"
          value={settings.llm_api_key ?? ""}
          onChange={setField("llm_api_key")}
          placeholder={secretPlaceholder("llm_api_key", storedSecrets)}
          className="h-8 text-sm"
        />
      </div>
      {provider === "azure" && (
        <>
          <div className="flex flex-col gap-1">
            <label htmlFor={`${idPrefix}-az-endpoint`} className="text-xs text-muted-foreground">
              Azure endpoint
            </label>
            <Input
              id={`${idPrefix}-az-endpoint`}
              value={settings.azure_llm_endpoint ?? ""}
              onChange={setField("azure_llm_endpoint")}
              className="h-8 text-sm"
            />
          </div>
          <div className="flex flex-col gap-1">
            <label htmlFor={`${idPrefix}-az-version`} className="text-xs text-muted-foreground">
              Azure API version
            </label>
            <Input
              id={`${idPrefix}-az-version`}
              value={settings.azure_llm_api_version ?? ""}
              onChange={setField("azure_llm_api_version")}
              className="h-8 text-sm"
            />
          </div>
        </>
      )}
      {provider === "databricks" && (
        <>
          <div className="flex flex-col gap-1">
            <label htmlFor={`${idPrefix}-dbx-url`} className="text-xs text-muted-foreground">
              Workspace URL
            </label>
            <Input
              id={`${idPrefix}-dbx-url`}
              value={settings.databricks_workspace_url ?? ""}
              onChange={setField("databricks_workspace_url")}
              className="h-8 text-sm"
            />
          </div>
          <div className="flex flex-col gap-1">
            <label htmlFor={`${idPrefix}-dbx-id`} className="text-xs text-muted-foreground">
              Client ID
            </label>
            <Input
              id={`${idPrefix}-dbx-id`}
              value={settings.databricks_client_id ?? ""}
              onChange={setField("databricks_client_id")}
              className="h-8 text-sm"
            />
          </div>
          <div className="flex flex-col gap-1">
            <label htmlFor={`${idPrefix}-dbx-secret`} className="text-xs text-muted-foreground">
              Client secret
            </label>
            <Input
              id={`${idPrefix}-dbx-secret`}
              type="password"
              value={settings.databricks_client_secret ?? ""}
              onChange={setField("databricks_client_secret")}
              placeholder={secretPlaceholder("databricks_client_secret", storedSecrets)}
              className="h-8 text-sm"
            />
          </div>
        </>
      )}
      {provider === "snowflake_cortex" && (
        <div className="flex flex-col gap-1">
          <label htmlFor={`${idPrefix}-sf-url`} className="text-xs text-muted-foreground">
            Account URL
          </label>
          <Input
            id={`${idPrefix}-sf-url`}
            value={settings.snowflake_account_url ?? ""}
            onChange={setField("snowflake_account_url")}
            className="h-8 text-sm"
          />
        </div>
      )}
    </div>
  );
}
