import { Check, ChevronDown, ChevronRight, X } from "lucide-react";
import { useState } from "react";

import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

import type { ToolProgressData, ToolStatus } from "../store";

interface ToolMessageProps {
  toolName: string;
  toolDetail?: string;
  status: ToolStatus;
  progress?: ToolProgressData;
  toolInput?: Record<string, unknown>;
  toolResult?: Record<string, unknown>;
}

function formatProgressLabel(progress: ToolProgressData): string | null {
  // A tool that knows how to describe its own progress says so; ingestion,
  // which counts chunks, does not.
  if (progress.label) return progress.label;
  if (progress.current === undefined || progress.total === undefined) return null;
  return `chunk ${progress.current} of ${progress.total}`;
}

function formatPayload(payload: Record<string, unknown>): string {
  try {
    return JSON.stringify(payload, null, 2);
  } catch {
    return String(payload);
  }
}

interface PayloadSectionProps {
  label: string;
  payload: Record<string, unknown>;
}

function PayloadSection({ label, payload }: PayloadSectionProps) {
  return (
    <div className="flex flex-col gap-1">
      <span className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
        {label}
      </span>
      <pre className="max-h-64 overflow-auto rounded-md border border-border bg-muted/40 p-2.5 font-mono text-[11px] leading-relaxed text-foreground">
        {formatPayload(payload)}
      </pre>
    </div>
  );
}

// A single tool-execution card, styled to match ContextLoadedChip so the two
// read as one family in the transcript. Status is conveyed by the spinner
// (running) / green check (done) / red X (error) — no decorative wrench. When the
// call carries a request/response payload the whole card becomes an expander.
export function ToolMessage({
  toolName,
  toolDetail,
  status,
  progress,
  toolInput,
  toolResult,
}: ToolMessageProps) {
  const [expanded, setExpanded] = useState(false);

  const label = toolName.replace(/_/g, " ");
  const progressLabel = progress ? formatProgressLabel(progress) : null;
  // Show the chunk counter for both running and done states. Fast tools
  // (single-chunk ingest) would otherwise flash the counter for ~100ms
  // and leave the user no proof of what got persisted.
  const showProgress = progressLabel && status !== "error";
  const hasInput = !!toolInput && Object.keys(toolInput).length > 0;
  const hasResult = !!toolResult && Object.keys(toolResult).length > 0;
  const isExpandable = hasInput || hasResult;

  const toggleExpanded = () => setExpanded((prev) => !prev);

  const statusIcon =
    status === "running" ? (
      <PrometheuxSpinner size={14} />
    ) : status === "done" ? (
      <Check className="h-3.5 w-3.5 shrink-0 text-green-500 dark:text-green-400" />
    ) : (
      <X className="h-3.5 w-3.5 shrink-0 text-destructive" />
    );

  const header = (
    <>
      {statusIcon}
      <span className="truncate font-medium capitalize text-foreground">{label}</span>
      {toolDetail && <span className="truncate text-muted-foreground">· {toolDetail}</span>}
      {showProgress && <span className="shrink-0 text-muted-foreground">· {progressLabel}</span>}
    </>
  );

  if (!isExpandable) {
    return (
      <div className="flex items-center gap-2 rounded-lg border border-border bg-card px-3 py-2 text-xs shadow-sm">
        {header}
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-border bg-card px-3 py-2 text-xs shadow-sm">
      <button
        type="button"
        onClick={toggleExpanded}
        className="flex w-full items-center gap-2 text-left"
        aria-expanded={expanded}
      >
        {header}
        {expanded ? (
          <ChevronDown className="ml-auto h-3.5 w-3.5 shrink-0 text-muted-foreground" />
        ) : (
          <ChevronRight className="ml-auto h-3.5 w-3.5 shrink-0 text-muted-foreground" />
        )}
      </button>
      {expanded && (
        <div className="mt-2.5 flex flex-col gap-2.5 border-t border-border pt-2.5">
          {hasInput && <PayloadSection label="Request" payload={toolInput} />}
          {hasResult && <PayloadSection label="Response" payload={toolResult} />}
        </div>
      )}
    </div>
  );
}
