import { formatDistanceToNow, parseISO } from "date-fns";

export function formatRelativeTime(iso: string): string {
  try {
    return formatDistanceToNow(parseISO(iso), { addSuffix: true });
  } catch {
    return "unknown";
  }
}

export function formatHitCount(count: number): string {
  if (count >= 1_000_000) return `${(count / 1_000_000).toFixed(1)}M`;
  if (count >= 1_000) return `${(count / 1_000).toFixed(1)}K`;
  return count.toLocaleString();
}

export function formatLocation(city: string | null, country: string | null): string {
  if (city && country) return `${city}, ${country}`;
  if (country) return country;
  if (city) return city;
  return "Unknown";
}

const TOKEN_TYPE_LABELS = {
  bootstrap: "Browser",
  api_key: "API Key",
} as const;

export function formatTokenLabel(
  tokenType: "bootstrap" | "api_key" | null,
  tokenName: string | null,
): string {
  if (!tokenType) return "—";
  const typeLabel = TOKEN_TYPE_LABELS[tokenType];
  if (tokenType === "api_key" && tokenName && tokenName !== "bootstrap") {
    return `${typeLabel}: ${tokenName}`;
  }
  return typeLabel;
}
