import { CheckCircle2, ChevronRight, Circle } from "lucide-react";
import { cn } from "@/shared/lib/utils";
import type { ResolvedStep } from "../gettingStarted.types";

interface GettingStartedStepItemProps {
  step: ResolvedStep;
  onSelect: (step: ResolvedStep) => void;
}

export function GettingStartedStepItem({ step, onSelect }: GettingStartedStepItemProps) {
  const Icon = step.completed ? CheckCircle2 : Circle;

  const handleClick = () => {
    onSelect(step);
  };

  return (
    <button
      type="button"
      onClick={handleClick}
      className="group flex w-full items-start gap-3 rounded-md p-2 text-left transition-colors hover:bg-accent"
    >
      <Icon
        className={cn(
          "mt-0.5 h-4 w-4 shrink-0",
          step.completed ? "text-primary" : "text-muted-foreground",
        )}
      />
      <span className="min-w-0 flex-1">
        <span
          className={cn(
            "block text-sm font-medium",
            step.completed ? "text-muted-foreground line-through" : "text-foreground",
          )}
        >
          {step.title}
        </span>
        <span className="mt-0.5 block text-xs text-muted-foreground">{step.description}</span>
      </span>
      {!step.completed && (
        <ChevronRight className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100" />
      )}
    </button>
  );
}
