import { format, formatDistanceToNow, parseISO } from "date-fns";

export type ExpiryPreset = "7d" | "30d" | "90d" | "never";

export type QuickExpiryPreset = "1h" | "24h" | "7d" | "30d";

export type TokenStatus = "active" | "expired" | "never_expires";

export interface ExpiryPresetOption {
  value: ExpiryPreset;
  label: string;
}

export interface QuickExpiryPresetOption {
  value: QuickExpiryPreset;
  label: string;
}

export const EXPIRY_PRESET_OPTIONS: readonly ExpiryPresetOption[] = [
  { value: "7d", label: "7 days" },
  { value: "30d", label: "30 days" },
  { value: "90d", label: "90 days" },
  { value: "never", label: "Never" },
] as const;

// Shorter-lived presets for ad-hoc "Copy API" flows — no "never" option on
// purpose, those belong in the Settings → API Keys page.
export const QUICK_EXPIRY_PRESET_OPTIONS: readonly QuickExpiryPresetOption[] = [
  { value: "1h", label: "1 hour" },
  { value: "24h", label: "24 hours" },
  { value: "7d", label: "7 days" },
  { value: "30d", label: "30 days" },
] as const;

const MINUTES_PER_HOUR = 60;
const MINUTES_PER_DAY = 24 * MINUTES_PER_HOUR;

export function presetToMinutes(preset: ExpiryPreset): number | null {
  switch (preset) {
    case "never":
      return null;
    case "7d":
      return 7 * MINUTES_PER_DAY;
    case "30d":
      return 30 * MINUTES_PER_DAY;
    case "90d":
      return 90 * MINUTES_PER_DAY;
    default: {
      const _exhaustive: never = preset;
      throw new Error(`Unhandled preset: ${_exhaustive}`);
    }
  }
}

export function quickPresetToMinutes(preset: QuickExpiryPreset): number {
  switch (preset) {
    case "1h":
      return MINUTES_PER_HOUR;
    case "24h":
      return MINUTES_PER_DAY;
    case "7d":
      return 7 * MINUTES_PER_DAY;
    case "30d":
      return 30 * MINUTES_PER_DAY;
    default: {
      const _exhaustive: never = preset;
      throw new Error(`Unhandled quick preset: ${_exhaustive}`);
    }
  }
}

const NAME_MAX_LENGTH = 120;

export function buildDefaultQuickKeyName(label: string | null | undefined): string {
  const timestamp = format(new Date(), "yyyy-MM-dd HH:mm");
  const trimmedLabel = label?.trim();
  const base = trimmedLabel ? `cURL · ${trimmedLabel} · ${timestamp}` : `cURL · ${timestamp}`;
  return base.length > NAME_MAX_LENGTH ? base.slice(0, NAME_MAX_LENGTH) : base;
}

export const API_KEY_PLACEHOLDER = "YOUR_API_KEY_HERE";

export function formatRelativeSafe(iso: string | null): string {
  if (!iso) return "—";
  try {
    return formatDistanceToNow(parseISO(iso), { addSuffix: true });
  } catch {
    return "unknown";
  }
}

function parseExpiry(expiresAt: string | null): number | null {
  if (!expiresAt) return null;
  try {
    return parseISO(expiresAt).getTime();
  } catch {
    return null;
  }
}

export function getTokenStatus(expiresAt: string | null): TokenStatus {
  if (!expiresAt) return "never_expires";
  const expiryMs = parseExpiry(expiresAt);
  if (expiryMs === null) return "never_expires";
  return expiryMs <= Date.now() ? "expired" : "active";
}

export function formatExpiry(expiresAt: string | null): string {
  if (!expiresAt) return "Never";
  return formatRelativeSafe(expiresAt);
}
