import { Info, X } from "lucide-react";
import { useState } from "react";

import type { ContextNote } from "../../types";
import { notesPreferences } from "../notesPreferences";

interface FormerlyPinnedNoticeProps {
  notes: ContextNote[];
}

/**
 * One-time notice for users who had pinned notes before pinning was
 * retired. The `pinned` column is still returned by the API solely so
 * this notice can detect them; it will be dropped in a later migration.
 */
export function FormerlyPinnedNotice({ notes }: FormerlyPinnedNoticeProps) {
  const [isDismissed, setIsDismissed] = useState(notesPreferences.isPinnedNoticeDismissed);

  const hasFormerlyPinned = notes.some((note) => note.pinned);
  if (isDismissed || !hasFormerlyPinned) return null;

  const handleDismiss = () => {
    notesPreferences.dismissPinnedNotice();
    setIsDismissed(true);
  };

  return (
    <div className="flex items-start gap-2 border-b border-border bg-blue-50 px-4 py-2 text-xs text-blue-800 dark:bg-blue-900/20 dark:text-blue-300">
      <Info className="mt-0.5 h-3.5 w-3.5 shrink-0" />
      <p className="flex-1">
        Pinning has been retired: notes now surface based on relevance and how often they're
        actually used. Some of your notes were pinned before — if one must reach the assistant on
        every request, open it and set it to <strong>Always applied</strong> to make it a Rule.
      </p>
      <button
        type="button"
        onClick={handleDismiss}
        aria-label="Dismiss notice"
        className="shrink-0 text-blue-800 hover:opacity-70 dark:text-blue-300"
      >
        <X className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}
