import { ChevronRight, FolderKanban } from "lucide-react";
import type React from "react";
import { Link } from "react-router-dom";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { guardSidebarNavClick } from "@/features/engine-status/engineStatus";
import { useOntologies } from "@/features/ontologies/hooks/useOntologies";
import { cn } from "@/shared/lib/utils";
import { useSidebarStore } from "@/shared/store/sidebarStore";
import { generateEditorUrl } from "@/shared/utils/navigationUtils";

interface SidebarOntologiesItemProps {
  collapsed: boolean;
  isActive: boolean;
  currentOntologyId: string | null;
  onNavigateToOntologies: () => void;
  onNavigateToOntology: (ontologyId: string, scope: string) => void;
}

export function SidebarOntologiesItem({
  collapsed,
  isActive,
  currentOntologyId,
  onNavigateToOntologies,
  onNavigateToOntology,
}: SidebarOntologiesItemProps) {
  const { user } = useAuth();
  const { ontologiesExpanded: expanded, setOntologiesExpanded: setExpanded } = useSidebarStore();
  const { projects } = useOntologies(["user", "organization"]);

  const handleOntologiesClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    void guardSidebarNavClick(e, onNavigateToOntologies);
  };

  if (collapsed) {
    return (
      <Link
        to="/ontologies"
        onClick={handleOntologiesClick}
        title="Ontologies"
        className={cn(
          "flex h-9 w-full items-center justify-center rounded-md text-sm font-medium text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
          isActive && "bg-primary/10 text-primary",
        )}
      >
        <FolderKanban className="h-4 w-4 shrink-0" />
      </Link>
    );
  }

  return (
    <>
      <div className="flex h-9 items-center">
        <Link
          to="/ontologies"
          onClick={handleOntologiesClick}
          className={cn(
            "flex flex-1 items-center gap-3 rounded-md px-2 h-full text-sm font-medium text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
            isActive && "bg-primary/10 text-primary",
          )}
        >
          <FolderKanban className="h-4 w-4 shrink-0" />
          <span className="truncate">Ontologies</span>
        </Link>
        <button
          type="button"
          onClick={() => setExpanded(!expanded)}
          title={expanded ? "Collapse ontologies" : "Expand ontologies"}
          className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
        >
          <ChevronRight
            className={cn("h-3.5 w-3.5 transition-transform duration-150", expanded && "rotate-90")}
          />
        </button>
      </div>

      {expanded && (
        <div className="ml-5 mr-1 mt-0.5 space-y-0.5">
          {projects.map((project) => (
            <Link
              key={project.id}
              to={generateEditorUrl(user, project.id)}
              onClick={(e) =>
                guardSidebarNavClick(e, () =>
                  onNavigateToOntology(project.id, project.scope ?? "user"),
                )
              }
              className={cn(
                "flex h-8 w-full items-center gap-2 rounded-md px-2 text-sm text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
                project.id === currentOntologyId && "bg-primary/10 text-primary",
              )}
            >
              <FolderKanban className="h-3.5 w-3.5 shrink-0 opacity-60" />
              <span className="truncate">{project.name || project.id}</span>
            </Link>
          ))}
        </div>
      )}
    </>
  );
}
