import type { Edge, Node as FlowNode } from "@xyflow/react";
import dagre from "dagre";
import type { ConceptCell } from "@/features/concept-editor/types";
import type { ConceptCardCustomData } from "@/features/ontology-schema/types";
import {
  CONCEPT_CARD_HEADER_HEIGHT,
  DATASOURCE_CARD_CHROME_WIDTH,
  getConceptCardHeight,
  getConceptCardWidth,
} from "../ConceptCardNode";
import {
  DATASOURCE_NODE_ID_PREFIX,
  DEFAULT_EDGE_MARKER,
  DEFAULT_EDGE_STYLE,
  DIMMED_EDGE_MARKER,
  DIMMED_EDGE_STYLE,
  FLOW_RUNNING_MARKER,
  FLOW_RUNNING_STYLE,
  FLOW_SUCCESS_MARKER,
  FLOW_SUCCESS_STYLE,
  HIGHLIGHTED_EDGE_MARKER,
  HIGHLIGHTED_EDGE_STYLE,
} from "./constants";
import { groupFilterKey } from "./groupColors";

const isDatasourceNodeId = (id: string): boolean => id.startsWith(DATASOURCE_NODE_ID_PREFIX);

type FlowNodeData = ConceptCardCustomData & { nodeType?: string };

const isDatasourceNode = (node: FlowNode<ConceptCardCustomData>): boolean =>
  (node.data as FlowNodeData).nodeType === "datasource";

/**
 * Hide nodes whose concept group is in `hiddenGroups`. Datasource nodes carry
 * no group, so they're kept only while at least one connected concept is still
 * visible; edges touching a hidden node are dropped. Returns the inputs
 * unchanged when nothing is hidden, so the common (no-filter) path is free.
 */
export const filterNodesByGroups = (
  nodes: FlowNode<ConceptCardCustomData>[],
  edges: Edge[],
  hiddenGroups: Set<string>,
): { nodes: FlowNode<ConceptCardCustomData>[]; edges: Edge[] } => {
  if (hiddenGroups.size === 0) return { nodes, edges };

  const visibleConceptIds = new Set(
    nodes
      .filter((n) => !isDatasourceNode(n))
      .filter((n) => !hiddenGroups.has(groupFilterKey((n.data as FlowNodeData).group)))
      .map((n) => n.id),
  );

  const visibleDatasourceIds = new Set<string>();
  for (const edge of edges) {
    if (visibleConceptIds.has(edge.source) && isDatasourceNodeId(edge.target)) {
      visibleDatasourceIds.add(edge.target);
    }
    if (visibleConceptIds.has(edge.target) && isDatasourceNodeId(edge.source)) {
      visibleDatasourceIds.add(edge.source);
    }
  }

  const visibleNodes = nodes.filter((n) =>
    isDatasourceNode(n) ? visibleDatasourceIds.has(n.id) : visibleConceptIds.has(n.id),
  );
  const visibleIds = new Set(visibleNodes.map((n) => n.id));
  const visibleEdges = edges.filter((e) => visibleIds.has(e.source) && visibleIds.has(e.target));
  return { nodes: visibleNodes, edges: visibleEdges };
};

/**
 * Resolve which concept's execution status drives an edge's color.
 *
 * Normally an edge is colored by its target concept's status. But output-bind
 * edges point from a concept *into* a datasource node (`concept → datasource`),
 * and datasource nodes never execute, so they'd stay gray. For those, fall back
 * to the source concept's status so the "writes_to" arrow turns green/orange
 * along with the concept that produced the data.
 */
export const resolveEdgeStatus = (
  edge: Edge,
  statuses: Record<string, { status: string }>,
): string | undefined => {
  const statusKey = isDatasourceNodeId(edge.target) ? edge.source : edge.target;
  return statuses[statusKey]?.status;
};

/** A freshly-added concept the user hasn't named, written, or saved yet. */
export const isBlankUnsavedCell = (cell: ConceptCell): boolean =>
  !cell.cellBackendId && !cell.code?.trim() && !cell.outputPredicate?.trim();

/** Run dagre left-to-right layout over the flow nodes/edges. */
export const layoutElements = (nodes: FlowNode<ConceptCardCustomData>[], edges: Edge[]) => {
  const g = new dagre.graphlib.Graph();
  g.setDefaultEdgeLabel(() => ({}));
  g.setGraph({
    rankdir: "LR",
    nodesep: 44,
    ranksep: 110,
    edgesep: 20,
    marginx: 24,
    marginy: 24,
    ranker: "network-simplex",
  });

  nodes.forEach((node) => {
    const nodeData = node.data as ConceptCardCustomData & {
      nodeType?: string;
      datasource_label?: string;
      hasContext?: boolean;
      isRestricted?: boolean;
    };
    if (nodeData.isRestricted) {
      // Fixed placeholder size — keeps the layout box matching the rendered
      // "Restricted concept" card and stops the hidden name's length leaking.
      const width = getConceptCardWidth("Restricted concept");
      g.setNode(node.id, { width: width + 20, height: CONCEPT_CARD_HEADER_HEIGHT + 20 });
    } else if (nodeData.nodeType === "datasource") {
      const dsName = nodeData.datasource_label || nodeData.datasource_type || "Data Source";
      const width = getConceptCardWidth(dsName, DATASOURCE_CARD_CHROME_WIDTH);
      g.setNode(node.id, { width: width + 20, height: CONCEPT_CARD_HEADER_HEIGHT + 20 });
    } else {
      const fieldCount = Object.keys(nodeData.fields ?? {}).length;
      // The footer renders for the language pill, row counts, and the attached-
      // context marker — so it is present whenever any of those are set.
      const hasFooter = Boolean(
        nodeData.concept_type ||
          (nodeData.is_populated && (nodeData.row_count ?? 0) > 0) ||
          nodeData.hasContext,
      );
      const height = getConceptCardHeight(fieldCount, !!nodeData.isExpanded, hasFooter);
      const width = getConceptCardWidth(nodeData.label);
      g.setNode(node.id, { width: width + 20, height: height + 20 });
    }
  });

  edges.forEach((edge) => {
    g.setEdge(edge.source, edge.target);
  });

  dagre.layout(g);

  const layoutedNodes = nodes.map((node) => {
    const pos = g.node(node.id);
    return {
      ...node,
      position: {
        x: pos.x - pos.width / 2,
        y: pos.y - pos.height / 2,
      },
    };
  });

  return { nodes: layoutedNodes, edges };
};

/** Map API lineage edges to ReactFlow edges with default styling. */
export const transformEdges = (
  apiEdges: { source: string; target: string; label: string }[],
): Edge[] =>
  apiEdges.map((e, i) => ({
    id: `e-${e.source}-${e.target}-${i}`,
    source: e.source,
    target: e.target,
    type: "default",
    animated: false,
    style: DEFAULT_EDGE_STYLE,
    markerEnd: DEFAULT_EDGE_MARKER,
  }));

/** Recolor/animate edges based on per-concept execution status. */
export const applyFlowEdgeStyles = (
  flowEdges: Edge[],
  statuses: Record<string, { status: string }>,
): Edge[] => {
  if (Object.keys(statuses).length === 0) return flowEdges;
  return flowEdges.map((e) => {
    const edgeStatus = resolveEdgeStatus(e, statuses);
    if (edgeStatus === "running") {
      return { ...e, animated: true, style: FLOW_RUNNING_STYLE, markerEnd: FLOW_RUNNING_MARKER };
    }
    if (edgeStatus === "success") {
      return { ...e, animated: false, style: FLOW_SUCCESS_STYLE, markerEnd: FLOW_SUCCESS_MARKER };
    }
    return e;
  });
};

/**
 * Walk backwards through the graph from `nodeId` collecting every ancestor
 * node and every edge on the path.  Returns the set of edge IDs that form
 * the full dependency chain from data-sources to the selected node.
 *
 * Also includes the selected node's own output-bind edges (edges pointing into
 * a datasource, i.e. `concept → datasource`). Those are downstream, not
 * upstream, but they represent where the selected concept writes its data, so
 * they must stay in the highlight set instead of being dimmed — otherwise a
 * successful "writes_to" arrow loses its green color when its source concept is
 * selected.
 */
export const collectUpstreamEdgeIds = (nodeId: string, edges: Edge[]): Set<string> => {
  const incomingByTarget = new Map<string, Edge[]>();
  for (const e of edges) {
    const list = incomingByTarget.get(e.target);
    if (list) {
      list.push(e);
    } else {
      incomingByTarget.set(e.target, [e]);
    }
  }

  const visitedNodes = new Set<string>();
  const result = new Set<string>();
  const stack = [nodeId];

  while (stack.length > 0) {
    const current = stack.pop()!;
    if (visitedNodes.has(current)) continue;
    visitedNodes.add(current);

    const incoming = incomingByTarget.get(current);
    if (!incoming) continue;
    for (const edge of incoming) {
      result.add(edge.id);
      stack.push(edge.source);
    }
  }

  for (const e of edges) {
    if (e.source === nodeId && isDatasourceNodeId(e.target)) {
      result.add(e.id);
    }
  }

  return result;
};

/**
 * Apply selection highlighting: edges on the upstream path are bold + blue,
 * all others are dimmed. Execution-status styles are preserved on highlighted
 * edges — only non-highlighted edges get dimmed.
 */
export const applySelectionHighlight = (
  flowEdges: Edge[],
  highlightedIds: Set<string>,
  statuses: Record<string, { status: string }>,
): Edge[] =>
  flowEdges.map((e) => {
    if (highlightedIds.has(e.id)) {
      const edgeStatus = resolveEdgeStatus(e, statuses);
      if (edgeStatus === "running") {
        return { ...e, animated: true, style: FLOW_RUNNING_STYLE, markerEnd: FLOW_RUNNING_MARKER };
      }
      if (edgeStatus === "success") {
        return { ...e, animated: false, style: FLOW_SUCCESS_STYLE, markerEnd: FLOW_SUCCESS_MARKER };
      }
      return {
        ...e,
        animated: false,
        style: HIGHLIGHTED_EDGE_STYLE,
        markerEnd: HIGHLIGHTED_EDGE_MARKER,
      };
    }
    return { ...e, animated: false, style: DIMMED_EDGE_STYLE, markerEnd: DIMMED_EDGE_MARKER };
  });
