import { Link2, NotebookText } from "lucide-react";
import { useMemo } from "react";

import { useOntologies } from "@/features/ontologies/hooks/useOntologies";
import { cn } from "@/shared/lib/utils";

import { useAllContextEdges } from "../hooks/useContextEdges";
import { useContextNotes } from "../hooks/useContextNotes";
import { ShelfBadge } from "../notes/components/ShelfBadge";
import type { PanelNoteConnection, PanelNoteEntry } from "./contextPanelModel";
import { buildContextPanelEntries, filterPanelEntries } from "./contextPanelModel";

interface ContextNotesPanelProps {
  ontologyId: string;
  searchTerm: string;
  /** Opens the note in the Explorer's bottom dock — inside the concept's
   *  context tab when attached (conceptName set), standalone otherwise. */
  onOpenNote: (noteId: string, conceptName?: string) => void;
}

function connectionChipClass(kind: PanelNoteConnection["kind"]): string {
  if (kind === "concept" || kind === "ontology") {
    return "bg-violet-100 text-violet-700 hover:bg-violet-200 dark:bg-violet-900/30 dark:text-violet-300 dark:hover:bg-violet-900/50";
  }
  return "bg-muted text-muted-foreground hover:bg-accent hover:text-accent-foreground";
}

/** Right-rail Context panel: every note related to the open project —
 *  project-scoped, attached to the project, or attached to its concepts —
 *  with first-level connections as chips. */
export function ContextNotesPanel({ ontologyId, searchTerm, onOpenNote }: ContextNotesPanelProps) {
  const { projects } = useOntologies();
  const { data: ontologyNotes, isLoading: ontologyLoading } = useContextNotes({
    scope: "ontology",
    scopeId: ontologyId,
  });
  const { data: globalNotes, isLoading: globalLoading } = useContextNotes({ scope: "global" });
  const { data: allEdges, isLoading: edgesLoading } = useAllContextEdges();

  const ontologyName = useMemo(
    () => projects?.find((p) => p.id === ontologyId)?.name ?? "This ontology",
    [projects, ontologyId],
  );

  const entries = useMemo(
    () =>
      buildContextPanelEntries(
        ontologyId,
        ontologyName,
        ontologyNotes ?? [],
        globalNotes ?? [],
        allEdges ?? [],
      ),
    [ontologyId, ontologyName, ontologyNotes, globalNotes, allEdges],
  );
  const visible = filterPanelEntries(entries, searchTerm);

  const handleOpenNote = (entry: PanelNoteEntry) => {
    // Attached notes open inside their (first) concept's context tab.
    const conceptConnection = entry.connections.find((c) => c.kind === "concept");
    onOpenNote(entry.note.id, conceptConnection?.conceptName);
  };

  const handleConnectionClick = (event: React.MouseEvent, connection: PanelNoteConnection) => {
    event.stopPropagation();
    if (connection.kind === "concept" && connection.conceptName) {
      window.dispatchEvent(
        new CustomEvent("lineageFocusConcept", {
          detail: { conceptName: connection.conceptName },
        }),
      );
      return;
    }
    if (connection.kind === "note" && connection.noteId) {
      onOpenNote(connection.noteId);
    }
  };

  if (ontologyLoading || globalLoading || edgesLoading) {
    return <p className="p-4 text-center text-muted-foreground">Loading context notes...</p>;
  }

  if (visible.length === 0) {
    return (
      <div className="p-4 text-center text-muted-foreground">
        <p>{searchTerm ? "No notes match your search" : "No context notes for this ontology"}</p>
        <p className="text-sm mt-2">
          {searchTerm
            ? "Try a different search term"
            : "Attach notes from a concept's context tab, or add ontology notes on the Context page"}
        </p>
      </div>
    );
  }

  return (
    <>
      {visible.map((entry) => (
        <button
          key={entry.note.id}
          type="button"
          onClick={() => handleOpenNote(entry)}
          className="w-full rounded-lg border bg-card px-3 py-2.5 text-left transition-colors hover:border-violet-400 dark:hover:border-violet-500"
        >
          <div className="flex items-center gap-2">
            <NotebookText className="h-4 w-4 shrink-0 text-violet-500 dark:text-violet-400" />
            <span className="min-w-0 flex-1 truncate text-sm font-medium text-foreground">
              {entry.title}
            </span>
            <ShelfBadge shelf={entry.shelf} />
          </div>
          {entry.snippet && (
            <p className="mt-1 line-clamp-2 text-xs leading-snug text-muted-foreground">
              {entry.snippet}
            </p>
          )}
          {entry.connections.length > 0 && (
            <div className="mt-2 flex flex-wrap items-center gap-1">
              <Link2 className="h-3 w-3 shrink-0 text-muted-foreground" />
              {entry.connections.map((connection) => (
                <span
                  key={`${connection.kind}:${connection.label}`}
                  role="link"
                  tabIndex={0}
                  onClick={(event) => handleConnectionClick(event, connection)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") handleConnectionClick(event as never, connection);
                  }}
                  className={cn(
                    "inline-block max-w-[180px] cursor-pointer truncate rounded px-1.5 py-0.5 align-bottom text-[11px] font-medium transition-colors",
                    connectionChipClass(connection.kind),
                  )}
                  title={
                    connection.kind === "concept"
                      ? "Focus this concept in the lineage"
                      : connection.label
                  }
                >
                  {connection.label}
                </span>
              ))}
            </div>
          )}
        </button>
      ))}
    </>
  );
}
