import type React from "react";
import { useMachineStatusContext } from "@/features/compute/context/MachineStatusContext";
import { useStartMachineStore } from "@/features/compute/store/startMachineStore";
import { StartMachineModal } from "./StartMachineModal";

/**
 * Mounted once at app level (inside MachineStatusProvider).
 * Any component can open it by calling useStartMachineStore().openModal().
 */
export const GlobalStartMachineModal: React.FC = () => {
  const { open, closeModal } = useStartMachineStore();
  const {
    notRunningMachines,
    availabilityResults,
    checkingAvailability,
    startMachine,
    databricksClusters,
    loadingDatabricksClusters,
    startDatabricksCluster,
    fetchDatabricksClusters,
  } = useMachineStatusContext();

  return (
    <StartMachineModal
      open={open}
      onClose={closeModal}
      stoppedMachines={notRunningMachines}
      availabilityResults={availabilityResults}
      checkingAvailability={checkingAvailability}
      onStartMachine={startMachine}
      databricksClusters={databricksClusters}
      loadingDatabricksClusters={loadingDatabricksClusters}
      onStartDatabricksCluster={startDatabricksCluster}
      onFetchDatabricksClusters={fetchDatabricksClusters}
    />
  );
};
