import { Check, Loader2, UserPlus, X } from "lucide-react";
import type React from "react";
import { useCallback } from "react";
import { toast } from "sonner";
import { useTeamJoinRequests } from "@/features/teams/hooks/useTeamJoinRequests";
import type { TeamError, TeamJoinRequest } from "@/features/teams/types";
import { Button } from "@/shared/components/ui/button";

interface TeamJoinRequestsSectionProps {
  teamId: string;
}

// Team-side "Join requests" panel — owner/admin only. Sits next to the
// pending-invitations section in TeamRosterPanel. Non-admin callers see an
// empty list from the backend, but the parent hides the section entirely to
// avoid rendering a permanently-empty panel for regular members.
const TeamJoinRequestsSection: React.FC<TeamJoinRequestsSectionProps> = ({ teamId }) => {
  const {
    requests,
    isLoading,
    error,
    approve,
    reject,
    isApproving,
    approvingRequestId,
    isRejecting,
    rejectingRequestId,
  } = useTeamJoinRequests(teamId);

  return (
    <section className="space-y-3">
      <div>
        <h3 className="text-sm font-semibold text-foreground">Join requests</h3>
        <p className="text-xs text-muted-foreground">
          {requests.length === 0 ? "No pending requests" : `${requests.length} awaiting review`}
        </p>
      </div>

      {isLoading ? (
        <div className="flex items-center gap-2 py-4 text-xs text-muted-foreground">
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
          Loading join requests...
        </div>
      ) : error ? (
        <div className="rounded-md border border-destructive/40 bg-destructive/[0.04] px-3 py-2 text-xs text-destructive">
          {error.message}
        </div>
      ) : requests.length === 0 ? (
        <div className="flex flex-col items-center justify-center gap-2 rounded-md border border-dashed border-border bg-muted/30 px-3 py-6 text-center">
          <div className="flex h-9 w-9 items-center justify-center rounded-full bg-secondary">
            <UserPlus className="h-4 w-4 text-muted-foreground" />
          </div>
          <p className="text-xs text-muted-foreground">
            Users from your domain can request to join — their requests will show up here.
          </p>
        </div>
      ) : (
        <div className="space-y-2">
          {requests.map((request) => (
            <JoinRequestRow
              key={request.id}
              request={request}
              onApprove={approve}
              onReject={reject}
              isApproving={isApproving && approvingRequestId === request.id}
              isRejecting={isRejecting && rejectingRequestId === request.id}
            />
          ))}
        </div>
      )}
    </section>
  );
};

interface JoinRequestRowProps {
  request: TeamJoinRequest;
  onApprove: (requestId: string) => Promise<unknown>;
  onReject: (requestId: string) => Promise<unknown>;
  isApproving: boolean;
  isRejecting: boolean;
}

// Single join-request row. Layout mirrors TeamMemberRow / PendingInvitationRow
// so the three admin sections read as a family. Approve is primary (adds a
// member) — reject is a ghost destructive.
const JoinRequestRow: React.FC<JoinRequestRowProps> = ({
  request,
  onApprove,
  onReject,
  isApproving,
  isRejecting,
}) => {
  const busy = isApproving || isRejecting;
  const displayName = request.username || request.email;

  const handleApprove = useCallback(async (): Promise<void> => {
    try {
      await onApprove(request.id);
      toast.success(`Added ${displayName} to the team.`);
    } catch (err) {
      const teamErr = err as TeamError;
      // 404 — the request may already have been cancelled or actioned from
      // another tab. Next refetch will drop the row; the message tells the
      // admin why the button just did nothing.
      if (teamErr.httpStatus === 404) {
        toast.error("This request is no longer pending.");
        return;
      }
      if (teamErr.httpStatus === 409) {
        toast.error(teamErr.message || "This user is already a member.");
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to approve request";
      toast.error(message);
    }
  }, [displayName, onApprove, request.id]);

  const handleReject = useCallback(async (): Promise<void> => {
    const confirmed = window.confirm(
      `Reject the join request from ${displayName}? They'll be able to request again later.`,
    );
    if (!confirmed) return;
    try {
      await onReject(request.id);
      toast.success(`Rejected request from ${displayName}.`);
    } catch (err) {
      const teamErr = err as TeamError;
      if (teamErr.httpStatus === 404) {
        toast.error("This request is no longer pending.");
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to reject request";
      toast.error(message);
    }
  }, [displayName, onReject, request.id]);

  return (
    <div className="flex items-start justify-between gap-3 rounded-md border border-border bg-card px-3 py-2.5">
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <UserPlus className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
          <span className="truncate text-sm font-medium text-foreground">{displayName}</span>
        </div>
        <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
          <span className="truncate">{request.email}</span>
          {request.organization && (
            <>
              <span aria-hidden="true">·</span>
              <span className="truncate">{request.organization}</span>
            </>
          )}
        </div>
      </div>
      <div className="flex items-center gap-1">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="h-8 text-destructive hover:text-destructive"
          onClick={handleReject}
          disabled={busy}
        >
          {isRejecting ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <X className="h-3.5 w-3.5" />
          )}
          <span className="ml-1">Reject</span>
        </Button>
        <Button type="button" size="sm" className="h-8" onClick={handleApprove} disabled={busy}>
          {isApproving ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <Check className="h-3.5 w-3.5" />
          )}
          <span className="ml-1">Approve</span>
        </Button>
      </div>
    </div>
  );
};

export default TeamJoinRequestsSection;
