import { useMemo, useState } from "react";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/components/ui/tabs";
import { useEngineMonitor } from "../hooks/useEngineMonitor";
import { computeTaskTotals } from "../utils/engineMonitor.utils";
import EngineMonitorEmptyState from "./EngineMonitorEmptyState";
import EngineMonitorExecutors from "./EngineMonitorExecutors";
import EngineMonitorHeader from "./EngineMonitorHeader";
import EngineMonitorJobs from "./EngineMonitorJobs";
import EngineMonitorLogs from "./EngineMonitorLogs";
import EngineMonitorOverview from "./EngineMonitorOverview";
import EngineMonitorRuntime from "./EngineMonitorRuntime";
import EngineMonitorStatus from "./EngineMonitorStatus";

interface EngineMonitorPanelProps {
  isRunning: boolean;
}

type TabValue = "overview" | "jobs" | "executors" | "runtime" | "logs" | "status";

interface TabTriggerWithCountProps {
  value: TabValue;
  label: string;
  count?: number;
}

const VALID_TABS: ReadonlySet<TabValue> = new Set<TabValue>([
  "overview",
  "jobs",
  "executors",
  "runtime",
  "logs",
  "status",
]);

function isTabValue(value: string): value is TabValue {
  return (VALID_TABS as ReadonlySet<string>).has(value);
}

const TabTriggerWithCount: React.FC<TabTriggerWithCountProps> = ({ value, label, count }) => (
  <TabsTrigger
    value={value}
    className="group text-xs h-6 px-2 gap-1.5 data-[state=active]:font-semibold"
  >
    <span>{label}</span>
    {typeof count === "number" ? (
      <span className="inline-flex h-4 min-w-[16px] items-center justify-center rounded-full bg-muted-foreground/20 px-1 text-[9px] font-semibold tabular-nums text-muted-foreground transition-colors group-data-[state=active]:bg-primary/15 group-data-[state=active]:text-primary">
        {count}
      </span>
    ) : null}
  </TabsTrigger>
);

const EngineMonitorPanel: React.FC<EngineMonitorPanelProps> = ({ isRunning }) => {
  const {
    status,
    jobs,
    executors,
    applications,
    runtime,
    isLoading,
    lastUpdatedAt,
    error,
    refreshNow,
    triggerGc,
  } = useEngineMonitor();

  const canSeeLogs = usePermissionsStore((state) => state.canSee("can_see_engine_logs"));

  const [activeTab, setActiveTab] = useState<TabValue>("overview");

  const sparkActive = status?.running === true;
  const engineAlive =
    runtime.health?.status === "UP" || runtime.cpu !== null || runtime.memoryUsed !== null;
  const runningTasks = useMemo(() => computeTaskTotals(jobs).running, [jobs]);

  const handleTabChange = (value: string) => {
    if (!isTabValue(value)) return;
    if (value === "logs" && !canSeeLogs) return;
    setActiveTab(value);
  };

  const handleRefresh = () => {
    void refreshNow();
  };

  const handleTriggerGc = () => {
    void triggerGc();
  };

  return (
    <div className="border border-border/40 rounded-md overflow-hidden bg-gradient-to-b from-muted/30 to-muted/10">
      <EngineMonitorHeader
        isRunning={isRunning}
        engineAlive={engineAlive}
        sparkActive={sparkActive}
        isLoading={isLoading}
        runningTaskCount={runningTasks}
        executorCount={executors.length}
        lastUpdatedAt={lastUpdatedAt}
        onRefresh={handleRefresh}
      />
      <Tabs value={activeTab} onValueChange={handleTabChange}>
        <div className="px-3 pt-3">
          <TabsList className="h-8 bg-muted/60 border border-border/60">
            <TabTriggerWithCount value="overview" label="Overview" />
            <TabTriggerWithCount value="jobs" label="Jobs" count={jobs.length} />
            <TabTriggerWithCount value="executors" label="Executors" count={executors.length} />
            <TabTriggerWithCount value="runtime" label="Runtime" />
            {canSeeLogs && <TabTriggerWithCount value="logs" label="Logs" />}
            <TabTriggerWithCount value="status" label="Status" />
          </TabsList>
        </div>

        <TabsContent value="overview" className="mt-0">
          {sparkActive ? (
            <EngineMonitorOverview jobs={jobs} executors={executors} applications={applications} />
          ) : (
            <EngineMonitorEmptyState isLoading={isLoading && !lastUpdatedAt} />
          )}
        </TabsContent>
        <TabsContent value="jobs" className="mt-0">
          {sparkActive ? (
            <EngineMonitorJobs jobs={jobs} />
          ) : (
            <EngineMonitorEmptyState isLoading={isLoading && !lastUpdatedAt} />
          )}
        </TabsContent>
        <TabsContent value="executors" className="mt-0">
          {sparkActive ? (
            <EngineMonitorExecutors executors={executors} />
          ) : (
            <EngineMonitorEmptyState isLoading={isLoading && !lastUpdatedAt} />
          )}
        </TabsContent>
        <TabsContent value="runtime" className="mt-0">
          <EngineMonitorRuntime runtime={runtime} onTriggerGc={handleTriggerGc} />
        </TabsContent>
        {canSeeLogs && (
          <TabsContent value="logs" className="mt-0">
            <EngineMonitorLogs active={activeTab === "logs"} />
          </TabsContent>
        )}
        <TabsContent value="status" className="mt-0">
          <EngineMonitorStatus
            status={status}
            jobsCount={jobs.length}
            executorsCount={executors.length}
            applicationsCount={applications.length}
            lastUpdatedAt={lastUpdatedAt}
            error={error}
          />
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default EngineMonitorPanel;
