import { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";

/**
 * Resolves the project the AI assistant should operate on, based on what the
 * user is currently looking at. Returns null when there is no active project
 * context (home, data sources, compute, …) so the chat falls back to the "_"
 * sentinel and the backend reports "no project open".
 *
 * Recognised contexts:
 *   /editor/:org/:user/:ontologyId      — concept editor (standard)
 *   /editor/:ontologyId                 — concept editor (legacy)
 *   /dashboards/:ontologyId/:id[/edit]  — dynamic dashboard (ontologyId is in the URL)
 *   /apps/:dashboardId                 — federated app (ontologyId is not in the URL;
 *                                        AppsDashboardPage / RemoteAppHost seed it into
 *                                        sessionStorage as `currentOntologyId` once the
 *                                        app's config resolves)
 */
function ontologyIdFromPath(pathname: string): string | null {
  // Standard editor: /editor/org/user/ontologyId
  const editorLong = pathname.match(/^\/editor\/[^/]+\/[^/]+\/([^/]+)/);
  if (editorLong) return editorLong[1];
  // Legacy editor: /editor/ontologyId
  const editorShort = pathname.match(/^\/editor\/([^/]+)$/);
  if (editorShort) return editorShort[1];
  // Dynamic dashboard: /dashboards/projectId/id and /dashboards/projectId/id/edit.
  // Excludes /dashboards/new/edit, which has no project assigned yet.
  const dashboard = pathname.match(/^\/dashboards\/([^/]+)\/[^/]+/);
  if (dashboard && dashboard[1] !== "new") return dashboard[1];
  return null;
}

const APPS_ROUTE = /^\/apps\/[^/]+/;

function resolveOntologyId(pathname: string): string | null {
  const fromPath = ontologyIdFromPath(pathname);
  if (fromPath) return fromPath;
  // Federated apps carry the projectId in sessionStorage, not the URL.
  if (APPS_ROUTE.test(pathname)) return sessionStorage.getItem("currentOntologyId");
  return null;
}

export function useCurrentOntologyId(): string | null {
  const { pathname } = useLocation();
  const [ontologyId, setOntologyId] = useState<string | null>(() => resolveOntologyId(pathname));

  useEffect(() => {
    const update = () => setOntologyId(resolveOntologyId(pathname));
    update();
    // A federated app seeds `currentOntologyId` only after its remote config
    // loads, so react to that the same way useProjectId does.
    window.addEventListener("sessionStorageChanged", update);
    window.addEventListener("storage", update);
    return () => {
      window.removeEventListener("sessionStorageChanged", update);
      window.removeEventListener("storage", update);
    };
  }, [pathname]);

  return ontologyId;
}
