import type { FetchResult } from "../../../api/ConceptClient";
import { columnIndex } from "../../../runtime/useConceptRows";
import type { ColumnFormat } from "../../../schema/appDefinition.types";
import type {
  BoundTableHandlers,
  ColumnFilterValue,
  OrderByItem,
} from "../../outputs/table/tableOutput.types";

/**
 * Column projection for rich_table's `columns` subset/order.
 *
 * Sort/filter handlers and the server-side search state address columns by
 * ORIGINAL fetch position, while the projected table displays a subset — the
 * projection remaps both directions so header interactions keep working.
 */

export interface ColumnProjection {
  /** original column indexes, in display order */
  indexes: number[];
}

export function buildProjection(
  columnNames: string[],
  subset: string[] | undefined,
): ColumnProjection | null {
  if (!subset || subset.length === 0) return null;
  const indexes = subset
    .map((name) => columnIndex(columnNames, name))
    .filter((index) => index >= 0);
  if (indexes.length === 0) return null;
  return { indexes };
}

function ontologyOrderBy(
  orderBy: OrderByItem[] | undefined,
  projection: ColumnProjection,
): OrderByItem[] | undefined {
  if (!orderBy) return undefined;
  return orderBy
    .map((item) => ({ ...item, position: projection.indexes.indexOf(item.position) }))
    .filter((item) => item.position >= 0);
}

function ontologyFilterKeys(
  filters: Record<number, ColumnFilterValue> | undefined,
  projection: ColumnProjection,
): Record<number, ColumnFilterValue> | undefined {
  if (!filters) return undefined;
  const projected: Record<number, ColumnFilterValue> = {};
  for (const [key, value] of Object.entries(filters)) {
    const displayed = projection.indexes.indexOf(Number(key));
    if (displayed >= 0) projected[displayed] = value;
  }
  return projected;
}

export function ontologyData(data: FetchResult, projection: ColumnProjection): FetchResult {
  return {
    ...data,
    columnNames: projection.indexes.map((index) => data.columnNames[index]),
    rows: data.rows.map((row) => projection.indexes.map((index) => row[index])),
    orderBy: ontologyOrderBy(data.orderBy, projection),
    ...(data.searchState
      ? {
          searchState: {
            ...data.searchState,
            columnFilters: ontologyFilterKeys(data.searchState.columnFilters, projection),
          },
        }
      : {}),
  };
}

export function ontologyHandlers(
  handlers: BoundTableHandlers,
  projection: ColumnProjection,
): BoundTableHandlers {
  const toOriginal = (displayed: number) => projection.indexes[displayed] ?? displayed;
  return {
    ...handlers,
    onSort: (orderBy) =>
      handlers.onSort(orderBy.map((item) => ({ ...item, position: toOriginal(item.position) }))),
    onSearch: (searchTerm, columnFilters) => {
      if (!columnFilters) return handlers.onSearch(searchTerm, columnFilters);
      const remapped: Record<number, ColumnFilterValue> = {};
      for (const [key, value] of Object.entries(columnFilters)) {
        remapped[toOriginal(Number(key))] = value;
      }
      return handlers.onSearch(searchTerm, remapped);
    },
  };
}

/** Format a cell per the column's declared format; non-numeric cells pass through. */
export function formatCell(cell: unknown, format: ColumnFormat | undefined): string {
  const text = cell === null || cell === undefined ? "" : String(cell);
  if (!format) return text;
  const numeric = Number(cell);
  if (!Number.isFinite(numeric)) return text;
  if (format === "number") return numeric.toLocaleString();
  if (format === "percent") return `${text}%`;
  // signed_percent: "+0.24%" / "-0.04%"
  return `${numeric > 0 ? "+" : ""}${text}%`;
}
