import { Loader2, Ticket, Trash2 } from "lucide-react";
import type React from "react";
import { useCallback } from "react";
import { toast } from "sonner";
import type { AssignableTeamRole, MemberRow, TeamError, TeamRole } from "@/features/teams/types";
import { assignableRolesFor, teamRoleMeta } from "@/features/teams/utils/teams.utils";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { cn } from "@/shared/lib/utils";

interface TeamMemberRowProps {
  member: MemberRow;
  callerRole: TeamRole;
  callerUserId: string;
  onChangeRole: (userId: string, role: AssignableTeamRole) => Promise<unknown>;
  onRemove: (userId: string) => Promise<unknown>;
  onGrantSeat: (userId: string) => Promise<unknown>;
  onReleaseSeat: (userId: string) => Promise<unknown>;
  isUpdatingRole: boolean;
  isRemoving: boolean;
  isUpdatingSeat: boolean;
  // Whether the plan has at least one free seat left. Only meaningful when
  // the caller can manage seats — regular members never see the toggle.
  canGrantMoreSeats: boolean;
}

function isAssignableRole(value: string): value is AssignableTeamRole {
  return value === "admin" || value === "member";
}

// Roster row on the team detail page. Rendering rules match the FE gating
// cheat-sheet in the backend contract:
//   * Owner row is read-only — the owner can only be replaced via
//     transfer-ownership; the role select is hidden and the remove button is
//     hidden. The owner's seat is protected (auto-seated on team creation,
//     backend refuses release with 409) so we skip the seat toggle too and
//     show the passive "Seated" badge instead.
//   * Non-owner rows show a role select + remove button when the caller is
//     owner/admin. The backend also enforces this (returns 403), so optimistic
//     rendering is safe.
//   * The caller can't remove themselves from the roster — leaving the team is
//     a distinct flow (Leave team in the header kebab).
//   * Seat controls are shown to owner/admin on every non-owner row. Regular
//     members see the seat status on all rows as a passive indicator only.
const TeamMemberRow: React.FC<TeamMemberRowProps> = ({
  member,
  callerRole,
  callerUserId,
  onChangeRole,
  onRemove,
  onGrantSeat,
  onReleaseSeat,
  isUpdatingRole,
  isRemoving,
  isUpdatingSeat,
  canGrantMoreSeats,
}) => {
  const canManage = callerRole === "owner" || callerRole === "admin";
  const isTargetOwner = member.role === "owner";
  const isSelf = member.user_id === callerUserId;

  const canEditRole = canManage && !isTargetOwner;
  const canRemove = canManage && !isTargetOwner && !isSelf;
  // Owner's seat is permanent (backend 409 on release) — read-only badge.
  const canToggleSeat = canManage && !isTargetOwner;

  const handleRoleSelect = useCallback(
    async (value: string): Promise<void> => {
      if (!isAssignableRole(value)) return;
      if (value === member.role) return;
      try {
        await onChangeRole(member.user_id, value);
        toast.success(`Role updated to ${value}`);
      } catch (err) {
        const message = err instanceof Error ? err.message : "Failed to update role";
        toast.error(message);
      }
    },
    [member.user_id, member.role, onChangeRole],
  );

  const handleRemove = useCallback(async (): Promise<void> => {
    const confirmed = window.confirm(
      `Remove ${member.username} from the team? This can't be undone.`,
    );
    if (!confirmed) return;
    try {
      await onRemove(member.user_id);
      toast.success(`${member.username} removed from the team`);
    } catch (err) {
      const teamErr = err as TeamError;
      if (teamErr.httpStatus === 403) {
        toast.error(teamErr.message || "You aren't allowed to remove this member.");
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to remove member";
      toast.error(message);
    }
  }, [member.user_id, member.username, onRemove]);

  const handleGrantSeat = useCallback(async (): Promise<void> => {
    try {
      await onGrantSeat(member.user_id);
      toast.success(`Granted a seat to ${member.username}`);
    } catch (err) {
      const teamErr = err as TeamError;
      // 409 = out of free seats. Surface backend detail verbatim so the
      // admin knows exactly why the click didn't stick.
      if (teamErr.httpStatus === 409) {
        toast.error(teamErr.message || "No free seats on this plan.", {
          description: "Release a seat from another member or upgrade the plan.",
        });
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to grant seat";
      toast.error(message);
    }
  }, [member.user_id, member.username, onGrantSeat]);

  const handleReleaseSeat = useCallback(async (): Promise<void> => {
    const confirmed = window.confirm(
      `Release ${member.username}'s seat? They'll lose the team plan benefit.`,
    );
    if (!confirmed) return;
    try {
      await onReleaseSeat(member.user_id);
      toast.success(`Released ${member.username}'s seat`);
    } catch (err) {
      const teamErr = err as TeamError;
      // 409 = owner's own seat, but we already hide the toggle for owner
      // rows. Surface backend detail as a fallback in case backend state
      // drifted from the FE cache.
      if (teamErr.httpStatus === 409) {
        toast.error(teamErr.message || "This seat can't be released.");
        return;
      }
      const message = err instanceof Error ? err.message : "Failed to release seat";
      toast.error(message);
    }
  }, [member.user_id, member.username, onReleaseSeat]);

  const roleTitle = teamRoleMeta(member.role).title;

  return (
    <div
      className={cn(
        "flex items-start justify-between gap-3 rounded-md border border-border bg-card px-3 py-2.5",
        member.status !== "active" && "opacity-60",
      )}
    >
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className="truncate text-sm font-medium text-foreground">
            {member.username}
            {isSelf && (
              <span className="ml-1.5 text-xs font-normal text-muted-foreground">(you)</span>
            )}
          </span>
          <span className="truncate text-xs text-muted-foreground">{member.email}</span>
        </div>
        <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
          {canEditRole ? (
            <div className="flex items-center gap-1.5">
              <Select
                value={member.role}
                onValueChange={handleRoleSelect}
                disabled={isUpdatingRole}
              >
                <SelectTrigger className="h-7 w-[100px] px-2 py-0 text-xs capitalize">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {assignableRolesFor(callerRole).map((r) => (
                    <SelectItem key={r} value={r} className="capitalize">
                      {r}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {isUpdatingRole && <Loader2 className="h-3 w-3 animate-spin text-muted-foreground" />}
            </div>
          ) : (
            <Badge variant="outline" className="capitalize">
              {roleTitle}
            </Badge>
          )}
          {member.seat_granted && (
            <Badge
              className="gap-1 bg-amber-500/15 text-amber-700 hover:bg-amber-500/20 dark:text-amber-400"
              title="This member currently holds a seat on the team plan"
            >
              <Ticket className="h-3 w-3" />
              Seated
            </Badge>
          )}
          <span>@{member.organization}</span>
        </div>
      </div>
      <div className="flex items-center gap-1">
        {canToggleSeat && member.seat_granted && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-8"
            onClick={handleReleaseSeat}
            disabled={isUpdatingSeat}
            title="Release this seat"
          >
            {isUpdatingSeat ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Ticket className="h-3.5 w-3.5" />
            )}
            <span className="ml-1">Release seat</span>
          </Button>
        )}
        {canToggleSeat && !member.seat_granted && (
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-8"
            onClick={handleGrantSeat}
            disabled={isUpdatingSeat || !canGrantMoreSeats}
            title={canGrantMoreSeats ? "Grant a plan seat" : "No free seats on this plan"}
          >
            {isUpdatingSeat ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Ticket className="h-3.5 w-3.5" />
            )}
            <span className="ml-1">Grant seat</span>
          </Button>
        )}
        {canRemove && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-8 text-destructive hover:text-destructive"
            onClick={handleRemove}
            disabled={isRemoving}
          >
            {isRemoving ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Trash2 className="h-3.5 w-3.5" />
            )}
            <span className="ml-1">Remove</span>
          </Button>
        )}
      </div>
    </div>
  );
};

export default TeamMemberRow;
