import { Pencil } from "lucide-react";
import type React from "react";
import { Input } from "@/shared/components/ui/input";

interface CellRenameControlProps {
  /** Current concept name — empty renders the placeholder label. */
  name: string;
  isRenaming: boolean;
  renameValue: string;
  inputRef: React.Ref<HTMLInputElement>;
  onRenameValueChange: (value: string) => void;
  onConfirm: () => void;
  onCancel: () => void;
  onStart: () => void;
}

/**
 * The editable concept-name widget in a cell header: a label that turns into an
 * input on click. Enter confirms, Escape cancels, blur confirms.
 */
export function CellRenameControl({
  name,
  isRenaming,
  renameValue,
  inputRef,
  onRenameValueChange,
  onConfirm,
  onCancel,
  onStart,
}: CellRenameControlProps) {
  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") onConfirm();
    if (event.key === "Escape") onCancel();
  };

  if (isRenaming) {
    return (
      <Input
        ref={inputRef}
        value={renameValue}
        onChange={(e) => onRenameValueChange(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={onConfirm}
        placeholder="concept_name"
        className="h-7 text-sm w-40 bg-muted/80"
        autoFocus
      />
    );
  }

  return (
    <button
      type="button"
      onClick={onStart}
      className="flex flex-shrink-0 items-center gap-1 px-2 py-1 rounded text-sm font-medium cursor-pointer hover:bg-muted/80 bg-muted/50 min-w-[120px]"
    >
      <span className="truncate">{name || "Set concept name..."}</span>
      <Pencil className="h-3 w-3 opacity-50" />
    </button>
  );
}
