import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/shared/components/ui/card";
import { Input } from "@/shared/components/ui/input";
import { useForceLightTheme } from "@/shared/hooks/useForceLightTheme";
import { supabase } from "@/shared/integrations/supabase/client";

const PasswordResetConfirm = () => {
  useForceLightTheme();

  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isValidSession, setIsValidSession] = useState<boolean | null>(null);
  const navigate = useNavigate();

  useEffect(() => {
    // Use Supabase's onAuthStateChange listener to automatically handle the hash fragment
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event, session) => {
      // Set valid session if PASSWORD_RECOVERY event fires or if there's a valid session
      if (event === "PASSWORD_RECOVERY" || session) {
        setIsValidSession(true);
      }
    });

    // Fallback: if no valid session is detected after a short delay, mark as invalid
    const fallbackTimer = setTimeout(() => {
      setIsValidSession((current) => (current === null ? false : current));
    }, 1500);

    return () => {
      subscription.unsubscribe();
      clearTimeout(fallbackTimer);
    };
  }, []);

  // Redirect to login if session is invalid
  useEffect(() => {
    if (isValidSession === false) {
      const timer = setTimeout(() => {
        navigate("/login");
      }, 2000);
      return () => clearTimeout(timer);
    }
  }, [isValidSession, navigate]);

  const isPasswordValid = password.length >= 8;
  const passwordsMatch = password === confirmPassword;
  const canSubmit = isPasswordValid && passwordsMatch && password.length > 0;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!canSubmit) {
      return;
    }

    setIsLoading(true);
    try {
      const { error } = await supabase.auth.updateUser({
        password: password,
      });

      if (error) throw error;

      // Sign out to ensure clean state
      await supabase.auth.signOut();
      navigate("/login");
    } catch (_error: any) {
    } finally {
      setIsLoading(false);
    }
  };

  // Loading state
  if (isValidSession === null) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <Card className="w-[400px] border-0 shadow-none">
          <CardHeader className="text-center space-y-6">
            <div className="flex justify-center">
              <img src="/prometheux-logo.png" alt="Prometheux" className="h-8" />
            </div>
            <CardTitle>Verifying reset link...</CardTitle>
          </CardHeader>
          <CardContent className="text-center">
            <p className="text-sm text-muted-foreground">
              Please wait while we verify your password reset link.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Invalid session state
  if (isValidSession === false) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <Card className="w-[400px] border-0 shadow-none">
          <CardHeader className="text-center space-y-6">
            <div className="flex justify-center">
              <img src="/prometheux-logo.png" alt="Prometheux" className="h-8" />
            </div>
            <CardTitle>Invalid Reset Link</CardTitle>
          </CardHeader>
          <CardContent className="text-center">
            <p className="text-sm text-muted-foreground">
              This password reset link is invalid or has expired. Redirecting to login...
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Valid session - show password reset form
  return (
    <div className="min-h-screen flex items-center justify-center bg-white">
      <Card className="w-[400px] border-0 shadow-none">
        <CardHeader className="text-center space-y-6">
          <div className="flex justify-center">
            <img src="/prometheux-logo.png" alt="Prometheux" className="h-8" />
          </div>
          <CardTitle>Set new password</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Input
                type="password"
                placeholder="New password*"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="bg-[#F5F7FB]"
                required
                disabled={isLoading}
              />
              {password && password.length < 8 && (
                <p className="text-sm text-destructive">Password must be at least 8 characters</p>
              )}
            </div>

            <div className="space-y-2">
              <Input
                type="password"
                placeholder="Confirm new password*"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="bg-[#F5F7FB]"
                required
                disabled={isLoading}
              />
              {confirmPassword && !passwordsMatch && (
                <p className="text-sm text-destructive">Passwords do not match</p>
              )}
              {confirmPassword && passwordsMatch && password.length > 0 && (
                <p className="text-sm text-green-600">Passwords match</p>
              )}
            </div>

            <Button
              type="submit"
              className="w-full bg-[#29CC7A] hover:bg-[#25B86E]"
              disabled={isLoading || !canSubmit}
            >
              {isLoading ? "Updating..." : "Update Password"}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
};

export default PasswordResetConfirm;
