import type React from "react";
import { useState } from "react";
import { cellGroupOrNull } from "@/features/concept-editor/components/explorerTreeItem.utils";
import type { ConceptCell } from "@/features/concept-editor/types";

const DRAG_TYPE = "explorerCell";
export const ROOT_TARGET = "__root__";
type CellDropPosition = "top" | "bottom";

interface DragPayload {
  type: typeof DRAG_TYPE;
  cellId: string;
  sourceGroup: string | null;
}

const isGroupName = (value: unknown): value is string | null =>
  value === null || typeof value === "string";

function parseDragData(raw: string): DragPayload | null {
  if (!raw) return null;
  try {
    const data: unknown = JSON.parse(raw);
    if (typeof data !== "object" || data === null) return null;
    if (!("type" in data) || data.type !== DRAG_TYPE) return null;
    if (!("cellId" in data) || typeof data.cellId !== "string") return null;
    if (!("sourceGroup" in data) || !isGroupName(data.sourceGroup)) return null;
    return { type: DRAG_TYPE, cellId: data.cellId, sourceGroup: data.sourceGroup };
  } catch {
    return null;
  }
}

function getCellDropPosition(e: React.DragEvent): CellDropPosition {
  const bounds = e.currentTarget.getBoundingClientRect();
  return e.clientY < bounds.top + bounds.height / 2 ? "top" : "bottom";
}

interface UseTreeDragDropParams {
  canEditOntologies: boolean;
  onAddCellToGroup: (cellId: string, groupName: string) => void;
  onRemoveCellFromGroup: (cellId: string) => void;
}

interface UseTreeDragDropReturn {
  /** Current drop target — either `ROOT_TARGET`, a folder name, or null. */
  dropTarget: string | null;
  cellDropTarget: { cellId: string; position: CellDropPosition } | null;
  handleDragStartCell: (e: React.DragEvent, cell: ConceptCell) => void;
  handleDragEndCell: () => void;
  handleDragOverCell: (e: React.DragEvent, cell: ConceptCell) => void;
  handleDragLeaveCell: (e: React.DragEvent, cellId: string) => void;
  handleDropOnCell: (e: React.DragEvent, cell: ConceptCell) => void;
  handleDragOverFolder: (e: React.DragEvent, groupName: string) => void;
  handleDragLeaveFolder: (e: React.DragEvent) => void;
  handleDropOnFolder: (e: React.DragEvent, groupName: string) => void;
  handleDragOverRoot: (e: React.DragEvent) => void;
  handleDragLeaveRoot: (e: React.DragEvent) => void;
  handleDropOnRoot: (e: React.DragEvent) => void;
}

/**
 * Explorer drag-and-drop behavior: ordering within a group, moving between
 * groups, ungrouping at the root, and visual drop-target state.
 */
export function useTreeDragDrop(params: UseTreeDragDropParams): UseTreeDragDropReturn {
  const { canEditOntologies, onAddCellToGroup, onRemoveCellFromGroup } = params;
  const [dropTarget, setDropTarget] = useState<string | null>(null);
  const [draggedCell, setDraggedCell] = useState<DragPayload | null>(null);
  const [cellDropTarget, setCellDropTarget] =
    useState<UseTreeDragDropReturn["cellDropTarget"]>(null);

  const handleDragStartCell = (e: React.DragEvent, cell: ConceptCell) => {
    if (!canEditOntologies) return;
    const payload: DragPayload = {
      type: DRAG_TYPE,
      cellId: cell.id,
      sourceGroup: cellGroupOrNull(cell),
    };
    e.dataTransfer.setData("text/plain", JSON.stringify(payload));
    e.dataTransfer.effectAllowed = "move";
    setDraggedCell(payload);
  };

  const handleDragEndCell = () => {
    setDraggedCell(null);
    setCellDropTarget(null);
    setDropTarget(null);
  };

  const handleDragOverCell = (e: React.DragEvent, cell: ConceptCell) => {
    if (!canEditOntologies || !draggedCell) return;
    if (draggedCell.cellId === cell.id || draggedCell.sourceGroup !== cellGroupOrNull(cell)) return;
    e.preventDefault();
    e.stopPropagation();
    e.dataTransfer.dropEffect = "move";
    setDropTarget(null);
    setCellDropTarget({ cellId: cell.id, position: getCellDropPosition(e) });
  };

  const handleDragLeaveCell = (e: React.DragEvent, cellId: string) => {
    if (e.relatedTarget instanceof Node && e.currentTarget.contains(e.relatedTarget)) return;
    setCellDropTarget((current) => (current?.cellId === cellId ? null : current));
  };

  const handleDropOnCell = (e: React.DragEvent, cell: ConceptCell) => {
    if (!canEditOntologies || !draggedCell) return;
    if (draggedCell.cellId === cell.id) return;
    if (draggedCell.sourceGroup !== cellGroupOrNull(cell)) return;
    e.preventDefault();
    e.stopPropagation();
    const position = getCellDropPosition(e);
    setCellDropTarget(null);
    window.dispatchEvent(
      new CustomEvent("cellReorder", {
        detail: { draggedCellId: draggedCell.cellId, targetCellId: cell.id, position },
      }),
    );
  };

  const handleDragOverFolder = (e: React.DragEvent, groupName: string) => {
    if (!canEditOntologies) return;
    e.preventDefault();
    e.stopPropagation();
    e.dataTransfer.dropEffect = "move";
    setDropTarget(groupName);
  };

  const handleDragLeaveFolder = (e: React.DragEvent) => {
    if (e.relatedTarget instanceof Node && e.currentTarget.contains(e.relatedTarget)) return;
    setDropTarget((prev) => (prev === ROOT_TARGET ? prev : null));
  };

  const handleDropOnFolder = (e: React.DragEvent, groupName: string) => {
    if (!canEditOntologies) return;
    e.preventDefault();
    e.stopPropagation();
    setDropTarget(null);
    const data = parseDragData(e.dataTransfer.getData("text/plain"));
    if (!data) return;
    if (data.sourceGroup === groupName) return;
    onAddCellToGroup(data.cellId, groupName);
  };

  const handleDragOverRoot = (e: React.DragEvent) => {
    if (!canEditOntologies) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
    setDropTarget(ROOT_TARGET);
  };

  const handleDragLeaveRoot = (e: React.DragEvent) => {
    if (e.relatedTarget instanceof Node && e.currentTarget.contains(e.relatedTarget)) return;
    setDropTarget(null);
  };

  const handleDropOnRoot = (e: React.DragEvent) => {
    if (!canEditOntologies) return;
    e.preventDefault();
    setDropTarget(null);
    const data = parseDragData(e.dataTransfer.getData("text/plain"));
    if (!data) return;
    if (data.sourceGroup === null) return;
    onRemoveCellFromGroup(data.cellId);
  };

  return {
    dropTarget,
    cellDropTarget,
    handleDragStartCell,
    handleDragEndCell,
    handleDragOverCell,
    handleDragLeaveCell,
    handleDropOnCell,
    handleDragOverFolder,
    handleDragLeaveFolder,
    handleDropOnFolder,
    handleDragOverRoot,
    handleDragLeaveRoot,
    handleDropOnRoot,
  };
}
