import { LottiePlayer } from "@/shared/components/LottiePlayer";

interface HeroLoadingScreenProps {
  /** Animation width/height in pixels. */
  size?: number;
  /** Show the Prometheux logo above the animation. */
  showLogo?: boolean;
  /** Optional caption rendered below the animation. */
  message?: string;
}

// Full-screen, intentionally light-themed loading screen used during auth,
// OAuth, and onboarding transitions (#f2f2f2 matches the forced-light auth UI).
export const HeroLoadingScreen = ({
  size = 400,
  showLogo = false,
  message,
}: HeroLoadingScreenProps) => {
  return (
    <div
      className="flex min-h-screen flex-col items-center justify-center gap-4"
      style={{ background: "#f2f2f2" }}
    >
      {showLogo && <img src="/prometheux-logo.png" alt="Prometheux" className="h-8" />}
      <LottiePlayer
        src="/hero-animation.json"
        style={{ width: `${size}px`, height: `${size}px` }}
        loop
        autoplay
      />
      {message && <p className="text-sm text-gray-500">{message}</p>}
    </div>
  );
};
