import { FileText, ImageIcon } from "lucide-react";
import { toast } from "sonner";

import { AttachmentGoneError, downloadAttachment } from "../attachmentPreview";
import type { MessageAttachment } from "../attachments.types";
import { useAttachmentPreview } from "../hooks/useAttachmentPreview";

interface MessageAttachmentChipProps {
  attachment: MessageAttachment;
  onOpenImage: (attachment: MessageAttachment) => void;
}

/** One attached file on a sent turn: thumbnail if it is an image, name always. */
export function MessageAttachmentChip({ attachment, onOpenImage }: MessageAttachmentChipProps) {
  const { url, isGone } = useAttachmentPreview(attachment);
  const Icon = attachment.kind === "image" ? ImageIcon : FileText;
  const isImage = attachment.kind === "image";
  // Nothing to open for a file whose upload predates path tracking, nor for one
  // retention has since removed.
  const hasTarget = isImage ? !!url || !!attachment.path : !!attachment.path;
  const isInteractive = hasTarget && !isGone;
  const title = isGone
    ? `${attachment.name} (no longer available — attachments are removed after a chat goes unused)`
    : attachment.name;

  const handleClick = async () => {
    if (isImage) {
      onOpenImage(attachment);
      return;
    }
    if (!attachment.path) return;
    try {
      await downloadAttachment(attachment.path, attachment.name);
    } catch (err) {
      const message =
        err instanceof AttachmentGoneError
          ? `"${attachment.name}" is no longer available`
          : `Could not download "${attachment.name}"`;
      toast.error(message);
    }
  };

  return (
    <li className="max-w-[220px]">
      <button
        type="button"
        onClick={handleClick}
        disabled={!isInteractive}
        title={title}
        className="inline-flex w-full items-center gap-1.5 overflow-hidden rounded-lg border border-border bg-card px-2 py-1 text-left transition-colors enabled:hover:bg-accent disabled:cursor-default"
      >
        {url ? (
          <img
            src={url}
            alt={attachment.name}
            className="h-9 w-9 shrink-0 rounded-md border border-border object-cover"
          />
        ) : (
          <Icon
            className={`h-3.5 w-3.5 shrink-0 ${isGone ? "text-muted-foreground/60" : "text-muted-foreground"}`}
          />
        )}
        <span
          className={`truncate text-xs ${isGone ? "text-muted-foreground line-through" : "text-foreground"}`}
        >
          {attachment.name}
        </span>
        {isGone && <span className="shrink-0 text-[10px] text-muted-foreground">expired</span>}
      </button>
    </li>
  );
}
