import { Plus, RefreshCw } from "lucide-react";

import ComputeIndicator from "@/features/compute/components/ComputeIndicator";
import { GlobalSearchTrigger } from "@/features/global-search/components/GlobalSearchTrigger";
import { Button } from "@/shared/components/ui/button";

interface OntologiesListHeaderActionsProps {
  isLoading: boolean;
  canEditOntologies: boolean;
  onRefresh: () => void;
  onNewOntology: () => void;
}

export function OntologiesListHeaderActions({
  isLoading,
  canEditOntologies,
  onRefresh,
  onNewOntology,
}: OntologiesListHeaderActionsProps) {
  return (
    <>
      <GlobalSearchTrigger />
      <ComputeIndicator interactive={true} />
      <Button
        variant="outline"
        size="icon"
        onClick={onRefresh}
        disabled={isLoading}
        title="Refresh"
      >
        <RefreshCw className={`h-4 w-4 ${isLoading ? "animate-spin" : ""}`} />
      </Button>
      {canEditOntologies && (
        <Button className="gap-2" onClick={onNewOntology}>
          <Plus className="h-4 w-4" />
          New Ontology
        </Button>
      )}
    </>
  );
}
