import { syntaxHighlighting } from "@codemirror/language";
import type { Extension } from "@codemirror/state";
import { EditorView } from "@codemirror/view";
import CodeMirror from "@uiw/react-codemirror";
import { Check, Copy, Download, FileCode } from "lucide-react";
import { useMemo, useState } from "react";
import { customLanguage } from "@/features/concept-editor/components/code-editor/language/customProlog";
import { customHighlightStyle } from "@/features/concept-editor/components/code-editor/styles/editorHighlightStyle";
import { Button } from "@/shared/components/ui/button";
import { useThemeStore } from "@/shared/store/themeStore";

interface RenderedFileProps {
  filename: string;
  content: string;
}

export function RenderedFile({ filename, content }: RenderedFileProps) {
  const [copied, setCopied] = useState(false);
  const theme = useThemeStore((s) => s.theme);

  const extensions = useMemo<Extension[]>(
    () => [
      customLanguage,
      syntaxHighlighting(customHighlightStyle),
      EditorView.lineWrapping,
      EditorView.editable.of(false),
      EditorView.theme({
        ".cm-content": { paddingRight: "2rem" },
        ".cm-scroller": { paddingRight: "0.5rem" },
      }),
    ],
    [],
  );

  const handleCopy = async () => {
    await navigator.clipboard.writeText(content);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1500);
  };

  const handleDownload = () => {
    const blob = new Blob([content], { type: "text/vnd.vadalog" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
  };

  if (!content.trim()) {
    return (
      <section className="px-8 py-6">
        <p className="text-sm italic text-muted-foreground/80">
          Nothing to render yet — add a concept to populate this view.
        </p>
      </section>
    );
  }

  return (
    <section className="flex flex-col gap-3 px-8 py-6">
      <header className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <FileCode className="h-4 w-4 text-muted-foreground" />
          <span className="font-mono text-sm text-foreground">{filename}</span>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            className="gap-1.5"
            onClick={handleCopy}
            type="button"
          >
            {copied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
            {copied ? "Copied" : "Copy"}
          </Button>
          <Button
            variant="outline"
            size="sm"
            className="gap-1.5"
            onClick={handleDownload}
            type="button"
          >
            <Download className="h-3.5 w-3.5" />
            Download
          </Button>
        </div>
      </header>
      <div className="overflow-hidden rounded-lg border border-border bg-card">
        <CodeMirror
          value={content}
          extensions={extensions}
          theme={theme}
          editable={false}
          basicSetup={{
            lineNumbers: true,
            foldGutter: false,
            highlightActiveLine: false,
            highlightActiveLineGutter: false,
            autocompletion: false,
            drawSelection: true,
            // Read-only, but Find (Cmd-F) is still useful for navigating large files.
            searchKeymap: true,
          }}
        />
      </div>
    </section>
  );
}
