import type React from "react";
import { Navigate, useLocation } from "react-router-dom";
import { requiresMfaChallenge, useMfaAal } from "@/features/auth/hooks/useMfaAal";
import { HeroLoadingScreen } from "@/shared/components/HeroLoadingScreen";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { useAuth } from "./AuthProvider";

export const RequireAuth = ({ children }: { children: React.ReactNode }) => {
  const { user, loading, hasPlatformAccess } = useAuth();
  const mfaAal = useMfaAal();
  const location = useLocation();

  // Skip authentication in Snowflake mode or development mode
  if (PROMETHEUX_CONFIG.SNOWFLAKE_MODE || PROMETHEUX_CONFIG.SKIP_AUTH) {
    return <>{children}</>;
  }

  if (loading || (user && mfaAal.isLoading)) {
    return <HeroLoadingScreen />;
  }

  if (!user) {
    // Preserve URL hash for OAuth callbacks
    const currentHash = window.location.hash;
    if (currentHash) {
      // Use window.location.replace to preserve hash
      window.location.replace(`/login${currentHash}`);
      return null;
    }
    // Preserve the original URL so LoginPage can redirect back after auth
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  // If the session is at AAL1 but needs AAL2 (user has a verified MFA factor),
  // force the MFA challenge before granting access to any protected route.
  if (requiresMfaChallenge(mfaAal)) {
    return <Navigate to="/mfa-challenge" state={{ from: location }} replace />;
  }

  // Allow access to onboarding even without platform access
  const isOnboardingRoute = location.pathname === "/onboarding";

  // If user has platform access and tries to access onboarding, redirect to home
  if (hasPlatformAccess && isOnboardingRoute) {
    return <Navigate to="/" replace />;
  }

  // If user doesn't have platform access and tries to access protected routes, redirect to onboarding
  if (!hasPlatformAccess && !isOnboardingRoute) {
    // Preserve the original URL so OnboardingPage can redirect back after access is confirmed
    return <Navigate to="/onboarding" state={{ from: location }} replace />;
  }

  return <>{children}</>;
};
