import type React from "react";
import {
  type BrandIconData,
  DATABASE_ICON_BY_TYPE,
  type DatabaseIconSpec,
  DEFAULT_DATABASE_ICON,
} from "./databaseIconMap";
import { FILE_ICON_BY_TYPE, resolveFileIcon } from "./fileTypeIcons";

interface DatabaseIconProps {
  type: string;
  className?: string;
  /** Override the per-type color (e.g. "text-white" for an icon on a colored badge). */
  colorClassName?: string;
}

/**
 * The Tailwind text-color class used to paint a given type's icon. Useful for
 * tinting a surrounding badge to match (e.g. via `bg-current`).
 */
export const getDatabaseIconColorClass = (type: string | undefined | null): string => {
  const normalized = type?.toLowerCase() ?? "";
  const fileSpec = FILE_ICON_BY_TYPE[normalized];
  if (fileSpec) return fileSpec.colorClass;
  const dbSpec = DATABASE_ICON_BY_TYPE[normalized] ?? DEFAULT_DATABASE_ICON;
  return "colorClass" in dbSpec ? dbSpec.colorClass : "text-muted-foreground";
};

// simple-icons SVGs declare intrinsic px size; Tailwind h-/w- classes still override it.
const getSizeFromClassName = (className: string): number => {
  if (className.includes("h-3 w-3")) return 12;
  if (className.includes("h-4 w-4")) return 16;
  if (className.includes("h-5 w-5")) return 20;
  if (className.includes("h-6 w-6")) return 24;
  if (className.includes("h-8 w-8")) return 32;
  if (className.includes("h-12 w-12")) return 48;
  return 20;
};

const BrandIcon: React.FC<{ icon: BrandIconData; size: number; className?: string }> = ({
  icon,
  size,
  className,
}) => (
  <svg
    role="img"
    viewBox="0 0 24 24"
    width={size}
    height={size}
    className={className}
    fill="currentColor"
    xmlns="http://www.w3.org/2000/svg"
  >
    <title>{icon.title}</title>
    <path d={icon.path} />
  </svg>
);

const maskStyle = (src: string): React.CSSProperties => {
  const maskUrl = `url(${src})`;
  return {
    backgroundColor: "currentColor",
    WebkitMaskImage: maskUrl,
    maskImage: maskUrl,
    WebkitMaskRepeat: "no-repeat",
    maskRepeat: "no-repeat",
    WebkitMaskPosition: "center",
    maskPosition: "center",
    WebkitMaskSize: "contain",
    maskSize: "contain",
  };
};

const renderDatabaseSpec = (
  spec: DatabaseIconSpec,
  className: string,
  colorClassName?: string,
): React.ReactElement => {
  // Image-asset logos keep their own colors — an <img> can't be recolored via CSS.
  if (spec.kind === "image") {
    const size = getSizeFromClassName(className);
    return <img src={spec.src} alt={spec.alt} width={size} height={size} className={className} />;
  }
  // Brand + Lucide + mask are monochromatic: painted with currentColor via the theme class.
  const themedClassName = `${className} ${colorClassName ?? spec.colorClass}`;
  // A single-color SVG used as a CSS mask, filled with currentColor so it follows the theme.
  if (spec.kind === "mask") {
    return (
      <span
        role="img"
        aria-label={spec.alt}
        className={`${themedClassName} inline-block`}
        style={maskStyle(spec.src)}
      />
    );
  }
  if (spec.kind === "brand") {
    return (
      <BrandIcon
        icon={spec.icon}
        size={getSizeFromClassName(className)}
        className={themedClassName}
      />
    );
  }
  const { Icon } = spec;
  return <Icon className={themedClassName} />;
};

const DatabaseIcon: React.FC<DatabaseIconProps> = ({
  type,
  className = "h-5 w-5",
  colorClassName,
}) => {
  if (!type) return renderDatabaseSpec(DEFAULT_DATABASE_ICON, className, colorClassName);

  const normalizedType = type.toLowerCase();

  // File types resolve through the shared file-icon source of truth (matches the Files tab).
  const fileIcon = resolveFileIcon(normalizedType, className, colorClassName);
  if (fileIcon) return fileIcon;

  // Database / storage / brand types come from the shared database-icon map.
  return renderDatabaseSpec(
    DATABASE_ICON_BY_TYPE[normalizedType] ?? DEFAULT_DATABASE_ICON,
    className,
    colorClassName,
  );
};

export default DatabaseIcon;
