import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { supabase } from "@/shared/integrations/supabase/client";

export interface UnpaidInvoice {
  id: string;
  status: string;
  sent_at: string;
  stripe_invoice_url: string | null;
  total_amount: number;
}

const UNPAID_INVOICES_KEY = "billing-unpaid-invoices";

const isUnpaidInvoice = (value: unknown): value is UnpaidInvoice => {
  if (typeof value !== "object" || value === null) return false;
  if (!("id" in value) || typeof value.id !== "string") return false;
  if (!("status" in value) || typeof value.status !== "string") return false;
  if (!("sent_at" in value) || typeof value.sent_at !== "string") return false;
  return true;
};

const fetchUnpaidInvoices = async (userId: string): Promise<UnpaidInvoice[]> => {
  const { data, error } = await supabase
    .from("invoices")
    .select("id, status, sent_at, stripe_invoice_url, total_amount")
    .eq("user_id", userId)
    .neq("status", "paid")
    .order("sent_at", { ascending: false });

  if (error) throw error;
  const rows = data ?? [];
  if (!Array.isArray(rows)) {
    throw new Error("invoices select returned non-array data");
  }
  if (!rows.every(isUnpaidInvoice)) {
    throw new Error("invoices select returned rows with unexpected shape");
  }
  return rows;
};

export interface UseUnpaidInvoicesResult {
  invoices: UnpaidInvoice[];
  isLoading: boolean;
  error: Error | null;
  refetch: () => void;
}

export const useUnpaidInvoices = (): UseUnpaidInvoicesResult => {
  const { user } = useAuth();
  const userId = user?.id;

  const query = useQuery({
    queryKey: [UNPAID_INVOICES_KEY, userId],
    queryFn: () => {
      if (!userId) throw new Error("useUnpaidInvoices called without a userId");
      return fetchUnpaidInvoices(userId);
    },
    enabled: Boolean(userId),
  });

  return {
    invoices: query.data ?? [],
    isLoading: query.isLoading,
    error: query.error,
    refetch: () => {
      query.refetch();
    },
  };
};

export const UNPAID_INVOICES_QUERY_KEY = UNPAID_INVOICES_KEY;
