/**
 * OAuth Token Capture Utility
 *
 * This utility captures OAuth tokens from the URL hash immediately when the page loads,
 * before React Router or any other code can clear them.
 */

interface OAuthTokens {
  access_token: string;
  refresh_token: string;
  expires_at?: string;
  expires_in?: string;
  provider_token?: string;
  provider_refresh_token?: string;
  token_type?: string;
}

// Store captured tokens in memory
let capturedTokens: OAuthTokens | null = null;
let tokensProcessed = false;

/**
 * Capture OAuth tokens from URL hash immediately
 * This should be called as early as possible in the app lifecycle
 */
export const captureOAuthTokens = (): OAuthTokens | null => {
  // Only capture once per page load
  if (capturedTokens || tokensProcessed) {
    return capturedTokens;
  }

  const hash = window.location.hash;

  if (!hash?.includes("access_token")) {
    return null;
  }

  try {
    // Parse tokens from hash
    const hashParams = new URLSearchParams(hash.substring(1));
    const tokens: OAuthTokens = {
      access_token: hashParams.get("access_token") || "",
      refresh_token: hashParams.get("refresh_token") || "",
      expires_at: hashParams.get("expires_at") || undefined,
      expires_in: hashParams.get("expires_in") || undefined,
      provider_token: hashParams.get("provider_token") || undefined,
      provider_refresh_token: hashParams.get("provider_refresh_token") || undefined,
      token_type: hashParams.get("token_type") || undefined,
    };

    // Validate required tokens
    if (!tokens.access_token || !tokens.refresh_token) {
      return null;
    }

    // Store tokens
    capturedTokens = tokens;

    // Clear the hash to prevent it from being processed again
    // but preserve the current path
    const newUrl = window.location.pathname + window.location.search;
    window.history.replaceState({}, document.title, newUrl);

    return capturedTokens;
  } catch (error) {
    console.error("Error capturing OAuth tokens:", error);
    return null;
  }
};

/**
 * Get previously captured tokens
 */
export const getCapturedTokens = (): OAuthTokens | null => {
  return capturedTokens;
};

/**
 * Mark tokens as processed to prevent reuse
 */
export const markTokensAsProcessed = (): void => {
  tokensProcessed = true;
};

/**
 * Check if we have valid captured tokens
 */
export const hasCapturedTokens = (): boolean => {
  return capturedTokens !== null && !tokensProcessed;
};
