import { Check } from "lucide-react";
import type { ReactNode } from "react";
import { useEffect, useRef } from "react";

import { cn } from "@/shared/lib/utils";

import type { WizardControls, WizardStepDef } from "./useWizardState";

interface WizardProps {
  steps: WizardStepDef[];
  controls: WizardControls;
  onComplete?: () => void;
  className?: string;
  children: (controls: WizardControls) => ReactNode;
}

interface StepIndicatorProps {
  steps: WizardStepDef[];
  currentIndex: number;
  completedStepIds: string[];
  skippedStepIds: string[];
  onSelect: (stepId: string) => void;
}

function StepIndicator({
  steps,
  currentIndex,
  completedStepIds,
  skippedStepIds,
  onSelect,
}: StepIndicatorProps) {
  return (
    <ol className="flex items-start gap-2 pb-2">
      {steps.map((step, index) => {
        const isCurrent = index === currentIndex;
        const isCompleted = completedStepIds.includes(step.id);
        const isSkipped = skippedStepIds.includes(step.id);
        const handleClick = () => onSelect(step.id);
        const isLast = index === steps.length - 1;
        return (
          <li key={step.id} className={cn("flex items-start gap-2", !isLast && "flex-1")}>
            <div className="flex shrink-0 flex-col items-center gap-1.5">
              <button
                type="button"
                onClick={handleClick}
                className={cn(
                  "flex h-8 min-w-8 items-center justify-center rounded-full border px-2 text-xs font-medium transition-colors",
                  isCurrent && "border-primary bg-primary text-primary-foreground",
                  !isCurrent && isCompleted && "border-primary/40 bg-primary/10 text-primary",
                  !isCurrent &&
                    !isCompleted &&
                    "border-border bg-card text-muted-foreground hover:text-foreground",
                  isSkipped && !isCompleted && "border-dashed",
                )}
                aria-current={isCurrent ? "step" : undefined}
              >
                {isCompleted ? <Check className="h-3.5 w-3.5" /> : index + 1}
              </button>
              <span
                className={cn(
                  "hidden whitespace-nowrap text-xs sm:inline",
                  isCurrent ? "text-foreground" : "text-muted-foreground",
                )}
              >
                {step.title}
              </span>
            </div>
            {!isLast && <span className="mt-4 h-px flex-1 bg-border" aria-hidden="true" />}
          </li>
        );
      })}
    </ol>
  );
}

export function Wizard({ steps, controls, onComplete, className, children }: WizardProps) {
  const { currentIndex, completedStepIds, skippedStepIds, isComplete, goTo } = controls;
  const completionFired = useRef(false);

  useEffect(() => {
    // Guard against firing onComplete more than once per mount. Without
    // this, a parent re-render that produces a fresh `onComplete` reference
    // can cause repeated navigations and, combined with an empty-state
    // redirect gate, an infinite redirect loop.
    if (isComplete && onComplete && !completionFired.current) {
      completionFired.current = true;
      onComplete();
    }
  }, [isComplete, onComplete]);

  if (isComplete) return null;

  return (
    <div className={cn("flex h-full flex-col gap-6", className)}>
      <StepIndicator
        steps={steps}
        currentIndex={currentIndex}
        completedStepIds={completedStepIds}
        skippedStepIds={skippedStepIds}
        onSelect={goTo}
      />
      <div className="flex-1 overflow-y-auto">{children(controls)}</div>
    </div>
  );
}
