import { useQuery } from "@tanstack/react-query";
import { useMemo } from "react";

import { DataClient } from "@/features/data-sources/api/DataClient";
import type { DemoSourcePreset } from "@/features/data-sources/types";

const DEMO_SOURCES_QUERY_KEY = ["demo-sources"] as const;
const PRESETS_STALE_TIME_MS = 5 * 60 * 1000;

interface UseDemoSourcesReturn {
  presets: DemoSourcePreset[];
  isLoadingPresets: boolean;
  presetsError: Error | null;
}

export function useDemoSources(): UseDemoSourcesReturn {
  const dataClient = useMemo(() => new DataClient(), []);

  const presetsQuery = useQuery({
    queryKey: DEMO_SOURCES_QUERY_KEY,
    queryFn: () => dataClient.loadDemoSources(),
    staleTime: PRESETS_STALE_TIME_MS,
  });

  return {
    presets: presetsQuery.data ?? [],
    isLoadingPresets: presetsQuery.isLoading,
    presetsError: presetsQuery.error,
  };
}
