import type { ConceptData } from "@/features/concepts/api";

export interface ConceptParam {
  name: string;
  defaultValue?: string;
}

/**
 * Matches `@param("name")` / `@param("name","default")` / `@param("name",42)`.
 * The default may be a quoted string (group 2) or a bare literal (group 3).
 */
const PARAM_PATTERN =
  /@param\(\s*"((?:[^"\\]|\\.)*)"\s*(?:,\s*(?:"((?:[^"\\]|\\.)*)"|([^),\s]+)))?\s*\)/g;

/** Parses the raw `@param(...)` annotation block of a concept's source. */
export function parseParamAnnotations(annotations: string | undefined): ConceptParam[] {
  if (!annotations) return [];
  return [...annotations.matchAll(PARAM_PATTERN)].map((match) => ({
    name: match[1],
    defaultValue: match[2] ?? match[3],
  }));
}

/** All params of a concept across its detail entries, deduped by name. */
export function conceptParams(concept: ConceptData): ConceptParam[] {
  const params = (concept.concept_details ?? []).flatMap((detail) =>
    parseParamAnnotations(detail.param_annotations),
  );
  const byName = new Map(params.map((param) => [param.name, param]));
  return [...byName.values()];
}
