import { useEffect, useState } from "react";

/** Below this, secondary actions (Run / New Concept / Search) collapse into a kebab. */
export const NARROW_VIEWPORT_PX = 1280;
/**
 * Ontology carries more (and wider) controls than lineage — compute, the
 * Visual/JSON toggle, Add, Save, Upload and a wide search box — so its toolbar
 * needs to collapse into a kebab at a wider viewport to avoid overrunning the
 * nav tabs.
 */
export const LINEAGE_NARROW_VIEWPORT_PX = 1440;
/** Below this, the nav tabs and machine dropdown also fold into the kebab. */
export const VERY_NARROW_VIEWPORT_PX = 900;

/**
 * Returns true when the available width is below the threshold.
 * `reservedPx` is subtracted from the viewport width — pass the width of any
 * docked panel (e.g. the AI assistant chat) so its space counts against the
 * threshold, since it pushes the page content narrower.
 */
export function useIsNarrowViewport(
  thresholdPx: number = NARROW_VIEWPORT_PX,
  reservedPx = 0,
): boolean {
  const [viewportWidth, setViewportWidth] = useState(() =>
    typeof window === "undefined" ? Number.POSITIVE_INFINITY : window.innerWidth,
  );

  useEffect(() => {
    const update = () => setViewportWidth(window.innerWidth);
    update();
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);

  return viewportWidth - reservedPx < thresholdPx;
}

export function useIsVeryNarrowViewport(reservedPx = 0): boolean {
  return useIsNarrowViewport(VERY_NARROW_VIEWPORT_PX, reservedPx);
}
