import { AlertCircle, Check, Loader2, Upload, X } from "lucide-react";
import { useRef, useState } from "react";

import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

import type { PendingContextUpload } from "../hooks/useContextUpload";

interface CompanyContextUploadPanelProps {
  attachments: PendingContextUpload[];
  onPick: (file: File) => void;
  onRemove: (id: string) => void;
  disabled: boolean;
}

// Subset of types `process_file_from_path` can extract. DOCX is not yet
// supported by the backend extractor — leaving it out of the picker so
// users don't get a confusing 422 after upload.
const ACCEPT = ".pdf,.txt,.md,.csv,.json,.yaml,.yml,.ttl,.rdf,.owl";
const HINT = "PDF, TXT, MD, CSV, JSON, YAML, TTL, RDF, OWL — up to 50 MB";

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

export function CompanyContextUploadPanel({
  attachments,
  onPick,
  onRemove,
  disabled,
}: CompanyContextUploadPanelProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleBrowseClick = () => inputRef.current?.click();

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    for (const file of Array.from(files)) {
      onPick(file);
    }
    // Reset so re-picking the same file re-triggers change.
    e.target.value = "";
  };

  const handleDragOver = (e: React.DragEvent<HTMLButtonElement>) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent<HTMLButtonElement>) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent<HTMLButtonElement>) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;
    const files = e.dataTransfer.files;
    if (!files) return;
    for (const file of Array.from(files)) {
      onPick(file);
    }
  };

  return (
    <div className="space-y-2">
      <h3 className="text-sm font-medium text-foreground">Or upload documents</h3>

      <button
        type="button"
        onClick={handleBrowseClick}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        disabled={disabled}
        className={cn(
          "group flex w-full flex-col items-center justify-center gap-3 rounded-lg border-2 border-dashed bg-primary/[0.03] px-4 py-8 text-sm transition-all focus:outline-none focus:ring-2 focus:ring-primary/40 disabled:cursor-not-allowed disabled:opacity-60",
          isDragging
            ? "border-primary bg-primary/10 text-foreground"
            : "border-primary/30 text-muted-foreground hover:border-primary/60 hover:bg-primary/[0.06] hover:text-foreground",
        )}
      >
        <span
          className={cn(
            "flex h-11 w-11 items-center justify-center rounded-full transition-colors",
            isDragging ? "bg-primary/20" : "bg-primary/10 group-hover:bg-primary/15",
          )}
        >
          <Upload className="h-5 w-5 text-primary" />
        </span>
        <div className="space-y-1">
          <p className="font-medium text-foreground">
            {isDragging ? "Release to upload" : "Drop files here or browse"}
          </p>
          <p className="text-xs text-muted-foreground">{HINT}</p>
        </div>
      </button>

      <input
        ref={inputRef}
        type="file"
        accept={ACCEPT}
        multiple
        onChange={handleFileChange}
        className="hidden"
      />

      {attachments.length > 0 && (
        <ul className="space-y-1.5">
          {attachments.map((a) => (
            <UploadChip key={a.id} attachment={a} onRemove={onRemove} disabled={disabled} />
          ))}
        </ul>
      )}
    </div>
  );
}

interface UploadChipProps {
  attachment: PendingContextUpload;
  onRemove: (id: string) => void;
  disabled: boolean;
}

function UploadChip({ attachment, onRemove, disabled }: UploadChipProps) {
  const handleRemove = () => onRemove(attachment.id);

  return (
    <li className="flex items-center gap-2 rounded-md border border-border bg-card px-2.5 py-1.5 text-xs">
      <StatusIcon attachment={attachment} />
      <span className="flex-1 truncate text-foreground">{attachment.fileName}</span>
      <span className="text-muted-foreground">{formatBytes(attachment.fileSize)}</span>
      {attachment.error && (
        <span
          className="max-w-[180px] truncate text-red-600 dark:text-red-400"
          title={attachment.error}
        >
          {attachment.error}
        </span>
      )}
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="h-6 w-6"
        onClick={handleRemove}
        disabled={disabled}
        aria-label={`Remove ${attachment.fileName}`}
      >
        <X className="h-3.5 w-3.5" />
      </Button>
    </li>
  );
}

function StatusIcon({ attachment }: { attachment: PendingContextUpload }) {
  if (attachment.isUploading) {
    return <Loader2 className="h-3.5 w-3.5 shrink-0 animate-spin text-muted-foreground" />;
  }
  if (attachment.error) {
    return <AlertCircle className="h-3.5 w-3.5 shrink-0 text-red-600 dark:text-red-400" />;
  }
  return <Check className="h-3.5 w-3.5 shrink-0 text-green-600 dark:text-green-400" />;
}
