import { Check, Folder, Globe, Lightbulb, X } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { ContextNoteApi } from "@/features/context-layer/api";
import type { ContextKind, ContextScope } from "@/features/context-layer/types";
import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

import type { WriterProposalData, WriterProposalState } from "../store";

interface WriterProposalCardProps {
  proposal: WriterProposalData;
  state: WriterProposalState;
  onResolve: (state: WriterProposalState) => void;
}

export function WriterProposalCard({ proposal, state, onResolve }: WriterProposalCardProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [scope, setScope] = useState<ContextScope>(proposal.scope as ContextScope);

  const supersedes = proposal.supersedes ?? [];
  const supersedeIds = supersedes.map((s) => s.id);
  const ontologyAvailable = Boolean(proposal.ontology_id);
  const proposalTitle = proposal.title?.trim() ?? "";

  const handleSave = async () => {
    if (isSubmitting || state !== "pending") return;
    setIsSubmitting(true);
    try {
      await ContextNoteApi.create({
        scope,
        scope_id: scope === "ontology" ? (proposal.ontology_id ?? null) : null,
        kind: proposal.kind as ContextKind,
        title: proposalTitle || undefined,
        text: proposal.text,
        // Supersede ids that don't match the chosen scope would be rejected
        // server-side; the writer only ever returns supersedes within its
        // proposed scope, so re-scoping clears them.
        supersedes: supersedeIds.length > 0 && scope === proposal.scope ? supersedeIds : undefined,
      });
      onResolve("saved");
      toast.success(
        supersedeIds.length > 0 && scope === proposal.scope
          ? `Saved to your Context Layer (replaced ${supersedeIds.length} older note${supersedeIds.length === 1 ? "" : "s"})`
          : "Saved to your Context Layer",
      );
    } catch (err) {
      const message = err instanceof Error ? err.message : "Unknown error";
      toast.error(`Could not save note: ${message}`);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDismiss = () => {
    if (state !== "pending") return;
    onResolve("dismissed");
  };

  const isPending = state === "pending";
  const handleScopeOntology = () => setScope("ontology");
  const handleScopeGlobal = () => setScope("global");

  return (
    <div
      className={cn(
        "rounded-md border border-border bg-card p-3 text-sm",
        state === "saved" && "border-primary/40 bg-primary/5",
        state === "dismissed" && "opacity-60",
      )}
    >
      <header className="flex flex-wrap items-center gap-2 pb-1.5 text-xs text-muted-foreground">
        <Lightbulb className="h-3.5 w-3.5 text-primary" />
        <span className="font-medium uppercase tracking-wide">{proposal.kind}</span>
        <span aria-hidden>·</span>
        {isPending && ontologyAvailable ? (
          <div className="inline-flex items-center gap-0.5 rounded border border-border bg-background/60 p-0.5">
            <button
              type="button"
              onClick={handleScopeOntology}
              className={cn(
                "inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide transition-colors",
                scope === "ontology"
                  ? "bg-primary text-primary-foreground"
                  : "text-muted-foreground hover:text-foreground",
              )}
            >
              <Folder className="h-3 w-3" />
              project
            </button>
            <button
              type="button"
              onClick={handleScopeGlobal}
              className={cn(
                "inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide transition-colors",
                scope === "global"
                  ? "bg-primary text-primary-foreground"
                  : "text-muted-foreground hover:text-foreground",
              )}
            >
              <Globe className="h-3 w-3" />
              global
            </button>
          </div>
        ) : (
          <span>{scope}</span>
        )}
        <span aria-hidden>·</span>
        <span>Save to Context Layer?</span>
      </header>
      {proposalTitle && <p className="pb-0.5 font-medium text-foreground">{proposalTitle}</p>}
      <p className="whitespace-pre-wrap text-foreground">{proposal.text}</p>
      {supersedes.length > 0 && (
        <div className="mt-2 rounded border border-border bg-muted/40 p-2 text-xs">
          <div className="pb-1 font-medium text-muted-foreground">
            Will replace your previous note{supersedes.length === 1 ? "" : "s"}:
          </div>
          <ul className="space-y-1">
            {supersedes.map((s) => (
              <li key={s.id} className="flex items-start gap-1.5 text-foreground/80">
                <span className="rounded bg-muted px-1.5 py-0.5 text-[10px] uppercase tracking-wide text-muted-foreground">
                  {s.kind}
                </span>
                <span className="line-through">{s.text}</span>
              </li>
            ))}
          </ul>
        </div>
      )}
      {state === "pending" && (
        <footer className="mt-3 flex justify-end gap-2">
          <Button type="button" variant="ghost" size="sm" onClick={handleDismiss}>
            <X className="mr-1 h-3.5 w-3.5" />
            Dismiss
          </Button>
          <Button type="button" size="sm" onClick={handleSave} disabled={isSubmitting}>
            <Check className="mr-1 h-3.5 w-3.5" />
            Save
          </Button>
        </footer>
      )}
      {state === "saved" && (
        <footer className="mt-2 inline-flex items-center gap-1.5 text-xs text-primary">
          <Check className="h-3.5 w-3.5" />
          Saved to Context Layer
        </footer>
      )}
      {state === "dismissed" && (
        <footer className="mt-2 inline-flex items-center gap-1.5 text-xs text-muted-foreground">
          <X className="h-3.5 w-3.5" />
          Dismissed
        </footer>
      )}
    </div>
  );
}
