import { Activity, BarChart3, Brain, Database, HardDrive, Rocket, Server } from "lucide-react";
import type React from "react";

export interface Machine {
  id: string;
  name: string;
  type: string;
  category: string | null;
  cores: number;
  memory_gb: number;
  cost_per_machine: number;
  ami?: string;
  created_at: string | null;
  updated_at: string | null;
}

export interface CurrentSession {
  id: string;
  started_at: string;
  stopped_at: string | null;
  duration_minutes: number | null;
  current_duration_minutes?: number;
}

export interface UserMachine {
  id: string;
  user_id: string;
  machine_id: string;
  node_group_id: string | null;
  status: "Requested" | "Enabled" | "Disabled";
  requested_at: string | null;
  enabled_at: string | null;
  disabled_at: string | null;
  created_at: string | null;
  is_default: boolean;
  is_active: boolean;
  for_compute: boolean;
  last_started_at: string | null;
  last_stopped_at: string | null;
  total_usage_minutes?: number;
  free_minutes_remaining?: number;
  current_session?: CurrentSession;
  current_session_cost_usd?: number;
  autotermination_minutes?: number | null;
  machines?: Machine;
}

export interface AvailabilityResult {
  status: "success" | "error";
  message: string;
  is_available?: boolean;
  machine_status?:
    | "started"
    | "stopped"
    | "stopping"
    | "pending"
    | "starting"
    | "crashed"
    | "restarting";
  pod_info?: any;
  metrics?: any;
}

export const SimpleIcon: React.FC<{
  iconData: any;
  size: number;
  className?: string;
}> = ({ iconData, size, className }) => {
  if (!iconData) return null;

  return (
    <svg
      role="img"
      viewBox="0 0 24 24"
      width={size}
      height={size}
      className={className}
      fill={`#${iconData.hex}`}
      xmlns="http://www.w3.org/2000/svg"
    >
      <title>{iconData.title}</title>
      <path d={iconData.path} />
    </svg>
  );
};

export const getCategoryIcon = (category: string | null) => {
  switch (category) {
    case "burstable":
      return <Activity className="w-5 h-5 text-orange-600 dark:text-orange-400" />;
    case "compute_optimized":
      return <Rocket className="w-5 h-5 text-red-600 dark:text-red-400" />;
    case "general_purpose":
      return <BarChart3 className="w-5 h-5 text-blue-600 dark:text-blue-400" />;
    case "memory_optimized":
      return <HardDrive className="w-5 h-5 text-purple-600 dark:text-purple-400" />;
    case "storage_optimized":
      return <Database className="w-5 h-5 text-green-600 dark:text-green-400" />;
    case "gpu":
      return <Brain className="w-5 h-5 text-pink-600 dark:text-pink-400" />;
    default:
      return <Server className="w-5 h-5 text-gray-600 dark:text-gray-400" />;
  }
};

export const getCategoryColor = (category: string | null) => {
  switch (category) {
    case "burstable":
      return "border-orange-200 dark:border-orange-800 bg-orange-50 dark:bg-orange-900/10";
    case "compute_optimized":
      return "border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/10";
    case "general_purpose":
      return "border-blue-200 dark:border-blue-800 bg-blue-50 dark:bg-blue-900/10";
    case "memory_optimized":
      return "border-purple-200 dark:border-purple-800 bg-purple-50 dark:bg-purple-900/10";
    case "storage_optimized":
      return "border-green-200 dark:border-green-800 bg-green-50 dark:bg-green-900/10";
    case "gpu":
      return "border-pink-200 dark:border-pink-800 bg-pink-50 dark:bg-pink-900/10";
    default:
      return "border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900/10";
  }
};

export const getCategoryDisplayName = (category: string | null) => {
  const base = category?.replace(/_ondemand$/, "") ?? null;
  switch (base) {
    case "burstable":
      return "Burstable";
    case "compute_optimized":
      return "Compute Optimized";
    case "general_purpose":
      return "General Purpose";
    case "memory_optimized":
      return "Memory Optimized";
    case "storage_optimized":
      return "Storage Optimized";
    case "gpu":
      return "GPU Accelerated";
    default:
      return "Uncategorized";
  }
};

export interface CategoryGroup {
  category: string;
  displayName: string;
  machines: Machine[];
  ondemandMachines: Machine[];
}

const CATEGORY_ORDER = [
  "general_purpose",
  "compute_optimized",
  "memory_optimized",
  "storage_optimized",
  "gpu",
  "burstable",
  "uncategorized",
];

export const groupMachinesByCategory = (machines: Machine[]): CategoryGroup[] => {
  const reserved: Record<string, Machine[]> = {};
  const ondemand: Record<string, Machine[]> = {};

  for (const machine of machines) {
    const raw = machine.category || "uncategorized";
    const isOndemand = raw.endsWith("_ondemand");
    const baseCategory = isOndemand ? raw.replace(/_ondemand$/, "") : raw;
    const target = isOndemand ? ondemand : reserved;
    if (!target[baseCategory]) target[baseCategory] = [];
    target[baseCategory].push(machine);
  }

  const allBaseCategories = new Set([...Object.keys(reserved), ...Object.keys(ondemand)]);
  const sorted = [...allBaseCategories].sort((a, b) => {
    const indexA = CATEGORY_ORDER.indexOf(a);
    const indexB = CATEGORY_ORDER.indexOf(b);
    return (
      (indexA === -1 ? CATEGORY_ORDER.length : indexA) -
      (indexB === -1 ? CATEGORY_ORDER.length : indexB)
    );
  });

  const byCost = (a: Machine, b: Machine) => a.cost_per_machine - b.cost_per_machine;

  return sorted.map((category) => ({
    category,
    displayName: getCategoryDisplayName(category),
    machines: [...(reserved[category] || [])].sort(byCost),
    ondemandMachines: [...(ondemand[category] || [])].sort(byCost),
  }));
};

export const groupUserMachinesByCategory = (userMachines: UserMachine[]) => {
  const machines = userMachines.map((um) => um.machines).filter(Boolean) as Machine[];
  return groupMachinesByCategory(machines);
};

export const MACHINES_PER_CATEGORY = 6;
