import { useEffect } from "react";
import { DatabricksConfigService } from "@/features/compute/api/databricksService";
import type { DatabricksConfig } from "@/features/compute/types";

/**
 * On mount, take on the Databricks config the backend holds for this user.
 *
 * The settings form seeds its state from localStorage, which a config set
 * through the assistant or over MCP never reaches. This pulls that config in
 * once, writes it to localStorage like any other, and hands it to `apply` so
 * the form shows it without waiting for a reload.
 *
 * `apply` must be stable across renders — a `setState` setter is.
 */
export function useDatabricksSessionHydration(apply: (config: DatabricksConfig) => void): void {
  useEffect(() => {
    let cancelled = false;

    void DatabricksConfigService.hydrateFromBackend().then((config) => {
      if (cancelled || !config) {
        return;
      }
      apply(config);
    });

    return () => {
      cancelled = true;
    };
  }, [apply]);
}
