import { ArrowRight, Loader2 } from "lucide-react";
import type { OntologyScope, SnapshotDiffSource } from "@/features/ontologies/api";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import { ConceptDiffCard } from "./ConceptDiffCard";
import { singleConceptFieldDiffs } from "./snapshotDiff.utils";
import { useSnapshotDiff } from "./useSnapshotDiff";

interface SnapshotDiffDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  ontologyId: string | null;
  scope: OntologyScope;
  baseSource: SnapshotDiffSource | null;
  targetSource: SnapshotDiffSource | null;
  baseLabel: string;
  targetLabel: string;
}

export function SnapshotDiffDialog({
  open,
  onOpenChange,
  ontologyId,
  scope,
  baseSource,
  targetSource,
  baseLabel,
  targetLabel,
}: SnapshotDiffDialogProps) {
  const { diff, isLoading, error } = useSnapshotDiff({
    ontologyId,
    scope,
    baseSource,
    targetSource,
  });

  const hasChanges =
    diff !== null && (diff.changed.length > 0 || diff.added.length > 0 || diff.removed.length > 0);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[85vh] w-full max-w-3xl flex-col">
        <DialogHeader>
          <DialogTitle>Compare concepts</DialogTitle>
          <DialogDescription asChild>
            <div className="flex items-center gap-2 text-xs">
              <span className="rounded bg-muted px-1.5 py-0.5 font-medium text-foreground">
                {baseLabel}
              </span>
              <ArrowRight className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
              <span className="rounded bg-muted px-1.5 py-0.5 font-medium text-foreground">
                {targetLabel}
              </span>
            </div>
          </DialogDescription>
        </DialogHeader>

        <div className="-mx-1 flex-1 space-y-3 overflow-y-auto px-1">
          {isLoading && (
            <div className="flex items-center justify-center gap-2 py-10 text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" />
              <span className="text-sm">Loading concepts…</span>
            </div>
          )}

          {!isLoading && error && (
            <p className="py-10 text-center text-sm text-destructive">
              Failed to load concepts for comparison.
            </p>
          )}

          {!isLoading && !error && !hasChanges && (
            <p className="py-10 text-center text-sm text-muted-foreground">
              No concept changes between these versions.
            </p>
          )}

          {!isLoading && !error && diff && (
            <>
              {diff.changed.map((concept) => (
                <ConceptDiffCard
                  key={`changed-${concept.predicateName}`}
                  status="changed"
                  predicateName={concept.predicateName}
                  fieldDiffs={concept.fieldDiffs}
                />
              ))}
              {diff.added.map((concept) => (
                <ConceptDiffCard
                  key={`added-${concept.predicate_name}`}
                  status="added"
                  predicateName={concept.predicate_name}
                  fieldDiffs={singleConceptFieldDiffs(concept, "added")}
                />
              ))}
              {diff.removed.map((concept) => (
                <ConceptDiffCard
                  key={`removed-${concept.predicate_name}`}
                  status="removed"
                  predicateName={concept.predicate_name}
                  fieldDiffs={singleConceptFieldDiffs(concept, "removed")}
                />
              ))}
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}
