import {
  autocompletion,
  type Completion,
  type CompletionContext,
  type CompletionResult,
} from "@codemirror/autocomplete";
import type { Extension } from "@codemirror/state";
import type { EditorView } from "@codemirror/view";

export interface WikilinkCandidate {
  id: string;
  title: string;
}

/** Insert `Title]]`, consuming any auto-closed `]` already after the
 *  cursor (typing `[[` auto-inserts `]]`, so a plain string apply would
 *  produce `[[Title]]]]`). */
function applyWikilink(title: string) {
  return (view: EditorView, _completion: Completion, from: number, to: number) => {
    const doc = view.state.doc;
    let end = to;
    while (end < doc.length && end - to < 2 && doc.sliceString(end, end + 1) === "]") {
      end += 1;
    }
    const insert = `${title}]]`;
    view.dispatch({
      changes: { from, to: end, insert },
      selection: { anchor: from + insert.length },
      userEvent: "input.complete",
    });
  };
}

/**
 * `[[` autocompletes over note titles. Selecting a title inserts
 * `Title]]`; the structured `context_edges` row is written on save
 * (wikilinks are the authoring gesture, edges are the storage).
 *
 * Candidates are read through a getter so the extension survives
 * note-list refetches without rebuilding the editor state.
 */
export function wikilinkCompletion(getCandidates: () => WikilinkCandidate[]): Extension {
  const source = (context: CompletionContext): CompletionResult | null => {
    const match = context.matchBefore(/\[\[([^\][\n]*)$/);
    if (!match) return null;
    const options = getCandidates().map((candidate) => ({
      label: candidate.title,
      type: "text",
      apply: applyWikilink(candidate.title),
    }));
    return { from: match.from + 2, options, validFor: /^[^\][\n]*$/ };
  };
  return autocompletion({ override: [source] });
}
