import { AppWindow, Calendar, Download, Settings, Trash2 } from "lucide-react";
import type React from "react";
import { Link } from "react-router-dom";
import type { DashboardListItem } from "../../api/DashboardClient";
import { PUBLISHING_UI_ENABLED } from "../../publishing";

export interface DashboardCardProps {
  item: DashboardListItem;
  onEdit?: (e: React.MouseEvent) => void;
  onExport: (e: React.MouseEvent) => void;
  onDelete?: (e: React.MouseEvent) => void;
}

export function DashboardCard({
  item,
  onEdit = undefined,
  onExport,
  onDelete = undefined,
}: DashboardCardProps) {
  const created = new Date(item.createdAt).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });

  return (
    <Link
      to={`/apps/${item.ontologyId}/${item.id}`}
      className="group relative text-left bg-card border border-border rounded-xl p-5 hover:border-foreground/30 hover:shadow-sm transition-all duration-150 flex flex-col gap-3 no-underline"
    >
      <div className="absolute top-3 right-3 flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
        <div
          role="button"
          tabIndex={0}
          onClick={onExport}
          onKeyDown={(e) => {
            if (e.key === "Enter") onExport(e as unknown as React.MouseEvent);
          }}
          className="p-1.5 rounded-md text-muted-foreground/40 hover:text-foreground hover:bg-secondary transition-colors"
          title="Export app"
        >
          <Download className="h-3.5 w-3.5" />
        </div>
        {onEdit && (
          <div
            role="button"
            tabIndex={0}
            onClick={onEdit}
            onKeyDown={(e) => {
              if (e.key === "Enter") onEdit(e as unknown as React.MouseEvent);
            }}
            className="p-1.5 rounded-md text-muted-foreground/40 hover:text-foreground hover:bg-secondary transition-colors"
            title="Edit app"
          >
            <Settings className="h-3.5 w-3.5" />
          </div>
        )}
        {onDelete && (
          <div
            role="button"
            tabIndex={0}
            onClick={onDelete}
            onKeyDown={(e) => {
              if (e.key === "Enter") onDelete(e as unknown as React.MouseEvent);
            }}
            className="p-1.5 rounded-md text-muted-foreground/40 hover:text-destructive hover:bg-secondary transition-colors"
            title="Delete app"
          >
            <Trash2 className="h-3.5 w-3.5" />
          </div>
        )}
      </div>

      <div className="flex items-start gap-3">
        <div className="w-9 h-9 rounded-lg bg-secondary flex items-center justify-center flex-shrink-0 group-hover:bg-secondary/70 transition-colors overflow-hidden">
          {item.logoUrl ? (
            <img src={item.logoUrl} alt="" className="w-full h-full object-contain p-1" />
          ) : (
            <AppWindow className="h-4 w-4 text-foreground/60" />
          )}
        </div>
        <div className="min-w-0 flex-1 overflow-hidden">
          <div className="font-semibold text-[14px] text-foreground leading-tight truncate pr-6">
            {item.name}
          </div>
          <div className="text-[11px] text-muted-foreground mt-0.5 truncate">
            {item.ontologyName}
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between border-t border-border/60 pt-3">
        <span className="flex items-center gap-2 min-w-0">
          {PUBLISHING_UI_ENABLED && item.status === "published" && (
            <span className="text-[10px] px-1.5 py-px rounded-full bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-400 flex-shrink-0">
              Published
            </span>
          )}
          {PUBLISHING_UI_ENABLED && item.status !== "published" && (
            <span className="text-[10px] px-1.5 py-px rounded-full bg-secondary text-muted-foreground flex-shrink-0">
              Draft
            </span>
          )}
          <span className="text-[12px] text-muted-foreground truncate">{item.author}</span>
        </span>
        <span className="flex items-center gap-1 text-[11px] text-muted-foreground/60 flex-shrink-0">
          <Calendar className="h-3 w-3" />
          {created}
        </span>
      </div>
    </Link>
  );
}
