import { ArrowDown, ArrowUp, Filter, MoreVertical } from "lucide-react";
import { useEffect, useState } from "react";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";
import { cn } from "@/shared/lib/utils";
import { FilterSection, MainMenu, OrderSection } from "./ColumnFilterSections";
import type { ColumnFilterValue, FilterOperator } from "./tableOutput.types";
import { operatorNeedsValue } from "./tableOutput.utils";

interface ColumnFilterPopoverProps {
  columnIndex: number;
  columnName: string;
  currentFilter?: ColumnFilterValue;
  currentSortDirection: "asc" | "desc" | null;
  onApplyFilter: (columnIndex: number, value: string, operator: FilterOperator) => void;
  onClearFilter: (columnIndex: number) => void;
  onSort: (columnIndex: number, direction: "asc" | "desc" | null) => void;
}

type Section = "main" | "filter" | "order";

export function ColumnFilterPopover({
  columnIndex,
  columnName,
  currentFilter,
  currentSortDirection,
  onApplyFilter,
  onClearFilter,
  onSort,
}: ColumnFilterPopoverProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [section, setSection] = useState<Section>("main");
  const [operator, setOperator] = useState<FilterOperator>(currentFilter?.operator ?? "contains");
  const [value, setValue] = useState<string>(currentFilter?.value ?? "");

  const isFiltered = !!currentFilter;
  const needsValue = operatorNeedsValue(operator);
  const hasActiveState = isFiltered || !!currentSortDirection;

  useEffect(() => {
    if (!isOpen) return;
    setOperator(currentFilter?.operator ?? "contains");
    setValue(currentFilter?.value ?? "");
    setSection("main");
  }, [isOpen, currentFilter]);

  const handleApply = (e: React.FormEvent) => {
    e.preventDefault();
    if (needsValue && !value.trim()) return;
    onApplyFilter(columnIndex, needsValue ? value.trim() : "", operator);
    setIsOpen(false);
  };

  const handleClear = () => {
    onClearFilter(columnIndex);
    setValue("");
    setOperator("contains");
    setIsOpen(false);
  };

  const handleSort = (direction: "asc" | "desc" | null) => {
    onSort(columnIndex, direction);
    setIsOpen(false);
  };

  return (
    <Popover open={isOpen} onOpenChange={setIsOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          title={`Options for ${columnName}`}
          className={cn(
            "ml-1 p-0.5 rounded hover:bg-muted transition-colors inline-flex items-center justify-center gap-0.5",
            hasActiveState && "text-blue-600 bg-blue-50 dark:bg-blue-900/30",
          )}
        >
          {isFiltered && <Filter className="h-2.5 w-2.5 text-blue-600" />}
          {currentSortDirection === "asc" && <ArrowUp className="h-2.5 w-2.5 text-blue-600" />}
          {currentSortDirection === "desc" && <ArrowDown className="h-2.5 w-2.5 text-blue-600" />}
          <MoreVertical className="h-3.5 w-3.5" />
        </button>
      </PopoverTrigger>
      <PopoverContent className="w-56 p-0" align="start">
        {section === "main" && (
          <MainMenu
            isFiltered={isFiltered}
            currentSortDirection={currentSortDirection}
            onPickFilter={() => setSection("filter")}
            onPickOrder={() => setSection("order")}
          />
        )}
        {section === "filter" && (
          <FilterSection
            columnName={columnName}
            operator={operator}
            value={value}
            isFiltered={isFiltered}
            currentFilter={currentFilter}
            needsValue={needsValue}
            onBack={() => setSection("main")}
            onChangeOperator={setOperator}
            onChangeValue={setValue}
            onSubmit={handleApply}
            onClear={handleClear}
          />
        )}
        {section === "order" && (
          <OrderSection
            currentSortDirection={currentSortDirection}
            onBack={() => setSection("main")}
            onSort={handleSort}
          />
        )}
      </PopoverContent>
    </Popover>
  );
}
