import { Plus } from "lucide-react";
import type React from "react";
import { useCallback, useState } from "react";
import { Button } from "@/shared/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/shared/components/ui/dialog";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import type { CreateTokenInput } from "./apiKeys.types";
import { EXPIRY_PRESET_OPTIONS, type ExpiryPreset, presetToMinutes } from "./apiKeys.utils";

interface ApiKeyDialogProps {
  onCreateKey: (input: CreateTokenInput) => Promise<unknown>;
  isCreating: boolean;
}

interface FormState {
  name: string;
  expiry: ExpiryPreset;
  error: string | null;
}

const INITIAL_FORM: FormState = { name: "", expiry: "30d", error: null };

export const ApiKeyDialog: React.FC<ApiKeyDialogProps> = ({ onCreateKey, isCreating }) => {
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState<FormState>(INITIAL_FORM);

  const resetForm = useCallback(() => {
    setForm(INITIAL_FORM);
  }, []);

  const handleOpenChange = useCallback(
    (nextOpen: boolean) => {
      if (isCreating) return;
      setOpen(nextOpen);
      if (!nextOpen) resetForm();
    },
    [isCreating, resetForm],
  );

  const handleNameChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    setForm((prev) => ({ ...prev, name: value, error: null }));
  }, []);

  const handleExpiryChange = useCallback((value: string) => {
    setForm((prev) => ({ ...prev, expiry: value as ExpiryPreset }));
  }, []);

  const handleSubmit = useCallback(
    async (event: React.FormEvent) => {
      event.preventDefault();

      const trimmedName = form.name.trim();
      if (!trimmedName) {
        setForm((prev) => ({ ...prev, error: "Please enter a name for your API key" }));
        return;
      }
      if (trimmedName.length > 120) {
        setForm((prev) => ({ ...prev, error: "Name must be 120 characters or fewer" }));
        return;
      }

      try {
        await onCreateKey({
          name: trimmedName,
          expiresInMinutes: presetToMinutes(form.expiry),
        });
        setOpen(false);
        resetForm();
      } catch (err) {
        setForm((prev) => ({
          ...prev,
          error: err instanceof Error ? err.message : "Failed to create API key",
        }));
      }
    },
    [form.name, form.expiry, onCreateKey, resetForm],
  );

  const handleCancel = useCallback(() => {
    handleOpenChange(false);
  }, [handleOpenChange]);

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogTrigger asChild>
        <Button>
          <Plus className="h-4 w-4 mr-2" />
          Create API Key
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>Create New API Key</DialogTitle>
            <DialogDescription>
              Create a new API key to access the Prometheux API. Give it a descriptive name and
              choose how long it should remain valid.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="key-name">Name</Label>
              <Input
                id="key-name"
                placeholder="e.g., Production App, CI pipeline, My laptop"
                value={form.name}
                onChange={handleNameChange}
                disabled={isCreating}
                maxLength={120}
                autoFocus
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="key-expiry">Expires</Label>
              <Select value={form.expiry} onValueChange={handleExpiryChange} disabled={isCreating}>
                <SelectTrigger id="key-expiry">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {EXPIRY_PRESET_OPTIONS.map((option) => (
                    <SelectItem key={option.value} value={option.value}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {form.error && <div className="text-sm text-destructive">{form.error}</div>}
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={handleCancel} disabled={isCreating}>
              Cancel
            </Button>
            <Button type="submit" disabled={isCreating || !form.name.trim()}>
              {isCreating ? (
                <>
                  <PrometheuxSpinner size={16} className="mr-2" />
                  Creating...
                </>
              ) : (
                "Create Key"
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};
