import { useMemo } from "react";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import type { LineageCardActions } from "../components/ConceptCardNode";

interface UseConceptCardActionsInput {
  onRename: LineageCardActions["onRename"];
  onDelete: LineageCardActions["onDelete"];
  onManagePermissions: (conceptName: string) => void;
  /** Whether the caller may manage concept permissions (project owner / team admin). */
  canManage: boolean;
}

// Builds the memoized card-action bundle handed to each lineage node via
// LineageCardActionsContext. Concept permissions are a teams-governance feature,
// so the "Permissions" menu item is gated behind can_see_teams here — keeping
// that policy out of the already-large LineageView component.
export function useConceptCardActions({
  onRename,
  onDelete,
  onManagePermissions,
  canManage,
}: UseConceptCardActionsInput): LineageCardActions {
  const canSeeTeams = usePermissionsStore((s) => s.canSee("can_see_teams"));
  return useMemo(
    () => ({
      onRename,
      onDelete,
      onManagePermissions,
      canManagePermissions: canManage && canSeeTeams,
    }),
    [onRename, onDelete, onManagePermissions, canManage, canSeeTeams],
  );
}
