import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";
import { cn } from "@/shared/lib/utils";
import type { ResolvedStep } from "../gettingStarted.types";
import { useGettingStartedUiStore } from "../gettingStartedUiStore";
import { useGettingStarted } from "../hooks/useGettingStarted";
import { GettingStartedPopover } from "./GettingStartedPopover";
import { ProgressRing } from "./ProgressRing";

interface GettingStartedWidgetProps {
  collapsed: boolean;
}

export function GettingStartedWidget({ collapsed }: GettingStartedWidgetProps) {
  const navigate = useNavigate();
  const open = useGettingStartedUiStore((s) => s.open);
  const setOpen = useGettingStartedUiStore((s) => s.setOpen);
  const {
    steps,
    completedCount,
    total,
    isVisible,
    shouldAutoOpen,
    markAutoOpened,
    markDone,
    dismiss,
  } = useGettingStarted();

  // Open the checklist by default on the very first load for a brand-new user.
  // The "auto-opened" flag is persisted (see gettingStartedStorage) so it fires
  // once ever; the open state itself lives in a store so it survives the
  // per-route remounts of the sidebar instead of blinking shut.
  useEffect(() => {
    if (!shouldAutoOpen) return;
    markAutoOpened();
    setOpen(true);
  }, [shouldAutoOpen, markAutoOpened, setOpen]);

  if (!isVisible) return null;

  const handleSelect = (step: ResolvedStep) => {
    setOpen(false);
    if (step.manual) markDone(step.id);
    if (step.external) {
      window.open(step.route, "_blank", "noopener,noreferrer");
      return;
    }
    navigate(step.route, step.navState ? { state: step.navState } : undefined);
  };

  const handleSkip = () => {
    setOpen(false);
    dismiss();
  };

  return (
    <div className="border-b py-2">
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <button
            type="button"
            title={collapsed ? "Getting started" : undefined}
            className={cn(
              "flex h-9 w-full items-center gap-3 px-3 text-sm font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground",
              collapsed && "justify-center px-0",
            )}
          >
            <ProgressRing completed={completedCount} total={total} />
            {!collapsed && <span className="truncate">Getting started</span>}
            {!collapsed && (
              <span className="ml-auto text-xs text-muted-foreground">
                {completedCount}/{total}
              </span>
            )}
          </button>
        </PopoverTrigger>
        <PopoverContent side="right" align="end" sideOffset={8} className="w-80 p-0">
          <GettingStartedPopover
            steps={steps}
            completedCount={completedCount}
            total={total}
            onSelect={handleSelect}
            onSkip={handleSkip}
          />
        </PopoverContent>
      </Popover>
    </div>
  );
}
