import type {
  ActuatorMetric,
  HealthStatus,
  SparkApplication,
  SparkJob,
  TaskTotals,
} from "../types/engineMonitor.types";

const BYTE_UNITS = ["B", "KB", "MB", "GB", "TB"] as const;

export function parseSparkTime(raw: string | number | undefined | null): Date | null {
  if (raw === undefined || raw === null) return null;
  if (typeof raw === "number") {
    const d = new Date(raw);
    return Number.isNaN(d.getTime()) ? null : d;
  }
  const normalized = raw.endsWith("GMT") ? raw.replace("GMT", "+00:00") : raw;
  const d = new Date(normalized);
  return Number.isNaN(d.getTime()) ? null : d;
}

export function formatBytes(bytes: number | undefined | null): string {
  if (!bytes || bytes <= 0) return "0 B";
  const i = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), BYTE_UNITS.length - 1);
  const value = bytes / 1024 ** i;
  return `${value.toFixed(2)} ${BYTE_UNITS[i]}`;
}

export function formatUptime(startDate: Date | null, now: Date = new Date()): string {
  if (!startDate) return "—";
  const deltaMs = Math.max(0, now.getTime() - startDate.getTime());
  const totalSeconds = Math.floor(deltaMs / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  if (hours > 0) return `${hours}h ${minutes}m ${seconds}s`;
  if (minutes > 0) return `${minutes}m ${seconds}s`;
  return `${seconds}s`;
}

export function formatAbsoluteTime(date: Date | null): string {
  if (!date) return "—";
  return date.toLocaleString();
}

export function computeTaskTotals(jobs: SparkJob[]): TaskTotals {
  return jobs.reduce<TaskTotals>(
    (acc, job) => {
      acc.total += job.numTasks ?? 0;
      acc.running += job.numActiveTasks ?? 0;
      acc.completed += job.numCompletedTasks ?? 0;
      acc.failed += job.numFailedTasks ?? 0;
      return acc;
    },
    { total: 0, running: 0, completed: 0, failed: 0 },
  );
}

export function getPrimaryAttempt(application: SparkApplication | undefined) {
  if (!application?.attempts || application.attempts.length === 0) return null;
  return application.attempts[0];
}

export function extractMetricValue(metric: ActuatorMetric | null): number | null {
  if (!metric || !Array.isArray(metric.measurements)) return null;
  const valueMeasurement = metric.measurements.find((m) => m.statistic === "VALUE");
  const measurement = valueMeasurement ?? metric.measurements[0];
  if (!measurement || typeof measurement.value !== "number") return null;
  if (!Number.isFinite(measurement.value)) return null;
  return measurement.value;
}

export function formatCpuPercent(cpu: number | null): string {
  if (cpu === null) return "—";
  return `${(cpu * 100).toFixed(1)}%`;
}

export function healthBadgeClass(status: HealthStatus | undefined): string {
  switch (status) {
    case "UP":
      return "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400";
    case "DOWN":
      return "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400";
    case "OUT_OF_SERVICE":
      return "bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400";
    default:
      return "bg-muted text-muted-foreground";
  }
}

export function jobStatusBadgeClass(status: string): string {
  const normalized = status.toUpperCase();
  if (normalized === "RUNNING") {
    return "bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400";
  }
  if (normalized === "SUCCEEDED" || normalized === "COMPLETE") {
    return "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400";
  }
  if (normalized === "FAILED") {
    return "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400";
  }
  return "bg-muted text-muted-foreground";
}
