import {
  AlertCircle,
  AlertTriangle,
  ArrowRightLeft,
  Ban,
  CheckCircle,
  Cpu,
  DollarSign,
  ExternalLink,
  MemoryStick,
  Plus,
  Power,
  RefreshCw,
  Server,
  Trash2,
  Zap,
} from "lucide-react";
import React from "react";
import { Alert, AlertDescription } from "@/shared/components/ui/alert";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/shared/components/ui/alert-dialog";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "@/shared/components/ui/card";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import type { AvailabilityResult, Machine, UserMachine } from "../utils";
import { getCategoryDisplayName, groupMachinesByCategory } from "../utils";

interface SnowflakePoolsTabContentProps {
  availableMachines: Machine[];
  userMachines: UserMachine[];
  currentPool: string;
  loading: boolean;
  error: string | null;
  isRequesting: boolean;
  checkingStatus: Record<string, boolean>;
  availabilityResults: Record<string, AvailabilityResult>;
  onRefresh: () => Promise<void>;
  onUsePool: (instanceFamily: string) => Promise<{ success: boolean }>;
  onToggleActive: (
    poolName: string,
    instanceFamily: string,
    currentIsActive: boolean,
  ) => Promise<void>;
  onRemovePool: (poolName: string) => Promise<void>;
  onCheckStatus: (poolName: string) => void;
  onSwitchCompute: (poolName: string) => Promise<boolean>;
}

const DOC_URL = "https://docs.prometheux.ai/learn/vadalog/data-sources#setting-up-pat-in-snowflake";

const SnowflakePoolCard: React.FC<{
  machine: Machine;
  userMachine?: UserMachine;
  isAvailable?: boolean;
  isCurrent?: boolean;
  availabilityResult?: AvailabilityResult;
  isCheckingStatus?: boolean;
  isRequesting?: boolean;
  onUse?: () => void;
  onToggleActive?: (
    poolName: string,
    instanceFamily: string,
    currentIsActive: boolean,
  ) => Promise<void>;
  onRemove?: (poolName: string) => Promise<void>;
  onCheckStatus?: (poolName: string) => void;
  onSwitchCompute?: (poolName: string) => Promise<boolean>;
}> = ({
  machine,
  userMachine,
  isAvailable = false,
  isCurrent = false,
  availabilityResult,
  isCheckingStatus = false,
  isRequesting = false,
  onUse,
  onToggleActive,
  onRemove,
  onCheckStatus,
  onSwitchCompute,
}) => {
  const machineStatus = availabilityResult?.machine_status;
  const isRunning = machineStatus === "started";

  return (
    <Card
      className={`@container transition-all hover:shadow-md ${isCurrent ? "border-primary ring-1 ring-primary/30" : ""}`}
    >
      <CardHeader className="flex flex-row flex-wrap items-center justify-between gap-2 space-y-0 pb-2">
        <CardTitle className="text-sm font-medium">
          <div className="flex items-center gap-2">
            {machine.name}
            {isCurrent && (
              <Badge variant="default" className="text-xs">
                Current
              </Badge>
            )}
          </div>
          {userMachine && (
            <div className="text-xs font-mono text-muted-foreground font-normal mt-0.5">
              {userMachine.id}
            </div>
          )}
        </CardTitle>
        <div className="flex items-center gap-2">
          {/* Start/Stop for existing pools */}
          {userMachine && !isAvailable && onToggleActive && (
            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    variant={userMachine.is_active ? "default" : "outline"}
                    size="sm"
                    className="h-6 px-2 text-xs"
                    disabled={
                      (isCurrent && userMachine.is_active) ||
                      (machineStatus != null && ["starting", "pending"].includes(machineStatus))
                    }
                    onClick={(e) => {
                      e.stopPropagation();
                      onToggleActive(userMachine.id, machine.id, userMachine.is_active);
                    }}
                  >
                    <Power className="w-2 h-2 mr-1" />
                    {userMachine.is_active ? "Stop" : "Start"}
                  </Button>
                </TooltipTrigger>
                <TooltipContent>
                  {isCurrent && userMachine.is_active ? (
                    <p>Cannot suspend the current platform compute pool</p>
                  ) : (
                    <p>
                      {userMachine.is_active
                        ? "Suspend this compute pool"
                        : "Resume this compute pool"}
                    </p>
                  )}
                </TooltipContent>
              </Tooltip>
            </TooltipProvider>
          )}

          {/* Status check */}
          {userMachine && !isAvailable && onCheckStatus && (
            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-6 px-2 text-xs"
                    onClick={(e) => {
                      e.stopPropagation();
                      onCheckStatus(userMachine.id);
                    }}
                    disabled={isCheckingStatus}
                  >
                    <RefreshCw className={`w-3 h-3 ${isCheckingStatus ? "animate-spin" : ""}`} />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>
                  <p>{availabilityResult?.message || "Check compute pool status"}</p>
                </TooltipContent>
              </Tooltip>
            </TooltipProvider>
          )}

          {/* Use button for available machines */}
          {isAvailable && onUse && (
            <Button
              variant="outline"
              size="sm"
              className="h-6 px-2 text-xs"
              onClick={(e) => {
                e.stopPropagation();
                onUse();
              }}
              disabled={isRequesting}
            >
              {isRequesting ? (
                <>
                  <PrometheuxSpinner size={16} className="mr-1" />
                  Creating...
                </>
              ) : (
                <>
                  <Plus className="w-2 h-2 mr-1" />
                  Use
                </>
              )}
            </Button>
          )}
        </div>
      </CardHeader>

      <CardContent>
        <div className="space-y-3">
          {machine.category && (
            <div className="text-xs text-muted-foreground">
              {getCategoryDisplayName(machine.category)}
            </div>
          )}
          <div className="grid grid-cols-1 gap-3 @xs:grid-cols-3 @xs:gap-4">
            <div className="flex items-center gap-2">
              <div className="flex items-center justify-center w-6 h-6 rounded-full bg-blue-100 dark:bg-blue-900/30">
                <Cpu className="w-3 h-3 text-blue-600 dark:text-blue-400" />
              </div>
              <div>
                <div className="text-xs text-muted-foreground">vCPUs</div>
                <div className="text-sm font-semibold">{machine.cores}</div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <div className="flex items-center justify-center w-6 h-6 rounded-full bg-purple-100 dark:bg-purple-900/30">
                <MemoryStick className="w-3 h-3 text-purple-600 dark:text-purple-400" />
              </div>
              <div>
                <div className="text-xs text-muted-foreground">Memory</div>
                <div className="text-sm font-semibold">{machine.memory_gb} GB</div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <div className="flex items-center justify-center w-6 h-6 rounded-full bg-green-100 dark:bg-green-900/30">
                <DollarSign className="w-3 h-3 text-green-600 dark:text-green-400" />
              </div>
              <div>
                <div className="text-xs text-muted-foreground">Cost</div>
                <div className="text-sm font-semibold">${machine.cost_per_machine}/hr</div>
              </div>
            </div>
          </div>
        </div>
      </CardContent>

      {/* Footer for existing pools */}
      {userMachine && !isAvailable && (
        <CardFooter className="flex items-center justify-between pt-2 border-t">
          <div className="flex items-center gap-2">
            {machineStatus === "started" && (
              <Badge
                variant="outline"
                className="text-xs text-green-600 dark:text-green-400 border-green-600"
              >
                <CheckCircle className="w-2 h-2 mr-1" />
                Running
              </Badge>
            )}
            {["pending", "starting"].includes(machineStatus || "") && (
              <Badge
                variant="outline"
                className="text-xs text-blue-600 dark:text-blue-400 border-blue-600"
              >
                <PrometheuxSpinner size={16} className="mr-1" />
                Starting
              </Badge>
            )}
            {machineStatus === "stopped" && (
              <Badge
                variant="outline"
                className="text-xs text-gray-600 dark:text-gray-400 border-gray-600"
              >
                <Ban className="w-2 h-2 mr-1" />
                Suspended
              </Badge>
            )}
          </div>

          <div className="flex items-center gap-2">
            {/* Select for Platform button (only for running pools that aren't already current) */}
            {isRunning && !isCurrent && onSwitchCompute && (
              <AlertDialog>
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <AlertDialogTrigger asChild>
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-7 px-3 text-xs border-primary text-primary hover:bg-primary/10"
                          onClick={(e) => e.stopPropagation()}
                        >
                          <ArrowRightLeft className="w-3 h-3 mr-1" />
                          Select
                        </Button>
                      </AlertDialogTrigger>
                    </TooltipTrigger>
                    <TooltipContent>
                      <p>Switch the platform to use this compute pool</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
                <AlertDialogContent>
                  <AlertDialogHeader>
                    <AlertDialogTitle className="flex items-center gap-2">
                      <AlertTriangle className="w-5 h-5 text-amber-500" />
                      Switch Compute Pool?
                    </AlertDialogTitle>
                    <AlertDialogDescription asChild>
                      <div className="space-y-3">
                        <p>
                          You are about to switch the platform to compute pool{" "}
                          <strong className="font-mono">{userMachine.id}</strong>.
                        </p>
                        <div className="bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded-md p-3 text-sm text-amber-800 dark:text-amber-300 space-y-1">
                          <p className="font-medium">This action will:</p>
                          <ul className="list-disc list-inside space-y-1">
                            <li>Restart all platform services (backend, frontend, data-manager)</li>
                            <li>Change the application URL -- this page will stop working</li>
                            <li>
                              Require you to reopen the app from Snowsight (Catalog &rarr; Apps
                              &rarr; Prometheux)
                            </li>
                          </ul>
                        </div>
                        <p className="text-xs">
                          The restart typically takes 2-5 minutes. Your data and configurations are
                          preserved.
                        </p>
                      </div>
                    </AlertDialogDescription>
                  </AlertDialogHeader>
                  <AlertDialogFooter>
                    <AlertDialogCancel>Cancel</AlertDialogCancel>
                    <AlertDialogAction
                      onClick={() => onSwitchCompute(userMachine.id)}
                      className="bg-primary"
                    >
                      Switch Compute
                    </AlertDialogAction>
                  </AlertDialogFooter>
                </AlertDialogContent>
              </AlertDialog>
            )}

            {/* Remove button (only for stopped, non-current pools) */}
            {!userMachine.is_active && !isCurrent && onRemove && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-7 px-2 text-xs text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-950"
                      onClick={(e) => {
                        e.stopPropagation();
                        onRemove(userMachine.id);
                      }}
                    >
                      <Trash2 className="w-3 h-3 mr-1" />
                      Drop
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>
                    <p>Drop this compute pool permanently</p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}
          </div>
        </CardFooter>
      )}
    </Card>
  );
};

export const SnowflakePoolsTabContent: React.FC<SnowflakePoolsTabContentProps> = ({
  availableMachines,
  userMachines,
  currentPool,
  loading,
  error,
  isRequesting,
  checkingStatus,
  availabilityResults,
  onRefresh,
  onUsePool,
  onToggleActive,
  onRemovePool,
  onCheckStatus,
  onSwitchCompute,
}) => {
  const [refreshing, setRefreshing] = React.useState(false);

  const handleRefresh = async () => {
    setRefreshing(true);
    try {
      await onRefresh();
    } finally {
      setRefreshing(false);
    }
  };

  const activeUserMachines = userMachines.filter((um) => um.is_active);
  const stoppedUserMachines = userMachines.filter((um) => !um.is_active);

  return (
    <div className="space-y-6">
      {/* Info banner with grant instructions */}
      <Alert>
        <AlertCircle className="h-4 w-4" />
        <AlertDescription className="flex items-center justify-between">
          <span>
            Compute pools must be granted to the Prometheux app. Create a pool below, or grant an
            existing one via SQL.
          </span>
          <Button
            variant="link"
            size="sm"
            className="ml-2 flex-shrink-0"
            onClick={() => window.open(DOC_URL, "_blank")}
          >
            <ExternalLink className="w-3 h-3 mr-1" />
            Docs
          </Button>
        </AlertDescription>
      </Alert>

      {/* Refresh button */}
      <div className="flex justify-end">
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="outline"
                size="icon"
                onClick={handleRefresh}
                disabled={refreshing}
                aria-label="Refresh compute pool status"
              >
                <RefreshCw className={`w-4 h-4 ${refreshing ? "animate-spin" : ""}`} />
              </Button>
            </TooltipTrigger>
            <TooltipContent>
              <p>Refresh compute pool status</p>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-8">
          <PrometheuxSpinner size={36} label="Loading compute pools ..." />
        </div>
      ) : error ? (
        <div className="text-center py-8">
          <p className="text-red-600 dark:text-red-400 mb-4">{error}</p>
          <Button onClick={handleRefresh} variant="outline">
            <RefreshCw className="w-4 h-4 mr-2" />
            Retry
          </Button>
        </div>
      ) : (
        <div className="space-y-8">
          {/* Active (Running) Pools */}
          {activeUserMachines.length > 0 && (
            <div>
              <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Zap className="w-5 h-5 text-green-600 dark:text-green-400" />
                Active Compute Pools
              </h3>
              <div className="grid gap-4 @2xl:grid-cols-2 @5xl:grid-cols-3">
                {activeUserMachines.map((um) => {
                  if (!um.machines) return null;
                  return (
                    <SnowflakePoolCard
                      key={um.id}
                      machine={um.machines}
                      userMachine={um}
                      isCurrent={um.is_default}
                      availabilityResult={availabilityResults[um.id]}
                      isCheckingStatus={checkingStatus[um.id]}
                      onToggleActive={onToggleActive}
                      onRemove={onRemovePool}
                      onCheckStatus={onCheckStatus}
                      onSwitchCompute={onSwitchCompute}
                    />
                  );
                })}
              </div>
            </div>
          )}

          {/* Stopped (Suspended) Pools */}
          {stoppedUserMachines.length > 0 && (
            <div>
              <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Server className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                Suspended Compute Pools
              </h3>
              <div className="grid gap-4 @2xl:grid-cols-2 @5xl:grid-cols-3">
                {stoppedUserMachines.map((um) => {
                  if (!um.machines) return null;
                  return (
                    <SnowflakePoolCard
                      key={um.id}
                      machine={um.machines}
                      userMachine={um}
                      isCurrent={um.is_default}
                      availabilityResult={availabilityResults[um.id]}
                      isCheckingStatus={checkingStatus[um.id]}
                      onToggleActive={onToggleActive}
                      onRemove={onRemovePool}
                      onCheckStatus={onCheckStatus}
                      onSwitchCompute={onSwitchCompute}
                    />
                  );
                })}
              </div>
            </div>
          )}

          {/* Available Instance Families (not yet created as pools) */}
          {availableMachines.length > 0 && (
            <div>
              <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Plus className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                Available Instance Families
              </h3>
              {groupMachinesByCategory(availableMachines).map(
                ({ category, displayName, machines: catMachines }) => (
                  <div key={category} className="mb-6">
                    <h4 className="text-md font-medium text-muted-foreground flex items-center gap-2 mb-3">
                      {displayName}
                      <Badge variant="outline" className="text-xs">
                        {catMachines.length}
                      </Badge>
                    </h4>
                    <div className="grid gap-4 @2xl:grid-cols-2 @5xl:grid-cols-3">
                      {catMachines.map((machine) => (
                        <SnowflakePoolCard
                          key={machine.id}
                          machine={machine}
                          isAvailable
                          isRequesting={isRequesting}
                          onUse={() => onUsePool(machine.id)}
                        />
                      ))}
                    </div>
                  </div>
                ),
              )}
            </div>
          )}

          {/* Empty state */}
          {userMachines.length === 0 && availableMachines.length === 0 && (
            <Card className="border-dashed">
              <CardHeader>
                <CardTitle className="text-sm font-medium text-muted-foreground">
                  No Compute Pools
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-muted-foreground">
                  No compute pools or instance families are available. Please check your Snowflake
                  account configuration and ensure pools are granted to the app.
                </p>
              </CardContent>
            </Card>
          )}
        </div>
      )}
    </div>
  );
};
