import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import type {
  GraphAnalyticsDef,
  GraphAnalyticsKey,
  GraphAnalyticsParam,
} from "../../graphAnalytics";

const INPUT_CLS =
  "h-7 bg-background border border-border rounded px-1.5 text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring";

interface ConceptGraphAnalyticsToolbarProps {
  /** The analytics function chosen in the mode bar. */
  fn: GraphAnalyticsDef;
  isBusy: boolean;
  /** The analytics overlay currently applied to the graph, if any. */
  activeType: string | null;
  onRun: (key: GraphAnalyticsKey, params: Record<string, unknown>) => void;
  onClear: () => void;
}

type RawParams = Record<string, string>;

function defaultRawParams(def: GraphAnalyticsDef): RawParams {
  return def.params.reduce<RawParams>((acc, param) => {
    acc[param.name] = param.kind === "int" ? "" : String(param.default);
    return acc;
  }, {});
}

function coerceParam(param: GraphAnalyticsParam, raw: string): [string, unknown] | null {
  if (param.kind === "number") return [param.name, Number.parseFloat(raw) || param.default];
  if (param.kind === "enum") return [param.name, raw || param.default];
  const parsed = Number.parseInt(raw, 10);
  if (Number.isNaN(parsed)) return null;
  return [param.name, parsed];
}

function buildFunctionParams(def: GraphAnalyticsDef, raw: RawParams): Record<string, unknown> {
  return def.params.reduce<Record<string, unknown>>((acc, param) => {
    const entry = coerceParam(param, raw[param.name] ?? "");
    if (entry) acc[entry[0]] = entry[1];
    return acc;
  }, {});
}

export function ConceptGraphAnalyticsToolbar({
  fn,
  isBusy,
  activeType,
  onRun,
  onClear,
}: ConceptGraphAnalyticsToolbarProps) {
  const [rawParams, setRawParams] = useState<RawParams>(() => defaultRawParams(fn));

  const setParam = (name: string, value: string) =>
    setRawParams((prev) => ({ ...prev, [name]: value }));

  const handleRun = () => onRun(fn.key, buildFunctionParams(fn, rawParams));

  const renderParam = (param: GraphAnalyticsParam) => {
    const value = rawParams[param.name] ?? "";
    if (param.kind === "enum") {
      return (
        <label
          key={param.name}
          className="flex items-center gap-1 text-[11px] text-muted-foreground"
        >
          {param.label}
          <select
            value={value}
            disabled={isBusy}
            onChange={(event) => setParam(param.name, event.target.value)}
            className={INPUT_CLS}
          >
            {param.options.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </label>
      );
    }
    const isInt = param.kind === "int";
    return (
      <label key={param.name} className="flex items-center gap-1 text-[11px] text-muted-foreground">
        {param.label}
        <input
          type="number"
          value={value}
          disabled={isBusy}
          min={param.min}
          max={param.max}
          step={param.kind === "number" ? param.step : undefined}
          placeholder={isInt ? param.placeholder : undefined}
          onChange={(event) => setParam(param.name, event.target.value)}
          className={`${INPUT_CLS} w-20`}
        />
      </label>
    );
  };

  return (
    <div className="flex items-center gap-2 px-3 py-1.5 border-b border-border flex-shrink-0 flex-wrap">
      <span className="text-[11px] font-medium text-muted-foreground">{fn.label}</span>

      {fn.params.map(renderParam)}

      <Button size="sm" className="h-7 text-xs" disabled={isBusy} onClick={handleRun}>
        {isBusy ? "Running…" : "Run"}
      </Button>

      {activeType && (
        <Button
          size="sm"
          variant="outline"
          className="h-7 text-xs"
          disabled={isBusy}
          onClick={onClear}
        >
          Clear
        </Button>
      )}

      <p className="text-[10px] text-muted-foreground">{fn.description}</p>
    </div>
  );
}
