import { FileText, Table2 } from "lucide-react";
import type React from "react";
import type { ConceptCell } from "@/features/concept-editor/types";
import { runStatusDotClass } from "@/features/concept-editor/utils/runStatus";
import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

export type CellView = "editor" | "context" | "output";

interface CellViewTabsProps {
  cell: ConceptCell;
  currentView: CellView;
  /** Label for the cell's authoring view (e.g. "notes", "prompt"). */
  editorLabel: string;
  editorIcon: React.ReactNode;
  /** Label for the context/description view ("context" or "description"). */
  contextLabel?: string;
  /**
   * Explorer layout: the editor is always mounted, so the other two views move
   * to the bottom panel (see CellSplitBottomTabs) and only the editor tab stays.
   */
  splitLayout?: boolean;
  onSelectView: (view: CellView) => void;
}

const TAB_BASE = "h-7 px-2 text-xs";
const TAB_ACTIVE = "bg-muted text-foreground";
const TAB_INACTIVE = "hover:bg-muted/50";

/**
 * View switcher for the context / llm cells — the same context | editor |
 * output pattern the established cells use (see PythonCellViewTabs), with a
 * configurable authoring-tab label.
 */
export function CellViewTabs({
  cell,
  currentView,
  editorLabel,
  editorIcon,
  contextLabel = "context",
  splitLayout = false,
  onSelectView,
}: CellViewTabsProps) {
  const showOutputDot = !!(cell.result || cell.error || cell.isRunning);
  // In split layout the editor pane is always mounted, so its tab reads as active.
  const editorActive = currentView === "editor" || splitLayout;

  return (
    <div className={cn("border-b border-border/50 bg-muted/30", splitLayout && "order-1 border-t")}>
      <div className="flex items-center gap-1 px-4 py-2">
        {!splitLayout && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onSelectView("context")}
            className={cn(TAB_BASE, currentView === "context" ? TAB_ACTIVE : TAB_INACTIVE)}
          >
            <FileText className="h-3 w-3 mr-1" />
            {contextLabel}
          </Button>
        )}
        <Button
          variant="ghost"
          size="sm"
          onClick={() => onSelectView("editor")}
          className={cn(TAB_BASE, editorActive ? TAB_ACTIVE : TAB_INACTIVE)}
        >
          {editorIcon}
          {editorLabel}
        </Button>
        {!splitLayout && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onSelectView("output")}
            className={cn(TAB_BASE, currentView === "output" ? TAB_ACTIVE : TAB_INACTIVE)}
          >
            <Table2 className="h-3 w-3 mr-1" />
            output
            {showOutputDot && (
              <span
                className={`ml-1 inline-block h-1.5 w-1.5 rounded-full ${runStatusDotClass(cell)}`}
              />
            )}
          </Button>
        )}
      </div>
    </div>
  );
}
