import { useEffect } from "react";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { ConfigService } from "@/features/settings/api/configService";
import { useConfigStore } from "@/features/settings/store/configStore";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

/**
 * Loads the user's saved LLM/embedding configuration from the backend and
 * applies it to the global `PROMETHEUX_CONFIG` on startup.
 *
 * On a fresh login the auth token is set asynchronously (by AuthProvider) after
 * this hook first mounts, so the effect must re-run once authentication lands —
 * otherwise the load would no-op on the missing token and never retry, leaving
 * the chat on the build-time default model until the user visits Settings.
 *
 * We key the effect on `user?.id` rather than the context `authToken`: during a
 * normal login AuthProvider writes the real token into the global
 * `PROMETHEUX_CONFIG.AUTH_TOKEN` (and `HttpService`) but leaves the reactive
 * `authToken` null — it only sets `user` after the token is in place. Keying on
 * `user?.id` therefore guarantees the token is already available in the global
 * when this effect re-runs, with no race against the cold-login metadata retry.
 */
export const useConfigLoader = () => {
  const { user } = useAuth();
  const bumpConfigVersion = useConfigStore((s) => s.bumpConfigVersion);

  // `user?.id` is an intentional trigger (not read in the body): it flips from
  // null to a value only after AuthProvider has placed the token in the global,
  // which is precisely when we want to (re)load the config.
  // biome-ignore lint/correctness/useExhaustiveDependencies: user?.id is a deliberate re-run trigger
  useEffect(() => {
    // The real token lives in the global by the time `user` is populated
    // (AuthProvider sets it before `setUser`); the reactive `authToken` stays
    // null during a normal login, so we read the global directly here.
    const token = PROMETHEUX_CONFIG.AUTH_TOKEN;
    if (!token) return;

    let cancelled = false;

    const loadUserConfig = async () => {
      try {
        const config = await ConfigService.loadUserConfig();
        if (cancelled || !config) return;
        ConfigService.applyConfigToGlobal(config);
        bumpConfigVersion();
      } catch (error) {
        console.error("Error loading user configuration on startup:", error);
        // Continue with default configuration if loading fails
      }
    };

    loadUserConfig();

    return () => {
      cancelled = true;
    };
  }, [user?.id, bumpConfigVersion]);
};
