import ReactMarkdown from "react-markdown";
import type { FetchResult } from "../../../api/ConceptClient";

interface TextWidgetProps {
  data?: FetchResult;
  /** static markdown — used when the widget carries content instead of a tap */
  content?: string;
}

/**
 * text widget (ADR D4): renders a tap's output as markdown — this is how
 * non-deterministic (LLM) concept outputs display (first column of every
 * row, joined) — or static `content` markdown for descriptions and prose.
 */
export function TextWidget({ data, content }: TextWidgetProps) {
  const text =
    content ??
    (data?.rows ?? [])
      .map((row) => String(row[0] ?? ""))
      .filter(Boolean)
      .join("\n\n");

  if (!text) return <p className="text-xs text-muted-foreground py-4">No text output</p>;

  return (
    <div className="prose prose-sm dark:prose-invert max-w-none text-sm leading-relaxed">
      <ReactMarkdown>{text}</ReactMarkdown>
    </div>
  );
}
