import { Button } from "@/shared/components/ui/button";
import { Checkbox } from "@/shared/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import { Label } from "@/shared/components/ui/label";

interface OwlVadalogConfigDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  includeImports: boolean;
  onIncludeImportsChange: (value: boolean) => void;
  onSelectFile: () => void;
}

/** Configures the OWL → Vadalog translation, then triggers the OWL file picker. */
export function OwlVadalogConfigDialog({
  open,
  onOpenChange,
  includeImports,
  onIncludeImportsChange,
  onSelectFile,
}: OwlVadalogConfigDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Translate OWL to Vadalog</DialogTitle>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="flex items-center space-x-2">
            <Checkbox
              id="include-imports"
              checked={includeImports}
              onCheckedChange={(checked) => onIncludeImportsChange(checked as boolean)}
            />
            <Label
              htmlFor="include-imports"
              className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
            >
              Include imported ontologies
            </Label>
          </div>
          <p className="text-sm text-muted-foreground">
            When enabled, CSV files for classes and relations from imported ontologies will be
            automatically generated.
            <br />
            <br />
            The process may take a few minutes to complete, depending on the size of the imported
            ontologies and the internet connection.
          </p>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={onSelectFile}>Select OWL File</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
