import {
  ChevronDown,
  Circle,
  Code,
  Eye,
  FileCode,
  Link2,
  MoreHorizontal,
  Plus,
  Save,
  Upload,
} from "lucide-react";
import { useState } from "react";
import { useChatReservedWidth } from "@/features/code-assistant/hooks/useChatReservedWidth";
import ComputeIndicator from "@/features/compute/components/ComputeIndicator";
import { ReadOnlyGate } from "@/features/ontologies/sharing/components/ReadOnlyGate";
import { useOntologyWideReadOnly } from "@/features/ontologies/sharing/hooks/useOntologyWideReadOnly";
import OntologySchemaSearchBar from "@/features/ontology-schema/components/OntologySchemaSearchBar";
import { Button } from "@/shared/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/components/ui/dropdown-menu";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/components/ui/popover";
import {
  LINEAGE_NARROW_VIEWPORT_PX,
  useIsNarrowViewport,
} from "@/shared/hooks/ui/useIsNarrowViewport";
import { cn } from "@/shared/lib/utils";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";
import { OntologySchemaActionItems } from "./OntologySchemaActionItems";

function FullOntologySchemaActions() {
  const {
    viewMode,
    isSaving,
    isImporting,
    onViewModeChange,
    onAddNode,
    onOpenEdgeDialog,
    onSave,
    onTriggerOwlImport,
    onOpenOwlVadalogConfig,
    searchNodes,
    searchEdges,
    onNodeSearchSelect,
    onEdgeSearchSelect,
    onZoomToElement,
  } = useEditorActionsStore();
  // Ontology-wide save: allowed under a viewer share only if at least one
  // concept is elevated to writeable (the backend still enforces per concept).
  const ontologyWideReadOnly = useOntologyWideReadOnly();

  return (
    <>
      <div className="flex items-center rounded-md border bg-muted p-0.5 h-9">
        <button
          type="button"
          onClick={() => onViewModeChange?.("visual")}
          className={cn(
            "flex h-full items-center gap-1.5 rounded px-2.5 text-xs font-medium transition-colors",
            viewMode === "visual"
              ? "bg-background text-foreground shadow-sm"
              : "text-muted-foreground hover:text-foreground",
          )}
        >
          <Eye className="h-3.5 w-3.5" />
          Visual
        </button>
        <button
          type="button"
          onClick={() => onViewModeChange?.("json")}
          className={cn(
            "flex h-full items-center gap-1.5 rounded px-2.5 text-xs font-medium transition-colors",
            viewMode === "json"
              ? "bg-background text-foreground shadow-sm"
              : "text-muted-foreground hover:text-foreground",
          )}
        >
          <Code className="h-3.5 w-3.5" />
          JSON
        </button>
      </div>

      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button variant="outline" size="sm" className="gap-1">
            <Plus className="h-3.5 w-3.5" />
            <ChevronDown className="h-3 w-3" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem onClick={() => onAddNode?.()} className="gap-2">
            <Circle className="h-3.5 w-3.5 text-muted-foreground" />
            Add Node
          </DropdownMenuItem>
          <DropdownMenuItem onClick={() => onOpenEdgeDialog?.()} className="gap-2">
            <Link2 className="h-3.5 w-3.5 text-muted-foreground" />
            Add Edge
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      <ReadOnlyGate readOnly={ontologyWideReadOnly}>
        <Button
          variant="outline"
          size="iconSm"
          onClick={() => onSave?.()}
          disabled={isSaving}
          title="Save graph"
        >
          <Save className="h-3.5 w-3.5" />
        </Button>
      </ReadOnlyGate>

      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button variant="outline" size="sm" className="gap-1" disabled={isImporting}>
            <Upload className="h-3.5 w-3.5" />
            <ChevronDown className="h-3 w-3" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem onClick={() => onTriggerOwlImport?.()} className="gap-2">
            <Eye className="h-3.5 w-3.5 text-muted-foreground" />
            Visualize OWL
          </DropdownMenuItem>
          <DropdownMenuItem onClick={() => onOpenOwlVadalogConfig?.()} className="gap-2">
            <FileCode className="h-3.5 w-3.5 text-muted-foreground" />
            Translate OWL to Vadalog
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      {onNodeSearchSelect && onEdgeSearchSelect && onZoomToElement && (
        <OntologySchemaSearchBar
          nodes={searchNodes}
          edges={searchEdges}
          onNodeSelect={onNodeSearchSelect}
          onEdgeSelect={onEdgeSearchSelect}
          onZoomToElement={onZoomToElement}
        />
      )}
    </>
  );
}

function CompactOntologySchemaActions() {
  const [open, setOpen] = useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="outline" size="iconSm" title="More actions" aria-label="More actions">
          <MoreHorizontal className="h-4 w-4" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-64 p-2">
        <OntologySchemaActionItems close={() => setOpen(false)} />
      </PopoverContent>
    </Popover>
  );
}

interface OntologySchemaActionsProps {
  /**
   * Show the compute selector. Compute drives concept *execution*, which lives
   * on the lineage view — the schema editor embedded in the Document view has
   * no use for it, so it opts out.
   */
  showCompute?: boolean;
}

export function OntologySchemaActions({ showCompute = true }: OntologySchemaActionsProps) {
  const reservedWidth = useChatReservedWidth();
  const isNarrow = useIsNarrowViewport(LINEAGE_NARROW_VIEWPORT_PX, reservedWidth);

  return (
    <>
      {showCompute && <ComputeIndicator interactive={true} />}
      {isNarrow ? <CompactOntologySchemaActions /> : <FullOntologySchemaActions />}
    </>
  );
}
