import type { EdgeData, NodeData } from "@antv/g6";
import type { ContextEdge, ContextNote, ContextShelf } from "../types";
import { parseConceptNodeId, shelfOf } from "../types";
import { linkDisplayTitle } from "./notesModel";

export type NotesGraphNodeType = "note" | "concept" | "ontology";

export interface NotesGraphNode extends NodeData {
  id: string;
  data: {
    label: string;
    /** null for concept/project nodes. */
    shelf: ContextShelf | null;
    nodeType: NotesGraphNodeType;
    degree: number;
    /** 1-hop neighbor outside the current collection — drawn muted. */
    isGhost: boolean;
  };
}

export interface NotesGraphEdge extends EdgeData {
  id: string;
  source: string;
  target: string;
  data: { relation: string };
}

export interface NotesGraphData {
  nodes: NotesGraphNode[];
  edges: NotesGraphEdge[];
}

function isGraphNodeType(value: string): value is "concept" | "ontology" {
  return value === "concept" || value === "ontology";
}

/**
 * Graph of the current collection plus its 1-hop neighbors (Obsidian's
 * local-graph idea): collection notes render full, note neighbors that only
 * appear on the other end of an edge render as muted ghosts, and linked
 * concepts/projects render as distinct (violet) nodes — clicking one
 * navigates to its project (decision 7).
 */
export function buildNotesGraphData(
  collectionNotes: ContextNote[],
  allEdges: ContextEdge[],
  lookupNotes: ContextNote[],
  ontologyNames: Map<string, string> = new Map(),
): NotesGraphData {
  const collectionIds = new Set(collectionNotes.map((note) => note.id));
  const byId = new Map<string, ContextNote>();
  for (const note of [...collectionNotes, ...lookupNotes]) {
    if (!byId.has(note.id)) byId.set(note.id, note);
  }

  const noteEdges = allEdges.filter(
    (edge) =>
      edge.src_type === "note" &&
      edge.dst_type === "note" &&
      (collectionIds.has(edge.src_id) || collectionIds.has(edge.dst_id)) &&
      byId.has(edge.src_id) &&
      byId.has(edge.dst_id),
  );

  // Note ↔ concept/project edges touching the collection.
  const entityEdges = allEdges.filter((edge) => {
    if (edge.src_type === "note" && isGraphNodeType(edge.dst_type)) {
      return collectionIds.has(edge.src_id);
    }
    if (edge.dst_type === "note" && isGraphNodeType(edge.src_type)) {
      return collectionIds.has(edge.dst_id);
    }
    return false;
  });

  const nodeIds = new Set(collectionIds);
  for (const edge of noteEdges) {
    nodeIds.add(edge.src_id);
    nodeIds.add(edge.dst_id);
  }

  const includedEdges = [...noteEdges, ...entityEdges];
  const degree = new Map<string, number>();
  for (const edge of includedEdges) {
    degree.set(edge.src_id, (degree.get(edge.src_id) ?? 0) + 1);
    degree.set(edge.dst_id, (degree.get(edge.dst_id) ?? 0) + 1);
  }

  const noteNodes = [...nodeIds]
    .map((id) => byId.get(id))
    .filter((note): note is ContextNote => Boolean(note))
    .map((note) => ({
      id: note.id,
      data: {
        // Documents are labeled by filename, like everywhere else.
        label: linkDisplayTitle(note),
        shelf: shelfOf(note),
        nodeType: "note" as const,
        degree: degree.get(note.id) ?? 0,
        isGhost: !collectionIds.has(note.id),
      },
    }));

  const entityNodes = new Map<string, NotesGraphNode>();
  for (const edge of entityEdges) {
    const entityType = edge.src_type === "note" ? edge.dst_type : edge.src_type;
    const entityId = edge.src_type === "note" ? edge.dst_id : edge.src_id;
    if (!isGraphNodeType(entityType) || entityNodes.has(entityId)) continue;
    const label =
      entityType === "concept"
        ? (parseConceptNodeId(entityId)?.conceptName ?? entityId)
        : (ontologyNames.get(entityId) ?? "(project)");
    entityNodes.set(entityId, {
      id: entityId,
      data: {
        label,
        shelf: null,
        nodeType: entityType,
        degree: degree.get(entityId) ?? 0,
        isGhost: false,
      },
    });
  }

  const edges = includedEdges.map((edge) => ({
    id: edge.id,
    source: edge.src_id,
    target: edge.dst_id,
    data: { relation: edge.relation },
  }));

  return { nodes: [...noteNodes, ...entityNodes.values()], edges };
}
