import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { DataClient } from "@/features/data-sources/api/DataClient";
import {
  createDirectory,
  deleteFiles,
  type FileEntry,
  listFiles,
  moveFile,
} from "@/features/data-sources/api/fileSystemApi";
import { buildUploadDescription } from "@/features/data-sources/utils";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";

const FILE_TYPE_MAP: Record<string, string> = {
  csv: "csv",
  parquet: "parquet",
  json: "json",
  xlsx: "excel",
  xls: "excel",
  tsv: "csv",
  txt: "text",
  pdf: "binaryfile",
  docx: "binaryfile",
  doc: "binaryfile",
  ttl: "ttl",
  rdf: "rdf",
  owl: "owl",
  yaml: "yaml",
  yml: "yaml",
  orc: "parquet",
  png: "binaryfile",
  jpg: "binaryfile",
  jpeg: "binaryfile",
  gif: "binaryfile",
  svg: "binaryfile",
  tiff: "binaryfile",
  cbl: "cobol",
  cpy: "cobol",
};

const CONNECTABLE_EXTENSIONS = new Set(Object.keys(FILE_TYPE_MAP));

type BinaryDocumentType = "sections" | "layout";

/**
 * How each `binaryfile` extension should be read, mirroring the defaults the
 * schema-inference form sends: `sections` for PDFs and images, `layout` for Word
 * documents.
 *
 * Sending nothing is not the neutral option. The backend then falls back to
 * `layout`, which OCRs the file through Azure Document Intelligence and feeds the
 * text to an LLM to invent a schema — metered per file, against a shared daily
 * quota. `sections` costs nothing at connect: its schema is fixed and known up
 * front. Keep the keys in step with the `binaryfile` entries of FILE_TYPE_MAP.
 */
const BINARY_DOCUMENT_TYPE: Record<string, BinaryDocumentType> = {
  pdf: "sections",
  png: "sections",
  jpg: "sections",
  jpeg: "sections",
  gif: "sections",
  svg: "sections",
  tiff: "sections",
  docx: "layout",
  doc: "layout",
};

export function isConnectable(entry: FileEntry): boolean {
  if (entry.type !== "file") return false;
  return CONNECTABLE_EXTENSIONS.has(entry.extension ?? "");
}

export function useFileBrowser() {
  const [currentPath, setCurrentPath] = useState("");
  const [entries, setEntries] = useState<FileEntry[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedFiles, setSelectedFiles] = useState<Set<string>>(new Set());

  const dataClient = useMemo(() => new DataClient(), []);
  const loadInProgress = useRef(false);

  const loadEntries = useCallback(async (path: string) => {
    if (loadInProgress.current) return;
    loadInProgress.current = true;
    setIsLoading(true);
    try {
      const result = await listFiles(path);
      setEntries(result);
      setSelectedFiles(new Set());
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to list files");
    } finally {
      setIsLoading(false);
      loadInProgress.current = false;
    }
  }, []);

  useEffect(() => {
    loadEntries(currentPath);
  }, [currentPath, loadEntries]);

  const navigate = useCallback((path: string) => {
    setCurrentPath(path);
  }, []);

  const navigateUp = useCallback(() => {
    if (!currentPath) return;
    const parts = currentPath.split("/").filter(Boolean);
    parts.pop();
    setCurrentPath(parts.join("/"));
  }, [currentPath]);

  const navigateInto = useCallback(
    (folderName: string) => {
      const next = currentPath ? `${currentPath}/${folderName}` : folderName;
      setCurrentPath(next);
    },
    [currentPath],
  );

  const refresh = useCallback(() => {
    loadEntries(currentPath);
  }, [currentPath, loadEntries]);

  const toggleSelect = useCallback((name: string) => {
    setSelectedFiles((prev) => {
      const next = new Set(prev);
      if (next.has(name)) next.delete(name);
      else next.add(name);
      return next;
    });
  }, []);

  const toggleSelectAll = useCallback(
    (selectAll: boolean) => {
      if (selectAll) {
        setSelectedFiles(new Set(entries.map((e) => e.name)));
      } else {
        setSelectedFiles(new Set());
      }
    },
    [entries],
  );

  const mkdir = useCallback(
    async (name: string) => {
      const fullPath = currentPath ? `${currentPath}/${name}` : name;
      try {
        await createDirectory(fullPath);
        toast.success(`Folder "${name}" created`);
        refresh();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Failed to create folder");
      }
    },
    [currentPath, refresh],
  );

  const deleteSelected = useCallback(
    async (names: string[], recursive = false) => {
      const fullPaths = names.map((n) => (currentPath ? `${currentPath}/${n}` : n));
      try {
        const result = await deleteFiles(fullPaths, recursive);
        if (result.deleted.length > 0) {
          toast.success(`Deleted ${result.deleted.length} item(s)`);
        }
        if (result.errors.length > 0) {
          for (const e of result.errors) {
            toast.error(`${e.path}: ${e.error}`);
          }
        }
        refresh();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Failed to delete");
      }
    },
    [currentPath, refresh],
  );

  const uploadFile = useCallback(
    async (file: File, onProgress?: (p: number) => void) => {
      try {
        const result = await dataClient.uploadFile(file, currentPath, onProgress);
        toast.success(`"${file.name}" uploaded`, {
          description: buildUploadDescription(result),
        });
        refresh();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Upload failed");
        throw err;
      }
    },
    [dataClient, currentPath, refresh],
  );

  const rename = useCallback(
    async (oldName: string, newName: string) => {
      const source = currentPath ? `${currentPath}/${oldName}` : oldName;
      const destination = currentPath ? `${currentPath}/${newName}` : newName;
      try {
        await moveFile(source, destination);
        toast.success(`Renamed "${oldName}" to "${newName}"`);
        refresh();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Rename failed");
      }
    },
    [currentPath, refresh],
  );

  const move = useCallback(
    async (name: string, destinationDir: string) => {
      const source = currentPath ? `${currentPath}/${name}` : name;
      const destination = destinationDir ? `${destinationDir}/${name}` : name;
      try {
        await moveFile(source, destination);
        toast.success(`Moved "${name}" to "${destinationDir || "root"}"`);
        refresh();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Move failed");
      }
    },
    [currentPath, refresh],
  );

  const download = useCallback(
    async (name: string) => {
      const filePath = currentPath ? `${currentPath}/${name}` : name;
      const url = `${PROMETHEUX_CONFIG.BASE_URL}/data/files/download?path=${encodeURIComponent(filePath)}`;
      try {
        const response = await fetch(url, {
          headers: {
            Authorization: `Bearer ${PROMETHEUX_CONFIG.AUTH_TOKEN || ""}`,
          },
          mode: "cors",
        });
        if (!response.ok) {
          const errData = await response.json().catch(() => null);
          toast.error(errData?.message || "Download failed");
          return;
        }
        const blob = await response.blob();
        const blobUrl = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = blobUrl;
        a.download = name;
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(blobUrl);
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Download failed");
      }
    },
    [currentPath],
  );

  const buildConnectConfig = useCallback(
    (entry: FileEntry) => {
      const ext = entry.extension ?? "";
      const databaseType = FILE_TYPE_MAP[ext] ?? "csv";
      const host = currentPath ? `disk/${currentPath}` : "disk";
      const documentType = BINARY_DOCUMENT_TYPE[ext];
      return {
        databaseType,
        host,
        port: 0,
        databaseName: entry.name,
        ...(documentType ? { options: { documentType } } : {}),
      };
    },
    [currentPath],
  );

  return {
    currentPath,
    entries,
    isLoading,
    selectedFiles,
    navigate,
    navigateUp,
    navigateInto,
    refresh,
    toggleSelect,
    toggleSelectAll,
    mkdir,
    deleteSelected,
    uploadFile,
    rename,
    move,
    download,
    buildConnectConfig,
  };
}
