import type { ChatMessage } from "./store";

/**
 * Which persisted user row the bubble at `index` corresponds to, 0-based.
 *
 * The backend translates this into a database ordinal and truncates the
 * conversation there, so it has to match the stored rows rather than what is on
 * screen. Bubbles restored from history carry their true index, because a
 * stored message can render to nothing and be dropped from the list. Bubbles
 * typed in this session have none, so they are counted forward from the last
 * restored one — which keeps a list holding both kinds correct.
 */
export function resolveUserTurnIndex(messages: ChatMessage[], index: number): number {
  const own = messages[index]?.userTurnIndex;
  if (own !== undefined) return own;

  const preceding = messages.slice(0, index).filter((m) => m.role === "user");

  const lastRestored = preceding.reduce(
    (found, message, i) => (message.userTurnIndex === undefined ? found : i),
    -1,
  );
  if (lastRestored < 0) return preceding.length;

  const anchor = preceding[lastRestored].userTurnIndex ?? 0;
  return anchor + (preceding.length - lastRestored);
}

/**
 * The messages left after removing one exchange: the user message at `index`
 * and everything the assistant said in reply, up to the next user message.
 *
 * Stored turn indices further down are shifted back by one, because a row
 * before them has gone from the transcript and every later index the backend
 * knows about has moved with it. Messages typed in this session carry no index
 * and need none — they are counted forward from the last restored one, which
 * this keeps correct.
 */
export function removeTurnAt(messages: ChatMessage[], index: number): ChatMessage[] {
  const target = messages[index];
  if (!target || target.role !== "user") return messages;

  const following = messages.slice(index + 1);
  const nextUserOffset = following.findIndex((m) => m.role === "user");
  const end = nextUserOffset < 0 ? messages.length : index + 1 + nextUserOffset;
  const remaining = [...messages.slice(0, index), ...messages.slice(end)];

  const removedIndex = target.userTurnIndex;
  if (removedIndex === undefined) return remaining;

  return remaining.map((message) => shiftTurnIndex(message, removedIndex));
}

function shiftTurnIndex(message: ChatMessage, removedIndex: number): ChatMessage {
  const current = message.userTurnIndex;
  if (current === undefined || current <= removedIndex) return message;
  return { ...message, userTurnIndex: current - 1 };
}
