import { AlertCircle, ShieldOff } from "lucide-react";
import type React from "react";
import { useCallback, useState } from "react";
import { Alert, AlertDescription } from "@/shared/components/ui/alert";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/shared/components/ui/alert-dialog";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent, CardHeader } from "@/shared/components/ui/card";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { ApiKeyDialog } from "./ApiKeyDialog";
import { ApiKeyList } from "./ApiKeyList";
import { ApiKeySuccessDialog } from "./ApiKeySuccessDialog";
import type { CreateTokenInput } from "./apiKeys.types";
import { useApiKeys } from "./useApiKeys";

interface SuccessDialogState {
  isOpen: boolean;
  apiKey: string;
  keyName: string;
}

const INITIAL_SUCCESS_STATE: SuccessDialogState = { isOpen: false, apiKey: "", keyName: "" };

export const ApiKeys: React.FC = () => {
  const {
    tokens,
    isLoading,
    error,
    isCreating,
    isRevoking,
    isRevokingAll,
    createToken,
    revokeToken,
    revokeAllTokens,
  } = useApiKeys();

  const [successDialog, setSuccessDialog] = useState<SuccessDialogState>(INITIAL_SUCCESS_STATE);

  const handleCreateKey = useCallback(
    async (input: CreateTokenInput) => {
      const result = await createToken(input);
      setSuccessDialog({
        isOpen: true,
        apiKey: result.token,
        keyName: input.name,
      });
      return result;
    },
    [createToken],
  );

  const handleCloseSuccessDialog = useCallback(() => {
    setSuccessDialog(INITIAL_SUCCESS_STATE);
  }, []);

  const handleRevokeAll = useCallback(async () => {
    await revokeAllTokens();
  }, [revokeAllTokens]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <PrometheuxSpinner size={36} />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="destructive">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>Failed to load API keys: {error.message}</AlertDescription>
      </Alert>
    );
  }

  const hasTokens = tokens.length > 0;

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-2 flex-wrap">
            <ApiKeyDialog onCreateKey={handleCreateKey} isCreating={isCreating} />

            {hasTokens && (
              <AlertDialog>
                <AlertDialogTrigger asChild>
                  <Button variant="outline" disabled={isRevokingAll}>
                    <ShieldOff className="h-4 w-4 mr-2" />
                    {isRevokingAll ? "Revoking..." : "Revoke all keys"}
                  </Button>
                </AlertDialogTrigger>
                <AlertDialogContent>
                  <AlertDialogHeader>
                    <AlertDialogTitle>Revoke all API keys?</AlertDialogTitle>
                    <AlertDialogDescription>
                      This revokes every API key you own. Any service using these keys will stop
                      working immediately. This cannot be undone.
                    </AlertDialogDescription>
                  </AlertDialogHeader>
                  <AlertDialogFooter>
                    <AlertDialogCancel>Cancel</AlertDialogCancel>
                    <AlertDialogAction
                      onClick={handleRevokeAll}
                      className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                    >
                      Revoke everything
                    </AlertDialogAction>
                  </AlertDialogFooter>
                </AlertDialogContent>
              </AlertDialog>
            )}
          </div>
        </CardHeader>
        <CardContent>
          <ApiKeyList tokens={tokens} onRevokeToken={revokeToken} isRevoking={isRevoking} />
        </CardContent>
      </Card>

      <ApiKeySuccessDialog
        open={successDialog.isOpen}
        onOpenChange={handleCloseSuccessDialog}
        apiKey={successDialog.apiKey}
        keyName={successDialog.keyName}
      />
    </div>
  );
};
