import { useMemo } from "react";
import { useMyTeams } from "@/features/teams/hooks/useMyTeams";
import type { ShareType } from "../types";

interface TeamAdminAccess {
  canManage: boolean;
  teamName: string;
}

// Resolves whether the current user may co-manage a team share's permissions:
// true only for an owner/admin of the recipient team of a team-type share.
// The project owner manages via the owner-only path, not this one.
export function useTeamAdminAccess(
  teamId: string | undefined,
  shareType: ShareType | undefined,
): TeamAdminAccess {
  const { teams } = useMyTeams();

  return useMemo(() => {
    if (shareType !== "team" || !teamId) return { canManage: false, teamName: "" };
    const membership = teams.find((t) => t.id === teamId);
    if (!membership) return { canManage: false, teamName: "" };
    const canManage = membership.role === "owner" || membership.role === "admin";
    return { canManage, teamName: membership.name };
  }, [teams, teamId, shareType]);
}
