import { AlertTriangle, Ban, Loader2, PlugZap } from "lucide-react";
import type { ExecutionOverallStatus } from "@/features/lineage/executionStatus";

interface OntologyStatusBadgeProps {
  status: ExecutionOverallStatus | undefined;
}

interface BadgePresentation {
  label: string;
  Icon: typeof AlertTriangle;
  className: string;
  spin?: boolean;
}

/**
 * Compact execution-state pill for a project card. Renders only for states
 * worth surfacing on the list — a live run, or a last run that failed /
 * was cancelled / was interrupted. Idle and succeeded projects render nothing.
 */
function resolveBadge(status: ExecutionOverallStatus | undefined): BadgePresentation | null {
  if (status === "running") {
    return {
      label: "Running",
      Icon: Loader2,
      spin: true,
      className:
        "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900/40 dark:bg-amber-900/20 dark:text-amber-300",
    };
  }
  if (status === "error") {
    return {
      label: "Failed",
      Icon: AlertTriangle,
      className:
        "border-red-200 bg-red-50 text-red-700 dark:border-red-900/40 dark:bg-red-900/20 dark:text-red-300",
    };
  }
  if (status === "cancelled") {
    return {
      label: "Cancelled",
      Icon: Ban,
      className:
        "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900/40 dark:bg-amber-900/20 dark:text-amber-300",
    };
  }
  if (status === "interrupted") {
    return {
      label: "Interrupted",
      Icon: PlugZap,
      className:
        "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900/40 dark:bg-amber-900/20 dark:text-amber-300",
    };
  }
  return null;
}

export function OntologyStatusBadge({ status }: OntologyStatusBadgeProps) {
  const badge = resolveBadge(status);
  if (!badge) return null;

  const { label, Icon, className, spin } = badge;
  return (
    <span
      className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[11px] font-medium ${className}`}
    >
      <Icon className={`h-3 w-3 ${spin ? "animate-spin" : ""}`} />
      {label}
    </span>
  );
}
