import type { ReactNode } from "react";

import { Button } from "@/shared/components/ui/button";
import { cn } from "@/shared/lib/utils";

import type { WizardControls } from "./useWizardState";

interface WizardStepActionProps {
  label: string;
  onClick?: () => void;
  disabled?: boolean;
  variant?: "default" | "secondary" | "ghost" | "outline";
}

interface WizardStepProps {
  controls: WizardControls;
  title?: string;
  description?: string;
  primaryAction?: WizardStepActionProps;
  secondaryAction?: WizardStepActionProps;
  hideDefaultNav?: boolean;
  className?: string;
  children: ReactNode;
}

export function WizardStep({
  controls,
  title,
  description,
  primaryAction,
  secondaryAction,
  hideDefaultNav,
  className,
  children,
}: WizardStepProps) {
  const { currentStep, isFirstStep, isLastStep, goNext, goPrev, skipCurrent } = controls;
  const headingTitle = title ?? currentStep.title;
  const headingDescription = description ?? currentStep.description;

  const showSkip = !hideDefaultNav && currentStep.canSkip;
  const primaryLabel = primaryAction?.label ?? (isLastStep ? "Finish" : "Continue");
  const handlePrimary = primaryAction?.onClick ?? goNext;
  const handleSecondary = secondaryAction?.onClick ?? goPrev;
  const secondaryLabel = secondaryAction?.label ?? "Back";

  return (
    <div className={cn("flex h-full flex-col gap-4", className)}>
      <header className="space-y-1">
        <h2 className="text-lg font-semibold text-foreground">{headingTitle}</h2>
        {headingDescription && (
          <p className="text-sm text-muted-foreground">{headingDescription}</p>
        )}
      </header>
      <div className="flex-1">{children}</div>
      {!hideDefaultNav && (
        <footer className="flex items-center justify-between gap-2 border-t border-border pt-4">
          <div className="flex gap-2">
            {!isFirstStep && (
              <Button
                type="button"
                variant={secondaryAction?.variant ?? "ghost"}
                onClick={handleSecondary}
                disabled={secondaryAction?.disabled}
              >
                {secondaryLabel}
              </Button>
            )}
          </div>
          <div className="flex gap-2">
            {showSkip && (
              <Button type="button" variant="ghost" onClick={skipCurrent}>
                Skip this step
              </Button>
            )}
            <Button
              type="button"
              variant={primaryAction?.variant ?? "default"}
              onClick={handlePrimary}
              disabled={primaryAction?.disabled}
            >
              {primaryLabel}
            </Button>
          </div>
        </footer>
      )}
    </div>
  );
}
