import type React from "react";
import { siPython } from "simple-icons";

interface PythonIconProps {
  className?: string;
  size?: number;
}

/**
 * Python brand icon from simple-icons.
 * Drop-in replacement for the lucide Code2 icon wherever a Python-specific glyph is needed.
 * Fills with `currentColor` so it inherits surrounding text-color classes (theme-aware).
 */
const PythonIcon: React.FC<PythonIconProps> = ({ className = "", size }) => {
  const resolvedSize = size ?? sizeFromClassName(className) ?? 16;

  return (
    <svg
      role="img"
      viewBox="0 0 24 24"
      width={resolvedSize}
      height={resolvedSize}
      className={className}
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d={siPython.path} />
    </svg>
  );
};

function sizeFromClassName(cls: string): number | undefined {
  if (/\bw-3\b/.test(cls)) return 12;
  if (/\bw-3\.5\b/.test(cls)) return 14;
  if (/\bw-4\b/.test(cls)) return 16;
  if (/\bw-5\b/.test(cls)) return 20;
  if (/\bw-6\b/.test(cls)) return 24;
  return undefined;
}

export default PythonIcon;
