import { useState } from "react";
import { useParams } from "react-router-dom";
import { hydrateOntologySessionFromUrl } from "@/features/ontologies/utils";
import Ontology from "./Ontology";

/**
 * Route-level wrapper for the project editor. Keys Project by project id so a
 * project switch remounts the page, and hydrates the sessionStorage project
 * session from the URL before Project (and its children) mount — a direct URL
 * open (new tab, pasted link) bypasses the navigation handlers that normally
 * write currentOntologyId, which the concept-editor API clients rely on to load
 * cells. Runs as a state initializer (not an effect) so it is guaranteed to
 * precede child mounts and their data loads.
 */
export default function OntologyRoute() {
  const { id } = useParams<{ id: string }>();
  useState(() => hydrateOntologySessionFromUrl(window.location.pathname));
  return <Ontology key={id} />;
}
