import { Boxes } from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import { Button } from "@/shared/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/components/ui/tooltip";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";

import { useAttachedNotes } from "../hooks/useAttachedNotes";
import { useAllContextEdges, useContextEdges } from "../hooks/useContextEdges";
import { useContextNotes } from "../hooks/useContextNotes";
import { linkDisplayTitle } from "../notes/notesModel";
import type { ContextNote } from "../types";
import { conceptNodeId } from "../types";
import { AttachedNoteEditor } from "./AttachedNoteEditor";
import { AttachNoteControls } from "./AttachNoteControls";
import { ConceptContextCanvas } from "./ConceptContextCanvas";
import { DetachNoteDialog } from "./DetachNoteDialog";
import { useConceptContextActions } from "./useConceptContextActions";

interface ConceptContextPanelProps {
  ontologyId: string;
  conceptName: string;
}

type EditorState = { mode: "closed" } | { mode: "draft" } | { mode: "edit"; noteId: string };

/**
 * The concept-context area of the Explorer bottom panel's Context tab:
 * local context graph (concept + attached notes + note↔note links) with
 * attach/create affordances and in-place note editing. The description
 * section rendered above this is owned by the cell components.
 */
export function ConceptContextPanel({ ontologyId, conceptName }: ConceptContextPanelProps) {
  const conceptKey = conceptNodeId(ontologyId, conceptName);
  const [editor, setEditor] = useState<EditorState>({ mode: "closed" });
  const [isSaving, setIsSaving] = useState(false);

  const { data: attachedNotes } = useAttachedNotes("concept", conceptKey);
  const { data: allEdges } = useAllContextEdges();
  const { data: conceptEdges } = useContextEdges("concept", conceptKey);
  const { data: globalNotes } = useContextNotes({ scope: "global" });
  const { data: ontologyNotes } = useContextNotes({ scope: "ontology", scopeId: ontologyId });

  const actions = useConceptContextActions(ontologyId, conceptName);

  const attached = attachedNotes ?? [];
  const attachedIds = useMemo(() => new Set(attached.map((note) => note.id)), [attached]);
  const workspaceNotes = useMemo(
    () => [...(globalNotes ?? []), ...(ontologyNotes ?? [])],
    [globalNotes, ontologyNotes],
  );

  const editingNote: ContextNote | null =
    editor.mode === "edit" ? (attached.find((note) => note.id === editor.noteId) ?? null) : null;

  // The Explorer's Context rail can ask for a specific attached note to be
  // opened here (click on a note in the panel list). Consume once the
  // attached notes are loaded; clear either way so it can't fire later.
  const pendingNoteId = useEditorActionsStore((s) => s.pendingContextNoteId);
  useEffect(() => {
    if (!pendingNoteId || attachedNotes === undefined) return;
    useEditorActionsStore.getState().register({ pendingContextNoteId: null });
    if (attachedNotes.some((note) => note.id === pendingNoteId)) {
      setEditor({ mode: "edit", noteId: pendingNoteId });
    }
  }, [pendingNoteId, attachedNotes]);

  const closeEditor = () => setEditor({ mode: "closed" });

  const handleSave = async (text: string) => {
    setIsSaving(true);
    try {
      if (editor.mode === "draft") {
        const created = await actions.createAndAttach(text, workspaceNotes);
        if (created) closeEditor();
        return;
      }
      if (editingNote) {
        const noteEdges = (allEdges ?? []).filter(
          (edge) => edge.src_id === editingNote.id || edge.dst_id === editingNote.id,
        );
        const saved = await actions.saveNoteText(editingNote, text, workspaceNotes, noteEdges);
        if (saved) closeEditor();
      }
    } finally {
      setIsSaving(false);
    }
  };

  // Detaching the note's LAST connection leaves a project note floating
  // with no visible reason to exist — ask whether to keep or delete it
  // (a global note keeps living in the global vault; no prompt needed).
  const [confirmingDetach, setConfirmingDetach] = useState(false);

  const countOtherConnections = (note: ContextNote): number => {
    const conceptEdgeIds = new Set(
      (conceptEdges ?? [])
        .filter((e) => e.src_id === note.id || e.dst_id === note.id)
        .map((e) => e.id),
    );
    return (allEdges ?? []).filter(
      (edge) =>
        (edge.src_id === note.id || edge.dst_id === note.id) && !conceptEdgeIds.has(edge.id),
    ).length;
  };

  const performDetach = async () => {
    if (!editingNote) return;
    setConfirmingDetach(false);
    await actions.detachNote(editingNote.id, conceptEdges ?? []);
    closeEditor();
  };

  const performDetachAndDelete = async () => {
    if (!editingNote) return;
    setConfirmingDetach(false);
    await actions.deleteNote(editingNote.id);
    closeEditor();
  };

  const handleDetach = async () => {
    if (!editingNote) return;
    if (editingNote.scope === "ontology" && countOtherConnections(editingNote) === 0) {
      setConfirmingDetach(true);
      return;
    }
    await performDetach();
  };

  const isEditorOpen = editor.mode !== "closed";

  // Bridge: turn this concept's attached notes into a new static context
  // concept (a computable node pinned to the same note set). LineageView
  // consumes the seed and opens the pre-filled cell.
  const handleCreateContextConcept = () => {
    useEditorActionsStore.getState().register({
      pendingContextCellSeed: {
        noteIds: attached.map((note) => note.id),
        sourceConcept: conceptName,
      },
    });
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-2">
      <div className="flex items-center justify-between gap-2">
        <span className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
          Attached context
        </span>
        <div className="flex items-center gap-1.5">
          {attached.length > 0 && (
            <Tooltip delayDuration={300}>
              <TooltipTrigger asChild>
                <Button
                  variant="outline"
                  size="sm"
                  className="h-7 gap-1.5 text-xs"
                  onClick={handleCreateContextConcept}
                >
                  <Boxes className="h-3.5 w-3.5" />
                  Create context concept
                </Button>
              </TooltipTrigger>
              <TooltipContent side="bottom" className="max-w-xs text-xs leading-relaxed">
                New static context concept pre-pinned with these {attached.length} attached note
                {attached.length === 1 ? "" : "s"} — makes this knowledge a runnable node other
                concepts can bind.
              </TooltipContent>
            </Tooltip>
          )}
          <AttachNoteControls
            candidates={workspaceNotes}
            attachedIds={attachedIds}
            onAttach={actions.attachNote}
            onStartNewNote={() => setEditor({ mode: "draft" })}
          />
        </div>
      </div>
      {/* min-h keeps the canvas usable when the tab renders outside the
          split layout (accordion view has no fixed panel height). */}
      <div className="flex min-h-[240px] flex-1 gap-2">
        <div className={isEditorOpen ? "min-h-0 w-1/2" : "min-h-0 flex-1"}>
          <ConceptContextCanvas
            conceptKey={conceptKey}
            conceptName={conceptName}
            attachedNotes={attached}
            allEdges={allEdges ?? []}
            onOpenNote={(noteId) => setEditor({ mode: "edit", noteId })}
            refitKey={isEditorOpen ? "editor-open" : "editor-closed"}
          />
        </div>
        {isEditorOpen && (
          <div className="min-h-0 w-1/2">
            <AttachedNoteEditor
              key={editor.mode === "edit" ? editor.noteId : "draft"}
              note={editingNote}
              linkCandidates={workspaceNotes}
              onSave={handleSave}
              onDetach={editor.mode === "edit" ? handleDetach : undefined}
              onClose={closeEditor}
              isSaving={isSaving}
            />
          </div>
        )}
      </div>
      <DetachNoteDialog
        open={confirmingDetach}
        noteTitle={editingNote ? linkDisplayTitle(editingNote) : ""}
        onDetachOnly={performDetach}
        onDetachAndDelete={performDetachAndDelete}
        onCancel={() => setConfirmingDetach(false)}
      />
    </div>
  );
}
