import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { useAgentMessageUsage } from "../hooks/useAgentMessageUsage";
import { formatResetDate } from "../utils/billing.utils";
import { ContactToUpgradeDialog } from "./ContactToUpgradeDialog";

/**
 * Shown when a freemium account hits its monthly AI-agent message cap. Reads the
 * shared open flag from the chat store so either send site (HomeChat or the
 * docked panel) can trigger it without prop drilling. Lifting the cap is part of
 * a paid subscription, so the CTA contacts Prometheux rather than Stripe.
 */
export const AgentMessageLimitDialog = () => {
  const isOpen = useCodeAssistantStore((s) => s.isAgentLimitDialogOpen);
  const closeDialog = useCodeAssistantStore((s) => s.closeAgentLimitDialog);
  const { usage } = useAgentMessageUsage();

  const limit = usage?.limit ?? 150;
  const resetDate = formatResetDate(usage?.resetsAt ?? null);
  const resetClause = resetDate ? ` Your quota resets on ${resetDate}.` : "";
  const description = `Freemium accounts include ${limit} AI agent messages per month.${resetClause} Lifting this limit is part of a paid subscription — contact Prometheux to upgrade and keep building without interruption.`;

  const handleOpenChange = (open: boolean) => {
    if (!open) closeDialog();
  };

  return (
    <ContactToUpgradeDialog
      open={isOpen}
      onOpenChange={handleOpenChange}
      title="You've reached your monthly AI agent limit"
      description={description}
      contactSubject="Upgrade request — AI agent messages"
    />
  );
};
