import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { toast } from "sonner";
import { PAID_COMPUTE_ELIGIBILITY_QUERY_KEY } from "./usePaidComputeEligibility";
import { SUBSCRIBER_ROW_QUERY_KEY } from "./useSubscriberRow";

const POLL_INTERVAL_MS = 2000;
const MAX_POLL_ATTEMPTS = 15;
const SESSION_ID_PARAM = "session_id";

export interface UsePostCheckoutConfirmationResult {
  isConfirming: boolean;
}

// When Stripe redirects back to /settings/billing?session_id=…, we cannot trust
// the next call to can_use_paid_compute() — the stripe-webhook may not yet have
// written the subscribers row. We poll the RPC up to ~30s, refetching both the
// eligibility query and the subscribers row each tick so the UI flips as soon
// as the truth changes. On success / timeout we strip the param from the URL
// so a reload doesn't restart the loop.
export const usePostCheckoutConfirmation = (
  isEligible: boolean | undefined,
): UsePostCheckoutConfirmationResult => {
  const [searchParams, setSearchParams] = useSearchParams();
  const queryClient = useQueryClient();
  const sessionId = searchParams.get(SESSION_ID_PARAM);
  const [isConfirming, setIsConfirming] = useState<boolean>(Boolean(sessionId));
  const attemptsRef = useRef(0);
  const intervalRef = useRef<number | null>(null);

  const stop = useCallback(
    (clearParam: boolean) => {
      if (intervalRef.current !== null) {
        window.clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      setIsConfirming(false);
      if (clearParam) {
        const next = new URLSearchParams(searchParams);
        next.delete(SESSION_ID_PARAM);
        setSearchParams(next, { replace: true });
      }
    },
    [searchParams, setSearchParams],
  );

  useEffect(() => {
    if (!sessionId) return;
    setIsConfirming(true);
    attemptsRef.current = 0;

    const tick = () => {
      attemptsRef.current += 1;
      queryClient.invalidateQueries({ queryKey: [PAID_COMPUTE_ELIGIBILITY_QUERY_KEY] });
      queryClient.invalidateQueries({ queryKey: [SUBSCRIBER_ROW_QUERY_KEY] });
      if (attemptsRef.current >= MAX_POLL_ATTEMPTS) {
        toast.warning("We couldn't confirm your subscription yet. Refresh the page in a moment.");
        stop(true);
      }
    };

    intervalRef.current = window.setInterval(tick, POLL_INTERVAL_MS);
    return () => {
      if (intervalRef.current !== null) {
        window.clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [sessionId, queryClient, stop]);

  useEffect(() => {
    if (!sessionId) return;
    if (isEligible === true) {
      toast.success("Subscription active");
      stop(true);
    }
  }, [isEligible, sessionId, stop]);

  return { isConfirming };
};
