import { Check, CheckCircle2, ChevronDown, ChevronRight, Copy, ExternalLink } from "lucide-react";
import type React from "react";
import { useState } from "react";
import SnowflakeIcon from "@/shared/components/icons/SnowflakeIcon";
import { Button } from "@/shared/components/ui/button";

// Resolved at build time. In any non-Snowflake build (notably the Databricks 3P
// Marketplace bundle, where VITE_SNOWFLAKE_MODE is undefined) Vite's `define`
// makes this fold to "" and esbuild drops the string `"https://app.snowflake.com"`
// from the chunk — satisfying the Marketplace egress declaration.
const SNOWFLAKE_DASHBOARD_URL: string =
  import.meta.env.VITE_SNOWFLAKE_MODE === "true" ? "https://app.snowflake.com" : "";

interface ComputeSwitchOverlayProps {
  isVisible: boolean;
  poolName: string;
  onDismiss: () => void;
}

/**
 * Full-screen overlay shown after a compute pool switch has been initiated.
 *
 * In Snowflake SPCS, switching compute triggers init() which destroys and recreates
 * all services -- including this frontend. The URL changes, so polling from the old
 * URL is impossible. Instead we show a static message directing the user to the
 * Snowflake dashboard to find the app once it's back up.
 */
export const ComputeSwitchOverlay: React.FC<ComputeSwitchOverlayProps> = ({
  isVisible,
  poolName,
  onDismiss,
}) => {
  const [showLogQuery, setShowLogQuery] = useState(false);
  const [copied, setCopied] = useState(false);

  if (!isVisible) return null;

  const logQuery = `SELECT
    TIMESTAMP                      AS time_utc,
    VALUE::STRING                  AS message
FROM SNOWFLAKE.TELEMETRY.EVENTS
WHERE RECORD_TYPE = 'LOG'
  AND TIMESTAMP > DATEADD('minute', -10, CURRENT_TIMESTAMP())
  AND (
        RESOURCE_ATTRIBUTES['snow.application.name'] = 'PROMETHEUX'
        OR RESOURCE_ATTRIBUTES['snow.database.name'] = 'PROMETHEUX'
      )
ORDER BY time_utc DESC
LIMIT 200;`;

  const handleCopyQuery = async () => {
    try {
      await navigator.clipboard.writeText(logQuery);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // fallback
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/95 backdrop-blur-sm">
      <div className="max-w-lg w-full mx-4 p-8 bg-card border rounded-xl shadow-2xl space-y-6">
        {/* Header */}
        <div className="flex flex-col items-center text-center space-y-3">
          <div className="flex items-center justify-center w-14 h-14 rounded-full bg-green-100 dark:bg-green-900/30">
            <CheckCircle2 className="w-8 h-8 text-green-600 dark:text-green-400" />
          </div>
          <h2 className="text-xl font-semibold">Compute Switch Initiated</h2>
          <p className="text-sm text-muted-foreground">
            The platform is being restarted on compute pool{" "}
            <span className="font-mono font-medium text-foreground">{poolName}</span>.
          </p>
        </div>

        {/* Explanation */}
        <div className="bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded-lg p-4 space-y-3">
          <p className="text-sm text-amber-900 dark:text-amber-200 font-medium">
            What happens now?
          </p>
          <ul className="text-sm text-amber-800 dark:text-amber-300 space-y-2 list-disc list-inside">
            <li>All platform services are restarting on the new compute pool</li>
            <li>This page will stop working as the application URL changes</li>
            <li>The restart typically takes 2-5 minutes</li>
          </ul>
        </div>

        {/* Instructions */}
        <div className="space-y-3">
          <p className="text-sm font-medium">To access the app after restart:</p>
          <ol className="text-sm text-muted-foreground space-y-2 list-decimal list-inside">
            <li>
              Open your Snowflake dashboard (<strong>Snowsight</strong>)
            </li>
            <li>
              In the left sidebar, go to <strong>Catalog</strong> &rarr; <strong>Apps</strong>
            </li>
            <li>
              Find and open the <strong>Prometheux</strong> application
            </li>
            <li>
              Wait until the app status shows <strong>Ready</strong>, then click to open it
            </li>
            <li>
              Once prompted to the Prometheux app, it may be necessary to click{" "}
              <strong>Retry</strong> to effectively restart it
            </li>
          </ol>
        </div>

        {/* Monitor logs query */}
        <div className="border rounded-lg overflow-hidden">
          <button
            type="button"
            className="w-full flex items-center gap-2 px-3 py-2 text-sm font-medium text-left hover:bg-muted/50 transition-colors"
            onClick={() => setShowLogQuery(!showLogQuery)}
          >
            {showLogQuery ? (
              <ChevronDown className="w-3.5 h-3.5 text-muted-foreground" />
            ) : (
              <ChevronRight className="w-3.5 h-3.5 text-muted-foreground" />
            )}
            Monitor restart logs via SQL worksheet
          </button>
          {showLogQuery && (
            <div className="border-t px-3 py-3 space-y-2 bg-muted/30">
              <p className="text-xs text-muted-foreground">
                Run this query in a Snowflake SQL worksheet to monitor the restart progress:
              </p>
              <div className="relative">
                <pre className="text-[11px] font-mono bg-background border rounded-md p-3 overflow-x-auto whitespace-pre">
                  {logQuery}
                </pre>
                <Button
                  variant="ghost"
                  size="sm"
                  className="absolute top-1.5 right-1.5 h-7 w-7 p-0"
                  onClick={handleCopyQuery}
                >
                  {copied ? (
                    <Check className="w-3.5 h-3.5 text-green-600" />
                  ) : (
                    <Copy className="w-3.5 h-3.5" />
                  )}
                </Button>
              </div>
            </div>
          )}
        </div>

        {/* Actions */}
        <div className="flex flex-col gap-3 pt-2">
          {SNOWFLAKE_DASHBOARD_URL && (
            <Button
              variant="default"
              className="w-full"
              onClick={() => {
                window.open(SNOWFLAKE_DASHBOARD_URL, "_blank");
              }}
            >
              <SnowflakeIcon className="w-4 h-4 mr-2" />
              Open Snowflake Dashboard
              <ExternalLink className="w-3 h-3 ml-2" />
            </Button>
          )}
          <Button variant="outline" className="w-full" onClick={onDismiss}>
            Dismiss
          </Button>
        </div>
      </div>
    </div>
  );
};
