/**
 * Auto-indentation utility for concept cell code
 * Formats code according to the rule:
 * rule head :-
 * tab tab body concept,
 * tab tab body concept,
 * ... full stop
 */

export function autoIndentCode(code: string): string {
  if (!code || code.trim() === "") {
    return code;
  }

  const lines = code.split("\n");
  const formattedLines: string[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmedLine = line.trim();

    // Skip empty lines
    if (trimmedLine === "") {
      formattedLines.push("");
      continue;
    }

    // Check if this is a rule head (contains :-)
    if (trimmedLine.includes(":-")) {
      // Rule head - no indentation
      formattedLines.push(trimmedLine);
    }
    // Check if this is a body concept (contains parentheses and comma or period)
    else if (
      trimmedLine.includes("(") &&
      (trimmedLine.includes(",") || trimmedLine.includes("."))
    ) {
      // Body concept - add one tab
      formattedLines.push(`\t${trimmedLine}`);
    }
    // Check if this is a comment (starts with %)
    else if (trimmedLine.startsWith("%")) {
      // Comment - keep as is
      formattedLines.push(trimmedLine);
    }
    // Default case - keep original indentation
    else {
      formattedLines.push(line);
    }
  }

  return formattedLines.join("\n");
}
