import type { UploadFileResult } from "@/features/data-sources/api/DataClient";
import type { DataSource } from "@/features/data-sources/types";
import { isFileType } from "@/shared/components/icons/fileTypeIconMap";

export interface TypeGroup {
  type: string;
  dataSources: DataSource[];
}

export interface SubGroup {
  name: string;
  type: string;
  dataSources: DataSource[];
  typeGroups: TypeGroup[];
}

export interface LocationGroup {
  location: string;
  subGroups: SubGroup[];
}

/**
 * Explain what an upload did beyond writing bytes: overwriting a connected file
 * changes what its data source points at, and the backend re-infers the schema
 * so the source's columns keep matching the file.
 */
export const buildUploadDescription = (result: UploadFileResult): string | undefined => {
  if (!result.replacedExisting) return undefined;
  const count = result.resyncedDataSources.length;
  if (count === 0) return "Replaced the existing file";
  const sources = count === 1 ? "data source" : "data sources";
  return `Replaced the existing file — schema updated for ${count} connected ${sources}`;
};

export const extractDatabaseInfo = (bindAnnotation: string) => {
  // Handle both @bind and @qbind annotations
  const bindMatch = bindAnnotation.match(/@bind\("([^"]+)",\s*"([^"]+)"/);
  const qbindMatch = bindAnnotation.match(/@qbind\("([^"]+)",\s*"([^"]+)"/);

  const match = bindMatch || qbindMatch;
  const isQbind = !!qbindMatch;

  if (!match) {
    return {
      type: "Unknown",
      connectionString: "Unknown connection",
      connectionId: "unknown",
    };
  }

  const connectionString = match[2];
  let type = connectionString.split(" ")[0];

  // For qbind, the second parameter is often just the database type
  if (isQbind) {
    type = connectionString.toLowerCase();
    // Handle common database type mappings
    if (type === "mariadb") {
      type = "MariaDB";
    } else if (type === "postgresql" || type === "postgres") {
      type = "PostgreSQL";
    } else if (type === "mysql") {
      type = "MySQL";
    } else {
      // Capitalize first letter for display
      type = type.charAt(0).toUpperCase() + type.slice(1);
    }
  }

  // Create a unique connection ID based on the third argument of the bind annotation
  // Format: @bind("table_name", "type", "database_name_or_path", ...)
  // Format: @qbind("table_name", "type", "database_name_or_path", ...)
  let connectionId = "";

  const prefix = isQbind ? "qbind" : "bind";
  const thirdArgMatch = bindAnnotation.match(
    isQbind ? /@qbind\("[^"]+",\s*"[^"]+",\s*"([^"]+)"/ : /@bind\("[^"]+",\s*"[^"]+",\s*"([^"]+)"/,
  );

  const databaseIdentifier = thirdArgMatch ? thirdArgMatch[1] : "unknown";
  connectionId = `${type.toLowerCase()}_${prefix}_${databaseIdentifier}`;

  return {
    type,
    connectionString,
    connectionId,
  };
};

export const getConnectionDisplayName = (
  type: string,
  _connectionString: string,
  bindAnnotation?: string,
) => {
  const normalizedType = type.charAt(0).toUpperCase() + type.slice(1).toLowerCase();
  const isQbind = bindAnnotation?.includes("@qbind");
  let identifier = "unknown";

  // Extract identifier from the third argument of the bind annotation
  // Format: @bind("table_name", "type", "database_name_or_path", ...)
  // Format: @qbind("table_name", "type", "database_name_or_path", ...)
  if (bindAnnotation) {
    const thirdArgMatch = bindAnnotation.match(
      isQbind
        ? /@qbind\("[^"]+",\s*"[^"]+",\s*"([^"]+)"/
        : /@bind\("[^"]+",\s*"[^"]+",\s*"([^"]+)"/,
    );

    if (thirdArgMatch?.[1]) {
      identifier = thirdArgMatch[1];

      // For file-based sources (CSV, Parquet), extract just the directory name
      if (
        ["Csv", "Parquet", "Json", "Ttl", "Rdf", "Owl", "Yaml", "Cobol"].includes(normalizedType)
      ) {
        const pathParts = identifier.split(/[\\/]/).filter(Boolean);
        identifier = pathParts[pathParts.length - 1] || identifier;
      }
    }
  }

  return `${normalizedType} - ${identifier}`;
};

const STORAGE_PROTOCOLS: Record<string, string> = {
  "s3://": "s3",
  "s3a://": "s3",
  "gs://": "gcs",
  "abfss://": "azure",
  "wasbs://": "azure",
  "hdfs://": "hdfs",
};

/**
 * Detects the storage system icon type from a group name (location path).
 * Returns null for database groups so the caller can fall back to the DB type.
 */
export const getStorageIconType = (groupName: string): string | null => {
  if (groupName === "Local Files") return "local";
  const lowerName = groupName.toLowerCase();
  for (const [prefix, iconType] of Object.entries(STORAGE_PROTOCOLS)) {
    if (lowerName.startsWith(prefix)) return iconType;
  }
  return null;
};

/**
 * Returns the icon type for a sub-group collapsible header.
 * For file-storage groups (S3, local, etc.) returns the storage system type.
 * For database groups returns the datasource type of the group.
 */
export const getGroupIconType = (subGroupName: string, subGroupType: string): string => {
  return getStorageIconType(subGroupName) ?? subGroupType;
};

/**
 * Groups data sources by location first, then by group_by field
 * Uses the location, type, and group_by fields provided by the backend
 */
export const groupDataSourcesByLocationAndType = (dataSources: DataSource[]): LocationGroup[] => {
  const locationMap = new Map<string, Map<string, DataSource[]>>();

  dataSources.forEach((dataSource) => {
    const location = dataSource.location || "Unknown";
    const groupBy = dataSource.groupBy || "unknown";

    if (!locationMap.has(location)) {
      locationMap.set(location, new Map());
    }

    const groupMap = locationMap.get(location)!;
    if (!groupMap.has(groupBy)) {
      groupMap.set(groupBy, []);
    }

    groupMap.get(groupBy)!.push(dataSource);
  });

  // Convert to array format and sort
  const locationGroups: LocationGroup[] = Array.from(locationMap.entries()).map(
    ([location, groupMap]) => {
      const subGroups: SubGroup[] = Array.from(groupMap.entries()).map(([groupName, sources]) => {
        const sorted = sources.sort((a, b) => {
          const timestampA = a.timestamp || "";
          const timestampB = b.timestamp || "";
          return timestampB.localeCompare(timestampA);
        });

        const typeMap = new Map<string, DataSource[]>();
        sorted.forEach((ds) => {
          const t = ds.datasourceType || "unknown";
          if (!typeMap.has(t)) typeMap.set(t, []);
          typeMap.get(t)!.push(ds);
        });

        const typeGroups: TypeGroup[] = Array.from(typeMap.entries())
          .map(([type, dsList]) => ({ type, dataSources: dsList }))
          .sort((a, b) => a.type.localeCompare(b.type));

        return {
          name: groupName,
          type: sorted[0]?.datasourceType || "unknown",
          dataSources: sorted,
          typeGroups,
        };
      });

      subGroups.sort((a, b) => a.name.localeCompare(b.name));

      return { location, subGroups };
    },
  );

  // Sort location groups alphabetically
  locationGroups.sort((a, b) => a.location.localeCompare(b.location));

  return locationGroups;
};

/**
 * Builds a display path for a data source from its DataSource fields.
 *
 * For file-based sources the bind annotation stores the directory/URI as
 * `database` (mapped to `databaseName`) and the actual filename as
 * `table_name` (mapped to `tableName`, already shown as the display name).
 *
 * Returns the full path (dir + file) when possible, falling back to
 * just the directory or file alone.
 */
export const getDataSourcePath = (ds: {
  databaseName?: string;
  tableName?: string;
}): string | null => {
  const dir = ds.databaseName;
  if (!dir) return null;

  const file = ds.tableName;
  if (!file) return dir;

  const normalizedDir = dir.endsWith("/") ? dir : `${dir}/`;
  return `${normalizedDir}${file}`;
};

export const generateMockModelAnnotation = (
  tableName: string,
  fields: Record<string, string> = {},
): string => {
  const fieldEntries = Object.entries(fields)
    .map(([field, type]) => `${field}:${type}`)
    .join(", ");
  return `@model("${tableName}", "${fieldEntries}")`;
};

/**
 * Extracts filename from the 4th argument of bind annotation
 * Format: @bind("table_name", "type", "database_name_or_path", "filename")
 */
export const extractFilenameFromBind = (bindAnnotation: string): string | null => {
  const bindMatch = bindAnnotation.match(/@bind\("[^"]+",\s*"[^"]+",\s*"[^"]+",\s*"([^"]+)"/);
  const qbindMatch = bindAnnotation.match(/@qbind\("[^"]+",\s*"[^"]+",\s*"[^"]+",\s*"([^"]+)"/);

  const match = bindMatch || qbindMatch;
  return match ? match[1] : null;
};

/**
 * Extracts file extension from filename
 */
export const getFileExtensionFromFilename = (filename: string): string | null => {
  const extension = filename.split(".").pop()?.toLowerCase();
  return extension || null;
};

/**
 * Gets the appropriate database type for icon display based on file extension for binary files
 */
export const getIconTypeForBinaryFile = (bindAnnotation: string): string => {
  const { type } = extractDatabaseInfo(bindAnnotation);

  // If it's a binary file, derive the icon token from the filename extension.
  // We delegate to the shared file-icon map (the single authority for what counts
  // as a file type) and return the RAW extension when it's known — so the icon
  // matches the Files tab exactly. Unknown extensions fall back to the generic
  // binary icon. This avoids maintaining a second extension list that could drift.
  if (type.toLowerCase() === "binaryfile") {
    const filename = extractFilenameFromBind(bindAnnotation);
    const extension = filename ? getFileExtensionFromFilename(filename) : null;
    return extension && isFileType(extension) ? extension : "binaryfile";
  }

  // If the type looks like a connection string (e.g. "postgresql://..."), extract just the protocol
  if (type.includes("://")) {
    return type.split("://")[0].toLowerCase();
  }

  return type;
};

/**
 * Extracts database type from a node ID or connection string
 * This is useful for lineage views where node IDs might be database names
 * rather than explicit database types
 */
export const extractDatabaseTypeFromNodeId = (nodeId: string): string => {
  const lowerNodeId = nodeId.toLowerCase();

  // Check for common database type patterns in node IDs
  if (lowerNodeId.includes("postgres") || lowerNodeId.includes("postgresql")) {
    return "postgresql";
  }
  if (lowerNodeId.includes("mongo") || lowerNodeId.includes("mongodb")) {
    return "mongodb";
  }
  if (lowerNodeId.includes("mysql")) {
    return "mysql";
  }
  if (lowerNodeId.includes("mariadb")) {
    return "mariadb";
  }
  if (lowerNodeId.includes("sqlite")) {
    return "sqlite";
  }
  if (
    lowerNodeId.includes("sqlserver") ||
    lowerNodeId.includes("mssql") ||
    lowerNodeId.includes("sql_server")
  ) {
    return "sqlserver";
  }
  if (lowerNodeId.includes("clickhouse")) {
    return "clickhouse";
  }
  if (lowerNodeId.includes("neo4j")) {
    return "neo4j";
  }
  if (lowerNodeId.includes("redis")) {
    return "redis";
  }
  if (lowerNodeId.includes("qdrant")) {
    return "qdrant";
  }
  if (lowerNodeId.includes("databricks")) {
    return "databricks";
  }
  if (lowerNodeId.includes("parquet")) {
    return "parquet";
  }
  if (lowerNodeId.includes("csv")) {
    return "csv";
  }
  if (lowerNodeId.includes("ttl") || lowerNodeId.includes(".ttl")) {
    return "ttl";
  }
  if (lowerNodeId.includes(".rdf") || lowerNodeId.endsWith("rdf")) {
    return "rdf";
  }
  if (lowerNodeId.includes(".owl") || lowerNodeId.endsWith("owl")) {
    return "owl";
  }
  if (lowerNodeId.includes("yaml") || lowerNodeId.includes(".yml")) {
    return "yaml";
  }
  if (
    lowerNodeId.includes("cobol") ||
    lowerNodeId.includes(".cob") ||
    lowerNodeId.includes(".cbl")
  ) {
    return "cobol";
  }

  // If no specific type found, return generic database type
  return "database";
};
