import { RefreshCw, Server } from "lucide-react";
import type React from "react";
import { useCallback, useRef, useState } from "react";
import * as Icons from "simple-icons";
import ComputeIndicator from "@/features/compute/components/ComputeIndicator";
import ComputeTab, { type ComputeActiveTab } from "@/features/compute/components/ComputeTab";
import { SimpleIcon } from "@/features/compute/utils";
import SnowflakeIcon from "@/shared/components/icons/SnowflakeIcon";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import SidePanel from "@/shared/components/layout/SidePanel";
import { Button } from "@/shared/components/ui/button";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";

const Compute: React.FC = () => {
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [activeTab, setActiveTab] = useState<ComputeActiveTab>("pools");
  const refreshFnRef = useRef<(() => Promise<void>) | null>(null);

  const isSnowflake = PROMETHEUX_CONFIG.SNOWFLAKE_MODE;
  const isDatabricksMode = PROMETHEUX_CONFIG.DATABRICKS_UI_MODE;

  const handleRefreshReady = useCallback((fn: () => Promise<void>) => {
    refreshFnRef.current = fn;
  }, []);

  const handleRefresh = async () => {
    if (!refreshFnRef.current) return;
    setIsRefreshing(true);
    try {
      await refreshFnRef.current();
    } finally {
      setIsRefreshing(false);
    }
  };

  const tabClass = (key: ComputeActiveTab) =>
    `flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium transition-colors ${
      activeTab === key
        ? "border-b-2 border-primary text-primary"
        : "text-muted-foreground hover:text-foreground"
    }`;

  const marginClass = sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0";

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="compute"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-col flex-1 ${marginClass} overflow-hidden transition-all duration-200`}
      >
        <PageHeader
          title="Compute"
          subtitle="Manage your compute resources and cluster configurations"
          icon={Server}
          actions={
            <>
              <ComputeIndicator interactive={true} />
              <Button variant="outline" size="icon" onClick={handleRefresh} disabled={isRefreshing}>
                <RefreshCw className={`h-4 w-4 ${isRefreshing ? "animate-spin" : ""}`} />
              </Button>
            </>
          }
        />

        {!isDatabricksMode && (
          <div className="flex border-b border-border px-6">
            <button
              type="button"
              onClick={() => setActiveTab("pools")}
              className={tabClass("pools")}
            >
              {isSnowflake ? <SnowflakeIcon className="h-4 w-4" /> : <Server className="h-4 w-4" />}
              {isSnowflake ? "Snowflake Pools" : "Compute Pools"}
            </button>

            <button
              type="button"
              onClick={() => setActiveTab("databricks")}
              className={tabClass("databricks")}
            >
              <SimpleIcon iconData={Icons.siDatabricks} size={16} />
              Databricks
            </button>
          </div>
        )}

        <div className="@container flex-1 overflow-y-auto min-h-0">
          <ComputeTab activeTab={activeTab} onRefreshReady={handleRefreshReady} />
        </div>
      </div>
    </div>
  );
};

export default Compute;
