  async startCluster(clusterId: string): Promise<{ status: string; message: string }> {
    const config = DatabricksConfigService.getConfig();

    if (!config.workspaceUrl) {
      throw new Error("Workspace URL is required for cluster operations");
    }

    const body: any = {
      clusterId,
      host: config.workspaceUrl,
      auth_mode: config.authMode,
    };

    if (config.authMode === "token" && config.token) {
      body.token = config.token; // Works for both PAT and OAuth tokens
    } else if (config.authMode === "oauth2" && config.clientId && config.clientSecret) {
      body.client_id = config.clientId;
      body.client_secret = config.clientSecret;
    }

    if (config.defaultCatalog) body.catalog = config.defaultCatalog;
    if (config.defaultSchema) body.schema = config.defaultSchema;
    if (config.defaultVolume) body.volume = config.defaultVolume;
    if (config.jarFileName) body.jarFileName = config.jarFileName;

    return this.makeRequest(`/clusters/start`, {
      method: "POST",
      body: JSON.stringify(body),
    });
  }

