  async createCluster(
    clusterConfig: any,
  ): Promise<{ status: string; message: string; cluster_id?: string }> {
    const config = DatabricksConfigService.getConfig();

    if (!config.workspaceUrl) {
      throw new Error("Workspace URL is required for cluster creation");
    }

    const body: any = {
      host: config.workspaceUrl,
      sparkVersion: clusterConfig.sparkVersion,
      nodeTypeId: clusterConfig.nodeTypeId,
      authMode: config.authMode,
    };

    // Add authentication
    if (config.authMode === "token" && config.token) {
      body.token = config.token;
    } else if (config.authMode === "oauth2" && config.clientId && config.clientSecret) {
      body.clientId = config.clientId;
      body.clientSecret = config.clientSecret;
    }

    // Add optional fields
    if (clusterConfig.clusterName) body.clusterName = clusterConfig.clusterName;
    if (clusterConfig.numWorkers !== undefined) body.numWorkers = clusterConfig.numWorkers;
    if (clusterConfig.autoscale) body.autoscale = clusterConfig.autoscale;
    if (clusterConfig.driverNodeTypeId) body.driverNodeTypeId = clusterConfig.driverNodeTypeId;
    if (clusterConfig.autoterminationMinutes)
      body.autoterminationMinutes = clusterConfig.autoterminationMinutes;
    if (clusterConfig.sparkConf) body.sparkConf = clusterConfig.sparkConf;
    if (clusterConfig.sparkEnvVars) body.sparkEnvVars = clusterConfig.sparkEnvVars;
    if (clusterConfig.customTags) body.customTags = clusterConfig.customTags;

    // Security fields
    if (clusterConfig.dataSecurityMode) body.dataSecurityMode = clusterConfig.dataSecurityMode;
    if (clusterConfig.singleUserName) body.singleUserName = clusterConfig.singleUserName;

    // Advanced fields
    if (clusterConfig.enableElasticDisk !== undefined)
      body.enableElasticDisk = clusterConfig.enableElasticDisk;
    if (clusterConfig.runtimeEngine) body.runtimeEngine = clusterConfig.runtimeEngine;

    return this.makeRequest(`/clusters/create`, {
      method: "POST",
      body: JSON.stringify(body),
    });
  }

  // Prometheux Installation
  async installPrometheux(
    clusterId: string,
    catalog?: string,
    schema?: string,
    volume?: string,
  ): Promise<PrometheuxInstallationResponse> {
    const config = DatabricksConfigService.getConfig();

    if (!config.workspaceUrl) {
      throw new Error("Workspace URL is required for Prometheux installation");
    }

    // Build request body with auth parameters
    const body: any = {
      cluster_id: clusterId,
      host: config.workspaceUrl,
      auth_mode: config.authMode,
    };

    // Add optional catalog, schema, and volume parameters
    if (catalog) {
      body.catalog = catalog;
    }
    if (schema) {
      body.schema = schema;
    }
    if (volume) {
      body.volume = volume;
    }

    // Add authentication credentials based on auth mode
    if (config.authMode === "token" && config.token) {
      body.token = config.token;
    } else if (config.authMode === "oauth2" && config.clientId && config.clientSecret) {
      body.client_id = config.clientId;
      body.client_secret = config.clientSecret;
    } else {
      throw new Error(`Missing credentials for ${config.authMode} authentication mode`);
    }

    // Use custom fetch to avoid unwrapping the response
    const url = `${this.baseUrl}/install-prometheux`;
    const fetchResponse = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${this.authToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    });

    const responseText = await fetchResponse.text();
    let result: any;

    try {
      result = JSON.parse(responseText);
    } catch (_parseError) {
      throw new Error(`Invalid response: ${responseText}`);
    }

    // Check the backend's status field, not HTTP status
    if (result.status === "error") {
      let cleanMessage = result.message || "Installation failed";
      cleanMessage = cleanMessage
        .replace(
          /^Error (creating|listing|deleting|updating|installing) \w+: Failed to \1 \w+: /,
          "",
        )
        .replace(/^Failed to \w+ \w+: /, "");
      throw new Error(cleanMessage);
    }

    return result as PrometheuxInstallationResponse;
  }

