  // Check Prometheux Installation Status
  async checkPrometheuxStatus(clusterId: string): Promise<PrometheuxStatusResponse> {
    const config = DatabricksConfigService.getConfig();

    if (!config.workspaceUrl) {
      throw new Error("Workspace URL is required to check Prometheux status");
    }

    const params = this.buildDatabricksParams(config.authMode);

    // Backend now has auto-discovery - no need to send catalog/schema/volume
    const url = `${this.baseUrl}/clusters/${clusterId}/prometheux/status?${params}`;

    const response = await fetch(url, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${this.authToken}`,
        "Content-Type": "application/json",
      },
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Databricks API error: ${response.status} - ${errorText}`);
    }

    const result = await response.json();
    return result as PrometheuxStatusResponse;
  }

