  async uploadFile(
    catalogName: string,
    schemaName: string,
    volumeName: string,
    filePath: string,
    file: File,
  ): Promise<{ status: string; message: string }> {
    const formData = new FormData();
    formData.append("catalog", catalogName);
    formData.append("schema", schemaName);
    formData.append("volume", volumeName);
    formData.append("file_path", filePath);
    formData.append("file", file);

    const response = await fetch(`${this.baseUrl}/volumes/files/upload`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${this.authToken}`,
      },
      body: formData,
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`File upload error: ${response.status} - ${errorText}`);
    }

    return response.json();
  }

