import { create } from "zustand";

export type LineageConceptStatusMap = Record<
  string,
  { status: "running" | "success" | "error" | "skipped"; error?: string }
>;

interface LineageRunStatusState {
  /**
   * Per-concept statuses recovered from the backend when reconnecting to an
   * in-flight (or just-finished) run. Published by useReconnectExecutionStatus
   * and consumed by useConceptExecutionStatus, which live in different parts of
   * the lineage tree (Lineage wrapper vs. deep inside LineageView). Delivering
   * them as shared state — rather than a transient window event — means they
   * survive the mount race between the lineage data load and the graph view.
   */
  reconnectStatuses: LineageConceptStatusMap | null;
  setReconnectStatuses: (statuses: LineageConceptStatusMap | null) => void;
}

export const useLineageRunStatusStore = create<LineageRunStatusState>((set) => ({
  reconnectStatuses: null,
  setReconnectStatuses: (reconnectStatuses) => set({ reconnectStatuses }),
}));
