import { ChevronDown, ChevronRight, Plus, Trash2 } from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import type { AppConcept } from "../../api/ConceptClient";
import type { DashboardSection, DashboardWidget, SectionLayout } from "../../types";
import { WidgetConfigRow } from "./WidgetConfigRow";

export const SECTION_LAYOUTS: { value: SectionLayout; label: string }[] = [
  { value: "single", label: "Single column" },
  { value: "two_col", label: "Two columns" },
  { value: "four_col", label: "Four columns" },
];

export interface SectionEditorProps {
  section: DashboardSection;
  concepts: AppConcept[];
  knownColumnsMap: Record<string, string[]>;
  onChange: (s: DashboardSection) => void;
  onRemove: () => void;
}

export function SectionEditor({
  section,
  concepts,
  knownColumnsMap,
  onChange,
  onRemove,
}: SectionEditorProps) {
  const [expanded, setExpanded] = useState(true);

  const addWidget = () => {
    onChange({
      ...section,
      widgets: [
        ...section.widgets,
        { id: crypto.randomUUID(), type: "stat_card", conceptName: "", xCol: 0, yCol: 1 },
      ],
    });
  };

  const updateWidget = (id: string, w: DashboardWidget) => {
    onChange({ ...section, widgets: section.widgets.map((ww) => (ww.id === id ? w : ww)) });
  };

  const removeWidget = (id: string) => {
    onChange({ ...section, widgets: section.widgets.filter((ww) => ww.id !== id) });
  };

  return (
    <div className="border border-dashed border-border rounded-md">
      <div className="flex items-center gap-2 px-3 py-2 bg-secondary/30 rounded-t-md">
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          className="text-muted-foreground hover:text-foreground"
        >
          {expanded ? (
            <ChevronDown className="h-3.5 w-3.5" />
          ) : (
            <ChevronRight className="h-3.5 w-3.5" />
          )}
        </button>

        <Input
          value={section.title ?? ""}
          onChange={(e) => onChange({ ...section, title: e.target.value })}
          placeholder="Section title (optional)"
          className="h-6 text-xs flex-1 bg-transparent border-0 shadow-none focus-visible:ring-0 p-0"
        />

        <Select
          value={section.layout}
          onValueChange={(v) => onChange({ ...section, layout: v as SectionLayout })}
        >
          <SelectTrigger className="h-6 text-xs w-28">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {SECTION_LAYOUTS.map((l) => (
              <SelectItem key={l.value} value={l.value} className="text-xs">
                {l.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Button
          variant="ghost"
          size="iconSm"
          onClick={onRemove}
          className="text-muted-foreground hover:text-destructive h-6 w-6"
        >
          <Trash2 className="h-3 w-3" />
        </Button>
      </div>

      {expanded && (
        <div className="p-3 flex flex-col gap-2">
          {section.widgets.map((widget) => (
            <WidgetConfigRow
              key={widget.id}
              widget={widget}
              concepts={concepts}
              knownColumns={knownColumnsMap[widget.conceptName]}
              onChange={(w) => updateWidget(widget.id, w)}
              onRemove={() => removeWidget(widget.id)}
            />
          ))}
          <Button
            variant="ghost"
            size="sm"
            onClick={addWidget}
            className="gap-1.5 h-7 text-xs text-muted-foreground self-start"
          >
            <Plus className="h-3 w-3" /> Add widget
          </Button>
        </div>
      )}
    </div>
  );
}
