import type {
  ConceptCell,
  ConceptType,
  ContextMode,
  LlmConceptConfig,
  LlmConnectionHint,
  LlmOutputColumn,
} from "@/features/concept-editor/types";

const UNGROUPED = "group_id";

export interface ParsedContextConfig {
  mode: ContextMode;
  noteIds: string[];
  query: string;
  topK?: number;
  kinds?: string[];
}

/**
 * Parse a context concept's `concept_config` as returned by the concepts-list
 * read path into the fields the editor cell needs. Postgres JSON may arrive as
 * an object or a raw string, so parse defensively. Static concepts carry
 * `note_ids`; dynamic concepts carry `query` (+ optional `top_k`/`kinds`).
 */
export function parseContextConfig(config: unknown): ParsedContextConfig {
  const empty: ParsedContextConfig = { mode: "static", noteIds: [], query: "" };
  if (!config) return empty;
  let parsed: unknown = config;
  if (typeof config === "string") {
    try {
      parsed = JSON.parse(config);
    } catch {
      return empty;
    }
  }
  if (typeof parsed !== "object" || parsed === null) return empty;
  const obj = parsed as {
    mode?: unknown;
    note_ids?: unknown;
    query?: unknown;
    top_k?: unknown;
    kinds?: unknown;
  };
  const mode: ContextMode = obj.mode === "dynamic" ? "dynamic" : "static";
  const noteIds = Array.isArray(obj.note_ids)
    ? obj.note_ids.filter((id): id is string => typeof id === "string")
    : [];
  const query = typeof obj.query === "string" ? obj.query : "";
  const topK = typeof obj.top_k === "number" ? obj.top_k : undefined;
  const kinds = Array.isArray(obj.kinds)
    ? obj.kinds.filter((k): k is string => typeof k === "string")
    : undefined;
  return { mode, noteIds, query, topK, kinds };
}

/**
 * Back-compat helper: just the pinned note ids from a concept's `concept_config`.
 */
export function parseContextNoteIds(config: unknown): string[] {
  return parseContextConfig(config).noteIds;
}

/**
 * Map a context concept's `concept_config` to the editor cell fields, so load and
 * refresh set mode/query/notes consistently from one place.
 */
export function contextCellFieldsFromConfig(
  config: unknown,
): Pick<ConceptCell, "contextMode" | "noteIds" | "contextQuery" | "contextTopK" | "contextKinds"> {
  const parsed = parseContextConfig(config);
  return {
    contextMode: parsed.mode,
    noteIds: parsed.noteIds,
    contextQuery: parsed.query,
    contextTopK: parsed.topK,
    contextKinds: parsed.kinds,
  };
}

function parseConnectionHint(raw: unknown): LlmConnectionHint | undefined {
  if (typeof raw !== "object" || raw === null) return undefined;
  const hint = raw as { provider?: unknown; model?: unknown };
  const provider = typeof hint.provider === "string" && hint.provider ? hint.provider : undefined;
  const model = typeof hint.model === "string" && hint.model ? hint.model : undefined;
  if (!provider && !model) return undefined;
  return { provider, model };
}

/**
 * Parse an llm concept's `concept_config` as returned by the concepts-list read
 * path. Postgres JSON may arrive as an object or a raw string, so parse
 * defensively; unknown/invalid entries collapse to an empty config (single
 * `response` column, user-level LLM settings).
 */
export function parseLlmConfig(config: unknown): LlmConceptConfig {
  if (!config) return {};
  let parsed: unknown = config;
  if (typeof config === "string") {
    try {
      parsed = JSON.parse(config);
    } catch {
      return {};
    }
  }
  if (typeof parsed !== "object" || parsed === null) return {};
  const obj = parsed as {
    output_columns?: unknown;
    provider?: unknown;
    model?: unknown;
    connection?: unknown;
    connection_hint?: unknown;
    temperature?: unknown;
    max_tokens?: unknown;
    row_limit?: unknown;
  };
  const outputColumns = Array.isArray(obj.output_columns)
    ? obj.output_columns
        .filter(
          (col): col is { name: string; type?: unknown } =>
            typeof col === "object" &&
            col !== null &&
            typeof (col as { name?: unknown }).name === "string",
        )
        .map(
          (col): LlmOutputColumn => ({
            name: col.name,
            type: typeof col.type === "string" && col.type ? col.type : "string",
          }),
        )
    : [];
  return {
    output_columns: outputColumns.length > 0 ? outputColumns : undefined,
    provider: typeof obj.provider === "string" && obj.provider ? obj.provider : undefined,
    model: typeof obj.model === "string" && obj.model ? obj.model : undefined,
    connection: typeof obj.connection === "string" && obj.connection ? obj.connection : undefined,
    connection_hint: parseConnectionHint(obj.connection_hint),
    temperature: typeof obj.temperature === "number" ? obj.temperature : undefined,
    max_tokens: typeof obj.max_tokens === "number" ? obj.max_tokens : undefined,
    row_limit: typeof obj.row_limit === "number" ? obj.row_limit : undefined,
  };
}

/**
 * Map an llm concept's `concept_config` to the editor cell fields, so load and
 * refresh set the config consistently from one place.
 */
export function llmCellFieldsFromConfig(config: unknown): Pick<ConceptCell, "llmConfig"> {
  return { llmConfig: parseLlmConfig(config) };
}

/**
 * Starter body for a new Python concept: the `main(params)` entry point ready to
 * edit, with the usage hints (output shape and in-code dependencies) as comments.
 */
export const PYTHON_DEFAULT_CODE = `def main(params):
    # Return the concept's rows as a list of dicts; the dict keys become the
    # output columns. Declare dependencies in-code (each returns a DataFrame):
    #   df = use_px_concept("other_concept")  # another concept's output
    #   rows = use_px_data("my_datasource")   # a connected datasource
    return []
`;

interface CreateConceptCellParams {
  conceptType: ConceptType;
  group?: string;
  autoOpen?: boolean;
  /** Pre-pinned note ids for a new static context cell (bridge from the
   *  concept context panel's "create context concept" affordance). */
  contextNoteIds?: string[];
}

/**
 * Build a fresh cell. Used by every "add cell" handler so the default shape
 * stays in one place. SQL, Cypher and Python cells additionally get an empty
 * `outputPredicate` (they require an explicit concept name). Python cells are
 * seeded with a starter `main()` body. `group` falls back to the ungrouped
 * sentinel.
 */
export function createConceptCell({
  conceptType,
  group,
  autoOpen = false,
  contextNoteIds,
}: CreateConceptCellParams): ConceptCell {
  const requiresExplicitName =
    conceptType === "sql" ||
    conceptType === "cypher" ||
    conceptType === "python" ||
    conceptType === "context" ||
    conceptType === "llm";
  const code = conceptType === "python" ? PYTHON_DEFAULT_CODE : "";
  return {
    id: `cell-${Date.now()}`,
    code,
    result: null,
    isRunning: false,
    isModified: false,
    lastSavedContent: "",
    group: group || UNGROUPED,
    conceptType,
    ...(requiresExplicitName ? { outputPredicate: "" } : {}),
    ...(conceptType === "context"
      ? { contextMode: "static" as ContextMode, noteIds: contextNoteIds ?? [], contextQuery: "" }
      : {}),
    ...(conceptType === "llm" ? { llmConfig: {} } : {}),
    ...(autoOpen ? { autoOpen: true } : {}),
  };
}
