import type { GraphTableQuery } from "@/features/concept-editor/api/ConceptEditorClient";
import { BaseClient } from "@/shared/lib/BaseClient";
import type { GraphViewModel } from "../types";

interface ApiEnvelope {
  status: string;
  message?: string;
  data?: unknown;
}

/** Request body for the graph-analytics endpoint. */
export interface RunAnalyticsRequest {
  column_roles: { source: number; target: number };
  function: string;
  function_params?: Record<string, unknown>;
  project?: { scope: string };
  /** 1-based page of the persisted node-scoring results. */
  page?: number;
  page_size?: number;
  /** Recompute + persist to parquet (first run); false serves an existing page. */
  recompute?: boolean;
  /** Table sort — applied to the table only; the overlay ranking stays fixed. */
  order_by?: GraphTableQuery["order_by"];
  /** Table free-text search — table only. */
  search_term?: GraphTableQuery["search_term"];
  /** Table column filters — table only. */
  column_filters?: GraphTableQuery["column_filters"];
}

function unwrap(response: ApiEnvelope, fallbackMessage: string): unknown {
  if (response.status !== "ok" && response.status !== "success") {
    throw new Error(response.message || fallbackMessage);
  }
  return response.data;
}

class GraphExplorerClient extends BaseClient {
  /**
   * Run a node-scoring analytics function over an edge predicate's output.
   * Returns the raw envelope so callers can reuse `parseConceptGraphResponse`
   * (the response `data` shares the `{nodes, edges}` graph shape, plus
   * `analytics_type` / `analytics_range`).
   */
  async runAnalytics(
    ontologyId: string,
    predicate: string,
    request: RunAnalyticsRequest,
  ): Promise<unknown> {
    const response = (await this.post(
      `/kgs/${encodeURIComponent(ontologyId)}/graph-analytics/${encodeURIComponent(predicate)}`,
      request,
    )) as ApiEnvelope;
    if (response.status !== "ok" && response.status !== "success") {
      throw new Error(response.message || "Graph analytics failed");
    }
    return response;
  }

  async saveModel(
    ontologyId: string,
    scope: string,
    model: GraphViewModel,
  ): Promise<GraphViewModel> {
    const response = await this.post(`/graph-explorer/${encodeURIComponent(ontologyId)}/model`, {
      scope,
      model,
    });
    return unwrap(response, "Failed to save graph model") as GraphViewModel;
  }

  async getModel(ontologyId: string, scope: string): Promise<GraphViewModel | null> {
    const response = await this.get(
      `/graph-explorer/${encodeURIComponent(ontologyId)}/model?scope=${encodeURIComponent(scope)}`,
    );
    const data = unwrap(response, "Failed to load graph model");
    return (data as GraphViewModel | null) ?? null;
  }
}

export const graphExplorerClient = new GraphExplorerClient();
