import type React from "react";
import { Accordion, AccordionItem } from "@/shared/components/ui/accordion";

type DropPosition = "top" | "bottom" | null;

interface CellAccordionShellProps {
  cellId: string;
  /** Backend id when the cell is persisted — used by DOM-based cell lookups. */
  cellBackendId?: string;
  /** Accordion value: the cell id when expanded, empty string when collapsed. */
  open: string;
  onOpenChange: (value: string) => void;
  /** Where a dragged cell would land relative to this one. */
  dropPosition: DropPosition;
  onDragOver: (event: React.DragEvent) => void;
  onDragLeave: (event: React.DragEvent) => void;
  onDrop: (event: React.DragEvent) => void;
  /** Header row and AccordionContent. */
  children: React.ReactNode;
}

/**
 * The outer frame every concept cell shares: drag-and-drop reorder target, drop
 * indicators, and the accordion that expands the cell body.
 */
export function CellAccordionShell({
  cellId,
  cellBackendId,
  open,
  onOpenChange,
  dropPosition,
  onDragOver,
  onDragLeave,
  onDrop,
  children,
}: CellAccordionShellProps) {
  return (
    <div className="relative">
      {dropPosition === "top" && (
        <div
          className="absolute top-0 left-0 right-0 h-1 bg-primary/30 z-10 rounded-full"
          style={{ transform: "translateY(-50%)" }}
        />
      )}

      <Accordion
        type="single"
        className="w-full bg-card border rounded-md transition-colors"
        style={{ minWidth: 0, overflow: "hidden", position: "relative" }}
        value={open}
        onValueChange={onOpenChange}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onDrop={onDrop}
      >
        <AccordionItem
          value={cellId}
          style={{ overflow: "visible" }}
          data-cell-id={cellBackendId || cellId}
          data-cell-client-id={cellId}
        >
          {children}
        </AccordionItem>
      </Accordion>

      {dropPosition === "bottom" && (
        <div
          className="absolute bottom-0 left-0 right-0 h-1 bg-primary/30 z-10 rounded-full"
          style={{ transform: "translateY(50%)" }}
        />
      )}
    </div>
  );
}
