import { Upload } from "lucide-react";

interface ChatDropOverlayProps {
  isVisible: boolean;
}

/**
 * "Drop to attach" affordance covering a chat composer while a file drag is
 * over it. The composer must be positioned (`relative`) for this to land.
 */
export function ChatDropOverlay({ isVisible }: ChatDropOverlayProps) {
  if (!isVisible) return null;
  return (
    <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center gap-2 rounded-2xl border-2 border-primary border-dashed bg-primary/5 font-medium text-primary text-sm">
      <Upload className="h-4 w-4" />
      Drop to attach
    </div>
  );
}
