import { History } from "lucide-react";
import { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import { useChatReservedWidth } from "@/features/code-assistant/hooks/useChatReservedWidth";
import {
  LineageActionItems,
  LineageHeaderActions,
} from "@/features/lineage/components/LineageHeaderActions";
import { EditorHeaderLeft } from "@/features/ontologies/components/header/EditorHeaderLeft";
import { OntologyHeaderOverflow } from "@/features/ontologies/components/header/OntologyHeaderOverflow";
import { OntologyShareButton } from "@/features/ontologies/components/header/OntologyShareButton";
import type { OntologyTab } from "@/features/ontologies/components/header/projectTabs";
import { useOntologyId, useOntologyScope } from "@/features/ontologies/hooks/useOntologyId";
import { SnapshotsSheet } from "@/features/ontologies/snapshots/SnapshotsSheet";
import MainContent from "@/shared/components/layout/MainContent";
import SidePanel from "@/shared/components/layout/SidePanel";
import { Button } from "@/shared/components/ui/button";
import { useTabSwitchEffect } from "@/shared/hooks/tabs/useTabSwitchEffect";
import { useIsVeryNarrowViewport } from "@/shared/hooks/ui/useIsNarrowViewport";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";

// ─── Page ─────────────────────────────────────────────────────────────────────

const Ontology = () => {
  const location = useLocation();
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [snapshotsOpen, setSnapshotsOpen] = useState(false);
  const ontologyId = useOntologyId();
  const ontologyScope = useOntologyScope();

  // The docked AI assistant chat pushes the header narrower, so count its width
  // against the breakpoint when it's open.
  const reservedWidth = useChatReservedWidth();
  const isVeryNarrow = useIsVeryNarrowViewport(reservedWidth);

  // Pick up any schema inferred from the Data Sources page and pre-populate the editor.
  const [code, setCode] = useState(() => {
    const pending = sessionStorage.getItem("pendingInferredSchema");
    if (pending) {
      sessionStorage.removeItem("pendingInferredSchema");
      return pending;
    }
    return "";
  });

  // Canvas tab is purely local state — ontology and lineage are editor-internal
  // views, not navigation destinations. Using the shared useNavigationState hook
  // caused a reset loop: its effects re-applied location.state.activeTab every
  // time activeTab changed, reverting any local tab switch.
  // "ontology" is no longer a top-level tab — the former Lineage view is now
  // labelled "Ontology" (id still "lineage"), and the schema editor moved into
  // the Document view. Coerce any legacy incoming "ontology" tab to "lineage".
  const coerceTab = (tab: OntologyTab): OntologyTab => (tab === "ontology" ? "lineage" : tab);
  const initialTab = coerceTab((location.state?.activeTab as OntologyTab) ?? "lineage");
  const [canvasTab, setCanvasTab] = useState<OntologyTab>(initialTab);
  const applyTab = (tab: OntologyTab) => setCanvasTab(coerceTab(tab));

  // After sidebar collapse/expand transition (300ms), refit the lineage canvas
  useEffect(() => {
    const timer = setTimeout(() => {
      window.dispatchEvent(new Event("lineageFitView"));
    }, 320);
    return () => clearTimeout(timer);
  }, []);

  const isOntologyTab = (tab: string): tab is OntologyTab =>
    tab === "ontology" ||
    tab === "lineage" ||
    tab === "document" ||
    tab === "context" ||
    tab === "app";

  // Keep listening for programmatic switchTab events (e.g. from concept run results)
  useTabSwitchEffect((tab) => {
    if (isOntologyTab(tab)) applyTab(tab);
  });

  const resolveHeaderActions = () => {
    // Share sits to the left of "Ontology versions"; it self-hides for
    // recipients and non-user-scoped projects.
    const shareButton = <OntologyShareButton />;
    const snapshotsButton = (
      <Button
        type="button"
        variant="outline"
        size="iconSm"
        onClick={() => setSnapshotsOpen(true)}
        title="Ontology versions"
      >
        <History className="h-3.5 w-3.5" />
      </Button>
    );

    // Very narrow: every view's actions fold into a single overflow menu alongside
    // the nav tabs + machine dropdown. The menu items differ per view.
    if (isVeryNarrow) {
      const renderOverflowItems = (close: () => void) => {
        if (canvasTab === "lineage") return <LineageActionItems close={close} />;
        return null;
      };
      const hasViewActions = canvasTab === "lineage";

      return (
        <>
          {shareButton}
          {snapshotsButton}
          <OntologyHeaderOverflow
            activeTab={canvasTab}
            onTabChange={applyTab}
            showCompute={hasViewActions}
            renderItems={hasViewActions ? renderOverflowItems : undefined}
          />
        </>
      );
    }

    if (canvasTab === "lineage")
      return (
        <>
          {shareButton}
          {snapshotsButton}
          <LineageHeaderActions />
        </>
      );
    return (
      <>
        {shareButton}
        {snapshotsButton}
      </>
    );
  };
  const headerActions = resolveHeaderActions();

  const handleSnapshotRestored = () => {
    window.location.reload();
  };

  return (
    <div className="flex h-screen overflow-hidden">
      <SidePanel
        activeTab={canvasTab}
        visible={sidebarVisible}
        onTabChange={(tab) => {
          if (isOntologyTab(tab)) applyTab(tab);
        }}
        onToggle={toggleSidebar}
        onCollapsedChange={setSidebarCollapsed}
      />
      <MainContent
        activeTab={canvasTab}
        code={code}
        setCode={setCode}
        sidebarCollapsed={sidebarCollapsed}
        sidebarVisible={sidebarVisible}
        onToggleSidebar={toggleSidebar}
        header={{
          left: (
            <EditorHeaderLeft
              activeTab={canvasTab}
              onTabChange={applyTab}
              showTabs={!isVeryNarrow}
            />
          ),
          actions: headerActions,
        }}
      />
      <SnapshotsSheet
        open={snapshotsOpen}
        onOpenChange={setSnapshotsOpen}
        ontologyId={ontologyId}
        scope={ontologyScope as "user" | "organization"}
        onRestored={handleSnapshotRestored}
      />
    </div>
  );
};

export default Ontology;
