// Single configured origin/base for all federated client apps.
//
// The host stores NO per-app URLs anywhere. Each app's remoteEntry URL is derived from this
// one base plus the stable per-app path convention:
//
//   `${VITE_APPS_BASE_URL}/<dashboardId>/remoteEntry.js`
//
// and `dashboardId` itself comes from the permission key (`can_see_<id>_app`). So a single
// env var + the permissions the user already has is all the host needs to discover every app.
//
//   • Dev (dev:remote): point at a local `serve:all` origin, e.g. http://localhost:4173
//   • Prod: the CDN base, e.g. https://apps.prometheux.ai
//
// When unset, no app is treated as a remote (URL derivation returns null) — federated apps
// simply don't resolve until a base is configured.

export function getAppsBaseUrl(): string {
  return (import.meta.env.VITE_APPS_BASE_URL ?? "").trim().replace(/\/+$/, "");
}

export function remoteEntryUrlFor(dashboardId: string): string | null {
  const base = getAppsBaseUrl();
  if (!base) return null;
  return `${base}/${dashboardId}/remoteEntry.js`;
}
