import { useCallback, useMemo, useState } from "react";

import { createLocalCache } from "@/shared/utils/createLocalCache";

const WIZARD_STATE_TTL_MS = 7 * 24 * 60 * 60 * 1000;

export interface WizardStepDef {
  id: string;
  title: string;
  description?: string;
  canSkip?: boolean;
}

interface WizardPersistedState {
  currentIndex: number;
  completedStepIds: string[];
  skippedStepIds: string[];
}

interface UseWizardStateProps {
  id: string;
  steps: WizardStepDef[];
  userId: string;
}

export interface WizardControls {
  currentStep: WizardStepDef;
  currentIndex: number;
  totalSteps: number;
  completedStepIds: string[];
  skippedStepIds: string[];
  isFirstStep: boolean;
  isLastStep: boolean;
  isComplete: boolean;
  goNext: () => void;
  goPrev: () => void;
  goTo: (stepId: string) => void;
  skipCurrent: () => void;
  markCurrentCompleted: () => void;
  reset: () => void;
}

const wizardCache = (id: string) =>
  createLocalCache<WizardPersistedState>(`wizard_state_${id}`, WIZARD_STATE_TTL_MS);

const initialState = (
  cache: ReturnType<typeof wizardCache>,
  userId: string,
): WizardPersistedState =>
  cache.get(userId) ?? {
    currentIndex: 0,
    completedStepIds: [],
    skippedStepIds: [],
  };

const FRESH_STATE: WizardPersistedState = {
  currentIndex: 0,
  completedStepIds: [],
  skippedStepIds: [],
};

export function useWizardState({ id, steps, userId }: UseWizardStateProps): WizardControls {
  const cache = useMemo(() => wizardCache(id), [id]);
  const [state, setState] = useState<WizardPersistedState>(() => {
    const cached = initialState(cache, userId);
    // If the cached state thinks the wizard is already complete — either
    // because the user finished it on a previous visit, or because the
    // steps array shape changed since the cache was written — return a
    // fresh state. Otherwise the Wizard fires `onComplete` on mount, the
    // parent navigates away, the empty-state gate redirects back, and
    // the wizard remounts with the same cached state → infinite loop.
    if (cached.currentIndex >= steps.length) {
      cache.clear();
      return FRESH_STATE;
    }
    return cached;
  });

  const totalSteps = steps.length;
  const safeIndex = Math.max(0, Math.min(state.currentIndex, totalSteps - 1));
  const currentStep = steps[safeIndex];
  const isComplete = state.currentIndex >= totalSteps;

  const persist = useCallback(
    (next: WizardPersistedState) => {
      setState(next);
      cache.set(userId, next);
    },
    [cache, userId],
  );

  const goNext = useCallback(() => {
    persist({
      ...state,
      currentIndex: Math.min(state.currentIndex + 1, totalSteps),
      completedStepIds: state.completedStepIds.includes(currentStep.id)
        ? state.completedStepIds
        : [...state.completedStepIds, currentStep.id],
    });
  }, [persist, state, totalSteps, currentStep]);

  const goPrev = useCallback(() => {
    if (state.currentIndex === 0) return;
    persist({ ...state, currentIndex: state.currentIndex - 1 });
  }, [persist, state]);

  const goTo = useCallback(
    (stepId: string) => {
      const targetIndex = steps.findIndex((s) => s.id === stepId);
      if (targetIndex < 0) return;
      persist({ ...state, currentIndex: targetIndex });
    },
    [persist, state, steps],
  );

  const skipCurrent = useCallback(() => {
    if (!currentStep.canSkip) return;
    persist({
      ...state,
      currentIndex: Math.min(state.currentIndex + 1, totalSteps),
      skippedStepIds: state.skippedStepIds.includes(currentStep.id)
        ? state.skippedStepIds
        : [...state.skippedStepIds, currentStep.id],
    });
  }, [persist, state, totalSteps, currentStep]);

  const markCurrentCompleted = useCallback(() => {
    if (state.completedStepIds.includes(currentStep.id)) return;
    persist({
      ...state,
      completedStepIds: [...state.completedStepIds, currentStep.id],
    });
  }, [persist, state, currentStep]);

  const reset = useCallback(() => {
    cache.clear();
    setState({ currentIndex: 0, completedStepIds: [], skippedStepIds: [] });
  }, [cache]);

  return {
    currentStep,
    currentIndex: safeIndex,
    totalSteps,
    completedStepIds: state.completedStepIds,
    skippedStepIds: state.skippedStepIds,
    isFirstStep: safeIndex === 0,
    isLastStep: safeIndex === totalSteps - 1,
    isComplete,
    goNext,
    goPrev,
    goTo,
    skipCurrent,
    markCurrentCompleted,
    reset,
  };
}
