import { useMemo } from "react";
import type { FetchResult } from "../../api/ConceptClient";
import type { DashboardWidget } from "../../types";
import type {
  BoundTableHandlers,
  DashboardTableHandlers,
} from "../outputs/table/tableOutput.types";
import { WidgetRenderer } from "../widgets/WidgetRenderer";

// Widgets that get a card wrapper with a header label
const CARD_WRAPPED_TYPES = new Set([
  "table",
  "badge_table",
  "bar_list",
  "line_chart",
  "pie_chart",
  "progress_bar",
  "channel_grid",
  "graph",
]);

interface WidgetCellProps {
  widget: DashboardWidget;
  data: Record<string, FetchResult | null>;
  loading: Record<string, boolean>;
  errors: Record<string, string>;
  tableHandlers?: DashboardTableHandlers;
  fullscreen?: boolean;
  ontologyId?: string;
}

function bindHandlers(conceptName: string, handlers: DashboardTableHandlers): BoundTableHandlers {
  return {
    onPageChange: (page) => handlers.onPageChange(conceptName, page),
    onPageSizeChange: (pageSize) => handlers.onPageSizeChange(conceptName, pageSize),
    onSort: (orderBy) => handlers.onSort(conceptName, orderBy),
    onSearch: (searchTerm, columnFilters) =>
      handlers.onSearch(conceptName, searchTerm, columnFilters),
    onClearSearch: () => handlers.onClearSearch(conceptName),
  };
}

export function WidgetCell({
  widget,
  data,
  loading,
  errors,
  tableHandlers,
  fullscreen = false,
  ontologyId,
}: WidgetCellProps) {
  const boundHandlers = useMemo(
    () => (tableHandlers ? bindHandlers(widget.conceptName, tableHandlers) : undefined),
    [widget.conceptName, tableHandlers],
  );

  const content = (
    <WidgetRenderer
      widget={widget}
      data={data[widget.conceptName]}
      isLoading={loading[widget.conceptName]}
      error={errors[widget.conceptName]}
      tableHandlers={boundHandlers}
      fullscreen={fullscreen}
      ontologyId={ontologyId}
    />
  );

  if (!CARD_WRAPPED_TYPES.has(widget.type)) {
    return content;
  }

  if (fullscreen) {
    return (
      <div className="flex-1 min-h-0 flex flex-col bg-card border border-border rounded-lg overflow-hidden">
        {(widget.label || widget.conceptName) && (
          <div className="px-4 py-3 border-b border-border flex-shrink-0">
            <span className="text-[12px] font-semibold text-foreground">
              {widget.label || widget.conceptName}
            </span>
          </div>
        )}
        <div className="flex-1 min-h-0 p-4">{content}</div>
      </div>
    );
  }

  return (
    <div className="bg-card border border-border rounded-lg overflow-hidden">
      {(widget.label || widget.conceptName) && (
        <div className="px-4 py-3 border-b border-border">
          <span className="text-[12px] font-semibold text-foreground">
            {widget.label || widget.conceptName}
          </span>
        </div>
      )}
      <div className="p-4">{content}</div>
    </div>
  );
}
