import { useQuery } from "@tanstack/react-query";
import { useMemo } from "react";
import {
  type OntologyScope,
  OntologyService,
  type SnapshotConcept,
  type SnapshotDiffSource,
} from "@/features/ontologies/api";
import { type ConceptSetDiff, diffConceptSets } from "./snapshotDiff.utils";

interface UseSnapshotDiffParams {
  ontologyId: string | null;
  scope: OntologyScope;
  baseSource: SnapshotDiffSource | null;
  targetSource: SnapshotDiffSource | null;
}

interface UseSnapshotDiffReturn {
  diff: ConceptSetDiff | null;
  isLoading: boolean;
  error: Error | null;
}

const conceptsKey = (ontologyId: string, source: string) =>
  ["ontology", "snapshot-concepts", ontologyId, source] as const;

export function useSnapshotDiff({
  ontologyId,
  scope,
  baseSource,
  targetSource,
}: UseSnapshotDiffParams): UseSnapshotDiffReturn {
  const baseQuery = useQuery<SnapshotConcept[], Error>({
    queryKey: conceptsKey(ontologyId ?? "", baseSource ?? ""),
    queryFn: () => OntologyService.getSnapshotConcepts(ontologyId!, baseSource!, scope),
    enabled: Boolean(ontologyId && baseSource),
    staleTime: 30_000,
    refetchOnWindowFocus: false,
  });

  const targetQuery = useQuery<SnapshotConcept[], Error>({
    queryKey: conceptsKey(ontologyId ?? "", targetSource ?? ""),
    queryFn: () => OntologyService.getSnapshotConcepts(ontologyId!, targetSource!, scope),
    enabled: Boolean(ontologyId && targetSource),
    staleTime: 30_000,
    refetchOnWindowFocus: false,
  });

  const diff = useMemo(() => {
    if (!baseQuery.data || !targetQuery.data) return null;
    return diffConceptSets(baseQuery.data, targetQuery.data);
  }, [baseQuery.data, targetQuery.data]);

  return {
    diff,
    isLoading: baseQuery.isLoading || targetQuery.isLoading,
    error: baseQuery.error ?? targetQuery.error,
  };
}
