import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { acceptTeamInvitation, declineTeamInvitation, listMyInvitations } from "../api";
import type { InvitationInboxEntry, Membership, TeamError } from "../types";
import { MY_TEAMS_KEY } from "./useMyTeams";
import { TEAM_PENDING_INVITATIONS_KEY } from "./useTeamPendingInvitations";
import { TEAM_SUGGESTION_KEY } from "./useTeamSuggestion";

// Shared prefix so any mutation that could add/remove an invitation (invite
// send, accept, decline) can invalidate the invitee's inbox in one call.
export const TEAM_INVITATIONS_KEY = ["teams", "invitations"] as const;
const invitationsKey = (userId: string) => [...TEAM_INVITATIONS_KEY, userId] as const;

interface UseTeamInvitationsReturn {
  invitations: InvitationInboxEntry[];
  isLoading: boolean;
  isFetching: boolean;
  error: TeamError | null;
  refresh: () => Promise<unknown>;

  accept: (token: string) => Promise<Membership>;
  isAccepting: boolean;

  decline: (token: string) => Promise<{ token: string; status: "declined" }>;
  isDeclining: boolean;
}

// GET /teams/invitations (invitee's pending inbox) + accept + decline mutations.
// Accept flips the caller into a team, so we also invalidate the teams list
// and the suggestion — mirrors the useShareInbox pattern.
export function useTeamInvitations(): UseTeamInvitationsReturn {
  const { user, session } = useAuth();
  const queryClient = useQueryClient();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";

  const query = useQuery<InvitationInboxEntry[], TeamError>({
    queryKey: invitationsKey(userId),
    queryFn: () => listMyInvitations(supabaseToken),
    enabled: Boolean(userId && supabaseToken),
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const acceptMutation = useMutation<Membership, TeamError, string>({
    mutationFn: (token) => acceptTeamInvitation(token, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: TEAM_INVITATIONS_KEY });
      queryClient.invalidateQueries({ queryKey: MY_TEAMS_KEY });
      queryClient.invalidateQueries({ queryKey: TEAM_SUGGESTION_KEY });
      // If the sender happens to be viewing this team's pending list in the
      // same tab (dev/staging flow), the accepted row should stop appearing
      // as pending. We don't know the team id from just the token, so we
      // invalidate the whole prefix — RQ dedupes matching queries.
      queryClient.invalidateQueries({ queryKey: TEAM_PENDING_INVITATIONS_KEY });
    },
  });

  const declineMutation = useMutation<{ token: string; status: "declined" }, TeamError, string>({
    mutationFn: (token) => declineTeamInvitation(token, supabaseToken),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: TEAM_INVITATIONS_KEY });
      // Same rationale as accept — a declined invite is no longer pending.
      queryClient.invalidateQueries({ queryKey: TEAM_PENDING_INVITATIONS_KEY });
    },
  });

  return {
    invitations: query.data ?? [],
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    refresh: query.refetch,

    accept: acceptMutation.mutateAsync,
    isAccepting: acceptMutation.isPending,

    decline: declineMutation.mutateAsync,
    isDeclining: declineMutation.isPending,
  };
}
