import { LogOut, Settings, User } from "lucide-react";
import { Link } from "react-router-dom";
import { GettingStartedWidget } from "@/features/onboarding/getting-started/components/GettingStartedWidget";
import { SidebarAssistantItem } from "@/shared/components/layout/SidebarAssistantItem";
import { Avatar, AvatarFallback, AvatarImage } from "@/shared/components/ui/avatar";
import { ThemeToggle } from "@/shared/components/ui/ThemeToggle";
import { PROMETHEUX_CONFIG } from "@/shared/config/prometheux";
import { cn } from "@/shared/lib/utils";

interface SidebarBottomProps {
  collapsed: boolean;
  userDisplayName: string;
  avatarSrc?: string;
  isProfilePage: boolean;
  isOnboardingPage: boolean;
  isSettingsTab: boolean;
  canSeeSettings: boolean;
  onSignOut: () => void;
}

export function SidebarBottom({
  collapsed,
  userDisplayName,
  avatarSrc,
  isProfilePage,
  isOnboardingPage,
  isSettingsTab,
  canSeeSettings,
  onSignOut,
}: SidebarBottomProps) {
  return (
    <div className="shrink-0 border-t">
      {!isOnboardingPage && <GettingStartedWidget collapsed={collapsed} />}

      <SidebarAssistantItem collapsed={collapsed} />

      <div className="px-2 py-2">
        <ThemeToggle collapsed={collapsed} />

        {!PROMETHEUX_CONFIG.SKIP_AUTH && (
          <Link
            to="/profile"
            title={collapsed ? userDisplayName : undefined}
            className={cn(
              "flex h-9 w-full items-center gap-3 rounded-md px-2 text-sm font-medium text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
              isProfilePage && "bg-primary/10 text-primary",
              collapsed && "justify-center px-0",
            )}
          >
            <Avatar className="h-4 w-4 shrink-0">
              {avatarSrc ? (
                <AvatarImage src={avatarSrc} alt="Profile" />
              ) : (
                <AvatarFallback>
                  <User className="h-4 w-4" />
                </AvatarFallback>
              )}
            </Avatar>
            {!collapsed && <span className="truncate">{userDisplayName}</span>}
          </Link>
        )}

        {!isOnboardingPage && canSeeSettings && (
          <Link
            to="/settings"
            title={collapsed ? "Settings" : undefined}
            className={cn(
              "flex h-9 w-full items-center gap-3 rounded-md px-2 text-sm font-medium text-muted-foreground no-underline transition-colors hover:bg-accent hover:text-foreground",
              isSettingsTab && "bg-primary/10 text-primary",
              collapsed && "justify-center px-0",
            )}
          >
            <Settings className="h-4 w-4 shrink-0" />
            {!collapsed && <span className="truncate">Settings</span>}
          </Link>
        )}

        {!PROMETHEUX_CONFIG.SKIP_AUTH && (
          <button
            type="button"
            onClick={onSignOut}
            title={collapsed ? "Sign Out" : undefined}
            className={cn(
              "flex h-9 w-full items-center gap-3 rounded-md px-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground",
              collapsed && "justify-center px-0",
            )}
          >
            <LogOut className="h-4 w-4 shrink-0" />
            {!collapsed && <span className="truncate">Sign Out</span>}
          </button>
        )}
      </div>
    </div>
  );
}
