import { type Extension, StateEffect, StateField } from "@codemirror/state";
import { Decoration, type DecorationSet, EditorView } from "@codemirror/view";

/**
 * Mirrors the backend's `_PLACEHOLDER_RE` in `app/executors/llm_executor.py`.
 * A reference name is an identifier: no dots, dashes or indices, and the inner
 * whitespace of `{{ name }}` is tolerated. Kept identical on purpose — the
 * editor must mark exactly the spans the executor will substitute.
 */
const PLACEHOLDER_SOURCE = "\\{\\{\\s*([A-Za-z_][A-Za-z0-9_]*)\\s*\\}\\}";

/** The ordered, de-duplicated `{{name}}` references in a prompt. */
export function extractPromptReferences(text: string): string[] {
  const pattern = new RegExp(PLACEHOLDER_SOURCE, "g");
  const seen = new Set<string>();
  const refs: string[] = [];
  let match = pattern.exec(text);
  while (match !== null) {
    const name = match[1];
    if (!seen.has(name)) {
      seen.add(name);
      refs.push(name);
    }
    match = pattern.exec(text);
  }
  return refs;
}

export interface PromptReferenceState {
  /** References that resolve to no concept in the project. */
  unresolved: string[];
  /** False until the project has been consulted, so nothing is marked broken while unknown. */
  checked: boolean;
}

const UNCHECKED: PromptReferenceState = { unresolved: [], checked: false };

/**
 * Publish the resolution verdict into an open editor. Dispatched when the
 * server answers rather than passed as a prop: `CellEditor` is memoized on a
 * prop list that excludes `extensions`, so a React-side update would not reach
 * the running editor.
 */
export const setPromptReferenceState = StateEffect.define<PromptReferenceState>();

const referenceState = StateField.define<PromptReferenceState>({
  create: () => UNCHECKED,
  update(value, tr) {
    for (const effect of tr.effects) {
      if (effect.is(setPromptReferenceState)) return effect.value;
    }
    return value;
  },
});

const resolvedMark = Decoration.mark({ class: "cm-prompt-ref" });

function unresolvedMark(name: string) {
  return Decoration.mark({
    class: "cm-prompt-ref cm-prompt-ref-unresolved",
    attributes: {
      title:
        `No concept named "${name}" in this project. An unresolved reference ` +
        "is left in the prompt as literal text, so the model never sees the data.",
    },
  });
}

function buildDecorations(text: string, state: PromptReferenceState): DecorationSet {
  const pattern = new RegExp(PLACEHOLDER_SOURCE, "g");
  const unresolved = new Set(state.unresolved);
  const ranges = [];
  let match = pattern.exec(text);
  while (match !== null) {
    const broken = state.checked && unresolved.has(match[1]);
    const mark = broken ? unresolvedMark(match[1]) : resolvedMark;
    ranges.push(mark.range(match.index, match.index + match[0].length));
    match = pattern.exec(text);
  }
  return Decoration.set(ranges);
}

const referenceDecorations = StateField.define<DecorationSet>({
  create: (state) => buildDecorations(state.doc.toString(), state.field(referenceState)),
  update(value, tr) {
    const verdictChanged = tr.effects.some((effect) => effect.is(setPromptReferenceState));
    if (!tr.docChanged && !verdictChanged) return value;
    return buildDecorations(tr.state.doc.toString(), tr.state.field(referenceState));
  },
  provide: (field) => EditorView.decorations.from(field),
});

const referenceTheme = EditorView.baseTheme({
  ".cm-prompt-ref": {
    backgroundColor: "hsl(var(--primary) / 0.12)",
    color: "hsl(var(--primary))",
    borderRadius: "3px",
    padding: "0 2px",
  },
  ".cm-prompt-ref-unresolved": {
    backgroundColor: "hsl(var(--destructive) / 0.12)",
    color: "hsl(var(--destructive))",
    textDecoration: "underline wavy",
  },
});

/**
 * Renders `{{name}}` references as chips, dimming to a warning style for the
 * ones the project cannot resolve. Purely presentational: the text is still the
 * body that gets saved, so nothing here changes what is stored.
 */
export function promptReferenceExtension(): Extension {
  return [referenceState, referenceDecorations, referenceTheme];
}
