import { z } from "zod";

export const TokenSummarySchema = z.object({
  jti: z.string(),
  name: z.string().nullable(),
  issued_at: z.string(),
  expires_at: z.string().nullable(),
});
export type TokenSummary = z.infer<typeof TokenSummarySchema>;

export const ListTokensResponseSchema = z.object({
  status: z.literal("success"),
  data: z.object({
    tokens: z.array(TokenSummarySchema),
  }),
});

// The spec doesn't fix the issue-token response shape beyond "returns the token
// once". Accept the common fields and treat the raw JWT as required.
export const IssueTokenDataSchema = z.object({
  jti: z.string(),
  token: z.string(),
  name: z.string().nullable().optional(),
  issued_at: z.string().optional(),
  expires_at: z.string().nullable().optional(),
});
export type IssueTokenData = z.infer<typeof IssueTokenDataSchema>;

export const IssueTokenResponseSchema = z.object({
  status: z.literal("success"),
  data: IssueTokenDataSchema,
});
export type IssueTokenResponse = z.infer<typeof IssueTokenResponseSchema>;

export const RevokeTokenResponseSchema = z.object({
  status: z.literal("success"),
  data: z.object({
    jti: z.string(),
    status: z.enum(["revoked", "not_found"]),
  }),
});
export type RevokeTokenResponse = z.infer<typeof RevokeTokenResponseSchema>;

export const RevokeAllResponseSchema = z.object({
  status: z.literal("success"),
  data: z.object({
    sub: z.string(),
    status: z.literal("all_revoked"),
  }),
});

export interface IssueTokenRequest {
  name?: string;
  expiresInMinutes: number | null;
}

export interface CreateTokenInput {
  name: string;
  expiresInMinutes: number | null;
}
