/**
 * Persisted UI preferences for the Explorer view.
 *
 * Keys are typed constants per the project rules (see state-management.md).
 * Reads are defensive — invalid stored values fall back to `null`, so the
 * caller can decide the default.
 *
 * Note: the editor's default bottom tab is no longer persisted here. It is
 * enforced by the user's `defaultCellView` preference (see `preferencesStore`);
 * in-session tab switching is local component state only.
 */

const STORAGE_KEYS = {
  EXPLORER_EDITOR_RATIO: "prometheux:explorer:editorRatio",
} as const;

/**
 * Every view a concept cell can show, and therefore every tab the dock can
 * remember. "context" and "output" are common to all cells; the authoring view
 * is named after the cell's language, or is plain "editor" for the context and
 * llm cells, whose bodies are not code. "engine" is the logic cell's run log.
 */
export type ExplorerBottomTab =
  | "context"
  | "logic"
  | "sql"
  | "cypher"
  | "python"
  | "editor"
  | "engine"
  | "output";

// Clamp so neither pane ever fully collapses behind the drag handle.
export const EDITOR_RATIO_MIN = 0.15;
export const EDITOR_RATIO_MAX = 0.85;

function clampRatio(value: number): number {
  if (!Number.isFinite(value)) return EDITOR_RATIO_MIN;
  if (value < EDITOR_RATIO_MIN) return EDITOR_RATIO_MIN;
  if (value > EDITOR_RATIO_MAX) return EDITOR_RATIO_MAX;
  return value;
}

export const explorerPreferences = {
  getEditorRatio(): number | null {
    try {
      const raw = localStorage.getItem(STORAGE_KEYS.EXPLORER_EDITOR_RATIO);
      if (!raw) return null;
      const parsed = Number.parseFloat(raw);
      if (!Number.isFinite(parsed)) return null;
      return clampRatio(parsed);
    } catch (error) {
      console.error("Failed to read explorer editor ratio from storage:", error);
      return null;
    }
  },
  setEditorRatio(ratio: number): void {
    try {
      localStorage.setItem(STORAGE_KEYS.EXPLORER_EDITOR_RATIO, String(clampRatio(ratio)));
    } catch (error) {
      console.error("Failed to persist explorer editor ratio:", error);
    }
  },
  clear(): void {
    try {
      localStorage.removeItem(STORAGE_KEYS.EXPLORER_EDITOR_RATIO);
    } catch (error) {
      console.error("Failed to clear explorer preferences:", error);
    }
  },
};
