import { Undo2 } from "lucide-react";
import type React from "react";
import { Button } from "@/shared/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";

export interface RosterOption {
  value: string;
  label: string;
}

interface RosterRowProps {
  label: string;
  // Optional secondary line under the label — used to explain how the subject
  // got access (e.g. "via Acme team") so team-derived members aren't mistaken
  // for direct shares.
  hint?: string;
  // The effective-access badge shown to the left of the dropdown.
  badgeText: string;
  badgeClass: string;
  // Dropdown options + current value. Only rendered when `editable`.
  options: RosterOption[];
  // Undefined = no explicit rule (subject inherits its level). When undefined
  // the `placeholder` is shown instead of a selected option.
  value?: string;
  editable: boolean;
  isBusy: boolean;
  onChange: (value: string) => void;
  // Shown in the trigger when `value` is undefined — used to surface the
  // inherited level (e.g. "Inherited (Editor)") for callers that model
  // "inherit" as the absence of a rule rather than a dropdown option.
  placeholder?: string;
  // When provided, a Reset button is rendered next to the dropdown to clear an
  // explicit rule and revert to the inherited level. Disabled when `canReset`
  // is false (there is nothing to reset).
  onReset?: () => void;
  canReset?: boolean;
}

// Presentational roster row shared by the concept- and project-level rosters: a
// subject label, its effective-access badge, and an optional dropdown to change
// the subject's permission.
const RosterRow: React.FC<RosterRowProps> = ({
  label,
  hint,
  badgeText,
  badgeClass,
  options,
  value,
  editable,
  isBusy,
  onChange,
  placeholder,
  onReset,
  canReset,
}) => {
  return (
    <div className="flex items-center justify-between gap-2 rounded-md border border-border bg-card px-3 py-1.5">
      <div className="flex min-w-0 flex-col">
        <span className="truncate text-xs text-foreground">{label}</span>
        {hint && <span className="truncate text-[10px] text-muted-foreground">{hint}</span>}
      </div>
      <div className="flex flex-shrink-0 items-center gap-1.5">
        {editable ? (
          <>
            <Select value={value} onValueChange={onChange} disabled={isBusy}>
              <SelectTrigger className="h-7 w-[132px] text-xs">
                <SelectValue placeholder={placeholder} />
              </SelectTrigger>
              <SelectContent>
                {options.map((o) => (
                  <SelectItem key={o.value} value={o.value}>
                    {o.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {onReset && (
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={onReset}
                disabled={isBusy || !canReset}
                title="Reset to inherited level"
              >
                <Undo2 className="h-3.5 w-3.5" />
              </Button>
            )}
          </>
        ) : (
          <span className={`rounded px-1.5 py-0.5 text-[10px] font-medium ${badgeClass}`}>
            {badgeText}
          </span>
        )}
      </div>
    </div>
  );
};

export default RosterRow;
