import { useCallback, useState } from "react";
import { toast } from "sonner";
import type { ConceptCell } from "@/features/concept-editor/types";

interface UseLineageEditorActionsParams {
  cells: ConceptCell[];
  loadCells: () => Promise<void>;
  saveCell: (
    cellId: string,
    freshCode?: string,
    showToast?: boolean,
  ) => Promise<string | undefined>;
  refreshLineage?: () => Promise<void>;
}

interface UseLineageEditorActionsReturn {
  isRefreshing: boolean;
  isSavingAll: boolean;
  hasUnsavedChanges: boolean;
  handleRefresh: () => Promise<void>;
  saveAllChanges: () => Promise<void>;
}

/**
 * The "Refresh" and "Save All" editor actions surfaced in the Explorer header.
 * Refresh reloads the concept cells; Save All re-persists every concept (not
 * just modified ones) and then refreshes the lineage graph once.
 */
export function useLineageEditorActions({
  cells,
  loadCells,
  saveCell,
  refreshLineage,
}: UseLineageEditorActionsParams): UseLineageEditorActionsReturn {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isSavingAll, setIsSavingAll] = useState(false);

  const hasUnsavedChanges = cells.some((c) => c.isModified);

  const handleRefresh = useCallback(async () => {
    setIsRefreshing(true);
    try {
      await loadCells();
      toast.success("Concepts refreshed");
    } catch {
      toast.error("Failed to refresh");
    } finally {
      setIsRefreshing(false);
    }
  }, [loadCells]);

  const saveAllChanges = useCallback(async () => {
    // Re-persist every concept, not just modified ones. Empty cells are skipped
    // since there is nothing to save. Existing concepts are updated (no conflict);
    // one failing cell must not abort the rest, so each save is isolated.
    const savable = cells.filter((c) => c.code?.trim());
    if (savable.length === 0) {
      toast.info("No concepts to save");
      return;
    }
    setIsSavingAll(true);
    let failed = 0;
    try {
      for (const c of savable) {
        try {
          await saveCell(c.id, c.code, false);
        } catch (e) {
          failed += 1;
          console.error(`Error saving concept ${c.id}:`, e);
        }
      }
      if (failed === 0) toast.success("All concepts saved");
      else toast.error(`Failed to save ${failed} concept${failed === 1 ? "" : "s"}`);
      await refreshLineage?.();
    } finally {
      setIsSavingAll(false);
    }
  }, [cells, saveCell, refreshLineage]);

  return { isRefreshing, isSavingAll, hasUnsavedChanges, handleRefresh, saveAllChanges };
}
