import {
  Background,
  ControlButton,
  Controls,
  type Edge,
  type Node as FlowNode,
  ReactFlow,
  ReactFlowProvider,
  useEdgesState,
  useNodesState,
} from "@xyflow/react";
import { ChevronsDownUp, ChevronsUpDown } from "lucide-react";
import React, {
  type CSSProperties,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import "@xyflow/react/dist/style.css";
import { python } from "@codemirror/lang-python";
import { syntaxHighlighting } from "@codemirror/language";
import type { Extension } from "@codemirror/state";
import { toast } from "sonner";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { RunLimitDialog } from "@/features/billing/components/RunLimitDialog";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { useMachineStatusContext } from "@/features/compute/context/MachineStatusContext";
import { useRequireCompute } from "@/features/compute/hooks/useRequireCompute";
import { customLanguage } from "@/features/concept-editor/components/code-editor/language/customProlog";
import { customHighlightStyle } from "@/features/concept-editor/components/code-editor/styles/editorHighlightStyle";
import GroupDialog from "@/features/concept-editor/components/GroupDialog";
import { vadalogLinter } from "@/features/concept-editor/components/query/linters/vadalogLinter";
import SelectedCellEditor from "@/features/concept-editor/components/SelectedCellEditor";
import { useConceptEditor } from "@/features/concept-editor/hooks/useConceptEditor";
import { useEditorGroups } from "@/features/concept-editor/hooks/useEditorGroups";
import type { ConceptCell } from "@/features/concept-editor/types";
import ConceptLibrarySidebar, {
  type LibraryPanel,
} from "@/features/concepts/components/ConceptLibrarySidebar";
import LibraryRail from "@/features/concepts/components/LibraryRail";
import { NoteDockPanel } from "@/features/context-layer/explorer-panel/NoteDockPanel";
import { useAnnotatedConcepts } from "@/features/context-layer/hooks/useAnnotatedConcepts";
import { useExpandCollapseAll } from "@/features/lineage/hooks/useExpandCollapseAll";
import { useLineageConceptFocus } from "@/features/lineage/hooks/useLineageConceptFocus";
import { useLineageEditorActions } from "@/features/lineage/hooks/useLineageEditorActions";
import {
  DOCK_DEFAULT_PCT,
  useLineageEditorDock,
} from "@/features/lineage/hooks/useLineageEditorDock";
import { useLineageGroupFilter } from "@/features/lineage/hooks/useLineageGroupFilter";
import { useOpenContextNote } from "@/features/lineage/hooks/useOpenContextNote";
import { useOntologyId } from "@/features/ontologies/hooks/useOntologyId";
import ConceptRestrictionsDialog from "@/features/ontologies/sharing/components/ConceptRestrictionsDialog";
import { useOntologyPermissionAccess } from "@/features/ontologies/sharing/hooks/useOntologyPermissionAccess";
import type { ConceptCardCustomData, LineageApiResponse } from "@/features/ontology-schema/types";
import { ErrorBoundary } from "@/shared/components/ErrorBoundary";
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/shared/components/ui/resizable";
import SidebarToggleButton from "@/shared/components/ui/SidebarToggleButton";
import { useEditorActionsStore } from "@/shared/store/editorActionsStore";
import { autoIndentCode } from "@/shared/utils/indentationUtils";
import { useConceptCardActions } from "../hooks/useConceptCardActions";
import ConceptCardNode, { LineageCardActionsContext } from "./ConceptCardNode";
import DatasourceDetailPanel from "./DatasourceDetailPanel";
import LineageExplorerPanel from "./LineageExplorerPanel";
import { LineageFocusBanner } from "./LineageFocusBanner";
import { LineageGroupLegend } from "./LineageGroupLegend";
import { LineageLoadingOverlay } from "./LineageLoadingOverlay";
import { LineageStyles } from "./LineageStyles";
import LineageTreeRail from "./LineageTreeRail";
import { LineagePanelHeader } from "./lineage-view/components/LineagePanelHeader";
import { OverwriteConfirmDialog } from "./lineage-view/components/OverwriteConfirmDialog";
import { buildGroupLegend } from "./lineage-view/groupColors";
import { useConceptExecutionStatus } from "./lineage-view/hooks/useConceptExecutionStatus";
import {
  markRestrictedNodes,
  restorePreservedNodeState,
  stampAnnotatedNodes,
  transformNodes,
} from "./lineage-view/lineage.nodes.utils";
import {
  applyFlowEdgeStyles,
  applySelectionHighlight,
  collectUpstreamEdgeIds,
  filterNodesByGroups,
  isBlankUnsavedCell,
  layoutElements,
  transformEdges,
} from "./lineage-view/lineage.utils";
import type { DatasourcePanelInfo, PanelState } from "./lineage-view/types";

const nodeTypes = { conceptCard: ConceptCardNode };

interface LineageViewProps {
  data?: LineageApiResponse;
  /** Concept names accessible to the current scoped session. Nodes outside this
   * set are rendered as anonymized "Restricted concept" placeholders. */
  accessibleConcepts?: Set<string>;
  topLeftControls?: React.ReactNode;
  isLineageLoading?: boolean;
  onToggleSidebar?: () => void;
  sidebarVisible?: boolean;
  onRefreshLineage?: () => Promise<void>;
  focusConceptName?: string | null;
  onFocusConsumed?: () => void;
  /** Concept whose upstream slice is currently isolated, if any. */
  isolatedConcept?: string | null;
  /** Isolate a concept's upstream dependency slice (re-fetch + re-render). */
  onIsolateConcept?: (conceptName: string) => void;
  /** Clear isolation and return to the full lineage. */
  onClearIsolation?: () => void;
}

const LineageViewInner: React.FC<LineageViewProps> = ({
  data,
  accessibleConcepts,
  topLeftControls,
  isLineageLoading = false,
  onToggleSidebar,
  sidebarVisible = true,
  onRefreshLineage,
  focusConceptName,
  onFocusConsumed,
  isolatedConcept,
  onIsolateConcept,
  onClearIsolation,
}) => {
  const [nodes, setNodes, onNodesChange] = useNodesState<FlowNode<ConceptCardCustomData>>([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([]);
  const reactFlowInstance = useRef<any>(null);

  // Panel state — tracks which cell is open
  const [panelState, setPanelState] = useState<PanelState | null>(null);
  const [datasourcePanelInfo, setDatasourcePanelInfo] = useState<DatasourcePanelInfo | null>(null);
  // A standalone context note (no concept attached) shown in the dock;
  // noteId null = a new-project-note draft from the Context rail.
  const [notePanel, setNotePanel] = useState<{ noteId: string | null } | null>(null);
  const [librarySidebarPanel, setLibrarySidebarPanel] = useState<LibraryPanel | null>(null);

  // The single editor dock. It resizes via the panel group's drag handle; the
  // header's expand button maximizes/restores it. There is no separate
  // full-screen mode — one panel, resized.
  const dock = useLineageEditorDock();

  // Selection highlight — tracks which node is selected so we can
  // highlight the full upstream dependency path on the edges.
  const selectedNodeIdRef = useRef<string | null>(null);
  const baseEdgesRef = useRef<Edge[]>([]);
  const skipAutoFitViewRef = useRef(false);
  // Pending single-click panel-open, debounced so a double-click (isolate) can
  // cancel it before the editor pops open.
  const pendingOpenRef = useRef<number | null>(null);

  // Expand/collapse all concept cards (re-layouts + re-fits). Owns the
  // expanded-labels ref used to restore expansion across lineage refreshes.
  const { allCardsExpanded, toggleAllCards, expandedLabelsRef } = useExpandCollapseAll({
    nodes,
    setNodes,
    baseEdgesRef,
    reactFlowInstance,
    skipAutoFitViewRef,
  });

  // Search state
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchValue, setSearchValue] = useState("");

  // Group colour legend + per-group visibility filter for the canvas.
  const groupFilter = useLineageGroupFilter();
  const groupLegend = useMemo(
    () =>
      buildGroupLegend(
        nodes.filter((n) => n.data.nodeType !== "datasource").map((n) => n.data.group),
      ),
    [nodes],
  );
  // Attached-context indicator: concepts with notes linked via context_edges
  // get a violet notebook marker in their card footer (context revamp,
  // phase 4). Stamped on the visible nodes so attach/detach updates live;
  // the ref lets the layout effect see it too (footer affects card height)
  // without relayout on every edge change.
  const lineageOntologyId = useOntologyId();
  const annotatedConcepts = useAnnotatedConcepts(lineageOntologyId);
  const annotatedConceptsRef = useRef(annotatedConcepts);
  annotatedConceptsRef.current = annotatedConcepts;

  // Concept-permissions dialog, triggered from a card's kebab menu. Offered to
  // the project owner and to owner/admins of a recipient team (delegated). The
  // access hook resolves which, and how mutations route. `null` = closed.
  const permissionAccess = useOntologyPermissionAccess();
  const [permissionsTarget, setPermissionsTarget] = useState<string | null>(null);
  const handleManagePermissions = useCallback((conceptName: string) => {
    setPermissionsTarget(conceptName);
  }, []);
  const { nodes: visibleNodes, edges: visibleEdges } = useMemo(() => {
    const filtered = filterNodesByGroups(nodes, edges, groupFilter.hiddenGroups);
    return { nodes: stampAnnotatedNodes(filtered.nodes, annotatedConcepts), edges: filtered.edges };
  }, [nodes, edges, groupFilter.hiddenGroups, annotatedConcepts]);

  // Per-concept execution status (SSE) reflected onto the lineage graph.
  const { conceptStatusesRef } = useConceptExecutionStatus({
    setNodes,
    setEdges,
    selectedNodeIdRef,
    baseEdgesRef,
  });

  // Lineage only opens concept cells on demand.
  const nb = useConceptEditor({ ensureEmptyCell: false });

  // Machine state from global context. Compute detection + the "start a machine"
  // prompt are handled by the shared useRequireCompute guard (which also re-syncs
  // machine data on mount).
  const { hasRunningMachine, userMachines, autoSelectRunningCompute } = useMachineStatusContext();
  const { ensureCompute } = useRequireCompute();

  // Code-assistant wiring for the editor's "Ask AI" action.
  const setActiveCode = useCodeAssistantStore((s) => s.setActiveCode);
  const openAssistantPanel = useCodeAssistantStore((s) => s.openPanel);
  const setFocusedConcept = useCodeAssistantStore((s) => s.setFocusedConcept);
  const clearAssistantMessages = useCodeAssistantStore((s) => s.clearMessages);

  // CodeMirror extensions (memoised)
  const extensionsWithLinter = useMemo<Extension[]>(
    () => [customLanguage, syntaxHighlighting(customHighlightStyle), vadalogLinter()],
    [],
  );

  const extensionsWithoutLinter = useMemo<Extension[]>(
    () => [customLanguage, syntaxHighlighting(customHighlightStyle)],
    [],
  );

  // Apply the same Vadalog highlight palette to Python so it inherits the
  // theme-aware `--syntax-*` colors (and looks consistent in dark mode) instead
  // of CodeMirror's bright default highlight style.
  const extensionsPython = useMemo<Extension[]>(
    () => [python(), syntaxHighlighting(customHighlightStyle)],
    [],
  );

  const canEditOntologies = usePermissionsStore((s) => s.canEdit("can_edit_projects"));

  // File-tree search (independent of the canvas/header node search).
  const [treeSearch, setTreeSearch] = useState("");
  const filteredCells = useMemo(() => {
    if (!treeSearch.trim()) return nb.cells;
    const lower = treeSearch.toLowerCase();
    return nb.cells.filter(
      (c) =>
        c.code?.toLowerCase().includes(lower) ||
        c.description?.toLowerCase().includes(lower) ||
        c.outputPredicate?.toLowerCase().includes(lower),
    );
  }, [nb.cells, treeSearch]);

  // All group concerns (tree derivations, collapse, group dialog, persistence),
  // shared by the left Explorer tree and the editor dock's cell.
  const groups = useEditorGroups({
    cells: nb.cells,
    setCells: nb.setCells,
    filteredCells,
    onSaveCell: nb.handleSaveCell,
  });

  // "Refresh" / "Save All" actions shown in the Explorer header.
  const editorActions = useLineageEditorActions({
    cells: nb.cells,
    loadCells: nb.loadCells,
    saveCell: nb.handleSaveCell,
    refreshLineage: onRefreshLineage,
  });

  // Left Explorer tree visibility — an independent panel, decoupled from the dock.
  const [isTreeOpen, setIsTreeOpen] = useState(false);
  const toggleTree = useCallback(() => setIsTreeOpen((prev) => !prev), []);

  const handleIndentCode = useCallback(
    (cellId: string) => {
      const cell = nb.cells.find((c) => c.id === cellId);
      if (cell) {
        const indented = autoIndentCode(cell.code);
        if (indented !== cell.code) nb.handleCodeChange(indented, cellId);
      }
    },
    [nb.cells, nb.handleCodeChange],
  );

  const handleOpenAssistant = useCallback(
    (cellId: string) => {
      const cell = nb.cells.find((c) => c.id === cellId);
      if (cell) {
        setActiveCode(cell.code, cell.id, cell.outputPredicate || cell.id);
        clearAssistantMessages();
        setFocusedConcept({ name: cell.outputPredicate || cell.id, code: cell.code });
      }
      openAssistantPanel();
    },
    [nb.cells, setActiveCode, clearAssistantMessages, setFocusedConcept, openAssistantPanel],
  );

  // Transform + layout when lineage data changes.
  // Also re-apply persisted execution statuses and card expansion so they
  // survive a refresh (e.g. running a concept re-fetches the lineage).
  useEffect(() => {
    if (!data?.data) {
      setNodes([]);
      setEdges([]);
      return;
    }
    const rawEdges = transformEdges(data.data.edges);
    const sts = conceptStatusesRef.current;
    const rawNodes = markRestrictedNodes(
      stampAnnotatedNodes(
        restorePreservedNodeState(transformNodes(data.data.nodes), sts, expandedLabelsRef.current),
        annotatedConceptsRef.current,
      ),
      accessibleConcepts ?? new Set<string>(),
    );

    const { nodes: laid, edges: laidEdges } = layoutElements(rawNodes, rawEdges);
    const styledEdges = applyFlowEdgeStyles(laidEdges, sts);
    baseEdgesRef.current = styledEdges;
    setNodes(laid);

    if (selectedNodeIdRef.current) {
      const highlighted = collectUpstreamEdgeIds(selectedNodeIdRef.current, styledEdges);
      setEdges(applySelectionHighlight(styledEdges, highlighted, sts));
    } else {
      setEdges(styledEdges);
    }

    if (!skipAutoFitViewRef.current) {
      const timer = setTimeout(() => {
        reactFlowInstance.current?.fitView({ padding: 0.15 });
      }, 120);
      return () => clearTimeout(timer);
    } else {
      skipAutoFitViewRef.current = false;
    }
  }, [data, accessibleConcepts, setNodes, setEdges]);

  // Re-fit view when detail panel opens/closes
  const panelOpen = panelState !== null || datasourcePanelInfo !== null || notePanel !== null;
  const prevPanelOpenRef = useRef(panelOpen);
  useEffect(() => {
    if (prevPanelOpenRef.current !== panelOpen) {
      if (!skipAutoFitViewRef.current) {
        const timer = setTimeout(() => {
          reactFlowInstance.current?.fitView({ padding: 0.15 });
        }, 180);
        prevPanelOpenRef.current = panelOpen;
        return () => clearTimeout(timer);
      }
      skipAutoFitViewRef.current = false;
    }
    prevPanelOpenRef.current = panelOpen;
  }, [panelOpen]);

  // Auto fit-view when the lineage tab becomes visible
  useEffect(() => {
    const handleFitView = () => {
      skipAutoFitViewRef.current = false;
      setTimeout(() => {
        reactFlowInstance.current?.fitView({ padding: 0.15, duration: 200 });
      }, 150);
    };
    window.addEventListener("lineageFitView", handleFitView);
    return () => window.removeEventListener("lineageFitView", handleFitView);
  }, []);

  // Close search dropdown on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (searchOpen && !target.closest(".search-dropdown-container")) setSearchOpen(false);
    };
    if (searchOpen) {
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
    }
  }, [searchOpen]);

  // ---------------------------------------------------------------------------
  // Find matching cell for a concept name
  // ---------------------------------------------------------------------------
  const findCellForConcept = useCallback(
    (conceptName: string): ConceptCell | undefined => {
      return nb.cells.find((c) => c.outputPredicate === conceptName);
    },
    [nb.cells],
  );

  // ---------------------------------------------------------------------------
  // Node click — open cell / datasource in panel
  // ---------------------------------------------------------------------------
  const openNodePanel = useCallback(
    (node: FlowNode) => {
      const nd = node.data as unknown as ConceptCardCustomData & {
        nodeType?: string;
        datasource_label?: string;
        database?: string;
        bind_annotation?: string;
      };

      // Hidden-for-this-session concepts have no accessible cell/definition —
      // never open a panel for them.
      if (nd.isRestricted) return;

      if (nd.nodeType === "datasource") {
        skipAutoFitViewRef.current = true;
        setPanelState(null);
        setNotePanel(null);
        setDatasourcePanelInfo({
          nodeId: node.id,
          label: nd.datasource_label || nd.label || "Data Source",
          datasourceType: nd.datasource_type || "unknown",
          database: (nd as unknown as { database?: string }).database || "",
          bindAnnotation: (nd as unknown as { bind_annotation?: string }).bind_annotation || "",
          fields: nd.fields ?? {},
        });
        return;
      }

      skipAutoFitViewRef.current = true;
      setDatasourcePanelInfo(null);
      setNotePanel(null);
      const cell = findCellForConcept(nd.label);
      if (cell) {
        setPanelState({
          conceptName: nd.label,
          cellId: cell.id,
          isNew: false,
          panelKey: `node-${node.id}-${Date.now()}`,
        });
      } else {
        toast.error(`Cell for concept "${nd.label}" not found`);
      }
    },
    [findCellForConcept],
  );

  // Ctrl/Cmd-click or double-click a concept isolates its upstream slice. A
  // plain single-click selects the node and (after a short debounce) opens its
  // editor; the debounce lets a double-click cancel the open first.
  const handleNodeClick = useCallback(
    (event: React.MouseEvent, node: FlowNode) => {
      const nd = node.data as unknown as ConceptCardCustomData & { nodeType?: string };

      // Restricted placeholders carry no accessible data — ignore all clicks.
      if (nd.isRestricted) return;

      if ((event.ctrlKey || event.metaKey) && nd.nodeType !== "datasource" && onIsolateConcept) {
        onIsolateConcept(nd.label);
        return;
      }

      selectedNodeIdRef.current = node.id;
      const highlighted = collectUpstreamEdgeIds(node.id, baseEdgesRef.current);
      setEdges(
        applySelectionHighlight(baseEdgesRef.current, highlighted, conceptStatusesRef.current),
      );

      if (pendingOpenRef.current) window.clearTimeout(pendingOpenRef.current);
      pendingOpenRef.current = window.setTimeout(() => openNodePanel(node), 200);
    },
    [openNodePanel, setEdges, conceptStatusesRef, onIsolateConcept],
  );

  const handleNodeDoubleClick = useCallback(
    (_event: React.MouseEvent, node: FlowNode) => {
      if (pendingOpenRef.current) {
        window.clearTimeout(pendingOpenRef.current);
        pendingOpenRef.current = null;
      }
      const nd = node.data as unknown as {
        nodeType?: string;
        label: string;
        isRestricted?: boolean;
      };
      if (nd.nodeType === "datasource" || nd.isRestricted) return;
      onIsolateConcept?.(nd.label);
    },
    [onIsolateConcept],
  );

  const handlePaneClick = useCallback(() => {
    selectedNodeIdRef.current = null;
    setEdges(baseEdgesRef.current);
    setPanelState(null);
    setDatasourcePanelInfo(null);
    setNotePanel(null);
  }, [setEdges]);
  const handleClosePanel = useCallback(() => {
    setPanelState(null);
    setDatasourcePanelInfo(null);
    setNotePanel(null);
    dock.restore();
  }, [dock.restore]);

  const handleOpenContextNote = useOpenContextNote({
    nodes,
    setBottomTab: dock.setBottomTab,
    openNodePanel,
    setPanelState,
    setDatasourcePanelInfo,
    setNotePanelId: (noteId) => setNotePanel(noteId === null ? null : { noteId }),
  });

  // Plus button on the Context rail header — a new project-note draft in
  // the dock (noteId null until the first save persists it).
  const handleCreateContextNote = useCallback(() => {
    setPanelState(null);
    setDatasourcePanelInfo(null);
    setNotePanel({ noteId: null });
  }, []);

  // Center the canvas on a concept's node and open its cell in the dock. Shared
  // by the top-right search and the Explorer tree so both behave the same way.
  const focusConceptInGraph = useCallback(
    (conceptName: string, cell: ConceptCell | undefined) => {
      const node = nodes.find((n) => n.data.label === conceptName);
      if (node && reactFlowInstance.current) {
        skipAutoFitViewRef.current = true;
        // Select the node (blue ring) and light up its upstream edges in blue —
        // identical to clicking the node directly.
        selectedNodeIdRef.current = node.id;
        setNodes((nds) => nds.map((n) => ({ ...n, selected: n.id === node.id })));
        const highlighted = collectUpstreamEdgeIds(node.id, baseEdgesRef.current);
        setEdges(
          applySelectionHighlight(baseEdgesRef.current, highlighted, conceptStatusesRef.current),
        );
        reactFlowInstance.current.fitView({
          nodes: [node],
          duration: 500,
          padding: 0.5,
          maxZoom: 0.7,
        });
      }
      setDatasourcePanelInfo(null);
      if (cell) {
        setPanelState({
          conceptName,
          cellId: cell.id,
          isNew: false,
          panelKey: `focus-${node?.id ?? cell.id}-${Date.now()}`,
        });
      }
    },
    [nodes, setNodes, setEdges, conceptStatusesRef],
  );

  // Selecting a concept in the left tree focuses its node and opens it in the dock.
  const handleTreeSelect = useCallback(
    (cellId: string) => {
      const cell = nb.cells.find((c) => c.id === cellId);
      if (!cell) return;
      focusConceptInGraph(cell.outputPredicate || cell.id, cell);
    },
    [nb.cells, focusConceptInGraph],
  );

  // ---------------------------------------------------------------------------
  // "New Concept" button
  // ---------------------------------------------------------------------------
  const newCellIdRef = useRef<string | null>(null);
  const handleNewConcept = useCallback(() => {
    // Reuse an existing blank, unsaved concept instead of stacking up empties on
    // repeated clicks (close panel → reopen → click again). The concepts-list
    // "Logic" button keeps adding unconditionally; this is the header button only.
    const cell = nb.cells.find(isBlankUnsavedCell) ?? nb.handleAddCell();
    newCellIdRef.current = cell.id;
    // Always show the new concept, replacing whatever was selected (including an
    // open datasource panel). Don't collapse: full-screen just adds it into the
    // expanded editor; collapsed shows the new-concept panel as before.
    setDatasourcePanelInfo(null);
    setPanelState({
      conceptName: `__new__${cell.id}`,
      isNew: true,
      panelKey: `new-${Date.now()}`,
    });
  }, [nb.cells, nb.handleAddCell]);

  // A concept's context panel can ask for a new static context cell
  // pre-pinned with that concept's attached notes ("make this knowledge
  // computable"). Consume the request and open the new cell like the
  // "New Concept" button does.
  const pendingContextCellSeed = useEditorActionsStore((s) => s.pendingContextCellSeed);
  useEffect(() => {
    if (!pendingContextCellSeed) return;
    useEditorActionsStore.getState().register({ pendingContextCellSeed: null });
    const cell = nb.handleAddContextCell(pendingContextCellSeed.noteIds);
    newCellIdRef.current = cell.id;
    setDatasourcePanelInfo(null);
    setPanelState({
      conceptName: `__new__${cell.id}`,
      isNew: true,
      panelKey: `new-${Date.now()}`,
    });
  }, [pendingContextCellSeed, nb.handleAddContextCell]);

  // ---------------------------------------------------------------------------
  // Wrap cell handlers to refresh lineage after mutations
  // ---------------------------------------------------------------------------
  const handleRunCell = useCallback(
    async (cellId: string, freshCode?: string, forceRerun?: boolean) => {
      // No compute running → prompt the user to start a machine instead of failing.
      if (!ensureCompute()) return;
      // Verify the selected pool machine is the one that is actually active.
      // The selection can be stale (e.g. machine A was running, user switched to B on the
      // Compute Management page, but selectedMachineId still points to A).
      // Only applies to pool machines — Databricks selection is managed separately.
      const currentCompute = localStorage.getItem("selectedCompute");
      if (currentCompute === "pools" && hasRunningMachine) {
        const selectedMachineId = localStorage.getItem("selectedMachineId");
        const selectedUm = selectedMachineId
          ? userMachines.find((um) => um.machines?.id === selectedMachineId)
          : null;
        const selectedIsActive = selectedUm?.is_active;
        if (!selectedIsActive) {
          autoSelectRunningCompute();
        }
      }
      await nb.handleRunCell(cellId, freshCode, forceRerun);
      if (onRefreshLineage) {
        skipAutoFitViewRef.current = true;
        onRefreshLineage();
      }
    },
    [
      nb.handleRunCell,
      onRefreshLineage,
      hasRunningMachine,
      userMachines,
      autoSelectRunningCompute,
      ensureCompute,
    ],
  );

  const handleSaveCell = useCallback(
    async (cellId: string, freshCode?: string, showToast?: boolean) => {
      const savedBackendId = await nb.handleSaveCell(cellId, freshCode, showToast);
      if (onRefreshLineage) {
        skipAutoFitViewRef.current = true;
        onRefreshLineage();
      }
      return savedBackendId;
    },
    [nb.handleSaveCell, onRefreshLineage],
  );

  const handleDeleteCell = useCallback(
    async (cellId: string) => {
      await nb.handleDeleteCell(cellId);
      setPanelState(null);
      dock.restore();
      if (onRefreshLineage) {
        skipAutoFitViewRef.current = true;
        await onRefreshLineage();
      }
    },
    [nb.handleDeleteCell, onRefreshLineage, dock.restore],
  );

  // ---------------------------------------------------------------------------
  // Lineage card actions (rename / delete from the card kebab menu)
  // ---------------------------------------------------------------------------
  const handleCardRename = useCallback(
    async (oldName: string, newName: string) => {
      const cell = findCellForConcept(oldName);
      if (!cell) {
        toast.error(`Cell for concept "${oldName}" not found`);
        return;
      }
      await nb.handleRenameConcept(cell.id, newName);
      if (onRefreshLineage) {
        skipAutoFitViewRef.current = true;
        await onRefreshLineage();
      }
    },
    [findCellForConcept, nb.handleRenameConcept, onRefreshLineage],
  );

  const handleCardDelete = useCallback(
    async (conceptName: string) => {
      const cell = findCellForConcept(conceptName);
      if (!cell) {
        toast.error(`Cell for concept "${conceptName}" not found`);
        return;
      }
      await handleDeleteCell(cell.id);
    },
    [findCellForConcept, handleDeleteCell],
  );

  const handleRenameConcept = useCallback(
    async (cellId: string, newName: string) => {
      // Capture the old concept name BEFORE the rename so we can update
      // panelState (the rename also calls loadCells which regenerates
      // client-side cell IDs, so cellId-based lookups go stale).
      const oldName = nb.cells.find((c) => c.id === cellId)?.outputPredicate;
      await nb.handleRenameConcept(cellId, newName);
      // Don't null panelState — the `panelOpen` check would unmount the editor
      // dock, dumping the user back to the lineage graph. Instead, update the
      // conceptName so the dock keeps tracking the same cell under its new name.
      // Clearing cellId here forces activeCell to resolve via the (fresh) name lookup.
      const normalizedNewName = newName.trim().toLowerCase();
      setPanelState((prev) => {
        if (!prev) return prev;
        if (prev.conceptName !== oldName) return prev;
        return { ...prev, conceptName: normalizedNewName, cellId: undefined };
      });
      if (onRefreshLineage) {
        skipAutoFitViewRef.current = true;
        await onRefreshLineage();
      }
    },
    [nb.cells, nb.handleRenameConcept, onRefreshLineage],
  );

  const handleConfirmOverwrite = useCallback(async () => {
    await nb.handleConfirmOverwrite();
    setPanelState(null);
    dock.restore();
    if (onRefreshLineage) {
      skipAutoFitViewRef.current = true;
      await onRefreshLineage();
    }
  }, [nb.handleConfirmOverwrite, onRefreshLineage, dock.restore]);

  const cardActions = useConceptCardActions({
    onRename: handleCardRename,
    onDelete: handleCardDelete,
    onManagePermissions: handleManagePermissions,
    canManage: permissionAccess.canManage,
  });

  // ---------------------------------------------------------------------------
  // Search handler
  // ---------------------------------------------------------------------------
  const handleSearchSelect = useCallback(
    (conceptName: string) => {
      focusConceptInGraph(conceptName, findCellForConcept(conceptName));
      setSearchOpen(false);
      setSearchValue("");
    },
    [focusConceptInGraph, findCellForConcept],
  );

  // nodesRef and registerEditorActions are used by the registration effect below
  // (placed after activeCell to avoid TDZ — activeCell is defined at line ~803).
  const nodesRef = useRef(nodes);
  nodesRef.current = nodes;
  const registerEditorActions = useEditorActionsStore((s) => s.register);

  // ---------------------------------------------------------------------------
  // Focus / select a concept in the panel (cross-view focus + expanded-panel
  // data-sidebar creation). See useLineageConceptFocus.
  // ---------------------------------------------------------------------------
  useLineageConceptFocus({
    focusConceptName,
    onFocusConsumed,
    nodes,
    findCellForConcept,
    loadCells: nb.loadCells,
    reactFlowInstance,
    skipAutoFitViewRef,
    setPanelState,
  });

  // A concept was created somewhere (data sidebar, AI assistant, …). Reload the
  // editor's cells. The graph refresh + selection of the new concept is driven
  // separately by the `lineageFocusConcept` window event (see Lineage.tsx),
  // which always fires now that there is a single, non-fullscreen editor dock.
  useEffect(() => {
    const handleConceptCreated = () => nb.loadCells();
    window.addEventListener("conceptCreated", handleConceptCreated);
    return () => window.removeEventListener("conceptCreated", handleConceptCreated);
  }, [nb.loadCells]);

  // ---------------------------------------------------------------------------
  // Resolve active cell from panel state
  // ---------------------------------------------------------------------------
  const activeCell = useMemo(() => {
    if (!panelState) return null;
    if (panelState.isNew && panelState.conceptName.startsWith("__new__")) {
      const newId = newCellIdRef.current;
      return nb.cells.find((c) => c.id === newId) ?? null;
    }
    return (
      findCellForConcept(panelState.conceptName) ??
      (panelState.cellId ? nb.cells.find((c) => c.id === panelState.cellId) : null) ??
      null
    );
  }, [panelState, nb.cells, findCellForConcept]);

  // Register lineage actions with the editor header store.
  // Placed here (after activeCell) to avoid TDZ — activeCell is used in the effect.
  useEffect(() => {
    const canRun = !!(activeCell && panelState && !panelState.isNew);
    registerEditorActions({
      onNewConcept: handleNewConcept,
      lineageSearchValue: searchValue,
      setLineageSearchValue: setSearchValue,
      lineageSearchNodes: nodesRef.current
        .filter((n) => n.data.nodeType !== "datasource")
        .map((n) => ({
          id: n.id,
          label: n.data.label as string,
          nodeType: n.data.nodeType as string | undefined,
        })),
      onLineageSearchSelect: handleSearchSelect,
      canRunConcept: canRun,
      isRunningConcept: canRun ? (activeCell?.isRunning ?? false) : false,
      onRunConcept: canRun ? () => handleRunCell(activeCell!.id) : null,
      isLineagePanelExpanded: false,
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    handleNewConcept,
    searchValue,
    handleSearchSelect,
    registerEditorActions,
    activeCell,
    activeCell?.isRunning,
    panelState?.isNew,
    handleRunCell,
    panelState,
  ]);

  const bgStyle = useMemo<CSSProperties>(
    () => ({ backgroundColor: "hsl(var(--flow-bg, var(--background)))" }),
    [],
  );

  const unsavedCellCount = nb.cells.filter((c) => c.isModified).length;
  const runningCellCount = nb.cells.filter((c) => c.isRunning).length;

  return (
    <div className="absolute inset-0 flex flex-col" data-lineage-root>
      <LineageStyles />
      <RunLimitDialog />
      <LineageLoadingOverlay visible={isLineageLoading || nb.isLoading} />

      <div className="flex min-h-0 flex-1">
        {/* Left rail toggles the Explorer tree — mirrors the right Concepts/Data rail */}
        <LineageTreeRail isOpen={isTreeOpen} onToggle={toggleTree} />

        {/* Independent left file-tree panel */}
        {isTreeOpen && (
          <LineageExplorerPanel
            groups={groups}
            cells={nb.cells}
            selectedCellId={activeCell?.id ?? null}
            onSelectCell={handleTreeSelect}
            canEditOntologies={canEditOntologies}
            onAddCell={nb.handleAddCell}
            onRenameConcept={handleRenameConcept}
            onDeleteCell={handleDeleteCell}
            onIsolateConcept={onIsolateConcept}
            onOutputPredicateChange={nb.handleOutputPredicateChange}
            searchTerm={treeSearch}
            onSearchTermChange={setTreeSearch}
            onRefresh={editorActions.handleRefresh}
            isRefreshing={editorActions.isRefreshing}
            onSaveAll={editorActions.saveAllChanges}
            isSavingAll={editorActions.isSavingAll}
            hasUnsavedChanges={editorActions.hasUnsavedChanges}
          />
        )}

        <ResizablePanelGroup direction="vertical" className="min-w-0 flex-1">
          {/* Lineage canvas — collapsible so maximizing the dock fills the view */}
          <ResizablePanel
            id="lineage-canvas"
            order={1}
            ref={dock.canvasPanelRef}
            minSize={20}
            collapsible
            collapsedSize={0}
            onCollapse={dock.onCanvasCollapse}
            onExpand={dock.onCanvasExpand}
          >
            <div className="relative h-full w-full">
              {/* Top-left controls overlay */}
              <div className="absolute top-4 left-4 z-10 flex items-center gap-3">
                {onToggleSidebar && (
                  <SidebarToggleButton
                    onToggleSidebar={onToggleSidebar}
                    sidebarVisible={sidebarVisible}
                  />
                )}
                {topLeftControls}
                {isolatedConcept && onClearIsolation && (
                  <LineageFocusBanner conceptName={isolatedConcept} onClear={onClearIsolation} />
                )}
              </div>

              {/* Top-right overlay — group colour legend + visibility filter */}
              {groupLegend.length > 0 && (
                <div className="absolute top-4 right-4 z-10">
                  <LineageGroupLegend
                    entries={groupLegend}
                    isGroupVisible={groupFilter.isGroupVisible}
                    onToggleGroup={groupFilter.toggleGroup}
                  />
                </div>
              )}

              <LineageCardActionsContext.Provider value={cardActions}>
                <ReactFlow
                  proOptions={{ hideAttribution: true }}
                  nodes={visibleNodes}
                  edges={visibleEdges}
                  onNodesChange={onNodesChange}
                  onEdgesChange={onEdgesChange}
                  nodeTypes={nodeTypes}
                  nodesFocusable={false}
                  nodesConnectable={false}
                  onNodeClick={handleNodeClick}
                  onNodeDoubleClick={handleNodeDoubleClick}
                  onPaneClick={handlePaneClick}
                  minZoom={0.1}
                  maxZoom={1.5}
                  fitView
                  onInit={(instance) => {
                    reactFlowInstance.current = instance;
                    instance.fitView({ padding: 0.15 });
                  }}
                  style={{ width: "100%", height: "100%" }}
                >
                  <Background color="hsl(var(--border))" style={bgStyle} gap={28} size={0.8} />
                  <Controls className="glass-card">
                    <ControlButton
                      onClick={toggleAllCards}
                      title={allCardsExpanded ? "Collapse all cards" : "Expand all cards"}
                      aria-label={allCardsExpanded ? "Collapse all cards" : "Expand all cards"}
                    >
                      {allCardsExpanded ? <ChevronsDownUp /> : <ChevronsUpDown />}
                    </ControlButton>
                  </Controls>
                </ReactFlow>
              </LineageCardActionsContext.Provider>

              {permissionsTarget && lineageOntologyId && (
                <ErrorBoundary inline>
                  <ConceptRestrictionsDialog
                    isOpen
                    onClose={() => setPermissionsTarget(null)}
                    ontologyId={lineageOntologyId}
                    predicateName={permissionsTarget}
                    caller={permissionAccess.caller}
                    ownerSub={permissionAccess.ownerSub}
                  />
                </ErrorBoundary>
              )}
            </div>
          </ResizablePanel>

          {/* The single editor dock — resizable; the header's expand button
            maximizes/restores it. There is no separate full-screen mode. */}
          {panelOpen && !dock.isMaximized && <ResizableHandle withHandle />}
          {panelOpen && (
            <ResizablePanel
              id="lineage-dock"
              order={2}
              defaultSize={DOCK_DEFAULT_PCT}
              minSize={15}
              className="flex flex-col overflow-hidden"
            >
              <LineagePanelHeader
                showCounts={!datasourcePanelInfo && !notePanel}
                unsavedCount={unsavedCellCount}
                runningCount={runningCellCount}
                isExpanded={dock.isMaximized}
                onToggleExpand={dock.toggleMaximize}
                onClose={handleClosePanel}
              />

              <div className="flex min-h-0 flex-1">
                {notePanel && (
                  <NoteDockPanel
                    key={notePanel.noteId ?? "draft"}
                    noteId={notePanel.noteId}
                    ontologyId={lineageOntologyId ?? ""}
                    onClose={handleClosePanel}
                    onCreated={(noteId) => setNotePanel({ noteId })}
                  />
                )}
                {!notePanel && datasourcePanelInfo ? (
                  <DatasourceDetailPanel
                    key={datasourcePanelInfo.nodeId}
                    datasource={datasourcePanelInfo}
                  />
                ) : !notePanel && activeCell ? (
                  // Two scoped layouts (see code-editor.css): the IDE split when
                  // maximized (explorer-cell-host) vs the single-view, all-tabs-
                  // on-top layout when collapsed (lineage-cell-host).
                  <div
                    className={
                      dock.isMaximized
                        ? "explorer-cell-host min-w-0 flex-1 overflow-hidden"
                        : "lineage-cell-host flex min-h-0 flex-1 flex-col overflow-hidden"
                    }
                  >
                    <SelectedCellEditor
                      key={panelState?.panelKey}
                      cell={activeCell}
                      expanded={dock.isMaximized}
                      extensionsWithLinter={extensionsWithLinter}
                      extensionsWithoutLinter={extensionsWithoutLinter}
                      extensionsPython={extensionsPython}
                      editorTheme="light"
                      setCells={nb.setCells}
                      onCodeChange={nb.handleCodeChange}
                      onRunCell={handleRunCell}
                      onSaveCell={handleSaveCell}
                      onDeleteCell={handleDeleteCell}
                      onStopCell={nb.handleStopCell}
                      onClearResults={nb.handleClearResults}
                      onRestoreResults={nb.handleRestoreResults}
                      onIndentCode={handleIndentCode}
                      onOpenAssistant={handleOpenAssistant}
                      onCellTypeChange={nb.handleCellTypeChange}
                      onOutputPredicateChange={nb.handleOutputPredicateChange}
                      onRenameConcept={handleRenameConcept}
                      groupNames={groups.groupNames}
                      onAddCellToGroup={groups.handleAddCellToGroup}
                      onRemoveCellFromGroup={groups.handleRemoveCellFromGroup}
                      bottomTab={dock.bottomTab}
                      onBottomTabChange={dock.setBottomTab}
                    />
                  </div>
                ) : null}
              </div>
            </ResizablePanel>
          )}
        </ResizablePanelGroup>

        {/* Independent right Concepts/Data panel — available without the dock */}
        {librarySidebarPanel && (
          <ConceptLibrarySidebar
            panel={librarySidebarPanel}
            cells={nb.cells}
            onRefreshCells={nb.loadCells}
            onOpenContextNote={handleOpenContextNote}
            onCreateContextNote={handleCreateContextNote}
          />
        )}
        <LibraryRail activePanel={librarySidebarPanel} onPanelChange={setLibrarySidebarPanel} />
      </div>

      <OverwriteConfirmDialog
        open={nb.conflictDialog.open}
        conceptName={nb.conflictDialog.conceptName}
        onOpenChange={(open) => !open && nb.handleCancelOverwrite()}
        onConfirm={handleConfirmOverwrite}
      />

      <GroupDialog
        isOpen={groups.showGroupDialog}
        onClose={groups.closeGroupDialog}
        onConfirm={groups.confirmGroupDialog}
        initialName={groups.editingGroupName ?? ""}
        mode={groups.groupDialogMode}
        existingGroups={groups.groupNames}
      />
    </div>
  );
};

const LineageView: React.FC<LineageViewProps> = (props) => (
  <ReactFlowProvider>
    <LineageViewInner {...props} />
  </ReactFlowProvider>
);

export default React.memo(LineageView);
