import { Loader2, Undo2 } from "lucide-react";
import type React from "react";
import { useMemo } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { useTeamMembers } from "@/features/teams/hooks/useTeamMembers";
import { Button } from "@/shared/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import { useConceptRestrictions } from "../hooks/useConceptRestrictions";
import { useOntologyRoleOverride } from "../hooks/useOntologyRoleOverride";
import {
  type ConceptRestriction,
  OWNER_CALLER,
  type PermissionCaller,
  type ShareRole,
} from "../types";
import { normalizeLevel } from "../utils/conceptAccess.utils";
import { isAssignableSubjectMember } from "../utils/sharing.utils";

interface TeamMemberOverridesProps {
  ontologyId: string;
  teamId: string;
  caller?: PermissionCaller;
  // The project owner's id — excluded from the roster (can't be restricted).
  // In owner mode the current user is the owner and is dropped automatically.
  ownerSub?: string;
  // The team's base share role — surfaced in the dropdown so a member with no
  // override reads e.g. "Viewer (team role)" instead of a vague "Team role".
  teamBaseRole?: ShareRole;
}

type OverrideValue = ShareRole | "default";

// Project-level override rows carry the effective base role as a restriction
// level: read_write → editor, read_only → viewer. Absence means "inherit the
// team base role" (Default).
function overrideForSub(restrictions: ConceptRestriction[], sub: string): OverrideValue {
  const row = restrictions.find(
    (r) =>
      r.scope === "ontology" &&
      r.subject_type === "user" &&
      (r.recipient_sub ?? r.subject_id) === sub,
  );
  if (!row) return "default";
  return normalizeLevel(row.level) === "read_write" ? "editor" : "viewer";
}

// The dropdown only offers explicit roles now; "revert to inherit" is a
// separate Reset action rather than a third dropdown item.
function isAssignableRole(value: string): value is ShareRole {
  return value === "viewer" || value === "editor";
}

const TeamMemberOverrides: React.FC<TeamMemberOverridesProps> = ({
  ontologyId,
  teamId,
  caller = OWNER_CALLER,
  ownerSub,
  teamBaseRole,
}) => {
  const { user } = useAuth();
  const { members, isLoading, error } = useTeamMembers(teamId, { enabled: Boolean(teamId) });
  const { restrictions } = useConceptRestrictions({ ontologyId, caller });
  const { setOntologyRole, clearOntologyRole, isSettingOntologyRole, isClearingOntologyRole } =
    useOntologyRoleOverride(caller);

  const isBusy = isSettingOntologyRole || isClearingOntologyRole;

  // Shown when a member has no explicit override — spells out the inherited team
  // role (e.g. "Viewer (team role)") rather than the ambiguous "Team role".
  const inheritPlaceholder = teamBaseRole
    ? `${teamBaseRole === "editor" ? "Editor" : "Viewer"} (team role)`
    : "Team role";

  const assignableMembers = useMemo(
    () =>
      members.filter((m) =>
        isAssignableSubjectMember(m, {
          currentUserId: user?.id ?? "",
          ownerSub,
          excludeTeamOwner: caller.mode === "team_admin",
        }),
      ),
    [members, user?.id, ownerSub, caller.mode],
  );

  const overrideBySub = useMemo(() => {
    const map = new Map<string, OverrideValue>();
    for (const member of assignableMembers) {
      map.set(member.user_id, overrideForSub(restrictions, member.user_id));
    }
    return map;
  }, [assignableMembers, restrictions]);

  const handleChange = async (recipientSub: string, value: string): Promise<void> => {
    if (!isAssignableRole(value)) return;
    try {
      await setOntologyRole({ ontologyId, recipientSub, role: value });
      toast.success(`Member set to ${value}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to update member role";
      toast.error(message);
    }
  };

  const handleReset = async (recipientSub: string): Promise<void> => {
    try {
      await clearOntologyRole({ ontologyId, recipientSub });
      toast.success("Reverted to team base role");
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to reset member role";
      toast.error(message);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center gap-2 px-3 py-2 text-xs text-muted-foreground">
        <Loader2 className="h-3 w-3 animate-spin" />
        Loading members…
      </div>
    );
  }

  if (error) {
    return <p className="px-3 py-2 text-xs text-destructive">{error.message}</p>;
  }

  if (assignableMembers.length === 0) {
    return (
      <p className="px-3 py-2 text-xs text-muted-foreground">No members available to override.</p>
    );
  }

  return (
    <div className="space-y-1 rounded-md border border-border bg-muted/20 p-2">
      <p className="px-1 pb-1 text-[11px] text-muted-foreground">
        Override a member's base role. Reset to inherit the team role.
      </p>
      {assignableMembers.map((member) => {
        const value = overrideBySub.get(member.user_id) ?? "default";
        const hasOverride = value !== "default";
        return (
          <div key={member.user_id} className="flex items-center justify-between gap-2 px-1 py-0.5">
            <span className="min-w-0 truncate text-xs text-foreground">
              {member.username}
              <span className="text-muted-foreground">@{member.organization}</span>
            </span>
            <div className="flex flex-shrink-0 items-center gap-1">
              <Select
                value={hasOverride ? value : undefined}
                onValueChange={(v) => handleChange(member.user_id, v)}
                disabled={isBusy}
              >
                <SelectTrigger className="h-7 w-[150px] px-2 py-0 text-xs">
                  <SelectValue placeholder={inheritPlaceholder} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="viewer">Viewer</SelectItem>
                  <SelectItem value="editor">Editor</SelectItem>
                </SelectContent>
              </Select>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={() => handleReset(member.user_id)}
                disabled={isBusy || !hasOverride}
                title="Reset to team role"
              >
                <Undo2 className="h-3.5 w-3.5" />
              </Button>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default TeamMemberOverrides;
