import { useConcepts } from "@/features/concepts/hooks/useConcepts";
import { useSharedOntologyContext } from "./useSharedOntologyContext";

// Effective read-only state for ontology-*wide* edit surfaces — ones that are
// NOT tied to a single concept (e.g. "Save graph", "New Concept"). Per-concept
// elevation still has to unlock these, otherwise a viewer with a writeable
// concept could edit the concept's cell but never save the graph or add the
// concepts it depends on.
//
// Rule:
//   - not a viewer share (owner / editor)        → editable (false)
//   - viewer share, ≥1 concept is writeable      → editable (false)  [elevation]
//   - viewer share, every concept is read-only   → blocked  (true)
//
// A concept is "writeable" when the concept list marks it `read_only === false`
// (the backend sets this per concept to reflect the recipient's effective
// access, folding in any elevation). The backend still enforces the per-concept
// rules on the mutating routes, so allowing the surface here is safe — the
// server rejects writes to concepts the user can't modify.
export function useOntologyWideReadOnly(): boolean {
  const { isReadOnly } = useSharedOntologyContext();
  const { concepts } = useConcepts();

  if (!isReadOnly) return false;
  const hasWriteableConcept = concepts.some((c) => c.read_only === false);
  return !hasWriteableConcept;
}
