import type React from "react";
import { usePermissionsStore } from "@/features/auth/store/permissionsStore";
import { cn } from "@/shared/lib/utils";
import type { ShareType } from "../types";

const SHARE_MODES: readonly { value: ShareType; label: string }[] = [
  { value: "user", label: "Person" },
  { value: "team", label: "Team" },
];

interface ShareModeSelectorProps {
  value: ShareType;
  onChange: (mode: ShareType) => void;
}

const ShareModeSelector: React.FC<ShareModeSelectorProps> = ({ value, onChange }) => {
  const canSeeTeams = usePermissionsStore((state) => state.canSee("can_see_teams"));
  if (!canSeeTeams) return null;

  return (
    <div className="grid grid-cols-2 gap-2">
      {SHARE_MODES.map((option) => {
        const isActive = value === option.value;
        return (
          <button
            key={option.value}
            type="button"
            onClick={() => onChange(option.value)}
            className={cn(
              "rounded-md border px-3 py-2 text-sm font-medium transition-colors",
              isActive
                ? "border-foreground bg-foreground text-background"
                : "border-border bg-card text-muted-foreground hover:text-foreground",
            )}
          >
            {option.label}
          </button>
        );
      })}
    </div>
  );
};

export default ShareModeSelector;
