import type React from "react";
import type { ShareRole } from "../types";
import RosterRow, { type RosterOption } from "./RosterRow";

// "Inherit" is not a dropdown option — clearing an override is done via the
// Reset button, and the inherited role is shown in the trigger placeholder.
const MEMBER_ROLE_OPTIONS: RosterOption[] = [
  { value: "editor", label: "Editor" },
  { value: "viewer", label: "Viewer" },
];

const TEAM_ROLE_OPTIONS: RosterOption[] = [
  { value: "editor", label: "Editor" },
  { value: "viewer", label: "Viewer" },
];

function roleBadge(role: ShareRole): { text: string; cls: string } {
  if (role === "editor") {
    return {
      text: "Editor",
      cls: "bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-400",
    };
  }
  return {
    text: "Viewer",
    cls: "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-400",
  };
}

const isShareRole = (value: string): value is ShareRole => value === "editor" || value === "viewer";

interface TeamRoleRowProps {
  name: string;
  baseRole: ShareRole;
  editable: boolean;
  isBusy: boolean;
  onSet: (role: ShareRole) => void;
}

export const TeamRoleRow: React.FC<TeamRoleRowProps> = ({
  name,
  baseRole,
  editable,
  isBusy,
  onSet,
}) => {
  const badge = roleBadge(baseRole);
  const handleChange = (value: string): void => {
    if (isShareRole(value)) onSet(value);
  };
  return (
    <RosterRow
      label={name}
      badgeText={badge.text}
      badgeClass={badge.cls}
      options={TEAM_ROLE_OPTIONS}
      value={baseRole}
      editable={editable}
      isBusy={isBusy}
      onChange={handleChange}
    />
  );
};

interface MemberRoleRowProps {
  label: string;
  hint?: string;
  effective: ShareRole;
  override?: ShareRole;
  editable: boolean;
  isBusy: boolean;
  onSet: (role: ShareRole) => void;
  onClear: () => void;
}

export const MemberRoleRow: React.FC<MemberRoleRowProps> = ({
  label,
  hint,
  effective,
  override,
  editable,
  isBusy,
  onSet,
  onClear,
}) => {
  const badge = roleBadge(effective);
  const handleChange = (value: string): void => {
    if (isShareRole(value)) onSet(value);
  };
  // Without an override the row inherits its role; surface the concrete
  // inherited value in the trigger (e.g. "Editor (inherited)").
  const inheritedPlaceholder = `${badge.text} (inherited)`;
  return (
    <RosterRow
      label={label}
      hint={hint}
      badgeText={badge.text}
      badgeClass={badge.cls}
      options={MEMBER_ROLE_OPTIONS}
      value={override}
      placeholder={inheritedPlaceholder}
      editable={editable}
      isBusy={isBusy}
      onChange={handleChange}
      onReset={onClear}
      canReset={Boolean(override)}
    />
  );
};
