import { Check, ChevronDown, ChevronUp, ExternalLink, X } from "lucide-react";
import type React from "react";
import { useState } from "react";
import { useNavigate } from "react-router-dom";

import { useAuth } from "@/features/auth/components/AuthProvider";
import { setCurrentOntologyId, setCurrentOntologyScope } from "@/features/ontologies/utils";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { generateEditorUrl } from "@/shared/utils/navigationUtils";

import type { ProposalData } from "../store";

type ToolStatus = "running" | "done" | "error";

function statusBorder(status: ToolStatus | undefined, deletingDestructive = false): string {
  if (status === "done") return "border-green-500/40 bg-green-500/5";
  if (status === "error") return "border-destructive/40 bg-destructive/5";
  if (deletingDestructive) return "border-destructive/40 bg-destructive/5";
  return "border-primary/40 bg-primary/5";
}

interface ConceptProposalCardProps {
  data: ProposalData;
  toolStatus?: ToolStatus;
}

export const ConceptProposalCard: React.FC<ConceptProposalCardProps> = ({ data, toolStatus }) => {
  const [expanded, setExpanded] = useState(false);
  const actionLabel = data.tool === "update_concept" ? "Updating" : "Creating";

  return (
    <div className={`rounded-lg border text-xs overflow-hidden ${statusBorder(toolStatus)}`}>
      <div className="px-3 py-2 flex items-center justify-between gap-2">
        <div className="flex items-center gap-1.5 min-w-0">
          {(toolStatus === "running" || !toolStatus) && (
            <PrometheuxSpinner size={16} className="flex-shrink-0" />
          )}
          {toolStatus === "done" && <Check className="h-3 w-3 text-green-500 flex-shrink-0" />}
          {toolStatus === "error" && <X className="h-3 w-3 text-destructive flex-shrink-0" />}
          <span className="font-medium text-primary flex-shrink-0">{actionLabel} concept</span>
          {data.concept_name && (
            <span className="font-mono text-[11px] text-muted-foreground truncate">
              {data.concept_name}
            </span>
          )}
        </div>
        {data.definition && (
          <button
            type="button"
            onClick={() => setExpanded((v) => !v)}
            className="flex-shrink-0 text-muted-foreground hover:text-foreground transition-colors"
            title={expanded ? "Hide code" : "Show code"}
          >
            {expanded ? (
              <ChevronUp className="h-3.5 w-3.5" />
            ) : (
              <ChevronDown className="h-3.5 w-3.5" />
            )}
          </button>
        )}
      </div>

      {expanded && data.definition && (
        <div className="border-t border-border/50 bg-muted/40 px-3 py-2 font-mono text-[11px] whitespace-pre-wrap leading-relaxed max-h-48 overflow-y-auto">
          {data.definition}
        </div>
      )}

      {data.description && (
        <div className="px-3 pb-2 text-muted-foreground text-[11px]">{data.description}</div>
      )}
    </div>
  );
};

interface DashboardProposalCardProps {
  data: ProposalData;
  toolStatus?: ToolStatus;
}

export const DashboardProposalCard: React.FC<DashboardProposalCardProps> = ({
  data,
  toolStatus,
}) => {
  const isDelete = data.tool === "delete_app" || data.tool === "delete_dashboard";
  const actionLabel = isDelete ? "Deleting app" : "Creating app";
  const displayName = data.dashboard_name || data.dashboard_id || "";

  return (
    <div
      className={`rounded-lg border text-xs overflow-hidden ${statusBorder(toolStatus, isDelete)}`}
    >
      <div className="px-3 py-2 flex items-center gap-1.5 min-w-0">
        {(toolStatus === "running" || !toolStatus) && (
          <PrometheuxSpinner size={16} className="flex-shrink-0" />
        )}
        {toolStatus === "done" && <Check className="h-3 w-3 text-green-500 flex-shrink-0" />}
        {toolStatus === "error" && <X className="h-3 w-3 text-destructive flex-shrink-0" />}
        <span className="font-medium text-primary flex-shrink-0">{actionLabel}</span>
        {displayName && (
          <span className="font-mono text-[11px] text-muted-foreground truncate">
            {displayName}
          </span>
        )}
        {!isDelete && data.page_count != null && (
          <span className="text-[11px] text-muted-foreground flex-shrink-0 ml-auto">
            {data.page_count}p · {data.widget_count ?? 0}w
          </span>
        )}
      </div>
    </div>
  );
};

interface OntologySchemaProposalCardProps {
  data: ProposalData;
  toolStatus?: ToolStatus;
}

export const OntologySchemaProposalCard: React.FC<OntologySchemaProposalCardProps> = ({
  data,
  toolStatus,
}) => {
  const hasCounts = data.node_count != null || data.edge_count != null;

  return (
    <div className={`rounded-lg border text-xs overflow-hidden ${statusBorder(toolStatus)}`}>
      <div className="px-3 py-2 flex items-center gap-1.5 min-w-0">
        {(toolStatus === "running" || !toolStatus) && (
          <PrometheuxSpinner size={16} className="flex-shrink-0" />
        )}
        {toolStatus === "done" && <Check className="h-3 w-3 text-green-500 flex-shrink-0" />}
        {toolStatus === "error" && <X className="h-3 w-3 text-destructive flex-shrink-0" />}
        <span className="font-medium text-primary flex-shrink-0">Saving schema</span>
        {hasCounts && (
          <span className="text-[11px] text-muted-foreground flex-shrink-0 ml-auto">
            {data.node_count ?? 0} nodes · {data.edge_count ?? 0} edges
          </span>
        )}
      </div>
    </div>
  );
};

interface OntologyProposalCardProps {
  data: ProposalData;
  toolStatus?: ToolStatus;
  createdOntologyId?: string;
}

export const OntologyProposalCard: React.FC<OntologyProposalCardProps> = ({
  data,
  toolStatus,
  createdOntologyId,
}) => {
  const navigate = useNavigate();
  const { user } = useAuth();

  const handleOpen = () => {
    if (!createdOntologyId) return;
    sessionStorage.removeItem("ontologyConceptCells");
    sessionStorage.setItem("newOntologyScope", "user");
    setCurrentOntologyId(createdOntologyId);
    setCurrentOntologyScope("user");
    navigate(generateEditorUrl(user, createdOntologyId), { state: { activeTab: "lineage" } });
  };

  return (
    <div className={`rounded-lg border text-xs overflow-hidden ${statusBorder(toolStatus)}`}>
      <div className="px-3 py-2 flex items-center justify-between gap-2">
        <div className="flex items-center gap-1.5 min-w-0">
          {(toolStatus === "running" || !toolStatus) && (
            <PrometheuxSpinner size={16} className="flex-shrink-0" />
          )}
          {toolStatus === "done" && <Check className="h-3 w-3 text-green-500 flex-shrink-0" />}
          {toolStatus === "error" && <X className="h-3 w-3 text-destructive flex-shrink-0" />}
          <span className="font-medium text-primary flex-shrink-0">Creating ontology</span>
          {data.concept_name && (
            <span className="font-mono text-[11px] text-muted-foreground truncate">
              {data.concept_name}
            </span>
          )}
        </div>
        {toolStatus === "done" && createdOntologyId && (
          <button
            type="button"
            onClick={handleOpen}
            className="flex-shrink-0 flex items-center gap-1 text-[11px] text-primary hover:underline"
          >
            <ExternalLink className="h-3 w-3" />
            Open
          </button>
        )}
      </div>
      {data.description && (
        <div className="px-3 pb-2 text-muted-foreground text-[11px]">{data.description}</div>
      )}
    </div>
  );
};
