import { useEffect, useRef, useState } from "react";

import type { CellView } from "@/features/concept-editor/components/query/components/CellViewTabs";
import type { ConceptCell } from "@/features/concept-editor/types";

type Initial<V extends string> = V | (() => V);

/**
 * View state for a concept cell with the established auto-switch behavior: jump
 * to the output view when a run finishes or a result first appears.
 *
 * Each cell type has its own set of views, so the type parameter carries them;
 * `"output"` is always available since this hook selects it. Pass a function to
 * compute the initial view lazily.
 */
export function useCellView<V extends string = CellView>(
  cell: ConceptCell,
  initial: Initial<V | "output">,
) {
  const [currentView, setCurrentView] = useState<V | "output">(initial);

  const prevIsRunning = useRef(cell.isRunning);
  useEffect(() => {
    if (prevIsRunning.current && !cell.isRunning) setCurrentView("output");
    prevIsRunning.current = cell.isRunning;
  }, [cell.isRunning]);

  const prevResult = useRef(cell.result);
  useEffect(() => {
    if (!prevResult.current && cell.result) setCurrentView("output");
    prevResult.current = cell.result;
  }, [cell.result]);

  return { currentView, setCurrentView };
}
