import type { ConceptData } from "@/features/concepts/api";
import type { AppPageDef } from "../../../schema/appDefinition.types";

/**
 * Column names a tap-bound widget can reference: the widget's output tap
 * resolves to a concept, whose fields are the available columns. Empty when
 * the tap or concept is unknown — the pickers then fall back to free text.
 */
export function resolveTapColumns(
  page: AppPageDef,
  outputId: string | undefined,
  concepts: ConceptData[],
): string[] {
  if (!outputId) return [];
  const tap = page.runGroups
    .flatMap((group) => group.outputs ?? [])
    .find((candidate) => candidate.id === outputId);
  if (!tap) return [];
  const concept = concepts.find((candidate) => candidate.predicate_name === tap.concept);
  if (!concept) return [];
  if (concept.fields) return Object.keys(concept.fields);
  return concept.column_names ?? [];
}
