import { useCallback } from "react";
import { toast } from "sonner";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { getAuthToken } from "@/shared/auth/authToken";

import { deleteTurn as deleteTurnRequest } from "../chatHistoryApi";
import { useCodeAssistantStore } from "../store";
import { resolveUserTurnIndex } from "../turnIndex.utils";

interface UseDeleteTurnReturn {
  /** Discard the exchange the given user message belongs to. */
  deleteTurn: (messageId: string) => Promise<void>;
}

/**
 * Removes one exchange — a user message and the assistant's reply to it —
 * without touching the rest of the conversation.
 *
 * The stored transcript is what the agent reads back, so the local message list
 * is only updated once the delete is confirmed. Doing it optimistically would
 * leave the chat showing something different from what the model sees on the
 * next turn, which is the kind of divergence nobody notices until the answers
 * stop making sense.
 */
export function useDeleteTurn(): UseDeleteTurnReturn {
  const { session } = useAuth();
  const sessionId = useCodeAssistantStore((s) => s.sessionId);
  const removeTurn = useCodeAssistantStore((s) => s.removeTurn);
  const bumpHistoryRevision = useCodeAssistantStore((s) => s.bumpHistoryRevision);

  const deleteTurn = useCallback(
    async (messageId: string) => {
      const messages = useCodeAssistantStore.getState().messages;
      const index = messages.findIndex((m) => m.id === messageId);
      if (index < 0) return;

      const turnIndex = resolveUserTurnIndex(messages, index);
      try {
        await deleteTurnRequest(sessionId, turnIndex, getAuthToken(), session?.access_token);
      } catch {
        toast.error("Could not delete the message");
        return;
      }
      removeTurn(messageId);
      bumpHistoryRevision();
    },
    [sessionId, session, removeTurn, bumpHistoryRevision],
  );

  return { deleteTurn };
}
