// Engine-busy handling for concept runs.
//
// The Vadalog engine executes one run at a time GLOBALLY (not per user/tab), so
// a run that collides with another in-flight run comes back as ENGINE_BUSY.
// Rather than fail with a red error, callers wrap their run in
// `runWithEngineWait`, which surfaces a "waiting" state and retries until the
// engine frees up — then the pending run proceeds automatically.

export class EngineBusyError extends Error {
  constructor(message = "The engine is currently busy.") {
    super(message);
    this.name = "EngineBusyError";
  }
}

// Thrown by runWithEngineWait when the caller aborts while waiting for the
// engine. Callers treat this like a user-initiated stop, not a failure.
export class EngineWaitCancelledError extends Error {
  constructor(message = "Stopped waiting for the engine.") {
    super(message);
    this.name = "EngineWaitCancelledError";
  }
}

// Recognises the backend's engine-busy signal in a WebSocket `error`-event
// payload or a REST body. Deliberately narrow: it must NOT match freemium /
// run-limit codes, which have their own typed handling and their own UX.
export function isEngineBusyPayload(data: unknown): boolean {
  if (typeof data !== "object" || data === null) return false;
  const d = data as Record<string, unknown>;
  if (d.status === "busy") return true;
  if (d.errorCode === "ENGINE_BUSY") return true;
  const nested = d.data as Record<string, unknown> | null | undefined;
  return !!nested && nested.errorCode === "ENGINE_BUSY";
}

export const ENGINE_BUSY_RETRY_MS = 2000;

export interface EngineWaitOptions {
  /** Abort to stop waiting; runWithEngineWait then throws EngineWaitCancelledError. */
  signal?: AbortSignal;
  /** Fires each time a run comes back busy (attempt starts at 1). */
  onWaiting?: (attempt: number) => void;
  /** Fires once when a run finally proceeds after having waited at least once. */
  onResume?: () => void;
  /** Delay between retries; defaults to ENGINE_BUSY_RETRY_MS. */
  retryMs?: number;
}

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(new EngineWaitCancelledError());
      return;
    }
    const onAbort = () => {
      clearTimeout(timer);
      reject(new EngineWaitCancelledError());
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

/**
 * Runs `run`; if it rejects with EngineBusyError, waits `retryMs` and retries —
 * indefinitely — until it resolves, rejects with a non-busy error, or the
 * signal aborts. Non-busy errors propagate unchanged (so freemium limits, parse
 * errors, etc. keep their existing handling). Aborting throws
 * EngineWaitCancelledError.
 */
export async function runWithEngineWait<T>(
  run: () => Promise<T>,
  { signal, onWaiting, onResume, retryMs = ENGINE_BUSY_RETRY_MS }: EngineWaitOptions = {},
): Promise<T> {
  let waited = false;
  for (let attempt = 1; ; attempt++) {
    if (signal?.aborted) throw new EngineWaitCancelledError();
    try {
      const result = await run();
      if (waited) onResume?.();
      return result;
    } catch (err) {
      if (!(err instanceof EngineBusyError)) throw err;
      waited = true;
      onWaiting?.(attempt);
      // Throws EngineWaitCancelledError if aborted during the wait.
      await sleep(retryMs, signal);
    }
  }
}
