import React, { useCallback, useEffect, useRef, useState } from "react";
import ReactMarkdown from "react-markdown";
import rehypeHighlight from "rehype-highlight";
import remarkGfm from "remark-gfm";
import "highlight.js/styles/tokyo-night-dark.css";
import { ArrowUp, Check, Copy, History, Paperclip, Plus, Square } from "lucide-react";
import type { Components } from "react-markdown";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { AgentMessageLimitDialog } from "@/features/billing/components/AgentMessageLimitDialog";
import { useAgentMessageUsage } from "@/features/billing/hooks/useAgentMessageUsage";
import { AuthorizationPrompt } from "@/features/code-assistant/components/AuthorizationPrompt";
import { ChatAttachmentChips } from "@/features/code-assistant/components/ChatAttachmentChips";
import { ChatDropOverlay } from "@/features/code-assistant/components/ChatDropOverlay";
import ChatHistorySidebar from "@/features/code-assistant/components/ChatHistorySidebar";
import { ChatModelSelect } from "@/features/code-assistant/components/ChatModelSelect";
import { ChatModeSelect } from "@/features/code-assistant/components/ChatModeSelect";
import { ClarificationPrompt } from "@/features/code-assistant/components/ClarificationPrompt";
import { ContextLoadedChip } from "@/features/code-assistant/components/ContextLoadedChip";
import { CredentialRequestCard } from "@/features/code-assistant/components/CredentialRequestCard";
import CsvDatasourceProposalCard from "@/features/code-assistant/components/CsvDatasourceProposalCard";
import { HaltNotice } from "@/features/code-assistant/components/HaltNotice";
import { PlanMessage } from "@/features/code-assistant/components/PlanMessage";
import {
  ConceptProposalCard,
  DashboardProposalCard,
  OntologyProposalCard,
  OntologySchemaProposalCard,
} from "@/features/code-assistant/components/ProposalCards";
import { ThinkingMessage } from "@/features/code-assistant/components/ThinkingMessage";
import { ToolMessage } from "@/features/code-assistant/components/ToolMessage";
import { UserMessageBubble } from "@/features/code-assistant/components/UserMessageBubble";
import { VisionWarning } from "@/features/code-assistant/components/VisionWarning";
import { WriterProposalCard } from "@/features/code-assistant/components/WriterProposalCard";
import { useAgentTurn } from "@/features/code-assistant/hooks/useAgentTurn";
import { useChatAttachments } from "@/features/code-assistant/hooks/useChatAttachments";
import { useDeleteTurn } from "@/features/code-assistant/hooks/useDeleteTurn";
import { useFileDropZone } from "@/features/code-assistant/hooks/useFileDropZone";
import { useVisionSupport } from "@/features/code-assistant/hooks/useVisionSupport";
import { isAppWriteTool } from "@/features/code-assistant/proposal.utils";
import { useCodeAssistantStore } from "@/features/code-assistant/store";
import { Button } from "@/shared/components/ui/button";
import { Card, CardContent } from "@/shared/components/ui/card";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";

// ── Constants ─────────────────────────────────────────────────────────────────

const PLACEHOLDERS = [
  "I have product, order, and customer tables. Model how customers relate to orders and products.",
  "I have CSV files with people, companies, and transactions. Map the relationships between them.",
  "I have patient records and clinical events. Build an ontology to represent the care journey.",
  "I have genes, diseases, and drug tables. Model the biological network connecting them.",
  "I have IoT sensor data across devices and locations. Represent how devices relate to each other.",
];

const SUGGESTED_PROMPTS = [
  {
    label: "New ontology",
    text: "Create a new ontology for fraud detection analysis",
  },
  {
    label: "Knowledge graph",
    text: "Build a biomedical knowledge graph for drug repurposing — model compounds, genes, diseases, and pathways",
  },
  {
    label: "Network analysis",
    text: "I want to analyze transaction data across companies and individuals to identify connected entities",
  },
];

// ── Helpers ───────────────────────────────────────────────────────────────────

const getTimeBasedGreeting = (): string => {
  const h = new Date().getHours();
  if (h < 12) return "Good morning";
  if (h < 17) return "Good afternoon";
  return "Good evening";
};

const capitalize = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

function extractText(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(extractText).join("");
  if (React.isValidElement(node))
    return extractText((node.props as { children?: React.ReactNode }).children);
  return "";
}

// ── Main component ────────────────────────────────────────────────────────────

const HomeChat: React.FC = () => {
  const { user } = useAuth();

  const {
    messages,
    haltNotice,
    isLoading,
    setClarificationState,
    setCredentialRequestState,
    setWriterProposalState,
    clearMessages,
    toggleHistory,
    abortActiveChat,
    openAgentLimitDialog,
  } = useCodeAssistantStore();

  const { usage: agentUsage } = useAgentMessageUsage();
  const agentLimitReached =
    !!agentUsage?.isFreemium && agentUsage.remaining !== null && agentUsage.remaining <= 0;

  const [input, setInput] = useState("");
  const [placeholderIndex, setPlaceholderIndex] = useState(0);
  const [displayedPlaceholder, setDisplayedPlaceholder] = useState("");

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const {
    attachments,
    attach: attachFile,
    remove: removeAttachment,
    clear: clearAttachments,
    readyPaths: attachmentPaths,
    readyAttachments,
    isUploading: attachmentsUploading,
  } = useChatAttachments();

  const chatStarted = messages.length > 0;

  const userName = user
    ? user.first_name
      ? capitalize(user.first_name)
      : capitalize(user.username || "there")
    : "there";

  // Animated placeholder — stop cycling once chat begins
  useEffect(() => {
    if (chatStarted) return;
    const full = PLACEHOLDERS[placeholderIndex];
    let i = 0;
    setDisplayedPlaceholder("");
    const t = setInterval(() => {
      i++;
      setDisplayedPlaceholder(full.slice(0, i));
      if (i >= full.length) {
        clearInterval(t);
        setTimeout(() => setPlaceholderIndex((p) => (p + 1) % PLACEHOLDERS.length), 2500);
      }
    }, 38);
    return () => clearInterval(t);
  }, [placeholderIndex, chatStarted]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, []);

  // ── Send ──────────────────────────────────────────────────────────────────

  const { runTurn, editTurn, resolveAuthorization, resumeAfterCredentials, resumeTurn } =
    useAgentTurn({ ontologyId: "_" });
  const { deleteTurn } = useDeleteTurn();

  // Editing rewrites the conversation from that turn on, which cannot be done
  // sensibly while a reply is still streaming into it.
  const canEditMessages = !isLoading;

  const handleSubmitEdit = useCallback(
    (messageId: string, newText: string) => {
      if (agentLimitReached) {
        openAgentLimitDialog();
        return;
      }
      void editTurn({ messageId, userText: newText });
    },
    [agentLimitReached, openAgentLimitDialog, editTurn],
  );

  const handleDeleteTurn = useCallback(
    (messageId: string) => {
      void deleteTurn(messageId);
    },
    [deleteTurn],
  );

  const handleSend = useCallback(
    async (overrideText?: string) => {
      const text = (overrideText ?? input).trim();
      const pathsToSend = overrideText ? [] : attachmentPaths;
      const attachmentsToShow = overrideText ? [] : readyAttachments;
      const canSend = !isLoading && (text.length > 0 || pathsToSend.length > 0);
      if (!canSend) return;
      if (agentLimitReached) {
        openAgentLimitDialog();
        return;
      }
      if (!overrideText) {
        setInput("");
        clearAttachments();
      }

      await runTurn({
        userText: text,
        attachmentPaths: pathsToSend,
        attachments: attachmentsToShow,
      });
    },
    [
      input,
      attachmentPaths,
      readyAttachments,
      clearAttachments,
      isLoading,
      agentLimitReached,
      openAgentLimitDialog,
      runTurn,
    ],
  );

  // ── Markdown components ───────────────────────────────────────────────────

  const markdownComponents: Components = {
    pre({ children, ...props }) {
      const codeEl = React.Children.toArray(children).find(
        (c): c is React.ReactElement => React.isValidElement(c) && c.type === "code",
      );
      const rawCode = codeEl ? extractText(codeEl).replace(/\n$/, "") : "";
      const [copied, setCopied] = React.useState(false);
      const handleCopy = () => {
        navigator.clipboard.writeText(rawCode).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 2000);
        });
      };
      return (
        <div className="my-3 rounded-xl overflow-hidden border border-white/[0.06] bg-[#1a1b26]">
          <div className="flex items-center justify-between px-4 py-2 bg-white/[0.04] border-b border-white/[0.06]">
            <div className="flex gap-1.5">
              <span className="w-3 h-3 rounded-full bg-[#ff5f57]" />
              <span className="w-3 h-3 rounded-full bg-[#febc2e]" />
              <span className="w-3 h-3 rounded-full bg-[#28c840]" />
            </div>
            {rawCode && (
              <button
                onClick={handleCopy}
                className="flex items-center gap-1.5 text-[11px] text-white/40 hover:text-white/70 transition-colors"
              >
                {copied ? <Check className="h-3 w-3" /> : <Copy className="h-3 w-3" />}
                {copied ? "Copied!" : "Copy"}
              </button>
            )}
          </div>
          <pre
            {...props}
            className="!m-0 !rounded-none !bg-transparent overflow-x-auto px-4 py-3 text-[13px] leading-[1.7] font-mono text-[#a9b1d6]"
          >
            {children}
          </pre>
        </div>
      );
    },
  };

  // ── Shared input box ──────────────────────────────────────────────────────

  const handleFiles = (files: File[]) => {
    for (const file of files) attachFile(file);
  };
  const { isDragging, dropZoneProps, handlePaste } = useFileDropZone(handleFiles, isLoading);
  const { isTextOnly, model: chatModel } = useVisionSupport();
  const hasImageAttached = attachments.some((a) => a.kind === "image" && !a.error);

  const handleAttachClick = () => fileInputRef.current?.click();
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    handleFiles(Array.from(e.target.files ?? []));
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const sendDisabled = attachmentsUploading || (!input.trim() && attachmentPaths.length === 0);

  const showUsageMeter = !!agentUsage?.isFreemium && agentUsage.remaining !== null;
  const usageMeterClass = agentLimitReached
    ? "text-red-500 dark:text-red-400"
    : "text-muted-foreground";

  const inputBox = (
    // Drop target for attachments; the paperclip button is the keyboard path.
    <div
      {...dropZoneProps}
      className="relative bg-card border border-border rounded-2xl p-4 shadow-lg"
    >
      <ChatDropOverlay isVisible={isDragging} />
      {attachments.length > 0 && (
        <div className="pb-2">
          <ChatAttachmentChips attachments={attachments} onRemove={removeAttachment} />
        </div>
      )}
      {hasImageAttached && isTextOnly && (
        <div className="pb-2">
          <VisionWarning isVisible model={chatModel} />
        </div>
      )}
      <textarea
        value={input}
        onChange={(e) => setInput(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" && !e.shiftKey) {
            e.preventDefault();
            handleSend();
          }
        }}
        onPaste={handlePaste}
        placeholder={chatStarted ? "Ask a follow-up…" : displayedPlaceholder}
        disabled={isLoading}
        className="w-full resize-none border-0 focus:ring-0 outline-none bg-transparent text-base leading-relaxed placeholder:text-muted-foreground disabled:opacity-50"
        style={{ minHeight: chatStarted ? "3rem" : "4.5rem", maxHeight: "12rem" }}
        onInput={(e) => {
          const t = e.target as HTMLTextAreaElement;
          t.style.height = "auto";
          t.style.height = `${Math.min(t.scrollHeight, 192)}px`;
        }}
      />
      <input
        ref={fileInputRef}
        type="file"
        multiple
        className="hidden"
        onChange={handleFileChange}
      />
      <div className="flex items-center justify-between gap-2 pt-1">
        {showUsageMeter ? (
          <span className={`text-xs ${usageMeterClass}`}>
            {agentUsage?.remaining} of {agentUsage?.limit} agent messages left this month
          </span>
        ) : (
          <span />
        )}
        <div className="flex items-center gap-2">
          <ChatModeSelect />
          <ChatModelSelect />
          <Button
            type="button"
            variant="ghost"
            onClick={toggleHistory}
            className="h-8 w-8 p-0 text-muted-foreground hover:text-foreground"
            title="Chat history"
          >
            <History className="h-4 w-4" />
          </Button>
          <Button
            type="button"
            variant="ghost"
            onClick={handleAttachClick}
            disabled={isLoading}
            className="h-8 w-8 p-0 text-muted-foreground hover:text-foreground"
            title="Attach a file"
          >
            <Paperclip className="h-4 w-4" />
          </Button>
          {isLoading ? (
            <Button
              onClick={abortActiveChat}
              className="h-8 w-8 p-0 bg-red-600 text-white rounded-lg hover:bg-red-700"
              title="Stop"
            >
              <Square className="h-4 w-4 fill-current" />
            </Button>
          ) : (
            <Button
              onClick={() => handleSend()}
              className="h-8 w-8 p-0 bg-brand text-brand-foreground rounded-md hover:bg-brand/90 disabled:opacity-50"
              disabled={sendDisabled}
              title={attachmentsUploading ? "Waiting for uploads…" : "Send (Enter)"}
            >
              <ArrowUp className="h-4 w-4" />
            </Button>
          )}
        </div>
      </div>
    </div>
  );

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <div className={chatStarted ? "h-full flex flex-row" : "min-h-full flex flex-row"}>
      <div
        className={
          chatStarted ? "flex-1 flex flex-col min-w-0 overflow-hidden" : "flex-1 flex flex-col"
        }
      >
        {!chatStarted ? (
          // ── Welcome / initial state ──────────────────────────────────────
          <div className="flex-1 flex flex-col items-center justify-center px-6 py-16">
            <div className="w-full max-w-2xl">
              {/* Greeting */}
              <div className="text-center mb-8">
                <div className="flex flex-col items-center gap-3 mb-2">
                  <div className="relative" style={{ width: 110, height: 95 }}>
                    <img
                      src="/sun-icon.svg"
                      alt=""
                      aria-hidden="true"
                      style={{
                        width: 48,
                        height: 48,
                        position: "absolute",
                        top: 0,
                        right: 0,
                        zIndex: 0,
                        animation: "spin 12s linear infinite",
                      }}
                    />
                    <img
                      src="/3dcloud-icon.svg"
                      alt=""
                      aria-hidden="true"
                      style={{
                        width: 90,
                        height: 90,
                        position: "absolute",
                        bottom: 0,
                        left: 0,
                        zIndex: 1,
                      }}
                    />
                  </div>
                  <h1 className="greeting-title text-4xl font-bold text-foreground">
                    {getTimeBasedGreeting()}, {userName}
                  </h1>
                </div>
                <p className="text-muted-foreground text-base mt-1">How can I help you today?</p>
              </div>

              {/* Input */}
              {inputBox}

              {/* Suggested prompts */}
              <div className="mt-6">
                <p className="mb-3 px-1 text-xs font-medium uppercase tracking-wide text-muted-foreground">
                  Suggested prompts
                </p>
                <div className="grid grid-cols-3 gap-3">
                  {SUGGESTED_PROMPTS.map((p) => (
                    <Card
                      key={p.label}
                      className="cursor-pointer bg-card/80 backdrop-blur-sm transition-all hover:border-foreground/20 hover:shadow-sm"
                      onClick={() => handleSend(p.text)}
                    >
                      <CardContent className="p-3">
                        <p className="mb-1 text-xs font-semibold text-muted-foreground">
                          {p.label}
                        </p>
                        <p className="text-sm leading-snug text-foreground">{p.text}</p>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            </div>
          </div>
        ) : (
          // ── Conversation state ───────────────────────────────────────────
          <>
            {/* Messages */}
            <div className="flex-1 overflow-y-auto">
              <div className="max-w-2xl mx-auto px-4 py-8 space-y-5">
                {messages.map((msg) => {
                  if (msg.role === "thinking") {
                    return (
                      <ThinkingMessage
                        key={msg.id}
                        content={msg.content}
                        isActive={isLoading && msg.id === messages[messages.length - 1]?.id}
                      />
                    );
                  }

                  if (msg.role === "tool") {
                    return (
                      <ToolMessage
                        key={msg.id}
                        toolName={msg.toolName ?? msg.content}
                        toolDetail={msg.toolDetail}
                        status={msg.toolStatus ?? "running"}
                        progress={msg.toolProgress}
                        toolInput={msg.toolInput}
                        toolResult={msg.toolResult}
                      />
                    );
                  }

                  if (msg.role === "proposal" && msg.proposalData) {
                    const proposal = msg.proposalData;
                    if (proposal.tool === "create_ontology") {
                      return (
                        <OntologyProposalCard
                          key={msg.id}
                          data={proposal}
                          toolStatus={msg.toolStatus}
                          createdOntologyId={msg.createdOntologyId}
                        />
                      );
                    }
                    if (isAppWriteTool(proposal.tool)) {
                      return (
                        <DashboardProposalCard
                          key={msg.id}
                          data={proposal}
                          toolStatus={msg.toolStatus}
                        />
                      );
                    }
                    if (proposal.tool === "save_ontology_schema") {
                      return (
                        <OntologySchemaProposalCard
                          key={msg.id}
                          data={proposal}
                          toolStatus={msg.toolStatus}
                        />
                      );
                    }
                    if (proposal.tool === "create_csv_datasource") {
                      return (
                        <CsvDatasourceProposalCard
                          key={msg.id}
                          data={proposal}
                          toolStatus={msg.toolStatus}
                        />
                      );
                    }
                    return (
                      <ConceptProposalCard
                        key={msg.id}
                        data={proposal}
                        toolStatus={msg.toolStatus}
                      />
                    );
                  }

                  if (msg.role === "context_loaded" && msg.contextLoaded) {
                    return <ContextLoadedChip key={msg.id} data={msg.contextLoaded} />;
                  }

                  if (msg.role === "plan" && msg.planSteps) {
                    return <PlanMessage key={msg.id} steps={msg.planSteps} />;
                  }

                  if (msg.role === "writer_proposal" && msg.writerProposal) {
                    return (
                      <WriterProposalCard
                        key={msg.id}
                        proposal={msg.writerProposal}
                        state={msg.writerProposalState ?? "pending"}
                        onResolve={(next) => setWriterProposalState(msg.id, next)}
                      />
                    );
                  }

                  if (msg.role === "clarification" && msg.clarification) {
                    return (
                      <ClarificationPrompt
                        key={msg.id}
                        data={msg.clarification}
                        state={msg.clarificationState ?? "pending"}
                        onResolve={(next) => setClarificationState(msg.id, next)}
                        onAnswer={(answer) => handleSend(answer)}
                      />
                    );
                  }

                  if (msg.role === "authorization" && msg.authorization) {
                    return (
                      <AuthorizationPrompt
                        key={msg.id}
                        data={msg.authorization}
                        state={msg.authorizationState ?? "pending"}
                        onDecide={(decision) =>
                          resolveAuthorization(msg.id, decision, msg.authorization!)
                        }
                      />
                    );
                  }

                  if (msg.role === "credential_request" && msg.credentialRequest) {
                    return (
                      <CredentialRequestCard
                        key={msg.id}
                        data={msg.credentialRequest}
                        state={msg.credentialRequestState ?? "pending"}
                        onResolve={(next) => setCredentialRequestState(msg.id, next)}
                        onSubmitted={() => resumeAfterCredentials(true)}
                        onDismiss={() => resumeAfterCredentials(false)}
                      />
                    );
                  }

                  return (
                    <div
                      key={msg.id}
                      className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"}`}
                    >
                      {msg.role === "user" ? (
                        <UserMessageBubble
                          content={msg.content}
                          attachments={msg.attachments}
                          createdAt={msg.createdAt}
                          canEdit={canEditMessages}
                          onSubmitEdit={(newText) => handleSubmitEdit(msg.id, newText)}
                          onDelete={() => handleDeleteTurn(msg.id)}
                          bubbleClassName="max-w-[80%] bg-blue-500 text-white rounded-2xl rounded-br-md px-4 py-2.5 text-sm leading-relaxed [overflow-wrap:break-word]"
                        />
                      ) : (
                        <div className="max-w-[85%] text-foreground text-sm leading-relaxed [overflow-wrap:break-word] home-chat-message">
                          <ReactMarkdown
                            remarkPlugins={[remarkGfm]}
                            rehypePlugins={[rehypeHighlight]}
                            components={markdownComponents}
                          >
                            {msg.content || "▍"}
                          </ReactMarkdown>
                        </div>
                      )}
                    </div>
                  );
                })}

                {haltNotice && (
                  <HaltNotice data={haltNotice} disabled={isLoading} onResume={resumeTurn} />
                )}

                {(() => {
                  if (!isLoading) return null;
                  const last = messages[messages.length - 1];
                  if (last?.role === "assistant" || last?.role === "thinking") return null;
                  if (
                    (last?.role === "tool" || last?.role === "proposal") &&
                    last.toolStatus === "running"
                  )
                    return null;
                  const label = !last || last.role === "user" ? "Thinking…" : "Working…";
                  return (
                    <div className="flex items-center gap-2 text-muted-foreground">
                      <PrometheuxSpinner size={16} />
                      <span className="text-sm">{label}</span>
                    </div>
                  );
                })()}

                <div ref={messagesEndRef} />
              </div>
            </div>

            {/* Input — anchored at the bottom */}
            <div className="border-t border-border py-4 px-4 bg-background/90 backdrop-blur-sm">
              <div className="max-w-2xl mx-auto">
                <div className="flex items-center justify-end gap-2 mb-2">
                  <Button
                    onClick={clearMessages}
                    size="sm"
                    className="flex items-center gap-2 bg-[#FFDF4B] text-[#212020] hover:bg-[#FFDF4B]/90 shadow-[2px_2px_0_0_#212020] hover:shadow-[1px_1px_0_0_#212020] hover:translate-x-[1px] hover:translate-y-[1px] transition-all"
                  >
                    <Plus className="h-3.5 w-3.5" />
                    New conversation
                  </Button>
                </div>
                {inputBox}
              </div>
            </div>
          </>
        )}

        <style>{`
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @font-face {
          font-family: 'Roobert';
          src: url('/RoobertTRIALVF.woff2') format('woff2'), url('/RoobertTRIALVF.woff') format('woff');
          font-weight: 100 900;
        }
        .greeting-title { font-family: 'Roobert', sans-serif; }
        .home-chat-message { font-size: 14px; line-height: 1.65; color: hsl(var(--foreground)); overflow-wrap: break-word; }
        .home-chat-message p { margin: 0.5em 0; }
        .home-chat-message p:first-child { margin-top: 0; }
        .home-chat-message p:last-child { margin-bottom: 0; }
        .home-chat-message h1, .home-chat-message h2, .home-chat-message h3, .home-chat-message h4 { font-weight: 600; margin: 1em 0 0.375em; line-height: 1.3; }
        .home-chat-message h1 { font-size: 1.15em; }
        .home-chat-message h2 { font-size: 1.05em; }
        .home-chat-message h3 { font-size: 1em; }
        .home-chat-message h4 { font-size: 0.95em; }
        .home-chat-message ul, .home-chat-message ol { padding-left: 1.25rem; margin: 0.5em 0; }
        .home-chat-message li { margin-bottom: 0.2em; }
        .home-chat-message strong { font-weight: 600; }
        .home-chat-message em { font-style: italic; }
        .home-chat-message :not(pre) > code { font-family: ui-monospace, "Fira Code", Menlo, monospace; font-size: 0.8125em; background: hsl(var(--muted)); color: hsl(var(--foreground)); padding: 0.15em 0.35em; border-radius: 0.3em; }
        .home-chat-message pre { margin: 0.75em 0; }
        .home-chat-message blockquote { border-left: 3px solid hsl(var(--border)); padding-left: 0.75em; color: hsl(var(--muted-foreground)); margin: 0.5em 0; }
        .home-chat-message hr { border: none; border-top: 1px solid hsl(var(--border)); margin: 0.875em 0; }
        .home-chat-message table { width: 100%; border-collapse: collapse; font-size: 0.875em; margin: 0.75em 0; }
        .home-chat-message th, .home-chat-message td { padding: 0.3em 0.5em; border: 1px solid hsl(var(--border)); text-align: left; }
        .home-chat-message th { font-weight: 600; background: hsl(var(--muted)); }
        .home-chat-message a { color: #1828FF; text-decoration: underline; }
      `}</style>
      </div>
      {/* end main column */}

      {/* History sidebar — right side */}
      <ChatHistorySidebar />

      <AgentMessageLimitDialog />
    </div>
  );
};

export default HomeChat;
