import { createLocalCache } from "@/shared/utils/createLocalCache";
import type { GettingStartedState, StepId } from "./gettingStarted.types";

const STORAGE_KEY = "getting-started";
const ONE_YEAR_MS = 365 * 24 * 60 * 60 * 1000;
const SCHEMA_VERSION = 1;

const EMPTY_STATE: GettingStartedState = { dismissed: false, manualDone: [] };

const cache = createLocalCache<GettingStartedState>(STORAGE_KEY, ONE_YEAR_MS, SCHEMA_VERSION);

export const gettingStartedStorage = {
  read(userId: string): GettingStartedState {
    return cache.get(userId) ?? EMPTY_STATE;
  },
  dismiss(userId: string): void {
    const current = this.read(userId);
    cache.set(userId, { ...current, dismissed: true });
  },
  markDone(userId: string, stepId: StepId): void {
    const current = this.read(userId);
    if (current.manualDone.includes(stepId)) return;
    cache.set(userId, { ...current, manualDone: [...current.manualDone, stepId] });
  },
  markAutoOpened(userId: string): void {
    const current = this.read(userId);
    if (current.autoOpened) return;
    cache.set(userId, { ...current, autoOpened: true });
  },
  clear(): void {
    cache.clear();
  },
};
