import { useQuery } from "@tanstack/react-query";
import { useMemo } from "react";
import { type ConceptData, ConceptService } from "@/features/concepts/api";

interface UseOntologyConceptsReturn {
  concepts: ConceptData[];
  conceptNames: string[];
  isLoading: boolean;
  isRefetching: boolean;
  refetch: () => void;
}

/**
 * Concepts of an explicit project. Unlike `useConcepts`, which reads the
 * global current project, run groups belong to their page's own project
 * (`page.project.id`) — the editor may be authoring against a project that is
 * not the globally selected one.
 */
export function useOntologyConcepts(ontologyId: string | undefined): UseOntologyConceptsReturn {
  const { data, isLoading, isRefetching, refetch } = useQuery<ConceptData[], Error>({
    queryKey: ["concepts", ontologyId, "user"],
    queryFn: () => ConceptService.listConcepts(ontologyId ?? "", "user"),
    enabled: !!ontologyId,
    staleTime: 60000,
    retry: 2,
  });

  const concepts = useMemo(() => data ?? [], [data]);
  const conceptNames = useMemo(
    () => concepts.map((concept) => concept.predicate_name).sort(),
    [concepts],
  );

  return { concepts, conceptNames, isLoading, isRefetching, refetch };
}
