import { Link2, Trash2 } from "lucide-react";

import { useOntologies } from "@/features/ontologies/hooks/useOntologies";
import { InfoHint } from "@/shared/components/InfoHint";
import { Button } from "@/shared/components/ui/button";
import { Label } from "@/shared/components/ui/label";
import { useContextEdges, useDeleteContextEdge } from "../../hooks/useContextEdges";
import type { ContextEdge, ContextNote } from "../../types";
import { CONTEXT_EDGE_RELATION_LABELS, PROVENANCE_RELATION, parseConceptNodeId } from "../../types";
import { useOpenGraphNode } from "../hooks/useOpenGraphNode";
import { linkDisplayTitle } from "../notesModel";

interface NoteLinksSectionProps {
  note: ContextNote;
  linkCandidates: ContextNote[];
  onOpenNote: (noteId: string) => void;
}

type LinkTargetRef =
  | { kind: "note"; noteId: string }
  | { kind: "concept"; nodeId: string }
  | { kind: "ontology"; ontologyId: string }
  | { kind: "none" };

interface LinkRow {
  edge: ContextEdge;
  label: string;
  /** "concept" / "ontology" chip; notes render without a badge. */
  badge: string | null;
  /** Relation label, prefixed with ← for incoming links (backlinks). */
  relationLabel: string;
  /** derived_from — this note feeds a context concept's output (provenance),
   *  as opposed to a plain "about" annotation. */
  isProvenance: boolean;
  /** System-managed provenance pins are rewritten by the concept's runs, so
   *  hand-deleting them is futile — the delete affordance hides. */
  isSystemManaged: boolean;
  target: LinkTargetRef;
}

function buildLinkRows(
  note: ContextNote,
  edges: ContextEdge[],
  candidates: ContextNote[],
  ontologyNames: Map<string, string>,
): LinkRow[] {
  // Document chunks are labeled by filename — links point at documents.
  const titleById = new Map(candidates.map((c) => [c.id, linkDisplayTitle(c)]));

  const describe = (nodeType: string, nodeId: string): { label: string; target: LinkTargetRef } => {
    if (nodeType === "note") {
      return {
        label: titleById.get(nodeId) ?? "(note in another ontology)",
        target: titleById.has(nodeId) ? { kind: "note", noteId: nodeId } : { kind: "none" },
      };
    }
    if (nodeType === "concept") {
      const ref = parseConceptNodeId(nodeId);
      if (!ref) return { label: nodeId, target: { kind: "none" } };
      const project = ontologyNames.get(ref.ontologyId);
      return {
        label: project ? `${ref.conceptName} · ${project}` : ref.conceptName,
        target: { kind: "concept", nodeId },
      };
    }
    if (nodeType === "ontology") {
      return {
        label: ontologyNames.get(nodeId) ?? "(project)",
        target: { kind: "ontology", ontologyId: nodeId },
      };
    }
    return { label: `${nodeType}: ${nodeId}`, target: { kind: "none" } };
  };

  return edges.map((edge) => {
    const isOutgoing = edge.src_type === "note" && edge.src_id === note.id;
    const otherType = isOutgoing ? edge.dst_type : edge.src_type;
    const otherId = isOutgoing ? edge.dst_id : edge.src_id;
    const relationName = CONTEXT_EDGE_RELATION_LABELS[edge.relation];
    const { label, target } = describe(otherType, otherId);
    const isProvenance = edge.relation === PROVENANCE_RELATION;
    return {
      edge,
      label,
      badge: otherType === "note" ? null : otherType,
      relationLabel: isOutgoing ? relationName : `← ${relationName}`,
      isProvenance,
      isSystemManaged: isProvenance && edge.created_by === "system",
      target,
    };
  });
}

/** Outgoing links + backlinks of a note — notes, concepts, and projects in
 *  one list (decision 7), with per-edge removal and click-through. */
export function NoteLinksSection({ note, linkCandidates, onOpenNote }: NoteLinksSectionProps) {
  const { data: edges = [] } = useContextEdges("note", note.id);
  const deleteEdgeMutation = useDeleteContextEdge();
  const { projects } = useOntologies();
  const { openConcept, openOntology } = useOpenGraphNode();

  const ontologyNames = new Map((projects ?? []).map((p) => [p.id, p.name]));
  const linkRows = buildLinkRows(note, edges, linkCandidates, ontologyNames);

  const handleOpenLink = (row: LinkRow) => {
    if (row.target.kind === "note") onOpenNote(row.target.noteId);
    if (row.target.kind === "concept") openConcept(row.target.nodeId);
    if (row.target.kind === "ontology") openOntology(row.target.ontologyId);
  };

  return (
    <section className="space-y-1.5">
      <div className="flex items-center gap-1.5">
        <Label>Links</Label>
        <InfoHint label="How links are used">
          <p>
            Links connect notes, documents, and rules into a knowledge graph. When one note is
            relevant, the assistant can follow its links to pull in the connected context too — so
            linking a note to what it depends on helps the assistant load the right background.
          </p>
          <p>
            Type <code className="rounded bg-muted px-1">[[</code> in the editor to create a link,
            or <code className="rounded bg-muted px-1">[[concept:</code> to attach the note to a
            concept. Links born from text disappear when you delete the{" "}
            <code className="rounded bg-muted px-1">[[…]]</code> text; the ← arrow marks incoming
            links. Clicking a concept or project opens it in its project.
          </p>
          <p>
            Amber “Derived from” links are provenance — the note feeds a context concept’s output,
            not just an annotation. Pins managed by the concept’s runs can’t be removed by hand.
          </p>
        </InfoHint>
      </div>
      {linkRows.length === 0 && (
        <p className="text-xs text-muted-foreground">
          No links yet. Type <code className="rounded bg-muted px-1">[[</code> in the editor to link
          this note to another.
        </p>
      )}
      <ul className="space-y-1">
        {linkRows.map((row) => (
          <li key={row.edge.id} className="flex items-center gap-1.5">
            <Link2 className="h-4 w-4 shrink-0 text-muted-foreground" />
            <button
              type="button"
              onClick={() => handleOpenLink(row)}
              disabled={row.target.kind === "none"}
              className="min-w-0 flex-1 truncate text-left text-sm text-primary hover:underline disabled:cursor-default disabled:text-muted-foreground disabled:no-underline"
            >
              {row.label}
            </button>
            {row.badge && (
              <span className="shrink-0 rounded bg-violet-100 px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide text-violet-700 dark:bg-violet-900/30 dark:text-violet-300">
                {row.badge}
              </span>
            )}
            {row.isProvenance ? (
              <span
                className="shrink-0 rounded bg-amber-100 px-1.5 py-0.5 text-[10px] font-medium text-amber-700 dark:bg-amber-900/30 dark:text-amber-300"
                title="Provenance: this note feeds a context concept's output (not just an annotation)"
              >
                {row.relationLabel}
              </span>
            ) : (
              <span className="shrink-0 text-xs text-muted-foreground">{row.relationLabel}</span>
            )}
            {!row.isSystemManaged && (
              <Button
                type="button"
                variant="ghost"
                size="icon"
                onClick={() => deleteEdgeMutation.mutate(row.edge.id)}
                className="h-6 w-6 shrink-0 text-muted-foreground hover:text-destructive"
                aria-label="Remove link"
              >
                <Trash2 className="h-3.5 w-3.5" />
              </Button>
            )}
          </li>
        ))}
      </ul>
    </section>
  );
}
