// Pure helpers for deriving a concept name from a data source and reading the
// canonical concept name back from a save response. Shared by the data-source
// "create concept" flows (ConceptLibrarySidebar, RunDataSourceModal).

const FILE_EXTENSIONS = new Set([
  "csv",
  "parquet",
  "json",
  "xlsx",
  "xls",
  "tsv",
  "txt",
  "orc",
  "avro",
  "ttl",
  "rdf",
  "owl",
  "yaml",
  "yml",
  "cobol",
  "cob",
  "cbl",
]);

/**
 * Read the canonical concept name from a save response. The backend lowercases
 * predicate names on save, so callers must prefer the returned `data.id` over
 * the client-side generated name (lineage/cell matching is case-sensitive).
 */
export function extractSavedConceptName(saveResponse: unknown, fallback: string): string {
  const normalizedFallback = fallback.trim().toLowerCase();
  if (typeof saveResponse !== "object" || saveResponse === null) return normalizedFallback;
  const data = (saveResponse as { data?: unknown }).data;
  if (typeof data !== "object" || data === null) return normalizedFallback;
  const id = (data as { id?: unknown }).id;
  return typeof id === "string" && id.length > 0 ? id : normalizedFallback;
}

/** Derive a safe concept predicate name from a (possibly file-based) table name. */
export function getConceptNameFromTableName(tableName: string): string {
  const parts = tableName.split(".");
  const last = parts[parts.length - 1];
  if (FILE_EXTENSIONS.has(last.toLowerCase()) && parts.length >= 2) {
    return parts[parts.length - 2].replace(/[^a-zA-Z0-9_]/g, "_");
  }
  return last.replace(/[^a-zA-Z0-9_]/g, "_");
}
