import { useQueries } from "@tanstack/react-query";
import {
  DASHBOARD_CONFIG_MAP,
  type DashboardAppConfig,
} from "@/features/dashboards/dashboardConfigRegistry";
import type { DashboardEntry } from "@/features/dashboards/dashboardRegistry";
import { loadRemoteExport } from "./remoteLoader";

interface AppMeta {
  name: string;
  description: string;
}

interface RemoteConfigModule {
  default: DashboardAppConfig;
}

type RemoteEntry = DashboardEntry & { remoteUrl: string };

// Resolves the display name + description for each visible app:
//   • bundled app   → its build-time DASHBOARD_CONFIG_MAP entry
//   • federated app → its exposed `./config`, lazily loaded here
//
// The permission carries no name/description for federated apps, so the list and sidebar
// would otherwise fall back to the raw id. We load the remote `./config` with the SAME query
// key RemoteAppHost uses (`["remote-app-config", id, url]`), so it's fetched once and reused
// when the app is opened. A handful of apps per user makes this negligible.
export function useResolvedAppMeta(apps: DashboardEntry[]): Record<string, AppMeta> {
  const remoteApps = apps.filter((a): a is RemoteEntry => Boolean(a.remoteUrl));

  const remoteConfigs = useQueries({
    queries: remoteApps.map((app) => ({
      queryKey: ["remote-app-config", app.id, app.remoteUrl],
      queryFn: async () => {
        const mod = await loadRemoteExport<RemoteConfigModule>(app.id, app.remoteUrl, "config");
        return mod.default;
      },
      staleTime: Number.POSITIVE_INFINITY,
      retry: 1,
    })),
  });

  const remoteConfigById = new Map(remoteApps.map((app, i) => [app.id, remoteConfigs[i]?.data]));

  return apps.reduce<Record<string, AppMeta>>((acc, app) => {
    const bundled = DASHBOARD_CONFIG_MAP[app.id];
    if (bundled) {
      acc[app.id] = { name: bundled.name, description: bundled.description };
      return acc;
    }
    const remote = remoteConfigById.get(app.id);
    acc[app.id] = { name: remote?.name ?? app.name, description: remote?.description ?? "" };
    return acc;
  }, {});
}
