import { useState } from "react";
import { toast } from "sonner";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import type { LlmConnectionSettings } from "../../api/configService";
import { storedSecretsOf, withoutSecrets } from "../../utils/llmConnection.utils";
import { LlmConnectionFields } from "./LlmConnectionFields";

interface ConnectionDraft {
  name: string;
  settings: LlmConnectionSettings;
}

interface LlmConnectionFormProps {
  /** Existing connection being edited, or null when creating a new one. */
  initial: ConnectionDraft | null;
  isSaving: boolean;
  onSubmit: (name: string, settings: LlmConnectionSettings) => Promise<boolean>;
  onCancel: () => void;
}

/**
 * Create/edit form for one named LLM connection: a name, plus the provider
 * fields shared with the llm cell.
 */
export function LlmConnectionForm({
  initial,
  isSaving,
  onSubmit,
  onCancel,
}: LlmConnectionFormProps) {
  // Credentials start blank even when stored: the save path treats an omitted
  // one as unchanged, so editing the model does not require handling the key.
  const [draft, setDraft] = useState<ConnectionDraft>(
    initial
      ? { name: initial.name, settings: withoutSecrets(initial.settings) }
      : { name: "", settings: { llm_provider: "openai" } },
  );

  const storedSecrets = storedSecretsOf(initial?.settings);

  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setDraft((prev) => ({ ...prev, name: e.target.value }));
  };

  const handleSettingsChange = (settings: LlmConnectionSettings) => {
    setDraft((prev) => ({ ...prev, settings }));
  };

  const handleSubmit = async () => {
    const name = draft.name.trim();
    if (!name) {
      toast.error("Give the connection a name");
      return;
    }
    const saved = await onSubmit(name, draft.settings);
    if (saved) onCancel();
  };

  return (
    <div className="flex flex-col gap-3 rounded-md border border-border p-3">
      <div className="grid grid-cols-2 gap-3">
        <div className="flex flex-col gap-1">
          <label htmlFor="llm-conn-name" className="text-xs text-muted-foreground">
            Name
          </label>
          <Input
            id="llm-conn-name"
            value={draft.name}
            onChange={handleNameChange}
            placeholder="e.g. team_openai"
            disabled={Boolean(initial)}
            className="h-8 text-sm"
          />
        </div>
      </div>
      <LlmConnectionFields
        settings={draft.settings}
        storedSecrets={storedSecrets}
        connectionName={initial?.name}
        onChange={handleSettingsChange}
      />
      <div className="flex items-center gap-2">
        <Button type="button" size="sm" onClick={handleSubmit} disabled={isSaving}>
          {initial ? "Save changes" : "Add connection"}
        </Button>
        <Button type="button" size="sm" variant="ghost" onClick={onCancel} disabled={isSaving}>
          Cancel
        </Button>
      </div>
    </div>
  );
}
