/**
 * No-op PostHog service stub for builds that ship without telemetry
 * (e.g. the Databricks 3P Marketplace bundle).
 *
 * This file is selected by Vite at build time via `resolve.alias` when
 * VITE_PUBLIC_POSTHOG_KEY is NOT set. It exposes the same public API as
 * the real `posthogService.ts` so call sites do not change, but every
 * method is an inert no-op and nothing is imported from `posthog-js`.
 *
 * Effect on the bundle:
 *   - `posthog-js/react` and `posthog-js` are never reached statically,
 *     so Vite/Rollup tree-shake the entire SDK out.
 *   - `webVitalsService.ts` is only loaded via `await import()` inside the
 *     real `PostHogService.setupUser()`. With the stub, `setupUser()` is a
 *     no-op and never reaches that dynamic import, so `webVitalsService`
 *     and its `posthog-js` re-export are also tree-shaken.
 *
 * The net result is zero telemetry code in the shipped 3P bundle.
 */

import { useCallback } from "react";

export interface PostHogUser {
  username: string;
  organization: string;
  id: string;
  email?: string;
}

// biome-ignore lint/complexity/noStaticOnlyClass: must mirror the real class shape
export class PostHogService {
  // Kept for API compatibility — never read by call sites.
  private static posthog: unknown = null;
  private static lastSetupUsername: string | null = null;

  static setPostHogInstance(_posthogInstance: unknown): void {
    // no-op
  }

  static identifyUser(_user: PostHogUser): void {
    // no-op
  }

  static groupUser(_user: PostHogUser): void {
    // no-op
  }

  static async setupUser(_user: PostHogUser): Promise<void> {
    // no-op — intentionally does not await the dynamic webVitalsService import
    // so that file (and its posthog-js dependency) is dropped from the bundle.
  }

  static debugPostHogState(): void {
    // no-op
  }

  static captureEvent(_eventName: string, _properties: Record<string, unknown> = {}): void {
    // no-op
  }

  static startSessionRecording(): void {
    // no-op
  }

  static stopSessionRecording(): void {
    // no-op
  }

  static getSessionRecordingStatus(): { isRecording: boolean; sessionId: string } | null {
    return null;
  }

  static setSessionProperties(_properties: Record<string, unknown>): void {
    // no-op
  }

  static reset(): void {
    PostHogService.lastSetupUsername = null;
  }
}

/**
 * Hook returning the same shape as the real `usePostHogService`, but every
 * returned function is an inert no-op. Stable references via useCallback so
 * downstream effects do not re-fire.
 */
export const usePostHogService = () => {
  const identifyUser = useCallback((user: PostHogUser) => PostHogService.identifyUser(user), []);
  const groupUser = useCallback((user: PostHogUser) => PostHogService.groupUser(user), []);
  const setupUser = useCallback((user: PostHogUser) => PostHogService.setupUser(user), []);
  const reset = useCallback(() => PostHogService.reset(), []);
  const debugState = useCallback(() => PostHogService.debugPostHogState(), []);
  const startRecording = useCallback(() => PostHogService.startSessionRecording(), []);
  const stopRecording = useCallback(() => PostHogService.stopSessionRecording(), []);
  const getRecordingStatus = useCallback(() => PostHogService.getSessionRecordingStatus(), []);
  const setSessionProperties = useCallback(
    (properties: Record<string, unknown>) => PostHogService.setSessionProperties(properties),
    [],
  );

  return {
    identifyUser,
    groupUser,
    setupUser,
    reset,
    debugState,
    startRecording,
    stopRecording,
    getRecordingStatus,
    setSessionProperties,
  };
};
