import { AlertTriangle, RefreshCw } from "lucide-react";
import { Component, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  /** Compact inline variant — used inside widget cells */
  inline?: boolean;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error("[ErrorBoundary]", error.message, info.componentStack);
  }

  private reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, inline } = this.props;

    if (!error) return children;

    if (inline) {
      return (
        <div className="flex items-center gap-2 p-3 rounded-lg border border-destructive/30 bg-destructive/5 text-xs text-destructive">
          <AlertTriangle className="h-3.5 w-3.5 flex-shrink-0" />
          <span className="flex-1 font-mono truncate">{error.message || "Widget crashed"}</span>
          <button
            onClick={this.reset}
            className="flex-shrink-0 hover:text-destructive/70 transition-colors"
            title="Retry"
          >
            <RefreshCw className="h-3 w-3" />
          </button>
        </div>
      );
    }

    return (
      <div className="flex flex-col items-center justify-center h-full gap-4 p-10 text-muted-foreground">
        <AlertTriangle className="h-10 w-10 text-destructive/40" />
        <div className="text-center max-w-sm">
          <p className="text-sm font-semibold text-foreground">Something went wrong</p>
          <p className="mt-1 text-xs font-mono text-muted-foreground break-words">
            {error.message}
          </p>
        </div>
        <button
          onClick={this.reset}
          className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
        >
          <RefreshCw className="h-3.5 w-3.5" />
          Try again
        </button>
      </div>
    );
  }
}
