import { createContext, useContext } from "react";
import { cn } from "@/shared/lib/utils";

/**
 * Editor-only selection plumbing for the v2 renderer. The viewer never mounts
 * the provider, so `useEditorSelection()` returns null there and the renderer
 * behaves exactly as before. Inside the editor, each widget cell renders an
 * EditorSelectOverlay that captures clicks (select mode) and draws the
 * selection ring — "the live preview IS the canvas" (ADR D7).
 */
export interface EditorSelectionValue {
  selectedWidgetId: string | null;
  /** false = clicks select widgets; true = the preview behaves like the live app. */
  interactMode: boolean;
  onSelectWidget: (sectionId: string, widgetId: string) => void;
}

const EditorSelectionContext = createContext<EditorSelectionValue | null>(null);

export const EditorSelectionProvider = EditorSelectionContext.Provider;

export function useEditorSelection(): EditorSelectionValue | null {
  return useContext(EditorSelectionContext);
}

interface EditorSelectOverlayProps {
  sectionId: string;
  widgetId: string;
}

/**
 * Rendered inside each (relative) widget cell. In select mode a transparent
 * button covers the widget and captures the click; the selected widget keeps
 * a visible ring in both modes so selection survives toggling to interact.
 */
export function EditorSelectOverlay({ sectionId, widgetId }: EditorSelectOverlayProps) {
  const editor = useEditorSelection();
  if (!editor) return null;

  const isSelected = editor.selectedWidgetId === widgetId;
  return (
    <>
      {isSelected && (
        <div className="pointer-events-none absolute -inset-px z-20 rounded-lg ring-2 ring-primary" />
      )}
      {!editor.interactMode && (
        <button
          type="button"
          aria-label="Select widget"
          onClick={() => editor.onSelectWidget(sectionId, widgetId)}
          className={cn(
            "absolute inset-0 z-10 rounded-lg",
            !isSelected && "hover:ring-1 hover:ring-primary/50",
          )}
        />
      )}
    </>
  );
}
