import { Globe } from "lucide-react";
import type React from "react";
import { Badge } from "@/shared/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/shared/components/ui/table";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/components/ui/tooltip";
import type { LoginSession } from "./loginActivity.types";
import {
  formatHitCount,
  formatLocation,
  formatRelativeTime,
  formatTokenLabel,
} from "./loginActivity.utils";

// Build-time flag (folded by Vite's `define` + esbuild constant propagation).
// We use this — not PROMETHEUX_CONFIG.DATABRICKS_3P_MODE — because the goal is
// to dead-code-eliminate the `FLAG_CDN` string literal from the 3P bundle.
// PROMETHEUX_CONFIG is a runtime object lookup that the bundler cannot prove
// constant, so a JSX branch gated on it would still ship the URL string.
const IS_DATABRICKS_3P_BUILD: boolean = import.meta.env.VITE_DATABRICKS_3P_MODE === "true";

interface LoginActivityListProps {
  sessions: LoginSession[];
}

interface SessionRowData {
  ip: string;
  location: string;
  countryCode: string | null;
  firstSeen: string;
  lastSeen: string;
  hitCount: string;
  rawHitCount: number;
  accessVia: string;
  isApiKey: boolean;
}

interface CountryFlagProps {
  code: string | null;
}

/**
 * Convert an ISO 3166-1 alpha-2 country code to its Unicode flag emoji by
 * mapping each ASCII letter to the corresponding Regional Indicator Symbol
 * (U+1F1E6..U+1F1FF). This is fully offline — no network, no asset bundle.
 */
const codeToEmojiFlag = (code: string): string => {
  const base = 0x1f1e6;
  const a = "A".charCodeAt(0);
  const upper = code.toUpperCase();
  return String.fromCodePoint(base + (upper.charCodeAt(0) - a), base + (upper.charCodeAt(1) - a));
};

/**
 * SaaS-only flag renderer that fetches a high-fidelity PNG from flagcdn.com.
 * Isolated in its own component so esbuild can drop the entire definition
 * (along with the `FLAG_CDN` URL literal) from the 3P bundle once
 * `IS_DATABRICKS_3P_BUILD` folds to `true` and the reference below becomes
 * unreachable code.
 */
const CountryFlagPng: React.FC<{ code: string }> = ({ code }) => {
  const FLAG_CDN = "https://flagcdn.com";
  const lowerCode = code.toLowerCase();
  return (
    <img
      src={`${FLAG_CDN}/w40/${lowerCode}.png`}
      srcSet={`${FLAG_CDN}/w40/${lowerCode}.png 1x, ${FLAG_CDN}/w80/${lowerCode}.png 2x`}
      alt={`${code} flag`}
      className="h-4 w-6 rounded-sm object-cover"
      loading="lazy"
    />
  );
};

/**
 * The 3P Databricks Marketplace build is not allowed to contact undeclared
 * external hosts (flagcdn.com is a CDN that would need separate egress
 * declaration + security review). In that build the gating constant folds to
 * `true`, esbuild eliminates the `CountryFlagPng` branch and the URL literal
 * never ships. The SaaS build keeps the higher-fidelity CDN PNGs.
 */
const CountryFlag: React.FC<CountryFlagProps> = ({ code }) => {
  if (!code || code.length !== 2) {
    return <Globe className="h-4 w-4 text-muted-foreground" />;
  }

  if (IS_DATABRICKS_3P_BUILD) {
    return (
      <span
        role="img"
        aria-label={`${code} flag`}
        className="inline-block w-6 text-center text-base leading-none"
      >
        {codeToEmojiFlag(code)}
      </span>
    );
  }

  return <CountryFlagPng code={code} />;
};

const EmptyState: React.FC = () => (
  <div className="text-center py-8">
    <Globe className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
    <h3 className="text-lg font-medium mb-2">No login activity</h3>
    <p className="text-muted-foreground mb-4">
      No sessions have been tracked yet. Activity will appear here as you use the platform.
    </p>
  </div>
);

export const LoginActivityList: React.FC<LoginActivityListProps> = ({ sessions }) => {
  if (sessions.length === 0) return <EmptyState />;

  const rows: SessionRowData[] = sessions.map((s) => ({
    ip: s.ip,
    location: formatLocation(s.city, s.country),
    countryCode: s.country_code,
    firstSeen: formatRelativeTime(s.first_seen),
    lastSeen: formatRelativeTime(s.last_seen),
    hitCount: formatHitCount(s.hit_count),
    rawHitCount: s.hit_count,
    accessVia: formatTokenLabel(s.last_token_type, s.last_token_name),
    isApiKey: s.last_token_type === "api_key",
  }));

  return (
    <div className="border border-border rounded-lg">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Location</TableHead>
            <TableHead>IP Address</TableHead>
            <TableHead>Access Via</TableHead>
            <TableHead>First Seen</TableHead>
            <TableHead>Last Seen</TableHead>
            <TableHead className="text-right">Sessions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.ip}>
              <TableCell>
                <div className="flex items-center gap-2">
                  <CountryFlag code={row.countryCode} />
                  <span className="font-medium">{row.location}</span>
                </div>
              </TableCell>
              <TableCell>
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <code className="rounded bg-muted px-1.5 py-0.5 text-xs font-mono text-muted-foreground">
                        {row.ip}
                      </code>
                    </TooltipTrigger>
                    <TooltipContent>
                      <p>IP address</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </TableCell>
              <TableCell>
                <Badge
                  variant="outline"
                  className={
                    row.isApiKey
                      ? "bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-900/40"
                      : "bg-green-50 text-green-700 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-900/40"
                  }
                >
                  {row.accessVia}
                </Badge>
              </TableCell>
              <TableCell className="text-muted-foreground">{row.firstSeen}</TableCell>
              <TableCell className="text-muted-foreground">{row.lastSeen}</TableCell>
              <TableCell className="text-right">
                <Badge variant="secondary" className="font-mono tabular-nums">
                  {row.hitCount}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
};
