import { Loader2 } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { useInterviewTemplate, useSubmitInterview } from "@/features/onboarding/hooks/useInterview";
import type { WizardControls } from "@/shared/components/wizard/useWizardState";
import { WizardStep } from "@/shared/components/wizard/WizardStep";
import { createSessionCache } from "@/shared/utils/createSessionCache";

type Scope = "global" | "ontology";
type AnswersMap = Record<string, string>;

interface InterviewStepProps {
  controls: WizardControls;
  scope?: Scope;
  scopeId?: string | null;
}

const STORAGE_KEYS = {
  ANSWERS: "prometheux-interview-answers",
} as const;

const SAVE_DEBOUNCE_MS = 200;

// Filter cached values down to a clean `Record<string, string>`. Throws
// on a non-object payload so the cache treats it as a miss.
function validateAnswers(parsed: unknown): AnswersMap {
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Invalid answers payload");
  }
  const out: AnswersMap = {};
  for (const [k, v] of Object.entries(parsed as Record<string, unknown>)) {
    if (typeof v === "string") out[k] = v;
  }
  return out;
}

const answersCache = createSessionCache<AnswersMap>(STORAGE_KEYS.ANSWERS, {
  validate: validateAnswers,
});

function nonEmptyAnswerCount(answers: AnswersMap): number {
  return Object.values(answers).filter((v) => v.trim().length > 0).length;
}

function formatSuccessMessage(savedCount: number, reusedCount: number): string {
  const total = savedCount + reusedCount;
  if (total === 0) return "No answers to save — moving on";
  if (reusedCount === 0) {
    return `Saved ${savedCount} note${savedCount === 1 ? "" : "s"} to your context`;
  }
  if (savedCount === 0) {
    return `Already saved ${reusedCount} note${reusedCount === 1 ? "" : "s"} — moving on`;
  }
  return `Saved ${savedCount}, reused ${reusedCount} — added to your context`;
}

export function InterviewStep({ controls, scope = "global", scopeId = null }: InterviewStepProps) {
  const template = useInterviewTemplate(scope);
  const { submit, isPending, errorMessage } = useSubmitInterview();

  const [index, setIndex] = useState(0);
  const [answers, setAnswers] = useState<AnswersMap>(() => answersCache.get() ?? {});

  // Debounced persistence: write to sessionStorage at most every
  // SAVE_DEBOUNCE_MS while the user types, plus a flush on unmount
  // so the latest keystroke isn't lost if they navigate away.
  useEffect(() => {
    const handle = window.setTimeout(() => answersCache.set(answers), SAVE_DEBOUNCE_MS);
    return () => {
      window.clearTimeout(handle);
      // Synchronous flush on unmount: protects the in-flight keystroke
      // window when the user refreshes mid-typing.
      answersCache.set(answers);
    };
  }, [answers]);

  const questions = template.data?.questions ?? [];
  const total = questions.length;
  const current = questions[index];
  const isLastQuestion = total > 0 && index === total - 1;

  const currentAnswer = current ? (answers[current.id] ?? "") : "";
  const savedCount = nonEmptyAnswerCount(answers);

  // ── Handlers ─────────────────────────────────────────────────────────
  // handleFinish declared first because handleNextQuestion and
  // handleSkipQuestion call it; closures captured here are stable.

  const handleFinish = useCallback(async () => {
    if (isPending) return;
    try {
      const result = await submit({ scope, scope_id: scopeId, answers });
      answersCache.clear();
      const message = formatSuccessMessage(result.saved_count, result.reused_count);
      if (result.saved_count + result.reused_count > 0) {
        toast.success(message);
      } else {
        toast.message(message);
      }
      controls.goNext();
    } catch {
      // useSubmitInterview surfaces error via errorMessage; show a
      // toast as a backstop in case the consumer ignores it.
      toast.error(`Could not save interview: ${errorMessage ?? "Unknown error"}`);
    }
  }, [answers, controls, errorMessage, isPending, scope, scopeId, submit]);

  const updateAnswer = useCallback(
    (value: string) => {
      if (!current) return;
      setAnswers((prev) => ({ ...prev, [current.id]: value }));
    },
    [current],
  );

  const handleTextareaChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    updateAnswer(e.target.value);
  };

  const handleNextQuestion = () => {
    if (isLastQuestion) {
      handleFinish();
      return;
    }
    setIndex((i) => i + 1);
  };

  // "Back" walks the questions in reverse; from the first question it
  // steps back to the previous wizard step (Your context). The footer's
  // "Skip this step" handles skipping the whole interview.
  const handlePrev = () => {
    if (index > 0) {
      setIndex((i) => i - 1);
      return;
    }
    controls.goPrev();
  };

  // ── Render ───────────────────────────────────────────────────────────

  if (template.isLoading) {
    return (
      <WizardStep
        controls={controls}
        title="A few quick questions"
        description="Loading…"
        hideDefaultNav
      >
        <div className="flex items-center justify-center py-10 text-muted-foreground">
          <Loader2 className="h-5 w-5 animate-spin" />
        </div>
      </WizardStep>
    );
  }

  if (template.isError || !current) {
    return (
      <WizardStep
        controls={controls}
        title="A few quick questions"
        description="We couldn't load the questions. Skip for now and revisit later."
        primaryAction={{
          label: "Skip",
          onClick: () => controls.goNext(),
        }}
      >
        <div className="text-sm text-muted-foreground">
          {template.error?.message ?? "Interview template unavailable."}
        </div>
      </WizardStep>
    );
  }

  const primaryLabel = (() => {
    if (isPending) return "Saving…";
    if (isLastQuestion) return "Save and continue";
    return "Save and answer next";
  })();

  return (
    <WizardStep
      controls={controls}
      title="A few quick questions"
      description="Five short prompts. Each answer becomes a Context Layer note the assistant will use on every future turn. Skip any that don't apply."
      secondaryAction={{
        label: "Back",
        onClick: handlePrev,
        disabled: isPending,
      }}
      primaryAction={{
        label: primaryLabel,
        onClick: handleNextQuestion,
        disabled: isPending,
      }}
    >
      <div className="space-y-4">
        <div className="flex items-center justify-between text-xs text-muted-foreground">
          <span>
            Question {index + 1} of {total}
          </span>
          <span>{savedCount} answered so far</span>
        </div>

        <div className="space-y-2">
          <h3 className="text-base font-medium text-foreground">{current.prompt}</h3>
          {current.helper && <p className="text-xs text-muted-foreground">{current.helper}</p>}
        </div>

        <textarea
          value={currentAnswer}
          onChange={handleTextareaChange}
          disabled={isPending}
          placeholder={current.placeholder}
          className="min-h-[160px] w-full resize-y rounded-md border border-input bg-background p-3 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-primary disabled:opacity-60"
        />
      </div>
    </WizardStep>
  );
}
