import { Loader2 } from "lucide-react";

import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shared/components/ui/dialog";

import type { MessageAttachment } from "../attachments.types";
import { useAttachmentPreview } from "../hooks/useAttachmentPreview";

interface AttachmentLightboxProps {
  attachment: MessageAttachment | null;
  onClose: () => void;
}

/** Full-size view of an attached image, opened from its chip. */
export function AttachmentLightbox({ attachment, onClose }: AttachmentLightboxProps) {
  if (!attachment) return null;
  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-4xl">
        <DialogHeader>
          <DialogTitle className="truncate text-sm">{attachment.name}</DialogTitle>
        </DialogHeader>
        <LightboxImage attachment={attachment} />
      </DialogContent>
    </Dialog>
  );
}

interface LightboxImageProps {
  attachment: MessageAttachment;
}

function LightboxImage({ attachment }: LightboxImageProps) {
  const { url, isLoading, hasFailed } = useAttachmentPreview(attachment);

  if (hasFailed) {
    return (
      <p className="py-8 text-center text-muted-foreground text-sm">
        This file is no longer available.
      </p>
    );
  }
  if (isLoading || !url) {
    return (
      <div className="flex items-center justify-center gap-2 py-12">
        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
        <span className="text-muted-foreground text-sm">Loading…</span>
      </div>
    );
  }
  return (
    <img
      src={url}
      alt={attachment.name}
      className="max-h-[75vh] w-full rounded-md object-contain"
    />
  );
}
