import { useEffect } from "react";
import { applyTheme, useThemeStore } from "@/shared/store/themeStore";

/**
 * Forces the light theme while the calling component is mounted, restoring the
 * user's persisted theme on unmount.
 *
 * The auth pages (login, password reset) are light-only designs with hardcoded
 * light backgrounds. When a user picks the dark theme inside the app and logs
 * out, the persisted `dark` class stays on `<html>`, turning the semantic
 * `text-foreground` form inputs near-white and unreadable on those light
 * backgrounds. Forcing light while mounted keeps them legible without touching
 * the user's saved preference.
 */
export function useForceLightTheme(): void {
  const theme = useThemeStore((state) => state.theme);

  useEffect(() => {
    applyTheme("light");
    return () => applyTheme(theme);
  }, [theme]);
}
