/**
 * Shape consumed by the Tables picker: every row needs `name`, extra metadata
 * fields are tolerated and passed through. Structurally compatible with the
 * `DatabricksTable` interface declared in `useDatabricksConnection.ts`.
 */
export interface NormalizedDatabricksTable {
  name: string;
  [extra: string]: unknown;
}

/**
 * Coerce whatever the backend returns for `GET /databricks/catalogs/.../tables`
 * into the `{ name: string }[]` shape the picker consumes. Three payloads have
 * been observed in the wild:
 *
 *   1. `["orders", "customers"]`                     — array of plain strings
 *      (jarvispy's current `list_schema_tables` response).
 *   2. `[{ name: "orders" }, { name: "customers" }]` — Unity Catalog native.
 *   3. `[{ table_name: "orders" }, ...]`             — alternative key seen
 *      from some proxy layers; `full_name` (`catalog.schema.table`) is also
 *      handled as a defensive fallback.
 *
 * Items that yield no usable name are skipped silently. Keeping the
 * normalisation here (rather than in the hook or the JSX) means the picker
 * doesn't have to know about backend shape drift.
 */
export function normalizeDatabricksTables(raw: unknown): NormalizedDatabricksTable[] {
  if (!Array.isArray(raw)) return [];

  const out: NormalizedDatabricksTable[] = [];
  for (const item of raw) {
    if (typeof item === "string") {
      const trimmed = item.trim();
      if (trimmed) out.push({ name: trimmed });
      continue;
    }
    if (item && typeof item === "object") {
      const obj = item as Record<string, unknown>;
      const candidate =
        (typeof obj.name === "string" && obj.name) ||
        (typeof obj.table_name === "string" && obj.table_name) ||
        (typeof obj.full_name === "string" && obj.full_name.split(".").pop());
      if (candidate) {
        out.push({ ...obj, name: candidate });
      }
    }
  }
  return out;
}

/**
 * Parse the comma-separated `selectedTables` string the form stores into a
 * normalised, de-duplicated list of table names. Empty entries are dropped.
 */
export function parseSelectedTables(csv: string): string[] {
  if (!csv) return [];
  const seen = new Set<string>();
  const result: string[] = [];
  for (const raw of csv.split(",")) {
    const name = raw.trim();
    if (!name || seen.has(name)) continue;
    seen.add(name);
    result.push(name);
  }
  return result;
}

/**
 * Add or remove `name` from the comma-separated `csv` list and return the new
 * comma-separated string. Used by the Tables multi-select picker so the
 * underlying form field stays a plain string (preserving the legacy submit
 * shape and the free-text fallback).
 */
export function toggleSelectedTable(csv: string, name: string): string {
  const list = parseSelectedTables(csv);
  const idx = list.indexOf(name);
  if (idx >= 0) {
    list.splice(idx, 1);
  } else {
    list.push(name);
  }
  return list.join(", ");
}

/**
 * Turn the verbose error messages the Databricks Spark Connect / JDBC drivers
 * tend to surface into something a user can act on. Pure function — safe to
 * import anywhere without dragging React state along.
 */
export function simplifyDatabricksErrorMessage(message: string): string {
  const cleanMessage = message
    .replace(/^Database connection failed:\s*/i, "")
    .replace(/^Databricks Spark Connect connection failed:\s*/i, "")
    .replace(/org\.sparkproject\.connect\.grpc\.StatusRuntimeException:\s*/g, "")
    .trim();

  if (
    cleanMessage.includes("Single-user check failed") ||
    cleanMessage.includes("PERMISSION_DENIED")
  ) {
    if (cleanMessage.includes("single user of this cluster is")) {
      const match = cleanMessage.match(/single user of this cluster is '([^']+)'/);
      if (match) {
        return `Permission denied: This cluster is configured for single-user mode with user '${match[1]}'. Please use matching credentials or select a different cluster.`;
      }
    }
    return "Permission denied: You do not have access to this cluster. Please check your credentials or cluster configuration.";
  }

  if (
    cleanMessage.toLowerCase().includes("connection refused") ||
    cleanMessage.toLowerCase().includes("timed out")
  ) {
    return "Unable to connect to the cluster. Please ensure it is running and accessible.";
  }

  if (
    cleanMessage.toLowerCase().includes("invalid") &&
    cleanMessage.toLowerCase().includes("cluster")
  ) {
    return "Invalid cluster ID or cluster not found.";
  }

  // Return cleaned message (first sentence only to avoid overwhelming user)
  const firstSentence = cleanMessage.split(/[.!?]\s/)[0];
  return firstSentence || message;
}
