import { Folder, Inbox, Users2 } from "lucide-react";
import type { ReactNode } from "react";
import { notificationSubtitle } from "../notifications.utils";
import type { NotificationItem, NotificationType } from "../types";

interface NotificationPanelProps {
  items: NotificationItem[];
  isLoading: boolean;
  onItemClick: (item: NotificationItem) => void;
}

function typeIcon(type: NotificationType): ReactNode {
  const Icon = type === "project_share" ? Folder : Users2;
  return <Icon className="h-4 w-4 text-muted-foreground" />;
}

export function NotificationPanel({ items, isLoading, onItemClick }: NotificationPanelProps) {
  if (isLoading && items.length === 0) {
    return <div className="px-3 py-6 text-center text-sm text-muted-foreground">Loading…</div>;
  }

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center gap-2 px-3 py-8 text-center">
        <Inbox className="h-5 w-5 text-muted-foreground" />
        <p className="text-sm text-muted-foreground">You're all caught up</p>
      </div>
    );
  }

  return (
    <ul className="divide-y divide-border">
      {items.map((item) => (
        <li key={item.id}>
          <button
            type="button"
            onClick={() => onItemClick(item)}
            className="flex w-full items-start gap-3 px-3 py-2.5 text-left transition-colors hover:bg-accent"
          >
            <span className="mt-0.5 shrink-0">{typeIcon(item.type)}</span>
            <span className="min-w-0 flex-1">
              <span className="flex items-center gap-2">
                {!item.read && (
                  <span
                    className="h-2 w-2 shrink-0 rounded-full bg-destructive"
                    aria-label="unread"
                  />
                )}
                <span className="truncate text-sm font-medium text-foreground">{item.title}</span>
              </span>
              <span className="block truncate text-xs text-muted-foreground">
                {notificationSubtitle(item)}
              </span>
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
