import type { DatabricksConfig, DatabricksSessionConfig } from "../types";

const AUTH_MODES = { TOKEN: "token", OAUTH2: "oauth2" } as const;

function isAuthMode(value: string): value is DatabricksConfig["authMode"] {
  return value === AUTH_MODES.TOKEN || value === AUTH_MODES.OAUTH2;
}

function isSessionConfig(value: unknown): value is DatabricksSessionConfig {
  if (typeof value !== "object" || value === null || !("host" in value)) {
    return false;
  }

  const { host } = value;
  return typeof host === "string" && host.length > 0;
}

/**
 * Pull a Databricks config out of a backend response envelope.
 *
 * Null covers both shapes of "nothing to hydrate from": the backend holding no
 * config, and a response that does not look like one.
 */
export function parseSessionResponse(body: unknown): DatabricksSessionConfig | null {
  if (typeof body !== "object" || body === null || !("data" in body)) {
    return null;
  }

  const { data } = body;
  if (typeof data !== "object" || data === null || !("databricks_configs" in data)) {
    return null;
  }

  const stored = data.databricks_configs;
  return isSessionConfig(stored) ? stored : null;
}

/** The auth panel the settings form shows for a given config. */
export type DatabricksAuthView = "pat" | "databricks_login" | "oauth2";

/**
 * Pick the auth panel that matches a config.
 *
 * In 3P mode the default is OAuth2: the client id is autofilled from the
 * embedded app's context and the user supplies a secret for it. Elsewhere a
 * Personal Access Token is the default. An explicit earlier choice — a token
 * from the Databricks login flow, a typed PAT — is respected either way.
 */
export function resolveAuthView(config: DatabricksConfig, is3pMode: boolean): DatabricksAuthView {
  if (is3pMode) {
    if (config.isOAuthToken && config.token) return "databricks_login";
    if (config.authMode === AUTH_MODES.TOKEN && config.token && !config.isAppPrincipalToken) {
      return "pat";
    }
    return "oauth2";
  }

  if (config.authMode === AUTH_MODES.OAUTH2) return "oauth2";
  if (config.isOAuthToken && config.token) return "databricks_login";
  return "pat";
}

/**
 * Fold the backend's copy of the Databricks config into the browser's.
 *
 * The backend holds whichever config was set last — from this page, from the
 * assistant, or over MCP — so it wins on every field it carries. Fields it does
 * not know about, such as the execution toggle, stay as the browser has them.
 */
export function applySessionConfig(
  current: DatabricksConfig,
  session: DatabricksSessionConfig,
): DatabricksConfig {
  const authMode = isAuthMode(session.auth_mode) ? session.auth_mode : current.authMode;
  const isTokenAuth = authMode === AUTH_MODES.TOKEN;
  const token = isTokenAuth ? (session.token ?? current.token) : undefined;
  const clusterId = session.cluster_id ?? current.defaultClusterId;

  // A token that changed hands did not come from this browser's OAuth flow, so
  // the metadata describing that flow no longer describes what is stored.
  const oauthMetadata =
    token === current.token
      ? {}
      : {
          isOAuthToken: undefined,
          oauthRefreshToken: undefined,
          oauthExpiresAt: undefined,
          oauthUserEmail: undefined,
          isAppPrincipalToken: undefined,
        };

  return {
    ...current,
    ...oauthMetadata,
    authMode,
    token,
    // Credentials belong to the mode in force — carrying the other mode's over
    // would leave the form showing a secret that authenticates nothing.
    clientId: isTokenAuth ? undefined : (session.client_id ?? current.clientId),
    clientSecret: isTokenAuth ? undefined : (session.client_secret ?? current.clientSecret),
    workspaceUrl: session.host || current.workspaceUrl,
    defaultClusterId: clusterId,
    // The cached cluster object describes the old cluster once the id moves on.
    defaultCluster: clusterId === current.defaultClusterId ? current.defaultCluster : undefined,
    defaultCatalog: session.catalog ?? current.defaultCatalog,
    defaultSchema: session.schema ?? current.defaultSchema,
    defaultVolume: session.volume ?? current.defaultVolume,
    jarFileName: session.jar_file_name ?? current.jarFileName,
  };
}
