import { Inbox, Plus, RefreshCw, Users2 } from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useState } from "react";
import { GlobalSearchTrigger } from "@/features/global-search/components/GlobalSearchTrigger";
import CreateTeamDialog from "@/features/teams/components/CreateTeamDialog";
import InvitationCard from "@/features/teams/components/InvitationCard";
import TeamCard from "@/features/teams/components/TeamCard";
import TeamSuggestionBanner from "@/features/teams/components/TeamSuggestionBanner";
import { useMyTeams } from "@/features/teams/hooks/useMyTeams";
import { useTeamInvitations } from "@/features/teams/hooks/useTeamInvitations";
import { PageHeader } from "@/shared/components/layout/PageHeader";
import SidePanel from "@/shared/components/layout/SidePanel";
import { Button } from "@/shared/components/ui/button";
import { PrometheuxSpinner } from "@/shared/components/ui/geometric-loaders";
import { useSidebarState } from "@/shared/hooks/ui/useSidebarState";

type TabId = "teams" | "invitations";

// Landing route for the Teams feature. Two tabs mirroring the Projects page:
//   * My Teams — grid of TeamCard + "New team" action
//   * Invitations — grid of InvitationCard, Accept/Decline in-place
// Detail (roster, invite, settings) lives at /teams/:teamId.
const TeamsPage: React.FC = () => {
  const { sidebarVisible, toggleSidebar } = useSidebarState();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [activeTab, setActiveTab] = useState<TabId>("teams");
  const [showCreateDialog, setShowCreateDialog] = useState(false);

  const {
    teams,
    isLoading: isLoadingTeams,
    isFetching: isFetchingTeams,
    refresh: refreshTeams,
  } = useMyTeams();
  const {
    invitations,
    isLoading: isLoadingInvitations,
    isFetching: isFetchingInvitations,
    refresh: refreshInvitations,
    accept,
    decline,
  } = useTeamInvitations();

  const isLoading = isLoadingTeams || isLoadingInvitations;
  const isFetching = isFetchingTeams || isFetchingInvitations;

  // Pick a sensible default tab once both queries have settled: teams first,
  // then invitations if the user has any pending ones with no team yet. Don't
  // yank the user around after this initial pick — they may prefer to sit on
  // Invitations even when a team resolves.
  useEffect(() => {
    if (isLoading) return;
    if (teams.length === 0 && invitations.length > 0) {
      setActiveTab("invitations");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isLoading]);

  const handleRefresh = useCallback((): void => {
    refreshTeams();
    refreshInvitations();
  }, [refreshTeams, refreshInvitations]);

  const headerActions = (
    <>
      <Button
        variant="outline"
        size="icon"
        onClick={handleRefresh}
        disabled={isFetching}
        title="Refresh"
      >
        <RefreshCw className={`h-4 w-4 ${isFetching ? "animate-spin" : ""}`} />
      </Button>
      <Button
        onClick={() => setShowCreateDialog(true)}
        className="gap-2 text-xs font-semibold uppercase tracking-wide"
      >
        <Plus className="h-4 w-4" />
        New team
      </Button>
    </>
  );

  const subtitle = `${teams.length} team${teams.length !== 1 ? "s" : ""}`;

  return (
    <div className="flex h-screen overflow-hidden">
      {sidebarVisible && (
        <SidePanel
          activeTab="teams"
          onTabChange={() => {}}
          visible={sidebarVisible}
          onToggle={toggleSidebar}
          onCollapsedChange={setSidebarCollapsed}
        />
      )}

      <div
        className={`flex flex-1 flex-col overflow-hidden transition-all duration-200 ${sidebarVisible ? (sidebarCollapsed ? "ml-14" : "ml-60") : "ml-0"}`}
      >
        <PageHeader
          title="Teams"
          subtitle={subtitle}
          icon={Users2}
          actions={
            <>
              <GlobalSearchTrigger />
              {headerActions}
            </>
          }
        />

        {/* Onboarding hint (dismissible). Rendered once per user per
            suggestion-signature; hides itself when the suggestion is "none"
            or after the user dismisses. Sits above the tab bar so it's
            page-wide, not tied to a tab. */}
        <TeamSuggestionBanner />

        <div className="flex border-b border-border px-6">
          <TabButton
            active={activeTab === "teams"}
            onClick={() => setActiveTab("teams")}
            label="My Teams"
            count={teams.length}
          />
          <TabButton
            active={activeTab === "invitations"}
            onClick={() => setActiveTab("invitations")}
            label="Invitations"
            count={invitations.length}
          />
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto">
          <div className="px-8 py-6">
            {activeTab === "teams" && (
              <TeamsTabContent
                isLoading={isLoadingTeams}
                teams={teams}
                onCreate={() => setShowCreateDialog(true)}
              />
            )}
            {activeTab === "invitations" && (
              <InvitationsTabContent
                isLoading={isLoadingInvitations}
                invitations={invitations}
                onAccept={accept}
                onDecline={decline}
              />
            )}
          </div>
        </div>
      </div>

      <CreateTeamDialog
        isOpen={showCreateDialog}
        onClose={() => setShowCreateDialog(false)}
        onCreated={() => refreshTeams()}
      />
    </div>
  );
};

interface TabButtonProps {
  active: boolean;
  onClick: () => void;
  label: string;
  count: number;
}

const TabButton: React.FC<TabButtonProps> = ({ active, onClick, label, count }) => (
  <button
    type="button"
    onClick={onClick}
    className={`flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium transition-colors ${
      active
        ? "border-b-2 border-primary text-primary"
        : "text-muted-foreground hover:text-foreground"
    }`}
  >
    {label}
    {count > 0 && (
      <span className="rounded-full bg-secondary px-1.5 py-0.5 text-[10px] font-semibold text-muted-foreground">
        {count}
      </span>
    )}
  </button>
);

interface TeamsTabContentProps {
  isLoading: boolean;
  teams: ReturnType<typeof useMyTeams>["teams"];
  onCreate: () => void;
}

const TeamsTabContent: React.FC<TeamsTabContentProps> = ({ isLoading, teams, onCreate }) => {
  if (isLoading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <PrometheuxSpinner size={36} label="Loading teams..." />
      </div>
    );
  }
  if (teams.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center gap-3 py-16 text-center">
        <div className="flex h-12 w-12 items-center justify-center rounded-full bg-secondary">
          <Users2 className="h-5 w-5 text-muted-foreground" />
        </div>
        <div>
          <p className="text-sm font-medium text-foreground">You aren't in any team yet</p>
          <p className="mt-1 text-xs text-muted-foreground">
            Create one, or wait for an invitation from your colleagues.
          </p>
        </div>
        <Button type="button" size="sm" onClick={onCreate} className="gap-1.5">
          <Plus className="h-4 w-4" />
          New team
        </Button>
      </div>
    );
  }
  return (
    <div className="grid grid-cols-3 gap-4">
      {teams.map((team) => (
        <TeamCard key={team.id} team={team} />
      ))}
    </div>
  );
};

interface InvitationsTabContentProps {
  isLoading: boolean;
  invitations: ReturnType<typeof useTeamInvitations>["invitations"];
  onAccept: (token: string) => Promise<unknown>;
  onDecline: (token: string) => Promise<unknown>;
}

const InvitationsTabContent: React.FC<InvitationsTabContentProps> = ({
  isLoading,
  invitations,
  onAccept,
  onDecline,
}) => {
  if (isLoading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <PrometheuxSpinner size={36} label="Loading invitations..." />
      </div>
    );
  }
  if (invitations.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center gap-3 py-16 text-center">
        <div className="flex h-12 w-12 items-center justify-center rounded-full bg-secondary">
          <Inbox className="h-5 w-5 text-muted-foreground" />
        </div>
        <div>
          <p className="text-sm font-medium text-foreground">No pending invitations</p>
          <p className="mt-1 text-xs text-muted-foreground">
            When someone invites you to a team, it'll show up here.
          </p>
        </div>
      </div>
    );
  }
  return (
    <div className="grid grid-cols-3 gap-4">
      {invitations.map((invitation) => (
        <InvitationCard
          key={invitation.id}
          invitation={invitation}
          onAccept={onAccept}
          onDecline={onDecline}
        />
      ))}
    </div>
  );
};

export default TeamsPage;
