import { LottiePlayer } from "@/shared/components/LottiePlayer";

interface LoginIntroOverlayProps {
  visible: boolean;
  fading: boolean;
  fadeDurationMs: number;
}

// Full-screen hero animation shown on first load, fading out into the login page.
export const LoginIntroOverlay = ({ visible, fading, fadeDurationMs }: LoginIntroOverlayProps) => {
  if (!visible) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex flex-col items-center justify-center"
      style={{
        background: "#f2f2f2",
        opacity: fading ? 0 : 1,
        transition: `opacity ${fadeDurationMs}ms ease-in-out`,
        pointerEvents: fading ? "none" : "all",
      }}
    >
      <LottiePlayer
        src="/hero-animation.json"
        style={{ width: "560px", maxWidth: "90vw", height: "560px", maxHeight: "70vw" }}
        autoplay
      />
    </div>
  );
};
