import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/AuthProvider";
import { getTeamSuggestion } from "../api";
import type { Suggestion, TeamError } from "../types";

export const TEAM_SUGGESTION_KEY = ["teams", "suggestion"] as const;
const suggestionKey = (userId: string) => [...TEAM_SUGGESTION_KEY, userId] as const;

interface UseTeamSuggestionReturn {
  suggestion: Suggestion | null;
  isLoading: boolean;
  error: TeamError | null;
  refresh: () => Promise<unknown>;
}

// Read-only endpoint. Recompute on any mutation that could change the caller's
// team membership (create, leave, accept invite) — those hooks invalidate
// TEAM_SUGGESTION_KEY, so this stays honest without polling.
export function useTeamSuggestion(): UseTeamSuggestionReturn {
  const { user, session } = useAuth();
  const supabaseToken = session?.access_token ?? null;
  const userId = user?.id ?? "";

  const query = useQuery<Suggestion, TeamError>({
    queryKey: suggestionKey(userId),
    queryFn: () => getTeamSuggestion(supabaseToken),
    enabled: Boolean(userId && supabaseToken),
    staleTime: 0,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  return {
    suggestion: query.data ?? null,
    isLoading: query.isLoading,
    error: query.error,
    refresh: query.refetch,
  };
}
